    (8, 'tanzil-uthmani-v1.1', 2, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'e190dd3d3d044e6256ebd129866c8631838018200128280a20f27d07491b7e45', 'الٓمٓ', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الم', 1, 1, 1, 1, 1, 2, false, NULL),
    (9, 'tanzil-uthmani-v1.1', 2, 2, 'ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ', '4997d75a72e6d5096caf1108c77bae3712a5aa6a428587e14bd7c59d1df474e1', 'ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ', '4997d75a72e6d5096caf1108c77bae3712a5aa6a428587e14bd7c59d1df474e1', '4997d75a72e6d5096caf1108c77bae3712a5aa6a428587e14bd7c59d1df474e1', NULL, 'ذلك الكتب لا ريب فيه هدي للمتقين', 1, 1, 1, 1, 1, 2, false, NULL),
    (10, 'tanzil-uthmani-v1.1', 2, 3, 'ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'aef1994a31784ca13a984836fbecbe761618f8307f13336afc68c2764df758a2', 'ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'aef1994a31784ca13a984836fbecbe761618f8307f13336afc68c2764df758a2', 'aef1994a31784ca13a984836fbecbe761618f8307f13336afc68c2764df758a2', NULL, 'الذين يؤمنون بالغيب ويقيمون الصلوه ومما رزقنهم ينفقون', 1, 1, 1, 1, 1, 2, false, NULL),
    (11, 'tanzil-uthmani-v1.1', 2, 4, 'وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', 'c7f1f857a1ff3a3e0c0418e780b04dd8b5116a09fe2604ee4659f128bcba0b0a', 'وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', 'c7f1f857a1ff3a3e0c0418e780b04dd8b5116a09fe2604ee4659f128bcba0b0a', 'c7f1f857a1ff3a3e0c0418e780b04dd8b5116a09fe2604ee4659f128bcba0b0a', NULL, 'والذين يؤمنون بما انزل اليك وما انزل من قبلك وبالاخره هم يوقنون', 1, 1, 1, 1, 1, 2, false, NULL),
    (12, 'tanzil-uthmani-v1.1', 2, 5, 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '6390ed1e5b1434ecb1ff54ec6cf1802c8b4466045513aad48c6798deafda6c8d', 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '6390ed1e5b1434ecb1ff54ec6cf1802c8b4466045513aad48c6798deafda6c8d', '6390ed1e5b1434ecb1ff54ec6cf1802c8b4466045513aad48c6798deafda6c8d', NULL, 'اولئك علي هدي من ربهم واولئك هم المفلحون', 1, 1, 1, 1, 1, 2, false, NULL),
    (13, 'tanzil-uthmani-v1.1', 2, 6, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', '500f5429551b57588828407f9b1614d35ecee7befea9c1507151ea02eafdb15b', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', '500f5429551b57588828407f9b1614d35ecee7befea9c1507151ea02eafdb15b', '500f5429551b57588828407f9b1614d35ecee7befea9c1507151ea02eafdb15b', NULL, 'ان الذين كفروا سواء عليهم ءانذرتهم ام لم تنذرهم لا يؤمنون', 1, 1, 1, 1, 1, 3, false, NULL),
    (14, 'tanzil-uthmani-v1.1', 2, 7, 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ وَعَلَىٰٓ أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ', '49d4bb34aaa928396a7332ab40ad32d95fb1637401e813077654af0968504ba7', 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ وَعَلَىٰٓ أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ', '49d4bb34aaa928396a7332ab40ad32d95fb1637401e813077654af0968504ba7', '49d4bb34aaa928396a7332ab40ad32d95fb1637401e813077654af0968504ba7', NULL, 'ختم الله علي قلوبهم وعلي سمعهم وعلي ابصرهم غشوه ولهم عذاب عظيم', 1, 1, 1, 1, 1, 3, false, NULL),
    (15, 'tanzil-uthmani-v1.1', 2, 8, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ', 'e60780e25fad81601d86ed6faf64d5a47d6af8beb9d0286b2414792eb5d20f8e', 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ', 'e60780e25fad81601d86ed6faf64d5a47d6af8beb9d0286b2414792eb5d20f8e', 'e60780e25fad81601d86ed6faf64d5a47d6af8beb9d0286b2414792eb5d20f8e', NULL, 'ومن الناس من يقول ءامنا بالله وباليوم الاخر وما هم بمؤمنين', 1, 1, 1, 1, 1, 3, false, NULL),
    (16, 'tanzil-uthmani-v1.1', 2, 9, 'يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'bdb2060ff858512ab51437559ae8e19b5c671417bad5607a05317e78298b71f1', 'يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'bdb2060ff858512ab51437559ae8e19b5c671417bad5607a05317e78298b71f1', 'bdb2060ff858512ab51437559ae8e19b5c671417bad5607a05317e78298b71f1', NULL, 'يخدعون الله والذين ءامنوا وما يخدعون الا انفسهم وما يشعرون', 1, 1, 1, 1, 1, 3, false, NULL),
    (17, 'tanzil-uthmani-v1.1', 2, 10, 'فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ', 'd57ad6c5f002c32927ec39c72b1916939f15097a0ddc813d3e24b7c208b64770', 'فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ', 'd57ad6c5f002c32927ec39c72b1916939f15097a0ddc813d3e24b7c208b64770', 'd57ad6c5f002c32927ec39c72b1916939f15097a0ddc813d3e24b7c208b64770', NULL, 'في قلوبهم مرض فزادهم الله مرضا ولهم عذاب اليم بما كانوا يكذبون', 1, 1, 1, 1, 1, 3, false, NULL),
    (18, 'tanzil-uthmani-v1.1', 2, 11, 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ', '3e920ddb02227c4c057b0d5caa662c31d9b0f2e98265c7e258330dd2a556b4ba', 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ', '3e920ddb02227c4c057b0d5caa662c31d9b0f2e98265c7e258330dd2a556b4ba', '3e920ddb02227c4c057b0d5caa662c31d9b0f2e98265c7e258330dd2a556b4ba', NULL, 'واذا قيل لهم لا تفسدوا في الارض قالوا انما نحن مصلحون', 1, 1, 1, 1, 1, 3, false, NULL),
    (19, 'tanzil-uthmani-v1.1', 2, 12, 'أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ', 'ccc04ffe7920e739ccd8652f692ae51045dc97e18844b3671db4d01fac6655d3', 'أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ', 'ccc04ffe7920e739ccd8652f692ae51045dc97e18844b3671db4d01fac6655d3', 'ccc04ffe7920e739ccd8652f692ae51045dc97e18844b3671db4d01fac6655d3', NULL, 'الا انهم هم المفسدون ولكن لا يشعرون', 1, 1, 1, 1, 1, 3, false, NULL),
    (20, 'tanzil-uthmani-v1.1', 2, 13, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ', '291e327a455dcb8f78c0e90945b8c4de0f850b5659d45e513f8542aa12a318fe', 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ', '291e327a455dcb8f78c0e90945b8c4de0f850b5659d45e513f8542aa12a318fe', '291e327a455dcb8f78c0e90945b8c4de0f850b5659d45e513f8542aa12a318fe', NULL, 'واذا قيل لهم ءامنوا كما ءامن الناس قالوا انؤمن كما ءامن السفهاء الا انهم هم السفهاء ولكن لا يعلمون', 1, 1, 1, 1, 1, 3, false, NULL),
    (21, 'tanzil-uthmani-v1.1', 2, 14, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ', '98b647ff5b4fbec2417ff5c1e6ae058f2d6e15c27cc6c71a4d596059b00e8299', 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ', '98b647ff5b4fbec2417ff5c1e6ae058f2d6e15c27cc6c71a4d596059b00e8299', '98b647ff5b4fbec2417ff5c1e6ae058f2d6e15c27cc6c71a4d596059b00e8299', NULL, 'واذا لقوا الذين ءامنوا قالوا ءامنا واذا خلوا الي شيطينهم قالوا انا معكم انما نحن مستهزءون', 1, 1, 1, 1, 1, 3, false, NULL),
    (22, 'tanzil-uthmani-v1.1', 2, 15, 'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'd507a600b18f45917acf2b0aaf0a6665cd592791942d5239f094a8b5c6d43bdc', 'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'd507a600b18f45917acf2b0aaf0a6665cd592791942d5239f094a8b5c6d43bdc', 'd507a600b18f45917acf2b0aaf0a6665cd592791942d5239f094a8b5c6d43bdc', NULL, 'الله يستهزئ بهم ويمدهم في طغينهم يعمهون', 1, 1, 1, 1, 1, 3, false, NULL),
    (23, 'tanzil-uthmani-v1.1', 2, 16, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ', '7b94889d7da986c7b9a844e62fe154e25edb50560f3266d801bb91f3f9520fdd', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ', '7b94889d7da986c7b9a844e62fe154e25edb50560f3266d801bb91f3f9520fdd', '7b94889d7da986c7b9a844e62fe154e25edb50560f3266d801bb91f3f9520fdd', NULL, 'اولئك الذين اشتروا الضلله بالهدي فما ربحت تجرتهم وما كانوا مهتدين', 1, 1, 1, 1, 1, 3, false, NULL),
    (24, 'tanzil-uthmani-v1.1', 2, 17, 'مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَٰتٍ لَّا يُبْصِرُونَ', 'b820ea41afe52b605343059cf93d5d4660fb82864c93a749962f59f2e9674988', 'مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَٰتٍ لَّا يُبْصِرُونَ', 'b820ea41afe52b605343059cf93d5d4660fb82864c93a749962f59f2e9674988', 'b820ea41afe52b605343059cf93d5d4660fb82864c93a749962f59f2e9674988', NULL, 'مثلهم كمثل الذي استوقد نارا فلما اضاءت ما حوله ذهب الله بنورهم وتركهم في ظلمت لا يبصرون', 1, 1, 1, 1, 1, 4, false, NULL),
    (25, 'tanzil-uthmani-v1.1', 2, 18, 'صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَرْجِعُونَ', 'b5de25030cca451183d30c724f70bc9fa8185c3be1ad91ddc1408572189c7709', 'صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَرْجِعُونَ', 'b5de25030cca451183d30c724f70bc9fa8185c3be1ad91ddc1408572189c7709', 'b5de25030cca451183d30c724f70bc9fa8185c3be1ad91ddc1408572189c7709', NULL, 'صم بكم عمي فهم لا يرجعون', 1, 1, 1, 1, 1, 4, false, NULL),
    (26, 'tanzil-uthmani-v1.1', 2, 19, 'أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَٰفِرِينَ', '3c9737b1c138888d78f0ac7b1069d3bcecd17a564ead3a86535b07c352b82188', 'أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَٰفِرِينَ', '3c9737b1c138888d78f0ac7b1069d3bcecd17a564ead3a86535b07c352b82188', '3c9737b1c138888d78f0ac7b1069d3bcecd17a564ead3a86535b07c352b82188', NULL, 'او كصيب من السماء فيه ظلمت ورعد وبرق يجعلون اصبعهم في ءاذانهم من الصوعق حذر الموت والله محيط بالكفرين', 1, 1, 1, 1, 1, 4, false, NULL),
    (27, 'tanzil-uthmani-v1.1', 2, 20, 'يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَٰرَهُمْ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَٰرِهِمْ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '813421a2f6d28de002a05741830543264fc62346bdcffa08b21989f9eae6d31d', 'يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَٰرَهُمْ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَٰرِهِمْ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '813421a2f6d28de002a05741830543264fc62346bdcffa08b21989f9eae6d31d', '813421a2f6d28de002a05741830543264fc62346bdcffa08b21989f9eae6d31d', NULL, 'يكاد البرق يخطف ابصرهم كلما اضاء لهم مشوا فيه واذا اظلم عليهم قاموا ولو شاء الله لذهب بسمعهم وابصرهم ان الله علي كل شيء قدير', 1, 1, 1, 1, 1, 4, false, NULL),
    (28, 'tanzil-uthmani-v1.1', 2, 21, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'ce16b924decba40c113455a247dd15a5bf1b51b577d9bf74d4ab68f4c206c055', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'ce16b924decba40c113455a247dd15a5bf1b51b577d9bf74d4ab68f4c206c055', 'ce16b924decba40c113455a247dd15a5bf1b51b577d9bf74d4ab68f4c206c055', NULL, 'يايها الناس اعبدوا ربكم الذي خلقكم والذين من قبلكم لعلكم تتقون', 1, 1, 1, 1, 1, 4, false, NULL),
    (29, 'tanzil-uthmani-v1.1', 2, 22, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ', 'b5926d3201e3c9b624f4a899d9049f8bc95036232931aee6f8c44b637c0ced2c', 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ', 'b5926d3201e3c9b624f4a899d9049f8bc95036232931aee6f8c44b637c0ced2c', 'b5926d3201e3c9b624f4a899d9049f8bc95036232931aee6f8c44b637c0ced2c', NULL, 'الذي جعل لكم الارض فرشا والسماء بناء وانزل من السماء ماء فاخرج به من الثمرت رزقا لكم فلا تجعلوا لله اندادا وانتم تعلمون', 1, 1, 1, 1, 1, 4, false, NULL),
    (30, 'tanzil-uthmani-v1.1', 2, 23, 'وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', '7322ad35a6e00c22370eac3cbee89ecf7a54dc8285e0e0b4ad47ed303eeda76a', 'وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', '7322ad35a6e00c22370eac3cbee89ecf7a54dc8285e0e0b4ad47ed303eeda76a', '7322ad35a6e00c22370eac3cbee89ecf7a54dc8285e0e0b4ad47ed303eeda76a', NULL, 'وان كنتم في ريب مما نزلنا علي عبدنا فاتوا بسوره من مثله وادعوا شهداءكم من دون الله ان كنتم صدقين', 1, 1, 1, 1, 1, 4, false, NULL),
    (31, 'tanzil-uthmani-v1.1', 2, 24, 'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ أُعِدَّتْ لِلْكَٰفِرِينَ', 'ba82cce18bb6e085d2af558b20f9de89b36f0011d59b46606fc985ea03ef790b', 'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ أُعِدَّتْ لِلْكَٰفِرِينَ', 'ba82cce18bb6e085d2af558b20f9de89b36f0011d59b46606fc985ea03ef790b', 'ba82cce18bb6e085d2af558b20f9de89b36f0011d59b46606fc985ea03ef790b', NULL, 'فان لم تفعلوا ولن تفعلوا فاتقوا النار التي وقودها الناس والحجاره اعدت للكفرين', 1, 1, 1, 1, 1, 4, false, NULL),
    (32, 'tanzil-uthmani-v1.1', 2, 25, 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا قَالُوا۟ هَٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ وَأُتُوا۟ بِهِۦ مُتَشَٰبِهًا وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ وَهُمْ فِيهَا خَٰلِدُونَ', '2a6bfa1da97f3aa6b7da224300339ccfe36f3144a4d8c201cbe2c2eec9d4be42', 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا قَالُوا۟ هَٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ وَأُتُوا۟ بِهِۦ مُتَشَٰبِهًا وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ وَهُمْ فِيهَا خَٰلِدُونَ', '2a6bfa1da97f3aa6b7da224300339ccfe36f3144a4d8c201cbe2c2eec9d4be42', '2a6bfa1da97f3aa6b7da224300339ccfe36f3144a4d8c201cbe2c2eec9d4be42', NULL, 'وبشر الذين ءامنوا وعملوا الصلحت ان لهم جنت تجري من تحتها الانهر كلما رزقوا منها من ثمره رزقا قالوا هذا الذي رزقنا من قبل واتوا به متشبها ولهم فيها ازوج مطهره وهم فيها خلدون', 1, 1, 1, 1, 1, 5, false, NULL),
    (33, 'tanzil-uthmani-v1.1', 2, 26, 'إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَٰسِقِينَ', 'f00fb61dbe6ce5edd6cd7f2a83ab40c4379a9a0b2a8f9dc0784031a66b4ccf0c', 'إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَٰسِقِينَ', 'f00fb61dbe6ce5edd6cd7f2a83ab40c4379a9a0b2a8f9dc0784031a66b4ccf0c', 'f00fb61dbe6ce5edd6cd7f2a83ab40c4379a9a0b2a8f9dc0784031a66b4ccf0c', NULL, 'ان الله لا يستحي ان يضرب مثلا ما بعوضه فما فوقها فاما الذين ءامنوا فيعلمون انه الحق من ربهم واما الذين كفروا فيقولون ماذا اراد الله بهذا مثلا يضل به كثيرا ويهدي به كثيرا وما يضل به الا الفسقين', 1, 1, 2, 1, 1, 5, false, NULL),
    (34, 'tanzil-uthmani-v1.1', 2, 27, 'ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '660aefbb0bcdc3534c9c995e2c8f32d12412290c3a587037d3869abb646ebb74', 'ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '660aefbb0bcdc3534c9c995e2c8f32d12412290c3a587037d3869abb646ebb74', '660aefbb0bcdc3534c9c995e2c8f32d12412290c3a587037d3869abb646ebb74', NULL, 'الذين ينقضون عهد الله من بعد ميثقه ويقطعون ما امر الله به ان يوصل ويفسدون في الارض اولئك هم الخسرون', 1, 1, 2, 1, 1, 5, false, NULL),
    (35, 'tanzil-uthmani-v1.1', 2, 28, 'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَٰكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'faa32392466f3af370cfec3788aa0d1d88a30b4d29ae399598cf2e6f37a773e3', 'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَٰكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 'faa32392466f3af370cfec3788aa0d1d88a30b4d29ae399598cf2e6f37a773e3', 'faa32392466f3af370cfec3788aa0d1d88a30b4d29ae399598cf2e6f37a773e3', NULL, 'كيف تكفرون بالله وكنتم اموتا فاحيكم ثم يميتكم ثم يحييكم ثم اليه ترجعون', 1, 1, 2, 1, 1, 5, false, NULL),
    (36, 'tanzil-uthmani-v1.1', 2, 29, 'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَٰوَٰتٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'd1574c59051be5f8bb97d885594753bcd1524e75f065a4dd4dcbf9e5861637d9', 'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَٰوَٰتٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'd1574c59051be5f8bb97d885594753bcd1524e75f065a4dd4dcbf9e5861637d9', 'd1574c59051be5f8bb97d885594753bcd1524e75f065a4dd4dcbf9e5861637d9', NULL, 'هو الذي خلق لكم ما في الارض جميعا ثم استوي الي السماء فسويهن سبع سموت وهو بكل شيء عليم', 1, 1, 2, 1, 1, 5, false, NULL),
    (37, 'tanzil-uthmani-v1.1', 2, 30, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', '1ac44b4951dc3bcd76b0766cfbd89e9f10118453589517a76038b13410005fb5', 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', '1ac44b4951dc3bcd76b0766cfbd89e9f10118453589517a76038b13410005fb5', '1ac44b4951dc3bcd76b0766cfbd89e9f10118453589517a76038b13410005fb5', NULL, 'واذ قال ربك للملئكه اني جاعل في الارض خليفه قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون', 1, 1, 2, 1, 1, 6, false, NULL),
    (38, 'tanzil-uthmani-v1.1', 2, 31, 'وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ', '1db1c4f0017c4a49b3d758df89136e6f25fa8c6c161d677a1fd04bda569b14d6', 'وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ', '1db1c4f0017c4a49b3d758df89136e6f25fa8c6c161d677a1fd04bda569b14d6', '1db1c4f0017c4a49b3d758df89136e6f25fa8c6c161d677a1fd04bda569b14d6', NULL, 'وعلم ءادم الاسماء كلها ثم عرضهم علي الملئكه فقال انبوني باسماء هؤلاء ان كنتم صدقين', 1, 1, 2, 1, 1, 6, false, NULL),
    (39, 'tanzil-uthmani-v1.1', 2, 32, 'قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'f917f12a2eeb676b3eab86b337e1417855e149dea02734134bbb648f8de2dabd', 'قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 'f917f12a2eeb676b3eab86b337e1417855e149dea02734134bbb648f8de2dabd', 'f917f12a2eeb676b3eab86b337e1417855e149dea02734134bbb648f8de2dabd', NULL, 'قالوا سبحنك لا علم لنا الا ما علمتنا انك انت العليم الحكيم', 1, 1, 2, 1, 1, 6, false, NULL),
    (40, 'tanzil-uthmani-v1.1', 2, 33, 'قَالَ يَٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ', 'd70deacbb93f7acf51be7402e6e9e6e08ab3f6b4046dc150de79ee538f3d3113', 'قَالَ يَٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ', 'd70deacbb93f7acf51be7402e6e9e6e08ab3f6b4046dc150de79ee538f3d3113', 'd70deacbb93f7acf51be7402e6e9e6e08ab3f6b4046dc150de79ee538f3d3113', NULL, 'قال يادم انبئهم باسمائهم فلما انباهم باسمائهم قال الم اقل لكم اني اعلم غيب السموت والارض واعلم ما تبدون وما كنتم تكتمون', 1, 1, 2, 1, 1, 6, false, NULL),
    (41, 'tanzil-uthmani-v1.1', 2, 34, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', '29a8efd3f703c9703f13d8f24e6baf2b76a875761d78dd26973d24a9ae9f77e2', 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', '29a8efd3f703c9703f13d8f24e6baf2b76a875761d78dd26973d24a9ae9f77e2', '29a8efd3f703c9703f13d8f24e6baf2b76a875761d78dd26973d24a9ae9f77e2', NULL, 'واذ قلنا للملئكه اسجدوا لادم فسجدوا الا ابليس ابي واستكبر وكان من الكفرين', 1, 1, 2, 1, 1, 6, false, NULL),
    (42, 'tanzil-uthmani-v1.1', 2, 35, 'وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', '4236a11dbbf8754ef61c64a7375e3f46f8d4433a4909bccf893c1d5310144b11', 'وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', '4236a11dbbf8754ef61c64a7375e3f46f8d4433a4909bccf893c1d5310144b11', '4236a11dbbf8754ef61c64a7375e3f46f8d4433a4909bccf893c1d5310144b11', NULL, 'وقلنا يادم اسكن انت وزوجك الجنه وكلا منها رغدا حيث شئتما ولا تقربا هذه الشجره فتكونا من الظلمين', 1, 1, 2, 1, 1, 6, false, NULL),
    (43, 'tanzil-uthmani-v1.1', 2, 36, 'فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'e548573ac12ad070239f5f50c28bf274caa664897862967e01c3f1f3c57d998a', 'فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'e548573ac12ad070239f5f50c28bf274caa664897862967e01c3f1f3c57d998a', 'e548573ac12ad070239f5f50c28bf274caa664897862967e01c3f1f3c57d998a', NULL, 'فازلهما الشيطن عنها فاخرجهما مما كانا فيه وقلنا اهبطوا بعضكم لبعض عدو ولكم في الارض مستقر ومتع الي حين', 1, 1, 2, 1, 1, 6, false, NULL),
    (44, 'tanzil-uthmani-v1.1', 2, 37, 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٍ فَتَابَ عَلَيْهِ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '29fda9f73105f529194d8b0525ae439910276aca6b9ebba49ef9c1a91b80790c', 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٍ فَتَابَ عَلَيْهِ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '29fda9f73105f529194d8b0525ae439910276aca6b9ebba49ef9c1a91b80790c', '29fda9f73105f529194d8b0525ae439910276aca6b9ebba49ef9c1a91b80790c', NULL, 'فتلقي ءادم من ربه كلمت فتاب عليه انه هو التواب الرحيم', 1, 1, 2, 1, 1, 6, false, NULL),
    (45, 'tanzil-uthmani-v1.1', 2, 38, 'قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '9c282b504b37f0612bed21b971a012e26cb9fc4fae3883a886472916f41ea6f9', 'قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '9c282b504b37f0612bed21b971a012e26cb9fc4fae3883a886472916f41ea6f9', '9c282b504b37f0612bed21b971a012e26cb9fc4fae3883a886472916f41ea6f9', NULL, 'قلنا اهبطوا منها جميعا فاما ياتينكم مني هدي فمن تبع هداي فلا خوف عليهم ولا هم يحزنون', 1, 1, 2, 1, 1, 7, false, NULL),
    (46, 'tanzil-uthmani-v1.1', 2, 39, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '891129bad87871d033797d60d9fb86f0b07696d92e0d47af816b9ad05cd5b745', 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '891129bad87871d033797d60d9fb86f0b07696d92e0d47af816b9ad05cd5b745', '891129bad87871d033797d60d9fb86f0b07696d92e0d47af816b9ad05cd5b745', NULL, 'والذين كفروا وكذبوا بايتنا اولئك اصحب النار هم فيها خلدون', 1, 1, 2, 1, 1, 7, false, NULL),
    (47, 'tanzil-uthmani-v1.1', 2, 40, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰىَ فَٱرْهَبُونِ', '14dce83896b812a2316a1701c044e0e88e0c1135fe76afbdcf9eb8499d5aca0f', 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰىَ فَٱرْهَبُونِ', '14dce83896b812a2316a1701c044e0e88e0c1135fe76afbdcf9eb8499d5aca0f', '14dce83896b812a2316a1701c044e0e88e0c1135fe76afbdcf9eb8499d5aca0f', NULL, 'يبني اسرءيل اذكروا نعمتي التي انعمت عليكم واوفوا بعهدي اوف بعهدكم وايي فارهبون', 1, 1, 2, 1, 1, 7, false, NULL),
    (48, 'tanzil-uthmani-v1.1', 2, 41, 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَإِيَّٰىَ فَٱتَّقُونِ', 'b8905c1559829f79310059cd21c638e925c3cfee223420a9dc6a4c3d0dc70736', 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَإِيَّٰىَ فَٱتَّقُونِ', 'b8905c1559829f79310059cd21c638e925c3cfee223420a9dc6a4c3d0dc70736', 'b8905c1559829f79310059cd21c638e925c3cfee223420a9dc6a4c3d0dc70736', NULL, 'وءامنوا بما انزلت مصدقا لما معكم ولا تكونوا اول كافر به ولا تشتروا بايتي ثمنا قليلا وايي فاتقون', 1, 1, 2, 1, 1, 7, false, NULL),
    (49, 'tanzil-uthmani-v1.1', 2, 42, 'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', '820d71d67f156b7376519719f4144ceb25505bc378e66721a94fc12fe671395c', 'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', '820d71d67f156b7376519719f4144ceb25505bc378e66721a94fc12fe671395c', '820d71d67f156b7376519719f4144ceb25505bc378e66721a94fc12fe671395c', NULL, 'ولا تلبسوا الحق بالبطل وتكتموا الحق وانتم تعلمون', 1, 1, 2, 1, 1, 7, false, NULL),
    (50, 'tanzil-uthmani-v1.1', 2, 43, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ', 'fdc95670a2f3284162b189efc668692b824042929d2efaaa6e9fa9501fa4755e', 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ', 'fdc95670a2f3284162b189efc668692b824042929d2efaaa6e9fa9501fa4755e', 'fdc95670a2f3284162b189efc668692b824042929d2efaaa6e9fa9501fa4755e', NULL, 'واقيموا الصلوه وءاتوا الزكوه واركعوا مع الركعين', 1, 1, 2, 1, 1, 7, false, NULL),
    (51, 'tanzil-uthmani-v1.1', 2, 44, 'أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ أَفَلَا تَعْقِلُونَ', '86eee0d13d19f16598240ab31e1a053acead66790871a7f43c0948f667822f28', 'أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ أَفَلَا تَعْقِلُونَ', '86eee0d13d19f16598240ab31e1a053acead66790871a7f43c0948f667822f28', '86eee0d13d19f16598240ab31e1a053acead66790871a7f43c0948f667822f28', NULL, 'اتامرون الناس بالبر وتنسون انفسكم وانتم تتلون الكتب افلا تعقلون', 1, 1, 3, 1, 1, 7, false, NULL),
    (52, 'tanzil-uthmani-v1.1', 2, 45, 'وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَٰشِعِينَ', '7dc641ce0cbdf68f7972048423ef53610be88fde994b5d36eff35a6ca2605d06', 'وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَٰشِعِينَ', '7dc641ce0cbdf68f7972048423ef53610be88fde994b5d36eff35a6ca2605d06', '7dc641ce0cbdf68f7972048423ef53610be88fde994b5d36eff35a6ca2605d06', NULL, 'واستعينوا بالصبر والصلوه وانها لكبيره الا علي الخشعين', 1, 1, 3, 1, 1, 7, false, NULL),
    (53, 'tanzil-uthmani-v1.1', 2, 46, 'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ', '9defe3c5a377f9d70d02844d73edfc7321499942f7c44607ac778c2db101e3c5', 'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ', '9defe3c5a377f9d70d02844d73edfc7321499942f7c44607ac778c2db101e3c5', '9defe3c5a377f9d70d02844d73edfc7321499942f7c44607ac778c2db101e3c5', NULL, 'الذين يظنون انهم ملقوا ربهم وانهم اليه رجعون', 1, 1, 3, 1, 1, 7, false, NULL),
    (54, 'tanzil-uthmani-v1.1', 2, 47, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', '985c1473e1dc1c23056354b159a347ab7faffcaf8ca6ebe028428faa68d24475', 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', '985c1473e1dc1c23056354b159a347ab7faffcaf8ca6ebe028428faa68d24475', '985c1473e1dc1c23056354b159a347ab7faffcaf8ca6ebe028428faa68d24475', NULL, 'يبني اسرءيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين', 1, 1, 3, 1, 1, 7, false, NULL),
    (55, 'tanzil-uthmani-v1.1', 2, 48, 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ', '6f33348882da795bbccc69aaaddfa3cc892a78d213c93e1b6ded2871ca91f0b2', 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ', '6f33348882da795bbccc69aaaddfa3cc892a78d213c93e1b6ded2871ca91f0b2', '6f33348882da795bbccc69aaaddfa3cc892a78d213c93e1b6ded2871ca91f0b2', NULL, 'واتقوا يوما لا تجزي نفس عن نفس شيا ولا يقبل منها شفعه ولا يؤخذ منها عدل ولا هم ينصرون', 1, 1, 3, 1, 1, 7, false, NULL),
    (56, 'tanzil-uthmani-v1.1', 2, 49, 'وَإِذْ نَجَّيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'ef92dd9105dfe09a000701d9c857e82424ca43ab2dfc7fa0247d7d05571ce52d', 'وَإِذْ نَجَّيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'ef92dd9105dfe09a000701d9c857e82424ca43ab2dfc7fa0247d7d05571ce52d', 'ef92dd9105dfe09a000701d9c857e82424ca43ab2dfc7fa0247d7d05571ce52d', NULL, 'واذ نجينكم من ءال فرعون يسومونكم سوء العذاب يذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم', 1, 1, 3, 1, 1, 8, false, NULL),
    (57, 'tanzil-uthmani-v1.1', 2, 50, 'وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ', '7e1b8eaa4aac24d6906e404ab67b21b59beb68605ec7b87dcdfb50922426f7d5', 'وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ', '7e1b8eaa4aac24d6906e404ab67b21b59beb68605ec7b87dcdfb50922426f7d5', '7e1b8eaa4aac24d6906e404ab67b21b59beb68605ec7b87dcdfb50922426f7d5', NULL, 'واذ فرقنا بكم البحر فانجينكم واغرقنا ءال فرعون وانتم تنظرون', 1, 1, 3, 1, 1, 8, false, NULL),
    (58, 'tanzil-uthmani-v1.1', 2, 51, 'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', '4bf042a432e572dc5485b6a2c2d12cd48cd4d4d9142654c58794729231e75154', 'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', '4bf042a432e572dc5485b6a2c2d12cd48cd4d4d9142654c58794729231e75154', '4bf042a432e572dc5485b6a2c2d12cd48cd4d4d9142654c58794729231e75154', NULL, 'واذ وعدنا موسي اربعين ليله ثم اتخذتم العجل من بعده وانتم ظلمون', 1, 1, 3, 1, 1, 8, false, NULL),
    (59, 'tanzil-uthmani-v1.1', 2, 52, 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', 'ff02f12880085f7ea94a7a936cffae403c491a23f470b18218129f19c98e844e', 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', 'ff02f12880085f7ea94a7a936cffae403c491a23f470b18218129f19c98e844e', 'ff02f12880085f7ea94a7a936cffae403c491a23f470b18218129f19c98e844e', NULL, 'ثم عفونا عنكم من بعد ذلك لعلكم تشكرون', 1, 1, 3, 1, 1, 8, false, NULL),
    (60, 'tanzil-uthmani-v1.1', 2, 53, 'وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', '0b2bc68b7aa727134d98665fb4927faaf7755d4c269819dcb19f6cc263fa7f6e', 'وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', '0b2bc68b7aa727134d98665fb4927faaf7755d4c269819dcb19f6cc263fa7f6e', '0b2bc68b7aa727134d98665fb4927faaf7755d4c269819dcb19f6cc263fa7f6e', NULL, 'واذ ءاتينا موسي الكتب والفرقان لعلكم تهتدون', 1, 1, 3, 1, 1, 8, false, NULL),
    (61, 'tanzil-uthmani-v1.1', 2, 54, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'd1abacb1392377fb848ee7fdb37eb052a6907c492741b139be3d74ae1e174ab6', 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 'd1abacb1392377fb848ee7fdb37eb052a6907c492741b139be3d74ae1e174ab6', 'd1abacb1392377fb848ee7fdb37eb052a6907c492741b139be3d74ae1e174ab6', NULL, 'واذ قال موسي لقومه يقوم انكم ظلمتم انفسكم باتخاذكم العجل فتوبوا الي بارئكم فاقتلوا انفسكم ذلكم خير لكم عند بارئكم فتاب عليكم انه هو التواب الرحيم', 1, 1, 3, 1, 1, 8, false, NULL),
    (62, 'tanzil-uthmani-v1.1', 2, 55, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةً فَأَخَذَتْكُمُ ٱلصَّٰعِقَةُ وَأَنتُمْ تَنظُرُونَ', '0aeb7e3f585dde2711a1845ad65af3b09be0e75e4704eff28abd5fac487310fd', 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةً فَأَخَذَتْكُمُ ٱلصَّٰعِقَةُ وَأَنتُمْ تَنظُرُونَ', '0aeb7e3f585dde2711a1845ad65af3b09be0e75e4704eff28abd5fac487310fd', '0aeb7e3f585dde2711a1845ad65af3b09be0e75e4704eff28abd5fac487310fd', NULL, 'واذ قلتم يموسي لن نؤمن لك حتي نري الله جهره فاخذتكم الصعقه وانتم تنظرون', 1, 1, 3, 1, 1, 8, false, NULL),
    (63, 'tanzil-uthmani-v1.1', 2, 56, 'ثُمَّ بَعَثْنَٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ', '7f9a814043a40b212ea22244a293500321148be862478e967f751e718c85814a', 'ثُمَّ بَعَثْنَٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ', '7f9a814043a40b212ea22244a293500321148be862478e967f751e718c85814a', '7f9a814043a40b212ea22244a293500321148be862478e967f751e718c85814a', NULL, 'ثم بعثنكم من بعد موتكم لعلكم تشكرون', 1, 1, 3, 1, 1, 8, false, NULL),
    (64, 'tanzil-uthmani-v1.1', 2, 57, 'وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'c016fb20eff8ab282ba7834aa9d632eda8f84db4150a20d49cd35e41211d7cb7', 'وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'c016fb20eff8ab282ba7834aa9d632eda8f84db4150a20d49cd35e41211d7cb7', 'c016fb20eff8ab282ba7834aa9d632eda8f84db4150a20d49cd35e41211d7cb7', NULL, 'وظللنا عليكم الغمام وانزلنا عليكم المن والسلوي كلوا من طيبت ما رزقنكم وما ظلمونا ولكن كانوا انفسهم يظلمون', 1, 1, 3, 1, 1, 8, false, NULL),
    (65, 'tanzil-uthmani-v1.1', 2, 58, 'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَٰيَٰكُمْ وَسَنَزِيدُ ٱلْمُحْسِنِينَ', 'eea493607ae4ea75de20a7c13554b28d27cd21303df732b5546378761e6a6b88', 'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَٰيَٰكُمْ وَسَنَزِيدُ ٱلْمُحْسِنِينَ', 'eea493607ae4ea75de20a7c13554b28d27cd21303df732b5546378761e6a6b88', 'eea493607ae4ea75de20a7c13554b28d27cd21303df732b5546378761e6a6b88', NULL, 'واذ قلنا ادخلوا هذه القريه فكلوا منها حيث شئتم رغدا وادخلوا الباب سجدا وقولوا حطه نغفر لكم خطيكم وسنزيد المحسنين', 1, 1, 3, 1, 1, 9, false, NULL),
    (66, 'tanzil-uthmani-v1.1', 2, 59, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', '3abe1104826fc56da80a42f0acc6896690aae5f3cf60a92ca299b2fa9a432bb2', 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', '3abe1104826fc56da80a42f0acc6896690aae5f3cf60a92ca299b2fa9a432bb2', '3abe1104826fc56da80a42f0acc6896690aae5f3cf60a92ca299b2fa9a432bb2', NULL, 'فبدل الذين ظلموا قولا غير الذي قيل لهم فانزلنا علي الذين ظلموا رجزا من السماء بما كانوا يفسقون', 1, 1, 3, 1, 1, 9, false, NULL),
    (67, 'tanzil-uthmani-v1.1', 2, 60, 'وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '21dcc0525a78866714ae477ac0db5ae6f52eb0916b69062f9ffb0a7fd97590af', 'وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '21dcc0525a78866714ae477ac0db5ae6f52eb0916b69062f9ffb0a7fd97590af', '21dcc0525a78866714ae477ac0db5ae6f52eb0916b69062f9ffb0a7fd97590af', NULL, 'واذ استسقي موسي لقومه فقلنا اضرب بعصاك الحجر فانفجرت منه اثنتا عشره عينا قد علم كل اناس مشربهم كلوا واشربوا من رزق الله ولا تعثوا في الارض مفسدين', 1, 1, 4, 1, 1, 9, false, NULL),
    (68, 'tanzil-uthmani-v1.1', 2, 61, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'c98b346cf1f48f225c076b1f560c4d2ca42e5f5b8e8a9e18fbefbf9abe9f672a', 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'c98b346cf1f48f225c076b1f560c4d2ca42e5f5b8e8a9e18fbefbf9abe9f672a', 'c98b346cf1f48f225c076b1f560c4d2ca42e5f5b8e8a9e18fbefbf9abe9f672a', NULL, 'واذ قلتم يموسي لن نصبر علي طعام وحد فادع لنا ربك يخرج لنا مما تنبت الارض من بقلها وقثائها وفومها وعدسها وبصلها قال اتستبدلون الذي هو ادني بالذي هو خير اهبطوا مصرا فان لكم ما سالتم وضربت عليهم الذله والمسكنه وباءو بغضب من الله ذلك بانهم كانوا يكفرون بايت الله ويقتلون النبين بغير الحق ذلك بما عصوا وكانوا يعتدون', 1, 1, 4, 1, 1, 9, false, NULL),
    (69, 'tanzil-uthmani-v1.1', 2, 62, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '6c476cb85470e4fe72608e487321b001859daf02045b0eeed1fdf57aa8ce1c74', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '6c476cb85470e4fe72608e487321b001859daf02045b0eeed1fdf57aa8ce1c74', '6c476cb85470e4fe72608e487321b001859daf02045b0eeed1fdf57aa8ce1c74', NULL, 'ان الذين ءامنوا والذين هادوا والنصري والصبين من ءامن بالله واليوم الاخر وعمل صلحا فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', 1, 1, 4, 1, 1, 10, false, NULL),
    (70, 'tanzil-uthmani-v1.1', 2, 63, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'a1859396064bba589f7026fe3216dc4149f36ef0cecc881f96ecb0bfb135d013', 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'a1859396064bba589f7026fe3216dc4149f36ef0cecc881f96ecb0bfb135d013', 'a1859396064bba589f7026fe3216dc4149f36ef0cecc881f96ecb0bfb135d013', NULL, 'واذ اخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما ءاتينكم بقوه واذكروا ما فيه لعلكم تتقون', 1, 1, 4, 1, 1, 10, false, NULL),
    (71, 'tanzil-uthmani-v1.1', 2, 64, 'ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَٰسِرِينَ', 'd92fb7eddc054e400b94170086739e498a67ea7eea5a53539ee388c9761b3e74', 'ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَٰسِرِينَ', 'd92fb7eddc054e400b94170086739e498a67ea7eea5a53539ee388c9761b3e74', 'd92fb7eddc054e400b94170086739e498a67ea7eea5a53539ee388c9761b3e74', NULL, 'ثم توليتم من بعد ذلك فلولا فضل الله عليكم ورحمته لكنتم من الخسرين', 1, 1, 4, 1, 1, 10, false, NULL),
    (72, 'tanzil-uthmani-v1.1', 2, 65, 'وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', '5c6dc6489d6f17980399f9dba3761327ba986efc21cfd741825c6ca55a4bfd7b', 'وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', '5c6dc6489d6f17980399f9dba3761327ba986efc21cfd741825c6ca55a4bfd7b', '5c6dc6489d6f17980399f9dba3761327ba986efc21cfd741825c6ca55a4bfd7b', NULL, 'ولقد علمتم الذين اعتدوا منكم في السبت فقلنا لهم كونوا قرده خسين', 1, 1, 4, 1, 1, 10, false, NULL),
    (73, 'tanzil-uthmani-v1.1', 2, 66, 'فَجَعَلْنَٰهَا نَكَٰلًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ', '375d6c9bf649f0a6e925582353e080088a5284ed7cad43471352fb0c69fb7b19', 'فَجَعَلْنَٰهَا نَكَٰلًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ', '375d6c9bf649f0a6e925582353e080088a5284ed7cad43471352fb0c69fb7b19', '375d6c9bf649f0a6e925582353e080088a5284ed7cad43471352fb0c69fb7b19', NULL, 'فجعلنها نكلا لما بين يديها وما خلفها وموعظه للمتقين', 1, 1, 4, 1, 1, 10, false, NULL),
    (74, 'tanzil-uthmani-v1.1', 2, 67, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةً قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًا قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَٰهِلِينَ', '8c5a09639237dd7166d00c1131b482a5e0e418e4ffbe6027150b0d3c635e955e', 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةً قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًا قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَٰهِلِينَ', '8c5a09639237dd7166d00c1131b482a5e0e418e4ffbe6027150b0d3c635e955e', '8c5a09639237dd7166d00c1131b482a5e0e418e4ffbe6027150b0d3c635e955e', NULL, 'واذ قال موسي لقومه ان الله يامركم ان تذبحوا بقره قالوا اتتخذنا هزوا قال اعوذ بالله ان اكون من الجهلين', 1, 1, 4, 1, 1, 10, false, NULL),
    (75, 'tanzil-uthmani-v1.1', 2, 68, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ', '1f883057b1e160d8d4c3ea3584170e5a35099767b8bdc3726b5bdace53e49138', 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ', '1f883057b1e160d8d4c3ea3584170e5a35099767b8bdc3726b5bdace53e49138', '1f883057b1e160d8d4c3ea3584170e5a35099767b8bdc3726b5bdace53e49138', NULL, 'قالوا ادع لنا ربك يبين لنا ما هي قال انه يقول انها بقره لا فارض ولا بكر عوان بين ذلك فافعلوا ما تؤمرون', 1, 1, 4, 1, 1, 10, false, NULL),
    (76, 'tanzil-uthmani-v1.1', 2, 69, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَآءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ ٱلنَّٰظِرِينَ', '45bafe745dbac4fb7731cbe8300ab65f8e0b8505d7f0ebd74847cf3f1a43ac15', 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَآءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ ٱلنَّٰظِرِينَ', '45bafe745dbac4fb7731cbe8300ab65f8e0b8505d7f0ebd74847cf3f1a43ac15', '45bafe745dbac4fb7731cbe8300ab65f8e0b8505d7f0ebd74847cf3f1a43ac15', NULL, 'قالوا ادع لنا ربك يبين لنا ما لونها قال انه يقول انها بقره صفراء فاقع لونها تسر النظرين', 1, 1, 4, 1, 1, 10, false, NULL),
    (77, 'tanzil-uthmani-v1.1', 2, 70, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ', '9a131802a2e3af1216e68c255709fdb1f85adbdfa7fdcfa6092eae54ed6b4993', 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ', '9a131802a2e3af1216e68c255709fdb1f85adbdfa7fdcfa6092eae54ed6b4993', '9a131802a2e3af1216e68c255709fdb1f85adbdfa7fdcfa6092eae54ed6b4993', NULL, 'قالوا ادع لنا ربك يبين لنا ما هي ان البقر تشبه علينا وانا ان شاء الله لمهتدون', 1, 1, 4, 1, 1, 11, false, NULL),
    (78, 'tanzil-uthmani-v1.1', 2, 71, 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا قَالُوا۟ ٱلْـَٰٔنَ جِئْتَ بِٱلْحَقِّ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ', 'bb8ae3d7d3401cd49d04b1bd075da476ef49f2383f161b085178073cb99d9000', 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا قَالُوا۟ ٱلْـَٰٔنَ جِئْتَ بِٱلْحَقِّ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ', 'bb8ae3d7d3401cd49d04b1bd075da476ef49f2383f161b085178073cb99d9000', 'bb8ae3d7d3401cd49d04b1bd075da476ef49f2383f161b085178073cb99d9000', NULL, 'قال انه يقول انها بقره لا ذلول تثير الارض ولا تسقي الحرث مسلمه لا شيه فيها قالوا الن جئت بالحق فذبحوها وما كادوا يفعلون', 1, 1, 4, 1, 1, 11, false, NULL),
    (79, 'tanzil-uthmani-v1.1', 2, 72, 'وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ', 'e77a64588d799f4f9e5e78a5cbc15cdf459bdcab043c49688cf572a18b351610', 'وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ', 'e77a64588d799f4f9e5e78a5cbc15cdf459bdcab043c49688cf572a18b351610', 'e77a64588d799f4f9e5e78a5cbc15cdf459bdcab043c49688cf572a18b351610', NULL, 'واذ قتلتم نفسا فادرتم فيها والله مخرج ما كنتم تكتمون', 1, 1, 4, 1, 1, 11, false, NULL),
    (80, 'tanzil-uthmani-v1.1', 2, 73, 'فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '47162099f97ce945be94ecd3c87536a943ca05c804d78d7904bde4fd9e250866', 'فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '47162099f97ce945be94ecd3c87536a943ca05c804d78d7904bde4fd9e250866', '47162099f97ce945be94ecd3c87536a943ca05c804d78d7904bde4fd9e250866', NULL, 'فقلنا اضربوه ببعضها كذلك يحي الله الموتي ويريكم ءايته لعلكم تعقلون', 1, 1, 4, 1, 1, 11, false, NULL),
    (81, 'tanzil-uthmani-v1.1', 2, 74, 'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَٰرُ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'b99e03db0d177f173c7d5cea089f90adf5cbd188264407fc54ea81c4b3c0663f', 'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَٰرُ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'b99e03db0d177f173c7d5cea089f90adf5cbd188264407fc54ea81c4b3c0663f', 'b99e03db0d177f173c7d5cea089f90adf5cbd188264407fc54ea81c4b3c0663f', NULL, 'ثم قست قلوبكم من بعد ذلك فهي كالحجاره او اشد قسوه وان من الحجاره لما يتفجر منه الانهر وان منها لما يشقق فيخرج منه الماء وان منها لما يهبط من خشيه الله وما الله بغفل عما تعملون', 1, 1, 4, 1, 1, 11, false, NULL),
    (82, 'tanzil-uthmani-v1.1', 2, 75, 'أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ', '3df42c06490569a67e1f4db72c54fcbc6e29b0e6fb65ba7c00095cf5b2b5dbb8', 'أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ', '3df42c06490569a67e1f4db72c54fcbc6e29b0e6fb65ba7c00095cf5b2b5dbb8', '3df42c06490569a67e1f4db72c54fcbc6e29b0e6fb65ba7c00095cf5b2b5dbb8', NULL, 'افتطمعون ان يؤمنوا لكم وقد كان فريق منهم يسمعون كلم الله ثم يحرفونه من بعد ما عقلوه وهم يعلمون', 1, 2, 5, 1, 1, 11, false, NULL),
    (83, 'tanzil-uthmani-v1.1', 2, 76, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ أَفَلَا تَعْقِلُونَ', 'c2639a4c045e340cf58003119ee69950fcc73140304489d88ee90037725f8992', 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ أَفَلَا تَعْقِلُونَ', 'c2639a4c045e340cf58003119ee69950fcc73140304489d88ee90037725f8992', 'c2639a4c045e340cf58003119ee69950fcc73140304489d88ee90037725f8992', NULL, 'واذا لقوا الذين ءامنوا قالوا ءامنا واذا خلا بعضهم الي بعض قالوا اتحدثونهم بما فتح الله عليكم ليحاجوكم به عند ربكم افلا تعقلون', 1, 2, 5, 1, 1, 11, false, NULL),
    (84, 'tanzil-uthmani-v1.1', 2, 77, 'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'a5d36aa5c5b096a31dc42b0208b33a8e1451b9d3e8fcb84c00a40c340c61e657', 'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'a5d36aa5c5b096a31dc42b0208b33a8e1451b9d3e8fcb84c00a40c340c61e657', 'a5d36aa5c5b096a31dc42b0208b33a8e1451b9d3e8fcb84c00a40c340c61e657', NULL, 'اولا يعلمون ان الله يعلم ما يسرون وما يعلنون', 1, 2, 5, 1, 1, 12, false, NULL),
    (85, 'tanzil-uthmani-v1.1', 2, 78, 'وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ', '6c0e90923dd33a21a4c42ba00ce7b97a025b45689fa46a327cb8d4c6b0bb2dde', 'وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ', '6c0e90923dd33a21a4c42ba00ce7b97a025b45689fa46a327cb8d4c6b0bb2dde', '6c0e90923dd33a21a4c42ba00ce7b97a025b45689fa46a327cb8d4c6b0bb2dde', NULL, 'ومنهم اميون لا يعلمون الكتب الا اماني وان هم الا يظنون', 1, 2, 5, 1, 1, 12, false, NULL),
    (86, 'tanzil-uthmani-v1.1', 2, 79, 'فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ', 'a0f730dd7031e1e9e8a3ff6dea936de5ced3119a01a303a207efbabf0984e493', 'فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ', 'a0f730dd7031e1e9e8a3ff6dea936de5ced3119a01a303a207efbabf0984e493', 'a0f730dd7031e1e9e8a3ff6dea936de5ced3119a01a303a207efbabf0984e493', NULL, 'فويل للذين يكتبون الكتب بايديهم ثم يقولون هذا من عند الله ليشتروا به ثمنا قليلا فويل لهم مما كتبت ايديهم وويل لهم مما يكسبون', 1, 2, 5, 1, 1, 12, false, NULL),
    (87, 'tanzil-uthmani-v1.1', 2, 80, 'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '3039d887ee51964841f31f147e443e780ffe25c869f9d8663b3e44f6572aafdd', 'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '3039d887ee51964841f31f147e443e780ffe25c869f9d8663b3e44f6572aafdd', '3039d887ee51964841f31f147e443e780ffe25c869f9d8663b3e44f6572aafdd', NULL, 'وقالوا لن تمسنا النار الا اياما معدوده قل اتخذتم عند الله عهدا فلن يخلف الله عهده ام تقولون علي الله ما لا تعلمون', 1, 2, 5, 1, 1, 12, false, NULL),
    (88, 'tanzil-uthmani-v1.1', 2, 81, 'بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '3481f3694a7431d2b2933d98f4ebec9a885dcc782a1c1344288cb838fc891346', 'بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '3481f3694a7431d2b2933d98f4ebec9a885dcc782a1c1344288cb838fc891346', '3481f3694a7431d2b2933d98f4ebec9a885dcc782a1c1344288cb838fc891346', NULL, 'بلي من كسب سيئه واحطت به خطيته فاولئك اصحب النار هم فيها خلدون', 1, 2, 5, 1, 1, 12, false, NULL),
    (89, 'tanzil-uthmani-v1.1', 2, 82, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', '91dd7ed4f65cf564b660122ea1c6c51f8509aa09b652f6f0f07cf842f53ced5e', 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', '91dd7ed4f65cf564b660122ea1c6c51f8509aa09b652f6f0f07cf842f53ced5e', '91dd7ed4f65cf564b660122ea1c6c51f8509aa09b652f6f0f07cf842f53ced5e', NULL, 'والذين ءامنوا وعملوا الصلحت اولئك اصحب الجنه هم فيها خلدون', 1, 2, 5, 1, 1, 12, false, NULL),
    (90, 'tanzil-uthmani-v1.1', 2, 83, 'وَإِذْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ', 'a3b557c8e3f1008c20cfdf1fea4fee856ab5f9fa438f081f6be68c435b559401', 'وَإِذْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ', 'a3b557c8e3f1008c20cfdf1fea4fee856ab5f9fa438f081f6be68c435b559401', 'a3b557c8e3f1008c20cfdf1fea4fee856ab5f9fa438f081f6be68c435b559401', NULL, 'واذ اخذنا ميثق بني اسرءيل لا تعبدون الا الله وبالولدين احسانا وذي القربي واليتمي والمسكين وقولوا للناس حسنا واقيموا الصلوه وءاتوا الزكوه ثم توليتم الا قليلا منكم وانتم معرضون', 1, 2, 5, 1, 1, 12, false, NULL),
    (91, 'tanzil-uthmani-v1.1', 2, 84, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ', '2f840c1242e02bdb06deffcc017acd525545a87c76a32692748ec3a2f139db01', 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ', '2f840c1242e02bdb06deffcc017acd525545a87c76a32692748ec3a2f139db01', '2f840c1242e02bdb06deffcc017acd525545a87c76a32692748ec3a2f139db01', NULL, 'واذ اخذنا ميثقكم لا تسفكون دماءكم ولا تخرجون انفسكم من ديركم ثم اقررتم وانتم تشهدون', 1, 2, 5, 1, 1, 13, false, NULL),
    (92, 'tanzil-uthmani-v1.1', 2, 85, 'ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَٰرِهِمْ تَظَٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَٰرَىٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ ٱلْقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'd720107f159e37a72a25f6553d0895e2de653ac9d86a642be0137a18afa933ef', 'ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَٰرِهِمْ تَظَٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَٰرَىٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ ٱلْقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'd720107f159e37a72a25f6553d0895e2de653ac9d86a642be0137a18afa933ef', 'd720107f159e37a72a25f6553d0895e2de653ac9d86a642be0137a18afa933ef', NULL, 'ثم انتم هؤلاء تقتلون انفسكم وتخرجون فريقا منكم من ديرهم تظهرون عليهم بالاثم والعدون وان ياتوكم اسري تفدوهم وهو محرم عليكم اخراجهم افتؤمنون ببعض الكتب وتكفرون ببعض فما جزاء من يفعل ذلك منكم الا خزي في الحيوه الدنيا ويوم القيمه يردون الي اشد العذاب وما الله بغفل عما تعملون', 1, 2, 5, 1, 1, 13, false, NULL),
    (93, 'tanzil-uthmani-v1.1', 2, 86, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ', 'c68ab8536691ad417abce9e0f681b5b01596498b376064dad7af578959b5afb0', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ', 'c68ab8536691ad417abce9e0f681b5b01596498b376064dad7af578959b5afb0', 'c68ab8536691ad417abce9e0f681b5b01596498b376064dad7af578959b5afb0', NULL, 'اولئك الذين اشتروا الحيوه الدنيا بالاخره فلا يخفف عنهم العذاب ولا هم ينصرون', 1, 2, 5, 1, 1, 13, false, NULL),
    (94, 'tanzil-uthmani-v1.1', 2, 87, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ', '0cf0cbdaf9b408400ce9ed47a7b3416ada1dcd1372c613dd35abda9e3533a456', 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ', '0cf0cbdaf9b408400ce9ed47a7b3416ada1dcd1372c613dd35abda9e3533a456', '0cf0cbdaf9b408400ce9ed47a7b3416ada1dcd1372c613dd35abda9e3533a456', NULL, 'ولقد ءاتينا موسي الكتب وقفينا من بعده بالرسل وءاتينا عيسي ابن مريم البينت وايدنه بروح القدس افكلما جاءكم رسول بما لا تهوي انفسكم استكبرتم ففريقا كذبتم وفريقا تقتلون', 1, 2, 5, 1, 1, 13, false, NULL),
    (95, 'tanzil-uthmani-v1.1', 2, 88, 'وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ', '4a62652d580cc9fded35010f39059b378ef5899c5928983caa1385598ed0a5c5', 'وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ', '4a62652d580cc9fded35010f39059b378ef5899c5928983caa1385598ed0a5c5', '4a62652d580cc9fded35010f39059b378ef5899c5928983caa1385598ed0a5c5', NULL, 'وقالوا قلوبنا غلف بل لعنهم الله بكفرهم فقليلا ما يؤمنون', 1, 2, 5, 1, 1, 13, false, NULL),
    (96, 'tanzil-uthmani-v1.1', 2, 89, 'وَلَمَّا جَآءَهُمْ كِتَٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَٰفِرِينَ', 'c38fa2d0488b1719dd7c1db7196043111762fb8a65e29836bac5d9cca997a9f4', 'وَلَمَّا جَآءَهُمْ كِتَٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَٰفِرِينَ', 'c38fa2d0488b1719dd7c1db7196043111762fb8a65e29836bac5d9cca997a9f4', 'c38fa2d0488b1719dd7c1db7196043111762fb8a65e29836bac5d9cca997a9f4', NULL, 'ولما جاءهم كتب من عند الله مصدق لما معهم وكانوا من قبل يستفتحون علي الذين كفروا فلما جاءهم ما عرفوا كفروا به فلعنه الله علي الكفرين', 1, 2, 5, 1, 1, 14, false, NULL),
    (97, 'tanzil-uthmani-v1.1', 2, 90, 'بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ وَلِلْكَٰفِرِينَ عَذَابٌ مُّهِينٌ', 'deae4ace10eaa42998dd5c565efe97c26c3f4cb89548ecf37fc7b96c4937f8f7', 'بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ وَلِلْكَٰفِرِينَ عَذَابٌ مُّهِينٌ', 'deae4ace10eaa42998dd5c565efe97c26c3f4cb89548ecf37fc7b96c4937f8f7', 'deae4ace10eaa42998dd5c565efe97c26c3f4cb89548ecf37fc7b96c4937f8f7', NULL, 'بئسما اشتروا به انفسهم ان يكفروا بما انزل الله بغيا ان ينزل الله من فضله علي من يشاء من عباده فباءو بغضب علي غضب وللكفرين عذاب مهين', 1, 2, 5, 1, 1, 14, false, NULL),
    (98, 'tanzil-uthmani-v1.1', 2, 91, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ', '577f1be2cf2c6cef9c4cfff2af372e90213c83d14196ea586c8b3516cf9a65e4', 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ', '577f1be2cf2c6cef9c4cfff2af372e90213c83d14196ea586c8b3516cf9a65e4', '577f1be2cf2c6cef9c4cfff2af372e90213c83d14196ea586c8b3516cf9a65e4', NULL, 'واذا قيل لهم ءامنوا بما انزل الله قالوا نؤمن بما انزل علينا ويكفرون بما وراءه وهو الحق مصدقا لما معهم قل فلم تقتلون انبياء الله من قبل ان كنتم مؤمنين', 1, 2, 5, 1, 1, 14, false, NULL),
    (99, 'tanzil-uthmani-v1.1', 2, 92, 'وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', '5c047767453359d5832321397dc560cddd94ed02f2d32855171f13bc1506184a', 'وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', '5c047767453359d5832321397dc560cddd94ed02f2d32855171f13bc1506184a', '5c047767453359d5832321397dc560cddd94ed02f2d32855171f13bc1506184a', NULL, 'ولقد جاءكم موسي بالبينت ثم اتخذتم العجل من بعده وانتم ظلمون', 1, 2, 6, 1, 1, 14, false, NULL),
    (100, 'tanzil-uthmani-v1.1', 2, 93, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'e04ce8b9cedf93c1f588a05d4ef713f8bf577a36d083badeb3a824a04c332d3d', 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'e04ce8b9cedf93c1f588a05d4ef713f8bf577a36d083badeb3a824a04c332d3d', 'e04ce8b9cedf93c1f588a05d4ef713f8bf577a36d083badeb3a824a04c332d3d', NULL, 'واذ اخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما ءاتينكم بقوه واسمعوا قالوا سمعنا وعصينا واشربوا في قلوبهم العجل بكفرهم قل بئسما يامركم به ايمنكم ان كنتم مؤمنين', 1, 2, 6, 1, 1, 14, false, NULL),
    (101, 'tanzil-uthmani-v1.1', 2, 94, 'قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةً مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', '0f7864b5b61479438bea7334af803689cc511b1f8769572a8ab5554c9fcf6e91', 'قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةً مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', '0f7864b5b61479438bea7334af803689cc511b1f8769572a8ab5554c9fcf6e91', '0f7864b5b61479438bea7334af803689cc511b1f8769572a8ab5554c9fcf6e91', NULL, 'قل ان كانت لكم الدار الاخره عند الله خالصه من دون الناس فتمنوا الموت ان كنتم صدقين', 1, 2, 6, 1, 1, 15, false, NULL),
    (102, 'tanzil-uthmani-v1.1', 2, 95, 'وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', '25dab4825af53ae65df9c1ccf326af46288275184b476a4ede46678a21fc9ff6', 'وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', '25dab4825af53ae65df9c1ccf326af46288275184b476a4ede46678a21fc9ff6', '25dab4825af53ae65df9c1ccf326af46288275184b476a4ede46678a21fc9ff6', NULL, 'ولن يتمنوه ابدا بما قدمت ايديهم والله عليم بالظلمين', 1, 2, 6, 1, 1, 15, false, NULL),
    (103, 'tanzil-uthmani-v1.1', 2, 96, 'وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', '5763e538c94cb42f3043a781b1af08134746f541fd1ef7ea1765ec31f9739e89', 'وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', '5763e538c94cb42f3043a781b1af08134746f541fd1ef7ea1765ec31f9739e89', '5763e538c94cb42f3043a781b1af08134746f541fd1ef7ea1765ec31f9739e89', NULL, 'ولتجدنهم احرص الناس علي حيوه ومن الذين اشركوا يود احدهم لو يعمر الف سنه وما هو بمزحزحه من العذاب ان يعمر والله بصير بما يعملون', 1, 2, 6, 1, 1, 15, false, NULL),
    (104, 'tanzil-uthmani-v1.1', 2, 97, 'قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 'ba086ed4f15527c0b564683f295a4a1b0bf3699db5143604d6b46e8e4bbdc3ac', 'قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 'ba086ed4f15527c0b564683f295a4a1b0bf3699db5143604d6b46e8e4bbdc3ac', 'ba086ed4f15527c0b564683f295a4a1b0bf3699db5143604d6b46e8e4bbdc3ac', NULL, 'قل من كان عدوا لجبريل فانه نزله علي قلبك باذن الله مصدقا لما بين يديه وهدي وبشري للمؤمنين', 1, 2, 6, 1, 1, 15, false, NULL),
    (105, 'tanzil-uthmani-v1.1', 2, 98, 'مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّ لِّلْكَٰفِرِينَ', '7b857df39b9264de5cf25d1ab55a6df459a2861744beb633eaa76e0232817112', 'مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّ لِّلْكَٰفِرِينَ', '7b857df39b9264de5cf25d1ab55a6df459a2861744beb633eaa76e0232817112', '7b857df39b9264de5cf25d1ab55a6df459a2861744beb633eaa76e0232817112', NULL, 'من كان عدوا لله وملئكته ورسله وجبريل وميكيل فان الله عدو للكفرين', 1, 2, 6, 1, 1, 15, false, NULL),
    (106, 'tanzil-uthmani-v1.1', 2, 99, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَٰتٍۭ بَيِّنَٰتٍ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَٰسِقُونَ', '0650bc1bcb43a45b6d81f97c8f0857e54933311bc1f018575ccd8eee1e28198f', 'وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَٰتٍۭ بَيِّنَٰتٍ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَٰسِقُونَ', '0650bc1bcb43a45b6d81f97c8f0857e54933311bc1f018575ccd8eee1e28198f', '0650bc1bcb43a45b6d81f97c8f0857e54933311bc1f018575ccd8eee1e28198f', NULL, 'ولقد انزلنا اليك ءايت بينت وما يكفر بها الا الفسقون', 1, 2, 6, 1, 1, 15, false, NULL),
    (107, 'tanzil-uthmani-v1.1', 2, 100, 'أَوَكُلَّمَا عَٰهَدُوا۟ عَهْدًا نَّبَذَهُۥ فَرِيقٌ مِّنْهُم بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ', 'f14b2b367bd9ba963703cd1b06306378c8e3f7ae7c5fff436befaa35078c6c26', 'أَوَكُلَّمَا عَٰهَدُوا۟ عَهْدًا نَّبَذَهُۥ فَرِيقٌ مِّنْهُم بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ', 'f14b2b367bd9ba963703cd1b06306378c8e3f7ae7c5fff436befaa35078c6c26', 'f14b2b367bd9ba963703cd1b06306378c8e3f7ae7c5fff436befaa35078c6c26', NULL, 'اوكلما عهدوا عهدا نبذه فريق منهم بل اكثرهم لا يؤمنون', 1, 2, 6, 1, 1, 15, false, NULL),
    (108, 'tanzil-uthmani-v1.1', 2, 101, 'وَلَمَّا جَآءَهُمْ رَسُولٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ', 'df0513235ab710a3e784d6ce692c2900f884b115f4e30139573f6ed231f9268e', 'وَلَمَّا جَآءَهُمْ رَسُولٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ', 'df0513235ab710a3e784d6ce692c2900f884b115f4e30139573f6ed231f9268e', 'df0513235ab710a3e784d6ce692c2900f884b115f4e30139573f6ed231f9268e', NULL, 'ولما جاءهم رسول من عند الله مصدق لما معهم نبذ فريق من الذين اوتوا الكتب كتب الله وراء ظهورهم كانهم لا يعلمون', 1, 2, 6, 1, 1, 15, false, NULL),
    (109, 'tanzil-uthmani-v1.1', 2, 102, 'وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَٰنَ وَمَا كَفَرَ سُلَيْمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَٰقٍ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ لَوْ كَانُوا۟ يَعْلَمُونَ', '98cea3b091a35cc0356ee7e5cd4189d641f9bbe54a6bd8ffc3bebde84a9731a4', 'وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَٰنَ وَمَا كَفَرَ سُلَيْمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَٰقٍ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ لَوْ كَانُوا۟ يَعْلَمُونَ', '98cea3b091a35cc0356ee7e5cd4189d641f9bbe54a6bd8ffc3bebde84a9731a4', '98cea3b091a35cc0356ee7e5cd4189d641f9bbe54a6bd8ffc3bebde84a9731a4', NULL, 'واتبعوا ما تتلوا الشيطين علي ملك سليمن وما كفر سليمن ولكن الشيطين كفروا يعلمون الناس السحر وما انزل علي الملكين ببابل هروت ومروت وما يعلمان من احد حتي يقولا انما نحن فتنه فلا تكفر فيتعلمون منهما ما يفرقون به بين المرء وزوجه وما هم بضارين به من احد الا باذن الله ويتعلمون ما يضرهم ولا ينفعهم ولقد علموا لمن اشتريه ما له في الاخره من خلق ولبئس ما شروا به انفسهم لو كانوا يعلمون', 1, 2, 6, 1, 1, 16, false, NULL),
    (110, 'tanzil-uthmani-v1.1', 2, 103, 'وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌ مِّنْ عِندِ ٱللَّهِ خَيْرٌ لَّوْ كَانُوا۟ يَعْلَمُونَ', 'ec0f16fd7ff624611f4c2323039cf61ce4c91b685ae55a6e10907ec472e71656', 'وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌ مِّنْ عِندِ ٱللَّهِ خَيْرٌ لَّوْ كَانُوا۟ يَعْلَمُونَ', 'ec0f16fd7ff624611f4c2323039cf61ce4c91b685ae55a6e10907ec472e71656', 'ec0f16fd7ff624611f4c2323039cf61ce4c91b685ae55a6e10907ec472e71656', NULL, 'ولو انهم ءامنوا واتقوا لمثوبه من عند الله خير لو كانوا يعلمون', 1, 2, 6, 1, 1, 16, false, NULL),
    (111, 'tanzil-uthmani-v1.1', 2, 104, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ', '1f07dc567d73a5bdbec7be763f517c3c357be1f4c065085c2f0e6f72c646505c', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ', '1f07dc567d73a5bdbec7be763f517c3c357be1f4c065085c2f0e6f72c646505c', '1f07dc567d73a5bdbec7be763f517c3c357be1f4c065085c2f0e6f72c646505c', NULL, 'يايها الذين ءامنوا لا تقولوا رعنا وقولوا انظرنا واسمعوا وللكفرين عذاب اليم', 1, 2, 6, 1, 1, 16, false, NULL),
    (112, 'tanzil-uthmani-v1.1', 2, 105, 'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '8538816e35adaa69aa228ef7997c6e2454001a1c91813ca7c439756a871c661c', 'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '8538816e35adaa69aa228ef7997c6e2454001a1c91813ca7c439756a871c661c', '8538816e35adaa69aa228ef7997c6e2454001a1c91813ca7c439756a871c661c', NULL, 'ما يود الذين كفروا من اهل الكتب ولا المشركين ان ينزل عليكم من خير من ربكم والله يختص برحمته من يشاء والله ذو الفضل العظيم', 1, 2, 6, 1, 1, 16, false, NULL),
    (113, 'tanzil-uthmani-v1.1', 2, 106, 'مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '24d419b620e9c10b8be9fd2a73be5c797cf9a39b549800543b577f8ad6ab67e2', 'مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '24d419b620e9c10b8be9fd2a73be5c797cf9a39b549800543b577f8ad6ab67e2', '24d419b620e9c10b8be9fd2a73be5c797cf9a39b549800543b577f8ad6ab67e2', NULL, 'ما ننسخ من ءايه او ننسها نات بخير منها او مثلها الم تعلم ان الله علي كل شيء قدير', 1, 2, 7, 1, 1, 17, false, NULL),
    (114, 'tanzil-uthmani-v1.1', 2, 107, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '8d05d605e87d51a34a6813b33bfbd6314ae54959804fd7a6d0a7a0610664a7be', 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '8d05d605e87d51a34a6813b33bfbd6314ae54959804fd7a6d0a7a0610664a7be', '8d05d605e87d51a34a6813b33bfbd6314ae54959804fd7a6d0a7a0610664a7be', NULL, 'الم تعلم ان الله له ملك السموت والارض وما لكم من دون الله من ولي ولا نصير', 1, 2, 7, 1, 1, 17, false, NULL),
    (115, 'tanzil-uthmani-v1.1', 2, 108, 'أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'faca860a4dbc2e1531e18b364334cbaca039af43d9cafe57d53d87edff8673f4', 'أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'faca860a4dbc2e1531e18b364334cbaca039af43d9cafe57d53d87edff8673f4', 'faca860a4dbc2e1531e18b364334cbaca039af43d9cafe57d53d87edff8673f4', NULL, 'ام تريدون ان تسلوا رسولكم كما سئل موسي من قبل ومن يتبدل الكفر بالايمن فقد ضل سواء السبيل', 1, 2, 7, 1, 1, 17, false, NULL),
    (116, 'tanzil-uthmani-v1.1', 2, 109, 'وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '90c6d39b5c24ddc6c413fa942a82ea19d3009ac4974778760f774f9078bf4aa1', 'وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '90c6d39b5c24ddc6c413fa942a82ea19d3009ac4974778760f774f9078bf4aa1', '90c6d39b5c24ddc6c413fa942a82ea19d3009ac4974778760f774f9078bf4aa1', NULL, 'ود كثير من اهل الكتب لو يردونكم من بعد ايمنكم كفارا حسدا من عند انفسهم من بعد ما تبين لهم الحق فاعفوا واصفحوا حتي ياتي الله بامره ان الله علي كل شيء قدير', 1, 2, 7, 1, 1, 17, false, NULL),
    (117, 'tanzil-uthmani-v1.1', 2, 110, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 'acfcdd4009425ed0557a86790e927f5ad521e65a21bdf7425c1b0c47e5f6bf0b', 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 'acfcdd4009425ed0557a86790e927f5ad521e65a21bdf7425c1b0c47e5f6bf0b', 'acfcdd4009425ed0557a86790e927f5ad521e65a21bdf7425c1b0c47e5f6bf0b', NULL, 'واقيموا الصلوه وءاتوا الزكوه وما تقدموا لانفسكم من خير تجدوه عند الله ان الله بما تعملون بصير', 1, 2, 7, 1, 1, 17, false, NULL),
    (118, 'tanzil-uthmani-v1.1', 2, 111, 'وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَٰرَىٰ تِلْكَ أَمَانِيُّهُمْ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'e5eeea2f27643e1df12fb4b022a0d3ef2f42cb48c82587e782dd06542582b25b', 'وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَٰرَىٰ تِلْكَ أَمَانِيُّهُمْ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'e5eeea2f27643e1df12fb4b022a0d3ef2f42cb48c82587e782dd06542582b25b', 'e5eeea2f27643e1df12fb4b022a0d3ef2f42cb48c82587e782dd06542582b25b', NULL, 'وقالوا لن يدخل الجنه الا من كان هودا او نصري تلك امانيهم قل هاتوا برهنكم ان كنتم صدقين', 1, 2, 7, 1, 1, 17, false, NULL),
    (119, 'tanzil-uthmani-v1.1', 2, 112, 'بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '539f8e12674420614027b008f3b255e01c4329afb4772d99d1950dde928af5d9', 'بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '539f8e12674420614027b008f3b255e01c4329afb4772d99d1950dde928af5d9', '539f8e12674420614027b008f3b255e01c4329afb4772d99d1950dde928af5d9', NULL, 'بلي من اسلم وجهه لله وهو محسن فله اجره عند ربه ولا خوف عليهم ولا هم يحزنون', 1, 2, 7, 1, 1, 17, false, NULL),
    (120, 'tanzil-uthmani-v1.1', 2, 113, 'وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَىْءٍ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍ وَهُمْ يَتْلُونَ ٱلْكِتَٰبَ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '37eedce6ecf498fae7d342388df9e520246beae1956ebf897a9d67c91bc7e393', 'وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَىْءٍ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍ وَهُمْ يَتْلُونَ ٱلْكِتَٰبَ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '37eedce6ecf498fae7d342388df9e520246beae1956ebf897a9d67c91bc7e393', '37eedce6ecf498fae7d342388df9e520246beae1956ebf897a9d67c91bc7e393', NULL, 'وقالت اليهود ليست النصري علي شيء وقالت النصري ليست اليهود علي شيء وهم يتلون الكتب كذلك قال الذين لا يعلمون مثل قولهم فالله يحكم بينهم يوم القيمه فيما كانوا فيه يختلفون', 1, 2, 7, 1, 1, 18, false, NULL),
    (121, 'tanzil-uthmani-v1.1', 2, 114, 'وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ أُو۟لَٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', '388e304e5b296d936513687f7eac9f6795b4eb442a7e4e4908392ee03d9090bd', 'وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ أُو۟لَٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', '388e304e5b296d936513687f7eac9f6795b4eb442a7e4e4908392ee03d9090bd', '388e304e5b296d936513687f7eac9f6795b4eb442a7e4e4908392ee03d9090bd', NULL, 'ومن اظلم ممن منع مسجد الله ان يذكر فيها اسمه وسعي في خرابها اولئك ما كان لهم ان يدخلوها الا خائفين لهم في الدنيا خزي ولهم في الاخره عذاب عظيم', 1, 2, 7, 1, 1, 18, false, NULL),
    (122, 'tanzil-uthmani-v1.1', 2, 115, 'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌ', '94d01c4e1267d51482190e157de7b3124ecd5989898e01055dd2cc0d063a6cdd', 'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌ', '94d01c4e1267d51482190e157de7b3124ecd5989898e01055dd2cc0d063a6cdd', '94d01c4e1267d51482190e157de7b3124ecd5989898e01055dd2cc0d063a6cdd', NULL, 'ولله المشرق والمغرب فاينما تولوا فثم وجه الله ان الله وسع عليم', 1, 2, 7, 1, 1, 18, false, NULL),
    (123, 'tanzil-uthmani-v1.1', 2, 116, 'وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ بَل لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلٌّ لَّهُۥ قَٰنِتُونَ', '2595d3ca6d0a337b6c60dcd2972e3f90efd6fa7795f5a2cd2db0c53aabc0470d', 'وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ بَل لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلٌّ لَّهُۥ قَٰنِتُونَ', '2595d3ca6d0a337b6c60dcd2972e3f90efd6fa7795f5a2cd2db0c53aabc0470d', '2595d3ca6d0a337b6c60dcd2972e3f90efd6fa7795f5a2cd2db0c53aabc0470d', NULL, 'وقالوا اتخذ الله ولدا سبحنه بل له ما في السموت والارض كل له قنتون', 1, 2, 7, 1, 1, 18, false, NULL),
    (124, 'tanzil-uthmani-v1.1', 2, 117, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'b5c5743d89cda0edefd8cdaf8a1f3d72de7772b6b9a33d5ee6b425a42dd7a227', 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 'b5c5743d89cda0edefd8cdaf8a1f3d72de7772b6b9a33d5ee6b425a42dd7a227', 'b5c5743d89cda0edefd8cdaf8a1f3d72de7772b6b9a33d5ee6b425a42dd7a227', NULL, 'بديع السموت والارض واذا قضي امرا فانما يقول له كن فيكون', 1, 2, 7, 1, 1, 18, false, NULL),
    (125, 'tanzil-uthmani-v1.1', 2, 118, 'وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ تَشَٰبَهَتْ قُلُوبُهُمْ قَدْ بَيَّنَّا ٱلْـَٔايَٰتِ لِقَوْمٍ يُوقِنُونَ', '7198c9e7df68a6d96a99a1407bb053dcbe451730e371240c5bc30081ab77bd16', 'وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ تَشَٰبَهَتْ قُلُوبُهُمْ قَدْ بَيَّنَّا ٱلْـَٔايَٰتِ لِقَوْمٍ يُوقِنُونَ', '7198c9e7df68a6d96a99a1407bb053dcbe451730e371240c5bc30081ab77bd16', '7198c9e7df68a6d96a99a1407bb053dcbe451730e371240c5bc30081ab77bd16', NULL, 'وقال الذين لا يعلمون لولا يكلمنا الله او تاتينا ءايه كذلك قال الذين من قبلهم مثل قولهم تشبهت قلوبهم قد بينا الايت لقوم يوقنون', 1, 2, 7, 1, 1, 18, false, NULL),
    (126, 'tanzil-uthmani-v1.1', 2, 119, 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَلَا تُسْـَٔلُ عَنْ أَصْحَٰبِ ٱلْجَحِيمِ', '4b8e9079c8c8ce72a21d1b65b60dc4b5a203315c1cf7c989b50a711ead044579', 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَلَا تُسْـَٔلُ عَنْ أَصْحَٰبِ ٱلْجَحِيمِ', '4b8e9079c8c8ce72a21d1b65b60dc4b5a203315c1cf7c989b50a711ead044579', '4b8e9079c8c8ce72a21d1b65b60dc4b5a203315c1cf7c989b50a711ead044579', NULL, 'انا ارسلنك بالحق بشيرا ونذيرا ولا تسل عن اصحب الجحيم', 1, 2, 7, 1, 1, 18, false, NULL),
    (127, 'tanzil-uthmani-v1.1', 2, 120, 'وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '30f89b7edf2c40a8a30af06dfc020d35cedf4223b55da5fc308e02ebecd25ce4', 'وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '30f89b7edf2c40a8a30af06dfc020d35cedf4223b55da5fc308e02ebecd25ce4', '30f89b7edf2c40a8a30af06dfc020d35cedf4223b55da5fc308e02ebecd25ce4', NULL, 'ولن ترضي عنك اليهود ولا النصري حتي تتبع ملتهم قل ان هدي الله هو الهدي ولئن اتبعت اهواءهم بعد الذي جاءك من العلم ما لك من الله من ولي ولا نصير', 1, 2, 7, 1, 1, 19, false, NULL),
    (128, 'tanzil-uthmani-v1.1', 2, 121, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'bf06696a977895f3a6895c758ca430051327859d7340cb3e50851db0c704de76', 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'bf06696a977895f3a6895c758ca430051327859d7340cb3e50851db0c704de76', 'bf06696a977895f3a6895c758ca430051327859d7340cb3e50851db0c704de76', NULL, 'الذين ءاتينهم الكتب يتلونه حق تلاوته اولئك يؤمنون به ومن يكفر به فاولئك هم الخسرون', 1, 2, 7, 1, 1, 19, false, NULL),
    (129, 'tanzil-uthmani-v1.1', 2, 122, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', '985c1473e1dc1c23056354b159a347ab7faffcaf8ca6ebe028428faa68d24475', 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', '985c1473e1dc1c23056354b159a347ab7faffcaf8ca6ebe028428faa68d24475', '985c1473e1dc1c23056354b159a347ab7faffcaf8ca6ebe028428faa68d24475', NULL, 'يبني اسرءيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين', 1, 2, 7, 1, 1, 19, false, NULL),
    (130, 'tanzil-uthmani-v1.1', 2, 123, 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَٰعَةٌ وَلَا هُمْ يُنصَرُونَ', '4079b527c4ff01d7b5206edc760a6bcdcfd746a2149808dc7abd695c20d9252b', 'وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَٰعَةٌ وَلَا هُمْ يُنصَرُونَ', '4079b527c4ff01d7b5206edc760a6bcdcfd746a2149808dc7abd695c20d9252b', '4079b527c4ff01d7b5206edc760a6bcdcfd746a2149808dc7abd695c20d9252b', NULL, 'واتقوا يوما لا تجزي نفس عن نفس شيا ولا يقبل منها عدل ولا تنفعها شفعه ولا هم ينصرون', 1, 2, 7, 1, 1, 19, false, NULL),
    (131, 'tanzil-uthmani-v1.1', 2, 124, 'وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٍ فَأَتَمَّهُنَّ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًا قَالَ وَمِن ذُرِّيَّتِى قَالَ لَا يَنَالُ عَهْدِى ٱلظَّٰلِمِينَ', '6e2fde6e943f6d9d4d1e8fdc99abe77f196cba0403bd26a96dc0fd0b41db52dc', 'وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٍ فَأَتَمَّهُنَّ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًا قَالَ وَمِن ذُرِّيَّتِى قَالَ لَا يَنَالُ عَهْدِى ٱلظَّٰلِمِينَ', '6e2fde6e943f6d9d4d1e8fdc99abe77f196cba0403bd26a96dc0fd0b41db52dc', '6e2fde6e943f6d9d4d1e8fdc99abe77f196cba0403bd26a96dc0fd0b41db52dc', NULL, 'واذ ابتلي ابرهم ربه بكلمت فاتمهن قال اني جاعلك للناس اماما قال ومن ذريتي قال لا ينال عهدي الظلمين', 1, 2, 8, 1, 1, 19, false, NULL),
    (132, 'tanzil-uthmani-v1.1', 2, 125, 'وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِـۧمَ مُصَلًّى وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', '21e8122dc227940cc4dcaf6126e3f9e044fdbfbcb5df386c4dbf21539bcb412a', 'وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِـۧمَ مُصَلًّى وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', '21e8122dc227940cc4dcaf6126e3f9e044fdbfbcb5df386c4dbf21539bcb412a', '21e8122dc227940cc4dcaf6126e3f9e044fdbfbcb5df386c4dbf21539bcb412a', NULL, 'واذ جعلنا البيت مثابه للناس وامنا واتخذوا من مقام ابرهم مصلي وعهدنا الي ابرهم واسمعيل ان طهرا بيتي للطائفين والعكفين والركع السجود', 1, 2, 8, 1, 1, 19, false, NULL),
    (133, 'tanzil-uthmani-v1.1', 2, 126, 'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ ٱجْعَلْ هَٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ وَبِئْسَ ٱلْمَصِيرُ', 'eb5fae141aa9627b0bdbafdf38dfe4bbcd5d45a8968786a9a43c4b2a070dd478', 'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ ٱجْعَلْ هَٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ وَبِئْسَ ٱلْمَصِيرُ', 'eb5fae141aa9627b0bdbafdf38dfe4bbcd5d45a8968786a9a43c4b2a070dd478', 'eb5fae141aa9627b0bdbafdf38dfe4bbcd5d45a8968786a9a43c4b2a070dd478', NULL, 'واذ قال ابرهم رب اجعل هذا بلدا ءامنا وارزق اهله من الثمرت من ءامن منهم بالله واليوم الاخر قال ومن كفر فامتعه قليلا ثم اضطره الي عذاب النار وبئس المصير', 1, 2, 8, 1, 1, 19, false, NULL),
    (134, 'tanzil-uthmani-v1.1', 2, 127, 'وَإِذْ يَرْفَعُ إِبْرَٰهِـۧمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '478cec6011108ad68397c07fdd4d9aac30c46c8e9266ceba59f0f9f752b8b769', 'وَإِذْ يَرْفَعُ إِبْرَٰهِـۧمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '478cec6011108ad68397c07fdd4d9aac30c46c8e9266ceba59f0f9f752b8b769', '478cec6011108ad68397c07fdd4d9aac30c46c8e9266ceba59f0f9f752b8b769', NULL, 'واذ يرفع ابرهم القواعد من البيت واسمعيل ربنا تقبل منا انك انت السميع العليم', 1, 2, 8, 1, 1, 20, false, NULL),
    (135, 'tanzil-uthmani-v1.1', 2, 128, 'رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '6b24703baa6be836dc4b6a0529c10d1d365c525395fb37e890310c95ca039336', 'رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '6b24703baa6be836dc4b6a0529c10d1d365c525395fb37e890310c95ca039336', '6b24703baa6be836dc4b6a0529c10d1d365c525395fb37e890310c95ca039336', NULL, 'ربنا واجعلنا مسلمين لك ومن ذريتنا امه مسلمه لك وارنا مناسكنا وتب علينا انك انت التواب الرحيم', 1, 2, 8, 1, 1, 20, false, NULL),
    (136, 'tanzil-uthmani-v1.1', 2, 129, 'رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'c7f024eb5520857678c9bce15c26312868eb8ed5e6b79bde98a3ca7b4bac842b', 'رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'c7f024eb5520857678c9bce15c26312868eb8ed5e6b79bde98a3ca7b4bac842b', 'c7f024eb5520857678c9bce15c26312868eb8ed5e6b79bde98a3ca7b4bac842b', NULL, 'ربنا وابعث فيهم رسولا منهم يتلوا عليهم ءايتك ويعلمهم الكتب والحكمه ويزكيهم انك انت العزيز الحكيم', 1, 2, 8, 1, 1, 20, false, NULL),
    (137, 'tanzil-uthmani-v1.1', 2, 130, 'وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ وَلَقَدِ ٱصْطَفَيْنَٰهُ فِى ٱلدُّنْيَا وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'bb2c8ac398429a21c85ab4cc422e7f40db31fe4b9063a48dd4b70fa31daa5195', 'وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ وَلَقَدِ ٱصْطَفَيْنَٰهُ فِى ٱلدُّنْيَا وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'bb2c8ac398429a21c85ab4cc422e7f40db31fe4b9063a48dd4b70fa31daa5195', 'bb2c8ac398429a21c85ab4cc422e7f40db31fe4b9063a48dd4b70fa31daa5195', NULL, 'ومن يرغب عن مله ابرهم الا من سفه نفسه ولقد اصطفينه في الدنيا وانه في الاخره لمن الصلحين', 1, 2, 8, 1, 1, 20, false, NULL),
    (138, 'tanzil-uthmani-v1.1', 2, 131, 'إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَٰلَمِينَ', 'e24bbfa53cacf40f0c4e19bacb1fcdbe34296fd3099d401b6de3ecc3234c0090', 'إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَٰلَمِينَ', 'e24bbfa53cacf40f0c4e19bacb1fcdbe34296fd3099d401b6de3ecc3234c0090', 'e24bbfa53cacf40f0c4e19bacb1fcdbe34296fd3099d401b6de3ecc3234c0090', NULL, 'اذ قال له ربه اسلم قال اسلمت لرب العلمين', 1, 2, 8, 1, 1, 20, false, NULL),
    (139, 'tanzil-uthmani-v1.1', 2, 132, 'وَوَصَّىٰ بِهَآ إِبْرَٰهِـۧمُ بَنِيهِ وَيَعْقُوبُ يَٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', '9e90b3e5e044b506a015af971f4ac1de3db05b94d0fb3a240baaf727754d6e74', 'وَوَصَّىٰ بِهَآ إِبْرَٰهِـۧمُ بَنِيهِ وَيَعْقُوبُ يَٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', '9e90b3e5e044b506a015af971f4ac1de3db05b94d0fb3a240baaf727754d6e74', '9e90b3e5e044b506a015af971f4ac1de3db05b94d0fb3a240baaf727754d6e74', NULL, 'ووصي بها ابرهم بنيه ويعقوب يبني ان الله اصطفي لكم الدين فلا تموتن الا وانتم مسلمون', 1, 2, 8, 1, 1, 20, false, NULL),
    (140, 'tanzil-uthmani-v1.1', 2, 133, 'أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ إِلَٰهًا وَٰحِدًا وَنَحْنُ لَهُۥ مُسْلِمُونَ', '2b74b8ec492bd7cd651fa68a505f309dad715153032c071f78dd5c16983601f8', 'أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ إِلَٰهًا وَٰحِدًا وَنَحْنُ لَهُۥ مُسْلِمُونَ', '2b74b8ec492bd7cd651fa68a505f309dad715153032c071f78dd5c16983601f8', '2b74b8ec492bd7cd651fa68a505f309dad715153032c071f78dd5c16983601f8', NULL, 'ام كنتم شهداء اذ حضر يعقوب الموت اذ قال لبنيه ما تعبدون من بعدي قالوا نعبد الهك واله ءابائك ابرهم واسمعيل واسحق الها وحدا ونحن له مسلمون', 1, 2, 8, 1, 1, 20, false, NULL),
    (141, 'tanzil-uthmani-v1.1', 2, 134, 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', '10d086b7595bc7045491030930ef5b1e3d82030ca91351a3ceb55d78944af6fa', 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', '10d086b7595bc7045491030930ef5b1e3d82030ca91351a3ceb55d78944af6fa', '10d086b7595bc7045491030930ef5b1e3d82030ca91351a3ceb55d78944af6fa', NULL, 'تلك امه قد خلت لها ما كسبت ولكم ما كسبتم ولا تسلون عما كانوا يعملون', 1, 2, 8, 1, 1, 20, false, NULL),
    (142, 'tanzil-uthmani-v1.1', 2, 135, 'وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَٰرَىٰ تَهْتَدُوا۟ قُلْ بَلْ مِلَّةَ إِبْرَٰهِـۧمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '89932900ea5c8e020c671c876c463ebffd11e26afa4cbb9def9c8dcca04fbe14', 'وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَٰرَىٰ تَهْتَدُوا۟ قُلْ بَلْ مِلَّةَ إِبْرَٰهِـۧمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '89932900ea5c8e020c671c876c463ebffd11e26afa4cbb9def9c8dcca04fbe14', '89932900ea5c8e020c671c876c463ebffd11e26afa4cbb9def9c8dcca04fbe14', NULL, 'وقالوا كونوا هودا او نصري تهتدوا قل بل مله ابرهم حنيفا وما كان من المشركين', 1, 2, 8, 1, 1, 21, false, NULL),
    (143, 'tanzil-uthmani-v1.1', 2, 136, 'قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', '3461ca773388eb28f722c4079ba668438a34db5cf973f37a86a7f3b9a72fb3a5', 'قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', '3461ca773388eb28f722c4079ba668438a34db5cf973f37a86a7f3b9a72fb3a5', '3461ca773388eb28f722c4079ba668438a34db5cf973f37a86a7f3b9a72fb3a5', NULL, 'قولوا ءامنا بالله وما انزل الينا وما انزل الي ابرهم واسمعيل واسحق ويعقوب والاسباط وما اوتي موسي وعيسي وما اوتي النبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون', 1, 2, 8, 1, 1, 21, false, NULL),
    (144, 'tanzil-uthmani-v1.1', 2, 137, 'فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍ فَسَيَكْفِيكَهُمُ ٱللَّهُ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '784f5567a081a4f625a4d6b5a339c886405624a8765461c644695ae3b187dc3e', 'فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍ فَسَيَكْفِيكَهُمُ ٱللَّهُ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '784f5567a081a4f625a4d6b5a339c886405624a8765461c644695ae3b187dc3e', '784f5567a081a4f625a4d6b5a339c886405624a8765461c644695ae3b187dc3e', NULL, 'فان ءامنوا بمثل ما ءامنتم به فقد اهتدوا وان تولوا فانما هم في شقاق فسيكفيكهم الله وهو السميع العليم', 1, 2, 8, 1, 1, 21, false, NULL),
    (145, 'tanzil-uthmani-v1.1', 2, 138, 'صِبْغَةَ ٱللَّهِ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةً وَنَحْنُ لَهُۥ عَٰبِدُونَ', 'e93fa491712a41be21857134292c9d0775f91a2b75d615e28c43de6238ad1329', 'صِبْغَةَ ٱللَّهِ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةً وَنَحْنُ لَهُۥ عَٰبِدُونَ', 'e93fa491712a41be21857134292c9d0775f91a2b75d615e28c43de6238ad1329', 'e93fa491712a41be21857134292c9d0775f91a2b75d615e28c43de6238ad1329', NULL, 'صبغه الله ومن احسن من الله صبغه ونحن له عبدون', 1, 2, 8, 1, 1, 21, false, NULL),
    (146, 'tanzil-uthmani-v1.1', 2, 139, 'قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ', 'a8048f2011211ca912ca2c04777f95a2f133db9901107a64d912753501726faf', 'قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ', 'a8048f2011211ca912ca2c04777f95a2f133db9901107a64d912753501726faf', 'a8048f2011211ca912ca2c04777f95a2f133db9901107a64d912753501726faf', NULL, 'قل اتحاجوننا في الله وهو ربنا وربكم ولنا اعملنا ولكم اعملكم ونحن له مخلصون', 1, 2, 8, 1, 1, 21, false, NULL),
    (147, 'tanzil-uthmani-v1.1', 2, 140, 'أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَٰرَىٰ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'd7123f2a1f2fbec4e0768ab2ff3d014ab8d801980bb92946ad6706edf2b66b4a', 'أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَٰرَىٰ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'd7123f2a1f2fbec4e0768ab2ff3d014ab8d801980bb92946ad6706edf2b66b4a', 'd7123f2a1f2fbec4e0768ab2ff3d014ab8d801980bb92946ad6706edf2b66b4a', NULL, 'ام تقولون ان ابرهم واسمعيل واسحق ويعقوب والاسباط كانوا هودا او نصري قل ءانتم اعلم ام الله ومن اظلم ممن كتم شهده عنده من الله وما الله بغفل عما تعملون', 1, 2, 8, 1, 1, 21, false, NULL),
    (148, 'tanzil-uthmani-v1.1', 2, 141, 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', '10d086b7595bc7045491030930ef5b1e3d82030ca91351a3ceb55d78944af6fa', 'تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', '10d086b7595bc7045491030930ef5b1e3d82030ca91351a3ceb55d78944af6fa', '10d086b7595bc7045491030930ef5b1e3d82030ca91351a3ceb55d78944af6fa', NULL, 'تلك امه قد خلت لها ما كسبت ولكم ما كسبتم ولا تسلون عما كانوا يعملون', 1, 2, 8, 1, 1, 21, false, NULL),
    (149, 'tanzil-uthmani-v1.1', 2, 142, 'سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '75b68d6ffcf7a76762c0615112598da5f981f8740752b7b6d5b6dd8f2ba723a6', 'سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '75b68d6ffcf7a76762c0615112598da5f981f8740752b7b6d5b6dd8f2ba723a6', '75b68d6ffcf7a76762c0615112598da5f981f8740752b7b6d5b6dd8f2ba723a6', NULL, 'سيقول السفهاء من الناس ما وليهم عن قبلتهم التي كانوا عليها قل لله المشرق والمغرب يهدي من يشاء الي صرط مستقيم', 2, 3, 9, 1, 1, 22, false, NULL),
    (150, 'tanzil-uthmani-v1.1', 2, 143, 'وَكَذَٰلِكَ جَعَلْنَٰكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًا وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمْ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', '1e96543f9daa14618650cf4f03a64fb7782c0643746c52bb223a93d44b5bf83b', 'وَكَذَٰلِكَ جَعَلْنَٰكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًا وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمْ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', '1e96543f9daa14618650cf4f03a64fb7782c0643746c52bb223a93d44b5bf83b', '1e96543f9daa14618650cf4f03a64fb7782c0643746c52bb223a93d44b5bf83b', NULL, 'وكذلك جعلنكم امه وسطا لتكونوا شهداء علي الناس ويكون الرسول عليكم شهيدا وما جعلنا القبله التي كنت عليها الا لنعلم من يتبع الرسول ممن ينقلب علي عقبيه وان كانت لكبيره الا علي الذين هدي الله وما كان الله ليضيع ايمنكم ان الله بالناس لرءوف رحيم', 2, 3, 9, 1, 1, 22, false, NULL),
    (151, 'tanzil-uthmani-v1.1', 2, 144, 'قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَىٰهَا فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'd740237200d3e183333e7a09624fd877ffa136edb822001d1899185d7bbeb157', 'قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَىٰهَا فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'd740237200d3e183333e7a09624fd877ffa136edb822001d1899185d7bbeb157', 'd740237200d3e183333e7a09624fd877ffa136edb822001d1899185d7bbeb157', NULL, 'قد نري تقلب وجهك في السماء فلنولينك قبله ترضيها فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره وان الذين اوتوا الكتب ليعلمون انه الحق من ربهم وما الله بغفل عما يعملون', 2, 3, 9, 1, 1, 22, false, NULL),
    (152, 'tanzil-uthmani-v1.1', 2, 145, 'وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ بِكُلِّ ءَايَةٍ مَّا تَبِعُوا۟ قِبْلَتَكَ وَمَآ أَنتَ بِتَابِعٍ قِبْلَتَهُمْ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ إِنَّكَ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'fc810dd7aee1bd2b8faa8e0a9ce459ef36480a8137d19b7bcda81214df486958', 'وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ بِكُلِّ ءَايَةٍ مَّا تَبِعُوا۟ قِبْلَتَكَ وَمَآ أَنتَ بِتَابِعٍ قِبْلَتَهُمْ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ إِنَّكَ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'fc810dd7aee1bd2b8faa8e0a9ce459ef36480a8137d19b7bcda81214df486958', 'fc810dd7aee1bd2b8faa8e0a9ce459ef36480a8137d19b7bcda81214df486958', NULL, 'ولئن اتيت الذين اوتوا الكتب بكل ءايه ما تبعوا قبلتك وما انت بتابع قبلتهم وما بعضهم بتابع قبله بعض ولئن اتبعت اهواءهم من بعد ما جاءك من العلم انك اذا لمن الظلمين', 2, 3, 9, 1, 1, 22, false, NULL),
    (153, 'tanzil-uthmani-v1.1', 2, 146, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ', 'ad601e89d53b2972587b930de14b19b14b012d354632af462f97edb8bc41b731', 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ', 'ad601e89d53b2972587b930de14b19b14b012d354632af462f97edb8bc41b731', 'ad601e89d53b2972587b930de14b19b14b012d354632af462f97edb8bc41b731', NULL, 'الذين ءاتينهم الكتب يعرفونه كما يعرفون ابناءهم وان فريقا منهم ليكتمون الحق وهم يعلمون', 2, 3, 9, 1, 1, 23, false, NULL),
    (154, 'tanzil-uthmani-v1.1', 2, 147, 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'e3194439f439a44712ab6ea49b400fe051217bd3dd91e503b8667f27489092a6', 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'e3194439f439a44712ab6ea49b400fe051217bd3dd91e503b8667f27489092a6', 'e3194439f439a44712ab6ea49b400fe051217bd3dd91e503b8667f27489092a6', NULL, 'الحق من ربك فلا تكونن من الممترين', 2, 3, 9, 1, 1, 23, false, NULL),
    (155, 'tanzil-uthmani-v1.1', 2, 148, 'وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'ef2eb5682831aeca8cbd1d103b36f19ca23b47ac1548d74a444ede9ba5de9cc8', 'وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'ef2eb5682831aeca8cbd1d103b36f19ca23b47ac1548d74a444ede9ba5de9cc8', 'ef2eb5682831aeca8cbd1d103b36f19ca23b47ac1548d74a444ede9ba5de9cc8', NULL, 'ولكل وجهه هو موليها فاستبقوا الخيرت اين ما تكونوا يات بكم الله جميعا ان الله علي كل شيء قدير', 2, 3, 9, 1, 1, 23, false, NULL),
    (156, 'tanzil-uthmani-v1.1', 2, 149, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', '9e413a7ef0288b1324f57d780f7689ad25f142cc9c3e996783529569327c86b7', 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', '9e413a7ef0288b1324f57d780f7689ad25f142cc9c3e996783529569327c86b7', '9e413a7ef0288b1324f57d780f7689ad25f142cc9c3e996783529569327c86b7', NULL, 'ومن حيث خرجت فول وجهك شطر المسجد الحرام وانه للحق من ربك وما الله بغفل عما تعملون', 2, 3, 9, 1, 1, 23, false, NULL),
    (157, 'tanzil-uthmani-v1.1', 2, 150, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ', 'ed9976e4636c91bb123cc1af69394a47ce5c834e5453f119b23b165189796ded', 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ', 'ed9976e4636c91bb123cc1af69394a47ce5c834e5453f119b23b165189796ded', 'ed9976e4636c91bb123cc1af69394a47ce5c834e5453f119b23b165189796ded', NULL, 'ومن حيث خرجت فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره لئلا يكون للناس عليكم حجه الا الذين ظلموا منهم فلا تخشوهم واخشوني ولاتم نعمتي عليكم ولعلكم تهتدون', 2, 3, 9, 1, 1, 23, false, NULL),
    (158, 'tanzil-uthmani-v1.1', 2, 151, 'كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 'b2b96d070f8fb7004f98fb522a95899cf687e4237c573e3884d7f89ba7a9a9d5', 'كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 'b2b96d070f8fb7004f98fb522a95899cf687e4237c573e3884d7f89ba7a9a9d5', 'b2b96d070f8fb7004f98fb522a95899cf687e4237c573e3884d7f89ba7a9a9d5', NULL, 'كما ارسلنا فيكم رسولا منكم يتلوا عليكم ءايتنا ويزكيكم ويعلمكم الكتب والحكمه ويعلمكم ما لم تكونوا تعلمون', 2, 3, 9, 1, 1, 23, false, NULL),
    (159, 'tanzil-uthmani-v1.1', 2, 152, 'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ', '990be2a1d255dd0bd01b215464074654fe8550ea3ffb97e161d88d420b9db809', 'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ', '990be2a1d255dd0bd01b215464074654fe8550ea3ffb97e161d88d420b9db809', '990be2a1d255dd0bd01b215464074654fe8550ea3ffb97e161d88d420b9db809', NULL, 'فاذكروني اذكركم واشكروا لي ولا تكفرون', 2, 3, 9, 1, 1, 23, false, NULL),
    (160, 'tanzil-uthmani-v1.1', 2, 153, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', '27460dea15329355458c79dcea6936ae0fd7e5f9a7859bdb65ad1a9ee0dcfa98', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', '27460dea15329355458c79dcea6936ae0fd7e5f9a7859bdb65ad1a9ee0dcfa98', '27460dea15329355458c79dcea6936ae0fd7e5f9a7859bdb65ad1a9ee0dcfa98', NULL, 'يايها الذين ءامنوا استعينوا بالصبر والصلوه ان الله مع الصبرين', 2, 3, 9, 1, 1, 23, false, NULL),
    (161, 'tanzil-uthmani-v1.1', 2, 154, 'وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ بَلْ أَحْيَآءٌ وَلَٰكِن لَّا تَشْعُرُونَ', 'a8494b2311ab14090c54a5f070581264a715a0275274732db462d6337909b848', 'وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ بَلْ أَحْيَآءٌ وَلَٰكِن لَّا تَشْعُرُونَ', 'a8494b2311ab14090c54a5f070581264a715a0275274732db462d6337909b848', 'a8494b2311ab14090c54a5f070581264a715a0275274732db462d6337909b848', NULL, 'ولا تقولوا لمن يقتل في سبيل الله اموت بل احياء ولكن لا تشعرون', 2, 3, 9, 1, 1, 24, false, NULL),
    (162, 'tanzil-uthmani-v1.1', 2, 155, 'وَلَنَبْلُوَنَّكُم بِشَىْءٍ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ وَبَشِّرِ ٱلصَّٰبِرِينَ', '8e2d17e6a0b440d72d060f9318b41313c3c4b40bce8c8febea2e2009dc9774f2', 'وَلَنَبْلُوَنَّكُم بِشَىْءٍ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ وَبَشِّرِ ٱلصَّٰبِرِينَ', '8e2d17e6a0b440d72d060f9318b41313c3c4b40bce8c8febea2e2009dc9774f2', '8e2d17e6a0b440d72d060f9318b41313c3c4b40bce8c8febea2e2009dc9774f2', NULL, 'ولنبلونكم بشيء من الخوف والجوع ونقص من الامول والانفس والثمرت وبشر الصبرين', 2, 3, 9, 1, 1, 24, false, NULL),
    (163, 'tanzil-uthmani-v1.1', 2, 156, 'ٱلَّذِينَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ', '0a5855023f71fc934fb121ae09ff2571a0af34714cc09f7c5c340fface634551', 'ٱلَّذِينَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ', '0a5855023f71fc934fb121ae09ff2571a0af34714cc09f7c5c340fface634551', '0a5855023f71fc934fb121ae09ff2571a0af34714cc09f7c5c340fface634551', NULL, 'الذين اذا اصبتهم مصيبه قالوا انا لله وانا اليه رجعون', 2, 3, 9, 1, 1, 24, false, NULL),
    (164, 'tanzil-uthmani-v1.1', 2, 157, 'أُو۟لَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ', 'dda2fd48c56fe5cdd276dc4238c1975cec0638cdc719e79bc7925aa26cf63861', 'أُو۟لَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ', 'dda2fd48c56fe5cdd276dc4238c1975cec0638cdc719e79bc7925aa26cf63861', 'dda2fd48c56fe5cdd276dc4238c1975cec0638cdc719e79bc7925aa26cf63861', NULL, 'اولئك عليهم صلوت من ربهم ورحمه واولئك هم المهتدون', 2, 3, 9, 1, 1, 24, false, NULL),
    (165, 'tanzil-uthmani-v1.1', 2, 158, 'إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ', 'e4b268d0c0ee0df60c54949bf619ed214008e669fd0234592f70f5214ca87a19', 'إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ', 'e4b268d0c0ee0df60c54949bf619ed214008e669fd0234592f70f5214ca87a19', 'e4b268d0c0ee0df60c54949bf619ed214008e669fd0234592f70f5214ca87a19', NULL, 'ان الصفا والمروه من شعائر الله فمن حج البيت او اعتمر فلا جناح عليه ان يطوف بهما ومن تطوع خيرا فان الله شاكر عليم', 2, 3, 10, 1, 1, 24, false, NULL),
    (166, 'tanzil-uthmani-v1.1', 2, 159, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ', '0a3922bbae81aa0e5ad45fa78ed6ab6ac97606aef2dae50fff81e85fe2099411', 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ', '0a3922bbae81aa0e5ad45fa78ed6ab6ac97606aef2dae50fff81e85fe2099411', '0a3922bbae81aa0e5ad45fa78ed6ab6ac97606aef2dae50fff81e85fe2099411', NULL, 'ان الذين يكتمون ما انزلنا من البينت والهدي من بعد ما بينه للناس في الكتب اولئك يلعنهم الله ويلعنهم اللعنون', 2, 3, 10, 1, 1, 24, false, NULL),
    (167, 'tanzil-uthmani-v1.1', 2, 160, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ', '1de4ee77fccb4add4d023da4a2a93c8c3664ead8e99cf02e178fc73e0c15e97d', 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ', '1de4ee77fccb4add4d023da4a2a93c8c3664ead8e99cf02e178fc73e0c15e97d', '1de4ee77fccb4add4d023da4a2a93c8c3664ead8e99cf02e178fc73e0c15e97d', NULL, 'الا الذين تابوا واصلحوا وبينوا فاولئك اتوب عليهم وانا التواب الرحيم', 2, 3, 10, 1, 1, 24, false, NULL),
    (168, 'tanzil-uthmani-v1.1', 2, 161, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', '9348867e0390095758e7843dc484ee7e643f90a569b261aad3830164e4c82723', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', '9348867e0390095758e7843dc484ee7e643f90a569b261aad3830164e4c82723', '9348867e0390095758e7843dc484ee7e643f90a569b261aad3830164e4c82723', NULL, 'ان الذين كفروا وماتوا وهم كفار اولئك عليهم لعنه الله والملئكه والناس اجمعين', 2, 3, 10, 1, 1, 24, false, NULL),
    (169, 'tanzil-uthmani-v1.1', 2, 162, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', '9e96454c03bb1a28c88b840f7d10128937e20755297eda9f178208f52de6e7e6', 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', '9e96454c03bb1a28c88b840f7d10128937e20755297eda9f178208f52de6e7e6', '9e96454c03bb1a28c88b840f7d10128937e20755297eda9f178208f52de6e7e6', NULL, 'خلدين فيها لا يخفف عنهم العذاب ولا هم ينظرون', 2, 3, 10, 1, 1, 24, false, NULL),
    (170, 'tanzil-uthmani-v1.1', 2, 163, 'وَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', '75aa0b0dc643f4238c1e317428acf76f020dede34480c0901e6fa38c5d10b1dd', 'وَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', '75aa0b0dc643f4238c1e317428acf76f020dede34480c0901e6fa38c5d10b1dd', '75aa0b0dc643f4238c1e317428acf76f020dede34480c0901e6fa38c5d10b1dd', NULL, 'والهكم اله وحد لا اله الا هو الرحمن الرحيم', 2, 3, 10, 1, 1, 24, false, NULL),
    (171, 'tanzil-uthmani-v1.1', 2, 164, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَتَصْرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', '275a812bafb5d3c0d749c015989816e8c8ee28abd183fc8be7f617d154548433', 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَتَصْرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', '275a812bafb5d3c0d749c015989816e8c8ee28abd183fc8be7f617d154548433', '275a812bafb5d3c0d749c015989816e8c8ee28abd183fc8be7f617d154548433', NULL, 'ان في خلق السموت والارض واختلف اليل والنهار والفلك التي تجري في البحر بما ينفع الناس وما انزل الله من السماء من ماء فاحيا به الارض بعد موتها وبث فيها من كل دابه وتصريف الريح والسحاب المسخر بين السماء والارض لايت لقوم يعقلون', 2, 3, 10, 1, 1, 25, false, NULL),
    (172, 'tanzil-uthmani-v1.1', 2, 165, 'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّا لِّلَّهِ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ', '51934b3c0a081156c9e20b6d6abce3f6c35b827fbd13fbfc225db283d09fa146', 'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّا لِّلَّهِ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ', '51934b3c0a081156c9e20b6d6abce3f6c35b827fbd13fbfc225db283d09fa146', '51934b3c0a081156c9e20b6d6abce3f6c35b827fbd13fbfc225db283d09fa146', NULL, 'ومن الناس من يتخذ من دون الله اندادا يحبونهم كحب الله والذين ءامنوا اشد حبا لله ولو يري الذين ظلموا اذ يرون العذاب ان القوه لله جميعا وان الله شديد العذاب', 2, 3, 10, 1, 1, 25, false, NULL),
    (173, 'tanzil-uthmani-v1.1', 2, 166, 'إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ', 'edb11f038fa60f83d27983886f40c4c5eb7c0eb709588d6bf6de12e6c13924bd', 'إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ', 'edb11f038fa60f83d27983886f40c4c5eb7c0eb709588d6bf6de12e6c13924bd', 'edb11f038fa60f83d27983886f40c4c5eb7c0eb709588d6bf6de12e6c13924bd', NULL, 'اذ تبرا الذين اتبعوا من الذين اتبعوا وراوا العذاب وتقطعت بهم الاسباب', 2, 3, 10, 1, 1, 25, false, NULL),
    (174, 'tanzil-uthmani-v1.1', 2, 167, 'وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ', '943b5b800ac0a4788406ba91b0240c3ae90fe8c06fd4b80bfb3fa85b7fd25eb5', 'وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ', '943b5b800ac0a4788406ba91b0240c3ae90fe8c06fd4b80bfb3fa85b7fd25eb5', '943b5b800ac0a4788406ba91b0240c3ae90fe8c06fd4b80bfb3fa85b7fd25eb5', NULL, 'وقال الذين اتبعوا لو ان لنا كره فنتبرا منهم كما تبرءوا منا كذلك يريهم الله اعملهم حسرت عليهم وما هم بخرجين من النار', 2, 3, 10, 1, 1, 25, false, NULL),
    (175, 'tanzil-uthmani-v1.1', 2, 168, 'يَٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَٰلًا طَيِّبًا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '2ff543bc0be227afbbe45019c280d57a547b5f834dc1f94c6c68ee2a0e9ad9ae', 'يَٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَٰلًا طَيِّبًا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '2ff543bc0be227afbbe45019c280d57a547b5f834dc1f94c6c68ee2a0e9ad9ae', '2ff543bc0be227afbbe45019c280d57a547b5f834dc1f94c6c68ee2a0e9ad9ae', NULL, 'يايها الناس كلوا مما في الارض حللا طيبا ولا تتبعوا خطوت الشيطن انه لكم عدو مبين', 2, 3, 10, 1, 1, 25, false, NULL),
    (176, 'tanzil-uthmani-v1.1', 2, 169, 'إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '72b545088dbaef0fb1da9d45750ca59b4a5ecf5b781064ac14903b55945ad24d', 'إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '72b545088dbaef0fb1da9d45750ca59b4a5ecf5b781064ac14903b55945ad24d', '72b545088dbaef0fb1da9d45750ca59b4a5ecf5b781064ac14903b55945ad24d', NULL, 'انما يامركم بالسوء والفحشاء وان تقولوا علي الله ما لا تعلمون', 2, 3, 10, 1, 1, 25, false, NULL),
    (177, 'tanzil-uthmani-v1.1', 2, 170, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', '443030b16307e9fcd25c7cb8c1fc4db4e75589e3c922cd373e3aeb80cea1193d', 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', '443030b16307e9fcd25c7cb8c1fc4db4e75589e3c922cd373e3aeb80cea1193d', '443030b16307e9fcd25c7cb8c1fc4db4e75589e3c922cd373e3aeb80cea1193d', NULL, 'واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما الفينا عليه ءاباءنا اولو كان ءاباؤهم لا يعقلون شيا ولا يهتدون', 2, 3, 10, 1, 1, 26, false, NULL),
    (178, 'tanzil-uthmani-v1.1', 2, 171, 'وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءً وَنِدَآءً صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَعْقِلُونَ', '04ceead4c5f6349f8950d71e13cecaf19083c9c9814d3cfe552a7869c0abcfe1', 'وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءً وَنِدَآءً صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَعْقِلُونَ', '04ceead4c5f6349f8950d71e13cecaf19083c9c9814d3cfe552a7869c0abcfe1', '04ceead4c5f6349f8950d71e13cecaf19083c9c9814d3cfe552a7869c0abcfe1', NULL, 'ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع الا دعاء ونداء صم بكم عمي فهم لا يعقلون', 2, 3, 10, 1, 1, 26, false, NULL),
    (179, 'tanzil-uthmani-v1.1', 2, 172, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'e985202608d27a181e82d8e4305900fcb7c0360a698eb10beb6cac10b8c57c70', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'e985202608d27a181e82d8e4305900fcb7c0360a698eb10beb6cac10b8c57c70', 'e985202608d27a181e82d8e4305900fcb7c0360a698eb10beb6cac10b8c57c70', NULL, 'يايها الذين ءامنوا كلوا من طيبت ما رزقنكم واشكروا لله ان كنتم اياه تعبدون', 2, 3, 10, 1, 1, 26, false, NULL),
    (180, 'tanzil-uthmani-v1.1', 2, 173, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '5f457b9528e1cace1817e3cd9de83337d9040c5771565cc0aeffb28ca3adf71e', 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '5f457b9528e1cace1817e3cd9de83337d9040c5771565cc0aeffb28ca3adf71e', '5f457b9528e1cace1817e3cd9de83337d9040c5771565cc0aeffb28ca3adf71e', NULL, 'انما حرم عليكم الميته والدم ولحم الخنزير وما اهل به لغير الله فمن اضطر غير باغ ولا عاد فلا اثم عليه ان الله غفور رحيم', 2, 3, 10, 1, 1, 26, false, NULL),
    (181, 'tanzil-uthmani-v1.1', 2, 174, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '5fa3f31c551eadd20a893e850edc12445da5cb7d94fc7d476387925ea048d6d3', 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '5fa3f31c551eadd20a893e850edc12445da5cb7d94fc7d476387925ea048d6d3', '5fa3f31c551eadd20a893e850edc12445da5cb7d94fc7d476387925ea048d6d3', NULL, 'ان الذين يكتمون ما انزل الله من الكتب ويشترون به ثمنا قليلا اولئك ما ياكلون في بطونهم الا النار ولا يكلمهم الله يوم القيمه ولا يزكيهم ولهم عذاب اليم', 2, 3, 10, 1, 1, 26, false, NULL),
    (182, 'tanzil-uthmani-v1.1', 2, 175, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ', '1e1a93ce5753f0afd7269b4df8736f0e60527425fdddfd4a0481aba68b7c73a9', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ', '1e1a93ce5753f0afd7269b4df8736f0e60527425fdddfd4a0481aba68b7c73a9', '1e1a93ce5753f0afd7269b4df8736f0e60527425fdddfd4a0481aba68b7c73a9', NULL, 'اولئك الذين اشتروا الضلله بالهدي والعذاب بالمغفره فما اصبرهم علي النار', 2, 3, 10, 1, 1, 26, false, NULL),
    (183, 'tanzil-uthmani-v1.1', 2, 176, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَٰبِ لَفِى شِقَاقٍۭ بَعِيدٍ', 'cc95707418a1f1881ca1a8a6ae2144aa9101597c87617b8facd886b5500313b9', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَٰبِ لَفِى شِقَاقٍۭ بَعِيدٍ', 'cc95707418a1f1881ca1a8a6ae2144aa9101597c87617b8facd886b5500313b9', 'cc95707418a1f1881ca1a8a6ae2144aa9101597c87617b8facd886b5500313b9', NULL, 'ذلك بان الله نزل الكتب بالحق وان الذين اختلفوا في الكتب لفي شقاق بعيد', 2, 3, 10, 1, 1, 26, false, NULL),
    (184, 'tanzil-uthmani-v1.1', 2, 177, 'لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱلْمَلَٰٓئِكَةِ وَٱلْكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَٰهَدُوا۟ وَٱلصَّٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ أُو۟لَٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'a17e5f11345ba2687aefd76698e8ad3fc5af77e37def40f3b0bce0222bf76a1b', 'لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱلْمَلَٰٓئِكَةِ وَٱلْكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَٰهَدُوا۟ وَٱلصَّٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ أُو۟لَٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'a17e5f11345ba2687aefd76698e8ad3fc5af77e37def40f3b0bce0222bf76a1b', 'a17e5f11345ba2687aefd76698e8ad3fc5af77e37def40f3b0bce0222bf76a1b', NULL, 'ليس البر ان تولوا وجوهكم قبل المشرق والمغرب ولكن البر من ءامن بالله واليوم الاخر والملئكه والكتب والنبين وءاتي المال علي حبه ذوي القربي واليتمي والمسكين وابن السبيل والسائلين وفي الرقاب واقام الصلوه وءاتي الزكوه والموفون بعهدهم اذا عهدوا والصبرين في الباساء والضراء وحين الباس اولئك الذين صدقوا واولئك هم المتقون', 2, 3, 11, 1, 1, 27, false, NULL),
    (185, 'tanzil-uthmani-v1.1', 2, 178, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَٰنٍ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', '2196335107cc5cd9baa4f8e496a4765100f0bad307aadd7896b9b3fba0b14923', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَٰنٍ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', '2196335107cc5cd9baa4f8e496a4765100f0bad307aadd7896b9b3fba0b14923', '2196335107cc5cd9baa4f8e496a4765100f0bad307aadd7896b9b3fba0b14923', NULL, 'يايها الذين ءامنوا كتب عليكم القصاص في القتلي الحر بالحر والعبد بالعبد والانثي بالانثي فمن عفي له من اخيه شيء فاتباع بالمعروف واداء اليه باحسن ذلك تخفيف من ربكم ورحمه فمن اعتدي بعد ذلك فله عذاب اليم', 2, 3, 11, 1, 1, 27, false, NULL),
    (186, 'tanzil-uthmani-v1.1', 2, 179, 'وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تَتَّقُونَ', '1aa1096608e869c460c70f2d29f1b8b77f36bc7e6be962295fcd0f3cff9f8db6', 'وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تَتَّقُونَ', '1aa1096608e869c460c70f2d29f1b8b77f36bc7e6be962295fcd0f3cff9f8db6', '1aa1096608e869c460c70f2d29f1b8b77f36bc7e6be962295fcd0f3cff9f8db6', NULL, 'ولكم في القصاص حيوه ياولي الالبب لعلكم تتقون', 2, 3, 11, 1, 1, 27, false, NULL),
    (187, 'tanzil-uthmani-v1.1', 2, 180, 'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ', '335269f34dce51b75b52fb141a300098b9bc75c0d942322f8983ae88fe617396', 'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ', '335269f34dce51b75b52fb141a300098b9bc75c0d942322f8983ae88fe617396', '335269f34dce51b75b52fb141a300098b9bc75c0d942322f8983ae88fe617396', NULL, 'كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصيه للولدين والاقربين بالمعروف حقا علي المتقين', 2, 3, 11, 1, 1, 27, false, NULL),
    (188, 'tanzil-uthmani-v1.1', 2, 181, 'فَمَنۢ بَدَّلَهُۥ بَعْدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '8a180610b0038a18cd42426905bbb7f66ff7b81f78225a10c329c1c1a7cf7b29', 'فَمَنۢ بَدَّلَهُۥ بَعْدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '8a180610b0038a18cd42426905bbb7f66ff7b81f78225a10c329c1c1a7cf7b29', '8a180610b0038a18cd42426905bbb7f66ff7b81f78225a10c329c1c1a7cf7b29', NULL, 'فمن بدله بعد ما سمعه فانما اثمه علي الذين يبدلونه ان الله سميع عليم', 2, 3, 11, 1, 1, 27, false, NULL),
    (189, 'tanzil-uthmani-v1.1', 2, 182, 'فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'a7580686fb84d222f9e780274f68c8814804a80a554e7a1acd3e2d12d9d5a705', 'فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'a7580686fb84d222f9e780274f68c8814804a80a554e7a1acd3e2d12d9d5a705', 'a7580686fb84d222f9e780274f68c8814804a80a554e7a1acd3e2d12d9d5a705', NULL, 'فمن خاف من موص جنفا او اثما فاصلح بينهم فلا اثم عليه ان الله غفور رحيم', 2, 3, 11, 1, 1, 28, false, NULL),
    (190, 'tanzil-uthmani-v1.1', 2, 183, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', '7d9115842a97092adabbb78b14c0be34e8c0160ef2bc55903db4300fe9d2883d', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', '7d9115842a97092adabbb78b14c0be34e8c0160ef2bc55903db4300fe9d2883d', '7d9115842a97092adabbb78b14c0be34e8c0160ef2bc55903db4300fe9d2883d', NULL, 'يايها الذين ءامنوا كتب عليكم الصيام كما كتب علي الذين من قبلكم لعلكم تتقون', 2, 3, 11, 1, 1, 28, false, NULL),
    (191, 'tanzil-uthmani-v1.1', 2, 184, 'أَيَّامًا مَّعْدُودَٰتٍ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '1c314b5389c011c2639a951641deabc8ee4fea4a995ae6fcaba7115a68144971', 'أَيَّامًا مَّعْدُودَٰتٍ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '1c314b5389c011c2639a951641deabc8ee4fea4a995ae6fcaba7115a68144971', '1c314b5389c011c2639a951641deabc8ee4fea4a995ae6fcaba7115a68144971', NULL, 'اياما معدودت فمن كان منكم مريضا او علي سفر فعده من ايام اخر وعلي الذين يطيقونه فديه طعام مسكين فمن تطوع خيرا فهو خير له وان تصوموا خير لكم ان كنتم تعلمون', 2, 3, 11, 1, 1, 28, false, NULL),
    (192, 'tanzil-uthmani-v1.1', 2, 185, 'شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', 'e17f77e4d2198af285776e1cbcf24fb70ca344be4c7d4848ef49a87b689119ca', 'شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', 'e17f77e4d2198af285776e1cbcf24fb70ca344be4c7d4848ef49a87b689119ca', 'e17f77e4d2198af285776e1cbcf24fb70ca344be4c7d4848ef49a87b689119ca', NULL, 'شهر رمضان الذي انزل فيه القرءان هدي للناس وبينت من الهدي والفرقان فمن شهد منكم الشهر فليصمه ومن كان مريضا او علي سفر فعده من ايام اخر يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العده ولتكبروا الله علي ما هديكم ولعلكم تشكرون', 2, 3, 11, 1, 1, 28, false, NULL),
    (193, 'tanzil-uthmani-v1.1', 2, 186, 'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ', '597cdf7ba92693ed18b41e2e7c44ba8ee7e310a4e495fef022c07316f7f825c2', 'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ', '597cdf7ba92693ed18b41e2e7c44ba8ee7e310a4e495fef022c07316f7f825c2', '597cdf7ba92693ed18b41e2e7c44ba8ee7e310a4e495fef022c07316f7f825c2', NULL, 'واذا سالك عبادي عني فاني قريب اجيب دعوه الداع اذا دعان فليستجيبوا لي وليؤمنوا بي لعلهم يرشدون', 2, 3, 11, 1, 1, 28, false, NULL),
    (194, 'tanzil-uthmani-v1.1', 2, 187, 'أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ فَٱلْـَٰٔنَ بَٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِى ٱلْمَسَٰجِدِ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ', '4cd26f390245f1583e837816cd9ba38a15f917c621db111bf310a4d2aa6f3fe7', 'أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ فَٱلْـَٰٔنَ بَٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِى ٱلْمَسَٰجِدِ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ', '4cd26f390245f1583e837816cd9ba38a15f917c621db111bf310a4d2aa6f3fe7', '4cd26f390245f1583e837816cd9ba38a15f917c621db111bf310a4d2aa6f3fe7', NULL, 'احل لكم ليله الصيام الرفث الي نسائكم هن لباس لكم وانتم لباس لهن علم الله انكم كنتم تختانون انفسكم فتاب عليكم وعفا عنكم فالن بشروهن وابتغوا ما كتب الله لكم وكلوا واشربوا حتي يتبين لكم الخيط الابيض من الخيط الاسود من الفجر ثم اتموا الصيام الي اليل ولا تبشروهن وانتم عكفون في المسجد تلك حدود الله فلا تقربوها كذلك يبين الله ءايته للناس لعلهم يتقون', 2, 3, 11, 1, 1, 29, false, NULL),
    (195, 'tanzil-uthmani-v1.1', 2, 188, 'وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', '6e13b5129a304adc9464fd16a9b3fb97403fb3b7156a50d44e607aecd48f49dc', 'وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', '6e13b5129a304adc9464fd16a9b3fb97403fb3b7156a50d44e607aecd48f49dc', '6e13b5129a304adc9464fd16a9b3fb97403fb3b7156a50d44e607aecd48f49dc', NULL, 'ولا تاكلوا امولكم بينكم بالبطل وتدلوا بها الي الحكام لتاكلوا فريقا من امول الناس بالاثم وانتم تعلمون', 2, 3, 11, 1, 1, 29, false, NULL),
    (196, 'tanzil-uthmani-v1.1', 2, 189, 'يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', '0f4d4cba39071a3d650780d26c0b7affa79f4f9b2624f8fe8fabad99514c6ac1', 'يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', '0f4d4cba39071a3d650780d26c0b7affa79f4f9b2624f8fe8fabad99514c6ac1', '0f4d4cba39071a3d650780d26c0b7affa79f4f9b2624f8fe8fabad99514c6ac1', NULL, 'يسلونك عن الاهله قل هي موقيت للناس والحج وليس البر بان تاتوا البيوت من ظهورها ولكن البر من اتقي واتوا البيوت من ابوبها واتقوا الله لعلكم تفلحون', 2, 3, 12, 1, 1, 29, false, NULL),
    (197, 'tanzil-uthmani-v1.1', 2, 190, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', '6f01f7620fe1202a3422eb968b23960d075b77d6c343c4b9658399567bfd8bcf', 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', '6f01f7620fe1202a3422eb968b23960d075b77d6c343c4b9658399567bfd8bcf', '6f01f7620fe1202a3422eb968b23960d075b77d6c343c4b9658399567bfd8bcf', NULL, 'وقتلوا في سبيل الله الذين يقتلونكم ولا تعتدوا ان الله لا يحب المعتدين', 2, 3, 12, 1, 1, 29, false, NULL),
    (198, 'tanzil-uthmani-v1.1', 2, 191, 'وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ وَلَا تُقَٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمْ فِيهِ فَإِن قَٰتَلُوكُمْ فَٱقْتُلُوهُمْ كَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'cd645a405c5e0000c579040fb65919964a651303a8510c9efef510d016637181', 'وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ وَلَا تُقَٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمْ فِيهِ فَإِن قَٰتَلُوكُمْ فَٱقْتُلُوهُمْ كَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'cd645a405c5e0000c579040fb65919964a651303a8510c9efef510d016637181', 'cd645a405c5e0000c579040fb65919964a651303a8510c9efef510d016637181', NULL, 'واقتلوهم حيث ثقفتموهم واخرجوهم من حيث اخرجوكم والفتنه اشد من القتل ولا تقتلوهم عند المسجد الحرام حتي يقتلوكم فيه فان قتلوكم فاقتلوهم كذلك جزاء الكفرين', 2, 3, 12, 1, 1, 30, false, NULL),
    (199, 'tanzil-uthmani-v1.1', 2, 192, 'فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'f248c265a59f9d03cec46a383b8bb55e666ebf0e3a037967025edad66247b44d', 'فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'f248c265a59f9d03cec46a383b8bb55e666ebf0e3a037967025edad66247b44d', 'f248c265a59f9d03cec46a383b8bb55e666ebf0e3a037967025edad66247b44d', NULL, 'فان انتهوا فان الله غفور رحيم', 2, 3, 12, 1, 1, 30, false, NULL),
    (200, 'tanzil-uthmani-v1.1', 2, 193, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ', '6ecb2f28adcb3a131e901b510b7294e52209a46d1b03601d6c11276dfcf9fb51', 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ', '6ecb2f28adcb3a131e901b510b7294e52209a46d1b03601d6c11276dfcf9fb51', '6ecb2f28adcb3a131e901b510b7294e52209a46d1b03601d6c11276dfcf9fb51', NULL, 'وقتلوهم حتي لا تكون فتنه ويكون الدين لله فان انتهوا فلا عدون الا علي الظلمين', 2, 3, 12, 1, 1, 30, false, NULL),
    (201, 'tanzil-uthmani-v1.1', 2, 194, 'ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَٰتُ قِصَاصٌ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', '24c64447bed0012310e8bae29c21fe0e3217dd447f4fd51d957869b1460b5cbc', 'ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَٰتُ قِصَاصٌ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', '24c64447bed0012310e8bae29c21fe0e3217dd447f4fd51d957869b1460b5cbc', '24c64447bed0012310e8bae29c21fe0e3217dd447f4fd51d957869b1460b5cbc', NULL, 'الشهر الحرام بالشهر الحرام والحرمت قصاص فمن اعتدي عليكم فاعتدوا عليه بمثل ما اعتدي عليكم واتقوا الله واعلموا ان الله مع المتقين', 2, 3, 12, 1, 1, 30, false, NULL),
    (202, 'tanzil-uthmani-v1.1', 2, 195, 'وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ وَأَحْسِنُوٓا۟ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', '86ac43fb2288be64c761fc01886d01e3e26af0f16d9588ed945ec128fcc31e9d', 'وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ وَأَحْسِنُوٓا۟ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', '86ac43fb2288be64c761fc01886d01e3e26af0f16d9588ed945ec128fcc31e9d', '86ac43fb2288be64c761fc01886d01e3e26af0f16d9588ed945ec128fcc31e9d', NULL, 'وانفقوا في سبيل الله ولا تلقوا بايديكم الي التهلكه واحسنوا ان الله يحب المحسنين', 2, 3, 12, 1, 1, 30, false, NULL),
    (203, 'tanzil-uthmani-v1.1', 2, 196, 'وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًى مِّن رَّأْسِهِۦ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'e28feef5b597811bf9a30bc0fccfa65ba8001c47b8a82c614606eae33c1f20a8', 'وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًى مِّن رَّأْسِهِۦ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'e28feef5b597811bf9a30bc0fccfa65ba8001c47b8a82c614606eae33c1f20a8', 'e28feef5b597811bf9a30bc0fccfa65ba8001c47b8a82c614606eae33c1f20a8', NULL, 'واتموا الحج والعمره لله فان احصرتم فما استيسر من الهدي ولا تحلقوا رءوسكم حتي يبلغ الهدي محله فمن كان منكم مريضا او به اذي من راسه ففديه من صيام او صدقه او نسك فاذا امنتم فمن تمتع بالعمره الي الحج فما استيسر من الهدي فمن لم يجد فصيام ثلثه ايام في الحج وسبعه اذا رجعتم تلك عشره كامله ذلك لمن لم يكن اهله حاضري المسجد الحرام واتقوا الله واعلموا ان الله شديد العقاب', 2, 3, 12, 1, 1, 30, false, NULL),
    (204, 'tanzil-uthmani-v1.1', 2, 197, 'ٱلْحَجُّ أَشْهُرٌ مَّعْلُومَٰتٌ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ يَعْلَمْهُ ٱللَّهُ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ وَٱتَّقُونِ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ', 'a50024f93c5e01cf4aeb29b48ad888ccd480063f07aacf485aa496dd6cd9960f', 'ٱلْحَجُّ أَشْهُرٌ مَّعْلُومَٰتٌ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ يَعْلَمْهُ ٱللَّهُ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ وَٱتَّقُونِ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ', 'a50024f93c5e01cf4aeb29b48ad888ccd480063f07aacf485aa496dd6cd9960f', 'a50024f93c5e01cf4aeb29b48ad888ccd480063f07aacf485aa496dd6cd9960f', NULL, 'الحج اشهر معلومت فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال في الحج وما تفعلوا من خير يعلمه الله وتزودوا فان خير الزاد التقوي واتقون ياولي الالبب', 2, 3, 12, 1, 1, 31, false, NULL),
    (205, 'tanzil-uthmani-v1.1', 2, 198, 'لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتٍ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ', '210312389b313e17723957ae611173ce17f714cfad0ce98b0b830f6f5728e7b9', 'لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتٍ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ', '210312389b313e17723957ae611173ce17f714cfad0ce98b0b830f6f5728e7b9', '210312389b313e17723957ae611173ce17f714cfad0ce98b0b830f6f5728e7b9', NULL, 'ليس عليكم جناح ان تبتغوا فضلا من ربكم فاذا افضتم من عرفت فاذكروا الله عند المشعر الحرام واذكروه كما هديكم وان كنتم من قبله لمن الضالين', 2, 3, 12, 1, 1, 31, false, NULL),
    (206, 'tanzil-uthmani-v1.1', 2, 199, 'ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '449e92412811446fa1c0727979be447ee0edd9b93ba28c2154c5d80012e64457', 'ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '449e92412811446fa1c0727979be447ee0edd9b93ba28c2154c5d80012e64457', '449e92412811446fa1c0727979be447ee0edd9b93ba28c2154c5d80012e64457', NULL, 'ثم افيضوا من حيث افاض الناس واستغفروا الله ان الله غفور رحيم', 2, 3, 12, 1, 1, 31, false, NULL),
    (207, 'tanzil-uthmani-v1.1', 2, 200, 'فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًا فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَٰقٍ', 'f937e96db3b4e8c3ac456bd07e74c3627ce50b3e51fcd05563f24d5481ce38b4', 'فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًا فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَٰقٍ', 'f937e96db3b4e8c3ac456bd07e74c3627ce50b3e51fcd05563f24d5481ce38b4', 'f937e96db3b4e8c3ac456bd07e74c3627ce50b3e51fcd05563f24d5481ce38b4', NULL, 'فاذا قضيتم منسككم فاذكروا الله كذكركم ءاباءكم او اشد ذكرا فمن الناس من يقول ربنا ءاتنا في الدنيا وما له في الاخره من خلق', 2, 3, 12, 1, 1, 31, false, NULL),
    (208, 'tanzil-uthmani-v1.1', 2, 201, 'وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ', '1869efce969543db13d292ffa547575bed42dc526d1e5102cb5d7093468af822', 'وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ', '1869efce969543db13d292ffa547575bed42dc526d1e5102cb5d7093468af822', '1869efce969543db13d292ffa547575bed42dc526d1e5102cb5d7093468af822', NULL, 'ومنهم من يقول ربنا ءاتنا في الدنيا حسنه وفي الاخره حسنه وقنا عذاب النار', 2, 3, 12, 1, 1, 31, false, NULL),
    (209, 'tanzil-uthmani-v1.1', 2, 202, 'أُو۟لَٰٓئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا۟ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', '9466baf8623c6d28f7ecf45b683f29a1544adc65fbb4e3fe53372713a0ecbbf9', 'أُو۟لَٰٓئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا۟ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', '9466baf8623c6d28f7ecf45b683f29a1544adc65fbb4e3fe53372713a0ecbbf9', '9466baf8623c6d28f7ecf45b683f29a1544adc65fbb4e3fe53372713a0ecbbf9', NULL, 'اولئك لهم نصيب مما كسبوا والله سريع الحساب', 2, 3, 12, 1, 1, 31, false, NULL),
    (210, 'tanzil-uthmani-v1.1', 2, 203, 'وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ لِمَنِ ٱتَّقَىٰ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ', '68e551e43fba5ec4019ce5467a90af68b3ed9b3cf78cbdebe71d1cbb1ad32321', 'وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ لِمَنِ ٱتَّقَىٰ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ', '68e551e43fba5ec4019ce5467a90af68b3ed9b3cf78cbdebe71d1cbb1ad32321', '68e551e43fba5ec4019ce5467a90af68b3ed9b3cf78cbdebe71d1cbb1ad32321', NULL, 'واذكروا الله في ايام معدودت فمن تعجل في يومين فلا اثم عليه ومن تاخر فلا اثم عليه لمن اتقي واتقوا الله واعلموا انكم اليه تحشرون', 2, 4, 13, 1, 1, 32, false, NULL),
    (211, 'tanzil-uthmani-v1.1', 2, 204, 'وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ', 'f617cbee03f02bb564994f1cacbf19fc218dc0aca633fb052c09cbea3bedad27', 'وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ', 'f617cbee03f02bb564994f1cacbf19fc218dc0aca633fb052c09cbea3bedad27', 'f617cbee03f02bb564994f1cacbf19fc218dc0aca633fb052c09cbea3bedad27', NULL, 'ومن الناس من يعجبك قوله في الحيوه الدنيا ويشهد الله علي ما في قلبه وهو الد الخصام', 2, 4, 13, 1, 1, 32, false, NULL),
    (212, 'tanzil-uthmani-v1.1', 2, 205, 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ', '912821ecfbe18dfdd15f33df13f8d18747ccf6d3d0200ecc9e32211a8e808c81', 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ', '912821ecfbe18dfdd15f33df13f8d18747ccf6d3d0200ecc9e32211a8e808c81', '912821ecfbe18dfdd15f33df13f8d18747ccf6d3d0200ecc9e32211a8e808c81', NULL, 'واذا تولي سعي في الارض ليفسد فيها ويهلك الحرث والنسل والله لا يحب الفساد', 2, 4, 13, 1, 1, 32, false, NULL),
    (213, 'tanzil-uthmani-v1.1', 2, 206, 'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ فَحَسْبُهُۥ جَهَنَّمُ وَلَبِئْسَ ٱلْمِهَادُ', '5f391a769f8f7b66037a648275a6c3823b0a6d30c6db68b07c1755a07cf00167', 'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ فَحَسْبُهُۥ جَهَنَّمُ وَلَبِئْسَ ٱلْمِهَادُ', '5f391a769f8f7b66037a648275a6c3823b0a6d30c6db68b07c1755a07cf00167', '5f391a769f8f7b66037a648275a6c3823b0a6d30c6db68b07c1755a07cf00167', NULL, 'واذا قيل له اتق الله اخذته العزه بالاثم فحسبه جهنم ولبئس المهاد', 2, 4, 13, 1, 1, 32, false, NULL),
    (214, 'tanzil-uthmani-v1.1', 2, 207, 'وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', '39727b0e24bd38ff56d0645f4edc104bb5100acb09c444530a3ec658ad35e4c2', 'وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', '39727b0e24bd38ff56d0645f4edc104bb5100acb09c444530a3ec658ad35e4c2', '39727b0e24bd38ff56d0645f4edc104bb5100acb09c444530a3ec658ad35e4c2', NULL, 'ومن الناس من يشري نفسه ابتغاء مرضات الله والله رءوف بالعباد', 2, 4, 13, 1, 1, 32, false, NULL),
    (215, 'tanzil-uthmani-v1.1', 2, 208, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةً وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'a4b478a4f5952fb5508526fc3478cb1135512d0557291de7429b9592e9feec3c', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةً وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'a4b478a4f5952fb5508526fc3478cb1135512d0557291de7429b9592e9feec3c', 'a4b478a4f5952fb5508526fc3478cb1135512d0557291de7429b9592e9feec3c', NULL, 'يايها الذين ءامنوا ادخلوا في السلم كافه ولا تتبعوا خطوت الشيطن انه لكم عدو مبين', 2, 4, 13, 1, 1, 32, false, NULL),
    (216, 'tanzil-uthmani-v1.1', 2, 209, 'فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '2a7104bbf5f3f128734efb49c47f72d238f3d18d6f792d21577724cf679fb69e', 'فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '2a7104bbf5f3f128734efb49c47f72d238f3d18d6f792d21577724cf679fb69e', '2a7104bbf5f3f128734efb49c47f72d238f3d18d6f792d21577724cf679fb69e', NULL, 'فان زللتم من بعد ما جاءتكم البينت فاعلموا ان الله عزيز حكيم', 2, 4, 13, 1, 1, 32, false, NULL),
    (217, 'tanzil-uthmani-v1.1', 2, 210, 'هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍ مِّنَ ٱلْغَمَامِ وَٱلْمَلَٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '0c245e1cb100f06001671719b337955fe907c22bfc346a24d9d235c6fbf90bf0', 'هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍ مِّنَ ٱلْغَمَامِ وَٱلْمَلَٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '0c245e1cb100f06001671719b337955fe907c22bfc346a24d9d235c6fbf90bf0', '0c245e1cb100f06001671719b337955fe907c22bfc346a24d9d235c6fbf90bf0', NULL, 'هل ينظرون الا ان ياتيهم الله في ظلل من الغمام والملئكه وقضي الامر والي الله ترجع الامور', 2, 4, 13, 1, 1, 32, false, NULL),
    (218, 'tanzil-uthmani-v1.1', 2, 211, 'سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'b921f5334a62a1a903690db9c84c4570799f0ddb8ea17970b74334102000fbcb', 'سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'b921f5334a62a1a903690db9c84c4570799f0ddb8ea17970b74334102000fbcb', 'b921f5334a62a1a903690db9c84c4570799f0ddb8ea17970b74334102000fbcb', NULL, 'سل بني اسرءيل كم ءاتينهم من ءايه بينه ومن يبدل نعمه الله من بعد ما جاءته فان الله شديد العقاب', 2, 4, 13, 1, 1, 33, false, NULL),
    (219, 'tanzil-uthmani-v1.1', 2, 212, 'زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', '81bfb77751be21df9354e1a2425e5589af50172e316b76f8264e9535743cc9c4', 'زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', '81bfb77751be21df9354e1a2425e5589af50172e316b76f8264e9535743cc9c4', '81bfb77751be21df9354e1a2425e5589af50172e316b76f8264e9535743cc9c4', NULL, 'زين للذين كفروا الحيوه الدنيا ويسخرون من الذين ءامنوا والذين اتقوا فوقهم يوم القيمه والله يرزق من يشاء بغير حساب', 2, 4, 13, 1, 1, 33, false, NULL),
    (220, 'tanzil-uthmani-v1.1', 2, 213, 'كَانَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ بَغْيًۢا بَيْنَهُمْ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '003bd1f5011bfcfa5b1356672d312c5d225e4d12b089c34a0b955203be94b82e', 'كَانَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ بَغْيًۢا بَيْنَهُمْ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '003bd1f5011bfcfa5b1356672d312c5d225e4d12b089c34a0b955203be94b82e', '003bd1f5011bfcfa5b1356672d312c5d225e4d12b089c34a0b955203be94b82e', NULL, 'كان الناس امه وحده فبعث الله النبين مبشرين ومنذرين وانزل معهم الكتب بالحق ليحكم بين الناس فيما اختلفوا فيه وما اختلف فيه الا الذين اوتوه من بعد ما جاءتهم البينت بغيا بينهم فهدي الله الذين ءامنوا لما اختلفوا فيه من الحق باذنه والله يهدي من يشاء الي صرط مستقيم', 2, 4, 13, 1, 1, 33, false, NULL),
    (221, 'tanzil-uthmani-v1.1', 2, 214, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌ', '54cf1170ee408e64b106c140a4eaaa760179c3736400b3f825478e9371bbba40', 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌ', '54cf1170ee408e64b106c140a4eaaa760179c3736400b3f825478e9371bbba40', '54cf1170ee408e64b106c140a4eaaa760179c3736400b3f825478e9371bbba40', NULL, 'ام حسبتم ان تدخلوا الجنه ولما ياتكم مثل الذين خلوا من قبلكم مستهم الباساء والضراء وزلزلوا حتي يقول الرسول والذين ءامنوا معه متي نصر الله الا ان نصر الله قريب', 2, 4, 13, 1, 1, 33, false, NULL),
    (222, 'tanzil-uthmani-v1.1', 2, 215, 'يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '5c701ff9189b07746ef418de35fb61a2ec349a43699579745654abbb12701b38', 'يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '5c701ff9189b07746ef418de35fb61a2ec349a43699579745654abbb12701b38', '5c701ff9189b07746ef418de35fb61a2ec349a43699579745654abbb12701b38', NULL, 'يسلونك ماذا ينفقون قل ما انفقتم من خير فللولدين والاقربين واليتمي والمسكين وابن السبيل وما تفعلوا من خير فان الله به عليم', 2, 4, 13, 1, 1, 33, false, NULL),
    (223, 'tanzil-uthmani-v1.1', 2, 216, 'كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَهُوَ خَيْرٌ لَّكُمْ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًٔا وَهُوَ شَرٌّ لَّكُمْ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '02fec7ada3465e04c6ff96a6c93a3711d10b153109ac8d39ea5dcf733e2fcc55', 'كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَهُوَ خَيْرٌ لَّكُمْ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًٔا وَهُوَ شَرٌّ لَّكُمْ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '02fec7ada3465e04c6ff96a6c93a3711d10b153109ac8d39ea5dcf733e2fcc55', '02fec7ada3465e04c6ff96a6c93a3711d10b153109ac8d39ea5dcf733e2fcc55', NULL, 'كتب عليكم القتال وهو كره لكم وعسي ان تكرهوا شيا وهو خير لكم وعسي ان تحبوا شيا وهو شر لكم والله يعلم وانتم لا تعلمون', 2, 4, 13, 1, 1, 34, false, NULL),
    (224, 'tanzil-uthmani-v1.1', 2, 217, 'يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَٰعُوا۟ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌ فَأُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'b9e57bd31e02a9ccbfacead32172002346109380998e795de86d516ed70f0a17', 'يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَٰعُوا۟ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌ فَأُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'b9e57bd31e02a9ccbfacead32172002346109380998e795de86d516ed70f0a17', 'b9e57bd31e02a9ccbfacead32172002346109380998e795de86d516ed70f0a17', NULL, 'يسلونك عن الشهر الحرام قتال فيه قل قتال فيه كبير وصد عن سبيل الله وكفر به والمسجد الحرام واخراج اهله منه اكبر عند الله والفتنه اكبر من القتل ولا يزالون يقتلونكم حتي يردوكم عن دينكم ان استطعوا ومن يرتدد منكم عن دينه فيمت وهو كافر فاولئك حبطت اعملهم في الدنيا والاخره واولئك اصحب النار هم فيها خلدون', 2, 4, 13, 1, 1, 34, false, NULL),
    (225, 'tanzil-uthmani-v1.1', 2, 218, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'dbe1e85a280acaae665eca68a222324e13484ee2d7e1ebcb87a792901d12a487', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'dbe1e85a280acaae665eca68a222324e13484ee2d7e1ebcb87a792901d12a487', 'dbe1e85a280acaae665eca68a222324e13484ee2d7e1ebcb87a792901d12a487', NULL, 'ان الذين ءامنوا والذين هاجروا وجهدوا في سبيل الله اولئك يرجون رحمت الله والله غفور رحيم', 2, 4, 13, 1, 1, 34, false, NULL),
    (226, 'tanzil-uthmani-v1.1', 2, 219, 'يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ قُلْ فِيهِمَآ إِثْمٌ كَبِيرٌ وَمَنَٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', '6e66f481f8257a0a4fdedf7cbbe118cc733bfe8051b134852e1c01c0e20f5464', 'يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ قُلْ فِيهِمَآ إِثْمٌ كَبِيرٌ وَمَنَٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', '6e66f481f8257a0a4fdedf7cbbe118cc733bfe8051b134852e1c01c0e20f5464', '6e66f481f8257a0a4fdedf7cbbe118cc733bfe8051b134852e1c01c0e20f5464', NULL, 'يسلونك عن الخمر والميسر قل فيهما اثم كبير ومنفع للناس واثمهما اكبر من نفعهما ويسلونك ماذا ينفقون قل العفو كذلك يبين الله لكم الايت لعلكم تتفكرون', 2, 4, 14, 1, 1, 34, false, NULL),
    (227, 'tanzil-uthmani-v1.1', 2, 220, 'فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَٰمَىٰ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'f048819b1b45bc7b127d59148ffb32eb7f857c862c2f85b81a09450638942c38', 'فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَٰمَىٰ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'f048819b1b45bc7b127d59148ffb32eb7f857c862c2f85b81a09450638942c38', 'f048819b1b45bc7b127d59148ffb32eb7f857c862c2f85b81a09450638942c38', NULL, 'في الدنيا والاخره ويسلونك عن اليتمي قل اصلاح لهم خير وان تخالطوهم فاخونكم والله يعلم المفسد من المصلح ولو شاء الله لاعنتكم ان الله عزيز حكيم', 2, 4, 14, 1, 1, 35, false, NULL),
    (228, 'tanzil-uthmani-v1.1', 2, 221, 'وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَٰتِ حَتَّىٰ يُؤْمِنَّ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ أُو۟لَٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', '96942a5d872114876f85f6bb00277dd8200c79ace9d3fc016d330418b530811f', 'وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَٰتِ حَتَّىٰ يُؤْمِنَّ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ أُو۟لَٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', '96942a5d872114876f85f6bb00277dd8200c79ace9d3fc016d330418b530811f', '96942a5d872114876f85f6bb00277dd8200c79ace9d3fc016d330418b530811f', NULL, 'ولا تنكحوا المشركت حتي يؤمن ولامه مؤمنه خير من مشركه ولو اعجبتكم ولا تنكحوا المشركين حتي يؤمنوا ولعبد مؤمن خير من مشرك ولو اعجبكم اولئك يدعون الي النار والله يدعوا الي الجنه والمغفره باذنه ويبين ءايته للناس لعلهم يتذكرون', 2, 4, 14, 1, 1, 35, false, NULL),
    (229, 'tanzil-uthmani-v1.1', 2, 222, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', '99e56ab32619a2caa39c68340993ed4b28d132204f1ef45f19651ca69c9e8b43', 'وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', '99e56ab32619a2caa39c68340993ed4b28d132204f1ef45f19651ca69c9e8b43', '99e56ab32619a2caa39c68340993ed4b28d132204f1ef45f19651ca69c9e8b43', NULL, 'ويسلونك عن المحيض قل هو اذي فاعتزلوا النساء في المحيض ولا تقربوهن حتي يطهرن فاذا تطهرن فاتوهن من حيث امركم الله ان الله يحب التوبين ويحب المتطهرين', 2, 4, 14, 1, 1, 35, false, NULL),
    (230, 'tanzil-uthmani-v1.1', 2, 223, 'نِسَآؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ وَقَدِّمُوا۟ لِأَنفُسِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَٰقُوهُ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '875e046d2f99a1453018ea45404cecfce820524e2ef4526171672cf5baf267b2', 'نِسَآؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ وَقَدِّمُوا۟ لِأَنفُسِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَٰقُوهُ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '875e046d2f99a1453018ea45404cecfce820524e2ef4526171672cf5baf267b2', '875e046d2f99a1453018ea45404cecfce820524e2ef4526171672cf5baf267b2', NULL, 'نساؤكم حرث لكم فاتوا حرثكم اني شئتم وقدموا لانفسكم واتقوا الله واعلموا انكم ملقوه وبشر المؤمنين', 2, 4, 14, 1, 1, 35, false, NULL),
    (231, 'tanzil-uthmani-v1.1', 2, 224, 'وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةً لِّأَيْمَٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'd2811824b7b9e276d4af9069cb6cd96c3d36d5347e82ed1c6e65d4f2fb481b94', 'وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةً لِّأَيْمَٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'd2811824b7b9e276d4af9069cb6cd96c3d36d5347e82ed1c6e65d4f2fb481b94', 'd2811824b7b9e276d4af9069cb6cd96c3d36d5347e82ed1c6e65d4f2fb481b94', NULL, 'ولا تجعلوا الله عرضه لايمنكم ان تبروا وتتقوا وتصلحوا بين الناس والله سميع عليم', 2, 4, 14, 1, 1, 35, false, NULL),
    (232, 'tanzil-uthmani-v1.1', 2, 225, 'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ وَٱللَّهُ غَفُورٌ حَلِيمٌ', '1e06d77e3f64a31add18bdcbbac305ee0634333627b53881b7937b37fefe1252', 'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ وَٱللَّهُ غَفُورٌ حَلِيمٌ', '1e06d77e3f64a31add18bdcbbac305ee0634333627b53881b7937b37fefe1252', '1e06d77e3f64a31add18bdcbbac305ee0634333627b53881b7937b37fefe1252', NULL, 'لا يؤاخذكم الله باللغو في ايمنكم ولكن يؤاخذكم بما كسبت قلوبكم والله غفور حليم', 2, 4, 14, 1, 1, 36, false, NULL),
    (233, 'tanzil-uthmani-v1.1', 2, 226, 'لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '3c372478315c0972478cf5799e409601aac79145b49d4f62af235f00ddcaa452', 'لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '3c372478315c0972478cf5799e409601aac79145b49d4f62af235f00ddcaa452', '3c372478315c0972478cf5799e409601aac79145b49d4f62af235f00ddcaa452', NULL, 'للذين يؤلون من نسائهم تربص اربعه اشهر فان فاءو فان الله غفور رحيم', 2, 4, 14, 1, 1, 36, false, NULL),
    (234, 'tanzil-uthmani-v1.1', 2, 227, 'وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '1aee654d9050518e62c95f524f7ad261bd628b2cd2d62ab3321165ab0762840b', 'وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '1aee654d9050518e62c95f524f7ad261bd628b2cd2d62ab3321165ab0762840b', '1aee654d9050518e62c95f524f7ad261bd628b2cd2d62ab3321165ab0762840b', NULL, 'وان عزموا الطلق فان الله سميع عليم', 2, 4, 14, 1, 1, 36, false, NULL),
    (235, 'tanzil-uthmani-v1.1', 2, 228, 'وَٱلْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٍ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَٰحًا وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'f1b93c8cc8ef6a77490ac30dea990733934dafcb8820e7aa588309ed0b958c2e', 'وَٱلْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٍ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَٰحًا وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'f1b93c8cc8ef6a77490ac30dea990733934dafcb8820e7aa588309ed0b958c2e', 'f1b93c8cc8ef6a77490ac30dea990733934dafcb8820e7aa588309ed0b958c2e', NULL, 'والمطلقت يتربصن بانفسهن ثلثه قروء ولا يحل لهن ان يكتمن ما خلق الله في ارحامهن ان كن يؤمن بالله واليوم الاخر وبعولتهن احق بردهن في ذلك ان ارادوا اصلحا ولهن مثل الذي عليهن بالمعروف وللرجال عليهن درجه والله عزيز حكيم', 2, 4, 14, 1, 1, 36, false, NULL),
    (236, 'tanzil-uthmani-v1.1', 2, 229, 'ٱلطَّلَٰقُ مَرَّتَانِ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَٰنٍ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', '140fb7e80d7a225b778ce50604c5f03c23f1a45050304d88dc2f9881d6a2c110', 'ٱلطَّلَٰقُ مَرَّتَانِ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَٰنٍ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', '140fb7e80d7a225b778ce50604c5f03c23f1a45050304d88dc2f9881d6a2c110', '140fb7e80d7a225b778ce50604c5f03c23f1a45050304d88dc2f9881d6a2c110', NULL, 'الطلق مرتان فامساك بمعروف او تسريح باحسن ولا يحل لكم ان تاخذوا مما ءاتيتموهن شيا الا ان يخافا الا يقيما حدود الله فان خفتم الا يقيما حدود الله فلا جناح عليهما فيما افتدت به تلك حدود الله فلا تعتدوها ومن يتعد حدود الله فاولئك هم الظلمون', 2, 4, 14, 1, 1, 36, false, NULL),
    (237, 'tanzil-uthmani-v1.1', 2, 230, 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ', 'c95bd0bbb1ac97c18082a27301e65cfa313e2c5e0d5e51a9e4df52419a7b90b2', 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ', 'c95bd0bbb1ac97c18082a27301e65cfa313e2c5e0d5e51a9e4df52419a7b90b2', 'c95bd0bbb1ac97c18082a27301e65cfa313e2c5e0d5e51a9e4df52419a7b90b2', NULL, 'فان طلقها فلا تحل له من بعد حتي تنكح زوجا غيره فان طلقها فلا جناح عليهما ان يتراجعا ان ظنا ان يقيما حدود الله وتلك حدود الله يبينها لقوم يعلمون', 2, 4, 14, 1, 1, 36, false, NULL),
    (238, 'tanzil-uthmani-v1.1', 2, 231, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا۟ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ وَلَا تَتَّخِذُوٓا۟ ءَايَٰتِ ٱللَّهِ هُزُوًا وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', '97f4df9fbd8180245932e2f6adc9e7becfddba7a003b88a7b3e0132eaa01c6b0', 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا۟ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ وَلَا تَتَّخِذُوٓا۟ ءَايَٰتِ ٱللَّهِ هُزُوًا وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', '97f4df9fbd8180245932e2f6adc9e7becfddba7a003b88a7b3e0132eaa01c6b0', '97f4df9fbd8180245932e2f6adc9e7becfddba7a003b88a7b3e0132eaa01c6b0', NULL, 'واذا طلقتم النساء فبلغن اجلهن فامسكوهن بمعروف او سرحوهن بمعروف ولا تمسكوهن ضرارا لتعتدوا ومن يفعل ذلك فقد ظلم نفسه ولا تتخذوا ءايت الله هزوا واذكروا نعمت الله عليكم وما انزل عليكم من الكتب والحكمه يعظكم به واتقوا الله واعلموا ان الله بكل شيء عليم', 2, 4, 14, 1, 1, 37, false, NULL),
    (239, 'tanzil-uthmani-v1.1', 2, 232, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'c154ac42f826e9e24d5ba28eb51fd39be932a19df711f8c59ccbdfb3b8dcb31d', 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'c154ac42f826e9e24d5ba28eb51fd39be932a19df711f8c59ccbdfb3b8dcb31d', 'c154ac42f826e9e24d5ba28eb51fd39be932a19df711f8c59ccbdfb3b8dcb31d', NULL, 'واذا طلقتم النساء فبلغن اجلهن فلا تعضلوهن ان ينكحن ازوجهن اذا ترضوا بينهم بالمعروف ذلك يوعظ به من كان منكم يؤمن بالله واليوم الاخر ذلكم ازكي لكم واطهر والله يعلم وانتم لا تعلمون', 2, 4, 14, 1, 1, 37, false, NULL),
    (240, 'tanzil-uthmani-v1.1', 2, 233, 'وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُۥ بِوَلَدِهِۦ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', '40a0997b2408f697f0b6af3c513c2f4203aa8dae38cc83079231b401d5cf5046', 'وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُۥ بِوَلَدِهِۦ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', '40a0997b2408f697f0b6af3c513c2f4203aa8dae38cc83079231b401d5cf5046', '40a0997b2408f697f0b6af3c513c2f4203aa8dae38cc83079231b401d5cf5046', NULL, 'والولدت يرضعن اولدهن حولين كاملين لمن اراد ان يتم الرضاعه وعلي المولود له رزقهن وكسوتهن بالمعروف لا تكلف نفس الا وسعها لا تضار ولده بولدها ولا مولود له بولده وعلي الوارث مثل ذلك فان ارادا فصالا عن تراض منهما وتشاور فلا جناح عليهما وان اردتم ان تسترضعوا اولدكم فلا جناح عليكم اذا سلمتم ما ءاتيتم بالمعروف واتقوا الله واعلموا ان الله بما تعملون بصير', 2, 4, 15, 1, 1, 37, false, NULL),
    (241, 'tanzil-uthmani-v1.1', 2, 234, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '2e80ec37773419fbede465c731ddb740033569b29e641a810d7750e5b07b5f3f', 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '2e80ec37773419fbede465c731ddb740033569b29e641a810d7750e5b07b5f3f', '2e80ec37773419fbede465c731ddb740033569b29e641a810d7750e5b07b5f3f', NULL, 'والذين يتوفون منكم ويذرون ازوجا يتربصن بانفسهن اربعه اشهر وعشرا فاذا بلغن اجلهن فلا جناح عليكم فيما فعلن في انفسهن بالمعروف والله بما تعملون خبير', 2, 4, 15, 1, 1, 38, false, NULL),
    (242, 'tanzil-uthmani-v1.1', 2, 235, 'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًا مَّعْرُوفًا وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَٰبُ أَجَلَهُۥ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', '8923aeaa7c45eeddb2d367f09b9bef3ce94b2d021dd41422c8fc879efbbef5c7', 'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًا مَّعْرُوفًا وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَٰبُ أَجَلَهُۥ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', '8923aeaa7c45eeddb2d367f09b9bef3ce94b2d021dd41422c8fc879efbbef5c7', '8923aeaa7c45eeddb2d367f09b9bef3ce94b2d021dd41422c8fc879efbbef5c7', NULL, 'ولا جناح عليكم فيما عرضتم به من خطبه النساء او اكننتم في انفسكم علم الله انكم ستذكرونهن ولكن لا تواعدوهن سرا الا ان تقولوا قولا معروفا ولا تعزموا عقده النكاح حتي يبلغ الكتب اجله واعلموا ان الله يعلم ما في انفسكم فاحذروه واعلموا ان الله غفور حليم', 2, 4, 15, 1, 1, 38, false, NULL),
    (243, 'tanzil-uthmani-v1.1', 2, 236, 'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَٰعًۢا بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُحْسِنِينَ', '77d6cc502771a80fc855088aa2da62a154c335093c7c9cedcf7d73b7b026130e', 'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَٰعًۢا بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُحْسِنِينَ', '77d6cc502771a80fc855088aa2da62a154c335093c7c9cedcf7d73b7b026130e', '77d6cc502771a80fc855088aa2da62a154c335093c7c9cedcf7d73b7b026130e', NULL, 'لا جناح عليكم ان طلقتم النساء ما لم تمسوهن او تفرضوا لهن فريضه ومتعوهن علي الموسع قدره وعلي المقتر قدره متعا بالمعروف حقا علي المحسنين', 2, 4, 15, 1, 1, 38, false, NULL),
    (244, 'tanzil-uthmani-v1.1', 2, 237, 'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', '8ef528b5627573a4c63f1eb4abebc95e6ad48c01ecea09ee3b994407dddf62e3', 'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', '8ef528b5627573a4c63f1eb4abebc95e6ad48c01ecea09ee3b994407dddf62e3', '8ef528b5627573a4c63f1eb4abebc95e6ad48c01ecea09ee3b994407dddf62e3', NULL, 'وان طلقتموهن من قبل ان تمسوهن وقد فرضتم لهن فريضه فنصف ما فرضتم الا ان يعفون او يعفوا الذي بيده عقده النكاح وان تعفوا اقرب للتقوي ولا تنسوا الفضل بينكم ان الله بما تعملون بصير', 2, 4, 15, 1, 1, 38, false, NULL),
    (245, 'tanzil-uthmani-v1.1', 2, 238, 'حَٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَٰنِتِينَ', 'b0241b63ea4d190b349337ba1b5f3318b19166fd4b1b1a3a8128fb278243f94f', 'حَٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَٰنِتِينَ', 'b0241b63ea4d190b349337ba1b5f3318b19166fd4b1b1a3a8128fb278243f94f', 'b0241b63ea4d190b349337ba1b5f3318b19166fd4b1b1a3a8128fb278243f94f', NULL, 'حفظوا علي الصلوت والصلوه الوسطي وقوموا لله قنتين', 2, 4, 15, 1, 1, 39, false, NULL),
    (246, 'tanzil-uthmani-v1.1', 2, 239, 'فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', '70b59b73018b0dd257594c79d072d45fba522caf1c3644cde6588ec00be161b7', 'فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', '70b59b73018b0dd257594c79d072d45fba522caf1c3644cde6588ec00be161b7', '70b59b73018b0dd257594c79d072d45fba522caf1c3644cde6588ec00be161b7', NULL, 'فان خفتم فرجالا او ركبانا فاذا امنتم فاذكروا الله كما علمكم ما لم تكونوا تعلمون', 2, 4, 15, 1, 1, 39, false, NULL),
    (247, 'tanzil-uthmani-v1.1', 2, 240, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا وَصِيَّةً لِّأَزْوَٰجِهِم مَّتَٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'a92962cb6acbaad7d5a08e0e09fa05684aad89ff5cf515a065d7af6da78584bd', 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا وَصِيَّةً لِّأَزْوَٰجِهِم مَّتَٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'a92962cb6acbaad7d5a08e0e09fa05684aad89ff5cf515a065d7af6da78584bd', 'a92962cb6acbaad7d5a08e0e09fa05684aad89ff5cf515a065d7af6da78584bd', NULL, 'والذين يتوفون منكم ويذرون ازوجا وصيه لازوجهم متعا الي الحول غير اخراج فان خرجن فلا جناح عليكم في ما فعلن في انفسهن من معروف والله عزيز حكيم', 2, 4, 15, 1, 1, 39, false, NULL),
    (248, 'tanzil-uthmani-v1.1', 2, 241, 'وَلِلْمُطَلَّقَٰتِ مَتَٰعٌۢ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ', '28e6244084e9987eacc388e1a68751cf1e86d92d34c6149ad81743e4c5704045', 'وَلِلْمُطَلَّقَٰتِ مَتَٰعٌۢ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ', '28e6244084e9987eacc388e1a68751cf1e86d92d34c6149ad81743e4c5704045', '28e6244084e9987eacc388e1a68751cf1e86d92d34c6149ad81743e4c5704045', NULL, 'وللمطلقت متع بالمعروف حقا علي المتقين', 2, 4, 15, 1, 1, 39, false, NULL),
    (249, 'tanzil-uthmani-v1.1', 2, 242, 'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '45d5d7ff02601625b154863754c4a63744ec9652ebbcd46d3ce72e739cfd8be8', 'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '45d5d7ff02601625b154863754c4a63744ec9652ebbcd46d3ce72e739cfd8be8', '45d5d7ff02601625b154863754c4a63744ec9652ebbcd46d3ce72e739cfd8be8', NULL, 'كذلك يبين الله لكم ءايته لعلكم تعقلون', 2, 4, 15, 1, 1, 39, false, NULL),
    (250, 'tanzil-uthmani-v1.1', 2, 243, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَٰهُمْ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'c977e025f6f6f9d46a6e6a2fde95b2deee35410557130a806e83166e2826d6a7', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَٰهُمْ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 'c977e025f6f6f9d46a6e6a2fde95b2deee35410557130a806e83166e2826d6a7', 'c977e025f6f6f9d46a6e6a2fde95b2deee35410557130a806e83166e2826d6a7', NULL, 'الم تر الي الذين خرجوا من ديرهم وهم الوف حذر الموت فقال لهم الله موتوا ثم احيهم ان الله لذو فضل علي الناس ولكن اكثر الناس لا يشكرون', 2, 4, 16, 1, 1, 39, false, NULL),
    (251, 'tanzil-uthmani-v1.1', 2, 244, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'a7115e55bbd8ea05dc4f46e8975bd08be1abbfcc5b2e99563d28f4574b97f0b3', 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'a7115e55bbd8ea05dc4f46e8975bd08be1abbfcc5b2e99563d28f4574b97f0b3', 'a7115e55bbd8ea05dc4f46e8975bd08be1abbfcc5b2e99563d28f4574b97f0b3', NULL, 'وقتلوا في سبيل الله واعلموا ان الله سميع عليم', 2, 4, 16, 1, 1, 39, false, NULL),
    (252, 'tanzil-uthmani-v1.1', 2, 245, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضْعَافًا كَثِيرَةً وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ', '9fe8fd0981e863c91c36a440778b01b21587a07bc4e08a63f3335af29e1ea65b', 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضْعَافًا كَثِيرَةً وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ', '9fe8fd0981e863c91c36a440778b01b21587a07bc4e08a63f3335af29e1ea65b', '9fe8fd0981e863c91c36a440778b01b21587a07bc4e08a63f3335af29e1ea65b', NULL, 'من ذا الذي يقرض الله قرضا حسنا فيضعفه له اضعافا كثيره والله يقبض ويبصط واليه ترجعون', 2, 4, 16, 1, 1, 39, false, NULL),
    (253, 'tanzil-uthmani-v1.1', 2, 246, 'أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًا نُّقَٰتِلْ فِى سَبِيلِ ٱللَّهِ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَٰتِلُوا۟ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَٰرِنَا وَأَبْنَآئِنَا فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًا مِّنْهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'a02a0a95717284418b8a1ca049caf7ca683c95574de6c9f5a8d6a64f46b4024d', 'أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًا نُّقَٰتِلْ فِى سَبِيلِ ٱللَّهِ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَٰتِلُوا۟ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَٰرِنَا وَأَبْنَآئِنَا فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًا مِّنْهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'a02a0a95717284418b8a1ca049caf7ca683c95574de6c9f5a8d6a64f46b4024d', 'a02a0a95717284418b8a1ca049caf7ca683c95574de6c9f5a8d6a64f46b4024d', NULL, 'الم تر الي الملا من بني اسرءيل من بعد موسي اذ قالوا لنبي لهم ابعث لنا ملكا نقتل في سبيل الله قال هل عسيتم ان كتب عليكم القتال الا تقتلوا قالوا وما لنا الا نقتل في سبيل الله وقد اخرجنا من ديرنا وابنائنا فلما كتب عليهم القتال تولوا الا قليلا منهم والله عليم بالظلمين', 2, 4, 16, 1, 1, 40, false, NULL),
    (254, 'tanzil-uthmani-v1.1', 2, 247, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ ٱلْمَالِ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةً فِى ٱلْعِلْمِ وَٱلْجِسْمِ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '9814094a1e3cfc759677100a731d42c79199678ed4c4f7b2ccd0607b02df44d8', 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ ٱلْمَالِ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةً فِى ٱلْعِلْمِ وَٱلْجِسْمِ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '9814094a1e3cfc759677100a731d42c79199678ed4c4f7b2ccd0607b02df44d8', '9814094a1e3cfc759677100a731d42c79199678ed4c4f7b2ccd0607b02df44d8', NULL, 'وقال لهم نبيهم ان الله قد بعث لكم طالوت ملكا قالوا اني يكون له الملك علينا ونحن احق بالملك منه ولم يؤت سعه من المال قال ان الله اصطفيه عليكم وزاده بسطه في العلم والجسم والله يؤتي ملكه من يشاء والله وسع عليم', 2, 4, 16, 1, 1, 40, false, NULL),
    (255, 'tanzil-uthmani-v1.1', 2, 248, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحْمِلُهُ ٱلْمَلَٰٓئِكَةُ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', '797f49f11fce4ec10ab787fd9301d5041156583cc08a53bbb8d9cd75cf0e0bda', 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحْمِلُهُ ٱلْمَلَٰٓئِكَةُ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', '797f49f11fce4ec10ab787fd9301d5041156583cc08a53bbb8d9cd75cf0e0bda', '797f49f11fce4ec10ab787fd9301d5041156583cc08a53bbb8d9cd75cf0e0bda', NULL, 'وقال لهم نبيهم ان ءايه ملكه ان ياتيكم التابوت فيه سكينه من ربكم وبقيه مما ترك ءال موسي وءال هرون تحمله الملئكه ان في ذلك لايه لكم ان كنتم مؤمنين', 2, 4, 16, 1, 1, 40, false, NULL),
    (256, 'tanzil-uthmani-v1.1', 2, 249, 'فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', '4df6f98f2a419aba07ad26f5735671cc14843396da1ab4c9267fece4dcc5bb89', 'فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', '4df6f98f2a419aba07ad26f5735671cc14843396da1ab4c9267fece4dcc5bb89', '4df6f98f2a419aba07ad26f5735671cc14843396da1ab4c9267fece4dcc5bb89', NULL, 'فلما فصل طالوت بالجنود قال ان الله مبتليكم بنهر فمن شرب منه فليس مني ومن لم يطعمه فانه مني الا من اغترف غرفه بيده فشربوا منه الا قليلا منهم فلما جاوزه هو والذين ءامنوا معه قالوا لا طاقه لنا اليوم بجالوت وجنوده قال الذين يظنون انهم ملقوا الله كم من فئه قليله غلبت فئه كثيره باذن الله والله مع الصبرين', 2, 4, 16, 1, 1, 41, false, NULL),
    (257, 'tanzil-uthmani-v1.1', 2, 250, 'وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '71721d197d9e76d278b4c50e06f2de9e5bedc5947bb6eba84cad9811d837509a', 'وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '71721d197d9e76d278b4c50e06f2de9e5bedc5947bb6eba84cad9811d837509a', '71721d197d9e76d278b4c50e06f2de9e5bedc5947bb6eba84cad9811d837509a', NULL, 'ولما برزوا لجالوت وجنوده قالوا ربنا افرغ علينا صبرا وثبت اقدامنا وانصرنا علي القوم الكفرين', 2, 4, 16, 1, 1, 41, false, NULL),
    (258, 'tanzil-uthmani-v1.1', 2, 251, 'فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ ٱلْأَرْضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَٰلَمِينَ', '1784681bede00a77104718d5bd8f13e0c15966ff87daaa0c25698d424bb2fa37', 'فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ ٱلْأَرْضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَٰلَمِينَ', '1784681bede00a77104718d5bd8f13e0c15966ff87daaa0c25698d424bb2fa37', '1784681bede00a77104718d5bd8f13e0c15966ff87daaa0c25698d424bb2fa37', NULL, 'فهزموهم باذن الله وقتل داود جالوت وءاتيه الله الملك والحكمه وعلمه مما يشاء ولولا دفع الله الناس بعضهم ببعض لفسدت الارض ولكن الله ذو فضل علي العلمين', 2, 4, 16, 1, 1, 41, false, NULL),
    (259, 'tanzil-uthmani-v1.1', 2, 252, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', 'a79480d195625e3992fc4de587f76805e2bb5b61960dac8e235339cd84c7a808', 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', 'a79480d195625e3992fc4de587f76805e2bb5b61960dac8e235339cd84c7a808', 'a79480d195625e3992fc4de587f76805e2bb5b61960dac8e235339cd84c7a808', NULL, 'تلك ءايت الله نتلوها عليك بالحق وانك لمن المرسلين', 2, 4, 16, 1, 1, 41, false, NULL),
    (260, 'tanzil-uthmani-v1.1', 2, 253, 'تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتٍ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ وَلَٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', '55800dbba9c0dd04837ed54afb4bff901b447ae430c5b381b4306926125c51df', 'تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتٍ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ وَلَٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', '55800dbba9c0dd04837ed54afb4bff901b447ae430c5b381b4306926125c51df', '55800dbba9c0dd04837ed54afb4bff901b447ae430c5b381b4306926125c51df', NULL, 'تلك الرسل فضلنا بعضهم علي بعض منهم من كلم الله ورفع بعضهم درجت وءاتينا عيسي ابن مريم البينت وايدنه بروح القدس ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينت ولكن اختلفوا فمنهم من ءامن ومنهم من كفر ولو شاء الله ما اقتتلوا ولكن الله يفعل ما يريد', 3, 5, 17, 1, 1, 42, false, NULL),
    (261, 'tanzil-uthmani-v1.1', 2, 254, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَٰعَةٌ وَٱلْكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ', '6eee07915f0e9991dc4756d5e3ab73f771f82bf4378991f646ef97981601ad9a', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَٰعَةٌ وَٱلْكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ', '6eee07915f0e9991dc4756d5e3ab73f771f82bf4378991f646ef97981601ad9a', '6eee07915f0e9991dc4756d5e3ab73f771f82bf4378991f646ef97981601ad9a', NULL, 'يايها الذين ءامنوا انفقوا مما رزقنكم من قبل ان ياتي يوم لا بيع فيه ولا خله ولا شفعه والكفرون هم الظلمون', 3, 5, 17, 1, 1, 42, false, NULL),
    (262, 'tanzil-uthmani-v1.1', 2, 255, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'cdf04bda6db38541c5d84d515be92968fc30e60051165a9aa14da016470ca4fe', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'cdf04bda6db38541c5d84d515be92968fc30e60051165a9aa14da016470ca4fe', 'cdf04bda6db38541c5d84d515be92968fc30e60051165a9aa14da016470ca4fe', NULL, 'الله لا اله الا هو الحي القيوم لا تاخذه سنه ولا نوم له ما في السموت وما في الارض من ذا الذي يشفع عنده الا باذنه يعلم ما بين ايديهم وما خلفهم ولا يحيطون بشيء من علمه الا بما شاء وسع كرسيه السموت والارض ولا يوده حفظهما وهو العلي العظيم', 3, 5, 17, 1, 1, 42, false, NULL),
    (263, 'tanzil-uthmani-v1.1', 2, 256, 'لَآ إِكْرَاهَ فِى ٱلدِّينِ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ فَمَن يَكْفُرْ بِٱلطَّٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'f073b804fa29cf579ad523c231a309f9eda3967c5149868c6090f8def1ef9997', 'لَآ إِكْرَاهَ فِى ٱلدِّينِ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ فَمَن يَكْفُرْ بِٱلطَّٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'f073b804fa29cf579ad523c231a309f9eda3967c5149868c6090f8def1ef9997', 'f073b804fa29cf579ad523c231a309f9eda3967c5149868c6090f8def1ef9997', NULL, 'لا اكراه في الدين قد تبين الرشد من الغي فمن يكفر بالطغوت ويؤمن بالله فقد استمسك بالعروه الوثقي لا انفصام لها والله سميع عليم', 3, 5, 17, 1, 1, 42, false, NULL),
    (264, 'tanzil-uthmani-v1.1', 2, 257, 'ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'e4b67f3ae4e661547cb628ac0befad3bd4b957e1162a5bb66a57755af8c9fbd7', 'ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'e4b67f3ae4e661547cb628ac0befad3bd4b957e1162a5bb66a57755af8c9fbd7', 'e4b67f3ae4e661547cb628ac0befad3bd4b957e1162a5bb66a57755af8c9fbd7', NULL, 'الله ولي الذين ءامنوا يخرجهم من الظلمت الي النور والذين كفروا اولياؤهم الطغوت يخرجونهم من النور الي الظلمت اولئك اصحب النار هم فيها خلدون', 3, 5, 17, 1, 1, 43, false, NULL),
    (265, 'tanzil-uthmani-v1.1', 2, 258, 'أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِـۧمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ قَالَ إِبْرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'e30c7945560592bd3e5cf5cc7585cc11d860e567e8b6c5cf4efe6b4576a88da0', 'أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِـۧمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ قَالَ إِبْرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'e30c7945560592bd3e5cf5cc7585cc11d860e567e8b6c5cf4efe6b4576a88da0', 'e30c7945560592bd3e5cf5cc7585cc11d860e567e8b6c5cf4efe6b4576a88da0', NULL, 'الم تر الي الذي حاج ابرهم في ربه ان ءاتيه الله الملك اذ قال ابرهم ربي الذي يحي ويميت قال انا احي واميت قال ابرهم فان الله ياتي بالشمس من المشرق فات بها من المغرب فبهت الذي كفر والله لا يهدي القوم الظلمين', 3, 5, 17, 1, 1, 43, false, NULL),
    (266, 'tanzil-uthmani-v1.1', 2, 259, 'أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍ ثُمَّ بَعَثَهُۥ قَالَ كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةً لِّلنَّاسِ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'bafde1028c4a3230233d0e95a39bcf7ff6735dd2ef4191c849ae52a2dc216b92', 'أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍ ثُمَّ بَعَثَهُۥ قَالَ كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةً لِّلنَّاسِ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'bafde1028c4a3230233d0e95a39bcf7ff6735dd2ef4191c849ae52a2dc216b92', 'bafde1028c4a3230233d0e95a39bcf7ff6735dd2ef4191c849ae52a2dc216b92', NULL, 'او كالذي مر علي قريه وهي خاويه علي عروشها قال اني يحي هذه الله بعد موتها فاماته الله مائه عام ثم بعثه قال كم لبثت قال لبثت يوما او بعض يوم قال بل لبثت مائه عام فانظر الي طعامك وشرابك لم يتسنه وانظر الي حمارك ولنجعلك ءايه للناس وانظر الي العظام كيف ننشزها ثم نكسوها لحما فلما تبين له قال اعلم ان الله علي كل شيء قدير', 3, 5, 17, 1, 1, 43, false, NULL),
    (267, 'tanzil-uthmani-v1.1', 2, 260, 'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ قَالَ أَوَلَمْ تُؤْمِن قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِى قَالَ فَخُذْ أَرْبَعَةً مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًا وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'e964e879a872848f27de03aa5693f13d975d99f0f3c91aecca57731a3b84c420', 'وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ قَالَ أَوَلَمْ تُؤْمِن قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِى قَالَ فَخُذْ أَرْبَعَةً مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًا وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'e964e879a872848f27de03aa5693f13d975d99f0f3c91aecca57731a3b84c420', 'e964e879a872848f27de03aa5693f13d975d99f0f3c91aecca57731a3b84c420', NULL, 'واذ قال ابرهم رب ارني كيف تحي الموتي قال اولم تؤمن قال بلي ولكن ليطمئن قلبي قال فخذ اربعه من الطير فصرهن اليك ثم اجعل علي كل جبل منهن جزءا ثم ادعهن ياتينك سعيا واعلم ان الله عزيز حكيم', 3, 5, 17, 1, 1, 44, false, NULL),
    (268, 'tanzil-uthmani-v1.1', 2, 261, 'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍ مِّا۟ئَةُ حَبَّةٍ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'ef04d9bf4300e3c0fc161d1c57db431cd7760624d83180f6c2f51ee0a2e545cd', 'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍ مِّا۟ئَةُ حَبَّةٍ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 'ef04d9bf4300e3c0fc161d1c57db431cd7760624d83180f6c2f51ee0a2e545cd', 'ef04d9bf4300e3c0fc161d1c57db431cd7760624d83180f6c2f51ee0a2e545cd', NULL, 'مثل الذين ينفقون امولهم في سبيل الله كمثل حبه انبتت سبع سنابل في كل سنبله مائه حبه والله يضعف لمن يشاء والله وسع عليم', 3, 5, 17, 1, 1, 44, false, NULL),
    (269, 'tanzil-uthmani-v1.1', 2, 262, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّا وَلَآ أَذًى لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '33b48b3a3c7aadf283e201cbd5af8b9844bbd42e7821dd976b84671a02d6c766', 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّا وَلَآ أَذًى لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '33b48b3a3c7aadf283e201cbd5af8b9844bbd42e7821dd976b84671a02d6c766', '33b48b3a3c7aadf283e201cbd5af8b9844bbd42e7821dd976b84671a02d6c766', NULL, 'الذين ينفقون امولهم في سبيل الله ثم لا يتبعون ما انفقوا منا ولا اذي لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', 3, 5, 17, 1, 1, 44, false, NULL),
    (270, 'tanzil-uthmani-v1.1', 2, 263, 'قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَآ أَذًى وَٱللَّهُ غَنِىٌّ حَلِيمٌ', '96e5c7f23e8a4b8070372560b933be295495818a4331f15764f59812100b5fe9', 'قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَآ أَذًى وَٱللَّهُ غَنِىٌّ حَلِيمٌ', '96e5c7f23e8a4b8070372560b933be295495818a4331f15764f59812100b5fe9', '96e5c7f23e8a4b8070372560b933be295495818a4331f15764f59812100b5fe9', NULL, 'قول معروف ومغفره خير من صدقه يتبعها اذي والله غني حليم', 3, 5, 18, 1, 1, 44, false, NULL),
    (271, 'tanzil-uthmani-v1.1', 2, 264, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُۥ وَابِلٌ فَتَرَكَهُۥ صَلْدًا لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّمَّا كَسَبُوا۟ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', '02e5a1655a41473fdf324a8980df1ed870c6357e91cca8df46aaa99f507bf98b', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُۥ وَابِلٌ فَتَرَكَهُۥ صَلْدًا لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّمَّا كَسَبُوا۟ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', '02e5a1655a41473fdf324a8980df1ed870c6357e91cca8df46aaa99f507bf98b', '02e5a1655a41473fdf324a8980df1ed870c6357e91cca8df46aaa99f507bf98b', NULL, 'يايها الذين ءامنوا لا تبطلوا صدقتكم بالمن والاذي كالذي ينفق ماله رئاء الناس ولا يؤمن بالله واليوم الاخر فمثله كمثل صفوان عليه تراب فاصابه وابل فتركه صلدا لا يقدرون علي شيء مما كسبوا والله لا يهدي القوم الكفرين', 3, 5, 18, 1, 1, 44, false, NULL),
    (272, 'tanzil-uthmani-v1.1', 2, 265, 'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '242b251a386f439a5b3fa4eed8333809ff33baad33020bdbbf0753a24193778d', 'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '242b251a386f439a5b3fa4eed8333809ff33baad33020bdbbf0753a24193778d', '242b251a386f439a5b3fa4eed8333809ff33baad33020bdbbf0753a24193778d', NULL, 'ومثل الذين ينفقون امولهم ابتغاء مرضات الله وتثبيتا من انفسهم كمثل جنه بربوه اصابها وابل فاتت اكلها ضعفين فان لم يصبها وابل فطل والله بما تعملون بصير', 3, 5, 18, 1, 1, 45, false, NULL),
    (273, 'tanzil-uthmani-v1.1', 2, 266, 'أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌ فِيهِ نَارٌ فَٱحْتَرَقَتْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 'fd3e980b6b103aae1f8dddb5cdc8f74f4b490d008a0045643ba110f13fa07709', 'أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌ فِيهِ نَارٌ فَٱحْتَرَقَتْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 'fd3e980b6b103aae1f8dddb5cdc8f74f4b490d008a0045643ba110f13fa07709', 'fd3e980b6b103aae1f8dddb5cdc8f74f4b490d008a0045643ba110f13fa07709', NULL, 'ايود احدكم ان تكون له جنه من نخيل واعناب تجري من تحتها الانهر له فيها من كل الثمرت واصابه الكبر وله ذريه ضعفاء فاصابها اعصار فيه نار فاحترقت كذلك يبين الله لكم الايت لعلكم تتفكرون', 3, 5, 18, 1, 1, 45, false, NULL),
    (274, 'tanzil-uthmani-v1.1', 2, 267, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', '407f80de74189ab73bafd077c46339d9693f2a2adf47d788c3368ce31ecb5362', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', '407f80de74189ab73bafd077c46339d9693f2a2adf47d788c3368ce31ecb5362', '407f80de74189ab73bafd077c46339d9693f2a2adf47d788c3368ce31ecb5362', NULL, 'يايها الذين ءامنوا انفقوا من طيبت ما كسبتم ومما اخرجنا لكم من الارض ولا تيمموا الخبيث منه تنفقون ولستم باخذيه الا ان تغمضوا فيه واعلموا ان الله غني حميد', 3, 5, 18, 1, 1, 45, false, NULL),
    (275, 'tanzil-uthmani-v1.1', 2, 268, 'ٱلشَّيْطَٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '46eee8dbb739d951624f616e75d882fdae52df0dec1695d167ef8aa789c724da', 'ٱلشَّيْطَٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '46eee8dbb739d951624f616e75d882fdae52df0dec1695d167ef8aa789c724da', '46eee8dbb739d951624f616e75d882fdae52df0dec1695d167ef8aa789c724da', NULL, 'الشيطن يعدكم الفقر ويامركم بالفحشاء والله يعدكم مغفره منه وفضلا والله وسع عليم', 3, 5, 18, 1, 1, 45, false, NULL),
    (276, 'tanzil-uthmani-v1.1', 2, 269, 'يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًا كَثِيرًا وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '311e19d067c6678d571338864a3631fdfa1180d6d9aaced2f9b40c65edf03409', 'يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًا كَثِيرًا وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '311e19d067c6678d571338864a3631fdfa1180d6d9aaced2f9b40c65edf03409', '311e19d067c6678d571338864a3631fdfa1180d6d9aaced2f9b40c65edf03409', NULL, 'يؤتي الحكمه من يشاء ومن يؤت الحكمه فقد اوتي خيرا كثيرا وما يذكر الا اولوا الالبب', 3, 5, 18, 1, 1, 45, false, NULL),
    (277, 'tanzil-uthmani-v1.1', 2, 270, 'وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', '9e5d4a63dde3b01e0c7fc031bc75235b25e1575092e2959059494f00f0a9f91c', 'وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', '9e5d4a63dde3b01e0c7fc031bc75235b25e1575092e2959059494f00f0a9f91c', '9e5d4a63dde3b01e0c7fc031bc75235b25e1575092e2959059494f00f0a9f91c', NULL, 'وما انفقتم من نفقه او نذرتم من نذر فان الله يعلمه وما للظلمين من انصار', 3, 5, 18, 1, 1, 46, false, NULL),
    (278, 'tanzil-uthmani-v1.1', 2, 271, 'إِن تُبْدُوا۟ ٱلصَّدَقَٰتِ فَنِعِمَّا هِىَ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌ لَّكُمْ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'bad83db34bee0bf2e8e4beaf10b8b4ce2a848de0700d59335556a8763c6f6975', 'إِن تُبْدُوا۟ ٱلصَّدَقَٰتِ فَنِعِمَّا هِىَ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌ لَّكُمْ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'bad83db34bee0bf2e8e4beaf10b8b4ce2a848de0700d59335556a8763c6f6975', 'bad83db34bee0bf2e8e4beaf10b8b4ce2a848de0700d59335556a8763c6f6975', NULL, 'ان تبدوا الصدقت فنعما هي وان تخفوها وتؤتوها الفقراء فهو خير لكم ويكفر عنكم من سياتكم والله بما تعملون خبير', 3, 5, 18, 1, 1, 46, false, NULL),
    (279, 'tanzil-uthmani-v1.1', 2, 272, 'لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَلِأَنفُسِكُمْ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 'fdffb7d6f86b37805664230705c7f9766d15a1511441b53e4c8d050dfd062cbd', 'لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَلِأَنفُسِكُمْ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 'fdffb7d6f86b37805664230705c7f9766d15a1511441b53e4c8d050dfd062cbd', 'fdffb7d6f86b37805664230705c7f9766d15a1511441b53e4c8d050dfd062cbd', NULL, 'ليس عليك هديهم ولكن الله يهدي من يشاء وما تنفقوا من خير فلانفسكم وما تنفقون الا ابتغاء وجه الله وما تنفقوا من خير يوف اليكم وانتم لا تظلمون', 3, 5, 19, 1, 1, 46, false, NULL),
    (280, 'tanzil-uthmani-v1.1', 2, 273, 'لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًا وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '76e09291cafc1c9b6460da2257d631a50a92f09768c6e88430a2baa79ee814e5', 'لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًا وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '76e09291cafc1c9b6460da2257d631a50a92f09768c6e88430a2baa79ee814e5', '76e09291cafc1c9b6460da2257d631a50a92f09768c6e88430a2baa79ee814e5', NULL, 'للفقراء الذين احصروا في سبيل الله لا يستطيعون ضربا في الارض يحسبهم الجاهل اغنياء من التعفف تعرفهم بسيمهم لا يسلون الناس الحافا وما تنفقوا من خير فان الله به عليم', 3, 5, 19, 1, 1, 46, false, NULL),
    (281, 'tanzil-uthmani-v1.1', 2, 274, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '563bfe326361698e820502f3b42342e7cecb30ee301ed53fb33d36dac7d877c6', 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '563bfe326361698e820502f3b42342e7cecb30ee301ed53fb33d36dac7d877c6', '563bfe326361698e820502f3b42342e7cecb30ee301ed53fb33d36dac7d877c6', NULL, 'الذين ينفقون امولهم باليل والنهار سرا وعلانيه فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', 3, 5, 19, 1, 1, 46, false, NULL),
    (282, 'tanzil-uthmani-v1.1', 2, 275, 'ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَٰنُ مِنَ ٱلْمَسِّ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ فَمَن جَآءَهُۥ مَوْعِظَةٌ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ وَمَنْ عَادَ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '1a50be2418d3321b4ea2f6a266af309a295eab7f521121c1ce07b0894f775d8d', 'ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَٰنُ مِنَ ٱلْمَسِّ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ فَمَن جَآءَهُۥ مَوْعِظَةٌ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ وَمَنْ عَادَ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '1a50be2418d3321b4ea2f6a266af309a295eab7f521121c1ce07b0894f775d8d', '1a50be2418d3321b4ea2f6a266af309a295eab7f521121c1ce07b0894f775d8d', NULL, 'الذين ياكلون الربوا لا يقومون الا كما يقوم الذي يتخبطه الشيطن من المس ذلك بانهم قالوا انما البيع مثل الربوا واحل الله البيع وحرم الربوا فمن جاءه موعظه من ربه فانتهي فله ما سلف وامره الي الله ومن عاد فاولئك اصحب النار هم فيها خلدون', 3, 5, 19, 1, 1, 47, false, NULL),
    (283, 'tanzil-uthmani-v1.1', 2, 276, 'يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَٰتِ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', '423ffe7b4e279917c8ef5a0420bb8d5a5c4ba3bebdc148ea7e3efb17bafec9ec', 'يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَٰتِ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', '423ffe7b4e279917c8ef5a0420bb8d5a5c4ba3bebdc148ea7e3efb17bafec9ec', '423ffe7b4e279917c8ef5a0420bb8d5a5c4ba3bebdc148ea7e3efb17bafec9ec', NULL, 'يمحق الله الربوا ويربي الصدقت والله لا يحب كل كفار اثيم', 3, 5, 19, 1, 1, 47, false, NULL),
    (284, 'tanzil-uthmani-v1.1', 2, 277, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'bfdf560f983042b30e5dac363043fc351a9ccb46e975d853371e7b241a8ace60', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'bfdf560f983042b30e5dac363043fc351a9ccb46e975d853371e7b241a8ace60', 'bfdf560f983042b30e5dac363043fc351a9ccb46e975d853371e7b241a8ace60', NULL, 'ان الذين ءامنوا وعملوا الصلحت واقاموا الصلوه وءاتوا الزكوه لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', 3, 5, 19, 1, 1, 47, false, NULL),
    (285, 'tanzil-uthmani-v1.1', 2, 278, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ', '8d4267702bcc4ac2c86b0b206241112fa65583c3c8fcd15c9b36694757d64648', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ', '8d4267702bcc4ac2c86b0b206241112fa65583c3c8fcd15c9b36694757d64648', '8d4267702bcc4ac2c86b0b206241112fa65583c3c8fcd15c9b36694757d64648', NULL, 'يايها الذين ءامنوا اتقوا الله وذروا ما بقي من الربوا ان كنتم مؤمنين', 3, 5, 19, 1, 1, 47, false, NULL),
    (286, 'tanzil-uthmani-v1.1', 2, 279, 'فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍ مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ', '60a66f290068e56de3376d1989c99a815ffab0e8d7f86b2ec84baac4fb2e8449', 'فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍ مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ', '60a66f290068e56de3376d1989c99a815ffab0e8d7f86b2ec84baac4fb2e8449', '60a66f290068e56de3376d1989c99a815ffab0e8d7f86b2ec84baac4fb2e8449', NULL, 'فان لم تفعلوا فاذنوا بحرب من الله ورسوله وان تبتم فلكم رءوس امولكم لا تظلمون ولا تظلمون', 3, 5, 19, 1, 1, 47, false, NULL),
    (287, 'tanzil-uthmani-v1.1', 2, 280, 'وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَن تَصَدَّقُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '5b1eb83626548e9d47ab12511136f9c6670ec5089bd586355adb9d1ad679eff0', 'وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَن تَصَدَّقُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '5b1eb83626548e9d47ab12511136f9c6670ec5089bd586355adb9d1ad679eff0', '5b1eb83626548e9d47ab12511136f9c6670ec5089bd586355adb9d1ad679eff0', NULL, 'وان كان ذو عسره فنظره الي ميسره وان تصدقوا خير لكم ان كنتم تعلمون', 3, 5, 19, 1, 1, 47, false, NULL),
    (288, 'tanzil-uthmani-v1.1', 2, 281, 'وَٱتَّقُوا۟ يَوْمًا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'c6747eebe52f68fe4c3052352a1242c89a6122d1bcc4f0e3e134667e22ca5ce9', 'وَٱتَّقُوا۟ يَوْمًا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'c6747eebe52f68fe4c3052352a1242c89a6122d1bcc4f0e3e134667e22ca5ce9', 'c6747eebe52f68fe4c3052352a1242c89a6122d1bcc4f0e3e134667e22ca5ce9', NULL, 'واتقوا يوما ترجعون فيه الي الله ثم توفي كل نفس ما كسبت وهم لا يظلمون', 3, 5, 19, 1, 1, 47, false, NULL),
    (289, 'tanzil-uthmani-v1.1', 2, 282, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَٱكْتُبُوهُ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًٔا فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ وَلَا يُضَآرَّ كَاتِبٌ وَلَا شَهِيدٌ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَيُعَلِّمُكُمُ ٱللَّهُ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '5ae07116ba7a4cc66989c083ef5a3e5300b3ffef2e0153f99619171a5525612c', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَٱكْتُبُوهُ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًٔا فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ وَلَا يُضَآرَّ كَاتِبٌ وَلَا شَهِيدٌ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَيُعَلِّمُكُمُ ٱللَّهُ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '5ae07116ba7a4cc66989c083ef5a3e5300b3ffef2e0153f99619171a5525612c', '5ae07116ba7a4cc66989c083ef5a3e5300b3ffef2e0153f99619171a5525612c', NULL, 'يايها الذين ءامنوا اذا تداينتم بدين الي اجل مسمي فاكتبوه وليكتب بينكم كاتب بالعدل ولا ياب كاتب ان يكتب كما علمه الله فليكتب وليملل الذي عليه الحق وليتق الله ربه ولا يبخس منه شيا فان كان الذي عليه الحق سفيها او ضعيفا او لا يستطيع ان يمل هو فليملل وليه بالعدل واستشهدوا شهيدين من رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء ان تضل احديهما فتذكر احديهما الاخري ولا ياب الشهداء اذا ما دعوا ولا تسموا ان تكتبوه صغيرا او كبيرا الي اجله ذلكم اقسط عند الله واقوم للشهده وادني الا ترتابوا الا ان تكون تجره حاضره تديرونها بينكم فليس عليكم جناح الا تكتبوها واشهدوا اذا تبايعتم ولا يضار كاتب ولا شهيد وان تفعلوا فانه فسوق بكم واتقوا الله ويعلمكم الله والله بكل شيء عليم', 3, 5, 19, 1, 1, 48, false, NULL),
    (290, 'tanzil-uthmani-v1.1', 2, 283, 'وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا۟ كَاتِبًا فَرِهَٰنٌ مَّقْبُوضَةٌ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا تَكْتُمُوا۟ ٱلشَّهَٰدَةَ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌ قَلْبُهُۥ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', '036dd0d3df874e57f4cd37e4349f8e9268e0f111ca529b1e985cde125938574c', 'وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا۟ كَاتِبًا فَرِهَٰنٌ مَّقْبُوضَةٌ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا تَكْتُمُوا۟ ٱلشَّهَٰدَةَ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌ قَلْبُهُۥ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', '036dd0d3df874e57f4cd37e4349f8e9268e0f111ca529b1e985cde125938574c', '036dd0d3df874e57f4cd37e4349f8e9268e0f111ca529b1e985cde125938574c', NULL, 'وان كنتم علي سفر ولم تجدوا كاتبا فرهن مقبوضه فان امن بعضكم بعضا فليؤد الذي اؤتمن امنته وليتق الله ربه ولا تكتموا الشهده ومن يكتمها فانه ءاثم قلبه والله بما تعملون عليم', 3, 5, 20, 1, 1, 49, false, NULL),
    (291, 'tanzil-uthmani-v1.1', 2, 284, 'لِّلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '5b82a0742be31247295452ec6ee94dabcf186519b09aad4782bb95322ec26cc4', 'لِّلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '5b82a0742be31247295452ec6ee94dabcf186519b09aad4782bb95322ec26cc4', '5b82a0742be31247295452ec6ee94dabcf186519b09aad4782bb95322ec26cc4', NULL, 'لله ما في السموت وما في الارض وان تبدوا ما في انفسكم او تخفوه يحاسبكم به الله فيغفر لمن يشاء ويعذب من يشاء والله علي كل شيء قدير', 3, 5, 20, 1, 1, 49, false, NULL),
    (292, 'tanzil-uthmani-v1.1', 2, 285, 'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ', 'f2265abebc5021a9e475ac61d652136d1fde684ad236b309dab355e094caaa9f', 'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ', 'f2265abebc5021a9e475ac61d652136d1fde684ad236b309dab355e094caaa9f', 'f2265abebc5021a9e475ac61d652136d1fde684ad236b309dab355e094caaa9f', NULL, 'ءامن الرسول بما انزل اليه من ربه والمؤمنون كل ءامن بالله وملئكته وكتبه ورسله لا نفرق بين احد من رسله وقالوا سمعنا واطعنا غفرانك ربنا واليك المصير', 3, 5, 20, 1, 1, 49, false, NULL),
    (293, 'tanzil-uthmani-v1.1', 2, 286, 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '6390338cde40a23217a3342d07dcb64dc546650b5a7a2cb9aa050157edb33f51', 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '6390338cde40a23217a3342d07dcb64dc546650b5a7a2cb9aa050157edb33f51', '6390338cde40a23217a3342d07dcb64dc546650b5a7a2cb9aa050157edb33f51', NULL, 'لا يكلف الله نفسا الا وسعها لها ما كسبت وعليها ما اكتسبت ربنا لا تؤاخذنا ان نسينا او اخطانا ربنا ولا تحمل علينا اصرا كما حملته علي الذين من قبلنا ربنا ولا تحملنا ما لا طاقه لنا به واعف عنا واغفر لنا وارحمنا انت مولينا فانصرنا علي القوم الكفرين', 3, 5, 20, 1, 1, 49, false, NULL),
    (294, 'tanzil-uthmani-v1.1', 3, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'e190dd3d3d044e6256ebd129866c8631838018200128280a20f27d07491b7e45', 'الٓمٓ', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الم', 3, 5, 20, 1, 1, 50, false, NULL),
    (295, 'tanzil-uthmani-v1.1', 3, 2, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ', 'a5af5ea0618d48468d41949b1957e7e4fa8a9e6df13a5b24252091f17a01fe23', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ', 'a5af5ea0618d48468d41949b1957e7e4fa8a9e6df13a5b24252091f17a01fe23', 'a5af5ea0618d48468d41949b1957e7e4fa8a9e6df13a5b24252091f17a01fe23', NULL, 'الله لا اله الا هو الحي القيوم', 3, 5, 20, 1, 1, 50, false, NULL),
    (296, 'tanzil-uthmani-v1.1', 3, 3, 'نَزَّلَ عَلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 'decc92f867900e725c3cab3b71070496152cbf744ed6a4dfabd13ee64e128296', 'نَزَّلَ عَلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 'decc92f867900e725c3cab3b71070496152cbf744ed6a4dfabd13ee64e128296', 'decc92f867900e725c3cab3b71070496152cbf744ed6a4dfabd13ee64e128296', NULL, 'نزل عليك الكتب بالحق مصدقا لما بين يديه وانزل التوريه والانجيل', 3, 5, 20, 1, 1, 50, false, NULL),
    (297, 'tanzil-uthmani-v1.1', 3, 4, 'مِن قَبْلُ هُدًى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', 'b9a17ea1ec9ae71a7619be7472679c668079c2ac6fa034670dd63b5869741770', 'مِن قَبْلُ هُدًى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', 'b9a17ea1ec9ae71a7619be7472679c668079c2ac6fa034670dd63b5869741770', 'b9a17ea1ec9ae71a7619be7472679c668079c2ac6fa034670dd63b5869741770', NULL, 'من قبل هدي للناس وانزل الفرقان ان الذين كفروا بايت الله لهم عذاب شديد والله عزيز ذو انتقام', 3, 5, 20, 1, 1, 50, false, NULL),
    (298, 'tanzil-uthmani-v1.1', 3, 5, 'إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', '6dfb424714650664c7a31e959258fb4debda1f43d0b764053ea8c1b478f10a43', 'إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', '6dfb424714650664c7a31e959258fb4debda1f43d0b764053ea8c1b478f10a43', '6dfb424714650664c7a31e959258fb4debda1f43d0b764053ea8c1b478f10a43', NULL, 'ان الله لا يخفي عليه شيء في الارض ولا في السماء', 3, 5, 20, 1, 1, 50, false, NULL),
    (299, 'tanzil-uthmani-v1.1', 3, 6, 'هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '8954d36c37cb8bf21d632efa00f18ae6883e4e268a558f153099f5660131a84f', 'هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '8954d36c37cb8bf21d632efa00f18ae6883e4e268a558f153099f5660131a84f', '8954d36c37cb8bf21d632efa00f18ae6883e4e268a558f153099f5660131a84f', NULL, 'هو الذي يصوركم في الارحام كيف يشاء لا اله الا هو العزيز الحكيم', 3, 5, 20, 1, 1, 50, false, NULL),
    (300, 'tanzil-uthmani-v1.1', 3, 7, 'هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَٰبَ مِنْهُ ءَايَٰتٌ مُّحْكَمَٰتٌ هُنَّ أُمُّ ٱلْكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٌ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّ مِّنْ عِندِ رَبِّنَا وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '192ac9dcd5ee9986af5060ac6e079ff9cc922937a35c96d66771a00150d9da0a', 'هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَٰبَ مِنْهُ ءَايَٰتٌ مُّحْكَمَٰتٌ هُنَّ أُمُّ ٱلْكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٌ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّ مِّنْ عِندِ رَبِّنَا وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '192ac9dcd5ee9986af5060ac6e079ff9cc922937a35c96d66771a00150d9da0a', '192ac9dcd5ee9986af5060ac6e079ff9cc922937a35c96d66771a00150d9da0a', NULL, 'هو الذي انزل عليك الكتب منه ءايت محكمت هن ام الكتب واخر متشبهت فاما الذين في قلوبهم زيغ فيتبعون ما تشبه منه ابتغاء الفتنه وابتغاء تاويله وما يعلم تاويله الا الله والرسخون في العلم يقولون ءامنا به كل من عند ربنا وما يذكر الا اولوا الالبب', 3, 5, 20, 1, 1, 50, false, NULL),
    (301, 'tanzil-uthmani-v1.1', 3, 8, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً إِنَّكَ أَنتَ ٱلْوَهَّابُ', '6afb710d8b67ebf013892ad17fdfab213af279065e33757c82da3bc45a9e83f2', 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً إِنَّكَ أَنتَ ٱلْوَهَّابُ', '6afb710d8b67ebf013892ad17fdfab213af279065e33757c82da3bc45a9e83f2', '6afb710d8b67ebf013892ad17fdfab213af279065e33757c82da3bc45a9e83f2', NULL, 'ربنا لا تزغ قلوبنا بعد اذ هديتنا وهب لنا من لدنك رحمه انك انت الوهاب', 3, 5, 20, 1, 1, 50, false, NULL),
    (302, 'tanzil-uthmani-v1.1', 3, 9, 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', '8d702782f87187946a897603638284c0c03a0747abd7acf05e02d3d258ad1fcd', 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', '8d702782f87187946a897603638284c0c03a0747abd7acf05e02d3d258ad1fcd', '8d702782f87187946a897603638284c0c03a0747abd7acf05e02d3d258ad1fcd', NULL, 'ربنا انك جامع الناس ليوم لا ريب فيه ان الله لا يخلف الميعاد', 3, 5, 20, 1, 1, 50, false, NULL),
    (303, 'tanzil-uthmani-v1.1', 3, 10, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا وَأُو۟لَٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ', 'e7de68f479bfa8d998c042509876b9756bef6f52a6f46c4d5e823b494ae7929c', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا وَأُو۟لَٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ', 'e7de68f479bfa8d998c042509876b9756bef6f52a6f46c4d5e823b494ae7929c', 'e7de68f479bfa8d998c042509876b9756bef6f52a6f46c4d5e823b494ae7929c', NULL, 'ان الذين كفروا لن تغني عنهم امولهم ولا اولدهم من الله شيا واولئك هم وقود النار', 3, 5, 20, 1, 1, 51, false, NULL),
    (304, 'tanzil-uthmani-v1.1', 3, 11, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 'a191918c1c5fc9b973aa530abd601240a376046d6742b5f0bb1ec53de170d9b6', 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 'a191918c1c5fc9b973aa530abd601240a376046d6742b5f0bb1ec53de170d9b6', 'a191918c1c5fc9b973aa530abd601240a376046d6742b5f0bb1ec53de170d9b6', NULL, 'كداب ءال فرعون والذين من قبلهم كذبوا بايتنا فاخذهم الله بذنوبهم والله شديد العقاب', 3, 5, 20, 1, 1, 51, false, NULL),
    (305, 'tanzil-uthmani-v1.1', 3, 12, 'قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ وَبِئْسَ ٱلْمِهَادُ', '1d5152f4885a289d9eb8196a8a96d34268df9305640a4c595c442a2cd028a391', 'قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ وَبِئْسَ ٱلْمِهَادُ', '1d5152f4885a289d9eb8196a8a96d34268df9305640a4c595c442a2cd028a391', '1d5152f4885a289d9eb8196a8a96d34268df9305640a4c595c442a2cd028a391', NULL, 'قل للذين كفروا ستغلبون وتحشرون الي جهنم وبئس المهاد', 3, 5, 20, 1, 1, 51, false, NULL),
    (306, 'tanzil-uthmani-v1.1', 3, 13, 'قَدْ كَانَ لَكُمْ ءَايَةٌ فِى فِئَتَيْنِ ٱلْتَقَتَا فِئَةٌ تُقَٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَٰرِ', 'aa14ddd1c304cacd2a037b4e8ea1fbeb1c4d02af9ba0046bc724069237ab86fb', 'قَدْ كَانَ لَكُمْ ءَايَةٌ فِى فِئَتَيْنِ ٱلْتَقَتَا فِئَةٌ تُقَٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَٰرِ', 'aa14ddd1c304cacd2a037b4e8ea1fbeb1c4d02af9ba0046bc724069237ab86fb', 'aa14ddd1c304cacd2a037b4e8ea1fbeb1c4d02af9ba0046bc724069237ab86fb', NULL, 'قد كان لكم ءايه في فئتين التقتا فئه تقتل في سبيل الله واخري كافره يرونهم مثليهم راي العين والله يؤيد بنصره من يشاء ان في ذلك لعبره لاولي الابصر', 3, 5, 20, 1, 1, 51, false, NULL),
    (307, 'tanzil-uthmani-v1.1', 3, 14, 'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَٰمِ وَٱلْحَرْثِ ذَٰلِكَ مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ', '9c3ec1b19cc1af2dedbbd43a78359769858488d47144eb75cf2d9b8c05d78d90', 'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَٰمِ وَٱلْحَرْثِ ذَٰلِكَ مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ', '9c3ec1b19cc1af2dedbbd43a78359769858488d47144eb75cf2d9b8c05d78d90', '9c3ec1b19cc1af2dedbbd43a78359769858488d47144eb75cf2d9b8c05d78d90', NULL, 'زين للناس حب الشهوت من النساء والبنين والقنطير المقنطره من الذهب والفضه والخيل المسومه والانعم والحرث ذلك متع الحيوه الدنيا والله عنده حسن الماب', 3, 5, 20, 1, 1, 51, false, NULL),
    (308, 'tanzil-uthmani-v1.1', 3, 15, 'قُلْ أَؤُنَبِّئُكُم بِخَيْرٍ مِّن ذَٰلِكُمْ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', '90a6f7e038f418a18b730f441b79d4385283fd8405ad267b885bef2854c0d356', 'قُلْ أَؤُنَبِّئُكُم بِخَيْرٍ مِّن ذَٰلِكُمْ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَأَزْوَٰجٌ مُّطَهَّرَةٌ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', '90a6f7e038f418a18b730f441b79d4385283fd8405ad267b885bef2854c0d356', '90a6f7e038f418a18b730f441b79d4385283fd8405ad267b885bef2854c0d356', NULL, 'قل اؤنبئكم بخير من ذلكم للذين اتقوا عند ربهم جنت تجري من تحتها الانهر خلدين فيها وازوج مطهره ورضون من الله والله بصير بالعباد', 3, 6, 21, 1, 1, 51, false, NULL),
    (309, 'tanzil-uthmani-v1.1', 3, 16, 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', '5f52570371e9c55a4802195ae0c6a3a2b771630b174fcbafb1f15ad590e8ee40', 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', '5f52570371e9c55a4802195ae0c6a3a2b771630b174fcbafb1f15ad590e8ee40', '5f52570371e9c55a4802195ae0c6a3a2b771630b174fcbafb1f15ad590e8ee40', NULL, 'الذين يقولون ربنا اننا ءامنا فاغفر لنا ذنوبنا وقنا عذاب النار', 3, 6, 21, 1, 1, 52, false, NULL),
    (310, 'tanzil-uthmani-v1.1', 3, 17, 'ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلْقَٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ', 'df418472d3217269d5956a1ac411815131ea16d34708518395ae59a4d4106706', 'ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلْقَٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ', 'df418472d3217269d5956a1ac411815131ea16d34708518395ae59a4d4106706', 'df418472d3217269d5956a1ac411815131ea16d34708518395ae59a4d4106706', NULL, 'الصبرين والصدقين والقنتين والمنفقين والمستغفرين بالاسحار', 3, 6, 21, 1, 1, 52, false, NULL),
    (311, 'tanzil-uthmani-v1.1', 3, 18, 'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '823c6c62cb0306968a13c67a2c6a408f4f0ece738eb02a2ef68a2f717bc34b6a', 'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '823c6c62cb0306968a13c67a2c6a408f4f0ece738eb02a2ef68a2f717bc34b6a', '823c6c62cb0306968a13c67a2c6a408f4f0ece738eb02a2ef68a2f717bc34b6a', NULL, 'شهد الله انه لا اله الا هو والملئكه واولوا العلم قائما بالقسط لا اله الا هو العزيز الحكيم', 3, 6, 21, 1, 1, 52, false, NULL),
    (312, 'tanzil-uthmani-v1.1', 3, 19, 'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَٰمُ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ وَمَن يَكْفُرْ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'a8c0ebc531d08f634d199f4540352f2019593460f596573adf47f949998a6afe', 'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَٰمُ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ وَمَن يَكْفُرْ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'a8c0ebc531d08f634d199f4540352f2019593460f596573adf47f949998a6afe', 'a8c0ebc531d08f634d199f4540352f2019593460f596573adf47f949998a6afe', NULL, 'ان الدين عند الله الاسلم وما اختلف الذين اوتوا الكتب الا من بعد ما جاءهم العلم بغيا بينهم ومن يكفر بايت الله فان الله سريع الحساب', 3, 6, 21, 1, 1, 52, false, NULL),
    (313, 'tanzil-uthmani-v1.1', 3, 20, 'فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْأُمِّيِّـۧنَ ءَأَسْلَمْتُمْ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', '6d263338af8e45ffaa532743b80748c2ca805f9fd8f993595c510c89a6af35e8', 'فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْأُمِّيِّـۧنَ ءَأَسْلَمْتُمْ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', '6d263338af8e45ffaa532743b80748c2ca805f9fd8f993595c510c89a6af35e8', '6d263338af8e45ffaa532743b80748c2ca805f9fd8f993595c510c89a6af35e8', NULL, 'فان حاجوك فقل اسلمت وجهي لله ومن اتبعن وقل للذين اوتوا الكتب والامين ءاسلمتم فان اسلموا فقد اهتدوا وان تولوا فانما عليك البلغ والله بصير بالعباد', 3, 6, 21, 1, 1, 52, false, NULL),
    (314, 'tanzil-uthmani-v1.1', 3, 21, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', '6ac40a6e31e2a883e7f40bf6650e8c15dbd6fc5bb7fbee538dbdf8e3ef3bc0a2', 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ حَقٍّ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', '6ac40a6e31e2a883e7f40bf6650e8c15dbd6fc5bb7fbee538dbdf8e3ef3bc0a2', '6ac40a6e31e2a883e7f40bf6650e8c15dbd6fc5bb7fbee538dbdf8e3ef3bc0a2', NULL, 'ان الذين يكفرون بايت الله ويقتلون النبين بغير حق ويقتلون الذين يامرون بالقسط من الناس فبشرهم بعذاب اليم', 3, 6, 21, 1, 1, 52, false, NULL),
    (315, 'tanzil-uthmani-v1.1', 3, 22, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', '1e542d8f5d297054001f764ce1c267072f31c3b4506bb05911f31ed22bf373d4', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', '1e542d8f5d297054001f764ce1c267072f31c3b4506bb05911f31ed22bf373d4', '1e542d8f5d297054001f764ce1c267072f31c3b4506bb05911f31ed22bf373d4', NULL, 'اولئك الذين حبطت اعملهم في الدنيا والاخره وما لهم من نصرين', 3, 6, 21, 1, 1, 52, false, NULL),
    (316, 'tanzil-uthmani-v1.1', 3, 23, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يُدْعَوْنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُمْ وَهُم مُّعْرِضُونَ', '2f935207aeffc35cd5d48caebc0636a838c2abe5df10f3bda13df69854b30921', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يُدْعَوْنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُمْ وَهُم مُّعْرِضُونَ', '2f935207aeffc35cd5d48caebc0636a838c2abe5df10f3bda13df69854b30921', '2f935207aeffc35cd5d48caebc0636a838c2abe5df10f3bda13df69854b30921', NULL, 'الم تر الي الذين اوتوا نصيبا من الكتب يدعون الي كتب الله ليحكم بينهم ثم يتولي فريق منهم وهم معرضون', 3, 6, 21, 1, 1, 53, false, NULL),
    (317, 'tanzil-uthmani-v1.1', 3, 24, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَٰتٍ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ', '18fd40b8919166b528378da57d35dafca65198ebd3b137d1ef5ed1dc481660c4', 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَٰتٍ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ', '18fd40b8919166b528378da57d35dafca65198ebd3b137d1ef5ed1dc481660c4', '18fd40b8919166b528378da57d35dafca65198ebd3b137d1ef5ed1dc481660c4', NULL, 'ذلك بانهم قالوا لن تمسنا النار الا اياما معدودت وغرهم في دينهم ما كانوا يفترون', 3, 6, 21, 1, 1, 53, false, NULL),
    (318, 'tanzil-uthmani-v1.1', 3, 25, 'فَكَيْفَ إِذَا جَمَعْنَٰهُمْ لِيَوْمٍ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'ce98fab3e0e0d98e2af32de75254994768044bd86c55bd9f3334a254a94a7136', 'فَكَيْفَ إِذَا جَمَعْنَٰهُمْ لِيَوْمٍ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'ce98fab3e0e0d98e2af32de75254994768044bd86c55bd9f3334a254a94a7136', 'ce98fab3e0e0d98e2af32de75254994768044bd86c55bd9f3334a254a94a7136', NULL, 'فكيف اذا جمعنهم ليوم لا ريب فيه ووفيت كل نفس ما كسبت وهم لا يظلمون', 3, 6, 21, 1, 1, 53, false, NULL),
    (319, 'tanzil-uthmani-v1.1', 3, 26, 'قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ بِيَدِكَ ٱلْخَيْرُ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '54428c1b33b1e81845a63cd71ae51c8a160367f0f6eab0ab7f09a70296998a2f', 'قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ بِيَدِكَ ٱلْخَيْرُ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '54428c1b33b1e81845a63cd71ae51c8a160367f0f6eab0ab7f09a70296998a2f', '54428c1b33b1e81845a63cd71ae51c8a160367f0f6eab0ab7f09a70296998a2f', NULL, 'قل اللهم ملك الملك تؤتي الملك من تشاء وتنزع الملك ممن تشاء وتعز من تشاء وتذل من تشاء بيدك الخير انك علي كل شيء قدير', 3, 6, 21, 1, 1, 53, false, NULL),
    (320, 'tanzil-uthmani-v1.1', 3, 27, 'تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍ', 'ea9c1a669227d716466ed086fbe1d624aab8f491ff3a0050b1eda0c3ef839937', 'تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍ', 'ea9c1a669227d716466ed086fbe1d624aab8f491ff3a0050b1eda0c3ef839937', 'ea9c1a669227d716466ed086fbe1d624aab8f491ff3a0050b1eda0c3ef839937', NULL, 'تولج اليل في النهار وتولج النهار في اليل وتخرج الحي من الميت وتخرج الميت من الحي وترزق من تشاء بغير حساب', 3, 6, 21, 1, 1, 53, false, NULL),
    (321, 'tanzil-uthmani-v1.1', 3, 28, 'لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةً وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'c022f58b9a5dba30ed9ca94a80d07b26cfdf72f2f2958f39562b057e84ff7bad', 'لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةً وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'c022f58b9a5dba30ed9ca94a80d07b26cfdf72f2f2958f39562b057e84ff7bad', 'c022f58b9a5dba30ed9ca94a80d07b26cfdf72f2f2958f39562b057e84ff7bad', NULL, 'لا يتخذ المؤمنون الكفرين اولياء من دون المؤمنين ومن يفعل ذلك فليس من الله في شيء الا ان تتقوا منهم تقيه ويحذركم الله نفسه والي الله المصير', 3, 6, 21, 1, 1, 53, false, NULL),
    (322, 'tanzil-uthmani-v1.1', 3, 29, 'قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ وَيَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '790e12143dfcb3206c4e39a9a87f496d726208293412eb37a4888730115ff7e5', 'قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ وَيَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '790e12143dfcb3206c4e39a9a87f496d726208293412eb37a4888730115ff7e5', '790e12143dfcb3206c4e39a9a87f496d726208293412eb37a4888730115ff7e5', NULL, 'قل ان تخفوا ما في صدوركم او تبدوه يعلمه الله ويعلم ما في السموت وما في الارض والله علي كل شيء قدير', 3, 6, 21, 1, 1, 53, false, NULL),
    (323, 'tanzil-uthmani-v1.1', 3, 30, 'يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَرًا وَمَا عَمِلَتْ مِن سُوٓءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًا وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 'a3f7062d938a936948dfe1e04b1d2c12c9f14246aa488cbe7aedf7563beb6f25', 'يَوْمَ تَجِدُ كُلُّ نَفْسٍ مَّا عَمِلَتْ مِنْ خَيْرٍ مُّحْضَرًا وَمَا عَمِلَتْ مِن سُوٓءٍ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًا وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 'a3f7062d938a936948dfe1e04b1d2c12c9f14246aa488cbe7aedf7563beb6f25', 'a3f7062d938a936948dfe1e04b1d2c12c9f14246aa488cbe7aedf7563beb6f25', NULL, 'يوم تجد كل نفس ما عملت من خير محضرا وما عملت من سوء تود لو ان بينها وبينه امدا بعيدا ويحذركم الله نفسه والله رءوف بالعباد', 3, 6, 21, 1, 1, 54, false, NULL),
    (324, 'tanzil-uthmani-v1.1', 3, 31, 'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '32d7b49a6e7a160d13a7a6050182794f0684e0acf328268fb8e85999a47d4510', 'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '32d7b49a6e7a160d13a7a6050182794f0684e0acf328268fb8e85999a47d4510', '32d7b49a6e7a160d13a7a6050182794f0684e0acf328268fb8e85999a47d4510', NULL, 'قل ان كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم والله غفور رحيم', 3, 6, 21, 1, 1, 54, false, NULL),
    (325, 'tanzil-uthmani-v1.1', 3, 32, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَٰفِرِينَ', '756101ea6daf3baba4f588f4752b261a595e66cb31533416807a73eb77130743', 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَٰفِرِينَ', '756101ea6daf3baba4f588f4752b261a595e66cb31533416807a73eb77130743', '756101ea6daf3baba4f588f4752b261a595e66cb31533416807a73eb77130743', NULL, 'قل اطيعوا الله والرسول فان تولوا فان الله لا يحب الكفرين', 3, 6, 21, 1, 1, 54, false, NULL),
    (326, 'tanzil-uthmani-v1.1', 3, 33, 'إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَٰلَمِينَ', 'eae64286c868603d23358f67f8de1aa520fbacb058d412420588a8a70e86b67f', 'إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَٰلَمِينَ', 'eae64286c868603d23358f67f8de1aa520fbacb058d412420588a8a70e86b67f', 'eae64286c868603d23358f67f8de1aa520fbacb058d412420588a8a70e86b67f', NULL, 'ان الله اصطفي ءادم ونوحا وءال ابرهيم وءال عمرن علي العلمين', 3, 6, 22, 1, 1, 54, false, NULL),
    (327, 'tanzil-uthmani-v1.1', 3, 34, 'ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '38f7517381c9a98b38360dde9bcbabb73e79a43c06a992159542391a52a21a6f', 'ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '38f7517381c9a98b38360dde9bcbabb73e79a43c06a992159542391a52a21a6f', '38f7517381c9a98b38360dde9bcbabb73e79a43c06a992159542391a52a21a6f', NULL, 'ذريه بعضها من بعض والله سميع عليم', 3, 6, 22, 1, 1, 54, false, NULL),
    (328, 'tanzil-uthmani-v1.1', 3, 35, 'إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًا فَتَقَبَّلْ مِنِّىٓ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'd2498ae4059bdbbb7cd5856ff9020e5c62ca6f1c8f856dc6960fb0f396891f35', 'إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًا فَتَقَبَّلْ مِنِّىٓ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'd2498ae4059bdbbb7cd5856ff9020e5c62ca6f1c8f856dc6960fb0f396891f35', 'd2498ae4059bdbbb7cd5856ff9020e5c62ca6f1c8f856dc6960fb0f396891f35', NULL, 'اذ قالت امرات عمرن رب اني نذرت لك ما في بطني محررا فتقبل مني انك انت السميع العليم', 3, 6, 22, 1, 1, 54, false, NULL),
    (329, 'tanzil-uthmani-v1.1', 3, 36, 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'c678aaa3689fe2ac8c13cdd43bb684128cbc0045df56043c4b47cbb27985b4d8', 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'c678aaa3689fe2ac8c13cdd43bb684128cbc0045df56043c4b47cbb27985b4d8', 'c678aaa3689fe2ac8c13cdd43bb684128cbc0045df56043c4b47cbb27985b4d8', NULL, 'فلما وضعتها قالت رب اني وضعتها انثي والله اعلم بما وضعت وليس الذكر كالانثي واني سميتها مريم واني اعيذها بك وذريتها من الشيطن الرجيم', 3, 6, 22, 1, 1, 54, false, NULL),
    (330, 'tanzil-uthmani-v1.1', 3, 37, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَأَنۢبَتَهَا نَبَاتًا حَسَنًا وَكَفَّلَهَا زَكَرِيَّا كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًا قَالَ يَٰمَرْيَمُ أَنَّىٰ لَكِ هَٰذَا قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', '04bd4f62878afe245a8b39111515bc4cf0511a0a1c1e89f42984256f4e292dad', 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍ وَأَنۢبَتَهَا نَبَاتًا حَسَنًا وَكَفَّلَهَا زَكَرِيَّا كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًا قَالَ يَٰمَرْيَمُ أَنَّىٰ لَكِ هَٰذَا قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', '04bd4f62878afe245a8b39111515bc4cf0511a0a1c1e89f42984256f4e292dad', '04bd4f62878afe245a8b39111515bc4cf0511a0a1c1e89f42984256f4e292dad', NULL, 'فتقبلها ربها بقبول حسن وانبتها نباتا حسنا وكفلها زكريا كلما دخل عليها زكريا المحراب وجد عندها رزقا قال يمريم اني لك هذا قالت هو من عند الله ان الله يرزق من يشاء بغير حساب', 3, 6, 22, 1, 1, 54, false, NULL),
    (331, 'tanzil-uthmani-v1.1', 3, 38, 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ ٱلدُّعَآءِ', 'c34ca5c444491f5bf658613e7f57da556133e98aba00a89a43dfbad532f32c25', 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ ٱلدُّعَآءِ', 'c34ca5c444491f5bf658613e7f57da556133e98aba00a89a43dfbad532f32c25', 'c34ca5c444491f5bf658613e7f57da556133e98aba00a89a43dfbad532f32c25', NULL, 'هنالك دعا زكريا ربه قال رب هب لي من لدنك ذريه طيبه انك سميع الدعاء', 3, 6, 22, 1, 1, 55, false, NULL),
    (332, 'tanzil-uthmani-v1.1', 3, 39, 'فَنَادَتْهُ ٱلْمَلَٰٓئِكَةُ وَهُوَ قَآئِمٌ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍ مِّنَ ٱللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ ٱلصَّٰلِحِينَ', '5befdace895ed1455ec7f338a9d7b3babac1ea594c6c723bb32eff56f9dff14c', 'فَنَادَتْهُ ٱلْمَلَٰٓئِكَةُ وَهُوَ قَآئِمٌ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍ مِّنَ ٱللَّهِ وَسَيِّدًا وَحَصُورًا وَنَبِيًّا مِّنَ ٱلصَّٰلِحِينَ', '5befdace895ed1455ec7f338a9d7b3babac1ea594c6c723bb32eff56f9dff14c', '5befdace895ed1455ec7f338a9d7b3babac1ea594c6c723bb32eff56f9dff14c', NULL, 'فنادته الملئكه وهو قائم يصلي في المحراب ان الله يبشرك بيحيي مصدقا بكلمه من الله وسيدا وحصورا ونبيا من الصلحين', 3, 6, 22, 1, 1, 55, false, NULL),
    (333, 'tanzil-uthmani-v1.1', 3, 40, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ', '160bdca8d057f758ef81e1c574a41626ab35536f63b84bcccc67e5a8c5abde49', 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ', '160bdca8d057f758ef81e1c574a41626ab35536f63b84bcccc67e5a8c5abde49', '160bdca8d057f758ef81e1c574a41626ab35536f63b84bcccc67e5a8c5abde49', NULL, 'قال رب اني يكون لي غلم وقد بلغني الكبر وامراتي عاقر قال كذلك الله يفعل ما يشاء', 3, 6, 22, 1, 1, 55, false, NULL),
    (334, 'tanzil-uthmani-v1.1', 3, 41, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمْزًا وَٱذْكُر رَّبَّكَ كَثِيرًا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 'bb173469da346a0ac00ccbea7ee938571e6a34d42c974b0e9255adedccbe1c62', 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمْزًا وَٱذْكُر رَّبَّكَ كَثِيرًا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 'bb173469da346a0ac00ccbea7ee938571e6a34d42c974b0e9255adedccbe1c62', 'bb173469da346a0ac00ccbea7ee938571e6a34d42c974b0e9255adedccbe1c62', NULL, 'قال رب اجعل لي ءايه قال ءايتك الا تكلم الناس ثلثه ايام الا رمزا واذكر ربك كثيرا وسبح بالعشي والابكر', 3, 6, 22, 1, 1, 55, false, NULL),
    (335, 'tanzil-uthmani-v1.1', 3, 42, 'وَإِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَٰلَمِينَ', '5099bb9fb039baa4a0330a2f8faee0fa8972940d7a4a761927c77d1834f24b9d', 'وَإِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَٰلَمِينَ', '5099bb9fb039baa4a0330a2f8faee0fa8972940d7a4a761927c77d1834f24b9d', '5099bb9fb039baa4a0330a2f8faee0fa8972940d7a4a761927c77d1834f24b9d', NULL, 'واذ قالت الملئكه يمريم ان الله اصطفيك وطهرك واصطفيك علي نساء العلمين', 3, 6, 22, 1, 1, 55, false, NULL),
    (336, 'tanzil-uthmani-v1.1', 3, 43, 'يَٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ', 'b5d17924c1619fef18dce40be8e6f9f005d4bb3ff9ba696b639edaaa3ae264a0', 'يَٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ', 'b5d17924c1619fef18dce40be8e6f9f005d4bb3ff9ba696b639edaaa3ae264a0', 'b5d17924c1619fef18dce40be8e6f9f005d4bb3ff9ba696b639edaaa3ae264a0', NULL, 'يمريم اقنتي لربك واسجدي واركعي مع الركعين', 3, 6, 22, 1, 1, 55, false, NULL),
    (337, 'tanzil-uthmani-v1.1', 3, 44, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ', '24299499c9cddede308f14faa8e70e95c9c12d1f620894c51578a2fb8a0b2a4a', 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ', '24299499c9cddede308f14faa8e70e95c9c12d1f620894c51578a2fb8a0b2a4a', '24299499c9cddede308f14faa8e70e95c9c12d1f620894c51578a2fb8a0b2a4a', NULL, 'ذلك من انباء الغيب نوحيه اليك وما كنت لديهم اذ يلقون اقلمهم ايهم يكفل مريم وما كنت لديهم اذ يختصمون', 3, 6, 22, 1, 1, 55, false, NULL),
    (338, 'tanzil-uthmani-v1.1', 3, 45, 'إِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ', 'c3d31931576e6e2e19da2c91d5414a2964e7c37589edd0bbec759456031f75d0', 'إِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ', 'c3d31931576e6e2e19da2c91d5414a2964e7c37589edd0bbec759456031f75d0', 'c3d31931576e6e2e19da2c91d5414a2964e7c37589edd0bbec759456031f75d0', NULL, 'اذ قالت الملئكه يمريم ان الله يبشرك بكلمه منه اسمه المسيح عيسي ابن مريم وجيها في الدنيا والاخره ومن المقربين', 3, 6, 22, 1, 1, 55, false, NULL),
    (339, 'tanzil-uthmani-v1.1', 3, 46, 'وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَمِنَ ٱلصَّٰلِحِينَ', 'ebc4789b57a5db37a752eb2c1f402558ddf59ad08938e7bf2970f4e371924c23', 'وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَمِنَ ٱلصَّٰلِحِينَ', 'ebc4789b57a5db37a752eb2c1f402558ddf59ad08938e7bf2970f4e371924c23', 'ebc4789b57a5db37a752eb2c1f402558ddf59ad08938e7bf2970f4e371924c23', NULL, 'ويكلم الناس في المهد وكهلا ومن الصلحين', 3, 6, 22, 1, 1, 56, false, NULL),
    (340, 'tanzil-uthmani-v1.1', 3, 47, 'قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌ وَلَمْ يَمْسَسْنِى بَشَرٌ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '3a53e1180f156be051b5fd9e54985bb0dd2a3d1be8eb7d64bd33076423953ab0', 'قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌ وَلَمْ يَمْسَسْنِى بَشَرٌ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '3a53e1180f156be051b5fd9e54985bb0dd2a3d1be8eb7d64bd33076423953ab0', '3a53e1180f156be051b5fd9e54985bb0dd2a3d1be8eb7d64bd33076423953ab0', NULL, 'قالت رب اني يكون لي ولد ولم يمسسني بشر قال كذلك الله يخلق ما يشاء اذا قضي امرا فانما يقول له كن فيكون', 3, 6, 22, 1, 1, 56, false, NULL),
    (341, 'tanzil-uthmani-v1.1', 3, 48, 'وَيُعَلِّمُهُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', '3c6b19a1c160ea27b8d01a91ddfa87d5527d78864db90aadcbb0dc007014a399', 'وَيُعَلِّمُهُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', '3c6b19a1c160ea27b8d01a91ddfa87d5527d78864db90aadcbb0dc007014a399', '3c6b19a1c160ea27b8d01a91ddfa87d5527d78864db90aadcbb0dc007014a399', NULL, 'ويعلمه الكتب والحكمه والتوريه والانجيل', 3, 6, 22, 1, 1, 56, false, NULL),
    (342, 'tanzil-uthmani-v1.1', 3, 49, 'وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'e629895544a3fcba23d366bf95f3a7bdae5a9e414b6e38b8143b0f7bf30410a7', 'وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'e629895544a3fcba23d366bf95f3a7bdae5a9e414b6e38b8143b0f7bf30410a7', 'e629895544a3fcba23d366bf95f3a7bdae5a9e414b6e38b8143b0f7bf30410a7', NULL, 'ورسولا الي بني اسرءيل اني قد جئتكم بايه من ربكم اني اخلق لكم من الطين كهيه الطير فانفخ فيه فيكون طيرا باذن الله وابرئ الاكمه والابرص واحي الموتي باذن الله وانبئكم بما تاكلون وما تدخرون في بيوتكم ان في ذلك لايه لكم ان كنتم مؤمنين', 3, 6, 22, 1, 1, 56, false, NULL),
    (343, 'tanzil-uthmani-v1.1', 3, 50, 'وَمُصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ وَجِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'ba5caa589d1b70197e56225ffa81d2ee91817e9b3c80a70d1921a47e44c6bf77', 'وَمُصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ وَجِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'ba5caa589d1b70197e56225ffa81d2ee91817e9b3c80a70d1921a47e44c6bf77', 'ba5caa589d1b70197e56225ffa81d2ee91817e9b3c80a70d1921a47e44c6bf77', NULL, 'ومصدقا لما بين يدي من التوريه ولاحل لكم بعض الذي حرم عليكم وجئتكم بايه من ربكم فاتقوا الله واطيعون', 3, 6, 22, 1, 1, 56, false, NULL),
    (344, 'tanzil-uthmani-v1.1', 3, 51, 'إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '560c5690eabe430ba6d4fc9d720766bb855f3ff5bd318059dfe778b250a28ba1', 'إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '560c5690eabe430ba6d4fc9d720766bb855f3ff5bd318059dfe778b250a28ba1', '560c5690eabe430ba6d4fc9d720766bb855f3ff5bd318059dfe778b250a28ba1', NULL, 'ان الله ربي وربكم فاعبدوه هذا صرط مستقيم', 3, 6, 22, 1, 1, 56, false, NULL),
    (345, 'tanzil-uthmani-v1.1', 3, 52, 'فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ', 'a5c9b1380b0778b3540113e7e12058d1cd0e187f6e9b2e0eb9558c5450c6b31a', 'فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ', 'a5c9b1380b0778b3540113e7e12058d1cd0e187f6e9b2e0eb9558c5450c6b31a', 'a5c9b1380b0778b3540113e7e12058d1cd0e187f6e9b2e0eb9558c5450c6b31a', NULL, 'فلما احس عيسي منهم الكفر قال من انصاري الي الله قال الحواريون نحن انصار الله ءامنا بالله واشهد بانا مسلمون', 3, 6, 23, 1, 1, 56, false, NULL),
    (346, 'tanzil-uthmani-v1.1', 3, 53, 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', '5f8a386cad97e666bdbffeccab9feddeb4089184c7fb71a13351abf44a7edf0d', 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', '5f8a386cad97e666bdbffeccab9feddeb4089184c7fb71a13351abf44a7edf0d', '5f8a386cad97e666bdbffeccab9feddeb4089184c7fb71a13351abf44a7edf0d', NULL, 'ربنا ءامنا بما انزلت واتبعنا الرسول فاكتبنا مع الشهدين', 3, 6, 23, 1, 1, 57, false, NULL),
    (347, 'tanzil-uthmani-v1.1', 3, 54, 'وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', '8eb564129e4b21c2cc276e46e95bc0d64e11910b0337d80a11cd2c9a10e0060a', 'وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', '8eb564129e4b21c2cc276e46e95bc0d64e11910b0337d80a11cd2c9a10e0060a', '8eb564129e4b21c2cc276e46e95bc0d64e11910b0337d80a11cd2c9a10e0060a', NULL, 'ومكروا ومكر الله والله خير المكرين', 3, 6, 23, 1, 1, 57, false, NULL),
    (348, 'tanzil-uthmani-v1.1', 3, 55, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '353c8faedede731076e7127108d5db84b0bfe8c92e62045f239742a78bea2811', 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '353c8faedede731076e7127108d5db84b0bfe8c92e62045f239742a78bea2811', '353c8faedede731076e7127108d5db84b0bfe8c92e62045f239742a78bea2811', NULL, 'اذ قال الله يعيسي اني متوفيك ورافعك الي ومطهرك من الذين كفروا وجاعل الذين اتبعوك فوق الذين كفروا الي يوم القيمه ثم الي مرجعكم فاحكم بينكم فيما كنتم فيه تختلفون', 3, 6, 23, 1, 1, 57, false, NULL),
    (349, 'tanzil-uthmani-v1.1', 3, 56, 'فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًا شَدِيدًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', '31f175bbc0bb28d25dca9715ce4a19de4deedef132cb98f99c6f8f565c04e18c', 'فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًا شَدِيدًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', '31f175bbc0bb28d25dca9715ce4a19de4deedef132cb98f99c6f8f565c04e18c', '31f175bbc0bb28d25dca9715ce4a19de4deedef132cb98f99c6f8f565c04e18c', NULL, 'فاما الذين كفروا فاعذبهم عذابا شديدا في الدنيا والاخره وما لهم من نصرين', 3, 6, 23, 1, 1, 57, false, NULL),
    (350, 'tanzil-uthmani-v1.1', 3, 57, 'وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'b1c251994cc94bee6c44af117c646ac59b6c98d0c47e6cb6326383df0523ba2d', 'وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'b1c251994cc94bee6c44af117c646ac59b6c98d0c47e6cb6326383df0523ba2d', 'b1c251994cc94bee6c44af117c646ac59b6c98d0c47e6cb6326383df0523ba2d', NULL, 'واما الذين ءامنوا وعملوا الصلحت فيوفيهم اجورهم والله لا يحب الظلمين', 3, 6, 23, 1, 1, 57, false, NULL),
    (351, 'tanzil-uthmani-v1.1', 3, 58, 'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْـَٔايَٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ', '8d06383873c743b009e68144647a71db73c7d53bd021360f03b90429f9196366', 'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْـَٔايَٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ', '8d06383873c743b009e68144647a71db73c7d53bd021360f03b90429f9196366', '8d06383873c743b009e68144647a71db73c7d53bd021360f03b90429f9196366', NULL, 'ذلك نتلوه عليك من الايت والذكر الحكيم', 3, 6, 23, 1, 1, 57, false, NULL),
    (352, 'tanzil-uthmani-v1.1', 3, 59, 'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ خَلَقَهُۥ مِن تُرَابٍ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ', '54c23a800d5b6fda467021f8c1fece93543acea93c7958c6acdd32ade146bd68', 'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ خَلَقَهُۥ مِن تُرَابٍ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ', '54c23a800d5b6fda467021f8c1fece93543acea93c7958c6acdd32ade146bd68', '54c23a800d5b6fda467021f8c1fece93543acea93c7958c6acdd32ade146bd68', NULL, 'ان مثل عيسي عند الله كمثل ءادم خلقه من تراب ثم قال له كن فيكون', 3, 6, 23, 1, 1, 57, false, NULL),
    (353, 'tanzil-uthmani-v1.1', 3, 60, 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ', 'b5df17e10e1713d5bfc4cccb131948c9cbc75d067653cd6e21213ae813eaabe1', 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ', 'b5df17e10e1713d5bfc4cccb131948c9cbc75d067653cd6e21213ae813eaabe1', 'b5df17e10e1713d5bfc4cccb131948c9cbc75d067653cd6e21213ae813eaabe1', NULL, 'الحق من ربك فلا تكن من الممترين', 3, 6, 23, 1, 1, 57, false, NULL),
    (354, 'tanzil-uthmani-v1.1', 3, 61, 'فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَٰذِبِينَ', '06c1482ca80cc9d9eb21d86c1eb0861dc70b14236ffa451b16b9b2681af0cf8d', 'فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَٰذِبِينَ', '06c1482ca80cc9d9eb21d86c1eb0861dc70b14236ffa451b16b9b2681af0cf8d', '06c1482ca80cc9d9eb21d86c1eb0861dc70b14236ffa451b16b9b2681af0cf8d', NULL, 'فمن حاجك فيه من بعد ما جاءك من العلم فقل تعالوا ندع ابناءنا وابناءكم ونساءنا ونساءكم وانفسنا وانفسكم ثم نبتهل فنجعل لعنت الله علي الكذبين', 3, 6, 23, 1, 1, 57, false, NULL),
    (355, 'tanzil-uthmani-v1.1', 3, 62, 'إِنَّ هَٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '84a6dd0d5b3880214399719b30269e3ed4ae2b69a3c14f278efb64b72359c6fb', 'إِنَّ هَٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '84a6dd0d5b3880214399719b30269e3ed4ae2b69a3c14f278efb64b72359c6fb', '84a6dd0d5b3880214399719b30269e3ed4ae2b69a3c14f278efb64b72359c6fb', NULL, 'ان هذا لهو القصص الحق وما من اله الا الله وان الله لهو العزيز الحكيم', 3, 6, 23, 1, 1, 58, false, NULL),
    (356, 'tanzil-uthmani-v1.1', 3, 63, 'فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ', '1a8b1a52687787f0987c7e39c9f92c85cc2f7f644b6b07bd91a81883cdc13bef', 'فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ', '1a8b1a52687787f0987c7e39c9f92c85cc2f7f644b6b07bd91a81883cdc13bef', '1a8b1a52687787f0987c7e39c9f92c85cc2f7f644b6b07bd91a81883cdc13bef', NULL, 'فان تولوا فان الله عليم بالمفسدين', 3, 6, 23, 1, 1, 58, false, NULL),
    (357, 'tanzil-uthmani-v1.1', 3, 64, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ ٱللَّهِ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ', 'e527e1ba2ef92f965d21416c4a71b451f54120d78ff7880c875e0a21fa412af5', 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ ٱللَّهِ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ', 'e527e1ba2ef92f965d21416c4a71b451f54120d78ff7880c875e0a21fa412af5', 'e527e1ba2ef92f965d21416c4a71b451f54120d78ff7880c875e0a21fa412af5', NULL, 'قل ياهل الكتب تعالوا الي كلمه سواء بيننا وبينكم الا نعبد الا الله ولا نشرك به شيا ولا يتخذ بعضنا بعضا اربابا من دون الله فان تولوا فقولوا اشهدوا بانا مسلمون', 3, 6, 23, 1, 1, 58, false, NULL),
    (358, 'tanzil-uthmani-v1.1', 3, 65, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ أَفَلَا تَعْقِلُونَ', '9cdf2a2715802e805c16be207ecc682a3e6d1b78605505ed8fc0fee7d6a66f85', 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ أَفَلَا تَعْقِلُونَ', '9cdf2a2715802e805c16be207ecc682a3e6d1b78605505ed8fc0fee7d6a66f85', '9cdf2a2715802e805c16be207ecc682a3e6d1b78605505ed8fc0fee7d6a66f85', NULL, 'ياهل الكتب لم تحاجون في ابرهيم وما انزلت التوريه والانجيل الا من بعده افلا تعقلون', 3, 6, 23, 1, 1, 58, false, NULL),
    (359, 'tanzil-uthmani-v1.1', 3, 66, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ حَٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'b61d0c36636f6ef2fbab91f1d5d941b5719802336f6194d9d340ecc4df6e22f5', 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ حَٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 'b61d0c36636f6ef2fbab91f1d5d941b5719802336f6194d9d340ecc4df6e22f5', 'b61d0c36636f6ef2fbab91f1d5d941b5719802336f6194d9d340ecc4df6e22f5', NULL, 'هانتم هؤلاء حججتم فيما لكم به علم فلم تحاجون فيما ليس لكم به علم والله يعلم وانتم لا تعلمون', 3, 6, 23, 1, 1, 58, false, NULL),
    (360, 'tanzil-uthmani-v1.1', 3, 67, 'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّا وَلَا نَصْرَانِيًّا وَلَٰكِن كَانَ حَنِيفًا مُّسْلِمًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'a00ccd6193a2254ecec168f6326a51b93c3ed9458cca77a3d65de29e638eb063', 'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّا وَلَا نَصْرَانِيًّا وَلَٰكِن كَانَ حَنِيفًا مُّسْلِمًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'a00ccd6193a2254ecec168f6326a51b93c3ed9458cca77a3d65de29e638eb063', 'a00ccd6193a2254ecec168f6326a51b93c3ed9458cca77a3d65de29e638eb063', NULL, 'ما كان ابرهيم يهوديا ولا نصرانيا ولكن كان حنيفا مسلما وما كان من المشركين', 3, 6, 23, 1, 1, 58, false, NULL),
    (361, 'tanzil-uthmani-v1.1', 3, 68, 'إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ', '29bf0e9dede64c4bd8bcb1a818c7ae8ef2e707a6b9740b77fa7f09c7abe36fa2', 'إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ', '29bf0e9dede64c4bd8bcb1a818c7ae8ef2e707a6b9740b77fa7f09c7abe36fa2', '29bf0e9dede64c4bd8bcb1a818c7ae8ef2e707a6b9740b77fa7f09c7abe36fa2', NULL, 'ان اولي الناس بابرهيم للذين اتبعوه وهذا النبي والذين ءامنوا والله ولي المؤمنين', 3, 6, 23, 1, 1, 58, false, NULL),
    (362, 'tanzil-uthmani-v1.1', 3, 69, 'وَدَّت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', '3b312e2aa4bcde46492a3abc1a9bbfe857f9563ef5aed0adf2799e2879872101', 'وَدَّت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', '3b312e2aa4bcde46492a3abc1a9bbfe857f9563ef5aed0adf2799e2879872101', '3b312e2aa4bcde46492a3abc1a9bbfe857f9563ef5aed0adf2799e2879872101', NULL, 'ودت طائفه من اهل الكتب لو يضلونكم وما يضلون الا انفسهم وما يشعرون', 3, 6, 23, 1, 1, 58, false, NULL),
    (363, 'tanzil-uthmani-v1.1', 3, 70, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ', 'efaf72e0448e5a66e42e8e483b4b7b4603d0658f9b32f46505e48ed921dabe22', 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ', 'efaf72e0448e5a66e42e8e483b4b7b4603d0658f9b32f46505e48ed921dabe22', 'efaf72e0448e5a66e42e8e483b4b7b4603d0658f9b32f46505e48ed921dabe22', NULL, 'ياهل الكتب لم تكفرون بايت الله وانتم تشهدون', 3, 6, 23, 1, 1, 58, false, NULL),
    (364, 'tanzil-uthmani-v1.1', 3, 71, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', '560bcef9e2dd383e5b6918b8c4b569fb05e277df6387db421f58dfcfafdc5601', 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', '560bcef9e2dd383e5b6918b8c4b569fb05e277df6387db421f58dfcfafdc5601', '560bcef9e2dd383e5b6918b8c4b569fb05e277df6387db421f58dfcfafdc5601', NULL, 'ياهل الكتب لم تلبسون الحق بالبطل وتكتمون الحق وانتم تعلمون', 3, 6, 23, 1, 1, 59, false, NULL),
    (365, 'tanzil-uthmani-v1.1', 3, 72, 'وَقَالَت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ', '1df0b04b9af28abe59befc0b10fd8832e8e02689dbc1d2755bda5ca91cd3f44a', 'وَقَالَت طَّآئِفَةٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ', '1df0b04b9af28abe59befc0b10fd8832e8e02689dbc1d2755bda5ca91cd3f44a', '1df0b04b9af28abe59befc0b10fd8832e8e02689dbc1d2755bda5ca91cd3f44a', NULL, 'وقالت طائفه من اهل الكتب ءامنوا بالذي انزل علي الذين ءامنوا وجه النهار واكفروا ءاخره لعلهم يرجعون', 3, 6, 23, 1, 1, 59, false, NULL),
    (366, 'tanzil-uthmani-v1.1', 3, 73, 'وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '2aff033d183c8cd2e174935e059cd60ce76dab609b8e1b9706cacc753be3dcb8', 'وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '2aff033d183c8cd2e174935e059cd60ce76dab609b8e1b9706cacc753be3dcb8', '2aff033d183c8cd2e174935e059cd60ce76dab609b8e1b9706cacc753be3dcb8', NULL, 'ولا تؤمنوا الا لمن تبع دينكم قل ان الهدي هدي الله ان يؤتي احد مثل ما اوتيتم او يحاجوكم عند ربكم قل ان الفضل بيد الله يؤتيه من يشاء والله وسع عليم', 3, 6, 23, 1, 1, 59, false, NULL),
    (367, 'tanzil-uthmani-v1.1', 3, 74, 'يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '7bffd3ad71423bcf21c7b2d03b4452af0234e97516f8ddd7474affd1b9a951b6', 'يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '7bffd3ad71423bcf21c7b2d03b4452af0234e97516f8ddd7474affd1b9a951b6', '7bffd3ad71423bcf21c7b2d03b4452af0234e97516f8ddd7474affd1b9a951b6', NULL, 'يختص برحمته من يشاء والله ذو الفضل العظيم', 3, 6, 23, 1, 1, 59, false, NULL),
    (368, 'tanzil-uthmani-v1.1', 3, 75, 'وَمِنْ أَهْلِ ٱلْكِتَٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًا ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّـۧنَ سَبِيلٌ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 'e284c03f0320f227c84f555fb5a36517096ec4e210fc1146cd464ff8cf58f264', 'وَمِنْ أَهْلِ ٱلْكِتَٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًا ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّـۧنَ سَبِيلٌ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 'e284c03f0320f227c84f555fb5a36517096ec4e210fc1146cd464ff8cf58f264', 'e284c03f0320f227c84f555fb5a36517096ec4e210fc1146cd464ff8cf58f264', NULL, 'ومن اهل الكتب من ان تامنه بقنطار يؤده اليك ومنهم من ان تامنه بدينار لا يؤده اليك الا ما دمت عليه قائما ذلك بانهم قالوا ليس علينا في الامين سبيل ويقولون علي الله الكذب وهم يعلمون', 3, 6, 24, 1, 1, 59, false, NULL),
    (369, 'tanzil-uthmani-v1.1', 3, 76, 'بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'c90128e242d5892bac59cc2a138690688751d13d427621647d7f602883a9f8ba', 'بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'c90128e242d5892bac59cc2a138690688751d13d427621647d7f602883a9f8ba', 'c90128e242d5892bac59cc2a138690688751d13d427621647d7f602883a9f8ba', NULL, 'بلي من اوفي بعهده واتقي فان الله يحب المتقين', 3, 6, 24, 1, 1, 59, false, NULL),
    (370, 'tanzil-uthmani-v1.1', 3, 77, 'إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَا خَلَٰقَ لَهُمْ فِى ٱلْـَٔاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'b678945d52d1c724946e49b4067b2daf1adb6464c1130a469471473b3bf3cded', 'إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَا خَلَٰقَ لَهُمْ فِى ٱلْـَٔاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'b678945d52d1c724946e49b4067b2daf1adb6464c1130a469471473b3bf3cded', 'b678945d52d1c724946e49b4067b2daf1adb6464c1130a469471473b3bf3cded', NULL, 'ان الذين يشترون بعهد الله وايمنهم ثمنا قليلا اولئك لا خلق لهم في الاخره ولا يكلمهم الله ولا ينظر اليهم يوم القيمه ولا يزكيهم ولهم عذاب اليم', 3, 6, 24, 1, 1, 59, false, NULL),
    (371, 'tanzil-uthmani-v1.1', 3, 78, 'وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَٰبِ وَمَا هُوَ مِنَ ٱلْكِتَٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', '2c1fc9400b03f96708db5b40e51bfd0f13524579330f3ef96623b16e981658e5', 'وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَٰبِ وَمَا هُوَ مِنَ ٱلْكِتَٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', '2c1fc9400b03f96708db5b40e51bfd0f13524579330f3ef96623b16e981658e5', '2c1fc9400b03f96708db5b40e51bfd0f13524579330f3ef96623b16e981658e5', NULL, 'وان منهم لفريقا يلون السنتهم بالكتب لتحسبوه من الكتب وما هو من الكتب ويقولون هو من عند الله وما هو من عند الله ويقولون علي الله الكذب وهم يعلمون', 3, 6, 24, 1, 1, 60, false, NULL),
    (372, 'tanzil-uthmani-v1.1', 3, 79, 'مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًا لِّى مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُوا۟ رَبَّٰنِيِّـۧنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ', '77cc0787f7f7bac0d8ee9ba822613a669d32812fec1cd17fa694139061a17333', 'مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًا لِّى مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُوا۟ رَبَّٰنِيِّـۧنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ', '77cc0787f7f7bac0d8ee9ba822613a669d32812fec1cd17fa694139061a17333', '77cc0787f7f7bac0d8ee9ba822613a669d32812fec1cd17fa694139061a17333', NULL, 'ما كان لبشر ان يؤتيه الله الكتب والحكم والنبوه ثم يقول للناس كونوا عبادا لي من دون الله ولكن كونوا ربنين بما كنتم تعلمون الكتب وبما كنتم تدرسون', 3, 6, 24, 1, 1, 60, false, NULL),
    (373, 'tanzil-uthmani-v1.1', 3, 80, 'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرْبَابًا أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ', '039cd53833a4db257d02940a223b0f8d7021f24170ddd252b378a47d01bfdd70', 'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرْبَابًا أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ', '039cd53833a4db257d02940a223b0f8d7021f24170ddd252b378a47d01bfdd70', '039cd53833a4db257d02940a223b0f8d7021f24170ddd252b378a47d01bfdd70', NULL, 'ولا يامركم ان تتخذوا الملئكه والنبين اربابا ايامركم بالكفر بعد اذ انتم مسلمون', 3, 6, 24, 1, 1, 60, false, NULL),
    (374, 'tanzil-uthmani-v1.1', 3, 81, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَٰبٍ وَحِكْمَةٍ ثُمَّ جَآءَكُمْ رَسُولٌ مُّصَدِّقٌ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى قَالُوٓا۟ أَقْرَرْنَا قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ', 'f4cebe5e24d788dda9945d19bd66209f1723020b5be69e6d4a186510afdc62b9', 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَٰبٍ وَحِكْمَةٍ ثُمَّ جَآءَكُمْ رَسُولٌ مُّصَدِّقٌ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى قَالُوٓا۟ أَقْرَرْنَا قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ', 'f4cebe5e24d788dda9945d19bd66209f1723020b5be69e6d4a186510afdc62b9', 'f4cebe5e24d788dda9945d19bd66209f1723020b5be69e6d4a186510afdc62b9', NULL, 'واذ اخذ الله ميثق النبين لما ءاتيتكم من كتب وحكمه ثم جاءكم رسول مصدق لما معكم لتؤمنن به ولتنصرنه قال ءاقررتم واخذتم علي ذلكم اصري قالوا اقررنا قال فاشهدوا وانا معكم من الشهدين', 3, 6, 24, 1, 1, 60, false, NULL),
    (375, 'tanzil-uthmani-v1.1', 3, 82, 'فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', '40271d601c45ce38f55887788d67f2a75e4cfd39838cdaff3c86430fa6fe4e37', 'فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', '40271d601c45ce38f55887788d67f2a75e4cfd39838cdaff3c86430fa6fe4e37', '40271d601c45ce38f55887788d67f2a75e4cfd39838cdaff3c86430fa6fe4e37', NULL, 'فمن تولي بعد ذلك فاولئك هم الفسقون', 3, 6, 24, 1, 1, 60, false, NULL),
    (376, 'tanzil-uthmani-v1.1', 3, 83, 'أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَإِلَيْهِ يُرْجَعُونَ', 'd96174c3c5cad2dbf7b8808d5c5ce6bab5ac0b29e6d38a8fa2258f834c1029da', 'أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَإِلَيْهِ يُرْجَعُونَ', 'd96174c3c5cad2dbf7b8808d5c5ce6bab5ac0b29e6d38a8fa2258f834c1029da', 'd96174c3c5cad2dbf7b8808d5c5ce6bab5ac0b29e6d38a8fa2258f834c1029da', NULL, 'افغير دين الله يبغون وله اسلم من في السموت والارض طوعا وكرها واليه يرجعون', 3, 6, 24, 1, 1, 60, false, NULL),
    (377, 'tanzil-uthmani-v1.1', 3, 84, 'قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', '97211d9ccd07813dbe7c266e3f0258f181aa29733268888b1dfd6eb584212834', 'قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', '97211d9ccd07813dbe7c266e3f0258f181aa29733268888b1dfd6eb584212834', '97211d9ccd07813dbe7c266e3f0258f181aa29733268888b1dfd6eb584212834', NULL, 'قل ءامنا بالله وما انزل علينا وما انزل علي ابرهيم واسمعيل واسحق ويعقوب والاسباط وما اوتي موسي وعيسي والنبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون', 3, 6, 24, 1, 1, 61, false, NULL),
    (378, 'tanzil-uthmani-v1.1', 3, 85, 'وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَٰمِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', '7ca2d749633f8930589293cd0bae8714bc03eb3833f77647d7e15ac5f75af021', 'وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَٰمِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', '7ca2d749633f8930589293cd0bae8714bc03eb3833f77647d7e15ac5f75af021', '7ca2d749633f8930589293cd0bae8714bc03eb3833f77647d7e15ac5f75af021', NULL, 'ومن يبتغ غير الاسلم دينا فلن يقبل منه وهو في الاخره من الخسرين', 3, 6, 24, 1, 1, 61, false, NULL),
    (379, 'tanzil-uthmani-v1.1', 3, 86, 'كَيْفَ يَهْدِى ٱللَّهُ قَوْمًا كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّ وَجَآءَهُمُ ٱلْبَيِّنَٰتُ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'f08efe2415a04a956b77753f894b18640a6955b3124be158a55e7aeefa6171d8', 'كَيْفَ يَهْدِى ٱللَّهُ قَوْمًا كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّ وَجَآءَهُمُ ٱلْبَيِّنَٰتُ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'f08efe2415a04a956b77753f894b18640a6955b3124be158a55e7aeefa6171d8', 'f08efe2415a04a956b77753f894b18640a6955b3124be158a55e7aeefa6171d8', NULL, 'كيف يهدي الله قوما كفروا بعد ايمنهم وشهدوا ان الرسول حق وجاءهم البينت والله لا يهدي القوم الظلمين', 3, 6, 24, 1, 1, 61, false, NULL),
    (380, 'tanzil-uthmani-v1.1', 3, 87, 'أُو۟لَٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 'f5e62e1719fcf49b25fad3db605726ecc5a735db875005f5a4d3fb2bcd9f78b4', 'أُو۟لَٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 'f5e62e1719fcf49b25fad3db605726ecc5a735db875005f5a4d3fb2bcd9f78b4', 'f5e62e1719fcf49b25fad3db605726ecc5a735db875005f5a4d3fb2bcd9f78b4', NULL, 'اولئك جزاؤهم ان عليهم لعنه الله والملئكه والناس اجمعين', 3, 6, 24, 1, 1, 61, false, NULL),
    (381, 'tanzil-uthmani-v1.1', 3, 88, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', '9e96454c03bb1a28c88b840f7d10128937e20755297eda9f178208f52de6e7e6', 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', '9e96454c03bb1a28c88b840f7d10128937e20755297eda9f178208f52de6e7e6', '9e96454c03bb1a28c88b840f7d10128937e20755297eda9f178208f52de6e7e6', NULL, 'خلدين فيها لا يخفف عنهم العذاب ولا هم ينظرون', 3, 6, 24, 1, 1, 61, false, NULL),
    (382, 'tanzil-uthmani-v1.1', 3, 89, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'ec341ba847900c3787d19c33ca40340c5c066f6a12700a872808001c94bab6c8', 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'ec341ba847900c3787d19c33ca40340c5c066f6a12700a872808001c94bab6c8', 'ec341ba847900c3787d19c33ca40340c5c066f6a12700a872808001c94bab6c8', NULL, 'الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم', 3, 6, 24, 1, 1, 61, false, NULL),
    (383, 'tanzil-uthmani-v1.1', 3, 90, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلضَّآلُّونَ', '2d48ecae69337eb3385ca162cc76a831aa42e6442ed7cd0929e02cf4266ecfbf', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلضَّآلُّونَ', '2d48ecae69337eb3385ca162cc76a831aa42e6442ed7cd0929e02cf4266ecfbf', '2d48ecae69337eb3385ca162cc76a831aa42e6442ed7cd0929e02cf4266ecfbf', NULL, 'ان الذين كفروا بعد ايمنهم ثم ازدادوا كفرا لن تقبل توبتهم واولئك هم الضالون', 3, 6, 24, 1, 1, 61, false, NULL),
    (384, 'tanzil-uthmani-v1.1', 3, 91, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'f786c2cc17adb781ba61553826355d404bee81c76c4356c458c552707c2a2e0e', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'f786c2cc17adb781ba61553826355d404bee81c76c4356c458c552707c2a2e0e', 'f786c2cc17adb781ba61553826355d404bee81c76c4356c458c552707c2a2e0e', NULL, 'ان الذين كفروا وماتوا وهم كفار فلن يقبل من احدهم ملء الارض ذهبا ولو افتدي به اولئك لهم عذاب اليم وما لهم من نصرين', 3, 6, 24, 1, 1, 61, false, NULL),
    (385, 'tanzil-uthmani-v1.1', 3, 92, 'لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '868f2a6ad78ad55338e44863830e52a13336ecc4a1c4b2697c4eedc8a00063f5', 'لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', '868f2a6ad78ad55338e44863830e52a13336ecc4a1c4b2697c4eedc8a00063f5', '868f2a6ad78ad55338e44863830e52a13336ecc4a1c4b2697c4eedc8a00063f5', NULL, 'لن تنالوا البر حتي تنفقوا مما تحبون وما تنفقوا من شيء فان الله به عليم', 3, 6, 24, 1, 1, 62, false, NULL),
    (386, 'tanzil-uthmani-v1.1', 3, 93, 'كُلُّ ٱلطَّعَامِ كَانَ حِلًّا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَٰدِقِينَ', '31a3d0afe500aeddb5f2d6cf8243090a67db30c8ae76081f45b4ed37e16785b2', 'كُلُّ ٱلطَّعَامِ كَانَ حِلًّا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَٰدِقِينَ', '31a3d0afe500aeddb5f2d6cf8243090a67db30c8ae76081f45b4ed37e16785b2', '31a3d0afe500aeddb5f2d6cf8243090a67db30c8ae76081f45b4ed37e16785b2', NULL, 'كل الطعام كان حلا لبني اسرءيل الا ما حرم اسرءيل علي نفسه من قبل ان تنزل التوريه قل فاتوا بالتوريه فاتلوها ان كنتم صدقين', 4, 7, 25, 1, 1, 62, false, NULL),
    (387, 'tanzil-uthmani-v1.1', 3, 94, 'فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'fc0df56817817f3e48f8f6edb9f6c97b1e26461756f136494847ce9bf4fc1b53', 'فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'fc0df56817817f3e48f8f6edb9f6c97b1e26461756f136494847ce9bf4fc1b53', 'fc0df56817817f3e48f8f6edb9f6c97b1e26461756f136494847ce9bf4fc1b53', NULL, 'فمن افتري علي الله الكذب من بعد ذلك فاولئك هم الظلمون', 4, 7, 25, 1, 1, 62, false, NULL),
    (388, 'tanzil-uthmani-v1.1', 3, 95, 'قُلْ صَدَقَ ٱللَّهُ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'd9be4c5ade703ec0433d6d68ae53b1d2db14b095a92dd7a80796ded0e6eadca4', 'قُلْ صَدَقَ ٱللَّهُ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 'd9be4c5ade703ec0433d6d68ae53b1d2db14b095a92dd7a80796ded0e6eadca4', 'd9be4c5ade703ec0433d6d68ae53b1d2db14b095a92dd7a80796ded0e6eadca4', NULL, 'قل صدق الله فاتبعوا مله ابرهيم حنيفا وما كان من المشركين', 4, 7, 25, 1, 1, 62, false, NULL),
    (389, 'tanzil-uthmani-v1.1', 3, 96, 'إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَٰلَمِينَ', 'bd38f6332ab29a1964c2c6376a2c56f5042e382c2dc46cf6f802ce36c12ee7e4', 'إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًا وَهُدًى لِّلْعَٰلَمِينَ', 'bd38f6332ab29a1964c2c6376a2c56f5042e382c2dc46cf6f802ce36c12ee7e4', 'bd38f6332ab29a1964c2c6376a2c56f5042e382c2dc46cf6f802ce36c12ee7e4', NULL, 'ان اول بيت وضع للناس للذي ببكه مباركا وهدي للعلمين', 4, 7, 25, 1, 1, 62, false, NULL),
    (390, 'tanzil-uthmani-v1.1', 3, 97, 'فِيهِ ءَايَٰتٌۢ بَيِّنَٰتٌ مَّقَامُ إِبْرَٰهِيمَ وَمَن دَخَلَهُۥ كَانَ ءَامِنًا وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًا وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', 'a2b997e57bf947155b0c4317e681368d4dc30649a52a92f51906c9ab8996835d', 'فِيهِ ءَايَٰتٌۢ بَيِّنَٰتٌ مَّقَامُ إِبْرَٰهِيمَ وَمَن دَخَلَهُۥ كَانَ ءَامِنًا وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًا وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', 'a2b997e57bf947155b0c4317e681368d4dc30649a52a92f51906c9ab8996835d', 'a2b997e57bf947155b0c4317e681368d4dc30649a52a92f51906c9ab8996835d', NULL, 'فيه ءايت بينت مقام ابرهيم ومن دخله كان ءامنا ولله علي الناس حج البيت من استطاع اليه سبيلا ومن كفر فان الله غني عن العلمين', 4, 7, 25, 1, 1, 62, false, NULL),
    (391, 'tanzil-uthmani-v1.1', 3, 98, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ', 'be7897ca6dee16b2b678488ad0b485fc417c08c8096cf57da08a04b690c1dc3a', 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ', 'be7897ca6dee16b2b678488ad0b485fc417c08c8096cf57da08a04b690c1dc3a', 'be7897ca6dee16b2b678488ad0b485fc417c08c8096cf57da08a04b690c1dc3a', NULL, 'قل ياهل الكتب لم تكفرون بايت الله والله شهيد علي ما تعملون', 4, 7, 25, 1, 1, 62, false, NULL),
    (392, 'tanzil-uthmani-v1.1', 3, 99, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَآءُ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', '49d80af59dbb830372bea237548125ebfc6154da9bf3f6ee9880c9c4ee9bee03', 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًا وَأَنتُمْ شُهَدَآءُ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', '49d80af59dbb830372bea237548125ebfc6154da9bf3f6ee9880c9c4ee9bee03', '49d80af59dbb830372bea237548125ebfc6154da9bf3f6ee9880c9c4ee9bee03', NULL, 'قل ياهل الكتب لم تصدون عن سبيل الله من ءامن تبغونها عوجا وانتم شهداء وما الله بغفل عما تعملون', 4, 7, 25, 1, 1, 62, false, NULL),
    (393, 'tanzil-uthmani-v1.1', 3, 100, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ يَرُدُّوكُم بَعْدَ إِيمَٰنِكُمْ كَٰفِرِينَ', '1958d154b791faae3858819209ad37ec0ee44d905131fce852a8877faeb48831', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ يَرُدُّوكُم بَعْدَ إِيمَٰنِكُمْ كَٰفِرِينَ', '1958d154b791faae3858819209ad37ec0ee44d905131fce852a8877faeb48831', '1958d154b791faae3858819209ad37ec0ee44d905131fce852a8877faeb48831', NULL, 'يايها الذين ءامنوا ان تطيعوا فريقا من الذين اوتوا الكتب يردوكم بعد ايمنكم كفرين', 4, 7, 25, 1, 1, 62, false, NULL),
    (394, 'tanzil-uthmani-v1.1', 3, 101, 'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'ddd988c5ca07da5fea3fe832e7b0e8394eb6bbcf66172c3c70aaca56b2f65be6', 'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'ddd988c5ca07da5fea3fe832e7b0e8394eb6bbcf66172c3c70aaca56b2f65be6', 'ddd988c5ca07da5fea3fe832e7b0e8394eb6bbcf66172c3c70aaca56b2f65be6', NULL, 'وكيف تكفرون وانتم تتلي عليكم ءايت الله وفيكم رسوله ومن يعتصم بالله فقد هدي الي صرط مستقيم', 4, 7, 25, 1, 1, 63, false, NULL),
    (395, 'tanzil-uthmani-v1.1', 3, 102, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', '981d30b40f39fab5680cff922b7f4ca497a44528e9a5d688b097d9866d299b56', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', '981d30b40f39fab5680cff922b7f4ca497a44528e9a5d688b097d9866d299b56', '981d30b40f39fab5680cff922b7f4ca497a44528e9a5d688b097d9866d299b56', NULL, 'يايها الذين ءامنوا اتقوا الله حق تقاته ولا تموتن الا وانتم مسلمون', 4, 7, 25, 1, 1, 63, false, NULL),
    (396, 'tanzil-uthmani-v1.1', 3, 103, 'وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا۟ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ', '9d5562b36156ef32945702daf47a24e1289ecaa84801aa827bd926acb12418ff', 'وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا۟ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ', '9d5562b36156ef32945702daf47a24e1289ecaa84801aa827bd926acb12418ff', '9d5562b36156ef32945702daf47a24e1289ecaa84801aa827bd926acb12418ff', NULL, 'واعتصموا بحبل الله جميعا ولا تفرقوا واذكروا نعمت الله عليكم اذ كنتم اعداء فالف بين قلوبكم فاصبحتم بنعمته اخونا وكنتم علي شفا حفره من النار فانقذكم منها كذلك يبين الله لكم ءايته لعلكم تهتدون', 4, 7, 25, 1, 1, 63, false, NULL),
    (397, 'tanzil-uthmani-v1.1', 3, 104, 'وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'c9903e72711a6f131494831a06228d453859392819aabfd4fdf4375121215670', 'وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'c9903e72711a6f131494831a06228d453859392819aabfd4fdf4375121215670', 'c9903e72711a6f131494831a06228d453859392819aabfd4fdf4375121215670', NULL, 'ولتكن منكم امه يدعون الي الخير ويامرون بالمعروف وينهون عن المنكر واولئك هم المفلحون', 4, 7, 25, 1, 1, 63, false, NULL),
    (398, 'tanzil-uthmani-v1.1', 3, 105, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌ', 'f2278bd2230af2225867c8202494d0bba74eb5c3cad57a012860d35d63f8012d', 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌ', 'f2278bd2230af2225867c8202494d0bba74eb5c3cad57a012860d35d63f8012d', 'f2278bd2230af2225867c8202494d0bba74eb5c3cad57a012860d35d63f8012d', NULL, 'ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم البينت واولئك لهم عذاب عظيم', 4, 7, 25, 1, 1, 63, false, NULL),
    (399, 'tanzil-uthmani-v1.1', 3, 106, 'يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'e6f259aa5247ca2de44fa67cc3ae9cf15a9e7ce08dbdedb2c5ec126ceca7b104', 'يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 'e6f259aa5247ca2de44fa67cc3ae9cf15a9e7ce08dbdedb2c5ec126ceca7b104', 'e6f259aa5247ca2de44fa67cc3ae9cf15a9e7ce08dbdedb2c5ec126ceca7b104', NULL, 'يوم تبيض وجوه وتسود وجوه فاما الذين اسودت وجوههم اكفرتم بعد ايمنكم فذوقوا العذاب بما كنتم تكفرون', 4, 7, 25, 1, 1, 63, false, NULL),
    (400, 'tanzil-uthmani-v1.1', 3, 107, 'وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَٰلِدُونَ', '9d73fd00a4f71e3970a5bdcfaa83a4e3c274432e5a2c08453c390170fdd6507f', 'وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَٰلِدُونَ', '9d73fd00a4f71e3970a5bdcfaa83a4e3c274432e5a2c08453c390170fdd6507f', '9d73fd00a4f71e3970a5bdcfaa83a4e3c274432e5a2c08453c390170fdd6507f', NULL, 'واما الذين ابيضت وجوههم ففي رحمه الله هم فيها خلدون', 4, 7, 25, 1, 1, 63, false, NULL),
    (401, 'tanzil-uthmani-v1.1', 3, 108, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعَٰلَمِينَ', 'e16470f450aff9ad682027ad56091faa452091f7219a2eba7a1c547ef737f6a8', 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعَٰلَمِينَ', 'e16470f450aff9ad682027ad56091faa452091f7219a2eba7a1c547ef737f6a8', 'e16470f450aff9ad682027ad56091faa452091f7219a2eba7a1c547ef737f6a8', NULL, 'تلك ءايت الله نتلوها عليك بالحق وما الله يريد ظلما للعلمين', 4, 7, 25, 1, 1, 63, false, NULL),
    (402, 'tanzil-uthmani-v1.1', 3, 109, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'd482fdf497a2406b423093fb304e5ae9b397571a0ea57ada7c0ab7fdad123137', 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'd482fdf497a2406b423093fb304e5ae9b397571a0ea57ada7c0ab7fdad123137', 'd482fdf497a2406b423093fb304e5ae9b397571a0ea57ada7c0ab7fdad123137', NULL, 'ولله ما في السموت وما في الارض والي الله ترجع الامور', 4, 7, 25, 1, 1, 64, false, NULL),
    (403, 'tanzil-uthmani-v1.1', 3, 110, 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَٰبِ لَكَانَ خَيْرًا لَّهُم مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَٰسِقُونَ', 'c5504171162b4dad1a53debf7dce9494eaa4b71e752cbbf58a2d9071817f6362', 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَٰبِ لَكَانَ خَيْرًا لَّهُم مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَٰسِقُونَ', 'c5504171162b4dad1a53debf7dce9494eaa4b71e752cbbf58a2d9071817f6362', 'c5504171162b4dad1a53debf7dce9494eaa4b71e752cbbf58a2d9071817f6362', NULL, 'كنتم خير امه اخرجت للناس تامرون بالمعروف وتنهون عن المنكر وتؤمنون بالله ولو ءامن اهل الكتب لكان خيرا لهم منهم المؤمنون واكثرهم الفسقون', 4, 7, 25, 1, 1, 64, false, NULL),
    (404, 'tanzil-uthmani-v1.1', 3, 111, 'لَن يَضُرُّوكُمْ إِلَّآ أَذًى وَإِن يُقَٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ', 'dbc311feb432c7df790d48b720624d96862d3a9eb2557a29dd87b570dc7a7f9d', 'لَن يَضُرُّوكُمْ إِلَّآ أَذًى وَإِن يُقَٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ', 'dbc311feb432c7df790d48b720624d96862d3a9eb2557a29dd87b570dc7a7f9d', 'dbc311feb432c7df790d48b720624d96862d3a9eb2557a29dd87b570dc7a7f9d', NULL, 'لن يضروكم الا اذي وان يقتلوكم يولوكم الادبار ثم لا ينصرون', 4, 7, 25, 1, 1, 64, false, NULL),
    (405, 'tanzil-uthmani-v1.1', 3, 112, 'ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍ مِّنَ ٱللَّهِ وَحَبْلٍ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', '85409c7c0814865f499a822d5871f76191697aa31ee33e3c0f9d8e78e095ca75', 'ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍ مِّنَ ٱللَّهِ وَحَبْلٍ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', '85409c7c0814865f499a822d5871f76191697aa31ee33e3c0f9d8e78e095ca75', '85409c7c0814865f499a822d5871f76191697aa31ee33e3c0f9d8e78e095ca75', NULL, 'ضربت عليهم الذله اين ما ثقفوا الا بحبل من الله وحبل من الناس وباءو بغضب من الله وضربت عليهم المسكنه ذلك بانهم كانوا يكفرون بايت الله ويقتلون الانبياء بغير حق ذلك بما عصوا وكانوا يعتدون', 4, 7, 25, 1, 1, 64, false, NULL),
    (406, 'tanzil-uthmani-v1.1', 3, 113, 'لَيْسُوا۟ سَوَآءً مِّنْ أَهْلِ ٱلْكِتَٰبِ أُمَّةٌ قَآئِمَةٌ يَتْلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ', '9cd5d306c59ea5ff51169b2f5c29a71c4e92b752162d643df457fd6227d9cf4e', 'لَيْسُوا۟ سَوَآءً مِّنْ أَهْلِ ٱلْكِتَٰبِ أُمَّةٌ قَآئِمَةٌ يَتْلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ', '9cd5d306c59ea5ff51169b2f5c29a71c4e92b752162d643df457fd6227d9cf4e', '9cd5d306c59ea5ff51169b2f5c29a71c4e92b752162d643df457fd6227d9cf4e', NULL, 'ليسوا سواء من اهل الكتب امه قائمه يتلون ءايت الله ءاناء اليل وهم يسجدون', 4, 7, 26, 1, 1, 64, false, NULL),
    (407, 'tanzil-uthmani-v1.1', 3, 114, 'يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ', 'b4d2ad008ee4f35b9899b16f5440778fbcff8b3ba4e103a329e095c653c169a3', 'يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ', 'b4d2ad008ee4f35b9899b16f5440778fbcff8b3ba4e103a329e095c653c169a3', 'b4d2ad008ee4f35b9899b16f5440778fbcff8b3ba4e103a329e095c653c169a3', NULL, 'يؤمنون بالله واليوم الاخر ويامرون بالمعروف وينهون عن المنكر ويسرعون في الخيرت واولئك من الصلحين', 4, 7, 26, 1, 1, 64, false, NULL),
    (408, 'tanzil-uthmani-v1.1', 3, 115, 'وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍ فَلَن يُكْفَرُوهُ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', '729edeb5ab29ac6ac277db20cf2b90574b58085ce7298396cde51f7cee93ddbe', 'وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍ فَلَن يُكْفَرُوهُ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', '729edeb5ab29ac6ac277db20cf2b90574b58085ce7298396cde51f7cee93ddbe', '729edeb5ab29ac6ac277db20cf2b90574b58085ce7298396cde51f7cee93ddbe', NULL, 'وما يفعلوا من خير فلن يكفروه والله عليم بالمتقين', 4, 7, 26, 1, 1, 64, false, NULL),
    (409, 'tanzil-uthmani-v1.1', 3, 116, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '475ddeb7e09ffdeae4fe90a355679c71f2021d92329ea3d1436d1dbbce061a1b', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '475ddeb7e09ffdeae4fe90a355679c71f2021d92329ea3d1436d1dbbce061a1b', '475ddeb7e09ffdeae4fe90a355679c71f2021d92329ea3d1436d1dbbce061a1b', NULL, 'ان الذين كفروا لن تغني عنهم امولهم ولا اولدهم من الله شيا واولئك اصحب النار هم فيها خلدون', 4, 7, 26, 1, 1, 65, false, NULL),
    (410, 'tanzil-uthmani-v1.1', 3, 117, 'مَثَلُ مَا يُنفِقُونَ فِى هَٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ', 'b76207552774d2c81ae01ab4917d88fe337fa4c681ec3acc2f9356aabe4c4528', 'مَثَلُ مَا يُنفِقُونَ فِى هَٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ', 'b76207552774d2c81ae01ab4917d88fe337fa4c681ec3acc2f9356aabe4c4528', 'b76207552774d2c81ae01ab4917d88fe337fa4c681ec3acc2f9356aabe4c4528', NULL, 'مثل ما ينفقون في هذه الحيوه الدنيا كمثل ريح فيها صر اصابت حرث قوم ظلموا انفسهم فاهلكته وما ظلمهم الله ولكن انفسهم يظلمون', 4, 7, 26, 1, 1, 65, false, NULL),
    (411, 'tanzil-uthmani-v1.1', 3, 118, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَٰتِ إِن كُنتُمْ تَعْقِلُونَ', 'b0b69c794287f9cc1bb502f0c3e9fb7a2d228d4e7239e5abe783076d1d499e7e', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةً مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَٰتِ إِن كُنتُمْ تَعْقِلُونَ', 'b0b69c794287f9cc1bb502f0c3e9fb7a2d228d4e7239e5abe783076d1d499e7e', 'b0b69c794287f9cc1bb502f0c3e9fb7a2d228d4e7239e5abe783076d1d499e7e', NULL, 'يايها الذين ءامنوا لا تتخذوا بطانه من دونكم لا يالونكم خبالا ودوا ما عنتم قد بدت البغضاء من افوههم وما تخفي صدورهم اكبر قد بينا لكم الايت ان كنتم تعقلون', 4, 7, 26, 1, 1, 65, false, NULL),
    (412, 'tanzil-uthmani-v1.1', 3, 119, 'هَٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ قُلْ مُوتُوا۟ بِغَيْظِكُمْ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '6ccbeadd161a283f124135c8a27744c9ba9e3790e51a0fde265e36904800d89a', 'هَٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ قُلْ مُوتُوا۟ بِغَيْظِكُمْ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '6ccbeadd161a283f124135c8a27744c9ba9e3790e51a0fde265e36904800d89a', '6ccbeadd161a283f124135c8a27744c9ba9e3790e51a0fde265e36904800d89a', NULL, 'هانتم اولاء تحبونهم ولا يحبونكم وتؤمنون بالكتب كله واذا لقوكم قالوا ءامنا واذا خلوا عضوا عليكم الانامل من الغيظ قل موتوا بغيظكم ان الله عليم بذات الصدور', 4, 7, 26, 1, 1, 65, false, NULL),
    (413, 'tanzil-uthmani-v1.1', 3, 120, 'إِن تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا۟ بِهَا وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ', 'ae6316dbcafe3157bae849409fa3cbbd120357e26cd7995de683ea6c14c24183', 'إِن تَمْسَسْكُمْ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌ يَفْرَحُوا۟ بِهَا وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ', 'ae6316dbcafe3157bae849409fa3cbbd120357e26cd7995de683ea6c14c24183', 'ae6316dbcafe3157bae849409fa3cbbd120357e26cd7995de683ea6c14c24183', NULL, 'ان تمسسكم حسنه تسؤهم وان تصبكم سيئه يفرحوا بها وان تصبروا وتتقوا لا يضركم كيدهم شيا ان الله بما يعملون محيط', 4, 7, 26, 1, 1, 65, false, NULL),
    (414, 'tanzil-uthmani-v1.1', 3, 121, 'وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَٰعِدَ لِلْقِتَالِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '0e879acd2ae8328472ff04df31949db5325830b28f54134ea2cfe844ed019806', 'وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَٰعِدَ لِلْقِتَالِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '0e879acd2ae8328472ff04df31949db5325830b28f54134ea2cfe844ed019806', '0e879acd2ae8328472ff04df31949db5325830b28f54134ea2cfe844ed019806', NULL, 'واذ غدوت من اهلك تبوئ المؤمنين مقعد للقتال والله سميع عليم', 4, 7, 26, 1, 1, 65, false, NULL),
    (415, 'tanzil-uthmani-v1.1', 3, 122, 'إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '9efadd60fbe8d74eb982e21097dd21e52afa72bf5010fe8b76b790106dbc2407', 'إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '9efadd60fbe8d74eb982e21097dd21e52afa72bf5010fe8b76b790106dbc2407', '9efadd60fbe8d74eb982e21097dd21e52afa72bf5010fe8b76b790106dbc2407', NULL, 'اذ همت طائفتان منكم ان تفشلا والله وليهما وعلي الله فليتوكل المؤمنون', 4, 7, 26, 1, 1, 66, false, NULL),
    (416, 'tanzil-uthmani-v1.1', 3, 123, 'وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ', 'a1b4782bc26883f63babf663f946c6f5df1b262e8ee31128d913668eaa438d6c', 'وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ', 'a1b4782bc26883f63babf663f946c6f5df1b262e8ee31128d913668eaa438d6c', 'a1b4782bc26883f63babf663f946c6f5df1b262e8ee31128d913668eaa438d6c', NULL, 'ولقد نصركم الله ببدر وانتم اذله فاتقوا الله لعلكم تشكرون', 4, 7, 26, 1, 1, 66, false, NULL),
    (417, 'tanzil-uthmani-v1.1', 3, 124, 'إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُنزَلِينَ', 'eca564e3fd28e4bfc7d425dff553b2cbe541d3f3a126e678c247d8ca88f23cb0', 'إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُنزَلِينَ', 'eca564e3fd28e4bfc7d425dff553b2cbe541d3f3a126e678c247d8ca88f23cb0', 'eca564e3fd28e4bfc7d425dff553b2cbe541d3f3a126e678c247d8ca88f23cb0', NULL, 'اذ تقول للمؤمنين الن يكفيكم ان يمدكم ربكم بثلثه ءالف من الملئكه منزلين', 4, 7, 26, 1, 1, 66, false, NULL),
    (418, 'tanzil-uthmani-v1.1', 3, 125, 'بَلَىٰٓ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَٰفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُسَوِّمِينَ', '653153f7dff8411b852e660091910c53d53c459ba024da2ee3ca6c8259c24f4c', 'بَلَىٰٓ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَٰفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُسَوِّمِينَ', '653153f7dff8411b852e660091910c53d53c459ba024da2ee3ca6c8259c24f4c', '653153f7dff8411b852e660091910c53d53c459ba024da2ee3ca6c8259c24f4c', NULL, 'بلي ان تصبروا وتتقوا وياتوكم من فورهم هذا يمددكم ربكم بخمسه ءالف من الملئكه مسومين', 4, 7, 26, 1, 1, 66, false, NULL),
    (419, 'tanzil-uthmani-v1.1', 3, 126, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '55a79f3983db188a57940308a2e96e3742ae48f7d65a48654e160433821c7185', 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '55a79f3983db188a57940308a2e96e3742ae48f7d65a48654e160433821c7185', '55a79f3983db188a57940308a2e96e3742ae48f7d65a48654e160433821c7185', NULL, 'وما جعله الله الا بشري لكم ولتطمئن قلوبكم به وما النصر الا من عند الله العزيز الحكيم', 4, 7, 26, 1, 1, 66, false, NULL),
    (420, 'tanzil-uthmani-v1.1', 3, 127, 'لِيَقْطَعَ طَرَفًا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ', 'ef74406b33a15b51fb0e4c1692066ec7a2651a1c9318f89d0f9cf992c3a08c5a', 'لِيَقْطَعَ طَرَفًا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ', 'ef74406b33a15b51fb0e4c1692066ec7a2651a1c9318f89d0f9cf992c3a08c5a', 'ef74406b33a15b51fb0e4c1692066ec7a2651a1c9318f89d0f9cf992c3a08c5a', NULL, 'ليقطع طرفا من الذين كفروا او يكبتهم فينقلبوا خائبين', 4, 7, 26, 1, 1, 66, false, NULL),
    (421, 'tanzil-uthmani-v1.1', 3, 128, 'لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ', '52905ff77da1e7e7ed8e36b186261bf530f0b3629bbb0aca951dde212224f992', 'لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ', '52905ff77da1e7e7ed8e36b186261bf530f0b3629bbb0aca951dde212224f992', '52905ff77da1e7e7ed8e36b186261bf530f0b3629bbb0aca951dde212224f992', NULL, 'ليس لك من الامر شيء او يتوب عليهم او يعذبهم فانهم ظلمون', 4, 7, 26, 1, 1, 66, false, NULL),
    (422, 'tanzil-uthmani-v1.1', 3, 129, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '7054eba296c349f2c84a951be8028c2af66d071487610a5a0812e07e484702d9', 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '7054eba296c349f2c84a951be8028c2af66d071487610a5a0812e07e484702d9', '7054eba296c349f2c84a951be8028c2af66d071487610a5a0812e07e484702d9', NULL, 'ولله ما في السموت وما في الارض يغفر لمن يشاء ويعذب من يشاء والله غفور رحيم', 4, 7, 26, 1, 1, 66, false, NULL),
    (423, 'tanzil-uthmani-v1.1', 3, 130, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَٰفًا مُّضَٰعَفَةً وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', '272cb59e2f27c60552b7815a8bd3b19bb6cf29e83f5fd9052c2ebfdc39915e3b', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَٰفًا مُّضَٰعَفَةً وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', '272cb59e2f27c60552b7815a8bd3b19bb6cf29e83f5fd9052c2ebfdc39915e3b', '272cb59e2f27c60552b7815a8bd3b19bb6cf29e83f5fd9052c2ebfdc39915e3b', NULL, 'يايها الذين ءامنوا لا تاكلوا الربوا اضعفا مضعفه واتقوا الله لعلكم تفلحون', 4, 7, 26, 1, 1, 66, false, NULL),
    (424, 'tanzil-uthmani-v1.1', 3, 131, 'وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَٰفِرِينَ', 'dc86d459766f0121e756c97105483ca7418cf79d6f9fc28e0b8ff2341b962e10', 'وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَٰفِرِينَ', 'dc86d459766f0121e756c97105483ca7418cf79d6f9fc28e0b8ff2341b962e10', 'dc86d459766f0121e756c97105483ca7418cf79d6f9fc28e0b8ff2341b962e10', NULL, 'واتقوا النار التي اعدت للكفرين', 4, 7, 26, 1, 1, 66, false, NULL),
    (425, 'tanzil-uthmani-v1.1', 3, 132, 'وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', '1b23bc76f29fc2db005671ce62e68a53a8ebfd29d3b8b609124132fcda02bbea', 'وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', '1b23bc76f29fc2db005671ce62e68a53a8ebfd29d3b8b609124132fcda02bbea', '1b23bc76f29fc2db005671ce62e68a53a8ebfd29d3b8b609124132fcda02bbea', NULL, 'واطيعوا الله والرسول لعلكم ترحمون', 4, 7, 26, 1, 1, 66, false, NULL),
    (426, 'tanzil-uthmani-v1.1', 3, 133, 'وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ', 'df8ac0ada54a23ca7d3399235e0491384276d9cba36b05ff014256fa239c7b50', 'وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ', 'df8ac0ada54a23ca7d3399235e0491384276d9cba36b05ff014256fa239c7b50', 'df8ac0ada54a23ca7d3399235e0491384276d9cba36b05ff014256fa239c7b50', NULL, 'وسارعوا الي مغفره من ربكم وجنه عرضها السموت والارض اعدت للمتقين', 4, 7, 27, 1, 1, 67, false, NULL),
    (427, 'tanzil-uthmani-v1.1', 3, 134, 'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', '4cfffb9b297c873f79fc62736c90e68d6a10c9f1f1861848fb22fa96a445d832', 'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', '4cfffb9b297c873f79fc62736c90e68d6a10c9f1f1861848fb22fa96a445d832', '4cfffb9b297c873f79fc62736c90e68d6a10c9f1f1861848fb22fa96a445d832', NULL, 'الذين ينفقون في السراء والضراء والكظمين الغيظ والعافين عن الناس والله يحب المحسنين', 4, 7, 27, 1, 1, 67, false, NULL),
    (428, 'tanzil-uthmani-v1.1', 3, 135, 'وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ', '94f846cc661942077f58e2a49abef3673a730278c4777bbd5da6b84ba29044fc', 'وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ', '94f846cc661942077f58e2a49abef3673a730278c4777bbd5da6b84ba29044fc', '94f846cc661942077f58e2a49abef3673a730278c4777bbd5da6b84ba29044fc', NULL, 'والذين اذا فعلوا فحشه او ظلموا انفسهم ذكروا الله فاستغفروا لذنوبهم ومن يغفر الذنوب الا الله ولم يصروا علي ما فعلوا وهم يعلمون', 4, 7, 27, 1, 1, 67, false, NULL),
    (429, 'tanzil-uthmani-v1.1', 3, 136, 'أُو۟لَٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', '2f3a96349429e27d909b95782363a18aef0c0dc6bf363b5772654238116ced2a', 'أُو۟لَٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', '2f3a96349429e27d909b95782363a18aef0c0dc6bf363b5772654238116ced2a', '2f3a96349429e27d909b95782363a18aef0c0dc6bf363b5772654238116ced2a', NULL, 'اولئك جزاؤهم مغفره من ربهم وجنت تجري من تحتها الانهر خلدين فيها ونعم اجر العملين', 4, 7, 27, 1, 1, 67, false, NULL),
    (430, 'tanzil-uthmani-v1.1', 3, 137, 'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'ba5de587f13efa5a1280f2b9eea0102411615d3c6a7ee8a7a5257edb4427d9dd', 'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'ba5de587f13efa5a1280f2b9eea0102411615d3c6a7ee8a7a5257edb4427d9dd', 'ba5de587f13efa5a1280f2b9eea0102411615d3c6a7ee8a7a5257edb4427d9dd', NULL, 'قد خلت من قبلكم سنن فسيروا في الارض فانظروا كيف كان عقبه المكذبين', 4, 7, 27, 1, 1, 67, false, NULL),
    (431, 'tanzil-uthmani-v1.1', 3, 138, 'هَٰذَا بَيَانٌ لِّلنَّاسِ وَهُدًى وَمَوْعِظَةٌ لِّلْمُتَّقِينَ', 'fd99e3c5ebb2e9c6444ff0129d25684a670fa5174c4cf70898557ee168c4e616', 'هَٰذَا بَيَانٌ لِّلنَّاسِ وَهُدًى وَمَوْعِظَةٌ لِّلْمُتَّقِينَ', 'fd99e3c5ebb2e9c6444ff0129d25684a670fa5174c4cf70898557ee168c4e616', 'fd99e3c5ebb2e9c6444ff0129d25684a670fa5174c4cf70898557ee168c4e616', NULL, 'هذا بيان للناس وهدي وموعظه للمتقين', 4, 7, 27, 1, 1, 67, false, NULL),
    (432, 'tanzil-uthmani-v1.1', 3, 139, 'وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', '414550a2d3e7391c09b87a5b1e7d16fa260564d8d1c11f88b2f9fda5d0ac6477', 'وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', '414550a2d3e7391c09b87a5b1e7d16fa260564d8d1c11f88b2f9fda5d0ac6477', '414550a2d3e7391c09b87a5b1e7d16fa260564d8d1c11f88b2f9fda5d0ac6477', NULL, 'ولا تهنوا ولا تحزنوا وانتم الاعلون ان كنتم مؤمنين', 4, 7, 27, 1, 1, 67, false, NULL),
    (433, 'tanzil-uthmani-v1.1', 3, 140, 'إِن يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌ مِّثْلُهُۥ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'f7c3708b74b6a369ceea067c5ef41f79aea711cd0cca99e36913200f1cc4d962', 'إِن يَمْسَسْكُمْ قَرْحٌ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌ مِّثْلُهُۥ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 'f7c3708b74b6a369ceea067c5ef41f79aea711cd0cca99e36913200f1cc4d962', 'f7c3708b74b6a369ceea067c5ef41f79aea711cd0cca99e36913200f1cc4d962', NULL, 'ان يمسسكم قرح فقد مس القوم قرح مثله وتلك الايام نداولها بين الناس وليعلم الله الذين ءامنوا ويتخذ منكم شهداء والله لا يحب الظلمين', 4, 7, 27, 1, 1, 67, false, NULL),
    (434, 'tanzil-uthmani-v1.1', 3, 141, 'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَٰفِرِينَ', '98ab59865ba01d38a79facd31fb59ecac2ad08965f10102d3f442d3ab37534d3', 'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَٰفِرِينَ', '98ab59865ba01d38a79facd31fb59ecac2ad08965f10102d3f442d3ab37534d3', '98ab59865ba01d38a79facd31fb59ecac2ad08965f10102d3f442d3ab37534d3', NULL, 'وليمحص الله الذين ءامنوا ويمحق الكفرين', 4, 7, 27, 1, 1, 68, false, NULL),
    (435, 'tanzil-uthmani-v1.1', 3, 142, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّٰبِرِينَ', '116d7e870b95a03a5435482930fc82854732ad8feeb8776d0eeca522387acea8', 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّٰبِرِينَ', '116d7e870b95a03a5435482930fc82854732ad8feeb8776d0eeca522387acea8', '116d7e870b95a03a5435482930fc82854732ad8feeb8776d0eeca522387acea8', NULL, 'ام حسبتم ان تدخلوا الجنه ولما يعلم الله الذين جهدوا منكم ويعلم الصبرين', 4, 7, 27, 1, 1, 68, false, NULL),
    (436, 'tanzil-uthmani-v1.1', 3, 143, 'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ', '6ea0f43eac55e390cc27803572af5b93f3c0c37f7e63e27a6ecb6f23cfedde3c', 'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ', '6ea0f43eac55e390cc27803572af5b93f3c0c37f7e63e27a6ecb6f23cfedde3c', '6ea0f43eac55e390cc27803572af5b93f3c0c37f7e63e27a6ecb6f23cfedde3c', NULL, 'ولقد كنتم تمنون الموت من قبل ان تلقوه فقد رايتموه وانتم تنظرون', 4, 7, 27, 1, 1, 68, false, NULL),
    (437, 'tanzil-uthmani-v1.1', 3, 144, 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًٔا وَسَيَجْزِى ٱللَّهُ ٱلشَّٰكِرِينَ', 'b408a7c36f01336eb2cab76636549a5e08c9edfbbbecf9ff74b816b147a80e0e', 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًٔا وَسَيَجْزِى ٱللَّهُ ٱلشَّٰكِرِينَ', 'b408a7c36f01336eb2cab76636549a5e08c9edfbbbecf9ff74b816b147a80e0e', 'b408a7c36f01336eb2cab76636549a5e08c9edfbbbecf9ff74b816b147a80e0e', NULL, 'وما محمد الا رسول قد خلت من قبله الرسل افاين مات او قتل انقلبتم علي اعقبكم ومن ينقلب علي عقبيه فلن يضر الله شيا وسيجزي الله الشكرين', 4, 7, 27, 1, 1, 68, false, NULL),
    (438, 'tanzil-uthmani-v1.1', 3, 145, 'وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَٰبًا مُّؤَجَّلًا وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْـَٔاخِرَةِ نُؤْتِهِۦ مِنْهَا وَسَنَجْزِى ٱلشَّٰكِرِينَ', '1cf5d3e680b998e56870c85186046804fcb1c0b2e34fb84269153ea303af9380', 'وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَٰبًا مُّؤَجَّلًا وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْـَٔاخِرَةِ نُؤْتِهِۦ مِنْهَا وَسَنَجْزِى ٱلشَّٰكِرِينَ', '1cf5d3e680b998e56870c85186046804fcb1c0b2e34fb84269153ea303af9380', '1cf5d3e680b998e56870c85186046804fcb1c0b2e34fb84269153ea303af9380', NULL, 'وما كان لنفس ان تموت الا باذن الله كتبا مؤجلا ومن يرد ثواب الدنيا نؤته منها ومن يرد ثواب الاخره نؤته منها وسنجزي الشكرين', 4, 7, 27, 1, 1, 68, false, NULL),
    (439, 'tanzil-uthmani-v1.1', 3, 146, 'وَكَأَيِّن مِّن نَّبِىٍّ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ', '36b85ebeacf63c2375898021912b8b8f89b9a414ca11735f539937aac509c509', 'وَكَأَيِّن مِّن نَّبِىٍّ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ', '36b85ebeacf63c2375898021912b8b8f89b9a414ca11735f539937aac509c509', '36b85ebeacf63c2375898021912b8b8f89b9a414ca11735f539937aac509c509', NULL, 'وكاين من نبي قتل معه ربيون كثير فما وهنوا لما اصابهم في سبيل الله وما ضعفوا وما استكانوا والله يحب الصبرين', 4, 7, 27, 1, 1, 68, false, NULL),
    (440, 'tanzil-uthmani-v1.1', 3, 147, 'وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '9d7949d92f5abc1016ec29ecb6c9f1eec912668cbb37e1feaaacf77c1e273604', 'وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '9d7949d92f5abc1016ec29ecb6c9f1eec912668cbb37e1feaaacf77c1e273604', '9d7949d92f5abc1016ec29ecb6c9f1eec912668cbb37e1feaaacf77c1e273604', NULL, 'وما كان قولهم الا ان قالوا ربنا اغفر لنا ذنوبنا واسرافنا في امرنا وثبت اقدامنا وانصرنا علي القوم الكفرين', 4, 7, 27, 1, 1, 68, false, NULL),
    (441, 'tanzil-uthmani-v1.1', 3, 148, 'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْـَٔاخِرَةِ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', '6d3ea7a3bfb39e3a6c96f79c5fddee59ed8017e98c40ee5460eea4322a0e0ff7', 'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْـَٔاخِرَةِ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', '6d3ea7a3bfb39e3a6c96f79c5fddee59ed8017e98c40ee5460eea4322a0e0ff7', '6d3ea7a3bfb39e3a6c96f79c5fddee59ed8017e98c40ee5460eea4322a0e0ff7', NULL, 'فاتيهم الله ثواب الدنيا وحسن ثواب الاخره والله يحب المحسنين', 4, 7, 27, 1, 1, 68, false, NULL),
    (442, 'tanzil-uthmani-v1.1', 3, 149, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَٰبِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', '082a898b63abe31e79790082a0cf69b2849c1451a160915b86064b5b88d38115', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَٰبِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', '082a898b63abe31e79790082a0cf69b2849c1451a160915b86064b5b88d38115', '082a898b63abe31e79790082a0cf69b2849c1451a160915b86064b5b88d38115', NULL, 'يايها الذين ءامنوا ان تطيعوا الذين كفروا يردوكم علي اعقبكم فتنقلبوا خسرين', 4, 7, 27, 1, 1, 69, false, NULL),
    (443, 'tanzil-uthmani-v1.1', 3, 150, 'بَلِ ٱللَّهُ مَوْلَىٰكُمْ وَهُوَ خَيْرُ ٱلنَّٰصِرِينَ', '12a6ec75ce44505e1303aee125297cd31b3ca4184e152990597d817854add4fb', 'بَلِ ٱللَّهُ مَوْلَىٰكُمْ وَهُوَ خَيْرُ ٱلنَّٰصِرِينَ', '12a6ec75ce44505e1303aee125297cd31b3ca4184e152990597d817854add4fb', '12a6ec75ce44505e1303aee125297cd31b3ca4184e152990597d817854add4fb', NULL, 'بل الله موليكم وهو خير النصرين', 4, 7, 27, 1, 1, 69, false, NULL),
    (444, 'tanzil-uthmani-v1.1', 3, 151, 'سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَمَأْوَىٰهُمُ ٱلنَّارُ وَبِئْسَ مَثْوَى ٱلظَّٰلِمِينَ', '5f79fa628a0361e7c38200657d5bba28e89fb7c29fa4cc64c18bf06de2b8a608', 'سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَمَأْوَىٰهُمُ ٱلنَّارُ وَبِئْسَ مَثْوَى ٱلظَّٰلِمِينَ', '5f79fa628a0361e7c38200657d5bba28e89fb7c29fa4cc64c18bf06de2b8a608', '5f79fa628a0361e7c38200657d5bba28e89fb7c29fa4cc64c18bf06de2b8a608', NULL, 'سنلقي في قلوب الذين كفروا الرعب بما اشركوا بالله ما لم ينزل به سلطنا وماويهم النار وبئس مثوي الظلمين', 4, 7, 27, 1, 1, 69, false, NULL),
    (445, 'tanzil-uthmani-v1.1', 3, 152, 'وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْـَٔاخِرَةَ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ وَلَقَدْ عَفَا عَنكُمْ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ', '3cc20357507a944b4e0bae386ea6f0a3e4f70565fa7d48da25b2bc6516ab1b8f', 'وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْـَٔاخِرَةَ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ وَلَقَدْ عَفَا عَنكُمْ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ', '3cc20357507a944b4e0bae386ea6f0a3e4f70565fa7d48da25b2bc6516ab1b8f', '3cc20357507a944b4e0bae386ea6f0a3e4f70565fa7d48da25b2bc6516ab1b8f', NULL, 'ولقد صدقكم الله وعده اذ تحسونهم باذنه حتي اذا فشلتم وتنزعتم في الامر وعصيتم من بعد ما اريكم ما تحبون منكم من يريد الدنيا ومنكم من يريد الاخره ثم صرفكم عنهم ليبتليكم ولقد عفا عنكم والله ذو فضل علي المؤمنين', 4, 7, 27, 1, 1, 69, false, NULL),
    (446, 'tanzil-uthmani-v1.1', 3, 153, 'إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَٰبَكُمْ غَمًّۢا بِغَمٍّ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَٰبَكُمْ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '7b728ffb7d2da1ca041377ccd8de0b2934c204e252a9fe202ad3c52b8a0ae11d', 'إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَٰبَكُمْ غَمًّۢا بِغَمٍّ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَٰبَكُمْ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '7b728ffb7d2da1ca041377ccd8de0b2934c204e252a9fe202ad3c52b8a0ae11d', '7b728ffb7d2da1ca041377ccd8de0b2934c204e252a9fe202ad3c52b8a0ae11d', NULL, 'اذ تصعدون ولا تلون علي احد والرسول يدعوكم في اخريكم فاثبكم غما بغم لكيلا تحزنوا علي ما فاتكم ولا ما اصبكم والله خبير بما تعملون', 4, 7, 28, 1, 1, 69, false, NULL),
    (447, 'tanzil-uthmani-v1.1', 3, 154, 'ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَآئِفَةً مِّنكُمْ وَطَآئِفَةٌ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَٰهِلِيَّةِ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌ مَّا قُتِلْنَا هَٰهُنَا قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '5e6dbc9db17fd84927a42df9a2f9c765c94a0671dd97136b5e864ad429a211f7', 'ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَآئِفَةً مِّنكُمْ وَطَآئِفَةٌ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَٰهِلِيَّةِ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌ مَّا قُتِلْنَا هَٰهُنَا قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '5e6dbc9db17fd84927a42df9a2f9c765c94a0671dd97136b5e864ad429a211f7', '5e6dbc9db17fd84927a42df9a2f9c765c94a0671dd97136b5e864ad429a211f7', NULL, 'ثم انزل عليكم من بعد الغم امنه نعاسا يغشي طائفه منكم وطائفه قد اهمتهم انفسهم يظنون بالله غير الحق ظن الجهليه يقولون هل لنا من الامر من شيء قل ان الامر كله لله يخفون في انفسهم ما لا يبدون لك يقولون لو كان لنا من الامر شيء ما قتلنا ههنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل الي مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور', 4, 7, 28, 1, 1, 70, false, NULL),
    (448, 'tanzil-uthmani-v1.1', 3, 155, 'إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَٰنُ بِبَعْضِ مَا كَسَبُوا۟ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', 'e8239e6cfc492e7901e1518cbfa7fa457407eb4d0436b06b2c1e2e9d74c33cd0', 'إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَٰنُ بِبَعْضِ مَا كَسَبُوا۟ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ', 'e8239e6cfc492e7901e1518cbfa7fa457407eb4d0436b06b2c1e2e9d74c33cd0', 'e8239e6cfc492e7901e1518cbfa7fa457407eb4d0436b06b2c1e2e9d74c33cd0', NULL, 'ان الذين تولوا منكم يوم التقي الجمعان انما استزلهم الشيطن ببعض ما كسبوا ولقد عفا الله عنهم ان الله غفور حليم', 4, 7, 28, 1, 1, 70, false, NULL),
    (449, 'tanzil-uthmani-v1.1', 3, 156, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةً فِى قُلُوبِهِمْ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '54b7f35cdcc20067d1dc2bb01e255d66211a8dcd047bb28f8c11171eac3e21d3', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةً فِى قُلُوبِهِمْ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '54b7f35cdcc20067d1dc2bb01e255d66211a8dcd047bb28f8c11171eac3e21d3', '54b7f35cdcc20067d1dc2bb01e255d66211a8dcd047bb28f8c11171eac3e21d3', NULL, 'يايها الذين ءامنوا لا تكونوا كالذين كفروا وقالوا لاخونهم اذا ضربوا في الارض او كانوا غزي لو كانوا عندنا ما ماتوا وما قتلوا ليجعل الله ذلك حسره في قلوبهم والله يحي ويميت والله بما تعملون بصير', 4, 7, 28, 1, 1, 70, false, NULL),
    (450, 'tanzil-uthmani-v1.1', 3, 157, 'وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌ مِّمَّا يَجْمَعُونَ', 'd0efb463f12a0ee9896c782510e395902425c367cb815929c700be9797c7e798', 'وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌ مِّمَّا يَجْمَعُونَ', 'd0efb463f12a0ee9896c782510e395902425c367cb815929c700be9797c7e798', 'd0efb463f12a0ee9896c782510e395902425c367cb815929c700be9797c7e798', NULL, 'ولئن قتلتم في سبيل الله او متم لمغفره من الله ورحمه خير مما يجمعون', 4, 7, 28, 1, 1, 70, false, NULL),
    (451, 'tanzil-uthmani-v1.1', 3, 158, 'وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ', 'f887f4d3521ef40e001294c820158df45037123d94b3de93e74c348ef7ae15f7', 'وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ', 'f887f4d3521ef40e001294c820158df45037123d94b3de93e74c348ef7ae15f7', 'f887f4d3521ef40e001294c820158df45037123d94b3de93e74c348ef7ae15f7', NULL, 'ولئن متم او قتلتم لالي الله تحشرون', 4, 7, 28, 1, 1, 71, false, NULL),
    (452, 'tanzil-uthmani-v1.1', 3, 159, 'فَبِمَا رَحْمَةٍ مِّنَ ٱللَّهِ لِنتَ لَهُمْ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ', 'c22dc7b1d38f6debc61822aea22b5876934a527298bfc519eda979b90d6fa78f', 'فَبِمَا رَحْمَةٍ مِّنَ ٱللَّهِ لِنتَ لَهُمْ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ', 'c22dc7b1d38f6debc61822aea22b5876934a527298bfc519eda979b90d6fa78f', 'c22dc7b1d38f6debc61822aea22b5876934a527298bfc519eda979b90d6fa78f', NULL, 'فبما رحمه من الله لنت لهم ولو كنت فظا غليظ القلب لانفضوا من حولك فاعف عنهم واستغفر لهم وشاورهم في الامر فاذا عزمت فتوكل علي الله ان الله يحب المتوكلين', 4, 7, 28, 1, 1, 71, false, NULL),
    (453, 'tanzil-uthmani-v1.1', 3, 160, 'إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '6323b0280ba63bd8a632e0e35c16ca4b94498eb65f4788e45532ef222d89da4a', 'إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '6323b0280ba63bd8a632e0e35c16ca4b94498eb65f4788e45532ef222d89da4a', '6323b0280ba63bd8a632e0e35c16ca4b94498eb65f4788e45532ef222d89da4a', NULL, 'ان ينصركم الله فلا غالب لكم وان يخذلكم فمن ذا الذي ينصركم من بعده وعلي الله فليتوكل المؤمنون', 4, 7, 28, 1, 1, 71, false, NULL),
    (454, 'tanzil-uthmani-v1.1', 3, 161, 'وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَٰمَةِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', '2ab0adc6c161b4116521bce7ef3af97a753d8e74a8d31e55c74425ce7bde5dda', 'وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَٰمَةِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', '2ab0adc6c161b4116521bce7ef3af97a753d8e74a8d31e55c74425ce7bde5dda', '2ab0adc6c161b4116521bce7ef3af97a753d8e74a8d31e55c74425ce7bde5dda', NULL, 'وما كان لنبي ان يغل ومن يغلل يات بما غل يوم القيمه ثم توفي كل نفس ما كسبت وهم لا يظلمون', 4, 7, 28, 1, 1, 71, false, NULL),
    (455, 'tanzil-uthmani-v1.1', 3, 162, 'أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', '69fd39b21c893f14f5f9d7a3eed2bb1b30c10f9c5f797f2a3a8a939832a0e39c', 'أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', '69fd39b21c893f14f5f9d7a3eed2bb1b30c10f9c5f797f2a3a8a939832a0e39c', '69fd39b21c893f14f5f9d7a3eed2bb1b30c10f9c5f797f2a3a8a939832a0e39c', NULL, 'افمن اتبع رضون الله كمن باء بسخط من الله وماويه جهنم وبئس المصير', 4, 7, 28, 1, 1, 71, false, NULL),
    (456, 'tanzil-uthmani-v1.1', 3, 163, 'هُمْ دَرَجَٰتٌ عِندَ ٱللَّهِ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'ba171aaf6b8e179f1159cae85ccdc204c8e8def25c9cce741843b5426dc05227', 'هُمْ دَرَجَٰتٌ عِندَ ٱللَّهِ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 'ba171aaf6b8e179f1159cae85ccdc204c8e8def25c9cce741843b5426dc05227', 'ba171aaf6b8e179f1159cae85ccdc204c8e8def25c9cce741843b5426dc05227', NULL, 'هم درجت عند الله والله بصير بما يعملون', 4, 7, 28, 1, 1, 71, false, NULL),
    (457, 'tanzil-uthmani-v1.1', 3, 164, 'لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍ مُّبِينٍ', 'ef1c624e84b158b526e925fd55bd410079518774b81059889db9d850407649d6', 'لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍ مُّبِينٍ', 'ef1c624e84b158b526e925fd55bd410079518774b81059889db9d850407649d6', 'ef1c624e84b158b526e925fd55bd410079518774b81059889db9d850407649d6', NULL, 'لقد من الله علي المؤمنين اذ بعث فيهم رسولا من انفسهم يتلوا عليهم ءايته ويزكيهم ويعلمهم الكتب والحكمه وان كانوا من قبل لفي ضلل مبين', 4, 7, 28, 1, 1, 71, false, NULL),
    (458, 'tanzil-uthmani-v1.1', 3, 165, 'أَوَلَمَّآ أَصَٰبَتْكُم مُّصِيبَةٌ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَٰذَا قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'e6a788101b2dc518218436eb16bef12f884a33239ddd049e5ae7e94811da1e2a', 'أَوَلَمَّآ أَصَٰبَتْكُم مُّصِيبَةٌ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَٰذَا قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'e6a788101b2dc518218436eb16bef12f884a33239ddd049e5ae7e94811da1e2a', 'e6a788101b2dc518218436eb16bef12f884a33239ddd049e5ae7e94811da1e2a', NULL, 'اولما اصبتكم مصيبه قد اصبتم مثليها قلتم اني هذا قل هو من عند انفسكم ان الله علي كل شيء قدير', 4, 7, 28, 1, 1, 71, false, NULL),
    (459, 'tanzil-uthmani-v1.1', 3, 166, 'وَمَآ أَصَٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ', '4c62b95d94560919c1c595a361c3694eb3907a9571bfff71cc9bf7251c2802f3', 'وَمَآ أَصَٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ', '4c62b95d94560919c1c595a361c3694eb3907a9571bfff71cc9bf7251c2802f3', '4c62b95d94560919c1c595a361c3694eb3907a9571bfff71cc9bf7251c2802f3', NULL, 'وما اصبكم يوم التقي الجمعان فباذن الله وليعلم المؤمنين', 4, 7, 28, 1, 1, 72, false, NULL),
    (460, 'tanzil-uthmani-v1.1', 3, 167, 'وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًا لَّٱتَّبَعْنَٰكُمْ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَٰنِ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ', '5913a4e3071cc9c1220f67ff506c5df0097395350390c57a031f33abc5ae7e5f', 'وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًا لَّٱتَّبَعْنَٰكُمْ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَٰنِ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ', '5913a4e3071cc9c1220f67ff506c5df0097395350390c57a031f33abc5ae7e5f', '5913a4e3071cc9c1220f67ff506c5df0097395350390c57a031f33abc5ae7e5f', NULL, 'وليعلم الذين نافقوا وقيل لهم تعالوا قتلوا في سبيل الله او ادفعوا قالوا لو نعلم قتالا لاتبعنكم هم للكفر يومئذ اقرب منهم للايمن يقولون بافوههم ما ليس في قلوبهم والله اعلم بما يكتمون', 4, 7, 28, 1, 1, 72, false, NULL),
    (461, 'tanzil-uthmani-v1.1', 3, 168, 'ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', '3ce610f33b5cf3b7185888852dcb5cd3c300379e1ad1ccd8b0ddbdcef97639c0', 'ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', '3ce610f33b5cf3b7185888852dcb5cd3c300379e1ad1ccd8b0ddbdcef97639c0', '3ce610f33b5cf3b7185888852dcb5cd3c300379e1ad1ccd8b0ddbdcef97639c0', NULL, 'الذين قالوا لاخونهم وقعدوا لو اطاعونا ما قتلوا قل فادرءوا عن انفسكم الموت ان كنتم صدقين', 4, 7, 28, 1, 1, 72, false, NULL),
    (462, 'tanzil-uthmani-v1.1', 3, 169, 'وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ', 'f0b47bfc64d5af0b859f98ed37419df8211dc2fdcc8e3e3a916b944db3df99d8', 'وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ', 'f0b47bfc64d5af0b859f98ed37419df8211dc2fdcc8e3e3a916b944db3df99d8', 'f0b47bfc64d5af0b859f98ed37419df8211dc2fdcc8e3e3a916b944db3df99d8', NULL, 'ولا تحسبن الذين قتلوا في سبيل الله اموتا بل احياء عند ربهم يرزقون', 4, 7, 28, 1, 1, 72, false, NULL),
    (463, 'tanzil-uthmani-v1.1', 3, 170, 'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '2815c9d281e3135e9e3da39cc19ee1202900eb5a771e9d150d9a5b7333737907', 'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '2815c9d281e3135e9e3da39cc19ee1202900eb5a771e9d150d9a5b7333737907', '2815c9d281e3135e9e3da39cc19ee1202900eb5a771e9d150d9a5b7333737907', NULL, 'فرحين بما ءاتيهم الله من فضله ويستبشرون بالذين لم يلحقوا بهم من خلفهم الا خوف عليهم ولا هم يحزنون', 4, 7, 28, 1, 1, 72, false, NULL),
    (464, 'tanzil-uthmani-v1.1', 3, 171, 'يَسْتَبْشِرُونَ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ', '873306e7478c876ef114ef75480fe2d2d0898f01733cd9d399e9fc4108aef3af', 'يَسْتَبْشِرُونَ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ', '873306e7478c876ef114ef75480fe2d2d0898f01733cd9d399e9fc4108aef3af', '873306e7478c876ef114ef75480fe2d2d0898f01733cd9d399e9fc4108aef3af', NULL, 'يستبشرون بنعمه من الله وفضل وان الله لا يضيع اجر المؤمنين', 4, 8, 29, 1, 1, 72, false, NULL),
    (465, 'tanzil-uthmani-v1.1', 3, 172, 'ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ', '7fbc230c607be6c1d402468c24e5e13fe3aa1451b4a7fc37410a674691cd18f2', 'ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ', '7fbc230c607be6c1d402468c24e5e13fe3aa1451b4a7fc37410a674691cd18f2', '7fbc230c607be6c1d402468c24e5e13fe3aa1451b4a7fc37410a674691cd18f2', NULL, 'الذين استجابوا لله والرسول من بعد ما اصابهم القرح للذين احسنوا منهم واتقوا اجر عظيم', 4, 8, 29, 1, 1, 72, false, NULL),
    (466, 'tanzil-uthmani-v1.1', 3, 173, 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَٰنًا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ', 'c7d0ba138ccfb873e8a11bca1521b66e4cec8a887b25acbddbf81cec45af7385', 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَٰنًا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ', 'c7d0ba138ccfb873e8a11bca1521b66e4cec8a887b25acbddbf81cec45af7385', 'c7d0ba138ccfb873e8a11bca1521b66e4cec8a887b25acbddbf81cec45af7385', NULL, 'الذين قال لهم الناس ان الناس قد جمعوا لكم فاخشوهم فزادهم ايمنا وقالوا حسبنا الله ونعم الوكيل', 4, 8, 29, 1, 1, 72, false, NULL),
    (467, 'tanzil-uthmani-v1.1', 3, 174, 'فَٱنقَلَبُوا۟ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوٓءٌ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ', 'a6b0c42396f1c4ce198a7410eccd1cc40e86d39e50ceff78d823ddd3840fba99', 'فَٱنقَلَبُوا۟ بِنِعْمَةٍ مِّنَ ٱللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوٓءٌ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ', 'a6b0c42396f1c4ce198a7410eccd1cc40e86d39e50ceff78d823ddd3840fba99', 'a6b0c42396f1c4ce198a7410eccd1cc40e86d39e50ceff78d823ddd3840fba99', NULL, 'فانقلبوا بنعمه من الله وفضل لم يمسسهم سوء واتبعوا رضون الله والله ذو فضل عظيم', 4, 8, 29, 1, 1, 73, false, NULL),
    (468, 'tanzil-uthmani-v1.1', 3, 175, 'إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ', 'c8d9f5e4eb1ba7974eb572cb1e916a428a8f6b9e5055541b8b4dc53f195e493b', 'إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ', 'c8d9f5e4eb1ba7974eb572cb1e916a428a8f6b9e5055541b8b4dc53f195e493b', 'c8d9f5e4eb1ba7974eb572cb1e916a428a8f6b9e5055541b8b4dc53f195e493b', NULL, 'انما ذلكم الشيطن يخوف اولياءه فلا تخافوهم وخافون ان كنتم مؤمنين', 4, 8, 29, 1, 1, 73, false, NULL),
    (469, 'tanzil-uthmani-v1.1', 3, 176, 'وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِى ٱلْـَٔاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', '9e7a89bd55c1a44025dcace8152d02422f350cebc932bdbf0c5d87fe8a9f7762', 'وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِى ٱلْـَٔاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', '9e7a89bd55c1a44025dcace8152d02422f350cebc932bdbf0c5d87fe8a9f7762', '9e7a89bd55c1a44025dcace8152d02422f350cebc932bdbf0c5d87fe8a9f7762', NULL, 'ولا يحزنك الذين يسرعون في الكفر انهم لن يضروا الله شيا يريد الله الا يجعل لهم حظا في الاخره ولهم عذاب عظيم', 4, 8, 29, 1, 1, 73, false, NULL),
    (470, 'tanzil-uthmani-v1.1', 3, 177, 'إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَلَهُمْ عَذَابٌ أَلِيمٌ', '2cfead54bc1cd841d90df3089c18acec983e81a64a6fc6661499c2e2117dee8a', 'إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَلَهُمْ عَذَابٌ أَلِيمٌ', '2cfead54bc1cd841d90df3089c18acec983e81a64a6fc6661499c2e2117dee8a', '2cfead54bc1cd841d90df3089c18acec983e81a64a6fc6661499c2e2117dee8a', NULL, 'ان الذين اشتروا الكفر بالايمن لن يضروا الله شيا ولهم عذاب اليم', 4, 8, 29, 1, 1, 73, false, NULL),
    (471, 'tanzil-uthmani-v1.1', 3, 178, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًا وَلَهُمْ عَذَابٌ مُّهِينٌ', 'd1a7753df0bcedff5da57983aabb6137a287ab7d642cc23c837d160537b8f500', 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًا وَلَهُمْ عَذَابٌ مُّهِينٌ', 'd1a7753df0bcedff5da57983aabb6137a287ab7d642cc23c837d160537b8f500', 'd1a7753df0bcedff5da57983aabb6137a287ab7d642cc23c837d160537b8f500', NULL, 'ولا يحسبن الذين كفروا انما نملي لهم خير لانفسهم انما نملي لهم ليزدادوا اثما ولهم عذاب مهين', 4, 8, 29, 1, 1, 73, false, NULL),
    (472, 'tanzil-uthmani-v1.1', 3, 179, 'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌ', '12233ede7485523a771ef33f8156cf7da37d60f450574a6d24db5a6b3ba8aae6', 'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌ', '12233ede7485523a771ef33f8156cf7da37d60f450574a6d24db5a6b3ba8aae6', '12233ede7485523a771ef33f8156cf7da37d60f450574a6d24db5a6b3ba8aae6', NULL, 'ما كان الله ليذر المؤمنين علي ما انتم عليه حتي يميز الخبيث من الطيب وما كان الله ليطلعكم علي الغيب ولكن الله يجتبي من رسله من يشاء فامنوا بالله ورسله وان تؤمنوا وتتقوا فلكم اجر عظيم', 4, 8, 29, 1, 1, 73, false, NULL),
    (473, 'tanzil-uthmani-v1.1', 3, 180, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًا لَّهُم بَلْ هُوَ شَرٌّ لَّهُمْ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَٰمَةِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'f3b69f56583483c58cfc2f6c21e0d814ca8f9a99bacd603129efc2abba0b4045', 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًا لَّهُم بَلْ هُوَ شَرٌّ لَّهُمْ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَٰمَةِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'f3b69f56583483c58cfc2f6c21e0d814ca8f9a99bacd603129efc2abba0b4045', 'f3b69f56583483c58cfc2f6c21e0d814ca8f9a99bacd603129efc2abba0b4045', NULL, 'ولا يحسبن الذين يبخلون بما ءاتيهم الله من فضله هو خيرا لهم بل هو شر لهم سيطوقون ما بخلوا به يوم القيمه ولله ميرث السموت والارض والله بما تعملون خبير', 4, 8, 29, 1, 1, 73, false, NULL),
    (474, 'tanzil-uthmani-v1.1', 3, 181, 'لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَآءُ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', '1041f6e25180e5dc80cf512f8f55faea1c4b148f3720b55f137ce22b66ba89b0', 'لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَآءُ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', '1041f6e25180e5dc80cf512f8f55faea1c4b148f3720b55f137ce22b66ba89b0', '1041f6e25180e5dc80cf512f8f55faea1c4b148f3720b55f137ce22b66ba89b0', NULL, 'لقد سمع الله قول الذين قالوا ان الله فقير ونحن اغنياء سنكتب ما قالوا وقتلهم الانبياء بغير حق ونقول ذوقوا عذاب الحريق', 4, 8, 29, 1, 1, 74, false, NULL),
    (475, 'tanzil-uthmani-v1.1', 3, 182, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ', '70cf4570802a16ad257692f18104eb1f4ea9417ca4c34a8c3bd8b38bebb976eb', 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ', '70cf4570802a16ad257692f18104eb1f4ea9417ca4c34a8c3bd8b38bebb976eb', '70cf4570802a16ad257692f18104eb1f4ea9417ca4c34a8c3bd8b38bebb976eb', NULL, 'ذلك بما قدمت ايديكم وان الله ليس بظلام للعبيد', 4, 8, 29, 1, 1, 74, false, NULL),
    (476, 'tanzil-uthmani-v1.1', 3, 183, 'ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ ٱلنَّارُ قُلْ قَدْ جَآءَكُمْ رُسُلٌ مِّن قَبْلِى بِٱلْبَيِّنَٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَٰدِقِينَ', '4754a6afda501152f5f23aa5ab94fa1190265bcb8b1e1f9edf7ee97c5586d7eb', 'ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ ٱلنَّارُ قُلْ قَدْ جَآءَكُمْ رُسُلٌ مِّن قَبْلِى بِٱلْبَيِّنَٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَٰدِقِينَ', '4754a6afda501152f5f23aa5ab94fa1190265bcb8b1e1f9edf7ee97c5586d7eb', '4754a6afda501152f5f23aa5ab94fa1190265bcb8b1e1f9edf7ee97c5586d7eb', NULL, 'الذين قالوا ان الله عهد الينا الا نؤمن لرسول حتي ياتينا بقربان تاكله النار قل قد جاءكم رسل من قبلي بالبينت وبالذي قلتم فلم قتلتموهم ان كنتم صدقين', 4, 8, 29, 1, 1, 74, false, NULL),
    (477, 'tanzil-uthmani-v1.1', 3, 184, 'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلْكِتَٰبِ ٱلْمُنِيرِ', '230ef69651635a74e3ff1c9657d20b453b03b9bf62784526cc925dfe7cd19ba4', 'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلْكِتَٰبِ ٱلْمُنِيرِ', '230ef69651635a74e3ff1c9657d20b453b03b9bf62784526cc925dfe7cd19ba4', '230ef69651635a74e3ff1c9657d20b453b03b9bf62784526cc925dfe7cd19ba4', NULL, 'فان كذبوك فقد كذب رسل من قبلك جاءو بالبينت والزبر والكتب المنير', 4, 8, 29, 1, 1, 74, false, NULL),
    (478, 'tanzil-uthmani-v1.1', 3, 185, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', '4c22918fa96c593391b27919e6517d035d4bb23f0f21915a20e18946f6bea307', 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', '4c22918fa96c593391b27919e6517d035d4bb23f0f21915a20e18946f6bea307', '4c22918fa96c593391b27919e6517d035d4bb23f0f21915a20e18946f6bea307', NULL, 'كل نفس ذائقه الموت وانما توفون اجوركم يوم القيمه فمن زحزح عن النار وادخل الجنه فقد فاز وما الحيوه الدنيا الا متع الغرور', 4, 8, 29, 1, 1, 74, false, NULL),
    (479, 'tanzil-uthmani-v1.1', 3, 186, 'لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًى كَثِيرًا وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', '886afa7c643881487664f3979506233cd48d121158c5e6a7ce145aa9dd2e2abf', 'لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًى كَثِيرًا وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', '886afa7c643881487664f3979506233cd48d121158c5e6a7ce145aa9dd2e2abf', '886afa7c643881487664f3979506233cd48d121158c5e6a7ce145aa9dd2e2abf', NULL, 'لتبلون في امولكم وانفسكم ولتسمعن من الذين اوتوا الكتب من قبلكم ومن الذين اشركوا اذي كثيرا وان تصبروا وتتقوا فان ذلك من عزم الامور', 4, 8, 30, 1, 1, 74, false, NULL),
    (480, 'tanzil-uthmani-v1.1', 3, 187, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًا قَلِيلًا فَبِئْسَ مَا يَشْتَرُونَ', 'a8498ab29fc5d197c474b8c66773dc59cdf3a9670608f9121f947fc07ac906f0', 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًا قَلِيلًا فَبِئْسَ مَا يَشْتَرُونَ', 'a8498ab29fc5d197c474b8c66773dc59cdf3a9670608f9121f947fc07ac906f0', 'a8498ab29fc5d197c474b8c66773dc59cdf3a9670608f9121f947fc07ac906f0', NULL, 'واذ اخذ الله ميثق الذين اوتوا الكتب لتبيننه للناس ولا تكتمونه فنبذوه وراء ظهورهم واشتروا به ثمنا قليلا فبئس ما يشترون', 4, 8, 30, 1, 1, 75, false, NULL),
    (481, 'tanzil-uthmani-v1.1', 3, 188, 'لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍ مِّنَ ٱلْعَذَابِ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'f2ccbb2c7f4c6d82bf5edd948c86cdf4c93be069608fb3f2d6a6dbab504f3db5', 'لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍ مِّنَ ٱلْعَذَابِ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'f2ccbb2c7f4c6d82bf5edd948c86cdf4c93be069608fb3f2d6a6dbab504f3db5', 'f2ccbb2c7f4c6d82bf5edd948c86cdf4c93be069608fb3f2d6a6dbab504f3db5', NULL, 'لا تحسبن الذين يفرحون بما اتوا ويحبون ان يحمدوا بما لم يفعلوا فلا تحسبنهم بمفازه من العذاب ولهم عذاب اليم', 4, 8, 30, 1, 1, 75, false, NULL),
    (482, 'tanzil-uthmani-v1.1', 3, 189, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'eed5c188677db3ed0c6d1cffdda0b821e839d7d4b1f64e8f28e9f04c0b6a570e', 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'eed5c188677db3ed0c6d1cffdda0b821e839d7d4b1f64e8f28e9f04c0b6a570e', 'eed5c188677db3ed0c6d1cffdda0b821e839d7d4b1f64e8f28e9f04c0b6a570e', NULL, 'ولله ملك السموت والارض والله علي كل شيء قدير', 4, 8, 30, 1, 1, 75, false, NULL),
    (483, 'tanzil-uthmani-v1.1', 3, 190, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلْأَلْبَٰبِ', '7a14405f6aa00e4c993bf0fbd7e41faad8a31179954b2f07a048a7ff68fe273d', 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلْأَلْبَٰبِ', '7a14405f6aa00e4c993bf0fbd7e41faad8a31179954b2f07a048a7ff68fe273d', '7a14405f6aa00e4c993bf0fbd7e41faad8a31179954b2f07a048a7ff68fe273d', NULL, 'ان في خلق السموت والارض واختلف اليل والنهار لايت لاولي الالبب', 4, 8, 30, 1, 1, 75, false, NULL),
    (484, 'tanzil-uthmani-v1.1', 3, 191, 'ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', 'e93710cfe59939cb28ec4348768c9528c03f896ceb34eee3b80eedd3fe89d174', 'ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', 'e93710cfe59939cb28ec4348768c9528c03f896ceb34eee3b80eedd3fe89d174', 'e93710cfe59939cb28ec4348768c9528c03f896ceb34eee3b80eedd3fe89d174', NULL, 'الذين يذكرون الله قيما وقعودا وعلي جنوبهم ويتفكرون في خلق السموت والارض ربنا ما خلقت هذا بطلا سبحنك فقنا عذاب النار', 4, 8, 30, 1, 1, 75, false, NULL),
    (485, 'tanzil-uthmani-v1.1', 3, 192, 'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 'd27a596b325d9c63b97f77f03a6643e340d431b40ce4c4fe8351c4611cee1586', 'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 'd27a596b325d9c63b97f77f03a6643e340d431b40ce4c4fe8351c4611cee1586', 'd27a596b325d9c63b97f77f03a6643e340d431b40ce4c4fe8351c4611cee1586', NULL, 'ربنا انك من تدخل النار فقد اخزيته وما للظلمين من انصار', 4, 8, 30, 1, 1, 75, false, NULL),
    (486, 'tanzil-uthmani-v1.1', 3, 193, 'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ', '899b12621ab6353721c1208a89ef4b8ef68cf1dd6f684eec242464e0a045cad4', 'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ', '899b12621ab6353721c1208a89ef4b8ef68cf1dd6f684eec242464e0a045cad4', '899b12621ab6353721c1208a89ef4b8ef68cf1dd6f684eec242464e0a045cad4', NULL, 'ربنا اننا سمعنا مناديا ينادي للايمن ان ءامنوا بربكم فامنا ربنا فاغفر لنا ذنوبنا وكفر عنا سياتنا وتوفنا مع الابرار', 4, 8, 30, 1, 1, 75, false, NULL),
    (487, 'tanzil-uthmani-v1.1', 3, 194, 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ', '1fa4b3f0420034cd360b98ad6d9a1f01ca12842265388f9cd772971da1ea05f8', 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ', '1fa4b3f0420034cd360b98ad6d9a1f01ca12842265388f9cd772971da1ea05f8', '1fa4b3f0420034cd360b98ad6d9a1f01ca12842265388f9cd772971da1ea05f8', NULL, 'ربنا وءاتنا ما وعدتنا علي رسلك ولا تخزنا يوم القيمه انك لا تخلف الميعاد', 4, 8, 30, 1, 1, 75, false, NULL),
    (488, 'tanzil-uthmani-v1.1', 3, 195, 'فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ بَعْضُكُم مِّنۢ بَعْضٍ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًا مِّنْ عِندِ ٱللَّهِ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ', 'd14997448db1e6ee27677e6061d883c6a4159b804c6f3366f2d59c486d347581', 'فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ بَعْضُكُم مِّنۢ بَعْضٍ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًا مِّنْ عِندِ ٱللَّهِ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ', 'd14997448db1e6ee27677e6061d883c6a4159b804c6f3366f2d59c486d347581', 'd14997448db1e6ee27677e6061d883c6a4159b804c6f3366f2d59c486d347581', NULL, 'فاستجاب لهم ربهم اني لا اضيع عمل عمل منكم من ذكر او انثي بعضكم من بعض فالذين هاجروا واخرجوا من ديرهم واوذوا في سبيلي وقتلوا وقتلوا لاكفرن عنهم سياتهم ولادخلنهم جنت تجري من تحتها الانهر ثوابا من عند الله والله عنده حسن الثواب', 4, 8, 30, 1, 1, 76, false, NULL),
    (489, 'tanzil-uthmani-v1.1', 3, 196, 'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ', 'ab4e64389c0c897dacaace2e76680794a71ac42abe32041e36f2083fb6790249', 'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ', 'ab4e64389c0c897dacaace2e76680794a71ac42abe32041e36f2083fb6790249', 'ab4e64389c0c897dacaace2e76680794a71ac42abe32041e36f2083fb6790249', NULL, 'لا يغرنك تقلب الذين كفروا في البلد', 4, 8, 30, 1, 1, 76, false, NULL),
    (490, 'tanzil-uthmani-v1.1', 3, 197, 'مَتَٰعٌ قَلِيلٌ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمِهَادُ', '0a73d9c885fcf3b63be8f7cc9e379214a07d990cc3ca1ce1dcc6066b0f254888', 'مَتَٰعٌ قَلِيلٌ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمِهَادُ', '0a73d9c885fcf3b63be8f7cc9e379214a07d990cc3ca1ce1dcc6066b0f254888', '0a73d9c885fcf3b63be8f7cc9e379214a07d990cc3ca1ce1dcc6066b0f254888', NULL, 'متع قليل ثم ماويهم جهنم وبئس المهاد', 4, 8, 30, 1, 1, 76, false, NULL),
    (491, 'tanzil-uthmani-v1.1', 3, 198, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ ٱللَّهِ وَمَا عِندَ ٱللَّهِ خَيْرٌ لِّلْأَبْرَارِ', 'ed2ee8764d0e526f75db19c6084c782db14fec0cd6403be227500feff52e76c8', 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ ٱللَّهِ وَمَا عِندَ ٱللَّهِ خَيْرٌ لِّلْأَبْرَارِ', 'ed2ee8764d0e526f75db19c6084c782db14fec0cd6403be227500feff52e76c8', 'ed2ee8764d0e526f75db19c6084c782db14fec0cd6403be227500feff52e76c8', NULL, 'لكن الذين اتقوا ربهم لهم جنت تجري من تحتها الانهر خلدين فيها نزلا من عند الله وما عند الله خير للابرار', 4, 8, 30, 1, 1, 76, false, NULL),
    (492, 'tanzil-uthmani-v1.1', 3, 199, 'وَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'e45a32e46f0778e000b12237bcefd3eeac7a908a5324ee7ff402d5746ea6aa70', 'وَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'e45a32e46f0778e000b12237bcefd3eeac7a908a5324ee7ff402d5746ea6aa70', 'e45a32e46f0778e000b12237bcefd3eeac7a908a5324ee7ff402d5746ea6aa70', NULL, 'وان من اهل الكتب لمن يؤمن بالله وما انزل اليكم وما انزل اليهم خشعين لله لا يشترون بايت الله ثمنا قليلا اولئك لهم اجرهم عند ربهم ان الله سريع الحساب', 4, 8, 30, 1, 1, 76, false, NULL),
    (493, 'tanzil-uthmani-v1.1', 3, 200, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', '8f833ce502effcd43cc9cee577413b99fb1ab2f517b7a65009c51da22b75d09d', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', '8f833ce502effcd43cc9cee577413b99fb1ab2f517b7a65009c51da22b75d09d', '8f833ce502effcd43cc9cee577413b99fb1ab2f517b7a65009c51da22b75d09d', NULL, 'يايها الذين ءامنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون', 4, 8, 30, 1, 1, 76, false, NULL),
    (494, 'tanzil-uthmani-v1.1', 4, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَآءً وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِى تَسَآءَلُونَ بِهِۦ وَٱلْأَرْحَامَ إِنَّ ٱللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا', '584ba2480d72ef9562e6117c9398bb19c98b8b49baaffc285177bbfeb04f276c', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَآءً وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِى تَسَآءَلُونَ بِهِۦ وَٱلْأَرْحَامَ إِنَّ ٱللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا', 'f149ba721e27571c36b74f01689d6cf609a4fcfff9c088f948d224f846184441', 'f149ba721e27571c36b74f01689d6cf609a4fcfff9c088f948d224f846184441', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يايها الناس اتقوا ربكم الذي خلقكم من نفس وحده وخلق منها زوجها وبث منهما رجالا كثيرا ونساء واتقوا الله الذي تساءلون به والارحام ان الله كان عليكم رقيبا', 4, 8, 31, 1, 1, 77, false, NULL),
    (495, 'tanzil-uthmani-v1.1', 4, 2, 'وَءَاتُوا۟ ٱلْيَتَٰمَىٰٓ أَمْوَٰلَهُمْ وَلَا تَتَبَدَّلُوا۟ ٱلْخَبِيثَ بِٱلطَّيِّبِ وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَهُمْ إِلَىٰٓ أَمْوَٰلِكُمْ إِنَّهُۥ كَانَ حُوبًا كَبِيرًا', '78cbf37352f3b4aa418502078129ebd793013a9bd6065cd12b54048392f77b09', 'وَءَاتُوا۟ ٱلْيَتَٰمَىٰٓ أَمْوَٰلَهُمْ وَلَا تَتَبَدَّلُوا۟ ٱلْخَبِيثَ بِٱلطَّيِّبِ وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَهُمْ إِلَىٰٓ أَمْوَٰلِكُمْ إِنَّهُۥ كَانَ حُوبًا كَبِيرًا', '78cbf37352f3b4aa418502078129ebd793013a9bd6065cd12b54048392f77b09', '78cbf37352f3b4aa418502078129ebd793013a9bd6065cd12b54048392f77b09', NULL, 'وءاتوا اليتمي امولهم ولا تتبدلوا الخبيث بالطيب ولا تاكلوا امولهم الي امولكم انه كان حوبا كبيرا', 4, 8, 31, 1, 1, 77, false, NULL),
    (496, 'tanzil-uthmani-v1.1', 4, 3, 'وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَٰنُكُمْ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟', '8cf20c6384d4b28705712e17c773647b406d501a5ba64903b8dae820c41f56f6', 'وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَٰنُكُمْ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟', '8cf20c6384d4b28705712e17c773647b406d501a5ba64903b8dae820c41f56f6', '8cf20c6384d4b28705712e17c773647b406d501a5ba64903b8dae820c41f56f6', NULL, 'وان خفتم الا تقسطوا في اليتمي فانكحوا ما طاب لكم من النساء مثني وثلث وربع فان خفتم الا تعدلوا فوحده او ما ملكت ايمنكم ذلك ادني الا تعولوا', 4, 8, 31, 1, 1, 77, false, NULL),
    (497, 'tanzil-uthmani-v1.1', 4, 4, 'وَءَاتُوا۟ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحْلَةً فَإِن طِبْنَ لَكُمْ عَن شَىْءٍ مِّنْهُ نَفْسًا فَكُلُوهُ هَنِيٓـًٔا مَّرِيٓـًٔا', '6d9824abff38d13778a8a71753ceaf24140c602128f9db85ffdad7b012da2243', 'وَءَاتُوا۟ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحْلَةً فَإِن طِبْنَ لَكُمْ عَن شَىْءٍ مِّنْهُ نَفْسًا فَكُلُوهُ هَنِيٓـًٔا مَّرِيٓـًٔا', '6d9824abff38d13778a8a71753ceaf24140c602128f9db85ffdad7b012da2243', '6d9824abff38d13778a8a71753ceaf24140c602128f9db85ffdad7b012da2243', NULL, 'وءاتوا النساء صدقتهن نحله فان طبن لكم عن شيء منه نفسا فكلوه هنيا مريا', 4, 8, 31, 1, 1, 77, false, NULL),
    (498, 'tanzil-uthmani-v1.1', 4, 5, 'وَلَا تُؤْتُوا۟ ٱلسُّفَهَآءَ أَمْوَٰلَكُمُ ٱلَّتِى جَعَلَ ٱللَّهُ لَكُمْ قِيَٰمًا وَٱرْزُقُوهُمْ فِيهَا وَٱكْسُوهُمْ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', 'd1b09af5d2ae6c1662da713f1e3ba143528567c26dca1a49afeffbcdc14f72a9', 'وَلَا تُؤْتُوا۟ ٱلسُّفَهَآءَ أَمْوَٰلَكُمُ ٱلَّتِى جَعَلَ ٱللَّهُ لَكُمْ قِيَٰمًا وَٱرْزُقُوهُمْ فِيهَا وَٱكْسُوهُمْ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', 'd1b09af5d2ae6c1662da713f1e3ba143528567c26dca1a49afeffbcdc14f72a9', 'd1b09af5d2ae6c1662da713f1e3ba143528567c26dca1a49afeffbcdc14f72a9', NULL, 'ولا تؤتوا السفهاء امولكم التي جعل الله لكم قيما وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا', 4, 8, 31, 1, 1, 77, false, NULL),
    (499, 'tanzil-uthmani-v1.1', 4, 6, 'وَٱبْتَلُوا۟ ٱلْيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنْ ءَانَسْتُم مِّنْهُمْ رُشْدًا فَٱدْفَعُوٓا۟ إِلَيْهِمْ أَمْوَٰلَهُمْ وَلَا تَأْكُلُوهَآ إِسْرَافًا وَبِدَارًا أَن يَكْبَرُوا۟ وَمَن كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَن كَانَ فَقِيرًا فَلْيَأْكُلْ بِٱلْمَعْرُوفِ فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْوَٰلَهُمْ فَأَشْهِدُوا۟ عَلَيْهِمْ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', '8fe54c251d55537a559d92875b46487a2b6ac66f8e6453b633452762793651da', 'وَٱبْتَلُوا۟ ٱلْيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنْ ءَانَسْتُم مِّنْهُمْ رُشْدًا فَٱدْفَعُوٓا۟ إِلَيْهِمْ أَمْوَٰلَهُمْ وَلَا تَأْكُلُوهَآ إِسْرَافًا وَبِدَارًا أَن يَكْبَرُوا۟ وَمَن كَانَ غَنِيًّا فَلْيَسْتَعْفِفْ وَمَن كَانَ فَقِيرًا فَلْيَأْكُلْ بِٱلْمَعْرُوفِ فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْوَٰلَهُمْ فَأَشْهِدُوا۟ عَلَيْهِمْ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', '8fe54c251d55537a559d92875b46487a2b6ac66f8e6453b633452762793651da', '8fe54c251d55537a559d92875b46487a2b6ac66f8e6453b633452762793651da', NULL, 'وابتلوا اليتمي حتي اذا بلغوا النكاح فان ءانستم منهم رشدا فادفعوا اليهم امولهم ولا تاكلوها اسرافا وبدارا ان يكبروا ومن كان غنيا فليستعفف ومن كان فقيرا فلياكل بالمعروف فاذا دفعتم اليهم امولهم فاشهدوا عليهم وكفي بالله حسيبا', 4, 8, 31, 1, 1, 77, false, NULL),
    (500, 'tanzil-uthmani-v1.1', 4, 7, 'لِّلرِّجَالِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ نَصِيبًا مَّفْرُوضًا', 'dc4a59dc315560c9da82e42f04890a657b96614c4a6e7ea41eceb869ddfd7205', 'لِّلرِّجَالِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ نَصِيبًا مَّفْرُوضًا', 'dc4a59dc315560c9da82e42f04890a657b96614c4a6e7ea41eceb869ddfd7205', 'dc4a59dc315560c9da82e42f04890a657b96614c4a6e7ea41eceb869ddfd7205', NULL, 'للرجال نصيب مما ترك الولدان والاقربون وللنساء نصيب مما ترك الولدان والاقربون مما قل منه او كثر نصيبا مفروضا', 4, 8, 31, 1, 1, 78, false, NULL)
