    juz_number, hizb_number, rub_number, ruku_number, manzil_number, page_number,
    sajdah, sajdah_type
) VALUES
    (501, 'tanzil-uthmani-v1.1', 4, 8, 'وَإِذَا حَضَرَ ٱلْقِسْمَةَ أُو۟لُوا۟ ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينُ فَٱرْزُقُوهُم مِّنْهُ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', 'b77bab48e0860a9260bb4d5df929fa87b8b899fc5bf24db219eb8594fd628c39', 'وَإِذَا حَضَرَ ٱلْقِسْمَةَ أُو۟لُوا۟ ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينُ فَٱرْزُقُوهُم مِّنْهُ وَقُولُوا۟ لَهُمْ قَوْلًا مَّعْرُوفًا', 'b77bab48e0860a9260bb4d5df929fa87b8b899fc5bf24db219eb8594fd628c39', 'b77bab48e0860a9260bb4d5df929fa87b8b899fc5bf24db219eb8594fd628c39', NULL, 'واذا حضر القسمه اولوا القربي واليتمي والمسكين فارزقوهم منه وقولوا لهم قولا معروفا', 4, 8, 31, 1, 1, 78, false, NULL),
    (502, 'tanzil-uthmani-v1.1', 4, 9, 'وَلْيَخْشَ ٱلَّذِينَ لَوْ تَرَكُوا۟ مِنْ خَلْفِهِمْ ذُرِّيَّةً ضِعَٰفًا خَافُوا۟ عَلَيْهِمْ فَلْيَتَّقُوا۟ ٱللَّهَ وَلْيَقُولُوا۟ قَوْلًا سَدِيدًا', 'de8b16ae76425b8cc3b4600b58ad0b2f06df2e849c8fd3fc817f71bb44230f63', 'وَلْيَخْشَ ٱلَّذِينَ لَوْ تَرَكُوا۟ مِنْ خَلْفِهِمْ ذُرِّيَّةً ضِعَٰفًا خَافُوا۟ عَلَيْهِمْ فَلْيَتَّقُوا۟ ٱللَّهَ وَلْيَقُولُوا۟ قَوْلًا سَدِيدًا', 'de8b16ae76425b8cc3b4600b58ad0b2f06df2e849c8fd3fc817f71bb44230f63', 'de8b16ae76425b8cc3b4600b58ad0b2f06df2e849c8fd3fc817f71bb44230f63', NULL, 'وليخش الذين لو تركوا من خلفهم ذريه ضعفا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا', 4, 8, 31, 1, 1, 78, false, NULL),
    (503, 'tanzil-uthmani-v1.1', 4, 10, 'إِنَّ ٱلَّذِينَ يَأْكُلُونَ أَمْوَٰلَ ٱلْيَتَٰمَىٰ ظُلْمًا إِنَّمَا يَأْكُلُونَ فِى بُطُونِهِمْ نَارًا وَسَيَصْلَوْنَ سَعِيرًا', '1f5b7574e6f7bc6565136233ec7b6d340aafbdc47f1f1ab6325567808f0159b1', 'إِنَّ ٱلَّذِينَ يَأْكُلُونَ أَمْوَٰلَ ٱلْيَتَٰمَىٰ ظُلْمًا إِنَّمَا يَأْكُلُونَ فِى بُطُونِهِمْ نَارًا وَسَيَصْلَوْنَ سَعِيرًا', '1f5b7574e6f7bc6565136233ec7b6d340aafbdc47f1f1ab6325567808f0159b1', '1f5b7574e6f7bc6565136233ec7b6d340aafbdc47f1f1ab6325567808f0159b1', NULL, 'ان الذين ياكلون امول اليتمي ظلما انما ياكلون في بطونهم نارا وسيصلون سعيرا', 4, 8, 31, 1, 1, 78, false, NULL),
    (504, 'tanzil-uthmani-v1.1', 4, 11, 'يُوصِيكُمُ ٱللَّهُ فِىٓ أَوْلَٰدِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ فَإِن كُنَّ نِسَآءً فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ وَإِن كَانَتْ وَٰحِدَةً فَلَهَا ٱلنِّصْفُ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ فَإِن كَانَ لَهُۥٓ إِخْوَةٌ فَلِأُمِّهِ ٱلسُّدُسُ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِى بِهَآ أَوْ دَيْنٍ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا فَرِيضَةً مِّنَ ٱللَّهِ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', '0acafdbbad7bcf46919e804eb30b9b01aa479277baf6b89ac7e6aa055a5ce8a4', 'يُوصِيكُمُ ٱللَّهُ فِىٓ أَوْلَٰدِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ فَإِن كُنَّ نِسَآءً فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ وَإِن كَانَتْ وَٰحِدَةً فَلَهَا ٱلنِّصْفُ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ فَإِن كَانَ لَهُۥٓ إِخْوَةٌ فَلِأُمِّهِ ٱلسُّدُسُ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِى بِهَآ أَوْ دَيْنٍ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا فَرِيضَةً مِّنَ ٱللَّهِ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', '0acafdbbad7bcf46919e804eb30b9b01aa479277baf6b89ac7e6aa055a5ce8a4', '0acafdbbad7bcf46919e804eb30b9b01aa479277baf6b89ac7e6aa055a5ce8a4', NULL, 'يوصيكم الله في اولدكم للذكر مثل حظ الانثيين فان كن نساء فوق اثنتين فلهن ثلثا ما ترك وان كانت وحده فلها النصف ولابويه لكل وحد منهما السدس مما ترك ان كان له ولد فان لم يكن له ولد وورثه ابواه فلامه الثلث فان كان له اخوه فلامه السدس من بعد وصيه يوصي بها او دين ءاباؤكم وابناؤكم لا تدرون ايهم اقرب لكم نفعا فريضه من الله ان الله كان عليما حكيما', 4, 8, 31, 1, 1, 78, false, NULL),
    (505, 'tanzil-uthmani-v1.1', 4, 12, 'وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ فَإِن كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِينَ بِهَآ أَوْ دَيْنٍ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌ فَإِن كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم مِّنۢ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَآ أَوْ دَيْنٍ وَإِن كَانَ رَجُلٌ يُورَثُ كَلَٰلَةً أَوِ ٱمْرَأَةٌ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ مِنۢ بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّ وَصِيَّةً مِّنَ ٱللَّهِ وَٱللَّهُ عَلِيمٌ حَلِيمٌ', '987c15ea59aa417de4bf586a399e3806051923bd9322cf560d6ebbed37e9e18e', 'وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ فَإِن كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِينَ بِهَآ أَوْ دَيْنٍ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌ فَإِن كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم مِّنۢ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَآ أَوْ دَيْنٍ وَإِن كَانَ رَجُلٌ يُورَثُ كَلَٰلَةً أَوِ ٱمْرَأَةٌ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ مِنۢ بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّ وَصِيَّةً مِّنَ ٱللَّهِ وَٱللَّهُ عَلِيمٌ حَلِيمٌ', '987c15ea59aa417de4bf586a399e3806051923bd9322cf560d6ebbed37e9e18e', '987c15ea59aa417de4bf586a399e3806051923bd9322cf560d6ebbed37e9e18e', NULL, 'ولكم نصف ما ترك ازوجكم ان لم يكن لهن ولد فان كان لهن ولد فلكم الربع مما تركن من بعد وصيه يوصين بها او دين ولهن الربع مما تركتم ان لم يكن لكم ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلله او امراه وله اخ او اخت فلكل وحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصي بها او دين غير مضار وصيه من الله والله عليم حليم', 4, 8, 32, 1, 1, 79, false, NULL),
    (506, 'tanzil-uthmani-v1.1', 4, 13, 'تِلْكَ حُدُودُ ٱللَّهِ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'f073690f534f87f574e6671c7074d53e8f1d9af7328872a2ee73870b2315b23d', 'تِلْكَ حُدُودُ ٱللَّهِ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'f073690f534f87f574e6671c7074d53e8f1d9af7328872a2ee73870b2315b23d', 'f073690f534f87f574e6671c7074d53e8f1d9af7328872a2ee73870b2315b23d', NULL, 'تلك حدود الله ومن يطع الله ورسوله يدخله جنت تجري من تحتها الانهر خلدين فيها وذلك الفوز العظيم', 4, 8, 32, 1, 1, 79, false, NULL),
    (507, 'tanzil-uthmani-v1.1', 4, 14, 'وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدْخِلْهُ نَارًا خَٰلِدًا فِيهَا وَلَهُۥ عَذَابٌ مُّهِينٌ', '88060308d41678ba2ab68c21872b0ba87a33447b35dfeadf6fdac419407df43a', 'وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدْخِلْهُ نَارًا خَٰلِدًا فِيهَا وَلَهُۥ عَذَابٌ مُّهِينٌ', '88060308d41678ba2ab68c21872b0ba87a33447b35dfeadf6fdac419407df43a', '88060308d41678ba2ab68c21872b0ba87a33447b35dfeadf6fdac419407df43a', NULL, 'ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خلدا فيها وله عذاب مهين', 4, 8, 32, 1, 1, 79, false, NULL),
    (508, 'tanzil-uthmani-v1.1', 4, 15, 'وَٱلَّٰتِى يَأْتِينَ ٱلْفَٰحِشَةَ مِن نِّسَآئِكُمْ فَٱسْتَشْهِدُوا۟ عَلَيْهِنَّ أَرْبَعَةً مِّنكُمْ فَإِن شَهِدُوا۟ فَأَمْسِكُوهُنَّ فِى ٱلْبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلْمَوْتُ أَوْ يَجْعَلَ ٱللَّهُ لَهُنَّ سَبِيلًا', '34302874ce09c21fba433a42d3ecb323b2f1f5d8a73380ea3d963c0aaebdb079', 'وَٱلَّٰتِى يَأْتِينَ ٱلْفَٰحِشَةَ مِن نِّسَآئِكُمْ فَٱسْتَشْهِدُوا۟ عَلَيْهِنَّ أَرْبَعَةً مِّنكُمْ فَإِن شَهِدُوا۟ فَأَمْسِكُوهُنَّ فِى ٱلْبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلْمَوْتُ أَوْ يَجْعَلَ ٱللَّهُ لَهُنَّ سَبِيلًا', '34302874ce09c21fba433a42d3ecb323b2f1f5d8a73380ea3d963c0aaebdb079', '34302874ce09c21fba433a42d3ecb323b2f1f5d8a73380ea3d963c0aaebdb079', NULL, 'والتي ياتين الفحشه من نسائكم فاستشهدوا عليهن اربعه منكم فان شهدوا فامسكوهن في البيوت حتي يتوفيهن الموت او يجعل الله لهن سبيلا', 4, 8, 32, 1, 1, 80, false, NULL),
    (509, 'tanzil-uthmani-v1.1', 4, 16, 'وَٱلَّذَانِ يَأْتِيَٰنِهَا مِنكُمْ فَـَٔاذُوهُمَا فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُوا۟ عَنْهُمَآ إِنَّ ٱللَّهَ كَانَ تَوَّابًا رَّحِيمًا', '42755375c9e32dd0a6d4170fb827eeb1077f979ff73c7e1d739a85336a3fbce2', 'وَٱلَّذَانِ يَأْتِيَٰنِهَا مِنكُمْ فَـَٔاذُوهُمَا فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُوا۟ عَنْهُمَآ إِنَّ ٱللَّهَ كَانَ تَوَّابًا رَّحِيمًا', '42755375c9e32dd0a6d4170fb827eeb1077f979ff73c7e1d739a85336a3fbce2', '42755375c9e32dd0a6d4170fb827eeb1077f979ff73c7e1d739a85336a3fbce2', NULL, 'والذان ياتينها منكم فاذوهما فان تابا واصلحا فاعرضوا عنهما ان الله كان توابا رحيما', 4, 8, 32, 1, 1, 80, false, NULL),
    (510, 'tanzil-uthmani-v1.1', 4, 17, 'إِنَّمَا ٱلتَّوْبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعْمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٍ ثُمَّ يَتُوبُونَ مِن قَرِيبٍ فَأُو۟لَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيْهِمْ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '49ecc9ec3856ccac34262c94e1876e5625af5a16462eda8de03fdc40862090ae', 'إِنَّمَا ٱلتَّوْبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعْمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٍ ثُمَّ يَتُوبُونَ مِن قَرِيبٍ فَأُو۟لَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيْهِمْ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '49ecc9ec3856ccac34262c94e1876e5625af5a16462eda8de03fdc40862090ae', '49ecc9ec3856ccac34262c94e1876e5625af5a16462eda8de03fdc40862090ae', NULL, 'انما التوبه علي الله للذين يعملون السوء بجهله ثم يتوبون من قريب فاولئك يتوب الله عليهم وكان الله عليما حكيما', 4, 8, 32, 1, 1, 80, false, NULL),
    (511, 'tanzil-uthmani-v1.1', 4, 18, 'وَلَيْسَتِ ٱلتَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ إِنِّى تُبْتُ ٱلْـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', '3ebf2a33fdc92eb98043a93b5677585add4b04c10e1a72df287b9dcd752bd53a', 'وَلَيْسَتِ ٱلتَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ إِنِّى تُبْتُ ٱلْـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', '3ebf2a33fdc92eb98043a93b5677585add4b04c10e1a72df287b9dcd752bd53a', '3ebf2a33fdc92eb98043a93b5677585add4b04c10e1a72df287b9dcd752bd53a', NULL, 'وليست التوبه للذين يعملون السيات حتي اذا حضر احدهم الموت قال اني تبت الن ولا الذين يموتون وهم كفار اولئك اعتدنا لهم عذابا اليما', 4, 8, 32, 1, 1, 80, false, NULL),
    (512, 'tanzil-uthmani-v1.1', 4, 19, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَحِلُّ لَكُمْ أَن تَرِثُوا۟ ٱلنِّسَآءَ كَرْهًا وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا۟ بِبَعْضِ مَآ ءَاتَيْتُمُوهُنَّ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍ مُّبَيِّنَةٍ وَعَاشِرُوهُنَّ بِٱلْمَعْرُوفِ فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَيَجْعَلَ ٱللَّهُ فِيهِ خَيْرًا كَثِيرًا', '618b43913d88aac702dedd9d537fa28dcd45db83aee7c29f6d57f92b60f09208', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَحِلُّ لَكُمْ أَن تَرِثُوا۟ ٱلنِّسَآءَ كَرْهًا وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا۟ بِبَعْضِ مَآ ءَاتَيْتُمُوهُنَّ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍ مُّبَيِّنَةٍ وَعَاشِرُوهُنَّ بِٱلْمَعْرُوفِ فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَيَجْعَلَ ٱللَّهُ فِيهِ خَيْرًا كَثِيرًا', '618b43913d88aac702dedd9d537fa28dcd45db83aee7c29f6d57f92b60f09208', '618b43913d88aac702dedd9d537fa28dcd45db83aee7c29f6d57f92b60f09208', NULL, 'يايها الذين ءامنوا لا يحل لكم ان ترثوا النساء كرها ولا تعضلوهن لتذهبوا ببعض ما ءاتيتموهن الا ان ياتين بفحشه مبينه وعاشروهن بالمعروف فان كرهتموهن فعسي ان تكرهوا شيا ويجعل الله فيه خيرا كثيرا', 4, 8, 32, 1, 1, 80, false, NULL),
    (513, 'tanzil-uthmani-v1.1', 4, 20, 'وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًا فَلَا تَأْخُذُوا۟ مِنْهُ شَيْـًٔا أَتَأْخُذُونَهُۥ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'd3b5412640dbc71e0276267989b185350fb471ed8d46461ec7b1072dc88d7000', 'وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًا فَلَا تَأْخُذُوا۟ مِنْهُ شَيْـًٔا أَتَأْخُذُونَهُۥ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'd3b5412640dbc71e0276267989b185350fb471ed8d46461ec7b1072dc88d7000', 'd3b5412640dbc71e0276267989b185350fb471ed8d46461ec7b1072dc88d7000', NULL, 'وان اردتم استبدال زوج مكان زوج وءاتيتم احديهن قنطارا فلا تاخذوا منه شيا اتاخذونه بهتنا واثما مبينا', 4, 8, 32, 1, 1, 81, false, NULL),
    (514, 'tanzil-uthmani-v1.1', 4, 21, 'وَكَيْفَ تَأْخُذُونَهُۥ وَقَدْ أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْضٍ وَأَخَذْنَ مِنكُم مِّيثَٰقًا غَلِيظًا', '1544221c5396404b4dc089c72b330af28b9a9854b531d491182f1c128d2dcce6', 'وَكَيْفَ تَأْخُذُونَهُۥ وَقَدْ أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْضٍ وَأَخَذْنَ مِنكُم مِّيثَٰقًا غَلِيظًا', '1544221c5396404b4dc089c72b330af28b9a9854b531d491182f1c128d2dcce6', '1544221c5396404b4dc089c72b330af28b9a9854b531d491182f1c128d2dcce6', NULL, 'وكيف تاخذونه وقد افضي بعضكم الي بعض واخذن منكم ميثقا غليظا', 4, 8, 32, 1, 1, 81, false, NULL),
    (515, 'tanzil-uthmani-v1.1', 4, 22, 'وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ إِنَّهُۥ كَانَ فَٰحِشَةً وَمَقْتًا وَسَآءَ سَبِيلًا', 'd27e6aa59acb608551a46de601ec2352212aea33f283de694a11ce8e67cb9b60', 'وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ إِنَّهُۥ كَانَ فَٰحِشَةً وَمَقْتًا وَسَآءَ سَبِيلًا', 'd27e6aa59acb608551a46de601ec2352212aea33f283de694a11ce8e67cb9b60', 'd27e6aa59acb608551a46de601ec2352212aea33f283de694a11ce8e67cb9b60', NULL, 'ولا تنكحوا ما نكح ءاباؤكم من النساء الا ما قد سلف انه كان فحشه ومقتا وساء سبيلا', 4, 8, 32, 1, 1, 81, false, NULL),
    (516, 'tanzil-uthmani-v1.1', 4, 23, 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ وَعَمَّٰتُكُمْ وَخَٰلَٰتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِىٓ أَرْضَعْنَكُمْ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمْ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَٰٓئِلُ أَبْنَآئِكُمُ ٱلَّذِينَ مِنْ أَصْلَٰبِكُمْ وَأَن تَجْمَعُوا۟ بَيْنَ ٱلْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'ec8f4f15597c14c43352eef81a980ced02d1f4f4f2c1ef6f576b1005b70bec51', 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ وَعَمَّٰتُكُمْ وَخَٰلَٰتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِىٓ أَرْضَعْنَكُمْ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمْ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَٰٓئِلُ أَبْنَآئِكُمُ ٱلَّذِينَ مِنْ أَصْلَٰبِكُمْ وَأَن تَجْمَعُوا۟ بَيْنَ ٱلْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'ec8f4f15597c14c43352eef81a980ced02d1f4f4f2c1ef6f576b1005b70bec51', 'ec8f4f15597c14c43352eef81a980ced02d1f4f4f2c1ef6f576b1005b70bec51', NULL, 'حرمت عليكم امهتكم وبناتكم واخوتكم وعمتكم وخلتكم وبنات الاخ وبنات الاخت وامهتكم التي ارضعنكم واخوتكم من الرضعه وامهت نسائكم وربئبكم التي في حجوركم من نسائكم التي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم وحلئل ابنائكم الذين من اصلبكم وان تجمعوا بين الاختين الا ما قد سلف ان الله كان غفورا رحيما', 4, 8, 32, 1, 1, 81, false, NULL),
    (517, 'tanzil-uthmani-v1.1', 4, 24, 'وَٱلْمُحْصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتْ أَيْمَٰنُكُمْ كِتَٰبَ ٱللَّهِ عَلَيْكُمْ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمْ أَن تَبْتَغُوا۟ بِأَمْوَٰلِكُم مُّحْصِنِينَ غَيْرَ مُسَٰفِحِينَ فَمَا ٱسْتَمْتَعْتُم بِهِۦ مِنْهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَٰضَيْتُم بِهِۦ مِنۢ بَعْدِ ٱلْفَرِيضَةِ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'd2d884d04cc25b0543e129003c5127f15c8755d247925857cd7b61ffd6e4b300', 'وَٱلْمُحْصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتْ أَيْمَٰنُكُمْ كِتَٰبَ ٱللَّهِ عَلَيْكُمْ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمْ أَن تَبْتَغُوا۟ بِأَمْوَٰلِكُم مُّحْصِنِينَ غَيْرَ مُسَٰفِحِينَ فَمَا ٱسْتَمْتَعْتُم بِهِۦ مِنْهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةً وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَٰضَيْتُم بِهِۦ مِنۢ بَعْدِ ٱلْفَرِيضَةِ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'd2d884d04cc25b0543e129003c5127f15c8755d247925857cd7b61ffd6e4b300', 'd2d884d04cc25b0543e129003c5127f15c8755d247925857cd7b61ffd6e4b300', NULL, 'والمحصنت من النساء الا ما ملكت ايمنكم كتب الله عليكم واحل لكم ما وراء ذلكم ان تبتغوا بامولكم محصنين غير مسفحين فما استمتعتم به منهن فاتوهن اجورهن فريضه ولا جناح عليكم فيما ترضيتم به من بعد الفريضه ان الله كان عليما حكيما', 5, 9, 33, 1, 1, 82, false, NULL),
    (518, 'tanzil-uthmani-v1.1', 4, 25, 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَٰتِ ٱلْمُؤْمِنَٰتِ فَمِن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلْمُؤْمِنَٰتِ وَٱللَّهُ أَعْلَمُ بِإِيمَٰنِكُم بَعْضُكُم مِّنۢ بَعْضٍ فَٱنكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلْمَعْرُوفِ مُحْصَنَٰتٍ غَيْرَ مُسَٰفِحَٰتٍ وَلَا مُتَّخِذَٰتِ أَخْدَانٍ فَإِذَآ أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَٰحِشَةٍ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى ٱلْمُحْصَنَٰتِ مِنَ ٱلْعَذَابِ ذَٰلِكَ لِمَنْ خَشِىَ ٱلْعَنَتَ مِنكُمْ وَأَن تَصْبِرُوا۟ خَيْرٌ لَّكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '6c368c45d91afdac92fd4acb19f933fedf49756265c7a4734530dd00de2a53bd', 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَٰتِ ٱلْمُؤْمِنَٰتِ فَمِن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلْمُؤْمِنَٰتِ وَٱللَّهُ أَعْلَمُ بِإِيمَٰنِكُم بَعْضُكُم مِّنۢ بَعْضٍ فَٱنكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلْمَعْرُوفِ مُحْصَنَٰتٍ غَيْرَ مُسَٰفِحَٰتٍ وَلَا مُتَّخِذَٰتِ أَخْدَانٍ فَإِذَآ أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَٰحِشَةٍ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى ٱلْمُحْصَنَٰتِ مِنَ ٱلْعَذَابِ ذَٰلِكَ لِمَنْ خَشِىَ ٱلْعَنَتَ مِنكُمْ وَأَن تَصْبِرُوا۟ خَيْرٌ لَّكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '6c368c45d91afdac92fd4acb19f933fedf49756265c7a4734530dd00de2a53bd', '6c368c45d91afdac92fd4acb19f933fedf49756265c7a4734530dd00de2a53bd', NULL, 'ومن لم يستطع منكم طولا ان ينكح المحصنت المؤمنت فمن ما ملكت ايمنكم من فتيتكم المؤمنت والله اعلم بايمنكم بعضكم من بعض فانكحوهن باذن اهلهن وءاتوهن اجورهن بالمعروف محصنت غير مسفحت ولا متخذت اخدان فاذا احصن فان اتين بفحشه فعليهن نصف ما علي المحصنت من العذاب ذلك لمن خشي العنت منكم وان تصبروا خير لكم والله غفور رحيم', 5, 9, 33, 1, 1, 82, false, NULL),
    (519, 'tanzil-uthmani-v1.1', 4, 26, 'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ ٱلَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '8462cb23734f354aa17a293cbf5f6500c0d08ad5c55455e017e5dab67d82797b', 'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ ٱلَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '8462cb23734f354aa17a293cbf5f6500c0d08ad5c55455e017e5dab67d82797b', '8462cb23734f354aa17a293cbf5f6500c0d08ad5c55455e017e5dab67d82797b', NULL, 'يريد الله ليبين لكم ويهديكم سنن الذين من قبلكم ويتوب عليكم والله عليم حكيم', 5, 9, 33, 1, 1, 82, false, NULL),
    (520, 'tanzil-uthmani-v1.1', 4, 27, 'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُوا۟ مَيْلًا عَظِيمًا', 'af8fa025026aad1345ac0d542c0ac040a01f853085f173a91ebf1c992dde8f41', 'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُوا۟ مَيْلًا عَظِيمًا', 'af8fa025026aad1345ac0d542c0ac040a01f853085f173a91ebf1c992dde8f41', 'af8fa025026aad1345ac0d542c0ac040a01f853085f173a91ebf1c992dde8f41', NULL, 'والله يريد ان يتوب عليكم ويريد الذين يتبعون الشهوت ان تميلوا ميلا عظيما', 5, 9, 33, 1, 1, 83, false, NULL),
    (521, 'tanzil-uthmani-v1.1', 4, 28, 'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ وَخُلِقَ ٱلْإِنسَٰنُ ضَعِيفًا', '52f5d1944b46883e551a61e06de76e1cfe6fddd7b176647e3eb820ac7accc0b1', 'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ وَخُلِقَ ٱلْإِنسَٰنُ ضَعِيفًا', '52f5d1944b46883e551a61e06de76e1cfe6fddd7b176647e3eb820ac7accc0b1', '52f5d1944b46883e551a61e06de76e1cfe6fddd7b176647e3eb820ac7accc0b1', NULL, 'يريد الله ان يخفف عنكم وخلق الانسن ضعيفا', 5, 9, 33, 1, 1, 83, false, NULL),
    (522, 'tanzil-uthmani-v1.1', 4, 29, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍ مِّنكُمْ وَلَا تَقْتُلُوٓا۟ أَنفُسَكُمْ إِنَّ ٱللَّهَ كَانَ بِكُمْ رَحِيمًا', '926f49f30408d1b0a1d7cf334bd243cb5d6a53c944b3e8db6602e812abf52fff', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍ مِّنكُمْ وَلَا تَقْتُلُوٓا۟ أَنفُسَكُمْ إِنَّ ٱللَّهَ كَانَ بِكُمْ رَحِيمًا', '926f49f30408d1b0a1d7cf334bd243cb5d6a53c944b3e8db6602e812abf52fff', '926f49f30408d1b0a1d7cf334bd243cb5d6a53c944b3e8db6602e812abf52fff', NULL, 'يايها الذين ءامنوا لا تاكلوا امولكم بينكم بالبطل الا ان تكون تجره عن تراض منكم ولا تقتلوا انفسكم ان الله كان بكم رحيما', 5, 9, 33, 1, 1, 83, false, NULL),
    (523, 'tanzil-uthmani-v1.1', 4, 30, 'وَمَن يَفْعَلْ ذَٰلِكَ عُدْوَٰنًا وَظُلْمًا فَسَوْفَ نُصْلِيهِ نَارًا وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', '272e5389f1a0db70ec7ddb7c4b2c555a479cb20425561664d075d96b0b145ec3', 'وَمَن يَفْعَلْ ذَٰلِكَ عُدْوَٰنًا وَظُلْمًا فَسَوْفَ نُصْلِيهِ نَارًا وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', '272e5389f1a0db70ec7ddb7c4b2c555a479cb20425561664d075d96b0b145ec3', '272e5389f1a0db70ec7ddb7c4b2c555a479cb20425561664d075d96b0b145ec3', NULL, 'ومن يفعل ذلك عدونا وظلما فسوف نصليه نارا وكان ذلك علي الله يسيرا', 5, 9, 33, 1, 1, 83, false, NULL),
    (524, 'tanzil-uthmani-v1.1', 4, 31, 'إِن تَجْتَنِبُوا۟ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًا كَرِيمًا', 'ebd8953c5b26e53e388e288096ff69ef819df8e570ba97a4ac3a597b6c2a2f8f', 'إِن تَجْتَنِبُوا۟ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًا كَرِيمًا', 'ebd8953c5b26e53e388e288096ff69ef819df8e570ba97a4ac3a597b6c2a2f8f', 'ebd8953c5b26e53e388e288096ff69ef819df8e570ba97a4ac3a597b6c2a2f8f', NULL, 'ان تجتنبوا كبائر ما تنهون عنه نكفر عنكم سياتكم وندخلكم مدخلا كريما', 5, 9, 33, 1, 1, 83, false, NULL),
    (525, 'tanzil-uthmani-v1.1', 4, 32, 'وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍ لِّلرِّجَالِ نَصِيبٌ مِّمَّا ٱكْتَسَبُوا۟ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا ٱكْتَسَبْنَ وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', 'fcabf56ededf33cce1cbcd2fbd76dacae2963ef10a8d1a2da67ea18e928cf09c', 'وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍ لِّلرِّجَالِ نَصِيبٌ مِّمَّا ٱكْتَسَبُوا۟ وَلِلنِّسَآءِ نَصِيبٌ مِّمَّا ٱكْتَسَبْنَ وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', 'fcabf56ededf33cce1cbcd2fbd76dacae2963ef10a8d1a2da67ea18e928cf09c', 'fcabf56ededf33cce1cbcd2fbd76dacae2963ef10a8d1a2da67ea18e928cf09c', NULL, 'ولا تتمنوا ما فضل الله به بعضكم علي بعض للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن وسلوا الله من فضله ان الله كان بكل شيء عليما', 5, 9, 33, 1, 1, 83, false, NULL),
    (526, 'tanzil-uthmani-v1.1', 4, 33, 'وَلِكُلٍّ جَعَلْنَا مَوَٰلِىَ مِمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمْ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', '84da2b877966b47fc554103526442b6e1aadc15bae6523988e423918e6fc4739', 'وَلِكُلٍّ جَعَلْنَا مَوَٰلِىَ مِمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمْ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', '84da2b877966b47fc554103526442b6e1aadc15bae6523988e423918e6fc4739', '84da2b877966b47fc554103526442b6e1aadc15bae6523988e423918e6fc4739', NULL, 'ولكل جعلنا مولي مما ترك الولدان والاقربون والذين عقدت ايمنكم فاتوهم نصيبهم ان الله كان علي كل شيء شهيدا', 5, 9, 33, 1, 1, 83, false, NULL),
    (527, 'tanzil-uthmani-v1.1', 4, 34, 'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَآ أَنفَقُوا۟ مِنْ أَمْوَٰلِهِمْ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٌ لِّلْغَيْبِ بِمَا حَفِظَ ٱللَّهُ وَٱلَّٰتِى تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهْجُرُوهُنَّ فِى ٱلْمَضَاجِعِ وَٱضْرِبُوهُنَّ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا۟ عَلَيْهِنَّ سَبِيلًا إِنَّ ٱللَّهَ كَانَ عَلِيًّا كَبِيرًا', '799610c0989ae509387ea7a77e2c9ba34c23f714224189c27ae4a8a6c1a2498b', 'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍ وَبِمَآ أَنفَقُوا۟ مِنْ أَمْوَٰلِهِمْ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٌ لِّلْغَيْبِ بِمَا حَفِظَ ٱللَّهُ وَٱلَّٰتِى تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهْجُرُوهُنَّ فِى ٱلْمَضَاجِعِ وَٱضْرِبُوهُنَّ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا۟ عَلَيْهِنَّ سَبِيلًا إِنَّ ٱللَّهَ كَانَ عَلِيًّا كَبِيرًا', '799610c0989ae509387ea7a77e2c9ba34c23f714224189c27ae4a8a6c1a2498b', '799610c0989ae509387ea7a77e2c9ba34c23f714224189c27ae4a8a6c1a2498b', NULL, 'الرجال قومون علي النساء بما فضل الله بعضهم علي بعض وبما انفقوا من امولهم فالصلحت قنتت حفظت للغيب بما حفظ الله والتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فان اطعنكم فلا تبغوا عليهن سبيلا ان الله كان عليا كبيرا', 5, 9, 33, 1, 1, 84, false, NULL),
    (528, 'tanzil-uthmani-v1.1', 4, 35, 'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَٱبْعَثُوا۟ حَكَمًا مِّنْ أَهْلِهِۦ وَحَكَمًا مِّنْ أَهْلِهَآ إِن يُرِيدَآ إِصْلَٰحًا يُوَفِّقِ ٱللَّهُ بَيْنَهُمَآ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرًا', 'd8d40f578bf433f3842671a905bb8305f7ff28eb6dadc95d40c26bcd03f81528', 'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَٱبْعَثُوا۟ حَكَمًا مِّنْ أَهْلِهِۦ وَحَكَمًا مِّنْ أَهْلِهَآ إِن يُرِيدَآ إِصْلَٰحًا يُوَفِّقِ ٱللَّهُ بَيْنَهُمَآ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرًا', 'd8d40f578bf433f3842671a905bb8305f7ff28eb6dadc95d40c26bcd03f81528', 'd8d40f578bf433f3842671a905bb8305f7ff28eb6dadc95d40c26bcd03f81528', NULL, 'وان خفتم شقاق بينهما فابعثوا حكما من اهله وحكما من اهلها ان يريدا اصلحا يوفق الله بينهما ان الله كان عليما خبيرا', 5, 9, 33, 1, 1, 84, false, NULL),
    (529, 'tanzil-uthmani-v1.1', 4, 36, 'وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَٰنُكُمْ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًا فَخُورًا', 'a47a0fae2ec653429daa17f2b0bd40438660b435ae224f527604185b15e9ffa9', 'وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَٰنُكُمْ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًا فَخُورًا', 'a47a0fae2ec653429daa17f2b0bd40438660b435ae224f527604185b15e9ffa9', 'a47a0fae2ec653429daa17f2b0bd40438660b435ae224f527604185b15e9ffa9', NULL, 'واعبدوا الله ولا تشركوا به شيا وبالولدين احسنا وبذي القربي واليتمي والمسكين والجار ذي القربي والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت ايمنكم ان الله لا يحب من كان مختالا فخورا', 5, 9, 34, 1, 1, 84, false, NULL),
    (530, 'tanzil-uthmani-v1.1', 4, 37, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَيَكْتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', '649f8a3cc9ec8a3a2500b46530084fd465664ab5ab906d854b0fbe05cc8a1fda', 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَيَكْتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', '649f8a3cc9ec8a3a2500b46530084fd465664ab5ab906d854b0fbe05cc8a1fda', '649f8a3cc9ec8a3a2500b46530084fd465664ab5ab906d854b0fbe05cc8a1fda', NULL, 'الذين يبخلون ويامرون الناس بالبخل ويكتمون ما ءاتيهم الله من فضله واعتدنا للكفرين عذابا مهينا', 5, 9, 34, 1, 1, 84, false, NULL),
    (531, 'tanzil-uthmani-v1.1', 4, 38, 'وَٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَن يَكُنِ ٱلشَّيْطَٰنُ لَهُۥ قَرِينًا فَسَآءَ قَرِينًا', 'bd7c3b671b7ee6029fcdd9e200f9a4cd18398463b7766f9a633ac26bb9574af9', 'وَٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَن يَكُنِ ٱلشَّيْطَٰنُ لَهُۥ قَرِينًا فَسَآءَ قَرِينًا', 'bd7c3b671b7ee6029fcdd9e200f9a4cd18398463b7766f9a633ac26bb9574af9', 'bd7c3b671b7ee6029fcdd9e200f9a4cd18398463b7766f9a633ac26bb9574af9', NULL, 'والذين ينفقون امولهم رئاء الناس ولا يؤمنون بالله ولا باليوم الاخر ومن يكن الشيطن له قرينا فساء قرينا', 5, 9, 34, 1, 1, 85, false, NULL),
    (532, 'tanzil-uthmani-v1.1', 4, 39, 'وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُوا۟ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُ وَكَانَ ٱللَّهُ بِهِمْ عَلِيمًا', 'd015fd013504a788483aa96117b5e4e40e828d0c176d8b0ceec42da5b1ceb15a', 'وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُوا۟ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُ وَكَانَ ٱللَّهُ بِهِمْ عَلِيمًا', 'd015fd013504a788483aa96117b5e4e40e828d0c176d8b0ceec42da5b1ceb15a', 'd015fd013504a788483aa96117b5e4e40e828d0c176d8b0ceec42da5b1ceb15a', NULL, 'وماذا عليهم لو ءامنوا بالله واليوم الاخر وانفقوا مما رزقهم الله وكان الله بهم عليما', 5, 9, 34, 1, 1, 85, false, NULL),
    (533, 'tanzil-uthmani-v1.1', 4, 40, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِن تَكُ حَسَنَةً يُضَٰعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًا', '587701336deb7c902b4eee908fcdf6045cd17cbc5c4ab4e90812afd122153b1f', 'إِنَّ ٱللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِن تَكُ حَسَنَةً يُضَٰعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًا', '587701336deb7c902b4eee908fcdf6045cd17cbc5c4ab4e90812afd122153b1f', '587701336deb7c902b4eee908fcdf6045cd17cbc5c4ab4e90812afd122153b1f', NULL, 'ان الله لا يظلم مثقال ذره وان تك حسنه يضعفها ويؤت من لدنه اجرا عظيما', 5, 9, 34, 1, 1, 85, false, NULL),
    (534, 'tanzil-uthmani-v1.1', 4, 41, 'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍۭ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدًا', 'cb8b5077f6ba0151469f85a5bd23be0e6c2112a75a0e07debddd471a23e250f1', 'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍۭ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدًا', 'cb8b5077f6ba0151469f85a5bd23be0e6c2112a75a0e07debddd471a23e250f1', 'cb8b5077f6ba0151469f85a5bd23be0e6c2112a75a0e07debddd471a23e250f1', NULL, 'فكيف اذا جئنا من كل امه بشهيد وجئنا بك علي هؤلاء شهيدا', 5, 9, 34, 1, 1, 85, false, NULL),
    (535, 'tanzil-uthmani-v1.1', 4, 42, 'يَوْمَئِذٍ يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ ٱلْأَرْضُ وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًا', 'a635bfe4a85c8993049399c75908f11e619951d27bf73cb0669b9dc83aa0fd27', 'يَوْمَئِذٍ يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ ٱلْأَرْضُ وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًا', 'a635bfe4a85c8993049399c75908f11e619951d27bf73cb0669b9dc83aa0fd27', 'a635bfe4a85c8993049399c75908f11e619951d27bf73cb0669b9dc83aa0fd27', NULL, 'يومئذ يود الذين كفروا وعصوا الرسول لو تسوي بهم الارض ولا يكتمون الله حديثا', 5, 9, 34, 1, 1, 85, false, NULL),
    (536, 'tanzil-uthmani-v1.1', 4, 43, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمْ سُكَٰرَىٰ حَتَّىٰ تَعْلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا۟ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُمْ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا', '2a39a433d51a7513b07632c2805bed91f2ba560d5c699ba3742bc7743f812731', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمْ سُكَٰرَىٰ حَتَّىٰ تَعْلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا۟ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُمْ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا', '2a39a433d51a7513b07632c2805bed91f2ba560d5c699ba3742bc7743f812731', '2a39a433d51a7513b07632c2805bed91f2ba560d5c699ba3742bc7743f812731', NULL, 'يايها الذين ءامنوا لا تقربوا الصلوه وانتم سكري حتي تعلموا ما تقولون ولا جنبا الا عابري سبيل حتي تغتسلوا وان كنتم مرضي او علي سفر او جاء احد منكم من الغائط او لمستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم ان الله كان عفوا غفورا', 5, 9, 34, 1, 1, 85, false, NULL),
    (537, 'tanzil-uthmani-v1.1', 4, 44, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يَشْتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّوا۟ ٱلسَّبِيلَ', '81660216b71a2c6d34c4acc9f2df1f29b8bea1b699b9784165a6c372ba8f5eb3', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يَشْتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّوا۟ ٱلسَّبِيلَ', '81660216b71a2c6d34c4acc9f2df1f29b8bea1b699b9784165a6c372ba8f5eb3', '81660216b71a2c6d34c4acc9f2df1f29b8bea1b699b9784165a6c372ba8f5eb3', NULL, 'الم تر الي الذين اوتوا نصيبا من الكتب يشترون الضلله ويريدون ان تضلوا السبيل', 5, 9, 34, 1, 1, 85, false, NULL),
    (538, 'tanzil-uthmani-v1.1', 4, 45, 'وَٱللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ وَكَفَىٰ بِٱللَّهِ وَلِيًّا وَكَفَىٰ بِٱللَّهِ نَصِيرًا', 'edafda8d89db88eb59de88f8e36f8d36ff17311250427b46cdb7e8119baf56f2', 'وَٱللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ وَكَفَىٰ بِٱللَّهِ وَلِيًّا وَكَفَىٰ بِٱللَّهِ نَصِيرًا', 'edafda8d89db88eb59de88f8e36f8d36ff17311250427b46cdb7e8119baf56f2', 'edafda8d89db88eb59de88f8e36f8d36ff17311250427b46cdb7e8119baf56f2', NULL, 'والله اعلم باعدائكم وكفي بالله وليا وكفي بالله نصيرا', 5, 9, 34, 1, 1, 86, false, NULL),
    (539, 'tanzil-uthmani-v1.1', 4, 46, 'مِّنَ ٱلَّذِينَ هَادُوا۟ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَٱسْمَعْ غَيْرَ مُسْمَعٍ وَرَٰعِنَا لَيًّۢا بِأَلْسِنَتِهِمْ وَطَعْنًا فِى ٱلدِّينِ وَلَوْ أَنَّهُمْ قَالُوا۟ سَمِعْنَا وَأَطَعْنَا وَٱسْمَعْ وَٱنظُرْنَا لَكَانَ خَيْرًا لَّهُمْ وَأَقْوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', '0f56b4884784b81194da9a020d2787c5bc74af8847d80c7ba63a8dbe5860bfd1', 'مِّنَ ٱلَّذِينَ هَادُوا۟ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَٱسْمَعْ غَيْرَ مُسْمَعٍ وَرَٰعِنَا لَيًّۢا بِأَلْسِنَتِهِمْ وَطَعْنًا فِى ٱلدِّينِ وَلَوْ أَنَّهُمْ قَالُوا۟ سَمِعْنَا وَأَطَعْنَا وَٱسْمَعْ وَٱنظُرْنَا لَكَانَ خَيْرًا لَّهُمْ وَأَقْوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', '0f56b4884784b81194da9a020d2787c5bc74af8847d80c7ba63a8dbe5860bfd1', '0f56b4884784b81194da9a020d2787c5bc74af8847d80c7ba63a8dbe5860bfd1', NULL, 'من الذين هادوا يحرفون الكلم عن مواضعه ويقولون سمعنا وعصينا واسمع غير مسمع ورعنا ليا بالسنتهم وطعنا في الدين ولو انهم قالوا سمعنا واطعنا واسمع وانظرنا لكان خيرا لهم واقوم ولكن لعنهم الله بكفرهم فلا يؤمنون الا قليلا', 5, 9, 34, 1, 1, 86, false, NULL),
    (540, 'tanzil-uthmani-v1.1', 4, 47, 'يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ ءَامِنُوا۟ بِمَا نَزَّلْنَا مُصَدِّقًا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَىٰٓ أَدْبَارِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَٰبَ ٱلسَّبْتِ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', '5a92721ea374b044c07b65713edaa30760cdabc37af8698142f903a4251b3203', 'يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ ءَامِنُوا۟ بِمَا نَزَّلْنَا مُصَدِّقًا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَىٰٓ أَدْبَارِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَٰبَ ٱلسَّبْتِ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', '5a92721ea374b044c07b65713edaa30760cdabc37af8698142f903a4251b3203', '5a92721ea374b044c07b65713edaa30760cdabc37af8698142f903a4251b3203', NULL, 'يايها الذين اوتوا الكتب ءامنوا بما نزلنا مصدقا لما معكم من قبل ان نطمس وجوها فنردها علي ادبارها او نلعنهم كما لعنا اصحب السبت وكان امر الله مفعولا', 5, 9, 34, 1, 1, 86, false, NULL),
    (541, 'tanzil-uthmani-v1.1', 4, 48, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا', '2ea45cd65ab08c525376da2a74ec4c44136da9cdd08aa295017bf5e2225b2450', 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا', '2ea45cd65ab08c525376da2a74ec4c44136da9cdd08aa295017bf5e2225b2450', '2ea45cd65ab08c525376da2a74ec4c44136da9cdd08aa295017bf5e2225b2450', NULL, 'ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد افتري اثما عظيما', 5, 9, 34, 1, 1, 86, false, NULL),
    (542, 'tanzil-uthmani-v1.1', 4, 49, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُم بَلِ ٱللَّهُ يُزَكِّى مَن يَشَآءُ وَلَا يُظْلَمُونَ فَتِيلًا', '6de1ea13c1493f2553ea4f08d1693accc2bb36980c769fa902abe9bdaec0c4b8', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُم بَلِ ٱللَّهُ يُزَكِّى مَن يَشَآءُ وَلَا يُظْلَمُونَ فَتِيلًا', '6de1ea13c1493f2553ea4f08d1693accc2bb36980c769fa902abe9bdaec0c4b8', '6de1ea13c1493f2553ea4f08d1693accc2bb36980c769fa902abe9bdaec0c4b8', NULL, 'الم تر الي الذين يزكون انفسهم بل الله يزكي من يشاء ولا يظلمون فتيلا', 5, 9, 34, 1, 1, 86, false, NULL),
    (543, 'tanzil-uthmani-v1.1', 4, 50, 'ٱنظُرْ كَيْفَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَكَفَىٰ بِهِۦٓ إِثْمًا مُّبِينًا', '48bbb9836b5110395410c15621484ded42e3628dd5c94f0ffb247adebe88ea99', 'ٱنظُرْ كَيْفَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَكَفَىٰ بِهِۦٓ إِثْمًا مُّبِينًا', '48bbb9836b5110395410c15621484ded42e3628dd5c94f0ffb247adebe88ea99', '48bbb9836b5110395410c15621484ded42e3628dd5c94f0ffb247adebe88ea99', NULL, 'انظر كيف يفترون علي الله الكذب وكفي به اثما مبينا', 5, 9, 34, 1, 1, 86, false, NULL),
    (544, 'tanzil-uthmani-v1.1', 4, 51, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يُؤْمِنُونَ بِٱلْجِبْتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا۟ هَٰٓؤُلَآءِ أَهْدَىٰ مِنَ ٱلَّذِينَ ءَامَنُوا۟ سَبِيلًا', '08e4175afeb03b2a6a7045f7dfbb3ade711434e2141dd2e1ecef34d3e87ecfca', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًا مِّنَ ٱلْكِتَٰبِ يُؤْمِنُونَ بِٱلْجِبْتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا۟ هَٰٓؤُلَآءِ أَهْدَىٰ مِنَ ٱلَّذِينَ ءَامَنُوا۟ سَبِيلًا', '08e4175afeb03b2a6a7045f7dfbb3ade711434e2141dd2e1ecef34d3e87ecfca', '08e4175afeb03b2a6a7045f7dfbb3ade711434e2141dd2e1ecef34d3e87ecfca', NULL, 'الم تر الي الذين اوتوا نصيبا من الكتب يؤمنون بالجبت والطغوت ويقولون للذين كفروا هؤلاء اهدي من الذين ءامنوا سبيلا', 5, 9, 34, 1, 1, 86, false, NULL),
    (545, 'tanzil-uthmani-v1.1', 4, 52, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ وَمَن يَلْعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا', '3acb517866b64d3ac00e9bb07954583b56adf94326241193f25bfdc95bdc1f8a', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ وَمَن يَلْعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا', '3acb517866b64d3ac00e9bb07954583b56adf94326241193f25bfdc95bdc1f8a', '3acb517866b64d3ac00e9bb07954583b56adf94326241193f25bfdc95bdc1f8a', NULL, 'اولئك الذين لعنهم الله ومن يلعن الله فلن تجد له نصيرا', 5, 9, 34, 1, 1, 87, false, NULL),
    (546, 'tanzil-uthmani-v1.1', 4, 53, 'أَمْ لَهُمْ نَصِيبٌ مِّنَ ٱلْمُلْكِ فَإِذًا لَّا يُؤْتُونَ ٱلنَّاسَ نَقِيرًا', '01af7d1d890af3b4583f34621c1dfa57a744f2cfad08311c276d00ed4b1222ea', 'أَمْ لَهُمْ نَصِيبٌ مِّنَ ٱلْمُلْكِ فَإِذًا لَّا يُؤْتُونَ ٱلنَّاسَ نَقِيرًا', '01af7d1d890af3b4583f34621c1dfa57a744f2cfad08311c276d00ed4b1222ea', '01af7d1d890af3b4583f34621c1dfa57a744f2cfad08311c276d00ed4b1222ea', NULL, 'ام لهم نصيب من الملك فاذا لا يؤتون الناس نقيرا', 5, 9, 34, 1, 1, 87, false, NULL),
    (547, 'tanzil-uthmani-v1.1', 4, 54, 'أَمْ يَحْسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ فَقَدْ ءَاتَيْنَآ ءَالَ إِبْرَٰهِيمَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَءَاتَيْنَٰهُم مُّلْكًا عَظِيمًا', '9137261f7d2467ccc09967cae0efd4d741e919d5bf93cd53b6bf80fae85a1565', 'أَمْ يَحْسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ فَقَدْ ءَاتَيْنَآ ءَالَ إِبْرَٰهِيمَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَءَاتَيْنَٰهُم مُّلْكًا عَظِيمًا', '9137261f7d2467ccc09967cae0efd4d741e919d5bf93cd53b6bf80fae85a1565', '9137261f7d2467ccc09967cae0efd4d741e919d5bf93cd53b6bf80fae85a1565', NULL, 'ام يحسدون الناس علي ما ءاتيهم الله من فضله فقد ءاتينا ءال ابرهيم الكتب والحكمه وءاتينهم ملكا عظيما', 5, 9, 34, 1, 1, 87, false, NULL),
    (548, 'tanzil-uthmani-v1.1', 4, 55, 'فَمِنْهُم مَّنْ ءَامَنَ بِهِۦ وَمِنْهُم مَّن صَدَّ عَنْهُ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', '43a895e497c769ecdf26286ad17637dad061d3a9ecd6d7d693d3f7b0a932e3bb', 'فَمِنْهُم مَّنْ ءَامَنَ بِهِۦ وَمِنْهُم مَّن صَدَّ عَنْهُ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', '43a895e497c769ecdf26286ad17637dad061d3a9ecd6d7d693d3f7b0a932e3bb', '43a895e497c769ecdf26286ad17637dad061d3a9ecd6d7d693d3f7b0a932e3bb', NULL, 'فمنهم من ءامن به ومنهم من صد عنه وكفي بجهنم سعيرا', 5, 9, 34, 1, 1, 87, false, NULL),
    (549, 'tanzil-uthmani-v1.1', 4, 56, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا سَوْفَ نُصْلِيهِمْ نَارًا كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَٰهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا۟ ٱلْعَذَابَ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمًا', '619fe1ecd437b6263b2d486100496c3c8cb2a8a48ded6b58076caa61e4eb8dc8', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا سَوْفَ نُصْلِيهِمْ نَارًا كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَٰهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا۟ ٱلْعَذَابَ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمًا', '619fe1ecd437b6263b2d486100496c3c8cb2a8a48ded6b58076caa61e4eb8dc8', '619fe1ecd437b6263b2d486100496c3c8cb2a8a48ded6b58076caa61e4eb8dc8', NULL, 'ان الذين كفروا بايتنا سوف نصليهم نارا كلما نضجت جلودهم بدلنهم جلودا غيرها ليذوقوا العذاب ان الله كان عزيزا حكيما', 5, 9, 34, 1, 1, 87, false, NULL),
    (550, 'tanzil-uthmani-v1.1', 4, 57, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا لَّهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا', '0338224591164050cc8b98b08fdbc24cfb991f28a964bbf48d4e25b026988dac', 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا لَّهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا', '0338224591164050cc8b98b08fdbc24cfb991f28a964bbf48d4e25b026988dac', '0338224591164050cc8b98b08fdbc24cfb991f28a964bbf48d4e25b026988dac', NULL, 'والذين ءامنوا وعملوا الصلحت سندخلهم جنت تجري من تحتها الانهر خلدين فيها ابدا لهم فيها ازوج مطهره وندخلهم ظلا ظليلا', 5, 9, 34, 1, 1, 87, false, NULL),
    (551, 'tanzil-uthmani-v1.1', 4, 58, 'إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَٰنَٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ٱلنَّاسِ أَن تَحْكُمُوا۟ بِٱلْعَدْلِ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ إِنَّ ٱللَّهَ كَانَ سَمِيعًۢا بَصِيرًا', 'ad002b97ede2da5d77d80c26e151a6331d2b6a4b5f1f156bf531e4be2be98847', 'إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَٰنَٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ٱلنَّاسِ أَن تَحْكُمُوا۟ بِٱلْعَدْلِ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ إِنَّ ٱللَّهَ كَانَ سَمِيعًۢا بَصِيرًا', 'ad002b97ede2da5d77d80c26e151a6331d2b6a4b5f1f156bf531e4be2be98847', 'ad002b97ede2da5d77d80c26e151a6331d2b6a4b5f1f156bf531e4be2be98847', NULL, 'ان الله يامركم ان تؤدوا الامنت الي اهلها واذا حكمتم بين الناس ان تحكموا بالعدل ان الله نعما يعظكم به ان الله كان سميعا بصيرا', 5, 9, 35, 1, 1, 87, false, NULL),
    (552, 'tanzil-uthmani-v1.1', 4, 59, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', '8af922a2ec10e54b383cd649496bbb7e1c98d3570eaa9e022d4c9ab60c2f132b', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', '8af922a2ec10e54b383cd649496bbb7e1c98d3570eaa9e022d4c9ab60c2f132b', '8af922a2ec10e54b383cd649496bbb7e1c98d3570eaa9e022d4c9ab60c2f132b', NULL, 'يايها الذين ءامنوا اطيعوا الله واطيعوا الرسول واولي الامر منكم فان تنزعتم في شيء فردوه الي الله والرسول ان كنتم تؤمنون بالله واليوم الاخر ذلك خير واحسن تاويلا', 5, 9, 35, 1, 1, 87, false, NULL),
    (553, 'tanzil-uthmani-v1.1', 4, 60, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يَزْعُمُونَ أَنَّهُمْ ءَامَنُوا۟ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓا۟ إِلَى ٱلطَّٰغُوتِ وَقَدْ أُمِرُوٓا۟ أَن يَكْفُرُوا۟ بِهِۦ وَيُرِيدُ ٱلشَّيْطَٰنُ أَن يُضِلَّهُمْ ضَلَٰلًۢا بَعِيدًا', '45cff9c6c07d878e9e369e92e60983ce238c1cea83068315c3e91d67511dad35', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يَزْعُمُونَ أَنَّهُمْ ءَامَنُوا۟ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓا۟ إِلَى ٱلطَّٰغُوتِ وَقَدْ أُمِرُوٓا۟ أَن يَكْفُرُوا۟ بِهِۦ وَيُرِيدُ ٱلشَّيْطَٰنُ أَن يُضِلَّهُمْ ضَلَٰلًۢا بَعِيدًا', '45cff9c6c07d878e9e369e92e60983ce238c1cea83068315c3e91d67511dad35', '45cff9c6c07d878e9e369e92e60983ce238c1cea83068315c3e91d67511dad35', NULL, 'الم تر الي الذين يزعمون انهم ءامنوا بما انزل اليك وما انزل من قبلك يريدون ان يتحاكموا الي الطغوت وقد امروا ان يكفروا به ويريد الشيطن ان يضلهم ضللا بعيدا', 5, 9, 35, 1, 1, 88, false, NULL),
    (554, 'tanzil-uthmani-v1.1', 4, 61, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيْتَ ٱلْمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًا', 'feeef77d5e257ef48c5b5c04271fa1d9583d5313e164ea8c6f5784b2f9f66715', 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيْتَ ٱلْمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًا', 'feeef77d5e257ef48c5b5c04271fa1d9583d5313e164ea8c6f5784b2f9f66715', 'feeef77d5e257ef48c5b5c04271fa1d9583d5313e164ea8c6f5784b2f9f66715', NULL, 'واذا قيل لهم تعالوا الي ما انزل الله والي الرسول رايت المنفقين يصدون عنك صدودا', 5, 9, 35, 1, 1, 88, false, NULL),
    (555, 'tanzil-uthmani-v1.1', 4, 62, 'فَكَيْفَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ ثُمَّ جَآءُوكَ يَحْلِفُونَ بِٱللَّهِ إِنْ أَرَدْنَآ إِلَّآ إِحْسَٰنًا وَتَوْفِيقًا', '1ec12fb2ff3ccaa788c6c7be62db3cc9cbf1c63d5f71f41daacf29d981fed277', 'فَكَيْفَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ ثُمَّ جَآءُوكَ يَحْلِفُونَ بِٱللَّهِ إِنْ أَرَدْنَآ إِلَّآ إِحْسَٰنًا وَتَوْفِيقًا', '1ec12fb2ff3ccaa788c6c7be62db3cc9cbf1c63d5f71f41daacf29d981fed277', '1ec12fb2ff3ccaa788c6c7be62db3cc9cbf1c63d5f71f41daacf29d981fed277', NULL, 'فكيف اذا اصبتهم مصيبه بما قدمت ايديهم ثم جاءوك يحلفون بالله ان اردنا الا احسنا وتوفيقا', 5, 9, 35, 1, 1, 88, false, NULL),
    (556, 'tanzil-uthmani-v1.1', 4, 63, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَعْلَمُ ٱللَّهُ مَا فِى قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِىٓ أَنفُسِهِمْ قَوْلًۢا بَلِيغًا', '59cba5309bd864455dfda53f8756b77427ea213404fbd2dc1e5d030e8663c631', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَعْلَمُ ٱللَّهُ مَا فِى قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِىٓ أَنفُسِهِمْ قَوْلًۢا بَلِيغًا', '59cba5309bd864455dfda53f8756b77427ea213404fbd2dc1e5d030e8663c631', '59cba5309bd864455dfda53f8756b77427ea213404fbd2dc1e5d030e8663c631', NULL, 'اولئك الذين يعلم الله ما في قلوبهم فاعرض عنهم وعظهم وقل لهم في انفسهم قولا بليغا', 5, 9, 35, 1, 1, 88, false, NULL),
    (557, 'tanzil-uthmani-v1.1', 4, 64, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ ٱللَّهِ وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوٓا۟ أَنفُسَهُمْ جَآءُوكَ فَٱسْتَغْفَرُوا۟ ٱللَّهَ وَٱسْتَغْفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابًا رَّحِيمًا', '7a4e5c1604bf21d300d7a4c249b80696b6b4c430ccbcc0db7f88471e7abd3ffa', 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ ٱللَّهِ وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوٓا۟ أَنفُسَهُمْ جَآءُوكَ فَٱسْتَغْفَرُوا۟ ٱللَّهَ وَٱسْتَغْفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابًا رَّحِيمًا', '7a4e5c1604bf21d300d7a4c249b80696b6b4c430ccbcc0db7f88471e7abd3ffa', '7a4e5c1604bf21d300d7a4c249b80696b6b4c430ccbcc0db7f88471e7abd3ffa', NULL, 'وما ارسلنا من رسول الا ليطاع باذن الله ولو انهم اذ ظلموا انفسهم جاءوك فاستغفروا الله واستغفر لهم الرسول لوجدوا الله توابا رحيما', 5, 9, 35, 1, 1, 88, false, NULL),
    (558, 'tanzil-uthmani-v1.1', 4, 65, 'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًا', 'ef4aa933429860f4a72f933820d3a0b8cded75b40997b39d376c9bffa16ecfbc', 'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًا', 'ef4aa933429860f4a72f933820d3a0b8cded75b40997b39d376c9bffa16ecfbc', 'ef4aa933429860f4a72f933820d3a0b8cded75b40997b39d376c9bffa16ecfbc', NULL, 'فلا وربك لا يؤمنون حتي يحكموك فيما شجر بينهم ثم لا يجدوا في انفسهم حرجا مما قضيت ويسلموا تسليما', 5, 9, 35, 1, 1, 88, false, NULL),
    (559, 'tanzil-uthmani-v1.1', 4, 66, 'وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ ٱقْتُلُوٓا۟ أَنفُسَكُمْ أَوِ ٱخْرُجُوا۟ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٌ مِّنْهُمْ وَلَوْ أَنَّهُمْ فَعَلُوا۟ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيْرًا لَّهُمْ وَأَشَدَّ تَثْبِيتًا', 'b9693acb350caac242290ffa3b82978ea1cccfa8dc41d23f4ba3f9607678bb0b', 'وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ ٱقْتُلُوٓا۟ أَنفُسَكُمْ أَوِ ٱخْرُجُوا۟ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٌ مِّنْهُمْ وَلَوْ أَنَّهُمْ فَعَلُوا۟ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيْرًا لَّهُمْ وَأَشَدَّ تَثْبِيتًا', 'b9693acb350caac242290ffa3b82978ea1cccfa8dc41d23f4ba3f9607678bb0b', 'b9693acb350caac242290ffa3b82978ea1cccfa8dc41d23f4ba3f9607678bb0b', NULL, 'ولو انا كتبنا عليهم ان اقتلوا انفسكم او اخرجوا من ديركم ما فعلوه الا قليل منهم ولو انهم فعلوا ما يوعظون به لكان خيرا لهم واشد تثبيتا', 5, 9, 35, 1, 1, 89, false, NULL),
    (560, 'tanzil-uthmani-v1.1', 4, 67, 'وَإِذًا لَّـَٔاتَيْنَٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًا', 'b4ba89a1ebb37a39b842c76299abe2ef792d203dad341965f0063c397942d1f7', 'وَإِذًا لَّـَٔاتَيْنَٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًا', 'b4ba89a1ebb37a39b842c76299abe2ef792d203dad341965f0063c397942d1f7', 'b4ba89a1ebb37a39b842c76299abe2ef792d203dad341965f0063c397942d1f7', NULL, 'واذا لاتينهم من لدنا اجرا عظيما', 5, 9, 35, 1, 1, 89, false, NULL),
    (561, 'tanzil-uthmani-v1.1', 4, 68, 'وَلَهَدَيْنَٰهُمْ صِرَٰطًا مُّسْتَقِيمًا', '5ccdfc5003204b2e59abfb813652367522b93e5c3132964fc06f3f129dd0b3fe', 'وَلَهَدَيْنَٰهُمْ صِرَٰطًا مُّسْتَقِيمًا', '5ccdfc5003204b2e59abfb813652367522b93e5c3132964fc06f3f129dd0b3fe', '5ccdfc5003204b2e59abfb813652367522b93e5c3132964fc06f3f129dd0b3fe', NULL, 'ولهدينهم صرطا مستقيما', 5, 9, 35, 1, 1, 89, false, NULL),
    (562, 'tanzil-uthmani-v1.1', 4, 69, 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَٰٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَ وَحَسُنَ أُو۟لَٰٓئِكَ رَفِيقًا', '9d076eb20361e4a017ca1bfa9d85fcf66f480d7005f4e8f91718d9ae5df4f4e8', 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَٰٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَ وَحَسُنَ أُو۟لَٰٓئِكَ رَفِيقًا', '9d076eb20361e4a017ca1bfa9d85fcf66f480d7005f4e8f91718d9ae5df4f4e8', '9d076eb20361e4a017ca1bfa9d85fcf66f480d7005f4e8f91718d9ae5df4f4e8', NULL, 'ومن يطع الله والرسول فاولئك مع الذين انعم الله عليهم من النبين والصديقين والشهداء والصلحين وحسن اولئك رفيقا', 5, 9, 35, 1, 1, 89, false, NULL),
    (563, 'tanzil-uthmani-v1.1', 4, 70, 'ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ وَكَفَىٰ بِٱللَّهِ عَلِيمًا', '1bfebf9b252436e28676c5e7bfa1f29de3b4681d7a3d14fcb5aa7673e24ae79d', 'ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ وَكَفَىٰ بِٱللَّهِ عَلِيمًا', '1bfebf9b252436e28676c5e7bfa1f29de3b4681d7a3d14fcb5aa7673e24ae79d', '1bfebf9b252436e28676c5e7bfa1f29de3b4681d7a3d14fcb5aa7673e24ae79d', NULL, 'ذلك الفضل من الله وكفي بالله عليما', 5, 9, 35, 1, 1, 89, false, NULL),
    (564, 'tanzil-uthmani-v1.1', 4, 71, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ خُذُوا۟ حِذْرَكُمْ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِيعًا', 'f58092042609db428cd156fda87146d0fed8a75060ce8c1acf7e45825cd78366', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ خُذُوا۟ حِذْرَكُمْ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِيعًا', 'f58092042609db428cd156fda87146d0fed8a75060ce8c1acf7e45825cd78366', 'f58092042609db428cd156fda87146d0fed8a75060ce8c1acf7e45825cd78366', NULL, 'يايها الذين ءامنوا خذوا حذركم فانفروا ثبات او انفروا جميعا', 5, 9, 35, 1, 1, 89, false, NULL),
    (565, 'tanzil-uthmani-v1.1', 4, 72, 'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ فَإِنْ أَصَٰبَتْكُم مُّصِيبَةٌ قَالَ قَدْ أَنْعَمَ ٱللَّهُ عَلَىَّ إِذْ لَمْ أَكُن مَّعَهُمْ شَهِيدًا', '57d5a76f1503382135513328267ec168535c8e9c9dde252b41a3b18b812b7b93', 'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ فَإِنْ أَصَٰبَتْكُم مُّصِيبَةٌ قَالَ قَدْ أَنْعَمَ ٱللَّهُ عَلَىَّ إِذْ لَمْ أَكُن مَّعَهُمْ شَهِيدًا', '57d5a76f1503382135513328267ec168535c8e9c9dde252b41a3b18b812b7b93', '57d5a76f1503382135513328267ec168535c8e9c9dde252b41a3b18b812b7b93', NULL, 'وان منكم لمن ليبطئن فان اصبتكم مصيبه قال قد انعم الله علي اذ لم اكن معهم شهيدا', 5, 9, 35, 1, 1, 89, false, NULL),
    (566, 'tanzil-uthmani-v1.1', 4, 73, 'وَلَئِنْ أَصَٰبَكُمْ فَضْلٌ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمْ تَكُنۢ بَيْنَكُمْ وَبَيْنَهُۥ مَوَدَّةٌ يَٰلَيْتَنِى كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًا', '88ecf5e3e2be77ee5f50d9e53f98c3b73320424fb721ef20a5e33d30afd79977', 'وَلَئِنْ أَصَٰبَكُمْ فَضْلٌ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمْ تَكُنۢ بَيْنَكُمْ وَبَيْنَهُۥ مَوَدَّةٌ يَٰلَيْتَنِى كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًا', '88ecf5e3e2be77ee5f50d9e53f98c3b73320424fb721ef20a5e33d30afd79977', '88ecf5e3e2be77ee5f50d9e53f98c3b73320424fb721ef20a5e33d30afd79977', NULL, 'ولئن اصبكم فضل من الله ليقولن كان لم تكن بينكم وبينه موده يليتني كنت معهم فافوز فوزا عظيما', 5, 9, 35, 1, 1, 89, false, NULL),
    (567, 'tanzil-uthmani-v1.1', 4, 74, 'فَلْيُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشْرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ وَمَن يُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ فَيُقْتَلْ أَوْ يَغْلِبْ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', '7bd3fe6e7178224074204653027bd8e290bfedab14b019a5e6fc181da9c5a429', 'فَلْيُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشْرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ وَمَن يُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ فَيُقْتَلْ أَوْ يَغْلِبْ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', '7bd3fe6e7178224074204653027bd8e290bfedab14b019a5e6fc181da9c5a429', '7bd3fe6e7178224074204653027bd8e290bfedab14b019a5e6fc181da9c5a429', NULL, 'فليقتل في سبيل الله الذين يشرون الحيوه الدنيا بالاخره ومن يقتل في سبيل الله فيقتل او يغلب فسوف نؤتيه اجرا عظيما', 5, 9, 36, 1, 1, 89, false, NULL),
    (568, 'tanzil-uthmani-v1.1', 4, 75, 'وَمَا لَكُمْ لَا تُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخْرِجْنَا مِنْ هَٰذِهِ ٱلْقَرْيَةِ ٱلظَّالِمِ أَهْلُهَا وَٱجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَٱجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', '96cb85402586a0d8d81d22770ac6d7dbe4e73e8382e356d16878fd9a539c3e0f', 'وَمَا لَكُمْ لَا تُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخْرِجْنَا مِنْ هَٰذِهِ ٱلْقَرْيَةِ ٱلظَّالِمِ أَهْلُهَا وَٱجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَٱجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', '96cb85402586a0d8d81d22770ac6d7dbe4e73e8382e356d16878fd9a539c3e0f', '96cb85402586a0d8d81d22770ac6d7dbe4e73e8382e356d16878fd9a539c3e0f', NULL, 'وما لكم لا تقتلون في سبيل الله والمستضعفين من الرجال والنساء والولدن الذين يقولون ربنا اخرجنا من هذه القريه الظالم اهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا', 5, 9, 36, 1, 1, 90, false, NULL),
    (569, 'tanzil-uthmani-v1.1', 4, 76, 'ٱلَّذِينَ ءَامَنُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ كَفَرُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓا۟ أَوْلِيَآءَ ٱلشَّيْطَٰنِ إِنَّ كَيْدَ ٱلشَّيْطَٰنِ كَانَ ضَعِيفًا', 'df904190eb85d27efd2b724c52a369492ba7930d66139f882e9d86f775e2d9c9', 'ٱلَّذِينَ ءَامَنُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ كَفَرُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓا۟ أَوْلِيَآءَ ٱلشَّيْطَٰنِ إِنَّ كَيْدَ ٱلشَّيْطَٰنِ كَانَ ضَعِيفًا', 'df904190eb85d27efd2b724c52a369492ba7930d66139f882e9d86f775e2d9c9', 'df904190eb85d27efd2b724c52a369492ba7930d66139f882e9d86f775e2d9c9', NULL, 'الذين ءامنوا يقتلون في سبيل الله والذين كفروا يقتلون في سبيل الطغوت فقتلوا اولياء الشيطن ان كيد الشيطن كان ضعيفا', 5, 9, 36, 1, 1, 90, false, NULL),
    (570, 'tanzil-uthmani-v1.1', 4, 77, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمْ كُفُّوٓا۟ أَيْدِيَكُمْ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ ٱلنَّاسَ كَخَشْيَةِ ٱللَّهِ أَوْ أَشَدَّ خَشْيَةً وَقَالُوا۟ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا ٱلْقِتَالَ لَوْلَآ أَخَّرْتَنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ قُلْ مَتَٰعُ ٱلدُّنْيَا قَلِيلٌ وَٱلْـَٔاخِرَةُ خَيْرٌ لِّمَنِ ٱتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا', '06af19d431f88b6e43c018ea804b5c38f58754e11be87ed17457046286e4a9fc', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمْ كُفُّوٓا۟ أَيْدِيَكُمْ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ إِذَا فَرِيقٌ مِّنْهُمْ يَخْشَوْنَ ٱلنَّاسَ كَخَشْيَةِ ٱللَّهِ أَوْ أَشَدَّ خَشْيَةً وَقَالُوا۟ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا ٱلْقِتَالَ لَوْلَآ أَخَّرْتَنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ قُلْ مَتَٰعُ ٱلدُّنْيَا قَلِيلٌ وَٱلْـَٔاخِرَةُ خَيْرٌ لِّمَنِ ٱتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا', '06af19d431f88b6e43c018ea804b5c38f58754e11be87ed17457046286e4a9fc', '06af19d431f88b6e43c018ea804b5c38f58754e11be87ed17457046286e4a9fc', NULL, 'الم تر الي الذين قيل لهم كفوا ايديكم واقيموا الصلوه وءاتوا الزكوه فلما كتب عليهم القتال اذا فريق منهم يخشون الناس كخشيه الله او اشد خشيه وقالوا ربنا لم كتبت علينا القتال لولا اخرتنا الي اجل قريب قل متع الدنيا قليل والاخره خير لمن اتقي ولا تظلمون فتيلا', 5, 9, 36, 1, 1, 90, false, NULL),
    (571, 'tanzil-uthmani-v1.1', 4, 78, 'أَيْنَمَا تَكُونُوا۟ يُدْرِككُّمُ ٱلْمَوْتُ وَلَوْ كُنتُمْ فِى بُرُوجٍ مُّشَيَّدَةٍ وَإِن تُصِبْهُمْ حَسَنَةٌ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِ ٱللَّهِ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِكَ قُلْ كُلٌّ مِّنْ عِندِ ٱللَّهِ فَمَالِ هَٰٓؤُلَآءِ ٱلْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا', '93779b7a51c0e10598578ea9882c9bd5c3e0cdaead215cedb3924861c2cfcb53', 'أَيْنَمَا تَكُونُوا۟ يُدْرِككُّمُ ٱلْمَوْتُ وَلَوْ كُنتُمْ فِى بُرُوجٍ مُّشَيَّدَةٍ وَإِن تُصِبْهُمْ حَسَنَةٌ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِ ٱللَّهِ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِكَ قُلْ كُلٌّ مِّنْ عِندِ ٱللَّهِ فَمَالِ هَٰٓؤُلَآءِ ٱلْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا', '93779b7a51c0e10598578ea9882c9bd5c3e0cdaead215cedb3924861c2cfcb53', '93779b7a51c0e10598578ea9882c9bd5c3e0cdaead215cedb3924861c2cfcb53', NULL, 'اينما تكونوا يدرككم الموت ولو كنتم في بروج مشيده وان تصبهم حسنه يقولوا هذه من عند الله وان تصبهم سيئه يقولوا هذه من عندك قل كل من عند الله فمال هؤلاء القوم لا يكادون يفقهون حديثا', 5, 9, 36, 1, 1, 90, false, NULL),
    (572, 'tanzil-uthmani-v1.1', 4, 79, 'مَّآ أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ ٱللَّهِ وَمَآ أَصَابَكَ مِن سَيِّئَةٍ فَمِن نَّفْسِكَ وَأَرْسَلْنَٰكَ لِلنَّاسِ رَسُولًا وَكَفَىٰ بِٱللَّهِ شَهِيدًا', '909e772c37c5265e32562bd71da79169a72db1d078d8c0cdc90537deb5a5d2a5', 'مَّآ أَصَابَكَ مِنْ حَسَنَةٍ فَمِنَ ٱللَّهِ وَمَآ أَصَابَكَ مِن سَيِّئَةٍ فَمِن نَّفْسِكَ وَأَرْسَلْنَٰكَ لِلنَّاسِ رَسُولًا وَكَفَىٰ بِٱللَّهِ شَهِيدًا', '909e772c37c5265e32562bd71da79169a72db1d078d8c0cdc90537deb5a5d2a5', '909e772c37c5265e32562bd71da79169a72db1d078d8c0cdc90537deb5a5d2a5', NULL, 'ما اصابك من حسنه فمن الله وما اصابك من سيئه فمن نفسك وارسلنك للناس رسولا وكفي بالله شهيدا', 5, 9, 36, 1, 1, 90, false, NULL),
    (573, 'tanzil-uthmani-v1.1', 4, 80, 'مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ وَمَن تَوَلَّىٰ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا', '155ab6f08902007a3613fa1fa3356b4fb48a9e314f5e1bf6429ce34b44126938', 'مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ وَمَن تَوَلَّىٰ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا', '155ab6f08902007a3613fa1fa3356b4fb48a9e314f5e1bf6429ce34b44126938', '155ab6f08902007a3613fa1fa3356b4fb48a9e314f5e1bf6429ce34b44126938', NULL, 'من يطع الرسول فقد اطاع الله ومن تولي فما ارسلنك عليهم حفيظا', 5, 9, 36, 1, 1, 91, false, NULL),
    (574, 'tanzil-uthmani-v1.1', 4, 81, 'وَيَقُولُونَ طَاعَةٌ فَإِذَا بَرَزُوا۟ مِنْ عِندِكَ بَيَّتَ طَآئِفَةٌ مِّنْهُمْ غَيْرَ ٱلَّذِى تَقُولُ وَٱللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '526eb37e57bd7da5e5eb2590375ac3c46afe9672439ae629bf2a4fe784c2a9a7', 'وَيَقُولُونَ طَاعَةٌ فَإِذَا بَرَزُوا۟ مِنْ عِندِكَ بَيَّتَ طَآئِفَةٌ مِّنْهُمْ غَيْرَ ٱلَّذِى تَقُولُ وَٱللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '526eb37e57bd7da5e5eb2590375ac3c46afe9672439ae629bf2a4fe784c2a9a7', '526eb37e57bd7da5e5eb2590375ac3c46afe9672439ae629bf2a4fe784c2a9a7', NULL, 'ويقولون طاعه فاذا برزوا من عندك بيت طائفه منهم غير الذي تقول والله يكتب ما يبيتون فاعرض عنهم وتوكل علي الله وكفي بالله وكيلا', 5, 9, 36, 1, 1, 91, false, NULL),
    (575, 'tanzil-uthmani-v1.1', 4, 82, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ٱللَّهِ لَوَجَدُوا۟ فِيهِ ٱخْتِلَٰفًا كَثِيرًا', '5f2cee432dca3267b7d758caa54ee3ffa7b748da508739cb53bb0fd13de11d03', 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ٱللَّهِ لَوَجَدُوا۟ فِيهِ ٱخْتِلَٰفًا كَثِيرًا', '5f2cee432dca3267b7d758caa54ee3ffa7b748da508739cb53bb0fd13de11d03', '5f2cee432dca3267b7d758caa54ee3ffa7b748da508739cb53bb0fd13de11d03', NULL, 'افلا يتدبرون القرءان ولو كان من عند غير الله لوجدوا فيه اختلفا كثيرا', 5, 9, 36, 1, 1, 91, false, NULL),
    (576, 'tanzil-uthmani-v1.1', 4, 83, 'وَإِذَا جَآءَهُمْ أَمْرٌ مِّنَ ٱلْأَمْنِ أَوِ ٱلْخَوْفِ أَذَاعُوا۟ بِهِۦ وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَٱتَّبَعْتُمُ ٱلشَّيْطَٰنَ إِلَّا قَلِيلًا', '863fb9d8edf7ab574eab7d231e5355f3bd056fe7ba5e9eae35bc25fa7d55044f', 'وَإِذَا جَآءَهُمْ أَمْرٌ مِّنَ ٱلْأَمْنِ أَوِ ٱلْخَوْفِ أَذَاعُوا۟ بِهِۦ وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَٱتَّبَعْتُمُ ٱلشَّيْطَٰنَ إِلَّا قَلِيلًا', '863fb9d8edf7ab574eab7d231e5355f3bd056fe7ba5e9eae35bc25fa7d55044f', '863fb9d8edf7ab574eab7d231e5355f3bd056fe7ba5e9eae35bc25fa7d55044f', NULL, 'واذا جاءهم امر من الامن او الخوف اذاعوا به ولو ردوه الي الرسول والي اولي الامر منهم لعلمه الذين يستنبطونه منهم ولولا فضل الله عليكم ورحمته لاتبعتم الشيطن الا قليلا', 5, 9, 36, 1, 1, 91, false, NULL),
    (577, 'tanzil-uthmani-v1.1', 4, 84, 'فَقَٰتِلْ فِى سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ وَحَرِّضِ ٱلْمُؤْمِنِينَ عَسَى ٱللَّهُ أَن يَكُفَّ بَأْسَ ٱلَّذِينَ كَفَرُوا۟ وَٱللَّهُ أَشَدُّ بَأْسًا وَأَشَدُّ تَنكِيلًا', '7fad28e3da93dc5e567177176d121443641f907bbb984dd7d0a893e9c18c5870', 'فَقَٰتِلْ فِى سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ وَحَرِّضِ ٱلْمُؤْمِنِينَ عَسَى ٱللَّهُ أَن يَكُفَّ بَأْسَ ٱلَّذِينَ كَفَرُوا۟ وَٱللَّهُ أَشَدُّ بَأْسًا وَأَشَدُّ تَنكِيلًا', '7fad28e3da93dc5e567177176d121443641f907bbb984dd7d0a893e9c18c5870', '7fad28e3da93dc5e567177176d121443641f907bbb984dd7d0a893e9c18c5870', NULL, 'فقتل في سبيل الله لا تكلف الا نفسك وحرض المؤمنين عسي الله ان يكف باس الذين كفروا والله اشد باسا واشد تنكيلا', 5, 9, 36, 1, 1, 91, false, NULL),
    (578, 'tanzil-uthmani-v1.1', 4, 85, 'مَّن يَشْفَعْ شَفَٰعَةً حَسَنَةً يَكُن لَّهُۥ نَصِيبٌ مِّنْهَا وَمَن يَشْفَعْ شَفَٰعَةً سَيِّئَةً يَكُن لَّهُۥ كِفْلٌ مِّنْهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقِيتًا', '6179e5279fa46607d920b949e1c52d4864457392cf7d511d04df44c4d2695ba6', 'مَّن يَشْفَعْ شَفَٰعَةً حَسَنَةً يَكُن لَّهُۥ نَصِيبٌ مِّنْهَا وَمَن يَشْفَعْ شَفَٰعَةً سَيِّئَةً يَكُن لَّهُۥ كِفْلٌ مِّنْهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقِيتًا', '6179e5279fa46607d920b949e1c52d4864457392cf7d511d04df44c4d2695ba6', '6179e5279fa46607d920b949e1c52d4864457392cf7d511d04df44c4d2695ba6', NULL, 'من يشفع شفعه حسنه يكن له نصيب منها ومن يشفع شفعه سيئه يكن له كفل منها وكان الله علي كل شيء مقيتا', 5, 9, 36, 1, 1, 91, false, NULL),
    (579, 'tanzil-uthmani-v1.1', 4, 86, 'وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا', '19dcbf328dfa06a0fc7c8b4dcf9ed2e35f73bc771b179666a7173d56eef2c2c5', 'وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا', '19dcbf328dfa06a0fc7c8b4dcf9ed2e35f73bc771b179666a7173d56eef2c2c5', '19dcbf328dfa06a0fc7c8b4dcf9ed2e35f73bc771b179666a7173d56eef2c2c5', NULL, 'واذا حييتم بتحيه فحيوا باحسن منها او ردوها ان الله كان علي كل شيء حسيبا', 5, 9, 36, 1, 1, 91, false, NULL),
    (580, 'tanzil-uthmani-v1.1', 4, 87, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ حَدِيثًا', '32577fee55ddc78af77728ca171a9971dcf2b4b2759274bc54fac89aba34efff', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ حَدِيثًا', '32577fee55ddc78af77728ca171a9971dcf2b4b2759274bc54fac89aba34efff', '32577fee55ddc78af77728ca171a9971dcf2b4b2759274bc54fac89aba34efff', NULL, 'الله لا اله الا هو ليجمعنكم الي يوم القيمه لا ريب فيه ومن اصدق من الله حديثا', 5, 9, 36, 1, 1, 92, false, NULL),
    (581, 'tanzil-uthmani-v1.1', 4, 88, 'فَمَا لَكُمْ فِى ٱلْمُنَٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', '8ec17121fe46799860ae71c552a546335ca93a6bad7d7221bc6219e9b08dd8cb', 'فَمَا لَكُمْ فِى ٱلْمُنَٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', '8ec17121fe46799860ae71c552a546335ca93a6bad7d7221bc6219e9b08dd8cb', '8ec17121fe46799860ae71c552a546335ca93a6bad7d7221bc6219e9b08dd8cb', NULL, 'فما لكم في المنفقين فئتين والله اركسهم بما كسبوا اتريدون ان تهدوا من اضل الله ومن يضلل الله فلن تجد له سبيلا', 5, 10, 37, 1, 1, 92, false, NULL),
    (582, 'tanzil-uthmani-v1.1', 4, 89, 'وَدُّوا۟ لَوْ تَكْفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَآءً فَلَا تَتَّخِذُوا۟ مِنْهُمْ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُوا۟ فِى سَبِيلِ ٱللَّهِ فَإِن تَوَلَّوْا۟ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ وَلَا تَتَّخِذُوا۟ مِنْهُمْ وَلِيًّا وَلَا نَصِيرًا', '3346c848397c002067fdcc0537f13d4809132594e5d1516c39c73ca94e79bddf', 'وَدُّوا۟ لَوْ تَكْفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَآءً فَلَا تَتَّخِذُوا۟ مِنْهُمْ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُوا۟ فِى سَبِيلِ ٱللَّهِ فَإِن تَوَلَّوْا۟ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ وَلَا تَتَّخِذُوا۟ مِنْهُمْ وَلِيًّا وَلَا نَصِيرًا', '3346c848397c002067fdcc0537f13d4809132594e5d1516c39c73ca94e79bddf', '3346c848397c002067fdcc0537f13d4809132594e5d1516c39c73ca94e79bddf', NULL, 'ودوا لو تكفرون كما كفروا فتكونون سواء فلا تتخذوا منهم اولياء حتي يهاجروا في سبيل الله فان تولوا فخذوهم واقتلوهم حيث وجدتموهم ولا تتخذوا منهم وليا ولا نصيرا', 5, 10, 37, 1, 1, 92, false, NULL),
    (583, 'tanzil-uthmani-v1.1', 4, 90, 'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ أَوْ جَآءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَٰتِلُوكُمْ أَوْ يُقَٰتِلُوا۟ قَوْمَهُمْ وَلَوْ شَآءَ ٱللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَٰتَلُوكُمْ فَإِنِ ٱعْتَزَلُوكُمْ فَلَمْ يُقَٰتِلُوكُمْ وَأَلْقَوْا۟ إِلَيْكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًا', 'a3f9d3585c23bdb9d7be6168ea61b6015aea640977fd7ab483be15d3c2ccb974', 'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ أَوْ جَآءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَٰتِلُوكُمْ أَوْ يُقَٰتِلُوا۟ قَوْمَهُمْ وَلَوْ شَآءَ ٱللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَٰتَلُوكُمْ فَإِنِ ٱعْتَزَلُوكُمْ فَلَمْ يُقَٰتِلُوكُمْ وَأَلْقَوْا۟ إِلَيْكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًا', 'a3f9d3585c23bdb9d7be6168ea61b6015aea640977fd7ab483be15d3c2ccb974', 'a3f9d3585c23bdb9d7be6168ea61b6015aea640977fd7ab483be15d3c2ccb974', NULL, 'الا الذين يصلون الي قوم بينكم وبينهم ميثق او جاءوكم حصرت صدورهم ان يقتلوكم او يقتلوا قومهم ولو شاء الله لسلطهم عليكم فلقتلوكم فان اعتزلوكم فلم يقتلوكم والقوا اليكم السلم فما جعل الله لكم عليهم سبيلا', 5, 10, 37, 1, 1, 92, false, NULL),
    (584, 'tanzil-uthmani-v1.1', 4, 91, 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا۟ قَوْمَهُمْ كُلَّ مَا رُدُّوٓا۟ إِلَى ٱلْفِتْنَةِ أُرْكِسُوا۟ فِيهَا فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓا۟ إِلَيْكُمُ ٱلسَّلَمَ وَيَكُفُّوٓا۟ أَيْدِيَهُمْ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأُو۟لَٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَٰنًا مُّبِينًا', 'be883aa41993010a524c93961359dc03de89e87bb5276b67a361af93f1112fe1', 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا۟ قَوْمَهُمْ كُلَّ مَا رُدُّوٓا۟ إِلَى ٱلْفِتْنَةِ أُرْكِسُوا۟ فِيهَا فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓا۟ إِلَيْكُمُ ٱلسَّلَمَ وَيَكُفُّوٓا۟ أَيْدِيَهُمْ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأُو۟لَٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَٰنًا مُّبِينًا', 'be883aa41993010a524c93961359dc03de89e87bb5276b67a361af93f1112fe1', 'be883aa41993010a524c93961359dc03de89e87bb5276b67a361af93f1112fe1', NULL, 'ستجدون ءاخرين يريدون ان يامنوكم ويامنوا قومهم كل ما ردوا الي الفتنه اركسوا فيها فان لم يعتزلوكم ويلقوا اليكم السلم ويكفوا ايديهم فخذوهم واقتلوهم حيث ثقفتموهم واولئكم جعلنا لكم عليهم سلطنا مبينا', 5, 10, 37, 1, 1, 92, false, NULL),
    (585, 'tanzil-uthmani-v1.1', 4, 92, 'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَـًٔا وَمَن قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَن يَصَّدَّقُوا۟ فَإِن كَانَ مِن قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَإِن كَانَ مِن قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ فَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِّنَ ٱللَّهِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'a3bbf89e574ef53bf54d78e8d50298feb161222cb9bd5dadce8ee8c15ab42315', 'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَـًٔا وَمَن قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَن يَصَّدَّقُوا۟ فَإِن كَانَ مِن قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَإِن كَانَ مِن قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ فَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِّنَ ٱللَّهِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'a3bbf89e574ef53bf54d78e8d50298feb161222cb9bd5dadce8ee8c15ab42315', 'a3bbf89e574ef53bf54d78e8d50298feb161222cb9bd5dadce8ee8c15ab42315', NULL, 'وما كان لمؤمن ان يقتل مؤمنا الا خطا ومن قتل مؤمنا خطا فتحرير رقبه مؤمنه وديه مسلمه الي اهله الا ان يصدقوا فان كان من قوم عدو لكم وهو مؤمن فتحرير رقبه مؤمنه وان كان من قوم بينكم وبينهم ميثق فديه مسلمه الي اهله وتحرير رقبه مؤمنه فمن لم يجد فصيام شهرين متتابعين توبه من الله وكان الله عليما حكيما', 5, 10, 37, 1, 1, 93, false, NULL),
    (586, 'tanzil-uthmani-v1.1', 4, 93, 'وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدًا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمًا', 'f693685908a4a2da3a28254fcd547d026d143ab65ec88e7430cc2ad28ff61a99', 'وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدًا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمًا', 'f693685908a4a2da3a28254fcd547d026d143ab65ec88e7430cc2ad28ff61a99', 'f693685908a4a2da3a28254fcd547d026d143ab65ec88e7430cc2ad28ff61a99', NULL, 'ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خلدا فيها وغضب الله عليه ولعنه واعد له عذابا عظيما', 5, 10, 37, 1, 1, 93, false, NULL),
    (587, 'tanzil-uthmani-v1.1', 4, 94, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَٰمَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', '4dc5dd71e60afa78bc5bc2142ebda2a0b5a9ebcb888d3a23c93f9c40f9c11ff3', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَٰمَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', '4dc5dd71e60afa78bc5bc2142ebda2a0b5a9ebcb888d3a23c93f9c40f9c11ff3', '4dc5dd71e60afa78bc5bc2142ebda2a0b5a9ebcb888d3a23c93f9c40f9c11ff3', NULL, 'يايها الذين ءامنوا اذا ضربتم في سبيل الله فتبينوا ولا تقولوا لمن القي اليكم السلم لست مؤمنا تبتغون عرض الحيوه الدنيا فعند الله مغانم كثيره كذلك كنتم من قبل فمن الله عليكم فتبينوا ان الله كان بما تعملون خبيرا', 5, 10, 37, 1, 1, 93, false, NULL),
    (588, 'tanzil-uthmani-v1.1', 4, 95, 'لَّا يَسْتَوِى ٱلْقَٰعِدُونَ مِنَ ٱلْمُؤْمِنِينَ غَيْرُ أُو۟لِى ٱلضَّرَرِ وَٱلْمُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَٰعِدِينَ دَرَجَةً وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ وَفَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ عَلَى ٱلْقَٰعِدِينَ أَجْرًا عَظِيمًا', '7f19c3c091fd4671fc44e59ac129502de582f379354fec6dbbea655f786c3674', 'لَّا يَسْتَوِى ٱلْقَٰعِدُونَ مِنَ ٱلْمُؤْمِنِينَ غَيْرُ أُو۟لِى ٱلضَّرَرِ وَٱلْمُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَٰعِدِينَ دَرَجَةً وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ وَفَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ عَلَى ٱلْقَٰعِدِينَ أَجْرًا عَظِيمًا', '7f19c3c091fd4671fc44e59ac129502de582f379354fec6dbbea655f786c3674', '7f19c3c091fd4671fc44e59ac129502de582f379354fec6dbbea655f786c3674', NULL, 'لا يستوي القعدون من المؤمنين غير اولي الضرر والمجهدون في سبيل الله بامولهم وانفسهم فضل الله المجهدين بامولهم وانفسهم علي القعدين درجه وكلا وعد الله الحسني وفضل الله المجهدين علي القعدين اجرا عظيما', 5, 10, 37, 1, 1, 94, false, NULL),
    (589, 'tanzil-uthmani-v1.1', 4, 96, 'دَرَجَٰتٍ مِّنْهُ وَمَغْفِرَةً وَرَحْمَةً وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'bca7c0a7057cc5935a57203027974e9caf6a4f7556f3b9b63d5c6eeda32419a0', 'دَرَجَٰتٍ مِّنْهُ وَمَغْفِرَةً وَرَحْمَةً وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'bca7c0a7057cc5935a57203027974e9caf6a4f7556f3b9b63d5c6eeda32419a0', 'bca7c0a7057cc5935a57203027974e9caf6a4f7556f3b9b63d5c6eeda32419a0', NULL, 'درجت منه ومغفره ورحمه وكان الله غفورا رحيما', 5, 10, 37, 1, 1, 94, false, NULL),
    (590, 'tanzil-uthmani-v1.1', 4, 97, 'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ قَالُوا۟ فِيمَ كُنتُمْ قَالُوا۟ كُنَّا مُسْتَضْعَفِينَ فِى ٱلْأَرْضِ قَالُوٓا۟ أَلَمْ تَكُنْ أَرْضُ ٱللَّهِ وَٰسِعَةً فَتُهَاجِرُوا۟ فِيهَا فَأُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَسَآءَتْ مَصِيرًا', 'f1b9de003b95ff57cf9a4aef493a4ef57531eb99b442ac3b7df7c2c4a5f5319f', 'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ قَالُوا۟ فِيمَ كُنتُمْ قَالُوا۟ كُنَّا مُسْتَضْعَفِينَ فِى ٱلْأَرْضِ قَالُوٓا۟ أَلَمْ تَكُنْ أَرْضُ ٱللَّهِ وَٰسِعَةً فَتُهَاجِرُوا۟ فِيهَا فَأُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَسَآءَتْ مَصِيرًا', 'f1b9de003b95ff57cf9a4aef493a4ef57531eb99b442ac3b7df7c2c4a5f5319f', 'f1b9de003b95ff57cf9a4aef493a4ef57531eb99b442ac3b7df7c2c4a5f5319f', NULL, 'ان الذين توفيهم الملئكه ظالمي انفسهم قالوا فيم كنتم قالوا كنا مستضعفين في الارض قالوا الم تكن ارض الله وسعه فتهاجروا فيها فاولئك ماويهم جهنم وساءت مصيرا', 5, 10, 37, 1, 1, 94, false, NULL),
    (591, 'tanzil-uthmani-v1.1', 4, 98, 'إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا', 'b0fbbab6faa81fa9f252b0a31a34847dead8cae4e1a6d4547117730cafeb9ea9', 'إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا', 'b0fbbab6faa81fa9f252b0a31a34847dead8cae4e1a6d4547117730cafeb9ea9', 'b0fbbab6faa81fa9f252b0a31a34847dead8cae4e1a6d4547117730cafeb9ea9', NULL, 'الا المستضعفين من الرجال والنساء والولدن لا يستطيعون حيله ولا يهتدون سبيلا', 5, 10, 37, 1, 1, 94, false, NULL),
    (592, 'tanzil-uthmani-v1.1', 4, 99, 'فَأُو۟لَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًا', '739df20a585789458fd60621c5b53903d67f90c0ed0f1d4670e15e06cd48d3ec', 'فَأُو۟لَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًا', '739df20a585789458fd60621c5b53903d67f90c0ed0f1d4670e15e06cd48d3ec', '739df20a585789458fd60621c5b53903d67f90c0ed0f1d4670e15e06cd48d3ec', NULL, 'فاولئك عسي الله ان يعفو عنهم وكان الله عفوا غفورا', 5, 10, 37, 1, 1, 94, false, NULL),
    (593, 'tanzil-uthmani-v1.1', 4, 100, 'وَمَن يُهَاجِرْ فِى سَبِيلِ ٱللَّهِ يَجِدْ فِى ٱلْأَرْضِ مُرَٰغَمًا كَثِيرًا وَسَعَةً وَمَن يَخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ٱلْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ٱللَّهِ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '339c95b2509c81c0491c488f50537cbf873a216a1fc22d70290c8eefe842a781', 'وَمَن يُهَاجِرْ فِى سَبِيلِ ٱللَّهِ يَجِدْ فِى ٱلْأَرْضِ مُرَٰغَمًا كَثِيرًا وَسَعَةً وَمَن يَخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ٱلْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ٱللَّهِ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '339c95b2509c81c0491c488f50537cbf873a216a1fc22d70290c8eefe842a781', '339c95b2509c81c0491c488f50537cbf873a216a1fc22d70290c8eefe842a781', NULL, 'ومن يهاجر في سبيل الله يجد في الارض مرغما كثيرا وسعه ومن يخرج من بيته مهاجرا الي الله ورسوله ثم يدركه الموت فقد وقع اجره علي الله وكان الله غفورا رحيما', 5, 10, 38, 1, 1, 94, false, NULL),
    (594, 'tanzil-uthmani-v1.1', 4, 101, 'وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ ٱلَّذِينَ كَفَرُوٓا۟ إِنَّ ٱلْكَٰفِرِينَ كَانُوا۟ لَكُمْ عَدُوًّا مُّبِينًا', 'd5e76d0cbe7e2ee61d0782b0c4e56044bc7628922b86403dd5e9abb95b43b485', 'وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ ٱلَّذِينَ كَفَرُوٓا۟ إِنَّ ٱلْكَٰفِرِينَ كَانُوا۟ لَكُمْ عَدُوًّا مُّبِينًا', 'd5e76d0cbe7e2ee61d0782b0c4e56044bc7628922b86403dd5e9abb95b43b485', 'd5e76d0cbe7e2ee61d0782b0c4e56044bc7628922b86403dd5e9abb95b43b485', NULL, 'واذا ضربتم في الارض فليس عليكم جناح ان تقصروا من الصلوه ان خفتم ان يفتنكم الذين كفروا ان الكفرين كانوا لكم عدوا مبينا', 5, 10, 38, 1, 1, 94, false, NULL),
    (595, 'tanzil-uthmani-v1.1', 4, 102, 'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا۟ فَلْيَكُونُوا۟ مِن وَرَآئِكُمْ وَلْتَأْتِ طَآئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا۟ فَلْيُصَلُّوا۟ مَعَكَ وَلْيَأْخُذُوا۟ حِذْرَهُمْ وَأَسْلِحَتَهُمْ وَدَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةً وَٰحِدَةً وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰٓ أَن تَضَعُوٓا۟ أَسْلِحَتَكُمْ وَخُذُوا۟ حِذْرَكُمْ إِنَّ ٱللَّهَ أَعَدَّ لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'b07d938a4a01ec340972caab581673f7fd70400057afa212f47eeab37636750d', 'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا۟ فَلْيَكُونُوا۟ مِن وَرَآئِكُمْ وَلْتَأْتِ طَآئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا۟ فَلْيُصَلُّوا۟ مَعَكَ وَلْيَأْخُذُوا۟ حِذْرَهُمْ وَأَسْلِحَتَهُمْ وَدَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةً وَٰحِدَةً وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰٓ أَن تَضَعُوٓا۟ أَسْلِحَتَكُمْ وَخُذُوا۟ حِذْرَكُمْ إِنَّ ٱللَّهَ أَعَدَّ لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'b07d938a4a01ec340972caab581673f7fd70400057afa212f47eeab37636750d', 'b07d938a4a01ec340972caab581673f7fd70400057afa212f47eeab37636750d', NULL, 'واذا كنت فيهم فاقمت لهم الصلوه فلتقم طائفه منهم معك ولياخذوا اسلحتهم فاذا سجدوا فليكونوا من ورائكم ولتات طائفه اخري لم يصلوا فليصلوا معك ولياخذوا حذرهم واسلحتهم ود الذين كفروا لو تغفلون عن اسلحتكم وامتعتكم فيميلون عليكم ميله وحده ولا جناح عليكم ان كان بكم اذي من مطر او كنتم مرضي ان تضعوا اسلحتكم وخذوا حذركم ان الله اعد للكفرين عذابا مهينا', 5, 10, 38, 1, 1, 95, false, NULL),
    (596, 'tanzil-uthmani-v1.1', 4, 103, 'فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًا مَّوْقُوتًا', 'a8f04657f90a1016b7b22da65d46a3c06745e82a1d5057b0102efd9469b167f3', 'فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًا مَّوْقُوتًا', 'a8f04657f90a1016b7b22da65d46a3c06745e82a1d5057b0102efd9469b167f3', 'a8f04657f90a1016b7b22da65d46a3c06745e82a1d5057b0102efd9469b167f3', NULL, 'فاذا قضيتم الصلوه فاذكروا الله قيما وقعودا وعلي جنوبكم فاذا اطماننتم فاقيموا الصلوه ان الصلوه كانت علي المؤمنين كتبا موقوتا', 5, 10, 38, 1, 1, 95, false, NULL),
    (597, 'tanzil-uthmani-v1.1', 4, 104, 'وَلَا تَهِنُوا۟ فِى ٱبْتِغَآءِ ٱلْقَوْمِ إِن تَكُونُوا۟ تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ وَتَرْجُونَ مِنَ ٱللَّهِ مَا لَا يَرْجُونَ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'cb226e8611feb566c4056651b026b8c32d616447189d3693d617a48b0c0734b1', 'وَلَا تَهِنُوا۟ فِى ٱبْتِغَآءِ ٱلْقَوْمِ إِن تَكُونُوا۟ تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ وَتَرْجُونَ مِنَ ٱللَّهِ مَا لَا يَرْجُونَ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'cb226e8611feb566c4056651b026b8c32d616447189d3693d617a48b0c0734b1', 'cb226e8611feb566c4056651b026b8c32d616447189d3693d617a48b0c0734b1', NULL, 'ولا تهنوا في ابتغاء القوم ان تكونوا تالمون فانهم يالمون كما تالمون وترجون من الله ما لا يرجون وكان الله عليما حكيما', 5, 10, 38, 1, 1, 95, false, NULL),
    (598, 'tanzil-uthmani-v1.1', 4, 105, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ لِتَحْكُمَ بَيْنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيمًا', '5cf71726954f7d255a249fabd2769ba344c8807df3339e9cc20f8631f0ad722b', 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ لِتَحْكُمَ بَيْنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيمًا', '5cf71726954f7d255a249fabd2769ba344c8807df3339e9cc20f8631f0ad722b', '5cf71726954f7d255a249fabd2769ba344c8807df3339e9cc20f8631f0ad722b', NULL, 'انا انزلنا اليك الكتب بالحق لتحكم بين الناس بما اريك الله ولا تكن للخائنين خصيما', 5, 10, 38, 1, 1, 95, false, NULL),
    (599, 'tanzil-uthmani-v1.1', 4, 106, 'وَٱسْتَغْفِرِ ٱللَّهَ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', '7ff90c4bba4b68333d72238511d48bd1d5535bb8eb6562ad9d81a9a18637a5ef', 'وَٱسْتَغْفِرِ ٱللَّهَ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', '7ff90c4bba4b68333d72238511d48bd1d5535bb8eb6562ad9d81a9a18637a5ef', '7ff90c4bba4b68333d72238511d48bd1d5535bb8eb6562ad9d81a9a18637a5ef', NULL, 'واستغفر الله ان الله كان غفورا رحيما', 5, 10, 38, 1, 1, 96, false, NULL),
    (600, 'tanzil-uthmani-v1.1', 4, 107, 'وَلَا تُجَٰدِلْ عَنِ ٱلَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًا', '07c3a71a1a13b81f997adc827731c7d2f7cf0b71a975f3dffe0b047a0cf58ff0', 'وَلَا تُجَٰدِلْ عَنِ ٱلَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًا', '07c3a71a1a13b81f997adc827731c7d2f7cf0b71a975f3dffe0b047a0cf58ff0', '07c3a71a1a13b81f997adc827731c7d2f7cf0b71a975f3dffe0b047a0cf58ff0', NULL, 'ولا تجدل عن الذين يختانون انفسهم ان الله لا يحب من كان خوانا اثيما', 5, 10, 38, 1, 1, 96, false, NULL),
    (601, 'tanzil-uthmani-v1.1', 4, 108, 'يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا', '010725638d51e03d3277d1c9b71ae429fb3cac644bedbde75e2b53a5d50de110', 'يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا', '010725638d51e03d3277d1c9b71ae429fb3cac644bedbde75e2b53a5d50de110', '010725638d51e03d3277d1c9b71ae429fb3cac644bedbde75e2b53a5d50de110', NULL, 'يستخفون من الناس ولا يستخفون من الله وهو معهم اذ يبيتون ما لا يرضي من القول وكان الله بما يعملون محيطا', 5, 10, 38, 1, 1, 96, false, NULL),
    (602, 'tanzil-uthmani-v1.1', 4, 109, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ جَٰدَلْتُمْ عَنْهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنْهُمْ يَوْمَ ٱلْقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًا', '414cb64e40ed205ce6e02f98e0cd56a3a9654764b7526fc83937c9179b90a6db', 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ جَٰدَلْتُمْ عَنْهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنْهُمْ يَوْمَ ٱلْقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًا', '414cb64e40ed205ce6e02f98e0cd56a3a9654764b7526fc83937c9179b90a6db', '414cb64e40ed205ce6e02f98e0cd56a3a9654764b7526fc83937c9179b90a6db', NULL, 'هانتم هؤلاء جدلتم عنهم في الحيوه الدنيا فمن يجدل الله عنهم يوم القيمه ام من يكون عليهم وكيلا', 5, 10, 38, 1, 1, 96, false, NULL),
    (603, 'tanzil-uthmani-v1.1', 4, 110, 'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًا رَّحِيمًا', 'f8f7420a06c23b8c977cefede08548b53f97ceb05210565f97007f7e0b78b985', 'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًا رَّحِيمًا', 'f8f7420a06c23b8c977cefede08548b53f97ceb05210565f97007f7e0b78b985', 'f8f7420a06c23b8c977cefede08548b53f97ceb05210565f97007f7e0b78b985', NULL, 'ومن يعمل سوءا او يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما', 5, 10, 38, 1, 1, 96, false, NULL),
    (604, 'tanzil-uthmani-v1.1', 4, 111, 'وَمَن يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'baaa17db857fe31edbdc1e6b287f978655fb6b1c957792fde17297e650c83659', 'وَمَن يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 'baaa17db857fe31edbdc1e6b287f978655fb6b1c957792fde17297e650c83659', 'baaa17db857fe31edbdc1e6b287f978655fb6b1c957792fde17297e650c83659', NULL, 'ومن يكسب اثما فانما يكسبه علي نفسه وكان الله عليما حكيما', 5, 10, 38, 1, 1, 96, false, NULL),
    (605, 'tanzil-uthmani-v1.1', 4, 112, 'وَمَن يَكْسِبْ خَطِيٓـَٔةً أَوْ إِثْمًا ثُمَّ يَرْمِ بِهِۦ بَرِيٓـًٔا فَقَدِ ٱحْتَمَلَ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'f16318bf4cf0393876b4da0798d3538594560ca201c51215bdf4002aaee16d20', 'وَمَن يَكْسِبْ خَطِيٓـَٔةً أَوْ إِثْمًا ثُمَّ يَرْمِ بِهِۦ بَرِيٓـًٔا فَقَدِ ٱحْتَمَلَ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'f16318bf4cf0393876b4da0798d3538594560ca201c51215bdf4002aaee16d20', 'f16318bf4cf0393876b4da0798d3538594560ca201c51215bdf4002aaee16d20', NULL, 'ومن يكسب خطيه او اثما ثم يرم به بريا فقد احتمل بهتنا واثما مبينا', 5, 10, 38, 1, 1, 96, false, NULL),
    (606, 'tanzil-uthmani-v1.1', 4, 113, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةٌ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَضُرُّونَكَ مِن شَىْءٍ وَأَنزَلَ ٱللَّهُ عَلَيْكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ وَكَانَ فَضْلُ ٱللَّهِ عَلَيْكَ عَظِيمًا', '0941e450d96f6aa98f8ebad6bac2d423fe99b0e08d8c1e017eea3bec74bebb1e', 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةٌ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَضُرُّونَكَ مِن شَىْءٍ وَأَنزَلَ ٱللَّهُ عَلَيْكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ وَكَانَ فَضْلُ ٱللَّهِ عَلَيْكَ عَظِيمًا', '0941e450d96f6aa98f8ebad6bac2d423fe99b0e08d8c1e017eea3bec74bebb1e', '0941e450d96f6aa98f8ebad6bac2d423fe99b0e08d8c1e017eea3bec74bebb1e', NULL, 'ولولا فضل الله عليك ورحمته لهمت طائفه منهم ان يضلوك وما يضلون الا انفسهم وما يضرونك من شيء وانزل الله عليك الكتب والحكمه وعلمك ما لم تكن تعلم وكان فضل الله عليك عظيما', 5, 10, 38, 1, 1, 96, false, NULL),
    (607, 'tanzil-uthmani-v1.1', 4, 114, 'لَّا خَيْرَ فِى كَثِيرٍ مِّن نَّجْوَىٰهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَٰحٍۭ بَيْنَ ٱلنَّاسِ وَمَن يَفْعَلْ ذَٰلِكَ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', 'c514ab577e7d01d9762e2fc443f185d7cfd894380a219614ce98725e75e29770', 'لَّا خَيْرَ فِى كَثِيرٍ مِّن نَّجْوَىٰهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَٰحٍۭ بَيْنَ ٱلنَّاسِ وَمَن يَفْعَلْ ذَٰلِكَ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا', 'c514ab577e7d01d9762e2fc443f185d7cfd894380a219614ce98725e75e29770', 'c514ab577e7d01d9762e2fc443f185d7cfd894380a219614ce98725e75e29770', NULL, 'لا خير في كثير من نجويهم الا من امر بصدقه او معروف او اصلح بين الناس ومن يفعل ذلك ابتغاء مرضات الله فسوف نؤتيه اجرا عظيما', 5, 10, 39, 1, 1, 97, false, NULL),
    (608, 'tanzil-uthmani-v1.1', 4, 115, 'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ وَسَآءَتْ مَصِيرًا', 'd8166d358b2701511acc339e496f053030debb74a8f97c5f60bce36470b4fe67', 'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ وَسَآءَتْ مَصِيرًا', 'd8166d358b2701511acc339e496f053030debb74a8f97c5f60bce36470b4fe67', 'd8166d358b2701511acc339e496f053030debb74a8f97c5f60bce36470b4fe67', NULL, 'ومن يشاقق الرسول من بعد ما تبين له الهدي ويتبع غير سبيل المؤمنين نوله ما تولي ونصله جهنم وساءت مصيرا', 5, 10, 39, 1, 1, 97, false, NULL),
    (609, 'tanzil-uthmani-v1.1', 4, 116, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', '72aff3b733b9e8ee4c45cba9f67a522e63a1ccaadd000952120c49f94bfc9add', 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', '72aff3b733b9e8ee4c45cba9f67a522e63a1ccaadd000952120c49f94bfc9add', '72aff3b733b9e8ee4c45cba9f67a522e63a1ccaadd000952120c49f94bfc9add', NULL, 'ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد ضل ضللا بعيدا', 5, 10, 39, 1, 1, 97, false, NULL),
    (610, 'tanzil-uthmani-v1.1', 4, 117, 'إِن يَدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثًا وَإِن يَدْعُونَ إِلَّا شَيْطَٰنًا مَّرِيدًا', '263543ad0b2a40c3c16f4ebfd1ff20bd99048fc70e7d536bdeed3bc7b81809fc', 'إِن يَدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثًا وَإِن يَدْعُونَ إِلَّا شَيْطَٰنًا مَّرِيدًا', '263543ad0b2a40c3c16f4ebfd1ff20bd99048fc70e7d536bdeed3bc7b81809fc', '263543ad0b2a40c3c16f4ebfd1ff20bd99048fc70e7d536bdeed3bc7b81809fc', NULL, 'ان يدعون من دونه الا انثا وان يدعون الا شيطنا مريدا', 5, 10, 39, 1, 1, 97, false, NULL),
    (611, 'tanzil-uthmani-v1.1', 4, 118, 'لَّعَنَهُ ٱللَّهُ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَّفْرُوضًا', '24b4c48b676341786e38b595d08e78ac256f445b908eb1931cf003bedc3e13a5', 'لَّعَنَهُ ٱللَّهُ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَّفْرُوضًا', '24b4c48b676341786e38b595d08e78ac256f445b908eb1931cf003bedc3e13a5', '24b4c48b676341786e38b595d08e78ac256f445b908eb1931cf003bedc3e13a5', NULL, 'لعنه الله وقال لاتخذن من عبادك نصيبا مفروضا', 5, 10, 39, 1, 1, 97, false, NULL),
    (612, 'tanzil-uthmani-v1.1', 4, 119, 'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَـَٔامُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلْأَنْعَٰمِ وَلَـَٔامُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ٱللَّهِ وَمَن يَتَّخِذِ ٱلشَّيْطَٰنَ وَلِيًّا مِّن دُونِ ٱللَّهِ فَقَدْ خَسِرَ خُسْرَانًا مُّبِينًا', '6b3341b1c547190b4c49e8f180f91a3fb92e7382e760fd3c8129df461b3f0171', 'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَـَٔامُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلْأَنْعَٰمِ وَلَـَٔامُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ٱللَّهِ وَمَن يَتَّخِذِ ٱلشَّيْطَٰنَ وَلِيًّا مِّن دُونِ ٱللَّهِ فَقَدْ خَسِرَ خُسْرَانًا مُّبِينًا', '6b3341b1c547190b4c49e8f180f91a3fb92e7382e760fd3c8129df461b3f0171', '6b3341b1c547190b4c49e8f180f91a3fb92e7382e760fd3c8129df461b3f0171', NULL, 'ولاضلنهم ولامنينهم ولامرنهم فليبتكن ءاذان الانعم ولامرنهم فليغيرن خلق الله ومن يتخذ الشيطن وليا من دون الله فقد خسر خسرانا مبينا', 5, 10, 39, 1, 1, 97, false, NULL),
    (613, 'tanzil-uthmani-v1.1', 4, 120, 'يَعِدُهُمْ وَيُمَنِّيهِمْ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', '5939065b9f909c0f585a8095dcf02e385c7db18b66b7bc7f81fc92ee06f72ccc', 'يَعِدُهُمْ وَيُمَنِّيهِمْ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', '5939065b9f909c0f585a8095dcf02e385c7db18b66b7bc7f81fc92ee06f72ccc', '5939065b9f909c0f585a8095dcf02e385c7db18b66b7bc7f81fc92ee06f72ccc', NULL, 'يعدهم ويمنيهم وما يعدهم الشيطن الا غرورا', 5, 10, 39, 1, 1, 97, false, NULL),
    (614, 'tanzil-uthmani-v1.1', 4, 121, 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًا', '9bc44fb27b793f1516d18f1a5976e5444639feb702fe759bcb47dfef1879ad7d', 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًا', '9bc44fb27b793f1516d18f1a5976e5444639feb702fe759bcb47dfef1879ad7d', '9bc44fb27b793f1516d18f1a5976e5444639feb702fe759bcb47dfef1879ad7d', NULL, 'اولئك ماويهم جهنم ولا يجدون عنها محيصا', 5, 10, 39, 1, 1, 97, false, NULL),
    (615, 'tanzil-uthmani-v1.1', 4, 122, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا وَعْدَ ٱللَّهِ حَقًّا وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ قِيلًا', '7657c09ae55e36da498bc796009c65da5228a27f481c8fc50b0b3e2479856475', 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا وَعْدَ ٱللَّهِ حَقًّا وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ قِيلًا', '7657c09ae55e36da498bc796009c65da5228a27f481c8fc50b0b3e2479856475', '7657c09ae55e36da498bc796009c65da5228a27f481c8fc50b0b3e2479856475', NULL, 'والذين ءامنوا وعملوا الصلحت سندخلهم جنت تجري من تحتها الانهر خلدين فيها ابدا وعد الله حقا ومن اصدق من الله قيلا', 5, 10, 39, 1, 1, 98, false, NULL),
    (616, 'tanzil-uthmani-v1.1', 4, 123, 'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَٰبِ مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'c3d10b5e3069f141902899ef1f41f068483bee1b6b833f53c78d88f3baf88b0a', 'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَٰبِ مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'c3d10b5e3069f141902899ef1f41f068483bee1b6b833f53c78d88f3baf88b0a', 'c3d10b5e3069f141902899ef1f41f068483bee1b6b833f53c78d88f3baf88b0a', NULL, 'ليس بامانيكم ولا اماني اهل الكتب من يعمل سوءا يجز به ولا يجد له من دون الله وليا ولا نصيرا', 5, 10, 39, 1, 1, 98, false, NULL),
    (617, 'tanzil-uthmani-v1.1', 4, 124, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًا', 'e07aa0a0eb8ba172f1d01da5ef70116c3f0bcc76e36a6a5eb757014251928854', 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًا', 'e07aa0a0eb8ba172f1d01da5ef70116c3f0bcc76e36a6a5eb757014251928854', 'e07aa0a0eb8ba172f1d01da5ef70116c3f0bcc76e36a6a5eb757014251928854', NULL, 'ومن يعمل من الصلحت من ذكر او انثي وهو مؤمن فاولئك يدخلون الجنه ولا يظلمون نقيرا', 5, 10, 39, 1, 1, 98, false, NULL),
    (618, 'tanzil-uthmani-v1.1', 4, 125, 'وَمَنْ أَحْسَنُ دِينًا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًا', '4bcb7287175ca71a64815f494fbd1e1075dbb83fc076a4e7c240396925ef2934', 'وَمَنْ أَحْسَنُ دِينًا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًا', '4bcb7287175ca71a64815f494fbd1e1075dbb83fc076a4e7c240396925ef2934', '4bcb7287175ca71a64815f494fbd1e1075dbb83fc076a4e7c240396925ef2934', NULL, 'ومن احسن دينا ممن اسلم وجهه لله وهو محسن واتبع مله ابرهيم حنيفا واتخذ الله ابرهيم خليلا', 5, 10, 39, 1, 1, 98, false, NULL),
    (619, 'tanzil-uthmani-v1.1', 4, 126, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ مُّحِيطًا', 'c24b4980f8d807ca79bacc4d3e511a2a42047db395a312bc4a734f00fae301c8', 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ مُّحِيطًا', 'c24b4980f8d807ca79bacc4d3e511a2a42047db395a312bc4a734f00fae301c8', 'c24b4980f8d807ca79bacc4d3e511a2a42047db395a312bc4a734f00fae301c8', NULL, 'ولله ما في السموت وما في الارض وكان الله بكل شيء محيطا', 5, 10, 39, 1, 1, 98, false, NULL),
    (620, 'tanzil-uthmani-v1.1', 4, 127, 'وَيَسْتَفْتُونَكَ فِى ٱلنِّسَآءِ قُلِ ٱللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى ٱلْكِتَٰبِ فِى يَتَٰمَى ٱلنِّسَآءِ ٱلَّٰتِى لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلْوِلْدَٰنِ وَأَن تَقُومُوا۟ لِلْيَتَٰمَىٰ بِٱلْقِسْطِ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمًا', 'afef9d84611fea41c443fc6565c584e74530688a3e8a1ca3cc03c70ffffccae0', 'وَيَسْتَفْتُونَكَ فِى ٱلنِّسَآءِ قُلِ ٱللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى ٱلْكِتَٰبِ فِى يَتَٰمَى ٱلنِّسَآءِ ٱلَّٰتِى لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلْوِلْدَٰنِ وَأَن تَقُومُوا۟ لِلْيَتَٰمَىٰ بِٱلْقِسْطِ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمًا', 'afef9d84611fea41c443fc6565c584e74530688a3e8a1ca3cc03c70ffffccae0', 'afef9d84611fea41c443fc6565c584e74530688a3e8a1ca3cc03c70ffffccae0', NULL, 'ويستفتونك في النساء قل الله يفتيكم فيهن وما يتلي عليكم في الكتب في يتمي النساء التي لا تؤتونهن ما كتب لهن وترغبون ان تنكحوهن والمستضعفين من الولدن وان تقوموا لليتمي بالقسط وما تفعلوا من خير فان الله كان به عليما', 5, 10, 39, 1, 1, 98, false, NULL),
    (621, 'tanzil-uthmani-v1.1', 4, 128, 'وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا وَٱلصُّلْحُ خَيْرٌ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', '3e6c568ba6cebba6e84c76ac03c8d8f65c609791d002607567d5af4c33aa8251', 'وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا وَٱلصُّلْحُ خَيْرٌ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', '3e6c568ba6cebba6e84c76ac03c8d8f65c609791d002607567d5af4c33aa8251', '3e6c568ba6cebba6e84c76ac03c8d8f65c609791d002607567d5af4c33aa8251', NULL, 'وان امراه خافت من بعلها نشوزا او اعراضا فلا جناح عليهما ان يصلحا بينهما صلحا والصلح خير واحضرت الانفس الشح وان تحسنوا وتتقوا فان الله كان بما تعملون خبيرا', 5, 10, 39, 1, 1, 99, false, NULL),
    (622, 'tanzil-uthmani-v1.1', 4, 129, 'وَلَن تَسْتَطِيعُوٓا۟ أَن تَعْدِلُوا۟ بَيْنَ ٱلنِّسَآءِ وَلَوْ حَرَصْتُمْ فَلَا تَمِيلُوا۟ كُلَّ ٱلْمَيْلِ فَتَذَرُوهَا كَٱلْمُعَلَّقَةِ وَإِن تُصْلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', '14d0efa83723e170c145a094c682825370ecf454e6a1318e31cc82774e8f58c6', 'وَلَن تَسْتَطِيعُوٓا۟ أَن تَعْدِلُوا۟ بَيْنَ ٱلنِّسَآءِ وَلَوْ حَرَصْتُمْ فَلَا تَمِيلُوا۟ كُلَّ ٱلْمَيْلِ فَتَذَرُوهَا كَٱلْمُعَلَّقَةِ وَإِن تُصْلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', '14d0efa83723e170c145a094c682825370ecf454e6a1318e31cc82774e8f58c6', '14d0efa83723e170c145a094c682825370ecf454e6a1318e31cc82774e8f58c6', NULL, 'ولن تستطيعوا ان تعدلوا بين النساء ولو حرصتم فلا تميلوا كل الميل فتذروها كالمعلقه وان تصلحوا وتتقوا فان الله كان غفورا رحيما', 5, 10, 39, 1, 1, 99, false, NULL),
    (623, 'tanzil-uthmani-v1.1', 4, 130, 'وَإِن يَتَفَرَّقَا يُغْنِ ٱللَّهُ كُلًّا مِّن سَعَتِهِۦ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمًا', '8b7e396c37c085c53061b7d27242c96f3c6533fc5d150a73392f84b45f6bd6a5', 'وَإِن يَتَفَرَّقَا يُغْنِ ٱللَّهُ كُلًّا مِّن سَعَتِهِۦ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمًا', '8b7e396c37c085c53061b7d27242c96f3c6533fc5d150a73392f84b45f6bd6a5', '8b7e396c37c085c53061b7d27242c96f3c6533fc5d150a73392f84b45f6bd6a5', NULL, 'وان يتفرقا يغن الله كلا من سعته وكان الله وسعا حكيما', 5, 10, 39, 1, 1, 99, false, NULL),
    (624, 'tanzil-uthmani-v1.1', 4, 131, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَقَدْ وَصَّيْنَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ ٱتَّقُوا۟ ٱللَّهَ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدًا', '5c77f3511e3e02c141ef4685e136cc5e6f9a2013424066d11730b453fe8854fb', 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَقَدْ وَصَّيْنَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ ٱتَّقُوا۟ ٱللَّهَ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدًا', '5c77f3511e3e02c141ef4685e136cc5e6f9a2013424066d11730b453fe8854fb', '5c77f3511e3e02c141ef4685e136cc5e6f9a2013424066d11730b453fe8854fb', NULL, 'ولله ما في السموت وما في الارض ولقد وصينا الذين اوتوا الكتب من قبلكم واياكم ان اتقوا الله وان تكفروا فان لله ما في السموت وما في الارض وكان الله غنيا حميدا', 5, 10, 39, 1, 1, 99, false, NULL),
    (625, 'tanzil-uthmani-v1.1', 4, 132, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'd8d80cccf2a2deb2eb2e32c782f4221931b176d3c9f45b5ade9ffa6d289a8a21', 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'd8d80cccf2a2deb2eb2e32c782f4221931b176d3c9f45b5ade9ffa6d289a8a21', 'd8d80cccf2a2deb2eb2e32c782f4221931b176d3c9f45b5ade9ffa6d289a8a21', NULL, 'ولله ما في السموت وما في الارض وكفي بالله وكيلا', 5, 10, 39, 1, 1, 99, false, NULL),
    (626, 'tanzil-uthmani-v1.1', 4, 133, 'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا ٱلنَّاسُ وَيَأْتِ بِـَٔاخَرِينَ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًا', 'bd04a803a3a7e1dba6d71500d05918410bcba90686f90c21b564c693cfd28a1e', 'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا ٱلنَّاسُ وَيَأْتِ بِـَٔاخَرِينَ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًا', 'bd04a803a3a7e1dba6d71500d05918410bcba90686f90c21b564c693cfd28a1e', 'bd04a803a3a7e1dba6d71500d05918410bcba90686f90c21b564c693cfd28a1e', NULL, 'ان يشا يذهبكم ايها الناس ويات باخرين وكان الله علي ذلك قديرا', 5, 10, 39, 1, 1, 99, false, NULL),
    (627, 'tanzil-uthmani-v1.1', 4, 134, 'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنْيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَكَانَ ٱللَّهُ سَمِيعًۢا بَصِيرًا', '0f940717577dcce7b5d6f21b60f95e634949384e20ebc0f2e76a2413a20ebc83', 'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنْيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَكَانَ ٱللَّهُ سَمِيعًۢا بَصِيرًا', '0f940717577dcce7b5d6f21b60f95e634949384e20ebc0f2e76a2413a20ebc83', '0f940717577dcce7b5d6f21b60f95e634949384e20ebc0f2e76a2413a20ebc83', NULL, 'من كان يريد ثواب الدنيا فعند الله ثواب الدنيا والاخره وكان الله سميعا بصيرا', 5, 10, 39, 1, 1, 99, false, NULL),
    (628, 'tanzil-uthmani-v1.1', 4, 135, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَٱللَّهُ أَوْلَىٰ بِهِمَا فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'e4640ace28fb7c0528bd0fe786c201adf19b65c8fbf561cf9c4583dbab862f7b', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَٱللَّهُ أَوْلَىٰ بِهِمَا فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'e4640ace28fb7c0528bd0fe786c201adf19b65c8fbf561cf9c4583dbab862f7b', 'e4640ace28fb7c0528bd0fe786c201adf19b65c8fbf561cf9c4583dbab862f7b', NULL, 'يايها الذين ءامنوا كونوا قومين بالقسط شهداء لله ولو علي انفسكم او الولدين والاقربين ان يكن غنيا او فقيرا فالله اولي بهما فلا تتبعوا الهوي ان تعدلوا وان تلوا او تعرضوا فان الله كان بما تعملون خبيرا', 5, 10, 40, 1, 1, 100, false, NULL),
    (629, 'tanzil-uthmani-v1.1', 4, 136, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', '960fea40f3c58cac8665056e20b54ade5dd2036fd33380bd7e0cd13b44f633d8', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', '960fea40f3c58cac8665056e20b54ade5dd2036fd33380bd7e0cd13b44f633d8', '960fea40f3c58cac8665056e20b54ade5dd2036fd33380bd7e0cd13b44f633d8', NULL, 'يايها الذين ءامنوا ءامنوا بالله ورسوله والكتب الذي نزل علي رسوله والكتب الذي انزل من قبل ومن يكفر بالله وملئكته وكتبه ورسله واليوم الاخر فقد ضل ضللا بعيدا', 5, 10, 40, 1, 1, 100, false, NULL),
    (630, 'tanzil-uthmani-v1.1', 4, 137, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًۢا', 'ee7e764ffcefcdeb57d5aaa25790f062002f3c7192fa32e209aefbc106e5f55f', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًۢا', 'ee7e764ffcefcdeb57d5aaa25790f062002f3c7192fa32e209aefbc106e5f55f', 'ee7e764ffcefcdeb57d5aaa25790f062002f3c7192fa32e209aefbc106e5f55f', NULL, 'ان الذين ءامنوا ثم كفروا ثم ءامنوا ثم كفروا ثم ازدادوا كفرا لم يكن الله ليغفر لهم ولا ليهديهم سبيلا', 5, 10, 40, 1, 1, 100, false, NULL),
    (631, 'tanzil-uthmani-v1.1', 4, 138, 'بَشِّرِ ٱلْمُنَٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا', 'a539508e90f49ebe563a284b6a5d929934d92324167827f1ae8bcace2add162f', 'بَشِّرِ ٱلْمُنَٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا', 'a539508e90f49ebe563a284b6a5d929934d92324167827f1ae8bcace2add162f', 'a539508e90f49ebe563a284b6a5d929934d92324167827f1ae8bcace2add162f', NULL, 'بشر المنفقين بان لهم عذابا اليما', 5, 10, 40, 1, 1, 100, false, NULL),
    (632, 'tanzil-uthmani-v1.1', 4, 139, 'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا', 'a6e2115e3bacefda75aef9989f106f9d3ac84f8caf0a3d22cd36b58188dede7d', 'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا', 'a6e2115e3bacefda75aef9989f106f9d3ac84f8caf0a3d22cd36b58188dede7d', 'a6e2115e3bacefda75aef9989f106f9d3ac84f8caf0a3d22cd36b58188dede7d', NULL, 'الذين يتخذون الكفرين اولياء من دون المؤمنين ايبتغون عندهم العزه فان العزه لله جميعا', 5, 10, 40, 1, 1, 100, false, NULL),
    (633, 'tanzil-uthmani-v1.1', 4, 140, 'وَقَدْ نَزَّلَ عَلَيْكُمْ فِى ٱلْكِتَٰبِ أَنْ إِذَا سَمِعْتُمْ ءَايَٰتِ ٱللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا۟ مَعَهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦٓ إِنَّكُمْ إِذًا مِّثْلُهُمْ إِنَّ ٱللَّهَ جَامِعُ ٱلْمُنَٰفِقِينَ وَٱلْكَٰفِرِينَ فِى جَهَنَّمَ جَمِيعًا', 'bcf21e78a269b8e053f8e7f520670e45bda71032677b0db0b0abeec418c5d09b', 'وَقَدْ نَزَّلَ عَلَيْكُمْ فِى ٱلْكِتَٰبِ أَنْ إِذَا سَمِعْتُمْ ءَايَٰتِ ٱللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا۟ مَعَهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦٓ إِنَّكُمْ إِذًا مِّثْلُهُمْ إِنَّ ٱللَّهَ جَامِعُ ٱلْمُنَٰفِقِينَ وَٱلْكَٰفِرِينَ فِى جَهَنَّمَ جَمِيعًا', 'bcf21e78a269b8e053f8e7f520670e45bda71032677b0db0b0abeec418c5d09b', 'bcf21e78a269b8e053f8e7f520670e45bda71032677b0db0b0abeec418c5d09b', NULL, 'وقد نزل عليكم في الكتب ان اذا سمعتم ءايت الله يكفر بها ويستهزا بها فلا تقعدوا معهم حتي يخوضوا في حديث غيره انكم اذا مثلهم ان الله جامع المنفقين والكفرين في جهنم جميعا', 5, 10, 40, 1, 1, 100, false, NULL),
    (634, 'tanzil-uthmani-v1.1', 4, 141, 'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌ مِّنَ ٱللَّهِ قَالُوٓا۟ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَٰفِرِينَ نَصِيبٌ قَالُوٓا۟ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ٱلْمُؤْمِنِينَ فَٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَن يَجْعَلَ ٱللَّهُ لِلْكَٰفِرِينَ عَلَى ٱلْمُؤْمِنِينَ سَبِيلًا', 'd19644ae4794f5f0e3a3f71c0e52347e2384c85ead644615f925347cfa897587', 'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌ مِّنَ ٱللَّهِ قَالُوٓا۟ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَٰفِرِينَ نَصِيبٌ قَالُوٓا۟ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ٱلْمُؤْمِنِينَ فَٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَن يَجْعَلَ ٱللَّهُ لِلْكَٰفِرِينَ عَلَى ٱلْمُؤْمِنِينَ سَبِيلًا', 'd19644ae4794f5f0e3a3f71c0e52347e2384c85ead644615f925347cfa897587', 'd19644ae4794f5f0e3a3f71c0e52347e2384c85ead644615f925347cfa897587', NULL, 'الذين يتربصون بكم فان كان لكم فتح من الله قالوا الم نكن معكم وان كان للكفرين نصيب قالوا الم نستحوذ عليكم ونمنعكم من المؤمنين فالله يحكم بينكم يوم القيمه ولن يجعل الله للكفرين علي المؤمنين سبيلا', 5, 10, 40, 1, 1, 101, false, NULL),
    (635, 'tanzil-uthmani-v1.1', 4, 142, 'إِنَّ ٱلْمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمْ وَإِذَا قَامُوٓا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذْكُرُونَ ٱللَّهَ إِلَّا قَلِيلًا', 'ec3f5a2f4615e2100a73029eb1bd49d45ccea55a087581054e1c0fbf6388bd8b', 'إِنَّ ٱلْمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمْ وَإِذَا قَامُوٓا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذْكُرُونَ ٱللَّهَ إِلَّا قَلِيلًا', 'ec3f5a2f4615e2100a73029eb1bd49d45ccea55a087581054e1c0fbf6388bd8b', 'ec3f5a2f4615e2100a73029eb1bd49d45ccea55a087581054e1c0fbf6388bd8b', NULL, 'ان المنفقين يخدعون الله وهو خدعهم واذا قاموا الي الصلوه قاموا كسالي يراءون الناس ولا يذكرون الله الا قليلا', 5, 10, 40, 1, 1, 101, false, NULL),
    (636, 'tanzil-uthmani-v1.1', 4, 143, 'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', 'acfcf77da8a42721f6c8afd8a42623940167d2dcc3173dabee5e180ce7e29bd0', 'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا', 'acfcf77da8a42721f6c8afd8a42623940167d2dcc3173dabee5e180ce7e29bd0', 'acfcf77da8a42721f6c8afd8a42623940167d2dcc3173dabee5e180ce7e29bd0', NULL, 'مذبذبين بين ذلك لا الي هؤلاء ولا الي هؤلاء ومن يضلل الله فلن تجد له سبيلا', 5, 10, 40, 1, 1, 101, false, NULL),
    (637, 'tanzil-uthmani-v1.1', 4, 144, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَٰنًا مُّبِينًا', '270180adcc2bf8fad88a3adacc7ceb3c71308652bcbb00e58551d764d3d7fad7', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَٰنًا مُّبِينًا', '270180adcc2bf8fad88a3adacc7ceb3c71308652bcbb00e58551d764d3d7fad7', '270180adcc2bf8fad88a3adacc7ceb3c71308652bcbb00e58551d764d3d7fad7', NULL, 'يايها الذين ءامنوا لا تتخذوا الكفرين اولياء من دون المؤمنين اتريدون ان تجعلوا لله عليكم سلطنا مبينا', 5, 10, 40, 1, 1, 101, false, NULL),
    (638, 'tanzil-uthmani-v1.1', 4, 145, 'إِنَّ ٱلْمُنَٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا', '7954794c9f38dae77d2deac587a73b598df2da990d4be49240c9a11fff776cba', 'إِنَّ ٱلْمُنَٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا', '7954794c9f38dae77d2deac587a73b598df2da990d4be49240c9a11fff776cba', '7954794c9f38dae77d2deac587a73b598df2da990d4be49240c9a11fff776cba', NULL, 'ان المنفقين في الدرك الاسفل من النار ولن تجد لهم نصيرا', 5, 10, 40, 1, 1, 101, false, NULL),
    (639, 'tanzil-uthmani-v1.1', 4, 146, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًا', '0caf654190a7d434137952e9bcf77eb5ffe780211ca5ed1affc84115ddfa4e1b', 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًا', '0caf654190a7d434137952e9bcf77eb5ffe780211ca5ed1affc84115ddfa4e1b', '0caf654190a7d434137952e9bcf77eb5ffe780211ca5ed1affc84115ddfa4e1b', NULL, 'الا الذين تابوا واصلحوا واعتصموا بالله واخلصوا دينهم لله فاولئك مع المؤمنين وسوف يؤت الله المؤمنين اجرا عظيما', 5, 10, 40, 1, 1, 101, false, NULL),
    (640, 'tanzil-uthmani-v1.1', 4, 147, 'مَّا يَفْعَلُ ٱللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَءَامَنتُمْ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمًا', '8ab6883e4c6970856f48cc79584ba905332787bdd88ef9e6f5d41e8a1454789e', 'مَّا يَفْعَلُ ٱللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَءَامَنتُمْ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمًا', '8ab6883e4c6970856f48cc79584ba905332787bdd88ef9e6f5d41e8a1454789e', '8ab6883e4c6970856f48cc79584ba905332787bdd88ef9e6f5d41e8a1454789e', NULL, 'ما يفعل الله بعذابكم ان شكرتم وءامنتم وكان الله شاكرا عليما', 5, 10, 40, 1, 1, 101, false, NULL),
    (641, 'tanzil-uthmani-v1.1', 4, 148, 'لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا', '41af04ee9113cfb5d5d3d2e754ac9d3c5f0c2e0d93557d7d5d309eeb2e0cbc99', 'لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا', '41af04ee9113cfb5d5d3d2e754ac9d3c5f0c2e0d93557d7d5d309eeb2e0cbc99', '41af04ee9113cfb5d5d3d2e754ac9d3c5f0c2e0d93557d7d5d309eeb2e0cbc99', NULL, 'لا يحب الله الجهر بالسوء من القول الا من ظلم وكان الله سميعا عليما', 6, 11, 41, 1, 1, 102, false, NULL),
    (642, 'tanzil-uthmani-v1.1', 4, 149, 'إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّا قَدِيرًا', '6ba3c46151bd457e629afb95c4dec5b3fb68a757db91c8417675e3fa7258cf36', 'إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّا قَدِيرًا', '6ba3c46151bd457e629afb95c4dec5b3fb68a757db91c8417675e3fa7258cf36', '6ba3c46151bd457e629afb95c4dec5b3fb68a757db91c8417675e3fa7258cf36', NULL, 'ان تبدوا خيرا او تخفوه او تعفوا عن سوء فان الله كان عفوا قديرا', 6, 11, 41, 1, 1, 102, false, NULL),
    (643, 'tanzil-uthmani-v1.1', 4, 150, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُوا۟ بَيْنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍ وَيُرِيدُونَ أَن يَتَّخِذُوا۟ بَيْنَ ذَٰلِكَ سَبِيلًا', '25574c4fe522d7c4546de65e545e43a02d0b664c812660b729c6848b2a492e00', 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُوا۟ بَيْنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍ وَيُرِيدُونَ أَن يَتَّخِذُوا۟ بَيْنَ ذَٰلِكَ سَبِيلًا', '25574c4fe522d7c4546de65e545e43a02d0b664c812660b729c6848b2a492e00', '25574c4fe522d7c4546de65e545e43a02d0b664c812660b729c6848b2a492e00', NULL, 'ان الذين يكفرون بالله ورسله ويريدون ان يفرقوا بين الله ورسله ويقولون نؤمن ببعض ونكفر ببعض ويريدون ان يتخذوا بين ذلك سبيلا', 6, 11, 41, 1, 1, 102, false, NULL),
    (644, 'tanzil-uthmani-v1.1', 4, 151, 'أُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ حَقًّا وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'b1b26feb9cf7cea36178f1b906556febbcd86d3f68778033a11dc4367837c133', 'أُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ حَقًّا وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًا مُّهِينًا', 'b1b26feb9cf7cea36178f1b906556febbcd86d3f68778033a11dc4367837c133', 'b1b26feb9cf7cea36178f1b906556febbcd86d3f68778033a11dc4367837c133', NULL, 'اولئك هم الكفرون حقا واعتدنا للكفرين عذابا مهينا', 6, 11, 41, 1, 1, 102, false, NULL),
    (645, 'tanzil-uthmani-v1.1', 4, 152, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُوا۟ بَيْنَ أَحَدٍ مِّنْهُمْ أُو۟لَٰٓئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '074a219f2d4e2ff8d6ed68b5cac0440cdc9dcaf026fa3a20ca8f56df7bd69ee5', 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُوا۟ بَيْنَ أَحَدٍ مِّنْهُمْ أُو۟لَٰٓئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '074a219f2d4e2ff8d6ed68b5cac0440cdc9dcaf026fa3a20ca8f56df7bd69ee5', '074a219f2d4e2ff8d6ed68b5cac0440cdc9dcaf026fa3a20ca8f56df7bd69ee5', NULL, 'والذين ءامنوا بالله ورسله ولم يفرقوا بين احد منهم اولئك سوف يؤتيهم اجورهم وكان الله غفورا رحيما', 6, 11, 41, 1, 1, 102, false, NULL),
    (646, 'tanzil-uthmani-v1.1', 4, 153, 'يَسْـَٔلُكَ أَهْلُ ٱلْكِتَٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَٰبًا مِّنَ ٱلسَّمَآءِ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةً فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ بِظُلْمِهِمْ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ فَعَفَوْنَا عَن ذَٰلِكَ وَءَاتَيْنَا مُوسَىٰ سُلْطَٰنًا مُّبِينًا', 'aac7f7c0b31ee58ede197497e12d4690a9201a33ff47f86bcd7320738947ace3', 'يَسْـَٔلُكَ أَهْلُ ٱلْكِتَٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَٰبًا مِّنَ ٱلسَّمَآءِ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةً فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ بِظُلْمِهِمْ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ فَعَفَوْنَا عَن ذَٰلِكَ وَءَاتَيْنَا مُوسَىٰ سُلْطَٰنًا مُّبِينًا', 'aac7f7c0b31ee58ede197497e12d4690a9201a33ff47f86bcd7320738947ace3', 'aac7f7c0b31ee58ede197497e12d4690a9201a33ff47f86bcd7320738947ace3', NULL, 'يسلك اهل الكتب ان تنزل عليهم كتبا من السماء فقد سالوا موسي اكبر من ذلك فقالوا ارنا الله جهره فاخذتهم الصعقه بظلمهم ثم اتخذوا العجل من بعد ما جاءتهم البينت فعفونا عن ذلك وءاتينا موسي سلطنا مبينا', 6, 11, 41, 1, 1, 102, false, NULL),
    (647, 'tanzil-uthmani-v1.1', 4, 154, 'وَرَفَعْنَا فَوْقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمْ وَقُلْنَا لَهُمُ ٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُلْنَا لَهُمْ لَا تَعْدُوا۟ فِى ٱلسَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًا', '624e7f979924893901b60abe1ebef1a3fdfdcfdb1aa2577f213d249ea67773a1', 'وَرَفَعْنَا فَوْقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمْ وَقُلْنَا لَهُمُ ٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُلْنَا لَهُمْ لَا تَعْدُوا۟ فِى ٱلسَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًا', '624e7f979924893901b60abe1ebef1a3fdfdcfdb1aa2577f213d249ea67773a1', '624e7f979924893901b60abe1ebef1a3fdfdcfdb1aa2577f213d249ea67773a1', NULL, 'ورفعنا فوقهم الطور بميثقهم وقلنا لهم ادخلوا الباب سجدا وقلنا لهم لا تعدوا في السبت واخذنا منهم ميثقا غليظا', 6, 11, 41, 1, 1, 102, false, NULL),
    (648, 'tanzil-uthmani-v1.1', 4, 155, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ وَكُفْرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتْلِهِمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۢ بَلْ طَبَعَ ٱللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', '6ba738ecbf1cd2791f037d08a808a6fe47079bc9fdd671d7394d1229585ba886', 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ وَكُفْرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتْلِهِمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۢ بَلْ طَبَعَ ٱللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا', '6ba738ecbf1cd2791f037d08a808a6fe47079bc9fdd671d7394d1229585ba886', '6ba738ecbf1cd2791f037d08a808a6fe47079bc9fdd671d7394d1229585ba886', NULL, 'فبما نقضهم ميثقهم وكفرهم بايت الله وقتلهم الانبياء بغير حق وقولهم قلوبنا غلف بل طبع الله عليها بكفرهم فلا يؤمنون الا قليلا', 6, 11, 41, 1, 1, 103, false, NULL),
    (649, 'tanzil-uthmani-v1.1', 4, 156, 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَٰنًا عَظِيمًا', 'cc3363b7cb2a70f36d0e81381bdfd48e911e6613e0d22f672a97be6a1345d9d3', 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَٰنًا عَظِيمًا', 'cc3363b7cb2a70f36d0e81381bdfd48e911e6613e0d22f672a97be6a1345d9d3', 'cc3363b7cb2a70f36d0e81381bdfd48e911e6613e0d22f672a97be6a1345d9d3', NULL, 'وبكفرهم وقولهم علي مريم بهتنا عظيما', 6, 11, 41, 1, 1, 103, false, NULL),
    (650, 'tanzil-uthmani-v1.1', 4, 157, 'وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّ مِّنْهُ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ وَمَا قَتَلُوهُ يَقِينًۢا', '8f62957f85565f18ce1c43c945042b60b1268b4a770f10fddf162abbf3bf4cc9', 'وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّ مِّنْهُ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ وَمَا قَتَلُوهُ يَقِينًۢا', '8f62957f85565f18ce1c43c945042b60b1268b4a770f10fddf162abbf3bf4cc9', '8f62957f85565f18ce1c43c945042b60b1268b4a770f10fddf162abbf3bf4cc9', NULL, 'وقولهم انا قتلنا المسيح عيسي ابن مريم رسول الله وما قتلوه وما صلبوه ولكن شبه لهم وان الذين اختلفوا فيه لفي شك منه ما لهم به من علم الا اتباع الظن وما قتلوه يقينا', 6, 11, 41, 1, 1, 103, false, NULL),
    (651, 'tanzil-uthmani-v1.1', 4, 158, 'بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'feb2c8bd3860e7002b9a844c2281965f57fbb3bdcf93e5bd7fc47d295efa2cd0', 'بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'feb2c8bd3860e7002b9a844c2281965f57fbb3bdcf93e5bd7fc47d295efa2cd0', 'feb2c8bd3860e7002b9a844c2281965f57fbb3bdcf93e5bd7fc47d295efa2cd0', NULL, 'بل رفعه الله اليه وكان الله عزيزا حكيما', 6, 11, 41, 1, 1, 103, false, NULL),
    (652, 'tanzil-uthmani-v1.1', 4, 159, 'وَإِن مِّنْ أَهْلِ ٱلْكِتَٰبِ إِلَّا لَيُؤْمِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ وَيَوْمَ ٱلْقِيَٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا', 'ba65aba58b784b08742a8801a8327eb4b419e4fbdef6e07d89d96f1efeb051d7', 'وَإِن مِّنْ أَهْلِ ٱلْكِتَٰبِ إِلَّا لَيُؤْمِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ وَيَوْمَ ٱلْقِيَٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا', 'ba65aba58b784b08742a8801a8327eb4b419e4fbdef6e07d89d96f1efeb051d7', 'ba65aba58b784b08742a8801a8327eb4b419e4fbdef6e07d89d96f1efeb051d7', NULL, 'وان من اهل الكتب الا ليؤمنن به قبل موته ويوم القيمه يكون عليهم شهيدا', 6, 11, 41, 1, 1, 103, false, NULL),
    (653, 'tanzil-uthmani-v1.1', 4, 160, 'فَبِظُلْمٍ مِّنَ ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا عَلَيْهِمْ طَيِّبَٰتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ٱللَّهِ كَثِيرًا', '209b7abe3bf2ea757f24776c4242ec1728627c4e4dbc9be65b84f8ab61edc521', 'فَبِظُلْمٍ مِّنَ ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا عَلَيْهِمْ طَيِّبَٰتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ٱللَّهِ كَثِيرًا', '209b7abe3bf2ea757f24776c4242ec1728627c4e4dbc9be65b84f8ab61edc521', '209b7abe3bf2ea757f24776c4242ec1728627c4e4dbc9be65b84f8ab61edc521', NULL, 'فبظلم من الذين هادوا حرمنا عليهم طيبت احلت لهم وبصدهم عن سبيل الله كثيرا', 6, 11, 41, 1, 1, 103, false, NULL),
    (654, 'tanzil-uthmani-v1.1', 4, 161, 'وَأَخْذِهِمُ ٱلرِّبَوٰا۟ وَقَدْ نُهُوا۟ عَنْهُ وَأَكْلِهِمْ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَأَعْتَدْنَا لِلْكَٰفِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا', 'b40c84c8424e1a1086fcf2ff0542991c4a90dd25b7c2da909f5b042bcfc464ef', 'وَأَخْذِهِمُ ٱلرِّبَوٰا۟ وَقَدْ نُهُوا۟ عَنْهُ وَأَكْلِهِمْ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَأَعْتَدْنَا لِلْكَٰفِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا', 'b40c84c8424e1a1086fcf2ff0542991c4a90dd25b7c2da909f5b042bcfc464ef', 'b40c84c8424e1a1086fcf2ff0542991c4a90dd25b7c2da909f5b042bcfc464ef', NULL, 'واخذهم الربوا وقد نهوا عنه واكلهم امول الناس بالبطل واعتدنا للكفرين منهم عذابا اليما', 6, 11, 41, 1, 1, 103, false, NULL),
    (655, 'tanzil-uthmani-v1.1', 4, 162, 'لَّٰكِنِ ٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ مِنْهُمْ وَٱلْمُؤْمِنُونَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَٱلْمُقِيمِينَ ٱلصَّلَوٰةَ وَٱلْمُؤْتُونَ ٱلزَّكَوٰةَ وَٱلْمُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أُو۟لَٰٓئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا', '0a3a1643c7e8322add5cb78ac5d1c0907dc743d6c20a0574f9c1f8fffd3d4dd6', 'لَّٰكِنِ ٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ مِنْهُمْ وَٱلْمُؤْمِنُونَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَٱلْمُقِيمِينَ ٱلصَّلَوٰةَ وَٱلْمُؤْتُونَ ٱلزَّكَوٰةَ وَٱلْمُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أُو۟لَٰٓئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا', '0a3a1643c7e8322add5cb78ac5d1c0907dc743d6c20a0574f9c1f8fffd3d4dd6', '0a3a1643c7e8322add5cb78ac5d1c0907dc743d6c20a0574f9c1f8fffd3d4dd6', NULL, 'لكن الرسخون في العلم منهم والمؤمنون يؤمنون بما انزل اليك وما انزل من قبلك والمقيمين الصلوه والمؤتون الزكوه والمؤمنون بالله واليوم الاخر اولئك سنؤتيهم اجرا عظيما', 6, 11, 41, 1, 1, 103, false, NULL),
    (656, 'tanzil-uthmani-v1.1', 4, 163, 'إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍ وَٱلنَّبِيِّـۧنَ مِنۢ بَعْدِهِۦ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيْمَٰنَ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', '7b630b4d19286c92697931fbf8d33c204635951401035a636575dd17098e9bca', 'إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍ وَٱلنَّبِيِّـۧنَ مِنۢ بَعْدِهِۦ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيْمَٰنَ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', '7b630b4d19286c92697931fbf8d33c204635951401035a636575dd17098e9bca', '7b630b4d19286c92697931fbf8d33c204635951401035a636575dd17098e9bca', NULL, 'انا اوحينا اليك كما اوحينا الي نوح والنبين من بعده واوحينا الي ابرهيم واسمعيل واسحق ويعقوب والاسباط وعيسي وايوب ويونس وهرون وسليمن وءاتينا داود زبورا', 6, 11, 42, 1, 1, 104, false, NULL),
    (657, 'tanzil-uthmani-v1.1', 4, 164, 'وَرُسُلًا قَدْ قَصَصْنَٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًا لَّمْ نَقْصُصْهُمْ عَلَيْكَ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًا', '7d533244f51a89e27a7a55351f0fd20c2e95295e72edd891c41d6ab8e0290644', 'وَرُسُلًا قَدْ قَصَصْنَٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًا لَّمْ نَقْصُصْهُمْ عَلَيْكَ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًا', '7d533244f51a89e27a7a55351f0fd20c2e95295e72edd891c41d6ab8e0290644', '7d533244f51a89e27a7a55351f0fd20c2e95295e72edd891c41d6ab8e0290644', NULL, 'ورسلا قد قصصنهم عليك من قبل ورسلا لم نقصصهم عليك وكلم الله موسي تكليما', 6, 11, 42, 1, 1, 104, false, NULL),
    (658, 'tanzil-uthmani-v1.1', 4, 165, 'رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'a2c48ed65a99ae045ec42ef8f4d96ed47c2ccb73a1cde1c4be3cb22a227eb868', 'رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'a2c48ed65a99ae045ec42ef8f4d96ed47c2ccb73a1cde1c4be3cb22a227eb868', 'a2c48ed65a99ae045ec42ef8f4d96ed47c2ccb73a1cde1c4be3cb22a227eb868', NULL, 'رسلا مبشرين ومنذرين لئلا يكون للناس علي الله حجه بعد الرسل وكان الله عزيزا حكيما', 6, 11, 42, 1, 1, 104, false, NULL),
    (659, 'tanzil-uthmani-v1.1', 4, 166, 'لَّٰكِنِ ٱللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ أَنزَلَهُۥ بِعِلْمِهِۦ وَٱلْمَلَٰٓئِكَةُ يَشْهَدُونَ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', '7a4be809cd0b712cb4ed7dc44177ff6ab7b3d717782f091ffdb02678ae57e440', 'لَّٰكِنِ ٱللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ أَنزَلَهُۥ بِعِلْمِهِۦ وَٱلْمَلَٰٓئِكَةُ يَشْهَدُونَ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', '7a4be809cd0b712cb4ed7dc44177ff6ab7b3d717782f091ffdb02678ae57e440', '7a4be809cd0b712cb4ed7dc44177ff6ab7b3d717782f091ffdb02678ae57e440', NULL, 'لكن الله يشهد بما انزل اليك انزله بعلمه والملئكه يشهدون وكفي بالله شهيدا', 6, 11, 42, 1, 1, 104, false, NULL),
    (660, 'tanzil-uthmani-v1.1', 4, 167, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ قَدْ ضَلُّوا۟ ضَلَٰلًۢا بَعِيدًا', '6f817b827183c883a6584296e2f6a433ca90593a4749299069ac165ff94d420a', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ قَدْ ضَلُّوا۟ ضَلَٰلًۢا بَعِيدًا', '6f817b827183c883a6584296e2f6a433ca90593a4749299069ac165ff94d420a', '6f817b827183c883a6584296e2f6a433ca90593a4749299069ac165ff94d420a', NULL, 'ان الذين كفروا وصدوا عن سبيل الله قد ضلوا ضللا بعيدا', 6, 11, 42, 1, 1, 104, false, NULL),
    (661, 'tanzil-uthmani-v1.1', 4, 168, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا', '855ca25919b014e67071b99c77b24a4d7034974a08b0dea73de3d74c1828e703', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا', '855ca25919b014e67071b99c77b24a4d7034974a08b0dea73de3d74c1828e703', '855ca25919b014e67071b99c77b24a4d7034974a08b0dea73de3d74c1828e703', NULL, 'ان الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقا', 6, 11, 42, 1, 1, 104, false, NULL),
    (662, 'tanzil-uthmani-v1.1', 4, 169, 'إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', '0911f99aa16b8731deee640465cd45fbd9fbdab8cd5a643b5eaf47550fed1929', 'إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', '0911f99aa16b8731deee640465cd45fbd9fbdab8cd5a643b5eaf47550fed1929', '0911f99aa16b8731deee640465cd45fbd9fbdab8cd5a643b5eaf47550fed1929', NULL, 'الا طريق جهنم خلدين فيها ابدا وكان ذلك علي الله يسيرا', 6, 11, 42, 1, 1, 104, false, NULL),
    (663, 'tanzil-uthmani-v1.1', 4, 170, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلرَّسُولُ بِٱلْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُوا۟ خَيْرًا لَّكُمْ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '234c68c8215e38e84fc9390af581324a7b8fc0720d4d505c4b1f643fe235cd03', 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلرَّسُولُ بِٱلْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُوا۟ خَيْرًا لَّكُمْ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '234c68c8215e38e84fc9390af581324a7b8fc0720d4d505c4b1f643fe235cd03', '234c68c8215e38e84fc9390af581324a7b8fc0720d4d505c4b1f643fe235cd03', NULL, 'يايها الناس قد جاءكم الرسول بالحق من ربكم فامنوا خيرا لكم وان تكفروا فان لله ما في السموت والارض وكان الله عليما حكيما', 6, 11, 42, 1, 1, 104, false, NULL),
    (664, 'tanzil-uthmani-v1.1', 4, 171, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَا تَقُولُوا۟ ثَلَٰثَةٌ ٱنتَهُوا۟ خَيْرًا لَّكُمْ إِنَّمَا ٱللَّهُ إِلَٰهٌ وَٰحِدٌ سُبْحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'bb50c5c19665e53514d4c20f244fbfab06630bcc5765be47576b0bcf4772ed83', 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَا تَقُولُوا۟ ثَلَٰثَةٌ ٱنتَهُوا۟ خَيْرًا لَّكُمْ إِنَّمَا ٱللَّهُ إِلَٰهٌ وَٰحِدٌ سُبْحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 'bb50c5c19665e53514d4c20f244fbfab06630bcc5765be47576b0bcf4772ed83', 'bb50c5c19665e53514d4c20f244fbfab06630bcc5765be47576b0bcf4772ed83', NULL, 'ياهل الكتب لا تغلوا في دينكم ولا تقولوا علي الله الا الحق انما المسيح عيسي ابن مريم رسول الله وكلمته القيها الي مريم وروح منه فامنوا بالله ورسله ولا تقولوا ثلثه انتهوا خيرا لكم انما الله اله وحد سبحنه ان يكون له ولد له ما في السموت وما في الارض وكفي بالله وكيلا', 6, 11, 42, 1, 1, 105, false, NULL),
    (665, 'tanzil-uthmani-v1.1', 4, 172, 'لَّن يَسْتَنكِفَ ٱلْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّهِ وَلَا ٱلْمَلَٰٓئِكَةُ ٱلْمُقَرَّبُونَ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا', '467ef8bf4d70ba70f25666b7c81b95503f8410a5263a397e6a6e1f30911279f1', 'لَّن يَسْتَنكِفَ ٱلْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّهِ وَلَا ٱلْمَلَٰٓئِكَةُ ٱلْمُقَرَّبُونَ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا', '467ef8bf4d70ba70f25666b7c81b95503f8410a5263a397e6a6e1f30911279f1', '467ef8bf4d70ba70f25666b7c81b95503f8410a5263a397e6a6e1f30911279f1', NULL, 'لن يستنكف المسيح ان يكون عبدا لله ولا الملئكه المقربون ومن يستنكف عن عبادته ويستكبر فسيحشرهم اليه جميعا', 6, 11, 42, 1, 1, 105, false, NULL),
    (666, 'tanzil-uthmani-v1.1', 4, 173, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ وَأَمَّا ٱلَّذِينَ ٱسْتَنكَفُوا۟ وَٱسْتَكْبَرُوا۟ فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', '7a5b4958196ac9832d3211c5eff976f463ef00613aa48424499ebcaca1c178c7', 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ وَأَمَّا ٱلَّذِينَ ٱسْتَنكَفُوا۟ وَٱسْتَكْبَرُوا۟ فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', '7a5b4958196ac9832d3211c5eff976f463ef00613aa48424499ebcaca1c178c7', '7a5b4958196ac9832d3211c5eff976f463ef00613aa48424499ebcaca1c178c7', NULL, 'فاما الذين ءامنوا وعملوا الصلحت فيوفيهم اجورهم ويزيدهم من فضله واما الذين استنكفوا واستكبروا فيعذبهم عذابا اليما ولا يجدون لهم من دون الله وليا ولا نصيرا', 6, 11, 42, 1, 1, 105, false, NULL),
    (667, 'tanzil-uthmani-v1.1', 4, 174, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَٰنٌ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًا مُّبِينًا', 'e261843c603e2e3e993ec97cf6a42c07f08ec80f2197165f3adca03f10edb67a', 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَٰنٌ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًا مُّبِينًا', 'e261843c603e2e3e993ec97cf6a42c07f08ec80f2197165f3adca03f10edb67a', 'e261843c603e2e3e993ec97cf6a42c07f08ec80f2197165f3adca03f10edb67a', NULL, 'يايها الناس قد جاءكم برهن من ربكم وانزلنا اليكم نورا مبينا', 6, 11, 42, 1, 1, 105, false, NULL),
    (668, 'tanzil-uthmani-v1.1', 4, 175, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَٱعْتَصَمُوا۟ بِهِۦ فَسَيُدْخِلُهُمْ فِى رَحْمَةٍ مِّنْهُ وَفَضْلٍ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًا مُّسْتَقِيمًا', '2139b8c7345280f31b521128328f3831b0201a792b74574fb03f06541ba5334d', 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَٱعْتَصَمُوا۟ بِهِۦ فَسَيُدْخِلُهُمْ فِى رَحْمَةٍ مِّنْهُ وَفَضْلٍ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًا مُّسْتَقِيمًا', '2139b8c7345280f31b521128328f3831b0201a792b74574fb03f06541ba5334d', '2139b8c7345280f31b521128328f3831b0201a792b74574fb03f06541ba5334d', NULL, 'فاما الذين ءامنوا بالله واعتصموا به فسيدخلهم في رحمه منه وفضل ويهديهم اليه صرطا مستقيما', 6, 11, 42, 1, 1, 105, false, NULL),
    (669, 'tanzil-uthmani-v1.1', 4, 176, 'يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَٰلَةِ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌ وَلَهُۥٓ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ وَإِن كَانُوٓا۟ إِخْوَةً رِّجَالًا وَنِسَآءً فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '2a2ff00022cdd5995853745c38bb36618e4e07f68f042b63ed6487f613ad7986', 'يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَٰلَةِ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌ وَلَهُۥٓ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ وَإِن كَانُوٓا۟ إِخْوَةً رِّجَالًا وَنِسَآءً فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '2a2ff00022cdd5995853745c38bb36618e4e07f68f042b63ed6487f613ad7986', '2a2ff00022cdd5995853745c38bb36618e4e07f68f042b63ed6487f613ad7986', NULL, 'يستفتونك قل الله يفتيكم في الكلله ان امرؤا هلك ليس له ولد وله اخت فلها نصف ما ترك وهو يرثها ان لم يكن لها ولد فان كانتا اثنتين فلهما الثلثان مما ترك وان كانوا اخوه رجالا ونساء فللذكر مثل حظ الانثيين يبين الله لكم ان تضلوا والله بكل شيء عليم', 6, 11, 42, 1, 1, 106, false, NULL),
    (670, 'tanzil-uthmani-v1.1', 5, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَٰمِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى ٱلصَّيْدِ وَأَنتُمْ حُرُمٌ إِنَّ ٱللَّهَ يَحْكُمُ مَا يُرِيدُ', '39cce38ea00036a05a390ca4068fa1281416aa9362730e26aacaa9e1eacf4823', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَٰمِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى ٱلصَّيْدِ وَأَنتُمْ حُرُمٌ إِنَّ ٱللَّهَ يَحْكُمُ مَا يُرِيدُ', 'c26aa716e7251c975f5b4c816e7171258a49d2d72ef80511a8ee7b51826c137a', 'c26aa716e7251c975f5b4c816e7171258a49d2d72ef80511a8ee7b51826c137a', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يايها الذين ءامنوا اوفوا بالعقود احلت لكم بهيمه الانعم الا ما يتلي عليكم غير محلي الصيد وانتم حرم ان الله يحكم ما يريد', 6, 11, 43, 1, 2, 106, false, NULL),
    (671, 'tanzil-uthmani-v1.1', 5, 2, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًا مِّن رَّبِّهِمْ وَرِضْوَٰنًا وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '656c6530cfc8c8db344c30847787c32949673a06b60bdb49bea8c708fd792ab2', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًا مِّن رَّبِّهِمْ وَرِضْوَٰنًا وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '656c6530cfc8c8db344c30847787c32949673a06b60bdb49bea8c708fd792ab2', '656c6530cfc8c8db344c30847787c32949673a06b60bdb49bea8c708fd792ab2', NULL, 'يايها الذين ءامنوا لا تحلوا شعئر الله ولا الشهر الحرام ولا الهدي ولا القلئد ولا ءامين البيت الحرام يبتغون فضلا من ربهم ورضونا واذا حللتم فاصطادوا ولا يجرمنكم شنان قوم ان صدوكم عن المسجد الحرام ان تعتدوا وتعاونوا علي البر والتقوي ولا تعاونوا علي الاثم والعدون واتقوا الله ان الله شديد العقاب', 6, 11, 43, 1, 2, 106, false, NULL),
    (672, 'tanzil-uthmani-v1.1', 5, 3, 'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَٰمِ ذَٰلِكُمْ فِسْقٌ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَٰمَ دِينًا فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِّإِثْمٍ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '75bfd7ef5e6d4ac97ddfc4fc378b589698bd7e5dc307ff43bfd0d7c25ffbd55a', 'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَٰمِ ذَٰلِكُمْ فِسْقٌ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَٰمَ دِينًا فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِّإِثْمٍ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '75bfd7ef5e6d4ac97ddfc4fc378b589698bd7e5dc307ff43bfd0d7c25ffbd55a', '75bfd7ef5e6d4ac97ddfc4fc378b589698bd7e5dc307ff43bfd0d7c25ffbd55a', NULL, 'حرمت عليكم الميته والدم ولحم الخنزير وما اهل لغير الله به والمنخنقه والموقوذه والمترديه والنطيحه وما اكل السبع الا ما ذكيتم وما ذبح علي النصب وان تستقسموا بالازلم ذلكم فسق اليوم يئس الذين كفروا من دينكم فلا تخشوهم واخشون اليوم اكملت لكم دينكم واتممت عليكم نعمتي ورضيت لكم الاسلم دينا فمن اضطر في مخمصه غير متجانف لاثم فان الله غفور رحيم', 6, 11, 43, 1, 2, 107, false, NULL),
    (673, 'tanzil-uthmani-v1.1', 5, 4, 'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمْتُم مِّنَ ٱلْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُ فَكُلُوا۟ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهِ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', '30c7b70b96b8c082cc1d9878bc955ffc15b9bbe7403f65d5bae4b62b2f2d2fa7', 'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمْتُم مِّنَ ٱلْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُ فَكُلُوا۟ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهِ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', '30c7b70b96b8c082cc1d9878bc955ffc15b9bbe7403f65d5bae4b62b2f2d2fa7', '30c7b70b96b8c082cc1d9878bc955ffc15b9bbe7403f65d5bae4b62b2f2d2fa7', NULL, 'يسلونك ماذا احل لهم قل احل لكم الطيبت وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما امسكن عليكم واذكروا اسم الله عليه واتقوا الله ان الله سريع الحساب', 6, 11, 43, 1, 2, 107, false, NULL),
    (674, 'tanzil-uthmani-v1.1', 5, 5, 'ٱلْيَوْمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ وَٱلْمُحْصَنَٰتُ مِنَ ٱلْمُؤْمِنَٰتِ وَٱلْمُحْصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍ وَمَن يَكْفُرْ بِٱلْإِيمَٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', 'd74b5c6c074573a75867a2cba662c02c14c21fafe0711abd5207ff73e66ccdd5', 'ٱلْيَوْمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ وَٱلْمُحْصَنَٰتُ مِنَ ٱلْمُؤْمِنَٰتِ وَٱلْمُحْصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍ وَمَن يَكْفُرْ بِٱلْإِيمَٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', 'd74b5c6c074573a75867a2cba662c02c14c21fafe0711abd5207ff73e66ccdd5', 'd74b5c6c074573a75867a2cba662c02c14c21fafe0711abd5207ff73e66ccdd5', NULL, 'اليوم احل لكم الطيبت وطعام الذين اوتوا الكتب حل لكم وطعامكم حل لهم والمحصنت من المؤمنت والمحصنت من الذين اوتوا الكتب من قبلكم اذا ءاتيتموهن اجورهن محصنين غير مسفحين ولا متخذي اخدان ومن يكفر بالايمن فقد حبط عمله وهو في الاخره من الخسرين', 6, 11, 43, 1, 2, 107, false, NULL),
    (675, 'tanzil-uthmani-v1.1', 5, 6, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ وَإِن كُنتُمْ جُنُبًا فَٱطَّهَّرُوا۟ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ', '676a1a5ba6fca8c29ad697957c3676d5d1da13321a9144e49ddb8f764b3203e9', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ وَإِن كُنتُمْ جُنُبًا فَٱطَّهَّرُوا۟ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ', '676a1a5ba6fca8c29ad697957c3676d5d1da13321a9144e49ddb8f764b3203e9', '676a1a5ba6fca8c29ad697957c3676d5d1da13321a9144e49ddb8f764b3203e9', NULL, 'يايها الذين ءامنوا اذا قمتم الي الصلوه فاغسلوا وجوهكم وايديكم الي المرافق وامسحوا برءوسكم وارجلكم الي الكعبين وان كنتم جنبا فاطهروا وان كنتم مرضي او علي سفر او جاء احد منكم من الغائط او لمستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم منه ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم وليتم نعمته عليكم لعلكم تشكرون', 6, 11, 43, 1, 2, 108, false, NULL),
    (676, 'tanzil-uthmani-v1.1', 5, 7, 'وَٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ وَمِيثَٰقَهُ ٱلَّذِى وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '67e1432b88c60306d5c1070634a7dffdadc4cecda00390cfa6cbf779812283a4', 'وَٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ وَمِيثَٰقَهُ ٱلَّذِى وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '67e1432b88c60306d5c1070634a7dffdadc4cecda00390cfa6cbf779812283a4', '67e1432b88c60306d5c1070634a7dffdadc4cecda00390cfa6cbf779812283a4', NULL, 'واذكروا نعمه الله عليكم وميثقه الذي واثقكم به اذ قلتم سمعنا واطعنا واتقوا الله ان الله عليم بذات الصدور', 6, 11, 43, 1, 2, 108, false, NULL),
    (677, 'tanzil-uthmani-v1.1', 5, 8, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '3f7059cb64115c4a5efade8f8b0429a44457a4cddaa9bda38f022bc058c772f0', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '3f7059cb64115c4a5efade8f8b0429a44457a4cddaa9bda38f022bc058c772f0', '3f7059cb64115c4a5efade8f8b0429a44457a4cddaa9bda38f022bc058c772f0', NULL, 'يايها الذين ءامنوا كونوا قومين لله شهداء بالقسط ولا يجرمنكم شنان قوم علي الا تعدلوا اعدلوا هو اقرب للتقوي واتقوا الله ان الله خبير بما تعملون', 6, 11, 43, 1, 2, 108, false, NULL),
    (678, 'tanzil-uthmani-v1.1', 5, 9, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', '72c294a69d326f15bbbf24299ac4b2e981bed5e07f333e77b257a398ac25df66', 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', '72c294a69d326f15bbbf24299ac4b2e981bed5e07f333e77b257a398ac25df66', '72c294a69d326f15bbbf24299ac4b2e981bed5e07f333e77b257a398ac25df66', NULL, 'وعد الله الذين ءامنوا وعملوا الصلحت لهم مغفره واجر عظيم', 6, 11, 43, 1, 2, 108, false, NULL),
    (679, 'tanzil-uthmani-v1.1', 5, 10, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'c0e50c23b8630f482495f326c92d0a4b13b8d7b1b61807b99350996bb32832b2', 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'c0e50c23b8630f482495f326c92d0a4b13b8d7b1b61807b99350996bb32832b2', 'c0e50c23b8630f482495f326c92d0a4b13b8d7b1b61807b99350996bb32832b2', NULL, 'والذين كفروا وكذبوا بايتنا اولئك اصحب الجحيم', 6, 11, 43, 1, 2, 109, false, NULL),
    (680, 'tanzil-uthmani-v1.1', 5, 11, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'f6d7e7209f8b1eb2f0e756df6c758839fdd96844cf449fd1b61ceab9ebd1ed1a', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'f6d7e7209f8b1eb2f0e756df6c758839fdd96844cf449fd1b61ceab9ebd1ed1a', 'f6d7e7209f8b1eb2f0e756df6c758839fdd96844cf449fd1b61ceab9ebd1ed1a', NULL, 'يايها الذين ءامنوا اذكروا نعمت الله عليكم اذ هم قوم ان يبسطوا اليكم ايديهم فكف ايديهم عنكم واتقوا الله وعلي الله فليتوكل المؤمنون', 6, 11, 43, 1, 2, 109, false, NULL),
    (681, 'tanzil-uthmani-v1.1', 5, 12, 'وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًا وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'ca2dea68b248bec03d958accbdee5fbf3c355bdfbbcc3b77f3a64fe9639416c1', 'وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًا وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'ca2dea68b248bec03d958accbdee5fbf3c355bdfbbcc3b77f3a64fe9639416c1', 'ca2dea68b248bec03d958accbdee5fbf3c355bdfbbcc3b77f3a64fe9639416c1', NULL, 'ولقد اخذ الله ميثق بني اسرءيل وبعثنا منهم اثني عشر نقيبا وقال الله اني معكم لئن اقمتم الصلوه وءاتيتم الزكوه وءامنتم برسلي وعزرتموهم واقرضتم الله قرضا حسنا لاكفرن عنكم سياتكم ولادخلنكم جنت تجري من تحتها الانهر فمن كفر بعد ذلك منكم فقد ضل سواء السبيل', 6, 11, 44, 1, 2, 109, false, NULL),
    (682, 'tanzil-uthmani-v1.1', 5, 13, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ لَعَنَّٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَٰسِيَةً يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍ مِّنْهُمْ إِلَّا قَلِيلًا مِّنْهُمْ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', '97727e991b98017aee3cd0dc233b31585e963ff5ec1136793ca28e1eaa9c5bc7', 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ لَعَنَّٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَٰسِيَةً يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍ مِّنْهُمْ إِلَّا قَلِيلًا مِّنْهُمْ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', '97727e991b98017aee3cd0dc233b31585e963ff5ec1136793ca28e1eaa9c5bc7', '97727e991b98017aee3cd0dc233b31585e963ff5ec1136793ca28e1eaa9c5bc7', NULL, 'فبما نقضهم ميثقهم لعنهم وجعلنا قلوبهم قسيه يحرفون الكلم عن مواضعه ونسوا حظا مما ذكروا به ولا تزال تطلع علي خائنه منهم الا قليلا منهم فاعف عنهم واصفح ان الله يحب المحسنين', 6, 11, 44, 1, 2, 109, false, NULL),
    (683, 'tanzil-uthmani-v1.1', 5, 14, 'وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰٓ أَخَذْنَا مِيثَٰقَهُمْ فَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ', 'ecccbe2c334f7b46faa8a80e544efc4e89a4d6572788f8d25a3983151e07b084', 'وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰٓ أَخَذْنَا مِيثَٰقَهُمْ فَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ', 'ecccbe2c334f7b46faa8a80e544efc4e89a4d6572788f8d25a3983151e07b084', 'ecccbe2c334f7b46faa8a80e544efc4e89a4d6572788f8d25a3983151e07b084', NULL, 'ومن الذين قالوا انا نصري اخذنا ميثقهم فنسوا حظا مما ذكروا به فاغرينا بينهم العداوه والبغضاء الي يوم القيمه وسوف ينبئهم الله بما كانوا يصنعون', 6, 11, 44, 1, 2, 110, false, NULL),
    (684, 'tanzil-uthmani-v1.1', 5, 15, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ٱلْكِتَٰبِ وَيَعْفُوا۟ عَن كَثِيرٍ قَدْ جَآءَكُم مِّنَ ٱللَّهِ نُورٌ وَكِتَٰبٌ مُّبِينٌ', '4f4a02feba8a2c161328f5190cd04297b04897e55fd5a6c488f2a6c6162c8604', 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ٱلْكِتَٰبِ وَيَعْفُوا۟ عَن كَثِيرٍ قَدْ جَآءَكُم مِّنَ ٱللَّهِ نُورٌ وَكِتَٰبٌ مُّبِينٌ', '4f4a02feba8a2c161328f5190cd04297b04897e55fd5a6c488f2a6c6162c8604', '4f4a02feba8a2c161328f5190cd04297b04897e55fd5a6c488f2a6c6162c8604', NULL, 'ياهل الكتب قد جاءكم رسولنا يبين لكم كثيرا مما كنتم تخفون من الكتب ويعفوا عن كثير قد جاءكم من الله نور وكتب مبين', 6, 11, 44, 1, 2, 110, false, NULL),
    (685, 'tanzil-uthmani-v1.1', 5, 16, 'يَهْدِى بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِهِۦ وَيَهْدِيهِمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '3acbfbef6a04cb10299e0745055d10ac72112741821549c7c98c2aad81a7dc90', 'يَهْدِى بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِهِۦ وَيَهْدِيهِمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '3acbfbef6a04cb10299e0745055d10ac72112741821549c7c98c2aad81a7dc90', '3acbfbef6a04cb10299e0745055d10ac72112741821549c7c98c2aad81a7dc90', NULL, 'يهدي به الله من اتبع رضونه سبل السلم ويخرجهم من الظلمت الي النور باذنه ويهديهم الي صرط مستقيم', 6, 11, 44, 1, 2, 110, false, NULL),
    (686, 'tanzil-uthmani-v1.1', 5, 17, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ قُلْ فَمَن يَمْلِكُ مِنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ أَن يُهْلِكَ ٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِى ٱلْأَرْضِ جَمِيعًا وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا يَخْلُقُ مَا يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '03c7fb963f5e7b744036a8c840d64ae0ac3532a16d95d6c802550241c9ebf7d0', 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ قُلْ فَمَن يَمْلِكُ مِنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ أَن يُهْلِكَ ٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِى ٱلْأَرْضِ جَمِيعًا وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا يَخْلُقُ مَا يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '03c7fb963f5e7b744036a8c840d64ae0ac3532a16d95d6c802550241c9ebf7d0', '03c7fb963f5e7b744036a8c840d64ae0ac3532a16d95d6c802550241c9ebf7d0', NULL, 'لقد كفر الذين قالوا ان الله هو المسيح ابن مريم قل فمن يملك من الله شيا ان اراد ان يهلك المسيح ابن مريم وامه ومن في الارض جميعا ولله ملك السموت والارض وما بينهما يخلق ما يشاء والله علي كل شيء قدير', 6, 11, 44, 1, 2, 110, false, NULL),
    (687, 'tanzil-uthmani-v1.1', 5, 18, 'وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَٰرَىٰ نَحْنُ أَبْنَٰٓؤُا۟ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَإِلَيْهِ ٱلْمَصِيرُ', 'd69de6bcc34f8096cd3b9f5e255265c6eb111675669d7362e96aaba22dd9e40e', 'وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَٰرَىٰ نَحْنُ أَبْنَٰٓؤُا۟ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَإِلَيْهِ ٱلْمَصِيرُ', 'd69de6bcc34f8096cd3b9f5e255265c6eb111675669d7362e96aaba22dd9e40e', 'd69de6bcc34f8096cd3b9f5e255265c6eb111675669d7362e96aaba22dd9e40e', NULL, 'وقالت اليهود والنصري نحن ابنؤا الله واحبؤه قل فلم يعذبكم بذنوبكم بل انتم بشر ممن خلق يغفر لمن يشاء ويعذب من يشاء ولله ملك السموت والارض وما بينهما واليه المصير', 6, 11, 44, 1, 2, 111, false, NULL),
    (688, 'tanzil-uthmani-v1.1', 5, 19, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةٍ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَآءَنَا مِنۢ بَشِيرٍ وَلَا نَذِيرٍ فَقَدْ جَآءَكُم بَشِيرٌ وَنَذِيرٌ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'b23a02f5d5ef94036c9dc3d59389cde7ebaff1c68cae39667e77709a1006944e', 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةٍ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَآءَنَا مِنۢ بَشِيرٍ وَلَا نَذِيرٍ فَقَدْ جَآءَكُم بَشِيرٌ وَنَذِيرٌ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'b23a02f5d5ef94036c9dc3d59389cde7ebaff1c68cae39667e77709a1006944e', 'b23a02f5d5ef94036c9dc3d59389cde7ebaff1c68cae39667e77709a1006944e', NULL, 'ياهل الكتب قد جاءكم رسولنا يبين لكم علي فتره من الرسل ان تقولوا ما جاءنا من بشير ولا نذير فقد جاءكم بشير ونذير والله علي كل شيء قدير', 6, 11, 44, 1, 2, 111, false, NULL),
    (689, 'tanzil-uthmani-v1.1', 5, 20, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكًا وَءَاتَىٰكُم مَّا لَمْ يُؤْتِ أَحَدًا مِّنَ ٱلْعَٰلَمِينَ', '411b0a32d6bf05a2a6a7381461eafe8579c25aef850c66f8255fcbcd07dcb0f4', 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكًا وَءَاتَىٰكُم مَّا لَمْ يُؤْتِ أَحَدًا مِّنَ ٱلْعَٰلَمِينَ', '411b0a32d6bf05a2a6a7381461eafe8579c25aef850c66f8255fcbcd07dcb0f4', '411b0a32d6bf05a2a6a7381461eafe8579c25aef850c66f8255fcbcd07dcb0f4', NULL, 'واذ قال موسي لقومه يقوم اذكروا نعمه الله عليكم اذ جعل فيكم انبياء وجعلكم ملوكا وءاتيكم ما لم يؤت احدا من العلمين', 6, 11, 44, 1, 2, 111, false, NULL),
    (690, 'tanzil-uthmani-v1.1', 5, 21, 'يَٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 'b265a506027d7c826cbc10c64f7b90c84f5411225740b091ab04f2a88559e268', 'يَٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 'b265a506027d7c826cbc10c64f7b90c84f5411225740b091ab04f2a88559e268', 'b265a506027d7c826cbc10c64f7b90c84f5411225740b091ab04f2a88559e268', NULL, 'يقوم ادخلوا الارض المقدسه التي كتب الله لكم ولا ترتدوا علي ادباركم فتنقلبوا خسرين', 6, 11, 44, 1, 2, 111, false, NULL),
    (691, 'tanzil-uthmani-v1.1', 5, 22, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ', '1a273c174025e0e13066eb32c575132641c834faf250583c22e93f7446215306', 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ', '1a273c174025e0e13066eb32c575132641c834faf250583c22e93f7446215306', '1a273c174025e0e13066eb32c575132641c834faf250583c22e93f7446215306', NULL, 'قالوا يموسي ان فيها قوما جبارين وانا لن ندخلها حتي يخرجوا منها فان يخرجوا منها فانا دخلون', 6, 11, 44, 1, 2, 111, false, NULL),
    (692, 'tanzil-uthmani-v1.1', 5, 23, 'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنْعَمَ ٱللَّهُ عَلَيْهِمَا ٱدْخُلُوا۟ عَلَيْهِمُ ٱلْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَٰلِبُونَ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓا۟ إِن كُنتُم مُّؤْمِنِينَ', '2db2f19bc1168fb9c1bb05fbbf15be1df8092ffda4a6c586b01e548a9381ce67', 'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنْعَمَ ٱللَّهُ عَلَيْهِمَا ٱدْخُلُوا۟ عَلَيْهِمُ ٱلْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَٰلِبُونَ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓا۟ إِن كُنتُم مُّؤْمِنِينَ', '2db2f19bc1168fb9c1bb05fbbf15be1df8092ffda4a6c586b01e548a9381ce67', '2db2f19bc1168fb9c1bb05fbbf15be1df8092ffda4a6c586b01e548a9381ce67', NULL, 'قال رجلان من الذين يخافون انعم الله عليهما ادخلوا عليهم الباب فاذا دخلتموه فانكم غلبون وعلي الله فتوكلوا ان كنتم مؤمنين', 6, 11, 44, 1, 2, 111, false, NULL),
    (693, 'tanzil-uthmani-v1.1', 5, 24, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَدًا مَّا دَامُوا۟ فِيهَا فَٱذْهَبْ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ', '459ac05b9d15edbca70280cb9eb9557fe8d3f79e91bd4641559a7e3c8f5a490f', 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَدًا مَّا دَامُوا۟ فِيهَا فَٱذْهَبْ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ', '459ac05b9d15edbca70280cb9eb9557fe8d3f79e91bd4641559a7e3c8f5a490f', '459ac05b9d15edbca70280cb9eb9557fe8d3f79e91bd4641559a7e3c8f5a490f', NULL, 'قالوا يموسي انا لن ندخلها ابدا ما داموا فيها فاذهب انت وربك فقتلا انا ههنا قعدون', 6, 11, 44, 1, 2, 112, false, NULL),
    (694, 'tanzil-uthmani-v1.1', 5, 25, 'قَالَ رَبِّ إِنِّى لَآ أَمْلِكُ إِلَّا نَفْسِى وَأَخِى فَٱفْرُقْ بَيْنَنَا وَبَيْنَ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', '797367a3fa44298166d4f8f7af37649b1b515ca843e8191f75e8b1f873cbac4d', 'قَالَ رَبِّ إِنِّى لَآ أَمْلِكُ إِلَّا نَفْسِى وَأَخِى فَٱفْرُقْ بَيْنَنَا وَبَيْنَ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', '797367a3fa44298166d4f8f7af37649b1b515ca843e8191f75e8b1f873cbac4d', '797367a3fa44298166d4f8f7af37649b1b515ca843e8191f75e8b1f873cbac4d', NULL, 'قال رب اني لا املك الا نفسي واخي فافرق بيننا وبين القوم الفسقين', 6, 11, 44, 1, 2, 112, false, NULL),
    (695, 'tanzil-uthmani-v1.1', 5, 26, 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ أَرْبَعِينَ سَنَةً يَتِيهُونَ فِى ٱلْأَرْضِ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'bc6467bc290d31ab463c1013bb24dbc214866363c5e4e79f3eb08f3c547903a3', 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ أَرْبَعِينَ سَنَةً يَتِيهُونَ فِى ٱلْأَرْضِ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 'bc6467bc290d31ab463c1013bb24dbc214866363c5e4e79f3eb08f3c547903a3', 'bc6467bc290d31ab463c1013bb24dbc214866363c5e4e79f3eb08f3c547903a3', NULL, 'قال فانها محرمه عليهم اربعين سنه يتيهون في الارض فلا تاس علي القوم الفسقين', 6, 11, 44, 1, 2, 112, false, NULL),
    (696, 'tanzil-uthmani-v1.1', 5, 27, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱبْنَىْ ءَادَمَ بِٱلْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ٱلْـَٔاخَرِ قَالَ لَأَقْتُلَنَّكَ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلْمُتَّقِينَ', '3859fa74883e59169f4cbdb407dc7aedd3822b9d0d58cbca2ee9cc34d3854893', 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱبْنَىْ ءَادَمَ بِٱلْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ٱلْـَٔاخَرِ قَالَ لَأَقْتُلَنَّكَ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلْمُتَّقِينَ', '3859fa74883e59169f4cbdb407dc7aedd3822b9d0d58cbca2ee9cc34d3854893', '3859fa74883e59169f4cbdb407dc7aedd3822b9d0d58cbca2ee9cc34d3854893', NULL, 'واتل عليهم نبا ابني ءادم بالحق اذ قربا قربانا فتقبل من احدهما ولم يتقبل من الاخر قال لاقتلنك قال انما يتقبل الله من المتقين', 6, 12, 45, 1, 2, 112, false, NULL),
    (697, 'tanzil-uthmani-v1.1', 5, 28, 'لَئِنۢ بَسَطتَ إِلَىَّ يَدَكَ لِتَقْتُلَنِى مَآ أَنَا۠ بِبَاسِطٍ يَدِىَ إِلَيْكَ لِأَقْتُلَكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', '97a6b62cba065a7526b3f4c746c5630e0af2317bc5cfd4c642423ebe3f98c994', 'لَئِنۢ بَسَطتَ إِلَىَّ يَدَكَ لِتَقْتُلَنِى مَآ أَنَا۠ بِبَاسِطٍ يَدِىَ إِلَيْكَ لِأَقْتُلَكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', '97a6b62cba065a7526b3f4c746c5630e0af2317bc5cfd4c642423ebe3f98c994', '97a6b62cba065a7526b3f4c746c5630e0af2317bc5cfd4c642423ebe3f98c994', NULL, 'لئن بسطت الي يدك لتقتلني ما انا بباسط يدي اليك لاقتلك اني اخاف الله رب العلمين', 6, 12, 45, 1, 2, 112, false, NULL),
    (698, 'tanzil-uthmani-v1.1', 5, 29, 'إِنِّىٓ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَٰبِ ٱلنَّارِ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', '4e896ee98ec9466f35b297e3e7755f47f49d3a23d169daeddcc776d8d0133086', 'إِنِّىٓ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَٰبِ ٱلنَّارِ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', '4e896ee98ec9466f35b297e3e7755f47f49d3a23d169daeddcc776d8d0133086', '4e896ee98ec9466f35b297e3e7755f47f49d3a23d169daeddcc776d8d0133086', NULL, 'اني اريد ان تبوا باثمي واثمك فتكون من اصحب النار وذلك جزؤا الظلمين', 6, 12, 45, 1, 2, 112, false, NULL),
    (699, 'tanzil-uthmani-v1.1', 5, 30, 'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ٱلْخَٰسِرِينَ', 'f5f9866ac55df94611f06a6f53238cc5f027ebd251ebff8b53ef139c3270e201', 'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ٱلْخَٰسِرِينَ', 'f5f9866ac55df94611f06a6f53238cc5f027ebd251ebff8b53ef139c3270e201', 'f5f9866ac55df94611f06a6f53238cc5f027ebd251ebff8b53ef139c3270e201', NULL, 'فطوعت له نفسه قتل اخيه فقتله فاصبح من الخسرين', 6, 12, 45, 1, 2, 112, false, NULL),
    (700, 'tanzil-uthmani-v1.1', 5, 31, 'فَبَعَثَ ٱللَّهُ غُرَابًا يَبْحَثُ فِى ٱلْأَرْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِى سَوْءَةَ أَخِيهِ قَالَ يَٰوَيْلَتَىٰٓ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَٰذَا ٱلْغُرَابِ فَأُوَٰرِىَ سَوْءَةَ أَخِى فَأَصْبَحَ مِنَ ٱلنَّٰدِمِينَ', '7a6bae1b8e25e9de0dc7aafcd602b6aa4124b45b00bb25e0318ecf657b3a8712', 'فَبَعَثَ ٱللَّهُ غُرَابًا يَبْحَثُ فِى ٱلْأَرْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِى سَوْءَةَ أَخِيهِ قَالَ يَٰوَيْلَتَىٰٓ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَٰذَا ٱلْغُرَابِ فَأُوَٰرِىَ سَوْءَةَ أَخِى فَأَصْبَحَ مِنَ ٱلنَّٰدِمِينَ', '7a6bae1b8e25e9de0dc7aafcd602b6aa4124b45b00bb25e0318ecf657b3a8712', '7a6bae1b8e25e9de0dc7aafcd602b6aa4124b45b00bb25e0318ecf657b3a8712', NULL, 'فبعث الله غرابا يبحث في الارض ليريه كيف يوري سوءه اخيه قال يويلتي اعجزت ان اكون مثل هذا الغراب فاوري سوءه اخي فاصبح من الندمين', 6, 12, 45, 1, 2, 112, false, NULL),
    (701, 'tanzil-uthmani-v1.1', 5, 32, 'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًا وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرًا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ', '684723381073a332aa5b3541adf7f6d5386f0eb7ebcae27e741dcdf257022727', 'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًا وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرًا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ', '684723381073a332aa5b3541adf7f6d5386f0eb7ebcae27e741dcdf257022727', '684723381073a332aa5b3541adf7f6d5386f0eb7ebcae27e741dcdf257022727', NULL, 'من اجل ذلك كتبنا علي بني اسرءيل انه من قتل نفسا بغير نفس او فساد في الارض فكانما قتل الناس جميعا ومن احياها فكانما احيا الناس جميعا ولقد جاءتهم رسلنا بالبينت ثم ان كثيرا منهم بعد ذلك في الارض لمسرفون', 6, 12, 45, 1, 2, 113, false, NULL),
    (702, 'tanzil-uthmani-v1.1', 5, 33, 'إِنَّمَا جَزَٰٓؤُا۟ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا أَن يُقَتَّلُوٓا۟ أَوْ يُصَلَّبُوٓا۟ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَٰفٍ أَوْ يُنفَوْا۟ مِنَ ٱلْأَرْضِ ذَٰلِكَ لَهُمْ خِزْىٌ فِى ٱلدُّنْيَا وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', '24e773488aaa2a2189f0333a47665094ba73207a91cd8c117eb59414dde881ee', 'إِنَّمَا جَزَٰٓؤُا۟ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا أَن يُقَتَّلُوٓا۟ أَوْ يُصَلَّبُوٓا۟ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَٰفٍ أَوْ يُنفَوْا۟ مِنَ ٱلْأَرْضِ ذَٰلِكَ لَهُمْ خِزْىٌ فِى ٱلدُّنْيَا وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', '24e773488aaa2a2189f0333a47665094ba73207a91cd8c117eb59414dde881ee', '24e773488aaa2a2189f0333a47665094ba73207a91cd8c117eb59414dde881ee', NULL, 'انما جزؤا الذين يحاربون الله ورسوله ويسعون في الارض فسادا ان يقتلوا او يصلبوا او تقطع ايديهم وارجلهم من خلف او ينفوا من الارض ذلك لهم خزي في الدنيا ولهم في الاخره عذاب عظيم', 6, 12, 45, 1, 2, 113, false, NULL),
    (703, 'tanzil-uthmani-v1.1', 5, 34, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِن قَبْلِ أَن تَقْدِرُوا۟ عَلَيْهِمْ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '40e6bd2e8d42144efe7081594b21ff160cd074ae1bc7c6ba4974fcaff50b5d46', 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِن قَبْلِ أَن تَقْدِرُوا۟ عَلَيْهِمْ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '40e6bd2e8d42144efe7081594b21ff160cd074ae1bc7c6ba4974fcaff50b5d46', '40e6bd2e8d42144efe7081594b21ff160cd074ae1bc7c6ba4974fcaff50b5d46', NULL, 'الا الذين تابوا من قبل ان تقدروا عليهم فاعلموا ان الله غفور رحيم', 6, 12, 45, 1, 2, 113, false, NULL),
    (704, 'tanzil-uthmani-v1.1', 5, 35, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبْتَغُوٓا۟ إِلَيْهِ ٱلْوَسِيلَةَ وَجَٰهِدُوا۟ فِى سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ', '9fa1baa4cd659b942142d466e1d781489ae078923f96d317fe03c82ade3e2aa0', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبْتَغُوٓا۟ إِلَيْهِ ٱلْوَسِيلَةَ وَجَٰهِدُوا۟ فِى سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ', '9fa1baa4cd659b942142d466e1d781489ae078923f96d317fe03c82ade3e2aa0', '9fa1baa4cd659b942142d466e1d781489ae078923f96d317fe03c82ade3e2aa0', NULL, 'يايها الذين ءامنوا اتقوا الله وابتغوا اليه الوسيله وجهدوا في سبيله لعلكم تفلحون', 6, 12, 45, 1, 2, 113, false, NULL),
    (705, 'tanzil-uthmani-v1.1', 5, 36, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَٰمَةِ مَا تُقُبِّلَ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '7f264f2e7b1159d4f798163c8ee86958362a1e32f4229afa8b516eca5f99d6f6', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَٰمَةِ مَا تُقُبِّلَ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '7f264f2e7b1159d4f798163c8ee86958362a1e32f4229afa8b516eca5f99d6f6', '7f264f2e7b1159d4f798163c8ee86958362a1e32f4229afa8b516eca5f99d6f6', NULL, 'ان الذين كفروا لو ان لهم ما في الارض جميعا ومثله معه ليفتدوا به من عذاب يوم القيمه ما تقبل منهم ولهم عذاب اليم', 6, 12, 45, 1, 2, 113, false, NULL),
    (706, 'tanzil-uthmani-v1.1', 5, 37, 'يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُّقِيمٌ', '233581437170ffd3b787e01dfd850297db23397ebda3f5f452cfc5c2f65a8276', 'يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنْهَا وَلَهُمْ عَذَابٌ مُّقِيمٌ', '233581437170ffd3b787e01dfd850297db23397ebda3f5f452cfc5c2f65a8276', '233581437170ffd3b787e01dfd850297db23397ebda3f5f452cfc5c2f65a8276', NULL, 'يريدون ان يخرجوا من النار وما هم بخرجين منها ولهم عذاب مقيم', 6, 12, 45, 1, 2, 114, false, NULL),
    (707, 'tanzil-uthmani-v1.1', 5, 38, 'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَٰلًا مِّنَ ٱللَّهِ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'de82e3ccc693a34dd7c27a8d54314ab3aed95867f07c09cceac7a94acea7ed19', 'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَٰلًا مِّنَ ٱللَّهِ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'de82e3ccc693a34dd7c27a8d54314ab3aed95867f07c09cceac7a94acea7ed19', 'de82e3ccc693a34dd7c27a8d54314ab3aed95867f07c09cceac7a94acea7ed19', NULL, 'والسارق والسارقه فاقطعوا ايديهما جزاء بما كسبا نكلا من الله والله عزيز حكيم', 6, 12, 45, 1, 2, 114, false, NULL),
    (708, 'tanzil-uthmani-v1.1', 5, 39, 'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'd6cacba5cc3fd0da7fe8da97f4facb5b983bca4de84bbcf07fb592c25fc29461', 'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'd6cacba5cc3fd0da7fe8da97f4facb5b983bca4de84bbcf07fb592c25fc29461', 'd6cacba5cc3fd0da7fe8da97f4facb5b983bca4de84bbcf07fb592c25fc29461', NULL, 'فمن تاب من بعد ظلمه واصلح فان الله يتوب عليه ان الله غفور رحيم', 6, 12, 45, 1, 2, 114, false, NULL),
    (709, 'tanzil-uthmani-v1.1', 5, 40, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُعَذِّبُ مَن يَشَآءُ وَيَغْفِرُ لِمَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '34ae8a10be2fbaf16c254a27620ea0044449a180a8df36d43fb78676a9229a1f', 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُعَذِّبُ مَن يَشَآءُ وَيَغْفِرُ لِمَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '34ae8a10be2fbaf16c254a27620ea0044449a180a8df36d43fb78676a9229a1f', '34ae8a10be2fbaf16c254a27620ea0044449a180a8df36d43fb78676a9229a1f', NULL, 'الم تعلم ان الله له ملك السموت والارض يعذب من يشاء ويغفر لمن يشاء والله علي كل شيء قدير', 6, 12, 45, 1, 2, 114, false, NULL),
    (710, 'tanzil-uthmani-v1.1', 5, 41, 'يَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ وَمِنَ ٱلَّذِينَ هَادُوا۟ سَمَّٰعُونَ لِلْكَذِبِ سَمَّٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ يَقُولُونَ إِنْ أُوتِيتُمْ هَٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا أُو۟لَٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', '6091fad4dfed4146ee460d7059a75f315a400f415e35bf3543e7414c15248577', 'يَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ وَمِنَ ٱلَّذِينَ هَادُوا۟ سَمَّٰعُونَ لِلْكَذِبِ سَمَّٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ يَقُولُونَ إِنْ أُوتِيتُمْ هَٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا أُو۟لَٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ', '6091fad4dfed4146ee460d7059a75f315a400f415e35bf3543e7414c15248577', '6091fad4dfed4146ee460d7059a75f315a400f415e35bf3543e7414c15248577', NULL, 'يايها الرسول لا يحزنك الذين يسرعون في الكفر من الذين قالوا ءامنا بافوههم ولم تؤمن قلوبهم ومن الذين هادوا سمعون للكذب سمعون لقوم ءاخرين لم ياتوك يحرفون الكلم من بعد مواضعه يقولون ان اوتيتم هذا فخذوه وان لم تؤتوه فاحذروا ومن يرد الله فتنته فلن تملك له من الله شيا اولئك الذين لم يرد الله ان يطهر قلوبهم لهم في الدنيا خزي ولهم في الاخره عذاب عظيم', 6, 12, 46, 1, 2, 114, false, NULL),
    (711, 'tanzil-uthmani-v1.1', 5, 42, 'سَمَّٰعُونَ لِلْكَذِبِ أَكَّٰلُونَ لِلسُّحْتِ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًٔا وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', '99bc08a5445e4af42672a054e40f178e60cb595c17db7fac405eae3c858bff9b', 'سَمَّٰعُونَ لِلْكَذِبِ أَكَّٰلُونَ لِلسُّحْتِ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًٔا وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', '99bc08a5445e4af42672a054e40f178e60cb595c17db7fac405eae3c858bff9b', '99bc08a5445e4af42672a054e40f178e60cb595c17db7fac405eae3c858bff9b', NULL, 'سمعون للكذب اكلون للسحت فان جاءوك فاحكم بينهم او اعرض عنهم وان تعرض عنهم فلن يضروك شيا وان حكمت فاحكم بينهم بالقسط ان الله يحب المقسطين', 6, 12, 46, 1, 2, 115, false, NULL),
    (712, 'tanzil-uthmani-v1.1', 5, 43, 'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوْرَىٰةُ فِيهَا حُكْمُ ٱللَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', '00e239b23cae7cd82525fccf110242594f67df35f404c013ce1441dc548dae5c', 'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوْرَىٰةُ فِيهَا حُكْمُ ٱللَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', '00e239b23cae7cd82525fccf110242594f67df35f404c013ce1441dc548dae5c', '00e239b23cae7cd82525fccf110242594f67df35f404c013ce1441dc548dae5c', NULL, 'وكيف يحكمونك وعندهم التوريه فيها حكم الله ثم يتولون من بعد ذلك وما اولئك بالمؤمنين', 6, 12, 46, 1, 2, 115, false, NULL),
    (713, 'tanzil-uthmani-v1.1', 5, 44, 'إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ', '0706327176ec09e4fe6315c28c195d0482a71e7268b501a83eea67780f39315f', 'إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ', '0706327176ec09e4fe6315c28c195d0482a71e7268b501a83eea67780f39315f', '0706327176ec09e4fe6315c28c195d0482a71e7268b501a83eea67780f39315f', NULL, 'انا انزلنا التوريه فيها هدي ونور يحكم بها النبيون الذين اسلموا للذين هادوا والربنيون والاحبار بما استحفظوا من كتب الله وكانوا عليه شهداء فلا تخشوا الناس واخشون ولا تشتروا بايتي ثمنا قليلا ومن لم يحكم بما انزل الله فاولئك هم الكفرون', 6, 12, 46, 1, 2, 115, false, NULL),
    (714, 'tanzil-uthmani-v1.1', 5, 45, 'وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٌ لَّهُۥ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'e16aef95ab03a032be3a3e08144b00ad53f916c132ce0debec2528fd69d07c6c', 'وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٌ لَّهُۥ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'e16aef95ab03a032be3a3e08144b00ad53f916c132ce0debec2528fd69d07c6c', 'e16aef95ab03a032be3a3e08144b00ad53f916c132ce0debec2528fd69d07c6c', NULL, 'وكتبنا عليهم فيها ان النفس بالنفس والعين بالعين والانف بالانف والاذن بالاذن والسن بالسن والجروح قصاص فمن تصدق به فهو كفاره له ومن لم يحكم بما انزل الله فاولئك هم الظلمون', 6, 12, 46, 1, 2, 115, false, NULL),
    (715, 'tanzil-uthmani-v1.1', 5, 46, 'وَقَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًى وَمَوْعِظَةً لِّلْمُتَّقِينَ', 'f3f7d675d5225a7229b9d92d640613fb692d70c144d1c0679089fcab450b46f9', 'وَقَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًى وَمَوْعِظَةً لِّلْمُتَّقِينَ', 'f3f7d675d5225a7229b9d92d640613fb692d70c144d1c0679089fcab450b46f9', 'f3f7d675d5225a7229b9d92d640613fb692d70c144d1c0679089fcab450b46f9', NULL, 'وقفينا علي ءاثرهم بعيسي ابن مريم مصدقا لما بين يديه من التوريه وءاتينه الانجيل فيه هدي ونور ومصدقا لما بين يديه من التوريه وهدي وموعظه للمتقين', 6, 12, 46, 1, 2, 116, false, NULL),
    (716, 'tanzil-uthmani-v1.1', 5, 47, 'وَلْيَحْكُمْ أَهْلُ ٱلْإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', '7e2c934232209f6d144c01b70c8985dbb457d3da030a67175b364047b249a160', 'وَلْيَحْكُمْ أَهْلُ ٱلْإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', '7e2c934232209f6d144c01b70c8985dbb457d3da030a67175b364047b249a160', '7e2c934232209f6d144c01b70c8985dbb457d3da030a67175b364047b249a160', NULL, 'وليحكم اهل الانجيل بما انزل الله فيه ومن لم يحكم بما انزل الله فاولئك هم الفسقون', 6, 12, 46, 1, 2, 116, false, NULL),
    (717, 'tanzil-uthmani-v1.1', 5, 48, 'وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَٰبِ وَمُهَيْمِنًا عَلَيْهِ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'e21ce3a6b80142c405ab215c493d49b760c37d9b34d7470c4c59480e834e0e62', 'وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَٰبِ وَمُهَيْمِنًا عَلَيْهِ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'e21ce3a6b80142c405ab215c493d49b760c37d9b34d7470c4c59480e834e0e62', 'e21ce3a6b80142c405ab215c493d49b760c37d9b34d7470c4c59480e834e0e62', NULL, 'وانزلنا اليك الكتب بالحق مصدقا لما بين يديه من الكتب ومهيمنا عليه فاحكم بينهم بما انزل الله ولا تتبع اهواءهم عما جاءك من الحق لكل جعلنا منكم شرعه ومنهاجا ولو شاء الله لجعلكم امه وحده ولكن ليبلوكم في ما ءاتيكم فاستبقوا الخيرت الي الله مرجعكم جميعا فينبئكم بما كنتم فيه تختلفون', 6, 12, 46, 1, 2, 116, false, NULL),
    (718, 'tanzil-uthmani-v1.1', 5, 49, 'وَأَنِ ٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَٱحْذَرْهُمْ أَن يَفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ٱللَّهُ إِلَيْكَ فَإِن تَوَلَّوْا۟ فَٱعْلَمْ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ', '246b4d5c5f6fb200f30794c3a728876ad4cce79192654def47fd7c645748e90d', 'وَأَنِ ٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَٱحْذَرْهُمْ أَن يَفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ٱللَّهُ إِلَيْكَ فَإِن تَوَلَّوْا۟ فَٱعْلَمْ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ', '246b4d5c5f6fb200f30794c3a728876ad4cce79192654def47fd7c645748e90d', '246b4d5c5f6fb200f30794c3a728876ad4cce79192654def47fd7c645748e90d', NULL, 'وان احكم بينهم بما انزل الله ولا تتبع اهواءهم واحذرهم ان يفتنوك عن بعض ما انزل الله اليك فان تولوا فاعلم انما يريد الله ان يصيبهم ببعض ذنوبهم وان كثيرا من الناس لفسقون', 6, 12, 46, 1, 2, 116, false, NULL),
    (719, 'tanzil-uthmani-v1.1', 5, 50, 'أَفَحُكْمَ ٱلْجَٰهِلِيَّةِ يَبْغُونَ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ', '5e113612d6280187151022487e34d0e78cf6862b852d3f67cd38e59b94702116', 'أَفَحُكْمَ ٱلْجَٰهِلِيَّةِ يَبْغُونَ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ', '5e113612d6280187151022487e34d0e78cf6862b852d3f67cd38e59b94702116', '5e113612d6280187151022487e34d0e78cf6862b852d3f67cd38e59b94702116', NULL, 'افحكم الجهليه يبغون ومن احسن من الله حكما لقوم يوقنون', 6, 12, 46, 1, 2, 116, false, NULL),
    (720, 'tanzil-uthmani-v1.1', 5, 51, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوْلِيَآءَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'b4795f84129f91b3d1939cdc33cda95fa07eb832aced85ebb6f76268c77da623', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوْلِيَآءَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'b4795f84129f91b3d1939cdc33cda95fa07eb832aced85ebb6f76268c77da623', 'b4795f84129f91b3d1939cdc33cda95fa07eb832aced85ebb6f76268c77da623', NULL, 'يايها الذين ءامنوا لا تتخذوا اليهود والنصري اولياء بعضهم اولياء بعض ومن يتولهم منكم فانه منهم ان الله لا يهدي القوم الظلمين', 6, 12, 47, 1, 2, 117, false, NULL),
    (721, 'tanzil-uthmani-v1.1', 5, 52, 'فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يُسَٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَٰدِمِينَ', '3370dab4ba36330ba22cc64db232b523f4c1b6a14046e315be11cc7d4998df03', 'فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يُسَٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَٰدِمِينَ', '3370dab4ba36330ba22cc64db232b523f4c1b6a14046e315be11cc7d4998df03', '3370dab4ba36330ba22cc64db232b523f4c1b6a14046e315be11cc7d4998df03', NULL, 'فتري الذين في قلوبهم مرض يسرعون فيهم يقولون نخشي ان تصيبنا دائره فعسي الله ان ياتي بالفتح او امر من عنده فيصبحوا علي ما اسروا في انفسهم ندمين', 6, 12, 47, 1, 2, 117, false, NULL),
    (722, 'tanzil-uthmani-v1.1', 5, 53, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ إِنَّهُمْ لَمَعَكُمْ حَبِطَتْ أَعْمَٰلُهُمْ فَأَصْبَحُوا۟ خَٰسِرِينَ', 'c63d67f0f95ed0837673c4cc64c7df4353533c0f16d9b407463c8627de51224d', 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ إِنَّهُمْ لَمَعَكُمْ حَبِطَتْ أَعْمَٰلُهُمْ فَأَصْبَحُوا۟ خَٰسِرِينَ', 'c63d67f0f95ed0837673c4cc64c7df4353533c0f16d9b407463c8627de51224d', 'c63d67f0f95ed0837673c4cc64c7df4353533c0f16d9b407463c8627de51224d', NULL, 'ويقول الذين ءامنوا اهؤلاء الذين اقسموا بالله جهد ايمنهم انهم لمعكم حبطت اعملهم فاصبحوا خسرين', 6, 12, 47, 1, 2, 117, false, NULL),
    (723, 'tanzil-uthmani-v1.1', 5, 54, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَأْتِى ٱللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلْمُؤْمِنِينَ أَعِزَّةٍ عَلَى ٱلْكَٰفِرِينَ يُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَآئِمٍ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '9169a0bebd76ac571b225340ffbe5756ff48565a4c12c03052fac2361093d44f', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَأْتِى ٱللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلْمُؤْمِنِينَ أَعِزَّةٍ عَلَى ٱلْكَٰفِرِينَ يُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَآئِمٍ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '9169a0bebd76ac571b225340ffbe5756ff48565a4c12c03052fac2361093d44f', '9169a0bebd76ac571b225340ffbe5756ff48565a4c12c03052fac2361093d44f', NULL, 'يايها الذين ءامنوا من يرتد منكم عن دينه فسوف ياتي الله بقوم يحبهم ويحبونه اذله علي المؤمنين اعزه علي الكفرين يجهدون في سبيل الله ولا يخافون لومه لائم ذلك فضل الله يؤتيه من يشاء والله وسع عليم', 6, 12, 47, 1, 2, 117, false, NULL),
    (724, 'tanzil-uthmani-v1.1', 5, 55, 'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُمْ رَٰكِعُونَ', 'bc9022bbc063d00dcac60b35747e09bfe227777d82e3f173aaf58e74a932ecea', 'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُمْ رَٰكِعُونَ', 'bc9022bbc063d00dcac60b35747e09bfe227777d82e3f173aaf58e74a932ecea', 'bc9022bbc063d00dcac60b35747e09bfe227777d82e3f173aaf58e74a932ecea', NULL, 'انما وليكم الله ورسوله والذين ءامنوا الذين يقيمون الصلوه ويؤتون الزكوه وهم ركعون', 6, 12, 47, 1, 2, 117, false, NULL),
    (725, 'tanzil-uthmani-v1.1', 5, 56, 'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُوا۟ فَإِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْغَٰلِبُونَ', 'c44453651add759f0421ad28d2ed03f9311b629c14cb3a25ae38295a594e520a', 'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُوا۟ فَإِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْغَٰلِبُونَ', 'c44453651add759f0421ad28d2ed03f9311b629c14cb3a25ae38295a594e520a', 'c44453651add759f0421ad28d2ed03f9311b629c14cb3a25ae38295a594e520a', NULL, 'ومن يتول الله ورسوله والذين ءامنوا فان حزب الله هم الغلبون', 6, 12, 47, 1, 2, 117, false, NULL),
    (726, 'tanzil-uthmani-v1.1', 5, 57, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَكُمْ هُزُوًا وَلَعِبًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَٱلْكُفَّارَ أَوْلِيَآءَ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', '1682ca82261b6c9e98ec8d0d311a96e564fb75a722e39667d859164f1d3ac9af', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَكُمْ هُزُوًا وَلَعِبًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَٱلْكُفَّارَ أَوْلِيَآءَ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', '1682ca82261b6c9e98ec8d0d311a96e564fb75a722e39667d859164f1d3ac9af', '1682ca82261b6c9e98ec8d0d311a96e564fb75a722e39667d859164f1d3ac9af', NULL, 'يايها الذين ءامنوا لا تتخذوا الذين اتخذوا دينكم هزوا ولعبا من الذين اوتوا الكتب من قبلكم والكفار اولياء واتقوا الله ان كنتم مؤمنين', 6, 12, 47, 1, 2, 117, false, NULL),
    (727, 'tanzil-uthmani-v1.1', 5, 58, 'وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًا وَلَعِبًا ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', '31a58b0ca957745f3a9ef296bd9fe2914ac3c9353a7ca00be32aa8771f4ffbeb', 'وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًا وَلَعِبًا ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', '31a58b0ca957745f3a9ef296bd9fe2914ac3c9353a7ca00be32aa8771f4ffbeb', '31a58b0ca957745f3a9ef296bd9fe2914ac3c9353a7ca00be32aa8771f4ffbeb', NULL, 'واذا ناديتم الي الصلوه اتخذوها هزوا ولعبا ذلك بانهم قوم لا يعقلون', 6, 12, 47, 1, 2, 118, false, NULL),
    (728, 'tanzil-uthmani-v1.1', 5, 59, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَٰسِقُونَ', '466e4be79703ecb3a74e0cd3554f0093b024f9feffc313f3115ec4ea8875a026', 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَٰسِقُونَ', '466e4be79703ecb3a74e0cd3554f0093b024f9feffc313f3115ec4ea8875a026', '466e4be79703ecb3a74e0cd3554f0093b024f9feffc313f3115ec4ea8875a026', NULL, 'قل ياهل الكتب هل تنقمون منا الا ان ءامنا بالله وما انزل الينا وما انزل من قبل وان اكثركم فسقون', 6, 12, 47, 1, 2, 118, false, NULL),
    (729, 'tanzil-uthmani-v1.1', 5, 60, 'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ٱلْقِرَدَةَ وَٱلْخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَ أُو۟لَٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ', '626264962f35c7d447f2831684a7545f9b5e1893bd8c3b08a4de2b6cf716de74', 'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ٱلْقِرَدَةَ وَٱلْخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَ أُو۟لَٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ', '626264962f35c7d447f2831684a7545f9b5e1893bd8c3b08a4de2b6cf716de74', '626264962f35c7d447f2831684a7545f9b5e1893bd8c3b08a4de2b6cf716de74', NULL, 'قل هل انبئكم بشر من ذلك مثوبه عند الله من لعنه الله وغضب عليه وجعل منهم القرده والخنازير وعبد الطغوت اولئك شر مكانا واضل عن سواء السبيل', 6, 12, 47, 1, 2, 118, false, NULL),
    (730, 'tanzil-uthmani-v1.1', 5, 61, 'وَإِذَا جَآءُوكُمْ قَالُوٓا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ وَٱللَّهُ أَعْلَمُ بِمَا كَانُوا۟ يَكْتُمُونَ', '4d6f41fd924a6a320c1d7fb3e2eb3f9376040025017736a85a85f8fbc73429d0', 'وَإِذَا جَآءُوكُمْ قَالُوٓا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ وَٱللَّهُ أَعْلَمُ بِمَا كَانُوا۟ يَكْتُمُونَ', '4d6f41fd924a6a320c1d7fb3e2eb3f9376040025017736a85a85f8fbc73429d0', '4d6f41fd924a6a320c1d7fb3e2eb3f9376040025017736a85a85f8fbc73429d0', NULL, 'واذا جاءوكم قالوا ءامنا وقد دخلوا بالكفر وهم قد خرجوا به والله اعلم بما كانوا يكتمون', 6, 12, 47, 1, 2, 118, false, NULL),
    (731, 'tanzil-uthmani-v1.1', 5, 62, 'وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ', 'd2bd11187d99eee0e97384e851ed45d81da3cf8b5ed50370cd8b19219d66a29e', 'وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ', 'd2bd11187d99eee0e97384e851ed45d81da3cf8b5ed50370cd8b19219d66a29e', 'd2bd11187d99eee0e97384e851ed45d81da3cf8b5ed50370cd8b19219d66a29e', NULL, 'وتري كثيرا منهم يسرعون في الاثم والعدون واكلهم السحت لبئس ما كانوا يعملون', 6, 12, 47, 1, 2, 118, false, NULL),
    (732, 'tanzil-uthmani-v1.1', 5, 63, 'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ', '1a51858dd4ed415ac27c174a4831fd8d6fc0f9778a8af227154d4cd89c97c7a0', 'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ', '1a51858dd4ed415ac27c174a4831fd8d6fc0f9778a8af227154d4cd89c97c7a0', '1a51858dd4ed415ac27c174a4831fd8d6fc0f9778a8af227154d4cd89c97c7a0', NULL, 'لولا ينهيهم الربنيون والاحبار عن قولهم الاثم واكلهم السحت لبئس ما كانوا يصنعون', 6, 12, 47, 1, 2, 118, false, NULL),
    (733, 'tanzil-uthmani-v1.1', 5, 64, 'وَقَالَتِ ٱلْيَهُودُ يَدُ ٱللَّهِ مَغْلُولَةٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا۟ بِمَا قَالُوا۟ بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَآءُ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًا وَكُفْرًا وَأَلْقَيْنَا بَيْنَهُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ كُلَّمَآ أَوْقَدُوا۟ نَارًا لِّلْحَرْبِ أَطْفَأَهَا ٱللَّهُ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا وَٱللَّهُ لَا يُحِبُّ ٱلْمُفْسِدِينَ', '03feb121a6d31c57fa6b24c7abad6121089a722cc675da4c01eae48f117339b4', 'وَقَالَتِ ٱلْيَهُودُ يَدُ ٱللَّهِ مَغْلُولَةٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا۟ بِمَا قَالُوا۟ بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَآءُ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًا وَكُفْرًا وَأَلْقَيْنَا بَيْنَهُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ كُلَّمَآ أَوْقَدُوا۟ نَارًا لِّلْحَرْبِ أَطْفَأَهَا ٱللَّهُ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا وَٱللَّهُ لَا يُحِبُّ ٱلْمُفْسِدِينَ', '03feb121a6d31c57fa6b24c7abad6121089a722cc675da4c01eae48f117339b4', '03feb121a6d31c57fa6b24c7abad6121089a722cc675da4c01eae48f117339b4', NULL, 'وقالت اليهود يد الله مغلوله غلت ايديهم ولعنوا بما قالوا بل يداه مبسوطتان ينفق كيف يشاء وليزيدن كثيرا منهم ما انزل اليك من ربك طغينا وكفرا والقينا بينهم العدوه والبغضاء الي يوم القيمه كلما اوقدوا نارا للحرب اطفاها الله ويسعون في الارض فسادا والله لا يحب المفسدين', 6, 12, 47, 1, 2, 118, false, NULL),
    (734, 'tanzil-uthmani-v1.1', 5, 65, 'وَلَوْ أَنَّ أَهْلَ ٱلْكِتَٰبِ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَٰهُمْ جَنَّٰتِ ٱلنَّعِيمِ', '6c2042f4a6fc07bfd382396b814ddb70e39350137c18d630a2fc975de62a96b2', 'وَلَوْ أَنَّ أَهْلَ ٱلْكِتَٰبِ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَٰهُمْ جَنَّٰتِ ٱلنَّعِيمِ', '6c2042f4a6fc07bfd382396b814ddb70e39350137c18d630a2fc975de62a96b2', '6c2042f4a6fc07bfd382396b814ddb70e39350137c18d630a2fc975de62a96b2', NULL, 'ولو ان اهل الكتب ءامنوا واتقوا لكفرنا عنهم سياتهم ولادخلنهم جنت النعيم', 6, 12, 47, 1, 2, 119, false, NULL),
    (735, 'tanzil-uthmani-v1.1', 5, 66, 'وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم مِّنْهُمْ أُمَّةٌ مُّقْتَصِدَةٌ وَكَثِيرٌ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ', '336cc974bb599708e8768a08c261ec69a2266038a49b4652a4020df60924172c', 'وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم مِّنْهُمْ أُمَّةٌ مُّقْتَصِدَةٌ وَكَثِيرٌ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ', '336cc974bb599708e8768a08c261ec69a2266038a49b4652a4020df60924172c', '336cc974bb599708e8768a08c261ec69a2266038a49b4652a4020df60924172c', NULL, 'ولو انهم اقاموا التوريه والانجيل وما انزل اليهم من ربهم لاكلوا من فوقهم ومن تحت ارجلهم منهم امه مقتصده وكثير منهم ساء ما يعملون', 6, 12, 47, 1, 2, 119, false, NULL),
    (736, 'tanzil-uthmani-v1.1', 5, 67, 'يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'e2363d6f59354e996443ec0118b28e6d383aa8767794b8f32b1fa6f06330c794', 'يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'e2363d6f59354e996443ec0118b28e6d383aa8767794b8f32b1fa6f06330c794', 'e2363d6f59354e996443ec0118b28e6d383aa8767794b8f32b1fa6f06330c794', NULL, 'يايها الرسول بلغ ما انزل اليك من ربك وان لم تفعل فما بلغت رسالته والله يعصمك من الناس ان الله لا يهدي القوم الكفرين', 6, 12, 48, 1, 2, 119, false, NULL),
    (737, 'tanzil-uthmani-v1.1', 5, 68, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًا وَكُفْرًا فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '6a323cc5e55f19c794221581da13dfa83b89395f84709197df5d654ae291d921', 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًا وَكُفْرًا فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '6a323cc5e55f19c794221581da13dfa83b89395f84709197df5d654ae291d921', '6a323cc5e55f19c794221581da13dfa83b89395f84709197df5d654ae291d921', NULL, 'قل ياهل الكتب لستم علي شيء حتي تقيموا التوريه والانجيل وما انزل اليكم من ربكم وليزيدن كثيرا منهم ما انزل اليك من ربك طغينا وكفرا فلا تاس علي القوم الكفرين', 6, 12, 48, 1, 2, 119, false, NULL),
    (738, 'tanzil-uthmani-v1.1', 5, 69, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَٰلِحًا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '17fa0ef6d6051eb3da11d83dd436e0c392fa2e539d6514726e3bc2b9f6ab8d89', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَٰلِحًا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '17fa0ef6d6051eb3da11d83dd436e0c392fa2e539d6514726e3bc2b9f6ab8d89', '17fa0ef6d6051eb3da11d83dd436e0c392fa2e539d6514726e3bc2b9f6ab8d89', NULL, 'ان الذين ءامنوا والذين هادوا والصبون والنصري من ءامن بالله واليوم الاخر وعمل صلحا فلا خوف عليهم ولا هم يحزنون', 6, 12, 48, 1, 2, 119, false, NULL),
    (739, 'tanzil-uthmani-v1.1', 5, 70, 'لَقَدْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلًا كُلَّمَا جَآءَهُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُهُمْ فَرِيقًا كَذَّبُوا۟ وَفَرِيقًا يَقْتُلُونَ', 'ed2c198ff0dbc2f09ef078c0d66e014887f4706d0655251f37717e381a9308b7', 'لَقَدْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلًا كُلَّمَا جَآءَهُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُهُمْ فَرِيقًا كَذَّبُوا۟ وَفَرِيقًا يَقْتُلُونَ', 'ed2c198ff0dbc2f09ef078c0d66e014887f4706d0655251f37717e381a9308b7', 'ed2c198ff0dbc2f09ef078c0d66e014887f4706d0655251f37717e381a9308b7', NULL, 'لقد اخذنا ميثق بني اسرءيل وارسلنا اليهم رسلا كلما جاءهم رسول بما لا تهوي انفسهم فريقا كذبوا وفريقا يقتلون', 6, 12, 48, 1, 2, 119, false, NULL),
    (740, 'tanzil-uthmani-v1.1', 5, 71, 'وَحَسِبُوٓا۟ أَلَّا تَكُونَ فِتْنَةٌ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِيرٌ مِّنْهُمْ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', '752efa5bee5bd963330e0e89e749aed5cdad9ed792d62614b039bf264c72f841', 'وَحَسِبُوٓا۟ أَلَّا تَكُونَ فِتْنَةٌ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِيرٌ مِّنْهُمْ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', '752efa5bee5bd963330e0e89e749aed5cdad9ed792d62614b039bf264c72f841', '752efa5bee5bd963330e0e89e749aed5cdad9ed792d62614b039bf264c72f841', NULL, 'وحسبوا الا تكون فتنه فعموا وصموا ثم تاب الله عليهم ثم عموا وصموا كثير منهم والله بصير بما يعملون', 6, 12, 48, 1, 2, 120, false, NULL),
    (741, 'tanzil-uthmani-v1.1', 5, 72, 'لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ وَقَالَ ٱلْمَسِيحُ يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', '64237e9f32fca5c2cdc070b4e0cfda03f0bd05569f9dc8ba69a8e31fbdb8a3a4', 'لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ وَقَالَ ٱلْمَسِيحُ يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', '64237e9f32fca5c2cdc070b4e0cfda03f0bd05569f9dc8ba69a8e31fbdb8a3a4', '64237e9f32fca5c2cdc070b4e0cfda03f0bd05569f9dc8ba69a8e31fbdb8a3a4', NULL, 'لقد كفر الذين قالوا ان الله هو المسيح ابن مريم وقال المسيح يبني اسرءيل اعبدوا الله ربي وربكم انه من يشرك بالله فقد حرم الله عليه الجنه وماويه النار وما للظلمين من انصار', 6, 12, 48, 1, 2, 120, false, NULL),
    (742, 'tanzil-uthmani-v1.1', 5, 73, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٍ وَمَا مِنْ إِلَٰهٍ إِلَّآ إِلَٰهٌ وَٰحِدٌ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', '820a881ea24d432b721f5e00a5bbf17c7f8c9dfb13303dc4f5a20d71b0b995e0', 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٍ وَمَا مِنْ إِلَٰهٍ إِلَّآ إِلَٰهٌ وَٰحِدٌ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', '820a881ea24d432b721f5e00a5bbf17c7f8c9dfb13303dc4f5a20d71b0b995e0', '820a881ea24d432b721f5e00a5bbf17c7f8c9dfb13303dc4f5a20d71b0b995e0', NULL, 'لقد كفر الذين قالوا ان الله ثالث ثلثه وما من اله الا اله وحد وان لم ينتهوا عما يقولون ليمسن الذين كفروا منهم عذاب اليم', 6, 12, 48, 1, 2, 120, false, NULL),
    (743, 'tanzil-uthmani-v1.1', 5, 74, 'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '386353f19055f6e37ac9a5b18d1b65e47c7d4c2d8dadce3cc7a74c8981a59a42', 'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '386353f19055f6e37ac9a5b18d1b65e47c7d4c2d8dadce3cc7a74c8981a59a42', '386353f19055f6e37ac9a5b18d1b65e47c7d4c2d8dadce3cc7a74c8981a59a42', NULL, 'افلا يتوبون الي الله ويستغفرونه والله غفور رحيم', 6, 12, 48, 1, 2, 120, false, NULL),
    (744, 'tanzil-uthmani-v1.1', 5, 75, 'مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْـَٔايَٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ', '4284b5cc43622996fb64fa6f4527ab0f906d0fc37bef6ba5efe88b95fe6348ca', 'مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْـَٔايَٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ', '4284b5cc43622996fb64fa6f4527ab0f906d0fc37bef6ba5efe88b95fe6348ca', '4284b5cc43622996fb64fa6f4527ab0f906d0fc37bef6ba5efe88b95fe6348ca', NULL, 'ما المسيح ابن مريم الا رسول قد خلت من قبله الرسل وامه صديقه كانا ياكلان الطعام انظر كيف نبين لهم الايت ثم انظر اني يؤفكون', 6, 12, 48, 1, 2, 120, false, NULL),
    (745, 'tanzil-uthmani-v1.1', 5, 76, 'قُلْ أَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّا وَلَا نَفْعًا وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '28c086aec44bc47f6645cf03b5da00e7307abdd454715e09da6660e1968707fb', 'قُلْ أَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّا وَلَا نَفْعًا وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '28c086aec44bc47f6645cf03b5da00e7307abdd454715e09da6660e1968707fb', '28c086aec44bc47f6645cf03b5da00e7307abdd454715e09da6660e1968707fb', NULL, 'قل اتعبدون من دون الله ما لا يملك لكم ضرا ولا نفعا والله هو السميع العليم', 6, 12, 48, 1, 2, 120, false, NULL),
    (746, 'tanzil-uthmani-v1.1', 5, 77, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ', '50917514ddb2098157c039c0f5c0970664685f3b854fafd3f2f185bdbf7cf060', 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ', '50917514ddb2098157c039c0f5c0970664685f3b854fafd3f2f185bdbf7cf060', '50917514ddb2098157c039c0f5c0970664685f3b854fafd3f2f185bdbf7cf060', NULL, 'قل ياهل الكتب لا تغلوا في دينكم غير الحق ولا تتبعوا اهواء قوم قد ضلوا من قبل واضلوا كثيرا وضلوا عن سواء السبيل', 6, 12, 48, 1, 2, 121, false, NULL),
    (747, 'tanzil-uthmani-v1.1', 5, 78, 'لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'b06d7e2e4b27036a033d5b7126861f54dd45f39b2d8bdf4d701d1c7444aedf1d', 'لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 'b06d7e2e4b27036a033d5b7126861f54dd45f39b2d8bdf4d701d1c7444aedf1d', 'b06d7e2e4b27036a033d5b7126861f54dd45f39b2d8bdf4d701d1c7444aedf1d', NULL, 'لعن الذين كفروا من بني اسرءيل علي لسان داود وعيسي ابن مريم ذلك بما عصوا وكانوا يعتدون', 6, 12, 48, 1, 2, 121, false, NULL),
    (748, 'tanzil-uthmani-v1.1', 5, 79, 'كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ', '7237256046732761ae11fd25a8aad19ad6fa1fbe841788127511332e2f0ef8f2', 'كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ', '7237256046732761ae11fd25a8aad19ad6fa1fbe841788127511332e2f0ef8f2', '7237256046732761ae11fd25a8aad19ad6fa1fbe841788127511332e2f0ef8f2', NULL, 'كانوا لا يتناهون عن منكر فعلوه لبئس ما كانوا يفعلون', 6, 12, 48, 1, 2, 121, false, NULL),
    (749, 'tanzil-uthmani-v1.1', 5, 80, 'تَرَىٰ كَثِيرًا مِّنْهُمْ يَتَوَلَّوْنَ ٱلَّذِينَ كَفَرُوا۟ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ ٱللَّهُ عَلَيْهِمْ وَفِى ٱلْعَذَابِ هُمْ خَٰلِدُونَ', '22795b4d82bfb6f36c3c88cb3190681b0597c131f5c05f0b1f8cbc65fdf626a1', 'تَرَىٰ كَثِيرًا مِّنْهُمْ يَتَوَلَّوْنَ ٱلَّذِينَ كَفَرُوا۟ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ ٱللَّهُ عَلَيْهِمْ وَفِى ٱلْعَذَابِ هُمْ خَٰلِدُونَ', '22795b4d82bfb6f36c3c88cb3190681b0597c131f5c05f0b1f8cbc65fdf626a1', '22795b4d82bfb6f36c3c88cb3190681b0597c131f5c05f0b1f8cbc65fdf626a1', NULL, 'تري كثيرا منهم يتولون الذين كفروا لبئس ما قدمت لهم انفسهم ان سخط الله عليهم وفي العذاب هم خلدون', 6, 12, 48, 1, 2, 121, false, NULL),
    (750, 'tanzil-uthmani-v1.1', 5, 81, 'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَٰكِنَّ كَثِيرًا مِّنْهُمْ فَٰسِقُونَ', 'd91550145de48f564bcc580c97b63f94bc460b0d86fdb990bce88fb7dbe59a56', 'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَٰكِنَّ كَثِيرًا مِّنْهُمْ فَٰسِقُونَ', 'd91550145de48f564bcc580c97b63f94bc460b0d86fdb990bce88fb7dbe59a56', 'd91550145de48f564bcc580c97b63f94bc460b0d86fdb990bce88fb7dbe59a56', NULL, 'ولو كانوا يؤمنون بالله والنبي وما انزل اليه ما اتخذوهم اولياء ولكن كثيرا منهم فسقون', 6, 12, 48, 1, 2, 121, false, NULL),
    (751, 'tanzil-uthmani-v1.1', 5, 82, 'لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةً لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةً لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ', '53b2847fbb295d1184a97ba4308a3816adc49999c61eb2b65a3c7a91f70c8be5', 'لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةً لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةً لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ', '53b2847fbb295d1184a97ba4308a3816adc49999c61eb2b65a3c7a91f70c8be5', '53b2847fbb295d1184a97ba4308a3816adc49999c61eb2b65a3c7a91f70c8be5', NULL, 'لتجدن اشد الناس عدوه للذين ءامنوا اليهود والذين اشركوا ولتجدن اقربهم موده للذين ءامنوا الذين قالوا انا نصري ذلك بان منهم قسيسين ورهبانا وانهم لا يستكبرون', 7, 13, 49, 1, 2, 121, false, NULL),
    (752, 'tanzil-uthmani-v1.1', 5, 83, 'وَإِذَا سَمِعُوا۟ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ مِمَّا عَرَفُوا۟ مِنَ ٱلْحَقِّ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', '383e0e529ea0661caa386d12056e186789f590d9a81f05ae33dd512e56664190', 'وَإِذَا سَمِعُوا۟ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ مِمَّا عَرَفُوا۟ مِنَ ٱلْحَقِّ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', '383e0e529ea0661caa386d12056e186789f590d9a81f05ae33dd512e56664190', '383e0e529ea0661caa386d12056e186789f590d9a81f05ae33dd512e56664190', NULL, 'واذا سمعوا ما انزل الي الرسول تري اعينهم تفيض من الدمع مما عرفوا من الحق يقولون ربنا ءامنا فاكتبنا مع الشهدين', 7, 13, 49, 1, 2, 122, false, NULL),
    (753, 'tanzil-uthmani-v1.1', 5, 84, 'وَمَا لَنَا لَا نُؤْمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ ٱلْقَوْمِ ٱلصَّٰلِحِينَ', 'b8d806c75ee91b6fea7fc35cd3eab40cccb5a8c462ed8902c1f5c90be415504d', 'وَمَا لَنَا لَا نُؤْمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ ٱلْقَوْمِ ٱلصَّٰلِحِينَ', 'b8d806c75ee91b6fea7fc35cd3eab40cccb5a8c462ed8902c1f5c90be415504d', 'b8d806c75ee91b6fea7fc35cd3eab40cccb5a8c462ed8902c1f5c90be415504d', NULL, 'وما لنا لا نؤمن بالله وما جاءنا من الحق ونطمع ان يدخلنا ربنا مع القوم الصلحين', 7, 13, 49, 1, 2, 122, false, NULL),
    (754, 'tanzil-uthmani-v1.1', 5, 85, 'فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', '9d5d985885765e6b4fc23fb0c9c97c6249a9f25301d5bf1438e283fa8495e9bd', 'فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', '9d5d985885765e6b4fc23fb0c9c97c6249a9f25301d5bf1438e283fa8495e9bd', '9d5d985885765e6b4fc23fb0c9c97c6249a9f25301d5bf1438e283fa8495e9bd', NULL, 'فاثبهم الله بما قالوا جنت تجري من تحتها الانهر خلدين فيها وذلك جزاء المحسنين', 7, 13, 49, 1, 2, 122, false, NULL),
    (755, 'tanzil-uthmani-v1.1', 5, 86, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'c0e50c23b8630f482495f326c92d0a4b13b8d7b1b61807b99350996bb32832b2', 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'c0e50c23b8630f482495f326c92d0a4b13b8d7b1b61807b99350996bb32832b2', 'c0e50c23b8630f482495f326c92d0a4b13b8d7b1b61807b99350996bb32832b2', NULL, 'والذين كفروا وكذبوا بايتنا اولئك اصحب الجحيم', 7, 13, 49, 1, 2, 122, false, NULL),
    (756, 'tanzil-uthmani-v1.1', 5, 87, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', '0a3a987566c4d13068ff808797b7c033a7fd2674f7302917c959fd4d72b331ab', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', '0a3a987566c4d13068ff808797b7c033a7fd2674f7302917c959fd4d72b331ab', '0a3a987566c4d13068ff808797b7c033a7fd2674f7302917c959fd4d72b331ab', NULL, 'يايها الذين ءامنوا لا تحرموا طيبت ما احل الله لكم ولا تعتدوا ان الله لا يحب المعتدين', 7, 13, 49, 1, 2, 122, false, NULL),
    (757, 'tanzil-uthmani-v1.1', 5, 88, 'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًا طَيِّبًا وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', '3a3c8e4549cdb17bd08608f34667b4cee61793c98338aeddf257d4e13bd9971a', 'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًا طَيِّبًا وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', '3a3c8e4549cdb17bd08608f34667b4cee61793c98338aeddf257d4e13bd9971a', '3a3c8e4549cdb17bd08608f34667b4cee61793c98338aeddf257d4e13bd9971a', NULL, 'وكلوا مما رزقكم الله حللا طيبا واتقوا الله الذي انتم به مؤمنون', 7, 13, 49, 1, 2, 122, false, NULL),
    (758, 'tanzil-uthmani-v1.1', 5, 89, 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَٰنَ فَكَفَّٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ ذَٰلِكَ كَفَّٰرَةُ أَيْمَٰنِكُمْ إِذَا حَلَفْتُمْ وَٱحْفَظُوٓا۟ أَيْمَٰنَكُمْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ', '789635ab7f2be42b9113ba712e890f995bab68c1db7b1c8c19f00922aae1cef4', 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَٰنَ فَكَفَّٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ ذَٰلِكَ كَفَّٰرَةُ أَيْمَٰنِكُمْ إِذَا حَلَفْتُمْ وَٱحْفَظُوٓا۟ أَيْمَٰنَكُمْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ', '789635ab7f2be42b9113ba712e890f995bab68c1db7b1c8c19f00922aae1cef4', '789635ab7f2be42b9113ba712e890f995bab68c1db7b1c8c19f00922aae1cef4', NULL, 'لا يؤاخذكم الله باللغو في ايمنكم ولكن يؤاخذكم بما عقدتم الايمن فكفرته اطعام عشره مسكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبه فمن لم يجد فصيام ثلثه ايام ذلك كفره ايمنكم اذا حلفتم واحفظوا ايمنكم كذلك يبين الله لكم ءايته لعلكم تشكرون', 7, 13, 49, 1, 2, 122, false, NULL),
    (759, 'tanzil-uthmani-v1.1', 5, 90, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَٰمُ رِجْسٌ مِّنْ عَمَلِ ٱلشَّيْطَٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ', 'bc59f7323246ac7cb7f700c671222214f1a5f632a2a2400efbf081a5bda2e135', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَٰمُ رِجْسٌ مِّنْ عَمَلِ ٱلشَّيْطَٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ', 'bc59f7323246ac7cb7f700c671222214f1a5f632a2a2400efbf081a5bda2e135', 'bc59f7323246ac7cb7f700c671222214f1a5f632a2a2400efbf081a5bda2e135', NULL, 'يايها الذين ءامنوا انما الخمر والميسر والانصاب والازلم رجس من عمل الشيطن فاجتنبوه لعلكم تفلحون', 7, 13, 49, 1, 2, 123, false, NULL),
    (760, 'tanzil-uthmani-v1.1', 5, 91, 'إِنَّمَا يُرِيدُ ٱلشَّيْطَٰنُ أَن يُوقِعَ بَيْنَكُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ فِى ٱلْخَمْرِ وَٱلْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِ فَهَلْ أَنتُم مُّنتَهُونَ', '79564c28591c1fe83e3cd1e9b3e08e78eb7e38ea95bc155bc18a539841c35d20', 'إِنَّمَا يُرِيدُ ٱلشَّيْطَٰنُ أَن يُوقِعَ بَيْنَكُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ فِى ٱلْخَمْرِ وَٱلْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِ فَهَلْ أَنتُم مُّنتَهُونَ', '79564c28591c1fe83e3cd1e9b3e08e78eb7e38ea95bc155bc18a539841c35d20', '79564c28591c1fe83e3cd1e9b3e08e78eb7e38ea95bc155bc18a539841c35d20', NULL, 'انما يريد الشيطن ان يوقع بينكم العدوه والبغضاء في الخمر والميسر ويصدكم عن ذكر الله وعن الصلوه فهل انتم منتهون', 7, 13, 49, 1, 2, 123, false, NULL),
    (761, 'tanzil-uthmani-v1.1', 5, 92, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', '67767ec6a14518bf9c69e48d9799e56eed2861e2e53a5c1cef8d71f8d3a004bf', 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', '67767ec6a14518bf9c69e48d9799e56eed2861e2e53a5c1cef8d71f8d3a004bf', '67767ec6a14518bf9c69e48d9799e56eed2861e2e53a5c1cef8d71f8d3a004bf', NULL, 'واطيعوا الله واطيعوا الرسول واحذروا فان توليتم فاعلموا انما علي رسولنا البلغ المبين', 7, 13, 49, 1, 2, 123, false, NULL),
    (762, 'tanzil-uthmani-v1.1', 5, 93, 'لَيْسَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جُنَاحٌ فِيمَا طَعِمُوٓا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحْسَنُوا۟ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', '13c9fdb2cfd55dd4a9654df267ec9c7ae38e8585791b790ef892571d2022e390', 'لَيْسَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جُنَاحٌ فِيمَا طَعِمُوٓا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحْسَنُوا۟ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', '13c9fdb2cfd55dd4a9654df267ec9c7ae38e8585791b790ef892571d2022e390', '13c9fdb2cfd55dd4a9654df267ec9c7ae38e8585791b790ef892571d2022e390', NULL, 'ليس علي الذين ءامنوا وعملوا الصلحت جناح فيما طعموا اذا ما اتقوا وءامنوا وعملوا الصلحت ثم اتقوا وءامنوا ثم اتقوا واحسنوا والله يحب المحسنين', 7, 13, 49, 1, 2, 123, false, NULL),
    (763, 'tanzil-uthmani-v1.1', 5, 94, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَيَبْلُوَنَّكُمُ ٱللَّهُ بِشَىْءٍ مِّنَ ٱلصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلْغَيْبِ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', 'a353ce5fecf3d0490d47dfaa2d8bee6b740b351e57f973bed59d069d690190cc', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَيَبْلُوَنَّكُمُ ٱللَّهُ بِشَىْءٍ مِّنَ ٱلصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلْغَيْبِ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ', 'a353ce5fecf3d0490d47dfaa2d8bee6b740b351e57f973bed59d069d690190cc', 'a353ce5fecf3d0490d47dfaa2d8bee6b740b351e57f973bed59d069d690190cc', NULL, 'يايها الذين ءامنوا ليبلونكم الله بشيء من الصيد تناله ايديكم ورماحكم ليعلم الله من يخافه بالغيب فمن اعتدي بعد ذلك فله عذاب اليم', 7, 13, 49, 1, 2, 123, false, NULL),
    (764, 'tanzil-uthmani-v1.1', 5, 95, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْتُلُوا۟ ٱلصَّيْدَ وَأَنتُمْ حُرُمٌ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدًا فَجَزَآءٌ مِّثْلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلٍ مِّنكُمْ هَدْيًۢا بَٰلِغَ ٱلْكَعْبَةِ أَوْ كَفَّٰرَةٌ طَعَامُ مَسَٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًا لِّيَذُوقَ وَبَالَ أَمْرِهِۦ عَفَا ٱللَّهُ عَمَّا سَلَفَ وَمَنْ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنْهُ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', 'b2dc69c47a0d21ff1dd26efe0f5611ffbd79b908d635a725b6f03f2fe23e5bca', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْتُلُوا۟ ٱلصَّيْدَ وَأَنتُمْ حُرُمٌ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدًا فَجَزَآءٌ مِّثْلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلٍ مِّنكُمْ هَدْيًۢا بَٰلِغَ ٱلْكَعْبَةِ أَوْ كَفَّٰرَةٌ طَعَامُ مَسَٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًا لِّيَذُوقَ وَبَالَ أَمْرِهِۦ عَفَا ٱللَّهُ عَمَّا سَلَفَ وَمَنْ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنْهُ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ', 'b2dc69c47a0d21ff1dd26efe0f5611ffbd79b908d635a725b6f03f2fe23e5bca', 'b2dc69c47a0d21ff1dd26efe0f5611ffbd79b908d635a725b6f03f2fe23e5bca', NULL, 'يايها الذين ءامنوا لا تقتلوا الصيد وانتم حرم ومن قتله منكم متعمدا فجزاء مثل ما قتل من النعم يحكم به ذوا عدل منكم هديا بلغ الكعبه او كفره طعام مسكين او عدل ذلك صياما ليذوق وبال امره عفا الله عما سلف ومن عاد فينتقم الله منه والله عزيز ذو انتقام', 7, 13, 49, 1, 2, 123, false, NULL),
    (765, 'tanzil-uthmani-v1.1', 5, 96, 'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَٰعًا لَّكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًا وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', '5b5d3b7d0a5d8e5d2d58555005bd83770d9989f5aa8279c3cc3927682a7421d7', 'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَٰعًا لَّكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًا وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', '5b5d3b7d0a5d8e5d2d58555005bd83770d9989f5aa8279c3cc3927682a7421d7', '5b5d3b7d0a5d8e5d2d58555005bd83770d9989f5aa8279c3cc3927682a7421d7', NULL, 'احل لكم صيد البحر وطعامه متعا لكم وللسياره وحرم عليكم صيد البر ما دمتم حرما واتقوا الله الذي اليه تحشرون', 7, 13, 49, 1, 2, 124, false, NULL),
    (766, 'tanzil-uthmani-v1.1', 5, 97, 'جَعَلَ ٱللَّهُ ٱلْكَعْبَةَ ٱلْبَيْتَ ٱلْحَرَامَ قِيَٰمًا لِّلنَّاسِ وَٱلشَّهْرَ ٱلْحَرَامَ وَٱلْهَدْىَ وَٱلْقَلَٰٓئِدَ ذَٰلِكَ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'dc8f9aa47d847351b7d8798b5bf2322994b65dc9867434f1a1b26420a23181fa', 'جَعَلَ ٱللَّهُ ٱلْكَعْبَةَ ٱلْبَيْتَ ٱلْحَرَامَ قِيَٰمًا لِّلنَّاسِ وَٱلشَّهْرَ ٱلْحَرَامَ وَٱلْهَدْىَ وَٱلْقَلَٰٓئِدَ ذَٰلِكَ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'dc8f9aa47d847351b7d8798b5bf2322994b65dc9867434f1a1b26420a23181fa', 'dc8f9aa47d847351b7d8798b5bf2322994b65dc9867434f1a1b26420a23181fa', NULL, 'جعل الله الكعبه البيت الحرام قيما للناس والشهر الحرام والهدي والقلئد ذلك لتعلموا ان الله يعلم ما في السموت وما في الارض وان الله بكل شيء عليم', 7, 13, 50, 1, 2, 124, false, NULL),
    (767, 'tanzil-uthmani-v1.1', 5, 98, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '5ec4ec966a48c9aa89299437e9b6cf9607c10283ebe6c77b72ace5ed345f824a', 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '5ec4ec966a48c9aa89299437e9b6cf9607c10283ebe6c77b72ace5ed345f824a', '5ec4ec966a48c9aa89299437e9b6cf9607c10283ebe6c77b72ace5ed345f824a', NULL, 'اعلموا ان الله شديد العقاب وان الله غفور رحيم', 7, 13, 50, 1, 2, 124, false, NULL),
    (768, 'tanzil-uthmani-v1.1', 5, 99, 'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'b5b8253dd11b4476e9267551618b2dd691631f2fbd1ce01ea69e52e050e8e7ce', 'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 'b5b8253dd11b4476e9267551618b2dd691631f2fbd1ce01ea69e52e050e8e7ce', 'b5b8253dd11b4476e9267551618b2dd691631f2fbd1ce01ea69e52e050e8e7ce', NULL, 'ما علي الرسول الا البلغ والله يعلم ما تبدون وما تكتمون', 7, 13, 50, 1, 2, 124, false, NULL),
    (769, 'tanzil-uthmani-v1.1', 5, 100, 'قُل لَّا يَسْتَوِى ٱلْخَبِيثُ وَٱلطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ ٱلْخَبِيثِ فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تُفْلِحُونَ', '00f944b59c38ec9ff5c8077a54f94748b7226ffd7bcdf8bce4da01e86443b783', 'قُل لَّا يَسْتَوِى ٱلْخَبِيثُ وَٱلطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ ٱلْخَبِيثِ فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تُفْلِحُونَ', '00f944b59c38ec9ff5c8077a54f94748b7226ffd7bcdf8bce4da01e86443b783', '00f944b59c38ec9ff5c8077a54f94748b7226ffd7bcdf8bce4da01e86443b783', NULL, 'قل لا يستوي الخبيث والطيب ولو اعجبك كثره الخبيث فاتقوا الله ياولي الالبب لعلكم تفلحون', 7, 13, 50, 1, 2, 124, false, NULL),
    (770, 'tanzil-uthmani-v1.1', 5, 101, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْـَٔلُوا۟ عَنْهَا حِينَ يُنَزَّلُ ٱلْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ٱللَّهُ عَنْهَا وَٱللَّهُ غَفُورٌ حَلِيمٌ', '9524f41bd240ccbbec8d9a154558df3185a4ac727285e2a49fa709b06b4d09b5', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْـَٔلُوا۟ عَنْهَا حِينَ يُنَزَّلُ ٱلْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ٱللَّهُ عَنْهَا وَٱللَّهُ غَفُورٌ حَلِيمٌ', '9524f41bd240ccbbec8d9a154558df3185a4ac727285e2a49fa709b06b4d09b5', '9524f41bd240ccbbec8d9a154558df3185a4ac727285e2a49fa709b06b4d09b5', NULL, 'يايها الذين ءامنوا لا تسلوا عن اشياء ان تبد لكم تسؤكم وان تسلوا عنها حين ينزل القرءان تبد لكم عفا الله عنها والله غفور حليم', 7, 13, 50, 1, 2, 124, false, NULL),
    (771, 'tanzil-uthmani-v1.1', 5, 102, 'قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَٰفِرِينَ', 'e7ac24e4ab11bfec7aca8a80aa5184272405c415aba4889994fb7e2c3f1d1174', 'قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَٰفِرِينَ', 'e7ac24e4ab11bfec7aca8a80aa5184272405c415aba4889994fb7e2c3f1d1174', 'e7ac24e4ab11bfec7aca8a80aa5184272405c415aba4889994fb7e2c3f1d1174', NULL, 'قد سالها قوم من قبلكم ثم اصبحوا بها كفرين', 7, 13, 50, 1, 2, 124, false, NULL),
    (772, 'tanzil-uthmani-v1.1', 5, 103, 'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٍ وَلَا سَآئِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُوا۟ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ', '7ef8b750c8878e9df756495cf2ccd7c7c3798990d7f2234ff70e55268b7557cd', 'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٍ وَلَا سَآئِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُوا۟ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ', '7ef8b750c8878e9df756495cf2ccd7c7c3798990d7f2234ff70e55268b7557cd', '7ef8b750c8878e9df756495cf2ccd7c7c3798990d7f2234ff70e55268b7557cd', NULL, 'ما جعل الله من بحيره ولا سائبه ولا وصيله ولا حام ولكن الذين كفروا يفترون علي الله الكذب واكثرهم لا يعقلون', 7, 13, 50, 1, 2, 124, false, NULL),
    (773, 'tanzil-uthmani-v1.1', 5, 104, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', 'ac3f7b7138b3e772fef2473d6ff0a114e1b42da9830968484cf6ddcd361f06ca', 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًٔا وَلَا يَهْتَدُونَ', 'ac3f7b7138b3e772fef2473d6ff0a114e1b42da9830968484cf6ddcd361f06ca', 'ac3f7b7138b3e772fef2473d6ff0a114e1b42da9830968484cf6ddcd361f06ca', NULL, 'واذا قيل لهم تعالوا الي ما انزل الله والي الرسول قالوا حسبنا ما وجدنا عليه ءاباءنا اولو كان ءاباؤهم لا يعلمون شيا ولا يهتدون', 7, 13, 50, 1, 2, 125, false, NULL),
    (774, 'tanzil-uthmani-v1.1', 5, 105, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ عَلَيْكُمْ أَنفُسَكُمْ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '1befbfb182abd6037b5856fbee8cbd16742ea6ff97682c96d6060aad33fed5b9', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ عَلَيْكُمْ أَنفُسَكُمْ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '1befbfb182abd6037b5856fbee8cbd16742ea6ff97682c96d6060aad33fed5b9', '1befbfb182abd6037b5856fbee8cbd16742ea6ff97682c96d6060aad33fed5b9', NULL, 'يايها الذين ءامنوا عليكم انفسكم لا يضركم من ضل اذا اهتديتم الي الله مرجعكم جميعا فينبئكم بما كنتم تعملون', 7, 13, 50, 1, 2, 125, false, NULL),
    (775, 'tanzil-uthmani-v1.1', 5, 106, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ شَهَٰدَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍ مِّنكُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِى ٱلْأَرْضِ فَأَصَٰبَتْكُم مُّصِيبَةُ ٱلْمَوْتِ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ٱلصَّلَوٰةِ فَيُقْسِمَانِ بِٱللَّهِ إِنِ ٱرْتَبْتُمْ لَا نَشْتَرِى بِهِۦ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَىٰ وَلَا نَكْتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذًا لَّمِنَ ٱلْـَٔاثِمِينَ', '4efe82091471fc63c67599053397bb0091aa35d579d02ec683763fba70047ae6', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ شَهَٰدَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍ مِّنكُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِى ٱلْأَرْضِ فَأَصَٰبَتْكُم مُّصِيبَةُ ٱلْمَوْتِ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ٱلصَّلَوٰةِ فَيُقْسِمَانِ بِٱللَّهِ إِنِ ٱرْتَبْتُمْ لَا نَشْتَرِى بِهِۦ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَىٰ وَلَا نَكْتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذًا لَّمِنَ ٱلْـَٔاثِمِينَ', '4efe82091471fc63c67599053397bb0091aa35d579d02ec683763fba70047ae6', '4efe82091471fc63c67599053397bb0091aa35d579d02ec683763fba70047ae6', NULL, 'يايها الذين ءامنوا شهده بينكم اذا حضر احدكم الموت حين الوصيه اثنان ذوا عدل منكم او ءاخران من غيركم ان انتم ضربتم في الارض فاصبتكم مصيبه الموت تحبسونهما من بعد الصلوه فيقسمان بالله ان ارتبتم لا نشتري به ثمنا ولو كان ذا قربي ولا نكتم شهده الله انا اذا لمن الاثمين', 7, 13, 50, 1, 2, 125, false, NULL),
    (776, 'tanzil-uthmani-v1.1', 5, 107, 'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسْتَحَقَّآ إِثْمًا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسْتَحَقَّ عَلَيْهِمُ ٱلْأَوْلَيَٰنِ فَيُقْسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعْتَدَيْنَآ إِنَّآ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'd5b0f96fc33ea7875df2ac457ce70774626bb90cb3e0189d555f3875c61b2898', 'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسْتَحَقَّآ إِثْمًا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسْتَحَقَّ عَلَيْهِمُ ٱلْأَوْلَيَٰنِ فَيُقْسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعْتَدَيْنَآ إِنَّآ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'd5b0f96fc33ea7875df2ac457ce70774626bb90cb3e0189d555f3875c61b2898', 'd5b0f96fc33ea7875df2ac457ce70774626bb90cb3e0189d555f3875c61b2898', NULL, 'فان عثر علي انهما استحقا اثما فاخران يقومان مقامهما من الذين استحق عليهم الاولين فيقسمان بالله لشهدتنا احق من شهدتهما وما اعتدينا انا اذا لمن الظلمين', 7, 13, 50, 1, 2, 125, false, NULL),
    (777, 'tanzil-uthmani-v1.1', 5, 108, 'ذَٰلِكَ أَدْنَىٰٓ أَن يَأْتُوا۟ بِٱلشَّهَٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓا۟ أَن تُرَدَّ أَيْمَٰنٌۢ بَعْدَ أَيْمَٰنِهِمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱسْمَعُوا۟ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'a8ffd7b0784e460f542d112d3144b84a71812b62f6147ea3b53561abdad85837', 'ذَٰلِكَ أَدْنَىٰٓ أَن يَأْتُوا۟ بِٱلشَّهَٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓا۟ أَن تُرَدَّ أَيْمَٰنٌۢ بَعْدَ أَيْمَٰنِهِمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱسْمَعُوا۟ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'a8ffd7b0784e460f542d112d3144b84a71812b62f6147ea3b53561abdad85837', 'a8ffd7b0784e460f542d112d3144b84a71812b62f6147ea3b53561abdad85837', NULL, 'ذلك ادني ان ياتوا بالشهده علي وجهها او يخافوا ان ترد ايمن بعد ايمنهم واتقوا الله واسمعوا والله لا يهدي القوم الفسقين', 7, 13, 50, 1, 2, 125, false, NULL),
    (778, 'tanzil-uthmani-v1.1', 5, 109, 'يَوْمَ يَجْمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ قَالُوا۟ لَا عِلْمَ لَنَآ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', '5f20346cd675ffc495ac8fdf2ca4ed610e427bd8b865dd4041b80de456c9bac3', 'يَوْمَ يَجْمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ قَالُوا۟ لَا عِلْمَ لَنَآ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', '5f20346cd675ffc495ac8fdf2ca4ed610e427bd8b865dd4041b80de456c9bac3', '5f20346cd675ffc495ac8fdf2ca4ed610e427bd8b865dd4041b80de456c9bac3', NULL, 'يوم يجمع الله الرسل فيقول ماذا اجبتم قالوا لا علم لنا انك انت علم الغيوب', 7, 13, 51, 1, 2, 126, false, NULL),
    (779, 'tanzil-uthmani-v1.1', 5, 110, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ٱذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ ٱلْقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَإِذْ عَلَّمْتُكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَإِذْ تَخْلُقُ مِنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ بِإِذْنِى فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًۢا بِإِذْنِى وَتُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ بِإِذْنِى وَإِذْ تُخْرِجُ ٱلْمَوْتَىٰ بِإِذْنِى وَإِذْ كَفَفْتُ بَنِىٓ إِسْرَٰٓءِيلَ عَنكَ إِذْ جِئْتَهُم بِٱلْبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'cda3615a0b9a9f7c1f56c1813e1ec119f4e7bc122766fd355897c59b24dea4a8', 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ٱذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ ٱلْقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا وَإِذْ عَلَّمْتُكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَإِذْ تَخْلُقُ مِنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ بِإِذْنِى فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًۢا بِإِذْنِى وَتُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ بِإِذْنِى وَإِذْ تُخْرِجُ ٱلْمَوْتَىٰ بِإِذْنِى وَإِذْ كَفَفْتُ بَنِىٓ إِسْرَٰٓءِيلَ عَنكَ إِذْ جِئْتَهُم بِٱلْبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'cda3615a0b9a9f7c1f56c1813e1ec119f4e7bc122766fd355897c59b24dea4a8', 'cda3615a0b9a9f7c1f56c1813e1ec119f4e7bc122766fd355897c59b24dea4a8', NULL, 'اذ قال الله يعيسي ابن مريم اذكر نعمتي عليك وعلي ولدتك اذ ايدتك بروح القدس تكلم الناس في المهد وكهلا واذ علمتك الكتب والحكمه والتوريه والانجيل واذ تخلق من الطين كهيه الطير باذني فتنفخ فيها فتكون طيرا باذني وتبرئ الاكمه والابرص باذني واذ تخرج الموتي باذني واذ كففت بني اسرءيل عنك اذ جئتهم بالبينت فقال الذين كفروا منهم ان هذا الا سحر مبين', 7, 13, 51, 1, 2, 126, false, NULL),
    (780, 'tanzil-uthmani-v1.1', 5, 111, 'وَإِذْ أَوْحَيْتُ إِلَى ٱلْحَوَارِيِّـۧنَ أَنْ ءَامِنُوا۟ بِى وَبِرَسُولِى قَالُوٓا۟ ءَامَنَّا وَٱشْهَدْ بِأَنَّنَا مُسْلِمُونَ', '52c8542afe4217cb25102db1d153b9a45d8ae917e39c40880d6de99126c1e9c3', 'وَإِذْ أَوْحَيْتُ إِلَى ٱلْحَوَارِيِّـۧنَ أَنْ ءَامِنُوا۟ بِى وَبِرَسُولِى قَالُوٓا۟ ءَامَنَّا وَٱشْهَدْ بِأَنَّنَا مُسْلِمُونَ', '52c8542afe4217cb25102db1d153b9a45d8ae917e39c40880d6de99126c1e9c3', '52c8542afe4217cb25102db1d153b9a45d8ae917e39c40880d6de99126c1e9c3', NULL, 'واذ اوحيت الي الحوارين ان ءامنوا بي وبرسولي قالوا ءامنا واشهد باننا مسلمون', 7, 13, 51, 1, 2, 126, false, NULL),
    (781, 'tanzil-uthmani-v1.1', 5, 112, 'إِذْ قَالَ ٱلْحَوَارِيُّونَ يَٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', '22329bbf6c3b4bb2c1a4133a0246efc2adf9187ffe2992957e1d718851cc6c49', 'إِذْ قَالَ ٱلْحَوَارِيُّونَ يَٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', '22329bbf6c3b4bb2c1a4133a0246efc2adf9187ffe2992957e1d718851cc6c49', '22329bbf6c3b4bb2c1a4133a0246efc2adf9187ffe2992957e1d718851cc6c49', NULL, 'اذ قال الحواريون يعيسي ابن مريم هل يستطيع ربك ان ينزل علينا مائده من السماء قال اتقوا الله ان كنتم مؤمنين', 7, 13, 51, 1, 2, 126, false, NULL),
    (782, 'tanzil-uthmani-v1.1', 5, 113, 'قَالُوا۟ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ٱلشَّٰهِدِينَ', 'b18a503803889ca19b7bafcb36a886c69659453396f3692721386134fc0d38d1', 'قَالُوا۟ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ٱلشَّٰهِدِينَ', 'b18a503803889ca19b7bafcb36a886c69659453396f3692721386134fc0d38d1', 'b18a503803889ca19b7bafcb36a886c69659453396f3692721386134fc0d38d1', NULL, 'قالوا نريد ان ناكل منها وتطمئن قلوبنا ونعلم ان قد صدقتنا ونكون عليها من الشهدين', 7, 13, 51, 1, 2, 126, false, NULL),
    (783, 'tanzil-uthmani-v1.1', 5, 114, 'قَالَ عِيسَى ٱبْنُ مَرْيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةً مِّنكَ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ', '8ac9ffddd466395f8c0f9e6b55969abca06f56d370d3b2dca5253f3b274e3405', 'قَالَ عِيسَى ٱبْنُ مَرْيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةً مِّنكَ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ', '8ac9ffddd466395f8c0f9e6b55969abca06f56d370d3b2dca5253f3b274e3405', '8ac9ffddd466395f8c0f9e6b55969abca06f56d370d3b2dca5253f3b274e3405', NULL, 'قال عيسي ابن مريم اللهم ربنا انزل علينا مائده من السماء تكون لنا عيدا لاولنا وءاخرنا وءايه منك وارزقنا وانت خير الرزقين', 7, 13, 51, 1, 2, 127, false, NULL),
    (784, 'tanzil-uthmani-v1.1', 5, 115, 'قَالَ ٱللَّهُ إِنِّى مُنَزِّلُهَا عَلَيْكُمْ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّىٓ أُعَذِّبُهُۥ عَذَابًا لَّآ أُعَذِّبُهُۥٓ أَحَدًا مِّنَ ٱلْعَٰلَمِينَ', 'aa142ae31061a24440b60bfbf55ba493d0ea02ebdd7e8825c55d08b3999f936b', 'قَالَ ٱللَّهُ إِنِّى مُنَزِّلُهَا عَلَيْكُمْ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّىٓ أُعَذِّبُهُۥ عَذَابًا لَّآ أُعَذِّبُهُۥٓ أَحَدًا مِّنَ ٱلْعَٰلَمِينَ', 'aa142ae31061a24440b60bfbf55ba493d0ea02ebdd7e8825c55d08b3999f936b', 'aa142ae31061a24440b60bfbf55ba493d0ea02ebdd7e8825c55d08b3999f936b', NULL, 'قال الله اني منزلها عليكم فمن يكفر بعد منكم فاني اعذبه عذابا لا اعذبه احدا من العلمين', 7, 13, 51, 1, 2, 127, false, NULL),
    (785, 'tanzil-uthmani-v1.1', 5, 116, 'وَإِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَٰهَيْنِ مِن دُونِ ٱللَّهِ قَالَ سُبْحَٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', '351b065f327cfce9ca1da2492eef9d262130f4da0089bf2183fcc80863f2a599', 'وَإِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَٰهَيْنِ مِن دُونِ ٱللَّهِ قَالَ سُبْحَٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', '351b065f327cfce9ca1da2492eef9d262130f4da0089bf2183fcc80863f2a599', '351b065f327cfce9ca1da2492eef9d262130f4da0089bf2183fcc80863f2a599', NULL, 'واذ قال الله يعيسي ابن مريم ءانت قلت للناس اتخذوني وامي الهين من دون الله قال سبحنك ما يكون لي ان اقول ما ليس لي بحق ان كنت قلته فقد علمته تعلم ما في نفسي ولا اعلم ما في نفسك انك انت علم الغيوب', 7, 13, 51, 1, 2, 127, false, NULL),
    (786, 'tanzil-uthmani-v1.1', 5, 117, 'مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '1fa0df12e90a48a4981ed31b6cb14a688c42adeeafacd5194db5b34063016698', 'مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '1fa0df12e90a48a4981ed31b6cb14a688c42adeeafacd5194db5b34063016698', '1fa0df12e90a48a4981ed31b6cb14a688c42adeeafacd5194db5b34063016698', NULL, 'ما قلت لهم الا ما امرتني به ان اعبدوا الله ربي وربكم وكنت عليهم شهيدا ما دمت فيهم فلما توفيتني كنت انت الرقيب عليهم وانت علي كل شيء شهيد', 7, 13, 51, 1, 2, 127, false, NULL),
    (787, 'tanzil-uthmani-v1.1', 5, 118, 'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'cb7a778a5627723d7d3c720215c104413227872fff9b397d1066615135d06e51', 'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'cb7a778a5627723d7d3c720215c104413227872fff9b397d1066615135d06e51', 'cb7a778a5627723d7d3c720215c104413227872fff9b397d1066615135d06e51', NULL, 'ان تعذبهم فانهم عبادك وان تغفر لهم فانك انت العزيز الحكيم', 7, 13, 51, 1, 2, 127, false, NULL),
    (788, 'tanzil-uthmani-v1.1', 5, 119, 'قَالَ ٱللَّهُ هَٰذَا يَوْمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدْقُهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '36787aa97fc4a5bb7465d60426fe87c55e28b4f77b73a661420bc644cbf3f50e', 'قَالَ ٱللَّهُ هَٰذَا يَوْمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدْقُهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '36787aa97fc4a5bb7465d60426fe87c55e28b4f77b73a661420bc644cbf3f50e', '36787aa97fc4a5bb7465d60426fe87c55e28b4f77b73a661420bc644cbf3f50e', NULL, 'قال الله هذا يوم ينفع الصدقين صدقهم لهم جنت تجري من تحتها الانهر خلدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك الفوز العظيم', 7, 13, 51, 1, 2, 127, false, NULL),
    (789, 'tanzil-uthmani-v1.1', 5, 120, 'لِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا فِيهِنَّ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌۢ', '23fd78acac999d5c47fd81b67ee5a65ce67f15770a533a34ee933a5d7caaa538', 'لِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا فِيهِنَّ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌۢ', '23fd78acac999d5c47fd81b67ee5a65ce67f15770a533a34ee933a5d7caaa538', '23fd78acac999d5c47fd81b67ee5a65ce67f15770a533a34ee933a5d7caaa538', NULL, 'لله ملك السموت والارض وما فيهن وهو علي كل شيء قدير', 7, 13, 51, 1, 2, 127, false, NULL),
    (790, 'tanzil-uthmani-v1.1', 6, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ', '4e2633ffdb98f390569b431f7935ee7575b8c08776248b77cff4b899955b466d', 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ', '953fe64bc658bba920bb6c47593b52c3afafebd4c7069929dc58fcdd847f2152', '953fe64bc658bba920bb6c47593b52c3afafebd4c7069929dc58fcdd847f2152', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الحمد لله الذي خلق السموت والارض وجعل الظلمت والنور ثم الذين كفروا بربهم يعدلون', 7, 13, 51, 1, 2, 128, false, NULL),
    (791, 'tanzil-uthmani-v1.1', 6, 2, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍ ثُمَّ قَضَىٰٓ أَجَلًا وَأَجَلٌ مُّسَمًّى عِندَهُۥ ثُمَّ أَنتُمْ تَمْتَرُونَ', '42e77469d343829b9270c5717a6b79878518a4cad09bb31c923f6215b866f75a', 'هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍ ثُمَّ قَضَىٰٓ أَجَلًا وَأَجَلٌ مُّسَمًّى عِندَهُۥ ثُمَّ أَنتُمْ تَمْتَرُونَ', '42e77469d343829b9270c5717a6b79878518a4cad09bb31c923f6215b866f75a', '42e77469d343829b9270c5717a6b79878518a4cad09bb31c923f6215b866f75a', NULL, 'هو الذي خلقكم من طين ثم قضي اجلا واجل مسمي عنده ثم انتم تمترون', 7, 13, 51, 1, 2, 128, false, NULL),
    (792, 'tanzil-uthmani-v1.1', 6, 3, 'وَهُوَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَفِى ٱلْأَرْضِ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ', '0d61400db28cbb267789ea29702821d94e27eedd504091e504aff2089855cd43', 'وَهُوَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَفِى ٱلْأَرْضِ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ', '0d61400db28cbb267789ea29702821d94e27eedd504091e504aff2089855cd43', '0d61400db28cbb267789ea29702821d94e27eedd504091e504aff2089855cd43', NULL, 'وهو الله في السموت وفي الارض يعلم سركم وجهركم ويعلم ما تكسبون', 7, 13, 51, 1, 2, 128, false, NULL),
    (793, 'tanzil-uthmani-v1.1', 6, 4, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', '819974d447708c55311f9c1e09ab62d776a4be56d1e9e6f7ac584b08996326a2', 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', '819974d447708c55311f9c1e09ab62d776a4be56d1e9e6f7ac584b08996326a2', '819974d447708c55311f9c1e09ab62d776a4be56d1e9e6f7ac584b08996326a2', NULL, 'وما تاتيهم من ءايه من ءايت ربهم الا كانوا عنها معرضين', 7, 13, 51, 1, 2, 128, false, NULL),
    (794, 'tanzil-uthmani-v1.1', 6, 5, 'فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَسَوْفَ يَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '75490cb4b6d63806cd80a2933e7fed15913751de8a7698bc1aebd89c2d4ce79a', 'فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَسَوْفَ يَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '75490cb4b6d63806cd80a2933e7fed15913751de8a7698bc1aebd89c2d4ce79a', '75490cb4b6d63806cd80a2933e7fed15913751de8a7698bc1aebd89c2d4ce79a', NULL, 'فقد كذبوا بالحق لما جاءهم فسوف ياتيهم انبؤا ما كانوا به يستهزءون', 7, 13, 51, 1, 2, 128, false, NULL),
    (795, 'tanzil-uthmani-v1.1', 6, 6, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًا وَجَعَلْنَا ٱلْأَنْهَٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', '6c67397e21f6e60308c040c533e1ef94cd406f4371c4d48c196b2e006c0b1994', 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًا وَجَعَلْنَا ٱلْأَنْهَٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', '6c67397e21f6e60308c040c533e1ef94cd406f4371c4d48c196b2e006c0b1994', '6c67397e21f6e60308c040c533e1ef94cd406f4371c4d48c196b2e006c0b1994', NULL, 'الم يروا كم اهلكنا من قبلهم من قرن مكنهم في الارض ما لم نمكن لكم وارسلنا السماء عليهم مدرارا وجعلنا الانهر تجري من تحتهم فاهلكنهم بذنوبهم وانشانا من بعدهم قرنا ءاخرين', 7, 13, 51, 1, 2, 128, false, NULL),
    (796, 'tanzil-uthmani-v1.1', 6, 7, 'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَٰبًا فِى قِرْطَاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', '797343c25fca92f9949376ad30be85a2b9e71d664d18829b97f342b2081d927e', 'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَٰبًا فِى قِرْطَاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', '797343c25fca92f9949376ad30be85a2b9e71d664d18829b97f342b2081d927e', '797343c25fca92f9949376ad30be85a2b9e71d664d18829b97f342b2081d927e', NULL, 'ولو نزلنا عليك كتبا في قرطاس فلمسوه بايديهم لقال الذين كفروا ان هذا الا سحر مبين', 7, 13, 51, 1, 2, 128, false, NULL),
    (797, 'tanzil-uthmani-v1.1', 6, 8, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌ وَلَوْ أَنزَلْنَا مَلَكًا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ', '1fac97f341117518e23cf1c931e7e35b42bc05ee19205a5c13c8432d3eafe126', 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌ وَلَوْ أَنزَلْنَا مَلَكًا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ', '1fac97f341117518e23cf1c931e7e35b42bc05ee19205a5c13c8432d3eafe126', '1fac97f341117518e23cf1c931e7e35b42bc05ee19205a5c13c8432d3eafe126', NULL, 'وقالوا لولا انزل عليه ملك ولو انزلنا ملكا لقضي الامر ثم لا ينظرون', 7, 13, 51, 1, 2, 128, false, NULL),
    (798, 'tanzil-uthmani-v1.1', 6, 9, 'وَلَوْ جَعَلْنَٰهُ مَلَكًا لَّجَعَلْنَٰهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ', 'f5a6d33dede52d55e61eb67c32eaa09cd91fcaaa226a8950c835dd729c0c91c5', 'وَلَوْ جَعَلْنَٰهُ مَلَكًا لَّجَعَلْنَٰهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ', 'f5a6d33dede52d55e61eb67c32eaa09cd91fcaaa226a8950c835dd729c0c91c5', 'f5a6d33dede52d55e61eb67c32eaa09cd91fcaaa226a8950c835dd729c0c91c5', NULL, 'ولو جعلنه ملكا لجعلنه رجلا وللبسنا عليهم ما يلبسون', 7, 13, 51, 1, 2, 129, false, NULL),
    (799, 'tanzil-uthmani-v1.1', 6, 10, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'c26ef020836af375cca527f6e1683337d66425da65ce922fe53f8e4f76866e36', 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'c26ef020836af375cca527f6e1683337d66425da65ce922fe53f8e4f76866e36', 'c26ef020836af375cca527f6e1683337d66425da65ce922fe53f8e4f76866e36', NULL, 'ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزءون', 7, 13, 51, 1, 2, 129, false, NULL),
    (800, 'tanzil-uthmani-v1.1', 6, 11, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', '71492edf279030a6e2888a746ef149c5f99796430c7943def9352793113e2ccb', 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', '71492edf279030a6e2888a746ef149c5f99796430c7943def9352793113e2ccb', '71492edf279030a6e2888a746ef149c5f99796430c7943def9352793113e2ccb', NULL, 'قل سيروا في الارض ثم انظروا كيف كان عقبه المكذبين', 7, 13, 51, 1, 2, 129, false, NULL),
    (801, 'tanzil-uthmani-v1.1', 6, 12, 'قُل لِّمَن مَّا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُل لِّلَّهِ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', '5b0353afba1b258a7e94745e82dd1fde2c4eccb86e7fb5ec41cafbaeb88deb74', 'قُل لِّمَن مَّا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُل لِّلَّهِ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', '5b0353afba1b258a7e94745e82dd1fde2c4eccb86e7fb5ec41cafbaeb88deb74', '5b0353afba1b258a7e94745e82dd1fde2c4eccb86e7fb5ec41cafbaeb88deb74', NULL, 'قل لمن ما في السموت والارض قل لله كتب علي نفسه الرحمه ليجمعنكم الي يوم القيمه لا ريب فيه الذين خسروا انفسهم فهم لا يؤمنون', 7, 13, 51, 1, 2, 129, false, NULL),
    (802, 'tanzil-uthmani-v1.1', 6, 13, 'وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '541bc8bbf858f74abf2abb840435453361972b84984d0d8187bebc5ba9d3c36e', 'وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '541bc8bbf858f74abf2abb840435453361972b84984d0d8187bebc5ba9d3c36e', '541bc8bbf858f74abf2abb840435453361972b84984d0d8187bebc5ba9d3c36e', NULL, 'وله ما سكن في اليل والنهار وهو السميع العليم', 7, 13, 52, 1, 2, 129, false, NULL),
    (803, 'tanzil-uthmani-v1.1', 6, 14, 'قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', '5f949e36988ec8e59ed2abcef558f191ee59cd96ef94229b04bc2b4f647a9edb', 'قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', '5f949e36988ec8e59ed2abcef558f191ee59cd96ef94229b04bc2b4f647a9edb', '5f949e36988ec8e59ed2abcef558f191ee59cd96ef94229b04bc2b4f647a9edb', NULL, 'قل اغير الله اتخذ وليا فاطر السموت والارض وهو يطعم ولا يطعم قل اني امرت ان اكون اول من اسلم ولا تكونن من المشركين', 7, 13, 52, 1, 2, 129, false, NULL),
    (804, 'tanzil-uthmani-v1.1', 6, 15, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'f06309ac89f947b69e5580500c3c2361ffa81838839304310e2fea2130c7f193', 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'f06309ac89f947b69e5580500c3c2361ffa81838839304310e2fea2130c7f193', 'f06309ac89f947b69e5580500c3c2361ffa81838839304310e2fea2130c7f193', NULL, 'قل اني اخاف ان عصيت ربي عذاب يوم عظيم', 7, 13, 52, 1, 2, 129, false, NULL),
    (805, 'tanzil-uthmani-v1.1', 6, 16, 'مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۥ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ', 'd0007b6c1f835f6b527420a87d28897830475dd660fa1beedc7b3d743612de73', 'مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۥ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ', 'd0007b6c1f835f6b527420a87d28897830475dd660fa1beedc7b3d743612de73', 'd0007b6c1f835f6b527420a87d28897830475dd660fa1beedc7b3d743612de73', NULL, 'من يصرف عنه يومئذ فقد رحمه وذلك الفوز المبين', 7, 13, 52, 1, 2, 129, false, NULL),
    (806, 'tanzil-uthmani-v1.1', 6, 17, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '3845da95387cd6b52a49c535505048938b674b644289acea0842830f98110b4c', 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '3845da95387cd6b52a49c535505048938b674b644289acea0842830f98110b4c', '3845da95387cd6b52a49c535505048938b674b644289acea0842830f98110b4c', NULL, 'وان يمسسك الله بضر فلا كاشف له الا هو وان يمسسك بخير فهو علي كل شيء قدير', 7, 13, 52, 1, 2, 129, false, NULL),
    (807, 'tanzil-uthmani-v1.1', 6, 18, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'da82a7b109f6b3abfacf4b59a4ccf6112696e18dc41cc3f53a8ab644b2ca574d', 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 'da82a7b109f6b3abfacf4b59a4ccf6112696e18dc41cc3f53a8ab644b2ca574d', 'da82a7b109f6b3abfacf4b59a4ccf6112696e18dc41cc3f53a8ab644b2ca574d', NULL, 'وهو القاهر فوق عباده وهو الحكيم الخبير', 7, 13, 52, 1, 2, 129, false, NULL),
    (808, 'tanzil-uthmani-v1.1', 6, 19, 'قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَٰدَةً قُلِ ٱللَّهُ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ وَأُوحِىَ إِلَىَّ هَٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ قُل لَّآ أَشْهَدُ قُلْ إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ وَإِنَّنِى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'ac8eb1654849f206d5850edd50fa1f1d10a5c4414407192207c0ea92c566f0de', 'قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَٰدَةً قُلِ ٱللَّهُ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ وَأُوحِىَ إِلَىَّ هَٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ قُل لَّآ أَشْهَدُ قُلْ إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ وَإِنَّنِى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'ac8eb1654849f206d5850edd50fa1f1d10a5c4414407192207c0ea92c566f0de', 'ac8eb1654849f206d5850edd50fa1f1d10a5c4414407192207c0ea92c566f0de', NULL, 'قل اي شيء اكبر شهده قل الله شهيد بيني وبينكم واوحي الي هذا القرءان لانذركم به ومن بلغ ائنكم لتشهدون ان مع الله ءالهه اخري قل لا اشهد قل انما هو اله وحد وانني بريء مما تشركون', 7, 13, 52, 1, 2, 130, false, NULL),
    (809, 'tanzil-uthmani-v1.1', 6, 20, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 'e86d5244eecd356efd74f3aef99030b811e36277ac1598cfff7baf7c9a83db0f', 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 'e86d5244eecd356efd74f3aef99030b811e36277ac1598cfff7baf7c9a83db0f', 'e86d5244eecd356efd74f3aef99030b811e36277ac1598cfff7baf7c9a83db0f', NULL, 'الذين ءاتينهم الكتب يعرفونه كما يعرفون ابناءهم الذين خسروا انفسهم فهم لا يؤمنون', 7, 13, 52, 1, 2, 130, false, NULL),
    (810, 'tanzil-uthmani-v1.1', 6, 21, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'd0d72642d7e83b2c80240a4e56672d6ee064277f06dffe161b11a3ff71a35bc5', 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'd0d72642d7e83b2c80240a4e56672d6ee064277f06dffe161b11a3ff71a35bc5', 'd0d72642d7e83b2c80240a4e56672d6ee064277f06dffe161b11a3ff71a35bc5', NULL, 'ومن اظلم ممن افتري علي الله كذبا او كذب بايته انه لا يفلح الظلمون', 7, 13, 52, 1, 2, 130, false, NULL),
    (811, 'tanzil-uthmani-v1.1', 6, 22, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', '4c6602550bc63cf798c5f626a59b408fe4d496ba19bff3103374b2c2faeb51a5', 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', '4c6602550bc63cf798c5f626a59b408fe4d496ba19bff3103374b2c2faeb51a5', '4c6602550bc63cf798c5f626a59b408fe4d496ba19bff3103374b2c2faeb51a5', NULL, 'ويوم نحشرهم جميعا ثم نقول للذين اشركوا اين شركاؤكم الذين كنتم تزعمون', 7, 13, 52, 1, 2, 130, false, NULL),
    (812, 'tanzil-uthmani-v1.1', 6, 23, 'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ', 'af5506661c51b69dc8172ade44730bf5710b4a4e570304dc624ff0a3a34384d9', 'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ', 'af5506661c51b69dc8172ade44730bf5710b4a4e570304dc624ff0a3a34384d9', 'af5506661c51b69dc8172ade44730bf5710b4a4e570304dc624ff0a3a34384d9', NULL, 'ثم لم تكن فتنتهم الا ان قالوا والله ربنا ما كنا مشركين', 7, 13, 52, 1, 2, 130, false, NULL),
    (813, 'tanzil-uthmani-v1.1', 6, 24, 'ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'b5122bbba4835213371f10926b7312ef54a8f07c54dc3e2d9febdea1eddf3d12', 'ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'b5122bbba4835213371f10926b7312ef54a8f07c54dc3e2d9febdea1eddf3d12', 'b5122bbba4835213371f10926b7312ef54a8f07c54dc3e2d9febdea1eddf3d12', NULL, 'انظر كيف كذبوا علي انفسهم وضل عنهم ما كانوا يفترون', 7, 13, 52, 1, 2, 130, false, NULL),
    (814, 'tanzil-uthmani-v1.1', 6, 25, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', '5d5acc71621fca9f0f71ffbfc49a7cc5009d2a038b7f8cd26a909c9a0e2bd4b6', 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', '5d5acc71621fca9f0f71ffbfc49a7cc5009d2a038b7f8cd26a909c9a0e2bd4b6', '5d5acc71621fca9f0f71ffbfc49a7cc5009d2a038b7f8cd26a909c9a0e2bd4b6', NULL, 'ومنهم من يستمع اليك وجعلنا علي قلوبهم اكنه ان يفقهوه وفي ءاذانهم وقرا وان يروا كل ءايه لا يؤمنوا بها حتي اذا جاءوك يجدلونك يقول الذين كفروا ان هذا الا اسطير الاولين', 7, 13, 52, 1, 2, 130, false, NULL),
    (815, 'tanzil-uthmani-v1.1', 6, 26, 'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'f1f4e67d2c894a67ac5a89c332e3151f2c56c159a794e74c740a98705309b19b', 'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 'f1f4e67d2c894a67ac5a89c332e3151f2c56c159a794e74c740a98705309b19b', 'f1f4e67d2c894a67ac5a89c332e3151f2c56c159a794e74c740a98705309b19b', NULL, 'وهم ينهون عنه وينون عنه وان يهلكون الا انفسهم وما يشعرون', 7, 13, 52, 1, 2, 130, false, NULL),
    (816, 'tanzil-uthmani-v1.1', 6, 27, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'eb075e6211b3e59e82fb082b54deb2add018aff9d23fdb3f32e0060734c226ad', 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'eb075e6211b3e59e82fb082b54deb2add018aff9d23fdb3f32e0060734c226ad', 'eb075e6211b3e59e82fb082b54deb2add018aff9d23fdb3f32e0060734c226ad', NULL, 'ولو تري اذ وقفوا علي النار فقالوا يليتنا نرد ولا نكذب بايت ربنا ونكون من المؤمنين', 7, 13, 52, 1, 2, 130, false, NULL),
    (817, 'tanzil-uthmani-v1.1', 6, 28, 'بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 'e36a1de5e5f801dfbeee4f6ddfa204b4a392927799ac5f314b8513aaeb5d0cc1', 'بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 'e36a1de5e5f801dfbeee4f6ddfa204b4a392927799ac5f314b8513aaeb5d0cc1', 'e36a1de5e5f801dfbeee4f6ddfa204b4a392927799ac5f314b8513aaeb5d0cc1', NULL, 'بل بدا لهم ما كانوا يخفون من قبل ولو ردوا لعادوا لما نهوا عنه وانهم لكذبون', 7, 13, 52, 1, 2, 131, false, NULL),
    (818, 'tanzil-uthmani-v1.1', 6, 29, 'وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', '539ade3298d756d4af439fc47a0a14a12b9ee33bc8f1178c34ec5c5f3d140851', 'وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', '539ade3298d756d4af439fc47a0a14a12b9ee33bc8f1178c34ec5c5f3d140851', '539ade3298d756d4af439fc47a0a14a12b9ee33bc8f1178c34ec5c5f3d140851', NULL, 'وقالوا ان هي الا حياتنا الدنيا وما نحن بمبعوثين', 7, 13, 52, 1, 2, 131, false, NULL),
    (819, 'tanzil-uthmani-v1.1', 6, 30, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ قَالَ أَلَيْسَ هَٰذَا بِٱلْحَقِّ قَالُوا۟ بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '698c2e1bbf850d3afad2a6644cb3d44e24047ddb3965eb557abb4bc45b4a773f', 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ قَالَ أَلَيْسَ هَٰذَا بِٱلْحَقِّ قَالُوا۟ بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '698c2e1bbf850d3afad2a6644cb3d44e24047ddb3965eb557abb4bc45b4a773f', '698c2e1bbf850d3afad2a6644cb3d44e24047ddb3965eb557abb4bc45b4a773f', NULL, 'ولو تري اذ وقفوا علي ربهم قال اليس هذا بالحق قالوا بلي وربنا قال فذوقوا العذاب بما كنتم تكفرون', 7, 13, 52, 1, 2, 131, false, NULL),
    (820, 'tanzil-uthmani-v1.1', 6, 31, 'قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةً قَالُوا۟ يَٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ أَلَا سَآءَ مَا يَزِرُونَ', 'eec2f215bf22441ff7048ab05e4aeba6774fe56b6dc39312a53a71ed211d0d73', 'قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةً قَالُوا۟ يَٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ أَلَا سَآءَ مَا يَزِرُونَ', 'eec2f215bf22441ff7048ab05e4aeba6774fe56b6dc39312a53a71ed211d0d73', 'eec2f215bf22441ff7048ab05e4aeba6774fe56b6dc39312a53a71ed211d0d73', NULL, 'قد خسر الذين كذبوا بلقاء الله حتي اذا جاءتهم الساعه بغته قالوا يحسرتنا علي ما فرطنا فيها وهم يحملون اوزارهم علي ظهورهم الا ساء ما يزرون', 7, 13, 52, 1, 2, 131, false, NULL),
    (821, 'tanzil-uthmani-v1.1', 6, 32, 'وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌ وَلَهْوٌ وَلَلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', '9276dfc806a5b96fa532152b92cec7281974955cf9672c31fe3ad2f5b9b0f596', 'وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌ وَلَهْوٌ وَلَلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', '9276dfc806a5b96fa532152b92cec7281974955cf9672c31fe3ad2f5b9b0f596', '9276dfc806a5b96fa532152b92cec7281974955cf9672c31fe3ad2f5b9b0f596', NULL, 'وما الحيوه الدنيا الا لعب ولهو وللدار الاخره خير للذين يتقون افلا تعقلون', 7, 13, 52, 1, 2, 131, false, NULL),
    (822, 'tanzil-uthmani-v1.1', 6, 33, 'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', '3c0c9de9ebe9b800f2cacd047beac6454556deebbe3ae771a5cd6d95c0322c68', 'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', '3c0c9de9ebe9b800f2cacd047beac6454556deebbe3ae771a5cd6d95c0322c68', '3c0c9de9ebe9b800f2cacd047beac6454556deebbe3ae771a5cd6d95c0322c68', NULL, 'قد نعلم انه ليحزنك الذي يقولون فانهم لا يكذبونك ولكن الظلمين بايت الله يجحدون', 7, 13, 52, 1, 2, 131, false, NULL),
    (823, 'tanzil-uthmani-v1.1', 6, 34, 'وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ', 'd8b4b31c80d3d7af5b66f9c71b08e4909e51d1dffd6c164e5c363465329c2d10', 'وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ', 'd8b4b31c80d3d7af5b66f9c71b08e4909e51d1dffd6c164e5c363465329c2d10', 'd8b4b31c80d3d7af5b66f9c71b08e4909e51d1dffd6c164e5c363465329c2d10', NULL, 'ولقد كذبت رسل من قبلك فصبروا علي ما كذبوا واوذوا حتي اتيهم نصرنا ولا مبدل لكلمت الله ولقد جاءك من نباي المرسلين', 7, 13, 52, 1, 2, 131, false, NULL),
    (824, 'tanzil-uthmani-v1.1', 6, 35, 'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًا فِى ٱلْأَرْضِ أَوْ سُلَّمًا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ فَلَا تَكُونَنَّ مِنَ ٱلْجَٰهِلِينَ', 'd7b931fbeab4cdc5e4d05bcfb16de83c6a2e07766d08cc9789b798c10abcf9e4', 'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًا فِى ٱلْأَرْضِ أَوْ سُلَّمًا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ فَلَا تَكُونَنَّ مِنَ ٱلْجَٰهِلِينَ', 'd7b931fbeab4cdc5e4d05bcfb16de83c6a2e07766d08cc9789b798c10abcf9e4', 'd7b931fbeab4cdc5e4d05bcfb16de83c6a2e07766d08cc9789b798c10abcf9e4', NULL, 'وان كان كبر عليك اعراضهم فان استطعت ان تبتغي نفقا في الارض او سلما في السماء فتاتيهم بايه ولو شاء الله لجمعهم علي الهدي فلا تكونن من الجهلين', 7, 13, 52, 1, 2, 131, false, NULL),
    (825, 'tanzil-uthmani-v1.1', 6, 36, 'إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ', 'f49fecb59980f70d14eaa7e40f9cf0e5255125d50092a5e5060f95bf68c4605b', 'إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ', 'f49fecb59980f70d14eaa7e40f9cf0e5255125d50092a5e5060f95bf68c4605b', 'f49fecb59980f70d14eaa7e40f9cf0e5255125d50092a5e5060f95bf68c4605b', NULL, 'انما يستجيب الذين يسمعون والموتي يبعثهم الله ثم اليه يرجعون', 7, 14, 53, 1, 2, 132, false, NULL),
    (826, 'tanzil-uthmani-v1.1', 6, 37, 'وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةً وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '99dbe33ee6ec89390ffe74c0070547fe630530c47206958a7643d4a01a9b1377', 'وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةً وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '99dbe33ee6ec89390ffe74c0070547fe630530c47206958a7643d4a01a9b1377', '99dbe33ee6ec89390ffe74c0070547fe630530c47206958a7643d4a01a9b1377', NULL, 'وقالوا لولا نزل عليه ءايه من ربه قل ان الله قادر علي ان ينزل ءايه ولكن اكثرهم لا يعلمون', 7, 14, 53, 1, 2, 132, false, NULL),
    (827, 'tanzil-uthmani-v1.1', 6, 38, 'وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ وَلَا طَٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم مَّا فَرَّطْنَا فِى ٱلْكِتَٰبِ مِن شَىْءٍ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ', '575db3178b96200b91d0e0e38e80256204f9ddf4b226ad12f793b7bc49ec90e7', 'وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ وَلَا طَٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم مَّا فَرَّطْنَا فِى ٱلْكِتَٰبِ مِن شَىْءٍ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ', '575db3178b96200b91d0e0e38e80256204f9ddf4b226ad12f793b7bc49ec90e7', '575db3178b96200b91d0e0e38e80256204f9ddf4b226ad12f793b7bc49ec90e7', NULL, 'وما من دابه في الارض ولا طئر يطير بجناحيه الا امم امثالكم ما فرطنا في الكتب من شيء ثم الي ربهم يحشرون', 7, 14, 53, 1, 2, 132, false, NULL),
    (828, 'tanzil-uthmani-v1.1', 6, 39, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا صُمٌّ وَبُكْمٌ فِى ٱلظُّلُمَٰتِ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '3acdb4dd30e61b7f5ea909565b8fa622aed4d76a40c4f7d3864353e4b0e4c0cf', 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا صُمٌّ وَبُكْمٌ فِى ٱلظُّلُمَٰتِ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '3acdb4dd30e61b7f5ea909565b8fa622aed4d76a40c4f7d3864353e4b0e4c0cf', '3acdb4dd30e61b7f5ea909565b8fa622aed4d76a40c4f7d3864353e4b0e4c0cf', NULL, 'والذين كذبوا بايتنا صم وبكم في الظلمت من يشا الله يضلله ومن يشا يجعله علي صرط مستقيم', 7, 14, 53, 1, 2, 132, false, NULL),
    (829, 'tanzil-uthmani-v1.1', 6, 40, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَٰدِقِينَ', '2bd1f2603e0c1ba649184778b467bcca1a13b93c00402e8613b4255c2c447997', 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَٰدِقِينَ', '2bd1f2603e0c1ba649184778b467bcca1a13b93c00402e8613b4255c2c447997', '2bd1f2603e0c1ba649184778b467bcca1a13b93c00402e8613b4255c2c447997', NULL, 'قل ارءيتكم ان اتيكم عذاب الله او اتتكم الساعه اغير الله تدعون ان كنتم صدقين', 7, 14, 53, 1, 2, 132, false, NULL),
    (830, 'tanzil-uthmani-v1.1', 6, 41, 'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ', '052e24be2cad1ea86a26f91c7632d4c326f92971cc78167a45f22c5806bb49f9', 'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ', '052e24be2cad1ea86a26f91c7632d4c326f92971cc78167a45f22c5806bb49f9', '052e24be2cad1ea86a26f91c7632d4c326f92971cc78167a45f22c5806bb49f9', NULL, 'بل اياه تدعون فيكشف ما تدعون اليه ان شاء وتنسون ما تشركون', 7, 14, 53, 1, 2, 132, false, NULL),
    (831, 'tanzil-uthmani-v1.1', 6, 42, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ', '45d9c2ae0b0e1e94a8067f6c29398589af6c5e6d693c3219d8253e2b32343ecf', 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ', '45d9c2ae0b0e1e94a8067f6c29398589af6c5e6d693c3219d8253e2b32343ecf', '45d9c2ae0b0e1e94a8067f6c29398589af6c5e6d693c3219d8253e2b32343ecf', NULL, 'ولقد ارسلنا الي امم من قبلك فاخذنهم بالباساء والضراء لعلهم يتضرعون', 7, 14, 53, 1, 2, 132, false, NULL),
    (832, 'tanzil-uthmani-v1.1', 6, 43, 'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ مَا كَانُوا۟ يَعْمَلُونَ', 'b3fd34bc1102e2fe2bf9b26100ea9e117065b6ce715d1c403ce9dc7493131d04', 'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ مَا كَانُوا۟ يَعْمَلُونَ', 'b3fd34bc1102e2fe2bf9b26100ea9e117065b6ce715d1c403ce9dc7493131d04', 'b3fd34bc1102e2fe2bf9b26100ea9e117065b6ce715d1c403ce9dc7493131d04', NULL, 'فلولا اذ جاءهم باسنا تضرعوا ولكن قست قلوبهم وزين لهم الشيطن ما كانوا يعملون', 7, 14, 53, 1, 2, 132, false, NULL),
    (833, 'tanzil-uthmani-v1.1', 6, 44, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ', '51dd6762ccb1c1348ff5af28c243db3a5275ce6ee48f52ac92449950abbdbba1', 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ', '51dd6762ccb1c1348ff5af28c243db3a5275ce6ee48f52ac92449950abbdbba1', '51dd6762ccb1c1348ff5af28c243db3a5275ce6ee48f52ac92449950abbdbba1', NULL, 'فلما نسوا ما ذكروا به فتحنا عليهم ابوب كل شيء حتي اذا فرحوا بما اوتوا اخذنهم بغته فاذا هم مبلسون', 7, 14, 53, 1, 2, 132, false, NULL),
    (834, 'tanzil-uthmani-v1.1', 6, 45, 'فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'd0e77f11bfde9900e80da3f9da72e264527ed12cb488f81c844a96989f8a6cba', 'فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'd0e77f11bfde9900e80da3f9da72e264527ed12cb488f81c844a96989f8a6cba', 'd0e77f11bfde9900e80da3f9da72e264527ed12cb488f81c844a96989f8a6cba', NULL, 'فقطع دابر القوم الذين ظلموا والحمد لله رب العلمين', 7, 14, 53, 1, 2, 133, false, NULL),
    (835, 'tanzil-uthmani-v1.1', 6, 46, 'قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَٰتِ ثُمَّ هُمْ يَصْدِفُونَ', 'f858dc0a19e76426bc6f40493a8c1d83c5b5c9fc129b04881b533e01dbfbfeb9', 'قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَٰتِ ثُمَّ هُمْ يَصْدِفُونَ', 'f858dc0a19e76426bc6f40493a8c1d83c5b5c9fc129b04881b533e01dbfbfeb9', 'f858dc0a19e76426bc6f40493a8c1d83c5b5c9fc129b04881b533e01dbfbfeb9', NULL, 'قل ارءيتم ان اخذ الله سمعكم وابصركم وختم علي قلوبكم من اله غير الله ياتيكم به انظر كيف نصرف الايت ثم هم يصدفون', 7, 14, 53, 1, 2, 133, false, NULL),
    (836, 'tanzil-uthmani-v1.1', 6, 47, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّٰلِمُونَ', '0e5087f6e562c7a662bfa7e443ba7972ea7f48c837868fee91a0b56df22d7cf7', 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّٰلِمُونَ', '0e5087f6e562c7a662bfa7e443ba7972ea7f48c837868fee91a0b56df22d7cf7', '0e5087f6e562c7a662bfa7e443ba7972ea7f48c837868fee91a0b56df22d7cf7', NULL, 'قل ارءيتكم ان اتيكم عذاب الله بغته او جهره هل يهلك الا القوم الظلمون', 7, 14, 53, 1, 2, 133, false, NULL),
    (837, 'tanzil-uthmani-v1.1', 6, 48, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '04b1e95e845fc93b3faf4883311890e72f0ac812fcfb2a46a32ddc8d537703f6', 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '04b1e95e845fc93b3faf4883311890e72f0ac812fcfb2a46a32ddc8d537703f6', '04b1e95e845fc93b3faf4883311890e72f0ac812fcfb2a46a32ddc8d537703f6', NULL, 'وما نرسل المرسلين الا مبشرين ومنذرين فمن ءامن واصلح فلا خوف عليهم ولا هم يحزنون', 7, 14, 53, 1, 2, 133, false, NULL),
    (838, 'tanzil-uthmani-v1.1', 6, 49, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ', 'be8d47bd232f8ef3c84dc80d8afa379836549596482b5d21d0ca2265002f5c44', 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ', 'be8d47bd232f8ef3c84dc80d8afa379836549596482b5d21d0ca2265002f5c44', 'be8d47bd232f8ef3c84dc80d8afa379836549596482b5d21d0ca2265002f5c44', NULL, 'والذين كذبوا بايتنا يمسهم العذاب بما كانوا يفسقون', 7, 14, 53, 1, 2, 133, false, NULL),
    (839, 'tanzil-uthmani-v1.1', 6, 50, 'قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَفَلَا تَتَفَكَّرُونَ', '2da07f89fb19318372307e9eea57c24898b80702ae192230209848534f0f7f90', 'قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَفَلَا تَتَفَكَّرُونَ', '2da07f89fb19318372307e9eea57c24898b80702ae192230209848534f0f7f90', '2da07f89fb19318372307e9eea57c24898b80702ae192230209848534f0f7f90', NULL, 'قل لا اقول لكم عندي خزائن الله ولا اعلم الغيب ولا اقول لكم اني ملك ان اتبع الا ما يوحي الي قل هل يستوي الاعمي والبصير افلا تتفكرون', 7, 14, 53, 1, 2, 133, false, NULL),
    (840, 'tanzil-uthmani-v1.1', 6, 51, 'وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ', '66e8e9b7b632a76acc1b087bd2c511a3cd88438f49fdff45bf007dc22d5ec650', 'وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ', '66e8e9b7b632a76acc1b087bd2c511a3cd88438f49fdff45bf007dc22d5ec650', '66e8e9b7b632a76acc1b087bd2c511a3cd88438f49fdff45bf007dc22d5ec650', NULL, 'وانذر به الذين يخافون ان يحشروا الي ربهم ليس لهم من دونه ولي ولا شفيع لعلهم يتقون', 7, 14, 53, 1, 2, 133, false, NULL),
    (841, 'tanzil-uthmani-v1.1', 6, 52, 'وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ', 'e96901812654841854a9f5d49f747967325cfad57e13a4572b9b853f5baac1e5', 'وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ', 'e96901812654841854a9f5d49f747967325cfad57e13a4572b9b853f5baac1e5', 'e96901812654841854a9f5d49f747967325cfad57e13a4572b9b853f5baac1e5', NULL, 'ولا تطرد الذين يدعون ربهم بالغدوه والعشي يريدون وجهه ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء فتطردهم فتكون من الظلمين', 7, 14, 53, 1, 2, 133, false, NULL),
    (842, 'tanzil-uthmani-v1.1', 6, 53, 'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوٓا۟ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّٰكِرِينَ', 'e89c295ba2b18682dcd4259a20d7432463830678d71b4211d9f04c95d2ef38c2', 'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوٓا۟ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّٰكِرِينَ', 'e89c295ba2b18682dcd4259a20d7432463830678d71b4211d9f04c95d2ef38c2', 'e89c295ba2b18682dcd4259a20d7432463830678d71b4211d9f04c95d2ef38c2', NULL, 'وكذلك فتنا بعضهم ببعض ليقولوا اهؤلاء من الله عليهم من بيننا اليس الله باعلم بالشكرين', 7, 14, 53, 1, 2, 134, false, NULL),
    (843, 'tanzil-uthmani-v1.1', 6, 54, 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَٰتِنَا فَقُلْ سَلَٰمٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَٰلَةٍ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌ رَّحِيمٌ', '838b6ed497c5d28cd5e421503b0becc680fd908065ca7fb5ff2c582f7bee00cb', 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَٰتِنَا فَقُلْ سَلَٰمٌ عَلَيْكُمْ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَٰلَةٍ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌ رَّحِيمٌ', '838b6ed497c5d28cd5e421503b0becc680fd908065ca7fb5ff2c582f7bee00cb', '838b6ed497c5d28cd5e421503b0becc680fd908065ca7fb5ff2c582f7bee00cb', NULL, 'واذا جاءك الذين يؤمنون بايتنا فقل سلم عليكم كتب ربكم علي نفسه الرحمه انه من عمل منكم سوءا بجهله ثم تاب من بعده واصلح فانه غفور رحيم', 7, 14, 53, 1, 2, 134, false, NULL),
    (844, 'tanzil-uthmani-v1.1', 6, 55, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ', '231a31ee59f2466f168168e8252069f55475fa7783f29e3ce9d5d49b9bbea521', 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ', '231a31ee59f2466f168168e8252069f55475fa7783f29e3ce9d5d49b9bbea521', '231a31ee59f2466f168168e8252069f55475fa7783f29e3ce9d5d49b9bbea521', NULL, 'وكذلك نفصل الايت ولتستبين سبيل المجرمين', 7, 14, 53, 1, 2, 134, false, NULL),
    (845, 'tanzil-uthmani-v1.1', 6, 56, 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ قَدْ ضَلَلْتُ إِذًا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ', 'a6e37cb0c640edc1ad5af10ac38cea2dd27a84315b2223d8d1a1255fb73a753f', 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ قَدْ ضَلَلْتُ إِذًا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ', 'a6e37cb0c640edc1ad5af10ac38cea2dd27a84315b2223d8d1a1255fb73a753f', 'a6e37cb0c640edc1ad5af10ac38cea2dd27a84315b2223d8d1a1255fb73a753f', NULL, 'قل اني نهيت ان اعبد الذين تدعون من دون الله قل لا اتبع اهواءكم قد ضللت اذا وما انا من المهتدين', 7, 14, 53, 1, 2, 134, false, NULL),
    (846, 'tanzil-uthmani-v1.1', 6, 57, 'قُلْ إِنِّى عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ يَقُصُّ ٱلْحَقَّ وَهُوَ خَيْرُ ٱلْفَٰصِلِينَ', '6ba903a33eaa6f29dec2b36123a2719e53c0e944e0b101f988495d53757a835a', 'قُلْ إِنِّى عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ يَقُصُّ ٱلْحَقَّ وَهُوَ خَيْرُ ٱلْفَٰصِلِينَ', '6ba903a33eaa6f29dec2b36123a2719e53c0e944e0b101f988495d53757a835a', '6ba903a33eaa6f29dec2b36123a2719e53c0e944e0b101f988495d53757a835a', NULL, 'قل اني علي بينه من ربي وكذبتم به ما عندي ما تستعجلون به ان الحكم الا لله يقص الحق وهو خير الفصلين', 7, 14, 53, 1, 2, 134, false, NULL),
    (847, 'tanzil-uthmani-v1.1', 6, 58, 'قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ وَٱللَّهُ أَعْلَمُ بِٱلظَّٰلِمِينَ', '2e691e3ba3ed552e47ec8f4b6355350c8fba82f72dfed78020fb195537df7f27', 'قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ وَٱللَّهُ أَعْلَمُ بِٱلظَّٰلِمِينَ', '2e691e3ba3ed552e47ec8f4b6355350c8fba82f72dfed78020fb195537df7f27', '2e691e3ba3ed552e47ec8f4b6355350c8fba82f72dfed78020fb195537df7f27', NULL, 'قل لو ان عندي ما تستعجلون به لقضي الامر بيني وبينكم والله اعلم بالظلمين', 7, 14, 53, 1, 2, 134, false, NULL),
    (848, 'tanzil-uthmani-v1.1', 6, 59, 'وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِى ظُلُمَٰتِ ٱلْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', '1272cc0235e752873dd95ec3ceec6b9227f76dac40ba0dbb61fc16b6dbb30975', 'وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِى ظُلُمَٰتِ ٱلْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', '1272cc0235e752873dd95ec3ceec6b9227f76dac40ba0dbb61fc16b6dbb30975', '1272cc0235e752873dd95ec3ceec6b9227f76dac40ba0dbb61fc16b6dbb30975', NULL, 'وعنده مفاتح الغيب لا يعلمها الا هو ويعلم ما في البر والبحر وما تسقط من ورقه الا يعلمها ولا حبه في ظلمت الارض ولا رطب ولا يابس الا في كتب مبين', 7, 14, 54, 1, 2, 134, false, NULL),
    (849, 'tanzil-uthmani-v1.1', 6, 60, 'وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌ مُّسَمًّى ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'fbc8182a873bf5d202bfbe7371916080cafeb4c94feefbab4c3492b1bcad7116', 'وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌ مُّسَمًّى ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'fbc8182a873bf5d202bfbe7371916080cafeb4c94feefbab4c3492b1bcad7116', 'fbc8182a873bf5d202bfbe7371916080cafeb4c94feefbab4c3492b1bcad7116', NULL, 'وهو الذي يتوفيكم باليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضي اجل مسمي ثم اليه مرجعكم ثم ينبئكم بما كنتم تعملون', 7, 14, 54, 1, 2, 135, false, NULL),
    (850, 'tanzil-uthmani-v1.1', 6, 61, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ', 'b40ee3bf80093bf91f544ce9e4841d32d33b24977af413ff3b1c601b694c6da3', 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ', 'b40ee3bf80093bf91f544ce9e4841d32d33b24977af413ff3b1c601b694c6da3', 'b40ee3bf80093bf91f544ce9e4841d32d33b24977af413ff3b1c601b694c6da3', NULL, 'وهو القاهر فوق عباده ويرسل عليكم حفظه حتي اذا جاء احدكم الموت توفته رسلنا وهم لا يفرطون', 7, 14, 54, 1, 2, 135, false, NULL),
    (851, 'tanzil-uthmani-v1.1', 6, 62, 'ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَٰسِبِينَ', '90c74ed964fbb17453345cbf60f4f5b32d5756d1b41592ccb65ead7b2a3a152d', 'ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَٰسِبِينَ', '90c74ed964fbb17453345cbf60f4f5b32d5756d1b41592ccb65ead7b2a3a152d', '90c74ed964fbb17453345cbf60f4f5b32d5756d1b41592ccb65ead7b2a3a152d', NULL, 'ثم ردوا الي الله موليهم الحق الا له الحكم وهو اسرع الحسبين', 7, 14, 54, 1, 2, 135, false, NULL),
    (852, 'tanzil-uthmani-v1.1', 6, 63, 'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَىٰنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'c5549fbd04007240732450e0ccffd62bd8defa2b8598ceda6a68ea7ed7d10491', 'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَىٰنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'c5549fbd04007240732450e0ccffd62bd8defa2b8598ceda6a68ea7ed7d10491', 'c5549fbd04007240732450e0ccffd62bd8defa2b8598ceda6a68ea7ed7d10491', NULL, 'قل من ينجيكم من ظلمت البر والبحر تدعونه تضرعا وخفيه لئن انجينا من هذه لنكونن من الشكرين', 7, 14, 54, 1, 2, 135, false, NULL),
    (853, 'tanzil-uthmani-v1.1', 6, 64, 'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ', 'ef5768d4802d41c19d3c3a34cc8692e89efe9d7f6d613b6fdcfef9e546e28732', 'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ', 'ef5768d4802d41c19d3c3a34cc8692e89efe9d7f6d613b6fdcfef9e546e28732', 'ef5768d4802d41c19d3c3a34cc8692e89efe9d7f6d613b6fdcfef9e546e28732', NULL, 'قل الله ينجيكم منها ومن كل كرب ثم انتم تشركون', 7, 14, 54, 1, 2, 135, false, NULL),
    (854, 'tanzil-uthmani-v1.1', 6, 65, 'قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَٰتِ لَعَلَّهُمْ يَفْقَهُونَ', 'd542b8ecf0264c1578638ff905afad352dc6f06cc6d065bacc63124947eab349', 'قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَٰتِ لَعَلَّهُمْ يَفْقَهُونَ', 'd542b8ecf0264c1578638ff905afad352dc6f06cc6d065bacc63124947eab349', 'd542b8ecf0264c1578638ff905afad352dc6f06cc6d065bacc63124947eab349', NULL, 'قل هو القادر علي ان يبعث عليكم عذابا من فوقكم او من تحت ارجلكم او يلبسكم شيعا ويذيق بعضكم باس بعض انظر كيف نصرف الايت لعلهم يفقهون', 7, 14, 54, 1, 2, 135, false, NULL),
    (855, 'tanzil-uthmani-v1.1', 6, 66, 'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ', 'cf06f4688920fccf819f556b0320b6d481ad913fd8fa7457082c0b01d623369f', 'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ', 'cf06f4688920fccf819f556b0320b6d481ad913fd8fa7457082c0b01d623369f', 'cf06f4688920fccf819f556b0320b6d481ad913fd8fa7457082c0b01d623369f', NULL, 'وكذب به قومك وهو الحق قل لست عليكم بوكيل', 7, 14, 54, 1, 2, 135, false, NULL),
    (856, 'tanzil-uthmani-v1.1', 6, 67, 'لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ وَسَوْفَ تَعْلَمُونَ', '26669aa51a343b177397760b6b79071a6228e3428167bd6b7ff3afeae8bc1d52', 'لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ وَسَوْفَ تَعْلَمُونَ', '26669aa51a343b177397760b6b79071a6228e3428167bd6b7ff3afeae8bc1d52', '26669aa51a343b177397760b6b79071a6228e3428167bd6b7ff3afeae8bc1d52', NULL, 'لكل نبا مستقر وسوف تعلمون', 7, 14, 54, 1, 2, 135, false, NULL),
    (857, 'tanzil-uthmani-v1.1', 6, 68, 'وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '2260cf9be05eb1f22d8cbe8beafe3dfb4d3ac8c8315a7af8292ea4f29b299b78', 'وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '2260cf9be05eb1f22d8cbe8beafe3dfb4d3ac8c8315a7af8292ea4f29b299b78', '2260cf9be05eb1f22d8cbe8beafe3dfb4d3ac8c8315a7af8292ea4f29b299b78', NULL, 'واذا رايت الذين يخوضون في ءايتنا فاعرض عنهم حتي يخوضوا في حديث غيره واما ينسينك الشيطن فلا تقعد بعد الذكري مع القوم الظلمين', 7, 14, 54, 1, 2, 135, false, NULL),
    (858, 'tanzil-uthmani-v1.1', 6, 69, 'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَلَٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ', '18a2a7fb4732e24130368adab20d27bad611e5c3e33ad784488a892f14d0272e', 'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَلَٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ', '18a2a7fb4732e24130368adab20d27bad611e5c3e33ad784488a892f14d0272e', '18a2a7fb4732e24130368adab20d27bad611e5c3e33ad784488a892f14d0272e', NULL, 'وما علي الذين يتقون من حسابهم من شيء ولكن ذكري لعلهم يتقون', 7, 14, 54, 1, 2, 136, false, NULL),
    (859, 'tanzil-uthmani-v1.1', 6, 70, 'وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَآ أُو۟لَٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 'ed146ab917a7053bb66b3b83372eacbbfd4599b6eb742cfb429262ddec13b7e6', 'وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَآ أُو۟لَٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 'ed146ab917a7053bb66b3b83372eacbbfd4599b6eb742cfb429262ddec13b7e6', 'ed146ab917a7053bb66b3b83372eacbbfd4599b6eb742cfb429262ddec13b7e6', NULL, 'وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحيوه الدنيا وذكر به ان تبسل نفس بما كسبت ليس لها من دون الله ولي ولا شفيع وان تعدل كل عدل لا يؤخذ منها اولئك الذين ابسلوا بما كسبوا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون', 7, 14, 54, 1, 2, 136, false, NULL),
    (860, 'tanzil-uthmani-v1.1', 6, 71, 'قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَٰبٌ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 'd3a6c0d105fba8d6f261442df03a892d0f1661ab485a6dba455a81bf5962c68b', 'قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَٰبٌ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 'd3a6c0d105fba8d6f261442df03a892d0f1661ab485a6dba455a81bf5962c68b', 'd3a6c0d105fba8d6f261442df03a892d0f1661ab485a6dba455a81bf5962c68b', NULL, 'قل اندعوا من دون الله ما لا ينفعنا ولا يضرنا ونرد علي اعقابنا بعد اذ هدينا الله كالذي استهوته الشيطين في الارض حيران له اصحب يدعونه الي الهدي ائتنا قل ان هدي الله هو الهدي وامرنا لنسلم لرب العلمين', 7, 14, 54, 1, 2, 136, false, NULL),
    (861, 'tanzil-uthmani-v1.1', 6, 72, 'وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'a2a48cc76def41ea5eb1b5efca56af8da1744bc14eac647f543616e63439e1cb', 'وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 'a2a48cc76def41ea5eb1b5efca56af8da1744bc14eac647f543616e63439e1cb', 'a2a48cc76def41ea5eb1b5efca56af8da1744bc14eac647f543616e63439e1cb', NULL, 'وان اقيموا الصلوه واتقوه وهو الذي اليه تحشرون', 7, 14, 54, 1, 2, 136, false, NULL),
    (862, 'tanzil-uthmani-v1.1', 6, 73, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَيَوْمَ يَقُولُ كُن فَيَكُونُ قَوْلُهُ ٱلْحَقُّ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', '4aad86718517a438fbdfaf43dbacbc7ac178a2310d71ff93adaa221302df8ec5', 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَيَوْمَ يَقُولُ كُن فَيَكُونُ قَوْلُهُ ٱلْحَقُّ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', '4aad86718517a438fbdfaf43dbacbc7ac178a2310d71ff93adaa221302df8ec5', '4aad86718517a438fbdfaf43dbacbc7ac178a2310d71ff93adaa221302df8ec5', NULL, 'وهو الذي خلق السموت والارض بالحق ويوم يقول كن فيكون قوله الحق وله الملك يوم ينفخ في الصور علم الغيب والشهده وهو الحكيم الخبير', 7, 14, 54, 1, 2, 136, false, NULL),
    (863, 'tanzil-uthmani-v1.1', 6, 74, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَٰلٍ مُّبِينٍ', '59a85a8bbcb36bb7a7f8ac069ceb13fa4a3a5267beed4ec611567b501fd84e14', 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَٰلٍ مُّبِينٍ', '59a85a8bbcb36bb7a7f8ac069ceb13fa4a3a5267beed4ec611567b501fd84e14', '59a85a8bbcb36bb7a7f8ac069ceb13fa4a3a5267beed4ec611567b501fd84e14', NULL, 'واذ قال ابرهيم لابيه ءازر اتتخذ اصناما ءالهه اني اريك وقومك في ضلل مبين', 7, 14, 55, 1, 2, 137, false, NULL),
    (864, 'tanzil-uthmani-v1.1', 6, 75, 'وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ', '73560d13454cf69adceaa6632e867254713a8764e79f5d543140fe14fe8b83d4', 'وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ', '73560d13454cf69adceaa6632e867254713a8764e79f5d543140fe14fe8b83d4', '73560d13454cf69adceaa6632e867254713a8764e79f5d543140fe14fe8b83d4', NULL, 'وكذلك نري ابرهيم ملكوت السموت والارض وليكون من الموقنين', 7, 14, 55, 1, 2, 137, false, NULL),
    (865, 'tanzil-uthmani-v1.1', 6, 76, 'فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْـَٔافِلِينَ', '9118c347ea2aa56e43bc81efdd62e5119111795ccba327598f6f0e1c72bb6ee3', 'فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْـَٔافِلِينَ', '9118c347ea2aa56e43bc81efdd62e5119111795ccba327598f6f0e1c72bb6ee3', '9118c347ea2aa56e43bc81efdd62e5119111795ccba327598f6f0e1c72bb6ee3', NULL, 'فلما جن عليه اليل رءا كوكبا قال هذا ربي فلما افل قال لا احب الافلين', 7, 14, 55, 1, 2, 137, false, NULL),
    (866, 'tanzil-uthmani-v1.1', 6, 77, 'فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ', 'b6bdd098dd6d852de91bb91892ff253f3ad0beca7db906a36ce81fcacb1fbef0', 'فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَٰذَا رَبِّى فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ', 'b6bdd098dd6d852de91bb91892ff253f3ad0beca7db906a36ce81fcacb1fbef0', 'b6bdd098dd6d852de91bb91892ff253f3ad0beca7db906a36ce81fcacb1fbef0', NULL, 'فلما رءا القمر بازغا قال هذا ربي فلما افل قال لئن لم يهدني ربي لاكونن من القوم الضالين', 7, 14, 55, 1, 2, 137, false, NULL),
    (867, 'tanzil-uthmani-v1.1', 6, 78, 'فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَٰذَا رَبِّى هَٰذَآ أَكْبَرُ فَلَمَّآ أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'c13499506c4fe44f8f84da86fe977a13e75fc96b31b872f4c54473281457665f', 'فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَٰذَا رَبِّى هَٰذَآ أَكْبَرُ فَلَمَّآ أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'c13499506c4fe44f8f84da86fe977a13e75fc96b31b872f4c54473281457665f', 'c13499506c4fe44f8f84da86fe977a13e75fc96b31b872f4c54473281457665f', NULL, 'فلما رءا الشمس بازغه قال هذا ربي هذا اكبر فلما افلت قال يقوم اني بريء مما تشركون', 7, 14, 55, 1, 2, 137, false, NULL),
    (868, 'tanzil-uthmani-v1.1', 6, 79, 'إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', '0b86212a6010087256c48ecab6ba82bd434c8b839f76e5f92ac08f341459e83e', 'إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', '0b86212a6010087256c48ecab6ba82bd434c8b839f76e5f92ac08f341459e83e', '0b86212a6010087256c48ecab6ba82bd434c8b839f76e5f92ac08f341459e83e', NULL, 'اني وجهت وجهي للذي فطر السموت والارض حنيفا وما انا من المشركين', 7, 14, 55, 1, 2, 137, false, NULL),
    (869, 'tanzil-uthmani-v1.1', 6, 80, 'وَحَآجَّهُۥ قَوْمُهُۥ قَالَ أَتُحَٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًٔا وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا أَفَلَا تَتَذَكَّرُونَ', '0b8c1de106c5c5a791171c5e0f845c8975263abc698a9b4513722926990b8884', 'وَحَآجَّهُۥ قَوْمُهُۥ قَالَ أَتُحَٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًٔا وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا أَفَلَا تَتَذَكَّرُونَ', '0b8c1de106c5c5a791171c5e0f845c8975263abc698a9b4513722926990b8884', '0b8c1de106c5c5a791171c5e0f845c8975263abc698a9b4513722926990b8884', NULL, 'وحاجه قومه قال اتحجوني في الله وقد هدين ولا اخاف ما تشركون به الا ان يشاء ربي شيا وسع ربي كل شيء علما افلا تتذكرون', 7, 14, 55, 1, 2, 137, false, NULL),
    (870, 'tanzil-uthmani-v1.1', 6, 81, 'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَٰنًا فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ إِن كُنتُمْ تَعْلَمُونَ', '52a1d6179e4355a771b507670d6c56f0aa35953a691caaf9ef4e2ab636a8d61d', 'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَٰنًا فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ إِن كُنتُمْ تَعْلَمُونَ', '52a1d6179e4355a771b507670d6c56f0aa35953a691caaf9ef4e2ab636a8d61d', '52a1d6179e4355a771b507670d6c56f0aa35953a691caaf9ef4e2ab636a8d61d', NULL, 'وكيف اخاف ما اشركتم ولا تخافون انكم اشركتم بالله ما لم ينزل به عليكم سلطنا فاي الفريقين احق بالامن ان كنتم تعلمون', 7, 14, 55, 1, 2, 137, false, NULL),
    (871, 'tanzil-uthmani-v1.1', 6, 82, 'ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ أُو۟لَٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ', '211e08f1bc6d9cc7d5e1963b3286c3cf1b4d4595fe7feccca0693b700be7fc6e', 'ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ أُو۟لَٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ', '211e08f1bc6d9cc7d5e1963b3286c3cf1b4d4595fe7feccca0693b700be7fc6e', '211e08f1bc6d9cc7d5e1963b3286c3cf1b4d4595fe7feccca0693b700be7fc6e', NULL, 'الذين ءامنوا ولم يلبسوا ايمنهم بظلم اولئك لهم الامن وهم مهتدون', 7, 14, 55, 1, 2, 138, false, NULL),
    (872, 'tanzil-uthmani-v1.1', 6, 83, 'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', '059930cec26a2c81de3655fdaa4de3ba715fb9785053c8c73c72e29378850074', 'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', '059930cec26a2c81de3655fdaa4de3ba715fb9785053c8c73c72e29378850074', '059930cec26a2c81de3655fdaa4de3ba715fb9785053c8c73c72e29378850074', NULL, 'وتلك حجتنا ءاتينها ابرهيم علي قومه نرفع درجت من نشاء ان ربك حكيم عليم', 7, 14, 55, 1, 2, 138, false, NULL),
    (873, 'tanzil-uthmani-v1.1', 6, 84, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ كُلًّا هَدَيْنَا وَنُوحًا هَدَيْنَا مِن قَبْلُ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '5384f69da695724c7ec6cd683354aee9c0f03028dafbe81082afcb71e57a26e4', 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ كُلًّا هَدَيْنَا وَنُوحًا هَدَيْنَا مِن قَبْلُ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '5384f69da695724c7ec6cd683354aee9c0f03028dafbe81082afcb71e57a26e4', '5384f69da695724c7ec6cd683354aee9c0f03028dafbe81082afcb71e57a26e4', NULL, 'ووهبنا له اسحق ويعقوب كلا هدينا ونوحا هدينا من قبل ومن ذريته داود وسليمن وايوب ويوسف وموسي وهرون وكذلك نجزي المحسنين', 7, 14, 55, 1, 2, 138, false, NULL),
    (874, 'tanzil-uthmani-v1.1', 6, 85, 'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ كُلٌّ مِّنَ ٱلصَّٰلِحِينَ', '78015ce75249147cf77713f3aeb5ff928607dbb3896148ee35d3b31cf8c3962e', 'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ كُلٌّ مِّنَ ٱلصَّٰلِحِينَ', '78015ce75249147cf77713f3aeb5ff928607dbb3896148ee35d3b31cf8c3962e', '78015ce75249147cf77713f3aeb5ff928607dbb3896148ee35d3b31cf8c3962e', NULL, 'وزكريا ويحيي وعيسي والياس كل من الصلحين', 7, 14, 55, 1, 2, 138, false, NULL),
    (875, 'tanzil-uthmani-v1.1', 6, 86, 'وَإِسْمَٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًا وَكُلًّا فَضَّلْنَا عَلَى ٱلْعَٰلَمِينَ', 'dae7170b3ff400e43432f9ecf559e7e778f6c94c0c9253d2a0360f3678f37998', 'وَإِسْمَٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًا وَكُلًّا فَضَّلْنَا عَلَى ٱلْعَٰلَمِينَ', 'dae7170b3ff400e43432f9ecf559e7e778f6c94c0c9253d2a0360f3678f37998', 'dae7170b3ff400e43432f9ecf559e7e778f6c94c0c9253d2a0360f3678f37998', NULL, 'واسمعيل واليسع ويونس ولوطا وكلا فضلنا علي العلمين', 7, 14, 55, 1, 2, 138, false, NULL),
    (876, 'tanzil-uthmani-v1.1', 6, 87, 'وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْ وَٱجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '8823eab46941b874cc261a775c40bdff4f15243da0e42658b3a3f6d5aae1abd7', 'وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْ وَٱجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '8823eab46941b874cc261a775c40bdff4f15243da0e42658b3a3f6d5aae1abd7', '8823eab46941b874cc261a775c40bdff4f15243da0e42658b3a3f6d5aae1abd7', NULL, 'ومن ءابائهم وذريتهم واخونهم واجتبينهم وهدينهم الي صرط مستقيم', 7, 14, 55, 1, 2, 138, false, NULL),
    (877, 'tanzil-uthmani-v1.1', 6, 88, 'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ', 'b9129ede65a76decb638b47821277f0d1bc687e018cefd1db07f9485c206d68b', 'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ', 'b9129ede65a76decb638b47821277f0d1bc687e018cefd1db07f9485c206d68b', 'b9129ede65a76decb638b47821277f0d1bc687e018cefd1db07f9485c206d68b', NULL, 'ذلك هدي الله يهدي به من يشاء من عباده ولو اشركوا لحبط عنهم ما كانوا يعملون', 7, 14, 55, 1, 2, 138, false, NULL),
    (878, 'tanzil-uthmani-v1.1', 6, 89, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ فَإِن يَكْفُرْ بِهَا هَٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا۟ بِهَا بِكَٰفِرِينَ', '88775df3d794bdcf60be0aebb525b3c728865ecca14fd638b21746889c5fc480', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ فَإِن يَكْفُرْ بِهَا هَٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا۟ بِهَا بِكَٰفِرِينَ', '88775df3d794bdcf60be0aebb525b3c728865ecca14fd638b21746889c5fc480', '88775df3d794bdcf60be0aebb525b3c728865ecca14fd638b21746889c5fc480', NULL, 'اولئك الذين ءاتينهم الكتب والحكم والنبوه فان يكفر بها هؤلاء فقد وكلنا بها قوما ليسوا بها بكفرين', 7, 14, 55, 1, 2, 138, false, NULL),
    (879, 'tanzil-uthmani-v1.1', 6, 90, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ فَبِهُدَىٰهُمُ ٱقْتَدِهْ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَٰلَمِينَ', '11d5127dca38e9359970d46c318dbdd1a932bd5dd695b7af34cc89f3a0edbe1e', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ فَبِهُدَىٰهُمُ ٱقْتَدِهْ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَٰلَمِينَ', '11d5127dca38e9359970d46c318dbdd1a932bd5dd695b7af34cc89f3a0edbe1e', '11d5127dca38e9359970d46c318dbdd1a932bd5dd695b7af34cc89f3a0edbe1e', NULL, 'اولئك الذين هدي الله فبهديهم اقتده قل لا اسلكم عليه اجرا ان هو الا ذكري للعلمين', 7, 14, 55, 1, 2, 138, false, NULL),
    (880, 'tanzil-uthmani-v1.1', 6, 91, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍ مِّن شَىْءٍ قُلْ مَنْ أَنزَلَ ٱلْكِتَٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ قُلِ ٱللَّهُ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ', '53171720cff4ac0df49bb7d9356d4999663dbaa3e8029771ccf517823e04ebff', 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍ مِّن شَىْءٍ قُلْ مَنْ أَنزَلَ ٱلْكِتَٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ قُلِ ٱللَّهُ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ', '53171720cff4ac0df49bb7d9356d4999663dbaa3e8029771ccf517823e04ebff', '53171720cff4ac0df49bb7d9356d4999663dbaa3e8029771ccf517823e04ebff', NULL, 'وما قدروا الله حق قدره اذ قالوا ما انزل الله علي بشر من شيء قل من انزل الكتب الذي جاء به موسي نورا وهدي للناس تجعلونه قراطيس تبدونها وتخفون كثيرا وعلمتم ما لم تعلموا انتم ولا ءاباؤكم قل الله ثم ذرهم في خوضهم يلعبون', 7, 14, 55, 1, 2, 139, false, NULL),
    (881, 'tanzil-uthmani-v1.1', 6, 92, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ يُؤْمِنُونَ بِهِۦ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', '6d92c1eb53ed900fca0e3759157dbe7f02e3f24e5c48e1835f6ffaf26db888f6', 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ يُؤْمِنُونَ بِهِۦ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', '6d92c1eb53ed900fca0e3759157dbe7f02e3f24e5c48e1835f6ffaf26db888f6', '6d92c1eb53ed900fca0e3759157dbe7f02e3f24e5c48e1835f6ffaf26db888f6', NULL, 'وهذا كتب انزلنه مبارك مصدق الذي بين يديه ولتنذر ام القري ومن حولها والذين يؤمنون بالاخره يؤمنون به وهم علي صلاتهم يحافظون', 7, 14, 55, 1, 2, 139, false, NULL),
    (882, 'tanzil-uthmani-v1.1', 6, 93, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَٰتِهِۦ تَسْتَكْبِرُونَ', '34ce39059c71d2e95ccf77d3aefa6a0e81828c6f629110cfe34878bf53bb49c5', 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَٰتِهِۦ تَسْتَكْبِرُونَ', '34ce39059c71d2e95ccf77d3aefa6a0e81828c6f629110cfe34878bf53bb49c5', '34ce39059c71d2e95ccf77d3aefa6a0e81828c6f629110cfe34878bf53bb49c5', NULL, 'ومن اظلم ممن افتري علي الله كذبا او قال اوحي الي ولم يوح اليه شيء ومن قال سانزل مثل ما انزل الله ولو تري اذ الظلمون في غمرت الموت والملئكه باسطوا ايديهم اخرجوا انفسكم اليوم تجزون عذاب الهون بما كنتم تقولون علي الله غير الحق وكنتم عن ءايته تستكبرون', 7, 14, 55, 1, 2, 139, false, NULL),
    (883, 'tanzil-uthmani-v1.1', 6, 94, 'وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَٰكُمْ وَرَآءَ ظُهُورِكُمْ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَٰٓؤُا۟ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ', 'c1e0d4f497d6a037cc8b29386908c650aaf16927bb1bdeccdc386353fbc4f5b3', 'وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَٰكُمْ وَرَآءَ ظُهُورِكُمْ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَٰٓؤُا۟ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ', 'c1e0d4f497d6a037cc8b29386908c650aaf16927bb1bdeccdc386353fbc4f5b3', 'c1e0d4f497d6a037cc8b29386908c650aaf16927bb1bdeccdc386353fbc4f5b3', NULL, 'ولقد جئتمونا فردي كما خلقنكم اول مره وتركتم ما خولنكم وراء ظهوركم وما نري معكم شفعاءكم الذين زعمتم انهم فيكم شركؤا لقد تقطع بينكم وضل عنكم ما كنتم تزعمون', 7, 14, 55, 1, 2, 139, false, NULL),
    (884, 'tanzil-uthmani-v1.1', 6, 95, 'إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ذَٰلِكُمُ ٱللَّهُ فَأَنَّىٰ تُؤْفَكُونَ', 'a2330cc78c70384385150d0da56ca3efe264022608afaadf2c2a1cb97776b8e8', 'إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ذَٰلِكُمُ ٱللَّهُ فَأَنَّىٰ تُؤْفَكُونَ', 'a2330cc78c70384385150d0da56ca3efe264022608afaadf2c2a1cb97776b8e8', 'a2330cc78c70384385150d0da56ca3efe264022608afaadf2c2a1cb97776b8e8', NULL, 'ان الله فالق الحب والنوي يخرج الحي من الميت ومخرج الميت من الحي ذلكم الله فاني تؤفكون', 7, 14, 56, 1, 2, 140, false, NULL),
    (885, 'tanzil-uthmani-v1.1', 6, 96, 'فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'a16cb4d61f857a29355132d095a0702437ca2bde3ada1eaa341fbba704d16442', 'فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'a16cb4d61f857a29355132d095a0702437ca2bde3ada1eaa341fbba704d16442', 'a16cb4d61f857a29355132d095a0702437ca2bde3ada1eaa341fbba704d16442', NULL, 'فالق الاصباح وجعل اليل سكنا والشمس والقمر حسبانا ذلك تقدير العزيز العليم', 7, 14, 56, 1, 2, 140, false, NULL),
    (886, 'tanzil-uthmani-v1.1', 6, 97, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', '6f4d03988c0e787b32f367a721caaf5ca45611ef33a6bd39df744c8f7d09b94c', 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', '6f4d03988c0e787b32f367a721caaf5ca45611ef33a6bd39df744c8f7d09b94c', '6f4d03988c0e787b32f367a721caaf5ca45611ef33a6bd39df744c8f7d09b94c', NULL, 'وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمت البر والبحر قد فصلنا الايت لقوم يعلمون', 7, 14, 56, 1, 2, 140, false, NULL),
    (887, 'tanzil-uthmani-v1.1', 6, 98, 'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍ وَٰحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَفْقَهُونَ', '8b400bc26245471bb100c1d95aa931d303ab91e8797db09356a30e93022c4e1d', 'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍ وَٰحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَفْقَهُونَ', '8b400bc26245471bb100c1d95aa931d303ab91e8797db09356a30e93022c4e1d', '8b400bc26245471bb100c1d95aa931d303ab91e8797db09356a30e93022c4e1d', NULL, 'وهو الذي انشاكم من نفس وحده فمستقر ومستودع قد فصلنا الايت لقوم يفقهون', 7, 14, 56, 1, 2, 140, false, NULL),
    (888, 'tanzil-uthmani-v1.1', 6, 99, 'وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّٰتٍ مِّنْ أَعْنَابٍ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَٰبِهٍ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ إِنَّ فِى ذَٰلِكُمْ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '94cf846b528cd5f7b88c1a66433a408b597cc0007693888f596480b66601bb71', 'وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّٰتٍ مِّنْ أَعْنَابٍ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَٰبِهٍ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ إِنَّ فِى ذَٰلِكُمْ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '94cf846b528cd5f7b88c1a66433a408b597cc0007693888f596480b66601bb71', '94cf846b528cd5f7b88c1a66433a408b597cc0007693888f596480b66601bb71', NULL, 'وهو الذي انزل من السماء ماء فاخرجنا به نبات كل شيء فاخرجنا منه خضرا نخرج منه حبا متراكبا ومن النخل من طلعها قنوان دانيه وجنت من اعناب والزيتون والرمان مشتبها وغير متشبه انظروا الي ثمره اذا اثمر وينعه ان في ذلكم لايت لقوم يؤمنون', 7, 14, 56, 1, 2, 140, false, NULL),
    (889, 'tanzil-uthmani-v1.1', 6, 100, 'وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَٰتٍۭ بِغَيْرِ عِلْمٍ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ', '665a4f3d1cdcc6a0a65c10342e72d6b8921184db27bc0f7830774c61e999797f', 'وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَٰتٍۭ بِغَيْرِ عِلْمٍ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ', '665a4f3d1cdcc6a0a65c10342e72d6b8921184db27bc0f7830774c61e999797f', '665a4f3d1cdcc6a0a65c10342e72d6b8921184db27bc0f7830774c61e999797f', NULL, 'وجعلوا لله شركاء الجن وخلقهم وخرقوا له بنين وبنت بغير علم سبحنه وتعلي عما يصفون', 7, 14, 56, 1, 2, 140, false, NULL),
    (890, 'tanzil-uthmani-v1.1', 6, 101, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌ وَلَمْ تَكُن لَّهُۥ صَٰحِبَةٌ وَخَلَقَ كُلَّ شَىْءٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '7057616e53546422a142b3fc1da6ca80d2423620105cf8bbb6c6822678ff4ea5', 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌ وَلَمْ تَكُن لَّهُۥ صَٰحِبَةٌ وَخَلَقَ كُلَّ شَىْءٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '7057616e53546422a142b3fc1da6ca80d2423620105cf8bbb6c6822678ff4ea5', '7057616e53546422a142b3fc1da6ca80d2423620105cf8bbb6c6822678ff4ea5', NULL, 'بديع السموت والارض اني يكون له ولد ولم تكن له صحبه وخلق كل شيء وهو بكل شيء عليم', 7, 14, 56, 1, 2, 140, false, NULL),
    (891, 'tanzil-uthmani-v1.1', 6, 102, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَآ إِلَٰهَ إِلَّا هُوَ خَٰلِقُ كُلِّ شَىْءٍ فَٱعْبُدُوهُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', 'fed8600ad67bc5e3af1affb4ee5941a253a50e8d52d39af22b3bca51f3f6b78a', 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَآ إِلَٰهَ إِلَّا هُوَ خَٰلِقُ كُلِّ شَىْءٍ فَٱعْبُدُوهُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', 'fed8600ad67bc5e3af1affb4ee5941a253a50e8d52d39af22b3bca51f3f6b78a', 'fed8600ad67bc5e3af1affb4ee5941a253a50e8d52d39af22b3bca51f3f6b78a', NULL, 'ذلكم الله ربكم لا اله الا هو خلق كل شيء فاعبدوه وهو علي كل شيء وكيل', 7, 14, 56, 1, 2, 141, false, NULL),
    (892, 'tanzil-uthmani-v1.1', 6, 103, 'لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'fe579db7331b5b0042f07b55b3846af379c57b75ca7efd4e5c6e86c0b98f3d07', 'لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'fe579db7331b5b0042f07b55b3846af379c57b75ca7efd4e5c6e86c0b98f3d07', 'fe579db7331b5b0042f07b55b3846af379c57b75ca7efd4e5c6e86c0b98f3d07', NULL, 'لا تدركه الابصر وهو يدرك الابصر وهو اللطيف الخبير', 7, 14, 56, 1, 2, 141, false, NULL),
    (893, 'tanzil-uthmani-v1.1', 6, 104, 'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ وَمَنْ عَمِىَ فَعَلَيْهَا وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', '883e93f76312095d5df9505570d4232488e10c1a0826c51408871a46c54900b8', 'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ وَمَنْ عَمِىَ فَعَلَيْهَا وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', '883e93f76312095d5df9505570d4232488e10c1a0826c51408871a46c54900b8', '883e93f76312095d5df9505570d4232488e10c1a0826c51408871a46c54900b8', NULL, 'قد جاءكم بصائر من ربكم فمن ابصر فلنفسه ومن عمي فعليها وما انا عليكم بحفيظ', 7, 14, 56, 1, 2, 141, false, NULL),
    (894, 'tanzil-uthmani-v1.1', 6, 105, 'وَكَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍ يَعْلَمُونَ', '2dcda1c3606695138aae0933cc68bbd90372cdd8e1a14946ea633a082f914d38', 'وَكَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍ يَعْلَمُونَ', '2dcda1c3606695138aae0933cc68bbd90372cdd8e1a14946ea633a082f914d38', '2dcda1c3606695138aae0933cc68bbd90372cdd8e1a14946ea633a082f914d38', NULL, 'وكذلك نصرف الايت وليقولوا درست ولنبينه لقوم يعلمون', 7, 14, 56, 1, 2, 141, false, NULL),
    (895, 'tanzil-uthmani-v1.1', 6, 106, 'ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ لَآ إِلَٰهَ إِلَّا هُوَ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 'a57305d105dc613d46db8f579d308a836a6511bb483002c6d9f9946eea86035f', 'ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ لَآ إِلَٰهَ إِلَّا هُوَ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 'a57305d105dc613d46db8f579d308a836a6511bb483002c6d9f9946eea86035f', 'a57305d105dc613d46db8f579d308a836a6511bb483002c6d9f9946eea86035f', NULL, 'اتبع ما اوحي اليك من ربك لا اله الا هو واعرض عن المشركين', 7, 14, 56, 1, 2, 141, false, NULL),
    (896, 'tanzil-uthmani-v1.1', 6, 107, 'وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظًا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', '806a27c34b61976eba2efd8db60b0857c9d187a9939007dc4a07e947adf83249', 'وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظًا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', '806a27c34b61976eba2efd8db60b0857c9d187a9939007dc4a07e947adf83249', '806a27c34b61976eba2efd8db60b0857c9d187a9939007dc4a07e947adf83249', NULL, 'ولو شاء الله ما اشركوا وما جعلنك عليهم حفيظا وما انت عليهم بوكيل', 7, 14, 56, 1, 2, 141, false, NULL),
    (897, 'tanzil-uthmani-v1.1', 6, 108, 'وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'c1d2a4e55f5d9725a8a3a4cf7e72a92d18fe81b01e4c9be8e26e2992db1850ca', 'وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'c1d2a4e55f5d9725a8a3a4cf7e72a92d18fe81b01e4c9be8e26e2992db1850ca', 'c1d2a4e55f5d9725a8a3a4cf7e72a92d18fe81b01e4c9be8e26e2992db1850ca', NULL, 'ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم كذلك زينا لكل امه عملهم ثم الي ربهم مرجعهم فينبئهم بما كانوا يعملون', 7, 14, 56, 1, 2, 141, false, NULL),
    (898, 'tanzil-uthmani-v1.1', 6, 109, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌ لَّيُؤْمِنُنَّ بِهَا قُلْ إِنَّمَا ٱلْـَٔايَٰتُ عِندَ ٱللَّهِ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ', 'e3a6f797ef0fd31be4231e659b496700254f5d4216affcbc28184560ae9e8463', 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌ لَّيُؤْمِنُنَّ بِهَا قُلْ إِنَّمَا ٱلْـَٔايَٰتُ عِندَ ٱللَّهِ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ', 'e3a6f797ef0fd31be4231e659b496700254f5d4216affcbc28184560ae9e8463', 'e3a6f797ef0fd31be4231e659b496700254f5d4216affcbc28184560ae9e8463', NULL, 'واقسموا بالله جهد ايمنهم لئن جاءتهم ءايه ليؤمنن بها قل انما الايت عند الله وما يشعركم انها اذا جاءت لا يؤمنون', 7, 14, 56, 1, 2, 141, false, NULL),
    (899, 'tanzil-uthmani-v1.1', 6, 110, 'وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'b17cff68ab729409104f97845e87ff22c61bed7978093b75edf2d3bd6ba1f790', 'وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'b17cff68ab729409104f97845e87ff22c61bed7978093b75edf2d3bd6ba1f790', 'b17cff68ab729409104f97845e87ff22c61bed7978093b75edf2d3bd6ba1f790', NULL, 'ونقلب افدتهم وابصرهم كما لم يؤمنوا به اول مره ونذرهم في طغينهم يعمهون', 7, 14, 56, 1, 2, 141, false, NULL),
    (900, 'tanzil-uthmani-v1.1', 6, 111, 'وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍ قُبُلًا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ', '3c48e6f8302bedac887fdbd4d7c3fcc8f939f18efb6912e09bc76cbbcbb38b18', 'وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍ قُبُلًا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ', '3c48e6f8302bedac887fdbd4d7c3fcc8f939f18efb6912e09bc76cbbcbb38b18', '3c48e6f8302bedac887fdbd4d7c3fcc8f939f18efb6912e09bc76cbbcbb38b18', NULL, 'ولو اننا نزلنا اليهم الملئكه وكلمهم الموتي وحشرنا عليهم كل شيء قبلا ما كانوا ليؤمنوا الا ان يشاء الله ولكن اكثرهم يجهلون', 8, 15, 57, 1, 2, 142, false, NULL),
    (901, 'tanzil-uthmani-v1.1', 6, 112, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا شَيَٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ ٱلْقَوْلِ غُرُورًا وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', '02c3389fe85ece2450224a8b893f02b9a1661695e0df2186c0af5570dcbdd519', 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا شَيَٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ ٱلْقَوْلِ غُرُورًا وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', '02c3389fe85ece2450224a8b893f02b9a1661695e0df2186c0af5570dcbdd519', '02c3389fe85ece2450224a8b893f02b9a1661695e0df2186c0af5570dcbdd519', NULL, 'وكذلك جعلنا لكل نبي عدوا شيطين الانس والجن يوحي بعضهم الي بعض زخرف القول غرورا ولو شاء ربك ما فعلوه فذرهم وما يفترون', 8, 15, 57, 1, 2, 142, false, NULL),
    (902, 'tanzil-uthmani-v1.1', 6, 113, 'وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ', 'b8300744cbc24a1ec308131f9cfbc748096df5449d0bc364805747763df63729', 'وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ', 'b8300744cbc24a1ec308131f9cfbc748096df5449d0bc364805747763df63729', 'b8300744cbc24a1ec308131f9cfbc748096df5449d0bc364805747763df63729', NULL, 'ولتصغي اليه افده الذين لا يؤمنون بالاخره وليرضوه وليقترفوا ما هم مقترفون', 8, 15, 57, 1, 2, 142, false, NULL),
    (903, 'tanzil-uthmani-v1.1', 6, 114, 'أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَٰبَ مُفَصَّلًا وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌ مِّن رَّبِّكَ بِٱلْحَقِّ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', '897176485c906cc9330ed74041ad3852064464a78ccadc8754f24b4acff2982a', 'أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَٰبَ مُفَصَّلًا وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌ مِّن رَّبِّكَ بِٱلْحَقِّ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', '897176485c906cc9330ed74041ad3852064464a78ccadc8754f24b4acff2982a', '897176485c906cc9330ed74041ad3852064464a78ccadc8754f24b4acff2982a', NULL, 'افغير الله ابتغي حكما وهو الذي انزل اليكم الكتب مفصلا والذين ءاتينهم الكتب يعلمون انه منزل من ربك بالحق فلا تكونن من الممترين', 8, 15, 57, 1, 2, 142, false, NULL),
    (904, 'tanzil-uthmani-v1.1', 6, 115, 'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '7ffe31742163c26e74e693fc6a9d269b71dd6067ba6bf894fad639a25d2126ac', 'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '7ffe31742163c26e74e693fc6a9d269b71dd6067ba6bf894fad639a25d2126ac', '7ffe31742163c26e74e693fc6a9d269b71dd6067ba6bf894fad639a25d2126ac', NULL, 'وتمت كلمت ربك صدقا وعدلا لا مبدل لكلمته وهو السميع العليم', 8, 15, 57, 1, 2, 142, false, NULL),
    (905, 'tanzil-uthmani-v1.1', 6, 116, 'وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 'b5e4e304875b9a3228b8cda448e6b20abd8a1371142dae4d31d619db7c8c73af', 'وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 'b5e4e304875b9a3228b8cda448e6b20abd8a1371142dae4d31d619db7c8c73af', 'b5e4e304875b9a3228b8cda448e6b20abd8a1371142dae4d31d619db7c8c73af', NULL, 'وان تطع اكثر من في الارض يضلوك عن سبيل الله ان يتبعون الا الظن وان هم الا يخرصون', 8, 15, 57, 1, 2, 142, false, NULL),
    (906, 'tanzil-uthmani-v1.1', 6, 117, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', '6fe83994c2f4c1990d6b57d60d877a7ff319b35539e7183dfb25394366cad74a', 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', '6fe83994c2f4c1990d6b57d60d877a7ff319b35539e7183dfb25394366cad74a', '6fe83994c2f4c1990d6b57d60d877a7ff319b35539e7183dfb25394366cad74a', NULL, 'ان ربك هو اعلم من يضل عن سبيله وهو اعلم بالمهتدين', 8, 15, 57, 1, 2, 142, false, NULL),
    (907, 'tanzil-uthmani-v1.1', 6, 118, 'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤْمِنِينَ', '59fb792e2be5302bfdea785dc2c057cc0373c70d0fd30dfb14728032aa06a556', 'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤْمِنِينَ', '59fb792e2be5302bfdea785dc2c057cc0373c70d0fd30dfb14728032aa06a556', '59fb792e2be5302bfdea785dc2c057cc0373c70d0fd30dfb14728032aa06a556', NULL, 'فكلوا مما ذكر اسم الله عليه ان كنتم بايته مؤمنين', 8, 15, 57, 1, 2, 142, false, NULL),
    (908, 'tanzil-uthmani-v1.1', 6, 119, 'وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ', '0f75d4c1e096ede0b75fae084396b3d19acb6be9968cb1dfdb8301d70bea5138', 'وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ', '0f75d4c1e096ede0b75fae084396b3d19acb6be9968cb1dfdb8301d70bea5138', '0f75d4c1e096ede0b75fae084396b3d19acb6be9968cb1dfdb8301d70bea5138', NULL, 'وما لكم الا تاكلوا مما ذكر اسم الله عليه وقد فصل لكم ما حرم عليكم الا ما اضطررتم اليه وان كثيرا ليضلون باهوائهم بغير علم ان ربك هو اعلم بالمعتدين', 8, 15, 57, 1, 2, 143, false, NULL),
    (909, 'tanzil-uthmani-v1.1', 6, 120, 'وَذَرُوا۟ ظَٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ', 'd918e29d8ea86a5bde2c51093ad77a64fbc40f423db9d9f181be1b203d159d74', 'وَذَرُوا۟ ظَٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ', 'd918e29d8ea86a5bde2c51093ad77a64fbc40f423db9d9f181be1b203d159d74', 'd918e29d8ea86a5bde2c51093ad77a64fbc40f423db9d9f181be1b203d159d74', NULL, 'وذروا ظهر الاثم وباطنه ان الذين يكسبون الاثم سيجزون بما كانوا يقترفون', 8, 15, 57, 1, 2, 143, false, NULL),
    (910, 'tanzil-uthmani-v1.1', 6, 121, 'وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَٰدِلُوكُمْ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ', 'c8c2989193188b30b56a6afa114e121c3f6ebed8b0bb23a81755b76e47aca1ac', 'وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَٰدِلُوكُمْ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ', 'c8c2989193188b30b56a6afa114e121c3f6ebed8b0bb23a81755b76e47aca1ac', 'c8c2989193188b30b56a6afa114e121c3f6ebed8b0bb23a81755b76e47aca1ac', NULL, 'ولا تاكلوا مما لم يذكر اسم الله عليه وانه لفسق وان الشيطين ليوحون الي اوليائهم ليجدلوكم وان اطعتموهم انكم لمشركون', 8, 15, 57, 1, 2, 143, false, NULL),
    (911, 'tanzil-uthmani-v1.1', 6, 122, 'أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُورًا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَٰتِ لَيْسَ بِخَارِجٍ مِّنْهَا كَذَٰلِكَ زُيِّنَ لِلْكَٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ', 'a2bdd067d7d9c3e6e4849996c3b44108ec70d0bc4bcbfa976bb5568c66e97fb3', 'أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُورًا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَٰتِ لَيْسَ بِخَارِجٍ مِّنْهَا كَذَٰلِكَ زُيِّنَ لِلْكَٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ', 'a2bdd067d7d9c3e6e4849996c3b44108ec70d0bc4bcbfa976bb5568c66e97fb3', 'a2bdd067d7d9c3e6e4849996c3b44108ec70d0bc4bcbfa976bb5568c66e97fb3', NULL, 'اومن كان ميتا فاحيينه وجعلنا له نورا يمشي به في الناس كمن مثله في الظلمت ليس بخارج منها كذلك زين للكفرين ما كانوا يعملون', 8, 15, 57, 1, 2, 143, false, NULL),
    (912, 'tanzil-uthmani-v1.1', 6, 123, 'وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ', 'dd6250631ef883f50fd80a10b791636d5fdaf8bc8cfe25796770ef225f234544', 'وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ', 'dd6250631ef883f50fd80a10b791636d5fdaf8bc8cfe25796770ef225f234544', 'dd6250631ef883f50fd80a10b791636d5fdaf8bc8cfe25796770ef225f234544', NULL, 'وكذلك جعلنا في كل قريه اكبر مجرميها ليمكروا فيها وما يمكرون الا بانفسهم وما يشعرون', 8, 15, 57, 1, 2, 143, false, NULL),
    (913, 'tanzil-uthmani-v1.1', 6, 124, 'وَإِذَا جَآءَتْهُمْ ءَايَةٌ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ', 'e9cc7a3611b68b3eedbdafd37418c45be494594775c3532020b46e05c10253ac', 'وَإِذَا جَآءَتْهُمْ ءَايَةٌ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ', 'e9cc7a3611b68b3eedbdafd37418c45be494594775c3532020b46e05c10253ac', 'e9cc7a3611b68b3eedbdafd37418c45be494594775c3532020b46e05c10253ac', NULL, 'واذا جاءتهم ءايه قالوا لن نؤمن حتي نؤتي مثل ما اوتي رسل الله الله اعلم حيث يجعل رسالته سيصيب الذين اجرموا صغار عند الله وعذاب شديد بما كانوا يمكرون', 8, 15, 57, 1, 2, 143, false, NULL),
    (914, 'tanzil-uthmani-v1.1', 6, 125, 'فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَٰمِ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ', '0315b7c614025ef803b4bf28e5df29e9cf20be90db93b1b9228577ebf6be94c1', 'فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَٰمِ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ', '0315b7c614025ef803b4bf28e5df29e9cf20be90db93b1b9228577ebf6be94c1', '0315b7c614025ef803b4bf28e5df29e9cf20be90db93b1b9228577ebf6be94c1', NULL, 'فمن يرد الله ان يهديه يشرح صدره للاسلم ومن يرد ان يضله يجعل صدره ضيقا حرجا كانما يصعد في السماء كذلك يجعل الله الرجس علي الذين لا يؤمنون', 8, 15, 57, 1, 2, 144, false, NULL),
    (915, 'tanzil-uthmani-v1.1', 6, 126, 'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًا قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَذَّكَّرُونَ', '83c0d717498f556b50521fe1b5bd7e23f0650c388666b525b4b6dba35d115de7', 'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًا قَدْ فَصَّلْنَا ٱلْـَٔايَٰتِ لِقَوْمٍ يَذَّكَّرُونَ', '83c0d717498f556b50521fe1b5bd7e23f0650c388666b525b4b6dba35d115de7', '83c0d717498f556b50521fe1b5bd7e23f0650c388666b525b4b6dba35d115de7', NULL, 'وهذا صرط ربك مستقيما قد فصلنا الايت لقوم يذكرون', 8, 15, 57, 1, 2, 144, false, NULL),
    (916, 'tanzil-uthmani-v1.1', 6, 127, 'لَهُمْ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمْ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ', '5e07258a43645a52dc3b51bc00878916069efcb1982c664d9b47be079237d4a5', 'لَهُمْ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمْ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ', '5e07258a43645a52dc3b51bc00878916069efcb1982c664d9b47be079237d4a5', '5e07258a43645a52dc3b51bc00878916069efcb1982c664d9b47be079237d4a5', NULL, 'لهم دار السلم عند ربهم وهو وليهم بما كانوا يعملون', 8, 15, 58, 1, 2, 144, false, NULL),
    (917, 'tanzil-uthmani-v1.1', 6, 128, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', '3b1253fdab5344686af639a6a3c3693f6f868e54e06b8d78ab8eeb8aa8205b59', 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ', '3b1253fdab5344686af639a6a3c3693f6f868e54e06b8d78ab8eeb8aa8205b59', '3b1253fdab5344686af639a6a3c3693f6f868e54e06b8d78ab8eeb8aa8205b59', NULL, 'ويوم يحشرهم جميعا يمعشر الجن قد استكثرتم من الانس وقال اولياؤهم من الانس ربنا استمتع بعضنا ببعض وبلغنا اجلنا الذي اجلت لنا قال النار مثويكم خلدين فيها الا ما شاء الله ان ربك حكيم عليم', 8, 15, 58, 1, 2, 144, false, NULL),
    (918, 'tanzil-uthmani-v1.1', 6, 129, 'وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 'c7dbb6e6d82ef8363a38d415a90655fd7d54eac6054accd2b564bcf374c2e4a2', 'وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 'c7dbb6e6d82ef8363a38d415a90655fd7d54eac6054accd2b564bcf374c2e4a2', 'c7dbb6e6d82ef8363a38d415a90655fd7d54eac6054accd2b564bcf374c2e4a2', NULL, 'وكذلك نولي بعض الظلمين بعضا بما كانوا يكسبون', 8, 15, 58, 1, 2, 144, false, NULL),
    (919, 'tanzil-uthmani-v1.1', 6, 130, 'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', '38b93e0d148a23fc1fdaf3277764f412c1e2e494b4e309426f77a00c9d06df00', 'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', '38b93e0d148a23fc1fdaf3277764f412c1e2e494b4e309426f77a00c9d06df00', '38b93e0d148a23fc1fdaf3277764f412c1e2e494b4e309426f77a00c9d06df00', NULL, 'يمعشر الجن والانس الم ياتكم رسل منكم يقصون عليكم ءايتي وينذرونكم لقاء يومكم هذا قالوا شهدنا علي انفسنا وغرتهم الحيوه الدنيا وشهدوا علي انفسهم انهم كانوا كفرين', 8, 15, 58, 1, 2, 144, false, NULL),
    (920, 'tanzil-uthmani-v1.1', 6, 131, 'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَٰفِلُونَ', 'ab89ff330ac351cd7bb9c6bb050b5645e5b9cc106493bc8229fb94fb05a7d637', 'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَٰفِلُونَ', 'ab89ff330ac351cd7bb9c6bb050b5645e5b9cc106493bc8229fb94fb05a7d637', 'ab89ff330ac351cd7bb9c6bb050b5645e5b9cc106493bc8229fb94fb05a7d637', NULL, 'ذلك ان لم يكن ربك مهلك القري بظلم واهلها غفلون', 8, 15, 58, 1, 2, 144, false, NULL),
    (921, 'tanzil-uthmani-v1.1', 6, 132, 'وَلِكُلٍّ دَرَجَٰتٌ مِّمَّا عَمِلُوا۟ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'c4392aa4b49c5312c23438b7b5d27db29ee2319dca56191a03e6b2d87198fafa', 'وَلِكُلٍّ دَرَجَٰتٌ مِّمَّا عَمِلُوا۟ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 'c4392aa4b49c5312c23438b7b5d27db29ee2319dca56191a03e6b2d87198fafa', 'c4392aa4b49c5312c23438b7b5d27db29ee2319dca56191a03e6b2d87198fafa', NULL, 'ولكل درجت مما عملوا وما ربك بغفل عما يعملون', 8, 15, 58, 1, 2, 145, false, NULL),
    (922, 'tanzil-uthmani-v1.1', 6, 133, 'وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ', '334230f7753b28910be0546757623ae8764937afdab3e949276a6011f4f6c777', 'وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ', '334230f7753b28910be0546757623ae8764937afdab3e949276a6011f4f6c777', '334230f7753b28910be0546757623ae8764937afdab3e949276a6011f4f6c777', NULL, 'وربك الغني ذو الرحمه ان يشا يذهبكم ويستخلف من بعدكم ما يشاء كما انشاكم من ذريه قوم ءاخرين', 8, 15, 58, 1, 2, 145, false, NULL),
    (923, 'tanzil-uthmani-v1.1', 6, 134, 'إِنَّ مَا تُوعَدُونَ لَـَٔاتٍ وَمَآ أَنتُم بِمُعْجِزِينَ', '1af4da27d66be1b107ec155b7ab08cc94638c0e6d7ec83a90e0274739a577481', 'إِنَّ مَا تُوعَدُونَ لَـَٔاتٍ وَمَآ أَنتُم بِمُعْجِزِينَ', '1af4da27d66be1b107ec155b7ab08cc94638c0e6d7ec83a90e0274739a577481', '1af4da27d66be1b107ec155b7ab08cc94638c0e6d7ec83a90e0274739a577481', NULL, 'ان ما توعدون لات وما انتم بمعجزين', 8, 15, 58, 1, 2, 145, false, NULL),
    (924, 'tanzil-uthmani-v1.1', 6, 135, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', '62428095d5334a7e14883605ae77efd72934b169f5eabad4429c2dfa5d5d620d', 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', '62428095d5334a7e14883605ae77efd72934b169f5eabad4429c2dfa5d5d620d', '62428095d5334a7e14883605ae77efd72934b169f5eabad4429c2dfa5d5d620d', NULL, 'قل يقوم اعملوا علي مكانتكم اني عامل فسوف تعلمون من تكون له عقبه الدار انه لا يفلح الظلمون', 8, 15, 58, 1, 2, 145, false, NULL),
    (925, 'tanzil-uthmani-v1.1', 6, 136, 'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَٰمِ نَصِيبًا فَقَالُوا۟ هَٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَآئِنَا فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ سَآءَ مَا يَحْكُمُونَ', 'b51c5f05a5695d4ee548f450afe3757f7b4447226d82fd80b04056065f72282c', 'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَٰمِ نَصِيبًا فَقَالُوا۟ هَٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَآئِنَا فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ سَآءَ مَا يَحْكُمُونَ', 'b51c5f05a5695d4ee548f450afe3757f7b4447226d82fd80b04056065f72282c', 'b51c5f05a5695d4ee548f450afe3757f7b4447226d82fd80b04056065f72282c', NULL, 'وجعلوا لله مما ذرا من الحرث والانعم نصيبا فقالوا هذا لله بزعمهم وهذا لشركائنا فما كان لشركائهم فلا يصل الي الله وما كان لله فهو يصل الي شركائهم ساء ما يحكمون', 8, 15, 58, 1, 2, 145, false, NULL),
    (926, 'tanzil-uthmani-v1.1', 6, 137, 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'bd6b15fcd337bc10768e77abe1fefeb22ed754b6a26e696feeeb41b470d4318b', 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 'bd6b15fcd337bc10768e77abe1fefeb22ed754b6a26e696feeeb41b470d4318b', 'bd6b15fcd337bc10768e77abe1fefeb22ed754b6a26e696feeeb41b470d4318b', NULL, 'وكذلك زين لكثير من المشركين قتل اولدهم شركاؤهم ليردوهم وليلبسوا عليهم دينهم ولو شاء الله ما فعلوه فذرهم وما يفترون', 8, 15, 58, 1, 2, 145, false, NULL),
    (927, 'tanzil-uthmani-v1.1', 6, 138, 'وَقَالُوا۟ هَٰذِهِۦٓ أَنْعَٰمٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَٰمٌ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ', 'd37c4b07dbfd2fe55de2c58f4de91415a9bf78ff28ca12f2e60a2a7ac211603b', 'وَقَالُوا۟ هَٰذِهِۦٓ أَنْعَٰمٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَٰمٌ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ', 'd37c4b07dbfd2fe55de2c58f4de91415a9bf78ff28ca12f2e60a2a7ac211603b', 'd37c4b07dbfd2fe55de2c58f4de91415a9bf78ff28ca12f2e60a2a7ac211603b', NULL, 'وقالوا هذه انعم وحرث حجر لا يطعمها الا من نشاء بزعمهم وانعم حرمت ظهورها وانعم لا يذكرون اسم الله عليها افتراء عليه سيجزيهم بما كانوا يفترون', 8, 15, 58, 1, 2, 146, false, NULL),
    (928, 'tanzil-uthmani-v1.1', 6, 139, 'وَقَالُوا۟ مَا فِى بُطُونِ هَٰذِهِ ٱلْأَنْعَٰمِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَآءُ سَيَجْزِيهِمْ وَصْفَهُمْ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', 'ac981f251b108a1e6132c20b3761e76dede15fb007a4eed3fdd17386bee316a5', 'وَقَالُوا۟ مَا فِى بُطُونِ هَٰذِهِ ٱلْأَنْعَٰمِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَآءُ سَيَجْزِيهِمْ وَصْفَهُمْ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', 'ac981f251b108a1e6132c20b3761e76dede15fb007a4eed3fdd17386bee316a5', 'ac981f251b108a1e6132c20b3761e76dede15fb007a4eed3fdd17386bee316a5', NULL, 'وقالوا ما في بطون هذه الانعم خالصه لذكورنا ومحرم علي ازوجنا وان يكن ميته فهم فيه شركاء سيجزيهم وصفهم انه حكيم عليم', 8, 15, 58, 1, 2, 146, false, NULL),
    (929, 'tanzil-uthmani-v1.1', 6, 140, 'قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ', 'e426a808a7ad700c6b6ec9ab6c1997e46c319fe0023f6695f917d65762231515', 'قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ', 'e426a808a7ad700c6b6ec9ab6c1997e46c319fe0023f6695f917d65762231515', 'e426a808a7ad700c6b6ec9ab6c1997e46c319fe0023f6695f917d65762231515', NULL, 'قد خسر الذين قتلوا اولدهم سفها بغير علم وحرموا ما رزقهم الله افتراء علي الله قد ضلوا وما كانوا مهتدين', 8, 15, 58, 1, 2, 146, false, NULL),
    (930, 'tanzil-uthmani-v1.1', 6, 141, 'وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّٰتٍ مَّعْرُوشَٰتٍ وَغَيْرَ مَعْرُوشَٰتٍ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهًا وَغَيْرَ مُتَشَٰبِهٍ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 'cf3aef953f84676133261bb6e9b1e64cb0f5c906d9f361539f531f95748e46e5', 'وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّٰتٍ مَّعْرُوشَٰتٍ وَغَيْرَ مَعْرُوشَٰتٍ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهًا وَغَيْرَ مُتَشَٰبِهٍ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 'cf3aef953f84676133261bb6e9b1e64cb0f5c906d9f361539f531f95748e46e5', 'cf3aef953f84676133261bb6e9b1e64cb0f5c906d9f361539f531f95748e46e5', NULL, 'وهو الذي انشا جنت معروشت وغير معروشت والنخل والزرع مختلفا اكله والزيتون والرمان متشبها وغير متشبه كلوا من ثمره اذا اثمر وءاتوا حقه يوم حصاده ولا تسرفوا انه لا يحب المسرفين', 8, 15, 59, 1, 2, 146, false, NULL),
    (931, 'tanzil-uthmani-v1.1', 6, 142, 'وَمِنَ ٱلْأَنْعَٰمِ حَمُولَةً وَفَرْشًا كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'c6b5405e32157d20152567ae23babd8926af85f2f2dc12344d298f8f951f9fa0', 'وَمِنَ ٱلْأَنْعَٰمِ حَمُولَةً وَفَرْشًا كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', 'c6b5405e32157d20152567ae23babd8926af85f2f2dc12344d298f8f951f9fa0', 'c6b5405e32157d20152567ae23babd8926af85f2f2dc12344d298f8f951f9fa0', NULL, 'ومن الانعم حموله وفرشا كلوا مما رزقكم الله ولا تتبعوا خطوت الشيطن انه لكم عدو مبين', 8, 15, 59, 1, 2, 146, false, NULL),
    (932, 'tanzil-uthmani-v1.1', 6, 143, 'ثَمَٰنِيَةَ أَزْوَٰجٍ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', 'e195068a9439e88bb2d52ed58a9ef925858212306c29d79e5a989cac15359fca', 'ثَمَٰنِيَةَ أَزْوَٰجٍ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', 'e195068a9439e88bb2d52ed58a9ef925858212306c29d79e5a989cac15359fca', 'e195068a9439e88bb2d52ed58a9ef925858212306c29d79e5a989cac15359fca', NULL, 'ثمنيه ازوج من الضان اثنين ومن المعز اثنين قل ءالذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين نبوني بعلم ان كنتم صدقين', 8, 15, 59, 1, 2, 147, false, NULL),
    (933, 'tanzil-uthmani-v1.1', 6, 144, 'وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَا فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '16809108cbae968fd8aefefd8d3ba755ac9ed47a8234ad35763bfe414a0e697e', 'وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَا فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '16809108cbae968fd8aefefd8d3ba755ac9ed47a8234ad35763bfe414a0e697e', '16809108cbae968fd8aefefd8d3ba755ac9ed47a8234ad35763bfe414a0e697e', NULL, 'ومن الابل اثنين ومن البقر اثنين قل ءالذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين ام كنتم شهداء اذ وصيكم الله بهذا فمن اظلم ممن افتري علي الله كذبا ليضل الناس بغير علم ان الله لا يهدي القوم الظلمين', 8, 15, 59, 1, 2, 147, false, NULL),
    (934, 'tanzil-uthmani-v1.1', 6, 145, 'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ', '736e875d465bdbb2f9c6254ded7d4c78c7fb3596f341138cb39b38b05fdd8d4e', 'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ', '736e875d465bdbb2f9c6254ded7d4c78c7fb3596f341138cb39b38b05fdd8d4e', '736e875d465bdbb2f9c6254ded7d4c78c7fb3596f341138cb39b38b05fdd8d4e', NULL, 'قل لا اجد في ما اوحي الي محرما علي طاعم يطعمه الا ان يكون ميته او دما مسفوحا او لحم خنزير فانه رجس او فسقا اهل لغير الله به فمن اضطر غير باغ ولا عاد فان ربك غفور رحيم', 8, 15, 59, 1, 2, 147, false, NULL),
    (935, 'tanzil-uthmani-v1.1', 6, 146, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍ ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْ وَإِنَّا لَصَٰدِقُونَ', '0a378225e8130f853d488f4b734f92b014642570950fb10ce0048aef6544ee10', 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍ ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْ وَإِنَّا لَصَٰدِقُونَ', '0a378225e8130f853d488f4b734f92b014642570950fb10ce0048aef6544ee10', '0a378225e8130f853d488f4b734f92b014642570950fb10ce0048aef6544ee10', NULL, 'وعلي الذين هادوا حرمنا كل ذي ظفر ومن البقر والغنم حرمنا عليهم شحومهما الا ما حملت ظهورهما او الحوايا او ما اختلط بعظم ذلك جزينهم ببغيهم وانا لصدقون', 8, 15, 59, 1, 2, 147, false, NULL),
    (936, 'tanzil-uthmani-v1.1', 6, 147, 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَٰسِعَةٍ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', '7cb38af130fc2f6833cd793218fe67179afa5a8546cbbfccdefee78f8ce20653', 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَٰسِعَةٍ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', '7cb38af130fc2f6833cd793218fe67179afa5a8546cbbfccdefee78f8ce20653', '7cb38af130fc2f6833cd793218fe67179afa5a8546cbbfccdefee78f8ce20653', NULL, 'فان كذبوك فقل ربكم ذو رحمه وسعه ولا يرد باسه عن القوم المجرمين', 8, 15, 59, 1, 2, 148, false, NULL),
    (937, 'tanzil-uthmani-v1.1', 6, 148, 'سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ', '6375c97157602faf564384de28762ef9917ba955f77584360c73d042ea4f326d', 'سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ', '6375c97157602faf564384de28762ef9917ba955f77584360c73d042ea4f326d', '6375c97157602faf564384de28762ef9917ba955f77584360c73d042ea4f326d', NULL, 'سيقول الذين اشركوا لو شاء الله ما اشركنا ولا ءاباؤنا ولا حرمنا من شيء كذلك كذب الذين من قبلهم حتي ذاقوا باسنا قل هل عندكم من علم فتخرجوه لنا ان تتبعون الا الظن وان انتم الا تخرصون', 8, 15, 59, 1, 2, 148, false, NULL),
    (938, 'tanzil-uthmani-v1.1', 6, 149, 'قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَٰلِغَةُ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', '6145890e447e364c3303065c2c70c6ddcab283741de0f352c0cf9efc469dca03', 'قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَٰلِغَةُ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', '6145890e447e364c3303065c2c70c6ddcab283741de0f352c0cf9efc469dca03', '6145890e447e364c3303065c2c70c6ddcab283741de0f352c0cf9efc469dca03', NULL, 'قل فلله الحجه البلغه فلو شاء لهديكم اجمعين', 8, 15, 59, 1, 2, 148, false, NULL),
    (939, 'tanzil-uthmani-v1.1', 6, 150, 'قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَا فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ', 'd42c753ced6445f3ed51db71964d75ced118390997111a5067e1ee08de10bc6e', 'قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَا فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ', 'd42c753ced6445f3ed51db71964d75ced118390997111a5067e1ee08de10bc6e', 'd42c753ced6445f3ed51db71964d75ced118390997111a5067e1ee08de10bc6e', NULL, 'قل هلم شهداءكم الذين يشهدون ان الله حرم هذا فان شهدوا فلا تشهد معهم ولا تتبع اهواء الذين كذبوا بايتنا والذين لا يؤمنون بالاخره وهم بربهم يعدلون', 8, 15, 59, 1, 2, 148, false, NULL),
    (940, 'tanzil-uthmani-v1.1', 6, 151, 'قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُم مِّنْ إِمْلَٰقٍ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '1fd71681cd5e7fd9b6edc2979568a59a0974a82afb6ff748b79f2bfd9591b245', 'قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُم مِّنْ إِمْلَٰقٍ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', '1fd71681cd5e7fd9b6edc2979568a59a0974a82afb6ff748b79f2bfd9591b245', '1fd71681cd5e7fd9b6edc2979568a59a0974a82afb6ff748b79f2bfd9591b245', NULL, 'قل تعالوا اتل ما حرم ربكم عليكم الا تشركوا به شيا وبالولدين احسنا ولا تقتلوا اولدكم من املق نحن نرزقكم واياهم ولا تقربوا الفوحش ما ظهر منها وما بطن ولا تقتلوا النفس التي حرم الله الا بالحق ذلكم وصيكم به لعلكم تعقلون', 8, 15, 60, 1, 2, 148, false, NULL),
    (941, 'tanzil-uthmani-v1.1', 6, 152, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ', 'b1d46f303165e9f922a8383020d0b2a98614d08c7a50802c83b3dd2376562a0a', 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ', 'b1d46f303165e9f922a8383020d0b2a98614d08c7a50802c83b3dd2376562a0a', 'b1d46f303165e9f922a8383020d0b2a98614d08c7a50802c83b3dd2376562a0a', NULL, 'ولا تقربوا مال اليتيم الا بالتي هي احسن حتي يبلغ اشده واوفوا الكيل والميزان بالقسط لا نكلف نفسا الا وسعها واذا قلتم فاعدلوا ولو كان ذا قربي وبعهد الله اوفوا ذلكم وصيكم به لعلكم تذكرون', 8, 15, 60, 1, 2, 149, false, NULL),
    (942, 'tanzil-uthmani-v1.1', 6, 153, 'وَأَنَّ هَٰذَا صِرَٰطِى مُسْتَقِيمًا فَٱتَّبِعُوهُ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ', 'b2d996a5bf62cab9bd6d6c59b1dab1f33604a06358203c6a80ae062e237a67e5', 'وَأَنَّ هَٰذَا صِرَٰطِى مُسْتَقِيمًا فَٱتَّبِعُوهُ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ', 'b2d996a5bf62cab9bd6d6c59b1dab1f33604a06358203c6a80ae062e237a67e5', 'b2d996a5bf62cab9bd6d6c59b1dab1f33604a06358203c6a80ae062e237a67e5', NULL, 'وان هذا صرطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله ذلكم وصيكم به لعلكم تتقون', 8, 15, 60, 1, 2, 149, false, NULL),
    (943, 'tanzil-uthmani-v1.1', 6, 154, 'ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ', '13bf680bffb54984bd6239700c637272c12b068651640f03bbf8e85579b55c5d', 'ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ', '13bf680bffb54984bd6239700c637272c12b068651640f03bbf8e85579b55c5d', '13bf680bffb54984bd6239700c637272c12b068651640f03bbf8e85579b55c5d', NULL, 'ثم ءاتينا موسي الكتب تماما علي الذي احسن وتفصيلا لكل شيء وهدي ورحمه لعلهم بلقاء ربهم يؤمنون', 8, 15, 60, 1, 2, 149, false, NULL),
    (944, 'tanzil-uthmani-v1.1', 6, 155, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', '53a5df7e57581903236917c2e9f1a24c6f7c920486856e0236878e61ca0d7283', 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', '53a5df7e57581903236917c2e9f1a24c6f7c920486856e0236878e61ca0d7283', '53a5df7e57581903236917c2e9f1a24c6f7c920486856e0236878e61ca0d7283', NULL, 'وهذا كتب انزلنه مبارك فاتبعوه واتقوا لعلكم ترحمون', 8, 15, 60, 1, 2, 149, false, NULL),
    (945, 'tanzil-uthmani-v1.1', 6, 156, 'أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَٰفِلِينَ', '4736edd527fefa9bfe390bf3fad5ea99303ef55d771db563dac468d0b4a016aa', 'أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَٰفِلِينَ', '4736edd527fefa9bfe390bf3fad5ea99303ef55d771db563dac468d0b4a016aa', '4736edd527fefa9bfe390bf3fad5ea99303ef55d771db563dac468d0b4a016aa', NULL, 'ان تقولوا انما انزل الكتب علي طائفتين من قبلنا وان كنا عن دراستهم لغفلين', 8, 15, 60, 1, 2, 149, false, NULL),
    (946, 'tanzil-uthmani-v1.1', 6, 157, 'أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ فَقَدْ جَآءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ', 'fe8579d89a70ca256bb38368aa4551f59347c8f47adbb64d103cd7230410122f', 'أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ فَقَدْ جَآءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ', 'fe8579d89a70ca256bb38368aa4551f59347c8f47adbb64d103cd7230410122f', 'fe8579d89a70ca256bb38368aa4551f59347c8f47adbb64d103cd7230410122f', NULL, 'او تقولوا لو انا انزل علينا الكتب لكنا اهدي منهم فقد جاءكم بينه من ربكم وهدي ورحمه فمن اظلم ممن كذب بايت الله وصدف عنها سنجزي الذين يصدفون عن ءايتنا سوء العذاب بما كانوا يصدفون', 8, 15, 60, 1, 2, 149, false, NULL),
    (947, 'tanzil-uthmani-v1.1', 6, 158, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَٰتِ رَبِّكَ يَوْمَ يَأْتِى بَعْضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَٰنِهَا خَيْرًا قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', '2a0943ff9ef6094d5a3d6104ac8d81a0783e96d6b02bbb1945c28348459d1bea', 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَٰتِ رَبِّكَ يَوْمَ يَأْتِى بَعْضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَٰنِهَا خَيْرًا قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', '2a0943ff9ef6094d5a3d6104ac8d81a0783e96d6b02bbb1945c28348459d1bea', '2a0943ff9ef6094d5a3d6104ac8d81a0783e96d6b02bbb1945c28348459d1bea', NULL, 'هل ينظرون الا ان تاتيهم الملئكه او ياتي ربك او ياتي بعض ءايت ربك يوم ياتي بعض ءايت ربك لا ينفع نفسا ايمنها لم تكن ءامنت من قبل او كسبت في ايمنها خيرا قل انتظروا انا منتظرون', 8, 15, 60, 1, 2, 150, false, NULL),
    (948, 'tanzil-uthmani-v1.1', 6, 159, 'إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا لَّسْتَ مِنْهُمْ فِى شَىْءٍ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ', '32e1a6ae89ad1260cf9a966ae4cb44c1d084b0b8de1e3dda2f5ad5a3776847ac', 'إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا لَّسْتَ مِنْهُمْ فِى شَىْءٍ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ', '32e1a6ae89ad1260cf9a966ae4cb44c1d084b0b8de1e3dda2f5ad5a3776847ac', '32e1a6ae89ad1260cf9a966ae4cb44c1d084b0b8de1e3dda2f5ad5a3776847ac', NULL, 'ان الذين فرقوا دينهم وكانوا شيعا لست منهم في شيء انما امرهم الي الله ثم ينبئهم بما كانوا يفعلون', 8, 15, 60, 1, 2, 150, false, NULL),
    (949, 'tanzil-uthmani-v1.1', 6, 160, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ', '199f1555f4b75dc492d7477c1b6162ce8d8590c7f9de68dd36f15a3074a61712', 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ', '199f1555f4b75dc492d7477c1b6162ce8d8590c7f9de68dd36f15a3074a61712', '199f1555f4b75dc492d7477c1b6162ce8d8590c7f9de68dd36f15a3074a61712', NULL, 'من جاء بالحسنه فله عشر امثالها ومن جاء بالسيئه فلا يجزي الا مثلها وهم لا يظلمون', 8, 15, 60, 1, 2, 150, false, NULL),
    (950, 'tanzil-uthmani-v1.1', 6, 161, 'قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '37cfb74c8264c960e3eb450fd66be3075d0c6dbcb7ed65d33cf26b60b7636c82', 'قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '37cfb74c8264c960e3eb450fd66be3075d0c6dbcb7ed65d33cf26b60b7636c82', '37cfb74c8264c960e3eb450fd66be3075d0c6dbcb7ed65d33cf26b60b7636c82', NULL, 'قل انني هديني ربي الي صرط مستقيم دينا قيما مله ابرهيم حنيفا وما كان من المشركين', 8, 15, 60, 1, 2, 150, false, NULL),
    (951, 'tanzil-uthmani-v1.1', 6, 162, 'قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', '48b2a11c2b09d3ef63a71e1a9addddf469afb58d29fab8d6d8c691d9e47f044d', 'قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', '48b2a11c2b09d3ef63a71e1a9addddf469afb58d29fab8d6d8c691d9e47f044d', '48b2a11c2b09d3ef63a71e1a9addddf469afb58d29fab8d6d8c691d9e47f044d', NULL, 'قل ان صلاتي ونسكي ومحياي ومماتي لله رب العلمين', 8, 15, 60, 1, 2, 150, false, NULL),
    (952, 'tanzil-uthmani-v1.1', 6, 163, 'لَا شَرِيكَ لَهُۥ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ', '5a0e78db40325a287a955ee1b400e851b12e033b497abaf483b262e795aed865', 'لَا شَرِيكَ لَهُۥ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ', '5a0e78db40325a287a955ee1b400e851b12e033b497abaf483b262e795aed865', '5a0e78db40325a287a955ee1b400e851b12e033b497abaf483b262e795aed865', NULL, 'لا شريك له وبذلك امرت وانا اول المسلمين', 8, 15, 60, 1, 2, 150, false, NULL),
    (953, 'tanzil-uthmani-v1.1', 6, 164, 'قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'af90b6236f9bf3d9801b7f9f03a612cdf1d23eb9ee734a1ce67e2b160530f09c', 'قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 'af90b6236f9bf3d9801b7f9f03a612cdf1d23eb9ee734a1ce67e2b160530f09c', 'af90b6236f9bf3d9801b7f9f03a612cdf1d23eb9ee734a1ce67e2b160530f09c', NULL, 'قل اغير الله ابغي ربا وهو رب كل شيء ولا تكسب كل نفس الا عليها ولا تزر وازره وزر اخري ثم الي ربكم مرجعكم فينبئكم بما كنتم فيه تختلفون', 8, 15, 60, 1, 2, 150, false, NULL),
    (954, 'tanzil-uthmani-v1.1', 6, 165, 'وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌۢ', '9ff06b676b71c62ea05cc8e166a4720a5034542b64a30095c694355ee3766179', 'وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌۢ', '9ff06b676b71c62ea05cc8e166a4720a5034542b64a30095c694355ee3766179', '9ff06b676b71c62ea05cc8e166a4720a5034542b64a30095c694355ee3766179', NULL, 'وهو الذي جعلكم خلئف الارض ورفع بعضكم فوق بعض درجت ليبلوكم في ما ءاتيكم ان ربك سريع العقاب وانه لغفور رحيم', 8, 15, 60, 1, 2, 150, false, NULL),
    (955, 'tanzil-uthmani-v1.1', 7, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓصٓ', 'ac5c1a487a2be24f696bc6c11f454b115e83b795b551257ae2fbcb44a52f8304', 'الٓمٓصٓ', 'ab3efaf0d357b9410b079d6a661dea89e6d213a0f944bfb76276c7ea00ff0794', 'ab3efaf0d357b9410b079d6a661dea89e6d213a0f944bfb76276c7ea00ff0794', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'المص', 8, 16, 61, 1, 2, 151, false, NULL),
    (956, 'tanzil-uthmani-v1.1', 7, 2, 'كِتَٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', '701ffad750cfa07dbb3cebab89ea546caee2164f8d141b19889a83e14f8226cf', 'كِتَٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', '701ffad750cfa07dbb3cebab89ea546caee2164f8d141b19889a83e14f8226cf', '701ffad750cfa07dbb3cebab89ea546caee2164f8d141b19889a83e14f8226cf', NULL, 'كتب انزل اليك فلا يكن في صدرك حرج منه لتنذر به وذكري للمؤمنين', 8, 16, 61, 1, 2, 151, false, NULL),
    (957, 'tanzil-uthmani-v1.1', 7, 3, 'ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ قَلِيلًا مَّا تَذَكَّرُونَ', '179751071885476c40651ce4ca1b9371170c99df97b068bf3003b80b51292e66', 'ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ قَلِيلًا مَّا تَذَكَّرُونَ', '179751071885476c40651ce4ca1b9371170c99df97b068bf3003b80b51292e66', '179751071885476c40651ce4ca1b9371170c99df97b068bf3003b80b51292e66', NULL, 'اتبعوا ما انزل اليكم من ربكم ولا تتبعوا من دونه اولياء قليلا ما تذكرون', 8, 16, 61, 1, 2, 151, false, NULL),
    (958, 'tanzil-uthmani-v1.1', 7, 4, 'وَكَم مِّن قَرْيَةٍ أَهْلَكْنَٰهَا فَجَآءَهَا بَأْسُنَا بَيَٰتًا أَوْ هُمْ قَآئِلُونَ', '79145196bdfd7bd62566dfafa54024799935a3ffc25130d9fcba817eb0946488', 'وَكَم مِّن قَرْيَةٍ أَهْلَكْنَٰهَا فَجَآءَهَا بَأْسُنَا بَيَٰتًا أَوْ هُمْ قَآئِلُونَ', '79145196bdfd7bd62566dfafa54024799935a3ffc25130d9fcba817eb0946488', '79145196bdfd7bd62566dfafa54024799935a3ffc25130d9fcba817eb0946488', NULL, 'وكم من قريه اهلكنها فجاءها باسنا بيتا او هم قائلون', 8, 16, 61, 1, 2, 151, false, NULL),
    (959, 'tanzil-uthmani-v1.1', 7, 5, 'فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَٰلِمِينَ', '163efb31cf3fb0d4608c8e9dfae4db2757a12a37a47d2c9bc3b3533eceaf1c00', 'فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَٰلِمِينَ', '163efb31cf3fb0d4608c8e9dfae4db2757a12a37a47d2c9bc3b3533eceaf1c00', '163efb31cf3fb0d4608c8e9dfae4db2757a12a37a47d2c9bc3b3533eceaf1c00', NULL, 'فما كان دعويهم اذ جاءهم باسنا الا ان قالوا انا كنا ظلمين', 8, 16, 61, 1, 2, 151, false, NULL),
    (960, 'tanzil-uthmani-v1.1', 7, 6, 'فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ', '47a160357beff1a2fb98496fee132c8857109749d72275384710a93031a99d79', 'فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ', '47a160357beff1a2fb98496fee132c8857109749d72275384710a93031a99d79', '47a160357beff1a2fb98496fee132c8857109749d72275384710a93031a99d79', NULL, 'فلنسلن الذين ارسل اليهم ولنسلن المرسلين', 8, 16, 61, 1, 2, 151, false, NULL),
    (961, 'tanzil-uthmani-v1.1', 7, 7, 'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍ وَمَا كُنَّا غَآئِبِينَ', '9b3d3183a9c3ef113fab381315f8654b595e7ab977f13ec38220a862616c08db', 'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍ وَمَا كُنَّا غَآئِبِينَ', '9b3d3183a9c3ef113fab381315f8654b595e7ab977f13ec38220a862616c08db', '9b3d3183a9c3ef113fab381315f8654b595e7ab977f13ec38220a862616c08db', NULL, 'فلنقصن عليهم بعلم وما كنا غائبين', 8, 16, 61, 1, 2, 151, false, NULL),
    (962, 'tanzil-uthmani-v1.1', 7, 8, 'وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '172f10f33a73875f695e7c5bef23b617e8a7dbb647a9f411fe3c5167646cd57a', 'وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '172f10f33a73875f695e7c5bef23b617e8a7dbb647a9f411fe3c5167646cd57a', '172f10f33a73875f695e7c5bef23b617e8a7dbb647a9f411fe3c5167646cd57a', NULL, 'والوزن يومئذ الحق فمن ثقلت موزينه فاولئك هم المفلحون', 8, 16, 61, 1, 2, 151, false, NULL),
    (963, 'tanzil-uthmani-v1.1', 7, 9, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَظْلِمُونَ', '96424d99636f72dd15facc7e29767ad3717a914b3c69bb4b96078d257610e6aa', 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَظْلِمُونَ', '96424d99636f72dd15facc7e29767ad3717a914b3c69bb4b96078d257610e6aa', '96424d99636f72dd15facc7e29767ad3717a914b3c69bb4b96078d257610e6aa', NULL, 'ومن خفت موزينه فاولئك الذين خسروا انفسهم بما كانوا بايتنا يظلمون', 8, 16, 61, 1, 2, 151, false, NULL),
    (964, 'tanzil-uthmani-v1.1', 7, 10, 'وَلَقَدْ مَكَّنَّٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ قَلِيلًا مَّا تَشْكُرُونَ', 'c9e474b4b1bd67bfaaccab4e1ffe892dad60359ab441ff16dc845f711a373733', 'وَلَقَدْ مَكَّنَّٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ قَلِيلًا مَّا تَشْكُرُونَ', 'c9e474b4b1bd67bfaaccab4e1ffe892dad60359ab441ff16dc845f711a373733', 'c9e474b4b1bd67bfaaccab4e1ffe892dad60359ab441ff16dc845f711a373733', NULL, 'ولقد مكنكم في الارض وجعلنا لكم فيها معيش قليلا ما تشكرون', 8, 16, 61, 1, 2, 151, false, NULL),
    (965, 'tanzil-uthmani-v1.1', 7, 11, 'وَلَقَدْ خَلَقْنَٰكُمْ ثُمَّ صَوَّرْنَٰكُمْ ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ', 'ed9a783482086e2aa6446d63f8516c6ac09ae2b43219509e5afc25ebc4e3b074', 'وَلَقَدْ خَلَقْنَٰكُمْ ثُمَّ صَوَّرْنَٰكُمْ ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ', 'ed9a783482086e2aa6446d63f8516c6ac09ae2b43219509e5afc25ebc4e3b074', 'ed9a783482086e2aa6446d63f8516c6ac09ae2b43219509e5afc25ebc4e3b074', NULL, 'ولقد خلقنكم ثم صورنكم ثم قلنا للملئكه اسجدوا لادم فسجدوا الا ابليس لم يكن من السجدين', 8, 16, 61, 1, 2, 151, false, NULL),
    (966, 'tanzil-uthmani-v1.1', 7, 12, 'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', 'fedd4dd0e59de33c5222474126da4730e283db526840168d333ecc42ec41be7e', 'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', 'fedd4dd0e59de33c5222474126da4730e283db526840168d333ecc42ec41be7e', 'fedd4dd0e59de33c5222474126da4730e283db526840168d333ecc42ec41be7e', NULL, 'قال ما منعك الا تسجد اذ امرتك قال انا خير منه خلقتني من نار وخلقته من طين', 8, 16, 61, 1, 2, 152, false, NULL),
    (967, 'tanzil-uthmani-v1.1', 7, 13, 'قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ', 'd918dd55d7c44bc2adb8e6222731cdf9b3b8219726e4f9dc88ca19dd235f7962', 'قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ', 'd918dd55d7c44bc2adb8e6222731cdf9b3b8219726e4f9dc88ca19dd235f7962', 'd918dd55d7c44bc2adb8e6222731cdf9b3b8219726e4f9dc88ca19dd235f7962', NULL, 'قال فاهبط منها فما يكون لك ان تتكبر فيها فاخرج انك من الصغرين', 8, 16, 61, 1, 2, 152, false, NULL),
    (968, 'tanzil-uthmani-v1.1', 7, 14, 'قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'b0f6397bd2385fd04579e96ec16170c6e6c572d2c777b012936658e1419037f8', 'قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 'b0f6397bd2385fd04579e96ec16170c6e6c572d2c777b012936658e1419037f8', 'b0f6397bd2385fd04579e96ec16170c6e6c572d2c777b012936658e1419037f8', NULL, 'قال انظرني الي يوم يبعثون', 8, 16, 61, 1, 2, 152, false, NULL),
    (969, 'tanzil-uthmani-v1.1', 7, 15, 'قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ', '884cc7cf68fd321f05db3107310def3aab1e9cdff3b829ad66f50b018d7d5e73', 'قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ', '884cc7cf68fd321f05db3107310def3aab1e9cdff3b829ad66f50b018d7d5e73', '884cc7cf68fd321f05db3107310def3aab1e9cdff3b829ad66f50b018d7d5e73', NULL, 'قال انك من المنظرين', 8, 16, 61, 1, 2, 152, false, NULL),
    (970, 'tanzil-uthmani-v1.1', 7, 16, 'قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ', 'e65b5449b4be8447b6c8df57ba235d16c6eb864672a1205c1959501e31566fd2', 'قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ', 'e65b5449b4be8447b6c8df57ba235d16c6eb864672a1205c1959501e31566fd2', 'e65b5449b4be8447b6c8df57ba235d16c6eb864672a1205c1959501e31566fd2', NULL, 'قال فبما اغويتني لاقعدن لهم صرطك المستقيم', 8, 16, 61, 1, 2, 152, false, NULL),
    (971, 'tanzil-uthmani-v1.1', 7, 17, 'ثُمَّ لَـَٔاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَٰنِهِمْ وَعَن شَمَآئِلِهِمْ وَلَا تَجِدُ أَكْثَرَهُمْ شَٰكِرِينَ', 'cb26199df32d9d499f54f791edffd7c9ff32c1ec2dd2c848ca056cd0583fcc7f', 'ثُمَّ لَـَٔاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَٰنِهِمْ وَعَن شَمَآئِلِهِمْ وَلَا تَجِدُ أَكْثَرَهُمْ شَٰكِرِينَ', 'cb26199df32d9d499f54f791edffd7c9ff32c1ec2dd2c848ca056cd0583fcc7f', 'cb26199df32d9d499f54f791edffd7c9ff32c1ec2dd2c848ca056cd0583fcc7f', NULL, 'ثم لاتينهم من بين ايديهم ومن خلفهم وعن ايمنهم وعن شمائلهم ولا تجد اكثرهم شكرين', 8, 16, 61, 1, 2, 152, false, NULL),
    (972, 'tanzil-uthmani-v1.1', 7, 18, 'قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًا مَّدْحُورًا لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ', '676871b389f11b5683f0018f775bb678a2fc99e1d1ade349751e37be3c9b13cd', 'قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًا مَّدْحُورًا لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ', '676871b389f11b5683f0018f775bb678a2fc99e1d1ade349751e37be3c9b13cd', '676871b389f11b5683f0018f775bb678a2fc99e1d1ade349751e37be3c9b13cd', NULL, 'قال اخرج منها مذءوما مدحورا لمن تبعك منهم لاملان جهنم منكم اجمعين', 8, 16, 61, 1, 2, 152, false, NULL),
    (973, 'tanzil-uthmani-v1.1', 7, 19, 'وَيَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', '6efcb2fa11b218653a88f4b4976fec5bb377ab7e1a2f1b0aae34bc7151752070', 'وَيَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', '6efcb2fa11b218653a88f4b4976fec5bb377ab7e1a2f1b0aae34bc7151752070', '6efcb2fa11b218653a88f4b4976fec5bb377ab7e1a2f1b0aae34bc7151752070', NULL, 'ويادم اسكن انت وزوجك الجنه فكلا من حيث شئتما ولا تقربا هذه الشجره فتكونا من الظلمين', 8, 16, 61, 1, 2, 152, false, NULL),
    (974, 'tanzil-uthmani-v1.1', 7, 20, 'فَوَسْوَسَ لَهُمَا ٱلشَّيْطَٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَٰلِدِينَ', '7aebc560c0752eecb1aed71b836521a5beff21ba1a3bfd6aecdc4f7dd0327ff0', 'فَوَسْوَسَ لَهُمَا ٱلشَّيْطَٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَٰلِدِينَ', '7aebc560c0752eecb1aed71b836521a5beff21ba1a3bfd6aecdc4f7dd0327ff0', '7aebc560c0752eecb1aed71b836521a5beff21ba1a3bfd6aecdc4f7dd0327ff0', NULL, 'فوسوس لهما الشيطن ليبدي لهما ما وري عنهما من سوءتهما وقال ما نهيكما ربكما عن هذه الشجره الا ان تكونا ملكين او تكونا من الخلدين', 8, 16, 61, 1, 2, 152, false, NULL),
    (975, 'tanzil-uthmani-v1.1', 7, 21, 'وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ', '6fcad31f6453cd30c9abc9080bf612a30698ae8227cc335d55449e8809b14ab8', 'وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ', '6fcad31f6453cd30c9abc9080bf612a30698ae8227cc335d55449e8809b14ab8', '6fcad31f6453cd30c9abc9080bf612a30698ae8227cc335d55449e8809b14ab8', NULL, 'وقاسمهما اني لكما لمن النصحين', 8, 16, 61, 1, 2, 152, false, NULL),
    (976, 'tanzil-uthmani-v1.1', 7, 22, 'فَدَلَّىٰهُمَا بِغُرُورٍ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَٰنَ لَكُمَا عَدُوٌّ مُّبِينٌ', 'b2d98fab401bab407774bd9720097303e504c5ac5c922f0d0e762e0c6601d7e7', 'فَدَلَّىٰهُمَا بِغُرُورٍ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَٰنَ لَكُمَا عَدُوٌّ مُّبِينٌ', 'b2d98fab401bab407774bd9720097303e504c5ac5c922f0d0e762e0c6601d7e7', 'b2d98fab401bab407774bd9720097303e504c5ac5c922f0d0e762e0c6601d7e7', NULL, 'فدليهما بغرور فلما ذاقا الشجره بدت لهما سوءتهما وطفقا يخصفان عليهما من ورق الجنه وناديهما ربهما الم انهكما عن تلكما الشجره واقل لكما ان الشيطن لكما عدو مبين', 8, 16, 61, 1, 2, 152, false, NULL),
    (977, 'tanzil-uthmani-v1.1', 7, 23, 'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', '4791d843db65c6c782f4f15fac02d76df2bed3239232a7a1625d4b5f5b834c21', 'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', '4791d843db65c6c782f4f15fac02d76df2bed3239232a7a1625d4b5f5b834c21', '4791d843db65c6c782f4f15fac02d76df2bed3239232a7a1625d4b5f5b834c21', NULL, 'قالا ربنا ظلمنا انفسنا وان لم تغفر لنا وترحمنا لنكونن من الخسرين', 8, 16, 61, 1, 2, 153, false, NULL),
    (978, 'tanzil-uthmani-v1.1', 7, 24, 'قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'afb353e4ecb1fdc52ba69abf895cee4bffeccf08f7f706cc2aed780e205056ed', 'قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'afb353e4ecb1fdc52ba69abf895cee4bffeccf08f7f706cc2aed780e205056ed', 'afb353e4ecb1fdc52ba69abf895cee4bffeccf08f7f706cc2aed780e205056ed', NULL, 'قال اهبطوا بعضكم لبعض عدو ولكم في الارض مستقر ومتع الي حين', 8, 16, 61, 1, 2, 153, false, NULL),
    (979, 'tanzil-uthmani-v1.1', 7, 25, 'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', 'c847c4de790d45f751bfed4c7bdefdd79872f4631bb366ac2e8893d78e1b93f3', 'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', 'c847c4de790d45f751bfed4c7bdefdd79872f4631bb366ac2e8893d78e1b93f3', 'c847c4de790d45f751bfed4c7bdefdd79872f4631bb366ac2e8893d78e1b93f3', NULL, 'قال فيها تحيون وفيها تموتون ومنها تخرجون', 8, 16, 61, 1, 2, 153, false, NULL),
    (980, 'tanzil-uthmani-v1.1', 7, 26, 'يَٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًا وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ', '07d8fdee7f6788a06a48eb5e5061328e20b319a3f514db05dd4c4dbe3322da04', 'يَٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًا وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ', '07d8fdee7f6788a06a48eb5e5061328e20b319a3f514db05dd4c4dbe3322da04', '07d8fdee7f6788a06a48eb5e5061328e20b319a3f514db05dd4c4dbe3322da04', NULL, 'يبني ءادم قد انزلنا عليكم لباسا يوري سوءتكم وريشا ولباس التقوي ذلك خير ذلك من ءايت الله لعلهم يذكرون', 8, 16, 61, 1, 2, 153, false, NULL),
    (981, 'tanzil-uthmani-v1.1', 7, 27, 'يَٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ إِنَّا جَعَلْنَا ٱلشَّيَٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ', '567ab60893f5764d3c5946510e187c90a98715f6dbe9d7836a43a3a47894596c', 'يَٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ إِنَّا جَعَلْنَا ٱلشَّيَٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ', '567ab60893f5764d3c5946510e187c90a98715f6dbe9d7836a43a3a47894596c', '567ab60893f5764d3c5946510e187c90a98715f6dbe9d7836a43a3a47894596c', NULL, 'يبني ءادم لا يفتننكم الشيطن كما اخرج ابويكم من الجنه ينزع عنهما لباسهما ليريهما سوءتهما انه يريكم هو وقبيله من حيث لا ترونهم انا جعلنا الشيطين اولياء للذين لا يؤمنون', 8, 16, 61, 1, 2, 153, false, NULL),
    (982, 'tanzil-uthmani-v1.1', 7, 28, 'وَإِذَا فَعَلُوا۟ فَٰحِشَةً قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '0e2f43bf1d928a249bbec61ac870abe5e43cde14049fdb8d0487453097c6ab8b', 'وَإِذَا فَعَلُوا۟ فَٰحِشَةً قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '0e2f43bf1d928a249bbec61ac870abe5e43cde14049fdb8d0487453097c6ab8b', '0e2f43bf1d928a249bbec61ac870abe5e43cde14049fdb8d0487453097c6ab8b', NULL, 'واذا فعلوا فحشه قالوا وجدنا عليها ءاباءنا والله امرنا بها قل ان الله لا يامر بالفحشاء اتقولون علي الله ما لا تعلمون', 8, 16, 61, 1, 2, 153, false, NULL),
    (983, 'tanzil-uthmani-v1.1', 7, 29, 'قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ كَمَا بَدَأَكُمْ تَعُودُونَ', 'f0753e39f7f30958c957b8b1c95ee936606853c1fa9e5a7c8b19bbf8bbc994a1', 'قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ كَمَا بَدَأَكُمْ تَعُودُونَ', 'f0753e39f7f30958c957b8b1c95ee936606853c1fa9e5a7c8b19bbf8bbc994a1', 'f0753e39f7f30958c957b8b1c95ee936606853c1fa9e5a7c8b19bbf8bbc994a1', NULL, 'قل امر ربي بالقسط واقيموا وجوهكم عند كل مسجد وادعوه مخلصين له الدين كما بداكم تعودون', 8, 16, 61, 1, 2, 153, false, NULL),
    (984, 'tanzil-uthmani-v1.1', 7, 30, 'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَٰلَةُ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', '38ff63322920ea4d778b93ebcbf476689b639a34981edb676508b448c011b17d', 'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَٰلَةُ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', '38ff63322920ea4d778b93ebcbf476689b639a34981edb676508b448c011b17d', '38ff63322920ea4d778b93ebcbf476689b639a34981edb676508b448c011b17d', NULL, 'فريقا هدي وفريقا حق عليهم الضلله انهم اتخذوا الشيطين اولياء من دون الله ويحسبون انهم مهتدون', 8, 16, 61, 1, 2, 153, false, NULL),
    (985, 'tanzil-uthmani-v1.1', 7, 31, 'يَٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', '995158f1a819ad9f1d7179f01e36179bc0b710f38ca676c27c0b2f4f6afb1cc8', 'يَٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', '995158f1a819ad9f1d7179f01e36179bc0b710f38ca676c27c0b2f4f6afb1cc8', '995158f1a819ad9f1d7179f01e36179bc0b710f38ca676c27c0b2f4f6afb1cc8', NULL, 'يبني ءادم خذوا زينتكم عند كل مسجد وكلوا واشربوا ولا تسرفوا انه لا يحب المسرفين', 8, 16, 62, 1, 2, 154, false, NULL),
    (986, 'tanzil-uthmani-v1.1', 7, 32, 'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزْقِ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةً يَوْمَ ٱلْقِيَٰمَةِ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', '2beb46c0661ae9baf601d681fb050674c733dccab0af6688d9c056d8255e8335', 'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزْقِ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةً يَوْمَ ٱلْقِيَٰمَةِ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', '2beb46c0661ae9baf601d681fb050674c733dccab0af6688d9c056d8255e8335', '2beb46c0661ae9baf601d681fb050674c733dccab0af6688d9c056d8255e8335', NULL, 'قل من حرم زينه الله التي اخرج لعباده والطيبت من الرزق قل هي للذين ءامنوا في الحيوه الدنيا خالصه يوم القيمه كذلك نفصل الايت لقوم يعلمون', 8, 16, 62, 1, 2, 154, false, NULL),
    (987, 'tanzil-uthmani-v1.1', 7, 33, 'قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '1570043eac0a5b019c44c88675d07b84b1c850ae4eb3569823d038c57a1ffb28', 'قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '1570043eac0a5b019c44c88675d07b84b1c850ae4eb3569823d038c57a1ffb28', '1570043eac0a5b019c44c88675d07b84b1c850ae4eb3569823d038c57a1ffb28', NULL, 'قل انما حرم ربي الفوحش ما ظهر منها وما بطن والاثم والبغي بغير الحق وان تشركوا بالله ما لم ينزل به سلطنا وان تقولوا علي الله ما لا تعلمون', 8, 16, 62, 1, 2, 154, false, NULL),
    (988, 'tanzil-uthmani-v1.1', 7, 34, 'وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'a3f170b83bbce92b24306c6bfa7bc37dfcbb79562a045218ab86f732bf6b4cdc', 'وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'a3f170b83bbce92b24306c6bfa7bc37dfcbb79562a045218ab86f732bf6b4cdc', 'a3f170b83bbce92b24306c6bfa7bc37dfcbb79562a045218ab86f732bf6b4cdc', NULL, 'ولكل امه اجل فاذا جاء اجلهم لا يستاخرون ساعه ولا يستقدمون', 8, 16, 62, 1, 2, 154, false, NULL),
    (989, 'tanzil-uthmani-v1.1', 7, 35, 'يَٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'cc278874554b5c5e75c8652959fb0680eb8332570c86efc056e9083d4a972088', 'يَٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'cc278874554b5c5e75c8652959fb0680eb8332570c86efc056e9083d4a972088', 'cc278874554b5c5e75c8652959fb0680eb8332570c86efc056e9083d4a972088', NULL, 'يبني ءادم اما ياتينكم رسل منكم يقصون عليكم ءايتي فمن اتقي واصلح فلا خوف عليهم ولا هم يحزنون', 8, 16, 62, 1, 2, 154, false, NULL),
    (990, 'tanzil-uthmani-v1.1', 7, 36, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '87a6ca98f54b18f4607327e2c2b0f534462f831040c0562c9b96614cd1202048', 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '87a6ca98f54b18f4607327e2c2b0f534462f831040c0562c9b96614cd1202048', '87a6ca98f54b18f4607327e2c2b0f534462f831040c0562c9b96614cd1202048', NULL, 'والذين كذبوا بايتنا واستكبروا عنها اولئك اصحب النار هم فيها خلدون', 8, 16, 62, 1, 2, 154, false, NULL),
    (991, 'tanzil-uthmani-v1.1', 7, 37, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ أُو۟لَٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَٰبِ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', '6b73bd1e42eec2ec770fd87c97c2d71a271705ad9f5a01ee88cdf4f92ff7efd5', 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ أُو۟لَٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَٰبِ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', '6b73bd1e42eec2ec770fd87c97c2d71a271705ad9f5a01ee88cdf4f92ff7efd5', '6b73bd1e42eec2ec770fd87c97c2d71a271705ad9f5a01ee88cdf4f92ff7efd5', NULL, 'فمن اظلم ممن افتري علي الله كذبا او كذب بايته اولئك ينالهم نصيبهم من الكتب حتي اذا جاءتهم رسلنا يتوفونهم قالوا اين ما كنتم تدعون من دون الله قالوا ضلوا عنا وشهدوا علي انفسهم انهم كانوا كفرين', 8, 16, 62, 1, 2, 154, false, NULL),
    (992, 'tanzil-uthmani-v1.1', 7, 38, 'قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ كُلَّمَا دَخَلَتْ أُمَّةٌ لَّعَنَتْ أُخْتَهَا حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًا ضِعْفًا مِّنَ ٱلنَّارِ قَالَ لِكُلٍّ ضِعْفٌ وَلَٰكِن لَّا تَعْلَمُونَ', 'c20549755e3bdedeb7af6b53dec6cb75a5a776ce2e27c003fffd5b0600e508e2', 'قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ كُلَّمَا دَخَلَتْ أُمَّةٌ لَّعَنَتْ أُخْتَهَا حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًا ضِعْفًا مِّنَ ٱلنَّارِ قَالَ لِكُلٍّ ضِعْفٌ وَلَٰكِن لَّا تَعْلَمُونَ', 'c20549755e3bdedeb7af6b53dec6cb75a5a776ce2e27c003fffd5b0600e508e2', 'c20549755e3bdedeb7af6b53dec6cb75a5a776ce2e27c003fffd5b0600e508e2', NULL, 'قال ادخلوا في امم قد خلت من قبلكم من الجن والانس في النار كلما دخلت امه لعنت اختها حتي اذا اداركوا فيها جميعا قالت اخريهم لاوليهم ربنا هؤلاء اضلونا فاتهم عذابا ضعفا من النار قال لكل ضعف ولكن لا تعلمون', 8, 16, 62, 1, 2, 155, false, NULL),
    (993, 'tanzil-uthmani-v1.1', 7, 39, 'وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ', '67434324d09556338d729d8e8f97d329cdbdc1ad42da6908409b2241dbfa000a', 'وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ', '67434324d09556338d729d8e8f97d329cdbdc1ad42da6908409b2241dbfa000a', '67434324d09556338d729d8e8f97d329cdbdc1ad42da6908409b2241dbfa000a', NULL, 'وقالت اوليهم لاخريهم فما كان لكم علينا من فضل فذوقوا العذاب بما كنتم تكسبون', 8, 16, 62, 1, 2, 155, false, NULL),
    (994, 'tanzil-uthmani-v1.1', 7, 40, 'إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ', '3b52180add1bd78c4e7a4151f2a840f843eab5f26cc1d683c806b325d726f349', 'إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ', '3b52180add1bd78c4e7a4151f2a840f843eab5f26cc1d683c806b325d726f349', '3b52180add1bd78c4e7a4151f2a840f843eab5f26cc1d683c806b325d726f349', NULL, 'ان الذين كذبوا بايتنا واستكبروا عنها لا تفتح لهم ابوب السماء ولا يدخلون الجنه حتي يلج الجمل في سم الخياط وكذلك نجزي المجرمين', 8, 16, 62, 1, 2, 155, false, NULL),
    (995, 'tanzil-uthmani-v1.1', 7, 41, 'لَهُم مِّن جَهَنَّمَ مِهَادٌ وَمِن فَوْقِهِمْ غَوَاشٍ وَكَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', '50b24118ac853814761dc40c2be6cc2d6ae74db274e05e9eb55991c9bba96453', 'لَهُم مِّن جَهَنَّمَ مِهَادٌ وَمِن فَوْقِهِمْ غَوَاشٍ وَكَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', '50b24118ac853814761dc40c2be6cc2d6ae74db274e05e9eb55991c9bba96453', '50b24118ac853814761dc40c2be6cc2d6ae74db274e05e9eb55991c9bba96453', NULL, 'لهم من جهنم مهاد ومن فوقهم غواش وكذلك نجزي الظلمين', 8, 16, 62, 1, 2, 155, false, NULL),
    (996, 'tanzil-uthmani-v1.1', 7, 42, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', '8523a00d04a48933c7e3673419d34c7909ce9252a002087d792b981fd8181112', 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', '8523a00d04a48933c7e3673419d34c7909ce9252a002087d792b981fd8181112', '8523a00d04a48933c7e3673419d34c7909ce9252a002087d792b981fd8181112', NULL, 'والذين ءامنوا وعملوا الصلحت لا نكلف نفسا الا وسعها اولئك اصحب الجنه هم فيها خلدون', 8, 16, 62, 1, 2, 155, false, NULL),
    (997, 'tanzil-uthmani-v1.1', 7, 43, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', '01b641b34077898cc9e2647fca98c6d43fc7700102b1c7596f44377f5773364c', 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', '01b641b34077898cc9e2647fca98c6d43fc7700102b1c7596f44377f5773364c', '01b641b34077898cc9e2647fca98c6d43fc7700102b1c7596f44377f5773364c', NULL, 'ونزعنا ما في صدورهم من غل تجري من تحتهم الانهر وقالوا الحمد لله الذي هدينا لهذا وما كنا لنهتدي لولا ان هدينا الله لقد جاءت رسل ربنا بالحق ونودوا ان تلكم الجنه اورثتموها بما كنتم تعملون', 8, 16, 62, 1, 2, 155, false, NULL),
    (998, 'tanzil-uthmani-v1.1', 7, 44, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّا قَالُوا۟ نَعَمْ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', '21b553d454a29dd719f05dc25b3f28a7155abb50bb18d37d8c7b96aa59188475', 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّا قَالُوا۟ نَعَمْ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', '21b553d454a29dd719f05dc25b3f28a7155abb50bb18d37d8c7b96aa59188475', '21b553d454a29dd719f05dc25b3f28a7155abb50bb18d37d8c7b96aa59188475', NULL, 'ونادي اصحب الجنه اصحب النار ان قد وجدنا ما وعدنا ربنا حقا فهل وجدتم ما وعد ربكم حقا قالوا نعم فاذن مؤذن بينهم ان لعنه الله علي الظلمين', 8, 16, 62, 1, 2, 156, false, NULL),
    (999, 'tanzil-uthmani-v1.1', 7, 45, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ كَٰفِرُونَ', '6973861487369e78051004a71c9fc1c2296d40ff4cd43670fadd8e99c63609a6', 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ كَٰفِرُونَ', '6973861487369e78051004a71c9fc1c2296d40ff4cd43670fadd8e99c63609a6', '6973861487369e78051004a71c9fc1c2296d40ff4cd43670fadd8e99c63609a6', NULL, 'الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالاخره كفرون', 8, 16, 62, 1, 2, 156, false, NULL),
    (1000, 'tanzil-uthmani-v1.1', 7, 46, 'وَبَيْنَهُمَا حِجَابٌ وَعَلَى ٱلْأَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ وَنَادَوْا۟ أَصْحَٰبَ ٱلْجَنَّةِ أَن سَلَٰمٌ عَلَيْكُمْ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ', '75dcb38587c8df773bed91bca90afbbcd7e928d84d0b8305219a017f8b54a129', 'وَبَيْنَهُمَا حِجَابٌ وَعَلَى ٱلْأَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ وَنَادَوْا۟ أَصْحَٰبَ ٱلْجَنَّةِ أَن سَلَٰمٌ عَلَيْكُمْ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ', '75dcb38587c8df773bed91bca90afbbcd7e928d84d0b8305219a017f8b54a129', '75dcb38587c8df773bed91bca90afbbcd7e928d84d0b8305219a017f8b54a129', NULL, 'وبينهما حجاب وعلي الاعراف رجال يعرفون كلا بسيميهم ونادوا اصحب الجنه ان سلم عليكم لم يدخلوها وهم يطمعون', 8, 16, 62, 1, 2, 156, false, NULL)
