    (1001, 'tanzil-uthmani-v1.1', 7, 47, 'وَإِذَا صُرِفَتْ أَبْصَٰرُهُمْ تِلْقَآءَ أَصْحَٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'e2a7e5309597abb96e122c9e78d6b27557f36e9fedb21cdb15bdbcbb561de578', 'وَإِذَا صُرِفَتْ أَبْصَٰرُهُمْ تِلْقَآءَ أَصْحَٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'e2a7e5309597abb96e122c9e78d6b27557f36e9fedb21cdb15bdbcbb561de578', 'e2a7e5309597abb96e122c9e78d6b27557f36e9fedb21cdb15bdbcbb561de578', NULL, 'واذا صرفت ابصرهم تلقاء اصحب النار قالوا ربنا لا تجعلنا مع القوم الظلمين', 8, 16, 63, 1, 2, 156, false, NULL),
    (1002, 'tanzil-uthmani-v1.1', 7, 48, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْأَعْرَافِ رِجَالًا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ', 'fa52772ba15842366184992047a9815a0666237c95ef0264b29bd9c88b084096', 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْأَعْرَافِ رِجَالًا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ', 'fa52772ba15842366184992047a9815a0666237c95ef0264b29bd9c88b084096', 'fa52772ba15842366184992047a9815a0666237c95ef0264b29bd9c88b084096', NULL, 'ونادي اصحب الاعراف رجالا يعرفونهم بسيميهم قالوا ما اغني عنكم جمعكم وما كنتم تستكبرون', 8, 16, 63, 1, 2, 156, false, NULL),
    (1003, 'tanzil-uthmani-v1.1', 7, 49, 'أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ', 'a6ddaafa581f8c2732b949be8f11c918d3e57b69b6c8749854a3e609a2b312be', 'أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ', 'a6ddaafa581f8c2732b949be8f11c918d3e57b69b6c8749854a3e609a2b312be', 'a6ddaafa581f8c2732b949be8f11c918d3e57b69b6c8749854a3e609a2b312be', NULL, 'اهؤلاء الذين اقسمتم لا ينالهم الله برحمه ادخلوا الجنه لا خوف عليكم ولا انتم تحزنون', 8, 16, 63, 1, 2, 156, false, NULL),
    (1004, 'tanzil-uthmani-v1.1', 7, 50, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلنَّارِ أَصْحَٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَٰفِرِينَ', '6a75596a649fa4b614cccfbd973367a4ef20dc262e62df7f84bec9273896170a', 'وَنَادَىٰٓ أَصْحَٰبُ ٱلنَّارِ أَصْحَٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَٰفِرِينَ', '6a75596a649fa4b614cccfbd973367a4ef20dc262e62df7f84bec9273896170a', '6a75596a649fa4b614cccfbd973367a4ef20dc262e62df7f84bec9273896170a', NULL, 'ونادي اصحب النار اصحب الجنه ان افيضوا علينا من الماء او مما رزقكم الله قالوا ان الله حرمهما علي الكفرين', 8, 16, 63, 1, 2, 156, false, NULL),
    (1005, 'tanzil-uthmani-v1.1', 7, 51, 'ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', '04f3c7acda826a2f3a93f3a84552a66107798f665447e6c602ea9155012bb8df', 'ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', '04f3c7acda826a2f3a93f3a84552a66107798f665447e6c602ea9155012bb8df', '04f3c7acda826a2f3a93f3a84552a66107798f665447e6c602ea9155012bb8df', NULL, 'الذين اتخذوا دينهم لهوا ولعبا وغرتهم الحيوه الدنيا فاليوم ننسيهم كما نسوا لقاء يومهم هذا وما كانوا بايتنا يجحدون', 8, 16, 63, 1, 2, 156, false, NULL),
    (1006, 'tanzil-uthmani-v1.1', 7, 52, 'وَلَقَدْ جِئْنَٰهُم بِكِتَٰبٍ فَصَّلْنَٰهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', '806e7db08e974bd2f93f5d0879da7dac5212b6ed0aeddd5a6b460fad457dddc8', 'وَلَقَدْ جِئْنَٰهُم بِكِتَٰبٍ فَصَّلْنَٰهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', '806e7db08e974bd2f93f5d0879da7dac5212b6ed0aeddd5a6b460fad457dddc8', '806e7db08e974bd2f93f5d0879da7dac5212b6ed0aeddd5a6b460fad457dddc8', NULL, 'ولقد جئنهم بكتب فصلنه علي علم هدي ورحمه لقوم يؤمنون', 8, 16, 63, 1, 2, 157, false, NULL),
    (1007, 'tanzil-uthmani-v1.1', 7, 53, 'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '6eb4ecc88a18e736c2f65f4ee77803235f68b7fdb8d7cf9a6be56d1a6098686f', 'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '6eb4ecc88a18e736c2f65f4ee77803235f68b7fdb8d7cf9a6be56d1a6098686f', '6eb4ecc88a18e736c2f65f4ee77803235f68b7fdb8d7cf9a6be56d1a6098686f', NULL, 'هل ينظرون الا تاويله يوم ياتي تاويله يقول الذين نسوه من قبل قد جاءت رسل ربنا بالحق فهل لنا من شفعاء فيشفعوا لنا او نرد فنعمل غير الذي كنا نعمل قد خسروا انفسهم وضل عنهم ما كانوا يفترون', 8, 16, 63, 1, 2, 157, false, NULL),
    (1008, 'tanzil-uthmani-v1.1', 7, 54, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', '360e2c298d5b67736580d15c061fcbdb10c5b4c16110e02d5344c54bf5dd9bf9', 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', '360e2c298d5b67736580d15c061fcbdb10c5b4c16110e02d5344c54bf5dd9bf9', '360e2c298d5b67736580d15c061fcbdb10c5b4c16110e02d5344c54bf5dd9bf9', NULL, 'ان ربكم الله الذي خلق السموت والارض في سته ايام ثم استوي علي العرش يغشي اليل النهار يطلبه حثيثا والشمس والقمر والنجوم مسخرت بامره الا له الخلق والامر تبارك الله رب العلمين', 8, 16, 63, 1, 2, 157, false, NULL),
    (1009, 'tanzil-uthmani-v1.1', 7, 55, 'ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'd017240a67df864076c2a071c0e5d5844666e8d0b16fa18dee9ddf6a9ad3f164', 'ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 'd017240a67df864076c2a071c0e5d5844666e8d0b16fa18dee9ddf6a9ad3f164', 'd017240a67df864076c2a071c0e5d5844666e8d0b16fa18dee9ddf6a9ad3f164', NULL, 'ادعوا ربكم تضرعا وخفيه انه لا يحب المعتدين', 8, 16, 63, 1, 2, 157, false, NULL),
    (1010, 'tanzil-uthmani-v1.1', 7, 56, 'وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا وَٱدْعُوهُ خَوْفًا وَطَمَعًا إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌ مِّنَ ٱلْمُحْسِنِينَ', 'd023dbeadcb9ac74e0959b71c11e3dcdf9727f6280028fdbc23e4406421f3754', 'وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا وَٱدْعُوهُ خَوْفًا وَطَمَعًا إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌ مِّنَ ٱلْمُحْسِنِينَ', 'd023dbeadcb9ac74e0959b71c11e3dcdf9727f6280028fdbc23e4406421f3754', 'd023dbeadcb9ac74e0959b71c11e3dcdf9727f6280028fdbc23e4406421f3754', NULL, 'ولا تفسدوا في الارض بعد اصلحها وادعوه خوفا وطمعا ان رحمت الله قريب من المحسنين', 8, 16, 63, 1, 2, 157, false, NULL),
    (1011, 'tanzil-uthmani-v1.1', 7, 57, 'وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَٰهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ', '6325c9017c3b228ff94f1992908f464d6fd6388b5667d7a7ec9d4513a864d9d1', 'وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَٰهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ', '6325c9017c3b228ff94f1992908f464d6fd6388b5667d7a7ec9d4513a864d9d1', '6325c9017c3b228ff94f1992908f464d6fd6388b5667d7a7ec9d4513a864d9d1', NULL, 'وهو الذي يرسل الريح بشرا بين يدي رحمته حتي اذا اقلت سحابا ثقالا سقنه لبلد ميت فانزلنا به الماء فاخرجنا به من كل الثمرت كذلك نخرج الموتي لعلكم تذكرون', 8, 16, 63, 1, 2, 157, false, NULL),
    (1012, 'tanzil-uthmani-v1.1', 7, 58, 'وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا كَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَشْكُرُونَ', 'd0c6ef3458e1d6151a437861c7d352782eeaf94c97b395949c6840851bab7bbe', 'وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا كَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَشْكُرُونَ', 'd0c6ef3458e1d6151a437861c7d352782eeaf94c97b395949c6840851bab7bbe', 'd0c6ef3458e1d6151a437861c7d352782eeaf94c97b395949c6840851bab7bbe', NULL, 'والبلد الطيب يخرج نباته باذن ربه والذي خبث لا يخرج الا نكدا كذلك نصرف الايت لقوم يشكرون', 8, 16, 63, 1, 2, 158, false, NULL),
    (1013, 'tanzil-uthmani-v1.1', 7, 59, 'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'd15e03e21b2251124dd46ad044cbe82f9609c0934af19b351a1e1a8b04f8903a', 'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'd15e03e21b2251124dd46ad044cbe82f9609c0934af19b351a1e1a8b04f8903a', 'd15e03e21b2251124dd46ad044cbe82f9609c0934af19b351a1e1a8b04f8903a', NULL, 'لقد ارسلنا نوحا الي قومه فقال يقوم اعبدوا الله ما لكم من اله غيره اني اخاف عليكم عذاب يوم عظيم', 8, 16, 63, 1, 2, 158, false, NULL),
    (1014, 'tanzil-uthmani-v1.1', 7, 60, 'قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَٰلٍ مُّبِينٍ', 'ab144580f84716ebf72af5212ef8b53fc79145fde004275729d848a935202681', 'قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَٰلٍ مُّبِينٍ', 'ab144580f84716ebf72af5212ef8b53fc79145fde004275729d848a935202681', 'ab144580f84716ebf72af5212ef8b53fc79145fde004275729d848a935202681', NULL, 'قال الملا من قومه انا لنريك في ضلل مبين', 8, 16, 63, 1, 2, 158, false, NULL),
    (1015, 'tanzil-uthmani-v1.1', 7, 61, 'قَالَ يَٰقَوْمِ لَيْسَ بِى ضَلَٰلَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'b047efea2bfd6ae84ad25e312153e744b4f5d7bf13cecd1ca00c755d9c5e2190', 'قَالَ يَٰقَوْمِ لَيْسَ بِى ضَلَٰلَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'b047efea2bfd6ae84ad25e312153e744b4f5d7bf13cecd1ca00c755d9c5e2190', 'b047efea2bfd6ae84ad25e312153e744b4f5d7bf13cecd1ca00c755d9c5e2190', NULL, 'قال يقوم ليس بي ضلله ولكني رسول من رب العلمين', 8, 16, 63, 1, 2, 158, false, NULL),
    (1016, 'tanzil-uthmani-v1.1', 7, 62, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', '79c7d5972ed65758096595bc8bc49fb1b63004a209c5cabdae14300492b4f908', 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', '79c7d5972ed65758096595bc8bc49fb1b63004a209c5cabdae14300492b4f908', '79c7d5972ed65758096595bc8bc49fb1b63004a209c5cabdae14300492b4f908', NULL, 'ابلغكم رسلت ربي وانصح لكم واعلم من الله ما لا تعلمون', 8, 16, 63, 1, 2, 158, false, NULL),
    (1017, 'tanzil-uthmani-v1.1', 7, 63, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ', 'cd5309fbcf66144202d8ba9874dfe30b930a3dd7218f521120b6a5254e3d33ca', 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ', 'cd5309fbcf66144202d8ba9874dfe30b930a3dd7218f521120b6a5254e3d33ca', 'cd5309fbcf66144202d8ba9874dfe30b930a3dd7218f521120b6a5254e3d33ca', NULL, 'اوعجبتم ان جاءكم ذكر من ربكم علي رجل منكم لينذركم ولتتقوا ولعلكم ترحمون', 8, 16, 63, 1, 2, 158, false, NULL),
    (1018, 'tanzil-uthmani-v1.1', 7, 64, 'فَكَذَّبُوهُ فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ', '5b15afc2697d45445b45578fb86e204ddbde3a6799d37b23355c2406556594a5', 'فَكَذَّبُوهُ فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ', '5b15afc2697d45445b45578fb86e204ddbde3a6799d37b23355c2406556594a5', '5b15afc2697d45445b45578fb86e204ddbde3a6799d37b23355c2406556594a5', NULL, 'فكذبوه فانجينه والذين معه في الفلك واغرقنا الذين كذبوا بايتنا انهم كانوا قوما عمين', 8, 16, 63, 1, 2, 158, false, NULL),
    (1019, 'tanzil-uthmani-v1.1', 7, 65, 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'dc3123fef3c61e8eb596fb374be515b1c9759dbdf7556d02c0bf5587f5871b3e', 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'dc3123fef3c61e8eb596fb374be515b1c9759dbdf7556d02c0bf5587f5871b3e', 'dc3123fef3c61e8eb596fb374be515b1c9759dbdf7556d02c0bf5587f5871b3e', NULL, 'والي عاد اخاهم هودا قال يقوم اعبدوا الله ما لكم من اله غيره افلا تتقون', 8, 16, 64, 1, 2, 158, false, NULL),
    (1020, 'tanzil-uthmani-v1.1', 7, 66, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَٰذِبِينَ', '81e3a3d1063ae78601fc7b5d8cb32ee90f0f13236ebdb507eecaecd5b413a985', 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَٰذِبِينَ', '81e3a3d1063ae78601fc7b5d8cb32ee90f0f13236ebdb507eecaecd5b413a985', '81e3a3d1063ae78601fc7b5d8cb32ee90f0f13236ebdb507eecaecd5b413a985', NULL, 'قال الملا الذين كفروا من قومه انا لنريك في سفاهه وانا لنظنك من الكذبين', 8, 16, 64, 1, 2, 158, false, NULL),
    (1021, 'tanzil-uthmani-v1.1', 7, 67, 'قَالَ يَٰقَوْمِ لَيْسَ بِى سَفَاهَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'ec90192c0cfa17a5cf3baa71e23350d45c1aa6fe87b226a671a271e9f02c4377', 'قَالَ يَٰقَوْمِ لَيْسَ بِى سَفَاهَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'ec90192c0cfa17a5cf3baa71e23350d45c1aa6fe87b226a671a271e9f02c4377', 'ec90192c0cfa17a5cf3baa71e23350d45c1aa6fe87b226a671a271e9f02c4377', NULL, 'قال يقوم ليس بي سفاهه ولكني رسول من رب العلمين', 8, 16, 64, 1, 2, 158, false, NULL),
    (1022, 'tanzil-uthmani-v1.1', 7, 68, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ', '0818638c11353f7ff43d50a893e0b6a1a2b8797a28cf031b738017a87d3513db', 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ', '0818638c11353f7ff43d50a893e0b6a1a2b8797a28cf031b738017a87d3513db', '0818638c11353f7ff43d50a893e0b6a1a2b8797a28cf031b738017a87d3513db', NULL, 'ابلغكم رسلت ربي وانا لكم ناصح امين', 8, 16, 64, 1, 2, 159, false, NULL),
    (1023, 'tanzil-uthmani-v1.1', 7, 69, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةً فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ', 'f134682cb35e6a6206fdec264279d73c4daca50e70aa392c8f44537c9d28a12f', 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةً فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ', 'f134682cb35e6a6206fdec264279d73c4daca50e70aa392c8f44537c9d28a12f', 'f134682cb35e6a6206fdec264279d73c4daca50e70aa392c8f44537c9d28a12f', NULL, 'اوعجبتم ان جاءكم ذكر من ربكم علي رجل منكم لينذركم واذكروا اذ جعلكم خلفاء من بعد قوم نوح وزادكم في الخلق بصطه فاذكروا ءالاء الله لعلكم تفلحون', 8, 16, 64, 1, 2, 159, false, NULL),
    (1024, 'tanzil-uthmani-v1.1', 7, 70, 'قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', '5f40a33b03e855520a64cb2385be5e9dcb900d71d1cc01a5e017baafafc13233', 'قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', '5f40a33b03e855520a64cb2385be5e9dcb900d71d1cc01a5e017baafafc13233', '5f40a33b03e855520a64cb2385be5e9dcb900d71d1cc01a5e017baafafc13233', NULL, 'قالوا اجئتنا لنعبد الله وحده ونذر ما كان يعبد ءاباؤنا فاتنا بما تعدنا ان كنت من الصدقين', 8, 16, 64, 1, 2, 159, false, NULL),
    (1025, 'tanzil-uthmani-v1.1', 7, 71, 'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ أَتُجَٰدِلُونَنِى فِىٓ أَسْمَآءٍ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', '43c2ee059dae4b907c7e1a69acf6f52426903dda8fb7bccb5e1749d878a89ba1', 'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ أَتُجَٰدِلُونَنِى فِىٓ أَسْمَآءٍ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', '43c2ee059dae4b907c7e1a69acf6f52426903dda8fb7bccb5e1749d878a89ba1', '43c2ee059dae4b907c7e1a69acf6f52426903dda8fb7bccb5e1749d878a89ba1', NULL, 'قال قد وقع عليكم من ربكم رجس وغضب اتجدلونني في اسماء سميتموها انتم وءاباؤكم ما نزل الله بها من سلطن فانتظروا اني معكم من المنتظرين', 8, 16, 64, 1, 2, 159, false, NULL),
    (1026, 'tanzil-uthmani-v1.1', 7, 72, 'فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَمَا كَانُوا۟ مُؤْمِنِينَ', '368046e280179f3b74860be795b80bd333858fce061831400c6b34fc551aa769', 'فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَمَا كَانُوا۟ مُؤْمِنِينَ', '368046e280179f3b74860be795b80bd333858fce061831400c6b34fc551aa769', '368046e280179f3b74860be795b80bd333858fce061831400c6b34fc551aa769', NULL, 'فانجينه والذين معه برحمه منا وقطعنا دابر الذين كذبوا بايتنا وما كانوا مؤمنين', 8, 16, 64, 1, 2, 159, false, NULL),
    (1027, 'tanzil-uthmani-v1.1', 7, 73, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ', 'abcd1ca5d521a7dbb794f7841b0a71f3cd20c40ef6ba319667999eac7e7b0183', 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ', 'abcd1ca5d521a7dbb794f7841b0a71f3cd20c40ef6ba319667999eac7e7b0183', 'abcd1ca5d521a7dbb794f7841b0a71f3cd20c40ef6ba319667999eac7e7b0183', NULL, 'والي ثمود اخاهم صلحا قال يقوم اعبدوا الله ما لكم من اله غيره قد جاءتكم بينه من ربكم هذه ناقه الله لكم ءايه فذروها تاكل في ارض الله ولا تمسوها بسوء فياخذكم عذاب اليم', 8, 16, 64, 1, 2, 159, false, NULL),
    (1028, 'tanzil-uthmani-v1.1', 7, 74, 'وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًا فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '93ef2dd05712096d564181403098cf18a55183befccb1b7237d8f37a7427c049', 'وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًا فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '93ef2dd05712096d564181403098cf18a55183befccb1b7237d8f37a7427c049', '93ef2dd05712096d564181403098cf18a55183befccb1b7237d8f37a7427c049', NULL, 'واذكروا اذ جعلكم خلفاء من بعد عاد وبواكم في الارض تتخذون من سهولها قصورا وتنحتون الجبال بيوتا فاذكروا ءالاء الله ولا تعثوا في الارض مفسدين', 8, 16, 64, 1, 2, 160, false, NULL),
    (1029, 'tanzil-uthmani-v1.1', 7, 75, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَٰلِحًا مُّرْسَلٌ مِّن رَّبِّهِۦ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ', 'b21e85d9a1019958418252e410dd5ba53615dc95073cb68653dd9acc79e17094', 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَٰلِحًا مُّرْسَلٌ مِّن رَّبِّهِۦ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ', 'b21e85d9a1019958418252e410dd5ba53615dc95073cb68653dd9acc79e17094', 'b21e85d9a1019958418252e410dd5ba53615dc95073cb68653dd9acc79e17094', NULL, 'قال الملا الذين استكبروا من قومه للذين استضعفوا لمن ءامن منهم اتعلمون ان صلحا مرسل من ربه قالوا انا بما ارسل به مؤمنون', 8, 16, 64, 1, 2, 160, false, NULL),
    (1030, 'tanzil-uthmani-v1.1', 7, 76, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ', 'e6a29ab90afea779204b498dddf03170aa031dc2e76bef65dfdb14011210cf71', 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ', 'e6a29ab90afea779204b498dddf03170aa031dc2e76bef65dfdb14011210cf71', 'e6a29ab90afea779204b498dddf03170aa031dc2e76bef65dfdb14011210cf71', NULL, 'قال الذين استكبروا انا بالذي ءامنتم به كفرون', 8, 16, 64, 1, 2, 160, false, NULL),
    (1031, 'tanzil-uthmani-v1.1', 7, 77, 'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَٰصَٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ', '0d35c58b1502de51507b16ed0db3ee9feac976cdbde07d80d344f4a616f4fba8', 'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَٰصَٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ', '0d35c58b1502de51507b16ed0db3ee9feac976cdbde07d80d344f4a616f4fba8', '0d35c58b1502de51507b16ed0db3ee9feac976cdbde07d80d344f4a616f4fba8', NULL, 'فعقروا الناقه وعتوا عن امر ربهم وقالوا يصلح ائتنا بما تعدنا ان كنت من المرسلين', 8, 16, 64, 1, 2, 160, false, NULL),
    (1032, 'tanzil-uthmani-v1.1', 7, 78, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'a8aebf5cd3db0d3dd02c1604f05198839743b247523166d48ed0f0d8ddfdf316', 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'a8aebf5cd3db0d3dd02c1604f05198839743b247523166d48ed0f0d8ddfdf316', 'a8aebf5cd3db0d3dd02c1604f05198839743b247523166d48ed0f0d8ddfdf316', NULL, 'فاخذتهم الرجفه فاصبحوا في دارهم جثمين', 8, 16, 64, 1, 2, 160, false, NULL),
    (1033, 'tanzil-uthmani-v1.1', 7, 79, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ', '3016398734a7bce3b7bd5f3a92f2abf81303418c7c852166de5811606b3c8859', 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ', '3016398734a7bce3b7bd5f3a92f2abf81303418c7c852166de5811606b3c8859', '3016398734a7bce3b7bd5f3a92f2abf81303418c7c852166de5811606b3c8859', NULL, 'فتولي عنهم وقال يقوم لقد ابلغتكم رساله ربي ونصحت لكم ولكن لا تحبون النصحين', 8, 16, 64, 1, 2, 160, false, NULL),
    (1034, 'tanzil-uthmani-v1.1', 7, 80, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَٰلَمِينَ', '1fc419870bd0c83d44bbf822a83fe9aa25c964feaef24aeb91616a920c5d72d0', 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَٰلَمِينَ', '1fc419870bd0c83d44bbf822a83fe9aa25c964feaef24aeb91616a920c5d72d0', '1fc419870bd0c83d44bbf822a83fe9aa25c964feaef24aeb91616a920c5d72d0', NULL, 'ولوطا اذ قال لقومه اتاتون الفحشه ما سبقكم بها من احد من العلمين', 8, 16, 64, 1, 2, 160, false, NULL),
    (1035, 'tanzil-uthmani-v1.1', 7, 81, 'إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', '575a327dc319759a88c9c10f4d2f2c2c163c70e3171f3d7af436c164ab6bbf74', 'إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', '575a327dc319759a88c9c10f4d2f2c2c163c70e3171f3d7af436c164ab6bbf74', '575a327dc319759a88c9c10f4d2f2c2c163c70e3171f3d7af436c164ab6bbf74', NULL, 'انكم لتاتون الرجال شهوه من دون النساء بل انتم قوم مسرفون', 8, 16, 64, 1, 2, 160, false, NULL),
    (1036, 'tanzil-uthmani-v1.1', 7, 82, 'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', 'bd832c4a0dd9e129a6f23e41e7e7588aa8b6e9f22d16e3ffeb1b004d7d9f653c', 'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', 'bd832c4a0dd9e129a6f23e41e7e7588aa8b6e9f22d16e3ffeb1b004d7d9f653c', 'bd832c4a0dd9e129a6f23e41e7e7588aa8b6e9f22d16e3ffeb1b004d7d9f653c', NULL, 'وما كان جواب قومه الا ان قالوا اخرجوهم من قريتكم انهم اناس يتطهرون', 8, 16, 64, 1, 2, 161, false, NULL),
    (1037, 'tanzil-uthmani-v1.1', 7, 83, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', '68edf824207ccabce005713e5c2fab17e0545060241a5ea25dd8a64fd2041ee1', 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', '68edf824207ccabce005713e5c2fab17e0545060241a5ea25dd8a64fd2041ee1', '68edf824207ccabce005713e5c2fab17e0545060241a5ea25dd8a64fd2041ee1', NULL, 'فانجينه واهله الا امراته كانت من الغبرين', 8, 16, 64, 1, 2, 161, false, NULL),
    (1038, 'tanzil-uthmani-v1.1', 7, 84, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'bf29329a6a0e8bc7a73b65aa6575466febb24f4e9d365261d642b9a062f49a2a', 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'bf29329a6a0e8bc7a73b65aa6575466febb24f4e9d365261d642b9a062f49a2a', 'bf29329a6a0e8bc7a73b65aa6575466febb24f4e9d365261d642b9a062f49a2a', NULL, 'وامطرنا عليهم مطرا فانظر كيف كان عقبه المجرمين', 8, 16, 64, 1, 2, 161, false, NULL),
    (1039, 'tanzil-uthmani-v1.1', 7, 85, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', '0c45a43090229d464a5ab5d77e59a1ba5339c1f029ff3c81f1e8602a7716ee18', 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', '0c45a43090229d464a5ab5d77e59a1ba5339c1f029ff3c81f1e8602a7716ee18', '0c45a43090229d464a5ab5d77e59a1ba5339c1f029ff3c81f1e8602a7716ee18', NULL, 'والي مدين اخاهم شعيبا قال يقوم اعبدوا الله ما لكم من اله غيره قد جاءتكم بينه من ربكم فاوفوا الكيل والميزان ولا تبخسوا الناس اشياءهم ولا تفسدوا في الارض بعد اصلحها ذلكم خير لكم ان كنتم مؤمنين', 8, 16, 64, 1, 2, 161, false, NULL),
    (1040, 'tanzil-uthmani-v1.1', 7, 86, 'وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًا وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ وَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', '803a78030448891ada823792939778876b0c2c9bd012781e5cdd04b5ab263af8', 'وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًا وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ وَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', '803a78030448891ada823792939778876b0c2c9bd012781e5cdd04b5ab263af8', '803a78030448891ada823792939778876b0c2c9bd012781e5cdd04b5ab263af8', NULL, 'ولا تقعدوا بكل صرط توعدون وتصدون عن سبيل الله من ءامن به وتبغونها عوجا واذكروا اذ كنتم قليلا فكثركم وانظروا كيف كان عقبه المفسدين', 8, 16, 64, 1, 2, 161, false, NULL),
    (1041, 'tanzil-uthmani-v1.1', 7, 87, 'وَإِن كَانَ طَآئِفَةٌ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'b98f3a6d4d6d0f62b2581a4a00410636f9397313776e9942adb54ac0f5cdcc92', 'وَإِن كَانَ طَآئِفَةٌ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'b98f3a6d4d6d0f62b2581a4a00410636f9397313776e9942adb54ac0f5cdcc92', 'b98f3a6d4d6d0f62b2581a4a00410636f9397313776e9942adb54ac0f5cdcc92', NULL, 'وان كان طائفه منكم ءامنوا بالذي ارسلت به وطائفه لم يؤمنوا فاصبروا حتي يحكم الله بيننا وهو خير الحكمين', 8, 16, 64, 1, 2, 161, false, NULL),
    (1042, 'tanzil-uthmani-v1.1', 7, 88, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا قَالَ أَوَلَوْ كُنَّا كَٰرِهِينَ', 'b342c7801d83e4be379d56853641d8b8d93e9185b47e1af37683e370c8435d60', 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا قَالَ أَوَلَوْ كُنَّا كَٰرِهِينَ', 'b342c7801d83e4be379d56853641d8b8d93e9185b47e1af37683e370c8435d60', 'b342c7801d83e4be379d56853641d8b8d93e9185b47e1af37683e370c8435d60', NULL, 'قال الملا الذين استكبروا من قومه لنخرجنك يشعيب والذين ءامنوا معك من قريتنا او لتعودن في ملتنا قال اولو كنا كرهين', 9, 17, 65, 1, 2, 162, false, NULL),
    (1043, 'tanzil-uthmani-v1.1', 7, 89, 'قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَٰتِحِينَ', '2decb9474ea4183f5c662145dd3ce73dd0a81113cb14cda196855cb0fef87aaf', 'قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَٰتِحِينَ', '2decb9474ea4183f5c662145dd3ce73dd0a81113cb14cda196855cb0fef87aaf', '2decb9474ea4183f5c662145dd3ce73dd0a81113cb14cda196855cb0fef87aaf', NULL, 'قد افترينا علي الله كذبا ان عدنا في ملتكم بعد اذ نجينا الله منها وما يكون لنا ان نعود فيها الا ان يشاء الله ربنا وسع ربنا كل شيء علما علي الله توكلنا ربنا افتح بيننا وبين قومنا بالحق وانت خير الفتحين', 9, 17, 65, 1, 2, 162, false, NULL),
    (1044, 'tanzil-uthmani-v1.1', 7, 90, 'وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَٰسِرُونَ', 'e28e22d60a3a3e5ffafa7ca0838b8d065ac3b2e2c783b2191c804eace2f80f3b', 'وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَٰسِرُونَ', 'e28e22d60a3a3e5ffafa7ca0838b8d065ac3b2e2c783b2191c804eace2f80f3b', 'e28e22d60a3a3e5ffafa7ca0838b8d065ac3b2e2c783b2191c804eace2f80f3b', NULL, 'وقال الملا الذين كفروا من قومه لئن اتبعتم شعيبا انكم اذا لخسرون', 9, 17, 65, 1, 2, 162, false, NULL),
    (1045, 'tanzil-uthmani-v1.1', 7, 91, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'a8aebf5cd3db0d3dd02c1604f05198839743b247523166d48ed0f0d8ddfdf316', 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'a8aebf5cd3db0d3dd02c1604f05198839743b247523166d48ed0f0d8ddfdf316', 'a8aebf5cd3db0d3dd02c1604f05198839743b247523166d48ed0f0d8ddfdf316', NULL, 'فاخذتهم الرجفه فاصبحوا في دارهم جثمين', 9, 17, 65, 1, 2, 162, false, NULL),
    (1046, 'tanzil-uthmani-v1.1', 7, 92, 'ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَانُوا۟ هُمُ ٱلْخَٰسِرِينَ', '24fccce22a6e5e84875962fba3af758c78d091f6a97412c5306b5a932b484b77', 'ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَانُوا۟ هُمُ ٱلْخَٰسِرِينَ', '24fccce22a6e5e84875962fba3af758c78d091f6a97412c5306b5a932b484b77', '24fccce22a6e5e84875962fba3af758c78d091f6a97412c5306b5a932b484b77', NULL, 'الذين كذبوا شعيبا كان لم يغنوا فيها الذين كذبوا شعيبا كانوا هم الخسرين', 9, 17, 65, 1, 2, 162, false, NULL),
    (1047, 'tanzil-uthmani-v1.1', 7, 93, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَٰلَٰتِ رَبِّى وَنَصَحْتُ لَكُمْ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍ كَٰفِرِينَ', '256acd7645d325ef353f82f09b1f70343e2ccae76d9f0abb761f942f3dd7658f', 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَٰلَٰتِ رَبِّى وَنَصَحْتُ لَكُمْ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍ كَٰفِرِينَ', '256acd7645d325ef353f82f09b1f70343e2ccae76d9f0abb761f942f3dd7658f', '256acd7645d325ef353f82f09b1f70343e2ccae76d9f0abb761f942f3dd7658f', NULL, 'فتولي عنهم وقال يقوم لقد ابلغتكم رسلت ربي ونصحت لكم فكيف ءاسي علي قوم كفرين', 9, 17, 65, 1, 2, 162, false, NULL),
    (1048, 'tanzil-uthmani-v1.1', 7, 94, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ', 'f78bdbc9d1223fd2310ef3c21f2fe14a080d1bf001cf59dc0e608bd66bc733a2', 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ', 'f78bdbc9d1223fd2310ef3c21f2fe14a080d1bf001cf59dc0e608bd66bc733a2', 'f78bdbc9d1223fd2310ef3c21f2fe14a080d1bf001cf59dc0e608bd66bc733a2', NULL, 'وما ارسلنا في قريه من نبي الا اخذنا اهلها بالباساء والضراء لعلهم يضرعون', 9, 17, 65, 1, 2, 162, false, NULL),
    (1049, 'tanzil-uthmani-v1.1', 7, 95, 'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', '7065f288bbffd4ca026aba76dc849d3dcab9f468c4ace5409333c580a07dbdac', 'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', '7065f288bbffd4ca026aba76dc849d3dcab9f468c4ace5409333c580a07dbdac', '7065f288bbffd4ca026aba76dc849d3dcab9f468c4ace5409333c580a07dbdac', NULL, 'ثم بدلنا مكان السيئه الحسنه حتي عفوا وقالوا قد مس ءاباءنا الضراء والسراء فاخذنهم بغته وهم لا يشعرون', 9, 17, 65, 1, 2, 162, false, NULL),
    (1050, 'tanzil-uthmani-v1.1', 7, 96, 'وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَٰكِن كَذَّبُوا۟ فَأَخَذْنَٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ', 'af5a653cbc1f7f9fe8c9ccdd4bff9a176c022c63fd71e2af0eec5b5be5b8fcda', 'وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَٰكِن كَذَّبُوا۟ فَأَخَذْنَٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ', 'af5a653cbc1f7f9fe8c9ccdd4bff9a176c022c63fd71e2af0eec5b5be5b8fcda', 'af5a653cbc1f7f9fe8c9ccdd4bff9a176c022c63fd71e2af0eec5b5be5b8fcda', NULL, 'ولو ان اهل القري ءامنوا واتقوا لفتحنا عليهم بركت من السماء والارض ولكن كذبوا فاخذنهم بما كانوا يكسبون', 9, 17, 65, 1, 2, 163, false, NULL),
    (1051, 'tanzil-uthmani-v1.1', 7, 97, 'أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَٰتًا وَهُمْ نَآئِمُونَ', '1456c975233c910db55fe16349398107082bbf7f60c90e8415945bc93dd2fab3', 'أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَٰتًا وَهُمْ نَآئِمُونَ', '1456c975233c910db55fe16349398107082bbf7f60c90e8415945bc93dd2fab3', '1456c975233c910db55fe16349398107082bbf7f60c90e8415945bc93dd2fab3', NULL, 'افامن اهل القري ان ياتيهم باسنا بيتا وهم نائمون', 9, 17, 65, 1, 2, 163, false, NULL),
    (1052, 'tanzil-uthmani-v1.1', 7, 98, 'أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ', '68121cc1b76892f8f9837c58649baee022673815b2e8fd82517bd886065f153d', 'أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ', '68121cc1b76892f8f9837c58649baee022673815b2e8fd82517bd886065f153d', '68121cc1b76892f8f9837c58649baee022673815b2e8fd82517bd886065f153d', NULL, 'اوامن اهل القري ان ياتيهم باسنا ضحي وهم يلعبون', 9, 17, 65, 1, 2, 163, false, NULL),
    (1053, 'tanzil-uthmani-v1.1', 7, 99, 'أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَٰسِرُونَ', '754e0f2ba6800994974ef8b827b849ce3bc5e36d636268f6d8c48a14c3576d44', 'أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَٰسِرُونَ', '754e0f2ba6800994974ef8b827b849ce3bc5e36d636268f6d8c48a14c3576d44', '754e0f2ba6800994974ef8b827b849ce3bc5e36d636268f6d8c48a14c3576d44', NULL, 'افامنوا مكر الله فلا يامن مكر الله الا القوم الخسرون', 9, 17, 65, 1, 2, 163, false, NULL),
    (1054, 'tanzil-uthmani-v1.1', 7, 100, 'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَٰهُم بِذُنُوبِهِمْ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ', '21a0a5b2ed14983f81945543b36dc3a9c2da69331fcd5095e886dd36c9ab238f', 'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَٰهُم بِذُنُوبِهِمْ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ', '21a0a5b2ed14983f81945543b36dc3a9c2da69331fcd5095e886dd36c9ab238f', '21a0a5b2ed14983f81945543b36dc3a9c2da69331fcd5095e886dd36c9ab238f', NULL, 'اولم يهد للذين يرثون الارض من بعد اهلها ان لو نشاء اصبنهم بذنوبهم ونطبع علي قلوبهم فهم لا يسمعون', 9, 17, 65, 1, 2, 163, false, NULL),
    (1055, 'tanzil-uthmani-v1.1', 7, 101, 'تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَٰفِرِينَ', 'eaffbf8ecebdf3350730bb68a4e1d12c9f9186c219583be6b73da8d1c60e6ada', 'تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَٰفِرِينَ', 'eaffbf8ecebdf3350730bb68a4e1d12c9f9186c219583be6b73da8d1c60e6ada', 'eaffbf8ecebdf3350730bb68a4e1d12c9f9186c219583be6b73da8d1c60e6ada', NULL, 'تلك القري نقص عليك من انبائها ولقد جاءتهم رسلهم بالبينت فما كانوا ليؤمنوا بما كذبوا من قبل كذلك يطبع الله علي قلوب الكفرين', 9, 17, 65, 1, 2, 163, false, NULL),
    (1056, 'tanzil-uthmani-v1.1', 7, 102, 'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَٰسِقِينَ', 'c002ae97b8b8a9d482de56b2d5f758f4b680b4bd50b98bf06cd363e02899cf39', 'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَٰسِقِينَ', 'c002ae97b8b8a9d482de56b2d5f758f4b680b4bd50b98bf06cd363e02899cf39', 'c002ae97b8b8a9d482de56b2d5f758f4b680b4bd50b98bf06cd363e02899cf39', NULL, 'وما وجدنا لاكثرهم من عهد وان وجدنا اكثرهم لفسقين', 9, 17, 65, 1, 2, 163, false, NULL),
    (1057, 'tanzil-uthmani-v1.1', 7, 103, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', '2ce6211f397904cbfafee5c0610cd1dd092ced001249c1dca09287913750a2f1', 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', '2ce6211f397904cbfafee5c0610cd1dd092ced001249c1dca09287913750a2f1', '2ce6211f397904cbfafee5c0610cd1dd092ced001249c1dca09287913750a2f1', NULL, 'ثم بعثنا من بعدهم موسي بايتنا الي فرعون وملايه فظلموا بها فانظر كيف كان عقبه المفسدين', 9, 17, 65, 1, 2, 163, false, NULL),
    (1058, 'tanzil-uthmani-v1.1', 7, 104, 'وَقَالَ مُوسَىٰ يَٰفِرْعَوْنُ إِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'd46da691d09456ea9b537ab19e1304f77c2a35242c1eb07853d73495ed5230ec', 'وَقَالَ مُوسَىٰ يَٰفِرْعَوْنُ إِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 'd46da691d09456ea9b537ab19e1304f77c2a35242c1eb07853d73495ed5230ec', 'd46da691d09456ea9b537ab19e1304f77c2a35242c1eb07853d73495ed5230ec', NULL, 'وقال موسي يفرعون اني رسول من رب العلمين', 9, 17, 65, 1, 2, 163, false, NULL),
    (1059, 'tanzil-uthmani-v1.1', 7, 105, 'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ قَدْ جِئْتُكُم بِبَيِّنَةٍ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ', '5ba5c5cabfbd71de71ee1e24693daf4b53dae692d9fe07b642b0ec6768eb7799', 'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ قَدْ جِئْتُكُم بِبَيِّنَةٍ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ', '5ba5c5cabfbd71de71ee1e24693daf4b53dae692d9fe07b642b0ec6768eb7799', '5ba5c5cabfbd71de71ee1e24693daf4b53dae692d9fe07b642b0ec6768eb7799', NULL, 'حقيق علي ان لا اقول علي الله الا الحق قد جئتكم ببينه من ربكم فارسل معي بني اسرءيل', 9, 17, 65, 1, 2, 164, false, NULL),
    (1060, 'tanzil-uthmani-v1.1', 7, 106, 'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', '2ddd3c561688ec68325f93e7ea0778d3f36f4019cc5c83da7d349c1a1d0cc390', 'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', '2ddd3c561688ec68325f93e7ea0778d3f36f4019cc5c83da7d349c1a1d0cc390', '2ddd3c561688ec68325f93e7ea0778d3f36f4019cc5c83da7d349c1a1d0cc390', NULL, 'قال ان كنت جئت بايه فات بها ان كنت من الصدقين', 9, 17, 65, 1, 2, 164, false, NULL),
    (1061, 'tanzil-uthmani-v1.1', 7, 107, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ', 'ca1e9a42b2bb560c3e07f5c3975985e11cbad81314678a2dd0600fee138037bc', 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ', 'ca1e9a42b2bb560c3e07f5c3975985e11cbad81314678a2dd0600fee138037bc', 'ca1e9a42b2bb560c3e07f5c3975985e11cbad81314678a2dd0600fee138037bc', NULL, 'فالقي عصاه فاذا هي ثعبان مبين', 9, 17, 65, 1, 2, 164, false, NULL),
    (1062, 'tanzil-uthmani-v1.1', 7, 108, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', '8de006a1b5717fa4e4d11d02e6957ff8ec1f583a37792997b54d4c6d936cb643', 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', '8de006a1b5717fa4e4d11d02e6957ff8ec1f583a37792997b54d4c6d936cb643', '8de006a1b5717fa4e4d11d02e6957ff8ec1f583a37792997b54d4c6d936cb643', NULL, 'ونزع يده فاذا هي بيضاء للنظرين', 9, 17, 65, 1, 2, 164, false, NULL),
    (1063, 'tanzil-uthmani-v1.1', 7, 109, 'قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌ', '11f1d0ab358ca99a341bc03d6e5b3f2f52038c653a3092b69c11bb586ff5fc29', 'قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌ', '11f1d0ab358ca99a341bc03d6e5b3f2f52038c653a3092b69c11bb586ff5fc29', '11f1d0ab358ca99a341bc03d6e5b3f2f52038c653a3092b69c11bb586ff5fc29', NULL, 'قال الملا من قوم فرعون ان هذا لسحر عليم', 9, 17, 65, 1, 2, 164, false, NULL),
    (1064, 'tanzil-uthmani-v1.1', 7, 110, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ فَمَاذَا تَأْمُرُونَ', '924b694207a77bc2d641f8dfdd76af8c8ef2aab65e63c0ab4a50d09391ec10bc', 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ فَمَاذَا تَأْمُرُونَ', '924b694207a77bc2d641f8dfdd76af8c8ef2aab65e63c0ab4a50d09391ec10bc', '924b694207a77bc2d641f8dfdd76af8c8ef2aab65e63c0ab4a50d09391ec10bc', NULL, 'يريد ان يخرجكم من ارضكم فماذا تامرون', 9, 17, 65, 1, 2, 164, false, NULL),
    (1065, 'tanzil-uthmani-v1.1', 7, 111, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'ab9cad6d6865209a20355682d957b61ff266279fa1b2a18cc50611fd23e2fc17', 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 'ab9cad6d6865209a20355682d957b61ff266279fa1b2a18cc50611fd23e2fc17', 'ab9cad6d6865209a20355682d957b61ff266279fa1b2a18cc50611fd23e2fc17', NULL, 'قالوا ارجه واخاه وارسل في المدائن حشرين', 9, 17, 65, 1, 2, 164, false, NULL),
    (1066, 'tanzil-uthmani-v1.1', 7, 112, 'يَأْتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٍ', 'c0ca58774166a450f4b302c4ecb4c70f5601b89eaa0956516eaed2dfac2bf7bf', 'يَأْتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٍ', 'c0ca58774166a450f4b302c4ecb4c70f5601b89eaa0956516eaed2dfac2bf7bf', 'c0ca58774166a450f4b302c4ecb4c70f5601b89eaa0956516eaed2dfac2bf7bf', NULL, 'ياتوك بكل سحر عليم', 9, 17, 65, 1, 2, 164, false, NULL),
    (1067, 'tanzil-uthmani-v1.1', 7, 113, 'وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', '286713a4656ebc8dfac9097c81500ed5da747d9837dd8c375f23797186bbc83f', 'وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', '286713a4656ebc8dfac9097c81500ed5da747d9837dd8c375f23797186bbc83f', '286713a4656ebc8dfac9097c81500ed5da747d9837dd8c375f23797186bbc83f', NULL, 'وجاء السحره فرعون قالوا ان لنا لاجرا ان كنا نحن الغلبين', 9, 17, 65, 1, 2, 164, false, NULL),
    (1068, 'tanzil-uthmani-v1.1', 7, 114, 'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ', 'ba9fbf05ffb6e14162827c3e9944649d459ddc280b873adffe775b8817d9a817', 'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ', 'ba9fbf05ffb6e14162827c3e9944649d459ddc280b873adffe775b8817d9a817', 'ba9fbf05ffb6e14162827c3e9944649d459ddc280b873adffe775b8817d9a817', NULL, 'قال نعم وانكم لمن المقربين', 9, 17, 65, 1, 2, 164, false, NULL),
    (1069, 'tanzil-uthmani-v1.1', 7, 115, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ', 'd131a8d3897e53b0b79994d28b37a8c757bc539e263d3c214dbbb513ec53c992', 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ', 'd131a8d3897e53b0b79994d28b37a8c757bc539e263d3c214dbbb513ec53c992', 'd131a8d3897e53b0b79994d28b37a8c757bc539e263d3c214dbbb513ec53c992', NULL, 'قالوا يموسي اما ان تلقي واما ان نكون نحن الملقين', 9, 17, 65, 1, 2, 164, false, NULL),
    (1070, 'tanzil-uthmani-v1.1', 7, 116, 'قَالَ أَلْقُوا۟ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍ', 'e7f56ae1286d15a0b9233631ecb7d306d3af532c19289871d70c0a278c469c93', 'قَالَ أَلْقُوا۟ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍ', 'e7f56ae1286d15a0b9233631ecb7d306d3af532c19289871d70c0a278c469c93', 'e7f56ae1286d15a0b9233631ecb7d306d3af532c19289871d70c0a278c469c93', NULL, 'قال القوا فلما القوا سحروا اعين الناس واسترهبوهم وجاءو بسحر عظيم', 9, 17, 65, 1, 2, 164, false, NULL),
    (1071, 'tanzil-uthmani-v1.1', 7, 117, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', '464eb3b56b4ab52576800243e906ac50354853daed11a4ee9bb191199f220c66', 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', '464eb3b56b4ab52576800243e906ac50354853daed11a4ee9bb191199f220c66', '464eb3b56b4ab52576800243e906ac50354853daed11a4ee9bb191199f220c66', NULL, 'واوحينا الي موسي ان الق عصاك فاذا هي تلقف ما يافكون', 9, 17, 66, 1, 2, 164, false, NULL),
    (1072, 'tanzil-uthmani-v1.1', 7, 118, 'فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ', '49efede1a535e62fa3db074ee83c032795385c33b0df132e766a156c689d2fbb', 'فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ', '49efede1a535e62fa3db074ee83c032795385c33b0df132e766a156c689d2fbb', '49efede1a535e62fa3db074ee83c032795385c33b0df132e766a156c689d2fbb', NULL, 'فوقع الحق وبطل ما كانوا يعملون', 9, 17, 66, 1, 2, 164, false, NULL),
    (1073, 'tanzil-uthmani-v1.1', 7, 119, 'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَٰغِرِينَ', '66ac30a340aaa1f2bf5d9e3d41e9ebafb65bb58626d7f658679146144f503ef5', 'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَٰغِرِينَ', '66ac30a340aaa1f2bf5d9e3d41e9ebafb65bb58626d7f658679146144f503ef5', '66ac30a340aaa1f2bf5d9e3d41e9ebafb65bb58626d7f658679146144f503ef5', NULL, 'فغلبوا هنالك وانقلبوا صغرين', 9, 17, 66, 1, 2, 164, false, NULL),
    (1074, 'tanzil-uthmani-v1.1', 7, 120, 'وَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'd63de914549e0816ce3efb72850f0c9a322f5c50c9fb455adff7f30d0a571ab5', 'وَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 'd63de914549e0816ce3efb72850f0c9a322f5c50c9fb455adff7f30d0a571ab5', 'd63de914549e0816ce3efb72850f0c9a322f5c50c9fb455adff7f30d0a571ab5', NULL, 'والقي السحره سجدين', 9, 17, 66, 1, 2, 164, false, NULL),
    (1075, 'tanzil-uthmani-v1.1', 7, 121, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', '44c4f7e31cb2d958010c9efd86858f9b86e703502b7f43de87bf321aa119f263', 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', '44c4f7e31cb2d958010c9efd86858f9b86e703502b7f43de87bf321aa119f263', '44c4f7e31cb2d958010c9efd86858f9b86e703502b7f43de87bf321aa119f263', NULL, 'قالوا ءامنا برب العلمين', 9, 17, 66, 1, 2, 165, false, NULL),
    (1076, 'tanzil-uthmani-v1.1', 7, 122, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'd305a99b800520707ad552e6b13323196b763f6e70dcbea623242935da54f63b', 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'd305a99b800520707ad552e6b13323196b763f6e70dcbea623242935da54f63b', 'd305a99b800520707ad552e6b13323196b763f6e70dcbea623242935da54f63b', NULL, 'رب موسي وهرون', 9, 17, 66, 1, 2, 165, false, NULL),
    (1077, 'tanzil-uthmani-v1.1', 7, 123, 'قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّ هَٰذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا فَسَوْفَ تَعْلَمُونَ', 'd8ff2d6c9d8ad1bbadb2455d51a6230ecb89f5ef2d146688c1a4d89f509841fa', 'قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّ هَٰذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا فَسَوْفَ تَعْلَمُونَ', 'd8ff2d6c9d8ad1bbadb2455d51a6230ecb89f5ef2d146688c1a4d89f509841fa', 'd8ff2d6c9d8ad1bbadb2455d51a6230ecb89f5ef2d146688c1a4d89f509841fa', NULL, 'قال فرعون ءامنتم به قبل ان ءاذن لكم ان هذا لمكر مكرتموه في المدينه لتخرجوا منها اهلها فسوف تعلمون', 9, 17, 66, 1, 2, 165, false, NULL),
    (1078, 'tanzil-uthmani-v1.1', 7, 124, 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', '59b77dacc4fd41089ba9162fdb6cc265a7c1195a563b1854bd0eace1d2dad5cf', 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', '59b77dacc4fd41089ba9162fdb6cc265a7c1195a563b1854bd0eace1d2dad5cf', '59b77dacc4fd41089ba9162fdb6cc265a7c1195a563b1854bd0eace1d2dad5cf', NULL, 'لاقطعن ايديكم وارجلكم من خلف ثم لاصلبنكم اجمعين', 9, 17, 66, 1, 2, 165, false, NULL),
    (1079, 'tanzil-uthmani-v1.1', 7, 125, 'قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'bac7bb4219968574120f1e397d954bf9496b5b0941ebd2ecaf11006c521e28db', 'قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 'bac7bb4219968574120f1e397d954bf9496b5b0941ebd2ecaf11006c521e28db', 'bac7bb4219968574120f1e397d954bf9496b5b0941ebd2ecaf11006c521e28db', NULL, 'قالوا انا الي ربنا منقلبون', 9, 17, 66, 1, 2, 165, false, NULL),
    (1080, 'tanzil-uthmani-v1.1', 7, 126, 'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتْنَا رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ', '28cc266779bed2c0da5e2b809e6766b66f6025b32e8e7dd7afb0ff40160bfe9b', 'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتْنَا رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ', '28cc266779bed2c0da5e2b809e6766b66f6025b32e8e7dd7afb0ff40160bfe9b', '28cc266779bed2c0da5e2b809e6766b66f6025b32e8e7dd7afb0ff40160bfe9b', NULL, 'وما تنقم منا الا ان ءامنا بايت ربنا لما جاءتنا ربنا افرغ علينا صبرا وتوفنا مسلمين', 9, 17, 66, 1, 2, 165, false, NULL),
    (1081, 'tanzil-uthmani-v1.1', 7, 127, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَٰهِرُونَ', '63ad9809c293b3764e50868b65839876230cdfc47193f2eabe5fac8f6a9f77c8', 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَٰهِرُونَ', '63ad9809c293b3764e50868b65839876230cdfc47193f2eabe5fac8f6a9f77c8', '63ad9809c293b3764e50868b65839876230cdfc47193f2eabe5fac8f6a9f77c8', NULL, 'وقال الملا من قوم فرعون اتذر موسي وقومه ليفسدوا في الارض ويذرك وءالهتك قال سنقتل ابناءهم ونستحي نساءهم وانا فوقهم قهرون', 9, 17, 66, 1, 2, 165, false, NULL),
    (1082, 'tanzil-uthmani-v1.1', 7, 128, 'قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', 'f29e3ad0a46c3166f7dd8b9d61f230faf83acaf4e3906f5cde65a95fdb3fc777', 'قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', 'f29e3ad0a46c3166f7dd8b9d61f230faf83acaf4e3906f5cde65a95fdb3fc777', 'f29e3ad0a46c3166f7dd8b9d61f230faf83acaf4e3906f5cde65a95fdb3fc777', NULL, 'قال موسي لقومه استعينوا بالله واصبروا ان الارض لله يورثها من يشاء من عباده والعقبه للمتقين', 9, 17, 66, 1, 2, 165, false, NULL),
    (1083, 'tanzil-uthmani-v1.1', 7, 129, 'قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', '0ed7779438281ae69bec4698a5606c62667c003e7b97878301aa82a3658bb556', 'قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', '0ed7779438281ae69bec4698a5606c62667c003e7b97878301aa82a3658bb556', '0ed7779438281ae69bec4698a5606c62667c003e7b97878301aa82a3658bb556', NULL, 'قالوا اوذينا من قبل ان تاتينا ومن بعد ما جئتنا قال عسي ربكم ان يهلك عدوكم ويستخلفكم في الارض فينظر كيف تعملون', 9, 17, 66, 1, 2, 165, false, NULL),
    (1084, 'tanzil-uthmani-v1.1', 7, 130, 'وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ', '15c94dec33ce082681d693ecb5dea1e85f8debe1fc31b80de8406eaabe4ee67f', 'وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ', '15c94dec33ce082681d693ecb5dea1e85f8debe1fc31b80de8406eaabe4ee67f', '15c94dec33ce082681d693ecb5dea1e85f8debe1fc31b80de8406eaabe4ee67f', NULL, 'ولقد اخذنا ءال فرعون بالسنين ونقص من الثمرت لعلهم يذكرون', 9, 17, 66, 1, 2, 165, false, NULL),
    (1085, 'tanzil-uthmani-v1.1', 7, 131, 'فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَٰذِهِۦ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ أَلَآ إِنَّمَا طَٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'dadf77be86af42c901e2a0624bbb161638351824a2707043dbf6cefae45fc94a', 'فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَٰذِهِۦ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ أَلَآ إِنَّمَا طَٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'dadf77be86af42c901e2a0624bbb161638351824a2707043dbf6cefae45fc94a', 'dadf77be86af42c901e2a0624bbb161638351824a2707043dbf6cefae45fc94a', NULL, 'فاذا جاءتهم الحسنه قالوا لنا هذه وان تصبهم سيئه يطيروا بموسي ومن معه الا انما طئرهم عند الله ولكن اكثرهم لا يعلمون', 9, 17, 66, 1, 2, 166, false, NULL),
    (1086, 'tanzil-uthmani-v1.1', 7, 132, 'وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 'a2dd973363a45fdff0c61635b782a727584f5670aa59cec237a54ef9659ac68d', 'وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 'a2dd973363a45fdff0c61635b782a727584f5670aa59cec237a54ef9659ac68d', 'a2dd973363a45fdff0c61635b782a727584f5670aa59cec237a54ef9659ac68d', NULL, 'وقالوا مهما تاتنا به من ءايه لتسحرنا بها فما نحن لك بمؤمنين', 9, 17, 66, 1, 2, 166, false, NULL),
    (1087, 'tanzil-uthmani-v1.1', 7, 133, 'فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٍ مُّفَصَّلَٰتٍ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', 'b61716e79d2f8975cfe80c63b1272e34bb84471ae341cd57d1b21133609adafc', 'فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٍ مُّفَصَّلَٰتٍ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', 'b61716e79d2f8975cfe80c63b1272e34bb84471ae341cd57d1b21133609adafc', 'b61716e79d2f8975cfe80c63b1272e34bb84471ae341cd57d1b21133609adafc', NULL, 'فارسلنا عليهم الطوفان والجراد والقمل والضفادع والدم ءايت مفصلت فاستكبروا وكانوا قوما مجرمين', 9, 17, 66, 1, 2, 166, false, NULL),
    (1088, 'tanzil-uthmani-v1.1', 7, 134, 'وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ', '629b4d2814380765a209b06752b06138cf24224730b3a8dcd485c8a7bc0aa46e', 'وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ', '629b4d2814380765a209b06752b06138cf24224730b3a8dcd485c8a7bc0aa46e', '629b4d2814380765a209b06752b06138cf24224730b3a8dcd485c8a7bc0aa46e', NULL, 'ولما وقع عليهم الرجز قالوا يموسي ادع لنا ربك بما عهد عندك لئن كشفت عنا الرجز لنؤمنن لك ولنرسلن معك بني اسرءيل', 9, 17, 66, 1, 2, 166, false, NULL),
    (1089, 'tanzil-uthmani-v1.1', 7, 135, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ', 'ca35db6fea7aa8e1656ecab1590d6a2e5f2f7288f899cfb6be9241e3db117937', 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ', 'ca35db6fea7aa8e1656ecab1590d6a2e5f2f7288f899cfb6be9241e3db117937', 'ca35db6fea7aa8e1656ecab1590d6a2e5f2f7288f899cfb6be9241e3db117937', NULL, 'فلما كشفنا عنهم الرجز الي اجل هم بلغوه اذا هم ينكثون', 9, 17, 66, 1, 2, 166, false, NULL),
    (1090, 'tanzil-uthmani-v1.1', 7, 136, 'فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'a7bf774307fba354cc99637abea9c7e766701a6b73c267b39c97b5e821d63e93', 'فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'a7bf774307fba354cc99637abea9c7e766701a6b73c267b39c97b5e821d63e93', 'a7bf774307fba354cc99637abea9c7e766701a6b73c267b39c97b5e821d63e93', NULL, 'فانتقمنا منهم فاغرقنهم في اليم بانهم كذبوا بايتنا وكانوا عنها غفلين', 9, 17, 66, 1, 2, 166, false, NULL),
    (1091, 'tanzil-uthmani-v1.1', 7, 137, 'وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَٰرِقَ ٱلْأَرْضِ وَمَغَٰرِبَهَا ٱلَّتِى بَٰرَكْنَا فِيهَا وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ', '26ab6e640dfbcb6d5a6103565597062ec1f83c2eef545a564564b5abfa05455d', 'وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَٰرِقَ ٱلْأَرْضِ وَمَغَٰرِبَهَا ٱلَّتِى بَٰرَكْنَا فِيهَا وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ', '26ab6e640dfbcb6d5a6103565597062ec1f83c2eef545a564564b5abfa05455d', '26ab6e640dfbcb6d5a6103565597062ec1f83c2eef545a564564b5abfa05455d', NULL, 'واورثنا القوم الذين كانوا يستضعفون مشرق الارض ومغربها التي بركنا فيها وتمت كلمت ربك الحسني علي بني اسرءيل بما صبروا ودمرنا ما كان يصنع فرعون وقومه وما كانوا يعرشون', 9, 17, 66, 1, 2, 166, false, NULL),
    (1092, 'tanzil-uthmani-v1.1', 7, 138, 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍ لَّهُمْ قَالُوا۟ يَٰمُوسَى ٱجْعَل لَّنَآ إِلَٰهًا كَمَا لَهُمْ ءَالِهَةٌ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ', 'e6893a770d5c2b48c9bd8abec26a1e6a6f9f9522453dcc1fe847aaca4abeb031', 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍ لَّهُمْ قَالُوا۟ يَٰمُوسَى ٱجْعَل لَّنَآ إِلَٰهًا كَمَا لَهُمْ ءَالِهَةٌ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ', 'e6893a770d5c2b48c9bd8abec26a1e6a6f9f9522453dcc1fe847aaca4abeb031', 'e6893a770d5c2b48c9bd8abec26a1e6a6f9f9522453dcc1fe847aaca4abeb031', NULL, 'وجوزنا ببني اسرءيل البحر فاتوا علي قوم يعكفون علي اصنام لهم قالوا يموسي اجعل لنا الها كما لهم ءالهه قال انكم قوم تجهلون', 9, 17, 66, 1, 2, 167, false, NULL),
    (1093, 'tanzil-uthmani-v1.1', 7, 139, 'إِنَّ هَٰٓؤُلَآءِ مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ', 'fd70faaf141adef9b2709fc2afedfbb57728f343bb56da4c1e8e225e058e5446', 'إِنَّ هَٰٓؤُلَآءِ مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ', 'fd70faaf141adef9b2709fc2afedfbb57728f343bb56da4c1e8e225e058e5446', 'fd70faaf141adef9b2709fc2afedfbb57728f343bb56da4c1e8e225e058e5446', NULL, 'ان هؤلاء متبر ما هم فيه وبطل ما كانوا يعملون', 9, 17, 66, 1, 2, 167, false, NULL),
    (1094, 'tanzil-uthmani-v1.1', 7, 140, 'قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَٰهًا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَٰلَمِينَ', '1482882b714f902c9207b8babeeacd4468bf3833525f06034d90339ab7bfa8cf', 'قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَٰهًا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَٰلَمِينَ', '1482882b714f902c9207b8babeeacd4468bf3833525f06034d90339ab7bfa8cf', '1482882b714f902c9207b8babeeacd4468bf3833525f06034d90339ab7bfa8cf', NULL, 'قال اغير الله ابغيكم الها وهو فضلكم علي العلمين', 9, 17, 66, 1, 2, 167, false, NULL),
    (1095, 'tanzil-uthmani-v1.1', 7, 141, 'وَإِذْ أَنجَيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'bb84fd49f9b188e7356d83107b85d362f07fb6b22d7715a0961bc80db172d2e4', 'وَإِذْ أَنجَيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', 'bb84fd49f9b188e7356d83107b85d362f07fb6b22d7715a0961bc80db172d2e4', 'bb84fd49f9b188e7356d83107b85d362f07fb6b22d7715a0961bc80db172d2e4', NULL, 'واذ انجينكم من ءال فرعون يسومونكم سوء العذاب يقتلون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم', 9, 17, 66, 1, 2, 167, false, NULL),
    (1096, 'tanzil-uthmani-v1.1', 7, 142, 'وَوَٰعَدْنَا مُوسَىٰ ثَلَٰثِينَ لَيْلَةً وَأَتْمَمْنَٰهَا بِعَشْرٍ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ', 'fbb8a13dab09bde7aec429d9f1f2994a7fb3f2235970f6d1c9e5658793d733a8', 'وَوَٰعَدْنَا مُوسَىٰ ثَلَٰثِينَ لَيْلَةً وَأَتْمَمْنَٰهَا بِعَشْرٍ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ', 'fbb8a13dab09bde7aec429d9f1f2994a7fb3f2235970f6d1c9e5658793d733a8', 'fbb8a13dab09bde7aec429d9f1f2994a7fb3f2235970f6d1c9e5658793d733a8', NULL, 'ووعدنا موسي ثلثين ليله واتممنها بعشر فتم ميقت ربه اربعين ليله وقال موسي لاخيه هرون اخلفني في قومي واصلح ولا تتبع سبيل المفسدين', 9, 17, 67, 1, 2, 167, false, NULL),
    (1097, 'tanzil-uthmani-v1.1', 7, 143, 'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ قَالَ لَن تَرَىٰنِى وَلَٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّا وَخَرَّ مُوسَىٰ صَعِقًا فَلَمَّآ أَفَاقَ قَالَ سُبْحَٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ', 'bc0e3e5bccb25d088a998ac065612b0d036e7ddbb055fd09740df9d274b04153', 'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ قَالَ لَن تَرَىٰنِى وَلَٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّا وَخَرَّ مُوسَىٰ صَعِقًا فَلَمَّآ أَفَاقَ قَالَ سُبْحَٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ', 'bc0e3e5bccb25d088a998ac065612b0d036e7ddbb055fd09740df9d274b04153', 'bc0e3e5bccb25d088a998ac065612b0d036e7ddbb055fd09740df9d274b04153', NULL, 'ولما جاء موسي لميقتنا وكلمه ربه قال رب ارني انظر اليك قال لن تريني ولكن انظر الي الجبل فان استقر مكانه فسوف تريني فلما تجلي ربه للجبل جعله دكا وخر موسي صعقا فلما افاق قال سبحنك تبت اليك وانا اول المؤمنين', 9, 17, 67, 1, 2, 167, false, NULL),
    (1098, 'tanzil-uthmani-v1.1', 7, 144, 'قَالَ يَٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِى وَبِكَلَٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّٰكِرِينَ', '2ac5338f31a855dda53c56e1d1bdb483981811f7aa8790a4f7f3bb767748d858', 'قَالَ يَٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِى وَبِكَلَٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّٰكِرِينَ', '2ac5338f31a855dda53c56e1d1bdb483981811f7aa8790a4f7f3bb767748d858', '2ac5338f31a855dda53c56e1d1bdb483981811f7aa8790a4f7f3bb767748d858', NULL, 'قال يموسي اني اصطفيتك علي الناس برسلتي وبكلمي فخذ ما ءاتيتك وكن من الشكرين', 9, 17, 67, 1, 2, 168, false, NULL),
    (1099, 'tanzil-uthmani-v1.1', 7, 145, 'وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَىْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا سَأُو۟رِيكُمْ دَارَ ٱلْفَٰسِقِينَ', 'f087fb19f7b13c15f7e5dbc097ff371bf03d2567df43f8988c2063dc071a2eee', 'وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَىْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا سَأُو۟رِيكُمْ دَارَ ٱلْفَٰسِقِينَ', 'f087fb19f7b13c15f7e5dbc097ff371bf03d2567df43f8988c2063dc071a2eee', 'f087fb19f7b13c15f7e5dbc097ff371bf03d2567df43f8988c2063dc071a2eee', NULL, 'وكتبنا له في الالواح من كل شيء موعظه وتفصيلا لكل شيء فخذها بقوه وامر قومك ياخذوا باحسنها ساوريكم دار الفسقين', 9, 17, 67, 1, 2, 168, false, NULL),
    (1100, 'tanzil-uthmani-v1.1', 7, 146, 'سَأَصْرِفُ عَنْ ءَايَٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًا ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'f6e2696c35726242db1e6581200e69e591a3eb6ee183805778419b50cb76920d', 'سَأَصْرِفُ عَنْ ءَايَٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًا ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 'f6e2696c35726242db1e6581200e69e591a3eb6ee183805778419b50cb76920d', 'f6e2696c35726242db1e6581200e69e591a3eb6ee183805778419b50cb76920d', NULL, 'ساصرف عن ءايتي الذين يتكبرون في الارض بغير الحق وان يروا كل ءايه لا يؤمنوا بها وان يروا سبيل الرشد لا يتخذوه سبيلا وان يروا سبيل الغي يتخذوه سبيلا ذلك بانهم كذبوا بايتنا وكانوا عنها غفلين', 9, 17, 67, 1, 2, 168, false, NULL),
    (1101, 'tanzil-uthmani-v1.1', 7, 147, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلْـَٔاخِرَةِ حَبِطَتْ أَعْمَٰلُهُمْ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', '5da9670042e10b27389df2c8a41b23ef7d1b979c67711e107ea83e27015eb2b8', 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلْـَٔاخِرَةِ حَبِطَتْ أَعْمَٰلُهُمْ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', '5da9670042e10b27389df2c8a41b23ef7d1b979c67711e107ea83e27015eb2b8', '5da9670042e10b27389df2c8a41b23ef7d1b979c67711e107ea83e27015eb2b8', NULL, 'والذين كذبوا بايتنا ولقاء الاخره حبطت اعملهم هل يجزون الا ما كانوا يعملون', 9, 17, 67, 1, 2, 168, false, NULL),
    (1102, 'tanzil-uthmani-v1.1', 7, 148, 'وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ٱتَّخَذُوهُ وَكَانُوا۟ ظَٰلِمِينَ', '6e06973c14959c4f91af6f7f0babac4717422108e0a83896dda4e818f5e3fde2', 'وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ٱتَّخَذُوهُ وَكَانُوا۟ ظَٰلِمِينَ', '6e06973c14959c4f91af6f7f0babac4717422108e0a83896dda4e818f5e3fde2', '6e06973c14959c4f91af6f7f0babac4717422108e0a83896dda4e818f5e3fde2', NULL, 'واتخذ قوم موسي من بعده من حليهم عجلا جسدا له خوار الم يروا انه لا يكلمهم ولا يهديهم سبيلا اتخذوه وكانوا ظلمين', 9, 17, 67, 1, 2, 168, false, NULL),
    (1103, 'tanzil-uthmani-v1.1', 7, 149, 'وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', '8ad2fd23514230b3523cc4dc5fd34b837f624f6a52e35d4a1c0eee6d51fe547b', 'وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', '8ad2fd23514230b3523cc4dc5fd34b837f624f6a52e35d4a1c0eee6d51fe547b', '8ad2fd23514230b3523cc4dc5fd34b837f624f6a52e35d4a1c0eee6d51fe547b', NULL, 'ولما سقط في ايديهم وراوا انهم قد ضلوا قالوا لئن لم يرحمنا ربنا ويغفر لنا لنكونن من الخسرين', 9, 17, 67, 1, 2, 168, false, NULL),
    (1104, 'tanzil-uthmani-v1.1', 7, 150, 'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '6991b76faf4bc9dd28ed758aa9b7486aa909f6d99f289a604000a36ed7d836e8', 'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '6991b76faf4bc9dd28ed758aa9b7486aa909f6d99f289a604000a36ed7d836e8', '6991b76faf4bc9dd28ed758aa9b7486aa909f6d99f289a604000a36ed7d836e8', NULL, 'ولما رجع موسي الي قومه غضبن اسفا قال بئسما خلفتموني من بعدي اعجلتم امر ربكم والقي الالواح واخذ براس اخيه يجره اليه قال ابن ام ان القوم استضعفوني وكادوا يقتلونني فلا تشمت بي الاعداء ولا تجعلني مع القوم الظلمين', 9, 17, 67, 1, 2, 169, false, NULL),
    (1105, 'tanzil-uthmani-v1.1', 7, 151, 'قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'e013bccb32170c03ee5f9bc6fb1c9242553f0d2cd0f39aa7193680fc5ea47b37', 'قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'e013bccb32170c03ee5f9bc6fb1c9242553f0d2cd0f39aa7193680fc5ea47b37', 'e013bccb32170c03ee5f9bc6fb1c9242553f0d2cd0f39aa7193680fc5ea47b37', NULL, 'قال رب اغفر لي ولاخي وادخلنا في رحمتك وانت ارحم الرحمين', 9, 17, 67, 1, 2, 169, false, NULL),
    (1106, 'tanzil-uthmani-v1.1', 7, 152, 'إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّةٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ', '0f07731fdc3152c27f39ad2353158d1569d14a9e111a169243342e474274e299', 'إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّةٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ', '0f07731fdc3152c27f39ad2353158d1569d14a9e111a169243342e474274e299', '0f07731fdc3152c27f39ad2353158d1569d14a9e111a169243342e474274e299', NULL, 'ان الذين اتخذوا العجل سينالهم غضب من ربهم وذله في الحيوه الدنيا وكذلك نجزي المفترين', 9, 17, 67, 1, 2, 169, false, NULL),
    (1107, 'tanzil-uthmani-v1.1', 7, 153, 'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', '32b8f52703ca67a5ca92e37f8653c1d6f7b486e37c593b4e67e143c47075f463', 'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', '32b8f52703ca67a5ca92e37f8653c1d6f7b486e37c593b4e67e143c47075f463', '32b8f52703ca67a5ca92e37f8653c1d6f7b486e37c593b4e67e143c47075f463', NULL, 'والذين عملوا السيات ثم تابوا من بعدها وءامنوا ان ربك من بعدها لغفور رحيم', 9, 17, 67, 1, 2, 169, false, NULL),
    (1108, 'tanzil-uthmani-v1.1', 7, 154, 'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ وَفِى نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ', 'b185c6c0453114456a2dfea5f8ab64005e0fa37a200e5a23dedf00a4b37c3830', 'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ وَفِى نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ', 'b185c6c0453114456a2dfea5f8ab64005e0fa37a200e5a23dedf00a4b37c3830', 'b185c6c0453114456a2dfea5f8ab64005e0fa37a200e5a23dedf00a4b37c3830', NULL, 'ولما سكت عن موسي الغضب اخذ الالواح وفي نسختها هدي ورحمه للذين هم لربهم يرهبون', 9, 17, 67, 1, 2, 169, false, NULL),
    (1109, 'tanzil-uthmani-v1.1', 7, 155, 'وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًا لِّمِيقَٰتِنَا فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّٰىَ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلْغَٰفِرِينَ', 'c6cc7e189a87406bb6bf5b0f2f784ea245bb4890039efeab502d810a433cb3c1', 'وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًا لِّمِيقَٰتِنَا فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّٰىَ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلْغَٰفِرِينَ', 'c6cc7e189a87406bb6bf5b0f2f784ea245bb4890039efeab502d810a433cb3c1', 'c6cc7e189a87406bb6bf5b0f2f784ea245bb4890039efeab502d810a433cb3c1', NULL, 'واختار موسي قومه سبعين رجلا لميقتنا فلما اخذتهم الرجفه قال رب لو شئت اهلكتهم من قبل وايي اتهلكنا بما فعل السفهاء منا ان هي الا فتنتك تضل بها من تشاء وتهدي من تشاء انت ولينا فاغفر لنا وارحمنا وانت خير الغفرين', 9, 17, 67, 1, 2, 169, false, NULL),
    (1110, 'tanzil-uthmani-v1.1', 7, 156, 'وَٱكْتُبْ لَنَا فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤْمِنُونَ', '389b09aa8f6c15e7db8308af7bba36af6d6ee34c6a8d46b717f56dd0637b5222', 'وَٱكْتُبْ لَنَا فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤْمِنُونَ', '389b09aa8f6c15e7db8308af7bba36af6d6ee34c6a8d46b717f56dd0637b5222', '389b09aa8f6c15e7db8308af7bba36af6d6ee34c6a8d46b717f56dd0637b5222', NULL, 'واكتب لنا في هذه الدنيا حسنه وفي الاخره انا هدنا اليك قال عذابي اصيب به من اشاء ورحمتي وسعت كل شيء فساكتبها للذين يتقون ويؤتون الزكوه والذين هم بايتنا يؤمنون', 9, 17, 68, 1, 2, 170, false, NULL),
    (1111, 'tanzil-uthmani-v1.1', 7, 157, 'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '472f5a7964991894061f8811e864488b8052b7f374329bed2d2b74853a35843b', 'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '472f5a7964991894061f8811e864488b8052b7f374329bed2d2b74853a35843b', '472f5a7964991894061f8811e864488b8052b7f374329bed2d2b74853a35843b', NULL, 'الذين يتبعون الرسول النبي الامي الذي يجدونه مكتوبا عندهم في التوريه والانجيل يامرهم بالمعروف وينهيهم عن المنكر ويحل لهم الطيبت ويحرم عليهم الخبئث ويضع عنهم اصرهم والاغلل التي كانت عليهم فالذين ءامنوا به وعزروه ونصروه واتبعوا النور الذي انزل معه اولئك هم المفلحون', 9, 17, 68, 1, 2, 170, false, NULL),
    (1112, 'tanzil-uthmani-v1.1', 7, 158, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ', '19eb37287a21773e6611330e9329111e0547929c3e4869cc965fda12dd39bd9c', 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ', '19eb37287a21773e6611330e9329111e0547929c3e4869cc965fda12dd39bd9c', '19eb37287a21773e6611330e9329111e0547929c3e4869cc965fda12dd39bd9c', NULL, 'قل يايها الناس اني رسول الله اليكم جميعا الذي له ملك السموت والارض لا اله الا هو يحي ويميت فامنوا بالله ورسوله النبي الامي الذي يؤمن بالله وكلمته واتبعوه لعلكم تهتدون', 9, 17, 68, 1, 2, 170, false, NULL),
    (1113, 'tanzil-uthmani-v1.1', 7, 159, 'وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'f0aa87609e8f4c1aef6976a8bcd35346806113719f21fd1d63d561829c0bf74a', 'وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'f0aa87609e8f4c1aef6976a8bcd35346806113719f21fd1d63d561829c0bf74a', 'f0aa87609e8f4c1aef6976a8bcd35346806113719f21fd1d63d561829c0bf74a', NULL, 'ومن قوم موسي امه يهدون بالحق وبه يعدلون', 9, 17, 68, 1, 2, 170, false, NULL),
    (1114, 'tanzil-uthmani-v1.1', 7, 160, 'وَقَطَّعْنَٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًا وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '5a400694c8acec4a1a916f2cd93390dfe8c8abf341cf31fa2cad9883d7a48245', 'وَقَطَّعْنَٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًا وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '5a400694c8acec4a1a916f2cd93390dfe8c8abf341cf31fa2cad9883d7a48245', '5a400694c8acec4a1a916f2cd93390dfe8c8abf341cf31fa2cad9883d7a48245', NULL, 'وقطعنهم اثنتي عشره اسباطا امما واوحينا الي موسي اذ استسقيه قومه ان اضرب بعصاك الحجر فانبجست منه اثنتا عشره عينا قد علم كل اناس مشربهم وظللنا عليهم الغمم وانزلنا عليهم المن والسلوي كلوا من طيبت ما رزقنكم وما ظلمونا ولكن كانوا انفسهم يظلمون', 9, 17, 68, 1, 2, 171, false, NULL),
    (1115, 'tanzil-uthmani-v1.1', 7, 161, 'وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيٓـَٰٔتِكُمْ سَنَزِيدُ ٱلْمُحْسِنِينَ', 'a17749d72d1188ba98d63bd797914a706471a3ae920f16eff4571cc18c0544ff', 'وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيٓـَٰٔتِكُمْ سَنَزِيدُ ٱلْمُحْسِنِينَ', 'a17749d72d1188ba98d63bd797914a706471a3ae920f16eff4571cc18c0544ff', 'a17749d72d1188ba98d63bd797914a706471a3ae920f16eff4571cc18c0544ff', NULL, 'واذ قيل لهم اسكنوا هذه القريه وكلوا منها حيث شئتم وقولوا حطه وادخلوا الباب سجدا نغفر لكم خطيتكم سنزيد المحسنين', 9, 17, 68, 1, 2, 171, false, NULL),
    (1116, 'tanzil-uthmani-v1.1', 7, 162, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ', 'c7984d11fa5de44bad74d608137df9c9efd91e979dbd05665896fe947cc31bde', 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ', 'c7984d11fa5de44bad74d608137df9c9efd91e979dbd05665896fe947cc31bde', 'c7984d11fa5de44bad74d608137df9c9efd91e979dbd05665896fe947cc31bde', NULL, 'فبدل الذين ظلموا منهم قولا غير الذي قيل لهم فارسلنا عليهم رجزا من السماء بما كانوا يظلمون', 9, 17, 68, 1, 2, 171, false, NULL),
    (1117, 'tanzil-uthmani-v1.1', 7, 163, 'وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ لَا تَأْتِيهِمْ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ', 'eaba00c39a58c4a4cdd73380a6bc928f1cf076df55df5130d5cd4c03414eaeef', 'وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ لَا تَأْتِيهِمْ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ', 'eaba00c39a58c4a4cdd73380a6bc928f1cf076df55df5130d5cd4c03414eaeef', 'eaba00c39a58c4a4cdd73380a6bc928f1cf076df55df5130d5cd4c03414eaeef', NULL, 'وسلهم عن القريه التي كانت حاضره البحر اذ يعدون في السبت اذ تاتيهم حيتانهم يوم سبتهم شرعا ويوم لا يسبتون لا تاتيهم كذلك نبلوهم بما كانوا يفسقون', 9, 17, 68, 1, 2, 171, false, NULL),
    (1118, 'tanzil-uthmani-v1.1', 7, 164, 'وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ', '2ee3a58ae3b3001eee06c48ed7916e79210801fe332259470551d57005fce5bb', 'وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ', '2ee3a58ae3b3001eee06c48ed7916e79210801fe332259470551d57005fce5bb', '2ee3a58ae3b3001eee06c48ed7916e79210801fe332259470551d57005fce5bb', NULL, 'واذ قالت امه منهم لم تعظون قوما الله مهلكهم او معذبهم عذابا شديدا قالوا معذره الي ربكم ولعلهم يتقون', 9, 17, 68, 1, 2, 172, false, NULL),
    (1119, 'tanzil-uthmani-v1.1', 7, 165, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ', '58685f822c533614fa63736011d7857c1b3a24c40a6961ef8ca294a5860d00e5', 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ', '58685f822c533614fa63736011d7857c1b3a24c40a6961ef8ca294a5860d00e5', '58685f822c533614fa63736011d7857c1b3a24c40a6961ef8ca294a5860d00e5', NULL, 'فلما نسوا ما ذكروا به انجينا الذين ينهون عن السوء واخذنا الذين ظلموا بعذاب بيس بما كانوا يفسقون', 9, 17, 68, 1, 2, 172, false, NULL),
    (1120, 'tanzil-uthmani-v1.1', 7, 166, 'فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', '1559e6673fea3fdf48619c51c2688d0adffbf0bd741d74e2272ecfa91c467e46', 'فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', '1559e6673fea3fdf48619c51c2688d0adffbf0bd741d74e2272ecfa91c467e46', '1559e6673fea3fdf48619c51c2688d0adffbf0bd741d74e2272ecfa91c467e46', NULL, 'فلما عتوا عن ما نهوا عنه قلنا لهم كونوا قرده خسين', 9, 17, 68, 1, 2, 172, false, NULL),
    (1121, 'tanzil-uthmani-v1.1', 7, 167, 'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌ', '10ee4d366a4b85b50a71ad3a8c705149e9c8224574c600449a146fbf02098a22', 'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌ', '10ee4d366a4b85b50a71ad3a8c705149e9c8224574c600449a146fbf02098a22', '10ee4d366a4b85b50a71ad3a8c705149e9c8224574c600449a146fbf02098a22', NULL, 'واذ تاذن ربك ليبعثن عليهم الي يوم القيمه من يسومهم سوء العذاب ان ربك لسريع العقاب وانه لغفور رحيم', 9, 17, 68, 1, 2, 172, false, NULL),
    (1122, 'tanzil-uthmani-v1.1', 7, 168, 'وَقَطَّعْنَٰهُمْ فِى ٱلْأَرْضِ أُمَمًا مِّنْهُمُ ٱلصَّٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ وَبَلَوْنَٰهُم بِٱلْحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ', '51292c9011228b11b439022030cff84bddd61ea6283f9c5c4954e14b839fd404', 'وَقَطَّعْنَٰهُمْ فِى ٱلْأَرْضِ أُمَمًا مِّنْهُمُ ٱلصَّٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ وَبَلَوْنَٰهُم بِٱلْحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ', '51292c9011228b11b439022030cff84bddd61ea6283f9c5c4954e14b839fd404', '51292c9011228b11b439022030cff84bddd61ea6283f9c5c4954e14b839fd404', NULL, 'وقطعنهم في الارض امما منهم الصلحون ومنهم دون ذلك وبلونهم بالحسنت والسيات لعلهم يرجعون', 9, 17, 68, 1, 2, 172, false, NULL),
    (1123, 'tanzil-uthmani-v1.1', 7, 169, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ وَرِثُوا۟ ٱلْكِتَٰبَ يَأْخُذُونَ عَرَضَ هَٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُۥ يَأْخُذُوهُ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَٰقُ ٱلْكِتَٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ وَٱلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', 'e4577a0c53049d46d48a9c5d049be9137c4241a2ecdc428fe8e0766897adc05d', 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ وَرِثُوا۟ ٱلْكِتَٰبَ يَأْخُذُونَ عَرَضَ هَٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُۥ يَأْخُذُوهُ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَٰقُ ٱلْكِتَٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ وَٱلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ', 'e4577a0c53049d46d48a9c5d049be9137c4241a2ecdc428fe8e0766897adc05d', 'e4577a0c53049d46d48a9c5d049be9137c4241a2ecdc428fe8e0766897adc05d', NULL, 'فخلف من بعدهم خلف ورثوا الكتب ياخذون عرض هذا الادني ويقولون سيغفر لنا وان ياتهم عرض مثله ياخذوه الم يؤخذ عليهم ميثق الكتب ان لا يقولوا علي الله الا الحق ودرسوا ما فيه والدار الاخره خير للذين يتقون افلا تعقلون', 9, 17, 68, 1, 2, 172, false, NULL),
    (1124, 'tanzil-uthmani-v1.1', 7, 170, 'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ', '2ce3981cfd2c4bec10ada8ab0c07b6cea8ec4a96563d6c310d266da4fcec44ff', 'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ', '2ce3981cfd2c4bec10ada8ab0c07b6cea8ec4a96563d6c310d266da4fcec44ff', '2ce3981cfd2c4bec10ada8ab0c07b6cea8ec4a96563d6c310d266da4fcec44ff', NULL, 'والذين يمسكون بالكتب واقاموا الصلوه انا لا نضيع اجر المصلحين', 9, 17, 68, 1, 2, 172, false, NULL),
    (1125, 'tanzil-uthmani-v1.1', 7, 171, 'وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'b22843f3672d71fd3866cb3cf949e24964385f4e06bc7b9f14145fa276528e4b', 'وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 'b22843f3672d71fd3866cb3cf949e24964385f4e06bc7b9f14145fa276528e4b', 'b22843f3672d71fd3866cb3cf949e24964385f4e06bc7b9f14145fa276528e4b', NULL, 'واذ نتقنا الجبل فوقهم كانه ظله وظنوا انه واقع بهم خذوا ما ءاتينكم بقوه واذكروا ما فيه لعلكم تتقون', 9, 18, 69, 1, 2, 173, false, NULL),
    (1126, 'tanzil-uthmani-v1.1', 7, 172, 'وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا۟ بَلَىٰ شَهِدْنَآ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَٰفِلِينَ', '2d5f3b346a8bc8ab1863a6861a99cc83a889670475c460ff3541f36733feb342', 'وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا۟ بَلَىٰ شَهِدْنَآ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَٰفِلِينَ', '2d5f3b346a8bc8ab1863a6861a99cc83a889670475c460ff3541f36733feb342', '2d5f3b346a8bc8ab1863a6861a99cc83a889670475c460ff3541f36733feb342', NULL, 'واذ اخذ ربك من بني ءادم من ظهورهم ذريتهم واشهدهم علي انفسهم الست بربكم قالوا بلي شهدنا ان تقولوا يوم القيمه انا كنا عن هذا غفلين', 9, 18, 69, 1, 2, 173, false, NULL),
    (1127, 'tanzil-uthmani-v1.1', 7, 173, 'أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّنۢ بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ', '00adbccbf215becb0b14333973cc0b4cf4a4e6508cbe1e1587dbc3658b47ed4b', 'أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّنۢ بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ', '00adbccbf215becb0b14333973cc0b4cf4a4e6508cbe1e1587dbc3658b47ed4b', '00adbccbf215becb0b14333973cc0b4cf4a4e6508cbe1e1587dbc3658b47ed4b', NULL, 'او تقولوا انما اشرك ءاباؤنا من قبل وكنا ذريه من بعدهم افتهلكنا بما فعل المبطلون', 9, 18, 69, 1, 2, 173, false, NULL),
    (1128, 'tanzil-uthmani-v1.1', 7, 174, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ', 'e52fd075c2b9ba474da632d6fe84a586979482df64b4db12791047283d76a459', 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ', 'e52fd075c2b9ba474da632d6fe84a586979482df64b4db12791047283d76a459', 'e52fd075c2b9ba474da632d6fe84a586979482df64b4db12791047283d76a459', NULL, 'وكذلك نفصل الايت ولعلهم يرجعون', 9, 18, 69, 1, 2, 173, false, NULL),
    (1129, 'tanzil-uthmani-v1.1', 7, 175, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ', 'a799ef281b3cfb26149c70099f5d30802c461db4fcff585d2533abb080b3f717', 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ', 'a799ef281b3cfb26149c70099f5d30802c461db4fcff585d2533abb080b3f717', 'a799ef281b3cfb26149c70099f5d30802c461db4fcff585d2533abb080b3f717', NULL, 'واتل عليهم نبا الذي ءاتينه ءايتنا فانسلخ منها فاتبعه الشيطن فكان من الغاوين', 9, 18, 69, 1, 2, 173, false, NULL),
    (1130, 'tanzil-uthmani-v1.1', 7, 176, 'وَلَوْ شِئْنَا لَرَفَعْنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ', '4c44860355625cda70179863f19fd4e39f90205a5e963aecb720f480e0455e3e', 'وَلَوْ شِئْنَا لَرَفَعْنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ', '4c44860355625cda70179863f19fd4e39f90205a5e963aecb720f480e0455e3e', '4c44860355625cda70179863f19fd4e39f90205a5e963aecb720f480e0455e3e', NULL, 'ولو شئنا لرفعنه بها ولكنه اخلد الي الارض واتبع هويه فمثله كمثل الكلب ان تحمل عليه يلهث او تتركه يلهث ذلك مثل القوم الذين كذبوا بايتنا فاقصص القصص لعلهم يتفكرون', 9, 18, 69, 1, 2, 173, false, NULL),
    (1131, 'tanzil-uthmani-v1.1', 7, 177, 'سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ', '728f42ecb83d81160290a6494f0e61ba46f4f7ebf48352dce3e7fe78ebfaad0d', 'سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ', '728f42ecb83d81160290a6494f0e61ba46f4f7ebf48352dce3e7fe78ebfaad0d', '728f42ecb83d81160290a6494f0e61ba46f4f7ebf48352dce3e7fe78ebfaad0d', NULL, 'ساء مثلا القوم الذين كذبوا بايتنا وانفسهم كانوا يظلمون', 9, 18, 69, 1, 2, 173, false, NULL),
    (1132, 'tanzil-uthmani-v1.1', 7, 178, 'مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى وَمَن يُضْلِلْ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'f388c83786aebc29cac8b4a066bcd944965e51f440e2e7230ca145a2d46556d3', 'مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى وَمَن يُضْلِلْ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'f388c83786aebc29cac8b4a066bcd944965e51f440e2e7230ca145a2d46556d3', 'f388c83786aebc29cac8b4a066bcd944965e51f440e2e7230ca145a2d46556d3', NULL, 'من يهد الله فهو المهتدي ومن يضلل فاولئك هم الخسرون', 9, 18, 69, 1, 2, 173, false, NULL),
    (1133, 'tanzil-uthmani-v1.1', 7, 179, 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ لَهُمْ قُلُوبٌ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌ لَّا يَسْمَعُونَ بِهَآ أُو۟لَٰٓئِكَ كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ أُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', '01fa7321434ce28fe64f8eab5a4e88cb31465bbc06102ef5dfe58f0f1598d748', 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ لَهُمْ قُلُوبٌ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌ لَّا يَسْمَعُونَ بِهَآ أُو۟لَٰٓئِكَ كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ أُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', '01fa7321434ce28fe64f8eab5a4e88cb31465bbc06102ef5dfe58f0f1598d748', '01fa7321434ce28fe64f8eab5a4e88cb31465bbc06102ef5dfe58f0f1598d748', NULL, 'ولقد ذرانا لجهنم كثيرا من الجن والانس لهم قلوب لا يفقهون بها ولهم اعين لا يبصرون بها ولهم ءاذان لا يسمعون بها اولئك كالانعم بل هم اضل اولئك هم الغفلون', 9, 18, 69, 1, 2, 174, false, NULL),
    (1134, 'tanzil-uthmani-v1.1', 7, 180, 'وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَٰٓئِهِۦ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ', '907219ad2945ba095e47cf8b167b237040c5118d110208a2776f7ad8d602c025', 'وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَٰٓئِهِۦ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ', '907219ad2945ba095e47cf8b167b237040c5118d110208a2776f7ad8d602c025', '907219ad2945ba095e47cf8b167b237040c5118d110208a2776f7ad8d602c025', NULL, 'ولله الاسماء الحسني فادعوه بها وذروا الذين يلحدون في اسمئه سيجزون ما كانوا يعملون', 9, 18, 69, 1, 2, 174, false, NULL),
    (1135, 'tanzil-uthmani-v1.1', 7, 181, 'وَمِمَّنْ خَلَقْنَآ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'dc1dcd8ba4a54da16568271da840a3fbd5ce329436fecad669d3ef237b6239f9', 'وَمِمَّنْ خَلَقْنَآ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 'dc1dcd8ba4a54da16568271da840a3fbd5ce329436fecad669d3ef237b6239f9', 'dc1dcd8ba4a54da16568271da840a3fbd5ce329436fecad669d3ef237b6239f9', NULL, 'وممن خلقنا امه يهدون بالحق وبه يعدلون', 9, 18, 69, 1, 2, 174, false, NULL),
    (1136, 'tanzil-uthmani-v1.1', 7, 182, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', '8a67f3ef3fb15f46535905027b95c75c1c31670f97487b16a5fae169cecc9128', 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', '8a67f3ef3fb15f46535905027b95c75c1c31670f97487b16a5fae169cecc9128', '8a67f3ef3fb15f46535905027b95c75c1c31670f97487b16a5fae169cecc9128', NULL, 'والذين كذبوا بايتنا سنستدرجهم من حيث لا يعلمون', 9, 18, 69, 1, 2, 174, false, NULL),
    (1137, 'tanzil-uthmani-v1.1', 7, 183, 'وَأُمْلِى لَهُمْ إِنَّ كَيْدِى مَتِينٌ', '885691afc1295b70155d660b8a74e1de0627fb1e52f887f59d071be19246e7e9', 'وَأُمْلِى لَهُمْ إِنَّ كَيْدِى مَتِينٌ', '885691afc1295b70155d660b8a74e1de0627fb1e52f887f59d071be19246e7e9', '885691afc1295b70155d660b8a74e1de0627fb1e52f887f59d071be19246e7e9', NULL, 'واملي لهم ان كيدي متين', 9, 18, 69, 1, 2, 174, false, NULL),
    (1138, 'tanzil-uthmani-v1.1', 7, 184, 'أَوَلَمْ يَتَفَكَّرُوا۟ مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ مُّبِينٌ', '7c56e3e21088b1906268dafd859039c44bb552fb1b3a271af52a24c111ace879', 'أَوَلَمْ يَتَفَكَّرُوا۟ مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ مُّبِينٌ', '7c56e3e21088b1906268dafd859039c44bb552fb1b3a271af52a24c111ace879', '7c56e3e21088b1906268dafd859039c44bb552fb1b3a271af52a24c111ace879', NULL, 'اولم يتفكروا ما بصاحبهم من جنه ان هو الا نذير مبين', 9, 18, 69, 1, 2, 174, false, NULL),
    (1139, 'tanzil-uthmani-v1.1', 7, 185, 'أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', '3bf1ad5fefd7bd6187e244ba698fb25464febda2e223e342263b2d378c5a0bcf', 'أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', '3bf1ad5fefd7bd6187e244ba698fb25464febda2e223e342263b2d378c5a0bcf', '3bf1ad5fefd7bd6187e244ba698fb25464febda2e223e342263b2d378c5a0bcf', NULL, 'اولم ينظروا في ملكوت السموت والارض وما خلق الله من شيء وان عسي ان يكون قد اقترب اجلهم فباي حديث بعده يؤمنون', 9, 18, 69, 1, 2, 174, false, NULL),
    (1140, 'tanzil-uthmani-v1.1', 7, 186, 'مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ وَيَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'cfa4b4a32f2146690fd4088096785de578646584592c086838147117d31dd6a6', 'مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ وَيَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'cfa4b4a32f2146690fd4088096785de578646584592c086838147117d31dd6a6', 'cfa4b4a32f2146690fd4088096785de578646584592c086838147117d31dd6a6', NULL, 'من يضلل الله فلا هادي له ويذرهم في طغينهم يعمهون', 9, 18, 69, 1, 2, 174, false, NULL),
    (1141, 'tanzil-uthmani-v1.1', 7, 187, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ثَقُلَتْ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '9bcadcdfc550bd57b312c8431a889a9ecefcf6b669e3be16e0e60c0134d3397b', 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ثَقُلَتْ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '9bcadcdfc550bd57b312c8431a889a9ecefcf6b669e3be16e0e60c0134d3397b', '9bcadcdfc550bd57b312c8431a889a9ecefcf6b669e3be16e0e60c0134d3397b', NULL, 'يسلونك عن الساعه ايان مرسيها قل انما علمها عند ربي لا يجليها لوقتها الا هو ثقلت في السموت والارض لا تاتيكم الا بغته يسلونك كانك حفي عنها قل انما علمها عند الله ولكن اكثر الناس لا يعلمون', 9, 18, 69, 1, 2, 174, false, NULL),
    (1142, 'tanzil-uthmani-v1.1', 7, 188, 'قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ إِنْ أَنَا۠ إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ', 'e1a2272b3a49966727eb08aedbc4b745c614c81e76399271e713bb461f21f603', 'قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ إِنْ أَنَا۠ إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ', 'e1a2272b3a49966727eb08aedbc4b745c614c81e76399271e713bb461f21f603', 'e1a2272b3a49966727eb08aedbc4b745c614c81e76399271e713bb461f21f603', NULL, 'قل لا املك لنفسي نفعا ولا ضرا الا ما شاء الله ولو كنت اعلم الغيب لاستكثرت من الخير وما مسني السوء ان انا الا نذير وبشير لقوم يؤمنون', 9, 18, 69, 1, 2, 175, false, NULL),
    (1143, 'tanzil-uthmani-v1.1', 7, 189, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِۦ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَٰلِحًا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'dd73813954a6e574b0d278a55e665d58feedb1e52ec5179983e2d70a8c52f291', 'هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِۦ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَٰلِحًا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'dd73813954a6e574b0d278a55e665d58feedb1e52ec5179983e2d70a8c52f291', 'dd73813954a6e574b0d278a55e665d58feedb1e52ec5179983e2d70a8c52f291', NULL, 'هو الذي خلقكم من نفس وحده وجعل منها زوجها ليسكن اليها فلما تغشيها حملت حملا خفيفا فمرت به فلما اثقلت دعوا الله ربهما لئن ءاتيتنا صلحا لنكونن من الشكرين', 9, 18, 70, 1, 2, 175, false, NULL),
    (1144, 'tanzil-uthmani-v1.1', 7, 190, 'فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحًا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا فَتَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', '5549db8590dfde86445c3bf870eeed5c5046a4ce35f79a8c60599500f4acb9ab', 'فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحًا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا فَتَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', '5549db8590dfde86445c3bf870eeed5c5046a4ce35f79a8c60599500f4acb9ab', '5549db8590dfde86445c3bf870eeed5c5046a4ce35f79a8c60599500f4acb9ab', NULL, 'فلما ءاتيهما صلحا جعلا له شركاء فيما ءاتيهما فتعلي الله عما يشركون', 9, 18, 70, 1, 2, 175, false, NULL),
    (1145, 'tanzil-uthmani-v1.1', 7, 191, 'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًٔا وَهُمْ يُخْلَقُونَ', '27bd0a394ba6c8d81f84730432bf34c009849d192654c88bbdcbe4f580f8175e', 'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًٔا وَهُمْ يُخْلَقُونَ', '27bd0a394ba6c8d81f84730432bf34c009849d192654c88bbdcbe4f580f8175e', '27bd0a394ba6c8d81f84730432bf34c009849d192654c88bbdcbe4f580f8175e', NULL, 'ايشركون ما لا يخلق شيا وهم يخلقون', 9, 18, 70, 1, 2, 175, false, NULL),
    (1146, 'tanzil-uthmani-v1.1', 7, 192, 'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَآ أَنفُسَهُمْ يَنصُرُونَ', '925dcb70a3b4ff8f654da248d3c44a50c6c5d5d9a3cb51d94cf764203526da82', 'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَآ أَنفُسَهُمْ يَنصُرُونَ', '925dcb70a3b4ff8f654da248d3c44a50c6c5d5d9a3cb51d94cf764203526da82', '925dcb70a3b4ff8f654da248d3c44a50c6c5d5d9a3cb51d94cf764203526da82', NULL, 'ولا يستطيعون لهم نصرا ولا انفسهم ينصرون', 9, 18, 70, 1, 2, 175, false, NULL),
    (1147, 'tanzil-uthmani-v1.1', 7, 193, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَٰمِتُونَ', '445fbebec166533b8d0c95d8b6f406fa69b32cce7c4b26a55e03c77071855107', 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَٰمِتُونَ', '445fbebec166533b8d0c95d8b6f406fa69b32cce7c4b26a55e03c77071855107', '445fbebec166533b8d0c95d8b6f406fa69b32cce7c4b26a55e03c77071855107', NULL, 'وان تدعوهم الي الهدي لا يتبعوكم سواء عليكم ادعوتموهم ام انتم صمتون', 9, 18, 70, 1, 2, 175, false, NULL),
    (1148, 'tanzil-uthmani-v1.1', 7, 194, 'إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَٰدِقِينَ', '3995f3e388f8cc8d3a76ea2723f9746ac0aa8fd00e10d83d7649683b4af050ab', 'إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَٰدِقِينَ', '3995f3e388f8cc8d3a76ea2723f9746ac0aa8fd00e10d83d7649683b4af050ab', '3995f3e388f8cc8d3a76ea2723f9746ac0aa8fd00e10d83d7649683b4af050ab', NULL, 'ان الذين تدعون من دون الله عباد امثالكم فادعوهم فليستجيبوا لكم ان كنتم صدقين', 9, 18, 70, 1, 2, 175, false, NULL),
    (1149, 'tanzil-uthmani-v1.1', 7, 195, 'أَلَهُمْ أَرْجُلٌ يَمْشُونَ بِهَآ أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَآ أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِهَآ أَمْ لَهُمْ ءَاذَانٌ يَسْمَعُونَ بِهَا قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ', 'd50f9348b15426a4cc09471019a310cf850db658f467b53e74ebdf54601f57d3', 'أَلَهُمْ أَرْجُلٌ يَمْشُونَ بِهَآ أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَآ أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِهَآ أَمْ لَهُمْ ءَاذَانٌ يَسْمَعُونَ بِهَا قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ', 'd50f9348b15426a4cc09471019a310cf850db658f467b53e74ebdf54601f57d3', 'd50f9348b15426a4cc09471019a310cf850db658f467b53e74ebdf54601f57d3', NULL, 'الهم ارجل يمشون بها ام لهم ايد يبطشون بها ام لهم اعين يبصرون بها ام لهم ءاذان يسمعون بها قل ادعوا شركاءكم ثم كيدون فلا تنظرون', 9, 18, 70, 1, 2, 175, false, NULL),
    (1150, 'tanzil-uthmani-v1.1', 7, 196, 'إِنَّ وَلِـِّۧىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَٰبَ وَهُوَ يَتَوَلَّى ٱلصَّٰلِحِينَ', 'e264e2f3302562ac5aa68a706710740d0f664d1502711445bfb46e83e729b424', 'إِنَّ وَلِـِّۧىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَٰبَ وَهُوَ يَتَوَلَّى ٱلصَّٰلِحِينَ', 'e264e2f3302562ac5aa68a706710740d0f664d1502711445bfb46e83e729b424', 'e264e2f3302562ac5aa68a706710740d0f664d1502711445bfb46e83e729b424', NULL, 'ان ولي الله الذي نزل الكتب وهو يتولي الصلحين', 9, 18, 70, 1, 2, 176, false, NULL),
    (1151, 'tanzil-uthmani-v1.1', 7, 197, 'وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ', '73e747aef2be958d01650ca6babfc37c2c889447b71b722dcedf8ec67b4345ee', 'وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ', '73e747aef2be958d01650ca6babfc37c2c889447b71b722dcedf8ec67b4345ee', '73e747aef2be958d01650ca6babfc37c2c889447b71b722dcedf8ec67b4345ee', NULL, 'والذين تدعون من دونه لا يستطيعون نصركم ولا انفسهم ينصرون', 9, 18, 70, 1, 2, 176, false, NULL),
    (1152, 'tanzil-uthmani-v1.1', 7, 198, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ', '7e8e098c568c9588bc333f39428faac4667c0d153a6dc0d883948c61b3e10fe8', 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ', '7e8e098c568c9588bc333f39428faac4667c0d153a6dc0d883948c61b3e10fe8', '7e8e098c568c9588bc333f39428faac4667c0d153a6dc0d883948c61b3e10fe8', NULL, 'وان تدعوهم الي الهدي لا يسمعوا وتريهم ينظرون اليك وهم لا يبصرون', 9, 18, 70, 1, 2, 176, false, NULL),
    (1153, 'tanzil-uthmani-v1.1', 7, 199, 'خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَٰهِلِينَ', '5b38ed3ad1222135d5c5b2caf9cbda7fb1fbc03d7c4f889b150e8aab0eb95784', 'خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَٰهِلِينَ', '5b38ed3ad1222135d5c5b2caf9cbda7fb1fbc03d7c4f889b150e8aab0eb95784', '5b38ed3ad1222135d5c5b2caf9cbda7fb1fbc03d7c4f889b150e8aab0eb95784', NULL, 'خذ العفو وامر بالعرف واعرض عن الجهلين', 9, 18, 70, 1, 2, 176, false, NULL),
    (1154, 'tanzil-uthmani-v1.1', 7, 200, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ سَمِيعٌ عَلِيمٌ', '64ff1150ef40ba1fcead9459dd81bb0696b3f6146b8db182e95c6f7f84d84062', 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ سَمِيعٌ عَلِيمٌ', '64ff1150ef40ba1fcead9459dd81bb0696b3f6146b8db182e95c6f7f84d84062', '64ff1150ef40ba1fcead9459dd81bb0696b3f6146b8db182e95c6f7f84d84062', NULL, 'واما ينزغنك من الشيطن نزغ فاستعذ بالله انه سميع عليم', 9, 18, 70, 1, 2, 176, false, NULL),
    (1155, 'tanzil-uthmani-v1.1', 7, 201, 'إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَٰٓئِفٌ مِّنَ ٱلشَّيْطَٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ', '9c6ccf1f9e09a6046b5ca6f8e3df02ea13c60b310d5f57537863dd9e2493f83e', 'إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَٰٓئِفٌ مِّنَ ٱلشَّيْطَٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ', '9c6ccf1f9e09a6046b5ca6f8e3df02ea13c60b310d5f57537863dd9e2493f83e', '9c6ccf1f9e09a6046b5ca6f8e3df02ea13c60b310d5f57537863dd9e2493f83e', NULL, 'ان الذين اتقوا اذا مسهم طئف من الشيطن تذكروا فاذا هم مبصرون', 9, 18, 70, 1, 2, 176, false, NULL),
    (1156, 'tanzil-uthmani-v1.1', 7, 202, 'وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ', '4672bc9d2361b46a2b1805858a243b0dd3e3705ae96398c6b15341b75710563a', 'وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ', '4672bc9d2361b46a2b1805858a243b0dd3e3705ae96398c6b15341b75710563a', '4672bc9d2361b46a2b1805858a243b0dd3e3705ae96398c6b15341b75710563a', NULL, 'واخونهم يمدونهم في الغي ثم لا يقصرون', 9, 18, 70, 1, 2, 176, false, NULL),
    (1157, 'tanzil-uthmani-v1.1', 7, 203, 'وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى هَٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُؤْمِنُونَ', '6116f5a7c1d8fb946625792787ac45ec65f7dd158a61f9ed9b955a05e3238c8a', 'وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى هَٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُؤْمِنُونَ', '6116f5a7c1d8fb946625792787ac45ec65f7dd158a61f9ed9b955a05e3238c8a', '6116f5a7c1d8fb946625792787ac45ec65f7dd158a61f9ed9b955a05e3238c8a', NULL, 'واذا لم تاتهم بايه قالوا لولا اجتبيتها قل انما اتبع ما يوحي الي من ربي هذا بصائر من ربكم وهدي ورحمه لقوم يؤمنون', 9, 18, 70, 1, 2, 176, false, NULL),
    (1158, 'tanzil-uthmani-v1.1', 7, 204, 'وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', '303db4f032734fec17c45cac16840f7733d2a416e81bb2f3734de123843cd92e', 'وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', '303db4f032734fec17c45cac16840f7733d2a416e81bb2f3734de123843cd92e', '303db4f032734fec17c45cac16840f7733d2a416e81bb2f3734de123843cd92e', NULL, 'واذا قرئ القرءان فاستمعوا له وانصتوا لعلكم ترحمون', 9, 18, 70, 1, 2, 176, false, NULL),
    (1159, 'tanzil-uthmani-v1.1', 7, 205, 'وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ وَلَا تَكُن مِّنَ ٱلْغَٰفِلِينَ', 'b3abdd301fba20da5d98c79735f58a6abee668bb5c6848573c008d88c8006283', 'وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ وَلَا تَكُن مِّنَ ٱلْغَٰفِلِينَ', 'b3abdd301fba20da5d98c79735f58a6abee668bb5c6848573c008d88c8006283', 'b3abdd301fba20da5d98c79735f58a6abee668bb5c6848573c008d88c8006283', NULL, 'واذكر ربك في نفسك تضرعا وخيفه ودون الجهر من القول بالغدو والاصال ولا تكن من الغفلين', 9, 18, 70, 1, 2, 176, false, NULL),
    (1160, 'tanzil-uthmani-v1.1', 7, 206, 'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ', '329ceac30150f23cd0999fadacdb6d367960f5e9a68b7f9807bce63da35a6113', 'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ', '329ceac30150f23cd0999fadacdb6d367960f5e9a68b7f9807bce63da35a6113', '329ceac30150f23cd0999fadacdb6d367960f5e9a68b7f9807bce63da35a6113', NULL, 'ان الذين عند ربك لا يستكبرون عن عبادته ويسبحونه وله يسجدون', 9, 18, 70, 1, 2, 176, true, 'recommended'),
    (1161, 'tanzil-uthmani-v1.1', 8, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ', '2a68acee9e3cafe55553114b00cba41bfbfd6057560bd798b8c803b3363bb9db', 'يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ', 'b70714b95082ddc1a151e892e014656b6ed90bb7c2fbae0613910c8ec7c9fd68', 'b70714b95082ddc1a151e892e014656b6ed90bb7c2fbae0613910c8ec7c9fd68', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يسلونك عن الانفال قل الانفال لله والرسول فاتقوا الله واصلحوا ذات بينكم واطيعوا الله ورسوله ان كنتم مؤمنين', 9, 18, 71, 1, 2, 177, false, NULL),
    (1162, 'tanzil-uthmani-v1.1', 8, 2, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَٰتُهُۥ زَادَتْهُمْ إِيمَٰنًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'd74bb230200a2521ec6e4beb9e5bd3b51e07e641a1703db710c61369fcb5c1ea', 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَٰتُهُۥ زَادَتْهُمْ إِيمَٰنًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'd74bb230200a2521ec6e4beb9e5bd3b51e07e641a1703db710c61369fcb5c1ea', 'd74bb230200a2521ec6e4beb9e5bd3b51e07e641a1703db710c61369fcb5c1ea', NULL, 'انما المؤمنون الذين اذا ذكر الله وجلت قلوبهم واذا تليت عليهم ءايته زادتهم ايمنا وعلي ربهم يتوكلون', 9, 18, 71, 1, 2, 177, false, NULL),
    (1163, 'tanzil-uthmani-v1.1', 8, 3, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', '4af1fb6108a4295f50e4b2ea6d986dbed94e524a6325a1c82dc4874a84bd2390', 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', '4af1fb6108a4295f50e4b2ea6d986dbed94e524a6325a1c82dc4874a84bd2390', '4af1fb6108a4295f50e4b2ea6d986dbed94e524a6325a1c82dc4874a84bd2390', NULL, 'الذين يقيمون الصلوه ومما رزقنهم ينفقون', 9, 18, 71, 1, 2, 177, false, NULL),
    (1164, 'tanzil-uthmani-v1.1', 8, 4, 'أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا لَّهُمْ دَرَجَٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '0bcfe9eccd44546f5a6fd88f4d927aed55b3a9e6d963b018d3b15989bfd1771a', 'أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا لَّهُمْ دَرَجَٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '0bcfe9eccd44546f5a6fd88f4d927aed55b3a9e6d963b018d3b15989bfd1771a', '0bcfe9eccd44546f5a6fd88f4d927aed55b3a9e6d963b018d3b15989bfd1771a', NULL, 'اولئك هم المؤمنون حقا لهم درجت عند ربهم ومغفره ورزق كريم', 9, 18, 71, 1, 2, 177, false, NULL),
    (1165, 'tanzil-uthmani-v1.1', 8, 5, 'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ لَكَٰرِهُونَ', 'dfe44c7c9f4f76d097360513f69ca062827aa9688f0c4f021502bebc3ae6673c', 'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ لَكَٰرِهُونَ', 'dfe44c7c9f4f76d097360513f69ca062827aa9688f0c4f021502bebc3ae6673c', 'dfe44c7c9f4f76d097360513f69ca062827aa9688f0c4f021502bebc3ae6673c', NULL, 'كما اخرجك ربك من بيتك بالحق وان فريقا من المؤمنين لكرهون', 9, 18, 71, 1, 2, 177, false, NULL),
    (1166, 'tanzil-uthmani-v1.1', 8, 6, 'يُجَٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ', 'dcc1ee7502a308c3844d36f99e32c60c3ce2c7b61a06b96bce83de55c8533074', 'يُجَٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ', 'dcc1ee7502a308c3844d36f99e32c60c3ce2c7b61a06b96bce83de55c8533074', 'dcc1ee7502a308c3844d36f99e32c60c3ce2c7b61a06b96bce83de55c8533074', NULL, 'يجدلونك في الحق بعد ما تبين كانما يساقون الي الموت وهم ينظرون', 9, 18, 71, 1, 2, 177, false, NULL),
    (1167, 'tanzil-uthmani-v1.1', 8, 7, 'وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَٰفِرِينَ', '185adaef5007c0d1f95e09bca98dd94389e73bfc76c383f8a07afce4a531c542', 'وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَٰفِرِينَ', '185adaef5007c0d1f95e09bca98dd94389e73bfc76c383f8a07afce4a531c542', '185adaef5007c0d1f95e09bca98dd94389e73bfc76c383f8a07afce4a531c542', NULL, 'واذ يعدكم الله احدي الطائفتين انها لكم وتودون ان غير ذات الشوكه تكون لكم ويريد الله ان يحق الحق بكلمته ويقطع دابر الكفرين', 9, 18, 71, 1, 2, 177, false, NULL),
    (1168, 'tanzil-uthmani-v1.1', 8, 8, 'لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', '77fd5753fc560eee59fc093831cef4533e06abb4bdbca1a8099c9140f5211d25', 'لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', '77fd5753fc560eee59fc093831cef4533e06abb4bdbca1a8099c9140f5211d25', '77fd5753fc560eee59fc093831cef4533e06abb4bdbca1a8099c9140f5211d25', NULL, 'ليحق الحق ويبطل البطل ولو كره المجرمون', 9, 18, 71, 1, 2, 177, false, NULL),
    (1169, 'tanzil-uthmani-v1.1', 8, 9, 'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُرْدِفِينَ', 'dd40fc827bf42607dedddfd11577983c455e210b287386b62123a98c6f5c7966', 'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍ مِّنَ ٱلْمَلَٰٓئِكَةِ مُرْدِفِينَ', 'dd40fc827bf42607dedddfd11577983c455e210b287386b62123a98c6f5c7966', 'dd40fc827bf42607dedddfd11577983c455e210b287386b62123a98c6f5c7966', NULL, 'اذ تستغيثون ربكم فاستجاب لكم اني ممدكم بالف من الملئكه مردفين', 9, 18, 71, 1, 2, 178, false, NULL),
    (1170, 'tanzil-uthmani-v1.1', 8, 10, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '6e1d51720cfa59e97d0f581d448f1c66d95c781d7bf16e0c655dabb252d10cd2', 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '6e1d51720cfa59e97d0f581d448f1c66d95c781d7bf16e0c655dabb252d10cd2', '6e1d51720cfa59e97d0f581d448f1c66d95c781d7bf16e0c655dabb252d10cd2', NULL, 'وما جعله الله الا بشري ولتطمئن به قلوبكم وما النصر الا من عند الله ان الله عزيز حكيم', 9, 18, 71, 1, 2, 178, false, NULL),
    (1171, 'tanzil-uthmani-v1.1', 8, 11, 'إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءً لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ', 'a0ec7671f6378f1ba4a502bb13b2deb2e309b95d73a7d2fea46ac21f660c225a', 'إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءً لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ', 'a0ec7671f6378f1ba4a502bb13b2deb2e309b95d73a7d2fea46ac21f660c225a', 'a0ec7671f6378f1ba4a502bb13b2deb2e309b95d73a7d2fea46ac21f660c225a', NULL, 'اذ يغشيكم النعاس امنه منه وينزل عليكم من السماء ماء ليطهركم به ويذهب عنكم رجز الشيطن وليربط علي قلوبكم ويثبت به الاقدام', 9, 18, 71, 1, 2, 178, false, NULL),
    (1172, 'tanzil-uthmani-v1.1', 8, 12, 'إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍ', '2cd8c3050bacf3d1b7e83384ded2906a976c1b197f82165fd6425c28b0c447ba', 'إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍ', '2cd8c3050bacf3d1b7e83384ded2906a976c1b197f82165fd6425c28b0c447ba', '2cd8c3050bacf3d1b7e83384ded2906a976c1b197f82165fd6425c28b0c447ba', NULL, 'اذ يوحي ربك الي الملئكه اني معكم فثبتوا الذين ءامنوا سالقي في قلوب الذين كفروا الرعب فاضربوا فوق الاعناق واضربوا منهم كل بنان', 9, 18, 71, 1, 2, 178, false, NULL),
    (1173, 'tanzil-uthmani-v1.1', 8, 13, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '209ada60ee08457862e4e7931240e83d9dfdf6ff2249d3d739e4ad1c4468b3d1', 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '209ada60ee08457862e4e7931240e83d9dfdf6ff2249d3d739e4ad1c4468b3d1', '209ada60ee08457862e4e7931240e83d9dfdf6ff2249d3d739e4ad1c4468b3d1', NULL, 'ذلك بانهم شاقوا الله ورسوله ومن يشاقق الله ورسوله فان الله شديد العقاب', 9, 18, 71, 1, 2, 178, false, NULL),
    (1174, 'tanzil-uthmani-v1.1', 8, 14, 'ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَٰفِرِينَ عَذَابَ ٱلنَّارِ', 'e77d442267b29ed42211fae8d6dee78d30ea7026eae29101518509d631e654ea', 'ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَٰفِرِينَ عَذَابَ ٱلنَّارِ', 'e77d442267b29ed42211fae8d6dee78d30ea7026eae29101518509d631e654ea', 'e77d442267b29ed42211fae8d6dee78d30ea7026eae29101518509d631e654ea', NULL, 'ذلكم فذوقوه وان للكفرين عذاب النار', 9, 18, 71, 1, 2, 178, false, NULL),
    (1175, 'tanzil-uthmani-v1.1', 8, 15, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ', '451e8def7a237f3eb94bb057b633943894913333afc3ce2f3ee3257b9dc0cdf0', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ', '451e8def7a237f3eb94bb057b633943894913333afc3ce2f3ee3257b9dc0cdf0', '451e8def7a237f3eb94bb057b633943894913333afc3ce2f3ee3257b9dc0cdf0', NULL, 'يايها الذين ءامنوا اذا لقيتم الذين كفروا زحفا فلا تولوهم الادبار', 9, 18, 71, 1, 2, 178, false, NULL),
    (1176, 'tanzil-uthmani-v1.1', 8, 16, 'وَمَن يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍ فَقَدْ بَآءَ بِغَضَبٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'd3a87e84f65937bccaf9b312c696dcd0ad0ceb683ab0663e814071b1e857ecde', 'وَمَن يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍ فَقَدْ بَآءَ بِغَضَبٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'd3a87e84f65937bccaf9b312c696dcd0ad0ceb683ab0663e814071b1e857ecde', 'd3a87e84f65937bccaf9b312c696dcd0ad0ceb683ab0663e814071b1e857ecde', NULL, 'ومن يولهم يومئذ دبره الا متحرفا لقتال او متحيزا الي فئه فقد باء بغضب من الله وماويه جهنم وبئس المصير', 9, 18, 71, 1, 2, 178, false, NULL),
    (1177, 'tanzil-uthmani-v1.1', 8, 17, 'فَلَمْ تَقْتُلُوهُمْ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمْ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'd1b651a5cb95eee151f503e7a5e0a700ab09ec2c0a189453cf85fc9e1cfb4721', 'فَلَمْ تَقْتُلُوهُمْ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمْ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'd1b651a5cb95eee151f503e7a5e0a700ab09ec2c0a189453cf85fc9e1cfb4721', 'd1b651a5cb95eee151f503e7a5e0a700ab09ec2c0a189453cf85fc9e1cfb4721', NULL, 'فلم تقتلوهم ولكن الله قتلهم وما رميت اذ رميت ولكن الله رمي وليبلي المؤمنين منه بلاء حسنا ان الله سميع عليم', 9, 18, 71, 1, 2, 179, false, NULL),
    (1178, 'tanzil-uthmani-v1.1', 8, 18, 'ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَٰفِرِينَ', 'eb6ed1d020bf5069bc35497ce8ae7f75a9c41ff796b10008aaea1c2e7b825b8d', 'ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَٰفِرِينَ', 'eb6ed1d020bf5069bc35497ce8ae7f75a9c41ff796b10008aaea1c2e7b825b8d', 'eb6ed1d020bf5069bc35497ce8ae7f75a9c41ff796b10008aaea1c2e7b825b8d', NULL, 'ذلكم وان الله موهن كيد الكفرين', 9, 18, 71, 1, 2, 179, false, NULL),
    (1179, 'tanzil-uthmani-v1.1', 8, 19, 'إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ', 'b1747158e89875c04df280bfd972c15133e4be5144a6e204489204b6fcba1dcb', 'إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ', 'b1747158e89875c04df280bfd972c15133e4be5144a6e204489204b6fcba1dcb', 'b1747158e89875c04df280bfd972c15133e4be5144a6e204489204b6fcba1dcb', NULL, 'ان تستفتحوا فقد جاءكم الفتح وان تنتهوا فهو خير لكم وان تعودوا نعد ولن تغني عنكم فئتكم شيا ولو كثرت وان الله مع المؤمنين', 9, 18, 71, 1, 2, 179, false, NULL),
    (1180, 'tanzil-uthmani-v1.1', 8, 20, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ', '4403bb7843c234b183e7cfea0a07c3efbf456393cc42d3a282b15bc874b770cf', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ', '4403bb7843c234b183e7cfea0a07c3efbf456393cc42d3a282b15bc874b770cf', '4403bb7843c234b183e7cfea0a07c3efbf456393cc42d3a282b15bc874b770cf', NULL, 'يايها الذين ءامنوا اطيعوا الله ورسوله ولا تولوا عنه وانتم تسمعون', 9, 18, 71, 1, 2, 179, false, NULL),
    (1181, 'tanzil-uthmani-v1.1', 8, 21, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ', '308e7a7307c62017f84807e931b5cd793edec534a4be0eb0e61af63f147a46bf', 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ', '308e7a7307c62017f84807e931b5cd793edec534a4be0eb0e61af63f147a46bf', '308e7a7307c62017f84807e931b5cd793edec534a4be0eb0e61af63f147a46bf', NULL, 'ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون', 9, 18, 71, 1, 2, 179, false, NULL),
    (1182, 'tanzil-uthmani-v1.1', 8, 22, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ', '7127bfd118fb07cfa955de30f8a081496677de1613b92be42fd339a01300f247', 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ', '7127bfd118fb07cfa955de30f8a081496677de1613b92be42fd339a01300f247', '7127bfd118fb07cfa955de30f8a081496677de1613b92be42fd339a01300f247', NULL, 'ان شر الدواب عند الله الصم البكم الذين لا يعقلون', 9, 18, 72, 1, 2, 179, false, NULL),
    (1183, 'tanzil-uthmani-v1.1', 8, 23, 'وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'e7dcc1305f0a342a4f5797189efa01beb3ed77ae75207a11883f274037ca18e4', 'وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'e7dcc1305f0a342a4f5797189efa01beb3ed77ae75207a11883f274037ca18e4', 'e7dcc1305f0a342a4f5797189efa01beb3ed77ae75207a11883f274037ca18e4', NULL, 'ولو علم الله فيهم خيرا لاسمعهم ولو اسمعهم لتولوا وهم معرضون', 9, 18, 72, 1, 2, 179, false, NULL),
    (1184, 'tanzil-uthmani-v1.1', 8, 24, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ', 'ed7340aba1e2cc895a17aaf4255b996596662b30b046d11273d2b9e685ceec7f', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ', 'ed7340aba1e2cc895a17aaf4255b996596662b30b046d11273d2b9e685ceec7f', 'ed7340aba1e2cc895a17aaf4255b996596662b30b046d11273d2b9e685ceec7f', NULL, 'يايها الذين ءامنوا استجيبوا لله وللرسول اذا دعاكم لما يحييكم واعلموا ان الله يحول بين المرء وقلبه وانه اليه تحشرون', 9, 18, 72, 1, 2, 179, false, NULL),
    (1185, 'tanzil-uthmani-v1.1', 8, 25, 'وَٱتَّقُوا۟ فِتْنَةً لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '342eff94f7d68984d4a336f7268b923d89ff0c987cc7d92cd68ac3e3d994769f', 'وَٱتَّقُوا۟ فِتْنَةً لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '342eff94f7d68984d4a336f7268b923d89ff0c987cc7d92cd68ac3e3d994769f', '342eff94f7d68984d4a336f7268b923d89ff0c987cc7d92cd68ac3e3d994769f', NULL, 'واتقوا فتنه لا تصيبن الذين ظلموا منكم خاصه واعلموا ان الله شديد العقاب', 9, 18, 72, 1, 2, 179, false, NULL),
    (1186, 'tanzil-uthmani-v1.1', 8, 26, 'وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمْ تَشْكُرُونَ', 'bc3fb904a9c4a302669dbdfee45b39ee4670173bf77dbdc2d589f2b5bcc00f2b', 'وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمْ تَشْكُرُونَ', 'bc3fb904a9c4a302669dbdfee45b39ee4670173bf77dbdc2d589f2b5bcc00f2b', 'bc3fb904a9c4a302669dbdfee45b39ee4670173bf77dbdc2d589f2b5bcc00f2b', NULL, 'واذكروا اذ انتم قليل مستضعفون في الارض تخافون ان يتخطفكم الناس فاويكم وايدكم بنصره ورزقكم من الطيبت لعلكم تشكرون', 9, 18, 72, 1, 2, 180, false, NULL),
    (1187, 'tanzil-uthmani-v1.1', 8, 27, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَٰنَٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ', '02913d9c205e6e7c712ddd27ccb91515885ca70592e075c316f9865636f56255', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَٰنَٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ', '02913d9c205e6e7c712ddd27ccb91515885ca70592e075c316f9865636f56255', '02913d9c205e6e7c712ddd27ccb91515885ca70592e075c316f9865636f56255', NULL, 'يايها الذين ءامنوا لا تخونوا الله والرسول وتخونوا امنتكم وانتم تعلمون', 9, 18, 72, 1, 2, 180, false, NULL),
    (1188, 'tanzil-uthmani-v1.1', 8, 28, 'وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'fa6b82ba5715a3d4fbb24a10366d70feafd299cbdbeb78a77475daffa5e4a83f', 'وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'fa6b82ba5715a3d4fbb24a10366d70feafd299cbdbeb78a77475daffa5e4a83f', 'fa6b82ba5715a3d4fbb24a10366d70feafd299cbdbeb78a77475daffa5e4a83f', NULL, 'واعلموا انما امولكم واولدكم فتنه وان الله عنده اجر عظيم', 9, 18, 72, 1, 2, 180, false, NULL),
    (1189, 'tanzil-uthmani-v1.1', 8, 29, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'f4fab7238cd9b2dd351ccb81cb1eb2dd5b94146f2c1ee97b5597e79c9af7c86d', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'f4fab7238cd9b2dd351ccb81cb1eb2dd5b94146f2c1ee97b5597e79c9af7c86d', 'f4fab7238cd9b2dd351ccb81cb1eb2dd5b94146f2c1ee97b5597e79c9af7c86d', NULL, 'يايها الذين ءامنوا ان تتقوا الله يجعل لكم فرقانا ويكفر عنكم سياتكم ويغفر لكم والله ذو الفضل العظيم', 9, 18, 72, 1, 2, 180, false, NULL),
    (1190, 'tanzil-uthmani-v1.1', 8, 30, 'وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 'c469657d02a83e2c4e6a4aced6d6dec1939736652cd7488a1a4e874923ef8ec7', 'وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 'c469657d02a83e2c4e6a4aced6d6dec1939736652cd7488a1a4e874923ef8ec7', 'c469657d02a83e2c4e6a4aced6d6dec1939736652cd7488a1a4e874923ef8ec7', NULL, 'واذ يمكر بك الذين كفروا ليثبتوك او يقتلوك او يخرجوك ويمكرون ويمكر الله والله خير المكرين', 9, 18, 72, 1, 2, 180, false, NULL),
    (1191, 'tanzil-uthmani-v1.1', 8, 31, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'd2c8e39528159823f300099bafb823e629c3259b5c10b9721ae7785c5fdcaa5b', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'd2c8e39528159823f300099bafb823e629c3259b5c10b9721ae7785c5fdcaa5b', 'd2c8e39528159823f300099bafb823e629c3259b5c10b9721ae7785c5fdcaa5b', NULL, 'واذا تتلي عليهم ءايتنا قالوا قد سمعنا لو نشاء لقلنا مثل هذا ان هذا الا اسطير الاولين', 9, 18, 72, 1, 2, 180, false, NULL),
    (1192, 'tanzil-uthmani-v1.1', 8, 32, 'وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍ', 'df7e6b966ff3b7076c0ec444d4a31909529ada662f5bd429dc7565d50f78ebe7', 'وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍ', 'df7e6b966ff3b7076c0ec444d4a31909529ada662f5bd429dc7565d50f78ebe7', 'df7e6b966ff3b7076c0ec444d4a31909529ada662f5bd429dc7565d50f78ebe7', NULL, 'واذ قالوا اللهم ان كان هذا هو الحق من عندك فامطر علينا حجاره من السماء او ائتنا بعذاب اليم', 9, 18, 72, 1, 2, 180, false, NULL),
    (1193, 'tanzil-uthmani-v1.1', 8, 33, 'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ', '197cec6e3e8375044cb6fc919296bd7cf49b86cf1ebd42924371bfdb5cd0131a', 'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ', '197cec6e3e8375044cb6fc919296bd7cf49b86cf1ebd42924371bfdb5cd0131a', '197cec6e3e8375044cb6fc919296bd7cf49b86cf1ebd42924371bfdb5cd0131a', NULL, 'وما كان الله ليعذبهم وانت فيهم وما كان الله معذبهم وهم يستغفرون', 9, 18, 72, 1, 2, 180, false, NULL),
    (1194, 'tanzil-uthmani-v1.1', 8, 34, 'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '109214320e4f54bdf10ebc62d2c11ce4c9a4fcf20df71f108fd4275eb2f2bea6', 'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '109214320e4f54bdf10ebc62d2c11ce4c9a4fcf20df71f108fd4275eb2f2bea6', '109214320e4f54bdf10ebc62d2c11ce4c9a4fcf20df71f108fd4275eb2f2bea6', NULL, 'وما لهم الا يعذبهم الله وهم يصدون عن المسجد الحرام وما كانوا اولياءه ان اولياؤه الا المتقون ولكن اكثرهم لا يعلمون', 9, 18, 72, 1, 2, 181, false, NULL),
    (1195, 'tanzil-uthmani-v1.1', 8, 35, 'وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءً وَتَصْدِيَةً فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '123dd6db2df1e6488b0e8d9a085bb67d62f197b8716822fcf80719a565d1cb81', 'وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءً وَتَصْدِيَةً فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '123dd6db2df1e6488b0e8d9a085bb67d62f197b8716822fcf80719a565d1cb81', '123dd6db2df1e6488b0e8d9a085bb67d62f197b8716822fcf80719a565d1cb81', NULL, 'وما كان صلاتهم عند البيت الا مكاء وتصديه فذوقوا العذاب بما كنتم تكفرون', 9, 18, 72, 1, 2, 181, false, NULL),
    (1196, 'tanzil-uthmani-v1.1', 8, 36, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ', 'ab1ade98c86d860b85e5bf1a94b9f40557eb1c8acfb569b526a2047154a7ed3f', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ', 'ab1ade98c86d860b85e5bf1a94b9f40557eb1c8acfb569b526a2047154a7ed3f', 'ab1ade98c86d860b85e5bf1a94b9f40557eb1c8acfb569b526a2047154a7ed3f', NULL, 'ان الذين كفروا ينفقون امولهم ليصدوا عن سبيل الله فسينفقونها ثم تكون عليهم حسره ثم يغلبون والذين كفروا الي جهنم يحشرون', 9, 18, 72, 1, 2, 181, false, NULL),
    (1197, 'tanzil-uthmani-v1.1', 8, 37, 'لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍ فَيَرْكُمَهُۥ جَمِيعًا فَيَجْعَلَهُۥ فِى جَهَنَّمَ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '0660fc10e80ec837860f9841d80f16cf2e57fbab9566326988d7aefa5c5bf97a', 'لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍ فَيَرْكُمَهُۥ جَمِيعًا فَيَجْعَلَهُۥ فِى جَهَنَّمَ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '0660fc10e80ec837860f9841d80f16cf2e57fbab9566326988d7aefa5c5bf97a', '0660fc10e80ec837860f9841d80f16cf2e57fbab9566326988d7aefa5c5bf97a', NULL, 'ليميز الله الخبيث من الطيب ويجعل الخبيث بعضه علي بعض فيركمه جميعا فيجعله في جهنم اولئك هم الخسرون', 9, 18, 72, 1, 2, 181, false, NULL),
    (1198, 'tanzil-uthmani-v1.1', 8, 38, 'قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ', '5fc7dfbebb3f4cca5b31616f2783070823192c78a4e4ccc124bee59ef7c85de3', 'قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ', '5fc7dfbebb3f4cca5b31616f2783070823192c78a4e4ccc124bee59ef7c85de3', '5fc7dfbebb3f4cca5b31616f2783070823192c78a4e4ccc124bee59ef7c85de3', NULL, 'قل للذين كفروا ان ينتهوا يغفر لهم ما قد سلف وان يعودوا فقد مضت سنت الاولين', 9, 18, 72, 1, 2, 181, false, NULL),
    (1199, 'tanzil-uthmani-v1.1', 8, 39, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ', '991bd814a0c05b4d9ddadf6b7a43e96d743e0067cf6e161e8c18e8e7399ccecd', 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ', '991bd814a0c05b4d9ddadf6b7a43e96d743e0067cf6e161e8c18e8e7399ccecd', '991bd814a0c05b4d9ddadf6b7a43e96d743e0067cf6e161e8c18e8e7399ccecd', NULL, 'وقتلوهم حتي لا تكون فتنه ويكون الدين كله لله فان انتهوا فان الله بما يعملون بصير', 9, 18, 72, 1, 2, 181, false, NULL),
    (1200, 'tanzil-uthmani-v1.1', 8, 40, 'وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 'a5aaad3c91bbbf6290e0e60e7f81336300eb647066c1ac7b8ba90898f5fd4e54', 'وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 'a5aaad3c91bbbf6290e0e60e7f81336300eb647066c1ac7b8ba90898f5fd4e54', 'a5aaad3c91bbbf6290e0e60e7f81336300eb647066c1ac7b8ba90898f5fd4e54', NULL, 'وان تولوا فاعلموا ان الله موليكم نعم المولي ونعم النصير', 9, 18, 72, 1, 2, 181, false, NULL),
    (1201, 'tanzil-uthmani-v1.1', 8, 41, 'وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'b975da93db02022b3953d3efbe2dce3b1ad0de9b5ff5dcb8781ec87b5ce32ec1', 'وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'b975da93db02022b3953d3efbe2dce3b1ad0de9b5ff5dcb8781ec87b5ce32ec1', 'b975da93db02022b3953d3efbe2dce3b1ad0de9b5ff5dcb8781ec87b5ce32ec1', NULL, 'واعلموا انما غنمتم من شيء فان لله خمسه وللرسول ولذي القربي واليتمي والمسكين وابن السبيل ان كنتم ءامنتم بالله وما انزلنا علي عبدنا يوم الفرقان يوم التقي الجمعان والله علي كل شيء قدير', 10, 19, 73, 1, 2, 182, false, NULL),
    (1202, 'tanzil-uthmani-v1.1', 8, 42, 'إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَٰدِ وَلَٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ', 'f6cfb7a0e0778b2993f7478572fbc2cde64ce5179a65438c16450cf9ce642f36', 'إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَٰدِ وَلَٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ', 'f6cfb7a0e0778b2993f7478572fbc2cde64ce5179a65438c16450cf9ce642f36', 'f6cfb7a0e0778b2993f7478572fbc2cde64ce5179a65438c16450cf9ce642f36', NULL, 'اذ انتم بالعدوه الدنيا وهم بالعدوه القصوي والركب اسفل منكم ولو تواعدتم لاختلفتم في الميعد ولكن ليقضي الله امرا كان مفعولا ليهلك من هلك عن بينه ويحيي من حي عن بينه وان الله لسميع عليم', 10, 19, 73, 1, 2, 182, false, NULL),
    (1203, 'tanzil-uthmani-v1.1', 8, 43, 'إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًا وَلَوْ أَرَىٰكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'b40bbc6ba3ca18b2de4dc78caa24ab7cb5d006e5bd444f168148ee581a9fcbb2', 'إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًا وَلَوْ أَرَىٰكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'b40bbc6ba3ca18b2de4dc78caa24ab7cb5d006e5bd444f168148ee581a9fcbb2', 'b40bbc6ba3ca18b2de4dc78caa24ab7cb5d006e5bd444f168148ee581a9fcbb2', NULL, 'اذ يريكهم الله في منامك قليلا ولو اريكهم كثيرا لفشلتم ولتنزعتم في الامر ولكن الله سلم انه عليم بذات الصدور', 10, 19, 73, 1, 2, 182, false, NULL),
    (1204, 'tanzil-uthmani-v1.1', 8, 44, 'وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '3674e631eed0c8cd38e4a75fb8489979ac6aa7fee0ade309f4e6e7f5192e59d1', 'وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '3674e631eed0c8cd38e4a75fb8489979ac6aa7fee0ade309f4e6e7f5192e59d1', '3674e631eed0c8cd38e4a75fb8489979ac6aa7fee0ade309f4e6e7f5192e59d1', NULL, 'واذ يريكموهم اذ التقيتم في اعينكم قليلا ويقللكم في اعينهم ليقضي الله امرا كان مفعولا والي الله ترجع الامور', 10, 19, 73, 1, 2, 182, false, NULL),
    (1205, 'tanzil-uthmani-v1.1', 8, 45, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةً فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', 'bc4ab9877fb059c8792ada137303b16dd1839af4e2739371e8ad656c041192ed', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةً فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', 'bc4ab9877fb059c8792ada137303b16dd1839af4e2739371e8ad656c041192ed', 'bc4ab9877fb059c8792ada137303b16dd1839af4e2739371e8ad656c041192ed', NULL, 'يايها الذين ءامنوا اذا لقيتم فئه فاثبتوا واذكروا الله كثيرا لعلكم تفلحون', 10, 19, 73, 1, 2, 182, false, NULL),
    (1206, 'tanzil-uthmani-v1.1', 8, 46, 'وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ وَٱصْبِرُوٓا۟ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', '800be8bf1f5cddd970ddd8bf538f675b70a419c8f950033d79bb015617e0cd26', 'وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ وَٱصْبِرُوٓا۟ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', '800be8bf1f5cddd970ddd8bf538f675b70a419c8f950033d79bb015617e0cd26', '800be8bf1f5cddd970ddd8bf538f675b70a419c8f950033d79bb015617e0cd26', NULL, 'واطيعوا الله ورسوله ولا تنزعوا فتفشلوا وتذهب ريحكم واصبروا ان الله مع الصبرين', 10, 19, 73, 1, 2, 183, false, NULL),
    (1207, 'tanzil-uthmani-v1.1', 8, 47, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِم بَطَرًا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ', 'fb0e4b982710729dae657ddbba916799b4f1bd0de0d859a4a0fd151b345c14f8', 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِم بَطَرًا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ', 'fb0e4b982710729dae657ddbba916799b4f1bd0de0d859a4a0fd151b345c14f8', 'fb0e4b982710729dae657ddbba916799b4f1bd0de0d859a4a0fd151b345c14f8', NULL, 'ولا تكونوا كالذين خرجوا من ديرهم بطرا ورئاء الناس ويصدون عن سبيل الله والله بما يعملون محيط', 10, 19, 73, 1, 2, 183, false, NULL),
    (1208, 'tanzil-uthmani-v1.1', 8, 48, 'وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌ لَّكُمْ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', '30d1458290625af690254dcd33ea2ee0c8dafcdce0f1df5b4db845e820e866fd', 'وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌ لَّكُمْ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', '30d1458290625af690254dcd33ea2ee0c8dafcdce0f1df5b4db845e820e866fd', '30d1458290625af690254dcd33ea2ee0c8dafcdce0f1df5b4db845e820e866fd', NULL, 'واذ زين لهم الشيطن اعملهم وقال لا غالب لكم اليوم من الناس واني جار لكم فلما تراءت الفئتان نكص علي عقبيه وقال اني بريء منكم اني اري ما لا ترون اني اخاف الله والله شديد العقاب', 10, 19, 73, 1, 2, 183, false, NULL),
    (1209, 'tanzil-uthmani-v1.1', 8, 49, 'إِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمْ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'fde72a61a87db498e8987da2788bcfcd8eb62fac8748e3f0349650822f445320', 'إِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمْ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'fde72a61a87db498e8987da2788bcfcd8eb62fac8748e3f0349650822f445320', 'fde72a61a87db498e8987da2788bcfcd8eb62fac8748e3f0349650822f445320', NULL, 'اذ يقول المنفقون والذين في قلوبهم مرض غر هؤلاء دينهم ومن يتوكل علي الله فان الله عزيز حكيم', 10, 19, 73, 1, 2, 183, false, NULL),
    (1210, 'tanzil-uthmani-v1.1', 8, 50, 'وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', '781a8935a710299f78506b99114efcd2243f6becbf4cd599ec450dfb92190d27', 'وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', '781a8935a710299f78506b99114efcd2243f6becbf4cd599ec450dfb92190d27', '781a8935a710299f78506b99114efcd2243f6becbf4cd599ec450dfb92190d27', NULL, 'ولو تري اذ يتوفي الذين كفروا الملئكه يضربون وجوههم وادبرهم وذوقوا عذاب الحريق', 10, 19, 73, 1, 2, 183, false, NULL),
    (1211, 'tanzil-uthmani-v1.1', 8, 51, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍ لِّلْعَبِيدِ', 'faab4308c2d4089f0fac477d3282442ff611b9ab25609ebb7f9d08f153314771', 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍ لِّلْعَبِيدِ', 'faab4308c2d4089f0fac477d3282442ff611b9ab25609ebb7f9d08f153314771', 'faab4308c2d4089f0fac477d3282442ff611b9ab25609ebb7f9d08f153314771', NULL, 'ذلك بما قدمت ايديكم وان الله ليس بظلم للعبيد', 10, 19, 73, 1, 2, 183, false, NULL),
    (1212, 'tanzil-uthmani-v1.1', 8, 52, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ إِنَّ ٱللَّهَ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', '38a3827dba38357d24a9415c67f70d7071bb6071e10ea6b9322c95fd03d10fb3', 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ إِنَّ ٱللَّهَ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', '38a3827dba38357d24a9415c67f70d7071bb6071e10ea6b9322c95fd03d10fb3', '38a3827dba38357d24a9415c67f70d7071bb6071e10ea6b9322c95fd03d10fb3', NULL, 'كداب ءال فرعون والذين من قبلهم كفروا بايت الله فاخذهم الله بذنوبهم ان الله قوي شديد العقاب', 10, 19, 73, 1, 2, 183, false, NULL),
    (1213, 'tanzil-uthmani-v1.1', 8, 53, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '624fa532209a295c2ceb550177cc109cbf2e00af7ebdd5c957796d3b9ee04536', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '624fa532209a295c2ceb550177cc109cbf2e00af7ebdd5c957796d3b9ee04536', '624fa532209a295c2ceb550177cc109cbf2e00af7ebdd5c957796d3b9ee04536', NULL, 'ذلك بان الله لم يك مغيرا نعمه انعمها علي قوم حتي يغيروا ما بانفسهم وان الله سميع عليم', 10, 19, 73, 1, 2, 184, false, NULL),
    (1214, 'tanzil-uthmani-v1.1', 8, 54, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا۟ بِـَٔايَٰتِ رَبِّهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَكُلٌّ كَانُوا۟ ظَٰلِمِينَ', '2cb5d76e16b86adfd4b7b8d21e5b9e00fe4b32a8a7d09f18d6f340bd84c98cdd', 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا۟ بِـَٔايَٰتِ رَبِّهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَكُلٌّ كَانُوا۟ ظَٰلِمِينَ', '2cb5d76e16b86adfd4b7b8d21e5b9e00fe4b32a8a7d09f18d6f340bd84c98cdd', '2cb5d76e16b86adfd4b7b8d21e5b9e00fe4b32a8a7d09f18d6f340bd84c98cdd', NULL, 'كداب ءال فرعون والذين من قبلهم كذبوا بايت ربهم فاهلكنهم بذنوبهم واغرقنا ءال فرعون وكل كانوا ظلمين', 10, 19, 73, 1, 2, 184, false, NULL),
    (1215, 'tanzil-uthmani-v1.1', 8, 55, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ', '7a77de18cd5f79402f790aa2291d84dacc05b89a372bd8963e7bcacb9d9ac3e9', 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ', '7a77de18cd5f79402f790aa2291d84dacc05b89a372bd8963e7bcacb9d9ac3e9', '7a77de18cd5f79402f790aa2291d84dacc05b89a372bd8963e7bcacb9d9ac3e9', NULL, 'ان شر الدواب عند الله الذين كفروا فهم لا يؤمنون', 10, 19, 73, 1, 2, 184, false, NULL),
    (1216, 'tanzil-uthmani-v1.1', 8, 56, 'ٱلَّذِينَ عَٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ', '665117d966a1f2a71521d2486727056e2bd8c2cdb10e731943b40138204ab613', 'ٱلَّذِينَ عَٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ', '665117d966a1f2a71521d2486727056e2bd8c2cdb10e731943b40138204ab613', '665117d966a1f2a71521d2486727056e2bd8c2cdb10e731943b40138204ab613', NULL, 'الذين عهدت منهم ثم ينقضون عهدهم في كل مره وهم لا يتقون', 10, 19, 73, 1, 2, 184, false, NULL),
    (1217, 'tanzil-uthmani-v1.1', 8, 57, 'فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ', '3e05ba2946fb8ec7700f958519784e77d1e3eb1119f121f972fc71e71ec0b14c', 'فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ', '3e05ba2946fb8ec7700f958519784e77d1e3eb1119f121f972fc71e71ec0b14c', '3e05ba2946fb8ec7700f958519784e77d1e3eb1119f121f972fc71e71ec0b14c', NULL, 'فاما تثقفنهم في الحرب فشرد بهم من خلفهم لعلهم يذكرون', 10, 19, 73, 1, 2, 184, false, NULL),
    (1218, 'tanzil-uthmani-v1.1', 8, 58, 'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةً فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ', '2bf88b2502e65d9f6de6e7df693cedf2ba12aa29971ff65d6c9982421f2ce7ab', 'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةً فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ', '2bf88b2502e65d9f6de6e7df693cedf2ba12aa29971ff65d6c9982421f2ce7ab', '2bf88b2502e65d9f6de6e7df693cedf2ba12aa29971ff65d6c9982421f2ce7ab', NULL, 'واما تخافن من قوم خيانه فانبذ اليهم علي سواء ان الله لا يحب الخائنين', 10, 19, 73, 1, 2, 184, false, NULL),
    (1219, 'tanzil-uthmani-v1.1', 8, 59, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ إِنَّهُمْ لَا يُعْجِزُونَ', 'caee9203e417acfeb3988f75e9509cdf2b4df304c8a23ceceedfbaabec70b155', 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ إِنَّهُمْ لَا يُعْجِزُونَ', 'caee9203e417acfeb3988f75e9509cdf2b4df304c8a23ceceedfbaabec70b155', 'caee9203e417acfeb3988f75e9509cdf2b4df304c8a23ceceedfbaabec70b155', NULL, 'ولا يحسبن الذين كفروا سبقوا انهم لا يعجزون', 10, 19, 73, 1, 2, 184, false, NULL),
    (1220, 'tanzil-uthmani-v1.1', 8, 60, 'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', '91752b7e9b0f8e67ec539432b3f0866904236646c4959eac90411aabfc91bcf6', 'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', '91752b7e9b0f8e67ec539432b3f0866904236646c4959eac90411aabfc91bcf6', '91752b7e9b0f8e67ec539432b3f0866904236646c4959eac90411aabfc91bcf6', NULL, 'واعدوا لهم ما استطعتم من قوه ومن رباط الخيل ترهبون به عدو الله وعدوكم وءاخرين من دونهم لا تعلمونهم الله يعلمهم وما تنفقوا من شيء في سبيل الله يوف اليكم وانتم لا تظلمون', 10, 19, 73, 1, 2, 184, false, NULL),
    (1221, 'tanzil-uthmani-v1.1', 8, 61, 'وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '95b7743988ba0832dd47779861a918db47fd50e3a5dc73207d05b9700fd430c9', 'وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '95b7743988ba0832dd47779861a918db47fd50e3a5dc73207d05b9700fd430c9', '95b7743988ba0832dd47779861a918db47fd50e3a5dc73207d05b9700fd430c9', NULL, 'وان جنحوا للسلم فاجنح لها وتوكل علي الله انه هو السميع العليم', 10, 19, 74, 1, 2, 184, false, NULL),
    (1222, 'tanzil-uthmani-v1.1', 8, 62, 'وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ', '533e71d98af88530098fee405561e5b4b1a23b62867fe2eb33bbeef719cd9ac3', 'وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ', '533e71d98af88530098fee405561e5b4b1a23b62867fe2eb33bbeef719cd9ac3', '533e71d98af88530098fee405561e5b4b1a23b62867fe2eb33bbeef719cd9ac3', NULL, 'وان يريدوا ان يخدعوك فان حسبك الله هو الذي ايدك بنصره وبالمؤمنين', 10, 19, 74, 1, 2, 185, false, NULL),
    (1223, 'tanzil-uthmani-v1.1', 8, 63, 'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ إِنَّهُۥ عَزِيزٌ حَكِيمٌ', 'f14f413faaea425c7572125125c6a89c6e29d6db1dba2b8faacc596020ef1006', 'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ إِنَّهُۥ عَزِيزٌ حَكِيمٌ', 'f14f413faaea425c7572125125c6a89c6e29d6db1dba2b8faacc596020ef1006', 'f14f413faaea425c7572125125c6a89c6e29d6db1dba2b8faacc596020ef1006', NULL, 'والف بين قلوبهم لو انفقت ما في الارض جميعا ما الفت بين قلوبهم ولكن الله الف بينهم انه عزيز حكيم', 10, 19, 74, 1, 2, 185, false, NULL),
    (1224, 'tanzil-uthmani-v1.1', 8, 64, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', 'b27aa5436b4fe07de7202a1322123b28826a91ad223b781de8bf80f1e3d0075a', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', 'b27aa5436b4fe07de7202a1322123b28826a91ad223b781de8bf80f1e3d0075a', 'b27aa5436b4fe07de7202a1322123b28826a91ad223b781de8bf80f1e3d0075a', NULL, 'يايها النبي حسبك الله ومن اتبعك من المؤمنين', 10, 19, 74, 1, 2, 185, false, NULL),
    (1225, 'tanzil-uthmani-v1.1', 8, 65, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ إِن يَكُن مِّنكُمْ عِشْرُونَ صَٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌ يَغْلِبُوٓا۟ أَلْفًا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'd540a1fb670016fc165c5beafd148789b1a3803b319a2c53338bcfda1f5fd9b3', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ إِن يَكُن مِّنكُمْ عِشْرُونَ صَٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌ يَغْلِبُوٓا۟ أَلْفًا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'd540a1fb670016fc165c5beafd148789b1a3803b319a2c53338bcfda1f5fd9b3', 'd540a1fb670016fc165c5beafd148789b1a3803b319a2c53338bcfda1f5fd9b3', NULL, 'يايها النبي حرض المؤمنين علي القتال ان يكن منكم عشرون صبرون يغلبوا مائتين وان يكن منكم مائه يغلبوا الفا من الذين كفروا بانهم قوم لا يفقهون', 10, 19, 74, 1, 2, 185, false, NULL),
    (1226, 'tanzil-uthmani-v1.1', 8, 66, 'ٱلْـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا فَإِن يَكُن مِّنكُم مِّا۟ئَةٌ صَابِرَةٌ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', '954271c3a0bc0951cc72785e4b091871361d4ab27d7211580f77599c84965d6a', 'ٱلْـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا فَإِن يَكُن مِّنكُم مِّا۟ئَةٌ صَابِرَةٌ يَغْلِبُوا۟ مِا۟ئَتَيْنِ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', '954271c3a0bc0951cc72785e4b091871361d4ab27d7211580f77599c84965d6a', '954271c3a0bc0951cc72785e4b091871361d4ab27d7211580f77599c84965d6a', NULL, 'الن خفف الله عنكم وعلم ان فيكم ضعفا فان يكن منكم مائه صابره يغلبوا مائتين وان يكن منكم الف يغلبوا الفين باذن الله والله مع الصبرين', 10, 19, 74, 1, 2, 185, false, NULL),
    (1227, 'tanzil-uthmani-v1.1', 8, 67, 'مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْـَٔاخِرَةَ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'ec6090b0dfe99c50ade01d80da0ac96346091a5542d842dc48a817937904b650', 'مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْـَٔاخِرَةَ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'ec6090b0dfe99c50ade01d80da0ac96346091a5542d842dc48a817937904b650', 'ec6090b0dfe99c50ade01d80da0ac96346091a5542d842dc48a817937904b650', NULL, 'ما كان لنبي ان يكون له اسري حتي يثخن في الارض تريدون عرض الدنيا والله يريد الاخره والله عزيز حكيم', 10, 19, 74, 1, 2, 185, false, NULL),
    (1228, 'tanzil-uthmani-v1.1', 8, 68, 'لَّوْلَا كِتَٰبٌ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌ', '69341369c8e4d3e946bbbb76bb6de07b10d40366c2a51fc2c0db7429745edbed', 'لَّوْلَا كِتَٰبٌ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌ', '69341369c8e4d3e946bbbb76bb6de07b10d40366c2a51fc2c0db7429745edbed', '69341369c8e4d3e946bbbb76bb6de07b10d40366c2a51fc2c0db7429745edbed', NULL, 'لولا كتب من الله سبق لمسكم فيما اخذتم عذاب عظيم', 10, 19, 74, 1, 2, 185, false, NULL),
    (1229, 'tanzil-uthmani-v1.1', 8, 69, 'فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَٰلًا طَيِّبًا وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'ffa675265309f58fede25f2c9366068648283a0210622133ea77f7ddc3036972', 'فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَٰلًا طَيِّبًا وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'ffa675265309f58fede25f2c9366068648283a0210622133ea77f7ddc3036972', 'ffa675265309f58fede25f2c9366068648283a0210622133ea77f7ddc3036972', NULL, 'فكلوا مما غنمتم حللا طيبا واتقوا الله ان الله غفور رحيم', 10, 19, 74, 1, 2, 185, false, NULL),
    (1230, 'tanzil-uthmani-v1.1', 8, 70, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًا يُؤْتِكُمْ خَيْرًا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'cb1cf385b7fc16acfcc68d0d987da6a2fa66d76c5dcf85c1ab556bc984631833', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًا يُؤْتِكُمْ خَيْرًا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'cb1cf385b7fc16acfcc68d0d987da6a2fa66d76c5dcf85c1ab556bc984631833', 'cb1cf385b7fc16acfcc68d0d987da6a2fa66d76c5dcf85c1ab556bc984631833', NULL, 'يايها النبي قل لمن في ايديكم من الاسري ان يعلم الله في قلوبكم خيرا يؤتكم خيرا مما اخذ منكم ويغفر لكم والله غفور رحيم', 10, 19, 74, 1, 2, 186, false, NULL),
    (1231, 'tanzil-uthmani-v1.1', 8, 71, 'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '8cc425738773b23174d8448b7567123ee824abd5a31e85846328833303923d14', 'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '8cc425738773b23174d8448b7567123ee824abd5a31e85846328833303923d14', '8cc425738773b23174d8448b7567123ee824abd5a31e85846328833303923d14', NULL, 'وان يريدوا خيانتك فقد خانوا الله من قبل فامكن منهم والله عليم حكيم', 10, 19, 74, 1, 2, 186, false, NULL),
    (1232, 'tanzil-uthmani-v1.1', 8, 72, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'b0654c47d99a41be0f306324b4be29f84ca7414b0f819f17c782ec883d7a9364', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'b0654c47d99a41be0f306324b4be29f84ca7414b0f819f17c782ec883d7a9364', 'b0654c47d99a41be0f306324b4be29f84ca7414b0f819f17c782ec883d7a9364', NULL, 'ان الذين ءامنوا وهاجروا وجهدوا بامولهم وانفسهم في سبيل الله والذين ءاووا ونصروا اولئك بعضهم اولياء بعض والذين ءامنوا ولم يهاجروا ما لكم من وليتهم من شيء حتي يهاجروا وان استنصروكم في الدين فعليكم النصر الا علي قوم بينكم وبينهم ميثق والله بما تعملون بصير', 10, 19, 74, 1, 2, 186, false, NULL),
    (1233, 'tanzil-uthmani-v1.1', 8, 73, 'وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌ فِى ٱلْأَرْضِ وَفَسَادٌ كَبِيرٌ', 'd7ca088f54d2120e93928731e5d5e64ca321e7107dcd13bf1f544f0586710459', 'وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌ فِى ٱلْأَرْضِ وَفَسَادٌ كَبِيرٌ', 'd7ca088f54d2120e93928731e5d5e64ca321e7107dcd13bf1f544f0586710459', 'd7ca088f54d2120e93928731e5d5e64ca321e7107dcd13bf1f544f0586710459', NULL, 'والذين كفروا بعضهم اولياء بعض الا تفعلوه تكن فتنه في الارض وفساد كبير', 10, 19, 74, 1, 2, 186, false, NULL),
    (1234, 'tanzil-uthmani-v1.1', 8, 74, 'وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'efe513ada704e50183b4dbf02915635e0805f7a471fa284a5ffd10e0fd97fb57', 'وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'efe513ada704e50183b4dbf02915635e0805f7a471fa284a5ffd10e0fd97fb57', 'efe513ada704e50183b4dbf02915635e0805f7a471fa284a5ffd10e0fd97fb57', NULL, 'والذين ءامنوا وهاجروا وجهدوا في سبيل الله والذين ءاووا ونصروا اولئك هم المؤمنون حقا لهم مغفره ورزق كريم', 10, 19, 74, 1, 2, 186, false, NULL),
    (1235, 'tanzil-uthmani-v1.1', 8, 75, 'وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ مَعَكُمْ فَأُو۟لَٰٓئِكَ مِنكُمْ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ ٱللَّهِ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '52b6d7b09431c1ac54e8d9afdf0a7e500eb9bf7907880f569e4ae8ce87a2e0c4', 'وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ مَعَكُمْ فَأُو۟لَٰٓئِكَ مِنكُمْ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ ٱللَّهِ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '52b6d7b09431c1ac54e8d9afdf0a7e500eb9bf7907880f569e4ae8ce87a2e0c4', '52b6d7b09431c1ac54e8d9afdf0a7e500eb9bf7907880f569e4ae8ce87a2e0c4', NULL, 'والذين ءامنوا من بعد وهاجروا وجهدوا معكم فاولئك منكم واولوا الارحام بعضهم اولي ببعض في كتب الله ان الله بكل شيء عليم', 10, 19, 74, 1, 2, 186, false, NULL),
    (1236, 'tanzil-uthmani-v1.1', 9, 1, 'بَرَآءَةٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ', '1923eddf942adc4962e991876b4e19e1268d3f8568a70e397694793d5ab39dc6', 'بَرَآءَةٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ', '1923eddf942adc4962e991876b4e19e1268d3f8568a70e397694793d5ab39dc6', '1923eddf942adc4962e991876b4e19e1268d3f8568a70e397694793d5ab39dc6', NULL, 'براءه من الله ورسوله الي الذين عهدتم من المشركين', 10, 19, 75, 1, 2, 187, false, NULL),
    (1237, 'tanzil-uthmani-v1.1', 9, 2, 'فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَٰفِرِينَ', 'a0c2fd1252ba8542a28cb911cca81e497385755164e3f3edbcb8ff6db7e10a21', 'فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَٰفِرِينَ', 'a0c2fd1252ba8542a28cb911cca81e497385755164e3f3edbcb8ff6db7e10a21', 'a0c2fd1252ba8542a28cb911cca81e497385755164e3f3edbcb8ff6db7e10a21', NULL, 'فسيحوا في الارض اربعه اشهر واعلموا انكم غير معجزي الله وان الله مخزي الكفرين', 10, 19, 75, 1, 2, 187, false, NULL),
    (1238, 'tanzil-uthmani-v1.1', 9, 3, 'وَأَذَٰنٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌ مِّنَ ٱلْمُشْرِكِينَ وَرَسُولُهُۥ فَإِن تُبْتُمْ فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ', 'bcccc014dd477fe4e0a3da8213ec884495fc731a90f93de696dcf65ed9e2cdef', 'وَأَذَٰنٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌ مِّنَ ٱلْمُشْرِكِينَ وَرَسُولُهُۥ فَإِن تُبْتُمْ فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ', 'bcccc014dd477fe4e0a3da8213ec884495fc731a90f93de696dcf65ed9e2cdef', 'bcccc014dd477fe4e0a3da8213ec884495fc731a90f93de696dcf65ed9e2cdef', NULL, 'واذن من الله ورسوله الي الناس يوم الحج الاكبر ان الله بريء من المشركين ورسوله فان تبتم فهو خير لكم وان توليتم فاعلموا انكم غير معجزي الله وبشر الذين كفروا بعذاب اليم', 10, 19, 75, 1, 2, 187, false, NULL),
    (1239, 'tanzil-uthmani-v1.1', 9, 4, 'إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًٔا وَلَمْ يُظَٰهِرُوا۟ عَلَيْكُمْ أَحَدًا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'ac63222a2598c4fd3e4abbd47ef63bdf7018d88267a0bccd784fe662de75f484', 'إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًٔا وَلَمْ يُظَٰهِرُوا۟ عَلَيْكُمْ أَحَدًا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 'ac63222a2598c4fd3e4abbd47ef63bdf7018d88267a0bccd784fe662de75f484', 'ac63222a2598c4fd3e4abbd47ef63bdf7018d88267a0bccd784fe662de75f484', NULL, 'الا الذين عهدتم من المشركين ثم لم ينقصوكم شيا ولم يظهروا عليكم احدا فاتموا اليهم عهدهم الي مدتهم ان الله يحب المتقين', 10, 19, 75, 1, 2, 187, false, NULL),
    (1240, 'tanzil-uthmani-v1.1', 9, 5, 'فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'd3614007c5af5471cbd66a54f76a54687f22b55a993635243fff587737b643d7', 'فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'd3614007c5af5471cbd66a54f76a54687f22b55a993635243fff587737b643d7', 'd3614007c5af5471cbd66a54f76a54687f22b55a993635243fff587737b643d7', NULL, 'فاذا انسلخ الاشهر الحرم فاقتلوا المشركين حيث وجدتموهم وخذوهم واحصروهم واقعدوا لهم كل مرصد فان تابوا واقاموا الصلوه وءاتوا الزكوه فخلوا سبيلهم ان الله غفور رحيم', 10, 19, 75, 1, 2, 187, false, NULL),
    (1241, 'tanzil-uthmani-v1.1', 9, 6, 'وَإِنْ أَحَدٌ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْلَمُونَ', 'c0df8b4cc9f549da757b1fc1862a048fff5568597ac69d346dbdd7c3bcdb5e43', 'وَإِنْ أَحَدٌ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْلَمُونَ', 'c0df8b4cc9f549da757b1fc1862a048fff5568597ac69d346dbdd7c3bcdb5e43', 'c0df8b4cc9f549da757b1fc1862a048fff5568597ac69d346dbdd7c3bcdb5e43', NULL, 'وان احد من المشركين استجارك فاجره حتي يسمع كلم الله ثم ابلغه مامنه ذلك بانهم قوم لا يعلمون', 10, 19, 75, 1, 2, 187, false, NULL),
    (1242, 'tanzil-uthmani-v1.1', 9, 7, 'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ فَمَا ٱسْتَقَٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', '166e3c355ec7704381d402e439fb80835c09539a4e5b85515e044dddaee73180', 'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ فَمَا ٱسْتَقَٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', '166e3c355ec7704381d402e439fb80835c09539a4e5b85515e044dddaee73180', '166e3c355ec7704381d402e439fb80835c09539a4e5b85515e044dddaee73180', NULL, 'كيف يكون للمشركين عهد عند الله وعند رسوله الا الذين عهدتم عند المسجد الحرام فما استقموا لكم فاستقيموا لهم ان الله يحب المتقين', 10, 19, 75, 1, 2, 188, false, NULL),
    (1243, 'tanzil-uthmani-v1.1', 9, 8, 'كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّا وَلَا ذِمَّةً يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَٰسِقُونَ', '027ad3d0e74ded2399326fca32094d9809ba602f28dd03bad50a47207628aaf6', 'كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّا وَلَا ذِمَّةً يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَٰسِقُونَ', '027ad3d0e74ded2399326fca32094d9809ba602f28dd03bad50a47207628aaf6', '027ad3d0e74ded2399326fca32094d9809ba602f28dd03bad50a47207628aaf6', NULL, 'كيف وان يظهروا عليكم لا يرقبوا فيكم الا ولا ذمه يرضونكم بافوههم وتابي قلوبهم واكثرهم فسقون', 10, 19, 75, 1, 2, 188, false, NULL),
    (1244, 'tanzil-uthmani-v1.1', 9, 9, 'ٱشْتَرَوْا۟ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', '67cc5f57ef41248ad9a7745d647109052319b5dc5f592e6977ea8359ec04ad1a', 'ٱشْتَرَوْا۟ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', '67cc5f57ef41248ad9a7745d647109052319b5dc5f592e6977ea8359ec04ad1a', '67cc5f57ef41248ad9a7745d647109052319b5dc5f592e6977ea8359ec04ad1a', NULL, 'اشتروا بايت الله ثمنا قليلا فصدوا عن سبيله انهم ساء ما كانوا يعملون', 10, 19, 75, 1, 2, 188, false, NULL),
    (1245, 'tanzil-uthmani-v1.1', 9, 10, 'لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّا وَلَا ذِمَّةً وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ', '2569f1dc5a0f8d2dba090f7379ffd33e4decb29b28aa3af50c509e3eac3ff0e2', 'لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّا وَلَا ذِمَّةً وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ', '2569f1dc5a0f8d2dba090f7379ffd33e4decb29b28aa3af50c509e3eac3ff0e2', '2569f1dc5a0f8d2dba090f7379ffd33e4decb29b28aa3af50c509e3eac3ff0e2', NULL, 'لا يرقبون في مؤمن الا ولا ذمه واولئك هم المعتدون', 10, 19, 75, 1, 2, 188, false, NULL),
    (1246, 'tanzil-uthmani-v1.1', 9, 11, 'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَنُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', '5daa4b348be2430de06b1b2dd63386a52d34c513ac09c5082869f086a7e54ff5', 'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَنُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', '5daa4b348be2430de06b1b2dd63386a52d34c513ac09c5082869f086a7e54ff5', '5daa4b348be2430de06b1b2dd63386a52d34c513ac09c5082869f086a7e54ff5', NULL, 'فان تابوا واقاموا الصلوه وءاتوا الزكوه فاخونكم في الدين ونفصل الايت لقوم يعلمون', 10, 19, 75, 1, 2, 188, false, NULL),
    (1247, 'tanzil-uthmani-v1.1', 9, 12, 'وَإِن نَّكَثُوٓا۟ أَيْمَٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ إِنَّهُمْ لَآ أَيْمَٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ', '591e93442b2f2acbc6d1ff9f9dc7d7a7f9362402d39e22dce215d61c5197442e', 'وَإِن نَّكَثُوٓا۟ أَيْمَٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ إِنَّهُمْ لَآ أَيْمَٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ', '591e93442b2f2acbc6d1ff9f9dc7d7a7f9362402d39e22dce215d61c5197442e', '591e93442b2f2acbc6d1ff9f9dc7d7a7f9362402d39e22dce215d61c5197442e', NULL, 'وان نكثوا ايمنهم من بعد عهدهم وطعنوا في دينكم فقتلوا ائمه الكفر انهم لا ايمن لهم لعلهم ينتهون', 10, 19, 75, 1, 2, 188, false, NULL),
    (1248, 'tanzil-uthmani-v1.1', 9, 13, 'أَلَا تُقَٰتِلُونَ قَوْمًا نَّكَثُوٓا۟ أَيْمَٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ أَتَخْشَوْنَهُمْ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ', '20c687a8b943468991912e49062b8893298b6518ddb33fc5b6581ad4d1e6d17d', 'أَلَا تُقَٰتِلُونَ قَوْمًا نَّكَثُوٓا۟ أَيْمَٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ أَتَخْشَوْنَهُمْ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ', '20c687a8b943468991912e49062b8893298b6518ddb33fc5b6581ad4d1e6d17d', '20c687a8b943468991912e49062b8893298b6518ddb33fc5b6581ad4d1e6d17d', NULL, 'الا تقتلون قوما نكثوا ايمنهم وهموا باخراج الرسول وهم بدءوكم اول مره اتخشونهم فالله احق ان تخشوه ان كنتم مؤمنين', 10, 19, 75, 1, 2, 188, false, NULL),
    (1249, 'tanzil-uthmani-v1.1', 9, 14, 'قَٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ', '357ff948d71f4c7db4e2dc73e20da775e486ed88465c9ea27f7de2445e1a2197', 'قَٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ', '357ff948d71f4c7db4e2dc73e20da775e486ed88465c9ea27f7de2445e1a2197', '357ff948d71f4c7db4e2dc73e20da775e486ed88465c9ea27f7de2445e1a2197', NULL, 'قتلوهم يعذبهم الله بايديكم ويخزهم وينصركم عليهم ويشف صدور قوم مؤمنين', 10, 19, 75, 1, 2, 189, false, NULL),
    (1250, 'tanzil-uthmani-v1.1', 9, 15, 'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '92fa5acee38683934003072977a8ae8ebf1a116f7aa5d3cef4466f99683a61b1', 'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '92fa5acee38683934003072977a8ae8ebf1a116f7aa5d3cef4466f99683a61b1', '92fa5acee38683934003072977a8ae8ebf1a116f7aa5d3cef4466f99683a61b1', NULL, 'ويذهب غيظ قلوبهم ويتوب الله علي من يشاء والله عليم حكيم', 10, 19, 75, 1, 2, 189, false, NULL),
    (1251, 'tanzil-uthmani-v1.1', 9, 16, 'أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةً وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '20141c1c1ef3269e95679c04c7e5ac0d5e5bd946279321f3ce95af116f668ff7', 'أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةً وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '20141c1c1ef3269e95679c04c7e5ac0d5e5bd946279321f3ce95af116f668ff7', '20141c1c1ef3269e95679c04c7e5ac0d5e5bd946279321f3ce95af116f668ff7', NULL, 'ام حسبتم ان تتركوا ولما يعلم الله الذين جهدوا منكم ولم يتخذوا من دون الله ولا رسوله ولا المؤمنين وليجه والله خبير بما تعملون', 10, 19, 75, 1, 2, 189, false, NULL),
    (1252, 'tanzil-uthmani-v1.1', 9, 17, 'مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا۟ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلْكُفْرِ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ وَفِى ٱلنَّارِ هُمْ خَٰلِدُونَ', '04c066686fb49a1f83ca58140a8809c5f747ba6f36b2556f859ae04fa6d3f619', 'مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا۟ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلْكُفْرِ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ وَفِى ٱلنَّارِ هُمْ خَٰلِدُونَ', '04c066686fb49a1f83ca58140a8809c5f747ba6f36b2556f859ae04fa6d3f619', '04c066686fb49a1f83ca58140a8809c5f747ba6f36b2556f859ae04fa6d3f619', NULL, 'ما كان للمشركين ان يعمروا مسجد الله شهدين علي انفسهم بالكفر اولئك حبطت اعملهم وفي النار هم خلدون', 10, 19, 75, 1, 2, 189, false, NULL),
    (1253, 'tanzil-uthmani-v1.1', 9, 18, 'إِنَّمَا يَعْمُرُ مَسَٰجِدَ ٱللَّهِ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ٱللَّهَ فَعَسَىٰٓ أُو۟لَٰٓئِكَ أَن يَكُونُوا۟ مِنَ ٱلْمُهْتَدِينَ', 'cf836345a429a49b73678573d61c168d08d5a64b6ebca5b06b30a033222986dd', 'إِنَّمَا يَعْمُرُ مَسَٰجِدَ ٱللَّهِ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ٱللَّهَ فَعَسَىٰٓ أُو۟لَٰٓئِكَ أَن يَكُونُوا۟ مِنَ ٱلْمُهْتَدِينَ', 'cf836345a429a49b73678573d61c168d08d5a64b6ebca5b06b30a033222986dd', 'cf836345a429a49b73678573d61c168d08d5a64b6ebca5b06b30a033222986dd', NULL, 'انما يعمر مسجد الله من ءامن بالله واليوم الاخر واقام الصلوه وءاتي الزكوه ولم يخش الا الله فعسي اولئك ان يكونوا من المهتدين', 10, 19, 75, 1, 2, 189, false, NULL),
    (1254, 'tanzil-uthmani-v1.1', 9, 19, 'أَجَعَلْتُمْ سِقَايَةَ ٱلْحَآجِّ وَعِمَارَةَ ٱلْمَسْجِدِ ٱلْحَرَامِ كَمَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَجَٰهَدَ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَوُۥنَ عِندَ ٱللَّهِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '392a0c090f8fc544407d09d852e6ac49a27a01d8a9d154d9a69fb621815ec61d', 'أَجَعَلْتُمْ سِقَايَةَ ٱلْحَآجِّ وَعِمَارَةَ ٱلْمَسْجِدِ ٱلْحَرَامِ كَمَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَجَٰهَدَ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَوُۥنَ عِندَ ٱللَّهِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '392a0c090f8fc544407d09d852e6ac49a27a01d8a9d154d9a69fb621815ec61d', '392a0c090f8fc544407d09d852e6ac49a27a01d8a9d154d9a69fb621815ec61d', NULL, 'اجعلتم سقايه الحاج وعماره المسجد الحرام كمن ءامن بالله واليوم الاخر وجهد في سبيل الله لا يستون عند الله والله لا يهدي القوم الظلمين', 10, 19, 76, 1, 2, 189, false, NULL),
    (1255, 'tanzil-uthmani-v1.1', 9, 20, 'ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 'f2ab46ec541e7b36fca8495cfa559d414a8dc7374eff75fcd82a1c9499914624', 'ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 'f2ab46ec541e7b36fca8495cfa559d414a8dc7374eff75fcd82a1c9499914624', 'f2ab46ec541e7b36fca8495cfa559d414a8dc7374eff75fcd82a1c9499914624', NULL, 'الذين ءامنوا وهاجروا وجهدوا في سبيل الله بامولهم وانفسهم اعظم درجه عند الله واولئك هم الفائزون', 10, 19, 76, 1, 2, 189, false, NULL),
    (1256, 'tanzil-uthmani-v1.1', 9, 21, 'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍ مِّنْهُ وَرِضْوَٰنٍ وَجَنَّٰتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ', '6d6b2c89eff2f59c3f68c761a76edad297135bd20a976c4bc989b83a5c3fb2f4', 'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍ مِّنْهُ وَرِضْوَٰنٍ وَجَنَّٰتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ', '6d6b2c89eff2f59c3f68c761a76edad297135bd20a976c4bc989b83a5c3fb2f4', '6d6b2c89eff2f59c3f68c761a76edad297135bd20a976c4bc989b83a5c3fb2f4', NULL, 'يبشرهم ربهم برحمه منه ورضون وجنت لهم فيها نعيم مقيم', 10, 19, 76, 1, 2, 190, false, NULL),
    (1257, 'tanzil-uthmani-v1.1', 9, 22, 'خَٰلِدِينَ فِيهَآ أَبَدًا إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', '4ebb8312373bd3afc9c4d030bdf6a2d8faecaa908a13223bb7dad34e607db9e4', 'خَٰلِدِينَ فِيهَآ أَبَدًا إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', '4ebb8312373bd3afc9c4d030bdf6a2d8faecaa908a13223bb7dad34e607db9e4', '4ebb8312373bd3afc9c4d030bdf6a2d8faecaa908a13223bb7dad34e607db9e4', NULL, 'خلدين فيها ابدا ان الله عنده اجر عظيم', 10, 19, 76, 1, 2, 190, false, NULL),
    (1258, 'tanzil-uthmani-v1.1', 9, 23, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوٓا۟ ءَابَآءَكُمْ وَإِخْوَٰنَكُمْ أَوْلِيَآءَ إِنِ ٱسْتَحَبُّوا۟ ٱلْكُفْرَ عَلَى ٱلْإِيمَٰنِ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'cf868488441480af021b3b01c8bee3a9fde9f5ce8cc8d32a5bb016875a69c428', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوٓا۟ ءَابَآءَكُمْ وَإِخْوَٰنَكُمْ أَوْلِيَآءَ إِنِ ٱسْتَحَبُّوا۟ ٱلْكُفْرَ عَلَى ٱلْإِيمَٰنِ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'cf868488441480af021b3b01c8bee3a9fde9f5ce8cc8d32a5bb016875a69c428', 'cf868488441480af021b3b01c8bee3a9fde9f5ce8cc8d32a5bb016875a69c428', NULL, 'يايها الذين ءامنوا لا تتخذوا ءاباءكم واخونكم اولياء ان استحبوا الكفر علي الايمن ومن يتولهم منكم فاولئك هم الظلمون', 10, 19, 76, 1, 2, 190, false, NULL),
    (1259, 'tanzil-uthmani-v1.1', 9, 24, 'قُلْ إِن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ٱقْتَرَفْتُمُوهَا وَتِجَٰرَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٍ فِى سَبِيلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', '75abfc4eb04982eb137c316b1ca5c32e0b023b9a4d9a05000e52f28d40c4e2db', 'قُلْ إِن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ٱقْتَرَفْتُمُوهَا وَتِجَٰرَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٍ فِى سَبِيلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', '75abfc4eb04982eb137c316b1ca5c32e0b023b9a4d9a05000e52f28d40c4e2db', '75abfc4eb04982eb137c316b1ca5c32e0b023b9a4d9a05000e52f28d40c4e2db', NULL, 'قل ان كان ءاباؤكم وابناؤكم واخونكم وازوجكم وعشيرتكم وامول اقترفتموها وتجره تخشون كسادها ومسكن ترضونها احب اليكم من الله ورسوله وجهاد في سبيله فتربصوا حتي ياتي الله بامره والله لا يهدي القوم الفسقين', 10, 19, 76, 1, 2, 190, false, NULL),
    (1260, 'tanzil-uthmani-v1.1', 9, 25, 'لَقَدْ نَصَرَكُمُ ٱللَّهُ فِى مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـًٔا وَضَاقَتْ عَلَيْكُمُ ٱلْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ', '784bb78fd40647870a8b4d86850ec6d16a7b51c1c9f0fa49fad9a81db077d1c2', 'لَقَدْ نَصَرَكُمُ ٱللَّهُ فِى مَوَاطِنَ كَثِيرَةٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـًٔا وَضَاقَتْ عَلَيْكُمُ ٱلْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ', '784bb78fd40647870a8b4d86850ec6d16a7b51c1c9f0fa49fad9a81db077d1c2', '784bb78fd40647870a8b4d86850ec6d16a7b51c1c9f0fa49fad9a81db077d1c2', NULL, 'لقد نصركم الله في مواطن كثيره ويوم حنين اذ اعجبتكم كثرتكم فلم تغن عنكم شيا وضاقت عليكم الارض بما رحبت ثم وليتم مدبرين', 10, 19, 76, 1, 2, 190, false, NULL),
    (1261, 'tanzil-uthmani-v1.1', 9, 26, 'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ وَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'b26bf60f5a91ccb582c5b57884999ba34da0788631be7eb0221736c921ae5c78', 'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ وَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 'b26bf60f5a91ccb582c5b57884999ba34da0788631be7eb0221736c921ae5c78', 'b26bf60f5a91ccb582c5b57884999ba34da0788631be7eb0221736c921ae5c78', NULL, 'ثم انزل الله سكينته علي رسوله وعلي المؤمنين وانزل جنودا لم تروها وعذب الذين كفروا وذلك جزاء الكفرين', 10, 19, 76, 1, 2, 190, false, NULL),
    (1262, 'tanzil-uthmani-v1.1', 9, 27, 'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'e88608e1a7a08560c75ec3ab777d18c5c169bed2425dc2af3980351bd541be88', 'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 'e88608e1a7a08560c75ec3ab777d18c5c169bed2425dc2af3980351bd541be88', 'e88608e1a7a08560c75ec3ab777d18c5c169bed2425dc2af3980351bd541be88', NULL, 'ثم يتوب الله من بعد ذلك علي من يشاء والله غفور رحيم', 10, 19, 76, 1, 2, 191, false, NULL),
    (1263, 'tanzil-uthmani-v1.1', 9, 28, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا۟ ٱلْمَسْجِدَ ٱلْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ ٱللَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٌ', 'e52fbd16699b67a99f646ccebeae43eebb597059e4b10c0f5afb43519e83ce84', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا۟ ٱلْمَسْجِدَ ٱلْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ ٱللَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٌ', 'e52fbd16699b67a99f646ccebeae43eebb597059e4b10c0f5afb43519e83ce84', 'e52fbd16699b67a99f646ccebeae43eebb597059e4b10c0f5afb43519e83ce84', NULL, 'يايها الذين ءامنوا انما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا وان خفتم عيله فسوف يغنيكم الله من فضله ان شاء ان الله عليم حكيم', 10, 19, 76, 1, 2, 191, false, NULL),
    (1264, 'tanzil-uthmani-v1.1', 9, 29, 'قَٰتِلُوا۟ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلْحَقِّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حَتَّىٰ يُعْطُوا۟ ٱلْجِزْيَةَ عَن يَدٍ وَهُمْ صَٰغِرُونَ', 'f823b2d8f499a0e581397f15dc301fd6f6203f0fc5864190ee3b3b3586497820', 'قَٰتِلُوا۟ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْـَٔاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلْحَقِّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حَتَّىٰ يُعْطُوا۟ ٱلْجِزْيَةَ عَن يَدٍ وَهُمْ صَٰغِرُونَ', 'f823b2d8f499a0e581397f15dc301fd6f6203f0fc5864190ee3b3b3586497820', 'f823b2d8f499a0e581397f15dc301fd6f6203f0fc5864190ee3b3b3586497820', NULL, 'قتلوا الذين لا يؤمنون بالله ولا باليوم الاخر ولا يحرمون ما حرم الله ورسوله ولا يدينون دين الحق من الذين اوتوا الكتب حتي يعطوا الجزيه عن يد وهم صغرون', 10, 19, 76, 1, 2, 191, false, NULL),
    (1265, 'tanzil-uthmani-v1.1', 9, 30, 'وَقَالَتِ ٱلْيَهُودُ عُزَيْرٌ ٱبْنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلْمَسِيحُ ٱبْنُ ٱللَّهِ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ يُضَٰهِـُٔونَ قَوْلَ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ قَٰتَلَهُمُ ٱللَّهُ أَنَّىٰ يُؤْفَكُونَ', '84139d690c1c7c0d8d97837b752e086fbb1a3e484db2cad52804a9a4eafd10af', 'وَقَالَتِ ٱلْيَهُودُ عُزَيْرٌ ٱبْنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلْمَسِيحُ ٱبْنُ ٱللَّهِ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ يُضَٰهِـُٔونَ قَوْلَ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ قَٰتَلَهُمُ ٱللَّهُ أَنَّىٰ يُؤْفَكُونَ', '84139d690c1c7c0d8d97837b752e086fbb1a3e484db2cad52804a9a4eafd10af', '84139d690c1c7c0d8d97837b752e086fbb1a3e484db2cad52804a9a4eafd10af', NULL, 'وقالت اليهود عزير ابن الله وقالت النصري المسيح ابن الله ذلك قولهم بافوههم يضهون قول الذين كفروا من قبل قتلهم الله اني يؤفكون', 10, 19, 76, 1, 2, 191, false, NULL),
    (1266, 'tanzil-uthmani-v1.1', 9, 31, 'ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَٰهًا وَٰحِدًا لَّآ إِلَٰهَ إِلَّا هُوَ سُبْحَٰنَهُۥ عَمَّا يُشْرِكُونَ', 'e0a404bff34511c99701d9a16ce0f7a87d0c19540842bed64a4bf800d22bd480', 'ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَٰهًا وَٰحِدًا لَّآ إِلَٰهَ إِلَّا هُوَ سُبْحَٰنَهُۥ عَمَّا يُشْرِكُونَ', 'e0a404bff34511c99701d9a16ce0f7a87d0c19540842bed64a4bf800d22bd480', 'e0a404bff34511c99701d9a16ce0f7a87d0c19540842bed64a4bf800d22bd480', NULL, 'اتخذوا احبارهم ورهبنهم اربابا من دون الله والمسيح ابن مريم وما امروا الا ليعبدوا الها وحدا لا اله الا هو سبحنه عما يشركون', 10, 19, 76, 1, 2, 191, false, NULL),
    (1267, 'tanzil-uthmani-v1.1', 9, 32, 'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'd040aa08515ac71a9248ca05a8e62e7f69c0d799c6ba165872d06be6a445f010', 'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'd040aa08515ac71a9248ca05a8e62e7f69c0d799c6ba165872d06be6a445f010', 'd040aa08515ac71a9248ca05a8e62e7f69c0d799c6ba165872d06be6a445f010', NULL, 'يريدون ان يطفوا نور الله بافوههم ويابي الله الا ان يتم نوره ولو كره الكفرون', 10, 19, 76, 1, 2, 192, false, NULL),
    (1268, 'tanzil-uthmani-v1.1', 9, 33, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', '72056e1cc5d673ddd6155a648c4fc6f16db7f0b860112f62fbe189b5e490d593', 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', '72056e1cc5d673ddd6155a648c4fc6f16db7f0b860112f62fbe189b5e490d593', '72056e1cc5d673ddd6155a648c4fc6f16db7f0b860112f62fbe189b5e490d593', NULL, 'هو الذي ارسل رسوله بالهدي ودين الحق ليظهره علي الدين كله ولو كره المشركون', 10, 19, 76, 1, 2, 192, false, NULL),
    (1269, 'tanzil-uthmani-v1.1', 9, 34, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', '557fa615e344c014533374266479132ce4df84e06043d8d9f01318dbf18c1f13', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', '557fa615e344c014533374266479132ce4df84e06043d8d9f01318dbf18c1f13', '557fa615e344c014533374266479132ce4df84e06043d8d9f01318dbf18c1f13', NULL, 'يايها الذين ءامنوا ان كثيرا من الاحبار والرهبان لياكلون امول الناس بالبطل ويصدون عن سبيل الله والذين يكنزون الذهب والفضه ولا ينفقونها في سبيل الله فبشرهم بعذاب اليم', 10, 20, 77, 1, 2, 192, false, NULL),
    (1270, 'tanzil-uthmani-v1.1', 9, 35, 'يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا۟ مَا كُنتُمْ تَكْنِزُونَ', '1a4297e05feecfbddff2a5f7484b9524c51a9b78795fac5ed1ff3ee145915903', 'يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا۟ مَا كُنتُمْ تَكْنِزُونَ', '1a4297e05feecfbddff2a5f7484b9524c51a9b78795fac5ed1ff3ee145915903', '1a4297e05feecfbddff2a5f7484b9524c51a9b78795fac5ed1ff3ee145915903', NULL, 'يوم يحمي عليها في نار جهنم فتكوي بها جباههم وجنوبهم وظهورهم هذا ما كنزتم لانفسكم فذوقوا ما كنتم تكنزون', 10, 20, 77, 1, 2, 192, false, NULL),
    (1271, 'tanzil-uthmani-v1.1', 9, 36, 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًا فِى كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ وَقَٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةً كَمَا يُقَٰتِلُونَكُمْ كَآفَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', '20e267cfe9aee76d74c08f439d293993d58458f0c512f6a8d33f74292fed3cf4', 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًا فِى كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ وَقَٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةً كَمَا يُقَٰتِلُونَكُمْ كَآفَّةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', '20e267cfe9aee76d74c08f439d293993d58458f0c512f6a8d33f74292fed3cf4', '20e267cfe9aee76d74c08f439d293993d58458f0c512f6a8d33f74292fed3cf4', NULL, 'ان عده الشهور عند الله اثنا عشر شهرا في كتب الله يوم خلق السموت والارض منها اربعه حرم ذلك الدين القيم فلا تظلموا فيهن انفسكم وقتلوا المشركين كافه كما يقتلونكم كافه واعلموا ان الله مع المتقين', 10, 20, 77, 1, 2, 192, false, NULL),
    (1272, 'tanzil-uthmani-v1.1', 9, 37, 'إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌ فِى ٱلْكُفْرِ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُوا۟ يُحِلُّونَهُۥ عَامًا وَيُحَرِّمُونَهُۥ عَامًا لِّيُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُ زُيِّنَ لَهُمْ سُوٓءُ أَعْمَٰلِهِمْ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', '43afa22bbf33fc26bc471e9fb67a180eaf6ab5b590b3fc546ff2455b14620cab', 'إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌ فِى ٱلْكُفْرِ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُوا۟ يُحِلُّونَهُۥ عَامًا وَيُحَرِّمُونَهُۥ عَامًا لِّيُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُ زُيِّنَ لَهُمْ سُوٓءُ أَعْمَٰلِهِمْ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', '43afa22bbf33fc26bc471e9fb67a180eaf6ab5b590b3fc546ff2455b14620cab', '43afa22bbf33fc26bc471e9fb67a180eaf6ab5b590b3fc546ff2455b14620cab', NULL, 'انما النسيء زياده في الكفر يضل به الذين كفروا يحلونه عاما ويحرمونه عاما ليواطوا عده ما حرم الله فيحلوا ما حرم الله زين لهم سوء اعملهم والله لا يهدي القوم الكفرين', 10, 20, 77, 1, 2, 193, false, NULL),
    (1273, 'tanzil-uthmani-v1.1', 9, 38, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَا لَكُمْ إِذَا قِيلَ لَكُمُ ٱنفِرُوا۟ فِى سَبِيلِ ٱللَّهِ ٱثَّاقَلْتُمْ إِلَى ٱلْأَرْضِ أَرَضِيتُم بِٱلْحَيَوٰةِ ٱلدُّنْيَا مِنَ ٱلْـَٔاخِرَةِ فَمَا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا قَلِيلٌ', '725a0f0f3f03d177440f6fbfe858e98832ec8ac632d5daac36ef2c43dca5ab46', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَا لَكُمْ إِذَا قِيلَ لَكُمُ ٱنفِرُوا۟ فِى سَبِيلِ ٱللَّهِ ٱثَّاقَلْتُمْ إِلَى ٱلْأَرْضِ أَرَضِيتُم بِٱلْحَيَوٰةِ ٱلدُّنْيَا مِنَ ٱلْـَٔاخِرَةِ فَمَا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا قَلِيلٌ', '725a0f0f3f03d177440f6fbfe858e98832ec8ac632d5daac36ef2c43dca5ab46', '725a0f0f3f03d177440f6fbfe858e98832ec8ac632d5daac36ef2c43dca5ab46', NULL, 'يايها الذين ءامنوا ما لكم اذا قيل لكم انفروا في سبيل الله اثاقلتم الي الارض ارضيتم بالحيوه الدنيا من الاخره فما متع الحيوه الدنيا في الاخره الا قليل', 10, 20, 77, 1, 2, 193, false, NULL),
    (1274, 'tanzil-uthmani-v1.1', 9, 39, 'إِلَّا تَنفِرُوا۟ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـًٔا وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '618212e747ce59af8daa72ce5ec30cf3344881fee46a5c82cfaa3adf6fe815e2', 'إِلَّا تَنفِرُوا۟ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـًٔا وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '618212e747ce59af8daa72ce5ec30cf3344881fee46a5c82cfaa3adf6fe815e2', '618212e747ce59af8daa72ce5ec30cf3344881fee46a5c82cfaa3adf6fe815e2', NULL, 'الا تنفروا يعذبكم عذابا اليما ويستبدل قوما غيركم ولا تضروه شيا والله علي كل شيء قدير', 10, 20, 77, 1, 2, 193, false, NULL),
    (1275, 'tanzil-uthmani-v1.1', 9, 40, 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا وَٱللَّهُ عَزِيزٌ حَكِيمٌ', '05530a82bf92e0fdff657b40dec5134d34ca8f0fb306c11bf2081e0a59357880', 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا وَٱللَّهُ عَزِيزٌ حَكِيمٌ', '05530a82bf92e0fdff657b40dec5134d34ca8f0fb306c11bf2081e0a59357880', '05530a82bf92e0fdff657b40dec5134d34ca8f0fb306c11bf2081e0a59357880', NULL, 'الا تنصروه فقد نصره الله اذ اخرجه الذين كفروا ثاني اثنين اذ هما في الغار اذ يقول لصحبه لا تحزن ان الله معنا فانزل الله سكينته عليه وايده بجنود لم تروها وجعل كلمه الذين كفروا السفلي وكلمه الله هي العليا والله عزيز حكيم', 10, 20, 77, 1, 2, 193, false, NULL),
    (1276, 'tanzil-uthmani-v1.1', 9, 41, 'ٱنفِرُوا۟ خِفَافًا وَثِقَالًا وَجَٰهِدُوا۟ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِى سَبِيلِ ٱللَّهِ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'a3e451114ee132045f24b734aae72ce0213732557fac74dd6c56bd359fbfb015', 'ٱنفِرُوا۟ خِفَافًا وَثِقَالًا وَجَٰهِدُوا۟ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِى سَبِيلِ ٱللَّهِ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'a3e451114ee132045f24b734aae72ce0213732557fac74dd6c56bd359fbfb015', 'a3e451114ee132045f24b734aae72ce0213732557fac74dd6c56bd359fbfb015', NULL, 'انفروا خفافا وثقالا وجهدوا بامولكم وانفسكم في سبيل الله ذلكم خير لكم ان كنتم تعلمون', 10, 20, 77, 1, 2, 194, false, NULL),
    (1277, 'tanzil-uthmani-v1.1', 9, 42, 'لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتْ عَلَيْهِمُ ٱلشُّقَّةُ وَسَيَحْلِفُونَ بِٱللَّهِ لَوِ ٱسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَٱللَّهُ يَعْلَمُ إِنَّهُمْ لَكَٰذِبُونَ', 'c91302a7de00c4e6ff8c8b6175c8fdfd8c156a1b26ec52de2fd0e0ab163e3c83', 'لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتْ عَلَيْهِمُ ٱلشُّقَّةُ وَسَيَحْلِفُونَ بِٱللَّهِ لَوِ ٱسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَٱللَّهُ يَعْلَمُ إِنَّهُمْ لَكَٰذِبُونَ', 'c91302a7de00c4e6ff8c8b6175c8fdfd8c156a1b26ec52de2fd0e0ab163e3c83', 'c91302a7de00c4e6ff8c8b6175c8fdfd8c156a1b26ec52de2fd0e0ab163e3c83', NULL, 'لو كان عرضا قريبا وسفرا قاصدا لاتبعوك ولكن بعدت عليهم الشقه وسيحلفون بالله لو استطعنا لخرجنا معكم يهلكون انفسهم والله يعلم انهم لكذبون', 10, 20, 77, 1, 2, 194, false, NULL),
    (1278, 'tanzil-uthmani-v1.1', 9, 43, 'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُوا۟ وَتَعْلَمَ ٱلْكَٰذِبِينَ', 'fdf1eb8fde104ae0054231d049dc0abe0ff74a3a83e62f6aa384489de0cbd498', 'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُوا۟ وَتَعْلَمَ ٱلْكَٰذِبِينَ', 'fdf1eb8fde104ae0054231d049dc0abe0ff74a3a83e62f6aa384489de0cbd498', 'fdf1eb8fde104ae0054231d049dc0abe0ff74a3a83e62f6aa384489de0cbd498', NULL, 'عفا الله عنك لم اذنت لهم حتي يتبين لك الذين صدقوا وتعلم الكذبين', 10, 20, 77, 1, 2, 194, false, NULL),
    (1279, 'tanzil-uthmani-v1.1', 9, 44, 'لَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', '4d7cef93490be940af4993255b9179a472b0a481b23483ba461dc117a6ef476f', 'لَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', '4d7cef93490be940af4993255b9179a472b0a481b23483ba461dc117a6ef476f', '4d7cef93490be940af4993255b9179a472b0a481b23483ba461dc117a6ef476f', NULL, 'لا يستذنك الذين يؤمنون بالله واليوم الاخر ان يجهدوا بامولهم وانفسهم والله عليم بالمتقين', 10, 20, 77, 1, 2, 194, false, NULL),
    (1280, 'tanzil-uthmani-v1.1', 9, 45, 'إِنَّمَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱرْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّدُونَ', '20174e9b3a3bf3e474c053440554b30d5a3ce960ff836464f848c0da4861367b', 'إِنَّمَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱرْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّدُونَ', '20174e9b3a3bf3e474c053440554b30d5a3ce960ff836464f848c0da4861367b', '20174e9b3a3bf3e474c053440554b30d5a3ce960ff836464f848c0da4861367b', NULL, 'انما يستذنك الذين لا يؤمنون بالله واليوم الاخر وارتابت قلوبهم فهم في ريبهم يترددون', 10, 20, 77, 1, 2, 194, false, NULL),
    (1281, 'tanzil-uthmani-v1.1', 9, 46, 'وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةً وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَٰعِدِينَ', 'd9bc5678dcfd630dc67dfc4ee1b16a7bb044189bbd76d87dfe182c7415cc3e93', 'وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةً وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَٰعِدِينَ', 'd9bc5678dcfd630dc67dfc4ee1b16a7bb044189bbd76d87dfe182c7415cc3e93', 'd9bc5678dcfd630dc67dfc4ee1b16a7bb044189bbd76d87dfe182c7415cc3e93', NULL, 'ولو ارادوا الخروج لاعدوا له عده ولكن كره الله انبعاثهم فثبطهم وقيل اقعدوا مع القعدين', 10, 20, 78, 1, 2, 194, false, NULL),
    (1282, 'tanzil-uthmani-v1.1', 9, 47, 'لَوْ خَرَجُوا۟ فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا۟ خِلَٰلَكُمْ يَبْغُونَكُمُ ٱلْفِتْنَةَ وَفِيكُمْ سَمَّٰعُونَ لَهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', '7854739813cb325bcf8047b73da11dbdc956fe41c2135d76402bb0741c0e08e1', 'لَوْ خَرَجُوا۟ فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا۟ خِلَٰلَكُمْ يَبْغُونَكُمُ ٱلْفِتْنَةَ وَفِيكُمْ سَمَّٰعُونَ لَهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', '7854739813cb325bcf8047b73da11dbdc956fe41c2135d76402bb0741c0e08e1', '7854739813cb325bcf8047b73da11dbdc956fe41c2135d76402bb0741c0e08e1', NULL, 'لو خرجوا فيكم ما زادوكم الا خبالا ولاوضعوا خللكم يبغونكم الفتنه وفيكم سمعون لهم والله عليم بالظلمين', 10, 20, 78, 1, 2, 194, false, NULL),
    (1283, 'tanzil-uthmani-v1.1', 9, 48, 'لَقَدِ ٱبْتَغَوُا۟ ٱلْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا۟ لَكَ ٱلْأُمُورَ حَتَّىٰ جَآءَ ٱلْحَقُّ وَظَهَرَ أَمْرُ ٱللَّهِ وَهُمْ كَٰرِهُونَ', '498999daeebea563307c0f626818e5c86ca65f6e95b2e7365f4b215a754c8c85', 'لَقَدِ ٱبْتَغَوُا۟ ٱلْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا۟ لَكَ ٱلْأُمُورَ حَتَّىٰ جَآءَ ٱلْحَقُّ وَظَهَرَ أَمْرُ ٱللَّهِ وَهُمْ كَٰرِهُونَ', '498999daeebea563307c0f626818e5c86ca65f6e95b2e7365f4b215a754c8c85', '498999daeebea563307c0f626818e5c86ca65f6e95b2e7365f4b215a754c8c85', NULL, 'لقد ابتغوا الفتنه من قبل وقلبوا لك الامور حتي جاء الحق وظهر امر الله وهم كرهون', 10, 20, 78, 1, 2, 195, false, NULL),
    (1284, 'tanzil-uthmani-v1.1', 9, 49, 'وَمِنْهُم مَّن يَقُولُ ٱئْذَن لِّى وَلَا تَفْتِنِّىٓ أَلَا فِى ٱلْفِتْنَةِ سَقَطُوا۟ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', '4494bd4c8a866343b60871cb5914947c9676ef1a68e685f1fe87bd89efe8a913', 'وَمِنْهُم مَّن يَقُولُ ٱئْذَن لِّى وَلَا تَفْتِنِّىٓ أَلَا فِى ٱلْفِتْنَةِ سَقَطُوا۟ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', '4494bd4c8a866343b60871cb5914947c9676ef1a68e685f1fe87bd89efe8a913', '4494bd4c8a866343b60871cb5914947c9676ef1a68e685f1fe87bd89efe8a913', NULL, 'ومنهم من يقول ائذن لي ولا تفتني الا في الفتنه سقطوا وان جهنم لمحيطه بالكفرين', 10, 20, 78, 1, 2, 195, false, NULL),
    (1285, 'tanzil-uthmani-v1.1', 9, 50, 'إِن تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكَ مُصِيبَةٌ يَقُولُوا۟ قَدْ أَخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا۟ وَّهُمْ فَرِحُونَ', 'cc48ab575d179494040a9229c35b221b8b4b8fb925ad310c4bf02b904b7bd7c5', 'إِن تُصِبْكَ حَسَنَةٌ تَسُؤْهُمْ وَإِن تُصِبْكَ مُصِيبَةٌ يَقُولُوا۟ قَدْ أَخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا۟ وَّهُمْ فَرِحُونَ', 'cc48ab575d179494040a9229c35b221b8b4b8fb925ad310c4bf02b904b7bd7c5', 'cc48ab575d179494040a9229c35b221b8b4b8fb925ad310c4bf02b904b7bd7c5', NULL, 'ان تصبك حسنه تسؤهم وان تصبك مصيبه يقولوا قد اخذنا امرنا من قبل ويتولوا وهم فرحون', 10, 20, 78, 1, 2, 195, false, NULL),
    (1286, 'tanzil-uthmani-v1.1', 9, 51, 'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'f82697d3942e484ece5e7a29a56e6aae2610ea0e3e117b3ae5b5b78d6ea9699c', 'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'f82697d3942e484ece5e7a29a56e6aae2610ea0e3e117b3ae5b5b78d6ea9699c', 'f82697d3942e484ece5e7a29a56e6aae2610ea0e3e117b3ae5b5b78d6ea9699c', NULL, 'قل لن يصيبنا الا ما كتب الله لنا هو مولينا وعلي الله فليتوكل المؤمنون', 10, 20, 78, 1, 2, 195, false, NULL),
    (1287, 'tanzil-uthmani-v1.1', 9, 52, 'قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ٱلْحُسْنَيَيْنِ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٍ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا فَتَرَبَّصُوٓا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ', '423534275528fc7ca9394cd352397b2f02b7d70308114f3114c53332d2faece5', 'قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ٱلْحُسْنَيَيْنِ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٍ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا فَتَرَبَّصُوٓا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ', '423534275528fc7ca9394cd352397b2f02b7d70308114f3114c53332d2faece5', '423534275528fc7ca9394cd352397b2f02b7d70308114f3114c53332d2faece5', NULL, 'قل هل تربصون بنا الا احدي الحسنيين ونحن نتربص بكم ان يصيبكم الله بعذاب من عنده او بايدينا فتربصوا انا معكم متربصون', 10, 20, 78, 1, 2, 195, false, NULL),
    (1288, 'tanzil-uthmani-v1.1', 9, 53, 'قُلْ أَنفِقُوا۟ طَوْعًا أَوْ كَرْهًا لَّن يُتَقَبَّلَ مِنكُمْ إِنَّكُمْ كُنتُمْ قَوْمًا فَٰسِقِينَ', '426449a0580a66162b507e1a8e15d1f423c65a65fe896eac9430a3b4c2dcd874', 'قُلْ أَنفِقُوا۟ طَوْعًا أَوْ كَرْهًا لَّن يُتَقَبَّلَ مِنكُمْ إِنَّكُمْ كُنتُمْ قَوْمًا فَٰسِقِينَ', '426449a0580a66162b507e1a8e15d1f423c65a65fe896eac9430a3b4c2dcd874', '426449a0580a66162b507e1a8e15d1f423c65a65fe896eac9430a3b4c2dcd874', NULL, 'قل انفقوا طوعا او كرها لن يتقبل منكم انكم كنتم قوما فسقين', 10, 20, 78, 1, 2, 195, false, NULL),
    (1289, 'tanzil-uthmani-v1.1', 9, 54, 'وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَٰتُهُمْ إِلَّآ أَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأْتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَٰرِهُونَ', 'c10c381f3bd4e6101ae1da75f7b50979cceeb380fff64119348075a83112fcab', 'وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَٰتُهُمْ إِلَّآ أَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأْتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَٰرِهُونَ', 'c10c381f3bd4e6101ae1da75f7b50979cceeb380fff64119348075a83112fcab', 'c10c381f3bd4e6101ae1da75f7b50979cceeb380fff64119348075a83112fcab', NULL, 'وما منعهم ان تقبل منهم نفقتهم الا انهم كفروا بالله وبرسوله ولا ياتون الصلوه الا وهم كسالي ولا ينفقون الا وهم كرهون', 10, 20, 78, 1, 2, 195, false, NULL),
    (1290, 'tanzil-uthmani-v1.1', 9, 55, 'فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 'a9bd804777c4c8ae9e9337ea75648bb5f7ca23101eb231a9e3bda7ddbb0e3635', 'فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 'a9bd804777c4c8ae9e9337ea75648bb5f7ca23101eb231a9e3bda7ddbb0e3635', 'a9bd804777c4c8ae9e9337ea75648bb5f7ca23101eb231a9e3bda7ddbb0e3635', NULL, 'فلا تعجبك امولهم ولا اولدهم انما يريد الله ليعذبهم بها في الحيوه الدنيا وتزهق انفسهم وهم كفرون', 10, 20, 78, 1, 2, 196, false, NULL),
    (1291, 'tanzil-uthmani-v1.1', 9, 56, 'وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ', '7b5f9cbdb6dcdb7061205075d70336a59d8e21586d7201b40b61d6decb1fa694', 'وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ', '7b5f9cbdb6dcdb7061205075d70336a59d8e21586d7201b40b61d6decb1fa694', '7b5f9cbdb6dcdb7061205075d70336a59d8e21586d7201b40b61d6decb1fa694', NULL, 'ويحلفون بالله انهم لمنكم وما هم منكم ولكنهم قوم يفرقون', 10, 20, 78, 1, 2, 196, false, NULL),
    (1292, 'tanzil-uthmani-v1.1', 9, 57, 'لَوْ يَجِدُونَ مَلْجَـًٔا أَوْ مَغَٰرَٰتٍ أَوْ مُدَّخَلًا لَّوَلَّوْا۟ إِلَيْهِ وَهُمْ يَجْمَحُونَ', '1304c69d7423f8d925a620e5d8799f3f47ac1e3f187d49e61b1f1f410fc22e8d', 'لَوْ يَجِدُونَ مَلْجَـًٔا أَوْ مَغَٰرَٰتٍ أَوْ مُدَّخَلًا لَّوَلَّوْا۟ إِلَيْهِ وَهُمْ يَجْمَحُونَ', '1304c69d7423f8d925a620e5d8799f3f47ac1e3f187d49e61b1f1f410fc22e8d', '1304c69d7423f8d925a620e5d8799f3f47ac1e3f187d49e61b1f1f410fc22e8d', NULL, 'لو يجدون ملجا او مغرت او مدخلا لولوا اليه وهم يجمحون', 10, 20, 78, 1, 2, 196, false, NULL),
    (1293, 'tanzil-uthmani-v1.1', 9, 58, 'وَمِنْهُم مَّن يَلْمِزُكَ فِى ٱلصَّدَقَٰتِ فَإِنْ أُعْطُوا۟ مِنْهَا رَضُوا۟ وَإِن لَّمْ يُعْطَوْا۟ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ', '53d6afe65582d68b1c8a2ff458ad545599e540c8bd7a90fb73cf1538b3f9a613', 'وَمِنْهُم مَّن يَلْمِزُكَ فِى ٱلصَّدَقَٰتِ فَإِنْ أُعْطُوا۟ مِنْهَا رَضُوا۟ وَإِن لَّمْ يُعْطَوْا۟ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ', '53d6afe65582d68b1c8a2ff458ad545599e540c8bd7a90fb73cf1538b3f9a613', '53d6afe65582d68b1c8a2ff458ad545599e540c8bd7a90fb73cf1538b3f9a613', NULL, 'ومنهم من يلمزك في الصدقت فان اعطوا منها رضوا وان لم يعطوا منها اذا هم يسخطون', 10, 20, 78, 1, 2, 196, false, NULL),
    (1294, 'tanzil-uthmani-v1.1', 9, 59, 'وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ', 'a69e70b9ef1184d3b90d09f89f1e4ebfd62de53679c9d218c0f2bfd31eb9bc32', 'وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ', 'a69e70b9ef1184d3b90d09f89f1e4ebfd62de53679c9d218c0f2bfd31eb9bc32', 'a69e70b9ef1184d3b90d09f89f1e4ebfd62de53679c9d218c0f2bfd31eb9bc32', NULL, 'ولو انهم رضوا ما ءاتيهم الله ورسوله وقالوا حسبنا الله سيؤتينا الله من فضله ورسوله انا الي الله رغبون', 10, 20, 78, 1, 2, 196, false, NULL),
    (1295, 'tanzil-uthmani-v1.1', 9, 60, 'إِنَّمَا ٱلصَّدَقَٰتُ لِلْفُقَرَآءِ وَٱلْمَسَٰكِينِ وَٱلْعَٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ فَرِيضَةً مِّنَ ٱللَّهِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '1324f3d78dc9237b71dff139a9a3e0f1aabd38fce415938d5473f73170aff22f', 'إِنَّمَا ٱلصَّدَقَٰتُ لِلْفُقَرَآءِ وَٱلْمَسَٰكِينِ وَٱلْعَٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ فَرِيضَةً مِّنَ ٱللَّهِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '1324f3d78dc9237b71dff139a9a3e0f1aabd38fce415938d5473f73170aff22f', '1324f3d78dc9237b71dff139a9a3e0f1aabd38fce415938d5473f73170aff22f', NULL, 'انما الصدقت للفقراء والمسكين والعملين عليها والمؤلفه قلوبهم وفي الرقاب والغرمين وفي سبيل الله وابن السبيل فريضه من الله والله عليم حكيم', 10, 20, 79, 1, 2, 196, false, NULL),
    (1296, 'tanzil-uthmani-v1.1', 9, 61, 'وَمِنْهُمُ ٱلَّذِينَ يُؤْذُونَ ٱلنَّبِىَّ وَيَقُولُونَ هُوَ أُذُنٌ قُلْ أُذُنُ خَيْرٍ لَّكُمْ يُؤْمِنُ بِٱللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌ لِّلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ يُؤْذُونَ رَسُولَ ٱللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ', '57abeaddb0f7f9024faf684f268a93a6f7b177b3b4d753d63a865da1ce1c5569', 'وَمِنْهُمُ ٱلَّذِينَ يُؤْذُونَ ٱلنَّبِىَّ وَيَقُولُونَ هُوَ أُذُنٌ قُلْ أُذُنُ خَيْرٍ لَّكُمْ يُؤْمِنُ بِٱللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌ لِّلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ يُؤْذُونَ رَسُولَ ٱللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ', '57abeaddb0f7f9024faf684f268a93a6f7b177b3b4d753d63a865da1ce1c5569', '57abeaddb0f7f9024faf684f268a93a6f7b177b3b4d753d63a865da1ce1c5569', NULL, 'ومنهم الذين يؤذون النبي ويقولون هو اذن قل اذن خير لكم يؤمن بالله ويؤمن للمؤمنين ورحمه للذين ءامنوا منكم والذين يؤذون رسول الله لهم عذاب اليم', 10, 20, 79, 1, 2, 196, false, NULL),
    (1297, 'tanzil-uthmani-v1.1', 9, 62, 'يَحْلِفُونَ بِٱللَّهِ لَكُمْ لِيُرْضُوكُمْ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا۟ مُؤْمِنِينَ', 'af9c29467a3443b39870a6174e977e666ddcd3981fdb4d9c8c19f6d0d5408bb6', 'يَحْلِفُونَ بِٱللَّهِ لَكُمْ لِيُرْضُوكُمْ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا۟ مُؤْمِنِينَ', 'af9c29467a3443b39870a6174e977e666ddcd3981fdb4d9c8c19f6d0d5408bb6', 'af9c29467a3443b39870a6174e977e666ddcd3981fdb4d9c8c19f6d0d5408bb6', NULL, 'يحلفون بالله لكم ليرضوكم والله ورسوله احق ان يرضوه ان كانوا مؤمنين', 10, 20, 79, 1, 2, 197, false, NULL),
    (1298, 'tanzil-uthmani-v1.1', 9, 63, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدًا فِيهَا ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ', 'a5ffacdf15b80b285091414eeecbcff419868677df7ece455b82e96320fbc017', 'أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدًا فِيهَا ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ', 'a5ffacdf15b80b285091414eeecbcff419868677df7ece455b82e96320fbc017', 'a5ffacdf15b80b285091414eeecbcff419868677df7ece455b82e96320fbc017', NULL, 'الم يعلموا انه من يحادد الله ورسوله فان له نار جهنم خلدا فيها ذلك الخزي العظيم', 10, 20, 79, 1, 2, 197, false, NULL),
    (1299, 'tanzil-uthmani-v1.1', 9, 64, 'يَحْذَرُ ٱلْمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُم بِمَا فِى قُلُوبِهِمْ قُلِ ٱسْتَهْزِءُوٓا۟ إِنَّ ٱللَّهَ مُخْرِجٌ مَّا تَحْذَرُونَ', 'ae5df5a178b7d0cffb02615a0730d8903aef9e7d74784aa04fd4593929e131be', 'يَحْذَرُ ٱلْمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌ تُنَبِّئُهُم بِمَا فِى قُلُوبِهِمْ قُلِ ٱسْتَهْزِءُوٓا۟ إِنَّ ٱللَّهَ مُخْرِجٌ مَّا تَحْذَرُونَ', 'ae5df5a178b7d0cffb02615a0730d8903aef9e7d74784aa04fd4593929e131be', 'ae5df5a178b7d0cffb02615a0730d8903aef9e7d74784aa04fd4593929e131be', NULL, 'يحذر المنفقون ان تنزل عليهم سوره تنبئهم بما في قلوبهم قل استهزءوا ان الله مخرج ما تحذرون', 10, 20, 79, 1, 2, 197, false, NULL),
    (1300, 'tanzil-uthmani-v1.1', 9, 65, 'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ', '163176afbaec272a92009e0b02cfcb87c9fde7d9bdb70be6bf6d1f97398cf7dc', 'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ', '163176afbaec272a92009e0b02cfcb87c9fde7d9bdb70be6bf6d1f97398cf7dc', '163176afbaec272a92009e0b02cfcb87c9fde7d9bdb70be6bf6d1f97398cf7dc', NULL, 'ولئن سالتهم ليقولن انما كنا نخوض ونلعب قل ابالله وءايته ورسوله كنتم تستهزءون', 10, 20, 79, 1, 2, 197, false, NULL),
    (1301, 'tanzil-uthmani-v1.1', 9, 66, 'لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَٰنِكُمْ إِن نَّعْفُ عَن طَآئِفَةٍ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 'a3f9baadd844dd8044d2dea2fad69dab907f603556422f72d1a4dc01d74dcf7d', 'لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَٰنِكُمْ إِن نَّعْفُ عَن طَآئِفَةٍ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 'a3f9baadd844dd8044d2dea2fad69dab907f603556422f72d1a4dc01d74dcf7d', 'a3f9baadd844dd8044d2dea2fad69dab907f603556422f72d1a4dc01d74dcf7d', NULL, 'لا تعتذروا قد كفرتم بعد ايمنكم ان نعف عن طائفه منكم نعذب طائفه بانهم كانوا مجرمين', 10, 20, 79, 1, 2, 197, false, NULL),
    (1302, 'tanzil-uthmani-v1.1', 9, 67, 'ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ بَعْضُهُم مِّنۢ بَعْضٍ يَأْمُرُونَ بِٱلْمُنكَرِ وَيَنْهَوْنَ عَنِ ٱلْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ نَسُوا۟ ٱللَّهَ فَنَسِيَهُمْ إِنَّ ٱلْمُنَٰفِقِينَ هُمُ ٱلْفَٰسِقُونَ', 'e0dc710ff298197105069f638e8d9be38971d6d8af2a21bd25955dc70e8cff8a', 'ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ بَعْضُهُم مِّنۢ بَعْضٍ يَأْمُرُونَ بِٱلْمُنكَرِ وَيَنْهَوْنَ عَنِ ٱلْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ نَسُوا۟ ٱللَّهَ فَنَسِيَهُمْ إِنَّ ٱلْمُنَٰفِقِينَ هُمُ ٱلْفَٰسِقُونَ', 'e0dc710ff298197105069f638e8d9be38971d6d8af2a21bd25955dc70e8cff8a', 'e0dc710ff298197105069f638e8d9be38971d6d8af2a21bd25955dc70e8cff8a', NULL, 'المنفقون والمنفقت بعضهم من بعض يامرون بالمنكر وينهون عن المعروف ويقبضون ايديهم نسوا الله فنسيهم ان المنفقين هم الفسقون', 10, 20, 79, 1, 2, 197, false, NULL),
    (1303, 'tanzil-uthmani-v1.1', 9, 68, 'وَعَدَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَا هِىَ حَسْبُهُمْ وَلَعَنَهُمُ ٱللَّهُ وَلَهُمْ عَذَابٌ مُّقِيمٌ', 'c6a30c0ba0a172cbe0fc06100f5e55a8011f941170b00b709e0b2c98521d4712', 'وَعَدَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَا هِىَ حَسْبُهُمْ وَلَعَنَهُمُ ٱللَّهُ وَلَهُمْ عَذَابٌ مُّقِيمٌ', 'c6a30c0ba0a172cbe0fc06100f5e55a8011f941170b00b709e0b2c98521d4712', 'c6a30c0ba0a172cbe0fc06100f5e55a8011f941170b00b709e0b2c98521d4712', NULL, 'وعد الله المنفقين والمنفقت والكفار نار جهنم خلدين فيها هي حسبهم ولعنهم الله ولهم عذاب مقيم', 10, 20, 79, 1, 2, 197, false, NULL),
    (1304, 'tanzil-uthmani-v1.1', 9, 69, 'كَٱلَّذِينَ مِن قَبْلِكُمْ كَانُوٓا۟ أَشَدَّ مِنكُمْ قُوَّةً وَأَكْثَرَ أَمْوَٰلًا وَأَوْلَٰدًا فَٱسْتَمْتَعُوا۟ بِخَلَٰقِهِمْ فَٱسْتَمْتَعْتُم بِخَلَٰقِكُمْ كَمَا ٱسْتَمْتَعَ ٱلَّذِينَ مِن قَبْلِكُم بِخَلَٰقِهِمْ وَخُضْتُمْ كَٱلَّذِى خَاضُوٓا۟ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'ca2cf7818f4c5a3806def452bc15e78e5b0ab39bcc2609cc8a832e9fc2adcc62', 'كَٱلَّذِينَ مِن قَبْلِكُمْ كَانُوٓا۟ أَشَدَّ مِنكُمْ قُوَّةً وَأَكْثَرَ أَمْوَٰلًا وَأَوْلَٰدًا فَٱسْتَمْتَعُوا۟ بِخَلَٰقِهِمْ فَٱسْتَمْتَعْتُم بِخَلَٰقِكُمْ كَمَا ٱسْتَمْتَعَ ٱلَّذِينَ مِن قَبْلِكُم بِخَلَٰقِهِمْ وَخُضْتُمْ كَٱلَّذِى خَاضُوٓا۟ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 'ca2cf7818f4c5a3806def452bc15e78e5b0ab39bcc2609cc8a832e9fc2adcc62', 'ca2cf7818f4c5a3806def452bc15e78e5b0ab39bcc2609cc8a832e9fc2adcc62', NULL, 'كالذين من قبلكم كانوا اشد منكم قوه واكثر امولا واولدا فاستمتعوا بخلقهم فاستمتعتم بخلقكم كما استمتع الذين من قبلكم بخلقهم وخضتم كالذي خاضوا اولئك حبطت اعملهم في الدنيا والاخره واولئك هم الخسرون', 10, 20, 79, 1, 2, 198, false, NULL),
    (1305, 'tanzil-uthmani-v1.1', 9, 70, 'أَلَمْ يَأْتِهِمْ نَبَأُ ٱلَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَٰبِ مَدْيَنَ وَٱلْمُؤْتَفِكَٰتِ أَتَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'b8905a0b7559b1506b35f1f91f83c843790563a1deb6b10948e1f253aff61c94', 'أَلَمْ يَأْتِهِمْ نَبَأُ ٱلَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَٰبِ مَدْيَنَ وَٱلْمُؤْتَفِكَٰتِ أَتَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'b8905a0b7559b1506b35f1f91f83c843790563a1deb6b10948e1f253aff61c94', 'b8905a0b7559b1506b35f1f91f83c843790563a1deb6b10948e1f253aff61c94', NULL, 'الم ياتهم نبا الذين من قبلهم قوم نوح وعاد وثمود وقوم ابرهيم واصحب مدين والمؤتفكت اتتهم رسلهم بالبينت فما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون', 10, 20, 79, 1, 2, 198, false, NULL),
    (1306, 'tanzil-uthmani-v1.1', 9, 71, 'وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '3e5ea6d724d018de9253aa2cfce78df8d6c8c4f252b19dee03de4d8acaeb17e5', 'وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', '3e5ea6d724d018de9253aa2cfce78df8d6c8c4f252b19dee03de4d8acaeb17e5', '3e5ea6d724d018de9253aa2cfce78df8d6c8c4f252b19dee03de4d8acaeb17e5', NULL, 'والمؤمنون والمؤمنت بعضهم اولياء بعض يامرون بالمعروف وينهون عن المنكر ويقيمون الصلوه ويؤتون الزكوه ويطيعون الله ورسوله اولئك سيرحمهم الله ان الله عزيز حكيم', 10, 20, 79, 1, 2, 198, false, NULL),
    (1307, 'tanzil-uthmani-v1.1', 9, 72, 'وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةً فِى جَنَّٰتِ عَدْنٍ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ أَكْبَرُ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'c3708e67505c1a006781030318a3b12c599b564f1595f239866926d46e8a61be', 'وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةً فِى جَنَّٰتِ عَدْنٍ وَرِضْوَٰنٌ مِّنَ ٱللَّهِ أَكْبَرُ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'c3708e67505c1a006781030318a3b12c599b564f1595f239866926d46e8a61be', 'c3708e67505c1a006781030318a3b12c599b564f1595f239866926d46e8a61be', NULL, 'وعد الله المؤمنين والمؤمنت جنت تجري من تحتها الانهر خلدين فيها ومسكن طيبه في جنت عدن ورضون من الله اكبر ذلك هو الفوز العظيم', 10, 20, 79, 1, 2, 198, false, NULL),
    (1308, 'tanzil-uthmani-v1.1', 9, 73, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'a139f24252aceaca90815affeaad879ea850f82261322d9a23939de18e793cc7', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'a139f24252aceaca90815affeaad879ea850f82261322d9a23939de18e793cc7', 'a139f24252aceaca90815affeaad879ea850f82261322d9a23939de18e793cc7', NULL, 'يايها النبي جهد الكفار والمنفقين واغلظ عليهم وماويهم جهنم وبئس المصير', 10, 20, 79, 1, 2, 199, false, NULL),
    (1309, 'tanzil-uthmani-v1.1', 9, 74, 'يَحْلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدْ قَالُوا۟ كَلِمَةَ ٱلْكُفْرِ وَكَفَرُوا۟ بَعْدَ إِسْلَٰمِهِمْ وَهَمُّوا۟ بِمَا لَمْ يَنَالُوا۟ وَمَا نَقَمُوٓا۟ إِلَّآ أَنْ أَغْنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ فَإِن يَتُوبُوا۟ يَكُ خَيْرًا لَّهُمْ وَإِن يَتَوَلَّوْا۟ يُعَذِّبْهُمُ ٱللَّهُ عَذَابًا أَلِيمًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُمْ فِى ٱلْأَرْضِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'f2c931e966e343c931f34456875a775cae056f1a6d8aeeff29f72f9949d5221c', 'يَحْلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدْ قَالُوا۟ كَلِمَةَ ٱلْكُفْرِ وَكَفَرُوا۟ بَعْدَ إِسْلَٰمِهِمْ وَهَمُّوا۟ بِمَا لَمْ يَنَالُوا۟ وَمَا نَقَمُوٓا۟ إِلَّآ أَنْ أَغْنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ فَإِن يَتُوبُوا۟ يَكُ خَيْرًا لَّهُمْ وَإِن يَتَوَلَّوْا۟ يُعَذِّبْهُمُ ٱللَّهُ عَذَابًا أَلِيمًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمَا لَهُمْ فِى ٱلْأَرْضِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'f2c931e966e343c931f34456875a775cae056f1a6d8aeeff29f72f9949d5221c', 'f2c931e966e343c931f34456875a775cae056f1a6d8aeeff29f72f9949d5221c', NULL, 'يحلفون بالله ما قالوا ولقد قالوا كلمه الكفر وكفروا بعد اسلمهم وهموا بما لم ينالوا وما نقموا الا ان اغنيهم الله ورسوله من فضله فان يتوبوا يك خيرا لهم وان يتولوا يعذبهم الله عذابا اليما في الدنيا والاخره وما لهم في الارض من ولي ولا نصير', 10, 20, 79, 1, 2, 199, false, NULL),
    (1310, 'tanzil-uthmani-v1.1', 9, 75, 'وَمِنْهُم مَّنْ عَٰهَدَ ٱللَّهَ لَئِنْ ءَاتَىٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ', 'dcf02e0e5464672eb5ac713a2310ae18a10657b1b26b07f01a1a690a62d03016', 'وَمِنْهُم مَّنْ عَٰهَدَ ٱللَّهَ لَئِنْ ءَاتَىٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ', 'dcf02e0e5464672eb5ac713a2310ae18a10657b1b26b07f01a1a690a62d03016', 'dcf02e0e5464672eb5ac713a2310ae18a10657b1b26b07f01a1a690a62d03016', NULL, 'ومنهم من عهد الله لئن ءاتينا من فضله لنصدقن ولنكونن من الصلحين', 10, 20, 80, 1, 2, 199, false, NULL),
    (1311, 'tanzil-uthmani-v1.1', 9, 76, 'فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'ea566078e96a031c90c0566c00bccce0a531f26eb0133655e74798e82d3cd293', 'فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 'ea566078e96a031c90c0566c00bccce0a531f26eb0133655e74798e82d3cd293', 'ea566078e96a031c90c0566c00bccce0a531f26eb0133655e74798e82d3cd293', NULL, 'فلما ءاتيهم من فضله بخلوا به وتولوا وهم معرضون', 10, 20, 80, 1, 2, 199, false, NULL),
    (1312, 'tanzil-uthmani-v1.1', 9, 77, 'فَأَعْقَبَهُمْ نِفَاقًا فِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ يَكْذِبُونَ', '6c0cacc01ce1e853d19cfb5f2eb1ba4d511da8c27624d347315ceffa83ebbaba', 'فَأَعْقَبَهُمْ نِفَاقًا فِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ يَكْذِبُونَ', '6c0cacc01ce1e853d19cfb5f2eb1ba4d511da8c27624d347315ceffa83ebbaba', '6c0cacc01ce1e853d19cfb5f2eb1ba4d511da8c27624d347315ceffa83ebbaba', NULL, 'فاعقبهم نفاقا في قلوبهم الي يوم يلقونه بما اخلفوا الله ما وعدوه وبما كانوا يكذبون', 10, 20, 80, 1, 2, 199, false, NULL),
    (1313, 'tanzil-uthmani-v1.1', 9, 78, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّٰمُ ٱلْغُيُوبِ', '0adea2dedb1ee8ec12ee4f2d11f423426668cf5a2a5f443bcd47aca12d8a0763', 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّٰمُ ٱلْغُيُوبِ', '0adea2dedb1ee8ec12ee4f2d11f423426668cf5a2a5f443bcd47aca12d8a0763', '0adea2dedb1ee8ec12ee4f2d11f423426668cf5a2a5f443bcd47aca12d8a0763', NULL, 'الم يعلموا ان الله يعلم سرهم ونجويهم وان الله علم الغيوب', 10, 20, 80, 1, 2, 199, false, NULL),
    (1314, 'tanzil-uthmani-v1.1', 9, 79, 'ٱلَّذِينَ يَلْمِزُونَ ٱلْمُطَّوِّعِينَ مِنَ ٱلْمُؤْمِنِينَ فِى ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ سَخِرَ ٱللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '005b89fe1c705cb2df67e29be33df6632f402be7de2927b315a0789d700db930', 'ٱلَّذِينَ يَلْمِزُونَ ٱلْمُطَّوِّعِينَ مِنَ ٱلْمُؤْمِنِينَ فِى ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ سَخِرَ ٱللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '005b89fe1c705cb2df67e29be33df6632f402be7de2927b315a0789d700db930', '005b89fe1c705cb2df67e29be33df6632f402be7de2927b315a0789d700db930', NULL, 'الذين يلمزون المطوعين من المؤمنين في الصدقت والذين لا يجدون الا جهدهم فيسخرون منهم سخر الله منهم ولهم عذاب اليم', 10, 20, 80, 1, 2, 199, false, NULL),
    (1315, 'tanzil-uthmani-v1.1', 9, 80, 'ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'df12a6b65b8b72d8b9fc94f93427abb471d3093c4af70b8786e8a47115e9ef83', 'ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'df12a6b65b8b72d8b9fc94f93427abb471d3093c4af70b8786e8a47115e9ef83', 'df12a6b65b8b72d8b9fc94f93427abb471d3093c4af70b8786e8a47115e9ef83', NULL, 'استغفر لهم او لا تستغفر لهم ان تستغفر لهم سبعين مره فلن يغفر الله لهم ذلك بانهم كفروا بالله ورسوله والله لا يهدي القوم الفسقين', 10, 20, 80, 1, 2, 200, false, NULL),
    (1316, 'tanzil-uthmani-v1.1', 9, 81, 'فَرِحَ ٱلْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓا۟ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِى ٱلْحَرِّ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا لَّوْ كَانُوا۟ يَفْقَهُونَ', '8286f836e17a29fc176c1548c92c788b0b6644eb816105c50cbafec257c6c20e', 'فَرِحَ ٱلْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓا۟ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِى ٱلْحَرِّ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا لَّوْ كَانُوا۟ يَفْقَهُونَ', '8286f836e17a29fc176c1548c92c788b0b6644eb816105c50cbafec257c6c20e', '8286f836e17a29fc176c1548c92c788b0b6644eb816105c50cbafec257c6c20e', NULL, 'فرح المخلفون بمقعدهم خلف رسول الله وكرهوا ان يجهدوا بامولهم وانفسهم في سبيل الله وقالوا لا تنفروا في الحر قل نار جهنم اشد حرا لو كانوا يفقهون', 10, 20, 80, 1, 2, 200, false, NULL),
    (1317, 'tanzil-uthmani-v1.1', 9, 82, 'فَلْيَضْحَكُوا۟ قَلِيلًا وَلْيَبْكُوا۟ كَثِيرًا جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 'fc62fbf1f05c909e3d30c28a7fa38fd3ce04df484ae9de3d6f927ed43eee056b', 'فَلْيَضْحَكُوا۟ قَلِيلًا وَلْيَبْكُوا۟ كَثِيرًا جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 'fc62fbf1f05c909e3d30c28a7fa38fd3ce04df484ae9de3d6f927ed43eee056b', 'fc62fbf1f05c909e3d30c28a7fa38fd3ce04df484ae9de3d6f927ed43eee056b', NULL, 'فليضحكوا قليلا وليبكوا كثيرا جزاء بما كانوا يكسبون', 10, 20, 80, 1, 2, 200, false, NULL),
    (1318, 'tanzil-uthmani-v1.1', 9, 83, 'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٍ مِّنْهُمْ فَٱسْتَـْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا۟ مَعِىَ أَبَدًا وَلَن تُقَٰتِلُوا۟ مَعِىَ عَدُوًّا إِنَّكُمْ رَضِيتُم بِٱلْقُعُودِ أَوَّلَ مَرَّةٍ فَٱقْعُدُوا۟ مَعَ ٱلْخَٰلِفِينَ', 'd00cd4f612e3e6400ac679cef1ec8dec14eb941ec718b4bc110611473cc3f6f7', 'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٍ مِّنْهُمْ فَٱسْتَـْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا۟ مَعِىَ أَبَدًا وَلَن تُقَٰتِلُوا۟ مَعِىَ عَدُوًّا إِنَّكُمْ رَضِيتُم بِٱلْقُعُودِ أَوَّلَ مَرَّةٍ فَٱقْعُدُوا۟ مَعَ ٱلْخَٰلِفِينَ', 'd00cd4f612e3e6400ac679cef1ec8dec14eb941ec718b4bc110611473cc3f6f7', 'd00cd4f612e3e6400ac679cef1ec8dec14eb941ec718b4bc110611473cc3f6f7', NULL, 'فان رجعك الله الي طائفه منهم فاستذنوك للخروج فقل لن تخرجوا معي ابدا ولن تقتلوا معي عدوا انكم رضيتم بالقعود اول مره فاقعدوا مع الخلفين', 10, 20, 80, 1, 2, 200, false, NULL),
    (1319, 'tanzil-uthmani-v1.1', 9, 84, 'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ إِنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمْ فَٰسِقُونَ', 'a141dc848c9fef8a5948b295570451934b835bcb95894220e30f24e365f6f5e3', 'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ إِنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمْ فَٰسِقُونَ', 'a141dc848c9fef8a5948b295570451934b835bcb95894220e30f24e365f6f5e3', 'a141dc848c9fef8a5948b295570451934b835bcb95894220e30f24e365f6f5e3', NULL, 'ولا تصل علي احد منهم مات ابدا ولا تقم علي قبره انهم كفروا بالله ورسوله وماتوا وهم فسقون', 10, 20, 80, 1, 2, 200, false, NULL),
    (1320, 'tanzil-uthmani-v1.1', 9, 85, 'وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', '54f8e313591b8ce5a27a225c974896b86a9338772fc9ed784392ffb727f9fe5c', 'وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَٰدُهُمْ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', '54f8e313591b8ce5a27a225c974896b86a9338772fc9ed784392ffb727f9fe5c', '54f8e313591b8ce5a27a225c974896b86a9338772fc9ed784392ffb727f9fe5c', NULL, 'ولا تعجبك امولهم واولدهم انما يريد الله ان يعذبهم بها في الدنيا وتزهق انفسهم وهم كفرون', 10, 20, 80, 1, 2, 200, false, NULL),
    (1321, 'tanzil-uthmani-v1.1', 9, 86, 'وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَٰعِدِينَ', '7dd0b1fa34eb93bc5c3bfe6a8f6e7def1ef7e31f0529744a4a4724cd58db2c34', 'وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَٰعِدِينَ', '7dd0b1fa34eb93bc5c3bfe6a8f6e7def1ef7e31f0529744a4a4724cd58db2c34', '7dd0b1fa34eb93bc5c3bfe6a8f6e7def1ef7e31f0529744a4a4724cd58db2c34', NULL, 'واذا انزلت سوره ان ءامنوا بالله وجهدوا مع رسوله استذنك اولوا الطول منهم وقالوا ذرنا نكن مع القعدين', 10, 20, 80, 1, 2, 200, false, NULL),
    (1322, 'tanzil-uthmani-v1.1', 9, 87, 'رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'e34f3f28921e38512d52b4cbf56692cc47cd84a6e9f644283497fd914c9a839c', 'رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 'e34f3f28921e38512d52b4cbf56692cc47cd84a6e9f644283497fd914c9a839c', 'e34f3f28921e38512d52b4cbf56692cc47cd84a6e9f644283497fd914c9a839c', NULL, 'رضوا بان يكونوا مع الخوالف وطبع علي قلوبهم فهم لا يفقهون', 10, 20, 80, 1, 2, 201, false, NULL),
    (1323, 'tanzil-uthmani-v1.1', 9, 88, 'لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ جَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَأُو۟لَٰٓئِكَ لَهُمُ ٱلْخَيْرَٰتُ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'b66c4d9905960731e7971bac26903f32868d552a568fca54538eab452b307eb9', 'لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ جَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ وَأُو۟لَٰٓئِكَ لَهُمُ ٱلْخَيْرَٰتُ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'b66c4d9905960731e7971bac26903f32868d552a568fca54538eab452b307eb9', 'b66c4d9905960731e7971bac26903f32868d552a568fca54538eab452b307eb9', NULL, 'لكن الرسول والذين ءامنوا معه جهدوا بامولهم وانفسهم واولئك لهم الخيرت واولئك هم المفلحون', 10, 20, 80, 1, 2, 201, false, NULL),
    (1324, 'tanzil-uthmani-v1.1', 9, 89, 'أَعَدَّ ٱللَّهُ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '2a147e70165bec7b21d6ce876a257e0588474b821e3a63dd0bccf7c65319884a', 'أَعَدَّ ٱللَّهُ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '2a147e70165bec7b21d6ce876a257e0588474b821e3a63dd0bccf7c65319884a', '2a147e70165bec7b21d6ce876a257e0588474b821e3a63dd0bccf7c65319884a', NULL, 'اعد الله لهم جنت تجري من تحتها الانهر خلدين فيها ذلك الفوز العظيم', 10, 20, 80, 1, 2, 201, false, NULL),
    (1325, 'tanzil-uthmani-v1.1', 9, 90, 'وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', '0987cd361c1592cd8551053f8027df744464601b6f1505c28fc18a987faf395d', 'وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', '0987cd361c1592cd8551053f8027df744464601b6f1505c28fc18a987faf395d', '0987cd361c1592cd8551053f8027df744464601b6f1505c28fc18a987faf395d', NULL, 'وجاء المعذرون من الاعراب ليؤذن لهم وقعد الذين كذبوا الله ورسوله سيصيب الذين كفروا منهم عذاب اليم', 10, 20, 80, 1, 2, 201, false, NULL),
    (1326, 'tanzil-uthmani-v1.1', 9, 91, 'لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ مَا عَلَى ٱلْمُحْسِنِينَ مِن سَبِيلٍ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '8cab16085b1dc6c66835684b7f82649055a57cc9c083328ce73f7ba080d7ad2d', 'لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ مَا عَلَى ٱلْمُحْسِنِينَ مِن سَبِيلٍ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '8cab16085b1dc6c66835684b7f82649055a57cc9c083328ce73f7ba080d7ad2d', '8cab16085b1dc6c66835684b7f82649055a57cc9c083328ce73f7ba080d7ad2d', NULL, 'ليس علي الضعفاء ولا علي المرضي ولا علي الذين لا يجدون ما ينفقون حرج اذا نصحوا لله ورسوله ما علي المحسنين من سبيل والله غفور رحيم', 10, 20, 80, 1, 2, 201, false, NULL),
    (1327, 'tanzil-uthmani-v1.1', 9, 92, 'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا۟ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ حَزَنًا أَلَّا يَجِدُوا۟ مَا يُنفِقُونَ', 'b951d9524906c5f7ed20cfdc0be217c0ccd497d70a64b93960c85dedb81e8931', 'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا۟ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ حَزَنًا أَلَّا يَجِدُوا۟ مَا يُنفِقُونَ', 'b951d9524906c5f7ed20cfdc0be217c0ccd497d70a64b93960c85dedb81e8931', 'b951d9524906c5f7ed20cfdc0be217c0ccd497d70a64b93960c85dedb81e8931', NULL, 'ولا علي الذين اذا ما اتوك لتحملهم قلت لا اجد ما احملكم عليه تولوا واعينهم تفيض من الدمع حزنا الا يجدوا ما ينفقون', 10, 20, 80, 1, 2, 201, false, NULL),
    (1328, 'tanzil-uthmani-v1.1', 9, 93, 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ وَهُمْ أَغْنِيَآءُ رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ', '29bd16e846700c2d1330988babc79ca83fb449e3b9f03514a8a801f82d41ee7b', 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ وَهُمْ أَغْنِيَآءُ رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ', '29bd16e846700c2d1330988babc79ca83fb449e3b9f03514a8a801f82d41ee7b', '29bd16e846700c2d1330988babc79ca83fb449e3b9f03514a8a801f82d41ee7b', NULL, 'انما السبيل علي الذين يستذنونك وهم اغنياء رضوا بان يكونوا مع الخوالف وطبع الله علي قلوبهم فهم لا يعلمون', 11, 21, 81, 1, 2, 201, false, NULL),
    (1329, 'tanzil-uthmani-v1.1', 9, 94, 'يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ قُل لَّا تَعْتَذِرُوا۟ لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا ٱللَّهُ مِنْ أَخْبَارِكُمْ وَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'a09ed6d07d1b916344eab2b1bea27c208ca5fb0b19a09bffd6bf60656b14d73d', 'يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ قُل لَّا تَعْتَذِرُوا۟ لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا ٱللَّهُ مِنْ أَخْبَارِكُمْ وَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 'a09ed6d07d1b916344eab2b1bea27c208ca5fb0b19a09bffd6bf60656b14d73d', 'a09ed6d07d1b916344eab2b1bea27c208ca5fb0b19a09bffd6bf60656b14d73d', NULL, 'يعتذرون اليكم اذا رجعتم اليهم قل لا تعتذروا لن نؤمن لكم قد نبانا الله من اخباركم وسيري الله عملكم ورسوله ثم تردون الي علم الغيب والشهده فينبئكم بما كنتم تعملون', 11, 21, 81, 1, 2, 202, false, NULL),
    (1330, 'tanzil-uthmani-v1.1', 9, 95, 'سَيَحْلِفُونَ بِٱللَّهِ لَكُمْ إِذَا ٱنقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا۟ عَنْهُمْ فَأَعْرِضُوا۟ عَنْهُمْ إِنَّهُمْ رِجْسٌ وَمَأْوَىٰهُمْ جَهَنَّمُ جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', '6a6bf052b02a916aa9c39551300980487d01ac52cab8f3a39bc00ea32fc1a85e', 'سَيَحْلِفُونَ بِٱللَّهِ لَكُمْ إِذَا ٱنقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا۟ عَنْهُمْ فَأَعْرِضُوا۟ عَنْهُمْ إِنَّهُمْ رِجْسٌ وَمَأْوَىٰهُمْ جَهَنَّمُ جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', '6a6bf052b02a916aa9c39551300980487d01ac52cab8f3a39bc00ea32fc1a85e', '6a6bf052b02a916aa9c39551300980487d01ac52cab8f3a39bc00ea32fc1a85e', NULL, 'سيحلفون بالله لكم اذا انقلبتم اليهم لتعرضوا عنهم فاعرضوا عنهم انهم رجس وماويهم جهنم جزاء بما كانوا يكسبون', 11, 21, 81, 1, 2, 202, false, NULL),
    (1331, 'tanzil-uthmani-v1.1', 9, 96, 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', '93948827036f1c3448151ddc3ee6506b1123efda1af78b07ec42254341717f44', 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', '93948827036f1c3448151ddc3ee6506b1123efda1af78b07ec42254341717f44', '93948827036f1c3448151ddc3ee6506b1123efda1af78b07ec42254341717f44', NULL, 'يحلفون لكم لترضوا عنهم فان ترضوا عنهم فان الله لا يرضي عن القوم الفسقين', 11, 21, 81, 1, 2, 202, false, NULL),
    (1332, 'tanzil-uthmani-v1.1', 9, 97, 'ٱلْأَعْرَابُ أَشَدُّ كُفْرًا وَنِفَاقًا وَأَجْدَرُ أَلَّا يَعْلَمُوا۟ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'bc8a540f3a6a90441f9091a2d07c21002bf5499475ebfb21c5342d035d935040', 'ٱلْأَعْرَابُ أَشَدُّ كُفْرًا وَنِفَاقًا وَأَجْدَرُ أَلَّا يَعْلَمُوا۟ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'bc8a540f3a6a90441f9091a2d07c21002bf5499475ebfb21c5342d035d935040', 'bc8a540f3a6a90441f9091a2d07c21002bf5499475ebfb21c5342d035d935040', NULL, 'الاعراب اشد كفرا ونفاقا واجدر الا يعلموا حدود ما انزل الله علي رسوله والله عليم حكيم', 11, 21, 81, 1, 2, 202, false, NULL),
    (1333, 'tanzil-uthmani-v1.1', 9, 98, 'وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '430781549cb646dc289197068c39f0f595be2a35b5b24079ba698ff440a22f6e', 'وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '430781549cb646dc289197068c39f0f595be2a35b5b24079ba698ff440a22f6e', '430781549cb646dc289197068c39f0f595be2a35b5b24079ba698ff440a22f6e', NULL, 'ومن الاعراب من يتخذ ما ينفق مغرما ويتربص بكم الدوائر عليهم دائره السوء والله سميع عليم', 11, 21, 81, 1, 2, 202, false, NULL),
    (1334, 'tanzil-uthmani-v1.1', 9, 99, 'وَمِنَ ٱلْأَعْرَابِ مَن يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِ أَلَآ إِنَّهَا قُرْبَةٌ لَّهُمْ سَيُدْخِلُهُمُ ٱللَّهُ فِى رَحْمَتِهِۦٓ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'bfd1ccc95d29144ff12627cbb6906c690201c5b3fa4fb305a6012ef1b6948b9d', 'وَمِنَ ٱلْأَعْرَابِ مَن يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِ أَلَآ إِنَّهَا قُرْبَةٌ لَّهُمْ سَيُدْخِلُهُمُ ٱللَّهُ فِى رَحْمَتِهِۦٓ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'bfd1ccc95d29144ff12627cbb6906c690201c5b3fa4fb305a6012ef1b6948b9d', 'bfd1ccc95d29144ff12627cbb6906c690201c5b3fa4fb305a6012ef1b6948b9d', NULL, 'ومن الاعراب من يؤمن بالله واليوم الاخر ويتخذ ما ينفق قربت عند الله وصلوت الرسول الا انها قربه لهم سيدخلهم الله في رحمته ان الله غفور رحيم', 11, 21, 81, 1, 2, 202, false, NULL),
    (1335, 'tanzil-uthmani-v1.1', 9, 100, 'وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '9f314a05de55162ea27ead033c08bbbbbd4e3c4e783982ec0f5b22dddd5cb27c', 'وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', '9f314a05de55162ea27ead033c08bbbbbd4e3c4e783982ec0f5b22dddd5cb27c', '9f314a05de55162ea27ead033c08bbbbbd4e3c4e783982ec0f5b22dddd5cb27c', NULL, 'والسبقون الاولون من المهجرين والانصار والذين اتبعوهم باحسن رضي الله عنهم ورضوا عنه واعد لهم جنت تجري تحتها الانهر خلدين فيها ابدا ذلك الفوز العظيم', 11, 21, 81, 1, 2, 203, false, NULL),
    (1336, 'tanzil-uthmani-v1.1', 9, 101, 'وَمِمَّنْ حَوْلَكُم مِّنَ ٱلْأَعْرَابِ مُنَٰفِقُونَ وَمِنْ أَهْلِ ٱلْمَدِينَةِ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ', 'cf429f44e36d23da490adad300e1619e2898affb5b9c11488d528af7d099b4a8', 'وَمِمَّنْ حَوْلَكُم مِّنَ ٱلْأَعْرَابِ مُنَٰفِقُونَ وَمِنْ أَهْلِ ٱلْمَدِينَةِ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعْلَمُهُمْ نَحْنُ نَعْلَمُهُمْ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ', 'cf429f44e36d23da490adad300e1619e2898affb5b9c11488d528af7d099b4a8', 'cf429f44e36d23da490adad300e1619e2898affb5b9c11488d528af7d099b4a8', NULL, 'وممن حولكم من الاعراب منفقون ومن اهل المدينه مردوا علي النفاق لا تعلمهم نحن نعلمهم سنعذبهم مرتين ثم يردون الي عذاب عظيم', 11, 21, 81, 1, 2, 203, false, NULL),
    (1337, 'tanzil-uthmani-v1.1', 9, 102, 'وَءَاخَرُونَ ٱعْتَرَفُوا۟ بِذُنُوبِهِمْ خَلَطُوا۟ عَمَلًا صَٰلِحًا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '8efa243854888cdcf5b2b447261bce2ebaae4c8150cc28872b941d71e8135154', 'وَءَاخَرُونَ ٱعْتَرَفُوا۟ بِذُنُوبِهِمْ خَلَطُوا۟ عَمَلًا صَٰلِحًا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '8efa243854888cdcf5b2b447261bce2ebaae4c8150cc28872b941d71e8135154', '8efa243854888cdcf5b2b447261bce2ebaae4c8150cc28872b941d71e8135154', NULL, 'وءاخرون اعترفوا بذنوبهم خلطوا عملا صلحا وءاخر سيئا عسي الله ان يتوب عليهم ان الله غفور رحيم', 11, 21, 81, 1, 2, 203, false, NULL),
    (1338, 'tanzil-uthmani-v1.1', 9, 103, 'خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ إِنَّ صَلَوٰتَكَ سَكَنٌ لَّهُمْ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'aca2514d9f4e9d49078b37526a9ee9e209b0ef90639bc6b37d80f8e3d2741cd5', 'خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ إِنَّ صَلَوٰتَكَ سَكَنٌ لَّهُمْ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'aca2514d9f4e9d49078b37526a9ee9e209b0ef90639bc6b37d80f8e3d2741cd5', 'aca2514d9f4e9d49078b37526a9ee9e209b0ef90639bc6b37d80f8e3d2741cd5', NULL, 'خذ من امولهم صدقه تطهرهم وتزكيهم بها وصل عليهم ان صلوتك سكن لهم والله سميع عليم', 11, 21, 81, 1, 2, 203, false, NULL),
    (1339, 'tanzil-uthmani-v1.1', 9, 104, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '9364a5c3b62524fd9c26cb70de8101be8aab4200ace93efa0b262c7687462c49', 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '9364a5c3b62524fd9c26cb70de8101be8aab4200ace93efa0b262c7687462c49', '9364a5c3b62524fd9c26cb70de8101be8aab4200ace93efa0b262c7687462c49', NULL, 'الم يعلموا ان الله هو يقبل التوبه عن عباده وياخذ الصدقت وان الله هو التواب الرحيم', 11, 21, 81, 1, 2, 203, false, NULL),
    (1340, 'tanzil-uthmani-v1.1', 9, 105, 'وَقُلِ ٱعْمَلُوا۟ فَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَٱلْمُؤْمِنُونَ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '98249c08c1f00479b4a185fd114d8702230010e3deda0da0b1e9536a58e224a1', 'وَقُلِ ٱعْمَلُوا۟ فَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَٱلْمُؤْمِنُونَ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '98249c08c1f00479b4a185fd114d8702230010e3deda0da0b1e9536a58e224a1', '98249c08c1f00479b4a185fd114d8702230010e3deda0da0b1e9536a58e224a1', NULL, 'وقل اعملوا فسيري الله عملكم ورسوله والمؤمنون وستردون الي علم الغيب والشهده فينبئكم بما كنتم تعملون', 11, 21, 81, 1, 2, 203, false, NULL),
    (1341, 'tanzil-uthmani-v1.1', 9, 106, 'وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'e1bfead08e9a4c0d7f984cabdc4e7ee5bbadb70d80f4e07c14f835209da85318', 'وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'e1bfead08e9a4c0d7f984cabdc4e7ee5bbadb70d80f4e07c14f835209da85318', 'e1bfead08e9a4c0d7f984cabdc4e7ee5bbadb70d80f4e07c14f835209da85318', NULL, 'وءاخرون مرجون لامر الله اما يعذبهم واما يتوب عليهم والله عليم حكيم', 11, 21, 81, 1, 2, 203, false, NULL),
    (1342, 'tanzil-uthmani-v1.1', 9, 107, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًۢا بَيْنَ ٱلْمُؤْمِنِينَ وَإِرْصَادًا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَآ إِلَّا ٱلْحُسْنَىٰ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', '14d5073c04e75142390a17028436377c90eb533325eb1863ba1903feee1352b4', 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًۢا بَيْنَ ٱلْمُؤْمِنِينَ وَإِرْصَادًا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَآ إِلَّا ٱلْحُسْنَىٰ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', '14d5073c04e75142390a17028436377c90eb533325eb1863ba1903feee1352b4', '14d5073c04e75142390a17028436377c90eb533325eb1863ba1903feee1352b4', NULL, 'والذين اتخذوا مسجدا ضرارا وكفرا وتفريقا بين المؤمنين وارصادا لمن حارب الله ورسوله من قبل وليحلفن ان اردنا الا الحسني والله يشهد انهم لكذبون', 11, 21, 81, 1, 2, 204, false, NULL),
    (1343, 'tanzil-uthmani-v1.1', 9, 108, 'لَا تَقُمْ فِيهِ أَبَدًا لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ', '7e707592fd62555264de34e0a8e6279293fe3bddb4f3bb5adfcc788617f4caf3', 'لَا تَقُمْ فِيهِ أَبَدًا لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ', '7e707592fd62555264de34e0a8e6279293fe3bddb4f3bb5adfcc788617f4caf3', '7e707592fd62555264de34e0a8e6279293fe3bddb4f3bb5adfcc788617f4caf3', NULL, 'لا تقم فيه ابدا لمسجد اسس علي التقوي من اول يوم احق ان تقوم فيه فيه رجال يحبون ان يتطهروا والله يحب المطهرين', 11, 21, 81, 1, 2, 204, false, NULL),
    (1344, 'tanzil-uthmani-v1.1', 9, 109, 'أَفَمَنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ تَقْوَىٰ مِنَ ٱللَّهِ وَرِضْوَٰنٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٍ فَٱنْهَارَ بِهِۦ فِى نَارِ جَهَنَّمَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '313ea77082204cb8339c745b88950726c6f1ccac24a5a8b865de0381f6feb6ef', 'أَفَمَنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ تَقْوَىٰ مِنَ ٱللَّهِ وَرِضْوَٰنٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٍ فَٱنْهَارَ بِهِۦ فِى نَارِ جَهَنَّمَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '313ea77082204cb8339c745b88950726c6f1ccac24a5a8b865de0381f6feb6ef', '313ea77082204cb8339c745b88950726c6f1ccac24a5a8b865de0381f6feb6ef', NULL, 'افمن اسس بنينه علي تقوي من الله ورضون خير ام من اسس بنينه علي شفا جرف هار فانهار به في نار جهنم والله لا يهدي القوم الظلمين', 11, 21, 81, 1, 2, 204, false, NULL),
    (1345, 'tanzil-uthmani-v1.1', 9, 110, 'لَا يَزَالُ بُنْيَٰنُهُمُ ٱلَّذِى بَنَوْا۟ رِيبَةً فِى قُلُوبِهِمْ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '2b431b8665d5931e58fcea91048c54b7864f09a1b8f7d4fce4ce479edceca0ca', 'لَا يَزَالُ بُنْيَٰنُهُمُ ٱلَّذِى بَنَوْا۟ رِيبَةً فِى قُلُوبِهِمْ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '2b431b8665d5931e58fcea91048c54b7864f09a1b8f7d4fce4ce479edceca0ca', '2b431b8665d5931e58fcea91048c54b7864f09a1b8f7d4fce4ce479edceca0ca', NULL, 'لا يزال بنينهم الذي بنوا ريبه في قلوبهم الا ان تقطع قلوبهم والله عليم حكيم', 11, 21, 81, 1, 2, 204, false, NULL),
    (1346, 'tanzil-uthmani-v1.1', 9, 111, 'إِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْدًا عَلَيْهِ حَقًّا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '48371d55473dcccf4ac23ac1f15aab70ec601651d2739c84d7ecbcd614073f3d', 'إِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ وَعْدًا عَلَيْهِ حَقًّا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '48371d55473dcccf4ac23ac1f15aab70ec601651d2739c84d7ecbcd614073f3d', '48371d55473dcccf4ac23ac1f15aab70ec601651d2739c84d7ecbcd614073f3d', NULL, 'ان الله اشتري من المؤمنين انفسهم وامولهم بان لهم الجنه يقتلون في سبيل الله فيقتلون ويقتلون وعدا عليه حقا في التوريه والانجيل والقرءان ومن اوفي بعهده من الله فاستبشروا ببيعكم الذي بايعتم به وذلك هو الفوز العظيم', 11, 21, 82, 1, 2, 204, false, NULL),
    (1347, 'tanzil-uthmani-v1.1', 9, 112, 'ٱلتَّٰٓئِبُونَ ٱلْعَٰبِدُونَ ٱلْحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلْـَٔامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَٰفِظُونَ لِحُدُودِ ٱللَّهِ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'b9e8e2e99d0a45a606910bcd76cf195b98aedecb8bd3cabcbd31913bcecb728d', 'ٱلتَّٰٓئِبُونَ ٱلْعَٰبِدُونَ ٱلْحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلْـَٔامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَٰفِظُونَ لِحُدُودِ ٱللَّهِ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 'b9e8e2e99d0a45a606910bcd76cf195b98aedecb8bd3cabcbd31913bcecb728d', 'b9e8e2e99d0a45a606910bcd76cf195b98aedecb8bd3cabcbd31913bcecb728d', NULL, 'التئبون العبدون الحمدون السئحون الركعون السجدون الامرون بالمعروف والناهون عن المنكر والحفظون لحدود الله وبشر المؤمنين', 11, 21, 82, 1, 2, 205, false, NULL),
    (1348, 'tanzil-uthmani-v1.1', 9, 113, 'مَا كَانَ لِلنَّبِىِّ وَٱلَّذِينَ ءَامَنُوٓا۟ أَن يَسْتَغْفِرُوا۟ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓا۟ أُو۟لِى قُرْبَىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَٰبُ ٱلْجَحِيمِ', '7ee7128b0dc48ad3a691562fa7f5e8a22885b6d0ab88d17e60164ea916b363da', 'مَا كَانَ لِلنَّبِىِّ وَٱلَّذِينَ ءَامَنُوٓا۟ أَن يَسْتَغْفِرُوا۟ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓا۟ أُو۟لِى قُرْبَىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَٰبُ ٱلْجَحِيمِ', '7ee7128b0dc48ad3a691562fa7f5e8a22885b6d0ab88d17e60164ea916b363da', '7ee7128b0dc48ad3a691562fa7f5e8a22885b6d0ab88d17e60164ea916b363da', NULL, 'ما كان للنبي والذين ءامنوا ان يستغفروا للمشركين ولو كانوا اولي قربي من بعد ما تبين لهم انهم اصحب الجحيم', 11, 21, 82, 1, 2, 205, false, NULL),
    (1349, 'tanzil-uthmani-v1.1', 9, 114, 'وَمَا كَانَ ٱسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٌ', '1330a51a7fa14903e94e580ed1d9f18e9d8ddea4a17e0cd0ece4eb9d92561c2e', 'وَمَا كَانَ ٱسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٌ', '1330a51a7fa14903e94e580ed1d9f18e9d8ddea4a17e0cd0ece4eb9d92561c2e', '1330a51a7fa14903e94e580ed1d9f18e9d8ddea4a17e0cd0ece4eb9d92561c2e', NULL, 'وما كان استغفار ابرهيم لابيه الا عن موعده وعدها اياه فلما تبين له انه عدو لله تبرا منه ان ابرهيم لاوه حليم', 11, 21, 82, 1, 2, 205, false, NULL),
    (1350, 'tanzil-uthmani-v1.1', 9, 115, 'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوْمًۢا بَعْدَ إِذْ هَدَىٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'd2e29ee0ea6f4aff7c3e45a397b1286769dad1f97f198da3cce0cd4607c9c22f', 'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوْمًۢا بَعْدَ إِذْ هَدَىٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'd2e29ee0ea6f4aff7c3e45a397b1286769dad1f97f198da3cce0cd4607c9c22f', 'd2e29ee0ea6f4aff7c3e45a397b1286769dad1f97f198da3cce0cd4607c9c22f', NULL, 'وما كان الله ليضل قوما بعد اذ هديهم حتي يبين لهم ما يتقون ان الله بكل شيء عليم', 11, 21, 82, 1, 2, 205, false, NULL),
    (1351, 'tanzil-uthmani-v1.1', 9, 116, 'إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُحْىِۦ وَيُمِيتُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '3945ce277a6095ad8b398f24f41f0ef75e2a5d4a8eb56bea7dd1fa43a7865192', 'إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُحْىِۦ وَيُمِيتُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '3945ce277a6095ad8b398f24f41f0ef75e2a5d4a8eb56bea7dd1fa43a7865192', '3945ce277a6095ad8b398f24f41f0ef75e2a5d4a8eb56bea7dd1fa43a7865192', NULL, 'ان الله له ملك السموت والارض يحي ويميت وما لكم من دون الله من ولي ولا نصير', 11, 21, 82, 1, 2, 205, false, NULL),
    (1352, 'tanzil-uthmani-v1.1', 9, 117, 'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِىِّ وَٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِى سَاعَةِ ٱلْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُۥ بِهِمْ رَءُوفٌ رَّحِيمٌ', '48e2233544dad51c2575ddfc71aa74409c6375127a9c8adf095e55652aa858e3', 'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِىِّ وَٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِى سَاعَةِ ٱلْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ إِنَّهُۥ بِهِمْ رَءُوفٌ رَّحِيمٌ', '48e2233544dad51c2575ddfc71aa74409c6375127a9c8adf095e55652aa858e3', '48e2233544dad51c2575ddfc71aa74409c6375127a9c8adf095e55652aa858e3', NULL, 'لقد تاب الله علي النبي والمهجرين والانصار الذين اتبعوه في ساعه العسره من بعد ما كاد يزيغ قلوب فريق منهم ثم تاب عليهم انه بهم رءوف رحيم', 11, 21, 82, 1, 2, 205, false, NULL),
    (1353, 'tanzil-uthmani-v1.1', 9, 118, 'وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُوا۟ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوٓا۟ أَن لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '78ef511f13dc98e1dfe2b56608d028570170ed8801b0945ee84ecbf326ac2b55', 'وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُوا۟ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوٓا۟ أَن لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', '78ef511f13dc98e1dfe2b56608d028570170ed8801b0945ee84ecbf326ac2b55', '78ef511f13dc98e1dfe2b56608d028570170ed8801b0945ee84ecbf326ac2b55', NULL, 'وعلي الثلثه الذين خلفوا حتي اذا ضاقت عليهم الارض بما رحبت وضاقت عليهم انفسهم وظنوا ان لا ملجا من الله الا اليه ثم تاب عليهم ليتوبوا ان الله هو التواب الرحيم', 11, 21, 82, 1, 2, 206, false, NULL),
    (1354, 'tanzil-uthmani-v1.1', 9, 119, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّٰدِقِينَ', '9e70e3f982ea76c6c260fb6c3092d44f8bf1cc48221985a16c792aa288de7c00', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّٰدِقِينَ', '9e70e3f982ea76c6c260fb6c3092d44f8bf1cc48221985a16c792aa288de7c00', '9e70e3f982ea76c6c260fb6c3092d44f8bf1cc48221985a16c792aa288de7c00', NULL, 'يايها الذين ءامنوا اتقوا الله وكونوا مع الصدقين', 11, 21, 82, 1, 2, 206, false, NULL),
    (1355, 'tanzil-uthmani-v1.1', 9, 120, 'مَا كَانَ لِأَهْلِ ٱلْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ٱلْأَعْرَابِ أَن يَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا يَرْغَبُوا۟ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِى سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوْطِئًا يَغِيظُ ٱلْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٌ صَٰلِحٌ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'cc724326dd576dd43c7ebc3d3d828425f21756d2d6e88f10ea911b7598f15426', 'مَا كَانَ لِأَهْلِ ٱلْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ٱلْأَعْرَابِ أَن يَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا يَرْغَبُوا۟ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌ وَلَا نَصَبٌ وَلَا مَخْمَصَةٌ فِى سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوْطِئًا يَغِيظُ ٱلْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٌ صَٰلِحٌ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 'cc724326dd576dd43c7ebc3d3d828425f21756d2d6e88f10ea911b7598f15426', 'cc724326dd576dd43c7ebc3d3d828425f21756d2d6e88f10ea911b7598f15426', NULL, 'ما كان لاهل المدينه ومن حولهم من الاعراب ان يتخلفوا عن رسول الله ولا يرغبوا بانفسهم عن نفسه ذلك بانهم لا يصيبهم ظما ولا نصب ولا مخمصه في سبيل الله ولا يطون موطئا يغيظ الكفار ولا ينالون من عدو نيلا الا كتب لهم به عمل صلح ان الله لا يضيع اجر المحسنين', 11, 21, 82, 1, 2, 206, false, NULL),
    (1356, 'tanzil-uthmani-v1.1', 9, 121, 'وَلَا يُنفِقُونَ نَفَقَةً صَغِيرَةً وَلَا كَبِيرَةً وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا كَانُوا۟ يَعْمَلُونَ', '3a537b2872e55b21481e74efdf26aed26f2432b2e46b551b7a2fad8ade67282e', 'وَلَا يُنفِقُونَ نَفَقَةً صَغِيرَةً وَلَا كَبِيرَةً وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا كَانُوا۟ يَعْمَلُونَ', '3a537b2872e55b21481e74efdf26aed26f2432b2e46b551b7a2fad8ade67282e', '3a537b2872e55b21481e74efdf26aed26f2432b2e46b551b7a2fad8ade67282e', NULL, 'ولا ينفقون نفقه صغيره ولا كبيره ولا يقطعون واديا الا كتب لهم ليجزيهم الله احسن ما كانوا يعملون', 11, 21, 82, 1, 2, 206, false, NULL),
    (1357, 'tanzil-uthmani-v1.1', 9, 122, 'وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةً فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَآئِفَةٌ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ', '19d8ee643e484fce95569ff3bec8062c9be4ae27407d87675e594697fd9cec9b', 'وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةً فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَآئِفَةٌ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ', '19d8ee643e484fce95569ff3bec8062c9be4ae27407d87675e594697fd9cec9b', '19d8ee643e484fce95569ff3bec8062c9be4ae27407d87675e594697fd9cec9b', NULL, 'وما كان المؤمنون لينفروا كافه فلولا نفر من كل فرقه منهم طائفه ليتفقهوا في الدين ولينذروا قومهم اذا رجعوا اليهم لعلهم يحذرون', 11, 21, 83, 1, 2, 206, false, NULL),
    (1358, 'tanzil-uthmani-v1.1', 9, 123, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'd56c8f698a2c0951103d4403ac5f50c46076a603792bad6fe19f59e0350c1b4c', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةً وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 'd56c8f698a2c0951103d4403ac5f50c46076a603792bad6fe19f59e0350c1b4c', 'd56c8f698a2c0951103d4403ac5f50c46076a603792bad6fe19f59e0350c1b4c', NULL, 'يايها الذين ءامنوا قتلوا الذين يلونكم من الكفار وليجدوا فيكم غلظه واعلموا ان الله مع المتقين', 11, 21, 83, 1, 2, 207, false, NULL),
    (1359, 'tanzil-uthmani-v1.1', 9, 124, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِۦٓ إِيمَٰنًا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَزَادَتْهُمْ إِيمَٰنًا وَهُمْ يَسْتَبْشِرُونَ', '65ba9fa71a87ef6fa2d923361440597351562fbc86ce72fbdba28ba1c7e682f8', 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِۦٓ إِيمَٰنًا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَزَادَتْهُمْ إِيمَٰنًا وَهُمْ يَسْتَبْشِرُونَ', '65ba9fa71a87ef6fa2d923361440597351562fbc86ce72fbdba28ba1c7e682f8', '65ba9fa71a87ef6fa2d923361440597351562fbc86ce72fbdba28ba1c7e682f8', NULL, 'واذا ما انزلت سوره فمنهم من يقول ايكم زادته هذه ايمنا فاما الذين ءامنوا فزادتهم ايمنا وهم يستبشرون', 11, 21, 83, 1, 2, 207, false, NULL),
    (1360, 'tanzil-uthmani-v1.1', 9, 125, 'وَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا۟ وَهُمْ كَٰفِرُونَ', '971226b564416293c776ec78252a7b11a1071fd61a51e363e57f0292f29eeff8', 'وَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا۟ وَهُمْ كَٰفِرُونَ', '971226b564416293c776ec78252a7b11a1071fd61a51e363e57f0292f29eeff8', '971226b564416293c776ec78252a7b11a1071fd61a51e363e57f0292f29eeff8', NULL, 'واما الذين في قلوبهم مرض فزادتهم رجسا الي رجسهم وماتوا وهم كفرون', 11, 21, 83, 1, 2, 207, false, NULL),
    (1361, 'tanzil-uthmani-v1.1', 9, 126, 'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ', '71927a4f649c55eb2a120d87574ebd369799d0305e031ee8cca36253149fbe3f', 'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ', '71927a4f649c55eb2a120d87574ebd369799d0305e031ee8cca36253149fbe3f', '71927a4f649c55eb2a120d87574ebd369799d0305e031ee8cca36253149fbe3f', NULL, 'اولا يرون انهم يفتنون في كل عام مره او مرتين ثم لا يتوبون ولا هم يذكرون', 11, 21, 83, 1, 2, 207, false, NULL),
    (1362, 'tanzil-uthmani-v1.1', 9, 127, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَىٰكُم مِّنْ أَحَدٍ ثُمَّ ٱنصَرَفُوا۟ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'c5dd4afca382a2cfb9554ac5836f43e489f5c52c6eb4b66aa5187b2e657a7d42', 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَىٰكُم مِّنْ أَحَدٍ ثُمَّ ٱنصَرَفُوا۟ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 'c5dd4afca382a2cfb9554ac5836f43e489f5c52c6eb4b66aa5187b2e657a7d42', 'c5dd4afca382a2cfb9554ac5836f43e489f5c52c6eb4b66aa5187b2e657a7d42', NULL, 'واذا ما انزلت سوره نظر بعضهم الي بعض هل يريكم من احد ثم انصرفوا صرف الله قلوبهم بانهم قوم لا يفقهون', 11, 21, 83, 1, 2, 207, false, NULL),
    (1363, 'tanzil-uthmani-v1.1', 9, 128, 'لَقَدْ جَآءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ', 'b5e59ac9ed25370a6bb55e9cb99a503d9c308147677c661fc7762ecdf808591e', 'لَقَدْ جَآءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ', 'b5e59ac9ed25370a6bb55e9cb99a503d9c308147677c661fc7762ecdf808591e', 'b5e59ac9ed25370a6bb55e9cb99a503d9c308147677c661fc7762ecdf808591e', NULL, 'لقد جاءكم رسول من انفسكم عزيز عليه ما عنتم حريص عليكم بالمؤمنين رءوف رحيم', 11, 21, 83, 1, 2, 207, false, NULL),
    (1364, 'tanzil-uthmani-v1.1', 9, 129, 'فَإِن تَوَلَّوْا۟ فَقُلْ حَسْبِىَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', '9d44094ad2f086d9e4b84520b9aca7b30620edad426c6e189ee8518fcf45fea8', 'فَإِن تَوَلَّوْا۟ فَقُلْ حَسْبِىَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', '9d44094ad2f086d9e4b84520b9aca7b30620edad426c6e189ee8518fcf45fea8', '9d44094ad2f086d9e4b84520b9aca7b30620edad426c6e189ee8518fcf45fea8', NULL, 'فان تولوا فقل حسبي الله لا اله الا هو عليه توكلت وهو رب العرش العظيم', 11, 21, 83, 1, 2, 207, false, NULL),
    (1365, 'tanzil-uthmani-v1.1', 10, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ', '375b99b5ff311333dcbcd3d3b23595d7ab019a072d68438a842258e120c03128', 'الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ', '1255502fc4ff12113f83440479fc590867dba1cac5431dc9613afc56619e1a9f', '1255502fc4ff12113f83440479fc590867dba1cac5431dc9613afc56619e1a9f', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الر تلك ءايت الكتب الحكيم', 11, 21, 83, 1, 3, 208, false, NULL),
    (1366, 'tanzil-uthmani-v1.1', 10, 2, 'أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ قَالَ ٱلْكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٌ مُّبِينٌ', '59ef6ce1069b533005a2b9fea39fd6d22346e3c702b6df848008cb8bb7ecb9a1', 'أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ قَالَ ٱلْكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٌ مُّبِينٌ', '59ef6ce1069b533005a2b9fea39fd6d22346e3c702b6df848008cb8bb7ecb9a1', '59ef6ce1069b533005a2b9fea39fd6d22346e3c702b6df848008cb8bb7ecb9a1', NULL, 'اكان للناس عجبا ان اوحينا الي رجل منهم ان انذر الناس وبشر الذين ءامنوا ان لهم قدم صدق عند ربهم قال الكفرون ان هذا لسحر مبين', 11, 21, 83, 1, 3, 208, false, NULL),
    (1367, 'tanzil-uthmani-v1.1', 10, 3, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُدَبِّرُ ٱلْأَمْرَ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ أَفَلَا تَذَكَّرُونَ', '1222cf7cc0e7759ddc11edf9db3bb99a8e6f9a2f703dc43a52e3124b539b6db4', 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُدَبِّرُ ٱلْأَمْرَ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ أَفَلَا تَذَكَّرُونَ', '1222cf7cc0e7759ddc11edf9db3bb99a8e6f9a2f703dc43a52e3124b539b6db4', '1222cf7cc0e7759ddc11edf9db3bb99a8e6f9a2f703dc43a52e3124b539b6db4', NULL, 'ان ربكم الله الذي خلق السموت والارض في سته ايام ثم استوي علي العرش يدبر الامر ما من شفيع الا من بعد اذنه ذلكم الله ربكم فاعبدوه افلا تذكرون', 11, 21, 83, 1, 3, 208, false, NULL),
    (1368, 'tanzil-uthmani-v1.1', 10, 4, 'إِلَيْهِ مَرْجِعُكُمْ جَمِيعًا وَعْدَ ٱللَّهِ حَقًّا إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ بِٱلْقِسْطِ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', '052346fca1c22abc9c236d03a905e10ca5b4da88fcc24631835802ed37ddcb08', 'إِلَيْهِ مَرْجِعُكُمْ جَمِيعًا وَعْدَ ٱللَّهِ حَقًّا إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ بِٱلْقِسْطِ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', '052346fca1c22abc9c236d03a905e10ca5b4da88fcc24631835802ed37ddcb08', '052346fca1c22abc9c236d03a905e10ca5b4da88fcc24631835802ed37ddcb08', NULL, 'اليه مرجعكم جميعا وعد الله حقا انه يبدؤا الخلق ثم يعيده ليجزي الذين ءامنوا وعملوا الصلحت بالقسط والذين كفروا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون', 11, 21, 83, 1, 3, 208, false, NULL),
    (1369, 'tanzil-uthmani-v1.1', 10, 5, 'هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءً وَٱلْقَمَرَ نُورًا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ يُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', '66cd16acb6f3f32d70fd51e2fbfe8ff59b27f782298c988d757a5990f81069b2', 'هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءً وَٱلْقَمَرَ نُورًا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ يُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ', '66cd16acb6f3f32d70fd51e2fbfe8ff59b27f782298c988d757a5990f81069b2', '66cd16acb6f3f32d70fd51e2fbfe8ff59b27f782298c988d757a5990f81069b2', NULL, 'هو الذي جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب ما خلق الله ذلك الا بالحق يفصل الايت لقوم يعلمون', 11, 21, 83, 1, 3, 208, false, NULL),
    (1370, 'tanzil-uthmani-v1.1', 10, 6, 'إِنَّ فِى ٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَّقُونَ', '43889a308b73cb16509c6e427210c3518cf692bc823a7d3c0b5a7d977a693a1a', 'إِنَّ فِى ٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَّقُونَ', '43889a308b73cb16509c6e427210c3518cf692bc823a7d3c0b5a7d977a693a1a', '43889a308b73cb16509c6e427210c3518cf692bc823a7d3c0b5a7d977a693a1a', NULL, 'ان في اختلف اليل والنهار وما خلق الله في السموت والارض لايت لقوم يتقون', 11, 21, 83, 1, 3, 208, false, NULL),
    (1371, 'tanzil-uthmani-v1.1', 10, 7, 'إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَٰتِنَا غَٰفِلُونَ', '39b9a03358fbbd6d86f958cb23fb95d33a8f504593a84ddb0f03cdf6e424afc5', 'إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَٰتِنَا غَٰفِلُونَ', '39b9a03358fbbd6d86f958cb23fb95d33a8f504593a84ddb0f03cdf6e424afc5', '39b9a03358fbbd6d86f958cb23fb95d33a8f504593a84ddb0f03cdf6e424afc5', NULL, 'ان الذين لا يرجون لقاءنا ورضوا بالحيوه الدنيا واطمانوا بها والذين هم عن ءايتنا غفلون', 11, 21, 83, 1, 3, 209, false, NULL),
    (1372, 'tanzil-uthmani-v1.1', 10, 8, 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ', '6591cfdf43b23e4b7f1eeb491485d45fa862ae44fe202c34e95e2b69ae2785ca', 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ', '6591cfdf43b23e4b7f1eeb491485d45fa862ae44fe202c34e95e2b69ae2785ca', '6591cfdf43b23e4b7f1eeb491485d45fa862ae44fe202c34e95e2b69ae2785ca', NULL, 'اولئك ماويهم النار بما كانوا يكسبون', 11, 21, 83, 1, 3, 209, false, NULL),
    (1373, 'tanzil-uthmani-v1.1', 10, 9, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَٰنِهِمْ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ فِى جَنَّٰتِ ٱلنَّعِيمِ', '411df7a75e88c9af6c2df3dcb6418d49c1f050a8cf83ab2530c1ac387fccd992', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَٰنِهِمْ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ فِى جَنَّٰتِ ٱلنَّعِيمِ', '411df7a75e88c9af6c2df3dcb6418d49c1f050a8cf83ab2530c1ac387fccd992', '411df7a75e88c9af6c2df3dcb6418d49c1f050a8cf83ab2530c1ac387fccd992', NULL, 'ان الذين ءامنوا وعملوا الصلحت يهديهم ربهم بايمنهم تجري من تحتهم الانهر في جنت النعيم', 11, 21, 83, 1, 3, 209, false, NULL),
    (1374, 'tanzil-uthmani-v1.1', 10, 10, 'دَعْوَىٰهُمْ فِيهَا سُبْحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', '7fcf3e73ef3d0b457935771da1cde13362b659e29f45e411f4b90ee81952ebe6', 'دَعْوَىٰهُمْ فِيهَا سُبْحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', '7fcf3e73ef3d0b457935771da1cde13362b659e29f45e411f4b90ee81952ebe6', '7fcf3e73ef3d0b457935771da1cde13362b659e29f45e411f4b90ee81952ebe6', NULL, 'دعويهم فيها سبحنك اللهم وتحيتهم فيها سلم وءاخر دعويهم ان الحمد لله رب العلمين', 11, 21, 83, 1, 3, 209, false, NULL),
    (1375, 'tanzil-uthmani-v1.1', 10, 11, 'وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'c09413cdf3c6f271542192e6e43b890099b1f23ceb0e3db10a3162f4fb92ee67', 'وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 'c09413cdf3c6f271542192e6e43b890099b1f23ceb0e3db10a3162f4fb92ee67', 'c09413cdf3c6f271542192e6e43b890099b1f23ceb0e3db10a3162f4fb92ee67', NULL, 'ولو يعجل الله للناس الشر استعجالهم بالخير لقضي اليهم اجلهم فنذر الذين لا يرجون لقاءنا في طغينهم يعمهون', 11, 21, 84, 1, 3, 209, false, NULL),
    (1376, 'tanzil-uthmani-v1.1', 10, 12, 'وَإِذَا مَسَّ ٱلْإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّ مَّسَّهُۥ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ', '52a951ea52bdf0b6a2b97bb7f010ec2141605b6a13f4c0e4bef65de5c4caa0de', 'وَإِذَا مَسَّ ٱلْإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّ مَّسَّهُۥ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ', '52a951ea52bdf0b6a2b97bb7f010ec2141605b6a13f4c0e4bef65de5c4caa0de', '52a951ea52bdf0b6a2b97bb7f010ec2141605b6a13f4c0e4bef65de5c4caa0de', NULL, 'واذا مس الانسن الضر دعانا لجنبه او قاعدا او قائما فلما كشفنا عنه ضره مر كان لم يدعنا الي ضر مسه كذلك زين للمسرفين ما كانوا يعملون', 11, 21, 84, 1, 3, 209, false, NULL),
    (1377, 'tanzil-uthmani-v1.1', 10, 13, 'وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', '45f4753d9c55687f0b7331e7c9652bb93670aeabd094c583a3b4d40ecd0ae63f', 'وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', '45f4753d9c55687f0b7331e7c9652bb93670aeabd094c583a3b4d40ecd0ae63f', '45f4753d9c55687f0b7331e7c9652bb93670aeabd094c583a3b4d40ecd0ae63f', NULL, 'ولقد اهلكنا القرون من قبلكم لما ظلموا وجاءتهم رسلهم بالبينت وما كانوا ليؤمنوا كذلك نجزي القوم المجرمين', 11, 21, 84, 1, 3, 209, false, NULL),
    (1378, 'tanzil-uthmani-v1.1', 10, 14, 'ثُمَّ جَعَلْنَٰكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ', 'ee862641ed84041d51355d30b053d665b894cf274a44f9b1162240ce16639edb', 'ثُمَّ جَعَلْنَٰكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ', 'ee862641ed84041d51355d30b053d665b894cf274a44f9b1162240ce16639edb', 'ee862641ed84041d51355d30b053d665b894cf274a44f9b1162240ce16639edb', NULL, 'ثم جعلنكم خلئف في الارض من بعدهم لننظر كيف تعملون', 11, 21, 84, 1, 3, 209, false, NULL),
    (1379, 'tanzil-uthmani-v1.1', 10, 15, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَٰذَآ أَوْ بَدِّلْهُ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'be90e8d1f6227a53ffa40cd78b182d8dcf9c969b6e3e70dad8399fcfd0a2d876', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَٰذَآ أَوْ بَدِّلْهُ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'be90e8d1f6227a53ffa40cd78b182d8dcf9c969b6e3e70dad8399fcfd0a2d876', 'be90e8d1f6227a53ffa40cd78b182d8dcf9c969b6e3e70dad8399fcfd0a2d876', NULL, 'واذا تتلي عليهم ءاياتنا بينت قال الذين لا يرجون لقاءنا ائت بقرءان غير هذا او بدله قل ما يكون لي ان ابدله من تلقائ نفسي ان اتبع الا ما يوحي الي اني اخاف ان عصيت ربي عذاب يوم عظيم', 11, 21, 84, 1, 3, 210, false, NULL),
    (1380, 'tanzil-uthmani-v1.1', 10, 16, 'قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِۦٓ أَفَلَا تَعْقِلُونَ', 'eeec9d05906e82a948f2094a6efe92928e1c5e0dbfb32d290f8afb48eccc652a', 'قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِۦٓ أَفَلَا تَعْقِلُونَ', 'eeec9d05906e82a948f2094a6efe92928e1c5e0dbfb32d290f8afb48eccc652a', 'eeec9d05906e82a948f2094a6efe92928e1c5e0dbfb32d290f8afb48eccc652a', NULL, 'قل لو شاء الله ما تلوته عليكم ولا ادريكم به فقد لبثت فيكم عمرا من قبله افلا تعقلون', 11, 21, 84, 1, 3, 210, false, NULL),
    (1381, 'tanzil-uthmani-v1.1', 10, 17, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ', 'f435d3ba64d3ca7e5501f696da5ee7858b19069e8c54f66378383d16a9b575fb', 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ', 'f435d3ba64d3ca7e5501f696da5ee7858b19069e8c54f66378383d16a9b575fb', 'f435d3ba64d3ca7e5501f696da5ee7858b19069e8c54f66378383d16a9b575fb', NULL, 'فمن اظلم ممن افتري علي الله كذبا او كذب بايته انه لا يفلح المجرمون', 11, 21, 84, 1, 3, 210, false, NULL),
    (1382, 'tanzil-uthmani-v1.1', 10, 18, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '978e318d310fc7fdd81c5849e8fcdb4008e30ae608fd55ae3f44d263d2ce2fc4', 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '978e318d310fc7fdd81c5849e8fcdb4008e30ae608fd55ae3f44d263d2ce2fc4', '978e318d310fc7fdd81c5849e8fcdb4008e30ae608fd55ae3f44d263d2ce2fc4', NULL, 'ويعبدون من دون الله ما لا يضرهم ولا ينفعهم ويقولون هؤلاء شفعؤنا عند الله قل اتنبون الله بما لا يعلم في السموت ولا في الارض سبحنه وتعلي عما يشركون', 11, 21, 84, 1, 3, 210, false, NULL),
    (1383, 'tanzil-uthmani-v1.1', 10, 19, 'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةً وَٰحِدَةً فَٱخْتَلَفُوا۟ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ', 'cee07a7243b9bfa75e3bfba6fdb371e65e9f079d37b4f9aef336ed82527a3d54', 'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةً وَٰحِدَةً فَٱخْتَلَفُوا۟ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ', 'cee07a7243b9bfa75e3bfba6fdb371e65e9f079d37b4f9aef336ed82527a3d54', 'cee07a7243b9bfa75e3bfba6fdb371e65e9f079d37b4f9aef336ed82527a3d54', NULL, 'وما كان الناس الا امه وحده فاختلفوا ولولا كلمه سبقت من ربك لقضي بينهم فيما فيه يختلفون', 11, 21, 84, 1, 3, 210, false, NULL),
    (1384, 'tanzil-uthmani-v1.1', 10, 20, 'وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'a048d5e714560e56b2e5a94bbdb06f5daec11b82c91cca9656bbc50d594348da', 'وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 'a048d5e714560e56b2e5a94bbdb06f5daec11b82c91cca9656bbc50d594348da', 'a048d5e714560e56b2e5a94bbdb06f5daec11b82c91cca9656bbc50d594348da', NULL, 'ويقولون لولا انزل عليه ءايه من ربه فقل انما الغيب لله فانتظروا اني معكم من المنتظرين', 11, 21, 84, 1, 3, 210, false, NULL),
    (1385, 'tanzil-uthmani-v1.1', 10, 21, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌ فِىٓ ءَايَاتِنَا قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ', '4fe61dad9d6d8e2da9c2de465589e9ede67fddd7650b0790f2de8a7b37d86e1b', 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌ فِىٓ ءَايَاتِنَا قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ', '4fe61dad9d6d8e2da9c2de465589e9ede67fddd7650b0790f2de8a7b37d86e1b', '4fe61dad9d6d8e2da9c2de465589e9ede67fddd7650b0790f2de8a7b37d86e1b', NULL, 'واذا اذقنا الناس رحمه من بعد ضراء مستهم اذا لهم مكر في ءاياتنا قل الله اسرع مكرا ان رسلنا يكتبون ما تمكرون', 11, 21, 84, 1, 3, 211, false, NULL),
    (1386, 'tanzil-uthmani-v1.1', 10, 22, 'هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'd1e4f8217ec3d76bfc9c5700949c5bc40a5cc27af7ae1666e1369fce6637902a', 'هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 'd1e4f8217ec3d76bfc9c5700949c5bc40a5cc27af7ae1666e1369fce6637902a', 'd1e4f8217ec3d76bfc9c5700949c5bc40a5cc27af7ae1666e1369fce6637902a', NULL, 'هو الذي يسيركم في البر والبحر حتي اذا كنتم في الفلك وجرين بهم بريح طيبه وفرحوا بها جاءتها ريح عاصف وجاءهم الموج من كل مكان وظنوا انهم احيط بهم دعوا الله مخلصين له الدين لئن انجيتنا من هذه لنكونن من الشكرين', 11, 21, 84, 1, 3, 211, false, NULL),
    (1387, 'tanzil-uthmani-v1.1', 10, 23, 'فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم مَّتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '002c320c5a527e84a49fa57109dcc9ff1e7672d27ea19811b3a5ccf66c577ec1', 'فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم مَّتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '002c320c5a527e84a49fa57109dcc9ff1e7672d27ea19811b3a5ccf66c577ec1', '002c320c5a527e84a49fa57109dcc9ff1e7672d27ea19811b3a5ccf66c577ec1', NULL, 'فلما انجيهم اذا هم يبغون في الارض بغير الحق يايها الناس انما بغيكم علي انفسكم متع الحيوه الدنيا ثم الينا مرجعكم فننبئكم بما كنتم تعملون', 11, 21, 84, 1, 3, 211, false, NULL),
    (1388, 'tanzil-uthmani-v1.1', 10, 24, 'إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَٰهَا حَصِيدًا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَتَفَكَّرُونَ', '81a327bc28a43393d0f5f6cfec3d7e1bc83cee75f4cc1cae7422929f6b3f1151', 'إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَٰهَا حَصِيدًا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَتَفَكَّرُونَ', '81a327bc28a43393d0f5f6cfec3d7e1bc83cee75f4cc1cae7422929f6b3f1151', '81a327bc28a43393d0f5f6cfec3d7e1bc83cee75f4cc1cae7422929f6b3f1151', NULL, 'انما مثل الحيوه الدنيا كماء انزلنه من السماء فاختلط به نبات الارض مما ياكل الناس والانعم حتي اذا اخذت الارض زخرفها وازينت وظن اهلها انهم قدرون عليها اتيها امرنا ليلا او نهارا فجعلنها حصيدا كان لم تغن بالامس كذلك نفصل الايت لقوم يتفكرون', 11, 21, 84, 1, 3, 211, false, NULL),
    (1389, 'tanzil-uthmani-v1.1', 10, 25, 'وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '1ce50ffefc8ebaa43402500d09731c50ab162c50e60617f4f5b5789b5612c28f', 'وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '1ce50ffefc8ebaa43402500d09731c50ab162c50e60617f4f5b5789b5612c28f', '1ce50ffefc8ebaa43402500d09731c50ab162c50e60617f4f5b5789b5612c28f', NULL, 'والله يدعوا الي دار السلم ويهدي من يشاء الي صرط مستقيم', 11, 21, 84, 1, 3, 211, false, NULL),
    (1390, 'tanzil-uthmani-v1.1', 10, 26, 'لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', '53338771a4282bfc1edf5028b7514ba27cecfa9c77a3648ff78bb461279e6f42', 'لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلَا ذِلَّةٌ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', '53338771a4282bfc1edf5028b7514ba27cecfa9c77a3648ff78bb461279e6f42', '53338771a4282bfc1edf5028b7514ba27cecfa9c77a3648ff78bb461279e6f42', NULL, 'للذين احسنوا الحسني وزياده ولا يرهق وجوههم قتر ولا ذله اولئك اصحب الجنه هم فيها خلدون', 11, 22, 85, 1, 3, 212, false, NULL),
    (1391, 'tanzil-uthmani-v1.1', 10, 27, 'وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًا مِّنَ ٱلَّيْلِ مُظْلِمًا أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'a4a1ec498872741cb555d307452c204d37021fca1f5f870d5f74ab50e8adbca9', 'وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًا مِّنَ ٱلَّيْلِ مُظْلِمًا أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', 'a4a1ec498872741cb555d307452c204d37021fca1f5f870d5f74ab50e8adbca9', 'a4a1ec498872741cb555d307452c204d37021fca1f5f870d5f74ab50e8adbca9', NULL, 'والذين كسبوا السيات جزاء سيئه بمثلها وترهقهم ذله ما لهم من الله من عاصم كانما اغشيت وجوههم قطعا من اليل مظلما اولئك اصحب النار هم فيها خلدون', 11, 22, 85, 1, 3, 212, false, NULL),
    (1392, 'tanzil-uthmani-v1.1', 10, 28, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ فَزَيَّلْنَا بَيْنَهُمْ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ', 'a8c7f9d4394e5a25ac8e19a344c2ff284bbee0f8a55f923617662b645c7ad05e', 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ فَزَيَّلْنَا بَيْنَهُمْ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ', 'a8c7f9d4394e5a25ac8e19a344c2ff284bbee0f8a55f923617662b645c7ad05e', 'a8c7f9d4394e5a25ac8e19a344c2ff284bbee0f8a55f923617662b645c7ad05e', NULL, 'ويوم نحشرهم جميعا ثم نقول للذين اشركوا مكانكم انتم وشركاؤكم فزيلنا بينهم وقال شركاؤهم ما كنتم ايانا تعبدون', 11, 22, 85, 1, 3, 212, false, NULL),
    (1393, 'tanzil-uthmani-v1.1', 10, 29, 'فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَٰفِلِينَ', '866ec6df17333143e9ecf773ef6a403b99527b05e4d5c04f5b4933fe8e45f806', 'فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَٰفِلِينَ', '866ec6df17333143e9ecf773ef6a403b99527b05e4d5c04f5b4933fe8e45f806', '866ec6df17333143e9ecf773ef6a403b99527b05e4d5c04f5b4933fe8e45f806', NULL, 'فكفي بالله شهيدا بيننا وبينكم ان كنا عن عبادتكم لغفلين', 11, 22, 85, 1, 3, 212, false, NULL),
    (1394, 'tanzil-uthmani-v1.1', 10, 30, 'هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍ مَّآ أَسْلَفَتْ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '0188a61873b0bdb82b4c9a5f7646ef61e347e8211a4b88803d8e2450cc54c9bf', 'هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍ مَّآ أَسْلَفَتْ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '0188a61873b0bdb82b4c9a5f7646ef61e347e8211a4b88803d8e2450cc54c9bf', '0188a61873b0bdb82b4c9a5f7646ef61e347e8211a4b88803d8e2450cc54c9bf', NULL, 'هنالك تبلوا كل نفس ما اسلفت وردوا الي الله موليهم الحق وضل عنهم ما كانوا يفترون', 11, 22, 85, 1, 3, 212, false, NULL),
    (1395, 'tanzil-uthmani-v1.1', 10, 31, 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ فَسَيَقُولُونَ ٱللَّهُ فَقُلْ أَفَلَا تَتَّقُونَ', 'f0c86c6bd5d1be05e03f8ec19c39f7e870d4612427af33bc0a5f85cf285003fe', 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ فَسَيَقُولُونَ ٱللَّهُ فَقُلْ أَفَلَا تَتَّقُونَ', 'f0c86c6bd5d1be05e03f8ec19c39f7e870d4612427af33bc0a5f85cf285003fe', 'f0c86c6bd5d1be05e03f8ec19c39f7e870d4612427af33bc0a5f85cf285003fe', NULL, 'قل من يرزقكم من السماء والارض امن يملك السمع والابصر ومن يخرج الحي من الميت ويخرج الميت من الحي ومن يدبر الامر فسيقولون الله فقل افلا تتقون', 11, 22, 85, 1, 3, 212, false, NULL),
    (1396, 'tanzil-uthmani-v1.1', 10, 32, 'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَٰلُ فَأَنَّىٰ تُصْرَفُونَ', '74abeb55d5a1dc838e81e64a690fce6ad3551047715abee9380329d4105f89a3', 'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَٰلُ فَأَنَّىٰ تُصْرَفُونَ', '74abeb55d5a1dc838e81e64a690fce6ad3551047715abee9380329d4105f89a3', '74abeb55d5a1dc838e81e64a690fce6ad3551047715abee9380329d4105f89a3', NULL, 'فذلكم الله ربكم الحق فماذا بعد الحق الا الضلل فاني تصرفون', 11, 22, 85, 1, 3, 212, false, NULL),
    (1397, 'tanzil-uthmani-v1.1', 10, 33, 'كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ', '4353ddf576263fa9b3c8c9f9328bf778c96a24b5e246277199023679bb7a2b58', 'كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ', '4353ddf576263fa9b3c8c9f9328bf778c96a24b5e246277199023679bb7a2b58', '4353ddf576263fa9b3c8c9f9328bf778c96a24b5e246277199023679bb7a2b58', NULL, 'كذلك حقت كلمت ربك علي الذين فسقوا انهم لا يؤمنون', 11, 22, 85, 1, 3, 212, false, NULL),
    (1398, 'tanzil-uthmani-v1.1', 10, 34, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ فَأَنَّىٰ تُؤْفَكُونَ', 'f3266f53d60bac30b53e244bf3bccf8abfc6b78dfbd3897ae89c79737aec9daa', 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ فَأَنَّىٰ تُؤْفَكُونَ', 'f3266f53d60bac30b53e244bf3bccf8abfc6b78dfbd3897ae89c79737aec9daa', 'f3266f53d60bac30b53e244bf3bccf8abfc6b78dfbd3897ae89c79737aec9daa', NULL, 'قل هل من شركائكم من يبدؤا الخلق ثم يعيده قل الله يبدؤا الخلق ثم يعيده فاني تؤفكون', 11, 22, 85, 1, 3, 213, false, NULL),
    (1399, 'tanzil-uthmani-v1.1', 10, 35, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ', '621334b9bcb271509f0420ea264a4245aed28f881c7285318d274803b9d0196e', 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ', '621334b9bcb271509f0420ea264a4245aed28f881c7285318d274803b9d0196e', '621334b9bcb271509f0420ea264a4245aed28f881c7285318d274803b9d0196e', NULL, 'قل هل من شركائكم من يهدي الي الحق قل الله يهدي للحق افمن يهدي الي الحق احق ان يتبع امن لا يهدي الا ان يهدي فما لكم كيف تحكمون', 11, 22, 85, 1, 3, 213, false, NULL),
    (1400, 'tanzil-uthmani-v1.1', 10, 36, 'وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 'f89fe0a70aaf659a79e04a420582f0cdd3ca73af7eb65ee61672f190d4c5f240', 'وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 'f89fe0a70aaf659a79e04a420582f0cdd3ca73af7eb65ee61672f190d4c5f240', 'f89fe0a70aaf659a79e04a420582f0cdd3ca73af7eb65ee61672f190d4c5f240', NULL, 'وما يتبع اكثرهم الا ظنا ان الظن لا يغني من الحق شيا ان الله عليم بما يفعلون', 11, 22, 85, 1, 3, 213, false, NULL),
    (1401, 'tanzil-uthmani-v1.1', 10, 37, 'وَمَا كَانَ هَٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', '7a8b51cab8cf96f5bc5af37316393b8b5bc2d8b44b20efef6b6fb2d97a744bca', 'وَمَا كَانَ هَٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', '7a8b51cab8cf96f5bc5af37316393b8b5bc2d8b44b20efef6b6fb2d97a744bca', '7a8b51cab8cf96f5bc5af37316393b8b5bc2d8b44b20efef6b6fb2d97a744bca', NULL, 'وما كان هذا القرءان ان يفتري من دون الله ولكن تصديق الذي بين يديه وتفصيل الكتب لا ريب فيه من رب العلمين', 11, 22, 85, 1, 3, 213, false, NULL),
    (1402, 'tanzil-uthmani-v1.1', 10, 38, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ فَأْتُوا۟ بِسُورَةٍ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'ed3dca48929d77fa6bf8009d3078fcd470a096014dd7b6de16cc5ea73c35fe2b', 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ فَأْتُوا۟ بِسُورَةٍ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'ed3dca48929d77fa6bf8009d3078fcd470a096014dd7b6de16cc5ea73c35fe2b', 'ed3dca48929d77fa6bf8009d3078fcd470a096014dd7b6de16cc5ea73c35fe2b', NULL, 'ام يقولون افتريه قل فاتوا بسوره مثله وادعوا من استطعتم من دون الله ان كنتم صدقين', 11, 22, 85, 1, 3, 213, false, NULL),
    (1403, 'tanzil-uthmani-v1.1', 10, 39, 'بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'c4321ee38d7ca401de8daf3199499081807eba0397553c8f4f739a9cbab310bf', 'بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'c4321ee38d7ca401de8daf3199499081807eba0397553c8f4f739a9cbab310bf', 'c4321ee38d7ca401de8daf3199499081807eba0397553c8f4f739a9cbab310bf', NULL, 'بل كذبوا بما لم يحيطوا بعلمه ولما ياتهم تاويله كذلك كذب الذين من قبلهم فانظر كيف كان عقبه الظلمين', 11, 22, 85, 1, 3, 213, false, NULL),
    (1404, 'tanzil-uthmani-v1.1', 10, 40, 'وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ', 'c7657d4869e79131758ea8534e290c96b5a8103126d0dbcfa9a51cf0b665ce5f', 'وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ', 'c7657d4869e79131758ea8534e290c96b5a8103126d0dbcfa9a51cf0b665ce5f', 'c7657d4869e79131758ea8534e290c96b5a8103126d0dbcfa9a51cf0b665ce5f', NULL, 'ومنهم من يؤمن به ومنهم من لا يؤمن به وربك اعلم بالمفسدين', 11, 22, 85, 1, 3, 213, false, NULL),
    (1405, 'tanzil-uthmani-v1.1', 10, 41, 'وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌ مِّمَّا تَعْمَلُونَ', 'a75f1923064c0220d7fe2ee8b7d80582806b3d0912b0f3a7df77c7430648ea13', 'وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌ مِّمَّا تَعْمَلُونَ', 'a75f1923064c0220d7fe2ee8b7d80582806b3d0912b0f3a7df77c7430648ea13', 'a75f1923064c0220d7fe2ee8b7d80582806b3d0912b0f3a7df77c7430648ea13', NULL, 'وان كذبوك فقل لي عملي ولكم عملكم انتم بريون مما اعمل وانا بريء مما تعملون', 11, 22, 85, 1, 3, 213, false, NULL),
    (1406, 'tanzil-uthmani-v1.1', 10, 42, 'وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ', 'e7c237ce841a3628a975a74fba4025fb0b7c00a507059ad0f1deadc76b44f38e', 'وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ', 'e7c237ce841a3628a975a74fba4025fb0b7c00a507059ad0f1deadc76b44f38e', 'e7c237ce841a3628a975a74fba4025fb0b7c00a507059ad0f1deadc76b44f38e', NULL, 'ومنهم من يستمعون اليك افانت تسمع الصم ولو كانوا لا يعقلون', 11, 22, 85, 1, 3, 213, false, NULL),
    (1407, 'tanzil-uthmani-v1.1', 10, 43, 'وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ', '8c0c1f16082a2e000eecba5909293bb1df6ce925e5de68a5f3d7c2e1c1571f7b', 'وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ', '8c0c1f16082a2e000eecba5909293bb1df6ce925e5de68a5f3d7c2e1c1571f7b', '8c0c1f16082a2e000eecba5909293bb1df6ce925e5de68a5f3d7c2e1c1571f7b', NULL, 'ومنهم من ينظر اليك افانت تهدي العمي ولو كانوا لا يبصرون', 11, 22, 85, 1, 3, 214, false, NULL),
    (1408, 'tanzil-uthmani-v1.1', 10, 44, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًٔا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ', '80dc1df8f7352c6eaafe9ae558973045084987b961d3ac033b0ea03fe99849e3', 'إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًٔا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ', '80dc1df8f7352c6eaafe9ae558973045084987b961d3ac033b0ea03fe99849e3', '80dc1df8f7352c6eaafe9ae558973045084987b961d3ac033b0ea03fe99849e3', NULL, 'ان الله لا يظلم الناس شيا ولكن الناس انفسهم يظلمون', 11, 22, 85, 1, 3, 214, false, NULL),
    (1409, 'tanzil-uthmani-v1.1', 10, 45, 'وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ', '934f8a3b36b3d2fd669a79d5653f19003e90cf1a50e6661f10450984657d6de5', 'وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ', '934f8a3b36b3d2fd669a79d5653f19003e90cf1a50e6661f10450984657d6de5', '934f8a3b36b3d2fd669a79d5653f19003e90cf1a50e6661f10450984657d6de5', NULL, 'ويوم يحشرهم كان لم يلبثوا الا ساعه من النهار يتعارفون بينهم قد خسر الذين كذبوا بلقاء الله وما كانوا مهتدين', 11, 22, 85, 1, 3, 214, false, NULL),
    (1410, 'tanzil-uthmani-v1.1', 10, 46, 'وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ', '9c5f4010bb335d7210d79deed0b4f7a208ccec42577856b7b29cf28ea941812d', 'وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ', '9c5f4010bb335d7210d79deed0b4f7a208ccec42577856b7b29cf28ea941812d', '9c5f4010bb335d7210d79deed0b4f7a208ccec42577856b7b29cf28ea941812d', NULL, 'واما نرينك بعض الذي نعدهم او نتوفينك فالينا مرجعهم ثم الله شهيد علي ما يفعلون', 11, 22, 85, 1, 3, 214, false, NULL),
    (1411, 'tanzil-uthmani-v1.1', 10, 47, 'وَلِكُلِّ أُمَّةٍ رَّسُولٌ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', '59009ae9ea7abbf94f310111632207d3d4115f3c1e1f198e195fba97cba9a180', 'وَلِكُلِّ أُمَّةٍ رَّسُولٌ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', '59009ae9ea7abbf94f310111632207d3d4115f3c1e1f198e195fba97cba9a180', '59009ae9ea7abbf94f310111632207d3d4115f3c1e1f198e195fba97cba9a180', NULL, 'ولكل امه رسول فاذا جاء رسولهم قضي بينهم بالقسط وهم لا يظلمون', 11, 22, 85, 1, 3, 214, false, NULL),
    (1412, 'tanzil-uthmani-v1.1', 10, 48, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', NULL, 'ويقولون متي هذا الوعد ان كنتم صدقين', 11, 22, 85, 1, 3, 214, false, NULL),
    (1413, 'tanzil-uthmani-v1.1', 10, 49, 'قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ لِكُلِّ أُمَّةٍ أَجَلٌ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'a024262d3980c5290180e0d2913bf487d8e18b88aa98ca5ce66118cc32933a3d', 'قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ لِكُلِّ أُمَّةٍ أَجَلٌ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', 'a024262d3980c5290180e0d2913bf487d8e18b88aa98ca5ce66118cc32933a3d', 'a024262d3980c5290180e0d2913bf487d8e18b88aa98ca5ce66118cc32933a3d', NULL, 'قل لا املك لنفسي ضرا ولا نفعا الا ما شاء الله لكل امه اجل اذا جاء اجلهم فلا يستخرون ساعه ولا يستقدمون', 11, 22, 85, 1, 3, 214, false, NULL),
    (1414, 'tanzil-uthmani-v1.1', 10, 50, 'قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَٰتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ', 'c4081517557350ef162f29876c9afb60c1636ee960d27a54df4d89bef7e793d1', 'قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَٰتًا أَوْ نَهَارًا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ', 'c4081517557350ef162f29876c9afb60c1636ee960d27a54df4d89bef7e793d1', 'c4081517557350ef162f29876c9afb60c1636ee960d27a54df4d89bef7e793d1', NULL, 'قل ارءيتم ان اتيكم عذابه بيتا او نهارا ماذا يستعجل منه المجرمون', 11, 22, 85, 1, 3, 214, false, NULL),
    (1415, 'tanzil-uthmani-v1.1', 10, 51, 'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ءَآلْـَٰٔنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 'cae1be5921ec3f8790e7e30b5d2d94f558325e3a256c72f353a470cf046070b6', 'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ءَآلْـَٰٔنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 'cae1be5921ec3f8790e7e30b5d2d94f558325e3a256c72f353a470cf046070b6', 'cae1be5921ec3f8790e7e30b5d2d94f558325e3a256c72f353a470cf046070b6', NULL, 'اثم اذا ما وقع ءامنتم به ءالن وقد كنتم به تستعجلون', 11, 22, 85, 1, 3, 214, false, NULL),
    (1416, 'tanzil-uthmani-v1.1', 10, 52, 'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ', '4c555d307890b5143ed4d81503b7fe42389f2a85230af16467bdf98119c3c9a4', 'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ', '4c555d307890b5143ed4d81503b7fe42389f2a85230af16467bdf98119c3c9a4', '4c555d307890b5143ed4d81503b7fe42389f2a85230af16467bdf98119c3c9a4', NULL, 'ثم قيل للذين ظلموا ذوقوا عذاب الخلد هل تجزون الا بما كنتم تكسبون', 11, 22, 85, 1, 3, 214, false, NULL),
    (1417, 'tanzil-uthmani-v1.1', 10, 53, 'وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّ وَمَآ أَنتُم بِمُعْجِزِينَ', 'f3a6dfe87ba43889579ddeae03f67ed01f870b97b491a750688f44895ed6353e', 'وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّ وَمَآ أَنتُم بِمُعْجِزِينَ', 'f3a6dfe87ba43889579ddeae03f67ed01f870b97b491a750688f44895ed6353e', 'f3a6dfe87ba43889579ddeae03f67ed01f870b97b491a750688f44895ed6353e', NULL, 'ويستنبونك احق هو قل اي وربي انه لحق وما انتم بمعجزين', 11, 22, 86, 1, 3, 214, false, NULL),
    (1418, 'tanzil-uthmani-v1.1', 10, 54, 'وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', '92cef91d9cced93bc350d5ee440c68a326fe62b7ab1bb739b46abd188f212f8d', 'وَلَوْ أَنَّ لِكُلِّ نَفْسٍ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', '92cef91d9cced93bc350d5ee440c68a326fe62b7ab1bb739b46abd188f212f8d', '92cef91d9cced93bc350d5ee440c68a326fe62b7ab1bb739b46abd188f212f8d', NULL, 'ولو ان لكل نفس ظلمت ما في الارض لافتدت به واسروا الندامه لما راوا العذاب وقضي بينهم بالقسط وهم لا يظلمون', 11, 22, 86, 1, 3, 215, false, NULL),
    (1419, 'tanzil-uthmani-v1.1', 10, 55, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '91c2615386678781c98d61bb5a967877b3f055eab473044c6fe1303ab68780a6', 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '91c2615386678781c98d61bb5a967877b3f055eab473044c6fe1303ab68780a6', '91c2615386678781c98d61bb5a967877b3f055eab473044c6fe1303ab68780a6', NULL, 'الا ان لله ما في السموت والارض الا ان وعد الله حق ولكن اكثرهم لا يعلمون', 11, 22, 86, 1, 3, 215, false, NULL),
    (1420, 'tanzil-uthmani-v1.1', 10, 56, 'هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ', 'a1c0ad2103c2074aa7574630e2417f7fb635daaafe2f0b9555b7370910675888', 'هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ', 'a1c0ad2103c2074aa7574630e2417f7fb635daaafe2f0b9555b7370910675888', 'a1c0ad2103c2074aa7574630e2417f7fb635daaafe2f0b9555b7370910675888', NULL, 'هو يحي ويميت واليه ترجعون', 11, 22, 86, 1, 3, 215, false, NULL),
    (1421, 'tanzil-uthmani-v1.1', 10, 57, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَآءٌ لِّمَا فِى ٱلصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', '7f89f97d03637d2d8462de2de60916bffe5f47be01ad15fea928e4c89cf17988', 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَآءٌ لِّمَا فِى ٱلصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', '7f89f97d03637d2d8462de2de60916bffe5f47be01ad15fea928e4c89cf17988', '7f89f97d03637d2d8462de2de60916bffe5f47be01ad15fea928e4c89cf17988', NULL, 'يايها الناس قد جاءتكم موعظه من ربكم وشفاء لما في الصدور وهدي ورحمه للمؤمنين', 11, 22, 86, 1, 3, 215, false, NULL),
    (1422, 'tanzil-uthmani-v1.1', 10, 58, 'قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ', '85122836db518e71f79e3061fbf3997f3c705853a630c31a5128c66fde7910ce', 'قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ', '85122836db518e71f79e3061fbf3997f3c705853a630c31a5128c66fde7910ce', '85122836db518e71f79e3061fbf3997f3c705853a630c31a5128c66fde7910ce', NULL, 'قل بفضل الله وبرحمته فبذلك فليفرحوا هو خير مما يجمعون', 11, 22, 86, 1, 3, 215, false, NULL),
    (1423, 'tanzil-uthmani-v1.1', 10, 59, 'قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَٰلًا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ', '753360a7ef53ec6a5d26a1a6b3762d17d7f2b13ec188d57cd1a5efd35803cda5', 'قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍ فَجَعَلْتُم مِّنْهُ حَرَامًا وَحَلَٰلًا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ', '753360a7ef53ec6a5d26a1a6b3762d17d7f2b13ec188d57cd1a5efd35803cda5', '753360a7ef53ec6a5d26a1a6b3762d17d7f2b13ec188d57cd1a5efd35803cda5', NULL, 'قل ارءيتم ما انزل الله لكم من رزق فجعلتم منه حراما وحللا قل ءالله اذن لكم ام علي الله تفترون', 11, 22, 86, 1, 3, 215, false, NULL),
    (1424, 'tanzil-uthmani-v1.1', 10, 60, 'وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', '09f6eca44ad5d13812b2849de59ad0bc18d3f089da1b75d271fe8cfefd0eb7fc', 'وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', '09f6eca44ad5d13812b2849de59ad0bc18d3f089da1b75d271fe8cfefd0eb7fc', '09f6eca44ad5d13812b2849de59ad0bc18d3f089da1b75d271fe8cfefd0eb7fc', NULL, 'وما ظن الذين يفترون علي الله الكذب يوم القيمه ان الله لذو فضل علي الناس ولكن اكثرهم لا يشكرون', 11, 22, 86, 1, 3, 215, false, NULL),
    (1425, 'tanzil-uthmani-v1.1', 10, 61, 'وَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', 'c6f1ca16ff8a3670d1d674dda6284d91fdf63efca931bab5e7654c2b6c6b9d2a', 'وَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', 'c6f1ca16ff8a3670d1d674dda6284d91fdf63efca931bab5e7654c2b6c6b9d2a', 'c6f1ca16ff8a3670d1d674dda6284d91fdf63efca931bab5e7654c2b6c6b9d2a', NULL, 'وما تكون في شان وما تتلوا منه من قرءان ولا تعملون من عمل الا كنا عليكم شهودا اذ تفيضون فيه وما يعزب عن ربك من مثقال ذره في الارض ولا في السماء ولا اصغر من ذلك ولا اكبر الا في كتب مبين', 11, 22, 86, 1, 3, 215, false, NULL),
    (1426, 'tanzil-uthmani-v1.1', 10, 62, 'أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '1e83946af8105593e7a6d1f614e986a33135d918a23e068f43ea9540366076dd', 'أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '1e83946af8105593e7a6d1f614e986a33135d918a23e068f43ea9540366076dd', '1e83946af8105593e7a6d1f614e986a33135d918a23e068f43ea9540366076dd', NULL, 'الا ان اولياء الله لا خوف عليهم ولا هم يحزنون', 11, 22, 86, 1, 3, 216, false, NULL),
    (1427, 'tanzil-uthmani-v1.1', 10, 63, 'ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'ff1ecbf248d8dde100afa2eb8907f1858eecba204456f6af874104460ccc294f', 'ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 'ff1ecbf248d8dde100afa2eb8907f1858eecba204456f6af874104460ccc294f', 'ff1ecbf248d8dde100afa2eb8907f1858eecba204456f6af874104460ccc294f', NULL, 'الذين ءامنوا وكانوا يتقون', 11, 22, 86, 1, 3, 216, false, NULL),
    (1428, 'tanzil-uthmani-v1.1', 10, 64, 'لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ لَا تَبْدِيلَ لِكَلِمَٰتِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '41988d4affa212bb87a3671983ec3e8411d4f1f8e7e4b452e5d5971311d4b905', 'لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ لَا تَبْدِيلَ لِكَلِمَٰتِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '41988d4affa212bb87a3671983ec3e8411d4f1f8e7e4b452e5d5971311d4b905', '41988d4affa212bb87a3671983ec3e8411d4f1f8e7e4b452e5d5971311d4b905', NULL, 'لهم البشري في الحيوه الدنيا وفي الاخره لا تبديل لكلمت الله ذلك هو الفوز العظيم', 11, 22, 86, 1, 3, 216, false, NULL),
    (1429, 'tanzil-uthmani-v1.1', 10, 65, 'وَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'e741f1069981e8962f8436c79c0507e8ecad9f53aa2cd99d80f232159a847cbc', 'وَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'e741f1069981e8962f8436c79c0507e8ecad9f53aa2cd99d80f232159a847cbc', 'e741f1069981e8962f8436c79c0507e8ecad9f53aa2cd99d80f232159a847cbc', NULL, 'ولا يحزنك قولهم ان العزه لله جميعا هو السميع العليم', 11, 22, 86, 1, 3, 216, false, NULL),
    (1430, 'tanzil-uthmani-v1.1', 10, 66, 'أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', '92607a619c80af1123346d54c5c481cfaa5df9cd0fcad45e29cb2cd07761ba1e', 'أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', '92607a619c80af1123346d54c5c481cfaa5df9cd0fcad45e29cb2cd07761ba1e', '92607a619c80af1123346d54c5c481cfaa5df9cd0fcad45e29cb2cd07761ba1e', NULL, 'الا ان لله من في السموت ومن في الارض وما يتبع الذين يدعون من دون الله شركاء ان يتبعون الا الظن وان هم الا يخرصون', 11, 22, 86, 1, 3, 216, false, NULL),
    (1431, 'tanzil-uthmani-v1.1', 10, 67, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ', '91b09a5f3d2f00c7c72c3cc396a3912cb2e8d7bde713d4ced7da6f970d130e34', 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ', '91b09a5f3d2f00c7c72c3cc396a3912cb2e8d7bde713d4ced7da6f970d130e34', '91b09a5f3d2f00c7c72c3cc396a3912cb2e8d7bde713d4ced7da6f970d130e34', NULL, 'هو الذي جعل لكم اليل لتسكنوا فيه والنهار مبصرا ان في ذلك لايت لقوم يسمعون', 11, 22, 86, 1, 3, 216, false, NULL),
    (1432, 'tanzil-uthmani-v1.1', 10, 68, 'قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ هُوَ ٱلْغَنِىُّ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ إِنْ عِندَكُم مِّن سُلْطَٰنٍۭ بِهَٰذَآ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '86a323ee704a6fea41d0403793fec8b1de93ae645bd37a6f2b2784a01c4c9360', 'قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ هُوَ ٱلْغَنِىُّ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ إِنْ عِندَكُم مِّن سُلْطَٰنٍۭ بِهَٰذَآ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', '86a323ee704a6fea41d0403793fec8b1de93ae645bd37a6f2b2784a01c4c9360', '86a323ee704a6fea41d0403793fec8b1de93ae645bd37a6f2b2784a01c4c9360', NULL, 'قالوا اتخذ الله ولدا سبحنه هو الغني له ما في السموت وما في الارض ان عندكم من سلطن بهذا اتقولون علي الله ما لا تعلمون', 11, 22, 86, 1, 3, 216, false, NULL),
    (1433, 'tanzil-uthmani-v1.1', 10, 69, 'قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', '5576e96f5b548f169e6c38711d2a187a17e447566a29733783326d0e7281be8e', 'قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', '5576e96f5b548f169e6c38711d2a187a17e447566a29733783326d0e7281be8e', '5576e96f5b548f169e6c38711d2a187a17e447566a29733783326d0e7281be8e', NULL, 'قل ان الذين يفترون علي الله الكذب لا يفلحون', 11, 22, 86, 1, 3, 216, false, NULL),
    (1434, 'tanzil-uthmani-v1.1', 10, 70, 'مَتَٰعٌ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ', 'bbbd69436788da1824752e5fb79fa69ef5f07b8155695bc49894d85053d3fd41', 'مَتَٰعٌ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ', 'bbbd69436788da1824752e5fb79fa69ef5f07b8155695bc49894d85053d3fd41', 'bbbd69436788da1824752e5fb79fa69ef5f07b8155695bc49894d85053d3fd41', NULL, 'متع في الدنيا ثم الينا مرجعهم ثم نذيقهم العذاب الشديد بما كانوا يكفرون', 11, 22, 86, 1, 3, 216, false, NULL),
    (1435, 'tanzil-uthmani-v1.1', 10, 71, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ', '8d3d9285a34d050cf822230b6036c7a2791a1fe74780536446d076a188f758cd', 'وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ', '8d3d9285a34d050cf822230b6036c7a2791a1fe74780536446d076a188f758cd', '8d3d9285a34d050cf822230b6036c7a2791a1fe74780536446d076a188f758cd', NULL, 'واتل عليهم نبا نوح اذ قال لقومه يقوم ان كان كبر عليكم مقامي وتذكيري بايت الله فعلي الله توكلت فاجمعوا امركم وشركاءكم ثم لا يكن امركم عليكم غمه ثم اقضوا الي ولا تنظرون', 11, 22, 87, 1, 3, 217, false, NULL),
    (1436, 'tanzil-uthmani-v1.1', 10, 72, 'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', '0a67bf68ed6f95200dc4315b07528ccaee3f910c7fc8deef0aa80e883de37b5d', 'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', '0a67bf68ed6f95200dc4315b07528ccaee3f910c7fc8deef0aa80e883de37b5d', '0a67bf68ed6f95200dc4315b07528ccaee3f910c7fc8deef0aa80e883de37b5d', NULL, 'فان توليتم فما سالتكم من اجر ان اجري الا علي الله وامرت ان اكون من المسلمين', 11, 22, 87, 1, 3, 217, false, NULL),
    (1437, 'tanzil-uthmani-v1.1', 10, 73, 'فَكَذَّبُوهُ فَنَجَّيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَٰهُمْ خَلَٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', '2b5c00620f085cb04d50112f0287b27f2e5b8be67ffb7439a2045efb526e03dc', 'فَكَذَّبُوهُ فَنَجَّيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَٰهُمْ خَلَٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', '2b5c00620f085cb04d50112f0287b27f2e5b8be67ffb7439a2045efb526e03dc', '2b5c00620f085cb04d50112f0287b27f2e5b8be67ffb7439a2045efb526e03dc', NULL, 'فكذبوه فنجينه ومن معه في الفلك وجعلنهم خلئف واغرقنا الذين كذبوا بايتنا فانظر كيف كان عقبه المنذرين', 11, 22, 87, 1, 3, 217, false, NULL),
    (1438, 'tanzil-uthmani-v1.1', 10, 74, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ', 'e6dc9823aba710c54eb7469c342961ccdc2e0d46c7c72e2809bdae0e38bb3671', 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ', 'e6dc9823aba710c54eb7469c342961ccdc2e0d46c7c72e2809bdae0e38bb3671', 'e6dc9823aba710c54eb7469c342961ccdc2e0d46c7c72e2809bdae0e38bb3671', NULL, 'ثم بعثنا من بعده رسلا الي قومهم فجاءوهم بالبينت فما كانوا ليؤمنوا بما كذبوا به من قبل كذلك نطبع علي قلوب المعتدين', 11, 22, 87, 1, 3, 217, false, NULL),
    (1439, 'tanzil-uthmani-v1.1', 10, 75, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', '87d71b9a45a08b95c3bfc7fab1a754016463bf02eac52c684ebee600445b3b4f', 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ', '87d71b9a45a08b95c3bfc7fab1a754016463bf02eac52c684ebee600445b3b4f', '87d71b9a45a08b95c3bfc7fab1a754016463bf02eac52c684ebee600445b3b4f', NULL, 'ثم بعثنا من بعدهم موسي وهرون الي فرعون وملايه بايتنا فاستكبروا وكانوا قوما مجرمين', 11, 22, 87, 1, 3, 217, false, NULL),
    (1440, 'tanzil-uthmani-v1.1', 10, 76, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَٰذَا لَسِحْرٌ مُّبِينٌ', '7a8009571e9afdd67913aaf92877c29a4b1d1f1479ae9cfd23d9529c7ac76353', 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَٰذَا لَسِحْرٌ مُّبِينٌ', '7a8009571e9afdd67913aaf92877c29a4b1d1f1479ae9cfd23d9529c7ac76353', '7a8009571e9afdd67913aaf92877c29a4b1d1f1479ae9cfd23d9529c7ac76353', NULL, 'فلما جاءهم الحق من عندنا قالوا ان هذا لسحر مبين', 11, 22, 87, 1, 3, 217, false, NULL),
    (1441, 'tanzil-uthmani-v1.1', 10, 77, 'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ ٱلسَّٰحِرُونَ', '0dd01dd98a161c42afd3226e88047aba02c22cf477fdaca0767e99a2ebf5e5eb', 'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ ٱلسَّٰحِرُونَ', '0dd01dd98a161c42afd3226e88047aba02c22cf477fdaca0767e99a2ebf5e5eb', '0dd01dd98a161c42afd3226e88047aba02c22cf477fdaca0767e99a2ebf5e5eb', NULL, 'قال موسي اتقولون للحق لما جاءكم اسحر هذا ولا يفلح السحرون', 11, 22, 87, 1, 3, 217, false, NULL),
    (1442, 'tanzil-uthmani-v1.1', 10, 78, 'قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ', '60c1b0beb89979b647fc16e22c6ff1eacae74b631fc7f5506b67827f62aa79a1', 'قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ', '60c1b0beb89979b647fc16e22c6ff1eacae74b631fc7f5506b67827f62aa79a1', '60c1b0beb89979b647fc16e22c6ff1eacae74b631fc7f5506b67827f62aa79a1', NULL, 'قالوا اجئتنا لتلفتنا عما وجدنا عليه ءاباءنا وتكون لكما الكبرياء في الارض وما نحن لكما بمؤمنين', 11, 22, 87, 1, 3, 217, false, NULL),
    (1443, 'tanzil-uthmani-v1.1', 10, 79, 'وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَٰحِرٍ عَلِيمٍ', '0ae639746433e25060a1d705e9ef5adc68c0d5338bad128eb46dd20c39862790', 'وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَٰحِرٍ عَلِيمٍ', '0ae639746433e25060a1d705e9ef5adc68c0d5338bad128eb46dd20c39862790', '0ae639746433e25060a1d705e9ef5adc68c0d5338bad128eb46dd20c39862790', NULL, 'وقال فرعون ائتوني بكل سحر عليم', 11, 22, 87, 1, 3, 218, false, NULL),
    (1444, 'tanzil-uthmani-v1.1', 10, 80, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', '3540b288464f3147196b7ce9f12de78e6110315c01b352617386c698ce45302c', 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', '3540b288464f3147196b7ce9f12de78e6110315c01b352617386c698ce45302c', '3540b288464f3147196b7ce9f12de78e6110315c01b352617386c698ce45302c', NULL, 'فلما جاء السحره قال لهم موسي القوا ما انتم ملقون', 11, 22, 87, 1, 3, 218, false, NULL),
    (1445, 'tanzil-uthmani-v1.1', 10, 81, 'فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ', '1551568a9eee44dff2cdf2a2efeaa2aa0a910d4474c0bc8eebe6e65883a805f2', 'فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ', '1551568a9eee44dff2cdf2a2efeaa2aa0a910d4474c0bc8eebe6e65883a805f2', '1551568a9eee44dff2cdf2a2efeaa2aa0a910d4474c0bc8eebe6e65883a805f2', NULL, 'فلما القوا قال موسي ما جئتم به السحر ان الله سيبطله ان الله لا يصلح عمل المفسدين', 11, 22, 87, 1, 3, 218, false, NULL),
    (1446, 'tanzil-uthmani-v1.1', 10, 82, 'وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 'a4407ea877a77cbfc6b3a57aa1cc8c82956854c8352eec97ff4842ef00cd58c2', 'وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 'a4407ea877a77cbfc6b3a57aa1cc8c82956854c8352eec97ff4842ef00cd58c2', 'a4407ea877a77cbfc6b3a57aa1cc8c82956854c8352eec97ff4842ef00cd58c2', NULL, 'ويحق الله الحق بكلمته ولو كره المجرمون', 11, 22, 87, 1, 3, 218, false, NULL),
    (1447, 'tanzil-uthmani-v1.1', 10, 83, 'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ', '016be0e32ce2d547c091c9e479760c136f51004ae1f2975ddbb4d6bfab52debb', 'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ وَإِنَّ فِرْعَوْنَ لَعَالٍ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ', '016be0e32ce2d547c091c9e479760c136f51004ae1f2975ddbb4d6bfab52debb', '016be0e32ce2d547c091c9e479760c136f51004ae1f2975ddbb4d6bfab52debb', NULL, 'فما ءامن لموسي الا ذريه من قومه علي خوف من فرعون وملايهم ان يفتنهم وان فرعون لعال في الارض وانه لمن المسرفين', 11, 22, 87, 1, 3, 218, false, NULL),
    (1448, 'tanzil-uthmani-v1.1', 10, 84, 'وَقَالَ مُوسَىٰ يَٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ', '2575cfef40cbaa427ecf2d6ac7715b3b1cb75d41e650ad8f3dc6f8b7b643adbb', 'وَقَالَ مُوسَىٰ يَٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ', '2575cfef40cbaa427ecf2d6ac7715b3b1cb75d41e650ad8f3dc6f8b7b643adbb', '2575cfef40cbaa427ecf2d6ac7715b3b1cb75d41e650ad8f3dc6f8b7b643adbb', NULL, 'وقال موسي يقوم ان كنتم ءامنتم بالله فعليه توكلوا ان كنتم مسلمين', 11, 22, 87, 1, 3, 218, false, NULL),
    (1449, 'tanzil-uthmani-v1.1', 10, 85, 'فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ ٱلظَّٰلِمِينَ', '70e7b6254aecb17ab3456c4e3fb7bdac139d06b413107699c8f0f9804d131d33', 'فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ ٱلظَّٰلِمِينَ', '70e7b6254aecb17ab3456c4e3fb7bdac139d06b413107699c8f0f9804d131d33', '70e7b6254aecb17ab3456c4e3fb7bdac139d06b413107699c8f0f9804d131d33', NULL, 'فقالوا علي الله توكلنا ربنا لا تجعلنا فتنه للقوم الظلمين', 11, 22, 87, 1, 3, 218, false, NULL),
    (1450, 'tanzil-uthmani-v1.1', 10, 86, 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '8230ead7c9bc045a38e717a07ac020ce9a8f8b88f9d460be8b93ef9c7f110d8d', 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَٰفِرِينَ', '8230ead7c9bc045a38e717a07ac020ce9a8f8b88f9d460be8b93ef9c7f110d8d', '8230ead7c9bc045a38e717a07ac020ce9a8f8b88f9d460be8b93ef9c7f110d8d', NULL, 'ونجنا برحمتك من القوم الكفرين', 11, 22, 87, 1, 3, 218, false, NULL),
    (1451, 'tanzil-uthmani-v1.1', 10, 87, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '5f497469c34dca838a7e483609f4937e78b3a83b8a9e4e56121d131641b36b6e', 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةً وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '5f497469c34dca838a7e483609f4937e78b3a83b8a9e4e56121d131641b36b6e', '5f497469c34dca838a7e483609f4937e78b3a83b8a9e4e56121d131641b36b6e', NULL, 'واوحينا الي موسي واخيه ان تبوءا لقومكما بمصر بيوتا واجعلوا بيوتكم قبله واقيموا الصلوه وبشر المؤمنين', 11, 22, 87, 1, 3, 218, false, NULL),
    (1452, 'tanzil-uthmani-v1.1', 10, 88, 'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةً وَأَمْوَٰلًا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', '12d432a5929f313953e47752e169f6590e0cf30ea0ead5d80e18976e7851d964', 'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةً وَأَمْوَٰلًا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', '12d432a5929f313953e47752e169f6590e0cf30ea0ead5d80e18976e7851d964', '12d432a5929f313953e47752e169f6590e0cf30ea0ead5d80e18976e7851d964', NULL, 'وقال موسي ربنا انك ءاتيت فرعون وملاه زينه وامولا في الحيوه الدنيا ربنا ليضلوا عن سبيلك ربنا اطمس علي امولهم واشدد علي قلوبهم فلا يؤمنوا حتي يروا العذاب الاليم', 11, 22, 87, 1, 3, 218, false, NULL),
    (1453, 'tanzil-uthmani-v1.1', 10, 89, 'قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ', '32be8a48599c16e2cf86534ac287c7109890eec5c495f800f73c3b35ba10dcd2', 'قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ', '32be8a48599c16e2cf86534ac287c7109890eec5c495f800f73c3b35ba10dcd2', '32be8a48599c16e2cf86534ac287c7109890eec5c495f800f73c3b35ba10dcd2', NULL, 'قال قد اجيبت دعوتكما فاستقيما ولا تتبعان سبيل الذين لا يعلمون', 11, 22, 87, 1, 3, 219, false, NULL),
    (1454, 'tanzil-uthmani-v1.1', 10, 90, 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًا وَعَدْوًا حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ', '432ec0d4e82bd55e87453ebdae5e7b905ac8f792efdf95990c79121cc5154ae2', 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًا وَعَدْوًا حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ', '432ec0d4e82bd55e87453ebdae5e7b905ac8f792efdf95990c79121cc5154ae2', '432ec0d4e82bd55e87453ebdae5e7b905ac8f792efdf95990c79121cc5154ae2', NULL, 'وجوزنا ببني اسرءيل البحر فاتبعهم فرعون وجنوده بغيا وعدوا حتي اذا ادركه الغرق قال ءامنت انه لا اله الا الذي ءامنت به بنوا اسرءيل وانا من المسلمين', 11, 22, 88, 1, 3, 219, false, NULL),
    (1455, 'tanzil-uthmani-v1.1', 10, 91, 'ءَآلْـَٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ', '16d15a093bb4b89a233369550c24241c7f4e063b85c3db9decd77e02773269e1', 'ءَآلْـَٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ', '16d15a093bb4b89a233369550c24241c7f4e063b85c3db9decd77e02773269e1', '16d15a093bb4b89a233369550c24241c7f4e063b85c3db9decd77e02773269e1', NULL, 'ءالن وقد عصيت قبل وكنت من المفسدين', 11, 22, 88, 1, 3, 219, false, NULL),
    (1456, 'tanzil-uthmani-v1.1', 10, 92, 'فَٱلْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةً وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ عَنْ ءَايَٰتِنَا لَغَٰفِلُونَ', '7e7ee49afc80474fe4c0ee09f2162cfc89fcc1d3bf3452fbdba3104e40b3048c', 'فَٱلْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةً وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ عَنْ ءَايَٰتِنَا لَغَٰفِلُونَ', '7e7ee49afc80474fe4c0ee09f2162cfc89fcc1d3bf3452fbdba3104e40b3048c', '7e7ee49afc80474fe4c0ee09f2162cfc89fcc1d3bf3452fbdba3104e40b3048c', NULL, 'فاليوم ننجيك ببدنك لتكون لمن خلفك ءايه وان كثيرا من الناس عن ءايتنا لغفلون', 11, 22, 88, 1, 3, 219, false, NULL),
    (1457, 'tanzil-uthmani-v1.1', 10, 93, 'وَلَقَدْ بَوَّأْنَا بَنِىٓ إِسْرَٰٓءِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخْتَلَفُوا۟ حَتَّىٰ جَآءَهُمُ ٱلْعِلْمُ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '971c059ed3135cf3b30fc555de8afa3af3addbe62e90f8122a2b0c0c1f76d86c', 'وَلَقَدْ بَوَّأْنَا بَنِىٓ إِسْرَٰٓءِيلَ مُبَوَّأَ صِدْقٍ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخْتَلَفُوا۟ حَتَّىٰ جَآءَهُمُ ٱلْعِلْمُ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '971c059ed3135cf3b30fc555de8afa3af3addbe62e90f8122a2b0c0c1f76d86c', '971c059ed3135cf3b30fc555de8afa3af3addbe62e90f8122a2b0c0c1f76d86c', NULL, 'ولقد بوانا بني اسرءيل مبوا صدق ورزقنهم من الطيبت فما اختلفوا حتي جاءهم العلم ان ربك يقضي بينهم يوم القيمه فيما كانوا فيه يختلفون', 11, 22, 88, 1, 3, 219, false, NULL),
    (1458, 'tanzil-uthmani-v1.1', 10, 94, 'فَإِن كُنتَ فِى شَكٍّ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ٱلَّذِينَ يَقْرَءُونَ ٱلْكِتَٰبَ مِن قَبْلِكَ لَقَدْ جَآءَكَ ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'c1c035ee838ca12db289bc096f09bef5f91edc06b56f9d909f834798fe5cdb6f', 'فَإِن كُنتَ فِى شَكٍّ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ٱلَّذِينَ يَقْرَءُونَ ٱلْكِتَٰبَ مِن قَبْلِكَ لَقَدْ جَآءَكَ ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 'c1c035ee838ca12db289bc096f09bef5f91edc06b56f9d909f834798fe5cdb6f', 'c1c035ee838ca12db289bc096f09bef5f91edc06b56f9d909f834798fe5cdb6f', NULL, 'فان كنت في شك مما انزلنا اليك فسل الذين يقرءون الكتب من قبلك لقد جاءك الحق من ربك فلا تكونن من الممترين', 11, 22, 88, 1, 3, 219, false, NULL),
    (1459, 'tanzil-uthmani-v1.1', 10, 95, 'وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلْخَٰسِرِينَ', 'cccdcb6a25027ecb03a05d524712564e5b8b0dea2a409bc7717c2596f4b0bea8', 'وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلْخَٰسِرِينَ', 'cccdcb6a25027ecb03a05d524712564e5b8b0dea2a409bc7717c2596f4b0bea8', 'cccdcb6a25027ecb03a05d524712564e5b8b0dea2a409bc7717c2596f4b0bea8', NULL, 'ولا تكونن من الذين كذبوا بايت الله فتكون من الخسرين', 11, 22, 88, 1, 3, 219, false, NULL),
    (1460, 'tanzil-uthmani-v1.1', 10, 96, 'إِنَّ ٱلَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ', '3864df4c0c2b2fb4dc51f34e09a0fb56f1b25d2a38eb7656e39aa2cf51281ecf', 'إِنَّ ٱلَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ', '3864df4c0c2b2fb4dc51f34e09a0fb56f1b25d2a38eb7656e39aa2cf51281ecf', '3864df4c0c2b2fb4dc51f34e09a0fb56f1b25d2a38eb7656e39aa2cf51281ecf', NULL, 'ان الذين حقت عليهم كلمت ربك لا يؤمنون', 11, 22, 88, 1, 3, 219, false, NULL),
    (1461, 'tanzil-uthmani-v1.1', 10, 97, 'وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', '8f5099f3f13026475dc55c0198b58a2e1a5699fb07848133a151ea376c37af07', 'وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', '8f5099f3f13026475dc55c0198b58a2e1a5699fb07848133a151ea376c37af07', '8f5099f3f13026475dc55c0198b58a2e1a5699fb07848133a151ea376c37af07', NULL, 'ولو جاءتهم كل ءايه حتي يروا العذاب الاليم', 11, 22, 88, 1, 3, 219, false, NULL),
    (1462, 'tanzil-uthmani-v1.1', 10, 98, 'فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍ', '590b6973d7b75e44a48735fb8f06e71a152114dddfcf08d0bf67876e1f94a44c', 'فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍ', '590b6973d7b75e44a48735fb8f06e71a152114dddfcf08d0bf67876e1f94a44c', '590b6973d7b75e44a48735fb8f06e71a152114dddfcf08d0bf67876e1f94a44c', NULL, 'فلولا كانت قريه ءامنت فنفعها ايمنها الا قوم يونس لما ءامنوا كشفنا عنهم عذاب الخزي في الحيوه الدنيا ومتعنهم الي حين', 11, 22, 88, 1, 3, 220, false, NULL),
    (1463, 'tanzil-uthmani-v1.1', 10, 99, 'وَلَوْ شَآءَ رَبُّكَ لَـَٔامَنَ مَن فِى ٱلْأَرْضِ كُلُّهُمْ جَمِيعًا أَفَأَنتَ تُكْرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُوا۟ مُؤْمِنِينَ', '3a8cef1010692e5d69c1cd8ab94baa0acd56910f59396c877fb61f27e11c3199', 'وَلَوْ شَآءَ رَبُّكَ لَـَٔامَنَ مَن فِى ٱلْأَرْضِ كُلُّهُمْ جَمِيعًا أَفَأَنتَ تُكْرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُوا۟ مُؤْمِنِينَ', '3a8cef1010692e5d69c1cd8ab94baa0acd56910f59396c877fb61f27e11c3199', '3a8cef1010692e5d69c1cd8ab94baa0acd56910f59396c877fb61f27e11c3199', NULL, 'ولو شاء ربك لامن من في الارض كلهم جميعا افانت تكره الناس حتي يكونوا مؤمنين', 11, 22, 88, 1, 3, 220, false, NULL),
    (1464, 'tanzil-uthmani-v1.1', 10, 100, 'وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ', '42374d773d5503eab52d5dc837a7da30f93a51cf52b155f830508e85125f5621', 'وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ', '42374d773d5503eab52d5dc837a7da30f93a51cf52b155f830508e85125f5621', '42374d773d5503eab52d5dc837a7da30f93a51cf52b155f830508e85125f5621', NULL, 'وما كان لنفس ان تؤمن الا باذن الله ويجعل الرجس علي الذين لا يعقلون', 11, 22, 88, 1, 3, 220, false, NULL),
    (1465, 'tanzil-uthmani-v1.1', 10, 101, 'قُلِ ٱنظُرُوا۟ مَاذَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا تُغْنِى ٱلْـَٔايَٰتُ وَٱلنُّذُرُ عَن قَوْمٍ لَّا يُؤْمِنُونَ', '6208ad6f776844bf94e785f96242e680b3d44814fd6034fbf03423be523d6a67', 'قُلِ ٱنظُرُوا۟ مَاذَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا تُغْنِى ٱلْـَٔايَٰتُ وَٱلنُّذُرُ عَن قَوْمٍ لَّا يُؤْمِنُونَ', '6208ad6f776844bf94e785f96242e680b3d44814fd6034fbf03423be523d6a67', '6208ad6f776844bf94e785f96242e680b3d44814fd6034fbf03423be523d6a67', NULL, 'قل انظروا ماذا في السموت والارض وما تغني الايت والنذر عن قوم لا يؤمنون', 11, 22, 88, 1, 3, 220, false, NULL),
    (1466, 'tanzil-uthmani-v1.1', 10, 102, 'فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِهِمْ قُلْ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', '4916d5d396aefa95f1fddf3db3f20afdad0d92e0d4dc3027c446fcfb63c44551', 'فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِهِمْ قُلْ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', '4916d5d396aefa95f1fddf3db3f20afdad0d92e0d4dc3027c446fcfb63c44551', '4916d5d396aefa95f1fddf3db3f20afdad0d92e0d4dc3027c446fcfb63c44551', NULL, 'فهل ينتظرون الا مثل ايام الذين خلوا من قبلهم قل فانتظروا اني معكم من المنتظرين', 11, 22, 88, 1, 3, 220, false, NULL),
    (1467, 'tanzil-uthmani-v1.1', 10, 103, 'ثُمَّ نُنَجِّى رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ ٱلْمُؤْمِنِينَ', '7951c83278f6ab5f3bb14efa40a76bf42511d5d89a554c714afd8afe8eab2220', 'ثُمَّ نُنَجِّى رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ ٱلْمُؤْمِنِينَ', '7951c83278f6ab5f3bb14efa40a76bf42511d5d89a554c714afd8afe8eab2220', '7951c83278f6ab5f3bb14efa40a76bf42511d5d89a554c714afd8afe8eab2220', NULL, 'ثم ننجي رسلنا والذين ءامنوا كذلك حقا علينا ننج المؤمنين', 11, 22, 88, 1, 3, 220, false, NULL),
    (1468, 'tanzil-uthmani-v1.1', 10, 104, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى شَكٍّ مِّن دِينِى فَلَآ أَعْبُدُ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنْ أَعْبُدُ ٱللَّهَ ٱلَّذِى يَتَوَفَّىٰكُمْ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُؤْمِنِينَ', '7568a4e14d0bba0ad2a565d9d03c8856f2d2d284c3151ba427b57d0c233b49bc', 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى شَكٍّ مِّن دِينِى فَلَآ أَعْبُدُ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنْ أَعْبُدُ ٱللَّهَ ٱلَّذِى يَتَوَفَّىٰكُمْ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُؤْمِنِينَ', '7568a4e14d0bba0ad2a565d9d03c8856f2d2d284c3151ba427b57d0c233b49bc', '7568a4e14d0bba0ad2a565d9d03c8856f2d2d284c3151ba427b57d0c233b49bc', NULL, 'قل يايها الناس ان كنتم في شك من ديني فلا اعبد الذين تعبدون من دون الله ولكن اعبد الله الذي يتوفيكم وامرت ان اكون من المؤمنين', 11, 22, 88, 1, 3, 220, false, NULL),
    (1469, 'tanzil-uthmani-v1.1', 10, 105, 'وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', '14ae5f30a8449cbe602151d6dd66a0c136dd4bc2fca62b9a313da0718c03f70f', 'وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', '14ae5f30a8449cbe602151d6dd66a0c136dd4bc2fca62b9a313da0718c03f70f', '14ae5f30a8449cbe602151d6dd66a0c136dd4bc2fca62b9a313da0718c03f70f', NULL, 'وان اقم وجهك للدين حنيفا ولا تكونن من المشركين', 11, 22, 88, 1, 3, 220, false, NULL),
    (1470, 'tanzil-uthmani-v1.1', 10, 106, 'وَلَا تَدْعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ فَإِن فَعَلْتَ فَإِنَّكَ إِذًا مِّنَ ٱلظَّٰلِمِينَ', '1049fed5120b776075e66842e2f7ba13d93e0325bb304d7d416016a2adbd7a85', 'وَلَا تَدْعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ فَإِن فَعَلْتَ فَإِنَّكَ إِذًا مِّنَ ٱلظَّٰلِمِينَ', '1049fed5120b776075e66842e2f7ba13d93e0325bb304d7d416016a2adbd7a85', '1049fed5120b776075e66842e2f7ba13d93e0325bb304d7d416016a2adbd7a85', NULL, 'ولا تدع من دون الله ما لا ينفعك ولا يضرك فان فعلت فانك اذا من الظلمين', 11, 22, 88, 1, 3, 220, false, NULL),
    (1471, 'tanzil-uthmani-v1.1', 10, 107, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَآدَّ لِفَضْلِهِۦ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '1d0b38295b51f447c6fe2ab4e45810564efb648ae5dc98829bbc85cacec61cac', 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَآدَّ لِفَضْلِهِۦ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '1d0b38295b51f447c6fe2ab4e45810564efb648ae5dc98829bbc85cacec61cac', '1d0b38295b51f447c6fe2ab4e45810564efb648ae5dc98829bbc85cacec61cac', NULL, 'وان يمسسك الله بضر فلا كاشف له الا هو وان يردك بخير فلا راد لفضله يصيب به من يشاء من عباده وهو الغفور الرحيم', 11, 22, 88, 1, 3, 221, false, NULL),
    (1472, 'tanzil-uthmani-v1.1', 10, 108, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلْحَقُّ مِن رَّبِّكُمْ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَآ أَنَا۠ عَلَيْكُم بِوَكِيلٍ', 'f483a4df6f2363eb596cc08539759aa9d9255233f3a39e9184540b34220786b4', 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلْحَقُّ مِن رَّبِّكُمْ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَآ أَنَا۠ عَلَيْكُم بِوَكِيلٍ', 'f483a4df6f2363eb596cc08539759aa9d9255233f3a39e9184540b34220786b4', 'f483a4df6f2363eb596cc08539759aa9d9255233f3a39e9184540b34220786b4', NULL, 'قل يايها الناس قد جاءكم الحق من ربكم فمن اهتدي فانما يهتدي لنفسه ومن ضل فانما يضل عليها وما انا عليكم بوكيل', 11, 22, 88, 1, 3, 221, false, NULL),
    (1473, 'tanzil-uthmani-v1.1', 10, 109, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ وَٱصْبِرْ حَتَّىٰ يَحْكُمَ ٱللَّهُ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'f443e602b2d175973816ba6cbdffb2adb5e74c6fa3e8fe3fe7fc9d55ea08929a', 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ وَٱصْبِرْ حَتَّىٰ يَحْكُمَ ٱللَّهُ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 'f443e602b2d175973816ba6cbdffb2adb5e74c6fa3e8fe3fe7fc9d55ea08929a', 'f443e602b2d175973816ba6cbdffb2adb5e74c6fa3e8fe3fe7fc9d55ea08929a', NULL, 'واتبع ما يوحي اليك واصبر حتي يحكم الله وهو خير الحكمين', 11, 22, 88, 1, 3, 221, false, NULL),
    (1474, 'tanzil-uthmani-v1.1', 11, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر كِتَٰبٌ أُحْكِمَتْ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ', 'c44f97458c6884a9bdd8fae70f23a65dc6e589a29d16e3ddb1328458c1d585f8', 'الٓر كِتَٰبٌ أُحْكِمَتْ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ', 'bbe5cdd8f95ce58e868a05566107029d65abf1bbcc989c94668caa1458f4b29a', 'bbe5cdd8f95ce58e868a05566107029d65abf1bbcc989c94668caa1458f4b29a', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الر كتب احكمت ءايته ثم فصلت من لدن حكيم خبير', 11, 22, 88, 1, 3, 221, false, NULL),
    (1475, 'tanzil-uthmani-v1.1', 11, 2, 'أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنَّنِى لَكُم مِّنْهُ نَذِيرٌ وَبَشِيرٌ', 'cb14be9a17d561206346b1f40fc3b46c1b392de501d806781551fe6afd207588', 'أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنَّنِى لَكُم مِّنْهُ نَذِيرٌ وَبَشِيرٌ', 'cb14be9a17d561206346b1f40fc3b46c1b392de501d806781551fe6afd207588', 'cb14be9a17d561206346b1f40fc3b46c1b392de501d806781551fe6afd207588', NULL, 'الا تعبدوا الا الله انني لكم منه نذير وبشير', 11, 22, 88, 1, 3, 221, false, NULL),
    (1476, 'tanzil-uthmani-v1.1', 11, 3, 'وَأَنِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُمَتِّعْكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٍ مُّسَمًّى وَيُؤْتِ كُلَّ ذِى فَضْلٍ فَضْلَهُۥ وَإِن تَوَلَّوْا۟ فَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ كَبِيرٍ', '03d3a66feaeb5cbbefddd1b0aa5eac49f09d105328b2928debd5ae57edc3f5a2', 'وَأَنِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُمَتِّعْكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٍ مُّسَمًّى وَيُؤْتِ كُلَّ ذِى فَضْلٍ فَضْلَهُۥ وَإِن تَوَلَّوْا۟ فَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ كَبِيرٍ', '03d3a66feaeb5cbbefddd1b0aa5eac49f09d105328b2928debd5ae57edc3f5a2', '03d3a66feaeb5cbbefddd1b0aa5eac49f09d105328b2928debd5ae57edc3f5a2', NULL, 'وان استغفروا ربكم ثم توبوا اليه يمتعكم متعا حسنا الي اجل مسمي ويؤت كل ذي فضل فضله وان تولوا فاني اخاف عليكم عذاب يوم كبير', 11, 22, 88, 1, 3, 221, false, NULL),
    (1477, 'tanzil-uthmani-v1.1', 11, 4, 'إِلَى ٱللَّهِ مَرْجِعُكُمْ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '412eae482b2caa66862043387f2994f41540de4bfd9bff9434a49e495ad6294a', 'إِلَى ٱللَّهِ مَرْجِعُكُمْ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '412eae482b2caa66862043387f2994f41540de4bfd9bff9434a49e495ad6294a', '412eae482b2caa66862043387f2994f41540de4bfd9bff9434a49e495ad6294a', NULL, 'الي الله مرجعكم وهو علي كل شيء قدير', 11, 22, 88, 1, 3, 221, false, NULL),
    (1478, 'tanzil-uthmani-v1.1', 11, 5, 'أَلَآ إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا۟ مِنْهُ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'b0199dda2710d51525cfb1acf48db9dfd6272da996e65d67b60a4745bf8faacd', 'أَلَآ إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا۟ مِنْهُ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'b0199dda2710d51525cfb1acf48db9dfd6272da996e65d67b60a4745bf8faacd', 'b0199dda2710d51525cfb1acf48db9dfd6272da996e65d67b60a4745bf8faacd', NULL, 'الا انهم يثنون صدورهم ليستخفوا منه الا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون انه عليم بذات الصدور', 11, 22, 88, 1, 3, 221, false, NULL),
    (1479, 'tanzil-uthmani-v1.1', 11, 6, 'وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ إِلَّا عَلَى ٱللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا كُلٌّ فِى كِتَٰبٍ مُّبِينٍ', '1bbcd4850c62e604fa1e9b313054d9210c1762b0e598ea32d576fe1f04c01373', 'وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ إِلَّا عَلَى ٱللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا كُلٌّ فِى كِتَٰبٍ مُّبِينٍ', '1bbcd4850c62e604fa1e9b313054d9210c1762b0e598ea32d576fe1f04c01373', '1bbcd4850c62e604fa1e9b313054d9210c1762b0e598ea32d576fe1f04c01373', NULL, 'وما من دابه في الارض الا علي الله رزقها ويعلم مستقرها ومستودعها كل في كتب مبين', 12, 23, 89, 1, 3, 222, false, NULL),
    (1480, 'tanzil-uthmani-v1.1', 11, 7, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُۥ عَلَى ٱلْمَآءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِنۢ بَعْدِ ٱلْمَوْتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'ecb3fcd21814b16eb1d8e109258e6f971f0165220cdd4d8477574e7f2072f2f1', 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُۥ عَلَى ٱلْمَآءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِنۢ بَعْدِ ٱلْمَوْتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', 'ecb3fcd21814b16eb1d8e109258e6f971f0165220cdd4d8477574e7f2072f2f1', 'ecb3fcd21814b16eb1d8e109258e6f971f0165220cdd4d8477574e7f2072f2f1', NULL, 'وهو الذي خلق السموت والارض في سته ايام وكان عرشه علي الماء ليبلوكم ايكم احسن عملا ولئن قلت انكم مبعوثون من بعد الموت ليقولن الذين كفروا ان هذا الا سحر مبين', 12, 23, 89, 1, 3, 222, false, NULL),
    (1481, 'tanzil-uthmani-v1.1', 11, 8, 'وَلَئِنْ أَخَّرْنَا عَنْهُمُ ٱلْعَذَابَ إِلَىٰٓ أُمَّةٍ مَّعْدُودَةٍ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'e4212631626c5b0b45357ae99cff7fe64bb7f93797f55beee28088a53658f20a', 'وَلَئِنْ أَخَّرْنَا عَنْهُمُ ٱلْعَذَابَ إِلَىٰٓ أُمَّةٍ مَّعْدُودَةٍ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'e4212631626c5b0b45357ae99cff7fe64bb7f93797f55beee28088a53658f20a', 'e4212631626c5b0b45357ae99cff7fe64bb7f93797f55beee28088a53658f20a', NULL, 'ولئن اخرنا عنهم العذاب الي امه معدوده ليقولن ما يحبسه الا يوم ياتيهم ليس مصروفا عنهم وحاق بهم ما كانوا به يستهزءون', 12, 23, 89, 1, 3, 222, false, NULL),
    (1482, 'tanzil-uthmani-v1.1', 11, 9, 'وَلَئِنْ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةً ثُمَّ نَزَعْنَٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسٌ كَفُورٌ', 'b481a21f6dc24c7cfea17602280e657b8bbdf74a3f6876cda8538b1440eab34d', 'وَلَئِنْ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةً ثُمَّ نَزَعْنَٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسٌ كَفُورٌ', 'b481a21f6dc24c7cfea17602280e657b8bbdf74a3f6876cda8538b1440eab34d', 'b481a21f6dc24c7cfea17602280e657b8bbdf74a3f6876cda8538b1440eab34d', NULL, 'ولئن اذقنا الانسن منا رحمه ثم نزعنها منه انه ليوس كفور', 12, 23, 89, 1, 3, 222, false, NULL),
    (1483, 'tanzil-uthmani-v1.1', 11, 10, 'وَلَئِنْ أَذَقْنَٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّىٓ إِنَّهُۥ لَفَرِحٌ فَخُورٌ', '69a27554d1f95b7c1ff85a3e8fe3cebdd160490e2d4ad4dddc72cb1240ef3a98', 'وَلَئِنْ أَذَقْنَٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّىٓ إِنَّهُۥ لَفَرِحٌ فَخُورٌ', '69a27554d1f95b7c1ff85a3e8fe3cebdd160490e2d4ad4dddc72cb1240ef3a98', '69a27554d1f95b7c1ff85a3e8fe3cebdd160490e2d4ad4dddc72cb1240ef3a98', NULL, 'ولئن اذقنه نعماء بعد ضراء مسته ليقولن ذهب السيات عني انه لفرح فخور', 12, 23, 89, 1, 3, 222, false, NULL),
    (1484, 'tanzil-uthmani-v1.1', 11, 11, 'إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', '7dbedb6fd50b763e59bb2ec56197f98d133919f2bc8208a8258c06992291a363', 'إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', '7dbedb6fd50b763e59bb2ec56197f98d133919f2bc8208a8258c06992291a363', '7dbedb6fd50b763e59bb2ec56197f98d133919f2bc8208a8258c06992291a363', NULL, 'الا الذين صبروا وعملوا الصلحت اولئك لهم مغفره واجر كبير', 12, 23, 89, 1, 3, 222, false, NULL),
    (1485, 'tanzil-uthmani-v1.1', 11, 12, 'فَلَعَلَّكَ تَارِكٌۢ بَعْضَ مَا يُوحَىٰٓ إِلَيْكَ وَضَآئِقٌۢ بِهِۦ صَدْرُكَ أَن يَقُولُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ كَنزٌ أَوْ جَآءَ مَعَهُۥ مَلَكٌ إِنَّمَآ أَنتَ نَذِيرٌ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', '6ea7d099088775b110d75b8bd4c2b65843d2099d9c9562c9966a7966e7498c2e', 'فَلَعَلَّكَ تَارِكٌۢ بَعْضَ مَا يُوحَىٰٓ إِلَيْكَ وَضَآئِقٌۢ بِهِۦ صَدْرُكَ أَن يَقُولُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ كَنزٌ أَوْ جَآءَ مَعَهُۥ مَلَكٌ إِنَّمَآ أَنتَ نَذِيرٌ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', '6ea7d099088775b110d75b8bd4c2b65843d2099d9c9562c9966a7966e7498c2e', '6ea7d099088775b110d75b8bd4c2b65843d2099d9c9562c9966a7966e7498c2e', NULL, 'فلعلك تارك بعض ما يوحي اليك وضائق به صدرك ان يقولوا لولا انزل عليه كنز او جاء معه ملك انما انت نذير والله علي كل شيء وكيل', 12, 23, 89, 1, 3, 222, false, NULL),
    (1486, 'tanzil-uthmani-v1.1', 11, 13, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ فَأْتُوا۟ بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'b113a636b5bb1c70654b34d58e578ded1af7c0a9753a70c10d63c46d66f28260', 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ فَأْتُوا۟ بِعَشْرِ سُوَرٍ مِّثْلِهِۦ مُفْتَرَيَٰتٍ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 'b113a636b5bb1c70654b34d58e578ded1af7c0a9753a70c10d63c46d66f28260', 'b113a636b5bb1c70654b34d58e578ded1af7c0a9753a70c10d63c46d66f28260', NULL, 'ام يقولون افتريه قل فاتوا بعشر سور مثله مفتريت وادعوا من استطعتم من دون الله ان كنتم صدقين', 12, 23, 89, 1, 3, 223, false, NULL),
    (1487, 'tanzil-uthmani-v1.1', 11, 14, 'فَإِلَّمْ يَسْتَجِيبُوا۟ لَكُمْ فَٱعْلَمُوٓا۟ أَنَّمَآ أُنزِلَ بِعِلْمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَ فَهَلْ أَنتُم مُّسْلِمُونَ', '46c179744c9760a7064771e7bc20f7c0c8c43b588664f5ffdfc79ffb53ba6a8a', 'فَإِلَّمْ يَسْتَجِيبُوا۟ لَكُمْ فَٱعْلَمُوٓا۟ أَنَّمَآ أُنزِلَ بِعِلْمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَ فَهَلْ أَنتُم مُّسْلِمُونَ', '46c179744c9760a7064771e7bc20f7c0c8c43b588664f5ffdfc79ffb53ba6a8a', '46c179744c9760a7064771e7bc20f7c0c8c43b588664f5ffdfc79ffb53ba6a8a', NULL, 'فالم يستجيبوا لكم فاعلموا انما انزل بعلم الله وان لا اله الا هو فهل انتم مسلمون', 12, 23, 89, 1, 3, 223, false, NULL),
    (1488, 'tanzil-uthmani-v1.1', 11, 15, 'مَن كَانَ يُرِيدُ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ', '173ac3f9a7faefc01bb66714e15510e331e171e637d5c607d4f6fb25c294d6e7', 'مَن كَانَ يُرِيدُ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ', '173ac3f9a7faefc01bb66714e15510e331e171e637d5c607d4f6fb25c294d6e7', '173ac3f9a7faefc01bb66714e15510e331e171e637d5c607d4f6fb25c294d6e7', NULL, 'من كان يريد الحيوه الدنيا وزينتها نوف اليهم اعملهم فيها وهم فيها لا يبخسون', 12, 23, 89, 1, 3, 223, false, NULL),
    (1489, 'tanzil-uthmani-v1.1', 11, 16, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَيْسَ لَهُمْ فِى ٱلْـَٔاخِرَةِ إِلَّا ٱلنَّارُ وَحَبِطَ مَا صَنَعُوا۟ فِيهَا وَبَٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ', 'f66879d8e1f8727685b22a3d3377bd31f7597326b25f121f28062f14373caebe', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَيْسَ لَهُمْ فِى ٱلْـَٔاخِرَةِ إِلَّا ٱلنَّارُ وَحَبِطَ مَا صَنَعُوا۟ فِيهَا وَبَٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ', 'f66879d8e1f8727685b22a3d3377bd31f7597326b25f121f28062f14373caebe', 'f66879d8e1f8727685b22a3d3377bd31f7597326b25f121f28062f14373caebe', NULL, 'اولئك الذين ليس لهم في الاخره الا النار وحبط ما صنعوا فيها وبطل ما كانوا يعملون', 12, 23, 89, 1, 3, 223, false, NULL),
    (1490, 'tanzil-uthmani-v1.1', 11, 17, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ وَيَتْلُوهُ شَاهِدٌ مِّنْهُ وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ وَمَن يَكْفُرْ بِهِۦ مِنَ ٱلْأَحْزَابِ فَٱلنَّارُ مَوْعِدُهُۥ فَلَا تَكُ فِى مِرْيَةٍ مِّنْهُ إِنَّهُ ٱلْحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'be35ca34f1c2fa72ad04714fc86a6e208f533c4eab7635ef8b226e1af845395b', 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ وَيَتْلُوهُ شَاهِدٌ مِّنْهُ وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ وَمَن يَكْفُرْ بِهِۦ مِنَ ٱلْأَحْزَابِ فَٱلنَّارُ مَوْعِدُهُۥ فَلَا تَكُ فِى مِرْيَةٍ مِّنْهُ إِنَّهُ ٱلْحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'be35ca34f1c2fa72ad04714fc86a6e208f533c4eab7635ef8b226e1af845395b', 'be35ca34f1c2fa72ad04714fc86a6e208f533c4eab7635ef8b226e1af845395b', NULL, 'افمن كان علي بينه من ربه ويتلوه شاهد منه ومن قبله كتب موسي اماما ورحمه اولئك يؤمنون به ومن يكفر به من الاحزاب فالنار موعده فلا تك في مريه منه انه الحق من ربك ولكن اكثر الناس لا يؤمنون', 12, 23, 89, 1, 3, 223, false, NULL),
    (1491, 'tanzil-uthmani-v1.1', 11, 18, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أُو۟لَٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ٱلْأَشْهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُوا۟ عَلَىٰ رَبِّهِمْ أَلَا لَعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', '6e07c3defcce27fb2be0dbd081922a354c32e737551a8cf2e52ddd8bf527f076', 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أُو۟لَٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ٱلْأَشْهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُوا۟ عَلَىٰ رَبِّهِمْ أَلَا لَعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', '6e07c3defcce27fb2be0dbd081922a354c32e737551a8cf2e52ddd8bf527f076', '6e07c3defcce27fb2be0dbd081922a354c32e737551a8cf2e52ddd8bf527f076', NULL, 'ومن اظلم ممن افتري علي الله كذبا اولئك يعرضون علي ربهم ويقول الاشهد هؤلاء الذين كذبوا علي ربهم الا لعنه الله علي الظلمين', 12, 23, 89, 1, 3, 223, false, NULL),
    (1492, 'tanzil-uthmani-v1.1', 11, 19, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ', '41b3ba612f2803bda6d536fd58a4186afcebfe597aa7e20ab69b5d0ab3c54f7e', 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ', '41b3ba612f2803bda6d536fd58a4186afcebfe597aa7e20ab69b5d0ab3c54f7e', '41b3ba612f2803bda6d536fd58a4186afcebfe597aa7e20ab69b5d0ab3c54f7e', NULL, 'الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالاخره هم كفرون', 12, 23, 89, 1, 3, 223, false, NULL),
    (1493, 'tanzil-uthmani-v1.1', 11, 20, 'أُو۟لَٰٓئِكَ لَمْ يَكُونُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ يُضَٰعَفُ لَهُمُ ٱلْعَذَابُ مَا كَانُوا۟ يَسْتَطِيعُونَ ٱلسَّمْعَ وَمَا كَانُوا۟ يُبْصِرُونَ', '64253765ff74127bd6bfb4b7c23f3d67d44057cb2cc2e909d43a4152eed0f560', 'أُو۟لَٰٓئِكَ لَمْ يَكُونُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ يُضَٰعَفُ لَهُمُ ٱلْعَذَابُ مَا كَانُوا۟ يَسْتَطِيعُونَ ٱلسَّمْعَ وَمَا كَانُوا۟ يُبْصِرُونَ', '64253765ff74127bd6bfb4b7c23f3d67d44057cb2cc2e909d43a4152eed0f560', '64253765ff74127bd6bfb4b7c23f3d67d44057cb2cc2e909d43a4152eed0f560', NULL, 'اولئك لم يكونوا معجزين في الارض وما كان لهم من دون الله من اولياء يضعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون', 12, 23, 89, 1, 3, 224, false, NULL),
    (1494, 'tanzil-uthmani-v1.1', 11, 21, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '0e49dc76bc9bfb112b19793c4bb33238d8ae789218d1c56588d88e67695469a7', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '0e49dc76bc9bfb112b19793c4bb33238d8ae789218d1c56588d88e67695469a7', '0e49dc76bc9bfb112b19793c4bb33238d8ae789218d1c56588d88e67695469a7', NULL, 'اولئك الذين خسروا انفسهم وضل عنهم ما كانوا يفترون', 12, 23, 89, 1, 3, 224, false, NULL),
    (1495, 'tanzil-uthmani-v1.1', 11, 22, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', '48d0a96efe530f5ca812d8b98fd4200ada3f1949f0e5b7da9edb4e04d3454659', 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', '48d0a96efe530f5ca812d8b98fd4200ada3f1949f0e5b7da9edb4e04d3454659', '48d0a96efe530f5ca812d8b98fd4200ada3f1949f0e5b7da9edb4e04d3454659', NULL, 'لا جرم انهم في الاخره هم الاخسرون', 12, 23, 89, 1, 3, 224, false, NULL),
    (1496, 'tanzil-uthmani-v1.1', 11, 23, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَخْبَتُوٓا۟ إِلَىٰ رَبِّهِمْ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', '1d21b1317c34b74af43ff8b481c22864e946bf2a733a23eb71c391896d277776', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَخْبَتُوٓا۟ إِلَىٰ رَبِّهِمْ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ', '1d21b1317c34b74af43ff8b481c22864e946bf2a733a23eb71c391896d277776', '1d21b1317c34b74af43ff8b481c22864e946bf2a733a23eb71c391896d277776', NULL, 'ان الذين ءامنوا وعملوا الصلحت واخبتوا الي ربهم اولئك اصحب الجنه هم فيها خلدون', 12, 23, 89, 1, 3, 224, false, NULL),
    (1497, 'tanzil-uthmani-v1.1', 11, 24, 'مَثَلُ ٱلْفَرِيقَيْنِ كَٱلْأَعْمَىٰ وَٱلْأَصَمِّ وَٱلْبَصِيرِ وَٱلسَّمِيعِ هَلْ يَسْتَوِيَانِ مَثَلًا أَفَلَا تَذَكَّرُونَ', '7300b19784d0f945b476a58743a9d7e9e9afa75631e833dd3a647e9a5e457d16', 'مَثَلُ ٱلْفَرِيقَيْنِ كَٱلْأَعْمَىٰ وَٱلْأَصَمِّ وَٱلْبَصِيرِ وَٱلسَّمِيعِ هَلْ يَسْتَوِيَانِ مَثَلًا أَفَلَا تَذَكَّرُونَ', '7300b19784d0f945b476a58743a9d7e9e9afa75631e833dd3a647e9a5e457d16', '7300b19784d0f945b476a58743a9d7e9e9afa75631e833dd3a647e9a5e457d16', NULL, 'مثل الفريقين كالاعمي والاصم والبصير والسميع هل يستويان مثلا افلا تذكرون', 12, 23, 90, 1, 3, 224, false, NULL),
    (1498, 'tanzil-uthmani-v1.1', 11, 25, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', 'daaaa73c76458cf43f4b1bdca0e3afc6b9c0f46b781d2c2f084b28cdc3e649b8', 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', 'daaaa73c76458cf43f4b1bdca0e3afc6b9c0f46b781d2c2f084b28cdc3e649b8', 'daaaa73c76458cf43f4b1bdca0e3afc6b9c0f46b781d2c2f084b28cdc3e649b8', NULL, 'ولقد ارسلنا نوحا الي قومه اني لكم نذير مبين', 12, 23, 90, 1, 3, 224, false, NULL),
    (1499, 'tanzil-uthmani-v1.1', 11, 26, 'أَن لَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍ', 'e50b96d3ead83c8153a0da3f203d28c75b6b93919fb56d9a8e151dd8aa4a6e6b', 'أَن لَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍ', 'e50b96d3ead83c8153a0da3f203d28c75b6b93919fb56d9a8e151dd8aa4a6e6b', 'e50b96d3ead83c8153a0da3f203d28c75b6b93919fb56d9a8e151dd8aa4a6e6b', NULL, 'ان لا تعبدوا الا الله اني اخاف عليكم عذاب يوم اليم', 12, 23, 90, 1, 3, 224, false, NULL),
    (1500, 'tanzil-uthmani-v1.1', 11, 27, 'فَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرًا مِّثْلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ ٱلرَّأْىِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍۭ بَلْ نَظُنُّكُمْ كَٰذِبِينَ', '9100dbf1ca283de78e3970551347a453044f5a34a584c9924cf3eb43e8bdcd15', 'فَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرًا مِّثْلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ ٱلرَّأْىِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍۭ بَلْ نَظُنُّكُمْ كَٰذِبِينَ', '9100dbf1ca283de78e3970551347a453044f5a34a584c9924cf3eb43e8bdcd15', '9100dbf1ca283de78e3970551347a453044f5a34a584c9924cf3eb43e8bdcd15', NULL, 'فقال الملا الذين كفروا من قومه ما نريك الا بشرا مثلنا وما نريك اتبعك الا الذين هم اراذلنا بادي الراي وما نري لكم علينا من فضل بل نظنكم كذبين', 12, 23, 90, 1, 3, 224, false, NULL)
