    sajdah, sajdah_type
) VALUES
    (1501, 'tanzil-uthmani-v1.1', 11, 28, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةً مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَٰرِهُونَ', 'b166a695a65ad5f4aed466d0fb42ffc5558e233e9a22644152eae18be7545221', 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةً مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَٰرِهُونَ', 'b166a695a65ad5f4aed466d0fb42ffc5558e233e9a22644152eae18be7545221', 'b166a695a65ad5f4aed466d0fb42ffc5558e233e9a22644152eae18be7545221', NULL, 'قال يقوم ارءيتم ان كنت علي بينه من ربي وءاتيني رحمه من عنده فعميت عليكم انلزمكموها وانتم لها كرهون', 12, 23, 90, 1, 3, 224, false, NULL),
    (1502, 'tanzil-uthmani-v1.1', 11, 29, 'وَيَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', '17cf81b1523a0a453177405fb4c1891e453eb7fc33a8afe622366585d4e55f0d', 'وَيَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', '17cf81b1523a0a453177405fb4c1891e453eb7fc33a8afe622366585d4e55f0d', '17cf81b1523a0a453177405fb4c1891e453eb7fc33a8afe622366585d4e55f0d', NULL, 'ويقوم لا اسلكم عليه مالا ان اجري الا علي الله وما انا بطارد الذين ءامنوا انهم ملقوا ربهم ولكني اريكم قوما تجهلون', 12, 23, 90, 1, 3, 225, false, NULL),
    (1503, 'tanzil-uthmani-v1.1', 11, 30, 'وَيَٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ أَفَلَا تَذَكَّرُونَ', '941b33172620da50f8e7dee9f94e546af0d301a1b6bae87e71c5edac93c13330', 'وَيَٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ أَفَلَا تَذَكَّرُونَ', '941b33172620da50f8e7dee9f94e546af0d301a1b6bae87e71c5edac93c13330', '941b33172620da50f8e7dee9f94e546af0d301a1b6bae87e71c5edac93c13330', NULL, 'ويقوم من ينصرني من الله ان طردتهم افلا تذكرون', 12, 23, 90, 1, 3, 225, false, NULL),
    (1504, 'tanzil-uthmani-v1.1', 11, 31, 'وَلَآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ إِنِّى مَلَكٌ وَلَآ أَقُولُ لِلَّذِينَ تَزْدَرِىٓ أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ ٱللَّهُ خَيْرًا ٱللَّهُ أَعْلَمُ بِمَا فِىٓ أَنفُسِهِمْ إِنِّىٓ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'ed2460cac7029f606dd98bb9482ddcfa4416056e42ec918bb5ba199f54ce5589', 'وَلَآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ إِنِّى مَلَكٌ وَلَآ أَقُولُ لِلَّذِينَ تَزْدَرِىٓ أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ ٱللَّهُ خَيْرًا ٱللَّهُ أَعْلَمُ بِمَا فِىٓ أَنفُسِهِمْ إِنِّىٓ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ', 'ed2460cac7029f606dd98bb9482ddcfa4416056e42ec918bb5ba199f54ce5589', 'ed2460cac7029f606dd98bb9482ddcfa4416056e42ec918bb5ba199f54ce5589', NULL, 'ولا اقول لكم عندي خزائن الله ولا اعلم الغيب ولا اقول اني ملك ولا اقول للذين تزدري اعينكم لن يؤتيهم الله خيرا الله اعلم بما في انفسهم اني اذا لمن الظلمين', 12, 23, 90, 1, 3, 225, false, NULL),
    (1505, 'tanzil-uthmani-v1.1', 11, 32, 'قَالُوا۟ يَٰنُوحُ قَدْ جَٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', '004afa85641e9d74d6ecf5dab4696b3645da9cfb4ca323c19415de110b231350', 'قَالُوا۟ يَٰنُوحُ قَدْ جَٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', '004afa85641e9d74d6ecf5dab4696b3645da9cfb4ca323c19415de110b231350', '004afa85641e9d74d6ecf5dab4696b3645da9cfb4ca323c19415de110b231350', NULL, 'قالوا ينوح قد جدلتنا فاكثرت جدلنا فاتنا بما تعدنا ان كنت من الصدقين', 12, 23, 90, 1, 3, 225, false, NULL),
    (1506, 'tanzil-uthmani-v1.1', 11, 33, 'قَالَ إِنَّمَا يَأْتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ', '7b0d1e98fd9ad6b1c2e8c263fb66e479aea29110b95d75042735e795fbaf8a83', 'قَالَ إِنَّمَا يَأْتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ', '7b0d1e98fd9ad6b1c2e8c263fb66e479aea29110b95d75042735e795fbaf8a83', '7b0d1e98fd9ad6b1c2e8c263fb66e479aea29110b95d75042735e795fbaf8a83', NULL, 'قال انما ياتيكم به الله ان شاء وما انتم بمعجزين', 12, 23, 90, 1, 3, 225, false, NULL),
    (1507, 'tanzil-uthmani-v1.1', 11, 34, 'وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ', 'd5be6f242174bb35d50989d71b4d8396bb1362b4f09996e7efc8339e8ab641f8', 'وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ', 'd5be6f242174bb35d50989d71b4d8396bb1362b4f09996e7efc8339e8ab641f8', 'd5be6f242174bb35d50989d71b4d8396bb1362b4f09996e7efc8339e8ab641f8', NULL, 'ولا ينفعكم نصحي ان اردت ان انصح لكم ان كان الله يريد ان يغويكم هو ربكم واليه ترجعون', 12, 23, 90, 1, 3, 225, false, NULL),
    (1508, 'tanzil-uthmani-v1.1', 11, 35, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَعَلَىَّ إِجْرَامِى وَأَنَا۠ بَرِىٓءٌ مِّمَّا تُجْرِمُونَ', '275c725ccb9822f21a30849c68c74ec43b4ba16f045cd8ed5376d17af8cfce8e', 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَعَلَىَّ إِجْرَامِى وَأَنَا۠ بَرِىٓءٌ مِّمَّا تُجْرِمُونَ', '275c725ccb9822f21a30849c68c74ec43b4ba16f045cd8ed5376d17af8cfce8e', '275c725ccb9822f21a30849c68c74ec43b4ba16f045cd8ed5376d17af8cfce8e', NULL, 'ام يقولون افتريه قل ان افتريته فعلي اجرامي وانا بريء مما تجرمون', 12, 23, 90, 1, 3, 225, false, NULL),
    (1509, 'tanzil-uthmani-v1.1', 11, 36, 'وَأُوحِىَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ ءَامَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَفْعَلُونَ', '9c99e91028c81351a0dd62504f395425723540214295ace42d187811e93a82bc', 'وَأُوحِىَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ ءَامَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَفْعَلُونَ', '9c99e91028c81351a0dd62504f395425723540214295ace42d187811e93a82bc', '9c99e91028c81351a0dd62504f395425723540214295ace42d187811e93a82bc', NULL, 'واوحي الي نوح انه لن يؤمن من قومك الا من قد ءامن فلا تبتئس بما كانوا يفعلون', 12, 23, 90, 1, 3, 225, false, NULL),
    (1510, 'tanzil-uthmani-v1.1', 11, 37, 'وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ إِنَّهُم مُّغْرَقُونَ', '53f3c642f859a7f00fe105c77ea9b7d857da22fb3a874ab032e6340f28bc1f4a', 'وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ إِنَّهُم مُّغْرَقُونَ', '53f3c642f859a7f00fe105c77ea9b7d857da22fb3a874ab032e6340f28bc1f4a', '53f3c642f859a7f00fe105c77ea9b7d857da22fb3a874ab032e6340f28bc1f4a', NULL, 'واصنع الفلك باعيننا ووحينا ولا تخطبني في الذين ظلموا انهم مغرقون', 12, 23, 90, 1, 3, 225, false, NULL),
    (1511, 'tanzil-uthmani-v1.1', 11, 38, 'وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ', '58eb7c8d094679962c7c1e597959b7e8499a66ffb43445da5a56efd4d6c042ba', 'وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ', '58eb7c8d094679962c7c1e597959b7e8499a66ffb43445da5a56efd4d6c042ba', '58eb7c8d094679962c7c1e597959b7e8499a66ffb43445da5a56efd4d6c042ba', NULL, 'ويصنع الفلك وكلما مر عليه ملا من قومه سخروا منه قال ان تسخروا منا فانا نسخر منكم كما تسخرون', 12, 23, 90, 1, 3, 226, false, NULL),
    (1512, 'tanzil-uthmani-v1.1', 11, 39, 'فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', '722434051f235a46349d70d1d6d1a888a7e01cfaf07a191f99128343454a9e76', 'فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', '722434051f235a46349d70d1d6d1a888a7e01cfaf07a191f99128343454a9e76', '722434051f235a46349d70d1d6d1a888a7e01cfaf07a191f99128343454a9e76', NULL, 'فسوف تعلمون من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم', 12, 23, 90, 1, 3, 226, false, NULL),
    (1513, 'tanzil-uthmani-v1.1', 11, 40, 'حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌ', '9d21477ca64997bbfb15e99800938a844bb8b8d35810583a25f48f8befa5e857', 'حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌ', '9d21477ca64997bbfb15e99800938a844bb8b8d35810583a25f48f8befa5e857', '9d21477ca64997bbfb15e99800938a844bb8b8d35810583a25f48f8befa5e857', NULL, 'حتي اذا جاء امرنا وفار التنور قلنا احمل فيها من كل زوجين اثنين واهلك الا من سبق عليه القول ومن ءامن وما ءامن معه الا قليل', 12, 23, 90, 1, 3, 226, false, NULL),
    (1514, 'tanzil-uthmani-v1.1', 11, 41, 'وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ', 'b68a72dfc32c8ee82d1f25fb36b72750437226087ec170b3cd084548d76abeeb', 'وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ', 'b68a72dfc32c8ee82d1f25fb36b72750437226087ec170b3cd084548d76abeeb', 'b68a72dfc32c8ee82d1f25fb36b72750437226087ec170b3cd084548d76abeeb', NULL, 'وقال اركبوا فيها بسم الله مجريها ومرسيها ان ربي لغفور رحيم', 12, 23, 91, 1, 3, 226, false, NULL),
    (1515, 'tanzil-uthmani-v1.1', 11, 42, 'وَهِىَ تَجْرِى بِهِمْ فِى مَوْجٍ كَٱلْجِبَالِ وَنَادَىٰ نُوحٌ ٱبْنَهُۥ وَكَانَ فِى مَعْزِلٍ يَٰبُنَىَّ ٱرْكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلْكَٰفِرِينَ', 'a06ec9965fe519d8be6d323f1adf65c0a167babb9d6980fb91bf4ca9367d52fb', 'وَهِىَ تَجْرِى بِهِمْ فِى مَوْجٍ كَٱلْجِبَالِ وَنَادَىٰ نُوحٌ ٱبْنَهُۥ وَكَانَ فِى مَعْزِلٍ يَٰبُنَىَّ ٱرْكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلْكَٰفِرِينَ', 'a06ec9965fe519d8be6d323f1adf65c0a167babb9d6980fb91bf4ca9367d52fb', 'a06ec9965fe519d8be6d323f1adf65c0a167babb9d6980fb91bf4ca9367d52fb', NULL, 'وهي تجري بهم في موج كالجبال ونادي نوح ابنه وكان في معزل يبني اركب معنا ولا تكن مع الكفرين', 12, 23, 91, 1, 3, 226, false, NULL),
    (1516, 'tanzil-uthmani-v1.1', 11, 43, 'قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍ يَعْصِمُنِى مِنَ ٱلْمَآءِ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ', '33cd780d8d826935a7251b67c3b810cce174b6e7e448978539bec408c3d70cea', 'قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍ يَعْصِمُنِى مِنَ ٱلْمَآءِ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ', '33cd780d8d826935a7251b67c3b810cce174b6e7e448978539bec408c3d70cea', '33cd780d8d826935a7251b67c3b810cce174b6e7e448978539bec408c3d70cea', NULL, 'قال ساوي الي جبل يعصمني من الماء قال لا عاصم اليوم من امر الله الا من رحم وحال بينهما الموج فكان من المغرقين', 12, 23, 91, 1, 3, 226, false, NULL),
    (1517, 'tanzil-uthmani-v1.1', 11, 44, 'وَقِيلَ يَٰٓأَرْضُ ٱبْلَعِى مَآءَكِ وَيَٰسَمَآءُ أَقْلِعِى وَغِيضَ ٱلْمَآءُ وَقُضِىَ ٱلْأَمْرُ وَٱسْتَوَتْ عَلَى ٱلْجُودِىِّ وَقِيلَ بُعْدًا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', '63d97e9c942317030bedd354ebdbed636eb51d376a0b02605184c62af8d2cb3b', 'وَقِيلَ يَٰٓأَرْضُ ٱبْلَعِى مَآءَكِ وَيَٰسَمَآءُ أَقْلِعِى وَغِيضَ ٱلْمَآءُ وَقُضِىَ ٱلْأَمْرُ وَٱسْتَوَتْ عَلَى ٱلْجُودِىِّ وَقِيلَ بُعْدًا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', '63d97e9c942317030bedd354ebdbed636eb51d376a0b02605184c62af8d2cb3b', '63d97e9c942317030bedd354ebdbed636eb51d376a0b02605184c62af8d2cb3b', NULL, 'وقيل يارض ابلعي ماءك ويسماء اقلعي وغيض الماء وقضي الامر واستوت علي الجودي وقيل بعدا للقوم الظلمين', 12, 23, 91, 1, 3, 226, false, NULL),
    (1518, 'tanzil-uthmani-v1.1', 11, 45, 'وَنَادَىٰ نُوحٌ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبْنِى مِنْ أَهْلِى وَإِنَّ وَعْدَكَ ٱلْحَقُّ وَأَنتَ أَحْكَمُ ٱلْحَٰكِمِينَ', '5d045a8a40463dd86a6b3011705b62c7cf6968eaaf4b024225ddfe9200e04127', 'وَنَادَىٰ نُوحٌ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبْنِى مِنْ أَهْلِى وَإِنَّ وَعْدَكَ ٱلْحَقُّ وَأَنتَ أَحْكَمُ ٱلْحَٰكِمِينَ', '5d045a8a40463dd86a6b3011705b62c7cf6968eaaf4b024225ddfe9200e04127', '5d045a8a40463dd86a6b3011705b62c7cf6968eaaf4b024225ddfe9200e04127', NULL, 'ونادي نوح ربه فقال رب ان ابني من اهلي وان وعدك الحق وانت احكم الحكمين', 12, 23, 91, 1, 3, 226, false, NULL),
    (1519, 'tanzil-uthmani-v1.1', 11, 46, 'قَالَ يَٰنُوحُ إِنَّهُۥ لَيْسَ مِنْ أَهْلِكَ إِنَّهُۥ عَمَلٌ غَيْرُ صَٰلِحٍ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ إِنِّىٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلْجَٰهِلِينَ', '933f4e95f99fdd95e3ca4806f5376964e259fa03cc1b96f86405e13d032d9fe7', 'قَالَ يَٰنُوحُ إِنَّهُۥ لَيْسَ مِنْ أَهْلِكَ إِنَّهُۥ عَمَلٌ غَيْرُ صَٰلِحٍ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ إِنِّىٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلْجَٰهِلِينَ', '933f4e95f99fdd95e3ca4806f5376964e259fa03cc1b96f86405e13d032d9fe7', '933f4e95f99fdd95e3ca4806f5376964e259fa03cc1b96f86405e13d032d9fe7', NULL, 'قال ينوح انه ليس من اهلك انه عمل غير صلح فلا تسلن ما ليس لك به علم اني اعظك ان تكون من الجهلين', 12, 23, 91, 1, 3, 227, false, NULL),
    (1520, 'tanzil-uthmani-v1.1', 11, 47, 'قَالَ رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَٰسِرِينَ', '3eccc7d817e3ccded880ec9ba6b78d2c69ed7dde66fe3ace861f0ed4f364a944', 'قَالَ رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَٰسِرِينَ', '3eccc7d817e3ccded880ec9ba6b78d2c69ed7dde66fe3ace861f0ed4f364a944', '3eccc7d817e3ccded880ec9ba6b78d2c69ed7dde66fe3ace861f0ed4f364a944', NULL, 'قال رب اني اعوذ بك ان اسلك ما ليس لي به علم والا تغفر لي وترحمني اكن من الخسرين', 12, 23, 91, 1, 3, 227, false, NULL),
    (1521, 'tanzil-uthmani-v1.1', 11, 48, 'قِيلَ يَٰنُوحُ ٱهْبِطْ بِسَلَٰمٍ مِّنَّا وَبَرَكَٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍ مِّمَّن مَّعَكَ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌ', '9424b2e4a5c999c5ea53cc07f0180fb45bd77893bf21771224f36b613e99b8cd', 'قِيلَ يَٰنُوحُ ٱهْبِطْ بِسَلَٰمٍ مِّنَّا وَبَرَكَٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍ مِّمَّن مَّعَكَ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌ', '9424b2e4a5c999c5ea53cc07f0180fb45bd77893bf21771224f36b613e99b8cd', '9424b2e4a5c999c5ea53cc07f0180fb45bd77893bf21771224f36b613e99b8cd', NULL, 'قيل ينوح اهبط بسلم منا وبركت عليك وعلي امم ممن معك وامم سنمتعهم ثم يمسهم منا عذاب اليم', 12, 23, 91, 1, 3, 227, false, NULL),
    (1522, 'tanzil-uthmani-v1.1', 11, 49, 'تِلْكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهَآ إِلَيْكَ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَٰذَا فَٱصْبِرْ إِنَّ ٱلْعَٰقِبَةَ لِلْمُتَّقِينَ', 'bbf3ad013e5657ec14192a243a3591e9de93fadcc918b471fb1636f2a140557f', 'تِلْكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهَآ إِلَيْكَ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَٰذَا فَٱصْبِرْ إِنَّ ٱلْعَٰقِبَةَ لِلْمُتَّقِينَ', 'bbf3ad013e5657ec14192a243a3591e9de93fadcc918b471fb1636f2a140557f', 'bbf3ad013e5657ec14192a243a3591e9de93fadcc918b471fb1636f2a140557f', NULL, 'تلك من انباء الغيب نوحيها اليك ما كنت تعلمها انت ولا قومك من قبل هذا فاصبر ان العقبه للمتقين', 12, 23, 91, 1, 3, 227, false, NULL),
    (1523, 'tanzil-uthmani-v1.1', 11, 50, 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ', '589738b0ce3c8585fa84ebd333814c1771f8be361fe77a30d0dbe5d0e6babbf8', 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ', '589738b0ce3c8585fa84ebd333814c1771f8be361fe77a30d0dbe5d0e6babbf8', '589738b0ce3c8585fa84ebd333814c1771f8be361fe77a30d0dbe5d0e6babbf8', NULL, 'والي عاد اخاهم هودا قال يقوم اعبدوا الله ما لكم من اله غيره ان انتم الا مفترون', 12, 23, 91, 1, 3, 227, false, NULL),
    (1524, 'tanzil-uthmani-v1.1', 11, 51, 'يَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ أَفَلَا تَعْقِلُونَ', '3fc8a1ecd79a550ed049a5e3abdf0ffb14a2649691ee7b522742087d82a1f792', 'يَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ أَفَلَا تَعْقِلُونَ', '3fc8a1ecd79a550ed049a5e3abdf0ffb14a2649691ee7b522742087d82a1f792', '3fc8a1ecd79a550ed049a5e3abdf0ffb14a2649691ee7b522742087d82a1f792', NULL, 'يقوم لا اسلكم عليه اجرا ان اجري الا علي الذي فطرني افلا تعقلون', 12, 23, 91, 1, 3, 227, false, NULL),
    (1525, 'tanzil-uthmani-v1.1', 11, 52, 'وَيَٰقَوْمِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا۟ مُجْرِمِينَ', '5fb8f6f3fd502a211381d909fb6fda663b8a8e7cf049bbf3c2b53d4e63631293', 'وَيَٰقَوْمِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا۟ مُجْرِمِينَ', '5fb8f6f3fd502a211381d909fb6fda663b8a8e7cf049bbf3c2b53d4e63631293', '5fb8f6f3fd502a211381d909fb6fda663b8a8e7cf049bbf3c2b53d4e63631293', NULL, 'ويقوم استغفروا ربكم ثم توبوا اليه يرسل السماء عليكم مدرارا ويزدكم قوه الي قوتكم ولا تتولوا مجرمين', 12, 23, 91, 1, 3, 227, false, NULL),
    (1526, 'tanzil-uthmani-v1.1', 11, 53, 'قَالُوا۟ يَٰهُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِكِىٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', '3d8bc99b5cb63b323f7840bb7a074e3de9795368ea6abe13366296aea59117e4', 'قَالُوا۟ يَٰهُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِكِىٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', '3d8bc99b5cb63b323f7840bb7a074e3de9795368ea6abe13366296aea59117e4', '3d8bc99b5cb63b323f7840bb7a074e3de9795368ea6abe13366296aea59117e4', NULL, 'قالوا يهود ما جئتنا ببينه وما نحن بتاركي ءالهتنا عن قولك وما نحن لك بمؤمنين', 12, 23, 91, 1, 3, 227, false, NULL),
    (1527, 'tanzil-uthmani-v1.1', 11, 54, 'إِن نَّقُولُ إِلَّا ٱعْتَرَىٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءٍ قَالَ إِنِّىٓ أُشْهِدُ ٱللَّهَ وَٱشْهَدُوٓا۟ أَنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'b3ef028ee23844ddb47709b5439b6c457d5b034c0090edcd83987bcf75fd79d1', 'إِن نَّقُولُ إِلَّا ٱعْتَرَىٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءٍ قَالَ إِنِّىٓ أُشْهِدُ ٱللَّهَ وَٱشْهَدُوٓا۟ أَنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ', 'b3ef028ee23844ddb47709b5439b6c457d5b034c0090edcd83987bcf75fd79d1', 'b3ef028ee23844ddb47709b5439b6c457d5b034c0090edcd83987bcf75fd79d1', NULL, 'ان نقول الا اعتريك بعض ءالهتنا بسوء قال اني اشهد الله واشهدوا اني بريء مما تشركون', 12, 23, 91, 1, 3, 228, false, NULL),
    (1528, 'tanzil-uthmani-v1.1', 11, 55, 'مِن دُونِهِۦ فَكِيدُونِى جَمِيعًا ثُمَّ لَا تُنظِرُونِ', 'b95c64d545d0b64a02cd89a301c80d6cdfb35bbc373b920716da66071658e971', 'مِن دُونِهِۦ فَكِيدُونِى جَمِيعًا ثُمَّ لَا تُنظِرُونِ', 'b95c64d545d0b64a02cd89a301c80d6cdfb35bbc373b920716da66071658e971', 'b95c64d545d0b64a02cd89a301c80d6cdfb35bbc373b920716da66071658e971', NULL, 'من دونه فكيدوني جميعا ثم لا تنظرون', 12, 23, 91, 1, 3, 228, false, NULL),
    (1529, 'tanzil-uthmani-v1.1', 11, 56, 'إِنِّى تَوَكَّلْتُ عَلَى ٱللَّهِ رَبِّى وَرَبِّكُم مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذٌۢ بِنَاصِيَتِهَآ إِنَّ رَبِّى عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'd6dabc65b7ff47acfa4693d7cb9abf9b7f52965418450615ca34810b5a359342', 'إِنِّى تَوَكَّلْتُ عَلَى ٱللَّهِ رَبِّى وَرَبِّكُم مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذٌۢ بِنَاصِيَتِهَآ إِنَّ رَبِّى عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'd6dabc65b7ff47acfa4693d7cb9abf9b7f52965418450615ca34810b5a359342', 'd6dabc65b7ff47acfa4693d7cb9abf9b7f52965418450615ca34810b5a359342', NULL, 'اني توكلت علي الله ربي وربكم ما من دابه الا هو ءاخذ بناصيتها ان ربي علي صرط مستقيم', 12, 23, 91, 1, 3, 228, false, NULL),
    (1530, 'tanzil-uthmani-v1.1', 11, 57, 'فَإِن تَوَلَّوْا۟ فَقَدْ أَبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـًٔا إِنَّ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', '861d00cd4e9c6ef36baa8672c9cf5c3483e93ef062cefdc983d1102cd34b0b99', 'فَإِن تَوَلَّوْا۟ فَقَدْ أَبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـًٔا إِنَّ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', '861d00cd4e9c6ef36baa8672c9cf5c3483e93ef062cefdc983d1102cd34b0b99', '861d00cd4e9c6ef36baa8672c9cf5c3483e93ef062cefdc983d1102cd34b0b99', NULL, 'فان تولوا فقد ابلغتكم ما ارسلت به اليكم ويستخلف ربي قوما غيركم ولا تضرونه شيا ان ربي علي كل شيء حفيظ', 12, 23, 91, 1, 3, 228, false, NULL),
    (1531, 'tanzil-uthmani-v1.1', 11, 58, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَنَجَّيْنَٰهُم مِّنْ عَذَابٍ غَلِيظٍ', 'd4d4aa7b0421f7aac35cb55e631142c07a75a1f9f304311e50c8810221fff5f4', 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَنَجَّيْنَٰهُم مِّنْ عَذَابٍ غَلِيظٍ', 'd4d4aa7b0421f7aac35cb55e631142c07a75a1f9f304311e50c8810221fff5f4', 'd4d4aa7b0421f7aac35cb55e631142c07a75a1f9f304311e50c8810221fff5f4', NULL, 'ولما جاء امرنا نجينا هودا والذين ءامنوا معه برحمه منا ونجينهم من عذاب غليظ', 12, 23, 91, 1, 3, 228, false, NULL),
    (1532, 'tanzil-uthmani-v1.1', 11, 59, 'وَتِلْكَ عَادٌ جَحَدُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَعَصَوْا۟ رُسُلَهُۥ وَٱتَّبَعُوٓا۟ أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ', '0282db0fd3dc91787b44045cd27542ed952f7ffb94b7ae0d696ab003370f46bb', 'وَتِلْكَ عَادٌ جَحَدُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَعَصَوْا۟ رُسُلَهُۥ وَٱتَّبَعُوٓا۟ أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ', '0282db0fd3dc91787b44045cd27542ed952f7ffb94b7ae0d696ab003370f46bb', '0282db0fd3dc91787b44045cd27542ed952f7ffb94b7ae0d696ab003370f46bb', NULL, 'وتلك عاد جحدوا بايت ربهم وعصوا رسله واتبعوا امر كل جبار عنيد', 12, 23, 91, 1, 3, 228, false, NULL),
    (1533, 'tanzil-uthmani-v1.1', 11, 60, 'وَأُتْبِعُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ عَادًا كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّعَادٍ قَوْمِ هُودٍ', '07c8402f98ff3d933f9d9953a3001ac1fa5dedaae5303467bc1c762543d591af', 'وَأُتْبِعُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ عَادًا كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّعَادٍ قَوْمِ هُودٍ', '07c8402f98ff3d933f9d9953a3001ac1fa5dedaae5303467bc1c762543d591af', '07c8402f98ff3d933f9d9953a3001ac1fa5dedaae5303467bc1c762543d591af', NULL, 'واتبعوا في هذه الدنيا لعنه ويوم القيمه الا ان عادا كفروا ربهم الا بعدا لعاد قوم هود', 12, 23, 91, 1, 3, 228, false, NULL),
    (1534, 'tanzil-uthmani-v1.1', 11, 61, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا فَٱسْتَغْفِرُوهُ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى قَرِيبٌ مُّجِيبٌ', '117e8cff9c058d24d69b9823678e7ffbd9a8112c7e33814a5fc4d8b193d8057e', 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا فَٱسْتَغْفِرُوهُ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى قَرِيبٌ مُّجِيبٌ', '117e8cff9c058d24d69b9823678e7ffbd9a8112c7e33814a5fc4d8b193d8057e', '117e8cff9c058d24d69b9823678e7ffbd9a8112c7e33814a5fc4d8b193d8057e', NULL, 'والي ثمود اخاهم صلحا قال يقوم اعبدوا الله ما لكم من اله غيره هو انشاكم من الارض واستعمركم فيها فاستغفروه ثم توبوا اليه ان ربي قريب مجيب', 12, 23, 92, 1, 3, 228, false, NULL),
    (1535, 'tanzil-uthmani-v1.1', 11, 62, 'قَالُوا۟ يَٰصَٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَٰذَآ أَتَنْهَىٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِى شَكٍّ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبٍ', '9fc02b19abede3ff317e41b0fc27e2dc905460726686e8ef09549f3a64239656', 'قَالُوا۟ يَٰصَٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَٰذَآ أَتَنْهَىٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِى شَكٍّ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبٍ', '9fc02b19abede3ff317e41b0fc27e2dc905460726686e8ef09549f3a64239656', '9fc02b19abede3ff317e41b0fc27e2dc905460726686e8ef09549f3a64239656', NULL, 'قالوا يصلح قد كنت فينا مرجوا قبل هذا اتنهينا ان نعبد ما يعبد ءاباؤنا واننا لفي شك مما تدعونا اليه مريب', 12, 23, 92, 1, 3, 228, false, NULL),
    (1536, 'tanzil-uthmani-v1.1', 11, 63, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى مِنْهُ رَحْمَةً فَمَن يَنصُرُنِى مِنَ ٱللَّهِ إِنْ عَصَيْتُهُۥ فَمَا تَزِيدُونَنِى غَيْرَ تَخْسِيرٍ', '8661aca07ef4f7e8e13c73fae9f388d76b7a464c3c9975a789ae6915a8e55add', 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَءَاتَىٰنِى مِنْهُ رَحْمَةً فَمَن يَنصُرُنِى مِنَ ٱللَّهِ إِنْ عَصَيْتُهُۥ فَمَا تَزِيدُونَنِى غَيْرَ تَخْسِيرٍ', '8661aca07ef4f7e8e13c73fae9f388d76b7a464c3c9975a789ae6915a8e55add', '8661aca07ef4f7e8e13c73fae9f388d76b7a464c3c9975a789ae6915a8e55add', NULL, 'قال يقوم ارءيتم ان كنت علي بينه من ربي وءاتيني منه رحمه فمن ينصرني من الله ان عصيته فما تزيدونني غير تخسير', 12, 23, 92, 1, 3, 229, false, NULL),
    (1537, 'tanzil-uthmani-v1.1', 11, 64, 'وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ', 'ab05c5ff975d859ebba328748e43ac92ac7732f6aaff4f90ca89bbacc6b7c78c', 'وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ', 'ab05c5ff975d859ebba328748e43ac92ac7732f6aaff4f90ca89bbacc6b7c78c', 'ab05c5ff975d859ebba328748e43ac92ac7732f6aaff4f90ca89bbacc6b7c78c', NULL, 'ويقوم هذه ناقه الله لكم ءايه فذروها تاكل في ارض الله ولا تمسوها بسوء فياخذكم عذاب قريب', 12, 23, 92, 1, 3, 229, false, NULL),
    (1538, 'tanzil-uthmani-v1.1', 11, 65, 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِى دَارِكُمْ ثَلَٰثَةَ أَيَّامٍ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ', '908bfc748027f30964679a4ef0c69f7aeedd1c1897a21ad98d7c27ef32dea7fa', 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِى دَارِكُمْ ثَلَٰثَةَ أَيَّامٍ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ', '908bfc748027f30964679a4ef0c69f7aeedd1c1897a21ad98d7c27ef32dea7fa', '908bfc748027f30964679a4ef0c69f7aeedd1c1897a21ad98d7c27ef32dea7fa', NULL, 'فعقروها فقال تمتعوا في داركم ثلثه ايام ذلك وعد غير مكذوب', 12, 23, 92, 1, 3, 229, false, NULL),
    (1539, 'tanzil-uthmani-v1.1', 11, 66, 'فَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا صَٰلِحًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَمِنْ خِزْىِ يَوْمِئِذٍ إِنَّ رَبَّكَ هُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', '3338736ced0ddcc19216c7c323f8688a4f17d8cae1b1af93aac74ab28705817f', 'فَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا صَٰلِحًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَمِنْ خِزْىِ يَوْمِئِذٍ إِنَّ رَبَّكَ هُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', '3338736ced0ddcc19216c7c323f8688a4f17d8cae1b1af93aac74ab28705817f', '3338736ced0ddcc19216c7c323f8688a4f17d8cae1b1af93aac74ab28705817f', NULL, 'فلما جاء امرنا نجينا صلحا والذين ءامنوا معه برحمه منا ومن خزي يومئذ ان ربك هو القوي العزيز', 12, 23, 92, 1, 3, 229, false, NULL),
    (1540, 'tanzil-uthmani-v1.1', 11, 67, 'وَأَخَذَ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 'ba04d57bc30304f72c04df0f14bf76fba4e06c9cd84867424ba219e594542966', 'وَأَخَذَ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 'ba04d57bc30304f72c04df0f14bf76fba4e06c9cd84867424ba219e594542966', 'ba04d57bc30304f72c04df0f14bf76fba4e06c9cd84867424ba219e594542966', NULL, 'واخذ الذين ظلموا الصيحه فاصبحوا في ديرهم جثمين', 12, 23, 92, 1, 3, 229, false, NULL),
    (1541, 'tanzil-uthmani-v1.1', 11, 68, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّثَمُودَ', '1e6a8e6069a3535d54b01101f7f54d14ccaa9831fb151bd6f9492e94267e2b1a', 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ أَلَا بُعْدًا لِّثَمُودَ', '1e6a8e6069a3535d54b01101f7f54d14ccaa9831fb151bd6f9492e94267e2b1a', '1e6a8e6069a3535d54b01101f7f54d14ccaa9831fb151bd6f9492e94267e2b1a', NULL, 'كان لم يغنوا فيها الا ان ثمودا كفروا ربهم الا بعدا لثمود', 12, 23, 92, 1, 3, 229, false, NULL),
    (1542, 'tanzil-uthmani-v1.1', 11, 69, 'وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوا۟ سَلَٰمًا قَالَ سَلَٰمٌ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذٍ', 'b2f5bf746159c94ea8359272f1b0b8cf4b86bf82a5a418535a2a5d7a3e47e232', 'وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوا۟ سَلَٰمًا قَالَ سَلَٰمٌ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذٍ', 'b2f5bf746159c94ea8359272f1b0b8cf4b86bf82a5a418535a2a5d7a3e47e232', 'b2f5bf746159c94ea8359272f1b0b8cf4b86bf82a5a418535a2a5d7a3e47e232', NULL, 'ولقد جاءت رسلنا ابرهيم بالبشري قالوا سلما قال سلم فما لبث ان جاء بعجل حنيذ', 12, 23, 92, 1, 3, 229, false, NULL),
    (1543, 'tanzil-uthmani-v1.1', 11, 70, 'فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍ', '56769f33dcc0ffd4b81a6e9e46259cd1d97541741a795f41b30e2f0126fdc073', 'فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍ', '56769f33dcc0ffd4b81a6e9e46259cd1d97541741a795f41b30e2f0126fdc073', '56769f33dcc0ffd4b81a6e9e46259cd1d97541741a795f41b30e2f0126fdc073', NULL, 'فلما رءا ايديهم لا تصل اليه نكرهم واوجس منهم خيفه قالوا لا تخف انا ارسلنا الي قوم لوط', 12, 23, 92, 1, 3, 229, false, NULL),
    (1544, 'tanzil-uthmani-v1.1', 11, 71, 'وَٱمْرَأَتُهُۥ قَآئِمَةٌ فَضَحِكَتْ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ وَمِن وَرَآءِ إِسْحَٰقَ يَعْقُوبَ', '5ec635a6c995cf711b9034fcf0e6653db4ba1978a0e65467fb3757d1e2d8b152', 'وَٱمْرَأَتُهُۥ قَآئِمَةٌ فَضَحِكَتْ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ وَمِن وَرَآءِ إِسْحَٰقَ يَعْقُوبَ', '5ec635a6c995cf711b9034fcf0e6653db4ba1978a0e65467fb3757d1e2d8b152', '5ec635a6c995cf711b9034fcf0e6653db4ba1978a0e65467fb3757d1e2d8b152', NULL, 'وامراته قائمه فضحكت فبشرنها باسحق ومن وراء اسحق يعقوب', 12, 23, 92, 1, 3, 229, false, NULL),
    (1545, 'tanzil-uthmani-v1.1', 11, 72, 'قَالَتْ يَٰوَيْلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٌ وَهَٰذَا بَعْلِى شَيْخًا إِنَّ هَٰذَا لَشَىْءٌ عَجِيبٌ', 'bf78427d4462a4fbdcca9f2358eb4b571f65a1df709ce018aa6b27f9bfdf356f', 'قَالَتْ يَٰوَيْلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٌ وَهَٰذَا بَعْلِى شَيْخًا إِنَّ هَٰذَا لَشَىْءٌ عَجِيبٌ', 'bf78427d4462a4fbdcca9f2358eb4b571f65a1df709ce018aa6b27f9bfdf356f', 'bf78427d4462a4fbdcca9f2358eb4b571f65a1df709ce018aa6b27f9bfdf356f', NULL, 'قالت يويلتي ءالد وانا عجوز وهذا بعلي شيخا ان هذا لشيء عجيب', 12, 23, 92, 1, 3, 230, false, NULL),
    (1546, 'tanzil-uthmani-v1.1', 11, 73, 'قَالُوٓا۟ أَتَعْجَبِينَ مِنْ أَمْرِ ٱللَّهِ رَحْمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيْكُمْ أَهْلَ ٱلْبَيْتِ إِنَّهُۥ حَمِيدٌ مَّجِيدٌ', 'dfc62da22c297fbaabfdd8a93be6e601776070051b805b68eb5138480f3ddc38', 'قَالُوٓا۟ أَتَعْجَبِينَ مِنْ أَمْرِ ٱللَّهِ رَحْمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيْكُمْ أَهْلَ ٱلْبَيْتِ إِنَّهُۥ حَمِيدٌ مَّجِيدٌ', 'dfc62da22c297fbaabfdd8a93be6e601776070051b805b68eb5138480f3ddc38', 'dfc62da22c297fbaabfdd8a93be6e601776070051b805b68eb5138480f3ddc38', NULL, 'قالوا اتعجبين من امر الله رحمت الله وبركته عليكم اهل البيت انه حميد مجيد', 12, 23, 92, 1, 3, 230, false, NULL),
    (1547, 'tanzil-uthmani-v1.1', 11, 74, 'فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ ٱلرَّوْعُ وَجَآءَتْهُ ٱلْبُشْرَىٰ يُجَٰدِلُنَا فِى قَوْمِ لُوطٍ', '6b9bd5641776e530ac5eed7eee480219abd8bc6e9e051471fec69ec5382a9587', 'فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ ٱلرَّوْعُ وَجَآءَتْهُ ٱلْبُشْرَىٰ يُجَٰدِلُنَا فِى قَوْمِ لُوطٍ', '6b9bd5641776e530ac5eed7eee480219abd8bc6e9e051471fec69ec5382a9587', '6b9bd5641776e530ac5eed7eee480219abd8bc6e9e051471fec69ec5382a9587', NULL, 'فلما ذهب عن ابرهيم الروع وجاءته البشري يجدلنا في قوم لوط', 12, 23, 92, 1, 3, 230, false, NULL),
    (1548, 'tanzil-uthmani-v1.1', 11, 75, 'إِنَّ إِبْرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٌ مُّنِيبٌ', '405ce0da0c19387bbeaedf541bdcd77e0f30e86ce4eb99272dd1645ca2ea1a2e', 'إِنَّ إِبْرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٌ مُّنِيبٌ', '405ce0da0c19387bbeaedf541bdcd77e0f30e86ce4eb99272dd1645ca2ea1a2e', '405ce0da0c19387bbeaedf541bdcd77e0f30e86ce4eb99272dd1645ca2ea1a2e', NULL, 'ان ابرهيم لحليم اوه منيب', 12, 23, 92, 1, 3, 230, false, NULL),
    (1549, 'tanzil-uthmani-v1.1', 11, 76, 'يَٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَٰذَآ إِنَّهُۥ قَدْ جَآءَ أَمْرُ رَبِّكَ وَإِنَّهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ', 'ec88c57f49931c084c10ec2d5e6802c891fb28a492cb43737b669f3306716f43', 'يَٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَٰذَآ إِنَّهُۥ قَدْ جَآءَ أَمْرُ رَبِّكَ وَإِنَّهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ', 'ec88c57f49931c084c10ec2d5e6802c891fb28a492cb43737b669f3306716f43', 'ec88c57f49931c084c10ec2d5e6802c891fb28a492cb43737b669f3306716f43', NULL, 'يابرهيم اعرض عن هذا انه قد جاء امر ربك وانهم ءاتيهم عذاب غير مردود', 12, 23, 92, 1, 3, 230, false, NULL),
    (1550, 'tanzil-uthmani-v1.1', 11, 77, 'وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌ', '6945b8a0e8f6e9519a49759fa460e569ff5070e6d80984dbef1cc490d4884c09', 'وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌ', '6945b8a0e8f6e9519a49759fa460e569ff5070e6d80984dbef1cc490d4884c09', '6945b8a0e8f6e9519a49759fa460e569ff5070e6d80984dbef1cc490d4884c09', NULL, 'ولما جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقال هذا يوم عصيب', 12, 23, 92, 1, 3, 230, false, NULL),
    (1551, 'tanzil-uthmani-v1.1', 11, 78, 'وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ قَالَ يَٰقَوْمِ هَٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ', '81f7ad5c51154d053b379af3db1be543df2fb7924b7e8ce2316cb87b7a208d5c', 'وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ قَالَ يَٰقَوْمِ هَٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ', '81f7ad5c51154d053b379af3db1be543df2fb7924b7e8ce2316cb87b7a208d5c', '81f7ad5c51154d053b379af3db1be543df2fb7924b7e8ce2316cb87b7a208d5c', NULL, 'وجاءه قومه يهرعون اليه ومن قبل كانوا يعملون السيات قال يقوم هؤلاء بناتي هن اطهر لكم فاتقوا الله ولا تخزون في ضيفي اليس منكم رجل رشيد', 12, 23, 92, 1, 3, 230, false, NULL),
    (1552, 'tanzil-uthmani-v1.1', 11, 79, 'قَالُوا۟ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ', '52d936e6a5919cd33a4103306fb1e0fd726509aee1db9e9ea8e399c7c2803e0b', 'قَالُوا۟ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ', '52d936e6a5919cd33a4103306fb1e0fd726509aee1db9e9ea8e399c7c2803e0b', '52d936e6a5919cd33a4103306fb1e0fd726509aee1db9e9ea8e399c7c2803e0b', NULL, 'قالوا لقد علمت ما لنا في بناتك من حق وانك لتعلم ما نريد', 12, 23, 92, 1, 3, 230, false, NULL),
    (1553, 'tanzil-uthmani-v1.1', 11, 80, 'قَالَ لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍ شَدِيدٍ', 'c52d28e567025b67018cbf661baa298c2970e211983cbcd1c08ca85a255d46fa', 'قَالَ لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍ شَدِيدٍ', 'c52d28e567025b67018cbf661baa298c2970e211983cbcd1c08ca85a255d46fa', 'c52d28e567025b67018cbf661baa298c2970e211983cbcd1c08ca85a255d46fa', NULL, 'قال لو ان لي بكم قوه او ءاوي الي ركن شديد', 12, 23, 92, 1, 3, 230, false, NULL),
    (1554, 'tanzil-uthmani-v1.1', 11, 81, 'قَالُوا۟ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓا۟ إِلَيْكَ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا ٱمْرَأَتَكَ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمْ إِنَّ مَوْعِدَهُمُ ٱلصُّبْحُ أَلَيْسَ ٱلصُّبْحُ بِقَرِيبٍ', 'ea1401648527f1e1896d8ace3ac38c8f4fd21b3c5da3e8f3f74d345ab8727e6f', 'قَالُوا۟ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓا۟ إِلَيْكَ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ ٱلَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا ٱمْرَأَتَكَ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمْ إِنَّ مَوْعِدَهُمُ ٱلصُّبْحُ أَلَيْسَ ٱلصُّبْحُ بِقَرِيبٍ', 'ea1401648527f1e1896d8ace3ac38c8f4fd21b3c5da3e8f3f74d345ab8727e6f', 'ea1401648527f1e1896d8ace3ac38c8f4fd21b3c5da3e8f3f74d345ab8727e6f', NULL, 'قالوا يلوط انا رسل ربك لن يصلوا اليك فاسر باهلك بقطع من اليل ولا يلتفت منكم احد الا امراتك انه مصيبها ما اصابهم ان موعدهم الصبح اليس الصبح بقريب', 12, 23, 92, 1, 3, 230, false, NULL),
    (1555, 'tanzil-uthmani-v1.1', 11, 82, 'فَلَمَّا جَآءَ أَمْرُنَا جَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ مَّنضُودٍ', '23ea360d99548553cb1a0c6fdc5f09f95bc7419baf554e6bf0e94351be40e58b', 'فَلَمَّا جَآءَ أَمْرُنَا جَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ مَّنضُودٍ', '23ea360d99548553cb1a0c6fdc5f09f95bc7419baf554e6bf0e94351be40e58b', '23ea360d99548553cb1a0c6fdc5f09f95bc7419baf554e6bf0e94351be40e58b', NULL, 'فلما جاء امرنا جعلنا عليها سافلها وامطرنا عليها حجاره من سجيل منضود', 12, 23, 92, 1, 3, 231, false, NULL),
    (1556, 'tanzil-uthmani-v1.1', 11, 83, 'مُّسَوَّمَةً عِندَ رَبِّكَ وَمَا هِىَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٍ', '65e960885b8e12d8afc2e56d7a94d47cdd8550174d4772080d79c21c96b81f13', 'مُّسَوَّمَةً عِندَ رَبِّكَ وَمَا هِىَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٍ', '65e960885b8e12d8afc2e56d7a94d47cdd8550174d4772080d79c21c96b81f13', '65e960885b8e12d8afc2e56d7a94d47cdd8550174d4772080d79c21c96b81f13', NULL, 'مسومه عند ربك وما هي من الظلمين ببعيد', 12, 23, 92, 1, 3, 231, false, NULL),
    (1557, 'tanzil-uthmani-v1.1', 11, 84, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ وَلَا تَنقُصُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ إِنِّىٓ أَرَىٰكُم بِخَيْرٍ وَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ', '8614008de9ab4e3063d3d4ad59dc8a8181a2e3d037bd8c7df14764e5ef22546b', 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ وَلَا تَنقُصُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ إِنِّىٓ أَرَىٰكُم بِخَيْرٍ وَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ', '8614008de9ab4e3063d3d4ad59dc8a8181a2e3d037bd8c7df14764e5ef22546b', '8614008de9ab4e3063d3d4ad59dc8a8181a2e3d037bd8c7df14764e5ef22546b', NULL, 'والي مدين اخاهم شعيبا قال يقوم اعبدوا الله ما لكم من اله غيره ولا تنقصوا المكيال والميزان اني اريكم بخير واني اخاف عليكم عذاب يوم محيط', 12, 24, 93, 1, 3, 231, false, NULL),
    (1558, 'tanzil-uthmani-v1.1', 11, 85, 'وَيَٰقَوْمِ أَوْفُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ بِٱلْقِسْطِ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'b0b49397bad817981ddcfdfaad735469393d585ead14c33bd9149464b6dc883a', 'وَيَٰقَوْمِ أَوْفُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ بِٱلْقِسْطِ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 'b0b49397bad817981ddcfdfaad735469393d585ead14c33bd9149464b6dc883a', 'b0b49397bad817981ddcfdfaad735469393d585ead14c33bd9149464b6dc883a', NULL, 'ويقوم اوفوا المكيال والميزان بالقسط ولا تبخسوا الناس اشياءهم ولا تعثوا في الارض مفسدين', 12, 24, 93, 1, 3, 231, false, NULL),
    (1559, 'tanzil-uthmani-v1.1', 11, 86, 'بَقِيَّتُ ٱللَّهِ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', '973bff0996d941aa3939e151ce1cb8ebaeec903cbbed411c1ed7a7f55c3178a1', 'بَقِيَّتُ ٱللَّهِ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ', '973bff0996d941aa3939e151ce1cb8ebaeec903cbbed411c1ed7a7f55c3178a1', '973bff0996d941aa3939e151ce1cb8ebaeec903cbbed411c1ed7a7f55c3178a1', NULL, 'بقيت الله خير لكم ان كنتم مؤمنين وما انا عليكم بحفيظ', 12, 24, 93, 1, 3, 231, false, NULL),
    (1560, 'tanzil-uthmani-v1.1', 11, 87, 'قَالُوا۟ يَٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَٰٓؤُا۟ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ', '35678c77a8d31e2e2e598dadc5d6baffb8a6abfae9fe1f9603bddc3fabb456a8', 'قَالُوا۟ يَٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَٰٓؤُا۟ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ', '35678c77a8d31e2e2e598dadc5d6baffb8a6abfae9fe1f9603bddc3fabb456a8', '35678c77a8d31e2e2e598dadc5d6baffb8a6abfae9fe1f9603bddc3fabb456a8', NULL, 'قالوا يشعيب اصلوتك تامرك ان نترك ما يعبد ءاباؤنا او ان نفعل في امولنا ما نشؤا انك لانت الحليم الرشيد', 12, 24, 93, 1, 3, 231, false, NULL),
    (1561, 'tanzil-uthmani-v1.1', 11, 88, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًا وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَٰحَ مَا ٱسْتَطَعْتُ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', '31e3f73de916f784d88d3e226dbfdb2171bad53f49119711ce1dd418ff69d02d', 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًا وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَٰحَ مَا ٱسْتَطَعْتُ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', '31e3f73de916f784d88d3e226dbfdb2171bad53f49119711ce1dd418ff69d02d', '31e3f73de916f784d88d3e226dbfdb2171bad53f49119711ce1dd418ff69d02d', NULL, 'قال يقوم ارءيتم ان كنت علي بينه من ربي ورزقني منه رزقا حسنا وما اريد ان اخالفكم الي ما انهيكم عنه ان اريد الا الاصلح ما استطعت وما توفيقي الا بالله عليه توكلت واليه انيب', 12, 24, 93, 1, 3, 231, false, NULL),
    (1562, 'tanzil-uthmani-v1.1', 11, 89, 'وَيَٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِىٓ أَن يُصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَٰلِحٍ وَمَا قَوْمُ لُوطٍ مِّنكُم بِبَعِيدٍ', 'b1502d90dc30277948e8f1dc50cfee9f459c1ebe5e978e16a85abe21b160f470', 'وَيَٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِىٓ أَن يُصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَٰلِحٍ وَمَا قَوْمُ لُوطٍ مِّنكُم بِبَعِيدٍ', 'b1502d90dc30277948e8f1dc50cfee9f459c1ebe5e978e16a85abe21b160f470', 'b1502d90dc30277948e8f1dc50cfee9f459c1ebe5e978e16a85abe21b160f470', NULL, 'ويقوم لا يجرمنكم شقاقي ان يصيبكم مثل ما اصاب قوم نوح او قوم هود او قوم صلح وما قوم لوط منكم ببعيد', 12, 24, 93, 1, 3, 232, false, NULL),
    (1563, 'tanzil-uthmani-v1.1', 11, 90, 'وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى رَحِيمٌ وَدُودٌ', '09bbeafc2ba4d7a6eaa6b88b00d824d72e5da8820ed7785d7b3795c5aa7b5df6', 'وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ إِنَّ رَبِّى رَحِيمٌ وَدُودٌ', '09bbeafc2ba4d7a6eaa6b88b00d824d72e5da8820ed7785d7b3795c5aa7b5df6', '09bbeafc2ba4d7a6eaa6b88b00d824d72e5da8820ed7785d7b3795c5aa7b5df6', NULL, 'واستغفروا ربكم ثم توبوا اليه ان ربي رحيم ودود', 12, 24, 93, 1, 3, 232, false, NULL),
    (1564, 'tanzil-uthmani-v1.1', 11, 91, 'قَالُوا۟ يَٰشُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًا وَلَوْلَا رَهْطُكَ لَرَجَمْنَٰكَ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزٍ', '819d92a8210a3aff86d4b4e1a491e84772da601099d844610737f75444c16281', 'قَالُوا۟ يَٰشُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًا وَلَوْلَا رَهْطُكَ لَرَجَمْنَٰكَ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزٍ', '819d92a8210a3aff86d4b4e1a491e84772da601099d844610737f75444c16281', '819d92a8210a3aff86d4b4e1a491e84772da601099d844610737f75444c16281', NULL, 'قالوا يشعيب ما نفقه كثيرا مما تقول وانا لنريك فينا ضعيفا ولولا رهطك لرجمنك وما انت علينا بعزيز', 12, 24, 93, 1, 3, 232, false, NULL),
    (1565, 'tanzil-uthmani-v1.1', 11, 92, 'قَالَ يَٰقَوْمِ أَرَهْطِىٓ أَعَزُّ عَلَيْكُم مِّنَ ٱللَّهِ وَٱتَّخَذْتُمُوهُ وَرَآءَكُمْ ظِهْرِيًّا إِنَّ رَبِّى بِمَا تَعْمَلُونَ مُحِيطٌ', '83a78418db811e17498fea8f6ad9ca513c9962b9c5e9e84957dc185d5d90bb37', 'قَالَ يَٰقَوْمِ أَرَهْطِىٓ أَعَزُّ عَلَيْكُم مِّنَ ٱللَّهِ وَٱتَّخَذْتُمُوهُ وَرَآءَكُمْ ظِهْرِيًّا إِنَّ رَبِّى بِمَا تَعْمَلُونَ مُحِيطٌ', '83a78418db811e17498fea8f6ad9ca513c9962b9c5e9e84957dc185d5d90bb37', '83a78418db811e17498fea8f6ad9ca513c9962b9c5e9e84957dc185d5d90bb37', NULL, 'قال يقوم ارهطي اعز عليكم من الله واتخذتموه وراءكم ظهريا ان ربي بما تعملون محيط', 12, 24, 93, 1, 3, 232, false, NULL),
    (1566, 'tanzil-uthmani-v1.1', 11, 93, 'وَيَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَٰذِبٌ وَٱرْتَقِبُوٓا۟ إِنِّى مَعَكُمْ رَقِيبٌ', '0056650f2d8fd53092162eeaac1faddd16c2998f99a7e3612181e64084845911', 'وَيَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَٰذِبٌ وَٱرْتَقِبُوٓا۟ إِنِّى مَعَكُمْ رَقِيبٌ', '0056650f2d8fd53092162eeaac1faddd16c2998f99a7e3612181e64084845911', '0056650f2d8fd53092162eeaac1faddd16c2998f99a7e3612181e64084845911', NULL, 'ويقوم اعملوا علي مكانتكم اني عمل سوف تعلمون من ياتيه عذاب يخزيه ومن هو كذب وارتقبوا اني معكم رقيب', 12, 24, 93, 1, 3, 232, false, NULL),
    (1567, 'tanzil-uthmani-v1.1', 11, 94, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', '3fe761f9050c3fc5ce592e5ddfd059009c5beb2aeb9739fbc194206676b2af08', 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', '3fe761f9050c3fc5ce592e5ddfd059009c5beb2aeb9739fbc194206676b2af08', '3fe761f9050c3fc5ce592e5ddfd059009c5beb2aeb9739fbc194206676b2af08', NULL, 'ولما جاء امرنا نجينا شعيبا والذين ءامنوا معه برحمه منا واخذت الذين ظلموا الصيحه فاصبحوا في ديرهم جثمين', 12, 24, 93, 1, 3, 232, false, NULL),
    (1568, 'tanzil-uthmani-v1.1', 11, 95, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَا بُعْدًا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ', '17ead843fbb7fb54fa2234a34362c872a8713844c8c326ec3de77e62bf63afe4', 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ أَلَا بُعْدًا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ', '17ead843fbb7fb54fa2234a34362c872a8713844c8c326ec3de77e62bf63afe4', '17ead843fbb7fb54fa2234a34362c872a8713844c8c326ec3de77e62bf63afe4', NULL, 'كان لم يغنوا فيها الا بعدا لمدين كما بعدت ثمود', 12, 24, 93, 1, 3, 232, false, NULL),
    (1569, 'tanzil-uthmani-v1.1', 11, 96, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', '441f49071d0a9f5e889b74f21aa879c47eaf4ee3b30cd4fa49d770732833a270', 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', '441f49071d0a9f5e889b74f21aa879c47eaf4ee3b30cd4fa49d770732833a270', '441f49071d0a9f5e889b74f21aa879c47eaf4ee3b30cd4fa49d770732833a270', NULL, 'ولقد ارسلنا موسي بايتنا وسلطن مبين', 12, 24, 93, 1, 3, 232, false, NULL),
    (1570, 'tanzil-uthmani-v1.1', 11, 97, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱتَّبَعُوٓا۟ أَمْرَ فِرْعَوْنَ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍ', '39b773ab858e83211d90d905dc225c12934ef4effa5426c524a47dd269b6fde1', 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱتَّبَعُوٓا۟ أَمْرَ فِرْعَوْنَ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍ', '39b773ab858e83211d90d905dc225c12934ef4effa5426c524a47dd269b6fde1', '39b773ab858e83211d90d905dc225c12934ef4effa5426c524a47dd269b6fde1', NULL, 'الي فرعون وملايه فاتبعوا امر فرعون وما امر فرعون برشيد', 12, 24, 93, 1, 3, 232, false, NULL),
    (1571, 'tanzil-uthmani-v1.1', 11, 98, 'يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ', 'e785ba634f3557cf2e757b386b4c0379e61928d670bd5054eb80064d13fe6838', 'يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ', 'e785ba634f3557cf2e757b386b4c0379e61928d670bd5054eb80064d13fe6838', 'e785ba634f3557cf2e757b386b4c0379e61928d670bd5054eb80064d13fe6838', NULL, 'يقدم قومه يوم القيمه فاوردهم النار وبئس الورد المورود', 12, 24, 93, 1, 3, 233, false, NULL),
    (1572, 'tanzil-uthmani-v1.1', 11, 99, 'وَأُتْبِعُوا۟ فِى هَٰذِهِۦ لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ بِئْسَ ٱلرِّفْدُ ٱلْمَرْفُودُ', '9f2a219875ea51afd9addc4bc41ae76ba54da4d08a27f81a242e929738311b44', 'وَأُتْبِعُوا۟ فِى هَٰذِهِۦ لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ بِئْسَ ٱلرِّفْدُ ٱلْمَرْفُودُ', '9f2a219875ea51afd9addc4bc41ae76ba54da4d08a27f81a242e929738311b44', '9f2a219875ea51afd9addc4bc41ae76ba54da4d08a27f81a242e929738311b44', NULL, 'واتبعوا في هذه لعنه ويوم القيمه بئس الرفد المرفود', 12, 24, 93, 1, 3, 233, false, NULL),
    (1573, 'tanzil-uthmani-v1.1', 11, 100, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْقُرَىٰ نَقُصُّهُۥ عَلَيْكَ مِنْهَا قَآئِمٌ وَحَصِيدٌ', 'c9d88accd98fba097bd61efd8a3b6f4bfa6191bb754912682bda7241056c4563', 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْقُرَىٰ نَقُصُّهُۥ عَلَيْكَ مِنْهَا قَآئِمٌ وَحَصِيدٌ', 'c9d88accd98fba097bd61efd8a3b6f4bfa6191bb754912682bda7241056c4563', 'c9d88accd98fba097bd61efd8a3b6f4bfa6191bb754912682bda7241056c4563', NULL, 'ذلك من انباء القري نقصه عليك منها قائم وحصيد', 12, 24, 93, 1, 3, 233, false, NULL),
    (1574, 'tanzil-uthmani-v1.1', 11, 101, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن ظَلَمُوٓا۟ أَنفُسَهُمْ فَمَآ أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ ٱلَّتِى يَدْعُونَ مِن دُونِ ٱللَّهِ مِن شَىْءٍ لَّمَّا جَآءَ أَمْرُ رَبِّكَ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ', '9337dc1c59a1dea772fad32ce66009ac70c45978668f4ae44cd4300ce6e13159', 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن ظَلَمُوٓا۟ أَنفُسَهُمْ فَمَآ أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ ٱلَّتِى يَدْعُونَ مِن دُونِ ٱللَّهِ مِن شَىْءٍ لَّمَّا جَآءَ أَمْرُ رَبِّكَ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ', '9337dc1c59a1dea772fad32ce66009ac70c45978668f4ae44cd4300ce6e13159', '9337dc1c59a1dea772fad32ce66009ac70c45978668f4ae44cd4300ce6e13159', NULL, 'وما ظلمنهم ولكن ظلموا انفسهم فما اغنت عنهم ءالهتهم التي يدعون من دون الله من شيء لما جاء امر ربك وما زادوهم غير تتبيب', 12, 24, 93, 1, 3, 233, false, NULL),
    (1575, 'tanzil-uthmani-v1.1', 11, 102, 'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ٱلْقُرَىٰ وَهِىَ ظَٰلِمَةٌ إِنَّ أَخْذَهُۥٓ أَلِيمٌ شَدِيدٌ', '37e05ab510be5a8bf3c8204c0a3986f221e4d6eed6338756396253cdccfb81dc', 'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ٱلْقُرَىٰ وَهِىَ ظَٰلِمَةٌ إِنَّ أَخْذَهُۥٓ أَلِيمٌ شَدِيدٌ', '37e05ab510be5a8bf3c8204c0a3986f221e4d6eed6338756396253cdccfb81dc', '37e05ab510be5a8bf3c8204c0a3986f221e4d6eed6338756396253cdccfb81dc', NULL, 'وكذلك اخذ ربك اذا اخذ القري وهي ظلمه ان اخذه اليم شديد', 12, 24, 93, 1, 3, 233, false, NULL),
    (1576, 'tanzil-uthmani-v1.1', 11, 103, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّمَنْ خَافَ عَذَابَ ٱلْـَٔاخِرَةِ ذَٰلِكَ يَوْمٌ مَّجْمُوعٌ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوْمٌ مَّشْهُودٌ', '9ecd7a76ee95058441527918a563d0f92d0be5f7c8df9d73bb7bec15c4d2c286', 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّمَنْ خَافَ عَذَابَ ٱلْـَٔاخِرَةِ ذَٰلِكَ يَوْمٌ مَّجْمُوعٌ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوْمٌ مَّشْهُودٌ', '9ecd7a76ee95058441527918a563d0f92d0be5f7c8df9d73bb7bec15c4d2c286', '9ecd7a76ee95058441527918a563d0f92d0be5f7c8df9d73bb7bec15c4d2c286', NULL, 'ان في ذلك لايه لمن خاف عذاب الاخره ذلك يوم مجموع له الناس وذلك يوم مشهود', 12, 24, 93, 1, 3, 233, false, NULL),
    (1577, 'tanzil-uthmani-v1.1', 11, 104, 'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٍ مَّعْدُودٍ', 'e95d109ac1d62b4f4e6890e894e0c6925648ed6e4614ad263ff983ce631ea11a', 'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٍ مَّعْدُودٍ', 'e95d109ac1d62b4f4e6890e894e0c6925648ed6e4614ad263ff983ce631ea11a', 'e95d109ac1d62b4f4e6890e894e0c6925648ed6e4614ad263ff983ce631ea11a', NULL, 'وما نؤخره الا لاجل معدود', 12, 24, 93, 1, 3, 233, false, NULL),
    (1578, 'tanzil-uthmani-v1.1', 11, 105, 'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِۦ فَمِنْهُمْ شَقِىٌّ وَسَعِيدٌ', 'da80e8c3f356d1d9c4da029969096dcdfd71084fa47f00ec2bdcafb2ba255ec3', 'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِۦ فَمِنْهُمْ شَقِىٌّ وَسَعِيدٌ', 'da80e8c3f356d1d9c4da029969096dcdfd71084fa47f00ec2bdcafb2ba255ec3', 'da80e8c3f356d1d9c4da029969096dcdfd71084fa47f00ec2bdcafb2ba255ec3', NULL, 'يوم يات لا تكلم نفس الا باذنه فمنهم شقي وسعيد', 12, 24, 93, 1, 3, 233, false, NULL),
    (1579, 'tanzil-uthmani-v1.1', 11, 106, 'فَأَمَّا ٱلَّذِينَ شَقُوا۟ فَفِى ٱلنَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ', '94e087714ca6f035e8e6c8a26a9af3c084fe25555cd35b56a104c7c43b543cbe', 'فَأَمَّا ٱلَّذِينَ شَقُوا۟ فَفِى ٱلنَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ', '94e087714ca6f035e8e6c8a26a9af3c084fe25555cd35b56a104c7c43b543cbe', '94e087714ca6f035e8e6c8a26a9af3c084fe25555cd35b56a104c7c43b543cbe', NULL, 'فاما الذين شقوا ففي النار لهم فيها زفير وشهيق', 12, 24, 93, 1, 3, 233, false, NULL),
    (1580, 'tanzil-uthmani-v1.1', 11, 107, 'خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِّمَا يُرِيدُ', 'a9e530c430c9641265dce8ea955d0ffe4d9c079ec443335c25c4ba9471f0ea40', 'خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِّمَا يُرِيدُ', 'a9e530c430c9641265dce8ea955d0ffe4d9c079ec443335c25c4ba9471f0ea40', 'a9e530c430c9641265dce8ea955d0ffe4d9c079ec443335c25c4ba9471f0ea40', NULL, 'خلدين فيها ما دامت السموت والارض الا ما شاء ربك ان ربك فعال لما يريد', 12, 24, 93, 1, 3, 233, false, NULL),
    (1581, 'tanzil-uthmani-v1.1', 11, 108, 'وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ عَطَآءً غَيْرَ مَجْذُوذٍ', 'e073d146e895c46694bed3ced370d6bb85700dab0add895b69479a4114a6f952', 'وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ عَطَآءً غَيْرَ مَجْذُوذٍ', 'e073d146e895c46694bed3ced370d6bb85700dab0add895b69479a4114a6f952', 'e073d146e895c46694bed3ced370d6bb85700dab0add895b69479a4114a6f952', NULL, 'واما الذين سعدوا ففي الجنه خلدين فيها ما دامت السموت والارض الا ما شاء ربك عطاء غير مجذوذ', 12, 24, 94, 1, 3, 233, false, NULL),
    (1582, 'tanzil-uthmani-v1.1', 11, 109, 'فَلَا تَكُ فِى مِرْيَةٍ مِّمَّا يَعْبُدُ هَٰٓؤُلَآءِ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ', 'ba70de23b1e2bc85aaad6ab0896572e6477177144d6c390e74abde85e8d58c41', 'فَلَا تَكُ فِى مِرْيَةٍ مِّمَّا يَعْبُدُ هَٰٓؤُلَآءِ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ', 'ba70de23b1e2bc85aaad6ab0896572e6477177144d6c390e74abde85e8d58c41', 'ba70de23b1e2bc85aaad6ab0896572e6477177144d6c390e74abde85e8d58c41', NULL, 'فلا تك في مريه مما يعبد هؤلاء ما يعبدون الا كما يعبد ءاباؤهم من قبل وانا لموفوهم نصيبهم غير منقوص', 12, 24, 94, 1, 3, 234, false, NULL),
    (1583, 'tanzil-uthmani-v1.1', 11, 110, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', '7bbde63e13562f6e2da4b681375090bc9f2100f518f668cfc660a39b763b3372', 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', '7bbde63e13562f6e2da4b681375090bc9f2100f518f668cfc660a39b763b3372', '7bbde63e13562f6e2da4b681375090bc9f2100f518f668cfc660a39b763b3372', NULL, 'ولقد ءاتينا موسي الكتب فاختلف فيه ولولا كلمه سبقت من ربك لقضي بينهم وانهم لفي شك منه مريب', 12, 24, 94, 1, 3, 234, false, NULL),
    (1584, 'tanzil-uthmani-v1.1', 11, 111, 'وَإِنَّ كُلًّا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَٰلَهُمْ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرٌ', 'f5b9eedbf24ef376ac6513c1fdd7c4e5508ec776136bc5f81e8abe725d803eeb', 'وَإِنَّ كُلًّا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَٰلَهُمْ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرٌ', 'f5b9eedbf24ef376ac6513c1fdd7c4e5508ec776136bc5f81e8abe725d803eeb', 'f5b9eedbf24ef376ac6513c1fdd7c4e5508ec776136bc5f81e8abe725d803eeb', NULL, 'وان كلا لما ليوفينهم ربك اعملهم انه بما يعملون خبير', 12, 24, 94, 1, 3, 234, false, NULL),
    (1585, 'tanzil-uthmani-v1.1', 11, 112, 'فَٱسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا۟ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', '6d76d1f953aea250a1f94389b85dafe02d0f78881f43005f5cc95a115dfaddc0', 'فَٱسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا۟ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', '6d76d1f953aea250a1f94389b85dafe02d0f78881f43005f5cc95a115dfaddc0', '6d76d1f953aea250a1f94389b85dafe02d0f78881f43005f5cc95a115dfaddc0', NULL, 'فاستقم كما امرت ومن تاب معك ولا تطغوا انه بما تعملون بصير', 12, 24, 94, 1, 3, 234, false, NULL),
    (1586, 'tanzil-uthmani-v1.1', 11, 113, 'وَلَا تَرْكَنُوٓا۟ إِلَى ٱلَّذِينَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ثُمَّ لَا تُنصَرُونَ', '1c2ed1f8473dc0b85924b7c36599fc0e2baafd11ea1dfbcd9bc9d52a0d320ecf', 'وَلَا تَرْكَنُوٓا۟ إِلَى ٱلَّذِينَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ثُمَّ لَا تُنصَرُونَ', '1c2ed1f8473dc0b85924b7c36599fc0e2baafd11ea1dfbcd9bc9d52a0d320ecf', '1c2ed1f8473dc0b85924b7c36599fc0e2baafd11ea1dfbcd9bc9d52a0d320ecf', NULL, 'ولا تركنوا الي الذين ظلموا فتمسكم النار وما لكم من دون الله من اولياء ثم لا تنصرون', 12, 24, 94, 1, 3, 234, false, NULL),
    (1587, 'tanzil-uthmani-v1.1', 11, 114, 'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًا مِّنَ ٱلَّيْلِ إِنَّ ٱلْحَسَنَٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ', '1ccdd3eabc6cfcb050b00c40d5fd3b2e969c40300e87af68cdc0d245854d6650', 'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًا مِّنَ ٱلَّيْلِ إِنَّ ٱلْحَسَنَٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ', '1ccdd3eabc6cfcb050b00c40d5fd3b2e969c40300e87af68cdc0d245854d6650', '1ccdd3eabc6cfcb050b00c40d5fd3b2e969c40300e87af68cdc0d245854d6650', NULL, 'واقم الصلوه طرفي النهار وزلفا من اليل ان الحسنت يذهبن السيات ذلك ذكري للذكرين', 12, 24, 94, 1, 3, 234, false, NULL),
    (1588, 'tanzil-uthmani-v1.1', 11, 115, 'وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '098d373e6098b8b10a8cb95aeca467b819c63d83d0468d0f1405a3559ea039ab', 'وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '098d373e6098b8b10a8cb95aeca467b819c63d83d0468d0f1405a3559ea039ab', '098d373e6098b8b10a8cb95aeca467b819c63d83d0468d0f1405a3559ea039ab', NULL, 'واصبر فان الله لا يضيع اجر المحسنين', 12, 24, 94, 1, 3, 234, false, NULL),
    (1589, 'tanzil-uthmani-v1.1', 11, 116, 'فَلَوْلَا كَانَ مِنَ ٱلْقُرُونِ مِن قَبْلِكُمْ أُو۟لُوا۟ بَقِيَّةٍ يَنْهَوْنَ عَنِ ٱلْفَسَادِ فِى ٱلْأَرْضِ إِلَّا قَلِيلًا مِّمَّنْ أَنجَيْنَا مِنْهُمْ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُوا۟ مَآ أُتْرِفُوا۟ فِيهِ وَكَانُوا۟ مُجْرِمِينَ', 'b1785882a26a67e6882862960b3631a1d911137da4951248ba05d1f3ee3d3e6b', 'فَلَوْلَا كَانَ مِنَ ٱلْقُرُونِ مِن قَبْلِكُمْ أُو۟لُوا۟ بَقِيَّةٍ يَنْهَوْنَ عَنِ ٱلْفَسَادِ فِى ٱلْأَرْضِ إِلَّا قَلِيلًا مِّمَّنْ أَنجَيْنَا مِنْهُمْ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُوا۟ مَآ أُتْرِفُوا۟ فِيهِ وَكَانُوا۟ مُجْرِمِينَ', 'b1785882a26a67e6882862960b3631a1d911137da4951248ba05d1f3ee3d3e6b', 'b1785882a26a67e6882862960b3631a1d911137da4951248ba05d1f3ee3d3e6b', NULL, 'فلولا كان من القرون من قبلكم اولوا بقيه ينهون عن الفساد في الارض الا قليلا ممن انجينا منهم واتبع الذين ظلموا ما اترفوا فيه وكانوا مجرمين', 12, 24, 94, 1, 3, 234, false, NULL),
    (1590, 'tanzil-uthmani-v1.1', 11, 117, 'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ', '6293301f3881ada1c8585021edc9d00d26c1811030d7935a99ef0ca73dd7efb3', 'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ', '6293301f3881ada1c8585021edc9d00d26c1811030d7935a99ef0ca73dd7efb3', '6293301f3881ada1c8585021edc9d00d26c1811030d7935a99ef0ca73dd7efb3', NULL, 'وما كان ربك ليهلك القري بظلم واهلها مصلحون', 12, 24, 94, 1, 3, 234, false, NULL),
    (1591, 'tanzil-uthmani-v1.1', 11, 118, 'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةً وَٰحِدَةً وَلَا يَزَالُونَ مُخْتَلِفِينَ', 'd5a0d7c7dd026c66ca7a5b3eda9fbc3d7f66f95b414d314744c294d54b286526', 'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةً وَٰحِدَةً وَلَا يَزَالُونَ مُخْتَلِفِينَ', 'd5a0d7c7dd026c66ca7a5b3eda9fbc3d7f66f95b414d314744c294d54b286526', 'd5a0d7c7dd026c66ca7a5b3eda9fbc3d7f66f95b414d314744c294d54b286526', NULL, 'ولو شاء ربك لجعل الناس امه وحده ولا يزالون مختلفين', 12, 24, 94, 1, 3, 235, false, NULL),
    (1592, 'tanzil-uthmani-v1.1', 11, 119, 'إِلَّا مَن رَّحِمَ رَبُّكَ وَلِذَٰلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', '8396f7c1336a9a346691d3469565af8f1c2c0a14dd45874ef4a898a5a9edcb09', 'إِلَّا مَن رَّحِمَ رَبُّكَ وَلِذَٰلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', '8396f7c1336a9a346691d3469565af8f1c2c0a14dd45874ef4a898a5a9edcb09', '8396f7c1336a9a346691d3469565af8f1c2c0a14dd45874ef4a898a5a9edcb09', NULL, 'الا من رحم ربك ولذلك خلقهم وتمت كلمه ربك لاملان جهنم من الجنه والناس اجمعين', 12, 24, 94, 1, 3, 235, false, NULL),
    (1593, 'tanzil-uthmani-v1.1', 11, 120, 'وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ وَجَآءَكَ فِى هَٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 'e3b81deaf9f1e66f47e1d86c0649f0b90adda8e5fc4756d71c87ef022fb28f81', 'وَكُلًّا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ وَجَآءَكَ فِى هَٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 'e3b81deaf9f1e66f47e1d86c0649f0b90adda8e5fc4756d71c87ef022fb28f81', 'e3b81deaf9f1e66f47e1d86c0649f0b90adda8e5fc4756d71c87ef022fb28f81', NULL, 'وكلا نقص عليك من انباء الرسل ما نثبت به فؤادك وجاءك في هذه الحق وموعظه وذكري للمؤمنين', 12, 24, 94, 1, 3, 235, false, NULL),
    (1594, 'tanzil-uthmani-v1.1', 11, 121, 'وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنَّا عَٰمِلُونَ', '7bfc8261ae0b200b74ba561edaf610b1b9e1942703b8f1152e68f9b5f2bbe744', 'وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنَّا عَٰمِلُونَ', '7bfc8261ae0b200b74ba561edaf610b1b9e1942703b8f1152e68f9b5f2bbe744', '7bfc8261ae0b200b74ba561edaf610b1b9e1942703b8f1152e68f9b5f2bbe744', NULL, 'وقل للذين لا يؤمنون اعملوا علي مكانتكم انا عملون', 12, 24, 94, 1, 3, 235, false, NULL),
    (1595, 'tanzil-uthmani-v1.1', 11, 122, 'وَٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', '88dc4d8357c89dafb177cb21c32ba96e6a53953eb2cfd5dfc6613e87b1234c9c', 'وَٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', '88dc4d8357c89dafb177cb21c32ba96e6a53953eb2cfd5dfc6613e87b1234c9c', '88dc4d8357c89dafb177cb21c32ba96e6a53953eb2cfd5dfc6613e87b1234c9c', NULL, 'وانتظروا انا منتظرون', 12, 24, 94, 1, 3, 235, false, NULL),
    (1596, 'tanzil-uthmani-v1.1', 11, 123, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَيْهِ يُرْجَعُ ٱلْأَمْرُ كُلُّهُۥ فَٱعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'bab88085db74cb2cb5e212df9608f500f00108a2af5bbc50a458c470da7438b7', 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَيْهِ يُرْجَعُ ٱلْأَمْرُ كُلُّهُۥ فَٱعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 'bab88085db74cb2cb5e212df9608f500f00108a2af5bbc50a458c470da7438b7', 'bab88085db74cb2cb5e212df9608f500f00108a2af5bbc50a458c470da7438b7', NULL, 'ولله غيب السموت والارض واليه يرجع الامر كله فاعبده وتوكل عليه وما ربك بغفل عما تعملون', 12, 24, 94, 1, 3, 235, false, NULL),
    (1597, 'tanzil-uthmani-v1.1', 12, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', '2be8da97fa42fa0a24dafcf881f87647aadeaa2e02606e4a21bc7150ab7f4197', 'الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', '8fb5d2e47bf40116d2122a25f546dbcd93efd743cedaa5ffb20662e5fd5b2088', '8fb5d2e47bf40116d2122a25f546dbcd93efd743cedaa5ffb20662e5fd5b2088', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الر تلك ءايت الكتب المبين', 12, 24, 94, 1, 3, 235, false, NULL),
    (1598, 'tanzil-uthmani-v1.1', 12, 2, 'إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', '87648227b38b9f4d62bedae67810db638017a8b1e084e2e15d5df401c83c4fde', 'إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', '87648227b38b9f4d62bedae67810db638017a8b1e084e2e15d5df401c83c4fde', '87648227b38b9f4d62bedae67810db638017a8b1e084e2e15d5df401c83c4fde', NULL, 'انا انزلنه قرءنا عربيا لعلكم تعقلون', 12, 24, 94, 1, 3, 235, false, NULL),
    (1599, 'tanzil-uthmani-v1.1', 12, 3, 'نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَٰفِلِينَ', 'baf7a98821d76fac6b8b0271287180c48f8fbb28f93a9eb7e0d0b9ef3376e675', 'نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَٰفِلِينَ', 'baf7a98821d76fac6b8b0271287180c48f8fbb28f93a9eb7e0d0b9ef3376e675', 'baf7a98821d76fac6b8b0271287180c48f8fbb28f93a9eb7e0d0b9ef3376e675', NULL, 'نحن نقص عليك احسن القصص بما اوحينا اليك هذا القرءان وان كنت من قبله لمن الغفلين', 12, 24, 94, 1, 3, 235, false, NULL),
    (1600, 'tanzil-uthmani-v1.1', 12, 4, 'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَٰجِدِينَ', '4bba0cbda7d0fe01c3f28af75febde5b6b3e145e183fd0bf2dea24eca80a3cba', 'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَٰجِدِينَ', '4bba0cbda7d0fe01c3f28af75febde5b6b3e145e183fd0bf2dea24eca80a3cba', '4bba0cbda7d0fe01c3f28af75febde5b6b3e145e183fd0bf2dea24eca80a3cba', NULL, 'اذ قال يوسف لابيه يابت اني رايت احد عشر كوكبا والشمس والقمر رايتهم لي سجدين', 12, 24, 94, 1, 3, 235, false, NULL),
    (1601, 'tanzil-uthmani-v1.1', 12, 5, 'قَالَ يَٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا إِنَّ ٱلشَّيْطَٰنَ لِلْإِنسَٰنِ عَدُوٌّ مُّبِينٌ', '4851d1cfbe7f08f6a8492e06c78c7be36b154435e5e3061da4212186b396679a', 'قَالَ يَٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا إِنَّ ٱلشَّيْطَٰنَ لِلْإِنسَٰنِ عَدُوٌّ مُّبِينٌ', '4851d1cfbe7f08f6a8492e06c78c7be36b154435e5e3061da4212186b396679a', '4851d1cfbe7f08f6a8492e06c78c7be36b154435e5e3061da4212186b396679a', NULL, 'قال يبني لا تقصص رءياك علي اخوتك فيكيدوا لك كيدا ان الشيطن للانسن عدو مبين', 12, 24, 94, 1, 3, 236, false, NULL),
    (1602, 'tanzil-uthmani-v1.1', 12, 6, 'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَٰقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ', 'cca5997cff8b1856417ce1f5ae2ade4bdb0ae1fb5b36cfaaf59999ee5fd7d754', 'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَٰقَ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌ', 'cca5997cff8b1856417ce1f5ae2ade4bdb0ae1fb5b36cfaaf59999ee5fd7d754', 'cca5997cff8b1856417ce1f5ae2ade4bdb0ae1fb5b36cfaaf59999ee5fd7d754', NULL, 'وكذلك يجتبيك ربك ويعلمك من تاويل الاحاديث ويتم نعمته عليك وعلي ءال يعقوب كما اتمها علي ابويك من قبل ابرهيم واسحق ان ربك عليم حكيم', 12, 24, 94, 1, 3, 236, false, NULL),
    (1603, 'tanzil-uthmani-v1.1', 12, 7, 'لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَٰتٌ لِّلسَّآئِلِينَ', '90e0ba157e89e951803a213dceed4e5b722123aa6e295370005b372c736f8636', 'لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَٰتٌ لِّلسَّآئِلِينَ', '90e0ba157e89e951803a213dceed4e5b722123aa6e295370005b372c736f8636', '90e0ba157e89e951803a213dceed4e5b722123aa6e295370005b372c736f8636', NULL, 'لقد كان في يوسف واخوته ءايت للسائلين', 12, 24, 95, 1, 3, 236, false, NULL),
    (1604, 'tanzil-uthmani-v1.1', 12, 8, 'إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَٰلٍ مُّبِينٍ', '81a91a2cdf54201c8f1c79a3e775287c51f051d3e86a3fd74739e7b48453f2e6', 'إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَٰلٍ مُّبِينٍ', '81a91a2cdf54201c8f1c79a3e775287c51f051d3e86a3fd74739e7b48453f2e6', '81a91a2cdf54201c8f1c79a3e775287c51f051d3e86a3fd74739e7b48453f2e6', NULL, 'اذ قالوا ليوسف واخوه احب الي ابينا منا ونحن عصبه ان ابانا لفي ضلل مبين', 12, 24, 95, 1, 3, 236, false, NULL),
    (1605, 'tanzil-uthmani-v1.1', 12, 9, 'ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًا صَٰلِحِينَ', '5f75d119867b6fbc6d2b18c7c5143029cb93c32dac89c9810d76d88dc935c029', 'ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًا صَٰلِحِينَ', '5f75d119867b6fbc6d2b18c7c5143029cb93c32dac89c9810d76d88dc935c029', '5f75d119867b6fbc6d2b18c7c5143029cb93c32dac89c9810d76d88dc935c029', NULL, 'اقتلوا يوسف او اطرحوه ارضا يخل لكم وجه ابيكم وتكونوا من بعده قوما صلحين', 12, 24, 95, 1, 3, 236, false, NULL),
    (1606, 'tanzil-uthmani-v1.1', 12, 10, 'قَالَ قَآئِلٌ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَٰعِلِينَ', 'a4b6de38a1501788d0f5179990d1c33ec48ef4e3a34ac1fb21c015b730149a95', 'قَالَ قَآئِلٌ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَٰعِلِينَ', 'a4b6de38a1501788d0f5179990d1c33ec48ef4e3a34ac1fb21c015b730149a95', 'a4b6de38a1501788d0f5179990d1c33ec48ef4e3a34ac1fb21c015b730149a95', NULL, 'قال قائل منهم لا تقتلوا يوسف والقوه في غيبت الجب يلتقطه بعض السياره ان كنتم فعلين', 12, 24, 95, 1, 3, 236, false, NULL),
    (1607, 'tanzil-uthmani-v1.1', 12, 11, 'قَالُوا۟ يَٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ', '25e2b83e6f5e02226c7b40627e4ea002ea09c734e6d7acea50d7aa7f74e2bbfe', 'قَالُوا۟ يَٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ', '25e2b83e6f5e02226c7b40627e4ea002ea09c734e6d7acea50d7aa7f74e2bbfe', '25e2b83e6f5e02226c7b40627e4ea002ea09c734e6d7acea50d7aa7f74e2bbfe', NULL, 'قالوا يابانا ما لك لا تامنا علي يوسف وانا له لنصحون', 12, 24, 95, 1, 3, 236, false, NULL),
    (1608, 'tanzil-uthmani-v1.1', 12, 12, 'أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'e022a82432b0976c6c61d87a41fd68db0e45da6f657ccf4cf5089caa7449c217', 'أَرْسِلْهُ مَعَنَا غَدًا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'e022a82432b0976c6c61d87a41fd68db0e45da6f657ccf4cf5089caa7449c217', 'e022a82432b0976c6c61d87a41fd68db0e45da6f657ccf4cf5089caa7449c217', NULL, 'ارسله معنا غدا يرتع ويلعب وانا له لحفظون', 12, 24, 95, 1, 3, 236, false, NULL),
    (1609, 'tanzil-uthmani-v1.1', 12, 13, 'قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَٰفِلُونَ', '44245201b08c295407b6027d1adb3e21a4a10b1dd862d7dccef4b4870289d61a', 'قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَٰفِلُونَ', '44245201b08c295407b6027d1adb3e21a4a10b1dd862d7dccef4b4870289d61a', '44245201b08c295407b6027d1adb3e21a4a10b1dd862d7dccef4b4870289d61a', NULL, 'قال اني ليحزنني ان تذهبوا به واخاف ان ياكله الذئب وانتم عنه غفلون', 12, 24, 95, 1, 3, 236, false, NULL),
    (1610, 'tanzil-uthmani-v1.1', 12, 14, 'قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًا لَّخَٰسِرُونَ', '0b9b71680064f2802fee34a166442ea4919dbb7cce5ff0d58101420b1dfe5f19', 'قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًا لَّخَٰسِرُونَ', '0b9b71680064f2802fee34a166442ea4919dbb7cce5ff0d58101420b1dfe5f19', '0b9b71680064f2802fee34a166442ea4919dbb7cce5ff0d58101420b1dfe5f19', NULL, 'قالوا لئن اكله الذئب ونحن عصبه انا اذا لخسرون', 12, 24, 95, 1, 3, 236, false, NULL),
    (1611, 'tanzil-uthmani-v1.1', 12, 15, 'فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ', '50f57412dbc885590ae554c3a2c628bd53db8553c50dfa6e353427796717f968', 'فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ', '50f57412dbc885590ae554c3a2c628bd53db8553c50dfa6e353427796717f968', '50f57412dbc885590ae554c3a2c628bd53db8553c50dfa6e353427796717f968', NULL, 'فلما ذهبوا به واجمعوا ان يجعلوه في غيبت الجب واوحينا اليه لتنبئنهم بامرهم هذا وهم لا يشعرون', 12, 24, 95, 1, 3, 237, false, NULL),
    (1612, 'tanzil-uthmani-v1.1', 12, 16, 'وَجَآءُوٓ أَبَاهُمْ عِشَآءً يَبْكُونَ', '5a291dc55a9763a4402d65d65a4eb3cf151733c6899c6322f47645004b904383', 'وَجَآءُوٓ أَبَاهُمْ عِشَآءً يَبْكُونَ', '5a291dc55a9763a4402d65d65a4eb3cf151733c6899c6322f47645004b904383', '5a291dc55a9763a4402d65d65a4eb3cf151733c6899c6322f47645004b904383', NULL, 'وجاءو اباهم عشاء يبكون', 12, 24, 95, 1, 3, 237, false, NULL),
    (1613, 'tanzil-uthmani-v1.1', 12, 17, 'قَالُوا۟ يَٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ وَمَآ أَنتَ بِمُؤْمِنٍ لَّنَا وَلَوْ كُنَّا صَٰدِقِينَ', 'fbf52fc1ac749b509b77e1ab4d5c6c12d6a68c31f4ae9de29b9a5d12c31ef205', 'قَالُوا۟ يَٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ وَمَآ أَنتَ بِمُؤْمِنٍ لَّنَا وَلَوْ كُنَّا صَٰدِقِينَ', 'fbf52fc1ac749b509b77e1ab4d5c6c12d6a68c31f4ae9de29b9a5d12c31ef205', 'fbf52fc1ac749b509b77e1ab4d5c6c12d6a68c31f4ae9de29b9a5d12c31ef205', NULL, 'قالوا يابانا انا ذهبنا نستبق وتركنا يوسف عند متعنا فاكله الذئب وما انت بمؤمن لنا ولو كنا صدقين', 12, 24, 95, 1, 3, 237, false, NULL),
    (1614, 'tanzil-uthmani-v1.1', 12, 18, 'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', '5d2e8622ef7925d2d9f0fe51b3392532724adeb7cf9175b004ab7f0214d43d78', 'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍ كَذِبٍ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', '5d2e8622ef7925d2d9f0fe51b3392532724adeb7cf9175b004ab7f0214d43d78', '5d2e8622ef7925d2d9f0fe51b3392532724adeb7cf9175b004ab7f0214d43d78', NULL, 'وجاءو علي قميصه بدم كذب قال بل سولت لكم انفسكم امرا فصبر جميل والله المستعان علي ما تصفون', 12, 24, 95, 1, 3, 237, false, NULL),
    (1615, 'tanzil-uthmani-v1.1', 12, 19, 'وَجَآءَتْ سَيَّارَةٌ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ قَالَ يَٰبُشْرَىٰ هَٰذَا غُلَٰمٌ وَأَسَرُّوهُ بِضَٰعَةً وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ', '200d17e4a3d3854b1a53da01c0977924c4c2419b14359a75849010366e03807a', 'وَجَآءَتْ سَيَّارَةٌ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ قَالَ يَٰبُشْرَىٰ هَٰذَا غُلَٰمٌ وَأَسَرُّوهُ بِضَٰعَةً وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ', '200d17e4a3d3854b1a53da01c0977924c4c2419b14359a75849010366e03807a', '200d17e4a3d3854b1a53da01c0977924c4c2419b14359a75849010366e03807a', NULL, 'وجاءت سياره فارسلوا واردهم فادلي دلوه قال يبشري هذا غلم واسروه بضعه والله عليم بما يعملون', 12, 24, 95, 1, 3, 237, false, NULL),
    (1616, 'tanzil-uthmani-v1.1', 12, 20, 'وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍ دَرَٰهِمَ مَعْدُودَةٍ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ', '4a0550be5d748405266df81545a1cafd4526680f27d81e1190dcae5f119c6944', 'وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍ دَرَٰهِمَ مَعْدُودَةٍ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ', '4a0550be5d748405266df81545a1cafd4526680f27d81e1190dcae5f119c6944', '4a0550be5d748405266df81545a1cafd4526680f27d81e1190dcae5f119c6944', NULL, 'وشروه بثمن بخس درهم معدوده وكانوا فيه من الزهدين', 12, 24, 95, 1, 3, 237, false, NULL),
    (1617, 'tanzil-uthmani-v1.1', 12, 21, 'وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'abe9b5594f4f0f7620d4ff48e4e853f59e73c91446a0bc059f53238dcba1b068', 'وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'abe9b5594f4f0f7620d4ff48e4e853f59e73c91446a0bc059f53238dcba1b068', 'abe9b5594f4f0f7620d4ff48e4e853f59e73c91446a0bc059f53238dcba1b068', NULL, 'وقال الذي اشتريه من مصر لامراته اكرمي مثويه عسي ان ينفعنا او نتخذه ولدا وكذلك مكنا ليوسف في الارض ولنعلمه من تاويل الاحاديث والله غالب علي امره ولكن اكثر الناس لا يعلمون', 12, 24, 95, 1, 3, 237, false, NULL),
    (1618, 'tanzil-uthmani-v1.1', 12, 22, 'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '96b3f5075035c8f5191862a048b5aa58260378a72bc3925c3319eaa51b8063df', 'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '96b3f5075035c8f5191862a048b5aa58260378a72bc3925c3319eaa51b8063df', '96b3f5075035c8f5191862a048b5aa58260378a72bc3925c3319eaa51b8063df', NULL, 'ولما بلغ اشده ءاتينه حكما وعلما وكذلك نجزي المحسنين', 12, 24, 95, 1, 3, 237, false, NULL),
    (1619, 'tanzil-uthmani-v1.1', 12, 23, 'وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ ٱللَّهِ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'ae9c91163f8e9d17d1545edc3f6aa66f2b4a9498597433e43b4af7db1790fa14', 'وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ قَالَ مَعَاذَ ٱللَّهِ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 'ae9c91163f8e9d17d1545edc3f6aa66f2b4a9498597433e43b4af7db1790fa14', 'ae9c91163f8e9d17d1545edc3f6aa66f2b4a9498597433e43b4af7db1790fa14', NULL, 'ورودته التي هو في بيتها عن نفسه وغلقت الابوب وقالت هيت لك قال معاذ الله انه ربي احسن مثواي انه لا يفلح الظلمون', 12, 24, 95, 1, 3, 238, false, NULL),
    (1620, 'tanzil-uthmani-v1.1', 12, 24, 'وَلَقَدْ هَمَّتْ بِهِۦ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَٰنَ رَبِّهِۦ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ', '218124cb05f67686e8354783a02ef8b11c924c5931cd9b1c96be0db9c6d50a20', 'وَلَقَدْ هَمَّتْ بِهِۦ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَٰنَ رَبِّهِۦ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ', '218124cb05f67686e8354783a02ef8b11c924c5931cd9b1c96be0db9c6d50a20', '218124cb05f67686e8354783a02ef8b11c924c5931cd9b1c96be0db9c6d50a20', NULL, 'ولقد همت به وهم بها لولا ان رءا برهن ربه كذلك لنصرف عنه السوء والفحشاء انه من عبادنا المخلصين', 12, 24, 95, 1, 3, 238, false, NULL),
    (1621, 'tanzil-uthmani-v1.1', 12, 25, 'وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ', 'c3cf83a1d0d7ce0a6fb4a0028429263e56d6d815782824befbcd60cae49c31be', 'وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌ', 'c3cf83a1d0d7ce0a6fb4a0028429263e56d6d815782824befbcd60cae49c31be', 'c3cf83a1d0d7ce0a6fb4a0028429263e56d6d815782824befbcd60cae49c31be', NULL, 'واستبقا الباب وقدت قميصه من دبر والفيا سيدها لدا الباب قالت ما جزاء من اراد باهلك سوءا الا ان يسجن او عذاب اليم', 12, 24, 95, 1, 3, 238, false, NULL),
    (1622, 'tanzil-uthmani-v1.1', 12, 26, 'قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَٰذِبِينَ', 'ed1c225974de6c17a134ebc569f9531c5542520f13fb25d65b860a958382819e', 'قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى وَشَهِدَ شَاهِدٌ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَٰذِبِينَ', 'ed1c225974de6c17a134ebc569f9531c5542520f13fb25d65b860a958382819e', 'ed1c225974de6c17a134ebc569f9531c5542520f13fb25d65b860a958382819e', NULL, 'قال هي رودتني عن نفسي وشهد شاهد من اهلها ان كان قميصه قد من قبل فصدقت وهو من الكذبين', 12, 24, 95, 1, 3, 238, false, NULL),
    (1623, 'tanzil-uthmani-v1.1', 12, 27, 'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّٰدِقِينَ', 'd438f501f7a6923a3be446e698a9a52026e2ae64aa7092782d7a24a18c6bd8f9', 'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّٰدِقِينَ', 'd438f501f7a6923a3be446e698a9a52026e2ae64aa7092782d7a24a18c6bd8f9', 'd438f501f7a6923a3be446e698a9a52026e2ae64aa7092782d7a24a18c6bd8f9', NULL, 'وان كان قميصه قد من دبر فكذبت وهو من الصدقين', 12, 24, 95, 1, 3, 238, false, NULL),
    (1624, 'tanzil-uthmani-v1.1', 12, 28, 'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ', 'e64689e812c65539b5c5bd4999dfb3d13c4bc58fd7266c7462e240f6dd83a318', 'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ إِنَّ كَيْدَكُنَّ عَظِيمٌ', 'e64689e812c65539b5c5bd4999dfb3d13c4bc58fd7266c7462e240f6dd83a318', 'e64689e812c65539b5c5bd4999dfb3d13c4bc58fd7266c7462e240f6dd83a318', NULL, 'فلما رءا قميصه قد من دبر قال انه من كيدكن ان كيدكن عظيم', 12, 24, 95, 1, 3, 238, false, NULL),
    (1625, 'tanzil-uthmani-v1.1', 12, 29, 'يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَٱسْتَغْفِرِى لِذَنۢبِكِ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ', 'ad51ad18d1ffd02539663cd3ba03860c9b8f22af654ddedfdf4a57134827b103', 'يُوسُفُ أَعْرِضْ عَنْ هَٰذَا وَٱسْتَغْفِرِى لِذَنۢبِكِ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ', 'ad51ad18d1ffd02539663cd3ba03860c9b8f22af654ddedfdf4a57134827b103', 'ad51ad18d1ffd02539663cd3ba03860c9b8f22af654ddedfdf4a57134827b103', NULL, 'يوسف اعرض عن هذا واستغفري لذنبك انك كنت من الخاطين', 12, 24, 95, 1, 3, 238, false, NULL),
    (1626, 'tanzil-uthmani-v1.1', 12, 30, 'وَقَالَ نِسْوَةٌ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ قَدْ شَغَفَهَا حُبًّا إِنَّا لَنَرَىٰهَا فِى ضَلَٰلٍ مُّبِينٍ', 'f990b4adf8faa251f6a8fe7f875bc8cde06d1f9c7f923dd41897e5eeecd4c7bc', 'وَقَالَ نِسْوَةٌ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ قَدْ شَغَفَهَا حُبًّا إِنَّا لَنَرَىٰهَا فِى ضَلَٰلٍ مُّبِينٍ', 'f990b4adf8faa251f6a8fe7f875bc8cde06d1f9c7f923dd41897e5eeecd4c7bc', 'f990b4adf8faa251f6a8fe7f875bc8cde06d1f9c7f923dd41897e5eeecd4c7bc', NULL, 'وقال نسوه في المدينه امرات العزيز ترود فتيها عن نفسه قد شغفها حبا انا لنريها في ضلل مبين', 12, 24, 96, 1, 3, 238, false, NULL),
    (1627, 'tanzil-uthmani-v1.1', 12, 31, 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنْ هَٰذَآ إِلَّا مَلَكٌ كَرِيمٌ', '8ae7edb0be67d5e84e5ed6efd71b8267dd11c383539a8c1d663fb3695a3742f4', 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنْ هَٰذَآ إِلَّا مَلَكٌ كَرِيمٌ', '8ae7edb0be67d5e84e5ed6efd71b8267dd11c383539a8c1d663fb3695a3742f4', '8ae7edb0be67d5e84e5ed6efd71b8267dd11c383539a8c1d663fb3695a3742f4', NULL, 'فلما سمعت بمكرهن ارسلت اليهن واعتدت لهن متكا وءاتت كل وحده منهن سكينا وقالت اخرج عليهن فلما راينه اكبرنه وقطعن ايديهن وقلن حش لله ما هذا بشرا ان هذا الا ملك كريم', 12, 24, 96, 1, 3, 239, false, NULL),
    (1628, 'tanzil-uthmani-v1.1', 12, 32, 'قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ ٱلصَّٰغِرِينَ', '58dc5abe5d738eec79ac32948c5eeddf80a6a94f19ace5516d061a314b53d132', 'قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ ٱلصَّٰغِرِينَ', '58dc5abe5d738eec79ac32948c5eeddf80a6a94f19ace5516d061a314b53d132', '58dc5abe5d738eec79ac32948c5eeddf80a6a94f19ace5516d061a314b53d132', NULL, 'قالت فذلكن الذي لمتنني فيه ولقد رودته عن نفسه فاستعصم ولئن لم يفعل ما ءامره ليسجنن وليكونا من الصغرين', 12, 24, 96, 1, 3, 239, false, NULL),
    (1629, 'tanzil-uthmani-v1.1', 12, 33, 'قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَٰهِلِينَ', '05ce7f6b055d0b7f5ae5271823b187567f423425d90e28af709afc89db8b9198', 'قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَٰهِلِينَ', '05ce7f6b055d0b7f5ae5271823b187567f423425d90e28af709afc89db8b9198', '05ce7f6b055d0b7f5ae5271823b187567f423425d90e28af709afc89db8b9198', NULL, 'قال رب السجن احب الي مما يدعونني اليه والا تصرف عني كيدهن اصب اليهن واكن من الجهلين', 12, 24, 96, 1, 3, 239, false, NULL),
    (1630, 'tanzil-uthmani-v1.1', 12, 34, 'فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '7a5dcf1183dcc0d52a3c137816f84397459e15832e3cc96baaed29630b3b32f4', 'فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '7a5dcf1183dcc0d52a3c137816f84397459e15832e3cc96baaed29630b3b32f4', '7a5dcf1183dcc0d52a3c137816f84397459e15832e3cc96baaed29630b3b32f4', NULL, 'فاستجاب له ربه فصرف عنه كيدهن انه هو السميع العليم', 12, 24, 96, 1, 3, 239, false, NULL),
    (1631, 'tanzil-uthmani-v1.1', 12, 35, 'ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْـَٔايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍ', '8d8b960873854ec3ae681078a855b2cdb58374315bd9e9ddc93b2afe3dc69bb5', 'ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْـَٔايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍ', '8d8b960873854ec3ae681078a855b2cdb58374315bd9e9ddc93b2afe3dc69bb5', '8d8b960873854ec3ae681078a855b2cdb58374315bd9e9ddc93b2afe3dc69bb5', NULL, 'ثم بدا لهم من بعد ما راوا الايت ليسجننه حتي حين', 12, 24, 96, 1, 3, 239, false, NULL),
    (1632, 'tanzil-uthmani-v1.1', 12, 36, 'وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًا وَقَالَ ٱلْـَٔاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًا تَأْكُلُ ٱلطَّيْرُ مِنْهُ نَبِّئْنَا بِتَأْوِيلِهِۦٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 'c18fd233fe4fc0ae41862eca928d5cc3a297fbd4177f569b852f9368a9f333ae', 'وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًا وَقَالَ ٱلْـَٔاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًا تَأْكُلُ ٱلطَّيْرُ مِنْهُ نَبِّئْنَا بِتَأْوِيلِهِۦٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 'c18fd233fe4fc0ae41862eca928d5cc3a297fbd4177f569b852f9368a9f333ae', 'c18fd233fe4fc0ae41862eca928d5cc3a297fbd4177f569b852f9368a9f333ae', NULL, 'ودخل معه السجن فتيان قال احدهما اني اريني اعصر خمرا وقال الاخر اني اريني احمل فوق راسي خبزا تاكل الطير منه نبئنا بتاويله انا نريك من المحسنين', 12, 24, 96, 1, 3, 239, false, NULL),
    (1633, 'tanzil-uthmani-v1.1', 12, 37, 'قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ', '9a48072da934619da876f64ed5d1af3d6f54a4a69360621992599754ca0ec202', 'قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ', '9a48072da934619da876f64ed5d1af3d6f54a4a69360621992599754ca0ec202', '9a48072da934619da876f64ed5d1af3d6f54a4a69360621992599754ca0ec202', NULL, 'قال لا ياتيكما طعام ترزقانه الا نباتكما بتاويله قبل ان ياتيكما ذلكما مما علمني ربي اني تركت مله قوم لا يؤمنون بالله وهم بالاخره هم كفرون', 12, 24, 96, 1, 3, 239, false, NULL),
    (1634, 'tanzil-uthmani-v1.1', 12, 38, 'وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', '65ae9da057582261badfb1877a70cb3568ba2233d755cfb9e8a11d4099b748a0', 'وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', '65ae9da057582261badfb1877a70cb3568ba2233d755cfb9e8a11d4099b748a0', '65ae9da057582261badfb1877a70cb3568ba2233d755cfb9e8a11d4099b748a0', NULL, 'واتبعت مله ءاباءي ابرهيم واسحق ويعقوب ما كان لنا ان نشرك بالله من شيء ذلك من فضل الله علينا وعلي الناس ولكن اكثر الناس لا يشكرون', 12, 24, 96, 1, 3, 240, false, NULL),
    (1635, 'tanzil-uthmani-v1.1', 12, 39, 'يَٰصَٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', '125ed863421bd3f95e3b483be63eaad2ef8316216fbfe23fdfdac7539943c4f5', 'يَٰصَٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', '125ed863421bd3f95e3b483be63eaad2ef8316216fbfe23fdfdac7539943c4f5', '125ed863421bd3f95e3b483be63eaad2ef8316216fbfe23fdfdac7539943c4f5', NULL, 'يصحبي السجن ءارباب متفرقون خير ام الله الوحد القهار', 12, 24, 96, 1, 3, 240, false, NULL),
    (1636, 'tanzil-uthmani-v1.1', 12, 40, 'مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءً سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '2582d0840d6e2d8c39c2b24da4371297026f9f17a7c3f9fd066134cf3950e002', 'مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءً سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '2582d0840d6e2d8c39c2b24da4371297026f9f17a7c3f9fd066134cf3950e002', '2582d0840d6e2d8c39c2b24da4371297026f9f17a7c3f9fd066134cf3950e002', NULL, 'ما تعبدون من دونه الا اسماء سميتموها انتم وءاباؤكم ما انزل الله بها من سلطن ان الحكم الا لله امر الا تعبدوا الا اياه ذلك الدين القيم ولكن اكثر الناس لا يعلمون', 12, 24, 96, 1, 3, 240, false, NULL),
    (1637, 'tanzil-uthmani-v1.1', 12, 41, 'يَٰصَٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًا وَأَمَّا ٱلْـَٔاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ', '280def09c764e9ca889e5faeb59ad731a250ba98a82ec2150463d273715ea928', 'يَٰصَٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًا وَأَمَّا ٱلْـَٔاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ', '280def09c764e9ca889e5faeb59ad731a250ba98a82ec2150463d273715ea928', '280def09c764e9ca889e5faeb59ad731a250ba98a82ec2150463d273715ea928', NULL, 'يصحبي السجن اما احدكما فيسقي ربه خمرا واما الاخر فيصلب فتاكل الطير من راسه قضي الامر الذي فيه تستفتيان', 12, 24, 96, 1, 3, 240, false, NULL),
    (1638, 'tanzil-uthmani-v1.1', 12, 42, 'وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ', '0af52ab0e374cedf2431e7ca0fb35d3d3551a46a9c9c9ac8ff2f650505641db5', 'وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ', '0af52ab0e374cedf2431e7ca0fb35d3d3551a46a9c9c9ac8ff2f650505641db5', '0af52ab0e374cedf2431e7ca0fb35d3d3551a46a9c9c9ac8ff2f650505641db5', NULL, 'وقال للذي ظن انه ناج منهما اذكرني عند ربك فانسيه الشيطن ذكر ربه فلبث في السجن بضع سنين', 12, 24, 96, 1, 3, 240, false, NULL),
    (1639, 'tanzil-uthmani-v1.1', 12, 43, 'وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ يَٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ', '5e96b171fbdec245e473b0a65010980f81d59f1069876523564a6194a1bc2c08', 'وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ يَٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ', '5e96b171fbdec245e473b0a65010980f81d59f1069876523564a6194a1bc2c08', '5e96b171fbdec245e473b0a65010980f81d59f1069876523564a6194a1bc2c08', NULL, 'وقال الملك اني اري سبع بقرت سمان ياكلهن سبع عجاف وسبع سنبلت خضر واخر يابست يايها الملا افتوني في رءيي ان كنتم للرءيا تعبرون', 12, 24, 96, 1, 3, 240, false, NULL),
    (1640, 'tanzil-uthmani-v1.1', 12, 44, 'قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَٰمِ بِعَٰلِمِينَ', '8db03f71df0d6506e1e0d3e32f07865c5e2419dda88d563d96497de3c4793859', 'قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَٰمِ بِعَٰلِمِينَ', '8db03f71df0d6506e1e0d3e32f07865c5e2419dda88d563d96497de3c4793859', '8db03f71df0d6506e1e0d3e32f07865c5e2419dda88d563d96497de3c4793859', NULL, 'قالوا اضغث احلم وما نحن بتاويل الاحلم بعلمين', 12, 24, 96, 1, 3, 241, false, NULL),
    (1641, 'tanzil-uthmani-v1.1', 12, 45, 'وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ', 'b6aa1ae48fa0e310f2a8e2c17aed396a9acb49c428481c7798757b343901fe08', 'وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ', 'b6aa1ae48fa0e310f2a8e2c17aed396a9acb49c428481c7798757b343901fe08', 'b6aa1ae48fa0e310f2a8e2c17aed396a9acb49c428481c7798757b343901fe08', NULL, 'وقال الذي نجا منهما وادكر بعد امه انا انبئكم بتاويله فارسلون', 12, 24, 96, 1, 3, 241, false, NULL),
    (1642, 'tanzil-uthmani-v1.1', 12, 46, 'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ', 'fa69a794943d4888646879077a7f08ab07d282064cd95a4d467e122e21efad5e', 'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنۢبُلَٰتٍ خُضْرٍ وَأُخَرَ يَابِسَٰتٍ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ', 'fa69a794943d4888646879077a7f08ab07d282064cd95a4d467e122e21efad5e', 'fa69a794943d4888646879077a7f08ab07d282064cd95a4d467e122e21efad5e', NULL, 'يوسف ايها الصديق افتنا في سبع بقرت سمان ياكلهن سبع عجاف وسبع سنبلت خضر واخر يابست لعلي ارجع الي الناس لعلهم يعلمون', 12, 24, 96, 1, 3, 241, false, NULL),
    (1643, 'tanzil-uthmani-v1.1', 12, 47, 'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ', '588cb23613a2711c93338d7d724fd10a392c90f47419e4858fc81975da8c0026', 'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ', '588cb23613a2711c93338d7d724fd10a392c90f47419e4858fc81975da8c0026', '588cb23613a2711c93338d7d724fd10a392c90f47419e4858fc81975da8c0026', NULL, 'قال تزرعون سبع سنين دابا فما حصدتم فذروه في سنبله الا قليلا مما تاكلون', 12, 24, 96, 1, 3, 241, false, NULL),
    (1644, 'tanzil-uthmani-v1.1', 12, 48, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ', '7af4691d5614039934f2349924994e01df0f5337e710f33cc539d6dee9cca75e', 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ', '7af4691d5614039934f2349924994e01df0f5337e710f33cc539d6dee9cca75e', '7af4691d5614039934f2349924994e01df0f5337e710f33cc539d6dee9cca75e', NULL, 'ثم ياتي من بعد ذلك سبع شداد ياكلن ما قدمتم لهن الا قليلا مما تحصنون', 12, 24, 96, 1, 3, 241, false, NULL),
    (1645, 'tanzil-uthmani-v1.1', 12, 49, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ', '3149bdcf1f1243839aa85fac18fbd7f945d2d47e95ed9f3384dddccbce3be945', 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ', '3149bdcf1f1243839aa85fac18fbd7f945d2d47e95ed9f3384dddccbce3be945', '3149bdcf1f1243839aa85fac18fbd7f945d2d47e95ed9f3384dddccbce3be945', NULL, 'ثم ياتي من بعد ذلك عام فيه يغاث الناس وفيه يعصرون', 12, 24, 96, 1, 3, 241, false, NULL),
    (1646, 'tanzil-uthmani-v1.1', 12, 50, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّٰتِى قَطَّعْنَ أَيْدِيَهُنَّ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌ', 'fe7aed478d44fb7d769637732193eeaa4d62538b843aa8bf65ec996524d84445', 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّٰتِى قَطَّعْنَ أَيْدِيَهُنَّ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌ', 'fe7aed478d44fb7d769637732193eeaa4d62538b843aa8bf65ec996524d84445', 'fe7aed478d44fb7d769637732193eeaa4d62538b843aa8bf65ec996524d84445', NULL, 'وقال الملك ائتوني به فلما جاءه الرسول قال ارجع الي ربك فسله ما بال النسوه التي قطعن ايديهن ان ربي بكيدهن عليم', 12, 24, 96, 1, 3, 241, false, NULL),
    (1647, 'tanzil-uthmani-v1.1', 12, 51, 'قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ قُلْنَ حَٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٰٔنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', '01be8ef027d875e0c16fe2876ae8c6d8eea52303c1a9bf67fa3559f23e3ed8df', 'قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ قُلْنَ حَٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٰٔنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', '01be8ef027d875e0c16fe2876ae8c6d8eea52303c1a9bf67fa3559f23e3ed8df', '01be8ef027d875e0c16fe2876ae8c6d8eea52303c1a9bf67fa3559f23e3ed8df', NULL, 'قال ما خطبكن اذ رودتن يوسف عن نفسه قلن حش لله ما علمنا عليه من سوء قالت امرات العزيز الن حصحص الحق انا رودته عن نفسه وانه لمن الصدقين', 12, 24, 96, 1, 3, 241, false, NULL),
    (1648, 'tanzil-uthmani-v1.1', 12, 52, 'ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ', 'db5a93180b203647f2cf3a67edf852b86d3186904efa6a9557d198d9855e33c1', 'ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ', 'db5a93180b203647f2cf3a67edf852b86d3186904efa6a9557d198d9855e33c1', 'db5a93180b203647f2cf3a67edf852b86d3186904efa6a9557d198d9855e33c1', NULL, 'ذلك ليعلم اني لم اخنه بالغيب وان الله لا يهدي كيد الخائنين', 12, 24, 96, 1, 3, 241, false, NULL),
    (1649, 'tanzil-uthmani-v1.1', 12, 53, 'وَمَآ أُبَرِّئُ نَفْسِىٓ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ إِنَّ رَبِّى غَفُورٌ رَّحِيمٌ', '7451e99caed04fa1b136bb467e815ba6612b5a8dfcbf245213f6b1abbbd0962c', 'وَمَآ أُبَرِّئُ نَفْسِىٓ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ إِنَّ رَبِّى غَفُورٌ رَّحِيمٌ', '7451e99caed04fa1b136bb467e815ba6612b5a8dfcbf245213f6b1abbbd0962c', '7451e99caed04fa1b136bb467e815ba6612b5a8dfcbf245213f6b1abbbd0962c', NULL, 'وما ابرئ نفسي ان النفس لاماره بالسوء الا ما رحم ربي ان ربي غفور رحيم', 13, 25, 97, 1, 3, 242, false, NULL),
    (1650, 'tanzil-uthmani-v1.1', 12, 54, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ', '904a3056b0f5c2bec4b9f3dfdaecf7be5b3ef2c21598c4820df34cf22f1e96ec', 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌ', '904a3056b0f5c2bec4b9f3dfdaecf7be5b3ef2c21598c4820df34cf22f1e96ec', '904a3056b0f5c2bec4b9f3dfdaecf7be5b3ef2c21598c4820df34cf22f1e96ec', NULL, 'وقال الملك ائتوني به استخلصه لنفسي فلما كلمه قال انك اليوم لدينا مكين امين', 13, 25, 97, 1, 3, 242, false, NULL),
    (1651, 'tanzil-uthmani-v1.1', 12, 55, 'قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ إِنِّى حَفِيظٌ عَلِيمٌ', 'ac47b2181decb1db691e7997f9a62bd1ebd9f6fcc6ae277d8d7c9b07cf03a481', 'قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ إِنِّى حَفِيظٌ عَلِيمٌ', 'ac47b2181decb1db691e7997f9a62bd1ebd9f6fcc6ae277d8d7c9b07cf03a481', 'ac47b2181decb1db691e7997f9a62bd1ebd9f6fcc6ae277d8d7c9b07cf03a481', NULL, 'قال اجعلني علي خزائن الارض اني حفيظ عليم', 13, 25, 97, 1, 3, 242, false, NULL),
    (1652, 'tanzil-uthmani-v1.1', 12, 56, 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '40f9c9a6ae8ec84d93360590d157c528cd8d46cbbf6886ad20912315823d6fb7', 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '40f9c9a6ae8ec84d93360590d157c528cd8d46cbbf6886ad20912315823d6fb7', '40f9c9a6ae8ec84d93360590d157c528cd8d46cbbf6886ad20912315823d6fb7', NULL, 'وكذلك مكنا ليوسف في الارض يتبوا منها حيث يشاء نصيب برحمتنا من نشاء ولا نضيع اجر المحسنين', 13, 25, 97, 1, 3, 242, false, NULL),
    (1653, 'tanzil-uthmani-v1.1', 12, 57, 'وَلَأَجْرُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '1a8c1b8be5a048cdefb0cd8c1a8a5644b461ba2a2468bd1aade5cd4ed197f18b', 'وَلَأَجْرُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '1a8c1b8be5a048cdefb0cd8c1a8a5644b461ba2a2468bd1aade5cd4ed197f18b', '1a8c1b8be5a048cdefb0cd8c1a8a5644b461ba2a2468bd1aade5cd4ed197f18b', NULL, 'ولاجر الاخره خير للذين ءامنوا وكانوا يتقون', 13, 25, 97, 1, 3, 242, false, NULL),
    (1654, 'tanzil-uthmani-v1.1', 12, 58, 'وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ', '2551d164d67e3ce1cf567503ef29429021b31bc524a3e3e0bdcbe1643220f57f', 'وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ', '2551d164d67e3ce1cf567503ef29429021b31bc524a3e3e0bdcbe1643220f57f', '2551d164d67e3ce1cf567503ef29429021b31bc524a3e3e0bdcbe1643220f57f', NULL, 'وجاء اخوه يوسف فدخلوا عليه فعرفهم وهم له منكرون', 13, 25, 97, 1, 3, 242, false, NULL),
    (1655, 'tanzil-uthmani-v1.1', 12, 59, 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ', '415715ccbfb1f00fc566285281e33998d15fd98518c432b86035cdc6ee3ddb54', 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍ لَّكُم مِّنْ أَبِيكُمْ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ', '415715ccbfb1f00fc566285281e33998d15fd98518c432b86035cdc6ee3ddb54', '415715ccbfb1f00fc566285281e33998d15fd98518c432b86035cdc6ee3ddb54', NULL, 'ولما جهزهم بجهازهم قال ائتوني باخ لكم من ابيكم الا ترون اني اوفي الكيل وانا خير المنزلين', 13, 25, 97, 1, 3, 242, false, NULL),
    (1656, 'tanzil-uthmani-v1.1', 12, 60, 'فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ', '738ba58d6b9abec07a29faf6fdf3b7bdba1dfc5d9a3beedebfdbfe636d4e8673', 'فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ', '738ba58d6b9abec07a29faf6fdf3b7bdba1dfc5d9a3beedebfdbfe636d4e8673', '738ba58d6b9abec07a29faf6fdf3b7bdba1dfc5d9a3beedebfdbfe636d4e8673', NULL, 'فان لم تاتوني به فلا كيل لكم عندي ولا تقربون', 13, 25, 97, 1, 3, 242, false, NULL),
    (1657, 'tanzil-uthmani-v1.1', 12, 61, 'قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ', '6c138d0576e17ddc4ca3474504c32631b4a8303225d67d68a88f7e6404e825d3', 'قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ', '6c138d0576e17ddc4ca3474504c32631b4a8303225d67d68a88f7e6404e825d3', '6c138d0576e17ddc4ca3474504c32631b4a8303225d67d68a88f7e6404e825d3', NULL, 'قالوا سنرود عنه اباه وانا لفعلون', 13, 25, 97, 1, 3, 242, false, NULL),
    (1658, 'tanzil-uthmani-v1.1', 12, 62, 'وَقَالَ لِفِتْيَٰنِهِ ٱجْعَلُوا۟ بِضَٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ', '3ecedb467097557f72bf50802d38222dda293cad6cf4f7f1ba493d1b4e98be5f', 'وَقَالَ لِفِتْيَٰنِهِ ٱجْعَلُوا۟ بِضَٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ', '3ecedb467097557f72bf50802d38222dda293cad6cf4f7f1ba493d1b4e98be5f', '3ecedb467097557f72bf50802d38222dda293cad6cf4f7f1ba493d1b4e98be5f', NULL, 'وقال لفتينه اجعلوا بضعتهم في رحالهم لعلهم يعرفونها اذا انقلبوا الي اهلهم لعلهم يرجعون', 13, 25, 97, 1, 3, 242, false, NULL),
    (1659, 'tanzil-uthmani-v1.1', 12, 63, 'فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', '0dc1833d62fab4914993533b00e94ecf579e70d9255c6cd88d96bae4ca2ca4bd', 'فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', '0dc1833d62fab4914993533b00e94ecf579e70d9255c6cd88d96bae4ca2ca4bd', '0dc1833d62fab4914993533b00e94ecf579e70d9255c6cd88d96bae4ca2ca4bd', NULL, 'فلما رجعوا الي ابيهم قالوا يابانا منع منا الكيل فارسل معنا اخانا نكتل وانا له لحفظون', 13, 25, 97, 1, 3, 242, false, NULL),
    (1660, 'tanzil-uthmani-v1.1', 12, 64, 'قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ فَٱللَّهُ خَيْرٌ حَٰفِظًا وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', '369d21dd6aa211c387f31b15aa2d0f64d2745d7f770391b42d610733f4b3d752', 'قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ فَٱللَّهُ خَيْرٌ حَٰفِظًا وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', '369d21dd6aa211c387f31b15aa2d0f64d2745d7f770391b42d610733f4b3d752', '369d21dd6aa211c387f31b15aa2d0f64d2745d7f770391b42d610733f4b3d752', NULL, 'قال هل ءامنكم عليه الا كما امنتكم علي اخيه من قبل فالله خير حفظا وهو ارحم الرحمين', 13, 25, 97, 1, 3, 243, false, NULL),
    (1661, 'tanzil-uthmani-v1.1', 12, 65, 'وَلَمَّا فَتَحُوا۟ مَتَٰعَهُمْ وَجَدُوا۟ بِضَٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ قَالُوا۟ يَٰٓأَبَانَا مَا نَبْغِى هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتْ إِلَيْنَا وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ذَٰلِكَ كَيْلٌ يَسِيرٌ', '5dafe0d7f1a4bb887312531486c25e02e3de6de8dc4c8503e8487521c1764411', 'وَلَمَّا فَتَحُوا۟ مَتَٰعَهُمْ وَجَدُوا۟ بِضَٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ قَالُوا۟ يَٰٓأَبَانَا مَا نَبْغِى هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتْ إِلَيْنَا وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍ ذَٰلِكَ كَيْلٌ يَسِيرٌ', '5dafe0d7f1a4bb887312531486c25e02e3de6de8dc4c8503e8487521c1764411', '5dafe0d7f1a4bb887312531486c25e02e3de6de8dc4c8503e8487521c1764411', NULL, 'ولما فتحوا متعهم وجدوا بضعتهم ردت اليهم قالوا يابانا ما نبغي هذه بضعتنا ردت الينا ونمير اهلنا ونحفظ اخانا ونزداد كيل بعير ذلك كيل يسير', 13, 25, 97, 1, 3, 243, false, NULL),
    (1662, 'tanzil-uthmani-v1.1', 12, 66, 'قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', 'f9da36fc9f4faf26f94c5c4a978d8521dd43dc2ecbab1d652cdf04056162955f', 'قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', 'f9da36fc9f4faf26f94c5c4a978d8521dd43dc2ecbab1d652cdf04056162955f', 'f9da36fc9f4faf26f94c5c4a978d8521dd43dc2ecbab1d652cdf04056162955f', NULL, 'قال لن ارسله معكم حتي تؤتون موثقا من الله لتاتنني به الا ان يحاط بكم فلما ءاتوه موثقهم قال الله علي ما نقول وكيل', 13, 25, 97, 1, 3, 243, false, NULL),
    (1663, 'tanzil-uthmani-v1.1', 12, 67, 'وَقَالَ يَٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍ وَٰحِدٍ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍ مُّتَفَرِّقَةٍ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ عَلَيْهِ تَوَكَّلْتُ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', '93510c0d5fab9ad937505630721586a7220078803f2e7799e3219775405fd071', 'وَقَالَ يَٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍ وَٰحِدٍ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍ مُّتَفَرِّقَةٍ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ عَلَيْهِ تَوَكَّلْتُ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', '93510c0d5fab9ad937505630721586a7220078803f2e7799e3219775405fd071', '93510c0d5fab9ad937505630721586a7220078803f2e7799e3219775405fd071', NULL, 'وقال يبني لا تدخلوا من باب وحد وادخلوا من ابوب متفرقه وما اغني عنكم من الله من شيء ان الحكم الا لله عليه توكلت وعليه فليتوكل المتوكلون', 13, 25, 97, 1, 3, 243, false, NULL),
    (1664, 'tanzil-uthmani-v1.1', 12, 68, 'وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةً فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا وَإِنَّهُۥ لَذُو عِلْمٍ لِّمَا عَلَّمْنَٰهُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '25f6bb69e6e29e20a7acb4447662fd4ef7330a82e4ebe062cec35e8020aedffd', 'وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةً فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا وَإِنَّهُۥ لَذُو عِلْمٍ لِّمَا عَلَّمْنَٰهُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '25f6bb69e6e29e20a7acb4447662fd4ef7330a82e4ebe062cec35e8020aedffd', '25f6bb69e6e29e20a7acb4447662fd4ef7330a82e4ebe062cec35e8020aedffd', NULL, 'ولما دخلوا من حيث امرهم ابوهم ما كان يغني عنهم من الله من شيء الا حاجه في نفس يعقوب قضيها وانه لذو علم لما علمنه ولكن اكثر الناس لا يعلمون', 13, 25, 97, 1, 3, 243, false, NULL),
    (1665, 'tanzil-uthmani-v1.1', 12, 69, 'وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ', 'fd3f96ef995b636cad6cd115fd354a02a3b1bcbca54c3296cb7f75c531968b6a', 'وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ', 'fd3f96ef995b636cad6cd115fd354a02a3b1bcbca54c3296cb7f75c531968b6a', 'fd3f96ef995b636cad6cd115fd354a02a3b1bcbca54c3296cb7f75c531968b6a', NULL, 'ولما دخلوا علي يوسف ءاوي اليه اخاه قال اني انا اخوك فلا تبتئس بما كانوا يعملون', 13, 25, 97, 1, 3, 243, false, NULL),
    (1666, 'tanzil-uthmani-v1.1', 12, 70, 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَٰرِقُونَ', '4c02cf83adeb0853c23fe4cee0d40af93c117a6db700375a4fd0903d0bc187a0', 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَٰرِقُونَ', '4c02cf83adeb0853c23fe4cee0d40af93c117a6db700375a4fd0903d0bc187a0', '4c02cf83adeb0853c23fe4cee0d40af93c117a6db700375a4fd0903d0bc187a0', NULL, 'فلما جهزهم بجهازهم جعل السقايه في رحل اخيه ثم اذن مؤذن ايتها العير انكم لسرقون', 13, 25, 97, 1, 3, 244, false, NULL),
    (1667, 'tanzil-uthmani-v1.1', 12, 71, 'قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ', '7b3ab0692a3634ae9e93f14d9418293f97463bf1f11d22318301dc14c4db0e4b', 'قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ', '7b3ab0692a3634ae9e93f14d9418293f97463bf1f11d22318301dc14c4db0e4b', '7b3ab0692a3634ae9e93f14d9418293f97463bf1f11d22318301dc14c4db0e4b', NULL, 'قالوا واقبلوا عليهم ماذا تفقدون', 13, 25, 97, 1, 3, 244, false, NULL),
    (1668, 'tanzil-uthmani-v1.1', 12, 72, 'قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍ وَأَنَا۠ بِهِۦ زَعِيمٌ', '9eea8dfc665b402728e6f58ea6190bec931c6a549929c41df46373309ce6aab5', 'قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍ وَأَنَا۠ بِهِۦ زَعِيمٌ', '9eea8dfc665b402728e6f58ea6190bec931c6a549929c41df46373309ce6aab5', '9eea8dfc665b402728e6f58ea6190bec931c6a549929c41df46373309ce6aab5', NULL, 'قالوا نفقد صواع الملك ولمن جاء به حمل بعير وانا به زعيم', 13, 25, 97, 1, 3, 244, false, NULL),
    (1669, 'tanzil-uthmani-v1.1', 12, 73, 'قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَٰرِقِينَ', 'dfab9b6b07439b98b1f74d7fbae70c0a6f32be802de5501698c64a811a6182fd', 'قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَٰرِقِينَ', 'dfab9b6b07439b98b1f74d7fbae70c0a6f32be802de5501698c64a811a6182fd', 'dfab9b6b07439b98b1f74d7fbae70c0a6f32be802de5501698c64a811a6182fd', NULL, 'قالوا تالله لقد علمتم ما جئنا لنفسد في الارض وما كنا سرقين', 13, 25, 97, 1, 3, 244, false, NULL),
    (1670, 'tanzil-uthmani-v1.1', 12, 74, 'قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَٰذِبِينَ', '1d8b4e0ae57270d0c6b8eca514a90be5e2327281d960b12b6b0ad3ccbc46782a', 'قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَٰذِبِينَ', '1d8b4e0ae57270d0c6b8eca514a90be5e2327281d960b12b6b0ad3ccbc46782a', '1d8b4e0ae57270d0c6b8eca514a90be5e2327281d960b12b6b0ad3ccbc46782a', NULL, 'قالوا فما جزؤه ان كنتم كذبين', 13, 25, 97, 1, 3, 244, false, NULL),
    (1671, 'tanzil-uthmani-v1.1', 12, 75, 'قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'abb0fa88808ce415a25d4bded17350a5e8fb18160759b77c2ffda40ce24cb592', 'قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 'abb0fa88808ce415a25d4bded17350a5e8fb18160759b77c2ffda40ce24cb592', 'abb0fa88808ce415a25d4bded17350a5e8fb18160759b77c2ffda40ce24cb592', NULL, 'قالوا جزؤه من وجد في رحله فهو جزؤه كذلك نجزي الظلمين', 13, 25, 97, 1, 3, 244, false, NULL),
    (1672, 'tanzil-uthmani-v1.1', 12, 76, 'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ كَذَٰلِكَ كِدْنَا لِيُوسُفَ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌ', '6f0fc5d97c8e4b15f3eb42960968a199756c8a03940d2797b4bdbbd2b7a1d899', 'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ كَذَٰلِكَ كِدْنَا لِيُوسُفَ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ نَرْفَعُ دَرَجَٰتٍ مَّن نَّشَآءُ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌ', '6f0fc5d97c8e4b15f3eb42960968a199756c8a03940d2797b4bdbbd2b7a1d899', '6f0fc5d97c8e4b15f3eb42960968a199756c8a03940d2797b4bdbbd2b7a1d899', NULL, 'فبدا باوعيتهم قبل وعاء اخيه ثم استخرجها من وعاء اخيه كذلك كدنا ليوسف ما كان لياخذ اخاه في دين الملك الا ان يشاء الله نرفع درجت من نشاء وفوق كل ذي علم عليم', 13, 25, 97, 1, 3, 244, false, NULL),
    (1673, 'tanzil-uthmani-v1.1', 12, 77, 'قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُۥ مِن قَبْلُ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ قَالَ أَنتُمْ شَرٌّ مَّكَانًا وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ', 'e81b209f2adeb453ddc89c1d6396f4eb8273b1517fed478967a16d0a8dee8eca', 'قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُۥ مِن قَبْلُ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ قَالَ أَنتُمْ شَرٌّ مَّكَانًا وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ', 'e81b209f2adeb453ddc89c1d6396f4eb8273b1517fed478967a16d0a8dee8eca', 'e81b209f2adeb453ddc89c1d6396f4eb8273b1517fed478967a16d0a8dee8eca', NULL, 'قالوا ان يسرق فقد سرق اخ له من قبل فاسرها يوسف في نفسه ولم يبدها لهم قال انتم شر مكانا والله اعلم بما تصفون', 13, 25, 98, 1, 3, 244, false, NULL),
    (1674, 'tanzil-uthmani-v1.1', 12, 78, 'قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', '582fca2bb351a284ff071d896cd41c5952b65de7f9dd21f0d592e2211f3ef945', 'قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', '582fca2bb351a284ff071d896cd41c5952b65de7f9dd21f0d592e2211f3ef945', '582fca2bb351a284ff071d896cd41c5952b65de7f9dd21f0d592e2211f3ef945', NULL, 'قالوا يايها العزيز ان له ابا شيخا كبيرا فخذ احدنا مكانه انا نريك من المحسنين', 13, 25, 98, 1, 3, 244, false, NULL),
    (1675, 'tanzil-uthmani-v1.1', 12, 79, 'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذًا لَّظَٰلِمُونَ', '0087c2fdbf6d569ee36fd0583caa5eef9397cdd52e5bdbedfe7dc95ca8cf6c7d', 'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذًا لَّظَٰلِمُونَ', '0087c2fdbf6d569ee36fd0583caa5eef9397cdd52e5bdbedfe7dc95ca8cf6c7d', '0087c2fdbf6d569ee36fd0583caa5eef9397cdd52e5bdbedfe7dc95ca8cf6c7d', NULL, 'قال معاذ الله ان ناخذ الا من وجدنا متعنا عنده انا اذا لظلمون', 13, 25, 98, 1, 3, 245, false, NULL),
    (1676, 'tanzil-uthmani-v1.1', 12, 80, 'فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّا قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', '54f8c7c0d6f37b1a90b907bfd97416f530284a1a312e1f34886de538c95665f5', 'فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّا قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', '54f8c7c0d6f37b1a90b907bfd97416f530284a1a312e1f34886de538c95665f5', '54f8c7c0d6f37b1a90b907bfd97416f530284a1a312e1f34886de538c95665f5', NULL, 'فلما استيسوا منه خلصوا نجيا قال كبيرهم الم تعلموا ان اباكم قد اخذ عليكم موثقا من الله ومن قبل ما فرطتم في يوسف فلن ابرح الارض حتي ياذن لي ابي او يحكم الله لي وهو خير الحكمين', 13, 25, 98, 1, 3, 245, false, NULL),
    (1677, 'tanzil-uthmani-v1.1', 12, 81, 'ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَٰفِظِينَ', 'ba130db3a5afe56a95f54cd7e7d2ecae68743c4aeb94988d4d1648ede996a878', 'ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَٰفِظِينَ', 'ba130db3a5afe56a95f54cd7e7d2ecae68743c4aeb94988d4d1648ede996a878', 'ba130db3a5afe56a95f54cd7e7d2ecae68743c4aeb94988d4d1648ede996a878', NULL, 'ارجعوا الي ابيكم فقولوا يابانا ان ابنك سرق وما شهدنا الا بما علمنا وما كنا للغيب حفظين', 13, 25, 98, 1, 3, 245, false, NULL),
    (1678, 'tanzil-uthmani-v1.1', 12, 82, 'وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا وَإِنَّا لَصَٰدِقُونَ', 'd47898e405554b0bf1dd8dbdb432b75c1c984d5874de0304d69753a5be13fc18', 'وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا وَإِنَّا لَصَٰدِقُونَ', 'd47898e405554b0bf1dd8dbdb432b75c1c984d5874de0304d69753a5be13fc18', 'd47898e405554b0bf1dd8dbdb432b75c1c984d5874de0304d69753a5be13fc18', NULL, 'وسل القريه التي كنا فيها والعير التي اقبلنا فيها وانا لصدقون', 13, 25, 98, 1, 3, 245, false, NULL),
    (1679, 'tanzil-uthmani-v1.1', 12, 83, 'قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '8db89ec499744e7f53c0a12325d43285370ad99c46cfbbeac4b4baa3cf9bba8d', 'قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '8db89ec499744e7f53c0a12325d43285370ad99c46cfbbeac4b4baa3cf9bba8d', '8db89ec499744e7f53c0a12325d43285370ad99c46cfbbeac4b4baa3cf9bba8d', NULL, 'قال بل سولت لكم انفسكم امرا فصبر جميل عسي الله ان ياتيني بهم جميعا انه هو العليم الحكيم', 13, 25, 98, 1, 3, 245, false, NULL),
    (1680, 'tanzil-uthmani-v1.1', 12, 84, 'وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌ', '45798134bfc44c62f83970a8c6606a49c4c8679cf331d0dde8a8f0c8b3df8908', 'وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌ', '45798134bfc44c62f83970a8c6606a49c4c8679cf331d0dde8a8f0c8b3df8908', '45798134bfc44c62f83970a8c6606a49c4c8679cf331d0dde8a8f0c8b3df8908', NULL, 'وتولي عنهم وقال ياسفي علي يوسف وابيضت عيناه من الحزن فهو كظيم', 13, 25, 98, 1, 3, 245, false, NULL),
    (1681, 'tanzil-uthmani-v1.1', 12, 85, 'قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَٰلِكِينَ', 'bc517f426b5f842f78a23ea85f51fc24a9a9f4844b2b361597174c65ff1e5147', 'قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَٰلِكِينَ', 'bc517f426b5f842f78a23ea85f51fc24a9a9f4844b2b361597174c65ff1e5147', 'bc517f426b5f842f78a23ea85f51fc24a9a9f4844b2b361597174c65ff1e5147', NULL, 'قالوا تالله تفتؤا تذكر يوسف حتي تكون حرضا او تكون من الهلكين', 13, 25, 98, 1, 3, 245, false, NULL),
    (1682, 'tanzil-uthmani-v1.1', 12, 86, 'قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', '8596bd260ebd91de049a9a7773b8914171b53c88fd5066499bc3f33a803cedb0', 'قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', '8596bd260ebd91de049a9a7773b8914171b53c88fd5066499bc3f33a803cedb0', '8596bd260ebd91de049a9a7773b8914171b53c88fd5066499bc3f33a803cedb0', NULL, 'قال انما اشكوا بثي وحزني الي الله واعلم من الله ما لا تعلمون', 13, 25, 98, 1, 3, 245, false, NULL),
    (1683, 'tanzil-uthmani-v1.1', 12, 87, 'يَٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَٰفِرُونَ', '6e69b7f9c92d0c916ee6beea837f4933ac02f4dc1c42b5d65d8ce39aacaec047', 'يَٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَٰفِرُونَ', '6e69b7f9c92d0c916ee6beea837f4933ac02f4dc1c42b5d65d8ce39aacaec047', '6e69b7f9c92d0c916ee6beea837f4933ac02f4dc1c42b5d65d8ce39aacaec047', NULL, 'يبني اذهبوا فتحسسوا من يوسف واخيه ولا تايسوا من روح الله انه لا يايس من روح الله الا القوم الكفرون', 13, 25, 98, 1, 3, 246, false, NULL),
    (1684, 'tanzil-uthmani-v1.1', 12, 88, 'فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَٰعَةٍ مُّزْجَىٰةٍ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ', '31ad9526adc98c63b96bad139b3591f48826428651ed6940046863c15e6c4106', 'فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَٰعَةٍ مُّزْجَىٰةٍ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ', '31ad9526adc98c63b96bad139b3591f48826428651ed6940046863c15e6c4106', '31ad9526adc98c63b96bad139b3591f48826428651ed6940046863c15e6c4106', NULL, 'فلما دخلوا عليه قالوا يايها العزيز مسنا واهلنا الضر وجئنا ببضعه مزجيه فاوف لنا الكيل وتصدق علينا ان الله يجزي المتصدقين', 13, 25, 98, 1, 3, 246, false, NULL),
    (1685, 'tanzil-uthmani-v1.1', 12, 89, 'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَٰهِلُونَ', '494c9c33fe44f7cbd45cb1efc7f584223a1c84720d31d194600a17e6f61992bd', 'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَٰهِلُونَ', '494c9c33fe44f7cbd45cb1efc7f584223a1c84720d31d194600a17e6f61992bd', '494c9c33fe44f7cbd45cb1efc7f584223a1c84720d31d194600a17e6f61992bd', NULL, 'قال هل علمتم ما فعلتم بيوسف واخيه اذ انتم جهلون', 13, 25, 98, 1, 3, 246, false, NULL),
    (1686, 'tanzil-uthmani-v1.1', 12, 90, 'قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِى قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '9aea71efbcda0100ce924288d50a06898f009cd4dbff26a86187ecbd5a5a958d', 'قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِى قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', '9aea71efbcda0100ce924288d50a06898f009cd4dbff26a86187ecbd5a5a958d', '9aea71efbcda0100ce924288d50a06898f009cd4dbff26a86187ecbd5a5a958d', NULL, 'قالوا اءنك لانت يوسف قال انا يوسف وهذا اخي قد من الله علينا انه من يتق ويصبر فان الله لا يضيع اجر المحسنين', 13, 25, 98, 1, 3, 246, false, NULL),
    (1687, 'tanzil-uthmani-v1.1', 12, 91, 'قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَٰطِـِٔينَ', 'c0bd23987dff59971f4549695dd766fb129dc564e669c7aad1f864c7f59781a3', 'قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَٰطِـِٔينَ', 'c0bd23987dff59971f4549695dd766fb129dc564e669c7aad1f864c7f59781a3', 'c0bd23987dff59971f4549695dd766fb129dc564e669c7aad1f864c7f59781a3', NULL, 'قالوا تالله لقد ءاثرك الله علينا وان كنا لخطين', 13, 25, 98, 1, 3, 246, false, NULL),
    (1688, 'tanzil-uthmani-v1.1', 12, 92, 'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ يَغْفِرُ ٱللَّهُ لَكُمْ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', '63711192e82f53b4028a7284336e39da64e84e9a9e478c84a7aee329c2aeef47', 'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ يَغْفِرُ ٱللَّهُ لَكُمْ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', '63711192e82f53b4028a7284336e39da64e84e9a9e478c84a7aee329c2aeef47', '63711192e82f53b4028a7284336e39da64e84e9a9e478c84a7aee329c2aeef47', NULL, 'قال لا تثريب عليكم اليوم يغفر الله لكم وهو ارحم الرحمين', 13, 25, 98, 1, 3, 246, false, NULL),
    (1689, 'tanzil-uthmani-v1.1', 12, 93, 'ٱذْهَبُوا۟ بِقَمِيصِى هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ', '3eb83b388c94f8c53a3f3fabcab63c325d3e1b7ed0db4005c1191dcde9a43cfb', 'ٱذْهَبُوا۟ بِقَمِيصِى هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ', '3eb83b388c94f8c53a3f3fabcab63c325d3e1b7ed0db4005c1191dcde9a43cfb', '3eb83b388c94f8c53a3f3fabcab63c325d3e1b7ed0db4005c1191dcde9a43cfb', NULL, 'اذهبوا بقميصي هذا فالقوه علي وجه ابي يات بصيرا واتوني باهلكم اجمعين', 13, 25, 98, 1, 3, 246, false, NULL),
    (1690, 'tanzil-uthmani-v1.1', 12, 94, 'وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ لَوْلَآ أَن تُفَنِّدُونِ', 'd7516313cd6ffe3fb9c9078bd569d35b777a3aa626b1a4f4bbd699e4d953b4db', 'وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ لَوْلَآ أَن تُفَنِّدُونِ', 'd7516313cd6ffe3fb9c9078bd569d35b777a3aa626b1a4f4bbd699e4d953b4db', 'd7516313cd6ffe3fb9c9078bd569d35b777a3aa626b1a4f4bbd699e4d953b4db', NULL, 'ولما فصلت العير قال ابوهم اني لاجد ريح يوسف لولا ان تفندون', 13, 25, 98, 1, 3, 246, false, NULL),
    (1691, 'tanzil-uthmani-v1.1', 12, 95, 'قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَٰلِكَ ٱلْقَدِيمِ', '0ce66b5844857013332a151ac38436b9b37d7a2ae73c0bd9e198e30683f72c57', 'قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَٰلِكَ ٱلْقَدِيمِ', '0ce66b5844857013332a151ac38436b9b37d7a2ae73c0bd9e198e30683f72c57', '0ce66b5844857013332a151ac38436b9b37d7a2ae73c0bd9e198e30683f72c57', NULL, 'قالوا تالله انك لفي ضللك القديم', 13, 25, 98, 1, 3, 246, false, NULL),
    (1692, 'tanzil-uthmani-v1.1', 12, 96, 'فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًا قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', '3e2a782ea0bdf7d8c89487a5c0d2d2e21271f7c3e88def758a7ede45f4a0e1b3', 'فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًا قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', '3e2a782ea0bdf7d8c89487a5c0d2d2e21271f7c3e88def758a7ede45f4a0e1b3', '3e2a782ea0bdf7d8c89487a5c0d2d2e21271f7c3e88def758a7ede45f4a0e1b3', NULL, 'فلما ان جاء البشير القيه علي وجهه فارتد بصيرا قال الم اقل لكم اني اعلم من الله ما لا تعلمون', 13, 25, 98, 1, 3, 247, false, NULL),
    (1693, 'tanzil-uthmani-v1.1', 12, 97, 'قَالُوا۟ يَٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ', '4cc6e3bb64e5367f604551b4525b70aff9af034ee450fc5133f8776020582830', 'قَالُوا۟ يَٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ', '4cc6e3bb64e5367f604551b4525b70aff9af034ee450fc5133f8776020582830', '4cc6e3bb64e5367f604551b4525b70aff9af034ee450fc5133f8776020582830', NULL, 'قالوا يابانا استغفر لنا ذنوبنا انا كنا خطين', 13, 25, 98, 1, 3, 247, false, NULL),
    (1694, 'tanzil-uthmani-v1.1', 12, 98, 'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '178422208bf47531f07b93a4d32d8c5d3f1db2c7fe9759c6d7b4bb533552ae80', 'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '178422208bf47531f07b93a4d32d8c5d3f1db2c7fe9759c6d7b4bb533552ae80', '178422208bf47531f07b93a4d32d8c5d3f1db2c7fe9759c6d7b4bb533552ae80', NULL, 'قال سوف استغفر لكم ربي انه هو الغفور الرحيم', 13, 25, 98, 1, 3, 247, false, NULL),
    (1695, 'tanzil-uthmani-v1.1', 12, 99, 'فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ', '3c1d25465c102e6df107091c941fc50a6ad3579aa606894dcb04fa30ec013dc5', 'فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ', '3c1d25465c102e6df107091c941fc50a6ad3579aa606894dcb04fa30ec013dc5', '3c1d25465c102e6df107091c941fc50a6ad3579aa606894dcb04fa30ec013dc5', NULL, 'فلما دخلوا علي يوسف ءاوي اليه ابويه وقال ادخلوا مصر ان شاء الله ءامنين', 13, 25, 98, 1, 3, 247, false, NULL),
    (1696, 'tanzil-uthmani-v1.1', 12, 100, 'وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًا وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأْوِيلُ رُءْيَٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّا وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ إِنَّ رَبِّى لَطِيفٌ لِّمَا يَشَآءُ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '5124c00bfa68e76140d493c606bac8f2561e03be200d54a2fbc0273f1896d263', 'وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًا وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأْوِيلُ رُءْيَٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّا وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ إِنَّ رَبِّى لَطِيفٌ لِّمَا يَشَآءُ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '5124c00bfa68e76140d493c606bac8f2561e03be200d54a2fbc0273f1896d263', '5124c00bfa68e76140d493c606bac8f2561e03be200d54a2fbc0273f1896d263', NULL, 'ورفع ابويه علي العرش وخروا له سجدا وقال يابت هذا تاويل رءيي من قبل قد جعلها ربي حقا وقد احسن بي اذ اخرجني من السجن وجاء بكم من البدو من بعد ان نزغ الشيطن بيني وبين اخوتي ان ربي لطيف لما يشاء انه هو العليم الحكيم', 13, 25, 98, 1, 3, 247, false, NULL),
    (1697, 'tanzil-uthmani-v1.1', 12, 101, 'رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ تَوَفَّنِى مُسْلِمًا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ', '8c85a07c2c96d3464cf0225c8e6b93703603f753ced470b4f821d5ccbe38af71', 'رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ تَوَفَّنِى مُسْلِمًا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ', '8c85a07c2c96d3464cf0225c8e6b93703603f753ced470b4f821d5ccbe38af71', '8c85a07c2c96d3464cf0225c8e6b93703603f753ced470b4f821d5ccbe38af71', NULL, 'رب قد ءاتيتني من الملك وعلمتني من تاويل الاحاديث فاطر السموت والارض انت ولي في الدنيا والاخره توفني مسلما والحقني بالصلحين', 13, 25, 99, 1, 3, 247, false, NULL),
    (1698, 'tanzil-uthmani-v1.1', 12, 102, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ', 'b4eefdf14f31407faf82f20f1d5a073186d4c1741ef92b028f97e587f2e6115a', 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ', 'b4eefdf14f31407faf82f20f1d5a073186d4c1741ef92b028f97e587f2e6115a', 'b4eefdf14f31407faf82f20f1d5a073186d4c1741ef92b028f97e587f2e6115a', NULL, 'ذلك من انباء الغيب نوحيه اليك وما كنت لديهم اذ اجمعوا امرهم وهم يمكرون', 13, 25, 99, 1, 3, 247, false, NULL),
    (1699, 'tanzil-uthmani-v1.1', 12, 103, 'وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ', '48ea210f6aec441fd5957fc6f52cfd2d3c2cbbd9af0b211dcbac1eb8526f44a4', 'وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ', '48ea210f6aec441fd5957fc6f52cfd2d3c2cbbd9af0b211dcbac1eb8526f44a4', '48ea210f6aec441fd5957fc6f52cfd2d3c2cbbd9af0b211dcbac1eb8526f44a4', NULL, 'وما اكثر الناس ولو حرصت بمؤمنين', 13, 25, 99, 1, 3, 247, false, NULL),
    (1700, 'tanzil-uthmani-v1.1', 12, 104, 'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', '3430a376d187095f9edfaff295bd888ca820a1e5b36654b54cf472ac213d6b4d', 'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', '3430a376d187095f9edfaff295bd888ca820a1e5b36654b54cf472ac213d6b4d', '3430a376d187095f9edfaff295bd888ca820a1e5b36654b54cf472ac213d6b4d', NULL, 'وما تسلهم عليه من اجر ان هو الا ذكر للعلمين', 13, 25, 99, 1, 3, 248, false, NULL),
    (1701, 'tanzil-uthmani-v1.1', 12, 105, 'وَكَأَيِّن مِّنْ ءَايَةٍ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ', 'd8056c2bc029a683eb754c5a4a4f62daa975d810bb887b5b5c13238f921c4991', 'وَكَأَيِّن مِّنْ ءَايَةٍ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ', 'd8056c2bc029a683eb754c5a4a4f62daa975d810bb887b5b5c13238f921c4991', 'd8056c2bc029a683eb754c5a4a4f62daa975d810bb887b5b5c13238f921c4991', NULL, 'وكاين من ءايه في السموت والارض يمرون عليها وهم عنها معرضون', 13, 25, 99, 1, 3, 248, false, NULL),
    (1702, 'tanzil-uthmani-v1.1', 12, 106, 'وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ', '5a4ae6dca8968a22bc79fed2e7e79a2edf3af71e5bc3a5532dc6de7877626b52', 'وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ', '5a4ae6dca8968a22bc79fed2e7e79a2edf3af71e5bc3a5532dc6de7877626b52', '5a4ae6dca8968a22bc79fed2e7e79a2edf3af71e5bc3a5532dc6de7877626b52', NULL, 'وما يؤمن اكثرهم بالله الا وهم مشركون', 13, 25, 99, 1, 3, 248, false, NULL),
    (1703, 'tanzil-uthmani-v1.1', 12, 107, 'أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَٰشِيَةٌ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'df2d23a6ea82302bc8ddffa2c4313be69e5f5477c43af1ee60b7e2cdc2c34e74', 'أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَٰشِيَةٌ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'df2d23a6ea82302bc8ddffa2c4313be69e5f5477c43af1ee60b7e2cdc2c34e74', 'df2d23a6ea82302bc8ddffa2c4313be69e5f5477c43af1ee60b7e2cdc2c34e74', NULL, 'افامنوا ان تاتيهم غشيه من عذاب الله او تاتيهم الساعه بغته وهم لا يشعرون', 13, 25, 99, 1, 3, 248, false, NULL),
    (1704, 'tanzil-uthmani-v1.1', 12, 108, 'قُلْ هَٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى وَسُبْحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', '6da5322894743bda4746762fac300e04ada08ddf80f84781cb0d49a5cb866fd5', 'قُلْ هَٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى وَسُبْحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', '6da5322894743bda4746762fac300e04ada08ddf80f84781cb0d49a5cb866fd5', '6da5322894743bda4746762fac300e04ada08ddf80f84781cb0d49a5cb866fd5', NULL, 'قل هذه سبيلي ادعوا الي الله علي بصيره انا ومن اتبعني وسبحن الله وما انا من المشركين', 13, 25, 99, 1, 3, 248, false, NULL),
    (1705, 'tanzil-uthmani-v1.1', 12, 109, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ٱتَّقَوْا۟ أَفَلَا تَعْقِلُونَ', 'e46ded09b0d91271ca1fe9ff218bed6e500002f55e8dec527cb28dfa295f29b9', 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ لِّلَّذِينَ ٱتَّقَوْا۟ أَفَلَا تَعْقِلُونَ', 'e46ded09b0d91271ca1fe9ff218bed6e500002f55e8dec527cb28dfa295f29b9', 'e46ded09b0d91271ca1fe9ff218bed6e500002f55e8dec527cb28dfa295f29b9', NULL, 'وما ارسلنا من قبلك الا رجالا نوحي اليهم من اهل القري افلم يسيروا في الارض فينظروا كيف كان عقبه الذين من قبلهم ولدار الاخره خير للذين اتقوا افلا تعقلون', 13, 25, 99, 1, 3, 248, false, NULL),
    (1706, 'tanzil-uthmani-v1.1', 12, 110, 'حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', '3c6368271d4bfe43ac1812643a1737ab5bcf4a6769b9aff08b0e0b192b570be4', 'حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', '3c6368271d4bfe43ac1812643a1737ab5bcf4a6769b9aff08b0e0b192b570be4', '3c6368271d4bfe43ac1812643a1737ab5bcf4a6769b9aff08b0e0b192b570be4', NULL, 'حتي اذا استيس الرسل وظنوا انهم قد كذبوا جاءهم نصرنا فنجي من نشاء ولا يرد باسنا عن القوم المجرمين', 13, 25, 99, 1, 3, 248, false, NULL),
    (1707, 'tanzil-uthmani-v1.1', 12, 111, 'لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌ لِّأُو۟لِى ٱلْأَلْبَٰبِ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', 'ccab832d9fc0e0f0dbe7cfb8d966bb04d03186acf93a9106c81a5a15740e2d3d', 'لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌ لِّأُو۟لِى ٱلْأَلْبَٰبِ مَا كَانَ حَدِيثًا يُفْتَرَىٰ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', 'ccab832d9fc0e0f0dbe7cfb8d966bb04d03186acf93a9106c81a5a15740e2d3d', 'ccab832d9fc0e0f0dbe7cfb8d966bb04d03186acf93a9106c81a5a15740e2d3d', NULL, 'لقد كان في قصصهم عبره لاولي الالبب ما كان حديثا يفتري ولكن تصديق الذي بين يديه وتفصيل كل شيء وهدي ورحمه لقوم يؤمنون', 13, 25, 99, 1, 3, 248, false, NULL),
    (1708, 'tanzil-uthmani-v1.1', 13, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ وَٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', '17c52bec6b40c1066e1082eed840ff4c4b3767aef5efbb0c284590e336d18042', 'الٓمٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ وَٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'b2bd98a875f19b12adb4948d4f19d2696487e8193af4899bb2c2f4e14cf405c1', 'b2bd98a875f19b12adb4948d4f19d2696487e8193af4899bb2c2f4e14cf405c1', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'المر تلك ءايت الكتب والذي انزل اليك من ربك الحق ولكن اكثر الناس لا يؤمنون', 13, 25, 99, 1, 3, 249, false, NULL),
    (1709, 'tanzil-uthmani-v1.1', 13, 2, 'ٱللَّهُ ٱلَّذِى رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى يُدَبِّرُ ٱلْأَمْرَ يُفَصِّلُ ٱلْـَٔايَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمْ تُوقِنُونَ', 'a5b34d2ce2ac0c773957da23bfee41e87d90b9189cbf398296edbc2375a40717', 'ٱللَّهُ ٱلَّذِى رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى يُدَبِّرُ ٱلْأَمْرَ يُفَصِّلُ ٱلْـَٔايَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمْ تُوقِنُونَ', 'a5b34d2ce2ac0c773957da23bfee41e87d90b9189cbf398296edbc2375a40717', 'a5b34d2ce2ac0c773957da23bfee41e87d90b9189cbf398296edbc2375a40717', NULL, 'الله الذي رفع السموت بغير عمد ترونها ثم استوي علي العرش وسخر الشمس والقمر كل يجري لاجل مسمي يدبر الامر يفصل الايت لعلكم بلقاء ربكم توقنون', 13, 25, 99, 1, 3, 249, false, NULL),
    (1710, 'tanzil-uthmani-v1.1', 13, 3, 'وَهُوَ ٱلَّذِى مَدَّ ٱلْأَرْضَ وَجَعَلَ فِيهَا رَوَٰسِىَ وَأَنْهَٰرًا وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ ٱثْنَيْنِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', '92651ea33176daba16deb009567adc53e03722f33a165f382f87237a240ba93b', 'وَهُوَ ٱلَّذِى مَدَّ ٱلْأَرْضَ وَجَعَلَ فِيهَا رَوَٰسِىَ وَأَنْهَٰرًا وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ ٱثْنَيْنِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', '92651ea33176daba16deb009567adc53e03722f33a165f382f87237a240ba93b', '92651ea33176daba16deb009567adc53e03722f33a165f382f87237a240ba93b', NULL, 'وهو الذي مد الارض وجعل فيها روسي وانهرا ومن كل الثمرت جعل فيها زوجين اثنين يغشي اليل النهار ان في ذلك لايت لقوم يتفكرون', 13, 25, 99, 1, 3, 249, false, NULL),
    (1711, 'tanzil-uthmani-v1.1', 13, 4, 'وَفِى ٱلْأَرْضِ قِطَعٌ مُّتَجَٰوِرَٰتٌ وَجَنَّٰتٌ مِّنْ أَعْنَٰبٍ وَزَرْعٌ وَنَخِيلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ يُسْقَىٰ بِمَآءٍ وَٰحِدٍ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍ فِى ٱلْأُكُلِ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'dbf9c71ed7b92055f002ce4bd143b1f1689671b9cb5b570f6ce98bffe709ece8', 'وَفِى ٱلْأَرْضِ قِطَعٌ مُّتَجَٰوِرَٰتٌ وَجَنَّٰتٌ مِّنْ أَعْنَٰبٍ وَزَرْعٌ وَنَخِيلٌ صِنْوَانٌ وَغَيْرُ صِنْوَانٍ يُسْقَىٰ بِمَآءٍ وَٰحِدٍ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍ فِى ٱلْأُكُلِ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'dbf9c71ed7b92055f002ce4bd143b1f1689671b9cb5b570f6ce98bffe709ece8', 'dbf9c71ed7b92055f002ce4bd143b1f1689671b9cb5b570f6ce98bffe709ece8', NULL, 'وفي الارض قطع متجورت وجنت من اعنب وزرع ونخيل صنوان وغير صنوان يسقي بماء وحد ونفضل بعضها علي بعض في الاكل ان في ذلك لايت لقوم يعقلون', 13, 25, 99, 1, 3, 249, false, NULL),
    (1712, 'tanzil-uthmani-v1.1', 13, 5, 'وَإِن تَعْجَبْ فَعَجَبٌ قَوْلُهُمْ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِى خَلْقٍ جَدِيدٍ أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ وَأُو۟لَٰٓئِكَ ٱلْأَغْلَٰلُ فِىٓ أَعْنَاقِهِمْ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '21d21ae13d53f0e6425f9ee0754f4a5c13ddf768f0a323c6f39e57e4017875d8', 'وَإِن تَعْجَبْ فَعَجَبٌ قَوْلُهُمْ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِى خَلْقٍ جَدِيدٍ أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ وَأُو۟لَٰٓئِكَ ٱلْأَغْلَٰلُ فِىٓ أَعْنَاقِهِمْ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '21d21ae13d53f0e6425f9ee0754f4a5c13ddf768f0a323c6f39e57e4017875d8', '21d21ae13d53f0e6425f9ee0754f4a5c13ddf768f0a323c6f39e57e4017875d8', NULL, 'وان تعجب فعجب قولهم اءذا كنا تربا اءنا لفي خلق جديد اولئك الذين كفروا بربهم واولئك الاغلل في اعناقهم واولئك اصحب النار هم فيها خلدون', 13, 25, 100, 1, 3, 249, false, NULL),
    (1713, 'tanzil-uthmani-v1.1', 13, 6, 'وَيَسْتَعْجِلُونَكَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ ٱلْمَثُلَٰتُ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلْعِقَابِ', '1977e2d1e715255289e49a62d71d7b8d1f4fe0e58bb509fc303a0bc830b2fca1', 'وَيَسْتَعْجِلُونَكَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ ٱلْمَثُلَٰتُ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلْعِقَابِ', '1977e2d1e715255289e49a62d71d7b8d1f4fe0e58bb509fc303a0bc830b2fca1', '1977e2d1e715255289e49a62d71d7b8d1f4fe0e58bb509fc303a0bc830b2fca1', NULL, 'ويستعجلونك بالسيئه قبل الحسنه وقد خلت من قبلهم المثلت وان ربك لذو مغفره للناس علي ظلمهم وان ربك لشديد العقاب', 13, 25, 100, 1, 3, 250, false, NULL),
    (1714, 'tanzil-uthmani-v1.1', 13, 7, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦٓ إِنَّمَآ أَنتَ مُنذِرٌ وَلِكُلِّ قَوْمٍ هَادٍ', '462516ccc079f27b2bd815f6ebe00a0ffd733fc2dd73bd646dd6428a282e5b90', 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦٓ إِنَّمَآ أَنتَ مُنذِرٌ وَلِكُلِّ قَوْمٍ هَادٍ', '462516ccc079f27b2bd815f6ebe00a0ffd733fc2dd73bd646dd6428a282e5b90', '462516ccc079f27b2bd815f6ebe00a0ffd733fc2dd73bd646dd6428a282e5b90', NULL, 'ويقول الذين كفروا لولا انزل عليه ءايه من ربه انما انت منذر ولكل قوم هاد', 13, 25, 100, 1, 3, 250, false, NULL),
    (1715, 'tanzil-uthmani-v1.1', 13, 8, 'ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلْأَرْحَامُ وَمَا تَزْدَادُ وَكُلُّ شَىْءٍ عِندَهُۥ بِمِقْدَارٍ', '632605e36f223c7e0df2dfd59e435b256699614e3decc0199fd2bbbccc62f0bf', 'ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلْأَرْحَامُ وَمَا تَزْدَادُ وَكُلُّ شَىْءٍ عِندَهُۥ بِمِقْدَارٍ', '632605e36f223c7e0df2dfd59e435b256699614e3decc0199fd2bbbccc62f0bf', '632605e36f223c7e0df2dfd59e435b256699614e3decc0199fd2bbbccc62f0bf', NULL, 'الله يعلم ما تحمل كل انثي وما تغيض الارحام وما تزداد وكل شيء عنده بمقدار', 13, 25, 100, 1, 3, 250, false, NULL),
    (1716, 'tanzil-uthmani-v1.1', 13, 9, 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْكَبِيرُ ٱلْمُتَعَالِ', '22bef97a695b812797b32c867442cbbca148c5dd4989f55fbad5f7bf2fd1ad2f', 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْكَبِيرُ ٱلْمُتَعَالِ', '22bef97a695b812797b32c867442cbbca148c5dd4989f55fbad5f7bf2fd1ad2f', '22bef97a695b812797b32c867442cbbca148c5dd4989f55fbad5f7bf2fd1ad2f', NULL, 'علم الغيب والشهده الكبير المتعال', 13, 25, 100, 1, 3, 250, false, NULL),
    (1717, 'tanzil-uthmani-v1.1', 13, 10, 'سَوَآءٌ مِّنكُم مَّنْ أَسَرَّ ٱلْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفٍۭ بِٱلَّيْلِ وَسَارِبٌۢ بِٱلنَّهَارِ', '78a1d0706c7e3dfdaeac697792329a5b336656a65b9c49aa5e1b2242871a780b', 'سَوَآءٌ مِّنكُم مَّنْ أَسَرَّ ٱلْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفٍۭ بِٱلَّيْلِ وَسَارِبٌۢ بِٱلنَّهَارِ', '78a1d0706c7e3dfdaeac697792329a5b336656a65b9c49aa5e1b2242871a780b', '78a1d0706c7e3dfdaeac697792329a5b336656a65b9c49aa5e1b2242871a780b', NULL, 'سواء منكم من اسر القول ومن جهر به ومن هو مستخف باليل وسارب بالنهار', 13, 25, 100, 1, 3, 250, false, NULL),
    (1718, 'tanzil-uthmani-v1.1', 13, 11, 'لَهُۥ مُعَقِّبَٰتٌ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍ سُوٓءًا فَلَا مَرَدَّ لَهُۥ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ', 'a50726a06f66509fea3b8764beb8861f0694b846a2dfd698849225529e6ed8e3', 'لَهُۥ مُعَقِّبَٰتٌ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍ سُوٓءًا فَلَا مَرَدَّ لَهُۥ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ', 'a50726a06f66509fea3b8764beb8861f0694b846a2dfd698849225529e6ed8e3', 'a50726a06f66509fea3b8764beb8861f0694b846a2dfd698849225529e6ed8e3', NULL, 'له معقبت من بين يديه ومن خلفه يحفظونه من امر الله ان الله لا يغير ما بقوم حتي يغيروا ما بانفسهم واذا اراد الله بقوم سوءا فلا مرد له وما لهم من دونه من وال', 13, 25, 100, 1, 3, 250, false, NULL),
    (1719, 'tanzil-uthmani-v1.1', 13, 12, 'هُوَ ٱلَّذِى يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ', '297f327cb99c4d31e6e9b9503b4500af4e960a5eafe1e4aa9201ec21e725ba2b', 'هُوَ ٱلَّذِى يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ', '297f327cb99c4d31e6e9b9503b4500af4e960a5eafe1e4aa9201ec21e725ba2b', '297f327cb99c4d31e6e9b9503b4500af4e960a5eafe1e4aa9201ec21e725ba2b', NULL, 'هو الذي يريكم البرق خوفا وطمعا وينشئ السحاب الثقال', 13, 25, 100, 1, 3, 250, false, NULL),
    (1720, 'tanzil-uthmani-v1.1', 13, 13, 'وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ', '33d0c5ae84b2d77e9cf00cb205a3d88e7cfe97f1ba6c2dbd7b9604053865a103', 'وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ', '33d0c5ae84b2d77e9cf00cb205a3d88e7cfe97f1ba6c2dbd7b9604053865a103', '33d0c5ae84b2d77e9cf00cb205a3d88e7cfe97f1ba6c2dbd7b9604053865a103', NULL, 'ويسبح الرعد بحمده والملئكه من خيفته ويرسل الصوعق فيصيب بها من يشاء وهم يجدلون في الله وهو شديد المحال', 13, 25, 100, 1, 3, 250, false, NULL),
    (1721, 'tanzil-uthmani-v1.1', 13, 14, 'لَهُۥ دَعْوَةُ ٱلْحَقِّ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَىْءٍ إِلَّا كَبَٰسِطِ كَفَّيْهِ إِلَى ٱلْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦ وَمَا دُعَآءُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'f76e9483b3b9e1b760179c35a5ba94814605e1e0925020fa3629cf0aa5cb73e3', 'لَهُۥ دَعْوَةُ ٱلْحَقِّ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَىْءٍ إِلَّا كَبَٰسِطِ كَفَّيْهِ إِلَى ٱلْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦ وَمَا دُعَآءُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'f76e9483b3b9e1b760179c35a5ba94814605e1e0925020fa3629cf0aa5cb73e3', 'f76e9483b3b9e1b760179c35a5ba94814605e1e0925020fa3629cf0aa5cb73e3', NULL, 'له دعوه الحق والذين يدعون من دونه لا يستجيبون لهم بشيء الا كبسط كفيه الي الماء ليبلغ فاه وما هو ببلغه وما دعاء الكفرين الا في ضلل', 13, 25, 100, 1, 3, 251, false, NULL),
    (1722, 'tanzil-uthmani-v1.1', 13, 15, 'وَلِلَّهِ يَسْجُدُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَظِلَٰلُهُم بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ', '8309815c6b7ded4d1858f6b04f2b534aec439ff21c4944b7c76409b9e3a83b30', 'وَلِلَّهِ يَسْجُدُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًا وَكَرْهًا وَظِلَٰلُهُم بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ', '8309815c6b7ded4d1858f6b04f2b534aec439ff21c4944b7c76409b9e3a83b30', '8309815c6b7ded4d1858f6b04f2b534aec439ff21c4944b7c76409b9e3a83b30', NULL, 'ولله يسجد من في السموت والارض طوعا وكرها وظللهم بالغدو والاصال', 13, 25, 100, 1, 3, 251, true, 'recommended'),
    (1723, 'tanzil-uthmani-v1.1', 13, 16, 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ قُلْ أَفَٱتَّخَذْتُم مِّن دُونِهِۦٓ أَوْلِيَآءَ لَا يَمْلِكُونَ لِأَنفُسِهِمْ نَفْعًا وَلَا ضَرًّا قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَمْ هَلْ تَسْتَوِى ٱلظُّلُمَٰتُ وَٱلنُّورُ أَمْ جَعَلُوا۟ لِلَّهِ شُرَكَآءَ خَلَقُوا۟ كَخَلْقِهِۦ فَتَشَٰبَهَ ٱلْخَلْقُ عَلَيْهِمْ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍ وَهُوَ ٱلْوَٰحِدُ ٱلْقَهَّٰرُ', 'aafce9c1ed33d228f4a0f91505ade0633ed6826ea994d32ed7768dd1ca3c4d6e', 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ قُلْ أَفَٱتَّخَذْتُم مِّن دُونِهِۦٓ أَوْلِيَآءَ لَا يَمْلِكُونَ لِأَنفُسِهِمْ نَفْعًا وَلَا ضَرًّا قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَمْ هَلْ تَسْتَوِى ٱلظُّلُمَٰتُ وَٱلنُّورُ أَمْ جَعَلُوا۟ لِلَّهِ شُرَكَآءَ خَلَقُوا۟ كَخَلْقِهِۦ فَتَشَٰبَهَ ٱلْخَلْقُ عَلَيْهِمْ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍ وَهُوَ ٱلْوَٰحِدُ ٱلْقَهَّٰرُ', 'aafce9c1ed33d228f4a0f91505ade0633ed6826ea994d32ed7768dd1ca3c4d6e', 'aafce9c1ed33d228f4a0f91505ade0633ed6826ea994d32ed7768dd1ca3c4d6e', NULL, 'قل من رب السموت والارض قل الله قل افاتخذتم من دونه اولياء لا يملكون لانفسهم نفعا ولا ضرا قل هل يستوي الاعمي والبصير ام هل تستوي الظلمت والنور ام جعلوا لله شركاء خلقوا كخلقه فتشبه الخلق عليهم قل الله خلق كل شيء وهو الوحد القهر', 13, 25, 100, 1, 3, 251, false, NULL),
    (1724, 'tanzil-uthmani-v1.1', 13, 17, 'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَالَتْ أَوْدِيَةٌۢ بِقَدَرِهَا فَٱحْتَمَلَ ٱلسَّيْلُ زَبَدًا رَّابِيًا وَمِمَّا يُوقِدُونَ عَلَيْهِ فِى ٱلنَّارِ ٱبْتِغَآءَ حِلْيَةٍ أَوْ مَتَٰعٍ زَبَدٌ مِّثْلُهُۥ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْحَقَّ وَٱلْبَٰطِلَ فَأَمَّا ٱلزَّبَدُ فَيَذْهَبُ جُفَآءً وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمْكُثُ فِى ٱلْأَرْضِ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ', 'f7a10160bac444198b9dbb1f1a23265e51e7e3a9fb251aa94abc8160a6fba2b7', 'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَالَتْ أَوْدِيَةٌۢ بِقَدَرِهَا فَٱحْتَمَلَ ٱلسَّيْلُ زَبَدًا رَّابِيًا وَمِمَّا يُوقِدُونَ عَلَيْهِ فِى ٱلنَّارِ ٱبْتِغَآءَ حِلْيَةٍ أَوْ مَتَٰعٍ زَبَدٌ مِّثْلُهُۥ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْحَقَّ وَٱلْبَٰطِلَ فَأَمَّا ٱلزَّبَدُ فَيَذْهَبُ جُفَآءً وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمْكُثُ فِى ٱلْأَرْضِ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ', 'f7a10160bac444198b9dbb1f1a23265e51e7e3a9fb251aa94abc8160a6fba2b7', 'f7a10160bac444198b9dbb1f1a23265e51e7e3a9fb251aa94abc8160a6fba2b7', NULL, 'انزل من السماء ماء فسالت اوديه بقدرها فاحتمل السيل زبدا رابيا ومما يوقدون عليه في النار ابتغاء حليه او متع زبد مثله كذلك يضرب الله الحق والبطل فاما الزبد فيذهب جفاء واما ما ينفع الناس فيمكث في الارض كذلك يضرب الله الامثال', 13, 25, 100, 1, 3, 251, false, NULL),
    (1725, 'tanzil-uthmani-v1.1', 13, 18, 'لِلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمُ ٱلْحُسْنَىٰ وَٱلَّذِينَ لَمْ يَسْتَجِيبُوا۟ لَهُۥ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦٓ أُو۟لَٰٓئِكَ لَهُمْ سُوٓءُ ٱلْحِسَابِ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمِهَادُ', '11e44d2f0db1250912d302f50e0d2e9561822858ec5d1609220fef5a6295aa96', 'لِلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمُ ٱلْحُسْنَىٰ وَٱلَّذِينَ لَمْ يَسْتَجِيبُوا۟ لَهُۥ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦٓ أُو۟لَٰٓئِكَ لَهُمْ سُوٓءُ ٱلْحِسَابِ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمِهَادُ', '11e44d2f0db1250912d302f50e0d2e9561822858ec5d1609220fef5a6295aa96', '11e44d2f0db1250912d302f50e0d2e9561822858ec5d1609220fef5a6295aa96', NULL, 'للذين استجابوا لربهم الحسني والذين لم يستجيبوا له لو ان لهم ما في الارض جميعا ومثله معه لافتدوا به اولئك لهم سوء الحساب وماويهم جهنم وبئس المهاد', 13, 25, 100, 1, 3, 251, false, NULL),
    (1726, 'tanzil-uthmani-v1.1', 13, 19, 'أَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ كَمَنْ هُوَ أَعْمَىٰٓ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '1895df4eddb096293deec08079608a6578323d3574851f0e171364974e074fc3', 'أَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ كَمَنْ هُوَ أَعْمَىٰٓ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '1895df4eddb096293deec08079608a6578323d3574851f0e171364974e074fc3', '1895df4eddb096293deec08079608a6578323d3574851f0e171364974e074fc3', NULL, 'افمن يعلم انما انزل اليك من ربك الحق كمن هو اعمي انما يتذكر اولوا الالبب', 13, 26, 101, 1, 3, 252, false, NULL),
    (1727, 'tanzil-uthmani-v1.1', 13, 20, 'ٱلَّذِينَ يُوفُونَ بِعَهْدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلْمِيثَٰقَ', '76912a5c6dd9d09f970e1abcab7175e652d5456c264e1549ca27a0be7f5867ed', 'ٱلَّذِينَ يُوفُونَ بِعَهْدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلْمِيثَٰقَ', '76912a5c6dd9d09f970e1abcab7175e652d5456c264e1549ca27a0be7f5867ed', '76912a5c6dd9d09f970e1abcab7175e652d5456c264e1549ca27a0be7f5867ed', NULL, 'الذين يوفون بعهد الله ولا ينقضون الميثق', 13, 26, 101, 1, 3, 252, false, NULL),
    (1728, 'tanzil-uthmani-v1.1', 13, 21, 'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوٓءَ ٱلْحِسَابِ', '16f4347d19137eef79f025526b57db0e2eaade5ff1461695fc0b5fe86b02a786', 'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوٓءَ ٱلْحِسَابِ', '16f4347d19137eef79f025526b57db0e2eaade5ff1461695fc0b5fe86b02a786', '16f4347d19137eef79f025526b57db0e2eaade5ff1461695fc0b5fe86b02a786', NULL, 'والذين يصلون ما امر الله به ان يوصل ويخشون ربهم ويخافون سوء الحساب', 13, 26, 101, 1, 3, 252, false, NULL),
    (1729, 'tanzil-uthmani-v1.1', 13, 22, 'وَٱلَّذِينَ صَبَرُوا۟ ٱبْتِغَآءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ أُو۟لَٰٓئِكَ لَهُمْ عُقْبَى ٱلدَّارِ', 'cedca722048be2ff7081afb5d086b5267eb0ca3b1ba0c3e2ee7905ec5f537d97', 'وَٱلَّذِينَ صَبَرُوا۟ ٱبْتِغَآءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ أُو۟لَٰٓئِكَ لَهُمْ عُقْبَى ٱلدَّارِ', 'cedca722048be2ff7081afb5d086b5267eb0ca3b1ba0c3e2ee7905ec5f537d97', 'cedca722048be2ff7081afb5d086b5267eb0ca3b1ba0c3e2ee7905ec5f537d97', NULL, 'والذين صبروا ابتغاء وجه ربهم واقاموا الصلوه وانفقوا مما رزقنهم سرا وعلانيه ويدرءون بالحسنه السيئه اولئك لهم عقبي الدار', 13, 26, 101, 1, 3, 252, false, NULL),
    (1730, 'tanzil-uthmani-v1.1', 13, 23, 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ وَٱلْمَلَٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍ', 'c43b9c330af8c8989ebf48a391f4a38c20f725481ef2991d140e996bcefc793f', 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ وَٱلْمَلَٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍ', 'c43b9c330af8c8989ebf48a391f4a38c20f725481ef2991d140e996bcefc793f', 'c43b9c330af8c8989ebf48a391f4a38c20f725481ef2991d140e996bcefc793f', NULL, 'جنت عدن يدخلونها ومن صلح من ءابائهم وازوجهم وذريتهم والملئكه يدخلون عليهم من كل باب', 13, 26, 101, 1, 3, 252, false, NULL),
    (1731, 'tanzil-uthmani-v1.1', 13, 24, 'سَلَٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى ٱلدَّارِ', '0879058b1148a0137f73ea05250ca16a0a0394a38426fb42e9e360d468ed9f7c', 'سَلَٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى ٱلدَّارِ', '0879058b1148a0137f73ea05250ca16a0a0394a38426fb42e9e360d468ed9f7c', '0879058b1148a0137f73ea05250ca16a0a0394a38426fb42e9e360d468ed9f7c', NULL, 'سلم عليكم بما صبرتم فنعم عقبي الدار', 13, 26, 101, 1, 3, 252, false, NULL),
    (1732, 'tanzil-uthmani-v1.1', 13, 25, 'وَٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ أُو۟لَٰٓئِكَ لَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', '4f428a4e647b641962cbe89104207dab34d6e99623c9745976ecd4fcdaf1778f', 'وَٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ أُو۟لَٰٓئِكَ لَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', '4f428a4e647b641962cbe89104207dab34d6e99623c9745976ecd4fcdaf1778f', '4f428a4e647b641962cbe89104207dab34d6e99623c9745976ecd4fcdaf1778f', NULL, 'والذين ينقضون عهد الله من بعد ميثقه ويقطعون ما امر الله به ان يوصل ويفسدون في الارض اولئك لهم اللعنه ولهم سوء الدار', 13, 26, 101, 1, 3, 252, false, NULL),
    (1733, 'tanzil-uthmani-v1.1', 13, 26, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَفَرِحُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا مَتَٰعٌ', '916d064efb361e65cf7f0ff19bf01301107741ced089c4b42024148b6719adb2', 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَفَرِحُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا فِى ٱلْـَٔاخِرَةِ إِلَّا مَتَٰعٌ', '916d064efb361e65cf7f0ff19bf01301107741ced089c4b42024148b6719adb2', '916d064efb361e65cf7f0ff19bf01301107741ced089c4b42024148b6719adb2', NULL, 'الله يبسط الرزق لمن يشاء ويقدر وفرحوا بالحيوه الدنيا وما الحيوه الدنيا في الاخره الا متع', 13, 26, 101, 1, 3, 252, false, NULL),
    (1734, 'tanzil-uthmani-v1.1', 13, 27, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ قُلْ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَنْ أَنَابَ', '0aa4022f3d86ecf6cf14d839692b1a3280831089da1e23a5127f02a66819a038', 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ قُلْ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَنْ أَنَابَ', '0aa4022f3d86ecf6cf14d839692b1a3280831089da1e23a5127f02a66819a038', '0aa4022f3d86ecf6cf14d839692b1a3280831089da1e23a5127f02a66819a038', NULL, 'ويقول الذين كفروا لولا انزل عليه ءايه من ربه قل ان الله يضل من يشاء ويهدي اليه من اناب', 13, 26, 101, 1, 3, 252, false, NULL),
    (1735, 'tanzil-uthmani-v1.1', 13, 28, 'ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ', '5e9ab559567ed8be17de1d60f1030dbea169edc7f833ab6e9c8add559f47d35e', 'ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ', '5e9ab559567ed8be17de1d60f1030dbea169edc7f833ab6e9c8add559f47d35e', '5e9ab559567ed8be17de1d60f1030dbea169edc7f833ab6e9c8add559f47d35e', NULL, 'الذين ءامنوا وتطمئن قلوبهم بذكر الله الا بذكر الله تطمئن القلوب', 13, 26, 101, 1, 3, 252, false, NULL),
    (1736, 'tanzil-uthmani-v1.1', 13, 29, 'ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَـَٔابٍ', '11d1ed6dcc2f1e2aeaaf47f0aff90c743f464ebcfb1c65e09e19f40226980aaa', 'ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَـَٔابٍ', '11d1ed6dcc2f1e2aeaaf47f0aff90c743f464ebcfb1c65e09e19f40226980aaa', '11d1ed6dcc2f1e2aeaaf47f0aff90c743f464ebcfb1c65e09e19f40226980aaa', NULL, 'الذين ءامنوا وعملوا الصلحت طوبي لهم وحسن ماب', 13, 26, 101, 1, 3, 253, false, NULL),
    (1737, 'tanzil-uthmani-v1.1', 13, 30, 'كَذَٰلِكَ أَرْسَلْنَٰكَ فِىٓ أُمَّةٍ قَدْ خَلَتْ مِن قَبْلِهَآ أُمَمٌ لِّتَتْلُوَا۟ عَلَيْهِمُ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَهُمْ يَكْفُرُونَ بِٱلرَّحْمَٰنِ قُلْ هُوَ رَبِّى لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ', '91c4020d5b550e7612c926703654f1d19e5fa506ee04c19816698e0efb4e39a4', 'كَذَٰلِكَ أَرْسَلْنَٰكَ فِىٓ أُمَّةٍ قَدْ خَلَتْ مِن قَبْلِهَآ أُمَمٌ لِّتَتْلُوَا۟ عَلَيْهِمُ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَهُمْ يَكْفُرُونَ بِٱلرَّحْمَٰنِ قُلْ هُوَ رَبِّى لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ', '91c4020d5b550e7612c926703654f1d19e5fa506ee04c19816698e0efb4e39a4', '91c4020d5b550e7612c926703654f1d19e5fa506ee04c19816698e0efb4e39a4', NULL, 'كذلك ارسلنك في امه قد خلت من قبلها امم لتتلوا عليهم الذي اوحينا اليك وهم يكفرون بالرحمن قل هو ربي لا اله الا هو عليه توكلت واليه متاب', 13, 26, 101, 1, 3, 253, false, NULL),
    (1738, 'tanzil-uthmani-v1.1', 13, 31, 'وَلَوْ أَنَّ قُرْءَانًا سُيِّرَتْ بِهِ ٱلْجِبَالُ أَوْ قُطِّعَتْ بِهِ ٱلْأَرْضُ أَوْ كُلِّمَ بِهِ ٱلْمَوْتَىٰ بَل لِّلَّهِ ٱلْأَمْرُ جَمِيعًا أَفَلَمْ يَا۟يْـَٔسِ ٱلَّذِينَ ءَامَنُوٓا۟ أَن لَّوْ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعًا وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ تُصِيبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًا مِّن دَارِهِمْ حَتَّىٰ يَأْتِىَ وَعْدُ ٱللَّهِ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', '1c6a3295df6ad00ff72ed6279658271e65a0a7e8205603e1174bfe5ab96979ee', 'وَلَوْ أَنَّ قُرْءَانًا سُيِّرَتْ بِهِ ٱلْجِبَالُ أَوْ قُطِّعَتْ بِهِ ٱلْأَرْضُ أَوْ كُلِّمَ بِهِ ٱلْمَوْتَىٰ بَل لِّلَّهِ ٱلْأَمْرُ جَمِيعًا أَفَلَمْ يَا۟يْـَٔسِ ٱلَّذِينَ ءَامَنُوٓا۟ أَن لَّوْ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعًا وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ تُصِيبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًا مِّن دَارِهِمْ حَتَّىٰ يَأْتِىَ وَعْدُ ٱللَّهِ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', '1c6a3295df6ad00ff72ed6279658271e65a0a7e8205603e1174bfe5ab96979ee', '1c6a3295df6ad00ff72ed6279658271e65a0a7e8205603e1174bfe5ab96979ee', NULL, 'ولو ان قرءانا سيرت به الجبال او قطعت به الارض او كلم به الموتي بل لله الامر جميعا افلم يايس الذين ءامنوا ان لو يشاء الله لهدي الناس جميعا ولا يزال الذين كفروا تصيبهم بما صنعوا قارعه او تحل قريبا من دارهم حتي ياتي وعد الله ان الله لا يخلف الميعاد', 13, 26, 101, 1, 3, 253, false, NULL),
    (1739, 'tanzil-uthmani-v1.1', 13, 32, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا۟ ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ', 'daf9532b5eba37ed30bc31db5039a1a4102cc93dde7678e9c5501ce67e1114ed', 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا۟ ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ', 'daf9532b5eba37ed30bc31db5039a1a4102cc93dde7678e9c5501ce67e1114ed', 'daf9532b5eba37ed30bc31db5039a1a4102cc93dde7678e9c5501ce67e1114ed', NULL, 'ولقد استهزئ برسل من قبلك فامليت للذين كفروا ثم اخذتهم فكيف كان عقاب', 13, 26, 101, 1, 3, 253, false, NULL),
    (1740, 'tanzil-uthmani-v1.1', 13, 33, 'أَفَمَنْ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفْسٍۭ بِمَا كَسَبَتْ وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ قُلْ سَمُّوهُمْ أَمْ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعْلَمُ فِى ٱلْأَرْضِ أَم بِظَٰهِرٍ مِّنَ ٱلْقَوْلِ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا۟ مَكْرُهُمْ وَصُدُّوا۟ عَنِ ٱلسَّبِيلِ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '6680e16fa9c173a462b304b9eaa8047ae3b02e34206b8efbfecfe42da96769f1', 'أَفَمَنْ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفْسٍۭ بِمَا كَسَبَتْ وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ قُلْ سَمُّوهُمْ أَمْ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعْلَمُ فِى ٱلْأَرْضِ أَم بِظَٰهِرٍ مِّنَ ٱلْقَوْلِ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا۟ مَكْرُهُمْ وَصُدُّوا۟ عَنِ ٱلسَّبِيلِ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '6680e16fa9c173a462b304b9eaa8047ae3b02e34206b8efbfecfe42da96769f1', '6680e16fa9c173a462b304b9eaa8047ae3b02e34206b8efbfecfe42da96769f1', NULL, 'افمن هو قائم علي كل نفس بما كسبت وجعلوا لله شركاء قل سموهم ام تنبونه بما لا يعلم في الارض ام بظهر من القول بل زين للذين كفروا مكرهم وصدوا عن السبيل ومن يضلل الله فما له من هاد', 13, 26, 101, 1, 3, 253, false, NULL),
    (1741, 'tanzil-uthmani-v1.1', 13, 34, 'لَّهُمْ عَذَابٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَقُّ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', '566725731e667025b6bb0735136547fb6db5f8bf1cf3e64815326de9334968e5', 'لَّهُمْ عَذَابٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَقُّ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', '566725731e667025b6bb0735136547fb6db5f8bf1cf3e64815326de9334968e5', '566725731e667025b6bb0735136547fb6db5f8bf1cf3e64815326de9334968e5', NULL, 'لهم عذاب في الحيوه الدنيا ولعذاب الاخره اشق وما لهم من الله من واق', 13, 26, 101, 1, 3, 253, false, NULL),
    (1742, 'tanzil-uthmani-v1.1', 13, 35, 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ أُكُلُهَا دَآئِمٌ وَظِلُّهَا تِلْكَ عُقْبَى ٱلَّذِينَ ٱتَّقَوا۟ وَّعُقْبَى ٱلْكَٰفِرِينَ ٱلنَّارُ', '047f04a4c712939271294ad4c84de2095211304db38d8ebb26eff896a1bb75df', 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ أُكُلُهَا دَآئِمٌ وَظِلُّهَا تِلْكَ عُقْبَى ٱلَّذِينَ ٱتَّقَوا۟ وَّعُقْبَى ٱلْكَٰفِرِينَ ٱلنَّارُ', '047f04a4c712939271294ad4c84de2095211304db38d8ebb26eff896a1bb75df', '047f04a4c712939271294ad4c84de2095211304db38d8ebb26eff896a1bb75df', NULL, 'مثل الجنه التي وعد المتقون تجري من تحتها الانهر اكلها دائم وظلها تلك عقبي الذين اتقوا وعقبي الكفرين النار', 13, 26, 102, 1, 3, 254, false, NULL),
    (1743, 'tanzil-uthmani-v1.1', 13, 36, 'وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَفْرَحُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمِنَ ٱلْأَحْزَابِ مَن يُنكِرُ بَعْضَهُۥ قُلْ إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ وَلَآ أُشْرِكَ بِهِۦٓ إِلَيْهِ أَدْعُوا۟ وَإِلَيْهِ مَـَٔابِ', '2ce66e558b73a7768a538e22c1e3bc343e05dbce81bb99bcf62aa86cfd068bec', 'وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَفْرَحُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمِنَ ٱلْأَحْزَابِ مَن يُنكِرُ بَعْضَهُۥ قُلْ إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ وَلَآ أُشْرِكَ بِهِۦٓ إِلَيْهِ أَدْعُوا۟ وَإِلَيْهِ مَـَٔابِ', '2ce66e558b73a7768a538e22c1e3bc343e05dbce81bb99bcf62aa86cfd068bec', '2ce66e558b73a7768a538e22c1e3bc343e05dbce81bb99bcf62aa86cfd068bec', NULL, 'والذين ءاتينهم الكتب يفرحون بما انزل اليك ومن الاحزاب من ينكر بعضه قل انما امرت ان اعبد الله ولا اشرك به اليه ادعوا واليه ماب', 13, 26, 102, 1, 3, 254, false, NULL),
    (1744, 'tanzil-uthmani-v1.1', 13, 37, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ حُكْمًا عَرَبِيًّا وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ مَا جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا وَاقٍ', '2053d85f35f7f94fbf43cba029f9c2f8524f5860e490c32d44c08bbd92d0f78f', 'وَكَذَٰلِكَ أَنزَلْنَٰهُ حُكْمًا عَرَبِيًّا وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ مَا جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا وَاقٍ', '2053d85f35f7f94fbf43cba029f9c2f8524f5860e490c32d44c08bbd92d0f78f', '2053d85f35f7f94fbf43cba029f9c2f8524f5860e490c32d44c08bbd92d0f78f', NULL, 'وكذلك انزلنه حكما عربيا ولئن اتبعت اهواءهم بعد ما جاءك من العلم ما لك من الله من ولي ولا واق', 13, 26, 102, 1, 3, 254, false, NULL),
    (1745, 'tanzil-uthmani-v1.1', 13, 38, 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَٰجًا وَذُرِّيَّةً وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ لِكُلِّ أَجَلٍ كِتَابٌ', '83a3747eab40c5c4be16607270fe0e4890e307aec198461bcaf3935d1fbfa709', 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَٰجًا وَذُرِّيَّةً وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ لِكُلِّ أَجَلٍ كِتَابٌ', '83a3747eab40c5c4be16607270fe0e4890e307aec198461bcaf3935d1fbfa709', '83a3747eab40c5c4be16607270fe0e4890e307aec198461bcaf3935d1fbfa709', NULL, 'ولقد ارسلنا رسلا من قبلك وجعلنا لهم ازوجا وذريه وما كان لرسول ان ياتي بايه الا باذن الله لكل اجل كتاب', 13, 26, 102, 1, 3, 254, false, NULL),
    (1746, 'tanzil-uthmani-v1.1', 13, 39, 'يَمْحُوا۟ ٱللَّهُ مَا يَشَآءُ وَيُثْبِتُ وَعِندَهُۥٓ أُمُّ ٱلْكِتَٰبِ', '369223fe32876df916d008195953e1da392ef9b35925db0b8ae7ea5a3236bcb8', 'يَمْحُوا۟ ٱللَّهُ مَا يَشَآءُ وَيُثْبِتُ وَعِندَهُۥٓ أُمُّ ٱلْكِتَٰبِ', '369223fe32876df916d008195953e1da392ef9b35925db0b8ae7ea5a3236bcb8', '369223fe32876df916d008195953e1da392ef9b35925db0b8ae7ea5a3236bcb8', NULL, 'يمحوا الله ما يشاء ويثبت وعنده ام الكتب', 13, 26, 102, 1, 3, 254, false, NULL),
    (1747, 'tanzil-uthmani-v1.1', 13, 40, 'وَإِن مَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ وَعَلَيْنَا ٱلْحِسَابُ', 'cedeea8e1688f2bcd4e6a4ccee5aeb151b8ffc69d38c3f0948014f1d281f5f65', 'وَإِن مَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ وَعَلَيْنَا ٱلْحِسَابُ', 'cedeea8e1688f2bcd4e6a4ccee5aeb151b8ffc69d38c3f0948014f1d281f5f65', 'cedeea8e1688f2bcd4e6a4ccee5aeb151b8ffc69d38c3f0948014f1d281f5f65', NULL, 'وان ما نرينك بعض الذي نعدهم او نتوفينك فانما عليك البلغ وعلينا الحساب', 13, 26, 102, 1, 3, 254, false, NULL),
    (1748, 'tanzil-uthmani-v1.1', 13, 41, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا وَٱللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ وَهُوَ سَرِيعُ ٱلْحِسَابِ', '342ab9bc9549165cf3f99305b856154694d83bd7d76c72a75d1e5ce64266682c', 'أَوَلَمْ يَرَوْا۟ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا وَٱللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ وَهُوَ سَرِيعُ ٱلْحِسَابِ', '342ab9bc9549165cf3f99305b856154694d83bd7d76c72a75d1e5ce64266682c', '342ab9bc9549165cf3f99305b856154694d83bd7d76c72a75d1e5ce64266682c', NULL, 'اولم يروا انا ناتي الارض ننقصها من اطرافها والله يحكم لا معقب لحكمه وهو سريع الحساب', 13, 26, 102, 1, 3, 254, false, NULL),
    (1749, 'tanzil-uthmani-v1.1', 13, 42, 'وَقَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ ٱلْمَكْرُ جَمِيعًا يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍ وَسَيَعْلَمُ ٱلْكُفَّٰرُ لِمَنْ عُقْبَى ٱلدَّارِ', '7c9d01c142143cac3fa8a22c89d363c0d59385a1bfdb47d235393f4c526f0c92', 'وَقَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ ٱلْمَكْرُ جَمِيعًا يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍ وَسَيَعْلَمُ ٱلْكُفَّٰرُ لِمَنْ عُقْبَى ٱلدَّارِ', '7c9d01c142143cac3fa8a22c89d363c0d59385a1bfdb47d235393f4c526f0c92', '7c9d01c142143cac3fa8a22c89d363c0d59385a1bfdb47d235393f4c526f0c92', NULL, 'وقد مكر الذين من قبلهم فلله المكر جميعا يعلم ما تكسب كل نفس وسيعلم الكفر لمن عقبي الدار', 13, 26, 102, 1, 3, 254, false, NULL),
    (1750, 'tanzil-uthmani-v1.1', 13, 43, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَسْتَ مُرْسَلًا قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ٱلْكِتَٰبِ', 'c48829f3da8787561c4439ab5272e105198e97f4375be4fd8b019ef1a2d44cc3', 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَسْتَ مُرْسَلًا قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ٱلْكِتَٰبِ', 'c48829f3da8787561c4439ab5272e105198e97f4375be4fd8b019ef1a2d44cc3', 'c48829f3da8787561c4439ab5272e105198e97f4375be4fd8b019ef1a2d44cc3', NULL, 'ويقول الذين كفروا لست مرسلا قل كفي بالله شهيدا بيني وبينكم ومن عنده علم الكتب', 13, 26, 102, 1, 3, 255, false, NULL),
    (1751, 'tanzil-uthmani-v1.1', 14, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ لِتُخْرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', '3b815aa8dc706c3e2d73d001ace1b513328c9df76c6719d4731147d12ee3e7bb', 'الٓر كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ لِتُخْرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'b4218e05088ed7c97cb125ca2d7ece6e5f527bf17fb134e8eec73a1b882e9a01', 'b4218e05088ed7c97cb125ca2d7ece6e5f527bf17fb134e8eec73a1b882e9a01', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الر كتب انزلنه اليك لتخرج الناس من الظلمت الي النور باذن ربهم الي صرط العزيز الحميد', 13, 26, 102, 1, 3, 255, false, NULL),
    (1752, 'tanzil-uthmani-v1.1', 14, 2, 'ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَوَيْلٌ لِّلْكَٰفِرِينَ مِنْ عَذَابٍ شَدِيدٍ', '774a8c437448fd104c24534dd4ce78c96c307ec50daa87cc3b2185602426bdc1', 'ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَوَيْلٌ لِّلْكَٰفِرِينَ مِنْ عَذَابٍ شَدِيدٍ', '774a8c437448fd104c24534dd4ce78c96c307ec50daa87cc3b2185602426bdc1', '774a8c437448fd104c24534dd4ce78c96c307ec50daa87cc3b2185602426bdc1', NULL, 'الله الذي له ما في السموت وما في الارض وويل للكفرين من عذاب شديد', 13, 26, 102, 1, 3, 255, false, NULL),
    (1753, 'tanzil-uthmani-v1.1', 14, 3, 'ٱلَّذِينَ يَسْتَحِبُّونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْـَٔاخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا أُو۟لَٰٓئِكَ فِى ضَلَٰلٍۭ بَعِيدٍ', '43fa6df92fc38fc74a6daa8cbee4ef8fe44450248f84e565659d2d43e223050e', 'ٱلَّذِينَ يَسْتَحِبُّونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْـَٔاخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا أُو۟لَٰٓئِكَ فِى ضَلَٰلٍۭ بَعِيدٍ', '43fa6df92fc38fc74a6daa8cbee4ef8fe44450248f84e565659d2d43e223050e', '43fa6df92fc38fc74a6daa8cbee4ef8fe44450248f84e565659d2d43e223050e', NULL, 'الذين يستحبون الحيوه الدنيا علي الاخره ويصدون عن سبيل الله ويبغونها عوجا اولئك في ضلل بعيد', 13, 26, 102, 1, 3, 255, false, NULL),
    (1754, 'tanzil-uthmani-v1.1', 14, 4, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '5933d4ef1c0e65042edac4ca916e0762594e7904cd27824777b5d36b88bfa45d', 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '5933d4ef1c0e65042edac4ca916e0762594e7904cd27824777b5d36b88bfa45d', '5933d4ef1c0e65042edac4ca916e0762594e7904cd27824777b5d36b88bfa45d', NULL, 'وما ارسلنا من رسول الا بلسان قومه ليبين لهم فيضل الله من يشاء ويهدي من يشاء وهو العزيز الحكيم', 13, 26, 102, 1, 3, 255, false, NULL),
    (1755, 'tanzil-uthmani-v1.1', 14, 5, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنْ أَخْرِجْ قَوْمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرْهُم بِأَيَّىٰمِ ٱللَّهِ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', '3f0a6cba7025f39a5ee360de3a3551a428571eb4adb1c4ceb18dec524b6c47ff', 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنْ أَخْرِجْ قَوْمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرْهُم بِأَيَّىٰمِ ٱللَّهِ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', '3f0a6cba7025f39a5ee360de3a3551a428571eb4adb1c4ceb18dec524b6c47ff', '3f0a6cba7025f39a5ee360de3a3551a428571eb4adb1c4ceb18dec524b6c47ff', NULL, 'ولقد ارسلنا موسي بايتنا ان اخرج قومك من الظلمت الي النور وذكرهم باييم الله ان في ذلك لايت لكل صبار شكور', 13, 26, 102, 1, 3, 255, false, NULL),
    (1756, 'tanzil-uthmani-v1.1', 14, 6, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', '906f10f24ddd5b433750e7c228355a6f74bc9cb6575e71a9d71cb641f6db6e17', 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ', '906f10f24ddd5b433750e7c228355a6f74bc9cb6575e71a9d71cb641f6db6e17', '906f10f24ddd5b433750e7c228355a6f74bc9cb6575e71a9d71cb641f6db6e17', NULL, 'واذ قال موسي لقومه اذكروا نعمه الله عليكم اذ انجيكم من ءال فرعون يسومونكم سوء العذاب ويذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم', 13, 26, 102, 1, 3, 256, false, NULL),
    (1757, 'tanzil-uthmani-v1.1', 14, 7, 'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌ', 'b97e491596aca6c6f0767dff800e14d0bc8aeda7fcaf4d65fc5b102045736770', 'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌ', 'b97e491596aca6c6f0767dff800e14d0bc8aeda7fcaf4d65fc5b102045736770', 'b97e491596aca6c6f0767dff800e14d0bc8aeda7fcaf4d65fc5b102045736770', NULL, 'واذ تاذن ربكم لئن شكرتم لازيدنكم ولئن كفرتم ان عذابي لشديد', 13, 26, 102, 1, 3, 256, false, NULL),
    (1758, 'tanzil-uthmani-v1.1', 14, 8, 'وَقَالَ مُوسَىٰٓ إِن تَكْفُرُوٓا۟ أَنتُمْ وَمَن فِى ٱلْأَرْضِ جَمِيعًا فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ', '1119cbb7a895abb73f0efc916bac068e767d5f94800711d36dd8079774ef783a', 'وَقَالَ مُوسَىٰٓ إِن تَكْفُرُوٓا۟ أَنتُمْ وَمَن فِى ٱلْأَرْضِ جَمِيعًا فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ', '1119cbb7a895abb73f0efc916bac068e767d5f94800711d36dd8079774ef783a', '1119cbb7a895abb73f0efc916bac068e767d5f94800711d36dd8079774ef783a', NULL, 'وقال موسي ان تكفروا انتم ومن في الارض جميعا فان الله لغني حميد', 13, 26, 102, 1, 3, 256, false, NULL),
    (1759, 'tanzil-uthmani-v1.1', 14, 9, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ مِن قَبْلِكُمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ لَا يَعْلَمُهُمْ إِلَّا ٱللَّهُ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرَدُّوٓا۟ أَيْدِيَهُمْ فِىٓ أَفْوَٰهِهِمْ وَقَالُوٓا۟ إِنَّا كَفَرْنَا بِمَآ أُرْسِلْتُم بِهِۦ وَإِنَّا لَفِى شَكٍّ مِّمَّا تَدْعُونَنَآ إِلَيْهِ مُرِيبٍ', '22ef91aacf7909fb9127f5f95129510fd09030c922a7b15a5ff100a3d40169d2', 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ مِن قَبْلِكُمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ لَا يَعْلَمُهُمْ إِلَّا ٱللَّهُ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرَدُّوٓا۟ أَيْدِيَهُمْ فِىٓ أَفْوَٰهِهِمْ وَقَالُوٓا۟ إِنَّا كَفَرْنَا بِمَآ أُرْسِلْتُم بِهِۦ وَإِنَّا لَفِى شَكٍّ مِّمَّا تَدْعُونَنَآ إِلَيْهِ مُرِيبٍ', '22ef91aacf7909fb9127f5f95129510fd09030c922a7b15a5ff100a3d40169d2', '22ef91aacf7909fb9127f5f95129510fd09030c922a7b15a5ff100a3d40169d2', NULL, 'الم ياتكم نبؤا الذين من قبلكم قوم نوح وعاد وثمود والذين من بعدهم لا يعلمهم الا الله جاءتهم رسلهم بالبينت فردوا ايديهم في افوههم وقالوا انا كفرنا بما ارسلتم به وانا لفي شك مما تدعوننا اليه مريب', 13, 26, 102, 1, 3, 256, false, NULL),
    (1760, 'tanzil-uthmani-v1.1', 14, 10, 'قَالَتْ رُسُلُهُمْ أَفِى ٱللَّهِ شَكٌّ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى قَالُوٓا۟ إِنْ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتُونَا بِسُلْطَٰنٍ مُّبِينٍ', '63191879d1ce4f80c0a556dfaac2568fb632f62d96e0e6d84e604ef257e7297f', 'قَالَتْ رُسُلُهُمْ أَفِى ٱللَّهِ شَكٌّ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى قَالُوٓا۟ إِنْ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتُونَا بِسُلْطَٰنٍ مُّبِينٍ', '63191879d1ce4f80c0a556dfaac2568fb632f62d96e0e6d84e604ef257e7297f', '63191879d1ce4f80c0a556dfaac2568fb632f62d96e0e6d84e604ef257e7297f', NULL, 'قالت رسلهم افي الله شك فاطر السموت والارض يدعوكم ليغفر لكم من ذنوبكم ويؤخركم الي اجل مسمي قالوا ان انتم الا بشر مثلنا تريدون ان تصدونا عما كان يعبد ءاباؤنا فاتونا بسلطن مبين', 13, 26, 103, 1, 3, 256, false, NULL),
    (1761, 'tanzil-uthmani-v1.1', 14, 11, 'قَالَتْ لَهُمْ رُسُلُهُمْ إِن نَّحْنُ إِلَّا بَشَرٌ مِّثْلُكُمْ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَمَا كَانَ لَنَآ أَن نَّأْتِيَكُم بِسُلْطَٰنٍ إِلَّا بِإِذْنِ ٱللَّهِ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '8687dffd00e2ab9f4a527811d276cee889d576338e9b899001064fecd46e29cf', 'قَالَتْ لَهُمْ رُسُلُهُمْ إِن نَّحْنُ إِلَّا بَشَرٌ مِّثْلُكُمْ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ وَمَا كَانَ لَنَآ أَن نَّأْتِيَكُم بِسُلْطَٰنٍ إِلَّا بِإِذْنِ ٱللَّهِ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '8687dffd00e2ab9f4a527811d276cee889d576338e9b899001064fecd46e29cf', '8687dffd00e2ab9f4a527811d276cee889d576338e9b899001064fecd46e29cf', NULL, 'قالت لهم رسلهم ان نحن الا بشر مثلكم ولكن الله يمن علي من يشاء من عباده وما كان لنا ان ناتيكم بسلطن الا باذن الله وعلي الله فليتوكل المؤمنون', 13, 26, 103, 1, 3, 257, false, NULL),
    (1762, 'tanzil-uthmani-v1.1', 14, 12, 'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدْ هَدَىٰنَا سُبُلَنَا وَلَنَصْبِرَنَّ عَلَىٰ مَآ ءَاذَيْتُمُونَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', '42c77167be109100f2ec2f0b50ca34ac12ad6377531f468dc8322bad61d3808c', 'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدْ هَدَىٰنَا سُبُلَنَا وَلَنَصْبِرَنَّ عَلَىٰ مَآ ءَاذَيْتُمُونَا وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', '42c77167be109100f2ec2f0b50ca34ac12ad6377531f468dc8322bad61d3808c', '42c77167be109100f2ec2f0b50ca34ac12ad6377531f468dc8322bad61d3808c', NULL, 'وما لنا الا نتوكل علي الله وقد هدينا سبلنا ولنصبرن علي ما ءاذيتمونا وعلي الله فليتوكل المتوكلون', 13, 26, 103, 1, 3, 257, false, NULL),
    (1763, 'tanzil-uthmani-v1.1', 14, 13, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنْ أَرْضِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا فَأَوْحَىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ٱلظَّٰلِمِينَ', 'e01fc3968c65234f4e621598fcaa5be5250e1ca38ce74e0c4e321bf25f4effaa', 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنْ أَرْضِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا فَأَوْحَىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ٱلظَّٰلِمِينَ', 'e01fc3968c65234f4e621598fcaa5be5250e1ca38ce74e0c4e321bf25f4effaa', 'e01fc3968c65234f4e621598fcaa5be5250e1ca38ce74e0c4e321bf25f4effaa', NULL, 'وقال الذين كفروا لرسلهم لنخرجنكم من ارضنا او لتعودن في ملتنا فاوحي اليهم ربهم لنهلكن الظلمين', 13, 26, 103, 1, 3, 257, false, NULL),
    (1764, 'tanzil-uthmani-v1.1', 14, 14, 'وَلَنُسْكِنَنَّكُمُ ٱلْأَرْضَ مِنۢ بَعْدِهِمْ ذَٰلِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَعِيدِ', '93cb8abb19aefe5907b4b81b3c706597d04f7493b6e5ed7eb420f772f6f97963', 'وَلَنُسْكِنَنَّكُمُ ٱلْأَرْضَ مِنۢ بَعْدِهِمْ ذَٰلِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَعِيدِ', '93cb8abb19aefe5907b4b81b3c706597d04f7493b6e5ed7eb420f772f6f97963', '93cb8abb19aefe5907b4b81b3c706597d04f7493b6e5ed7eb420f772f6f97963', NULL, 'ولنسكننكم الارض من بعدهم ذلك لمن خاف مقامي وخاف وعيد', 13, 26, 103, 1, 3, 257, false, NULL),
    (1765, 'tanzil-uthmani-v1.1', 14, 15, 'وَٱسْتَفْتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٍ', 'a3e7e6ff5070c6d21520620f9912b166328a273de3e8b6198023a44dcea49a58', 'وَٱسْتَفْتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٍ', 'a3e7e6ff5070c6d21520620f9912b166328a273de3e8b6198023a44dcea49a58', 'a3e7e6ff5070c6d21520620f9912b166328a273de3e8b6198023a44dcea49a58', NULL, 'واستفتحوا وخاب كل جبار عنيد', 13, 26, 103, 1, 3, 257, false, NULL),
    (1766, 'tanzil-uthmani-v1.1', 14, 16, 'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسْقَىٰ مِن مَّآءٍ صَدِيدٍ', 'd957d36175f67461b5c460239ca2a285c14d53426edd2ab39d78add6282990ec', 'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسْقَىٰ مِن مَّآءٍ صَدِيدٍ', 'd957d36175f67461b5c460239ca2a285c14d53426edd2ab39d78add6282990ec', 'd957d36175f67461b5c460239ca2a285c14d53426edd2ab39d78add6282990ec', NULL, 'من ورائه جهنم ويسقي من ماء صديد', 13, 26, 103, 1, 3, 257, false, NULL),
    (1767, 'tanzil-uthmani-v1.1', 14, 17, 'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأْتِيهِ ٱلْمَوْتُ مِن كُلِّ مَكَانٍ وَمَا هُوَ بِمَيِّتٍ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٌ', '872e3e35400a167782e07626c2cb16ecaf9b34b07efcfea8a824af4548492b4e', 'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأْتِيهِ ٱلْمَوْتُ مِن كُلِّ مَكَانٍ وَمَا هُوَ بِمَيِّتٍ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٌ', '872e3e35400a167782e07626c2cb16ecaf9b34b07efcfea8a824af4548492b4e', '872e3e35400a167782e07626c2cb16ecaf9b34b07efcfea8a824af4548492b4e', NULL, 'يتجرعه ولا يكاد يسيغه وياتيه الموت من كل مكان وما هو بميت ومن ورائه عذاب غليظ', 13, 26, 103, 1, 3, 257, false, NULL),
    (1768, 'tanzil-uthmani-v1.1', 14, 18, 'مَّثَلُ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ أَعْمَٰلُهُمْ كَرَمَادٍ ٱشْتَدَّتْ بِهِ ٱلرِّيحُ فِى يَوْمٍ عَاصِفٍ لَّا يَقْدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَىْءٍ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', '2cd496dddd0d9be057f3610f76e6ff047f1ed0539921b850b9bcdfd9fb189e7c', 'مَّثَلُ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ أَعْمَٰلُهُمْ كَرَمَادٍ ٱشْتَدَّتْ بِهِ ٱلرِّيحُ فِى يَوْمٍ عَاصِفٍ لَّا يَقْدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَىْءٍ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', '2cd496dddd0d9be057f3610f76e6ff047f1ed0539921b850b9bcdfd9fb189e7c', '2cd496dddd0d9be057f3610f76e6ff047f1ed0539921b850b9bcdfd9fb189e7c', NULL, 'مثل الذين كفروا بربهم اعملهم كرماد اشتدت به الريح في يوم عاصف لا يقدرون مما كسبوا علي شيء ذلك هو الضلل البعيد', 13, 26, 103, 1, 3, 257, false, NULL),
    (1769, 'tanzil-uthmani-v1.1', 14, 19, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', 'a4871eaaee6a69e6b1eab60851e7560c5171dd6e61483f1d373850053441134b', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', 'a4871eaaee6a69e6b1eab60851e7560c5171dd6e61483f1d373850053441134b', 'a4871eaaee6a69e6b1eab60851e7560c5171dd6e61483f1d373850053441134b', NULL, 'الم تر ان الله خلق السموت والارض بالحق ان يشا يذهبكم ويات بخلق جديد', 13, 26, 103, 1, 3, 258, false, NULL),
    (1770, 'tanzil-uthmani-v1.1', 14, 20, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', 'bf93483a6a94a234a5111dcf1daf8f32733873aaed3c085d15fbb3728c1ddc54', 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', 'bf93483a6a94a234a5111dcf1daf8f32733873aaed3c085d15fbb3728c1ddc54', 'bf93483a6a94a234a5111dcf1daf8f32733873aaed3c085d15fbb3728c1ddc54', NULL, 'وما ذلك علي الله بعزيز', 13, 26, 103, 1, 3, 258, false, NULL),
    (1771, 'tanzil-uthmani-v1.1', 14, 21, 'وَبَرَزُوا۟ لِلَّهِ جَمِيعًا فَقَالَ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ٱللَّهِ مِن شَىْءٍ قَالُوا۟ لَوْ هَدَىٰنَا ٱللَّهُ لَهَدَيْنَٰكُمْ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍ', '999d83804a667e7cc673e03e3cb69eda5c88e9008b4cf803c557a85d5d5865b7', 'وَبَرَزُوا۟ لِلَّهِ جَمِيعًا فَقَالَ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ٱللَّهِ مِن شَىْءٍ قَالُوا۟ لَوْ هَدَىٰنَا ٱللَّهُ لَهَدَيْنَٰكُمْ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍ', '999d83804a667e7cc673e03e3cb69eda5c88e9008b4cf803c557a85d5d5865b7', '999d83804a667e7cc673e03e3cb69eda5c88e9008b4cf803c557a85d5d5865b7', NULL, 'وبرزوا لله جميعا فقال الضعفؤا للذين استكبروا انا كنا لكم تبعا فهل انتم مغنون عنا من عذاب الله من شيء قالوا لو هدينا الله لهدينكم سواء علينا اجزعنا ام صبرنا ما لنا من محيص', 13, 26, 103, 1, 3, 258, false, NULL),
    (1772, 'tanzil-uthmani-v1.1', 14, 22, 'وَقَالَ ٱلشَّيْطَٰنُ لَمَّا قُضِىَ ٱلْأَمْرُ إِنَّ ٱللَّهَ وَعَدَكُمْ وَعْدَ ٱلْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَٰنٍ إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم مَّآ أَنَا۠ بِمُصْرِخِكُمْ وَمَآ أَنتُم بِمُصْرِخِىَّ إِنِّى كَفَرْتُ بِمَآ أَشْرَكْتُمُونِ مِن قَبْلُ إِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', '22a756dbe8405b19c81fbf49e43453db9bf6201af6ac08ff22d63a0fa6abd1b1', 'وَقَالَ ٱلشَّيْطَٰنُ لَمَّا قُضِىَ ٱلْأَمْرُ إِنَّ ٱللَّهَ وَعَدَكُمْ وَعْدَ ٱلْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَٰنٍ إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم مَّآ أَنَا۠ بِمُصْرِخِكُمْ وَمَآ أَنتُم بِمُصْرِخِىَّ إِنِّى كَفَرْتُ بِمَآ أَشْرَكْتُمُونِ مِن قَبْلُ إِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', '22a756dbe8405b19c81fbf49e43453db9bf6201af6ac08ff22d63a0fa6abd1b1', '22a756dbe8405b19c81fbf49e43453db9bf6201af6ac08ff22d63a0fa6abd1b1', NULL, 'وقال الشيطن لما قضي الامر ان الله وعدكم وعد الحق ووعدتكم فاخلفتكم وما كان لي عليكم من سلطن الا ان دعوتكم فاستجبتم لي فلا تلوموني ولوموا انفسكم ما انا بمصرخكم وما انتم بمصرخي اني كفرت بما اشركتمون من قبل ان الظلمين لهم عذاب اليم', 13, 26, 103, 1, 3, 258, false, NULL),
    (1773, 'tanzil-uthmani-v1.1', 14, 23, 'وَأُدْخِلَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ تَحِيَّتُهُمْ فِيهَا سَلَٰمٌ', 'd993287d5e6d22a20711dacd762db06558901d5800a59efbcf45c2f8685ecd1c', 'وَأُدْخِلَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ تَحِيَّتُهُمْ فِيهَا سَلَٰمٌ', 'd993287d5e6d22a20711dacd762db06558901d5800a59efbcf45c2f8685ecd1c', 'd993287d5e6d22a20711dacd762db06558901d5800a59efbcf45c2f8685ecd1c', NULL, 'وادخل الذين ءامنوا وعملوا الصلحت جنت تجري من تحتها الانهر خلدين فيها باذن ربهم تحيتهم فيها سلم', 13, 26, 103, 1, 3, 258, false, NULL),
    (1774, 'tanzil-uthmani-v1.1', 14, 24, 'أَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًا كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِى ٱلسَّمَآءِ', '55228cf526979ca4b210c7a76ada5f18b430f1868a817e149aded529f58f3447', 'أَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًا كَلِمَةً طَيِّبَةً كَشَجَرَةٍ طَيِّبَةٍ أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِى ٱلسَّمَآءِ', '55228cf526979ca4b210c7a76ada5f18b430f1868a817e149aded529f58f3447', '55228cf526979ca4b210c7a76ada5f18b430f1868a817e149aded529f58f3447', NULL, 'الم تر كيف ضرب الله مثلا كلمه طيبه كشجره طيبه اصلها ثابت وفرعها في السماء', 13, 26, 103, 1, 3, 258, false, NULL),
    (1775, 'tanzil-uthmani-v1.1', 14, 25, 'تُؤْتِىٓ أُكُلَهَا كُلَّ حِينٍۭ بِإِذْنِ رَبِّهَا وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', '8cc6b7bfcaf72ca11d604c630d69c1cf7ccbbcf103e1f8663b0cf5964daade34', 'تُؤْتِىٓ أُكُلَهَا كُلَّ حِينٍۭ بِإِذْنِ رَبِّهَا وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', '8cc6b7bfcaf72ca11d604c630d69c1cf7ccbbcf103e1f8663b0cf5964daade34', '8cc6b7bfcaf72ca11d604c630d69c1cf7ccbbcf103e1f8663b0cf5964daade34', NULL, 'تؤتي اكلها كل حين باذن ربها ويضرب الله الامثال للناس لعلهم يتذكرون', 13, 26, 103, 1, 3, 259, false, NULL),
    (1776, 'tanzil-uthmani-v1.1', 14, 26, 'وَمَثَلُ كَلِمَةٍ خَبِيثَةٍ كَشَجَرَةٍ خَبِيثَةٍ ٱجْتُثَّتْ مِن فَوْقِ ٱلْأَرْضِ مَا لَهَا مِن قَرَارٍ', '023c4e4af4dbd081762201edb3b1ff4d14493438ce791d0dd2e1b98121670d98', 'وَمَثَلُ كَلِمَةٍ خَبِيثَةٍ كَشَجَرَةٍ خَبِيثَةٍ ٱجْتُثَّتْ مِن فَوْقِ ٱلْأَرْضِ مَا لَهَا مِن قَرَارٍ', '023c4e4af4dbd081762201edb3b1ff4d14493438ce791d0dd2e1b98121670d98', '023c4e4af4dbd081762201edb3b1ff4d14493438ce791d0dd2e1b98121670d98', NULL, 'ومثل كلمه خبيثه كشجره خبيثه اجتثت من فوق الارض ما لها من قرار', 13, 26, 103, 1, 3, 259, false, NULL),
    (1777, 'tanzil-uthmani-v1.1', 14, 27, 'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ بِٱلْقَوْلِ ٱلثَّابِتِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَ وَيَفْعَلُ ٱللَّهُ مَا يَشَآءُ', 'e51e74962988e6a949815b384ce25dd4fbf264490da77985342ddb9119fd3374', 'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ بِٱلْقَوْلِ ٱلثَّابِتِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَ وَيَفْعَلُ ٱللَّهُ مَا يَشَآءُ', 'e51e74962988e6a949815b384ce25dd4fbf264490da77985342ddb9119fd3374', 'e51e74962988e6a949815b384ce25dd4fbf264490da77985342ddb9119fd3374', NULL, 'يثبت الله الذين ءامنوا بالقول الثابت في الحيوه الدنيا وفي الاخره ويضل الله الظلمين ويفعل الله ما يشاء', 13, 26, 103, 1, 3, 259, false, NULL),
    (1778, 'tanzil-uthmani-v1.1', 14, 28, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ بَدَّلُوا۟ نِعْمَتَ ٱللَّهِ كُفْرًا وَأَحَلُّوا۟ قَوْمَهُمْ دَارَ ٱلْبَوَارِ', 'b9493984b33bb4116a52648127cc81392ac80de1894ea2ca8ba7b438aab7fb91', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ بَدَّلُوا۟ نِعْمَتَ ٱللَّهِ كُفْرًا وَأَحَلُّوا۟ قَوْمَهُمْ دَارَ ٱلْبَوَارِ', 'b9493984b33bb4116a52648127cc81392ac80de1894ea2ca8ba7b438aab7fb91', 'b9493984b33bb4116a52648127cc81392ac80de1894ea2ca8ba7b438aab7fb91', NULL, 'الم تر الي الذين بدلوا نعمت الله كفرا واحلوا قومهم دار البوار', 13, 26, 104, 1, 3, 259, false, NULL),
    (1779, 'tanzil-uthmani-v1.1', 14, 29, 'جَهَنَّمَ يَصْلَوْنَهَا وَبِئْسَ ٱلْقَرَارُ', 'f18bff258f17d540fc7fa18b4e8b68509e1a24c3ed749a5ad0a2c4ecc7686471', 'جَهَنَّمَ يَصْلَوْنَهَا وَبِئْسَ ٱلْقَرَارُ', 'f18bff258f17d540fc7fa18b4e8b68509e1a24c3ed749a5ad0a2c4ecc7686471', 'f18bff258f17d540fc7fa18b4e8b68509e1a24c3ed749a5ad0a2c4ecc7686471', NULL, 'جهنم يصلونها وبئس القرار', 13, 26, 104, 1, 3, 259, false, NULL),
    (1780, 'tanzil-uthmani-v1.1', 14, 30, 'وَجَعَلُوا۟ لِلَّهِ أَندَادًا لِّيُضِلُّوا۟ عَن سَبِيلِهِۦ قُلْ تَمَتَّعُوا۟ فَإِنَّ مَصِيرَكُمْ إِلَى ٱلنَّارِ', '12f63b38e873fae8c5b5b5edbb6376966d4ec1b76638ecd1f8d5d4618b32d875', 'وَجَعَلُوا۟ لِلَّهِ أَندَادًا لِّيُضِلُّوا۟ عَن سَبِيلِهِۦ قُلْ تَمَتَّعُوا۟ فَإِنَّ مَصِيرَكُمْ إِلَى ٱلنَّارِ', '12f63b38e873fae8c5b5b5edbb6376966d4ec1b76638ecd1f8d5d4618b32d875', '12f63b38e873fae8c5b5b5edbb6376966d4ec1b76638ecd1f8d5d4618b32d875', NULL, 'وجعلوا لله اندادا ليضلوا عن سبيله قل تمتعوا فان مصيركم الي النار', 13, 26, 104, 1, 3, 259, false, NULL),
    (1781, 'tanzil-uthmani-v1.1', 14, 31, 'قُل لِّعِبَادِىَ ٱلَّذِينَ ءَامَنُوا۟ يُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُنفِقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خِلَٰلٌ', '29306dfdeb2559fb0e29ad6c5e9bdaa08a297e2d6075fa47d895edd0c1a98365', 'قُل لِّعِبَادِىَ ٱلَّذِينَ ءَامَنُوا۟ يُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُنفِقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خِلَٰلٌ', '29306dfdeb2559fb0e29ad6c5e9bdaa08a297e2d6075fa47d895edd0c1a98365', '29306dfdeb2559fb0e29ad6c5e9bdaa08a297e2d6075fa47d895edd0c1a98365', NULL, 'قل لعبادي الذين ءامنوا يقيموا الصلوه وينفقوا مما رزقنهم سرا وعلانيه من قبل ان ياتي يوم لا بيع فيه ولا خلل', 13, 26, 104, 1, 3, 259, false, NULL),
    (1782, 'tanzil-uthmani-v1.1', 14, 32, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ وَسَخَّرَ لَكُمُ ٱلْفُلْكَ لِتَجْرِىَ فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَسَخَّرَ لَكُمُ ٱلْأَنْهَٰرَ', 'a2ae8c3a7c8ff5be21c0836f2dd6bf13c49871dc768e9034509a3ca2f4fa7d63', 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ وَسَخَّرَ لَكُمُ ٱلْفُلْكَ لِتَجْرِىَ فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَسَخَّرَ لَكُمُ ٱلْأَنْهَٰرَ', 'a2ae8c3a7c8ff5be21c0836f2dd6bf13c49871dc768e9034509a3ca2f4fa7d63', 'a2ae8c3a7c8ff5be21c0836f2dd6bf13c49871dc768e9034509a3ca2f4fa7d63', NULL, 'الله الذي خلق السموت والارض وانزل من السماء ماء فاخرج به من الثمرت رزقا لكم وسخر لكم الفلك لتجري في البحر بامره وسخر لكم الانهر', 13, 26, 104, 1, 3, 259, false, NULL),
    (1783, 'tanzil-uthmani-v1.1', 14, 33, 'وَسَخَّرَ لَكُمُ ٱلشَّمْسَ وَٱلْقَمَرَ دَآئِبَيْنِ وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ', 'e96f26f05939645e8c191c1bb14bc8f0d2ec72b0a2b527d743efb5a1032a2be3', 'وَسَخَّرَ لَكُمُ ٱلشَّمْسَ وَٱلْقَمَرَ دَآئِبَيْنِ وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ', 'e96f26f05939645e8c191c1bb14bc8f0d2ec72b0a2b527d743efb5a1032a2be3', 'e96f26f05939645e8c191c1bb14bc8f0d2ec72b0a2b527d743efb5a1032a2be3', NULL, 'وسخر لكم الشمس والقمر دائبين وسخر لكم اليل والنهار', 13, 26, 104, 1, 3, 259, false, NULL),
    (1784, 'tanzil-uthmani-v1.1', 14, 34, 'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ وَإِن تَعُدُّوا۟ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ إِنَّ ٱلْإِنسَٰنَ لَظَلُومٌ كَفَّارٌ', 'af8663d8b5abeca86fb0d2ede48f7974ad578a554693e98c5021ab031c3bd793', 'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ وَإِن تَعُدُّوا۟ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ إِنَّ ٱلْإِنسَٰنَ لَظَلُومٌ كَفَّارٌ', 'af8663d8b5abeca86fb0d2ede48f7974ad578a554693e98c5021ab031c3bd793', 'af8663d8b5abeca86fb0d2ede48f7974ad578a554693e98c5021ab031c3bd793', NULL, 'وءاتيكم من كل ما سالتموه وان تعدوا نعمت الله لا تحصوها ان الانسن لظلوم كفار', 13, 26, 104, 1, 3, 260, false, NULL),
    (1785, 'tanzil-uthmani-v1.1', 14, 35, 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ٱجْعَلْ هَٰذَا ٱلْبَلَدَ ءَامِنًا وَٱجْنُبْنِى وَبَنِىَّ أَن نَّعْبُدَ ٱلْأَصْنَامَ', 'a8cbb3c3b5384f2c434eb3e6393f2a68ed307534c197071425c610f527023373', 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ٱجْعَلْ هَٰذَا ٱلْبَلَدَ ءَامِنًا وَٱجْنُبْنِى وَبَنِىَّ أَن نَّعْبُدَ ٱلْأَصْنَامَ', 'a8cbb3c3b5384f2c434eb3e6393f2a68ed307534c197071425c610f527023373', 'a8cbb3c3b5384f2c434eb3e6393f2a68ed307534c197071425c610f527023373', NULL, 'واذ قال ابرهيم رب اجعل هذا البلد ءامنا واجنبني وبني ان نعبد الاصنام', 13, 26, 104, 1, 3, 260, false, NULL),
    (1786, 'tanzil-uthmani-v1.1', 14, 36, 'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ ٱلنَّاسِ فَمَن تَبِعَنِى فَإِنَّهُۥ مِنِّى وَمَنْ عَصَانِى فَإِنَّكَ غَفُورٌ رَّحِيمٌ', '139c3b32fe58965a14929cb8293bed32ed37c0fd1437d18bc32007eefef23a36', 'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ ٱلنَّاسِ فَمَن تَبِعَنِى فَإِنَّهُۥ مِنِّى وَمَنْ عَصَانِى فَإِنَّكَ غَفُورٌ رَّحِيمٌ', '139c3b32fe58965a14929cb8293bed32ed37c0fd1437d18bc32007eefef23a36', '139c3b32fe58965a14929cb8293bed32ed37c0fd1437d18bc32007eefef23a36', NULL, 'رب انهن اضللن كثيرا من الناس فمن تبعني فانه مني ومن عصاني فانك غفور رحيم', 13, 26, 104, 1, 3, 260, false, NULL),
    (1787, 'tanzil-uthmani-v1.1', 14, 37, 'رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةً مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ', '81fb68ee9389489024b7411a1307c17be57ca2bb196273980f04f06b1b176558', 'رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةً مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ', '81fb68ee9389489024b7411a1307c17be57ca2bb196273980f04f06b1b176558', '81fb68ee9389489024b7411a1307c17be57ca2bb196273980f04f06b1b176558', NULL, 'ربنا اني اسكنت من ذريتي بواد غير ذي زرع عند بيتك المحرم ربنا ليقيموا الصلوه فاجعل افده من الناس تهوي اليهم وارزقهم من الثمرت لعلهم يشكرون', 13, 26, 104, 1, 3, 260, false, NULL),
    (1788, 'tanzil-uthmani-v1.1', 14, 38, 'رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 'eae6e3d0c21b697f08c301b91260286abedead43d15b125e62b379c8e49efb25', 'رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 'eae6e3d0c21b697f08c301b91260286abedead43d15b125e62b379c8e49efb25', 'eae6e3d0c21b697f08c301b91260286abedead43d15b125e62b379c8e49efb25', NULL, 'ربنا انك تعلم ما نخفي وما نعلن وما يخفي علي الله من شيء في الارض ولا في السماء', 13, 26, 104, 1, 3, 260, false, NULL),
    (1789, 'tanzil-uthmani-v1.1', 14, 39, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى وَهَبَ لِى عَلَى ٱلْكِبَرِ إِسْمَٰعِيلَ وَإِسْحَٰقَ إِنَّ رَبِّى لَسَمِيعُ ٱلدُّعَآءِ', '9bb548e3fa32713e7c0d77f6ad44c3440dd097075ae59901c4fc8e43571700b7', 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى وَهَبَ لِى عَلَى ٱلْكِبَرِ إِسْمَٰعِيلَ وَإِسْحَٰقَ إِنَّ رَبِّى لَسَمِيعُ ٱلدُّعَآءِ', '9bb548e3fa32713e7c0d77f6ad44c3440dd097075ae59901c4fc8e43571700b7', '9bb548e3fa32713e7c0d77f6ad44c3440dd097075ae59901c4fc8e43571700b7', NULL, 'الحمد لله الذي وهب لي علي الكبر اسمعيل واسحق ان ربي لسميع الدعاء', 13, 26, 104, 1, 3, 260, false, NULL),
    (1790, 'tanzil-uthmani-v1.1', 14, 40, 'رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى رَبَّنَا وَتَقَبَّلْ دُعَآءِ', 'e1ea2a2b9ec0ccdb1131561b130adca17502eaf39be35bb93f9905b44f5347bc', 'رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى رَبَّنَا وَتَقَبَّلْ دُعَآءِ', 'e1ea2a2b9ec0ccdb1131561b130adca17502eaf39be35bb93f9905b44f5347bc', 'e1ea2a2b9ec0ccdb1131561b130adca17502eaf39be35bb93f9905b44f5347bc', NULL, 'رب اجعلني مقيم الصلوه ومن ذريتي ربنا وتقبل دعاء', 13, 26, 104, 1, 3, 260, false, NULL),
    (1791, 'tanzil-uthmani-v1.1', 14, 41, 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', '207766da33b5fe0fc593cc22a185d12e3fd9b41ecfc4204031105caf771ecf5d', 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', '207766da33b5fe0fc593cc22a185d12e3fd9b41ecfc4204031105caf771ecf5d', '207766da33b5fe0fc593cc22a185d12e3fd9b41ecfc4204031105caf771ecf5d', NULL, 'ربنا اغفر لي ولولدي وللمؤمنين يوم يقوم الحساب', 13, 26, 104, 1, 3, 260, false, NULL),
    (1792, 'tanzil-uthmani-v1.1', 14, 42, 'وَلَا تَحْسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعْمَلُ ٱلظَّٰلِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ ٱلْأَبْصَٰرُ', '4fce6c0c4bd8821a7d59e02646dff7caf2cfc86caaf57c05f368a7bc7d064918', 'وَلَا تَحْسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعْمَلُ ٱلظَّٰلِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ ٱلْأَبْصَٰرُ', '4fce6c0c4bd8821a7d59e02646dff7caf2cfc86caaf57c05f368a7bc7d064918', '4fce6c0c4bd8821a7d59e02646dff7caf2cfc86caaf57c05f368a7bc7d064918', NULL, 'ولا تحسبن الله غفلا عما يعمل الظلمون انما يؤخرهم ليوم تشخص فيه الابصر', 13, 26, 104, 1, 3, 260, false, NULL),
    (1793, 'tanzil-uthmani-v1.1', 14, 43, 'مُهْطِعِينَ مُقْنِعِى رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ وَأَفْـِٔدَتُهُمْ هَوَآءٌ', 'c5a34a6f29952b63acf15e6f3c26c4ddf6a9d10b92bc71d0c743d3bf1e007aba', 'مُهْطِعِينَ مُقْنِعِى رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ وَأَفْـِٔدَتُهُمْ هَوَآءٌ', 'c5a34a6f29952b63acf15e6f3c26c4ddf6a9d10b92bc71d0c743d3bf1e007aba', 'c5a34a6f29952b63acf15e6f3c26c4ddf6a9d10b92bc71d0c743d3bf1e007aba', NULL, 'مهطعين مقنعي رءوسهم لا يرتد اليهم طرفهم وافدتهم هواء', 13, 26, 104, 1, 3, 261, false, NULL),
    (1794, 'tanzil-uthmani-v1.1', 14, 44, 'وَأَنذِرِ ٱلنَّاسَ يَوْمَ يَأْتِيهِمُ ٱلْعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُوا۟ رَبَّنَآ أَخِّرْنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَ أَوَلَمْ تَكُونُوٓا۟ أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالٍ', 'e60e68a856488d4cbeea430c2388fc48bb47a64c928b7ad4c8ffc671a583f471', 'وَأَنذِرِ ٱلنَّاسَ يَوْمَ يَأْتِيهِمُ ٱلْعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُوا۟ رَبَّنَآ أَخِّرْنَآ إِلَىٰٓ أَجَلٍ قَرِيبٍ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَ أَوَلَمْ تَكُونُوٓا۟ أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالٍ', 'e60e68a856488d4cbeea430c2388fc48bb47a64c928b7ad4c8ffc671a583f471', 'e60e68a856488d4cbeea430c2388fc48bb47a64c928b7ad4c8ffc671a583f471', NULL, 'وانذر الناس يوم ياتيهم العذاب فيقول الذين ظلموا ربنا اخرنا الي اجل قريب نجب دعوتك ونتبع الرسل اولم تكونوا اقسمتم من قبل ما لكم من زوال', 13, 26, 104, 1, 3, 261, false, NULL),
    (1795, 'tanzil-uthmani-v1.1', 14, 45, 'وَسَكَنتُمْ فِى مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓا۟ أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ ٱلْأَمْثَالَ', 'ca87f1426cfb70a4f90289a7720a6b66505f8b80dd1d1714181c466de4c1ed2e', 'وَسَكَنتُمْ فِى مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓا۟ أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ ٱلْأَمْثَالَ', 'ca87f1426cfb70a4f90289a7720a6b66505f8b80dd1d1714181c466de4c1ed2e', 'ca87f1426cfb70a4f90289a7720a6b66505f8b80dd1d1714181c466de4c1ed2e', NULL, 'وسكنتم في مسكن الذين ظلموا انفسهم وتبين لكم كيف فعلنا بهم وضربنا لكم الامثال', 13, 26, 104, 1, 3, 261, false, NULL),
    (1796, 'tanzil-uthmani-v1.1', 14, 46, 'وَقَدْ مَكَرُوا۟ مَكْرَهُمْ وَعِندَ ٱللَّهِ مَكْرُهُمْ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ ٱلْجِبَالُ', 'c2a6b1622f586bf39739f246478b02b18f6ea9ba1baa4b3d9d20e8334301c823', 'وَقَدْ مَكَرُوا۟ مَكْرَهُمْ وَعِندَ ٱللَّهِ مَكْرُهُمْ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ ٱلْجِبَالُ', 'c2a6b1622f586bf39739f246478b02b18f6ea9ba1baa4b3d9d20e8334301c823', 'c2a6b1622f586bf39739f246478b02b18f6ea9ba1baa4b3d9d20e8334301c823', NULL, 'وقد مكروا مكرهم وعند الله مكرهم وان كان مكرهم لتزول منه الجبال', 13, 26, 104, 1, 3, 261, false, NULL),
    (1797, 'tanzil-uthmani-v1.1', 14, 47, 'فَلَا تَحْسَبَنَّ ٱللَّهَ مُخْلِفَ وَعْدِهِۦ رُسُلَهُۥٓ إِنَّ ٱللَّهَ عَزِيزٌ ذُو ٱنتِقَامٍ', '745bef784a2bd85d7f3e9875200bf764dafe893dae920d5fb2572b5e8fa3aeae', 'فَلَا تَحْسَبَنَّ ٱللَّهَ مُخْلِفَ وَعْدِهِۦ رُسُلَهُۥٓ إِنَّ ٱللَّهَ عَزِيزٌ ذُو ٱنتِقَامٍ', '745bef784a2bd85d7f3e9875200bf764dafe893dae920d5fb2572b5e8fa3aeae', '745bef784a2bd85d7f3e9875200bf764dafe893dae920d5fb2572b5e8fa3aeae', NULL, 'فلا تحسبن الله مخلف وعده رسله ان الله عزيز ذو انتقام', 13, 26, 104, 1, 3, 261, false, NULL),
    (1798, 'tanzil-uthmani-v1.1', 14, 48, 'يَوْمَ تُبَدَّلُ ٱلْأَرْضُ غَيْرَ ٱلْأَرْضِ وَٱلسَّمَٰوَٰتُ وَبَرَزُوا۟ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', '117355414d06582529ec8481b8b65a4f9bfbf854b674d15223d82cdfe50830bc', 'يَوْمَ تُبَدَّلُ ٱلْأَرْضُ غَيْرَ ٱلْأَرْضِ وَٱلسَّمَٰوَٰتُ وَبَرَزُوا۟ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', '117355414d06582529ec8481b8b65a4f9bfbf854b674d15223d82cdfe50830bc', '117355414d06582529ec8481b8b65a4f9bfbf854b674d15223d82cdfe50830bc', NULL, 'يوم تبدل الارض غير الارض والسموت وبرزوا لله الوحد القهار', 13, 26, 104, 1, 3, 261, false, NULL),
    (1799, 'tanzil-uthmani-v1.1', 14, 49, 'وَتَرَى ٱلْمُجْرِمِينَ يَوْمَئِذٍ مُّقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'ec47e42f126d0d48834b36e0aea23e9b5a6aa05e859eda05078d4e86529bb4ca', 'وَتَرَى ٱلْمُجْرِمِينَ يَوْمَئِذٍ مُّقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'ec47e42f126d0d48834b36e0aea23e9b5a6aa05e859eda05078d4e86529bb4ca', 'ec47e42f126d0d48834b36e0aea23e9b5a6aa05e859eda05078d4e86529bb4ca', NULL, 'وتري المجرمين يومئذ مقرنين في الاصفاد', 13, 26, 104, 1, 3, 261, false, NULL),
    (1800, 'tanzil-uthmani-v1.1', 14, 50, 'سَرَابِيلُهُم مِّن قَطِرَانٍ وَتَغْشَىٰ وُجُوهَهُمُ ٱلنَّارُ', '71181e4f28e688cae7b909773baa76db4ea9b218bb0127f599af11f3a6dd38d2', 'سَرَابِيلُهُم مِّن قَطِرَانٍ وَتَغْشَىٰ وُجُوهَهُمُ ٱلنَّارُ', '71181e4f28e688cae7b909773baa76db4ea9b218bb0127f599af11f3a6dd38d2', '71181e4f28e688cae7b909773baa76db4ea9b218bb0127f599af11f3a6dd38d2', NULL, 'سرابيلهم من قطران وتغشي وجوههم النار', 13, 26, 104, 1, 3, 261, false, NULL),
    (1801, 'tanzil-uthmani-v1.1', 14, 51, 'لِيَجْزِىَ ٱللَّهُ كُلَّ نَفْسٍ مَّا كَسَبَتْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'b87a02f68eea95fd093136f0e1f93f1c7dd20ac00cd17cee8c98214191d0fef1', 'لِيَجْزِىَ ٱللَّهُ كُلَّ نَفْسٍ مَّا كَسَبَتْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 'b87a02f68eea95fd093136f0e1f93f1c7dd20ac00cd17cee8c98214191d0fef1', 'b87a02f68eea95fd093136f0e1f93f1c7dd20ac00cd17cee8c98214191d0fef1', NULL, 'ليجزي الله كل نفس ما كسبت ان الله سريع الحساب', 13, 26, 104, 1, 3, 261, false, NULL),
    (1802, 'tanzil-uthmani-v1.1', 14, 52, 'هَٰذَا بَلَٰغٌ لِّلنَّاسِ وَلِيُنذَرُوا۟ بِهِۦ وَلِيَعْلَمُوٓا۟ أَنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ وَلِيَذَّكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '6bac961b084d35950fb423d3236b83a4d4aeefcbc1d8b68cc3842734e57a820f', 'هَٰذَا بَلَٰغٌ لِّلنَّاسِ وَلِيُنذَرُوا۟ بِهِۦ وَلِيَعْلَمُوٓا۟ أَنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ وَلِيَذَّكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '6bac961b084d35950fb423d3236b83a4d4aeefcbc1d8b68cc3842734e57a820f', '6bac961b084d35950fb423d3236b83a4d4aeefcbc1d8b68cc3842734e57a820f', NULL, 'هذا بلغ للناس ولينذروا به وليعلموا انما هو اله وحد وليذكر اولوا الالبب', 13, 26, 104, 1, 3, 261, false, NULL),
    (1803, 'tanzil-uthmani-v1.1', 15, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ وَقُرْءَانٍ مُّبِينٍ', '40350a3662b5c0ef1fd71e466c23b83cb387b8afc2e809281c364e1be8a77f09', 'الٓر تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ وَقُرْءَانٍ مُّبِينٍ', '6a03a913ec73a99e72c619dfd3c5e4a058568ab807cced07e69264621765d704', '6a03a913ec73a99e72c619dfd3c5e4a058568ab807cced07e69264621765d704', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الر تلك ءايت الكتب وقرءان مبين', 14, 27, 105, 1, 3, 262, false, NULL),
    (1804, 'tanzil-uthmani-v1.1', 15, 2, 'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ لَوْ كَانُوا۟ مُسْلِمِينَ', 'c3a809c7556c18e20274ba3437ba77ea6a57d2b914e0b7b441c9b3b7bd040502', 'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ لَوْ كَانُوا۟ مُسْلِمِينَ', 'c3a809c7556c18e20274ba3437ba77ea6a57d2b914e0b7b441c9b3b7bd040502', 'c3a809c7556c18e20274ba3437ba77ea6a57d2b914e0b7b441c9b3b7bd040502', NULL, 'ربما يود الذين كفروا لو كانوا مسلمين', 14, 27, 105, 1, 3, 262, false, NULL),
    (1805, 'tanzil-uthmani-v1.1', 15, 3, 'ذَرْهُمْ يَأْكُلُوا۟ وَيَتَمَتَّعُوا۟ وَيُلْهِهِمُ ٱلْأَمَلُ فَسَوْفَ يَعْلَمُونَ', 'dd7d83951c3db5b1cf309d7a1156e18dce7e6fb36bebdb38f33e815d7303c6f4', 'ذَرْهُمْ يَأْكُلُوا۟ وَيَتَمَتَّعُوا۟ وَيُلْهِهِمُ ٱلْأَمَلُ فَسَوْفَ يَعْلَمُونَ', 'dd7d83951c3db5b1cf309d7a1156e18dce7e6fb36bebdb38f33e815d7303c6f4', 'dd7d83951c3db5b1cf309d7a1156e18dce7e6fb36bebdb38f33e815d7303c6f4', NULL, 'ذرهم ياكلوا ويتمتعوا ويلههم الامل فسوف يعلمون', 14, 27, 105, 1, 3, 262, false, NULL),
    (1806, 'tanzil-uthmani-v1.1', 15, 4, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا وَلَهَا كِتَابٌ مَّعْلُومٌ', '357f44a20a4d6b0c61bc7469cbc4bb6b5b2e512dfc4486bf88424ab195924afc', 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا وَلَهَا كِتَابٌ مَّعْلُومٌ', '357f44a20a4d6b0c61bc7469cbc4bb6b5b2e512dfc4486bf88424ab195924afc', '357f44a20a4d6b0c61bc7469cbc4bb6b5b2e512dfc4486bf88424ab195924afc', NULL, 'وما اهلكنا من قريه الا ولها كتاب معلوم', 14, 27, 105, 1, 3, 262, false, NULL),
    (1807, 'tanzil-uthmani-v1.1', 15, 5, 'مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', '2466b3ff812f63f0634fda54a2978f2dea651f028045b41751aeca3408096a4e', 'مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', '2466b3ff812f63f0634fda54a2978f2dea651f028045b41751aeca3408096a4e', '2466b3ff812f63f0634fda54a2978f2dea651f028045b41751aeca3408096a4e', NULL, 'ما تسبق من امه اجلها وما يستخرون', 14, 27, 105, 1, 3, 262, false, NULL),
    (1808, 'tanzil-uthmani-v1.1', 15, 6, 'وَقَالُوا۟ يَٰٓأَيُّهَا ٱلَّذِى نُزِّلَ عَلَيْهِ ٱلذِّكْرُ إِنَّكَ لَمَجْنُونٌ', '2cad96c520d0b84a00c24594ff10bcb0eff6b1bed92a437240eb81c60b5e1725', 'وَقَالُوا۟ يَٰٓأَيُّهَا ٱلَّذِى نُزِّلَ عَلَيْهِ ٱلذِّكْرُ إِنَّكَ لَمَجْنُونٌ', '2cad96c520d0b84a00c24594ff10bcb0eff6b1bed92a437240eb81c60b5e1725', '2cad96c520d0b84a00c24594ff10bcb0eff6b1bed92a437240eb81c60b5e1725', NULL, 'وقالوا يايها الذي نزل عليه الذكر انك لمجنون', 14, 27, 105, 1, 3, 262, false, NULL),
    (1809, 'tanzil-uthmani-v1.1', 15, 7, 'لَّوْ مَا تَأْتِينَا بِٱلْمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'dd7ce529f315d9aa4bc3afe33937d87331531ed466db05814dabcd99ba86097c', 'لَّوْ مَا تَأْتِينَا بِٱلْمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'dd7ce529f315d9aa4bc3afe33937d87331531ed466db05814dabcd99ba86097c', 'dd7ce529f315d9aa4bc3afe33937d87331531ed466db05814dabcd99ba86097c', NULL, 'لو ما تاتينا بالملئكه ان كنت من الصدقين', 14, 27, 105, 1, 3, 262, false, NULL),
    (1810, 'tanzil-uthmani-v1.1', 15, 8, 'مَا نُنَزِّلُ ٱلْمَلَٰٓئِكَةَ إِلَّا بِٱلْحَقِّ وَمَا كَانُوٓا۟ إِذًا مُّنظَرِينَ', 'c02ed087ce8d2ef45ad1c324653930d6d3fbd3c3f085ef8884092c2516fe442a', 'مَا نُنَزِّلُ ٱلْمَلَٰٓئِكَةَ إِلَّا بِٱلْحَقِّ وَمَا كَانُوٓا۟ إِذًا مُّنظَرِينَ', 'c02ed087ce8d2ef45ad1c324653930d6d3fbd3c3f085ef8884092c2516fe442a', 'c02ed087ce8d2ef45ad1c324653930d6d3fbd3c3f085ef8884092c2516fe442a', NULL, 'ما ننزل الملئكه الا بالحق وما كانوا اذا منظرين', 14, 27, 105, 1, 3, 262, false, NULL),
    (1811, 'tanzil-uthmani-v1.1', 15, 9, 'إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', '6745ebea5122bf232d2eb99e2590d6412febf5b8e42c5310210149878e811602', 'إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', '6745ebea5122bf232d2eb99e2590d6412febf5b8e42c5310210149878e811602', '6745ebea5122bf232d2eb99e2590d6412febf5b8e42c5310210149878e811602', NULL, 'انا نحن نزلنا الذكر وانا له لحفظون', 14, 27, 105, 1, 3, 262, false, NULL),
    (1812, 'tanzil-uthmani-v1.1', 15, 10, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ فِى شِيَعِ ٱلْأَوَّلِينَ', 'fa74556c372f7fd2f0e6eee43323996427f5bf70648d2bf304d1d6ab45dca670', 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ فِى شِيَعِ ٱلْأَوَّلِينَ', 'fa74556c372f7fd2f0e6eee43323996427f5bf70648d2bf304d1d6ab45dca670', 'fa74556c372f7fd2f0e6eee43323996427f5bf70648d2bf304d1d6ab45dca670', NULL, 'ولقد ارسلنا من قبلك في شيع الاولين', 14, 27, 105, 1, 3, 262, false, NULL),
    (1813, 'tanzil-uthmani-v1.1', 15, 11, 'وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '49bb296987ecaebfa84d9afcc8de7a7ed2be6ff06e3c3eca764a7b517be9386b', 'وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '49bb296987ecaebfa84d9afcc8de7a7ed2be6ff06e3c3eca764a7b517be9386b', '49bb296987ecaebfa84d9afcc8de7a7ed2be6ff06e3c3eca764a7b517be9386b', NULL, 'وما ياتيهم من رسول الا كانوا به يستهزءون', 14, 27, 105, 1, 3, 262, false, NULL),
    (1814, 'tanzil-uthmani-v1.1', 15, 12, 'كَذَٰلِكَ نَسْلُكُهُۥ فِى قُلُوبِ ٱلْمُجْرِمِينَ', '2382469da2c0a8375811da8710caacae66013d5072ea6d7e8646c3a160353abd', 'كَذَٰلِكَ نَسْلُكُهُۥ فِى قُلُوبِ ٱلْمُجْرِمِينَ', '2382469da2c0a8375811da8710caacae66013d5072ea6d7e8646c3a160353abd', '2382469da2c0a8375811da8710caacae66013d5072ea6d7e8646c3a160353abd', NULL, 'كذلك نسلكه في قلوب المجرمين', 14, 27, 105, 1, 3, 262, false, NULL),
    (1815, 'tanzil-uthmani-v1.1', 15, 13, 'لَا يُؤْمِنُونَ بِهِۦ وَقَدْ خَلَتْ سُنَّةُ ٱلْأَوَّلِينَ', 'e7bdd1f2c17412f349f7887053fcac63624569e9e048002d4a272799e1be1cd5', 'لَا يُؤْمِنُونَ بِهِۦ وَقَدْ خَلَتْ سُنَّةُ ٱلْأَوَّلِينَ', 'e7bdd1f2c17412f349f7887053fcac63624569e9e048002d4a272799e1be1cd5', 'e7bdd1f2c17412f349f7887053fcac63624569e9e048002d4a272799e1be1cd5', NULL, 'لا يؤمنون به وقد خلت سنه الاولين', 14, 27, 105, 1, 3, 262, false, NULL),
    (1816, 'tanzil-uthmani-v1.1', 15, 14, 'وَلَوْ فَتَحْنَا عَلَيْهِم بَابًا مِّنَ ٱلسَّمَآءِ فَظَلُّوا۟ فِيهِ يَعْرُجُونَ', '66c7db8e2360f731cde9ac4626c8d494c3b0d0cfbb74b7bac2990d6d0a7aef6e', 'وَلَوْ فَتَحْنَا عَلَيْهِم بَابًا مِّنَ ٱلسَّمَآءِ فَظَلُّوا۟ فِيهِ يَعْرُجُونَ', '66c7db8e2360f731cde9ac4626c8d494c3b0d0cfbb74b7bac2990d6d0a7aef6e', '66c7db8e2360f731cde9ac4626c8d494c3b0d0cfbb74b7bac2990d6d0a7aef6e', NULL, 'ولو فتحنا عليهم بابا من السماء فظلوا فيه يعرجون', 14, 27, 105, 1, 3, 262, false, NULL),
    (1817, 'tanzil-uthmani-v1.1', 15, 15, 'لَقَالُوٓا۟ إِنَّمَا سُكِّرَتْ أَبْصَٰرُنَا بَلْ نَحْنُ قَوْمٌ مَّسْحُورُونَ', '0fc14ad712841f9ea34c8eecf1f7e0d9ebf5e723bf345d86cdc72e34cc55d9e2', 'لَقَالُوٓا۟ إِنَّمَا سُكِّرَتْ أَبْصَٰرُنَا بَلْ نَحْنُ قَوْمٌ مَّسْحُورُونَ', '0fc14ad712841f9ea34c8eecf1f7e0d9ebf5e723bf345d86cdc72e34cc55d9e2', '0fc14ad712841f9ea34c8eecf1f7e0d9ebf5e723bf345d86cdc72e34cc55d9e2', NULL, 'لقالوا انما سكرت ابصرنا بل نحن قوم مسحورون', 14, 27, 105, 1, 3, 262, false, NULL),
    (1818, 'tanzil-uthmani-v1.1', 15, 16, 'وَلَقَدْ جَعَلْنَا فِى ٱلسَّمَآءِ بُرُوجًا وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ', 'eef774e27b5e26966662c104b48c45452b8dd88160dca00f7d76f1ec22f58877', 'وَلَقَدْ جَعَلْنَا فِى ٱلسَّمَآءِ بُرُوجًا وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ', 'eef774e27b5e26966662c104b48c45452b8dd88160dca00f7d76f1ec22f58877', 'eef774e27b5e26966662c104b48c45452b8dd88160dca00f7d76f1ec22f58877', NULL, 'ولقد جعلنا في السماء بروجا وزينها للنظرين', 14, 27, 105, 1, 3, 263, false, NULL),
    (1819, 'tanzil-uthmani-v1.1', 15, 17, 'وَحَفِظْنَٰهَا مِن كُلِّ شَيْطَٰنٍ رَّجِيمٍ', '59dfbc842b707f380a544617bcd179e3615a6f16ae3e456f15ee7a74c183e0a3', 'وَحَفِظْنَٰهَا مِن كُلِّ شَيْطَٰنٍ رَّجِيمٍ', '59dfbc842b707f380a544617bcd179e3615a6f16ae3e456f15ee7a74c183e0a3', '59dfbc842b707f380a544617bcd179e3615a6f16ae3e456f15ee7a74c183e0a3', NULL, 'وحفظنها من كل شيطن رجيم', 14, 27, 105, 1, 3, 263, false, NULL),
    (1820, 'tanzil-uthmani-v1.1', 15, 18, 'إِلَّا مَنِ ٱسْتَرَقَ ٱلسَّمْعَ فَأَتْبَعَهُۥ شِهَابٌ مُّبِينٌ', 'a970bf79a9a10cad64e4fe97cca47b6443aa241a4f2b9477e8fef3379d2de33c', 'إِلَّا مَنِ ٱسْتَرَقَ ٱلسَّمْعَ فَأَتْبَعَهُۥ شِهَابٌ مُّبِينٌ', 'a970bf79a9a10cad64e4fe97cca47b6443aa241a4f2b9477e8fef3379d2de33c', 'a970bf79a9a10cad64e4fe97cca47b6443aa241a4f2b9477e8fef3379d2de33c', NULL, 'الا من استرق السمع فاتبعه شهاب مبين', 14, 27, 105, 1, 3, 263, false, NULL),
    (1821, 'tanzil-uthmani-v1.1', 15, 19, 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَىْءٍ مَّوْزُونٍ', '3c789ad5df4b31c895912e4457292bf168add0a36c54fe5f9042f09063e3b4bd', 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَىْءٍ مَّوْزُونٍ', '3c789ad5df4b31c895912e4457292bf168add0a36c54fe5f9042f09063e3b4bd', '3c789ad5df4b31c895912e4457292bf168add0a36c54fe5f9042f09063e3b4bd', NULL, 'والارض مددنها والقينا فيها روسي وانبتنا فيها من كل شيء موزون', 14, 27, 105, 1, 3, 263, false, NULL),
    (1822, 'tanzil-uthmani-v1.1', 15, 20, 'وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ', '2f9fca2fc2b70b6efa872ebd78ccc05f6400352cd7c152ab35baec3f0ea7050b', 'وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ', '2f9fca2fc2b70b6efa872ebd78ccc05f6400352cd7c152ab35baec3f0ea7050b', '2f9fca2fc2b70b6efa872ebd78ccc05f6400352cd7c152ab35baec3f0ea7050b', NULL, 'وجعلنا لكم فيها معيش ومن لستم له برزقين', 14, 27, 105, 1, 3, 263, false, NULL),
    (1823, 'tanzil-uthmani-v1.1', 15, 21, 'وَإِن مِّن شَىْءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٍ مَّعْلُومٍ', 'b66851f0b4b5e950150f6193ae32f12454c6c882fc45d47aa0ba068a65545f0e', 'وَإِن مِّن شَىْءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٍ مَّعْلُومٍ', 'b66851f0b4b5e950150f6193ae32f12454c6c882fc45d47aa0ba068a65545f0e', 'b66851f0b4b5e950150f6193ae32f12454c6c882fc45d47aa0ba068a65545f0e', NULL, 'وان من شيء الا عندنا خزائنه وما ننزله الا بقدر معلوم', 14, 27, 105, 1, 3, 263, false, NULL),
    (1824, 'tanzil-uthmani-v1.1', 15, 22, 'وَأَرْسَلْنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَسْقَيْنَٰكُمُوهُ وَمَآ أَنتُمْ لَهُۥ بِخَٰزِنِينَ', '027cc566ce7d95285f8adf015768f03f890ba278f003fe233fdb90dc6758133d', 'وَأَرْسَلْنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَسْقَيْنَٰكُمُوهُ وَمَآ أَنتُمْ لَهُۥ بِخَٰزِنِينَ', '027cc566ce7d95285f8adf015768f03f890ba278f003fe233fdb90dc6758133d', '027cc566ce7d95285f8adf015768f03f890ba278f003fe233fdb90dc6758133d', NULL, 'وارسلنا الريح لوقح فانزلنا من السماء ماء فاسقينكموه وما انتم له بخزنين', 14, 27, 105, 1, 3, 263, false, NULL),
    (1825, 'tanzil-uthmani-v1.1', 15, 23, 'وَإِنَّا لَنَحْنُ نُحْىِۦ وَنُمِيتُ وَنَحْنُ ٱلْوَٰرِثُونَ', '517f210d4cdbe1947cc72071238b5911669617d7d142216008fa7f9c42d07ce4', 'وَإِنَّا لَنَحْنُ نُحْىِۦ وَنُمِيتُ وَنَحْنُ ٱلْوَٰرِثُونَ', '517f210d4cdbe1947cc72071238b5911669617d7d142216008fa7f9c42d07ce4', '517f210d4cdbe1947cc72071238b5911669617d7d142216008fa7f9c42d07ce4', NULL, 'وانا لنحن نحي ونميت ونحن الورثون', 14, 27, 105, 1, 3, 263, false, NULL),
    (1826, 'tanzil-uthmani-v1.1', 15, 24, 'وَلَقَدْ عَلِمْنَا ٱلْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا ٱلْمُسْتَـْٔخِرِينَ', '6e18e9d6f0852f695864d0d3ecfa5363b70eccddae9286ed6b314c170e904df0', 'وَلَقَدْ عَلِمْنَا ٱلْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا ٱلْمُسْتَـْٔخِرِينَ', '6e18e9d6f0852f695864d0d3ecfa5363b70eccddae9286ed6b314c170e904df0', '6e18e9d6f0852f695864d0d3ecfa5363b70eccddae9286ed6b314c170e904df0', NULL, 'ولقد علمنا المستقدمين منكم ولقد علمنا المستخرين', 14, 27, 105, 1, 3, 263, false, NULL),
    (1827, 'tanzil-uthmani-v1.1', 15, 25, 'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', '231fec4b38cbbfd81cb6436d230844c796a0c18f4076745b6cb7434938d67ac2', 'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ إِنَّهُۥ حَكِيمٌ عَلِيمٌ', '231fec4b38cbbfd81cb6436d230844c796a0c18f4076745b6cb7434938d67ac2', '231fec4b38cbbfd81cb6436d230844c796a0c18f4076745b6cb7434938d67ac2', NULL, 'وان ربك هو يحشرهم انه حكيم عليم', 14, 27, 105, 1, 3, 263, false, NULL),
    (1828, 'tanzil-uthmani-v1.1', 15, 26, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', 'f9d99ad12e2f9ac1fedcf7d79f4ee8b7e9e58954cef598c2a5b0726ec7fd64be', 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', 'f9d99ad12e2f9ac1fedcf7d79f4ee8b7e9e58954cef598c2a5b0726ec7fd64be', 'f9d99ad12e2f9ac1fedcf7d79f4ee8b7e9e58954cef598c2a5b0726ec7fd64be', NULL, 'ولقد خلقنا الانسن من صلصل من حما مسنون', 14, 27, 105, 1, 3, 263, false, NULL),
    (1829, 'tanzil-uthmani-v1.1', 15, 27, 'وَٱلْجَآنَّ خَلَقْنَٰهُ مِن قَبْلُ مِن نَّارِ ٱلسَّمُومِ', 'c815ef9cad5fffb653ee3bdda0691644df1e4b2b762c8fe6dfc521dfd75b740a', 'وَٱلْجَآنَّ خَلَقْنَٰهُ مِن قَبْلُ مِن نَّارِ ٱلسَّمُومِ', 'c815ef9cad5fffb653ee3bdda0691644df1e4b2b762c8fe6dfc521dfd75b740a', 'c815ef9cad5fffb653ee3bdda0691644df1e4b2b762c8fe6dfc521dfd75b740a', NULL, 'والجان خلقنه من قبل من نار السموم', 14, 27, 105, 1, 3, 263, false, NULL),
    (1830, 'tanzil-uthmani-v1.1', 15, 28, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًا مِّن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', '5e39c2c39fc32f7fbd6b372db82fdcafa3226d94fc25fba2ed46998942df124a', 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًا مِّن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', '5e39c2c39fc32f7fbd6b372db82fdcafa3226d94fc25fba2ed46998942df124a', '5e39c2c39fc32f7fbd6b372db82fdcafa3226d94fc25fba2ed46998942df124a', NULL, 'واذ قال ربك للملئكه اني خلق بشرا من صلصل من حما مسنون', 14, 27, 105, 1, 3, 263, false, NULL),
    (1831, 'tanzil-uthmani-v1.1', 15, 29, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'a75706fff1b49661297bf6a3fa839e9001809b70d1adaf8abab09da44d82d222', 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'a75706fff1b49661297bf6a3fa839e9001809b70d1adaf8abab09da44d82d222', 'a75706fff1b49661297bf6a3fa839e9001809b70d1adaf8abab09da44d82d222', NULL, 'فاذا سويته ونفخت فيه من روحي فقعوا له سجدين', 14, 27, 105, 1, 3, 263, false, NULL),
    (1832, 'tanzil-uthmani-v1.1', 15, 30, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', '5c55497bd9739f53ff46e56339eddd92a100dbdda5de52d247a2b86225553568', 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', '5c55497bd9739f53ff46e56339eddd92a100dbdda5de52d247a2b86225553568', '5c55497bd9739f53ff46e56339eddd92a100dbdda5de52d247a2b86225553568', NULL, 'فسجد الملئكه كلهم اجمعون', 14, 27, 105, 1, 3, 263, false, NULL),
    (1833, 'tanzil-uthmani-v1.1', 15, 31, 'إِلَّآ إِبْلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'bbd28992555441b4d4c477cc6fe08d7c1c749f2dd50d15ef094ea7b71f319650', 'إِلَّآ إِبْلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'bbd28992555441b4d4c477cc6fe08d7c1c749f2dd50d15ef094ea7b71f319650', 'bbd28992555441b4d4c477cc6fe08d7c1c749f2dd50d15ef094ea7b71f319650', NULL, 'الا ابليس ابي ان يكون مع السجدين', 14, 27, 105, 1, 3, 263, false, NULL),
    (1834, 'tanzil-uthmani-v1.1', 15, 32, 'قَالَ يَٰٓإِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'bdbf42bf9d5a11efdef28404487b14603b836a32cc4db953d7f0c2cf962a1c53', 'قَالَ يَٰٓإِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ', 'bdbf42bf9d5a11efdef28404487b14603b836a32cc4db953d7f0c2cf962a1c53', 'bdbf42bf9d5a11efdef28404487b14603b836a32cc4db953d7f0c2cf962a1c53', NULL, 'قال يابليس ما لك الا تكون مع السجدين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1835, 'tanzil-uthmani-v1.1', 15, 33, 'قَالَ لَمْ أَكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُۥ مِن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', '04bb4806d6b06b2703417914f6d0deca34095387382dee379d582924325b3b17', 'قَالَ لَمْ أَكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُۥ مِن صَلْصَٰلٍ مِّنْ حَمَإٍ مَّسْنُونٍ', '04bb4806d6b06b2703417914f6d0deca34095387382dee379d582924325b3b17', '04bb4806d6b06b2703417914f6d0deca34095387382dee379d582924325b3b17', NULL, 'قال لم اكن لاسجد لبشر خلقته من صلصل من حما مسنون', 14, 27, 105, 1, 3, 264, false, NULL),
    (1836, 'tanzil-uthmani-v1.1', 15, 34, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', '9a4202650c3884442863a1c0aea00c57ac3070003d059ec86137c37de8dae673', 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', '9a4202650c3884442863a1c0aea00c57ac3070003d059ec86137c37de8dae673', '9a4202650c3884442863a1c0aea00c57ac3070003d059ec86137c37de8dae673', NULL, 'قال فاخرج منها فانك رجيم', 14, 27, 105, 1, 3, 264, false, NULL),
    (1837, 'tanzil-uthmani-v1.1', 15, 35, 'وَإِنَّ عَلَيْكَ ٱللَّعْنَةَ إِلَىٰ يَوْمِ ٱلدِّينِ', '9e3ee712ec44a13141cd6b8173593df83cf553fcff3c505b46f5a10ee2de2f79', 'وَإِنَّ عَلَيْكَ ٱللَّعْنَةَ إِلَىٰ يَوْمِ ٱلدِّينِ', '9e3ee712ec44a13141cd6b8173593df83cf553fcff3c505b46f5a10ee2de2f79', '9e3ee712ec44a13141cd6b8173593df83cf553fcff3c505b46f5a10ee2de2f79', NULL, 'وان عليك اللعنه الي يوم الدين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1838, 'tanzil-uthmani-v1.1', 15, 36, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', '9ebcefd8b3b39bdec6a892b34a3916be46b8c104ca57763047f7624364879c5e', 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', '9ebcefd8b3b39bdec6a892b34a3916be46b8c104ca57763047f7624364879c5e', '9ebcefd8b3b39bdec6a892b34a3916be46b8c104ca57763047f7624364879c5e', NULL, 'قال رب فانظرني الي يوم يبعثون', 14, 27, 105, 1, 3, 264, false, NULL),
    (1839, 'tanzil-uthmani-v1.1', 15, 37, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', '08a8475c9751346b59c2e105a0bb97077c6edb08f6b14010a2e80ec6bc363bc8', 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', '08a8475c9751346b59c2e105a0bb97077c6edb08f6b14010a2e80ec6bc363bc8', '08a8475c9751346b59c2e105a0bb97077c6edb08f6b14010a2e80ec6bc363bc8', NULL, 'قال فانك من المنظرين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1840, 'tanzil-uthmani-v1.1', 15, 38, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'ed860cfd3749d7c7ba6f1cff8c99eb8f4fd2d83cde0bb829de851da2bdc743d9', 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'ed860cfd3749d7c7ba6f1cff8c99eb8f4fd2d83cde0bb829de851da2bdc743d9', 'ed860cfd3749d7c7ba6f1cff8c99eb8f4fd2d83cde0bb829de851da2bdc743d9', NULL, 'الي يوم الوقت المعلوم', 14, 27, 105, 1, 3, 264, false, NULL),
    (1841, 'tanzil-uthmani-v1.1', 15, 39, 'قَالَ رَبِّ بِمَآ أَغْوَيْتَنِى لَأُزَيِّنَنَّ لَهُمْ فِى ٱلْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'b41db49c13982b167e6c2c7adbdf83a4c267e0708181b9d06c642d2a32c0e4a9', 'قَالَ رَبِّ بِمَآ أَغْوَيْتَنِى لَأُزَيِّنَنَّ لَهُمْ فِى ٱلْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'b41db49c13982b167e6c2c7adbdf83a4c267e0708181b9d06c642d2a32c0e4a9', 'b41db49c13982b167e6c2c7adbdf83a4c267e0708181b9d06c642d2a32c0e4a9', NULL, 'قال رب بما اغويتني لازينن لهم في الارض ولاغوينهم اجمعين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1842, 'tanzil-uthmani-v1.1', 15, 40, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', '06a49c97581cb3cf3e595bbcf6b17f1ea11e0ca8d242b3f6a5a8e37129f39631', 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', '06a49c97581cb3cf3e595bbcf6b17f1ea11e0ca8d242b3f6a5a8e37129f39631', '06a49c97581cb3cf3e595bbcf6b17f1ea11e0ca8d242b3f6a5a8e37129f39631', NULL, 'الا عبادك منهم المخلصين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1843, 'tanzil-uthmani-v1.1', 15, 41, 'قَالَ هَٰذَا صِرَٰطٌ عَلَىَّ مُسْتَقِيمٌ', '875c50902f0efd520eb6523081ecdda8e538b2989cb5367bd90c37104cfcfe76', 'قَالَ هَٰذَا صِرَٰطٌ عَلَىَّ مُسْتَقِيمٌ', '875c50902f0efd520eb6523081ecdda8e538b2989cb5367bd90c37104cfcfe76', '875c50902f0efd520eb6523081ecdda8e538b2989cb5367bd90c37104cfcfe76', NULL, 'قال هذا صرط علي مستقيم', 14, 27, 105, 1, 3, 264, false, NULL),
    (1844, 'tanzil-uthmani-v1.1', 15, 42, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلْغَاوِينَ', '95a964bd820550790fddb99b57a1a177f2d8585b0acad6c219005eec2d60b572', 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلْغَاوِينَ', '95a964bd820550790fddb99b57a1a177f2d8585b0acad6c219005eec2d60b572', '95a964bd820550790fddb99b57a1a177f2d8585b0acad6c219005eec2d60b572', NULL, 'ان عبادي ليس لك عليهم سلطن الا من اتبعك من الغاوين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1845, 'tanzil-uthmani-v1.1', 15, 43, 'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ', '613aef186fdfd5af0b1b2b474ef579114656ccb64c23f03c58705ff130e18b80', 'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ', '613aef186fdfd5af0b1b2b474ef579114656ccb64c23f03c58705ff130e18b80', '613aef186fdfd5af0b1b2b474ef579114656ccb64c23f03c58705ff130e18b80', NULL, 'وان جهنم لموعدهم اجمعين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1846, 'tanzil-uthmani-v1.1', 15, 44, 'لَهَا سَبْعَةُ أَبْوَٰبٍ لِّكُلِّ بَابٍ مِّنْهُمْ جُزْءٌ مَّقْسُومٌ', 'e52b468d6e96a244ffb765bbaedaf5edd0b27b94f3f127074b58ba21eca49d47', 'لَهَا سَبْعَةُ أَبْوَٰبٍ لِّكُلِّ بَابٍ مِّنْهُمْ جُزْءٌ مَّقْسُومٌ', 'e52b468d6e96a244ffb765bbaedaf5edd0b27b94f3f127074b58ba21eca49d47', 'e52b468d6e96a244ffb765bbaedaf5edd0b27b94f3f127074b58ba21eca49d47', NULL, 'لها سبعه ابوب لكل باب منهم جزء مقسوم', 14, 27, 105, 1, 3, 264, false, NULL),
    (1847, 'tanzil-uthmani-v1.1', 15, 45, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍ وَعُيُونٍ', 'c30b617c04b8d9acb891e9d1a3b4b2c91ef8b55cf3e3889339e3f9f7b2c15140', 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍ وَعُيُونٍ', 'c30b617c04b8d9acb891e9d1a3b4b2c91ef8b55cf3e3889339e3f9f7b2c15140', 'c30b617c04b8d9acb891e9d1a3b4b2c91ef8b55cf3e3889339e3f9f7b2c15140', NULL, 'ان المتقين في جنت وعيون', 14, 27, 105, 1, 3, 264, false, NULL),
    (1848, 'tanzil-uthmani-v1.1', 15, 46, 'ٱدْخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ', 'fe106dfe3b80ac0d2a5a773491c57354c0591494fb4ee08d22b82b7cb58559c9', 'ٱدْخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ', 'fe106dfe3b80ac0d2a5a773491c57354c0591494fb4ee08d22b82b7cb58559c9', 'fe106dfe3b80ac0d2a5a773491c57354c0591494fb4ee08d22b82b7cb58559c9', NULL, 'ادخلوها بسلم ءامنين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1849, 'tanzil-uthmani-v1.1', 15, 47, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ إِخْوَٰنًا عَلَىٰ سُرُرٍ مُّتَقَٰبِلِينَ', 'a0cb986b0b2f6efc0809419620d98d6a91420ac5dec41e52ef7902d729399337', 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ إِخْوَٰنًا عَلَىٰ سُرُرٍ مُّتَقَٰبِلِينَ', 'a0cb986b0b2f6efc0809419620d98d6a91420ac5dec41e52ef7902d729399337', 'a0cb986b0b2f6efc0809419620d98d6a91420ac5dec41e52ef7902d729399337', NULL, 'ونزعنا ما في صدورهم من غل اخونا علي سرر متقبلين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1850, 'tanzil-uthmani-v1.1', 15, 48, 'لَا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ', '768ef4403f9770f6264df27fb54b1951dee2529159632542b0b2b73e3702718a', 'لَا يَمَسُّهُمْ فِيهَا نَصَبٌ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ', '768ef4403f9770f6264df27fb54b1951dee2529159632542b0b2b73e3702718a', '768ef4403f9770f6264df27fb54b1951dee2529159632542b0b2b73e3702718a', NULL, 'لا يمسهم فيها نصب وما هم منها بمخرجين', 14, 27, 105, 1, 3, 264, false, NULL),
    (1851, 'tanzil-uthmani-v1.1', 15, 49, 'نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ', '917f5355cf2e1f7f0643be18f763edd5319da897ae0c2ad5c420396605c1f9ee', 'نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ', '917f5355cf2e1f7f0643be18f763edd5319da897ae0c2ad5c420396605c1f9ee', '917f5355cf2e1f7f0643be18f763edd5319da897ae0c2ad5c420396605c1f9ee', NULL, 'نبئ عبادي اني انا الغفور الرحيم', 14, 27, 105, 1, 3, 264, false, NULL),
