    (1853, 'tanzil-uthmani-v1.1', 15, 51, 'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ', '3b7dcddbe1e9cd447b22da9073421efc9bd43357767165a25b99522b1ed00f3a', 'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ', '3b7dcddbe1e9cd447b22da9073421efc9bd43357767165a25b99522b1ed00f3a', '3b7dcddbe1e9cd447b22da9073421efc9bd43357767165a25b99522b1ed00f3a', NULL, 'ونبئهم عن ضيف ابرهيم', 14, 27, 106, 1, 3, 264, false, NULL),
