    (1898, 'tanzil-uthmani-v1.1', 15, 96, 'ٱلَّذِينَ يَجْعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَسَوْفَ يَعْلَمُونَ', '77b0def9ad14c6a92ed783da639866f329370d601ff5cd00d7d1dac4a139516f', 'ٱلَّذِينَ يَجْعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَسَوْفَ يَعْلَمُونَ', '77b0def9ad14c6a92ed783da639866f329370d601ff5cd00d7d1dac4a139516f', '77b0def9ad14c6a92ed783da639866f329370d601ff5cd00d7d1dac4a139516f', NULL, 'الذين يجعلون مع الله الها ءاخر فسوف يعلمون', 14, 27, 106, 1, 3, 267, false, NULL),
    (1899, 'tanzil-uthmani-v1.1', 15, 97, 'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ', 'c8bc47cabb8f3de9cadca8192c6badaa3920ecf28cc8d471dd729a6491973d03', 'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ', 'c8bc47cabb8f3de9cadca8192c6badaa3920ecf28cc8d471dd729a6491973d03', 'c8bc47cabb8f3de9cadca8192c6badaa3920ecf28cc8d471dd729a6491973d03', NULL, 'ولقد نعلم انك يضيق صدرك بما يقولون', 14, 27, 106, 1, 3, 267, false, NULL),
    (1900, 'tanzil-uthmani-v1.1', 15, 98, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ ٱلسَّٰجِدِينَ', '870044ee70cf3ec7750510d41d00ced6cfec3406a7ac9c76651df13a88ecf4d4', 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ ٱلسَّٰجِدِينَ', '870044ee70cf3ec7750510d41d00ced6cfec3406a7ac9c76651df13a88ecf4d4', '870044ee70cf3ec7750510d41d00ced6cfec3406a7ac9c76651df13a88ecf4d4', NULL, 'فسبح بحمد ربك وكن من السجدين', 14, 27, 106, 1, 3, 267, false, NULL),
    (1901, 'tanzil-uthmani-v1.1', 15, 99, 'وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ', 'a34fe4ef5a710342b8e9fbc26e9784dc5cada3dab0727eae098489afbf0ffb2f', 'وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ', 'a34fe4ef5a710342b8e9fbc26e9784dc5cada3dab0727eae098489afbf0ffb2f', 'a34fe4ef5a710342b8e9fbc26e9784dc5cada3dab0727eae098489afbf0ffb2f', NULL, 'واعبد ربك حتي ياتيك اليقين', 14, 27, 106, 1, 3, 267, false, NULL),
    (1902, 'tanzil-uthmani-v1.1', 16, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ أَتَىٰٓ أَمْرُ ٱللَّهِ فَلَا تَسْتَعْجِلُوهُ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '0dbbc97a56190e8b1f6892dbaec748023a16ef73647c7027ce6f248f941803d5', 'أَتَىٰٓ أَمْرُ ٱللَّهِ فَلَا تَسْتَعْجِلُوهُ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'd7751e9ec3d4b6af670c655c3ed04cde9ebf31e42d9da2484df026fefe4ca4ab', 'd7751e9ec3d4b6af670c655c3ed04cde9ebf31e42d9da2484df026fefe4ca4ab', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'اتي امر الله فلا تستعجلوه سبحنه وتعلي عما يشركون', 14, 27, 107, 1, 3, 267, false, NULL),
    (1903, 'tanzil-uthmani-v1.1', 16, 2, 'يُنَزِّلُ ٱلْمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ أَنْ أَنذِرُوٓا۟ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ', '88d6f2d2083d0202a6eee8350385dd3a0b0f3ae724d94fb5db18da87a9e824bb', 'يُنَزِّلُ ٱلْمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ أَنْ أَنذِرُوٓا۟ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ', '88d6f2d2083d0202a6eee8350385dd3a0b0f3ae724d94fb5db18da87a9e824bb', '88d6f2d2083d0202a6eee8350385dd3a0b0f3ae724d94fb5db18da87a9e824bb', NULL, 'ينزل الملئكه بالروح من امره علي من يشاء من عباده ان انذروا انه لا اله الا انا فاتقون', 14, 27, 107, 1, 3, 267, false, NULL),
    (1904, 'tanzil-uthmani-v1.1', 16, 3, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ تَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '5d94d635a0f1f1d66056a1eb688c257c629e6d557c9f1bc47919959b0c6a22d1', 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ تَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '5d94d635a0f1f1d66056a1eb688c257c629e6d557c9f1bc47919959b0c6a22d1', '5d94d635a0f1f1d66056a1eb688c257c629e6d557c9f1bc47919959b0c6a22d1', NULL, 'خلق السموت والارض بالحق تعلي عما يشركون', 14, 27, 107, 1, 3, 267, false, NULL),
    (1905, 'tanzil-uthmani-v1.1', 16, 4, 'خَلَقَ ٱلْإِنسَٰنَ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', '39dd238114e81b32c2a5ea6fe4a160e8e9a94097b73eaa323a7e3867d649665a', 'خَلَقَ ٱلْإِنسَٰنَ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', '39dd238114e81b32c2a5ea6fe4a160e8e9a94097b73eaa323a7e3867d649665a', '39dd238114e81b32c2a5ea6fe4a160e8e9a94097b73eaa323a7e3867d649665a', NULL, 'خلق الانسن من نطفه فاذا هو خصيم مبين', 14, 27, 107, 1, 3, 267, false, NULL),
    (1906, 'tanzil-uthmani-v1.1', 16, 5, 'وَٱلْأَنْعَٰمَ خَلَقَهَا لَكُمْ فِيهَا دِفْءٌ وَمَنَٰفِعُ وَمِنْهَا تَأْكُلُونَ', '0a45bb2b6d74ac3c7e651ab652059af5a3d0e1a3df067f800fc20f607acfe247', 'وَٱلْأَنْعَٰمَ خَلَقَهَا لَكُمْ فِيهَا دِفْءٌ وَمَنَٰفِعُ وَمِنْهَا تَأْكُلُونَ', '0a45bb2b6d74ac3c7e651ab652059af5a3d0e1a3df067f800fc20f607acfe247', '0a45bb2b6d74ac3c7e651ab652059af5a3d0e1a3df067f800fc20f607acfe247', NULL, 'والانعم خلقها لكم فيها دفء ومنفع ومنها تاكلون', 14, 27, 107, 1, 3, 267, false, NULL),
    (1907, 'tanzil-uthmani-v1.1', 16, 6, 'وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ', '45db37faf0910db4d3f21166bb8cf83457bde308cf09261061382de528b1ff3e', 'وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ', '45db37faf0910db4d3f21166bb8cf83457bde308cf09261061382de528b1ff3e', '45db37faf0910db4d3f21166bb8cf83457bde308cf09261061382de528b1ff3e', NULL, 'ولكم فيها جمال حين تريحون وحين تسرحون', 14, 27, 107, 1, 3, 267, false, NULL),
    (1908, 'tanzil-uthmani-v1.1', 16, 7, 'وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَدٍ لَّمْ تَكُونُوا۟ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلْأَنفُسِ إِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', 'de68497a056ef6ee37ec177464c9ca3387d69c46691a008329945c81783a2d53', 'وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَدٍ لَّمْ تَكُونُوا۟ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلْأَنفُسِ إِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', 'de68497a056ef6ee37ec177464c9ca3387d69c46691a008329945c81783a2d53', 'de68497a056ef6ee37ec177464c9ca3387d69c46691a008329945c81783a2d53', NULL, 'وتحمل اثقالكم الي بلد لم تكونوا بلغيه الا بشق الانفس ان ربكم لرءوف رحيم', 14, 27, 107, 1, 3, 268, false, NULL),
    (1909, 'tanzil-uthmani-v1.1', 16, 8, 'وَٱلْخَيْلَ وَٱلْبِغَالَ وَٱلْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً وَيَخْلُقُ مَا لَا تَعْلَمُونَ', '821b19c549a4d89cb248ac3bc49aa88efcf298d40ca342c300d002c771511a5a', 'وَٱلْخَيْلَ وَٱلْبِغَالَ وَٱلْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً وَيَخْلُقُ مَا لَا تَعْلَمُونَ', '821b19c549a4d89cb248ac3bc49aa88efcf298d40ca342c300d002c771511a5a', '821b19c549a4d89cb248ac3bc49aa88efcf298d40ca342c300d002c771511a5a', NULL, 'والخيل والبغال والحمير لتركبوها وزينه ويخلق ما لا تعلمون', 14, 27, 107, 1, 3, 268, false, NULL),
    (1910, 'tanzil-uthmani-v1.1', 16, 9, 'وَعَلَى ٱللَّهِ قَصْدُ ٱلسَّبِيلِ وَمِنْهَا جَآئِرٌ وَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', '94fcbfb12bccda75a254e242c07082308b42c0bb89bf8fa12158fb26ff2746e1', 'وَعَلَى ٱللَّهِ قَصْدُ ٱلسَّبِيلِ وَمِنْهَا جَآئِرٌ وَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', '94fcbfb12bccda75a254e242c07082308b42c0bb89bf8fa12158fb26ff2746e1', '94fcbfb12bccda75a254e242c07082308b42c0bb89bf8fa12158fb26ff2746e1', NULL, 'وعلي الله قصد السبيل ومنها جائر ولو شاء لهديكم اجمعين', 14, 27, 107, 1, 3, 268, false, NULL),
    (1911, 'tanzil-uthmani-v1.1', 16, 10, 'هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً لَّكُم مِّنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ فِيهِ تُسِيمُونَ', 'b7eb28f135c2c2598f50fd7c8a418b12f878c9460f10f7730a7a85a2ce72f54a', 'هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً لَّكُم مِّنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ فِيهِ تُسِيمُونَ', 'b7eb28f135c2c2598f50fd7c8a418b12f878c9460f10f7730a7a85a2ce72f54a', 'b7eb28f135c2c2598f50fd7c8a418b12f878c9460f10f7730a7a85a2ce72f54a', NULL, 'هو الذي انزل من السماء ماء لكم منه شراب ومنه شجر فيه تسيمون', 14, 27, 107, 1, 3, 268, false, NULL),
    (1912, 'tanzil-uthmani-v1.1', 16, 11, 'يُنۢبِتُ لَكُم بِهِ ٱلزَّرْعَ وَٱلزَّيْتُونَ وَٱلنَّخِيلَ وَٱلْأَعْنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', '1e55af68056779f946ef49b48f12965b37e55c7a912744f2e05e23e728591409', 'يُنۢبِتُ لَكُم بِهِ ٱلزَّرْعَ وَٱلزَّيْتُونَ وَٱلنَّخِيلَ وَٱلْأَعْنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', '1e55af68056779f946ef49b48f12965b37e55c7a912744f2e05e23e728591409', '1e55af68056779f946ef49b48f12965b37e55c7a912744f2e05e23e728591409', NULL, 'ينبت لكم به الزرع والزيتون والنخيل والاعنب ومن كل الثمرت ان في ذلك لايه لقوم يتفكرون', 14, 27, 107, 1, 3, 268, false, NULL),
    (1913, 'tanzil-uthmani-v1.1', 16, 12, 'وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومُ مُسَخَّرَٰتٌۢ بِأَمْرِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'd56ad6e4c800f46331c67f56de64c3f4a5592e152617950223d846ab82d4157a', 'وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومُ مُسَخَّرَٰتٌۢ بِأَمْرِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'd56ad6e4c800f46331c67f56de64c3f4a5592e152617950223d846ab82d4157a', 'd56ad6e4c800f46331c67f56de64c3f4a5592e152617950223d846ab82d4157a', NULL, 'وسخر لكم اليل والنهار والشمس والقمر والنجوم مسخرت بامره ان في ذلك لايت لقوم يعقلون', 14, 27, 107, 1, 3, 268, false, NULL),
    (1914, 'tanzil-uthmani-v1.1', 16, 13, 'وَمَا ذَرَأَ لَكُمْ فِى ٱلْأَرْضِ مُخْتَلِفًا أَلْوَٰنُهُۥٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَذَّكَّرُونَ', 'a181691c4cc518c98b5b161ed49f7d5ae84cd1c8ba7851e1545f4bd20795cc06', 'وَمَا ذَرَأَ لَكُمْ فِى ٱلْأَرْضِ مُخْتَلِفًا أَلْوَٰنُهُۥٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَذَّكَّرُونَ', 'a181691c4cc518c98b5b161ed49f7d5ae84cd1c8ba7851e1545f4bd20795cc06', 'a181691c4cc518c98b5b161ed49f7d5ae84cd1c8ba7851e1545f4bd20795cc06', NULL, 'وما ذرا لكم في الارض مختلفا الونه ان في ذلك لايه لقوم يذكرون', 14, 27, 107, 1, 3, 268, false, NULL),
    (1915, 'tanzil-uthmani-v1.1', 16, 14, 'وَهُوَ ٱلَّذِى سَخَّرَ ٱلْبَحْرَ لِتَأْكُلُوا۟ مِنْهُ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُوا۟ مِنْهُ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'd64dca3b260e3fa76bdf926f844df1452758b9b3ed0f2ad758db0c146c3cd839', 'وَهُوَ ٱلَّذِى سَخَّرَ ٱلْبَحْرَ لِتَأْكُلُوا۟ مِنْهُ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُوا۟ مِنْهُ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'd64dca3b260e3fa76bdf926f844df1452758b9b3ed0f2ad758db0c146c3cd839', 'd64dca3b260e3fa76bdf926f844df1452758b9b3ed0f2ad758db0c146c3cd839', NULL, 'وهو الذي سخر البحر لتاكلوا منه لحما طريا وتستخرجوا منه حليه تلبسونها وتري الفلك مواخر فيه ولتبتغوا من فضله ولعلكم تشكرون', 14, 27, 107, 1, 3, 268, false, NULL),
    (1916, 'tanzil-uthmani-v1.1', 16, 15, 'وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَأَنْهَٰرًا وَسُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', '6ed8efc3b9cbb9bbf7d6dd99df60d94a26004c9506bde055d031210e0d477a15', 'وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَأَنْهَٰرًا وَسُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', '6ed8efc3b9cbb9bbf7d6dd99df60d94a26004c9506bde055d031210e0d477a15', '6ed8efc3b9cbb9bbf7d6dd99df60d94a26004c9506bde055d031210e0d477a15', NULL, 'والقي في الارض روسي ان تميد بكم وانهرا وسبلا لعلكم تهتدون', 14, 27, 107, 1, 3, 269, false, NULL),
    (1917, 'tanzil-uthmani-v1.1', 16, 16, 'وَعَلَٰمَٰتٍ وَبِٱلنَّجْمِ هُمْ يَهْتَدُونَ', '8c4642f8c211081fd54dd011c765d986f4c5ecc92886a86184c5e4035912ad1c', 'وَعَلَٰمَٰتٍ وَبِٱلنَّجْمِ هُمْ يَهْتَدُونَ', '8c4642f8c211081fd54dd011c765d986f4c5ecc92886a86184c5e4035912ad1c', '8c4642f8c211081fd54dd011c765d986f4c5ecc92886a86184c5e4035912ad1c', NULL, 'وعلمت وبالنجم هم يهتدون', 14, 27, 107, 1, 3, 269, false, NULL),
    (1918, 'tanzil-uthmani-v1.1', 16, 17, 'أَفَمَن يَخْلُقُ كَمَن لَّا يَخْلُقُ أَفَلَا تَذَكَّرُونَ', 'e7eb730af1ce2658bae2ef6d856aa55d3706ab15a32594e9fea0030815861341', 'أَفَمَن يَخْلُقُ كَمَن لَّا يَخْلُقُ أَفَلَا تَذَكَّرُونَ', 'e7eb730af1ce2658bae2ef6d856aa55d3706ab15a32594e9fea0030815861341', 'e7eb730af1ce2658bae2ef6d856aa55d3706ab15a32594e9fea0030815861341', NULL, 'افمن يخلق كمن لا يخلق افلا تذكرون', 14, 27, 107, 1, 3, 269, false, NULL),
    (1919, 'tanzil-uthmani-v1.1', 16, 18, 'وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ إِنَّ ٱللَّهَ لَغَفُورٌ رَّحِيمٌ', 'c3e3561524873287640bea47cefc8d2f57443c64f870dbaafb2d792b84aeca78', 'وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ إِنَّ ٱللَّهَ لَغَفُورٌ رَّحِيمٌ', 'c3e3561524873287640bea47cefc8d2f57443c64f870dbaafb2d792b84aeca78', 'c3e3561524873287640bea47cefc8d2f57443c64f870dbaafb2d792b84aeca78', NULL, 'وان تعدوا نعمه الله لا تحصوها ان الله لغفور رحيم', 14, 27, 107, 1, 3, 269, false, NULL),
    (1920, 'tanzil-uthmani-v1.1', 16, 19, 'وَٱللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ', 'a7f5453ae692abb2795940d72db8a3c1579ab460838db55ff6348698b428ee9d', 'وَٱللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ', 'a7f5453ae692abb2795940d72db8a3c1579ab460838db55ff6348698b428ee9d', 'a7f5453ae692abb2795940d72db8a3c1579ab460838db55ff6348698b428ee9d', NULL, 'والله يعلم ما تسرون وما تعلنون', 14, 27, 107, 1, 3, 269, false, NULL),
    (1921, 'tanzil-uthmani-v1.1', 16, 20, 'وَٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ لَا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ', '5a1377ce1423b3b5d69bbb61dfddc7df3498510c4552ca61d03643dd13b0a61f', 'وَٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ لَا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ', '5a1377ce1423b3b5d69bbb61dfddc7df3498510c4552ca61d03643dd13b0a61f', '5a1377ce1423b3b5d69bbb61dfddc7df3498510c4552ca61d03643dd13b0a61f', NULL, 'والذين يدعون من دون الله لا يخلقون شيا وهم يخلقون', 14, 27, 107, 1, 3, 269, false, NULL),
    (1922, 'tanzil-uthmani-v1.1', 16, 21, 'أَمْوَٰتٌ غَيْرُ أَحْيَآءٍ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'f6ad60c1038b4099877903e379669972a5fe27b65f890a7b637803036360b900', 'أَمْوَٰتٌ غَيْرُ أَحْيَآءٍ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'f6ad60c1038b4099877903e379669972a5fe27b65f890a7b637803036360b900', 'f6ad60c1038b4099877903e379669972a5fe27b65f890a7b637803036360b900', NULL, 'اموت غير احياء وما يشعرون ايان يبعثون', 14, 27, 107, 1, 3, 269, false, NULL),
    (1923, 'tanzil-uthmani-v1.1', 16, 22, 'إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ قُلُوبُهُم مُّنكِرَةٌ وَهُم مُّسْتَكْبِرُونَ', '062ce3285686dde245a3242854883c6f5f468f1e37318aa4a8ac5963586c93ff', 'إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ قُلُوبُهُم مُّنكِرَةٌ وَهُم مُّسْتَكْبِرُونَ', '062ce3285686dde245a3242854883c6f5f468f1e37318aa4a8ac5963586c93ff', '062ce3285686dde245a3242854883c6f5f468f1e37318aa4a8ac5963586c93ff', NULL, 'الهكم اله وحد فالذين لا يؤمنون بالاخره قلوبهم منكره وهم مستكبرون', 14, 27, 107, 1, 3, 269, false, NULL),
    (1924, 'tanzil-uthmani-v1.1', 16, 23, 'لَا جَرَمَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْتَكْبِرِينَ', '43ffd7bfbdfd6fd25363b444b636de66ffecc9ec33d92b0ef7b9c26d1e4d733c', 'لَا جَرَمَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْتَكْبِرِينَ', '43ffd7bfbdfd6fd25363b444b636de66ffecc9ec33d92b0ef7b9c26d1e4d733c', '43ffd7bfbdfd6fd25363b444b636de66ffecc9ec33d92b0ef7b9c26d1e4d733c', NULL, 'لا جرم ان الله يعلم ما يسرون وما يعلنون انه لا يحب المستكبرين', 14, 27, 107, 1, 3, 269, false, NULL),
    (1925, 'tanzil-uthmani-v1.1', 16, 24, 'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمْ قَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'cc7a798baa7b9ef55dee0e48d1d5e225c3a75bcba6fffc233664100306a1dfd9', 'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمْ قَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 'cc7a798baa7b9ef55dee0e48d1d5e225c3a75bcba6fffc233664100306a1dfd9', 'cc7a798baa7b9ef55dee0e48d1d5e225c3a75bcba6fffc233664100306a1dfd9', NULL, 'واذا قيل لهم ماذا انزل ربكم قالوا اسطير الاولين', 14, 27, 107, 1, 3, 269, false, NULL),
    (1926, 'tanzil-uthmani-v1.1', 16, 25, 'لِيَحْمِلُوٓا۟ أَوْزَارَهُمْ كَامِلَةً يَوْمَ ٱلْقِيَٰمَةِ وَمِنْ أَوْزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ أَلَا سَآءَ مَا يَزِرُونَ', 'f1a653a851a93d9bd44aeaf42ff7617925ad62abe157dc0b54a96cdde8cbeb8a', 'لِيَحْمِلُوٓا۟ أَوْزَارَهُمْ كَامِلَةً يَوْمَ ٱلْقِيَٰمَةِ وَمِنْ أَوْزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ أَلَا سَآءَ مَا يَزِرُونَ', 'f1a653a851a93d9bd44aeaf42ff7617925ad62abe157dc0b54a96cdde8cbeb8a', 'f1a653a851a93d9bd44aeaf42ff7617925ad62abe157dc0b54a96cdde8cbeb8a', NULL, 'ليحملوا اوزارهم كامله يوم القيمه ومن اوزار الذين يضلونهم بغير علم الا ساء ما يزرون', 14, 27, 107, 1, 3, 269, false, NULL),
    (1927, 'tanzil-uthmani-v1.1', 16, 26, 'قَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَى ٱللَّهُ بُنْيَٰنَهُم مِّنَ ٱلْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ ٱلسَّقْفُ مِن فَوْقِهِمْ وَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', '4208c07f85784619d9e6a38c427cb2be9ed220eb29433b11dc017e0aee276887', 'قَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَى ٱللَّهُ بُنْيَٰنَهُم مِّنَ ٱلْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ ٱلسَّقْفُ مِن فَوْقِهِمْ وَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', '4208c07f85784619d9e6a38c427cb2be9ed220eb29433b11dc017e0aee276887', '4208c07f85784619d9e6a38c427cb2be9ed220eb29433b11dc017e0aee276887', NULL, 'قد مكر الذين من قبلهم فاتي الله بنينهم من القواعد فخر عليهم السقف من فوقهم واتيهم العذاب من حيث لا يشعرون', 14, 27, 107, 1, 3, 269, false, NULL),
    (1928, 'tanzil-uthmani-v1.1', 16, 27, 'ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تُشَٰٓقُّونَ فِيهِمْ قَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ إِنَّ ٱلْخِزْىَ ٱلْيَوْمَ وَٱلسُّوٓءَ عَلَى ٱلْكَٰفِرِينَ', '95efe1c642b3cd0006f5280fce3bf9539bbd9f586c4d9cac7f49d22487a03a83', 'ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تُشَٰٓقُّونَ فِيهِمْ قَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ إِنَّ ٱلْخِزْىَ ٱلْيَوْمَ وَٱلسُّوٓءَ عَلَى ٱلْكَٰفِرِينَ', '95efe1c642b3cd0006f5280fce3bf9539bbd9f586c4d9cac7f49d22487a03a83', '95efe1c642b3cd0006f5280fce3bf9539bbd9f586c4d9cac7f49d22487a03a83', NULL, 'ثم يوم القيمه يخزيهم ويقول اين شركاءي الذين كنتم تشقون فيهم قال الذين اوتوا العلم ان الخزي اليوم والسوء علي الكفرين', 14, 27, 107, 1, 3, 270, false, NULL),
    (1929, 'tanzil-uthmani-v1.1', 16, 28, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ فَأَلْقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوٓءٍۭ بَلَىٰٓ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا كُنتُمْ تَعْمَلُونَ', '614e743392f6c99eb0283e5ea2ad72a84f966d90ed5e144ed13fa4429784930b', 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ فَأَلْقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوٓءٍۭ بَلَىٰٓ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا كُنتُمْ تَعْمَلُونَ', '614e743392f6c99eb0283e5ea2ad72a84f966d90ed5e144ed13fa4429784930b', '614e743392f6c99eb0283e5ea2ad72a84f966d90ed5e144ed13fa4429784930b', NULL, 'الذين تتوفيهم الملئكه ظالمي انفسهم فالقوا السلم ما كنا نعمل من سوء بلي ان الله عليم بما كنتم تعملون', 14, 27, 107, 1, 3, 270, false, NULL),
    (1930, 'tanzil-uthmani-v1.1', 16, 29, 'فَٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'e7757fb434c86613c3f8747e7f6ae8cbff0c9f56d8412d456844650bd5996ab2', 'فَٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'e7757fb434c86613c3f8747e7f6ae8cbff0c9f56d8412d456844650bd5996ab2', 'e7757fb434c86613c3f8747e7f6ae8cbff0c9f56d8412d456844650bd5996ab2', NULL, 'فادخلوا ابوب جهنم خلدين فيها فلبئس مثوي المتكبرين', 14, 27, 107, 1, 3, 270, false, NULL),
    (1931, 'tanzil-uthmani-v1.1', 16, 30, 'وَقِيلَ لِلَّذِينَ ٱتَّقَوْا۟ مَاذَآ أَنزَلَ رَبُّكُمْ قَالُوا۟ خَيْرًا لِّلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ وَلَنِعْمَ دَارُ ٱلْمُتَّقِينَ', 'e9ad8313dc986bb9b1750304d9ee92711bb4de56b24f93167952b5315ccfc793', 'وَقِيلَ لِلَّذِينَ ٱتَّقَوْا۟ مَاذَآ أَنزَلَ رَبُّكُمْ قَالُوا۟ خَيْرًا لِّلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌ وَلَدَارُ ٱلْـَٔاخِرَةِ خَيْرٌ وَلَنِعْمَ دَارُ ٱلْمُتَّقِينَ', 'e9ad8313dc986bb9b1750304d9ee92711bb4de56b24f93167952b5315ccfc793', 'e9ad8313dc986bb9b1750304d9ee92711bb4de56b24f93167952b5315ccfc793', NULL, 'وقيل للذين اتقوا ماذا انزل ربكم قالوا خيرا للذين احسنوا في هذه الدنيا حسنه ولدار الاخره خير ولنعم دار المتقين', 14, 27, 108, 1, 3, 270, false, NULL),
    (1932, 'tanzil-uthmani-v1.1', 16, 31, 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُمْ فِيهَا مَا يَشَآءُونَ كَذَٰلِكَ يَجْزِى ٱللَّهُ ٱلْمُتَّقِينَ', 'bda5e1477dfdafb1232cb9ba4b08d5785e5b12e96684536935dc810845ea86fd', 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُمْ فِيهَا مَا يَشَآءُونَ كَذَٰلِكَ يَجْزِى ٱللَّهُ ٱلْمُتَّقِينَ', 'bda5e1477dfdafb1232cb9ba4b08d5785e5b12e96684536935dc810845ea86fd', 'bda5e1477dfdafb1232cb9ba4b08d5785e5b12e96684536935dc810845ea86fd', NULL, 'جنت عدن يدخلونها تجري من تحتها الانهر لهم فيها ما يشاءون كذلك يجزي الله المتقين', 14, 27, 108, 1, 3, 270, false, NULL),
    (1933, 'tanzil-uthmani-v1.1', 16, 32, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيْكُمُ ٱدْخُلُوا۟ ٱلْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ', 'ac2ea0efa2e3c36dd6e1b90980e63712f75357c8130bbc00df865a3ab040744c', 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيْكُمُ ٱدْخُلُوا۟ ٱلْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ', 'ac2ea0efa2e3c36dd6e1b90980e63712f75357c8130bbc00df865a3ab040744c', 'ac2ea0efa2e3c36dd6e1b90980e63712f75357c8130bbc00df865a3ab040744c', NULL, 'الذين تتوفيهم الملئكه طيبين يقولون سلم عليكم ادخلوا الجنه بما كنتم تعملون', 14, 27, 108, 1, 3, 270, false, NULL),
    (1934, 'tanzil-uthmani-v1.1', 16, 33, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ أَمْرُ رَبِّكَ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '8fa490860ddab543480068175f02e727c9c2fd7e86d87d2e32b048a45789096e', 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ أَمْرُ رَبِّكَ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '8fa490860ddab543480068175f02e727c9c2fd7e86d87d2e32b048a45789096e', '8fa490860ddab543480068175f02e727c9c2fd7e86d87d2e32b048a45789096e', NULL, 'هل ينظرون الا ان تاتيهم الملئكه او ياتي امر ربك كذلك فعل الذين من قبلهم وما ظلمهم الله ولكن كانوا انفسهم يظلمون', 14, 27, 108, 1, 3, 270, false, NULL),
    (1935, 'tanzil-uthmani-v1.1', 16, 34, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '277161dbb858e3285cf71efb69f85a479efd9ab0e005422a98cf94ecf0dee6fb', 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '277161dbb858e3285cf71efb69f85a479efd9ab0e005422a98cf94ecf0dee6fb', '277161dbb858e3285cf71efb69f85a479efd9ab0e005422a98cf94ecf0dee6fb', NULL, 'فاصابهم سيات ما عملوا وحاق بهم ما كانوا به يستهزءون', 14, 27, 108, 1, 3, 270, false, NULL),
    (1936, 'tanzil-uthmani-v1.1', 16, 35, 'وَقَالَ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَا عَبَدْنَا مِن دُونِهِۦ مِن شَىْءٍ نَّحْنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِۦ مِن شَىْءٍ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ فَهَلْ عَلَى ٱلرُّسُلِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'f956c2029e29a3d17f0a5fc9e67b60446a02475b97ddde906bbeb85a4d854d45', 'وَقَالَ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَا عَبَدْنَا مِن دُونِهِۦ مِن شَىْءٍ نَّحْنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِۦ مِن شَىْءٍ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ فَهَلْ عَلَى ٱلرُّسُلِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'f956c2029e29a3d17f0a5fc9e67b60446a02475b97ddde906bbeb85a4d854d45', 'f956c2029e29a3d17f0a5fc9e67b60446a02475b97ddde906bbeb85a4d854d45', NULL, 'وقال الذين اشركوا لو شاء الله ما عبدنا من دونه من شيء نحن ولا ءاباؤنا ولا حرمنا من دونه من شيء كذلك فعل الذين من قبلهم فهل علي الرسل الا البلغ المبين', 14, 27, 108, 1, 3, 271, false, NULL),
    (1937, 'tanzil-uthmani-v1.1', 16, 36, 'وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّٰغُوتَ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَٰلَةُ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', '098caf70f676584d3f2ed2d349799b4559215dc10084f2beabffaa792374e01b', 'وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّٰغُوتَ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَٰلَةُ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', '098caf70f676584d3f2ed2d349799b4559215dc10084f2beabffaa792374e01b', '098caf70f676584d3f2ed2d349799b4559215dc10084f2beabffaa792374e01b', NULL, 'ولقد بعثنا في كل امه رسولا ان اعبدوا الله واجتنبوا الطغوت فمنهم من هدي الله ومنهم من حقت عليه الضلله فسيروا في الارض فانظروا كيف كان عقبه المكذبين', 14, 27, 108, 1, 3, 271, false, NULL),
    (1938, 'tanzil-uthmani-v1.1', 16, 37, 'إِن تَحْرِصْ عَلَىٰ هُدَىٰهُمْ فَإِنَّ ٱللَّهَ لَا يَهْدِى مَن يُضِلُّ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'a2e863701b05eb04cb347bb9948c4e197e4832e307a4105c6bcbea80f5036b09', 'إِن تَحْرِصْ عَلَىٰ هُدَىٰهُمْ فَإِنَّ ٱللَّهَ لَا يَهْدِى مَن يُضِلُّ وَمَا لَهُم مِّن نَّٰصِرِينَ', 'a2e863701b05eb04cb347bb9948c4e197e4832e307a4105c6bcbea80f5036b09', 'a2e863701b05eb04cb347bb9948c4e197e4832e307a4105c6bcbea80f5036b09', NULL, 'ان تحرص علي هديهم فان الله لا يهدي من يضل وما لهم من نصرين', 14, 27, 108, 1, 3, 271, false, NULL),
    (1939, 'tanzil-uthmani-v1.1', 16, 38, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَا يَبْعَثُ ٱللَّهُ مَن يَمُوتُ بَلَىٰ وَعْدًا عَلَيْهِ حَقًّا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'c529b65461ec9844e848fed4c5b855e33a724930c7fcdf818d4919754cb7678a', 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَا يَبْعَثُ ٱللَّهُ مَن يَمُوتُ بَلَىٰ وَعْدًا عَلَيْهِ حَقًّا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'c529b65461ec9844e848fed4c5b855e33a724930c7fcdf818d4919754cb7678a', 'c529b65461ec9844e848fed4c5b855e33a724930c7fcdf818d4919754cb7678a', NULL, 'واقسموا بالله جهد ايمنهم لا يبعث الله من يموت بلي وعدا عليه حقا ولكن اكثر الناس لا يعلمون', 14, 27, 108, 1, 3, 271, false, NULL),
    (1940, 'tanzil-uthmani-v1.1', 16, 39, 'لِيُبَيِّنَ لَهُمُ ٱلَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ كَانُوا۟ كَٰذِبِينَ', '5ed028963e815dafdead0d6f66a4047ab7394ba0e3b59740f58dc43a83a483d1', 'لِيُبَيِّنَ لَهُمُ ٱلَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ كَانُوا۟ كَٰذِبِينَ', '5ed028963e815dafdead0d6f66a4047ab7394ba0e3b59740f58dc43a83a483d1', '5ed028963e815dafdead0d6f66a4047ab7394ba0e3b59740f58dc43a83a483d1', NULL, 'ليبين لهم الذي يختلفون فيه وليعلم الذين كفروا انهم كانوا كذبين', 14, 27, 108, 1, 3, 271, false, NULL),
    (1941, 'tanzil-uthmani-v1.1', 16, 40, 'إِنَّمَا قَوْلُنَا لِشَىْءٍ إِذَآ أَرَدْنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ', '502abb473920e39f26ead2d65ebf793b2e55becf1de9f603b32276778be8c9b2', 'إِنَّمَا قَوْلُنَا لِشَىْءٍ إِذَآ أَرَدْنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ', '502abb473920e39f26ead2d65ebf793b2e55becf1de9f603b32276778be8c9b2', '502abb473920e39f26ead2d65ebf793b2e55becf1de9f603b32276778be8c9b2', NULL, 'انما قولنا لشيء اذا اردنه ان نقول له كن فيكون', 14, 27, 108, 1, 3, 271, false, NULL),
    (1942, 'tanzil-uthmani-v1.1', 16, 41, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمْ فِى ٱلدُّنْيَا حَسَنَةً وَلَأَجْرُ ٱلْـَٔاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', '1b10423f60fbe3c42318df2bde4b52c12dd659a07d0f33297724e16d9d8f69d4', 'وَٱلَّذِينَ هَاجَرُوا۟ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمْ فِى ٱلدُّنْيَا حَسَنَةً وَلَأَجْرُ ٱلْـَٔاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', '1b10423f60fbe3c42318df2bde4b52c12dd659a07d0f33297724e16d9d8f69d4', '1b10423f60fbe3c42318df2bde4b52c12dd659a07d0f33297724e16d9d8f69d4', NULL, 'والذين هاجروا في الله من بعد ما ظلموا لنبوئنهم في الدنيا حسنه ولاجر الاخره اكبر لو كانوا يعلمون', 14, 27, 108, 1, 3, 271, false, NULL),
    (1943, 'tanzil-uthmani-v1.1', 16, 42, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'd389b068ccf2c4beba3e40cb1e20db651a73a21ad02609f9e1989e64fcf00a0e', 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'd389b068ccf2c4beba3e40cb1e20db651a73a21ad02609f9e1989e64fcf00a0e', 'd389b068ccf2c4beba3e40cb1e20db651a73a21ad02609f9e1989e64fcf00a0e', NULL, 'الذين صبروا وعلي ربهم يتوكلون', 14, 27, 108, 1, 3, 271, false, NULL),
    (1944, 'tanzil-uthmani-v1.1', 16, 43, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 'fe9dd2498a6f498a3fbe45814efcf37edb53670c07a922a2af17942dd071ba44', 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 'fe9dd2498a6f498a3fbe45814efcf37edb53670c07a922a2af17942dd071ba44', 'fe9dd2498a6f498a3fbe45814efcf37edb53670c07a922a2af17942dd071ba44', NULL, 'وما ارسلنا من قبلك الا رجالا نوحي اليهم فسلوا اهل الذكر ان كنتم لا تعلمون', 14, 27, 108, 1, 3, 272, false, NULL),
    (1945, 'tanzil-uthmani-v1.1', 16, 44, 'بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', '027f94746d0302334d7ec80e5dbed0f53a337868b2ae09fbfe8c3ac41e37b1df', 'بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', '027f94746d0302334d7ec80e5dbed0f53a337868b2ae09fbfe8c3ac41e37b1df', '027f94746d0302334d7ec80e5dbed0f53a337868b2ae09fbfe8c3ac41e37b1df', NULL, 'بالبينت والزبر وانزلنا اليك الذكر لتبين للناس ما نزل اليهم ولعلهم يتفكرون', 14, 27, 108, 1, 3, 272, false, NULL),
    (1946, 'tanzil-uthmani-v1.1', 16, 45, 'أَفَأَمِنَ ٱلَّذِينَ مَكَرُوا۟ ٱلسَّيِّـَٔاتِ أَن يَخْسِفَ ٱللَّهُ بِهِمُ ٱلْأَرْضَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', '0d2d80778f6a5686e2636fabd684045cd4c9a99dc7afaf35eec9e52f9debb251', 'أَفَأَمِنَ ٱلَّذِينَ مَكَرُوا۟ ٱلسَّيِّـَٔاتِ أَن يَخْسِفَ ٱللَّهُ بِهِمُ ٱلْأَرْضَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', '0d2d80778f6a5686e2636fabd684045cd4c9a99dc7afaf35eec9e52f9debb251', '0d2d80778f6a5686e2636fabd684045cd4c9a99dc7afaf35eec9e52f9debb251', NULL, 'افامن الذين مكروا السيات ان يخسف الله بهم الارض او ياتيهم العذاب من حيث لا يشعرون', 14, 27, 108, 1, 3, 272, false, NULL),
    (1947, 'tanzil-uthmani-v1.1', 16, 46, 'أَوْ يَأْخُذَهُمْ فِى تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ', '394c07a49396d9e587e23f9d29635d2891d1b9beffaa1fe0466fd3bfebb38e72', 'أَوْ يَأْخُذَهُمْ فِى تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ', '394c07a49396d9e587e23f9d29635d2891d1b9beffaa1fe0466fd3bfebb38e72', '394c07a49396d9e587e23f9d29635d2891d1b9beffaa1fe0466fd3bfebb38e72', NULL, 'او ياخذهم في تقلبهم فما هم بمعجزين', 14, 27, 108, 1, 3, 272, false, NULL),
    (1948, 'tanzil-uthmani-v1.1', 16, 47, 'أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍ فَإِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', 'cbf817c95eeb0e65f92a32c2ff0d509a588dbe7d1465af78e4200b08e1249bfe', 'أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍ فَإِنَّ رَبَّكُمْ لَرَءُوفٌ رَّحِيمٌ', 'cbf817c95eeb0e65f92a32c2ff0d509a588dbe7d1465af78e4200b08e1249bfe', 'cbf817c95eeb0e65f92a32c2ff0d509a588dbe7d1465af78e4200b08e1249bfe', NULL, 'او ياخذهم علي تخوف فان ربكم لرءوف رحيم', 14, 27, 108, 1, 3, 272, false, NULL),
    (1949, 'tanzil-uthmani-v1.1', 16, 48, 'أَوَلَمْ يَرَوْا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَىْءٍ يَتَفَيَّؤُا۟ ظِلَٰلُهُۥ عَنِ ٱلْيَمِينِ وَٱلشَّمَآئِلِ سُجَّدًا لِّلَّهِ وَهُمْ دَٰخِرُونَ', 'a51f4755a25a5881ebc1fe79e2b1dfa563f478469d12fad1f96a3d891626cbc3', 'أَوَلَمْ يَرَوْا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَىْءٍ يَتَفَيَّؤُا۟ ظِلَٰلُهُۥ عَنِ ٱلْيَمِينِ وَٱلشَّمَآئِلِ سُجَّدًا لِّلَّهِ وَهُمْ دَٰخِرُونَ', 'a51f4755a25a5881ebc1fe79e2b1dfa563f478469d12fad1f96a3d891626cbc3', 'a51f4755a25a5881ebc1fe79e2b1dfa563f478469d12fad1f96a3d891626cbc3', NULL, 'اولم يروا الي ما خلق الله من شيء يتفيؤا ظلله عن اليمين والشمائل سجدا لله وهم دخرون', 14, 27, 108, 1, 3, 272, false, NULL),
    (1950, 'tanzil-uthmani-v1.1', 16, 49, 'وَلِلَّهِ يَسْجُدُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مِن دَآبَّةٍ وَٱلْمَلَٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', '7046df4dd7c499e0abcb4801e33c2d009e9f16f30c774011ca3f2aef83297fab', 'وَلِلَّهِ يَسْجُدُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مِن دَآبَّةٍ وَٱلْمَلَٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', '7046df4dd7c499e0abcb4801e33c2d009e9f16f30c774011ca3f2aef83297fab', '7046df4dd7c499e0abcb4801e33c2d009e9f16f30c774011ca3f2aef83297fab', NULL, 'ولله يسجد ما في السموت وما في الارض من دابه والملئكه وهم لا يستكبرون', 14, 27, 108, 1, 3, 272, false, NULL),
    (1951, 'tanzil-uthmani-v1.1', 16, 50, 'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 'a4d50de1df8dee0bb84ca7715fad226aedbd4eceedffe598eb7f7eb5912cd9e8', 'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 'a4d50de1df8dee0bb84ca7715fad226aedbd4eceedffe598eb7f7eb5912cd9e8', 'a4d50de1df8dee0bb84ca7715fad226aedbd4eceedffe598eb7f7eb5912cd9e8', NULL, 'يخافون ربهم من فوقهم ويفعلون ما يؤمرون', 14, 27, 108, 1, 3, 272, true, 'recommended'),
    (1952, 'tanzil-uthmani-v1.1', 16, 51, 'وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓا۟ إِلَٰهَيْنِ ٱثْنَيْنِ إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ فَإِيَّٰىَ فَٱرْهَبُونِ', 'ac07c1f7f9996de44ac28a226b704e560646e014045ad49f23c155b284cd23a1', 'وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓا۟ إِلَٰهَيْنِ ٱثْنَيْنِ إِنَّمَا هُوَ إِلَٰهٌ وَٰحِدٌ فَإِيَّٰىَ فَٱرْهَبُونِ', 'ac07c1f7f9996de44ac28a226b704e560646e014045ad49f23c155b284cd23a1', 'ac07c1f7f9996de44ac28a226b704e560646e014045ad49f23c155b284cd23a1', NULL, 'وقال الله لا تتخذوا الهين اثنين انما هو اله وحد فايي فارهبون', 14, 28, 109, 1, 3, 272, false, NULL),
    (1953, 'tanzil-uthmani-v1.1', 16, 52, 'وَلَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَهُ ٱلدِّينُ وَاصِبًا أَفَغَيْرَ ٱللَّهِ تَتَّقُونَ', 'dd850211e93c6fcdd824215ec218447b6d9ab0f6d23685ac5fd810b602b0257d', 'وَلَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَهُ ٱلدِّينُ وَاصِبًا أَفَغَيْرَ ٱللَّهِ تَتَّقُونَ', 'dd850211e93c6fcdd824215ec218447b6d9ab0f6d23685ac5fd810b602b0257d', 'dd850211e93c6fcdd824215ec218447b6d9ab0f6d23685ac5fd810b602b0257d', NULL, 'وله ما في السموت والارض وله الدين واصبا افغير الله تتقون', 14, 28, 109, 1, 3, 272, false, NULL),
    (1954, 'tanzil-uthmani-v1.1', 16, 53, 'وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ ٱللَّهِ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيْهِ تَجْـَٔرُونَ', '8deca3fe911612bc0e5f7074acbf4da743511ed0aed11acd3f1ec381c13e2722', 'وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ ٱللَّهِ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيْهِ تَجْـَٔرُونَ', '8deca3fe911612bc0e5f7074acbf4da743511ed0aed11acd3f1ec381c13e2722', '8deca3fe911612bc0e5f7074acbf4da743511ed0aed11acd3f1ec381c13e2722', NULL, 'وما بكم من نعمه فمن الله ثم اذا مسكم الضر فاليه تجرون', 14, 28, 109, 1, 3, 272, false, NULL),
    (1955, 'tanzil-uthmani-v1.1', 16, 54, 'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمْ إِذَا فَرِيقٌ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ', 'd5e0755f3987671d2590c249b979a21b1cb060f8753154c4b776eabc760bab9e', 'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمْ إِذَا فَرِيقٌ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ', 'd5e0755f3987671d2590c249b979a21b1cb060f8753154c4b776eabc760bab9e', 'd5e0755f3987671d2590c249b979a21b1cb060f8753154c4b776eabc760bab9e', NULL, 'ثم اذا كشف الضر عنكم اذا فريق منكم بربهم يشركون', 14, 28, 109, 1, 3, 272, false, NULL),
    (1956, 'tanzil-uthmani-v1.1', 16, 55, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', 'c716e6d6188d17deecd789f5b9d198811228137208b98db9b6b51328d4c18349', 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', 'c716e6d6188d17deecd789f5b9d198811228137208b98db9b6b51328d4c18349', 'c716e6d6188d17deecd789f5b9d198811228137208b98db9b6b51328d4c18349', NULL, 'ليكفروا بما ءاتينهم فتمتعوا فسوف تعلمون', 14, 28, 109, 1, 3, 273, false, NULL),
    (1957, 'tanzil-uthmani-v1.1', 16, 56, 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا مِّمَّا رَزَقْنَٰهُمْ تَٱللَّهِ لَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ', '0552267ea72cabc15993fa3ca321999434963214eb0e1a7788b859ae48546be9', 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا مِّمَّا رَزَقْنَٰهُمْ تَٱللَّهِ لَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ', '0552267ea72cabc15993fa3ca321999434963214eb0e1a7788b859ae48546be9', '0552267ea72cabc15993fa3ca321999434963214eb0e1a7788b859ae48546be9', NULL, 'ويجعلون لما لا يعلمون نصيبا مما رزقنهم تالله لتسلن عما كنتم تفترون', 14, 28, 109, 1, 3, 273, false, NULL),
    (1958, 'tanzil-uthmani-v1.1', 16, 57, 'وَيَجْعَلُونَ لِلَّهِ ٱلْبَنَٰتِ سُبْحَٰنَهُۥ وَلَهُم مَّا يَشْتَهُونَ', '76d63cc576fa806e429d55d450f3d7fffe0c10834a4169b2d290a718d4f24a73', 'وَيَجْعَلُونَ لِلَّهِ ٱلْبَنَٰتِ سُبْحَٰنَهُۥ وَلَهُم مَّا يَشْتَهُونَ', '76d63cc576fa806e429d55d450f3d7fffe0c10834a4169b2d290a718d4f24a73', '76d63cc576fa806e429d55d450f3d7fffe0c10834a4169b2d290a718d4f24a73', NULL, 'ويجعلون لله البنت سبحنه ولهم ما يشتهون', 14, 28, 109, 1, 3, 273, false, NULL),
    (1959, 'tanzil-uthmani-v1.1', 16, 58, 'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', 'd471ee9206d78ac568a57efc0dc75aa8e35856e2870847f015fe7b6943bc88e5', 'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', 'd471ee9206d78ac568a57efc0dc75aa8e35856e2870847f015fe7b6943bc88e5', 'd471ee9206d78ac568a57efc0dc75aa8e35856e2870847f015fe7b6943bc88e5', NULL, 'واذا بشر احدهم بالانثي ظل وجهه مسودا وهو كظيم', 14, 28, 109, 1, 3, 273, false, NULL),
    (1960, 'tanzil-uthmani-v1.1', 16, 59, 'يَتَوَٰرَىٰ مِنَ ٱلْقَوْمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓ أَيُمْسِكُهُۥ عَلَىٰ هُونٍ أَمْ يَدُسُّهُۥ فِى ٱلتُّرَابِ أَلَا سَآءَ مَا يَحْكُمُونَ', '450dbda2088a875ddafdc715554a8bcdcedbe3815267cd5ef35a02bfe3d43634', 'يَتَوَٰرَىٰ مِنَ ٱلْقَوْمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓ أَيُمْسِكُهُۥ عَلَىٰ هُونٍ أَمْ يَدُسُّهُۥ فِى ٱلتُّرَابِ أَلَا سَآءَ مَا يَحْكُمُونَ', '450dbda2088a875ddafdc715554a8bcdcedbe3815267cd5ef35a02bfe3d43634', '450dbda2088a875ddafdc715554a8bcdcedbe3815267cd5ef35a02bfe3d43634', NULL, 'يتوري من القوم من سوء ما بشر به ايمسكه علي هون ام يدسه في التراب الا ساء ما يحكمون', 14, 28, 109, 1, 3, 273, false, NULL),
    (1961, 'tanzil-uthmani-v1.1', 16, 60, 'لِلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ مَثَلُ ٱلسَّوْءِ وَلِلَّهِ ٱلْمَثَلُ ٱلْأَعْلَىٰ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'c090f437e2f9a1915e6b31916a10190ed5055f30bbaab5ea01b530a3c6a27181', 'لِلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ مَثَلُ ٱلسَّوْءِ وَلِلَّهِ ٱلْمَثَلُ ٱلْأَعْلَىٰ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'c090f437e2f9a1915e6b31916a10190ed5055f30bbaab5ea01b530a3c6a27181', 'c090f437e2f9a1915e6b31916a10190ed5055f30bbaab5ea01b530a3c6a27181', NULL, 'للذين لا يؤمنون بالاخره مثل السوء ولله المثل الاعلي وهو العزيز الحكيم', 14, 28, 109, 1, 3, 273, false, NULL),
    (1962, 'tanzil-uthmani-v1.1', 16, 61, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَـْٔخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', '1043521cb7428f1305c2750453dc54da22b61700b76973eefccc318edb774806', 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَـْٔخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ', '1043521cb7428f1305c2750453dc54da22b61700b76973eefccc318edb774806', '1043521cb7428f1305c2750453dc54da22b61700b76973eefccc318edb774806', NULL, 'ولو يؤاخذ الله الناس بظلمهم ما ترك عليها من دابه ولكن يؤخرهم الي اجل مسمي فاذا جاء اجلهم لا يستخرون ساعه ولا يستقدمون', 14, 28, 109, 1, 3, 273, false, NULL),
    (1963, 'tanzil-uthmani-v1.1', 16, 62, 'وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ ٱلْكَذِبَ أَنَّ لَهُمُ ٱلْحُسْنَىٰ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفْرَطُونَ', 'c47102d6669c4d6caf79940720d010bbc29640441eacc9d185cbc27d677d6fe4', 'وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ ٱلْكَذِبَ أَنَّ لَهُمُ ٱلْحُسْنَىٰ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفْرَطُونَ', 'c47102d6669c4d6caf79940720d010bbc29640441eacc9d185cbc27d677d6fe4', 'c47102d6669c4d6caf79940720d010bbc29640441eacc9d185cbc27d677d6fe4', NULL, 'ويجعلون لله ما يكرهون وتصف السنتهم الكذب ان لهم الحسني لا جرم ان لهم النار وانهم مفرطون', 14, 28, 109, 1, 3, 273, false, NULL),
    (1964, 'tanzil-uthmani-v1.1', 16, 63, 'تَٱللَّهِ لَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَهُوَ وَلِيُّهُمُ ٱلْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'c117ede2ae27df147e2634793f61b65fb5e95358a284d308d1c27e1ba272c95a', 'تَٱللَّهِ لَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَهُوَ وَلِيُّهُمُ ٱلْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'c117ede2ae27df147e2634793f61b65fb5e95358a284d308d1c27e1ba272c95a', 'c117ede2ae27df147e2634793f61b65fb5e95358a284d308d1c27e1ba272c95a', NULL, 'تالله لقد ارسلنا الي امم من قبلك فزين لهم الشيطن اعملهم فهو وليهم اليوم ولهم عذاب اليم', 14, 28, 109, 1, 3, 273, false, NULL),
    (1965, 'tanzil-uthmani-v1.1', 16, 64, 'وَمَآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِى ٱخْتَلَفُوا۟ فِيهِ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', '29a802c73287fee4cda1daee742758795ae38fa46f4c9dcd80ad45d98ca0239d', 'وَمَآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِى ٱخْتَلَفُوا۟ فِيهِ وَهُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ', '29a802c73287fee4cda1daee742758795ae38fa46f4c9dcd80ad45d98ca0239d', '29a802c73287fee4cda1daee742758795ae38fa46f4c9dcd80ad45d98ca0239d', NULL, 'وما انزلنا عليك الكتب الا لتبين لهم الذي اختلفوا فيه وهدي ورحمه لقوم يؤمنون', 14, 28, 109, 1, 3, 273, false, NULL),
    (1966, 'tanzil-uthmani-v1.1', 16, 65, 'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَسْمَعُونَ', 'f0884755ff8aa8d776ef35be9a4f1da0857e06971ec4c5e7c5ab84befc517319', 'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَسْمَعُونَ', 'f0884755ff8aa8d776ef35be9a4f1da0857e06971ec4c5e7c5ab84befc517319', 'f0884755ff8aa8d776ef35be9a4f1da0857e06971ec4c5e7c5ab84befc517319', NULL, 'والله انزل من السماء ماء فاحيا به الارض بعد موتها ان في ذلك لايه لقوم يسمعون', 14, 28, 109, 1, 3, 274, false, NULL),
    (1967, 'tanzil-uthmani-v1.1', 16, 66, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِى بُطُونِهِۦ مِنۢ بَيْنِ فَرْثٍ وَدَمٍ لَّبَنًا خَالِصًا سَآئِغًا لِّلشَّٰرِبِينَ', '858e60612e3bd918abc602f01b98675d7fcd7595fa3cbf369302d855d7020733', 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِى بُطُونِهِۦ مِنۢ بَيْنِ فَرْثٍ وَدَمٍ لَّبَنًا خَالِصًا سَآئِغًا لِّلشَّٰرِبِينَ', '858e60612e3bd918abc602f01b98675d7fcd7595fa3cbf369302d855d7020733', '858e60612e3bd918abc602f01b98675d7fcd7595fa3cbf369302d855d7020733', NULL, 'وان لكم في الانعم لعبره نسقيكم مما في بطونه من بين فرث ودم لبنا خالصا سائغا للشربين', 14, 28, 109, 1, 3, 274, false, NULL),
    (1968, 'tanzil-uthmani-v1.1', 16, 67, 'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلْأَعْنَٰبِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْقِلُونَ', '6d774cd9a012cc5ec42d1defae58de38925615422f4d3828b5497576368fed6d', 'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلْأَعْنَٰبِ تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْقِلُونَ', '6d774cd9a012cc5ec42d1defae58de38925615422f4d3828b5497576368fed6d', '6d774cd9a012cc5ec42d1defae58de38925615422f4d3828b5497576368fed6d', NULL, 'ومن ثمرت النخيل والاعنب تتخذون منه سكرا ورزقا حسنا ان في ذلك لايه لقوم يعقلون', 14, 28, 109, 1, 3, 274, false, NULL),
    (1969, 'tanzil-uthmani-v1.1', 16, 68, 'وَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ', '7ee303fbacf26773428c858896eec57bcc82503276da8293acd62ec471e53647', 'وَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ', '7ee303fbacf26773428c858896eec57bcc82503276da8293acd62ec471e53647', '7ee303fbacf26773428c858896eec57bcc82503276da8293acd62ec471e53647', NULL, 'واوحي ربك الي النحل ان اتخذي من الجبال بيوتا ومن الشجر ومما يعرشون', 14, 28, 109, 1, 3, 274, false, NULL),
    (1970, 'tanzil-uthmani-v1.1', 16, 69, 'ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًا يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَٰنُهُۥ فِيهِ شِفَآءٌ لِّلنَّاسِ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', 'd263c80df104cbb49bfcf9cc87411fd95627d4c8b2235ae7d34a34eac43ef369', 'ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًا يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَٰنُهُۥ فِيهِ شِفَآءٌ لِّلنَّاسِ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ', 'd263c80df104cbb49bfcf9cc87411fd95627d4c8b2235ae7d34a34eac43ef369', 'd263c80df104cbb49bfcf9cc87411fd95627d4c8b2235ae7d34a34eac43ef369', NULL, 'ثم كلي من كل الثمرت فاسلكي سبل ربك ذللا يخرج من بطونها شراب مختلف الونه فيه شفاء للناس ان في ذلك لايه لقوم يتفكرون', 14, 28, 109, 1, 3, 274, false, NULL),
    (1971, 'tanzil-uthmani-v1.1', 16, 70, 'وَٱللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّىٰكُمْ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْـًٔا إِنَّ ٱللَّهَ عَلِيمٌ قَدِيرٌ', 'f4c8917cc7ee3886f402607c8dfb74d734da130ec001e1aeb543f143d356005f', 'وَٱللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّىٰكُمْ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْـًٔا إِنَّ ٱللَّهَ عَلِيمٌ قَدِيرٌ', 'f4c8917cc7ee3886f402607c8dfb74d734da130ec001e1aeb543f143d356005f', 'f4c8917cc7ee3886f402607c8dfb74d734da130ec001e1aeb543f143d356005f', NULL, 'والله خلقكم ثم يتوفيكم ومنكم من يرد الي ارذل العمر لكي لا يعلم بعد علم شيا ان الله عليم قدير', 14, 28, 109, 1, 3, 274, false, NULL),
    (1972, 'tanzil-uthmani-v1.1', 16, 71, 'وَٱللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضٍ فِى ٱلرِّزْقِ فَمَا ٱلَّذِينَ فُضِّلُوا۟ بِرَآدِّى رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَهُمْ فِيهِ سَوَآءٌ أَفَبِنِعْمَةِ ٱللَّهِ يَجْحَدُونَ', '251feea050d127a5dab0670ec159083441234967ae51a9aa66dc14f077f6fcb4', 'وَٱللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضٍ فِى ٱلرِّزْقِ فَمَا ٱلَّذِينَ فُضِّلُوا۟ بِرَآدِّى رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَهُمْ فِيهِ سَوَآءٌ أَفَبِنِعْمَةِ ٱللَّهِ يَجْحَدُونَ', '251feea050d127a5dab0670ec159083441234967ae51a9aa66dc14f077f6fcb4', '251feea050d127a5dab0670ec159083441234967ae51a9aa66dc14f077f6fcb4', NULL, 'والله فضل بعضكم علي بعض في الرزق فما الذين فضلوا برادي رزقهم علي ما ملكت ايمنهم فهم فيه سواء افبنعمه الله يجحدون', 14, 28, 109, 1, 3, 274, false, NULL),
    (1973, 'tanzil-uthmani-v1.1', 16, 72, 'وَٱللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَجَعَلَ لَكُم مِّنْ أَزْوَٰجِكُم بَنِينَ وَحَفَدَةً وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ ٱللَّهِ هُمْ يَكْفُرُونَ', '657832f6f48108aa6514079f3ea591c53df8097f53b7153402bd59f9b098aa83', 'وَٱللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَجَعَلَ لَكُم مِّنْ أَزْوَٰجِكُم بَنِينَ وَحَفَدَةً وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ ٱللَّهِ هُمْ يَكْفُرُونَ', '657832f6f48108aa6514079f3ea591c53df8097f53b7153402bd59f9b098aa83', '657832f6f48108aa6514079f3ea591c53df8097f53b7153402bd59f9b098aa83', NULL, 'والله جعل لكم من انفسكم ازوجا وجعل لكم من ازوجكم بنين وحفده ورزقكم من الطيبت افبالبطل يؤمنون وبنعمت الله هم يكفرون', 14, 28, 109, 1, 3, 274, false, NULL),
    (1974, 'tanzil-uthmani-v1.1', 16, 73, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ شَيْـًٔا وَلَا يَسْتَطِيعُونَ', 'ff961c83beeb86db8cd9556764cf2bc05b855c80b160be386a472dfaef1141e2', 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ شَيْـًٔا وَلَا يَسْتَطِيعُونَ', 'ff961c83beeb86db8cd9556764cf2bc05b855c80b160be386a472dfaef1141e2', 'ff961c83beeb86db8cd9556764cf2bc05b855c80b160be386a472dfaef1141e2', NULL, 'ويعبدون من دون الله ما لا يملك لهم رزقا من السموت والارض شيا ولا يستطيعون', 14, 28, 109, 1, 3, 275, false, NULL),
    (1975, 'tanzil-uthmani-v1.1', 16, 74, 'فَلَا تَضْرِبُوا۟ لِلَّهِ ٱلْأَمْثَالَ إِنَّ ٱللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '0c5380a31260ff9adacddff572bf48f4511cc04d56fd69bd221eec6a1a220ee1', 'فَلَا تَضْرِبُوا۟ لِلَّهِ ٱلْأَمْثَالَ إِنَّ ٱللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '0c5380a31260ff9adacddff572bf48f4511cc04d56fd69bd221eec6a1a220ee1', '0c5380a31260ff9adacddff572bf48f4511cc04d56fd69bd221eec6a1a220ee1', NULL, 'فلا تضربوا لله الامثال ان الله يعلم وانتم لا تعلمون', 14, 28, 109, 1, 3, 275, false, NULL),
    (1976, 'tanzil-uthmani-v1.1', 16, 75, 'ضَرَبَ ٱللَّهُ مَثَلًا عَبْدًا مَّمْلُوكًا لَّا يَقْدِرُ عَلَىٰ شَىْءٍ وَمَن رَّزَقْنَٰهُ مِنَّا رِزْقًا حَسَنًا فَهُوَ يُنفِقُ مِنْهُ سِرًّا وَجَهْرًا هَلْ يَسْتَوُۥنَ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '31f0bbb7ba2bb374d7c122aef042f76d90418f96810452e55bb1d35df8f2beaf', 'ضَرَبَ ٱللَّهُ مَثَلًا عَبْدًا مَّمْلُوكًا لَّا يَقْدِرُ عَلَىٰ شَىْءٍ وَمَن رَّزَقْنَٰهُ مِنَّا رِزْقًا حَسَنًا فَهُوَ يُنفِقُ مِنْهُ سِرًّا وَجَهْرًا هَلْ يَسْتَوُۥنَ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '31f0bbb7ba2bb374d7c122aef042f76d90418f96810452e55bb1d35df8f2beaf', '31f0bbb7ba2bb374d7c122aef042f76d90418f96810452e55bb1d35df8f2beaf', NULL, 'ضرب الله مثلا عبدا مملوكا لا يقدر علي شيء ومن رزقنه منا رزقا حسنا فهو ينفق منه سرا وجهرا هل يستون الحمد لله بل اكثرهم لا يعلمون', 14, 28, 110, 1, 3, 275, false, NULL),
    (1977, 'tanzil-uthmani-v1.1', 16, 76, 'وَضَرَبَ ٱللَّهُ مَثَلًا رَّجُلَيْنِ أَحَدُهُمَآ أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَىْءٍ وَهُوَ كَلٌّ عَلَىٰ مَوْلَىٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ هَلْ يَسْتَوِى هُوَ وَمَن يَأْمُرُ بِٱلْعَدْلِ وَهُوَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'af1d25d1199656c2ab8a4313629d7c477520cc4ea8546fff7bf44a27e797882b', 'وَضَرَبَ ٱللَّهُ مَثَلًا رَّجُلَيْنِ أَحَدُهُمَآ أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَىْءٍ وَهُوَ كَلٌّ عَلَىٰ مَوْلَىٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ هَلْ يَسْتَوِى هُوَ وَمَن يَأْمُرُ بِٱلْعَدْلِ وَهُوَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'af1d25d1199656c2ab8a4313629d7c477520cc4ea8546fff7bf44a27e797882b', 'af1d25d1199656c2ab8a4313629d7c477520cc4ea8546fff7bf44a27e797882b', NULL, 'وضرب الله مثلا رجلين احدهما ابكم لا يقدر علي شيء وهو كل علي موليه اينما يوجهه لا يات بخير هل يستوي هو ومن يامر بالعدل وهو علي صرط مستقيم', 14, 28, 110, 1, 3, 275, false, NULL),
    (1978, 'tanzil-uthmani-v1.1', 16, 77, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَآ أَمْرُ ٱلسَّاعَةِ إِلَّا كَلَمْحِ ٱلْبَصَرِ أَوْ هُوَ أَقْرَبُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '358ba1c14a266244064ee6a9d3586eb74bd91d0be81c1db2ed9c6d76e6425353', 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَآ أَمْرُ ٱلسَّاعَةِ إِلَّا كَلَمْحِ ٱلْبَصَرِ أَوْ هُوَ أَقْرَبُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '358ba1c14a266244064ee6a9d3586eb74bd91d0be81c1db2ed9c6d76e6425353', '358ba1c14a266244064ee6a9d3586eb74bd91d0be81c1db2ed9c6d76e6425353', NULL, 'ولله غيب السموت والارض وما امر الساعه الا كلمح البصر او هو اقرب ان الله علي كل شيء قدير', 14, 28, 110, 1, 3, 275, false, NULL),
    (1979, 'tanzil-uthmani-v1.1', 16, 78, 'وَٱللَّهُ أَخْرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمْ لَا تَعْلَمُونَ شَيْـًٔا وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ لَعَلَّكُمْ تَشْكُرُونَ', 'fd8068983735730a1491b5cef7bc210b5c662f1b0527479508fa582af2e8ffa2', 'وَٱللَّهُ أَخْرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمْ لَا تَعْلَمُونَ شَيْـًٔا وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ لَعَلَّكُمْ تَشْكُرُونَ', 'fd8068983735730a1491b5cef7bc210b5c662f1b0527479508fa582af2e8ffa2', 'fd8068983735730a1491b5cef7bc210b5c662f1b0527479508fa582af2e8ffa2', NULL, 'والله اخرجكم من بطون امهتكم لا تعلمون شيا وجعل لكم السمع والابصر والافده لعلكم تشكرون', 14, 28, 110, 1, 3, 275, false, NULL),
    (1980, 'tanzil-uthmani-v1.1', 16, 79, 'أَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ مُسَخَّرَٰتٍ فِى جَوِّ ٱلسَّمَآءِ مَا يُمْسِكُهُنَّ إِلَّا ٱللَّهُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'c0a3234a73d47e28ae005100e1c39d4476140ac24ad94d9ea5f8dd5eb5f77bcd', 'أَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ مُسَخَّرَٰتٍ فِى جَوِّ ٱلسَّمَآءِ مَا يُمْسِكُهُنَّ إِلَّا ٱللَّهُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'c0a3234a73d47e28ae005100e1c39d4476140ac24ad94d9ea5f8dd5eb5f77bcd', 'c0a3234a73d47e28ae005100e1c39d4476140ac24ad94d9ea5f8dd5eb5f77bcd', NULL, 'الم يروا الي الطير مسخرت في جو السماء ما يمسكهن الا الله ان في ذلك لايت لقوم يؤمنون', 14, 28, 110, 1, 3, 275, false, NULL),
    (1981, 'tanzil-uthmani-v1.1', 16, 80, 'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَنًا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلْأَنْعَٰمِ بُيُوتًا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَآ أَثَٰثًا وَمَتَٰعًا إِلَىٰ حِينٍ', 'e6cacbbe0ed968ca0eebd7635d4a4d824c0a1ce338e59387b54bdbdb7783e880', 'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَنًا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلْأَنْعَٰمِ بُيُوتًا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَآ أَثَٰثًا وَمَتَٰعًا إِلَىٰ حِينٍ', 'e6cacbbe0ed968ca0eebd7635d4a4d824c0a1ce338e59387b54bdbdb7783e880', 'e6cacbbe0ed968ca0eebd7635d4a4d824c0a1ce338e59387b54bdbdb7783e880', NULL, 'والله جعل لكم من بيوتكم سكنا وجعل لكم من جلود الانعم بيوتا تستخفونها يوم ظعنكم ويوم اقامتكم ومن اصوافها واوبارها واشعارها اثثا ومتعا الي حين', 14, 28, 110, 1, 3, 276, false, NULL),
    (1982, 'tanzil-uthmani-v1.1', 16, 81, 'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلًا وَجَعَلَ لَكُم مِّنَ ٱلْجِبَالِ أَكْنَٰنًا وَجَعَلَ لَكُمْ سَرَٰبِيلَ تَقِيكُمُ ٱلْحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأْسَكُمْ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ', '97bb10592c88fc1da2111b7b1aaf345e24659b1a0c1ca513bb51d74bd09341f3', 'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلًا وَجَعَلَ لَكُم مِّنَ ٱلْجِبَالِ أَكْنَٰنًا وَجَعَلَ لَكُمْ سَرَٰبِيلَ تَقِيكُمُ ٱلْحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأْسَكُمْ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ', '97bb10592c88fc1da2111b7b1aaf345e24659b1a0c1ca513bb51d74bd09341f3', '97bb10592c88fc1da2111b7b1aaf345e24659b1a0c1ca513bb51d74bd09341f3', NULL, 'والله جعل لكم مما خلق ظللا وجعل لكم من الجبال اكننا وجعل لكم سربيل تقيكم الحر وسربيل تقيكم باسكم كذلك يتم نعمته عليكم لعلكم تسلمون', 14, 28, 110, 1, 3, 276, false, NULL),
    (1983, 'tanzil-uthmani-v1.1', 16, 82, 'فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ ٱلْمُبِينُ', '1af687021189671d13e9040eea71299f534d68baaae3a0f6e149faf4eb975324', 'فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ ٱلْمُبِينُ', '1af687021189671d13e9040eea71299f534d68baaae3a0f6e149faf4eb975324', '1af687021189671d13e9040eea71299f534d68baaae3a0f6e149faf4eb975324', NULL, 'فان تولوا فانما عليك البلغ المبين', 14, 28, 110, 1, 3, 276, false, NULL),
    (1984, 'tanzil-uthmani-v1.1', 16, 83, 'يَعْرِفُونَ نِعْمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ ٱلْكَٰفِرُونَ', 'e00568ee2c0dd5886b22310c35a3527bf167948b6aabe30b69b5856752bb6e64', 'يَعْرِفُونَ نِعْمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ ٱلْكَٰفِرُونَ', 'e00568ee2c0dd5886b22310c35a3527bf167948b6aabe30b69b5856752bb6e64', 'e00568ee2c0dd5886b22310c35a3527bf167948b6aabe30b69b5856752bb6e64', NULL, 'يعرفون نعمت الله ثم ينكرونها واكثرهم الكفرون', 14, 28, 110, 1, 3, 276, false, NULL),
    (1985, 'tanzil-uthmani-v1.1', 16, 84, 'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةٍ شَهِيدًا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا۟ وَلَا هُمْ يُسْتَعْتَبُونَ', '697ddf5866105a8f5bba67f6ecc3f875bb6b286e8d965071ff3a90d5cfc02564', 'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةٍ شَهِيدًا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا۟ وَلَا هُمْ يُسْتَعْتَبُونَ', '697ddf5866105a8f5bba67f6ecc3f875bb6b286e8d965071ff3a90d5cfc02564', '697ddf5866105a8f5bba67f6ecc3f875bb6b286e8d965071ff3a90d5cfc02564', NULL, 'ويوم نبعث من كل امه شهيدا ثم لا يؤذن للذين كفروا ولا هم يستعتبون', 14, 28, 110, 1, 3, 276, false, NULL),
    (1986, 'tanzil-uthmani-v1.1', 16, 85, 'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُوا۟ ٱلْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ', '5aeb597615c7ffee24d22f2623753de05e583256f65b94f1c2b72b463c740fd7', 'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُوا۟ ٱلْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ', '5aeb597615c7ffee24d22f2623753de05e583256f65b94f1c2b72b463c740fd7', '5aeb597615c7ffee24d22f2623753de05e583256f65b94f1c2b72b463c740fd7', NULL, 'واذا رءا الذين ظلموا العذاب فلا يخفف عنهم ولا هم ينظرون', 14, 28, 110, 1, 3, 276, false, NULL),
    (1987, 'tanzil-uthmani-v1.1', 16, 86, 'وَإِذَا رَءَا ٱلَّذِينَ أَشْرَكُوا۟ شُرَكَآءَهُمْ قَالُوا۟ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدْعُوا۟ مِن دُونِكَ فَأَلْقَوْا۟ إِلَيْهِمُ ٱلْقَوْلَ إِنَّكُمْ لَكَٰذِبُونَ', 'a9648b1256c43268d20195832dcc8e7e345c342fb6538d2f44fc0870eb4fc20d', 'وَإِذَا رَءَا ٱلَّذِينَ أَشْرَكُوا۟ شُرَكَآءَهُمْ قَالُوا۟ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدْعُوا۟ مِن دُونِكَ فَأَلْقَوْا۟ إِلَيْهِمُ ٱلْقَوْلَ إِنَّكُمْ لَكَٰذِبُونَ', 'a9648b1256c43268d20195832dcc8e7e345c342fb6538d2f44fc0870eb4fc20d', 'a9648b1256c43268d20195832dcc8e7e345c342fb6538d2f44fc0870eb4fc20d', NULL, 'واذا رءا الذين اشركوا شركاءهم قالوا ربنا هؤلاء شركاؤنا الذين كنا ندعوا من دونك فالقوا اليهم القول انكم لكذبون', 14, 28, 110, 1, 3, 276, false, NULL),
    (1988, 'tanzil-uthmani-v1.1', 16, 87, 'وَأَلْقَوْا۟ إِلَى ٱللَّهِ يَوْمَئِذٍ ٱلسَّلَمَ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '3a20770a1ee07d3abe5986b444d98956e52e10e9e384ee8c7c50bad612c77e21', 'وَأَلْقَوْا۟ إِلَى ٱللَّهِ يَوْمَئِذٍ ٱلسَّلَمَ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', '3a20770a1ee07d3abe5986b444d98956e52e10e9e384ee8c7c50bad612c77e21', '3a20770a1ee07d3abe5986b444d98956e52e10e9e384ee8c7c50bad612c77e21', NULL, 'والقوا الي الله يومئذ السلم وضل عنهم ما كانوا يفترون', 14, 28, 110, 1, 3, 276, false, NULL),
    (1989, 'tanzil-uthmani-v1.1', 16, 88, 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ زِدْنَٰهُمْ عَذَابًا فَوْقَ ٱلْعَذَابِ بِمَا كَانُوا۟ يُفْسِدُونَ', '9935c05bca11368d06cc8d4a7d687f23f0325eea5f5e1cc536bb99ae4d9b9ee0', 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ زِدْنَٰهُمْ عَذَابًا فَوْقَ ٱلْعَذَابِ بِمَا كَانُوا۟ يُفْسِدُونَ', '9935c05bca11368d06cc8d4a7d687f23f0325eea5f5e1cc536bb99ae4d9b9ee0', '9935c05bca11368d06cc8d4a7d687f23f0325eea5f5e1cc536bb99ae4d9b9ee0', NULL, 'الذين كفروا وصدوا عن سبيل الله زدنهم عذابا فوق العذاب بما كانوا يفسدون', 14, 28, 110, 1, 3, 277, false, NULL),
    (1990, 'tanzil-uthmani-v1.1', 16, 89, 'وَيَوْمَ نَبْعَثُ فِى كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِ وَنَزَّلْنَا عَلَيْكَ ٱلْكِتَٰبَ تِبْيَٰنًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَىٰ لِلْمُسْلِمِينَ', '6900dc1f912853cf1ae9792d4896d65a1d2b448abd2fa5cda177e2474a03b036', 'وَيَوْمَ نَبْعَثُ فِى كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِ وَنَزَّلْنَا عَلَيْكَ ٱلْكِتَٰبَ تِبْيَٰنًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَىٰ لِلْمُسْلِمِينَ', '6900dc1f912853cf1ae9792d4896d65a1d2b448abd2fa5cda177e2474a03b036', '6900dc1f912853cf1ae9792d4896d65a1d2b448abd2fa5cda177e2474a03b036', NULL, 'ويوم نبعث في كل امه شهيدا عليهم من انفسهم وجئنا بك شهيدا علي هؤلاء ونزلنا عليك الكتب تبينا لكل شيء وهدي ورحمه وبشري للمسلمين', 14, 28, 110, 1, 3, 277, false, NULL),
    (1991, 'tanzil-uthmani-v1.1', 16, 90, 'إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'a057abbcf0b8a1b5d78cf211060f6d94616d769c93d3e62b8339fa5d41bc68c4', 'إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 'a057abbcf0b8a1b5d78cf211060f6d94616d769c93d3e62b8339fa5d41bc68c4', 'a057abbcf0b8a1b5d78cf211060f6d94616d769c93d3e62b8339fa5d41bc68c4', NULL, 'ان الله يامر بالعدل والاحسن وايتائ ذي القربي وينهي عن الفحشاء والمنكر والبغي يعظكم لعلكم تذكرون', 14, 28, 111, 1, 3, 277, false, NULL),
    (1992, 'tanzil-uthmani-v1.1', 16, 91, 'وَأَوْفُوا۟ بِعَهْدِ ٱللَّهِ إِذَا عَٰهَدتُّمْ وَلَا تَنقُضُوا۟ ٱلْأَيْمَٰنَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ ٱللَّهَ عَلَيْكُمْ كَفِيلًا إِنَّ ٱللَّهَ يَعْلَمُ مَا تَفْعَلُونَ', '9e678e3be0a8fbd66a27e1beb17b179ca6f1e02a06ddff239fabd32869864814', 'وَأَوْفُوا۟ بِعَهْدِ ٱللَّهِ إِذَا عَٰهَدتُّمْ وَلَا تَنقُضُوا۟ ٱلْأَيْمَٰنَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ ٱللَّهَ عَلَيْكُمْ كَفِيلًا إِنَّ ٱللَّهَ يَعْلَمُ مَا تَفْعَلُونَ', '9e678e3be0a8fbd66a27e1beb17b179ca6f1e02a06ddff239fabd32869864814', '9e678e3be0a8fbd66a27e1beb17b179ca6f1e02a06ddff239fabd32869864814', NULL, 'واوفوا بعهد الله اذا عهدتم ولا تنقضوا الايمن بعد توكيدها وقد جعلتم الله عليكم كفيلا ان الله يعلم ما تفعلون', 14, 28, 111, 1, 3, 277, false, NULL),
    (1993, 'tanzil-uthmani-v1.1', 16, 92, 'وَلَا تَكُونُوا۟ كَٱلَّتِى نَقَضَتْ غَزْلَهَا مِنۢ بَعْدِ قُوَّةٍ أَنكَٰثًا تَتَّخِذُونَ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ أَن تَكُونَ أُمَّةٌ هِىَ أَرْبَىٰ مِنْ أُمَّةٍ إِنَّمَا يَبْلُوكُمُ ٱللَّهُ بِهِۦ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ ٱلْقِيَٰمَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '14fed73f7801e51471896469168412b2a3a37044efe69468cc67bb24256e0906', 'وَلَا تَكُونُوا۟ كَٱلَّتِى نَقَضَتْ غَزْلَهَا مِنۢ بَعْدِ قُوَّةٍ أَنكَٰثًا تَتَّخِذُونَ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ أَن تَكُونَ أُمَّةٌ هِىَ أَرْبَىٰ مِنْ أُمَّةٍ إِنَّمَا يَبْلُوكُمُ ٱللَّهُ بِهِۦ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ ٱلْقِيَٰمَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '14fed73f7801e51471896469168412b2a3a37044efe69468cc67bb24256e0906', '14fed73f7801e51471896469168412b2a3a37044efe69468cc67bb24256e0906', NULL, 'ولا تكونوا كالتي نقضت غزلها من بعد قوه انكثا تتخذون ايمنكم دخلا بينكم ان تكون امه هي اربي من امه انما يبلوكم الله به وليبينن لكم يوم القيمه ما كنتم فيه تختلفون', 14, 28, 111, 1, 3, 277, false, NULL),
    (1994, 'tanzil-uthmani-v1.1', 16, 93, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ', '0be9b97b10bc03799f7a816f30ebe9f707cfc379bd29f3cc78ecb1cc5809226b', 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ', '0be9b97b10bc03799f7a816f30ebe9f707cfc379bd29f3cc78ecb1cc5809226b', '0be9b97b10bc03799f7a816f30ebe9f707cfc379bd29f3cc78ecb1cc5809226b', NULL, 'ولو شاء الله لجعلكم امه وحده ولكن يضل من يشاء ويهدي من يشاء ولتسلن عما كنتم تعملون', 14, 28, 111, 1, 3, 277, false, NULL),
    (1995, 'tanzil-uthmani-v1.1', 16, 94, 'وَلَا تَتَّخِذُوٓا۟ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ فَتَزِلَّ قَدَمٌۢ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوٓءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ ٱللَّهِ وَلَكُمْ عَذَابٌ عَظِيمٌ', 'a0c2f89ba7fbfec16955b5b5b5a32dbf99b272c645631c57964319727110cbc5', 'وَلَا تَتَّخِذُوٓا۟ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ فَتَزِلَّ قَدَمٌۢ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوٓءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ ٱللَّهِ وَلَكُمْ عَذَابٌ عَظِيمٌ', 'a0c2f89ba7fbfec16955b5b5b5a32dbf99b272c645631c57964319727110cbc5', 'a0c2f89ba7fbfec16955b5b5b5a32dbf99b272c645631c57964319727110cbc5', NULL, 'ولا تتخذوا ايمنكم دخلا بينكم فتزل قدم بعد ثبوتها وتذوقوا السوء بما صددتم عن سبيل الله ولكم عذاب عظيم', 14, 28, 111, 1, 3, 278, false, NULL),
    (1996, 'tanzil-uthmani-v1.1', 16, 95, 'وَلَا تَشْتَرُوا۟ بِعَهْدِ ٱللَّهِ ثَمَنًا قَلِيلًا إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'c9edd9eb7ccb4cee4f1f3e8af09c0ca0f1d3a5d9aef18270353574f68d609b02', 'وَلَا تَشْتَرُوا۟ بِعَهْدِ ٱللَّهِ ثَمَنًا قَلِيلًا إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'c9edd9eb7ccb4cee4f1f3e8af09c0ca0f1d3a5d9aef18270353574f68d609b02', 'c9edd9eb7ccb4cee4f1f3e8af09c0ca0f1d3a5d9aef18270353574f68d609b02', NULL, 'ولا تشتروا بعهد الله ثمنا قليلا انما عند الله هو خير لكم ان كنتم تعلمون', 14, 28, 111, 1, 3, 278, false, NULL),
    (1997, 'tanzil-uthmani-v1.1', 16, 96, 'مَا عِندَكُمْ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٍ وَلَنَجْزِيَنَّ ٱلَّذِينَ صَبَرُوٓا۟ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 'b072f864609796ba7010182b4f652730b0a503887dcc614805da44460419b14d', 'مَا عِندَكُمْ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٍ وَلَنَجْزِيَنَّ ٱلَّذِينَ صَبَرُوٓا۟ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 'b072f864609796ba7010182b4f652730b0a503887dcc614805da44460419b14d', 'b072f864609796ba7010182b4f652730b0a503887dcc614805da44460419b14d', NULL, 'ما عندكم ينفد وما عند الله باق ولنجزين الذين صبروا اجرهم باحسن ما كانوا يعملون', 14, 28, 111, 1, 3, 278, false, NULL),
    (1998, 'tanzil-uthmani-v1.1', 16, 97, 'مَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُۥ حَيَوٰةً طَيِّبَةً وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', '60f013350f0d4afcbbef9093893248eb42f9abd7aea09c55bcc3c296942e31ae', 'مَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُۥ حَيَوٰةً طَيِّبَةً وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', '60f013350f0d4afcbbef9093893248eb42f9abd7aea09c55bcc3c296942e31ae', '60f013350f0d4afcbbef9093893248eb42f9abd7aea09c55bcc3c296942e31ae', NULL, 'من عمل صلحا من ذكر او انثي وهو مؤمن فلنحيينه حيوه طيبه ولنجزينهم اجرهم باحسن ما كانوا يعملون', 14, 28, 111, 1, 3, 278, false, NULL),
    (1999, 'tanzil-uthmani-v1.1', 16, 98, 'فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'a2a39d079409bf0c4a197ae59d0276d199a4cabdfb5c64ada315980c5ab654a1', 'فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 'a2a39d079409bf0c4a197ae59d0276d199a4cabdfb5c64ada315980c5ab654a1', 'a2a39d079409bf0c4a197ae59d0276d199a4cabdfb5c64ada315980c5ab654a1', NULL, 'فاذا قرات القرءان فاستعذ بالله من الشيطن الرجيم', 14, 28, 111, 1, 3, 278, false, NULL),
    (2000, 'tanzil-uthmani-v1.1', 16, 99, 'إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'daa1ed015fdc130fef1f547bf0dd7567dcb6c5a7128436d485de823e81ed9b77', 'إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'daa1ed015fdc130fef1f547bf0dd7567dcb6c5a7128436d485de823e81ed9b77', 'daa1ed015fdc130fef1f547bf0dd7567dcb6c5a7128436d485de823e81ed9b77', NULL, 'انه ليس له سلطن علي الذين ءامنوا وعلي ربهم يتوكلون', 14, 28, 111, 1, 3, 278, false, NULL)
