    (2001, 'tanzil-uthmani-v1.1', 16, 100, 'إِنَّمَا سُلْطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوْنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشْرِكُونَ', 'ee7e3602dcac220b10319b8d9db7ae9d0f9f87c64eb33401bfdda5a9578cd53f', 'إِنَّمَا سُلْطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوْنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشْرِكُونَ', 'ee7e3602dcac220b10319b8d9db7ae9d0f9f87c64eb33401bfdda5a9578cd53f', 'ee7e3602dcac220b10319b8d9db7ae9d0f9f87c64eb33401bfdda5a9578cd53f', NULL, 'انما سلطنه علي الذين يتولونه والذين هم به مشركون', 14, 28, 111, 1, 3, 278, false, NULL),
    (2002, 'tanzil-uthmani-v1.1', 16, 101, 'وَإِذَا بَدَّلْنَآ ءَايَةً مَّكَانَ ءَايَةٍ وَٱللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوٓا۟ إِنَّمَآ أَنتَ مُفْتَرٍۭ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'b1bbfda0d946f02e8e73805c98dc1052c5760602fc396b085ad3a40588895831', 'وَإِذَا بَدَّلْنَآ ءَايَةً مَّكَانَ ءَايَةٍ وَٱللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوٓا۟ إِنَّمَآ أَنتَ مُفْتَرٍۭ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 'b1bbfda0d946f02e8e73805c98dc1052c5760602fc396b085ad3a40588895831', 'b1bbfda0d946f02e8e73805c98dc1052c5760602fc396b085ad3a40588895831', NULL, 'واذا بدلنا ءايه مكان ءايه والله اعلم بما ينزل قالوا انما انت مفتر بل اكثرهم لا يعلمون', 14, 28, 111, 1, 3, 278, false, NULL),
    (2003, 'tanzil-uthmani-v1.1', 16, 102, 'قُلْ نَزَّلَهُۥ رُوحُ ٱلْقُدُسِ مِن رَّبِّكَ بِٱلْحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُوا۟ وَهُدًى وَبُشْرَىٰ لِلْمُسْلِمِينَ', '2ee74a936129e3a23e5c7151856b5120058c92169b40e801fe18e02c96af6021', 'قُلْ نَزَّلَهُۥ رُوحُ ٱلْقُدُسِ مِن رَّبِّكَ بِٱلْحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُوا۟ وَهُدًى وَبُشْرَىٰ لِلْمُسْلِمِينَ', '2ee74a936129e3a23e5c7151856b5120058c92169b40e801fe18e02c96af6021', '2ee74a936129e3a23e5c7151856b5120058c92169b40e801fe18e02c96af6021', NULL, 'قل نزله روح القدس من ربك بالحق ليثبت الذين ءامنوا وهدي وبشري للمسلمين', 14, 28, 111, 1, 3, 278, false, NULL),
    (2004, 'tanzil-uthmani-v1.1', 16, 103, 'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٌ لِّسَانُ ٱلَّذِى يُلْحِدُونَ إِلَيْهِ أَعْجَمِىٌّ وَهَٰذَا لِسَانٌ عَرَبِىٌّ مُّبِينٌ', 'a38f09d15f90f94129abb192ab31dff284b2955f3c9e5eba605769b3969538df', 'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٌ لِّسَانُ ٱلَّذِى يُلْحِدُونَ إِلَيْهِ أَعْجَمِىٌّ وَهَٰذَا لِسَانٌ عَرَبِىٌّ مُّبِينٌ', 'a38f09d15f90f94129abb192ab31dff284b2955f3c9e5eba605769b3969538df', 'a38f09d15f90f94129abb192ab31dff284b2955f3c9e5eba605769b3969538df', NULL, 'ولقد نعلم انهم يقولون انما يعلمه بشر لسان الذي يلحدون اليه اعجمي وهذا لسان عربي مبين', 14, 28, 111, 1, 3, 279, false, NULL),
    (2005, 'tanzil-uthmani-v1.1', 16, 104, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهْدِيهِمُ ٱللَّهُ وَلَهُمْ عَذَابٌ أَلِيمٌ', '3e0fcd6c88e9d21f739a418c0ec47e8aedf96ab33df9f790876cd454255435ec', 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهْدِيهِمُ ٱللَّهُ وَلَهُمْ عَذَابٌ أَلِيمٌ', '3e0fcd6c88e9d21f739a418c0ec47e8aedf96ab33df9f790876cd454255435ec', '3e0fcd6c88e9d21f739a418c0ec47e8aedf96ab33df9f790876cd454255435ec', NULL, 'ان الذين لا يؤمنون بايت الله لا يهديهم الله ولهم عذاب اليم', 14, 28, 111, 1, 3, 279, false, NULL),
    (2006, 'tanzil-uthmani-v1.1', 16, 105, 'إِنَّمَا يَفْتَرِى ٱلْكَذِبَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰذِبُونَ', '06833992b2b2795ec0fbc8df2631c67d063128d120fc7ec5bc12e727566a1447', 'إِنَّمَا يَفْتَرِى ٱلْكَذِبَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰذِبُونَ', '06833992b2b2795ec0fbc8df2631c67d063128d120fc7ec5bc12e727566a1447', '06833992b2b2795ec0fbc8df2631c67d063128d120fc7ec5bc12e727566a1447', NULL, 'انما يفتري الكذب الذين لا يؤمنون بايت الله واولئك هم الكذبون', 14, 28, 111, 1, 3, 279, false, NULL),
    (2007, 'tanzil-uthmani-v1.1', 16, 106, 'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعْدِ إِيمَٰنِهِۦٓ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُۥ مُطْمَئِنٌّۢ بِٱلْإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلْكُفْرِ صَدْرًا فَعَلَيْهِمْ غَضَبٌ مِّنَ ٱللَّهِ وَلَهُمْ عَذَابٌ عَظِيمٌ', '16bbde9917acd03256c0742c363fc6735f5630aa22a62776f2eb447d80c28ef7', 'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعْدِ إِيمَٰنِهِۦٓ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُۥ مُطْمَئِنٌّۢ بِٱلْإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلْكُفْرِ صَدْرًا فَعَلَيْهِمْ غَضَبٌ مِّنَ ٱللَّهِ وَلَهُمْ عَذَابٌ عَظِيمٌ', '16bbde9917acd03256c0742c363fc6735f5630aa22a62776f2eb447d80c28ef7', '16bbde9917acd03256c0742c363fc6735f5630aa22a62776f2eb447d80c28ef7', NULL, 'من كفر بالله من بعد ايمنه الا من اكره وقلبه مطمئن بالايمن ولكن من شرح بالكفر صدرا فعليهم غضب من الله ولهم عذاب عظيم', 14, 28, 111, 1, 3, 279, false, NULL),
    (2008, 'tanzil-uthmani-v1.1', 16, 107, 'ذَٰلِكَ بِأَنَّهُمُ ٱسْتَحَبُّوا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْـَٔاخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'f4b99aa4f31a11510b99bc79e1f765df802f224ef6e7cab9b0104912b01dc551', 'ذَٰلِكَ بِأَنَّهُمُ ٱسْتَحَبُّوا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْـَٔاخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 'f4b99aa4f31a11510b99bc79e1f765df802f224ef6e7cab9b0104912b01dc551', 'f4b99aa4f31a11510b99bc79e1f765df802f224ef6e7cab9b0104912b01dc551', NULL, 'ذلك بانهم استحبوا الحيوه الدنيا علي الاخره وان الله لا يهدي القوم الكفرين', 14, 28, 111, 1, 3, 279, false, NULL),
    (2009, 'tanzil-uthmani-v1.1', 16, 108, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 'c48eb6a4c0893c734d052467898b6aaed923ab32bf1e9a8152e820e59d429c18', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 'c48eb6a4c0893c734d052467898b6aaed923ab32bf1e9a8152e820e59d429c18', 'c48eb6a4c0893c734d052467898b6aaed923ab32bf1e9a8152e820e59d429c18', NULL, 'اولئك الذين طبع الله علي قلوبهم وسمعهم وابصرهم واولئك هم الغفلون', 14, 28, 111, 1, 3, 279, false, NULL),
    (2010, 'tanzil-uthmani-v1.1', 16, 109, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْخَٰسِرُونَ', 'a6de4fd5bfcdb16679577a1e6346639219269543ac3c42f8d79b6ce46f8ccfd7', 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْخَٰسِرُونَ', 'a6de4fd5bfcdb16679577a1e6346639219269543ac3c42f8d79b6ce46f8ccfd7', 'a6de4fd5bfcdb16679577a1e6346639219269543ac3c42f8d79b6ce46f8ccfd7', NULL, 'لا جرم انهم في الاخره هم الخسرون', 14, 28, 111, 1, 3, 279, false, NULL),
    (2011, 'tanzil-uthmani-v1.1', 16, 110, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا۟ مِنۢ بَعْدِ مَا فُتِنُوا۟ ثُمَّ جَٰهَدُوا۟ وَصَبَرُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', '62e11717b7537864442a16824348384e5974e617cda50bbf9702c4943c91963c', 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا۟ مِنۢ بَعْدِ مَا فُتِنُوا۟ ثُمَّ جَٰهَدُوا۟ وَصَبَرُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', '62e11717b7537864442a16824348384e5974e617cda50bbf9702c4943c91963c', '62e11717b7537864442a16824348384e5974e617cda50bbf9702c4943c91963c', NULL, 'ثم ان ربك للذين هاجروا من بعد ما فتنوا ثم جهدوا وصبروا ان ربك من بعدها لغفور رحيم', 14, 28, 111, 1, 3, 279, false, NULL),
    (2012, 'tanzil-uthmani-v1.1', 16, 111, 'يَوْمَ تَأْتِى كُلُّ نَفْسٍ تُجَٰدِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ', 'adad35e96489099696e2100cad3465bcbcf4e66666e42a252b4a73550ac9c380', 'يَوْمَ تَأْتِى كُلُّ نَفْسٍ تُجَٰدِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ', 'adad35e96489099696e2100cad3465bcbcf4e66666e42a252b4a73550ac9c380', 'adad35e96489099696e2100cad3465bcbcf4e66666e42a252b4a73550ac9c380', NULL, 'يوم تاتي كل نفس تجدل عن نفسها وتوفي كل نفس ما عملت وهم لا يظلمون', 14, 28, 112, 1, 3, 280, false, NULL),
    (2013, 'tanzil-uthmani-v1.1', 16, 112, 'وَضَرَبَ ٱللَّهُ مَثَلًا قَرْيَةً كَانَتْ ءَامِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُوا۟ يَصْنَعُونَ', 'e582e8a215f4be186af3517341b78535036fc0c1414fce92ef236f58dee8c8a8', 'وَضَرَبَ ٱللَّهُ مَثَلًا قَرْيَةً كَانَتْ ءَامِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُوا۟ يَصْنَعُونَ', 'e582e8a215f4be186af3517341b78535036fc0c1414fce92ef236f58dee8c8a8', 'e582e8a215f4be186af3517341b78535036fc0c1414fce92ef236f58dee8c8a8', NULL, 'وضرب الله مثلا قريه كانت ءامنه مطمئنه ياتيها رزقها رغدا من كل مكان فكفرت بانعم الله فاذقها الله لباس الجوع والخوف بما كانوا يصنعون', 14, 28, 112, 1, 3, 280, false, NULL),
    (2014, 'tanzil-uthmani-v1.1', 16, 113, 'وَلَقَدْ جَآءَهُمْ رَسُولٌ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلْعَذَابُ وَهُمْ ظَٰلِمُونَ', '2a6876680e3db56543643e5540a589e0d0995741cbd807584b356e4aa778a80f', 'وَلَقَدْ جَآءَهُمْ رَسُولٌ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلْعَذَابُ وَهُمْ ظَٰلِمُونَ', '2a6876680e3db56543643e5540a589e0d0995741cbd807584b356e4aa778a80f', '2a6876680e3db56543643e5540a589e0d0995741cbd807584b356e4aa778a80f', NULL, 'ولقد جاءهم رسول منهم فكذبوه فاخذهم العذاب وهم ظلمون', 14, 28, 112, 1, 3, 280, false, NULL),
    (2015, 'tanzil-uthmani-v1.1', 16, 114, 'فَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًا طَيِّبًا وَٱشْكُرُوا۟ نِعْمَتَ ٱللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', '8ce60af360311adf1b81b00f5ea82d6050df4c4ea65158534bfd2fb8142a160d', 'فَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًا طَيِّبًا وَٱشْكُرُوا۟ نِعْمَتَ ٱللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', '8ce60af360311adf1b81b00f5ea82d6050df4c4ea65158534bfd2fb8142a160d', '8ce60af360311adf1b81b00f5ea82d6050df4c4ea65158534bfd2fb8142a160d', NULL, 'فكلوا مما رزقكم الله حللا طيبا واشكروا نعمت الله ان كنتم اياه تعبدون', 14, 28, 112, 1, 3, 280, false, NULL),
    (2016, 'tanzil-uthmani-v1.1', 16, 115, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '0285fc5c3a88474b78254376bf1dd7357754d2493e66ee7acda3e433f5e1b737', 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '0285fc5c3a88474b78254376bf1dd7357754d2493e66ee7acda3e433f5e1b737', '0285fc5c3a88474b78254376bf1dd7357754d2493e66ee7acda3e433f5e1b737', NULL, 'انما حرم عليكم الميته والدم ولحم الخنزير وما اهل لغير الله به فمن اضطر غير باغ ولا عاد فان الله غفور رحيم', 14, 28, 112, 1, 3, 280, false, NULL),
    (2017, 'tanzil-uthmani-v1.1', 16, 116, 'وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلْسِنَتُكُمُ ٱلْكَذِبَ هَٰذَا حَلَٰلٌ وَهَٰذَا حَرَامٌ لِّتَفْتَرُوا۟ عَلَى ٱللَّهِ ٱلْكَذِبَ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', '092a1bd0164ece4576a51d520963e96f4d79212ea04d9d8e3083485650ede639', 'وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلْسِنَتُكُمُ ٱلْكَذِبَ هَٰذَا حَلَٰلٌ وَهَٰذَا حَرَامٌ لِّتَفْتَرُوا۟ عَلَى ٱللَّهِ ٱلْكَذِبَ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', '092a1bd0164ece4576a51d520963e96f4d79212ea04d9d8e3083485650ede639', '092a1bd0164ece4576a51d520963e96f4d79212ea04d9d8e3083485650ede639', NULL, 'ولا تقولوا لما تصف السنتكم الكذب هذا حلل وهذا حرام لتفتروا علي الله الكذب ان الذين يفترون علي الله الكذب لا يفلحون', 14, 28, 112, 1, 3, 280, false, NULL),
    (2018, 'tanzil-uthmani-v1.1', 16, 117, 'مَتَٰعٌ قَلِيلٌ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'ee2a03bedc46fe42a9b637f73e19391c3a2bcc272012e52aedaec6fa055456b2', 'مَتَٰعٌ قَلِيلٌ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'ee2a03bedc46fe42a9b637f73e19391c3a2bcc272012e52aedaec6fa055456b2', 'ee2a03bedc46fe42a9b637f73e19391c3a2bcc272012e52aedaec6fa055456b2', NULL, 'متع قليل ولهم عذاب اليم', 14, 28, 112, 1, 3, 280, false, NULL),
    (2019, 'tanzil-uthmani-v1.1', 16, 118, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '7188cc6ee3399e9d22f50598d78d2c466d142921df2c315da245cc704022478b', 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '7188cc6ee3399e9d22f50598d78d2c466d142921df2c315da245cc704022478b', '7188cc6ee3399e9d22f50598d78d2c466d142921df2c315da245cc704022478b', NULL, 'وعلي الذين هادوا حرمنا ما قصصنا عليك من قبل وما ظلمنهم ولكن كانوا انفسهم يظلمون', 14, 28, 112, 1, 3, 280, false, NULL),
    (2020, 'tanzil-uthmani-v1.1', 16, 119, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا۟ ٱلسُّوٓءَ بِجَهَٰلَةٍ ثُمَّ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', '51fae977f39eaeff3f6f8bf4d5fd967a5c190143c9255036d924d82a7793ff67', 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا۟ ٱلسُّوٓءَ بِجَهَٰلَةٍ ثُمَّ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ', '51fae977f39eaeff3f6f8bf4d5fd967a5c190143c9255036d924d82a7793ff67', '51fae977f39eaeff3f6f8bf4d5fd967a5c190143c9255036d924d82a7793ff67', NULL, 'ثم ان ربك للذين عملوا السوء بجهله ثم تابوا من بعد ذلك واصلحوا ان ربك من بعدها لغفور رحيم', 14, 28, 112, 1, 3, 281, false, NULL),
    (2021, 'tanzil-uthmani-v1.1', 16, 120, 'إِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةً قَانِتًا لِّلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ ٱلْمُشْرِكِينَ', 'a25fe7ef0b6cdf030053aaf9b3a584ea4db555fb3f3a2bd101a0f5094c4bc114', 'إِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةً قَانِتًا لِّلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ ٱلْمُشْرِكِينَ', 'a25fe7ef0b6cdf030053aaf9b3a584ea4db555fb3f3a2bd101a0f5094c4bc114', 'a25fe7ef0b6cdf030053aaf9b3a584ea4db555fb3f3a2bd101a0f5094c4bc114', NULL, 'ان ابرهيم كان امه قانتا لله حنيفا ولم يك من المشركين', 14, 28, 112, 1, 3, 281, false, NULL),
    (2022, 'tanzil-uthmani-v1.1', 16, 121, 'شَاكِرًا لِّأَنْعُمِهِ ٱجْتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'be22b32d5beed8b3d05b06669388263316f17096268971dd39961303b10bc8b1', 'شَاكِرًا لِّأَنْعُمِهِ ٱجْتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'be22b32d5beed8b3d05b06669388263316f17096268971dd39961303b10bc8b1', 'be22b32d5beed8b3d05b06669388263316f17096268971dd39961303b10bc8b1', NULL, 'شاكرا لانعمه اجتبيه وهديه الي صرط مستقيم', 14, 28, 112, 1, 3, 281, false, NULL),
    (2023, 'tanzil-uthmani-v1.1', 16, 122, 'وَءَاتَيْنَٰهُ فِى ٱلدُّنْيَا حَسَنَةً وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', '8b9fbc10b1934bca1a6479d937e84f3ce856e33b7bcdb07f3e434359f088cd74', 'وَءَاتَيْنَٰهُ فِى ٱلدُّنْيَا حَسَنَةً وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', '8b9fbc10b1934bca1a6479d937e84f3ce856e33b7bcdb07f3e434359f088cd74', '8b9fbc10b1934bca1a6479d937e84f3ce856e33b7bcdb07f3e434359f088cd74', NULL, 'وءاتينه في الدنيا حسنه وانه في الاخره لمن الصلحين', 14, 28, 112, 1, 3, 281, false, NULL),
    (2024, 'tanzil-uthmani-v1.1', 16, 123, 'ثُمَّ أَوْحَيْنَآ إِلَيْكَ أَنِ ٱتَّبِعْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '33396a62f59c44e8a3ccb5c2f14ef68f768cab4628a2e11a78722ad4200ddba3', 'ثُمَّ أَوْحَيْنَآ إِلَيْكَ أَنِ ٱتَّبِعْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', '33396a62f59c44e8a3ccb5c2f14ef68f768cab4628a2e11a78722ad4200ddba3', '33396a62f59c44e8a3ccb5c2f14ef68f768cab4628a2e11a78722ad4200ddba3', NULL, 'ثم اوحينا اليك ان اتبع مله ابرهيم حنيفا وما كان من المشركين', 14, 28, 112, 1, 3, 281, false, NULL),
    (2025, 'tanzil-uthmani-v1.1', 16, 124, 'إِنَّمَا جُعِلَ ٱلسَّبْتُ عَلَى ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '4691ef90bac3a4d74bebfb21a8c79b46c8150ab5ea881cda791ceda7d246f643', 'إِنَّمَا جُعِلَ ٱلسَّبْتُ عَلَى ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '4691ef90bac3a4d74bebfb21a8c79b46c8150ab5ea881cda791ceda7d246f643', '4691ef90bac3a4d74bebfb21a8c79b46c8150ab5ea881cda791ceda7d246f643', NULL, 'انما جعل السبت علي الذين اختلفوا فيه وان ربك ليحكم بينهم يوم القيمه فيما كانوا فيه يختلفون', 14, 28, 112, 1, 3, 281, false, NULL),
    (2026, 'tanzil-uthmani-v1.1', 16, 125, 'ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', '4fc6a9c455366e1b0a7a67223003e079fee20d874da75da096b94c01100af678', 'ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', '4fc6a9c455366e1b0a7a67223003e079fee20d874da75da096b94c01100af678', '4fc6a9c455366e1b0a7a67223003e079fee20d874da75da096b94c01100af678', NULL, 'ادع الي سبيل ربك بالحكمه والموعظه الحسنه وجدلهم بالتي هي احسن ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين', 14, 28, 112, 1, 3, 281, false, NULL),
    (2027, 'tanzil-uthmani-v1.1', 16, 126, 'وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا۟ بِمِثْلِ مَا عُوقِبْتُم بِهِۦ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِّلصَّٰبِرِينَ', '7c17f952c8a7042c11fedffddea008aef76286773ff60734d2e0dedd3d0e3552', 'وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا۟ بِمِثْلِ مَا عُوقِبْتُم بِهِۦ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِّلصَّٰبِرِينَ', '7c17f952c8a7042c11fedffddea008aef76286773ff60734d2e0dedd3d0e3552', '7c17f952c8a7042c11fedffddea008aef76286773ff60734d2e0dedd3d0e3552', NULL, 'وان عاقبتم فعاقبوا بمثل ما عوقبتم به ولئن صبرتم لهو خير للصبرين', 14, 28, 112, 1, 3, 281, false, NULL),
    (2028, 'tanzil-uthmani-v1.1', 16, 127, 'وَٱصْبِرْ وَمَا صَبْرُكَ إِلَّا بِٱللَّهِ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', '10c41cf344a2c8644186709604c17d43dcb3b5c796505f0514ccfcf899af611f', 'وَٱصْبِرْ وَمَا صَبْرُكَ إِلَّا بِٱللَّهِ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', '10c41cf344a2c8644186709604c17d43dcb3b5c796505f0514ccfcf899af611f', '10c41cf344a2c8644186709604c17d43dcb3b5c796505f0514ccfcf899af611f', NULL, 'واصبر وما صبرك الا بالله ولا تحزن عليهم ولا تك في ضيق مما يمكرون', 14, 28, 112, 1, 3, 281, false, NULL),
    (2029, 'tanzil-uthmani-v1.1', 16, 128, 'إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَوا۟ وَّٱلَّذِينَ هُم مُّحْسِنُونَ', '7408453520845bd8a8acb871b14cc51a471edd350e5736c3bd1a68de760a7dc5', 'إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَوا۟ وَّٱلَّذِينَ هُم مُّحْسِنُونَ', '7408453520845bd8a8acb871b14cc51a471edd350e5736c3bd1a68de760a7dc5', '7408453520845bd8a8acb871b14cc51a471edd350e5736c3bd1a68de760a7dc5', NULL, 'ان الله مع الذين اتقوا والذين هم محسنون', 14, 28, 112, 1, 3, 281, false, NULL),
    (2030, 'tanzil-uthmani-v1.1', 17, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سُبْحَٰنَ ٱلَّذِىٓ أَسْرَىٰ بِعَبْدِهِۦ لَيْلًا مِّنَ ٱلْمَسْجِدِ ٱلْحَرَامِ إِلَى ٱلْمَسْجِدِ ٱلْأَقْصَا ٱلَّذِى بَٰرَكْنَا حَوْلَهُۥ لِنُرِيَهُۥ مِنْ ءَايَٰتِنَآ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '440cc8f728a1977e0f23c63dcf4a23425d756b86707001c8dfa2b39c3fecd8a8', 'سُبْحَٰنَ ٱلَّذِىٓ أَسْرَىٰ بِعَبْدِهِۦ لَيْلًا مِّنَ ٱلْمَسْجِدِ ٱلْحَرَامِ إِلَى ٱلْمَسْجِدِ ٱلْأَقْصَا ٱلَّذِى بَٰرَكْنَا حَوْلَهُۥ لِنُرِيَهُۥ مِنْ ءَايَٰتِنَآ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '87796b3e541c50e112fa8aab62753eb0b61f1f6bf97e3edd10b68d9718aef7cf', '87796b3e541c50e112fa8aab62753eb0b61f1f6bf97e3edd10b68d9718aef7cf', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'سبحن الذي اسري بعبده ليلا من المسجد الحرام الي المسجد الاقصا الذي بركنا حوله لنريه من ءايتنا انه هو السميع البصير', 15, 29, 113, 1, 4, 282, false, NULL),
    (2031, 'tanzil-uthmani-v1.1', 17, 2, 'وَءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِى وَكِيلًا', 'd55e3631b36f3a3c809d953c3a558c14e16aa7e7f09fc9735663f1618371f6ad', 'وَءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِى وَكِيلًا', 'd55e3631b36f3a3c809d953c3a558c14e16aa7e7f09fc9735663f1618371f6ad', 'd55e3631b36f3a3c809d953c3a558c14e16aa7e7f09fc9735663f1618371f6ad', NULL, 'وءاتينا موسي الكتب وجعلنه هدي لبني اسرءيل الا تتخذوا من دوني وكيلا', 15, 29, 113, 1, 4, 282, false, NULL),
    (2032, 'tanzil-uthmani-v1.1', 17, 3, 'ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ إِنَّهُۥ كَانَ عَبْدًا شَكُورًا', 'd255d162743aea8fe238a77f1a61959c2433e279c8185f7afcf347a2439e4f5f', 'ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ إِنَّهُۥ كَانَ عَبْدًا شَكُورًا', 'd255d162743aea8fe238a77f1a61959c2433e279c8185f7afcf347a2439e4f5f', 'd255d162743aea8fe238a77f1a61959c2433e279c8185f7afcf347a2439e4f5f', NULL, 'ذريه من حملنا مع نوح انه كان عبدا شكورا', 15, 29, 113, 1, 4, 282, false, NULL),
    (2033, 'tanzil-uthmani-v1.1', 17, 4, 'وَقَضَيْنَآ إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ فِى ٱلْكِتَٰبِ لَتُفْسِدُنَّ فِى ٱلْأَرْضِ مَرَّتَيْنِ وَلَتَعْلُنَّ عُلُوًّا كَبِيرًا', '7fc371f479116471cc60b2defa3a9b7f0450d5cda0acefebf0b57a61cc6fc8fe', 'وَقَضَيْنَآ إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ فِى ٱلْكِتَٰبِ لَتُفْسِدُنَّ فِى ٱلْأَرْضِ مَرَّتَيْنِ وَلَتَعْلُنَّ عُلُوًّا كَبِيرًا', '7fc371f479116471cc60b2defa3a9b7f0450d5cda0acefebf0b57a61cc6fc8fe', '7fc371f479116471cc60b2defa3a9b7f0450d5cda0acefebf0b57a61cc6fc8fe', NULL, 'وقضينا الي بني اسرءيل في الكتب لتفسدن في الارض مرتين ولتعلن علوا كبيرا', 15, 29, 113, 1, 4, 282, false, NULL),
    (2034, 'tanzil-uthmani-v1.1', 17, 5, 'فَإِذَا جَآءَ وَعْدُ أُولَىٰهُمَا بَعَثْنَا عَلَيْكُمْ عِبَادًا لَّنَآ أُو۟لِى بَأْسٍ شَدِيدٍ فَجَاسُوا۟ خِلَٰلَ ٱلدِّيَارِ وَكَانَ وَعْدًا مَّفْعُولًا', '0a54bc7e81ca54639afc179fd75ccab0094e6a958ddc073f0fe4472aeb06a1bf', 'فَإِذَا جَآءَ وَعْدُ أُولَىٰهُمَا بَعَثْنَا عَلَيْكُمْ عِبَادًا لَّنَآ أُو۟لِى بَأْسٍ شَدِيدٍ فَجَاسُوا۟ خِلَٰلَ ٱلدِّيَارِ وَكَانَ وَعْدًا مَّفْعُولًا', '0a54bc7e81ca54639afc179fd75ccab0094e6a958ddc073f0fe4472aeb06a1bf', '0a54bc7e81ca54639afc179fd75ccab0094e6a958ddc073f0fe4472aeb06a1bf', NULL, 'فاذا جاء وعد اوليهما بعثنا عليكم عبادا لنا اولي باس شديد فجاسوا خلل الديار وكان وعدا مفعولا', 15, 29, 113, 1, 4, 282, false, NULL),
    (2035, 'tanzil-uthmani-v1.1', 17, 6, 'ثُمَّ رَدَدْنَا لَكُمُ ٱلْكَرَّةَ عَلَيْهِمْ وَأَمْدَدْنَٰكُم بِأَمْوَٰلٍ وَبَنِينَ وَجَعَلْنَٰكُمْ أَكْثَرَ نَفِيرًا', 'd971ab8bfbc7b7dda1a52dd5cd5b2b3836c70e41aee018d9ef52b2e4e67e3f06', 'ثُمَّ رَدَدْنَا لَكُمُ ٱلْكَرَّةَ عَلَيْهِمْ وَأَمْدَدْنَٰكُم بِأَمْوَٰلٍ وَبَنِينَ وَجَعَلْنَٰكُمْ أَكْثَرَ نَفِيرًا', 'd971ab8bfbc7b7dda1a52dd5cd5b2b3836c70e41aee018d9ef52b2e4e67e3f06', 'd971ab8bfbc7b7dda1a52dd5cd5b2b3836c70e41aee018d9ef52b2e4e67e3f06', NULL, 'ثم رددنا لكم الكره عليهم وامددنكم بامول وبنين وجعلنكم اكثر نفيرا', 15, 29, 113, 1, 4, 282, false, NULL),
    (2036, 'tanzil-uthmani-v1.1', 17, 7, 'إِنْ أَحْسَنتُمْ أَحْسَنتُمْ لِأَنفُسِكُمْ وَإِنْ أَسَأْتُمْ فَلَهَا فَإِذَا جَآءَ وَعْدُ ٱلْـَٔاخِرَةِ لِيَسُـۥٓـُٔوا۟ وُجُوهَكُمْ وَلِيَدْخُلُوا۟ ٱلْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٍ وَلِيُتَبِّرُوا۟ مَا عَلَوْا۟ تَتْبِيرًا', '3de12b08d6da00d5f173d07e971def1000f207cc9afdb75c9f7bb106250f1202', 'إِنْ أَحْسَنتُمْ أَحْسَنتُمْ لِأَنفُسِكُمْ وَإِنْ أَسَأْتُمْ فَلَهَا فَإِذَا جَآءَ وَعْدُ ٱلْـَٔاخِرَةِ لِيَسُـۥٓـُٔوا۟ وُجُوهَكُمْ وَلِيَدْخُلُوا۟ ٱلْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٍ وَلِيُتَبِّرُوا۟ مَا عَلَوْا۟ تَتْبِيرًا', '3de12b08d6da00d5f173d07e971def1000f207cc9afdb75c9f7bb106250f1202', '3de12b08d6da00d5f173d07e971def1000f207cc9afdb75c9f7bb106250f1202', NULL, 'ان احسنتم احسنتم لانفسكم وان اساتم فلها فاذا جاء وعد الاخره ليسوا وجوهكم وليدخلوا المسجد كما دخلوه اول مره وليتبروا ما علوا تتبيرا', 15, 29, 113, 1, 4, 282, false, NULL),
    (2037, 'tanzil-uthmani-v1.1', 17, 8, 'عَسَىٰ رَبُّكُمْ أَن يَرْحَمَكُمْ وَإِنْ عُدتُّمْ عُدْنَا وَجَعَلْنَا جَهَنَّمَ لِلْكَٰفِرِينَ حَصِيرًا', 'd820d238ebcc80efa82d7ecfffbab0a6951fb7492fad721410991dd49ffd388c', 'عَسَىٰ رَبُّكُمْ أَن يَرْحَمَكُمْ وَإِنْ عُدتُّمْ عُدْنَا وَجَعَلْنَا جَهَنَّمَ لِلْكَٰفِرِينَ حَصِيرًا', 'd820d238ebcc80efa82d7ecfffbab0a6951fb7492fad721410991dd49ffd388c', 'd820d238ebcc80efa82d7ecfffbab0a6951fb7492fad721410991dd49ffd388c', NULL, 'عسي ربكم ان يرحمكم وان عدتم عدنا وجعلنا جهنم للكفرين حصيرا', 15, 29, 113, 1, 4, 283, false, NULL),
    (2038, 'tanzil-uthmani-v1.1', 17, 9, 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَهْدِى لِلَّتِى هِىَ أَقْوَمُ وَيُبَشِّرُ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًا كَبِيرًا', '83fb5bd9062bca7ac86e2a00839fc852f51420b234f8b4a142426a07329accf1', 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَهْدِى لِلَّتِى هِىَ أَقْوَمُ وَيُبَشِّرُ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًا كَبِيرًا', '83fb5bd9062bca7ac86e2a00839fc852f51420b234f8b4a142426a07329accf1', '83fb5bd9062bca7ac86e2a00839fc852f51420b234f8b4a142426a07329accf1', NULL, 'ان هذا القرءان يهدي للتي هي اقوم ويبشر المؤمنين الذين يعملون الصلحت ان لهم اجرا كبيرا', 15, 29, 113, 1, 4, 283, false, NULL),
    (2039, 'tanzil-uthmani-v1.1', 17, 10, 'وَأَنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', '036b72227990d1d7480c4e2a1bc8fbee219cba783dc10c30a23b0900a4715597', 'وَأَنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًا', '036b72227990d1d7480c4e2a1bc8fbee219cba783dc10c30a23b0900a4715597', '036b72227990d1d7480c4e2a1bc8fbee219cba783dc10c30a23b0900a4715597', NULL, 'وان الذين لا يؤمنون بالاخره اعتدنا لهم عذابا اليما', 15, 29, 113, 1, 4, 283, false, NULL),
    (2040, 'tanzil-uthmani-v1.1', 17, 11, 'وَيَدْعُ ٱلْإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلْخَيْرِ وَكَانَ ٱلْإِنسَٰنُ عَجُولًا', 'c7f10f49650ede3d038f79bb5418d9ae4473390dd2b1601fb77a7f36695e4259', 'وَيَدْعُ ٱلْإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلْخَيْرِ وَكَانَ ٱلْإِنسَٰنُ عَجُولًا', 'c7f10f49650ede3d038f79bb5418d9ae4473390dd2b1601fb77a7f36695e4259', 'c7f10f49650ede3d038f79bb5418d9ae4473390dd2b1601fb77a7f36695e4259', NULL, 'ويدع الانسن بالشر دعاءه بالخير وكان الانسن عجولا', 15, 29, 113, 1, 4, 283, false, NULL),
    (2041, 'tanzil-uthmani-v1.1', 17, 12, 'وَجَعَلْنَا ٱلَّيْلَ وَٱلنَّهَارَ ءَايَتَيْنِ فَمَحَوْنَآ ءَايَةَ ٱلَّيْلِ وَجَعَلْنَآ ءَايَةَ ٱلنَّهَارِ مُبْصِرَةً لِّتَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ وَلِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ وَكُلَّ شَىْءٍ فَصَّلْنَٰهُ تَفْصِيلًا', 'e2ded62efad0e8fb6e5b8321a020c7334fb7b325ac8f3cca8bbfd3973bb56f25', 'وَجَعَلْنَا ٱلَّيْلَ وَٱلنَّهَارَ ءَايَتَيْنِ فَمَحَوْنَآ ءَايَةَ ٱلَّيْلِ وَجَعَلْنَآ ءَايَةَ ٱلنَّهَارِ مُبْصِرَةً لِّتَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ وَلِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ وَكُلَّ شَىْءٍ فَصَّلْنَٰهُ تَفْصِيلًا', 'e2ded62efad0e8fb6e5b8321a020c7334fb7b325ac8f3cca8bbfd3973bb56f25', 'e2ded62efad0e8fb6e5b8321a020c7334fb7b325ac8f3cca8bbfd3973bb56f25', NULL, 'وجعلنا اليل والنهار ءايتين فمحونا ءايه اليل وجعلنا ءايه النهار مبصره لتبتغوا فضلا من ربكم ولتعلموا عدد السنين والحساب وكل شيء فصلنه تفصيلا', 15, 29, 113, 1, 4, 283, false, NULL),
    (2042, 'tanzil-uthmani-v1.1', 17, 13, 'وَكُلَّ إِنسَٰنٍ أَلْزَمْنَٰهُ طَٰٓئِرَهُۥ فِى عُنُقِهِۦ وَنُخْرِجُ لَهُۥ يَوْمَ ٱلْقِيَٰمَةِ كِتَٰبًا يَلْقَىٰهُ مَنشُورًا', 'a8e37b40de438526ddd6661dd42a284581f5e2a1efec8a3ec13d7211c6405947', 'وَكُلَّ إِنسَٰنٍ أَلْزَمْنَٰهُ طَٰٓئِرَهُۥ فِى عُنُقِهِۦ وَنُخْرِجُ لَهُۥ يَوْمَ ٱلْقِيَٰمَةِ كِتَٰبًا يَلْقَىٰهُ مَنشُورًا', 'a8e37b40de438526ddd6661dd42a284581f5e2a1efec8a3ec13d7211c6405947', 'a8e37b40de438526ddd6661dd42a284581f5e2a1efec8a3ec13d7211c6405947', NULL, 'وكل انسن الزمنه طئره في عنقه ونخرج له يوم القيمه كتبا يلقيه منشورا', 15, 29, 113, 1, 4, 283, false, NULL),
    (2043, 'tanzil-uthmani-v1.1', 17, 14, 'ٱقْرَأْ كِتَٰبَكَ كَفَىٰ بِنَفْسِكَ ٱلْيَوْمَ عَلَيْكَ حَسِيبًا', 'ac4ce5228939acbffa4e596654ea7e4b69840b0e1438fe94c9d8426ae8cfb7ce', 'ٱقْرَأْ كِتَٰبَكَ كَفَىٰ بِنَفْسِكَ ٱلْيَوْمَ عَلَيْكَ حَسِيبًا', 'ac4ce5228939acbffa4e596654ea7e4b69840b0e1438fe94c9d8426ae8cfb7ce', 'ac4ce5228939acbffa4e596654ea7e4b69840b0e1438fe94c9d8426ae8cfb7ce', NULL, 'اقرا كتبك كفي بنفسك اليوم عليك حسيبا', 15, 29, 113, 1, 4, 283, false, NULL),
    (2044, 'tanzil-uthmani-v1.1', 17, 15, 'مَّنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًا', 'f5c55173eae818d48300733a24fd783f1bced557c79930d641ed8cd227d5bf81', 'مَّنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًا', 'f5c55173eae818d48300733a24fd783f1bced557c79930d641ed8cd227d5bf81', 'f5c55173eae818d48300733a24fd783f1bced557c79930d641ed8cd227d5bf81', NULL, 'من اهتدي فانما يهتدي لنفسه ومن ضل فانما يضل عليها ولا تزر وازره وزر اخري وما كنا معذبين حتي نبعث رسولا', 15, 29, 113, 1, 4, 283, false, NULL),
    (2045, 'tanzil-uthmani-v1.1', 17, 16, 'وَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُوا۟ فِيهَا فَحَقَّ عَلَيْهَا ٱلْقَوْلُ فَدَمَّرْنَٰهَا تَدْمِيرًا', '7da1674b23b49adbce1401793c516dc6906e8ffa8c5a198cdaf43a9d82056766', 'وَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُوا۟ فِيهَا فَحَقَّ عَلَيْهَا ٱلْقَوْلُ فَدَمَّرْنَٰهَا تَدْمِيرًا', '7da1674b23b49adbce1401793c516dc6906e8ffa8c5a198cdaf43a9d82056766', '7da1674b23b49adbce1401793c516dc6906e8ffa8c5a198cdaf43a9d82056766', NULL, 'واذا اردنا ان نهلك قريه امرنا مترفيها ففسقوا فيها فحق عليها القول فدمرنها تدميرا', 15, 29, 113, 1, 4, 283, false, NULL),
    (2046, 'tanzil-uthmani-v1.1', 17, 17, 'وَكَمْ أَهْلَكْنَا مِنَ ٱلْقُرُونِ مِنۢ بَعْدِ نُوحٍ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرًۢا بَصِيرًا', '5e9b928025a94f338f9ffbc2544d359352a9a6fca9ec9f7f2d643a9ec2024cf9', 'وَكَمْ أَهْلَكْنَا مِنَ ٱلْقُرُونِ مِنۢ بَعْدِ نُوحٍ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرًۢا بَصِيرًا', '5e9b928025a94f338f9ffbc2544d359352a9a6fca9ec9f7f2d643a9ec2024cf9', '5e9b928025a94f338f9ffbc2544d359352a9a6fca9ec9f7f2d643a9ec2024cf9', NULL, 'وكم اهلكنا من القرون من بعد نوح وكفي بربك بذنوب عباده خبيرا بصيرا', 15, 29, 113, 1, 4, 283, false, NULL),
    (2047, 'tanzil-uthmani-v1.1', 17, 18, 'مَّن كَانَ يُرِيدُ ٱلْعَاجِلَةَ عَجَّلْنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُۥ جَهَنَّمَ يَصْلَىٰهَا مَذْمُومًا مَّدْحُورًا', '3916724d9bc3efca07b482f672845639d4c1cdbf06deb75d6c63116c8cb54d80', 'مَّن كَانَ يُرِيدُ ٱلْعَاجِلَةَ عَجَّلْنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُۥ جَهَنَّمَ يَصْلَىٰهَا مَذْمُومًا مَّدْحُورًا', '3916724d9bc3efca07b482f672845639d4c1cdbf06deb75d6c63116c8cb54d80', '3916724d9bc3efca07b482f672845639d4c1cdbf06deb75d6c63116c8cb54d80', NULL, 'من كان يريد العاجله عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصليها مذموما مدحورا', 15, 29, 113, 1, 4, 284, false, NULL),
    (2048, 'tanzil-uthmani-v1.1', 17, 19, 'وَمَنْ أَرَادَ ٱلْـَٔاخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ كَانَ سَعْيُهُم مَّشْكُورًا', '854d200205249eab6bbbe644c25515d7b3c651f4d6e5d9dd02d99b789abbbeb0', 'وَمَنْ أَرَادَ ٱلْـَٔاخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ كَانَ سَعْيُهُم مَّشْكُورًا', '854d200205249eab6bbbe644c25515d7b3c651f4d6e5d9dd02d99b789abbbeb0', '854d200205249eab6bbbe644c25515d7b3c651f4d6e5d9dd02d99b789abbbeb0', NULL, 'ومن اراد الاخره وسعي لها سعيها وهو مؤمن فاولئك كان سعيهم مشكورا', 15, 29, 113, 1, 4, 284, false, NULL),
    (2049, 'tanzil-uthmani-v1.1', 17, 20, 'كُلًّا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنْ عَطَآءِ رَبِّكَ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحْظُورًا', '6ae2a295f80d7e2d1e9aa4cd98db88df2bf3c4ea4852919dfc411f698dc95881', 'كُلًّا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنْ عَطَآءِ رَبِّكَ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحْظُورًا', '6ae2a295f80d7e2d1e9aa4cd98db88df2bf3c4ea4852919dfc411f698dc95881', '6ae2a295f80d7e2d1e9aa4cd98db88df2bf3c4ea4852919dfc411f698dc95881', NULL, 'كلا نمد هؤلاء وهؤلاء من عطاء ربك وما كان عطاء ربك محظورا', 15, 29, 113, 1, 4, 284, false, NULL),
    (2050, 'tanzil-uthmani-v1.1', 17, 21, 'ٱنظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ وَلَلْـَٔاخِرَةُ أَكْبَرُ دَرَجَٰتٍ وَأَكْبَرُ تَفْضِيلًا', '77ee2588ef7d18d855d154e1ab2be7194bf67cdf278f3959b6a7b0bb1f991aeb', 'ٱنظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ وَلَلْـَٔاخِرَةُ أَكْبَرُ دَرَجَٰتٍ وَأَكْبَرُ تَفْضِيلًا', '77ee2588ef7d18d855d154e1ab2be7194bf67cdf278f3959b6a7b0bb1f991aeb', '77ee2588ef7d18d855d154e1ab2be7194bf67cdf278f3959b6a7b0bb1f991aeb', NULL, 'انظر كيف فضلنا بعضهم علي بعض وللاخره اكبر درجت واكبر تفضيلا', 15, 29, 113, 1, 4, 284, false, NULL),
    (2051, 'tanzil-uthmani-v1.1', 17, 22, 'لَّا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقْعُدَ مَذْمُومًا مَّخْذُولًا', '74387bc1ede0e8f68cb412176e2f103dff9c40902b9ac9cbac2b8344d0367421', 'لَّا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقْعُدَ مَذْمُومًا مَّخْذُولًا', '74387bc1ede0e8f68cb412176e2f103dff9c40902b9ac9cbac2b8344d0367421', '74387bc1ede0e8f68cb412176e2f103dff9c40902b9ac9cbac2b8344d0367421', NULL, 'لا تجعل مع الله الها ءاخر فتقعد مذموما مخذولا', 15, 29, 113, 1, 4, 284, false, NULL),
    (2052, 'tanzil-uthmani-v1.1', 17, 23, 'وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًا كَرِيمًا', '06f04bfcd05ad18dcc4b39b80f74531ab461a362cd598cb072f67472aea2cf8e', 'وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًا كَرِيمًا', '06f04bfcd05ad18dcc4b39b80f74531ab461a362cd598cb072f67472aea2cf8e', '06f04bfcd05ad18dcc4b39b80f74531ab461a362cd598cb072f67472aea2cf8e', NULL, 'وقضي ربك الا تعبدوا الا اياه وبالولدين احسنا اما يبلغن عندك الكبر احدهما او كلاهما فلا تقل لهما اف ولا تنهرهما وقل لهما قولا كريما', 15, 29, 114, 1, 4, 284, false, NULL),
    (2053, 'tanzil-uthmani-v1.1', 17, 24, 'وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًا', '9982e021e645e65c077f10a4d34693663d1437fed1855e15aa0b9a0c9f5f0a93', 'وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًا', '9982e021e645e65c077f10a4d34693663d1437fed1855e15aa0b9a0c9f5f0a93', '9982e021e645e65c077f10a4d34693663d1437fed1855e15aa0b9a0c9f5f0a93', NULL, 'واخفض لهما جناح الذل من الرحمه وقل رب ارحمهما كما ربياني صغيرا', 15, 29, 114, 1, 4, 284, false, NULL),
    (2054, 'tanzil-uthmani-v1.1', 17, 25, 'رَّبُّكُمْ أَعْلَمُ بِمَا فِى نُفُوسِكُمْ إِن تَكُونُوا۟ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلْأَوَّٰبِينَ غَفُورًا', 'b1aa3140592aa220feb5da5d6c02ca43e273bbce6637ab8e16396c1e29957cb7', 'رَّبُّكُمْ أَعْلَمُ بِمَا فِى نُفُوسِكُمْ إِن تَكُونُوا۟ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلْأَوَّٰبِينَ غَفُورًا', 'b1aa3140592aa220feb5da5d6c02ca43e273bbce6637ab8e16396c1e29957cb7', 'b1aa3140592aa220feb5da5d6c02ca43e273bbce6637ab8e16396c1e29957cb7', NULL, 'ربكم اعلم بما في نفوسكم ان تكونوا صلحين فانه كان للاوبين غفورا', 15, 29, 114, 1, 4, 284, false, NULL),
    (2055, 'tanzil-uthmani-v1.1', 17, 26, 'وَءَاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ وَلَا تُبَذِّرْ تَبْذِيرًا', 'cc43de4b3399528ef3efb2e799b0b67a3f436010168079688cfd0f6416f2e01c', 'وَءَاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ وَلَا تُبَذِّرْ تَبْذِيرًا', 'cc43de4b3399528ef3efb2e799b0b67a3f436010168079688cfd0f6416f2e01c', 'cc43de4b3399528ef3efb2e799b0b67a3f436010168079688cfd0f6416f2e01c', NULL, 'وءات ذا القربي حقه والمسكين وابن السبيل ولا تبذر تبذيرا', 15, 29, 114, 1, 4, 284, false, NULL),
    (2056, 'tanzil-uthmani-v1.1', 17, 27, 'إِنَّ ٱلْمُبَذِّرِينَ كَانُوٓا۟ إِخْوَٰنَ ٱلشَّيَٰطِينِ وَكَانَ ٱلشَّيْطَٰنُ لِرَبِّهِۦ كَفُورًا', 'aa1eeb36ede32fd08ff06f44816989af46b299721f66e69eeeb09d7e0941bea9', 'إِنَّ ٱلْمُبَذِّرِينَ كَانُوٓا۟ إِخْوَٰنَ ٱلشَّيَٰطِينِ وَكَانَ ٱلشَّيْطَٰنُ لِرَبِّهِۦ كَفُورًا', 'aa1eeb36ede32fd08ff06f44816989af46b299721f66e69eeeb09d7e0941bea9', 'aa1eeb36ede32fd08ff06f44816989af46b299721f66e69eeeb09d7e0941bea9', NULL, 'ان المبذرين كانوا اخون الشيطين وكان الشيطن لربه كفورا', 15, 29, 114, 1, 4, 284, false, NULL),
    (2057, 'tanzil-uthmani-v1.1', 17, 28, 'وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ٱبْتِغَآءَ رَحْمَةٍ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًا مَّيْسُورًا', 'd26be79d9f58fb7f49ac26abf0c2bcaa221206c1d35a3b36f2e3ced9d0091968', 'وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ٱبْتِغَآءَ رَحْمَةٍ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًا مَّيْسُورًا', 'd26be79d9f58fb7f49ac26abf0c2bcaa221206c1d35a3b36f2e3ced9d0091968', 'd26be79d9f58fb7f49ac26abf0c2bcaa221206c1d35a3b36f2e3ced9d0091968', NULL, 'واما تعرضن عنهم ابتغاء رحمه من ربك ترجوها فقل لهم قولا ميسورا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2058, 'tanzil-uthmani-v1.1', 17, 29, 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ ٱلْبَسْطِ فَتَقْعُدَ مَلُومًا مَّحْسُورًا', 'b7be00f2363ddfe79ad3d1d6129d5b6518aeff05d04c87675491196c90d66a7d', 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ ٱلْبَسْطِ فَتَقْعُدَ مَلُومًا مَّحْسُورًا', 'b7be00f2363ddfe79ad3d1d6129d5b6518aeff05d04c87675491196c90d66a7d', 'b7be00f2363ddfe79ad3d1d6129d5b6518aeff05d04c87675491196c90d66a7d', NULL, 'ولا تجعل يدك مغلوله الي عنقك ولا تبسطها كل البسط فتقعد ملوما محسورا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2059, 'tanzil-uthmani-v1.1', 17, 30, 'إِنَّ رَبَّكَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'a59387e4eddff937f05b218d890ba4d45dfb966928542962f201e2fb081f37d6', 'إِنَّ رَبَّكَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'a59387e4eddff937f05b218d890ba4d45dfb966928542962f201e2fb081f37d6', 'a59387e4eddff937f05b218d890ba4d45dfb966928542962f201e2fb081f37d6', NULL, 'ان ربك يبسط الرزق لمن يشاء ويقدر انه كان بعباده خبيرا بصيرا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2060, 'tanzil-uthmani-v1.1', 17, 31, 'وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُمْ خَشْيَةَ إِمْلَٰقٍ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ إِنَّ قَتْلَهُمْ كَانَ خِطْـًٔا كَبِيرًا', '9ae0ae45451e0c08a2b4a9f845a20d1c3dfbb15eaafef8c9a09e18f99e124042', 'وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُمْ خَشْيَةَ إِمْلَٰقٍ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ إِنَّ قَتْلَهُمْ كَانَ خِطْـًٔا كَبِيرًا', '9ae0ae45451e0c08a2b4a9f845a20d1c3dfbb15eaafef8c9a09e18f99e124042', '9ae0ae45451e0c08a2b4a9f845a20d1c3dfbb15eaafef8c9a09e18f99e124042', NULL, 'ولا تقتلوا اولدكم خشيه املق نحن نرزقهم واياكم ان قتلهم كان خطا كبيرا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2061, 'tanzil-uthmani-v1.1', 17, 32, 'وَلَا تَقْرَبُوا۟ ٱلزِّنَىٰٓ إِنَّهُۥ كَانَ فَٰحِشَةً وَسَآءَ سَبِيلًا', 'd020b1adc4f529243c914cd46783e32f8c7d28fb4bf1b81f40c49250820bc6a4', 'وَلَا تَقْرَبُوا۟ ٱلزِّنَىٰٓ إِنَّهُۥ كَانَ فَٰحِشَةً وَسَآءَ سَبِيلًا', 'd020b1adc4f529243c914cd46783e32f8c7d28fb4bf1b81f40c49250820bc6a4', 'd020b1adc4f529243c914cd46783e32f8c7d28fb4bf1b81f40c49250820bc6a4', NULL, 'ولا تقربوا الزني انه كان فحشه وساء سبيلا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2062, 'tanzil-uthmani-v1.1', 17, 33, 'وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَمَن قُتِلَ مَظْلُومًا فَقَدْ جَعَلْنَا لِوَلِيِّهِۦ سُلْطَٰنًا فَلَا يُسْرِف فِّى ٱلْقَتْلِ إِنَّهُۥ كَانَ مَنصُورًا', '348c741b2982c43a2b267d53a675134384e29ce5c84f062a521fb9e3b0095345', 'وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَمَن قُتِلَ مَظْلُومًا فَقَدْ جَعَلْنَا لِوَلِيِّهِۦ سُلْطَٰنًا فَلَا يُسْرِف فِّى ٱلْقَتْلِ إِنَّهُۥ كَانَ مَنصُورًا', '348c741b2982c43a2b267d53a675134384e29ce5c84f062a521fb9e3b0095345', '348c741b2982c43a2b267d53a675134384e29ce5c84f062a521fb9e3b0095345', NULL, 'ولا تقتلوا النفس التي حرم الله الا بالحق ومن قتل مظلوما فقد جعلنا لوليه سلطنا فلا يسرف في القتل انه كان منصورا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2063, 'tanzil-uthmani-v1.1', 17, 34, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ وَأَوْفُوا۟ بِٱلْعَهْدِ إِنَّ ٱلْعَهْدَ كَانَ مَسْـُٔولًا', 'a29c037039bcd1c690de9f76569bbb5c54aef22306bd59979d1760a685755886', 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ وَأَوْفُوا۟ بِٱلْعَهْدِ إِنَّ ٱلْعَهْدَ كَانَ مَسْـُٔولًا', 'a29c037039bcd1c690de9f76569bbb5c54aef22306bd59979d1760a685755886', 'a29c037039bcd1c690de9f76569bbb5c54aef22306bd59979d1760a685755886', NULL, 'ولا تقربوا مال اليتيم الا بالتي هي احسن حتي يبلغ اشده واوفوا بالعهد ان العهد كان مسولا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2064, 'tanzil-uthmani-v1.1', 17, 35, 'وَأَوْفُوا۟ ٱلْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', '9f43be0e838c8e7a4c22847ffedde4f4cd36488164c5731b39b530ddaefdfcd6', 'وَأَوْفُوا۟ ٱلْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا', '9f43be0e838c8e7a4c22847ffedde4f4cd36488164c5731b39b530ddaefdfcd6', '9f43be0e838c8e7a4c22847ffedde4f4cd36488164c5731b39b530ddaefdfcd6', NULL, 'واوفوا الكيل اذا كلتم وزنوا بالقسطاس المستقيم ذلك خير واحسن تاويلا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2065, 'tanzil-uthmani-v1.1', 17, 36, 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ إِنَّ ٱلسَّمْعَ وَٱلْبَصَرَ وَٱلْفُؤَادَ كُلُّ أُو۟لَٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولًا', 'bce51116b7a447b70c57a82a6ee6bedaddd3b4ceb77148c06819518a68155f70', 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ إِنَّ ٱلسَّمْعَ وَٱلْبَصَرَ وَٱلْفُؤَادَ كُلُّ أُو۟لَٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولًا', 'bce51116b7a447b70c57a82a6ee6bedaddd3b4ceb77148c06819518a68155f70', 'bce51116b7a447b70c57a82a6ee6bedaddd3b4ceb77148c06819518a68155f70', NULL, 'ولا تقف ما ليس لك به علم ان السمع والبصر والفؤاد كل اولئك كان عنه مسولا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2066, 'tanzil-uthmani-v1.1', 17, 37, 'وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا إِنَّكَ لَن تَخْرِقَ ٱلْأَرْضَ وَلَن تَبْلُغَ ٱلْجِبَالَ طُولًا', 'de7d92edd36d0167b03010ffd22cd02dbfa634c8d05d26d4c2d1ae043e6e0afa', 'وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا إِنَّكَ لَن تَخْرِقَ ٱلْأَرْضَ وَلَن تَبْلُغَ ٱلْجِبَالَ طُولًا', 'de7d92edd36d0167b03010ffd22cd02dbfa634c8d05d26d4c2d1ae043e6e0afa', 'de7d92edd36d0167b03010ffd22cd02dbfa634c8d05d26d4c2d1ae043e6e0afa', NULL, 'ولا تمش في الارض مرحا انك لن تخرق الارض ولن تبلغ الجبال طولا', 15, 29, 114, 1, 4, 285, false, NULL),
    (2067, 'tanzil-uthmani-v1.1', 17, 38, 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكْرُوهًا', '48c121ca89f929b5486b9e0a19e9553c4ad329a19d382f13ac268a90e3c9406d', 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكْرُوهًا', '48c121ca89f929b5486b9e0a19e9553c4ad329a19d382f13ac268a90e3c9406d', '48c121ca89f929b5486b9e0a19e9553c4ad329a19d382f13ac268a90e3c9406d', NULL, 'كل ذلك كان سيئه عند ربك مكروها', 15, 29, 114, 1, 4, 285, false, NULL),
    (2068, 'tanzil-uthmani-v1.1', 17, 39, 'ذَٰلِكَ مِمَّآ أَوْحَىٰٓ إِلَيْكَ رَبُّكَ مِنَ ٱلْحِكْمَةِ وَلَا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلْقَىٰ فِى جَهَنَّمَ مَلُومًا مَّدْحُورًا', '0c25c4ac5f32001348fc26512d28c589d186a74c10b0958727424ccbf499ba46', 'ذَٰلِكَ مِمَّآ أَوْحَىٰٓ إِلَيْكَ رَبُّكَ مِنَ ٱلْحِكْمَةِ وَلَا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلْقَىٰ فِى جَهَنَّمَ مَلُومًا مَّدْحُورًا', '0c25c4ac5f32001348fc26512d28c589d186a74c10b0958727424ccbf499ba46', '0c25c4ac5f32001348fc26512d28c589d186a74c10b0958727424ccbf499ba46', NULL, 'ذلك مما اوحي اليك ربك من الحكمه ولا تجعل مع الله الها ءاخر فتلقي في جهنم ملوما مدحورا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2069, 'tanzil-uthmani-v1.1', 17, 40, 'أَفَأَصْفَىٰكُمْ رَبُّكُم بِٱلْبَنِينَ وَٱتَّخَذَ مِنَ ٱلْمَلَٰٓئِكَةِ إِنَٰثًا إِنَّكُمْ لَتَقُولُونَ قَوْلًا عَظِيمًا', 'a41558f22d9b16f350ea2ae8ef26419ea8fb688f8ff337c813f969a2fd2ea314', 'أَفَأَصْفَىٰكُمْ رَبُّكُم بِٱلْبَنِينَ وَٱتَّخَذَ مِنَ ٱلْمَلَٰٓئِكَةِ إِنَٰثًا إِنَّكُمْ لَتَقُولُونَ قَوْلًا عَظِيمًا', 'a41558f22d9b16f350ea2ae8ef26419ea8fb688f8ff337c813f969a2fd2ea314', 'a41558f22d9b16f350ea2ae8ef26419ea8fb688f8ff337c813f969a2fd2ea314', NULL, 'افاصفيكم ربكم بالبنين واتخذ من الملئكه انثا انكم لتقولون قولا عظيما', 15, 29, 114, 1, 4, 286, false, NULL),
    (2070, 'tanzil-uthmani-v1.1', 17, 41, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِيَذَّكَّرُوا۟ وَمَا يَزِيدُهُمْ إِلَّا نُفُورًا', '722b69afe44e9cf48ea700df5c08d4d8d871b9969a7cbefef95a95540a0e1897', 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِيَذَّكَّرُوا۟ وَمَا يَزِيدُهُمْ إِلَّا نُفُورًا', '722b69afe44e9cf48ea700df5c08d4d8d871b9969a7cbefef95a95540a0e1897', '722b69afe44e9cf48ea700df5c08d4d8d871b9969a7cbefef95a95540a0e1897', NULL, 'ولقد صرفنا في هذا القرءان ليذكروا وما يزيدهم الا نفورا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2071, 'tanzil-uthmani-v1.1', 17, 42, 'قُل لَّوْ كَانَ مَعَهُۥٓ ءَالِهَةٌ كَمَا يَقُولُونَ إِذًا لَّٱبْتَغَوْا۟ إِلَىٰ ذِى ٱلْعَرْشِ سَبِيلًا', '510ce551c20ee3e1595d02c7077c9fa3ce80805d1a3fda7d7512b53a5e86d42c', 'قُل لَّوْ كَانَ مَعَهُۥٓ ءَالِهَةٌ كَمَا يَقُولُونَ إِذًا لَّٱبْتَغَوْا۟ إِلَىٰ ذِى ٱلْعَرْشِ سَبِيلًا', '510ce551c20ee3e1595d02c7077c9fa3ce80805d1a3fda7d7512b53a5e86d42c', '510ce551c20ee3e1595d02c7077c9fa3ce80805d1a3fda7d7512b53a5e86d42c', NULL, 'قل لو كان معه ءالهه كما يقولون اذا لابتغوا الي ذي العرش سبيلا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2072, 'tanzil-uthmani-v1.1', 17, 43, 'سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوًّا كَبِيرًا', '8ee6293029211d311468137426147d49a901e9e062b5fff52c28adf8ac1e515e', 'سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوًّا كَبِيرًا', '8ee6293029211d311468137426147d49a901e9e062b5fff52c28adf8ac1e515e', '8ee6293029211d311468137426147d49a901e9e062b5fff52c28adf8ac1e515e', NULL, 'سبحنه وتعلي عما يقولون علوا كبيرا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2073, 'tanzil-uthmani-v1.1', 17, 44, 'تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَٰكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', 'c8e710f4928511aceacbd0c4c6fa87a1c5d68cd68c3d3b0e99e8f9cdd5a8d716', 'تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَٰكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', 'c8e710f4928511aceacbd0c4c6fa87a1c5d68cd68c3d3b0e99e8f9cdd5a8d716', 'c8e710f4928511aceacbd0c4c6fa87a1c5d68cd68c3d3b0e99e8f9cdd5a8d716', NULL, 'تسبح له السموت السبع والارض ومن فيهن وان من شيء الا يسبح بحمده ولكن لا تفقهون تسبيحهم انه كان حليما غفورا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2074, 'tanzil-uthmani-v1.1', 17, 45, 'وَإِذَا قَرَأْتَ ٱلْقُرْءَانَ جَعَلْنَا بَيْنَكَ وَبَيْنَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ حِجَابًا مَّسْتُورًا', 'a598d236628911ca080f3733a3c7990977a07bf6d2621689fb3ceb0ecefc1c3c', 'وَإِذَا قَرَأْتَ ٱلْقُرْءَانَ جَعَلْنَا بَيْنَكَ وَبَيْنَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ حِجَابًا مَّسْتُورًا', 'a598d236628911ca080f3733a3c7990977a07bf6d2621689fb3ceb0ecefc1c3c', 'a598d236628911ca080f3733a3c7990977a07bf6d2621689fb3ceb0ecefc1c3c', NULL, 'واذا قرات القرءان جعلنا بينك وبين الذين لا يؤمنون بالاخره حجابا مستورا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2075, 'tanzil-uthmani-v1.1', 17, 46, 'وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِذَا ذَكَرْتَ رَبَّكَ فِى ٱلْقُرْءَانِ وَحْدَهُۥ وَلَّوْا۟ عَلَىٰٓ أَدْبَٰرِهِمْ نُفُورًا', 'e93436d12de6242330bb0b65cfa72037814e0deb2f500ca83f65b0af620a2a54', 'وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِذَا ذَكَرْتَ رَبَّكَ فِى ٱلْقُرْءَانِ وَحْدَهُۥ وَلَّوْا۟ عَلَىٰٓ أَدْبَٰرِهِمْ نُفُورًا', 'e93436d12de6242330bb0b65cfa72037814e0deb2f500ca83f65b0af620a2a54', 'e93436d12de6242330bb0b65cfa72037814e0deb2f500ca83f65b0af620a2a54', NULL, 'وجعلنا علي قلوبهم اكنه ان يفقهوه وفي ءاذانهم وقرا واذا ذكرت ربك في القرءان وحده ولوا علي ادبرهم نفورا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2076, 'tanzil-uthmani-v1.1', 17, 47, 'نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِۦٓ إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَجْوَىٰٓ إِذْ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', 'ffa64f65ff73f2918d2f446cf9ebc7de7c19eb2f536f8bfe377b4cb65bfa9a72', 'نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِۦٓ إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَجْوَىٰٓ إِذْ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', 'ffa64f65ff73f2918d2f446cf9ebc7de7c19eb2f536f8bfe377b4cb65bfa9a72', 'ffa64f65ff73f2918d2f446cf9ebc7de7c19eb2f536f8bfe377b4cb65bfa9a72', NULL, 'نحن اعلم بما يستمعون به اذ يستمعون اليك واذ هم نجوي اذ يقول الظلمون ان تتبعون الا رجلا مسحورا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2077, 'tanzil-uthmani-v1.1', 17, 48, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَالَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', 'f4d58f77e9ebda361d00ea0d863b6c6c9cb142c64a71151fffe5aae3894da96e', 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَالَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', 'f4d58f77e9ebda361d00ea0d863b6c6c9cb142c64a71151fffe5aae3894da96e', 'f4d58f77e9ebda361d00ea0d863b6c6c9cb142c64a71151fffe5aae3894da96e', NULL, 'انظر كيف ضربوا لك الامثال فضلوا فلا يستطيعون سبيلا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2078, 'tanzil-uthmani-v1.1', 17, 49, 'وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', 'e3694832aca6c36ad0b8650460b902374a80b5995c681aa77bc7c2b1eb130c53', 'وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', 'e3694832aca6c36ad0b8650460b902374a80b5995c681aa77bc7c2b1eb130c53', 'e3694832aca6c36ad0b8650460b902374a80b5995c681aa77bc7c2b1eb130c53', NULL, 'وقالوا اءذا كنا عظما ورفتا اءنا لمبعوثون خلقا جديدا', 15, 29, 114, 1, 4, 286, false, NULL),
    (2079, 'tanzil-uthmani-v1.1', 17, 50, 'قُلْ كُونُوا۟ حِجَارَةً أَوْ حَدِيدًا', '2600cfa6cf28bfa10f60b6dc3fe73ca3a172a1b7b1efd7a92559b72fb91ee8a2', 'قُلْ كُونُوا۟ حِجَارَةً أَوْ حَدِيدًا', '2600cfa6cf28bfa10f60b6dc3fe73ca3a172a1b7b1efd7a92559b72fb91ee8a2', '2600cfa6cf28bfa10f60b6dc3fe73ca3a172a1b7b1efd7a92559b72fb91ee8a2', NULL, 'قل كونوا حجاره او حديدا', 15, 29, 115, 1, 4, 287, false, NULL),
    (2080, 'tanzil-uthmani-v1.1', 17, 51, 'أَوْ خَلْقًا مِّمَّا يَكْبُرُ فِى صُدُورِكُمْ فَسَيَقُولُونَ مَن يُعِيدُنَا قُلِ ٱلَّذِى فَطَرَكُمْ أَوَّلَ مَرَّةٍ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ قُلْ عَسَىٰٓ أَن يَكُونَ قَرِيبًا', '584f84642c59bd7384867e80567da5b8558581540458b01ad215bf7565ec0942', 'أَوْ خَلْقًا مِّمَّا يَكْبُرُ فِى صُدُورِكُمْ فَسَيَقُولُونَ مَن يُعِيدُنَا قُلِ ٱلَّذِى فَطَرَكُمْ أَوَّلَ مَرَّةٍ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ قُلْ عَسَىٰٓ أَن يَكُونَ قَرِيبًا', '584f84642c59bd7384867e80567da5b8558581540458b01ad215bf7565ec0942', '584f84642c59bd7384867e80567da5b8558581540458b01ad215bf7565ec0942', NULL, 'او خلقا مما يكبر في صدوركم فسيقولون من يعيدنا قل الذي فطركم اول مره فسينغضون اليك رءوسهم ويقولون متي هو قل عسي ان يكون قريبا', 15, 29, 115, 1, 4, 287, false, NULL),
    (2081, 'tanzil-uthmani-v1.1', 17, 52, 'يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِۦ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا', '4aa08685b1dad2a74bbe75e328b638909b45fabf43274a2d0f883ae6bc97c6fc', 'يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِۦ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا', '4aa08685b1dad2a74bbe75e328b638909b45fabf43274a2d0f883ae6bc97c6fc', '4aa08685b1dad2a74bbe75e328b638909b45fabf43274a2d0f883ae6bc97c6fc', NULL, 'يوم يدعوكم فتستجيبون بحمده وتظنون ان لبثتم الا قليلا', 15, 29, 115, 1, 4, 287, false, NULL),
    (2082, 'tanzil-uthmani-v1.1', 17, 53, 'وَقُل لِّعِبَادِى يَقُولُوا۟ ٱلَّتِى هِىَ أَحْسَنُ إِنَّ ٱلشَّيْطَٰنَ يَنزَغُ بَيْنَهُمْ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلْإِنسَٰنِ عَدُوًّا مُّبِينًا', '8daac97d95ce9e457f2038630607bb162c309bc5609b27091c54953ca5f19681', 'وَقُل لِّعِبَادِى يَقُولُوا۟ ٱلَّتِى هِىَ أَحْسَنُ إِنَّ ٱلشَّيْطَٰنَ يَنزَغُ بَيْنَهُمْ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلْإِنسَٰنِ عَدُوًّا مُّبِينًا', '8daac97d95ce9e457f2038630607bb162c309bc5609b27091c54953ca5f19681', '8daac97d95ce9e457f2038630607bb162c309bc5609b27091c54953ca5f19681', NULL, 'وقل لعبادي يقولوا التي هي احسن ان الشيطن ينزغ بينهم ان الشيطن كان للانسن عدوا مبينا', 15, 29, 115, 1, 4, 287, false, NULL),
    (2083, 'tanzil-uthmani-v1.1', 17, 54, 'رَّبُّكُمْ أَعْلَمُ بِكُمْ إِن يَشَأْ يَرْحَمْكُمْ أَوْ إِن يَشَأْ يُعَذِّبْكُمْ وَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ وَكِيلًا', '5c8c5a14723c20c1faefc5174b3f5fe1834f91b3efeb4ed908145a743c7e0b25', 'رَّبُّكُمْ أَعْلَمُ بِكُمْ إِن يَشَأْ يَرْحَمْكُمْ أَوْ إِن يَشَأْ يُعَذِّبْكُمْ وَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ وَكِيلًا', '5c8c5a14723c20c1faefc5174b3f5fe1834f91b3efeb4ed908145a743c7e0b25', '5c8c5a14723c20c1faefc5174b3f5fe1834f91b3efeb4ed908145a743c7e0b25', NULL, 'ربكم اعلم بكم ان يشا يرحمكم او ان يشا يعذبكم وما ارسلنك عليهم وكيلا', 15, 29, 115, 1, 4, 287, false, NULL),
    (2084, 'tanzil-uthmani-v1.1', 17, 55, 'وَرَبُّكَ أَعْلَمُ بِمَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَقَدْ فَضَّلْنَا بَعْضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعْضٍ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', 'aaa550e0971ad602780ed6d1367fe10e9a914f772d2b5eee8ff8fbe479216ed2', 'وَرَبُّكَ أَعْلَمُ بِمَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَقَدْ فَضَّلْنَا بَعْضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعْضٍ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا', 'aaa550e0971ad602780ed6d1367fe10e9a914f772d2b5eee8ff8fbe479216ed2', 'aaa550e0971ad602780ed6d1367fe10e9a914f772d2b5eee8ff8fbe479216ed2', NULL, 'وربك اعلم بمن في السموت والارض ولقد فضلنا بعض النبين علي بعض وءاتينا داود زبورا', 15, 29, 115, 1, 4, 287, false, NULL),
    (2085, 'tanzil-uthmani-v1.1', 17, 56, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِهِۦ فَلَا يَمْلِكُونَ كَشْفَ ٱلضُّرِّ عَنكُمْ وَلَا تَحْوِيلًا', 'd94083ef808a4e6000d65238dcede2817a81b1e0fa220df2f89beef3828e8e41', 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِهِۦ فَلَا يَمْلِكُونَ كَشْفَ ٱلضُّرِّ عَنكُمْ وَلَا تَحْوِيلًا', 'd94083ef808a4e6000d65238dcede2817a81b1e0fa220df2f89beef3828e8e41', 'd94083ef808a4e6000d65238dcede2817a81b1e0fa220df2f89beef3828e8e41', NULL, 'قل ادعوا الذين زعمتم من دونه فلا يملكون كشف الضر عنكم ولا تحويلا', 15, 29, 115, 1, 4, 287, false, NULL),
    (2086, 'tanzil-uthmani-v1.1', 17, 57, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ ٱلْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا', '94637317a7ffc2763933bd48a32ba7a262eb479508af1a1b01c68670f0efcc2a', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ ٱلْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا', '94637317a7ffc2763933bd48a32ba7a262eb479508af1a1b01c68670f0efcc2a', '94637317a7ffc2763933bd48a32ba7a262eb479508af1a1b01c68670f0efcc2a', NULL, 'اولئك الذين يدعون يبتغون الي ربهم الوسيله ايهم اقرب ويرجون رحمته ويخافون عذابه ان عذاب ربك كان محذورا', 15, 29, 115, 1, 4, 287, false, NULL),
    (2087, 'tanzil-uthmani-v1.1', 17, 58, 'وَإِن مِّن قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ ٱلْقِيَٰمَةِ أَوْ مُعَذِّبُوهَا عَذَابًا شَدِيدًا كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًا', 'f33fca863dff7aac552666fb601dfca8a8df8d93876c821988fb1756a0397649', 'وَإِن مِّن قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ ٱلْقِيَٰمَةِ أَوْ مُعَذِّبُوهَا عَذَابًا شَدِيدًا كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًا', 'f33fca863dff7aac552666fb601dfca8a8df8d93876c821988fb1756a0397649', 'f33fca863dff7aac552666fb601dfca8a8df8d93876c821988fb1756a0397649', NULL, 'وان من قريه الا نحن مهلكوها قبل يوم القيمه او معذبوها عذابا شديدا كان ذلك في الكتب مسطورا', 15, 29, 115, 1, 4, 287, false, NULL),
    (2088, 'tanzil-uthmani-v1.1', 17, 59, 'وَمَا مَنَعَنَآ أَن نُّرْسِلَ بِٱلْـَٔايَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلْأَوَّلُونَ وَءَاتَيْنَا ثَمُودَ ٱلنَّاقَةَ مُبْصِرَةً فَظَلَمُوا۟ بِهَا وَمَا نُرْسِلُ بِٱلْـَٔايَٰتِ إِلَّا تَخْوِيفًا', '50cb762a163ed1c723a9acb1dcd32a73caa87b8c169b4b20a096adfb9e5b9aa3', 'وَمَا مَنَعَنَآ أَن نُّرْسِلَ بِٱلْـَٔايَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلْأَوَّلُونَ وَءَاتَيْنَا ثَمُودَ ٱلنَّاقَةَ مُبْصِرَةً فَظَلَمُوا۟ بِهَا وَمَا نُرْسِلُ بِٱلْـَٔايَٰتِ إِلَّا تَخْوِيفًا', '50cb762a163ed1c723a9acb1dcd32a73caa87b8c169b4b20a096adfb9e5b9aa3', '50cb762a163ed1c723a9acb1dcd32a73caa87b8c169b4b20a096adfb9e5b9aa3', NULL, 'وما منعنا ان نرسل بالايت الا ان كذب بها الاولون وءاتينا ثمود الناقه مبصره فظلموا بها وما نرسل بالايت الا تخويفا', 15, 29, 115, 1, 4, 288, false, NULL),
    (2089, 'tanzil-uthmani-v1.1', 17, 60, 'وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِ وَمَا جَعَلْنَا ٱلرُّءْيَا ٱلَّتِىٓ أَرَيْنَٰكَ إِلَّا فِتْنَةً لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلْمَلْعُونَةَ فِى ٱلْقُرْءَانِ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَٰنًا كَبِيرًا', 'd21ab96888a844cd9e7a3afa654e29e5081f58211f5d85f3ec8b12f7ed3e8875', 'وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِ وَمَا جَعَلْنَا ٱلرُّءْيَا ٱلَّتِىٓ أَرَيْنَٰكَ إِلَّا فِتْنَةً لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلْمَلْعُونَةَ فِى ٱلْقُرْءَانِ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَٰنًا كَبِيرًا', 'd21ab96888a844cd9e7a3afa654e29e5081f58211f5d85f3ec8b12f7ed3e8875', 'd21ab96888a844cd9e7a3afa654e29e5081f58211f5d85f3ec8b12f7ed3e8875', NULL, 'واذ قلنا لك ان ربك احاط بالناس وما جعلنا الرءيا التي ارينك الا فتنه للناس والشجره الملعونه في القرءان ونخوفهم فما يزيدهم الا طغينا كبيرا', 15, 29, 115, 1, 4, 288, false, NULL),
    (2090, 'tanzil-uthmani-v1.1', 17, 61, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ قَالَ ءَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا', '4cf6d97a8754409c4bd432edcd3ded23fc6246678280dc7bfa90fd1897b869b8', 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ قَالَ ءَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا', '4cf6d97a8754409c4bd432edcd3ded23fc6246678280dc7bfa90fd1897b869b8', '4cf6d97a8754409c4bd432edcd3ded23fc6246678280dc7bfa90fd1897b869b8', NULL, 'واذ قلنا للملئكه اسجدوا لادم فسجدوا الا ابليس قال ءاسجد لمن خلقت طينا', 15, 29, 115, 1, 4, 288, false, NULL),
    (2091, 'tanzil-uthmani-v1.1', 17, 62, 'قَالَ أَرَءَيْتَكَ هَٰذَا ٱلَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلًا', '50358d75165d3e65b7fd446cc7f62f397513d53cc801ac9aa16d8d4c59220b3c', 'قَالَ أَرَءَيْتَكَ هَٰذَا ٱلَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلًا', '50358d75165d3e65b7fd446cc7f62f397513d53cc801ac9aa16d8d4c59220b3c', '50358d75165d3e65b7fd446cc7f62f397513d53cc801ac9aa16d8d4c59220b3c', NULL, 'قال ارءيتك هذا الذي كرمت علي لئن اخرتن الي يوم القيمه لاحتنكن ذريته الا قليلا', 15, 29, 115, 1, 4, 288, false, NULL),
    (2092, 'tanzil-uthmani-v1.1', 17, 63, 'قَالَ ٱذْهَبْ فَمَن تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمْ جَزَآءً مَّوْفُورًا', 'a30ca6cfbb57036646089338952f92d937914f208d0d68dd251321b0221324ce', 'قَالَ ٱذْهَبْ فَمَن تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمْ جَزَآءً مَّوْفُورًا', 'a30ca6cfbb57036646089338952f92d937914f208d0d68dd251321b0221324ce', 'a30ca6cfbb57036646089338952f92d937914f208d0d68dd251321b0221324ce', NULL, 'قال اذهب فمن تبعك منهم فان جهنم جزاؤكم جزاء موفورا', 15, 29, 115, 1, 4, 288, false, NULL),
    (2093, 'tanzil-uthmani-v1.1', 17, 64, 'وَٱسْتَفْزِزْ مَنِ ٱسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ وَعِدْهُمْ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 'd998d17f8be4162ad26d84937e0731afb3e81beae4b97119267a7aa4bd6dc7b1', 'وَٱسْتَفْزِزْ مَنِ ٱسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ وَعِدْهُمْ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 'd998d17f8be4162ad26d84937e0731afb3e81beae4b97119267a7aa4bd6dc7b1', 'd998d17f8be4162ad26d84937e0731afb3e81beae4b97119267a7aa4bd6dc7b1', NULL, 'واستفزز من استطعت منهم بصوتك واجلب عليهم بخيلك ورجلك وشاركهم في الامول والاولد وعدهم وما يعدهم الشيطن الا غرورا', 15, 29, 115, 1, 4, 288, false, NULL),
    (2094, 'tanzil-uthmani-v1.1', 17, 65, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ وَكَفَىٰ بِرَبِّكَ وَكِيلًا', '87a8e8ab55b1ea895dbc7be4c806ab4c7704ffd8daaf8f79155fdd734857ea42', 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ وَكَفَىٰ بِرَبِّكَ وَكِيلًا', '87a8e8ab55b1ea895dbc7be4c806ab4c7704ffd8daaf8f79155fdd734857ea42', '87a8e8ab55b1ea895dbc7be4c806ab4c7704ffd8daaf8f79155fdd734857ea42', NULL, 'ان عبادي ليس لك عليهم سلطن وكفي بربك وكيلا', 15, 29, 115, 1, 4, 288, false, NULL),
    (2095, 'tanzil-uthmani-v1.1', 17, 66, 'رَّبُّكُمُ ٱلَّذِى يُزْجِى لَكُمُ ٱلْفُلْكَ فِى ٱلْبَحْرِ لِتَبْتَغُوا۟ مِن فَضْلِهِۦٓ إِنَّهُۥ كَانَ بِكُمْ رَحِيمًا', '4b263e6dc93ebe6644aebd643c43641f986c97aa5a5da7ec71fa1a083559eda2', 'رَّبُّكُمُ ٱلَّذِى يُزْجِى لَكُمُ ٱلْفُلْكَ فِى ٱلْبَحْرِ لِتَبْتَغُوا۟ مِن فَضْلِهِۦٓ إِنَّهُۥ كَانَ بِكُمْ رَحِيمًا', '4b263e6dc93ebe6644aebd643c43641f986c97aa5a5da7ec71fa1a083559eda2', '4b263e6dc93ebe6644aebd643c43641f986c97aa5a5da7ec71fa1a083559eda2', NULL, 'ربكم الذي يزجي لكم الفلك في البحر لتبتغوا من فضله انه كان بكم رحيما', 15, 29, 115, 1, 4, 288, false, NULL),
    (2096, 'tanzil-uthmani-v1.1', 17, 67, 'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِى ٱلْبَحْرِ ضَلَّ مَن تَدْعُونَ إِلَّآ إِيَّاهُ فَلَمَّا نَجَّىٰكُمْ إِلَى ٱلْبَرِّ أَعْرَضْتُمْ وَكَانَ ٱلْإِنسَٰنُ كَفُورًا', '80e265ba77205f7f7932bb3b218e2b8131cd11fd300a8c1e550a34621f23e8f1', 'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِى ٱلْبَحْرِ ضَلَّ مَن تَدْعُونَ إِلَّآ إِيَّاهُ فَلَمَّا نَجَّىٰكُمْ إِلَى ٱلْبَرِّ أَعْرَضْتُمْ وَكَانَ ٱلْإِنسَٰنُ كَفُورًا', '80e265ba77205f7f7932bb3b218e2b8131cd11fd300a8c1e550a34621f23e8f1', '80e265ba77205f7f7932bb3b218e2b8131cd11fd300a8c1e550a34621f23e8f1', NULL, 'واذا مسكم الضر في البحر ضل من تدعون الا اياه فلما نجيكم الي البر اعرضتم وكان الانسن كفورا', 15, 29, 115, 1, 4, 289, false, NULL),
    (2097, 'tanzil-uthmani-v1.1', 17, 68, 'أَفَأَمِنتُمْ أَن يَخْسِفَ بِكُمْ جَانِبَ ٱلْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا ثُمَّ لَا تَجِدُوا۟ لَكُمْ وَكِيلًا', 'af3e6c50313d3d82cf68e68edb89ed922ede6c8708b2b3fdfee99e0cf027f29c', 'أَفَأَمِنتُمْ أَن يَخْسِفَ بِكُمْ جَانِبَ ٱلْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا ثُمَّ لَا تَجِدُوا۟ لَكُمْ وَكِيلًا', 'af3e6c50313d3d82cf68e68edb89ed922ede6c8708b2b3fdfee99e0cf027f29c', 'af3e6c50313d3d82cf68e68edb89ed922ede6c8708b2b3fdfee99e0cf027f29c', NULL, 'افامنتم ان يخسف بكم جانب البر او يرسل عليكم حاصبا ثم لا تجدوا لكم وكيلا', 15, 29, 115, 1, 4, 289, false, NULL),
    (2098, 'tanzil-uthmani-v1.1', 17, 69, 'أَمْ أَمِنتُمْ أَن يُعِيدَكُمْ فِيهِ تَارَةً أُخْرَىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِفًا مِّنَ ٱلرِّيحِ فَيُغْرِقَكُم بِمَا كَفَرْتُمْ ثُمَّ لَا تَجِدُوا۟ لَكُمْ عَلَيْنَا بِهِۦ تَبِيعًا', '71e10a3ee730d375ae8bc137cc3178a2872f964aa4b0bea08fcb29c7541c4bab', 'أَمْ أَمِنتُمْ أَن يُعِيدَكُمْ فِيهِ تَارَةً أُخْرَىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِفًا مِّنَ ٱلرِّيحِ فَيُغْرِقَكُم بِمَا كَفَرْتُمْ ثُمَّ لَا تَجِدُوا۟ لَكُمْ عَلَيْنَا بِهِۦ تَبِيعًا', '71e10a3ee730d375ae8bc137cc3178a2872f964aa4b0bea08fcb29c7541c4bab', '71e10a3ee730d375ae8bc137cc3178a2872f964aa4b0bea08fcb29c7541c4bab', NULL, 'ام امنتم ان يعيدكم فيه تاره اخري فيرسل عليكم قاصفا من الريح فيغرقكم بما كفرتم ثم لا تجدوا لكم علينا به تبيعا', 15, 29, 115, 1, 4, 289, false, NULL),
    (2099, 'tanzil-uthmani-v1.1', 17, 70, 'وَلَقَدْ كَرَّمْنَا بَنِىٓ ءَادَمَ وَحَمَلْنَٰهُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَىٰ كَثِيرٍ مِّمَّنْ خَلَقْنَا تَفْضِيلًا', '2ff0cfa27e9f09bf69b919e954b02a2c44008569aeb8505467e80708ba08e14c', 'وَلَقَدْ كَرَّمْنَا بَنِىٓ ءَادَمَ وَحَمَلْنَٰهُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَىٰ كَثِيرٍ مِّمَّنْ خَلَقْنَا تَفْضِيلًا', '2ff0cfa27e9f09bf69b919e954b02a2c44008569aeb8505467e80708ba08e14c', '2ff0cfa27e9f09bf69b919e954b02a2c44008569aeb8505467e80708ba08e14c', NULL, 'ولقد كرمنا بني ءادم وحملنهم في البر والبحر ورزقنهم من الطيبت وفضلنهم علي كثير ممن خلقنا تفضيلا', 15, 29, 116, 1, 4, 289, false, NULL),
    (2100, 'tanzil-uthmani-v1.1', 17, 71, 'يَوْمَ نَدْعُوا۟ كُلَّ أُنَاسٍۭ بِإِمَٰمِهِمْ فَمَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُو۟لَٰٓئِكَ يَقْرَءُونَ كِتَٰبَهُمْ وَلَا يُظْلَمُونَ فَتِيلًا', 'eff50622fabb04060ce23bfee5378b7753fa2f91cbfb684a683367868a9a5298', 'يَوْمَ نَدْعُوا۟ كُلَّ أُنَاسٍۭ بِإِمَٰمِهِمْ فَمَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُو۟لَٰٓئِكَ يَقْرَءُونَ كِتَٰبَهُمْ وَلَا يُظْلَمُونَ فَتِيلًا', 'eff50622fabb04060ce23bfee5378b7753fa2f91cbfb684a683367868a9a5298', 'eff50622fabb04060ce23bfee5378b7753fa2f91cbfb684a683367868a9a5298', NULL, 'يوم ندعوا كل اناس باممهم فمن اوتي كتبه بيمينه فاولئك يقرءون كتبهم ولا يظلمون فتيلا', 15, 29, 116, 1, 4, 289, false, NULL),
    (2101, 'tanzil-uthmani-v1.1', 17, 72, 'وَمَن كَانَ فِى هَٰذِهِۦٓ أَعْمَىٰ فَهُوَ فِى ٱلْـَٔاخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلًا', '1831217f30a0ea58bf1c84180c3931fa88098328ab6031bbfb1c60ff5e3f306e', 'وَمَن كَانَ فِى هَٰذِهِۦٓ أَعْمَىٰ فَهُوَ فِى ٱلْـَٔاخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلًا', '1831217f30a0ea58bf1c84180c3931fa88098328ab6031bbfb1c60ff5e3f306e', '1831217f30a0ea58bf1c84180c3931fa88098328ab6031bbfb1c60ff5e3f306e', NULL, 'ومن كان في هذه اعمي فهو في الاخره اعمي واضل سبيلا', 15, 29, 116, 1, 4, 289, false, NULL),
    (2102, 'tanzil-uthmani-v1.1', 17, 73, 'وَإِن كَادُوا۟ لَيَفْتِنُونَكَ عَنِ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ لِتَفْتَرِىَ عَلَيْنَا غَيْرَهُۥ وَإِذًا لَّٱتَّخَذُوكَ خَلِيلًا', '663a451b2e64e7a67f29b21fbfed8db8cb1135d3f8add34ff058c24714169eb9', 'وَإِن كَادُوا۟ لَيَفْتِنُونَكَ عَنِ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ لِتَفْتَرِىَ عَلَيْنَا غَيْرَهُۥ وَإِذًا لَّٱتَّخَذُوكَ خَلِيلًا', '663a451b2e64e7a67f29b21fbfed8db8cb1135d3f8add34ff058c24714169eb9', '663a451b2e64e7a67f29b21fbfed8db8cb1135d3f8add34ff058c24714169eb9', NULL, 'وان كادوا ليفتنونك عن الذي اوحينا اليك لتفتري علينا غيره واذا لاتخذوك خليلا', 15, 29, 116, 1, 4, 289, false, NULL),
    (2103, 'tanzil-uthmani-v1.1', 17, 74, 'وَلَوْلَآ أَن ثَبَّتْنَٰكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْـًٔا قَلِيلًا', '8bbad59cba4b05e94443ce8d406b1bd086a7d1ffbdcc9feac13abd19c0877bec', 'وَلَوْلَآ أَن ثَبَّتْنَٰكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْـًٔا قَلِيلًا', '8bbad59cba4b05e94443ce8d406b1bd086a7d1ffbdcc9feac13abd19c0877bec', '8bbad59cba4b05e94443ce8d406b1bd086a7d1ffbdcc9feac13abd19c0877bec', NULL, 'ولولا ان ثبتنك لقد كدت تركن اليهم شيا قليلا', 15, 29, 116, 1, 4, 289, false, NULL),
    (2104, 'tanzil-uthmani-v1.1', 17, 75, 'إِذًا لَّأَذَقْنَٰكَ ضِعْفَ ٱلْحَيَوٰةِ وَضِعْفَ ٱلْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًا', '2164238d3c2de30687c6fe7d37860b32bf29a9cbc724a8a7fb46135b2d5d2175', 'إِذًا لَّأَذَقْنَٰكَ ضِعْفَ ٱلْحَيَوٰةِ وَضِعْفَ ٱلْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًا', '2164238d3c2de30687c6fe7d37860b32bf29a9cbc724a8a7fb46135b2d5d2175', '2164238d3c2de30687c6fe7d37860b32bf29a9cbc724a8a7fb46135b2d5d2175', NULL, 'اذا لاذقنك ضعف الحيوه وضعف الممات ثم لا تجد لك علينا نصيرا', 15, 29, 116, 1, 4, 289, false, NULL),
    (2105, 'tanzil-uthmani-v1.1', 17, 76, 'وَإِن كَادُوا۟ لَيَسْتَفِزُّونَكَ مِنَ ٱلْأَرْضِ لِيُخْرِجُوكَ مِنْهَا وَإِذًا لَّا يَلْبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلًا', '5048774968187699e0fd4aacfb8b3f83626581b8f412e7af83913132bf72b340', 'وَإِن كَادُوا۟ لَيَسْتَفِزُّونَكَ مِنَ ٱلْأَرْضِ لِيُخْرِجُوكَ مِنْهَا وَإِذًا لَّا يَلْبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلًا', '5048774968187699e0fd4aacfb8b3f83626581b8f412e7af83913132bf72b340', '5048774968187699e0fd4aacfb8b3f83626581b8f412e7af83913132bf72b340', NULL, 'وان كادوا ليستفزونك من الارض ليخرجوك منها واذا لا يلبثون خلفك الا قليلا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2106, 'tanzil-uthmani-v1.1', 17, 77, 'سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', 'd9ce8a966d5f1536fb16ab3d30a70cc2e3bc9bca9e2138394a8a57df7d4df72c', 'سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', 'd9ce8a966d5f1536fb16ab3d30a70cc2e3bc9bca9e2138394a8a57df7d4df72c', 'd9ce8a966d5f1536fb16ab3d30a70cc2e3bc9bca9e2138394a8a57df7d4df72c', NULL, 'سنه من قد ارسلنا قبلك من رسلنا ولا تجد لسنتنا تحويلا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2107, 'tanzil-uthmani-v1.1', 17, 78, 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمْسِ إِلَىٰ غَسَقِ ٱلَّيْلِ وَقُرْءَانَ ٱلْفَجْرِ إِنَّ قُرْءَانَ ٱلْفَجْرِ كَانَ مَشْهُودًا', '4e2c1b4fa72456fb44115a78d07baab0201e9a4cd6a13d9124830163dd101d26', 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمْسِ إِلَىٰ غَسَقِ ٱلَّيْلِ وَقُرْءَانَ ٱلْفَجْرِ إِنَّ قُرْءَانَ ٱلْفَجْرِ كَانَ مَشْهُودًا', '4e2c1b4fa72456fb44115a78d07baab0201e9a4cd6a13d9124830163dd101d26', '4e2c1b4fa72456fb44115a78d07baab0201e9a4cd6a13d9124830163dd101d26', NULL, 'اقم الصلوه لدلوك الشمس الي غسق اليل وقرءان الفجر ان قرءان الفجر كان مشهودا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2108, 'tanzil-uthmani-v1.1', 17, 79, 'وَمِنَ ٱلَّيْلِ فَتَهَجَّدْ بِهِۦ نَافِلَةً لَّكَ عَسَىٰٓ أَن يَبْعَثَكَ رَبُّكَ مَقَامًا مَّحْمُودًا', '0fa8722cd721722e90c39ead83dc4055261fd44508c14d0eb719053773d1df55', 'وَمِنَ ٱلَّيْلِ فَتَهَجَّدْ بِهِۦ نَافِلَةً لَّكَ عَسَىٰٓ أَن يَبْعَثَكَ رَبُّكَ مَقَامًا مَّحْمُودًا', '0fa8722cd721722e90c39ead83dc4055261fd44508c14d0eb719053773d1df55', '0fa8722cd721722e90c39ead83dc4055261fd44508c14d0eb719053773d1df55', NULL, 'ومن اليل فتهجد به نافله لك عسي ان يبعثك ربك مقاما محمودا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2109, 'tanzil-uthmani-v1.1', 17, 80, 'وَقُل رَّبِّ أَدْخِلْنِى مُدْخَلَ صِدْقٍ وَأَخْرِجْنِى مُخْرَجَ صِدْقٍ وَٱجْعَل لِّى مِن لَّدُنكَ سُلْطَٰنًا نَّصِيرًا', '6fe8ac6d60952ac08b37e211488eb1aa686ccacf84f868dadaaf72d157f9500c', 'وَقُل رَّبِّ أَدْخِلْنِى مُدْخَلَ صِدْقٍ وَأَخْرِجْنِى مُخْرَجَ صِدْقٍ وَٱجْعَل لِّى مِن لَّدُنكَ سُلْطَٰنًا نَّصِيرًا', '6fe8ac6d60952ac08b37e211488eb1aa686ccacf84f868dadaaf72d157f9500c', '6fe8ac6d60952ac08b37e211488eb1aa686ccacf84f868dadaaf72d157f9500c', NULL, 'وقل رب ادخلني مدخل صدق واخرجني مخرج صدق واجعل لي من لدنك سلطنا نصيرا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2110, 'tanzil-uthmani-v1.1', 17, 81, 'وَقُلْ جَآءَ ٱلْحَقُّ وَزَهَقَ ٱلْبَٰطِلُ إِنَّ ٱلْبَٰطِلَ كَانَ زَهُوقًا', '7aa86fa6b84dda67dc32fc6d966ac1b80c259d388762f2ae763fa46c4394debf', 'وَقُلْ جَآءَ ٱلْحَقُّ وَزَهَقَ ٱلْبَٰطِلُ إِنَّ ٱلْبَٰطِلَ كَانَ زَهُوقًا', '7aa86fa6b84dda67dc32fc6d966ac1b80c259d388762f2ae763fa46c4394debf', '7aa86fa6b84dda67dc32fc6d966ac1b80c259d388762f2ae763fa46c4394debf', NULL, 'وقل جاء الحق وزهق البطل ان البطل كان زهوقا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2111, 'tanzil-uthmani-v1.1', 17, 82, 'وَنُنَزِّلُ مِنَ ٱلْقُرْءَانِ مَا هُوَ شِفَآءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارًا', 'f0237ca966fb1285fd18f6a5ee02b533a1849e0cc684eb28827bb0cff0892385', 'وَنُنَزِّلُ مِنَ ٱلْقُرْءَانِ مَا هُوَ شِفَآءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارًا', 'f0237ca966fb1285fd18f6a5ee02b533a1849e0cc684eb28827bb0cff0892385', 'f0237ca966fb1285fd18f6a5ee02b533a1849e0cc684eb28827bb0cff0892385', NULL, 'وننزل من القرءان ما هو شفاء ورحمه للمؤمنين ولا يزيد الظلمين الا خسارا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2112, 'tanzil-uthmani-v1.1', 17, 83, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسًا', '9dc6a64a6e4fbe2b0ab217efa3de3595599fac570a528369116b099091259b69', 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسًا', '9dc6a64a6e4fbe2b0ab217efa3de3595599fac570a528369116b099091259b69', '9dc6a64a6e4fbe2b0ab217efa3de3595599fac570a528369116b099091259b69', NULL, 'واذا انعمنا علي الانسن اعرض ونا بجانبه واذا مسه الشر كان يوسا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2113, 'tanzil-uthmani-v1.1', 17, 84, 'قُلْ كُلٌّ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًا', '0102a288e5017ed1da36b3af795c1a15bb2a9fe90c151f9bbb3618c3fe27fb85', 'قُلْ كُلٌّ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًا', '0102a288e5017ed1da36b3af795c1a15bb2a9fe90c151f9bbb3618c3fe27fb85', '0102a288e5017ed1da36b3af795c1a15bb2a9fe90c151f9bbb3618c3fe27fb85', NULL, 'قل كل يعمل علي شاكلته فربكم اعلم بمن هو اهدي سبيلا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2114, 'tanzil-uthmani-v1.1', 17, 85, 'وَيَسْـَٔلُونَكَ عَنِ ٱلرُّوحِ قُلِ ٱلرُّوحُ مِنْ أَمْرِ رَبِّى وَمَآ أُوتِيتُم مِّنَ ٱلْعِلْمِ إِلَّا قَلِيلًا', '0e2d1cdaae0cb82c5f0a32459c3aa2e0b3ae6bc0425afa9f0f8331471de00e32', 'وَيَسْـَٔلُونَكَ عَنِ ٱلرُّوحِ قُلِ ٱلرُّوحُ مِنْ أَمْرِ رَبِّى وَمَآ أُوتِيتُم مِّنَ ٱلْعِلْمِ إِلَّا قَلِيلًا', '0e2d1cdaae0cb82c5f0a32459c3aa2e0b3ae6bc0425afa9f0f8331471de00e32', '0e2d1cdaae0cb82c5f0a32459c3aa2e0b3ae6bc0425afa9f0f8331471de00e32', NULL, 'ويسلونك عن الروح قل الروح من امر ربي وما اوتيتم من العلم الا قليلا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2115, 'tanzil-uthmani-v1.1', 17, 86, 'وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيْنَا وَكِيلًا', 'da7ecc2b82241bb97f7507e3bc2065a4fbacbfa6bc769863d87b673289c2b0d2', 'وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيْنَا وَكِيلًا', 'da7ecc2b82241bb97f7507e3bc2065a4fbacbfa6bc769863d87b673289c2b0d2', 'da7ecc2b82241bb97f7507e3bc2065a4fbacbfa6bc769863d87b673289c2b0d2', NULL, 'ولئن شئنا لنذهبن بالذي اوحينا اليك ثم لا تجد لك به علينا وكيلا', 15, 29, 116, 1, 4, 290, false, NULL),
    (2116, 'tanzil-uthmani-v1.1', 17, 87, 'إِلَّا رَحْمَةً مِّن رَّبِّكَ إِنَّ فَضْلَهُۥ كَانَ عَلَيْكَ كَبِيرًا', '0eeb862e6eaddf41a1e40af347a7868889178bf156a2b97ae513e91181c30244', 'إِلَّا رَحْمَةً مِّن رَّبِّكَ إِنَّ فَضْلَهُۥ كَانَ عَلَيْكَ كَبِيرًا', '0eeb862e6eaddf41a1e40af347a7868889178bf156a2b97ae513e91181c30244', '0eeb862e6eaddf41a1e40af347a7868889178bf156a2b97ae513e91181c30244', NULL, 'الا رحمه من ربك ان فضله كان عليك كبيرا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2117, 'tanzil-uthmani-v1.1', 17, 88, 'قُل لَّئِنِ ٱجْتَمَعَتِ ٱلْإِنسُ وَٱلْجِنُّ عَلَىٰٓ أَن يَأْتُوا۟ بِمِثْلِ هَٰذَا ٱلْقُرْءَانِ لَا يَأْتُونَ بِمِثْلِهِۦ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا', 'c445419f071cc2ace682ed14746836397b28efb741923af38ed37917dfd6635d', 'قُل لَّئِنِ ٱجْتَمَعَتِ ٱلْإِنسُ وَٱلْجِنُّ عَلَىٰٓ أَن يَأْتُوا۟ بِمِثْلِ هَٰذَا ٱلْقُرْءَانِ لَا يَأْتُونَ بِمِثْلِهِۦ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا', 'c445419f071cc2ace682ed14746836397b28efb741923af38ed37917dfd6635d', 'c445419f071cc2ace682ed14746836397b28efb741923af38ed37917dfd6635d', NULL, 'قل لئن اجتمعت الانس والجن علي ان ياتوا بمثل هذا القرءان لا ياتون بمثله ولو كان بعضهم لبعض ظهيرا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2118, 'tanzil-uthmani-v1.1', 17, 89, 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', 'a19ecb1ba97fd51f05167344c12269e6f95f6d76c97b47a20a3c7059e2ab6afe', 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', 'a19ecb1ba97fd51f05167344c12269e6f95f6d76c97b47a20a3c7059e2ab6afe', 'a19ecb1ba97fd51f05167344c12269e6f95f6d76c97b47a20a3c7059e2ab6afe', NULL, 'ولقد صرفنا للناس في هذا القرءان من كل مثل فابي اكثر الناس الا كفورا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2119, 'tanzil-uthmani-v1.1', 17, 90, 'وَقَالُوا۟ لَن نُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ ٱلْأَرْضِ يَنۢبُوعًا', '58b4a57ef949ddd8d7f6178320cc39e00747a9f58e5ea2f201f62b2ade28a805', 'وَقَالُوا۟ لَن نُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ ٱلْأَرْضِ يَنۢبُوعًا', '58b4a57ef949ddd8d7f6178320cc39e00747a9f58e5ea2f201f62b2ade28a805', '58b4a57ef949ddd8d7f6178320cc39e00747a9f58e5ea2f201f62b2ade28a805', NULL, 'وقالوا لن نؤمن لك حتي تفجر لنا من الارض ينبوعا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2120, 'tanzil-uthmani-v1.1', 17, 91, 'أَوْ تَكُونَ لَكَ جَنَّةٌ مِّن نَّخِيلٍ وَعِنَبٍ فَتُفَجِّرَ ٱلْأَنْهَٰرَ خِلَٰلَهَا تَفْجِيرًا', '699816c309cba8d20539c424173f714b999c68da2186e45da7f335b1cab08dd1', 'أَوْ تَكُونَ لَكَ جَنَّةٌ مِّن نَّخِيلٍ وَعِنَبٍ فَتُفَجِّرَ ٱلْأَنْهَٰرَ خِلَٰلَهَا تَفْجِيرًا', '699816c309cba8d20539c424173f714b999c68da2186e45da7f335b1cab08dd1', '699816c309cba8d20539c424173f714b999c68da2186e45da7f335b1cab08dd1', NULL, 'او تكون لك جنه من نخيل وعنب فتفجر الانهر خللها تفجيرا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2121, 'tanzil-uthmani-v1.1', 17, 92, 'أَوْ تُسْقِطَ ٱلسَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِٱللَّهِ وَٱلْمَلَٰٓئِكَةِ قَبِيلًا', '1721f3730b3ef2a2eeb2238e2a805def21f48e1702574458f08f4aa9b44766fa', 'أَوْ تُسْقِطَ ٱلسَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِٱللَّهِ وَٱلْمَلَٰٓئِكَةِ قَبِيلًا', '1721f3730b3ef2a2eeb2238e2a805def21f48e1702574458f08f4aa9b44766fa', '1721f3730b3ef2a2eeb2238e2a805def21f48e1702574458f08f4aa9b44766fa', NULL, 'او تسقط السماء كما زعمت علينا كسفا او تاتي بالله والملئكه قبيلا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2122, 'tanzil-uthmani-v1.1', 17, 93, 'أَوْ يَكُونَ لَكَ بَيْتٌ مِّن زُخْرُفٍ أَوْ تَرْقَىٰ فِى ٱلسَّمَآءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَٰبًا نَّقْرَؤُهُۥ قُلْ سُبْحَانَ رَبِّى هَلْ كُنتُ إِلَّا بَشَرًا رَّسُولًا', '245597fe4e39849d421d80ca6fb7e9e12737c77ca345d8753be62e49f4c14a6c', 'أَوْ يَكُونَ لَكَ بَيْتٌ مِّن زُخْرُفٍ أَوْ تَرْقَىٰ فِى ٱلسَّمَآءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَٰبًا نَّقْرَؤُهُۥ قُلْ سُبْحَانَ رَبِّى هَلْ كُنتُ إِلَّا بَشَرًا رَّسُولًا', '245597fe4e39849d421d80ca6fb7e9e12737c77ca345d8753be62e49f4c14a6c', '245597fe4e39849d421d80ca6fb7e9e12737c77ca345d8753be62e49f4c14a6c', NULL, 'او يكون لك بيت من زخرف او ترقي في السماء ولن نؤمن لرقيك حتي تنزل علينا كتبا نقرؤه قل سبحان ربي هل كنت الا بشرا رسولا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2123, 'tanzil-uthmani-v1.1', 17, 94, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰٓ إِلَّآ أَن قَالُوٓا۟ أَبَعَثَ ٱللَّهُ بَشَرًا رَّسُولًا', '89f35f524b5991c84b07e1c55784b04ac3b1287fcbc81851334b89f61df99242', 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰٓ إِلَّآ أَن قَالُوٓا۟ أَبَعَثَ ٱللَّهُ بَشَرًا رَّسُولًا', '89f35f524b5991c84b07e1c55784b04ac3b1287fcbc81851334b89f61df99242', '89f35f524b5991c84b07e1c55784b04ac3b1287fcbc81851334b89f61df99242', NULL, 'وما منع الناس ان يؤمنوا اذ جاءهم الهدي الا ان قالوا ابعث الله بشرا رسولا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2124, 'tanzil-uthmani-v1.1', 17, 95, 'قُل لَّوْ كَانَ فِى ٱلْأَرْضِ مَلَٰٓئِكَةٌ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ ٱلسَّمَآءِ مَلَكًا رَّسُولًا', 'f876aeb4694255a1253323f9883895d3c510ebb3e318d7a93a69ec8edcaae7d9', 'قُل لَّوْ كَانَ فِى ٱلْأَرْضِ مَلَٰٓئِكَةٌ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ ٱلسَّمَآءِ مَلَكًا رَّسُولًا', 'f876aeb4694255a1253323f9883895d3c510ebb3e318d7a93a69ec8edcaae7d9', 'f876aeb4694255a1253323f9883895d3c510ebb3e318d7a93a69ec8edcaae7d9', NULL, 'قل لو كان في الارض ملئكه يمشون مطمئنين لنزلنا عليهم من السماء ملكا رسولا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2125, 'tanzil-uthmani-v1.1', 17, 96, 'قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'bb098bda01805e0001df0b8a41d9195dfd6e4ccc597122ebf0895641258e2bc7', 'قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًا', 'bb098bda01805e0001df0b8a41d9195dfd6e4ccc597122ebf0895641258e2bc7', 'bb098bda01805e0001df0b8a41d9195dfd6e4ccc597122ebf0895641258e2bc7', NULL, 'قل كفي بالله شهيدا بيني وبينكم انه كان بعباده خبيرا بصيرا', 15, 29, 116, 1, 4, 291, false, NULL),
    (2126, 'tanzil-uthmani-v1.1', 17, 97, 'وَمَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَآءَ مِن دُونِهِۦ وَنَحْشُرُهُمْ يَوْمَ ٱلْقِيَٰمَةِ عَلَىٰ وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَّأْوَىٰهُمْ جَهَنَّمُ كُلَّمَا خَبَتْ زِدْنَٰهُمْ سَعِيرًا', '72d3a0e3ea8d93c94cc7126e5b07b442248fad732358fc1352170efeab2571f7', 'وَمَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَآءَ مِن دُونِهِۦ وَنَحْشُرُهُمْ يَوْمَ ٱلْقِيَٰمَةِ عَلَىٰ وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَّأْوَىٰهُمْ جَهَنَّمُ كُلَّمَا خَبَتْ زِدْنَٰهُمْ سَعِيرًا', '72d3a0e3ea8d93c94cc7126e5b07b442248fad732358fc1352170efeab2571f7', '72d3a0e3ea8d93c94cc7126e5b07b442248fad732358fc1352170efeab2571f7', NULL, 'ومن يهد الله فهو المهتد ومن يضلل فلن تجد لهم اولياء من دونه ونحشرهم يوم القيمه علي وجوههم عميا وبكما وصما ماويهم جهنم كلما خبت زدنهم سعيرا', 15, 29, 116, 1, 4, 292, false, NULL),
    (2127, 'tanzil-uthmani-v1.1', 17, 98, 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمْ كَفَرُوا۟ بِـَٔايَٰتِنَا وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', '4e7f53b7c9769cda8adea245f2a36b4d66134d135e749b3b14cfc30a1c371451', 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمْ كَفَرُوا۟ بِـَٔايَٰتِنَا وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا', '4e7f53b7c9769cda8adea245f2a36b4d66134d135e749b3b14cfc30a1c371451', '4e7f53b7c9769cda8adea245f2a36b4d66134d135e749b3b14cfc30a1c371451', NULL, 'ذلك جزاؤهم بانهم كفروا بايتنا وقالوا اءذا كنا عظما ورفتا اءنا لمبعوثون خلقا جديدا', 15, 29, 116, 1, 4, 292, false, NULL),
    (2128, 'tanzil-uthmani-v1.1', 17, 99, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ قَادِرٌ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَلًا لَّا رَيْبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورًا', '7ec6db85332cb1cdaf17d18caf19325b29534bb9e05d36e32d9e016f561349f3', 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ قَادِرٌ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَلًا لَّا رَيْبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورًا', '7ec6db85332cb1cdaf17d18caf19325b29534bb9e05d36e32d9e016f561349f3', '7ec6db85332cb1cdaf17d18caf19325b29534bb9e05d36e32d9e016f561349f3', NULL, 'اولم يروا ان الله الذي خلق السموت والارض قادر علي ان يخلق مثلهم وجعل لهم اجلا لا ريب فيه فابي الظلمون الا كفورا', 15, 30, 117, 1, 4, 292, false, NULL),
    (2129, 'tanzil-uthmani-v1.1', 17, 100, 'قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّىٓ إِذًا لَّأَمْسَكْتُمْ خَشْيَةَ ٱلْإِنفَاقِ وَكَانَ ٱلْإِنسَٰنُ قَتُورًا', 'c50152ac8a7f16529d545c7389215a4d11368cc399aad09bc72abddaba51618f', 'قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّىٓ إِذًا لَّأَمْسَكْتُمْ خَشْيَةَ ٱلْإِنفَاقِ وَكَانَ ٱلْإِنسَٰنُ قَتُورًا', 'c50152ac8a7f16529d545c7389215a4d11368cc399aad09bc72abddaba51618f', 'c50152ac8a7f16529d545c7389215a4d11368cc399aad09bc72abddaba51618f', NULL, 'قل لو انتم تملكون خزائن رحمه ربي اذا لامسكتم خشيه الانفاق وكان الانسن قتورا', 15, 30, 117, 1, 4, 292, false, NULL),
    (2130, 'tanzil-uthmani-v1.1', 17, 101, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ تِسْعَ ءَايَٰتٍۭ بَيِّنَٰتٍ فَسْـَٔلْ بَنِىٓ إِسْرَٰٓءِيلَ إِذْ جَآءَهُمْ فَقَالَ لَهُۥ فِرْعَوْنُ إِنِّى لَأَظُنُّكَ يَٰمُوسَىٰ مَسْحُورًا', '5a60c171a850ecf74b18b668c471b1969178f8335b6d4136ee20874867ab5f8a', 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ تِسْعَ ءَايَٰتٍۭ بَيِّنَٰتٍ فَسْـَٔلْ بَنِىٓ إِسْرَٰٓءِيلَ إِذْ جَآءَهُمْ فَقَالَ لَهُۥ فِرْعَوْنُ إِنِّى لَأَظُنُّكَ يَٰمُوسَىٰ مَسْحُورًا', '5a60c171a850ecf74b18b668c471b1969178f8335b6d4136ee20874867ab5f8a', '5a60c171a850ecf74b18b668c471b1969178f8335b6d4136ee20874867ab5f8a', NULL, 'ولقد ءاتينا موسي تسع ءايت بينت فسل بني اسرءيل اذ جاءهم فقال له فرعون اني لاظنك يموسي مسحورا', 15, 30, 117, 1, 4, 292, false, NULL),
    (2131, 'tanzil-uthmani-v1.1', 17, 102, 'قَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ بَصَآئِرَ وَإِنِّى لَأَظُنُّكَ يَٰفِرْعَوْنُ مَثْبُورًا', 'b80f7114d69f5e0a53ac416ca41628ea4868e008102405455d4542ec98914aa8', 'قَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ بَصَآئِرَ وَإِنِّى لَأَظُنُّكَ يَٰفِرْعَوْنُ مَثْبُورًا', 'b80f7114d69f5e0a53ac416ca41628ea4868e008102405455d4542ec98914aa8', 'b80f7114d69f5e0a53ac416ca41628ea4868e008102405455d4542ec98914aa8', NULL, 'قال لقد علمت ما انزل هؤلاء الا رب السموت والارض بصائر واني لاظنك يفرعون مثبورا', 15, 30, 117, 1, 4, 292, false, NULL),
    (2132, 'tanzil-uthmani-v1.1', 17, 103, 'فَأَرَادَ أَن يَسْتَفِزَّهُم مِّنَ ٱلْأَرْضِ فَأَغْرَقْنَٰهُ وَمَن مَّعَهُۥ جَمِيعًا', '790751eed50e6db4612f5fd8af54f238c3d6ab8baac1152d65b6d70c26798daf', 'فَأَرَادَ أَن يَسْتَفِزَّهُم مِّنَ ٱلْأَرْضِ فَأَغْرَقْنَٰهُ وَمَن مَّعَهُۥ جَمِيعًا', '790751eed50e6db4612f5fd8af54f238c3d6ab8baac1152d65b6d70c26798daf', '790751eed50e6db4612f5fd8af54f238c3d6ab8baac1152d65b6d70c26798daf', NULL, 'فاراد ان يستفزهم من الارض فاغرقنه ومن معه جميعا', 15, 30, 117, 1, 4, 292, false, NULL),
    (2133, 'tanzil-uthmani-v1.1', 17, 104, 'وَقُلْنَا مِنۢ بَعْدِهِۦ لِبَنِىٓ إِسْرَٰٓءِيلَ ٱسْكُنُوا۟ ٱلْأَرْضَ فَإِذَا جَآءَ وَعْدُ ٱلْـَٔاخِرَةِ جِئْنَا بِكُمْ لَفِيفًا', 'ca8eaf10921ba014d5a18a8fd7f93138719affcc677149f1abbcb5b6399fc1db', 'وَقُلْنَا مِنۢ بَعْدِهِۦ لِبَنِىٓ إِسْرَٰٓءِيلَ ٱسْكُنُوا۟ ٱلْأَرْضَ فَإِذَا جَآءَ وَعْدُ ٱلْـَٔاخِرَةِ جِئْنَا بِكُمْ لَفِيفًا', 'ca8eaf10921ba014d5a18a8fd7f93138719affcc677149f1abbcb5b6399fc1db', 'ca8eaf10921ba014d5a18a8fd7f93138719affcc677149f1abbcb5b6399fc1db', NULL, 'وقلنا من بعده لبني اسرءيل اسكنوا الارض فاذا جاء وعد الاخره جئنا بكم لفيفا', 15, 30, 117, 1, 4, 292, false, NULL),
    (2134, 'tanzil-uthmani-v1.1', 17, 105, 'وَبِٱلْحَقِّ أَنزَلْنَٰهُ وَبِٱلْحَقِّ نَزَلَ وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', '8a101fc94f1e1f6be2cd6ccce3d70ca0375ebd03d4c7856cd97bfc5b22860382', 'وَبِٱلْحَقِّ أَنزَلْنَٰهُ وَبِٱلْحَقِّ نَزَلَ وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', '8a101fc94f1e1f6be2cd6ccce3d70ca0375ebd03d4c7856cd97bfc5b22860382', '8a101fc94f1e1f6be2cd6ccce3d70ca0375ebd03d4c7856cd97bfc5b22860382', NULL, 'وبالحق انزلنه وبالحق نزل وما ارسلنك الا مبشرا ونذيرا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2135, 'tanzil-uthmani-v1.1', 17, 106, 'وَقُرْءَانًا فَرَقْنَٰهُ لِتَقْرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكْثٍ وَنَزَّلْنَٰهُ تَنزِيلًا', 'd35bc3631e80be64e4f5282330222384f750496f7ae701aa8080610a84fd9492', 'وَقُرْءَانًا فَرَقْنَٰهُ لِتَقْرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكْثٍ وَنَزَّلْنَٰهُ تَنزِيلًا', 'd35bc3631e80be64e4f5282330222384f750496f7ae701aa8080610a84fd9492', 'd35bc3631e80be64e4f5282330222384f750496f7ae701aa8080610a84fd9492', NULL, 'وقرءانا فرقنه لتقراه علي الناس علي مكث ونزلنه تنزيلا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2136, 'tanzil-uthmani-v1.1', 17, 107, 'قُلْ ءَامِنُوا۟ بِهِۦٓ أَوْ لَا تُؤْمِنُوٓا۟ إِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مِن قَبْلِهِۦٓ إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًا', '535552ca7e06a62265a9960b76fd6ccdecd0164056d13fec74ca45e025ccdded', 'قُلْ ءَامِنُوا۟ بِهِۦٓ أَوْ لَا تُؤْمِنُوٓا۟ إِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مِن قَبْلِهِۦٓ إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًا', '535552ca7e06a62265a9960b76fd6ccdecd0164056d13fec74ca45e025ccdded', '535552ca7e06a62265a9960b76fd6ccdecd0164056d13fec74ca45e025ccdded', NULL, 'قل ءامنوا به او لا تؤمنوا ان الذين اوتوا العلم من قبله اذا يتلي عليهم يخرون للاذقان سجدا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2137, 'tanzil-uthmani-v1.1', 17, 108, 'وَيَقُولُونَ سُبْحَٰنَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًا', '268085536cd6fea49e2c5003678e354f6102bf104433afb0c01c4dace683370a', 'وَيَقُولُونَ سُبْحَٰنَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًا', '268085536cd6fea49e2c5003678e354f6102bf104433afb0c01c4dace683370a', '268085536cd6fea49e2c5003678e354f6102bf104433afb0c01c4dace683370a', NULL, 'ويقولون سبحن ربنا ان كان وعد ربنا لمفعولا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2138, 'tanzil-uthmani-v1.1', 17, 109, 'وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًا', 'd2d2c4b7282da03194d4cfa111f1064bc1c3a918c7151c8e297943a2c698c419', 'وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًا', 'd2d2c4b7282da03194d4cfa111f1064bc1c3a918c7151c8e297943a2c698c419', 'd2d2c4b7282da03194d4cfa111f1064bc1c3a918c7151c8e297943a2c698c419', NULL, 'ويخرون للاذقان يبكون ويزيدهم خشوعا', 15, 30, 117, 1, 4, 293, true, 'recommended'),
    (2139, 'tanzil-uthmani-v1.1', 17, 110, 'قُلِ ٱدْعُوا۟ ٱللَّهَ أَوِ ٱدْعُوا۟ ٱلرَّحْمَٰنَ أَيًّا مَّا تَدْعُوا۟ فَلَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَٱبْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا', 'bf1419ac05dd7be390adf324aa03a9cc7238d53a2345ef6d6cd9575e5f3e3da5', 'قُلِ ٱدْعُوا۟ ٱللَّهَ أَوِ ٱدْعُوا۟ ٱلرَّحْمَٰنَ أَيًّا مَّا تَدْعُوا۟ فَلَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَٱبْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا', 'bf1419ac05dd7be390adf324aa03a9cc7238d53a2345ef6d6cd9575e5f3e3da5', 'bf1419ac05dd7be390adf324aa03a9cc7238d53a2345ef6d6cd9575e5f3e3da5', NULL, 'قل ادعوا الله او ادعوا الرحمن ايا ما تدعوا فله الاسماء الحسني ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2140, 'tanzil-uthmani-v1.1', 17, 111, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَلَمْ يَكُن لَّهُۥ وَلِىٌّ مِّنَ ٱلذُّلِّ وَكَبِّرْهُ تَكْبِيرًۢا', 'fddae5a5cea969bb80de468ab709015967ef17edb381efb794f37e405de11713', 'وَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَلَمْ يَكُن لَّهُۥ وَلِىٌّ مِّنَ ٱلذُّلِّ وَكَبِّرْهُ تَكْبِيرًۢا', 'fddae5a5cea969bb80de468ab709015967ef17edb381efb794f37e405de11713', 'fddae5a5cea969bb80de468ab709015967ef17edb381efb794f37e405de11713', NULL, 'وقل الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2141, 'tanzil-uthmani-v1.1', 18, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَنزَلَ عَلَىٰ عَبْدِهِ ٱلْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا', '571850497f5c47015d3522721439098508783b3265035a15a27b480b77d376ff', 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَنزَلَ عَلَىٰ عَبْدِهِ ٱلْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا', '7ea8be6819ac92ce02aece34e0169a7b367533ade42481a3e8fe7e2d6f50320a', '7ea8be6819ac92ce02aece34e0169a7b367533ade42481a3e8fe7e2d6f50320a', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الحمد لله الذي انزل علي عبده الكتب ولم يجعل له عوجا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2142, 'tanzil-uthmani-v1.1', 18, 2, 'قَيِّمًا لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ وَيُبَشِّرَ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًا حَسَنًا', 'c5e060ef46189a19e7fa135eb6b2ad5ce4ceba52923364881dd5a354d0d6acae', 'قَيِّمًا لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ وَيُبَشِّرَ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًا حَسَنًا', 'c5e060ef46189a19e7fa135eb6b2ad5ce4ceba52923364881dd5a354d0d6acae', 'c5e060ef46189a19e7fa135eb6b2ad5ce4ceba52923364881dd5a354d0d6acae', NULL, 'قيما لينذر باسا شديدا من لدنه ويبشر المؤمنين الذين يعملون الصلحت ان لهم اجرا حسنا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2143, 'tanzil-uthmani-v1.1', 18, 3, 'مَّٰكِثِينَ فِيهِ أَبَدًا', '77df33b34728b0ffdcf8aa88f3d4a4c622bf154c6f19181d45e62882f2b467c0', 'مَّٰكِثِينَ فِيهِ أَبَدًا', '77df33b34728b0ffdcf8aa88f3d4a4c622bf154c6f19181d45e62882f2b467c0', '77df33b34728b0ffdcf8aa88f3d4a4c622bf154c6f19181d45e62882f2b467c0', NULL, 'مكثين فيه ابدا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2144, 'tanzil-uthmani-v1.1', 18, 4, 'وَيُنذِرَ ٱلَّذِينَ قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا', 'dcb8429a675e21fcb48282fa91dad768526e74e54b2199fd148ade5fc85316cd', 'وَيُنذِرَ ٱلَّذِينَ قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا', 'dcb8429a675e21fcb48282fa91dad768526e74e54b2199fd148ade5fc85316cd', 'dcb8429a675e21fcb48282fa91dad768526e74e54b2199fd148ade5fc85316cd', NULL, 'وينذر الذين قالوا اتخذ الله ولدا', 15, 30, 117, 1, 4, 293, false, NULL),
    (2145, 'tanzil-uthmani-v1.1', 18, 5, 'مَّا لَهُم بِهِۦ مِنْ عِلْمٍ وَلَا لِـَٔابَآئِهِمْ كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَٰهِهِمْ إِن يَقُولُونَ إِلَّا كَذِبًا', 'b0da196794358d59bb9e4b69facfe76a14cf25db2c132690a25de453b38d2a89', 'مَّا لَهُم بِهِۦ مِنْ عِلْمٍ وَلَا لِـَٔابَآئِهِمْ كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَٰهِهِمْ إِن يَقُولُونَ إِلَّا كَذِبًا', 'b0da196794358d59bb9e4b69facfe76a14cf25db2c132690a25de453b38d2a89', 'b0da196794358d59bb9e4b69facfe76a14cf25db2c132690a25de453b38d2a89', NULL, 'ما لهم به من علم ولا لابائهم كبرت كلمه تخرج من افوههم ان يقولون الا كذبا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2146, 'tanzil-uthmani-v1.1', 18, 6, 'فَلَعَلَّكَ بَٰخِعٌ نَّفْسَكَ عَلَىٰٓ ءَاثَٰرِهِمْ إِن لَّمْ يُؤْمِنُوا۟ بِهَٰذَا ٱلْحَدِيثِ أَسَفًا', '852a5804a878dfc8a5f8e9e2816d82a9b5f1891f8dbeafc15cb758f4ee9d8650', 'فَلَعَلَّكَ بَٰخِعٌ نَّفْسَكَ عَلَىٰٓ ءَاثَٰرِهِمْ إِن لَّمْ يُؤْمِنُوا۟ بِهَٰذَا ٱلْحَدِيثِ أَسَفًا', '852a5804a878dfc8a5f8e9e2816d82a9b5f1891f8dbeafc15cb758f4ee9d8650', '852a5804a878dfc8a5f8e9e2816d82a9b5f1891f8dbeafc15cb758f4ee9d8650', NULL, 'فلعلك بخع نفسك علي ءاثرهم ان لم يؤمنوا بهذا الحديث اسفا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2147, 'tanzil-uthmani-v1.1', 18, 7, 'إِنَّا جَعَلْنَا مَا عَلَى ٱلْأَرْضِ زِينَةً لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًا', '08b3ebfbb2f496a31c67c1d2557a709906b09647e1cb10bf4f18906234ca0ede', 'إِنَّا جَعَلْنَا مَا عَلَى ٱلْأَرْضِ زِينَةً لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًا', '08b3ebfbb2f496a31c67c1d2557a709906b09647e1cb10bf4f18906234ca0ede', '08b3ebfbb2f496a31c67c1d2557a709906b09647e1cb10bf4f18906234ca0ede', NULL, 'انا جعلنا ما علي الارض زينه لها لنبلوهم ايهم احسن عملا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2148, 'tanzil-uthmani-v1.1', 18, 8, 'وَإِنَّا لَجَٰعِلُونَ مَا عَلَيْهَا صَعِيدًا جُرُزًا', '021dbc05f95bd49c599450bc2a4bce762917d4f7722384035918ad8117622267', 'وَإِنَّا لَجَٰعِلُونَ مَا عَلَيْهَا صَعِيدًا جُرُزًا', '021dbc05f95bd49c599450bc2a4bce762917d4f7722384035918ad8117622267', '021dbc05f95bd49c599450bc2a4bce762917d4f7722384035918ad8117622267', NULL, 'وانا لجعلون ما عليها صعيدا جرزا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2149, 'tanzil-uthmani-v1.1', 18, 9, 'أَمْ حَسِبْتَ أَنَّ أَصْحَٰبَ ٱلْكَهْفِ وَٱلرَّقِيمِ كَانُوا۟ مِنْ ءَايَٰتِنَا عَجَبًا', 'fb2d6ed56198c30cadeb6f0c77e1c35b05ad0175e27fd1a110410747a660b40d', 'أَمْ حَسِبْتَ أَنَّ أَصْحَٰبَ ٱلْكَهْفِ وَٱلرَّقِيمِ كَانُوا۟ مِنْ ءَايَٰتِنَا عَجَبًا', 'fb2d6ed56198c30cadeb6f0c77e1c35b05ad0175e27fd1a110410747a660b40d', 'fb2d6ed56198c30cadeb6f0c77e1c35b05ad0175e27fd1a110410747a660b40d', NULL, 'ام حسبت ان اصحب الكهف والرقيم كانوا من ءايتنا عجبا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2150, 'tanzil-uthmani-v1.1', 18, 10, 'إِذْ أَوَى ٱلْفِتْيَةُ إِلَى ٱلْكَهْفِ فَقَالُوا۟ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا', 'f6e1578eabf2561cb0be2265243cdc9c207f78347190ae9c9f1cff22c5a17baf', 'إِذْ أَوَى ٱلْفِتْيَةُ إِلَى ٱلْكَهْفِ فَقَالُوا۟ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا', 'f6e1578eabf2561cb0be2265243cdc9c207f78347190ae9c9f1cff22c5a17baf', 'f6e1578eabf2561cb0be2265243cdc9c207f78347190ae9c9f1cff22c5a17baf', NULL, 'اذ اوي الفتيه الي الكهف فقالوا ربنا ءاتنا من لدنك رحمه وهيئ لنا من امرنا رشدا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2151, 'tanzil-uthmani-v1.1', 18, 11, 'فَضَرَبْنَا عَلَىٰٓ ءَاذَانِهِمْ فِى ٱلْكَهْفِ سِنِينَ عَدَدًا', '276c7739ad4ceb5fef16402e141b7ef5ad0e31f7f5622c1e85cb6aafbe4e28c2', 'فَضَرَبْنَا عَلَىٰٓ ءَاذَانِهِمْ فِى ٱلْكَهْفِ سِنِينَ عَدَدًا', '276c7739ad4ceb5fef16402e141b7ef5ad0e31f7f5622c1e85cb6aafbe4e28c2', '276c7739ad4ceb5fef16402e141b7ef5ad0e31f7f5622c1e85cb6aafbe4e28c2', NULL, 'فضربنا علي ءاذانهم في الكهف سنين عددا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2152, 'tanzil-uthmani-v1.1', 18, 12, 'ثُمَّ بَعَثْنَٰهُمْ لِنَعْلَمَ أَىُّ ٱلْحِزْبَيْنِ أَحْصَىٰ لِمَا لَبِثُوٓا۟ أَمَدًا', '717d168084580e48cbbb40137fd810a6314764e8e4433d0f1c67aacaba984eaf', 'ثُمَّ بَعَثْنَٰهُمْ لِنَعْلَمَ أَىُّ ٱلْحِزْبَيْنِ أَحْصَىٰ لِمَا لَبِثُوٓا۟ أَمَدًا', '717d168084580e48cbbb40137fd810a6314764e8e4433d0f1c67aacaba984eaf', '717d168084580e48cbbb40137fd810a6314764e8e4433d0f1c67aacaba984eaf', NULL, 'ثم بعثنهم لنعلم اي الحزبين احصي لما لبثوا امدا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2153, 'tanzil-uthmani-v1.1', 18, 13, 'نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِٱلْحَقِّ إِنَّهُمْ فِتْيَةٌ ءَامَنُوا۟ بِرَبِّهِمْ وَزِدْنَٰهُمْ هُدًى', '255f1b3cb80e0ab56447685556b3936b83f18af851302fa85c2e3994e29738ab', 'نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِٱلْحَقِّ إِنَّهُمْ فِتْيَةٌ ءَامَنُوا۟ بِرَبِّهِمْ وَزِدْنَٰهُمْ هُدًى', '255f1b3cb80e0ab56447685556b3936b83f18af851302fa85c2e3994e29738ab', '255f1b3cb80e0ab56447685556b3936b83f18af851302fa85c2e3994e29738ab', NULL, 'نحن نقص عليك نباهم بالحق انهم فتيه ءامنوا بربهم وزدنهم هدي', 15, 30, 117, 1, 4, 294, false, NULL),
    (2154, 'tanzil-uthmani-v1.1', 18, 14, 'وَرَبَطْنَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُوا۟ فَقَالُوا۟ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَن نَّدْعُوَا۟ مِن دُونِهِۦٓ إِلَٰهًا لَّقَدْ قُلْنَآ إِذًا شَطَطًا', 'cbe465e6d977b887cd5a84dadc979b741a4868c91316d320015039eb7aeb6c32', 'وَرَبَطْنَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُوا۟ فَقَالُوا۟ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَن نَّدْعُوَا۟ مِن دُونِهِۦٓ إِلَٰهًا لَّقَدْ قُلْنَآ إِذًا شَطَطًا', 'cbe465e6d977b887cd5a84dadc979b741a4868c91316d320015039eb7aeb6c32', 'cbe465e6d977b887cd5a84dadc979b741a4868c91316d320015039eb7aeb6c32', NULL, 'وربطنا علي قلوبهم اذ قاموا فقالوا ربنا رب السموت والارض لن ندعوا من دونه الها لقد قلنا اذا شططا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2155, 'tanzil-uthmani-v1.1', 18, 15, 'هَٰٓؤُلَآءِ قَوْمُنَا ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً لَّوْلَا يَأْتُونَ عَلَيْهِم بِسُلْطَٰنٍۭ بَيِّنٍ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا', 'e4b789d638eebb4aed33682d33f69246eb964ca6a265c213c36ad177cf9033be', 'هَٰٓؤُلَآءِ قَوْمُنَا ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً لَّوْلَا يَأْتُونَ عَلَيْهِم بِسُلْطَٰنٍۭ بَيِّنٍ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا', 'e4b789d638eebb4aed33682d33f69246eb964ca6a265c213c36ad177cf9033be', 'e4b789d638eebb4aed33682d33f69246eb964ca6a265c213c36ad177cf9033be', NULL, 'هؤلاء قومنا اتخذوا من دونه ءالهه لولا ياتون عليهم بسلطن بين فمن اظلم ممن افتري علي الله كذبا', 15, 30, 117, 1, 4, 294, false, NULL),
    (2156, 'tanzil-uthmani-v1.1', 18, 16, 'وَإِذِ ٱعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا ٱللَّهَ فَأْوُۥٓا۟ إِلَى ٱلْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِۦ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًا', '1e86f5ded47888d5ad41f90cc14e82f6869ecd5580f938a78854aac44c4a4378', 'وَإِذِ ٱعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا ٱللَّهَ فَأْوُۥٓا۟ إِلَى ٱلْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِۦ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًا', '1e86f5ded47888d5ad41f90cc14e82f6869ecd5580f938a78854aac44c4a4378', '1e86f5ded47888d5ad41f90cc14e82f6869ecd5580f938a78854aac44c4a4378', NULL, 'واذ اعتزلتموهم وما يعبدون الا الله فاوا الي الكهف ينشر لكم ربكم من رحمته ويهيئ لكم من امركم مرفقا', 15, 30, 117, 1, 4, 295, false, NULL),
    (2157, 'tanzil-uthmani-v1.1', 18, 17, 'وَتَرَى ٱلشَّمْسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهْفِهِمْ ذَاتَ ٱلْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ ٱلشِّمَالِ وَهُمْ فِى فَجْوَةٍ مِّنْهُ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُۥ وَلِيًّا مُّرْشِدًا', '3808714c2f8a5149e699d64eb865332dc50322fc8538c1f9cd43530a0796a048', 'وَتَرَى ٱلشَّمْسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهْفِهِمْ ذَاتَ ٱلْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ ٱلشِّمَالِ وَهُمْ فِى فَجْوَةٍ مِّنْهُ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُۥ وَلِيًّا مُّرْشِدًا', '3808714c2f8a5149e699d64eb865332dc50322fc8538c1f9cd43530a0796a048', '3808714c2f8a5149e699d64eb865332dc50322fc8538c1f9cd43530a0796a048', NULL, 'وتري الشمس اذا طلعت تزور عن كهفهم ذات اليمين واذا غربت تقرضهم ذات الشمال وهم في فجوه منه ذلك من ءايت الله من يهد الله فهو المهتد ومن يضلل فلن تجد له وليا مرشدا', 15, 30, 118, 1, 4, 295, false, NULL),
    (2158, 'tanzil-uthmani-v1.1', 18, 18, 'وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ وَنُقَلِّبُهُمْ ذَاتَ ٱلْيَمِينِ وَذَاتَ ٱلشِّمَالِ وَكَلْبُهُم بَٰسِطٌ ذِرَاعَيْهِ بِٱلْوَصِيدِ لَوِ ٱطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَارًا وَلَمُلِئْتَ مِنْهُمْ رُعْبًا', 'fc1a30c0bf4501cac08176584f79aea753c47e4ca122c379e4dcba18707a666a', 'وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ وَنُقَلِّبُهُمْ ذَاتَ ٱلْيَمِينِ وَذَاتَ ٱلشِّمَالِ وَكَلْبُهُم بَٰسِطٌ ذِرَاعَيْهِ بِٱلْوَصِيدِ لَوِ ٱطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَارًا وَلَمُلِئْتَ مِنْهُمْ رُعْبًا', 'fc1a30c0bf4501cac08176584f79aea753c47e4ca122c379e4dcba18707a666a', 'fc1a30c0bf4501cac08176584f79aea753c47e4ca122c379e4dcba18707a666a', NULL, 'وتحسبهم ايقاظا وهم رقود ونقلبهم ذات اليمين وذات الشمال وكلبهم بسط ذراعيه بالوصيد لو اطلعت عليهم لوليت منهم فرارا ولملئت منهم رعبا', 15, 30, 118, 1, 4, 295, false, NULL),
    (2159, 'tanzil-uthmani-v1.1', 18, 19, 'وَكَذَٰلِكَ بَعَثْنَٰهُمْ لِيَتَسَآءَلُوا۟ بَيْنَهُمْ قَالَ قَآئِلٌ مِّنْهُمْ كَمْ لَبِثْتُمْ قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالُوا۟ رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ فَٱبْعَثُوٓا۟ أَحَدَكُم بِوَرِقِكُمْ هَٰذِهِۦٓ إِلَى ٱلْمَدِينَةِ فَلْيَنظُرْ أَيُّهَآ أَزْكَىٰ طَعَامًا فَلْيَأْتِكُم بِرِزْقٍ مِّنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ أَحَدًا', 'd56ae1ef8605bd39445ef50f6b8ac5b43d86773cd65b8dc6124429d15656dfa4', 'وَكَذَٰلِكَ بَعَثْنَٰهُمْ لِيَتَسَآءَلُوا۟ بَيْنَهُمْ قَالَ قَآئِلٌ مِّنْهُمْ كَمْ لَبِثْتُمْ قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالُوا۟ رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ فَٱبْعَثُوٓا۟ أَحَدَكُم بِوَرِقِكُمْ هَٰذِهِۦٓ إِلَى ٱلْمَدِينَةِ فَلْيَنظُرْ أَيُّهَآ أَزْكَىٰ طَعَامًا فَلْيَأْتِكُم بِرِزْقٍ مِّنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ أَحَدًا', 'd56ae1ef8605bd39445ef50f6b8ac5b43d86773cd65b8dc6124429d15656dfa4', 'd56ae1ef8605bd39445ef50f6b8ac5b43d86773cd65b8dc6124429d15656dfa4', NULL, 'وكذلك بعثنهم ليتساءلوا بينهم قال قائل منهم كم لبثتم قالوا لبثنا يوما او بعض يوم قالوا ربكم اعلم بما لبثتم فابعثوا احدكم بورقكم هذه الي المدينه فلينظر ايها ازكي طعاما فلياتكم برزق منه وليتلطف ولا يشعرن بكم احدا', 15, 30, 118, 1, 4, 295, false, NULL),
    (2160, 'tanzil-uthmani-v1.1', 18, 20, 'إِنَّهُمْ إِن يَظْهَرُوا۟ عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِى مِلَّتِهِمْ وَلَن تُفْلِحُوٓا۟ إِذًا أَبَدًا', '59e1eb38bb1b0a3c1de0e32ea8b7b69fb45917cebe4483d452e7179101004315', 'إِنَّهُمْ إِن يَظْهَرُوا۟ عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِى مِلَّتِهِمْ وَلَن تُفْلِحُوٓا۟ إِذًا أَبَدًا', '59e1eb38bb1b0a3c1de0e32ea8b7b69fb45917cebe4483d452e7179101004315', '59e1eb38bb1b0a3c1de0e32ea8b7b69fb45917cebe4483d452e7179101004315', NULL, 'انهم ان يظهروا عليكم يرجموكم او يعيدوكم في ملتهم ولن تفلحوا اذا ابدا', 15, 30, 118, 1, 4, 295, false, NULL),
    (2161, 'tanzil-uthmani-v1.1', 18, 21, 'وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوٓا۟ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَأَنَّ ٱلسَّاعَةَ لَا رَيْبَ فِيهَآ إِذْ يَتَنَٰزَعُونَ بَيْنَهُمْ أَمْرَهُمْ فَقَالُوا۟ ٱبْنُوا۟ عَلَيْهِم بُنْيَٰنًا رَّبُّهُمْ أَعْلَمُ بِهِمْ قَالَ ٱلَّذِينَ غَلَبُوا۟ عَلَىٰٓ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِدًا', 'd60c72f5d968b2c7e3052daad93574e79b869ccba6004be5b0405282b63a1cbe', 'وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوٓا۟ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَأَنَّ ٱلسَّاعَةَ لَا رَيْبَ فِيهَآ إِذْ يَتَنَٰزَعُونَ بَيْنَهُمْ أَمْرَهُمْ فَقَالُوا۟ ٱبْنُوا۟ عَلَيْهِم بُنْيَٰنًا رَّبُّهُمْ أَعْلَمُ بِهِمْ قَالَ ٱلَّذِينَ غَلَبُوا۟ عَلَىٰٓ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِدًا', 'd60c72f5d968b2c7e3052daad93574e79b869ccba6004be5b0405282b63a1cbe', 'd60c72f5d968b2c7e3052daad93574e79b869ccba6004be5b0405282b63a1cbe', NULL, 'وكذلك اعثرنا عليهم ليعلموا ان وعد الله حق وان الساعه لا ريب فيها اذ يتنزعون بينهم امرهم فقالوا ابنوا عليهم بنينا ربهم اعلم بهم قال الذين غلبوا علي امرهم لنتخذن عليهم مسجدا', 15, 30, 118, 1, 4, 296, false, NULL),
    (2162, 'tanzil-uthmani-v1.1', 18, 22, 'سَيَقُولُونَ ثَلَٰثَةٌ رَّابِعُهُمْ كَلْبُهُمْ وَيَقُولُونَ خَمْسَةٌ سَادِسُهُمْ كَلْبُهُمْ رَجْمًۢا بِٱلْغَيْبِ وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ قُل رَّبِّىٓ أَعْلَمُ بِعِدَّتِهِم مَّا يَعْلَمُهُمْ إِلَّا قَلِيلٌ فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَآءً ظَٰهِرًا وَلَا تَسْتَفْتِ فِيهِم مِّنْهُمْ أَحَدًا', 'c9e3d70e440d7d3faf0139b6d6d2b68ee1a20e9c890e2a742425197355c137b3', 'سَيَقُولُونَ ثَلَٰثَةٌ رَّابِعُهُمْ كَلْبُهُمْ وَيَقُولُونَ خَمْسَةٌ سَادِسُهُمْ كَلْبُهُمْ رَجْمًۢا بِٱلْغَيْبِ وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ قُل رَّبِّىٓ أَعْلَمُ بِعِدَّتِهِم مَّا يَعْلَمُهُمْ إِلَّا قَلِيلٌ فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَآءً ظَٰهِرًا وَلَا تَسْتَفْتِ فِيهِم مِّنْهُمْ أَحَدًا', 'c9e3d70e440d7d3faf0139b6d6d2b68ee1a20e9c890e2a742425197355c137b3', 'c9e3d70e440d7d3faf0139b6d6d2b68ee1a20e9c890e2a742425197355c137b3', NULL, 'سيقولون ثلثه رابعهم كلبهم ويقولون خمسه سادسهم كلبهم رجما بالغيب ويقولون سبعه وثامنهم كلبهم قل ربي اعلم بعدتهم ما يعلمهم الا قليل فلا تمار فيهم الا مراء ظهرا ولا تستفت فيهم منهم احدا', 15, 30, 118, 1, 4, 296, false, NULL),
    (2163, 'tanzil-uthmani-v1.1', 18, 23, 'وَلَا تَقُولَنَّ لِشَا۟ىْءٍ إِنِّى فَاعِلٌ ذَٰلِكَ غَدًا', 'c3d75dc92f633e350c17850c60ce9d87159c2115074ddca16705d09bd2e9545f', 'وَلَا تَقُولَنَّ لِشَا۟ىْءٍ إِنِّى فَاعِلٌ ذَٰلِكَ غَدًا', 'c3d75dc92f633e350c17850c60ce9d87159c2115074ddca16705d09bd2e9545f', 'c3d75dc92f633e350c17850c60ce9d87159c2115074ddca16705d09bd2e9545f', NULL, 'ولا تقولن لشايء اني فاعل ذلك غدا', 15, 30, 118, 1, 4, 296, false, NULL),
    (2164, 'tanzil-uthmani-v1.1', 18, 24, 'إِلَّآ أَن يَشَآءَ ٱللَّهُ وَٱذْكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلْ عَسَىٰٓ أَن يَهْدِيَنِ رَبِّى لِأَقْرَبَ مِنْ هَٰذَا رَشَدًا', 'fb6a16674bfd75bd7f01cb6750a0da8c42c6481d12d9599bdd3e1d61752d3744', 'إِلَّآ أَن يَشَآءَ ٱللَّهُ وَٱذْكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلْ عَسَىٰٓ أَن يَهْدِيَنِ رَبِّى لِأَقْرَبَ مِنْ هَٰذَا رَشَدًا', 'fb6a16674bfd75bd7f01cb6750a0da8c42c6481d12d9599bdd3e1d61752d3744', 'fb6a16674bfd75bd7f01cb6750a0da8c42c6481d12d9599bdd3e1d61752d3744', NULL, 'الا ان يشاء الله واذكر ربك اذا نسيت وقل عسي ان يهدين ربي لاقرب من هذا رشدا', 15, 30, 118, 1, 4, 296, false, NULL),
    (2165, 'tanzil-uthmani-v1.1', 18, 25, 'وَلَبِثُوا۟ فِى كَهْفِهِمْ ثَلَٰثَ مِا۟ئَةٍ سِنِينَ وَٱزْدَادُوا۟ تِسْعًا', '2f7f3d2dfe9489de22a2af2e9950aeea2658548df9997d1dd52a63edd71b01cf', 'وَلَبِثُوا۟ فِى كَهْفِهِمْ ثَلَٰثَ مِا۟ئَةٍ سِنِينَ وَٱزْدَادُوا۟ تِسْعًا', '2f7f3d2dfe9489de22a2af2e9950aeea2658548df9997d1dd52a63edd71b01cf', '2f7f3d2dfe9489de22a2af2e9950aeea2658548df9997d1dd52a63edd71b01cf', NULL, 'ولبثوا في كهفهم ثلث مائه سنين وازدادوا تسعا', 15, 30, 118, 1, 4, 296, false, NULL),
    (2166, 'tanzil-uthmani-v1.1', 18, 26, 'قُلِ ٱللَّهُ أَعْلَمُ بِمَا لَبِثُوا۟ لَهُۥ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَبْصِرْ بِهِۦ وَأَسْمِعْ مَا لَهُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا يُشْرِكُ فِى حُكْمِهِۦٓ أَحَدًا', '6062038070d0f95616afaadb299cf4080cb6510d3eb0d45a0d76db4b918efea1', 'قُلِ ٱللَّهُ أَعْلَمُ بِمَا لَبِثُوا۟ لَهُۥ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَبْصِرْ بِهِۦ وَأَسْمِعْ مَا لَهُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا يُشْرِكُ فِى حُكْمِهِۦٓ أَحَدًا', '6062038070d0f95616afaadb299cf4080cb6510d3eb0d45a0d76db4b918efea1', '6062038070d0f95616afaadb299cf4080cb6510d3eb0d45a0d76db4b918efea1', NULL, 'قل الله اعلم بما لبثوا له غيب السموت والارض ابصر به واسمع ما لهم من دونه من ولي ولا يشرك في حكمه احدا', 15, 30, 118, 1, 4, 296, false, NULL),
    (2167, 'tanzil-uthmani-v1.1', 18, 27, 'وَٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِن كِتَابِ رَبِّكَ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', '284501da5117a89c342a6ef2a35d97ba531e67020b4d6bd39d4a4fd25995d96c', 'وَٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِن كِتَابِ رَبِّكَ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', '284501da5117a89c342a6ef2a35d97ba531e67020b4d6bd39d4a4fd25995d96c', '284501da5117a89c342a6ef2a35d97ba531e67020b4d6bd39d4a4fd25995d96c', NULL, 'واتل ما اوحي اليك من كتاب ربك لا مبدل لكلمته ولن تجد من دونه ملتحدا', 15, 30, 118, 1, 4, 296, false, NULL),
    (2168, 'tanzil-uthmani-v1.1', 18, 28, 'وَٱصْبِرْ نَفْسَكَ مَعَ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ تُرِيدُ زِينَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُۥ عَن ذِكْرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمْرُهُۥ فُرُطًا', '489148eb75cdbe8d1e7bc83f842eb1a35fa321a2e4fa5a024466ae2dceeab2cf', 'وَٱصْبِرْ نَفْسَكَ مَعَ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ تُرِيدُ زِينَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُۥ عَن ذِكْرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمْرُهُۥ فُرُطًا', '489148eb75cdbe8d1e7bc83f842eb1a35fa321a2e4fa5a024466ae2dceeab2cf', '489148eb75cdbe8d1e7bc83f842eb1a35fa321a2e4fa5a024466ae2dceeab2cf', NULL, 'واصبر نفسك مع الذين يدعون ربهم بالغدوه والعشي يريدون وجهه ولا تعد عيناك عنهم تريد زينه الحيوه الدنيا ولا تطع من اغفلنا قلبه عن ذكرنا واتبع هويه وكان امره فرطا', 15, 30, 118, 1, 4, 297, false, NULL),
    (2169, 'tanzil-uthmani-v1.1', 18, 29, 'وَقُلِ ٱلْحَقُّ مِن رَّبِّكُمْ فَمَن شَآءَ فَلْيُؤْمِن وَمَن شَآءَ فَلْيَكْفُرْ إِنَّآ أَعْتَدْنَا لِلظَّٰلِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا وَإِن يَسْتَغِيثُوا۟ يُغَاثُوا۟ بِمَآءٍ كَٱلْمُهْلِ يَشْوِى ٱلْوُجُوهَ بِئْسَ ٱلشَّرَابُ وَسَآءَتْ مُرْتَفَقًا', '34af82cef93fc205d7ab94256f4508db1b2958fd0632b616191130330a1fb7b1', 'وَقُلِ ٱلْحَقُّ مِن رَّبِّكُمْ فَمَن شَآءَ فَلْيُؤْمِن وَمَن شَآءَ فَلْيَكْفُرْ إِنَّآ أَعْتَدْنَا لِلظَّٰلِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا وَإِن يَسْتَغِيثُوا۟ يُغَاثُوا۟ بِمَآءٍ كَٱلْمُهْلِ يَشْوِى ٱلْوُجُوهَ بِئْسَ ٱلشَّرَابُ وَسَآءَتْ مُرْتَفَقًا', '34af82cef93fc205d7ab94256f4508db1b2958fd0632b616191130330a1fb7b1', '34af82cef93fc205d7ab94256f4508db1b2958fd0632b616191130330a1fb7b1', NULL, 'وقل الحق من ربكم فمن شاء فليؤمن ومن شاء فليكفر انا اعتدنا للظلمين نارا احاط بهم سرادقها وان يستغيثوا يغاثوا بماء كالمهل يشوي الوجوه بئس الشراب وساءت مرتفقا', 15, 30, 118, 1, 4, 297, false, NULL),
    (2170, 'tanzil-uthmani-v1.1', 18, 30, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا', '37d863d1bdb8b4ce58ca6dc44d66d16207f03e7f536d482aadbe00dbfa31d5fa', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا', '37d863d1bdb8b4ce58ca6dc44d66d16207f03e7f536d482aadbe00dbfa31d5fa', '37d863d1bdb8b4ce58ca6dc44d66d16207f03e7f536d482aadbe00dbfa31d5fa', NULL, 'ان الذين ءامنوا وعملوا الصلحت انا لا نضيع اجر من احسن عملا', 15, 30, 118, 1, 4, 297, false, NULL),
    (2171, 'tanzil-uthmani-v1.1', 18, 31, 'أُو۟لَٰٓئِكَ لَهُمْ جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَيَلْبَسُونَ ثِيَابًا خُضْرًا مِّن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ نِعْمَ ٱلثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا', '327b5d561972ffb18aeb28d10b8db67601fa33d43fd9ac14dfb2ca6cb8028bbe', 'أُو۟لَٰٓئِكَ لَهُمْ جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَيَلْبَسُونَ ثِيَابًا خُضْرًا مِّن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ نِعْمَ ٱلثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا', '327b5d561972ffb18aeb28d10b8db67601fa33d43fd9ac14dfb2ca6cb8028bbe', '327b5d561972ffb18aeb28d10b8db67601fa33d43fd9ac14dfb2ca6cb8028bbe', NULL, 'اولئك لهم جنت عدن تجري من تحتهم الانهر يحلون فيها من اساور من ذهب ويلبسون ثيابا خضرا من سندس واستبرق متكين فيها علي الارائك نعم الثواب وحسنت مرتفقا', 15, 30, 118, 1, 4, 297, false, NULL),
    (2172, 'tanzil-uthmani-v1.1', 18, 32, 'وَٱضْرِبْ لَهُم مَّثَلًا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَٰبٍ وَحَفَفْنَٰهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا', '4ebde14b667105ab8fcbe352430d46c570b92fab074df813dea18ec2e67eb071', 'وَٱضْرِبْ لَهُم مَّثَلًا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَٰبٍ وَحَفَفْنَٰهُمَا بِنَخْلٍ وَجَعَلْنَا بَيْنَهُمَا زَرْعًا', '4ebde14b667105ab8fcbe352430d46c570b92fab074df813dea18ec2e67eb071', '4ebde14b667105ab8fcbe352430d46c570b92fab074df813dea18ec2e67eb071', NULL, 'واضرب لهم مثلا رجلين جعلنا لاحدهما جنتين من اعنب وحففنهما بنخل وجعلنا بينهما زرعا', 15, 30, 119, 1, 4, 297, false, NULL),
    (2173, 'tanzil-uthmani-v1.1', 18, 33, 'كِلْتَا ٱلْجَنَّتَيْنِ ءَاتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْـًٔا وَفَجَّرْنَا خِلَٰلَهُمَا نَهَرًا', 'eb20b446a27babcc2846aa3b0c90f990f24542dc1807a5d83e4f15336265a57e', 'كِلْتَا ٱلْجَنَّتَيْنِ ءَاتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْـًٔا وَفَجَّرْنَا خِلَٰلَهُمَا نَهَرًا', 'eb20b446a27babcc2846aa3b0c90f990f24542dc1807a5d83e4f15336265a57e', 'eb20b446a27babcc2846aa3b0c90f990f24542dc1807a5d83e4f15336265a57e', NULL, 'كلتا الجنتين ءاتت اكلها ولم تظلم منه شيا وفجرنا خللهما نهرا', 15, 30, 119, 1, 4, 297, false, NULL),
    (2174, 'tanzil-uthmani-v1.1', 18, 34, 'وَكَانَ لَهُۥ ثَمَرٌ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكْثَرُ مِنكَ مَالًا وَأَعَزُّ نَفَرًا', '411624d35c66ae6c0018a687320af8284d30601d44283cae42d816e2426eb05b', 'وَكَانَ لَهُۥ ثَمَرٌ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكْثَرُ مِنكَ مَالًا وَأَعَزُّ نَفَرًا', '411624d35c66ae6c0018a687320af8284d30601d44283cae42d816e2426eb05b', '411624d35c66ae6c0018a687320af8284d30601d44283cae42d816e2426eb05b', NULL, 'وكان له ثمر فقال لصحبه وهو يحاوره انا اكثر منك مالا واعز نفرا', 15, 30, 119, 1, 4, 297, false, NULL),
    (2175, 'tanzil-uthmani-v1.1', 18, 35, 'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٌ لِّنَفْسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدًا', 'b9f6b757e802179ac4776734ca3d2af01e551ed4ac3812ae165c27dfb94ebf80', 'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٌ لِّنَفْسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدًا', 'b9f6b757e802179ac4776734ca3d2af01e551ed4ac3812ae165c27dfb94ebf80', 'b9f6b757e802179ac4776734ca3d2af01e551ed4ac3812ae165c27dfb94ebf80', NULL, 'ودخل جنته وهو ظالم لنفسه قال ما اظن ان تبيد هذه ابدا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2176, 'tanzil-uthmani-v1.1', 18, 36, 'وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّى لَأَجِدَنَّ خَيْرًا مِّنْهَا مُنقَلَبًا', '24db0b32585ff1c8d79b7a0882e8660ffc819512294f1d1a800df66565462caf', 'وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّى لَأَجِدَنَّ خَيْرًا مِّنْهَا مُنقَلَبًا', '24db0b32585ff1c8d79b7a0882e8660ffc819512294f1d1a800df66565462caf', '24db0b32585ff1c8d79b7a0882e8660ffc819512294f1d1a800df66565462caf', NULL, 'وما اظن الساعه قائمه ولئن رددت الي ربي لاجدن خيرا منها منقلبا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2177, 'tanzil-uthmani-v1.1', 18, 37, 'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرْتَ بِٱلَّذِى خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ سَوَّىٰكَ رَجُلًا', '76247b331862dd79bc221367544a624fdbf8ea6509ab1e330f429fe3636cf651', 'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرْتَ بِٱلَّذِى خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ سَوَّىٰكَ رَجُلًا', '76247b331862dd79bc221367544a624fdbf8ea6509ab1e330f429fe3636cf651', '76247b331862dd79bc221367544a624fdbf8ea6509ab1e330f429fe3636cf651', NULL, 'قال له صاحبه وهو يحاوره اكفرت بالذي خلقك من تراب ثم من نطفه ثم سويك رجلا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2178, 'tanzil-uthmani-v1.1', 18, 38, 'لَّٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّى وَلَآ أُشْرِكُ بِرَبِّىٓ أَحَدًا', '6fa174de045f9c462ee2bf30b29673b1918a397fb422179a764a3c1a979183c9', 'لَّٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّى وَلَآ أُشْرِكُ بِرَبِّىٓ أَحَدًا', '6fa174de045f9c462ee2bf30b29673b1918a397fb422179a764a3c1a979183c9', '6fa174de045f9c462ee2bf30b29673b1918a397fb422179a764a3c1a979183c9', NULL, 'لكنا هو الله ربي ولا اشرك بربي احدا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2179, 'tanzil-uthmani-v1.1', 18, 39, 'وَلَوْلَآ إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالًا وَوَلَدًا', 'e0dbf6100ec8004725aab46276d2d60ffce6f2b35e0413de07ebd8d778afab9a', 'وَلَوْلَآ إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالًا وَوَلَدًا', 'e0dbf6100ec8004725aab46276d2d60ffce6f2b35e0413de07ebd8d778afab9a', 'e0dbf6100ec8004725aab46276d2d60ffce6f2b35e0413de07ebd8d778afab9a', NULL, 'ولولا اذ دخلت جنتك قلت ما شاء الله لا قوه الا بالله ان ترن انا اقل منك مالا وولدا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2180, 'tanzil-uthmani-v1.1', 18, 40, 'فَعَسَىٰ رَبِّىٓ أَن يُؤْتِيَنِ خَيْرًا مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًا مِّنَ ٱلسَّمَآءِ فَتُصْبِحَ صَعِيدًا زَلَقًا', 'd955e30197f056e9caa7d0b9c68e3d5b303cd41e7bd80fb6bcecd72364acaf84', 'فَعَسَىٰ رَبِّىٓ أَن يُؤْتِيَنِ خَيْرًا مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًا مِّنَ ٱلسَّمَآءِ فَتُصْبِحَ صَعِيدًا زَلَقًا', 'd955e30197f056e9caa7d0b9c68e3d5b303cd41e7bd80fb6bcecd72364acaf84', 'd955e30197f056e9caa7d0b9c68e3d5b303cd41e7bd80fb6bcecd72364acaf84', NULL, 'فعسي ربي ان يؤتين خيرا من جنتك ويرسل عليها حسبانا من السماء فتصبح صعيدا زلقا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2181, 'tanzil-uthmani-v1.1', 18, 41, 'أَوْ يُصْبِحَ مَآؤُهَا غَوْرًا فَلَن تَسْتَطِيعَ لَهُۥ طَلَبًا', 'ff058f12436eaa90ba083d706370a61346bd4d8dd3c1141429f7869719e65cff', 'أَوْ يُصْبِحَ مَآؤُهَا غَوْرًا فَلَن تَسْتَطِيعَ لَهُۥ طَلَبًا', 'ff058f12436eaa90ba083d706370a61346bd4d8dd3c1141429f7869719e65cff', 'ff058f12436eaa90ba083d706370a61346bd4d8dd3c1141429f7869719e65cff', NULL, 'او يصبح ماؤها غورا فلن تستطيع له طلبا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2182, 'tanzil-uthmani-v1.1', 18, 42, 'وَأُحِيطَ بِثَمَرِهِۦ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيْتَنِى لَمْ أُشْرِكْ بِرَبِّىٓ أَحَدًا', 'f011dd7e38fe9a3d79a39facb545cd7510e4ba63f2f4e0630631ff41ec4683a2', 'وَأُحِيطَ بِثَمَرِهِۦ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيْتَنِى لَمْ أُشْرِكْ بِرَبِّىٓ أَحَدًا', 'f011dd7e38fe9a3d79a39facb545cd7510e4ba63f2f4e0630631ff41ec4683a2', 'f011dd7e38fe9a3d79a39facb545cd7510e4ba63f2f4e0630631ff41ec4683a2', NULL, 'واحيط بثمره فاصبح يقلب كفيه علي ما انفق فيها وهي خاويه علي عروشها ويقول يليتني لم اشرك بربي احدا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2183, 'tanzil-uthmani-v1.1', 18, 43, 'وَلَمْ تَكُن لَّهُۥ فِئَةٌ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا', '9428152e84c83567937f9ea925869a9682d09286fdaef1e03d5b019de820b982', 'وَلَمْ تَكُن لَّهُۥ فِئَةٌ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا', '9428152e84c83567937f9ea925869a9682d09286fdaef1e03d5b019de820b982', '9428152e84c83567937f9ea925869a9682d09286fdaef1e03d5b019de820b982', NULL, 'ولم تكن له فئه ينصرونه من دون الله وما كان منتصرا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2184, 'tanzil-uthmani-v1.1', 18, 44, 'هُنَالِكَ ٱلْوَلَٰيَةُ لِلَّهِ ٱلْحَقِّ هُوَ خَيْرٌ ثَوَابًا وَخَيْرٌ عُقْبًا', 'b77ce989e834d65ae0eae77272af4e2d4d7e4334c9cae2aa27d6930b9db73032', 'هُنَالِكَ ٱلْوَلَٰيَةُ لِلَّهِ ٱلْحَقِّ هُوَ خَيْرٌ ثَوَابًا وَخَيْرٌ عُقْبًا', 'b77ce989e834d65ae0eae77272af4e2d4d7e4334c9cae2aa27d6930b9db73032', 'b77ce989e834d65ae0eae77272af4e2d4d7e4334c9cae2aa27d6930b9db73032', NULL, 'هنالك الوليه لله الحق هو خير ثوابا وخير عقبا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2185, 'tanzil-uthmani-v1.1', 18, 45, 'وَٱضْرِبْ لَهُم مَّثَلَ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ فَأَصْبَحَ هَشِيمًا تَذْرُوهُ ٱلرِّيَٰحُ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقْتَدِرًا', 'a3c6c6c8e68e9f18bed328321221cc82996c57cb88f44902b4dbfb73a874d024', 'وَٱضْرِبْ لَهُم مَّثَلَ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ فَأَصْبَحَ هَشِيمًا تَذْرُوهُ ٱلرِّيَٰحُ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقْتَدِرًا', 'a3c6c6c8e68e9f18bed328321221cc82996c57cb88f44902b4dbfb73a874d024', 'a3c6c6c8e68e9f18bed328321221cc82996c57cb88f44902b4dbfb73a874d024', NULL, 'واضرب لهم مثل الحيوه الدنيا كماء انزلنه من السماء فاختلط به نبات الارض فاصبح هشيما تذروه الريح وكان الله علي كل شيء مقتدرا', 15, 30, 119, 1, 4, 298, false, NULL),
    (2186, 'tanzil-uthmani-v1.1', 18, 46, 'ٱلْمَالُ وَٱلْبَنُونَ زِينَةُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلًا', '56fd1c58c147876f558c1f15a00f496c5ba3a1f15162440923d59e1577ea62f5', 'ٱلْمَالُ وَٱلْبَنُونَ زِينَةُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلًا', '56fd1c58c147876f558c1f15a00f496c5ba3a1f15162440923d59e1577ea62f5', '56fd1c58c147876f558c1f15a00f496c5ba3a1f15162440923d59e1577ea62f5', NULL, 'المال والبنون زينه الحيوه الدنيا والبقيت الصلحت خير عند ربك ثوابا وخير املا', 15, 30, 119, 1, 4, 299, false, NULL),
    (2187, 'tanzil-uthmani-v1.1', 18, 47, 'وَيَوْمَ نُسَيِّرُ ٱلْجِبَالَ وَتَرَى ٱلْأَرْضَ بَارِزَةً وَحَشَرْنَٰهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا', '8880177fa041ee202146f630def1e17ced29ac706e269c04db2574b32bf0e692', 'وَيَوْمَ نُسَيِّرُ ٱلْجِبَالَ وَتَرَى ٱلْأَرْضَ بَارِزَةً وَحَشَرْنَٰهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا', '8880177fa041ee202146f630def1e17ced29ac706e269c04db2574b32bf0e692', '8880177fa041ee202146f630def1e17ced29ac706e269c04db2574b32bf0e692', NULL, 'ويوم نسير الجبال وتري الارض بارزه وحشرنهم فلم نغادر منهم احدا', 15, 30, 119, 1, 4, 299, false, NULL),
    (2188, 'tanzil-uthmani-v1.1', 18, 48, 'وَعُرِضُوا۟ عَلَىٰ رَبِّكَ صَفًّا لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍۭ بَلْ زَعَمْتُمْ أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًا', '69806a235f39c754f08f8ab261c64ddc34eb7df27edfa6a6ff07e61a8d1ab0cc', 'وَعُرِضُوا۟ عَلَىٰ رَبِّكَ صَفًّا لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍۭ بَلْ زَعَمْتُمْ أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًا', '69806a235f39c754f08f8ab261c64ddc34eb7df27edfa6a6ff07e61a8d1ab0cc', '69806a235f39c754f08f8ab261c64ddc34eb7df27edfa6a6ff07e61a8d1ab0cc', NULL, 'وعرضوا علي ربك صفا لقد جئتمونا كما خلقنكم اول مره بل زعمتم الن نجعل لكم موعدا', 15, 30, 119, 1, 4, 299, false, NULL),
    (2189, 'tanzil-uthmani-v1.1', 18, 49, 'وَوُضِعَ ٱلْكِتَٰبُ فَتَرَى ٱلْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيْلَتَنَا مَالِ هَٰذَا ٱلْكِتَٰبِ لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّآ أَحْصَىٰهَا وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرًا وَلَا يَظْلِمُ رَبُّكَ أَحَدًا', 'db39a4c0a0482aacd88acd01795f032c447c02ad88dfcf205d2a8f40fd4602df', 'وَوُضِعَ ٱلْكِتَٰبُ فَتَرَى ٱلْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيْلَتَنَا مَالِ هَٰذَا ٱلْكِتَٰبِ لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً إِلَّآ أَحْصَىٰهَا وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرًا وَلَا يَظْلِمُ رَبُّكَ أَحَدًا', 'db39a4c0a0482aacd88acd01795f032c447c02ad88dfcf205d2a8f40fd4602df', 'db39a4c0a0482aacd88acd01795f032c447c02ad88dfcf205d2a8f40fd4602df', NULL, 'ووضع الكتب فتري المجرمين مشفقين مما فيه ويقولون يويلتنا مال هذا الكتب لا يغادر صغيره ولا كبيره الا احصيها ووجدوا ما عملوا حاضرا ولا يظلم ربك احدا', 15, 30, 119, 1, 4, 299, false, NULL),
    (2190, 'tanzil-uthmani-v1.1', 18, 50, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦٓ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوْلِيَآءَ مِن دُونِى وَهُمْ لَكُمْ عَدُوٌّۢ بِئْسَ لِلظَّٰلِمِينَ بَدَلًا', '0ab71ca46314e0f1f437f1859174d4ecdbd714e5bc465d2eb87672c986552b14', 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦٓ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوْلِيَآءَ مِن دُونِى وَهُمْ لَكُمْ عَدُوٌّۢ بِئْسَ لِلظَّٰلِمِينَ بَدَلًا', '0ab71ca46314e0f1f437f1859174d4ecdbd714e5bc465d2eb87672c986552b14', '0ab71ca46314e0f1f437f1859174d4ecdbd714e5bc465d2eb87672c986552b14', NULL, 'واذ قلنا للملئكه اسجدوا لادم فسجدوا الا ابليس كان من الجن ففسق عن امر ربه افتتخذونه وذريته اولياء من دوني وهم لكم عدو بئس للظلمين بدلا', 15, 30, 119, 1, 4, 299, false, NULL),
    (2191, 'tanzil-uthmani-v1.1', 18, 51, 'مَّآ أَشْهَدتُّهُمْ خَلْقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ ٱلْمُضِلِّينَ عَضُدًا', '73c35fb539217d8dffd4f5d52656f9017d0af4ff3723873ce2c1998a2a1f324f', 'مَّآ أَشْهَدتُّهُمْ خَلْقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ ٱلْمُضِلِّينَ عَضُدًا', '73c35fb539217d8dffd4f5d52656f9017d0af4ff3723873ce2c1998a2a1f324f', '73c35fb539217d8dffd4f5d52656f9017d0af4ff3723873ce2c1998a2a1f324f', NULL, 'ما اشهدتهم خلق السموت والارض ولا خلق انفسهم وما كنت متخذ المضلين عضدا', 15, 30, 120, 1, 4, 299, false, NULL),
    (2192, 'tanzil-uthmani-v1.1', 18, 52, 'وَيَوْمَ يَقُولُ نَادُوا۟ شُرَكَآءِىَ ٱلَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقًا', 'c0f5c205124fa8b4d79a9fec722f16249c537980c6eae8995d392b658a535479', 'وَيَوْمَ يَقُولُ نَادُوا۟ شُرَكَآءِىَ ٱلَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقًا', 'c0f5c205124fa8b4d79a9fec722f16249c537980c6eae8995d392b658a535479', 'c0f5c205124fa8b4d79a9fec722f16249c537980c6eae8995d392b658a535479', NULL, 'ويوم يقول نادوا شركاءي الذين زعمتم فدعوهم فلم يستجيبوا لهم وجعلنا بينهم موبقا', 15, 30, 120, 1, 4, 299, false, NULL),
    (2193, 'tanzil-uthmani-v1.1', 18, 53, 'وَرَءَا ٱلْمُجْرِمُونَ ٱلنَّارَ فَظَنُّوٓا۟ أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُوا۟ عَنْهَا مَصْرِفًا', '2216d0dfd72a03dcc09adb1cadacf02af420c68d283757d4d908e3e6d777c075', 'وَرَءَا ٱلْمُجْرِمُونَ ٱلنَّارَ فَظَنُّوٓا۟ أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُوا۟ عَنْهَا مَصْرِفًا', '2216d0dfd72a03dcc09adb1cadacf02af420c68d283757d4d908e3e6d777c075', '2216d0dfd72a03dcc09adb1cadacf02af420c68d283757d4d908e3e6d777c075', NULL, 'ورءا المجرمون النار فظنوا انهم مواقعوها ولم يجدوا عنها مصرفا', 15, 30, 120, 1, 4, 299, false, NULL),
    (2194, 'tanzil-uthmani-v1.1', 18, 54, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٍ وَكَانَ ٱلْإِنسَٰنُ أَكْثَرَ شَىْءٍ جَدَلًا', '9213264d20bbdfd02a7b9e47b7737a29e9c89198aced703a67b0531ebcaeb204', 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٍ وَكَانَ ٱلْإِنسَٰنُ أَكْثَرَ شَىْءٍ جَدَلًا', '9213264d20bbdfd02a7b9e47b7737a29e9c89198aced703a67b0531ebcaeb204', '9213264d20bbdfd02a7b9e47b7737a29e9c89198aced703a67b0531ebcaeb204', NULL, 'ولقد صرفنا في هذا القرءان للناس من كل مثل وكان الانسن اكثر شيء جدلا', 15, 30, 120, 1, 4, 300, false, NULL),
    (2195, 'tanzil-uthmani-v1.1', 18, 55, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰ وَيَسْتَغْفِرُوا۟ رَبَّهُمْ إِلَّآ أَن تَأْتِيَهُمْ سُنَّةُ ٱلْأَوَّلِينَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ قُبُلًا', 'a49197d68b1ca9acec17986f69c790b3567203195af586632b326a71162f8dfb', 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰ وَيَسْتَغْفِرُوا۟ رَبَّهُمْ إِلَّآ أَن تَأْتِيَهُمْ سُنَّةُ ٱلْأَوَّلِينَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ قُبُلًا', 'a49197d68b1ca9acec17986f69c790b3567203195af586632b326a71162f8dfb', 'a49197d68b1ca9acec17986f69c790b3567203195af586632b326a71162f8dfb', NULL, 'وما منع الناس ان يؤمنوا اذ جاءهم الهدي ويستغفروا ربهم الا ان تاتيهم سنه الاولين او ياتيهم العذاب قبلا', 15, 30, 120, 1, 4, 300, false, NULL),
    (2196, 'tanzil-uthmani-v1.1', 18, 56, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَمَآ أُنذِرُوا۟ هُزُوًا', '3847cc70e78835b3cfe9c468ded256235eb848de2f8b47855a9e253b49e499d7', 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَمَآ أُنذِرُوا۟ هُزُوًا', '3847cc70e78835b3cfe9c468ded256235eb848de2f8b47855a9e253b49e499d7', '3847cc70e78835b3cfe9c468ded256235eb848de2f8b47855a9e253b49e499d7', NULL, 'وما نرسل المرسلين الا مبشرين ومنذرين ويجدل الذين كفروا بالبطل ليدحضوا به الحق واتخذوا ءايتي وما انذروا هزوا', 15, 30, 120, 1, 4, 300, false, NULL),
    (2197, 'tanzil-uthmani-v1.1', 18, 57, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعْرَضَ عَنْهَا وَنَسِىَ مَا قَدَّمَتْ يَدَاهُ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِن تَدْعُهُمْ إِلَى ٱلْهُدَىٰ فَلَن يَهْتَدُوٓا۟ إِذًا أَبَدًا', '11a172a758ab6b742cee2cbd76e1219f22b2722bcb2a2d56c9a99f517cdf090a', 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعْرَضَ عَنْهَا وَنَسِىَ مَا قَدَّمَتْ يَدَاهُ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا وَإِن تَدْعُهُمْ إِلَى ٱلْهُدَىٰ فَلَن يَهْتَدُوٓا۟ إِذًا أَبَدًا', '11a172a758ab6b742cee2cbd76e1219f22b2722bcb2a2d56c9a99f517cdf090a', '11a172a758ab6b742cee2cbd76e1219f22b2722bcb2a2d56c9a99f517cdf090a', NULL, 'ومن اظلم ممن ذكر بايت ربه فاعرض عنها ونسي ما قدمت يداه انا جعلنا علي قلوبهم اكنه ان يفقهوه وفي ءاذانهم وقرا وان تدعهم الي الهدي فلن يهتدوا اذا ابدا', 15, 30, 120, 1, 4, 300, false, NULL),
    (2198, 'tanzil-uthmani-v1.1', 18, 58, 'وَرَبُّكَ ٱلْغَفُورُ ذُو ٱلرَّحْمَةِ لَوْ يُؤَاخِذُهُم بِمَا كَسَبُوا۟ لَعَجَّلَ لَهُمُ ٱلْعَذَابَ بَل لَّهُم مَّوْعِدٌ لَّن يَجِدُوا۟ مِن دُونِهِۦ مَوْئِلًا', '82f6300327804faabe1590e9392fedce8c5c472904c14f386097599c10b28e16', 'وَرَبُّكَ ٱلْغَفُورُ ذُو ٱلرَّحْمَةِ لَوْ يُؤَاخِذُهُم بِمَا كَسَبُوا۟ لَعَجَّلَ لَهُمُ ٱلْعَذَابَ بَل لَّهُم مَّوْعِدٌ لَّن يَجِدُوا۟ مِن دُونِهِۦ مَوْئِلًا', '82f6300327804faabe1590e9392fedce8c5c472904c14f386097599c10b28e16', '82f6300327804faabe1590e9392fedce8c5c472904c14f386097599c10b28e16', NULL, 'وربك الغفور ذو الرحمه لو يؤاخذهم بما كسبوا لعجل لهم العذاب بل لهم موعد لن يجدوا من دونه موئلا', 15, 30, 120, 1, 4, 300, false, NULL),
    (2199, 'tanzil-uthmani-v1.1', 18, 59, 'وَتِلْكَ ٱلْقُرَىٰٓ أَهْلَكْنَٰهُمْ لَمَّا ظَلَمُوا۟ وَجَعَلْنَا لِمَهْلِكِهِم مَّوْعِدًا', '2b20ebd25d47564fb2813daf1889b6d241bb809af3d372ac7c69593600b560f5', 'وَتِلْكَ ٱلْقُرَىٰٓ أَهْلَكْنَٰهُمْ لَمَّا ظَلَمُوا۟ وَجَعَلْنَا لِمَهْلِكِهِم مَّوْعِدًا', '2b20ebd25d47564fb2813daf1889b6d241bb809af3d372ac7c69593600b560f5', '2b20ebd25d47564fb2813daf1889b6d241bb809af3d372ac7c69593600b560f5', NULL, 'وتلك القري اهلكنهم لما ظلموا وجعلنا لمهلكهم موعدا', 15, 30, 120, 1, 4, 300, false, NULL),
    (2200, 'tanzil-uthmani-v1.1', 18, 60, 'وَإِذْ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبْرَحُ حَتَّىٰٓ أَبْلُغَ مَجْمَعَ ٱلْبَحْرَيْنِ أَوْ أَمْضِىَ حُقُبًا', 'd4efb453ffbec4640757d43c1c121a51e606b5221f1d6105692de554eaf421f0', 'وَإِذْ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبْرَحُ حَتَّىٰٓ أَبْلُغَ مَجْمَعَ ٱلْبَحْرَيْنِ أَوْ أَمْضِىَ حُقُبًا', 'd4efb453ffbec4640757d43c1c121a51e606b5221f1d6105692de554eaf421f0', 'd4efb453ffbec4640757d43c1c121a51e606b5221f1d6105692de554eaf421f0', NULL, 'واذ قال موسي لفتيه لا ابرح حتي ابلغ مجمع البحرين او امضي حقبا', 15, 30, 120, 1, 4, 300, false, NULL),
    (2201, 'tanzil-uthmani-v1.1', 18, 61, 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ سَرَبًا', '11a51b6b53c2653bf66bc5e82e0efee86814aebc445391388318ea89c9888a4a', 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ سَرَبًا', '11a51b6b53c2653bf66bc5e82e0efee86814aebc445391388318ea89c9888a4a', '11a51b6b53c2653bf66bc5e82e0efee86814aebc445391388318ea89c9888a4a', NULL, 'فلما بلغا مجمع بينهما نسيا حوتهما فاتخذ سبيله في البحر سربا', 15, 30, 120, 1, 4, 300, false, NULL),
    (2202, 'tanzil-uthmani-v1.1', 18, 62, 'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبًا', '53fd1934c91302b23ffad6fde776e37f4a88375149ba1849a2f07e46552a02f7', 'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبًا', '53fd1934c91302b23ffad6fde776e37f4a88375149ba1849a2f07e46552a02f7', '53fd1934c91302b23ffad6fde776e37f4a88375149ba1849a2f07e46552a02f7', NULL, 'فلما جاوزا قال لفتيه ءاتنا غداءنا لقد لقينا من سفرنا هذا نصبا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2203, 'tanzil-uthmani-v1.1', 18, 63, 'قَالَ أَرَءَيْتَ إِذْ أَوَيْنَآ إِلَى ٱلصَّخْرَةِ فَإِنِّى نَسِيتُ ٱلْحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيْطَٰنُ أَنْ أَذْكُرَهُۥ وَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ عَجَبًا', 'ba1e533d520472cfc340b317bde41f0da10877b9c95751caf5bd2e0feada4df8', 'قَالَ أَرَءَيْتَ إِذْ أَوَيْنَآ إِلَى ٱلصَّخْرَةِ فَإِنِّى نَسِيتُ ٱلْحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيْطَٰنُ أَنْ أَذْكُرَهُۥ وَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ عَجَبًا', 'ba1e533d520472cfc340b317bde41f0da10877b9c95751caf5bd2e0feada4df8', 'ba1e533d520472cfc340b317bde41f0da10877b9c95751caf5bd2e0feada4df8', NULL, 'قال ارءيت اذ اوينا الي الصخره فاني نسيت الحوت وما انسينيه الا الشيطن ان اذكره واتخذ سبيله في البحر عجبا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2204, 'tanzil-uthmani-v1.1', 18, 64, 'قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِ فَٱرْتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصًا', '9b71fccfde89cf96465a198702af4499029f47191237f792ea0f1a711e2cc16b', 'قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِ فَٱرْتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصًا', '9b71fccfde89cf96465a198702af4499029f47191237f792ea0f1a711e2cc16b', '9b71fccfde89cf96465a198702af4499029f47191237f792ea0f1a711e2cc16b', NULL, 'قال ذلك ما كنا نبغ فارتدا علي ءاثارهما قصصا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2205, 'tanzil-uthmani-v1.1', 18, 65, 'فَوَجَدَا عَبْدًا مِّنْ عِبَادِنَآ ءَاتَيْنَٰهُ رَحْمَةً مِّنْ عِندِنَا وَعَلَّمْنَٰهُ مِن لَّدُنَّا عِلْمًا', '8fc05464f9e429f94d100ca54b3269d2232d304ded5b01721c48c0cfd83e92a8', 'فَوَجَدَا عَبْدًا مِّنْ عِبَادِنَآ ءَاتَيْنَٰهُ رَحْمَةً مِّنْ عِندِنَا وَعَلَّمْنَٰهُ مِن لَّدُنَّا عِلْمًا', '8fc05464f9e429f94d100ca54b3269d2232d304ded5b01721c48c0cfd83e92a8', '8fc05464f9e429f94d100ca54b3269d2232d304ded5b01721c48c0cfd83e92a8', NULL, 'فوجدا عبدا من عبادنا ءاتينه رحمه من عندنا وعلمنه من لدنا علما', 15, 30, 120, 1, 4, 301, false, NULL),
    (2206, 'tanzil-uthmani-v1.1', 18, 66, 'قَالَ لَهُۥ مُوسَىٰ هَلْ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًا', 'c1f564c294d4eeaf73fbac658d0033988b548361fd5bf2d97c7185bd31a86d43', 'قَالَ لَهُۥ مُوسَىٰ هَلْ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًا', 'c1f564c294d4eeaf73fbac658d0033988b548361fd5bf2d97c7185bd31a86d43', 'c1f564c294d4eeaf73fbac658d0033988b548361fd5bf2d97c7185bd31a86d43', NULL, 'قال له موسي هل اتبعك علي ان تعلمن مما علمت رشدا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2207, 'tanzil-uthmani-v1.1', 18, 67, 'قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', '8a9459407e2e17754b4779831a671d117e8eb526c1fb5d162476059d0237ad58', 'قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', '8a9459407e2e17754b4779831a671d117e8eb526c1fb5d162476059d0237ad58', '8a9459407e2e17754b4779831a671d117e8eb526c1fb5d162476059d0237ad58', NULL, 'قال انك لن تستطيع معي صبرا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2208, 'tanzil-uthmani-v1.1', 18, 68, 'وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِۦ خُبْرًا', '7cb416c0c478a4bea79585d978b2920c67ba478559135891c190662b1779846b', 'وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِۦ خُبْرًا', '7cb416c0c478a4bea79585d978b2920c67ba478559135891c190662b1779846b', '7cb416c0c478a4bea79585d978b2920c67ba478559135891c190662b1779846b', NULL, 'وكيف تصبر علي ما لم تحط به خبرا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2209, 'tanzil-uthmani-v1.1', 18, 69, 'قَالَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ صَابِرًا وَلَآ أَعْصِى لَكَ أَمْرًا', '4c2283fa2aaabd44e81368c5560479cb3e4038c17af314a26345b55d35271fbc', 'قَالَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ صَابِرًا وَلَآ أَعْصِى لَكَ أَمْرًا', '4c2283fa2aaabd44e81368c5560479cb3e4038c17af314a26345b55d35271fbc', '4c2283fa2aaabd44e81368c5560479cb3e4038c17af314a26345b55d35271fbc', NULL, 'قال ستجدني ان شاء الله صابرا ولا اعصي لك امرا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2210, 'tanzil-uthmani-v1.1', 18, 70, 'قَالَ فَإِنِ ٱتَّبَعْتَنِى فَلَا تَسْـَٔلْنِى عَن شَىْءٍ حَتَّىٰٓ أُحْدِثَ لَكَ مِنْهُ ذِكْرًا', '4966bb11dd0f2c4f4a07b89fc675fe8890eccbe2075bb29138c60922aa69a4ae', 'قَالَ فَإِنِ ٱتَّبَعْتَنِى فَلَا تَسْـَٔلْنِى عَن شَىْءٍ حَتَّىٰٓ أُحْدِثَ لَكَ مِنْهُ ذِكْرًا', '4966bb11dd0f2c4f4a07b89fc675fe8890eccbe2075bb29138c60922aa69a4ae', '4966bb11dd0f2c4f4a07b89fc675fe8890eccbe2075bb29138c60922aa69a4ae', NULL, 'قال فان اتبعتني فلا تسلني عن شيء حتي احدث لك منه ذكرا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2211, 'tanzil-uthmani-v1.1', 18, 71, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِى ٱلسَّفِينَةِ خَرَقَهَا قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْـًٔا إِمْرًا', 'e93da0d8ab9b1abcbb12c4cb7d06db20b8b9063883fdf5619be86b607cb4263f', 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِى ٱلسَّفِينَةِ خَرَقَهَا قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْـًٔا إِمْرًا', 'e93da0d8ab9b1abcbb12c4cb7d06db20b8b9063883fdf5619be86b607cb4263f', 'e93da0d8ab9b1abcbb12c4cb7d06db20b8b9063883fdf5619be86b607cb4263f', NULL, 'فانطلقا حتي اذا ركبا في السفينه خرقها قال اخرقتها لتغرق اهلها لقد جئت شيا امرا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2212, 'tanzil-uthmani-v1.1', 18, 72, 'قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', '4561d55e5ff8bc5b312e1f850193eb4a2633066c22209e736523262c0f21070f', 'قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', '4561d55e5ff8bc5b312e1f850193eb4a2633066c22209e736523262c0f21070f', '4561d55e5ff8bc5b312e1f850193eb4a2633066c22209e736523262c0f21070f', NULL, 'قال الم اقل انك لن تستطيع معي صبرا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2213, 'tanzil-uthmani-v1.1', 18, 73, 'قَالَ لَا تُؤَاخِذْنِى بِمَا نَسِيتُ وَلَا تُرْهِقْنِى مِنْ أَمْرِى عُسْرًا', '14c795e3c5e2b7e17a6c83a16ba3f90f832360c58608609ec927f9ba6f62bff0', 'قَالَ لَا تُؤَاخِذْنِى بِمَا نَسِيتُ وَلَا تُرْهِقْنِى مِنْ أَمْرِى عُسْرًا', '14c795e3c5e2b7e17a6c83a16ba3f90f832360c58608609ec927f9ba6f62bff0', '14c795e3c5e2b7e17a6c83a16ba3f90f832360c58608609ec927f9ba6f62bff0', NULL, 'قال لا تؤاخذني بما نسيت ولا ترهقني من امري عسرا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2214, 'tanzil-uthmani-v1.1', 18, 74, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمًا فَقَتَلَهُۥ قَالَ أَقَتَلْتَ نَفْسًا زَكِيَّةًۢ بِغَيْرِ نَفْسٍ لَّقَدْ جِئْتَ شَيْـًٔا نُّكْرًا', '8cc4beaedad53a972ed89cb2bf1041ceb40b148b3560e5443b530d1279550f49', 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمًا فَقَتَلَهُۥ قَالَ أَقَتَلْتَ نَفْسًا زَكِيَّةًۢ بِغَيْرِ نَفْسٍ لَّقَدْ جِئْتَ شَيْـًٔا نُّكْرًا', '8cc4beaedad53a972ed89cb2bf1041ceb40b148b3560e5443b530d1279550f49', '8cc4beaedad53a972ed89cb2bf1041ceb40b148b3560e5443b530d1279550f49', NULL, 'فانطلقا حتي اذا لقيا غلما فقتله قال اقتلت نفسا زكيه بغير نفس لقد جئت شيا نكرا', 15, 30, 120, 1, 4, 301, false, NULL),
    (2215, 'tanzil-uthmani-v1.1', 18, 75, 'قَالَ أَلَمْ أَقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', '7402b53fe18a934a2e69cff14422f3f21aa7d20775a08ca743900fe07a1d14e9', 'قَالَ أَلَمْ أَقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًا', '7402b53fe18a934a2e69cff14422f3f21aa7d20775a08ca743900fe07a1d14e9', '7402b53fe18a934a2e69cff14422f3f21aa7d20775a08ca743900fe07a1d14e9', NULL, 'قال الم اقل لك انك لن تستطيع معي صبرا', 16, 31, 121, 1, 4, 302, false, NULL),
    (2216, 'tanzil-uthmani-v1.1', 18, 76, 'قَالَ إِن سَأَلْتُكَ عَن شَىْءٍۭ بَعْدَهَا فَلَا تُصَٰحِبْنِى قَدْ بَلَغْتَ مِن لَّدُنِّى عُذْرًا', 'a2af60a04406fc7d240a13777b7d85d0bd7857022547b520ba3da297bc379ccc', 'قَالَ إِن سَأَلْتُكَ عَن شَىْءٍۭ بَعْدَهَا فَلَا تُصَٰحِبْنِى قَدْ بَلَغْتَ مِن لَّدُنِّى عُذْرًا', 'a2af60a04406fc7d240a13777b7d85d0bd7857022547b520ba3da297bc379ccc', 'a2af60a04406fc7d240a13777b7d85d0bd7857022547b520ba3da297bc379ccc', NULL, 'قال ان سالتك عن شيء بعدها فلا تصحبني قد بلغت من لدني عذرا', 16, 31, 121, 1, 4, 302, false, NULL),
    (2217, 'tanzil-uthmani-v1.1', 18, 77, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهْلَ قَرْيَةٍ ٱسْتَطْعَمَآ أَهْلَهَا فَأَبَوْا۟ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥ قَالَ لَوْ شِئْتَ لَتَّخَذْتَ عَلَيْهِ أَجْرًا', 'baf792fb56f7df3552dd9f42218c3aa0935415e94023bed9193a56c8807d8b70', 'فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهْلَ قَرْيَةٍ ٱسْتَطْعَمَآ أَهْلَهَا فَأَبَوْا۟ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥ قَالَ لَوْ شِئْتَ لَتَّخَذْتَ عَلَيْهِ أَجْرًا', 'baf792fb56f7df3552dd9f42218c3aa0935415e94023bed9193a56c8807d8b70', 'baf792fb56f7df3552dd9f42218c3aa0935415e94023bed9193a56c8807d8b70', NULL, 'فانطلقا حتي اذا اتيا اهل قريه استطعما اهلها فابوا ان يضيفوهما فوجدا فيها جدارا يريد ان ينقض فاقامه قال لو شئت لتخذت عليه اجرا', 16, 31, 121, 1, 4, 302, false, NULL),
    (2218, 'tanzil-uthmani-v1.1', 18, 78, 'قَالَ هَٰذَا فِرَاقُ بَيْنِى وَبَيْنِكَ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا', 'eee7b194aa809723785d351ac4876c128f0b200533276ee27e9e50b9271637f2', 'قَالَ هَٰذَا فِرَاقُ بَيْنِى وَبَيْنِكَ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا', 'eee7b194aa809723785d351ac4876c128f0b200533276ee27e9e50b9271637f2', 'eee7b194aa809723785d351ac4876c128f0b200533276ee27e9e50b9271637f2', NULL, 'قال هذا فراق بيني وبينك سانبئك بتاويل ما لم تستطع عليه صبرا', 16, 31, 121, 1, 4, 302, false, NULL),
    (2219, 'tanzil-uthmani-v1.1', 18, 79, 'أَمَّا ٱلسَّفِينَةُ فَكَانَتْ لِمَسَٰكِينَ يَعْمَلُونَ فِى ٱلْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٌ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا', '3167ea4fb0640ad054eacd1f609075ce5791f8a36469540d0452ce32fae51453', 'أَمَّا ٱلسَّفِينَةُ فَكَانَتْ لِمَسَٰكِينَ يَعْمَلُونَ فِى ٱلْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٌ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا', '3167ea4fb0640ad054eacd1f609075ce5791f8a36469540d0452ce32fae51453', '3167ea4fb0640ad054eacd1f609075ce5791f8a36469540d0452ce32fae51453', NULL, 'اما السفينه فكانت لمسكين يعملون في البحر فاردت ان اعيبها وكان وراءهم ملك ياخذ كل سفينه غصبا', 16, 31, 121, 1, 4, 302, false, NULL),
    (2220, 'tanzil-uthmani-v1.1', 18, 80, 'وَأَمَّا ٱلْغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَآ أَن يُرْهِقَهُمَا طُغْيَٰنًا وَكُفْرًا', '98295de66212901d594bdd6c4b78458375a8ffe1cb1b3258d463ca3bf4012ff3', 'وَأَمَّا ٱلْغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَآ أَن يُرْهِقَهُمَا طُغْيَٰنًا وَكُفْرًا', '98295de66212901d594bdd6c4b78458375a8ffe1cb1b3258d463ca3bf4012ff3', '98295de66212901d594bdd6c4b78458375a8ffe1cb1b3258d463ca3bf4012ff3', NULL, 'واما الغلم فكان ابواه مؤمنين فخشينا ان يرهقهما طغينا وكفرا', 16, 31, 121, 1, 4, 302, false, NULL),
    (2221, 'tanzil-uthmani-v1.1', 18, 81, 'فَأَرَدْنَآ أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًا مِّنْهُ زَكَوٰةً وَأَقْرَبَ رُحْمًا', 'de69c98c86cbb67ce0a18c91f62e3306df882a6bf08c353e9a225f39e1793126', 'فَأَرَدْنَآ أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًا مِّنْهُ زَكَوٰةً وَأَقْرَبَ رُحْمًا', 'de69c98c86cbb67ce0a18c91f62e3306df882a6bf08c353e9a225f39e1793126', 'de69c98c86cbb67ce0a18c91f62e3306df882a6bf08c353e9a225f39e1793126', NULL, 'فاردنا ان يبدلهما ربهما خيرا منه زكوه واقرب رحما', 16, 31, 121, 1, 4, 302, false, NULL),
    (2222, 'tanzil-uthmani-v1.1', 18, 82, 'وَأَمَّا ٱلْجِدَارُ فَكَانَ لِغُلَٰمَيْنِ يَتِيمَيْنِ فِى ٱلْمَدِينَةِ وَكَانَ تَحْتَهُۥ كَنزٌ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحًا فَأَرَادَ رَبُّكَ أَن يَبْلُغَآ أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةً مِّن رَّبِّكَ وَمَا فَعَلْتُهُۥ عَنْ أَمْرِى ذَٰلِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْرًا', 'c88520fddba6ca95a2007ba68607c13c1c50b5db5f533050fe6f6c5e06d939c6', 'وَأَمَّا ٱلْجِدَارُ فَكَانَ لِغُلَٰمَيْنِ يَتِيمَيْنِ فِى ٱلْمَدِينَةِ وَكَانَ تَحْتَهُۥ كَنزٌ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحًا فَأَرَادَ رَبُّكَ أَن يَبْلُغَآ أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةً مِّن رَّبِّكَ وَمَا فَعَلْتُهُۥ عَنْ أَمْرِى ذَٰلِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْرًا', 'c88520fddba6ca95a2007ba68607c13c1c50b5db5f533050fe6f6c5e06d939c6', 'c88520fddba6ca95a2007ba68607c13c1c50b5db5f533050fe6f6c5e06d939c6', NULL, 'واما الجدار فكان لغلمين يتيمين في المدينه وكان تحته كنز لهما وكان ابوهما صلحا فاراد ربك ان يبلغا اشدهما ويستخرجا كنزهما رحمه من ربك وما فعلته عن امري ذلك تاويل ما لم تسطع عليه صبرا', 16, 31, 121, 1, 4, 302, false, NULL),
    (2223, 'tanzil-uthmani-v1.1', 18, 83, 'وَيَسْـَٔلُونَكَ عَن ذِى ٱلْقَرْنَيْنِ قُلْ سَأَتْلُوا۟ عَلَيْكُم مِّنْهُ ذِكْرًا', '791aa1e914bd19a8cde8eccd1421141f77b5f43bb6ba6380b08bba9e83d5ccd7', 'وَيَسْـَٔلُونَكَ عَن ذِى ٱلْقَرْنَيْنِ قُلْ سَأَتْلُوا۟ عَلَيْكُم مِّنْهُ ذِكْرًا', '791aa1e914bd19a8cde8eccd1421141f77b5f43bb6ba6380b08bba9e83d5ccd7', '791aa1e914bd19a8cde8eccd1421141f77b5f43bb6ba6380b08bba9e83d5ccd7', NULL, 'ويسلونك عن ذي القرنين قل ساتلوا عليكم منه ذكرا', 16, 31, 121, 1, 4, 302, false, NULL),
    (2224, 'tanzil-uthmani-v1.1', 18, 84, 'إِنَّا مَكَّنَّا لَهُۥ فِى ٱلْأَرْضِ وَءَاتَيْنَٰهُ مِن كُلِّ شَىْءٍ سَبَبًا', '50fa388e97b5a7ded8f02f7c211212aece465f04529b74208bfab2b9e3e60fc1', 'إِنَّا مَكَّنَّا لَهُۥ فِى ٱلْأَرْضِ وَءَاتَيْنَٰهُ مِن كُلِّ شَىْءٍ سَبَبًا', '50fa388e97b5a7ded8f02f7c211212aece465f04529b74208bfab2b9e3e60fc1', '50fa388e97b5a7ded8f02f7c211212aece465f04529b74208bfab2b9e3e60fc1', NULL, 'انا مكنا له في الارض وءاتينه من كل شيء سببا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2225, 'tanzil-uthmani-v1.1', 18, 85, 'فَأَتْبَعَ سَبَبًا', '500d7c60bab36abe0552f2ed6d30cf417689f2bf71d5116e3af4e642c8ba3350', 'فَأَتْبَعَ سَبَبًا', '500d7c60bab36abe0552f2ed6d30cf417689f2bf71d5116e3af4e642c8ba3350', '500d7c60bab36abe0552f2ed6d30cf417689f2bf71d5116e3af4e642c8ba3350', NULL, 'فاتبع سببا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2226, 'tanzil-uthmani-v1.1', 18, 86, 'حَتَّىٰٓ إِذَا بَلَغَ مَغْرِبَ ٱلشَّمْسِ وَجَدَهَا تَغْرُبُ فِى عَيْنٍ حَمِئَةٍ وَوَجَدَ عِندَهَا قَوْمًا قُلْنَا يَٰذَا ٱلْقَرْنَيْنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمْ حُسْنًا', 'a84761ce46c417f354f8d6c6971eb364f6218deffcc816238327d13d8fff05da', 'حَتَّىٰٓ إِذَا بَلَغَ مَغْرِبَ ٱلشَّمْسِ وَجَدَهَا تَغْرُبُ فِى عَيْنٍ حَمِئَةٍ وَوَجَدَ عِندَهَا قَوْمًا قُلْنَا يَٰذَا ٱلْقَرْنَيْنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمْ حُسْنًا', 'a84761ce46c417f354f8d6c6971eb364f6218deffcc816238327d13d8fff05da', 'a84761ce46c417f354f8d6c6971eb364f6218deffcc816238327d13d8fff05da', NULL, 'حتي اذا بلغ مغرب الشمس وجدها تغرب في عين حمئه ووجد عندها قوما قلنا يذا القرنين اما ان تعذب واما ان تتخذ فيهم حسنا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2227, 'tanzil-uthmani-v1.1', 18, 87, 'قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابًا نُّكْرًا', '171e7dc8fb5cb6cba1c918b9085c7f07759ef568537afe82e2bd90c749212600', 'قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابًا نُّكْرًا', '171e7dc8fb5cb6cba1c918b9085c7f07759ef568537afe82e2bd90c749212600', '171e7dc8fb5cb6cba1c918b9085c7f07759ef568537afe82e2bd90c749212600', NULL, 'قال اما من ظلم فسوف نعذبه ثم يرد الي ربه فيعذبه عذابا نكرا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2228, 'tanzil-uthmani-v1.1', 18, 88, 'وَأَمَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَلَهُۥ جَزَآءً ٱلْحُسْنَىٰ وَسَنَقُولُ لَهُۥ مِنْ أَمْرِنَا يُسْرًا', '66d58411413ea82592fa97e584c8f323b4f8d39469239a36fc553c8c7bab7812', 'وَأَمَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَلَهُۥ جَزَآءً ٱلْحُسْنَىٰ وَسَنَقُولُ لَهُۥ مِنْ أَمْرِنَا يُسْرًا', '66d58411413ea82592fa97e584c8f323b4f8d39469239a36fc553c8c7bab7812', '66d58411413ea82592fa97e584c8f323b4f8d39469239a36fc553c8c7bab7812', NULL, 'واما من ءامن وعمل صلحا فله جزاء الحسني وسنقول له من امرنا يسرا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2229, 'tanzil-uthmani-v1.1', 18, 89, 'ثُمَّ أَتْبَعَ سَبَبًا', '4c0391e552d63a96acb5888a96f55178ffb5d847aa112a6471920eeefc633617', 'ثُمَّ أَتْبَعَ سَبَبًا', '4c0391e552d63a96acb5888a96f55178ffb5d847aa112a6471920eeefc633617', '4c0391e552d63a96acb5888a96f55178ffb5d847aa112a6471920eeefc633617', NULL, 'ثم اتبع سببا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2230, 'tanzil-uthmani-v1.1', 18, 90, 'حَتَّىٰٓ إِذَا بَلَغَ مَطْلِعَ ٱلشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَىٰ قَوْمٍ لَّمْ نَجْعَل لَّهُم مِّن دُونِهَا سِتْرًا', 'de6e9db67cb19951adf3e2824304c511d222dd7bba2f929ffd57053cb591f41f', 'حَتَّىٰٓ إِذَا بَلَغَ مَطْلِعَ ٱلشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَىٰ قَوْمٍ لَّمْ نَجْعَل لَّهُم مِّن دُونِهَا سِتْرًا', 'de6e9db67cb19951adf3e2824304c511d222dd7bba2f929ffd57053cb591f41f', 'de6e9db67cb19951adf3e2824304c511d222dd7bba2f929ffd57053cb591f41f', NULL, 'حتي اذا بلغ مطلع الشمس وجدها تطلع علي قوم لم نجعل لهم من دونها سترا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2231, 'tanzil-uthmani-v1.1', 18, 91, 'كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا', 'a25327ad2944a69a194dacee0a6cad1b1dbe5a8fd99a4fbb03431a6f7731acb3', 'كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا', 'a25327ad2944a69a194dacee0a6cad1b1dbe5a8fd99a4fbb03431a6f7731acb3', 'a25327ad2944a69a194dacee0a6cad1b1dbe5a8fd99a4fbb03431a6f7731acb3', NULL, 'كذلك وقد احطنا بما لديه خبرا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2232, 'tanzil-uthmani-v1.1', 18, 92, 'ثُمَّ أَتْبَعَ سَبَبًا', '4c0391e552d63a96acb5888a96f55178ffb5d847aa112a6471920eeefc633617', 'ثُمَّ أَتْبَعَ سَبَبًا', '4c0391e552d63a96acb5888a96f55178ffb5d847aa112a6471920eeefc633617', '4c0391e552d63a96acb5888a96f55178ffb5d847aa112a6471920eeefc633617', NULL, 'ثم اتبع سببا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2233, 'tanzil-uthmani-v1.1', 18, 93, 'حَتَّىٰٓ إِذَا بَلَغَ بَيْنَ ٱلسَّدَّيْنِ وَجَدَ مِن دُونِهِمَا قَوْمًا لَّا يَكَادُونَ يَفْقَهُونَ قَوْلًا', 'c7802f53ce2b01ef77d9ba4ba816b0452811e37eabb6866e651cdf3f407270e7', 'حَتَّىٰٓ إِذَا بَلَغَ بَيْنَ ٱلسَّدَّيْنِ وَجَدَ مِن دُونِهِمَا قَوْمًا لَّا يَكَادُونَ يَفْقَهُونَ قَوْلًا', 'c7802f53ce2b01ef77d9ba4ba816b0452811e37eabb6866e651cdf3f407270e7', 'c7802f53ce2b01ef77d9ba4ba816b0452811e37eabb6866e651cdf3f407270e7', NULL, 'حتي اذا بلغ بين السدين وجد من دونهما قوما لا يكادون يفقهون قولا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2234, 'tanzil-uthmani-v1.1', 18, 94, 'قَالُوا۟ يَٰذَا ٱلْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِى ٱلْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَىٰٓ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّا', 'd36e16420ff774f749bd1b85690a383288cff90eb393c310bcb87b20fe75b065', 'قَالُوا۟ يَٰذَا ٱلْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِى ٱلْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَىٰٓ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّا', 'd36e16420ff774f749bd1b85690a383288cff90eb393c310bcb87b20fe75b065', 'd36e16420ff774f749bd1b85690a383288cff90eb393c310bcb87b20fe75b065', NULL, 'قالوا يذا القرنين ان ياجوج وماجوج مفسدون في الارض فهل نجعل لك خرجا علي ان تجعل بيننا وبينهم سدا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2235, 'tanzil-uthmani-v1.1', 18, 95, 'قَالَ مَا مَكَّنِّى فِيهِ رَبِّى خَيْرٌ فَأَعِينُونِى بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا', 'a6ab3106b02cb27840cfe63872af84c5493924330ce477d7aff3d921eeb8a080', 'قَالَ مَا مَكَّنِّى فِيهِ رَبِّى خَيْرٌ فَأَعِينُونِى بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا', 'a6ab3106b02cb27840cfe63872af84c5493924330ce477d7aff3d921eeb8a080', 'a6ab3106b02cb27840cfe63872af84c5493924330ce477d7aff3d921eeb8a080', NULL, 'قال ما مكني فيه ربي خير فاعينوني بقوه اجعل بينكم وبينهم ردما', 16, 31, 121, 1, 4, 303, false, NULL),
    (2236, 'tanzil-uthmani-v1.1', 18, 96, 'ءَاتُونِى زُبَرَ ٱلْحَدِيدِ حَتَّىٰٓ إِذَا سَاوَىٰ بَيْنَ ٱلصَّدَفَيْنِ قَالَ ٱنفُخُوا۟ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارًا قَالَ ءَاتُونِىٓ أُفْرِغْ عَلَيْهِ قِطْرًا', 'a1d072046c845ad21ac7286c2bbb8cba425b2af6d58cf1f989105dbb1361f48d', 'ءَاتُونِى زُبَرَ ٱلْحَدِيدِ حَتَّىٰٓ إِذَا سَاوَىٰ بَيْنَ ٱلصَّدَفَيْنِ قَالَ ٱنفُخُوا۟ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارًا قَالَ ءَاتُونِىٓ أُفْرِغْ عَلَيْهِ قِطْرًا', 'a1d072046c845ad21ac7286c2bbb8cba425b2af6d58cf1f989105dbb1361f48d', 'a1d072046c845ad21ac7286c2bbb8cba425b2af6d58cf1f989105dbb1361f48d', NULL, 'ءاتوني زبر الحديد حتي اذا ساوي بين الصدفين قال انفخوا حتي اذا جعله نارا قال ءاتوني افرغ عليه قطرا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2237, 'tanzil-uthmani-v1.1', 18, 97, 'فَمَا ٱسْطَٰعُوٓا۟ أَن يَظْهَرُوهُ وَمَا ٱسْتَطَٰعُوا۟ لَهُۥ نَقْبًا', '61e1fc4129dac716e57f186dcfafe734a0997b393b901149dfc14ba64a95616d', 'فَمَا ٱسْطَٰعُوٓا۟ أَن يَظْهَرُوهُ وَمَا ٱسْتَطَٰعُوا۟ لَهُۥ نَقْبًا', '61e1fc4129dac716e57f186dcfafe734a0997b393b901149dfc14ba64a95616d', '61e1fc4129dac716e57f186dcfafe734a0997b393b901149dfc14ba64a95616d', NULL, 'فما اسطعوا ان يظهروه وما استطعوا له نقبا', 16, 31, 121, 1, 4, 303, false, NULL),
    (2238, 'tanzil-uthmani-v1.1', 18, 98, 'قَالَ هَٰذَا رَحْمَةٌ مِّن رَّبِّى فَإِذَا جَآءَ وَعْدُ رَبِّى جَعَلَهُۥ دَكَّآءَ وَكَانَ وَعْدُ رَبِّى حَقًّا', '49d4a6fdf41a3816fe7abacb175b308bb091f55d932ce744fb9c603625a0a4c7', 'قَالَ هَٰذَا رَحْمَةٌ مِّن رَّبِّى فَإِذَا جَآءَ وَعْدُ رَبِّى جَعَلَهُۥ دَكَّآءَ وَكَانَ وَعْدُ رَبِّى حَقًّا', '49d4a6fdf41a3816fe7abacb175b308bb091f55d932ce744fb9c603625a0a4c7', '49d4a6fdf41a3816fe7abacb175b308bb091f55d932ce744fb9c603625a0a4c7', NULL, 'قال هذا رحمه من ربي فاذا جاء وعد ربي جعله دكاء وكان وعد ربي حقا', 16, 31, 121, 1, 4, 304, false, NULL),
    (2239, 'tanzil-uthmani-v1.1', 18, 99, 'وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍ يَمُوجُ فِى بَعْضٍ وَنُفِخَ فِى ٱلصُّورِ فَجَمَعْنَٰهُمْ جَمْعًا', '2291063962a53ba92a609fdf5543613217928bc655974bb40705c7823669bdc2', 'وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍ يَمُوجُ فِى بَعْضٍ وَنُفِخَ فِى ٱلصُّورِ فَجَمَعْنَٰهُمْ جَمْعًا', '2291063962a53ba92a609fdf5543613217928bc655974bb40705c7823669bdc2', '2291063962a53ba92a609fdf5543613217928bc655974bb40705c7823669bdc2', NULL, 'وتركنا بعضهم يومئذ يموج في بعض ونفخ في الصور فجمعنهم جمعا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2240, 'tanzil-uthmani-v1.1', 18, 100, 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِّلْكَٰفِرِينَ عَرْضًا', '33e263ed4c9752a499d2fa53db67ee2c1d3140a246f924e0274f227c9758bea2', 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِّلْكَٰفِرِينَ عَرْضًا', '33e263ed4c9752a499d2fa53db67ee2c1d3140a246f924e0274f227c9758bea2', '33e263ed4c9752a499d2fa53db67ee2c1d3140a246f924e0274f227c9758bea2', NULL, 'وعرضنا جهنم يومئذ للكفرين عرضا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2241, 'tanzil-uthmani-v1.1', 18, 101, 'ٱلَّذِينَ كَانَتْ أَعْيُنُهُمْ فِى غِطَآءٍ عَن ذِكْرِى وَكَانُوا۟ لَا يَسْتَطِيعُونَ سَمْعًا', '7f987f64238bd96abd372b92b66d257f33d31a8894430cfcb860fe1f7fb79463', 'ٱلَّذِينَ كَانَتْ أَعْيُنُهُمْ فِى غِطَآءٍ عَن ذِكْرِى وَكَانُوا۟ لَا يَسْتَطِيعُونَ سَمْعًا', '7f987f64238bd96abd372b92b66d257f33d31a8894430cfcb860fe1f7fb79463', '7f987f64238bd96abd372b92b66d257f33d31a8894430cfcb860fe1f7fb79463', NULL, 'الذين كانت اعينهم في غطاء عن ذكري وكانوا لا يستطيعون سمعا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2242, 'tanzil-uthmani-v1.1', 18, 102, 'أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓا۟ أَن يَتَّخِذُوا۟ عِبَادِى مِن دُونِىٓ أَوْلِيَآءَ إِنَّآ أَعْتَدْنَا جَهَنَّمَ لِلْكَٰفِرِينَ نُزُلًا', 'c226c4ca16d24305031e806213468b513f9ed87060fc8b291052d55b42cbe0b3', 'أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓا۟ أَن يَتَّخِذُوا۟ عِبَادِى مِن دُونِىٓ أَوْلِيَآءَ إِنَّآ أَعْتَدْنَا جَهَنَّمَ لِلْكَٰفِرِينَ نُزُلًا', 'c226c4ca16d24305031e806213468b513f9ed87060fc8b291052d55b42cbe0b3', 'c226c4ca16d24305031e806213468b513f9ed87060fc8b291052d55b42cbe0b3', NULL, 'افحسب الذين كفروا ان يتخذوا عبادي من دوني اولياء انا اعتدنا جهنم للكفرين نزلا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2243, 'tanzil-uthmani-v1.1', 18, 103, 'قُلْ هَلْ نُنَبِّئُكُم بِٱلْأَخْسَرِينَ أَعْمَٰلًا', '461115a4d4b2c151f5ca131cb47386cbe790d7a47627be616b94eda9d7604665', 'قُلْ هَلْ نُنَبِّئُكُم بِٱلْأَخْسَرِينَ أَعْمَٰلًا', '461115a4d4b2c151f5ca131cb47386cbe790d7a47627be616b94eda9d7604665', '461115a4d4b2c151f5ca131cb47386cbe790d7a47627be616b94eda9d7604665', NULL, 'قل هل ننبئكم بالاخسرين اعملا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2244, 'tanzil-uthmani-v1.1', 18, 104, 'ٱلَّذِينَ ضَلَّ سَعْيُهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا', '012cd1c5c2467a86318a2289754e6df85f3f94c3ddd61ecf23f5d7c32051ce8b', 'ٱلَّذِينَ ضَلَّ سَعْيُهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا', '012cd1c5c2467a86318a2289754e6df85f3f94c3ddd61ecf23f5d7c32051ce8b', '012cd1c5c2467a86318a2289754e6df85f3f94c3ddd61ecf23f5d7c32051ce8b', NULL, 'الذين ضل سعيهم في الحيوه الدنيا وهم يحسبون انهم يحسنون صنعا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2245, 'tanzil-uthmani-v1.1', 18, 105, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَلِقَآئِهِۦ فَحَبِطَتْ أَعْمَٰلُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَزْنًا', 'e97f60c353e93457071fe9b4705c351177f912adf3df05b0dad1447d32eb8cb9', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَلِقَآئِهِۦ فَحَبِطَتْ أَعْمَٰلُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَزْنًا', 'e97f60c353e93457071fe9b4705c351177f912adf3df05b0dad1447d32eb8cb9', 'e97f60c353e93457071fe9b4705c351177f912adf3df05b0dad1447d32eb8cb9', NULL, 'اولئك الذين كفروا بايت ربهم ولقائه فحبطت اعملهم فلا نقيم لهم يوم القيمه وزنا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2246, 'tanzil-uthmani-v1.1', 18, 106, 'ذَٰلِكَ جَزَآؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوا۟ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَرُسُلِى هُزُوًا', '6aa07b6fe36f14aea510fc0c5823d6db9288b83aab3f8c22295e87d2d95e9d63', 'ذَٰلِكَ جَزَآؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوا۟ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَرُسُلِى هُزُوًا', '6aa07b6fe36f14aea510fc0c5823d6db9288b83aab3f8c22295e87d2d95e9d63', '6aa07b6fe36f14aea510fc0c5823d6db9288b83aab3f8c22295e87d2d95e9d63', NULL, 'ذلك جزاؤهم جهنم بما كفروا واتخذوا ءايتي ورسلي هزوا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2247, 'tanzil-uthmani-v1.1', 18, 107, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَانَتْ لَهُمْ جَنَّٰتُ ٱلْفِرْدَوْسِ نُزُلًا', 'b958da840cd3c6486a1a1af468c4f2609d5684268ec92fa664bdc80a1507b74b', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَانَتْ لَهُمْ جَنَّٰتُ ٱلْفِرْدَوْسِ نُزُلًا', 'b958da840cd3c6486a1a1af468c4f2609d5684268ec92fa664bdc80a1507b74b', 'b958da840cd3c6486a1a1af468c4f2609d5684268ec92fa664bdc80a1507b74b', NULL, 'ان الذين ءامنوا وعملوا الصلحت كانت لهم جنت الفردوس نزلا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2248, 'tanzil-uthmani-v1.1', 18, 108, 'خَٰلِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًا', '297ab4e9bbb3e3ba0a3e9149b1083fae1255f76893b95391268bee793c3f1c10', 'خَٰلِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًا', '297ab4e9bbb3e3ba0a3e9149b1083fae1255f76893b95391268bee793c3f1c10', '297ab4e9bbb3e3ba0a3e9149b1083fae1255f76893b95391268bee793c3f1c10', NULL, 'خلدين فيها لا يبغون عنها حولا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2249, 'tanzil-uthmani-v1.1', 18, 109, 'قُل لَّوْ كَانَ ٱلْبَحْرُ مِدَادًا لِّكَلِمَٰتِ رَبِّى لَنَفِدَ ٱلْبَحْرُ قَبْلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّى وَلَوْ جِئْنَا بِمِثْلِهِۦ مَدَدًا', 'cdf71fba63af48e580cdd1094fb4baf2161770e49899b05e1a0ac7d3e3b1ca16', 'قُل لَّوْ كَانَ ٱلْبَحْرُ مِدَادًا لِّكَلِمَٰتِ رَبِّى لَنَفِدَ ٱلْبَحْرُ قَبْلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّى وَلَوْ جِئْنَا بِمِثْلِهِۦ مَدَدًا', 'cdf71fba63af48e580cdd1094fb4baf2161770e49899b05e1a0ac7d3e3b1ca16', 'cdf71fba63af48e580cdd1094fb4baf2161770e49899b05e1a0ac7d3e3b1ca16', NULL, 'قل لو كان البحر مدادا لكلمت ربي لنفد البحر قبل ان تنفد كلمت ربي ولو جئنا بمثله مددا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2250, 'tanzil-uthmani-v1.1', 18, 110, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَمَن كَانَ يَرْجُوا۟ لِقَآءَ رَبِّهِۦ فَلْيَعْمَلْ عَمَلًا صَٰلِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِۦٓ أَحَدًۢا', '8c0a9ed86666c98b7ea0d06c435d166a1c1196464e7735c54eaaf8d4039a130c', 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَمَن كَانَ يَرْجُوا۟ لِقَآءَ رَبِّهِۦ فَلْيَعْمَلْ عَمَلًا صَٰلِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِۦٓ أَحَدًۢا', '8c0a9ed86666c98b7ea0d06c435d166a1c1196464e7735c54eaaf8d4039a130c', '8c0a9ed86666c98b7ea0d06c435d166a1c1196464e7735c54eaaf8d4039a130c', NULL, 'قل انما انا بشر مثلكم يوحي الي انما الهكم اله وحد فمن كان يرجوا لقاء ربه فليعمل عملا صلحا ولا يشرك بعباده ربه احدا', 16, 31, 122, 1, 4, 304, false, NULL),
    (2251, 'tanzil-uthmani-v1.1', 19, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ كٓهيعٓصٓ', 'fdc4f7e8ec0c50783bb850b33441d86cdfa056caae5469f7a0ce89cf457d8621', 'كٓهيعٓصٓ', '5d8f31d500cef98dbbbe4a812905775233be04ab330d80629bd60f1ae4765b26', '5d8f31d500cef98dbbbe4a812905775233be04ab330d80629bd60f1ae4765b26', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'كهيعص', 16, 31, 122, 1, 4, 305, false, NULL),
    (2252, 'tanzil-uthmani-v1.1', 19, 2, 'ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآ', '89040c680d9028cad414b007321d1034371fc2d3cdce9112c6598fe2880e09e1', 'ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآ', '89040c680d9028cad414b007321d1034371fc2d3cdce9112c6598fe2880e09e1', '89040c680d9028cad414b007321d1034371fc2d3cdce9112c6598fe2880e09e1', NULL, 'ذكر رحمت ربك عبده زكريا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2253, 'tanzil-uthmani-v1.1', 19, 3, 'إِذْ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيًّا', 'ea15b971311e071df600166c8be6421b89c7185fe64fa0bcd313bcd212f4ef74', 'إِذْ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيًّا', 'ea15b971311e071df600166c8be6421b89c7185fe64fa0bcd313bcd212f4ef74', 'ea15b971311e071df600166c8be6421b89c7185fe64fa0bcd313bcd212f4ef74', NULL, 'اذ نادي ربه نداء خفيا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2254, 'tanzil-uthmani-v1.1', 19, 4, 'قَالَ رَبِّ إِنِّى وَهَنَ ٱلْعَظْمُ مِنِّى وَٱشْتَعَلَ ٱلرَّأْسُ شَيْبًا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّا', '374876a864def5e2c08746c7f0cb1a03dc8b343d00deb2e14cbfac62731aa038', 'قَالَ رَبِّ إِنِّى وَهَنَ ٱلْعَظْمُ مِنِّى وَٱشْتَعَلَ ٱلرَّأْسُ شَيْبًا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّا', '374876a864def5e2c08746c7f0cb1a03dc8b343d00deb2e14cbfac62731aa038', '374876a864def5e2c08746c7f0cb1a03dc8b343d00deb2e14cbfac62731aa038', NULL, 'قال رب اني وهن العظم مني واشتعل الراس شيبا ولم اكن بدعائك رب شقيا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2255, 'tanzil-uthmani-v1.1', 19, 5, 'وَإِنِّى خِفْتُ ٱلْمَوَٰلِىَ مِن وَرَآءِى وَكَانَتِ ٱمْرَأَتِى عَاقِرًا فَهَبْ لِى مِن لَّدُنكَ وَلِيًّا', '6fe266ecf7aef47d9970bc4ef1c74f72f9d384368d83b55dabda97c896148e30', 'وَإِنِّى خِفْتُ ٱلْمَوَٰلِىَ مِن وَرَآءِى وَكَانَتِ ٱمْرَأَتِى عَاقِرًا فَهَبْ لِى مِن لَّدُنكَ وَلِيًّا', '6fe266ecf7aef47d9970bc4ef1c74f72f9d384368d83b55dabda97c896148e30', '6fe266ecf7aef47d9970bc4ef1c74f72f9d384368d83b55dabda97c896148e30', NULL, 'واني خفت المولي من وراءي وكانت امراتي عاقرا فهب لي من لدنك وليا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2256, 'tanzil-uthmani-v1.1', 19, 6, 'يَرِثُنِى وَيَرِثُ مِنْ ءَالِ يَعْقُوبَ وَٱجْعَلْهُ رَبِّ رَضِيًّا', '1e27bddc600367c99adbb06f9b7607938b4e5becb8c4e3c3f370504b02bc72d5', 'يَرِثُنِى وَيَرِثُ مِنْ ءَالِ يَعْقُوبَ وَٱجْعَلْهُ رَبِّ رَضِيًّا', '1e27bddc600367c99adbb06f9b7607938b4e5becb8c4e3c3f370504b02bc72d5', '1e27bddc600367c99adbb06f9b7607938b4e5becb8c4e3c3f370504b02bc72d5', NULL, 'يرثني ويرث من ءال يعقوب واجعله رب رضيا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2257, 'tanzil-uthmani-v1.1', 19, 7, 'يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسْمُهُۥ يَحْيَىٰ لَمْ نَجْعَل لَّهُۥ مِن قَبْلُ سَمِيًّا', '679879236b58d695828c0500af7641212c8e53e8892dde1674cf6cbf29ffb6c4', 'يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسْمُهُۥ يَحْيَىٰ لَمْ نَجْعَل لَّهُۥ مِن قَبْلُ سَمِيًّا', '679879236b58d695828c0500af7641212c8e53e8892dde1674cf6cbf29ffb6c4', '679879236b58d695828c0500af7641212c8e53e8892dde1674cf6cbf29ffb6c4', NULL, 'يزكريا انا نبشرك بغلم اسمه يحيي لم نجعل له من قبل سميا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2258, 'tanzil-uthmani-v1.1', 19, 8, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَكَانَتِ ٱمْرَأَتِى عَاقِرًا وَقَدْ بَلَغْتُ مِنَ ٱلْكِبَرِ عِتِيًّا', '8a242ef95bf43b8a71db55e8b91bd97e254854b95ff366092f1388b505825ab6', 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَكَانَتِ ٱمْرَأَتِى عَاقِرًا وَقَدْ بَلَغْتُ مِنَ ٱلْكِبَرِ عِتِيًّا', '8a242ef95bf43b8a71db55e8b91bd97e254854b95ff366092f1388b505825ab6', '8a242ef95bf43b8a71db55e8b91bd97e254854b95ff366092f1388b505825ab6', NULL, 'قال رب اني يكون لي غلم وكانت امراتي عاقرا وقد بلغت من الكبر عتيا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2259, 'tanzil-uthmani-v1.1', 19, 9, 'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّنٌ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْـًٔا', '5b7e7d8468278bd109597e3189ec4a7f33d7706dd88b95e864afe56eaf84c73f', 'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّنٌ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْـًٔا', '5b7e7d8468278bd109597e3189ec4a7f33d7706dd88b95e864afe56eaf84c73f', '5b7e7d8468278bd109597e3189ec4a7f33d7706dd88b95e864afe56eaf84c73f', NULL, 'قال كذلك قال ربك هو علي هين وقد خلقتك من قبل ولم تك شيا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2260, 'tanzil-uthmani-v1.1', 19, 10, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٍ سَوِيًّا', 'bc113aa018140d90e9c7fb7fdd6c733eeefa96c98f207a05f7f71a809649f6a5', 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةً قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٍ سَوِيًّا', 'bc113aa018140d90e9c7fb7fdd6c733eeefa96c98f207a05f7f71a809649f6a5', 'bc113aa018140d90e9c7fb7fdd6c733eeefa96c98f207a05f7f71a809649f6a5', NULL, 'قال رب اجعل لي ءايه قال ءايتك الا تكلم الناس ثلث ليال سويا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2261, 'tanzil-uthmani-v1.1', 19, 11, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ٱلْمِحْرَابِ فَأَوْحَىٰٓ إِلَيْهِمْ أَن سَبِّحُوا۟ بُكْرَةً وَعَشِيًّا', '611ea285aa621554d5ca7ace32eb364d57e76da49b5ec891646a3c0eb4ecd36f', 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ٱلْمِحْرَابِ فَأَوْحَىٰٓ إِلَيْهِمْ أَن سَبِّحُوا۟ بُكْرَةً وَعَشِيًّا', '611ea285aa621554d5ca7ace32eb364d57e76da49b5ec891646a3c0eb4ecd36f', '611ea285aa621554d5ca7ace32eb364d57e76da49b5ec891646a3c0eb4ecd36f', NULL, 'فخرج علي قومه من المحراب فاوحي اليهم ان سبحوا بكره وعشيا', 16, 31, 122, 1, 4, 305, false, NULL),
    (2262, 'tanzil-uthmani-v1.1', 19, 12, 'يَٰيَحْيَىٰ خُذِ ٱلْكِتَٰبَ بِقُوَّةٍ وَءَاتَيْنَٰهُ ٱلْحُكْمَ صَبِيًّا', '2b43b789ee1836d9516f089c7259970fc84ba95d300d4838506060c34e4201c3', 'يَٰيَحْيَىٰ خُذِ ٱلْكِتَٰبَ بِقُوَّةٍ وَءَاتَيْنَٰهُ ٱلْحُكْمَ صَبِيًّا', '2b43b789ee1836d9516f089c7259970fc84ba95d300d4838506060c34e4201c3', '2b43b789ee1836d9516f089c7259970fc84ba95d300d4838506060c34e4201c3', NULL, 'ييحيي خذ الكتب بقوه وءاتينه الحكم صبيا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2263, 'tanzil-uthmani-v1.1', 19, 13, 'وَحَنَانًا مِّن لَّدُنَّا وَزَكَوٰةً وَكَانَ تَقِيًّا', '4ddafce4d9e93e877013d3500ca4a081098fc3f5181b06695090be1a2638c07b', 'وَحَنَانًا مِّن لَّدُنَّا وَزَكَوٰةً وَكَانَ تَقِيًّا', '4ddafce4d9e93e877013d3500ca4a081098fc3f5181b06695090be1a2638c07b', '4ddafce4d9e93e877013d3500ca4a081098fc3f5181b06695090be1a2638c07b', NULL, 'وحنانا من لدنا وزكوه وكان تقيا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2264, 'tanzil-uthmani-v1.1', 19, 14, 'وَبَرًّۢا بِوَٰلِدَيْهِ وَلَمْ يَكُن جَبَّارًا عَصِيًّا', '1edf7d69a28544041bbc5de83ad82ada31910dc6f0a340a42d9589c13e8c0ecd', 'وَبَرًّۢا بِوَٰلِدَيْهِ وَلَمْ يَكُن جَبَّارًا عَصِيًّا', '1edf7d69a28544041bbc5de83ad82ada31910dc6f0a340a42d9589c13e8c0ecd', '1edf7d69a28544041bbc5de83ad82ada31910dc6f0a340a42d9589c13e8c0ecd', NULL, 'وبرا بولديه ولم يكن جبارا عصيا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2265, 'tanzil-uthmani-v1.1', 19, 15, 'وَسَلَٰمٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا', '37185dd8bc562860400fa8519069691c48dfc9c9b419c0c0d8dd257dcdad4c2d', 'وَسَلَٰمٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا', '37185dd8bc562860400fa8519069691c48dfc9c9b419c0c0d8dd257dcdad4c2d', '37185dd8bc562860400fa8519069691c48dfc9c9b419c0c0d8dd257dcdad4c2d', NULL, 'وسلم عليه يوم ولد ويوم يموت ويوم يبعث حيا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2266, 'tanzil-uthmani-v1.1', 19, 16, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مَرْيَمَ إِذِ ٱنتَبَذَتْ مِنْ أَهْلِهَا مَكَانًا شَرْقِيًّا', '17251882b603265225635adf6292c48aeed44da5e27c5d03c32624b6a0c3d0db', 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مَرْيَمَ إِذِ ٱنتَبَذَتْ مِنْ أَهْلِهَا مَكَانًا شَرْقِيًّا', '17251882b603265225635adf6292c48aeed44da5e27c5d03c32624b6a0c3d0db', '17251882b603265225635adf6292c48aeed44da5e27c5d03c32624b6a0c3d0db', NULL, 'واذكر في الكتب مريم اذ انتبذت من اهلها مكانا شرقيا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2267, 'tanzil-uthmani-v1.1', 19, 17, 'فَٱتَّخَذَتْ مِن دُونِهِمْ حِجَابًا فَأَرْسَلْنَآ إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا', 'f26f0c299a62b7a5e244f04d211327c66a6eea6e82abf530a7875b56a5b8ece5', 'فَٱتَّخَذَتْ مِن دُونِهِمْ حِجَابًا فَأَرْسَلْنَآ إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا', 'f26f0c299a62b7a5e244f04d211327c66a6eea6e82abf530a7875b56a5b8ece5', 'f26f0c299a62b7a5e244f04d211327c66a6eea6e82abf530a7875b56a5b8ece5', NULL, 'فاتخذت من دونهم حجابا فارسلنا اليها روحنا فتمثل لها بشرا سويا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2268, 'tanzil-uthmani-v1.1', 19, 18, 'قَالَتْ إِنِّىٓ أَعُوذُ بِٱلرَّحْمَٰنِ مِنكَ إِن كُنتَ تَقِيًّا', '124564362d130c77b0bc1848b3d8776e354167118e38b31c09d9bf51d41cecc1', 'قَالَتْ إِنِّىٓ أَعُوذُ بِٱلرَّحْمَٰنِ مِنكَ إِن كُنتَ تَقِيًّا', '124564362d130c77b0bc1848b3d8776e354167118e38b31c09d9bf51d41cecc1', '124564362d130c77b0bc1848b3d8776e354167118e38b31c09d9bf51d41cecc1', NULL, 'قالت اني اعوذ بالرحمن منك ان كنت تقيا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2269, 'tanzil-uthmani-v1.1', 19, 19, 'قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمًا زَكِيًّا', '8fbd53e0c7c839750f610567323d58ec69177a4d2cad6aa056b5a79edae68a73', 'قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمًا زَكِيًّا', '8fbd53e0c7c839750f610567323d58ec69177a4d2cad6aa056b5a79edae68a73', '8fbd53e0c7c839750f610567323d58ec69177a4d2cad6aa056b5a79edae68a73', NULL, 'قال انما انا رسول ربك لاهب لك غلما زكيا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2270, 'tanzil-uthmani-v1.1', 19, 20, 'قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَلَمْ يَمْسَسْنِى بَشَرٌ وَلَمْ أَكُ بَغِيًّا', '8a97628fc481e6a1784ec632a03794e6b3c2ded9e7eb3a5423ad0f9f65f2909f', 'قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَٰمٌ وَلَمْ يَمْسَسْنِى بَشَرٌ وَلَمْ أَكُ بَغِيًّا', '8a97628fc481e6a1784ec632a03794e6b3c2ded9e7eb3a5423ad0f9f65f2909f', '8a97628fc481e6a1784ec632a03794e6b3c2ded9e7eb3a5423ad0f9f65f2909f', NULL, 'قالت اني يكون لي غلم ولم يمسسني بشر ولم اك بغيا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2271, 'tanzil-uthmani-v1.1', 19, 21, 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌ وَلِنَجْعَلَهُۥٓ ءَايَةً لِّلنَّاسِ وَرَحْمَةً مِّنَّا وَكَانَ أَمْرًا مَّقْضِيًّا', '61e0e592b57e03b636ff9a7980b594c8df88b0d0b874da921f4342a22ff0d26e', 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌ وَلِنَجْعَلَهُۥٓ ءَايَةً لِّلنَّاسِ وَرَحْمَةً مِّنَّا وَكَانَ أَمْرًا مَّقْضِيًّا', '61e0e592b57e03b636ff9a7980b594c8df88b0d0b874da921f4342a22ff0d26e', '61e0e592b57e03b636ff9a7980b594c8df88b0d0b874da921f4342a22ff0d26e', NULL, 'قال كذلك قال ربك هو علي هين ولنجعله ءايه للناس ورحمه منا وكان امرا مقضيا', 16, 31, 122, 1, 4, 306, false, NULL),
    (2272, 'tanzil-uthmani-v1.1', 19, 22, 'فَحَمَلَتْهُ فَٱنتَبَذَتْ بِهِۦ مَكَانًا قَصِيًّا', 'cd22fe011cb5def74c003d5d6a33193ad6699084c15726507d771cd7d9141fee', 'فَحَمَلَتْهُ فَٱنتَبَذَتْ بِهِۦ مَكَانًا قَصِيًّا', 'cd22fe011cb5def74c003d5d6a33193ad6699084c15726507d771cd7d9141fee', 'cd22fe011cb5def74c003d5d6a33193ad6699084c15726507d771cd7d9141fee', NULL, 'فحملته فانتبذت به مكانا قصيا', 16, 31, 123, 1, 4, 306, false, NULL),
    (2273, 'tanzil-uthmani-v1.1', 19, 23, 'فَأَجَآءَهَا ٱلْمَخَاضُ إِلَىٰ جِذْعِ ٱلنَّخْلَةِ قَالَتْ يَٰلَيْتَنِى مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًا مَّنسِيًّا', '4c3f6f36fb66570a929acd1e09c52819581707dc175684dcb1a577581d177775', 'فَأَجَآءَهَا ٱلْمَخَاضُ إِلَىٰ جِذْعِ ٱلنَّخْلَةِ قَالَتْ يَٰلَيْتَنِى مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًا مَّنسِيًّا', '4c3f6f36fb66570a929acd1e09c52819581707dc175684dcb1a577581d177775', '4c3f6f36fb66570a929acd1e09c52819581707dc175684dcb1a577581d177775', NULL, 'فاجاءها المخاض الي جذع النخله قالت يليتني مت قبل هذا وكنت نسيا منسيا', 16, 31, 123, 1, 4, 306, false, NULL),
    (2274, 'tanzil-uthmani-v1.1', 19, 24, 'فَنَادَىٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِى قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا', '7ada252eb43a50b5b542003acdba241c6f4d6d6316145f402b1f7738e3b7b68c', 'فَنَادَىٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِى قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّا', '7ada252eb43a50b5b542003acdba241c6f4d6d6316145f402b1f7738e3b7b68c', '7ada252eb43a50b5b542003acdba241c6f4d6d6316145f402b1f7738e3b7b68c', NULL, 'فناديها من تحتها الا تحزني قد جعل ربك تحتك سريا', 16, 31, 123, 1, 4, 306, false, NULL),
    (2275, 'tanzil-uthmani-v1.1', 19, 25, 'وَهُزِّىٓ إِلَيْكِ بِجِذْعِ ٱلنَّخْلَةِ تُسَٰقِطْ عَلَيْكِ رُطَبًا جَنِيًّا', 'ff0fb17d61aad58169b9a09473cae83bf1a8427048235435063ca62d46aa6143', 'وَهُزِّىٓ إِلَيْكِ بِجِذْعِ ٱلنَّخْلَةِ تُسَٰقِطْ عَلَيْكِ رُطَبًا جَنِيًّا', 'ff0fb17d61aad58169b9a09473cae83bf1a8427048235435063ca62d46aa6143', 'ff0fb17d61aad58169b9a09473cae83bf1a8427048235435063ca62d46aa6143', NULL, 'وهزي اليك بجذع النخله تسقط عليك رطبا جنيا', 16, 31, 123, 1, 4, 306, false, NULL),
    (2276, 'tanzil-uthmani-v1.1', 19, 26, 'فَكُلِى وَٱشْرَبِى وَقَرِّى عَيْنًا فَإِمَّا تَرَيِنَّ مِنَ ٱلْبَشَرِ أَحَدًا فَقُولِىٓ إِنِّى نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّا', 'aa9825618885c8fc55fc07de7a250ae3c02d50c04226cdf41e1e75d574fd37ca', 'فَكُلِى وَٱشْرَبِى وَقَرِّى عَيْنًا فَإِمَّا تَرَيِنَّ مِنَ ٱلْبَشَرِ أَحَدًا فَقُولِىٓ إِنِّى نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّا', 'aa9825618885c8fc55fc07de7a250ae3c02d50c04226cdf41e1e75d574fd37ca', 'aa9825618885c8fc55fc07de7a250ae3c02d50c04226cdf41e1e75d574fd37ca', NULL, 'فكلي واشربي وقري عينا فاما ترين من البشر احدا فقولي اني نذرت للرحمن صوما فلن اكلم اليوم انسيا', 16, 31, 123, 1, 4, 307, false, NULL),
    (2277, 'tanzil-uthmani-v1.1', 19, 27, 'فَأَتَتْ بِهِۦ قَوْمَهَا تَحْمِلُهُۥ قَالُوا۟ يَٰمَرْيَمُ لَقَدْ جِئْتِ شَيْـًٔا فَرِيًّا', 'fc0dd7a55061d1defe07586d168368fb5003744848b5a1c83dabe43fa4c400a6', 'فَأَتَتْ بِهِۦ قَوْمَهَا تَحْمِلُهُۥ قَالُوا۟ يَٰمَرْيَمُ لَقَدْ جِئْتِ شَيْـًٔا فَرِيًّا', 'fc0dd7a55061d1defe07586d168368fb5003744848b5a1c83dabe43fa4c400a6', 'fc0dd7a55061d1defe07586d168368fb5003744848b5a1c83dabe43fa4c400a6', NULL, 'فاتت به قومها تحمله قالوا يمريم لقد جئت شيا فريا', 16, 31, 123, 1, 4, 307, false, NULL),
    (2278, 'tanzil-uthmani-v1.1', 19, 28, 'يَٰٓأُخْتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيًّا', '142746fb50f91b24c4e6d6308562b93aac4c71b4e6a8b107fadb6282397e44b2', 'يَٰٓأُخْتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمْرَأَ سَوْءٍ وَمَا كَانَتْ أُمُّكِ بَغِيًّا', '142746fb50f91b24c4e6d6308562b93aac4c71b4e6a8b107fadb6282397e44b2', '142746fb50f91b24c4e6d6308562b93aac4c71b4e6a8b107fadb6282397e44b2', NULL, 'ياخت هرون ما كان ابوك امرا سوء وما كانت امك بغيا', 16, 31, 123, 1, 4, 307, false, NULL),
    (2279, 'tanzil-uthmani-v1.1', 19, 29, 'فَأَشَارَتْ إِلَيْهِ قَالُوا۟ كَيْفَ نُكَلِّمُ مَن كَانَ فِى ٱلْمَهْدِ صَبِيًّا', '3724e741bce5985cefe24d534c7779d10f2d1079b103fa125e5f24c3e1b00c1b', 'فَأَشَارَتْ إِلَيْهِ قَالُوا۟ كَيْفَ نُكَلِّمُ مَن كَانَ فِى ٱلْمَهْدِ صَبِيًّا', '3724e741bce5985cefe24d534c7779d10f2d1079b103fa125e5f24c3e1b00c1b', '3724e741bce5985cefe24d534c7779d10f2d1079b103fa125e5f24c3e1b00c1b', NULL, 'فاشارت اليه قالوا كيف نكلم من كان في المهد صبيا', 16, 31, 123, 1, 4, 307, false, NULL),
    (2280, 'tanzil-uthmani-v1.1', 19, 30, 'قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَٰبَ وَجَعَلَنِى نَبِيًّا', '3dd6ddab65945e03db94acb54ebea43c5b7a0de9297f668276348d437dfd3171', 'قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَٰبَ وَجَعَلَنِى نَبِيًّا', '3dd6ddab65945e03db94acb54ebea43c5b7a0de9297f668276348d437dfd3171', '3dd6ddab65945e03db94acb54ebea43c5b7a0de9297f668276348d437dfd3171', NULL, 'قال اني عبد الله ءاتيني الكتب وجعلني نبيا', 16, 31, 123, 1, 4, 307, false, NULL),
    (2281, 'tanzil-uthmani-v1.1', 19, 31, 'وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّا', '4a3b1e171f93232c23debf29371f46bf5c37524cd2360da7d7c93dee2c25f016', 'وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّا', '4a3b1e171f93232c23debf29371f46bf5c37524cd2360da7d7c93dee2c25f016', '4a3b1e171f93232c23debf29371f46bf5c37524cd2360da7d7c93dee2c25f016', NULL, 'وجعلني مباركا اين ما كنت واوصني بالصلوه والزكوه ما دمت حيا', 16, 31, 123, 1, 4, 307, false, NULL),
    (2282, 'tanzil-uthmani-v1.1', 19, 32, 'وَبَرًّۢا بِوَٰلِدَتِى وَلَمْ يَجْعَلْنِى جَبَّارًا شَقِيًّا', 'd53a288ffa5fb2f31f514ad4e765881cf086ee3a789d3d1cb37d1fb54748eebe', 'وَبَرًّۢا بِوَٰلِدَتِى وَلَمْ يَجْعَلْنِى جَبَّارًا شَقِيًّا', 'd53a288ffa5fb2f31f514ad4e765881cf086ee3a789d3d1cb37d1fb54748eebe', 'd53a288ffa5fb2f31f514ad4e765881cf086ee3a789d3d1cb37d1fb54748eebe', NULL, 'وبرا بولدتي ولم يجعلني جبارا شقيا', 16, 31, 123, 1, 4, 307, false, NULL),
    (2283, 'tanzil-uthmani-v1.1', 19, 33, 'وَٱلسَّلَٰمُ عَلَىَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا', 'f577da78b66742f639d453253c5c546bba25f4eec1fa64d264a6290303f93b70', 'وَٱلسَّلَٰمُ عَلَىَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا', 'f577da78b66742f639d453253c5c546bba25f4eec1fa64d264a6290303f93b70', 'f577da78b66742f639d453253c5c546bba25f4eec1fa64d264a6290303f93b70', NULL, 'والسلم علي يوم ولدت ويوم اموت ويوم ابعث حيا', 16, 31, 123, 1, 4, 307, false, NULL),
    (2284, 'tanzil-uthmani-v1.1', 19, 34, 'ذَٰلِكَ عِيسَى ٱبْنُ مَرْيَمَ قَوْلَ ٱلْحَقِّ ٱلَّذِى فِيهِ يَمْتَرُونَ', '08f7c9c870a737f00e64138a020d315c3598a0abc13747fe00a3c00acd76f704', 'ذَٰلِكَ عِيسَى ٱبْنُ مَرْيَمَ قَوْلَ ٱلْحَقِّ ٱلَّذِى فِيهِ يَمْتَرُونَ', '08f7c9c870a737f00e64138a020d315c3598a0abc13747fe00a3c00acd76f704', '08f7c9c870a737f00e64138a020d315c3598a0abc13747fe00a3c00acd76f704', NULL, 'ذلك عيسي ابن مريم قول الحق الذي فيه يمترون', 16, 31, 123, 1, 4, 307, false, NULL),
    (2285, 'tanzil-uthmani-v1.1', 19, 35, 'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٍ سُبْحَٰنَهُۥٓ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '4bd83728104d8b722c4749bef2edcfa323bbfacf52a0b2d17c73d4c510c60c37', 'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٍ سُبْحَٰنَهُۥٓ إِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '4bd83728104d8b722c4749bef2edcfa323bbfacf52a0b2d17c73d4c510c60c37', '4bd83728104d8b722c4749bef2edcfa323bbfacf52a0b2d17c73d4c510c60c37', NULL, 'ما كان لله ان يتخذ من ولد سبحنه اذا قضي امرا فانما يقول له كن فيكون', 16, 31, 123, 1, 4, 307, false, NULL),
    (2286, 'tanzil-uthmani-v1.1', 19, 36, 'وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '4a738c74b85c83616d5787f3c14581a57adaf065536bcd6ec3a77c0526184520', 'وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '4a738c74b85c83616d5787f3c14581a57adaf065536bcd6ec3a77c0526184520', '4a738c74b85c83616d5787f3c14581a57adaf065536bcd6ec3a77c0526184520', NULL, 'وان الله ربي وربكم فاعبدوه هذا صرط مستقيم', 16, 31, 123, 1, 4, 307, false, NULL),
    (2287, 'tanzil-uthmani-v1.1', 19, 37, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ', '808ffbb13a38360712dc3bcc085e795fd36a1a26aa47f876cc30990447bc9eda', 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ', '808ffbb13a38360712dc3bcc085e795fd36a1a26aa47f876cc30990447bc9eda', '808ffbb13a38360712dc3bcc085e795fd36a1a26aa47f876cc30990447bc9eda', NULL, 'فاختلف الاحزاب من بينهم فويل للذين كفروا من مشهد يوم عظيم', 16, 31, 123, 1, 4, 307, false, NULL),
    (2288, 'tanzil-uthmani-v1.1', 19, 38, 'أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا لَٰكِنِ ٱلظَّٰلِمُونَ ٱلْيَوْمَ فِى ضَلَٰلٍ مُّبِينٍ', '77dd5aaee8ed86df6092320890e2525d695021b6852caea149628ef7fa8d845a', 'أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا لَٰكِنِ ٱلظَّٰلِمُونَ ٱلْيَوْمَ فِى ضَلَٰلٍ مُّبِينٍ', '77dd5aaee8ed86df6092320890e2525d695021b6852caea149628ef7fa8d845a', '77dd5aaee8ed86df6092320890e2525d695021b6852caea149628ef7fa8d845a', NULL, 'اسمع بهم وابصر يوم ياتوننا لكن الظلمون اليوم في ضلل مبين', 16, 31, 123, 1, 4, 307, false, NULL),
    (2289, 'tanzil-uthmani-v1.1', 19, 39, 'وَأَنذِرْهُمْ يَوْمَ ٱلْحَسْرَةِ إِذْ قُضِىَ ٱلْأَمْرُ وَهُمْ فِى غَفْلَةٍ وَهُمْ لَا يُؤْمِنُونَ', '43694de6794baf7b2b2b9ee3d96353491d90ee82213f9babc8de61874a1f2f30', 'وَأَنذِرْهُمْ يَوْمَ ٱلْحَسْرَةِ إِذْ قُضِىَ ٱلْأَمْرُ وَهُمْ فِى غَفْلَةٍ وَهُمْ لَا يُؤْمِنُونَ', '43694de6794baf7b2b2b9ee3d96353491d90ee82213f9babc8de61874a1f2f30', '43694de6794baf7b2b2b9ee3d96353491d90ee82213f9babc8de61874a1f2f30', NULL, 'وانذرهم يوم الحسره اذ قضي الامر وهم في غفله وهم لا يؤمنون', 16, 31, 123, 1, 4, 308, false, NULL),
    (2290, 'tanzil-uthmani-v1.1', 19, 40, 'إِنَّا نَحْنُ نَرِثُ ٱلْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَعُونَ', 'b16e87432c2d5d1d3fbba551307f9ca75965f18559e011764dc25083f9171823', 'إِنَّا نَحْنُ نَرِثُ ٱلْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَعُونَ', 'b16e87432c2d5d1d3fbba551307f9ca75965f18559e011764dc25083f9171823', 'b16e87432c2d5d1d3fbba551307f9ca75965f18559e011764dc25083f9171823', NULL, 'انا نحن نرث الارض ومن عليها والينا يرجعون', 16, 31, 123, 1, 4, 308, false, NULL),
    (2291, 'tanzil-uthmani-v1.1', 19, 41, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِبْرَٰهِيمَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', '78e8d45a085bd93380fd6764d2ee55bbc27aa7c3ce34ffcb4dbe489f91bffca7', 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِبْرَٰهِيمَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', '78e8d45a085bd93380fd6764d2ee55bbc27aa7c3ce34ffcb4dbe489f91bffca7', '78e8d45a085bd93380fd6764d2ee55bbc27aa7c3ce34ffcb4dbe489f91bffca7', NULL, 'واذكر في الكتب ابرهيم انه كان صديقا نبيا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2292, 'tanzil-uthmani-v1.1', 19, 42, 'إِذْ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِى عَنكَ شَيْـًٔا', 'b6c1953c63ca6c8a70d7b842895ae73e7595c9baa6ddce0184b503fa3e4461c8', 'إِذْ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِى عَنكَ شَيْـًٔا', 'b6c1953c63ca6c8a70d7b842895ae73e7595c9baa6ddce0184b503fa3e4461c8', 'b6c1953c63ca6c8a70d7b842895ae73e7595c9baa6ddce0184b503fa3e4461c8', NULL, 'اذ قال لابيه يابت لم تعبد ما لا يسمع ولا يبصر ولا يغني عنك شيا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2293, 'tanzil-uthmani-v1.1', 19, 43, 'يَٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًا سَوِيًّا', 'fb3f46d06e9c23175c4317b7e2d47b3d8a0cbb8d92bb51a72132f45607937566', 'يَٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًا سَوِيًّا', 'fb3f46d06e9c23175c4317b7e2d47b3d8a0cbb8d92bb51a72132f45607937566', 'fb3f46d06e9c23175c4317b7e2d47b3d8a0cbb8d92bb51a72132f45607937566', NULL, 'يابت اني قد جاءني من العلم ما لم ياتك فاتبعني اهدك صرطا سويا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2294, 'tanzil-uthmani-v1.1', 19, 44, 'يَٰٓأَبَتِ لَا تَعْبُدِ ٱلشَّيْطَٰنَ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلرَّحْمَٰنِ عَصِيًّا', 'fd66170bf0b47d3b7db209160ed8c9c1796edc505aea9ee50642cb768fcf4c70', 'يَٰٓأَبَتِ لَا تَعْبُدِ ٱلشَّيْطَٰنَ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلرَّحْمَٰنِ عَصِيًّا', 'fd66170bf0b47d3b7db209160ed8c9c1796edc505aea9ee50642cb768fcf4c70', 'fd66170bf0b47d3b7db209160ed8c9c1796edc505aea9ee50642cb768fcf4c70', NULL, 'يابت لا تعبد الشيطن ان الشيطن كان للرحمن عصيا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2295, 'tanzil-uthmani-v1.1', 19, 45, 'يَٰٓأَبَتِ إِنِّىٓ أَخَافُ أَن يَمَسَّكَ عَذَابٌ مِّنَ ٱلرَّحْمَٰنِ فَتَكُونَ لِلشَّيْطَٰنِ وَلِيًّا', '0325ac2309d1fb4e104b1b999a344c71b913c64c2e91f34fb7eb626d479bc0b6', 'يَٰٓأَبَتِ إِنِّىٓ أَخَافُ أَن يَمَسَّكَ عَذَابٌ مِّنَ ٱلرَّحْمَٰنِ فَتَكُونَ لِلشَّيْطَٰنِ وَلِيًّا', '0325ac2309d1fb4e104b1b999a344c71b913c64c2e91f34fb7eb626d479bc0b6', '0325ac2309d1fb4e104b1b999a344c71b913c64c2e91f34fb7eb626d479bc0b6', NULL, 'يابت اني اخاف ان يمسك عذاب من الرحمن فتكون للشيطن وليا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2296, 'tanzil-uthmani-v1.1', 19, 46, 'قَالَ أَرَاغِبٌ أَنتَ عَنْ ءَالِهَتِى يَٰٓإِبْرَٰهِيمُ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ وَٱهْجُرْنِى مَلِيًّا', 'b14fa72c51d60e94245e3fbe8e03a34ab74872841b0e6aa53ca8c8768b2f0084', 'قَالَ أَرَاغِبٌ أَنتَ عَنْ ءَالِهَتِى يَٰٓإِبْرَٰهِيمُ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ وَٱهْجُرْنِى مَلِيًّا', 'b14fa72c51d60e94245e3fbe8e03a34ab74872841b0e6aa53ca8c8768b2f0084', 'b14fa72c51d60e94245e3fbe8e03a34ab74872841b0e6aa53ca8c8768b2f0084', NULL, 'قال اراغب انت عن ءالهتي يابرهيم لئن لم تنته لارجمنك واهجرني مليا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2297, 'tanzil-uthmani-v1.1', 19, 47, 'قَالَ سَلَٰمٌ عَلَيْكَ سَأَسْتَغْفِرُ لَكَ رَبِّىٓ إِنَّهُۥ كَانَ بِى حَفِيًّا', 'e2140c33674618e16f01f12f9d6f8054914ccdcda411d78b938a103c45e4da83', 'قَالَ سَلَٰمٌ عَلَيْكَ سَأَسْتَغْفِرُ لَكَ رَبِّىٓ إِنَّهُۥ كَانَ بِى حَفِيًّا', 'e2140c33674618e16f01f12f9d6f8054914ccdcda411d78b938a103c45e4da83', 'e2140c33674618e16f01f12f9d6f8054914ccdcda411d78b938a103c45e4da83', NULL, 'قال سلم عليك ساستغفر لك ربي انه كان بي حفيا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2298, 'tanzil-uthmani-v1.1', 19, 48, 'وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ ٱللَّهِ وَأَدْعُوا۟ رَبِّى عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّى شَقِيًّا', 'babefdfae4106b30d0d82621e75ce2c2f57ff462c224f7ddfea73ade46d5b079', 'وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ ٱللَّهِ وَأَدْعُوا۟ رَبِّى عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّى شَقِيًّا', 'babefdfae4106b30d0d82621e75ce2c2f57ff462c224f7ddfea73ade46d5b079', 'babefdfae4106b30d0d82621e75ce2c2f57ff462c224f7ddfea73ade46d5b079', NULL, 'واعتزلكم وما تدعون من دون الله وادعوا ربي عسي الا اكون بدعاء ربي شقيا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2299, 'tanzil-uthmani-v1.1', 19, 49, 'فَلَمَّا ٱعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ وَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَكُلًّا جَعَلْنَا نَبِيًّا', '1fe2bbf5f2896cc16ea6cb2c27c1a78020ca1fa8b5977c1e098a018ae017ee65', 'فَلَمَّا ٱعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ وَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَكُلًّا جَعَلْنَا نَبِيًّا', '1fe2bbf5f2896cc16ea6cb2c27c1a78020ca1fa8b5977c1e098a018ae017ee65', '1fe2bbf5f2896cc16ea6cb2c27c1a78020ca1fa8b5977c1e098a018ae017ee65', NULL, 'فلما اعتزلهم وما يعبدون من دون الله وهبنا له اسحق ويعقوب وكلا جعلنا نبيا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2300, 'tanzil-uthmani-v1.1', 19, 50, 'وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّا', 'e8d8a50883e1100abe9b75892646bfa69b410eaf4ed56d130656aed8cf898cc3', 'وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّا', 'e8d8a50883e1100abe9b75892646bfa69b410eaf4ed56d130656aed8cf898cc3', 'e8d8a50883e1100abe9b75892646bfa69b410eaf4ed56d130656aed8cf898cc3', NULL, 'ووهبنا لهم من رحمتنا وجعلنا لهم لسان صدق عليا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2301, 'tanzil-uthmani-v1.1', 19, 51, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مُوسَىٰٓ إِنَّهُۥ كَانَ مُخْلَصًا وَكَانَ رَسُولًا نَّبِيًّا', '0f4c7629e4d064f060ed4d1e4ec0ea6f977608f761f44eddd1efc55afac49faa', 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مُوسَىٰٓ إِنَّهُۥ كَانَ مُخْلَصًا وَكَانَ رَسُولًا نَّبِيًّا', '0f4c7629e4d064f060ed4d1e4ec0ea6f977608f761f44eddd1efc55afac49faa', '0f4c7629e4d064f060ed4d1e4ec0ea6f977608f761f44eddd1efc55afac49faa', NULL, 'واذكر في الكتب موسي انه كان مخلصا وكان رسولا نبيا', 16, 31, 123, 1, 4, 308, false, NULL),
    (2302, 'tanzil-uthmani-v1.1', 19, 52, 'وَنَٰدَيْنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلْأَيْمَنِ وَقَرَّبْنَٰهُ نَجِيًّا', '1b4e339f2bebbca2babc45ab5ac9336020d27768687ed6a470eb22beee7c8999', 'وَنَٰدَيْنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلْأَيْمَنِ وَقَرَّبْنَٰهُ نَجِيًّا', '1b4e339f2bebbca2babc45ab5ac9336020d27768687ed6a470eb22beee7c8999', '1b4e339f2bebbca2babc45ab5ac9336020d27768687ed6a470eb22beee7c8999', NULL, 'وندينه من جانب الطور الايمن وقربنه نجيا', 16, 31, 123, 1, 4, 309, false, NULL),
    (2303, 'tanzil-uthmani-v1.1', 19, 53, 'وَوَهَبْنَا لَهُۥ مِن رَّحْمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيًّا', '0684fe771bb3b3e9024bbe3c0f5ca2203cbbef34d21a71a0b4cc7cc3a3674e1d', 'وَوَهَبْنَا لَهُۥ مِن رَّحْمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيًّا', '0684fe771bb3b3e9024bbe3c0f5ca2203cbbef34d21a71a0b4cc7cc3a3674e1d', '0684fe771bb3b3e9024bbe3c0f5ca2203cbbef34d21a71a0b4cc7cc3a3674e1d', NULL, 'ووهبنا له من رحمتنا اخاه هرون نبيا', 16, 31, 123, 1, 4, 309, false, NULL),
    (2304, 'tanzil-uthmani-v1.1', 19, 54, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِسْمَٰعِيلَ إِنَّهُۥ كَانَ صَادِقَ ٱلْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا', 'f3eb9ecdcf2cb402a4d5539856120697c1f53cbc6424862baee5e624e5dd1ac4', 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِسْمَٰعِيلَ إِنَّهُۥ كَانَ صَادِقَ ٱلْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا', 'f3eb9ecdcf2cb402a4d5539856120697c1f53cbc6424862baee5e624e5dd1ac4', 'f3eb9ecdcf2cb402a4d5539856120697c1f53cbc6424862baee5e624e5dd1ac4', NULL, 'واذكر في الكتب اسمعيل انه كان صادق الوعد وكان رسولا نبيا', 16, 31, 123, 1, 4, 309, false, NULL),
    (2305, 'tanzil-uthmani-v1.1', 19, 55, 'وَكَانَ يَأْمُرُ أَهْلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيًّا', 'd6d64b947b96a3682272eb5c166da9f81f90f80163a0623bf16556b7b2f21b84', 'وَكَانَ يَأْمُرُ أَهْلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيًّا', 'd6d64b947b96a3682272eb5c166da9f81f90f80163a0623bf16556b7b2f21b84', 'd6d64b947b96a3682272eb5c166da9f81f90f80163a0623bf16556b7b2f21b84', NULL, 'وكان يامر اهله بالصلوه والزكوه وكان عند ربه مرضيا', 16, 31, 123, 1, 4, 309, false, NULL),
    (2306, 'tanzil-uthmani-v1.1', 19, 56, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِدْرِيسَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', '028dfd6329bae58ec3a1c3267adc5c6a211555d30e8279e2234efad9dc3a09c3', 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِدْرِيسَ إِنَّهُۥ كَانَ صِدِّيقًا نَّبِيًّا', '028dfd6329bae58ec3a1c3267adc5c6a211555d30e8279e2234efad9dc3a09c3', '028dfd6329bae58ec3a1c3267adc5c6a211555d30e8279e2234efad9dc3a09c3', NULL, 'واذكر في الكتب ادريس انه كان صديقا نبيا', 16, 31, 123, 1, 4, 309, false, NULL),
    (2307, 'tanzil-uthmani-v1.1', 19, 57, 'وَرَفَعْنَٰهُ مَكَانًا عَلِيًّا', '2c9904be62eb352bff61e28f6fc82799a63f5f4833ec622ade16b49f9461858f', 'وَرَفَعْنَٰهُ مَكَانًا عَلِيًّا', '2c9904be62eb352bff61e28f6fc82799a63f5f4833ec622ade16b49f9461858f', '2c9904be62eb352bff61e28f6fc82799a63f5f4833ec622ade16b49f9461858f', NULL, 'ورفعنه مكانا عليا', 16, 31, 123, 1, 4, 309, false, NULL),
    (2308, 'tanzil-uthmani-v1.1', 19, 58, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍ وَمِن ذُرِّيَّةِ إِبْرَٰهِيمَ وَإِسْرَٰٓءِيلَ وَمِمَّنْ هَدَيْنَا وَٱجْتَبَيْنَآ إِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُ ٱلرَّحْمَٰنِ خَرُّوا۟ سُجَّدًا وَبُكِيًّا', 'f47af3823512e994462417fbdfb0902cbe1f2dd93c5fed096b75cc4912ee594b', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍ وَمِن ذُرِّيَّةِ إِبْرَٰهِيمَ وَإِسْرَٰٓءِيلَ وَمِمَّنْ هَدَيْنَا وَٱجْتَبَيْنَآ إِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُ ٱلرَّحْمَٰنِ خَرُّوا۟ سُجَّدًا وَبُكِيًّا', 'f47af3823512e994462417fbdfb0902cbe1f2dd93c5fed096b75cc4912ee594b', 'f47af3823512e994462417fbdfb0902cbe1f2dd93c5fed096b75cc4912ee594b', NULL, 'اولئك الذين انعم الله عليهم من النبين من ذريه ءادم وممن حملنا مع نوح ومن ذريه ابرهيم واسرءيل وممن هدينا واجتبينا اذا تتلي عليهم ءايت الرحمن خروا سجدا وبكيا', 16, 31, 123, 1, 4, 309, true, 'recommended'),
    (2309, 'tanzil-uthmani-v1.1', 19, 59, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَٰتِ فَسَوْفَ يَلْقَوْنَ غَيًّا', 'e4d4e83fdf27ad1c6d03a0ed6979dd24aa1ea75d445781b3fc446f07f77700e4', 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَٰتِ فَسَوْفَ يَلْقَوْنَ غَيًّا', 'e4d4e83fdf27ad1c6d03a0ed6979dd24aa1ea75d445781b3fc446f07f77700e4', 'e4d4e83fdf27ad1c6d03a0ed6979dd24aa1ea75d445781b3fc446f07f77700e4', NULL, 'فخلف من بعدهم خلف اضاعوا الصلوه واتبعوا الشهوت فسوف يلقون غيا', 16, 31, 124, 1, 4, 309, false, NULL),
    (2310, 'tanzil-uthmani-v1.1', 19, 60, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـًٔا', '2799bd891d712db36f84cdd9ff2d0faf7e62203dd82d109aef5816cecb5e8e1f', 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـًٔا', '2799bd891d712db36f84cdd9ff2d0faf7e62203dd82d109aef5816cecb5e8e1f', '2799bd891d712db36f84cdd9ff2d0faf7e62203dd82d109aef5816cecb5e8e1f', NULL, 'الا من تاب وءامن وعمل صلحا فاولئك يدخلون الجنه ولا يظلمون شيا', 16, 31, 124, 1, 4, 309, false, NULL),
    (2311, 'tanzil-uthmani-v1.1', 19, 61, 'جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدَ ٱلرَّحْمَٰنُ عِبَادَهُۥ بِٱلْغَيْبِ إِنَّهُۥ كَانَ وَعْدُهُۥ مَأْتِيًّا', '0b2743dd953a8d30afe2d5e03dcee2cac60f0caa2dfdb8d8dc423e17c02c9d88', 'جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدَ ٱلرَّحْمَٰنُ عِبَادَهُۥ بِٱلْغَيْبِ إِنَّهُۥ كَانَ وَعْدُهُۥ مَأْتِيًّا', '0b2743dd953a8d30afe2d5e03dcee2cac60f0caa2dfdb8d8dc423e17c02c9d88', '0b2743dd953a8d30afe2d5e03dcee2cac60f0caa2dfdb8d8dc423e17c02c9d88', NULL, 'جنت عدن التي وعد الرحمن عباده بالغيب انه كان وعده ماتيا', 16, 31, 124, 1, 4, 309, false, NULL),
    (2312, 'tanzil-uthmani-v1.1', 19, 62, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَٰمًا وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا', '4663969433fb41d527978040fb6ab4e425cd1112a7bc0f396f12078304a11632', 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَٰمًا وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا', '4663969433fb41d527978040fb6ab4e425cd1112a7bc0f396f12078304a11632', '4663969433fb41d527978040fb6ab4e425cd1112a7bc0f396f12078304a11632', NULL, 'لا يسمعون فيها لغوا الا سلما ولهم رزقهم فيها بكره وعشيا', 16, 31, 124, 1, 4, 309, false, NULL),
    (2313, 'tanzil-uthmani-v1.1', 19, 63, 'تِلْكَ ٱلْجَنَّةُ ٱلَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّا', '2b6e4232c30de0786d0a65dfac055c155b2cbac8e94dad27ae76604004e43a66', 'تِلْكَ ٱلْجَنَّةُ ٱلَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّا', '2b6e4232c30de0786d0a65dfac055c155b2cbac8e94dad27ae76604004e43a66', '2b6e4232c30de0786d0a65dfac055c155b2cbac8e94dad27ae76604004e43a66', NULL, 'تلك الجنه التي نورث من عبادنا من كان تقيا', 16, 31, 124, 1, 4, 309, false, NULL),
    (2314, 'tanzil-uthmani-v1.1', 19, 64, 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ وَمَا كَانَ رَبُّكَ نَسِيًّا', '86fb3a665c2070b21f2df381d398a081cd418adbf2f47ea4415e64ca93a8a0e9', 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ وَمَا كَانَ رَبُّكَ نَسِيًّا', '86fb3a665c2070b21f2df381d398a081cd418adbf2f47ea4415e64ca93a8a0e9', '86fb3a665c2070b21f2df381d398a081cd418adbf2f47ea4415e64ca93a8a0e9', NULL, 'وما نتنزل الا بامر ربك له ما بين ايدينا وما خلفنا وما بين ذلك وما كان ربك نسيا', 16, 31, 124, 1, 4, 309, false, NULL),
    (2315, 'tanzil-uthmani-v1.1', 19, 65, 'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ هَلْ تَعْلَمُ لَهُۥ سَمِيًّا', '7d56eedbff9f3ceee638d9ab183ee260d2ce54c375d023ca47d5df640205a7b6', 'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ هَلْ تَعْلَمُ لَهُۥ سَمِيًّا', '7d56eedbff9f3ceee638d9ab183ee260d2ce54c375d023ca47d5df640205a7b6', '7d56eedbff9f3ceee638d9ab183ee260d2ce54c375d023ca47d5df640205a7b6', NULL, 'رب السموت والارض وما بينهما فاعبده واصطبر لعبدته هل تعلم له سميا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2316, 'tanzil-uthmani-v1.1', 19, 66, 'وَيَقُولُ ٱلْإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا', '05abc77a4177736b800b332ff683447863e7a220ff90557079658ca4b1105392', 'وَيَقُولُ ٱلْإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا', '05abc77a4177736b800b332ff683447863e7a220ff90557079658ca4b1105392', '05abc77a4177736b800b332ff683447863e7a220ff90557079658ca4b1105392', NULL, 'ويقول الانسن اءذا ما مت لسوف اخرج حيا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2317, 'tanzil-uthmani-v1.1', 19, 67, 'أَوَلَا يَذْكُرُ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـًٔا', '053d377a4b819ce946f8162290a5bbef0cc1d0227b55fb581a55d4459f0cd6d3', 'أَوَلَا يَذْكُرُ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـًٔا', '053d377a4b819ce946f8162290a5bbef0cc1d0227b55fb581a55d4459f0cd6d3', '053d377a4b819ce946f8162290a5bbef0cc1d0227b55fb581a55d4459f0cd6d3', NULL, 'اولا يذكر الانسن انا خلقنه من قبل ولم يك شيا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2318, 'tanzil-uthmani-v1.1', 19, 68, 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا', 'df250448c78cabc521db83166b9e6a5852ae4ed4e82c2e2bb91468d2567be054', 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا', 'df250448c78cabc521db83166b9e6a5852ae4ed4e82c2e2bb91468d2567be054', 'df250448c78cabc521db83166b9e6a5852ae4ed4e82c2e2bb91468d2567be054', NULL, 'فوربك لنحشرنهم والشيطين ثم لنحضرنهم حول جهنم جثيا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2319, 'tanzil-uthmani-v1.1', 19, 69, 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى ٱلرَّحْمَٰنِ عِتِيًّا', 'b3182fd2ea87d7d5473fd1e6e0180bc3a4133a4c9740287660fe16af52286433', 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى ٱلرَّحْمَٰنِ عِتِيًّا', 'b3182fd2ea87d7d5473fd1e6e0180bc3a4133a4c9740287660fe16af52286433', 'b3182fd2ea87d7d5473fd1e6e0180bc3a4133a4c9740287660fe16af52286433', NULL, 'ثم لننزعن من كل شيعه ايهم اشد علي الرحمن عتيا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2320, 'tanzil-uthmani-v1.1', 19, 70, 'ثُمَّ لَنَحْنُ أَعْلَمُ بِٱلَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّا', 'd86f3ba54f44fa7aaebf9bf0a9d72825eb72491888a24874fa8638373fdf8b4d', 'ثُمَّ لَنَحْنُ أَعْلَمُ بِٱلَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّا', 'd86f3ba54f44fa7aaebf9bf0a9d72825eb72491888a24874fa8638373fdf8b4d', 'd86f3ba54f44fa7aaebf9bf0a9d72825eb72491888a24874fa8638373fdf8b4d', NULL, 'ثم لنحن اعلم بالذين هم اولي بها صليا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2321, 'tanzil-uthmani-v1.1', 19, 71, 'وَإِن مِّنكُمْ إِلَّا وَارِدُهَا كَانَ عَلَىٰ رَبِّكَ حَتْمًا مَّقْضِيًّا', '32e970e752ce72df67b3f7cf7067b188024b59f58b7cedfcd9d1c11262ef56bc', 'وَإِن مِّنكُمْ إِلَّا وَارِدُهَا كَانَ عَلَىٰ رَبِّكَ حَتْمًا مَّقْضِيًّا', '32e970e752ce72df67b3f7cf7067b188024b59f58b7cedfcd9d1c11262ef56bc', '32e970e752ce72df67b3f7cf7067b188024b59f58b7cedfcd9d1c11262ef56bc', NULL, 'وان منكم الا واردها كان علي ربك حتما مقضيا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2322, 'tanzil-uthmani-v1.1', 19, 72, 'ثُمَّ نُنَجِّى ٱلَّذِينَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّٰلِمِينَ فِيهَا جِثِيًّا', '9554a7bf914ca4c69032d0671d4cf83170426be7c4983c8f0c10b0d56f636d9f', 'ثُمَّ نُنَجِّى ٱلَّذِينَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّٰلِمِينَ فِيهَا جِثِيًّا', '9554a7bf914ca4c69032d0671d4cf83170426be7c4983c8f0c10b0d56f636d9f', '9554a7bf914ca4c69032d0671d4cf83170426be7c4983c8f0c10b0d56f636d9f', NULL, 'ثم ننجي الذين اتقوا ونذر الظلمين فيها جثيا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2323, 'tanzil-uthmani-v1.1', 19, 73, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَىُّ ٱلْفَرِيقَيْنِ خَيْرٌ مَّقَامًا وَأَحْسَنُ نَدِيًّا', '789c8c37837b7904ef915ccf977c1ba6314f2dc42371ace70c8cdb2b2c7aa195', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَىُّ ٱلْفَرِيقَيْنِ خَيْرٌ مَّقَامًا وَأَحْسَنُ نَدِيًّا', '789c8c37837b7904ef915ccf977c1ba6314f2dc42371ace70c8cdb2b2c7aa195', '789c8c37837b7904ef915ccf977c1ba6314f2dc42371ace70c8cdb2b2c7aa195', NULL, 'واذا تتلي عليهم ءايتنا بينت قال الذين كفروا للذين ءامنوا اي الفريقين خير مقاما واحسن نديا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2324, 'tanzil-uthmani-v1.1', 19, 74, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَحْسَنُ أَثَٰثًا وَرِءْيًا', '4327d6600d1b37b430481a4e2729c540a91bc8e2953f8f0b204da5341552e018', 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَحْسَنُ أَثَٰثًا وَرِءْيًا', '4327d6600d1b37b430481a4e2729c540a91bc8e2953f8f0b204da5341552e018', '4327d6600d1b37b430481a4e2729c540a91bc8e2953f8f0b204da5341552e018', NULL, 'وكم اهلكنا قبلهم من قرن هم احسن اثثا ورءيا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2325, 'tanzil-uthmani-v1.1', 19, 75, 'قُلْ مَن كَانَ فِى ٱلضَّلَٰلَةِ فَلْيَمْدُدْ لَهُ ٱلرَّحْمَٰنُ مَدًّا حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ إِمَّا ٱلْعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَّكَانًا وَأَضْعَفُ جُندًا', 'acd2380bc08e63d91f90c76f28f94f71764541206f480899d2df9bd192a52506', 'قُلْ مَن كَانَ فِى ٱلضَّلَٰلَةِ فَلْيَمْدُدْ لَهُ ٱلرَّحْمَٰنُ مَدًّا حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ إِمَّا ٱلْعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّ مَّكَانًا وَأَضْعَفُ جُندًا', 'acd2380bc08e63d91f90c76f28f94f71764541206f480899d2df9bd192a52506', 'acd2380bc08e63d91f90c76f28f94f71764541206f480899d2df9bd192a52506', NULL, 'قل من كان في الضلله فليمدد له الرحمن مدا حتي اذا راوا ما يوعدون اما العذاب واما الساعه فسيعلمون من هو شر مكانا واضعف جندا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2326, 'tanzil-uthmani-v1.1', 19, 76, 'وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهْتَدَوْا۟ هُدًى وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ مَّرَدًّا', '11e713442a5865a70e2bb36795893ac25fc2b12c84f4ff0e82850613000e0f98', 'وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهْتَدَوْا۟ هُدًى وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ مَّرَدًّا', '11e713442a5865a70e2bb36795893ac25fc2b12c84f4ff0e82850613000e0f98', '11e713442a5865a70e2bb36795893ac25fc2b12c84f4ff0e82850613000e0f98', NULL, 'ويزيد الله الذين اهتدوا هدي والبقيت الصلحت خير عند ربك ثوابا وخير مردا', 16, 31, 124, 1, 4, 310, false, NULL),
    (2327, 'tanzil-uthmani-v1.1', 19, 77, 'أَفَرَءَيْتَ ٱلَّذِى كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالًا وَوَلَدًا', '859412effdfd1eb0eeb798d16f556de145ac44c52ce7d26dafbc39c43c076398', 'أَفَرَءَيْتَ ٱلَّذِى كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالًا وَوَلَدًا', '859412effdfd1eb0eeb798d16f556de145ac44c52ce7d26dafbc39c43c076398', '859412effdfd1eb0eeb798d16f556de145ac44c52ce7d26dafbc39c43c076398', NULL, 'افرءيت الذي كفر بايتنا وقال لاوتين مالا وولدا', 16, 31, 124, 1, 4, 311, false, NULL),
