    (2334, 'tanzil-uthmani-v1.1', 19, 84, 'فَلَا تَعْجَلْ عَلَيْهِمْ إِنَّمَا نَعُدُّ لَهُمْ عَدًّا', 'a12ba831d1716935d7689912f044b3faf15005ac8d611a85c5b554f3dd1ca5dd', 'فَلَا تَعْجَلْ عَلَيْهِمْ إِنَّمَا نَعُدُّ لَهُمْ عَدًّا', 'a12ba831d1716935d7689912f044b3faf15005ac8d611a85c5b554f3dd1ca5dd', 'a12ba831d1716935d7689912f044b3faf15005ac8d611a85c5b554f3dd1ca5dd', NULL, 'فلا تعجل عليهم انما نعد لهم عدا', 16, 31, 124, 1, 4, 311, false, NULL),
