    (2384, 'tanzil-uthmani-v1.1', 20, 36, 'قَالَ قَدْ أُوتِيتَ سُؤْلَكَ يَٰمُوسَىٰ', '59cfb97c75883c85136dce960d99cae01992dd113bd7787b8ec36be510ac656f', 'قَالَ قَدْ أُوتِيتَ سُؤْلَكَ يَٰمُوسَىٰ', '59cfb97c75883c85136dce960d99cae01992dd113bd7787b8ec36be510ac656f', '59cfb97c75883c85136dce960d99cae01992dd113bd7787b8ec36be510ac656f', NULL, 'قال قد اوتيت سؤلك يموسي', 16, 32, 125, 1, 4, 313, false, NULL),
    (2385, 'tanzil-uthmani-v1.1', 20, 37, 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَىٰٓ', 'e582be76f3b40458f36a8ea9191cbf42687271e427b367007125498e03fbdfe0', 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَىٰٓ', 'e582be76f3b40458f36a8ea9191cbf42687271e427b367007125498e03fbdfe0', 'e582be76f3b40458f36a8ea9191cbf42687271e427b367007125498e03fbdfe0', NULL, 'ولقد مننا عليك مره اخري', 16, 32, 125, 1, 4, 313, false, NULL),
    (2386, 'tanzil-uthmani-v1.1', 20, 38, 'إِذْ أَوْحَيْنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ', 'f3a90b08a16b0040a72ccbcbc5eb0b483c993f00484c3cc64cd3bd6e4f52a8b6', 'إِذْ أَوْحَيْنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ', 'f3a90b08a16b0040a72ccbcbc5eb0b483c993f00484c3cc64cd3bd6e4f52a8b6', 'f3a90b08a16b0040a72ccbcbc5eb0b483c993f00484c3cc64cd3bd6e4f52a8b6', NULL, 'اذ اوحينا الي امك ما يوحي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2387, 'tanzil-uthmani-v1.1', 20, 39, 'أَنِ ٱقْذِفِيهِ فِى ٱلتَّابُوتِ فَٱقْذِفِيهِ فِى ٱلْيَمِّ فَلْيُلْقِهِ ٱلْيَمُّ بِٱلسَّاحِلِ يَأْخُذْهُ عَدُوٌّ لِّى وَعَدُوٌّ لَّهُۥ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّى وَلِتُصْنَعَ عَلَىٰ عَيْنِىٓ', 'beec65710ebe350de206a347358e6554c787bdcd9f038c12abbb794f2b51ea60', 'أَنِ ٱقْذِفِيهِ فِى ٱلتَّابُوتِ فَٱقْذِفِيهِ فِى ٱلْيَمِّ فَلْيُلْقِهِ ٱلْيَمُّ بِٱلسَّاحِلِ يَأْخُذْهُ عَدُوٌّ لِّى وَعَدُوٌّ لَّهُۥ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِّنِّى وَلِتُصْنَعَ عَلَىٰ عَيْنِىٓ', 'beec65710ebe350de206a347358e6554c787bdcd9f038c12abbb794f2b51ea60', 'beec65710ebe350de206a347358e6554c787bdcd9f038c12abbb794f2b51ea60', NULL, 'ان اقذفيه في التابوت فاقذفيه في اليم فليلقه اليم بالساحل ياخذه عدو لي وعدو له والقيت عليك محبه مني ولتصنع علي عيني', 16, 32, 125, 1, 4, 314, false, NULL),
    (2388, 'tanzil-uthmani-v1.1', 20, 40, 'إِذْ تَمْشِىٓ أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُۥ فَرَجَعْنَٰكَ إِلَىٰٓ أُمِّكَ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَقَتَلْتَ نَفْسًا فَنَجَّيْنَٰكَ مِنَ ٱلْغَمِّ وَفَتَنَّٰكَ فُتُونًا فَلَبِثْتَ سِنِينَ فِىٓ أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرٍ يَٰمُوسَىٰ', '20ac9f23c66e828da850bea00eb2707a67091720e2c91a3ebf80e9705d596228', 'إِذْ تَمْشِىٓ أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُۥ فَرَجَعْنَٰكَ إِلَىٰٓ أُمِّكَ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَقَتَلْتَ نَفْسًا فَنَجَّيْنَٰكَ مِنَ ٱلْغَمِّ وَفَتَنَّٰكَ فُتُونًا فَلَبِثْتَ سِنِينَ فِىٓ أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرٍ يَٰمُوسَىٰ', '20ac9f23c66e828da850bea00eb2707a67091720e2c91a3ebf80e9705d596228', '20ac9f23c66e828da850bea00eb2707a67091720e2c91a3ebf80e9705d596228', NULL, 'اذ تمشي اختك فتقول هل ادلكم علي من يكفله فرجعنك الي امك كي تقر عينها ولا تحزن وقتلت نفسا فنجينك من الغم وفتنك فتونا فلبثت سنين في اهل مدين ثم جئت علي قدر يموسي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2389, 'tanzil-uthmani-v1.1', 20, 41, 'وَٱصْطَنَعْتُكَ لِنَفْسِى', '01e13a059c2957655ed29da0b6826de0bf725b4deb6ad1dad4092242c130838c', 'وَٱصْطَنَعْتُكَ لِنَفْسِى', '01e13a059c2957655ed29da0b6826de0bf725b4deb6ad1dad4092242c130838c', '01e13a059c2957655ed29da0b6826de0bf725b4deb6ad1dad4092242c130838c', NULL, 'واصطنعتك لنفسي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2390, 'tanzil-uthmani-v1.1', 20, 42, 'ٱذْهَبْ أَنتَ وَأَخُوكَ بِـَٔايَٰتِى وَلَا تَنِيَا فِى ذِكْرِى', 'de1e05f21a747e1a7e0324214f7761aab965ebe9166b79ba09b5eed7a121908e', 'ٱذْهَبْ أَنتَ وَأَخُوكَ بِـَٔايَٰتِى وَلَا تَنِيَا فِى ذِكْرِى', 'de1e05f21a747e1a7e0324214f7761aab965ebe9166b79ba09b5eed7a121908e', 'de1e05f21a747e1a7e0324214f7761aab965ebe9166b79ba09b5eed7a121908e', NULL, 'اذهب انت واخوك بايتي ولا تنيا في ذكري', 16, 32, 125, 1, 4, 314, false, NULL),
    (2391, 'tanzil-uthmani-v1.1', 20, 43, 'ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', '9a22e6cf6de997edaf208fee4985837d25933fd6faf253c014fc334122c4cc03', 'ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', '9a22e6cf6de997edaf208fee4985837d25933fd6faf253c014fc334122c4cc03', '9a22e6cf6de997edaf208fee4985837d25933fd6faf253c014fc334122c4cc03', NULL, 'اذهبا الي فرعون انه طغي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2392, 'tanzil-uthmani-v1.1', 20, 44, 'فَقُولَا لَهُۥ قَوْلًا لَّيِّنًا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ', '749630f29017375ae473b76e2257c6dcd3dcfc97dc2a7729ee128166c447dc7e', 'فَقُولَا لَهُۥ قَوْلًا لَّيِّنًا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ', '749630f29017375ae473b76e2257c6dcd3dcfc97dc2a7729ee128166c447dc7e', '749630f29017375ae473b76e2257c6dcd3dcfc97dc2a7729ee128166c447dc7e', NULL, 'فقولا له قولا لينا لعله يتذكر او يخشي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2393, 'tanzil-uthmani-v1.1', 20, 45, 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَآ أَوْ أَن يَطْغَىٰ', 'e412df5b348a8918fc67e3c52f13b01af305b67cab6768a7477c4933b4545a35', 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَآ أَوْ أَن يَطْغَىٰ', 'e412df5b348a8918fc67e3c52f13b01af305b67cab6768a7477c4933b4545a35', 'e412df5b348a8918fc67e3c52f13b01af305b67cab6768a7477c4933b4545a35', NULL, 'قالا ربنا اننا نخاف ان يفرط علينا او ان يطغي', 16, 32, 125, 1, 4, 314, false, NULL),
