    (2395, 'tanzil-uthmani-v1.1', 20, 47, 'فَأْتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ وَلَا تُعَذِّبْهُمْ قَدْ جِئْنَٰكَ بِـَٔايَةٍ مِّن رَّبِّكَ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلْهُدَىٰٓ', '3176aec8169c7bfc5df6f1de5b4154c6138313b8cd003b1c4faf9c0ad78fb182', 'فَأْتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ وَلَا تُعَذِّبْهُمْ قَدْ جِئْنَٰكَ بِـَٔايَةٍ مِّن رَّبِّكَ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلْهُدَىٰٓ', '3176aec8169c7bfc5df6f1de5b4154c6138313b8cd003b1c4faf9c0ad78fb182', '3176aec8169c7bfc5df6f1de5b4154c6138313b8cd003b1c4faf9c0ad78fb182', NULL, 'فاتياه فقولا انا رسولا ربك فارسل معنا بني اسرءيل ولا تعذبهم قد جئنك بايه من ربك والسلم علي من اتبع الهدي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2396, 'tanzil-uthmani-v1.1', 20, 48, 'إِنَّا قَدْ أُوحِىَ إِلَيْنَآ أَنَّ ٱلْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', '7ad1834cc68e2f58b7f43648854710330adfbfbaa0d25b6f06e494ebd704bfa0', 'إِنَّا قَدْ أُوحِىَ إِلَيْنَآ أَنَّ ٱلْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', '7ad1834cc68e2f58b7f43648854710330adfbfbaa0d25b6f06e494ebd704bfa0', '7ad1834cc68e2f58b7f43648854710330adfbfbaa0d25b6f06e494ebd704bfa0', NULL, 'انا قد اوحي الينا ان العذاب علي من كذب وتولي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2397, 'tanzil-uthmani-v1.1', 20, 49, 'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ', '233df7442e4c546cf9aefcb7cd26e7a54b04d6397926e710fe52276e3432891f', 'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ', '233df7442e4c546cf9aefcb7cd26e7a54b04d6397926e710fe52276e3432891f', '233df7442e4c546cf9aefcb7cd26e7a54b04d6397926e710fe52276e3432891f', NULL, 'قال فمن ربكما يموسي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2398, 'tanzil-uthmani-v1.1', 20, 50, 'قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ', 'ae23f0a6dba0c0757f3dd7cab86eb382dfcdcba544e179c03dae9d207da1a521', 'قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ', 'ae23f0a6dba0c0757f3dd7cab86eb382dfcdcba544e179c03dae9d207da1a521', 'ae23f0a6dba0c0757f3dd7cab86eb382dfcdcba544e179c03dae9d207da1a521', NULL, 'قال ربنا الذي اعطي كل شيء خلقه ثم هدي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2399, 'tanzil-uthmani-v1.1', 20, 51, 'قَالَ فَمَا بَالُ ٱلْقُرُونِ ٱلْأُولَىٰ', '31043e6f328fb4b35a5aedbd11e4c0ec29c555de91d1b7a1e48b9c10544247b0', 'قَالَ فَمَا بَالُ ٱلْقُرُونِ ٱلْأُولَىٰ', '31043e6f328fb4b35a5aedbd11e4c0ec29c555de91d1b7a1e48b9c10544247b0', '31043e6f328fb4b35a5aedbd11e4c0ec29c555de91d1b7a1e48b9c10544247b0', NULL, 'قال فما بال القرون الاولي', 16, 32, 125, 1, 4, 314, false, NULL),
    (2400, 'tanzil-uthmani-v1.1', 20, 52, 'قَالَ عِلْمُهَا عِندَ رَبِّى فِى كِتَٰبٍ لَّا يَضِلُّ رَبِّى وَلَا يَنسَى', '6a4a8ce26622a7385f86bf2453ce0a097bd8f34a711381cb879c63e3086577a4', 'قَالَ عِلْمُهَا عِندَ رَبِّى فِى كِتَٰبٍ لَّا يَضِلُّ رَبِّى وَلَا يَنسَى', '6a4a8ce26622a7385f86bf2453ce0a097bd8f34a711381cb879c63e3086577a4', '6a4a8ce26622a7385f86bf2453ce0a097bd8f34a711381cb879c63e3086577a4', NULL, 'قال علمها عند ربي في كتب لا يضل ربي ولا ينسي', 16, 32, 125, 1, 4, 315, false, NULL),
    (2401, 'tanzil-uthmani-v1.1', 20, 53, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجًا مِّن نَّبَاتٍ شَتَّىٰ', 'e4b94f6fd47b4d5fe95f98c0cbcdeb3f79ce01af1302f7ce905758abe08d86dd', 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَسَلَكَ لَكُمْ فِيهَا سُبُلًا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجًا مِّن نَّبَاتٍ شَتَّىٰ', 'e4b94f6fd47b4d5fe95f98c0cbcdeb3f79ce01af1302f7ce905758abe08d86dd', 'e4b94f6fd47b4d5fe95f98c0cbcdeb3f79ce01af1302f7ce905758abe08d86dd', NULL, 'الذي جعل لكم الارض مهدا وسلك لكم فيها سبلا وانزل من السماء ماء فاخرجنا به ازوجا من نبات شتي', 16, 32, 125, 1, 4, 315, false, NULL),
    (2402, 'tanzil-uthmani-v1.1', 20, 54, 'كُلُوا۟ وَٱرْعَوْا۟ أَنْعَٰمَكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', '3ff3991b650246a0c70984f1e50bb28f98db1ed0cdbd190d18fcbeee9d1f10ca', 'كُلُوا۟ وَٱرْعَوْا۟ أَنْعَٰمَكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', '3ff3991b650246a0c70984f1e50bb28f98db1ed0cdbd190d18fcbeee9d1f10ca', '3ff3991b650246a0c70984f1e50bb28f98db1ed0cdbd190d18fcbeee9d1f10ca', NULL, 'كلوا وارعوا انعمكم ان في ذلك لايت لاولي النهي', 16, 32, 125, 1, 4, 315, false, NULL),
    (2403, 'tanzil-uthmani-v1.1', 20, 55, 'مِنْهَا خَلَقْنَٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ', '416038b2a55bd323d2cc160ef02dc2b85191aa855e54189395b268321bfa026e', 'مِنْهَا خَلَقْنَٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ', '416038b2a55bd323d2cc160ef02dc2b85191aa855e54189395b268321bfa026e', '416038b2a55bd323d2cc160ef02dc2b85191aa855e54189395b268321bfa026e', NULL, 'منها خلقنكم وفيها نعيدكم ومنها نخرجكم تاره اخري', 16, 32, 126, 1, 4, 315, false, NULL),
    (2404, 'tanzil-uthmani-v1.1', 20, 56, 'وَلَقَدْ أَرَيْنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', '0057cfadb8ab7e05eeb69a72b0d97e377e7631d514f50421e064495f1710fc67', 'وَلَقَدْ أَرَيْنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', '0057cfadb8ab7e05eeb69a72b0d97e377e7631d514f50421e064495f1710fc67', '0057cfadb8ab7e05eeb69a72b0d97e377e7631d514f50421e064495f1710fc67', NULL, 'ولقد ارينه ءايتنا كلها فكذب وابي', 16, 32, 126, 1, 4, 315, false, NULL),
    (2405, 'tanzil-uthmani-v1.1', 20, 57, 'قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَٰمُوسَىٰ', '8cd335a98de4590bae72fde756a4ad0539cd3dcbd9a1f4c856ad776e2e970c16', 'قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَٰمُوسَىٰ', '8cd335a98de4590bae72fde756a4ad0539cd3dcbd9a1f4c856ad776e2e970c16', '8cd335a98de4590bae72fde756a4ad0539cd3dcbd9a1f4c856ad776e2e970c16', NULL, 'قال اجئتنا لتخرجنا من ارضنا بسحرك يموسي', 16, 32, 126, 1, 4, 315, false, NULL),
    (2406, 'tanzil-uthmani-v1.1', 20, 58, 'فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِّثْلِهِۦ فَٱجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًا لَّا نُخْلِفُهُۥ نَحْنُ وَلَآ أَنتَ مَكَانًا سُوًى', '4c20a41413616b82c9a8f6de14ba33d98fd5ab13fe92acbfd98b2733f3896081', 'فَلَنَأْتِيَنَّكَ بِسِحْرٍ مِّثْلِهِۦ فَٱجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًا لَّا نُخْلِفُهُۥ نَحْنُ وَلَآ أَنتَ مَكَانًا سُوًى', '4c20a41413616b82c9a8f6de14ba33d98fd5ab13fe92acbfd98b2733f3896081', '4c20a41413616b82c9a8f6de14ba33d98fd5ab13fe92acbfd98b2733f3896081', NULL, 'فلناتينك بسحر مثله فاجعل بيننا وبينك موعدا لا نخلفه نحن ولا انت مكانا سوي', 16, 32, 126, 1, 4, 315, false, NULL),
    (2407, 'tanzil-uthmani-v1.1', 20, 59, 'قَالَ مَوْعِدُكُمْ يَوْمُ ٱلزِّينَةِ وَأَن يُحْشَرَ ٱلنَّاسُ ضُحًى', '7da7504f7b7f5a1c8074418758162dadc65a54488fc8511feeb2e55d2d8a9179', 'قَالَ مَوْعِدُكُمْ يَوْمُ ٱلزِّينَةِ وَأَن يُحْشَرَ ٱلنَّاسُ ضُحًى', '7da7504f7b7f5a1c8074418758162dadc65a54488fc8511feeb2e55d2d8a9179', '7da7504f7b7f5a1c8074418758162dadc65a54488fc8511feeb2e55d2d8a9179', NULL, 'قال موعدكم يوم الزينه وان يحشر الناس ضحي', 16, 32, 126, 1, 4, 315, false, NULL),
    (2408, 'tanzil-uthmani-v1.1', 20, 60, 'فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُۥ ثُمَّ أَتَىٰ', '8db0f35da2cb72ae7868379599703557935740b7a6cf898e2b9077248088fb3b', 'فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُۥ ثُمَّ أَتَىٰ', '8db0f35da2cb72ae7868379599703557935740b7a6cf898e2b9077248088fb3b', '8db0f35da2cb72ae7868379599703557935740b7a6cf898e2b9077248088fb3b', NULL, 'فتولي فرعون فجمع كيده ثم اتي', 16, 32, 126, 1, 4, 315, false, NULL),
    (2409, 'tanzil-uthmani-v1.1', 20, 61, 'قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا۟ عَلَى ٱللَّهِ كَذِبًا فَيُسْحِتَكُم بِعَذَابٍ وَقَدْ خَابَ مَنِ ٱفْتَرَىٰ', 'ef8ada758e77507532feec4a3350c23cf18745d32cbb9e38e6df44af4f4c204d', 'قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا۟ عَلَى ٱللَّهِ كَذِبًا فَيُسْحِتَكُم بِعَذَابٍ وَقَدْ خَابَ مَنِ ٱفْتَرَىٰ', 'ef8ada758e77507532feec4a3350c23cf18745d32cbb9e38e6df44af4f4c204d', 'ef8ada758e77507532feec4a3350c23cf18745d32cbb9e38e6df44af4f4c204d', NULL, 'قال لهم موسي ويلكم لا تفتروا علي الله كذبا فيسحتكم بعذاب وقد خاب من افتري', 16, 32, 126, 1, 4, 315, false, NULL),
    (2410, 'tanzil-uthmani-v1.1', 20, 62, 'فَتَنَٰزَعُوٓا۟ أَمْرَهُم بَيْنَهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَىٰ', 'f62028860d59502e6bdf850b6f86d8463cbcb64a3f4e35fb62fefa759dcf54c0', 'فَتَنَٰزَعُوٓا۟ أَمْرَهُم بَيْنَهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَىٰ', 'f62028860d59502e6bdf850b6f86d8463cbcb64a3f4e35fb62fefa759dcf54c0', 'f62028860d59502e6bdf850b6f86d8463cbcb64a3f4e35fb62fefa759dcf54c0', NULL, 'فتنزعوا امرهم بينهم واسروا النجوي', 16, 32, 126, 1, 4, 315, false, NULL),
    (2411, 'tanzil-uthmani-v1.1', 20, 63, 'قَالُوٓا۟ إِنْ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ٱلْمُثْلَىٰ', 'f4755976267a445ac55d2d043484b1840634516234742fc76e3c9d6399a39d3b', 'قَالُوٓا۟ إِنْ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ٱلْمُثْلَىٰ', 'f4755976267a445ac55d2d043484b1840634516234742fc76e3c9d6399a39d3b', 'f4755976267a445ac55d2d043484b1840634516234742fc76e3c9d6399a39d3b', NULL, 'قالوا ان هذن لسحرن يريدان ان يخرجاكم من ارضكم بسحرهما ويذهبا بطريقتكم المثلي', 16, 32, 126, 1, 4, 315, false, NULL),
    (2412, 'tanzil-uthmani-v1.1', 20, 64, 'فَأَجْمِعُوا۟ كَيْدَكُمْ ثُمَّ ٱئْتُوا۟ صَفًّا وَقَدْ أَفْلَحَ ٱلْيَوْمَ مَنِ ٱسْتَعْلَىٰ', '90c5646a10d957b2862260ef4c3b07a76bf40c5e1d91b5db0baf89dc4c0d26aa', 'فَأَجْمِعُوا۟ كَيْدَكُمْ ثُمَّ ٱئْتُوا۟ صَفًّا وَقَدْ أَفْلَحَ ٱلْيَوْمَ مَنِ ٱسْتَعْلَىٰ', '90c5646a10d957b2862260ef4c3b07a76bf40c5e1d91b5db0baf89dc4c0d26aa', '90c5646a10d957b2862260ef4c3b07a76bf40c5e1d91b5db0baf89dc4c0d26aa', NULL, 'فاجمعوا كيدكم ثم ائتوا صفا وقد افلح اليوم من استعلي', 16, 32, 126, 1, 4, 315, false, NULL),
    (2413, 'tanzil-uthmani-v1.1', 20, 65, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَىٰ', '07a0643487ff3dbbb5de7a8f16f8b110f2f031f968023531da35812945f7e9f1', 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَىٰ', '07a0643487ff3dbbb5de7a8f16f8b110f2f031f968023531da35812945f7e9f1', '07a0643487ff3dbbb5de7a8f16f8b110f2f031f968023531da35812945f7e9f1', NULL, 'قالوا يموسي اما ان تلقي واما ان نكون اول من القي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2414, 'tanzil-uthmani-v1.1', 20, 66, 'قَالَ بَلْ أَلْقُوا۟ فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ', 'cd7b6f31ab1bbb60aa836f0a015a0fed4f60529ceaada6caa90766425814c8a1', 'قَالَ بَلْ أَلْقُوا۟ فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ', 'cd7b6f31ab1bbb60aa836f0a015a0fed4f60529ceaada6caa90766425814c8a1', 'cd7b6f31ab1bbb60aa836f0a015a0fed4f60529ceaada6caa90766425814c8a1', NULL, 'قال بل القوا فاذا حبالهم وعصيهم يخيل اليه من سحرهم انها تسعي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2415, 'tanzil-uthmani-v1.1', 20, 67, 'فَأَوْجَسَ فِى نَفْسِهِۦ خِيفَةً مُّوسَىٰ', '161fb08933280f6e863228d468bf7dbb2ccfa8767878c2279bbd7fd413cfaf85', 'فَأَوْجَسَ فِى نَفْسِهِۦ خِيفَةً مُّوسَىٰ', '161fb08933280f6e863228d468bf7dbb2ccfa8767878c2279bbd7fd413cfaf85', '161fb08933280f6e863228d468bf7dbb2ccfa8767878c2279bbd7fd413cfaf85', NULL, 'فاوجس في نفسه خيفه موسي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2416, 'tanzil-uthmani-v1.1', 20, 68, 'قُلْنَا لَا تَخَفْ إِنَّكَ أَنتَ ٱلْأَعْلَىٰ', 'd70e75d64efb442dc31dd82fbcc5793cfe32729aae5488ed6c7f6b15a61744a3', 'قُلْنَا لَا تَخَفْ إِنَّكَ أَنتَ ٱلْأَعْلَىٰ', 'd70e75d64efb442dc31dd82fbcc5793cfe32729aae5488ed6c7f6b15a61744a3', 'd70e75d64efb442dc31dd82fbcc5793cfe32729aae5488ed6c7f6b15a61744a3', NULL, 'قلنا لا تخف انك انت الاعلي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2417, 'tanzil-uthmani-v1.1', 20, 69, 'وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُوٓا۟ إِنَّمَا صَنَعُوا۟ كَيْدُ سَٰحِرٍ وَلَا يُفْلِحُ ٱلسَّاحِرُ حَيْثُ أَتَىٰ', 'ae9b1948bd96de98051605819bf2439ca503d50b63f29278bc3a7e9c396864bb', 'وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُوٓا۟ إِنَّمَا صَنَعُوا۟ كَيْدُ سَٰحِرٍ وَلَا يُفْلِحُ ٱلسَّاحِرُ حَيْثُ أَتَىٰ', 'ae9b1948bd96de98051605819bf2439ca503d50b63f29278bc3a7e9c396864bb', 'ae9b1948bd96de98051605819bf2439ca503d50b63f29278bc3a7e9c396864bb', NULL, 'والق ما في يمينك تلقف ما صنعوا انما صنعوا كيد سحر ولا يفلح الساحر حيث اتي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2418, 'tanzil-uthmani-v1.1', 20, 70, 'فَأُلْقِىَ ٱلسَّحَرَةُ سُجَّدًا قَالُوٓا۟ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ', '4b432279df010aec9133d7841a14220b1e959a21cf49f2edcebe09b23f0306cd', 'فَأُلْقِىَ ٱلسَّحَرَةُ سُجَّدًا قَالُوٓا۟ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ', '4b432279df010aec9133d7841a14220b1e959a21cf49f2edcebe09b23f0306cd', '4b432279df010aec9133d7841a14220b1e959a21cf49f2edcebe09b23f0306cd', NULL, 'فالقي السحره سجدا قالوا ءامنا برب هرون وموسي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2419, 'tanzil-uthmani-v1.1', 20, 71, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ فِى جُذُوعِ ٱلنَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابًا وَأَبْقَىٰ', 'a9baa48c217823134184b7d1d06e25bcfa0d2001bc5761e52e4588ed3ad7113e', 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ فِى جُذُوعِ ٱلنَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابًا وَأَبْقَىٰ', 'a9baa48c217823134184b7d1d06e25bcfa0d2001bc5761e52e4588ed3ad7113e', 'a9baa48c217823134184b7d1d06e25bcfa0d2001bc5761e52e4588ed3ad7113e', NULL, 'قال ءامنتم له قبل ان ءاذن لكم انه لكبيركم الذي علمكم السحر فلاقطعن ايديكم وارجلكم من خلف ولاصلبنكم في جذوع النخل ولتعلمن اينا اشد عذابا وابقي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2420, 'tanzil-uthmani-v1.1', 20, 72, 'قَالُوا۟ لَن نُّؤْثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلَّذِى فَطَرَنَا فَٱقْضِ مَآ أَنتَ قَاضٍ إِنَّمَا تَقْضِى هَٰذِهِ ٱلْحَيَوٰةَ ٱلدُّنْيَآ', 'a37bb0e6956f4db433f91185bdf5a3c733abea036a577d0ddaa3e96e9bd69acd', 'قَالُوا۟ لَن نُّؤْثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلَّذِى فَطَرَنَا فَٱقْضِ مَآ أَنتَ قَاضٍ إِنَّمَا تَقْضِى هَٰذِهِ ٱلْحَيَوٰةَ ٱلدُّنْيَآ', 'a37bb0e6956f4db433f91185bdf5a3c733abea036a577d0ddaa3e96e9bd69acd', 'a37bb0e6956f4db433f91185bdf5a3c733abea036a577d0ddaa3e96e9bd69acd', NULL, 'قالوا لن نؤثرك علي ما جاءنا من البينت والذي فطرنا فاقض ما انت قاض انما تقضي هذه الحيوه الدنيا', 16, 32, 126, 1, 4, 316, false, NULL),
    (2421, 'tanzil-uthmani-v1.1', 20, 73, 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ٱلسِّحْرِ وَٱللَّهُ خَيْرٌ وَأَبْقَىٰٓ', '2e81d431f16cec29156c62788fee301d4af422f7c28c8df63ddf83fa2790fdb8', 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ٱلسِّحْرِ وَٱللَّهُ خَيْرٌ وَأَبْقَىٰٓ', '2e81d431f16cec29156c62788fee301d4af422f7c28c8df63ddf83fa2790fdb8', '2e81d431f16cec29156c62788fee301d4af422f7c28c8df63ddf83fa2790fdb8', NULL, 'انا ءامنا بربنا ليغفر لنا خطينا وما اكرهتنا عليه من السحر والله خير وابقي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2422, 'tanzil-uthmani-v1.1', 20, 74, 'إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 'f2527e819b85e17cf692bc08cb274126c789c05a2fabe6cc5efb1e110e7ba8ba', 'إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 'f2527e819b85e17cf692bc08cb274126c789c05a2fabe6cc5efb1e110e7ba8ba', 'f2527e819b85e17cf692bc08cb274126c789c05a2fabe6cc5efb1e110e7ba8ba', NULL, 'انه من يات ربه مجرما فان له جهنم لا يموت فيها ولا يحيي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2423, 'tanzil-uthmani-v1.1', 20, 75, 'وَمَن يَأْتِهِۦ مُؤْمِنًا قَدْ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُو۟لَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلْعُلَىٰ', '2274ab8c287d5abba87dd521fa400ec163f33bffe2a82a66ec10ff9e8eb97ddf', 'وَمَن يَأْتِهِۦ مُؤْمِنًا قَدْ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُو۟لَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلْعُلَىٰ', '2274ab8c287d5abba87dd521fa400ec163f33bffe2a82a66ec10ff9e8eb97ddf', '2274ab8c287d5abba87dd521fa400ec163f33bffe2a82a66ec10ff9e8eb97ddf', NULL, 'ومن ياته مؤمنا قد عمل الصلحت فاولئك لهم الدرجت العلي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2424, 'tanzil-uthmani-v1.1', 20, 76, 'جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ', '123481a6ca962709e45a14a5b61542141f2cb64c0526a39e0e3d8e6ee698f17c', 'جَنَّٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ', '123481a6ca962709e45a14a5b61542141f2cb64c0526a39e0e3d8e6ee698f17c', '123481a6ca962709e45a14a5b61542141f2cb64c0526a39e0e3d8e6ee698f17c', NULL, 'جنت عدن تجري من تحتها الانهر خلدين فيها وذلك جزاء من تزكي', 16, 32, 126, 1, 4, 316, false, NULL),
    (2425, 'tanzil-uthmani-v1.1', 20, 77, 'وَلَقَدْ أَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِى فَٱضْرِبْ لَهُمْ طَرِيقًا فِى ٱلْبَحْرِ يَبَسًا لَّا تَخَٰفُ دَرَكًا وَلَا تَخْشَىٰ', 'e89b5ed9b983b7ea007a0e03e31ae026fbeaeb1e885d70ceeb594d7dae502efc', 'وَلَقَدْ أَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِى فَٱضْرِبْ لَهُمْ طَرِيقًا فِى ٱلْبَحْرِ يَبَسًا لَّا تَخَٰفُ دَرَكًا وَلَا تَخْشَىٰ', 'e89b5ed9b983b7ea007a0e03e31ae026fbeaeb1e885d70ceeb594d7dae502efc', 'e89b5ed9b983b7ea007a0e03e31ae026fbeaeb1e885d70ceeb594d7dae502efc', NULL, 'ولقد اوحينا الي موسي ان اسر بعبادي فاضرب لهم طريقا في البحر يبسا لا تخف دركا ولا تخشي', 16, 32, 126, 1, 4, 317, false, NULL),
    (2426, 'tanzil-uthmani-v1.1', 20, 78, 'فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلْيَمِّ مَا غَشِيَهُمْ', 'c87ee26bba56871207e7ea10956903c208c16fcd8018c6383ac9beb93e1b3452', 'فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلْيَمِّ مَا غَشِيَهُمْ', 'c87ee26bba56871207e7ea10956903c208c16fcd8018c6383ac9beb93e1b3452', 'c87ee26bba56871207e7ea10956903c208c16fcd8018c6383ac9beb93e1b3452', NULL, 'فاتبعهم فرعون بجنوده فغشيهم من اليم ما غشيهم', 16, 32, 126, 1, 4, 317, false, NULL),
    (2427, 'tanzil-uthmani-v1.1', 20, 79, 'وَأَضَلَّ فِرْعَوْنُ قَوْمَهُۥ وَمَا هَدَىٰ', 'ef365753ee36dd5948e71610c57fd700714081b77e0f13f2d0bf384363cc44fd', 'وَأَضَلَّ فِرْعَوْنُ قَوْمَهُۥ وَمَا هَدَىٰ', 'ef365753ee36dd5948e71610c57fd700714081b77e0f13f2d0bf384363cc44fd', 'ef365753ee36dd5948e71610c57fd700714081b77e0f13f2d0bf384363cc44fd', NULL, 'واضل فرعون قومه وما هدي', 16, 32, 126, 1, 4, 317, false, NULL),
    (2428, 'tanzil-uthmani-v1.1', 20, 80, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ قَدْ أَنجَيْنَٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنَٰكُمْ جَانِبَ ٱلطُّورِ ٱلْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ', 'bfcff924bac98350e4186d12e5edb2082f31deb328a13cb5a4b7a8969be71d62', 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ قَدْ أَنجَيْنَٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنَٰكُمْ جَانِبَ ٱلطُّورِ ٱلْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ', 'bfcff924bac98350e4186d12e5edb2082f31deb328a13cb5a4b7a8969be71d62', 'bfcff924bac98350e4186d12e5edb2082f31deb328a13cb5a4b7a8969be71d62', NULL, 'يبني اسرءيل قد انجينكم من عدوكم ووعدنكم جانب الطور الايمن ونزلنا عليكم المن والسلوي', 16, 32, 126, 1, 4, 317, false, NULL),
    (2429, 'tanzil-uthmani-v1.1', 20, 81, 'كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَلَا تَطْغَوْا۟ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى وَمَن يَحْلِلْ عَلَيْهِ غَضَبِى فَقَدْ هَوَىٰ', 'bf8bbde94a97c1c08679288b723828556c8f8cb97937c8e5b0f73a3f7e6d7d0b', 'كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَلَا تَطْغَوْا۟ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى وَمَن يَحْلِلْ عَلَيْهِ غَضَبِى فَقَدْ هَوَىٰ', 'bf8bbde94a97c1c08679288b723828556c8f8cb97937c8e5b0f73a3f7e6d7d0b', 'bf8bbde94a97c1c08679288b723828556c8f8cb97937c8e5b0f73a3f7e6d7d0b', NULL, 'كلوا من طيبت ما رزقنكم ولا تطغوا فيه فيحل عليكم غضبي ومن يحلل عليه غضبي فقد هوي', 16, 32, 126, 1, 4, 317, false, NULL),
    (2430, 'tanzil-uthmani-v1.1', 20, 82, 'وَإِنِّى لَغَفَّارٌ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا ثُمَّ ٱهْتَدَىٰ', 'c96a4a99d2076bf13dd19269e0b11efe1d49f7578e895760de35c94ee93b8efd', 'وَإِنِّى لَغَفَّارٌ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا ثُمَّ ٱهْتَدَىٰ', 'c96a4a99d2076bf13dd19269e0b11efe1d49f7578e895760de35c94ee93b8efd', 'c96a4a99d2076bf13dd19269e0b11efe1d49f7578e895760de35c94ee93b8efd', NULL, 'واني لغفار لمن تاب وءامن وعمل صلحا ثم اهتدي', 16, 32, 126, 1, 4, 317, false, NULL),
    (2431, 'tanzil-uthmani-v1.1', 20, 83, 'وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوسَىٰ', '9133bbfdf7123b93dc3a08f27d0219979157d2f6e2050f9bf37c5c481a09458d', 'وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوسَىٰ', '9133bbfdf7123b93dc3a08f27d0219979157d2f6e2050f9bf37c5c481a09458d', '9133bbfdf7123b93dc3a08f27d0219979157d2f6e2050f9bf37c5c481a09458d', NULL, 'وما اعجلك عن قومك يموسي', 16, 32, 127, 1, 4, 317, false, NULL),
    (2432, 'tanzil-uthmani-v1.1', 20, 84, 'قَالَ هُمْ أُو۟لَآءِ عَلَىٰٓ أَثَرِى وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ', 'aa4c2fc069b4d976ba037dcc4200e6f43854afa3e593d46c6fd12536c121849f', 'قَالَ هُمْ أُو۟لَآءِ عَلَىٰٓ أَثَرِى وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ', 'aa4c2fc069b4d976ba037dcc4200e6f43854afa3e593d46c6fd12536c121849f', 'aa4c2fc069b4d976ba037dcc4200e6f43854afa3e593d46c6fd12536c121849f', NULL, 'قال هم اولاء علي اثري وعجلت اليك رب لترضي', 16, 32, 127, 1, 4, 317, false, NULL),
    (2433, 'tanzil-uthmani-v1.1', 20, 85, 'قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنۢ بَعْدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِىُّ', '938be0cfd615f43426c266ff1eca8764db89bb25b44133548dedd21f911e7c14', 'قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنۢ بَعْدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِىُّ', '938be0cfd615f43426c266ff1eca8764db89bb25b44133548dedd21f911e7c14', '938be0cfd615f43426c266ff1eca8764db89bb25b44133548dedd21f911e7c14', NULL, 'قال فانا قد فتنا قومك من بعدك واضلهم السامري', 16, 32, 127, 1, 4, 317, false, NULL),
    (2434, 'tanzil-uthmani-v1.1', 20, 86, 'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ يَٰقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا أَفَطَالَ عَلَيْكُمُ ٱلْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِى', '39c146c9e24bccf70400b5efa73d1f74e90fadefe5df5830265f078819a640fc', 'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ يَٰقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا أَفَطَالَ عَلَيْكُمُ ٱلْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِى', '39c146c9e24bccf70400b5efa73d1f74e90fadefe5df5830265f078819a640fc', '39c146c9e24bccf70400b5efa73d1f74e90fadefe5df5830265f078819a640fc', NULL, 'فرجع موسي الي قومه غضبن اسفا قال يقوم الم يعدكم ربكم وعدا حسنا افطال عليكم العهد ام اردتم ان يحل عليكم غضب من ربكم فاخلفتم موعدي', 16, 32, 127, 1, 4, 317, false, NULL),
    (2435, 'tanzil-uthmani-v1.1', 20, 87, 'قَالُوا۟ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَآ أَوْزَارًا مِّن زِينَةِ ٱلْقَوْمِ فَقَذَفْنَٰهَا فَكَذَٰلِكَ أَلْقَى ٱلسَّامِرِىُّ', '4b76ca00e5efc502118ef95deeb705ede640384f2ddc002a5fa39856d52ca7c2', 'قَالُوا۟ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَآ أَوْزَارًا مِّن زِينَةِ ٱلْقَوْمِ فَقَذَفْنَٰهَا فَكَذَٰلِكَ أَلْقَى ٱلسَّامِرِىُّ', '4b76ca00e5efc502118ef95deeb705ede640384f2ddc002a5fa39856d52ca7c2', '4b76ca00e5efc502118ef95deeb705ede640384f2ddc002a5fa39856d52ca7c2', NULL, 'قالوا ما اخلفنا موعدك بملكنا ولكنا حملنا اوزارا من زينه القوم فقذفنها فكذلك القي السامري', 16, 32, 127, 1, 4, 317, false, NULL),
    (2436, 'tanzil-uthmani-v1.1', 20, 88, 'فَأَخْرَجَ لَهُمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ فَقَالُوا۟ هَٰذَآ إِلَٰهُكُمْ وَإِلَٰهُ مُوسَىٰ فَنَسِىَ', '4822c8babff291b641897ca248b63b333766ea62075b01d19429edbacc1d843d', 'فَأَخْرَجَ لَهُمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ فَقَالُوا۟ هَٰذَآ إِلَٰهُكُمْ وَإِلَٰهُ مُوسَىٰ فَنَسِىَ', '4822c8babff291b641897ca248b63b333766ea62075b01d19429edbacc1d843d', '4822c8babff291b641897ca248b63b333766ea62075b01d19429edbacc1d843d', NULL, 'فاخرج لهم عجلا جسدا له خوار فقالوا هذا الهكم واله موسي فنسي', 16, 32, 127, 1, 4, 318, false, NULL),
    (2437, 'tanzil-uthmani-v1.1', 20, 89, 'أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا', '61b50a39f495af4383e1113e8544c61fc0d2847f153d4818069cd336e5a365cf', 'أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا', '61b50a39f495af4383e1113e8544c61fc0d2847f153d4818069cd336e5a365cf', '61b50a39f495af4383e1113e8544c61fc0d2847f153d4818069cd336e5a365cf', NULL, 'افلا يرون الا يرجع اليهم قولا ولا يملك لهم ضرا ولا نفعا', 16, 32, 127, 1, 4, 318, false, NULL),
    (2438, 'tanzil-uthmani-v1.1', 20, 90, 'وَلَقَدْ قَالَ لَهُمْ هَٰرُونُ مِن قَبْلُ يَٰقَوْمِ إِنَّمَا فُتِنتُم بِهِۦ وَإِنَّ رَبَّكُمُ ٱلرَّحْمَٰنُ فَٱتَّبِعُونِى وَأَطِيعُوٓا۟ أَمْرِى', '2d4a632f1c24bc43630d123af43b612f5a14513d93dc238427a3bcf5aaa9f9c0', 'وَلَقَدْ قَالَ لَهُمْ هَٰرُونُ مِن قَبْلُ يَٰقَوْمِ إِنَّمَا فُتِنتُم بِهِۦ وَإِنَّ رَبَّكُمُ ٱلرَّحْمَٰنُ فَٱتَّبِعُونِى وَأَطِيعُوٓا۟ أَمْرِى', '2d4a632f1c24bc43630d123af43b612f5a14513d93dc238427a3bcf5aaa9f9c0', '2d4a632f1c24bc43630d123af43b612f5a14513d93dc238427a3bcf5aaa9f9c0', NULL, 'ولقد قال لهم هرون من قبل يقوم انما فتنتم به وان ربكم الرحمن فاتبعوني واطيعوا امري', 16, 32, 127, 1, 4, 318, false, NULL),
    (2439, 'tanzil-uthmani-v1.1', 20, 91, 'قَالُوا۟ لَن نَّبْرَحَ عَلَيْهِ عَٰكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ', 'e2a9009c0f68840f95b57290b1757456482a5987acdf3d6b3bdb12cb63c39d98', 'قَالُوا۟ لَن نَّبْرَحَ عَلَيْهِ عَٰكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ', 'e2a9009c0f68840f95b57290b1757456482a5987acdf3d6b3bdb12cb63c39d98', 'e2a9009c0f68840f95b57290b1757456482a5987acdf3d6b3bdb12cb63c39d98', NULL, 'قالوا لن نبرح عليه عكفين حتي يرجع الينا موسي', 16, 32, 127, 1, 4, 318, false, NULL),
    (2440, 'tanzil-uthmani-v1.1', 20, 92, 'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓا۟', '8695b0540ddbbf5f14e4efebd9a58d2a5dbc307bbb39b435e2f08c3a15976a70', 'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓا۟', '8695b0540ddbbf5f14e4efebd9a58d2a5dbc307bbb39b435e2f08c3a15976a70', '8695b0540ddbbf5f14e4efebd9a58d2a5dbc307bbb39b435e2f08c3a15976a70', NULL, 'قال يهرون ما منعك اذ رايتهم ضلوا', 16, 32, 127, 1, 4, 318, false, NULL),
    (2441, 'tanzil-uthmani-v1.1', 20, 93, 'أَلَّا تَتَّبِعَنِ أَفَعَصَيْتَ أَمْرِى', '3dfe2b55f740e4122ea1edcc33c941365a557629522a0fb300f2fcd27be4a3b6', 'أَلَّا تَتَّبِعَنِ أَفَعَصَيْتَ أَمْرِى', '3dfe2b55f740e4122ea1edcc33c941365a557629522a0fb300f2fcd27be4a3b6', '3dfe2b55f740e4122ea1edcc33c941365a557629522a0fb300f2fcd27be4a3b6', NULL, 'الا تتبعن افعصيت امري', 16, 32, 127, 1, 4, 318, false, NULL),
    (2442, 'tanzil-uthmani-v1.1', 20, 94, 'قَالَ يَبْنَؤُمَّ لَا تَأْخُذْ بِلِحْيَتِى وَلَا بِرَأْسِىٓ إِنِّى خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِىٓ إِسْرَٰٓءِيلَ وَلَمْ تَرْقُبْ قَوْلِى', 'c75a66da3db4703e22467868bd3254d8c52e7df6bfe49666f1a1dd095cf16764', 'قَالَ يَبْنَؤُمَّ لَا تَأْخُذْ بِلِحْيَتِى وَلَا بِرَأْسِىٓ إِنِّى خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِىٓ إِسْرَٰٓءِيلَ وَلَمْ تَرْقُبْ قَوْلِى', 'c75a66da3db4703e22467868bd3254d8c52e7df6bfe49666f1a1dd095cf16764', 'c75a66da3db4703e22467868bd3254d8c52e7df6bfe49666f1a1dd095cf16764', NULL, 'قال يبنؤم لا تاخذ بلحيتي ولا براسي اني خشيت ان تقول فرقت بين بني اسرءيل ولم ترقب قولي', 16, 32, 127, 1, 4, 318, false, NULL),
    (2443, 'tanzil-uthmani-v1.1', 20, 95, 'قَالَ فَمَا خَطْبُكَ يَٰسَٰمِرِىُّ', '6ff64f1ad86b26b9015a948799d5167f78215e6e5d2ff4790782766a84824b80', 'قَالَ فَمَا خَطْبُكَ يَٰسَٰمِرِىُّ', '6ff64f1ad86b26b9015a948799d5167f78215e6e5d2ff4790782766a84824b80', '6ff64f1ad86b26b9015a948799d5167f78215e6e5d2ff4790782766a84824b80', NULL, 'قال فما خطبك يسمري', 16, 32, 127, 1, 4, 318, false, NULL),
    (2444, 'tanzil-uthmani-v1.1', 20, 96, 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا۟ بِهِۦ فَقَبَضْتُ قَبْضَةً مِّنْ أَثَرِ ٱلرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِى نَفْسِى', '7dabeb7528aae310558727c40b95fc1948c4c52d6fff5c444f5b94d03ffed177', 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا۟ بِهِۦ فَقَبَضْتُ قَبْضَةً مِّنْ أَثَرِ ٱلرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِى نَفْسِى', '7dabeb7528aae310558727c40b95fc1948c4c52d6fff5c444f5b94d03ffed177', '7dabeb7528aae310558727c40b95fc1948c4c52d6fff5c444f5b94d03ffed177', NULL, 'قال بصرت بما لم يبصروا به فقبضت قبضه من اثر الرسول فنبذتها وكذلك سولت لي نفسي', 16, 32, 127, 1, 4, 318, false, NULL),
    (2445, 'tanzil-uthmani-v1.1', 20, 97, 'قَالَ فَٱذْهَبْ فَإِنَّ لَكَ فِى ٱلْحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَ وَإِنَّ لَكَ مَوْعِدًا لَّن تُخْلَفَهُۥ وَٱنظُرْ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِى ظَلْتَ عَلَيْهِ عَاكِفًا لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِى ٱلْيَمِّ نَسْفًا', '4c8d761241c8d68c06ec53206e5acec7ea79772002af649ba80a427f410c5694', 'قَالَ فَٱذْهَبْ فَإِنَّ لَكَ فِى ٱلْحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَ وَإِنَّ لَكَ مَوْعِدًا لَّن تُخْلَفَهُۥ وَٱنظُرْ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِى ظَلْتَ عَلَيْهِ عَاكِفًا لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِى ٱلْيَمِّ نَسْفًا', '4c8d761241c8d68c06ec53206e5acec7ea79772002af649ba80a427f410c5694', '4c8d761241c8d68c06ec53206e5acec7ea79772002af649ba80a427f410c5694', NULL, 'قال فاذهب فان لك في الحيوه ان تقول لا مساس وان لك موعدا لن تخلفه وانظر الي الهك الذي ظلت عليه عاكفا لنحرقنه ثم لننسفنه في اليم نسفا', 16, 32, 127, 1, 4, 318, false, NULL),
    (2446, 'tanzil-uthmani-v1.1', 20, 98, 'إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ وَسِعَ كُلَّ شَىْءٍ عِلْمًا', 'fd18f053970e8e814050238a4267e7f0553a0197b445a70540e70794de4fee76', 'إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ وَسِعَ كُلَّ شَىْءٍ عِلْمًا', 'fd18f053970e8e814050238a4267e7f0553a0197b445a70540e70794de4fee76', 'fd18f053970e8e814050238a4267e7f0553a0197b445a70540e70794de4fee76', NULL, 'انما الهكم الله الذي لا اله الا هو وسع كل شيء علما', 16, 32, 127, 1, 4, 318, false, NULL),
    (2447, 'tanzil-uthmani-v1.1', 20, 99, 'كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ مَا قَدْ سَبَقَ وَقَدْ ءَاتَيْنَٰكَ مِن لَّدُنَّا ذِكْرًا', '38c3d692898dff3909a5876e0aad178aba77c467285f7d681e48f3534edc168e', 'كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ مَا قَدْ سَبَقَ وَقَدْ ءَاتَيْنَٰكَ مِن لَّدُنَّا ذِكْرًا', '38c3d692898dff3909a5876e0aad178aba77c467285f7d681e48f3534edc168e', '38c3d692898dff3909a5876e0aad178aba77c467285f7d681e48f3534edc168e', NULL, 'كذلك نقص عليك من انباء ما قد سبق وقد ءاتينك من لدنا ذكرا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2448, 'tanzil-uthmani-v1.1', 20, 100, 'مَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُۥ يَحْمِلُ يَوْمَ ٱلْقِيَٰمَةِ وِزْرًا', '415fab54563baf93204a13a374613b10046be58cd8a848b366221f87c2ddd351', 'مَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُۥ يَحْمِلُ يَوْمَ ٱلْقِيَٰمَةِ وِزْرًا', '415fab54563baf93204a13a374613b10046be58cd8a848b366221f87c2ddd351', '415fab54563baf93204a13a374613b10046be58cd8a848b366221f87c2ddd351', NULL, 'من اعرض عنه فانه يحمل يوم القيمه وزرا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2449, 'tanzil-uthmani-v1.1', 20, 101, 'خَٰلِدِينَ فِيهِ وَسَآءَ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ حِمْلًا', '92d57510557f8805a02bea52f27b78c4186f74dfe5125b80b50d2274ae5bb0a9', 'خَٰلِدِينَ فِيهِ وَسَآءَ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ حِمْلًا', '92d57510557f8805a02bea52f27b78c4186f74dfe5125b80b50d2274ae5bb0a9', '92d57510557f8805a02bea52f27b78c4186f74dfe5125b80b50d2274ae5bb0a9', NULL, 'خلدين فيه وساء لهم يوم القيمه حملا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2450, 'tanzil-uthmani-v1.1', 20, 102, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ وَنَحْشُرُ ٱلْمُجْرِمِينَ يَوْمَئِذٍ زُرْقًا', '18bb5caf5e18d25b9ece2aa8284f239665ff831e0a228bc4895697423daebe2c', 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ وَنَحْشُرُ ٱلْمُجْرِمِينَ يَوْمَئِذٍ زُرْقًا', '18bb5caf5e18d25b9ece2aa8284f239665ff831e0a228bc4895697423daebe2c', '18bb5caf5e18d25b9ece2aa8284f239665ff831e0a228bc4895697423daebe2c', NULL, 'يوم ينفخ في الصور ونحشر المجرمين يومئذ زرقا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2451, 'tanzil-uthmani-v1.1', 20, 103, 'يَتَخَٰفَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًا', 'f5ae1500143a708b23416bf60c65f4ad65b26423122517d0778ba6a7573876b9', 'يَتَخَٰفَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًا', 'f5ae1500143a708b23416bf60c65f4ad65b26423122517d0778ba6a7573876b9', 'f5ae1500143a708b23416bf60c65f4ad65b26423122517d0778ba6a7573876b9', NULL, 'يتخفتون بينهم ان لبثتم الا عشرا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2452, 'tanzil-uthmani-v1.1', 20, 104, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِن لَّبِثْتُمْ إِلَّا يَوْمًا', '8035d4f005d4d33c74e96a40453285d40071cdb5d20695296ca5b7d8925fb1e0', 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِن لَّبِثْتُمْ إِلَّا يَوْمًا', '8035d4f005d4d33c74e96a40453285d40071cdb5d20695296ca5b7d8925fb1e0', '8035d4f005d4d33c74e96a40453285d40071cdb5d20695296ca5b7d8925fb1e0', NULL, 'نحن اعلم بما يقولون اذ يقول امثلهم طريقه ان لبثتم الا يوما', 16, 32, 127, 1, 4, 319, false, NULL),
    (2453, 'tanzil-uthmani-v1.1', 20, 105, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّى نَسْفًا', 'a11a4605f18842cb992ddb45afdfdcd9388037938b10876f41ff435e163a5c3b', 'وَيَسْـَٔلُونَكَ عَنِ ٱلْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّى نَسْفًا', 'a11a4605f18842cb992ddb45afdfdcd9388037938b10876f41ff435e163a5c3b', 'a11a4605f18842cb992ddb45afdfdcd9388037938b10876f41ff435e163a5c3b', NULL, 'ويسلونك عن الجبال فقل ينسفها ربي نسفا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2454, 'tanzil-uthmani-v1.1', 20, 106, 'فَيَذَرُهَا قَاعًا صَفْصَفًا', 'bf8e0a0d86f2ad11d606d593e36e7dbceb7364ad182dc3170a78277d02275c52', 'فَيَذَرُهَا قَاعًا صَفْصَفًا', 'bf8e0a0d86f2ad11d606d593e36e7dbceb7364ad182dc3170a78277d02275c52', 'bf8e0a0d86f2ad11d606d593e36e7dbceb7364ad182dc3170a78277d02275c52', NULL, 'فيذرها قاعا صفصفا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2455, 'tanzil-uthmani-v1.1', 20, 107, 'لَّا تَرَىٰ فِيهَا عِوَجًا وَلَآ أَمْتًا', '15dd15259d96539756bbcd7ed966c13694ec46f851b604b075dd2347e2e91fde', 'لَّا تَرَىٰ فِيهَا عِوَجًا وَلَآ أَمْتًا', '15dd15259d96539756bbcd7ed966c13694ec46f851b604b075dd2347e2e91fde', '15dd15259d96539756bbcd7ed966c13694ec46f851b604b075dd2347e2e91fde', NULL, 'لا تري فيها عوجا ولا امتا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2456, 'tanzil-uthmani-v1.1', 20, 108, 'يَوْمَئِذٍ يَتَّبِعُونَ ٱلدَّاعِىَ لَا عِوَجَ لَهُۥ وَخَشَعَتِ ٱلْأَصْوَاتُ لِلرَّحْمَٰنِ فَلَا تَسْمَعُ إِلَّا هَمْسًا', 'e568656a8c837578e2d3cb0a1cefe0385a6227d06d02f3d36e54e61cbb46aca1', 'يَوْمَئِذٍ يَتَّبِعُونَ ٱلدَّاعِىَ لَا عِوَجَ لَهُۥ وَخَشَعَتِ ٱلْأَصْوَاتُ لِلرَّحْمَٰنِ فَلَا تَسْمَعُ إِلَّا هَمْسًا', 'e568656a8c837578e2d3cb0a1cefe0385a6227d06d02f3d36e54e61cbb46aca1', 'e568656a8c837578e2d3cb0a1cefe0385a6227d06d02f3d36e54e61cbb46aca1', NULL, 'يومئذ يتبعون الداعي لا عوج له وخشعت الاصوات للرحمن فلا تسمع الا همسا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2457, 'tanzil-uthmani-v1.1', 20, 109, 'يَوْمَئِذٍ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَرَضِىَ لَهُۥ قَوْلًا', '7170583b5cd57b143fd065a7009caf87ac765e036595bd51c609d1c89c096e49', 'يَوْمَئِذٍ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَرَضِىَ لَهُۥ قَوْلًا', '7170583b5cd57b143fd065a7009caf87ac765e036595bd51c609d1c89c096e49', '7170583b5cd57b143fd065a7009caf87ac765e036595bd51c609d1c89c096e49', NULL, 'يومئذ لا تنفع الشفعه الا من اذن له الرحمن ورضي له قولا', 16, 32, 127, 1, 4, 319, false, NULL),
    (2458, 'tanzil-uthmani-v1.1', 20, 110, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْمًا', '4e20335960b96cb0429e2b6d231c1253c2a71a6cdca76adda2397dea6417624c', 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْمًا', '4e20335960b96cb0429e2b6d231c1253c2a71a6cdca76adda2397dea6417624c', '4e20335960b96cb0429e2b6d231c1253c2a71a6cdca76adda2397dea6417624c', NULL, 'يعلم ما بين ايديهم وما خلفهم ولا يحيطون به علما', 16, 32, 127, 1, 4, 319, false, NULL),
    (2459, 'tanzil-uthmani-v1.1', 20, 111, 'وَعَنَتِ ٱلْوُجُوهُ لِلْحَىِّ ٱلْقَيُّومِ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْمًا', '3cf83a5013d8878edfd53988a3bf7fe27787db993f14751acbf27f15e48bea1f', 'وَعَنَتِ ٱلْوُجُوهُ لِلْحَىِّ ٱلْقَيُّومِ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْمًا', '3cf83a5013d8878edfd53988a3bf7fe27787db993f14751acbf27f15e48bea1f', '3cf83a5013d8878edfd53988a3bf7fe27787db993f14751acbf27f15e48bea1f', NULL, 'وعنت الوجوه للحي القيوم وقد خاب من حمل ظلما', 16, 32, 128, 1, 4, 319, false, NULL),
    (2460, 'tanzil-uthmani-v1.1', 20, 112, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا', '2025e5c9185434fb59358620e0f705c031541a856907654fd16e45707cb76f7b', 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا', '2025e5c9185434fb59358620e0f705c031541a856907654fd16e45707cb76f7b', '2025e5c9185434fb59358620e0f705c031541a856907654fd16e45707cb76f7b', NULL, 'ومن يعمل من الصلحت وهو مؤمن فلا يخاف ظلما ولا هضما', 16, 32, 128, 1, 4, 319, false, NULL),
    (2461, 'tanzil-uthmani-v1.1', 20, 113, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ قُرْءَانًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ ٱلْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًا', '9ea6ab6ee1bb12774d0c03ab725b69a318956558bc51ac340776326c94f97a80', 'وَكَذَٰلِكَ أَنزَلْنَٰهُ قُرْءَانًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ ٱلْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًا', '9ea6ab6ee1bb12774d0c03ab725b69a318956558bc51ac340776326c94f97a80', '9ea6ab6ee1bb12774d0c03ab725b69a318956558bc51ac340776326c94f97a80', NULL, 'وكذلك انزلنه قرءانا عربيا وصرفنا فيه من الوعيد لعلهم يتقون او يحدث لهم ذكرا', 16, 32, 128, 1, 4, 319, false, NULL),
    (2462, 'tanzil-uthmani-v1.1', 20, 114, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ وَقُل رَّبِّ زِدْنِى عِلْمًا', 'ee1133ea8f497da92cdce3d0aee58d44272050ecfba62dd467f96a37f8ab2831', 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ وَقُل رَّبِّ زِدْنِى عِلْمًا', 'ee1133ea8f497da92cdce3d0aee58d44272050ecfba62dd467f96a37f8ab2831', 'ee1133ea8f497da92cdce3d0aee58d44272050ecfba62dd467f96a37f8ab2831', NULL, 'فتعلي الله الملك الحق ولا تعجل بالقرءان من قبل ان يقضي اليك وحيه وقل رب زدني علما', 16, 32, 128, 1, 4, 320, false, NULL),
    (2463, 'tanzil-uthmani-v1.1', 20, 115, 'وَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِىَ وَلَمْ نَجِدْ لَهُۥ عَزْمًا', '7fa0f29a9f456d0c79fd1c3c87a246caed82c1c77a13dd7a34922f8760495204', 'وَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِىَ وَلَمْ نَجِدْ لَهُۥ عَزْمًا', '7fa0f29a9f456d0c79fd1c3c87a246caed82c1c77a13dd7a34922f8760495204', '7fa0f29a9f456d0c79fd1c3c87a246caed82c1c77a13dd7a34922f8760495204', NULL, 'ولقد عهدنا الي ءادم من قبل فنسي ولم نجد له عزما', 16, 32, 128, 1, 4, 320, false, NULL),
    (2464, 'tanzil-uthmani-v1.1', 20, 116, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ', '8eced9b5e01058779d11e39225ad9c7ddc476418a3d3c61d7e16d258fb6058fe', 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ', '8eced9b5e01058779d11e39225ad9c7ddc476418a3d3c61d7e16d258fb6058fe', '8eced9b5e01058779d11e39225ad9c7ddc476418a3d3c61d7e16d258fb6058fe', NULL, 'واذ قلنا للملئكه اسجدوا لادم فسجدوا الا ابليس ابي', 16, 32, 128, 1, 4, 320, false, NULL),
    (2465, 'tanzil-uthmani-v1.1', 20, 117, 'فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ٱلْجَنَّةِ فَتَشْقَىٰٓ', '0edacd3c7adfbedab9ab519d2bbf7f1c993a61a69e44d40d8c408e0f609e6e56', 'فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ٱلْجَنَّةِ فَتَشْقَىٰٓ', '0edacd3c7adfbedab9ab519d2bbf7f1c993a61a69e44d40d8c408e0f609e6e56', '0edacd3c7adfbedab9ab519d2bbf7f1c993a61a69e44d40d8c408e0f609e6e56', NULL, 'فقلنا يادم ان هذا عدو لك ولزوجك فلا يخرجنكما من الجنه فتشقي', 16, 32, 128, 1, 4, 320, false, NULL),
    (2466, 'tanzil-uthmani-v1.1', 20, 118, 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ', '16dbe8d02022ba13795e1abbff99bd1f7b09e370f25031df783cc9ba3aed3e41', 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ', '16dbe8d02022ba13795e1abbff99bd1f7b09e370f25031df783cc9ba3aed3e41', '16dbe8d02022ba13795e1abbff99bd1f7b09e370f25031df783cc9ba3aed3e41', NULL, 'ان لك الا تجوع فيها ولا تعري', 16, 32, 128, 1, 4, 320, false, NULL),
    (2467, 'tanzil-uthmani-v1.1', 20, 119, 'وَأَنَّكَ لَا تَظْمَؤُا۟ فِيهَا وَلَا تَضْحَىٰ', '4a2694847c2f105128d24a045ae130e8e53a2012a906d934a667d84c25985375', 'وَأَنَّكَ لَا تَظْمَؤُا۟ فِيهَا وَلَا تَضْحَىٰ', '4a2694847c2f105128d24a045ae130e8e53a2012a906d934a667d84c25985375', '4a2694847c2f105128d24a045ae130e8e53a2012a906d934a667d84c25985375', NULL, 'وانك لا تظمؤا فيها ولا تضحي', 16, 32, 128, 1, 4, 320, false, NULL),
    (2468, 'tanzil-uthmani-v1.1', 20, 120, 'فَوَسْوَسَ إِلَيْهِ ٱلشَّيْطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلْخُلْدِ وَمُلْكٍ لَّا يَبْلَىٰ', 'c6c0cc0055298cb02a66f71438124aa5bd223bc7c322e8620bb0a64e1e3aee65', 'فَوَسْوَسَ إِلَيْهِ ٱلشَّيْطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلْخُلْدِ وَمُلْكٍ لَّا يَبْلَىٰ', 'c6c0cc0055298cb02a66f71438124aa5bd223bc7c322e8620bb0a64e1e3aee65', 'c6c0cc0055298cb02a66f71438124aa5bd223bc7c322e8620bb0a64e1e3aee65', NULL, 'فوسوس اليه الشيطن قال يادم هل ادلك علي شجره الخلد وملك لا يبلي', 16, 32, 128, 1, 4, 320, false, NULL),
    (2469, 'tanzil-uthmani-v1.1', 20, 121, 'فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ', '067b4abcd17c8dc801aa6c6d63427c053dd71748a7e83e2c89a3fa6d9fe8f395', 'فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ', '067b4abcd17c8dc801aa6c6d63427c053dd71748a7e83e2c89a3fa6d9fe8f395', '067b4abcd17c8dc801aa6c6d63427c053dd71748a7e83e2c89a3fa6d9fe8f395', NULL, 'فاكلا منها فبدت لهما سوءتهما وطفقا يخصفان عليهما من ورق الجنه وعصي ءادم ربه فغوي', 16, 32, 128, 1, 4, 320, false, NULL),
    (2470, 'tanzil-uthmani-v1.1', 20, 122, 'ثُمَّ ٱجْتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ', 'e3c7082f760023806b450d244e0c40410cb8b64bdba806a1ed29aad101dffdae', 'ثُمَّ ٱجْتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ', 'e3c7082f760023806b450d244e0c40410cb8b64bdba806a1ed29aad101dffdae', 'e3c7082f760023806b450d244e0c40410cb8b64bdba806a1ed29aad101dffdae', NULL, 'ثم اجتبه ربه فتاب عليه وهدي', 16, 32, 128, 1, 4, 320, false, NULL),
    (2471, 'tanzil-uthmani-v1.1', 20, 123, 'قَالَ ٱهْبِطَا مِنْهَا جَمِيعًۢا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَنِ ٱتَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ', 'd9a83c6b58a12dc8df46e67e19866933dfcceab17e3b19a5fa576913af80b975', 'قَالَ ٱهْبِطَا مِنْهَا جَمِيعًۢا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَنِ ٱتَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ', 'd9a83c6b58a12dc8df46e67e19866933dfcceab17e3b19a5fa576913af80b975', 'd9a83c6b58a12dc8df46e67e19866933dfcceab17e3b19a5fa576913af80b975', NULL, 'قال اهبطا منها جميعا بعضكم لبعض عدو فاما ياتينكم مني هدي فمن اتبع هداي فلا يضل ولا يشقي', 16, 32, 128, 1, 4, 320, false, NULL),
    (2472, 'tanzil-uthmani-v1.1', 20, 124, 'وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةً ضَنكًا وَنَحْشُرُهُۥ يَوْمَ ٱلْقِيَٰمَةِ أَعْمَىٰ', 'f7385f11a67c2f5f5c0563c197c65cf2f3d877b0925a8fc7bde6df4bfc392ab3', 'وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةً ضَنكًا وَنَحْشُرُهُۥ يَوْمَ ٱلْقِيَٰمَةِ أَعْمَىٰ', 'f7385f11a67c2f5f5c0563c197c65cf2f3d877b0925a8fc7bde6df4bfc392ab3', 'f7385f11a67c2f5f5c0563c197c65cf2f3d877b0925a8fc7bde6df4bfc392ab3', NULL, 'ومن اعرض عن ذكري فان له معيشه ضنكا ونحشره يوم القيمه اعمي', 16, 32, 128, 1, 4, 320, false, NULL),
    (2473, 'tanzil-uthmani-v1.1', 20, 125, 'قَالَ رَبِّ لِمَ حَشَرْتَنِىٓ أَعْمَىٰ وَقَدْ كُنتُ بَصِيرًا', '30f8d9a648a5032d13e1a9c43edaa06d76095020ec8504a03eca433b8a909ef2', 'قَالَ رَبِّ لِمَ حَشَرْتَنِىٓ أَعْمَىٰ وَقَدْ كُنتُ بَصِيرًا', '30f8d9a648a5032d13e1a9c43edaa06d76095020ec8504a03eca433b8a909ef2', '30f8d9a648a5032d13e1a9c43edaa06d76095020ec8504a03eca433b8a909ef2', NULL, 'قال رب لم حشرتني اعمي وقد كنت بصيرا', 16, 32, 128, 1, 4, 320, false, NULL),
    (2474, 'tanzil-uthmani-v1.1', 20, 126, 'قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَٰتُنَا فَنَسِيتَهَا وَكَذَٰلِكَ ٱلْيَوْمَ تُنسَىٰ', '01282ea3aa3206fb22f2419e13cc015825a8eb84ac366e201c002c3a8cf2c705', 'قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَٰتُنَا فَنَسِيتَهَا وَكَذَٰلِكَ ٱلْيَوْمَ تُنسَىٰ', '01282ea3aa3206fb22f2419e13cc015825a8eb84ac366e201c002c3a8cf2c705', '01282ea3aa3206fb22f2419e13cc015825a8eb84ac366e201c002c3a8cf2c705', NULL, 'قال كذلك اتتك ءايتنا فنسيتها وكذلك اليوم تنسي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2475, 'tanzil-uthmani-v1.1', 20, 127, 'وَكَذَٰلِكَ نَجْزِى مَنْ أَسْرَفَ وَلَمْ يُؤْمِنۢ بِـَٔايَٰتِ رَبِّهِۦ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَدُّ وَأَبْقَىٰٓ', 'dbca71a0124fcc941a9dd8ccc7c0395a0b42de4829bb24793954a566def71b69', 'وَكَذَٰلِكَ نَجْزِى مَنْ أَسْرَفَ وَلَمْ يُؤْمِنۢ بِـَٔايَٰتِ رَبِّهِۦ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَشَدُّ وَأَبْقَىٰٓ', 'dbca71a0124fcc941a9dd8ccc7c0395a0b42de4829bb24793954a566def71b69', 'dbca71a0124fcc941a9dd8ccc7c0395a0b42de4829bb24793954a566def71b69', NULL, 'وكذلك نجزي من اسرف ولم يؤمن بايت ربه ولعذاب الاخره اشد وابقي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2476, 'tanzil-uthmani-v1.1', 20, 128, 'أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', '03cea03014d2af3907d637273166a1ff02491e77101df9b1538ddfd4efc189a6', 'أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلنُّهَىٰ', '03cea03014d2af3907d637273166a1ff02491e77101df9b1538ddfd4efc189a6', '03cea03014d2af3907d637273166a1ff02491e77101df9b1538ddfd4efc189a6', NULL, 'افلم يهد لهم كم اهلكنا قبلهم من القرون يمشون في مسكنهم ان في ذلك لايت لاولي النهي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2477, 'tanzil-uthmani-v1.1', 20, 129, 'وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَامًا وَأَجَلٌ مُّسَمًّى', '471387415b60699bc6d5dafa6208117c165ad0186dd29a1ab733b72600544b75', 'وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَامًا وَأَجَلٌ مُّسَمًّى', '471387415b60699bc6d5dafa6208117c165ad0186dd29a1ab733b72600544b75', '471387415b60699bc6d5dafa6208117c165ad0186dd29a1ab733b72600544b75', NULL, 'ولولا كلمه سبقت من ربك لكان لزاما واجل مسمي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2478, 'tanzil-uthmani-v1.1', 20, 130, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ غُرُوبِهَا وَمِنْ ءَانَآئِ ٱلَّيْلِ فَسَبِّحْ وَأَطْرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرْضَىٰ', '7df94cb0cad8dd76d5bddb5082757fef22a68c660ec70bb5bfa78ca1c3d4e527', 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ غُرُوبِهَا وَمِنْ ءَانَآئِ ٱلَّيْلِ فَسَبِّحْ وَأَطْرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرْضَىٰ', '7df94cb0cad8dd76d5bddb5082757fef22a68c660ec70bb5bfa78ca1c3d4e527', '7df94cb0cad8dd76d5bddb5082757fef22a68c660ec70bb5bfa78ca1c3d4e527', NULL, 'فاصبر علي ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل غروبها ومن ءانائ اليل فسبح واطراف النهار لعلك ترضي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2479, 'tanzil-uthmani-v1.1', 20, 131, 'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ زَهْرَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا لِنَفْتِنَهُمْ فِيهِ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَىٰ', '7236d6c72406362c5e679b9f107e54693559eb7ef6b9be6704cab68911dde70f', 'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًا مِّنْهُمْ زَهْرَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا لِنَفْتِنَهُمْ فِيهِ وَرِزْقُ رَبِّكَ خَيْرٌ وَأَبْقَىٰ', '7236d6c72406362c5e679b9f107e54693559eb7ef6b9be6704cab68911dde70f', '7236d6c72406362c5e679b9f107e54693559eb7ef6b9be6704cab68911dde70f', NULL, 'ولا تمدن عينيك الي ما متعنا به ازوجا منهم زهره الحيوه الدنيا لنفتنهم فيه ورزق ربك خير وابقي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2480, 'tanzil-uthmani-v1.1', 20, 132, 'وَأْمُرْ أَهْلَكَ بِٱلصَّلَوٰةِ وَٱصْطَبِرْ عَلَيْهَا لَا نَسْـَٔلُكَ رِزْقًا نَّحْنُ نَرْزُقُكَ وَٱلْعَٰقِبَةُ لِلتَّقْوَىٰ', 'fca3a3746f569bf091db2ef03c5b216002a62e83a26bf6776f357d729479fe5f', 'وَأْمُرْ أَهْلَكَ بِٱلصَّلَوٰةِ وَٱصْطَبِرْ عَلَيْهَا لَا نَسْـَٔلُكَ رِزْقًا نَّحْنُ نَرْزُقُكَ وَٱلْعَٰقِبَةُ لِلتَّقْوَىٰ', 'fca3a3746f569bf091db2ef03c5b216002a62e83a26bf6776f357d729479fe5f', 'fca3a3746f569bf091db2ef03c5b216002a62e83a26bf6776f357d729479fe5f', NULL, 'وامر اهلك بالصلوه واصطبر عليها لا نسلك رزقا نحن نرزقك والعقبه للتقوي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2481, 'tanzil-uthmani-v1.1', 20, 133, 'وَقَالُوا۟ لَوْلَا يَأْتِينَا بِـَٔايَةٍ مِّن رَّبِّهِۦٓ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِى ٱلصُّحُفِ ٱلْأُولَىٰ', 'b8f9b4544020728e6612447673bee7f9b8f9762ae6a834afe4c5ee8d689cb807', 'وَقَالُوا۟ لَوْلَا يَأْتِينَا بِـَٔايَةٍ مِّن رَّبِّهِۦٓ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِى ٱلصُّحُفِ ٱلْأُولَىٰ', 'b8f9b4544020728e6612447673bee7f9b8f9762ae6a834afe4c5ee8d689cb807', 'b8f9b4544020728e6612447673bee7f9b8f9762ae6a834afe4c5ee8d689cb807', NULL, 'وقالوا لولا ياتينا بايه من ربه اولم تاتهم بينه ما في الصحف الاولي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2482, 'tanzil-uthmani-v1.1', 20, 134, 'وَلَوْ أَنَّآ أَهْلَكْنَٰهُم بِعَذَابٍ مِّن قَبْلِهِۦ لَقَالُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَىٰ', 'e3540744cddb8d3649c301eb12da3bd3b3aa547fc22b80c931f75bf87af78ea6', 'وَلَوْ أَنَّآ أَهْلَكْنَٰهُم بِعَذَابٍ مِّن قَبْلِهِۦ لَقَالُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَىٰ', 'e3540744cddb8d3649c301eb12da3bd3b3aa547fc22b80c931f75bf87af78ea6', 'e3540744cddb8d3649c301eb12da3bd3b3aa547fc22b80c931f75bf87af78ea6', NULL, 'ولو انا اهلكنهم بعذاب من قبله لقالوا ربنا لولا ارسلت الينا رسولا فنتبع ءايتك من قبل ان نذل ونخزي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2483, 'tanzil-uthmani-v1.1', 20, 135, 'قُلْ كُلٌّ مُّتَرَبِّصٌ فَتَرَبَّصُوا۟ فَسَتَعْلَمُونَ مَنْ أَصْحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِىِّ وَمَنِ ٱهْتَدَىٰ', '9ee2b254404df608883db63cd361dfbd4cf385b9a86d365315ebbeb12ce3d81b', 'قُلْ كُلٌّ مُّتَرَبِّصٌ فَتَرَبَّصُوا۟ فَسَتَعْلَمُونَ مَنْ أَصْحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِىِّ وَمَنِ ٱهْتَدَىٰ', '9ee2b254404df608883db63cd361dfbd4cf385b9a86d365315ebbeb12ce3d81b', '9ee2b254404df608883db63cd361dfbd4cf385b9a86d365315ebbeb12ce3d81b', NULL, 'قل كل متربص فتربصوا فستعلمون من اصحب الصرط السوي ومن اهتدي', 16, 32, 128, 1, 4, 321, false, NULL),
    (2484, 'tanzil-uthmani-v1.1', 21, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَةٍ مُّعْرِضُونَ', '466abeffb516e041222bb23c367fe87659b05576de8845a1a9d521f3fb226087', 'ٱقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَةٍ مُّعْرِضُونَ', '66ad2bb1e68b3e488fc1591e50af355b11eb5585fdc61c0c8f28a792cac82f2b', '66ad2bb1e68b3e488fc1591e50af355b11eb5585fdc61c0c8f28a792cac82f2b', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'اقترب للناس حسابهم وهم في غفله معرضون', 17, 33, 129, 1, 4, 322, false, NULL),
    (2485, 'tanzil-uthmani-v1.1', 21, 2, 'مَا يَأْتِيهِم مِّن ذِكْرٍ مِّن رَّبِّهِم مُّحْدَثٍ إِلَّا ٱسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ', 'f672eab6720b70215a3eef268a658544b70bd733a73ed7c135933f864850e59e', 'مَا يَأْتِيهِم مِّن ذِكْرٍ مِّن رَّبِّهِم مُّحْدَثٍ إِلَّا ٱسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ', 'f672eab6720b70215a3eef268a658544b70bd733a73ed7c135933f864850e59e', 'f672eab6720b70215a3eef268a658544b70bd733a73ed7c135933f864850e59e', NULL, 'ما ياتيهم من ذكر من ربهم محدث الا استمعوه وهم يلعبون', 17, 33, 129, 1, 4, 322, false, NULL),
    (2486, 'tanzil-uthmani-v1.1', 21, 3, 'لَاهِيَةً قُلُوبُهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَى ٱلَّذِينَ ظَلَمُوا۟ هَلْ هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ أَفَتَأْتُونَ ٱلسِّحْرَ وَأَنتُمْ تُبْصِرُونَ', '7c4fecd35d2a6d31933abb6f232c11349d3450c76011993dff84b62da846ecd7', 'لَاهِيَةً قُلُوبُهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَى ٱلَّذِينَ ظَلَمُوا۟ هَلْ هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ أَفَتَأْتُونَ ٱلسِّحْرَ وَأَنتُمْ تُبْصِرُونَ', '7c4fecd35d2a6d31933abb6f232c11349d3450c76011993dff84b62da846ecd7', '7c4fecd35d2a6d31933abb6f232c11349d3450c76011993dff84b62da846ecd7', NULL, 'لاهيه قلوبهم واسروا النجوي الذين ظلموا هل هذا الا بشر مثلكم افتاتون السحر وانتم تبصرون', 17, 33, 129, 1, 4, 322, false, NULL),
    (2487, 'tanzil-uthmani-v1.1', 21, 4, 'قَالَ رَبِّى يَعْلَمُ ٱلْقَوْلَ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '7bd605fe5e4f809ef4b520ba48ace6eec5fb9e8d9eedc29ff4932717fb488525', 'قَالَ رَبِّى يَعْلَمُ ٱلْقَوْلَ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '7bd605fe5e4f809ef4b520ba48ace6eec5fb9e8d9eedc29ff4932717fb488525', '7bd605fe5e4f809ef4b520ba48ace6eec5fb9e8d9eedc29ff4932717fb488525', NULL, 'قال ربي يعلم القول في السماء والارض وهو السميع العليم', 17, 33, 129, 1, 4, 322, false, NULL),
    (2488, 'tanzil-uthmani-v1.1', 21, 5, 'بَلْ قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍۭ بَلِ ٱفْتَرَىٰهُ بَلْ هُوَ شَاعِرٌ فَلْيَأْتِنَا بِـَٔايَةٍ كَمَآ أُرْسِلَ ٱلْأَوَّلُونَ', '0eb473c0aa33c7b49178859e0a4ec178a506a780cdc1aaad653e84e556122c17', 'بَلْ قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍۭ بَلِ ٱفْتَرَىٰهُ بَلْ هُوَ شَاعِرٌ فَلْيَأْتِنَا بِـَٔايَةٍ كَمَآ أُرْسِلَ ٱلْأَوَّلُونَ', '0eb473c0aa33c7b49178859e0a4ec178a506a780cdc1aaad653e84e556122c17', '0eb473c0aa33c7b49178859e0a4ec178a506a780cdc1aaad653e84e556122c17', NULL, 'بل قالوا اضغث احلم بل افتريه بل هو شاعر فلياتنا بايه كما ارسل الاولون', 17, 33, 129, 1, 4, 322, false, NULL),
    (2489, 'tanzil-uthmani-v1.1', 21, 6, 'مَآ ءَامَنَتْ قَبْلَهُم مِّن قَرْيَةٍ أَهْلَكْنَٰهَآ أَفَهُمْ يُؤْمِنُونَ', '8985e36634dab6c1dea0d6d57c5de1bef91f2cd4c459e1831710ea008b3f428b', 'مَآ ءَامَنَتْ قَبْلَهُم مِّن قَرْيَةٍ أَهْلَكْنَٰهَآ أَفَهُمْ يُؤْمِنُونَ', '8985e36634dab6c1dea0d6d57c5de1bef91f2cd4c459e1831710ea008b3f428b', '8985e36634dab6c1dea0d6d57c5de1bef91f2cd4c459e1831710ea008b3f428b', NULL, 'ما ءامنت قبلهم من قريه اهلكنها افهم يؤمنون', 17, 33, 129, 1, 4, 322, false, NULL),
    (2490, 'tanzil-uthmani-v1.1', 21, 7, 'وَمَآ أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', '230dea3434feb1dc911e5e32cd84e17726b3d63cac571149ac90aade9e1df619', 'وَمَآ أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا نُّوحِىٓ إِلَيْهِمْ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', '230dea3434feb1dc911e5e32cd84e17726b3d63cac571149ac90aade9e1df619', '230dea3434feb1dc911e5e32cd84e17726b3d63cac571149ac90aade9e1df619', NULL, 'وما ارسلنا قبلك الا رجالا نوحي اليهم فسلوا اهل الذكر ان كنتم لا تعلمون', 17, 33, 129, 1, 4, 322, false, NULL),
    (2491, 'tanzil-uthmani-v1.1', 21, 8, 'وَمَا جَعَلْنَٰهُمْ جَسَدًا لَّا يَأْكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَٰلِدِينَ', '665ac5c37a4c6facacf961eeddd1476568d07b1eb9b2584e8a72f3d26521b40e', 'وَمَا جَعَلْنَٰهُمْ جَسَدًا لَّا يَأْكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَٰلِدِينَ', '665ac5c37a4c6facacf961eeddd1476568d07b1eb9b2584e8a72f3d26521b40e', '665ac5c37a4c6facacf961eeddd1476568d07b1eb9b2584e8a72f3d26521b40e', NULL, 'وما جعلنهم جسدا لا ياكلون الطعام وما كانوا خلدين', 17, 33, 129, 1, 4, 322, false, NULL),
    (2492, 'tanzil-uthmani-v1.1', 21, 9, 'ثُمَّ صَدَقْنَٰهُمُ ٱلْوَعْدَ فَأَنجَيْنَٰهُمْ وَمَن نَّشَآءُ وَأَهْلَكْنَا ٱلْمُسْرِفِينَ', '5a76c54938d5ccf06a020122427ff93f96711e715d9ed885096c8df7168f321a', 'ثُمَّ صَدَقْنَٰهُمُ ٱلْوَعْدَ فَأَنجَيْنَٰهُمْ وَمَن نَّشَآءُ وَأَهْلَكْنَا ٱلْمُسْرِفِينَ', '5a76c54938d5ccf06a020122427ff93f96711e715d9ed885096c8df7168f321a', '5a76c54938d5ccf06a020122427ff93f96711e715d9ed885096c8df7168f321a', NULL, 'ثم صدقنهم الوعد فانجينهم ومن نشاء واهلكنا المسرفين', 17, 33, 129, 1, 4, 322, false, NULL),
    (2493, 'tanzil-uthmani-v1.1', 21, 10, 'لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَٰبًا فِيهِ ذِكْرُكُمْ أَفَلَا تَعْقِلُونَ', '777ad9d2f1beacc346e5a46d159c48d9aabc104aba95a01bbe3c7d9b219661d2', 'لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَٰبًا فِيهِ ذِكْرُكُمْ أَفَلَا تَعْقِلُونَ', '777ad9d2f1beacc346e5a46d159c48d9aabc104aba95a01bbe3c7d9b219661d2', '777ad9d2f1beacc346e5a46d159c48d9aabc104aba95a01bbe3c7d9b219661d2', NULL, 'لقد انزلنا اليكم كتبا فيه ذكركم افلا تعقلون', 17, 33, 129, 1, 4, 322, false, NULL),
    (2494, 'tanzil-uthmani-v1.1', 21, 11, 'وَكَمْ قَصَمْنَا مِن قَرْيَةٍ كَانَتْ ظَالِمَةً وَأَنشَأْنَا بَعْدَهَا قَوْمًا ءَاخَرِينَ', 'b0a01e6cf35512bdfe686e71e0e07eddc9cbb16e2ac7f04a81f54b4544bb511c', 'وَكَمْ قَصَمْنَا مِن قَرْيَةٍ كَانَتْ ظَالِمَةً وَأَنشَأْنَا بَعْدَهَا قَوْمًا ءَاخَرِينَ', 'b0a01e6cf35512bdfe686e71e0e07eddc9cbb16e2ac7f04a81f54b4544bb511c', 'b0a01e6cf35512bdfe686e71e0e07eddc9cbb16e2ac7f04a81f54b4544bb511c', NULL, 'وكم قصمنا من قريه كانت ظالمه وانشانا بعدها قوما ءاخرين', 17, 33, 129, 1, 4, 323, false, NULL),
    (2495, 'tanzil-uthmani-v1.1', 21, 12, 'فَلَمَّآ أَحَسُّوا۟ بَأْسَنَآ إِذَا هُم مِّنْهَا يَرْكُضُونَ', '00fd34b0d76015d47e67626a8adc4a04ca19386ee0fe8872447055cf3b2ce1c7', 'فَلَمَّآ أَحَسُّوا۟ بَأْسَنَآ إِذَا هُم مِّنْهَا يَرْكُضُونَ', '00fd34b0d76015d47e67626a8adc4a04ca19386ee0fe8872447055cf3b2ce1c7', '00fd34b0d76015d47e67626a8adc4a04ca19386ee0fe8872447055cf3b2ce1c7', NULL, 'فلما احسوا باسنا اذا هم منها يركضون', 17, 33, 129, 1, 4, 323, false, NULL),
    (2496, 'tanzil-uthmani-v1.1', 21, 13, 'لَا تَرْكُضُوا۟ وَٱرْجِعُوٓا۟ إِلَىٰ مَآ أُتْرِفْتُمْ فِيهِ وَمَسَٰكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ', '5d3406b772ab4d5d7911b60de64dad5ede386c7274ec6170b528d76efa661aef', 'لَا تَرْكُضُوا۟ وَٱرْجِعُوٓا۟ إِلَىٰ مَآ أُتْرِفْتُمْ فِيهِ وَمَسَٰكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ', '5d3406b772ab4d5d7911b60de64dad5ede386c7274ec6170b528d76efa661aef', '5d3406b772ab4d5d7911b60de64dad5ede386c7274ec6170b528d76efa661aef', NULL, 'لا تركضوا وارجعوا الي ما اترفتم فيه ومسكنكم لعلكم تسلون', 17, 33, 129, 1, 4, 323, false, NULL),
    (2497, 'tanzil-uthmani-v1.1', 21, 14, 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'f5ae7ea916555de033a3908e3ab536d9e3cb31cdd05e3762765961234dfdbbed', 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 'f5ae7ea916555de033a3908e3ab536d9e3cb31cdd05e3762765961234dfdbbed', 'f5ae7ea916555de033a3908e3ab536d9e3cb31cdd05e3762765961234dfdbbed', NULL, 'قالوا يويلنا انا كنا ظلمين', 17, 33, 129, 1, 4, 323, false, NULL),
    (2498, 'tanzil-uthmani-v1.1', 21, 15, 'فَمَا زَالَت تِّلْكَ دَعْوَىٰهُمْ حَتَّىٰ جَعَلْنَٰهُمْ حَصِيدًا خَٰمِدِينَ', 'a338f870a146ec633306430253e1c7d2658d8acbede80a3b1971af74c8464095', 'فَمَا زَالَت تِّلْكَ دَعْوَىٰهُمْ حَتَّىٰ جَعَلْنَٰهُمْ حَصِيدًا خَٰمِدِينَ', 'a338f870a146ec633306430253e1c7d2658d8acbede80a3b1971af74c8464095', 'a338f870a146ec633306430253e1c7d2658d8acbede80a3b1971af74c8464095', NULL, 'فما زالت تلك دعويهم حتي جعلنهم حصيدا خمدين', 17, 33, 129, 1, 4, 323, false, NULL),
    (2499, 'tanzil-uthmani-v1.1', 21, 16, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ', '2890336ebc057796dce2573d3b37093c57b690ee071ab75e966e946da2ba1506', 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ', '2890336ebc057796dce2573d3b37093c57b690ee071ab75e966e946da2ba1506', '2890336ebc057796dce2573d3b37093c57b690ee071ab75e966e946da2ba1506', NULL, 'وما خلقنا السماء والارض وما بينهما لعبين', 17, 33, 129, 1, 4, 323, false, NULL),
    (2500, 'tanzil-uthmani-v1.1', 21, 17, 'لَوْ أَرَدْنَآ أَن نَّتَّخِذَ لَهْوًا لَّٱتَّخَذْنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ', '73c1af6a5e8c15337b977ad5b55d90144655bc7cf828fc21102ee89861b34fc3', 'لَوْ أَرَدْنَآ أَن نَّتَّخِذَ لَهْوًا لَّٱتَّخَذْنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ', '73c1af6a5e8c15337b977ad5b55d90144655bc7cf828fc21102ee89861b34fc3', '73c1af6a5e8c15337b977ad5b55d90144655bc7cf828fc21102ee89861b34fc3', NULL, 'لو اردنا ان نتخذ لهوا لاتخذنه من لدنا ان كنا فعلين', 17, 33, 129, 1, 4, 323, false, NULL)
