    (2501, 'tanzil-uthmani-v1.1', 21, 18, 'بَلْ نَقْذِفُ بِٱلْحَقِّ عَلَى ٱلْبَٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقٌ وَلَكُمُ ٱلْوَيْلُ مِمَّا تَصِفُونَ', 'ca7c76ae462c82144e6227a8f5de3504809cfc10a0ac14ffd0070190d8b3441a', 'بَلْ نَقْذِفُ بِٱلْحَقِّ عَلَى ٱلْبَٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقٌ وَلَكُمُ ٱلْوَيْلُ مِمَّا تَصِفُونَ', 'ca7c76ae462c82144e6227a8f5de3504809cfc10a0ac14ffd0070190d8b3441a', 'ca7c76ae462c82144e6227a8f5de3504809cfc10a0ac14ffd0070190d8b3441a', NULL, 'بل نقذف بالحق علي البطل فيدمغه فاذا هو زاهق ولكم الويل مما تصفون', 17, 33, 129, 1, 4, 323, false, NULL),
    (2502, 'tanzil-uthmani-v1.1', 21, 19, 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَنْ عِندَهُۥ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَلَا يَسْتَحْسِرُونَ', '6b9cff85551b69a1f7357bb78e3083e0097638cc31aa34a8ed18e6cd135a1c93', 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَنْ عِندَهُۥ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَلَا يَسْتَحْسِرُونَ', '6b9cff85551b69a1f7357bb78e3083e0097638cc31aa34a8ed18e6cd135a1c93', '6b9cff85551b69a1f7357bb78e3083e0097638cc31aa34a8ed18e6cd135a1c93', NULL, 'وله من في السموت والارض ومن عنده لا يستكبرون عن عبادته ولا يستحسرون', 17, 33, 129, 1, 4, 323, false, NULL),
    (2503, 'tanzil-uthmani-v1.1', 21, 20, 'يُسَبِّحُونَ ٱلَّيْلَ وَٱلنَّهَارَ لَا يَفْتُرُونَ', '81b250cca1e9324b6923293b3c0e9d6e6ef9b0d8e391aa444e4401f6bed6c598', 'يُسَبِّحُونَ ٱلَّيْلَ وَٱلنَّهَارَ لَا يَفْتُرُونَ', '81b250cca1e9324b6923293b3c0e9d6e6ef9b0d8e391aa444e4401f6bed6c598', '81b250cca1e9324b6923293b3c0e9d6e6ef9b0d8e391aa444e4401f6bed6c598', NULL, 'يسبحون اليل والنهار لا يفترون', 17, 33, 129, 1, 4, 323, false, NULL),
    (2504, 'tanzil-uthmani-v1.1', 21, 21, 'أَمِ ٱتَّخَذُوٓا۟ ءَالِهَةً مِّنَ ٱلْأَرْضِ هُمْ يُنشِرُونَ', 'ebe374beb11e7e08591725c338c992f73843d4d3320d8f9379ed1561d7f9b537', 'أَمِ ٱتَّخَذُوٓا۟ ءَالِهَةً مِّنَ ٱلْأَرْضِ هُمْ يُنشِرُونَ', 'ebe374beb11e7e08591725c338c992f73843d4d3320d8f9379ed1561d7f9b537', 'ebe374beb11e7e08591725c338c992f73843d4d3320d8f9379ed1561d7f9b537', NULL, 'ام اتخذوا ءالهه من الارض هم ينشرون', 17, 33, 129, 1, 4, 323, false, NULL),
    (2505, 'tanzil-uthmani-v1.1', 21, 22, 'لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا فَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'd63198d8646c2eff61a90e75c40722ffb33dfe44580c3027cea5faa9d626ad09', 'لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا فَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'd63198d8646c2eff61a90e75c40722ffb33dfe44580c3027cea5faa9d626ad09', 'd63198d8646c2eff61a90e75c40722ffb33dfe44580c3027cea5faa9d626ad09', NULL, 'لو كان فيهما ءالهه الا الله لفسدتا فسبحن الله رب العرش عما يصفون', 17, 33, 129, 1, 4, 323, false, NULL),
    (2506, 'tanzil-uthmani-v1.1', 21, 23, 'لَا يُسْـَٔلُ عَمَّا يَفْعَلُ وَهُمْ يُسْـَٔلُونَ', '97dd6f221672b3c71b0e0c146d4fe66d8e4775ace5b4dc52ee5fc8d43821e06a', 'لَا يُسْـَٔلُ عَمَّا يَفْعَلُ وَهُمْ يُسْـَٔلُونَ', '97dd6f221672b3c71b0e0c146d4fe66d8e4775ace5b4dc52ee5fc8d43821e06a', '97dd6f221672b3c71b0e0c146d4fe66d8e4775ace5b4dc52ee5fc8d43821e06a', NULL, 'لا يسل عما يفعل وهم يسلون', 17, 33, 129, 1, 4, 323, false, NULL),
    (2507, 'tanzil-uthmani-v1.1', 21, 24, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ هَٰذَا ذِكْرُ مَن مَّعِىَ وَذِكْرُ مَن قَبْلِى بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ ٱلْحَقَّ فَهُم مُّعْرِضُونَ', '6e7a916455e16734c31777b815b60ca455c402b78a4c97ecaf5e60a1dd5cef2e', 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ هَٰذَا ذِكْرُ مَن مَّعِىَ وَذِكْرُ مَن قَبْلِى بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ ٱلْحَقَّ فَهُم مُّعْرِضُونَ', '6e7a916455e16734c31777b815b60ca455c402b78a4c97ecaf5e60a1dd5cef2e', '6e7a916455e16734c31777b815b60ca455c402b78a4c97ecaf5e60a1dd5cef2e', NULL, 'ام اتخذوا من دونه ءالهه قل هاتوا برهنكم هذا ذكر من معي وذكر من قبلي بل اكثرهم لا يعلمون الحق فهم معرضون', 17, 33, 129, 1, 4, 323, false, NULL),
    (2508, 'tanzil-uthmani-v1.1', 21, 25, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِىٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ', '7d38b6185b49832f5ed8c0b6e4fc304e6287b2b3e92d880f8de8138efb93dc28', 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِىٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ', '7d38b6185b49832f5ed8c0b6e4fc304e6287b2b3e92d880f8de8138efb93dc28', '7d38b6185b49832f5ed8c0b6e4fc304e6287b2b3e92d880f8de8138efb93dc28', NULL, 'وما ارسلنا من قبلك من رسول الا نوحي اليه انه لا اله الا انا فاعبدون', 17, 33, 129, 1, 4, 324, false, NULL),
    (2509, 'tanzil-uthmani-v1.1', 21, 26, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًا سُبْحَٰنَهُۥ بَلْ عِبَادٌ مُّكْرَمُونَ', 'e2d8ca6c35edefe68313f75f8bab07bd56cbab3bd087c4da2024470d71b7b1e3', 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًا سُبْحَٰنَهُۥ بَلْ عِبَادٌ مُّكْرَمُونَ', 'e2d8ca6c35edefe68313f75f8bab07bd56cbab3bd087c4da2024470d71b7b1e3', 'e2d8ca6c35edefe68313f75f8bab07bd56cbab3bd087c4da2024470d71b7b1e3', NULL, 'وقالوا اتخذ الرحمن ولدا سبحنه بل عباد مكرمون', 17, 33, 129, 1, 4, 324, false, NULL),
    (2510, 'tanzil-uthmani-v1.1', 21, 27, 'لَا يَسْبِقُونَهُۥ بِٱلْقَوْلِ وَهُم بِأَمْرِهِۦ يَعْمَلُونَ', 'ead83163a6d0262b26c9b945231b9ce48b593be1fc9f21468ab5600ac0801138', 'لَا يَسْبِقُونَهُۥ بِٱلْقَوْلِ وَهُم بِأَمْرِهِۦ يَعْمَلُونَ', 'ead83163a6d0262b26c9b945231b9ce48b593be1fc9f21468ab5600ac0801138', 'ead83163a6d0262b26c9b945231b9ce48b593be1fc9f21468ab5600ac0801138', NULL, 'لا يسبقونه بالقول وهم بامره يعملون', 17, 33, 129, 1, 4, 324, false, NULL),
    (2511, 'tanzil-uthmani-v1.1', 21, 28, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ٱرْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ', 'a8ed52a0db85c279c270f39947fd469f0cd2399b065dd69b8df62ae73c2fa45f', 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ٱرْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ', 'a8ed52a0db85c279c270f39947fd469f0cd2399b065dd69b8df62ae73c2fa45f', 'a8ed52a0db85c279c270f39947fd469f0cd2399b065dd69b8df62ae73c2fa45f', NULL, 'يعلم ما بين ايديهم وما خلفهم ولا يشفعون الا لمن ارتضي وهم من خشيته مشفقون', 17, 33, 129, 1, 4, 324, false, NULL),
    (2512, 'tanzil-uthmani-v1.1', 21, 29, 'وَمَن يَقُلْ مِنْهُمْ إِنِّىٓ إِلَٰهٌ مِّن دُونِهِۦ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', '188c26149fa2d03b3d27b89298e3ec6e9f3629b0ebd14054c62ab3a912e20a85', 'وَمَن يَقُلْ مِنْهُمْ إِنِّىٓ إِلَٰهٌ مِّن دُونِهِۦ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', '188c26149fa2d03b3d27b89298e3ec6e9f3629b0ebd14054c62ab3a912e20a85', '188c26149fa2d03b3d27b89298e3ec6e9f3629b0ebd14054c62ab3a912e20a85', NULL, 'ومن يقل منهم اني اله من دونه فذلك نجزيه جهنم كذلك نجزي الظلمين', 17, 33, 130, 1, 4, 324, false, NULL),
    (2513, 'tanzil-uthmani-v1.1', 21, 30, 'أَوَلَمْ يَرَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَٰهُمَا وَجَعَلْنَا مِنَ ٱلْمَآءِ كُلَّ شَىْءٍ حَىٍّ أَفَلَا يُؤْمِنُونَ', 'cf61cf8229c681ab1121188103f9e4c10227531a0b0d311250106cc8fdf25619', 'أَوَلَمْ يَرَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَٰهُمَا وَجَعَلْنَا مِنَ ٱلْمَآءِ كُلَّ شَىْءٍ حَىٍّ أَفَلَا يُؤْمِنُونَ', 'cf61cf8229c681ab1121188103f9e4c10227531a0b0d311250106cc8fdf25619', 'cf61cf8229c681ab1121188103f9e4c10227531a0b0d311250106cc8fdf25619', NULL, 'اولم ير الذين كفروا ان السموت والارض كانتا رتقا ففتقنهما وجعلنا من الماء كل شيء حي افلا يؤمنون', 17, 33, 130, 1, 4, 324, false, NULL),
    (2514, 'tanzil-uthmani-v1.1', 21, 31, 'وَجَعَلْنَا فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَاجًا سُبُلًا لَّعَلَّهُمْ يَهْتَدُونَ', '46f6fe486cabcdfb109a0d507468bf5b38378c208ee036367c08d19efaa5c4d3', 'وَجَعَلْنَا فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَاجًا سُبُلًا لَّعَلَّهُمْ يَهْتَدُونَ', '46f6fe486cabcdfb109a0d507468bf5b38378c208ee036367c08d19efaa5c4d3', '46f6fe486cabcdfb109a0d507468bf5b38378c208ee036367c08d19efaa5c4d3', NULL, 'وجعلنا في الارض روسي ان تميد بهم وجعلنا فيها فجاجا سبلا لعلهم يهتدون', 17, 33, 130, 1, 4, 324, false, NULL),
    (2515, 'tanzil-uthmani-v1.1', 21, 32, 'وَجَعَلْنَا ٱلسَّمَآءَ سَقْفًا مَّحْفُوظًا وَهُمْ عَنْ ءَايَٰتِهَا مُعْرِضُونَ', '7c4d3ee98d00306608db306822a099e85aac22deac49face4e3e5b3d44900bc2', 'وَجَعَلْنَا ٱلسَّمَآءَ سَقْفًا مَّحْفُوظًا وَهُمْ عَنْ ءَايَٰتِهَا مُعْرِضُونَ', '7c4d3ee98d00306608db306822a099e85aac22deac49face4e3e5b3d44900bc2', '7c4d3ee98d00306608db306822a099e85aac22deac49face4e3e5b3d44900bc2', NULL, 'وجعلنا السماء سقفا محفوظا وهم عن ءايتها معرضون', 17, 33, 130, 1, 4, 324, false, NULL),
    (2516, 'tanzil-uthmani-v1.1', 21, 33, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ فِى فَلَكٍ يَسْبَحُونَ', 'cf442e858ef8c1321099b0b02708c36144b66b82d74642aa879c7c672f168898', 'وَهُوَ ٱلَّذِى خَلَقَ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ فِى فَلَكٍ يَسْبَحُونَ', 'cf442e858ef8c1321099b0b02708c36144b66b82d74642aa879c7c672f168898', 'cf442e858ef8c1321099b0b02708c36144b66b82d74642aa879c7c672f168898', NULL, 'وهو الذي خلق اليل والنهار والشمس والقمر كل في فلك يسبحون', 17, 33, 130, 1, 4, 324, false, NULL),
    (2517, 'tanzil-uthmani-v1.1', 21, 34, 'وَمَا جَعَلْنَا لِبَشَرٍ مِّن قَبْلِكَ ٱلْخُلْدَ أَفَإِي۟ن مِّتَّ فَهُمُ ٱلْخَٰلِدُونَ', 'e196d9914b05b9987975fd54559639e9b2ac6ed984bad8e989ca3fe82141a6b4', 'وَمَا جَعَلْنَا لِبَشَرٍ مِّن قَبْلِكَ ٱلْخُلْدَ أَفَإِي۟ن مِّتَّ فَهُمُ ٱلْخَٰلِدُونَ', 'e196d9914b05b9987975fd54559639e9b2ac6ed984bad8e989ca3fe82141a6b4', 'e196d9914b05b9987975fd54559639e9b2ac6ed984bad8e989ca3fe82141a6b4', NULL, 'وما جعلنا لبشر من قبلك الخلد افاين مت فهم الخلدون', 17, 33, 130, 1, 4, 324, false, NULL),
    (2518, 'tanzil-uthmani-v1.1', 21, 35, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ وَنَبْلُوكُم بِٱلشَّرِّ وَٱلْخَيْرِ فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ', 'e2637ff98edfe29a34e979a29d024e575c1b35f70bee997811fb9855d56c5f32', 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ وَنَبْلُوكُم بِٱلشَّرِّ وَٱلْخَيْرِ فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ', 'e2637ff98edfe29a34e979a29d024e575c1b35f70bee997811fb9855d56c5f32', 'e2637ff98edfe29a34e979a29d024e575c1b35f70bee997811fb9855d56c5f32', NULL, 'كل نفس ذائقه الموت ونبلوكم بالشر والخير فتنه والينا ترجعون', 17, 33, 130, 1, 4, 324, false, NULL),
    (2519, 'tanzil-uthmani-v1.1', 21, 36, 'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓا۟ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى يَذْكُرُ ءَالِهَتَكُمْ وَهُم بِذِكْرِ ٱلرَّحْمَٰنِ هُمْ كَٰفِرُونَ', 'a31138517b9d1243719124832ef4577d18e97ece3330a8134fe9793a9de27189', 'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓا۟ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى يَذْكُرُ ءَالِهَتَكُمْ وَهُم بِذِكْرِ ٱلرَّحْمَٰنِ هُمْ كَٰفِرُونَ', 'a31138517b9d1243719124832ef4577d18e97ece3330a8134fe9793a9de27189', 'a31138517b9d1243719124832ef4577d18e97ece3330a8134fe9793a9de27189', NULL, 'واذا رءاك الذين كفروا ان يتخذونك الا هزوا اهذا الذي يذكر ءالهتكم وهم بذكر الرحمن هم كفرون', 17, 33, 130, 1, 4, 325, false, NULL),
    (2520, 'tanzil-uthmani-v1.1', 21, 37, 'خُلِقَ ٱلْإِنسَٰنُ مِنْ عَجَلٍ سَأُو۟رِيكُمْ ءَايَٰتِى فَلَا تَسْتَعْجِلُونِ', '1b521caee5269ce22d91d389992a670820bd44c9fdc848a9a355414c961f3f76', 'خُلِقَ ٱلْإِنسَٰنُ مِنْ عَجَلٍ سَأُو۟رِيكُمْ ءَايَٰتِى فَلَا تَسْتَعْجِلُونِ', '1b521caee5269ce22d91d389992a670820bd44c9fdc848a9a355414c961f3f76', '1b521caee5269ce22d91d389992a670820bd44c9fdc848a9a355414c961f3f76', NULL, 'خلق الانسن من عجل ساوريكم ءايتي فلا تستعجلون', 17, 33, 130, 1, 4, 325, false, NULL),
    (2521, 'tanzil-uthmani-v1.1', 21, 38, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', NULL, 'ويقولون متي هذا الوعد ان كنتم صدقين', 17, 33, 130, 1, 4, 325, false, NULL),
    (2522, 'tanzil-uthmani-v1.1', 21, 39, 'لَوْ يَعْلَمُ ٱلَّذِينَ كَفَرُوا۟ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ', '7d4b63c28ae51f574b3a1cb619caabc4fe7a2409064f3a4685910eaf3ff16226', 'لَوْ يَعْلَمُ ٱلَّذِينَ كَفَرُوا۟ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ', '7d4b63c28ae51f574b3a1cb619caabc4fe7a2409064f3a4685910eaf3ff16226', '7d4b63c28ae51f574b3a1cb619caabc4fe7a2409064f3a4685910eaf3ff16226', NULL, 'لو يعلم الذين كفروا حين لا يكفون عن وجوههم النار ولا عن ظهورهم ولا هم ينصرون', 17, 33, 130, 1, 4, 325, false, NULL),
    (2523, 'tanzil-uthmani-v1.1', 21, 40, 'بَلْ تَأْتِيهِم بَغْتَةً فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ', 'a92959b6e3c55e37fceddfcbe867a7ee26f91da5b40faebf3ee8133403f3b3c0', 'بَلْ تَأْتِيهِم بَغْتَةً فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ', 'a92959b6e3c55e37fceddfcbe867a7ee26f91da5b40faebf3ee8133403f3b3c0', 'a92959b6e3c55e37fceddfcbe867a7ee26f91da5b40faebf3ee8133403f3b3c0', NULL, 'بل تاتيهم بغته فتبهتهم فلا يستطيعون ردها ولا هم ينظرون', 17, 33, 130, 1, 4, 325, false, NULL),
    (2524, 'tanzil-uthmani-v1.1', 21, 41, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'c26ef020836af375cca527f6e1683337d66425da65ce922fe53f8e4f76866e36', 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'c26ef020836af375cca527f6e1683337d66425da65ce922fe53f8e4f76866e36', 'c26ef020836af375cca527f6e1683337d66425da65ce922fe53f8e4f76866e36', NULL, 'ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزءون', 17, 33, 130, 1, 4, 325, false, NULL),
    (2525, 'tanzil-uthmani-v1.1', 21, 42, 'قُلْ مَن يَكْلَؤُكُم بِٱلَّيْلِ وَٱلنَّهَارِ مِنَ ٱلرَّحْمَٰنِ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ', 'cc98bd87a7eda31877d9cde73192f7346ae6a74deaf5ec54d1b11407e459daf0', 'قُلْ مَن يَكْلَؤُكُم بِٱلَّيْلِ وَٱلنَّهَارِ مِنَ ٱلرَّحْمَٰنِ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ', 'cc98bd87a7eda31877d9cde73192f7346ae6a74deaf5ec54d1b11407e459daf0', 'cc98bd87a7eda31877d9cde73192f7346ae6a74deaf5ec54d1b11407e459daf0', NULL, 'قل من يكلؤكم باليل والنهار من الرحمن بل هم عن ذكر ربهم معرضون', 17, 33, 130, 1, 4, 325, false, NULL),
    (2526, 'tanzil-uthmani-v1.1', 21, 43, 'أَمْ لَهُمْ ءَالِهَةٌ تَمْنَعُهُم مِّن دُونِنَا لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ', '062347ce4d95a1476a0fd7b3920bec14d7debe979499683e9b5a3763e405bb89', 'أَمْ لَهُمْ ءَالِهَةٌ تَمْنَعُهُم مِّن دُونِنَا لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ', '062347ce4d95a1476a0fd7b3920bec14d7debe979499683e9b5a3763e405bb89', '062347ce4d95a1476a0fd7b3920bec14d7debe979499683e9b5a3763e405bb89', NULL, 'ام لهم ءالهه تمنعهم من دوننا لا يستطيعون نصر انفسهم ولا هم منا يصحبون', 17, 33, 130, 1, 4, 325, false, NULL),
    (2527, 'tanzil-uthmani-v1.1', 21, 44, 'بَلْ مَتَّعْنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ ٱلْعُمُرُ أَفَلَا يَرَوْنَ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَآ أَفَهُمُ ٱلْغَٰلِبُونَ', '21153126452b4e67c4fb095f7365300923139a6193f9bebdb81ddca047700958', 'بَلْ مَتَّعْنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ ٱلْعُمُرُ أَفَلَا يَرَوْنَ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَآ أَفَهُمُ ٱلْغَٰلِبُونَ', '21153126452b4e67c4fb095f7365300923139a6193f9bebdb81ddca047700958', '21153126452b4e67c4fb095f7365300923139a6193f9bebdb81ddca047700958', NULL, 'بل متعنا هؤلاء وءاباءهم حتي طال عليهم العمر افلا يرون انا ناتي الارض ننقصها من اطرافها افهم الغلبون', 17, 33, 130, 1, 4, 325, false, NULL),
    (2528, 'tanzil-uthmani-v1.1', 21, 45, 'قُلْ إِنَّمَآ أُنذِرُكُم بِٱلْوَحْىِ وَلَا يَسْمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ', 'c0a799e615f0d27f4c22b375c6896bfb6aa44806e689642c79798da9e3c349e3', 'قُلْ إِنَّمَآ أُنذِرُكُم بِٱلْوَحْىِ وَلَا يَسْمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ', 'c0a799e615f0d27f4c22b375c6896bfb6aa44806e689642c79798da9e3c349e3', 'c0a799e615f0d27f4c22b375c6896bfb6aa44806e689642c79798da9e3c349e3', NULL, 'قل انما انذركم بالوحي ولا يسمع الصم الدعاء اذا ما ينذرون', 17, 33, 130, 1, 4, 326, false, NULL),
    (2529, 'tanzil-uthmani-v1.1', 21, 46, 'وَلَئِن مَّسَّتْهُمْ نَفْحَةٌ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', '6816d67cb1b87f058111307e1cceab12eced59aaabf2fd7eadd721e66410ba19', 'وَلَئِن مَّسَّتْهُمْ نَفْحَةٌ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', '6816d67cb1b87f058111307e1cceab12eced59aaabf2fd7eadd721e66410ba19', '6816d67cb1b87f058111307e1cceab12eced59aaabf2fd7eadd721e66410ba19', NULL, 'ولئن مستهم نفحه من عذاب ربك ليقولن يويلنا انا كنا ظلمين', 17, 33, 130, 1, 4, 326, false, NULL),
    (2530, 'tanzil-uthmani-v1.1', 21, 47, 'وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَٰسِبِينَ', 'a4308620b3789cb8fe479b0b796791bffc6c7517336f760eacc3b6ea8fe73f96', 'وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَٰسِبِينَ', 'a4308620b3789cb8fe479b0b796791bffc6c7517336f760eacc3b6ea8fe73f96', 'a4308620b3789cb8fe479b0b796791bffc6c7517336f760eacc3b6ea8fe73f96', NULL, 'ونضع الموزين القسط ليوم القيمه فلا تظلم نفس شيا وان كان مثقال حبه من خردل اتينا بها وكفي بنا حسبين', 17, 33, 130, 1, 4, 326, false, NULL),
    (2531, 'tanzil-uthmani-v1.1', 21, 48, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ وَهَٰرُونَ ٱلْفُرْقَانَ وَضِيَآءً وَذِكْرًا لِّلْمُتَّقِينَ', 'd7d2fca6e0e88d970390af3a0224d5000ffdf15773cadf45dd9aae4b2fc7bb9b', 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ وَهَٰرُونَ ٱلْفُرْقَانَ وَضِيَآءً وَذِكْرًا لِّلْمُتَّقِينَ', 'd7d2fca6e0e88d970390af3a0224d5000ffdf15773cadf45dd9aae4b2fc7bb9b', 'd7d2fca6e0e88d970390af3a0224d5000ffdf15773cadf45dd9aae4b2fc7bb9b', NULL, 'ولقد ءاتينا موسي وهرون الفرقان وضياء وذكرا للمتقين', 17, 33, 130, 1, 4, 326, false, NULL),
    (2532, 'tanzil-uthmani-v1.1', 21, 49, 'ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشْفِقُونَ', 'ed868c9539359123bd7565349c1ca9ce0b14939a722d647c1d4bd7ee8d946113', 'ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشْفِقُونَ', 'ed868c9539359123bd7565349c1ca9ce0b14939a722d647c1d4bd7ee8d946113', 'ed868c9539359123bd7565349c1ca9ce0b14939a722d647c1d4bd7ee8d946113', NULL, 'الذين يخشون ربهم بالغيب وهم من الساعه مشفقون', 17, 33, 130, 1, 4, 326, false, NULL),
    (2533, 'tanzil-uthmani-v1.1', 21, 50, 'وَهَٰذَا ذِكْرٌ مُّبَارَكٌ أَنزَلْنَٰهُ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ', '6f717cba808ed596432deeed5302b378ebccceb51d90d65542b8132afc1b8685', 'وَهَٰذَا ذِكْرٌ مُّبَارَكٌ أَنزَلْنَٰهُ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ', '6f717cba808ed596432deeed5302b378ebccceb51d90d65542b8132afc1b8685', '6f717cba808ed596432deeed5302b378ebccceb51d90d65542b8132afc1b8685', NULL, 'وهذا ذكر مبارك انزلنه افانتم له منكرون', 17, 33, 130, 1, 4, 326, false, NULL),
    (2534, 'tanzil-uthmani-v1.1', 21, 51, 'وَلَقَدْ ءَاتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ وَكُنَّا بِهِۦ عَٰلِمِينَ', '8d41caee081b6130d1e6ca4cb3998b46b44da02fb29ddf96d55c1c7e83542da9', 'وَلَقَدْ ءَاتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ وَكُنَّا بِهِۦ عَٰلِمِينَ', '8d41caee081b6130d1e6ca4cb3998b46b44da02fb29ddf96d55c1c7e83542da9', '8d41caee081b6130d1e6ca4cb3998b46b44da02fb29ddf96d55c1c7e83542da9', NULL, 'ولقد ءاتينا ابرهيم رشده من قبل وكنا به علمين', 17, 33, 131, 1, 4, 326, false, NULL),
    (2535, 'tanzil-uthmani-v1.1', 21, 52, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِىٓ أَنتُمْ لَهَا عَٰكِفُونَ', '10ceaaf96057773559f3102c43f2a0c6e4688d65279a59c435e13e3cc4f184f7', 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِىٓ أَنتُمْ لَهَا عَٰكِفُونَ', '10ceaaf96057773559f3102c43f2a0c6e4688d65279a59c435e13e3cc4f184f7', '10ceaaf96057773559f3102c43f2a0c6e4688d65279a59c435e13e3cc4f184f7', NULL, 'اذ قال لابيه وقومه ما هذه التماثيل التي انتم لها عكفون', 17, 33, 131, 1, 4, 326, false, NULL),
    (2536, 'tanzil-uthmani-v1.1', 21, 53, 'قَالُوا۟ وَجَدْنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ', '3f38b9d3113b3be8b9cf3814075aa26203342b59aeb1af1e9340f47ceff4ee9a', 'قَالُوا۟ وَجَدْنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ', '3f38b9d3113b3be8b9cf3814075aa26203342b59aeb1af1e9340f47ceff4ee9a', '3f38b9d3113b3be8b9cf3814075aa26203342b59aeb1af1e9340f47ceff4ee9a', NULL, 'قالوا وجدنا ءاباءنا لها عبدين', 17, 33, 131, 1, 4, 326, false, NULL),
    (2537, 'tanzil-uthmani-v1.1', 21, 54, 'قَالَ لَقَدْ كُنتُمْ أَنتُمْ وَءَابَآؤُكُمْ فِى ضَلَٰلٍ مُّبِينٍ', '374dd1357cefa2494dacd85ea7210a3e4a0d79ad98c8bdeb30277d41b368d605', 'قَالَ لَقَدْ كُنتُمْ أَنتُمْ وَءَابَآؤُكُمْ فِى ضَلَٰلٍ مُّبِينٍ', '374dd1357cefa2494dacd85ea7210a3e4a0d79ad98c8bdeb30277d41b368d605', '374dd1357cefa2494dacd85ea7210a3e4a0d79ad98c8bdeb30277d41b368d605', NULL, 'قال لقد كنتم انتم وءاباؤكم في ضلل مبين', 17, 33, 131, 1, 4, 326, false, NULL),
    (2538, 'tanzil-uthmani-v1.1', 21, 55, 'قَالُوٓا۟ أَجِئْتَنَا بِٱلْحَقِّ أَمْ أَنتَ مِنَ ٱللَّٰعِبِينَ', '311827f48c55662874dabf06302b06f45a1ed0afbc12b2c54b6749d5daf2233a', 'قَالُوٓا۟ أَجِئْتَنَا بِٱلْحَقِّ أَمْ أَنتَ مِنَ ٱللَّٰعِبِينَ', '311827f48c55662874dabf06302b06f45a1ed0afbc12b2c54b6749d5daf2233a', '311827f48c55662874dabf06302b06f45a1ed0afbc12b2c54b6749d5daf2233a', NULL, 'قالوا اجئتنا بالحق ام انت من اللعبين', 17, 33, 131, 1, 4, 326, false, NULL),
    (2539, 'tanzil-uthmani-v1.1', 21, 56, 'قَالَ بَل رَّبُّكُمْ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلَّذِى فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ', '26d9130c6abba749b795ae08640ee9a781b19a60d0715806a1edd88f3aa1252a', 'قَالَ بَل رَّبُّكُمْ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلَّذِى فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ', '26d9130c6abba749b795ae08640ee9a781b19a60d0715806a1edd88f3aa1252a', '26d9130c6abba749b795ae08640ee9a781b19a60d0715806a1edd88f3aa1252a', NULL, 'قال بل ربكم رب السموت والارض الذي فطرهن وانا علي ذلكم من الشهدين', 17, 33, 131, 1, 4, 326, false, NULL),
    (2540, 'tanzil-uthmani-v1.1', 21, 57, 'وَتَٱللَّهِ لَأَكِيدَنَّ أَصْنَٰمَكُم بَعْدَ أَن تُوَلُّوا۟ مُدْبِرِينَ', '63b5ee3669003be73a00279d4dfcb12afb43f8c3fcdb3d9b4c4c86d35f6ef8a9', 'وَتَٱللَّهِ لَأَكِيدَنَّ أَصْنَٰمَكُم بَعْدَ أَن تُوَلُّوا۟ مُدْبِرِينَ', '63b5ee3669003be73a00279d4dfcb12afb43f8c3fcdb3d9b4c4c86d35f6ef8a9', '63b5ee3669003be73a00279d4dfcb12afb43f8c3fcdb3d9b4c4c86d35f6ef8a9', NULL, 'وتالله لاكيدن اصنمكم بعد ان تولوا مدبرين', 17, 33, 131, 1, 4, 326, false, NULL),
    (2541, 'tanzil-uthmani-v1.1', 21, 58, 'فَجَعَلَهُمْ جُذَٰذًا إِلَّا كَبِيرًا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ', '592ae54d700ce717482d1f263efb067ca59464296b407c558a739881afee78e5', 'فَجَعَلَهُمْ جُذَٰذًا إِلَّا كَبِيرًا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ', '592ae54d700ce717482d1f263efb067ca59464296b407c558a739881afee78e5', '592ae54d700ce717482d1f263efb067ca59464296b407c558a739881afee78e5', NULL, 'فجعلهم جذذا الا كبيرا لهم لعلهم اليه يرجعون', 17, 33, 131, 1, 4, 327, false, NULL),
    (2542, 'tanzil-uthmani-v1.1', 21, 59, 'قَالُوا۟ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ', 'd74a5cd10eccf756e864e786477480e24879924ae06807f356c963787aa79264', 'قَالُوا۟ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ', 'd74a5cd10eccf756e864e786477480e24879924ae06807f356c963787aa79264', 'd74a5cd10eccf756e864e786477480e24879924ae06807f356c963787aa79264', NULL, 'قالوا من فعل هذا بالهتنا انه لمن الظلمين', 17, 33, 131, 1, 4, 327, false, NULL),
    (2543, 'tanzil-uthmani-v1.1', 21, 60, 'قَالُوا۟ سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُۥٓ إِبْرَٰهِيمُ', '26e151d6992331bbbcdfcd7141bb11cdadbf1486fe7346c7fbb84acf95f481af', 'قَالُوا۟ سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُۥٓ إِبْرَٰهِيمُ', '26e151d6992331bbbcdfcd7141bb11cdadbf1486fe7346c7fbb84acf95f481af', '26e151d6992331bbbcdfcd7141bb11cdadbf1486fe7346c7fbb84acf95f481af', NULL, 'قالوا سمعنا فتي يذكرهم يقال له ابرهيم', 17, 33, 131, 1, 4, 327, false, NULL),
    (2544, 'tanzil-uthmani-v1.1', 21, 61, 'قَالُوا۟ فَأْتُوا۟ بِهِۦ عَلَىٰٓ أَعْيُنِ ٱلنَّاسِ لَعَلَّهُمْ يَشْهَدُونَ', '1f4a8d09ff711804cdfe0d08f346b59430f90c06868d700a1ae7f52ce751cd8d', 'قَالُوا۟ فَأْتُوا۟ بِهِۦ عَلَىٰٓ أَعْيُنِ ٱلنَّاسِ لَعَلَّهُمْ يَشْهَدُونَ', '1f4a8d09ff711804cdfe0d08f346b59430f90c06868d700a1ae7f52ce751cd8d', '1f4a8d09ff711804cdfe0d08f346b59430f90c06868d700a1ae7f52ce751cd8d', NULL, 'قالوا فاتوا به علي اعين الناس لعلهم يشهدون', 17, 33, 131, 1, 4, 327, false, NULL),
    (2545, 'tanzil-uthmani-v1.1', 21, 62, 'قَالُوٓا۟ ءَأَنتَ فَعَلْتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبْرَٰهِيمُ', '97730aad28a3017b30fb402982510e3634d7d7fafe72bedd53075007357cae01', 'قَالُوٓا۟ ءَأَنتَ فَعَلْتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبْرَٰهِيمُ', '97730aad28a3017b30fb402982510e3634d7d7fafe72bedd53075007357cae01', '97730aad28a3017b30fb402982510e3634d7d7fafe72bedd53075007357cae01', NULL, 'قالوا ءانت فعلت هذا بالهتنا يابرهيم', 17, 33, 131, 1, 4, 327, false, NULL),
    (2546, 'tanzil-uthmani-v1.1', 21, 63, 'قَالَ بَلْ فَعَلَهُۥ كَبِيرُهُمْ هَٰذَا فَسْـَٔلُوهُمْ إِن كَانُوا۟ يَنطِقُونَ', 'e5cbb6739a25fb040da4ca3aa12fda0b6d4497816bd913b306d87a68b62398c6', 'قَالَ بَلْ فَعَلَهُۥ كَبِيرُهُمْ هَٰذَا فَسْـَٔلُوهُمْ إِن كَانُوا۟ يَنطِقُونَ', 'e5cbb6739a25fb040da4ca3aa12fda0b6d4497816bd913b306d87a68b62398c6', 'e5cbb6739a25fb040da4ca3aa12fda0b6d4497816bd913b306d87a68b62398c6', NULL, 'قال بل فعله كبيرهم هذا فسلوهم ان كانوا ينطقون', 17, 33, 131, 1, 4, 327, false, NULL),
    (2547, 'tanzil-uthmani-v1.1', 21, 64, 'فَرَجَعُوٓا۟ إِلَىٰٓ أَنفُسِهِمْ فَقَالُوٓا۟ إِنَّكُمْ أَنتُمُ ٱلظَّٰلِمُونَ', '064438f51a35697a2a7d05308ff00f84448cda2213981ad04e25adaf659e7ffd', 'فَرَجَعُوٓا۟ إِلَىٰٓ أَنفُسِهِمْ فَقَالُوٓا۟ إِنَّكُمْ أَنتُمُ ٱلظَّٰلِمُونَ', '064438f51a35697a2a7d05308ff00f84448cda2213981ad04e25adaf659e7ffd', '064438f51a35697a2a7d05308ff00f84448cda2213981ad04e25adaf659e7ffd', NULL, 'فرجعوا الي انفسهم فقالوا انكم انتم الظلمون', 17, 33, 131, 1, 4, 327, false, NULL),
    (2548, 'tanzil-uthmani-v1.1', 21, 65, 'ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمْ لَقَدْ عَلِمْتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ', 'ef0ea793c7fa03f43d688db5094eb8c370ffc7bcc0e0727c0e731421bb90ad53', 'ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمْ لَقَدْ عَلِمْتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ', 'ef0ea793c7fa03f43d688db5094eb8c370ffc7bcc0e0727c0e731421bb90ad53', 'ef0ea793c7fa03f43d688db5094eb8c370ffc7bcc0e0727c0e731421bb90ad53', NULL, 'ثم نكسوا علي رءوسهم لقد علمت ما هؤلاء ينطقون', 17, 33, 131, 1, 4, 327, false, NULL),
    (2549, 'tanzil-uthmani-v1.1', 21, 66, 'قَالَ أَفَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمْ شَيْـًٔا وَلَا يَضُرُّكُمْ', 'f78cb21e59ab060aa07e1ac2c7304eeb17adb3d02564e753b470f86111ee8580', 'قَالَ أَفَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمْ شَيْـًٔا وَلَا يَضُرُّكُمْ', 'f78cb21e59ab060aa07e1ac2c7304eeb17adb3d02564e753b470f86111ee8580', 'f78cb21e59ab060aa07e1ac2c7304eeb17adb3d02564e753b470f86111ee8580', NULL, 'قال افتعبدون من دون الله ما لا ينفعكم شيا ولا يضركم', 17, 33, 131, 1, 4, 327, false, NULL),
    (2550, 'tanzil-uthmani-v1.1', 21, 67, 'أُفٍّ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَفَلَا تَعْقِلُونَ', '27a24d714fe9a9cb53a6178b4b1eafded1f6ec848b5a2ef995bf876db5ef865e', 'أُفٍّ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَفَلَا تَعْقِلُونَ', '27a24d714fe9a9cb53a6178b4b1eafded1f6ec848b5a2ef995bf876db5ef865e', '27a24d714fe9a9cb53a6178b4b1eafded1f6ec848b5a2ef995bf876db5ef865e', NULL, 'اف لكم ولما تعبدون من دون الله افلا تعقلون', 17, 33, 131, 1, 4, 327, false, NULL),
    (2551, 'tanzil-uthmani-v1.1', 21, 68, 'قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوٓا۟ ءَالِهَتَكُمْ إِن كُنتُمْ فَٰعِلِينَ', 'd93ebd9611071d6ed085025c504d3a9e6a2b6fef0513089500bffba39d2627a4', 'قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوٓا۟ ءَالِهَتَكُمْ إِن كُنتُمْ فَٰعِلِينَ', 'd93ebd9611071d6ed085025c504d3a9e6a2b6fef0513089500bffba39d2627a4', 'd93ebd9611071d6ed085025c504d3a9e6a2b6fef0513089500bffba39d2627a4', NULL, 'قالوا حرقوه وانصروا ءالهتكم ان كنتم فعلين', 17, 33, 131, 1, 4, 327, false, NULL),
    (2552, 'tanzil-uthmani-v1.1', 21, 69, 'قُلْنَا يَٰنَارُ كُونِى بَرْدًا وَسَلَٰمًا عَلَىٰٓ إِبْرَٰهِيمَ', 'afb6d4bf5c89b84384373c50e21ca0028243111f2ef16e355180e2ac9795c032', 'قُلْنَا يَٰنَارُ كُونِى بَرْدًا وَسَلَٰمًا عَلَىٰٓ إِبْرَٰهِيمَ', 'afb6d4bf5c89b84384373c50e21ca0028243111f2ef16e355180e2ac9795c032', 'afb6d4bf5c89b84384373c50e21ca0028243111f2ef16e355180e2ac9795c032', NULL, 'قلنا ينار كوني بردا وسلما علي ابرهيم', 17, 33, 131, 1, 4, 327, false, NULL),
    (2553, 'tanzil-uthmani-v1.1', 21, 70, 'وَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَٰهُمُ ٱلْأَخْسَرِينَ', 'c75dc6c9eb63b8eef79d0321556e1d540383bfc3e63d0f940ae8eca7c0a05070', 'وَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَٰهُمُ ٱلْأَخْسَرِينَ', 'c75dc6c9eb63b8eef79d0321556e1d540383bfc3e63d0f940ae8eca7c0a05070', 'c75dc6c9eb63b8eef79d0321556e1d540383bfc3e63d0f940ae8eca7c0a05070', NULL, 'وارادوا به كيدا فجعلنهم الاخسرين', 17, 33, 131, 1, 4, 327, false, NULL),
    (2554, 'tanzil-uthmani-v1.1', 21, 71, 'وَنَجَّيْنَٰهُ وَلُوطًا إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا لِلْعَٰلَمِينَ', 'b514931069a33caff719813ca70e4e0f5f440bc6747ff604d5f33cecaaf871ad', 'وَنَجَّيْنَٰهُ وَلُوطًا إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا لِلْعَٰلَمِينَ', 'b514931069a33caff719813ca70e4e0f5f440bc6747ff604d5f33cecaaf871ad', 'b514931069a33caff719813ca70e4e0f5f440bc6747ff604d5f33cecaaf871ad', NULL, 'ونجينه ولوطا الي الارض التي بركنا فيها للعلمين', 17, 33, 131, 1, 4, 327, false, NULL),
    (2555, 'tanzil-uthmani-v1.1', 21, 72, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ نَافِلَةً وَكُلًّا جَعَلْنَا صَٰلِحِينَ', '833ae3d7ee1219306433395780279952b0ffc9c1be649613bb1b6a1a474980ff', 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ نَافِلَةً وَكُلًّا جَعَلْنَا صَٰلِحِينَ', '833ae3d7ee1219306433395780279952b0ffc9c1be649613bb1b6a1a474980ff', '833ae3d7ee1219306433395780279952b0ffc9c1be649613bb1b6a1a474980ff', NULL, 'ووهبنا له اسحق ويعقوب نافله وكلا جعلنا صلحين', 17, 33, 131, 1, 4, 327, false, NULL),
    (2556, 'tanzil-uthmani-v1.1', 21, 73, 'وَجَعَلْنَٰهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَآ إِلَيْهِمْ فِعْلَ ٱلْخَيْرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِ وَكَانُوا۟ لَنَا عَٰبِدِينَ', 'e7c2d77c7db0d411355a50f9a9b9e2cb30f8a9cff903d810fe4a26a86dfa9147', 'وَجَعَلْنَٰهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَآ إِلَيْهِمْ فِعْلَ ٱلْخَيْرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِ وَكَانُوا۟ لَنَا عَٰبِدِينَ', 'e7c2d77c7db0d411355a50f9a9b9e2cb30f8a9cff903d810fe4a26a86dfa9147', 'e7c2d77c7db0d411355a50f9a9b9e2cb30f8a9cff903d810fe4a26a86dfa9147', NULL, 'وجعلنهم ائمه يهدون بامرنا واوحينا اليهم فعل الخيرت واقام الصلوه وايتاء الزكوه وكانوا لنا عبدين', 17, 33, 131, 1, 4, 328, false, NULL),
    (2557, 'tanzil-uthmani-v1.1', 21, 74, 'وَلُوطًا ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَنَجَّيْنَٰهُ مِنَ ٱلْقَرْيَةِ ٱلَّتِى كَانَت تَّعْمَلُ ٱلْخَبَٰٓئِثَ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَٰسِقِينَ', '22fd6414d2946286a8469c87d200478f44ad37ff713d49b558c59b36def3418d', 'وَلُوطًا ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَنَجَّيْنَٰهُ مِنَ ٱلْقَرْيَةِ ٱلَّتِى كَانَت تَّعْمَلُ ٱلْخَبَٰٓئِثَ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَٰسِقِينَ', '22fd6414d2946286a8469c87d200478f44ad37ff713d49b558c59b36def3418d', '22fd6414d2946286a8469c87d200478f44ad37ff713d49b558c59b36def3418d', NULL, 'ولوطا ءاتينه حكما وعلما ونجينه من القريه التي كانت تعمل الخبئث انهم كانوا قوم سوء فسقين', 17, 33, 131, 1, 4, 328, false, NULL),
    (2558, 'tanzil-uthmani-v1.1', 21, 75, 'وَأَدْخَلْنَٰهُ فِى رَحْمَتِنَآ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ', 'fd7231f3b58fefbf8da7fa8e70e9734fb9769c2edc8e434dd5a0f22560d94883', 'وَأَدْخَلْنَٰهُ فِى رَحْمَتِنَآ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ', 'fd7231f3b58fefbf8da7fa8e70e9734fb9769c2edc8e434dd5a0f22560d94883', 'fd7231f3b58fefbf8da7fa8e70e9734fb9769c2edc8e434dd5a0f22560d94883', NULL, 'وادخلنه في رحمتنا انه من الصلحين', 17, 33, 131, 1, 4, 328, false, NULL),
    (2559, 'tanzil-uthmani-v1.1', 21, 76, 'وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَٱسْتَجَبْنَا لَهُۥ فَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'd902e85dfae0da7b5dc423981b092989798f67212db51ff2d571ae8b32f94e01', 'وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَٱسْتَجَبْنَا لَهُۥ فَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 'd902e85dfae0da7b5dc423981b092989798f67212db51ff2d571ae8b32f94e01', 'd902e85dfae0da7b5dc423981b092989798f67212db51ff2d571ae8b32f94e01', NULL, 'ونوحا اذ نادي من قبل فاستجبنا له فنجينه واهله من الكرب العظيم', 17, 33, 131, 1, 4, 328, false, NULL),
    (2560, 'tanzil-uthmani-v1.1', 21, 77, 'وَنَصَرْنَٰهُ مِنَ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 'dde4f91228855a131869bbae86d43a7253cdf0c4d9c5f40c41def691de41c4a4', 'وَنَصَرْنَٰهُ مِنَ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 'dde4f91228855a131869bbae86d43a7253cdf0c4d9c5f40c41def691de41c4a4', 'dde4f91228855a131869bbae86d43a7253cdf0c4d9c5f40c41def691de41c4a4', NULL, 'ونصرنه من القوم الذين كذبوا بايتنا انهم كانوا قوم سوء فاغرقنهم اجمعين', 17, 33, 131, 1, 4, 328, false, NULL),
    (2561, 'tanzil-uthmani-v1.1', 21, 78, 'وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَانِ فِى ٱلْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ٱلْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ', 'be3d3e08f9d4238ad1a64927e5f7aceb4c29996d5514a71ff6705eee86acb2f7', 'وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَانِ فِى ٱلْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ٱلْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ', 'be3d3e08f9d4238ad1a64927e5f7aceb4c29996d5514a71ff6705eee86acb2f7', 'be3d3e08f9d4238ad1a64927e5f7aceb4c29996d5514a71ff6705eee86acb2f7', NULL, 'وداود وسليمن اذ يحكمان في الحرث اذ نفشت فيه غنم القوم وكنا لحكمهم شهدين', 17, 33, 131, 1, 4, 328, false, NULL),
    (2562, 'tanzil-uthmani-v1.1', 21, 79, 'فَفَهَّمْنَٰهَا سُلَيْمَٰنَ وَكُلًّا ءَاتَيْنَا حُكْمًا وَعِلْمًا وَسَخَّرْنَا مَعَ دَاوُۥدَ ٱلْجِبَالَ يُسَبِّحْنَ وَٱلطَّيْرَ وَكُنَّا فَٰعِلِينَ', '2c7cb0e7f2270b24f1fe72b2e34b575b85589a0298787c62812c2dcab5dab60e', 'فَفَهَّمْنَٰهَا سُلَيْمَٰنَ وَكُلًّا ءَاتَيْنَا حُكْمًا وَعِلْمًا وَسَخَّرْنَا مَعَ دَاوُۥدَ ٱلْجِبَالَ يُسَبِّحْنَ وَٱلطَّيْرَ وَكُنَّا فَٰعِلِينَ', '2c7cb0e7f2270b24f1fe72b2e34b575b85589a0298787c62812c2dcab5dab60e', '2c7cb0e7f2270b24f1fe72b2e34b575b85589a0298787c62812c2dcab5dab60e', NULL, 'ففهمنها سليمن وكلا ءاتينا حكما وعلما وسخرنا مع داود الجبال يسبحن والطير وكنا فعلين', 17, 33, 131, 1, 4, 328, false, NULL),
    (2563, 'tanzil-uthmani-v1.1', 21, 80, 'وَعَلَّمْنَٰهُ صَنْعَةَ لَبُوسٍ لَّكُمْ لِتُحْصِنَكُم مِّنۢ بَأْسِكُمْ فَهَلْ أَنتُمْ شَٰكِرُونَ', 'b56b9f0d13f6ed6628212d28e68e570f86eeaf086d7baf452b0ec1f1cec7e9da', 'وَعَلَّمْنَٰهُ صَنْعَةَ لَبُوسٍ لَّكُمْ لِتُحْصِنَكُم مِّنۢ بَأْسِكُمْ فَهَلْ أَنتُمْ شَٰكِرُونَ', 'b56b9f0d13f6ed6628212d28e68e570f86eeaf086d7baf452b0ec1f1cec7e9da', 'b56b9f0d13f6ed6628212d28e68e570f86eeaf086d7baf452b0ec1f1cec7e9da', NULL, 'وعلمنه صنعه لبوس لكم لتحصنكم من باسكم فهل انتم شكرون', 17, 33, 131, 1, 4, 328, false, NULL),
    (2564, 'tanzil-uthmani-v1.1', 21, 81, 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ عَاصِفَةً تَجْرِى بِأَمْرِهِۦٓ إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا وَكُنَّا بِكُلِّ شَىْءٍ عَٰلِمِينَ', '49b0f5243f2a1912dcfa9cef86fde63a735a44d2fb8beb6db4a253fb4f16d385', 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ عَاصِفَةً تَجْرِى بِأَمْرِهِۦٓ إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا وَكُنَّا بِكُلِّ شَىْءٍ عَٰلِمِينَ', '49b0f5243f2a1912dcfa9cef86fde63a735a44d2fb8beb6db4a253fb4f16d385', '49b0f5243f2a1912dcfa9cef86fde63a735a44d2fb8beb6db4a253fb4f16d385', NULL, 'ولسليمن الريح عاصفه تجري بامره الي الارض التي بركنا فيها وكنا بكل شيء علمين', 17, 33, 131, 1, 4, 328, false, NULL),
    (2565, 'tanzil-uthmani-v1.1', 21, 82, 'وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلًا دُونَ ذَٰلِكَ وَكُنَّا لَهُمْ حَٰفِظِينَ', 'b39d48409819325350baa72ac319c63da5d3bab2a8be737a23b1862005a5ee1d', 'وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلًا دُونَ ذَٰلِكَ وَكُنَّا لَهُمْ حَٰفِظِينَ', 'b39d48409819325350baa72ac319c63da5d3bab2a8be737a23b1862005a5ee1d', 'b39d48409819325350baa72ac319c63da5d3bab2a8be737a23b1862005a5ee1d', NULL, 'ومن الشيطين من يغوصون له ويعملون عملا دون ذلك وكنا لهم حفظين', 17, 33, 131, 1, 4, 329, false, NULL),
    (2566, 'tanzil-uthmani-v1.1', 21, 83, 'وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلضُّرُّ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'eb00790925ad4cdea4ae073df94346f85367dead0838e23a73746488df1188cc', 'وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلضُّرُّ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 'eb00790925ad4cdea4ae073df94346f85367dead0838e23a73746488df1188cc', 'eb00790925ad4cdea4ae073df94346f85367dead0838e23a73746488df1188cc', NULL, 'وايوب اذ نادي ربه اني مسني الضر وانت ارحم الرحمين', 17, 33, 132, 1, 4, 329, false, NULL),
    (2567, 'tanzil-uthmani-v1.1', 21, 84, 'فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ', '822b31742f8a2bc2ce7d36b91bc542be81037d59241da62385b6235b72681ac7', 'فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ', '822b31742f8a2bc2ce7d36b91bc542be81037d59241da62385b6235b72681ac7', '822b31742f8a2bc2ce7d36b91bc542be81037d59241da62385b6235b72681ac7', NULL, 'فاستجبنا له فكشفنا ما به من ضر وءاتينه اهله ومثلهم معهم رحمه من عندنا وذكري للعبدين', 17, 33, 132, 1, 4, 329, false, NULL),
    (2568, 'tanzil-uthmani-v1.1', 21, 85, 'وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ كُلٌّ مِّنَ ٱلصَّٰبِرِينَ', '4d8b973dc9cdfcd09529c3c6995ac489aeb73935852de4482bc0085dde8360e4', 'وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ كُلٌّ مِّنَ ٱلصَّٰبِرِينَ', '4d8b973dc9cdfcd09529c3c6995ac489aeb73935852de4482bc0085dde8360e4', '4d8b973dc9cdfcd09529c3c6995ac489aeb73935852de4482bc0085dde8360e4', NULL, 'واسمعيل وادريس وذا الكفل كل من الصبرين', 17, 33, 132, 1, 4, 329, false, NULL),
    (2569, 'tanzil-uthmani-v1.1', 21, 86, 'وَأَدْخَلْنَٰهُمْ فِى رَحْمَتِنَآ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ', '8068401eae4e15b5e445c269c4e7189f12cad29570964da66837b6f51b491d9c', 'وَأَدْخَلْنَٰهُمْ فِى رَحْمَتِنَآ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ', '8068401eae4e15b5e445c269c4e7189f12cad29570964da66837b6f51b491d9c', '8068401eae4e15b5e445c269c4e7189f12cad29570964da66837b6f51b491d9c', NULL, 'وادخلنهم في رحمتنا انهم من الصلحين', 17, 33, 132, 1, 4, 329, false, NULL),
    (2570, 'tanzil-uthmani-v1.1', 21, 87, 'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ', '2c80e9d22caa53a59f79ad1a0943705845c73ad84597464575948e01a3c8a497', 'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ', '2c80e9d22caa53a59f79ad1a0943705845c73ad84597464575948e01a3c8a497', '2c80e9d22caa53a59f79ad1a0943705845c73ad84597464575948e01a3c8a497', NULL, 'وذا النون اذ ذهب مغضبا فظن ان لن نقدر عليه فنادي في الظلمت ان لا اله الا انت سبحنك اني كنت من الظلمين', 17, 33, 132, 1, 4, 329, false, NULL),
    (2571, 'tanzil-uthmani-v1.1', 21, 88, 'فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ وَكَذَٰلِكَ نُـۨجِى ٱلْمُؤْمِنِينَ', 'a41f5dde37c3972bdbe676bc1922664bf656d024cf1966e41f6699677c74004f', 'فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ وَكَذَٰلِكَ نُـۨجِى ٱلْمُؤْمِنِينَ', 'a41f5dde37c3972bdbe676bc1922664bf656d024cf1966e41f6699677c74004f', 'a41f5dde37c3972bdbe676bc1922664bf656d024cf1966e41f6699677c74004f', NULL, 'فاستجبنا له ونجينه من الغم وكذلك نجي المؤمنين', 17, 33, 132, 1, 4, 329, false, NULL),
    (2572, 'tanzil-uthmani-v1.1', 21, 89, 'وَزَكَرِيَّآ إِذْ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِى فَرْدًا وَأَنتَ خَيْرُ ٱلْوَٰرِثِينَ', '4564447317797e1d9c32978443508ce05d12be47c96a1227e12681d2e9e543c0', 'وَزَكَرِيَّآ إِذْ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِى فَرْدًا وَأَنتَ خَيْرُ ٱلْوَٰرِثِينَ', '4564447317797e1d9c32978443508ce05d12be47c96a1227e12681d2e9e543c0', '4564447317797e1d9c32978443508ce05d12be47c96a1227e12681d2e9e543c0', NULL, 'وزكريا اذ نادي ربه رب لا تذرني فردا وانت خير الورثين', 17, 33, 132, 1, 4, 329, false, NULL),
    (2573, 'tanzil-uthmani-v1.1', 21, 90, 'فَٱسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ إِنَّهُمْ كَانُوا۟ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا وَكَانُوا۟ لَنَا خَٰشِعِينَ', '8f5dea94b8c7bdf77de5f36782629109b4fa3f92d52116828c1741cab7e219a6', 'فَٱسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ إِنَّهُمْ كَانُوا۟ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا وَكَانُوا۟ لَنَا خَٰشِعِينَ', '8f5dea94b8c7bdf77de5f36782629109b4fa3f92d52116828c1741cab7e219a6', '8f5dea94b8c7bdf77de5f36782629109b4fa3f92d52116828c1741cab7e219a6', NULL, 'فاستجبنا له ووهبنا له يحيي واصلحنا له زوجه انهم كانوا يسرعون في الخيرت ويدعوننا رغبا ورهبا وكانوا لنا خشعين', 17, 33, 132, 1, 4, 329, false, NULL),
    (2574, 'tanzil-uthmani-v1.1', 21, 91, 'وَٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَٰهَا وَٱبْنَهَآ ءَايَةً لِّلْعَٰلَمِينَ', 'c35866b45645b6b9fee75ebfdd93e2c58b503de7db8cdb95c7cf1779739dcd00', 'وَٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَٰهَا وَٱبْنَهَآ ءَايَةً لِّلْعَٰلَمِينَ', 'c35866b45645b6b9fee75ebfdd93e2c58b503de7db8cdb95c7cf1779739dcd00', 'c35866b45645b6b9fee75ebfdd93e2c58b503de7db8cdb95c7cf1779739dcd00', NULL, 'والتي احصنت فرجها فنفخنا فيها من روحنا وجعلنها وابنها ءايه للعلمين', 17, 33, 132, 1, 4, 330, false, NULL),
    (2575, 'tanzil-uthmani-v1.1', 21, 92, 'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ', 'b3f4b05490ea1981204d050bd5ab82b2cb1a5b60bf0d414a9d24a8e298677947', 'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ', 'b3f4b05490ea1981204d050bd5ab82b2cb1a5b60bf0d414a9d24a8e298677947', 'b3f4b05490ea1981204d050bd5ab82b2cb1a5b60bf0d414a9d24a8e298677947', NULL, 'ان هذه امتكم امه وحده وانا ربكم فاعبدون', 17, 33, 132, 1, 4, 330, false, NULL),
    (2576, 'tanzil-uthmani-v1.1', 21, 93, 'وَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ كُلٌّ إِلَيْنَا رَٰجِعُونَ', 'b566413c4c77dde1898b91ac94f5a78fa685faf88be10a814dd9adadd0d79956', 'وَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ كُلٌّ إِلَيْنَا رَٰجِعُونَ', 'b566413c4c77dde1898b91ac94f5a78fa685faf88be10a814dd9adadd0d79956', 'b566413c4c77dde1898b91ac94f5a78fa685faf88be10a814dd9adadd0d79956', NULL, 'وتقطعوا امرهم بينهم كل الينا رجعون', 17, 33, 132, 1, 4, 330, false, NULL),
    (2577, 'tanzil-uthmani-v1.1', 21, 94, 'فَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ', '1b7d2d5b0bc2a742c7ee9edb27100923adf092c4df9c249347b564f06ae21d5c', 'فَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ', '1b7d2d5b0bc2a742c7ee9edb27100923adf092c4df9c249347b564f06ae21d5c', '1b7d2d5b0bc2a742c7ee9edb27100923adf092c4df9c249347b564f06ae21d5c', NULL, 'فمن يعمل من الصلحت وهو مؤمن فلا كفران لسعيه وانا له كتبون', 17, 33, 132, 1, 4, 330, false, NULL),
    (2578, 'tanzil-uthmani-v1.1', 21, 95, 'وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ', '5d5d48ce3362b722516ec21d6c0c8405734c1ff9ec04e8119e7c0cab90bee5cc', 'وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ', '5d5d48ce3362b722516ec21d6c0c8405734c1ff9ec04e8119e7c0cab90bee5cc', '5d5d48ce3362b722516ec21d6c0c8405734c1ff9ec04e8119e7c0cab90bee5cc', NULL, 'وحرم علي قريه اهلكنها انهم لا يرجعون', 17, 33, 132, 1, 4, 330, false, NULL),
    (2579, 'tanzil-uthmani-v1.1', 21, 96, 'حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍ يَنسِلُونَ', '8ab68296851deccdf4369e4cd31cb3ae1f2b11b9ab8f9c1d383cc191f907cfa9', 'حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍ يَنسِلُونَ', '8ab68296851deccdf4369e4cd31cb3ae1f2b11b9ab8f9c1d383cc191f907cfa9', '8ab68296851deccdf4369e4cd31cb3ae1f2b11b9ab8f9c1d383cc191f907cfa9', NULL, 'حتي اذا فتحت ياجوج وماجوج وهم من كل حدب ينسلون', 17, 33, 132, 1, 4, 330, false, NULL),
    (2580, 'tanzil-uthmani-v1.1', 21, 97, 'وَٱقْتَرَبَ ٱلْوَعْدُ ٱلْحَقُّ فَإِذَا هِىَ شَٰخِصَةٌ أَبْصَٰرُ ٱلَّذِينَ كَفَرُوا۟ يَٰوَيْلَنَا قَدْ كُنَّا فِى غَفْلَةٍ مِّنْ هَٰذَا بَلْ كُنَّا ظَٰلِمِينَ', '30591142c55cfd8feebb674e0c0161678db4869c6eb5c15b6f6e098f6bc7c409', 'وَٱقْتَرَبَ ٱلْوَعْدُ ٱلْحَقُّ فَإِذَا هِىَ شَٰخِصَةٌ أَبْصَٰرُ ٱلَّذِينَ كَفَرُوا۟ يَٰوَيْلَنَا قَدْ كُنَّا فِى غَفْلَةٍ مِّنْ هَٰذَا بَلْ كُنَّا ظَٰلِمِينَ', '30591142c55cfd8feebb674e0c0161678db4869c6eb5c15b6f6e098f6bc7c409', '30591142c55cfd8feebb674e0c0161678db4869c6eb5c15b6f6e098f6bc7c409', NULL, 'واقترب الوعد الحق فاذا هي شخصه ابصر الذين كفروا يويلنا قد كنا في غفله من هذا بل كنا ظلمين', 17, 33, 132, 1, 4, 330, false, NULL),
    (2581, 'tanzil-uthmani-v1.1', 21, 98, 'إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ', 'e79dfc6d6f8b8eeb344cbe8268653e7151cf69b0b0802dcaaa15c49989f76fd4', 'إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ', 'e79dfc6d6f8b8eeb344cbe8268653e7151cf69b0b0802dcaaa15c49989f76fd4', 'e79dfc6d6f8b8eeb344cbe8268653e7151cf69b0b0802dcaaa15c49989f76fd4', NULL, 'انكم وما تعبدون من دون الله حصب جهنم انتم لها وردون', 17, 33, 132, 1, 4, 330, false, NULL),
    (2582, 'tanzil-uthmani-v1.1', 21, 99, 'لَوْ كَانَ هَٰٓؤُلَآءِ ءَالِهَةً مَّا وَرَدُوهَا وَكُلٌّ فِيهَا خَٰلِدُونَ', 'cf6b4c284ea67271bacdabf481385b8b32f3587c8fcc2909b1ca3001e71938c2', 'لَوْ كَانَ هَٰٓؤُلَآءِ ءَالِهَةً مَّا وَرَدُوهَا وَكُلٌّ فِيهَا خَٰلِدُونَ', 'cf6b4c284ea67271bacdabf481385b8b32f3587c8fcc2909b1ca3001e71938c2', 'cf6b4c284ea67271bacdabf481385b8b32f3587c8fcc2909b1ca3001e71938c2', NULL, 'لو كان هؤلاء ءالهه ما وردوها وكل فيها خلدون', 17, 33, 132, 1, 4, 330, false, NULL),
    (2583, 'tanzil-uthmani-v1.1', 21, 100, 'لَهُمْ فِيهَا زَفِيرٌ وَهُمْ فِيهَا لَا يَسْمَعُونَ', 'ed4058e44afcc7a470269e9178fee5a2c7160b14428ca596a38fbb0af9f28983', 'لَهُمْ فِيهَا زَفِيرٌ وَهُمْ فِيهَا لَا يَسْمَعُونَ', 'ed4058e44afcc7a470269e9178fee5a2c7160b14428ca596a38fbb0af9f28983', 'ed4058e44afcc7a470269e9178fee5a2c7160b14428ca596a38fbb0af9f28983', NULL, 'لهم فيها زفير وهم فيها لا يسمعون', 17, 33, 132, 1, 4, 330, false, NULL),
    (2584, 'tanzil-uthmani-v1.1', 21, 101, 'إِنَّ ٱلَّذِينَ سَبَقَتْ لَهُم مِّنَّا ٱلْحُسْنَىٰٓ أُو۟لَٰٓئِكَ عَنْهَا مُبْعَدُونَ', '9ed9ed64f22622cbb26d3711e445d06f4299b493cb60e8cbffbb7fe08b9fb1c2', 'إِنَّ ٱلَّذِينَ سَبَقَتْ لَهُم مِّنَّا ٱلْحُسْنَىٰٓ أُو۟لَٰٓئِكَ عَنْهَا مُبْعَدُونَ', '9ed9ed64f22622cbb26d3711e445d06f4299b493cb60e8cbffbb7fe08b9fb1c2', '9ed9ed64f22622cbb26d3711e445d06f4299b493cb60e8cbffbb7fe08b9fb1c2', NULL, 'ان الذين سبقت لهم منا الحسني اولئك عنها مبعدون', 17, 33, 132, 1, 4, 330, false, NULL),
    (2585, 'tanzil-uthmani-v1.1', 21, 102, 'لَا يَسْمَعُونَ حَسِيسَهَا وَهُمْ فِى مَا ٱشْتَهَتْ أَنفُسُهُمْ خَٰلِدُونَ', '5a512f24ba9b165a48b7ed4255fd5c62e1616d55782de09f023e6723e1597e0c', 'لَا يَسْمَعُونَ حَسِيسَهَا وَهُمْ فِى مَا ٱشْتَهَتْ أَنفُسُهُمْ خَٰلِدُونَ', '5a512f24ba9b165a48b7ed4255fd5c62e1616d55782de09f023e6723e1597e0c', '5a512f24ba9b165a48b7ed4255fd5c62e1616d55782de09f023e6723e1597e0c', NULL, 'لا يسمعون حسيسها وهم في ما اشتهت انفسهم خلدون', 17, 33, 132, 1, 4, 331, false, NULL),
    (2586, 'tanzil-uthmani-v1.1', 21, 103, 'لَا يَحْزُنُهُمُ ٱلْفَزَعُ ٱلْأَكْبَرُ وَتَتَلَقَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ هَٰذَا يَوْمُكُمُ ٱلَّذِى كُنتُمْ تُوعَدُونَ', '6f3f135116bbc1d151aa21e838d337c268ded0abbce4a7c3f605aaae2b594c89', 'لَا يَحْزُنُهُمُ ٱلْفَزَعُ ٱلْأَكْبَرُ وَتَتَلَقَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ هَٰذَا يَوْمُكُمُ ٱلَّذِى كُنتُمْ تُوعَدُونَ', '6f3f135116bbc1d151aa21e838d337c268ded0abbce4a7c3f605aaae2b594c89', '6f3f135116bbc1d151aa21e838d337c268ded0abbce4a7c3f605aaae2b594c89', NULL, 'لا يحزنهم الفزع الاكبر وتتلقيهم الملئكه هذا يومكم الذي كنتم توعدون', 17, 33, 132, 1, 4, 331, false, NULL),
    (2587, 'tanzil-uthmani-v1.1', 21, 104, 'يَوْمَ نَطْوِى ٱلسَّمَآءَ كَطَىِّ ٱلسِّجِلِّ لِلْكُتُبِ كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍ نُّعِيدُهُۥ وَعْدًا عَلَيْنَآ إِنَّا كُنَّا فَٰعِلِينَ', '2e9fe493cbc73778950cffa5c36fb3e11cf4a413d0fee0f4d31347c26d94ee70', 'يَوْمَ نَطْوِى ٱلسَّمَآءَ كَطَىِّ ٱلسِّجِلِّ لِلْكُتُبِ كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍ نُّعِيدُهُۥ وَعْدًا عَلَيْنَآ إِنَّا كُنَّا فَٰعِلِينَ', '2e9fe493cbc73778950cffa5c36fb3e11cf4a413d0fee0f4d31347c26d94ee70', '2e9fe493cbc73778950cffa5c36fb3e11cf4a413d0fee0f4d31347c26d94ee70', NULL, 'يوم نطوي السماء كطي السجل للكتب كما بدانا اول خلق نعيده وعدا علينا انا كنا فعلين', 17, 33, 132, 1, 4, 331, false, NULL),
    (2588, 'tanzil-uthmani-v1.1', 21, 105, 'وَلَقَدْ كَتَبْنَا فِى ٱلزَّبُورِ مِنۢ بَعْدِ ٱلذِّكْرِ أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّٰلِحُونَ', '5e4f4232836574a0ddedf0943a1517f70044bb48fd81c91b47d0134c1be574d2', 'وَلَقَدْ كَتَبْنَا فِى ٱلزَّبُورِ مِنۢ بَعْدِ ٱلذِّكْرِ أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّٰلِحُونَ', '5e4f4232836574a0ddedf0943a1517f70044bb48fd81c91b47d0134c1be574d2', '5e4f4232836574a0ddedf0943a1517f70044bb48fd81c91b47d0134c1be574d2', NULL, 'ولقد كتبنا في الزبور من بعد الذكر ان الارض يرثها عبادي الصلحون', 17, 33, 132, 1, 4, 331, false, NULL),
    (2589, 'tanzil-uthmani-v1.1', 21, 106, 'إِنَّ فِى هَٰذَا لَبَلَٰغًا لِّقَوْمٍ عَٰبِدِينَ', 'c811b5d3ddf1a757a5b647a62c538c0f70500ef2e56d655a909343aa125428e3', 'إِنَّ فِى هَٰذَا لَبَلَٰغًا لِّقَوْمٍ عَٰبِدِينَ', 'c811b5d3ddf1a757a5b647a62c538c0f70500ef2e56d655a909343aa125428e3', 'c811b5d3ddf1a757a5b647a62c538c0f70500ef2e56d655a909343aa125428e3', NULL, 'ان في هذا لبلغا لقوم عبدين', 17, 33, 132, 1, 4, 331, false, NULL),
    (2590, 'tanzil-uthmani-v1.1', 21, 107, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةً لِّلْعَٰلَمِينَ', '39da87ffde787191d7bf5a3aa0ff45c68e8a7ae0e825a9b7f8238f3e04b9c5f6', 'وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةً لِّلْعَٰلَمِينَ', '39da87ffde787191d7bf5a3aa0ff45c68e8a7ae0e825a9b7f8238f3e04b9c5f6', '39da87ffde787191d7bf5a3aa0ff45c68e8a7ae0e825a9b7f8238f3e04b9c5f6', NULL, 'وما ارسلنك الا رحمه للعلمين', 17, 33, 132, 1, 4, 331, false, NULL),
    (2591, 'tanzil-uthmani-v1.1', 21, 108, 'قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَهَلْ أَنتُم مُّسْلِمُونَ', '9e48ef4e0c0264f0cda1e210e76c0405e1fe515be50a7a2c9b728b82168958e5', 'قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَهَلْ أَنتُم مُّسْلِمُونَ', '9e48ef4e0c0264f0cda1e210e76c0405e1fe515be50a7a2c9b728b82168958e5', '9e48ef4e0c0264f0cda1e210e76c0405e1fe515be50a7a2c9b728b82168958e5', NULL, 'قل انما يوحي الي انما الهكم اله وحد فهل انتم مسلمون', 17, 33, 132, 1, 4, 331, false, NULL),
    (2592, 'tanzil-uthmani-v1.1', 21, 109, 'فَإِن تَوَلَّوْا۟ فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍ وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌ مَّا تُوعَدُونَ', 'f9d1a16a15a67d7ca1e8d97476292d8b49f97c837f06484581e00c8847d262d5', 'فَإِن تَوَلَّوْا۟ فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍ وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌ مَّا تُوعَدُونَ', 'f9d1a16a15a67d7ca1e8d97476292d8b49f97c837f06484581e00c8847d262d5', 'f9d1a16a15a67d7ca1e8d97476292d8b49f97c837f06484581e00c8847d262d5', NULL, 'فان تولوا فقل ءاذنتكم علي سواء وان ادري اقريب ام بعيد ما توعدون', 17, 33, 132, 1, 4, 331, false, NULL),
    (2593, 'tanzil-uthmani-v1.1', 21, 110, 'إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ مِنَ ٱلْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ', 'd9cf776c171ffb93b45c4c9ab7828b75dd64b30df52d9aff161f510a23b4364e', 'إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ مِنَ ٱلْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ', 'd9cf776c171ffb93b45c4c9ab7828b75dd64b30df52d9aff161f510a23b4364e', 'd9cf776c171ffb93b45c4c9ab7828b75dd64b30df52d9aff161f510a23b4364e', NULL, 'انه يعلم الجهر من القول ويعلم ما تكتمون', 17, 33, 132, 1, 4, 331, false, NULL),
    (2594, 'tanzil-uthmani-v1.1', 21, 111, 'وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'bb5fc5da58db2474fea70207c6cd0ca68c19383cd397dc48d96ea2073c2f85e5', 'وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍ', 'bb5fc5da58db2474fea70207c6cd0ca68c19383cd397dc48d96ea2073c2f85e5', 'bb5fc5da58db2474fea70207c6cd0ca68c19383cd397dc48d96ea2073c2f85e5', NULL, 'وان ادري لعله فتنه لكم ومتع الي حين', 17, 33, 132, 1, 4, 331, false, NULL),
    (2595, 'tanzil-uthmani-v1.1', 21, 112, 'قَٰلَ رَبِّ ٱحْكُم بِٱلْحَقِّ وَرَبُّنَا ٱلرَّحْمَٰنُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', '76d9908ea5ffdd301f95c58a11be1ed6006cdae183a7f040cc49631704335401', 'قَٰلَ رَبِّ ٱحْكُم بِٱلْحَقِّ وَرَبُّنَا ٱلرَّحْمَٰنُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', '76d9908ea5ffdd301f95c58a11be1ed6006cdae183a7f040cc49631704335401', '76d9908ea5ffdd301f95c58a11be1ed6006cdae183a7f040cc49631704335401', NULL, 'قل رب احكم بالحق وربنا الرحمن المستعان علي ما تصفون', 17, 33, 132, 1, 4, 331, false, NULL),
    (2596, 'tanzil-uthmani-v1.1', 22, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ إِنَّ زَلْزَلَةَ ٱلسَّاعَةِ شَىْءٌ عَظِيمٌ', '7e4622130eebf2fa2b4878b8b6657b160fee265beeee03a9a2d1a3ce9d46222d', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ إِنَّ زَلْزَلَةَ ٱلسَّاعَةِ شَىْءٌ عَظِيمٌ', '80aeafff35a13b3ba9c2c1cf5bc99df42986d9d27bbb7ced7a5c679bcb6c7836', '80aeafff35a13b3ba9c2c1cf5bc99df42986d9d27bbb7ced7a5c679bcb6c7836', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يايها الناس اتقوا ربكم ان زلزله الساعه شيء عظيم', 17, 34, 133, 1, 4, 332, false, NULL),
    (2597, 'tanzil-uthmani-v1.1', 22, 2, 'يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّآ أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌ', '33af568f8a73c82393de4b8fad7283d5810619058745309b466d56cb9ecba49e', 'يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّآ أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌ', '33af568f8a73c82393de4b8fad7283d5810619058745309b466d56cb9ecba49e', '33af568f8a73c82393de4b8fad7283d5810619058745309b466d56cb9ecba49e', NULL, 'يوم ترونها تذهل كل مرضعه عما ارضعت وتضع كل ذات حمل حملها وتري الناس سكري وما هم بسكري ولكن عذاب الله شديد', 17, 34, 133, 1, 4, 332, false, NULL),
    (2598, 'tanzil-uthmani-v1.1', 22, 3, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّبِعُ كُلَّ شَيْطَٰنٍ مَّرِيدٍ', '476bc4154b0a11bfacac357694f2a66fee4de381c4d19b9856b36f71b2e2ba6e', 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّبِعُ كُلَّ شَيْطَٰنٍ مَّرِيدٍ', '476bc4154b0a11bfacac357694f2a66fee4de381c4d19b9856b36f71b2e2ba6e', '476bc4154b0a11bfacac357694f2a66fee4de381c4d19b9856b36f71b2e2ba6e', NULL, 'ومن الناس من يجدل في الله بغير علم ويتبع كل شيطن مريد', 17, 34, 133, 1, 4, 332, false, NULL),
    (2599, 'tanzil-uthmani-v1.1', 22, 4, 'كُتِبَ عَلَيْهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهْدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', '99a7289ff90258d476347de9440f13a06a45859125923c03ca5eb907d68247c4', 'كُتِبَ عَلَيْهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهْدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', '99a7289ff90258d476347de9440f13a06a45859125923c03ca5eb907d68247c4', '99a7289ff90258d476347de9440f13a06a45859125923c03ca5eb907d68247c4', NULL, 'كتب عليه انه من تولاه فانه يضله ويهديه الي عذاب السعير', 17, 34, 133, 1, 4, 332, false, NULL),
    (2600, 'tanzil-uthmani-v1.1', 22, 5, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى رَيْبٍ مِّنَ ٱلْبَعْثِ فَإِنَّا خَلَقْنَٰكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ مِن مُّضْغَةٍ مُّخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ لِّنُبَيِّنَ لَكُمْ وَنُقِرُّ فِى ٱلْأَرْحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ نُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَيْلَا يَعْلَمَ مِنۢ بَعْدِ عِلْمٍ شَيْـًٔا وَتَرَى ٱلْأَرْضَ هَامِدَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ وَأَنۢبَتَتْ مِن كُلِّ زَوْجٍۭ بَهِيجٍ', 'dcbf7342cd1cd545258d2b2abeb49bfbe598f66ab27bee382be1588669b78db9', 'يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى رَيْبٍ مِّنَ ٱلْبَعْثِ فَإِنَّا خَلَقْنَٰكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ مِن مُّضْغَةٍ مُّخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ لِّنُبَيِّنَ لَكُمْ وَنُقِرُّ فِى ٱلْأَرْحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ نُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَيْلَا يَعْلَمَ مِنۢ بَعْدِ عِلْمٍ شَيْـًٔا وَتَرَى ٱلْأَرْضَ هَامِدَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ وَأَنۢبَتَتْ مِن كُلِّ زَوْجٍۭ بَهِيجٍ', 'dcbf7342cd1cd545258d2b2abeb49bfbe598f66ab27bee382be1588669b78db9', 'dcbf7342cd1cd545258d2b2abeb49bfbe598f66ab27bee382be1588669b78db9', NULL, 'يايها الناس ان كنتم في ريب من البعث فانا خلقنكم من تراب ثم من نطفه ثم من علقه ثم من مضغه مخلقه وغير مخلقه لنبين لكم ونقر في الارحام ما نشاء الي اجل مسمي ثم نخرجكم طفلا ثم لتبلغوا اشدكم ومنكم من يتوفي ومنكم من يرد الي ارذل العمر لكيلا يعلم من بعد علم شيا وتري الارض هامده فاذا انزلنا عليها الماء اهتزت وربت وانبتت من كل زوج بهيج', 17, 34, 133, 1, 4, 332, false, NULL),
    (2601, 'tanzil-uthmani-v1.1', 22, 6, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّهُۥ يُحْىِ ٱلْمَوْتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '5936b21fb44cec8ce8076aee0dcdded111eed86d0277ecf034ed7e15c54a91f4', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّهُۥ يُحْىِ ٱلْمَوْتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '5936b21fb44cec8ce8076aee0dcdded111eed86d0277ecf034ed7e15c54a91f4', '5936b21fb44cec8ce8076aee0dcdded111eed86d0277ecf034ed7e15c54a91f4', NULL, 'ذلك بان الله هو الحق وانه يحي الموتي وانه علي كل شيء قدير', 17, 34, 133, 1, 4, 333, false, NULL),
    (2602, 'tanzil-uthmani-v1.1', 22, 7, 'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٌ لَّا رَيْبَ فِيهَا وَأَنَّ ٱللَّهَ يَبْعَثُ مَن فِى ٱلْقُبُورِ', '2418bf48ebb90f9c2c4e3f34c546869b3c57774194160bbe926e424a13af232c', 'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٌ لَّا رَيْبَ فِيهَا وَأَنَّ ٱللَّهَ يَبْعَثُ مَن فِى ٱلْقُبُورِ', '2418bf48ebb90f9c2c4e3f34c546869b3c57774194160bbe926e424a13af232c', '2418bf48ebb90f9c2c4e3f34c546869b3c57774194160bbe926e424a13af232c', NULL, 'وان الساعه ءاتيه لا ريب فيها وان الله يبعث من في القبور', 17, 34, 133, 1, 4, 333, false, NULL),
    (2603, 'tanzil-uthmani-v1.1', 22, 8, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَٰبٍ مُّنِيرٍ', 'c837701c1756a2aa4fbbaccbb888d5ddbec7c37de785283fff99ca6a77e23558', 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَٰبٍ مُّنِيرٍ', 'c837701c1756a2aa4fbbaccbb888d5ddbec7c37de785283fff99ca6a77e23558', 'c837701c1756a2aa4fbbaccbb888d5ddbec7c37de785283fff99ca6a77e23558', NULL, 'ومن الناس من يجدل في الله بغير علم ولا هدي ولا كتب منير', 17, 34, 133, 1, 4, 333, false, NULL),
    (2604, 'tanzil-uthmani-v1.1', 22, 9, 'ثَانِىَ عِطْفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ لَهُۥ فِى ٱلدُّنْيَا خِزْىٌ وَنُذِيقُهُۥ يَوْمَ ٱلْقِيَٰمَةِ عَذَابَ ٱلْحَرِيقِ', '79048b9294c1ba2346b73dd06356799b6c57b820ea62b47423124b5a30357c87', 'ثَانِىَ عِطْفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ لَهُۥ فِى ٱلدُّنْيَا خِزْىٌ وَنُذِيقُهُۥ يَوْمَ ٱلْقِيَٰمَةِ عَذَابَ ٱلْحَرِيقِ', '79048b9294c1ba2346b73dd06356799b6c57b820ea62b47423124b5a30357c87', '79048b9294c1ba2346b73dd06356799b6c57b820ea62b47423124b5a30357c87', NULL, 'ثاني عطفه ليضل عن سبيل الله له في الدنيا خزي ونذيقه يوم القيمه عذاب الحريق', 17, 34, 133, 1, 4, 333, false, NULL),
    (2605, 'tanzil-uthmani-v1.1', 22, 10, 'ذَٰلِكَ بِمَا قَدَّمَتْ يَدَاكَ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍ لِّلْعَبِيدِ', '016066702c66a48444910be37f815d7d427ef0da87c84f06817dc6b696a65600', 'ذَٰلِكَ بِمَا قَدَّمَتْ يَدَاكَ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍ لِّلْعَبِيدِ', '016066702c66a48444910be37f815d7d427ef0da87c84f06817dc6b696a65600', '016066702c66a48444910be37f815d7d427ef0da87c84f06817dc6b696a65600', NULL, 'ذلك بما قدمت يداك وان الله ليس بظلم للعبيد', 17, 34, 133, 1, 4, 333, false, NULL),
    (2606, 'tanzil-uthmani-v1.1', 22, 11, 'وَمِنَ ٱلنَّاسِ مَن يَعْبُدُ ٱللَّهَ عَلَىٰ حَرْفٍ فَإِنْ أَصَابَهُۥ خَيْرٌ ٱطْمَأَنَّ بِهِۦ وَإِنْ أَصَابَتْهُ فِتْنَةٌ ٱنقَلَبَ عَلَىٰ وَجْهِهِۦ خَسِرَ ٱلدُّنْيَا وَٱلْـَٔاخِرَةَ ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', '64d4de65b118421346fc6b4a637068e6864716ee9a3b4f6a5946d6124e679016', 'وَمِنَ ٱلنَّاسِ مَن يَعْبُدُ ٱللَّهَ عَلَىٰ حَرْفٍ فَإِنْ أَصَابَهُۥ خَيْرٌ ٱطْمَأَنَّ بِهِۦ وَإِنْ أَصَابَتْهُ فِتْنَةٌ ٱنقَلَبَ عَلَىٰ وَجْهِهِۦ خَسِرَ ٱلدُّنْيَا وَٱلْـَٔاخِرَةَ ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', '64d4de65b118421346fc6b4a637068e6864716ee9a3b4f6a5946d6124e679016', '64d4de65b118421346fc6b4a637068e6864716ee9a3b4f6a5946d6124e679016', NULL, 'ومن الناس من يعبد الله علي حرف فان اصابه خير اطمان به وان اصابته فتنه انقلب علي وجهه خسر الدنيا والاخره ذلك هو الخسران المبين', 17, 34, 133, 1, 4, 333, false, NULL),
    (2607, 'tanzil-uthmani-v1.1', 22, 12, 'يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', '233c5a0a1deba364f105ed740dac15017f1270fd76dfc64436d081c0def386d5', 'يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', '233c5a0a1deba364f105ed740dac15017f1270fd76dfc64436d081c0def386d5', '233c5a0a1deba364f105ed740dac15017f1270fd76dfc64436d081c0def386d5', NULL, 'يدعوا من دون الله ما لا يضره وما لا ينفعه ذلك هو الضلل البعيد', 17, 34, 133, 1, 4, 333, false, NULL),
    (2608, 'tanzil-uthmani-v1.1', 22, 13, 'يَدْعُوا۟ لَمَن ضَرُّهُۥٓ أَقْرَبُ مِن نَّفْعِهِۦ لَبِئْسَ ٱلْمَوْلَىٰ وَلَبِئْسَ ٱلْعَشِيرُ', '2301d418b20f122214f0c961eefaa56e05aa1675d41959e397210dfe546acabb', 'يَدْعُوا۟ لَمَن ضَرُّهُۥٓ أَقْرَبُ مِن نَّفْعِهِۦ لَبِئْسَ ٱلْمَوْلَىٰ وَلَبِئْسَ ٱلْعَشِيرُ', '2301d418b20f122214f0c961eefaa56e05aa1675d41959e397210dfe546acabb', '2301d418b20f122214f0c961eefaa56e05aa1675d41959e397210dfe546acabb', NULL, 'يدعوا لمن ضره اقرب من نفعه لبئس المولي ولبئس العشير', 17, 34, 133, 1, 4, 333, false, NULL),
    (2609, 'tanzil-uthmani-v1.1', 22, 14, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ إِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', '156c0f257a2915d287ef6461343fb171a52b9bf59fea0b617bd2444c8f7eb94d', 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ إِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', '156c0f257a2915d287ef6461343fb171a52b9bf59fea0b617bd2444c8f7eb94d', '156c0f257a2915d287ef6461343fb171a52b9bf59fea0b617bd2444c8f7eb94d', NULL, 'ان الله يدخل الذين ءامنوا وعملوا الصلحت جنت تجري من تحتها الانهر ان الله يفعل ما يريد', 17, 34, 133, 1, 4, 333, false, NULL),
    (2610, 'tanzil-uthmani-v1.1', 22, 15, 'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لْيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُۥ مَا يَغِيظُ', 'd1c7f6deb615dc0d236e0782b0a1eac80c0ab1d69851750e9a36e785121e9baf', 'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لْيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُۥ مَا يَغِيظُ', 'd1c7f6deb615dc0d236e0782b0a1eac80c0ab1d69851750e9a36e785121e9baf', 'd1c7f6deb615dc0d236e0782b0a1eac80c0ab1d69851750e9a36e785121e9baf', NULL, 'من كان يظن ان لن ينصره الله في الدنيا والاخره فليمدد بسبب الي السماء ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ', 17, 34, 133, 1, 4, 333, false, NULL),
    (2611, 'tanzil-uthmani-v1.1', 22, 16, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ ءَايَٰتٍۭ بَيِّنَٰتٍ وَأَنَّ ٱللَّهَ يَهْدِى مَن يُرِيدُ', 'faeaed6e648a5f5653b797e29e4cdad7a12b46b852d1b7939dbea06c9c393c9a', 'وَكَذَٰلِكَ أَنزَلْنَٰهُ ءَايَٰتٍۭ بَيِّنَٰتٍ وَأَنَّ ٱللَّهَ يَهْدِى مَن يُرِيدُ', 'faeaed6e648a5f5653b797e29e4cdad7a12b46b852d1b7939dbea06c9c393c9a', 'faeaed6e648a5f5653b797e29e4cdad7a12b46b852d1b7939dbea06c9c393c9a', NULL, 'وكذلك انزلنه ءايت بينت وان الله يهدي من يريد', 17, 34, 133, 1, 4, 334, false, NULL),
    (2612, 'tanzil-uthmani-v1.1', 22, 17, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلْمَجُوسَ وَٱلَّذِينَ أَشْرَكُوٓا۟ إِنَّ ٱللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '8f7d218d84ec762a6c0472171523d91dcd212f55db4487eac8c451a45a4d96d2', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلْمَجُوسَ وَٱلَّذِينَ أَشْرَكُوٓا۟ إِنَّ ٱللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '8f7d218d84ec762a6c0472171523d91dcd212f55db4487eac8c451a45a4d96d2', '8f7d218d84ec762a6c0472171523d91dcd212f55db4487eac8c451a45a4d96d2', NULL, 'ان الذين ءامنوا والذين هادوا والصبين والنصري والمجوس والذين اشركوا ان الله يفصل بينهم يوم القيمه ان الله علي كل شيء شهيد', 17, 34, 133, 1, 4, 334, false, NULL),
    (2613, 'tanzil-uthmani-v1.1', 22, 18, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَسْجُدُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَٱلشَّمْسُ وَٱلْقَمَرُ وَٱلنُّجُومُ وَٱلْجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٌ مِّنَ ٱلنَّاسِ وَكَثِيرٌ حَقَّ عَلَيْهِ ٱلْعَذَابُ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكْرِمٍ إِنَّ ٱللَّهَ يَفْعَلُ مَا يَشَآءُ', 'c446beefa776389233854d9a3fc1320986ad51728c620379789718ea5088b110', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَسْجُدُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَٱلشَّمْسُ وَٱلْقَمَرُ وَٱلنُّجُومُ وَٱلْجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٌ مِّنَ ٱلنَّاسِ وَكَثِيرٌ حَقَّ عَلَيْهِ ٱلْعَذَابُ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكْرِمٍ إِنَّ ٱللَّهَ يَفْعَلُ مَا يَشَآءُ', 'c446beefa776389233854d9a3fc1320986ad51728c620379789718ea5088b110', 'c446beefa776389233854d9a3fc1320986ad51728c620379789718ea5088b110', NULL, 'الم تر ان الله يسجد له من في السموت ومن في الارض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس وكثير حق عليه العذاب ومن يهن الله فما له من مكرم ان الله يفعل ما يشاء', 17, 34, 133, 1, 4, 334, true, 'recommended'),
    (2614, 'tanzil-uthmani-v1.1', 22, 19, 'هَٰذَانِ خَصْمَانِ ٱخْتَصَمُوا۟ فِى رَبِّهِمْ فَٱلَّذِينَ كَفَرُوا۟ قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ ٱلْحَمِيمُ', '863db1a7f055d7177e5fb943e9013608934481d1b74053fc96735adf60f86fdb', 'هَٰذَانِ خَصْمَانِ ٱخْتَصَمُوا۟ فِى رَبِّهِمْ فَٱلَّذِينَ كَفَرُوا۟ قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ ٱلْحَمِيمُ', '863db1a7f055d7177e5fb943e9013608934481d1b74053fc96735adf60f86fdb', '863db1a7f055d7177e5fb943e9013608934481d1b74053fc96735adf60f86fdb', NULL, 'هذان خصمان اختصموا في ربهم فالذين كفروا قطعت لهم ثياب من نار يصب من فوق رءوسهم الحميم', 17, 34, 134, 1, 4, 334, false, NULL),
    (2615, 'tanzil-uthmani-v1.1', 22, 20, 'يُصْهَرُ بِهِۦ مَا فِى بُطُونِهِمْ وَٱلْجُلُودُ', '300a8c66aec8977f21a32a95192c63061050f21ee9cf5ac9580a5a73486d4ba1', 'يُصْهَرُ بِهِۦ مَا فِى بُطُونِهِمْ وَٱلْجُلُودُ', '300a8c66aec8977f21a32a95192c63061050f21ee9cf5ac9580a5a73486d4ba1', '300a8c66aec8977f21a32a95192c63061050f21ee9cf5ac9580a5a73486d4ba1', NULL, 'يصهر به ما في بطونهم والجلود', 17, 34, 134, 1, 4, 334, false, NULL),
    (2616, 'tanzil-uthmani-v1.1', 22, 21, 'وَلَهُم مَّقَٰمِعُ مِنْ حَدِيدٍ', 'f13155268b0f2a3fcbd5c9af6ef88d5313c66fdbfd601f0f9e927feb3f8758b2', 'وَلَهُم مَّقَٰمِعُ مِنْ حَدِيدٍ', 'f13155268b0f2a3fcbd5c9af6ef88d5313c66fdbfd601f0f9e927feb3f8758b2', 'f13155268b0f2a3fcbd5c9af6ef88d5313c66fdbfd601f0f9e927feb3f8758b2', NULL, 'ولهم مقمع من حديد', 17, 34, 134, 1, 4, 334, false, NULL),
    (2617, 'tanzil-uthmani-v1.1', 22, 22, 'كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَا مِنْ غَمٍّ أُعِيدُوا۟ فِيهَا وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'eb65cce50c64164672dcbddf1564d03407b7cae164964a7ca6cfc6c7013819bc', 'كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَا مِنْ غَمٍّ أُعِيدُوا۟ فِيهَا وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 'eb65cce50c64164672dcbddf1564d03407b7cae164964a7ca6cfc6c7013819bc', 'eb65cce50c64164672dcbddf1564d03407b7cae164964a7ca6cfc6c7013819bc', NULL, 'كلما ارادوا ان يخرجوا منها من غم اعيدوا فيها وذوقوا عذاب الحريق', 17, 34, 134, 1, 4, 334, false, NULL),
    (2618, 'tanzil-uthmani-v1.1', 22, 23, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', 'dc290737e3330d8a707e3fe0f39fb106b70e315610aee4779c34f678b72812cd', 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', 'dc290737e3330d8a707e3fe0f39fb106b70e315610aee4779c34f678b72812cd', 'dc290737e3330d8a707e3fe0f39fb106b70e315610aee4779c34f678b72812cd', NULL, 'ان الله يدخل الذين ءامنوا وعملوا الصلحت جنت تجري من تحتها الانهر يحلون فيها من اساور من ذهب ولؤلؤا ولباسهم فيها حرير', 17, 34, 134, 1, 4, 334, false, NULL),
    (2619, 'tanzil-uthmani-v1.1', 22, 24, 'وَهُدُوٓا۟ إِلَى ٱلطَّيِّبِ مِنَ ٱلْقَوْلِ وَهُدُوٓا۟ إِلَىٰ صِرَٰطِ ٱلْحَمِيدِ', 'd019fd7c8f78adda1e1948f0bfda9d73369d1a40b3d7bce337681d45186ff511', 'وَهُدُوٓا۟ إِلَى ٱلطَّيِّبِ مِنَ ٱلْقَوْلِ وَهُدُوٓا۟ إِلَىٰ صِرَٰطِ ٱلْحَمِيدِ', 'd019fd7c8f78adda1e1948f0bfda9d73369d1a40b3d7bce337681d45186ff511', 'd019fd7c8f78adda1e1948f0bfda9d73369d1a40b3d7bce337681d45186ff511', NULL, 'وهدوا الي الطيب من القول وهدوا الي صرط الحميد', 17, 34, 134, 1, 4, 335, false, NULL),
    (2620, 'tanzil-uthmani-v1.1', 22, 25, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلْمَسْجِدِ ٱلْحَرَامِ ٱلَّذِى جَعَلْنَٰهُ لِلنَّاسِ سَوَآءً ٱلْعَٰكِفُ فِيهِ وَٱلْبَادِ وَمَن يُرِدْ فِيهِ بِإِلْحَادٍۭ بِظُلْمٍ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍ', '7627307718427099e532c3c5db44c214f518f8df1093012e0a0109f994e9a00e', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلْمَسْجِدِ ٱلْحَرَامِ ٱلَّذِى جَعَلْنَٰهُ لِلنَّاسِ سَوَآءً ٱلْعَٰكِفُ فِيهِ وَٱلْبَادِ وَمَن يُرِدْ فِيهِ بِإِلْحَادٍۭ بِظُلْمٍ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍ', '7627307718427099e532c3c5db44c214f518f8df1093012e0a0109f994e9a00e', '7627307718427099e532c3c5db44c214f518f8df1093012e0a0109f994e9a00e', NULL, 'ان الذين كفروا ويصدون عن سبيل الله والمسجد الحرام الذي جعلنه للناس سواء العكف فيه والباد ومن يرد فيه بالحاد بظلم نذقه من عذاب اليم', 17, 34, 134, 1, 4, 335, false, NULL),
    (2621, 'tanzil-uthmani-v1.1', 22, 26, 'وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ ٱلْبَيْتِ أَن لَّا تُشْرِكْ بِى شَيْـًٔا وَطَهِّرْ بَيْتِىَ لِلطَّآئِفِينَ وَٱلْقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 'fca8aa2632dbb6e9167cb90affc5b4a33602c3e585c655410b11762a9d46476e', 'وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ ٱلْبَيْتِ أَن لَّا تُشْرِكْ بِى شَيْـًٔا وَطَهِّرْ بَيْتِىَ لِلطَّآئِفِينَ وَٱلْقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 'fca8aa2632dbb6e9167cb90affc5b4a33602c3e585c655410b11762a9d46476e', 'fca8aa2632dbb6e9167cb90affc5b4a33602c3e585c655410b11762a9d46476e', NULL, 'واذ بوانا لابرهيم مكان البيت ان لا تشرك بي شيا وطهر بيتي للطائفين والقائمين والركع السجود', 17, 34, 134, 1, 4, 335, false, NULL),
    (2622, 'tanzil-uthmani-v1.1', 22, 27, 'وَأَذِّن فِى ٱلنَّاسِ بِٱلْحَجِّ يَأْتُوكَ رِجَالًا وَعَلَىٰ كُلِّ ضَامِرٍ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍ', '26fa004dd7b9d0bde8940693eaba88abad35ad1a848ae12c44ff2b06921cf287', 'وَأَذِّن فِى ٱلنَّاسِ بِٱلْحَجِّ يَأْتُوكَ رِجَالًا وَعَلَىٰ كُلِّ ضَامِرٍ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍ', '26fa004dd7b9d0bde8940693eaba88abad35ad1a848ae12c44ff2b06921cf287', '26fa004dd7b9d0bde8940693eaba88abad35ad1a848ae12c44ff2b06921cf287', NULL, 'واذن في الناس بالحج ياتوك رجالا وعلي كل ضامر ياتين من كل فج عميق', 17, 34, 134, 1, 4, 335, false, NULL),
    (2623, 'tanzil-uthmani-v1.1', 22, 28, 'لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِىٓ أَيَّامٍ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْبَآئِسَ ٱلْفَقِيرَ', '1c739376a83d2875fbec4041c3c5541e20d0c0b6af3ed91f8d6c3c0469dae3d6', 'لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِىٓ أَيَّامٍ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْبَآئِسَ ٱلْفَقِيرَ', '1c739376a83d2875fbec4041c3c5541e20d0c0b6af3ed91f8d6c3c0469dae3d6', '1c739376a83d2875fbec4041c3c5541e20d0c0b6af3ed91f8d6c3c0469dae3d6', NULL, 'ليشهدوا منفع لهم ويذكروا اسم الله في ايام معلومت علي ما رزقهم من بهيمه الانعم فكلوا منها واطعموا البائس الفقير', 17, 34, 134, 1, 4, 335, false, NULL),
    (2624, 'tanzil-uthmani-v1.1', 22, 29, 'ثُمَّ لْيَقْضُوا۟ تَفَثَهُمْ وَلْيُوفُوا۟ نُذُورَهُمْ وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ', '3d1c532ded1aa83e00849675c5c6800658bcdaae30d7d7369805a36acfa45e5a', 'ثُمَّ لْيَقْضُوا۟ تَفَثَهُمْ وَلْيُوفُوا۟ نُذُورَهُمْ وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ', '3d1c532ded1aa83e00849675c5c6800658bcdaae30d7d7369805a36acfa45e5a', '3d1c532ded1aa83e00849675c5c6800658bcdaae30d7d7369805a36acfa45e5a', NULL, 'ثم ليقضوا تفثهم وليوفوا نذورهم وليطوفوا بالبيت العتيق', 17, 34, 134, 1, 4, 335, false, NULL),
    (2625, 'tanzil-uthmani-v1.1', 22, 30, 'ذَٰلِكَ وَمَن يُعَظِّمْ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيْرٌ لَّهُۥ عِندَ رَبِّهِۦ وَأُحِلَّتْ لَكُمُ ٱلْأَنْعَٰمُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ فَٱجْتَنِبُوا۟ ٱلرِّجْسَ مِنَ ٱلْأَوْثَٰنِ وَٱجْتَنِبُوا۟ قَوْلَ ٱلزُّورِ', 'e8b58d39847c872fe0c028bdedbe2d1d71fa7c1edafdd0d89bf0505b568d4bf0', 'ذَٰلِكَ وَمَن يُعَظِّمْ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيْرٌ لَّهُۥ عِندَ رَبِّهِۦ وَأُحِلَّتْ لَكُمُ ٱلْأَنْعَٰمُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ فَٱجْتَنِبُوا۟ ٱلرِّجْسَ مِنَ ٱلْأَوْثَٰنِ وَٱجْتَنِبُوا۟ قَوْلَ ٱلزُّورِ', 'e8b58d39847c872fe0c028bdedbe2d1d71fa7c1edafdd0d89bf0505b568d4bf0', 'e8b58d39847c872fe0c028bdedbe2d1d71fa7c1edafdd0d89bf0505b568d4bf0', NULL, 'ذلك ومن يعظم حرمت الله فهو خير له عند ربه واحلت لكم الانعم الا ما يتلي عليكم فاجتنبوا الرجس من الاوثن واجتنبوا قول الزور', 17, 34, 134, 1, 4, 335, false, NULL),
    (2626, 'tanzil-uthmani-v1.1', 22, 31, 'حُنَفَآءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِهِۦ وَمَن يُشْرِكْ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخْطَفُهُ ٱلطَّيْرُ أَوْ تَهْوِى بِهِ ٱلرِّيحُ فِى مَكَانٍ سَحِيقٍ', '76c1171fc27df5da927ead60f7a52153bb763e547b3546a3e15e6fdc4283e876', 'حُنَفَآءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِهِۦ وَمَن يُشْرِكْ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخْطَفُهُ ٱلطَّيْرُ أَوْ تَهْوِى بِهِ ٱلرِّيحُ فِى مَكَانٍ سَحِيقٍ', '76c1171fc27df5da927ead60f7a52153bb763e547b3546a3e15e6fdc4283e876', '76c1171fc27df5da927ead60f7a52153bb763e547b3546a3e15e6fdc4283e876', NULL, 'حنفاء لله غير مشركين به ومن يشرك بالله فكانما خر من السماء فتخطفه الطير او تهوي به الريح في مكان سحيق', 17, 34, 134, 1, 4, 336, false, NULL),
    (2627, 'tanzil-uthmani-v1.1', 22, 32, 'ذَٰلِكَ وَمَن يُعَظِّمْ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقْوَى ٱلْقُلُوبِ', '0d02bb93b47e01243e5f8a48ed0e0c87e5ff65333086f673af9791b8a37df2fb', 'ذَٰلِكَ وَمَن يُعَظِّمْ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقْوَى ٱلْقُلُوبِ', '0d02bb93b47e01243e5f8a48ed0e0c87e5ff65333086f673af9791b8a37df2fb', '0d02bb93b47e01243e5f8a48ed0e0c87e5ff65333086f673af9791b8a37df2fb', NULL, 'ذلك ومن يعظم شعئر الله فانها من تقوي القلوب', 17, 34, 134, 1, 4, 336, false, NULL),
    (2628, 'tanzil-uthmani-v1.1', 22, 33, 'لَكُمْ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ مَحِلُّهَآ إِلَى ٱلْبَيْتِ ٱلْعَتِيقِ', '1f4f716bf04191e42ba5f29ed4c80a9b10fa0250db34603912ca6ba25e067800', 'لَكُمْ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ مَحِلُّهَآ إِلَى ٱلْبَيْتِ ٱلْعَتِيقِ', '1f4f716bf04191e42ba5f29ed4c80a9b10fa0250db34603912ca6ba25e067800', '1f4f716bf04191e42ba5f29ed4c80a9b10fa0250db34603912ca6ba25e067800', NULL, 'لكم فيها منفع الي اجل مسمي ثم محلها الي البيت العتيق', 17, 34, 134, 1, 4, 336, false, NULL),
    (2629, 'tanzil-uthmani-v1.1', 22, 34, 'وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا لِّيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ فَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَلَهُۥٓ أَسْلِمُوا۟ وَبَشِّرِ ٱلْمُخْبِتِينَ', 'ea008ba5ab1ea05c6d67eb6763212f15b98564605df1e704bb0ed8309eef1c77', 'وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا لِّيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ فَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَلَهُۥٓ أَسْلِمُوا۟ وَبَشِّرِ ٱلْمُخْبِتِينَ', 'ea008ba5ab1ea05c6d67eb6763212f15b98564605df1e704bb0ed8309eef1c77', 'ea008ba5ab1ea05c6d67eb6763212f15b98564605df1e704bb0ed8309eef1c77', NULL, 'ولكل امه جعلنا منسكا ليذكروا اسم الله علي ما رزقهم من بهيمه الانعم فالهكم اله وحد فله اسلموا وبشر المخبتين', 17, 34, 134, 1, 4, 336, false, NULL),
    (2630, 'tanzil-uthmani-v1.1', 22, 35, 'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمْ وَٱلْمُقِيمِى ٱلصَّلَوٰةِ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', '4101ef1fbef5b741b697ba1fc0cf35b979088e68ae8f7977285d63f7cbbbcdf5', 'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمْ وَٱلْمُقِيمِى ٱلصَّلَوٰةِ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', '4101ef1fbef5b741b697ba1fc0cf35b979088e68ae8f7977285d63f7cbbbcdf5', '4101ef1fbef5b741b697ba1fc0cf35b979088e68ae8f7977285d63f7cbbbcdf5', NULL, 'الذين اذا ذكر الله وجلت قلوبهم والصبرين علي ما اصابهم والمقيمي الصلوه ومما رزقنهم ينفقون', 17, 34, 134, 1, 4, 336, false, NULL),
    (2631, 'tanzil-uthmani-v1.1', 22, 36, 'وَٱلْبُدْنَ جَعَلْنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمْ فِيهَا خَيْرٌ فَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهَا صَوَآفَّ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ كَذَٰلِكَ سَخَّرْنَٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'd0f7a79e38c110ab79880ba7c131b18ec6de6df0855f2d451acf9992ff91c998', 'وَٱلْبُدْنَ جَعَلْنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمْ فِيهَا خَيْرٌ فَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهَا صَوَآفَّ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ كَذَٰلِكَ سَخَّرْنَٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 'd0f7a79e38c110ab79880ba7c131b18ec6de6df0855f2d451acf9992ff91c998', 'd0f7a79e38c110ab79880ba7c131b18ec6de6df0855f2d451acf9992ff91c998', NULL, 'والبدن جعلنها لكم من شعئر الله لكم فيها خير فاذكروا اسم الله عليها صواف فاذا وجبت جنوبها فكلوا منها واطعموا القانع والمعتر كذلك سخرنها لكم لعلكم تشكرون', 17, 34, 134, 1, 4, 336, false, NULL),
    (2632, 'tanzil-uthmani-v1.1', 22, 37, 'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقْوَىٰ مِنكُمْ كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَبَشِّرِ ٱلْمُحْسِنِينَ', '813d54ff89dc31522fa9827f0c8ae4e7b9b233065558e66d8431e608aa317468', 'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقْوَىٰ مِنكُمْ كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَبَشِّرِ ٱلْمُحْسِنِينَ', '813d54ff89dc31522fa9827f0c8ae4e7b9b233065558e66d8431e608aa317468', '813d54ff89dc31522fa9827f0c8ae4e7b9b233065558e66d8431e608aa317468', NULL, 'لن ينال الله لحومها ولا دماؤها ولكن يناله التقوي منكم كذلك سخرها لكم لتكبروا الله علي ما هديكم وبشر المحسنين', 17, 34, 134, 1, 4, 336, false, NULL),
    (2633, 'tanzil-uthmani-v1.1', 22, 38, 'إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ', 'a7eb7d84ec4162c8ad2a49cb975278470e54235733174ae1f1545e8b3866e1b8', 'إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ', 'a7eb7d84ec4162c8ad2a49cb975278470e54235733174ae1f1545e8b3866e1b8', 'a7eb7d84ec4162c8ad2a49cb975278470e54235733174ae1f1545e8b3866e1b8', NULL, 'ان الله يدفع عن الذين ءامنوا ان الله لا يحب كل خوان كفور', 17, 34, 135, 1, 4, 336, false, NULL),
    (2634, 'tanzil-uthmani-v1.1', 22, 39, 'أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمْ ظُلِمُوا۟ وَإِنَّ ٱللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ', '17a0a6b880110a97a4f3038ffe7e8e478c9c504946f326530e306d57fad7b4c7', 'أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمْ ظُلِمُوا۟ وَإِنَّ ٱللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ', '17a0a6b880110a97a4f3038ffe7e8e478c9c504946f326530e306d57fad7b4c7', '17a0a6b880110a97a4f3038ffe7e8e478c9c504946f326530e306d57fad7b4c7', NULL, 'اذن للذين يقتلون بانهم ظلموا وان الله علي نصرهم لقدير', 17, 34, 135, 1, 4, 337, false, NULL),
    (2635, 'tanzil-uthmani-v1.1', 22, 40, 'ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِم بِغَيْرِ حَقٍّ إِلَّآ أَن يَقُولُوا۟ رَبُّنَا ٱللَّهُ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّهُدِّمَتْ صَوَٰمِعُ وَبِيَعٌ وَصَلَوَٰتٌ وَمَسَٰجِدُ يُذْكَرُ فِيهَا ٱسْمُ ٱللَّهِ كَثِيرًا وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', '7b304f63febc2f18da750541220dc8cbbb75cc0d8f6792ff7e3297c5b4e7f5e7', 'ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِم بِغَيْرِ حَقٍّ إِلَّآ أَن يَقُولُوا۟ رَبُّنَا ٱللَّهُ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّهُدِّمَتْ صَوَٰمِعُ وَبِيَعٌ وَصَلَوَٰتٌ وَمَسَٰجِدُ يُذْكَرُ فِيهَا ٱسْمُ ٱللَّهِ كَثِيرًا وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', '7b304f63febc2f18da750541220dc8cbbb75cc0d8f6792ff7e3297c5b4e7f5e7', '7b304f63febc2f18da750541220dc8cbbb75cc0d8f6792ff7e3297c5b4e7f5e7', NULL, 'الذين اخرجوا من ديرهم بغير حق الا ان يقولوا ربنا الله ولولا دفع الله الناس بعضهم ببعض لهدمت صومع وبيع وصلوت ومسجد يذكر فيها اسم الله كثيرا ولينصرن الله من ينصره ان الله لقوي عزيز', 17, 34, 135, 1, 4, 337, false, NULL),
    (2636, 'tanzil-uthmani-v1.1', 22, 41, 'ٱلَّذِينَ إِن مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلْمَعْرُوفِ وَنَهَوْا۟ عَنِ ٱلْمُنكَرِ وَلِلَّهِ عَٰقِبَةُ ٱلْأُمُورِ', 'ce085fe7d5a4d0481c0b105743e5710688afe148c6c3669b2e9137624a0a1672', 'ٱلَّذِينَ إِن مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلْمَعْرُوفِ وَنَهَوْا۟ عَنِ ٱلْمُنكَرِ وَلِلَّهِ عَٰقِبَةُ ٱلْأُمُورِ', 'ce085fe7d5a4d0481c0b105743e5710688afe148c6c3669b2e9137624a0a1672', 'ce085fe7d5a4d0481c0b105743e5710688afe148c6c3669b2e9137624a0a1672', NULL, 'الذين ان مكنهم في الارض اقاموا الصلوه وءاتوا الزكوه وامروا بالمعروف ونهوا عن المنكر ولله عقبه الامور', 17, 34, 135, 1, 4, 337, false, NULL),
    (2637, 'tanzil-uthmani-v1.1', 22, 42, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَثَمُودُ', '56c9ff65db34b9555994a796a76db11cb8dc2cf2b0b07f3f6c8466bbea5f26da', 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَثَمُودُ', '56c9ff65db34b9555994a796a76db11cb8dc2cf2b0b07f3f6c8466bbea5f26da', '56c9ff65db34b9555994a796a76db11cb8dc2cf2b0b07f3f6c8466bbea5f26da', NULL, 'وان يكذبوك فقد كذبت قبلهم قوم نوح وعاد وثمود', 17, 34, 135, 1, 4, 337, false, NULL),
    (2638, 'tanzil-uthmani-v1.1', 22, 43, 'وَقَوْمُ إِبْرَٰهِيمَ وَقَوْمُ لُوطٍ', 'e5c043e48249f0e1aee66ade0eec1fd97f38363ca4156ea6ac9d53b160ff03d1', 'وَقَوْمُ إِبْرَٰهِيمَ وَقَوْمُ لُوطٍ', 'e5c043e48249f0e1aee66ade0eec1fd97f38363ca4156ea6ac9d53b160ff03d1', 'e5c043e48249f0e1aee66ade0eec1fd97f38363ca4156ea6ac9d53b160ff03d1', NULL, 'وقوم ابرهيم وقوم لوط', 17, 34, 135, 1, 4, 337, false, NULL),
    (2639, 'tanzil-uthmani-v1.1', 22, 44, 'وَأَصْحَٰبُ مَدْيَنَ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَٰفِرِينَ ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ نَكِيرِ', '7577e76f761a9567f92b2426899146466566e47d1e01248212e7aa22e4150187', 'وَأَصْحَٰبُ مَدْيَنَ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَٰفِرِينَ ثُمَّ أَخَذْتُهُمْ فَكَيْفَ كَانَ نَكِيرِ', '7577e76f761a9567f92b2426899146466566e47d1e01248212e7aa22e4150187', '7577e76f761a9567f92b2426899146466566e47d1e01248212e7aa22e4150187', NULL, 'واصحب مدين وكذب موسي فامليت للكفرين ثم اخذتهم فكيف كان نكير', 17, 34, 135, 1, 4, 337, false, NULL),
    (2640, 'tanzil-uthmani-v1.1', 22, 45, 'فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَٰهَا وَهِىَ ظَالِمَةٌ فَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍ مُّعَطَّلَةٍ وَقَصْرٍ مَّشِيدٍ', 'a45043c5f61e5889f0ed16cf4de8fb323def48e3f398a3e61676ce4fe9618a61', 'فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَٰهَا وَهِىَ ظَالِمَةٌ فَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍ مُّعَطَّلَةٍ وَقَصْرٍ مَّشِيدٍ', 'a45043c5f61e5889f0ed16cf4de8fb323def48e3f398a3e61676ce4fe9618a61', 'a45043c5f61e5889f0ed16cf4de8fb323def48e3f398a3e61676ce4fe9618a61', NULL, 'فكاين من قريه اهلكنها وهي ظالمه فهي خاويه علي عروشها وبئر معطله وقصر مشيد', 17, 34, 135, 1, 4, 337, false, NULL),
    (2641, 'tanzil-uthmani-v1.1', 22, 46, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌ يَسْمَعُونَ بِهَا فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَٰرُ وَلَٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ', '430f99d5e3cd1a85b87985293dd2d34bc0662a093439c9d2c06fc3895f67c701', 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌ يَسْمَعُونَ بِهَا فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَٰرُ وَلَٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ', '430f99d5e3cd1a85b87985293dd2d34bc0662a093439c9d2c06fc3895f67c701', '430f99d5e3cd1a85b87985293dd2d34bc0662a093439c9d2c06fc3895f67c701', NULL, 'افلم يسيروا في الارض فتكون لهم قلوب يعقلون بها او ءاذان يسمعون بها فانها لا تعمي الابصر ولكن تعمي القلوب التي في الصدور', 17, 34, 135, 1, 4, 337, false, NULL),
    (2642, 'tanzil-uthmani-v1.1', 22, 47, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَن يُخْلِفَ ٱللَّهُ وَعْدَهُۥ وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍ مِّمَّا تَعُدُّونَ', 'd99768c9d271501ad381574f2932568000b25af71115d503791535525ca1932a', 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَن يُخْلِفَ ٱللَّهُ وَعْدَهُۥ وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍ مِّمَّا تَعُدُّونَ', 'd99768c9d271501ad381574f2932568000b25af71115d503791535525ca1932a', 'd99768c9d271501ad381574f2932568000b25af71115d503791535525ca1932a', NULL, 'ويستعجلونك بالعذاب ولن يخلف الله وعده وان يوما عند ربك كالف سنه مما تعدون', 17, 34, 135, 1, 4, 338, false, NULL),
    (2643, 'tanzil-uthmani-v1.1', 22, 48, 'وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِىَ ظَالِمَةٌ ثُمَّ أَخَذْتُهَا وَإِلَىَّ ٱلْمَصِيرُ', 'c6f10c412596c3a42da60a362b894800a819da39f7dd26f4f35febd81278aca4', 'وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِىَ ظَالِمَةٌ ثُمَّ أَخَذْتُهَا وَإِلَىَّ ٱلْمَصِيرُ', 'c6f10c412596c3a42da60a362b894800a819da39f7dd26f4f35febd81278aca4', 'c6f10c412596c3a42da60a362b894800a819da39f7dd26f4f35febd81278aca4', NULL, 'وكاين من قريه امليت لها وهي ظالمه ثم اخذتها والي المصير', 17, 34, 135, 1, 4, 338, false, NULL),
    (2644, 'tanzil-uthmani-v1.1', 22, 49, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمْ نَذِيرٌ مُّبِينٌ', 'ed10cdb404db8b5f97f3a993363fa37876f245c1654f4ead204bee304563a92e', 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمْ نَذِيرٌ مُّبِينٌ', 'ed10cdb404db8b5f97f3a993363fa37876f245c1654f4ead204bee304563a92e', 'ed10cdb404db8b5f97f3a993363fa37876f245c1654f4ead204bee304563a92e', NULL, 'قل يايها الناس انما انا لكم نذير مبين', 17, 34, 135, 1, 4, 338, false, NULL),
    (2645, 'tanzil-uthmani-v1.1', 22, 50, 'فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '12c36f0697ec99e6cdb209dd827a846a169916a4c96d51d241161682467f7717', 'فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '12c36f0697ec99e6cdb209dd827a846a169916a4c96d51d241161682467f7717', '12c36f0697ec99e6cdb209dd827a846a169916a4c96d51d241161682467f7717', NULL, 'فالذين ءامنوا وعملوا الصلحت لهم مغفره ورزق كريم', 17, 34, 135, 1, 4, 338, false, NULL),
    (2646, 'tanzil-uthmani-v1.1', 22, 51, 'وَٱلَّذِينَ سَعَوْا۟ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'c1ad17bb5c7a0714dcf8b5fea9545d95f0533c305299fceaa709e9d50de441ed', 'وَٱلَّذِينَ سَعَوْا۟ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'c1ad17bb5c7a0714dcf8b5fea9545d95f0533c305299fceaa709e9d50de441ed', 'c1ad17bb5c7a0714dcf8b5fea9545d95f0533c305299fceaa709e9d50de441ed', NULL, 'والذين سعوا في ءايتنا معجزين اولئك اصحب الجحيم', 17, 34, 135, 1, 4, 338, false, NULL),
    (2647, 'tanzil-uthmani-v1.1', 22, 52, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ وَلَا نَبِىٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلْقَى ٱلشَّيْطَٰنُ فِىٓ أُمْنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلْقِى ٱلشَّيْطَٰنُ ثُمَّ يُحْكِمُ ٱللَّهُ ءَايَٰتِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'd859f060e1ca53a3517208f9443f943943e8306ac0c0cb81cfce078a1dd069cb', 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ وَلَا نَبِىٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلْقَى ٱلشَّيْطَٰنُ فِىٓ أُمْنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلْقِى ٱلشَّيْطَٰنُ ثُمَّ يُحْكِمُ ٱللَّهُ ءَايَٰتِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'd859f060e1ca53a3517208f9443f943943e8306ac0c0cb81cfce078a1dd069cb', 'd859f060e1ca53a3517208f9443f943943e8306ac0c0cb81cfce078a1dd069cb', NULL, 'وما ارسلنا من قبلك من رسول ولا نبي الا اذا تمني القي الشيطن في امنيته فينسخ الله ما يلقي الشيطن ثم يحكم الله ءايته والله عليم حكيم', 17, 34, 135, 1, 4, 338, false, NULL),
    (2648, 'tanzil-uthmani-v1.1', 22, 53, 'لِّيَجْعَلَ مَا يُلْقِى ٱلشَّيْطَٰنُ فِتْنَةً لِّلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْقَاسِيَةِ قُلُوبُهُمْ وَإِنَّ ٱلظَّٰلِمِينَ لَفِى شِقَاقٍۭ بَعِيدٍ', 'c0d05cb773f7c537d45fdf2b06eee4e24adc9f15df9593736ab6680e52d94e73', 'لِّيَجْعَلَ مَا يُلْقِى ٱلشَّيْطَٰنُ فِتْنَةً لِّلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْقَاسِيَةِ قُلُوبُهُمْ وَإِنَّ ٱلظَّٰلِمِينَ لَفِى شِقَاقٍۭ بَعِيدٍ', 'c0d05cb773f7c537d45fdf2b06eee4e24adc9f15df9593736ab6680e52d94e73', 'c0d05cb773f7c537d45fdf2b06eee4e24adc9f15df9593736ab6680e52d94e73', NULL, 'ليجعل ما يلقي الشيطن فتنه للذين في قلوبهم مرض والقاسيه قلوبهم وان الظلمين لفي شقاق بعيد', 17, 34, 135, 1, 4, 338, false, NULL),
    (2649, 'tanzil-uthmani-v1.1', 22, 54, 'وَلِيَعْلَمَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّكَ فَيُؤْمِنُوا۟ بِهِۦ فَتُخْبِتَ لَهُۥ قُلُوبُهُمْ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓا۟ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'ca10cbfb8a78d9bdc408fecdedfffc2cf5269ff6db78d8b98267441f1faff85b', 'وَلِيَعْلَمَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّكَ فَيُؤْمِنُوا۟ بِهِۦ فَتُخْبِتَ لَهُۥ قُلُوبُهُمْ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓا۟ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'ca10cbfb8a78d9bdc408fecdedfffc2cf5269ff6db78d8b98267441f1faff85b', 'ca10cbfb8a78d9bdc408fecdedfffc2cf5269ff6db78d8b98267441f1faff85b', NULL, 'وليعلم الذين اوتوا العلم انه الحق من ربك فيؤمنوا به فتخبت له قلوبهم وان الله لهاد الذين ءامنوا الي صرط مستقيم', 17, 34, 135, 1, 4, 338, false, NULL),
    (2650, 'tanzil-uthmani-v1.1', 22, 55, 'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ فِى مِرْيَةٍ مِّنْهُ حَتَّىٰ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ', '9027de6638dad05682f8780d3768a29465ff237ee813e43558c71d3959d1d5a0', 'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ فِى مِرْيَةٍ مِّنْهُ حَتَّىٰ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ', '9027de6638dad05682f8780d3768a29465ff237ee813e43558c71d3959d1d5a0', '9027de6638dad05682f8780d3768a29465ff237ee813e43558c71d3959d1d5a0', NULL, 'ولا يزال الذين كفروا في مريه منه حتي تاتيهم الساعه بغته او ياتيهم عذاب يوم عقيم', 17, 34, 135, 1, 4, 338, false, NULL),
    (2651, 'tanzil-uthmani-v1.1', 22, 56, 'ٱلْمُلْكُ يَوْمَئِذٍ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى جَنَّٰتِ ٱلنَّعِيمِ', '2d8d5b539ab7eeb92ee9a145a1673e2b8bd5299ec2e916d94b1435f698c08962', 'ٱلْمُلْكُ يَوْمَئِذٍ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى جَنَّٰتِ ٱلنَّعِيمِ', '2d8d5b539ab7eeb92ee9a145a1673e2b8bd5299ec2e916d94b1435f698c08962', '2d8d5b539ab7eeb92ee9a145a1673e2b8bd5299ec2e916d94b1435f698c08962', NULL, 'الملك يومئذ لله يحكم بينهم فالذين ءامنوا وعملوا الصلحت في جنت النعيم', 17, 34, 135, 1, 4, 339, false, NULL),
    (2652, 'tanzil-uthmani-v1.1', 22, 57, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا فَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'db1ae033da372c197bd6a2ffc323d46e1f909f0ce7f9325c57700535d6da67a9', 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا فَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'db1ae033da372c197bd6a2ffc323d46e1f909f0ce7f9325c57700535d6da67a9', 'db1ae033da372c197bd6a2ffc323d46e1f909f0ce7f9325c57700535d6da67a9', NULL, 'والذين كفروا وكذبوا بايتنا فاولئك لهم عذاب مهين', 17, 34, 135, 1, 4, 339, false, NULL),
    (2653, 'tanzil-uthmani-v1.1', 22, 58, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓا۟ أَوْ مَاتُوا۟ لَيَرْزُقَنَّهُمُ ٱللَّهُ رِزْقًا حَسَنًا وَإِنَّ ٱللَّهَ لَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'c7f8afcd7eeba23f3ef58cf33abbdc9ab41241ca9b6a2f7dc5d72040b6080633', 'وَٱلَّذِينَ هَاجَرُوا۟ فِى سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓا۟ أَوْ مَاتُوا۟ لَيَرْزُقَنَّهُمُ ٱللَّهُ رِزْقًا حَسَنًا وَإِنَّ ٱللَّهَ لَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'c7f8afcd7eeba23f3ef58cf33abbdc9ab41241ca9b6a2f7dc5d72040b6080633', 'c7f8afcd7eeba23f3ef58cf33abbdc9ab41241ca9b6a2f7dc5d72040b6080633', NULL, 'والذين هاجروا في سبيل الله ثم قتلوا او ماتوا ليرزقنهم الله رزقا حسنا وان الله لهو خير الرزقين', 17, 34, 135, 1, 4, 339, false, NULL),
    (2654, 'tanzil-uthmani-v1.1', 22, 59, 'لَيُدْخِلَنَّهُم مُّدْخَلًا يَرْضَوْنَهُۥ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٌ', 'c3d900cbbc8a655bb00deab2db30e5b40f3be199928b057fa77c07dfc4f8a9ba', 'لَيُدْخِلَنَّهُم مُّدْخَلًا يَرْضَوْنَهُۥ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٌ', 'c3d900cbbc8a655bb00deab2db30e5b40f3be199928b057fa77c07dfc4f8a9ba', 'c3d900cbbc8a655bb00deab2db30e5b40f3be199928b057fa77c07dfc4f8a9ba', NULL, 'ليدخلنهم مدخلا يرضونه وان الله لعليم حليم', 17, 34, 135, 1, 4, 339, false, NULL),
    (2655, 'tanzil-uthmani-v1.1', 22, 60, 'ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِىَ عَلَيْهِ لَيَنصُرَنَّهُ ٱللَّهُ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', '402839d8fe196cbcaac4c686bc250736934365c26d3aa6805fcc19f3cb3d7d5f', 'ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِىَ عَلَيْهِ لَيَنصُرَنَّهُ ٱللَّهُ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', '402839d8fe196cbcaac4c686bc250736934365c26d3aa6805fcc19f3cb3d7d5f', '402839d8fe196cbcaac4c686bc250736934365c26d3aa6805fcc19f3cb3d7d5f', NULL, 'ذلك ومن عاقب بمثل ما عوقب به ثم بغي عليه لينصرنه الله ان الله لعفو غفور', 17, 34, 136, 1, 4, 339, false, NULL),
    (2656, 'tanzil-uthmani-v1.1', 22, 61, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَأَنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'dcb0ef71f38608f6e70deb549e463277034d95cd7d2f73e3a4494710e7fe04c2', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَأَنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'dcb0ef71f38608f6e70deb549e463277034d95cd7d2f73e3a4494710e7fe04c2', 'dcb0ef71f38608f6e70deb549e463277034d95cd7d2f73e3a4494710e7fe04c2', NULL, 'ذلك بان الله يولج اليل في النهار ويولج النهار في اليل وان الله سميع بصير', 17, 34, 136, 1, 4, 339, false, NULL),
    (2657, 'tanzil-uthmani-v1.1', 22, 62, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', '316b6fa14cf324f21d25163983aa8f64a48e0bda027088c1b917b30a9dfcc0b2', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', '316b6fa14cf324f21d25163983aa8f64a48e0bda027088c1b917b30a9dfcc0b2', '316b6fa14cf324f21d25163983aa8f64a48e0bda027088c1b917b30a9dfcc0b2', NULL, 'ذلك بان الله هو الحق وان ما يدعون من دونه هو البطل وان الله هو العلي الكبير', 17, 34, 136, 1, 4, 339, false, NULL),
    (2658, 'tanzil-uthmani-v1.1', 22, 63, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَتُصْبِحُ ٱلْأَرْضُ مُخْضَرَّةً إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', 'd0a5f9fed98486af2e3f9a1bb8787ec32842884e0641530d7689967238db100f', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَتُصْبِحُ ٱلْأَرْضُ مُخْضَرَّةً إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', 'd0a5f9fed98486af2e3f9a1bb8787ec32842884e0641530d7689967238db100f', 'd0a5f9fed98486af2e3f9a1bb8787ec32842884e0641530d7689967238db100f', NULL, 'الم تر ان الله انزل من السماء ماء فتصبح الارض مخضره ان الله لطيف خبير', 17, 34, 136, 1, 4, 339, false, NULL),
    (2659, 'tanzil-uthmani-v1.1', 22, 64, 'لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'b071ad67b247cd99caff1f5909877369af30e48ac8a23488f5df3488e1acfd99', 'لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 'b071ad67b247cd99caff1f5909877369af30e48ac8a23488f5df3488e1acfd99', 'b071ad67b247cd99caff1f5909877369af30e48ac8a23488f5df3488e1acfd99', NULL, 'له ما في السموت وما في الارض وان الله لهو الغني الحميد', 17, 34, 136, 1, 4, 339, false, NULL),
    (2660, 'tanzil-uthmani-v1.1', 22, 65, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلْأَرْضِ وَٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَيُمْسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلْأَرْضِ إِلَّا بِإِذْنِهِۦٓ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', '001a29a4e609e6b67a10e7c7a7b61ef74d3fce7ac8b9fe9afbedf35910643e73', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلْأَرْضِ وَٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَيُمْسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلْأَرْضِ إِلَّا بِإِذْنِهِۦٓ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ', '001a29a4e609e6b67a10e7c7a7b61ef74d3fce7ac8b9fe9afbedf35910643e73', '001a29a4e609e6b67a10e7c7a7b61ef74d3fce7ac8b9fe9afbedf35910643e73', NULL, 'الم تر ان الله سخر لكم ما في الارض والفلك تجري في البحر بامره ويمسك السماء ان تقع علي الارض الا باذنه ان الله بالناس لرءوف رحيم', 17, 34, 136, 1, 4, 340, false, NULL),
    (2661, 'tanzil-uthmani-v1.1', 22, 66, 'وَهُوَ ٱلَّذِىٓ أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌ', '6c423a6cee7b842a4683f411ef57a5efa46e5c6ee8e28bbef110fa9d1e4f34d7', 'وَهُوَ ٱلَّذِىٓ أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌ', '6c423a6cee7b842a4683f411ef57a5efa46e5c6ee8e28bbef110fa9d1e4f34d7', '6c423a6cee7b842a4683f411ef57a5efa46e5c6ee8e28bbef110fa9d1e4f34d7', NULL, 'وهو الذي احياكم ثم يميتكم ثم يحييكم ان الانسن لكفور', 17, 34, 136, 1, 4, 340, false, NULL),
    (2662, 'tanzil-uthmani-v1.1', 22, 67, 'لِّكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا هُمْ نَاسِكُوهُ فَلَا يُنَٰزِعُنَّكَ فِى ٱلْأَمْرِ وَٱدْعُ إِلَىٰ رَبِّكَ إِنَّكَ لَعَلَىٰ هُدًى مُّسْتَقِيمٍ', '44bd4dd174c24fd0b670c38831493d3e4c49d323159bb98c3b10a9f44d231351', 'لِّكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا هُمْ نَاسِكُوهُ فَلَا يُنَٰزِعُنَّكَ فِى ٱلْأَمْرِ وَٱدْعُ إِلَىٰ رَبِّكَ إِنَّكَ لَعَلَىٰ هُدًى مُّسْتَقِيمٍ', '44bd4dd174c24fd0b670c38831493d3e4c49d323159bb98c3b10a9f44d231351', '44bd4dd174c24fd0b670c38831493d3e4c49d323159bb98c3b10a9f44d231351', NULL, 'لكل امه جعلنا منسكا هم ناسكوه فلا ينزعنك في الامر وادع الي ربك انك لعلي هدي مستقيم', 17, 34, 136, 1, 4, 340, false, NULL),
    (2663, 'tanzil-uthmani-v1.1', 22, 68, 'وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ', '6f3fb89fd2607386f138161a0dab08450a3cebb42906d8b25a1ee56bdaeb13ce', 'وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ', '6f3fb89fd2607386f138161a0dab08450a3cebb42906d8b25a1ee56bdaeb13ce', '6f3fb89fd2607386f138161a0dab08450a3cebb42906d8b25a1ee56bdaeb13ce', NULL, 'وان جدلوك فقل الله اعلم بما تعملون', 17, 34, 136, 1, 4, 340, false, NULL),
    (2664, 'tanzil-uthmani-v1.1', 22, 69, 'ٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '1f266dab42ce44ffd203da4a5833a9eef7a01582e4acbd6855d47d0a3f0495b1', 'ٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', '1f266dab42ce44ffd203da4a5833a9eef7a01582e4acbd6855d47d0a3f0495b1', '1f266dab42ce44ffd203da4a5833a9eef7a01582e4acbd6855d47d0a3f0495b1', NULL, 'الله يحكم بينكم يوم القيمه فيما كنتم فيه تختلفون', 17, 34, 136, 1, 4, 340, false, NULL),
    (2665, 'tanzil-uthmani-v1.1', 22, 70, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّ ذَٰلِكَ فِى كِتَٰبٍ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'eccad44fffc6fe21548797f45eb1cbf13e69dd5fb44402b6b8e6118b81207d07', 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّ ذَٰلِكَ فِى كِتَٰبٍ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'eccad44fffc6fe21548797f45eb1cbf13e69dd5fb44402b6b8e6118b81207d07', 'eccad44fffc6fe21548797f45eb1cbf13e69dd5fb44402b6b8e6118b81207d07', NULL, 'الم تعلم ان الله يعلم ما في السماء والارض ان ذلك في كتب ان ذلك علي الله يسير', 17, 34, 136, 1, 4, 340, false, NULL),
    (2666, 'tanzil-uthmani-v1.1', 22, 71, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَمَا لَيْسَ لَهُم بِهِۦ عِلْمٌ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', '6e1be6b09da16def8a40d19c42903a11a2a656e1be4675d1b9d7c92e95fd5c1f', 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَمَا لَيْسَ لَهُم بِهِۦ عِلْمٌ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', '6e1be6b09da16def8a40d19c42903a11a2a656e1be4675d1b9d7c92e95fd5c1f', '6e1be6b09da16def8a40d19c42903a11a2a656e1be4675d1b9d7c92e95fd5c1f', NULL, 'ويعبدون من دون الله ما لم ينزل به سلطنا وما ليس لهم به علم وما للظلمين من نصير', 17, 34, 136, 1, 4, 340, false, NULL),
    (2667, 'tanzil-uthmani-v1.1', 22, 72, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ تَعْرِفُ فِى وُجُوهِ ٱلَّذِينَ كَفَرُوا۟ ٱلْمُنكَرَ يَكَادُونَ يَسْطُونَ بِٱلَّذِينَ يَتْلُونَ عَلَيْهِمْ ءَايَٰتِنَا قُلْ أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ وَبِئْسَ ٱلْمَصِيرُ', '7f16206ddf75618ed03763121973c57dc0c1222460ce7482902b52b766988b56', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ تَعْرِفُ فِى وُجُوهِ ٱلَّذِينَ كَفَرُوا۟ ٱلْمُنكَرَ يَكَادُونَ يَسْطُونَ بِٱلَّذِينَ يَتْلُونَ عَلَيْهِمْ ءَايَٰتِنَا قُلْ أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ وَبِئْسَ ٱلْمَصِيرُ', '7f16206ddf75618ed03763121973c57dc0c1222460ce7482902b52b766988b56', '7f16206ddf75618ed03763121973c57dc0c1222460ce7482902b52b766988b56', NULL, 'واذا تتلي عليهم ءايتنا بينت تعرف في وجوه الذين كفروا المنكر يكادون يسطون بالذين يتلون عليهم ءايتنا قل افانبئكم بشر من ذلكم النار وعدها الله الذين كفروا وبئس المصير', 17, 34, 136, 1, 4, 340, false, NULL),
    (2668, 'tanzil-uthmani-v1.1', 22, 73, 'يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٌ فَٱسْتَمِعُوا۟ لَهُۥٓ إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَن يَخْلُقُوا۟ ذُبَابًا وَلَوِ ٱجْتَمَعُوا۟ لَهُۥ وَإِن يَسْلُبْهُمُ ٱلذُّبَابُ شَيْـًٔا لَّا يَسْتَنقِذُوهُ مِنْهُ ضَعُفَ ٱلطَّالِبُ وَٱلْمَطْلُوبُ', '0573faac6a70b99fb469b8065957dd6e822b8777b63468cb89d0325dd87e452a', 'يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٌ فَٱسْتَمِعُوا۟ لَهُۥٓ إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَن يَخْلُقُوا۟ ذُبَابًا وَلَوِ ٱجْتَمَعُوا۟ لَهُۥ وَإِن يَسْلُبْهُمُ ٱلذُّبَابُ شَيْـًٔا لَّا يَسْتَنقِذُوهُ مِنْهُ ضَعُفَ ٱلطَّالِبُ وَٱلْمَطْلُوبُ', '0573faac6a70b99fb469b8065957dd6e822b8777b63468cb89d0325dd87e452a', '0573faac6a70b99fb469b8065957dd6e822b8777b63468cb89d0325dd87e452a', NULL, 'يايها الناس ضرب مثل فاستمعوا له ان الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له وان يسلبهم الذباب شيا لا يستنقذوه منه ضعف الطالب والمطلوب', 17, 34, 136, 1, 4, 341, false, NULL),
    (2669, 'tanzil-uthmani-v1.1', 22, 74, 'مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 'f4b6d7b84260bfee2879f223678922133fa3391f1ac60115219616c8bb1eb260', 'مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 'f4b6d7b84260bfee2879f223678922133fa3391f1ac60115219616c8bb1eb260', 'f4b6d7b84260bfee2879f223678922133fa3391f1ac60115219616c8bb1eb260', NULL, 'ما قدروا الله حق قدره ان الله لقوي عزيز', 17, 34, 136, 1, 4, 341, false, NULL),
    (2670, 'tanzil-uthmani-v1.1', 22, 75, 'ٱللَّهُ يَصْطَفِى مِنَ ٱلْمَلَٰٓئِكَةِ رُسُلًا وَمِنَ ٱلنَّاسِ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'a93bbac938434fcb21629368971157323c6f9b2ca3286e276ff080949a6e31de', 'ٱللَّهُ يَصْطَفِى مِنَ ٱلْمَلَٰٓئِكَةِ رُسُلًا وَمِنَ ٱلنَّاسِ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'a93bbac938434fcb21629368971157323c6f9b2ca3286e276ff080949a6e31de', 'a93bbac938434fcb21629368971157323c6f9b2ca3286e276ff080949a6e31de', NULL, 'الله يصطفي من الملئكه رسلا ومن الناس ان الله سميع بصير', 17, 34, 136, 1, 4, 341, false, NULL),
    (2671, 'tanzil-uthmani-v1.1', 22, 76, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'f3009618109231aa3d77a70b5b3b71e52858c3bfea76efb2dfe28af00fa7cbfc', 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'f3009618109231aa3d77a70b5b3b71e52858c3bfea76efb2dfe28af00fa7cbfc', 'f3009618109231aa3d77a70b5b3b71e52858c3bfea76efb2dfe28af00fa7cbfc', NULL, 'يعلم ما بين ايديهم وما خلفهم والي الله ترجع الامور', 17, 34, 136, 1, 4, 341, false, NULL),
    (2672, 'tanzil-uthmani-v1.1', 22, 77, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱرْكَعُوا۟ وَٱسْجُدُوا۟ وَٱعْبُدُوا۟ رَبَّكُمْ وَٱفْعَلُوا۟ ٱلْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ', '6de289ef5bc85f82bb63e05b669305100a0a323e73b60234564418429e6fc2cf', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱرْكَعُوا۟ وَٱسْجُدُوا۟ وَٱعْبُدُوا۟ رَبَّكُمْ وَٱفْعَلُوا۟ ٱلْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ', '6de289ef5bc85f82bb63e05b669305100a0a323e73b60234564418429e6fc2cf', '6de289ef5bc85f82bb63e05b669305100a0a323e73b60234564418429e6fc2cf', NULL, 'يايها الذين ءامنوا اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون', 17, 34, 136, 1, 4, 341, true, 'recommended'),
    (2673, 'tanzil-uthmani-v1.1', 22, 78, 'وَجَٰهِدُوا۟ فِى ٱللَّهِ حَقَّ جِهَادِهِۦ هُوَ ٱجْتَبَىٰكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى ٱلدِّينِ مِنْ حَرَجٍ مِّلَّةَ أَبِيكُمْ إِبْرَٰهِيمَ هُوَ سَمَّىٰكُمُ ٱلْمُسْلِمِينَ مِن قَبْلُ وَفِى هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعْتَصِمُوا۟ بِٱللَّهِ هُوَ مَوْلَىٰكُمْ فَنِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', '8292625cc9944531f56acb8109f6535814685f990acda896a41ff552d35ed4ce', 'وَجَٰهِدُوا۟ فِى ٱللَّهِ حَقَّ جِهَادِهِۦ هُوَ ٱجْتَبَىٰكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى ٱلدِّينِ مِنْ حَرَجٍ مِّلَّةَ أَبِيكُمْ إِبْرَٰهِيمَ هُوَ سَمَّىٰكُمُ ٱلْمُسْلِمِينَ مِن قَبْلُ وَفِى هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعْتَصِمُوا۟ بِٱللَّهِ هُوَ مَوْلَىٰكُمْ فَنِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', '8292625cc9944531f56acb8109f6535814685f990acda896a41ff552d35ed4ce', '8292625cc9944531f56acb8109f6535814685f990acda896a41ff552d35ed4ce', NULL, 'وجهدوا في الله حق جهاده هو اجتبيكم وما جعل عليكم في الدين من حرج مله ابيكم ابرهيم هو سميكم المسلمين من قبل وفي هذا ليكون الرسول شهيدا عليكم وتكونوا شهداء علي الناس فاقيموا الصلوه وءاتوا الزكوه واعتصموا بالله هو موليكم فنعم المولي ونعم النصير', 17, 34, 136, 1, 4, 341, false, NULL),
    (2674, 'tanzil-uthmani-v1.1', 23, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قَدْ أَفْلَحَ ٱلْمُؤْمِنُونَ', '17b38735d1880ab23288dc3c52263dccd42ef1afe8f0bb974127037749f9271c', 'قَدْ أَفْلَحَ ٱلْمُؤْمِنُونَ', 'd826ba3a021f8fdac2b8d351a2c0d23a7ae28231074a94e972d1a19fc08d09cd', 'd826ba3a021f8fdac2b8d351a2c0d23a7ae28231074a94e972d1a19fc08d09cd', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'قد افلح المؤمنون', 18, 35, 137, 1, 4, 342, false, NULL),
    (2675, 'tanzil-uthmani-v1.1', 23, 2, 'ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَٰشِعُونَ', '0c125af0d12978bbbee19e0c1f0b7cea18a79ce17c9147010e373414f5c69220', 'ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَٰشِعُونَ', '0c125af0d12978bbbee19e0c1f0b7cea18a79ce17c9147010e373414f5c69220', '0c125af0d12978bbbee19e0c1f0b7cea18a79ce17c9147010e373414f5c69220', NULL, 'الذين هم في صلاتهم خشعون', 18, 35, 137, 1, 4, 342, false, NULL),
