    (2688, 'tanzil-uthmani-v1.1', 23, 15, 'ثُمَّ إِنَّكُم بَعْدَ ذَٰلِكَ لَمَيِّتُونَ', '3a41d68f7197f6520e26b6f59b25ffc1953b6b4d050fa9c9340900b12ac16233', 'ثُمَّ إِنَّكُم بَعْدَ ذَٰلِكَ لَمَيِّتُونَ', '3a41d68f7197f6520e26b6f59b25ffc1953b6b4d050fa9c9340900b12ac16233', '3a41d68f7197f6520e26b6f59b25ffc1953b6b4d050fa9c9340900b12ac16233', NULL, 'ثم انكم بعد ذلك لميتون', 18, 35, 137, 1, 4, 342, false, NULL),
    (2689, 'tanzil-uthmani-v1.1', 23, 16, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ تُبْعَثُونَ', 'a1123b16ce17558ff1d9e16207d002726b5348327726510790b7de592aff0e8b', 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ تُبْعَثُونَ', 'a1123b16ce17558ff1d9e16207d002726b5348327726510790b7de592aff0e8b', 'a1123b16ce17558ff1d9e16207d002726b5348327726510790b7de592aff0e8b', NULL, 'ثم انكم يوم القيمه تبعثون', 18, 35, 137, 1, 4, 342, false, NULL),
    (2690, 'tanzil-uthmani-v1.1', 23, 17, 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلْخَلْقِ غَٰفِلِينَ', '3fbde3e77bcc225f1fa36655ff180b986c9f9d77ae9ddfbb921fc141de45dd7c', 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلْخَلْقِ غَٰفِلِينَ', '3fbde3e77bcc225f1fa36655ff180b986c9f9d77ae9ddfbb921fc141de45dd7c', '3fbde3e77bcc225f1fa36655ff180b986c9f9d77ae9ddfbb921fc141de45dd7c', NULL, 'ولقد خلقنا فوقكم سبع طرائق وما كنا عن الخلق غفلين', 18, 35, 137, 1, 4, 342, false, NULL),
    (2691, 'tanzil-uthmani-v1.1', 23, 18, 'وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَسْكَنَّٰهُ فِى ٱلْأَرْضِ وَإِنَّا عَلَىٰ ذَهَابٍۭ بِهِۦ لَقَٰدِرُونَ', 'bf358a2ba6e36c9d274a108475cb2d61a47167d88c2bdf699819d3df410566a5', 'وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَسْكَنَّٰهُ فِى ٱلْأَرْضِ وَإِنَّا عَلَىٰ ذَهَابٍۭ بِهِۦ لَقَٰدِرُونَ', 'bf358a2ba6e36c9d274a108475cb2d61a47167d88c2bdf699819d3df410566a5', 'bf358a2ba6e36c9d274a108475cb2d61a47167d88c2bdf699819d3df410566a5', NULL, 'وانزلنا من السماء ماء بقدر فاسكنه في الارض وانا علي ذهاب به لقدرون', 18, 35, 137, 1, 4, 343, false, NULL),
    (2692, 'tanzil-uthmani-v1.1', 23, 19, 'فَأَنشَأْنَا لَكُم بِهِۦ جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ لَّكُمْ فِيهَا فَوَٰكِهُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', '08263c935ffc1bfad0f8add077005823a3c368a42d9aa97a5127aedaa3459017', 'فَأَنشَأْنَا لَكُم بِهِۦ جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ لَّكُمْ فِيهَا فَوَٰكِهُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', '08263c935ffc1bfad0f8add077005823a3c368a42d9aa97a5127aedaa3459017', '08263c935ffc1bfad0f8add077005823a3c368a42d9aa97a5127aedaa3459017', NULL, 'فانشانا لكم به جنت من نخيل واعنب لكم فيها فوكه كثيره ومنها تاكلون', 18, 35, 137, 1, 4, 343, false, NULL),
    (2693, 'tanzil-uthmani-v1.1', 23, 20, 'وَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَآءَ تَنۢبُتُ بِٱلدُّهْنِ وَصِبْغٍ لِّلْـَٔاكِلِينَ', '932595a2650831f5f0e3c185ab334c30c24fa4166aa143c2ce3ebe017bd39a3c', 'وَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَآءَ تَنۢبُتُ بِٱلدُّهْنِ وَصِبْغٍ لِّلْـَٔاكِلِينَ', '932595a2650831f5f0e3c185ab334c30c24fa4166aa143c2ce3ebe017bd39a3c', '932595a2650831f5f0e3c185ab334c30c24fa4166aa143c2ce3ebe017bd39a3c', NULL, 'وشجره تخرج من طور سيناء تنبت بالدهن وصبغ للاكلين', 18, 35, 137, 1, 4, 343, false, NULL),
    (2694, 'tanzil-uthmani-v1.1', 23, 21, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِى بُطُونِهَا وَلَكُمْ فِيهَا مَنَٰفِعُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', '15bfe1670536c8b2500a766d76bec4e18d4df7c2b458244e7d02770fd2830c14', 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِى بُطُونِهَا وَلَكُمْ فِيهَا مَنَٰفِعُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ', '15bfe1670536c8b2500a766d76bec4e18d4df7c2b458244e7d02770fd2830c14', '15bfe1670536c8b2500a766d76bec4e18d4df7c2b458244e7d02770fd2830c14', NULL, 'وان لكم في الانعم لعبره نسقيكم مما في بطونها ولكم فيها منفع كثيره ومنها تاكلون', 18, 35, 137, 1, 4, 343, false, NULL),
    (2695, 'tanzil-uthmani-v1.1', 23, 22, 'وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', '8a01e740e8f81352a99008f20fc79a43d13d611aa76746dbbfced69103067d0d', 'وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', '8a01e740e8f81352a99008f20fc79a43d13d611aa76746dbbfced69103067d0d', '8a01e740e8f81352a99008f20fc79a43d13d611aa76746dbbfced69103067d0d', NULL, 'وعليها وعلي الفلك تحملون', 18, 35, 137, 1, 4, 343, false, NULL),
    (2696, 'tanzil-uthmani-v1.1', 23, 23, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'e4472b06f7dbd0d230857b014802e77b159609eaa6397335babae65ca0c00fe5', 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', 'e4472b06f7dbd0d230857b014802e77b159609eaa6397335babae65ca0c00fe5', 'e4472b06f7dbd0d230857b014802e77b159609eaa6397335babae65ca0c00fe5', NULL, 'ولقد ارسلنا نوحا الي قومه فقال يقوم اعبدوا الله ما لكم من اله غيره افلا تتقون', 18, 35, 137, 1, 4, 343, false, NULL),
    (2697, 'tanzil-uthmani-v1.1', 23, 24, 'فَقَالَ ٱلْمَلَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةً مَّا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', '899173eb0481ea3352fc5887756ec6a32c61d42815e366be65f1b4f645d1a8ce', 'فَقَالَ ٱلْمَلَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةً مَّا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', '899173eb0481ea3352fc5887756ec6a32c61d42815e366be65f1b4f645d1a8ce', '899173eb0481ea3352fc5887756ec6a32c61d42815e366be65f1b4f645d1a8ce', NULL, 'فقال الملؤا الذين كفروا من قومه ما هذا الا بشر مثلكم يريد ان يتفضل عليكم ولو شاء الله لانزل ملئكه ما سمعنا بهذا في ءابائنا الاولين', 18, 35, 137, 1, 4, 343, false, NULL),
    (2698, 'tanzil-uthmani-v1.1', 23, 25, 'إِنْ هُوَ إِلَّا رَجُلٌۢ بِهِۦ جِنَّةٌ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِينٍ', '0ae2cff45ca903a4dfe3873ca727342ece5d0af2cf50db2b64a727dfabab4102', 'إِنْ هُوَ إِلَّا رَجُلٌۢ بِهِۦ جِنَّةٌ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِينٍ', '0ae2cff45ca903a4dfe3873ca727342ece5d0af2cf50db2b64a727dfabab4102', '0ae2cff45ca903a4dfe3873ca727342ece5d0af2cf50db2b64a727dfabab4102', NULL, 'ان هو الا رجل به جنه فتربصوا به حتي حين', 18, 35, 137, 1, 4, 343, false, NULL),
    (2699, 'tanzil-uthmani-v1.1', 23, 26, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'ff3f3407b3fb254fdf7082a9aae74dc76a9aeb151fd34573ad018fbd0c00bc67', 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'ff3f3407b3fb254fdf7082a9aae74dc76a9aeb151fd34573ad018fbd0c00bc67', 'ff3f3407b3fb254fdf7082a9aae74dc76a9aeb151fd34573ad018fbd0c00bc67', NULL, 'قال رب انصرني بما كذبون', 18, 35, 137, 1, 4, 343, false, NULL),
    (2700, 'tanzil-uthmani-v1.1', 23, 27, 'فَأَوْحَيْنَآ إِلَيْهِ أَنِ ٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسْلُكْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ مِنْهُمْ وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ إِنَّهُم مُّغْرَقُونَ', '75d76d2ba0654f94f279b857e039aaff947587cc77a3e5c135582e04c18e2273', 'فَأَوْحَيْنَآ إِلَيْهِ أَنِ ٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسْلُكْ فِيهَا مِن كُلٍّ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ مِنْهُمْ وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ إِنَّهُم مُّغْرَقُونَ', '75d76d2ba0654f94f279b857e039aaff947587cc77a3e5c135582e04c18e2273', '75d76d2ba0654f94f279b857e039aaff947587cc77a3e5c135582e04c18e2273', NULL, 'فاوحينا اليه ان اصنع الفلك باعيننا ووحينا فاذا جاء امرنا وفار التنور فاسلك فيها من كل زوجين اثنين واهلك الا من سبق عليه القول منهم ولا تخطبني في الذين ظلموا انهم مغرقون', 18, 35, 137, 1, 4, 343, false, NULL),
    (2701, 'tanzil-uthmani-v1.1', 23, 28, 'فَإِذَا ٱسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلْفُلْكِ فَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى نَجَّىٰنَا مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '72a61b48ec5349e065a219370cf80bd533dd4cb59c577a16fd9e8f4783c40137', 'فَإِذَا ٱسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلْفُلْكِ فَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى نَجَّىٰنَا مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '72a61b48ec5349e065a219370cf80bd533dd4cb59c577a16fd9e8f4783c40137', '72a61b48ec5349e065a219370cf80bd533dd4cb59c577a16fd9e8f4783c40137', NULL, 'فاذا استويت انت ومن معك علي الفلك فقل الحمد لله الذي نجينا من القوم الظلمين', 18, 35, 137, 1, 4, 344, false, NULL),
    (2702, 'tanzil-uthmani-v1.1', 23, 29, 'وَقُل رَّبِّ أَنزِلْنِى مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ ٱلْمُنزِلِينَ', 'c7f7568b68d6d5e592fcfe8fc3a0fb25b818051a3a352ec430e1012ca2da3c70', 'وَقُل رَّبِّ أَنزِلْنِى مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ ٱلْمُنزِلِينَ', 'c7f7568b68d6d5e592fcfe8fc3a0fb25b818051a3a352ec430e1012ca2da3c70', 'c7f7568b68d6d5e592fcfe8fc3a0fb25b818051a3a352ec430e1012ca2da3c70', NULL, 'وقل رب انزلني منزلا مباركا وانت خير المنزلين', 18, 35, 137, 1, 4, 344, false, NULL),
    (2703, 'tanzil-uthmani-v1.1', 23, 30, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ وَإِن كُنَّا لَمُبْتَلِينَ', 'efd78e30e894fe027e1f988f5d8ecd4577416d8f318865118be10640cf2fd1bf', 'إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ وَإِن كُنَّا لَمُبْتَلِينَ', 'efd78e30e894fe027e1f988f5d8ecd4577416d8f318865118be10640cf2fd1bf', 'efd78e30e894fe027e1f988f5d8ecd4577416d8f318865118be10640cf2fd1bf', NULL, 'ان في ذلك لايت وان كنا لمبتلين', 18, 35, 137, 1, 4, 344, false, NULL),
    (2704, 'tanzil-uthmani-v1.1', 23, 31, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', '307429c259bee35054d44bdfa2e3c7e49376bcf957bad7789244414e21478ddd', 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', '307429c259bee35054d44bdfa2e3c7e49376bcf957bad7789244414e21478ddd', '307429c259bee35054d44bdfa2e3c7e49376bcf957bad7789244414e21478ddd', NULL, 'ثم انشانا من بعدهم قرنا ءاخرين', 18, 35, 137, 1, 4, 344, false, NULL),
    (2705, 'tanzil-uthmani-v1.1', 23, 32, 'فَأَرْسَلْنَا فِيهِمْ رَسُولًا مِّنْهُمْ أَنِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', '64bd04b7aa295d5ff26e62ec042cf401a01028f4b40a04a0abc9b1b4e9ae1877', 'فَأَرْسَلْنَا فِيهِمْ رَسُولًا مِّنْهُمْ أَنِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ', '64bd04b7aa295d5ff26e62ec042cf401a01028f4b40a04a0abc9b1b4e9ae1877', '64bd04b7aa295d5ff26e62ec042cf401a01028f4b40a04a0abc9b1b4e9ae1877', NULL, 'فارسلنا فيهم رسولا منهم ان اعبدوا الله ما لكم من اله غيره افلا تتقون', 18, 35, 137, 1, 4, 344, false, NULL),
    (2706, 'tanzil-uthmani-v1.1', 23, 33, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِهِ ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِلِقَآءِ ٱلْـَٔاخِرَةِ وَأَتْرَفْنَٰهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', '3ac58899a2d9357109d5f37e2b9d4ea0b32fd9bd6f71b0b06c9e6bd26108d726', 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِهِ ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِلِقَآءِ ٱلْـَٔاخِرَةِ وَأَتْرَفْنَٰهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', '3ac58899a2d9357109d5f37e2b9d4ea0b32fd9bd6f71b0b06c9e6bd26108d726', '3ac58899a2d9357109d5f37e2b9d4ea0b32fd9bd6f71b0b06c9e6bd26108d726', NULL, 'وقال الملا من قومه الذين كفروا وكذبوا بلقاء الاخره واترفنهم في الحيوه الدنيا ما هذا الا بشر مثلكم ياكل مما تاكلون منه ويشرب مما تشربون', 18, 35, 137, 1, 4, 344, false, NULL),
    (2707, 'tanzil-uthmani-v1.1', 23, 34, 'وَلَئِنْ أَطَعْتُم بَشَرًا مِّثْلَكُمْ إِنَّكُمْ إِذًا لَّخَٰسِرُونَ', '4746da4f8f2ef9458fd587c796ff9fbf6caadb1ab3fb13cb647e4b76f66c471a', 'وَلَئِنْ أَطَعْتُم بَشَرًا مِّثْلَكُمْ إِنَّكُمْ إِذًا لَّخَٰسِرُونَ', '4746da4f8f2ef9458fd587c796ff9fbf6caadb1ab3fb13cb647e4b76f66c471a', '4746da4f8f2ef9458fd587c796ff9fbf6caadb1ab3fb13cb647e4b76f66c471a', NULL, 'ولئن اطعتم بشرا مثلكم انكم اذا لخسرون', 18, 35, 137, 1, 4, 344, false, NULL),
    (2708, 'tanzil-uthmani-v1.1', 23, 35, 'أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَابًا وَعِظَٰمًا أَنَّكُم مُّخْرَجُونَ', 'a6cfa9c463ff7f597cfdc05011bdd975df3c123b2d27524c7804bf058b7fefb5', 'أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَابًا وَعِظَٰمًا أَنَّكُم مُّخْرَجُونَ', 'a6cfa9c463ff7f597cfdc05011bdd975df3c123b2d27524c7804bf058b7fefb5', 'a6cfa9c463ff7f597cfdc05011bdd975df3c123b2d27524c7804bf058b7fefb5', NULL, 'ايعدكم انكم اذا متم وكنتم ترابا وعظما انكم مخرجون', 18, 35, 137, 1, 4, 344, false, NULL),
    (2709, 'tanzil-uthmani-v1.1', 23, 36, 'هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ', '766df77a19056c5a362beb3f80cb44e3d11d4117beb89c195e38bd1b4a3c77e1', 'هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ', '766df77a19056c5a362beb3f80cb44e3d11d4117beb89c195e38bd1b4a3c77e1', '766df77a19056c5a362beb3f80cb44e3d11d4117beb89c195e38bd1b4a3c77e1', NULL, 'هيهات هيهات لما توعدون', 18, 35, 138, 1, 4, 344, false, NULL),
    (2710, 'tanzil-uthmani-v1.1', 23, 37, 'إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', '49ce46509deab9f8ad6d3834f9e082c804707fc292f5c1ccfcf2fbb5ea8ba9cc', 'إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', '49ce46509deab9f8ad6d3834f9e082c804707fc292f5c1ccfcf2fbb5ea8ba9cc', '49ce46509deab9f8ad6d3834f9e082c804707fc292f5c1ccfcf2fbb5ea8ba9cc', NULL, 'ان هي الا حياتنا الدنيا نموت ونحيا وما نحن بمبعوثين', 18, 35, 138, 1, 4, 344, false, NULL),
    (2711, 'tanzil-uthmani-v1.1', 23, 38, 'إِنْ هُوَ إِلَّا رَجُلٌ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا وَمَا نَحْنُ لَهُۥ بِمُؤْمِنِينَ', '91589618cb34e999388e02f4d8e89c6bc1d68a3e2d6ec3dda253ac182adea650', 'إِنْ هُوَ إِلَّا رَجُلٌ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا وَمَا نَحْنُ لَهُۥ بِمُؤْمِنِينَ', '91589618cb34e999388e02f4d8e89c6bc1d68a3e2d6ec3dda253ac182adea650', '91589618cb34e999388e02f4d8e89c6bc1d68a3e2d6ec3dda253ac182adea650', NULL, 'ان هو الا رجل افتري علي الله كذبا وما نحن له بمؤمنين', 18, 35, 138, 1, 4, 344, false, NULL),
    (2712, 'tanzil-uthmani-v1.1', 23, 39, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'ff3f3407b3fb254fdf7082a9aae74dc76a9aeb151fd34573ad018fbd0c00bc67', 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 'ff3f3407b3fb254fdf7082a9aae74dc76a9aeb151fd34573ad018fbd0c00bc67', 'ff3f3407b3fb254fdf7082a9aae74dc76a9aeb151fd34573ad018fbd0c00bc67', NULL, 'قال رب انصرني بما كذبون', 18, 35, 138, 1, 4, 344, false, NULL),
    (2713, 'tanzil-uthmani-v1.1', 23, 40, 'قَالَ عَمَّا قَلِيلٍ لَّيُصْبِحُنَّ نَٰدِمِينَ', '4e80520f9a9d0d45fa0789e2c67a3358568a96c68c4c917aa185419537cc9853', 'قَالَ عَمَّا قَلِيلٍ لَّيُصْبِحُنَّ نَٰدِمِينَ', '4e80520f9a9d0d45fa0789e2c67a3358568a96c68c4c917aa185419537cc9853', '4e80520f9a9d0d45fa0789e2c67a3358568a96c68c4c917aa185419537cc9853', NULL, 'قال عما قليل ليصبحن ندمين', 18, 35, 138, 1, 4, 344, false, NULL),
    (2714, 'tanzil-uthmani-v1.1', 23, 41, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ بِٱلْحَقِّ فَجَعَلْنَٰهُمْ غُثَآءً فَبُعْدًا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'd3e372afca300778ca1be4d26f30ebd2ca6a6e2f493eeb34e58649e831a326dd', 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ بِٱلْحَقِّ فَجَعَلْنَٰهُمْ غُثَآءً فَبُعْدًا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 'd3e372afca300778ca1be4d26f30ebd2ca6a6e2f493eeb34e58649e831a326dd', 'd3e372afca300778ca1be4d26f30ebd2ca6a6e2f493eeb34e58649e831a326dd', NULL, 'فاخذتهم الصيحه بالحق فجعلنهم غثاء فبعدا للقوم الظلمين', 18, 35, 138, 1, 4, 344, false, NULL),
    (2715, 'tanzil-uthmani-v1.1', 23, 42, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قُرُونًا ءَاخَرِينَ', '313c397a613e8618fac67a4c9a65ab8369435f443984ab420dd2467b6d3119d7', 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قُرُونًا ءَاخَرِينَ', '313c397a613e8618fac67a4c9a65ab8369435f443984ab420dd2467b6d3119d7', '313c397a613e8618fac67a4c9a65ab8369435f443984ab420dd2467b6d3119d7', NULL, 'ثم انشانا من بعدهم قرونا ءاخرين', 18, 35, 138, 1, 4, 344, false, NULL),
    (2716, 'tanzil-uthmani-v1.1', 23, 43, 'مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', '722041d9b06f776ff0e6d62e7c596927aa342210d0b7d0e8006908604567adc1', 'مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', '722041d9b06f776ff0e6d62e7c596927aa342210d0b7d0e8006908604567adc1', '722041d9b06f776ff0e6d62e7c596927aa342210d0b7d0e8006908604567adc1', NULL, 'ما تسبق من امه اجلها وما يستخرون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2717, 'tanzil-uthmani-v1.1', 23, 44, 'ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَا كُلَّ مَا جَآءَ أُمَّةً رَّسُولُهَا كَذَّبُوهُ فَأَتْبَعْنَا بَعْضَهُم بَعْضًا وَجَعَلْنَٰهُمْ أَحَادِيثَ فَبُعْدًا لِّقَوْمٍ لَّا يُؤْمِنُونَ', '96903d0d93f8e06e2af5b423ae6a1d76ecb2d889d339a143365f205e52bf20a0', 'ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَا كُلَّ مَا جَآءَ أُمَّةً رَّسُولُهَا كَذَّبُوهُ فَأَتْبَعْنَا بَعْضَهُم بَعْضًا وَجَعَلْنَٰهُمْ أَحَادِيثَ فَبُعْدًا لِّقَوْمٍ لَّا يُؤْمِنُونَ', '96903d0d93f8e06e2af5b423ae6a1d76ecb2d889d339a143365f205e52bf20a0', '96903d0d93f8e06e2af5b423ae6a1d76ecb2d889d339a143365f205e52bf20a0', NULL, 'ثم ارسلنا رسلنا تترا كل ما جاء امه رسولها كذبوه فاتبعنا بعضهم بعضا وجعلنهم احاديث فبعدا لقوم لا يؤمنون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2718, 'tanzil-uthmani-v1.1', 23, 45, 'ثُمَّ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', 'ed92bbb7156f1b40f4dbb4b9a954e56b33bc8f2ca61c5c8c1c75ded1e7c207ff', 'ثُمَّ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', 'ed92bbb7156f1b40f4dbb4b9a954e56b33bc8f2ca61c5c8c1c75ded1e7c207ff', 'ed92bbb7156f1b40f4dbb4b9a954e56b33bc8f2ca61c5c8c1c75ded1e7c207ff', NULL, 'ثم ارسلنا موسي واخاه هرون بايتنا وسلطن مبين', 18, 35, 138, 1, 4, 345, false, NULL),
    (2719, 'tanzil-uthmani-v1.1', 23, 46, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا عَالِينَ', '13f5db1e2d2c9ea2ea44eff380ed4fcc39d2dfd7b4a613ac448d8919a68ef197', 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا عَالِينَ', '13f5db1e2d2c9ea2ea44eff380ed4fcc39d2dfd7b4a613ac448d8919a68ef197', '13f5db1e2d2c9ea2ea44eff380ed4fcc39d2dfd7b4a613ac448d8919a68ef197', NULL, 'الي فرعون وملايه فاستكبروا وكانوا قوما عالين', 18, 35, 138, 1, 4, 345, false, NULL),
    (2720, 'tanzil-uthmani-v1.1', 23, 47, 'فَقَالُوٓا۟ أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَٰبِدُونَ', 'd452ed72f620f2ff1209c6e0d48c1adf4b38ef61aacf11638b566ff2205ab0cb', 'فَقَالُوٓا۟ أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَٰبِدُونَ', 'd452ed72f620f2ff1209c6e0d48c1adf4b38ef61aacf11638b566ff2205ab0cb', 'd452ed72f620f2ff1209c6e0d48c1adf4b38ef61aacf11638b566ff2205ab0cb', NULL, 'فقالوا انؤمن لبشرين مثلنا وقومهما لنا عبدون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2721, 'tanzil-uthmani-v1.1', 23, 48, 'فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلْمُهْلَكِينَ', '6a05bb5a5cba1efd4c244f5eb0a67778e09af9a379e50be9eb0bcf697932db28', 'فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلْمُهْلَكِينَ', '6a05bb5a5cba1efd4c244f5eb0a67778e09af9a379e50be9eb0bcf697932db28', '6a05bb5a5cba1efd4c244f5eb0a67778e09af9a379e50be9eb0bcf697932db28', NULL, 'فكذبوهما فكانوا من المهلكين', 18, 35, 138, 1, 4, 345, false, NULL),
    (2722, 'tanzil-uthmani-v1.1', 23, 49, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ لَعَلَّهُمْ يَهْتَدُونَ', '8349c66e3d1699c079ce2d758475940c9f52d56b1d3b05fbaf2b3253ae50f5d7', 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ لَعَلَّهُمْ يَهْتَدُونَ', '8349c66e3d1699c079ce2d758475940c9f52d56b1d3b05fbaf2b3253ae50f5d7', '8349c66e3d1699c079ce2d758475940c9f52d56b1d3b05fbaf2b3253ae50f5d7', NULL, 'ولقد ءاتينا موسي الكتب لعلهم يهتدون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2723, 'tanzil-uthmani-v1.1', 23, 50, 'وَجَعَلْنَا ٱبْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةً وَءَاوَيْنَٰهُمَآ إِلَىٰ رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ', '94bd112d65a1e4b081838e940c8422b8cd61336df0db0697cd2d69da535e9957', 'وَجَعَلْنَا ٱبْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةً وَءَاوَيْنَٰهُمَآ إِلَىٰ رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ', '94bd112d65a1e4b081838e940c8422b8cd61336df0db0697cd2d69da535e9957', '94bd112d65a1e4b081838e940c8422b8cd61336df0db0697cd2d69da535e9957', NULL, 'وجعلنا ابن مريم وامه ءايه وءاوينهما الي ربوه ذات قرار ومعين', 18, 35, 138, 1, 4, 345, false, NULL),
    (2724, 'tanzil-uthmani-v1.1', 23, 51, 'يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُوا۟ مِنَ ٱلطَّيِّبَٰتِ وَٱعْمَلُوا۟ صَٰلِحًا إِنِّى بِمَا تَعْمَلُونَ عَلِيمٌ', '266d6732c0070f7143994d856c665680021c7d80daddd79a4416fcbee226745c', 'يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُوا۟ مِنَ ٱلطَّيِّبَٰتِ وَٱعْمَلُوا۟ صَٰلِحًا إِنِّى بِمَا تَعْمَلُونَ عَلِيمٌ', '266d6732c0070f7143994d856c665680021c7d80daddd79a4416fcbee226745c', '266d6732c0070f7143994d856c665680021c7d80daddd79a4416fcbee226745c', NULL, 'يايها الرسل كلوا من الطيبت واعملوا صلحا اني بما تعملون عليم', 18, 35, 138, 1, 4, 345, false, NULL),
    (2725, 'tanzil-uthmani-v1.1', 23, 52, 'وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱتَّقُونِ', '54d2fcadfe10e6acbf2f84a8608a6f4c57d14c82213d81be166e25eeb31e54ee', 'وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا۠ رَبُّكُمْ فَٱتَّقُونِ', '54d2fcadfe10e6acbf2f84a8608a6f4c57d14c82213d81be166e25eeb31e54ee', '54d2fcadfe10e6acbf2f84a8608a6f4c57d14c82213d81be166e25eeb31e54ee', NULL, 'وان هذه امتكم امه وحده وانا ربكم فاتقون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2726, 'tanzil-uthmani-v1.1', 23, 53, 'فَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ زُبُرًا كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', '29bb8d4375d3198d9cc46281d4574e32f826a70cd7b7de5d9ca0dbba61e71ade', 'فَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ زُبُرًا كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', '29bb8d4375d3198d9cc46281d4574e32f826a70cd7b7de5d9ca0dbba61e71ade', '29bb8d4375d3198d9cc46281d4574e32f826a70cd7b7de5d9ca0dbba61e71ade', NULL, 'فتقطعوا امرهم بينهم زبرا كل حزب بما لديهم فرحون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2727, 'tanzil-uthmani-v1.1', 23, 54, 'فَذَرْهُمْ فِى غَمْرَتِهِمْ حَتَّىٰ حِينٍ', '63349e5d6a393d280d5caf449bbb2ad0e350db7218caeaa5f5228de2e570da9c', 'فَذَرْهُمْ فِى غَمْرَتِهِمْ حَتَّىٰ حِينٍ', '63349e5d6a393d280d5caf449bbb2ad0e350db7218caeaa5f5228de2e570da9c', '63349e5d6a393d280d5caf449bbb2ad0e350db7218caeaa5f5228de2e570da9c', NULL, 'فذرهم في غمرتهم حتي حين', 18, 35, 138, 1, 4, 345, false, NULL),
    (2728, 'tanzil-uthmani-v1.1', 23, 55, 'أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٍ وَبَنِينَ', '0816529c1d7203cb4e6c34f144acb7b47ba7f3fe2480f16dce831fe4668d00bb', 'أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٍ وَبَنِينَ', '0816529c1d7203cb4e6c34f144acb7b47ba7f3fe2480f16dce831fe4668d00bb', '0816529c1d7203cb4e6c34f144acb7b47ba7f3fe2480f16dce831fe4668d00bb', NULL, 'ايحسبون انما نمدهم به من مال وبنين', 18, 35, 138, 1, 4, 345, false, NULL),
    (2729, 'tanzil-uthmani-v1.1', 23, 56, 'نُسَارِعُ لَهُمْ فِى ٱلْخَيْرَٰتِ بَل لَّا يَشْعُرُونَ', 'b650ed91b3118b5c3f8d28a497f37928a4f9dcbcd395b361db5d22093a4cae69', 'نُسَارِعُ لَهُمْ فِى ٱلْخَيْرَٰتِ بَل لَّا يَشْعُرُونَ', 'b650ed91b3118b5c3f8d28a497f37928a4f9dcbcd395b361db5d22093a4cae69', 'b650ed91b3118b5c3f8d28a497f37928a4f9dcbcd395b361db5d22093a4cae69', NULL, 'نسارع لهم في الخيرت بل لا يشعرون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2730, 'tanzil-uthmani-v1.1', 23, 57, 'إِنَّ ٱلَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', 'aacb13be6097d704d54f20e8016b5cd57708be8d8f6c0583b7e15f6611b9f128', 'إِنَّ ٱلَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', 'aacb13be6097d704d54f20e8016b5cd57708be8d8f6c0583b7e15f6611b9f128', 'aacb13be6097d704d54f20e8016b5cd57708be8d8f6c0583b7e15f6611b9f128', NULL, 'ان الذين هم من خشيه ربهم مشفقون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2731, 'tanzil-uthmani-v1.1', 23, 58, 'وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمْ يُؤْمِنُونَ', '34bd13be4357c0e07fa54ca9644426d69ba6664c24d0e4b6e31ba340c1356624', 'وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمْ يُؤْمِنُونَ', '34bd13be4357c0e07fa54ca9644426d69ba6664c24d0e4b6e31ba340c1356624', '34bd13be4357c0e07fa54ca9644426d69ba6664c24d0e4b6e31ba340c1356624', NULL, 'والذين هم بايت ربهم يؤمنون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2732, 'tanzil-uthmani-v1.1', 23, 59, 'وَٱلَّذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ', '06b28312616cda765f2581e3a27b94eda4cbd0d7b40de236749faf14af8cb3fa', 'وَٱلَّذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ', '06b28312616cda765f2581e3a27b94eda4cbd0d7b40de236749faf14af8cb3fa', '06b28312616cda765f2581e3a27b94eda4cbd0d7b40de236749faf14af8cb3fa', NULL, 'والذين هم بربهم لا يشركون', 18, 35, 138, 1, 4, 345, false, NULL),
    (2733, 'tanzil-uthmani-v1.1', 23, 60, 'وَٱلَّذِينَ يُؤْتُونَ مَآ ءَاتَوا۟ وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَٰجِعُونَ', '1e6e9f615d284e82b24c451367736394d346a8d1227d399bf1a6ea9bd365e8ea', 'وَٱلَّذِينَ يُؤْتُونَ مَآ ءَاتَوا۟ وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَٰجِعُونَ', '1e6e9f615d284e82b24c451367736394d346a8d1227d399bf1a6ea9bd365e8ea', '1e6e9f615d284e82b24c451367736394d346a8d1227d399bf1a6ea9bd365e8ea', NULL, 'والذين يؤتون ما ءاتوا وقلوبهم وجله انهم الي ربهم رجعون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2734, 'tanzil-uthmani-v1.1', 23, 61, 'أُو۟لَٰٓئِكَ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَهُمْ لَهَا سَٰبِقُونَ', '5b9a57b7e1f3394cace6ff87558f0f62402009f12981258c15d3d96282222566', 'أُو۟لَٰٓئِكَ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَهُمْ لَهَا سَٰبِقُونَ', '5b9a57b7e1f3394cace6ff87558f0f62402009f12981258c15d3d96282222566', '5b9a57b7e1f3394cace6ff87558f0f62402009f12981258c15d3d96282222566', NULL, 'اولئك يسرعون في الخيرت وهم لها سبقون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2735, 'tanzil-uthmani-v1.1', 23, 62, 'وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَلَدَيْنَا كِتَٰبٌ يَنطِقُ بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', '2156c406324efc0abfba0615d84af2b72662a92c912bc9634c4d1463e6c5d9c1', 'وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا وَلَدَيْنَا كِتَٰبٌ يَنطِقُ بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', '2156c406324efc0abfba0615d84af2b72662a92c912bc9634c4d1463e6c5d9c1', '2156c406324efc0abfba0615d84af2b72662a92c912bc9634c4d1463e6c5d9c1', NULL, 'ولا نكلف نفسا الا وسعها ولدينا كتب ينطق بالحق وهم لا يظلمون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2736, 'tanzil-uthmani-v1.1', 23, 63, 'بَلْ قُلُوبُهُمْ فِى غَمْرَةٍ مِّنْ هَٰذَا وَلَهُمْ أَعْمَٰلٌ مِّن دُونِ ذَٰلِكَ هُمْ لَهَا عَٰمِلُونَ', '35e1f15ac4c586bac2ab806ba3af7a7503f5196fe1dd62ef675c4b3d221b70f0', 'بَلْ قُلُوبُهُمْ فِى غَمْرَةٍ مِّنْ هَٰذَا وَلَهُمْ أَعْمَٰلٌ مِّن دُونِ ذَٰلِكَ هُمْ لَهَا عَٰمِلُونَ', '35e1f15ac4c586bac2ab806ba3af7a7503f5196fe1dd62ef675c4b3d221b70f0', '35e1f15ac4c586bac2ab806ba3af7a7503f5196fe1dd62ef675c4b3d221b70f0', NULL, 'بل قلوبهم في غمره من هذا ولهم اعمل من دون ذلك هم لها عملون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2737, 'tanzil-uthmani-v1.1', 23, 64, 'حَتَّىٰٓ إِذَآ أَخَذْنَا مُتْرَفِيهِم بِٱلْعَذَابِ إِذَا هُمْ يَجْـَٔرُونَ', '3f15df945bf393d9d639121c2a78c838591afe77ed738e00a39e179808a98d57', 'حَتَّىٰٓ إِذَآ أَخَذْنَا مُتْرَفِيهِم بِٱلْعَذَابِ إِذَا هُمْ يَجْـَٔرُونَ', '3f15df945bf393d9d639121c2a78c838591afe77ed738e00a39e179808a98d57', '3f15df945bf393d9d639121c2a78c838591afe77ed738e00a39e179808a98d57', NULL, 'حتي اذا اخذنا مترفيهم بالعذاب اذا هم يجرون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2738, 'tanzil-uthmani-v1.1', 23, 65, 'لَا تَجْـَٔرُوا۟ ٱلْيَوْمَ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', 'd1d1f361c11e156e0ec6e56fb64d428b7bd18961cb5a0e2dec4bfad7d12777f3', 'لَا تَجْـَٔرُوا۟ ٱلْيَوْمَ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', 'd1d1f361c11e156e0ec6e56fb64d428b7bd18961cb5a0e2dec4bfad7d12777f3', 'd1d1f361c11e156e0ec6e56fb64d428b7bd18961cb5a0e2dec4bfad7d12777f3', NULL, 'لا تجروا اليوم انكم منا لا تنصرون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2739, 'tanzil-uthmani-v1.1', 23, 66, 'قَدْ كَانَتْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ تَنكِصُونَ', '9a5eafe4f8f7b0763259b5ada9bdd0f7788a2f943f1553efa50f7678448edec8', 'قَدْ كَانَتْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ تَنكِصُونَ', '9a5eafe4f8f7b0763259b5ada9bdd0f7788a2f943f1553efa50f7678448edec8', '9a5eafe4f8f7b0763259b5ada9bdd0f7788a2f943f1553efa50f7678448edec8', NULL, 'قد كانت ءايتي تتلي عليكم فكنتم علي اعقبكم تنكصون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2740, 'tanzil-uthmani-v1.1', 23, 67, 'مُسْتَكْبِرِينَ بِهِۦ سَٰمِرًا تَهْجُرُونَ', '6707cd31e5c42aa34c76262d04644b394c8aae748924b4ab7bf065682ce2adf8', 'مُسْتَكْبِرِينَ بِهِۦ سَٰمِرًا تَهْجُرُونَ', '6707cd31e5c42aa34c76262d04644b394c8aae748924b4ab7bf065682ce2adf8', '6707cd31e5c42aa34c76262d04644b394c8aae748924b4ab7bf065682ce2adf8', NULL, 'مستكبرين به سمرا تهجرون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2741, 'tanzil-uthmani-v1.1', 23, 68, 'أَفَلَمْ يَدَّبَّرُوا۟ ٱلْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَأْتِ ءَابَآءَهُمُ ٱلْأَوَّلِينَ', '8243f88eee0073067eb98b76dfd002defe807544e1afd46bda4d9a040710e5da', 'أَفَلَمْ يَدَّبَّرُوا۟ ٱلْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَأْتِ ءَابَآءَهُمُ ٱلْأَوَّلِينَ', '8243f88eee0073067eb98b76dfd002defe807544e1afd46bda4d9a040710e5da', '8243f88eee0073067eb98b76dfd002defe807544e1afd46bda4d9a040710e5da', NULL, 'افلم يدبروا القول ام جاءهم ما لم يات ءاباءهم الاولين', 18, 35, 138, 1, 4, 346, false, NULL),
    (2742, 'tanzil-uthmani-v1.1', 23, 69, 'أَمْ لَمْ يَعْرِفُوا۟ رَسُولَهُمْ فَهُمْ لَهُۥ مُنكِرُونَ', 'd19f880c63b984d3b07c975f51078a69a81063af19b59740244db6468bf129bc', 'أَمْ لَمْ يَعْرِفُوا۟ رَسُولَهُمْ فَهُمْ لَهُۥ مُنكِرُونَ', 'd19f880c63b984d3b07c975f51078a69a81063af19b59740244db6468bf129bc', 'd19f880c63b984d3b07c975f51078a69a81063af19b59740244db6468bf129bc', NULL, 'ام لم يعرفوا رسولهم فهم له منكرون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2743, 'tanzil-uthmani-v1.1', 23, 70, 'أَمْ يَقُولُونَ بِهِۦ جِنَّةٌۢ بَلْ جَآءَهُم بِٱلْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَٰرِهُونَ', 'af84f6d957382874d01f0c731410ba578e2eddf521fd4528aa3e42eb18ceaec1', 'أَمْ يَقُولُونَ بِهِۦ جِنَّةٌۢ بَلْ جَآءَهُم بِٱلْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَٰرِهُونَ', 'af84f6d957382874d01f0c731410ba578e2eddf521fd4528aa3e42eb18ceaec1', 'af84f6d957382874d01f0c731410ba578e2eddf521fd4528aa3e42eb18ceaec1', NULL, 'ام يقولون به جنه بل جاءهم بالحق واكثرهم للحق كرهون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2744, 'tanzil-uthmani-v1.1', 23, 71, 'وَلَوِ ٱتَّبَعَ ٱلْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ وَمَن فِيهِنَّ بَلْ أَتَيْنَٰهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ', 'd21a8bb79927c97c19929055aad0ec51218d5b3f98bf73f2c31c4b87f8055235', 'وَلَوِ ٱتَّبَعَ ٱلْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ وَمَن فِيهِنَّ بَلْ أَتَيْنَٰهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ', 'd21a8bb79927c97c19929055aad0ec51218d5b3f98bf73f2c31c4b87f8055235', 'd21a8bb79927c97c19929055aad0ec51218d5b3f98bf73f2c31c4b87f8055235', NULL, 'ولو اتبع الحق اهواءهم لفسدت السموت والارض ومن فيهن بل اتينهم بذكرهم فهم عن ذكرهم معرضون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2745, 'tanzil-uthmani-v1.1', 23, 72, 'أَمْ تَسْـَٔلُهُمْ خَرْجًا فَخَرَاجُ رَبِّكَ خَيْرٌ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', '2828f95ea79a120a5371ba804e7f96e0b0cb26187ffe916f14ecbea7633fb2ef', 'أَمْ تَسْـَٔلُهُمْ خَرْجًا فَخَرَاجُ رَبِّكَ خَيْرٌ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', '2828f95ea79a120a5371ba804e7f96e0b0cb26187ffe916f14ecbea7633fb2ef', '2828f95ea79a120a5371ba804e7f96e0b0cb26187ffe916f14ecbea7633fb2ef', NULL, 'ام تسلهم خرجا فخراج ربك خير وهو خير الرزقين', 18, 35, 138, 1, 4, 346, false, NULL),
    (2746, 'tanzil-uthmani-v1.1', 23, 73, 'وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '008172ca73818a4997db56208171e39b956896248266f427affe71c8f7c13d23', 'وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '008172ca73818a4997db56208171e39b956896248266f427affe71c8f7c13d23', '008172ca73818a4997db56208171e39b956896248266f427affe71c8f7c13d23', NULL, 'وانك لتدعوهم الي صرط مستقيم', 18, 35, 138, 1, 4, 346, false, NULL),
    (2747, 'tanzil-uthmani-v1.1', 23, 74, 'وَإِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ', '8e36a8d88979cd3f2e8acf4559a20a8d18b6012a0ea417efb2ac22ac163f2ab2', 'وَإِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ', '8e36a8d88979cd3f2e8acf4559a20a8d18b6012a0ea417efb2ac22ac163f2ab2', '8e36a8d88979cd3f2e8acf4559a20a8d18b6012a0ea417efb2ac22ac163f2ab2', NULL, 'وان الذين لا يؤمنون بالاخره عن الصرط لنكبون', 18, 35, 138, 1, 4, 346, false, NULL),
    (2748, 'tanzil-uthmani-v1.1', 23, 75, 'وَلَوْ رَحِمْنَٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرٍّ لَّلَجُّوا۟ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', '80bb24a6c17a361f59ed4511d781ba5ed938048722457ed8a74f5926b192d771', 'وَلَوْ رَحِمْنَٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرٍّ لَّلَجُّوا۟ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', '80bb24a6c17a361f59ed4511d781ba5ed938048722457ed8a74f5926b192d771', '80bb24a6c17a361f59ed4511d781ba5ed938048722457ed8a74f5926b192d771', NULL, 'ولو رحمنهم وكشفنا ما بهم من ضر للجوا في طغينهم يعمهون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2749, 'tanzil-uthmani-v1.1', 23, 76, 'وَلَقَدْ أَخَذْنَٰهُم بِٱلْعَذَابِ فَمَا ٱسْتَكَانُوا۟ لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ', '0b48fbf403ed7edfb5f9431b78d7d5304065bcc22522d7a6754185650db68916', 'وَلَقَدْ أَخَذْنَٰهُم بِٱلْعَذَابِ فَمَا ٱسْتَكَانُوا۟ لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ', '0b48fbf403ed7edfb5f9431b78d7d5304065bcc22522d7a6754185650db68916', '0b48fbf403ed7edfb5f9431b78d7d5304065bcc22522d7a6754185650db68916', NULL, 'ولقد اخذنهم بالعذاب فما استكانوا لربهم وما يتضرعون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2750, 'tanzil-uthmani-v1.1', 23, 77, 'حَتَّىٰٓ إِذَا فَتَحْنَا عَلَيْهِم بَابًا ذَا عَذَابٍ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ', 'c927bcb4f5c4d65fb924f6fd9a21c0e34d79a4406a1a01b4f5ac711862429daf', 'حَتَّىٰٓ إِذَا فَتَحْنَا عَلَيْهِم بَابًا ذَا عَذَابٍ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ', 'c927bcb4f5c4d65fb924f6fd9a21c0e34d79a4406a1a01b4f5ac711862429daf', 'c927bcb4f5c4d65fb924f6fd9a21c0e34d79a4406a1a01b4f5ac711862429daf', NULL, 'حتي اذا فتحنا عليهم بابا ذا عذاب شديد اذا هم فيه مبلسون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2751, 'tanzil-uthmani-v1.1', 23, 78, 'وَهُوَ ٱلَّذِىٓ أَنشَأَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', 'dcb4d5f52d2cd0cdeace238ec8f6a9238ba058e9fcabca5b163face5dc29d675', 'وَهُوَ ٱلَّذِىٓ أَنشَأَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', 'dcb4d5f52d2cd0cdeace238ec8f6a9238ba058e9fcabca5b163face5dc29d675', 'dcb4d5f52d2cd0cdeace238ec8f6a9238ba058e9fcabca5b163face5dc29d675', NULL, 'وهو الذي انشا لكم السمع والابصر والافده قليلا ما تشكرون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2752, 'tanzil-uthmani-v1.1', 23, 79, 'وَهُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', '9124fa7167e673a3e0ec31aba257eed5c010d6c4539244566296441e9fd6e4ce', 'وَهُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', '9124fa7167e673a3e0ec31aba257eed5c010d6c4539244566296441e9fd6e4ce', '9124fa7167e673a3e0ec31aba257eed5c010d6c4539244566296441e9fd6e4ce', NULL, 'وهو الذي ذراكم في الارض واليه تحشرون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2753, 'tanzil-uthmani-v1.1', 23, 80, 'وَهُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ وَلَهُ ٱخْتِلَٰفُ ٱلَّيْلِ وَٱلنَّهَارِ أَفَلَا تَعْقِلُونَ', '5102d5d249dafe9f8f5df613c2a1f4a17bce2dec897a7b1050bf67a17ee29954', 'وَهُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ وَلَهُ ٱخْتِلَٰفُ ٱلَّيْلِ وَٱلنَّهَارِ أَفَلَا تَعْقِلُونَ', '5102d5d249dafe9f8f5df613c2a1f4a17bce2dec897a7b1050bf67a17ee29954', '5102d5d249dafe9f8f5df613c2a1f4a17bce2dec897a7b1050bf67a17ee29954', NULL, 'وهو الذي يحي ويميت وله اختلف اليل والنهار افلا تعقلون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2754, 'tanzil-uthmani-v1.1', 23, 81, 'بَلْ قَالُوا۟ مِثْلَ مَا قَالَ ٱلْأَوَّلُونَ', 'cf267888dd1b8a1311cc9519c68f3fcf6dca563db1a71458d8d6bd38abcc1ee0', 'بَلْ قَالُوا۟ مِثْلَ مَا قَالَ ٱلْأَوَّلُونَ', 'cf267888dd1b8a1311cc9519c68f3fcf6dca563db1a71458d8d6bd38abcc1ee0', 'cf267888dd1b8a1311cc9519c68f3fcf6dca563db1a71458d8d6bd38abcc1ee0', NULL, 'بل قالوا مثل ما قال الاولون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2755, 'tanzil-uthmani-v1.1', 23, 82, 'قَالُوٓا۟ أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', '0d1cd22ffce6e21afedd9ef38ab9e7d42bb445cae84c8b13389b7aa8ac609247', 'قَالُوٓا۟ أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', '0d1cd22ffce6e21afedd9ef38ab9e7d42bb445cae84c8b13389b7aa8ac609247', '0d1cd22ffce6e21afedd9ef38ab9e7d42bb445cae84c8b13389b7aa8ac609247', NULL, 'قالوا اءذا متنا وكنا ترابا وعظما اءنا لمبعوثون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2756, 'tanzil-uthmani-v1.1', 23, 83, 'لَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَٰذَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', '97e69c43b9eb4939bee1c4798959b322d9e59c13b1f83c99597c8ce5e8adb943', 'لَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَٰذَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', '97e69c43b9eb4939bee1c4798959b322d9e59c13b1f83c99597c8ce5e8adb943', '97e69c43b9eb4939bee1c4798959b322d9e59c13b1f83c99597c8ce5e8adb943', NULL, 'لقد وعدنا نحن وءاباؤنا هذا من قبل ان هذا الا اسطير الاولين', 18, 35, 139, 1, 4, 347, false, NULL),
    (2757, 'tanzil-uthmani-v1.1', 23, 84, 'قُل لِّمَنِ ٱلْأَرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ', 'c47c738d66c45bd9029a4604d61a2e53262ab22269e529d2c3bc4ed90f823426', 'قُل لِّمَنِ ٱلْأَرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ', 'c47c738d66c45bd9029a4604d61a2e53262ab22269e529d2c3bc4ed90f823426', 'c47c738d66c45bd9029a4604d61a2e53262ab22269e529d2c3bc4ed90f823426', NULL, 'قل لمن الارض ومن فيها ان كنتم تعلمون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2758, 'tanzil-uthmani-v1.1', 23, 85, 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَذَكَّرُونَ', '329acf71e10c2233c4c47e1dcd9b063f28c0bc4073656f16b208ff918fa4e10e', 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَذَكَّرُونَ', '329acf71e10c2233c4c47e1dcd9b063f28c0bc4073656f16b208ff918fa4e10e', '329acf71e10c2233c4c47e1dcd9b063f28c0bc4073656f16b208ff918fa4e10e', NULL, 'سيقولون لله قل افلا تذكرون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2759, 'tanzil-uthmani-v1.1', 23, 86, 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'a060957380b83f88009f559de238f10621be1c27e8953cce0ee337189ad0b6fb', 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'a060957380b83f88009f559de238f10621be1c27e8953cce0ee337189ad0b6fb', 'a060957380b83f88009f559de238f10621be1c27e8953cce0ee337189ad0b6fb', NULL, 'قل من رب السموت السبع ورب العرش العظيم', 18, 35, 139, 1, 4, 347, false, NULL),
    (2760, 'tanzil-uthmani-v1.1', 23, 87, 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَتَّقُونَ', '8541f5709b216064b1ad2cb9b0eff659ed192dd2cb6a601478d56156307ad599', 'سَيَقُولُونَ لِلَّهِ قُلْ أَفَلَا تَتَّقُونَ', '8541f5709b216064b1ad2cb9b0eff659ed192dd2cb6a601478d56156307ad599', '8541f5709b216064b1ad2cb9b0eff659ed192dd2cb6a601478d56156307ad599', NULL, 'سيقولون لله قل افلا تتقون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2761, 'tanzil-uthmani-v1.1', 23, 88, 'قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ', 'f007ca7345ea2d4c806f8263857c4a02491f171704bdc13b8d7499d3233f355e', 'قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ', 'f007ca7345ea2d4c806f8263857c4a02491f171704bdc13b8d7499d3233f355e', 'f007ca7345ea2d4c806f8263857c4a02491f171704bdc13b8d7499d3233f355e', NULL, 'قل من بيده ملكوت كل شيء وهو يجير ولا يجار عليه ان كنتم تعلمون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2762, 'tanzil-uthmani-v1.1', 23, 89, 'سَيَقُولُونَ لِلَّهِ قُلْ فَأَنَّىٰ تُسْحَرُونَ', 'b0394ac59f905a1d3ac8dbfb518d2249a51680021ea0b090bac687823b4694f7', 'سَيَقُولُونَ لِلَّهِ قُلْ فَأَنَّىٰ تُسْحَرُونَ', 'b0394ac59f905a1d3ac8dbfb518d2249a51680021ea0b090bac687823b4694f7', 'b0394ac59f905a1d3ac8dbfb518d2249a51680021ea0b090bac687823b4694f7', NULL, 'سيقولون لله قل فاني تسحرون', 18, 35, 139, 1, 4, 347, false, NULL),
    (2763, 'tanzil-uthmani-v1.1', 23, 90, 'بَلْ أَتَيْنَٰهُم بِٱلْحَقِّ وَإِنَّهُمْ لَكَٰذِبُونَ', 'ba7fc10a00db58db6209f60ea6e73cbdd5026d5832067ddc673a42b42bc77ffd', 'بَلْ أَتَيْنَٰهُم بِٱلْحَقِّ وَإِنَّهُمْ لَكَٰذِبُونَ', 'ba7fc10a00db58db6209f60ea6e73cbdd5026d5832067ddc673a42b42bc77ffd', 'ba7fc10a00db58db6209f60ea6e73cbdd5026d5832067ddc673a42b42bc77ffd', NULL, 'بل اتينهم بالحق وانهم لكذبون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2764, 'tanzil-uthmani-v1.1', 23, 91, 'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُۥ مِنْ إِلَٰهٍ إِذًا لَّذَهَبَ كُلُّ إِلَٰهٍۭ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍ سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', '4a80ee5e40f45257770208bf7980a6e656cc87a4ac563b6e874faf01d58ad812', 'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُۥ مِنْ إِلَٰهٍ إِذًا لَّذَهَبَ كُلُّ إِلَٰهٍۭ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍ سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', '4a80ee5e40f45257770208bf7980a6e656cc87a4ac563b6e874faf01d58ad812', '4a80ee5e40f45257770208bf7980a6e656cc87a4ac563b6e874faf01d58ad812', NULL, 'ما اتخذ الله من ولد وما كان معه من اله اذا لذهب كل اله بما خلق ولعلا بعضهم علي بعض سبحن الله عما يصفون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2765, 'tanzil-uthmani-v1.1', 23, 92, 'عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '4cd1b7860be2a683ad0d586171742f8d0947b855d6d1a6121a98a91361b75f5e', 'عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '4cd1b7860be2a683ad0d586171742f8d0947b855d6d1a6121a98a91361b75f5e', '4cd1b7860be2a683ad0d586171742f8d0947b855d6d1a6121a98a91361b75f5e', NULL, 'علم الغيب والشهده فتعلي عما يشركون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2766, 'tanzil-uthmani-v1.1', 23, 93, 'قُل رَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ', 'e7cb021a38116134b3d2d9420bb2d68ee4f7c28c773fdb412723318c37265866', 'قُل رَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ', 'e7cb021a38116134b3d2d9420bb2d68ee4f7c28c773fdb412723318c37265866', 'e7cb021a38116134b3d2d9420bb2d68ee4f7c28c773fdb412723318c37265866', NULL, 'قل رب اما تريني ما يوعدون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2767, 'tanzil-uthmani-v1.1', 23, 94, 'رَبِّ فَلَا تَجْعَلْنِى فِى ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '7cdcbb8c2c2913b9c3f0406fc4f281882f60f5aa2f462625c80dc917a7c17560', 'رَبِّ فَلَا تَجْعَلْنِى فِى ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '7cdcbb8c2c2913b9c3f0406fc4f281882f60f5aa2f462625c80dc917a7c17560', '7cdcbb8c2c2913b9c3f0406fc4f281882f60f5aa2f462625c80dc917a7c17560', NULL, 'رب فلا تجعلني في القوم الظلمين', 18, 35, 139, 1, 4, 348, false, NULL),
    (2768, 'tanzil-uthmani-v1.1', 23, 95, 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَٰدِرُونَ', 'de9b821a60b6e7b2680a77aeac5591ba2a3898f0efe914101b3c992e411e3c75', 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَٰدِرُونَ', 'de9b821a60b6e7b2680a77aeac5591ba2a3898f0efe914101b3c992e411e3c75', 'de9b821a60b6e7b2680a77aeac5591ba2a3898f0efe914101b3c992e411e3c75', NULL, 'وانا علي ان نريك ما نعدهم لقدرون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2769, 'tanzil-uthmani-v1.1', 23, 96, 'ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ ٱلسَّيِّئَةَ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ', '3395b256f75d57476817acd4067f3ff3aeef5b9813bb8441a087c3b39aa8b5f1', 'ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ ٱلسَّيِّئَةَ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ', '3395b256f75d57476817acd4067f3ff3aeef5b9813bb8441a087c3b39aa8b5f1', '3395b256f75d57476817acd4067f3ff3aeef5b9813bb8441a087c3b39aa8b5f1', NULL, 'ادفع بالتي هي احسن السيئه نحن اعلم بما يصفون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2770, 'tanzil-uthmani-v1.1', 23, 97, 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ ٱلشَّيَٰطِينِ', 'a2149cf7e462e9b099b817adc5b435f95c036bee9ebd5acf5e93a7022ff0c69b', 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ ٱلشَّيَٰطِينِ', 'a2149cf7e462e9b099b817adc5b435f95c036bee9ebd5acf5e93a7022ff0c69b', 'a2149cf7e462e9b099b817adc5b435f95c036bee9ebd5acf5e93a7022ff0c69b', NULL, 'وقل رب اعوذ بك من همزت الشيطين', 18, 35, 139, 1, 4, 348, false, NULL),
