    (2772, 'tanzil-uthmani-v1.1', 23, 99, 'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ رَبِّ ٱرْجِعُونِ', 'ff0eca04a7d70fd5d8cb382aea037c52da07d4f2fbba657aea4f902313838b7e', 'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ رَبِّ ٱرْجِعُونِ', 'ff0eca04a7d70fd5d8cb382aea037c52da07d4f2fbba657aea4f902313838b7e', 'ff0eca04a7d70fd5d8cb382aea037c52da07d4f2fbba657aea4f902313838b7e', NULL, 'حتي اذا جاء احدهم الموت قال رب ارجعون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2773, 'tanzil-uthmani-v1.1', 23, 100, 'لَعَلِّىٓ أَعْمَلُ صَٰلِحًا فِيمَا تَرَكْتُ كَلَّآ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ', '06cc58d9ff31cb0e5632646b422321bbf954d7963ab8f1a1a4f086bfa317d9f5', 'لَعَلِّىٓ أَعْمَلُ صَٰلِحًا فِيمَا تَرَكْتُ كَلَّآ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ', '06cc58d9ff31cb0e5632646b422321bbf954d7963ab8f1a1a4f086bfa317d9f5', '06cc58d9ff31cb0e5632646b422321bbf954d7963ab8f1a1a4f086bfa317d9f5', NULL, 'لعلي اعمل صلحا فيما تركت كلا انها كلمه هو قائلها ومن ورائهم برزخ الي يوم يبعثون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2774, 'tanzil-uthmani-v1.1', 23, 101, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ فَلَآ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَآءَلُونَ', '311322d6ba09a6871a504418a5a906ea322ecbcccdaf28a4f5c1fd8e45afece7', 'فَإِذَا نُفِخَ فِى ٱلصُّورِ فَلَآ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَآءَلُونَ', '311322d6ba09a6871a504418a5a906ea322ecbcccdaf28a4f5c1fd8e45afece7', '311322d6ba09a6871a504418a5a906ea322ecbcccdaf28a4f5c1fd8e45afece7', NULL, 'فاذا نفخ في الصور فلا انساب بينهم يومئذ ولا يتساءلون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2775, 'tanzil-uthmani-v1.1', 23, 102, 'فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'c2ba1406b8f4d50aa7422eece4f19fa800bb53497b71c20dda5fc9f02a99892b', 'فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'c2ba1406b8f4d50aa7422eece4f19fa800bb53497b71c20dda5fc9f02a99892b', 'c2ba1406b8f4d50aa7422eece4f19fa800bb53497b71c20dda5fc9f02a99892b', NULL, 'فمن ثقلت موزينه فاولئك هم المفلحون', 18, 35, 139, 1, 4, 348, false, NULL),
