    (2777, 'tanzil-uthmani-v1.1', 23, 104, 'تَلْفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمْ فِيهَا كَٰلِحُونَ', '30238b49ea812304b031d3f1561c45d5607e1a934d747a113b3aa6d424f0f0ed', 'تَلْفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمْ فِيهَا كَٰلِحُونَ', '30238b49ea812304b031d3f1561c45d5607e1a934d747a113b3aa6d424f0f0ed', '30238b49ea812304b031d3f1561c45d5607e1a934d747a113b3aa6d424f0f0ed', NULL, 'تلفح وجوههم النار وهم فيها كلحون', 18, 35, 139, 1, 4, 348, false, NULL),
    (2778, 'tanzil-uthmani-v1.1', 23, 105, 'أَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ', 'd785b71bb852dc090cc357c4266064cc42b109a0d0f454efbe73e6aac6bf794c', 'أَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ', 'd785b71bb852dc090cc357c4266064cc42b109a0d0f454efbe73e6aac6bf794c', 'd785b71bb852dc090cc357c4266064cc42b109a0d0f454efbe73e6aac6bf794c', NULL, 'الم تكن ءايتي تتلي عليكم فكنتم بها تكذبون', 18, 35, 139, 1, 4, 349, false, NULL),
    (2779, 'tanzil-uthmani-v1.1', 23, 106, 'قَالُوا۟ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًا ضَآلِّينَ', 'f9ec71fcc8b478c7907e6cdf3bbdcbd307ff2f90aaeb19f1d779715f942e3e6d', 'قَالُوا۟ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًا ضَآلِّينَ', 'f9ec71fcc8b478c7907e6cdf3bbdcbd307ff2f90aaeb19f1d779715f942e3e6d', 'f9ec71fcc8b478c7907e6cdf3bbdcbd307ff2f90aaeb19f1d779715f942e3e6d', NULL, 'قالوا ربنا غلبت علينا شقوتنا وكنا قوما ضالين', 18, 35, 139, 1, 4, 349, false, NULL),
    (2780, 'tanzil-uthmani-v1.1', 23, 107, 'رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَٰلِمُونَ', '36874e24d6161b47bc86a9c525472b6521e9c2fc435d62276fd28c852b533f6b', 'رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَٰلِمُونَ', '36874e24d6161b47bc86a9c525472b6521e9c2fc435d62276fd28c852b533f6b', '36874e24d6161b47bc86a9c525472b6521e9c2fc435d62276fd28c852b533f6b', NULL, 'ربنا اخرجنا منها فان عدنا فانا ظلمون', 18, 35, 139, 1, 4, 349, false, NULL),
    (2781, 'tanzil-uthmani-v1.1', 23, 108, 'قَالَ ٱخْسَـُٔوا۟ فِيهَا وَلَا تُكَلِّمُونِ', '2fe39919b4a4ece74be520228235e487c8ccf7f7d0314f63182b452bee5da377', 'قَالَ ٱخْسَـُٔوا۟ فِيهَا وَلَا تُكَلِّمُونِ', '2fe39919b4a4ece74be520228235e487c8ccf7f7d0314f63182b452bee5da377', '2fe39919b4a4ece74be520228235e487c8ccf7f7d0314f63182b452bee5da377', NULL, 'قال اخسوا فيها ولا تكلمون', 18, 35, 139, 1, 4, 349, false, NULL),
    (2782, 'tanzil-uthmani-v1.1', 23, 109, 'إِنَّهُۥ كَانَ فَرِيقٌ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 'f88c8224808ec940a23edf332c5d4a6eb4f0af4fd5e0b6980bb631272459eb7a', 'إِنَّهُۥ كَانَ فَرِيقٌ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 'f88c8224808ec940a23edf332c5d4a6eb4f0af4fd5e0b6980bb631272459eb7a', 'f88c8224808ec940a23edf332c5d4a6eb4f0af4fd5e0b6980bb631272459eb7a', NULL, 'انه كان فريق من عبادي يقولون ربنا ءامنا فاغفر لنا وارحمنا وانت خير الرحمين', 18, 35, 139, 1, 4, 349, false, NULL),
    (2783, 'tanzil-uthmani-v1.1', 23, 110, 'فَٱتَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّىٰٓ أَنسَوْكُمْ ذِكْرِى وَكُنتُم مِّنْهُمْ تَضْحَكُونَ', 'a0318bffbeb3e39b3f2907023b3e597eaf43b754a7dafaa426389fa7cfde2ce4', 'فَٱتَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّىٰٓ أَنسَوْكُمْ ذِكْرِى وَكُنتُم مِّنْهُمْ تَضْحَكُونَ', 'a0318bffbeb3e39b3f2907023b3e597eaf43b754a7dafaa426389fa7cfde2ce4', 'a0318bffbeb3e39b3f2907023b3e597eaf43b754a7dafaa426389fa7cfde2ce4', NULL, 'فاتخذتموهم سخريا حتي انسوكم ذكري وكنتم منهم تضحكون', 18, 35, 139, 1, 4, 349, false, NULL),
    (2784, 'tanzil-uthmani-v1.1', 23, 111, 'إِنِّى جَزَيْتُهُمُ ٱلْيَوْمَ بِمَا صَبَرُوٓا۟ أَنَّهُمْ هُمُ ٱلْفَآئِزُونَ', '0804f98eb47b58e44ffc3509f03ed5671e8ff368ba23f15791dd5dd80939078b', 'إِنِّى جَزَيْتُهُمُ ٱلْيَوْمَ بِمَا صَبَرُوٓا۟ أَنَّهُمْ هُمُ ٱلْفَآئِزُونَ', '0804f98eb47b58e44ffc3509f03ed5671e8ff368ba23f15791dd5dd80939078b', '0804f98eb47b58e44ffc3509f03ed5671e8ff368ba23f15791dd5dd80939078b', NULL, 'اني جزيتهم اليوم بما صبروا انهم هم الفائزون', 18, 35, 139, 1, 4, 349, false, NULL),
    (2785, 'tanzil-uthmani-v1.1', 23, 112, 'قَٰلَ كَمْ لَبِثْتُمْ فِى ٱلْأَرْضِ عَدَدَ سِنِينَ', '3700fbd8fd1d0400d98259a5cb2ab88833e7ce74349bc98bb6b44e05315eb6fc', 'قَٰلَ كَمْ لَبِثْتُمْ فِى ٱلْأَرْضِ عَدَدَ سِنِينَ', '3700fbd8fd1d0400d98259a5cb2ab88833e7ce74349bc98bb6b44e05315eb6fc', '3700fbd8fd1d0400d98259a5cb2ab88833e7ce74349bc98bb6b44e05315eb6fc', NULL, 'قل كم لبثتم في الارض عدد سنين', 18, 35, 139, 1, 4, 349, false, NULL),
    (2786, 'tanzil-uthmani-v1.1', 23, 113, 'قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ فَسْـَٔلِ ٱلْعَآدِّينَ', '02374c97e77cc012ec74fad19dfa969375414c540f979ddf7f3e9ff189f04965', 'قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ فَسْـَٔلِ ٱلْعَآدِّينَ', '02374c97e77cc012ec74fad19dfa969375414c540f979ddf7f3e9ff189f04965', '02374c97e77cc012ec74fad19dfa969375414c540f979ddf7f3e9ff189f04965', NULL, 'قالوا لبثنا يوما او بعض يوم فسل العادين', 18, 35, 139, 1, 4, 349, false, NULL),
    (2787, 'tanzil-uthmani-v1.1', 23, 114, 'قَٰلَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ', '94d0557c7c2db8864c7fd61c69dc115f3e31c8d9582cde3039ee414df85edef8', 'قَٰلَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ', '94d0557c7c2db8864c7fd61c69dc115f3e31c8d9582cde3039ee414df85edef8', '94d0557c7c2db8864c7fd61c69dc115f3e31c8d9582cde3039ee414df85edef8', NULL, 'قل ان لبثتم الا قليلا لو انكم كنتم تعلمون', 18, 35, 139, 1, 4, 349, false, NULL),
    (2788, 'tanzil-uthmani-v1.1', 23, 115, 'أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ', '87d2d85be188cd86dc897687519bdec324c9ef8b2054d6960354ed10cb6d38c7', 'أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ', '87d2d85be188cd86dc897687519bdec324c9ef8b2054d6960354ed10cb6d38c7', '87d2d85be188cd86dc897687519bdec324c9ef8b2054d6960354ed10cb6d38c7', NULL, 'افحسبتم انما خلقنكم عبثا وانكم الينا لا ترجعون', 18, 35, 139, 1, 4, 349, false, NULL),
    (2789, 'tanzil-uthmani-v1.1', 23, 116, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ', 'f60085891099353685b131242ea8f9220d8c85a2d115681952b1c7876c15dd16', 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ', 'f60085891099353685b131242ea8f9220d8c85a2d115681952b1c7876c15dd16', 'f60085891099353685b131242ea8f9220d8c85a2d115681952b1c7876c15dd16', NULL, 'فتعلي الله الملك الحق لا اله الا هو رب العرش الكريم', 18, 35, 139, 1, 4, 349, false, NULL),
    (2790, 'tanzil-uthmani-v1.1', 23, 117, 'وَمَن يَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرْهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', '4707bfc4ff5039a00fec89282f09b23b5f8c0fb38b40aed737a45d4958d80de5', 'وَمَن يَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرْهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ إِنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', '4707bfc4ff5039a00fec89282f09b23b5f8c0fb38b40aed737a45d4958d80de5', '4707bfc4ff5039a00fec89282f09b23b5f8c0fb38b40aed737a45d4958d80de5', NULL, 'ومن يدع مع الله الها ءاخر لا برهن له به فانما حسابه عند ربه انه لا يفلح الكفرون', 18, 35, 139, 1, 4, 349, false, NULL),
    (2791, 'tanzil-uthmani-v1.1', 23, 118, 'وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', '141de2ac78743f5f6b0d36694f61bb2e8c646e430320397f515ce7e936ad5643', 'وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', '141de2ac78743f5f6b0d36694f61bb2e8c646e430320397f515ce7e936ad5643', '141de2ac78743f5f6b0d36694f61bb2e8c646e430320397f515ce7e936ad5643', NULL, 'وقل رب اغفر وارحم وانت خير الرحمين', 18, 35, 139, 1, 4, 349, false, NULL),
    (2792, 'tanzil-uthmani-v1.1', 24, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سُورَةٌ أَنزَلْنَٰهَا وَفَرَضْنَٰهَا وَأَنزَلْنَا فِيهَآ ءَايَٰتٍۭ بَيِّنَٰتٍ لَّعَلَّكُمْ تَذَكَّرُونَ', 'dc93454d72c4716f6e85f06a7d620554e596bb516c62a1e77e1d5d70242583f3', 'سُورَةٌ أَنزَلْنَٰهَا وَفَرَضْنَٰهَا وَأَنزَلْنَا فِيهَآ ءَايَٰتٍۭ بَيِّنَٰتٍ لَّعَلَّكُمْ تَذَكَّرُونَ', '016ebb8a298fdd252ad8e331f376224ce8a0ee138cf72fb51caefb6aac2c6817', '016ebb8a298fdd252ad8e331f376224ce8a0ee138cf72fb51caefb6aac2c6817', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'سوره انزلنها وفرضنها وانزلنا فيها ءايت بينت لعلكم تذكرون', 18, 35, 140, 1, 4, 350, false, NULL),
    (2793, 'tanzil-uthmani-v1.1', 24, 2, 'ٱلزَّانِيَةُ وَٱلزَّانِى فَٱجْلِدُوا۟ كُلَّ وَٰحِدٍ مِّنْهُمَا مِا۟ئَةَ جَلْدَةٍ وَلَا تَأْخُذْكُم بِهِمَا رَأْفَةٌ فِى دِينِ ٱللَّهِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌ مِّنَ ٱلْمُؤْمِنِينَ', '540c6c63e92529c97c6b781a41d29476b5a9840bc468d23012743a40066c9911', 'ٱلزَّانِيَةُ وَٱلزَّانِى فَٱجْلِدُوا۟ كُلَّ وَٰحِدٍ مِّنْهُمَا مِا۟ئَةَ جَلْدَةٍ وَلَا تَأْخُذْكُم بِهِمَا رَأْفَةٌ فِى دِينِ ٱللَّهِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌ مِّنَ ٱلْمُؤْمِنِينَ', '540c6c63e92529c97c6b781a41d29476b5a9840bc468d23012743a40066c9911', '540c6c63e92529c97c6b781a41d29476b5a9840bc468d23012743a40066c9911', NULL, 'الزانيه والزاني فاجلدوا كل وحد منهما مائه جلده ولا تاخذكم بهما رافه في دين الله ان كنتم تؤمنون بالله واليوم الاخر وليشهد عذابهما طائفه من المؤمنين', 18, 35, 140, 1, 4, 350, false, NULL),
    (2794, 'tanzil-uthmani-v1.1', 24, 3, 'ٱلزَّانِى لَا يَنكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلْمُؤْمِنِينَ', 'e5bd39fdd44003ad8d3b7585b5295fd9f4cc691fc1c73903f6ec5a9b22f2ce48', 'ٱلزَّانِى لَا يَنكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلْمُؤْمِنِينَ', 'e5bd39fdd44003ad8d3b7585b5295fd9f4cc691fc1c73903f6ec5a9b22f2ce48', 'e5bd39fdd44003ad8d3b7585b5295fd9f4cc691fc1c73903f6ec5a9b22f2ce48', NULL, 'الزاني لا ينكح الا زانيه او مشركه والزانيه لا ينكحها الا زان او مشرك وحرم ذلك علي المؤمنين', 18, 35, 140, 1, 4, 350, false, NULL),
    (2795, 'tanzil-uthmani-v1.1', 24, 4, 'وَٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ثُمَّ لَمْ يَأْتُوا۟ بِأَرْبَعَةِ شُهَدَآءَ فَٱجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةً وَلَا تَقْبَلُوا۟ لَهُمْ شَهَٰدَةً أَبَدًا وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'f0e0d484993a5d6d49d8f025e6445a3b60219d14b7937524989150f63b8fee61', 'وَٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ثُمَّ لَمْ يَأْتُوا۟ بِأَرْبَعَةِ شُهَدَآءَ فَٱجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةً وَلَا تَقْبَلُوا۟ لَهُمْ شَهَٰدَةً أَبَدًا وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'f0e0d484993a5d6d49d8f025e6445a3b60219d14b7937524989150f63b8fee61', 'f0e0d484993a5d6d49d8f025e6445a3b60219d14b7937524989150f63b8fee61', NULL, 'والذين يرمون المحصنت ثم لم ياتوا باربعه شهداء فاجلدوهم ثمنين جلده ولا تقبلوا لهم شهده ابدا واولئك هم الفسقون', 18, 35, 140, 1, 4, 350, false, NULL),
    (2796, 'tanzil-uthmani-v1.1', 24, 5, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'ec341ba847900c3787d19c33ca40340c5c066f6a12700a872808001c94bab6c8', 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'ec341ba847900c3787d19c33ca40340c5c066f6a12700a872808001c94bab6c8', 'ec341ba847900c3787d19c33ca40340c5c066f6a12700a872808001c94bab6c8', NULL, 'الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم', 18, 35, 140, 1, 4, 350, false, NULL),
    (2797, 'tanzil-uthmani-v1.1', 24, 6, 'وَٱلَّذِينَ يَرْمُونَ أَزْوَٰجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَآءُ إِلَّآ أَنفُسُهُمْ فَشَهَٰدَةُ أَحَدِهِمْ أَرْبَعُ شَهَٰدَٰتٍۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', '11aa1b6935bf236988a3a789a89b2512231c675a03be2b434592b95a92f185e3', 'وَٱلَّذِينَ يَرْمُونَ أَزْوَٰجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَآءُ إِلَّآ أَنفُسُهُمْ فَشَهَٰدَةُ أَحَدِهِمْ أَرْبَعُ شَهَٰدَٰتٍۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', '11aa1b6935bf236988a3a789a89b2512231c675a03be2b434592b95a92f185e3', '11aa1b6935bf236988a3a789a89b2512231c675a03be2b434592b95a92f185e3', NULL, 'والذين يرمون ازوجهم ولم يكن لهم شهداء الا انفسهم فشهده احدهم اربع شهدت بالله انه لمن الصدقين', 18, 35, 140, 1, 4, 350, false, NULL),
    (2798, 'tanzil-uthmani-v1.1', 24, 7, 'وَٱلْخَٰمِسَةُ أَنَّ لَعْنَتَ ٱللَّهِ عَلَيْهِ إِن كَانَ مِنَ ٱلْكَٰذِبِينَ', 'f871ecc623f51ef4980c2d201fbba236d74a94f8601a1184904e10269d7fd28f', 'وَٱلْخَٰمِسَةُ أَنَّ لَعْنَتَ ٱللَّهِ عَلَيْهِ إِن كَانَ مِنَ ٱلْكَٰذِبِينَ', 'f871ecc623f51ef4980c2d201fbba236d74a94f8601a1184904e10269d7fd28f', 'f871ecc623f51ef4980c2d201fbba236d74a94f8601a1184904e10269d7fd28f', NULL, 'والخمسه ان لعنت الله عليه ان كان من الكذبين', 18, 35, 140, 1, 4, 350, false, NULL),
    (2799, 'tanzil-uthmani-v1.1', 24, 8, 'وَيَدْرَؤُا۟ عَنْهَا ٱلْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَٰدَٰتٍۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلْكَٰذِبِينَ', 'a90f119c7baf4176862bef95ca92a9a64fb6646d5d66fd67eb6e2cb1e4b5fcea', 'وَيَدْرَؤُا۟ عَنْهَا ٱلْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَٰدَٰتٍۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلْكَٰذِبِينَ', 'a90f119c7baf4176862bef95ca92a9a64fb6646d5d66fd67eb6e2cb1e4b5fcea', 'a90f119c7baf4176862bef95ca92a9a64fb6646d5d66fd67eb6e2cb1e4b5fcea', NULL, 'ويدرؤا عنها العذاب ان تشهد اربع شهدت بالله انه لمن الكذبين', 18, 35, 140, 1, 4, 350, false, NULL),
    (2800, 'tanzil-uthmani-v1.1', 24, 9, 'وَٱلْخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيْهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ', '2003731356b269d510b2dc6a4abb4767fa8dc41cc9c8b8190527c4d82aa4b1ce', 'وَٱلْخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيْهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ', '2003731356b269d510b2dc6a4abb4767fa8dc41cc9c8b8190527c4d82aa4b1ce', '2003731356b269d510b2dc6a4abb4767fa8dc41cc9c8b8190527c4d82aa4b1ce', NULL, 'والخمسه ان غضب الله عليها ان كان من الصدقين', 18, 35, 140, 1, 4, 350, false, NULL),
    (2801, 'tanzil-uthmani-v1.1', 24, 10, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ', '0ff0cca7ef110f758a21e663182d67db7fb4674021a0ad09907a010cc5d4a686', 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ', '0ff0cca7ef110f758a21e663182d67db7fb4674021a0ad09907a010cc5d4a686', '0ff0cca7ef110f758a21e663182d67db7fb4674021a0ad09907a010cc5d4a686', NULL, 'ولولا فضل الله عليكم ورحمته وان الله تواب حكيم', 18, 35, 140, 1, 4, 350, false, NULL),
    (2802, 'tanzil-uthmani-v1.1', 24, 11, 'إِنَّ ٱلَّذِينَ جَآءُو بِٱلْإِفْكِ عُصْبَةٌ مِّنكُمْ لَا تَحْسَبُوهُ شَرًّا لَّكُم بَلْ هُوَ خَيْرٌ لَّكُمْ لِكُلِّ ٱمْرِئٍ مِّنْهُم مَّا ٱكْتَسَبَ مِنَ ٱلْإِثْمِ وَٱلَّذِى تَوَلَّىٰ كِبْرَهُۥ مِنْهُمْ لَهُۥ عَذَابٌ عَظِيمٌ', '4d46f9f3f8d1384528f31197255b237728bc8d70447f02f538dafdab4964ebd5', 'إِنَّ ٱلَّذِينَ جَآءُو بِٱلْإِفْكِ عُصْبَةٌ مِّنكُمْ لَا تَحْسَبُوهُ شَرًّا لَّكُم بَلْ هُوَ خَيْرٌ لَّكُمْ لِكُلِّ ٱمْرِئٍ مِّنْهُم مَّا ٱكْتَسَبَ مِنَ ٱلْإِثْمِ وَٱلَّذِى تَوَلَّىٰ كِبْرَهُۥ مِنْهُمْ لَهُۥ عَذَابٌ عَظِيمٌ', '4d46f9f3f8d1384528f31197255b237728bc8d70447f02f538dafdab4964ebd5', '4d46f9f3f8d1384528f31197255b237728bc8d70447f02f538dafdab4964ebd5', NULL, 'ان الذين جاءو بالافك عصبه منكم لا تحسبوه شرا لكم بل هو خير لكم لكل امرئ منهم ما اكتسب من الاثم والذي تولي كبره منهم له عذاب عظيم', 18, 35, 140, 1, 4, 351, false, NULL),
    (2803, 'tanzil-uthmani-v1.1', 24, 12, 'لَّوْلَآ إِذْ سَمِعْتُمُوهُ ظَنَّ ٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بِأَنفُسِهِمْ خَيْرًا وَقَالُوا۟ هَٰذَآ إِفْكٌ مُّبِينٌ', '3fb289017e2cd13b59f776d0871127517e30eee3ef3fae6bccb845a6d9bc0213', 'لَّوْلَآ إِذْ سَمِعْتُمُوهُ ظَنَّ ٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بِأَنفُسِهِمْ خَيْرًا وَقَالُوا۟ هَٰذَآ إِفْكٌ مُّبِينٌ', '3fb289017e2cd13b59f776d0871127517e30eee3ef3fae6bccb845a6d9bc0213', '3fb289017e2cd13b59f776d0871127517e30eee3ef3fae6bccb845a6d9bc0213', NULL, 'لولا اذ سمعتموه ظن المؤمنون والمؤمنت بانفسهم خيرا وقالوا هذا افك مبين', 18, 35, 140, 1, 4, 351, false, NULL),
    (2804, 'tanzil-uthmani-v1.1', 24, 13, 'لَّوْلَا جَآءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ فَإِذْ لَمْ يَأْتُوا۟ بِٱلشُّهَدَآءِ فَأُو۟لَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلْكَٰذِبُونَ', 'cb6d018b6769e122e4933077ce9aaf0c2066ec0dbfc44c1a63540d1150c2b9f9', 'لَّوْلَا جَآءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ فَإِذْ لَمْ يَأْتُوا۟ بِٱلشُّهَدَآءِ فَأُو۟لَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلْكَٰذِبُونَ', 'cb6d018b6769e122e4933077ce9aaf0c2066ec0dbfc44c1a63540d1150c2b9f9', 'cb6d018b6769e122e4933077ce9aaf0c2066ec0dbfc44c1a63540d1150c2b9f9', NULL, 'لولا جاءو عليه باربعه شهداء فاذ لم ياتوا بالشهداء فاولئك عند الله هم الكذبون', 18, 35, 140, 1, 4, 351, false, NULL),
    (2805, 'tanzil-uthmani-v1.1', 24, 14, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ لَمَسَّكُمْ فِى مَآ أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ', '7cc7d7d90baa97a01d3947b4ef41fe36440f15276f2ca196c45d252c28e0d247', 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ لَمَسَّكُمْ فِى مَآ أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ', '7cc7d7d90baa97a01d3947b4ef41fe36440f15276f2ca196c45d252c28e0d247', '7cc7d7d90baa97a01d3947b4ef41fe36440f15276f2ca196c45d252c28e0d247', NULL, 'ولولا فضل الله عليكم ورحمته في الدنيا والاخره لمسكم في ما افضتم فيه عذاب عظيم', 18, 35, 140, 1, 4, 351, false, NULL),
    (2806, 'tanzil-uthmani-v1.1', 24, 15, 'إِذْ تَلَقَّوْنَهُۥ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَتَحْسَبُونَهُۥ هَيِّنًا وَهُوَ عِندَ ٱللَّهِ عَظِيمٌ', 'ed9960e7c83d8f1fde3c047903056ea5af8ed76484cacb4d679a3a1dd5eb6f32', 'إِذْ تَلَقَّوْنَهُۥ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَتَحْسَبُونَهُۥ هَيِّنًا وَهُوَ عِندَ ٱللَّهِ عَظِيمٌ', 'ed9960e7c83d8f1fde3c047903056ea5af8ed76484cacb4d679a3a1dd5eb6f32', 'ed9960e7c83d8f1fde3c047903056ea5af8ed76484cacb4d679a3a1dd5eb6f32', NULL, 'اذ تلقونه بالسنتكم وتقولون بافواهكم ما ليس لكم به علم وتحسبونه هينا وهو عند الله عظيم', 18, 35, 140, 1, 4, 351, false, NULL),
    (2807, 'tanzil-uthmani-v1.1', 24, 16, 'وَلَوْلَآ إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبْحَٰنَكَ هَٰذَا بُهْتَٰنٌ عَظِيمٌ', 'c141a5fa89ac679c67b401fa92232b6cf7b7e2e70ff849544a7e70026294ce4b', 'وَلَوْلَآ إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبْحَٰنَكَ هَٰذَا بُهْتَٰنٌ عَظِيمٌ', 'c141a5fa89ac679c67b401fa92232b6cf7b7e2e70ff849544a7e70026294ce4b', 'c141a5fa89ac679c67b401fa92232b6cf7b7e2e70ff849544a7e70026294ce4b', NULL, 'ولولا اذ سمعتموه قلتم ما يكون لنا ان نتكلم بهذا سبحنك هذا بهتن عظيم', 18, 35, 140, 1, 4, 351, false, NULL),
    (2808, 'tanzil-uthmani-v1.1', 24, 17, 'يَعِظُكُمُ ٱللَّهُ أَن تَعُودُوا۟ لِمِثْلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤْمِنِينَ', '13d035db5c649ee4f41f24841de3098412b163efe7579f5cc6bf559a1978dae8', 'يَعِظُكُمُ ٱللَّهُ أَن تَعُودُوا۟ لِمِثْلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤْمِنِينَ', '13d035db5c649ee4f41f24841de3098412b163efe7579f5cc6bf559a1978dae8', '13d035db5c649ee4f41f24841de3098412b163efe7579f5cc6bf559a1978dae8', NULL, 'يعظكم الله ان تعودوا لمثله ابدا ان كنتم مؤمنين', 18, 35, 140, 1, 4, 351, false, NULL),
    (2809, 'tanzil-uthmani-v1.1', 24, 18, 'وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '23be334a0682fab8db84881add5e40194ecc4c4467de17cf55e0496d0b55c577', 'وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '23be334a0682fab8db84881add5e40194ecc4c4467de17cf55e0496d0b55c577', '23be334a0682fab8db84881add5e40194ecc4c4467de17cf55e0496d0b55c577', NULL, 'ويبين الله لكم الايت والله عليم حكيم', 18, 35, 140, 1, 4, 351, false, NULL),
    (2810, 'tanzil-uthmani-v1.1', 24, 19, 'إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلْفَٰحِشَةُ فِى ٱلَّذِينَ ءَامَنُوا۟ لَهُمْ عَذَابٌ أَلِيمٌ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '34faf159a0f3c5691aa1f78daee4b3031aa94c292272dfe13388f0abc9bb7495', 'إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلْفَٰحِشَةُ فِى ٱلَّذِينَ ءَامَنُوا۟ لَهُمْ عَذَابٌ أَلِيمٌ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', '34faf159a0f3c5691aa1f78daee4b3031aa94c292272dfe13388f0abc9bb7495', '34faf159a0f3c5691aa1f78daee4b3031aa94c292272dfe13388f0abc9bb7495', NULL, 'ان الذين يحبون ان تشيع الفحشه في الذين ءامنوا لهم عذاب اليم في الدنيا والاخره والله يعلم وانتم لا تعلمون', 18, 35, 140, 1, 4, 351, false, NULL),
    (2811, 'tanzil-uthmani-v1.1', 24, 20, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٌ رَّحِيمٌ', '2cc233a6b47678c57b5e2d0fc283a49dd2bac956c2d5c57461da270d84adb937', 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٌ رَّحِيمٌ', '2cc233a6b47678c57b5e2d0fc283a49dd2bac956c2d5c57461da270d84adb937', '2cc233a6b47678c57b5e2d0fc283a49dd2bac956c2d5c57461da270d84adb937', NULL, 'ولولا فضل الله عليكم ورحمته وان الله رءوف رحيم', 18, 35, 140, 1, 4, 351, false, NULL),
    (2812, 'tanzil-uthmani-v1.1', 24, 21, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ وَمَن يَتَّبِعْ خُطُوَٰتِ ٱلشَّيْطَٰنِ فَإِنَّهُۥ يَأْمُرُ بِٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًا وَلَٰكِنَّ ٱللَّهَ يُزَكِّى مَن يَشَآءُ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '2bcb795eec460d7b06a030b3d83da372b5b19b5d7033388525ecbb2b971cd617', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ وَمَن يَتَّبِعْ خُطُوَٰتِ ٱلشَّيْطَٰنِ فَإِنَّهُۥ يَأْمُرُ بِٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًا وَلَٰكِنَّ ٱللَّهَ يُزَكِّى مَن يَشَآءُ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', '2bcb795eec460d7b06a030b3d83da372b5b19b5d7033388525ecbb2b971cd617', '2bcb795eec460d7b06a030b3d83da372b5b19b5d7033388525ecbb2b971cd617', NULL, 'يايها الذين ءامنوا لا تتبعوا خطوت الشيطن ومن يتبع خطوت الشيطن فانه يامر بالفحشاء والمنكر ولولا فضل الله عليكم ورحمته ما زكي منكم من احد ابدا ولكن الله يزكي من يشاء والله سميع عليم', 18, 36, 141, 1, 4, 352, false, NULL),
    (2813, 'tanzil-uthmani-v1.1', 24, 22, 'وَلَا يَأْتَلِ أُو۟لُوا۟ ٱلْفَضْلِ مِنكُمْ وَٱلسَّعَةِ أَن يُؤْتُوٓا۟ أُو۟لِى ٱلْقُرْبَىٰ وَٱلْمَسَٰكِينَ وَٱلْمُهَٰجِرِينَ فِى سَبِيلِ ٱللَّهِ وَلْيَعْفُوا۟ وَلْيَصْفَحُوٓا۟ أَلَا تُحِبُّونَ أَن يَغْفِرَ ٱللَّهُ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '0ebaa67798f20fe665072d86d66df275125b6f5c393d81aafcca420fd0d65a91', 'وَلَا يَأْتَلِ أُو۟لُوا۟ ٱلْفَضْلِ مِنكُمْ وَٱلسَّعَةِ أَن يُؤْتُوٓا۟ أُو۟لِى ٱلْقُرْبَىٰ وَٱلْمَسَٰكِينَ وَٱلْمُهَٰجِرِينَ فِى سَبِيلِ ٱللَّهِ وَلْيَعْفُوا۟ وَلْيَصْفَحُوٓا۟ أَلَا تُحِبُّونَ أَن يَغْفِرَ ٱللَّهُ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '0ebaa67798f20fe665072d86d66df275125b6f5c393d81aafcca420fd0d65a91', '0ebaa67798f20fe665072d86d66df275125b6f5c393d81aafcca420fd0d65a91', NULL, 'ولا ياتل اولوا الفضل منكم والسعه ان يؤتوا اولي القربي والمسكين والمهجرين في سبيل الله وليعفوا وليصفحوا الا تحبون ان يغفر الله لكم والله غفور رحيم', 18, 36, 141, 1, 4, 352, false, NULL),
    (2814, 'tanzil-uthmani-v1.1', 24, 23, 'إِنَّ ٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ٱلْغَٰفِلَٰتِ ٱلْمُؤْمِنَٰتِ لُعِنُوا۟ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'c61dab5b8add9d9cbd90f483858cae39e5787104a36e8a640c794ec9f2418b8b', 'إِنَّ ٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ٱلْغَٰفِلَٰتِ ٱلْمُؤْمِنَٰتِ لُعِنُوا۟ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ', 'c61dab5b8add9d9cbd90f483858cae39e5787104a36e8a640c794ec9f2418b8b', 'c61dab5b8add9d9cbd90f483858cae39e5787104a36e8a640c794ec9f2418b8b', NULL, 'ان الذين يرمون المحصنت الغفلت المؤمنت لعنوا في الدنيا والاخره ولهم عذاب عظيم', 18, 36, 141, 1, 4, 352, false, NULL),
    (2815, 'tanzil-uthmani-v1.1', 24, 24, 'يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', '133be420a497c2c61ac40d2326cc83d5ea95825d13390bad27d6bfebffbe917f', 'يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', '133be420a497c2c61ac40d2326cc83d5ea95825d13390bad27d6bfebffbe917f', '133be420a497c2c61ac40d2326cc83d5ea95825d13390bad27d6bfebffbe917f', NULL, 'يوم تشهد عليهم السنتهم وايديهم وارجلهم بما كانوا يعملون', 18, 36, 141, 1, 4, 352, false, NULL),
    (2816, 'tanzil-uthmani-v1.1', 24, 25, 'يَوْمَئِذٍ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلْحَقَّ وَيَعْلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ ٱلْمُبِينُ', '66b2b841433d6faadda575b90e38161120a2d16c9fbb60689d349ef5e288855b', 'يَوْمَئِذٍ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلْحَقَّ وَيَعْلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ ٱلْمُبِينُ', '66b2b841433d6faadda575b90e38161120a2d16c9fbb60689d349ef5e288855b', '66b2b841433d6faadda575b90e38161120a2d16c9fbb60689d349ef5e288855b', NULL, 'يومئذ يوفيهم الله دينهم الحق ويعلمون ان الله هو الحق المبين', 18, 36, 141, 1, 4, 352, false, NULL),
    (2817, 'tanzil-uthmani-v1.1', 24, 26, 'ٱلْخَبِيثَٰتُ لِلْخَبِيثِينَ وَٱلْخَبِيثُونَ لِلْخَبِيثَٰتِ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِ أُو۟لَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '054e0f4e03719f467830c24e141c014e1be03665c8c3c80ea69dbe1308d3eea0', 'ٱلْخَبِيثَٰتُ لِلْخَبِيثِينَ وَٱلْخَبِيثُونَ لِلْخَبِيثَٰتِ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِ أُو۟لَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', '054e0f4e03719f467830c24e141c014e1be03665c8c3c80ea69dbe1308d3eea0', '054e0f4e03719f467830c24e141c014e1be03665c8c3c80ea69dbe1308d3eea0', NULL, 'الخبيثت للخبيثين والخبيثون للخبيثت والطيبت للطيبين والطيبون للطيبت اولئك مبرءون مما يقولون لهم مغفره ورزق كريم', 18, 36, 141, 1, 4, 352, false, NULL),
    (2818, 'tanzil-uthmani-v1.1', 24, 27, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا۟ وَتُسَلِّمُوا۟ عَلَىٰٓ أَهْلِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', '6df161c0f17c0edd4455e93ee28b360d63356fd81e92f35a94daa933cd5f8ffb', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا۟ وَتُسَلِّمُوا۟ عَلَىٰٓ أَهْلِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', '6df161c0f17c0edd4455e93ee28b360d63356fd81e92f35a94daa933cd5f8ffb', '6df161c0f17c0edd4455e93ee28b360d63356fd81e92f35a94daa933cd5f8ffb', NULL, 'يايها الذين ءامنوا لا تدخلوا بيوتا غير بيوتكم حتي تستانسوا وتسلموا علي اهلها ذلكم خير لكم لعلكم تذكرون', 18, 36, 141, 1, 4, 352, false, NULL),
    (2819, 'tanzil-uthmani-v1.1', 24, 28, 'فَإِن لَّمْ تَجِدُوا۟ فِيهَآ أَحَدًا فَلَا تَدْخُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ وَإِن قِيلَ لَكُمُ ٱرْجِعُوا۟ فَٱرْجِعُوا۟ هُوَ أَزْكَىٰ لَكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', 'e15163a132307f65840d08497ed1f2e3794b23d8f00e546e8c829db52a7cb6c3', 'فَإِن لَّمْ تَجِدُوا۟ فِيهَآ أَحَدًا فَلَا تَدْخُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ وَإِن قِيلَ لَكُمُ ٱرْجِعُوا۟ فَٱرْجِعُوا۟ هُوَ أَزْكَىٰ لَكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ', 'e15163a132307f65840d08497ed1f2e3794b23d8f00e546e8c829db52a7cb6c3', 'e15163a132307f65840d08497ed1f2e3794b23d8f00e546e8c829db52a7cb6c3', NULL, 'فان لم تجدوا فيها احدا فلا تدخلوها حتي يؤذن لكم وان قيل لكم ارجعوا فارجعوا هو ازكي لكم والله بما تعملون عليم', 18, 36, 141, 1, 4, 353, false, NULL),
    (2820, 'tanzil-uthmani-v1.1', 24, 29, 'لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُوا۟ بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَٰعٌ لَّكُمْ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', '60a16c74de9c9a104548c54b24707f940369bda13a141c684913d585046f7ac0', 'لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُوا۟ بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَٰعٌ لَّكُمْ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', '60a16c74de9c9a104548c54b24707f940369bda13a141c684913d585046f7ac0', '60a16c74de9c9a104548c54b24707f940369bda13a141c684913d585046f7ac0', NULL, 'ليس عليكم جناح ان تدخلوا بيوتا غير مسكونه فيها متع لكم والله يعلم ما تبدون وما تكتمون', 18, 36, 141, 1, 4, 353, false, NULL),
    (2821, 'tanzil-uthmani-v1.1', 24, 30, 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَٰرِهِمْ وَيَحْفَظُوا۟ فُرُوجَهُمْ ذَٰلِكَ أَزْكَىٰ لَهُمْ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا يَصْنَعُونَ', '442c2640ba6b67b01b2815ca58e28885f0a9548cd247f83f556dfa02f236262a', 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَٰرِهِمْ وَيَحْفَظُوا۟ فُرُوجَهُمْ ذَٰلِكَ أَزْكَىٰ لَهُمْ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا يَصْنَعُونَ', '442c2640ba6b67b01b2815ca58e28885f0a9548cd247f83f556dfa02f236262a', '442c2640ba6b67b01b2815ca58e28885f0a9548cd247f83f556dfa02f236262a', NULL, 'قل للمؤمنين يغضوا من ابصرهم ويحفظوا فروجهم ذلك ازكي لهم ان الله خبير بما يصنعون', 18, 36, 141, 1, 4, 353, false, NULL),
    (2822, 'tanzil-uthmani-v1.1', 24, 31, 'وَقُل لِّلْمُؤْمِنَٰتِ يَغْضُضْنَ مِنْ أَبْصَٰرِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ أَوْ أَبْنَآئِهِنَّ أَوْ أَبْنَآءِ بُعُولَتِهِنَّ أَوْ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ أَخَوَٰتِهِنَّ أَوْ نِسَآئِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيْرِ أُو۟لِى ٱلْإِرْبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفْلِ ٱلَّذِينَ لَمْ يَظْهَرُوا۟ عَلَىٰ عَوْرَٰتِ ٱلنِّسَآءِ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ وَتُوبُوٓا۟ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ', '22d579d444798ec6bfc7f6878e6a97a3b2e537dd6b13cb592f91b5117fbb3f67', 'وَقُل لِّلْمُؤْمِنَٰتِ يَغْضُضْنَ مِنْ أَبْصَٰرِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ أَوْ أَبْنَآئِهِنَّ أَوْ أَبْنَآءِ بُعُولَتِهِنَّ أَوْ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ أَخَوَٰتِهِنَّ أَوْ نِسَآئِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيْرِ أُو۟لِى ٱلْإِرْبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفْلِ ٱلَّذِينَ لَمْ يَظْهَرُوا۟ عَلَىٰ عَوْرَٰتِ ٱلنِّسَآءِ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ وَتُوبُوٓا۟ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ', '22d579d444798ec6bfc7f6878e6a97a3b2e537dd6b13cb592f91b5117fbb3f67', '22d579d444798ec6bfc7f6878e6a97a3b2e537dd6b13cb592f91b5117fbb3f67', NULL, 'وقل للمؤمنت يغضضن من ابصرهن ويحفظن فروجهن ولا يبدين زينتهن الا ما ظهر منها وليضربن بخمرهن علي جيوبهن ولا يبدين زينتهن الا لبعولتهن او ءابائهن او ءاباء بعولتهن او ابنائهن او ابناء بعولتهن او اخونهن او بني اخونهن او بني اخوتهن او نسائهن او ما ملكت ايمنهن او التبعين غير اولي الاربه من الرجال او الطفل الذين لم يظهروا علي عورت النساء ولا يضربن بارجلهن ليعلم ما يخفين من زينتهن وتوبوا الي الله جميعا ايه المؤمنون لعلكم تفلحون', 18, 36, 141, 1, 4, 353, false, NULL),
    (2823, 'tanzil-uthmani-v1.1', 24, 32, 'وَأَنكِحُوا۟ ٱلْأَيَٰمَىٰ مِنكُمْ وَٱلصَّٰلِحِينَ مِنْ عِبَادِكُمْ وَإِمَآئِكُمْ إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '607029f68b8d8b87bbb592871a23003ffb6a5eb619786eca79a97ac2f6c59eae', 'وَأَنكِحُوا۟ ٱلْأَيَٰمَىٰ مِنكُمْ وَٱلصَّٰلِحِينَ مِنْ عِبَادِكُمْ وَإِمَآئِكُمْ إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', '607029f68b8d8b87bbb592871a23003ffb6a5eb619786eca79a97ac2f6c59eae', '607029f68b8d8b87bbb592871a23003ffb6a5eb619786eca79a97ac2f6c59eae', NULL, 'وانكحوا الايمي منكم والصلحين من عبادكم وامائكم ان يكونوا فقراء يغنهم الله من فضله والله وسع عليم', 18, 36, 141, 1, 4, 354, false, NULL),
    (2824, 'tanzil-uthmani-v1.1', 24, 33, 'وَلْيَسْتَعْفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَٱلَّذِينَ يَبْتَغُونَ ٱلْكِتَٰبَ مِمَّا مَلَكَتْ أَيْمَٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِىٓ ءَاتَىٰكُمْ وَلَا تُكْرِهُوا۟ فَتَيَٰتِكُمْ عَلَى ٱلْبِغَآءِ إِنْ أَرَدْنَ تَحَصُّنًا لِّتَبْتَغُوا۟ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَن يُكْرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعْدِ إِكْرَٰهِهِنَّ غَفُورٌ رَّحِيمٌ', 'a002921f63b710ed8fbe90ec4cf2e34117836f89718a2e0fa704b897c04492d2', 'وَلْيَسْتَعْفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَٱلَّذِينَ يَبْتَغُونَ ٱلْكِتَٰبَ مِمَّا مَلَكَتْ أَيْمَٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِىٓ ءَاتَىٰكُمْ وَلَا تُكْرِهُوا۟ فَتَيَٰتِكُمْ عَلَى ٱلْبِغَآءِ إِنْ أَرَدْنَ تَحَصُّنًا لِّتَبْتَغُوا۟ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَن يُكْرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعْدِ إِكْرَٰهِهِنَّ غَفُورٌ رَّحِيمٌ', 'a002921f63b710ed8fbe90ec4cf2e34117836f89718a2e0fa704b897c04492d2', 'a002921f63b710ed8fbe90ec4cf2e34117836f89718a2e0fa704b897c04492d2', NULL, 'وليستعفف الذين لا يجدون نكاحا حتي يغنيهم الله من فضله والذين يبتغون الكتب مما ملكت ايمنكم فكاتبوهم ان علمتم فيهم خيرا وءاتوهم من مال الله الذي ءاتيكم ولا تكرهوا فتيتكم علي البغاء ان اردن تحصنا لتبتغوا عرض الحيوه الدنيا ومن يكرههن فان الله من بعد اكرههن غفور رحيم', 18, 36, 141, 1, 4, 354, false, NULL),
    (2825, 'tanzil-uthmani-v1.1', 24, 34, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكُمْ ءَايَٰتٍ مُّبَيِّنَٰتٍ وَمَثَلًا مِّنَ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُمْ وَمَوْعِظَةً لِّلْمُتَّقِينَ', '9c9c55f182bda07bd7413a83d753919661f14f5fbadf4aad547c9c80ed40863c', 'وَلَقَدْ أَنزَلْنَآ إِلَيْكُمْ ءَايَٰتٍ مُّبَيِّنَٰتٍ وَمَثَلًا مِّنَ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُمْ وَمَوْعِظَةً لِّلْمُتَّقِينَ', '9c9c55f182bda07bd7413a83d753919661f14f5fbadf4aad547c9c80ed40863c', '9c9c55f182bda07bd7413a83d753919661f14f5fbadf4aad547c9c80ed40863c', NULL, 'ولقد انزلنا اليكم ءايت مبينت ومثلا من الذين خلوا من قبلكم وموعظه للمتقين', 18, 36, 141, 1, 4, 354, false, NULL),
    (2826, 'tanzil-uthmani-v1.1', 24, 35, 'ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ مَثَلُ نُورِهِۦ كَمِشْكَوٰةٍ فِيهَا مِصْبَاحٌ ٱلْمِصْبَاحُ فِى زُجَاجَةٍ ٱلزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّىٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَٰرَكَةٍ زَيْتُونَةٍ لَّا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِىٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ نُّورٌ عَلَىٰ نُورٍ يَهْدِى ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَٰلَ لِلنَّاسِ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'd99641a762fb4391dd2b173db5030fce09692b8b88bd501d6d0ed5899cf01147', 'ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ مَثَلُ نُورِهِۦ كَمِشْكَوٰةٍ فِيهَا مِصْبَاحٌ ٱلْمِصْبَاحُ فِى زُجَاجَةٍ ٱلزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّىٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَٰرَكَةٍ زَيْتُونَةٍ لَّا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِىٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ نُّورٌ عَلَىٰ نُورٍ يَهْدِى ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَٰلَ لِلنَّاسِ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 'd99641a762fb4391dd2b173db5030fce09692b8b88bd501d6d0ed5899cf01147', 'd99641a762fb4391dd2b173db5030fce09692b8b88bd501d6d0ed5899cf01147', NULL, 'الله نور السموت والارض مثل نوره كمشكوه فيها مصباح المصباح في زجاجه الزجاجه كانها كوكب دري يوقد من شجره مبركه زيتونه لا شرقيه ولا غربيه يكاد زيتها يضيء ولو لم تمسسه نار نور علي نور يهدي الله لنوره من يشاء ويضرب الله الامثل للناس والله بكل شيء عليم', 18, 36, 142, 1, 4, 354, false, NULL),
    (2827, 'tanzil-uthmani-v1.1', 24, 36, 'فِى بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا ٱسْمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ', 'b71d6a4570fa52aadd7ce565518e4580be002d7a1c0dbe19c3a8c927d6936ae3', 'فِى بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا ٱسْمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ', 'b71d6a4570fa52aadd7ce565518e4580be002d7a1c0dbe19c3a8c927d6936ae3', 'b71d6a4570fa52aadd7ce565518e4580be002d7a1c0dbe19c3a8c927d6936ae3', NULL, 'في بيوت اذن الله ان ترفع ويذكر فيها اسمه يسبح له فيها بالغدو والاصال', 18, 36, 142, 1, 4, 354, false, NULL),
    (2828, 'tanzil-uthmani-v1.1', 24, 37, 'رِجَالٌ لَّا تُلْهِيهِمْ تِجَٰرَةٌ وَلَا بَيْعٌ عَن ذِكْرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ ٱلْقُلُوبُ وَٱلْأَبْصَٰرُ', 'be558bf776a4ef71f79ccb294141fb3b7371d221744c04a0580c7866666243ee', 'رِجَالٌ لَّا تُلْهِيهِمْ تِجَٰرَةٌ وَلَا بَيْعٌ عَن ذِكْرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ ٱلْقُلُوبُ وَٱلْأَبْصَٰرُ', 'be558bf776a4ef71f79ccb294141fb3b7371d221744c04a0580c7866666243ee', 'be558bf776a4ef71f79ccb294141fb3b7371d221744c04a0580c7866666243ee', NULL, 'رجال لا تلهيهم تجره ولا بيع عن ذكر الله واقام الصلوه وايتاء الزكوه يخافون يوما تتقلب فيه القلوب والابصر', 18, 36, 142, 1, 4, 355, false, NULL),
    (2829, 'tanzil-uthmani-v1.1', 24, 38, 'لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا عَمِلُوا۟ وَيَزِيدَهُم مِّن فَضْلِهِۦ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', '03383b6e09bdf16d7ad9d16705782ffecf0a22e6b725f84b9c4aca537a421de7', 'لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا عَمِلُوا۟ وَيَزِيدَهُم مِّن فَضْلِهِۦ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', '03383b6e09bdf16d7ad9d16705782ffecf0a22e6b725f84b9c4aca537a421de7', '03383b6e09bdf16d7ad9d16705782ffecf0a22e6b725f84b9c4aca537a421de7', NULL, 'ليجزيهم الله احسن ما عملوا ويزيدهم من فضله والله يرزق من يشاء بغير حساب', 18, 36, 142, 1, 4, 355, false, NULL),
    (2830, 'tanzil-uthmani-v1.1', 24, 39, 'وَٱلَّذِينَ كَفَرُوٓا۟ أَعْمَٰلُهُمْ كَسَرَابٍۭ بِقِيعَةٍ يَحْسَبُهُ ٱلظَّمْـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمْ يَجِدْهُ شَيْـًٔا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 'd2e424f4ba40fecab0cf9f0931b8aa065041cca86308ace848169bdd00b1cd83', 'وَٱلَّذِينَ كَفَرُوٓا۟ أَعْمَٰلُهُمْ كَسَرَابٍۭ بِقِيعَةٍ يَحْسَبُهُ ٱلظَّمْـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمْ يَجِدْهُ شَيْـًٔا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 'd2e424f4ba40fecab0cf9f0931b8aa065041cca86308ace848169bdd00b1cd83', 'd2e424f4ba40fecab0cf9f0931b8aa065041cca86308ace848169bdd00b1cd83', NULL, 'والذين كفروا اعملهم كسراب بقيعه يحسبه الظمان ماء حتي اذا جاءه لم يجده شيا ووجد الله عنده فوفيه حسابه والله سريع الحساب', 18, 36, 142, 1, 4, 355, false, NULL),
    (2831, 'tanzil-uthmani-v1.1', 24, 40, 'أَوْ كَظُلُمَٰتٍ فِى بَحْرٍ لُّجِّىٍّ يَغْشَىٰهُ مَوْجٌ مِّن فَوْقِهِۦ مَوْجٌ مِّن فَوْقِهِۦ سَحَابٌ ظُلُمَٰتٌۢ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرَىٰهَا وَمَن لَّمْ يَجْعَلِ ٱللَّهُ لَهُۥ نُورًا فَمَا لَهُۥ مِن نُّورٍ', '4c2773d21b62a0cac543a1268d2ec696e815df37bb70c10e241f939973579b11', 'أَوْ كَظُلُمَٰتٍ فِى بَحْرٍ لُّجِّىٍّ يَغْشَىٰهُ مَوْجٌ مِّن فَوْقِهِۦ مَوْجٌ مِّن فَوْقِهِۦ سَحَابٌ ظُلُمَٰتٌۢ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرَىٰهَا وَمَن لَّمْ يَجْعَلِ ٱللَّهُ لَهُۥ نُورًا فَمَا لَهُۥ مِن نُّورٍ', '4c2773d21b62a0cac543a1268d2ec696e815df37bb70c10e241f939973579b11', '4c2773d21b62a0cac543a1268d2ec696e815df37bb70c10e241f939973579b11', NULL, 'او كظلمت في بحر لجي يغشيه موج من فوقه موج من فوقه سحاب ظلمت بعضها فوق بعض اذا اخرج يده لم يكد يريها ومن لم يجعل الله له نورا فما له من نور', 18, 36, 142, 1, 4, 355, false, NULL),
    (2832, 'tanzil-uthmani-v1.1', 24, 41, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلطَّيْرُ صَٰٓفَّٰتٍ كُلٌّ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ وَٱللَّهُ عَلِيمٌۢ بِمَا يَفْعَلُونَ', '0037ee255e547f7a65fa34c69b5aa04625d1c87533db1c964be806ec42aa2da0', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلطَّيْرُ صَٰٓفَّٰتٍ كُلٌّ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ وَٱللَّهُ عَلِيمٌۢ بِمَا يَفْعَلُونَ', '0037ee255e547f7a65fa34c69b5aa04625d1c87533db1c964be806ec42aa2da0', '0037ee255e547f7a65fa34c69b5aa04625d1c87533db1c964be806ec42aa2da0', NULL, 'الم تر ان الله يسبح له من في السموت والارض والطير صفت كل قد علم صلاته وتسبيحه والله عليم بما يفعلون', 18, 36, 142, 1, 4, 355, false, NULL),
    (2833, 'tanzil-uthmani-v1.1', 24, 42, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'bbd8bb1d9d6488d11cf535f352cdc2c2e49afa035524dfce091ac67613493daf', 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 'bbd8bb1d9d6488d11cf535f352cdc2c2e49afa035524dfce091ac67613493daf', 'bbd8bb1d9d6488d11cf535f352cdc2c2e49afa035524dfce091ac67613493daf', NULL, 'ولله ملك السموت والارض والي الله المصير', 18, 36, 142, 1, 4, 355, false, NULL),
    (2834, 'tanzil-uthmani-v1.1', 24, 43, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُزْجِى سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهُۥ ثُمَّ يَجْعَلُهُۥ رُكَامًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٍ فِيهَا مِنۢ بَرَدٍ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصْرِفُهُۥ عَن مَّن يَشَآءُ يَكَادُ سَنَا بَرْقِهِۦ يَذْهَبُ بِٱلْأَبْصَٰرِ', '8b077052238816dc5673fda1c60d7bac1880a24e4b76db821c2f4581f098bf9d', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُزْجِى سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهُۥ ثُمَّ يَجْعَلُهُۥ رُكَامًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٍ فِيهَا مِنۢ بَرَدٍ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصْرِفُهُۥ عَن مَّن يَشَآءُ يَكَادُ سَنَا بَرْقِهِۦ يَذْهَبُ بِٱلْأَبْصَٰرِ', '8b077052238816dc5673fda1c60d7bac1880a24e4b76db821c2f4581f098bf9d', '8b077052238816dc5673fda1c60d7bac1880a24e4b76db821c2f4581f098bf9d', NULL, 'الم تر ان الله يزجي سحابا ثم يؤلف بينه ثم يجعله ركاما فتري الودق يخرج من خلله وينزل من السماء من جبال فيها من برد فيصيب به من يشاء ويصرفه عن من يشاء يكاد سنا برقه يذهب بالابصر', 18, 36, 142, 1, 4, 355, false, NULL),
    (2835, 'tanzil-uthmani-v1.1', 24, 44, 'يُقَلِّبُ ٱللَّهُ ٱلَّيْلَ وَٱلنَّهَارَ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَٰرِ', 'd5f0c29b8fc795ae29ce275c6908f3f9ab57bf43a84b502c6bdeaa07f242a1a3', 'يُقَلِّبُ ٱللَّهُ ٱلَّيْلَ وَٱلنَّهَارَ إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُو۟لِى ٱلْأَبْصَٰرِ', 'd5f0c29b8fc795ae29ce275c6908f3f9ab57bf43a84b502c6bdeaa07f242a1a3', 'd5f0c29b8fc795ae29ce275c6908f3f9ab57bf43a84b502c6bdeaa07f242a1a3', NULL, 'يقلب الله اليل والنهار ان في ذلك لعبره لاولي الابصر', 18, 36, 142, 1, 4, 356, false, NULL),
    (2836, 'tanzil-uthmani-v1.1', 24, 45, 'وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٍ مِّن مَّآءٍ فَمِنْهُم مَّن يَمْشِى عَلَىٰ بَطْنِهِۦ وَمِنْهُم مَّن يَمْشِى عَلَىٰ رِجْلَيْنِ وَمِنْهُم مَّن يَمْشِى عَلَىٰٓ أَرْبَعٍ يَخْلُقُ ٱللَّهُ مَا يَشَآءُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '81d424b536f5fcfe391f924999aa974053deb0956d9a14faf7a680dd490477d9', 'وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٍ مِّن مَّآءٍ فَمِنْهُم مَّن يَمْشِى عَلَىٰ بَطْنِهِۦ وَمِنْهُم مَّن يَمْشِى عَلَىٰ رِجْلَيْنِ وَمِنْهُم مَّن يَمْشِى عَلَىٰٓ أَرْبَعٍ يَخْلُقُ ٱللَّهُ مَا يَشَآءُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '81d424b536f5fcfe391f924999aa974053deb0956d9a14faf7a680dd490477d9', '81d424b536f5fcfe391f924999aa974053deb0956d9a14faf7a680dd490477d9', NULL, 'والله خلق كل دابه من ماء فمنهم من يمشي علي بطنه ومنهم من يمشي علي رجلين ومنهم من يمشي علي اربع يخلق الله ما يشاء ان الله علي كل شيء قدير', 18, 36, 142, 1, 4, 356, false, NULL),
    (2837, 'tanzil-uthmani-v1.1', 24, 46, 'لَّقَدْ أَنزَلْنَآ ءَايَٰتٍ مُّبَيِّنَٰتٍ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '00968c66c667cdbbb7571b8e69b7682dbbeaff586702eb60abc5504f8e56f22d', 'لَّقَدْ أَنزَلْنَآ ءَايَٰتٍ مُّبَيِّنَٰتٍ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '00968c66c667cdbbb7571b8e69b7682dbbeaff586702eb60abc5504f8e56f22d', '00968c66c667cdbbb7571b8e69b7682dbbeaff586702eb60abc5504f8e56f22d', NULL, 'لقد انزلنا ءايت مبينت والله يهدي من يشاء الي صرط مستقيم', 18, 36, 142, 1, 4, 356, false, NULL),
    (2838, 'tanzil-uthmani-v1.1', 24, 47, 'وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُم مِّنۢ بَعْدِ ذَٰلِكَ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 'ee2612335e7f1eca689d3e9427b8ffd86508c08229a618c1c79641cc6327de07', 'وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُم مِّنۢ بَعْدِ ذَٰلِكَ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 'ee2612335e7f1eca689d3e9427b8ffd86508c08229a618c1c79641cc6327de07', 'ee2612335e7f1eca689d3e9427b8ffd86508c08229a618c1c79641cc6327de07', NULL, 'ويقولون ءامنا بالله وبالرسول واطعنا ثم يتولي فريق منهم من بعد ذلك وما اولئك بالمؤمنين', 18, 36, 142, 1, 4, 356, false, NULL),
    (2839, 'tanzil-uthmani-v1.1', 24, 48, 'وَإِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌ مِّنْهُم مُّعْرِضُونَ', 'f89dfdcd6c56e2f32b8c51fa31c6935cf4d8b834b5821a59b58ad4818d11f092', 'وَإِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌ مِّنْهُم مُّعْرِضُونَ', 'f89dfdcd6c56e2f32b8c51fa31c6935cf4d8b834b5821a59b58ad4818d11f092', 'f89dfdcd6c56e2f32b8c51fa31c6935cf4d8b834b5821a59b58ad4818d11f092', NULL, 'واذا دعوا الي الله ورسوله ليحكم بينهم اذا فريق منهم معرضون', 18, 36, 142, 1, 4, 356, false, NULL),
    (2840, 'tanzil-uthmani-v1.1', 24, 49, 'وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ', 'f38ac2f0d9acd434716a46482587ac896ab559e0bf024f2493f1b46ad5819e68', 'وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ', 'f38ac2f0d9acd434716a46482587ac896ab559e0bf024f2493f1b46ad5819e68', 'f38ac2f0d9acd434716a46482587ac896ab559e0bf024f2493f1b46ad5819e68', NULL, 'وان يكن لهم الحق ياتوا اليه مذعنين', 18, 36, 142, 1, 4, 356, false, NULL),
    (2841, 'tanzil-uthmani-v1.1', 24, 50, 'أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ٱرْتَابُوٓا۟ أَمْ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ بَلْ أُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'a26b018215b4f823969f81a96b0b74441b176f8ed06a8633d80e0185cc8dff5e', 'أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ٱرْتَابُوٓا۟ أَمْ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ بَلْ أُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'a26b018215b4f823969f81a96b0b74441b176f8ed06a8633d80e0185cc8dff5e', 'a26b018215b4f823969f81a96b0b74441b176f8ed06a8633d80e0185cc8dff5e', NULL, 'افي قلوبهم مرض ام ارتابوا ام يخافون ان يحيف الله عليهم ورسوله بل اولئك هم الظلمون', 18, 36, 142, 1, 4, 356, false, NULL),
    (2842, 'tanzil-uthmani-v1.1', 24, 51, 'إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'ffeeaf3b883bae7794f6dd3ee39940e67c15481846c8bdc06ce2c95f2c09edd5', 'إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'ffeeaf3b883bae7794f6dd3ee39940e67c15481846c8bdc06ce2c95f2c09edd5', 'ffeeaf3b883bae7794f6dd3ee39940e67c15481846c8bdc06ce2c95f2c09edd5', NULL, 'انما كان قول المؤمنين اذا دعوا الي الله ورسوله ليحكم بينهم ان يقولوا سمعنا واطعنا واولئك هم المفلحون', 18, 36, 142, 1, 4, 356, false, NULL),
    (2843, 'tanzil-uthmani-v1.1', 24, 52, 'وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخْشَ ٱللَّهَ وَيَتَّقْهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', '2e131747d33a64004fd1561938fe430fccd14f299a2a4bb542df333dd055e40b', 'وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخْشَ ٱللَّهَ وَيَتَّقْهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', '2e131747d33a64004fd1561938fe430fccd14f299a2a4bb542df333dd055e40b', '2e131747d33a64004fd1561938fe430fccd14f299a2a4bb542df333dd055e40b', NULL, 'ومن يطع الله ورسوله ويخش الله ويتقه فاولئك هم الفائزون', 18, 36, 142, 1, 4, 356, false, NULL),
    (2844, 'tanzil-uthmani-v1.1', 24, 53, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ قُل لَّا تُقْسِمُوا۟ طَاعَةٌ مَّعْرُوفَةٌ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'c22ad9c91f8332ae3742e8e864629ff9bb349a7b36ef5f45d4dbf4891bdf1f00', 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ قُل لَّا تُقْسِمُوا۟ طَاعَةٌ مَّعْرُوفَةٌ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'c22ad9c91f8332ae3742e8e864629ff9bb349a7b36ef5f45d4dbf4891bdf1f00', 'c22ad9c91f8332ae3742e8e864629ff9bb349a7b36ef5f45d4dbf4891bdf1f00', NULL, 'واقسموا بالله جهد ايمنهم لئن امرتهم ليخرجن قل لا تقسموا طاعه معروفه ان الله خبير بما تعملون', 18, 36, 143, 1, 4, 356, false, NULL),
    (2845, 'tanzil-uthmani-v1.1', 24, 54, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ وَإِن تُطِيعُوهُ تَهْتَدُوا۟ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', '61c516470928e7b5bad0d70085660a4a9668d0781b88237c64238a10f2d224c7', 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ وَإِن تُطِيعُوهُ تَهْتَدُوا۟ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', '61c516470928e7b5bad0d70085660a4a9668d0781b88237c64238a10f2d224c7', '61c516470928e7b5bad0d70085660a4a9668d0781b88237c64238a10f2d224c7', NULL, 'قل اطيعوا الله واطيعوا الرسول فان تولوا فانما عليه ما حمل وعليكم ما حملتم وان تطيعوه تهتدوا وما علي الرسول الا البلغ المبين', 18, 36, 143, 1, 4, 357, false, NULL),
    (2846, 'tanzil-uthmani-v1.1', 24, 55, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَيَسْتَخْلِفَنَّهُمْ فِى ٱلْأَرْضِ كَمَا ٱسْتَخْلَفَ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ ٱلَّذِى ٱرْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعْدِ خَوْفِهِمْ أَمْنًا يَعْبُدُونَنِى لَا يُشْرِكُونَ بِى شَيْـًٔا وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', '4bc0ea123b2dd8499e386381820e563afc76854cf1eeef5f31ce652fe07c6950', 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَيَسْتَخْلِفَنَّهُمْ فِى ٱلْأَرْضِ كَمَا ٱسْتَخْلَفَ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ ٱلَّذِى ٱرْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعْدِ خَوْفِهِمْ أَمْنًا يَعْبُدُونَنِى لَا يُشْرِكُونَ بِى شَيْـًٔا وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', '4bc0ea123b2dd8499e386381820e563afc76854cf1eeef5f31ce652fe07c6950', '4bc0ea123b2dd8499e386381820e563afc76854cf1eeef5f31ce652fe07c6950', NULL, 'وعد الله الذين ءامنوا منكم وعملوا الصلحت ليستخلفنهم في الارض كما استخلف الذين من قبلهم وليمكنن لهم دينهم الذي ارتضي لهم وليبدلنهم من بعد خوفهم امنا يعبدونني لا يشركون بي شيا ومن كفر بعد ذلك فاولئك هم الفسقون', 18, 36, 143, 1, 4, 357, false, NULL),
    (2847, 'tanzil-uthmani-v1.1', 24, 56, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', '2c55885aa6a41a0a9e70c38d59d2114efaa0168324744aa5d929c58042835267', 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', '2c55885aa6a41a0a9e70c38d59d2114efaa0168324744aa5d929c58042835267', '2c55885aa6a41a0a9e70c38d59d2114efaa0168324744aa5d929c58042835267', NULL, 'واقيموا الصلوه وءاتوا الزكوه واطيعوا الرسول لعلكم ترحمون', 18, 36, 143, 1, 4, 357, false, NULL),
    (2848, 'tanzil-uthmani-v1.1', 24, 57, 'لَا تَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَأْوَىٰهُمُ ٱلنَّارُ وَلَبِئْسَ ٱلْمَصِيرُ', 'd6c141952a54ff45ba1e375856ed288771db7d4037f51fbb6906b412977f0f4c', 'لَا تَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَأْوَىٰهُمُ ٱلنَّارُ وَلَبِئْسَ ٱلْمَصِيرُ', 'd6c141952a54ff45ba1e375856ed288771db7d4037f51fbb6906b412977f0f4c', 'd6c141952a54ff45ba1e375856ed288771db7d4037f51fbb6906b412977f0f4c', NULL, 'لا تحسبن الذين كفروا معجزين في الارض وماويهم النار ولبئس المصير', 18, 36, 143, 1, 4, 357, false, NULL),
    (2849, 'tanzil-uthmani-v1.1', 24, 58, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِيَسْتَـْٔذِنكُمُ ٱلَّذِينَ مَلَكَتْ أَيْمَٰنُكُمْ وَٱلَّذِينَ لَمْ يَبْلُغُوا۟ ٱلْحُلُمَ مِنكُمْ ثَلَٰثَ مَرَّٰتٍ مِّن قَبْلِ صَلَوٰةِ ٱلْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعْدِ صَلَوٰةِ ٱلْعِشَآءِ ثَلَٰثُ عَوْرَٰتٍ لَّكُمْ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌۢ بَعْدَهُنَّ طَوَّٰفُونَ عَلَيْكُم بَعْضُكُمْ عَلَىٰ بَعْضٍ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '3216799ecd5938a6f18bbaf001ee79bbc497f061ba5e6afb515429c316aa2b52', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِيَسْتَـْٔذِنكُمُ ٱلَّذِينَ مَلَكَتْ أَيْمَٰنُكُمْ وَٱلَّذِينَ لَمْ يَبْلُغُوا۟ ٱلْحُلُمَ مِنكُمْ ثَلَٰثَ مَرَّٰتٍ مِّن قَبْلِ صَلَوٰةِ ٱلْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعْدِ صَلَوٰةِ ٱلْعِشَآءِ ثَلَٰثُ عَوْرَٰتٍ لَّكُمْ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌۢ بَعْدَهُنَّ طَوَّٰفُونَ عَلَيْكُم بَعْضُكُمْ عَلَىٰ بَعْضٍ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '3216799ecd5938a6f18bbaf001ee79bbc497f061ba5e6afb515429c316aa2b52', '3216799ecd5938a6f18bbaf001ee79bbc497f061ba5e6afb515429c316aa2b52', NULL, 'يايها الذين ءامنوا ليستذنكم الذين ملكت ايمنكم والذين لم يبلغوا الحلم منكم ثلث مرت من قبل صلوه الفجر وحين تضعون ثيابكم من الظهيره ومن بعد صلوه العشاء ثلث عورت لكم ليس عليكم ولا عليهم جناح بعدهن طوفون عليكم بعضكم علي بعض كذلك يبين الله لكم الايت والله عليم حكيم', 18, 36, 143, 1, 4, 357, false, NULL),
    (2850, 'tanzil-uthmani-v1.1', 24, 59, 'وَإِذَا بَلَغَ ٱلْأَطْفَٰلُ مِنكُمُ ٱلْحُلُمَ فَلْيَسْتَـْٔذِنُوا۟ كَمَا ٱسْتَـْٔذَنَ ٱلَّذِينَ مِن قَبْلِهِمْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'd18b9eab31759a842067f6e9b5550c5f422be24bd643662ca2a1d1ce6e3d295a', 'وَإِذَا بَلَغَ ٱلْأَطْفَٰلُ مِنكُمُ ٱلْحُلُمَ فَلْيَسْتَـْٔذِنُوا۟ كَمَا ٱسْتَـْٔذَنَ ٱلَّذِينَ مِن قَبْلِهِمْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 'd18b9eab31759a842067f6e9b5550c5f422be24bd643662ca2a1d1ce6e3d295a', 'd18b9eab31759a842067f6e9b5550c5f422be24bd643662ca2a1d1ce6e3d295a', NULL, 'واذا بلغ الاطفل منكم الحلم فليستذنوا كما استذن الذين من قبلهم كذلك يبين الله لكم ءايته والله عليم حكيم', 18, 36, 143, 1, 4, 358, false, NULL),
    (2851, 'tanzil-uthmani-v1.1', 24, 60, 'وَٱلْقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِى لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَٰتٍۭ بِزِينَةٍ وَأَن يَسْتَعْفِفْنَ خَيْرٌ لَّهُنَّ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'e1333a3875fa61eecaeb6db12c7004b04f66fe5c42ae0d8be0e699d178701a18', 'وَٱلْقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِى لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَٰتٍۭ بِزِينَةٍ وَأَن يَسْتَعْفِفْنَ خَيْرٌ لَّهُنَّ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 'e1333a3875fa61eecaeb6db12c7004b04f66fe5c42ae0d8be0e699d178701a18', 'e1333a3875fa61eecaeb6db12c7004b04f66fe5c42ae0d8be0e699d178701a18', NULL, 'والقوعد من النساء التي لا يرجون نكاحا فليس عليهن جناح ان يضعن ثيابهن غير متبرجت بزينه وان يستعففن خير لهن والله سميع عليم', 18, 36, 143, 1, 4, 358, false, NULL),
    (2852, 'tanzil-uthmani-v1.1', 24, 61, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ وَلَا عَلَىٰٓ أَنفُسِكُمْ أَن تَأْكُلُوا۟ مِنۢ بُيُوتِكُمْ أَوْ بُيُوتِ ءَابَآئِكُمْ أَوْ بُيُوتِ أُمَّهَٰتِكُمْ أَوْ بُيُوتِ إِخْوَٰنِكُمْ أَوْ بُيُوتِ أَخَوَٰتِكُمْ أَوْ بُيُوتِ أَعْمَٰمِكُمْ أَوْ بُيُوتِ عَمَّٰتِكُمْ أَوْ بُيُوتِ أَخْوَٰلِكُمْ أَوْ بُيُوتِ خَٰلَٰتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُۥٓ أَوْ صَدِيقِكُمْ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا۟ جَمِيعًا أَوْ أَشْتَاتًا فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا۟ عَلَىٰٓ أَنفُسِكُمْ تَحِيَّةً مِّنْ عِندِ ٱللَّهِ مُبَٰرَكَةً طَيِّبَةً كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', '0346714dc3e646b856fd069baa547b84fee503036cb2d2bb92b096463df7237d', 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ وَلَا عَلَىٰٓ أَنفُسِكُمْ أَن تَأْكُلُوا۟ مِنۢ بُيُوتِكُمْ أَوْ بُيُوتِ ءَابَآئِكُمْ أَوْ بُيُوتِ أُمَّهَٰتِكُمْ أَوْ بُيُوتِ إِخْوَٰنِكُمْ أَوْ بُيُوتِ أَخَوَٰتِكُمْ أَوْ بُيُوتِ أَعْمَٰمِكُمْ أَوْ بُيُوتِ عَمَّٰتِكُمْ أَوْ بُيُوتِ أَخْوَٰلِكُمْ أَوْ بُيُوتِ خَٰلَٰتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُۥٓ أَوْ صَدِيقِكُمْ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا۟ جَمِيعًا أَوْ أَشْتَاتًا فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا۟ عَلَىٰٓ أَنفُسِكُمْ تَحِيَّةً مِّنْ عِندِ ٱللَّهِ مُبَٰرَكَةً طَيِّبَةً كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', '0346714dc3e646b856fd069baa547b84fee503036cb2d2bb92b096463df7237d', '0346714dc3e646b856fd069baa547b84fee503036cb2d2bb92b096463df7237d', NULL, 'ليس علي الاعمي حرج ولا علي الاعرج حرج ولا علي المريض حرج ولا علي انفسكم ان تاكلوا من بيوتكم او بيوت ءابائكم او بيوت امهتكم او بيوت اخونكم او بيوت اخوتكم او بيوت اعممكم او بيوت عمتكم او بيوت اخولكم او بيوت خلتكم او ما ملكتم مفاتحه او صديقكم ليس عليكم جناح ان تاكلوا جميعا او اشتاتا فاذا دخلتم بيوتا فسلموا علي انفسكم تحيه من عند الله مبركه طيبه كذلك يبين الله لكم الايت لعلكم تعقلون', 18, 36, 143, 1, 4, 358, false, NULL),
    (2853, 'tanzil-uthmani-v1.1', 24, 62, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا۟ مَعَهُۥ عَلَىٰٓ أَمْرٍ جَامِعٍ لَّمْ يَذْهَبُوا۟ حَتَّىٰ يَسْتَـْٔذِنُوهُ إِنَّ ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ أُو۟لَٰٓئِكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ فَإِذَا ٱسْتَـْٔذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَٱسْتَغْفِرْ لَهُمُ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '15b9ca35d658dab27c889845659d0e49941f62a8a1ed129bb1f2188ac9d7f158', 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا۟ مَعَهُۥ عَلَىٰٓ أَمْرٍ جَامِعٍ لَّمْ يَذْهَبُوا۟ حَتَّىٰ يَسْتَـْٔذِنُوهُ إِنَّ ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ أُو۟لَٰٓئِكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ فَإِذَا ٱسْتَـْٔذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَٱسْتَغْفِرْ لَهُمُ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '15b9ca35d658dab27c889845659d0e49941f62a8a1ed129bb1f2188ac9d7f158', '15b9ca35d658dab27c889845659d0e49941f62a8a1ed129bb1f2188ac9d7f158', NULL, 'انما المؤمنون الذين ءامنوا بالله ورسوله واذا كانوا معه علي امر جامع لم يذهبوا حتي يستذنوه ان الذين يستذنونك اولئك الذين يؤمنون بالله ورسوله فاذا استذنوك لبعض شانهم فاذن لمن شئت منهم واستغفر لهم الله ان الله غفور رحيم', 18, 36, 143, 1, 4, 359, false, NULL),
    (2854, 'tanzil-uthmani-v1.1', 24, 63, 'لَّا تَجْعَلُوا۟ دُعَآءَ ٱلرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم بَعْضًا قَدْ يَعْلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذًا فَلْيَحْذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ', 'ec21899d64d11ea7598e4e43719c155e96452be77c3a9d6bef22bc409fc02377', 'لَّا تَجْعَلُوا۟ دُعَآءَ ٱلرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم بَعْضًا قَدْ يَعْلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذًا فَلْيَحْذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ', 'ec21899d64d11ea7598e4e43719c155e96452be77c3a9d6bef22bc409fc02377', 'ec21899d64d11ea7598e4e43719c155e96452be77c3a9d6bef22bc409fc02377', NULL, 'لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا قد يعلم الله الذين يتسللون منكم لواذا فليحذر الذين يخالفون عن امره ان تصيبهم فتنه او يصيبهم عذاب اليم', 18, 36, 143, 1, 4, 359, false, NULL),
    (2855, 'tanzil-uthmani-v1.1', 24, 64, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُوا۟ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '7c93455353c2ea52247d51b2b061a59e3721398de2e306deb7a090f904515e47', 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُوا۟ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', '7c93455353c2ea52247d51b2b061a59e3721398de2e306deb7a090f904515e47', '7c93455353c2ea52247d51b2b061a59e3721398de2e306deb7a090f904515e47', NULL, 'الا ان لله ما في السموت والارض قد يعلم ما انتم عليه ويوم يرجعون اليه فينبئهم بما عملوا والله بكل شيء عليم', 18, 36, 143, 1, 4, 359, false, NULL),
    (2856, 'tanzil-uthmani-v1.1', 25, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَارَكَ ٱلَّذِى نَزَّلَ ٱلْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَٰلَمِينَ نَذِيرًا', '73f36279158a3854aedefc1616410f64f7a53a80326e8c173d4ba5515f933003', 'تَبَارَكَ ٱلَّذِى نَزَّلَ ٱلْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَٰلَمِينَ نَذِيرًا', '927aee68b9fd8ca61214ab8e1acefcf30c47c0910326fc0796b132e65d903386', '927aee68b9fd8ca61214ab8e1acefcf30c47c0910326fc0796b132e65d903386', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'تبارك الذي نزل الفرقان علي عبده ليكون للعلمين نذيرا', 18, 36, 144, 1, 4, 359, false, NULL),
    (2857, 'tanzil-uthmani-v1.1', 25, 2, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَخَلَقَ كُلَّ شَىْءٍ فَقَدَّرَهُۥ تَقْدِيرًا', 'b17bbc068a3657705c882c471b97684624b5b4889e3608e4b8349b80aa5326cc', 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى ٱلْمُلْكِ وَخَلَقَ كُلَّ شَىْءٍ فَقَدَّرَهُۥ تَقْدِيرًا', 'b17bbc068a3657705c882c471b97684624b5b4889e3608e4b8349b80aa5326cc', 'b17bbc068a3657705c882c471b97684624b5b4889e3608e4b8349b80aa5326cc', NULL, 'الذي له ملك السموت والارض ولم يتخذ ولدا ولم يكن له شريك في الملك وخلق كل شيء فقدره تقديرا', 18, 36, 144, 1, 4, 359, false, NULL),
    (2858, 'tanzil-uthmani-v1.1', 25, 3, 'وَٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً لَّا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرًّا وَلَا نَفْعًا وَلَا يَمْلِكُونَ مَوْتًا وَلَا حَيَوٰةً وَلَا نُشُورًا', 'b0fa681749fe05b649d4a973cf5ab41d9c53f49cbf2371c4d87ca6d5720ccb63', 'وَٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةً لَّا يَخْلُقُونَ شَيْـًٔا وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرًّا وَلَا نَفْعًا وَلَا يَمْلِكُونَ مَوْتًا وَلَا حَيَوٰةً وَلَا نُشُورًا', 'b0fa681749fe05b649d4a973cf5ab41d9c53f49cbf2371c4d87ca6d5720ccb63', 'b0fa681749fe05b649d4a973cf5ab41d9c53f49cbf2371c4d87ca6d5720ccb63', NULL, 'واتخذوا من دونه ءالهه لا يخلقون شيا وهم يخلقون ولا يملكون لانفسهم ضرا ولا نفعا ولا يملكون موتا ولا حيوه ولا نشورا', 18, 36, 144, 1, 4, 360, false, NULL),
    (2859, 'tanzil-uthmani-v1.1', 25, 4, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ إِفْكٌ ٱفْتَرَىٰهُ وَأَعَانَهُۥ عَلَيْهِ قَوْمٌ ءَاخَرُونَ فَقَدْ جَآءُو ظُلْمًا وَزُورًا', '489004fb14a4b83b5b2253d28c4aa47b018c5f07cac32fb6ed45431727f3c744', 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ إِفْكٌ ٱفْتَرَىٰهُ وَأَعَانَهُۥ عَلَيْهِ قَوْمٌ ءَاخَرُونَ فَقَدْ جَآءُو ظُلْمًا وَزُورًا', '489004fb14a4b83b5b2253d28c4aa47b018c5f07cac32fb6ed45431727f3c744', '489004fb14a4b83b5b2253d28c4aa47b018c5f07cac32fb6ed45431727f3c744', NULL, 'وقال الذين كفروا ان هذا الا افك افتريه واعانه عليه قوم ءاخرون فقد جاءو ظلما وزورا', 18, 36, 144, 1, 4, 360, false, NULL),
    (2860, 'tanzil-uthmani-v1.1', 25, 5, 'وَقَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ ٱكْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَةً وَأَصِيلًا', 'ef13a308ad7544bdecdd3d9b432eefb2f1f724754eaad9f687556313a3d513e5', 'وَقَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ ٱكْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَةً وَأَصِيلًا', 'ef13a308ad7544bdecdd3d9b432eefb2f1f724754eaad9f687556313a3d513e5', 'ef13a308ad7544bdecdd3d9b432eefb2f1f724754eaad9f687556313a3d513e5', NULL, 'وقالوا اسطير الاولين اكتتبها فهي تملي عليه بكره واصيلا', 18, 36, 144, 1, 4, 360, false, NULL),
    (2861, 'tanzil-uthmani-v1.1', 25, 6, 'قُلْ أَنزَلَهُ ٱلَّذِى يَعْلَمُ ٱلسِّرَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا', '9faa017cd8193120e6302d2a37c1a800de1cca76f7dd42d90c60f96054185b98', 'قُلْ أَنزَلَهُ ٱلَّذِى يَعْلَمُ ٱلسِّرَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا', '9faa017cd8193120e6302d2a37c1a800de1cca76f7dd42d90c60f96054185b98', '9faa017cd8193120e6302d2a37c1a800de1cca76f7dd42d90c60f96054185b98', NULL, 'قل انزله الذي يعلم السر في السموت والارض انه كان غفورا رحيما', 18, 36, 144, 1, 4, 360, false, NULL),
    (2862, 'tanzil-uthmani-v1.1', 25, 7, 'وَقَالُوا۟ مَالِ هَٰذَا ٱلرَّسُولِ يَأْكُلُ ٱلطَّعَامَ وَيَمْشِى فِى ٱلْأَسْوَاقِ لَوْلَآ أُنزِلَ إِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُۥ نَذِيرًا', 'edf320d7cf2718fca45f61e1dabf4eca39905fd371bb5a5557dd1be8c54acc4b', 'وَقَالُوا۟ مَالِ هَٰذَا ٱلرَّسُولِ يَأْكُلُ ٱلطَّعَامَ وَيَمْشِى فِى ٱلْأَسْوَاقِ لَوْلَآ أُنزِلَ إِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُۥ نَذِيرًا', 'edf320d7cf2718fca45f61e1dabf4eca39905fd371bb5a5557dd1be8c54acc4b', 'edf320d7cf2718fca45f61e1dabf4eca39905fd371bb5a5557dd1be8c54acc4b', NULL, 'وقالوا مال هذا الرسول ياكل الطعام ويمشي في الاسواق لولا انزل اليه ملك فيكون معه نذيرا', 18, 36, 144, 1, 4, 360, false, NULL),
    (2863, 'tanzil-uthmani-v1.1', 25, 8, 'أَوْ يُلْقَىٰٓ إِلَيْهِ كَنزٌ أَوْ تَكُونُ لَهُۥ جَنَّةٌ يَأْكُلُ مِنْهَا وَقَالَ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', '865988d4b96cac9636e3573892615ae16a7d6a4891b1a46629894f0849f2979b', 'أَوْ يُلْقَىٰٓ إِلَيْهِ كَنزٌ أَوْ تَكُونُ لَهُۥ جَنَّةٌ يَأْكُلُ مِنْهَا وَقَالَ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا', '865988d4b96cac9636e3573892615ae16a7d6a4891b1a46629894f0849f2979b', '865988d4b96cac9636e3573892615ae16a7d6a4891b1a46629894f0849f2979b', NULL, 'او يلقي اليه كنز او تكون له جنه ياكل منها وقال الظلمون ان تتبعون الا رجلا مسحورا', 18, 36, 144, 1, 4, 360, false, NULL),
    (2864, 'tanzil-uthmani-v1.1', 25, 9, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَٰلَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', '47f42a754c17dcb5f0bcce1bdd7b343f98e5c77f71b26698354324de6d52f428', 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَٰلَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًا', '47f42a754c17dcb5f0bcce1bdd7b343f98e5c77f71b26698354324de6d52f428', '47f42a754c17dcb5f0bcce1bdd7b343f98e5c77f71b26698354324de6d52f428', NULL, 'انظر كيف ضربوا لك الامثل فضلوا فلا يستطيعون سبيلا', 18, 36, 144, 1, 4, 360, false, NULL),
    (2865, 'tanzil-uthmani-v1.1', 25, 10, 'تَبَارَكَ ٱلَّذِىٓ إِن شَآءَ جَعَلَ لَكَ خَيْرًا مِّن ذَٰلِكَ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَيَجْعَل لَّكَ قُصُورًۢا', 'a4c5471a1a426531ec45b8c237cfb14ac5fb8202e3dc38bab22b6541bbde6f6e', 'تَبَارَكَ ٱلَّذِىٓ إِن شَآءَ جَعَلَ لَكَ خَيْرًا مِّن ذَٰلِكَ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَيَجْعَل لَّكَ قُصُورًۢا', 'a4c5471a1a426531ec45b8c237cfb14ac5fb8202e3dc38bab22b6541bbde6f6e', 'a4c5471a1a426531ec45b8c237cfb14ac5fb8202e3dc38bab22b6541bbde6f6e', NULL, 'تبارك الذي ان شاء جعل لك خيرا من ذلك جنت تجري من تحتها الانهر ويجعل لك قصورا', 18, 36, 144, 1, 4, 360, false, NULL),
    (2866, 'tanzil-uthmani-v1.1', 25, 11, 'بَلْ كَذَّبُوا۟ بِٱلسَّاعَةِ وَأَعْتَدْنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا', '0048b5c59938891180e52b9c601555d461d6304b325ac6fa2e29eb947ea7bc54', 'بَلْ كَذَّبُوا۟ بِٱلسَّاعَةِ وَأَعْتَدْنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا', '0048b5c59938891180e52b9c601555d461d6304b325ac6fa2e29eb947ea7bc54', '0048b5c59938891180e52b9c601555d461d6304b325ac6fa2e29eb947ea7bc54', NULL, 'بل كذبوا بالساعه واعتدنا لمن كذب بالساعه سعيرا', 18, 36, 144, 1, 4, 360, false, NULL),
    (2867, 'tanzil-uthmani-v1.1', 25, 12, 'إِذَا رَأَتْهُم مِّن مَّكَانٍۭ بَعِيدٍ سَمِعُوا۟ لَهَا تَغَيُّظًا وَزَفِيرًا', '8f41d42e3d9401067b5da78866479e08939756751c4c6d1034b164fa174a3bea', 'إِذَا رَأَتْهُم مِّن مَّكَانٍۭ بَعِيدٍ سَمِعُوا۟ لَهَا تَغَيُّظًا وَزَفِيرًا', '8f41d42e3d9401067b5da78866479e08939756751c4c6d1034b164fa174a3bea', '8f41d42e3d9401067b5da78866479e08939756751c4c6d1034b164fa174a3bea', NULL, 'اذا راتهم من مكان بعيد سمعوا لها تغيظا وزفيرا', 18, 36, 144, 1, 4, 361, false, NULL),
    (2868, 'tanzil-uthmani-v1.1', 25, 13, 'وَإِذَآ أُلْقُوا۟ مِنْهَا مَكَانًا ضَيِّقًا مُّقَرَّنِينَ دَعَوْا۟ هُنَالِكَ ثُبُورًا', '2c5d13a909a159b846d871a06711a67ab4ec9ad10fa6e8cb3df2901051f52592', 'وَإِذَآ أُلْقُوا۟ مِنْهَا مَكَانًا ضَيِّقًا مُّقَرَّنِينَ دَعَوْا۟ هُنَالِكَ ثُبُورًا', '2c5d13a909a159b846d871a06711a67ab4ec9ad10fa6e8cb3df2901051f52592', '2c5d13a909a159b846d871a06711a67ab4ec9ad10fa6e8cb3df2901051f52592', NULL, 'واذا القوا منها مكانا ضيقا مقرنين دعوا هنالك ثبورا', 18, 36, 144, 1, 4, 361, false, NULL),
    (2869, 'tanzil-uthmani-v1.1', 25, 14, 'لَّا تَدْعُوا۟ ٱلْيَوْمَ ثُبُورًا وَٰحِدًا وَٱدْعُوا۟ ثُبُورًا كَثِيرًا', '4f34ffb529eeb8c5776c8e50a680cc0cd458bc026c1b39f27aae8b214bb950b4', 'لَّا تَدْعُوا۟ ٱلْيَوْمَ ثُبُورًا وَٰحِدًا وَٱدْعُوا۟ ثُبُورًا كَثِيرًا', '4f34ffb529eeb8c5776c8e50a680cc0cd458bc026c1b39f27aae8b214bb950b4', '4f34ffb529eeb8c5776c8e50a680cc0cd458bc026c1b39f27aae8b214bb950b4', NULL, 'لا تدعوا اليوم ثبورا وحدا وادعوا ثبورا كثيرا', 18, 36, 144, 1, 4, 361, false, NULL),
    (2870, 'tanzil-uthmani-v1.1', 25, 15, 'قُلْ أَذَٰلِكَ خَيْرٌ أَمْ جَنَّةُ ٱلْخُلْدِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ كَانَتْ لَهُمْ جَزَآءً وَمَصِيرًا', 'cd105eb8abdf2e322c7331fbf477be29d50edabcf773d6a61136cd6e929b124c', 'قُلْ أَذَٰلِكَ خَيْرٌ أَمْ جَنَّةُ ٱلْخُلْدِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ كَانَتْ لَهُمْ جَزَآءً وَمَصِيرًا', 'cd105eb8abdf2e322c7331fbf477be29d50edabcf773d6a61136cd6e929b124c', 'cd105eb8abdf2e322c7331fbf477be29d50edabcf773d6a61136cd6e929b124c', NULL, 'قل اذلك خير ام جنه الخلد التي وعد المتقون كانت لهم جزاء ومصيرا', 18, 36, 144, 1, 4, 361, false, NULL),
    (2871, 'tanzil-uthmani-v1.1', 25, 16, 'لَّهُمْ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَ كَانَ عَلَىٰ رَبِّكَ وَعْدًا مَّسْـُٔولًا', '9b56f0d88b90d956bd1c73dd561a2a79fe317078acf7b1f1a106e019690d02ee', 'لَّهُمْ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَ كَانَ عَلَىٰ رَبِّكَ وَعْدًا مَّسْـُٔولًا', '9b56f0d88b90d956bd1c73dd561a2a79fe317078acf7b1f1a106e019690d02ee', '9b56f0d88b90d956bd1c73dd561a2a79fe317078acf7b1f1a106e019690d02ee', NULL, 'لهم فيها ما يشاءون خلدين كان علي ربك وعدا مسولا', 18, 36, 144, 1, 4, 361, false, NULL),
    (2872, 'tanzil-uthmani-v1.1', 25, 17, 'وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمْ أَضْلَلْتُمْ عِبَادِى هَٰٓؤُلَآءِ أَمْ هُمْ ضَلُّوا۟ ٱلسَّبِيلَ', '1f41ce81b1b99beeedf4708ec073cb234bcd87ff82fa9b0f0bc111a0d8d16b40', 'وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمْ أَضْلَلْتُمْ عِبَادِى هَٰٓؤُلَآءِ أَمْ هُمْ ضَلُّوا۟ ٱلسَّبِيلَ', '1f41ce81b1b99beeedf4708ec073cb234bcd87ff82fa9b0f0bc111a0d8d16b40', '1f41ce81b1b99beeedf4708ec073cb234bcd87ff82fa9b0f0bc111a0d8d16b40', NULL, 'ويوم يحشرهم وما يعبدون من دون الله فيقول ءانتم اضللتم عبادي هؤلاء ام هم ضلوا السبيل', 18, 36, 144, 1, 4, 361, false, NULL),
    (2873, 'tanzil-uthmani-v1.1', 25, 18, 'قَالُوا۟ سُبْحَٰنَكَ مَا كَانَ يَنۢبَغِى لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ وَلَٰكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ حَتَّىٰ نَسُوا۟ ٱلذِّكْرَ وَكَانُوا۟ قَوْمًۢا بُورًا', '6e769e59cbc020297402ea66d35318989a0799f5e3e9d49f336c110b03f4f7c2', 'قَالُوا۟ سُبْحَٰنَكَ مَا كَانَ يَنۢبَغِى لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ وَلَٰكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ حَتَّىٰ نَسُوا۟ ٱلذِّكْرَ وَكَانُوا۟ قَوْمًۢا بُورًا', '6e769e59cbc020297402ea66d35318989a0799f5e3e9d49f336c110b03f4f7c2', '6e769e59cbc020297402ea66d35318989a0799f5e3e9d49f336c110b03f4f7c2', NULL, 'قالوا سبحنك ما كان ينبغي لنا ان نتخذ من دونك من اولياء ولكن متعتهم وءاباءهم حتي نسوا الذكر وكانوا قوما بورا', 18, 36, 144, 1, 4, 361, false, NULL),
    (2874, 'tanzil-uthmani-v1.1', 25, 19, 'فَقَدْ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسْتَطِيعُونَ صَرْفًا وَلَا نَصْرًا وَمَن يَظْلِم مِّنكُمْ نُذِقْهُ عَذَابًا كَبِيرًا', '1eccc1e7882af2ef70a41a0333b6075dbf741983d8d1c1010aa4b82f80459bd7', 'فَقَدْ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسْتَطِيعُونَ صَرْفًا وَلَا نَصْرًا وَمَن يَظْلِم مِّنكُمْ نُذِقْهُ عَذَابًا كَبِيرًا', '1eccc1e7882af2ef70a41a0333b6075dbf741983d8d1c1010aa4b82f80459bd7', '1eccc1e7882af2ef70a41a0333b6075dbf741983d8d1c1010aa4b82f80459bd7', NULL, 'فقد كذبوكم بما تقولون فما تستطيعون صرفا ولا نصرا ومن يظلم منكم نذقه عذابا كبيرا', 18, 36, 144, 1, 4, 361, false, NULL),
    (2875, 'tanzil-uthmani-v1.1', 25, 20, 'وَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ ٱلْمُرْسَلِينَ إِلَّآ إِنَّهُمْ لَيَأْكُلُونَ ٱلطَّعَامَ وَيَمْشُونَ فِى ٱلْأَسْوَاقِ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ وَكَانَ رَبُّكَ بَصِيرًا', '41b581d85e780b3eb27530bccbb4fc6cd9628ce4a8389d866e8b751f1bba65a8', 'وَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ ٱلْمُرْسَلِينَ إِلَّآ إِنَّهُمْ لَيَأْكُلُونَ ٱلطَّعَامَ وَيَمْشُونَ فِى ٱلْأَسْوَاقِ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ وَكَانَ رَبُّكَ بَصِيرًا', '41b581d85e780b3eb27530bccbb4fc6cd9628ce4a8389d866e8b751f1bba65a8', '41b581d85e780b3eb27530bccbb4fc6cd9628ce4a8389d866e8b751f1bba65a8', NULL, 'وما ارسلنا قبلك من المرسلين الا انهم لياكلون الطعام ويمشون في الاسواق وجعلنا بعضكم لبعض فتنه اتصبرون وكان ربك بصيرا', 18, 36, 144, 1, 4, 361, false, NULL),
    (2876, 'tanzil-uthmani-v1.1', 25, 21, 'وَقَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا لَوْلَآ أُنزِلَ عَلَيْنَا ٱلْمَلَٰٓئِكَةُ أَوْ نَرَىٰ رَبَّنَا لَقَدِ ٱسْتَكْبَرُوا۟ فِىٓ أَنفُسِهِمْ وَعَتَوْ عُتُوًّا كَبِيرًا', '1b93d65ae494e5b3db1670edac134897d53a4d681dff249860a453fe4ec55a40', 'وَقَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا لَوْلَآ أُنزِلَ عَلَيْنَا ٱلْمَلَٰٓئِكَةُ أَوْ نَرَىٰ رَبَّنَا لَقَدِ ٱسْتَكْبَرُوا۟ فِىٓ أَنفُسِهِمْ وَعَتَوْ عُتُوًّا كَبِيرًا', '1b93d65ae494e5b3db1670edac134897d53a4d681dff249860a453fe4ec55a40', '1b93d65ae494e5b3db1670edac134897d53a4d681dff249860a453fe4ec55a40', NULL, 'وقال الذين لا يرجون لقاءنا لولا انزل علينا الملئكه او نري ربنا لقد استكبروا في انفسهم وعتو عتوا كبيرا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2877, 'tanzil-uthmani-v1.1', 25, 22, 'يَوْمَ يَرَوْنَ ٱلْمَلَٰٓئِكَةَ لَا بُشْرَىٰ يَوْمَئِذٍ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْرًا مَّحْجُورًا', '3dfe6de4595b6eb14d0ca0fcc10561f27bd23ed75e3c4999ab59619671761cac', 'يَوْمَ يَرَوْنَ ٱلْمَلَٰٓئِكَةَ لَا بُشْرَىٰ يَوْمَئِذٍ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْرًا مَّحْجُورًا', '3dfe6de4595b6eb14d0ca0fcc10561f27bd23ed75e3c4999ab59619671761cac', '3dfe6de4595b6eb14d0ca0fcc10561f27bd23ed75e3c4999ab59619671761cac', NULL, 'يوم يرون الملئكه لا بشري يومئذ للمجرمين ويقولون حجرا محجورا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2878, 'tanzil-uthmani-v1.1', 25, 23, 'وَقَدِمْنَآ إِلَىٰ مَا عَمِلُوا۟ مِنْ عَمَلٍ فَجَعَلْنَٰهُ هَبَآءً مَّنثُورًا', '4755211b56c0ddc735c9d16b7e0ba8994416a2d2041741f4148fb95a31876360', 'وَقَدِمْنَآ إِلَىٰ مَا عَمِلُوا۟ مِنْ عَمَلٍ فَجَعَلْنَٰهُ هَبَآءً مَّنثُورًا', '4755211b56c0ddc735c9d16b7e0ba8994416a2d2041741f4148fb95a31876360', '4755211b56c0ddc735c9d16b7e0ba8994416a2d2041741f4148fb95a31876360', NULL, 'وقدمنا الي ما عملوا من عمل فجعلنه هباء منثورا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2879, 'tanzil-uthmani-v1.1', 25, 24, 'أَصْحَٰبُ ٱلْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرًّا وَأَحْسَنُ مَقِيلًا', '6995656cf92bc4e2e370a3862fc33da6291291645e4bdd5ed73467047640d7c7', 'أَصْحَٰبُ ٱلْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرًّا وَأَحْسَنُ مَقِيلًا', '6995656cf92bc4e2e370a3862fc33da6291291645e4bdd5ed73467047640d7c7', '6995656cf92bc4e2e370a3862fc33da6291291645e4bdd5ed73467047640d7c7', NULL, 'اصحب الجنه يومئذ خير مستقرا واحسن مقيلا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2880, 'tanzil-uthmani-v1.1', 25, 25, 'وَيَوْمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلْغَمَٰمِ وَنُزِّلَ ٱلْمَلَٰٓئِكَةُ تَنزِيلًا', '73bec6a6dd01839296d4b7af6aad99390d9e7016f42e5744fd95609e42f04741', 'وَيَوْمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلْغَمَٰمِ وَنُزِّلَ ٱلْمَلَٰٓئِكَةُ تَنزِيلًا', '73bec6a6dd01839296d4b7af6aad99390d9e7016f42e5744fd95609e42f04741', '73bec6a6dd01839296d4b7af6aad99390d9e7016f42e5744fd95609e42f04741', NULL, 'ويوم تشقق السماء بالغمم ونزل الملئكه تنزيلا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2881, 'tanzil-uthmani-v1.1', 25, 26, 'ٱلْمُلْكُ يَوْمَئِذٍ ٱلْحَقُّ لِلرَّحْمَٰنِ وَكَانَ يَوْمًا عَلَى ٱلْكَٰفِرِينَ عَسِيرًا', 'cf054814207920591a522a73cc9bf9d1634ad456f92b71b7e2e98fcd8542bdad', 'ٱلْمُلْكُ يَوْمَئِذٍ ٱلْحَقُّ لِلرَّحْمَٰنِ وَكَانَ يَوْمًا عَلَى ٱلْكَٰفِرِينَ عَسِيرًا', 'cf054814207920591a522a73cc9bf9d1634ad456f92b71b7e2e98fcd8542bdad', 'cf054814207920591a522a73cc9bf9d1634ad456f92b71b7e2e98fcd8542bdad', NULL, 'الملك يومئذ الحق للرحمن وكان يوما علي الكفرين عسيرا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2882, 'tanzil-uthmani-v1.1', 25, 27, 'وَيَوْمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَٰلَيْتَنِى ٱتَّخَذْتُ مَعَ ٱلرَّسُولِ سَبِيلًا', 'c54f795bcb055c6caa5bdd6c623d93d74d4b27a6d22fb3c61fd502760ad3ed62', 'وَيَوْمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَٰلَيْتَنِى ٱتَّخَذْتُ مَعَ ٱلرَّسُولِ سَبِيلًا', 'c54f795bcb055c6caa5bdd6c623d93d74d4b27a6d22fb3c61fd502760ad3ed62', 'c54f795bcb055c6caa5bdd6c623d93d74d4b27a6d22fb3c61fd502760ad3ed62', NULL, 'ويوم يعض الظالم علي يديه يقول يليتني اتخذت مع الرسول سبيلا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2883, 'tanzil-uthmani-v1.1', 25, 28, 'يَٰوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا', '938846a3ca3a5cb567a97f1893b89feb1a16367366a32a0cefe5e7e5d6030d3a', 'يَٰوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا', '938846a3ca3a5cb567a97f1893b89feb1a16367366a32a0cefe5e7e5d6030d3a', '938846a3ca3a5cb567a97f1893b89feb1a16367366a32a0cefe5e7e5d6030d3a', NULL, 'يويلتي ليتني لم اتخذ فلانا خليلا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2884, 'tanzil-uthmani-v1.1', 25, 29, 'لَّقَدْ أَضَلَّنِى عَنِ ٱلذِّكْرِ بَعْدَ إِذْ جَآءَنِى وَكَانَ ٱلشَّيْطَٰنُ لِلْإِنسَٰنِ خَذُولًا', '16790544c631379a1c1c985305047149b789915fdecba8aa6d89c8505298e52c', 'لَّقَدْ أَضَلَّنِى عَنِ ٱلذِّكْرِ بَعْدَ إِذْ جَآءَنِى وَكَانَ ٱلشَّيْطَٰنُ لِلْإِنسَٰنِ خَذُولًا', '16790544c631379a1c1c985305047149b789915fdecba8aa6d89c8505298e52c', '16790544c631379a1c1c985305047149b789915fdecba8aa6d89c8505298e52c', NULL, 'لقد اضلني عن الذكر بعد اذ جاءني وكان الشيطن للانسن خذولا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2885, 'tanzil-uthmani-v1.1', 25, 30, 'وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوْمِى ٱتَّخَذُوا۟ هَٰذَا ٱلْقُرْءَانَ مَهْجُورًا', 'f499fe21ad2261fa1cf98c81119886e41e1c26e3f99ad26d29c026877fa78cd6', 'وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوْمِى ٱتَّخَذُوا۟ هَٰذَا ٱلْقُرْءَانَ مَهْجُورًا', 'f499fe21ad2261fa1cf98c81119886e41e1c26e3f99ad26d29c026877fa78cd6', 'f499fe21ad2261fa1cf98c81119886e41e1c26e3f99ad26d29c026877fa78cd6', NULL, 'وقال الرسول يرب ان قومي اتخذوا هذا القرءان مهجورا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2886, 'tanzil-uthmani-v1.1', 25, 31, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا مِّنَ ٱلْمُجْرِمِينَ وَكَفَىٰ بِرَبِّكَ هَادِيًا وَنَصِيرًا', 'b62b9183bba135ce626fe6765643dc689c06e945e93f5a007ffdbe13ebde1261', 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا مِّنَ ٱلْمُجْرِمِينَ وَكَفَىٰ بِرَبِّكَ هَادِيًا وَنَصِيرًا', 'b62b9183bba135ce626fe6765643dc689c06e945e93f5a007ffdbe13ebde1261', 'b62b9183bba135ce626fe6765643dc689c06e945e93f5a007ffdbe13ebde1261', NULL, 'وكذلك جعلنا لكل نبي عدوا من المجرمين وكفي بربك هاديا ونصيرا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2887, 'tanzil-uthmani-v1.1', 25, 32, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ٱلْقُرْءَانُ جُمْلَةً وَٰحِدَةً كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَ وَرَتَّلْنَٰهُ تَرْتِيلًا', 'bbf30c0bff135c0d2a581b79c3ae98601d7cc7bcd9b59cd334eeefedf969e1c3', 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ٱلْقُرْءَانُ جُمْلَةً وَٰحِدَةً كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَ وَرَتَّلْنَٰهُ تَرْتِيلًا', 'bbf30c0bff135c0d2a581b79c3ae98601d7cc7bcd9b59cd334eeefedf969e1c3', 'bbf30c0bff135c0d2a581b79c3ae98601d7cc7bcd9b59cd334eeefedf969e1c3', NULL, 'وقال الذين كفروا لولا نزل عليه القرءان جمله وحده كذلك لنثبت به فؤادك ورتلنه ترتيلا', 19, 37, 145, 1, 4, 362, false, NULL),
    (2888, 'tanzil-uthmani-v1.1', 25, 33, 'وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَٰكَ بِٱلْحَقِّ وَأَحْسَنَ تَفْسِيرًا', '6735f2128019bd15e2d87cb745498c2c5baa1c0a6aa41a36b7ada31012935352', 'وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَٰكَ بِٱلْحَقِّ وَأَحْسَنَ تَفْسِيرًا', '6735f2128019bd15e2d87cb745498c2c5baa1c0a6aa41a36b7ada31012935352', '6735f2128019bd15e2d87cb745498c2c5baa1c0a6aa41a36b7ada31012935352', NULL, 'ولا ياتونك بمثل الا جئنك بالحق واحسن تفسيرا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2889, 'tanzil-uthmani-v1.1', 25, 34, 'ٱلَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُو۟لَٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ سَبِيلًا', 'f274d49ba3152e9b7c8c20e458c6db2349acf90e58083b1b60f25ce3c76b5368', 'ٱلَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُو۟لَٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ سَبِيلًا', 'f274d49ba3152e9b7c8c20e458c6db2349acf90e58083b1b60f25ce3c76b5368', 'f274d49ba3152e9b7c8c20e458c6db2349acf90e58083b1b60f25ce3c76b5368', NULL, 'الذين يحشرون علي وجوههم الي جهنم اولئك شر مكانا واضل سبيلا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2890, 'tanzil-uthmani-v1.1', 25, 35, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرًا', 'e9ca94e5d12e95de425669495cf074542dd81afe5cc6dabad7479e8a6ee22742', 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرًا', 'e9ca94e5d12e95de425669495cf074542dd81afe5cc6dabad7479e8a6ee22742', 'e9ca94e5d12e95de425669495cf074542dd81afe5cc6dabad7479e8a6ee22742', NULL, 'ولقد ءاتينا موسي الكتب وجعلنا معه اخاه هرون وزيرا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2891, 'tanzil-uthmani-v1.1', 25, 36, 'فَقُلْنَا ٱذْهَبَآ إِلَى ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَدَمَّرْنَٰهُمْ تَدْمِيرًا', '7ff08b396b8fa9e0bbc1a4d1f04f8a20fc88c2b6ef37afd89eb97c211dfb0062', 'فَقُلْنَا ٱذْهَبَآ إِلَى ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَدَمَّرْنَٰهُمْ تَدْمِيرًا', '7ff08b396b8fa9e0bbc1a4d1f04f8a20fc88c2b6ef37afd89eb97c211dfb0062', '7ff08b396b8fa9e0bbc1a4d1f04f8a20fc88c2b6ef37afd89eb97c211dfb0062', NULL, 'فقلنا اذهبا الي القوم الذين كذبوا بايتنا فدمرنهم تدميرا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2892, 'tanzil-uthmani-v1.1', 25, 37, 'وَقَوْمَ نُوحٍ لَّمَّا كَذَّبُوا۟ ٱلرُّسُلَ أَغْرَقْنَٰهُمْ وَجَعَلْنَٰهُمْ لِلنَّاسِ ءَايَةً وَأَعْتَدْنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمًا', 'eea3be565997956c83404ac1b24915596587c57abd1a911885f85f8fdaa94719', 'وَقَوْمَ نُوحٍ لَّمَّا كَذَّبُوا۟ ٱلرُّسُلَ أَغْرَقْنَٰهُمْ وَجَعَلْنَٰهُمْ لِلنَّاسِ ءَايَةً وَأَعْتَدْنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمًا', 'eea3be565997956c83404ac1b24915596587c57abd1a911885f85f8fdaa94719', 'eea3be565997956c83404ac1b24915596587c57abd1a911885f85f8fdaa94719', NULL, 'وقوم نوح لما كذبوا الرسل اغرقنهم وجعلنهم للناس ءايه واعتدنا للظلمين عذابا اليما', 19, 37, 145, 1, 4, 363, false, NULL),
    (2893, 'tanzil-uthmani-v1.1', 25, 38, 'وَعَادًا وَثَمُودَا۟ وَأَصْحَٰبَ ٱلرَّسِّ وَقُرُونًۢا بَيْنَ ذَٰلِكَ كَثِيرًا', '589d51c7bee6478a7ea3a093ced0612e6a3766782dd7137cf26fd82e12c3c4f6', 'وَعَادًا وَثَمُودَا۟ وَأَصْحَٰبَ ٱلرَّسِّ وَقُرُونًۢا بَيْنَ ذَٰلِكَ كَثِيرًا', '589d51c7bee6478a7ea3a093ced0612e6a3766782dd7137cf26fd82e12c3c4f6', '589d51c7bee6478a7ea3a093ced0612e6a3766782dd7137cf26fd82e12c3c4f6', NULL, 'وعادا وثمودا واصحب الرس وقرونا بين ذلك كثيرا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2894, 'tanzil-uthmani-v1.1', 25, 39, 'وَكُلًّا ضَرَبْنَا لَهُ ٱلْأَمْثَٰلَ وَكُلًّا تَبَّرْنَا تَتْبِيرًا', 'c8746ce85ab27692231565d9b8c0646f79a4b90955f071d804cba3c1c7998141', 'وَكُلًّا ضَرَبْنَا لَهُ ٱلْأَمْثَٰلَ وَكُلًّا تَبَّرْنَا تَتْبِيرًا', 'c8746ce85ab27692231565d9b8c0646f79a4b90955f071d804cba3c1c7998141', 'c8746ce85ab27692231565d9b8c0646f79a4b90955f071d804cba3c1c7998141', NULL, 'وكلا ضربنا له الامثل وكلا تبرنا تتبيرا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2895, 'tanzil-uthmani-v1.1', 25, 40, 'وَلَقَدْ أَتَوْا۟ عَلَى ٱلْقَرْيَةِ ٱلَّتِىٓ أُمْطِرَتْ مَطَرَ ٱلسَّوْءِ أَفَلَمْ يَكُونُوا۟ يَرَوْنَهَا بَلْ كَانُوا۟ لَا يَرْجُونَ نُشُورًا', '4b3a0161affceeda233ade9180e20863513d81afdc759a49e1f3aa4003fa174d', 'وَلَقَدْ أَتَوْا۟ عَلَى ٱلْقَرْيَةِ ٱلَّتِىٓ أُمْطِرَتْ مَطَرَ ٱلسَّوْءِ أَفَلَمْ يَكُونُوا۟ يَرَوْنَهَا بَلْ كَانُوا۟ لَا يَرْجُونَ نُشُورًا', '4b3a0161affceeda233ade9180e20863513d81afdc759a49e1f3aa4003fa174d', '4b3a0161affceeda233ade9180e20863513d81afdc759a49e1f3aa4003fa174d', NULL, 'ولقد اتوا علي القريه التي امطرت مطر السوء افلم يكونوا يرونها بل كانوا لا يرجون نشورا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2896, 'tanzil-uthmani-v1.1', 25, 41, 'وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى بَعَثَ ٱللَّهُ رَسُولًا', '7f1e72760b6feb75a1cd96f7b85b5e24938ea44fc2dc889b1583c5307053c046', 'وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى بَعَثَ ٱللَّهُ رَسُولًا', '7f1e72760b6feb75a1cd96f7b85b5e24938ea44fc2dc889b1583c5307053c046', '7f1e72760b6feb75a1cd96f7b85b5e24938ea44fc2dc889b1583c5307053c046', NULL, 'واذا راوك ان يتخذونك الا هزوا اهذا الذي بعث الله رسولا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2897, 'tanzil-uthmani-v1.1', 25, 42, 'إِن كَادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْلَآ أَن صَبَرْنَا عَلَيْهَا وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ ٱلْعَذَابَ مَنْ أَضَلُّ سَبِيلًا', 'e3bd094040d007d2af50cd4a84ccd941e056e43bd50cbceab9381ce5e2a93a8c', 'إِن كَادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْلَآ أَن صَبَرْنَا عَلَيْهَا وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ ٱلْعَذَابَ مَنْ أَضَلُّ سَبِيلًا', 'e3bd094040d007d2af50cd4a84ccd941e056e43bd50cbceab9381ce5e2a93a8c', 'e3bd094040d007d2af50cd4a84ccd941e056e43bd50cbceab9381ce5e2a93a8c', NULL, 'ان كاد ليضلنا عن ءالهتنا لولا ان صبرنا عليها وسوف يعلمون حين يرون العذاب من اضل سبيلا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2898, 'tanzil-uthmani-v1.1', 25, 43, 'أَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', 'e77a35fc6e9da1a5306ca3b261166e6d7f44a970b34e5987e6d87314167fd473', 'أَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', 'e77a35fc6e9da1a5306ca3b261166e6d7f44a970b34e5987e6d87314167fd473', 'e77a35fc6e9da1a5306ca3b261166e6d7f44a970b34e5987e6d87314167fd473', NULL, 'ارءيت من اتخذ الهه هويه افانت تكون عليه وكيلا', 19, 37, 145, 1, 4, 363, false, NULL),
    (2899, 'tanzil-uthmani-v1.1', 25, 44, 'أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلَّا كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ سَبِيلًا', 'c3307f8cf334cfce8cb0eb4a09bdf6d9ed6671cfca32ce805c1bc341cb63c200', 'أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلَّا كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ سَبِيلًا', 'c3307f8cf334cfce8cb0eb4a09bdf6d9ed6671cfca32ce805c1bc341cb63c200', 'c3307f8cf334cfce8cb0eb4a09bdf6d9ed6671cfca32ce805c1bc341cb63c200', NULL, 'ام تحسب ان اكثرهم يسمعون او يعقلون ان هم الا كالانعم بل هم اضل سبيلا', 19, 37, 145, 1, 4, 364, false, NULL),
    (2900, 'tanzil-uthmani-v1.1', 25, 45, 'أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ ٱلظِّلَّ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِنًا ثُمَّ جَعَلْنَا ٱلشَّمْسَ عَلَيْهِ دَلِيلًا', '28b3b5ba47a550a57115927fbf00920cbb8f25591be1c7d6b72bac989eac264d', 'أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ ٱلظِّلَّ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِنًا ثُمَّ جَعَلْنَا ٱلشَّمْسَ عَلَيْهِ دَلِيلًا', '28b3b5ba47a550a57115927fbf00920cbb8f25591be1c7d6b72bac989eac264d', '28b3b5ba47a550a57115927fbf00920cbb8f25591be1c7d6b72bac989eac264d', NULL, 'الم تر الي ربك كيف مد الظل ولو شاء لجعله ساكنا ثم جعلنا الشمس عليه دليلا', 19, 37, 145, 1, 4, 364, false, NULL),
    (2901, 'tanzil-uthmani-v1.1', 25, 46, 'ثُمَّ قَبَضْنَٰهُ إِلَيْنَا قَبْضًا يَسِيرًا', 'e68a5f44d192d19a2a19d58ef762f518b26f93ed48b88d60e03aa7ab3f3ae76d', 'ثُمَّ قَبَضْنَٰهُ إِلَيْنَا قَبْضًا يَسِيرًا', 'e68a5f44d192d19a2a19d58ef762f518b26f93ed48b88d60e03aa7ab3f3ae76d', 'e68a5f44d192d19a2a19d58ef762f518b26f93ed48b88d60e03aa7ab3f3ae76d', NULL, 'ثم قبضنه الينا قبضا يسيرا', 19, 37, 145, 1, 4, 364, false, NULL),
    (2902, 'tanzil-uthmani-v1.1', 25, 47, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِبَاسًا وَٱلنَّوْمَ سُبَاتًا وَجَعَلَ ٱلنَّهَارَ نُشُورًا', 'a5a964b91f8614e214a5aa14ee2dfe12626f3c94989448a48abee25a5f409be5', 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِبَاسًا وَٱلنَّوْمَ سُبَاتًا وَجَعَلَ ٱلنَّهَارَ نُشُورًا', 'a5a964b91f8614e214a5aa14ee2dfe12626f3c94989448a48abee25a5f409be5', 'a5a964b91f8614e214a5aa14ee2dfe12626f3c94989448a48abee25a5f409be5', NULL, 'وهو الذي جعل لكم اليل لباسا والنوم سباتا وجعل النهار نشورا', 19, 37, 145, 1, 4, 364, false, NULL),
    (2903, 'tanzil-uthmani-v1.1', 25, 48, 'وَهُوَ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً طَهُورًا', '6b2b39dd5967121c0d7e0d2f7f6f01760c058a1d1d4ef7f057634b609c028d53', 'وَهُوَ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً طَهُورًا', '6b2b39dd5967121c0d7e0d2f7f6f01760c058a1d1d4ef7f057634b609c028d53', '6b2b39dd5967121c0d7e0d2f7f6f01760c058a1d1d4ef7f057634b609c028d53', NULL, 'وهو الذي ارسل الريح بشرا بين يدي رحمته وانزلنا من السماء ماء طهورا', 19, 37, 145, 1, 4, 364, false, NULL),
    (2904, 'tanzil-uthmani-v1.1', 25, 49, 'لِّنُحْـِۧىَ بِهِۦ بَلْدَةً مَّيْتًا وَنُسْقِيَهُۥ مِمَّا خَلَقْنَآ أَنْعَٰمًا وَأَنَاسِىَّ كَثِيرًا', 'bf45c26b0d4f8a5d8eea2187dfc6fb65303f37159deb1ed2b0402b50bad3154a', 'لِّنُحْـِۧىَ بِهِۦ بَلْدَةً مَّيْتًا وَنُسْقِيَهُۥ مِمَّا خَلَقْنَآ أَنْعَٰمًا وَأَنَاسِىَّ كَثِيرًا', 'bf45c26b0d4f8a5d8eea2187dfc6fb65303f37159deb1ed2b0402b50bad3154a', 'bf45c26b0d4f8a5d8eea2187dfc6fb65303f37159deb1ed2b0402b50bad3154a', NULL, 'لنحي به بلده ميتا ونسقيه مما خلقنا انعما واناسي كثيرا', 19, 37, 145, 1, 4, 364, false, NULL),
    (2905, 'tanzil-uthmani-v1.1', 25, 50, 'وَلَقَدْ صَرَّفْنَٰهُ بَيْنَهُمْ لِيَذَّكَّرُوا۟ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', '581f56a5445b1742e1cae1e34986cde5a41d5bf4b9b6d9559e91716d23b81f2f', 'وَلَقَدْ صَرَّفْنَٰهُ بَيْنَهُمْ لِيَذَّكَّرُوا۟ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًا', '581f56a5445b1742e1cae1e34986cde5a41d5bf4b9b6d9559e91716d23b81f2f', '581f56a5445b1742e1cae1e34986cde5a41d5bf4b9b6d9559e91716d23b81f2f', NULL, 'ولقد صرفنه بينهم ليذكروا فابي اكثر الناس الا كفورا', 19, 37, 145, 1, 4, 364, false, NULL),
    (2906, 'tanzil-uthmani-v1.1', 25, 51, 'وَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَةٍ نَّذِيرًا', '16178245b302f540b8726477b1e0cd6302da0d8fc2e0b95ad07ebab8c3bc7293', 'وَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَةٍ نَّذِيرًا', '16178245b302f540b8726477b1e0cd6302da0d8fc2e0b95ad07ebab8c3bc7293', '16178245b302f540b8726477b1e0cd6302da0d8fc2e0b95ad07ebab8c3bc7293', NULL, 'ولو شئنا لبعثنا في كل قريه نذيرا', 19, 37, 145, 1, 4, 364, false, NULL),
    (2907, 'tanzil-uthmani-v1.1', 25, 52, 'فَلَا تُطِعِ ٱلْكَٰفِرِينَ وَجَٰهِدْهُم بِهِۦ جِهَادًا كَبِيرًا', '864a46ded82d8d42044b3553408c96ae859b7c023432b84e383d7a2309b780d2', 'فَلَا تُطِعِ ٱلْكَٰفِرِينَ وَجَٰهِدْهُم بِهِۦ جِهَادًا كَبِيرًا', '864a46ded82d8d42044b3553408c96ae859b7c023432b84e383d7a2309b780d2', '864a46ded82d8d42044b3553408c96ae859b7c023432b84e383d7a2309b780d2', NULL, 'فلا تطع الكفرين وجهدهم به جهادا كبيرا', 19, 37, 145, 1, 4, 364, false, NULL),
    (2908, 'tanzil-uthmani-v1.1', 25, 53, 'وَهُوَ ٱلَّذِى مَرَجَ ٱلْبَحْرَيْنِ هَٰذَا عَذْبٌ فُرَاتٌ وَهَٰذَا مِلْحٌ أُجَاجٌ وَجَعَلَ بَيْنَهُمَا بَرْزَخًا وَحِجْرًا مَّحْجُورًا', 'd2b6875293e757cddf6942e50ec90804384e14997ab9e0c8f9f48a730555194e', 'وَهُوَ ٱلَّذِى مَرَجَ ٱلْبَحْرَيْنِ هَٰذَا عَذْبٌ فُرَاتٌ وَهَٰذَا مِلْحٌ أُجَاجٌ وَجَعَلَ بَيْنَهُمَا بَرْزَخًا وَحِجْرًا مَّحْجُورًا', 'd2b6875293e757cddf6942e50ec90804384e14997ab9e0c8f9f48a730555194e', 'd2b6875293e757cddf6942e50ec90804384e14997ab9e0c8f9f48a730555194e', NULL, 'وهو الذي مرج البحرين هذا عذب فرات وهذا ملح اجاج وجعل بينهما برزخا وحجرا محجورا', 19, 37, 146, 1, 4, 364, false, NULL),
    (2909, 'tanzil-uthmani-v1.1', 25, 54, 'وَهُوَ ٱلَّذِى خَلَقَ مِنَ ٱلْمَآءِ بَشَرًا فَجَعَلَهُۥ نَسَبًا وَصِهْرًا وَكَانَ رَبُّكَ قَدِيرًا', 'eef31c61ddf332231a3250be3a90efd0c52343862dc66d72991a673a87cfad09', 'وَهُوَ ٱلَّذِى خَلَقَ مِنَ ٱلْمَآءِ بَشَرًا فَجَعَلَهُۥ نَسَبًا وَصِهْرًا وَكَانَ رَبُّكَ قَدِيرًا', 'eef31c61ddf332231a3250be3a90efd0c52343862dc66d72991a673a87cfad09', 'eef31c61ddf332231a3250be3a90efd0c52343862dc66d72991a673a87cfad09', NULL, 'وهو الذي خلق من الماء بشرا فجعله نسبا وصهرا وكان ربك قديرا', 19, 37, 146, 1, 4, 364, false, NULL),
    (2910, 'tanzil-uthmani-v1.1', 25, 55, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ وَكَانَ ٱلْكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرًا', 'f199f3dcef9c7f3172358ec9a24103fa2222766dba51a89d31e7b0c8991c57a1', 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ وَكَانَ ٱلْكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرًا', 'f199f3dcef9c7f3172358ec9a24103fa2222766dba51a89d31e7b0c8991c57a1', 'f199f3dcef9c7f3172358ec9a24103fa2222766dba51a89d31e7b0c8991c57a1', NULL, 'ويعبدون من دون الله ما لا ينفعهم ولا يضرهم وكان الكافر علي ربه ظهيرا', 19, 37, 146, 1, 4, 364, false, NULL),
    (2911, 'tanzil-uthmani-v1.1', 25, 56, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', '4a7cb735cfeadd7422f865dcf26c71cae8b03d6b4790279d4a0eea7e875297a1', 'وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا', '4a7cb735cfeadd7422f865dcf26c71cae8b03d6b4790279d4a0eea7e875297a1', '4a7cb735cfeadd7422f865dcf26c71cae8b03d6b4790279d4a0eea7e875297a1', NULL, 'وما ارسلنك الا مبشرا ونذيرا', 19, 37, 146, 1, 4, 365, false, NULL),
    (2912, 'tanzil-uthmani-v1.1', 25, 57, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', '530b558c694e7cafe07ac682e69fc1bff6656fcac5f55e5385b56c4f367a5baf', 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', '530b558c694e7cafe07ac682e69fc1bff6656fcac5f55e5385b56c4f367a5baf', '530b558c694e7cafe07ac682e69fc1bff6656fcac5f55e5385b56c4f367a5baf', NULL, 'قل ما اسلكم عليه من اجر الا من شاء ان يتخذ الي ربه سبيلا', 19, 37, 146, 1, 4, 365, false, NULL),
    (2913, 'tanzil-uthmani-v1.1', 25, 58, 'وَتَوَكَّلْ عَلَى ٱلْحَىِّ ٱلَّذِى لَا يَمُوتُ وَسَبِّحْ بِحَمْدِهِۦ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا', 'eb1ea60fe78e08ae90a935259df878cc5ac6391200219646d3cd39a7a5298675', 'وَتَوَكَّلْ عَلَى ٱلْحَىِّ ٱلَّذِى لَا يَمُوتُ وَسَبِّحْ بِحَمْدِهِۦ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا', 'eb1ea60fe78e08ae90a935259df878cc5ac6391200219646d3cd39a7a5298675', 'eb1ea60fe78e08ae90a935259df878cc5ac6391200219646d3cd39a7a5298675', NULL, 'وتوكل علي الحي الذي لا يموت وسبح بحمده وكفي به بذنوب عباده خبيرا', 19, 37, 146, 1, 4, 365, false, NULL),
    (2914, 'tanzil-uthmani-v1.1', 25, 59, 'ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ٱلرَّحْمَٰنُ فَسْـَٔلْ بِهِۦ خَبِيرًا', '0158e8354dc8c5e69158eb6bd9b9087bbb0872dd558832d9133e207efe1eb326', 'ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ٱلرَّحْمَٰنُ فَسْـَٔلْ بِهِۦ خَبِيرًا', '0158e8354dc8c5e69158eb6bd9b9087bbb0872dd558832d9133e207efe1eb326', '0158e8354dc8c5e69158eb6bd9b9087bbb0872dd558832d9133e207efe1eb326', NULL, 'الذي خلق السموت والارض وما بينهما في سته ايام ثم استوي علي العرش الرحمن فسل به خبيرا', 19, 37, 146, 1, 4, 365, false, NULL),
    (2915, 'tanzil-uthmani-v1.1', 25, 60, 'وَإِذَا قِيلَ لَهُمُ ٱسْجُدُوا۟ لِلرَّحْمَٰنِ قَالُوا۟ وَمَا ٱلرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا', 'bb8349b9d1f49a9152477606bff8d2c38d3acf67b8d4ca0c09f5b186cc2e615c', 'وَإِذَا قِيلَ لَهُمُ ٱسْجُدُوا۟ لِلرَّحْمَٰنِ قَالُوا۟ وَمَا ٱلرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا', 'bb8349b9d1f49a9152477606bff8d2c38d3acf67b8d4ca0c09f5b186cc2e615c', 'bb8349b9d1f49a9152477606bff8d2c38d3acf67b8d4ca0c09f5b186cc2e615c', NULL, 'واذا قيل لهم اسجدوا للرحمن قالوا وما الرحمن انسجد لما تامرنا وزادهم نفورا', 19, 37, 146, 1, 4, 365, true, 'recommended'),
    (2916, 'tanzil-uthmani-v1.1', 25, 61, 'تَبَارَكَ ٱلَّذِى جَعَلَ فِى ٱلسَّمَآءِ بُرُوجًا وَجَعَلَ فِيهَا سِرَٰجًا وَقَمَرًا مُّنِيرًا', '80316a1b19be6a5c9055dc3e75f583f34ca78850a69defa853b31965108207f0', 'تَبَارَكَ ٱلَّذِى جَعَلَ فِى ٱلسَّمَآءِ بُرُوجًا وَجَعَلَ فِيهَا سِرَٰجًا وَقَمَرًا مُّنِيرًا', '80316a1b19be6a5c9055dc3e75f583f34ca78850a69defa853b31965108207f0', '80316a1b19be6a5c9055dc3e75f583f34ca78850a69defa853b31965108207f0', NULL, 'تبارك الذي جعل في السماء بروجا وجعل فيها سرجا وقمرا منيرا', 19, 37, 146, 1, 4, 365, false, NULL),
    (2917, 'tanzil-uthmani-v1.1', 25, 62, 'وَهُوَ ٱلَّذِى جَعَلَ ٱلَّيْلَ وَٱلنَّهَارَ خِلْفَةً لِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا', 'bb593c65346bea8c3998c18f549c7f7dec8ce2f52bde683f4c34ad5ec197f514', 'وَهُوَ ٱلَّذِى جَعَلَ ٱلَّيْلَ وَٱلنَّهَارَ خِلْفَةً لِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا', 'bb593c65346bea8c3998c18f549c7f7dec8ce2f52bde683f4c34ad5ec197f514', 'bb593c65346bea8c3998c18f549c7f7dec8ce2f52bde683f4c34ad5ec197f514', NULL, 'وهو الذي جعل اليل والنهار خلفه لمن اراد ان يذكر او اراد شكورا', 19, 37, 146, 1, 4, 365, false, NULL),
    (2918, 'tanzil-uthmani-v1.1', 25, 63, 'وَعِبَادُ ٱلرَّحْمَٰنِ ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ ٱلْجَٰهِلُونَ قَالُوا۟ سَلَٰمًا', '8b21d34e9d6ddc9b6273e33ef2694f19d388d7dca1e3b8f3a41bbc6866b06910', 'وَعِبَادُ ٱلرَّحْمَٰنِ ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ ٱلْجَٰهِلُونَ قَالُوا۟ سَلَٰمًا', '8b21d34e9d6ddc9b6273e33ef2694f19d388d7dca1e3b8f3a41bbc6866b06910', '8b21d34e9d6ddc9b6273e33ef2694f19d388d7dca1e3b8f3a41bbc6866b06910', NULL, 'وعباد الرحمن الذين يمشون علي الارض هونا واذا خاطبهم الجهلون قالوا سلما', 19, 37, 146, 1, 4, 365, false, NULL),
    (2919, 'tanzil-uthmani-v1.1', 25, 64, 'وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَٰمًا', 'a380615a02ab00935bdd56c8dcb386937f357ffdb90b97dd506940d1699ffaf8', 'وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَٰمًا', 'a380615a02ab00935bdd56c8dcb386937f357ffdb90b97dd506940d1699ffaf8', 'a380615a02ab00935bdd56c8dcb386937f357ffdb90b97dd506940d1699ffaf8', NULL, 'والذين يبيتون لربهم سجدا وقيما', 19, 37, 146, 1, 4, 365, false, NULL),
    (2920, 'tanzil-uthmani-v1.1', 25, 65, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَامًا', 'a3557c9df55fb35571ea37a71c728f9289e43144642f129ad57c08941c04074f', 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَامًا', 'a3557c9df55fb35571ea37a71c728f9289e43144642f129ad57c08941c04074f', 'a3557c9df55fb35571ea37a71c728f9289e43144642f129ad57c08941c04074f', NULL, 'والذين يقولون ربنا اصرف عنا عذاب جهنم ان عذابها كان غراما', 19, 37, 146, 1, 4, 365, false, NULL),
    (2921, 'tanzil-uthmani-v1.1', 25, 66, 'إِنَّهَا سَآءَتْ مُسْتَقَرًّا وَمُقَامًا', 'afb6a6826e678402cf062c6b801fa1f0745c53353f04e6bbc8e8945294695d2a', 'إِنَّهَا سَآءَتْ مُسْتَقَرًّا وَمُقَامًا', 'afb6a6826e678402cf062c6b801fa1f0745c53353f04e6bbc8e8945294695d2a', 'afb6a6826e678402cf062c6b801fa1f0745c53353f04e6bbc8e8945294695d2a', NULL, 'انها ساءت مستقرا ومقاما', 19, 37, 146, 1, 4, 365, false, NULL),
    (2922, 'tanzil-uthmani-v1.1', 25, 67, 'وَٱلَّذِينَ إِذَآ أَنفَقُوا۟ لَمْ يُسْرِفُوا۟ وَلَمْ يَقْتُرُوا۟ وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًا', '448b0424e219f9a05a8ad3185c867287d7f549ca17a927560dd1324b2129c13d', 'وَٱلَّذِينَ إِذَآ أَنفَقُوا۟ لَمْ يُسْرِفُوا۟ وَلَمْ يَقْتُرُوا۟ وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًا', '448b0424e219f9a05a8ad3185c867287d7f549ca17a927560dd1324b2129c13d', '448b0424e219f9a05a8ad3185c867287d7f549ca17a927560dd1324b2129c13d', NULL, 'والذين اذا انفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما', 19, 37, 146, 1, 4, 365, false, NULL),
    (2923, 'tanzil-uthmani-v1.1', 25, 68, 'وَٱلَّذِينَ لَا يَدْعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقْتُلُونَ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَلَا يَزْنُونَ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا', '04c31bd57b1c917f2f35c10456707c0006068c8ee320bc587778b66b48826622', 'وَٱلَّذِينَ لَا يَدْعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقْتُلُونَ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَلَا يَزْنُونَ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا', '04c31bd57b1c917f2f35c10456707c0006068c8ee320bc587778b66b48826622', '04c31bd57b1c917f2f35c10456707c0006068c8ee320bc587778b66b48826622', NULL, 'والذين لا يدعون مع الله الها ءاخر ولا يقتلون النفس التي حرم الله الا بالحق ولا يزنون ومن يفعل ذلك يلق اثاما', 19, 37, 146, 1, 4, 366, false, NULL),
    (2924, 'tanzil-uthmani-v1.1', 25, 69, 'يُضَٰعَفْ لَهُ ٱلْعَذَابُ يَوْمَ ٱلْقِيَٰمَةِ وَيَخْلُدْ فِيهِۦ مُهَانًا', 'd394d4bca3e5ceb4e5b85b5bfea7373691fdd2074d239d91bf1594f931c85aff', 'يُضَٰعَفْ لَهُ ٱلْعَذَابُ يَوْمَ ٱلْقِيَٰمَةِ وَيَخْلُدْ فِيهِۦ مُهَانًا', 'd394d4bca3e5ceb4e5b85b5bfea7373691fdd2074d239d91bf1594f931c85aff', 'd394d4bca3e5ceb4e5b85b5bfea7373691fdd2074d239d91bf1594f931c85aff', NULL, 'يضعف له العذاب يوم القيمه ويخلد فيه مهانا', 19, 37, 146, 1, 4, 366, false, NULL),
    (2925, 'tanzil-uthmani-v1.1', 25, 70, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَٰلِحًا فَأُو۟لَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمْ حَسَنَٰتٍ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'b56f43b52a940b29a7fcddaad694d4fb5dc7a9fcced3ff7448932eeaf5981bae', 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَٰلِحًا فَأُو۟لَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمْ حَسَنَٰتٍ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'b56f43b52a940b29a7fcddaad694d4fb5dc7a9fcced3ff7448932eeaf5981bae', 'b56f43b52a940b29a7fcddaad694d4fb5dc7a9fcced3ff7448932eeaf5981bae', NULL, 'الا من تاب وءامن وعمل عملا صلحا فاولئك يبدل الله سياتهم حسنت وكان الله غفورا رحيما', 19, 37, 146, 1, 4, 366, false, NULL),
    (2926, 'tanzil-uthmani-v1.1', 25, 71, 'وَمَن تَابَ وَعَمِلَ صَٰلِحًا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابًا', 'ad37fb48826c043b94db27c323b91155468a970eaa3decb64318556e51779c7d', 'وَمَن تَابَ وَعَمِلَ صَٰلِحًا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابًا', 'ad37fb48826c043b94db27c323b91155468a970eaa3decb64318556e51779c7d', 'ad37fb48826c043b94db27c323b91155468a970eaa3decb64318556e51779c7d', NULL, 'ومن تاب وعمل صلحا فانه يتوب الي الله متابا', 19, 37, 146, 1, 4, 366, false, NULL),
    (2927, 'tanzil-uthmani-v1.1', 25, 72, 'وَٱلَّذِينَ لَا يَشْهَدُونَ ٱلزُّورَ وَإِذَا مَرُّوا۟ بِٱللَّغْوِ مَرُّوا۟ كِرَامًا', '39a0eec5172bab7c0d0c118280a2d15b6168479a47b25e44c0fdfe05f3ff4bd5', 'وَٱلَّذِينَ لَا يَشْهَدُونَ ٱلزُّورَ وَإِذَا مَرُّوا۟ بِٱللَّغْوِ مَرُّوا۟ كِرَامًا', '39a0eec5172bab7c0d0c118280a2d15b6168479a47b25e44c0fdfe05f3ff4bd5', '39a0eec5172bab7c0d0c118280a2d15b6168479a47b25e44c0fdfe05f3ff4bd5', NULL, 'والذين لا يشهدون الزور واذا مروا باللغو مروا كراما', 19, 37, 146, 1, 4, 366, false, NULL),
    (2928, 'tanzil-uthmani-v1.1', 25, 73, 'وَٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَمْ يَخِرُّوا۟ عَلَيْهَا صُمًّا وَعُمْيَانًا', 'c6ac731385574ed9ad3d092a6afc9f580676384ec632fcc1b2701265e265a2bb', 'وَٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَمْ يَخِرُّوا۟ عَلَيْهَا صُمًّا وَعُمْيَانًا', 'c6ac731385574ed9ad3d092a6afc9f580676384ec632fcc1b2701265e265a2bb', 'c6ac731385574ed9ad3d092a6afc9f580676384ec632fcc1b2701265e265a2bb', NULL, 'والذين اذا ذكروا بايت ربهم لم يخروا عليها صما وعميانا', 19, 37, 146, 1, 4, 366, false, NULL),
    (2929, 'tanzil-uthmani-v1.1', 25, 74, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', 'b2de9272b2bb7acd94840460626284d3274dc8966e4b60b678f4264cfce8f150', 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', 'b2de9272b2bb7acd94840460626284d3274dc8966e4b60b678f4264cfce8f150', 'b2de9272b2bb7acd94840460626284d3274dc8966e4b60b678f4264cfce8f150', NULL, 'والذين يقولون ربنا هب لنا من ازوجنا وذريتنا قره اعين واجعلنا للمتقين اماما', 19, 37, 146, 1, 4, 366, false, NULL),
    (2930, 'tanzil-uthmani-v1.1', 25, 75, 'أُو۟لَٰٓئِكَ يُجْزَوْنَ ٱلْغُرْفَةَ بِمَا صَبَرُوا۟ وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَٰمًا', '8786055f7ebeca1b638e8a4b01cf2c722c91eebd0397c624ade0b34262d0bf7a', 'أُو۟لَٰٓئِكَ يُجْزَوْنَ ٱلْغُرْفَةَ بِمَا صَبَرُوا۟ وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَٰمًا', '8786055f7ebeca1b638e8a4b01cf2c722c91eebd0397c624ade0b34262d0bf7a', '8786055f7ebeca1b638e8a4b01cf2c722c91eebd0397c624ade0b34262d0bf7a', NULL, 'اولئك يجزون الغرفه بما صبروا ويلقون فيها تحيه وسلما', 19, 37, 146, 1, 4, 366, false, NULL),
    (2931, 'tanzil-uthmani-v1.1', 25, 76, 'خَٰلِدِينَ فِيهَا حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا', 'd2477a71351de8a33b6bba52b3ecd46da2b63650d6fe7c49df929e4fafc65800', 'خَٰلِدِينَ فِيهَا حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا', 'd2477a71351de8a33b6bba52b3ecd46da2b63650d6fe7c49df929e4fafc65800', 'd2477a71351de8a33b6bba52b3ecd46da2b63650d6fe7c49df929e4fafc65800', NULL, 'خلدين فيها حسنت مستقرا ومقاما', 19, 37, 146, 1, 4, 366, false, NULL),
    (2932, 'tanzil-uthmani-v1.1', 25, 77, 'قُلْ مَا يَعْبَؤُا۟ بِكُمْ رَبِّى لَوْلَا دُعَآؤُكُمْ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَامًۢا', '01209c45b97ae74e8a84a9a5188a5642449d95a1a5c75d5498cf5c2e58fbf82e', 'قُلْ مَا يَعْبَؤُا۟ بِكُمْ رَبِّى لَوْلَا دُعَآؤُكُمْ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَامًۢا', '01209c45b97ae74e8a84a9a5188a5642449d95a1a5c75d5498cf5c2e58fbf82e', '01209c45b97ae74e8a84a9a5188a5642449d95a1a5c75d5498cf5c2e58fbf82e', NULL, 'قل ما يعبؤا بكم ربي لولا دعاؤكم فقد كذبتم فسوف يكون لزاما', 19, 37, 146, 1, 4, 366, false, NULL),
    (2933, 'tanzil-uthmani-v1.1', 26, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ طسٓمٓ', '6355d27b1ff544257899ea1f1f83f4ea63b34b9b1bc3abbf17acf76a575c61fa', 'طسٓمٓ', '547911999c7d9d4491f025c0f3f7616997cbbf6354d715acc2a778254f009288', '547911999c7d9d4491f025c0f3f7616997cbbf6354d715acc2a778254f009288', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'طسم', 19, 37, 147, 1, 4, 367, false, NULL),
    (2934, 'tanzil-uthmani-v1.1', 26, 2, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'c008249b2b287157ea7a41075aeeeef82370051d2a44a191f4dc6582b7492836', 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'c008249b2b287157ea7a41075aeeeef82370051d2a44a191f4dc6582b7492836', 'c008249b2b287157ea7a41075aeeeef82370051d2a44a191f4dc6582b7492836', NULL, 'تلك ءايت الكتب المبين', 19, 37, 147, 1, 4, 367, false, NULL),
    (2935, 'tanzil-uthmani-v1.1', 26, 3, 'لَعَلَّكَ بَٰخِعٌ نَّفْسَكَ أَلَّا يَكُونُوا۟ مُؤْمِنِينَ', '253d989d0a932eee5b534bf765833aea15b7431b4410a07f87c04e0964bf24e1', 'لَعَلَّكَ بَٰخِعٌ نَّفْسَكَ أَلَّا يَكُونُوا۟ مُؤْمِنِينَ', '253d989d0a932eee5b534bf765833aea15b7431b4410a07f87c04e0964bf24e1', '253d989d0a932eee5b534bf765833aea15b7431b4410a07f87c04e0964bf24e1', NULL, 'لعلك بخع نفسك الا يكونوا مؤمنين', 19, 37, 147, 1, 4, 367, false, NULL),
    (2936, 'tanzil-uthmani-v1.1', 26, 4, 'إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ ٱلسَّمَآءِ ءَايَةً فَظَلَّتْ أَعْنَٰقُهُمْ لَهَا خَٰضِعِينَ', '29c6ea44f9ac17f529f7ccd85db1dd422ea78bc75b325ea1b432725829563bf2', 'إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ ٱلسَّمَآءِ ءَايَةً فَظَلَّتْ أَعْنَٰقُهُمْ لَهَا خَٰضِعِينَ', '29c6ea44f9ac17f529f7ccd85db1dd422ea78bc75b325ea1b432725829563bf2', '29c6ea44f9ac17f529f7ccd85db1dd422ea78bc75b325ea1b432725829563bf2', NULL, 'ان نشا ننزل عليهم من السماء ءايه فظلت اعنقهم لها خضعين', 19, 37, 147, 1, 4, 367, false, NULL),
    (2937, 'tanzil-uthmani-v1.1', 26, 5, 'وَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ ٱلرَّحْمَٰنِ مُحْدَثٍ إِلَّا كَانُوا۟ عَنْهُ مُعْرِضِينَ', '25dadcb7e38c16402e6777c39b6be386609283a5312a63e3998cd6cd9fa5e1a8', 'وَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ ٱلرَّحْمَٰنِ مُحْدَثٍ إِلَّا كَانُوا۟ عَنْهُ مُعْرِضِينَ', '25dadcb7e38c16402e6777c39b6be386609283a5312a63e3998cd6cd9fa5e1a8', '25dadcb7e38c16402e6777c39b6be386609283a5312a63e3998cd6cd9fa5e1a8', NULL, 'وما ياتيهم من ذكر من الرحمن محدث الا كانوا عنه معرضين', 19, 37, 147, 1, 4, 367, false, NULL),
    (2938, 'tanzil-uthmani-v1.1', 26, 6, 'فَقَدْ كَذَّبُوا۟ فَسَيَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'e897665320c53413609609c6ec9adc1ffd520bea72b12a9f7b92635881e4d0b2', 'فَقَدْ كَذَّبُوا۟ فَسَيَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'e897665320c53413609609c6ec9adc1ffd520bea72b12a9f7b92635881e4d0b2', 'e897665320c53413609609c6ec9adc1ffd520bea72b12a9f7b92635881e4d0b2', NULL, 'فقد كذبوا فسياتيهم انبؤا ما كانوا به يستهزءون', 19, 37, 147, 1, 4, 367, false, NULL),
    (2939, 'tanzil-uthmani-v1.1', 26, 7, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلْأَرْضِ كَمْ أَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', '6084d8102636c39e89dc5a6d04514a45a7fbe4fcae668fdda97fa3b97428ca9e', 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلْأَرْضِ كَمْ أَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', '6084d8102636c39e89dc5a6d04514a45a7fbe4fcae668fdda97fa3b97428ca9e', '6084d8102636c39e89dc5a6d04514a45a7fbe4fcae668fdda97fa3b97428ca9e', NULL, 'اولم يروا الي الارض كم انبتنا فيها من كل زوج كريم', 19, 37, 147, 1, 4, 367, false, NULL),
    (2940, 'tanzil-uthmani-v1.1', 26, 8, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '8dc980d41ec4ecf9b57c6cdd2094ae998a1081ee9cdc7058079cc6ce5b39ab1a', 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '8dc980d41ec4ecf9b57c6cdd2094ae998a1081ee9cdc7058079cc6ce5b39ab1a', '8dc980d41ec4ecf9b57c6cdd2094ae998a1081ee9cdc7058079cc6ce5b39ab1a', NULL, 'ان في ذلك لايه وما كان اكثرهم مؤمنين', 19, 37, 147, 1, 4, 367, false, NULL),
    (2941, 'tanzil-uthmani-v1.1', 26, 9, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '2ec28d382d6bce2169e10be9ea2538504c5c5b5a13983b3ec6acc9dd8f06aa2b', 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '2ec28d382d6bce2169e10be9ea2538504c5c5b5a13983b3ec6acc9dd8f06aa2b', '2ec28d382d6bce2169e10be9ea2538504c5c5b5a13983b3ec6acc9dd8f06aa2b', NULL, 'وان ربك لهو العزيز الرحيم', 19, 37, 147, 1, 4, 367, false, NULL),
    (2942, 'tanzil-uthmani-v1.1', 26, 10, 'وَإِذْ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئْتِ ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '32fd4189d4fdd9f708c1cfe9d9d91f851bfbeee5291bb33236eb73d63fcfb95b', 'وَإِذْ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئْتِ ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '32fd4189d4fdd9f708c1cfe9d9d91f851bfbeee5291bb33236eb73d63fcfb95b', '32fd4189d4fdd9f708c1cfe9d9d91f851bfbeee5291bb33236eb73d63fcfb95b', NULL, 'واذ نادي ربك موسي ان ائت القوم الظلمين', 19, 37, 147, 1, 4, 367, false, NULL),
    (2943, 'tanzil-uthmani-v1.1', 26, 11, 'قَوْمَ فِرْعَوْنَ أَلَا يَتَّقُونَ', 'b0bd952ef5c2cb57c1b70e9cc4202e51aa86741379fd757c717579e19cf60161', 'قَوْمَ فِرْعَوْنَ أَلَا يَتَّقُونَ', 'b0bd952ef5c2cb57c1b70e9cc4202e51aa86741379fd757c717579e19cf60161', 'b0bd952ef5c2cb57c1b70e9cc4202e51aa86741379fd757c717579e19cf60161', NULL, 'قوم فرعون الا يتقون', 19, 37, 147, 1, 4, 367, false, NULL),
    (2944, 'tanzil-uthmani-v1.1', 26, 12, 'قَالَ رَبِّ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', 'af8c6266de001e7c25bbaf3db1792ca3d308fe2a891341189c962ee42dceacb1', 'قَالَ رَبِّ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', 'af8c6266de001e7c25bbaf3db1792ca3d308fe2a891341189c962ee42dceacb1', 'af8c6266de001e7c25bbaf3db1792ca3d308fe2a891341189c962ee42dceacb1', NULL, 'قال رب اني اخاف ان يكذبون', 19, 37, 147, 1, 4, 367, false, NULL),
    (2945, 'tanzil-uthmani-v1.1', 26, 13, 'وَيَضِيقُ صَدْرِى وَلَا يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَٰرُونَ', 'd6501acd0d6bba2cf1e97d15ae2051127af9b272a8668bf0adb60e441e4b40a5', 'وَيَضِيقُ صَدْرِى وَلَا يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَٰرُونَ', 'd6501acd0d6bba2cf1e97d15ae2051127af9b272a8668bf0adb60e441e4b40a5', 'd6501acd0d6bba2cf1e97d15ae2051127af9b272a8668bf0adb60e441e4b40a5', NULL, 'ويضيق صدري ولا ينطلق لساني فارسل الي هرون', 19, 37, 147, 1, 4, 367, false, NULL),
    (2946, 'tanzil-uthmani-v1.1', 26, 14, 'وَلَهُمْ عَلَىَّ ذَنۢبٌ فَأَخَافُ أَن يَقْتُلُونِ', '9b556f90fabe294ac4357a4df1a085edec2b4c3fd6457d950d556d86ec69ae61', 'وَلَهُمْ عَلَىَّ ذَنۢبٌ فَأَخَافُ أَن يَقْتُلُونِ', '9b556f90fabe294ac4357a4df1a085edec2b4c3fd6457d950d556d86ec69ae61', '9b556f90fabe294ac4357a4df1a085edec2b4c3fd6457d950d556d86ec69ae61', NULL, 'ولهم علي ذنب فاخاف ان يقتلون', 19, 37, 147, 1, 4, 367, false, NULL),
    (2947, 'tanzil-uthmani-v1.1', 26, 15, 'قَالَ كَلَّا فَٱذْهَبَا بِـَٔايَٰتِنَآ إِنَّا مَعَكُم مُّسْتَمِعُونَ', '89f3dc7397610c99602b59711ccd258bd4eb80099b0f43dc57c92387e504467d', 'قَالَ كَلَّا فَٱذْهَبَا بِـَٔايَٰتِنَآ إِنَّا مَعَكُم مُّسْتَمِعُونَ', '89f3dc7397610c99602b59711ccd258bd4eb80099b0f43dc57c92387e504467d', '89f3dc7397610c99602b59711ccd258bd4eb80099b0f43dc57c92387e504467d', NULL, 'قال كلا فاذهبا بايتنا انا معكم مستمعون', 19, 37, 147, 1, 4, 367, false, NULL),
    (2948, 'tanzil-uthmani-v1.1', 26, 16, 'فَأْتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', '35f014f8c1fc3d68fbe6f732d835fe9979e6899f5a59e0c8806476bc929f1e71', 'فَأْتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', '35f014f8c1fc3d68fbe6f732d835fe9979e6899f5a59e0c8806476bc929f1e71', '35f014f8c1fc3d68fbe6f732d835fe9979e6899f5a59e0c8806476bc929f1e71', NULL, 'فاتيا فرعون فقولا انا رسول رب العلمين', 19, 37, 147, 1, 4, 367, false, NULL),
    (2949, 'tanzil-uthmani-v1.1', 26, 17, 'أَنْ أَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ', 'dfed7f0eb169c21fe406dae6ec34ff95d4392536239b06d10a5a391c9ce6b300', 'أَنْ أَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ', 'dfed7f0eb169c21fe406dae6ec34ff95d4392536239b06d10a5a391c9ce6b300', 'dfed7f0eb169c21fe406dae6ec34ff95d4392536239b06d10a5a391c9ce6b300', NULL, 'ان ارسل معنا بني اسرءيل', 19, 37, 147, 1, 4, 367, false, NULL),
    (2950, 'tanzil-uthmani-v1.1', 26, 18, 'قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ', '7c5d1c76de27f931c4817933223dbabf51dc461b7db524e9489521d7987e3738', 'قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ', '7c5d1c76de27f931c4817933223dbabf51dc461b7db524e9489521d7987e3738', '7c5d1c76de27f931c4817933223dbabf51dc461b7db524e9489521d7987e3738', NULL, 'قال الم نربك فينا وليدا ولبثت فينا من عمرك سنين', 19, 37, 147, 1, 4, 367, false, NULL),
    (2951, 'tanzil-uthmani-v1.1', 26, 19, 'وَفَعَلْتَ فَعْلَتَكَ ٱلَّتِى فَعَلْتَ وَأَنتَ مِنَ ٱلْكَٰفِرِينَ', '139e130d03bcb37e34210840aee8b31376cc8fd42aa55c59e11a22bf3356286e', 'وَفَعَلْتَ فَعْلَتَكَ ٱلَّتِى فَعَلْتَ وَأَنتَ مِنَ ٱلْكَٰفِرِينَ', '139e130d03bcb37e34210840aee8b31376cc8fd42aa55c59e11a22bf3356286e', '139e130d03bcb37e34210840aee8b31376cc8fd42aa55c59e11a22bf3356286e', NULL, 'وفعلت فعلتك التي فعلت وانت من الكفرين', 19, 37, 147, 1, 4, 367, false, NULL),
    (2952, 'tanzil-uthmani-v1.1', 26, 20, 'قَالَ فَعَلْتُهَآ إِذًا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ', 'badc7856bd3f68af2212e12c3188411c40a516a9d92667b4410d32036fd0c3d1', 'قَالَ فَعَلْتُهَآ إِذًا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ', 'badc7856bd3f68af2212e12c3188411c40a516a9d92667b4410d32036fd0c3d1', 'badc7856bd3f68af2212e12c3188411c40a516a9d92667b4410d32036fd0c3d1', NULL, 'قال فعلتها اذا وانا من الضالين', 19, 37, 147, 1, 4, 368, false, NULL),
    (2953, 'tanzil-uthmani-v1.1', 26, 21, 'فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْمًا وَجَعَلَنِى مِنَ ٱلْمُرْسَلِينَ', 'b946ba1a03159fd3f5c0b9098e2e6e87ea99dd9332cc4cdeecbe132a9cf4c4a1', 'فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْمًا وَجَعَلَنِى مِنَ ٱلْمُرْسَلِينَ', 'b946ba1a03159fd3f5c0b9098e2e6e87ea99dd9332cc4cdeecbe132a9cf4c4a1', 'b946ba1a03159fd3f5c0b9098e2e6e87ea99dd9332cc4cdeecbe132a9cf4c4a1', NULL, 'ففررت منكم لما خفتكم فوهب لي ربي حكما وجعلني من المرسلين', 19, 37, 147, 1, 4, 368, false, NULL),
    (2954, 'tanzil-uthmani-v1.1', 26, 22, 'وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ', 'd5ed644edddd54987f5f5afb8a3192a124fb81cf263b83aecbb28485c12d30d7', 'وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ', 'd5ed644edddd54987f5f5afb8a3192a124fb81cf263b83aecbb28485c12d30d7', 'd5ed644edddd54987f5f5afb8a3192a124fb81cf263b83aecbb28485c12d30d7', NULL, 'وتلك نعمه تمنها علي ان عبدت بني اسرءيل', 19, 37, 147, 1, 4, 368, false, NULL),
    (2955, 'tanzil-uthmani-v1.1', 26, 23, 'قَالَ فِرْعَوْنُ وَمَا رَبُّ ٱلْعَٰلَمِينَ', '01da358a780fe1cebed8928c055986a7afcf17d4a7fecc8895d41bdc0111cf58', 'قَالَ فِرْعَوْنُ وَمَا رَبُّ ٱلْعَٰلَمِينَ', '01da358a780fe1cebed8928c055986a7afcf17d4a7fecc8895d41bdc0111cf58', '01da358a780fe1cebed8928c055986a7afcf17d4a7fecc8895d41bdc0111cf58', NULL, 'قال فرعون وما رب العلمين', 19, 37, 147, 1, 4, 368, false, NULL),
    (2956, 'tanzil-uthmani-v1.1', 26, 24, 'قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ إِن كُنتُم مُّوقِنِينَ', '3cb0bf703401e9e092a213bfcecc053ed056bb4bf842b23eca9e36445355042f', 'قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ إِن كُنتُم مُّوقِنِينَ', '3cb0bf703401e9e092a213bfcecc053ed056bb4bf842b23eca9e36445355042f', '3cb0bf703401e9e092a213bfcecc053ed056bb4bf842b23eca9e36445355042f', NULL, 'قال رب السموت والارض وما بينهما ان كنتم موقنين', 19, 37, 147, 1, 4, 368, false, NULL),
    (2957, 'tanzil-uthmani-v1.1', 26, 25, 'قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ', 'c82e8c85b18a8f5025e702446c30cc5128879656586a9fb7bc8d1e9940ebceaa', 'قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ', 'c82e8c85b18a8f5025e702446c30cc5128879656586a9fb7bc8d1e9940ebceaa', 'c82e8c85b18a8f5025e702446c30cc5128879656586a9fb7bc8d1e9940ebceaa', NULL, 'قال لمن حوله الا تستمعون', 19, 37, 147, 1, 4, 368, false, NULL),
    (2958, 'tanzil-uthmani-v1.1', 26, 26, 'قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', '96bda2cd5ef7a18bc62b44d7d49848a6edf60a0e97020f436e4453804c3f3062', 'قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', '96bda2cd5ef7a18bc62b44d7d49848a6edf60a0e97020f436e4453804c3f3062', '96bda2cd5ef7a18bc62b44d7d49848a6edf60a0e97020f436e4453804c3f3062', NULL, 'قال ربكم ورب ءابائكم الاولين', 19, 37, 147, 1, 4, 368, false, NULL),
