    (2979, 'tanzil-uthmani-v1.1', 26, 47, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', '44c4f7e31cb2d958010c9efd86858f9b86e703502b7f43de87bf321aa119f263', 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', '44c4f7e31cb2d958010c9efd86858f9b86e703502b7f43de87bf321aa119f263', '44c4f7e31cb2d958010c9efd86858f9b86e703502b7f43de87bf321aa119f263', NULL, 'قالوا ءامنا برب العلمين', 19, 37, 147, 1, 4, 369, false, NULL),
    (2980, 'tanzil-uthmani-v1.1', 26, 48, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'd305a99b800520707ad552e6b13323196b763f6e70dcbea623242935da54f63b', 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 'd305a99b800520707ad552e6b13323196b763f6e70dcbea623242935da54f63b', 'd305a99b800520707ad552e6b13323196b763f6e70dcbea623242935da54f63b', NULL, 'رب موسي وهرون', 19, 37, 147, 1, 4, 369, false, NULL),
    (2981, 'tanzil-uthmani-v1.1', 26, 49, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَسَوْفَ تَعْلَمُونَ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', '8244c2e9a76ebd5da01803122d102a3b59fbbd0d7cf2f9b18d5c9f977083ab81', 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَسَوْفَ تَعْلَمُونَ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', '8244c2e9a76ebd5da01803122d102a3b59fbbd0d7cf2f9b18d5c9f977083ab81', '8244c2e9a76ebd5da01803122d102a3b59fbbd0d7cf2f9b18d5c9f977083ab81', NULL, 'قال ءامنتم له قبل ان ءاذن لكم انه لكبيركم الذي علمكم السحر فلسوف تعلمون لاقطعن ايديكم وارجلكم من خلف ولاصلبنكم اجمعين', 19, 37, 147, 1, 4, 369, false, NULL),
    (2982, 'tanzil-uthmani-v1.1', 26, 50, 'قَالُوا۟ لَا ضَيْرَ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', '3291e47019fbf8f2a3b5e8b7a450894eff143fe1b7691793a9cbcbc17e32ddb6', 'قَالُوا۟ لَا ضَيْرَ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', '3291e47019fbf8f2a3b5e8b7a450894eff143fe1b7691793a9cbcbc17e32ddb6', '3291e47019fbf8f2a3b5e8b7a450894eff143fe1b7691793a9cbcbc17e32ddb6', NULL, 'قالوا لا ضير انا الي ربنا منقلبون', 19, 37, 147, 1, 4, 369, false, NULL),
    (2983, 'tanzil-uthmani-v1.1', 26, 51, 'إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلْمُؤْمِنِينَ', 'a5b771d8000f08cf08a9ed477173ce85b3a8d0faba7450a6c12b6ba85d1d17e8', 'إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلْمُؤْمِنِينَ', 'a5b771d8000f08cf08a9ed477173ce85b3a8d0faba7450a6c12b6ba85d1d17e8', 'a5b771d8000f08cf08a9ed477173ce85b3a8d0faba7450a6c12b6ba85d1d17e8', NULL, 'انا نطمع ان يغفر لنا ربنا خطينا ان كنا اول المؤمنين', 19, 37, 147, 1, 4, 369, false, NULL),
    (2984, 'tanzil-uthmani-v1.1', 26, 52, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِىٓ إِنَّكُم مُّتَّبَعُونَ', '6409647e7c4b47a38997a3fab492b7cd16a8eda908a859a09508dcb31646031c', 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِىٓ إِنَّكُم مُّتَّبَعُونَ', '6409647e7c4b47a38997a3fab492b7cd16a8eda908a859a09508dcb31646031c', '6409647e7c4b47a38997a3fab492b7cd16a8eda908a859a09508dcb31646031c', NULL, 'واوحينا الي موسي ان اسر بعبادي انكم متبعون', 19, 37, 148, 1, 4, 369, false, NULL),
    (2985, 'tanzil-uthmani-v1.1', 26, 53, 'فَأَرْسَلَ فِرْعَوْنُ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', '39e2680b7a3e97645040c0a0c4d16f61d958bd0318e6b8ef8d5833db60cf61d4', 'فَأَرْسَلَ فِرْعَوْنُ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', '39e2680b7a3e97645040c0a0c4d16f61d958bd0318e6b8ef8d5833db60cf61d4', '39e2680b7a3e97645040c0a0c4d16f61d958bd0318e6b8ef8d5833db60cf61d4', NULL, 'فارسل فرعون في المدائن حشرين', 19, 37, 148, 1, 4, 369, false, NULL),
    (2986, 'tanzil-uthmani-v1.1', 26, 54, 'إِنَّ هَٰٓؤُلَآءِ لَشِرْذِمَةٌ قَلِيلُونَ', '7369deee38157dee2352cab7eb1f149f340cefd2bb08c52f6f23d5d7d75a1083', 'إِنَّ هَٰٓؤُلَآءِ لَشِرْذِمَةٌ قَلِيلُونَ', '7369deee38157dee2352cab7eb1f149f340cefd2bb08c52f6f23d5d7d75a1083', '7369deee38157dee2352cab7eb1f149f340cefd2bb08c52f6f23d5d7d75a1083', NULL, 'ان هؤلاء لشرذمه قليلون', 19, 37, 148, 1, 4, 369, false, NULL),
    (2987, 'tanzil-uthmani-v1.1', 26, 55, 'وَإِنَّهُمْ لَنَا لَغَآئِظُونَ', '2cdebf2429cefec12b1d1b197b6c3f00ed1a3e2f0919f629bf528b0f86773d02', 'وَإِنَّهُمْ لَنَا لَغَآئِظُونَ', '2cdebf2429cefec12b1d1b197b6c3f00ed1a3e2f0919f629bf528b0f86773d02', '2cdebf2429cefec12b1d1b197b6c3f00ed1a3e2f0919f629bf528b0f86773d02', NULL, 'وانهم لنا لغائظون', 19, 37, 148, 1, 4, 369, false, NULL),
    (2988, 'tanzil-uthmani-v1.1', 26, 56, 'وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ', '40f72d5c87da9280045f44fddd96ef4534e7c8d08a728abd5e4c10cf9228a4b3', 'وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ', '40f72d5c87da9280045f44fddd96ef4534e7c8d08a728abd5e4c10cf9228a4b3', '40f72d5c87da9280045f44fddd96ef4534e7c8d08a728abd5e4c10cf9228a4b3', NULL, 'وانا لجميع حذرون', 19, 37, 148, 1, 4, 369, false, NULL),
    (2989, 'tanzil-uthmani-v1.1', 26, 57, 'فَأَخْرَجْنَٰهُم مِّن جَنَّٰتٍ وَعُيُونٍ', '48f9766d2eba54d068faf2ede77b3f6bdef1ddac537224076662ed1adb3eab98', 'فَأَخْرَجْنَٰهُم مِّن جَنَّٰتٍ وَعُيُونٍ', '48f9766d2eba54d068faf2ede77b3f6bdef1ddac537224076662ed1adb3eab98', '48f9766d2eba54d068faf2ede77b3f6bdef1ddac537224076662ed1adb3eab98', NULL, 'فاخرجنهم من جنت وعيون', 19, 37, 148, 1, 4, 369, false, NULL),
    (2990, 'tanzil-uthmani-v1.1', 26, 58, 'وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ', '24564a6fa13b06eb9269e81fe9b3b058c1255237839facea9544ec07f3d17338', 'وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ', '24564a6fa13b06eb9269e81fe9b3b058c1255237839facea9544ec07f3d17338', '24564a6fa13b06eb9269e81fe9b3b058c1255237839facea9544ec07f3d17338', NULL, 'وكنوز ومقام كريم', 19, 37, 148, 1, 4, 369, false, NULL),
    (2991, 'tanzil-uthmani-v1.1', 26, 59, 'كَذَٰلِكَ وَأَوْرَثْنَٰهَا بَنِىٓ إِسْرَٰٓءِيلَ', '65fc4acfb6b9a1649ca5a88e94621fd8b8510ac0f63953af696d977ea2eda27a', 'كَذَٰلِكَ وَأَوْرَثْنَٰهَا بَنِىٓ إِسْرَٰٓءِيلَ', '65fc4acfb6b9a1649ca5a88e94621fd8b8510ac0f63953af696d977ea2eda27a', '65fc4acfb6b9a1649ca5a88e94621fd8b8510ac0f63953af696d977ea2eda27a', NULL, 'كذلك واورثنها بني اسرءيل', 19, 37, 148, 1, 4, 369, false, NULL),
    (2992, 'tanzil-uthmani-v1.1', 26, 60, 'فَأَتْبَعُوهُم مُّشْرِقِينَ', '8559227d463600181ed03c2aa0f67be6ae0e6e2fa43cc00c119cae40f4bfdda0', 'فَأَتْبَعُوهُم مُّشْرِقِينَ', '8559227d463600181ed03c2aa0f67be6ae0e6e2fa43cc00c119cae40f4bfdda0', '8559227d463600181ed03c2aa0f67be6ae0e6e2fa43cc00c119cae40f4bfdda0', NULL, 'فاتبعوهم مشرقين', 19, 37, 148, 1, 4, 369, false, NULL),
    (2993, 'tanzil-uthmani-v1.1', 26, 61, 'فَلَمَّا تَرَٰٓءَا ٱلْجَمْعَانِ قَالَ أَصْحَٰبُ مُوسَىٰٓ إِنَّا لَمُدْرَكُونَ', '40f39cf37a3eaddada17660bcd8458b1cf838509609e55543263336211f442f3', 'فَلَمَّا تَرَٰٓءَا ٱلْجَمْعَانِ قَالَ أَصْحَٰبُ مُوسَىٰٓ إِنَّا لَمُدْرَكُونَ', '40f39cf37a3eaddada17660bcd8458b1cf838509609e55543263336211f442f3', '40f39cf37a3eaddada17660bcd8458b1cf838509609e55543263336211f442f3', NULL, 'فلما ترءا الجمعان قال اصحب موسي انا لمدركون', 19, 37, 148, 1, 4, 370, false, NULL),
    (2994, 'tanzil-uthmani-v1.1', 26, 62, 'قَالَ كَلَّآ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ', 'f3df0fe6e175dfb2665c050792b9d49084fbc8e31e2f495181c91d9ff74d7d3f', 'قَالَ كَلَّآ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ', 'f3df0fe6e175dfb2665c050792b9d49084fbc8e31e2f495181c91d9ff74d7d3f', 'f3df0fe6e175dfb2665c050792b9d49084fbc8e31e2f495181c91d9ff74d7d3f', NULL, 'قال كلا ان معي ربي سيهدين', 19, 37, 148, 1, 4, 370, false, NULL),
    (2995, 'tanzil-uthmani-v1.1', 26, 63, 'فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ فَٱنفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَٱلطَّوْدِ ٱلْعَظِيمِ', 'd7dd49aa2dc6d84f77b6db9060095cfbf669e649f17146a7611a0b0d80f3e812', 'فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ فَٱنفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَٱلطَّوْدِ ٱلْعَظِيمِ', 'd7dd49aa2dc6d84f77b6db9060095cfbf669e649f17146a7611a0b0d80f3e812', 'd7dd49aa2dc6d84f77b6db9060095cfbf669e649f17146a7611a0b0d80f3e812', NULL, 'فاوحينا الي موسي ان اضرب بعصاك البحر فانفلق فكان كل فرق كالطود العظيم', 19, 37, 148, 1, 4, 370, false, NULL),
    (2996, 'tanzil-uthmani-v1.1', 26, 64, 'وَأَزْلَفْنَا ثَمَّ ٱلْـَٔاخَرِينَ', 'e3fbe84a1ee8611d031f9ea103ecede03c5c6bf37e7952ade5b2c5f93cbd84ab', 'وَأَزْلَفْنَا ثَمَّ ٱلْـَٔاخَرِينَ', 'e3fbe84a1ee8611d031f9ea103ecede03c5c6bf37e7952ade5b2c5f93cbd84ab', 'e3fbe84a1ee8611d031f9ea103ecede03c5c6bf37e7952ade5b2c5f93cbd84ab', NULL, 'وازلفنا ثم الاخرين', 19, 37, 148, 1, 4, 370, false, NULL),
    (2997, 'tanzil-uthmani-v1.1', 26, 65, 'وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ', '13e952ebec0715d3a184a3c55b752b609d543920698a333ac890d286219c9ddb', 'وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ', '13e952ebec0715d3a184a3c55b752b609d543920698a333ac890d286219c9ddb', '13e952ebec0715d3a184a3c55b752b609d543920698a333ac890d286219c9ddb', NULL, 'وانجينا موسي ومن معه اجمعين', 19, 37, 148, 1, 4, 370, false, NULL),
    (2998, 'tanzil-uthmani-v1.1', 26, 66, 'ثُمَّ أَغْرَقْنَا ٱلْـَٔاخَرِينَ', 'b0c9b489f9d8c539e9531b9567c5ef6e8d45cece1f8dfbffd9992a74a0b354f5', 'ثُمَّ أَغْرَقْنَا ٱلْـَٔاخَرِينَ', 'b0c9b489f9d8c539e9531b9567c5ef6e8d45cece1f8dfbffd9992a74a0b354f5', 'b0c9b489f9d8c539e9531b9567c5ef6e8d45cece1f8dfbffd9992a74a0b354f5', NULL, 'ثم اغرقنا الاخرين', 19, 37, 148, 1, 4, 370, false, NULL),
    (2999, 'tanzil-uthmani-v1.1', 26, 67, 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '8dc980d41ec4ecf9b57c6cdd2094ae998a1081ee9cdc7058079cc6ce5b39ab1a', 'إِنَّ فِى ذَٰلِكَ لَـَٔايَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', '8dc980d41ec4ecf9b57c6cdd2094ae998a1081ee9cdc7058079cc6ce5b39ab1a', '8dc980d41ec4ecf9b57c6cdd2094ae998a1081ee9cdc7058079cc6ce5b39ab1a', NULL, 'ان في ذلك لايه وما كان اكثرهم مؤمنين', 19, 37, 148, 1, 4, 370, false, NULL),
    (3000, 'tanzil-uthmani-v1.1', 26, 68, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '2ec28d382d6bce2169e10be9ea2538504c5c5b5a13983b3ec6acc9dd8f06aa2b', 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '2ec28d382d6bce2169e10be9ea2538504c5c5b5a13983b3ec6acc9dd8f06aa2b', '2ec28d382d6bce2169e10be9ea2538504c5c5b5a13983b3ec6acc9dd8f06aa2b', NULL, 'وان ربك لهو العزيز الرحيم', 19, 37, 148, 1, 4, 370, false, NULL)
