    (3155, 'tanzil-uthmani-v1.1', 26, 223, 'يُلْقُونَ ٱلسَّمْعَ وَأَكْثَرُهُمْ كَٰذِبُونَ', 'a40f846c89368741f99a29c1591af913c113ab12444db05f969051c21e3b8321', 'يُلْقُونَ ٱلسَّمْعَ وَأَكْثَرُهُمْ كَٰذِبُونَ', 'a40f846c89368741f99a29c1591af913c113ab12444db05f969051c21e3b8321', 'a40f846c89368741f99a29c1591af913c113ab12444db05f969051c21e3b8321', NULL, 'يلقون السمع واكثرهم كذبون', 19, 38, 150, 1, 4, 376, false, NULL),
    (3156, 'tanzil-uthmani-v1.1', 26, 224, 'وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلْغَاوُۥنَ', 'feeb796ed83696ecd07e9a66c08ee12db129fde25b45234292424e5a598ca4d9', 'وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلْغَاوُۥنَ', 'feeb796ed83696ecd07e9a66c08ee12db129fde25b45234292424e5a598ca4d9', 'feeb796ed83696ecd07e9a66c08ee12db129fde25b45234292424e5a598ca4d9', NULL, 'والشعراء يتبعهم الغاون', 19, 38, 150, 1, 4, 376, false, NULL),
    (3157, 'tanzil-uthmani-v1.1', 26, 225, 'أَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍ يَهِيمُونَ', '7b24e60d2bfc1e5d43918b8326a62ace86bcc1789ca3917e68bf0dd0dace8488', 'أَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍ يَهِيمُونَ', '7b24e60d2bfc1e5d43918b8326a62ace86bcc1789ca3917e68bf0dd0dace8488', '7b24e60d2bfc1e5d43918b8326a62ace86bcc1789ca3917e68bf0dd0dace8488', NULL, 'الم تر انهم في كل واد يهيمون', 19, 38, 150, 1, 4, 376, false, NULL),
    (3158, 'tanzil-uthmani-v1.1', 26, 226, 'وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ', '92588c72d2af3b31a5ecfe56ff5d7b0e57d2461f39fa5ebc9056983bcb02480b', 'وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ', '92588c72d2af3b31a5ecfe56ff5d7b0e57d2461f39fa5ebc9056983bcb02480b', '92588c72d2af3b31a5ecfe56ff5d7b0e57d2461f39fa5ebc9056983bcb02480b', NULL, 'وانهم يقولون ما لا يفعلون', 19, 38, 150, 1, 4, 376, false, NULL),
    (3159, 'tanzil-uthmani-v1.1', 26, 227, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَذَكَرُوا۟ ٱللَّهَ كَثِيرًا وَٱنتَصَرُوا۟ مِنۢ بَعْدِ مَا ظُلِمُوا۟ وَسَيَعْلَمُ ٱلَّذِينَ ظَلَمُوٓا۟ أَىَّ مُنقَلَبٍ يَنقَلِبُونَ', 'ee4b1b7a1c3e35144e90b93d98fd4e27d7d50ce6c70a5e659bd75bf1258a9c03', 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَذَكَرُوا۟ ٱللَّهَ كَثِيرًا وَٱنتَصَرُوا۟ مِنۢ بَعْدِ مَا ظُلِمُوا۟ وَسَيَعْلَمُ ٱلَّذِينَ ظَلَمُوٓا۟ أَىَّ مُنقَلَبٍ يَنقَلِبُونَ', 'ee4b1b7a1c3e35144e90b93d98fd4e27d7d50ce6c70a5e659bd75bf1258a9c03', 'ee4b1b7a1c3e35144e90b93d98fd4e27d7d50ce6c70a5e659bd75bf1258a9c03', NULL, 'الا الذين ءامنوا وعملوا الصلحت وذكروا الله كثيرا وانتصروا من بعد ما ظلموا وسيعلم الذين ظلموا اي منقلب ينقلبون', 19, 38, 150, 1, 4, 376, false, NULL),
    (3160, 'tanzil-uthmani-v1.1', 27, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ طسٓ تِلْكَ ءَايَٰتُ ٱلْقُرْءَانِ وَكِتَابٍ مُّبِينٍ', 'f7144d521e5d679d01b521935bc4c689953f81f7024dde074088a2cc8efb2cc7', 'طسٓ تِلْكَ ءَايَٰتُ ٱلْقُرْءَانِ وَكِتَابٍ مُّبِينٍ', '2cf3e613b9cf0cbcc639bd6906eaf15d3feb9f64f4e2ecfc1c10021d2094c23f', '2cf3e613b9cf0cbcc639bd6906eaf15d3feb9f64f4e2ecfc1c10021d2094c23f', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'طس تلك ءايت القرءان وكتاب مبين', 19, 38, 151, 1, 5, 377, false, NULL),
    (3161, 'tanzil-uthmani-v1.1', 27, 2, 'هُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', '976f61b5b2db838fe62c6145a61fc728eabc3ca57c544167d78bcde16615a922', 'هُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', '976f61b5b2db838fe62c6145a61fc728eabc3ca57c544167d78bcde16615a922', '976f61b5b2db838fe62c6145a61fc728eabc3ca57c544167d78bcde16615a922', NULL, 'هدي وبشري للمؤمنين', 19, 38, 151, 1, 5, 377, false, NULL),
    (3162, 'tanzil-uthmani-v1.1', 27, 3, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', '83086c40f75834468b6e8e835e2610c0cca93e606adf21fd2cff1931c578f4de', 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', '83086c40f75834468b6e8e835e2610c0cca93e606adf21fd2cff1931c578f4de', '83086c40f75834468b6e8e835e2610c0cca93e606adf21fd2cff1931c578f4de', NULL, 'الذين يقيمون الصلوه ويؤتون الزكوه وهم بالاخره هم يوقنون', 19, 38, 151, 1, 5, 377, false, NULL),
    (3163, 'tanzil-uthmani-v1.1', 27, 4, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ زَيَّنَّا لَهُمْ أَعْمَٰلَهُمْ فَهُمْ يَعْمَهُونَ', '3471626612b41aa225ed9859856d617cf0792f62ec088a9284b58d28066ad6ac', 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ زَيَّنَّا لَهُمْ أَعْمَٰلَهُمْ فَهُمْ يَعْمَهُونَ', '3471626612b41aa225ed9859856d617cf0792f62ec088a9284b58d28066ad6ac', '3471626612b41aa225ed9859856d617cf0792f62ec088a9284b58d28066ad6ac', NULL, 'ان الذين لا يؤمنون بالاخره زينا لهم اعملهم فهم يعمهون', 19, 38, 151, 1, 5, 377, false, NULL),
    (3164, 'tanzil-uthmani-v1.1', 27, 5, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَهُمْ سُوٓءُ ٱلْعَذَابِ وَهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', '2444dffacf15260c4f0260daf82bbc84646846e25e0e5493bce1a6faa1262f57', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَهُمْ سُوٓءُ ٱلْعَذَابِ وَهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', '2444dffacf15260c4f0260daf82bbc84646846e25e0e5493bce1a6faa1262f57', '2444dffacf15260c4f0260daf82bbc84646846e25e0e5493bce1a6faa1262f57', NULL, 'اولئك الذين لهم سوء العذاب وهم في الاخره هم الاخسرون', 19, 38, 151, 1, 5, 377, false, NULL),
    (3165, 'tanzil-uthmani-v1.1', 27, 6, 'وَإِنَّكَ لَتُلَقَّى ٱلْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍ', 'e21deede953f82257244b33bdcd013c8a7065037fb4b014c448c47833d43eb10', 'وَإِنَّكَ لَتُلَقَّى ٱلْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍ', 'e21deede953f82257244b33bdcd013c8a7065037fb4b014c448c47833d43eb10', 'e21deede953f82257244b33bdcd013c8a7065037fb4b014c448c47833d43eb10', NULL, 'وانك لتلقي القرءان من لدن حكيم عليم', 19, 38, 151, 1, 5, 377, false, NULL),
    (3166, 'tanzil-uthmani-v1.1', 27, 7, 'إِذْ قَالَ مُوسَىٰ لِأَهْلِهِۦٓ إِنِّىٓ ءَانَسْتُ نَارًا سَـَٔاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ ءَاتِيكُم بِشِهَابٍ قَبَسٍ لَّعَلَّكُمْ تَصْطَلُونَ', 'd9a69006f0496371fcffb316d37a2bee6aef996fb45e7448d54b19a00eb7116e', 'إِذْ قَالَ مُوسَىٰ لِأَهْلِهِۦٓ إِنِّىٓ ءَانَسْتُ نَارًا سَـَٔاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ ءَاتِيكُم بِشِهَابٍ قَبَسٍ لَّعَلَّكُمْ تَصْطَلُونَ', 'd9a69006f0496371fcffb316d37a2bee6aef996fb45e7448d54b19a00eb7116e', 'd9a69006f0496371fcffb316d37a2bee6aef996fb45e7448d54b19a00eb7116e', NULL, 'اذ قال موسي لاهله اني ءانست نارا ساتيكم منها بخبر او ءاتيكم بشهاب قبس لعلكم تصطلون', 19, 38, 151, 1, 5, 377, false, NULL),
    (3167, 'tanzil-uthmani-v1.1', 27, 8, 'فَلَمَّا جَآءَهَا نُودِىَ أَنۢ بُورِكَ مَن فِى ٱلنَّارِ وَمَنْ حَوْلَهَا وَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَٰلَمِينَ', '815594735394a0645b82a8b7633d424ee09318f812600c2266a97371d37df1af', 'فَلَمَّا جَآءَهَا نُودِىَ أَنۢ بُورِكَ مَن فِى ٱلنَّارِ وَمَنْ حَوْلَهَا وَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَٰلَمِينَ', '815594735394a0645b82a8b7633d424ee09318f812600c2266a97371d37df1af', '815594735394a0645b82a8b7633d424ee09318f812600c2266a97371d37df1af', NULL, 'فلما جاءها نودي ان بورك من في النار ومن حولها وسبحن الله رب العلمين', 19, 38, 151, 1, 5, 377, false, NULL),
    (3168, 'tanzil-uthmani-v1.1', 27, 9, 'يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', '7d7932777cfa9862dddb0c74585667825f6bcac2b8d6939bbb264d67db02853a', 'يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', '7d7932777cfa9862dddb0c74585667825f6bcac2b8d6939bbb264d67db02853a', '7d7932777cfa9862dddb0c74585667825f6bcac2b8d6939bbb264d67db02853a', NULL, 'يموسي انه انا الله العزيز الحكيم', 19, 38, 151, 1, 5, 377, false, NULL),
    (3169, 'tanzil-uthmani-v1.1', 27, 10, 'وَأَلْقِ عَصَاكَ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ يَٰمُوسَىٰ لَا تَخَفْ إِنِّى لَا يَخَافُ لَدَىَّ ٱلْمُرْسَلُونَ', '36e9715447c4464ea09772c94297eefac85ae36ed2b7297613c545f83c0c0597', 'وَأَلْقِ عَصَاكَ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ يَٰمُوسَىٰ لَا تَخَفْ إِنِّى لَا يَخَافُ لَدَىَّ ٱلْمُرْسَلُونَ', '36e9715447c4464ea09772c94297eefac85ae36ed2b7297613c545f83c0c0597', '36e9715447c4464ea09772c94297eefac85ae36ed2b7297613c545f83c0c0597', NULL, 'والق عصاك فلما رءاها تهتز كانها جان ولي مدبرا ولم يعقب يموسي لا تخف اني لا يخاف لدي المرسلون', 19, 38, 151, 1, 5, 377, false, NULL),
    (3170, 'tanzil-uthmani-v1.1', 27, 11, 'إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسْنًۢا بَعْدَ سُوٓءٍ فَإِنِّى غَفُورٌ رَّحِيمٌ', '2f7eead5b0f32ad126decdc30832995b74049f5e00f0c88a3a494c35adcaaf31', 'إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسْنًۢا بَعْدَ سُوٓءٍ فَإِنِّى غَفُورٌ رَّحِيمٌ', '2f7eead5b0f32ad126decdc30832995b74049f5e00f0c88a3a494c35adcaaf31', '2f7eead5b0f32ad126decdc30832995b74049f5e00f0c88a3a494c35adcaaf31', NULL, 'الا من ظلم ثم بدل حسنا بعد سوء فاني غفور رحيم', 19, 38, 151, 1, 5, 377, false, NULL),
    (3171, 'tanzil-uthmani-v1.1', 27, 12, 'وَأَدْخِلْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ فِى تِسْعِ ءَايَٰتٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', '73c01792624d6f4ae7d19e57d215023b517559aecaf8f6b779f26930ac8727bf', 'وَأَدْخِلْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ فِى تِسْعِ ءَايَٰتٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', '73c01792624d6f4ae7d19e57d215023b517559aecaf8f6b779f26930ac8727bf', '73c01792624d6f4ae7d19e57d215023b517559aecaf8f6b779f26930ac8727bf', NULL, 'وادخل يدك في جيبك تخرج بيضاء من غير سوء في تسع ءايت الي فرعون وقومه انهم كانوا قوما فسقين', 19, 38, 151, 1, 5, 377, false, NULL),
    (3172, 'tanzil-uthmani-v1.1', 27, 13, 'فَلَمَّا جَآءَتْهُمْ ءَايَٰتُنَا مُبْصِرَةً قَالُوا۟ هَٰذَا سِحْرٌ مُّبِينٌ', 'ada377580035f735b2777ceed578955f6e3053889f7d6f85529e72290749167a', 'فَلَمَّا جَآءَتْهُمْ ءَايَٰتُنَا مُبْصِرَةً قَالُوا۟ هَٰذَا سِحْرٌ مُّبِينٌ', 'ada377580035f735b2777ceed578955f6e3053889f7d6f85529e72290749167a', 'ada377580035f735b2777ceed578955f6e3053889f7d6f85529e72290749167a', NULL, 'فلما جاءتهم ءايتنا مبصره قالوا هذا سحر مبين', 19, 38, 151, 1, 5, 377, false, NULL),
    (3173, 'tanzil-uthmani-v1.1', 27, 14, 'وَجَحَدُوا۟ بِهَا وَٱسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', '620bbde728ba3a82ec175f6dd3bb77fd880bd8d592441012c91319c301cb25b4', 'وَجَحَدُوا۟ بِهَا وَٱسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', '620bbde728ba3a82ec175f6dd3bb77fd880bd8d592441012c91319c301cb25b4', '620bbde728ba3a82ec175f6dd3bb77fd880bd8d592441012c91319c301cb25b4', NULL, 'وجحدوا بها واستيقنتها انفسهم ظلما وعلوا فانظر كيف كان عقبه المفسدين', 19, 38, 151, 1, 5, 378, false, NULL),
    (3174, 'tanzil-uthmani-v1.1', 27, 15, 'وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ وَسُلَيْمَٰنَ عِلْمًا وَقَالَا ٱلْحَمْدُ لِلَّهِ ٱلَّذِى فَضَّلَنَا عَلَىٰ كَثِيرٍ مِّنْ عِبَادِهِ ٱلْمُؤْمِنِينَ', 'c9e38eb8f474c59b0de6737240eef700a0869e5a73049b11de2831afb0c894bb', 'وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ وَسُلَيْمَٰنَ عِلْمًا وَقَالَا ٱلْحَمْدُ لِلَّهِ ٱلَّذِى فَضَّلَنَا عَلَىٰ كَثِيرٍ مِّنْ عِبَادِهِ ٱلْمُؤْمِنِينَ', 'c9e38eb8f474c59b0de6737240eef700a0869e5a73049b11de2831afb0c894bb', 'c9e38eb8f474c59b0de6737240eef700a0869e5a73049b11de2831afb0c894bb', NULL, 'ولقد ءاتينا داود وسليمن علما وقالا الحمد لله الذي فضلنا علي كثير من عباده المؤمنين', 19, 38, 151, 1, 5, 378, false, NULL),
    (3175, 'tanzil-uthmani-v1.1', 27, 16, 'وَوَرِثَ سُلَيْمَٰنُ دَاوُۥدَ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ إِنَّ هَٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ', 'c27b3ae97f19328ff91d9d7ef3d8a355fc1dab543e5cd187f6a4a9725ff5e03f', 'وَوَرِثَ سُلَيْمَٰنُ دَاوُۥدَ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ إِنَّ هَٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ', 'c27b3ae97f19328ff91d9d7ef3d8a355fc1dab543e5cd187f6a4a9725ff5e03f', 'c27b3ae97f19328ff91d9d7ef3d8a355fc1dab543e5cd187f6a4a9725ff5e03f', NULL, 'وورث سليمن داود وقال يايها الناس علمنا منطق الطير واوتينا من كل شيء ان هذا لهو الفضل المبين', 19, 38, 151, 1, 5, 378, false, NULL),
    (3176, 'tanzil-uthmani-v1.1', 27, 17, 'وَحُشِرَ لِسُلَيْمَٰنَ جُنُودُهُۥ مِنَ ٱلْجِنِّ وَٱلْإِنسِ وَٱلطَّيْرِ فَهُمْ يُوزَعُونَ', '5e2f4b5e1a04d1d7b1569c9d32cebf8136eef20804379c296f3196874e385880', 'وَحُشِرَ لِسُلَيْمَٰنَ جُنُودُهُۥ مِنَ ٱلْجِنِّ وَٱلْإِنسِ وَٱلطَّيْرِ فَهُمْ يُوزَعُونَ', '5e2f4b5e1a04d1d7b1569c9d32cebf8136eef20804379c296f3196874e385880', '5e2f4b5e1a04d1d7b1569c9d32cebf8136eef20804379c296f3196874e385880', NULL, 'وحشر لسليمن جنوده من الجن والانس والطير فهم يوزعون', 19, 38, 151, 1, 5, 378, false, NULL),
    (3177, 'tanzil-uthmani-v1.1', 27, 18, 'حَتَّىٰٓ إِذَآ أَتَوْا۟ عَلَىٰ وَادِ ٱلنَّمْلِ قَالَتْ نَمْلَةٌ يَٰٓأَيُّهَا ٱلنَّمْلُ ٱدْخُلُوا۟ مَسَٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ', '4f9278b716fdeb2f253b3e77134fb78ed48c1934918af4546e33a3c8000597bf', 'حَتَّىٰٓ إِذَآ أَتَوْا۟ عَلَىٰ وَادِ ٱلنَّمْلِ قَالَتْ نَمْلَةٌ يَٰٓأَيُّهَا ٱلنَّمْلُ ٱدْخُلُوا۟ مَسَٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ', '4f9278b716fdeb2f253b3e77134fb78ed48c1934918af4546e33a3c8000597bf', '4f9278b716fdeb2f253b3e77134fb78ed48c1934918af4546e33a3c8000597bf', NULL, 'حتي اذا اتوا علي واد النمل قالت نمله يايها النمل ادخلوا مسكنكم لا يحطمنكم سليمن وجنوده وهم لا يشعرون', 19, 38, 151, 1, 5, 378, false, NULL),
    (3178, 'tanzil-uthmani-v1.1', 27, 19, 'فَتَبَسَّمَ ضَاحِكًا مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ ٱلصَّٰلِحِينَ', '914d60a229cdb496ee3544fda127d75c89d00f2196a8c5d1d5223fbdbe981eaf', 'فَتَبَسَّمَ ضَاحِكًا مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ ٱلصَّٰلِحِينَ', '914d60a229cdb496ee3544fda127d75c89d00f2196a8c5d1d5223fbdbe981eaf', '914d60a229cdb496ee3544fda127d75c89d00f2196a8c5d1d5223fbdbe981eaf', NULL, 'فتبسم ضاحكا من قولها وقال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلي ولدي وان اعمل صلحا ترضيه وادخلني برحمتك في عبادك الصلحين', 19, 38, 151, 1, 5, 378, false, NULL),
    (3179, 'tanzil-uthmani-v1.1', 27, 20, 'وَتَفَقَّدَ ٱلطَّيْرَ فَقَالَ مَا لِىَ لَآ أَرَى ٱلْهُدْهُدَ أَمْ كَانَ مِنَ ٱلْغَآئِبِينَ', '64270e00baa2fc3da38737fb97b5d39e696df1485e4a0feeaa1b391fdd3547ce', 'وَتَفَقَّدَ ٱلطَّيْرَ فَقَالَ مَا لِىَ لَآ أَرَى ٱلْهُدْهُدَ أَمْ كَانَ مِنَ ٱلْغَآئِبِينَ', '64270e00baa2fc3da38737fb97b5d39e696df1485e4a0feeaa1b391fdd3547ce', '64270e00baa2fc3da38737fb97b5d39e696df1485e4a0feeaa1b391fdd3547ce', NULL, 'وتفقد الطير فقال ما لي لا اري الهدهد ام كان من الغائبين', 19, 38, 151, 1, 5, 378, false, NULL),
    (3180, 'tanzil-uthmani-v1.1', 27, 21, 'لَأُعَذِّبَنَّهُۥ عَذَابًا شَدِيدًا أَوْ لَأَا۟ذْبَحَنَّهُۥٓ أَوْ لَيَأْتِيَنِّى بِسُلْطَٰنٍ مُّبِينٍ', 'a17aa44c8d1666848b0504834c3ec82561ae4d561615d8134661cf0ded3b03a1', 'لَأُعَذِّبَنَّهُۥ عَذَابًا شَدِيدًا أَوْ لَأَا۟ذْبَحَنَّهُۥٓ أَوْ لَيَأْتِيَنِّى بِسُلْطَٰنٍ مُّبِينٍ', 'a17aa44c8d1666848b0504834c3ec82561ae4d561615d8134661cf0ded3b03a1', 'a17aa44c8d1666848b0504834c3ec82561ae4d561615d8134661cf0ded3b03a1', NULL, 'لاعذبنه عذابا شديدا او لااذبحنه او لياتيني بسلطن مبين', 19, 38, 151, 1, 5, 378, false, NULL),
    (3181, 'tanzil-uthmani-v1.1', 27, 22, 'فَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإٍۭ بِنَبَإٍ يَقِينٍ', '3be117d92c5b542fd0d2e7473fbe51ac68e5c4946862fdfd26519081112d854a', 'فَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإٍۭ بِنَبَإٍ يَقِينٍ', '3be117d92c5b542fd0d2e7473fbe51ac68e5c4946862fdfd26519081112d854a', '3be117d92c5b542fd0d2e7473fbe51ac68e5c4946862fdfd26519081112d854a', NULL, 'فمكث غير بعيد فقال احطت بما لم تحط به وجئتك من سبا بنبا يقين', 19, 38, 151, 1, 5, 378, false, NULL),
    (3182, 'tanzil-uthmani-v1.1', 27, 23, 'إِنِّى وَجَدتُّ ٱمْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَىْءٍ وَلَهَا عَرْشٌ عَظِيمٌ', '40f338f0f86833a88e56de633e8fb7d796d2e7ec3eb1e6bfb69cb8fec686e375', 'إِنِّى وَجَدتُّ ٱمْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَىْءٍ وَلَهَا عَرْشٌ عَظِيمٌ', '40f338f0f86833a88e56de633e8fb7d796d2e7ec3eb1e6bfb69cb8fec686e375', '40f338f0f86833a88e56de633e8fb7d796d2e7ec3eb1e6bfb69cb8fec686e375', NULL, 'اني وجدت امراه تملكهم واوتيت من كل شيء ولها عرش عظيم', 19, 38, 151, 1, 5, 379, false, NULL),
    (3183, 'tanzil-uthmani-v1.1', 27, 24, 'وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ فَهُمْ لَا يَهْتَدُونَ', '966b268f694f55b1eac38ec15a756a90d7e4c19cbe2e58acfff3d603d4142bca', 'وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ فَهُمْ لَا يَهْتَدُونَ', '966b268f694f55b1eac38ec15a756a90d7e4c19cbe2e58acfff3d603d4142bca', '966b268f694f55b1eac38ec15a756a90d7e4c19cbe2e58acfff3d603d4142bca', NULL, 'وجدتها وقومها يسجدون للشمس من دون الله وزين لهم الشيطن اعملهم فصدهم عن السبيل فهم لا يهتدون', 19, 38, 151, 1, 5, 379, false, NULL),
    (3184, 'tanzil-uthmani-v1.1', 27, 25, 'أَلَّا يَسْجُدُوا۟ لِلَّهِ ٱلَّذِى يُخْرِجُ ٱلْخَبْءَ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ', 'eec1f27a70fa88d80009e7e1717dde971327c49c4d1d6a82a477a52560c0ac99', 'أَلَّا يَسْجُدُوا۟ لِلَّهِ ٱلَّذِى يُخْرِجُ ٱلْخَبْءَ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ', 'eec1f27a70fa88d80009e7e1717dde971327c49c4d1d6a82a477a52560c0ac99', 'eec1f27a70fa88d80009e7e1717dde971327c49c4d1d6a82a477a52560c0ac99', NULL, 'الا يسجدوا لله الذي يخرج الخبء في السموت والارض ويعلم ما تخفون وما تعلنون', 19, 38, 151, 1, 5, 379, false, NULL),
    (3185, 'tanzil-uthmani-v1.1', 27, 26, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'ee4f4b12370a742af578beeeaaf4a9b72eabe614ff19e020d28b6bf4fb0a1925', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 'ee4f4b12370a742af578beeeaaf4a9b72eabe614ff19e020d28b6bf4fb0a1925', 'ee4f4b12370a742af578beeeaaf4a9b72eabe614ff19e020d28b6bf4fb0a1925', NULL, 'الله لا اله الا هو رب العرش العظيم', 19, 38, 151, 1, 5, 379, true, 'recommended'),
    (3186, 'tanzil-uthmani-v1.1', 27, 27, 'قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ ٱلْكَٰذِبِينَ', 'b77c44b97020ca0782bccc3c8246e0b80ff439bb6260fd08607274680e96473e', 'قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ ٱلْكَٰذِبِينَ', 'b77c44b97020ca0782bccc3c8246e0b80ff439bb6260fd08607274680e96473e', 'b77c44b97020ca0782bccc3c8246e0b80ff439bb6260fd08607274680e96473e', NULL, 'قال سننظر اصدقت ام كنت من الكذبين', 19, 38, 152, 1, 5, 379, false, NULL),
    (3187, 'tanzil-uthmani-v1.1', 27, 28, 'ٱذْهَب بِّكِتَٰبِى هَٰذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَٱنظُرْ مَاذَا يَرْجِعُونَ', '2174cd3f78b4f940f24b3719df5c13ed59cc624070784e181e271ad6d3bc7bb9', 'ٱذْهَب بِّكِتَٰبِى هَٰذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَٱنظُرْ مَاذَا يَرْجِعُونَ', '2174cd3f78b4f940f24b3719df5c13ed59cc624070784e181e271ad6d3bc7bb9', '2174cd3f78b4f940f24b3719df5c13ed59cc624070784e181e271ad6d3bc7bb9', NULL, 'اذهب بكتبي هذا فالقه اليهم ثم تول عنهم فانظر ماذا يرجعون', 19, 38, 152, 1, 5, 379, false, NULL),
    (3188, 'tanzil-uthmani-v1.1', 27, 29, 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ إِنِّىٓ أُلْقِىَ إِلَىَّ كِتَٰبٌ كَرِيمٌ', '33aaf1d00bbb7d030c5670e0bd07b1fad8f151fa5283551fc3feb48bb3130b10', 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ إِنِّىٓ أُلْقِىَ إِلَىَّ كِتَٰبٌ كَرِيمٌ', '33aaf1d00bbb7d030c5670e0bd07b1fad8f151fa5283551fc3feb48bb3130b10', '33aaf1d00bbb7d030c5670e0bd07b1fad8f151fa5283551fc3feb48bb3130b10', NULL, 'قالت يايها الملؤا اني القي الي كتب كريم', 19, 38, 152, 1, 5, 379, false, NULL),
    (3189, 'tanzil-uthmani-v1.1', 27, 30, 'إِنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', '4cea5fd585054cbcc6914c55f0e66ba42d74b38160e2ac5d72b470e3e31f325c', 'إِنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', '4cea5fd585054cbcc6914c55f0e66ba42d74b38160e2ac5d72b470e3e31f325c', '4cea5fd585054cbcc6914c55f0e66ba42d74b38160e2ac5d72b470e3e31f325c', NULL, 'انه من سليمن وانه بسم الله الرحمن الرحيم', 19, 38, 152, 1, 5, 379, false, NULL),
    (3190, 'tanzil-uthmani-v1.1', 27, 31, 'أَلَّا تَعْلُوا۟ عَلَىَّ وَأْتُونِى مُسْلِمِينَ', '2c82fdbaddbda3328b33b87b18d93330ec32d397b69c419c1472f85e92ae6959', 'أَلَّا تَعْلُوا۟ عَلَىَّ وَأْتُونِى مُسْلِمِينَ', '2c82fdbaddbda3328b33b87b18d93330ec32d397b69c419c1472f85e92ae6959', '2c82fdbaddbda3328b33b87b18d93330ec32d397b69c419c1472f85e92ae6959', NULL, 'الا تعلوا علي واتوني مسلمين', 19, 38, 152, 1, 5, 379, false, NULL),
    (3191, 'tanzil-uthmani-v1.1', 27, 32, 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَفْتُونِى فِىٓ أَمْرِى مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ', '5deaf93e56b155ce57f9d1f8faf5e3418018cd697cc0b6406e38dd098699658a', 'قَالَتْ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَفْتُونِى فِىٓ أَمْرِى مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ', '5deaf93e56b155ce57f9d1f8faf5e3418018cd697cc0b6406e38dd098699658a', '5deaf93e56b155ce57f9d1f8faf5e3418018cd697cc0b6406e38dd098699658a', NULL, 'قالت يايها الملؤا افتوني في امري ما كنت قاطعه امرا حتي تشهدون', 19, 38, 152, 1, 5, 379, false, NULL),
    (3192, 'tanzil-uthmani-v1.1', 27, 33, 'قَالُوا۟ نَحْنُ أُو۟لُوا۟ قُوَّةٍ وَأُو۟لُوا۟ بَأْسٍ شَدِيدٍ وَٱلْأَمْرُ إِلَيْكِ فَٱنظُرِى مَاذَا تَأْمُرِينَ', 'dfa0d5d8e487bc8226ab6b93bfe5719045cbc9fe2e192897f950975eb49313f3', 'قَالُوا۟ نَحْنُ أُو۟لُوا۟ قُوَّةٍ وَأُو۟لُوا۟ بَأْسٍ شَدِيدٍ وَٱلْأَمْرُ إِلَيْكِ فَٱنظُرِى مَاذَا تَأْمُرِينَ', 'dfa0d5d8e487bc8226ab6b93bfe5719045cbc9fe2e192897f950975eb49313f3', 'dfa0d5d8e487bc8226ab6b93bfe5719045cbc9fe2e192897f950975eb49313f3', NULL, 'قالوا نحن اولوا قوه واولوا باس شديد والامر اليك فانظري ماذا تامرين', 19, 38, 152, 1, 5, 379, false, NULL),
    (3193, 'tanzil-uthmani-v1.1', 27, 34, 'قَالَتْ إِنَّ ٱلْمُلُوكَ إِذَا دَخَلُوا۟ قَرْيَةً أَفْسَدُوهَا وَجَعَلُوٓا۟ أَعِزَّةَ أَهْلِهَآ أَذِلَّةً وَكَذَٰلِكَ يَفْعَلُونَ', '7b8f471f7173751a297575b0f1ce16d56d022216a169ee0c05c524848c887964', 'قَالَتْ إِنَّ ٱلْمُلُوكَ إِذَا دَخَلُوا۟ قَرْيَةً أَفْسَدُوهَا وَجَعَلُوٓا۟ أَعِزَّةَ أَهْلِهَآ أَذِلَّةً وَكَذَٰلِكَ يَفْعَلُونَ', '7b8f471f7173751a297575b0f1ce16d56d022216a169ee0c05c524848c887964', '7b8f471f7173751a297575b0f1ce16d56d022216a169ee0c05c524848c887964', NULL, 'قالت ان الملوك اذا دخلوا قريه افسدوها وجعلوا اعزه اهلها اذله وكذلك يفعلون', 19, 38, 152, 1, 5, 379, false, NULL),
    (3194, 'tanzil-uthmani-v1.1', 27, 35, 'وَإِنِّى مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍ فَنَاظِرَةٌۢ بِمَ يَرْجِعُ ٱلْمُرْسَلُونَ', 'a72cec6bfc2a49c3ac795d8fef7f21ddb8dfc5fb8ea16ca9e1aff8f6d7b3fe6c', 'وَإِنِّى مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍ فَنَاظِرَةٌۢ بِمَ يَرْجِعُ ٱلْمُرْسَلُونَ', 'a72cec6bfc2a49c3ac795d8fef7f21ddb8dfc5fb8ea16ca9e1aff8f6d7b3fe6c', 'a72cec6bfc2a49c3ac795d8fef7f21ddb8dfc5fb8ea16ca9e1aff8f6d7b3fe6c', NULL, 'واني مرسله اليهم بهديه فناظره بم يرجع المرسلون', 19, 38, 152, 1, 5, 379, false, NULL),
    (3195, 'tanzil-uthmani-v1.1', 27, 36, 'فَلَمَّا جَآءَ سُلَيْمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيْرٌ مِّمَّآ ءَاتَىٰكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ', '827a376477916921b9f4330baea54e50d0c03b40d3ae615587155673f951633e', 'فَلَمَّا جَآءَ سُلَيْمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيْرٌ مِّمَّآ ءَاتَىٰكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ', '827a376477916921b9f4330baea54e50d0c03b40d3ae615587155673f951633e', '827a376477916921b9f4330baea54e50d0c03b40d3ae615587155673f951633e', NULL, 'فلما جاء سليمن قال اتمدونن بمال فما ءاتين الله خير مما ءاتيكم بل انتم بهديتكم تفرحون', 19, 38, 152, 1, 5, 380, false, NULL),
    (3196, 'tanzil-uthmani-v1.1', 27, 37, 'ٱرْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَآ أَذِلَّةً وَهُمْ صَٰغِرُونَ', '971bb90ddaf05732c8c0660e78cd13cfada9400ac029d5aa8b6b5a5f9a38ac76', 'ٱرْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَآ أَذِلَّةً وَهُمْ صَٰغِرُونَ', '971bb90ddaf05732c8c0660e78cd13cfada9400ac029d5aa8b6b5a5f9a38ac76', '971bb90ddaf05732c8c0660e78cd13cfada9400ac029d5aa8b6b5a5f9a38ac76', NULL, 'ارجع اليهم فلناتينهم بجنود لا قبل لهم بها ولنخرجنهم منها اذله وهم صغرون', 19, 38, 152, 1, 5, 380, false, NULL),
    (3197, 'tanzil-uthmani-v1.1', 27, 38, 'قَالَ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَيُّكُمْ يَأْتِينِى بِعَرْشِهَا قَبْلَ أَن يَأْتُونِى مُسْلِمِينَ', '4129dce0feb197b7402a5c80db4539ae49821c3bedf44b73af22eaaa89be065d', 'قَالَ يَٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَيُّكُمْ يَأْتِينِى بِعَرْشِهَا قَبْلَ أَن يَأْتُونِى مُسْلِمِينَ', '4129dce0feb197b7402a5c80db4539ae49821c3bedf44b73af22eaaa89be065d', '4129dce0feb197b7402a5c80db4539ae49821c3bedf44b73af22eaaa89be065d', NULL, 'قال يايها الملؤا ايكم ياتيني بعرشها قبل ان ياتوني مسلمين', 19, 38, 152, 1, 5, 380, false, NULL),
    (3198, 'tanzil-uthmani-v1.1', 27, 39, 'قَالَ عِفْرِيتٌ مِّنَ ٱلْجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ وَإِنِّى عَلَيْهِ لَقَوِىٌّ أَمِينٌ', '7dc828c715324efa3dab2e2446946aed8a171b1c325b181cdcbc58de52c08934', 'قَالَ عِفْرِيتٌ مِّنَ ٱلْجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ وَإِنِّى عَلَيْهِ لَقَوِىٌّ أَمِينٌ', '7dc828c715324efa3dab2e2446946aed8a171b1c325b181cdcbc58de52c08934', '7dc828c715324efa3dab2e2446946aed8a171b1c325b181cdcbc58de52c08934', NULL, 'قال عفريت من الجن انا ءاتيك به قبل ان تقوم من مقامك واني عليه لقوي امين', 19, 38, 152, 1, 5, 380, false, NULL),
    (3199, 'tanzil-uthmani-v1.1', 27, 40, 'قَالَ ٱلَّذِى عِندَهُۥ عِلْمٌ مِّنَ ٱلْكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ فَلَمَّا رَءَاهُ مُسْتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضْلِ رَبِّى لِيَبْلُوَنِىٓ ءَأَشْكُرُ أَمْ أَكْفُرُ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ وَمَن كَفَرَ فَإِنَّ رَبِّى غَنِىٌّ كَرِيمٌ', 'a2e1d5f844f6b4b847a413648e735478df767ee4abf3563409fff578c19ac616', 'قَالَ ٱلَّذِى عِندَهُۥ عِلْمٌ مِّنَ ٱلْكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ فَلَمَّا رَءَاهُ مُسْتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضْلِ رَبِّى لِيَبْلُوَنِىٓ ءَأَشْكُرُ أَمْ أَكْفُرُ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ وَمَن كَفَرَ فَإِنَّ رَبِّى غَنِىٌّ كَرِيمٌ', 'a2e1d5f844f6b4b847a413648e735478df767ee4abf3563409fff578c19ac616', 'a2e1d5f844f6b4b847a413648e735478df767ee4abf3563409fff578c19ac616', NULL, 'قال الذي عنده علم من الكتب انا ءاتيك به قبل ان يرتد اليك طرفك فلما رءاه مستقرا عنده قال هذا من فضل ربي ليبلوني ءاشكر ام اكفر ومن شكر فانما يشكر لنفسه ومن كفر فان ربي غني كريم', 19, 38, 152, 1, 5, 380, false, NULL),
    (3200, 'tanzil-uthmani-v1.1', 27, 41, 'قَالَ نَكِّرُوا۟ لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِىٓ أَمْ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهْتَدُونَ', '56fe0344e31bc396fed0cedad68cc1260e2664bdcfadc5180df0a4ab35047d7b', 'قَالَ نَكِّرُوا۟ لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِىٓ أَمْ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهْتَدُونَ', '56fe0344e31bc396fed0cedad68cc1260e2664bdcfadc5180df0a4ab35047d7b', '56fe0344e31bc396fed0cedad68cc1260e2664bdcfadc5180df0a4ab35047d7b', NULL, 'قال نكروا لها عرشها ننظر اتهتدي ام تكون من الذين لا يهتدون', 19, 38, 152, 1, 5, 380, false, NULL),
    (3201, 'tanzil-uthmani-v1.1', 27, 42, 'فَلَمَّا جَآءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ قَالَتْ كَأَنَّهُۥ هُوَ وَأُوتِينَا ٱلْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ', '7978a8d50cc19dd0b5de1bd7aad1cfd58339c19fd7d8469ce2730d9cf66e7099', 'فَلَمَّا جَآءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ قَالَتْ كَأَنَّهُۥ هُوَ وَأُوتِينَا ٱلْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ', '7978a8d50cc19dd0b5de1bd7aad1cfd58339c19fd7d8469ce2730d9cf66e7099', '7978a8d50cc19dd0b5de1bd7aad1cfd58339c19fd7d8469ce2730d9cf66e7099', NULL, 'فلما جاءت قيل اهكذا عرشك قالت كانه هو واوتينا العلم من قبلها وكنا مسلمين', 19, 38, 152, 1, 5, 380, false, NULL),
    (3202, 'tanzil-uthmani-v1.1', 27, 43, 'وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ ٱللَّهِ إِنَّهَا كَانَتْ مِن قَوْمٍ كَٰفِرِينَ', '11b5e75c229dc3d2b70e3f9ab03edc6f476c1a96c08f98f7022c35d3dff796d9', 'وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ ٱللَّهِ إِنَّهَا كَانَتْ مِن قَوْمٍ كَٰفِرِينَ', '11b5e75c229dc3d2b70e3f9ab03edc6f476c1a96c08f98f7022c35d3dff796d9', '11b5e75c229dc3d2b70e3f9ab03edc6f476c1a96c08f98f7022c35d3dff796d9', NULL, 'وصدها ما كانت تعبد من دون الله انها كانت من قوم كفرين', 19, 38, 152, 1, 5, 380, false, NULL),
    (3203, 'tanzil-uthmani-v1.1', 27, 44, 'قِيلَ لَهَا ٱدْخُلِى ٱلصَّرْحَ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَن سَاقَيْهَا قَالَ إِنَّهُۥ صَرْحٌ مُّمَرَّدٌ مِّن قَوَارِيرَ قَالَتْ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى وَأَسْلَمْتُ مَعَ سُلَيْمَٰنَ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'bb0b8cdfd6eea23fb9c49aa3dbdf1cf5b1f6d773bca94bdc879cd0138333d50f', 'قِيلَ لَهَا ٱدْخُلِى ٱلصَّرْحَ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَن سَاقَيْهَا قَالَ إِنَّهُۥ صَرْحٌ مُّمَرَّدٌ مِّن قَوَارِيرَ قَالَتْ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى وَأَسْلَمْتُ مَعَ سُلَيْمَٰنَ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'bb0b8cdfd6eea23fb9c49aa3dbdf1cf5b1f6d773bca94bdc879cd0138333d50f', 'bb0b8cdfd6eea23fb9c49aa3dbdf1cf5b1f6d773bca94bdc879cd0138333d50f', NULL, 'قيل لها ادخلي الصرح فلما راته حسبته لجه وكشفت عن ساقيها قال انه صرح ممرد من قوارير قالت رب اني ظلمت نفسي واسلمت مع سليمن لله رب العلمين', 19, 38, 152, 1, 5, 380, false, NULL),
    (3204, 'tanzil-uthmani-v1.1', 27, 45, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ', '43088e7ce2172bf56588c7328a2636d70f6759d4924ddddc09346a5ab508d5d7', 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ', '43088e7ce2172bf56588c7328a2636d70f6759d4924ddddc09346a5ab508d5d7', '43088e7ce2172bf56588c7328a2636d70f6759d4924ddddc09346a5ab508d5d7', NULL, 'ولقد ارسلنا الي ثمود اخاهم صلحا ان اعبدوا الله فاذا هم فريقان يختصمون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3205, 'tanzil-uthmani-v1.1', 27, 46, 'قَالَ يَٰقَوْمِ لِمَ تَسْتَعْجِلُونَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ لَوْلَا تَسْتَغْفِرُونَ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', '14c56acfea102b4882bc2ca2d223e8dd91b5a97872f680fafd32f00ea51bcb90', 'قَالَ يَٰقَوْمِ لِمَ تَسْتَعْجِلُونَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ لَوْلَا تَسْتَغْفِرُونَ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', '14c56acfea102b4882bc2ca2d223e8dd91b5a97872f680fafd32f00ea51bcb90', '14c56acfea102b4882bc2ca2d223e8dd91b5a97872f680fafd32f00ea51bcb90', NULL, 'قال يقوم لم تستعجلون بالسيئه قبل الحسنه لولا تستغفرون الله لعلكم ترحمون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3206, 'tanzil-uthmani-v1.1', 27, 47, 'قَالُوا۟ ٱطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ قَالَ طَٰٓئِرُكُمْ عِندَ ٱللَّهِ بَلْ أَنتُمْ قَوْمٌ تُفْتَنُونَ', 'db9f1f3fa81795dffa9ceb638d96b4938d1065c569fea818aa2463c365e421e6', 'قَالُوا۟ ٱطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ قَالَ طَٰٓئِرُكُمْ عِندَ ٱللَّهِ بَلْ أَنتُمْ قَوْمٌ تُفْتَنُونَ', 'db9f1f3fa81795dffa9ceb638d96b4938d1065c569fea818aa2463c365e421e6', 'db9f1f3fa81795dffa9ceb638d96b4938d1065c569fea818aa2463c365e421e6', NULL, 'قالوا اطيرنا بك وبمن معك قال طئركم عند الله بل انتم قوم تفتنون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3207, 'tanzil-uthmani-v1.1', 27, 48, 'وَكَانَ فِى ٱلْمَدِينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ', '524c53de2b2a97546e6ccd3e0c78430f290e5eb5343407d605ef178d33e45464', 'وَكَانَ فِى ٱلْمَدِينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ', '524c53de2b2a97546e6ccd3e0c78430f290e5eb5343407d605ef178d33e45464', '524c53de2b2a97546e6ccd3e0c78430f290e5eb5343407d605ef178d33e45464', NULL, 'وكان في المدينه تسعه رهط يفسدون في الارض ولا يصلحون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3208, 'tanzil-uthmani-v1.1', 27, 49, 'قَالُوا۟ تَقَاسَمُوا۟ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهْلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِۦ وَإِنَّا لَصَٰدِقُونَ', '86a30eae08760fcfcc8c6949e8522e094ce484273048af8e3e2e009d6a3f5889', 'قَالُوا۟ تَقَاسَمُوا۟ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهْلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِۦ وَإِنَّا لَصَٰدِقُونَ', '86a30eae08760fcfcc8c6949e8522e094ce484273048af8e3e2e009d6a3f5889', '86a30eae08760fcfcc8c6949e8522e094ce484273048af8e3e2e009d6a3f5889', NULL, 'قالوا تقاسموا بالله لنبيتنه واهله ثم لنقولن لوليه ما شهدنا مهلك اهله وانا لصدقون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3209, 'tanzil-uthmani-v1.1', 27, 50, 'وَمَكَرُوا۟ مَكْرًا وَمَكَرْنَا مَكْرًا وَهُمْ لَا يَشْعُرُونَ', 'c9574f6b3b10fb9558b9d0d102b2d6c3372446750289faa15b833e7ebdc10a8d', 'وَمَكَرُوا۟ مَكْرًا وَمَكَرْنَا مَكْرًا وَهُمْ لَا يَشْعُرُونَ', 'c9574f6b3b10fb9558b9d0d102b2d6c3372446750289faa15b833e7ebdc10a8d', 'c9574f6b3b10fb9558b9d0d102b2d6c3372446750289faa15b833e7ebdc10a8d', NULL, 'ومكروا مكرا ومكرنا مكرا وهم لا يشعرون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3210, 'tanzil-uthmani-v1.1', 27, 51, 'فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَٰهُمْ وَقَوْمَهُمْ أَجْمَعِينَ', '8e2c50d04841452635b22cdd9295bcc0efc760511a7f9ad4c1188758092412a6', 'فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَٰهُمْ وَقَوْمَهُمْ أَجْمَعِينَ', '8e2c50d04841452635b22cdd9295bcc0efc760511a7f9ad4c1188758092412a6', '8e2c50d04841452635b22cdd9295bcc0efc760511a7f9ad4c1188758092412a6', NULL, 'فانظر كيف كان عقبه مكرهم انا دمرنهم وقومهم اجمعين', 19, 38, 152, 1, 5, 381, false, NULL),
    (3211, 'tanzil-uthmani-v1.1', 27, 52, 'فَتِلْكَ بُيُوتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوٓا۟ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْلَمُونَ', 'f953d55d14633f62539194cf849a46053971e79c4e6d5b7d04b4765262c4e6f2', 'فَتِلْكَ بُيُوتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوٓا۟ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْلَمُونَ', 'f953d55d14633f62539194cf849a46053971e79c4e6d5b7d04b4765262c4e6f2', 'f953d55d14633f62539194cf849a46053971e79c4e6d5b7d04b4765262c4e6f2', NULL, 'فتلك بيوتهم خاويه بما ظلموا ان في ذلك لايه لقوم يعلمون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3212, 'tanzil-uthmani-v1.1', 27, 53, 'وَأَنجَيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '15b2964a6c80564e6de6af501f041e97f97d169746958edcf603ca46dcfbd295', 'وَأَنجَيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '15b2964a6c80564e6de6af501f041e97f97d169746958edcf603ca46dcfbd295', '15b2964a6c80564e6de6af501f041e97f97d169746958edcf603ca46dcfbd295', NULL, 'وانجينا الذين ءامنوا وكانوا يتقون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3213, 'tanzil-uthmani-v1.1', 27, 54, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ وَأَنتُمْ تُبْصِرُونَ', 'c2fef7937963b5c3c5d07671024a318f0443a2ef698c0a1f641b8ac7f6292944', 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ وَأَنتُمْ تُبْصِرُونَ', 'c2fef7937963b5c3c5d07671024a318f0443a2ef698c0a1f641b8ac7f6292944', 'c2fef7937963b5c3c5d07671024a318f0443a2ef698c0a1f641b8ac7f6292944', NULL, 'ولوطا اذ قال لقومه اتاتون الفحشه وانتم تبصرون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3214, 'tanzil-uthmani-v1.1', 27, 55, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ بَلْ أَنتُمْ قَوْمٌ تَجْهَلُونَ', 'ce2af96d97a51801e6dd80f051494d02099d89a6e11bdb91a31d713f467b280b', 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ بَلْ أَنتُمْ قَوْمٌ تَجْهَلُونَ', 'ce2af96d97a51801e6dd80f051494d02099d89a6e11bdb91a31d713f467b280b', 'ce2af96d97a51801e6dd80f051494d02099d89a6e11bdb91a31d713f467b280b', NULL, 'ائنكم لتاتون الرجال شهوه من دون النساء بل انتم قوم تجهلون', 19, 38, 152, 1, 5, 381, false, NULL),
    (3215, 'tanzil-uthmani-v1.1', 27, 56, 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوٓا۟ ءَالَ لُوطٍ مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', '1a803813d27cbd6fbd5fc6bbbd7b0fb8d256685971d921e27ababb0b2995d7a9', 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوٓا۟ ءَالَ لُوطٍ مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ', '1a803813d27cbd6fbd5fc6bbbd7b0fb8d256685971d921e27ababb0b2995d7a9', '1a803813d27cbd6fbd5fc6bbbd7b0fb8d256685971d921e27ababb0b2995d7a9', NULL, 'فما كان جواب قومه الا ان قالوا اخرجوا ءال لوط من قريتكم انهم اناس يتطهرون', 20, 39, 153, 1, 5, 382, false, NULL),
    (3216, 'tanzil-uthmani-v1.1', 27, 57, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَٰهَا مِنَ ٱلْغَٰبِرِينَ', '237ddee4164ada3789c6a98db3ba30a79c1e154c56f35f29359a13b3e1bccdc8', 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَٰهَا مِنَ ٱلْغَٰبِرِينَ', '237ddee4164ada3789c6a98db3ba30a79c1e154c56f35f29359a13b3e1bccdc8', '237ddee4164ada3789c6a98db3ba30a79c1e154c56f35f29359a13b3e1bccdc8', NULL, 'فانجينه واهله الا امراته قدرنها من الغبرين', 20, 39, 153, 1, 5, 382, false, NULL),
    (3217, 'tanzil-uthmani-v1.1', 27, 58, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ', 'b740263ec4f4fb39951923b1eaf72abee5ec2a84660b1806ec08bc37904512d1', 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ', 'b740263ec4f4fb39951923b1eaf72abee5ec2a84660b1806ec08bc37904512d1', 'b740263ec4f4fb39951923b1eaf72abee5ec2a84660b1806ec08bc37904512d1', NULL, 'وامطرنا عليهم مطرا فساء مطر المنذرين', 20, 39, 153, 1, 5, 382, false, NULL),
    (3218, 'tanzil-uthmani-v1.1', 27, 59, 'قُلِ ٱلْحَمْدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصْطَفَىٰٓ ءَآللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ', 'a1dc28af68ec7179a4a108385ed0b5e1ee479608a9a91965d715f7dc03586588', 'قُلِ ٱلْحَمْدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصْطَفَىٰٓ ءَآللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ', 'a1dc28af68ec7179a4a108385ed0b5e1ee479608a9a91965d715f7dc03586588', 'a1dc28af68ec7179a4a108385ed0b5e1ee479608a9a91965d715f7dc03586588', NULL, 'قل الحمد لله وسلم علي عباده الذين اصطفي ءالله خير اما يشركون', 20, 39, 153, 1, 5, 382, false, NULL),
    (3219, 'tanzil-uthmani-v1.1', 27, 60, 'أَمَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهْجَةٍ مَّا كَانَ لَكُمْ أَن تُنۢبِتُوا۟ شَجَرَهَآ أَءِلَٰهٌ مَّعَ ٱللَّهِ بَلْ هُمْ قَوْمٌ يَعْدِلُونَ', '5ba80924ddcc95201ed07c23a66f6ebe43e30c4f6dfe2e30cbd491a728831c6f', 'أَمَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهْجَةٍ مَّا كَانَ لَكُمْ أَن تُنۢبِتُوا۟ شَجَرَهَآ أَءِلَٰهٌ مَّعَ ٱللَّهِ بَلْ هُمْ قَوْمٌ يَعْدِلُونَ', '5ba80924ddcc95201ed07c23a66f6ebe43e30c4f6dfe2e30cbd491a728831c6f', '5ba80924ddcc95201ed07c23a66f6ebe43e30c4f6dfe2e30cbd491a728831c6f', NULL, 'امن خلق السموت والارض وانزل لكم من السماء ماء فانبتنا به حدائق ذات بهجه ما كان لكم ان تنبتوا شجرها اءله مع الله بل هم قوم يعدلون', 20, 39, 153, 1, 5, 382, false, NULL),
    (3220, 'tanzil-uthmani-v1.1', 27, 61, 'أَمَّن جَعَلَ ٱلْأَرْضَ قَرَارًا وَجَعَلَ خِلَٰلَهَآ أَنْهَٰرًا وَجَعَلَ لَهَا رَوَٰسِىَ وَجَعَلَ بَيْنَ ٱلْبَحْرَيْنِ حَاجِزًا أَءِلَٰهٌ مَّعَ ٱللَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '6303be5158a14a5096b87153f4822e2512ac47dde9d5af3640d3c95979326a9c', 'أَمَّن جَعَلَ ٱلْأَرْضَ قَرَارًا وَجَعَلَ خِلَٰلَهَآ أَنْهَٰرًا وَجَعَلَ لَهَا رَوَٰسِىَ وَجَعَلَ بَيْنَ ٱلْبَحْرَيْنِ حَاجِزًا أَءِلَٰهٌ مَّعَ ٱللَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '6303be5158a14a5096b87153f4822e2512ac47dde9d5af3640d3c95979326a9c', '6303be5158a14a5096b87153f4822e2512ac47dde9d5af3640d3c95979326a9c', NULL, 'امن جعل الارض قرارا وجعل خللها انهرا وجعل لها روسي وجعل بين البحرين حاجزا اءله مع الله بل اكثرهم لا يعلمون', 20, 39, 153, 1, 5, 382, false, NULL),
    (3221, 'tanzil-uthmani-v1.1', 27, 62, 'أَمَّن يُجِيبُ ٱلْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ ٱلسُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ ٱلْأَرْضِ أَءِلَٰهٌ مَّعَ ٱللَّهِ قَلِيلًا مَّا تَذَكَّرُونَ', '63278fad8b4dabfb607adc9c6a794f1077265f536b74fe39383e8906ad3b5a46', 'أَمَّن يُجِيبُ ٱلْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ ٱلسُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ ٱلْأَرْضِ أَءِلَٰهٌ مَّعَ ٱللَّهِ قَلِيلًا مَّا تَذَكَّرُونَ', '63278fad8b4dabfb607adc9c6a794f1077265f536b74fe39383e8906ad3b5a46', '63278fad8b4dabfb607adc9c6a794f1077265f536b74fe39383e8906ad3b5a46', NULL, 'امن يجيب المضطر اذا دعاه ويكشف السوء ويجعلكم خلفاء الارض اءله مع الله قليلا ما تذكرون', 20, 39, 153, 1, 5, 382, false, NULL),
    (3222, 'tanzil-uthmani-v1.1', 27, 63, 'أَمَّن يَهْدِيكُمْ فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ وَمَن يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦٓ أَءِلَٰهٌ مَّعَ ٱللَّهِ تَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', 'c63c28fded8b9688262240954cb4d0807808e26288f6ef9aa90e8eb7c42cd01b', 'أَمَّن يَهْدِيكُمْ فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ وَمَن يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦٓ أَءِلَٰهٌ مَّعَ ٱللَّهِ تَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', 'c63c28fded8b9688262240954cb4d0807808e26288f6ef9aa90e8eb7c42cd01b', 'c63c28fded8b9688262240954cb4d0807808e26288f6ef9aa90e8eb7c42cd01b', NULL, 'امن يهديكم في ظلمت البر والبحر ومن يرسل الريح بشرا بين يدي رحمته اءله مع الله تعلي الله عما يشركون', 20, 39, 153, 1, 5, 382, false, NULL),
    (3223, 'tanzil-uthmani-v1.1', 27, 64, 'أَمَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَءِلَٰهٌ مَّعَ ٱللَّهِ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'bc6e68fdd1c32810116526b1e67a47084a4c48b83debec2498b7a9e650606b63', 'أَمَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَءِلَٰهٌ مَّعَ ٱللَّهِ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 'bc6e68fdd1c32810116526b1e67a47084a4c48b83debec2498b7a9e650606b63', 'bc6e68fdd1c32810116526b1e67a47084a4c48b83debec2498b7a9e650606b63', NULL, 'امن يبدؤا الخلق ثم يعيده ومن يرزقكم من السماء والارض اءله مع الله قل هاتوا برهنكم ان كنتم صدقين', 20, 39, 153, 1, 5, 383, false, NULL),
    (3224, 'tanzil-uthmani-v1.1', 27, 65, 'قُل لَّا يَعْلَمُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلْغَيْبَ إِلَّا ٱللَّهُ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'fc7e880b2ab64ac820b6a60ab32cdc80e183ab27db3d1c4aecf4ff29418d5d88', 'قُل لَّا يَعْلَمُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلْغَيْبَ إِلَّا ٱللَّهُ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 'fc7e880b2ab64ac820b6a60ab32cdc80e183ab27db3d1c4aecf4ff29418d5d88', 'fc7e880b2ab64ac820b6a60ab32cdc80e183ab27db3d1c4aecf4ff29418d5d88', NULL, 'قل لا يعلم من في السموت والارض الغيب الا الله وما يشعرون ايان يبعثون', 20, 39, 153, 1, 5, 383, false, NULL),
    (3225, 'tanzil-uthmani-v1.1', 27, 66, 'بَلِ ٱدَّٰرَكَ عِلْمُهُمْ فِى ٱلْـَٔاخِرَةِ بَلْ هُمْ فِى شَكٍّ مِّنْهَا بَلْ هُم مِّنْهَا عَمُونَ', '5528e14e9f9e1344999d2cbc9bdd787d6d3fde2464f941f4944967ae3820a4dc', 'بَلِ ٱدَّٰرَكَ عِلْمُهُمْ فِى ٱلْـَٔاخِرَةِ بَلْ هُمْ فِى شَكٍّ مِّنْهَا بَلْ هُم مِّنْهَا عَمُونَ', '5528e14e9f9e1344999d2cbc9bdd787d6d3fde2464f941f4944967ae3820a4dc', '5528e14e9f9e1344999d2cbc9bdd787d6d3fde2464f941f4944967ae3820a4dc', NULL, 'بل ادرك علمهم في الاخره بل هم في شك منها بل هم منها عمون', 20, 39, 153, 1, 5, 383, false, NULL),
    (3226, 'tanzil-uthmani-v1.1', 27, 67, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ أَءِذَا كُنَّا تُرَٰبًا وَءَابَآؤُنَآ أَئِنَّا لَمُخْرَجُونَ', '991d17c184420e1e26c16b59f3cf9d0d3000cc37c54f8731ddf05959453af24c', 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ أَءِذَا كُنَّا تُرَٰبًا وَءَابَآؤُنَآ أَئِنَّا لَمُخْرَجُونَ', '991d17c184420e1e26c16b59f3cf9d0d3000cc37c54f8731ddf05959453af24c', '991d17c184420e1e26c16b59f3cf9d0d3000cc37c54f8731ddf05959453af24c', NULL, 'وقال الذين كفروا اءذا كنا تربا وءاباؤنا ائنا لمخرجون', 20, 39, 153, 1, 5, 383, false, NULL),
    (3227, 'tanzil-uthmani-v1.1', 27, 68, 'لَقَدْ وُعِدْنَا هَٰذَا نَحْنُ وَءَابَآؤُنَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', '7438a544528e68c1a2024950b00bf756136c96a85640a655abf0275bf1a0ea90', 'لَقَدْ وُعِدْنَا هَٰذَا نَحْنُ وَءَابَآؤُنَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', '7438a544528e68c1a2024950b00bf756136c96a85640a655abf0275bf1a0ea90', '7438a544528e68c1a2024950b00bf756136c96a85640a655abf0275bf1a0ea90', NULL, 'لقد وعدنا هذا نحن وءاباؤنا من قبل ان هذا الا اسطير الاولين', 20, 39, 153, 1, 5, 383, false, NULL),
    (3228, 'tanzil-uthmani-v1.1', 27, 69, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'eb122f18491cd628bb1f773d55309eb8fc51cb86524ebb4486f09af287be55aa', 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 'eb122f18491cd628bb1f773d55309eb8fc51cb86524ebb4486f09af287be55aa', 'eb122f18491cd628bb1f773d55309eb8fc51cb86524ebb4486f09af287be55aa', NULL, 'قل سيروا في الارض فانظروا كيف كان عقبه المجرمين', 20, 39, 153, 1, 5, 383, false, NULL),
    (3229, 'tanzil-uthmani-v1.1', 27, 70, 'وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', '32507888a5a527f85865a0a1863c5e30eebf224d87ee48b9c971326188637b5b', 'وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ', '32507888a5a527f85865a0a1863c5e30eebf224d87ee48b9c971326188637b5b', '32507888a5a527f85865a0a1863c5e30eebf224d87ee48b9c971326188637b5b', NULL, 'ولا تحزن عليهم ولا تكن في ضيق مما يمكرون', 20, 39, 153, 1, 5, 383, false, NULL),
    (3230, 'tanzil-uthmani-v1.1', 27, 71, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', NULL, 'ويقولون متي هذا الوعد ان كنتم صدقين', 20, 39, 153, 1, 5, 383, false, NULL),
    (3231, 'tanzil-uthmani-v1.1', 27, 72, 'قُلْ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ ٱلَّذِى تَسْتَعْجِلُونَ', '92625238acc96cbd37b482e58adf99bf7a7f39f14629661ba9f60ab0c5892953', 'قُلْ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ ٱلَّذِى تَسْتَعْجِلُونَ', '92625238acc96cbd37b482e58adf99bf7a7f39f14629661ba9f60ab0c5892953', '92625238acc96cbd37b482e58adf99bf7a7f39f14629661ba9f60ab0c5892953', NULL, 'قل عسي ان يكون ردف لكم بعض الذي تستعجلون', 20, 39, 153, 1, 5, 383, false, NULL),
    (3232, 'tanzil-uthmani-v1.1', 27, 73, 'وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', '2a732aedfc5e8ddcd04a619ee8812a1bc3cfad6df819048de16d894d47af2a60', 'وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', '2a732aedfc5e8ddcd04a619ee8812a1bc3cfad6df819048de16d894d47af2a60', '2a732aedfc5e8ddcd04a619ee8812a1bc3cfad6df819048de16d894d47af2a60', NULL, 'وان ربك لذو فضل علي الناس ولكن اكثرهم لا يشكرون', 20, 39, 153, 1, 5, 383, false, NULL),
    (3233, 'tanzil-uthmani-v1.1', 27, 74, 'وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'e3354b489f595db44e78e971c8a133c173f9dafd456a69e8e33e9d7d90df19e6', 'وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', 'e3354b489f595db44e78e971c8a133c173f9dafd456a69e8e33e9d7d90df19e6', 'e3354b489f595db44e78e971c8a133c173f9dafd456a69e8e33e9d7d90df19e6', NULL, 'وان ربك ليعلم ما تكن صدورهم وما يعلنون', 20, 39, 153, 1, 5, 383, false, NULL),
    (3234, 'tanzil-uthmani-v1.1', 27, 75, 'وَمَا مِنْ غَآئِبَةٍ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', '19728bb19da9413a61a841f3f3d31cd4f55a6ceccc9bc8f76c1b3129feafdbdd', 'وَمَا مِنْ غَآئِبَةٍ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', '19728bb19da9413a61a841f3f3d31cd4f55a6ceccc9bc8f76c1b3129feafdbdd', '19728bb19da9413a61a841f3f3d31cd4f55a6ceccc9bc8f76c1b3129feafdbdd', NULL, 'وما من غائبه في السماء والارض الا في كتب مبين', 20, 39, 153, 1, 5, 383, false, NULL),
    (3235, 'tanzil-uthmani-v1.1', 27, 76, 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَقُصُّ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَكْثَرَ ٱلَّذِى هُمْ فِيهِ يَخْتَلِفُونَ', '3fb079727d92d1bd414ea4a74e578978ae6fa458eace12ef16ab65e01663748f', 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَقُصُّ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَكْثَرَ ٱلَّذِى هُمْ فِيهِ يَخْتَلِفُونَ', '3fb079727d92d1bd414ea4a74e578978ae6fa458eace12ef16ab65e01663748f', '3fb079727d92d1bd414ea4a74e578978ae6fa458eace12ef16ab65e01663748f', NULL, 'ان هذا القرءان يقص علي بني اسرءيل اكثر الذي هم فيه يختلفون', 20, 39, 153, 1, 5, 383, false, NULL),
    (3236, 'tanzil-uthmani-v1.1', 27, 77, 'وَإِنَّهُۥ لَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', '0b1db10c001f8a6855452983ed7de64311167807245048fc40a5aedf31127ceb', 'وَإِنَّهُۥ لَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ', '0b1db10c001f8a6855452983ed7de64311167807245048fc40a5aedf31127ceb', '0b1db10c001f8a6855452983ed7de64311167807245048fc40a5aedf31127ceb', NULL, 'وانه لهدي ورحمه للمؤمنين', 20, 39, 153, 1, 5, 384, false, NULL),
    (3237, 'tanzil-uthmani-v1.1', 27, 78, 'إِنَّ رَبَّكَ يَقْضِى بَيْنَهُم بِحُكْمِهِۦ وَهُوَ ٱلْعَزِيزُ ٱلْعَلِيمُ', '6c1aeb3e45c81c5029c93caa5368f1b67d382a716838ddce6f59657a7b3bd820', 'إِنَّ رَبَّكَ يَقْضِى بَيْنَهُم بِحُكْمِهِۦ وَهُوَ ٱلْعَزِيزُ ٱلْعَلِيمُ', '6c1aeb3e45c81c5029c93caa5368f1b67d382a716838ddce6f59657a7b3bd820', '6c1aeb3e45c81c5029c93caa5368f1b67d382a716838ddce6f59657a7b3bd820', NULL, 'ان ربك يقضي بينهم بحكمه وهو العزيز العليم', 20, 39, 153, 1, 5, 384, false, NULL),
    (3238, 'tanzil-uthmani-v1.1', 27, 79, 'فَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّكَ عَلَى ٱلْحَقِّ ٱلْمُبِينِ', 'b252b12c6d8261050428fa19748c83f1787111a6c11a5e47ab68d69730f45223', 'فَتَوَكَّلْ عَلَى ٱللَّهِ إِنَّكَ عَلَى ٱلْحَقِّ ٱلْمُبِينِ', 'b252b12c6d8261050428fa19748c83f1787111a6c11a5e47ab68d69730f45223', 'b252b12c6d8261050428fa19748c83f1787111a6c11a5e47ab68d69730f45223', NULL, 'فتوكل علي الله انك علي الحق المبين', 20, 39, 153, 1, 5, 384, false, NULL),
    (3239, 'tanzil-uthmani-v1.1', 27, 80, 'إِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', '777a5d66af0511fd4c1dd0d87e2a69a55e52c3800b2f660489bf185beceb69aa', 'إِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', '777a5d66af0511fd4c1dd0d87e2a69a55e52c3800b2f660489bf185beceb69aa', '777a5d66af0511fd4c1dd0d87e2a69a55e52c3800b2f660489bf185beceb69aa', NULL, 'انك لا تسمع الموتي ولا تسمع الصم الدعاء اذا ولوا مدبرين', 20, 39, 153, 1, 5, 384, false, NULL),
    (3240, 'tanzil-uthmani-v1.1', 27, 81, 'وَمَآ أَنتَ بِهَٰدِى ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', '68184e1f3c074103abb1e22b716e8fd3b6af9475d16df005a0bd449590f26173', 'وَمَآ أَنتَ بِهَٰدِى ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', '68184e1f3c074103abb1e22b716e8fd3b6af9475d16df005a0bd449590f26173', '68184e1f3c074103abb1e22b716e8fd3b6af9475d16df005a0bd449590f26173', NULL, 'وما انت بهدي العمي عن ضللتهم ان تسمع الا من يؤمن بايتنا فهم مسلمون', 20, 39, 153, 1, 5, 384, false, NULL),
    (3241, 'tanzil-uthmani-v1.1', 27, 82, 'وَإِذَا وَقَعَ ٱلْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَآبَّةً مِّنَ ٱلْأَرْضِ تُكَلِّمُهُمْ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔايَٰتِنَا لَا يُوقِنُونَ', '08a76e6b89c1900aa29e379414315486c3b278601eb3ce867c55f53bd123dc83', 'وَإِذَا وَقَعَ ٱلْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَآبَّةً مِّنَ ٱلْأَرْضِ تُكَلِّمُهُمْ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔايَٰتِنَا لَا يُوقِنُونَ', '08a76e6b89c1900aa29e379414315486c3b278601eb3ce867c55f53bd123dc83', '08a76e6b89c1900aa29e379414315486c3b278601eb3ce867c55f53bd123dc83', NULL, 'واذا وقع القول عليهم اخرجنا لهم دابه من الارض تكلمهم ان الناس كانوا بايتنا لا يوقنون', 20, 39, 154, 1, 5, 384, false, NULL),
    (3242, 'tanzil-uthmani-v1.1', 27, 83, 'وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةٍ فَوْجًا مِّمَّن يُكَذِّبُ بِـَٔايَٰتِنَا فَهُمْ يُوزَعُونَ', 'a37bbdc39f3523661965bef1aee5fd296e332c44de7c7f8d2cde41d289cd12e9', 'وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةٍ فَوْجًا مِّمَّن يُكَذِّبُ بِـَٔايَٰتِنَا فَهُمْ يُوزَعُونَ', 'a37bbdc39f3523661965bef1aee5fd296e332c44de7c7f8d2cde41d289cd12e9', 'a37bbdc39f3523661965bef1aee5fd296e332c44de7c7f8d2cde41d289cd12e9', NULL, 'ويوم نحشر من كل امه فوجا ممن يكذب بايتنا فهم يوزعون', 20, 39, 154, 1, 5, 384, false, NULL),
    (3243, 'tanzil-uthmani-v1.1', 27, 84, 'حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبْتُم بِـَٔايَٰتِى وَلَمْ تُحِيطُوا۟ بِهَا عِلْمًا أَمَّاذَا كُنتُمْ تَعْمَلُونَ', '98982354d1f1bbe66b18982ed7a5695e58d9d69ce5b5fa5fb4024f37115d29d4', 'حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبْتُم بِـَٔايَٰتِى وَلَمْ تُحِيطُوا۟ بِهَا عِلْمًا أَمَّاذَا كُنتُمْ تَعْمَلُونَ', '98982354d1f1bbe66b18982ed7a5695e58d9d69ce5b5fa5fb4024f37115d29d4', '98982354d1f1bbe66b18982ed7a5695e58d9d69ce5b5fa5fb4024f37115d29d4', NULL, 'حتي اذا جاءو قال اكذبتم بايتي ولم تحيطوا بها علما اماذا كنتم تعملون', 20, 39, 154, 1, 5, 384, false, NULL),
    (3244, 'tanzil-uthmani-v1.1', 27, 85, 'وَوَقَعَ ٱلْقَوْلُ عَلَيْهِم بِمَا ظَلَمُوا۟ فَهُمْ لَا يَنطِقُونَ', 'b5a4f5e2d77a7085e4dc4a3cef7be727c23bf0688022f60bf782c91151cd59ff', 'وَوَقَعَ ٱلْقَوْلُ عَلَيْهِم بِمَا ظَلَمُوا۟ فَهُمْ لَا يَنطِقُونَ', 'b5a4f5e2d77a7085e4dc4a3cef7be727c23bf0688022f60bf782c91151cd59ff', 'b5a4f5e2d77a7085e4dc4a3cef7be727c23bf0688022f60bf782c91151cd59ff', NULL, 'ووقع القول عليهم بما ظلموا فهم لا ينطقون', 20, 39, 154, 1, 5, 384, false, NULL),
    (3245, 'tanzil-uthmani-v1.1', 27, 86, 'أَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا ٱلَّيْلَ لِيَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'd0ce2a960a3190917ec4121566d28c66d86adf0857403d37f23bb853a9ee1e5f', 'أَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا ٱلَّيْلَ لِيَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'd0ce2a960a3190917ec4121566d28c66d86adf0857403d37f23bb853a9ee1e5f', 'd0ce2a960a3190917ec4121566d28c66d86adf0857403d37f23bb853a9ee1e5f', NULL, 'الم يروا انا جعلنا اليل ليسكنوا فيه والنهار مبصرا ان في ذلك لايت لقوم يؤمنون', 20, 39, 154, 1, 5, 384, false, NULL),
    (3246, 'tanzil-uthmani-v1.1', 27, 87, 'وَيَوْمَ يُنفَخُ فِى ٱلصُّورِ فَفَزِعَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ وَكُلٌّ أَتَوْهُ دَٰخِرِينَ', 'e9ea20277eb3ebf279840d63d1e2b7e3a468defa36c2606b277d760df5fb2b4e', 'وَيَوْمَ يُنفَخُ فِى ٱلصُّورِ فَفَزِعَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ وَكُلٌّ أَتَوْهُ دَٰخِرِينَ', 'e9ea20277eb3ebf279840d63d1e2b7e3a468defa36c2606b277d760df5fb2b4e', 'e9ea20277eb3ebf279840d63d1e2b7e3a468defa36c2606b277d760df5fb2b4e', NULL, 'ويوم ينفخ في الصور ففزع من في السموت ومن في الارض الا من شاء الله وكل اتوه دخرين', 20, 39, 154, 1, 5, 384, false, NULL),
    (3247, 'tanzil-uthmani-v1.1', 27, 88, 'وَتَرَى ٱلْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِىَ تَمُرُّ مَرَّ ٱلسَّحَابِ صُنْعَ ٱللَّهِ ٱلَّذِىٓ أَتْقَنَ كُلَّ شَىْءٍ إِنَّهُۥ خَبِيرٌۢ بِمَا تَفْعَلُونَ', '739b1691ba61bfa36f5f4a4510646596d8c48ae4cbf0fb6df54e5ad2fe124941', 'وَتَرَى ٱلْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِىَ تَمُرُّ مَرَّ ٱلسَّحَابِ صُنْعَ ٱللَّهِ ٱلَّذِىٓ أَتْقَنَ كُلَّ شَىْءٍ إِنَّهُۥ خَبِيرٌۢ بِمَا تَفْعَلُونَ', '739b1691ba61bfa36f5f4a4510646596d8c48ae4cbf0fb6df54e5ad2fe124941', '739b1691ba61bfa36f5f4a4510646596d8c48ae4cbf0fb6df54e5ad2fe124941', NULL, 'وتري الجبال تحسبها جامده وهي تمر مر السحاب صنع الله الذي اتقن كل شيء انه خبير بما تفعلون', 20, 39, 154, 1, 5, 384, false, NULL),
    (3248, 'tanzil-uthmani-v1.1', 27, 89, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَهُم مِّن فَزَعٍ يَوْمَئِذٍ ءَامِنُونَ', '7aed5c486d40fb2f8c046707c4c538ae1b8f7e350172741e56d723cae1e1876c', 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَهُم مِّن فَزَعٍ يَوْمَئِذٍ ءَامِنُونَ', '7aed5c486d40fb2f8c046707c4c538ae1b8f7e350172741e56d723cae1e1876c', '7aed5c486d40fb2f8c046707c4c538ae1b8f7e350172741e56d723cae1e1876c', NULL, 'من جاء بالحسنه فله خير منها وهم من فزع يومئذ ءامنون', 20, 39, 154, 1, 5, 385, false, NULL),
    (3249, 'tanzil-uthmani-v1.1', 27, 90, 'وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِى ٱلنَّارِ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'ba42101705de78303313b2811942dade5e3909c7d4b71df3564751456aef8277', 'وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِى ٱلنَّارِ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 'ba42101705de78303313b2811942dade5e3909c7d4b71df3564751456aef8277', 'ba42101705de78303313b2811942dade5e3909c7d4b71df3564751456aef8277', NULL, 'ومن جاء بالسيئه فكبت وجوههم في النار هل تجزون الا ما كنتم تعملون', 20, 39, 154, 1, 5, 385, false, NULL),
    (3250, 'tanzil-uthmani-v1.1', 27, 91, 'إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَٰذِهِ ٱلْبَلْدَةِ ٱلَّذِى حَرَّمَهَا وَلَهُۥ كُلُّ شَىْءٍ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', '341c38ed2eab32d0d9d872e6e73db69deb99f0be9bab441d2966f45de6fef7ba', 'إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَٰذِهِ ٱلْبَلْدَةِ ٱلَّذِى حَرَّمَهَا وَلَهُۥ كُلُّ شَىْءٍ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', '341c38ed2eab32d0d9d872e6e73db69deb99f0be9bab441d2966f45de6fef7ba', '341c38ed2eab32d0d9d872e6e73db69deb99f0be9bab441d2966f45de6fef7ba', NULL, 'انما امرت ان اعبد رب هذه البلده الذي حرمها وله كل شيء وامرت ان اكون من المسلمين', 20, 39, 154, 1, 5, 385, false, NULL),
    (3251, 'tanzil-uthmani-v1.1', 27, 92, 'وَأَنْ أَتْلُوَا۟ ٱلْقُرْءَانَ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا۠ مِنَ ٱلْمُنذِرِينَ', '79a0a1af7c940bc6f6bc287c6f9c58629d21a4b90d5b82fd98644480c0b0327b', 'وَأَنْ أَتْلُوَا۟ ٱلْقُرْءَانَ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا۠ مِنَ ٱلْمُنذِرِينَ', '79a0a1af7c940bc6f6bc287c6f9c58629d21a4b90d5b82fd98644480c0b0327b', '79a0a1af7c940bc6f6bc287c6f9c58629d21a4b90d5b82fd98644480c0b0327b', NULL, 'وان اتلوا القرءان فمن اهتدي فانما يهتدي لنفسه ومن ضل فقل انما انا من المنذرين', 20, 39, 154, 1, 5, 385, false, NULL),
    (3252, 'tanzil-uthmani-v1.1', 27, 93, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ سَيُرِيكُمْ ءَايَٰتِهِۦ فَتَعْرِفُونَهَا وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', '2cd5ccc4aa6ccb07ca5e422bda5c89512c97968bbfc47bbdf35d5cef5f9ba2c7', 'وَقُلِ ٱلْحَمْدُ لِلَّهِ سَيُرِيكُمْ ءَايَٰتِهِۦ فَتَعْرِفُونَهَا وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', '2cd5ccc4aa6ccb07ca5e422bda5c89512c97968bbfc47bbdf35d5cef5f9ba2c7', '2cd5ccc4aa6ccb07ca5e422bda5c89512c97968bbfc47bbdf35d5cef5f9ba2c7', NULL, 'وقل الحمد لله سيريكم ءايته فتعرفونها وما ربك بغفل عما تعملون', 20, 39, 154, 1, 5, 385, false, NULL),
    (3253, 'tanzil-uthmani-v1.1', 28, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ طسٓمٓ', '6355d27b1ff544257899ea1f1f83f4ea63b34b9b1bc3abbf17acf76a575c61fa', 'طسٓمٓ', '547911999c7d9d4491f025c0f3f7616997cbbf6354d715acc2a778254f009288', '547911999c7d9d4491f025c0f3f7616997cbbf6354d715acc2a778254f009288', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'طسم', 20, 39, 154, 1, 5, 385, false, NULL),
    (3254, 'tanzil-uthmani-v1.1', 28, 2, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'c008249b2b287157ea7a41075aeeeef82370051d2a44a191f4dc6582b7492836', 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 'c008249b2b287157ea7a41075aeeeef82370051d2a44a191f4dc6582b7492836', 'c008249b2b287157ea7a41075aeeeef82370051d2a44a191f4dc6582b7492836', NULL, 'تلك ءايت الكتب المبين', 20, 39, 154, 1, 5, 385, false, NULL),
    (3255, 'tanzil-uthmani-v1.1', 28, 3, 'نَتْلُوا۟ عَلَيْكَ مِن نَّبَإِ مُوسَىٰ وَفِرْعَوْنَ بِٱلْحَقِّ لِقَوْمٍ يُؤْمِنُونَ', 'e36cfede55dafc7707ddb1fd2fd519b18282324d06469ad6213026b17d29117d', 'نَتْلُوا۟ عَلَيْكَ مِن نَّبَإِ مُوسَىٰ وَفِرْعَوْنَ بِٱلْحَقِّ لِقَوْمٍ يُؤْمِنُونَ', 'e36cfede55dafc7707ddb1fd2fd519b18282324d06469ad6213026b17d29117d', 'e36cfede55dafc7707ddb1fd2fd519b18282324d06469ad6213026b17d29117d', NULL, 'نتلوا عليك من نبا موسي وفرعون بالحق لقوم يؤمنون', 20, 39, 154, 1, 5, 385, false, NULL),
    (3256, 'tanzil-uthmani-v1.1', 28, 4, 'إِنَّ فِرْعَوْنَ عَلَا فِى ٱلْأَرْضِ وَجَعَلَ أَهْلَهَا شِيَعًا يَسْتَضْعِفُ طَآئِفَةً مِّنْهُمْ يُذَبِّحُ أَبْنَآءَهُمْ وَيَسْتَحْىِۦ نِسَآءَهُمْ إِنَّهُۥ كَانَ مِنَ ٱلْمُفْسِدِينَ', '2126f9b97d785712d476d27df2e50bef4fb3e409d28f66654a8bf19f2ae63117', 'إِنَّ فِرْعَوْنَ عَلَا فِى ٱلْأَرْضِ وَجَعَلَ أَهْلَهَا شِيَعًا يَسْتَضْعِفُ طَآئِفَةً مِّنْهُمْ يُذَبِّحُ أَبْنَآءَهُمْ وَيَسْتَحْىِۦ نِسَآءَهُمْ إِنَّهُۥ كَانَ مِنَ ٱلْمُفْسِدِينَ', '2126f9b97d785712d476d27df2e50bef4fb3e409d28f66654a8bf19f2ae63117', '2126f9b97d785712d476d27df2e50bef4fb3e409d28f66654a8bf19f2ae63117', NULL, 'ان فرعون علا في الارض وجعل اهلها شيعا يستضعف طائفه منهم يذبح ابناءهم ويستحي نساءهم انه كان من المفسدين', 20, 39, 154, 1, 5, 385, false, NULL),
    (3257, 'tanzil-uthmani-v1.1', 28, 5, 'وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسْتُضْعِفُوا۟ فِى ٱلْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ ٱلْوَٰرِثِينَ', '3434600ee730d44a3eac101bb2ed564918ac1624f56213f7380a00fa7194891a', 'وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسْتُضْعِفُوا۟ فِى ٱلْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ ٱلْوَٰرِثِينَ', '3434600ee730d44a3eac101bb2ed564918ac1624f56213f7380a00fa7194891a', '3434600ee730d44a3eac101bb2ed564918ac1624f56213f7380a00fa7194891a', NULL, 'ونريد ان نمن علي الذين استضعفوا في الارض ونجعلهم ائمه ونجعلهم الورثين', 20, 39, 154, 1, 5, 385, false, NULL),
    (3258, 'tanzil-uthmani-v1.1', 28, 6, 'وَنُمَكِّنَ لَهُمْ فِى ٱلْأَرْضِ وَنُرِىَ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنْهُم مَّا كَانُوا۟ يَحْذَرُونَ', '5f7a0221f7974432346915e5b775faf1d59ad32b3b72528098180856ac42582a', 'وَنُمَكِّنَ لَهُمْ فِى ٱلْأَرْضِ وَنُرِىَ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنْهُم مَّا كَانُوا۟ يَحْذَرُونَ', '5f7a0221f7974432346915e5b775faf1d59ad32b3b72528098180856ac42582a', '5f7a0221f7974432346915e5b775faf1d59ad32b3b72528098180856ac42582a', NULL, 'ونمكن لهم في الارض ونري فرعون وهمن وجنودهما منهم ما كانوا يحذرون', 20, 39, 154, 1, 5, 386, false, NULL),
    (3259, 'tanzil-uthmani-v1.1', 28, 7, 'وَأَوْحَيْنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنْ أَرْضِعِيهِ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِى ٱلْيَمِّ وَلَا تَخَافِى وَلَا تَحْزَنِىٓ إِنَّا رَآدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ ٱلْمُرْسَلِينَ', '659dac0cd62fcda33719fabf01192cf6e61bebb5d913dac2e109662096fba107', 'وَأَوْحَيْنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنْ أَرْضِعِيهِ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِى ٱلْيَمِّ وَلَا تَخَافِى وَلَا تَحْزَنِىٓ إِنَّا رَآدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ ٱلْمُرْسَلِينَ', '659dac0cd62fcda33719fabf01192cf6e61bebb5d913dac2e109662096fba107', '659dac0cd62fcda33719fabf01192cf6e61bebb5d913dac2e109662096fba107', NULL, 'واوحينا الي ام موسي ان ارضعيه فاذا خفت عليه فالقيه في اليم ولا تخافي ولا تحزني انا رادوه اليك وجاعلوه من المرسلين', 20, 39, 154, 1, 5, 386, false, NULL),
    (3260, 'tanzil-uthmani-v1.1', 28, 8, 'فَٱلْتَقَطَهُۥٓ ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا إِنَّ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُوا۟ خَٰطِـِٔينَ', '91d18f30e957d50a06b86e09678e75e2ee80ab60e32a2875fe220a0b03656e2f', 'فَٱلْتَقَطَهُۥٓ ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا إِنَّ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُوا۟ خَٰطِـِٔينَ', '91d18f30e957d50a06b86e09678e75e2ee80ab60e32a2875fe220a0b03656e2f', '91d18f30e957d50a06b86e09678e75e2ee80ab60e32a2875fe220a0b03656e2f', NULL, 'فالتقطه ءال فرعون ليكون لهم عدوا وحزنا ان فرعون وهمن وجنودهما كانوا خطين', 20, 39, 154, 1, 5, 386, false, NULL),
    (3261, 'tanzil-uthmani-v1.1', 28, 9, 'وَقَالَتِ ٱمْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ لِّى وَلَكَ لَا تَقْتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَهُمْ لَا يَشْعُرُونَ', 'ce744c5953e599d852258928a0593bb65306e896d474a53f260eeb7661799f30', 'وَقَالَتِ ٱمْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ لِّى وَلَكَ لَا تَقْتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَهُمْ لَا يَشْعُرُونَ', 'ce744c5953e599d852258928a0593bb65306e896d474a53f260eeb7661799f30', 'ce744c5953e599d852258928a0593bb65306e896d474a53f260eeb7661799f30', NULL, 'وقالت امرات فرعون قرت عين لي ولك لا تقتلوه عسي ان ينفعنا او نتخذه ولدا وهم لا يشعرون', 20, 39, 154, 1, 5, 386, false, NULL),
    (3262, 'tanzil-uthmani-v1.1', 28, 10, 'وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًا إِن كَادَتْ لَتُبْدِى بِهِۦ لَوْلَآ أَن رَّبَطْنَا عَلَىٰ قَلْبِهَا لِتَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'a086fd00f82a53e9ac9db1a13d50c3d3afbf11aaa3a1657739adec8b78804234', 'وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًا إِن كَادَتْ لَتُبْدِى بِهِۦ لَوْلَآ أَن رَّبَطْنَا عَلَىٰ قَلْبِهَا لِتَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 'a086fd00f82a53e9ac9db1a13d50c3d3afbf11aaa3a1657739adec8b78804234', 'a086fd00f82a53e9ac9db1a13d50c3d3afbf11aaa3a1657739adec8b78804234', NULL, 'واصبح فؤاد ام موسي فرغا ان كادت لتبدي به لولا ان ربطنا علي قلبها لتكون من المؤمنين', 20, 39, 154, 1, 5, 386, false, NULL),
    (3263, 'tanzil-uthmani-v1.1', 28, 11, 'وَقَالَتْ لِأُخْتِهِۦ قُصِّيهِ فَبَصُرَتْ بِهِۦ عَن جُنُبٍ وَهُمْ لَا يَشْعُرُونَ', '7b675847ab95159b175d46d3566bcd8ea3d658d8b508ec7f5e5bd5a800f284ff', 'وَقَالَتْ لِأُخْتِهِۦ قُصِّيهِ فَبَصُرَتْ بِهِۦ عَن جُنُبٍ وَهُمْ لَا يَشْعُرُونَ', '7b675847ab95159b175d46d3566bcd8ea3d658d8b508ec7f5e5bd5a800f284ff', '7b675847ab95159b175d46d3566bcd8ea3d658d8b508ec7f5e5bd5a800f284ff', NULL, 'وقالت لاخته قصيه فبصرت به عن جنب وهم لا يشعرون', 20, 39, 154, 1, 5, 386, false, NULL),
    (3264, 'tanzil-uthmani-v1.1', 28, 12, 'وَحَرَّمْنَا عَلَيْهِ ٱلْمَرَاضِعَ مِن قَبْلُ فَقَالَتْ هَلْ أَدُلُّكُمْ عَلَىٰٓ أَهْلِ بَيْتٍ يَكْفُلُونَهُۥ لَكُمْ وَهُمْ لَهُۥ نَٰصِحُونَ', 'b3d2efd3d816b9244635b05f124bad035e5bd3345c46223790e2780c3a73dcde', 'وَحَرَّمْنَا عَلَيْهِ ٱلْمَرَاضِعَ مِن قَبْلُ فَقَالَتْ هَلْ أَدُلُّكُمْ عَلَىٰٓ أَهْلِ بَيْتٍ يَكْفُلُونَهُۥ لَكُمْ وَهُمْ لَهُۥ نَٰصِحُونَ', 'b3d2efd3d816b9244635b05f124bad035e5bd3345c46223790e2780c3a73dcde', 'b3d2efd3d816b9244635b05f124bad035e5bd3345c46223790e2780c3a73dcde', NULL, 'وحرمنا عليه المراضع من قبل فقالت هل ادلكم علي اهل بيت يكفلونه لكم وهم له نصحون', 20, 39, 155, 1, 5, 386, false, NULL),
    (3265, 'tanzil-uthmani-v1.1', 28, 13, 'فَرَدَدْنَٰهُ إِلَىٰٓ أُمِّهِۦ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '67661dfec89c765b31a057580e6ed0e05571f1686871d421c16bba4536e671bc', 'فَرَدَدْنَٰهُ إِلَىٰٓ أُمِّهِۦ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ أَنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', '67661dfec89c765b31a057580e6ed0e05571f1686871d421c16bba4536e671bc', '67661dfec89c765b31a057580e6ed0e05571f1686871d421c16bba4536e671bc', NULL, 'فرددنه الي امه كي تقر عينها ولا تحزن ولتعلم ان وعد الله حق ولكن اكثرهم لا يعلمون', 20, 39, 155, 1, 5, 386, false, NULL),
    (3266, 'tanzil-uthmani-v1.1', 28, 14, 'وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسْتَوَىٰٓ ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '774ffee1324685eb2449d28381c857e7d415c8a044db1cd8efa887720bd2a067', 'وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسْتَوَىٰٓ ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', '774ffee1324685eb2449d28381c857e7d415c8a044db1cd8efa887720bd2a067', '774ffee1324685eb2449d28381c857e7d415c8a044db1cd8efa887720bd2a067', NULL, 'ولما بلغ اشده واستوي ءاتينه حكما وعلما وكذلك نجزي المحسنين', 20, 39, 155, 1, 5, 387, false, NULL),
    (3267, 'tanzil-uthmani-v1.1', 28, 15, 'وَدَخَلَ ٱلْمَدِينَةَ عَلَىٰ حِينِ غَفْلَةٍ مِّنْ أَهْلِهَا فَوَجَدَ فِيهَا رَجُلَيْنِ يَقْتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنْ عَدُوِّهِۦ فَٱسْتَغَٰثَهُ ٱلَّذِى مِن شِيعَتِهِۦ عَلَى ٱلَّذِى مِنْ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيْهِ قَالَ هَٰذَا مِنْ عَمَلِ ٱلشَّيْطَٰنِ إِنَّهُۥ عَدُوٌّ مُّضِلٌّ مُّبِينٌ', '7996e08a82ecbc66eaf04c0ec7765ffe13e79d5a5dbb4e9bc5f2a69c7699622b', 'وَدَخَلَ ٱلْمَدِينَةَ عَلَىٰ حِينِ غَفْلَةٍ مِّنْ أَهْلِهَا فَوَجَدَ فِيهَا رَجُلَيْنِ يَقْتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنْ عَدُوِّهِۦ فَٱسْتَغَٰثَهُ ٱلَّذِى مِن شِيعَتِهِۦ عَلَى ٱلَّذِى مِنْ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيْهِ قَالَ هَٰذَا مِنْ عَمَلِ ٱلشَّيْطَٰنِ إِنَّهُۥ عَدُوٌّ مُّضِلٌّ مُّبِينٌ', '7996e08a82ecbc66eaf04c0ec7765ffe13e79d5a5dbb4e9bc5f2a69c7699622b', '7996e08a82ecbc66eaf04c0ec7765ffe13e79d5a5dbb4e9bc5f2a69c7699622b', NULL, 'ودخل المدينه علي حين غفله من اهلها فوجد فيها رجلين يقتتلان هذا من شيعته وهذا من عدوه فاستغثه الذي من شيعته علي الذي من عدوه فوكزه موسي فقضي عليه قال هذا من عمل الشيطن انه عدو مضل مبين', 20, 39, 155, 1, 5, 387, false, NULL),
    (3268, 'tanzil-uthmani-v1.1', 28, 16, 'قَالَ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى فَٱغْفِرْ لِى فَغَفَرَ لَهُۥٓ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'cbb89f2a84cdaddba49cdad6ff4f95a6e097103c28303bf842efe5e1ad6c7a00', 'قَالَ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى فَٱغْفِرْ لِى فَغَفَرَ لَهُۥٓ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'cbb89f2a84cdaddba49cdad6ff4f95a6e097103c28303bf842efe5e1ad6c7a00', 'cbb89f2a84cdaddba49cdad6ff4f95a6e097103c28303bf842efe5e1ad6c7a00', NULL, 'قال رب اني ظلمت نفسي فاغفر لي فغفر له انه هو الغفور الرحيم', 20, 39, 155, 1, 5, 387, false, NULL),
    (3269, 'tanzil-uthmani-v1.1', 28, 17, 'قَالَ رَبِّ بِمَآ أَنْعَمْتَ عَلَىَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ', '9082f1f4c5c6b3f3559c731659ef9d2cdb2f8d45cd6ee1a74f37abd12d7e48a8', 'قَالَ رَبِّ بِمَآ أَنْعَمْتَ عَلَىَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ', '9082f1f4c5c6b3f3559c731659ef9d2cdb2f8d45cd6ee1a74f37abd12d7e48a8', '9082f1f4c5c6b3f3559c731659ef9d2cdb2f8d45cd6ee1a74f37abd12d7e48a8', NULL, 'قال رب بما انعمت علي فلن اكون ظهيرا للمجرمين', 20, 39, 155, 1, 5, 387, false, NULL),
    (3270, 'tanzil-uthmani-v1.1', 28, 18, 'فَأَصْبَحَ فِى ٱلْمَدِينَةِ خَآئِفًا يَتَرَقَّبُ فَإِذَا ٱلَّذِى ٱسْتَنصَرَهُۥ بِٱلْأَمْسِ يَسْتَصْرِخُهُۥ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِىٌّ مُّبِينٌ', '053d8080dbe7b5b3051c9f9b012ce605351c132782dcbe91482d4f1b1520be49', 'فَأَصْبَحَ فِى ٱلْمَدِينَةِ خَآئِفًا يَتَرَقَّبُ فَإِذَا ٱلَّذِى ٱسْتَنصَرَهُۥ بِٱلْأَمْسِ يَسْتَصْرِخُهُۥ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِىٌّ مُّبِينٌ', '053d8080dbe7b5b3051c9f9b012ce605351c132782dcbe91482d4f1b1520be49', '053d8080dbe7b5b3051c9f9b012ce605351c132782dcbe91482d4f1b1520be49', NULL, 'فاصبح في المدينه خائفا يترقب فاذا الذي استنصره بالامس يستصرخه قال له موسي انك لغوي مبين', 20, 39, 155, 1, 5, 387, false, NULL),
    (3271, 'tanzil-uthmani-v1.1', 28, 19, 'فَلَمَّآ أَنْ أَرَادَ أَن يَبْطِشَ بِٱلَّذِى هُوَ عَدُوٌّ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقْتُلَنِى كَمَا قَتَلْتَ نَفْسًۢا بِٱلْأَمْسِ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارًا فِى ٱلْأَرْضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلْمُصْلِحِينَ', 'cb7dde94289241dc1d10b48545a21c809e8f1b2f589339f2f5b808aace61dfa6', 'فَلَمَّآ أَنْ أَرَادَ أَن يَبْطِشَ بِٱلَّذِى هُوَ عَدُوٌّ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقْتُلَنِى كَمَا قَتَلْتَ نَفْسًۢا بِٱلْأَمْسِ إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارًا فِى ٱلْأَرْضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ ٱلْمُصْلِحِينَ', 'cb7dde94289241dc1d10b48545a21c809e8f1b2f589339f2f5b808aace61dfa6', 'cb7dde94289241dc1d10b48545a21c809e8f1b2f589339f2f5b808aace61dfa6', NULL, 'فلما ان اراد ان يبطش بالذي هو عدو لهما قال يموسي اتريد ان تقتلني كما قتلت نفسا بالامس ان تريد الا ان تكون جبارا في الارض وما تريد ان تكون من المصلحين', 20, 39, 155, 1, 5, 387, false, NULL),
    (3272, 'tanzil-uthmani-v1.1', 28, 20, 'وَجَآءَ رَجُلٌ مِّنْ أَقْصَا ٱلْمَدِينَةِ يَسْعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَٱخْرُجْ إِنِّى لَكَ مِنَ ٱلنَّٰصِحِينَ', 'e0581cb63fc625aec5fe9962d7694367dfa1a1a505fe60b72e20e1de5c17406e', 'وَجَآءَ رَجُلٌ مِّنْ أَقْصَا ٱلْمَدِينَةِ يَسْعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ ٱلْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَٱخْرُجْ إِنِّى لَكَ مِنَ ٱلنَّٰصِحِينَ', 'e0581cb63fc625aec5fe9962d7694367dfa1a1a505fe60b72e20e1de5c17406e', 'e0581cb63fc625aec5fe9962d7694367dfa1a1a505fe60b72e20e1de5c17406e', NULL, 'وجاء رجل من اقصا المدينه يسعي قال يموسي ان الملا ياتمرون بك ليقتلوك فاخرج اني لك من النصحين', 20, 39, 155, 1, 5, 387, false, NULL),
    (3273, 'tanzil-uthmani-v1.1', 28, 21, 'فَخَرَجَ مِنْهَا خَآئِفًا يَتَرَقَّبُ قَالَ رَبِّ نَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '88a95a77669e5ad7cc8dc8b918e1cc612d2ab2b1058bd884c64957916620412e', 'فَخَرَجَ مِنْهَا خَآئِفًا يَتَرَقَّبُ قَالَ رَبِّ نَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '88a95a77669e5ad7cc8dc8b918e1cc612d2ab2b1058bd884c64957916620412e', '88a95a77669e5ad7cc8dc8b918e1cc612d2ab2b1058bd884c64957916620412e', NULL, 'فخرج منها خائفا يترقب قال رب نجني من القوم الظلمين', 20, 39, 155, 1, 5, 387, false, NULL),
    (3274, 'tanzil-uthmani-v1.1', 28, 22, 'وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ قَالَ عَسَىٰ رَبِّىٓ أَن يَهْدِيَنِى سَوَآءَ ٱلسَّبِيلِ', 'bcdbe1d91a0ac976d2093865ece97829f0c21d494f24ecb02aadc438c2459d75', 'وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ قَالَ عَسَىٰ رَبِّىٓ أَن يَهْدِيَنِى سَوَآءَ ٱلسَّبِيلِ', 'bcdbe1d91a0ac976d2093865ece97829f0c21d494f24ecb02aadc438c2459d75', 'bcdbe1d91a0ac976d2093865ece97829f0c21d494f24ecb02aadc438c2459d75', NULL, 'ولما توجه تلقاء مدين قال عسي ربي ان يهديني سواء السبيل', 20, 39, 155, 1, 5, 388, false, NULL),
    (3275, 'tanzil-uthmani-v1.1', 28, 23, 'وَلَمَّا وَرَدَ مَآءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةً مِّنَ ٱلنَّاسِ يَسْقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمْرَأَتَيْنِ تَذُودَانِ قَالَ مَا خَطْبُكُمَا قَالَتَا لَا نَسْقِى حَتَّىٰ يُصْدِرَ ٱلرِّعَآءُ وَأَبُونَا شَيْخٌ كَبِيرٌ', '20cc285b395f65416c338b6895a5f7d4563e0890076efd788908e9bce7048d6b', 'وَلَمَّا وَرَدَ مَآءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةً مِّنَ ٱلنَّاسِ يَسْقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمْرَأَتَيْنِ تَذُودَانِ قَالَ مَا خَطْبُكُمَا قَالَتَا لَا نَسْقِى حَتَّىٰ يُصْدِرَ ٱلرِّعَآءُ وَأَبُونَا شَيْخٌ كَبِيرٌ', '20cc285b395f65416c338b6895a5f7d4563e0890076efd788908e9bce7048d6b', '20cc285b395f65416c338b6895a5f7d4563e0890076efd788908e9bce7048d6b', NULL, 'ولما ورد ماء مدين وجد عليه امه من الناس يسقون ووجد من دونهم امراتين تذودان قال ما خطبكما قالتا لا نسقي حتي يصدر الرعاء وابونا شيخ كبير', 20, 39, 155, 1, 5, 388, false, NULL),
    (3276, 'tanzil-uthmani-v1.1', 28, 24, 'فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍ فَقِيرٌ', 'd978eb342396464feb50e75fda3f8c5636bad71f8e3ca60dba21d3d8824697c3', 'فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍ فَقِيرٌ', 'd978eb342396464feb50e75fda3f8c5636bad71f8e3ca60dba21d3d8824697c3', 'd978eb342396464feb50e75fda3f8c5636bad71f8e3ca60dba21d3d8824697c3', NULL, 'فسقي لهما ثم تولي الي الظل فقال رب اني لما انزلت الي من خير فقير', 20, 39, 155, 1, 5, 388, false, NULL),
    (3277, 'tanzil-uthmani-v1.1', 28, 25, 'فَجَآءَتْهُ إِحْدَىٰهُمَا تَمْشِى عَلَى ٱسْتِحْيَآءٍ قَالَتْ إِنَّ أَبِى يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيْهِ ٱلْقَصَصَ قَالَ لَا تَخَفْ نَجَوْتَ مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '84c6efd0419d2cc2a12f80a122cc813325cc69b9802e3fac1a759b4412016761', 'فَجَآءَتْهُ إِحْدَىٰهُمَا تَمْشِى عَلَى ٱسْتِحْيَآءٍ قَالَتْ إِنَّ أَبِى يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيْهِ ٱلْقَصَصَ قَالَ لَا تَخَفْ نَجَوْتَ مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', '84c6efd0419d2cc2a12f80a122cc813325cc69b9802e3fac1a759b4412016761', '84c6efd0419d2cc2a12f80a122cc813325cc69b9802e3fac1a759b4412016761', NULL, 'فجاءته احديهما تمشي علي استحياء قالت ان ابي يدعوك ليجزيك اجر ما سقيت لنا فلما جاءه وقص عليه القصص قال لا تخف نجوت من القوم الظلمين', 20, 39, 155, 1, 5, 388, false, NULL),
    (3278, 'tanzil-uthmani-v1.1', 28, 26, 'قَالَتْ إِحْدَىٰهُمَا يَٰٓأَبَتِ ٱسْتَـْٔجِرْهُ إِنَّ خَيْرَ مَنِ ٱسْتَـْٔجَرْتَ ٱلْقَوِىُّ ٱلْأَمِينُ', 'c905e9be05f5896bb5088004fd38b8648731d5d97066c9c1dcf206d67f11d4fd', 'قَالَتْ إِحْدَىٰهُمَا يَٰٓأَبَتِ ٱسْتَـْٔجِرْهُ إِنَّ خَيْرَ مَنِ ٱسْتَـْٔجَرْتَ ٱلْقَوِىُّ ٱلْأَمِينُ', 'c905e9be05f5896bb5088004fd38b8648731d5d97066c9c1dcf206d67f11d4fd', 'c905e9be05f5896bb5088004fd38b8648731d5d97066c9c1dcf206d67f11d4fd', NULL, 'قالت احديهما يابت استجره ان خير من استجرت القوي الامين', 20, 39, 155, 1, 5, 388, false, NULL),
    (3279, 'tanzil-uthmani-v1.1', 28, 27, 'قَالَ إِنِّىٓ أُرِيدُ أَنْ أُنكِحَكَ إِحْدَى ٱبْنَتَىَّ هَٰتَيْنِ عَلَىٰٓ أَن تَأْجُرَنِى ثَمَٰنِىَ حِجَجٍ فَإِنْ أَتْمَمْتَ عَشْرًا فَمِنْ عِندِكَ وَمَآ أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ', 'a75a498e14a8d1ed5cdf05ab6e74d13cbcac19b050645e42614a70424d1ac7cb', 'قَالَ إِنِّىٓ أُرِيدُ أَنْ أُنكِحَكَ إِحْدَى ٱبْنَتَىَّ هَٰتَيْنِ عَلَىٰٓ أَن تَأْجُرَنِى ثَمَٰنِىَ حِجَجٍ فَإِنْ أَتْمَمْتَ عَشْرًا فَمِنْ عِندِكَ وَمَآ أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ', 'a75a498e14a8d1ed5cdf05ab6e74d13cbcac19b050645e42614a70424d1ac7cb', 'a75a498e14a8d1ed5cdf05ab6e74d13cbcac19b050645e42614a70424d1ac7cb', NULL, 'قال اني اريد ان انكحك احدي ابنتي هتين علي ان تاجرني ثمني حجج فان اتممت عشرا فمن عندك وما اريد ان اشق عليك ستجدني ان شاء الله من الصلحين', 20, 39, 155, 1, 5, 388, false, NULL),
    (3280, 'tanzil-uthmani-v1.1', 28, 28, 'قَالَ ذَٰلِكَ بَيْنِى وَبَيْنَكَ أَيَّمَا ٱلْأَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَٰنَ عَلَىَّ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', '23b0b1b7af4f696cab3cc5b6164d2f7b5f57a2b689dbf406eb46a947218fa11c', 'قَالَ ذَٰلِكَ بَيْنِى وَبَيْنَكَ أَيَّمَا ٱلْأَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَٰنَ عَلَىَّ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ', '23b0b1b7af4f696cab3cc5b6164d2f7b5f57a2b689dbf406eb46a947218fa11c', '23b0b1b7af4f696cab3cc5b6164d2f7b5f57a2b689dbf406eb46a947218fa11c', NULL, 'قال ذلك بيني وبينك ايما الاجلين قضيت فلا عدون علي والله علي ما نقول وكيل', 20, 39, 155, 1, 5, 388, false, NULL),
    (3281, 'tanzil-uthmani-v1.1', 28, 29, 'فَلَمَّا قَضَىٰ مُوسَى ٱلْأَجَلَ وَسَارَ بِأَهْلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارًا قَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِّنَ ٱلنَّارِ لَعَلَّكُمْ تَصْطَلُونَ', '036808439f858c7d59d644b2246c250d458a21e1b0cbf535f7d72f069b68d14d', 'فَلَمَّا قَضَىٰ مُوسَى ٱلْأَجَلَ وَسَارَ بِأَهْلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارًا قَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِّنَ ٱلنَّارِ لَعَلَّكُمْ تَصْطَلُونَ', '036808439f858c7d59d644b2246c250d458a21e1b0cbf535f7d72f069b68d14d', '036808439f858c7d59d644b2246c250d458a21e1b0cbf535f7d72f069b68d14d', NULL, 'فلما قضي موسي الاجل وسار باهله ءانس من جانب الطور نارا قال لاهله امكثوا اني ءانست نارا لعلي ءاتيكم منها بخبر او جذوه من النار لعلكم تصطلون', 20, 39, 156, 1, 5, 389, false, NULL),
    (3282, 'tanzil-uthmani-v1.1', 28, 30, 'فَلَمَّآ أَتَىٰهَا نُودِىَ مِن شَٰطِئِ ٱلْوَادِ ٱلْأَيْمَنِ فِى ٱلْبُقْعَةِ ٱلْمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّىٓ أَنَا ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'db69654524f538356b8b1932b68cd5f8da5d4bb540fb590940990372326bd537', 'فَلَمَّآ أَتَىٰهَا نُودِىَ مِن شَٰطِئِ ٱلْوَادِ ٱلْأَيْمَنِ فِى ٱلْبُقْعَةِ ٱلْمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّىٓ أَنَا ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'db69654524f538356b8b1932b68cd5f8da5d4bb540fb590940990372326bd537', 'db69654524f538356b8b1932b68cd5f8da5d4bb540fb590940990372326bd537', NULL, 'فلما اتيها نودي من شطئ الواد الايمن في البقعه المبركه من الشجره ان يموسي اني انا الله رب العلمين', 20, 39, 156, 1, 5, 389, false, NULL),
    (3283, 'tanzil-uthmani-v1.1', 28, 31, 'وَأَنْ أَلْقِ عَصَاكَ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ يَٰمُوسَىٰٓ أَقْبِلْ وَلَا تَخَفْ إِنَّكَ مِنَ ٱلْـَٔامِنِينَ', 'ebd8eb3de649fbc3bf8b1319ae3c2c037fc37a3d1e7170b09fe03511e122613e', 'وَأَنْ أَلْقِ عَصَاكَ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ يَٰمُوسَىٰٓ أَقْبِلْ وَلَا تَخَفْ إِنَّكَ مِنَ ٱلْـَٔامِنِينَ', 'ebd8eb3de649fbc3bf8b1319ae3c2c037fc37a3d1e7170b09fe03511e122613e', 'ebd8eb3de649fbc3bf8b1319ae3c2c037fc37a3d1e7170b09fe03511e122613e', NULL, 'وان الق عصاك فلما رءاها تهتز كانها جان ولي مدبرا ولم يعقب يموسي اقبل ولا تخف انك من الامنين', 20, 39, 156, 1, 5, 389, false, NULL),
    (3284, 'tanzil-uthmani-v1.1', 28, 32, 'ٱسْلُكْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ وَٱضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ ٱلرَّهْبِ فَذَٰنِكَ بُرْهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦٓ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', '34b281f75ee22128a65cfaa6899fcb9e613e8c64993dd4a945dc5bb59544d9f9', 'ٱسْلُكْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ وَٱضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ ٱلرَّهْبِ فَذَٰنِكَ بُرْهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦٓ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', '34b281f75ee22128a65cfaa6899fcb9e613e8c64993dd4a945dc5bb59544d9f9', '34b281f75ee22128a65cfaa6899fcb9e613e8c64993dd4a945dc5bb59544d9f9', NULL, 'اسلك يدك في جيبك تخرج بيضاء من غير سوء واضمم اليك جناحك من الرهب فذنك برهنان من ربك الي فرعون وملايه انهم كانوا قوما فسقين', 20, 39, 156, 1, 5, 389, false, NULL),
    (3285, 'tanzil-uthmani-v1.1', 28, 33, 'قَالَ رَبِّ إِنِّى قَتَلْتُ مِنْهُمْ نَفْسًا فَأَخَافُ أَن يَقْتُلُونِ', '5233d85f1add95c7091f3f039e500cdada93eab85ef3ebaaff039db389b33da9', 'قَالَ رَبِّ إِنِّى قَتَلْتُ مِنْهُمْ نَفْسًا فَأَخَافُ أَن يَقْتُلُونِ', '5233d85f1add95c7091f3f039e500cdada93eab85ef3ebaaff039db389b33da9', '5233d85f1add95c7091f3f039e500cdada93eab85ef3ebaaff039db389b33da9', NULL, 'قال رب اني قتلت منهم نفسا فاخاف ان يقتلون', 20, 39, 156, 1, 5, 389, false, NULL),
    (3286, 'tanzil-uthmani-v1.1', 28, 34, 'وَأَخِى هَٰرُونُ هُوَ أَفْصَحُ مِنِّى لِسَانًا فَأَرْسِلْهُ مَعِىَ رِدْءًا يُصَدِّقُنِىٓ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', '94c09aa77aa4c0fb99c48689f68a55857d4070c7abda851d0d0a56fa00787101', 'وَأَخِى هَٰرُونُ هُوَ أَفْصَحُ مِنِّى لِسَانًا فَأَرْسِلْهُ مَعِىَ رِدْءًا يُصَدِّقُنِىٓ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', '94c09aa77aa4c0fb99c48689f68a55857d4070c7abda851d0d0a56fa00787101', '94c09aa77aa4c0fb99c48689f68a55857d4070c7abda851d0d0a56fa00787101', NULL, 'واخي هرون هو افصح مني لسانا فارسله معي ردءا يصدقني اني اخاف ان يكذبون', 20, 39, 156, 1, 5, 389, false, NULL),
    (3287, 'tanzil-uthmani-v1.1', 28, 35, 'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَٰنًا فَلَا يَصِلُونَ إِلَيْكُمَا بِـَٔايَٰتِنَآ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلْغَٰلِبُونَ', 'dfc9307135488eae265e45a02ddaef8c1938b8631f5c8255ace8668c68e8b978', 'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَٰنًا فَلَا يَصِلُونَ إِلَيْكُمَا بِـَٔايَٰتِنَآ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلْغَٰلِبُونَ', 'dfc9307135488eae265e45a02ddaef8c1938b8631f5c8255ace8668c68e8b978', 'dfc9307135488eae265e45a02ddaef8c1938b8631f5c8255ace8668c68e8b978', NULL, 'قال سنشد عضدك باخيك ونجعل لكما سلطنا فلا يصلون اليكما بايتنا انتما ومن اتبعكما الغلبون', 20, 39, 156, 1, 5, 389, false, NULL),
    (3288, 'tanzil-uthmani-v1.1', 28, 36, 'فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٍ قَالُوا۟ مَا هَٰذَآ إِلَّا سِحْرٌ مُّفْتَرًى وَمَا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', '63c1987347fc9b89922c5cd1d21276759c83e6e4ae84aff7a15bf68a6c407c35', 'فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٍ قَالُوا۟ مَا هَٰذَآ إِلَّا سِحْرٌ مُّفْتَرًى وَمَا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', '63c1987347fc9b89922c5cd1d21276759c83e6e4ae84aff7a15bf68a6c407c35', '63c1987347fc9b89922c5cd1d21276759c83e6e4ae84aff7a15bf68a6c407c35', NULL, 'فلما جاءهم موسي بايتنا بينت قالوا ما هذا الا سحر مفتري وما سمعنا بهذا في ءابائنا الاولين', 20, 39, 156, 1, 5, 390, false, NULL),
    (3289, 'tanzil-uthmani-v1.1', 28, 37, 'وَقَالَ مُوسَىٰ رَبِّىٓ أَعْلَمُ بِمَن جَآءَ بِٱلْهُدَىٰ مِنْ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', '4d8050e558413905ab520c06072ac4e1ae341ae408e581b8ee25a264a827e058', 'وَقَالَ مُوسَىٰ رَبِّىٓ أَعْلَمُ بِمَن جَآءَ بِٱلْهُدَىٰ مِنْ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', '4d8050e558413905ab520c06072ac4e1ae341ae408e581b8ee25a264a827e058', '4d8050e558413905ab520c06072ac4e1ae341ae408e581b8ee25a264a827e058', NULL, 'وقال موسي ربي اعلم بمن جاء بالهدي من عنده ومن تكون له عقبه الدار انه لا يفلح الظلمون', 20, 39, 156, 1, 5, 390, false, NULL),
    (3290, 'tanzil-uthmani-v1.1', 28, 38, 'وَقَالَ فِرْعَوْنُ يَٰٓأَيُّهَا ٱلْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِى فَأَوْقِدْ لِى يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجْعَل لِّى صَرْحًا لَّعَلِّىٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ مِنَ ٱلْكَٰذِبِينَ', 'c994792ac9153764279efd6535e6b678009ed40f52f9032f8693e0c215f24537', 'وَقَالَ فِرْعَوْنُ يَٰٓأَيُّهَا ٱلْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِى فَأَوْقِدْ لِى يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجْعَل لِّى صَرْحًا لَّعَلِّىٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ مِنَ ٱلْكَٰذِبِينَ', 'c994792ac9153764279efd6535e6b678009ed40f52f9032f8693e0c215f24537', 'c994792ac9153764279efd6535e6b678009ed40f52f9032f8693e0c215f24537', NULL, 'وقال فرعون يايها الملا ما علمت لكم من اله غيري فاوقد لي يهمن علي الطين فاجعل لي صرحا لعلي اطلع الي اله موسي واني لاظنه من الكذبين', 20, 39, 156, 1, 5, 390, false, NULL),
    (3291, 'tanzil-uthmani-v1.1', 28, 39, 'وَٱسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَظَنُّوٓا۟ أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ', '6ef815f9a9a74c0f276cc1ebd26bc4f37fd2736f2e7773255f0ad3d8dd7f3de9', 'وَٱسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَظَنُّوٓا۟ أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ', '6ef815f9a9a74c0f276cc1ebd26bc4f37fd2736f2e7773255f0ad3d8dd7f3de9', '6ef815f9a9a74c0f276cc1ebd26bc4f37fd2736f2e7773255f0ad3d8dd7f3de9', NULL, 'واستكبر هو وجنوده في الارض بغير الحق وظنوا انهم الينا لا يرجعون', 20, 39, 156, 1, 5, 390, false, NULL),
    (3292, 'tanzil-uthmani-v1.1', 28, 40, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'd079c67aa1842c0fdfb363c550b5f12a39d0a863127a8d9278cd8d3f77738200', 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 'd079c67aa1842c0fdfb363c550b5f12a39d0a863127a8d9278cd8d3f77738200', 'd079c67aa1842c0fdfb363c550b5f12a39d0a863127a8d9278cd8d3f77738200', NULL, 'فاخذنه وجنوده فنبذنهم في اليم فانظر كيف كان عقبه الظلمين', 20, 39, 156, 1, 5, 390, false, NULL),
    (3293, 'tanzil-uthmani-v1.1', 28, 41, 'وَجَعَلْنَٰهُمْ أَئِمَّةً يَدْعُونَ إِلَى ٱلنَّارِ وَيَوْمَ ٱلْقِيَٰمَةِ لَا يُنصَرُونَ', '1cf2dbf229b42d5e56ad7f850b9a4a9e84118f2d25f841a7c010ab2d299aa6e1', 'وَجَعَلْنَٰهُمْ أَئِمَّةً يَدْعُونَ إِلَى ٱلنَّارِ وَيَوْمَ ٱلْقِيَٰمَةِ لَا يُنصَرُونَ', '1cf2dbf229b42d5e56ad7f850b9a4a9e84118f2d25f841a7c010ab2d299aa6e1', '1cf2dbf229b42d5e56ad7f850b9a4a9e84118f2d25f841a7c010ab2d299aa6e1', NULL, 'وجعلنهم ائمه يدعون الي النار ويوم القيمه لا ينصرون', 20, 39, 156, 1, 5, 390, false, NULL),
    (3294, 'tanzil-uthmani-v1.1', 28, 42, 'وَأَتْبَعْنَٰهُمْ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ هُم مِّنَ ٱلْمَقْبُوحِينَ', '5a8856968b695271058a2634b12bbd7718760c4457ea16d24ef0d21765582971', 'وَأَتْبَعْنَٰهُمْ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةً وَيَوْمَ ٱلْقِيَٰمَةِ هُم مِّنَ ٱلْمَقْبُوحِينَ', '5a8856968b695271058a2634b12bbd7718760c4457ea16d24ef0d21765582971', '5a8856968b695271058a2634b12bbd7718760c4457ea16d24ef0d21765582971', NULL, 'واتبعنهم في هذه الدنيا لعنه ويوم القيمه هم من المقبوحين', 20, 39, 156, 1, 5, 390, false, NULL),
    (3295, 'tanzil-uthmani-v1.1', 28, 43, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ مِنۢ بَعْدِ مَآ أَهْلَكْنَا ٱلْقُرُونَ ٱلْأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدًى وَرَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُونَ', '97f85515d9728f4f3af81b3935d6b1f70379ebfbafd2d5acd603e946c9d0886f', 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ مِنۢ بَعْدِ مَآ أَهْلَكْنَا ٱلْقُرُونَ ٱلْأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدًى وَرَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُونَ', '97f85515d9728f4f3af81b3935d6b1f70379ebfbafd2d5acd603e946c9d0886f', '97f85515d9728f4f3af81b3935d6b1f70379ebfbafd2d5acd603e946c9d0886f', NULL, 'ولقد ءاتينا موسي الكتب من بعد ما اهلكنا القرون الاولي بصائر للناس وهدي ورحمه لعلهم يتذكرون', 20, 39, 156, 1, 5, 390, false, NULL),
    (3296, 'tanzil-uthmani-v1.1', 28, 44, 'وَمَا كُنتَ بِجَانِبِ ٱلْغَرْبِىِّ إِذْ قَضَيْنَآ إِلَىٰ مُوسَى ٱلْأَمْرَ وَمَا كُنتَ مِنَ ٱلشَّٰهِدِينَ', '65f12683301a02970c1d1f3e782b36786ea476569867721be7b79af34bab1716', 'وَمَا كُنتَ بِجَانِبِ ٱلْغَرْبِىِّ إِذْ قَضَيْنَآ إِلَىٰ مُوسَى ٱلْأَمْرَ وَمَا كُنتَ مِنَ ٱلشَّٰهِدِينَ', '65f12683301a02970c1d1f3e782b36786ea476569867721be7b79af34bab1716', '65f12683301a02970c1d1f3e782b36786ea476569867721be7b79af34bab1716', NULL, 'وما كنت بجانب الغربي اذ قضينا الي موسي الامر وما كنت من الشهدين', 20, 39, 156, 1, 5, 391, false, NULL),
    (3297, 'tanzil-uthmani-v1.1', 28, 45, 'وَلَٰكِنَّآ أَنشَأْنَا قُرُونًا فَتَطَاوَلَ عَلَيْهِمُ ٱلْعُمُرُ وَمَا كُنتَ ثَاوِيًا فِىٓ أَهْلِ مَدْيَنَ تَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرْسِلِينَ', '2e6a768e47f11c0d823c3f1e94f88b8ae5497fefcd5f695721959b90a60650a3', 'وَلَٰكِنَّآ أَنشَأْنَا قُرُونًا فَتَطَاوَلَ عَلَيْهِمُ ٱلْعُمُرُ وَمَا كُنتَ ثَاوِيًا فِىٓ أَهْلِ مَدْيَنَ تَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرْسِلِينَ', '2e6a768e47f11c0d823c3f1e94f88b8ae5497fefcd5f695721959b90a60650a3', '2e6a768e47f11c0d823c3f1e94f88b8ae5497fefcd5f695721959b90a60650a3', NULL, 'ولكنا انشانا قرونا فتطاول عليهم العمر وما كنت ثاويا في اهل مدين تتلوا عليهم ءايتنا ولكنا كنا مرسلين', 20, 39, 156, 1, 5, 391, false, NULL),
    (3298, 'tanzil-uthmani-v1.1', 28, 46, 'وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذْ نَادَيْنَا وَلَٰكِن رَّحْمَةً مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', '5bcde9d3329440224cbf5b24ec0a45d62dbda54ae1f3386812b1783ca04a4cb3', 'وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذْ نَادَيْنَا وَلَٰكِن رَّحْمَةً مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', '5bcde9d3329440224cbf5b24ec0a45d62dbda54ae1f3386812b1783ca04a4cb3', '5bcde9d3329440224cbf5b24ec0a45d62dbda54ae1f3386812b1783ca04a4cb3', NULL, 'وما كنت بجانب الطور اذ نادينا ولكن رحمه من ربك لتنذر قوما ما اتيهم من نذير من قبلك لعلهم يتذكرون', 20, 39, 156, 1, 5, 391, false, NULL),
    (3299, 'tanzil-uthmani-v1.1', 28, 47, 'وَلَوْلَآ أَن تُصِيبَهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَيَقُولُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', '3e20e3af029611fcc536ef1fa2df1129fbedc453a7e2aab0d5cb88b3b1c28f88', 'وَلَوْلَآ أَن تُصِيبَهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَيَقُولُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', '3e20e3af029611fcc536ef1fa2df1129fbedc453a7e2aab0d5cb88b3b1c28f88', '3e20e3af029611fcc536ef1fa2df1129fbedc453a7e2aab0d5cb88b3b1c28f88', NULL, 'ولولا ان تصيبهم مصيبه بما قدمت ايديهم فيقولوا ربنا لولا ارسلت الينا رسولا فنتبع ءايتك ونكون من المؤمنين', 20, 39, 156, 1, 5, 391, false, NULL),
    (3300, 'tanzil-uthmani-v1.1', 28, 48, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوا۟ لَوْلَآ أُوتِىَ مِثْلَ مَآ أُوتِىَ مُوسَىٰٓ أَوَلَمْ يَكْفُرُوا۟ بِمَآ أُوتِىَ مُوسَىٰ مِن قَبْلُ قَالُوا۟ سِحْرَانِ تَظَٰهَرَا وَقَالُوٓا۟ إِنَّا بِكُلٍّ كَٰفِرُونَ', '2890c5d6cfc2526c82c33045701a288265820af2c0f1f4a21c1fd507d663c6a0', 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوا۟ لَوْلَآ أُوتِىَ مِثْلَ مَآ أُوتِىَ مُوسَىٰٓ أَوَلَمْ يَكْفُرُوا۟ بِمَآ أُوتِىَ مُوسَىٰ مِن قَبْلُ قَالُوا۟ سِحْرَانِ تَظَٰهَرَا وَقَالُوٓا۟ إِنَّا بِكُلٍّ كَٰفِرُونَ', '2890c5d6cfc2526c82c33045701a288265820af2c0f1f4a21c1fd507d663c6a0', '2890c5d6cfc2526c82c33045701a288265820af2c0f1f4a21c1fd507d663c6a0', NULL, 'فلما جاءهم الحق من عندنا قالوا لولا اوتي مثل ما اوتي موسي اولم يكفروا بما اوتي موسي من قبل قالوا سحران تظهرا وقالوا انا بكل كفرون', 20, 39, 156, 1, 5, 391, false, NULL),
    (3301, 'tanzil-uthmani-v1.1', 28, 49, 'قُلْ فَأْتُوا۟ بِكِتَٰبٍ مِّنْ عِندِ ٱللَّهِ هُوَ أَهْدَىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَٰدِقِينَ', '4e9016ecae84ca049c2a333b98cc5853fa902f3e6ec10abe57885f902622ab00', 'قُلْ فَأْتُوا۟ بِكِتَٰبٍ مِّنْ عِندِ ٱللَّهِ هُوَ أَهْدَىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَٰدِقِينَ', '4e9016ecae84ca049c2a333b98cc5853fa902f3e6ec10abe57885f902622ab00', '4e9016ecae84ca049c2a333b98cc5853fa902f3e6ec10abe57885f902622ab00', NULL, 'قل فاتوا بكتب من عند الله هو اهدي منهما اتبعه ان كنتم صدقين', 20, 39, 156, 1, 5, 391, false, NULL),
    (3302, 'tanzil-uthmani-v1.1', 28, 50, 'فَإِن لَّمْ يَسْتَجِيبُوا۟ لَكَ فَٱعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَآءَهُمْ وَمَنْ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيْرِ هُدًى مِّنَ ٱللَّهِ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '784292e8b4c88258dda0df2187212ef50159d8a574ce32f52cdd4eef867a775c', 'فَإِن لَّمْ يَسْتَجِيبُوا۟ لَكَ فَٱعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَآءَهُمْ وَمَنْ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيْرِ هُدًى مِّنَ ٱللَّهِ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '784292e8b4c88258dda0df2187212ef50159d8a574ce32f52cdd4eef867a775c', '784292e8b4c88258dda0df2187212ef50159d8a574ce32f52cdd4eef867a775c', NULL, 'فان لم يستجيبوا لك فاعلم انما يتبعون اهواءهم ومن اضل ممن اتبع هويه بغير هدي من الله ان الله لا يهدي القوم الظلمين', 20, 39, 156, 1, 5, 391, false, NULL),
    (3303, 'tanzil-uthmani-v1.1', 28, 51, 'وَلَقَدْ وَصَّلْنَا لَهُمُ ٱلْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'b0860736ec688baeaf461d66b65c1efc9dfb8824ee3911a147339e5003b788ec', 'وَلَقَدْ وَصَّلْنَا لَهُمُ ٱلْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 'b0860736ec688baeaf461d66b65c1efc9dfb8824ee3911a147339e5003b788ec', 'b0860736ec688baeaf461d66b65c1efc9dfb8824ee3911a147339e5003b788ec', NULL, 'ولقد وصلنا لهم القول لعلهم يتذكرون', 20, 40, 157, 1, 5, 392, false, NULL),
    (3304, 'tanzil-uthmani-v1.1', 28, 52, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ مِن قَبْلِهِۦ هُم بِهِۦ يُؤْمِنُونَ', '427a6f69bf00514c33a0b7f50c0d2f3083ee0b4a65d78d1fe1c414e62bf001e5', 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ مِن قَبْلِهِۦ هُم بِهِۦ يُؤْمِنُونَ', '427a6f69bf00514c33a0b7f50c0d2f3083ee0b4a65d78d1fe1c414e62bf001e5', '427a6f69bf00514c33a0b7f50c0d2f3083ee0b4a65d78d1fe1c414e62bf001e5', NULL, 'الذين ءاتينهم الكتب من قبله هم به يؤمنون', 20, 40, 157, 1, 5, 392, false, NULL),
    (3305, 'tanzil-uthmani-v1.1', 28, 53, 'وَإِذَا يُتْلَىٰ عَلَيْهِمْ قَالُوٓا۟ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلْحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبْلِهِۦ مُسْلِمِينَ', '78eb068d75996bd9393d7215959ec210e816020f6ba1ab9b92bf03b79dea78e7', 'وَإِذَا يُتْلَىٰ عَلَيْهِمْ قَالُوٓا۟ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلْحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبْلِهِۦ مُسْلِمِينَ', '78eb068d75996bd9393d7215959ec210e816020f6ba1ab9b92bf03b79dea78e7', '78eb068d75996bd9393d7215959ec210e816020f6ba1ab9b92bf03b79dea78e7', NULL, 'واذا يتلي عليهم قالوا ءامنا به انه الحق من ربنا انا كنا من قبله مسلمين', 20, 40, 157, 1, 5, 392, false, NULL),
    (3306, 'tanzil-uthmani-v1.1', 28, 54, 'أُو۟لَٰٓئِكَ يُؤْتَوْنَ أَجْرَهُم مَّرَّتَيْنِ بِمَا صَبَرُوا۟ وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', '240e1188c487f5004be28f02afd08be6871c04e45609560bccf02b3b0c22b99c', 'أُو۟لَٰٓئِكَ يُؤْتَوْنَ أَجْرَهُم مَّرَّتَيْنِ بِمَا صَبَرُوا۟ وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', '240e1188c487f5004be28f02afd08be6871c04e45609560bccf02b3b0c22b99c', '240e1188c487f5004be28f02afd08be6871c04e45609560bccf02b3b0c22b99c', NULL, 'اولئك يؤتون اجرهم مرتين بما صبروا ويدرءون بالحسنه السيئه ومما رزقنهم ينفقون', 20, 40, 157, 1, 5, 392, false, NULL),
    (3307, 'tanzil-uthmani-v1.1', 28, 55, 'وَإِذَا سَمِعُوا۟ ٱللَّغْوَ أَعْرَضُوا۟ عَنْهُ وَقَالُوا۟ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ سَلَٰمٌ عَلَيْكُمْ لَا نَبْتَغِى ٱلْجَٰهِلِينَ', 'dcfb9df5e5648721d35197a3085b6969988324fc5027b1d3b7f72deba904926c', 'وَإِذَا سَمِعُوا۟ ٱللَّغْوَ أَعْرَضُوا۟ عَنْهُ وَقَالُوا۟ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ سَلَٰمٌ عَلَيْكُمْ لَا نَبْتَغِى ٱلْجَٰهِلِينَ', 'dcfb9df5e5648721d35197a3085b6969988324fc5027b1d3b7f72deba904926c', 'dcfb9df5e5648721d35197a3085b6969988324fc5027b1d3b7f72deba904926c', NULL, 'واذا سمعوا اللغو اعرضوا عنه وقالوا لنا اعملنا ولكم اعملكم سلم عليكم لا نبتغي الجهلين', 20, 40, 157, 1, 5, 392, false, NULL),
    (3308, 'tanzil-uthmani-v1.1', 28, 56, 'إِنَّكَ لَا تَهْدِى مَنْ أَحْبَبْتَ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'a75dc279d83b4b9053e0e09f96b126a87bb13a5874af1d737a70a061939b9b2f', 'إِنَّكَ لَا تَهْدِى مَنْ أَحْبَبْتَ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 'a75dc279d83b4b9053e0e09f96b126a87bb13a5874af1d737a70a061939b9b2f', 'a75dc279d83b4b9053e0e09f96b126a87bb13a5874af1d737a70a061939b9b2f', NULL, 'انك لا تهدي من احببت ولكن الله يهدي من يشاء وهو اعلم بالمهتدين', 20, 40, 157, 1, 5, 392, false, NULL),
    (3309, 'tanzil-uthmani-v1.1', 28, 57, 'وَقَالُوٓا۟ إِن نَّتَّبِعِ ٱلْهُدَىٰ مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِنَآ أَوَلَمْ نُمَكِّن لَّهُمْ حَرَمًا ءَامِنًا يُجْبَىٰٓ إِلَيْهِ ثَمَرَٰتُ كُلِّ شَىْءٍ رِّزْقًا مِّن لَّدُنَّا وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'aef65a32d4cc869db1f898a3b4d3eb61d35a2c01ddcb829b94f6a4eafd5a1816', 'وَقَالُوٓا۟ إِن نَّتَّبِعِ ٱلْهُدَىٰ مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِنَآ أَوَلَمْ نُمَكِّن لَّهُمْ حَرَمًا ءَامِنًا يُجْبَىٰٓ إِلَيْهِ ثَمَرَٰتُ كُلِّ شَىْءٍ رِّزْقًا مِّن لَّدُنَّا وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'aef65a32d4cc869db1f898a3b4d3eb61d35a2c01ddcb829b94f6a4eafd5a1816', 'aef65a32d4cc869db1f898a3b4d3eb61d35a2c01ddcb829b94f6a4eafd5a1816', NULL, 'وقالوا ان نتبع الهدي معك نتخطف من ارضنا اولم نمكن لهم حرما ءامنا يجبي اليه ثمرت كل شيء رزقا من لدنا ولكن اكثرهم لا يعلمون', 20, 40, 157, 1, 5, 392, false, NULL),
    (3310, 'tanzil-uthmani-v1.1', 28, 58, 'وَكَمْ أَهْلَكْنَا مِن قَرْيَةٍۭ بَطِرَتْ مَعِيشَتَهَا فَتِلْكَ مَسَٰكِنُهُمْ لَمْ تُسْكَن مِّنۢ بَعْدِهِمْ إِلَّا قَلِيلًا وَكُنَّا نَحْنُ ٱلْوَٰرِثِينَ', '2d74f5f2d3c0251491e609f2c1801a21f00ec62361bde92b2848d9a1c244e195', 'وَكَمْ أَهْلَكْنَا مِن قَرْيَةٍۭ بَطِرَتْ مَعِيشَتَهَا فَتِلْكَ مَسَٰكِنُهُمْ لَمْ تُسْكَن مِّنۢ بَعْدِهِمْ إِلَّا قَلِيلًا وَكُنَّا نَحْنُ ٱلْوَٰرِثِينَ', '2d74f5f2d3c0251491e609f2c1801a21f00ec62361bde92b2848d9a1c244e195', '2d74f5f2d3c0251491e609f2c1801a21f00ec62361bde92b2848d9a1c244e195', NULL, 'وكم اهلكنا من قريه بطرت معيشتها فتلك مسكنهم لم تسكن من بعدهم الا قليلا وكنا نحن الورثين', 20, 40, 157, 1, 5, 392, false, NULL),
    (3311, 'tanzil-uthmani-v1.1', 28, 59, 'وَمَا كَانَ رَبُّكَ مُهْلِكَ ٱلْقُرَىٰ حَتَّىٰ يَبْعَثَ فِىٓ أُمِّهَا رَسُولًا يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا وَمَا كُنَّا مُهْلِكِى ٱلْقُرَىٰٓ إِلَّا وَأَهْلُهَا ظَٰلِمُونَ', '3cc2da9cb5c8e0f8dec65b4f7c5d46900205511247b0d2062054d66002f0a8fc', 'وَمَا كَانَ رَبُّكَ مُهْلِكَ ٱلْقُرَىٰ حَتَّىٰ يَبْعَثَ فِىٓ أُمِّهَا رَسُولًا يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِنَا وَمَا كُنَّا مُهْلِكِى ٱلْقُرَىٰٓ إِلَّا وَأَهْلُهَا ظَٰلِمُونَ', '3cc2da9cb5c8e0f8dec65b4f7c5d46900205511247b0d2062054d66002f0a8fc', '3cc2da9cb5c8e0f8dec65b4f7c5d46900205511247b0d2062054d66002f0a8fc', NULL, 'وما كان ربك مهلك القري حتي يبعث في امها رسولا يتلوا عليهم ءايتنا وما كنا مهلكي القري الا واهلها ظلمون', 20, 40, 157, 1, 5, 392, false, NULL),
    (3312, 'tanzil-uthmani-v1.1', 28, 60, 'وَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَزِينَتُهَا وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰٓ أَفَلَا تَعْقِلُونَ', '350ef0a315413d49f66b6b53af540efebfc3966150bff63dd987cd9a0372d526', 'وَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَزِينَتُهَا وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰٓ أَفَلَا تَعْقِلُونَ', '350ef0a315413d49f66b6b53af540efebfc3966150bff63dd987cd9a0372d526', '350ef0a315413d49f66b6b53af540efebfc3966150bff63dd987cd9a0372d526', NULL, 'وما اوتيتم من شيء فمتع الحيوه الدنيا وزينتها وما عند الله خير وابقي افلا تعقلون', 20, 40, 157, 1, 5, 393, false, NULL),
    (3313, 'tanzil-uthmani-v1.1', 28, 61, 'أَفَمَن وَعَدْنَٰهُ وَعْدًا حَسَنًا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعْنَٰهُ مَتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ هُوَ يَوْمَ ٱلْقِيَٰمَةِ مِنَ ٱلْمُحْضَرِينَ', '2be3fbda83feee7b2d3b1eb6693944a4f8eef958653802497d0815799b4d5757', 'أَفَمَن وَعَدْنَٰهُ وَعْدًا حَسَنًا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعْنَٰهُ مَتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ هُوَ يَوْمَ ٱلْقِيَٰمَةِ مِنَ ٱلْمُحْضَرِينَ', '2be3fbda83feee7b2d3b1eb6693944a4f8eef958653802497d0815799b4d5757', '2be3fbda83feee7b2d3b1eb6693944a4f8eef958653802497d0815799b4d5757', NULL, 'افمن وعدنه وعدا حسنا فهو لقيه كمن متعنه متع الحيوه الدنيا ثم هو يوم القيمه من المحضرين', 20, 40, 157, 1, 5, 393, false, NULL),
    (3314, 'tanzil-uthmani-v1.1', 28, 62, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', '1a8da080e3ae6d690de27cbb848fbb38ad9032bc0167fcde04b3be3ee667e489', 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', '1a8da080e3ae6d690de27cbb848fbb38ad9032bc0167fcde04b3be3ee667e489', '1a8da080e3ae6d690de27cbb848fbb38ad9032bc0167fcde04b3be3ee667e489', NULL, 'ويوم يناديهم فيقول اين شركاءي الذين كنتم تزعمون', 20, 40, 157, 1, 5, 393, false, NULL),
    (3315, 'tanzil-uthmani-v1.1', 28, 63, 'قَالَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ رَبَّنَا هَٰٓؤُلَآءِ ٱلَّذِينَ أَغْوَيْنَآ أَغْوَيْنَٰهُمْ كَمَا غَوَيْنَا تَبَرَّأْنَآ إِلَيْكَ مَا كَانُوٓا۟ إِيَّانَا يَعْبُدُونَ', '20b60bbb5d6a236f138124ab9123fe07520fefb5ebc9f12966335d4bcb983a9e', 'قَالَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ رَبَّنَا هَٰٓؤُلَآءِ ٱلَّذِينَ أَغْوَيْنَآ أَغْوَيْنَٰهُمْ كَمَا غَوَيْنَا تَبَرَّأْنَآ إِلَيْكَ مَا كَانُوٓا۟ إِيَّانَا يَعْبُدُونَ', '20b60bbb5d6a236f138124ab9123fe07520fefb5ebc9f12966335d4bcb983a9e', '20b60bbb5d6a236f138124ab9123fe07520fefb5ebc9f12966335d4bcb983a9e', NULL, 'قال الذين حق عليهم القول ربنا هؤلاء الذين اغوينا اغوينهم كما غوينا تبرانا اليك ما كانوا ايانا يعبدون', 20, 40, 157, 1, 5, 393, false, NULL),
    (3316, 'tanzil-uthmani-v1.1', 28, 64, 'وَقِيلَ ٱدْعُوا۟ شُرَكَآءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَرَأَوُا۟ ٱلْعَذَابَ لَوْ أَنَّهُمْ كَانُوا۟ يَهْتَدُونَ', 'f7f08bab2bc685a4e7eaa1a099b91c2cd9cd6a0f5dc8a453c7c7e8e4a9dbb380', 'وَقِيلَ ٱدْعُوا۟ شُرَكَآءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَرَأَوُا۟ ٱلْعَذَابَ لَوْ أَنَّهُمْ كَانُوا۟ يَهْتَدُونَ', 'f7f08bab2bc685a4e7eaa1a099b91c2cd9cd6a0f5dc8a453c7c7e8e4a9dbb380', 'f7f08bab2bc685a4e7eaa1a099b91c2cd9cd6a0f5dc8a453c7c7e8e4a9dbb380', NULL, 'وقيل ادعوا شركاءكم فدعوهم فلم يستجيبوا لهم وراوا العذاب لو انهم كانوا يهتدون', 20, 40, 157, 1, 5, 393, false, NULL),
    (3317, 'tanzil-uthmani-v1.1', 28, 65, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذَآ أَجَبْتُمُ ٱلْمُرْسَلِينَ', '3181c3de6909fb23fd44069435ff1bc546406c09de973d256a3ec850d4199031', 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذَآ أَجَبْتُمُ ٱلْمُرْسَلِينَ', '3181c3de6909fb23fd44069435ff1bc546406c09de973d256a3ec850d4199031', '3181c3de6909fb23fd44069435ff1bc546406c09de973d256a3ec850d4199031', NULL, 'ويوم يناديهم فيقول ماذا اجبتم المرسلين', 20, 40, 157, 1, 5, 393, false, NULL),
    (3318, 'tanzil-uthmani-v1.1', 28, 66, 'فَعَمِيَتْ عَلَيْهِمُ ٱلْأَنۢبَآءُ يَوْمَئِذٍ فَهُمْ لَا يَتَسَآءَلُونَ', 'c1722f18f7468012bfaedc305474ae20123b3d508b3b0f8282e6822e600ed5b4', 'فَعَمِيَتْ عَلَيْهِمُ ٱلْأَنۢبَآءُ يَوْمَئِذٍ فَهُمْ لَا يَتَسَآءَلُونَ', 'c1722f18f7468012bfaedc305474ae20123b3d508b3b0f8282e6822e600ed5b4', 'c1722f18f7468012bfaedc305474ae20123b3d508b3b0f8282e6822e600ed5b4', NULL, 'فعميت عليهم الانباء يومئذ فهم لا يتساءلون', 20, 40, 157, 1, 5, 393, false, NULL),
    (3319, 'tanzil-uthmani-v1.1', 28, 67, 'فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلْمُفْلِحِينَ', 'abb9ef104208e0e77f30b6274ea5072e834fc5b51aeac5ef3068c88f0a129280', 'فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلْمُفْلِحِينَ', 'abb9ef104208e0e77f30b6274ea5072e834fc5b51aeac5ef3068c88f0a129280', 'abb9ef104208e0e77f30b6274ea5072e834fc5b51aeac5ef3068c88f0a129280', NULL, 'فاما من تاب وءامن وعمل صلحا فعسي ان يكون من المفلحين', 20, 40, 157, 1, 5, 393, false, NULL),
    (3320, 'tanzil-uthmani-v1.1', 28, 68, 'وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ مَا كَانَ لَهُمُ ٱلْخِيَرَةُ سُبْحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '42084db489d759367b17f84f0106c48f5764e41dcb5547bf1b6c8654d01496e9', 'وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ مَا كَانَ لَهُمُ ٱلْخِيَرَةُ سُبْحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '42084db489d759367b17f84f0106c48f5764e41dcb5547bf1b6c8654d01496e9', '42084db489d759367b17f84f0106c48f5764e41dcb5547bf1b6c8654d01496e9', NULL, 'وربك يخلق ما يشاء ويختار ما كان لهم الخيره سبحن الله وتعلي عما يشركون', 20, 40, 157, 1, 5, 393, false, NULL),
    (3321, 'tanzil-uthmani-v1.1', 28, 69, 'وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', '915796ad4f2f216c041e0a9390f306695b729f96a252457af281818d60b2cb6c', 'وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ', '915796ad4f2f216c041e0a9390f306695b729f96a252457af281818d60b2cb6c', '915796ad4f2f216c041e0a9390f306695b729f96a252457af281818d60b2cb6c', NULL, 'وربك يعلم ما تكن صدورهم وما يعلنون', 20, 40, 157, 1, 5, 393, false, NULL),
    (3322, 'tanzil-uthmani-v1.1', 28, 70, 'وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَهُ ٱلْحَمْدُ فِى ٱلْأُولَىٰ وَٱلْـَٔاخِرَةِ وَلَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', '9904a6203fb59420abb465b67d8a9cb559978c1ce1dd8b9c9243a9a214e8e818', 'وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ لَهُ ٱلْحَمْدُ فِى ٱلْأُولَىٰ وَٱلْـَٔاخِرَةِ وَلَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', '9904a6203fb59420abb465b67d8a9cb559978c1ce1dd8b9c9243a9a214e8e818', '9904a6203fb59420abb465b67d8a9cb559978c1ce1dd8b9c9243a9a214e8e818', NULL, 'وهو الله لا اله الا هو له الحمد في الاولي والاخره وله الحكم واليه ترجعون', 20, 40, 157, 1, 5, 393, false, NULL),
    (3323, 'tanzil-uthmani-v1.1', 28, 71, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلَّيْلَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِضِيَآءٍ أَفَلَا تَسْمَعُونَ', 'a5f769544a3ca03c0c268ac3cbe803620d5f7c5b04c6c7594b88a933a123013c', 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلَّيْلَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِضِيَآءٍ أَفَلَا تَسْمَعُونَ', 'a5f769544a3ca03c0c268ac3cbe803620d5f7c5b04c6c7594b88a933a123013c', 'a5f769544a3ca03c0c268ac3cbe803620d5f7c5b04c6c7594b88a933a123013c', NULL, 'قل ارءيتم ان جعل الله عليكم اليل سرمدا الي يوم القيمه من اله غير الله ياتيكم بضياء افلا تسمعون', 20, 40, 157, 1, 5, 394, false, NULL),
    (3324, 'tanzil-uthmani-v1.1', 28, 72, 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلنَّهَارَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِلَيْلٍ تَسْكُنُونَ فِيهِ أَفَلَا تُبْصِرُونَ', '4c90e9eb520c4d3b53d35a6e95cbbbad9f1438be3175606123e5da395f415baa', 'قُلْ أَرَءَيْتُمْ إِن جَعَلَ ٱللَّهُ عَلَيْكُمُ ٱلنَّهَارَ سَرْمَدًا إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِلَيْلٍ تَسْكُنُونَ فِيهِ أَفَلَا تُبْصِرُونَ', '4c90e9eb520c4d3b53d35a6e95cbbbad9f1438be3175606123e5da395f415baa', '4c90e9eb520c4d3b53d35a6e95cbbbad9f1438be3175606123e5da395f415baa', NULL, 'قل ارءيتم ان جعل الله عليكم النهار سرمدا الي يوم القيمه من اله غير الله ياتيكم بليل تسكنون فيه افلا تبصرون', 20, 40, 157, 1, 5, 394, false, NULL),
    (3325, 'tanzil-uthmani-v1.1', 28, 73, 'وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ لِتَسْكُنُوا۟ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '028b8514deb48b4f66d09e3ac87c941fc371c8132e37a8b8672080a484a0d676', 'وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ لِتَسْكُنُوا۟ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '028b8514deb48b4f66d09e3ac87c941fc371c8132e37a8b8672080a484a0d676', '028b8514deb48b4f66d09e3ac87c941fc371c8132e37a8b8672080a484a0d676', NULL, 'ومن رحمته جعل لكم اليل والنهار لتسكنوا فيه ولتبتغوا من فضله ولعلكم تشكرون', 20, 40, 157, 1, 5, 394, false, NULL),
    (3326, 'tanzil-uthmani-v1.1', 28, 74, 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', '1a8da080e3ae6d690de27cbb848fbb38ad9032bc0167fcde04b3be3ee667e489', 'وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', '1a8da080e3ae6d690de27cbb848fbb38ad9032bc0167fcde04b3be3ee667e489', '1a8da080e3ae6d690de27cbb848fbb38ad9032bc0167fcde04b3be3ee667e489', NULL, 'ويوم يناديهم فيقول اين شركاءي الذين كنتم تزعمون', 20, 40, 157, 1, 5, 394, false, NULL),
    (3327, 'tanzil-uthmani-v1.1', 28, 75, 'وَنَزَعْنَا مِن كُلِّ أُمَّةٍ شَهِيدًا فَقُلْنَا هَاتُوا۟ بُرْهَٰنَكُمْ فَعَلِمُوٓا۟ أَنَّ ٱلْحَقَّ لِلَّهِ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'e48138354589d5364371754adc10df11ed00adc122866f513fe1d9fa96cbb407', 'وَنَزَعْنَا مِن كُلِّ أُمَّةٍ شَهِيدًا فَقُلْنَا هَاتُوا۟ بُرْهَٰنَكُمْ فَعَلِمُوٓا۟ أَنَّ ٱلْحَقَّ لِلَّهِ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 'e48138354589d5364371754adc10df11ed00adc122866f513fe1d9fa96cbb407', 'e48138354589d5364371754adc10df11ed00adc122866f513fe1d9fa96cbb407', NULL, 'ونزعنا من كل امه شهيدا فقلنا هاتوا برهنكم فعلموا ان الحق لله وضل عنهم ما كانوا يفترون', 20, 40, 157, 1, 5, 394, false, NULL),
    (3328, 'tanzil-uthmani-v1.1', 28, 76, 'إِنَّ قَٰرُونَ كَانَ مِن قَوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ وَءَاتَيْنَٰهُ مِنَ ٱلْكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلْعُصْبَةِ أُو۟لِى ٱلْقُوَّةِ إِذْ قَالَ لَهُۥ قَوْمُهُۥ لَا تَفْرَحْ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْفَرِحِينَ', '3d0e89f5fa05ce8c7a6f65a75e720a2295eb17e7cdf7c91d55da55718db4ad34', 'إِنَّ قَٰرُونَ كَانَ مِن قَوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ وَءَاتَيْنَٰهُ مِنَ ٱلْكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلْعُصْبَةِ أُو۟لِى ٱلْقُوَّةِ إِذْ قَالَ لَهُۥ قَوْمُهُۥ لَا تَفْرَحْ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْفَرِحِينَ', '3d0e89f5fa05ce8c7a6f65a75e720a2295eb17e7cdf7c91d55da55718db4ad34', '3d0e89f5fa05ce8c7a6f65a75e720a2295eb17e7cdf7c91d55da55718db4ad34', NULL, 'ان قرون كان من قوم موسي فبغي عليهم وءاتينه من الكنوز ما ان مفاتحه لتنوا بالعصبه اولي القوه اذ قال له قومه لا تفرح ان الله لا يحب الفرحين', 20, 40, 158, 1, 5, 394, false, NULL),
    (3329, 'tanzil-uthmani-v1.1', 28, 77, 'وَٱبْتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلْـَٔاخِرَةَ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنْيَا وَأَحْسِن كَمَآ أَحْسَنَ ٱللَّهُ إِلَيْكَ وَلَا تَبْغِ ٱلْفَسَادَ فِى ٱلْأَرْضِ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُفْسِدِينَ', '171b1450805cee9c9ca21b6db014cb0ed5100a21a09b05c6f7e264ef664e3f33', 'وَٱبْتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلْـَٔاخِرَةَ وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنْيَا وَأَحْسِن كَمَآ أَحْسَنَ ٱللَّهُ إِلَيْكَ وَلَا تَبْغِ ٱلْفَسَادَ فِى ٱلْأَرْضِ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُفْسِدِينَ', '171b1450805cee9c9ca21b6db014cb0ed5100a21a09b05c6f7e264ef664e3f33', '171b1450805cee9c9ca21b6db014cb0ed5100a21a09b05c6f7e264ef664e3f33', NULL, 'وابتغ فيما ءاتيك الله الدار الاخره ولا تنس نصيبك من الدنيا واحسن كما احسن الله اليك ولا تبغ الفساد في الارض ان الله لا يحب المفسدين', 20, 40, 158, 1, 5, 394, false, NULL),
    (3330, 'tanzil-uthmani-v1.1', 28, 78, 'قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ عِندِىٓ أَوَلَمْ يَعْلَمْ أَنَّ ٱللَّهَ قَدْ أَهْلَكَ مِن قَبْلِهِۦ مِنَ ٱلْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّةً وَأَكْثَرُ جَمْعًا وَلَا يُسْـَٔلُ عَن ذُنُوبِهِمُ ٱلْمُجْرِمُونَ', '520c59d877a1d8a78ecdd05a81f2aee1d23ddeedc8ff03b5d8348af30749c745', 'قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ عِندِىٓ أَوَلَمْ يَعْلَمْ أَنَّ ٱللَّهَ قَدْ أَهْلَكَ مِن قَبْلِهِۦ مِنَ ٱلْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّةً وَأَكْثَرُ جَمْعًا وَلَا يُسْـَٔلُ عَن ذُنُوبِهِمُ ٱلْمُجْرِمُونَ', '520c59d877a1d8a78ecdd05a81f2aee1d23ddeedc8ff03b5d8348af30749c745', '520c59d877a1d8a78ecdd05a81f2aee1d23ddeedc8ff03b5d8348af30749c745', NULL, 'قال انما اوتيته علي علم عندي اولم يعلم ان الله قد اهلك من قبله من القرون من هو اشد منه قوه واكثر جمعا ولا يسل عن ذنوبهم المجرمون', 20, 40, 158, 1, 5, 395, false, NULL),
    (3331, 'tanzil-uthmani-v1.1', 28, 79, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ فِى زِينَتِهِۦ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا يَٰلَيْتَ لَنَا مِثْلَ مَآ أُوتِىَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٍ', 'dfc3ecb057ac4b4dbc0400ef5003f1f378ab44fb47439a62e0d581a0f79868fa', 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ فِى زِينَتِهِۦ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا يَٰلَيْتَ لَنَا مِثْلَ مَآ أُوتِىَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٍ', 'dfc3ecb057ac4b4dbc0400ef5003f1f378ab44fb47439a62e0d581a0f79868fa', 'dfc3ecb057ac4b4dbc0400ef5003f1f378ab44fb47439a62e0d581a0f79868fa', NULL, 'فخرج علي قومه في زينته قال الذين يريدون الحيوه الدنيا يليت لنا مثل ما اوتي قرون انه لذو حظ عظيم', 20, 40, 158, 1, 5, 395, false, NULL),
    (3332, 'tanzil-uthmani-v1.1', 28, 80, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَيْلَكُمْ ثَوَابُ ٱللَّهِ خَيْرٌ لِّمَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ', '13f2941910eff2200d329f8d327e7b817ab5f6011bf3e607b866179003c53411', 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَيْلَكُمْ ثَوَابُ ٱللَّهِ خَيْرٌ لِّمَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ', '13f2941910eff2200d329f8d327e7b817ab5f6011bf3e607b866179003c53411', '13f2941910eff2200d329f8d327e7b817ab5f6011bf3e607b866179003c53411', NULL, 'وقال الذين اوتوا العلم ويلكم ثواب الله خير لمن ءامن وعمل صلحا ولا يلقيها الا الصبرون', 20, 40, 158, 1, 5, 395, false, NULL),
    (3333, 'tanzil-uthmani-v1.1', 28, 81, 'فَخَسَفْنَا بِهِۦ وَبِدَارِهِ ٱلْأَرْضَ فَمَا كَانَ لَهُۥ مِن فِئَةٍ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلْمُنتَصِرِينَ', '0ede2c7b64593d6680c3ade6c4cc225f5fee0d9a43dfe76de815db56ece45190', 'فَخَسَفْنَا بِهِۦ وَبِدَارِهِ ٱلْأَرْضَ فَمَا كَانَ لَهُۥ مِن فِئَةٍ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلْمُنتَصِرِينَ', '0ede2c7b64593d6680c3ade6c4cc225f5fee0d9a43dfe76de815db56ece45190', '0ede2c7b64593d6680c3ade6c4cc225f5fee0d9a43dfe76de815db56ece45190', NULL, 'فخسفنا به وبداره الارض فما كان له من فئه ينصرونه من دون الله وما كان من المنتصرين', 20, 40, 158, 1, 5, 395, false, NULL),
    (3334, 'tanzil-uthmani-v1.1', 28, 82, 'وَأَصْبَحَ ٱلَّذِينَ تَمَنَّوْا۟ مَكَانَهُۥ بِٱلْأَمْسِ يَقُولُونَ وَيْكَأَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَوْلَآ أَن مَّنَّ ٱللَّهُ عَلَيْنَا لَخَسَفَ بِنَا وَيْكَأَنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', 'fb0d5209be3cbce9566bffa925377bcc34e7cbeff40a348f09a29d7ccaa9a0a0', 'وَأَصْبَحَ ٱلَّذِينَ تَمَنَّوْا۟ مَكَانَهُۥ بِٱلْأَمْسِ يَقُولُونَ وَيْكَأَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَوْلَآ أَن مَّنَّ ٱللَّهُ عَلَيْنَا لَخَسَفَ بِنَا وَيْكَأَنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', 'fb0d5209be3cbce9566bffa925377bcc34e7cbeff40a348f09a29d7ccaa9a0a0', 'fb0d5209be3cbce9566bffa925377bcc34e7cbeff40a348f09a29d7ccaa9a0a0', NULL, 'واصبح الذين تمنوا مكانه بالامس يقولون ويكان الله يبسط الرزق لمن يشاء من عباده ويقدر لولا ان من الله علينا لخسف بنا ويكانه لا يفلح الكفرون', 20, 40, 158, 1, 5, 395, false, NULL),
    (3335, 'tanzil-uthmani-v1.1', 28, 83, 'تِلْكَ ٱلدَّارُ ٱلْـَٔاخِرَةُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِى ٱلْأَرْضِ وَلَا فَسَادًا وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', '05122e82bd05b2a345a89d46492b6cebfd6e2045fc1cb76e253e31128d99453f', 'تِلْكَ ٱلدَّارُ ٱلْـَٔاخِرَةُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِى ٱلْأَرْضِ وَلَا فَسَادًا وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', '05122e82bd05b2a345a89d46492b6cebfd6e2045fc1cb76e253e31128d99453f', '05122e82bd05b2a345a89d46492b6cebfd6e2045fc1cb76e253e31128d99453f', NULL, 'تلك الدار الاخره نجعلها للذين لا يريدون علوا في الارض ولا فسادا والعقبه للمتقين', 20, 40, 158, 1, 5, 395, false, NULL),
    (3336, 'tanzil-uthmani-v1.1', 28, 84, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَى ٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'c48ba9b9454a6d36c59750e1fee962e8cc1549a3e4c1fbc24ccdaf373e9cd78a', 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَى ٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'c48ba9b9454a6d36c59750e1fee962e8cc1549a3e4c1fbc24ccdaf373e9cd78a', 'c48ba9b9454a6d36c59750e1fee962e8cc1549a3e4c1fbc24ccdaf373e9cd78a', NULL, 'من جاء بالحسنه فله خير منها ومن جاء بالسيئه فلا يجزي الذين عملوا السيات الا ما كانوا يعملون', 20, 40, 158, 1, 5, 395, false, NULL),
    (3337, 'tanzil-uthmani-v1.1', 28, 85, 'إِنَّ ٱلَّذِى فَرَضَ عَلَيْكَ ٱلْقُرْءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٍ قُل رَّبِّىٓ أَعْلَمُ مَن جَآءَ بِٱلْهُدَىٰ وَمَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ', 'fe669eb85517cc99c86a75176fe505f43aeb65c7455e0fc78e62a74db5c2e6f1', 'إِنَّ ٱلَّذِى فَرَضَ عَلَيْكَ ٱلْقُرْءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٍ قُل رَّبِّىٓ أَعْلَمُ مَن جَآءَ بِٱلْهُدَىٰ وَمَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ', 'fe669eb85517cc99c86a75176fe505f43aeb65c7455e0fc78e62a74db5c2e6f1', 'fe669eb85517cc99c86a75176fe505f43aeb65c7455e0fc78e62a74db5c2e6f1', NULL, 'ان الذي فرض عليك القرءان لرادك الي معاد قل ربي اعلم من جاء بالهدي ومن هو في ضلل مبين', 20, 40, 158, 1, 5, 396, false, NULL),
    (3338, 'tanzil-uthmani-v1.1', 28, 86, 'وَمَا كُنتَ تَرْجُوٓا۟ أَن يُلْقَىٰٓ إِلَيْكَ ٱلْكِتَٰبُ إِلَّا رَحْمَةً مِّن رَّبِّكَ فَلَا تَكُونَنَّ ظَهِيرًا لِّلْكَٰفِرِينَ', 'd0ce04852fb958e0258e29c2af210f1a5f76e6c6c06bd799361717adb196031f', 'وَمَا كُنتَ تَرْجُوٓا۟ أَن يُلْقَىٰٓ إِلَيْكَ ٱلْكِتَٰبُ إِلَّا رَحْمَةً مِّن رَّبِّكَ فَلَا تَكُونَنَّ ظَهِيرًا لِّلْكَٰفِرِينَ', 'd0ce04852fb958e0258e29c2af210f1a5f76e6c6c06bd799361717adb196031f', 'd0ce04852fb958e0258e29c2af210f1a5f76e6c6c06bd799361717adb196031f', NULL, 'وما كنت ترجوا ان يلقي اليك الكتب الا رحمه من ربك فلا تكونن ظهيرا للكفرين', 20, 40, 158, 1, 5, 396, false, NULL),
    (3339, 'tanzil-uthmani-v1.1', 28, 87, 'وَلَا يَصُدُّنَّكَ عَنْ ءَايَٰتِ ٱللَّهِ بَعْدَ إِذْ أُنزِلَتْ إِلَيْكَ وَٱدْعُ إِلَىٰ رَبِّكَ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'eb048c056b642670db8e5f99678e007a81f7a27549bdde77c6340933db4a3782', 'وَلَا يَصُدُّنَّكَ عَنْ ءَايَٰتِ ٱللَّهِ بَعْدَ إِذْ أُنزِلَتْ إِلَيْكَ وَٱدْعُ إِلَىٰ رَبِّكَ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 'eb048c056b642670db8e5f99678e007a81f7a27549bdde77c6340933db4a3782', 'eb048c056b642670db8e5f99678e007a81f7a27549bdde77c6340933db4a3782', NULL, 'ولا يصدنك عن ءايت الله بعد اذ انزلت اليك وادع الي ربك ولا تكونن من المشركين', 20, 40, 158, 1, 5, 396, false, NULL),
    (3340, 'tanzil-uthmani-v1.1', 28, 88, 'وَلَا تَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَآ إِلَٰهَ إِلَّا هُوَ كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَجْهَهُۥ لَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', '315454522eb4e732876c20742fa1c55dfebbbe819eee440b45a9bbb18018cb4e', 'وَلَا تَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَآ إِلَٰهَ إِلَّا هُوَ كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَجْهَهُۥ لَهُ ٱلْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ', '315454522eb4e732876c20742fa1c55dfebbbe819eee440b45a9bbb18018cb4e', '315454522eb4e732876c20742fa1c55dfebbbe819eee440b45a9bbb18018cb4e', NULL, 'ولا تدع مع الله الها ءاخر لا اله الا هو كل شيء هالك الا وجهه له الحكم واليه ترجعون', 20, 40, 158, 1, 5, 396, false, NULL),
    (3341, 'tanzil-uthmani-v1.1', 29, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'e190dd3d3d044e6256ebd129866c8631838018200128280a20f27d07491b7e45', 'الٓمٓ', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الم', 20, 40, 159, 1, 5, 396, false, NULL),
    (3342, 'tanzil-uthmani-v1.1', 29, 2, 'أَحَسِبَ ٱلنَّاسُ أَن يُتْرَكُوٓا۟ أَن يَقُولُوٓا۟ ءَامَنَّا وَهُمْ لَا يُفْتَنُونَ', '4744d3e25262e91e9de5f759da714a3b0ab54ba56c0e4e982c7260051af15468', 'أَحَسِبَ ٱلنَّاسُ أَن يُتْرَكُوٓا۟ أَن يَقُولُوٓا۟ ءَامَنَّا وَهُمْ لَا يُفْتَنُونَ', '4744d3e25262e91e9de5f759da714a3b0ab54ba56c0e4e982c7260051af15468', '4744d3e25262e91e9de5f759da714a3b0ab54ba56c0e4e982c7260051af15468', NULL, 'احسب الناس ان يتركوا ان يقولوا ءامنا وهم لا يفتنون', 20, 40, 159, 1, 5, 396, false, NULL),
    (3343, 'tanzil-uthmani-v1.1', 29, 3, 'وَلَقَدْ فَتَنَّا ٱلَّذِينَ مِن قَبْلِهِمْ فَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُوا۟ وَلَيَعْلَمَنَّ ٱلْكَٰذِبِينَ', '9ae010357e2f977d42f6bf7d7db7c369cf413401df4b14ffe12fbb92f1135da4', 'وَلَقَدْ فَتَنَّا ٱلَّذِينَ مِن قَبْلِهِمْ فَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُوا۟ وَلَيَعْلَمَنَّ ٱلْكَٰذِبِينَ', '9ae010357e2f977d42f6bf7d7db7c369cf413401df4b14ffe12fbb92f1135da4', '9ae010357e2f977d42f6bf7d7db7c369cf413401df4b14ffe12fbb92f1135da4', NULL, 'ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكذبين', 20, 40, 159, 1, 5, 396, false, NULL),
    (3344, 'tanzil-uthmani-v1.1', 29, 4, 'أَمْ حَسِبَ ٱلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسْبِقُونَا سَآءَ مَا يَحْكُمُونَ', '6a5619068984ba42b046918c951b1c7529154526426873a3ad8d793bcf10e30a', 'أَمْ حَسِبَ ٱلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسْبِقُونَا سَآءَ مَا يَحْكُمُونَ', '6a5619068984ba42b046918c951b1c7529154526426873a3ad8d793bcf10e30a', '6a5619068984ba42b046918c951b1c7529154526426873a3ad8d793bcf10e30a', NULL, 'ام حسب الذين يعملون السيات ان يسبقونا ساء ما يحكمون', 20, 40, 159, 1, 5, 396, false, NULL),
    (3345, 'tanzil-uthmani-v1.1', 29, 5, 'مَن كَانَ يَرْجُوا۟ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَـَٔاتٍ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'd7854d7199546ae52da6598896c8468fc50d296a5b4260afaff943d98aa6dc38', 'مَن كَانَ يَرْجُوا۟ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَـَٔاتٍ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'd7854d7199546ae52da6598896c8468fc50d296a5b4260afaff943d98aa6dc38', 'd7854d7199546ae52da6598896c8468fc50d296a5b4260afaff943d98aa6dc38', NULL, 'من كان يرجوا لقاء الله فان اجل الله لات وهو السميع العليم', 20, 40, 159, 1, 5, 396, false, NULL),
    (3346, 'tanzil-uthmani-v1.1', 29, 6, 'وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفْسِهِۦٓ إِنَّ ٱللَّهَ لَغَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', '18b16e3d02523dfcc0d052a6ef78f7043a06c0b0c39fe777724df5436fc4777e', 'وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفْسِهِۦٓ إِنَّ ٱللَّهَ لَغَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', '18b16e3d02523dfcc0d052a6ef78f7043a06c0b0c39fe777724df5436fc4777e', '18b16e3d02523dfcc0d052a6ef78f7043a06c0b0c39fe777724df5436fc4777e', NULL, 'ومن جهد فانما يجهد لنفسه ان الله لغني عن العلمين', 20, 40, 159, 1, 5, 396, false, NULL),
    (3347, 'tanzil-uthmani-v1.1', 29, 7, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَنَجْزِيَنَّهُمْ أَحْسَنَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', '97273e48a44600c79472dc88f743b1e477cd6ea30a4ea6595e8881931bc90107', 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَنَجْزِيَنَّهُمْ أَحْسَنَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', '97273e48a44600c79472dc88f743b1e477cd6ea30a4ea6595e8881931bc90107', '97273e48a44600c79472dc88f743b1e477cd6ea30a4ea6595e8881931bc90107', NULL, 'والذين ءامنوا وعملوا الصلحت لنكفرن عنهم سياتهم ولنجزينهم احسن الذي كانوا يعملون', 20, 40, 159, 1, 5, 397, false, NULL),
    (3348, 'tanzil-uthmani-v1.1', 29, 8, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حُسْنًا وَإِن جَٰهَدَاكَ لِتُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَآ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '199fc580dd3b053665c8d7c1f2136fa27afe2891d5f3a7584bc6d4059367cd15', 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حُسْنًا وَإِن جَٰهَدَاكَ لِتُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَآ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '199fc580dd3b053665c8d7c1f2136fa27afe2891d5f3a7584bc6d4059367cd15', '199fc580dd3b053665c8d7c1f2136fa27afe2891d5f3a7584bc6d4059367cd15', NULL, 'ووصينا الانسن بولديه حسنا وان جهداك لتشرك بي ما ليس لك به علم فلا تطعهما الي مرجعكم فانبئكم بما كنتم تعملون', 20, 40, 159, 1, 5, 397, false, NULL),
    (3349, 'tanzil-uthmani-v1.1', 29, 9, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُدْخِلَنَّهُمْ فِى ٱلصَّٰلِحِينَ', '39dbea53010cd8ea786d752965e0f4354777abc9173ff011424b6ba6b3136376', 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُدْخِلَنَّهُمْ فِى ٱلصَّٰلِحِينَ', '39dbea53010cd8ea786d752965e0f4354777abc9173ff011424b6ba6b3136376', '39dbea53010cd8ea786d752965e0f4354777abc9173ff011424b6ba6b3136376', NULL, 'والذين ءامنوا وعملوا الصلحت لندخلنهم في الصلحين', 20, 40, 159, 1, 5, 397, false, NULL),
    (3350, 'tanzil-uthmani-v1.1', 29, 10, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِىَ فِى ٱللَّهِ جَعَلَ فِتْنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِ وَلَئِن جَآءَ نَصْرٌ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمْ أَوَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِمَا فِى صُدُورِ ٱلْعَٰلَمِينَ', '34638eac68ee57c05e2baf90ebdc34ddaf79e9925932e025563a9cfc6dabc15e', 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِىَ فِى ٱللَّهِ جَعَلَ فِتْنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِ وَلَئِن جَآءَ نَصْرٌ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمْ أَوَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِمَا فِى صُدُورِ ٱلْعَٰلَمِينَ', '34638eac68ee57c05e2baf90ebdc34ddaf79e9925932e025563a9cfc6dabc15e', '34638eac68ee57c05e2baf90ebdc34ddaf79e9925932e025563a9cfc6dabc15e', NULL, 'ومن الناس من يقول ءامنا بالله فاذا اوذي في الله جعل فتنه الناس كعذاب الله ولئن جاء نصر من ربك ليقولن انا كنا معكم اوليس الله باعلم بما في صدور العلمين', 20, 40, 159, 1, 5, 397, false, NULL),
    (3351, 'tanzil-uthmani-v1.1', 29, 11, 'وَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَلَيَعْلَمَنَّ ٱلْمُنَٰفِقِينَ', '857e4384291b1821c6c358ad8b27aec039ad9adb248ab404942ff3200fe4e2db', 'وَلَيَعْلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَلَيَعْلَمَنَّ ٱلْمُنَٰفِقِينَ', '857e4384291b1821c6c358ad8b27aec039ad9adb248ab404942ff3200fe4e2db', '857e4384291b1821c6c358ad8b27aec039ad9adb248ab404942ff3200fe4e2db', NULL, 'وليعلمن الله الذين ءامنوا وليعلمن المنفقين', 20, 40, 159, 1, 5, 397, false, NULL),
    (3352, 'tanzil-uthmani-v1.1', 29, 12, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ ٱتَّبِعُوا۟ سَبِيلَنَا وَلْنَحْمِلْ خَطَٰيَٰكُمْ وَمَا هُم بِحَٰمِلِينَ مِنْ خَطَٰيَٰهُم مِّن شَىْءٍ إِنَّهُمْ لَكَٰذِبُونَ', 'b93966039cec3121fa4de02ae7034a785efd6461ad990602fb01d5daa70fa123', 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ ٱتَّبِعُوا۟ سَبِيلَنَا وَلْنَحْمِلْ خَطَٰيَٰكُمْ وَمَا هُم بِحَٰمِلِينَ مِنْ خَطَٰيَٰهُم مِّن شَىْءٍ إِنَّهُمْ لَكَٰذِبُونَ', 'b93966039cec3121fa4de02ae7034a785efd6461ad990602fb01d5daa70fa123', 'b93966039cec3121fa4de02ae7034a785efd6461ad990602fb01d5daa70fa123', NULL, 'وقال الذين كفروا للذين ءامنوا اتبعوا سبيلنا ولنحمل خطيكم وما هم بحملين من خطيهم من شيء انهم لكذبون', 20, 40, 159, 1, 5, 397, false, NULL),
    (3353, 'tanzil-uthmani-v1.1', 29, 13, 'وَلَيَحْمِلُنَّ أَثْقَالَهُمْ وَأَثْقَالًا مَّعَ أَثْقَالِهِمْ وَلَيُسْـَٔلُنَّ يَوْمَ ٱلْقِيَٰمَةِ عَمَّا كَانُوا۟ يَفْتَرُونَ', '625e193f0e92d9da0d148a100ff09a83c865dd58f8c7b5e77ee473ad6f96dd4d', 'وَلَيَحْمِلُنَّ أَثْقَالَهُمْ وَأَثْقَالًا مَّعَ أَثْقَالِهِمْ وَلَيُسْـَٔلُنَّ يَوْمَ ٱلْقِيَٰمَةِ عَمَّا كَانُوا۟ يَفْتَرُونَ', '625e193f0e92d9da0d148a100ff09a83c865dd58f8c7b5e77ee473ad6f96dd4d', '625e193f0e92d9da0d148a100ff09a83c865dd58f8c7b5e77ee473ad6f96dd4d', NULL, 'وليحملن اثقالهم واثقالا مع اثقالهم وليسلن يوم القيمه عما كانوا يفترون', 20, 40, 159, 1, 5, 397, false, NULL),
    (3354, 'tanzil-uthmani-v1.1', 29, 14, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمْ ظَٰلِمُونَ', '4284b485d5004d554b7fe102e58689419d99ac578968a2d067ef420fe5de94e5', 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمْ ظَٰلِمُونَ', '4284b485d5004d554b7fe102e58689419d99ac578968a2d067ef420fe5de94e5', '4284b485d5004d554b7fe102e58689419d99ac578968a2d067ef420fe5de94e5', NULL, 'ولقد ارسلنا نوحا الي قومه فلبث فيهم الف سنه الا خمسين عاما فاخذهم الطوفان وهم ظلمون', 20, 40, 159, 1, 5, 397, false, NULL),
    (3355, 'tanzil-uthmani-v1.1', 29, 15, 'فَأَنجَيْنَٰهُ وَأَصْحَٰبَ ٱلسَّفِينَةِ وَجَعَلْنَٰهَآ ءَايَةً لِّلْعَٰلَمِينَ', '4987d10b0038486046562a7e20d35e2d3f7d52b601da6a4dd2c55c98e614d606', 'فَأَنجَيْنَٰهُ وَأَصْحَٰبَ ٱلسَّفِينَةِ وَجَعَلْنَٰهَآ ءَايَةً لِّلْعَٰلَمِينَ', '4987d10b0038486046562a7e20d35e2d3f7d52b601da6a4dd2c55c98e614d606', '4987d10b0038486046562a7e20d35e2d3f7d52b601da6a4dd2c55c98e614d606', NULL, 'فانجينه واصحب السفينه وجعلنها ءايه للعلمين', 20, 40, 159, 1, 5, 398, false, NULL),
    (3356, 'tanzil-uthmani-v1.1', 29, 16, 'وَإِبْرَٰهِيمَ إِذْ قَالَ لِقَوْمِهِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '1e55fb63256a9fec66e0332ab365aff6b8b93822688e0bb9f143887043e5c2e0', 'وَإِبْرَٰهِيمَ إِذْ قَالَ لِقَوْمِهِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '1e55fb63256a9fec66e0332ab365aff6b8b93822688e0bb9f143887043e5c2e0', '1e55fb63256a9fec66e0332ab365aff6b8b93822688e0bb9f143887043e5c2e0', NULL, 'وابرهيم اذ قال لقومه اعبدوا الله واتقوه ذلكم خير لكم ان كنتم تعلمون', 20, 40, 159, 1, 5, 398, false, NULL),
    (3357, 'tanzil-uthmani-v1.1', 29, 17, 'إِنَّمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَوْثَٰنًا وَتَخْلُقُونَ إِفْكًا إِنَّ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمْلِكُونَ لَكُمْ رِزْقًا فَٱبْتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزْقَ وَٱعْبُدُوهُ وَٱشْكُرُوا۟ لَهُۥٓ إِلَيْهِ تُرْجَعُونَ', 'd43f7645b443414f65c5faae76b5607f8aa0b6c75c94b38659097b1b9d947459', 'إِنَّمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ أَوْثَٰنًا وَتَخْلُقُونَ إِفْكًا إِنَّ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ لَا يَمْلِكُونَ لَكُمْ رِزْقًا فَٱبْتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزْقَ وَٱعْبُدُوهُ وَٱشْكُرُوا۟ لَهُۥٓ إِلَيْهِ تُرْجَعُونَ', 'd43f7645b443414f65c5faae76b5607f8aa0b6c75c94b38659097b1b9d947459', 'd43f7645b443414f65c5faae76b5607f8aa0b6c75c94b38659097b1b9d947459', NULL, 'انما تعبدون من دون الله اوثنا وتخلقون افكا ان الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له اليه ترجعون', 20, 40, 159, 1, 5, 398, false, NULL),
    (3358, 'tanzil-uthmani-v1.1', 29, 18, 'وَإِن تُكَذِّبُوا۟ فَقَدْ كَذَّبَ أُمَمٌ مِّن قَبْلِكُمْ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', '358cb1566ecaeeb32e5f113230907d187e10884c6c990cc68ac5b255f35e1439', 'وَإِن تُكَذِّبُوا۟ فَقَدْ كَذَّبَ أُمَمٌ مِّن قَبْلِكُمْ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', '358cb1566ecaeeb32e5f113230907d187e10884c6c990cc68ac5b255f35e1439', '358cb1566ecaeeb32e5f113230907d187e10884c6c990cc68ac5b255f35e1439', NULL, 'وان تكذبوا فقد كذب امم من قبلكم وما علي الرسول الا البلغ المبين', 20, 40, 159, 1, 5, 398, false, NULL),
    (3359, 'tanzil-uthmani-v1.1', 29, 19, 'أَوَلَمْ يَرَوْا۟ كَيْفَ يُبْدِئُ ٱللَّهُ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥٓ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'c678d09065d5d52325f683855bf107a6e3601d65a68a0e4207d7edc45369cca3', 'أَوَلَمْ يَرَوْا۟ كَيْفَ يُبْدِئُ ٱللَّهُ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥٓ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 'c678d09065d5d52325f683855bf107a6e3601d65a68a0e4207d7edc45369cca3', 'c678d09065d5d52325f683855bf107a6e3601d65a68a0e4207d7edc45369cca3', NULL, 'اولم يروا كيف يبدئ الله الخلق ثم يعيده ان ذلك علي الله يسير', 20, 40, 159, 1, 5, 398, false, NULL),
    (3360, 'tanzil-uthmani-v1.1', 29, 20, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ بَدَأَ ٱلْخَلْقَ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشْأَةَ ٱلْـَٔاخِرَةَ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '041797f1886b6f9819a0cc5347a15abc94eb889546979443310253d601958309', 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ بَدَأَ ٱلْخَلْقَ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشْأَةَ ٱلْـَٔاخِرَةَ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '041797f1886b6f9819a0cc5347a15abc94eb889546979443310253d601958309', '041797f1886b6f9819a0cc5347a15abc94eb889546979443310253d601958309', NULL, 'قل سيروا في الارض فانظروا كيف بدا الخلق ثم الله ينشئ النشاه الاخره ان الله علي كل شيء قدير', 20, 40, 159, 1, 5, 398, false, NULL),
    (3361, 'tanzil-uthmani-v1.1', 29, 21, 'يُعَذِّبُ مَن يَشَآءُ وَيَرْحَمُ مَن يَشَآءُ وَإِلَيْهِ تُقْلَبُونَ', 'ae2fee76900751d2d33997a0b18d5ea77a5e9fb18ffe6fde7e3a8c7fa634adc2', 'يُعَذِّبُ مَن يَشَآءُ وَيَرْحَمُ مَن يَشَآءُ وَإِلَيْهِ تُقْلَبُونَ', 'ae2fee76900751d2d33997a0b18d5ea77a5e9fb18ffe6fde7e3a8c7fa634adc2', 'ae2fee76900751d2d33997a0b18d5ea77a5e9fb18ffe6fde7e3a8c7fa634adc2', NULL, 'يعذب من يشاء ويرحم من يشاء واليه تقلبون', 20, 40, 159, 1, 5, 398, false, NULL),
    (3362, 'tanzil-uthmani-v1.1', 29, 22, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '53019717dbe31527c7786cec7f0360747ce38ca681fbd99097bdb599bcd4f198', 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', '53019717dbe31527c7786cec7f0360747ce38ca681fbd99097bdb599bcd4f198', '53019717dbe31527c7786cec7f0360747ce38ca681fbd99097bdb599bcd4f198', NULL, 'وما انتم بمعجزين في الارض ولا في السماء وما لكم من دون الله من ولي ولا نصير', 20, 40, 159, 1, 5, 398, false, NULL),
    (3363, 'tanzil-uthmani-v1.1', 29, 23, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُو۟لَٰٓئِكَ يَئِسُوا۟ مِن رَّحْمَتِى وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', '0216f36638c9a7d0a3454b3fd850ed693b53d762a98ba2482dc2086348b02747', 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُو۟لَٰٓئِكَ يَئِسُوا۟ مِن رَّحْمَتِى وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', '0216f36638c9a7d0a3454b3fd850ed693b53d762a98ba2482dc2086348b02747', '0216f36638c9a7d0a3454b3fd850ed693b53d762a98ba2482dc2086348b02747', NULL, 'والذين كفروا بايت الله ولقائه اولئك يئسوا من رحمتي واولئك لهم عذاب اليم', 20, 40, 159, 1, 5, 398, false, NULL),
    (3364, 'tanzil-uthmani-v1.1', 29, 24, 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱقْتُلُوهُ أَوْ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '835148c14ea943b1ebb54f35ac190b122bff09e84e7bb9d5f2d3f03f5c1254bf', 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱقْتُلُوهُ أَوْ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', '835148c14ea943b1ebb54f35ac190b122bff09e84e7bb9d5f2d3f03f5c1254bf', '835148c14ea943b1ebb54f35ac190b122bff09e84e7bb9d5f2d3f03f5c1254bf', NULL, 'فما كان جواب قومه الا ان قالوا اقتلوه او حرقوه فانجيه الله من النار ان في ذلك لايت لقوم يؤمنون', 20, 40, 159, 1, 5, 399, false, NULL),
    (3365, 'tanzil-uthmani-v1.1', 29, 25, 'وَقَالَ إِنَّمَا ٱتَّخَذْتُم مِّن دُونِ ٱللَّهِ أَوْثَٰنًا مَّوَدَّةَ بَيْنِكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُ بَعْضُكُم بِبَعْضٍ وَيَلْعَنُ بَعْضُكُم بَعْضًا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', '7cb12ac2aaefd4fa914dd1f886b3302629291ffc21664dc1369e912db8e7b3fb', 'وَقَالَ إِنَّمَا ٱتَّخَذْتُم مِّن دُونِ ٱللَّهِ أَوْثَٰنًا مَّوَدَّةَ بَيْنِكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُ بَعْضُكُم بِبَعْضٍ وَيَلْعَنُ بَعْضُكُم بَعْضًا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', '7cb12ac2aaefd4fa914dd1f886b3302629291ffc21664dc1369e912db8e7b3fb', '7cb12ac2aaefd4fa914dd1f886b3302629291ffc21664dc1369e912db8e7b3fb', NULL, 'وقال انما اتخذتم من دون الله اوثنا موده بينكم في الحيوه الدنيا ثم يوم القيمه يكفر بعضكم ببعض ويلعن بعضكم بعضا وماويكم النار وما لكم من نصرين', 20, 40, 159, 1, 5, 399, false, NULL),
    (3366, 'tanzil-uthmani-v1.1', 29, 26, 'فَـَٔامَنَ لَهُۥ لُوطٌ وَقَالَ إِنِّى مُهَاجِرٌ إِلَىٰ رَبِّىٓ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '0e71f8f8a9236a5bee178c73013a75e46ad8bb7af4b46cf0a2e0319ec038d046', 'فَـَٔامَنَ لَهُۥ لُوطٌ وَقَالَ إِنِّى مُهَاجِرٌ إِلَىٰ رَبِّىٓ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '0e71f8f8a9236a5bee178c73013a75e46ad8bb7af4b46cf0a2e0319ec038d046', '0e71f8f8a9236a5bee178c73013a75e46ad8bb7af4b46cf0a2e0319ec038d046', NULL, 'فامن له لوط وقال اني مهاجر الي ربي انه هو العزيز الحكيم', 20, 40, 160, 1, 5, 399, false, NULL),
    (3367, 'tanzil-uthmani-v1.1', 29, 27, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَجَعَلْنَا فِى ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ وَءَاتَيْنَٰهُ أَجْرَهُۥ فِى ٱلدُّنْيَا وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'd88f41ccb3866219ef10b1f6cfc68a7a38a1f2bc01e2f7dee2a238ad7f2e2d58', 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَجَعَلْنَا فِى ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ وَءَاتَيْنَٰهُ أَجْرَهُۥ فِى ٱلدُّنْيَا وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 'd88f41ccb3866219ef10b1f6cfc68a7a38a1f2bc01e2f7dee2a238ad7f2e2d58', 'd88f41ccb3866219ef10b1f6cfc68a7a38a1f2bc01e2f7dee2a238ad7f2e2d58', NULL, 'ووهبنا له اسحق ويعقوب وجعلنا في ذريته النبوه والكتب وءاتينه اجره في الدنيا وانه في الاخره لمن الصلحين', 20, 40, 160, 1, 5, 399, false, NULL),
    (3368, 'tanzil-uthmani-v1.1', 29, 28, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ إِنَّكُمْ لَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَٰلَمِينَ', '045758ccdd003bec476d1d7b09a8c14e017a02a49510f9984e6dcccaa36267ed', 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ إِنَّكُمْ لَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَٰلَمِينَ', '045758ccdd003bec476d1d7b09a8c14e017a02a49510f9984e6dcccaa36267ed', '045758ccdd003bec476d1d7b09a8c14e017a02a49510f9984e6dcccaa36267ed', NULL, 'ولوطا اذ قال لقومه انكم لتاتون الفحشه ما سبقكم بها من احد من العلمين', 20, 40, 160, 1, 5, 399, false, NULL),
    (3369, 'tanzil-uthmani-v1.1', 29, 29, 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ وَتَقْطَعُونَ ٱلسَّبِيلَ وَتَأْتُونَ فِى نَادِيكُمُ ٱلْمُنكَرَ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱئْتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', '8a267abe68b5e8981ceaa1cef9005146de34a8cac5f23caee742476b7f9f9176', 'أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ وَتَقْطَعُونَ ٱلسَّبِيلَ وَتَأْتُونَ فِى نَادِيكُمُ ٱلْمُنكَرَ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا۟ ٱئْتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', '8a267abe68b5e8981ceaa1cef9005146de34a8cac5f23caee742476b7f9f9176', '8a267abe68b5e8981ceaa1cef9005146de34a8cac5f23caee742476b7f9f9176', NULL, 'ائنكم لتاتون الرجال وتقطعون السبيل وتاتون في ناديكم المنكر فما كان جواب قومه الا ان قالوا ائتنا بعذاب الله ان كنت من الصدقين', 20, 40, 160, 1, 5, 399, false, NULL),
    (3370, 'tanzil-uthmani-v1.1', 29, 30, 'قَالَ رَبِّ ٱنصُرْنِى عَلَى ٱلْقَوْمِ ٱلْمُفْسِدِينَ', 'da765c3ffca0c8c00786a7d08fec04aa1c34d9a2f0e7418f8dd364a97ba0c533', 'قَالَ رَبِّ ٱنصُرْنِى عَلَى ٱلْقَوْمِ ٱلْمُفْسِدِينَ', 'da765c3ffca0c8c00786a7d08fec04aa1c34d9a2f0e7418f8dd364a97ba0c533', 'da765c3ffca0c8c00786a7d08fec04aa1c34d9a2f0e7418f8dd364a97ba0c533', NULL, 'قال رب انصرني علي القوم المفسدين', 20, 40, 160, 1, 5, 399, false, NULL),
    (3371, 'tanzil-uthmani-v1.1', 29, 31, 'وَلَمَّا جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوٓا۟ إِنَّا مُهْلِكُوٓا۟ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ إِنَّ أَهْلَهَا كَانُوا۟ ظَٰلِمِينَ', '722a8c7d0988b4a336277184661de96dcbea5152119db902b5ecfde38e314583', 'وَلَمَّا جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوٓا۟ إِنَّا مُهْلِكُوٓا۟ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ إِنَّ أَهْلَهَا كَانُوا۟ ظَٰلِمِينَ', '722a8c7d0988b4a336277184661de96dcbea5152119db902b5ecfde38e314583', '722a8c7d0988b4a336277184661de96dcbea5152119db902b5ecfde38e314583', NULL, 'ولما جاءت رسلنا ابرهيم بالبشري قالوا انا مهلكوا اهل هذه القريه ان اهلها كانوا ظلمين', 20, 40, 160, 1, 5, 400, false, NULL),
    (3372, 'tanzil-uthmani-v1.1', 29, 32, 'قَالَ إِنَّ فِيهَا لُوطًا قَالُوا۟ نَحْنُ أَعْلَمُ بِمَن فِيهَا لَنُنَجِّيَنَّهُۥ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', '1d6939d21f1c6a66eca1a5de308e4884efc954ca44733955ab066b76ce14a457', 'قَالَ إِنَّ فِيهَا لُوطًا قَالُوا۟ نَحْنُ أَعْلَمُ بِمَن فِيهَا لَنُنَجِّيَنَّهُۥ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', '1d6939d21f1c6a66eca1a5de308e4884efc954ca44733955ab066b76ce14a457', '1d6939d21f1c6a66eca1a5de308e4884efc954ca44733955ab066b76ce14a457', NULL, 'قال ان فيها لوطا قالوا نحن اعلم بمن فيها لننجينه واهله الا امراته كانت من الغبرين', 20, 40, 160, 1, 5, 400, false, NULL),
    (3373, 'tanzil-uthmani-v1.1', 29, 33, 'وَلَمَّآ أَن جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالُوا۟ لَا تَخَفْ وَلَا تَحْزَنْ إِنَّا مُنَجُّوكَ وَأَهْلَكَ إِلَّا ٱمْرَأَتَكَ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', '5d500a79b00cdc4a761e2d0541716d5a7a209105a2a0a4987fa3f6b261c95c46', 'وَلَمَّآ أَن جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالُوا۟ لَا تَخَفْ وَلَا تَحْزَنْ إِنَّا مُنَجُّوكَ وَأَهْلَكَ إِلَّا ٱمْرَأَتَكَ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', '5d500a79b00cdc4a761e2d0541716d5a7a209105a2a0a4987fa3f6b261c95c46', '5d500a79b00cdc4a761e2d0541716d5a7a209105a2a0a4987fa3f6b261c95c46', NULL, 'ولما ان جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقالوا لا تخف ولا تحزن انا منجوك واهلك الا امراتك كانت من الغبرين', 20, 40, 160, 1, 5, 400, false, NULL),
    (3374, 'tanzil-uthmani-v1.1', 29, 34, 'إِنَّا مُنزِلُونَ عَلَىٰٓ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', 'a8f535c77482235aab3a721731656f532914827a9d1d2408a99fb60b7ca968c7', 'إِنَّا مُنزِلُونَ عَلَىٰٓ أَهْلِ هَٰذِهِ ٱلْقَرْيَةِ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', 'a8f535c77482235aab3a721731656f532914827a9d1d2408a99fb60b7ca968c7', 'a8f535c77482235aab3a721731656f532914827a9d1d2408a99fb60b7ca968c7', NULL, 'انا منزلون علي اهل هذه القريه رجزا من السماء بما كانوا يفسقون', 20, 40, 160, 1, 5, 400, false, NULL),
    (3375, 'tanzil-uthmani-v1.1', 29, 35, 'وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةًۢ بَيِّنَةً لِّقَوْمٍ يَعْقِلُونَ', '5131e741b22e02e47887d1f44696ac074080cd26bdef414ed5e779a0569d7c94', 'وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةًۢ بَيِّنَةً لِّقَوْمٍ يَعْقِلُونَ', '5131e741b22e02e47887d1f44696ac074080cd26bdef414ed5e779a0569d7c94', '5131e741b22e02e47887d1f44696ac074080cd26bdef414ed5e779a0569d7c94', NULL, 'ولقد تركنا منها ءايه بينه لقوم يعقلون', 20, 40, 160, 1, 5, 400, false, NULL),
    (3376, 'tanzil-uthmani-v1.1', 29, 36, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ وَٱرْجُوا۟ ٱلْيَوْمَ ٱلْـَٔاخِرَ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '7150a9a1bbe709f627dc92b8a53b6f8f587d9900702e25f2fcfed28cbf4896d7', 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ وَٱرْجُوا۟ ٱلْيَوْمَ ٱلْـَٔاخِرَ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', '7150a9a1bbe709f627dc92b8a53b6f8f587d9900702e25f2fcfed28cbf4896d7', '7150a9a1bbe709f627dc92b8a53b6f8f587d9900702e25f2fcfed28cbf4896d7', NULL, 'والي مدين اخاهم شعيبا فقال يقوم اعبدوا الله وارجوا اليوم الاخر ولا تعثوا في الارض مفسدين', 20, 40, 160, 1, 5, 400, false, NULL),
    (3377, 'tanzil-uthmani-v1.1', 29, 37, 'فَكَذَّبُوهُ فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'e161f58c0f1a5e5c17e9923f105ddc305af5ac9e0c50b53fac25b187d347f068', 'فَكَذَّبُوهُ فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 'e161f58c0f1a5e5c17e9923f105ddc305af5ac9e0c50b53fac25b187d347f068', 'e161f58c0f1a5e5c17e9923f105ddc305af5ac9e0c50b53fac25b187d347f068', NULL, 'فكذبوه فاخذتهم الرجفه فاصبحوا في دارهم جثمين', 20, 40, 160, 1, 5, 400, false, NULL),
    (3378, 'tanzil-uthmani-v1.1', 29, 38, 'وَعَادًا وَثَمُودَا۟ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ', 'c6444bb29009ffe6dd8d551805bed84b2e20a0a8efa8ec198e4151d01fcdc544', 'وَعَادًا وَثَمُودَا۟ وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ وَكَانُوا۟ مُسْتَبْصِرِينَ', 'c6444bb29009ffe6dd8d551805bed84b2e20a0a8efa8ec198e4151d01fcdc544', 'c6444bb29009ffe6dd8d551805bed84b2e20a0a8efa8ec198e4151d01fcdc544', NULL, 'وعادا وثمودا وقد تبين لكم من مسكنهم وزين لهم الشيطن اعملهم فصدهم عن السبيل وكانوا مستبصرين', 20, 40, 160, 1, 5, 400, false, NULL),
    (3379, 'tanzil-uthmani-v1.1', 29, 39, 'وَقَٰرُونَ وَفِرْعَوْنَ وَهَٰمَٰنَ وَلَقَدْ جَآءَهُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ وَمَا كَانُوا۟ سَٰبِقِينَ', 'a6d4b09de11dd1625b811326648656b1b8f64792acaf7a24e433381c0031f9a3', 'وَقَٰرُونَ وَفِرْعَوْنَ وَهَٰمَٰنَ وَلَقَدْ جَآءَهُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ وَمَا كَانُوا۟ سَٰبِقِينَ', 'a6d4b09de11dd1625b811326648656b1b8f64792acaf7a24e433381c0031f9a3', 'a6d4b09de11dd1625b811326648656b1b8f64792acaf7a24e433381c0031f9a3', NULL, 'وقرون وفرعون وهمن ولقد جاءهم موسي بالبينت فاستكبروا في الارض وما كانوا سبقين', 20, 40, 160, 1, 5, 401, false, NULL),
    (3380, 'tanzil-uthmani-v1.1', 29, 40, 'فَكُلًّا أَخَذْنَا بِذَنۢبِهِۦ فَمِنْهُم مَّنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا وَمِنْهُم مَّنْ أَخَذَتْهُ ٱلصَّيْحَةُ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ ٱلْأَرْضَ وَمِنْهُم مَّنْ أَغْرَقْنَا وَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'a4479175fea862b80b33e64c19cca1c2f3ea0a645e2da8c26121ff1b1a4c5962', 'فَكُلًّا أَخَذْنَا بِذَنۢبِهِۦ فَمِنْهُم مَّنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا وَمِنْهُم مَّنْ أَخَذَتْهُ ٱلصَّيْحَةُ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ ٱلْأَرْضَ وَمِنْهُم مَّنْ أَغْرَقْنَا وَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 'a4479175fea862b80b33e64c19cca1c2f3ea0a645e2da8c26121ff1b1a4c5962', 'a4479175fea862b80b33e64c19cca1c2f3ea0a645e2da8c26121ff1b1a4c5962', NULL, 'فكلا اخذنا بذنبه فمنهم من ارسلنا عليه حاصبا ومنهم من اخذته الصيحه ومنهم من خسفنا به الارض ومنهم من اغرقنا وما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون', 20, 40, 160, 1, 5, 401, false, NULL),
    (3381, 'tanzil-uthmani-v1.1', 29, 41, 'مَثَلُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ كَمَثَلِ ٱلْعَنكَبُوتِ ٱتَّخَذَتْ بَيْتًا وَإِنَّ أَوْهَنَ ٱلْبُيُوتِ لَبَيْتُ ٱلْعَنكَبُوتِ لَوْ كَانُوا۟ يَعْلَمُونَ', 'e509faa004e2132f66a399cc7c6537079827b9b4cc0982af8c5d4b9331ca5ada', 'مَثَلُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ كَمَثَلِ ٱلْعَنكَبُوتِ ٱتَّخَذَتْ بَيْتًا وَإِنَّ أَوْهَنَ ٱلْبُيُوتِ لَبَيْتُ ٱلْعَنكَبُوتِ لَوْ كَانُوا۟ يَعْلَمُونَ', 'e509faa004e2132f66a399cc7c6537079827b9b4cc0982af8c5d4b9331ca5ada', 'e509faa004e2132f66a399cc7c6537079827b9b4cc0982af8c5d4b9331ca5ada', NULL, 'مثل الذين اتخذوا من دون الله اولياء كمثل العنكبوت اتخذت بيتا وان اوهن البيوت لبيت العنكبوت لو كانوا يعلمون', 20, 40, 160, 1, 5, 401, false, NULL),
    (3382, 'tanzil-uthmani-v1.1', 29, 42, 'إِنَّ ٱللَّهَ يَعْلَمُ مَا يَدْعُونَ مِن دُونِهِۦ مِن شَىْءٍ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '8a3c54401d12ff50abbc42b860d1a19d76e1e2661ec2170bf11b5b9e0774c7ba', 'إِنَّ ٱللَّهَ يَعْلَمُ مَا يَدْعُونَ مِن دُونِهِۦ مِن شَىْءٍ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '8a3c54401d12ff50abbc42b860d1a19d76e1e2661ec2170bf11b5b9e0774c7ba', '8a3c54401d12ff50abbc42b860d1a19d76e1e2661ec2170bf11b5b9e0774c7ba', NULL, 'ان الله يعلم ما يدعون من دونه من شيء وهو العزيز الحكيم', 20, 40, 160, 1, 5, 401, false, NULL),
    (3383, 'tanzil-uthmani-v1.1', 29, 43, 'وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ وَمَا يَعْقِلُهَآ إِلَّا ٱلْعَٰلِمُونَ', 'f26c35498ce52cc4bfa42fc8f368cb0b630087a8eeeb3534556e65a70a0226bf', 'وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ وَمَا يَعْقِلُهَآ إِلَّا ٱلْعَٰلِمُونَ', 'f26c35498ce52cc4bfa42fc8f368cb0b630087a8eeeb3534556e65a70a0226bf', 'f26c35498ce52cc4bfa42fc8f368cb0b630087a8eeeb3534556e65a70a0226bf', NULL, 'وتلك الامثل نضربها للناس وما يعقلها الا العلمون', 20, 40, 160, 1, 5, 401, false, NULL),
    (3384, 'tanzil-uthmani-v1.1', 29, 44, 'خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّلْمُؤْمِنِينَ', '06f8710daa99a6c2e77588b7a8608c17826bb8ce4e0663a34736b28a0afcd75b', 'خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّلْمُؤْمِنِينَ', '06f8710daa99a6c2e77588b7a8608c17826bb8ce4e0663a34736b28a0afcd75b', '06f8710daa99a6c2e77588b7a8608c17826bb8ce4e0663a34736b28a0afcd75b', NULL, 'خلق الله السموت والارض بالحق ان في ذلك لايه للمؤمنين', 20, 40, 160, 1, 5, 401, false, NULL),
    (3385, 'tanzil-uthmani-v1.1', 29, 45, 'ٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِنَ ٱلْكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَ إِنَّ ٱلصَّلَوٰةَ تَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَلَذِكْرُ ٱللَّهِ أَكْبَرُ وَٱللَّهُ يَعْلَمُ مَا تَصْنَعُونَ', '299a128f557da8e3fd2a61bef334d8dacccea2caab6ba7713b76ff967aac562c', 'ٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِنَ ٱلْكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَ إِنَّ ٱلصَّلَوٰةَ تَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَلَذِكْرُ ٱللَّهِ أَكْبَرُ وَٱللَّهُ يَعْلَمُ مَا تَصْنَعُونَ', '299a128f557da8e3fd2a61bef334d8dacccea2caab6ba7713b76ff967aac562c', '299a128f557da8e3fd2a61bef334d8dacccea2caab6ba7713b76ff967aac562c', NULL, 'اتل ما اوحي اليك من الكتب واقم الصلوه ان الصلوه تنهي عن الفحشاء والمنكر ولذكر الله اكبر والله يعلم ما تصنعون', 20, 40, 160, 1, 5, 401, false, NULL),
    (3386, 'tanzil-uthmani-v1.1', 29, 46, 'وَلَا تُجَٰدِلُوٓا۟ أَهْلَ ٱلْكِتَٰبِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ وَقُولُوٓا۟ ءَامَنَّا بِٱلَّذِىٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَٰهُنَا وَإِلَٰهُكُمْ وَٰحِدٌ وَنَحْنُ لَهُۥ مُسْلِمُونَ', '91cd285480f1696d28a44320f8a60dcd4bc879adb0bd471e7c20103abdbb8c32', 'وَلَا تُجَٰدِلُوٓا۟ أَهْلَ ٱلْكِتَٰبِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ وَقُولُوٓا۟ ءَامَنَّا بِٱلَّذِىٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَٰهُنَا وَإِلَٰهُكُمْ وَٰحِدٌ وَنَحْنُ لَهُۥ مُسْلِمُونَ', '91cd285480f1696d28a44320f8a60dcd4bc879adb0bd471e7c20103abdbb8c32', '91cd285480f1696d28a44320f8a60dcd4bc879adb0bd471e7c20103abdbb8c32', NULL, 'ولا تجدلوا اهل الكتب الا بالتي هي احسن الا الذين ظلموا منهم وقولوا ءامنا بالذي انزل الينا وانزل اليكم والهنا والهكم وحد ونحن له مسلمون', 21, 41, 161, 1, 5, 402, false, NULL),
    (3387, 'tanzil-uthmani-v1.1', 29, 47, 'وَكَذَٰلِكَ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ فَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يُؤْمِنُونَ بِهِۦ وَمِنْ هَٰٓؤُلَآءِ مَن يُؤْمِنُ بِهِۦ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلْكَٰفِرُونَ', '0338d6d1119681290b09c97735b72ab84945a190eade10a9ff3be104da971a13', 'وَكَذَٰلِكَ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ فَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يُؤْمِنُونَ بِهِۦ وَمِنْ هَٰٓؤُلَآءِ مَن يُؤْمِنُ بِهِۦ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلْكَٰفِرُونَ', '0338d6d1119681290b09c97735b72ab84945a190eade10a9ff3be104da971a13', '0338d6d1119681290b09c97735b72ab84945a190eade10a9ff3be104da971a13', NULL, 'وكذلك انزلنا اليك الكتب فالذين ءاتينهم الكتب يؤمنون به ومن هؤلاء من يؤمن به وما يجحد بايتنا الا الكفرون', 21, 41, 161, 1, 5, 402, false, NULL),
    (3388, 'tanzil-uthmani-v1.1', 29, 48, 'وَمَا كُنتَ تَتْلُوا۟ مِن قَبْلِهِۦ مِن كِتَٰبٍ وَلَا تَخُطُّهُۥ بِيَمِينِكَ إِذًا لَّٱرْتَابَ ٱلْمُبْطِلُونَ', '4a8b7c4c47195e2e81e59be81cfbe374a77ebe4146a1ed32cb1edffe7bc18979', 'وَمَا كُنتَ تَتْلُوا۟ مِن قَبْلِهِۦ مِن كِتَٰبٍ وَلَا تَخُطُّهُۥ بِيَمِينِكَ إِذًا لَّٱرْتَابَ ٱلْمُبْطِلُونَ', '4a8b7c4c47195e2e81e59be81cfbe374a77ebe4146a1ed32cb1edffe7bc18979', '4a8b7c4c47195e2e81e59be81cfbe374a77ebe4146a1ed32cb1edffe7bc18979', NULL, 'وما كنت تتلوا من قبله من كتب ولا تخطه بيمينك اذا لارتاب المبطلون', 21, 41, 161, 1, 5, 402, false, NULL),
    (3389, 'tanzil-uthmani-v1.1', 29, 49, 'بَلْ هُوَ ءَايَٰتٌۢ بَيِّنَٰتٌ فِى صُدُورِ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ', 'b92bd73784376e8a83044cb251ac4dfd9605b48412c62abb1f1ec81992b2fb55', 'بَلْ هُوَ ءَايَٰتٌۢ بَيِّنَٰتٌ فِى صُدُورِ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ', 'b92bd73784376e8a83044cb251ac4dfd9605b48412c62abb1f1ec81992b2fb55', 'b92bd73784376e8a83044cb251ac4dfd9605b48412c62abb1f1ec81992b2fb55', NULL, 'بل هو ءايت بينت في صدور الذين اوتوا العلم وما يجحد بايتنا الا الظلمون', 21, 41, 161, 1, 5, 402, false, NULL),
    (3390, 'tanzil-uthmani-v1.1', 29, 50, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَٰتٌ مِّن رَّبِّهِۦ قُلْ إِنَّمَا ٱلْـَٔايَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'b46ef53a0b3265988dd281c3058931d83ea0f923d8208048549e07a3edd5961c', 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَٰتٌ مِّن رَّبِّهِۦ قُلْ إِنَّمَا ٱلْـَٔايَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'b46ef53a0b3265988dd281c3058931d83ea0f923d8208048549e07a3edd5961c', 'b46ef53a0b3265988dd281c3058931d83ea0f923d8208048549e07a3edd5961c', NULL, 'وقالوا لولا انزل عليه ءايت من ربه قل انما الايت عند الله وانما انا نذير مبين', 21, 41, 161, 1, 5, 402, false, NULL),
    (3391, 'tanzil-uthmani-v1.1', 29, 51, 'أَوَلَمْ يَكْفِهِمْ أَنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ يُتْلَىٰ عَلَيْهِمْ إِنَّ فِى ذَٰلِكَ لَرَحْمَةً وَذِكْرَىٰ لِقَوْمٍ يُؤْمِنُونَ', '64b64ebcec19022d97b5a3ff66740af9fb1e58e933d7dea832314470bdfffe69', 'أَوَلَمْ يَكْفِهِمْ أَنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ يُتْلَىٰ عَلَيْهِمْ إِنَّ فِى ذَٰلِكَ لَرَحْمَةً وَذِكْرَىٰ لِقَوْمٍ يُؤْمِنُونَ', '64b64ebcec19022d97b5a3ff66740af9fb1e58e933d7dea832314470bdfffe69', '64b64ebcec19022d97b5a3ff66740af9fb1e58e933d7dea832314470bdfffe69', NULL, 'اولم يكفهم انا انزلنا عليك الكتب يتلي عليهم ان في ذلك لرحمه وذكري لقوم يؤمنون', 21, 41, 161, 1, 5, 402, false, NULL),
    (3392, 'tanzil-uthmani-v1.1', 29, 52, 'قُلْ كَفَىٰ بِٱللَّهِ بَيْنِى وَبَيْنَكُمْ شَهِيدًا يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلَّذِينَ ءَامَنُوا۟ بِٱلْبَٰطِلِ وَكَفَرُوا۟ بِٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '60aa7eee8adf17fba6977cdc547e97f6025c017224b8f134d480d494d5debcdd', 'قُلْ كَفَىٰ بِٱللَّهِ بَيْنِى وَبَيْنَكُمْ شَهِيدًا يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلَّذِينَ ءَامَنُوا۟ بِٱلْبَٰطِلِ وَكَفَرُوا۟ بِٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '60aa7eee8adf17fba6977cdc547e97f6025c017224b8f134d480d494d5debcdd', '60aa7eee8adf17fba6977cdc547e97f6025c017224b8f134d480d494d5debcdd', NULL, 'قل كفي بالله بيني وبينكم شهيدا يعلم ما في السموت والارض والذين ءامنوا بالبطل وكفروا بالله اولئك هم الخسرون', 21, 41, 161, 1, 5, 402, false, NULL),
    (3393, 'tanzil-uthmani-v1.1', 29, 53, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَوْلَآ أَجَلٌ مُّسَمًّى لَّجَآءَهُمُ ٱلْعَذَابُ وَلَيَأْتِيَنَّهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'c279ed597ce576731bc69d1aca32fad65d0e62c88a065a4d395faa55ff1d125d', 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَوْلَآ أَجَلٌ مُّسَمًّى لَّجَآءَهُمُ ٱلْعَذَابُ وَلَيَأْتِيَنَّهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', 'c279ed597ce576731bc69d1aca32fad65d0e62c88a065a4d395faa55ff1d125d', 'c279ed597ce576731bc69d1aca32fad65d0e62c88a065a4d395faa55ff1d125d', NULL, 'ويستعجلونك بالعذاب ولولا اجل مسمي لجاءهم العذاب ولياتينهم بغته وهم لا يشعرون', 21, 41, 161, 1, 5, 403, false, NULL),
    (3394, 'tanzil-uthmani-v1.1', 29, 54, 'يَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', 'c7b9bec8a2ec095fcaf2db05cb6948dcf6cb406e72cb3fb9fcb65ed4ff4983f4', 'يَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', 'c7b9bec8a2ec095fcaf2db05cb6948dcf6cb406e72cb3fb9fcb65ed4ff4983f4', 'c7b9bec8a2ec095fcaf2db05cb6948dcf6cb406e72cb3fb9fcb65ed4ff4983f4', NULL, 'يستعجلونك بالعذاب وان جهنم لمحيطه بالكفرين', 21, 41, 161, 1, 5, 403, false, NULL),
    (3395, 'tanzil-uthmani-v1.1', 29, 55, 'يَوْمَ يَغْشَىٰهُمُ ٱلْعَذَابُ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُوا۟ مَا كُنتُمْ تَعْمَلُونَ', 'c3943e2810a853c9128c2ee334ae904ea2949dbc9ce9cd29c0c52036e43be4a7', 'يَوْمَ يَغْشَىٰهُمُ ٱلْعَذَابُ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُوا۟ مَا كُنتُمْ تَعْمَلُونَ', 'c3943e2810a853c9128c2ee334ae904ea2949dbc9ce9cd29c0c52036e43be4a7', 'c3943e2810a853c9128c2ee334ae904ea2949dbc9ce9cd29c0c52036e43be4a7', NULL, 'يوم يغشيهم العذاب من فوقهم ومن تحت ارجلهم ويقول ذوقوا ما كنتم تعملون', 21, 41, 161, 1, 5, 403, false, NULL),
    (3396, 'tanzil-uthmani-v1.1', 29, 56, 'يَٰعِبَادِىَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ أَرْضِى وَٰسِعَةٌ فَإِيَّٰىَ فَٱعْبُدُونِ', '85729002c8c3080e2a7da4910d48f1a535ab8d0afdf9be7248a90bff2106737a', 'يَٰعِبَادِىَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ أَرْضِى وَٰسِعَةٌ فَإِيَّٰىَ فَٱعْبُدُونِ', '85729002c8c3080e2a7da4910d48f1a535ab8d0afdf9be7248a90bff2106737a', '85729002c8c3080e2a7da4910d48f1a535ab8d0afdf9be7248a90bff2106737a', NULL, 'يعبادي الذين ءامنوا ان ارضي وسعه فايي فاعبدون', 21, 41, 161, 1, 5, 403, false, NULL),
    (3397, 'tanzil-uthmani-v1.1', 29, 57, 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ثُمَّ إِلَيْنَا تُرْجَعُونَ', '589f4bfd8c78daa6f2d985292c2e3b684255e9d44863cd5e5be884e4fb4aee04', 'كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ثُمَّ إِلَيْنَا تُرْجَعُونَ', '589f4bfd8c78daa6f2d985292c2e3b684255e9d44863cd5e5be884e4fb4aee04', '589f4bfd8c78daa6f2d985292c2e3b684255e9d44863cd5e5be884e4fb4aee04', NULL, 'كل نفس ذائقه الموت ثم الينا ترجعون', 21, 41, 161, 1, 5, 403, false, NULL),
    (3398, 'tanzil-uthmani-v1.1', 29, 58, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلْجَنَّةِ غُرَفًا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', '6a9b0bad2594af161c0ecea45d396d86e7546461540111f169469d93b655ffcc', 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلْجَنَّةِ غُرَفًا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', '6a9b0bad2594af161c0ecea45d396d86e7546461540111f169469d93b655ffcc', '6a9b0bad2594af161c0ecea45d396d86e7546461540111f169469d93b655ffcc', NULL, 'والذين ءامنوا وعملوا الصلحت لنبوئنهم من الجنه غرفا تجري من تحتها الانهر خلدين فيها نعم اجر العملين', 21, 41, 161, 1, 5, 403, false, NULL),
    (3399, 'tanzil-uthmani-v1.1', 29, 59, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'd389b068ccf2c4beba3e40cb1e20db651a73a21ad02609f9e1989e64fcf00a0e', 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 'd389b068ccf2c4beba3e40cb1e20db651a73a21ad02609f9e1989e64fcf00a0e', 'd389b068ccf2c4beba3e40cb1e20db651a73a21ad02609f9e1989e64fcf00a0e', NULL, 'الذين صبروا وعلي ربهم يتوكلون', 21, 41, 161, 1, 5, 403, false, NULL),
    (3400, 'tanzil-uthmani-v1.1', 29, 60, 'وَكَأَيِّن مِّن دَآبَّةٍ لَّا تَحْمِلُ رِزْقَهَا ٱللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'f08820eadc19619d80da7a2b42e36161efaa30c6362ce508225675cecb3d8b97', 'وَكَأَيِّن مِّن دَآبَّةٍ لَّا تَحْمِلُ رِزْقَهَا ٱللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'f08820eadc19619d80da7a2b42e36161efaa30c6362ce508225675cecb3d8b97', 'f08820eadc19619d80da7a2b42e36161efaa30c6362ce508225675cecb3d8b97', NULL, 'وكاين من دابه لا تحمل رزقها الله يرزقها واياكم وهو السميع العليم', 21, 41, 161, 1, 5, 403, false, NULL),
    (3401, 'tanzil-uthmani-v1.1', 29, 61, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ لَيَقُولُنَّ ٱللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', '7b159f5a0aaa7e4ecf6e10fed68d98105ed558b6477ae2a1d9a647334494c1bf', 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ لَيَقُولُنَّ ٱللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', '7b159f5a0aaa7e4ecf6e10fed68d98105ed558b6477ae2a1d9a647334494c1bf', '7b159f5a0aaa7e4ecf6e10fed68d98105ed558b6477ae2a1d9a647334494c1bf', NULL, 'ولئن سالتهم من خلق السموت والارض وسخر الشمس والقمر ليقولن الله فاني يؤفكون', 21, 41, 161, 1, 5, 403, false, NULL),
    (3402, 'tanzil-uthmani-v1.1', 29, 62, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥٓ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'af5fe225c422844d13a5800bc2d3a9452ecbdd03e11c452959c66f3a88e3f471', 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥٓ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'af5fe225c422844d13a5800bc2d3a9452ecbdd03e11c452959c66f3a88e3f471', 'af5fe225c422844d13a5800bc2d3a9452ecbdd03e11c452959c66f3a88e3f471', NULL, 'الله يبسط الرزق لمن يشاء من عباده ويقدر له ان الله بكل شيء عليم', 21, 41, 161, 1, 5, 403, false, NULL),
    (3403, 'tanzil-uthmani-v1.1', 29, 63, 'وَلَئِن سَأَلْتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ مِنۢ بَعْدِ مَوْتِهَا لَيَقُولُنَّ ٱللَّهُ قُلِ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ', '2588ac73338735a308d454167b07a528136394cb21575646c0a7605f97b2ecae', 'وَلَئِن سَأَلْتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَحْيَا بِهِ ٱلْأَرْضَ مِنۢ بَعْدِ مَوْتِهَا لَيَقُولُنَّ ٱللَّهُ قُلِ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ', '2588ac73338735a308d454167b07a528136394cb21575646c0a7605f97b2ecae', '2588ac73338735a308d454167b07a528136394cb21575646c0a7605f97b2ecae', NULL, 'ولئن سالتهم من نزل من السماء ماء فاحيا به الارض من بعد موتها ليقولن الله قل الحمد لله بل اكثرهم لا يعقلون', 21, 41, 161, 1, 5, 403, false, NULL),
    (3404, 'tanzil-uthmani-v1.1', 29, 64, 'وَمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَهْوٌ وَلَعِبٌ وَإِنَّ ٱلدَّارَ ٱلْـَٔاخِرَةَ لَهِىَ ٱلْحَيَوَانُ لَوْ كَانُوا۟ يَعْلَمُونَ', '21e78032da1274906916b78b6b2adb50e88d9828a113db9434d6d0338b2efe43', 'وَمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَهْوٌ وَلَعِبٌ وَإِنَّ ٱلدَّارَ ٱلْـَٔاخِرَةَ لَهِىَ ٱلْحَيَوَانُ لَوْ كَانُوا۟ يَعْلَمُونَ', '21e78032da1274906916b78b6b2adb50e88d9828a113db9434d6d0338b2efe43', '21e78032da1274906916b78b6b2adb50e88d9828a113db9434d6d0338b2efe43', NULL, 'وما هذه الحيوه الدنيا الا لهو ولعب وان الدار الاخره لهي الحيوان لو كانوا يعلمون', 21, 41, 161, 1, 5, 404, false, NULL),
    (3405, 'tanzil-uthmani-v1.1', 29, 65, 'فَإِذَا رَكِبُوا۟ فِى ٱلْفُلْكِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ إِذَا هُمْ يُشْرِكُونَ', '1e6cf81bcb0fb740c8e046144a2dd3b19a765ce5cf959999e134bc4570c3434c', 'فَإِذَا رَكِبُوا۟ فِى ٱلْفُلْكِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ إِذَا هُمْ يُشْرِكُونَ', '1e6cf81bcb0fb740c8e046144a2dd3b19a765ce5cf959999e134bc4570c3434c', '1e6cf81bcb0fb740c8e046144a2dd3b19a765ce5cf959999e134bc4570c3434c', NULL, 'فاذا ركبوا في الفلك دعوا الله مخلصين له الدين فلما نجيهم الي البر اذا هم يشركون', 21, 41, 161, 1, 5, 404, false, NULL),
    (3406, 'tanzil-uthmani-v1.1', 29, 66, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ وَلِيَتَمَتَّعُوا۟ فَسَوْفَ يَعْلَمُونَ', '38eea1ee21aa168001aac30e12a7abb6c754e1ccb7a9a5110d4d1929cb81d99c', 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ وَلِيَتَمَتَّعُوا۟ فَسَوْفَ يَعْلَمُونَ', '38eea1ee21aa168001aac30e12a7abb6c754e1ccb7a9a5110d4d1929cb81d99c', '38eea1ee21aa168001aac30e12a7abb6c754e1ccb7a9a5110d4d1929cb81d99c', NULL, 'ليكفروا بما ءاتينهم وليتمتعوا فسوف يعلمون', 21, 41, 161, 1, 5, 404, false, NULL),
    (3407, 'tanzil-uthmani-v1.1', 29, 67, 'أَوَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا حَرَمًا ءَامِنًا وَيُتَخَطَّفُ ٱلنَّاسُ مِنْ حَوْلِهِمْ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ ٱللَّهِ يَكْفُرُونَ', '539041027b65f4b97e05a7d2f5f6cc6ab17329e9fbc569baf30010b5513dc7ce', 'أَوَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا حَرَمًا ءَامِنًا وَيُتَخَطَّفُ ٱلنَّاسُ مِنْ حَوْلِهِمْ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ ٱللَّهِ يَكْفُرُونَ', '539041027b65f4b97e05a7d2f5f6cc6ab17329e9fbc569baf30010b5513dc7ce', '539041027b65f4b97e05a7d2f5f6cc6ab17329e9fbc569baf30010b5513dc7ce', NULL, 'اولم يروا انا جعلنا حرما ءامنا ويتخطف الناس من حولهم افبالبطل يؤمنون وبنعمه الله يكفرون', 21, 41, 161, 1, 5, 404, false, NULL),
    (3408, 'tanzil-uthmani-v1.1', 29, 68, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِٱلْحَقِّ لَمَّا جَآءَهُۥٓ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ', '7a1d747569b6cf088f7cfa3538e10678ebf6920036a4d487a6d76e05599d3516', 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِٱلْحَقِّ لَمَّا جَآءَهُۥٓ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ', '7a1d747569b6cf088f7cfa3538e10678ebf6920036a4d487a6d76e05599d3516', '7a1d747569b6cf088f7cfa3538e10678ebf6920036a4d487a6d76e05599d3516', NULL, 'ومن اظلم ممن افتري علي الله كذبا او كذب بالحق لما جاءه اليس في جهنم مثوي للكفرين', 21, 41, 161, 1, 5, 404, false, NULL),
    (3409, 'tanzil-uthmani-v1.1', 29, 69, 'وَٱلَّذِينَ جَٰهَدُوا۟ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا وَإِنَّ ٱللَّهَ لَمَعَ ٱلْمُحْسِنِينَ', '4f537d9a084d2e0fb6b7860e9cb5128313ea56cd7217a01af87bb66d1c98f6b2', 'وَٱلَّذِينَ جَٰهَدُوا۟ فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا وَإِنَّ ٱللَّهَ لَمَعَ ٱلْمُحْسِنِينَ', '4f537d9a084d2e0fb6b7860e9cb5128313ea56cd7217a01af87bb66d1c98f6b2', '4f537d9a084d2e0fb6b7860e9cb5128313ea56cd7217a01af87bb66d1c98f6b2', NULL, 'والذين جهدوا فينا لنهدينهم سبلنا وان الله لمع المحسنين', 21, 41, 161, 1, 5, 404, false, NULL),
    (3410, 'tanzil-uthmani-v1.1', 30, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'e190dd3d3d044e6256ebd129866c8631838018200128280a20f27d07491b7e45', 'الٓمٓ', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الم', 21, 41, 162, 1, 5, 404, false, NULL),
    (3411, 'tanzil-uthmani-v1.1', 30, 2, 'غُلِبَتِ ٱلرُّومُ', '67b7027dcb2e5d2ab79f2c422604f3a8cf2549966a3f1fefac5436a053ec8f8b', 'غُلِبَتِ ٱلرُّومُ', '67b7027dcb2e5d2ab79f2c422604f3a8cf2549966a3f1fefac5436a053ec8f8b', '67b7027dcb2e5d2ab79f2c422604f3a8cf2549966a3f1fefac5436a053ec8f8b', NULL, 'غلبت الروم', 21, 41, 162, 1, 5, 404, false, NULL),
    (3412, 'tanzil-uthmani-v1.1', 30, 3, 'فِىٓ أَدْنَى ٱلْأَرْضِ وَهُم مِّنۢ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ', 'b103fef06fb9006fc0fabdcf1dd2b5cc3dbd2d997458d262e5c57a36b9e8c305', 'فِىٓ أَدْنَى ٱلْأَرْضِ وَهُم مِّنۢ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ', 'b103fef06fb9006fc0fabdcf1dd2b5cc3dbd2d997458d262e5c57a36b9e8c305', 'b103fef06fb9006fc0fabdcf1dd2b5cc3dbd2d997458d262e5c57a36b9e8c305', NULL, 'في ادني الارض وهم من بعد غلبهم سيغلبون', 21, 41, 162, 1, 5, 404, false, NULL),
    (3413, 'tanzil-uthmani-v1.1', 30, 4, 'فِى بِضْعِ سِنِينَ لِلَّهِ ٱلْأَمْرُ مِن قَبْلُ وَمِنۢ بَعْدُ وَيَوْمَئِذٍ يَفْرَحُ ٱلْمُؤْمِنُونَ', '6e7414e899b650bb8bfe9a42c56b161bac7b646192b8c9bbf970ddc3884eb4ba', 'فِى بِضْعِ سِنِينَ لِلَّهِ ٱلْأَمْرُ مِن قَبْلُ وَمِنۢ بَعْدُ وَيَوْمَئِذٍ يَفْرَحُ ٱلْمُؤْمِنُونَ', '6e7414e899b650bb8bfe9a42c56b161bac7b646192b8c9bbf970ddc3884eb4ba', '6e7414e899b650bb8bfe9a42c56b161bac7b646192b8c9bbf970ddc3884eb4ba', NULL, 'في بضع سنين لله الامر من قبل ومن بعد ويومئذ يفرح المؤمنون', 21, 41, 162, 1, 5, 404, false, NULL),
    (3414, 'tanzil-uthmani-v1.1', 30, 5, 'بِنَصْرِ ٱللَّهِ يَنصُرُ مَن يَشَآءُ وَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '4737d144b9fb445a36edaa1cd9e5e3c793e30e168b959b663c4e423a426cf010', 'بِنَصْرِ ٱللَّهِ يَنصُرُ مَن يَشَآءُ وَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', '4737d144b9fb445a36edaa1cd9e5e3c793e30e168b959b663c4e423a426cf010', '4737d144b9fb445a36edaa1cd9e5e3c793e30e168b959b663c4e423a426cf010', NULL, 'بنصر الله ينصر من يشاء وهو العزيز الرحيم', 21, 41, 162, 1, 5, 404, false, NULL),
    (3415, 'tanzil-uthmani-v1.1', 30, 6, 'وَعْدَ ٱللَّهِ لَا يُخْلِفُ ٱللَّهُ وَعْدَهُۥ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '24a6192dd28b2a154ee27f59d4a2dff321f10c5341c6c3273fc7b954e789ce44', 'وَعْدَ ٱللَّهِ لَا يُخْلِفُ ٱللَّهُ وَعْدَهُۥ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '24a6192dd28b2a154ee27f59d4a2dff321f10c5341c6c3273fc7b954e789ce44', '24a6192dd28b2a154ee27f59d4a2dff321f10c5341c6c3273fc7b954e789ce44', NULL, 'وعد الله لا يخلف الله وعده ولكن اكثر الناس لا يعلمون', 21, 41, 162, 1, 5, 405, false, NULL),
    (3416, 'tanzil-uthmani-v1.1', 30, 7, 'يَعْلَمُونَ ظَٰهِرًا مِّنَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ عَنِ ٱلْـَٔاخِرَةِ هُمْ غَٰفِلُونَ', '9c6a84cd9f22cdb537badb289fa139680a1aa499ec56ee5ad58df7592d70eb6e', 'يَعْلَمُونَ ظَٰهِرًا مِّنَ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ عَنِ ٱلْـَٔاخِرَةِ هُمْ غَٰفِلُونَ', '9c6a84cd9f22cdb537badb289fa139680a1aa499ec56ee5ad58df7592d70eb6e', '9c6a84cd9f22cdb537badb289fa139680a1aa499ec56ee5ad58df7592d70eb6e', NULL, 'يعلمون ظهرا من الحيوه الدنيا وهم عن الاخره هم غفلون', 21, 41, 162, 1, 5, 405, false, NULL),
    (3417, 'tanzil-uthmani-v1.1', 30, 8, 'أَوَلَمْ يَتَفَكَّرُوا۟ فِىٓ أَنفُسِهِم مَّا خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ بِلِقَآئِ رَبِّهِمْ لَكَٰفِرُونَ', 'b0492530430419d999456c976fb09008297890bd05cdc3e05b273f525bbc12e4', 'أَوَلَمْ يَتَفَكَّرُوا۟ فِىٓ أَنفُسِهِم مَّا خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ بِلِقَآئِ رَبِّهِمْ لَكَٰفِرُونَ', 'b0492530430419d999456c976fb09008297890bd05cdc3e05b273f525bbc12e4', 'b0492530430419d999456c976fb09008297890bd05cdc3e05b273f525bbc12e4', NULL, 'اولم يتفكروا في انفسهم ما خلق الله السموت والارض وما بينهما الا بالحق واجل مسمي وان كثيرا من الناس بلقائ ربهم لكفرون', 21, 41, 162, 1, 5, 405, false, NULL),
    (3418, 'tanzil-uthmani-v1.1', 30, 9, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ كَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَأَثَارُوا۟ ٱلْأَرْضَ وَعَمَرُوهَآ أَكْثَرَ مِمَّا عَمَرُوهَا وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '034f3a1ced94453b7f10a5637a3f09beab526672664d4400e0c2fb2f38cc83d9', 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ كَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَأَثَارُوا۟ ٱلْأَرْضَ وَعَمَرُوهَآ أَكْثَرَ مِمَّا عَمَرُوهَا وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', '034f3a1ced94453b7f10a5637a3f09beab526672664d4400e0c2fb2f38cc83d9', '034f3a1ced94453b7f10a5637a3f09beab526672664d4400e0c2fb2f38cc83d9', NULL, 'اولم يسيروا في الارض فينظروا كيف كان عقبه الذين من قبلهم كانوا اشد منهم قوه واثاروا الارض وعمروها اكثر مما عمروها وجاءتهم رسلهم بالبينت فما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون', 21, 41, 162, 1, 5, 405, false, NULL),
    (3419, 'tanzil-uthmani-v1.1', 30, 10, 'ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ ٱلسُّوٓأَىٰٓ أَن كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَكَانُوا۟ بِهَا يَسْتَهْزِءُونَ', '4f58d18bb0c4c69f03ecad8c26eaf61b6eed32cb3683d67e65cd5c9e2f1a91c4', 'ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ ٱلسُّوٓأَىٰٓ أَن كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَكَانُوا۟ بِهَا يَسْتَهْزِءُونَ', '4f58d18bb0c4c69f03ecad8c26eaf61b6eed32cb3683d67e65cd5c9e2f1a91c4', '4f58d18bb0c4c69f03ecad8c26eaf61b6eed32cb3683d67e65cd5c9e2f1a91c4', NULL, 'ثم كان عقبه الذين اسوا السواي ان كذبوا بايت الله وكانوا بها يستهزءون', 21, 41, 162, 1, 5, 405, false, NULL),
    (3420, 'tanzil-uthmani-v1.1', 30, 11, 'ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيْهِ تُرْجَعُونَ', '84721cc31f536bf36bf8255479efb8da9c9546ef2f390ed12c08b69a5aeb5a0e', 'ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيْهِ تُرْجَعُونَ', '84721cc31f536bf36bf8255479efb8da9c9546ef2f390ed12c08b69a5aeb5a0e', '84721cc31f536bf36bf8255479efb8da9c9546ef2f390ed12c08b69a5aeb5a0e', NULL, 'الله يبدؤا الخلق ثم يعيده ثم اليه ترجعون', 21, 41, 162, 1, 5, 405, false, NULL),
    (3421, 'tanzil-uthmani-v1.1', 30, 12, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُبْلِسُ ٱلْمُجْرِمُونَ', 'df4b970ece0cbbcdaed410ea1d83305d7891c431d79fb02b828c4e037e3bfde9', 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُبْلِسُ ٱلْمُجْرِمُونَ', 'df4b970ece0cbbcdaed410ea1d83305d7891c431d79fb02b828c4e037e3bfde9', 'df4b970ece0cbbcdaed410ea1d83305d7891c431d79fb02b828c4e037e3bfde9', NULL, 'ويوم تقوم الساعه يبلس المجرمون', 21, 41, 162, 1, 5, 405, false, NULL),
    (3422, 'tanzil-uthmani-v1.1', 30, 13, 'وَلَمْ يَكُن لَّهُم مِّن شُرَكَآئِهِمْ شُفَعَٰٓؤُا۟ وَكَانُوا۟ بِشُرَكَآئِهِمْ كَٰفِرِينَ', 'e3433f3cbdd076117ce927e1bff43fc0a615e43784049f8e5bd13816cf43489a', 'وَلَمْ يَكُن لَّهُم مِّن شُرَكَآئِهِمْ شُفَعَٰٓؤُا۟ وَكَانُوا۟ بِشُرَكَآئِهِمْ كَٰفِرِينَ', 'e3433f3cbdd076117ce927e1bff43fc0a615e43784049f8e5bd13816cf43489a', 'e3433f3cbdd076117ce927e1bff43fc0a615e43784049f8e5bd13816cf43489a', NULL, 'ولم يكن لهم من شركائهم شفعؤا وكانوا بشركائهم كفرين', 21, 41, 162, 1, 5, 405, false, NULL),
    (3423, 'tanzil-uthmani-v1.1', 30, 14, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَتَفَرَّقُونَ', '526e6dc1d3ef37b7a789222852f63677cf3125778037c170b5c25d988e79e809', 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَتَفَرَّقُونَ', '526e6dc1d3ef37b7a789222852f63677cf3125778037c170b5c25d988e79e809', '526e6dc1d3ef37b7a789222852f63677cf3125778037c170b5c25d988e79e809', NULL, 'ويوم تقوم الساعه يومئذ يتفرقون', 21, 41, 162, 1, 5, 405, false, NULL),
    (3424, 'tanzil-uthmani-v1.1', 30, 15, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَهُمْ فِى رَوْضَةٍ يُحْبَرُونَ', 'b885498944874b08042567ebc23a73cde0509e6a721fa58fdfd00dbb8721f489', 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَهُمْ فِى رَوْضَةٍ يُحْبَرُونَ', 'b885498944874b08042567ebc23a73cde0509e6a721fa58fdfd00dbb8721f489', 'b885498944874b08042567ebc23a73cde0509e6a721fa58fdfd00dbb8721f489', NULL, 'فاما الذين ءامنوا وعملوا الصلحت فهم في روضه يحبرون', 21, 41, 162, 1, 5, 405, false, NULL),
    (3425, 'tanzil-uthmani-v1.1', 30, 16, 'وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآئِ ٱلْـَٔاخِرَةِ فَأُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', '6ddcca6a777a5791fa6b7e66826f705154e7d03e39983ad3f80bcd2a068490a1', 'وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآئِ ٱلْـَٔاخِرَةِ فَأُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', '6ddcca6a777a5791fa6b7e66826f705154e7d03e39983ad3f80bcd2a068490a1', '6ddcca6a777a5791fa6b7e66826f705154e7d03e39983ad3f80bcd2a068490a1', NULL, 'واما الذين كفروا وكذبوا بايتنا ولقائ الاخره فاولئك في العذاب محضرون', 21, 41, 162, 1, 5, 406, false, NULL),
    (3426, 'tanzil-uthmani-v1.1', 30, 17, 'فَسُبْحَٰنَ ٱللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ', '78eeb2d938ab17fc0802ed0df276ada56c9f6a816bda720b9a091fbcbdd0e9f5', 'فَسُبْحَٰنَ ٱللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ', '78eeb2d938ab17fc0802ed0df276ada56c9f6a816bda720b9a091fbcbdd0e9f5', '78eeb2d938ab17fc0802ed0df276ada56c9f6a816bda720b9a091fbcbdd0e9f5', NULL, 'فسبحن الله حين تمسون وحين تصبحون', 21, 41, 162, 1, 5, 406, false, NULL),
    (3427, 'tanzil-uthmani-v1.1', 30, 18, 'وَلَهُ ٱلْحَمْدُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ', '9a561e6d6deadf4bea212c1ca7a301c85160a9ff985a4840a0bf9f54b46b784b', 'وَلَهُ ٱلْحَمْدُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ', '9a561e6d6deadf4bea212c1ca7a301c85160a9ff985a4840a0bf9f54b46b784b', '9a561e6d6deadf4bea212c1ca7a301c85160a9ff985a4840a0bf9f54b46b784b', NULL, 'وله الحمد في السموت والارض وعشيا وحين تظهرون', 21, 41, 162, 1, 5, 406, false, NULL),
    (3428, 'tanzil-uthmani-v1.1', 30, 19, 'يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَيُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَكَذَٰلِكَ تُخْرَجُونَ', '4e06e4b736e2de7d8c43b11163c09b1f5b991310782944e1c1d422490d230c87', 'يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَيُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَكَذَٰلِكَ تُخْرَجُونَ', '4e06e4b736e2de7d8c43b11163c09b1f5b991310782944e1c1d422490d230c87', '4e06e4b736e2de7d8c43b11163c09b1f5b991310782944e1c1d422490d230c87', NULL, 'يخرج الحي من الميت ويخرج الميت من الحي ويحي الارض بعد موتها وكذلك تخرجون', 21, 41, 162, 1, 5, 406, false, NULL),
    (3429, 'tanzil-uthmani-v1.1', 30, 20, 'وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَكُم مِّن تُرَابٍ ثُمَّ إِذَآ أَنتُم بَشَرٌ تَنتَشِرُونَ', 'bdfff932128246d71e88c495f215f69d9ff7ec4165cfcac02a98057b50ec813f', 'وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَكُم مِّن تُرَابٍ ثُمَّ إِذَآ أَنتُم بَشَرٌ تَنتَشِرُونَ', 'bdfff932128246d71e88c495f215f69d9ff7ec4165cfcac02a98057b50ec813f', 'bdfff932128246d71e88c495f215f69d9ff7ec4165cfcac02a98057b50ec813f', NULL, 'ومن ءايته ان خلقكم من تراب ثم اذا انتم بشر تنتشرون', 21, 41, 162, 1, 5, 406, false, NULL),
    (3430, 'tanzil-uthmani-v1.1', 30, 21, 'وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا لِّتَسْكُنُوٓا۟ إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'dd90a139a5c9435173f8636211e92f8134931e37e346dadcce06b2f6305e2f29', 'وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا لِّتَسْكُنُوٓا۟ إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'dd90a139a5c9435173f8636211e92f8134931e37e346dadcce06b2f6305e2f29', 'dd90a139a5c9435173f8636211e92f8134931e37e346dadcce06b2f6305e2f29', NULL, 'ومن ءايته ان خلق لكم من انفسكم ازوجا لتسكنوا اليها وجعل بينكم موده ورحمه ان في ذلك لايت لقوم يتفكرون', 21, 41, 162, 1, 5, 406, false, NULL),
    (3431, 'tanzil-uthmani-v1.1', 30, 22, 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفُ أَلْسِنَتِكُمْ وَأَلْوَٰنِكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّلْعَٰلِمِينَ', '1c451aa557757993eb318d4d847454bf73705315f508f23cd2d76d2e8d9397da', 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفُ أَلْسِنَتِكُمْ وَأَلْوَٰنِكُمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّلْعَٰلِمِينَ', '1c451aa557757993eb318d4d847454bf73705315f508f23cd2d76d2e8d9397da', '1c451aa557757993eb318d4d847454bf73705315f508f23cd2d76d2e8d9397da', NULL, 'ومن ءايته خلق السموت والارض واختلف السنتكم والونكم ان في ذلك لايت للعلمين', 21, 41, 162, 1, 5, 406, false, NULL),
    (3432, 'tanzil-uthmani-v1.1', 30, 23, 'وَمِنْ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيْلِ وَٱلنَّهَارِ وَٱبْتِغَآؤُكُم مِّن فَضْلِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ', 'b4bb883bab69dc087d6eefa34c36a4be40102f290d79d39b58f0c20b3e036297', 'وَمِنْ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيْلِ وَٱلنَّهَارِ وَٱبْتِغَآؤُكُم مِّن فَضْلِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ', 'b4bb883bab69dc087d6eefa34c36a4be40102f290d79d39b58f0c20b3e036297', 'b4bb883bab69dc087d6eefa34c36a4be40102f290d79d39b58f0c20b3e036297', NULL, 'ومن ءايته منامكم باليل والنهار وابتغاؤكم من فضله ان في ذلك لايت لقوم يسمعون', 21, 41, 162, 1, 5, 406, false, NULL),
    (3433, 'tanzil-uthmani-v1.1', 30, 24, 'وَمِنْ ءَايَٰتِهِۦ يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءً فَيُحْىِۦ بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'ec791c3521fd81f116a4cb581cc34cca9d36b3c2990d3d004339f226202e50ea', 'وَمِنْ ءَايَٰتِهِۦ يُرِيكُمُ ٱلْبَرْقَ خَوْفًا وَطَمَعًا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءً فَيُحْىِۦ بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ', 'ec791c3521fd81f116a4cb581cc34cca9d36b3c2990d3d004339f226202e50ea', 'ec791c3521fd81f116a4cb581cc34cca9d36b3c2990d3d004339f226202e50ea', NULL, 'ومن ءايته يريكم البرق خوفا وطمعا وينزل من السماء ماء فيحي به الارض بعد موتها ان في ذلك لايت لقوم يعقلون', 21, 41, 162, 1, 5, 406, false, NULL),
    (3434, 'tanzil-uthmani-v1.1', 30, 25, 'وَمِنْ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلْأَرْضُ بِأَمْرِهِۦ ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِّنَ ٱلْأَرْضِ إِذَآ أَنتُمْ تَخْرُجُونَ', 'ed648dcc5a894ab282644451e889dee870bb25c004ef2bd08f2d1536bbc6b289', 'وَمِنْ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلْأَرْضُ بِأَمْرِهِۦ ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِّنَ ٱلْأَرْضِ إِذَآ أَنتُمْ تَخْرُجُونَ', 'ed648dcc5a894ab282644451e889dee870bb25c004ef2bd08f2d1536bbc6b289', 'ed648dcc5a894ab282644451e889dee870bb25c004ef2bd08f2d1536bbc6b289', NULL, 'ومن ءايته ان تقوم السماء والارض بامره ثم اذا دعاكم دعوه من الارض اذا انتم تخرجون', 21, 41, 162, 1, 5, 407, false, NULL),
    (3435, 'tanzil-uthmani-v1.1', 30, 26, 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلٌّ لَّهُۥ قَٰنِتُونَ', 'c13e144e02e0d62a506afd1ba29a3206e07bdfb449a6836244c45e2f634eb58e', 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلٌّ لَّهُۥ قَٰنِتُونَ', 'c13e144e02e0d62a506afd1ba29a3206e07bdfb449a6836244c45e2f634eb58e', 'c13e144e02e0d62a506afd1ba29a3206e07bdfb449a6836244c45e2f634eb58e', NULL, 'وله من في السموت والارض كل له قنتون', 21, 41, 162, 1, 5, 407, false, NULL),
    (3436, 'tanzil-uthmani-v1.1', 30, 27, 'وَهُوَ ٱلَّذِى يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهْوَنُ عَلَيْهِ وَلَهُ ٱلْمَثَلُ ٱلْأَعْلَىٰ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'e6e37807693c3e062e706fd7821d40939f609c1999806068ca22a87494ec6068', 'وَهُوَ ٱلَّذِى يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهْوَنُ عَلَيْهِ وَلَهُ ٱلْمَثَلُ ٱلْأَعْلَىٰ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'e6e37807693c3e062e706fd7821d40939f609c1999806068ca22a87494ec6068', 'e6e37807693c3e062e706fd7821d40939f609c1999806068ca22a87494ec6068', NULL, 'وهو الذي يبدؤا الخلق ثم يعيده وهو اهون عليه وله المثل الاعلي في السموت والارض وهو العزيز الحكيم', 21, 41, 162, 1, 5, 407, false, NULL),
    (3437, 'tanzil-uthmani-v1.1', 30, 28, 'ضَرَبَ لَكُم مَّثَلًا مِّنْ أَنفُسِكُمْ هَل لَّكُم مِّن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن شُرَكَآءَ فِى مَا رَزَقْنَٰكُمْ فَأَنتُمْ فِيهِ سَوَآءٌ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنفُسَكُمْ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْقِلُونَ', '1f9a8e6d80d74e4c45fa460febde785032c5dec3cfd3655506db6ed2c7d8fc24', 'ضَرَبَ لَكُم مَّثَلًا مِّنْ أَنفُسِكُمْ هَل لَّكُم مِّن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن شُرَكَآءَ فِى مَا رَزَقْنَٰكُمْ فَأَنتُمْ فِيهِ سَوَآءٌ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنفُسَكُمْ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْقِلُونَ', '1f9a8e6d80d74e4c45fa460febde785032c5dec3cfd3655506db6ed2c7d8fc24', '1f9a8e6d80d74e4c45fa460febde785032c5dec3cfd3655506db6ed2c7d8fc24', NULL, 'ضرب لكم مثلا من انفسكم هل لكم من ما ملكت ايمنكم من شركاء في ما رزقنكم فانتم فيه سواء تخافونهم كخيفتكم انفسكم كذلك نفصل الايت لقوم يعقلون', 21, 41, 162, 1, 5, 407, false, NULL),
    (3438, 'tanzil-uthmani-v1.1', 30, 29, 'بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓا۟ أَهْوَآءَهُم بِغَيْرِ عِلْمٍ فَمَن يَهْدِى مَنْ أَضَلَّ ٱللَّهُ وَمَا لَهُم مِّن نَّٰصِرِينَ', '5be04c9e2e59b5abc91e21b67fab9989e10eee45c1a56c995525ee185a3c9174', 'بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓا۟ أَهْوَآءَهُم بِغَيْرِ عِلْمٍ فَمَن يَهْدِى مَنْ أَضَلَّ ٱللَّهُ وَمَا لَهُم مِّن نَّٰصِرِينَ', '5be04c9e2e59b5abc91e21b67fab9989e10eee45c1a56c995525ee185a3c9174', '5be04c9e2e59b5abc91e21b67fab9989e10eee45c1a56c995525ee185a3c9174', NULL, 'بل اتبع الذين ظلموا اهواءهم بغير علم فمن يهدي من اضل الله وما لهم من نصرين', 21, 41, 162, 1, 5, 407, false, NULL),
    (3439, 'tanzil-uthmani-v1.1', 30, 30, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ ٱللَّهِ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '3b555d3134b01e5ec8c0a191da9738eeb7b03a691ef140ad19a8b2ba99c429b5', 'فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ ٱللَّهِ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '3b555d3134b01e5ec8c0a191da9738eeb7b03a691ef140ad19a8b2ba99c429b5', '3b555d3134b01e5ec8c0a191da9738eeb7b03a691ef140ad19a8b2ba99c429b5', NULL, 'فاقم وجهك للدين حنيفا فطرت الله التي فطر الناس عليها لا تبديل لخلق الله ذلك الدين القيم ولكن اكثر الناس لا يعلمون', 21, 41, 162, 1, 5, 407, false, NULL),
    (3440, 'tanzil-uthmani-v1.1', 30, 31, 'مُنِيبِينَ إِلَيْهِ وَٱتَّقُوهُ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُشْرِكِينَ', '1415fe082dea0ca0d5adf3c6fa020c7cb888b653d574f409d7604c9f7f04a12a', 'مُنِيبِينَ إِلَيْهِ وَٱتَّقُوهُ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُشْرِكِينَ', '1415fe082dea0ca0d5adf3c6fa020c7cb888b653d574f409d7604c9f7f04a12a', '1415fe082dea0ca0d5adf3c6fa020c7cb888b653d574f409d7604c9f7f04a12a', NULL, 'منيبين اليه واتقوه واقيموا الصلوه ولا تكونوا من المشركين', 21, 41, 163, 1, 5, 407, false, NULL),
    (3441, 'tanzil-uthmani-v1.1', 30, 32, 'مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', '7a5f51588e04c798952881d12146211cb16956d070d81e731481ac06b4dcb522', 'مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', '7a5f51588e04c798952881d12146211cb16956d070d81e731481ac06b4dcb522', '7a5f51588e04c798952881d12146211cb16956d070d81e731481ac06b4dcb522', NULL, 'من الذين فرقوا دينهم وكانوا شيعا كل حزب بما لديهم فرحون', 21, 41, 163, 1, 5, 407, false, NULL),
    (3442, 'tanzil-uthmani-v1.1', 30, 33, 'وَإِذَا مَسَّ ٱلنَّاسَ ضُرٌّ دَعَوْا۟ رَبَّهُم مُّنِيبِينَ إِلَيْهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنْهُ رَحْمَةً إِذَا فَرِيقٌ مِّنْهُم بِرَبِّهِمْ يُشْرِكُونَ', 'd2f938d629889ad0ba5d932c0db42da022ae7b8eff90f9aeb4de1e9b7cbaecdb', 'وَإِذَا مَسَّ ٱلنَّاسَ ضُرٌّ دَعَوْا۟ رَبَّهُم مُّنِيبِينَ إِلَيْهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنْهُ رَحْمَةً إِذَا فَرِيقٌ مِّنْهُم بِرَبِّهِمْ يُشْرِكُونَ', 'd2f938d629889ad0ba5d932c0db42da022ae7b8eff90f9aeb4de1e9b7cbaecdb', 'd2f938d629889ad0ba5d932c0db42da022ae7b8eff90f9aeb4de1e9b7cbaecdb', NULL, 'واذا مس الناس ضر دعوا ربهم منيبين اليه ثم اذا اذاقهم منه رحمه اذا فريق منهم بربهم يشركون', 21, 41, 163, 1, 5, 408, false, NULL),
    (3443, 'tanzil-uthmani-v1.1', 30, 34, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', 'c716e6d6188d17deecd789f5b9d198811228137208b98db9b6b51328d4c18349', 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ فَتَمَتَّعُوا۟ فَسَوْفَ تَعْلَمُونَ', 'c716e6d6188d17deecd789f5b9d198811228137208b98db9b6b51328d4c18349', 'c716e6d6188d17deecd789f5b9d198811228137208b98db9b6b51328d4c18349', NULL, 'ليكفروا بما ءاتينهم فتمتعوا فسوف تعلمون', 21, 41, 163, 1, 5, 408, false, NULL),
    (3444, 'tanzil-uthmani-v1.1', 30, 35, 'أَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَٰنًا فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا۟ بِهِۦ يُشْرِكُونَ', '1e360351b77ebc059eb39f6b14845c499634667a7851e4d974fabf9e5c1f6e07', 'أَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَٰنًا فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا۟ بِهِۦ يُشْرِكُونَ', '1e360351b77ebc059eb39f6b14845c499634667a7851e4d974fabf9e5c1f6e07', '1e360351b77ebc059eb39f6b14845c499634667a7851e4d974fabf9e5c1f6e07', NULL, 'ام انزلنا عليهم سلطنا فهو يتكلم بما كانوا به يشركون', 21, 41, 163, 1, 5, 408, false, NULL),
    (3445, 'tanzil-uthmani-v1.1', 30, 36, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً فَرِحُوا۟ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ', '79f98cad543da819d30d9fca7e089ba873c39d15d34e90ca0e9da55088fdc380', 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةً فَرِحُوا۟ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ', '79f98cad543da819d30d9fca7e089ba873c39d15d34e90ca0e9da55088fdc380', '79f98cad543da819d30d9fca7e089ba873c39d15d34e90ca0e9da55088fdc380', NULL, 'واذا اذقنا الناس رحمه فرحوا بها وان تصبهم سيئه بما قدمت ايديهم اذا هم يقنطون', 21, 41, 163, 1, 5, 408, false, NULL),
    (3446, 'tanzil-uthmani-v1.1', 30, 37, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'b7699eee55240241381ac8387fb296edf3c0e17279823b0e064480a24b9c0f89', 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'b7699eee55240241381ac8387fb296edf3c0e17279823b0e064480a24b9c0f89', 'b7699eee55240241381ac8387fb296edf3c0e17279823b0e064480a24b9c0f89', NULL, 'اولم يروا ان الله يبسط الرزق لمن يشاء ويقدر ان في ذلك لايت لقوم يؤمنون', 21, 41, 163, 1, 5, 408, false, NULL),
    (3447, 'tanzil-uthmani-v1.1', 30, 38, 'فَـَٔاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ ذَٰلِكَ خَيْرٌ لِّلَّذِينَ يُرِيدُونَ وَجْهَ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'd8d538def1b6d94951b71912ce53ee92ac42a43af06a0403dd37b5aa546dd98d', 'فَـَٔاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ ذَٰلِكَ خَيْرٌ لِّلَّذِينَ يُرِيدُونَ وَجْهَ ٱللَّهِ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'd8d538def1b6d94951b71912ce53ee92ac42a43af06a0403dd37b5aa546dd98d', 'd8d538def1b6d94951b71912ce53ee92ac42a43af06a0403dd37b5aa546dd98d', NULL, 'فات ذا القربي حقه والمسكين وابن السبيل ذلك خير للذين يريدون وجه الله واولئك هم المفلحون', 21, 41, 163, 1, 5, 408, false, NULL),
    (3448, 'tanzil-uthmani-v1.1', 30, 39, 'وَمَآ ءَاتَيْتُم مِّن رِّبًا لِّيَرْبُوَا۟ فِىٓ أَمْوَٰلِ ٱلنَّاسِ فَلَا يَرْبُوا۟ عِندَ ٱللَّهِ وَمَآ ءَاتَيْتُم مِّن زَكَوٰةٍ تُرِيدُونَ وَجْهَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُضْعِفُونَ', '705f3632b6e3a4afe6816ae1b3537bea809fa5905a6c3e88da931f5db505b45f', 'وَمَآ ءَاتَيْتُم مِّن رِّبًا لِّيَرْبُوَا۟ فِىٓ أَمْوَٰلِ ٱلنَّاسِ فَلَا يَرْبُوا۟ عِندَ ٱللَّهِ وَمَآ ءَاتَيْتُم مِّن زَكَوٰةٍ تُرِيدُونَ وَجْهَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُضْعِفُونَ', '705f3632b6e3a4afe6816ae1b3537bea809fa5905a6c3e88da931f5db505b45f', '705f3632b6e3a4afe6816ae1b3537bea809fa5905a6c3e88da931f5db505b45f', NULL, 'وما ءاتيتم من ربا ليربوا في امول الناس فلا يربوا عند الله وما ءاتيتم من زكوه تريدون وجه الله فاولئك هم المضعفون', 21, 41, 163, 1, 5, 408, false, NULL),
    (3449, 'tanzil-uthmani-v1.1', 30, 40, 'ٱللَّهُ ٱلَّذِى خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ هَلْ مِن شُرَكَآئِكُم مَّن يَفْعَلُ مِن ذَٰلِكُم مِّن شَىْءٍ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '1f4793ebfc537ef490058af3398fcf765b5d24b7344e6f5dc5f2ffb8148cdaeb', 'ٱللَّهُ ٱلَّذِى خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ هَلْ مِن شُرَكَآئِكُم مَّن يَفْعَلُ مِن ذَٰلِكُم مِّن شَىْءٍ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', '1f4793ebfc537ef490058af3398fcf765b5d24b7344e6f5dc5f2ffb8148cdaeb', '1f4793ebfc537ef490058af3398fcf765b5d24b7344e6f5dc5f2ffb8148cdaeb', NULL, 'الله الذي خلقكم ثم رزقكم ثم يميتكم ثم يحييكم هل من شركائكم من يفعل من ذلكم من شيء سبحنه وتعلي عما يشركون', 21, 41, 163, 1, 5, 408, false, NULL),
    (3450, 'tanzil-uthmani-v1.1', 30, 41, 'ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ', 'bdbff56c706d9e4bdc11f630482f81ade2aed183495cc780d4fa1d20e1598131', 'ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ', 'bdbff56c706d9e4bdc11f630482f81ade2aed183495cc780d4fa1d20e1598131', 'bdbff56c706d9e4bdc11f630482f81ade2aed183495cc780d4fa1d20e1598131', NULL, 'ظهر الفساد في البر والبحر بما كسبت ايدي الناس ليذيقهم بعض الذي عملوا لعلهم يرجعون', 21, 41, 163, 1, 5, 408, false, NULL),
    (3451, 'tanzil-uthmani-v1.1', 30, 42, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلُ كَانَ أَكْثَرُهُم مُّشْرِكِينَ', '8e9d9c34c8b36b0231d59b1ec004d4a4de7a360593d2ebcab1cefe289d007c9e', 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلُ كَانَ أَكْثَرُهُم مُّشْرِكِينَ', '8e9d9c34c8b36b0231d59b1ec004d4a4de7a360593d2ebcab1cefe289d007c9e', '8e9d9c34c8b36b0231d59b1ec004d4a4de7a360593d2ebcab1cefe289d007c9e', NULL, 'قل سيروا في الارض فانظروا كيف كان عقبه الذين من قبل كان اكثرهم مشركين', 21, 41, 163, 1, 5, 409, false, NULL),
    (3452, 'tanzil-uthmani-v1.1', 30, 43, 'فَأَقِمْ وَجْهَكَ لِلدِّينِ ٱلْقَيِّمِ مِن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ يَوْمَئِذٍ يَصَّدَّعُونَ', 'ed4df19a4cf09a1aacb65e8c9e2e8e6a1aa94561d3757df643a8f7b7e61cc5ba', 'فَأَقِمْ وَجْهَكَ لِلدِّينِ ٱلْقَيِّمِ مِن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ يَوْمَئِذٍ يَصَّدَّعُونَ', 'ed4df19a4cf09a1aacb65e8c9e2e8e6a1aa94561d3757df643a8f7b7e61cc5ba', 'ed4df19a4cf09a1aacb65e8c9e2e8e6a1aa94561d3757df643a8f7b7e61cc5ba', NULL, 'فاقم وجهك للدين القيم من قبل ان ياتي يوم لا مرد له من الله يومئذ يصدعون', 21, 41, 163, 1, 5, 409, false, NULL),
    (3453, 'tanzil-uthmani-v1.1', 30, 44, 'مَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ وَمَنْ عَمِلَ صَٰلِحًا فَلِأَنفُسِهِمْ يَمْهَدُونَ', 'c57034dd7be592e0d6e4c9708ed0dd0fe4600d62a6efacacee071f92ec7208e0', 'مَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ وَمَنْ عَمِلَ صَٰلِحًا فَلِأَنفُسِهِمْ يَمْهَدُونَ', 'c57034dd7be592e0d6e4c9708ed0dd0fe4600d62a6efacacee071f92ec7208e0', 'c57034dd7be592e0d6e4c9708ed0dd0fe4600d62a6efacacee071f92ec7208e0', NULL, 'من كفر فعليه كفره ومن عمل صلحا فلانفسهم يمهدون', 21, 41, 163, 1, 5, 409, false, NULL),
    (3454, 'tanzil-uthmani-v1.1', 30, 45, 'لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِن فَضْلِهِۦٓ إِنَّهُۥ لَا يُحِبُّ ٱلْكَٰفِرِينَ', '505b44cde1a0156123bf803b69fd32283609fd7867bdec0258825c3f60a78aad', 'لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِن فَضْلِهِۦٓ إِنَّهُۥ لَا يُحِبُّ ٱلْكَٰفِرِينَ', '505b44cde1a0156123bf803b69fd32283609fd7867bdec0258825c3f60a78aad', '505b44cde1a0156123bf803b69fd32283609fd7867bdec0258825c3f60a78aad', NULL, 'ليجزي الذين ءامنوا وعملوا الصلحت من فضله انه لا يحب الكفرين', 21, 41, 163, 1, 5, 409, false, NULL),
    (3455, 'tanzil-uthmani-v1.1', 30, 46, 'وَمِنْ ءَايَٰتِهِۦٓ أَن يُرْسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٍ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِۦ وَلِتَجْرِىَ ٱلْفُلْكُ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'a285b1fd18e15698db44e832752edd7e85f10b322c872a46df4ca6ad0d89013a', 'وَمِنْ ءَايَٰتِهِۦٓ أَن يُرْسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٍ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِۦ وَلِتَجْرِىَ ٱلْفُلْكُ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 'a285b1fd18e15698db44e832752edd7e85f10b322c872a46df4ca6ad0d89013a', 'a285b1fd18e15698db44e832752edd7e85f10b322c872a46df4ca6ad0d89013a', NULL, 'ومن ءايته ان يرسل الرياح مبشرت وليذيقكم من رحمته ولتجري الفلك بامره ولتبتغوا من فضله ولعلكم تشكرون', 21, 41, 163, 1, 5, 409, false, NULL),
    (3456, 'tanzil-uthmani-v1.1', 30, 47, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَٱنتَقَمْنَا مِنَ ٱلَّذِينَ أَجْرَمُوا۟ وَكَانَ حَقًّا عَلَيْنَا نَصْرُ ٱلْمُؤْمِنِينَ', '9d2c35d4bcd17c2bfe20ed9c47c80425278e1777d430b1fb7b0304f558a6357a', 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَٱنتَقَمْنَا مِنَ ٱلَّذِينَ أَجْرَمُوا۟ وَكَانَ حَقًّا عَلَيْنَا نَصْرُ ٱلْمُؤْمِنِينَ', '9d2c35d4bcd17c2bfe20ed9c47c80425278e1777d430b1fb7b0304f558a6357a', '9d2c35d4bcd17c2bfe20ed9c47c80425278e1777d430b1fb7b0304f558a6357a', NULL, 'ولقد ارسلنا من قبلك رسلا الي قومهم فجاءوهم بالبينت فانتقمنا من الذين اجرموا وكان حقا علينا نصر المؤمنين', 21, 41, 163, 1, 5, 409, false, NULL),
    (3457, 'tanzil-uthmani-v1.1', 30, 48, 'ٱللَّهُ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًا فَيَبْسُطُهُۥ فِى ٱلسَّمَآءِ كَيْفَ يَشَآءُ وَيَجْعَلُهُۥ كِسَفًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', '5f2cf8291e024ddaf2146bbd3da7f75f626f7fc0b3cddabb892671648ef26460', 'ٱللَّهُ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًا فَيَبْسُطُهُۥ فِى ٱلسَّمَآءِ كَيْفَ يَشَآءُ وَيَجْعَلُهُۥ كِسَفًا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', '5f2cf8291e024ddaf2146bbd3da7f75f626f7fc0b3cddabb892671648ef26460', '5f2cf8291e024ddaf2146bbd3da7f75f626f7fc0b3cddabb892671648ef26460', NULL, 'الله الذي يرسل الريح فتثير سحابا فيبسطه في السماء كيف يشاء ويجعله كسفا فتري الودق يخرج من خلله فاذا اصاب به من يشاء من عباده اذا هم يستبشرون', 21, 41, 163, 1, 5, 409, false, NULL),
    (3458, 'tanzil-uthmani-v1.1', 30, 49, 'وَإِن كَانُوا۟ مِن قَبْلِ أَن يُنَزَّلَ عَلَيْهِم مِّن قَبْلِهِۦ لَمُبْلِسِينَ', '47e18cc602505df4a491360fed50c255f4f2c3cc801fb0c3caaa3a48f7d2e5cf', 'وَإِن كَانُوا۟ مِن قَبْلِ أَن يُنَزَّلَ عَلَيْهِم مِّن قَبْلِهِۦ لَمُبْلِسِينَ', '47e18cc602505df4a491360fed50c255f4f2c3cc801fb0c3caaa3a48f7d2e5cf', '47e18cc602505df4a491360fed50c255f4f2c3cc801fb0c3caaa3a48f7d2e5cf', NULL, 'وان كانوا من قبل ان ينزل عليهم من قبله لمبلسين', 21, 41, 163, 1, 5, 409, false, NULL),
    (3459, 'tanzil-uthmani-v1.1', 30, 50, 'فَٱنظُرْ إِلَىٰٓ ءَاثَٰرِ رَحْمَتِ ٱللَّهِ كَيْفَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ ذَٰلِكَ لَمُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'de20a10ae7e6df21e9a6088b621931272a77b8f82fa8a5d6c82da79ab68574da', 'فَٱنظُرْ إِلَىٰٓ ءَاثَٰرِ رَحْمَتِ ٱللَّهِ كَيْفَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ إِنَّ ذَٰلِكَ لَمُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'de20a10ae7e6df21e9a6088b621931272a77b8f82fa8a5d6c82da79ab68574da', 'de20a10ae7e6df21e9a6088b621931272a77b8f82fa8a5d6c82da79ab68574da', NULL, 'فانظر الي ءاثر رحمت الله كيف يحي الارض بعد موتها ان ذلك لمحي الموتي وهو علي كل شيء قدير', 21, 41, 163, 1, 5, 409, false, NULL),
    (3460, 'tanzil-uthmani-v1.1', 30, 51, 'وَلَئِنْ أَرْسَلْنَا رِيحًا فَرَأَوْهُ مُصْفَرًّا لَّظَلُّوا۟ مِنۢ بَعْدِهِۦ يَكْفُرُونَ', 'd148713417975bebcaafb7f5e442bf6fb1693acc303c14652068150fa68c0666', 'وَلَئِنْ أَرْسَلْنَا رِيحًا فَرَأَوْهُ مُصْفَرًّا لَّظَلُّوا۟ مِنۢ بَعْدِهِۦ يَكْفُرُونَ', 'd148713417975bebcaafb7f5e442bf6fb1693acc303c14652068150fa68c0666', 'd148713417975bebcaafb7f5e442bf6fb1693acc303c14652068150fa68c0666', NULL, 'ولئن ارسلنا ريحا فراوه مصفرا لظلوا من بعده يكفرون', 21, 41, 163, 1, 5, 410, false, NULL),
    (3461, 'tanzil-uthmani-v1.1', 30, 52, 'فَإِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', 'dd0b222f9f835a3be0492df328f62dcfc7d1e3725b94b01313847e18c3db04eb', 'فَإِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ', 'dd0b222f9f835a3be0492df328f62dcfc7d1e3725b94b01313847e18c3db04eb', 'dd0b222f9f835a3be0492df328f62dcfc7d1e3725b94b01313847e18c3db04eb', NULL, 'فانك لا تسمع الموتي ولا تسمع الصم الدعاء اذا ولوا مدبرين', 21, 41, 163, 1, 5, 410, false, NULL),
    (3462, 'tanzil-uthmani-v1.1', 30, 53, 'وَمَآ أَنتَ بِهَٰدِ ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', '71c20d3574dd0b4210cbf098fdd16b202ad59a2f2154213148596afa6bee9bcd', 'وَمَآ أَنتَ بِهَٰدِ ٱلْعُمْىِ عَن ضَلَٰلَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَٰتِنَا فَهُم مُّسْلِمُونَ', '71c20d3574dd0b4210cbf098fdd16b202ad59a2f2154213148596afa6bee9bcd', '71c20d3574dd0b4210cbf098fdd16b202ad59a2f2154213148596afa6bee9bcd', NULL, 'وما انت بهد العمي عن ضللتهم ان تسمع الا من يؤمن بايتنا فهم مسلمون', 21, 41, 163, 1, 5, 410, false, NULL),
    (3463, 'tanzil-uthmani-v1.1', 30, 54, 'ٱللَّهُ ٱلَّذِى خَلَقَكُم مِّن ضَعْفٍ ثُمَّ جَعَلَ مِنۢ بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنۢ بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً يَخْلُقُ مَا يَشَآءُ وَهُوَ ٱلْعَلِيمُ ٱلْقَدِيرُ', '11515eb2f1ccbe59d28d62f04921d75f562dd77f7a98fbe015e3be193c259cc2', 'ٱللَّهُ ٱلَّذِى خَلَقَكُم مِّن ضَعْفٍ ثُمَّ جَعَلَ مِنۢ بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنۢ بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً يَخْلُقُ مَا يَشَآءُ وَهُوَ ٱلْعَلِيمُ ٱلْقَدِيرُ', '11515eb2f1ccbe59d28d62f04921d75f562dd77f7a98fbe015e3be193c259cc2', '11515eb2f1ccbe59d28d62f04921d75f562dd77f7a98fbe015e3be193c259cc2', NULL, 'الله الذي خلقكم من ضعف ثم جعل من بعد ضعف قوه ثم جعل من بعد قوه ضعفا وشيبه يخلق ما يشاء وهو العليم القدير', 21, 41, 164, 1, 5, 410, false, NULL),
    (3464, 'tanzil-uthmani-v1.1', 30, 55, 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُقْسِمُ ٱلْمُجْرِمُونَ مَا لَبِثُوا۟ غَيْرَ سَاعَةٍ كَذَٰلِكَ كَانُوا۟ يُؤْفَكُونَ', '4def26bc6b3f9ff3794bb7d56b16a31b8e9fbbc146650f36704b5ca2d39e622f', 'وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يُقْسِمُ ٱلْمُجْرِمُونَ مَا لَبِثُوا۟ غَيْرَ سَاعَةٍ كَذَٰلِكَ كَانُوا۟ يُؤْفَكُونَ', '4def26bc6b3f9ff3794bb7d56b16a31b8e9fbbc146650f36704b5ca2d39e622f', '4def26bc6b3f9ff3794bb7d56b16a31b8e9fbbc146650f36704b5ca2d39e622f', NULL, 'ويوم تقوم الساعه يقسم المجرمون ما لبثوا غير ساعه كذلك كانوا يؤفكون', 21, 41, 164, 1, 5, 410, false, NULL),
    (3465, 'tanzil-uthmani-v1.1', 30, 56, 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَٱلْإِيمَٰنَ لَقَدْ لَبِثْتُمْ فِى كِتَٰبِ ٱللَّهِ إِلَىٰ يَوْمِ ٱلْبَعْثِ فَهَٰذَا يَوْمُ ٱلْبَعْثِ وَلَٰكِنَّكُمْ كُنتُمْ لَا تَعْلَمُونَ', '355db1bc99456ea3159f982360cb0ba016fbae4b2b99931794b3dd56f321f4b3', 'وَقَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ وَٱلْإِيمَٰنَ لَقَدْ لَبِثْتُمْ فِى كِتَٰبِ ٱللَّهِ إِلَىٰ يَوْمِ ٱلْبَعْثِ فَهَٰذَا يَوْمُ ٱلْبَعْثِ وَلَٰكِنَّكُمْ كُنتُمْ لَا تَعْلَمُونَ', '355db1bc99456ea3159f982360cb0ba016fbae4b2b99931794b3dd56f321f4b3', '355db1bc99456ea3159f982360cb0ba016fbae4b2b99931794b3dd56f321f4b3', NULL, 'وقال الذين اوتوا العلم والايمن لقد لبثتم في كتب الله الي يوم البعث فهذا يوم البعث ولكنكم كنتم لا تعلمون', 21, 41, 164, 1, 5, 410, false, NULL),
    (3466, 'tanzil-uthmani-v1.1', 30, 57, 'فَيَوْمَئِذٍ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُوا۟ مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ', '7ec65bf9c57316ab1ba1c86070e4bc9c5ba1e72cb7352d1ebb09d5f9313924e3', 'فَيَوْمَئِذٍ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُوا۟ مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ', '7ec65bf9c57316ab1ba1c86070e4bc9c5ba1e72cb7352d1ebb09d5f9313924e3', '7ec65bf9c57316ab1ba1c86070e4bc9c5ba1e72cb7352d1ebb09d5f9313924e3', NULL, 'فيومئذ لا ينفع الذين ظلموا معذرتهم ولا هم يستعتبون', 21, 41, 164, 1, 5, 410, false, NULL),
    (3467, 'tanzil-uthmani-v1.1', 30, 58, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ وَلَئِن جِئْتَهُم بِـَٔايَةٍ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ أَنتُمْ إِلَّا مُبْطِلُونَ', 'ad332ae8a9710b7a8f12e23b39b2685e845c981661771530b090853631cdd5b0', 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ وَلَئِن جِئْتَهُم بِـَٔايَةٍ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ أَنتُمْ إِلَّا مُبْطِلُونَ', 'ad332ae8a9710b7a8f12e23b39b2685e845c981661771530b090853631cdd5b0', 'ad332ae8a9710b7a8f12e23b39b2685e845c981661771530b090853631cdd5b0', NULL, 'ولقد ضربنا للناس في هذا القرءان من كل مثل ولئن جئتهم بايه ليقولن الذين كفروا ان انتم الا مبطلون', 21, 41, 164, 1, 5, 410, false, NULL),
    (3468, 'tanzil-uthmani-v1.1', 30, 59, 'كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعْلَمُونَ', 'f399f2107a6a9773ba346236a0eb1e4113e6c18ea938179df6920a01a1b06052', 'كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعْلَمُونَ', 'f399f2107a6a9773ba346236a0eb1e4113e6c18ea938179df6920a01a1b06052', 'f399f2107a6a9773ba346236a0eb1e4113e6c18ea938179df6920a01a1b06052', NULL, 'كذلك يطبع الله علي قلوب الذين لا يعلمون', 21, 41, 164, 1, 5, 410, false, NULL),
    (3469, 'tanzil-uthmani-v1.1', 30, 60, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَا يَسْتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ', '34bb434d76a458761f07b7e168d922dd51c174e448811bca5444b796c058fc80', 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَلَا يَسْتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ', '34bb434d76a458761f07b7e168d922dd51c174e448811bca5444b796c058fc80', '34bb434d76a458761f07b7e168d922dd51c174e448811bca5444b796c058fc80', NULL, 'فاصبر ان وعد الله حق ولا يستخفنك الذين لا يوقنون', 21, 41, 164, 1, 5, 410, false, NULL),
    (3470, 'tanzil-uthmani-v1.1', 31, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'e190dd3d3d044e6256ebd129866c8631838018200128280a20f27d07491b7e45', 'الٓمٓ', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الم', 21, 41, 164, 1, 5, 411, false, NULL),
    (3471, 'tanzil-uthmani-v1.1', 31, 2, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ', '379d880c8e5864bf4a8d0835b068c676221dbc0c9cc9ab6c572261b1e7e1f10d', 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ', '379d880c8e5864bf4a8d0835b068c676221dbc0c9cc9ab6c572261b1e7e1f10d', '379d880c8e5864bf4a8d0835b068c676221dbc0c9cc9ab6c572261b1e7e1f10d', NULL, 'تلك ءايت الكتب الحكيم', 21, 41, 164, 1, 5, 411, false, NULL),
    (3472, 'tanzil-uthmani-v1.1', 31, 3, 'هُدًى وَرَحْمَةً لِّلْمُحْسِنِينَ', '0835c1e1c732a77cf787e1c332efa8a48eff24a4a1a3628db4e6e3d2ddab9c7f', 'هُدًى وَرَحْمَةً لِّلْمُحْسِنِينَ', '0835c1e1c732a77cf787e1c332efa8a48eff24a4a1a3628db4e6e3d2ddab9c7f', '0835c1e1c732a77cf787e1c332efa8a48eff24a4a1a3628db4e6e3d2ddab9c7f', NULL, 'هدي ورحمه للمحسنين', 21, 41, 164, 1, 5, 411, false, NULL),
    (3473, 'tanzil-uthmani-v1.1', 31, 4, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', '83086c40f75834468b6e8e835e2610c0cca93e606adf21fd2cff1931c578f4de', 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ', '83086c40f75834468b6e8e835e2610c0cca93e606adf21fd2cff1931c578f4de', '83086c40f75834468b6e8e835e2610c0cca93e606adf21fd2cff1931c578f4de', NULL, 'الذين يقيمون الصلوه ويؤتون الزكوه وهم بالاخره هم يوقنون', 21, 41, 164, 1, 5, 411, false, NULL),
    (3474, 'tanzil-uthmani-v1.1', 31, 5, 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '6390ed1e5b1434ecb1ff54ec6cf1802c8b4466045513aad48c6798deafda6c8d', 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '6390ed1e5b1434ecb1ff54ec6cf1802c8b4466045513aad48c6798deafda6c8d', '6390ed1e5b1434ecb1ff54ec6cf1802c8b4466045513aad48c6798deafda6c8d', NULL, 'اولئك علي هدي من ربهم واولئك هم المفلحون', 21, 41, 164, 1, 5, 411, false, NULL),
    (3475, 'tanzil-uthmani-v1.1', 31, 6, 'وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', '68e7709e285a3b444b0b2b0e5a82cbadf463611e9766b216ece389ff011551f5', 'وَمِنَ ٱلنَّاسِ مَن يَشْتَرِى لَهْوَ ٱلْحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', '68e7709e285a3b444b0b2b0e5a82cbadf463611e9766b216ece389ff011551f5', '68e7709e285a3b444b0b2b0e5a82cbadf463611e9766b216ece389ff011551f5', NULL, 'ومن الناس من يشتري لهو الحديث ليضل عن سبيل الله بغير علم ويتخذها هزوا اولئك لهم عذاب مهين', 21, 41, 164, 1, 5, 411, false, NULL),
    (3476, 'tanzil-uthmani-v1.1', 31, 7, 'وَإِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا وَلَّىٰ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا كَأَنَّ فِىٓ أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', '3e1c818ab3d3dbf13ff0277dc83eb476fe338847a08931f7e43527b5db99691e', 'وَإِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا وَلَّىٰ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا كَأَنَّ فِىٓ أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', '3e1c818ab3d3dbf13ff0277dc83eb476fe338847a08931f7e43527b5db99691e', '3e1c818ab3d3dbf13ff0277dc83eb476fe338847a08931f7e43527b5db99691e', NULL, 'واذا تتلي عليه ءايتنا ولي مستكبرا كان لم يسمعها كان في اذنيه وقرا فبشره بعذاب اليم', 21, 41, 164, 1, 5, 411, false, NULL),
    (3477, 'tanzil-uthmani-v1.1', 31, 8, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتُ ٱلنَّعِيمِ', 'cd4e940593e7883d8cf44de87469ef929b49d3d7ea3189860b231356805fb07f', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتُ ٱلنَّعِيمِ', 'cd4e940593e7883d8cf44de87469ef929b49d3d7ea3189860b231356805fb07f', 'cd4e940593e7883d8cf44de87469ef929b49d3d7ea3189860b231356805fb07f', NULL, 'ان الذين ءامنوا وعملوا الصلحت لهم جنت النعيم', 21, 41, 164, 1, 5, 411, false, NULL),
    (3478, 'tanzil-uthmani-v1.1', 31, 9, 'خَٰلِدِينَ فِيهَا وَعْدَ ٱللَّهِ حَقًّا وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '894a21d3914903bd2d2251c9d7e874d5d3f8bb65f5610669646dd393892eaba0', 'خَٰلِدِينَ فِيهَا وَعْدَ ٱللَّهِ حَقًّا وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '894a21d3914903bd2d2251c9d7e874d5d3f8bb65f5610669646dd393892eaba0', '894a21d3914903bd2d2251c9d7e874d5d3f8bb65f5610669646dd393892eaba0', NULL, 'خلدين فيها وعد الله حقا وهو العزيز الحكيم', 21, 41, 164, 1, 5, 411, false, NULL),
    (3479, 'tanzil-uthmani-v1.1', 31, 10, 'خَلَقَ ٱلسَّمَٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', '846b3742d276c85a6ab41d541af501a6f0a5ccccc14f0cf7c5f7976bb7565d1e', 'خَلَقَ ٱلسَّمَٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ', '846b3742d276c85a6ab41d541af501a6f0a5ccccc14f0cf7c5f7976bb7565d1e', '846b3742d276c85a6ab41d541af501a6f0a5ccccc14f0cf7c5f7976bb7565d1e', NULL, 'خلق السموت بغير عمد ترونها والقي في الارض روسي ان تميد بكم وبث فيها من كل دابه وانزلنا من السماء ماء فانبتنا فيها من كل زوج كريم', 21, 41, 164, 1, 5, 411, false, NULL),
    (3480, 'tanzil-uthmani-v1.1', 31, 11, 'هَٰذَا خَلْقُ ٱللَّهِ فَأَرُونِى مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦ بَلِ ٱلظَّٰلِمُونَ فِى ضَلَٰلٍ مُّبِينٍ', 'ff71da1f47eacb69708107e0b61d63f1e159e5d1ced4082160e9f583832fe514', 'هَٰذَا خَلْقُ ٱللَّهِ فَأَرُونِى مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦ بَلِ ٱلظَّٰلِمُونَ فِى ضَلَٰلٍ مُّبِينٍ', 'ff71da1f47eacb69708107e0b61d63f1e159e5d1ced4082160e9f583832fe514', 'ff71da1f47eacb69708107e0b61d63f1e159e5d1ced4082160e9f583832fe514', NULL, 'هذا خلق الله فاروني ماذا خلق الذين من دونه بل الظلمون في ضلل مبين', 21, 41, 164, 1, 5, 411, false, NULL),
    (3481, 'tanzil-uthmani-v1.1', 31, 12, 'وَلَقَدْ ءَاتَيْنَا لُقْمَٰنَ ٱلْحِكْمَةَ أَنِ ٱشْكُرْ لِلَّهِ وَمَن يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', 'ed7f1860394801c2c82342fd1116c37c8d1e744915589227f631eecb54f9119f', 'وَلَقَدْ ءَاتَيْنَا لُقْمَٰنَ ٱلْحِكْمَةَ أَنِ ٱشْكُرْ لِلَّهِ وَمَن يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', 'ed7f1860394801c2c82342fd1116c37c8d1e744915589227f631eecb54f9119f', 'ed7f1860394801c2c82342fd1116c37c8d1e744915589227f631eecb54f9119f', NULL, 'ولقد ءاتينا لقمن الحكمه ان اشكر لله ومن يشكر فانما يشكر لنفسه ومن كفر فان الله غني حميد', 21, 41, 164, 1, 5, 412, false, NULL),
    (3482, 'tanzil-uthmani-v1.1', 31, 13, 'وَإِذْ قَالَ لُقْمَٰنُ لِٱبْنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَىَّ لَا تُشْرِكْ بِٱللَّهِ إِنَّ ٱلشِّرْكَ لَظُلْمٌ عَظِيمٌ', 'af558aa665477f3f5db6193f9eadc3b99100a136e6eb2a5b05b93ba087f6afb2', 'وَإِذْ قَالَ لُقْمَٰنُ لِٱبْنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَىَّ لَا تُشْرِكْ بِٱللَّهِ إِنَّ ٱلشِّرْكَ لَظُلْمٌ عَظِيمٌ', 'af558aa665477f3f5db6193f9eadc3b99100a136e6eb2a5b05b93ba087f6afb2', 'af558aa665477f3f5db6193f9eadc3b99100a136e6eb2a5b05b93ba087f6afb2', NULL, 'واذ قال لقمن لابنه وهو يعظه يبني لا تشرك بالله ان الشرك لظلم عظيم', 21, 41, 164, 1, 5, 412, false, NULL),
    (3483, 'tanzil-uthmani-v1.1', 31, 14, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍ وَفِصَٰلُهُۥ فِى عَامَيْنِ أَنِ ٱشْكُرْ لِى وَلِوَٰلِدَيْكَ إِلَىَّ ٱلْمَصِيرُ', '5d0302ec6499018463fd507704c82cab40e6024adcdd5551e7bb9501bf839fc6', 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍ وَفِصَٰلُهُۥ فِى عَامَيْنِ أَنِ ٱشْكُرْ لِى وَلِوَٰلِدَيْكَ إِلَىَّ ٱلْمَصِيرُ', '5d0302ec6499018463fd507704c82cab40e6024adcdd5551e7bb9501bf839fc6', '5d0302ec6499018463fd507704c82cab40e6024adcdd5551e7bb9501bf839fc6', NULL, 'ووصينا الانسن بولديه حملته امه وهنا علي وهن وفصله في عامين ان اشكر لي ولولديك الي المصير', 21, 41, 164, 1, 5, 412, false, NULL),
    (3484, 'tanzil-uthmani-v1.1', 31, 15, 'وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِى ٱلدُّنْيَا مَعْرُوفًا وَٱتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '782df4e6981a96ead767c7030d088b7634d830ef64ddbe407ea927b3b06e003b', 'وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِى ٱلدُّنْيَا مَعْرُوفًا وَٱتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '782df4e6981a96ead767c7030d088b7634d830ef64ddbe407ea927b3b06e003b', '782df4e6981a96ead767c7030d088b7634d830ef64ddbe407ea927b3b06e003b', NULL, 'وان جهداك علي ان تشرك بي ما ليس لك به علم فلا تطعهما وصاحبهما في الدنيا معروفا واتبع سبيل من اناب الي ثم الي مرجعكم فانبئكم بما كنتم تعملون', 21, 41, 164, 1, 5, 412, false, NULL),
    (3485, 'tanzil-uthmani-v1.1', 31, 16, 'يَٰبُنَىَّ إِنَّهَآ إِن تَكُ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ فَتَكُن فِى صَخْرَةٍ أَوْ فِى ٱلسَّمَٰوَٰتِ أَوْ فِى ٱلْأَرْضِ يَأْتِ بِهَا ٱللَّهُ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', '6d91e63c886f45271cf5e98cfc8c5a7d840bb1d50939e56e4e96f6ae25e90849', 'يَٰبُنَىَّ إِنَّهَآ إِن تَكُ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ فَتَكُن فِى صَخْرَةٍ أَوْ فِى ٱلسَّمَٰوَٰتِ أَوْ فِى ٱلْأَرْضِ يَأْتِ بِهَا ٱللَّهُ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌ', '6d91e63c886f45271cf5e98cfc8c5a7d840bb1d50939e56e4e96f6ae25e90849', '6d91e63c886f45271cf5e98cfc8c5a7d840bb1d50939e56e4e96f6ae25e90849', NULL, 'يبني انها ان تك مثقال حبه من خردل فتكن في صخره او في السموت او في الارض يات بها الله ان الله لطيف خبير', 21, 41, 164, 1, 5, 412, false, NULL),
    (3486, 'tanzil-uthmani-v1.1', 31, 17, 'يَٰبُنَىَّ أَقِمِ ٱلصَّلَوٰةَ وَأْمُرْ بِٱلْمَعْرُوفِ وَٱنْهَ عَنِ ٱلْمُنكَرِ وَٱصْبِرْ عَلَىٰ مَآ أَصَابَكَ إِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', '6e298d9c90f6d80780d4b7a17079895b7999aa8a1ddf2d9ee75c62784bbfc140', 'يَٰبُنَىَّ أَقِمِ ٱلصَّلَوٰةَ وَأْمُرْ بِٱلْمَعْرُوفِ وَٱنْهَ عَنِ ٱلْمُنكَرِ وَٱصْبِرْ عَلَىٰ مَآ أَصَابَكَ إِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', '6e298d9c90f6d80780d4b7a17079895b7999aa8a1ddf2d9ee75c62784bbfc140', '6e298d9c90f6d80780d4b7a17079895b7999aa8a1ddf2d9ee75c62784bbfc140', NULL, 'يبني اقم الصلوه وامر بالمعروف وانه عن المنكر واصبر علي ما اصابك ان ذلك من عزم الامور', 21, 41, 164, 1, 5, 412, false, NULL),
    (3487, 'tanzil-uthmani-v1.1', 31, 18, 'وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', '6a6086898a64c7d0134d667d56657b56563fc6a77835e323f7f551cd7937cd90', 'وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', '6a6086898a64c7d0134d667d56657b56563fc6a77835e323f7f551cd7937cd90', '6a6086898a64c7d0134d667d56657b56563fc6a77835e323f7f551cd7937cd90', NULL, 'ولا تصعر خدك للناس ولا تمش في الارض مرحا ان الله لا يحب كل مختال فخور', 21, 41, 164, 1, 5, 412, false, NULL),
    (3488, 'tanzil-uthmani-v1.1', 31, 19, 'وَٱقْصِدْ فِى مَشْيِكَ وَٱغْضُضْ مِن صَوْتِكَ إِنَّ أَنكَرَ ٱلْأَصْوَٰتِ لَصَوْتُ ٱلْحَمِيرِ', '94e5a389cb0aeb9d9f665aa83e59e36ddced41fc7d99ec655bd64948764aba1d', 'وَٱقْصِدْ فِى مَشْيِكَ وَٱغْضُضْ مِن صَوْتِكَ إِنَّ أَنكَرَ ٱلْأَصْوَٰتِ لَصَوْتُ ٱلْحَمِيرِ', '94e5a389cb0aeb9d9f665aa83e59e36ddced41fc7d99ec655bd64948764aba1d', '94e5a389cb0aeb9d9f665aa83e59e36ddced41fc7d99ec655bd64948764aba1d', NULL, 'واقصد في مشيك واغضض من صوتك ان انكر الاصوت لصوت الحمير', 21, 41, 164, 1, 5, 412, false, NULL),
    (3489, 'tanzil-uthmani-v1.1', 31, 20, 'أَلَمْ تَرَوْا۟ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُۥ ظَٰهِرَةً وَبَاطِنَةً وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَٰبٍ مُّنِيرٍ', '9a4b5ac59d880e0a0ad6d5cbd2cabf9307cb01f69e011c0dcf1017a04202fa92', 'أَلَمْ تَرَوْا۟ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُۥ ظَٰهِرَةً وَبَاطِنَةً وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَٰبٍ مُّنِيرٍ', '9a4b5ac59d880e0a0ad6d5cbd2cabf9307cb01f69e011c0dcf1017a04202fa92', '9a4b5ac59d880e0a0ad6d5cbd2cabf9307cb01f69e011c0dcf1017a04202fa92', NULL, 'الم تروا ان الله سخر لكم ما في السموت وما في الارض واسبغ عليكم نعمه ظهره وباطنه ومن الناس من يجدل في الله بغير علم ولا هدي ولا كتب منير', 21, 41, 164, 1, 5, 413, false, NULL),
    (3490, 'tanzil-uthmani-v1.1', 31, 21, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ٱلشَّيْطَٰنُ يَدْعُوهُمْ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 'c880093e15304fbd3e8e3f7aa8e0b51ea4b0b26573c7cbb30ab27d96a72f7ae3', 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ٱلشَّيْطَٰنُ يَدْعُوهُمْ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 'c880093e15304fbd3e8e3f7aa8e0b51ea4b0b26573c7cbb30ab27d96a72f7ae3', 'c880093e15304fbd3e8e3f7aa8e0b51ea4b0b26573c7cbb30ab27d96a72f7ae3', NULL, 'واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما وجدنا عليه ءاباءنا اولو كان الشيطن يدعوهم الي عذاب السعير', 21, 41, 164, 1, 5, 413, false, NULL),
    (3491, 'tanzil-uthmani-v1.1', 31, 22, 'وَمَن يُسْلِمْ وَجْهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحْسِنٌ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلْأُمُورِ', '09fd8d919b1fad9485b7dd4080fe8adf43a9b170fb154be315dc4f020c272726', 'وَمَن يُسْلِمْ وَجْهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحْسِنٌ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلْأُمُورِ', '09fd8d919b1fad9485b7dd4080fe8adf43a9b170fb154be315dc4f020c272726', '09fd8d919b1fad9485b7dd4080fe8adf43a9b170fb154be315dc4f020c272726', NULL, 'ومن يسلم وجهه الي الله وهو محسن فقد استمسك بالعروه الوثقي والي الله عقبه الامور', 21, 42, 165, 1, 5, 413, false, NULL),
    (3492, 'tanzil-uthmani-v1.1', 31, 23, 'وَمَن كَفَرَ فَلَا يَحْزُنكَ كُفْرُهُۥٓ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُم بِمَا عَمِلُوٓا۟ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'a70f549ac82996d9f4f92758bea73cd5fa84b9931ee3f7768e2d430cdacab01a', 'وَمَن كَفَرَ فَلَا يَحْزُنكَ كُفْرُهُۥٓ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُم بِمَا عَمِلُوٓا۟ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 'a70f549ac82996d9f4f92758bea73cd5fa84b9931ee3f7768e2d430cdacab01a', 'a70f549ac82996d9f4f92758bea73cd5fa84b9931ee3f7768e2d430cdacab01a', NULL, 'ومن كفر فلا يحزنك كفره الينا مرجعهم فننبئهم بما عملوا ان الله عليم بذات الصدور', 21, 42, 165, 1, 5, 413, false, NULL),
    (3493, 'tanzil-uthmani-v1.1', 31, 24, 'نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍ', '78fba0c186f059aee42e117b8eb266c3c48ed5402d7b47b4a3d4b647180bcdc6', 'نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍ', '78fba0c186f059aee42e117b8eb266c3c48ed5402d7b47b4a3d4b647180bcdc6', '78fba0c186f059aee42e117b8eb266c3c48ed5402d7b47b4a3d4b647180bcdc6', NULL, 'نمتعهم قليلا ثم نضطرهم الي عذاب غليظ', 21, 42, 165, 1, 5, 413, false, NULL),
    (3494, 'tanzil-uthmani-v1.1', 31, 25, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ قُلِ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '9d487edb037f01ac6977bdd4b214c6f355b1c6775f0968f067386457cb4b73ee', 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ قُلِ ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '9d487edb037f01ac6977bdd4b214c6f355b1c6775f0968f067386457cb4b73ee', '9d487edb037f01ac6977bdd4b214c6f355b1c6775f0968f067386457cb4b73ee', NULL, 'ولئن سالتهم من خلق السموت والارض ليقولن الله قل الحمد لله بل اكثرهم لا يعلمون', 21, 42, 165, 1, 5, 413, false, NULL),
    (3495, 'tanzil-uthmani-v1.1', 31, 26, 'لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '66dccc803f285b175d046b60c61c70f56906cc316517f07d654200b86119a4e0', 'لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '66dccc803f285b175d046b60c61c70f56906cc316517f07d654200b86119a4e0', '66dccc803f285b175d046b60c61c70f56906cc316517f07d654200b86119a4e0', NULL, 'لله ما في السموت والارض ان الله هو الغني الحميد', 21, 42, 165, 1, 5, 413, false, NULL),
    (3496, 'tanzil-uthmani-v1.1', 31, 27, 'وَلَوْ أَنَّمَا فِى ٱلْأَرْضِ مِن شَجَرَةٍ أَقْلَٰمٌ وَٱلْبَحْرُ يَمُدُّهُۥ مِنۢ بَعْدِهِۦ سَبْعَةُ أَبْحُرٍ مَّا نَفِدَتْ كَلِمَٰتُ ٱللَّهِ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'be2eb9211ec20489b5fdba1d9397d3d168f0c306c6bc05cf7b128abbf91b27bc', 'وَلَوْ أَنَّمَا فِى ٱلْأَرْضِ مِن شَجَرَةٍ أَقْلَٰمٌ وَٱلْبَحْرُ يَمُدُّهُۥ مِنۢ بَعْدِهِۦ سَبْعَةُ أَبْحُرٍ مَّا نَفِدَتْ كَلِمَٰتُ ٱللَّهِ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 'be2eb9211ec20489b5fdba1d9397d3d168f0c306c6bc05cf7b128abbf91b27bc', 'be2eb9211ec20489b5fdba1d9397d3d168f0c306c6bc05cf7b128abbf91b27bc', NULL, 'ولو انما في الارض من شجره اقلم والبحر يمده من بعده سبعه ابحر ما نفدت كلمت الله ان الله عزيز حكيم', 21, 42, 165, 1, 5, 413, false, NULL),
    (3497, 'tanzil-uthmani-v1.1', 31, 28, 'مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَٰحِدَةٍ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', '93ab4eb79780cb3fa4f9f7584dd42f61794d363c1cdf2028fcc7c1c44ee53530', 'مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَٰحِدَةٍ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', '93ab4eb79780cb3fa4f9f7584dd42f61794d363c1cdf2028fcc7c1c44ee53530', '93ab4eb79780cb3fa4f9f7584dd42f61794d363c1cdf2028fcc7c1c44ee53530', NULL, 'ما خلقكم ولا بعثكم الا كنفس وحده ان الله سميع بصير', 21, 42, 165, 1, 5, 413, false, NULL),
    (3498, 'tanzil-uthmani-v1.1', 31, 29, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِىٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى وَأَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌ', 'c0824397107becad1c9c1643caba5b13d55304d3d38bd4c557d30f67c8eb3570', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِىٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى وَأَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌ', 'c0824397107becad1c9c1643caba5b13d55304d3d38bd4c557d30f67c8eb3570', 'c0824397107becad1c9c1643caba5b13d55304d3d38bd4c557d30f67c8eb3570', NULL, 'الم تر ان الله يولج اليل في النهار ويولج النهار في اليل وسخر الشمس والقمر كل يجري الي اجل مسمي وان الله بما تعملون خبير', 21, 42, 165, 1, 5, 414, false, NULL),
    (3499, 'tanzil-uthmani-v1.1', 31, 30, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'c0c72b103f6b5ec8404e6d4c1dfd8843a400e1aca73e67333f3bb18b037e39b4', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 'c0c72b103f6b5ec8404e6d4c1dfd8843a400e1aca73e67333f3bb18b037e39b4', 'c0c72b103f6b5ec8404e6d4c1dfd8843a400e1aca73e67333f3bb18b037e39b4', NULL, 'ذلك بان الله هو الحق وان ما يدعون من دونه البطل وان الله هو العلي الكبير', 21, 42, 165, 1, 5, 414, false, NULL),
    (3500, 'tanzil-uthmani-v1.1', 31, 31, 'أَلَمْ تَرَ أَنَّ ٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِنِعْمَتِ ٱللَّهِ لِيُرِيَكُم مِّنْ ءَايَٰتِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'cd6b0673f7a496ac7aa76108c0a17b6611625114240d04207a2f98357cf6518a', 'أَلَمْ تَرَ أَنَّ ٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِنِعْمَتِ ٱللَّهِ لِيُرِيَكُم مِّنْ ءَايَٰتِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'cd6b0673f7a496ac7aa76108c0a17b6611625114240d04207a2f98357cf6518a', 'cd6b0673f7a496ac7aa76108c0a17b6611625114240d04207a2f98357cf6518a', NULL, 'الم تر ان الفلك تجري في البحر بنعمت الله ليريكم من ءايته ان في ذلك لايت لكل صبار شكور', 21, 42, 165, 1, 5, 414, false, NULL)
