    (3501, 'tanzil-uthmani-v1.1', 31, 32, 'وَإِذَا غَشِيَهُم مَّوْجٌ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ فَمِنْهُم مُّقْتَصِدٌ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٍ كَفُورٍ', '85f67e57ec98ef03f18e3f5b298fdc3f33f0be34b7f16a9fd75b30b5bc71f5db', 'وَإِذَا غَشِيَهُم مَّوْجٌ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ فَمِنْهُم مُّقْتَصِدٌ وَمَا يَجْحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٍ كَفُورٍ', '85f67e57ec98ef03f18e3f5b298fdc3f33f0be34b7f16a9fd75b30b5bc71f5db', '85f67e57ec98ef03f18e3f5b298fdc3f33f0be34b7f16a9fd75b30b5bc71f5db', NULL, 'واذا غشيهم موج كالظلل دعوا الله مخلصين له الدين فلما نجيهم الي البر فمنهم مقتصد وما يجحد بايتنا الا كل ختار كفور', 21, 42, 165, 1, 5, 414, false, NULL),
    (3502, 'tanzil-uthmani-v1.1', 31, 33, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ وَٱخْشَوْا۟ يَوْمًا لَّا يَجْزِى وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيْـًٔا إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'c050ed2bcc7f7aaa2105c3ade5e5a4bfdfa0b03f093b3c702390dfb1ef985bdd', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ وَٱخْشَوْا۟ يَوْمًا لَّا يَجْزِى وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيْـًٔا إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'c050ed2bcc7f7aaa2105c3ade5e5a4bfdfa0b03f093b3c702390dfb1ef985bdd', 'c050ed2bcc7f7aaa2105c3ade5e5a4bfdfa0b03f093b3c702390dfb1ef985bdd', NULL, 'يايها الناس اتقوا ربكم واخشوا يوما لا يجزي والد عن ولده ولا مولود هو جاز عن والده شيا ان وعد الله حق فلا تغرنكم الحيوه الدنيا ولا يغرنكم بالله الغرور', 21, 42, 165, 1, 5, 414, false, NULL),
    (3503, 'tanzil-uthmani-v1.1', 31, 34, 'إِنَّ ٱللَّهَ عِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلْغَيْثَ وَيَعْلَمُ مَا فِى ٱلْأَرْحَامِ وَمَا تَدْرِى نَفْسٌ مَّاذَا تَكْسِبُ غَدًا وَمَا تَدْرِى نَفْسٌۢ بِأَىِّ أَرْضٍ تَمُوتُ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌۢ', 'ac428931ee3a0a1635593023fe02faf3371f478d4b7a61d6ebe018a3edc74600', 'إِنَّ ٱللَّهَ عِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلْغَيْثَ وَيَعْلَمُ مَا فِى ٱلْأَرْحَامِ وَمَا تَدْرِى نَفْسٌ مَّاذَا تَكْسِبُ غَدًا وَمَا تَدْرِى نَفْسٌۢ بِأَىِّ أَرْضٍ تَمُوتُ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌۢ', 'ac428931ee3a0a1635593023fe02faf3371f478d4b7a61d6ebe018a3edc74600', 'ac428931ee3a0a1635593023fe02faf3371f478d4b7a61d6ebe018a3edc74600', NULL, 'ان الله عنده علم الساعه وينزل الغيث ويعلم ما في الارحام وما تدري نفس ماذا تكسب غدا وما تدري نفس باي ارض تموت ان الله عليم خبير', 21, 42, 165, 1, 5, 414, false, NULL),
    (3504, 'tanzil-uthmani-v1.1', 32, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 'e190dd3d3d044e6256ebd129866c8631838018200128280a20f27d07491b7e45', 'الٓمٓ', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', '49c5355bd921dc0d810e3be457432004847a72d5dbe754562be895be707be6c3', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الم', 21, 42, 165, 1, 5, 415, false, NULL),
    (3505, 'tanzil-uthmani-v1.1', 32, 2, 'تَنزِيلُ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', '0e7d6846e68486e451af5d69e7996e9b89181029b497cf2c88e966ad1ced24bf', 'تَنزِيلُ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', '0e7d6846e68486e451af5d69e7996e9b89181029b497cf2c88e966ad1ced24bf', '0e7d6846e68486e451af5d69e7996e9b89181029b497cf2c88e966ad1ced24bf', NULL, 'تنزيل الكتب لا ريب فيه من رب العلمين', 21, 42, 165, 1, 5, 415, false, NULL),
    (3506, 'tanzil-uthmani-v1.1', 32, 3, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ بَلْ هُوَ ٱلْحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ', 'e32f0222919d44262948b4d47fcb93d7f611f0a4385b720e7b72c12946bc5a11', 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ بَلْ هُوَ ٱلْحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ', 'e32f0222919d44262948b4d47fcb93d7f611f0a4385b720e7b72c12946bc5a11', 'e32f0222919d44262948b4d47fcb93d7f611f0a4385b720e7b72c12946bc5a11', NULL, 'ام يقولون افتريه بل هو الحق من ربك لتنذر قوما ما اتيهم من نذير من قبلك لعلهم يهتدون', 21, 42, 165, 1, 5, 415, false, NULL),
    (3507, 'tanzil-uthmani-v1.1', 32, 4, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ مَا لَكُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا شَفِيعٍ أَفَلَا تَتَذَكَّرُونَ', '0e0dbf3953f277c6c47e7805a444c439b2f024ce274ada0ac575b3791c0d87bb', 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ مَا لَكُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا شَفِيعٍ أَفَلَا تَتَذَكَّرُونَ', '0e0dbf3953f277c6c47e7805a444c439b2f024ce274ada0ac575b3791c0d87bb', '0e0dbf3953f277c6c47e7805a444c439b2f024ce274ada0ac575b3791c0d87bb', NULL, 'الله الذي خلق السموت والارض وما بينهما في سته ايام ثم استوي علي العرش ما لكم من دونه من ولي ولا شفيع افلا تتذكرون', 21, 42, 165, 1, 5, 415, false, NULL),
    (3508, 'tanzil-uthmani-v1.1', 32, 5, 'يُدَبِّرُ ٱلْأَمْرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥٓ أَلْفَ سَنَةٍ مِّمَّا تَعُدُّونَ', '51a9d8bb165d515ad698aeb4f50e7ba358ed287d9c7a535a892c2497cbe52ed7', 'يُدَبِّرُ ٱلْأَمْرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥٓ أَلْفَ سَنَةٍ مِّمَّا تَعُدُّونَ', '51a9d8bb165d515ad698aeb4f50e7ba358ed287d9c7a535a892c2497cbe52ed7', '51a9d8bb165d515ad698aeb4f50e7ba358ed287d9c7a535a892c2497cbe52ed7', NULL, 'يدبر الامر من السماء الي الارض ثم يعرج اليه في يوم كان مقداره الف سنه مما تعدون', 21, 42, 165, 1, 5, 415, false, NULL),
    (3509, 'tanzil-uthmani-v1.1', 32, 6, 'ذَٰلِكَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلرَّحِيمُ', '96e0e67d6f1e4e37e4cc57e0cdcd54221e9240b6ef107dc50528134de3e5fd50', 'ذَٰلِكَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلرَّحِيمُ', '96e0e67d6f1e4e37e4cc57e0cdcd54221e9240b6ef107dc50528134de3e5fd50', '96e0e67d6f1e4e37e4cc57e0cdcd54221e9240b6ef107dc50528134de3e5fd50', NULL, 'ذلك علم الغيب والشهده العزيز الرحيم', 21, 42, 165, 1, 5, 415, false, NULL),
    (3510, 'tanzil-uthmani-v1.1', 32, 7, 'ٱلَّذِىٓ أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُۥ وَبَدَأَ خَلْقَ ٱلْإِنسَٰنِ مِن طِينٍ', '06687c4cacd29b9b34884caf0411dbe543c89ab90ec5f07713e5a9cf0cc0c51a', 'ٱلَّذِىٓ أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُۥ وَبَدَأَ خَلْقَ ٱلْإِنسَٰنِ مِن طِينٍ', '06687c4cacd29b9b34884caf0411dbe543c89ab90ec5f07713e5a9cf0cc0c51a', '06687c4cacd29b9b34884caf0411dbe543c89ab90ec5f07713e5a9cf0cc0c51a', NULL, 'الذي احسن كل شيء خلقه وبدا خلق الانسن من طين', 21, 42, 165, 1, 5, 415, false, NULL),
    (3511, 'tanzil-uthmani-v1.1', 32, 8, 'ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَٰلَةٍ مِّن مَّآءٍ مَّهِينٍ', '2d6c1e7b0c22813e00a81dc4cdfdd3636a4b060065eacd84c8d1ab82365463b6', 'ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَٰلَةٍ مِّن مَّآءٍ مَّهِينٍ', '2d6c1e7b0c22813e00a81dc4cdfdd3636a4b060065eacd84c8d1ab82365463b6', '2d6c1e7b0c22813e00a81dc4cdfdd3636a4b060065eacd84c8d1ab82365463b6', NULL, 'ثم جعل نسله من سلله من ماء مهين', 21, 42, 165, 1, 5, 415, false, NULL),
    (3512, 'tanzil-uthmani-v1.1', 32, 9, 'ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', '174d7d8f58807156db9610fd0e50328f69b53c3d025fd0eb2b7f9752ac47f57f', 'ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', '174d7d8f58807156db9610fd0e50328f69b53c3d025fd0eb2b7f9752ac47f57f', '174d7d8f58807156db9610fd0e50328f69b53c3d025fd0eb2b7f9752ac47f57f', NULL, 'ثم سويه ونفخ فيه من روحه وجعل لكم السمع والابصر والافده قليلا ما تشكرون', 21, 42, 165, 1, 5, 415, false, NULL),
    (3513, 'tanzil-uthmani-v1.1', 32, 10, 'وَقَالُوٓا۟ أَءِذَا ضَلَلْنَا فِى ٱلْأَرْضِ أَءِنَّا لَفِى خَلْقٍ جَدِيدٍۭ بَلْ هُم بِلِقَآءِ رَبِّهِمْ كَٰفِرُونَ', '66ea87b42381448198571f31f7fbdd6757af234e08f8b7d47c59d6513c3aa489', 'وَقَالُوٓا۟ أَءِذَا ضَلَلْنَا فِى ٱلْأَرْضِ أَءِنَّا لَفِى خَلْقٍ جَدِيدٍۭ بَلْ هُم بِلِقَآءِ رَبِّهِمْ كَٰفِرُونَ', '66ea87b42381448198571f31f7fbdd6757af234e08f8b7d47c59d6513c3aa489', '66ea87b42381448198571f31f7fbdd6757af234e08f8b7d47c59d6513c3aa489', NULL, 'وقالوا اءذا ضللنا في الارض اءنا لفي خلق جديد بل هم بلقاء ربهم كفرون', 21, 42, 165, 1, 5, 415, false, NULL),
    (3514, 'tanzil-uthmani-v1.1', 32, 11, 'قُلْ يَتَوَفَّىٰكُم مَّلَكُ ٱلْمَوْتِ ٱلَّذِى وُكِّلَ بِكُمْ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', '7f3586217615fd02f23008ebe02969617f001cd6c706cf2041f6363566e8bbff', 'قُلْ يَتَوَفَّىٰكُم مَّلَكُ ٱلْمَوْتِ ٱلَّذِى وُكِّلَ بِكُمْ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', '7f3586217615fd02f23008ebe02969617f001cd6c706cf2041f6363566e8bbff', '7f3586217615fd02f23008ebe02969617f001cd6c706cf2041f6363566e8bbff', NULL, 'قل يتوفيكم ملك الموت الذي وكل بكم ثم الي ربكم ترجعون', 21, 42, 166, 1, 5, 415, false, NULL),
    (3515, 'tanzil-uthmani-v1.1', 32, 12, 'وَلَوْ تَرَىٰٓ إِذِ ٱلْمُجْرِمُونَ نَاكِسُوا۟ رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَٱرْجِعْنَا نَعْمَلْ صَٰلِحًا إِنَّا مُوقِنُونَ', 'd27f1c07b17e1eb71d3096296e1663d5f117ff4955bb55313555fb4d3d9ce52b', 'وَلَوْ تَرَىٰٓ إِذِ ٱلْمُجْرِمُونَ نَاكِسُوا۟ رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَٱرْجِعْنَا نَعْمَلْ صَٰلِحًا إِنَّا مُوقِنُونَ', 'd27f1c07b17e1eb71d3096296e1663d5f117ff4955bb55313555fb4d3d9ce52b', 'd27f1c07b17e1eb71d3096296e1663d5f117ff4955bb55313555fb4d3d9ce52b', NULL, 'ولو تري اذ المجرمون ناكسوا رءوسهم عند ربهم ربنا ابصرنا وسمعنا فارجعنا نعمل صلحا انا موقنون', 21, 42, 166, 1, 5, 416, false, NULL),
    (3516, 'tanzil-uthmani-v1.1', 32, 13, 'وَلَوْ شِئْنَا لَـَٔاتَيْنَا كُلَّ نَفْسٍ هُدَىٰهَا وَلَٰكِنْ حَقَّ ٱلْقَوْلُ مِنِّى لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', 'a6ac7f3e22ece348c6f25babb777933683feed79f92e62ad473dad1a55397df3', 'وَلَوْ شِئْنَا لَـَٔاتَيْنَا كُلَّ نَفْسٍ هُدَىٰهَا وَلَٰكِنْ حَقَّ ٱلْقَوْلُ مِنِّى لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', 'a6ac7f3e22ece348c6f25babb777933683feed79f92e62ad473dad1a55397df3', 'a6ac7f3e22ece348c6f25babb777933683feed79f92e62ad473dad1a55397df3', NULL, 'ولو شئنا لاتينا كل نفس هديها ولكن حق القول مني لاملان جهنم من الجنه والناس اجمعين', 21, 42, 166, 1, 5, 416, false, NULL),
    (3517, 'tanzil-uthmani-v1.1', 32, 14, 'فَذُوقُوا۟ بِمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَآ إِنَّا نَسِينَٰكُمْ وَذُوقُوا۟ عَذَابَ ٱلْخُلْدِ بِمَا كُنتُمْ تَعْمَلُونَ', '8e56d8ac1c49eec81f86cb9a47fa9ec5fd47e5fc7588c5135c019ee6f0c04948', 'فَذُوقُوا۟ بِمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَآ إِنَّا نَسِينَٰكُمْ وَذُوقُوا۟ عَذَابَ ٱلْخُلْدِ بِمَا كُنتُمْ تَعْمَلُونَ', '8e56d8ac1c49eec81f86cb9a47fa9ec5fd47e5fc7588c5135c019ee6f0c04948', '8e56d8ac1c49eec81f86cb9a47fa9ec5fd47e5fc7588c5135c019ee6f0c04948', NULL, 'فذوقوا بما نسيتم لقاء يومكم هذا انا نسينكم وذوقوا عذاب الخلد بما كنتم تعملون', 21, 42, 166, 1, 5, 416, false, NULL),
    (3518, 'tanzil-uthmani-v1.1', 32, 15, 'إِنَّمَا يُؤْمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِهَا خَرُّوا۟ سُجَّدًا وَسَبَّحُوا۟ بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ', 'f3e361a01dfb8b3a0f4859e53a4b30711ecfb99a425919b9d89f96bfdde75252', 'إِنَّمَا يُؤْمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِهَا خَرُّوا۟ سُجَّدًا وَسَبَّحُوا۟ بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ', 'f3e361a01dfb8b3a0f4859e53a4b30711ecfb99a425919b9d89f96bfdde75252', 'f3e361a01dfb8b3a0f4859e53a4b30711ecfb99a425919b9d89f96bfdde75252', NULL, 'انما يؤمن بايتنا الذين اذا ذكروا بها خروا سجدا وسبحوا بحمد ربهم وهم لا يستكبرون', 21, 42, 166, 1, 5, 416, true, 'obligatory'),
    (3519, 'tanzil-uthmani-v1.1', 32, 16, 'تَتَجَافَىٰ جُنُوبُهُمْ عَنِ ٱلْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'e75aee63fdb5742a0b858b670eec8437890bafbdd94e9d2021160f88ed454cad', 'تَتَجَافَىٰ جُنُوبُهُمْ عَنِ ٱلْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 'e75aee63fdb5742a0b858b670eec8437890bafbdd94e9d2021160f88ed454cad', 'e75aee63fdb5742a0b858b670eec8437890bafbdd94e9d2021160f88ed454cad', NULL, 'تتجافي جنوبهم عن المضاجع يدعون ربهم خوفا وطمعا ومما رزقنهم ينفقون', 21, 42, 166, 1, 5, 416, false, NULL),
    (3520, 'tanzil-uthmani-v1.1', 32, 17, 'فَلَا تَعْلَمُ نَفْسٌ مَّآ أُخْفِىَ لَهُم مِّن قُرَّةِ أَعْيُنٍ جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', '0ffceb237eeb6824611388e80917714bad232b6a88019abe3aa688eabd2b87b1', 'فَلَا تَعْلَمُ نَفْسٌ مَّآ أُخْفِىَ لَهُم مِّن قُرَّةِ أَعْيُنٍ جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', '0ffceb237eeb6824611388e80917714bad232b6a88019abe3aa688eabd2b87b1', '0ffceb237eeb6824611388e80917714bad232b6a88019abe3aa688eabd2b87b1', NULL, 'فلا تعلم نفس ما اخفي لهم من قره اعين جزاء بما كانوا يعملون', 21, 42, 166, 1, 5, 416, false, NULL),
    (3521, 'tanzil-uthmani-v1.1', 32, 18, 'أَفَمَن كَانَ مُؤْمِنًا كَمَن كَانَ فَاسِقًا لَّا يَسْتَوُۥنَ', '65c82bd2325821a7ada7211df4304376007bf324bea34a1c28c587b65f359b74', 'أَفَمَن كَانَ مُؤْمِنًا كَمَن كَانَ فَاسِقًا لَّا يَسْتَوُۥنَ', '65c82bd2325821a7ada7211df4304376007bf324bea34a1c28c587b65f359b74', '65c82bd2325821a7ada7211df4304376007bf324bea34a1c28c587b65f359b74', NULL, 'افمن كان مؤمنا كمن كان فاسقا لا يستون', 21, 42, 166, 1, 5, 416, false, NULL),
    (3522, 'tanzil-uthmani-v1.1', 32, 19, 'أَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ جَنَّٰتُ ٱلْمَأْوَىٰ نُزُلًۢا بِمَا كَانُوا۟ يَعْمَلُونَ', 'efd393c0738d33f71b196dcbd6f4087c22e25abda13150f61acdccea2075c693', 'أَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ جَنَّٰتُ ٱلْمَأْوَىٰ نُزُلًۢا بِمَا كَانُوا۟ يَعْمَلُونَ', 'efd393c0738d33f71b196dcbd6f4087c22e25abda13150f61acdccea2075c693', 'efd393c0738d33f71b196dcbd6f4087c22e25abda13150f61acdccea2075c693', NULL, 'اما الذين ءامنوا وعملوا الصلحت فلهم جنت الماوي نزلا بما كانوا يعملون', 21, 42, 166, 1, 5, 416, false, NULL),
    (3523, 'tanzil-uthmani-v1.1', 32, 20, 'وَأَمَّا ٱلَّذِينَ فَسَقُوا۟ فَمَأْوَىٰهُمُ ٱلنَّارُ كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَآ أُعِيدُوا۟ فِيهَا وَقِيلَ لَهُمْ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', '446bc19aaf841f562aeb2079d1637ffe1070b39d9bc94318cc20f4573fb73611', 'وَأَمَّا ٱلَّذِينَ فَسَقُوا۟ فَمَأْوَىٰهُمُ ٱلنَّارُ كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَآ أُعِيدُوا۟ فِيهَا وَقِيلَ لَهُمْ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', '446bc19aaf841f562aeb2079d1637ffe1070b39d9bc94318cc20f4573fb73611', '446bc19aaf841f562aeb2079d1637ffe1070b39d9bc94318cc20f4573fb73611', NULL, 'واما الذين فسقوا فماويهم النار كلما ارادوا ان يخرجوا منها اعيدوا فيها وقيل لهم ذوقوا عذاب النار الذي كنتم به تكذبون', 21, 42, 166, 1, 5, 416, false, NULL),
    (3524, 'tanzil-uthmani-v1.1', 32, 21, 'وَلَنُذِيقَنَّهُم مِّنَ ٱلْعَذَابِ ٱلْأَدْنَىٰ دُونَ ٱلْعَذَابِ ٱلْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ', '4de67504788b49c65dc00a4b6bc85761431cc828edc5916a9b639330f8c186b3', 'وَلَنُذِيقَنَّهُم مِّنَ ٱلْعَذَابِ ٱلْأَدْنَىٰ دُونَ ٱلْعَذَابِ ٱلْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ', '4de67504788b49c65dc00a4b6bc85761431cc828edc5916a9b639330f8c186b3', '4de67504788b49c65dc00a4b6bc85761431cc828edc5916a9b639330f8c186b3', NULL, 'ولنذيقنهم من العذاب الادني دون العذاب الاكبر لعلهم يرجعون', 21, 42, 166, 1, 5, 417, false, NULL),
    (3525, 'tanzil-uthmani-v1.1', 32, 22, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعْرَضَ عَنْهَآ إِنَّا مِنَ ٱلْمُجْرِمِينَ مُنتَقِمُونَ', '655ae1b3728acc4341e5f3bc86a645c728a5de2c75446938c9aefbcba2b76d87', 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعْرَضَ عَنْهَآ إِنَّا مِنَ ٱلْمُجْرِمِينَ مُنتَقِمُونَ', '655ae1b3728acc4341e5f3bc86a645c728a5de2c75446938c9aefbcba2b76d87', '655ae1b3728acc4341e5f3bc86a645c728a5de2c75446938c9aefbcba2b76d87', NULL, 'ومن اظلم ممن ذكر بايت ربه ثم اعرض عنها انا من المجرمين منتقمون', 21, 42, 166, 1, 5, 417, false, NULL),
    (3526, 'tanzil-uthmani-v1.1', 32, 23, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَلَا تَكُن فِى مِرْيَةٍ مِّن لِّقَآئِهِۦ وَجَعَلْنَٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ', 'a07cc25977f29fd8d817b6ef6711edb1ac1d81a1ec6243a59fb3896aad83ae26', 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَلَا تَكُن فِى مِرْيَةٍ مِّن لِّقَآئِهِۦ وَجَعَلْنَٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ', 'a07cc25977f29fd8d817b6ef6711edb1ac1d81a1ec6243a59fb3896aad83ae26', 'a07cc25977f29fd8d817b6ef6711edb1ac1d81a1ec6243a59fb3896aad83ae26', NULL, 'ولقد ءاتينا موسي الكتب فلا تكن في مريه من لقائه وجعلنه هدي لبني اسرءيل', 21, 42, 166, 1, 5, 417, false, NULL),
    (3527, 'tanzil-uthmani-v1.1', 32, 24, 'وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا۟ وَكَانُوا۟ بِـَٔايَٰتِنَا يُوقِنُونَ', 'a038407389cfb0ae771e5d848c46b8390d57dc5ef43f829d5b6626f78196c1a5', 'وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا۟ وَكَانُوا۟ بِـَٔايَٰتِنَا يُوقِنُونَ', 'a038407389cfb0ae771e5d848c46b8390d57dc5ef43f829d5b6626f78196c1a5', 'a038407389cfb0ae771e5d848c46b8390d57dc5ef43f829d5b6626f78196c1a5', NULL, 'وجعلنا منهم ائمه يهدون بامرنا لما صبروا وكانوا بايتنا يوقنون', 21, 42, 166, 1, 5, 417, false, NULL),
    (3528, 'tanzil-uthmani-v1.1', 32, 25, 'إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '26c16046b9719e632c9476b5c31e477dc68a5cbb21ba1de4796536cef2361ab3', 'إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '26c16046b9719e632c9476b5c31e477dc68a5cbb21ba1de4796536cef2361ab3', '26c16046b9719e632c9476b5c31e477dc68a5cbb21ba1de4796536cef2361ab3', NULL, 'ان ربك هو يفصل بينهم يوم القيمه فيما كانوا فيه يختلفون', 21, 42, 166, 1, 5, 417, false, NULL),
    (3529, 'tanzil-uthmani-v1.1', 32, 26, 'أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ أَفَلَا يَسْمَعُونَ', '099ef48334ff0bfb3e4361a0be4c845dbdad1941b7b247b1edef355a76e4cb22', 'أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ أَفَلَا يَسْمَعُونَ', '099ef48334ff0bfb3e4361a0be4c845dbdad1941b7b247b1edef355a76e4cb22', '099ef48334ff0bfb3e4361a0be4c845dbdad1941b7b247b1edef355a76e4cb22', NULL, 'اولم يهد لهم كم اهلكنا من قبلهم من القرون يمشون في مسكنهم ان في ذلك لايت افلا يسمعون', 21, 42, 166, 1, 5, 417, false, NULL),
    (3530, 'tanzil-uthmani-v1.1', 32, 27, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَسُوقُ ٱلْمَآءَ إِلَى ٱلْأَرْضِ ٱلْجُرُزِ فَنُخْرِجُ بِهِۦ زَرْعًا تَأْكُلُ مِنْهُ أَنْعَٰمُهُمْ وَأَنفُسُهُمْ أَفَلَا يُبْصِرُونَ', 'b15bbf891a544882772c33151930d46513537a78d87feb7dbcce80f7aec0e7ef', 'أَوَلَمْ يَرَوْا۟ أَنَّا نَسُوقُ ٱلْمَآءَ إِلَى ٱلْأَرْضِ ٱلْجُرُزِ فَنُخْرِجُ بِهِۦ زَرْعًا تَأْكُلُ مِنْهُ أَنْعَٰمُهُمْ وَأَنفُسُهُمْ أَفَلَا يُبْصِرُونَ', 'b15bbf891a544882772c33151930d46513537a78d87feb7dbcce80f7aec0e7ef', 'b15bbf891a544882772c33151930d46513537a78d87feb7dbcce80f7aec0e7ef', NULL, 'اولم يروا انا نسوق الماء الي الارض الجرز فنخرج به زرعا تاكل منه انعمهم وانفسهم افلا يبصرون', 21, 42, 166, 1, 5, 417, false, NULL),
    (3531, 'tanzil-uthmani-v1.1', 32, 28, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْفَتْحُ إِن كُنتُمْ صَٰدِقِينَ', '9cb744a2f12b14865ea66c6f69033c68613929426963df19e8306c0082cded4e', 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْفَتْحُ إِن كُنتُمْ صَٰدِقِينَ', '9cb744a2f12b14865ea66c6f69033c68613929426963df19e8306c0082cded4e', '9cb744a2f12b14865ea66c6f69033c68613929426963df19e8306c0082cded4e', NULL, 'ويقولون متي هذا الفتح ان كنتم صدقين', 21, 42, 166, 1, 5, 417, false, NULL),
    (3532, 'tanzil-uthmani-v1.1', 32, 29, 'قُلْ يَوْمَ ٱلْفَتْحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓا۟ إِيمَٰنُهُمْ وَلَا هُمْ يُنظَرُونَ', 'cdc4604653bb9b0ba5135c7f6cb618044a7db03316a2e5fe14d0cec3a06651f1', 'قُلْ يَوْمَ ٱلْفَتْحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓا۟ إِيمَٰنُهُمْ وَلَا هُمْ يُنظَرُونَ', 'cdc4604653bb9b0ba5135c7f6cb618044a7db03316a2e5fe14d0cec3a06651f1', 'cdc4604653bb9b0ba5135c7f6cb618044a7db03316a2e5fe14d0cec3a06651f1', NULL, 'قل يوم الفتح لا ينفع الذين كفروا ايمنهم ولا هم ينظرون', 21, 42, 166, 1, 5, 417, false, NULL),
    (3533, 'tanzil-uthmani-v1.1', 32, 30, 'فَأَعْرِضْ عَنْهُمْ وَٱنتَظِرْ إِنَّهُم مُّنتَظِرُونَ', '5476f7f1e3e5e6d97388786fdadbc80afdb98446d49b1b7ae6abfcabd7f7c1c4', 'فَأَعْرِضْ عَنْهُمْ وَٱنتَظِرْ إِنَّهُم مُّنتَظِرُونَ', '5476f7f1e3e5e6d97388786fdadbc80afdb98446d49b1b7ae6abfcabd7f7c1c4', '5476f7f1e3e5e6d97388786fdadbc80afdb98446d49b1b7ae6abfcabd7f7c1c4', NULL, 'فاعرض عنهم وانتظر انهم منتظرون', 21, 42, 166, 1, 5, 417, false, NULL),
    (3534, 'tanzil-uthmani-v1.1', 33, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 'a2c343f66f3b42a188ede9e58fbb2ea076101e99e7afaf72a6465b451cdb5e1f', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', '5e0bf045580a842f75c2fba19bb6de55e9b0cf6d915c7704c975d02982da3652', '5e0bf045580a842f75c2fba19bb6de55e9b0cf6d915c7704c975d02982da3652', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يايها النبي اتق الله ولا تطع الكفرين والمنفقين ان الله كان عليما حكيما', 21, 42, 167, 1, 5, 418, false, NULL),
    (3535, 'tanzil-uthmani-v1.1', 33, 2, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ مِن رَّبِّكَ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'c584a3883be04fbbc463285474c20e0d0a363828ef40d7791c7b1df769aa1808', 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ مِن رَّبِّكَ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا', 'c584a3883be04fbbc463285474c20e0d0a363828ef40d7791c7b1df769aa1808', 'c584a3883be04fbbc463285474c20e0d0a363828ef40d7791c7b1df769aa1808', NULL, 'واتبع ما يوحي اليك من ربك ان الله كان بما تعملون خبيرا', 21, 42, 167, 1, 5, 418, false, NULL),
    (3536, 'tanzil-uthmani-v1.1', 33, 3, 'وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '9f0e6e55561edc998326d743153d2beb526a3b14f1de1dc1e6a5fab811faba74', 'وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '9f0e6e55561edc998326d743153d2beb526a3b14f1de1dc1e6a5fab811faba74', '9f0e6e55561edc998326d743153d2beb526a3b14f1de1dc1e6a5fab811faba74', NULL, 'وتوكل علي الله وكفي بالله وكيلا', 21, 42, 167, 1, 5, 418, false, NULL),
    (3537, 'tanzil-uthmani-v1.1', 33, 4, 'مَّا جَعَلَ ٱللَّهُ لِرَجُلٍ مِّن قَلْبَيْنِ فِى جَوْفِهِۦ وَمَا جَعَلَ أَزْوَٰجَكُمُ ٱلَّٰٓـِٔى تُظَٰهِرُونَ مِنْهُنَّ أُمَّهَٰتِكُمْ وَمَا جَعَلَ أَدْعِيَآءَكُمْ أَبْنَآءَكُمْ ذَٰلِكُمْ قَوْلُكُم بِأَفْوَٰهِكُمْ وَٱللَّهُ يَقُولُ ٱلْحَقَّ وَهُوَ يَهْدِى ٱلسَّبِيلَ', '1ecc8270bb528be424ca9b5531565c9c2a6576e84b6c8931b19b8697c18b70b5', 'مَّا جَعَلَ ٱللَّهُ لِرَجُلٍ مِّن قَلْبَيْنِ فِى جَوْفِهِۦ وَمَا جَعَلَ أَزْوَٰجَكُمُ ٱلَّٰٓـِٔى تُظَٰهِرُونَ مِنْهُنَّ أُمَّهَٰتِكُمْ وَمَا جَعَلَ أَدْعِيَآءَكُمْ أَبْنَآءَكُمْ ذَٰلِكُمْ قَوْلُكُم بِأَفْوَٰهِكُمْ وَٱللَّهُ يَقُولُ ٱلْحَقَّ وَهُوَ يَهْدِى ٱلسَّبِيلَ', '1ecc8270bb528be424ca9b5531565c9c2a6576e84b6c8931b19b8697c18b70b5', '1ecc8270bb528be424ca9b5531565c9c2a6576e84b6c8931b19b8697c18b70b5', NULL, 'ما جعل الله لرجل من قلبين في جوفه وما جعل ازوجكم الي تظهرون منهن امهتكم وما جعل ادعياءكم ابناءكم ذلكم قولكم بافوهكم والله يقول الحق وهو يهدي السبيل', 21, 42, 167, 1, 5, 418, false, NULL),
    (3538, 'tanzil-uthmani-v1.1', 33, 5, 'ٱدْعُوهُمْ لِـَٔابَآئِهِمْ هُوَ أَقْسَطُ عِندَ ٱللَّهِ فَإِن لَّمْ تَعْلَمُوٓا۟ ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَمَوَٰلِيكُمْ وَلَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَآ أَخْطَأْتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'f7e59ac82b5652fe420dceb657f643a7a8a9207e67f649795d7981906f96ed15', 'ٱدْعُوهُمْ لِـَٔابَآئِهِمْ هُوَ أَقْسَطُ عِندَ ٱللَّهِ فَإِن لَّمْ تَعْلَمُوٓا۟ ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَمَوَٰلِيكُمْ وَلَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَآ أَخْطَأْتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'f7e59ac82b5652fe420dceb657f643a7a8a9207e67f649795d7981906f96ed15', 'f7e59ac82b5652fe420dceb657f643a7a8a9207e67f649795d7981906f96ed15', NULL, 'ادعوهم لابائهم هو اقسط عند الله فان لم تعلموا ءاباءهم فاخونكم في الدين وموليكم وليس عليكم جناح فيما اخطاتم به ولكن ما تعمدت قلوبكم وكان الله غفورا رحيما', 21, 42, 167, 1, 5, 418, false, NULL),
    (3539, 'tanzil-uthmani-v1.1', 33, 6, 'ٱلنَّبِىُّ أَوْلَىٰ بِٱلْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ وَأَزْوَٰجُهُۥٓ أُمَّهَٰتُهُمْ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ ٱللَّهِ مِنَ ٱلْمُؤْمِنِينَ وَٱلْمُهَٰجِرِينَ إِلَّآ أَن تَفْعَلُوٓا۟ إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفًا كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًا', 'e848e38d72a230016ed8b4df8e251008b9a95f49252746cff4f86d771865cc2b', 'ٱلنَّبِىُّ أَوْلَىٰ بِٱلْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ وَأَزْوَٰجُهُۥٓ أُمَّهَٰتُهُمْ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ ٱللَّهِ مِنَ ٱلْمُؤْمِنِينَ وَٱلْمُهَٰجِرِينَ إِلَّآ أَن تَفْعَلُوٓا۟ إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفًا كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًا', 'e848e38d72a230016ed8b4df8e251008b9a95f49252746cff4f86d771865cc2b', 'e848e38d72a230016ed8b4df8e251008b9a95f49252746cff4f86d771865cc2b', NULL, 'النبي اولي بالمؤمنين من انفسهم وازوجه امهتهم واولوا الارحام بعضهم اولي ببعض في كتب الله من المؤمنين والمهجرين الا ان تفعلوا الي اوليائكم معروفا كان ذلك في الكتب مسطورا', 21, 42, 167, 1, 5, 418, false, NULL),
    (3540, 'tanzil-uthmani-v1.1', 33, 7, 'وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًا', 'e8c37e9c23388c04323bd2ba52761644391d85b74e423456547e9f9a96274968', 'وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًا', 'e8c37e9c23388c04323bd2ba52761644391d85b74e423456547e9f9a96274968', 'e8c37e9c23388c04323bd2ba52761644391d85b74e423456547e9f9a96274968', NULL, 'واذ اخذنا من النبين ميثقهم ومنك ومن نوح وابرهيم وموسي وعيسي ابن مريم واخذنا منهم ميثقا غليظا', 21, 42, 167, 1, 5, 419, false, NULL),
    (3541, 'tanzil-uthmani-v1.1', 33, 8, 'لِّيَسْـَٔلَ ٱلصَّٰدِقِينَ عَن صِدْقِهِمْ وَأَعَدَّ لِلْكَٰفِرِينَ عَذَابًا أَلِيمًا', '6dd17749339f1091ae427b232ec677ce98c36ef43e7ed149b777458469d56f39', 'لِّيَسْـَٔلَ ٱلصَّٰدِقِينَ عَن صِدْقِهِمْ وَأَعَدَّ لِلْكَٰفِرِينَ عَذَابًا أَلِيمًا', '6dd17749339f1091ae427b232ec677ce98c36ef43e7ed149b777458469d56f39', '6dd17749339f1091ae427b232ec677ce98c36ef43e7ed149b777458469d56f39', NULL, 'ليسل الصدقين عن صدقهم واعد للكفرين عذابا اليما', 21, 42, 167, 1, 5, 419, false, NULL),
    (3542, 'tanzil-uthmani-v1.1', 33, 9, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', '455cb545eb9b032e0a4efcb5a9e802c4870ddc382c7635d683092d0ffe01e1b4', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', '455cb545eb9b032e0a4efcb5a9e802c4870ddc382c7635d683092d0ffe01e1b4', '455cb545eb9b032e0a4efcb5a9e802c4870ddc382c7635d683092d0ffe01e1b4', NULL, 'يايها الذين ءامنوا اذكروا نعمه الله عليكم اذ جاءتكم جنود فارسلنا عليهم ريحا وجنودا لم تروها وكان الله بما تعملون بصيرا', 21, 42, 167, 1, 5, 419, false, NULL),
    (3543, 'tanzil-uthmani-v1.1', 33, 10, 'إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ ٱلْأَبْصَٰرُ وَبَلَغَتِ ٱلْقُلُوبُ ٱلْحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠', 'd5d01d8edeef4b01e026b73267f34c451eb10131fa55788c93a773bffe21877d', 'إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ ٱلْأَبْصَٰرُ وَبَلَغَتِ ٱلْقُلُوبُ ٱلْحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠', 'd5d01d8edeef4b01e026b73267f34c451eb10131fa55788c93a773bffe21877d', 'd5d01d8edeef4b01e026b73267f34c451eb10131fa55788c93a773bffe21877d', NULL, 'اذ جاءوكم من فوقكم ومن اسفل منكم واذ زاغت الابصر وبلغت القلوب الحناجر وتظنون بالله الظنونا', 21, 42, 167, 1, 5, 419, false, NULL),
    (3544, 'tanzil-uthmani-v1.1', 33, 11, 'هُنَالِكَ ٱبْتُلِىَ ٱلْمُؤْمِنُونَ وَزُلْزِلُوا۟ زِلْزَالًا شَدِيدًا', '09e4ba289e0b9165d00f59d5d93c82fafed99668a12688aacb0cbb9a3f46f7cc', 'هُنَالِكَ ٱبْتُلِىَ ٱلْمُؤْمِنُونَ وَزُلْزِلُوا۟ زِلْزَالًا شَدِيدًا', '09e4ba289e0b9165d00f59d5d93c82fafed99668a12688aacb0cbb9a3f46f7cc', '09e4ba289e0b9165d00f59d5d93c82fafed99668a12688aacb0cbb9a3f46f7cc', NULL, 'هنالك ابتلي المؤمنون وزلزلوا زلزالا شديدا', 21, 42, 167, 1, 5, 419, false, NULL),
    (3545, 'tanzil-uthmani-v1.1', 33, 12, 'وَإِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورًا', 'c271496080acf3bc702f4cda43e347c30577934380e9a9fbc9fe1d10d1c0f81c', 'وَإِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورًا', 'c271496080acf3bc702f4cda43e347c30577934380e9a9fbc9fe1d10d1c0f81c', 'c271496080acf3bc702f4cda43e347c30577934380e9a9fbc9fe1d10d1c0f81c', NULL, 'واذ يقول المنفقون والذين في قلوبهم مرض ما وعدنا الله ورسوله الا غرورا', 21, 42, 167, 1, 5, 419, false, NULL),
    (3546, 'tanzil-uthmani-v1.1', 33, 13, 'وَإِذْ قَالَت طَّآئِفَةٌ مِّنْهُمْ يَٰٓأَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَٱرْجِعُوا۟ وَيَسْتَـْٔذِنُ فَرِيقٌ مِّنْهُمُ ٱلنَّبِىَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌ وَمَا هِىَ بِعَوْرَةٍ إِن يُرِيدُونَ إِلَّا فِرَارًا', '406b83617bc7311676409df454283c3d1a510cc8727dd14a5862568e9de276be', 'وَإِذْ قَالَت طَّآئِفَةٌ مِّنْهُمْ يَٰٓأَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَٱرْجِعُوا۟ وَيَسْتَـْٔذِنُ فَرِيقٌ مِّنْهُمُ ٱلنَّبِىَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌ وَمَا هِىَ بِعَوْرَةٍ إِن يُرِيدُونَ إِلَّا فِرَارًا', '406b83617bc7311676409df454283c3d1a510cc8727dd14a5862568e9de276be', '406b83617bc7311676409df454283c3d1a510cc8727dd14a5862568e9de276be', NULL, 'واذ قالت طائفه منهم ياهل يثرب لا مقام لكم فارجعوا ويستذن فريق منهم النبي يقولون ان بيوتنا عوره وما هي بعوره ان يريدون الا فرارا', 21, 42, 167, 1, 5, 419, false, NULL),
    (3547, 'tanzil-uthmani-v1.1', 33, 14, 'وَلَوْ دُخِلَتْ عَلَيْهِم مِّنْ أَقْطَارِهَا ثُمَّ سُئِلُوا۟ ٱلْفِتْنَةَ لَـَٔاتَوْهَا وَمَا تَلَبَّثُوا۟ بِهَآ إِلَّا يَسِيرًا', '5a033010f262e090f914710eba0e695f96916d90a3401d256b3edaf1014c49f7', 'وَلَوْ دُخِلَتْ عَلَيْهِم مِّنْ أَقْطَارِهَا ثُمَّ سُئِلُوا۟ ٱلْفِتْنَةَ لَـَٔاتَوْهَا وَمَا تَلَبَّثُوا۟ بِهَآ إِلَّا يَسِيرًا', '5a033010f262e090f914710eba0e695f96916d90a3401d256b3edaf1014c49f7', '5a033010f262e090f914710eba0e695f96916d90a3401d256b3edaf1014c49f7', NULL, 'ولو دخلت عليهم من اقطارها ثم سئلوا الفتنه لاتوها وما تلبثوا بها الا يسيرا', 21, 42, 167, 1, 5, 419, false, NULL),
    (3548, 'tanzil-uthmani-v1.1', 33, 15, 'وَلَقَدْ كَانُوا۟ عَٰهَدُوا۟ ٱللَّهَ مِن قَبْلُ لَا يُوَلُّونَ ٱلْأَدْبَٰرَ وَكَانَ عَهْدُ ٱللَّهِ مَسْـُٔولًا', '39057294bf7b0b97618d118de8b6c9240db230ea5017d07b3faca7972a293244', 'وَلَقَدْ كَانُوا۟ عَٰهَدُوا۟ ٱللَّهَ مِن قَبْلُ لَا يُوَلُّونَ ٱلْأَدْبَٰرَ وَكَانَ عَهْدُ ٱللَّهِ مَسْـُٔولًا', '39057294bf7b0b97618d118de8b6c9240db230ea5017d07b3faca7972a293244', '39057294bf7b0b97618d118de8b6c9240db230ea5017d07b3faca7972a293244', NULL, 'ولقد كانوا عهدوا الله من قبل لا يولون الادبر وكان عهد الله مسولا', 21, 42, 167, 1, 5, 419, false, NULL),
    (3549, 'tanzil-uthmani-v1.1', 33, 16, 'قُل لَّن يَنفَعَكُمُ ٱلْفِرَارُ إِن فَرَرْتُم مِّنَ ٱلْمَوْتِ أَوِ ٱلْقَتْلِ وَإِذًا لَّا تُمَتَّعُونَ إِلَّا قَلِيلًا', 'c37bea5c68c13079e41cf13b8041b96482de121ecb33ae50d215ba4b739ffda6', 'قُل لَّن يَنفَعَكُمُ ٱلْفِرَارُ إِن فَرَرْتُم مِّنَ ٱلْمَوْتِ أَوِ ٱلْقَتْلِ وَإِذًا لَّا تُمَتَّعُونَ إِلَّا قَلِيلًا', 'c37bea5c68c13079e41cf13b8041b96482de121ecb33ae50d215ba4b739ffda6', 'c37bea5c68c13079e41cf13b8041b96482de121ecb33ae50d215ba4b739ffda6', NULL, 'قل لن ينفعكم الفرار ان فررتم من الموت او القتل واذا لا تمتعون الا قليلا', 21, 42, 167, 1, 5, 420, false, NULL),
    (3550, 'tanzil-uthmani-v1.1', 33, 17, 'قُلْ مَن ذَا ٱلَّذِى يَعْصِمُكُم مِّنَ ٱللَّهِ إِنْ أَرَادَ بِكُمْ سُوٓءًا أَوْ أَرَادَ بِكُمْ رَحْمَةً وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'abf3425c95246b00c5d6bee2dd9b8480d50b612c6b1c295e70a959953443f3a3', 'قُلْ مَن ذَا ٱلَّذِى يَعْصِمُكُم مِّنَ ٱللَّهِ إِنْ أَرَادَ بِكُمْ سُوٓءًا أَوْ أَرَادَ بِكُمْ رَحْمَةً وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا', 'abf3425c95246b00c5d6bee2dd9b8480d50b612c6b1c295e70a959953443f3a3', 'abf3425c95246b00c5d6bee2dd9b8480d50b612c6b1c295e70a959953443f3a3', NULL, 'قل من ذا الذي يعصمكم من الله ان اراد بكم سوءا او اراد بكم رحمه ولا يجدون لهم من دون الله وليا ولا نصيرا', 21, 42, 167, 1, 5, 420, false, NULL),
    (3551, 'tanzil-uthmani-v1.1', 33, 18, 'قَدْ يَعْلَمُ ٱللَّهُ ٱلْمُعَوِّقِينَ مِنكُمْ وَٱلْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا وَلَا يَأْتُونَ ٱلْبَأْسَ إِلَّا قَلِيلًا', '30695a5f63f64a6fb03894ed1468650859f53cd16ad662656cb126a0000e8026', 'قَدْ يَعْلَمُ ٱللَّهُ ٱلْمُعَوِّقِينَ مِنكُمْ وَٱلْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا وَلَا يَأْتُونَ ٱلْبَأْسَ إِلَّا قَلِيلًا', '30695a5f63f64a6fb03894ed1468650859f53cd16ad662656cb126a0000e8026', '30695a5f63f64a6fb03894ed1468650859f53cd16ad662656cb126a0000e8026', NULL, 'قد يعلم الله المعوقين منكم والقائلين لاخونهم هلم الينا ولا ياتون الباس الا قليلا', 21, 42, 168, 1, 5, 420, false, NULL),
    (3552, 'tanzil-uthmani-v1.1', 33, 19, 'أَشِحَّةً عَلَيْكُمْ فَإِذَا جَآءَ ٱلْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَٱلَّذِى يُغْشَىٰ عَلَيْهِ مِنَ ٱلْمَوْتِ فَإِذَا ذَهَبَ ٱلْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلْخَيْرِ أُو۟لَٰٓئِكَ لَمْ يُؤْمِنُوا۟ فَأَحْبَطَ ٱللَّهُ أَعْمَٰلَهُمْ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'ffc3c95c37edc589ebe31ab92ce1c7185df3e284eb050d88f8a85c06dcbbce11', 'أَشِحَّةً عَلَيْكُمْ فَإِذَا جَآءَ ٱلْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَٱلَّذِى يُغْشَىٰ عَلَيْهِ مِنَ ٱلْمَوْتِ فَإِذَا ذَهَبَ ٱلْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلْخَيْرِ أُو۟لَٰٓئِكَ لَمْ يُؤْمِنُوا۟ فَأَحْبَطَ ٱللَّهُ أَعْمَٰلَهُمْ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'ffc3c95c37edc589ebe31ab92ce1c7185df3e284eb050d88f8a85c06dcbbce11', 'ffc3c95c37edc589ebe31ab92ce1c7185df3e284eb050d88f8a85c06dcbbce11', NULL, 'اشحه عليكم فاذا جاء الخوف رايتهم ينظرون اليك تدور اعينهم كالذي يغشي عليه من الموت فاذا ذهب الخوف سلقوكم بالسنه حداد اشحه علي الخير اولئك لم يؤمنوا فاحبط الله اعملهم وكان ذلك علي الله يسيرا', 21, 42, 168, 1, 5, 420, false, NULL),
    (3553, 'tanzil-uthmani-v1.1', 33, 20, 'يَحْسَبُونَ ٱلْأَحْزَابَ لَمْ يَذْهَبُوا۟ وَإِن يَأْتِ ٱلْأَحْزَابُ يَوَدُّوا۟ لَوْ أَنَّهُم بَادُونَ فِى ٱلْأَعْرَابِ يَسْـَٔلُونَ عَنْ أَنۢبَآئِكُمْ وَلَوْ كَانُوا۟ فِيكُم مَّا قَٰتَلُوٓا۟ إِلَّا قَلِيلًا', '17b731f46bf1664f09a0a1f73ef641cb58a86a9861f9e4560262e333b51ed6e5', 'يَحْسَبُونَ ٱلْأَحْزَابَ لَمْ يَذْهَبُوا۟ وَإِن يَأْتِ ٱلْأَحْزَابُ يَوَدُّوا۟ لَوْ أَنَّهُم بَادُونَ فِى ٱلْأَعْرَابِ يَسْـَٔلُونَ عَنْ أَنۢبَآئِكُمْ وَلَوْ كَانُوا۟ فِيكُم مَّا قَٰتَلُوٓا۟ إِلَّا قَلِيلًا', '17b731f46bf1664f09a0a1f73ef641cb58a86a9861f9e4560262e333b51ed6e5', '17b731f46bf1664f09a0a1f73ef641cb58a86a9861f9e4560262e333b51ed6e5', NULL, 'يحسبون الاحزاب لم يذهبوا وان يات الاحزاب يودوا لو انهم بادون في الاعراب يسلون عن انبائكم ولو كانوا فيكم ما قتلوا الا قليلا', 21, 42, 168, 1, 5, 420, false, NULL),
    (3554, 'tanzil-uthmani-v1.1', 33, 21, 'لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًا', 'ff5426d58410174ff245580178f7a690ecb32220c3c3aec579b5e1b6e611bece', 'لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًا', 'ff5426d58410174ff245580178f7a690ecb32220c3c3aec579b5e1b6e611bece', 'ff5426d58410174ff245580178f7a690ecb32220c3c3aec579b5e1b6e611bece', NULL, 'لقد كان لكم في رسول الله اسوه حسنه لمن كان يرجوا الله واليوم الاخر وذكر الله كثيرا', 21, 42, 168, 1, 5, 420, false, NULL),
    (3555, 'tanzil-uthmani-v1.1', 33, 22, 'وَلَمَّا رَءَا ٱلْمُؤْمِنُونَ ٱلْأَحْزَابَ قَالُوا۟ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥ وَمَا زَادَهُمْ إِلَّآ إِيمَٰنًا وَتَسْلِيمًا', '87c4657d54832e31663c10c96c71529b3e178ff5705def5a43a297a7acdd302f', 'وَلَمَّا رَءَا ٱلْمُؤْمِنُونَ ٱلْأَحْزَابَ قَالُوا۟ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥ وَمَا زَادَهُمْ إِلَّآ إِيمَٰنًا وَتَسْلِيمًا', '87c4657d54832e31663c10c96c71529b3e178ff5705def5a43a297a7acdd302f', '87c4657d54832e31663c10c96c71529b3e178ff5705def5a43a297a7acdd302f', NULL, 'ولما رءا المؤمنون الاحزاب قالوا هذا ما وعدنا الله ورسوله وصدق الله ورسوله وما زادهم الا ايمنا وتسليما', 21, 42, 168, 1, 5, 420, false, NULL),
    (3556, 'tanzil-uthmani-v1.1', 33, 23, 'مِّنَ ٱلْمُؤْمِنِينَ رِجَالٌ صَدَقُوا۟ مَا عَٰهَدُوا۟ ٱللَّهَ عَلَيْهِ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُۥ وَمِنْهُم مَّن يَنتَظِرُ وَمَا بَدَّلُوا۟ تَبْدِيلًا', '6c3f6f3c706087117599794956d2c66f03e730b0e9960abdc555dbd4477d10fb', 'مِّنَ ٱلْمُؤْمِنِينَ رِجَالٌ صَدَقُوا۟ مَا عَٰهَدُوا۟ ٱللَّهَ عَلَيْهِ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُۥ وَمِنْهُم مَّن يَنتَظِرُ وَمَا بَدَّلُوا۟ تَبْدِيلًا', '6c3f6f3c706087117599794956d2c66f03e730b0e9960abdc555dbd4477d10fb', '6c3f6f3c706087117599794956d2c66f03e730b0e9960abdc555dbd4477d10fb', NULL, 'من المؤمنين رجال صدقوا ما عهدوا الله عليه فمنهم من قضي نحبه ومنهم من ينتظر وما بدلوا تبديلا', 21, 42, 168, 1, 5, 421, false, NULL),
    (3557, 'tanzil-uthmani-v1.1', 33, 24, 'لِّيَجْزِىَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ إِن شَآءَ أَوْ يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'c194e6d63431b56975269c1e12a47174f41189719d75177f82b2713426825a09', 'لِّيَجْزِىَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ إِن شَآءَ أَوْ يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا', 'c194e6d63431b56975269c1e12a47174f41189719d75177f82b2713426825a09', 'c194e6d63431b56975269c1e12a47174f41189719d75177f82b2713426825a09', NULL, 'ليجزي الله الصدقين بصدقهم ويعذب المنفقين ان شاء او يتوب عليهم ان الله كان غفورا رحيما', 21, 42, 168, 1, 5, 421, false, NULL),
    (3558, 'tanzil-uthmani-v1.1', 33, 25, 'وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ بِغَيْظِهِمْ لَمْ يَنَالُوا۟ خَيْرًا وَكَفَى ٱللَّهُ ٱلْمُؤْمِنِينَ ٱلْقِتَالَ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزًا', 'd4d18d4ebd5f94cffc94d17704926be72f50d1c0f8592bf433b4abd4a62d29bb', 'وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ بِغَيْظِهِمْ لَمْ يَنَالُوا۟ خَيْرًا وَكَفَى ٱللَّهُ ٱلْمُؤْمِنِينَ ٱلْقِتَالَ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزًا', 'd4d18d4ebd5f94cffc94d17704926be72f50d1c0f8592bf433b4abd4a62d29bb', 'd4d18d4ebd5f94cffc94d17704926be72f50d1c0f8592bf433b4abd4a62d29bb', NULL, 'ورد الله الذين كفروا بغيظهم لم ينالوا خيرا وكفي الله المؤمنين القتال وكان الله قويا عزيزا', 21, 42, 168, 1, 5, 421, false, NULL),
    (3559, 'tanzil-uthmani-v1.1', 33, 26, 'وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنْ أَهْلِ ٱلْكِتَٰبِ مِن صَيَاصِيهِمْ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ فَرِيقًا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًا', '67658cca1c145f678f12d8b4cdfd8d6a57a88e0d0245796ca7066fdb82f132cc', 'وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنْ أَهْلِ ٱلْكِتَٰبِ مِن صَيَاصِيهِمْ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ فَرِيقًا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًا', '67658cca1c145f678f12d8b4cdfd8d6a57a88e0d0245796ca7066fdb82f132cc', '67658cca1c145f678f12d8b4cdfd8d6a57a88e0d0245796ca7066fdb82f132cc', NULL, 'وانزل الذين ظهروهم من اهل الكتب من صياصيهم وقذف في قلوبهم الرعب فريقا تقتلون وتاسرون فريقا', 21, 42, 168, 1, 5, 421, false, NULL),
    (3560, 'tanzil-uthmani-v1.1', 33, 27, 'وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَٰرَهُمْ وَأَمْوَٰلَهُمْ وَأَرْضًا لَّمْ تَطَـُٔوهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', '41680aaf76f2c1948d1b61bbdb4bb0ec0612a13672e247ecc615445ea20ad84c', 'وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَٰرَهُمْ وَأَمْوَٰلَهُمْ وَأَرْضًا لَّمْ تَطَـُٔوهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', '41680aaf76f2c1948d1b61bbdb4bb0ec0612a13672e247ecc615445ea20ad84c', '41680aaf76f2c1948d1b61bbdb4bb0ec0612a13672e247ecc615445ea20ad84c', NULL, 'واورثكم ارضهم وديرهم وامولهم وارضا لم تطوها وكان الله علي كل شيء قديرا', 21, 42, 168, 1, 5, 421, false, NULL),
    (3561, 'tanzil-uthmani-v1.1', 33, 28, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا', '3a9d7a4e61faed64065edf37f06f59f7b5dda4cf9b1818a1788cb6aa9c4e2cb2', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا', '3a9d7a4e61faed64065edf37f06f59f7b5dda4cf9b1818a1788cb6aa9c4e2cb2', '3a9d7a4e61faed64065edf37f06f59f7b5dda4cf9b1818a1788cb6aa9c4e2cb2', NULL, 'يايها النبي قل لازوجك ان كنتن تردن الحيوه الدنيا وزينتها فتعالين امتعكن واسرحكن سراحا جميلا', 21, 42, 168, 1, 5, 421, false, NULL),
    (3562, 'tanzil-uthmani-v1.1', 33, 29, 'وَإِن كُنتُنَّ تُرِدْنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلْـَٔاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلْمُحْسِنَٰتِ مِنكُنَّ أَجْرًا عَظِيمًا', 'bdfd962efcc20d40e1b0653f04f68c5abf394e51efb1d2c0eb6f945dffbe80bc', 'وَإِن كُنتُنَّ تُرِدْنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلْـَٔاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلْمُحْسِنَٰتِ مِنكُنَّ أَجْرًا عَظِيمًا', 'bdfd962efcc20d40e1b0653f04f68c5abf394e51efb1d2c0eb6f945dffbe80bc', 'bdfd962efcc20d40e1b0653f04f68c5abf394e51efb1d2c0eb6f945dffbe80bc', NULL, 'وان كنتن تردن الله ورسوله والدار الاخره فان الله اعد للمحسنت منكن اجرا عظيما', 21, 42, 168, 1, 5, 421, false, NULL),
    (3563, 'tanzil-uthmani-v1.1', 33, 30, 'يَٰنِسَآءَ ٱلنَّبِىِّ مَن يَأْتِ مِنكُنَّ بِفَٰحِشَةٍ مُّبَيِّنَةٍ يُضَٰعَفْ لَهَا ٱلْعَذَابُ ضِعْفَيْنِ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'a40da00f1325a406a65d5a58f33d20357042a59dbb673916c3b9f668aca87815', 'يَٰنِسَآءَ ٱلنَّبِىِّ مَن يَأْتِ مِنكُنَّ بِفَٰحِشَةٍ مُّبَيِّنَةٍ يُضَٰعَفْ لَهَا ٱلْعَذَابُ ضِعْفَيْنِ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 'a40da00f1325a406a65d5a58f33d20357042a59dbb673916c3b9f668aca87815', 'a40da00f1325a406a65d5a58f33d20357042a59dbb673916c3b9f668aca87815', NULL, 'ينساء النبي من يات منكن بفحشه مبينه يضعف لها العذاب ضعفين وكان ذلك علي الله يسيرا', 21, 42, 168, 1, 5, 421, false, NULL),
    (3564, 'tanzil-uthmani-v1.1', 33, 31, 'وَمَن يَقْنُتْ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعْمَلْ صَٰلِحًا نُّؤْتِهَآ أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقًا كَرِيمًا', 'bf88dbb07a730ec3e3fd246b2c637ff8087e8e28dc03643e5722c33e784adfd4', 'وَمَن يَقْنُتْ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعْمَلْ صَٰلِحًا نُّؤْتِهَآ أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقًا كَرِيمًا', 'bf88dbb07a730ec3e3fd246b2c637ff8087e8e28dc03643e5722c33e784adfd4', 'bf88dbb07a730ec3e3fd246b2c637ff8087e8e28dc03643e5722c33e784adfd4', NULL, 'ومن يقنت منكن لله ورسوله وتعمل صلحا نؤتها اجرها مرتين واعتدنا لها رزقا كريما', 22, 43, 169, 1, 5, 422, false, NULL),
    (3565, 'tanzil-uthmani-v1.1', 33, 32, 'يَٰنِسَآءَ ٱلنَّبِىِّ لَسْتُنَّ كَأَحَدٍ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِٱلْقَوْلِ فَيَطْمَعَ ٱلَّذِى فِى قَلْبِهِۦ مَرَضٌ وَقُلْنَ قَوْلًا مَّعْرُوفًا', 'f5b134862e4abae3322e5c40032bd84fbd3fa64fc00146017ae6be07518c2d14', 'يَٰنِسَآءَ ٱلنَّبِىِّ لَسْتُنَّ كَأَحَدٍ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِٱلْقَوْلِ فَيَطْمَعَ ٱلَّذِى فِى قَلْبِهِۦ مَرَضٌ وَقُلْنَ قَوْلًا مَّعْرُوفًا', 'f5b134862e4abae3322e5c40032bd84fbd3fa64fc00146017ae6be07518c2d14', 'f5b134862e4abae3322e5c40032bd84fbd3fa64fc00146017ae6be07518c2d14', NULL, 'ينساء النبي لستن كاحد من النساء ان اتقيتن فلا تخضعن بالقول فيطمع الذي في قلبه مرض وقلن قولا معروفا', 22, 43, 169, 1, 5, 422, false, NULL),
    (3566, 'tanzil-uthmani-v1.1', 33, 33, 'وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ ٱلْجَٰهِلِيَّةِ ٱلْأُولَىٰ وَأَقِمْنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعْنَ ٱللَّهَ وَرَسُولَهُۥٓ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', '1c373b95de02a4378b338bdc399a25cdd3e2beb4289bb7b918dd6e50523ed799', 'وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ ٱلْجَٰهِلِيَّةِ ٱلْأُولَىٰ وَأَقِمْنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعْنَ ٱللَّهَ وَرَسُولَهُۥٓ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', '1c373b95de02a4378b338bdc399a25cdd3e2beb4289bb7b918dd6e50523ed799', '1c373b95de02a4378b338bdc399a25cdd3e2beb4289bb7b918dd6e50523ed799', NULL, 'وقرن في بيوتكن ولا تبرجن تبرج الجهليه الاولي واقمن الصلوه وءاتين الزكوه واطعن الله ورسوله انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا', 22, 43, 169, 1, 5, 422, false, NULL),
    (3567, 'tanzil-uthmani-v1.1', 33, 34, 'وَٱذْكُرْنَ مَا يُتْلَىٰ فِى بُيُوتِكُنَّ مِنْ ءَايَٰتِ ٱللَّهِ وَٱلْحِكْمَةِ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا', 'e72532668caa649f81d1e01831a22b7cf611f57be52d81a6bc22b89c893b4041', 'وَٱذْكُرْنَ مَا يُتْلَىٰ فِى بُيُوتِكُنَّ مِنْ ءَايَٰتِ ٱللَّهِ وَٱلْحِكْمَةِ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا', 'e72532668caa649f81d1e01831a22b7cf611f57be52d81a6bc22b89c893b4041', 'e72532668caa649f81d1e01831a22b7cf611f57be52d81a6bc22b89c893b4041', NULL, 'واذكرن ما يتلي في بيوتكن من ءايت الله والحكمه ان الله كان لطيفا خبيرا', 22, 43, 169, 1, 5, 422, false, NULL),
    (3568, 'tanzil-uthmani-v1.1', 33, 35, 'إِنَّ ٱلْمُسْلِمِينَ وَٱلْمُسْلِمَٰتِ وَٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَٱلْقَٰنِتِينَ وَٱلْقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلْخَٰشِعِينَ وَٱلْخَٰشِعَٰتِ وَٱلْمُتَصَدِّقِينَ وَٱلْمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلْحَٰفِظِينَ فُرُوجَهُمْ وَٱلْحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرًا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًا', '6f64e5d987cc34c110c57a640ac6b37eca982c92d600765e1c4268055a970992', 'إِنَّ ٱلْمُسْلِمِينَ وَٱلْمُسْلِمَٰتِ وَٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَٱلْقَٰنِتِينَ وَٱلْقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلْخَٰشِعِينَ وَٱلْخَٰشِعَٰتِ وَٱلْمُتَصَدِّقِينَ وَٱلْمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلْحَٰفِظِينَ فُرُوجَهُمْ وَٱلْحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرًا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًا', '6f64e5d987cc34c110c57a640ac6b37eca982c92d600765e1c4268055a970992', '6f64e5d987cc34c110c57a640ac6b37eca982c92d600765e1c4268055a970992', NULL, 'ان المسلمين والمسلمت والمؤمنين والمؤمنت والقنتين والقنتت والصدقين والصدقت والصبرين والصبرت والخشعين والخشعت والمتصدقين والمتصدقت والصئمين والصئمت والحفظين فروجهم والحفظت والذكرين الله كثيرا والذكرت اعد الله لهم مغفره واجرا عظيما', 22, 43, 169, 1, 5, 422, false, NULL),
    (3569, 'tanzil-uthmani-v1.1', 33, 36, 'وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَٰلًا مُّبِينًا', 'd6c499bb4420b6ffa8f8eabedd274931ef25a3ac26c6e5ed0f3b0162cc80daa2', 'وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَٰلًا مُّبِينًا', 'd6c499bb4420b6ffa8f8eabedd274931ef25a3ac26c6e5ed0f3b0162cc80daa2', 'd6c499bb4420b6ffa8f8eabedd274931ef25a3ac26c6e5ed0f3b0162cc80daa2', NULL, 'وما كان لمؤمن ولا مؤمنه اذا قضي الله ورسوله امرا ان يكون لهم الخيره من امرهم ومن يعص الله ورسوله فقد ضل ضللا مبينا', 22, 43, 169, 1, 5, 423, false, NULL),
    (3570, 'tanzil-uthmani-v1.1', 33, 37, 'وَإِذْ تَقُولُ لِلَّذِىٓ أَنْعَمَ ٱللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَٱتَّقِ ٱللَّهَ وَتُخْفِى فِى نَفْسِكَ مَا ٱللَّهُ مُبْدِيهِ وَتَخْشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخْشَىٰهُ فَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَٰكَهَا لِكَىْ لَا يَكُونَ عَلَى ٱلْمُؤْمِنِينَ حَرَجٌ فِىٓ أَزْوَٰجِ أَدْعِيَآئِهِمْ إِذَا قَضَوْا۟ مِنْهُنَّ وَطَرًا وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', '69a871b6ec0339dfb306746fabc4f5db21f42912b01a6ae1cee1b45c4441ecea', 'وَإِذْ تَقُولُ لِلَّذِىٓ أَنْعَمَ ٱللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَٱتَّقِ ٱللَّهَ وَتُخْفِى فِى نَفْسِكَ مَا ٱللَّهُ مُبْدِيهِ وَتَخْشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخْشَىٰهُ فَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَٰكَهَا لِكَىْ لَا يَكُونَ عَلَى ٱلْمُؤْمِنِينَ حَرَجٌ فِىٓ أَزْوَٰجِ أَدْعِيَآئِهِمْ إِذَا قَضَوْا۟ مِنْهُنَّ وَطَرًا وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', '69a871b6ec0339dfb306746fabc4f5db21f42912b01a6ae1cee1b45c4441ecea', '69a871b6ec0339dfb306746fabc4f5db21f42912b01a6ae1cee1b45c4441ecea', NULL, 'واذ تقول للذي انعم الله عليه وانعمت عليه امسك عليك زوجك واتق الله وتخفي في نفسك ما الله مبديه وتخشي الناس والله احق ان تخشيه فلما قضي زيد منها وطرا زوجنكها لكي لا يكون علي المؤمنين حرج في ازوج ادعيائهم اذا قضوا منهن وطرا وكان امر الله مفعولا', 22, 43, 169, 1, 5, 423, false, NULL),
    (3571, 'tanzil-uthmani-v1.1', 33, 38, 'مَّا كَانَ عَلَى ٱلنَّبِىِّ مِنْ حَرَجٍ فِيمَا فَرَضَ ٱللَّهُ لَهُۥ سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَكَانَ أَمْرُ ٱللَّهِ قَدَرًا مَّقْدُورًا', '387bf5a4eff425e9bd904846313dfcf204d718c0ad970f5670de05449fd87262', 'مَّا كَانَ عَلَى ٱلنَّبِىِّ مِنْ حَرَجٍ فِيمَا فَرَضَ ٱللَّهُ لَهُۥ سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَكَانَ أَمْرُ ٱللَّهِ قَدَرًا مَّقْدُورًا', '387bf5a4eff425e9bd904846313dfcf204d718c0ad970f5670de05449fd87262', '387bf5a4eff425e9bd904846313dfcf204d718c0ad970f5670de05449fd87262', NULL, 'ما كان علي النبي من حرج فيما فرض الله له سنه الله في الذين خلوا من قبل وكان امر الله قدرا مقدورا', 22, 43, 169, 1, 5, 423, false, NULL),
    (3572, 'tanzil-uthmani-v1.1', 33, 39, 'ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخْشَوْنَهُۥ وَلَا يَخْشَوْنَ أَحَدًا إِلَّا ٱللَّهَ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', 'd74ab304c22c7f0b70c0e1ca3849a7a9104f1f298d578ff191de5adea45ca30c', 'ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخْشَوْنَهُۥ وَلَا يَخْشَوْنَ أَحَدًا إِلَّا ٱللَّهَ وَكَفَىٰ بِٱللَّهِ حَسِيبًا', 'd74ab304c22c7f0b70c0e1ca3849a7a9104f1f298d578ff191de5adea45ca30c', 'd74ab304c22c7f0b70c0e1ca3849a7a9104f1f298d578ff191de5adea45ca30c', NULL, 'الذين يبلغون رسلت الله ويخشونه ولا يخشون احدا الا الله وكفي بالله حسيبا', 22, 43, 169, 1, 5, 423, false, NULL),
    (3573, 'tanzil-uthmani-v1.1', 33, 40, 'مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', '4adb427443ee26cd4c1c06c9d08bfd4120accf35cf14fdded818e03ddc527169', 'مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', '4adb427443ee26cd4c1c06c9d08bfd4120accf35cf14fdded818e03ddc527169', '4adb427443ee26cd4c1c06c9d08bfd4120accf35cf14fdded818e03ddc527169', NULL, 'ما كان محمد ابا احد من رجالكم ولكن رسول الله وخاتم النبين وكان الله بكل شيء عليما', 22, 43, 169, 1, 5, 423, false, NULL),
    (3574, 'tanzil-uthmani-v1.1', 33, 41, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ ٱللَّهَ ذِكْرًا كَثِيرًا', '8df12bc092126dbecb5070741577ba0bfa424b6c82f6cc395050f7b700e2a084', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ ٱللَّهَ ذِكْرًا كَثِيرًا', '8df12bc092126dbecb5070741577ba0bfa424b6c82f6cc395050f7b700e2a084', '8df12bc092126dbecb5070741577ba0bfa424b6c82f6cc395050f7b700e2a084', NULL, 'يايها الذين ءامنوا اذكروا الله ذكرا كثيرا', 22, 43, 169, 1, 5, 423, false, NULL),
    (3575, 'tanzil-uthmani-v1.1', 33, 42, 'وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', '99dba0405a2eb4c3391ca878a57c50ccee2b89aa644f1f35227bb7952ac397be', 'وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', '99dba0405a2eb4c3391ca878a57c50ccee2b89aa644f1f35227bb7952ac397be', '99dba0405a2eb4c3391ca878a57c50ccee2b89aa644f1f35227bb7952ac397be', NULL, 'وسبحوه بكره واصيلا', 22, 43, 169, 1, 5, 423, false, NULL),
    (3576, 'tanzil-uthmani-v1.1', 33, 43, 'هُوَ ٱلَّذِى يُصَلِّى عَلَيْكُمْ وَمَلَٰٓئِكَتُهُۥ لِيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَكَانَ بِٱلْمُؤْمِنِينَ رَحِيمًا', '671ee6fca83e51c6774822979c7ebdea24a0f85be856afaac5e7eedb9d007851', 'هُوَ ٱلَّذِى يُصَلِّى عَلَيْكُمْ وَمَلَٰٓئِكَتُهُۥ لِيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَكَانَ بِٱلْمُؤْمِنِينَ رَحِيمًا', '671ee6fca83e51c6774822979c7ebdea24a0f85be856afaac5e7eedb9d007851', '671ee6fca83e51c6774822979c7ebdea24a0f85be856afaac5e7eedb9d007851', NULL, 'هو الذي يصلي عليكم وملئكته ليخرجكم من الظلمت الي النور وكان بالمؤمنين رحيما', 22, 43, 169, 1, 5, 423, false, NULL),
    (3577, 'tanzil-uthmani-v1.1', 33, 44, 'تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَٰمٌ وَأَعَدَّ لَهُمْ أَجْرًا كَرِيمًا', 'cd898f8a7586be9826adf155634310d9aade9280784d802f65bd825a007178c0', 'تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَٰمٌ وَأَعَدَّ لَهُمْ أَجْرًا كَرِيمًا', 'cd898f8a7586be9826adf155634310d9aade9280784d802f65bd825a007178c0', 'cd898f8a7586be9826adf155634310d9aade9280784d802f65bd825a007178c0', NULL, 'تحيتهم يوم يلقونه سلم واعد لهم اجرا كريما', 22, 43, 169, 1, 5, 424, false, NULL),
    (3578, 'tanzil-uthmani-v1.1', 33, 45, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', '0b072f45b647264a7b123493634aa5c179c1e95d833e97142c6d9117d3e0b4ad', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', '0b072f45b647264a7b123493634aa5c179c1e95d833e97142c6d9117d3e0b4ad', '0b072f45b647264a7b123493634aa5c179c1e95d833e97142c6d9117d3e0b4ad', NULL, 'يايها النبي انا ارسلنك شهدا ومبشرا ونذيرا', 22, 43, 169, 1, 5, 424, false, NULL),
    (3579, 'tanzil-uthmani-v1.1', 33, 46, 'وَدَاعِيًا إِلَى ٱللَّهِ بِإِذْنِهِۦ وَسِرَاجًا مُّنِيرًا', 'cb74a8076efcc2206aaa8483a62624fefb3d40bb8418b9970c1a8efbe1032760', 'وَدَاعِيًا إِلَى ٱللَّهِ بِإِذْنِهِۦ وَسِرَاجًا مُّنِيرًا', 'cb74a8076efcc2206aaa8483a62624fefb3d40bb8418b9970c1a8efbe1032760', 'cb74a8076efcc2206aaa8483a62624fefb3d40bb8418b9970c1a8efbe1032760', NULL, 'وداعيا الي الله باذنه وسراجا منيرا', 22, 43, 169, 1, 5, 424, false, NULL),
    (3580, 'tanzil-uthmani-v1.1', 33, 47, 'وَبَشِّرِ ٱلْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضْلًا كَبِيرًا', '678f89eb59c7dd3bf234244cede8c5015b7b9d0325d0da4920cb4b17756313a5', 'وَبَشِّرِ ٱلْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضْلًا كَبِيرًا', '678f89eb59c7dd3bf234244cede8c5015b7b9d0325d0da4920cb4b17756313a5', '678f89eb59c7dd3bf234244cede8c5015b7b9d0325d0da4920cb4b17756313a5', NULL, 'وبشر المؤمنين بان لهم من الله فضلا كبيرا', 22, 43, 169, 1, 5, 424, false, NULL),
    (3581, 'tanzil-uthmani-v1.1', 33, 48, 'وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ وَدَعْ أَذَىٰهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '0732d7faf469dee8692bd439d16bf97bdbc69a054d9712c0a45a6ed012b4d2b2', 'وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ وَدَعْ أَذَىٰهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', '0732d7faf469dee8692bd439d16bf97bdbc69a054d9712c0a45a6ed012b4d2b2', '0732d7faf469dee8692bd439d16bf97bdbc69a054d9712c0a45a6ed012b4d2b2', NULL, 'ولا تطع الكفرين والمنفقين ودع اذيهم وتوكل علي الله وكفي بالله وكيلا', 22, 43, 169, 1, 5, 424, false, NULL),
    (3582, 'tanzil-uthmani-v1.1', 33, 49, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَكَحْتُمُ ٱلْمُؤْمِنَٰتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا', 'a4cef49dcb2c3aaa6e6a7a9215b5bf8eebe835bcc78393da7d02eca6037f118f', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَكَحْتُمُ ٱلْمُؤْمِنَٰتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا', 'a4cef49dcb2c3aaa6e6a7a9215b5bf8eebe835bcc78393da7d02eca6037f118f', 'a4cef49dcb2c3aaa6e6a7a9215b5bf8eebe835bcc78393da7d02eca6037f118f', NULL, 'يايها الذين ءامنوا اذا نكحتم المؤمنت ثم طلقتموهن من قبل ان تمسوهن فما لكم عليهن من عده تعتدونها فمتعوهن وسرحوهن سراحا جميلا', 22, 43, 169, 1, 5, 424, false, NULL),
    (3583, 'tanzil-uthmani-v1.1', 33, 50, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ ٱلَّٰتِىٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِى هَاجَرْنَ مَعَكَ وَٱمْرَأَةً مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِىِّ إِنْ أَرَادَ ٱلنَّبِىُّ أَن يَسْتَنكِحَهَا خَالِصَةً لَّكَ مِن دُونِ ٱلْمُؤْمِنِينَ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتْ أَيْمَٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '1a4d87c20f8d7a7fcd242db81c75a3b203b4100672d31bfbee23ab0cb13339bf', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ ٱلَّٰتِىٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِى هَاجَرْنَ مَعَكَ وَٱمْرَأَةً مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِىِّ إِنْ أَرَادَ ٱلنَّبِىُّ أَن يَسْتَنكِحَهَا خَالِصَةً لَّكَ مِن دُونِ ٱلْمُؤْمِنِينَ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتْ أَيْمَٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '1a4d87c20f8d7a7fcd242db81c75a3b203b4100672d31bfbee23ab0cb13339bf', '1a4d87c20f8d7a7fcd242db81c75a3b203b4100672d31bfbee23ab0cb13339bf', NULL, 'يايها النبي انا احللنا لك ازوجك التي ءاتيت اجورهن وما ملكت يمينك مما افاء الله عليك وبنات عمك وبنات عمتك وبنات خالك وبنات خلتك التي هاجرن معك وامراه مؤمنه ان وهبت نفسها للنبي ان اراد النبي ان يستنكحها خالصه لك من دون المؤمنين قد علمنا ما فرضنا عليهم في ازوجهم وما ملكت ايمنهم لكيلا يكون عليك حرج وكان الله غفورا رحيما', 22, 43, 169, 1, 5, 424, false, NULL),
    (3584, 'tanzil-uthmani-v1.1', 33, 51, 'تُرْجِى مَن تَشَآءُ مِنْهُنَّ وَتُـْٔوِىٓ إِلَيْكَ مَن تَشَآءُ وَمَنِ ٱبْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ذَٰلِكَ أَدْنَىٰٓ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَآ ءَاتَيْتَهُنَّ كُلُّهُنَّ وَٱللَّهُ يَعْلَمُ مَا فِى قُلُوبِكُمْ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمًا', 'fded74303f30a764ed42e5b2b61e9862c2ff147bc408271987095c273510da1f', 'تُرْجِى مَن تَشَآءُ مِنْهُنَّ وَتُـْٔوِىٓ إِلَيْكَ مَن تَشَآءُ وَمَنِ ٱبْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ذَٰلِكَ أَدْنَىٰٓ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَآ ءَاتَيْتَهُنَّ كُلُّهُنَّ وَٱللَّهُ يَعْلَمُ مَا فِى قُلُوبِكُمْ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمًا', 'fded74303f30a764ed42e5b2b61e9862c2ff147bc408271987095c273510da1f', 'fded74303f30a764ed42e5b2b61e9862c2ff147bc408271987095c273510da1f', NULL, 'ترجي من تشاء منهن وتوي اليك من تشاء ومن ابتغيت ممن عزلت فلا جناح عليك ذلك ادني ان تقر اعينهن ولا يحزن ويرضين بما ءاتيتهن كلهن والله يعلم ما في قلوبكم وكان الله عليما حليما', 22, 43, 170, 1, 5, 425, false, NULL),
    (3585, 'tanzil-uthmani-v1.1', 33, 52, 'لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعْدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَٰجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ رَّقِيبًا', 'dea0a9b2380c878994c65faf3f1995f6fa612a30c8ba3c6ae21c68bc524c85ab', 'لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعْدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَٰجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ رَّقِيبًا', 'dea0a9b2380c878994c65faf3f1995f6fa612a30c8ba3c6ae21c68bc524c85ab', 'dea0a9b2380c878994c65faf3f1995f6fa612a30c8ba3c6ae21c68bc524c85ab', NULL, 'لا يحل لك النساء من بعد ولا ان تبدل بهن من ازوج ولو اعجبك حسنهن الا ما ملكت يمينك وكان الله علي كل شيء رقيبا', 22, 43, 170, 1, 5, 425, false, NULL),
    (3586, 'tanzil-uthmani-v1.1', 33, 53, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتَ ٱلنَّبِىِّ إِلَّآ أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنْ إِذَا دُعِيتُمْ فَٱدْخُلُوا۟ فَإِذَا طَعِمْتُمْ فَٱنتَشِرُوا۟ وَلَا مُسْتَـْٔنِسِينَ لِحَدِيثٍ إِنَّ ذَٰلِكُمْ كَانَ يُؤْذِى ٱلنَّبِىَّ فَيَسْتَحْىِۦ مِنكُمْ وَٱللَّهُ لَا يَسْتَحْىِۦ مِنَ ٱلْحَقِّ وَإِذَا سَأَلْتُمُوهُنَّ مَتَٰعًا فَسْـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٍ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ وَمَا كَانَ لَكُمْ أَن تُؤْذُوا۟ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓا۟ أَزْوَٰجَهُۥ مِنۢ بَعْدِهِۦٓ أَبَدًا إِنَّ ذَٰلِكُمْ كَانَ عِندَ ٱللَّهِ عَظِيمًا', '918d9fb4e680fdcb2103dbda44bdf01f84b584b005a235486816da20389a70ce', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتَ ٱلنَّبِىِّ إِلَّآ أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنْ إِذَا دُعِيتُمْ فَٱدْخُلُوا۟ فَإِذَا طَعِمْتُمْ فَٱنتَشِرُوا۟ وَلَا مُسْتَـْٔنِسِينَ لِحَدِيثٍ إِنَّ ذَٰلِكُمْ كَانَ يُؤْذِى ٱلنَّبِىَّ فَيَسْتَحْىِۦ مِنكُمْ وَٱللَّهُ لَا يَسْتَحْىِۦ مِنَ ٱلْحَقِّ وَإِذَا سَأَلْتُمُوهُنَّ مَتَٰعًا فَسْـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٍ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ وَمَا كَانَ لَكُمْ أَن تُؤْذُوا۟ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓا۟ أَزْوَٰجَهُۥ مِنۢ بَعْدِهِۦٓ أَبَدًا إِنَّ ذَٰلِكُمْ كَانَ عِندَ ٱللَّهِ عَظِيمًا', '918d9fb4e680fdcb2103dbda44bdf01f84b584b005a235486816da20389a70ce', '918d9fb4e680fdcb2103dbda44bdf01f84b584b005a235486816da20389a70ce', NULL, 'يايها الذين ءامنوا لا تدخلوا بيوت النبي الا ان يؤذن لكم الي طعام غير نظرين انيه ولكن اذا دعيتم فادخلوا فاذا طعمتم فانتشروا ولا مستنسين لحديث ان ذلكم كان يؤذي النبي فيستحي منكم والله لا يستحي من الحق واذا سالتموهن متعا فسلوهن من وراء حجاب ذلكم اطهر لقلوبكم وقلوبهن وما كان لكم ان تؤذوا رسول الله ولا ان تنكحوا ازوجه من بعده ابدا ان ذلكم كان عند الله عظيما', 22, 43, 170, 1, 5, 425, false, NULL),
    (3587, 'tanzil-uthmani-v1.1', 33, 54, 'إِن تُبْدُوا۟ شَيْـًٔا أَوْ تُخْفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', '56167e044352686dfb6364b15a6aecc00f856b98c81f659ef3b4dd040985cf17', 'إِن تُبْدُوا۟ شَيْـًٔا أَوْ تُخْفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا', '56167e044352686dfb6364b15a6aecc00f856b98c81f659ef3b4dd040985cf17', '56167e044352686dfb6364b15a6aecc00f856b98c81f659ef3b4dd040985cf17', NULL, 'ان تبدوا شيا او تخفوه فان الله كان بكل شيء عليما', 22, 43, 170, 1, 5, 425, false, NULL),
    (3588, 'tanzil-uthmani-v1.1', 33, 55, 'لَّا جُنَاحَ عَلَيْهِنَّ فِىٓ ءَابَآئِهِنَّ وَلَآ أَبْنَآئِهِنَّ وَلَآ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتْ أَيْمَٰنُهُنَّ وَٱتَّقِينَ ٱللَّهَ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', '1f5865529ad950a47e19597e6d23ef5ae495f1227a946882b37c1d69edda3a96', 'لَّا جُنَاحَ عَلَيْهِنَّ فِىٓ ءَابَآئِهِنَّ وَلَآ أَبْنَآئِهِنَّ وَلَآ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتْ أَيْمَٰنُهُنَّ وَٱتَّقِينَ ٱللَّهَ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا', '1f5865529ad950a47e19597e6d23ef5ae495f1227a946882b37c1d69edda3a96', '1f5865529ad950a47e19597e6d23ef5ae495f1227a946882b37c1d69edda3a96', NULL, 'لا جناح عليهن في ءابائهن ولا ابنائهن ولا اخونهن ولا ابناء اخونهن ولا ابناء اخوتهن ولا نسائهن ولا ما ملكت ايمنهن واتقين الله ان الله كان علي كل شيء شهيدا', 22, 43, 170, 1, 5, 426, false, NULL),
    (3589, 'tanzil-uthmani-v1.1', 33, 56, 'إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِىِّ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًا', 'abcc8807c82fe4129ded8d1f0ac37e7ce426060bce668f70c455c8c064e16a8d', 'إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِىِّ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًا', 'abcc8807c82fe4129ded8d1f0ac37e7ce426060bce668f70c455c8c064e16a8d', 'abcc8807c82fe4129ded8d1f0ac37e7ce426060bce668f70c455c8c064e16a8d', NULL, 'ان الله وملئكته يصلون علي النبي يايها الذين ءامنوا صلوا عليه وسلموا تسليما', 22, 43, 170, 1, 5, 426, false, NULL),
    (3590, 'tanzil-uthmani-v1.1', 33, 57, 'إِنَّ ٱلَّذِينَ يُؤْذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا', 'fb77f2b6adcbc73dfa26762b05908eb80d199a5e1b8e1118aad102c92b524446', 'إِنَّ ٱلَّذِينَ يُؤْذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا', 'fb77f2b6adcbc73dfa26762b05908eb80d199a5e1b8e1118aad102c92b524446', 'fb77f2b6adcbc73dfa26762b05908eb80d199a5e1b8e1118aad102c92b524446', NULL, 'ان الذين يؤذون الله ورسوله لعنهم الله في الدنيا والاخره واعد لهم عذابا مهينا', 22, 43, 170, 1, 5, 426, false, NULL),
    (3591, 'tanzil-uthmani-v1.1', 33, 58, 'وَٱلَّذِينَ يُؤْذُونَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ بِغَيْرِ مَا ٱكْتَسَبُوا۟ فَقَدِ ٱحْتَمَلُوا۟ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'a51cb1ccb753d0dd5aa554c1c92198aa88a3887d68092be651b87b76a6f55864', 'وَٱلَّذِينَ يُؤْذُونَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ بِغَيْرِ مَا ٱكْتَسَبُوا۟ فَقَدِ ٱحْتَمَلُوا۟ بُهْتَٰنًا وَإِثْمًا مُّبِينًا', 'a51cb1ccb753d0dd5aa554c1c92198aa88a3887d68092be651b87b76a6f55864', 'a51cb1ccb753d0dd5aa554c1c92198aa88a3887d68092be651b87b76a6f55864', NULL, 'والذين يؤذون المؤمنين والمؤمنت بغير ما اكتسبوا فقد احتملوا بهتنا واثما مبينا', 22, 43, 170, 1, 5, 426, false, NULL),
    (3592, 'tanzil-uthmani-v1.1', 33, 59, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَٰبِيبِهِنَّ ذَٰلِكَ أَدْنَىٰٓ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'e7c639489f8efe3225a911267d94beef1ea3ef955867183dca223da5a8f5965e', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَٰبِيبِهِنَّ ذَٰلِكَ أَدْنَىٰٓ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', 'e7c639489f8efe3225a911267d94beef1ea3ef955867183dca223da5a8f5965e', 'e7c639489f8efe3225a911267d94beef1ea3ef955867183dca223da5a8f5965e', NULL, 'يايها النبي قل لازوجك وبناتك ونساء المؤمنين يدنين عليهن من جلبيبهن ذلك ادني ان يعرفن فلا يؤذين وكان الله غفورا رحيما', 22, 43, 170, 1, 5, 426, false, NULL),
    (3593, 'tanzil-uthmani-v1.1', 33, 60, 'لَّئِن لَّمْ يَنتَهِ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْمُرْجِفُونَ فِى ٱلْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلًا', 'c901e0efea203be384b5d05cbe3a45dec79754fe5ba3ff9a5681e6849c14aca8', 'لَّئِن لَّمْ يَنتَهِ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْمُرْجِفُونَ فِى ٱلْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلًا', 'c901e0efea203be384b5d05cbe3a45dec79754fe5ba3ff9a5681e6849c14aca8', 'c901e0efea203be384b5d05cbe3a45dec79754fe5ba3ff9a5681e6849c14aca8', NULL, 'لئن لم ينته المنفقون والذين في قلوبهم مرض والمرجفون في المدينه لنغرينك بهم ثم لا يجاورونك فيها الا قليلا', 22, 43, 171, 1, 5, 426, false, NULL),
    (3594, 'tanzil-uthmani-v1.1', 33, 61, 'مَّلْعُونِينَ أَيْنَمَا ثُقِفُوٓا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقْتِيلًا', '79dbfa00e06c69eda5a2d26a763249ddaf7df84bf6347ffa3ebd36cad98d0868', 'مَّلْعُونِينَ أَيْنَمَا ثُقِفُوٓا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقْتِيلًا', '79dbfa00e06c69eda5a2d26a763249ddaf7df84bf6347ffa3ebd36cad98d0868', '79dbfa00e06c69eda5a2d26a763249ddaf7df84bf6347ffa3ebd36cad98d0868', NULL, 'ملعونين اينما ثقفوا اخذوا وقتلوا تقتيلا', 22, 43, 171, 1, 5, 426, false, NULL),
    (3595, 'tanzil-uthmani-v1.1', 33, 62, 'سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', '6e13a1755360728f12c4222e9aa843237c5360849aa1bd7f24997eae8ce50335', 'سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', '6e13a1755360728f12c4222e9aa843237c5360849aa1bd7f24997eae8ce50335', '6e13a1755360728f12c4222e9aa843237c5360849aa1bd7f24997eae8ce50335', NULL, 'سنه الله في الذين خلوا من قبل ولن تجد لسنه الله تبديلا', 22, 43, 171, 1, 5, 426, false, NULL),
    (3596, 'tanzil-uthmani-v1.1', 33, 63, 'يَسْـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا', 'a7c287301494a542485a9bc0fda2bb74398fcbbd3c495608805cd6472d8b3f1b', 'يَسْـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا', 'a7c287301494a542485a9bc0fda2bb74398fcbbd3c495608805cd6472d8b3f1b', 'a7c287301494a542485a9bc0fda2bb74398fcbbd3c495608805cd6472d8b3f1b', NULL, 'يسلك الناس عن الساعه قل انما علمها عند الله وما يدريك لعل الساعه تكون قريبا', 22, 43, 171, 1, 5, 427, false, NULL),
    (3597, 'tanzil-uthmani-v1.1', 33, 64, 'إِنَّ ٱللَّهَ لَعَنَ ٱلْكَٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا', '6430fbc5dce8d6c4f3f1b257de067e9718034509a7c3ffe5e5b77729b0698490', 'إِنَّ ٱللَّهَ لَعَنَ ٱلْكَٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا', '6430fbc5dce8d6c4f3f1b257de067e9718034509a7c3ffe5e5b77729b0698490', '6430fbc5dce8d6c4f3f1b257de067e9718034509a7c3ffe5e5b77729b0698490', NULL, 'ان الله لعن الكفرين واعد لهم سعيرا', 22, 43, 171, 1, 5, 427, false, NULL),
    (3598, 'tanzil-uthmani-v1.1', 33, 65, 'خَٰلِدِينَ فِيهَآ أَبَدًا لَّا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', '8cb3e2bcbe68dd1b68b0040303fc55d19fd75bb1d609d775655d7104067e70fd', 'خَٰلِدِينَ فِيهَآ أَبَدًا لَّا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', '8cb3e2bcbe68dd1b68b0040303fc55d19fd75bb1d609d775655d7104067e70fd', '8cb3e2bcbe68dd1b68b0040303fc55d19fd75bb1d609d775655d7104067e70fd', NULL, 'خلدين فيها ابدا لا يجدون وليا ولا نصيرا', 22, 43, 171, 1, 5, 427, false, NULL),
    (3599, 'tanzil-uthmani-v1.1', 33, 66, 'يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى ٱلنَّارِ يَقُولُونَ يَٰلَيْتَنَآ أَطَعْنَا ٱللَّهَ وَأَطَعْنَا ٱلرَّسُولَا۠', '7011a86a62703693014b1b1d09c6da6b33cca2cc738bf49360a4352fc69dcd9d', 'يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى ٱلنَّارِ يَقُولُونَ يَٰلَيْتَنَآ أَطَعْنَا ٱللَّهَ وَأَطَعْنَا ٱلرَّسُولَا۠', '7011a86a62703693014b1b1d09c6da6b33cca2cc738bf49360a4352fc69dcd9d', '7011a86a62703693014b1b1d09c6da6b33cca2cc738bf49360a4352fc69dcd9d', NULL, 'يوم تقلب وجوههم في النار يقولون يليتنا اطعنا الله واطعنا الرسولا', 22, 43, 171, 1, 5, 427, false, NULL),
    (3600, 'tanzil-uthmani-v1.1', 33, 67, 'وَقَالُوا۟ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠', '18e1d38582ebe393ce82e1be1ccb22245ee3c67b5ef61ab936e3eb55b7b94706', 'وَقَالُوا۟ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠', '18e1d38582ebe393ce82e1be1ccb22245ee3c67b5ef61ab936e3eb55b7b94706', '18e1d38582ebe393ce82e1be1ccb22245ee3c67b5ef61ab936e3eb55b7b94706', NULL, 'وقالوا ربنا انا اطعنا سادتنا وكبراءنا فاضلونا السبيلا', 22, 43, 171, 1, 5, 427, false, NULL),
    (3601, 'tanzil-uthmani-v1.1', 33, 68, 'رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًا كَبِيرًا', 'a775ce791c18a6c64329e626f6f38727a15903ecc3b9a8bfc221e36e26169893', 'رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًا كَبِيرًا', 'a775ce791c18a6c64329e626f6f38727a15903ecc3b9a8bfc221e36e26169893', 'a775ce791c18a6c64329e626f6f38727a15903ecc3b9a8bfc221e36e26169893', NULL, 'ربنا ءاتهم ضعفين من العذاب والعنهم لعنا كبيرا', 22, 43, 171, 1, 5, 427, false, NULL),
    (3602, 'tanzil-uthmani-v1.1', 33, 69, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ ءَاذَوْا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ وَكَانَ عِندَ ٱللَّهِ وَجِيهًا', '83f5ecabc9908fe56d86b85eef283fdc7bd6b001f36a2cc482d66987850c8ac6', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ ءَاذَوْا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ وَكَانَ عِندَ ٱللَّهِ وَجِيهًا', '83f5ecabc9908fe56d86b85eef283fdc7bd6b001f36a2cc482d66987850c8ac6', '83f5ecabc9908fe56d86b85eef283fdc7bd6b001f36a2cc482d66987850c8ac6', NULL, 'يايها الذين ءامنوا لا تكونوا كالذين ءاذوا موسي فبراه الله مما قالوا وكان عند الله وجيها', 22, 43, 171, 1, 5, 427, false, NULL),
    (3603, 'tanzil-uthmani-v1.1', 33, 70, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوْلًا سَدِيدًا', '8894d1866d9d211ac26092a1fea9aa45fae086ca1517c26dc7576ba372fb8fb9', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوْلًا سَدِيدًا', '8894d1866d9d211ac26092a1fea9aa45fae086ca1517c26dc7576ba372fb8fb9', '8894d1866d9d211ac26092a1fea9aa45fae086ca1517c26dc7576ba372fb8fb9', NULL, 'يايها الذين ءامنوا اتقوا الله وقولوا قولا سديدا', 22, 43, 171, 1, 5, 427, false, NULL),
    (3604, 'tanzil-uthmani-v1.1', 33, 71, 'يُصْلِحْ لَكُمْ أَعْمَٰلَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ فَازَ فَوْزًا عَظِيمًا', 'bd2e5c47ce843f1d2f5ea6aaafe7b9ef20bcd08868ba7ade2ea41e0b1a8f7c24', 'يُصْلِحْ لَكُمْ أَعْمَٰلَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ فَازَ فَوْزًا عَظِيمًا', 'bd2e5c47ce843f1d2f5ea6aaafe7b9ef20bcd08868ba7ade2ea41e0b1a8f7c24', 'bd2e5c47ce843f1d2f5ea6aaafe7b9ef20bcd08868ba7ade2ea41e0b1a8f7c24', NULL, 'يصلح لكم اعملكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزا عظيما', 22, 43, 171, 1, 5, 427, false, NULL),
    (3605, 'tanzil-uthmani-v1.1', 33, 72, 'إِنَّا عَرَضْنَا ٱلْأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلْجِبَالِ فَأَبَيْنَ أَن يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا ٱلْإِنسَٰنُ إِنَّهُۥ كَانَ ظَلُومًا جَهُولًا', '0184ef85bcefc550aa92b63037e012f8a1215a743ad53905182efa5d3e82a05f', 'إِنَّا عَرَضْنَا ٱلْأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلْجِبَالِ فَأَبَيْنَ أَن يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا ٱلْإِنسَٰنُ إِنَّهُۥ كَانَ ظَلُومًا جَهُولًا', '0184ef85bcefc550aa92b63037e012f8a1215a743ad53905182efa5d3e82a05f', '0184ef85bcefc550aa92b63037e012f8a1215a743ad53905182efa5d3e82a05f', NULL, 'انا عرضنا الامانه علي السموت والارض والجبال فابين ان يحملنها واشفقن منها وحملها الانسن انه كان ظلوما جهولا', 22, 43, 171, 1, 5, 427, false, NULL),
    (3606, 'tanzil-uthmani-v1.1', 33, 73, 'لِّيُعَذِّبَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًۢا', '0fc6a2b93190524744b3eb4d0ab15de2641715b1c436c250687fa8db4a35a76a', 'لِّيُعَذِّبَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًۢا', '0fc6a2b93190524744b3eb4d0ab15de2641715b1c436c250687fa8db4a35a76a', '0fc6a2b93190524744b3eb4d0ab15de2641715b1c436c250687fa8db4a35a76a', NULL, 'ليعذب الله المنفقين والمنفقت والمشركين والمشركت ويتوب الله علي المؤمنين والمؤمنت وكان الله غفورا رحيما', 22, 43, 171, 1, 5, 427, false, NULL),
    (3607, 'tanzil-uthmani-v1.1', 34, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَهُ ٱلْحَمْدُ فِى ٱلْـَٔاخِرَةِ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', '8a431f04ad7f909ee7a47efd0127fbf80f1b818bc2f60f567f15d5f513bbf891', 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَهُ ٱلْحَمْدُ فِى ٱلْـَٔاخِرَةِ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', '0ca9e80474fb7c66a4e7a71367d5f0a94b3bb1afdef9adfc9270b0307c39a5b2', '0ca9e80474fb7c66a4e7a71367d5f0a94b3bb1afdef9adfc9270b0307c39a5b2', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الحمد لله الذي له ما في السموت وما في الارض وله الحمد في الاخره وهو الحكيم الخبير', 22, 43, 171, 1, 5, 428, false, NULL),
    (3608, 'tanzil-uthmani-v1.1', 34, 2, 'يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ ٱلرَّحِيمُ ٱلْغَفُورُ', '10a27fb702264bd26c4a622aadb22c2283459423b19e30a32b8d610f1acbbeca', 'يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ ٱلرَّحِيمُ ٱلْغَفُورُ', '10a27fb702264bd26c4a622aadb22c2283459423b19e30a32b8d610f1acbbeca', '10a27fb702264bd26c4a622aadb22c2283459423b19e30a32b8d610f1acbbeca', NULL, 'يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو الرحيم الغفور', 22, 43, 171, 1, 5, 428, false, NULL),
    (3609, 'tanzil-uthmani-v1.1', 34, 3, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَأْتِينَا ٱلسَّاعَةُ قُلْ بَلَىٰ وَرَبِّى لَتَأْتِيَنَّكُمْ عَٰلِمِ ٱلْغَيْبِ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَلَآ أَصْغَرُ مِن ذَٰلِكَ وَلَآ أَكْبَرُ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', '6143141f83a6543593bd3ed79587cb60721570b895c8b343df08b7cd19a723ab', 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَأْتِينَا ٱلسَّاعَةُ قُلْ بَلَىٰ وَرَبِّى لَتَأْتِيَنَّكُمْ عَٰلِمِ ٱلْغَيْبِ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَلَآ أَصْغَرُ مِن ذَٰلِكَ وَلَآ أَكْبَرُ إِلَّا فِى كِتَٰبٍ مُّبِينٍ', '6143141f83a6543593bd3ed79587cb60721570b895c8b343df08b7cd19a723ab', '6143141f83a6543593bd3ed79587cb60721570b895c8b343df08b7cd19a723ab', NULL, 'وقال الذين كفروا لا تاتينا الساعه قل بلي وربي لتاتينكم علم الغيب لا يعزب عنه مثقال ذره في السموت ولا في الارض ولا اصغر من ذلك ولا اكبر الا في كتب مبين', 22, 43, 171, 1, 5, 428, false, NULL),
    (3610, 'tanzil-uthmani-v1.1', 34, 4, 'لِّيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'b832428d9e411325546c3e8a5b4f4a94f37f767a9edf8023b9f445faa28e3dea', 'لِّيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ', 'b832428d9e411325546c3e8a5b4f4a94f37f767a9edf8023b9f445faa28e3dea', 'b832428d9e411325546c3e8a5b4f4a94f37f767a9edf8023b9f445faa28e3dea', NULL, 'ليجزي الذين ءامنوا وعملوا الصلحت اولئك لهم مغفره ورزق كريم', 22, 43, 171, 1, 5, 428, false, NULL),
    (3611, 'tanzil-uthmani-v1.1', 34, 5, 'وَٱلَّذِينَ سَعَوْ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', '94415fc61a7b4eb25606536cb298c8561c4c76553fb7e56f544623e0a34d9b7f', 'وَٱلَّذِينَ سَعَوْ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', '94415fc61a7b4eb25606536cb298c8561c4c76553fb7e56f544623e0a34d9b7f', '94415fc61a7b4eb25606536cb298c8561c4c76553fb7e56f544623e0a34d9b7f', NULL, 'والذين سعو في ءايتنا معجزين اولئك لهم عذاب من رجز اليم', 22, 43, 171, 1, 5, 428, false, NULL),
    (3612, 'tanzil-uthmani-v1.1', 34, 6, 'وَيَرَى ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ ٱلْحَقَّ وَيَهْدِىٓ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'c95c0ba9b6c54bfcdb4c1a6cb502976a6b2a3b8b14d8eb46844ed4fd3df7bca6', 'وَيَرَى ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ ٱلْحَقَّ وَيَهْدِىٓ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 'c95c0ba9b6c54bfcdb4c1a6cb502976a6b2a3b8b14d8eb46844ed4fd3df7bca6', 'c95c0ba9b6c54bfcdb4c1a6cb502976a6b2a3b8b14d8eb46844ed4fd3df7bca6', NULL, 'ويري الذين اوتوا العلم الذي انزل اليك من ربك هو الحق ويهدي الي صرط العزيز الحميد', 22, 43, 171, 1, 5, 428, false, NULL),
    (3613, 'tanzil-uthmani-v1.1', 34, 7, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِى خَلْقٍ جَدِيدٍ', '3aa074e33ded55043f604d2e2d296176aaa4a3dba52ec58456597a876c4dd7ef', 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِى خَلْقٍ جَدِيدٍ', '3aa074e33ded55043f604d2e2d296176aaa4a3dba52ec58456597a876c4dd7ef', '3aa074e33ded55043f604d2e2d296176aaa4a3dba52ec58456597a876c4dd7ef', NULL, 'وقال الذين كفروا هل ندلكم علي رجل ينبئكم اذا مزقتم كل ممزق انكم لفي خلق جديد', 22, 43, 171, 1, 5, 428, false, NULL),
    (3614, 'tanzil-uthmani-v1.1', 34, 8, 'أَفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةٌۢ بَلِ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ فِى ٱلْعَذَابِ وَٱلضَّلَٰلِ ٱلْبَعِيدِ', 'b46dfd67051e15394bfb3d0a0149fb1ac6d21d98b59376a9b0c7c54eec0bcba6', 'أَفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةٌۢ بَلِ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ فِى ٱلْعَذَابِ وَٱلضَّلَٰلِ ٱلْبَعِيدِ', 'b46dfd67051e15394bfb3d0a0149fb1ac6d21d98b59376a9b0c7c54eec0bcba6', 'b46dfd67051e15394bfb3d0a0149fb1ac6d21d98b59376a9b0c7c54eec0bcba6', NULL, 'افتري علي الله كذبا ام به جنه بل الذين لا يؤمنون بالاخره في العذاب والضلل البعيد', 22, 43, 171, 1, 5, 429, false, NULL),
    (3615, 'tanzil-uthmani-v1.1', 34, 9, 'أَفَلَمْ يَرَوْا۟ إِلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ إِن نَّشَأْ نَخْسِفْ بِهِمُ ٱلْأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفًا مِّنَ ٱلسَّمَآءِ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّكُلِّ عَبْدٍ مُّنِيبٍ', '1acf962e13d11093861ddc03a4d83a74eb66061d95cd8f556a13959fc1b5dc51', 'أَفَلَمْ يَرَوْا۟ إِلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ إِن نَّشَأْ نَخْسِفْ بِهِمُ ٱلْأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفًا مِّنَ ٱلسَّمَآءِ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّكُلِّ عَبْدٍ مُّنِيبٍ', '1acf962e13d11093861ddc03a4d83a74eb66061d95cd8f556a13959fc1b5dc51', '1acf962e13d11093861ddc03a4d83a74eb66061d95cd8f556a13959fc1b5dc51', NULL, 'افلم يروا الي ما بين ايديهم وما خلفهم من السماء والارض ان نشا نخسف بهم الارض او نسقط عليهم كسفا من السماء ان في ذلك لايه لكل عبد منيب', 22, 43, 171, 1, 5, 429, false, NULL),
    (3616, 'tanzil-uthmani-v1.1', 34, 10, 'وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ مِنَّا فَضْلًا يَٰجِبَالُ أَوِّبِى مَعَهُۥ وَٱلطَّيْرَ وَأَلَنَّا لَهُ ٱلْحَدِيدَ', 'f239ad4be9a81b3a388771965bf802f1958e39c8cffec6adebc1d67ac764de07', 'وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ مِنَّا فَضْلًا يَٰجِبَالُ أَوِّبِى مَعَهُۥ وَٱلطَّيْرَ وَأَلَنَّا لَهُ ٱلْحَدِيدَ', 'f239ad4be9a81b3a388771965bf802f1958e39c8cffec6adebc1d67ac764de07', 'f239ad4be9a81b3a388771965bf802f1958e39c8cffec6adebc1d67ac764de07', NULL, 'ولقد ءاتينا داود منا فضلا يجبال اوبي معه والطير والنا له الحديد', 22, 43, 172, 1, 5, 429, false, NULL),
    (3617, 'tanzil-uthmani-v1.1', 34, 11, 'أَنِ ٱعْمَلْ سَٰبِغَٰتٍ وَقَدِّرْ فِى ٱلسَّرْدِ وَٱعْمَلُوا۟ صَٰلِحًا إِنِّى بِمَا تَعْمَلُونَ بَصِيرٌ', '9731fb9a578f8f207a11d2e9dcb72b81e3aa26308850f96aa14d29f0fc86003b', 'أَنِ ٱعْمَلْ سَٰبِغَٰتٍ وَقَدِّرْ فِى ٱلسَّرْدِ وَٱعْمَلُوا۟ صَٰلِحًا إِنِّى بِمَا تَعْمَلُونَ بَصِيرٌ', '9731fb9a578f8f207a11d2e9dcb72b81e3aa26308850f96aa14d29f0fc86003b', '9731fb9a578f8f207a11d2e9dcb72b81e3aa26308850f96aa14d29f0fc86003b', NULL, 'ان اعمل سبغت وقدر في السرد واعملوا صلحا اني بما تعملون بصير', 22, 43, 172, 1, 5, 429, false, NULL),
    (3618, 'tanzil-uthmani-v1.1', 34, 12, 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ وَأَسَلْنَا لَهُۥ عَيْنَ ٱلْقِطْرِ وَمِنَ ٱلْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ ٱلسَّعِيرِ', '100a7ee39c9227400726f82b90f995172429a61c4606cb8c750c78c2267a3736', 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ وَأَسَلْنَا لَهُۥ عَيْنَ ٱلْقِطْرِ وَمِنَ ٱلْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ ٱلسَّعِيرِ', '100a7ee39c9227400726f82b90f995172429a61c4606cb8c750c78c2267a3736', '100a7ee39c9227400726f82b90f995172429a61c4606cb8c750c78c2267a3736', NULL, 'ولسليمن الريح غدوها شهر ورواحها شهر واسلنا له عين القطر ومن الجن من يعمل بين يديه باذن ربه ومن يزغ منهم عن امرنا نذقه من عذاب السعير', 22, 43, 172, 1, 5, 429, false, NULL),
    (3619, 'tanzil-uthmani-v1.1', 34, 13, 'يَعْمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٍ كَٱلْجَوَابِ وَقُدُورٍ رَّاسِيَٰتٍ ٱعْمَلُوٓا۟ ءَالَ دَاوُۥدَ شُكْرًا وَقَلِيلٌ مِّنْ عِبَادِىَ ٱلشَّكُورُ', 'e827f482260248f7813d250f86107478f681bbb8f8bc23ffc4a1d138d4502947', 'يَعْمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٍ كَٱلْجَوَابِ وَقُدُورٍ رَّاسِيَٰتٍ ٱعْمَلُوٓا۟ ءَالَ دَاوُۥدَ شُكْرًا وَقَلِيلٌ مِّنْ عِبَادِىَ ٱلشَّكُورُ', 'e827f482260248f7813d250f86107478f681bbb8f8bc23ffc4a1d138d4502947', 'e827f482260248f7813d250f86107478f681bbb8f8bc23ffc4a1d138d4502947', NULL, 'يعملون له ما يشاء من محريب وتمثيل وجفان كالجواب وقدور راسيت اعملوا ءال داود شكرا وقليل من عبادي الشكور', 22, 43, 172, 1, 5, 429, false, NULL),
    (3620, 'tanzil-uthmani-v1.1', 34, 14, 'فَلَمَّا قَضَيْنَا عَلَيْهِ ٱلْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِۦٓ إِلَّا دَآبَّةُ ٱلْأَرْضِ تَأْكُلُ مِنسَأَتَهُۥ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلْجِنُّ أَن لَّوْ كَانُوا۟ يَعْلَمُونَ ٱلْغَيْبَ مَا لَبِثُوا۟ فِى ٱلْعَذَابِ ٱلْمُهِينِ', '182f54b461149f032bb3ff6e13db31008bfe0a2f350d6ee8e820b49bb8f52b23', 'فَلَمَّا قَضَيْنَا عَلَيْهِ ٱلْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِۦٓ إِلَّا دَآبَّةُ ٱلْأَرْضِ تَأْكُلُ مِنسَأَتَهُۥ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلْجِنُّ أَن لَّوْ كَانُوا۟ يَعْلَمُونَ ٱلْغَيْبَ مَا لَبِثُوا۟ فِى ٱلْعَذَابِ ٱلْمُهِينِ', '182f54b461149f032bb3ff6e13db31008bfe0a2f350d6ee8e820b49bb8f52b23', '182f54b461149f032bb3ff6e13db31008bfe0a2f350d6ee8e820b49bb8f52b23', NULL, 'فلما قضينا عليه الموت ما دلهم علي موته الا دابه الارض تاكل منساته فلما خر تبينت الجن ان لو كانوا يعلمون الغيب ما لبثوا في العذاب المهين', 22, 43, 172, 1, 5, 429, false, NULL),
    (3621, 'tanzil-uthmani-v1.1', 34, 15, 'لَقَدْ كَانَ لِسَبَإٍ فِى مَسْكَنِهِمْ ءَايَةٌ جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ كُلُوا۟ مِن رِّزْقِ رَبِّكُمْ وَٱشْكُرُوا۟ لَهُۥ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ', 'ae05b3aaaa723ca3b85017f3cdc6f3ba4086ac83affaa52cecef1f01464bacf8', 'لَقَدْ كَانَ لِسَبَإٍ فِى مَسْكَنِهِمْ ءَايَةٌ جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ كُلُوا۟ مِن رِّزْقِ رَبِّكُمْ وَٱشْكُرُوا۟ لَهُۥ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ', 'ae05b3aaaa723ca3b85017f3cdc6f3ba4086ac83affaa52cecef1f01464bacf8', 'ae05b3aaaa723ca3b85017f3cdc6f3ba4086ac83affaa52cecef1f01464bacf8', NULL, 'لقد كان لسبا في مسكنهم ءايه جنتان عن يمين وشمال كلوا من رزق ربكم واشكروا له بلده طيبه ورب غفور', 22, 43, 172, 1, 5, 430, false, NULL),
    (3622, 'tanzil-uthmani-v1.1', 34, 16, 'فَأَعْرَضُوا۟ فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ ٱلْعَرِمِ وَبَدَّلْنَٰهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَىْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَىْءٍ مِّن سِدْرٍ قَلِيلٍ', 'f4d9a2fe258d6a81c1694d157d842449552db127e41de805a7596cb49284fe43', 'فَأَعْرَضُوا۟ فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ ٱلْعَرِمِ وَبَدَّلْنَٰهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَىْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَىْءٍ مِّن سِدْرٍ قَلِيلٍ', 'f4d9a2fe258d6a81c1694d157d842449552db127e41de805a7596cb49284fe43', 'f4d9a2fe258d6a81c1694d157d842449552db127e41de805a7596cb49284fe43', NULL, 'فاعرضوا فارسلنا عليهم سيل العرم وبدلنهم بجنتيهم جنتين ذواتي اكل خمط واثل وشيء من سدر قليل', 22, 43, 172, 1, 5, 430, false, NULL),
    (3623, 'tanzil-uthmani-v1.1', 34, 17, 'ذَٰلِكَ جَزَيْنَٰهُم بِمَا كَفَرُوا۟ وَهَلْ نُجَٰزِىٓ إِلَّا ٱلْكَفُورَ', 'a11a087d2ca65b49b319d09e2004eadc47e1345c84e0d2896002751541ffe900', 'ذَٰلِكَ جَزَيْنَٰهُم بِمَا كَفَرُوا۟ وَهَلْ نُجَٰزِىٓ إِلَّا ٱلْكَفُورَ', 'a11a087d2ca65b49b319d09e2004eadc47e1345c84e0d2896002751541ffe900', 'a11a087d2ca65b49b319d09e2004eadc47e1345c84e0d2896002751541ffe900', NULL, 'ذلك جزينهم بما كفروا وهل نجزي الا الكفور', 22, 43, 172, 1, 5, 430, false, NULL),
    (3624, 'tanzil-uthmani-v1.1', 34, 18, 'وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ ٱلْقُرَى ٱلَّتِى بَٰرَكْنَا فِيهَا قُرًى ظَٰهِرَةً وَقَدَّرْنَا فِيهَا ٱلسَّيْرَ سِيرُوا۟ فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِنِينَ', '50559180b0e60a85ec2e5916fb78f0a4ef2e18cce9fc7de4173a51d84754032d', 'وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ ٱلْقُرَى ٱلَّتِى بَٰرَكْنَا فِيهَا قُرًى ظَٰهِرَةً وَقَدَّرْنَا فِيهَا ٱلسَّيْرَ سِيرُوا۟ فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِنِينَ', '50559180b0e60a85ec2e5916fb78f0a4ef2e18cce9fc7de4173a51d84754032d', '50559180b0e60a85ec2e5916fb78f0a4ef2e18cce9fc7de4173a51d84754032d', NULL, 'وجعلنا بينهم وبين القري التي بركنا فيها قري ظهره وقدرنا فيها السير سيروا فيها ليالي واياما ءامنين', 22, 43, 172, 1, 5, 430, false, NULL),
    (3625, 'tanzil-uthmani-v1.1', 34, 19, 'فَقَالُوا۟ رَبَّنَا بَٰعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوٓا۟ أَنفُسَهُمْ فَجَعَلْنَٰهُمْ أَحَادِيثَ وَمَزَّقْنَٰهُمْ كُلَّ مُمَزَّقٍ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'aed49104390293c462ca393d107cfba98fd3bd72deda71040906bab4bb4859af', 'فَقَالُوا۟ رَبَّنَا بَٰعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوٓا۟ أَنفُسَهُمْ فَجَعَلْنَٰهُمْ أَحَادِيثَ وَمَزَّقْنَٰهُمْ كُلَّ مُمَزَّقٍ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', 'aed49104390293c462ca393d107cfba98fd3bd72deda71040906bab4bb4859af', 'aed49104390293c462ca393d107cfba98fd3bd72deda71040906bab4bb4859af', NULL, 'فقالوا ربنا بعد بين اسفارنا وظلموا انفسهم فجعلنهم احاديث ومزقنهم كل ممزق ان في ذلك لايت لكل صبار شكور', 22, 43, 172, 1, 5, 430, false, NULL),
    (3626, 'tanzil-uthmani-v1.1', 34, 20, 'وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ', '10c525a61f9b7a0614135894a0b069a8174e1109e9690fd8e398f2d4a06b7ba8', 'وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ', '10c525a61f9b7a0614135894a0b069a8174e1109e9690fd8e398f2d4a06b7ba8', '10c525a61f9b7a0614135894a0b069a8174e1109e9690fd8e398f2d4a06b7ba8', NULL, 'ولقد صدق عليهم ابليس ظنه فاتبعوه الا فريقا من المؤمنين', 22, 43, 172, 1, 5, 430, false, NULL),
    (3627, 'tanzil-uthmani-v1.1', 34, 21, 'وَمَا كَانَ لَهُۥ عَلَيْهِم مِّن سُلْطَٰنٍ إِلَّا لِنَعْلَمَ مَن يُؤْمِنُ بِٱلْـَٔاخِرَةِ مِمَّنْ هُوَ مِنْهَا فِى شَكٍّ وَرَبُّكَ عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', 'd160b47b43bd3dd8aed0d4d8ec2641f949fae0316058acc7e905fb73e07a695f', 'وَمَا كَانَ لَهُۥ عَلَيْهِم مِّن سُلْطَٰنٍ إِلَّا لِنَعْلَمَ مَن يُؤْمِنُ بِٱلْـَٔاخِرَةِ مِمَّنْ هُوَ مِنْهَا فِى شَكٍّ وَرَبُّكَ عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ', 'd160b47b43bd3dd8aed0d4d8ec2641f949fae0316058acc7e905fb73e07a695f', 'd160b47b43bd3dd8aed0d4d8ec2641f949fae0316058acc7e905fb73e07a695f', NULL, 'وما كان له عليهم من سلطن الا لنعلم من يؤمن بالاخره ممن هو منها في شك وربك علي كل شيء حفيظ', 22, 43, 172, 1, 5, 430, false, NULL),
    (3628, 'tanzil-uthmani-v1.1', 34, 22, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِ ٱللَّهِ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِن شِرْكٍ وَمَا لَهُۥ مِنْهُم مِّن ظَهِيرٍ', '9540964ec67f327d65b2eb6f285f1d9e43e77fe90524ae5c67807ee78ff125d0', 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِ ٱللَّهِ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِن شِرْكٍ وَمَا لَهُۥ مِنْهُم مِّن ظَهِيرٍ', '9540964ec67f327d65b2eb6f285f1d9e43e77fe90524ae5c67807ee78ff125d0', '9540964ec67f327d65b2eb6f285f1d9e43e77fe90524ae5c67807ee78ff125d0', NULL, 'قل ادعوا الذين زعمتم من دون الله لا يملكون مثقال ذره في السموت ولا في الارض وما لهم فيهما من شرك وما له منهم من ظهير', 22, 43, 172, 1, 5, 430, false, NULL),
    (3629, 'tanzil-uthmani-v1.1', 34, 23, 'وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنْ أَذِنَ لَهُۥ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا۟ مَاذَا قَالَ رَبُّكُمْ قَالُوا۟ ٱلْحَقَّ وَهُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', '6534d9afab0dcf90362fe58d6cd272ae9f2da8423afa8e49aef9080510c041bd', 'وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنْ أَذِنَ لَهُۥ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا۟ مَاذَا قَالَ رَبُّكُمْ قَالُوا۟ ٱلْحَقَّ وَهُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', '6534d9afab0dcf90362fe58d6cd272ae9f2da8423afa8e49aef9080510c041bd', '6534d9afab0dcf90362fe58d6cd272ae9f2da8423afa8e49aef9080510c041bd', NULL, 'ولا تنفع الشفعه عنده الا لمن اذن له حتي اذا فزع عن قلوبهم قالوا ماذا قال ربكم قالوا الحق وهو العلي الكبير', 22, 43, 172, 1, 5, 431, false, NULL),
    (3630, 'tanzil-uthmani-v1.1', 34, 24, 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ وَإِنَّآ أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَٰلٍ مُّبِينٍ', 'a216c84a0cafe957fcdf9e6d2843e945c99e287c0e09d96d402fb427ab114f21', 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ وَإِنَّآ أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَٰلٍ مُّبِينٍ', 'a216c84a0cafe957fcdf9e6d2843e945c99e287c0e09d96d402fb427ab114f21', 'a216c84a0cafe957fcdf9e6d2843e945c99e287c0e09d96d402fb427ab114f21', NULL, 'قل من يرزقكم من السموت والارض قل الله وانا او اياكم لعلي هدي او في ضلل مبين', 22, 44, 173, 1, 5, 431, false, NULL),
    (3631, 'tanzil-uthmani-v1.1', 34, 25, 'قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ', '313b47ad8cf1241a44cb137e6836a1b6c5b671b43f355abba05d29d7852a3514', 'قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ', '313b47ad8cf1241a44cb137e6836a1b6c5b671b43f355abba05d29d7852a3514', '313b47ad8cf1241a44cb137e6836a1b6c5b671b43f355abba05d29d7852a3514', NULL, 'قل لا تسلون عما اجرمنا ولا نسل عما تعملون', 22, 44, 173, 1, 5, 431, false, NULL),
    (3632, 'tanzil-uthmani-v1.1', 34, 26, 'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِٱلْحَقِّ وَهُوَ ٱلْفَتَّاحُ ٱلْعَلِيمُ', '0b8f2127d2edc3d68f58590e4552942923baa8f6ea9c071c6ec2ab67d3597f6e', 'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِٱلْحَقِّ وَهُوَ ٱلْفَتَّاحُ ٱلْعَلِيمُ', '0b8f2127d2edc3d68f58590e4552942923baa8f6ea9c071c6ec2ab67d3597f6e', '0b8f2127d2edc3d68f58590e4552942923baa8f6ea9c071c6ec2ab67d3597f6e', NULL, 'قل يجمع بيننا ربنا ثم يفتح بيننا بالحق وهو الفتاح العليم', 22, 44, 173, 1, 5, 431, false, NULL),
    (3633, 'tanzil-uthmani-v1.1', 34, 27, 'قُلْ أَرُونِىَ ٱلَّذِينَ أَلْحَقْتُم بِهِۦ شُرَكَآءَ كَلَّا بَلْ هُوَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'c594012330dc733c5199573bc9e0461a034f826894692279bcbb0ff7a86ffa28', 'قُلْ أَرُونِىَ ٱلَّذِينَ أَلْحَقْتُم بِهِۦ شُرَكَآءَ كَلَّا بَلْ هُوَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'c594012330dc733c5199573bc9e0461a034f826894692279bcbb0ff7a86ffa28', 'c594012330dc733c5199573bc9e0461a034f826894692279bcbb0ff7a86ffa28', NULL, 'قل اروني الذين الحقتم به شركاء كلا بل هو الله العزيز الحكيم', 22, 44, 173, 1, 5, 431, false, NULL),
    (3634, 'tanzil-uthmani-v1.1', 34, 28, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا كَآفَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '7b452be6f35d773c9a8e17ef466881cf1d56b59f4ef3f1f1fed7834f2b78f8e2', 'وَمَآ أَرْسَلْنَٰكَ إِلَّا كَآفَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '7b452be6f35d773c9a8e17ef466881cf1d56b59f4ef3f1f1fed7834f2b78f8e2', '7b452be6f35d773c9a8e17ef466881cf1d56b59f4ef3f1f1fed7834f2b78f8e2', NULL, 'وما ارسلنك الا كافه للناس بشيرا ونذيرا ولكن اكثر الناس لا يعلمون', 22, 44, 173, 1, 5, 431, false, NULL),
    (3635, 'tanzil-uthmani-v1.1', 34, 29, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', NULL, 'ويقولون متي هذا الوعد ان كنتم صدقين', 22, 44, 173, 1, 5, 431, false, NULL),
    (3636, 'tanzil-uthmani-v1.1', 34, 30, 'قُل لَّكُم مِّيعَادُ يَوْمٍ لَّا تَسْتَـْٔخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ', '094471bec3edc3abb0a83507954384f602de77f28120bec2d91a845c3a9f2016', 'قُل لَّكُم مِّيعَادُ يَوْمٍ لَّا تَسْتَـْٔخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ', '094471bec3edc3abb0a83507954384f602de77f28120bec2d91a845c3a9f2016', '094471bec3edc3abb0a83507954384f602de77f28120bec2d91a845c3a9f2016', NULL, 'قل لكم ميعاد يوم لا تستخرون عنه ساعه ولا تستقدمون', 22, 44, 173, 1, 5, 431, false, NULL),
    (3637, 'tanzil-uthmani-v1.1', 34, 31, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَن نُّؤْمِنَ بِهَٰذَا ٱلْقُرْءَانِ وَلَا بِٱلَّذِى بَيْنَ يَدَيْهِ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ ٱلْقَوْلَ يَقُولُ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ لَوْلَآ أَنتُمْ لَكُنَّا مُؤْمِنِينَ', 'a9413d37b054739b3943a1e37240c9b7c8900b8b07c0d8c6cee1f4cfe19b273e', 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَن نُّؤْمِنَ بِهَٰذَا ٱلْقُرْءَانِ وَلَا بِٱلَّذِى بَيْنَ يَدَيْهِ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ ٱلْقَوْلَ يَقُولُ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ لَوْلَآ أَنتُمْ لَكُنَّا مُؤْمِنِينَ', 'a9413d37b054739b3943a1e37240c9b7c8900b8b07c0d8c6cee1f4cfe19b273e', 'a9413d37b054739b3943a1e37240c9b7c8900b8b07c0d8c6cee1f4cfe19b273e', NULL, 'وقال الذين كفروا لن نؤمن بهذا القرءان ولا بالذي بين يديه ولو تري اذ الظلمون موقوفون عند ربهم يرجع بعضهم الي بعض القول يقول الذين استضعفوا للذين استكبروا لولا انتم لكنا مؤمنين', 22, 44, 173, 1, 5, 431, false, NULL),
    (3638, 'tanzil-uthmani-v1.1', 34, 32, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ لِلَّذِينَ ٱسْتُضْعِفُوٓا۟ أَنَحْنُ صَدَدْنَٰكُمْ عَنِ ٱلْهُدَىٰ بَعْدَ إِذْ جَآءَكُم بَلْ كُنتُم مُّجْرِمِينَ', 'f9bb66caae401bb7c80fddc99ba6dc9795498ca81caf0cc6537e379eed43c7c8', 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ لِلَّذِينَ ٱسْتُضْعِفُوٓا۟ أَنَحْنُ صَدَدْنَٰكُمْ عَنِ ٱلْهُدَىٰ بَعْدَ إِذْ جَآءَكُم بَلْ كُنتُم مُّجْرِمِينَ', 'f9bb66caae401bb7c80fddc99ba6dc9795498ca81caf0cc6537e379eed43c7c8', 'f9bb66caae401bb7c80fddc99ba6dc9795498ca81caf0cc6537e379eed43c7c8', NULL, 'قال الذين استكبروا للذين استضعفوا انحن صددنكم عن الهدي بعد اذ جاءكم بل كنتم مجرمين', 22, 44, 173, 1, 5, 432, false, NULL),
    (3639, 'tanzil-uthmani-v1.1', 34, 33, 'وَقَالَ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ بَلْ مَكْرُ ٱلَّيْلِ وَٱلنَّهَارِ إِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِٱللَّهِ وَنَجْعَلَ لَهُۥٓ أَندَادًا وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَجَعَلْنَا ٱلْأَغْلَٰلَ فِىٓ أَعْنَاقِ ٱلَّذِينَ كَفَرُوا۟ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'aed074f87437f89e8cfbe6d95f5170dc11da9652576dc7e84c82607eeeb20e65', 'وَقَالَ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ بَلْ مَكْرُ ٱلَّيْلِ وَٱلنَّهَارِ إِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِٱللَّهِ وَنَجْعَلَ لَهُۥٓ أَندَادًا وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَجَعَلْنَا ٱلْأَغْلَٰلَ فِىٓ أَعْنَاقِ ٱلَّذِينَ كَفَرُوا۟ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 'aed074f87437f89e8cfbe6d95f5170dc11da9652576dc7e84c82607eeeb20e65', 'aed074f87437f89e8cfbe6d95f5170dc11da9652576dc7e84c82607eeeb20e65', NULL, 'وقال الذين استضعفوا للذين استكبروا بل مكر اليل والنهار اذ تامروننا ان نكفر بالله ونجعل له اندادا واسروا الندامه لما راوا العذاب وجعلنا الاغلل في اعناق الذين كفروا هل يجزون الا ما كانوا يعملون', 22, 44, 173, 1, 5, 432, false, NULL),
    (3640, 'tanzil-uthmani-v1.1', 34, 34, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', '6c6b98a150f17980e5a042c2b36812ca86f42a194236c8368b6cc77223370842', 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', '6c6b98a150f17980e5a042c2b36812ca86f42a194236c8368b6cc77223370842', '6c6b98a150f17980e5a042c2b36812ca86f42a194236c8368b6cc77223370842', NULL, 'وما ارسلنا في قريه من نذير الا قال مترفوها انا بما ارسلتم به كفرون', 22, 44, 173, 1, 5, 432, false, NULL),
    (3641, 'tanzil-uthmani-v1.1', 34, 35, 'وَقَالُوا۟ نَحْنُ أَكْثَرُ أَمْوَٰلًا وَأَوْلَٰدًا وَمَا نَحْنُ بِمُعَذَّبِينَ', '83bb1455cb6625bd64df8ae9b32e9662ec4ba4f1986e8eff69a370614b936c20', 'وَقَالُوا۟ نَحْنُ أَكْثَرُ أَمْوَٰلًا وَأَوْلَٰدًا وَمَا نَحْنُ بِمُعَذَّبِينَ', '83bb1455cb6625bd64df8ae9b32e9662ec4ba4f1986e8eff69a370614b936c20', '83bb1455cb6625bd64df8ae9b32e9662ec4ba4f1986e8eff69a370614b936c20', NULL, 'وقالوا نحن اكثر امولا واولدا وما نحن بمعذبين', 22, 44, 173, 1, 5, 432, false, NULL),
    (3642, 'tanzil-uthmani-v1.1', 34, 36, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '19114aeca197e7a98cc4277f0045c782415a1348317022af9adaa148412d1eb2', 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '19114aeca197e7a98cc4277f0045c782415a1348317022af9adaa148412d1eb2', '19114aeca197e7a98cc4277f0045c782415a1348317022af9adaa148412d1eb2', NULL, 'قل ان ربي يبسط الرزق لمن يشاء ويقدر ولكن اكثر الناس لا يعلمون', 22, 44, 173, 1, 5, 432, false, NULL),
    (3643, 'tanzil-uthmani-v1.1', 34, 37, 'وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُم بِٱلَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰٓ إِلَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ لَهُمْ جَزَآءُ ٱلضِّعْفِ بِمَا عَمِلُوا۟ وَهُمْ فِى ٱلْغُرُفَٰتِ ءَامِنُونَ', 'f0a41b04a9c94961008b90e74c6f4a968ad20ff6ede565f7af8f181274096b25', 'وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُم بِٱلَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰٓ إِلَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ لَهُمْ جَزَآءُ ٱلضِّعْفِ بِمَا عَمِلُوا۟ وَهُمْ فِى ٱلْغُرُفَٰتِ ءَامِنُونَ', 'f0a41b04a9c94961008b90e74c6f4a968ad20ff6ede565f7af8f181274096b25', 'f0a41b04a9c94961008b90e74c6f4a968ad20ff6ede565f7af8f181274096b25', NULL, 'وما امولكم ولا اولدكم بالتي تقربكم عندنا زلفي الا من ءامن وعمل صلحا فاولئك لهم جزاء الضعف بما عملوا وهم في الغرفت ءامنون', 22, 44, 173, 1, 5, 432, false, NULL),
    (3644, 'tanzil-uthmani-v1.1', 34, 38, 'وَٱلَّذِينَ يَسْعَوْنَ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', '7902b7c878a3965e37ec3809ef03e401887b7fedfd0c89e52e42405610b54059', 'وَٱلَّذِينَ يَسْعَوْنَ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ', '7902b7c878a3965e37ec3809ef03e401887b7fedfd0c89e52e42405610b54059', '7902b7c878a3965e37ec3809ef03e401887b7fedfd0c89e52e42405610b54059', NULL, 'والذين يسعون في ءايتنا معجزين اولئك في العذاب محضرون', 22, 44, 173, 1, 5, 432, false, NULL),
    (3645, 'tanzil-uthmani-v1.1', 34, 39, 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥ وَمَآ أَنفَقْتُم مِّن شَىْءٍ فَهُوَ يُخْلِفُهُۥ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'b72c8b77c0e2ff076cda1f4d38e7a2e7b9510d12f7a1413842e787e7952498c1', 'قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥ وَمَآ أَنفَقْتُم مِّن شَىْءٍ فَهُوَ يُخْلِفُهُۥ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 'b72c8b77c0e2ff076cda1f4d38e7a2e7b9510d12f7a1413842e787e7952498c1', 'b72c8b77c0e2ff076cda1f4d38e7a2e7b9510d12f7a1413842e787e7952498c1', NULL, 'قل ان ربي يبسط الرزق لمن يشاء من عباده ويقدر له وما انفقتم من شيء فهو يخلفه وهو خير الرزقين', 22, 44, 173, 1, 5, 432, false, NULL),
    (3646, 'tanzil-uthmani-v1.1', 34, 40, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمْ كَانُوا۟ يَعْبُدُونَ', '9033b0ae54ee0e4ede13663c2b25bd86612c701593bf0450d91be62e5d13dd9b', 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمْ كَانُوا۟ يَعْبُدُونَ', '9033b0ae54ee0e4ede13663c2b25bd86612c701593bf0450d91be62e5d13dd9b', '9033b0ae54ee0e4ede13663c2b25bd86612c701593bf0450d91be62e5d13dd9b', NULL, 'ويوم يحشرهم جميعا ثم يقول للملئكه اهؤلاء اياكم كانوا يعبدون', 22, 44, 173, 1, 5, 433, false, NULL),
    (3647, 'tanzil-uthmani-v1.1', 34, 41, 'قَالُوا۟ سُبْحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم بَلْ كَانُوا۟ يَعْبُدُونَ ٱلْجِنَّ أَكْثَرُهُم بِهِم مُّؤْمِنُونَ', 'cc91c395b8f96c41380299a88b2e76d13b46c9f72292342a3d53082c2ece51bd', 'قَالُوا۟ سُبْحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم بَلْ كَانُوا۟ يَعْبُدُونَ ٱلْجِنَّ أَكْثَرُهُم بِهِم مُّؤْمِنُونَ', 'cc91c395b8f96c41380299a88b2e76d13b46c9f72292342a3d53082c2ece51bd', 'cc91c395b8f96c41380299a88b2e76d13b46c9f72292342a3d53082c2ece51bd', NULL, 'قالوا سبحنك انت ولينا من دونهم بل كانوا يعبدون الجن اكثرهم بهم مؤمنون', 22, 44, 173, 1, 5, 433, false, NULL),
    (3648, 'tanzil-uthmani-v1.1', 34, 42, 'فَٱلْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَّفْعًا وَلَا ضَرًّا وَنَقُولُ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', 'e1e03d40e39ff9f0464c7585f9f3c78ac9bb3f77fcb09ca17ee28c5ad0047b03', 'فَٱلْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَّفْعًا وَلَا ضَرًّا وَنَقُولُ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', 'e1e03d40e39ff9f0464c7585f9f3c78ac9bb3f77fcb09ca17ee28c5ad0047b03', 'e1e03d40e39ff9f0464c7585f9f3c78ac9bb3f77fcb09ca17ee28c5ad0047b03', NULL, 'فاليوم لا يملك بعضكم لبعض نفعا ولا ضرا ونقول للذين ظلموا ذوقوا عذاب النار التي كنتم بها تكذبون', 22, 44, 173, 1, 5, 433, false, NULL),
    (3649, 'tanzil-uthmani-v1.1', 34, 43, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالُوا۟ مَا هَٰذَآ إِلَّا رَجُلٌ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُوا۟ مَا هَٰذَآ إِلَّآ إِفْكٌ مُّفْتَرًى وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', '940ae8aa682a5e1f3ed2608ace5945942cd47ebd79344972d2a9f19d23b193c1', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالُوا۟ مَا هَٰذَآ إِلَّا رَجُلٌ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُوا۟ مَا هَٰذَآ إِلَّآ إِفْكٌ مُّفْتَرًى وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ', '940ae8aa682a5e1f3ed2608ace5945942cd47ebd79344972d2a9f19d23b193c1', '940ae8aa682a5e1f3ed2608ace5945942cd47ebd79344972d2a9f19d23b193c1', NULL, 'واذا تتلي عليهم ءايتنا بينت قالوا ما هذا الا رجل يريد ان يصدكم عما كان يعبد ءاباؤكم وقالوا ما هذا الا افك مفتري وقال الذين كفروا للحق لما جاءهم ان هذا الا سحر مبين', 22, 44, 173, 1, 5, 433, false, NULL),
    (3650, 'tanzil-uthmani-v1.1', 34, 44, 'وَمَآ ءَاتَيْنَٰهُم مِّن كُتُبٍ يَدْرُسُونَهَا وَمَآ أَرْسَلْنَآ إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرٍ', '459b974cb082b0a069098b782a3473c60fe1c42fb349cf4edaf85040f00db9b6', 'وَمَآ ءَاتَيْنَٰهُم مِّن كُتُبٍ يَدْرُسُونَهَا وَمَآ أَرْسَلْنَآ إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرٍ', '459b974cb082b0a069098b782a3473c60fe1c42fb349cf4edaf85040f00db9b6', '459b974cb082b0a069098b782a3473c60fe1c42fb349cf4edaf85040f00db9b6', NULL, 'وما ءاتينهم من كتب يدرسونها وما ارسلنا اليهم قبلك من نذير', 22, 44, 173, 1, 5, 433, false, NULL),
    (3651, 'tanzil-uthmani-v1.1', 34, 45, 'وَكَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا۟ مِعْشَارَ مَآ ءَاتَيْنَٰهُمْ فَكَذَّبُوا۟ رُسُلِى فَكَيْفَ كَانَ نَكِيرِ', 'd48ed77f6d4e7074d33dff9be6ebf2682df13c201bebe385d7a67e3af44c226a', 'وَكَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا۟ مِعْشَارَ مَآ ءَاتَيْنَٰهُمْ فَكَذَّبُوا۟ رُسُلِى فَكَيْفَ كَانَ نَكِيرِ', 'd48ed77f6d4e7074d33dff9be6ebf2682df13c201bebe385d7a67e3af44c226a', 'd48ed77f6d4e7074d33dff9be6ebf2682df13c201bebe385d7a67e3af44c226a', NULL, 'وكذب الذين من قبلهم وما بلغوا معشار ما ءاتينهم فكذبوا رسلي فكيف كان نكير', 22, 44, 173, 1, 5, 433, false, NULL),
    (3652, 'tanzil-uthmani-v1.1', 34, 46, 'قُلْ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍ أَن تَقُومُوا۟ لِلَّهِ مَثْنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُوا۟ مَا بِصَاحِبِكُم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ لَّكُم بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ', '258be05d1b79a05da2d41b76df3d414bf8851a616fa92f12b58b4c1e5d425b36', 'قُلْ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍ أَن تَقُومُوا۟ لِلَّهِ مَثْنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُوا۟ مَا بِصَاحِبِكُم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ لَّكُم بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ', '258be05d1b79a05da2d41b76df3d414bf8851a616fa92f12b58b4c1e5d425b36', '258be05d1b79a05da2d41b76df3d414bf8851a616fa92f12b58b4c1e5d425b36', NULL, 'قل انما اعظكم بوحده ان تقوموا لله مثني وفردي ثم تتفكروا ما بصاحبكم من جنه ان هو الا نذير لكم بين يدي عذاب شديد', 22, 44, 174, 1, 5, 433, false, NULL),
    (3653, 'tanzil-uthmani-v1.1', 34, 47, 'قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍ فَهُوَ لَكُمْ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '1e8bdd775394fb9a06c2d56acfea2fa13415cbbb18935da1b418d1df9a2ed7f6', 'قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍ فَهُوَ لَكُمْ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '1e8bdd775394fb9a06c2d56acfea2fa13415cbbb18935da1b418d1df9a2ed7f6', '1e8bdd775394fb9a06c2d56acfea2fa13415cbbb18935da1b418d1df9a2ed7f6', NULL, 'قل ما سالتكم من اجر فهو لكم ان اجري الا علي الله وهو علي كل شيء شهيد', 22, 44, 174, 1, 5, 433, false, NULL),
    (3654, 'tanzil-uthmani-v1.1', 34, 48, 'قُلْ إِنَّ رَبِّى يَقْذِفُ بِٱلْحَقِّ عَلَّٰمُ ٱلْغُيُوبِ', '1cd07db1891727e6a4733ff84941e5f17ecc150bb22913ca74186d099429d2f0', 'قُلْ إِنَّ رَبِّى يَقْذِفُ بِٱلْحَقِّ عَلَّٰمُ ٱلْغُيُوبِ', '1cd07db1891727e6a4733ff84941e5f17ecc150bb22913ca74186d099429d2f0', '1cd07db1891727e6a4733ff84941e5f17ecc150bb22913ca74186d099429d2f0', NULL, 'قل ان ربي يقذف بالحق علم الغيوب', 22, 44, 174, 1, 5, 433, false, NULL),
    (3655, 'tanzil-uthmani-v1.1', 34, 49, 'قُلْ جَآءَ ٱلْحَقُّ وَمَا يُبْدِئُ ٱلْبَٰطِلُ وَمَا يُعِيدُ', '333aaa62169e108a1224ce547db8234e53b08bbece72b4bb4f35d90da346b64c', 'قُلْ جَآءَ ٱلْحَقُّ وَمَا يُبْدِئُ ٱلْبَٰطِلُ وَمَا يُعِيدُ', '333aaa62169e108a1224ce547db8234e53b08bbece72b4bb4f35d90da346b64c', '333aaa62169e108a1224ce547db8234e53b08bbece72b4bb4f35d90da346b64c', NULL, 'قل جاء الحق وما يبدئ البطل وما يعيد', 22, 44, 174, 1, 5, 434, false, NULL),
    (3656, 'tanzil-uthmani-v1.1', 34, 50, 'قُلْ إِن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفْسِى وَإِنِ ٱهْتَدَيْتُ فَبِمَا يُوحِىٓ إِلَىَّ رَبِّىٓ إِنَّهُۥ سَمِيعٌ قَرِيبٌ', 'bb0c03ce169b8bc9c94ff97fcf9a5f350cd1a2b9e8bc1ba4a5d0ed767b9bd163', 'قُلْ إِن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفْسِى وَإِنِ ٱهْتَدَيْتُ فَبِمَا يُوحِىٓ إِلَىَّ رَبِّىٓ إِنَّهُۥ سَمِيعٌ قَرِيبٌ', 'bb0c03ce169b8bc9c94ff97fcf9a5f350cd1a2b9e8bc1ba4a5d0ed767b9bd163', 'bb0c03ce169b8bc9c94ff97fcf9a5f350cd1a2b9e8bc1ba4a5d0ed767b9bd163', NULL, 'قل ان ضللت فانما اضل علي نفسي وان اهتديت فبما يوحي الي ربي انه سميع قريب', 22, 44, 174, 1, 5, 434, false, NULL),
    (3657, 'tanzil-uthmani-v1.1', 34, 51, 'وَلَوْ تَرَىٰٓ إِذْ فَزِعُوا۟ فَلَا فَوْتَ وَأُخِذُوا۟ مِن مَّكَانٍ قَرِيبٍ', '8a896b978a6ce6eab573c58972cab4f84baea564ce81b4cffb9384fe00b3afbe', 'وَلَوْ تَرَىٰٓ إِذْ فَزِعُوا۟ فَلَا فَوْتَ وَأُخِذُوا۟ مِن مَّكَانٍ قَرِيبٍ', '8a896b978a6ce6eab573c58972cab4f84baea564ce81b4cffb9384fe00b3afbe', '8a896b978a6ce6eab573c58972cab4f84baea564ce81b4cffb9384fe00b3afbe', NULL, 'ولو تري اذ فزعوا فلا فوت واخذوا من مكان قريب', 22, 44, 174, 1, 5, 434, false, NULL),
    (3658, 'tanzil-uthmani-v1.1', 34, 52, 'وَقَالُوٓا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانٍۭ بَعِيدٍ', '7753f9b782da8ee1c4ba186e4ea902fe735a41d7cf53efd97a53c93ae75941e2', 'وَقَالُوٓا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانٍۭ بَعِيدٍ', '7753f9b782da8ee1c4ba186e4ea902fe735a41d7cf53efd97a53c93ae75941e2', '7753f9b782da8ee1c4ba186e4ea902fe735a41d7cf53efd97a53c93ae75941e2', NULL, 'وقالوا ءامنا به واني لهم التناوش من مكان بعيد', 22, 44, 174, 1, 5, 434, false, NULL),
    (3659, 'tanzil-uthmani-v1.1', 34, 53, 'وَقَدْ كَفَرُوا۟ بِهِۦ مِن قَبْلُ وَيَقْذِفُونَ بِٱلْغَيْبِ مِن مَّكَانٍۭ بَعِيدٍ', '7dc28f26a14a1814a6dc734cb4babf66ae838c8c88ee4478bd8abeab84281913', 'وَقَدْ كَفَرُوا۟ بِهِۦ مِن قَبْلُ وَيَقْذِفُونَ بِٱلْغَيْبِ مِن مَّكَانٍۭ بَعِيدٍ', '7dc28f26a14a1814a6dc734cb4babf66ae838c8c88ee4478bd8abeab84281913', '7dc28f26a14a1814a6dc734cb4babf66ae838c8c88ee4478bd8abeab84281913', NULL, 'وقد كفروا به من قبل ويقذفون بالغيب من مكان بعيد', 22, 44, 174, 1, 5, 434, false, NULL),
    (3660, 'tanzil-uthmani-v1.1', 34, 54, 'وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ فِى شَكٍّ مُّرِيبٍۭ', '487a0784cb46f01bacd2ade71fa8dfc0d94501eb0af74721bc377dfc96f1d043', 'وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ فِى شَكٍّ مُّرِيبٍۭ', '487a0784cb46f01bacd2ade71fa8dfc0d94501eb0af74721bc377dfc96f1d043', '487a0784cb46f01bacd2ade71fa8dfc0d94501eb0af74721bc377dfc96f1d043', NULL, 'وحيل بينهم وبين ما يشتهون كما فعل باشياعهم من قبل انهم كانوا في شك مريب', 22, 44, 174, 1, 5, 434, false, NULL),
    (3661, 'tanzil-uthmani-v1.1', 35, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '5fd9b8d7bae87cf822891cc7ba471b8cee2e434b7fd4f752038f5a7a5e9bf719', 'ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '8d9a6b8b4eb3d702929e2a9afffabe7242974e3dcb28e538dc47d4798f0a42f6', '8d9a6b8b4eb3d702929e2a9afffabe7242974e3dcb28e538dc47d4798f0a42f6', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الحمد لله فاطر السموت والارض جاعل الملئكه رسلا اولي اجنحه مثني وثلث وربع يزيد في الخلق ما يشاء ان الله علي كل شيء قدير', 22, 44, 174, 1, 5, 434, false, NULL),
    (3662, 'tanzil-uthmani-v1.1', 35, 2, 'مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلَا مُمْسِكَ لَهَا وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '7ac176c13a852c3878287dc29e7fd05ff5efc2bb9889f53660c1971279cb9814', 'مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلَا مُمْسِكَ لَهَا وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '7ac176c13a852c3878287dc29e7fd05ff5efc2bb9889f53660c1971279cb9814', '7ac176c13a852c3878287dc29e7fd05ff5efc2bb9889f53660c1971279cb9814', NULL, 'ما يفتح الله للناس من رحمه فلا ممسك لها وما يمسك فلا مرسل له من بعده وهو العزيز الحكيم', 22, 44, 174, 1, 5, 434, false, NULL),
    (3663, 'tanzil-uthmani-v1.1', 35, 3, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ هَلْ مِنْ خَٰلِقٍ غَيْرُ ٱللَّهِ يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ', '3b4e2c3a00dfaff5761a24cafc5fd3013126e493f84aff5bd79b0dca70decee5', 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ هَلْ مِنْ خَٰلِقٍ غَيْرُ ٱللَّهِ يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ', '3b4e2c3a00dfaff5761a24cafc5fd3013126e493f84aff5bd79b0dca70decee5', '3b4e2c3a00dfaff5761a24cafc5fd3013126e493f84aff5bd79b0dca70decee5', NULL, 'يايها الناس اذكروا نعمت الله عليكم هل من خلق غير الله يرزقكم من السماء والارض لا اله الا هو فاني تؤفكون', 22, 44, 174, 1, 5, 434, false, NULL),
    (3664, 'tanzil-uthmani-v1.1', 35, 4, 'وَإِن يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'abf2d524cc6b30c1e64e1eae571bde6cd0a8a7734ef167369cffa6b4595be31d', 'وَإِن يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'abf2d524cc6b30c1e64e1eae571bde6cd0a8a7734ef167369cffa6b4595be31d', 'abf2d524cc6b30c1e64e1eae571bde6cd0a8a7734ef167369cffa6b4595be31d', NULL, 'وان يكذبوك فقد كذبت رسل من قبلك والي الله ترجع الامور', 22, 44, 174, 1, 5, 435, false, NULL),
    (3665, 'tanzil-uthmani-v1.1', 35, 5, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', '39a6c6bf2987e9ce4efadea07f7def088c7e8d384ade0555875ad630c2269f66', 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ', '39a6c6bf2987e9ce4efadea07f7def088c7e8d384ade0555875ad630c2269f66', '39a6c6bf2987e9ce4efadea07f7def088c7e8d384ade0555875ad630c2269f66', NULL, 'يايها الناس ان وعد الله حق فلا تغرنكم الحيوه الدنيا ولا يغرنكم بالله الغرور', 22, 44, 174, 1, 5, 435, false, NULL),
    (3666, 'tanzil-uthmani-v1.1', 35, 6, 'إِنَّ ٱلشَّيْطَٰنَ لَكُمْ عَدُوٌّ فَٱتَّخِذُوهُ عَدُوًّا إِنَّمَا يَدْعُوا۟ حِزْبَهُۥ لِيَكُونُوا۟ مِنْ أَصْحَٰبِ ٱلسَّعِيرِ', '2d32ac6d1f4521f8ac292f59d954d8a337b368ba2a66f124a6877bd2f44a83f1', 'إِنَّ ٱلشَّيْطَٰنَ لَكُمْ عَدُوٌّ فَٱتَّخِذُوهُ عَدُوًّا إِنَّمَا يَدْعُوا۟ حِزْبَهُۥ لِيَكُونُوا۟ مِنْ أَصْحَٰبِ ٱلسَّعِيرِ', '2d32ac6d1f4521f8ac292f59d954d8a337b368ba2a66f124a6877bd2f44a83f1', '2d32ac6d1f4521f8ac292f59d954d8a337b368ba2a66f124a6877bd2f44a83f1', NULL, 'ان الشيطن لكم عدو فاتخذوه عدوا انما يدعوا حزبه ليكونوا من اصحب السعير', 22, 44, 174, 1, 5, 435, false, NULL),
    (3667, 'tanzil-uthmani-v1.1', 35, 7, 'ٱلَّذِينَ كَفَرُوا۟ لَهُمْ عَذَابٌ شَدِيدٌ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', '64cd74264ec6583c2c8eac2bf968071fb080b2208a630328317e217485efd25d', 'ٱلَّذِينَ كَفَرُوا۟ لَهُمْ عَذَابٌ شَدِيدٌ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', '64cd74264ec6583c2c8eac2bf968071fb080b2208a630328317e217485efd25d', '64cd74264ec6583c2c8eac2bf968071fb080b2208a630328317e217485efd25d', NULL, 'الذين كفروا لهم عذاب شديد والذين ءامنوا وعملوا الصلحت لهم مغفره واجر كبير', 22, 44, 174, 1, 5, 435, false, NULL),
    (3668, 'tanzil-uthmani-v1.1', 35, 8, 'أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنًا فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَٰتٍ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَصْنَعُونَ', 'b7efbec35d32b8d1cae1a438f74c3fd528df7a1dd1a79297b47f0c1439bb0182', 'أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنًا فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَٰتٍ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَصْنَعُونَ', 'b7efbec35d32b8d1cae1a438f74c3fd528df7a1dd1a79297b47f0c1439bb0182', 'b7efbec35d32b8d1cae1a438f74c3fd528df7a1dd1a79297b47f0c1439bb0182', NULL, 'افمن زين له سوء عمله فرءاه حسنا فان الله يضل من يشاء ويهدي من يشاء فلا تذهب نفسك عليهم حسرت ان الله عليم بما يصنعون', 22, 44, 174, 1, 5, 435, false, NULL),
    (3669, 'tanzil-uthmani-v1.1', 35, 9, 'وَٱللَّهُ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًا فَسُقْنَٰهُ إِلَىٰ بَلَدٍ مَّيِّتٍ فَأَحْيَيْنَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا كَذَٰلِكَ ٱلنُّشُورُ', 'fd99998dbbc582acfb7f4458d84bec52fbea55b24a45b7f6b36fbf076045e02c', 'وَٱللَّهُ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًا فَسُقْنَٰهُ إِلَىٰ بَلَدٍ مَّيِّتٍ فَأَحْيَيْنَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا كَذَٰلِكَ ٱلنُّشُورُ', 'fd99998dbbc582acfb7f4458d84bec52fbea55b24a45b7f6b36fbf076045e02c', 'fd99998dbbc582acfb7f4458d84bec52fbea55b24a45b7f6b36fbf076045e02c', NULL, 'والله الذي ارسل الريح فتثير سحابا فسقنه الي بلد ميت فاحيينا به الارض بعد موتها كذلك النشور', 22, 44, 174, 1, 5, 435, false, NULL),
    (3670, 'tanzil-uthmani-v1.1', 35, 10, 'مَن كَانَ يُرِيدُ ٱلْعِزَّةَ فَلِلَّهِ ٱلْعِزَّةُ جَمِيعًا إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّٰلِحُ يَرْفَعُهُۥ وَٱلَّذِينَ يَمْكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمْ عَذَابٌ شَدِيدٌ وَمَكْرُ أُو۟لَٰٓئِكَ هُوَ يَبُورُ', '56d8966480b12a5011fc92065d9a9b9a84215dbc7d3dcd5daa1a4963cd7157ee', 'مَن كَانَ يُرِيدُ ٱلْعِزَّةَ فَلِلَّهِ ٱلْعِزَّةُ جَمِيعًا إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّٰلِحُ يَرْفَعُهُۥ وَٱلَّذِينَ يَمْكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمْ عَذَابٌ شَدِيدٌ وَمَكْرُ أُو۟لَٰٓئِكَ هُوَ يَبُورُ', '56d8966480b12a5011fc92065d9a9b9a84215dbc7d3dcd5daa1a4963cd7157ee', '56d8966480b12a5011fc92065d9a9b9a84215dbc7d3dcd5daa1a4963cd7157ee', NULL, 'من كان يريد العزه فلله العزه جميعا اليه يصعد الكلم الطيب والعمل الصلح يرفعه والذين يمكرون السيات لهم عذاب شديد ومكر اولئك هو يبور', 22, 44, 174, 1, 5, 435, false, NULL),
    (3671, 'tanzil-uthmani-v1.1', 35, 11, 'وَٱللَّهُ خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ جَعَلَكُمْ أَزْوَٰجًا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ وَمَا يُعَمَّرُ مِن مُّعَمَّرٍ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِى كِتَٰبٍ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '6366e6518d5bffc6616696d7638cfa1f886c3f72f96fb7a70f6619f1fd519471', 'وَٱللَّهُ خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ جَعَلَكُمْ أَزْوَٰجًا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ وَمَا يُعَمَّرُ مِن مُّعَمَّرٍ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِى كِتَٰبٍ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '6366e6518d5bffc6616696d7638cfa1f886c3f72f96fb7a70f6619f1fd519471', '6366e6518d5bffc6616696d7638cfa1f886c3f72f96fb7a70f6619f1fd519471', NULL, 'والله خلقكم من تراب ثم من نطفه ثم جعلكم ازوجا وما تحمل من انثي ولا تضع الا بعلمه وما يعمر من معمر ولا ينقص من عمره الا في كتب ان ذلك علي الله يسير', 22, 44, 174, 1, 5, 435, false, NULL),
    (3672, 'tanzil-uthmani-v1.1', 35, 12, 'وَمَا يَسْتَوِى ٱلْبَحْرَانِ هَٰذَا عَذْبٌ فُرَاتٌ سَآئِغٌ شَرَابُهُۥ وَهَٰذَا مِلْحٌ أُجَاجٌ وَمِن كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '3ffbd6fbb662b6eff99c626e260bc3ba4db918821a0155152b04b92b4bd373e4', 'وَمَا يَسْتَوِى ٱلْبَحْرَانِ هَٰذَا عَذْبٌ فُرَاتٌ سَآئِغٌ شَرَابُهُۥ وَهَٰذَا مِلْحٌ أُجَاجٌ وَمِن كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '3ffbd6fbb662b6eff99c626e260bc3ba4db918821a0155152b04b92b4bd373e4', '3ffbd6fbb662b6eff99c626e260bc3ba4db918821a0155152b04b92b4bd373e4', NULL, 'وما يستوي البحران هذا عذب فرات سائغ شرابه وهذا ملح اجاج ومن كل تاكلون لحما طريا وتستخرجون حليه تلبسونها وتري الفلك فيه مواخر لتبتغوا من فضله ولعلكم تشكرون', 22, 44, 174, 1, 5, 436, false, NULL),
    (3673, 'tanzil-uthmani-v1.1', 35, 13, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ مَا يَمْلِكُونَ مِن قِطْمِيرٍ', 'b35acab96c128f15fca3fae62ed2f611b3ff20ab9b142e25e344e0ef81d05a42', 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ مَا يَمْلِكُونَ مِن قِطْمِيرٍ', 'b35acab96c128f15fca3fae62ed2f611b3ff20ab9b142e25e344e0ef81d05a42', 'b35acab96c128f15fca3fae62ed2f611b3ff20ab9b142e25e344e0ef81d05a42', NULL, 'يولج اليل في النهار ويولج النهار في اليل وسخر الشمس والقمر كل يجري لاجل مسمي ذلكم الله ربكم له الملك والذين تدعون من دونه ما يملكون من قطمير', 22, 44, 174, 1, 5, 436, false, NULL),
    (3674, 'tanzil-uthmani-v1.1', 35, 14, 'إِن تَدْعُوهُمْ لَا يَسْمَعُوا۟ دُعَآءَكُمْ وَلَوْ سَمِعُوا۟ مَا ٱسْتَجَابُوا۟ لَكُمْ وَيَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ', 'f587792d3eedbdfd97c1eacdba012c4493ebd6de650cdc9e2b79896d062b421a', 'إِن تَدْعُوهُمْ لَا يَسْمَعُوا۟ دُعَآءَكُمْ وَلَوْ سَمِعُوا۟ مَا ٱسْتَجَابُوا۟ لَكُمْ وَيَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ', 'f587792d3eedbdfd97c1eacdba012c4493ebd6de650cdc9e2b79896d062b421a', 'f587792d3eedbdfd97c1eacdba012c4493ebd6de650cdc9e2b79896d062b421a', NULL, 'ان تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم ويوم القيمه يكفرون بشرككم ولا ينبئك مثل خبير', 22, 44, 174, 1, 5, 436, false, NULL),
    (3675, 'tanzil-uthmani-v1.1', 35, 15, 'يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '19ea01e118c40f633bfc7e15917ea0dd6069e6f46a635857af5befb63f6e08b6', 'يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '19ea01e118c40f633bfc7e15917ea0dd6069e6f46a635857af5befb63f6e08b6', '19ea01e118c40f633bfc7e15917ea0dd6069e6f46a635857af5befb63f6e08b6', NULL, 'يايها الناس انتم الفقراء الي الله والله هو الغني الحميد', 22, 44, 175, 1, 5, 436, false, NULL),
    (3676, 'tanzil-uthmani-v1.1', 35, 16, 'إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', 'd4dde68c1d3e228626fed763989be8f4e14e1bd878635a9e0fca35affa1c4245', 'إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ', 'd4dde68c1d3e228626fed763989be8f4e14e1bd878635a9e0fca35affa1c4245', 'd4dde68c1d3e228626fed763989be8f4e14e1bd878635a9e0fca35affa1c4245', NULL, 'ان يشا يذهبكم ويات بخلق جديد', 22, 44, 175, 1, 5, 436, false, NULL),
    (3677, 'tanzil-uthmani-v1.1', 35, 17, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', 'bf93483a6a94a234a5111dcf1daf8f32733873aaed3c085d15fbb3728c1ddc54', 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ', 'bf93483a6a94a234a5111dcf1daf8f32733873aaed3c085d15fbb3728c1ddc54', 'bf93483a6a94a234a5111dcf1daf8f32733873aaed3c085d15fbb3728c1ddc54', NULL, 'وما ذلك علي الله بعزيز', 22, 44, 175, 1, 5, 436, false, NULL),
    (3678, 'tanzil-uthmani-v1.1', 35, 18, 'وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌ وَلَوْ كَانَ ذَا قُرْبَىٰٓ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', '63fcc1843fbcc09c91bf10c9fd7fea48fef8ca84e500d482bd6dca686336ae01', 'وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌ وَلَوْ كَانَ ذَا قُرْبَىٰٓ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', '63fcc1843fbcc09c91bf10c9fd7fea48fef8ca84e500d482bd6dca686336ae01', '63fcc1843fbcc09c91bf10c9fd7fea48fef8ca84e500d482bd6dca686336ae01', NULL, 'ولا تزر وازره وزر اخري وان تدع مثقله الي حملها لا يحمل منه شيء ولو كان ذا قربي انما تنذر الذين يخشون ربهم بالغيب واقاموا الصلوه ومن تزكي فانما يتزكي لنفسه والي الله المصير', 22, 44, 175, 1, 5, 436, false, NULL),
    (3679, 'tanzil-uthmani-v1.1', 35, 19, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ', '6e11cffa489945da020a127dd2b52b75197f4776d439e9d783207dda74699d78', 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ', '6e11cffa489945da020a127dd2b52b75197f4776d439e9d783207dda74699d78', '6e11cffa489945da020a127dd2b52b75197f4776d439e9d783207dda74699d78', NULL, 'وما يستوي الاعمي والبصير', 22, 44, 175, 1, 5, 437, false, NULL),
    (3680, 'tanzil-uthmani-v1.1', 35, 20, 'وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ', 'ce4787b5fe46c749843b0c1b855f9481b93867656cbf474c90227449b854ea74', 'وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ', 'ce4787b5fe46c749843b0c1b855f9481b93867656cbf474c90227449b854ea74', 'ce4787b5fe46c749843b0c1b855f9481b93867656cbf474c90227449b854ea74', NULL, 'ولا الظلمت ولا النور', 22, 44, 175, 1, 5, 437, false, NULL),
    (3681, 'tanzil-uthmani-v1.1', 35, 21, 'وَلَا ٱلظِّلُّ وَلَا ٱلْحَرُورُ', '84ae52b09b8b307f7f610b3779755338baab5f98f3bd18ad731a9dcf4817dfdb', 'وَلَا ٱلظِّلُّ وَلَا ٱلْحَرُورُ', '84ae52b09b8b307f7f610b3779755338baab5f98f3bd18ad731a9dcf4817dfdb', '84ae52b09b8b307f7f610b3779755338baab5f98f3bd18ad731a9dcf4817dfdb', NULL, 'ولا الظل ولا الحرور', 22, 44, 175, 1, 5, 437, false, NULL),
    (3682, 'tanzil-uthmani-v1.1', 35, 22, 'وَمَا يَسْتَوِى ٱلْأَحْيَآءُ وَلَا ٱلْأَمْوَٰتُ إِنَّ ٱللَّهَ يُسْمِعُ مَن يَشَآءُ وَمَآ أَنتَ بِمُسْمِعٍ مَّن فِى ٱلْقُبُورِ', 'cee7f82bb7103e9bd8aea818ea7751c37d8ebb0eb9b2058d1faee808b74f58ac', 'وَمَا يَسْتَوِى ٱلْأَحْيَآءُ وَلَا ٱلْأَمْوَٰتُ إِنَّ ٱللَّهَ يُسْمِعُ مَن يَشَآءُ وَمَآ أَنتَ بِمُسْمِعٍ مَّن فِى ٱلْقُبُورِ', 'cee7f82bb7103e9bd8aea818ea7751c37d8ebb0eb9b2058d1faee808b74f58ac', 'cee7f82bb7103e9bd8aea818ea7751c37d8ebb0eb9b2058d1faee808b74f58ac', NULL, 'وما يستوي الاحياء ولا الاموت ان الله يسمع من يشاء وما انت بمسمع من في القبور', 22, 44, 175, 1, 5, 437, false, NULL),
    (3683, 'tanzil-uthmani-v1.1', 35, 23, 'إِنْ أَنتَ إِلَّا نَذِيرٌ', 'f7876278ee8d4b9e4e75747d87a410aab72f69789b9d1b30223053637f43f931', 'إِنْ أَنتَ إِلَّا نَذِيرٌ', 'f7876278ee8d4b9e4e75747d87a410aab72f69789b9d1b30223053637f43f931', 'f7876278ee8d4b9e4e75747d87a410aab72f69789b9d1b30223053637f43f931', NULL, 'ان انت الا نذير', 22, 44, 175, 1, 5, 437, false, NULL),
    (3684, 'tanzil-uthmani-v1.1', 35, 24, 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَإِن مِّنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ', '618d1b1f19231f1959e99178e2113011b23294cec9d4f530321ed3f406d20ed2', 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَإِن مِّنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ', '618d1b1f19231f1959e99178e2113011b23294cec9d4f530321ed3f406d20ed2', '618d1b1f19231f1959e99178e2113011b23294cec9d4f530321ed3f406d20ed2', NULL, 'انا ارسلنك بالحق بشيرا ونذيرا وان من امه الا خلا فيها نذير', 22, 44, 175, 1, 5, 437, false, NULL),
    (3685, 'tanzil-uthmani-v1.1', 35, 25, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلْكِتَٰبِ ٱلْمُنِيرِ', 'e23f0a846420ddd42b581bb63bccd74db2acdd3ac4b2ef6dbd40f0e4942eaf4e', 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلْكِتَٰبِ ٱلْمُنِيرِ', 'e23f0a846420ddd42b581bb63bccd74db2acdd3ac4b2ef6dbd40f0e4942eaf4e', 'e23f0a846420ddd42b581bb63bccd74db2acdd3ac4b2ef6dbd40f0e4942eaf4e', NULL, 'وان يكذبوك فقد كذب الذين من قبلهم جاءتهم رسلهم بالبينت وبالزبر وبالكتب المنير', 22, 44, 175, 1, 5, 437, false, NULL),
    (3686, 'tanzil-uthmani-v1.1', 35, 26, 'ثُمَّ أَخَذْتُ ٱلَّذِينَ كَفَرُوا۟ فَكَيْفَ كَانَ نَكِيرِ', 'a6063c7050abb8f78a79cc74f061b7983c3206750bbd1b021d7e413007ec6359', 'ثُمَّ أَخَذْتُ ٱلَّذِينَ كَفَرُوا۟ فَكَيْفَ كَانَ نَكِيرِ', 'a6063c7050abb8f78a79cc74f061b7983c3206750bbd1b021d7e413007ec6359', 'a6063c7050abb8f78a79cc74f061b7983c3206750bbd1b021d7e413007ec6359', NULL, 'ثم اخذت الذين كفروا فكيف كان نكير', 22, 44, 175, 1, 5, 437, false, NULL),
    (3687, 'tanzil-uthmani-v1.1', 35, 27, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ ٱلْجِبَالِ جُدَدٌۢ بِيضٌ وَحُمْرٌ مُّخْتَلِفٌ أَلْوَٰنُهَا وَغَرَابِيبُ سُودٌ', '879935e7837a4fdf1b713d334ed22c974e9594f656e2cf4ce98af5b98f4f3023', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ ٱلْجِبَالِ جُدَدٌۢ بِيضٌ وَحُمْرٌ مُّخْتَلِفٌ أَلْوَٰنُهَا وَغَرَابِيبُ سُودٌ', '879935e7837a4fdf1b713d334ed22c974e9594f656e2cf4ce98af5b98f4f3023', '879935e7837a4fdf1b713d334ed22c974e9594f656e2cf4ce98af5b98f4f3023', NULL, 'الم تر ان الله انزل من السماء ماء فاخرجنا به ثمرت مختلفا الونها ومن الجبال جدد بيض وحمر مختلف الونها وغرابيب سود', 22, 44, 175, 1, 5, 437, false, NULL),
    (3688, 'tanzil-uthmani-v1.1', 35, 28, 'وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلْأَنْعَٰمِ مُخْتَلِفٌ أَلْوَٰنُهُۥ كَذَٰلِكَ إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا۟ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ', 'bf23072adbfcb748f503a9cd6f069a32db121efc7f49511733edf56e3064134c', 'وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلْأَنْعَٰمِ مُخْتَلِفٌ أَلْوَٰنُهُۥ كَذَٰلِكَ إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا۟ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ', 'bf23072adbfcb748f503a9cd6f069a32db121efc7f49511733edf56e3064134c', 'bf23072adbfcb748f503a9cd6f069a32db121efc7f49511733edf56e3064134c', NULL, 'ومن الناس والدواب والانعم مختلف الونه كذلك انما يخشي الله من عباده العلمؤا ان الله عزيز غفور', 22, 44, 175, 1, 5, 437, false, NULL),
    (3689, 'tanzil-uthmani-v1.1', 35, 29, 'إِنَّ ٱلَّذِينَ يَتْلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً يَرْجُونَ تِجَٰرَةً لَّن تَبُورَ', '1951ec5d2b88871273deeec97228cdc2a01a4b7cc1388ec8fecf2dce525028c4', 'إِنَّ ٱلَّذِينَ يَتْلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً يَرْجُونَ تِجَٰرَةً لَّن تَبُورَ', '1951ec5d2b88871273deeec97228cdc2a01a4b7cc1388ec8fecf2dce525028c4', '1951ec5d2b88871273deeec97228cdc2a01a4b7cc1388ec8fecf2dce525028c4', NULL, 'ان الذين يتلون كتب الله واقاموا الصلوه وانفقوا مما رزقنهم سرا وعلانيه يرجون تجره لن تبور', 22, 44, 175, 1, 5, 437, false, NULL),
    (3690, 'tanzil-uthmani-v1.1', 35, 30, 'لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ إِنَّهُۥ غَفُورٌ شَكُورٌ', '3d802d645adb0d478c33b4a2541baadb92af65f5c4b2067464429dd76f8d7fa2', 'لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ إِنَّهُۥ غَفُورٌ شَكُورٌ', '3d802d645adb0d478c33b4a2541baadb92af65f5c4b2067464429dd76f8d7fa2', '3d802d645adb0d478c33b4a2541baadb92af65f5c4b2067464429dd76f8d7fa2', NULL, 'ليوفيهم اجورهم ويزيدهم من فضله انه غفور شكور', 22, 44, 175, 1, 5, 437, false, NULL),
    (3691, 'tanzil-uthmani-v1.1', 35, 31, 'وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ مِنَ ٱلْكِتَٰبِ هُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرٌۢ بَصِيرٌ', '7412e94a4beefb5f83e2c86b7b1eff2287c8935b9c6ae7d6e3faa6dfc30c1981', 'وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ مِنَ ٱلْكِتَٰبِ هُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرٌۢ بَصِيرٌ', '7412e94a4beefb5f83e2c86b7b1eff2287c8935b9c6ae7d6e3faa6dfc30c1981', '7412e94a4beefb5f83e2c86b7b1eff2287c8935b9c6ae7d6e3faa6dfc30c1981', NULL, 'والذي اوحينا اليك من الكتب هو الحق مصدقا لما بين يديه ان الله بعباده لخبير بصير', 22, 44, 175, 1, 5, 438, false, NULL),
    (3692, 'tanzil-uthmani-v1.1', 35, 32, 'ثُمَّ أَوْرَثْنَا ٱلْكِتَٰبَ ٱلَّذِينَ ٱصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِّنَفْسِهِۦ وَمِنْهُم مُّقْتَصِدٌ وَمِنْهُمْ سَابِقٌۢ بِٱلْخَيْرَٰتِ بِإِذْنِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', '082d3bd58e96625482834317e540addadb6b7f10e132a058983151f2f4610a8d', 'ثُمَّ أَوْرَثْنَا ٱلْكِتَٰبَ ٱلَّذِينَ ٱصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِّنَفْسِهِۦ وَمِنْهُم مُّقْتَصِدٌ وَمِنْهُمْ سَابِقٌۢ بِٱلْخَيْرَٰتِ بِإِذْنِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', '082d3bd58e96625482834317e540addadb6b7f10e132a058983151f2f4610a8d', '082d3bd58e96625482834317e540addadb6b7f10e132a058983151f2f4610a8d', NULL, 'ثم اورثنا الكتب الذين اصطفينا من عبادنا فمنهم ظالم لنفسه ومنهم مقتصد ومنهم سابق بالخيرت باذن الله ذلك هو الفضل الكبير', 22, 44, 175, 1, 5, 438, false, NULL),
    (3693, 'tanzil-uthmani-v1.1', 35, 33, 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', 'afa0f0a76bab93decbe1b43ee3e910fdb144458a79e1fafc8ac2212a9f60285e', 'جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ', 'afa0f0a76bab93decbe1b43ee3e910fdb144458a79e1fafc8ac2212a9f60285e', 'afa0f0a76bab93decbe1b43ee3e910fdb144458a79e1fafc8ac2212a9f60285e', NULL, 'جنت عدن يدخلونها يحلون فيها من اساور من ذهب ولؤلؤا ولباسهم فيها حرير', 22, 44, 175, 1, 5, 438, false, NULL),
    (3694, 'tanzil-uthmani-v1.1', 35, 34, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَذْهَبَ عَنَّا ٱلْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ', '762cb511c04287ca3a2252ff3e157b175dd85b33decf82e605c5f74add65d264', 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَذْهَبَ عَنَّا ٱلْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ', '762cb511c04287ca3a2252ff3e157b175dd85b33decf82e605c5f74add65d264', '762cb511c04287ca3a2252ff3e157b175dd85b33decf82e605c5f74add65d264', NULL, 'وقالوا الحمد لله الذي اذهب عنا الحزن ان ربنا لغفور شكور', 22, 44, 175, 1, 5, 438, false, NULL),
    (3695, 'tanzil-uthmani-v1.1', 35, 35, 'ٱلَّذِىٓ أَحَلَّنَا دَارَ ٱلْمُقَامَةِ مِن فَضْلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ', '6a01b7c64411cf40e1a602f68eef99ebc2946cf9e7fcb243b603fa67d8abc8a4', 'ٱلَّذِىٓ أَحَلَّنَا دَارَ ٱلْمُقَامَةِ مِن فَضْلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ', '6a01b7c64411cf40e1a602f68eef99ebc2946cf9e7fcb243b603fa67d8abc8a4', '6a01b7c64411cf40e1a602f68eef99ebc2946cf9e7fcb243b603fa67d8abc8a4', NULL, 'الذي احلنا دار المقامه من فضله لا يمسنا فيها نصب ولا يمسنا فيها لغوب', 22, 44, 175, 1, 5, 438, false, NULL),
    (3696, 'tanzil-uthmani-v1.1', 35, 36, 'وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَىٰ عَلَيْهِمْ فَيَمُوتُوا۟ وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا كَذَٰلِكَ نَجْزِى كُلَّ كَفُورٍ', '8d5a93dc1ad5ece495522af4a95212fe9708a678dc6259f83c0d15517b672c31', 'وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَىٰ عَلَيْهِمْ فَيَمُوتُوا۟ وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا كَذَٰلِكَ نَجْزِى كُلَّ كَفُورٍ', '8d5a93dc1ad5ece495522af4a95212fe9708a678dc6259f83c0d15517b672c31', '8d5a93dc1ad5ece495522af4a95212fe9708a678dc6259f83c0d15517b672c31', NULL, 'والذين كفروا لهم نار جهنم لا يقضي عليهم فيموتوا ولا يخفف عنهم من عذابها كذلك نجزي كل كفور', 22, 44, 175, 1, 5, 438, false, NULL),
    (3697, 'tanzil-uthmani-v1.1', 35, 37, 'وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَٰلِحًا غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُ فَذُوقُوا۟ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', '0da1d64f03ce054e3de05625f1e065dbb162d1414815dc3c9f04bb8833cf89e3', 'وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَٰلِحًا غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُ فَذُوقُوا۟ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ', '0da1d64f03ce054e3de05625f1e065dbb162d1414815dc3c9f04bb8833cf89e3', '0da1d64f03ce054e3de05625f1e065dbb162d1414815dc3c9f04bb8833cf89e3', NULL, 'وهم يصطرخون فيها ربنا اخرجنا نعمل صلحا غير الذي كنا نعمل اولم نعمركم ما يتذكر فيه من تذكر وجاءكم النذير فذوقوا فما للظلمين من نصير', 22, 44, 175, 1, 5, 438, false, NULL),
    (3698, 'tanzil-uthmani-v1.1', 35, 38, 'إِنَّ ٱللَّهَ عَٰلِمُ غَيْبِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '645f2fb024e1bb73248a0df6d1cb3abeefebd95a3611208708c650d421255cb7', 'إِنَّ ٱللَّهَ عَٰلِمُ غَيْبِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '645f2fb024e1bb73248a0df6d1cb3abeefebd95a3611208708c650d421255cb7', '645f2fb024e1bb73248a0df6d1cb3abeefebd95a3611208708c650d421255cb7', NULL, 'ان الله علم غيب السموت والارض انه عليم بذات الصدور', 22, 44, 175, 1, 5, 438, false, NULL),
    (3699, 'tanzil-uthmani-v1.1', 35, 39, 'هُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمْ إِلَّا مَقْتًا وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا', '120064d3c83709bfb37d3e7c82dd3dc187663579f1a2e44d98a86a18a25fefe7', 'هُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمْ إِلَّا مَقْتًا وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا', '120064d3c83709bfb37d3e7c82dd3dc187663579f1a2e44d98a86a18a25fefe7', '120064d3c83709bfb37d3e7c82dd3dc187663579f1a2e44d98a86a18a25fefe7', NULL, 'هو الذي جعلكم خلئف في الارض فمن كفر فعليه كفره ولا يزيد الكفرين كفرهم عند ربهم الا مقتا ولا يزيد الكفرين كفرهم الا خسارا', 22, 44, 175, 1, 5, 439, false, NULL),
    (3700, 'tanzil-uthmani-v1.1', 35, 40, 'قُلْ أَرَءَيْتُمْ شُرَكَآءَكُمُ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَٰوَٰتِ أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا فَهُمْ عَلَىٰ بَيِّنَتٍ مِّنْهُ بَلْ إِن يَعِدُ ٱلظَّٰلِمُونَ بَعْضُهُم بَعْضًا إِلَّا غُرُورًا', '108c854e718483ba698978a2f483f5b628276e765de4bd8896af316dfeac7be7', 'قُلْ أَرَءَيْتُمْ شُرَكَآءَكُمُ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَٰوَٰتِ أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا فَهُمْ عَلَىٰ بَيِّنَتٍ مِّنْهُ بَلْ إِن يَعِدُ ٱلظَّٰلِمُونَ بَعْضُهُم بَعْضًا إِلَّا غُرُورًا', '108c854e718483ba698978a2f483f5b628276e765de4bd8896af316dfeac7be7', '108c854e718483ba698978a2f483f5b628276e765de4bd8896af316dfeac7be7', NULL, 'قل ارءيتم شركاءكم الذين تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السموت ام ءاتينهم كتبا فهم علي بينت منه بل ان يعد الظلمون بعضهم بعضا الا غرورا', 22, 44, 175, 1, 5, 439, false, NULL),
    (3701, 'tanzil-uthmani-v1.1', 35, 41, 'إِنَّ ٱللَّهَ يُمْسِكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ أَن تَزُولَا وَلَئِن زَالَتَآ إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّنۢ بَعْدِهِۦٓ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', '48c957d2df9cd8378a32a15c23c86cf2d9b06f5583187f7f118215a72cdce646', 'إِنَّ ٱللَّهَ يُمْسِكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ أَن تَزُولَا وَلَئِن زَالَتَآ إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّنۢ بَعْدِهِۦٓ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا', '48c957d2df9cd8378a32a15c23c86cf2d9b06f5583187f7f118215a72cdce646', '48c957d2df9cd8378a32a15c23c86cf2d9b06f5583187f7f118215a72cdce646', NULL, 'ان الله يمسك السموت والارض ان تزولا ولئن زالتا ان امسكهما من احد من بعده انه كان حليما غفورا', 22, 44, 176, 1, 5, 439, false, NULL),
    (3702, 'tanzil-uthmani-v1.1', 35, 42, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى ٱلْأُمَمِ فَلَمَّا جَآءَهُمْ نَذِيرٌ مَّا زَادَهُمْ إِلَّا نُفُورًا', 'e682a4ccd23df2b9a568cfae9088decbac170ce55ec8334d812be981df17e959', 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى ٱلْأُمَمِ فَلَمَّا جَآءَهُمْ نَذِيرٌ مَّا زَادَهُمْ إِلَّا نُفُورًا', 'e682a4ccd23df2b9a568cfae9088decbac170ce55ec8334d812be981df17e959', 'e682a4ccd23df2b9a568cfae9088decbac170ce55ec8334d812be981df17e959', NULL, 'واقسموا بالله جهد ايمنهم لئن جاءهم نذير ليكونن اهدي من احدي الامم فلما جاءهم نذير ما زادهم الا نفورا', 22, 44, 176, 1, 5, 439, false, NULL),
    (3703, 'tanzil-uthmani-v1.1', 35, 43, 'ٱسْتِكْبَارًا فِى ٱلْأَرْضِ وَمَكْرَ ٱلسَّيِّئِ وَلَا يَحِيقُ ٱلْمَكْرُ ٱلسَّيِّئُ إِلَّا بِأَهْلِهِۦ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ ٱلْأَوَّلِينَ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبْدِيلًا وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحْوِيلًا', '12e2a2cd03cbccfb3b2ae0a76d88da3f834e95e7a51093e25dfb55439040f5a0', 'ٱسْتِكْبَارًا فِى ٱلْأَرْضِ وَمَكْرَ ٱلسَّيِّئِ وَلَا يَحِيقُ ٱلْمَكْرُ ٱلسَّيِّئُ إِلَّا بِأَهْلِهِۦ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ ٱلْأَوَّلِينَ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبْدِيلًا وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحْوِيلًا', '12e2a2cd03cbccfb3b2ae0a76d88da3f834e95e7a51093e25dfb55439040f5a0', '12e2a2cd03cbccfb3b2ae0a76d88da3f834e95e7a51093e25dfb55439040f5a0', NULL, 'استكبارا في الارض ومكر السيئ ولا يحيق المكر السيئ الا باهله فهل ينظرون الا سنت الاولين فلن تجد لسنت الله تبديلا ولن تجد لسنت الله تحويلا', 22, 44, 176, 1, 5, 439, false, NULL),
    (3704, 'tanzil-uthmani-v1.1', 35, 44, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَكَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَمَا كَانَ ٱللَّهُ لِيُعْجِزَهُۥ مِن شَىْءٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ إِنَّهُۥ كَانَ عَلِيمًا قَدِيرًا', '0560b76f4594913a785885d425968eff9435963f3fb55a4c7cb0e12d6165287b', 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَكَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَمَا كَانَ ٱللَّهُ لِيُعْجِزَهُۥ مِن شَىْءٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ إِنَّهُۥ كَانَ عَلِيمًا قَدِيرًا', '0560b76f4594913a785885d425968eff9435963f3fb55a4c7cb0e12d6165287b', '0560b76f4594913a785885d425968eff9435963f3fb55a4c7cb0e12d6165287b', NULL, 'اولم يسيروا في الارض فينظروا كيف كان عقبه الذين من قبلهم وكانوا اشد منهم قوه وما كان الله ليعجزه من شيء في السموت ولا في الارض انه كان عليما قديرا', 22, 44, 176, 1, 5, 439, false, NULL),
    (3705, 'tanzil-uthmani-v1.1', 35, 45, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَإِذَا جَآءَ أَجَلُهُمْ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرًۢا', '9538c89a29177dad6ae06d160b32762bc364fe0c78ceb08a32907adaeac599d2', 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَإِذَا جَآءَ أَجَلُهُمْ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرًۢا', '9538c89a29177dad6ae06d160b32762bc364fe0c78ceb08a32907adaeac599d2', '9538c89a29177dad6ae06d160b32762bc364fe0c78ceb08a32907adaeac599d2', NULL, 'ولو يؤاخذ الله الناس بما كسبوا ما ترك علي ظهرها من دابه ولكن يؤخرهم الي اجل مسمي فاذا جاء اجلهم فان الله كان بعباده بصيرا', 22, 44, 176, 1, 5, 440, false, NULL),
    (3706, 'tanzil-uthmani-v1.1', 36, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يسٓ', 'e49059e663b680e7e66a71ecf955b875a5c6898bbda82337bdceb13e3ff923e7', 'يسٓ', 'dbb15d0a4cccc65789aef67c88742f24ad70091dbef5507860907774ea36e6c3', 'dbb15d0a4cccc65789aef67c88742f24ad70091dbef5507860907774ea36e6c3', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يس', 22, 44, 176, 1, 5, 440, false, NULL),
    (3707, 'tanzil-uthmani-v1.1', 36, 2, 'وَٱلْقُرْءَانِ ٱلْحَكِيمِ', '70671f1e34648e5f404e1623deed0f3858c47504c52ac227f822a5caa8230303', 'وَٱلْقُرْءَانِ ٱلْحَكِيمِ', '70671f1e34648e5f404e1623deed0f3858c47504c52ac227f822a5caa8230303', '70671f1e34648e5f404e1623deed0f3858c47504c52ac227f822a5caa8230303', NULL, 'والقرءان الحكيم', 22, 44, 176, 1, 5, 440, false, NULL),
    (3708, 'tanzil-uthmani-v1.1', 36, 3, 'إِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', '084854ebf2e2c5f647fc177dbafd582485661f82ae397429a8c1621f5928a3ce', 'إِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', '084854ebf2e2c5f647fc177dbafd582485661f82ae397429a8c1621f5928a3ce', '084854ebf2e2c5f647fc177dbafd582485661f82ae397429a8c1621f5928a3ce', NULL, 'انك لمن المرسلين', 22, 44, 176, 1, 5, 440, false, NULL),
    (3709, 'tanzil-uthmani-v1.1', 36, 4, 'عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'c639ea508c230bad56b57ddcab9ef002e4865932130f7ad19f02d9658f459892', 'عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 'c639ea508c230bad56b57ddcab9ef002e4865932130f7ad19f02d9658f459892', 'c639ea508c230bad56b57ddcab9ef002e4865932130f7ad19f02d9658f459892', NULL, 'علي صرط مستقيم', 22, 44, 176, 1, 5, 440, false, NULL),
    (3710, 'tanzil-uthmani-v1.1', 36, 5, 'تَنزِيلَ ٱلْعَزِيزِ ٱلرَّحِيمِ', 'ac5b88d4aaa4b933a56fb5a548a2203fe6877e5e6f7822f6a2584d62ed59a293', 'تَنزِيلَ ٱلْعَزِيزِ ٱلرَّحِيمِ', 'ac5b88d4aaa4b933a56fb5a548a2203fe6877e5e6f7822f6a2584d62ed59a293', 'ac5b88d4aaa4b933a56fb5a548a2203fe6877e5e6f7822f6a2584d62ed59a293', NULL, 'تنزيل العزيز الرحيم', 22, 44, 176, 1, 5, 440, false, NULL),
    (3711, 'tanzil-uthmani-v1.1', 36, 6, 'لِتُنذِرَ قَوْمًا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَٰفِلُونَ', 'ef0345ef5f2ca1c76e460d7bb148b4abf95f989d1f33adb321383d5c48f9b29e', 'لِتُنذِرَ قَوْمًا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَٰفِلُونَ', 'ef0345ef5f2ca1c76e460d7bb148b4abf95f989d1f33adb321383d5c48f9b29e', 'ef0345ef5f2ca1c76e460d7bb148b4abf95f989d1f33adb321383d5c48f9b29e', NULL, 'لتنذر قوما ما انذر ءاباؤهم فهم غفلون', 22, 44, 176, 1, 5, 440, false, NULL),
    (3712, 'tanzil-uthmani-v1.1', 36, 7, 'لَقَدْ حَقَّ ٱلْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ', 'd7ae806aeabc5c40f31bf2ea179d246bcd3953c7cf3175ea30f870d24ade00e6', 'لَقَدْ حَقَّ ٱلْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ', 'd7ae806aeabc5c40f31bf2ea179d246bcd3953c7cf3175ea30f870d24ade00e6', 'd7ae806aeabc5c40f31bf2ea179d246bcd3953c7cf3175ea30f870d24ade00e6', NULL, 'لقد حق القول علي اكثرهم فهم لا يؤمنون', 22, 44, 176, 1, 5, 440, false, NULL),
    (3713, 'tanzil-uthmani-v1.1', 36, 8, 'إِنَّا جَعَلْنَا فِىٓ أَعْنَٰقِهِمْ أَغْلَٰلًا فَهِىَ إِلَى ٱلْأَذْقَانِ فَهُم مُّقْمَحُونَ', '984e8a8f77de5e1578f762ad914294ed0680ad76e7d3bf10692b09b87499a6bb', 'إِنَّا جَعَلْنَا فِىٓ أَعْنَٰقِهِمْ أَغْلَٰلًا فَهِىَ إِلَى ٱلْأَذْقَانِ فَهُم مُّقْمَحُونَ', '984e8a8f77de5e1578f762ad914294ed0680ad76e7d3bf10692b09b87499a6bb', '984e8a8f77de5e1578f762ad914294ed0680ad76e7d3bf10692b09b87499a6bb', NULL, 'انا جعلنا في اعنقهم اغللا فهي الي الاذقان فهم مقمحون', 22, 44, 176, 1, 5, 440, false, NULL),
    (3714, 'tanzil-uthmani-v1.1', 36, 9, 'وَجَعَلْنَا مِنۢ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَٰهُمْ فَهُمْ لَا يُبْصِرُونَ', '3cc71a95e350731ba25bc2666bb4dc3100b106ece8dcae0a9bace3092877d757', 'وَجَعَلْنَا مِنۢ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَٰهُمْ فَهُمْ لَا يُبْصِرُونَ', '3cc71a95e350731ba25bc2666bb4dc3100b106ece8dcae0a9bace3092877d757', '3cc71a95e350731ba25bc2666bb4dc3100b106ece8dcae0a9bace3092877d757', NULL, 'وجعلنا من بين ايديهم سدا ومن خلفهم سدا فاغشينهم فهم لا يبصرون', 22, 44, 176, 1, 5, 440, false, NULL),
    (3715, 'tanzil-uthmani-v1.1', 36, 10, 'وَسَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', '77cc2d483b34cc26e679733041d5a15a47ee25fbffd3a478bd3b620d2a22df20', 'وَسَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', '77cc2d483b34cc26e679733041d5a15a47ee25fbffd3a478bd3b620d2a22df20', '77cc2d483b34cc26e679733041d5a15a47ee25fbffd3a478bd3b620d2a22df20', NULL, 'وسواء عليهم ءانذرتهم ام لم تنذرهم لا يؤمنون', 22, 44, 176, 1, 5, 440, false, NULL),
    (3716, 'tanzil-uthmani-v1.1', 36, 11, 'إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكْرَ وَخَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ', '34219eea4f798c936e849839bf47d692aaa584c56d818ae757a3d2c2c8f3b733', 'إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكْرَ وَخَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ', '34219eea4f798c936e849839bf47d692aaa584c56d818ae757a3d2c2c8f3b733', '34219eea4f798c936e849839bf47d692aaa584c56d818ae757a3d2c2c8f3b733', NULL, 'انما تنذر من اتبع الذكر وخشي الرحمن بالغيب فبشره بمغفره واجر كريم', 22, 44, 176, 1, 5, 440, false, NULL),
    (3717, 'tanzil-uthmani-v1.1', 36, 12, 'إِنَّا نَحْنُ نُحْىِ ٱلْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا۟ وَءَاثَٰرَهُمْ وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ فِىٓ إِمَامٍ مُّبِينٍ', '49b3e679c2b04be0b35969e815d770a693bba8e57e68c88345aefbc62879979e', 'إِنَّا نَحْنُ نُحْىِ ٱلْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا۟ وَءَاثَٰرَهُمْ وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ فِىٓ إِمَامٍ مُّبِينٍ', '49b3e679c2b04be0b35969e815d770a693bba8e57e68c88345aefbc62879979e', '49b3e679c2b04be0b35969e815d770a693bba8e57e68c88345aefbc62879979e', NULL, 'انا نحن نحي الموتي ونكتب ما قدموا وءاثرهم وكل شيء احصينه في امام مبين', 22, 44, 176, 1, 5, 440, false, NULL),
    (3718, 'tanzil-uthmani-v1.1', 36, 13, 'وَٱضْرِبْ لَهُم مَّثَلًا أَصْحَٰبَ ٱلْقَرْيَةِ إِذْ جَآءَهَا ٱلْمُرْسَلُونَ', '6c38b97c74c51bcf53c5504d7dc564db550a8e533c9971c3fd54f760df8b6f5a', 'وَٱضْرِبْ لَهُم مَّثَلًا أَصْحَٰبَ ٱلْقَرْيَةِ إِذْ جَآءَهَا ٱلْمُرْسَلُونَ', '6c38b97c74c51bcf53c5504d7dc564db550a8e533c9971c3fd54f760df8b6f5a', '6c38b97c74c51bcf53c5504d7dc564db550a8e533c9971c3fd54f760df8b6f5a', NULL, 'واضرب لهم مثلا اصحب القريه اذ جاءها المرسلون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3719, 'tanzil-uthmani-v1.1', 36, 14, 'إِذْ أَرْسَلْنَآ إِلَيْهِمُ ٱثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوٓا۟ إِنَّآ إِلَيْكُم مُّرْسَلُونَ', 'f133105485fef9b925a2498839dbe723ca75ac2cad0c0fadef27f3872b8d2bff', 'إِذْ أَرْسَلْنَآ إِلَيْهِمُ ٱثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوٓا۟ إِنَّآ إِلَيْكُم مُّرْسَلُونَ', 'f133105485fef9b925a2498839dbe723ca75ac2cad0c0fadef27f3872b8d2bff', 'f133105485fef9b925a2498839dbe723ca75ac2cad0c0fadef27f3872b8d2bff', NULL, 'اذ ارسلنا اليهم اثنين فكذبوهما فعززنا بثالث فقالوا انا اليكم مرسلون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3720, 'tanzil-uthmani-v1.1', 36, 15, 'قَالُوا۟ مَآ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا وَمَآ أَنزَلَ ٱلرَّحْمَٰنُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ', '842072c79058dfde22258aeb00f89ede38ec779debd0e6c32888c83864693757', 'قَالُوا۟ مَآ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا وَمَآ أَنزَلَ ٱلرَّحْمَٰنُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ', '842072c79058dfde22258aeb00f89ede38ec779debd0e6c32888c83864693757', '842072c79058dfde22258aeb00f89ede38ec779debd0e6c32888c83864693757', NULL, 'قالوا ما انتم الا بشر مثلنا وما انزل الرحمن من شيء ان انتم الا تكذبون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3721, 'tanzil-uthmani-v1.1', 36, 16, 'قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ', '76c602e1ddbeb522a6014c2c3a5226b3113717d3715c527024cbffba7551cd29', 'قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ', '76c602e1ddbeb522a6014c2c3a5226b3113717d3715c527024cbffba7551cd29', '76c602e1ddbeb522a6014c2c3a5226b3113717d3715c527024cbffba7551cd29', NULL, 'قالوا ربنا يعلم انا اليكم لمرسلون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3722, 'tanzil-uthmani-v1.1', 36, 17, 'وَمَا عَلَيْنَآ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', '4e068214255446697d3e10810eed5c9fa5865ecdbdc3c990a1844a22147a1c38', 'وَمَا عَلَيْنَآ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', '4e068214255446697d3e10810eed5c9fa5865ecdbdc3c990a1844a22147a1c38', '4e068214255446697d3e10810eed5c9fa5865ecdbdc3c990a1844a22147a1c38', NULL, 'وما علينا الا البلغ المبين', 22, 44, 176, 1, 5, 441, false, NULL),
    (3723, 'tanzil-uthmani-v1.1', 36, 18, 'قَالُوٓا۟ إِنَّا تَطَيَّرْنَا بِكُمْ لَئِن لَّمْ تَنتَهُوا۟ لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌ', '7416bad6edb5396db4d1001f84772e8b9dc5512624ff1344e8eff6af36357349', 'قَالُوٓا۟ إِنَّا تَطَيَّرْنَا بِكُمْ لَئِن لَّمْ تَنتَهُوا۟ لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌ', '7416bad6edb5396db4d1001f84772e8b9dc5512624ff1344e8eff6af36357349', '7416bad6edb5396db4d1001f84772e8b9dc5512624ff1344e8eff6af36357349', NULL, 'قالوا انا تطيرنا بكم لئن لم تنتهوا لنرجمنكم وليمسنكم منا عذاب اليم', 22, 44, 176, 1, 5, 441, false, NULL),
    (3724, 'tanzil-uthmani-v1.1', 36, 19, 'قَالُوا۟ طَٰٓئِرُكُم مَّعَكُمْ أَئِن ذُكِّرْتُم بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', '85cfbf7c48fe87b7ea63ccfba5f2d7f282566f719aee66ca5c3438a3c1f20946', 'قَالُوا۟ طَٰٓئِرُكُم مَّعَكُمْ أَئِن ذُكِّرْتُم بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ', '85cfbf7c48fe87b7ea63ccfba5f2d7f282566f719aee66ca5c3438a3c1f20946', '85cfbf7c48fe87b7ea63ccfba5f2d7f282566f719aee66ca5c3438a3c1f20946', NULL, 'قالوا طئركم معكم ائن ذكرتم بل انتم قوم مسرفون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3725, 'tanzil-uthmani-v1.1', 36, 20, 'وَجَآءَ مِنْ أَقْصَا ٱلْمَدِينَةِ رَجُلٌ يَسْعَىٰ قَالَ يَٰقَوْمِ ٱتَّبِعُوا۟ ٱلْمُرْسَلِينَ', '2e3a45796795abfe92a14b393d0e86559aa026bf93272fe3781dc7a0dbf23a0b', 'وَجَآءَ مِنْ أَقْصَا ٱلْمَدِينَةِ رَجُلٌ يَسْعَىٰ قَالَ يَٰقَوْمِ ٱتَّبِعُوا۟ ٱلْمُرْسَلِينَ', '2e3a45796795abfe92a14b393d0e86559aa026bf93272fe3781dc7a0dbf23a0b', '2e3a45796795abfe92a14b393d0e86559aa026bf93272fe3781dc7a0dbf23a0b', NULL, 'وجاء من اقصا المدينه رجل يسعي قال يقوم اتبعوا المرسلين', 22, 44, 176, 1, 5, 441, false, NULL),
    (3726, 'tanzil-uthmani-v1.1', 36, 21, 'ٱتَّبِعُوا۟ مَن لَّا يَسْـَٔلُكُمْ أَجْرًا وَهُم مُّهْتَدُونَ', 'ff9cd566ef88109c11d6f3476fc3af793c432a9a1b283ee783a07d23bc12c8be', 'ٱتَّبِعُوا۟ مَن لَّا يَسْـَٔلُكُمْ أَجْرًا وَهُم مُّهْتَدُونَ', 'ff9cd566ef88109c11d6f3476fc3af793c432a9a1b283ee783a07d23bc12c8be', 'ff9cd566ef88109c11d6f3476fc3af793c432a9a1b283ee783a07d23bc12c8be', NULL, 'اتبعوا من لا يسلكم اجرا وهم مهتدون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3727, 'tanzil-uthmani-v1.1', 36, 22, 'وَمَا لِىَ لَآ أَعْبُدُ ٱلَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَعُونَ', '3add2c125b8953a47f3932b2cb41fde45b10462ba3f128e6d8ec3039e03da81a', 'وَمَا لِىَ لَآ أَعْبُدُ ٱلَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَعُونَ', '3add2c125b8953a47f3932b2cb41fde45b10462ba3f128e6d8ec3039e03da81a', '3add2c125b8953a47f3932b2cb41fde45b10462ba3f128e6d8ec3039e03da81a', NULL, 'وما لي لا اعبد الذي فطرني واليه ترجعون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3728, 'tanzil-uthmani-v1.1', 36, 23, 'ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدْنِ ٱلرَّحْمَٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّى شَفَٰعَتُهُمْ شَيْـًٔا وَلَا يُنقِذُونِ', '5a80b97bff5e251f586a65b8dc087a19c147a3bcf10b488f5b8d12c90dcc238a', 'ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدْنِ ٱلرَّحْمَٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّى شَفَٰعَتُهُمْ شَيْـًٔا وَلَا يُنقِذُونِ', '5a80b97bff5e251f586a65b8dc087a19c147a3bcf10b488f5b8d12c90dcc238a', '5a80b97bff5e251f586a65b8dc087a19c147a3bcf10b488f5b8d12c90dcc238a', NULL, 'ءاتخذ من دونه ءالهه ان يردن الرحمن بضر لا تغن عني شفعتهم شيا ولا ينقذون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3729, 'tanzil-uthmani-v1.1', 36, 24, 'إِنِّىٓ إِذًا لَّفِى ضَلَٰلٍ مُّبِينٍ', '6c38f8979e47542e41a4992de1adacd006ab36225879d9e2442079dc48086818', 'إِنِّىٓ إِذًا لَّفِى ضَلَٰلٍ مُّبِينٍ', '6c38f8979e47542e41a4992de1adacd006ab36225879d9e2442079dc48086818', '6c38f8979e47542e41a4992de1adacd006ab36225879d9e2442079dc48086818', NULL, 'اني اذا لفي ضلل مبين', 22, 44, 176, 1, 5, 441, false, NULL),
    (3730, 'tanzil-uthmani-v1.1', 36, 25, 'إِنِّىٓ ءَامَنتُ بِرَبِّكُمْ فَٱسْمَعُونِ', '6b128962ade6beb7c92ab8c0e2a8c9ad6e5b5acdb43258c54898b565a096d249', 'إِنِّىٓ ءَامَنتُ بِرَبِّكُمْ فَٱسْمَعُونِ', '6b128962ade6beb7c92ab8c0e2a8c9ad6e5b5acdb43258c54898b565a096d249', '6b128962ade6beb7c92ab8c0e2a8c9ad6e5b5acdb43258c54898b565a096d249', NULL, 'اني ءامنت بربكم فاسمعون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3731, 'tanzil-uthmani-v1.1', 36, 26, 'قِيلَ ٱدْخُلِ ٱلْجَنَّةَ قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ', 'c73af2fc101038d6f925000fdb764078dfa310218ff0f9c04d8445329f825717', 'قِيلَ ٱدْخُلِ ٱلْجَنَّةَ قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ', 'c73af2fc101038d6f925000fdb764078dfa310218ff0f9c04d8445329f825717', 'c73af2fc101038d6f925000fdb764078dfa310218ff0f9c04d8445329f825717', NULL, 'قيل ادخل الجنه قال يليت قومي يعلمون', 22, 44, 176, 1, 5, 441, false, NULL),
    (3732, 'tanzil-uthmani-v1.1', 36, 27, 'بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ ٱلْمُكْرَمِينَ', '18a727f85eaac3020931b8f7fc47b43fe8b851622bcc92ecb23d6f2567d09e43', 'بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ ٱلْمُكْرَمِينَ', '18a727f85eaac3020931b8f7fc47b43fe8b851622bcc92ecb23d6f2567d09e43', '18a727f85eaac3020931b8f7fc47b43fe8b851622bcc92ecb23d6f2567d09e43', NULL, 'بما غفر لي ربي وجعلني من المكرمين', 22, 44, 176, 1, 5, 441, false, NULL),
    (3733, 'tanzil-uthmani-v1.1', 36, 28, 'وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن جُندٍ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ', '1fcc847e57c683e3623b99ef92956b13f8df7911fa6f505f10207301eecbfdb1', 'وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن جُندٍ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ', '1fcc847e57c683e3623b99ef92956b13f8df7911fa6f505f10207301eecbfdb1', '1fcc847e57c683e3623b99ef92956b13f8df7911fa6f505f10207301eecbfdb1', NULL, 'وما انزلنا علي قومه من بعده من جند من السماء وما كنا منزلين', 23, 45, 177, 1, 5, 442, false, NULL),
    (3734, 'tanzil-uthmani-v1.1', 36, 29, 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ خَٰمِدُونَ', 'c65a8802140af9f6298f51b51fd00a2dc612357c2c2f8f2405eeff757120a7b6', 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ خَٰمِدُونَ', 'c65a8802140af9f6298f51b51fd00a2dc612357c2c2f8f2405eeff757120a7b6', 'c65a8802140af9f6298f51b51fd00a2dc612357c2c2f8f2405eeff757120a7b6', NULL, 'ان كانت الا صيحه وحده فاذا هم خمدون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3735, 'tanzil-uthmani-v1.1', 36, 30, 'يَٰحَسْرَةً عَلَى ٱلْعِبَادِ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'e71a878c5a710c1864470b14a2925c648503409c18ee6c9e76b6978a59e0efa0', 'يَٰحَسْرَةً عَلَى ٱلْعِبَادِ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'e71a878c5a710c1864470b14a2925c648503409c18ee6c9e76b6978a59e0efa0', 'e71a878c5a710c1864470b14a2925c648503409c18ee6c9e76b6978a59e0efa0', NULL, 'يحسره علي العباد ما ياتيهم من رسول الا كانوا به يستهزءون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3736, 'tanzil-uthmani-v1.1', 36, 31, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ', '4879ecb41b4823525a6fa6a35e092620391d8e3b908fb3e3b8593fafad494c2b', 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ', '4879ecb41b4823525a6fa6a35e092620391d8e3b908fb3e3b8593fafad494c2b', '4879ecb41b4823525a6fa6a35e092620391d8e3b908fb3e3b8593fafad494c2b', NULL, 'الم يروا كم اهلكنا قبلهم من القرون انهم اليهم لا يرجعون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3737, 'tanzil-uthmani-v1.1', 36, 32, 'وَإِن كُلٌّ لَّمَّا جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', '0372f1add02cfad95b52a42b9bf683274655c70a6b51b29ea14c3d73ee55512d', 'وَإِن كُلٌّ لَّمَّا جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', '0372f1add02cfad95b52a42b9bf683274655c70a6b51b29ea14c3d73ee55512d', '0372f1add02cfad95b52a42b9bf683274655c70a6b51b29ea14c3d73ee55512d', NULL, 'وان كل لما جميع لدينا محضرون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3738, 'tanzil-uthmani-v1.1', 36, 33, 'وَءَايَةٌ لَّهُمُ ٱلْأَرْضُ ٱلْمَيْتَةُ أَحْيَيْنَٰهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ', 'e0cc9e33556a373334b95279e71c1eeef9d0e5d0aaf619c0e849de2a7e525ea8', 'وَءَايَةٌ لَّهُمُ ٱلْأَرْضُ ٱلْمَيْتَةُ أَحْيَيْنَٰهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ', 'e0cc9e33556a373334b95279e71c1eeef9d0e5d0aaf619c0e849de2a7e525ea8', 'e0cc9e33556a373334b95279e71c1eeef9d0e5d0aaf619c0e849de2a7e525ea8', NULL, 'وءايه لهم الارض الميته احيينها واخرجنا منها حبا فمنه ياكلون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3739, 'tanzil-uthmani-v1.1', 36, 34, 'وَجَعَلْنَا فِيهَا جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ وَفَجَّرْنَا فِيهَا مِنَ ٱلْعُيُونِ', 'c61ff82964f65e86cc1f76dd0ba24e396ca10fd49f3e8fcaa9ea5bf1cd966d00', 'وَجَعَلْنَا فِيهَا جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ وَفَجَّرْنَا فِيهَا مِنَ ٱلْعُيُونِ', 'c61ff82964f65e86cc1f76dd0ba24e396ca10fd49f3e8fcaa9ea5bf1cd966d00', 'c61ff82964f65e86cc1f76dd0ba24e396ca10fd49f3e8fcaa9ea5bf1cd966d00', NULL, 'وجعلنا فيها جنت من نخيل واعنب وفجرنا فيها من العيون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3740, 'tanzil-uthmani-v1.1', 36, 35, 'لِيَأْكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ أَفَلَا يَشْكُرُونَ', 'afef829e0e385ab44638d6a6af2d695777166532939ede667f201fe96202dedf', 'لِيَأْكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ أَفَلَا يَشْكُرُونَ', 'afef829e0e385ab44638d6a6af2d695777166532939ede667f201fe96202dedf', 'afef829e0e385ab44638d6a6af2d695777166532939ede667f201fe96202dedf', NULL, 'لياكلوا من ثمره وما عملته ايديهم افلا يشكرون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3741, 'tanzil-uthmani-v1.1', 36, 36, 'سُبْحَٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ', '4e09baceb3c99e9af0a5d9253372e976a654336ef4dae7544122c7948b395c2b', 'سُبْحَٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ', '4e09baceb3c99e9af0a5d9253372e976a654336ef4dae7544122c7948b395c2b', '4e09baceb3c99e9af0a5d9253372e976a654336ef4dae7544122c7948b395c2b', NULL, 'سبحن الذي خلق الازوج كلها مما تنبت الارض ومن انفسهم ومما لا يعلمون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3742, 'tanzil-uthmani-v1.1', 36, 37, 'وَءَايَةٌ لَّهُمُ ٱلَّيْلُ نَسْلَخُ مِنْهُ ٱلنَّهَارَ فَإِذَا هُم مُّظْلِمُونَ', 'f964a91b79c3025500ef195bea282ab7250ac86153cd54c8af61cc0126c29e88', 'وَءَايَةٌ لَّهُمُ ٱلَّيْلُ نَسْلَخُ مِنْهُ ٱلنَّهَارَ فَإِذَا هُم مُّظْلِمُونَ', 'f964a91b79c3025500ef195bea282ab7250ac86153cd54c8af61cc0126c29e88', 'f964a91b79c3025500ef195bea282ab7250ac86153cd54c8af61cc0126c29e88', NULL, 'وءايه لهم اليل نسلخ منه النهار فاذا هم مظلمون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3743, 'tanzil-uthmani-v1.1', 36, 38, 'وَٱلشَّمْسُ تَجْرِى لِمُسْتَقَرٍّ لَّهَا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'a565e91c36162c204d4a668ce59d15845110e41c0b0ac44f2b2968d83e50dfd6', 'وَٱلشَّمْسُ تَجْرِى لِمُسْتَقَرٍّ لَّهَا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'a565e91c36162c204d4a668ce59d15845110e41c0b0ac44f2b2968d83e50dfd6', 'a565e91c36162c204d4a668ce59d15845110e41c0b0ac44f2b2968d83e50dfd6', NULL, 'والشمس تجري لمستقر لها ذلك تقدير العزيز العليم', 23, 45, 177, 1, 5, 442, false, NULL),
    (3744, 'tanzil-uthmani-v1.1', 36, 39, 'وَٱلْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ', '0720a16f909da3300d07661e1a25197b2d0c4c3f53dc38bfd23fe5f7c12fc050', 'وَٱلْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ', '0720a16f909da3300d07661e1a25197b2d0c4c3f53dc38bfd23fe5f7c12fc050', '0720a16f909da3300d07661e1a25197b2d0c4c3f53dc38bfd23fe5f7c12fc050', NULL, 'والقمر قدرنه منازل حتي عاد كالعرجون القديم', 23, 45, 177, 1, 5, 442, false, NULL),
    (3745, 'tanzil-uthmani-v1.1', 36, 40, 'لَا ٱلشَّمْسُ يَنۢبَغِى لَهَآ أَن تُدْرِكَ ٱلْقَمَرَ وَلَا ٱلَّيْلُ سَابِقُ ٱلنَّهَارِ وَكُلٌّ فِى فَلَكٍ يَسْبَحُونَ', '86babb468fa396e07a3e40f30a49e0135909c3437b7c6c49ffdccd75887678c3', 'لَا ٱلشَّمْسُ يَنۢبَغِى لَهَآ أَن تُدْرِكَ ٱلْقَمَرَ وَلَا ٱلَّيْلُ سَابِقُ ٱلنَّهَارِ وَكُلٌّ فِى فَلَكٍ يَسْبَحُونَ', '86babb468fa396e07a3e40f30a49e0135909c3437b7c6c49ffdccd75887678c3', '86babb468fa396e07a3e40f30a49e0135909c3437b7c6c49ffdccd75887678c3', NULL, 'لا الشمس ينبغي لها ان تدرك القمر ولا اليل سابق النهار وكل في فلك يسبحون', 23, 45, 177, 1, 5, 442, false, NULL),
    (3746, 'tanzil-uthmani-v1.1', 36, 41, 'وَءَايَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', '093d443bb04e2042988b6d290142873d88c9f61507b983ab34b10c89be13c914', 'وَءَايَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ', '093d443bb04e2042988b6d290142873d88c9f61507b983ab34b10c89be13c914', '093d443bb04e2042988b6d290142873d88c9f61507b983ab34b10c89be13c914', NULL, 'وءايه لهم انا حملنا ذريتهم في الفلك المشحون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3747, 'tanzil-uthmani-v1.1', 36, 42, 'وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ', '572aaca58ea40e2bc0ab6384777a21984780f66ee27777bdf299e598630ab9b4', 'وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ', '572aaca58ea40e2bc0ab6384777a21984780f66ee27777bdf299e598630ab9b4', '572aaca58ea40e2bc0ab6384777a21984780f66ee27777bdf299e598630ab9b4', NULL, 'وخلقنا لهم من مثله ما يركبون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3748, 'tanzil-uthmani-v1.1', 36, 43, 'وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ', '091688e2ae38fdb0d81075d36342975f0f5da14d72892296271633dfa15ebb20', 'وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ', '091688e2ae38fdb0d81075d36342975f0f5da14d72892296271633dfa15ebb20', '091688e2ae38fdb0d81075d36342975f0f5da14d72892296271633dfa15ebb20', NULL, 'وان نشا نغرقهم فلا صريخ لهم ولا هم ينقذون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3749, 'tanzil-uthmani-v1.1', 36, 44, 'إِلَّا رَحْمَةً مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٍ', '887f3d8107a859fe1b4ea7f6c64c04b3ca55474b45b5b38b8561392fb03e687f', 'إِلَّا رَحْمَةً مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٍ', '887f3d8107a859fe1b4ea7f6c64c04b3ca55474b45b5b38b8561392fb03e687f', '887f3d8107a859fe1b4ea7f6c64c04b3ca55474b45b5b38b8561392fb03e687f', NULL, 'الا رحمه منا ومتعا الي حين', 23, 45, 177, 1, 5, 443, false, NULL),
    (3750, 'tanzil-uthmani-v1.1', 36, 45, 'وَإِذَا قِيلَ لَهُمُ ٱتَّقُوا۟ مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ', 'fbf6403087abdcfa65d0091467539c76776e5060af6c3b8934bcdca3837aca42', 'وَإِذَا قِيلَ لَهُمُ ٱتَّقُوا۟ مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ', 'fbf6403087abdcfa65d0091467539c76776e5060af6c3b8934bcdca3837aca42', 'fbf6403087abdcfa65d0091467539c76776e5060af6c3b8934bcdca3837aca42', NULL, 'واذا قيل لهم اتقوا ما بين ايديكم وما خلفكم لعلكم ترحمون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3751, 'tanzil-uthmani-v1.1', 36, 46, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', '819974d447708c55311f9c1e09ab62d776a4be56d1e9e6f7ac584b08996326a2', 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', '819974d447708c55311f9c1e09ab62d776a4be56d1e9e6f7ac584b08996326a2', '819974d447708c55311f9c1e09ab62d776a4be56d1e9e6f7ac584b08996326a2', NULL, 'وما تاتيهم من ءايه من ءايت ربهم الا كانوا عنها معرضين', 23, 45, 177, 1, 5, 443, false, NULL),
    (3752, 'tanzil-uthmani-v1.1', 36, 47, 'وَإِذَا قِيلَ لَهُمْ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَنُطْعِمُ مَن لَّوْ يَشَآءُ ٱللَّهُ أَطْعَمَهُۥٓ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ مُّبِينٍ', '237364c93c12244e5c8d2e40cd8dcbe2dd31e1bca7e11f096fdf6f17f1342ce5', 'وَإِذَا قِيلَ لَهُمْ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَنُطْعِمُ مَن لَّوْ يَشَآءُ ٱللَّهُ أَطْعَمَهُۥٓ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ مُّبِينٍ', '237364c93c12244e5c8d2e40cd8dcbe2dd31e1bca7e11f096fdf6f17f1342ce5', '237364c93c12244e5c8d2e40cd8dcbe2dd31e1bca7e11f096fdf6f17f1342ce5', NULL, 'واذا قيل لهم انفقوا مما رزقكم الله قال الذين كفروا للذين ءامنوا انطعم من لو يشاء الله اطعمه ان انتم الا في ضلل مبين', 23, 45, 177, 1, 5, 443, false, NULL),
    (3753, 'tanzil-uthmani-v1.1', 36, 48, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', NULL, 'ويقولون متي هذا الوعد ان كنتم صدقين', 23, 45, 177, 1, 5, 443, false, NULL),
    (3754, 'tanzil-uthmani-v1.1', 36, 49, 'مَا يَنظُرُونَ إِلَّا صَيْحَةً وَٰحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ', '2ada69513ec7930263023353bad0870b42af0328e3e96bcca684a49afb6ad639', 'مَا يَنظُرُونَ إِلَّا صَيْحَةً وَٰحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ', '2ada69513ec7930263023353bad0870b42af0328e3e96bcca684a49afb6ad639', '2ada69513ec7930263023353bad0870b42af0328e3e96bcca684a49afb6ad639', NULL, 'ما ينظرون الا صيحه وحده تاخذهم وهم يخصمون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3755, 'tanzil-uthmani-v1.1', 36, 50, 'فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ', '64c4195db6cf067ed1268aec6e5b0379c363e60679b9bd99d84f81d5d7774709', 'فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ', '64c4195db6cf067ed1268aec6e5b0379c363e60679b9bd99d84f81d5d7774709', '64c4195db6cf067ed1268aec6e5b0379c363e60679b9bd99d84f81d5d7774709', NULL, 'فلا يستطيعون توصيه ولا الي اهلهم يرجعون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3756, 'tanzil-uthmani-v1.1', 36, 51, 'وَنُفِخَ فِى ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ', 'e7606aca593aa8898ac28662ed08a5b824dd7db527b45dad5935566b3616e83f', 'وَنُفِخَ فِى ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ', 'e7606aca593aa8898ac28662ed08a5b824dd7db527b45dad5935566b3616e83f', 'e7606aca593aa8898ac28662ed08a5b824dd7db527b45dad5935566b3616e83f', NULL, 'ونفخ في الصور فاذا هم من الاجداث الي ربهم ينسلون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3757, 'tanzil-uthmani-v1.1', 36, 52, 'قَالُوا۟ يَٰوَيْلَنَا مَنۢ بَعَثَنَا مِن مَّرْقَدِنَا هَٰذَا مَا وَعَدَ ٱلرَّحْمَٰنُ وَصَدَقَ ٱلْمُرْسَلُونَ', '1c2669d14cf366af64ad95d551552a466783a7a0906f6972a2337f2280944cea', 'قَالُوا۟ يَٰوَيْلَنَا مَنۢ بَعَثَنَا مِن مَّرْقَدِنَا هَٰذَا مَا وَعَدَ ٱلرَّحْمَٰنُ وَصَدَقَ ٱلْمُرْسَلُونَ', '1c2669d14cf366af64ad95d551552a466783a7a0906f6972a2337f2280944cea', '1c2669d14cf366af64ad95d551552a466783a7a0906f6972a2337f2280944cea', NULL, 'قالوا يويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3758, 'tanzil-uthmani-v1.1', 36, 53, 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', '6d72b00b014388347792311b590a73c4ca02f04dba87c561d83c0501a1d2e15a', 'إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ', '6d72b00b014388347792311b590a73c4ca02f04dba87c561d83c0501a1d2e15a', '6d72b00b014388347792311b590a73c4ca02f04dba87c561d83c0501a1d2e15a', NULL, 'ان كانت الا صيحه وحده فاذا هم جميع لدينا محضرون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3759, 'tanzil-uthmani-v1.1', 36, 54, 'فَٱلْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', '512afb468e3d21f5732416644bec536dd3f0df54db32a16e7c2e2c7b29b4b6c7', 'فَٱلْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', '512afb468e3d21f5732416644bec536dd3f0df54db32a16e7c2e2c7b29b4b6c7', '512afb468e3d21f5732416644bec536dd3f0df54db32a16e7c2e2c7b29b4b6c7', NULL, 'فاليوم لا تظلم نفس شيا ولا تجزون الا ما كنتم تعملون', 23, 45, 177, 1, 5, 443, false, NULL),
    (3760, 'tanzil-uthmani-v1.1', 36, 55, 'إِنَّ أَصْحَٰبَ ٱلْجَنَّةِ ٱلْيَوْمَ فِى شُغُلٍ فَٰكِهُونَ', '13279301d38dc909983262714a8ffc40a390cda638135d9c4786599fc50710f5', 'إِنَّ أَصْحَٰبَ ٱلْجَنَّةِ ٱلْيَوْمَ فِى شُغُلٍ فَٰكِهُونَ', '13279301d38dc909983262714a8ffc40a390cda638135d9c4786599fc50710f5', '13279301d38dc909983262714a8ffc40a390cda638135d9c4786599fc50710f5', NULL, 'ان اصحب الجنه اليوم في شغل فكهون', 23, 45, 177, 1, 5, 444, false, NULL),
    (3761, 'tanzil-uthmani-v1.1', 36, 56, 'هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَٰلٍ عَلَى ٱلْأَرَآئِكِ مُتَّكِـُٔونَ', 'd03b4b6a36482cc131421c85fcdd91f21e4c55510b79d6cb09038d87f1ffb03a', 'هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَٰلٍ عَلَى ٱلْأَرَآئِكِ مُتَّكِـُٔونَ', 'd03b4b6a36482cc131421c85fcdd91f21e4c55510b79d6cb09038d87f1ffb03a', 'd03b4b6a36482cc131421c85fcdd91f21e4c55510b79d6cb09038d87f1ffb03a', NULL, 'هم وازوجهم في ظلل علي الارائك متكون', 23, 45, 177, 1, 5, 444, false, NULL),
    (3762, 'tanzil-uthmani-v1.1', 36, 57, 'لَهُمْ فِيهَا فَٰكِهَةٌ وَلَهُم مَّا يَدَّعُونَ', '2c896657565d427fe230278cd6148bc7d7559048a7919196d4c57270f0af41bf', 'لَهُمْ فِيهَا فَٰكِهَةٌ وَلَهُم مَّا يَدَّعُونَ', '2c896657565d427fe230278cd6148bc7d7559048a7919196d4c57270f0af41bf', '2c896657565d427fe230278cd6148bc7d7559048a7919196d4c57270f0af41bf', NULL, 'لهم فيها فكهه ولهم ما يدعون', 23, 45, 177, 1, 5, 444, false, NULL),
    (3763, 'tanzil-uthmani-v1.1', 36, 58, 'سَلَٰمٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ', '4ab3e91167d80d5e7f51e7f1a5b2b010903e8ed25600b16938ec95558df806e4', 'سَلَٰمٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ', '4ab3e91167d80d5e7f51e7f1a5b2b010903e8ed25600b16938ec95558df806e4', '4ab3e91167d80d5e7f51e7f1a5b2b010903e8ed25600b16938ec95558df806e4', NULL, 'سلم قولا من رب رحيم', 23, 45, 177, 1, 5, 444, false, NULL),
    (3764, 'tanzil-uthmani-v1.1', 36, 59, 'وَٱمْتَٰزُوا۟ ٱلْيَوْمَ أَيُّهَا ٱلْمُجْرِمُونَ', '5d67cb7d300bc8818d0844e01f1fc297f97daa75d335b6dbf937818e73e0751a', 'وَٱمْتَٰزُوا۟ ٱلْيَوْمَ أَيُّهَا ٱلْمُجْرِمُونَ', '5d67cb7d300bc8818d0844e01f1fc297f97daa75d335b6dbf937818e73e0751a', '5d67cb7d300bc8818d0844e01f1fc297f97daa75d335b6dbf937818e73e0751a', NULL, 'وامتزوا اليوم ايها المجرمون', 23, 45, 177, 1, 5, 444, false, NULL),
    (3765, 'tanzil-uthmani-v1.1', 36, 60, 'أَلَمْ أَعْهَدْ إِلَيْكُمْ يَٰبَنِىٓ ءَادَمَ أَن لَّا تَعْبُدُوا۟ ٱلشَّيْطَٰنَ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '452af6f0b7222a5695e483cb4f6e5a5326f3cbd22fa922cdbb584de6b7b22178', 'أَلَمْ أَعْهَدْ إِلَيْكُمْ يَٰبَنِىٓ ءَادَمَ أَن لَّا تَعْبُدُوا۟ ٱلشَّيْطَٰنَ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '452af6f0b7222a5695e483cb4f6e5a5326f3cbd22fa922cdbb584de6b7b22178', '452af6f0b7222a5695e483cb4f6e5a5326f3cbd22fa922cdbb584de6b7b22178', NULL, 'الم اعهد اليكم يبني ءادم ان لا تعبدوا الشيطن انه لكم عدو مبين', 23, 45, 178, 1, 5, 444, false, NULL),
    (3766, 'tanzil-uthmani-v1.1', 36, 61, 'وَأَنِ ٱعْبُدُونِى هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '41edd8344af889073c53b5733962437ef5913cebca193a3bd18f1b2325275f1d', 'وَأَنِ ٱعْبُدُونِى هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', '41edd8344af889073c53b5733962437ef5913cebca193a3bd18f1b2325275f1d', '41edd8344af889073c53b5733962437ef5913cebca193a3bd18f1b2325275f1d', NULL, 'وان اعبدوني هذا صرط مستقيم', 23, 45, 178, 1, 5, 444, false, NULL),
    (3767, 'tanzil-uthmani-v1.1', 36, 62, 'وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّا كَثِيرًا أَفَلَمْ تَكُونُوا۟ تَعْقِلُونَ', '80705f29526bfe601974471ffae57783d750dd02ceb97534b99c50c39606b0f5', 'وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّا كَثِيرًا أَفَلَمْ تَكُونُوا۟ تَعْقِلُونَ', '80705f29526bfe601974471ffae57783d750dd02ceb97534b99c50c39606b0f5', '80705f29526bfe601974471ffae57783d750dd02ceb97534b99c50c39606b0f5', NULL, 'ولقد اضل منكم جبلا كثيرا افلم تكونوا تعقلون', 23, 45, 178, 1, 5, 444, false, NULL),
    (3768, 'tanzil-uthmani-v1.1', 36, 63, 'هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى كُنتُمْ تُوعَدُونَ', 'cfebbb4dd017cf7d619b44b1c294c12fbbfd5382951e069c5870d43d9a27a906', 'هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى كُنتُمْ تُوعَدُونَ', 'cfebbb4dd017cf7d619b44b1c294c12fbbfd5382951e069c5870d43d9a27a906', 'cfebbb4dd017cf7d619b44b1c294c12fbbfd5382951e069c5870d43d9a27a906', NULL, 'هذه جهنم التي كنتم توعدون', 23, 45, 178, 1, 5, 444, false, NULL),
    (3769, 'tanzil-uthmani-v1.1', 36, 64, 'ٱصْلَوْهَا ٱلْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ', '1cc799d2003aaffe998147a3252c365671d5e1c9ce83191de7c4926bcdd4d28a', 'ٱصْلَوْهَا ٱلْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ', '1cc799d2003aaffe998147a3252c365671d5e1c9ce83191de7c4926bcdd4d28a', '1cc799d2003aaffe998147a3252c365671d5e1c9ce83191de7c4926bcdd4d28a', NULL, 'اصلوها اليوم بما كنتم تكفرون', 23, 45, 178, 1, 5, 444, false, NULL),
    (3770, 'tanzil-uthmani-v1.1', 36, 65, 'ٱلْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا۟ يَكْسِبُونَ', '46c18959ac27eeb7441be3905d6cb714ef3f8d43901bd1505be0a9c446de898d', 'ٱلْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا۟ يَكْسِبُونَ', '46c18959ac27eeb7441be3905d6cb714ef3f8d43901bd1505be0a9c446de898d', '46c18959ac27eeb7441be3905d6cb714ef3f8d43901bd1505be0a9c446de898d', NULL, 'اليوم نختم علي افوههم وتكلمنا ايديهم وتشهد ارجلهم بما كانوا يكسبون', 23, 45, 178, 1, 5, 444, false, NULL),
    (3771, 'tanzil-uthmani-v1.1', 36, 66, 'وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَٱسْتَبَقُوا۟ ٱلصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ', 'c247896cefe40a99d1a4589c6cc02d8ac6b8ef0dc51eef53a732035775b0f197', 'وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَٱسْتَبَقُوا۟ ٱلصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ', 'c247896cefe40a99d1a4589c6cc02d8ac6b8ef0dc51eef53a732035775b0f197', 'c247896cefe40a99d1a4589c6cc02d8ac6b8ef0dc51eef53a732035775b0f197', NULL, 'ولو نشاء لطمسنا علي اعينهم فاستبقوا الصرط فاني يبصرون', 23, 45, 178, 1, 5, 444, false, NULL),
    (3772, 'tanzil-uthmani-v1.1', 36, 67, 'وَلَوْ نَشَآءُ لَمَسَخْنَٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا ٱسْتَطَٰعُوا۟ مُضِيًّا وَلَا يَرْجِعُونَ', 'd1c7eec15ca03bb4ff9ac59797ea9967b30b27777e966361691c389e55b42c28', 'وَلَوْ نَشَآءُ لَمَسَخْنَٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا ٱسْتَطَٰعُوا۟ مُضِيًّا وَلَا يَرْجِعُونَ', 'd1c7eec15ca03bb4ff9ac59797ea9967b30b27777e966361691c389e55b42c28', 'd1c7eec15ca03bb4ff9ac59797ea9967b30b27777e966361691c389e55b42c28', NULL, 'ولو نشاء لمسخنهم علي مكانتهم فما استطعوا مضيا ولا يرجعون', 23, 45, 178, 1, 5, 444, false, NULL),
    (3773, 'tanzil-uthmani-v1.1', 36, 68, 'وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى ٱلْخَلْقِ أَفَلَا يَعْقِلُونَ', '3df2f537b20f91627a4e1c925a2f7a9409fd3f0f36acb08fca7d055f34d50925', 'وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى ٱلْخَلْقِ أَفَلَا يَعْقِلُونَ', '3df2f537b20f91627a4e1c925a2f7a9409fd3f0f36acb08fca7d055f34d50925', '3df2f537b20f91627a4e1c925a2f7a9409fd3f0f36acb08fca7d055f34d50925', NULL, 'ومن نعمره ننكسه في الخلق افلا يعقلون', 23, 45, 178, 1, 5, 444, false, NULL),
    (3774, 'tanzil-uthmani-v1.1', 36, 69, 'وَمَا عَلَّمْنَٰهُ ٱلشِّعْرَ وَمَا يَنۢبَغِى لَهُۥٓ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْءَانٌ مُّبِينٌ', 'fbe688d12d0bd92fdc2d737f2154babb042c9141085f41e034ed8dcaac706534', 'وَمَا عَلَّمْنَٰهُ ٱلشِّعْرَ وَمَا يَنۢبَغِى لَهُۥٓ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْءَانٌ مُّبِينٌ', 'fbe688d12d0bd92fdc2d737f2154babb042c9141085f41e034ed8dcaac706534', 'fbe688d12d0bd92fdc2d737f2154babb042c9141085f41e034ed8dcaac706534', NULL, 'وما علمنه الشعر وما ينبغي له ان هو الا ذكر وقرءان مبين', 23, 45, 178, 1, 5, 444, false, NULL),
    (3775, 'tanzil-uthmani-v1.1', 36, 70, 'لِّيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ ٱلْقَوْلُ عَلَى ٱلْكَٰفِرِينَ', 'f23b01af340b82764e958d3d4694e58e24d98f7a93f28b998380d941e5c79445', 'لِّيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ ٱلْقَوْلُ عَلَى ٱلْكَٰفِرِينَ', 'f23b01af340b82764e958d3d4694e58e24d98f7a93f28b998380d941e5c79445', 'f23b01af340b82764e958d3d4694e58e24d98f7a93f28b998380d941e5c79445', NULL, 'لينذر من كان حيا ويحق القول علي الكفرين', 23, 45, 178, 1, 5, 444, false, NULL),
    (3776, 'tanzil-uthmani-v1.1', 36, 71, 'أَوَلَمْ يَرَوْا۟ أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَآ أَنْعَٰمًا فَهُمْ لَهَا مَٰلِكُونَ', 'c44d8ac2f8b7396602567692ed8e484b41ae8fb57a2c91511ef69da90b348e71', 'أَوَلَمْ يَرَوْا۟ أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَآ أَنْعَٰمًا فَهُمْ لَهَا مَٰلِكُونَ', 'c44d8ac2f8b7396602567692ed8e484b41ae8fb57a2c91511ef69da90b348e71', 'c44d8ac2f8b7396602567692ed8e484b41ae8fb57a2c91511ef69da90b348e71', NULL, 'اولم يروا انا خلقنا لهم مما عملت ايدينا انعما فهم لها ملكون', 23, 45, 178, 1, 5, 445, false, NULL),
    (3777, 'tanzil-uthmani-v1.1', 36, 72, 'وَذَلَّلْنَٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ', '6b72bc85c9ed04abfba9819f0533e85781e45f4ba8b30b9913c06a9d8b11f727', 'وَذَلَّلْنَٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ', '6b72bc85c9ed04abfba9819f0533e85781e45f4ba8b30b9913c06a9d8b11f727', '6b72bc85c9ed04abfba9819f0533e85781e45f4ba8b30b9913c06a9d8b11f727', NULL, 'وذللنها لهم فمنها ركوبهم ومنها ياكلون', 23, 45, 178, 1, 5, 445, false, NULL),
    (3778, 'tanzil-uthmani-v1.1', 36, 73, 'وَلَهُمْ فِيهَا مَنَٰفِعُ وَمَشَارِبُ أَفَلَا يَشْكُرُونَ', 'b53a4168e288325ca3c83a3f617cf72cec155fdd0c13656629b9e46b9d284207', 'وَلَهُمْ فِيهَا مَنَٰفِعُ وَمَشَارِبُ أَفَلَا يَشْكُرُونَ', 'b53a4168e288325ca3c83a3f617cf72cec155fdd0c13656629b9e46b9d284207', 'b53a4168e288325ca3c83a3f617cf72cec155fdd0c13656629b9e46b9d284207', NULL, 'ولهم فيها منفع ومشارب افلا يشكرون', 23, 45, 178, 1, 5, 445, false, NULL),
    (3779, 'tanzil-uthmani-v1.1', 36, 74, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لَّعَلَّهُمْ يُنصَرُونَ', 'b77cbb77ce586b404d1977476163a68f1131d010459cab8638ff9a4d72f52e36', 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لَّعَلَّهُمْ يُنصَرُونَ', 'b77cbb77ce586b404d1977476163a68f1131d010459cab8638ff9a4d72f52e36', 'b77cbb77ce586b404d1977476163a68f1131d010459cab8638ff9a4d72f52e36', NULL, 'واتخذوا من دون الله ءالهه لعلهم ينصرون', 23, 45, 178, 1, 5, 445, false, NULL),
    (3780, 'tanzil-uthmani-v1.1', 36, 75, 'لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُّحْضَرُونَ', 'fea521ae3ff64f8c54a2f8dee32561fe61a964d05b9be5bf4667cd7e0cc05529', 'لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُّحْضَرُونَ', 'fea521ae3ff64f8c54a2f8dee32561fe61a964d05b9be5bf4667cd7e0cc05529', 'fea521ae3ff64f8c54a2f8dee32561fe61a964d05b9be5bf4667cd7e0cc05529', NULL, 'لا يستطيعون نصرهم وهم لهم جند محضرون', 23, 45, 178, 1, 5, 445, false, NULL),
    (3781, 'tanzil-uthmani-v1.1', 36, 76, 'فَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'bdc95bc70d0883ce05c1f9297bb5a2baf2a7cb486336856ebe2827df460e4020', 'فَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 'bdc95bc70d0883ce05c1f9297bb5a2baf2a7cb486336856ebe2827df460e4020', 'bdc95bc70d0883ce05c1f9297bb5a2baf2a7cb486336856ebe2827df460e4020', NULL, 'فلا يحزنك قولهم انا نعلم ما يسرون وما يعلنون', 23, 45, 178, 1, 5, 445, false, NULL),
    (3782, 'tanzil-uthmani-v1.1', 36, 77, 'أَوَلَمْ يَرَ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', 'e299a836ec89f9f2df4866e6a9a1a8fd3ccf7e8337c9a0154f38378476f14219', 'أَوَلَمْ يَرَ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ', 'e299a836ec89f9f2df4866e6a9a1a8fd3ccf7e8337c9a0154f38378476f14219', 'e299a836ec89f9f2df4866e6a9a1a8fd3ccf7e8337c9a0154f38378476f14219', NULL, 'اولم ير الانسن انا خلقنه من نطفه فاذا هو خصيم مبين', 23, 45, 178, 1, 5, 445, false, NULL),
    (3783, 'tanzil-uthmani-v1.1', 36, 78, 'وَضَرَبَ لَنَا مَثَلًا وَنَسِىَ خَلْقَهُۥ قَالَ مَن يُحْىِ ٱلْعِظَٰمَ وَهِىَ رَمِيمٌ', 'b3fce81d448305d2fdd35f6e635492f9a1d21bb3fd8bb446886a95a0a120f22e', 'وَضَرَبَ لَنَا مَثَلًا وَنَسِىَ خَلْقَهُۥ قَالَ مَن يُحْىِ ٱلْعِظَٰمَ وَهِىَ رَمِيمٌ', 'b3fce81d448305d2fdd35f6e635492f9a1d21bb3fd8bb446886a95a0a120f22e', 'b3fce81d448305d2fdd35f6e635492f9a1d21bb3fd8bb446886a95a0a120f22e', NULL, 'وضرب لنا مثلا ونسي خلقه قال من يحي العظم وهي رميم', 23, 45, 178, 1, 5, 445, false, NULL),
    (3784, 'tanzil-uthmani-v1.1', 36, 79, 'قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ', 'cbac5fa2d76afaadd0a8c2127e8819f6430c9b4eaed2bae14d0c853dbf8591ca', 'قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ', 'cbac5fa2d76afaadd0a8c2127e8819f6430c9b4eaed2bae14d0c853dbf8591ca', 'cbac5fa2d76afaadd0a8c2127e8819f6430c9b4eaed2bae14d0c853dbf8591ca', NULL, 'قل يحييها الذي انشاها اول مره وهو بكل خلق عليم', 23, 45, 178, 1, 5, 445, false, NULL),
    (3785, 'tanzil-uthmani-v1.1', 36, 80, 'ٱلَّذِى جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلْأَخْضَرِ نَارًا فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ', '7c28152936633773ee3b9d09d2a73f8ca823ad6433a76a86de5db8aa8a66d629', 'ٱلَّذِى جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلْأَخْضَرِ نَارًا فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ', '7c28152936633773ee3b9d09d2a73f8ca823ad6433a76a86de5db8aa8a66d629', '7c28152936633773ee3b9d09d2a73f8ca823ad6433a76a86de5db8aa8a66d629', NULL, 'الذي جعل لكم من الشجر الاخضر نارا فاذا انتم منه توقدون', 23, 45, 178, 1, 5, 445, false, NULL),
    (3786, 'tanzil-uthmani-v1.1', 36, 81, 'أَوَلَيْسَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُم بَلَىٰ وَهُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ', 'b8d51c8a3ecfa6bd4518be5e0ee3c7996a0c537f0924e403501558f6078258a5', 'أَوَلَيْسَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُم بَلَىٰ وَهُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ', 'b8d51c8a3ecfa6bd4518be5e0ee3c7996a0c537f0924e403501558f6078258a5', 'b8d51c8a3ecfa6bd4518be5e0ee3c7996a0c537f0924e403501558f6078258a5', NULL, 'اوليس الذي خلق السموت والارض بقدر علي ان يخلق مثلهم بلي وهو الخلق العليم', 23, 45, 178, 1, 5, 445, false, NULL),
    (3787, 'tanzil-uthmani-v1.1', 36, 82, 'إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ', '1633fca91f1e9a0b38ee264ac192614ff202c4b26b646b7b9d1453ccc5f6c09d', 'إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ', '1633fca91f1e9a0b38ee264ac192614ff202c4b26b646b7b9d1453ccc5f6c09d', '1633fca91f1e9a0b38ee264ac192614ff202c4b26b646b7b9d1453ccc5f6c09d', NULL, 'انما امره اذا اراد شيا ان يقول له كن فيكون', 23, 45, 178, 1, 5, 445, false, NULL),
    (3788, 'tanzil-uthmani-v1.1', 36, 83, 'فَسُبْحَٰنَ ٱلَّذِى بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَإِلَيْهِ تُرْجَعُونَ', '8b752098a3a089d18d27fe9fed2f664986a824a6b53b404edc6d8adce4b99606', 'فَسُبْحَٰنَ ٱلَّذِى بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَإِلَيْهِ تُرْجَعُونَ', '8b752098a3a089d18d27fe9fed2f664986a824a6b53b404edc6d8adce4b99606', '8b752098a3a089d18d27fe9fed2f664986a824a6b53b404edc6d8adce4b99606', NULL, 'فسبحن الذي بيده ملكوت كل شيء واليه ترجعون', 23, 45, 178, 1, 5, 445, false, NULL),
    (3789, 'tanzil-uthmani-v1.1', 37, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلصَّٰٓفَّٰتِ صَفًّا', 'be0362293ce4caac0253c5bec688c4ffa37ebfc7a14dc3b8b121b589a3078e96', 'وَٱلصَّٰٓفَّٰتِ صَفًّا', 'b50eb6230934de966ccf5cd2f813f6b27407623f3c7bc1f4e62516eb6bc48975', 'b50eb6230934de966ccf5cd2f813f6b27407623f3c7bc1f4e62516eb6bc48975', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'والصفت صفا', 23, 45, 178, 1, 6, 446, false, NULL),
