    (3791, 'tanzil-uthmani-v1.1', 37, 3, 'فَٱلتَّٰلِيَٰتِ ذِكْرًا', '904517c6b075170523bfd92de9ee04be050e1abc8122d2a2f8605552ec538e98', 'فَٱلتَّٰلِيَٰتِ ذِكْرًا', '904517c6b075170523bfd92de9ee04be050e1abc8122d2a2f8605552ec538e98', '904517c6b075170523bfd92de9ee04be050e1abc8122d2a2f8605552ec538e98', NULL, 'فالتليت ذكرا', 23, 45, 178, 1, 6, 446, false, NULL),
    (3792, 'tanzil-uthmani-v1.1', 37, 4, 'إِنَّ إِلَٰهَكُمْ لَوَٰحِدٌ', '4dddf855a7fb86baa9862d9adb699728d6cd521d72ddc918724f3637e2d243f8', 'إِنَّ إِلَٰهَكُمْ لَوَٰحِدٌ', '4dddf855a7fb86baa9862d9adb699728d6cd521d72ddc918724f3637e2d243f8', '4dddf855a7fb86baa9862d9adb699728d6cd521d72ddc918724f3637e2d243f8', NULL, 'ان الهكم لوحد', 23, 45, 178, 1, 6, 446, false, NULL),
