    (3973, 'tanzil-uthmani-v1.1', 38, 3, 'كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ فَنَادَوا۟ وَّلَاتَ حِينَ مَنَاصٍ', '4dfff9607e00e0c87f8db0c8b68da0e3d71be6c11900abbdd79ac24c65fbc179', 'كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ فَنَادَوا۟ وَّلَاتَ حِينَ مَنَاصٍ', '4dfff9607e00e0c87f8db0c8b68da0e3d71be6c11900abbdd79ac24c65fbc179', '4dfff9607e00e0c87f8db0c8b68da0e3d71be6c11900abbdd79ac24c65fbc179', NULL, 'كم اهلكنا من قبلهم من قرن فنادوا ولات حين مناص', 23, 46, 181, 1, 6, 453, false, NULL),
    (3974, 'tanzil-uthmani-v1.1', 38, 4, 'وَعَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ ٱلْكَٰفِرُونَ هَٰذَا سَٰحِرٌ كَذَّابٌ', '77755fa356e4a2b12f8fec990cd35008815878d6f209f8ff5def28e7dc32a2b5', 'وَعَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ ٱلْكَٰفِرُونَ هَٰذَا سَٰحِرٌ كَذَّابٌ', '77755fa356e4a2b12f8fec990cd35008815878d6f209f8ff5def28e7dc32a2b5', '77755fa356e4a2b12f8fec990cd35008815878d6f209f8ff5def28e7dc32a2b5', NULL, 'وعجبوا ان جاءهم منذر منهم وقال الكفرون هذا سحر كذاب', 23, 46, 181, 1, 6, 453, false, NULL),
    (3975, 'tanzil-uthmani-v1.1', 38, 5, 'أَجَعَلَ ٱلْـَٔالِهَةَ إِلَٰهًا وَٰحِدًا إِنَّ هَٰذَا لَشَىْءٌ عُجَابٌ', 'c4fb71b1459a9fdf77e7b559cc30606d4143d082e06d3fef17869c67897c4037', 'أَجَعَلَ ٱلْـَٔالِهَةَ إِلَٰهًا وَٰحِدًا إِنَّ هَٰذَا لَشَىْءٌ عُجَابٌ', 'c4fb71b1459a9fdf77e7b559cc30606d4143d082e06d3fef17869c67897c4037', 'c4fb71b1459a9fdf77e7b559cc30606d4143d082e06d3fef17869c67897c4037', NULL, 'اجعل الالهه الها وحدا ان هذا لشيء عجاب', 23, 46, 181, 1, 6, 453, false, NULL),
    (3976, 'tanzil-uthmani-v1.1', 38, 6, 'وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ أَنِ ٱمْشُوا۟ وَٱصْبِرُوا۟ عَلَىٰٓ ءَالِهَتِكُمْ إِنَّ هَٰذَا لَشَىْءٌ يُرَادُ', '3ac502ebe72ad8d0720c78181b901d6da2886bf7cf2031f8f43f83b3b1f10602', 'وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ أَنِ ٱمْشُوا۟ وَٱصْبِرُوا۟ عَلَىٰٓ ءَالِهَتِكُمْ إِنَّ هَٰذَا لَشَىْءٌ يُرَادُ', '3ac502ebe72ad8d0720c78181b901d6da2886bf7cf2031f8f43f83b3b1f10602', '3ac502ebe72ad8d0720c78181b901d6da2886bf7cf2031f8f43f83b3b1f10602', NULL, 'وانطلق الملا منهم ان امشوا واصبروا علي ءالهتكم ان هذا لشيء يراد', 23, 46, 181, 1, 6, 453, false, NULL),
    (3977, 'tanzil-uthmani-v1.1', 38, 7, 'مَا سَمِعْنَا بِهَٰذَا فِى ٱلْمِلَّةِ ٱلْـَٔاخِرَةِ إِنْ هَٰذَآ إِلَّا ٱخْتِلَٰقٌ', '97f227171f820bd9e4b34ddea439305343cadd4e6005b994c5d98b5bae7c8bc6', 'مَا سَمِعْنَا بِهَٰذَا فِى ٱلْمِلَّةِ ٱلْـَٔاخِرَةِ إِنْ هَٰذَآ إِلَّا ٱخْتِلَٰقٌ', '97f227171f820bd9e4b34ddea439305343cadd4e6005b994c5d98b5bae7c8bc6', '97f227171f820bd9e4b34ddea439305343cadd4e6005b994c5d98b5bae7c8bc6', NULL, 'ما سمعنا بهذا في المله الاخره ان هذا الا اختلق', 23, 46, 181, 1, 6, 453, false, NULL),
    (3978, 'tanzil-uthmani-v1.1', 38, 8, 'أَءُنزِلَ عَلَيْهِ ٱلذِّكْرُ مِنۢ بَيْنِنَا بَلْ هُمْ فِى شَكٍّ مِّن ذِكْرِى بَل لَّمَّا يَذُوقُوا۟ عَذَابِ', '879f44eb2621e7f7d8f96260567681a1a4116e20881afd8a8980fdb1abe6a5a8', 'أَءُنزِلَ عَلَيْهِ ٱلذِّكْرُ مِنۢ بَيْنِنَا بَلْ هُمْ فِى شَكٍّ مِّن ذِكْرِى بَل لَّمَّا يَذُوقُوا۟ عَذَابِ', '879f44eb2621e7f7d8f96260567681a1a4116e20881afd8a8980fdb1abe6a5a8', '879f44eb2621e7f7d8f96260567681a1a4116e20881afd8a8980fdb1abe6a5a8', NULL, 'اءنزل عليه الذكر من بيننا بل هم في شك من ذكري بل لما يذوقوا عذاب', 23, 46, 181, 1, 6, 453, false, NULL),
    (3979, 'tanzil-uthmani-v1.1', 38, 9, 'أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ٱلْعَزِيزِ ٱلْوَهَّابِ', 'dbf16418918d378cebe95ba506fe59b12f38e050e53d83a3b6efc448cfbb5aa5', 'أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ٱلْعَزِيزِ ٱلْوَهَّابِ', 'dbf16418918d378cebe95ba506fe59b12f38e050e53d83a3b6efc448cfbb5aa5', 'dbf16418918d378cebe95ba506fe59b12f38e050e53d83a3b6efc448cfbb5aa5', NULL, 'ام عندهم خزائن رحمه ربك العزيز الوهاب', 23, 46, 181, 1, 6, 453, false, NULL),
    (3980, 'tanzil-uthmani-v1.1', 38, 10, 'أَمْ لَهُم مُّلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَلْيَرْتَقُوا۟ فِى ٱلْأَسْبَٰبِ', 'bd4cdf98e71598dadc23980fdcbe548f06195143d7af0a11a12b62e26f448286', 'أَمْ لَهُم مُّلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَلْيَرْتَقُوا۟ فِى ٱلْأَسْبَٰبِ', 'bd4cdf98e71598dadc23980fdcbe548f06195143d7af0a11a12b62e26f448286', 'bd4cdf98e71598dadc23980fdcbe548f06195143d7af0a11a12b62e26f448286', NULL, 'ام لهم ملك السموت والارض وما بينهما فليرتقوا في الاسبب', 23, 46, 181, 1, 6, 453, false, NULL),
    (3981, 'tanzil-uthmani-v1.1', 38, 11, 'جُندٌ مَّا هُنَالِكَ مَهْزُومٌ مِّنَ ٱلْأَحْزَابِ', '8cd9c68f5d13fe0c294b8eeb941bf582fa9af2242e98f382274c7136dbee0f8b', 'جُندٌ مَّا هُنَالِكَ مَهْزُومٌ مِّنَ ٱلْأَحْزَابِ', '8cd9c68f5d13fe0c294b8eeb941bf582fa9af2242e98f382274c7136dbee0f8b', '8cd9c68f5d13fe0c294b8eeb941bf582fa9af2242e98f382274c7136dbee0f8b', NULL, 'جند ما هنالك مهزوم من الاحزاب', 23, 46, 181, 1, 6, 453, false, NULL),
    (3982, 'tanzil-uthmani-v1.1', 38, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَفِرْعَوْنُ ذُو ٱلْأَوْتَادِ', 'e98c258fe1b90de582c790cc2c6a43881ad7e418ebcb835170db88eee2b79bf5', 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَفِرْعَوْنُ ذُو ٱلْأَوْتَادِ', 'e98c258fe1b90de582c790cc2c6a43881ad7e418ebcb835170db88eee2b79bf5', 'e98c258fe1b90de582c790cc2c6a43881ad7e418ebcb835170db88eee2b79bf5', NULL, 'كذبت قبلهم قوم نوح وعاد وفرعون ذو الاوتاد', 23, 46, 181, 1, 6, 453, false, NULL),
    (3983, 'tanzil-uthmani-v1.1', 38, 13, 'وَثَمُودُ وَقَوْمُ لُوطٍ وَأَصْحَٰبُ لْـَٔيْكَةِ أُو۟لَٰٓئِكَ ٱلْأَحْزَابُ', 'a613c1897e2f250a3100800371dfa8cb2923f3ae60a627dbe219d5250388ba2d', 'وَثَمُودُ وَقَوْمُ لُوطٍ وَأَصْحَٰبُ لْـَٔيْكَةِ أُو۟لَٰٓئِكَ ٱلْأَحْزَابُ', 'a613c1897e2f250a3100800371dfa8cb2923f3ae60a627dbe219d5250388ba2d', 'a613c1897e2f250a3100800371dfa8cb2923f3ae60a627dbe219d5250388ba2d', NULL, 'وثمود وقوم لوط واصحب ليكه اولئك الاحزاب', 23, 46, 181, 1, 6, 453, false, NULL),
    (3984, 'tanzil-uthmani-v1.1', 38, 14, 'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ', '26528e1f90576e499acb9693ed0df052585f92ddc9608982b85ffb95b8c978b9', 'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ', '26528e1f90576e499acb9693ed0df052585f92ddc9608982b85ffb95b8c978b9', '26528e1f90576e499acb9693ed0df052585f92ddc9608982b85ffb95b8c978b9', NULL, 'ان كل الا كذب الرسل فحق عقاب', 23, 46, 181, 1, 6, 453, false, NULL),
    (3985, 'tanzil-uthmani-v1.1', 38, 15, 'وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيْحَةً وَٰحِدَةً مَّا لَهَا مِن فَوَاقٍ', '271a263a52760ee351f1e3f54e33dfac522bdc1961579ccb7541fd947fbb0df3', 'وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيْحَةً وَٰحِدَةً مَّا لَهَا مِن فَوَاقٍ', '271a263a52760ee351f1e3f54e33dfac522bdc1961579ccb7541fd947fbb0df3', '271a263a52760ee351f1e3f54e33dfac522bdc1961579ccb7541fd947fbb0df3', NULL, 'وما ينظر هؤلاء الا صيحه وحده ما لها من فواق', 23, 46, 181, 1, 6, 453, false, NULL),
    (3986, 'tanzil-uthmani-v1.1', 38, 16, 'وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ ٱلْحِسَابِ', '8e3518578f330eee04aa5b4acc5ce2aa72186ce2a31ed9a9ccb656cd089c6def', 'وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ ٱلْحِسَابِ', '8e3518578f330eee04aa5b4acc5ce2aa72186ce2a31ed9a9ccb656cd089c6def', '8e3518578f330eee04aa5b4acc5ce2aa72186ce2a31ed9a9ccb656cd089c6def', NULL, 'وقالوا ربنا عجل لنا قطنا قبل يوم الحساب', 23, 46, 181, 1, 6, 453, false, NULL),
    (3987, 'tanzil-uthmani-v1.1', 38, 17, 'ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ٱلْأَيْدِ إِنَّهُۥٓ أَوَّابٌ', '02131e0e3e50cbf91390f09027c50d0416288fe080baf87a697dc3c08274dab0', 'ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ٱلْأَيْدِ إِنَّهُۥٓ أَوَّابٌ', '02131e0e3e50cbf91390f09027c50d0416288fe080baf87a697dc3c08274dab0', '02131e0e3e50cbf91390f09027c50d0416288fe080baf87a697dc3c08274dab0', NULL, 'اصبر علي ما يقولون واذكر عبدنا داود ذا الايد انه اواب', 23, 46, 181, 1, 6, 454, false, NULL),
    (3988, 'tanzil-uthmani-v1.1', 38, 18, 'إِنَّا سَخَّرْنَا ٱلْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِٱلْعَشِىِّ وَٱلْإِشْرَاقِ', '2f234533c9a34c86c053225e6dda43d042a757ca962679215c26dceeb08b0dcc', 'إِنَّا سَخَّرْنَا ٱلْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِٱلْعَشِىِّ وَٱلْإِشْرَاقِ', '2f234533c9a34c86c053225e6dda43d042a757ca962679215c26dceeb08b0dcc', '2f234533c9a34c86c053225e6dda43d042a757ca962679215c26dceeb08b0dcc', NULL, 'انا سخرنا الجبال معه يسبحن بالعشي والاشراق', 23, 46, 181, 1, 6, 454, false, NULL),
    (3989, 'tanzil-uthmani-v1.1', 38, 19, 'وَٱلطَّيْرَ مَحْشُورَةً كُلٌّ لَّهُۥٓ أَوَّابٌ', '0e719c78513566c687ad76568031111a8dd3b2b9ffd81c964ec74d6cfa98d2f3', 'وَٱلطَّيْرَ مَحْشُورَةً كُلٌّ لَّهُۥٓ أَوَّابٌ', '0e719c78513566c687ad76568031111a8dd3b2b9ffd81c964ec74d6cfa98d2f3', '0e719c78513566c687ad76568031111a8dd3b2b9ffd81c964ec74d6cfa98d2f3', NULL, 'والطير محشوره كل له اواب', 23, 46, 181, 1, 6, 454, false, NULL),
    (3990, 'tanzil-uthmani-v1.1', 38, 20, 'وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَٰهُ ٱلْحِكْمَةَ وَفَصْلَ ٱلْخِطَابِ', '9150698a34a4184349b8173904032dcbcf6f5ee38679fcc27493ea4489c403f2', 'وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَٰهُ ٱلْحِكْمَةَ وَفَصْلَ ٱلْخِطَابِ', '9150698a34a4184349b8173904032dcbcf6f5ee38679fcc27493ea4489c403f2', '9150698a34a4184349b8173904032dcbcf6f5ee38679fcc27493ea4489c403f2', NULL, 'وشددنا ملكه وءاتينه الحكمه وفصل الخطاب', 23, 46, 181, 1, 6, 454, false, NULL),
    (3991, 'tanzil-uthmani-v1.1', 38, 21, 'وَهَلْ أَتَىٰكَ نَبَؤُا۟ ٱلْخَصْمِ إِذْ تَسَوَّرُوا۟ ٱلْمِحْرَابَ', '6c7f80bd7ede8b4e8bc22b5246a471faba4c709cda5e66489cdfa83a970f66e6', 'وَهَلْ أَتَىٰكَ نَبَؤُا۟ ٱلْخَصْمِ إِذْ تَسَوَّرُوا۟ ٱلْمِحْرَابَ', '6c7f80bd7ede8b4e8bc22b5246a471faba4c709cda5e66489cdfa83a970f66e6', '6c7f80bd7ede8b4e8bc22b5246a471faba4c709cda5e66489cdfa83a970f66e6', NULL, 'وهل اتيك نبؤا الخصم اذ تسوروا المحراب', 23, 46, 182, 1, 6, 454, false, NULL),
    (3992, 'tanzil-uthmani-v1.1', 38, 22, 'إِذْ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ قَالُوا۟ لَا تَخَفْ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍ فَٱحْكُم بَيْنَنَا بِٱلْحَقِّ وَلَا تُشْطِطْ وَٱهْدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ', '2eb4b54a645f7bdda19a7daca0668bb552ff03607439b9e847ae6f0708aecabb', 'إِذْ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ قَالُوا۟ لَا تَخَفْ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍ فَٱحْكُم بَيْنَنَا بِٱلْحَقِّ وَلَا تُشْطِطْ وَٱهْدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ', '2eb4b54a645f7bdda19a7daca0668bb552ff03607439b9e847ae6f0708aecabb', '2eb4b54a645f7bdda19a7daca0668bb552ff03607439b9e847ae6f0708aecabb', NULL, 'اذ دخلوا علي داود ففزع منهم قالوا لا تخف خصمان بغي بعضنا علي بعض فاحكم بيننا بالحق ولا تشطط واهدنا الي سواء الصرط', 23, 46, 182, 1, 6, 454, false, NULL),
    (3993, 'tanzil-uthmani-v1.1', 38, 23, 'إِنَّ هَٰذَآ أَخِى لَهُۥ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِىَ نَعْجَةٌ وَٰحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى ٱلْخِطَابِ', 'b1a1d550993f85262a431cdaa42492db8073e37ef11293c46d8b6621d5997461', 'إِنَّ هَٰذَآ أَخِى لَهُۥ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِىَ نَعْجَةٌ وَٰحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى ٱلْخِطَابِ', 'b1a1d550993f85262a431cdaa42492db8073e37ef11293c46d8b6621d5997461', 'b1a1d550993f85262a431cdaa42492db8073e37ef11293c46d8b6621d5997461', NULL, 'ان هذا اخي له تسع وتسعون نعجه ولي نعجه وحده فقال اكفلنيها وعزني في الخطاب', 23, 46, 182, 1, 6, 454, false, NULL),
    (3994, 'tanzil-uthmani-v1.1', 38, 24, 'قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ وَإِنَّ كَثِيرًا مِّنَ ٱلْخُلَطَآءِ لَيَبْغِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَقَلِيلٌ مَّا هُمْ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعًا وَأَنَابَ', '86bf6d6925fb23659bea0271088673f057e516f6eeadd5730674eb4227ab063b', 'قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ وَإِنَّ كَثِيرًا مِّنَ ٱلْخُلَطَآءِ لَيَبْغِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَقَلِيلٌ مَّا هُمْ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعًا وَأَنَابَ', '86bf6d6925fb23659bea0271088673f057e516f6eeadd5730674eb4227ab063b', '86bf6d6925fb23659bea0271088673f057e516f6eeadd5730674eb4227ab063b', NULL, 'قال لقد ظلمك بسؤال نعجتك الي نعاجه وان كثيرا من الخلطاء ليبغي بعضهم علي بعض الا الذين ءامنوا وعملوا الصلحت وقليل ما هم وظن داود انما فتنه فاستغفر ربه وخر راكعا واناب', 23, 46, 182, 1, 6, 454, true, 'recommended'),
    (3995, 'tanzil-uthmani-v1.1', 38, 25, 'فَغَفَرْنَا لَهُۥ ذَٰلِكَ وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', '782f186c203d95e3a134dc3ce9393c1f19ec03dac34d5ce99a3b587ce215d58d', 'فَغَفَرْنَا لَهُۥ ذَٰلِكَ وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', '782f186c203d95e3a134dc3ce9393c1f19ec03dac34d5ce99a3b587ce215d58d', '782f186c203d95e3a134dc3ce9393c1f19ec03dac34d5ce99a3b587ce215d58d', NULL, 'فغفرنا له ذلك وان له عندنا لزلفي وحسن ماب', 23, 46, 182, 1, 6, 454, false, NULL),
    (3996, 'tanzil-uthmani-v1.1', 38, 26, 'يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةً فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ', '0e29808a537c828fe0b7da386f789ed53c229116bd5d53e107c1ec136f517d63', 'يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةً فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ', '0e29808a537c828fe0b7da386f789ed53c229116bd5d53e107c1ec136f517d63', '0e29808a537c828fe0b7da386f789ed53c229116bd5d53e107c1ec136f517d63', NULL, 'يداود انا جعلنك خليفه في الارض فاحكم بين الناس بالحق ولا تتبع الهوي فيضلك عن سبيل الله ان الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب', 23, 46, 182, 1, 6, 454, false, NULL),
    (3997, 'tanzil-uthmani-v1.1', 38, 27, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا بَٰطِلًا ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُوا۟ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِنَ ٱلنَّارِ', '822c3ccaec4fba0d4c26ce9b1efc472d2ccdffb8bdd0ea4570e6ef1100ec4813', 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا بَٰطِلًا ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُوا۟ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِنَ ٱلنَّارِ', '822c3ccaec4fba0d4c26ce9b1efc472d2ccdffb8bdd0ea4570e6ef1100ec4813', '822c3ccaec4fba0d4c26ce9b1efc472d2ccdffb8bdd0ea4570e6ef1100ec4813', NULL, 'وما خلقنا السماء والارض وما بينهما بطلا ذلك ظن الذين كفروا فويل للذين كفروا من النار', 23, 46, 182, 1, 6, 455, false, NULL),
    (3998, 'tanzil-uthmani-v1.1', 38, 28, 'أَمْ نَجْعَلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَٱلْمُفْسِدِينَ فِى ٱلْأَرْضِ أَمْ نَجْعَلُ ٱلْمُتَّقِينَ كَٱلْفُجَّارِ', 'a37f96cd30d54b2070a0dd9887da885ca3391101443d56e8b3c9c333f2dbf84b', 'أَمْ نَجْعَلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَٱلْمُفْسِدِينَ فِى ٱلْأَرْضِ أَمْ نَجْعَلُ ٱلْمُتَّقِينَ كَٱلْفُجَّارِ', 'a37f96cd30d54b2070a0dd9887da885ca3391101443d56e8b3c9c333f2dbf84b', 'a37f96cd30d54b2070a0dd9887da885ca3391101443d56e8b3c9c333f2dbf84b', NULL, 'ام نجعل الذين ءامنوا وعملوا الصلحت كالمفسدين في الارض ام نجعل المتقين كالفجار', 23, 46, 182, 1, 6, 455, false, NULL),
    (3999, 'tanzil-uthmani-v1.1', 38, 29, 'كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكٌ لِّيَدَّبَّرُوٓا۟ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '4198d9220d5f0887c09b4c71ace4e976cba6643d079e463eaf36d909d754c42a', 'كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكٌ لِّيَدَّبَّرُوٓا۟ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '4198d9220d5f0887c09b4c71ace4e976cba6643d079e463eaf36d909d754c42a', '4198d9220d5f0887c09b4c71ace4e976cba6643d079e463eaf36d909d754c42a', NULL, 'كتب انزلنه اليك مبرك ليدبروا ءايته وليتذكر اولوا الالبب', 23, 46, 182, 1, 6, 455, false, NULL),
    (4000, 'tanzil-uthmani-v1.1', 38, 30, 'وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَٰنَ نِعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ', 'b8f19c14465a8d0307be6bf92b26f1a098064a9c2a8cbd9f8281a588b70401a1', 'وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَٰنَ نِعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ', 'b8f19c14465a8d0307be6bf92b26f1a098064a9c2a8cbd9f8281a588b70401a1', 'b8f19c14465a8d0307be6bf92b26f1a098064a9c2a8cbd9f8281a588b70401a1', NULL, 'ووهبنا لداود سليمن نعم العبد انه اواب', 23, 46, 182, 1, 6, 455, false, NULL)
