    (4001, 'tanzil-uthmani-v1.1', 38, 31, 'إِذْ عُرِضَ عَلَيْهِ بِٱلْعَشِىِّ ٱلصَّٰفِنَٰتُ ٱلْجِيَادُ', '9edc456c64ea7650e069a9c641454cd6aa7bf7fd6d7f112dbb7cb42dd33404d8', 'إِذْ عُرِضَ عَلَيْهِ بِٱلْعَشِىِّ ٱلصَّٰفِنَٰتُ ٱلْجِيَادُ', '9edc456c64ea7650e069a9c641454cd6aa7bf7fd6d7f112dbb7cb42dd33404d8', '9edc456c64ea7650e069a9c641454cd6aa7bf7fd6d7f112dbb7cb42dd33404d8', NULL, 'اذ عرض عليه بالعشي الصفنت الجياد', 23, 46, 182, 1, 6, 455, false, NULL),
    (4002, 'tanzil-uthmani-v1.1', 38, 32, 'فَقَالَ إِنِّىٓ أَحْبَبْتُ حُبَّ ٱلْخَيْرِ عَن ذِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِٱلْحِجَابِ', '62799ee44a52db3f340eeb596ffc507ed0830e7ab0419fe2c840aa73770a27e0', 'فَقَالَ إِنِّىٓ أَحْبَبْتُ حُبَّ ٱلْخَيْرِ عَن ذِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِٱلْحِجَابِ', '62799ee44a52db3f340eeb596ffc507ed0830e7ab0419fe2c840aa73770a27e0', '62799ee44a52db3f340eeb596ffc507ed0830e7ab0419fe2c840aa73770a27e0', NULL, 'فقال اني احببت حب الخير عن ذكر ربي حتي توارت بالحجاب', 23, 46, 182, 1, 6, 455, false, NULL),
    (4003, 'tanzil-uthmani-v1.1', 38, 33, 'رُدُّوهَا عَلَىَّ فَطَفِقَ مَسْحًۢا بِٱلسُّوقِ وَٱلْأَعْنَاقِ', 'c0fbb52d2ae5c52646ffd5ce8862fce73d9dd6fce14254c1e72e012f7126c491', 'رُدُّوهَا عَلَىَّ فَطَفِقَ مَسْحًۢا بِٱلسُّوقِ وَٱلْأَعْنَاقِ', 'c0fbb52d2ae5c52646ffd5ce8862fce73d9dd6fce14254c1e72e012f7126c491', 'c0fbb52d2ae5c52646ffd5ce8862fce73d9dd6fce14254c1e72e012f7126c491', NULL, 'ردوها علي فطفق مسحا بالسوق والاعناق', 23, 46, 182, 1, 6, 455, false, NULL),
    (4004, 'tanzil-uthmani-v1.1', 38, 34, 'وَلَقَدْ فَتَنَّا سُلَيْمَٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَدًا ثُمَّ أَنَابَ', '6dcba0aefc9fafb30593f98c38893b89b5f5b2545a9f0d9eabd843c3ff14219f', 'وَلَقَدْ فَتَنَّا سُلَيْمَٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَدًا ثُمَّ أَنَابَ', '6dcba0aefc9fafb30593f98c38893b89b5f5b2545a9f0d9eabd843c3ff14219f', '6dcba0aefc9fafb30593f98c38893b89b5f5b2545a9f0d9eabd843c3ff14219f', NULL, 'ولقد فتنا سليمن والقينا علي كرسيه جسدا ثم اناب', 23, 46, 182, 1, 6, 455, false, NULL),
    (4005, 'tanzil-uthmani-v1.1', 38, 35, 'قَالَ رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًا لَّا يَنۢبَغِى لِأَحَدٍ مِّنۢ بَعْدِىٓ إِنَّكَ أَنتَ ٱلْوَهَّابُ', 'd2ffb6330d56cafcc6fd49de68fd0e3617c9825e42ff082b3a5634b553e3beb6', 'قَالَ رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًا لَّا يَنۢبَغِى لِأَحَدٍ مِّنۢ بَعْدِىٓ إِنَّكَ أَنتَ ٱلْوَهَّابُ', 'd2ffb6330d56cafcc6fd49de68fd0e3617c9825e42ff082b3a5634b553e3beb6', 'd2ffb6330d56cafcc6fd49de68fd0e3617c9825e42ff082b3a5634b553e3beb6', NULL, 'قال رب اغفر لي وهب لي ملكا لا ينبغي لاحد من بعدي انك انت الوهاب', 23, 46, 182, 1, 6, 455, false, NULL),
    (4006, 'tanzil-uthmani-v1.1', 38, 36, 'فَسَخَّرْنَا لَهُ ٱلرِّيحَ تَجْرِى بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ', '7e709215d0065fed25e25a0c4f2d5241442fa9a7aae04ba8327288267428662e', 'فَسَخَّرْنَا لَهُ ٱلرِّيحَ تَجْرِى بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ', '7e709215d0065fed25e25a0c4f2d5241442fa9a7aae04ba8327288267428662e', '7e709215d0065fed25e25a0c4f2d5241442fa9a7aae04ba8327288267428662e', NULL, 'فسخرنا له الريح تجري بامره رخاء حيث اصاب', 23, 46, 182, 1, 6, 455, false, NULL),
    (4007, 'tanzil-uthmani-v1.1', 38, 37, 'وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٍ وَغَوَّاصٍ', '9e1b693be082dfb47192fb60f434b63d004febc7f70f8a55d2e6813a0459d2ae', 'وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٍ وَغَوَّاصٍ', '9e1b693be082dfb47192fb60f434b63d004febc7f70f8a55d2e6813a0459d2ae', '9e1b693be082dfb47192fb60f434b63d004febc7f70f8a55d2e6813a0459d2ae', NULL, 'والشيطين كل بناء وغواص', 23, 46, 182, 1, 6, 455, false, NULL),
    (4008, 'tanzil-uthmani-v1.1', 38, 38, 'وَءَاخَرِينَ مُقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'e46e8be02820208f7a39bca5598ca4a9e045c38ad6d31f9146aa39a9affda15a', 'وَءَاخَرِينَ مُقَرَّنِينَ فِى ٱلْأَصْفَادِ', 'e46e8be02820208f7a39bca5598ca4a9e045c38ad6d31f9146aa39a9affda15a', 'e46e8be02820208f7a39bca5598ca4a9e045c38ad6d31f9146aa39a9affda15a', NULL, 'وءاخرين مقرنين في الاصفاد', 23, 46, 182, 1, 6, 455, false, NULL),
    (4009, 'tanzil-uthmani-v1.1', 38, 39, 'هَٰذَا عَطَآؤُنَا فَٱمْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ', '507ccde572277086df6b4576cdd79bec2dd23dfd7662bb8c9ef90cba3083b605', 'هَٰذَا عَطَآؤُنَا فَٱمْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ', '507ccde572277086df6b4576cdd79bec2dd23dfd7662bb8c9ef90cba3083b605', '507ccde572277086df6b4576cdd79bec2dd23dfd7662bb8c9ef90cba3083b605', NULL, 'هذا عطاؤنا فامنن او امسك بغير حساب', 23, 46, 182, 1, 6, 455, false, NULL),
    (4010, 'tanzil-uthmani-v1.1', 38, 40, 'وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', '1462ab2f9d6801b41c1a9bfb22c470f0831e9523dff8a432346f21fb220ae370', 'وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ', '1462ab2f9d6801b41c1a9bfb22c470f0831e9523dff8a432346f21fb220ae370', '1462ab2f9d6801b41c1a9bfb22c470f0831e9523dff8a432346f21fb220ae370', NULL, 'وان له عندنا لزلفي وحسن ماب', 23, 46, 182, 1, 6, 455, false, NULL),
    (4011, 'tanzil-uthmani-v1.1', 38, 41, 'وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَٰنُ بِنُصْبٍ وَعَذَابٍ', '7eedce7d3dd73492d8b1df4c3a63405ae2ec567ed0818e6934a5b691adbd99ce', 'وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَٰنُ بِنُصْبٍ وَعَذَابٍ', '7eedce7d3dd73492d8b1df4c3a63405ae2ec567ed0818e6934a5b691adbd99ce', '7eedce7d3dd73492d8b1df4c3a63405ae2ec567ed0818e6934a5b691adbd99ce', NULL, 'واذكر عبدنا ايوب اذ نادي ربه اني مسني الشيطن بنصب وعذاب', 23, 46, 182, 1, 6, 455, false, NULL),
    (4012, 'tanzil-uthmani-v1.1', 38, 42, 'ٱرْكُضْ بِرِجْلِكَ هَٰذَا مُغْتَسَلٌۢ بَارِدٌ وَشَرَابٌ', 'cdc6f6b93eb27fa840c1b0ebe73c4db9018c51c778822fdf9b96ee29a20111cb', 'ٱرْكُضْ بِرِجْلِكَ هَٰذَا مُغْتَسَلٌۢ بَارِدٌ وَشَرَابٌ', 'cdc6f6b93eb27fa840c1b0ebe73c4db9018c51c778822fdf9b96ee29a20111cb', 'cdc6f6b93eb27fa840c1b0ebe73c4db9018c51c778822fdf9b96ee29a20111cb', NULL, 'اركض برجلك هذا مغتسل بارد وشراب', 23, 46, 182, 1, 6, 455, false, NULL),
    (4013, 'tanzil-uthmani-v1.1', 38, 43, 'وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنَّا وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'c91fcbf88447da42deccb0e6c671233d227a4400d04fff79ae6181dca09bbe3d', 'وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنَّا وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'c91fcbf88447da42deccb0e6c671233d227a4400d04fff79ae6181dca09bbe3d', 'c91fcbf88447da42deccb0e6c671233d227a4400d04fff79ae6181dca09bbe3d', NULL, 'ووهبنا له اهله ومثلهم معهم رحمه منا وذكري لاولي الالبب', 23, 46, 182, 1, 6, 456, false, NULL),
    (4014, 'tanzil-uthmani-v1.1', 38, 44, 'وَخُذْ بِيَدِكَ ضِغْثًا فَٱضْرِب بِّهِۦ وَلَا تَحْنَثْ إِنَّا وَجَدْنَٰهُ صَابِرًا نِّعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ', 'c05f5a65b816b14597df1a5535cb56ee10686f7be2794d29c97bf1306cda6d94', 'وَخُذْ بِيَدِكَ ضِغْثًا فَٱضْرِب بِّهِۦ وَلَا تَحْنَثْ إِنَّا وَجَدْنَٰهُ صَابِرًا نِّعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ', 'c05f5a65b816b14597df1a5535cb56ee10686f7be2794d29c97bf1306cda6d94', 'c05f5a65b816b14597df1a5535cb56ee10686f7be2794d29c97bf1306cda6d94', NULL, 'وخذ بيدك ضغثا فاضرب به ولا تحنث انا وجدنه صابرا نعم العبد انه اواب', 23, 46, 182, 1, 6, 456, false, NULL),
    (4015, 'tanzil-uthmani-v1.1', 38, 45, 'وَٱذْكُرْ عِبَٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ أُو۟لِى ٱلْأَيْدِى وَٱلْأَبْصَٰرِ', 'f03eade149406c52628e0f52eccbbb7c1ac752c45e9c5ae80b23ed8701f3daff', 'وَٱذْكُرْ عِبَٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ أُو۟لِى ٱلْأَيْدِى وَٱلْأَبْصَٰرِ', 'f03eade149406c52628e0f52eccbbb7c1ac752c45e9c5ae80b23ed8701f3daff', 'f03eade149406c52628e0f52eccbbb7c1ac752c45e9c5ae80b23ed8701f3daff', NULL, 'واذكر عبدنا ابرهيم واسحق ويعقوب اولي الايدي والابصر', 23, 46, 182, 1, 6, 456, false, NULL),
    (4016, 'tanzil-uthmani-v1.1', 38, 46, 'إِنَّآ أَخْلَصْنَٰهُم بِخَالِصَةٍ ذِكْرَى ٱلدَّارِ', '140a45d1025235221d9fffe9058524dde19ef9d1a90d966a32148022343982ca', 'إِنَّآ أَخْلَصْنَٰهُم بِخَالِصَةٍ ذِكْرَى ٱلدَّارِ', '140a45d1025235221d9fffe9058524dde19ef9d1a90d966a32148022343982ca', '140a45d1025235221d9fffe9058524dde19ef9d1a90d966a32148022343982ca', NULL, 'انا اخلصنهم بخالصه ذكري الدار', 23, 46, 182, 1, 6, 456, false, NULL),
    (4017, 'tanzil-uthmani-v1.1', 38, 47, 'وَإِنَّهُمْ عِندَنَا لَمِنَ ٱلْمُصْطَفَيْنَ ٱلْأَخْيَارِ', '562a902d50bd3684308f397164da6ea43a2d76bac356ada8744a2723892a09e3', 'وَإِنَّهُمْ عِندَنَا لَمِنَ ٱلْمُصْطَفَيْنَ ٱلْأَخْيَارِ', '562a902d50bd3684308f397164da6ea43a2d76bac356ada8744a2723892a09e3', '562a902d50bd3684308f397164da6ea43a2d76bac356ada8744a2723892a09e3', NULL, 'وانهم عندنا لمن المصطفين الاخيار', 23, 46, 182, 1, 6, 456, false, NULL),
    (4018, 'tanzil-uthmani-v1.1', 38, 48, 'وَٱذْكُرْ إِسْمَٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ وَكُلٌّ مِّنَ ٱلْأَخْيَارِ', '633e44b983d8030be0e33cefaa2789e6affbed468d0522afa3bc9fab2e754f34', 'وَٱذْكُرْ إِسْمَٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ وَكُلٌّ مِّنَ ٱلْأَخْيَارِ', '633e44b983d8030be0e33cefaa2789e6affbed468d0522afa3bc9fab2e754f34', '633e44b983d8030be0e33cefaa2789e6affbed468d0522afa3bc9fab2e754f34', NULL, 'واذكر اسمعيل واليسع وذا الكفل وكل من الاخيار', 23, 46, 182, 1, 6, 456, false, NULL),
    (4019, 'tanzil-uthmani-v1.1', 38, 49, 'هَٰذَا ذِكْرٌ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابٍ', 'd797670b558ab191bcf4fcd3a06df4c7e576e882f32872af37d2d05a9cdbccbc', 'هَٰذَا ذِكْرٌ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابٍ', 'd797670b558ab191bcf4fcd3a06df4c7e576e882f32872af37d2d05a9cdbccbc', 'd797670b558ab191bcf4fcd3a06df4c7e576e882f32872af37d2d05a9cdbccbc', NULL, 'هذا ذكر وان للمتقين لحسن ماب', 23, 46, 182, 1, 6, 456, false, NULL),
    (4020, 'tanzil-uthmani-v1.1', 38, 50, 'جَنَّٰتِ عَدْنٍ مُّفَتَّحَةً لَّهُمُ ٱلْأَبْوَٰبُ', '1d4d968634ee894a50901ef26ae9c17963e7047f4b6d1280102b4cc9fa7cad72', 'جَنَّٰتِ عَدْنٍ مُّفَتَّحَةً لَّهُمُ ٱلْأَبْوَٰبُ', '1d4d968634ee894a50901ef26ae9c17963e7047f4b6d1280102b4cc9fa7cad72', '1d4d968634ee894a50901ef26ae9c17963e7047f4b6d1280102b4cc9fa7cad72', NULL, 'جنت عدن مفتحه لهم الابوب', 23, 46, 182, 1, 6, 456, false, NULL),
    (4021, 'tanzil-uthmani-v1.1', 38, 51, 'مُتَّكِـِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةٍ كَثِيرَةٍ وَشَرَابٍ', '2cdf48f81eeabe610daad11147752a85c84452c8af71a2895e14c48d832e3af6', 'مُتَّكِـِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةٍ كَثِيرَةٍ وَشَرَابٍ', '2cdf48f81eeabe610daad11147752a85c84452c8af71a2895e14c48d832e3af6', '2cdf48f81eeabe610daad11147752a85c84452c8af71a2895e14c48d832e3af6', NULL, 'متكين فيها يدعون فيها بفكهه كثيره وشراب', 23, 46, 182, 1, 6, 456, false, NULL),
    (4022, 'tanzil-uthmani-v1.1', 38, 52, 'وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ أَتْرَابٌ', '3c100857579b8d7dc5cdb988ce147e2efecaa927c5458c5212cdb9731bf1dd17', 'وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ أَتْرَابٌ', '3c100857579b8d7dc5cdb988ce147e2efecaa927c5458c5212cdb9731bf1dd17', '3c100857579b8d7dc5cdb988ce147e2efecaa927c5458c5212cdb9731bf1dd17', NULL, 'وعندهم قصرت الطرف اتراب', 23, 46, 183, 1, 6, 456, false, NULL),
    (4023, 'tanzil-uthmani-v1.1', 38, 53, 'هَٰذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ', '80e9be50c9c3db58083b7e20bf00d033e8fc58ed83a6bbb0ecb57e967b114591', 'هَٰذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ', '80e9be50c9c3db58083b7e20bf00d033e8fc58ed83a6bbb0ecb57e967b114591', '80e9be50c9c3db58083b7e20bf00d033e8fc58ed83a6bbb0ecb57e967b114591', NULL, 'هذا ما توعدون ليوم الحساب', 23, 46, 183, 1, 6, 456, false, NULL),
    (4024, 'tanzil-uthmani-v1.1', 38, 54, 'إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ', '126c00306742cb03b1390d542686bd23ba2b7e1b72595f43be7bb2812fc2bf5e', 'إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ', '126c00306742cb03b1390d542686bd23ba2b7e1b72595f43be7bb2812fc2bf5e', '126c00306742cb03b1390d542686bd23ba2b7e1b72595f43be7bb2812fc2bf5e', NULL, 'ان هذا لرزقنا ما له من نفاد', 23, 46, 183, 1, 6, 456, false, NULL),
    (4025, 'tanzil-uthmani-v1.1', 38, 55, 'هَٰذَا وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابٍ', '4d5fd523153965e582ce0689840e262951c2b728bae86529d601df9c3b415f00', 'هَٰذَا وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابٍ', '4d5fd523153965e582ce0689840e262951c2b728bae86529d601df9c3b415f00', '4d5fd523153965e582ce0689840e262951c2b728bae86529d601df9c3b415f00', NULL, 'هذا وان للطغين لشر ماب', 23, 46, 183, 1, 6, 456, false, NULL),
    (4026, 'tanzil-uthmani-v1.1', 38, 56, 'جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ ٱلْمِهَادُ', '96bfc4e29713c51ea6550f6a33835b5f985d1e369f7c2b41de658a61f9cfdf8c', 'جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ ٱلْمِهَادُ', '96bfc4e29713c51ea6550f6a33835b5f985d1e369f7c2b41de658a61f9cfdf8c', '96bfc4e29713c51ea6550f6a33835b5f985d1e369f7c2b41de658a61f9cfdf8c', NULL, 'جهنم يصلونها فبئس المهاد', 23, 46, 183, 1, 6, 456, false, NULL),
    (4027, 'tanzil-uthmani-v1.1', 38, 57, 'هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ', 'ec65b60c7252e748564dedcee46f607a4bc028d9aa3e581b6275e0e6cdd71bfc', 'هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ', 'ec65b60c7252e748564dedcee46f607a4bc028d9aa3e581b6275e0e6cdd71bfc', 'ec65b60c7252e748564dedcee46f607a4bc028d9aa3e581b6275e0e6cdd71bfc', NULL, 'هذا فليذوقوه حميم وغساق', 23, 46, 183, 1, 6, 456, false, NULL),
    (4028, 'tanzil-uthmani-v1.1', 38, 58, 'وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ', '5d77db71de5e0aca7d23a6a226005b79f6497ea03a8e81eecaaaccb65d9bbf32', 'وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ', '5d77db71de5e0aca7d23a6a226005b79f6497ea03a8e81eecaaaccb65d9bbf32', '5d77db71de5e0aca7d23a6a226005b79f6497ea03a8e81eecaaaccb65d9bbf32', NULL, 'وءاخر من شكله ازوج', 23, 46, 183, 1, 6, 456, false, NULL),
    (4029, 'tanzil-uthmani-v1.1', 38, 59, 'هَٰذَا فَوْجٌ مُّقْتَحِمٌ مَّعَكُمْ لَا مَرْحَبًۢا بِهِمْ إِنَّهُمْ صَالُوا۟ ٱلنَّارِ', '425066096ac68ff3b2f431881f162d334f1e51693d3657724ca7f0c2e25b89bf', 'هَٰذَا فَوْجٌ مُّقْتَحِمٌ مَّعَكُمْ لَا مَرْحَبًۢا بِهِمْ إِنَّهُمْ صَالُوا۟ ٱلنَّارِ', '425066096ac68ff3b2f431881f162d334f1e51693d3657724ca7f0c2e25b89bf', '425066096ac68ff3b2f431881f162d334f1e51693d3657724ca7f0c2e25b89bf', NULL, 'هذا فوج مقتحم معكم لا مرحبا بهم انهم صالوا النار', 23, 46, 183, 1, 6, 456, false, NULL),
    (4030, 'tanzil-uthmani-v1.1', 38, 60, 'قَالُوا۟ بَلْ أَنتُمْ لَا مَرْحَبًۢا بِكُمْ أَنتُمْ قَدَّمْتُمُوهُ لَنَا فَبِئْسَ ٱلْقَرَارُ', 'bfda23996c6a4c31c84c873cc468aa63afa2cf94b370103ef373376920850b66', 'قَالُوا۟ بَلْ أَنتُمْ لَا مَرْحَبًۢا بِكُمْ أَنتُمْ قَدَّمْتُمُوهُ لَنَا فَبِئْسَ ٱلْقَرَارُ', 'bfda23996c6a4c31c84c873cc468aa63afa2cf94b370103ef373376920850b66', 'bfda23996c6a4c31c84c873cc468aa63afa2cf94b370103ef373376920850b66', NULL, 'قالوا بل انتم لا مرحبا بكم انتم قدمتموه لنا فبئس القرار', 23, 46, 183, 1, 6, 456, false, NULL),
