    (4032, 'tanzil-uthmani-v1.1', 38, 62, 'وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالًا كُنَّا نَعُدُّهُم مِّنَ ٱلْأَشْرَارِ', '921e60683b5429750f59df7fe2be935506cb1523c7d0509ceb17f71b1941e8ee', 'وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالًا كُنَّا نَعُدُّهُم مِّنَ ٱلْأَشْرَارِ', '921e60683b5429750f59df7fe2be935506cb1523c7d0509ceb17f71b1941e8ee', '921e60683b5429750f59df7fe2be935506cb1523c7d0509ceb17f71b1941e8ee', NULL, 'وقالوا ما لنا لا نري رجالا كنا نعدهم من الاشرار', 23, 46, 183, 1, 6, 457, false, NULL),
    (4033, 'tanzil-uthmani-v1.1', 38, 63, 'أَتَّخَذْنَٰهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ ٱلْأَبْصَٰرُ', '14b05b99dcd4b6a62b6938a01c2a17d8b60557f2ca7143f60809d75fda7649fd', 'أَتَّخَذْنَٰهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ ٱلْأَبْصَٰرُ', '14b05b99dcd4b6a62b6938a01c2a17d8b60557f2ca7143f60809d75fda7649fd', '14b05b99dcd4b6a62b6938a01c2a17d8b60557f2ca7143f60809d75fda7649fd', NULL, 'اتخذنهم سخريا ام زاغت عنهم الابصر', 23, 46, 183, 1, 6, 457, false, NULL),
    (4034, 'tanzil-uthmani-v1.1', 38, 64, 'إِنَّ ذَٰلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ ٱلنَّارِ', '5f4d21ace62a29ed697cd801eeadb44d9044c4dfafd9fb9afd8b7e0a90f63795', 'إِنَّ ذَٰلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ ٱلنَّارِ', '5f4d21ace62a29ed697cd801eeadb44d9044c4dfafd9fb9afd8b7e0a90f63795', '5f4d21ace62a29ed697cd801eeadb44d9044c4dfafd9fb9afd8b7e0a90f63795', NULL, 'ان ذلك لحق تخاصم اهل النار', 23, 46, 183, 1, 6, 457, false, NULL),
    (4035, 'tanzil-uthmani-v1.1', 38, 65, 'قُلْ إِنَّمَآ أَنَا۠ مُنذِرٌ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'd1fcfe03137d606090c2a3791afce8aceff7f3b18496a1267baf65528c0ad673', 'قُلْ إِنَّمَآ أَنَا۠ مُنذِرٌ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'd1fcfe03137d606090c2a3791afce8aceff7f3b18496a1267baf65528c0ad673', 'd1fcfe03137d606090c2a3791afce8aceff7f3b18496a1267baf65528c0ad673', NULL, 'قل انما انا منذر وما من اله الا الله الوحد القهار', 23, 46, 183, 1, 6, 457, false, NULL),
    (4036, 'tanzil-uthmani-v1.1', 38, 66, 'رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلْعَزِيزُ ٱلْغَفَّٰرُ', '97271985142eeb280dcf9d19f9a6eaa07f196a0e803674809f4a64949e74c210', 'رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلْعَزِيزُ ٱلْغَفَّٰرُ', '97271985142eeb280dcf9d19f9a6eaa07f196a0e803674809f4a64949e74c210', '97271985142eeb280dcf9d19f9a6eaa07f196a0e803674809f4a64949e74c210', NULL, 'رب السموت والارض وما بينهما العزيز الغفر', 23, 46, 183, 1, 6, 457, false, NULL),
