    (4038, 'tanzil-uthmani-v1.1', 38, 68, 'أَنتُمْ عَنْهُ مُعْرِضُونَ', '268dbd94497b2e543f8379e27127f623375da9363ab3578de33cbaf6de15ae3a', 'أَنتُمْ عَنْهُ مُعْرِضُونَ', '268dbd94497b2e543f8379e27127f623375da9363ab3578de33cbaf6de15ae3a', '268dbd94497b2e543f8379e27127f623375da9363ab3578de33cbaf6de15ae3a', NULL, 'انتم عنه معرضون', 23, 46, 183, 1, 6, 457, false, NULL),
    (4039, 'tanzil-uthmani-v1.1', 38, 69, 'مَا كَانَ لِىَ مِنْ عِلْمٍۭ بِٱلْمَلَإِ ٱلْأَعْلَىٰٓ إِذْ يَخْتَصِمُونَ', 'f5ea968b116502b28212e591a46e5542ad387f2bf5b523618b79593dfdab419d', 'مَا كَانَ لِىَ مِنْ عِلْمٍۭ بِٱلْمَلَإِ ٱلْأَعْلَىٰٓ إِذْ يَخْتَصِمُونَ', 'f5ea968b116502b28212e591a46e5542ad387f2bf5b523618b79593dfdab419d', 'f5ea968b116502b28212e591a46e5542ad387f2bf5b523618b79593dfdab419d', NULL, 'ما كان لي من علم بالملا الاعلي اذ يختصمون', 23, 46, 183, 1, 6, 457, false, NULL),
    (4040, 'tanzil-uthmani-v1.1', 38, 70, 'إِن يُوحَىٰٓ إِلَىَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', '9c1530190a738e582d07c1350f5eea9125a488f7c7f95cbb072d8b102763b16c', 'إِن يُوحَىٰٓ إِلَىَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', '9c1530190a738e582d07c1350f5eea9125a488f7c7f95cbb072d8b102763b16c', '9c1530190a738e582d07c1350f5eea9125a488f7c7f95cbb072d8b102763b16c', NULL, 'ان يوحي الي الا انما انا نذير مبين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4041, 'tanzil-uthmani-v1.1', 38, 71, 'إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًا مِّن طِينٍ', '55a861b1d8311166387c0ed052af8e33731c064407849f9419f603d063180b76', 'إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًا مِّن طِينٍ', '55a861b1d8311166387c0ed052af8e33731c064407849f9419f603d063180b76', '55a861b1d8311166387c0ed052af8e33731c064407849f9419f603d063180b76', NULL, 'اذ قال ربك للملئكه اني خلق بشرا من طين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4042, 'tanzil-uthmani-v1.1', 38, 72, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'a75706fff1b49661297bf6a3fa839e9001809b70d1adaf8abab09da44d82d222', 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 'a75706fff1b49661297bf6a3fa839e9001809b70d1adaf8abab09da44d82d222', 'a75706fff1b49661297bf6a3fa839e9001809b70d1adaf8abab09da44d82d222', NULL, 'فاذا سويته ونفخت فيه من روحي فقعوا له سجدين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4043, 'tanzil-uthmani-v1.1', 38, 73, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', '5c55497bd9739f53ff46e56339eddd92a100dbdda5de52d247a2b86225553568', 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', '5c55497bd9739f53ff46e56339eddd92a100dbdda5de52d247a2b86225553568', '5c55497bd9739f53ff46e56339eddd92a100dbdda5de52d247a2b86225553568', NULL, 'فسجد الملئكه كلهم اجمعون', 23, 46, 183, 1, 6, 457, false, NULL),
    (4044, 'tanzil-uthmani-v1.1', 38, 74, 'إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', '671d72b5a0c8e51fd63d72d7d987f5cca60a1c4059a185265839a20d6fb9dd42', 'إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', '671d72b5a0c8e51fd63d72d7d987f5cca60a1c4059a185265839a20d6fb9dd42', '671d72b5a0c8e51fd63d72d7d987f5cca60a1c4059a185265839a20d6fb9dd42', NULL, 'الا ابليس استكبر وكان من الكفرين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4045, 'tanzil-uthmani-v1.1', 38, 75, 'قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَىَّ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ ٱلْعَالِينَ', '3436477850536f1929699ffb289280d0cc808bcc54d0347b5b31bae94f392bdc', 'قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَىَّ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ ٱلْعَالِينَ', '3436477850536f1929699ffb289280d0cc808bcc54d0347b5b31bae94f392bdc', '3436477850536f1929699ffb289280d0cc808bcc54d0347b5b31bae94f392bdc', NULL, 'قال يابليس ما منعك ان تسجد لما خلقت بيدي استكبرت ام كنت من العالين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4046, 'tanzil-uthmani-v1.1', 38, 76, 'قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', '3139463dc907f5a74b2bffc870c89a1e90702d286cb6f0e66df340fe308f37fb', 'قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ', '3139463dc907f5a74b2bffc870c89a1e90702d286cb6f0e66df340fe308f37fb', '3139463dc907f5a74b2bffc870c89a1e90702d286cb6f0e66df340fe308f37fb', NULL, 'قال انا خير منه خلقتني من نار وخلقته من طين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4047, 'tanzil-uthmani-v1.1', 38, 77, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', '9a4202650c3884442863a1c0aea00c57ac3070003d059ec86137c37de8dae673', 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ', '9a4202650c3884442863a1c0aea00c57ac3070003d059ec86137c37de8dae673', '9a4202650c3884442863a1c0aea00c57ac3070003d059ec86137c37de8dae673', NULL, 'قال فاخرج منها فانك رجيم', 23, 46, 183, 1, 6, 457, false, NULL),
    (4048, 'tanzil-uthmani-v1.1', 38, 78, 'وَإِنَّ عَلَيْكَ لَعْنَتِىٓ إِلَىٰ يَوْمِ ٱلدِّينِ', 'e7ce584ad48893cc810337810bc3bf97518a5e229f80c238d95224126a80e976', 'وَإِنَّ عَلَيْكَ لَعْنَتِىٓ إِلَىٰ يَوْمِ ٱلدِّينِ', 'e7ce584ad48893cc810337810bc3bf97518a5e229f80c238d95224126a80e976', 'e7ce584ad48893cc810337810bc3bf97518a5e229f80c238d95224126a80e976', NULL, 'وان عليك لعنتي الي يوم الدين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4049, 'tanzil-uthmani-v1.1', 38, 79, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', '9ebcefd8b3b39bdec6a892b34a3916be46b8c104ca57763047f7624364879c5e', 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', '9ebcefd8b3b39bdec6a892b34a3916be46b8c104ca57763047f7624364879c5e', '9ebcefd8b3b39bdec6a892b34a3916be46b8c104ca57763047f7624364879c5e', NULL, 'قال رب فانظرني الي يوم يبعثون', 23, 46, 183, 1, 6, 457, false, NULL),
    (4050, 'tanzil-uthmani-v1.1', 38, 80, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', '08a8475c9751346b59c2e105a0bb97077c6edb08f6b14010a2e80ec6bc363bc8', 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', '08a8475c9751346b59c2e105a0bb97077c6edb08f6b14010a2e80ec6bc363bc8', '08a8475c9751346b59c2e105a0bb97077c6edb08f6b14010a2e80ec6bc363bc8', NULL, 'قال فانك من المنظرين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4051, 'tanzil-uthmani-v1.1', 38, 81, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'ed860cfd3749d7c7ba6f1cff8c99eb8f4fd2d83cde0bb829de851da2bdc743d9', 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 'ed860cfd3749d7c7ba6f1cff8c99eb8f4fd2d83cde0bb829de851da2bdc743d9', 'ed860cfd3749d7c7ba6f1cff8c99eb8f4fd2d83cde0bb829de851da2bdc743d9', NULL, 'الي يوم الوقت المعلوم', 23, 46, 183, 1, 6, 457, false, NULL),
    (4052, 'tanzil-uthmani-v1.1', 38, 82, 'قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'ae443406ebd6666fe510ac38a3d9be2c95d14f896e6a0ceedd678f9bf7f4b8f9', 'قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 'ae443406ebd6666fe510ac38a3d9be2c95d14f896e6a0ceedd678f9bf7f4b8f9', 'ae443406ebd6666fe510ac38a3d9be2c95d14f896e6a0ceedd678f9bf7f4b8f9', NULL, 'قال فبعزتك لاغوينهم اجمعين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4053, 'tanzil-uthmani-v1.1', 38, 83, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', '06a49c97581cb3cf3e595bbcf6b17f1ea11e0ca8d242b3f6a5a8e37129f39631', 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', '06a49c97581cb3cf3e595bbcf6b17f1ea11e0ca8d242b3f6a5a8e37129f39631', '06a49c97581cb3cf3e595bbcf6b17f1ea11e0ca8d242b3f6a5a8e37129f39631', NULL, 'الا عبادك منهم المخلصين', 23, 46, 183, 1, 6, 457, false, NULL),
    (4054, 'tanzil-uthmani-v1.1', 38, 84, 'قَالَ فَٱلْحَقُّ وَٱلْحَقَّ أَقُولُ', '40eb9577b8c0f500f9f138282f8de3bd26052d85ec28f3ef9d208cb7648ebe95', 'قَالَ فَٱلْحَقُّ وَٱلْحَقَّ أَقُولُ', '40eb9577b8c0f500f9f138282f8de3bd26052d85ec28f3ef9d208cb7648ebe95', '40eb9577b8c0f500f9f138282f8de3bd26052d85ec28f3ef9d208cb7648ebe95', NULL, 'قال فالحق والحق اقول', 23, 46, 183, 1, 6, 458, false, NULL),
    (4055, 'tanzil-uthmani-v1.1', 38, 85, 'لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ', '095dce71b95814958715d1c049574d56690cca5ffd87c91546260e1a5fab4c9d', 'لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ', '095dce71b95814958715d1c049574d56690cca5ffd87c91546260e1a5fab4c9d', '095dce71b95814958715d1c049574d56690cca5ffd87c91546260e1a5fab4c9d', NULL, 'لاملان جهنم منك وممن تبعك منهم اجمعين', 23, 46, 183, 1, 6, 458, false, NULL),
    (4056, 'tanzil-uthmani-v1.1', 38, 86, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ', '8b07077e34c9a7fd47aece4aed75ddf2827795d10b0569ed16b5a1af7381575f', 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ', '8b07077e34c9a7fd47aece4aed75ddf2827795d10b0569ed16b5a1af7381575f', '8b07077e34c9a7fd47aece4aed75ddf2827795d10b0569ed16b5a1af7381575f', NULL, 'قل ما اسلكم عليه من اجر وما انا من المتكلفين', 23, 46, 183, 1, 6, 458, false, NULL),
    (4057, 'tanzil-uthmani-v1.1', 38, 87, 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'b5e45234bbf85e0359413d93aa589b3293f9876a16127477fc50955a5dfff702', 'إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ', 'b5e45234bbf85e0359413d93aa589b3293f9876a16127477fc50955a5dfff702', 'b5e45234bbf85e0359413d93aa589b3293f9876a16127477fc50955a5dfff702', NULL, 'ان هو الا ذكر للعلمين', 23, 46, 183, 1, 6, 458, false, NULL),
    (4058, 'tanzil-uthmani-v1.1', 38, 88, 'وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينٍۭ', '95506ea0e03ffa9fa9418034e268068b20cf7726143f75d3ae9db5f0d62a2571', 'وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينٍۭ', '95506ea0e03ffa9fa9418034e268068b20cf7726143f75d3ae9db5f0d62a2571', '95506ea0e03ffa9fa9418034e268068b20cf7726143f75d3ae9db5f0d62a2571', NULL, 'ولتعلمن نباه بعد حين', 23, 46, 183, 1, 6, 458, false, NULL),
    (4059, 'tanzil-uthmani-v1.1', 39, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '67e38f71be311afd98ed9198e7ad2157599273fdcd2c0859b0a51d213352cb27', 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '630417016fb5d33747dc7fe4937d3268572dc1e26350870e4cc108fcc240cae4', '630417016fb5d33747dc7fe4937d3268572dc1e26350870e4cc108fcc240cae4', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'تنزيل الكتب من الله العزيز الحكيم', 23, 46, 183, 1, 6, 458, false, NULL),
    (4060, 'tanzil-uthmani-v1.1', 39, 2, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ فَٱعْبُدِ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', '26014e3b0fe2a74f710a10fc65968c8e0974b15d4e5c103bda9d372410421d3b', 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ فَٱعْبُدِ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', '26014e3b0fe2a74f710a10fc65968c8e0974b15d4e5c103bda9d372410421d3b', '26014e3b0fe2a74f710a10fc65968c8e0974b15d4e5c103bda9d372410421d3b', NULL, 'انا انزلنا اليك الكتب بالحق فاعبد الله مخلصا له الدين', 23, 46, 183, 1, 6, 458, false, NULL),
    (4061, 'tanzil-uthmani-v1.1', 39, 3, 'أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌ كَفَّارٌ', '47c8109cd7d192219ea10b08b17ab6207a7eb1ef8936bea9ca639e3a7297ce13', 'أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌ كَفَّارٌ', '47c8109cd7d192219ea10b08b17ab6207a7eb1ef8936bea9ca639e3a7297ce13', '47c8109cd7d192219ea10b08b17ab6207a7eb1ef8936bea9ca639e3a7297ce13', NULL, 'الا لله الدين الخالص والذين اتخذوا من دونه اولياء ما نعبدهم الا ليقربونا الي الله زلفي ان الله يحكم بينهم في ما هم فيه يختلفون ان الله لا يهدي من هو كذب كفار', 23, 46, 183, 1, 6, 458, false, NULL),
    (4062, 'tanzil-uthmani-v1.1', 39, 4, 'لَّوْ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدًا لَّٱصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ سُبْحَٰنَهُۥ هُوَ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'ddbd310b909d289cf3156a3affabe1c65b00af7433154b300e40cc3ba196c110', 'لَّوْ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدًا لَّٱصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ سُبْحَٰنَهُۥ هُوَ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 'ddbd310b909d289cf3156a3affabe1c65b00af7433154b300e40cc3ba196c110', 'ddbd310b909d289cf3156a3affabe1c65b00af7433154b300e40cc3ba196c110', NULL, 'لو اراد الله ان يتخذ ولدا لاصطفي مما يخلق ما يشاء سبحنه هو الله الوحد القهار', 23, 46, 183, 1, 6, 458, false, NULL),
    (4063, 'tanzil-uthmani-v1.1', 39, 5, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ يُكَوِّرُ ٱلَّيْلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى أَلَا هُوَ ٱلْعَزِيزُ ٱلْغَفَّٰرُ', 'dd48acb7d1c23e8a9a8ba53054de12ce8d2ec492d4e622acf7d40ed280c054b7', 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ يُكَوِّرُ ٱلَّيْلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى أَلَا هُوَ ٱلْعَزِيزُ ٱلْغَفَّٰرُ', 'dd48acb7d1c23e8a9a8ba53054de12ce8d2ec492d4e622acf7d40ed280c054b7', 'dd48acb7d1c23e8a9a8ba53054de12ce8d2ec492d4e622acf7d40ed280c054b7', NULL, 'خلق السموت والارض بالحق يكور اليل علي النهار ويكور النهار علي اليل وسخر الشمس والقمر كل يجري لاجل مسمي الا هو العزيز الغفر', 23, 46, 183, 1, 6, 458, false, NULL),
    (4064, 'tanzil-uthmani-v1.1', 39, 6, 'خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلْأَنْعَٰمِ ثَمَٰنِيَةَ أَزْوَٰجٍ يَخْلُقُكُمْ فِى بُطُونِ أُمَّهَٰتِكُمْ خَلْقًا مِّنۢ بَعْدِ خَلْقٍ فِى ظُلُمَٰتٍ ثَلَٰثٍ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ لَآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُصْرَفُونَ', '0264d35d2a0a25d55570afdc94da8fb25524bd6847bb4160273f174754ccf993', 'خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلْأَنْعَٰمِ ثَمَٰنِيَةَ أَزْوَٰجٍ يَخْلُقُكُمْ فِى بُطُونِ أُمَّهَٰتِكُمْ خَلْقًا مِّنۢ بَعْدِ خَلْقٍ فِى ظُلُمَٰتٍ ثَلَٰثٍ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ لَآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُصْرَفُونَ', '0264d35d2a0a25d55570afdc94da8fb25524bd6847bb4160273f174754ccf993', '0264d35d2a0a25d55570afdc94da8fb25524bd6847bb4160273f174754ccf993', NULL, 'خلقكم من نفس وحده ثم جعل منها زوجها وانزل لكم من الانعم ثمنيه ازوج يخلقكم في بطون امهتكم خلقا من بعد خلق في ظلمت ثلث ذلكم الله ربكم له الملك لا اله الا هو فاني تصرفون', 23, 46, 183, 1, 6, 459, false, NULL),
    (4065, 'tanzil-uthmani-v1.1', 39, 7, 'إِن تَكْفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنكُمْ وَلَا يَرْضَىٰ لِعِبَادِهِ ٱلْكُفْرَ وَإِن تَشْكُرُوا۟ يَرْضَهُ لَكُمْ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '3f8086848f7bead36771414c02d3480429983e9a5d84f7b4c1c1b4d12555a7b6', 'إِن تَكْفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنكُمْ وَلَا يَرْضَىٰ لِعِبَادِهِ ٱلْكُفْرَ وَإِن تَشْكُرُوا۟ يَرْضَهُ لَكُمْ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '3f8086848f7bead36771414c02d3480429983e9a5d84f7b4c1c1b4d12555a7b6', '3f8086848f7bead36771414c02d3480429983e9a5d84f7b4c1c1b4d12555a7b6', NULL, 'ان تكفروا فان الله غني عنكم ولا يرضي لعباده الكفر وان تشكروا يرضه لكم ولا تزر وازره وزر اخري ثم الي ربكم مرجعكم فينبئكم بما كنتم تعملون انه عليم بذات الصدور', 23, 46, 183, 1, 6, 459, false, NULL),
    (4066, 'tanzil-uthmani-v1.1', 39, 8, 'وَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّ دَعَا رَبَّهُۥ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةً مِّنْهُ نَسِىَ مَا كَانَ يَدْعُوٓا۟ إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلَّهِ أَندَادًا لِّيُضِلَّ عَن سَبِيلِهِۦ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا إِنَّكَ مِنْ أَصْحَٰبِ ٱلنَّارِ', '50266737071b89764d96a8b64dcd684db656bf832331f08a810329b3c41786aa', 'وَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّ دَعَا رَبَّهُۥ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةً مِّنْهُ نَسِىَ مَا كَانَ يَدْعُوٓا۟ إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلَّهِ أَندَادًا لِّيُضِلَّ عَن سَبِيلِهِۦ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا إِنَّكَ مِنْ أَصْحَٰبِ ٱلنَّارِ', '50266737071b89764d96a8b64dcd684db656bf832331f08a810329b3c41786aa', '50266737071b89764d96a8b64dcd684db656bf832331f08a810329b3c41786aa', NULL, 'واذا مس الانسن ضر دعا ربه منيبا اليه ثم اذا خوله نعمه منه نسي ما كان يدعوا اليه من قبل وجعل لله اندادا ليضل عن سبيله قل تمتع بكفرك قليلا انك من اصحب النار', 23, 46, 184, 1, 6, 459, false, NULL),
    (4067, 'tanzil-uthmani-v1.1', 39, 9, 'أَمَّنْ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيْلِ سَاجِدًا وَقَآئِمًا يَحْذَرُ ٱلْـَٔاخِرَةَ وَيَرْجُوا۟ رَحْمَةَ رَبِّهِۦ قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '4cc02797d42203d014b96958742f68c41cb4db83b04996f8a46235d1e2014ea4', 'أَمَّنْ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيْلِ سَاجِدًا وَقَآئِمًا يَحْذَرُ ٱلْـَٔاخِرَةَ وَيَرْجُوا۟ رَحْمَةَ رَبِّهِۦ قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '4cc02797d42203d014b96958742f68c41cb4db83b04996f8a46235d1e2014ea4', '4cc02797d42203d014b96958742f68c41cb4db83b04996f8a46235d1e2014ea4', NULL, 'امن هو قنت ءاناء اليل ساجدا وقائما يحذر الاخره ويرجوا رحمه ربه قل هل يستوي الذين يعلمون والذين لا يعلمون انما يتذكر اولوا الالبب', 23, 46, 184, 1, 6, 459, false, NULL),
    (4068, 'tanzil-uthmani-v1.1', 39, 10, 'قُلْ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمْ لِلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌ وَأَرْضُ ٱللَّهِ وَٰسِعَةٌ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍ', '5f2bc1fad3d43f128cb40dfe94ac6e9e892cf43f37c8a7443b6ee42bdadbd389', 'قُلْ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمْ لِلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌ وَأَرْضُ ٱللَّهِ وَٰسِعَةٌ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍ', '5f2bc1fad3d43f128cb40dfe94ac6e9e892cf43f37c8a7443b6ee42bdadbd389', '5f2bc1fad3d43f128cb40dfe94ac6e9e892cf43f37c8a7443b6ee42bdadbd389', NULL, 'قل يعباد الذين ءامنوا اتقوا ربكم للذين احسنوا في هذه الدنيا حسنه وارض الله وسعه انما يوفي الصبرون اجرهم بغير حساب', 23, 46, 184, 1, 6, 459, false, NULL),
    (4069, 'tanzil-uthmani-v1.1', 39, 11, 'قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', '92f9fe5acf6722d1ab3ff318c1e5cf30c859417a0e42399b0c6085edee56b409', 'قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ', '92f9fe5acf6722d1ab3ff318c1e5cf30c859417a0e42399b0c6085edee56b409', '92f9fe5acf6722d1ab3ff318c1e5cf30c859417a0e42399b0c6085edee56b409', NULL, 'قل اني امرت ان اعبد الله مخلصا له الدين', 23, 46, 184, 1, 6, 460, false, NULL),
    (4070, 'tanzil-uthmani-v1.1', 39, 12, 'وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ ٱلْمُسْلِمِينَ', 'a47c3f32cd9454d7d5b6c40a5a15ed085dd137fbfa75dca39db95b40f9ac0270', 'وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ ٱلْمُسْلِمِينَ', 'a47c3f32cd9454d7d5b6c40a5a15ed085dd137fbfa75dca39db95b40f9ac0270', 'a47c3f32cd9454d7d5b6c40a5a15ed085dd137fbfa75dca39db95b40f9ac0270', NULL, 'وامرت لان اكون اول المسلمين', 23, 46, 184, 1, 6, 460, false, NULL),
    (4071, 'tanzil-uthmani-v1.1', 39, 13, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'f06309ac89f947b69e5580500c3c2361ffa81838839304310e2fea2130c7f193', 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ', 'f06309ac89f947b69e5580500c3c2361ffa81838839304310e2fea2130c7f193', 'f06309ac89f947b69e5580500c3c2361ffa81838839304310e2fea2130c7f193', NULL, 'قل اني اخاف ان عصيت ربي عذاب يوم عظيم', 23, 46, 184, 1, 6, 460, false, NULL),
    (4072, 'tanzil-uthmani-v1.1', 39, 14, 'قُلِ ٱللَّهَ أَعْبُدُ مُخْلِصًا لَّهُۥ دِينِى', 'b7d2be3d7becd71b1fcba9215586641128ae9d9fae785743350c16216354f739', 'قُلِ ٱللَّهَ أَعْبُدُ مُخْلِصًا لَّهُۥ دِينِى', 'b7d2be3d7becd71b1fcba9215586641128ae9d9fae785743350c16216354f739', 'b7d2be3d7becd71b1fcba9215586641128ae9d9fae785743350c16216354f739', NULL, 'قل الله اعبد مخلصا له ديني', 23, 46, 184, 1, 6, 460, false, NULL),
    (4073, 'tanzil-uthmani-v1.1', 39, 15, 'فَٱعْبُدُوا۟ مَا شِئْتُم مِّن دُونِهِۦ قُلْ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ أَلَا ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', '309f4f2019a13a13ff78c68fd0925f665e335b5150601db3466fcd27123912b4', 'فَٱعْبُدُوا۟ مَا شِئْتُم مِّن دُونِهِۦ قُلْ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ أَلَا ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', '309f4f2019a13a13ff78c68fd0925f665e335b5150601db3466fcd27123912b4', '309f4f2019a13a13ff78c68fd0925f665e335b5150601db3466fcd27123912b4', NULL, 'فاعبدوا ما شئتم من دونه قل ان الخسرين الذين خسروا انفسهم واهليهم يوم القيمه الا ذلك هو الخسران المبين', 23, 46, 184, 1, 6, 460, false, NULL),
    (4074, 'tanzil-uthmani-v1.1', 39, 16, 'لَهُم مِّن فَوْقِهِمْ ظُلَلٌ مِّنَ ٱلنَّارِ وَمِن تَحْتِهِمْ ظُلَلٌ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥ يَٰعِبَادِ فَٱتَّقُونِ', '6e61c770f369a1a72386e51c964d44fd6cbd257f028d5700c799915d33cef73b', 'لَهُم مِّن فَوْقِهِمْ ظُلَلٌ مِّنَ ٱلنَّارِ وَمِن تَحْتِهِمْ ظُلَلٌ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥ يَٰعِبَادِ فَٱتَّقُونِ', '6e61c770f369a1a72386e51c964d44fd6cbd257f028d5700c799915d33cef73b', '6e61c770f369a1a72386e51c964d44fd6cbd257f028d5700c799915d33cef73b', NULL, 'لهم من فوقهم ظلل من النار ومن تحتهم ظلل ذلك يخوف الله به عباده يعباد فاتقون', 23, 46, 184, 1, 6, 460, false, NULL),
    (4075, 'tanzil-uthmani-v1.1', 39, 17, 'وَٱلَّذِينَ ٱجْتَنَبُوا۟ ٱلطَّٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا۟ إِلَى ٱللَّهِ لَهُمُ ٱلْبُشْرَىٰ فَبَشِّرْ عِبَادِ', 'fa3e633645532acc26a4ecbddb850910612383f9a8895977b15f9da41208b23c', 'وَٱلَّذِينَ ٱجْتَنَبُوا۟ ٱلطَّٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا۟ إِلَى ٱللَّهِ لَهُمُ ٱلْبُشْرَىٰ فَبَشِّرْ عِبَادِ', 'fa3e633645532acc26a4ecbddb850910612383f9a8895977b15f9da41208b23c', 'fa3e633645532acc26a4ecbddb850910612383f9a8895977b15f9da41208b23c', NULL, 'والذين اجتنبوا الطغوت ان يعبدوها وانابوا الي الله لهم البشري فبشر عباد', 23, 46, 184, 1, 6, 460, false, NULL),
    (4076, 'tanzil-uthmani-v1.1', 39, 18, 'ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ وَأُو۟لَٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '39d4ced09019f1a94802cde06c307e06ae16e3453db1171198a9db868ebe3879', 'ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ وَأُو۟لَٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', '39d4ced09019f1a94802cde06c307e06ae16e3453db1171198a9db868ebe3879', '39d4ced09019f1a94802cde06c307e06ae16e3453db1171198a9db868ebe3879', NULL, 'الذين يستمعون القول فيتبعون احسنه اولئك الذين هديهم الله واولئك هم اولوا الالبب', 23, 46, 184, 1, 6, 460, false, NULL),
    (4077, 'tanzil-uthmani-v1.1', 39, 19, 'أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ ٱلْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِى ٱلنَّارِ', 'da1a9736dd69fe0fc8c4e53cc4557b3eebd53a9f237b6696e9525d7f4c10ad9c', 'أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ ٱلْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِى ٱلنَّارِ', 'da1a9736dd69fe0fc8c4e53cc4557b3eebd53a9f237b6696e9525d7f4c10ad9c', 'da1a9736dd69fe0fc8c4e53cc4557b3eebd53a9f237b6696e9525d7f4c10ad9c', NULL, 'افمن حق عليه كلمه العذاب افانت تنقذ من في النار', 23, 46, 184, 1, 6, 460, false, NULL),
    (4078, 'tanzil-uthmani-v1.1', 39, 20, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ غُرَفٌ مِّن فَوْقِهَا غُرَفٌ مَّبْنِيَّةٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَعْدَ ٱللَّهِ لَا يُخْلِفُ ٱللَّهُ ٱلْمِيعَادَ', '2de3972922a4c8b2b1670e767a0cf6bfa6bd3584130145f593888d636c54e9ae', 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ غُرَفٌ مِّن فَوْقِهَا غُرَفٌ مَّبْنِيَّةٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَعْدَ ٱللَّهِ لَا يُخْلِفُ ٱللَّهُ ٱلْمِيعَادَ', '2de3972922a4c8b2b1670e767a0cf6bfa6bd3584130145f593888d636c54e9ae', '2de3972922a4c8b2b1670e767a0cf6bfa6bd3584130145f593888d636c54e9ae', NULL, 'لكن الذين اتقوا ربهم لهم غرف من فوقها غرف مبنيه تجري من تحتها الانهر وعد الله لا يخلف الله الميعاد', 23, 46, 184, 1, 6, 460, false, NULL),
    (4079, 'tanzil-uthmani-v1.1', 39, 21, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَلَكَهُۥ يَنَٰبِيعَ فِى ٱلْأَرْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعًا مُّخْتَلِفًا أَلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَجْعَلُهُۥ حُطَٰمًا إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'f1b0af4a24107b129a7daed2777aae85ec04c2018790a50dd89eb991fb402f55', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَلَكَهُۥ يَنَٰبِيعَ فِى ٱلْأَرْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعًا مُّخْتَلِفًا أَلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَجْعَلُهُۥ حُطَٰمًا إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 'f1b0af4a24107b129a7daed2777aae85ec04c2018790a50dd89eb991fb402f55', 'f1b0af4a24107b129a7daed2777aae85ec04c2018790a50dd89eb991fb402f55', NULL, 'الم تر ان الله انزل من السماء ماء فسلكه ينبيع في الارض ثم يخرج به زرعا مختلفا الونه ثم يهيج فتريه مصفرا ثم يجعله حطما ان في ذلك لذكري لاولي الالبب', 23, 46, 184, 1, 6, 460, false, NULL),
    (4080, 'tanzil-uthmani-v1.1', 39, 22, 'أَفَمَن شَرَحَ ٱللَّهُ صَدْرَهُۥ لِلْإِسْلَٰمِ فَهُوَ عَلَىٰ نُورٍ مِّن رَّبِّهِۦ فَوَيْلٌ لِّلْقَٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ ٱللَّهِ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ', '291324e1b3b4e9481208db51ea23bbf6f1ebd116d9606f0c4f00b769a378683f', 'أَفَمَن شَرَحَ ٱللَّهُ صَدْرَهُۥ لِلْإِسْلَٰمِ فَهُوَ عَلَىٰ نُورٍ مِّن رَّبِّهِۦ فَوَيْلٌ لِّلْقَٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ ٱللَّهِ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ', '291324e1b3b4e9481208db51ea23bbf6f1ebd116d9606f0c4f00b769a378683f', '291324e1b3b4e9481208db51ea23bbf6f1ebd116d9606f0c4f00b769a378683f', NULL, 'افمن شرح الله صدره للاسلم فهو علي نور من ربه فويل للقسيه قلوبهم من ذكر الله اولئك في ضلل مبين', 23, 46, 184, 1, 6, 461, false, NULL),
    (4081, 'tanzil-uthmani-v1.1', 39, 23, 'ٱللَّهُ نَزَّلَ أَحْسَنَ ٱلْحَدِيثِ كِتَٰبًا مُّتَشَٰبِهًا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ ٱللَّهِ ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '56fd86f730cce380ef4e5aef0c0ee8d25235a4e716a5791f9a57b4ed5017523f', 'ٱللَّهُ نَزَّلَ أَحْسَنَ ٱلْحَدِيثِ كِتَٰبًا مُّتَشَٰبِهًا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ ٱللَّهِ ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '56fd86f730cce380ef4e5aef0c0ee8d25235a4e716a5791f9a57b4ed5017523f', '56fd86f730cce380ef4e5aef0c0ee8d25235a4e716a5791f9a57b4ed5017523f', NULL, 'الله نزل احسن الحديث كتبا متشبها مثاني تقشعر منه جلود الذين يخشون ربهم ثم تلين جلودهم وقلوبهم الي ذكر الله ذلك هدي الله يهدي به من يشاء ومن يضلل الله فما له من هاد', 23, 46, 184, 1, 6, 461, false, NULL),
    (4082, 'tanzil-uthmani-v1.1', 39, 24, 'أَفَمَن يَتَّقِى بِوَجْهِهِۦ سُوٓءَ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُوا۟ مَا كُنتُمْ تَكْسِبُونَ', 'c502bafbe7cdc81b01043ff76e93a09d6c2c058eb0dbc337d83771a77c279c83', 'أَفَمَن يَتَّقِى بِوَجْهِهِۦ سُوٓءَ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُوا۟ مَا كُنتُمْ تَكْسِبُونَ', 'c502bafbe7cdc81b01043ff76e93a09d6c2c058eb0dbc337d83771a77c279c83', 'c502bafbe7cdc81b01043ff76e93a09d6c2c058eb0dbc337d83771a77c279c83', NULL, 'افمن يتقي بوجهه سوء العذاب يوم القيمه وقيل للظلمين ذوقوا ما كنتم تكسبون', 23, 46, 184, 1, 6, 461, false, NULL),
    (4083, 'tanzil-uthmani-v1.1', 39, 25, 'كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', '0fc0b2329764d3eea252eebb8dbddefe09a06d39656e9db9e6b65991c502e883', 'كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', '0fc0b2329764d3eea252eebb8dbddefe09a06d39656e9db9e6b65991c502e883', '0fc0b2329764d3eea252eebb8dbddefe09a06d39656e9db9e6b65991c502e883', NULL, 'كذب الذين من قبلهم فاتيهم العذاب من حيث لا يشعرون', 23, 46, 184, 1, 6, 461, false, NULL),
    (4084, 'tanzil-uthmani-v1.1', 39, 26, 'فَأَذَاقَهُمُ ٱللَّهُ ٱلْخِزْىَ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', 'b65af6ea5c03815b18471c3af3a6a82eba565a10f5cb289c610b9aa3d8137f3c', 'فَأَذَاقَهُمُ ٱللَّهُ ٱلْخِزْىَ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ', 'b65af6ea5c03815b18471c3af3a6a82eba565a10f5cb289c610b9aa3d8137f3c', 'b65af6ea5c03815b18471c3af3a6a82eba565a10f5cb289c610b9aa3d8137f3c', NULL, 'فاذاقهم الله الخزي في الحيوه الدنيا ولعذاب الاخره اكبر لو كانوا يعلمون', 23, 46, 184, 1, 6, 461, false, NULL),
    (4085, 'tanzil-uthmani-v1.1', 39, 27, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ لَّعَلَّهُمْ يَتَذَكَّرُونَ', '5d41582781e3fda1e74d5df7c3175dbe95acb8cb2b0d126d87c12879d3c19075', 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ لَّعَلَّهُمْ يَتَذَكَّرُونَ', '5d41582781e3fda1e74d5df7c3175dbe95acb8cb2b0d126d87c12879d3c19075', '5d41582781e3fda1e74d5df7c3175dbe95acb8cb2b0d126d87c12879d3c19075', NULL, 'ولقد ضربنا للناس في هذا القرءان من كل مثل لعلهم يتذكرون', 23, 46, 184, 1, 6, 461, false, NULL),
    (4086, 'tanzil-uthmani-v1.1', 39, 28, 'قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَجٍ لَّعَلَّهُمْ يَتَّقُونَ', '5f7d4c7eb255c9ead708ab4dd3a4b5bc36f863673ea5b6a86c354aadc0d7c0d5', 'قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَجٍ لَّعَلَّهُمْ يَتَّقُونَ', '5f7d4c7eb255c9ead708ab4dd3a4b5bc36f863673ea5b6a86c354aadc0d7c0d5', '5f7d4c7eb255c9ead708ab4dd3a4b5bc36f863673ea5b6a86c354aadc0d7c0d5', NULL, 'قرءانا عربيا غير ذي عوج لعلهم يتقون', 23, 46, 184, 1, 6, 461, false, NULL),
    (4087, 'tanzil-uthmani-v1.1', 39, 29, 'ضَرَبَ ٱللَّهُ مَثَلًا رَّجُلًا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلًا سَلَمًا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '19231d02afc1aa39fe494b226f5eea85779b1975f74c70fbd1a91aa950f63d47', 'ضَرَبَ ٱللَّهُ مَثَلًا رَّجُلًا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلًا سَلَمًا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', '19231d02afc1aa39fe494b226f5eea85779b1975f74c70fbd1a91aa950f63d47', '19231d02afc1aa39fe494b226f5eea85779b1975f74c70fbd1a91aa950f63d47', NULL, 'ضرب الله مثلا رجلا فيه شركاء متشكسون ورجلا سلما لرجل هل يستويان مثلا الحمد لله بل اكثرهم لا يعلمون', 23, 46, 184, 1, 6, 461, false, NULL),
    (4088, 'tanzil-uthmani-v1.1', 39, 30, 'إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ', 'b342576f5408e2cfcab09d534fc3720b23c1f834b0e0898ee2a81aa236b2e303', 'إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ', 'b342576f5408e2cfcab09d534fc3720b23c1f834b0e0898ee2a81aa236b2e303', 'b342576f5408e2cfcab09d534fc3720b23c1f834b0e0898ee2a81aa236b2e303', NULL, 'انك ميت وانهم ميتون', 23, 46, 184, 1, 6, 461, false, NULL),
    (4089, 'tanzil-uthmani-v1.1', 39, 31, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ', '33475a146a76b04cff2d06625caaaec2ef5d782fc607dcd3bd0565a1731cff64', 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ', '33475a146a76b04cff2d06625caaaec2ef5d782fc607dcd3bd0565a1731cff64', '33475a146a76b04cff2d06625caaaec2ef5d782fc607dcd3bd0565a1731cff64', NULL, 'ثم انكم يوم القيمه عند ربكم تختصمون', 23, 46, 184, 1, 6, 461, false, NULL),
    (4090, 'tanzil-uthmani-v1.1', 39, 32, 'فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدْقِ إِذْ جَآءَهُۥٓ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ', 'a020c6213d9f2033a823b66bee0a0cbd33146767bd7d7ef7bc6820f9db109452', 'فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدْقِ إِذْ جَآءَهُۥٓ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ', 'a020c6213d9f2033a823b66bee0a0cbd33146767bd7d7ef7bc6820f9db109452', 'a020c6213d9f2033a823b66bee0a0cbd33146767bd7d7ef7bc6820f9db109452', NULL, 'فمن اظلم ممن كذب علي الله وكذب بالصدق اذ جاءه اليس في جهنم مثوي للكفرين', 24, 47, 185, 1, 6, 462, false, NULL),
    (4091, 'tanzil-uthmani-v1.1', 39, 33, 'وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'e17804ca605630e4c426e9d84a265a622e93955b820de70e25ce80be42fad7cd', 'وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 'e17804ca605630e4c426e9d84a265a622e93955b820de70e25ce80be42fad7cd', 'e17804ca605630e4c426e9d84a265a622e93955b820de70e25ce80be42fad7cd', NULL, 'والذي جاء بالصدق وصدق به اولئك هم المتقون', 24, 47, 185, 1, 6, 462, false, NULL),
    (4092, 'tanzil-uthmani-v1.1', 39, 34, 'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', '21ab3e48fb7d7a430584df7fc71c32568f352521f658b4503981910821b170f4', 'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', '21ab3e48fb7d7a430584df7fc71c32568f352521f658b4503981910821b170f4', '21ab3e48fb7d7a430584df7fc71c32568f352521f658b4503981910821b170f4', NULL, 'لهم ما يشاءون عند ربهم ذلك جزاء المحسنين', 24, 47, 185, 1, 6, 462, false, NULL),
    (4093, 'tanzil-uthmani-v1.1', 39, 35, 'لِيُكَفِّرَ ٱللَّهُ عَنْهُمْ أَسْوَأَ ٱلَّذِى عَمِلُوا۟ وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'ce4e91535b229ddcd3dcf1e6eadf6ca4b568f3ccb5709159cdd75df76e923322', 'لِيُكَفِّرَ ٱللَّهُ عَنْهُمْ أَسْوَأَ ٱلَّذِى عَمِلُوا۟ وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 'ce4e91535b229ddcd3dcf1e6eadf6ca4b568f3ccb5709159cdd75df76e923322', 'ce4e91535b229ddcd3dcf1e6eadf6ca4b568f3ccb5709159cdd75df76e923322', NULL, 'ليكفر الله عنهم اسوا الذي عملوا ويجزيهم اجرهم باحسن الذي كانوا يعملون', 24, 47, 185, 1, 6, 462, false, NULL),
    (4094, 'tanzil-uthmani-v1.1', 39, 36, 'أَلَيْسَ ٱللَّهُ بِكَافٍ عَبْدَهُۥ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '9464b603a7f5d15c02bcc1812dd0b27026c2e5a324e0d66dc0be71c942f9d1d6', 'أَلَيْسَ ٱللَّهُ بِكَافٍ عَبْدَهُۥ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '9464b603a7f5d15c02bcc1812dd0b27026c2e5a324e0d66dc0be71c942f9d1d6', '9464b603a7f5d15c02bcc1812dd0b27026c2e5a324e0d66dc0be71c942f9d1d6', NULL, 'اليس الله بكاف عبده ويخوفونك بالذين من دونه ومن يضلل الله فما له من هاد', 24, 47, 185, 1, 6, 462, false, NULL),
    (4095, 'tanzil-uthmani-v1.1', 39, 37, 'وَمَن يَهْدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ أَلَيْسَ ٱللَّهُ بِعَزِيزٍ ذِى ٱنتِقَامٍ', 'af92c9f6b6f2d84c38da3adaf8ea39ff93cb27824047eb8c0d72f85c91b53e73', 'وَمَن يَهْدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ أَلَيْسَ ٱللَّهُ بِعَزِيزٍ ذِى ٱنتِقَامٍ', 'af92c9f6b6f2d84c38da3adaf8ea39ff93cb27824047eb8c0d72f85c91b53e73', 'af92c9f6b6f2d84c38da3adaf8ea39ff93cb27824047eb8c0d72f85c91b53e73', NULL, 'ومن يهد الله فما له من مضل اليس الله بعزيز ذي انتقام', 24, 47, 185, 1, 6, 462, false, NULL),
    (4096, 'tanzil-uthmani-v1.1', 39, 38, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ قُلْ أَفَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ إِنْ أَرَادَنِىَ ٱللَّهُ بِضُرٍّ هَلْ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَٰتُ رَحْمَتِهِۦ قُلْ حَسْبِىَ ٱللَّهُ عَلَيْهِ يَتَوَكَّلُ ٱلْمُتَوَكِّلُونَ', 'd26bf1ae6f4917d8db16b9402167583443db34947cc5b99d7524b481f1434e34', 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ قُلْ أَفَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ إِنْ أَرَادَنِىَ ٱللَّهُ بِضُرٍّ هَلْ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَٰتُ رَحْمَتِهِۦ قُلْ حَسْبِىَ ٱللَّهُ عَلَيْهِ يَتَوَكَّلُ ٱلْمُتَوَكِّلُونَ', 'd26bf1ae6f4917d8db16b9402167583443db34947cc5b99d7524b481f1434e34', 'd26bf1ae6f4917d8db16b9402167583443db34947cc5b99d7524b481f1434e34', NULL, 'ولئن سالتهم من خلق السموت والارض ليقولن الله قل افرءيتم ما تدعون من دون الله ان ارادني الله بضر هل هن كشفت ضره او ارادني برحمه هل هن ممسكت رحمته قل حسبي الله عليه يتوكل المتوكلون', 24, 47, 185, 1, 6, 462, false, NULL),
    (4097, 'tanzil-uthmani-v1.1', 39, 39, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ فَسَوْفَ تَعْلَمُونَ', '62a2575ce804416a721eb07ec430fbeb71a749bfb52a82b4ecdf09829e2c70f2', 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ فَسَوْفَ تَعْلَمُونَ', '62a2575ce804416a721eb07ec430fbeb71a749bfb52a82b4ecdf09829e2c70f2', '62a2575ce804416a721eb07ec430fbeb71a749bfb52a82b4ecdf09829e2c70f2', NULL, 'قل يقوم اعملوا علي مكانتكم اني عمل فسوف تعلمون', 24, 47, 185, 1, 6, 462, false, NULL),
    (4098, 'tanzil-uthmani-v1.1', 39, 40, 'مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', '97d3d2c12bb0db317391b1ed1a9ee65de879b8d10db37a7b96ebb82c4b65ecf2', 'مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ', '97d3d2c12bb0db317391b1ed1a9ee65de879b8d10db37a7b96ebb82c4b65ecf2', '97d3d2c12bb0db317391b1ed1a9ee65de879b8d10db37a7b96ebb82c4b65ecf2', NULL, 'من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم', 24, 47, 185, 1, 6, 462, false, NULL),
    (4099, 'tanzil-uthmani-v1.1', 39, 41, 'إِنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ لِلنَّاسِ بِٱلْحَقِّ فَمَنِ ٱهْتَدَىٰ فَلِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', '577d3742811aee6ed7172ec6805bd3a36162c764503c505f0405f13422c5245b', 'إِنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ لِلنَّاسِ بِٱلْحَقِّ فَمَنِ ٱهْتَدَىٰ فَلِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', '577d3742811aee6ed7172ec6805bd3a36162c764503c505f0405f13422c5245b', '577d3742811aee6ed7172ec6805bd3a36162c764503c505f0405f13422c5245b', NULL, 'انا انزلنا عليك الكتب للناس بالحق فمن اهتدي فلنفسه ومن ضل فانما يضل عليها وما انت عليهم بوكيل', 24, 47, 185, 1, 6, 463, false, NULL),
    (4100, 'tanzil-uthmani-v1.1', 39, 42, 'ٱللَّهُ يَتَوَفَّى ٱلْأَنفُسَ حِينَ مَوْتِهَا وَٱلَّتِى لَمْ تَمُتْ فِى مَنَامِهَا فَيُمْسِكُ ٱلَّتِى قَضَىٰ عَلَيْهَا ٱلْمَوْتَ وَيُرْسِلُ ٱلْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'ab5f8b8e00c91061896095689fd43daaccc389ccebc9ceaf1a292b6e4da8cc6f', 'ٱللَّهُ يَتَوَفَّى ٱلْأَنفُسَ حِينَ مَوْتِهَا وَٱلَّتِى لَمْ تَمُتْ فِى مَنَامِهَا فَيُمْسِكُ ٱلَّتِى قَضَىٰ عَلَيْهَا ٱلْمَوْتَ وَيُرْسِلُ ٱلْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', 'ab5f8b8e00c91061896095689fd43daaccc389ccebc9ceaf1a292b6e4da8cc6f', 'ab5f8b8e00c91061896095689fd43daaccc389ccebc9ceaf1a292b6e4da8cc6f', NULL, 'الله يتوفي الانفس حين موتها والتي لم تمت في منامها فيمسك التي قضي عليها الموت ويرسل الاخري الي اجل مسمي ان في ذلك لايت لقوم يتفكرون', 24, 47, 185, 1, 6, 463, false, NULL),
    (4101, 'tanzil-uthmani-v1.1', 39, 43, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَآءَ قُلْ أَوَلَوْ كَانُوا۟ لَا يَمْلِكُونَ شَيْـًٔا وَلَا يَعْقِلُونَ', '36ab26345970e527a8db8e7c15496c3bd5b7d7c60f3b2d51b32a80f2e10c2648', 'أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَآءَ قُلْ أَوَلَوْ كَانُوا۟ لَا يَمْلِكُونَ شَيْـًٔا وَلَا يَعْقِلُونَ', '36ab26345970e527a8db8e7c15496c3bd5b7d7c60f3b2d51b32a80f2e10c2648', '36ab26345970e527a8db8e7c15496c3bd5b7d7c60f3b2d51b32a80f2e10c2648', NULL, 'ام اتخذوا من دون الله شفعاء قل اولو كانوا لا يملكون شيا ولا يعقلون', 24, 47, 185, 1, 6, 463, false, NULL),
    (4102, 'tanzil-uthmani-v1.1', 39, 44, 'قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعًا لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ثُمَّ إِلَيْهِ تُرْجَعُونَ', '23247d5377aa1174cae2813d816be16d25a7c547338bde4eb2906920c965442d', 'قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعًا لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ثُمَّ إِلَيْهِ تُرْجَعُونَ', '23247d5377aa1174cae2813d816be16d25a7c547338bde4eb2906920c965442d', '23247d5377aa1174cae2813d816be16d25a7c547338bde4eb2906920c965442d', NULL, 'قل لله الشفعه جميعا له ملك السموت والارض ثم اليه ترجعون', 24, 47, 185, 1, 6, 463, false, NULL),
    (4103, 'tanzil-uthmani-v1.1', 39, 45, 'وَإِذَا ذُكِرَ ٱللَّهُ وَحْدَهُ ٱشْمَأَزَّتْ قُلُوبُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', '76edd1b29c2ca1efaf9dcac6a9b0f3d944c7e2bd4d940815765550ea3d37d8ad', 'وَإِذَا ذُكِرَ ٱللَّهُ وَحْدَهُ ٱشْمَأَزَّتْ قُلُوبُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', '76edd1b29c2ca1efaf9dcac6a9b0f3d944c7e2bd4d940815765550ea3d37d8ad', '76edd1b29c2ca1efaf9dcac6a9b0f3d944c7e2bd4d940815765550ea3d37d8ad', NULL, 'واذا ذكر الله وحده اشمازت قلوب الذين لا يؤمنون بالاخره واذا ذكر الذين من دونه اذا هم يستبشرون', 24, 47, 185, 1, 6, 463, false, NULL),
    (4104, 'tanzil-uthmani-v1.1', 39, 46, 'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ عَٰلِمَ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '38ec8074f3f970277df57199df6b4d97df355f88420c059634eda63aa1472971', 'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ عَٰلِمَ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '38ec8074f3f970277df57199df6b4d97df355f88420c059634eda63aa1472971', '38ec8074f3f970277df57199df6b4d97df355f88420c059634eda63aa1472971', NULL, 'قل اللهم فاطر السموت والارض علم الغيب والشهده انت تحكم بين عبادك في ما كانوا فيه يختلفون', 24, 47, 185, 1, 6, 463, false, NULL),
    (4105, 'tanzil-uthmani-v1.1', 39, 47, 'وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا۟ مَا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦ مِن سُوٓءِ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمْ يَكُونُوا۟ يَحْتَسِبُونَ', '5ff704312ad6f8e530e394a49edc2ba7415e09c0e9f618b3f23e7fb569d1109c', 'وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا۟ مَا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦ مِن سُوٓءِ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمْ يَكُونُوا۟ يَحْتَسِبُونَ', '5ff704312ad6f8e530e394a49edc2ba7415e09c0e9f618b3f23e7fb569d1109c', '5ff704312ad6f8e530e394a49edc2ba7415e09c0e9f618b3f23e7fb569d1109c', NULL, 'ولو ان للذين ظلموا ما في الارض جميعا ومثله معه لافتدوا به من سوء العذاب يوم القيمه وبدا لهم من الله ما لم يكونوا يحتسبون', 24, 47, 185, 1, 6, 463, false, NULL),
    (4106, 'tanzil-uthmani-v1.1', 39, 48, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '1cc85a505846c84220f01d9e3c733528431d7477fcea4881d8bd587d97254d3a', 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '1cc85a505846c84220f01d9e3c733528431d7477fcea4881d8bd587d97254d3a', '1cc85a505846c84220f01d9e3c733528431d7477fcea4881d8bd587d97254d3a', NULL, 'وبدا لهم سيات ما كسبوا وحاق بهم ما كانوا به يستهزءون', 24, 47, 185, 1, 6, 464, false, NULL),
    (4107, 'tanzil-uthmani-v1.1', 39, 49, 'فَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَٰهُ نِعْمَةً مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍۭ بَلْ هِىَ فِتْنَةٌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'e47f477f1a1a6e4ed0e8711ee2eca443417487fcee7634c14499976dd0b5021f', 'فَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَٰهُ نِعْمَةً مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍۭ بَلْ هِىَ فِتْنَةٌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 'e47f477f1a1a6e4ed0e8711ee2eca443417487fcee7634c14499976dd0b5021f', 'e47f477f1a1a6e4ed0e8711ee2eca443417487fcee7634c14499976dd0b5021f', NULL, 'فاذا مس الانسن ضر دعانا ثم اذا خولنه نعمه منا قال انما اوتيته علي علم بل هي فتنه ولكن اكثرهم لا يعلمون', 24, 47, 185, 1, 6, 464, false, NULL),
    (4108, 'tanzil-uthmani-v1.1', 39, 50, 'قَدْ قَالَهَا ٱلَّذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', '8a82e80d493f9527403f862ff07da36d252ed9ab5b577d32abe6ade9a4b5fe14', 'قَدْ قَالَهَا ٱلَّذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', '8a82e80d493f9527403f862ff07da36d252ed9ab5b577d32abe6ade9a4b5fe14', '8a82e80d493f9527403f862ff07da36d252ed9ab5b577d32abe6ade9a4b5fe14', NULL, 'قد قالها الذين من قبلهم فما اغني عنهم ما كانوا يكسبون', 24, 47, 185, 1, 6, 464, false, NULL),
    (4109, 'tanzil-uthmani-v1.1', 39, 51, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَٱلَّذِينَ ظَلَمُوا۟ مِنْ هَٰٓؤُلَآءِ سَيُصِيبُهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعْجِزِينَ', '5b166e5c5da18abde94604fe9944f2167587ad7c5086d1feb638ced3a66816a0', 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَٱلَّذِينَ ظَلَمُوا۟ مِنْ هَٰٓؤُلَآءِ سَيُصِيبُهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعْجِزِينَ', '5b166e5c5da18abde94604fe9944f2167587ad7c5086d1feb638ced3a66816a0', '5b166e5c5da18abde94604fe9944f2167587ad7c5086d1feb638ced3a66816a0', NULL, 'فاصابهم سيات ما كسبوا والذين ظلموا من هؤلاء سيصيبهم سيات ما كسبوا وما هم بمعجزين', 24, 47, 185, 1, 6, 464, false, NULL),
    (4110, 'tanzil-uthmani-v1.1', 39, 52, 'أَوَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'c23582d577cbfc2bbbd6f0dbfb4a754026a46671435ffef4d56796106bea8099', 'أَوَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ', 'c23582d577cbfc2bbbd6f0dbfb4a754026a46671435ffef4d56796106bea8099', 'c23582d577cbfc2bbbd6f0dbfb4a754026a46671435ffef4d56796106bea8099', NULL, 'اولم يعلموا ان الله يبسط الرزق لمن يشاء ويقدر ان في ذلك لايت لقوم يؤمنون', 24, 47, 185, 1, 6, 464, false, NULL),
    (4111, 'tanzil-uthmani-v1.1', 39, 53, 'قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'e073806d2585cffbd962f85052a138e0be0c7c8d4c54a85e60b10805315c242b', 'قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'e073806d2585cffbd962f85052a138e0be0c7c8d4c54a85e60b10805315c242b', 'e073806d2585cffbd962f85052a138e0be0c7c8d4c54a85e60b10805315c242b', NULL, 'قل يعبادي الذين اسرفوا علي انفسهم لا تقنطوا من رحمه الله ان الله يغفر الذنوب جميعا انه هو الغفور الرحيم', 24, 47, 186, 1, 6, 464, false, NULL),
    (4112, 'tanzil-uthmani-v1.1', 39, 54, 'وَأَنِيبُوٓا۟ إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا۟ لَهُۥ مِن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ ثُمَّ لَا تُنصَرُونَ', 'f798e26e8d325f834693c0535ae423c70afd3ca2cca235d534cc9b0ed43eb326', 'وَأَنِيبُوٓا۟ إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا۟ لَهُۥ مِن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ ثُمَّ لَا تُنصَرُونَ', 'f798e26e8d325f834693c0535ae423c70afd3ca2cca235d534cc9b0ed43eb326', 'f798e26e8d325f834693c0535ae423c70afd3ca2cca235d534cc9b0ed43eb326', NULL, 'وانيبوا الي ربكم واسلموا له من قبل ان ياتيكم العذاب ثم لا تنصرون', 24, 47, 186, 1, 6, 464, false, NULL),
    (4113, 'tanzil-uthmani-v1.1', 39, 55, 'وَٱتَّبِعُوٓا۟ أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ بَغْتَةً وَأَنتُمْ لَا تَشْعُرُونَ', '7c166a2b6224981159f0afb991fe8c93c7ebbb64e175f6f7ffd3b0016e78f370', 'وَٱتَّبِعُوٓا۟ أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ بَغْتَةً وَأَنتُمْ لَا تَشْعُرُونَ', '7c166a2b6224981159f0afb991fe8c93c7ebbb64e175f6f7ffd3b0016e78f370', '7c166a2b6224981159f0afb991fe8c93c7ebbb64e175f6f7ffd3b0016e78f370', NULL, 'واتبعوا احسن ما انزل اليكم من ربكم من قبل ان ياتيكم العذاب بغته وانتم لا تشعرون', 24, 47, 186, 1, 6, 464, false, NULL),
    (4114, 'tanzil-uthmani-v1.1', 39, 56, 'أَن تَقُولَ نَفْسٌ يَٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ', '40edc0f10c5a3b5280d32e48fe04e243c74e1a3c9566d2b723a48fce68b39ac5', 'أَن تَقُولَ نَفْسٌ يَٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ', '40edc0f10c5a3b5280d32e48fe04e243c74e1a3c9566d2b723a48fce68b39ac5', '40edc0f10c5a3b5280d32e48fe04e243c74e1a3c9566d2b723a48fce68b39ac5', NULL, 'ان تقول نفس يحسرتي علي ما فرطت في جنب الله وان كنت لمن السخرين', 24, 47, 186, 1, 6, 464, false, NULL),
    (4115, 'tanzil-uthmani-v1.1', 39, 57, 'أَوْ تَقُولَ لَوْ أَنَّ ٱللَّهَ هَدَىٰنِى لَكُنتُ مِنَ ٱلْمُتَّقِينَ', '91fb8fed185a01072ec928f8664a9c79112e85d02317e6b8511be8c74fb4d32b', 'أَوْ تَقُولَ لَوْ أَنَّ ٱللَّهَ هَدَىٰنِى لَكُنتُ مِنَ ٱلْمُتَّقِينَ', '91fb8fed185a01072ec928f8664a9c79112e85d02317e6b8511be8c74fb4d32b', '91fb8fed185a01072ec928f8664a9c79112e85d02317e6b8511be8c74fb4d32b', NULL, 'او تقول لو ان الله هديني لكنت من المتقين', 24, 47, 186, 1, 6, 465, false, NULL),
    (4116, 'tanzil-uthmani-v1.1', 39, 58, 'أَوْ تَقُولَ حِينَ تَرَى ٱلْعَذَابَ لَوْ أَنَّ لِى كَرَّةً فَأَكُونَ مِنَ ٱلْمُحْسِنِينَ', 'e24d556076997e42d55243e470d39cdff3fd70ab15fc422a25511ef74c516434', 'أَوْ تَقُولَ حِينَ تَرَى ٱلْعَذَابَ لَوْ أَنَّ لِى كَرَّةً فَأَكُونَ مِنَ ٱلْمُحْسِنِينَ', 'e24d556076997e42d55243e470d39cdff3fd70ab15fc422a25511ef74c516434', 'e24d556076997e42d55243e470d39cdff3fd70ab15fc422a25511ef74c516434', NULL, 'او تقول حين تري العذاب لو ان لي كره فاكون من المحسنين', 24, 47, 186, 1, 6, 465, false, NULL),
    (4117, 'tanzil-uthmani-v1.1', 39, 59, 'بَلَىٰ قَدْ جَآءَتْكَ ءَايَٰتِى فَكَذَّبْتَ بِهَا وَٱسْتَكْبَرْتَ وَكُنتَ مِنَ ٱلْكَٰفِرِينَ', '3a79ab6118ed16494d0edc956abebc53a1f275012f5259ede9566ae4b0f188c5', 'بَلَىٰ قَدْ جَآءَتْكَ ءَايَٰتِى فَكَذَّبْتَ بِهَا وَٱسْتَكْبَرْتَ وَكُنتَ مِنَ ٱلْكَٰفِرِينَ', '3a79ab6118ed16494d0edc956abebc53a1f275012f5259ede9566ae4b0f188c5', '3a79ab6118ed16494d0edc956abebc53a1f275012f5259ede9566ae4b0f188c5', NULL, 'بلي قد جاءتك ءايتي فكذبت بها واستكبرت وكنت من الكفرين', 24, 47, 186, 1, 6, 465, false, NULL),
    (4118, 'tanzil-uthmani-v1.1', 39, 60, 'وَيَوْمَ ٱلْقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْمُتَكَبِّرِينَ', 'cf54f68b308fc52d49beef596031e92cdd8f7bf998ff0ddb68105f9e0fc25827', 'وَيَوْمَ ٱلْقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْمُتَكَبِّرِينَ', 'cf54f68b308fc52d49beef596031e92cdd8f7bf998ff0ddb68105f9e0fc25827', 'cf54f68b308fc52d49beef596031e92cdd8f7bf998ff0ddb68105f9e0fc25827', NULL, 'ويوم القيمه تري الذين كذبوا علي الله وجوههم مسوده اليس في جهنم مثوي للمتكبرين', 24, 47, 186, 1, 6, 465, false, NULL),
    (4119, 'tanzil-uthmani-v1.1', 39, 61, 'وَيُنَجِّى ٱللَّهُ ٱلَّذِينَ ٱتَّقَوْا۟ بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمْ يَحْزَنُونَ', 'ff80b63b4946d209d7ed985ab1b5ba35de6788a9a3f4a018f795d73d14982eb9', 'وَيُنَجِّى ٱللَّهُ ٱلَّذِينَ ٱتَّقَوْا۟ بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمْ يَحْزَنُونَ', 'ff80b63b4946d209d7ed985ab1b5ba35de6788a9a3f4a018f795d73d14982eb9', 'ff80b63b4946d209d7ed985ab1b5ba35de6788a9a3f4a018f795d73d14982eb9', NULL, 'وينجي الله الذين اتقوا بمفازتهم لا يمسهم السوء ولا هم يحزنون', 24, 47, 186, 1, 6, 465, false, NULL),
    (4120, 'tanzil-uthmani-v1.1', 39, 62, 'ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', '20f8df71627c905a5ca51351138bd7e1e34c449853fedbd2a1862f3444bc4a0c', 'ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ', '20f8df71627c905a5ca51351138bd7e1e34c449853fedbd2a1862f3444bc4a0c', '20f8df71627c905a5ca51351138bd7e1e34c449853fedbd2a1862f3444bc4a0c', NULL, 'الله خلق كل شيء وهو علي كل شيء وكيل', 24, 47, 186, 1, 6, 465, false, NULL),
    (4121, 'tanzil-uthmani-v1.1', 39, 63, 'لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '77a8f77a3476bd1eb898008d7bf21a9e0f5161f643a0f9b66bfe62d66e1c41b9', 'لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '77a8f77a3476bd1eb898008d7bf21a9e0f5161f643a0f9b66bfe62d66e1c41b9', '77a8f77a3476bd1eb898008d7bf21a9e0f5161f643a0f9b66bfe62d66e1c41b9', NULL, 'له مقاليد السموت والارض والذين كفروا بايت الله اولئك هم الخسرون', 24, 47, 186, 1, 6, 465, false, NULL),
    (4122, 'tanzil-uthmani-v1.1', 39, 64, 'قُلْ أَفَغَيْرَ ٱللَّهِ تَأْمُرُوٓنِّىٓ أَعْبُدُ أَيُّهَا ٱلْجَٰهِلُونَ', '53bef238913684dca3473de23d51f81eab13c561222f785e2d68941e465893cb', 'قُلْ أَفَغَيْرَ ٱللَّهِ تَأْمُرُوٓنِّىٓ أَعْبُدُ أَيُّهَا ٱلْجَٰهِلُونَ', '53bef238913684dca3473de23d51f81eab13c561222f785e2d68941e465893cb', '53bef238913684dca3473de23d51f81eab13c561222f785e2d68941e465893cb', NULL, 'قل افغير الله تامروني اعبد ايها الجهلون', 24, 47, 186, 1, 6, 465, false, NULL),
    (4123, 'tanzil-uthmani-v1.1', 39, 65, 'وَلَقَدْ أُوحِىَ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'd6c7ff6ea2def69a0965476294377616f93965b0c5b47f6d3c93ad2942e5db5e', 'وَلَقَدْ أُوحِىَ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 'd6c7ff6ea2def69a0965476294377616f93965b0c5b47f6d3c93ad2942e5db5e', 'd6c7ff6ea2def69a0965476294377616f93965b0c5b47f6d3c93ad2942e5db5e', NULL, 'ولقد اوحي اليك والي الذين من قبلك لئن اشركت ليحبطن عملك ولتكونن من الخسرين', 24, 47, 186, 1, 6, 465, false, NULL),
    (4124, 'tanzil-uthmani-v1.1', 39, 66, 'بَلِ ٱللَّهَ فَٱعْبُدْ وَكُن مِّنَ ٱلشَّٰكِرِينَ', '7978f67ef5110066b213bd684ed108df9d8fc05c8e591b1314b6796748b8d065', 'بَلِ ٱللَّهَ فَٱعْبُدْ وَكُن مِّنَ ٱلشَّٰكِرِينَ', '7978f67ef5110066b213bd684ed108df9d8fc05c8e591b1314b6796748b8d065', '7978f67ef5110066b213bd684ed108df9d8fc05c8e591b1314b6796748b8d065', NULL, 'بل الله فاعبد وكن من الشكرين', 24, 47, 186, 1, 6, 465, false, NULL),
    (4125, 'tanzil-uthmani-v1.1', 39, 67, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطْوِيَّٰتٌۢ بِيَمِينِهِۦ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'b7124df12b19f808540de027b4b7542c9a9e0b5be4b6112cbe271311117f4d02', 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطْوِيَّٰتٌۢ بِيَمِينِهِۦ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 'b7124df12b19f808540de027b4b7542c9a9e0b5be4b6112cbe271311117f4d02', 'b7124df12b19f808540de027b4b7542c9a9e0b5be4b6112cbe271311117f4d02', NULL, 'وما قدروا الله حق قدره والارض جميعا قبضته يوم القيمه والسموت مطويت بيمينه سبحنه وتعلي عما يشركون', 24, 47, 186, 1, 6, 465, false, NULL),
    (4126, 'tanzil-uthmani-v1.1', 39, 68, 'وَنُفِخَ فِى ٱلصُّورِ فَصَعِقَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ', '32a2930bb56d5306be719323700968f53ec7e02d2cadb1953285eead11bca337', 'وَنُفِخَ فِى ٱلصُّورِ فَصَعِقَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ', '32a2930bb56d5306be719323700968f53ec7e02d2cadb1953285eead11bca337', '32a2930bb56d5306be719323700968f53ec7e02d2cadb1953285eead11bca337', NULL, 'ونفخ في الصور فصعق من في السموت ومن في الارض الا من شاء الله ثم نفخ فيه اخري فاذا هم قيام ينظرون', 24, 47, 186, 1, 6, 466, false, NULL),
    (4127, 'tanzil-uthmani-v1.1', 39, 69, 'وَأَشْرَقَتِ ٱلْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلْكِتَٰبُ وَجِا۟ىٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 'ecd685f4587083258ae8a7bd91ea934ec562bad0b8c5192a57f4101009ce4f05', 'وَأَشْرَقَتِ ٱلْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلْكِتَٰبُ وَجِا۟ىٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 'ecd685f4587083258ae8a7bd91ea934ec562bad0b8c5192a57f4101009ce4f05', 'ecd685f4587083258ae8a7bd91ea934ec562bad0b8c5192a57f4101009ce4f05', NULL, 'واشرقت الارض بنور ربها ووضع الكتب وجايء بالنبين والشهداء وقضي بينهم بالحق وهم لا يظلمون', 24, 47, 186, 1, 6, 466, false, NULL),
    (4128, 'tanzil-uthmani-v1.1', 39, 70, 'وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ', '0f576c94684dc8c0eba12720bfd068cff93bf482f2e513a8368d04c605e1ff1c', 'وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ', '0f576c94684dc8c0eba12720bfd068cff93bf482f2e513a8368d04c605e1ff1c', '0f576c94684dc8c0eba12720bfd068cff93bf482f2e513a8368d04c605e1ff1c', NULL, 'ووفيت كل نفس ما عملت وهو اعلم بما يفعلون', 24, 47, 186, 1, 6, 466, false, NULL),
    (4129, 'tanzil-uthmani-v1.1', 39, 71, 'وَسِيقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ ءَايَٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ بَلَىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ ٱلْعَذَابِ عَلَى ٱلْكَٰفِرِينَ', 'fed7354c4dcb449820a121b673f8af7181f9014b5d8c27889089fdb4fa18cee3', 'وَسِيقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ ءَايَٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ بَلَىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ ٱلْعَذَابِ عَلَى ٱلْكَٰفِرِينَ', 'fed7354c4dcb449820a121b673f8af7181f9014b5d8c27889089fdb4fa18cee3', 'fed7354c4dcb449820a121b673f8af7181f9014b5d8c27889089fdb4fa18cee3', NULL, 'وسيق الذين كفروا الي جهنم زمرا حتي اذا جاءوها فتحت ابوبها وقال لهم خزنتها الم ياتكم رسل منكم يتلون عليكم ءايت ربكم وينذرونكم لقاء يومكم هذا قالوا بلي ولكن حقت كلمه العذاب علي الكفرين', 24, 47, 186, 1, 6, 466, false, NULL),
    (4130, 'tanzil-uthmani-v1.1', 39, 72, 'قِيلَ ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'd4f469d019b211590cb58ae3170ba374aabd3b111e2735efc1c9a3a8611f9169', 'قِيلَ ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 'd4f469d019b211590cb58ae3170ba374aabd3b111e2735efc1c9a3a8611f9169', 'd4f469d019b211590cb58ae3170ba374aabd3b111e2735efc1c9a3a8611f9169', NULL, 'قيل ادخلوا ابوب جهنم خلدين فيها فبئس مثوي المتكبرين', 24, 47, 186, 1, 6, 466, false, NULL),
    (4131, 'tanzil-uthmani-v1.1', 39, 73, 'وَسِيقَ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ إِلَى ٱلْجَنَّةِ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَٱدْخُلُوهَا خَٰلِدِينَ', '5b3979daba3dab91fd40e8d2a45360431e83081181386a6e74148c1c47940a2a', 'وَسِيقَ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ إِلَى ٱلْجَنَّةِ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَٱدْخُلُوهَا خَٰلِدِينَ', '5b3979daba3dab91fd40e8d2a45360431e83081181386a6e74148c1c47940a2a', '5b3979daba3dab91fd40e8d2a45360431e83081181386a6e74148c1c47940a2a', NULL, 'وسيق الذين اتقوا ربهم الي الجنه زمرا حتي اذا جاءوها وفتحت ابوبها وقال لهم خزنتها سلم عليكم طبتم فادخلوها خلدين', 24, 47, 186, 1, 6, 466, false, NULL),
    (4132, 'tanzil-uthmani-v1.1', 39, 74, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا ٱلْأَرْضَ نَتَبَوَّأُ مِنَ ٱلْجَنَّةِ حَيْثُ نَشَآءُ فَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', '9a0d7be3595e5dd2f1a1415aef8f869255bf8efe949c0725158a2a762782fda9', 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا ٱلْأَرْضَ نَتَبَوَّأُ مِنَ ٱلْجَنَّةِ حَيْثُ نَشَآءُ فَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', '9a0d7be3595e5dd2f1a1415aef8f869255bf8efe949c0725158a2a762782fda9', '9a0d7be3595e5dd2f1a1415aef8f869255bf8efe949c0725158a2a762782fda9', NULL, 'وقالوا الحمد لله الذي صدقنا وعده واورثنا الارض نتبوا من الجنه حيث نشاء فنعم اجر العملين', 24, 47, 186, 1, 6, 466, false, NULL),
    (4133, 'tanzil-uthmani-v1.1', 39, 75, 'وَتَرَى ٱلْمَلَٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ ٱلْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَقِيلَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', '47746a564e26546f7d3c073ea31f12cdffe141bd49e3b44c5688e7f537503a69', 'وَتَرَى ٱلْمَلَٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ ٱلْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَقِيلَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', '47746a564e26546f7d3c073ea31f12cdffe141bd49e3b44c5688e7f537503a69', '47746a564e26546f7d3c073ea31f12cdffe141bd49e3b44c5688e7f537503a69', NULL, 'وتري الملئكه حافين من حول العرش يسبحون بحمد ربهم وقضي بينهم بالحق وقيل الحمد لله رب العلمين', 24, 47, 186, 1, 6, 467, false, NULL),
    (4134, 'tanzil-uthmani-v1.1', 40, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'b4f3f13e19bbe78e5f72edb60140cdae2eb77fceae263ed0d2b48f30c7cc67fd', 'حمٓ', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'حم', 24, 47, 187, 1, 6, 467, false, NULL),
    (4135, 'tanzil-uthmani-v1.1', 40, 2, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ', '8a365024dd085c94cad47266a96c59ea141c67b115f8d0c6a663b2e82f13c15d', 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ', '8a365024dd085c94cad47266a96c59ea141c67b115f8d0c6a663b2e82f13c15d', '8a365024dd085c94cad47266a96c59ea141c67b115f8d0c6a663b2e82f13c15d', NULL, 'تنزيل الكتب من الله العزيز العليم', 24, 47, 187, 1, 6, 467, false, NULL),
    (4136, 'tanzil-uthmani-v1.1', 40, 3, 'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ لَآ إِلَٰهَ إِلَّا هُوَ إِلَيْهِ ٱلْمَصِيرُ', '2456bb67483084c257c82dfcfede0f7b0dcfcf6cd6216a17fe93fc3fa0c9078d', 'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ لَآ إِلَٰهَ إِلَّا هُوَ إِلَيْهِ ٱلْمَصِيرُ', '2456bb67483084c257c82dfcfede0f7b0dcfcf6cd6216a17fe93fc3fa0c9078d', '2456bb67483084c257c82dfcfede0f7b0dcfcf6cd6216a17fe93fc3fa0c9078d', NULL, 'غافر الذنب وقابل التوب شديد العقاب ذي الطول لا اله الا هو اليه المصير', 24, 47, 187, 1, 6, 467, false, NULL),
    (4137, 'tanzil-uthmani-v1.1', 40, 4, 'مَا يُجَٰدِلُ فِىٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُوا۟ فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى ٱلْبِلَٰدِ', '408fda8eb3cf80fd0d8c8aae126f1507fa4839d2c882825fe0364d40081e4f64', 'مَا يُجَٰدِلُ فِىٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُوا۟ فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى ٱلْبِلَٰدِ', '408fda8eb3cf80fd0d8c8aae126f1507fa4839d2c882825fe0364d40081e4f64', '408fda8eb3cf80fd0d8c8aae126f1507fa4839d2c882825fe0364d40081e4f64', NULL, 'ما يجدل في ءايت الله الا الذين كفروا فلا يغررك تقلبهم في البلد', 24, 47, 187, 1, 6, 467, false, NULL),
    (4138, 'tanzil-uthmani-v1.1', 40, 5, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَٱلْأَحْزَابُ مِنۢ بَعْدِهِمْ وَهَمَّتْ كُلُّ أُمَّةٍۭ بِرَسُولِهِمْ لِيَأْخُذُوهُ وَجَٰدَلُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ فَأَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ', 'f14f07407399321c182b1c103e2b8f085a36432b8ec8afa88608f5406adee333', 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَٱلْأَحْزَابُ مِنۢ بَعْدِهِمْ وَهَمَّتْ كُلُّ أُمَّةٍۭ بِرَسُولِهِمْ لِيَأْخُذُوهُ وَجَٰدَلُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ فَأَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ', 'f14f07407399321c182b1c103e2b8f085a36432b8ec8afa88608f5406adee333', 'f14f07407399321c182b1c103e2b8f085a36432b8ec8afa88608f5406adee333', NULL, 'كذبت قبلهم قوم نوح والاحزاب من بعدهم وهمت كل امه برسولهم لياخذوه وجدلوا بالبطل ليدحضوا به الحق فاخذتهم فكيف كان عقاب', 24, 47, 187, 1, 6, 467, false, NULL),
    (4139, 'tanzil-uthmani-v1.1', 40, 6, 'وَكَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ أَصْحَٰبُ ٱلنَّارِ', 'df003eb1feba46377c9f4bdc256ab1cef31a17da81f8706f0360ebf6a1ec048b', 'وَكَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ أَصْحَٰبُ ٱلنَّارِ', 'df003eb1feba46377c9f4bdc256ab1cef31a17da81f8706f0360ebf6a1ec048b', 'df003eb1feba46377c9f4bdc256ab1cef31a17da81f8706f0360ebf6a1ec048b', NULL, 'وكذلك حقت كلمت ربك علي الذين كفروا انهم اصحب النار', 24, 47, 187, 1, 6, 467, false, NULL),
    (4140, 'tanzil-uthmani-v1.1', 40, 7, 'ٱلَّذِينَ يَحْمِلُونَ ٱلْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُوا۟ رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍ رَّحْمَةً وَعِلْمًا فَٱغْفِرْ لِلَّذِينَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِيلَكَ وَقِهِمْ عَذَابَ ٱلْجَحِيمِ', 'eda48fe54eb41cfaac2347c1164cf2ed261cbc892984d2d21211675eec5199e8', 'ٱلَّذِينَ يَحْمِلُونَ ٱلْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُوا۟ رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍ رَّحْمَةً وَعِلْمًا فَٱغْفِرْ لِلَّذِينَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِيلَكَ وَقِهِمْ عَذَابَ ٱلْجَحِيمِ', 'eda48fe54eb41cfaac2347c1164cf2ed261cbc892984d2d21211675eec5199e8', 'eda48fe54eb41cfaac2347c1164cf2ed261cbc892984d2d21211675eec5199e8', NULL, 'الذين يحملون العرش ومن حوله يسبحون بحمد ربهم ويؤمنون به ويستغفرون للذين ءامنوا ربنا وسعت كل شيء رحمه وعلما فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب الجحيم', 24, 47, 187, 1, 6, 467, false, NULL),
    (4141, 'tanzil-uthmani-v1.1', 40, 8, 'رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ee29c06fb94310869a5a402d0073ea26496d794136a64476fd939b890d0cc8ce', 'رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'ee29c06fb94310869a5a402d0073ea26496d794136a64476fd939b890d0cc8ce', 'ee29c06fb94310869a5a402d0073ea26496d794136a64476fd939b890d0cc8ce', NULL, 'ربنا وادخلهم جنت عدن التي وعدتهم ومن صلح من ءابائهم وازوجهم وذريتهم انك انت العزيز الحكيم', 24, 47, 187, 1, 6, 468, false, NULL),
    (4142, 'tanzil-uthmani-v1.1', 40, 9, 'وَقِهِمُ ٱلسَّيِّـَٔاتِ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُۥ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '7f0465bbec50e39b99b4a50352bb81809278668bf8d8e59c1ea04509e01b9745', 'وَقِهِمُ ٱلسَّيِّـَٔاتِ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُۥ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '7f0465bbec50e39b99b4a50352bb81809278668bf8d8e59c1ea04509e01b9745', '7f0465bbec50e39b99b4a50352bb81809278668bf8d8e59c1ea04509e01b9745', NULL, 'وقهم السيات ومن تق السيات يومئذ فقد رحمته وذلك هو الفوز العظيم', 24, 47, 187, 1, 6, 468, false, NULL),
    (4143, 'tanzil-uthmani-v1.1', 40, 10, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنَادَوْنَ لَمَقْتُ ٱللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى ٱلْإِيمَٰنِ فَتَكْفُرُونَ', 'c2d41fdf4044a7fbe7d4fec800abcaa1075c10293385b32f369984cbe94017af', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنَادَوْنَ لَمَقْتُ ٱللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى ٱلْإِيمَٰنِ فَتَكْفُرُونَ', 'c2d41fdf4044a7fbe7d4fec800abcaa1075c10293385b32f369984cbe94017af', 'c2d41fdf4044a7fbe7d4fec800abcaa1075c10293385b32f369984cbe94017af', NULL, 'ان الذين كفروا ينادون لمقت الله اكبر من مقتكم انفسكم اذ تدعون الي الايمن فتكفرون', 24, 47, 187, 1, 6, 468, false, NULL),
    (4144, 'tanzil-uthmani-v1.1', 40, 11, 'قَالُوا۟ رَبَّنَآ أَمَتَّنَا ٱثْنَتَيْنِ وَأَحْيَيْتَنَا ٱثْنَتَيْنِ فَٱعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُوجٍ مِّن سَبِيلٍ', '410a58a151307ffb33bb78d500815c1901b39f5d837f824490d5dfb822092674', 'قَالُوا۟ رَبَّنَآ أَمَتَّنَا ٱثْنَتَيْنِ وَأَحْيَيْتَنَا ٱثْنَتَيْنِ فَٱعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُوجٍ مِّن سَبِيلٍ', '410a58a151307ffb33bb78d500815c1901b39f5d837f824490d5dfb822092674', '410a58a151307ffb33bb78d500815c1901b39f5d837f824490d5dfb822092674', NULL, 'قالوا ربنا امتنا اثنتين واحييتنا اثنتين فاعترفنا بذنوبنا فهل الي خروج من سبيل', 24, 47, 187, 1, 6, 468, false, NULL),
    (4145, 'tanzil-uthmani-v1.1', 40, 12, 'ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِىَ ٱللَّهُ وَحْدَهُۥ كَفَرْتُمْ وَإِن يُشْرَكْ بِهِۦ تُؤْمِنُوا۟ فَٱلْحُكْمُ لِلَّهِ ٱلْعَلِىِّ ٱلْكَبِيرِ', '0c28247451351c120db0a602431a13a580bfe41916964507cdf70241a4918e4a', 'ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِىَ ٱللَّهُ وَحْدَهُۥ كَفَرْتُمْ وَإِن يُشْرَكْ بِهِۦ تُؤْمِنُوا۟ فَٱلْحُكْمُ لِلَّهِ ٱلْعَلِىِّ ٱلْكَبِيرِ', '0c28247451351c120db0a602431a13a580bfe41916964507cdf70241a4918e4a', '0c28247451351c120db0a602431a13a580bfe41916964507cdf70241a4918e4a', NULL, 'ذلكم بانه اذا دعي الله وحده كفرتم وان يشرك به تؤمنوا فالحكم لله العلي الكبير', 24, 47, 187, 1, 6, 468, false, NULL),
    (4146, 'tanzil-uthmani-v1.1', 40, 13, 'هُوَ ٱلَّذِى يُرِيكُمْ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزْقًا وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ', 'fb9cfe337058800f6636f0776bbdc49e5d30995a466059b42c9b7be335662a86', 'هُوَ ٱلَّذِى يُرِيكُمْ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزْقًا وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ', 'fb9cfe337058800f6636f0776bbdc49e5d30995a466059b42c9b7be335662a86', 'fb9cfe337058800f6636f0776bbdc49e5d30995a466059b42c9b7be335662a86', NULL, 'هو الذي يريكم ءايته وينزل لكم من السماء رزقا وما يتذكر الا من ينيب', 24, 47, 187, 1, 6, 468, false, NULL),
    (4147, 'tanzil-uthmani-v1.1', 40, 14, 'فَٱدْعُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'ba417d23de9c4d57968649c7a936602accafd54d7339b440d5248f44832e776f', 'فَٱدْعُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 'ba417d23de9c4d57968649c7a936602accafd54d7339b440d5248f44832e776f', 'ba417d23de9c4d57968649c7a936602accafd54d7339b440d5248f44832e776f', NULL, 'فادعوا الله مخلصين له الدين ولو كره الكفرون', 24, 47, 187, 1, 6, 468, false, NULL),
    (4148, 'tanzil-uthmani-v1.1', 40, 15, 'رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلْعَرْشِ يُلْقِى ٱلرُّوحَ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ ٱلتَّلَاقِ', 'd1605af694ea8fd3b392e5872bf79b3ada7340ab56c1d88833676574af1cbded', 'رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلْعَرْشِ يُلْقِى ٱلرُّوحَ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ ٱلتَّلَاقِ', 'd1605af694ea8fd3b392e5872bf79b3ada7340ab56c1d88833676574af1cbded', 'd1605af694ea8fd3b392e5872bf79b3ada7340ab56c1d88833676574af1cbded', NULL, 'رفيع الدرجت ذو العرش يلقي الروح من امره علي من يشاء من عباده لينذر يوم التلاق', 24, 47, 187, 1, 6, 468, false, NULL),
    (4149, 'tanzil-uthmani-v1.1', 40, 16, 'يَوْمَ هُم بَٰرِزُونَ لَا يَخْفَىٰ عَلَى ٱللَّهِ مِنْهُمْ شَىْءٌ لِّمَنِ ٱلْمُلْكُ ٱلْيَوْمَ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 'f1bef6006d435a86f42b83f4de3d227e2b4d70fc1abacd9803b1d23de42030cc', 'يَوْمَ هُم بَٰرِزُونَ لَا يَخْفَىٰ عَلَى ٱللَّهِ مِنْهُمْ شَىْءٌ لِّمَنِ ٱلْمُلْكُ ٱلْيَوْمَ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 'f1bef6006d435a86f42b83f4de3d227e2b4d70fc1abacd9803b1d23de42030cc', 'f1bef6006d435a86f42b83f4de3d227e2b4d70fc1abacd9803b1d23de42030cc', NULL, 'يوم هم برزون لا يخفي علي الله منهم شيء لمن الملك اليوم لله الوحد القهار', 24, 47, 187, 1, 6, 468, false, NULL),
    (4150, 'tanzil-uthmani-v1.1', 40, 17, 'ٱلْيَوْمَ تُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ لَا ظُلْمَ ٱلْيَوْمَ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', '68cf37beffdd5d4a79dfd3d764bdf1e1a0cbe425d9984369a719adc8f080bbc8', 'ٱلْيَوْمَ تُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ لَا ظُلْمَ ٱلْيَوْمَ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', '68cf37beffdd5d4a79dfd3d764bdf1e1a0cbe425d9984369a719adc8f080bbc8', '68cf37beffdd5d4a79dfd3d764bdf1e1a0cbe425d9984369a719adc8f080bbc8', NULL, 'اليوم تجزي كل نفس بما كسبت لا ظلم اليوم ان الله سريع الحساب', 24, 47, 187, 1, 6, 469, false, NULL),
    (4151, 'tanzil-uthmani-v1.1', 40, 18, 'وَأَنذِرْهُمْ يَوْمَ ٱلْـَٔازِفَةِ إِذِ ٱلْقُلُوبُ لَدَى ٱلْحَنَاجِرِ كَٰظِمِينَ مَا لِلظَّٰلِمِينَ مِنْ حَمِيمٍ وَلَا شَفِيعٍ يُطَاعُ', 'a38ed5d865b1f7ec460000d59201478e3c32859fcfe86b0ddb565189d60ee7e7', 'وَأَنذِرْهُمْ يَوْمَ ٱلْـَٔازِفَةِ إِذِ ٱلْقُلُوبُ لَدَى ٱلْحَنَاجِرِ كَٰظِمِينَ مَا لِلظَّٰلِمِينَ مِنْ حَمِيمٍ وَلَا شَفِيعٍ يُطَاعُ', 'a38ed5d865b1f7ec460000d59201478e3c32859fcfe86b0ddb565189d60ee7e7', 'a38ed5d865b1f7ec460000d59201478e3c32859fcfe86b0ddb565189d60ee7e7', NULL, 'وانذرهم يوم الازفه اذ القلوب لدي الحناجر كظمين ما للظلمين من حميم ولا شفيع يطاع', 24, 47, 187, 1, 6, 469, false, NULL),
    (4152, 'tanzil-uthmani-v1.1', 40, 19, 'يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ', 'fc102c13e0b160308b24843dd18787396fd7e1f583b48020741d8780281f98d4', 'يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ', 'fc102c13e0b160308b24843dd18787396fd7e1f583b48020741d8780281f98d4', 'fc102c13e0b160308b24843dd18787396fd7e1f583b48020741d8780281f98d4', NULL, 'يعلم خائنه الاعين وما تخفي الصدور', 24, 47, 187, 1, 6, 469, false, NULL),
    (4153, 'tanzil-uthmani-v1.1', 40, 20, 'وَٱللَّهُ يَقْضِى بِٱلْحَقِّ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '6a84e79a1c1f40b3080caeab91a4f2acc92deb758622d0985795e0999cbb0124', 'وَٱللَّهُ يَقْضِى بِٱلْحَقِّ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '6a84e79a1c1f40b3080caeab91a4f2acc92deb758622d0985795e0999cbb0124', '6a84e79a1c1f40b3080caeab91a4f2acc92deb758622d0985795e0999cbb0124', NULL, 'والله يقضي بالحق والذين يدعون من دونه لا يقضون بشيء ان الله هو السميع البصير', 24, 47, 187, 1, 6, 469, false, NULL),
    (4154, 'tanzil-uthmani-v1.1', 40, 21, 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُوا۟ مِن قَبْلِهِمْ كَانُوا۟ هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', '2fe704815165c86a859b815a49a6b6057868f22da8f89bc1ee1a8016db9a604a', 'أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُوا۟ مِن قَبْلِهِمْ كَانُوا۟ هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ', '2fe704815165c86a859b815a49a6b6057868f22da8f89bc1ee1a8016db9a604a', '2fe704815165c86a859b815a49a6b6057868f22da8f89bc1ee1a8016db9a604a', NULL, 'اولم يسيروا في الارض فينظروا كيف كان عقبه الذين كانوا من قبلهم كانوا هم اشد منهم قوه وءاثارا في الارض فاخذهم الله بذنوبهم وما كان لهم من الله من واق', 24, 47, 188, 1, 6, 469, false, NULL),
    (4155, 'tanzil-uthmani-v1.1', 40, 22, 'ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُ إِنَّهُۥ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', '7429fe3a7630bfa1a510eaa0740225fba79312f34cdccfb894b5cf7a43adfcf9', 'ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُ إِنَّهُۥ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ', '7429fe3a7630bfa1a510eaa0740225fba79312f34cdccfb894b5cf7a43adfcf9', '7429fe3a7630bfa1a510eaa0740225fba79312f34cdccfb894b5cf7a43adfcf9', NULL, 'ذلك بانهم كانت تاتيهم رسلهم بالبينت فكفروا فاخذهم الله انه قوي شديد العقاب', 24, 47, 188, 1, 6, 469, false, NULL),
    (4156, 'tanzil-uthmani-v1.1', 40, 23, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', '441f49071d0a9f5e889b74f21aa879c47eaf4ee3b30cd4fa49d770732833a270', 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ', '441f49071d0a9f5e889b74f21aa879c47eaf4ee3b30cd4fa49d770732833a270', '441f49071d0a9f5e889b74f21aa879c47eaf4ee3b30cd4fa49d770732833a270', NULL, 'ولقد ارسلنا موسي بايتنا وسلطن مبين', 24, 47, 188, 1, 6, 469, false, NULL),
    (4157, 'tanzil-uthmani-v1.1', 40, 24, 'إِلَىٰ فِرْعَوْنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُوا۟ سَٰحِرٌ كَذَّابٌ', '9ca1de35e2208b53c5d49586aeaf4e635890bcc9323a5daa3251f9df109de0ce', 'إِلَىٰ فِرْعَوْنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُوا۟ سَٰحِرٌ كَذَّابٌ', '9ca1de35e2208b53c5d49586aeaf4e635890bcc9323a5daa3251f9df109de0ce', '9ca1de35e2208b53c5d49586aeaf4e635890bcc9323a5daa3251f9df109de0ce', NULL, 'الي فرعون وهمن وقرون فقالوا سحر كذاب', 24, 47, 188, 1, 6, 469, false, NULL),
    (4158, 'tanzil-uthmani-v1.1', 40, 25, 'فَلَمَّا جَآءَهُم بِٱلْحَقِّ مِنْ عِندِنَا قَالُوا۟ ٱقْتُلُوٓا۟ أَبْنَآءَ ٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ وَٱسْتَحْيُوا۟ نِسَآءَهُمْ وَمَا كَيْدُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'e2acb16e654033f820a98766a893d99d628b464e854072d357e94f1f0bbf5c68', 'فَلَمَّا جَآءَهُم بِٱلْحَقِّ مِنْ عِندِنَا قَالُوا۟ ٱقْتُلُوٓا۟ أَبْنَآءَ ٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ وَٱسْتَحْيُوا۟ نِسَآءَهُمْ وَمَا كَيْدُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 'e2acb16e654033f820a98766a893d99d628b464e854072d357e94f1f0bbf5c68', 'e2acb16e654033f820a98766a893d99d628b464e854072d357e94f1f0bbf5c68', NULL, 'فلما جاءهم بالحق من عندنا قالوا اقتلوا ابناء الذين ءامنوا معه واستحيوا نساءهم وما كيد الكفرين الا في ضلل', 24, 47, 188, 1, 6, 469, false, NULL),
    (4159, 'tanzil-uthmani-v1.1', 40, 26, 'وَقَالَ فِرْعَوْنُ ذَرُونِىٓ أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُۥٓ إِنِّىٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى ٱلْأَرْضِ ٱلْفَسَادَ', '5b9e63260dca81262dd28e117d7ca8125f10d00de6d4965acdd22887100c6f6e', 'وَقَالَ فِرْعَوْنُ ذَرُونِىٓ أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُۥٓ إِنِّىٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى ٱلْأَرْضِ ٱلْفَسَادَ', '5b9e63260dca81262dd28e117d7ca8125f10d00de6d4965acdd22887100c6f6e', '5b9e63260dca81262dd28e117d7ca8125f10d00de6d4965acdd22887100c6f6e', NULL, 'وقال فرعون ذروني اقتل موسي وليدع ربه اني اخاف ان يبدل دينكم او ان يظهر في الارض الفساد', 24, 47, 188, 1, 6, 470, false, NULL),
    (4160, 'tanzil-uthmani-v1.1', 40, 27, 'وَقَالَ مُوسَىٰٓ إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ ٱلْحِسَابِ', 'c414386059bc2c45c456a8e1a476acd55ba709405544db51e57dee821e5dbfd6', 'وَقَالَ مُوسَىٰٓ إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ ٱلْحِسَابِ', 'c414386059bc2c45c456a8e1a476acd55ba709405544db51e57dee821e5dbfd6', 'c414386059bc2c45c456a8e1a476acd55ba709405544db51e57dee821e5dbfd6', NULL, 'وقال موسي اني عذت بربي وربكم من كل متكبر لا يؤمن بيوم الحساب', 24, 47, 188, 1, 6, 470, false, NULL),
    (4161, 'tanzil-uthmani-v1.1', 40, 28, 'وَقَالَ رَجُلٌ مُّؤْمِنٌ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ ٱللَّهُ وَقَدْ جَآءَكُم بِٱلْبَيِّنَٰتِ مِن رَّبِّكُمْ وَإِن يَكُ كَٰذِبًا فَعَلَيْهِ كَذِبُهُۥ وَإِن يَكُ صَادِقًا يُصِبْكُم بَعْضُ ٱلَّذِى يَعِدُكُمْ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌ كَذَّابٌ', '2bea3b37add3e6931e873f3052145220ff637707403573fc869fe690c7e45e97', 'وَقَالَ رَجُلٌ مُّؤْمِنٌ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ ٱللَّهُ وَقَدْ جَآءَكُم بِٱلْبَيِّنَٰتِ مِن رَّبِّكُمْ وَإِن يَكُ كَٰذِبًا فَعَلَيْهِ كَذِبُهُۥ وَإِن يَكُ صَادِقًا يُصِبْكُم بَعْضُ ٱلَّذِى يَعِدُكُمْ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌ كَذَّابٌ', '2bea3b37add3e6931e873f3052145220ff637707403573fc869fe690c7e45e97', '2bea3b37add3e6931e873f3052145220ff637707403573fc869fe690c7e45e97', NULL, 'وقال رجل مؤمن من ءال فرعون يكتم ايمنه اتقتلون رجلا ان يقول ربي الله وقد جاءكم بالبينت من ربكم وان يك كذبا فعليه كذبه وان يك صادقا يصبكم بعض الذي يعدكم ان الله لا يهدي من هو مسرف كذاب', 24, 47, 188, 1, 6, 470, false, NULL),
    (4162, 'tanzil-uthmani-v1.1', 40, 29, 'يَٰقَوْمِ لَكُمُ ٱلْمُلْكُ ٱلْيَوْمَ ظَٰهِرِينَ فِى ٱلْأَرْضِ فَمَن يَنصُرُنَا مِنۢ بَأْسِ ٱللَّهِ إِن جَآءَنَا قَالَ فِرْعَوْنُ مَآ أُرِيكُمْ إِلَّا مَآ أَرَىٰ وَمَآ أَهْدِيكُمْ إِلَّا سَبِيلَ ٱلرَّشَادِ', 'bf9f5cf1afb10eff8a5400d547894248a336dbc0b0e422a820c0ade9e5577a44', 'يَٰقَوْمِ لَكُمُ ٱلْمُلْكُ ٱلْيَوْمَ ظَٰهِرِينَ فِى ٱلْأَرْضِ فَمَن يَنصُرُنَا مِنۢ بَأْسِ ٱللَّهِ إِن جَآءَنَا قَالَ فِرْعَوْنُ مَآ أُرِيكُمْ إِلَّا مَآ أَرَىٰ وَمَآ أَهْدِيكُمْ إِلَّا سَبِيلَ ٱلرَّشَادِ', 'bf9f5cf1afb10eff8a5400d547894248a336dbc0b0e422a820c0ade9e5577a44', 'bf9f5cf1afb10eff8a5400d547894248a336dbc0b0e422a820c0ade9e5577a44', NULL, 'يقوم لكم الملك اليوم ظهرين في الارض فمن ينصرنا من باس الله ان جاءنا قال فرعون ما اريكم الا ما اري وما اهديكم الا سبيل الرشاد', 24, 47, 188, 1, 6, 470, false, NULL),
    (4163, 'tanzil-uthmani-v1.1', 40, 30, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ ٱلْأَحْزَابِ', 'b9ce97d0595c7835078d06c4cc3b501d2674b760837030f14d2d30e150915e8b', 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ ٱلْأَحْزَابِ', 'b9ce97d0595c7835078d06c4cc3b501d2674b760837030f14d2d30e150915e8b', 'b9ce97d0595c7835078d06c4cc3b501d2674b760837030f14d2d30e150915e8b', NULL, 'وقال الذي ءامن يقوم اني اخاف عليكم مثل يوم الاحزاب', 24, 47, 188, 1, 6, 470, false, NULL),
    (4164, 'tanzil-uthmani-v1.1', 40, 31, 'مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعِبَادِ', '21479a197c4c4772baf2d029b2500449c2ce5b7a4a31e618f9e597b0478bc79e', 'مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعِبَادِ', '21479a197c4c4772baf2d029b2500449c2ce5b7a4a31e618f9e597b0478bc79e', '21479a197c4c4772baf2d029b2500449c2ce5b7a4a31e618f9e597b0478bc79e', NULL, 'مثل داب قوم نوح وعاد وثمود والذين من بعدهم وما الله يريد ظلما للعباد', 24, 47, 188, 1, 6, 470, false, NULL),
    (4165, 'tanzil-uthmani-v1.1', 40, 32, 'وَيَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُمْ يَوْمَ ٱلتَّنَادِ', 'c4485db9bc763b4546ee3964d5487875bdcb497dc734829c257eaffe297189af', 'وَيَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُمْ يَوْمَ ٱلتَّنَادِ', 'c4485db9bc763b4546ee3964d5487875bdcb497dc734829c257eaffe297189af', 'c4485db9bc763b4546ee3964d5487875bdcb497dc734829c257eaffe297189af', NULL, 'ويقوم اني اخاف عليكم يوم التناد', 24, 47, 188, 1, 6, 470, false, NULL),
    (4166, 'tanzil-uthmani-v1.1', 40, 33, 'يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '69c2a1255107d46fe64f0d2b284003fc20fe42a4765c264945bcf400b7e34124', 'يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', '69c2a1255107d46fe64f0d2b284003fc20fe42a4765c264945bcf400b7e34124', '69c2a1255107d46fe64f0d2b284003fc20fe42a4765c264945bcf400b7e34124', NULL, 'يوم تولون مدبرين ما لكم من الله من عاصم ومن يضلل الله فما له من هاد', 24, 47, 188, 1, 6, 470, false, NULL),
    (4167, 'tanzil-uthmani-v1.1', 40, 34, 'وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِٱلْبَيِّنَٰتِ فَمَا زِلْتُمْ فِى شَكٍّ مِّمَّا جَآءَكُم بِهِۦ حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ ٱللَّهُ مِنۢ بَعْدِهِۦ رَسُولًا كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنْ هُوَ مُسْرِفٌ مُّرْتَابٌ', 'd14a9e8d91f7561e800e30a56e6fc00751dbee31e091a87dbfe3b63cb2da713a', 'وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِٱلْبَيِّنَٰتِ فَمَا زِلْتُمْ فِى شَكٍّ مِّمَّا جَآءَكُم بِهِۦ حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ ٱللَّهُ مِنۢ بَعْدِهِۦ رَسُولًا كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنْ هُوَ مُسْرِفٌ مُّرْتَابٌ', 'd14a9e8d91f7561e800e30a56e6fc00751dbee31e091a87dbfe3b63cb2da713a', 'd14a9e8d91f7561e800e30a56e6fc00751dbee31e091a87dbfe3b63cb2da713a', NULL, 'ولقد جاءكم يوسف من قبل بالبينت فما زلتم في شك مما جاءكم به حتي اذا هلك قلتم لن يبعث الله من بعده رسولا كذلك يضل الله من هو مسرف مرتاب', 24, 47, 188, 1, 6, 471, false, NULL),
    (4168, 'tanzil-uthmani-v1.1', 40, 35, 'ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ كَبُرَ مَقْتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُوا۟ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ', '56fa7a3249acc48990793763205721f07fccf5a52eb28d3866460a41c8439075', 'ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ كَبُرَ مَقْتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُوا۟ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ', '56fa7a3249acc48990793763205721f07fccf5a52eb28d3866460a41c8439075', '56fa7a3249acc48990793763205721f07fccf5a52eb28d3866460a41c8439075', NULL, 'الذين يجدلون في ءايت الله بغير سلطن اتيهم كبر مقتا عند الله وعند الذين ءامنوا كذلك يطبع الله علي كل قلب متكبر جبار', 24, 47, 188, 1, 6, 471, false, NULL),
    (4169, 'tanzil-uthmani-v1.1', 40, 36, 'وَقَالَ فِرْعَوْنُ يَٰهَٰمَٰنُ ٱبْنِ لِى صَرْحًا لَّعَلِّىٓ أَبْلُغُ ٱلْأَسْبَٰبَ', '7b91ab73307cc40c5becce1ffe2fc2863c130d1cddd94a56935037b731d7f8ff', 'وَقَالَ فِرْعَوْنُ يَٰهَٰمَٰنُ ٱبْنِ لِى صَرْحًا لَّعَلِّىٓ أَبْلُغُ ٱلْأَسْبَٰبَ', '7b91ab73307cc40c5becce1ffe2fc2863c130d1cddd94a56935037b731d7f8ff', '7b91ab73307cc40c5becce1ffe2fc2863c130d1cddd94a56935037b731d7f8ff', NULL, 'وقال فرعون يهمن ابن لي صرحا لعلي ابلغ الاسبب', 24, 47, 188, 1, 6, 471, false, NULL),
    (4170, 'tanzil-uthmani-v1.1', 40, 37, 'أَسْبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ كَٰذِبًا وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَبَابٍ', '923ff8109cb6fa7ba804873abd288d19bacabc88de564f652d7af3144c219c20', 'أَسْبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ كَٰذِبًا وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَبَابٍ', '923ff8109cb6fa7ba804873abd288d19bacabc88de564f652d7af3144c219c20', '923ff8109cb6fa7ba804873abd288d19bacabc88de564f652d7af3144c219c20', NULL, 'اسبب السموت فاطلع الي اله موسي واني لاظنه كذبا وكذلك زين لفرعون سوء عمله وصد عن السبيل وما كيد فرعون الا في تباب', 24, 47, 188, 1, 6, 471, false, NULL),
    (4171, 'tanzil-uthmani-v1.1', 40, 38, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ ٱتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ٱلرَّشَادِ', 'd360d6f0cdd4ff918ddb7593474ab1ea5a3e9df757e35a58721f6ec7ba3f3de0', 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ ٱتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ٱلرَّشَادِ', 'd360d6f0cdd4ff918ddb7593474ab1ea5a3e9df757e35a58721f6ec7ba3f3de0', 'd360d6f0cdd4ff918ddb7593474ab1ea5a3e9df757e35a58721f6ec7ba3f3de0', NULL, 'وقال الذي ءامن يقوم اتبعون اهدكم سبيل الرشاد', 24, 47, 188, 1, 6, 471, false, NULL),
    (4172, 'tanzil-uthmani-v1.1', 40, 39, 'يَٰقَوْمِ إِنَّمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَا مَتَٰعٌ وَإِنَّ ٱلْـَٔاخِرَةَ هِىَ دَارُ ٱلْقَرَارِ', 'ff2ffcca35badfe2c98c0417e13412d0325551302da345bc09290d5a8b8375d7', 'يَٰقَوْمِ إِنَّمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَا مَتَٰعٌ وَإِنَّ ٱلْـَٔاخِرَةَ هِىَ دَارُ ٱلْقَرَارِ', 'ff2ffcca35badfe2c98c0417e13412d0325551302da345bc09290d5a8b8375d7', 'ff2ffcca35badfe2c98c0417e13412d0325551302da345bc09290d5a8b8375d7', NULL, 'يقوم انما هذه الحيوه الدنيا متع وان الاخره هي دار القرار', 24, 47, 188, 1, 6, 471, false, NULL),
    (4173, 'tanzil-uthmani-v1.1', 40, 40, 'مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَمَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ', '84b5cdb67c3f45dfa0089ed27d4b6d4514acea38c5b7b27bdc8d3aeeab87ae71', 'مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَمَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ', '84b5cdb67c3f45dfa0089ed27d4b6d4514acea38c5b7b27bdc8d3aeeab87ae71', '84b5cdb67c3f45dfa0089ed27d4b6d4514acea38c5b7b27bdc8d3aeeab87ae71', NULL, 'من عمل سيئه فلا يجزي الا مثلها ومن عمل صلحا من ذكر او انثي وهو مؤمن فاولئك يدخلون الجنه يرزقون فيها بغير حساب', 24, 47, 188, 1, 6, 471, false, NULL),
    (4174, 'tanzil-uthmani-v1.1', 40, 41, 'وَيَٰقَوْمِ مَا لِىٓ أَدْعُوكُمْ إِلَى ٱلنَّجَوٰةِ وَتَدْعُونَنِىٓ إِلَى ٱلنَّارِ', '32c0534065ccfccf6cd3014d35ab7603dfad905140114ba1ee26f5a282cfd585', 'وَيَٰقَوْمِ مَا لِىٓ أَدْعُوكُمْ إِلَى ٱلنَّجَوٰةِ وَتَدْعُونَنِىٓ إِلَى ٱلنَّارِ', '32c0534065ccfccf6cd3014d35ab7603dfad905140114ba1ee26f5a282cfd585', '32c0534065ccfccf6cd3014d35ab7603dfad905140114ba1ee26f5a282cfd585', NULL, 'ويقوم ما لي ادعوكم الي النجوه وتدعونني الي النار', 24, 48, 189, 1, 6, 472, false, NULL),
    (4175, 'tanzil-uthmani-v1.1', 40, 42, 'تَدْعُونَنِى لِأَكْفُرَ بِٱللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَأَنَا۠ أَدْعُوكُمْ إِلَى ٱلْعَزِيزِ ٱلْغَفَّٰرِ', '0ef6604320d0c3a330d72933bbb844371a9ea96d803f7ffa2fbe8872d4c3e817', 'تَدْعُونَنِى لِأَكْفُرَ بِٱللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَأَنَا۠ أَدْعُوكُمْ إِلَى ٱلْعَزِيزِ ٱلْغَفَّٰرِ', '0ef6604320d0c3a330d72933bbb844371a9ea96d803f7ffa2fbe8872d4c3e817', '0ef6604320d0c3a330d72933bbb844371a9ea96d803f7ffa2fbe8872d4c3e817', NULL, 'تدعونني لاكفر بالله واشرك به ما ليس لي به علم وانا ادعوكم الي العزيز الغفر', 24, 48, 189, 1, 6, 472, false, NULL),
    (4176, 'tanzil-uthmani-v1.1', 40, 43, 'لَا جَرَمَ أَنَّمَا تَدْعُونَنِىٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةٌ فِى ٱلدُّنْيَا وَلَا فِى ٱلْـَٔاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلْمُسْرِفِينَ هُمْ أَصْحَٰبُ ٱلنَّارِ', '8f6949bef250df9fc772bf974136dfcaf73091bcdf19e585d5597d6e1b1ddef8', 'لَا جَرَمَ أَنَّمَا تَدْعُونَنِىٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةٌ فِى ٱلدُّنْيَا وَلَا فِى ٱلْـَٔاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلْمُسْرِفِينَ هُمْ أَصْحَٰبُ ٱلنَّارِ', '8f6949bef250df9fc772bf974136dfcaf73091bcdf19e585d5597d6e1b1ddef8', '8f6949bef250df9fc772bf974136dfcaf73091bcdf19e585d5597d6e1b1ddef8', NULL, 'لا جرم انما تدعونني اليه ليس له دعوه في الدنيا ولا في الاخره وان مردنا الي الله وان المسرفين هم اصحب النار', 24, 48, 189, 1, 6, 472, false, NULL),
    (4177, 'tanzil-uthmani-v1.1', 40, 44, 'فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ وَأُفَوِّضُ أَمْرِىٓ إِلَى ٱللَّهِ إِنَّ ٱللَّهَ بَصِيرٌۢ بِٱلْعِبَادِ', '78b22f380522a3bdd5485fbe7573cbb5de9f69c5549f0d8a7ef66a9aba6c16f1', 'فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ وَأُفَوِّضُ أَمْرِىٓ إِلَى ٱللَّهِ إِنَّ ٱللَّهَ بَصِيرٌۢ بِٱلْعِبَادِ', '78b22f380522a3bdd5485fbe7573cbb5de9f69c5549f0d8a7ef66a9aba6c16f1', '78b22f380522a3bdd5485fbe7573cbb5de9f69c5549f0d8a7ef66a9aba6c16f1', NULL, 'فستذكرون ما اقول لكم وافوض امري الي الله ان الله بصير بالعباد', 24, 48, 189, 1, 6, 472, false, NULL),
    (4178, 'tanzil-uthmani-v1.1', 40, 45, 'فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُوا۟ وَحَاقَ بِـَٔالِ فِرْعَوْنَ سُوٓءُ ٱلْعَذَابِ', '7f807e10db380c4420d50aa3590b025ebf325cf6f0da32062b61fa0429bcbee7', 'فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُوا۟ وَحَاقَ بِـَٔالِ فِرْعَوْنَ سُوٓءُ ٱلْعَذَابِ', '7f807e10db380c4420d50aa3590b025ebf325cf6f0da32062b61fa0429bcbee7', '7f807e10db380c4420d50aa3590b025ebf325cf6f0da32062b61fa0429bcbee7', NULL, 'فوقيه الله سيات ما مكروا وحاق بال فرعون سوء العذاب', 24, 48, 189, 1, 6, 472, false, NULL),
    (4179, 'tanzil-uthmani-v1.1', 40, 46, 'ٱلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ ٱلسَّاعَةُ أَدْخِلُوٓا۟ ءَالَ فِرْعَوْنَ أَشَدَّ ٱلْعَذَابِ', '43bdc0c8e4b646090fd8c9844dc2e42d7bfa5ba4d0e10caa4d8625a992e60e69', 'ٱلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ ٱلسَّاعَةُ أَدْخِلُوٓا۟ ءَالَ فِرْعَوْنَ أَشَدَّ ٱلْعَذَابِ', '43bdc0c8e4b646090fd8c9844dc2e42d7bfa5ba4d0e10caa4d8625a992e60e69', '43bdc0c8e4b646090fd8c9844dc2e42d7bfa5ba4d0e10caa4d8625a992e60e69', NULL, 'النار يعرضون عليها غدوا وعشيا ويوم تقوم الساعه ادخلوا ءال فرعون اشد العذاب', 24, 48, 189, 1, 6, 472, false, NULL),
    (4180, 'tanzil-uthmani-v1.1', 40, 47, 'وَإِذْ يَتَحَآجُّونَ فِى ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًا مِّنَ ٱلنَّارِ', '1118259a930547cb6b1cde1d636988bd2f59594a9023715fcb2e099ee893c0ea', 'وَإِذْ يَتَحَآجُّونَ فِى ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًا مِّنَ ٱلنَّارِ', '1118259a930547cb6b1cde1d636988bd2f59594a9023715fcb2e099ee893c0ea', '1118259a930547cb6b1cde1d636988bd2f59594a9023715fcb2e099ee893c0ea', NULL, 'واذ يتحاجون في النار فيقول الضعفؤا للذين استكبروا انا كنا لكم تبعا فهل انتم مغنون عنا نصيبا من النار', 24, 48, 189, 1, 6, 472, false, NULL),
    (4181, 'tanzil-uthmani-v1.1', 40, 48, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُلٌّ فِيهَآ إِنَّ ٱللَّهَ قَدْ حَكَمَ بَيْنَ ٱلْعِبَادِ', 'a3e0b17041c5473131fdb6e65eb821ff10442d6650f105ce05e08b440b0326ac', 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُلٌّ فِيهَآ إِنَّ ٱللَّهَ قَدْ حَكَمَ بَيْنَ ٱلْعِبَادِ', 'a3e0b17041c5473131fdb6e65eb821ff10442d6650f105ce05e08b440b0326ac', 'a3e0b17041c5473131fdb6e65eb821ff10442d6650f105ce05e08b440b0326ac', NULL, 'قال الذين استكبروا انا كل فيها ان الله قد حكم بين العباد', 24, 48, 189, 1, 6, 472, false, NULL),
    (4182, 'tanzil-uthmani-v1.1', 40, 49, 'وَقَالَ ٱلَّذِينَ فِى ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدْعُوا۟ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًا مِّنَ ٱلْعَذَابِ', '016be1004ecd906b771a858a56cfc9d99fe74100dd83bb6f1fd1918516308d97', 'وَقَالَ ٱلَّذِينَ فِى ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدْعُوا۟ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًا مِّنَ ٱلْعَذَابِ', '016be1004ecd906b771a858a56cfc9d99fe74100dd83bb6f1fd1918516308d97', '016be1004ecd906b771a858a56cfc9d99fe74100dd83bb6f1fd1918516308d97', NULL, 'وقال الذين في النار لخزنه جهنم ادعوا ربكم يخفف عنا يوما من العذاب', 24, 48, 189, 1, 6, 472, false, NULL),
    (4183, 'tanzil-uthmani-v1.1', 40, 50, 'قَالُوٓا۟ أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِٱلْبَيِّنَٰتِ قَالُوا۟ بَلَىٰ قَالُوا۟ فَٱدْعُوا۟ وَمَا دُعَٰٓؤُا۟ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', '8ccaa6dd48e045d63329743289cbfac8e2fb96ee4599da3e3383a90b974c9c56', 'قَالُوٓا۟ أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِٱلْبَيِّنَٰتِ قَالُوا۟ بَلَىٰ قَالُوا۟ فَٱدْعُوا۟ وَمَا دُعَٰٓؤُا۟ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', '8ccaa6dd48e045d63329743289cbfac8e2fb96ee4599da3e3383a90b974c9c56', '8ccaa6dd48e045d63329743289cbfac8e2fb96ee4599da3e3383a90b974c9c56', NULL, 'قالوا اولم تك تاتيكم رسلكم بالبينت قالوا بلي قالوا فادعوا وما دعؤا الكفرين الا في ضلل', 24, 48, 189, 1, 6, 473, false, NULL),
    (4184, 'tanzil-uthmani-v1.1', 40, 51, 'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ يَقُومُ ٱلْأَشْهَٰدُ', '537694b14cef022b0e95ec0d4429e6996ea4292620fa254d6ddbe2d52fbdd7a8', 'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ يَقُومُ ٱلْأَشْهَٰدُ', '537694b14cef022b0e95ec0d4429e6996ea4292620fa254d6ddbe2d52fbdd7a8', '537694b14cef022b0e95ec0d4429e6996ea4292620fa254d6ddbe2d52fbdd7a8', NULL, 'انا لننصر رسلنا والذين ءامنوا في الحيوه الدنيا ويوم يقوم الاشهد', 24, 48, 189, 1, 6, 473, false, NULL),
    (4185, 'tanzil-uthmani-v1.1', 40, 52, 'يَوْمَ لَا يَنفَعُ ٱلظَّٰلِمِينَ مَعْذِرَتُهُمْ وَلَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', '7b8b3e04299e8368e66207ce2ebe205508368b6a334ab8ba2687b13c2780eeac', 'يَوْمَ لَا يَنفَعُ ٱلظَّٰلِمِينَ مَعْذِرَتُهُمْ وَلَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', '7b8b3e04299e8368e66207ce2ebe205508368b6a334ab8ba2687b13c2780eeac', '7b8b3e04299e8368e66207ce2ebe205508368b6a334ab8ba2687b13c2780eeac', NULL, 'يوم لا ينفع الظلمين معذرتهم ولهم اللعنه ولهم سوء الدار', 24, 48, 189, 1, 6, 473, false, NULL),
    (4186, 'tanzil-uthmani-v1.1', 40, 53, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ', 'c3964914c34d3aa3f1a85c7ba1cda54bb5a82626d7ff98f8f524597fd661d024', 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ', 'c3964914c34d3aa3f1a85c7ba1cda54bb5a82626d7ff98f8f524597fd661d024', 'c3964914c34d3aa3f1a85c7ba1cda54bb5a82626d7ff98f8f524597fd661d024', NULL, 'ولقد ءاتينا موسي الهدي واورثنا بني اسرءيل الكتب', 24, 48, 189, 1, 6, 473, false, NULL),
    (4187, 'tanzil-uthmani-v1.1', 40, 54, 'هُدًى وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', '5c3ff4661e6b69bfbcb92ce45f8ebe2238a1f275cee59223d1e591b218363396', 'هُدًى وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', '5c3ff4661e6b69bfbcb92ce45f8ebe2238a1f275cee59223d1e591b218363396', '5c3ff4661e6b69bfbcb92ce45f8ebe2238a1f275cee59223d1e591b218363396', NULL, 'هدي وذكري لاولي الالبب', 24, 48, 189, 1, 6, 473, false, NULL),
    (4188, 'tanzil-uthmani-v1.1', 40, 55, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', '111e23b307d9112f149a29cde3546748208229d7a226e143beb6607be949d2b6', 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', '111e23b307d9112f149a29cde3546748208229d7a226e143beb6607be949d2b6', '111e23b307d9112f149a29cde3546748208229d7a226e143beb6607be949d2b6', NULL, 'فاصبر ان وعد الله حق واستغفر لذنبك وسبح بحمد ربك بالعشي والابكر', 24, 48, 189, 1, 6, 473, false, NULL),
    (4189, 'tanzil-uthmani-v1.1', 40, 56, 'إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ إِن فِى صُدُورِهِمْ إِلَّا كِبْرٌ مَّا هُم بِبَٰلِغِيهِ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'fd6c81bf409a52a384b1841d29f87b93d1f69679ff308400ce2c8f5560a6d823', 'إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ إِن فِى صُدُورِهِمْ إِلَّا كِبْرٌ مَّا هُم بِبَٰلِغِيهِ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 'fd6c81bf409a52a384b1841d29f87b93d1f69679ff308400ce2c8f5560a6d823', 'fd6c81bf409a52a384b1841d29f87b93d1f69679ff308400ce2c8f5560a6d823', NULL, 'ان الذين يجدلون في ءايت الله بغير سلطن اتيهم ان في صدورهم الا كبر ما هم ببلغيه فاستعذ بالله انه هو السميع البصير', 24, 48, 189, 1, 6, 473, false, NULL),
    (4190, 'tanzil-uthmani-v1.1', 40, 57, 'لَخَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'e6cd99f95c5a5ee56c7fca74a7f915fd473c1142e904698027dde1fc2eb2d9c6', 'لَخَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 'e6cd99f95c5a5ee56c7fca74a7f915fd473c1142e904698027dde1fc2eb2d9c6', 'e6cd99f95c5a5ee56c7fca74a7f915fd473c1142e904698027dde1fc2eb2d9c6', NULL, 'لخلق السموت والارض اكبر من خلق الناس ولكن اكثر الناس لا يعلمون', 24, 48, 189, 1, 6, 473, false, NULL),
    (4191, 'tanzil-uthmani-v1.1', 40, 58, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَلَا ٱلْمُسِىٓءُ قَلِيلًا مَّا تَتَذَكَّرُونَ', '0b57bfa269522c72066899aeb4cc743f5b3beb9ec0810ceff524ac50b675719a', 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَلَا ٱلْمُسِىٓءُ قَلِيلًا مَّا تَتَذَكَّرُونَ', '0b57bfa269522c72066899aeb4cc743f5b3beb9ec0810ceff524ac50b675719a', '0b57bfa269522c72066899aeb4cc743f5b3beb9ec0810ceff524ac50b675719a', NULL, 'وما يستوي الاعمي والبصير والذين ءامنوا وعملوا الصلحت ولا المسيء قليلا ما تتذكرون', 24, 48, 189, 1, 6, 473, false, NULL),
    (4192, 'tanzil-uthmani-v1.1', 40, 59, 'إِنَّ ٱلسَّاعَةَ لَـَٔاتِيَةٌ لَّا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'ef091e8635abc4dd21f89a344e1c6aab5a29d062106c3db3b3642b2d73a5d7f7', 'إِنَّ ٱلسَّاعَةَ لَـَٔاتِيَةٌ لَّا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 'ef091e8635abc4dd21f89a344e1c6aab5a29d062106c3db3b3642b2d73a5d7f7', 'ef091e8635abc4dd21f89a344e1c6aab5a29d062106c3db3b3642b2d73a5d7f7', NULL, 'ان الساعه لاتيه لا ريب فيها ولكن اكثر الناس لا يؤمنون', 24, 48, 189, 1, 6, 474, false, NULL),
    (4193, 'tanzil-uthmani-v1.1', 40, 60, 'وَقَالَ رَبُّكُمُ ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', '493b29b072b32f540198704243d8573aae628a7ab072cfb97fa4e9c69c342033', 'وَقَالَ رَبُّكُمُ ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', '493b29b072b32f540198704243d8573aae628a7ab072cfb97fa4e9c69c342033', '493b29b072b32f540198704243d8573aae628a7ab072cfb97fa4e9c69c342033', NULL, 'وقال ربكم ادعوني استجب لكم ان الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين', 24, 48, 189, 1, 6, 474, false, NULL),
    (4194, 'tanzil-uthmani-v1.1', 40, 61, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', '53fb597b7de6402db6e482d8726bd9bad6d277649e9e375d9b72208c66619c1d', 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', '53fb597b7de6402db6e482d8726bd9bad6d277649e9e375d9b72208c66619c1d', '53fb597b7de6402db6e482d8726bd9bad6d277649e9e375d9b72208c66619c1d', NULL, 'الله الذي جعل لكم اليل لتسكنوا فيه والنهار مبصرا ان الله لذو فضل علي الناس ولكن اكثر الناس لا يشكرون', 24, 48, 189, 1, 6, 474, false, NULL),
    (4195, 'tanzil-uthmani-v1.1', 40, 62, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ خَٰلِقُ كُلِّ شَىْءٍ لَّآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ', 'a86fc651db60d73ac30aee1f271f538e300d0b40db3a8a67f6db4d29e960eb32', 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ خَٰلِقُ كُلِّ شَىْءٍ لَّآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ', 'a86fc651db60d73ac30aee1f271f538e300d0b40db3a8a67f6db4d29e960eb32', 'a86fc651db60d73ac30aee1f271f538e300d0b40db3a8a67f6db4d29e960eb32', NULL, 'ذلكم الله ربكم خلق كل شيء لا اله الا هو فاني تؤفكون', 24, 48, 189, 1, 6, 474, false, NULL),
    (4196, 'tanzil-uthmani-v1.1', 40, 63, 'كَذَٰلِكَ يُؤْفَكُ ٱلَّذِينَ كَانُوا۟ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', '9715dd54ef819bb3a069f7166dd24bec205f8645196a0714987d5d84fc0718bd', 'كَذَٰلِكَ يُؤْفَكُ ٱلَّذِينَ كَانُوا۟ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', '9715dd54ef819bb3a069f7166dd24bec205f8645196a0714987d5d84fc0718bd', '9715dd54ef819bb3a069f7166dd24bec205f8645196a0714987d5d84fc0718bd', NULL, 'كذلك يؤفك الذين كانوا بايت الله يجحدون', 24, 48, 189, 1, 6, 474, false, NULL),
    (4197, 'tanzil-uthmani-v1.1', 40, 64, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ قَرَارًا وَٱلسَّمَآءَ بِنَآءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'a28b05e0b508add48eaba789cf8b3845fbcab8b984a3db44dd0ed5e791bf1b64', 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ قَرَارًا وَٱلسَّمَآءَ بِنَآءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 'a28b05e0b508add48eaba789cf8b3845fbcab8b984a3db44dd0ed5e791bf1b64', 'a28b05e0b508add48eaba789cf8b3845fbcab8b984a3db44dd0ed5e791bf1b64', NULL, 'الله الذي جعل لكم الارض قرارا والسماء بناء وصوركم فاحسن صوركم ورزقكم من الطيبت ذلكم الله ربكم فتبارك الله رب العلمين', 24, 48, 189, 1, 6, 474, false, NULL),
    (4198, 'tanzil-uthmani-v1.1', 40, 65, 'هُوَ ٱلْحَىُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'b18f6527c1fbcc7f426dcbe793d4f6cf11a0dfdd28c7c03eebbb08aa42f71a4b', 'هُوَ ٱلْحَىُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 'b18f6527c1fbcc7f426dcbe793d4f6cf11a0dfdd28c7c03eebbb08aa42f71a4b', 'b18f6527c1fbcc7f426dcbe793d4f6cf11a0dfdd28c7c03eebbb08aa42f71a4b', NULL, 'هو الحي لا اله الا هو فادعوه مخلصين له الدين الحمد لله رب العلمين', 24, 48, 189, 1, 6, 474, false, NULL),
    (4199, 'tanzil-uthmani-v1.1', 40, 66, 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِىَ ٱلْبَيِّنَٰتُ مِن رَّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', '4da95fe9c032446dca6091fcde3f531acd9dd3f7f21b5f51d2ee583cea88b519', 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِىَ ٱلْبَيِّنَٰتُ مِن رَّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', '4da95fe9c032446dca6091fcde3f531acd9dd3f7f21b5f51d2ee583cea88b519', '4da95fe9c032446dca6091fcde3f531acd9dd3f7f21b5f51d2ee583cea88b519', NULL, 'قل اني نهيت ان اعبد الذين تدعون من دون الله لما جاءني البينت من ربي وامرت ان اسلم لرب العلمين', 24, 48, 190, 1, 6, 474, false, NULL),
    (4200, 'tanzil-uthmani-v1.1', 40, 67, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ثُمَّ لِتَكُونُوا۟ شُيُوخًا وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ وَلِتَبْلُغُوٓا۟ أَجَلًا مُّسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ', '7d6a38da5f0c2f05494154ce09ddec79821b16dca0c51ebbd715773fde98fd75', 'هُوَ ٱلَّذِى خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ثُمَّ لِتَكُونُوا۟ شُيُوخًا وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ وَلِتَبْلُغُوٓا۟ أَجَلًا مُّسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ', '7d6a38da5f0c2f05494154ce09ddec79821b16dca0c51ebbd715773fde98fd75', '7d6a38da5f0c2f05494154ce09ddec79821b16dca0c51ebbd715773fde98fd75', NULL, 'هو الذي خلقكم من تراب ثم من نطفه ثم من علقه ثم يخرجكم طفلا ثم لتبلغوا اشدكم ثم لتكونوا شيوخا ومنكم من يتوفي من قبل ولتبلغوا اجلا مسمي ولعلكم تعقلون', 24, 48, 190, 1, 6, 475, false, NULL),
    (4201, 'tanzil-uthmani-v1.1', 40, 68, 'هُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ فَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '062be75f98beb60da6497ecb82dd3870a79da09597d496128c3b284efa085fda', 'هُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ فَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', '062be75f98beb60da6497ecb82dd3870a79da09597d496128c3b284efa085fda', '062be75f98beb60da6497ecb82dd3870a79da09597d496128c3b284efa085fda', NULL, 'هو الذي يحي ويميت فاذا قضي امرا فانما يقول له كن فيكون', 24, 48, 190, 1, 6, 475, false, NULL),
    (4202, 'tanzil-uthmani-v1.1', 40, 69, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصْرَفُونَ', '00e3f84b9da7a60d1953d1b0e34e2d080368dc40baba0a20f936e75ae5b9c97e', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصْرَفُونَ', '00e3f84b9da7a60d1953d1b0e34e2d080368dc40baba0a20f936e75ae5b9c97e', '00e3f84b9da7a60d1953d1b0e34e2d080368dc40baba0a20f936e75ae5b9c97e', NULL, 'الم تر الي الذين يجدلون في ءايت الله اني يصرفون', 24, 48, 190, 1, 6, 475, false, NULL),
    (4203, 'tanzil-uthmani-v1.1', 40, 70, 'ٱلَّذِينَ كَذَّبُوا۟ بِٱلْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا فَسَوْفَ يَعْلَمُونَ', '73d2089c2f0cab4f8c5c8b1fc3c8c1cabc8df925d695b314d8dbefaf758ca030', 'ٱلَّذِينَ كَذَّبُوا۟ بِٱلْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا فَسَوْفَ يَعْلَمُونَ', '73d2089c2f0cab4f8c5c8b1fc3c8c1cabc8df925d695b314d8dbefaf758ca030', '73d2089c2f0cab4f8c5c8b1fc3c8c1cabc8df925d695b314d8dbefaf758ca030', NULL, 'الذين كذبوا بالكتب وبما ارسلنا به رسلنا فسوف يعلمون', 24, 48, 190, 1, 6, 475, false, NULL),
    (4204, 'tanzil-uthmani-v1.1', 40, 71, 'إِذِ ٱلْأَغْلَٰلُ فِىٓ أَعْنَٰقِهِمْ وَٱلسَّلَٰسِلُ يُسْحَبُونَ', '1201f960776427b5adc49f8c2d0dba85320f88ba18998dae99fc569546ad47e4', 'إِذِ ٱلْأَغْلَٰلُ فِىٓ أَعْنَٰقِهِمْ وَٱلسَّلَٰسِلُ يُسْحَبُونَ', '1201f960776427b5adc49f8c2d0dba85320f88ba18998dae99fc569546ad47e4', '1201f960776427b5adc49f8c2d0dba85320f88ba18998dae99fc569546ad47e4', NULL, 'اذ الاغلل في اعنقهم والسلسل يسحبون', 24, 48, 190, 1, 6, 475, false, NULL),
    (4205, 'tanzil-uthmani-v1.1', 40, 72, 'فِى ٱلْحَمِيمِ ثُمَّ فِى ٱلنَّارِ يُسْجَرُونَ', '9da8a05baa2b79d66d8cbc134911ce3dd59faaa59961176d1c279e782a4e6085', 'فِى ٱلْحَمِيمِ ثُمَّ فِى ٱلنَّارِ يُسْجَرُونَ', '9da8a05baa2b79d66d8cbc134911ce3dd59faaa59961176d1c279e782a4e6085', '9da8a05baa2b79d66d8cbc134911ce3dd59faaa59961176d1c279e782a4e6085', NULL, 'في الحميم ثم في النار يسجرون', 24, 48, 190, 1, 6, 475, false, NULL),
    (4206, 'tanzil-uthmani-v1.1', 40, 73, 'ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ', '78f1b3e320c602c873e5d6165a5322ad678ffe0d9a841d662e99a58c71042602', 'ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ', '78f1b3e320c602c873e5d6165a5322ad678ffe0d9a841d662e99a58c71042602', '78f1b3e320c602c873e5d6165a5322ad678ffe0d9a841d662e99a58c71042602', NULL, 'ثم قيل لهم اين ما كنتم تشركون', 24, 48, 190, 1, 6, 475, false, NULL),
    (4207, 'tanzil-uthmani-v1.1', 40, 74, 'مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمْ نَكُن نَّدْعُوا۟ مِن قَبْلُ شَيْـًٔا كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلْكَٰفِرِينَ', '56a92a418a9e20e200fba38128566cbdd30f747250ed7a98c182bea43b7b2d91', 'مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمْ نَكُن نَّدْعُوا۟ مِن قَبْلُ شَيْـًٔا كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلْكَٰفِرِينَ', '56a92a418a9e20e200fba38128566cbdd30f747250ed7a98c182bea43b7b2d91', '56a92a418a9e20e200fba38128566cbdd30f747250ed7a98c182bea43b7b2d91', NULL, 'من دون الله قالوا ضلوا عنا بل لم نكن ندعوا من قبل شيا كذلك يضل الله الكفرين', 24, 48, 190, 1, 6, 475, false, NULL),
    (4208, 'tanzil-uthmani-v1.1', 40, 75, 'ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ', '234c23c83edc9a9497be11dcc422083c25f98c2346763526078424fdd26b5066', 'ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ', '234c23c83edc9a9497be11dcc422083c25f98c2346763526078424fdd26b5066', '234c23c83edc9a9497be11dcc422083c25f98c2346763526078424fdd26b5066', NULL, 'ذلكم بما كنتم تفرحون في الارض بغير الحق وبما كنتم تمرحون', 24, 48, 190, 1, 6, 475, false, NULL),
    (4209, 'tanzil-uthmani-v1.1', 40, 76, 'ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', '29541f2d9a3d1f476205ae9033897d7e7813d09bac186d0df39fa7ebc989fe78', 'ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', '29541f2d9a3d1f476205ae9033897d7e7813d09bac186d0df39fa7ebc989fe78', '29541f2d9a3d1f476205ae9033897d7e7813d09bac186d0df39fa7ebc989fe78', NULL, 'ادخلوا ابوب جهنم خلدين فيها فبئس مثوي المتكبرين', 24, 48, 190, 1, 6, 475, false, NULL),
    (4210, 'tanzil-uthmani-v1.1', 40, 77, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ', '61fafda7382df0873f2af6a116a51a4bfd8ca9e08bdc6601f827c7c4a4ec579d', 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ', '61fafda7382df0873f2af6a116a51a4bfd8ca9e08bdc6601f827c7c4a4ec579d', '61fafda7382df0873f2af6a116a51a4bfd8ca9e08bdc6601f827c7c4a4ec579d', NULL, 'فاصبر ان وعد الله حق فاما نرينك بعض الذي نعدهم او نتوفينك فالينا يرجعون', 24, 48, 190, 1, 6, 475, false, NULL),
    (4211, 'tanzil-uthmani-v1.1', 40, 78, 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ فَإِذَا جَآءَ أَمْرُ ٱللَّهِ قُضِىَ بِٱلْحَقِّ وَخَسِرَ هُنَالِكَ ٱلْمُبْطِلُونَ', '80426c222aaab9aff63e126a104a0e59bee76d5f05522610f7cbf5d6250baa95', 'وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ فَإِذَا جَآءَ أَمْرُ ٱللَّهِ قُضِىَ بِٱلْحَقِّ وَخَسِرَ هُنَالِكَ ٱلْمُبْطِلُونَ', '80426c222aaab9aff63e126a104a0e59bee76d5f05522610f7cbf5d6250baa95', '80426c222aaab9aff63e126a104a0e59bee76d5f05522610f7cbf5d6250baa95', NULL, 'ولقد ارسلنا رسلا من قبلك منهم من قصصنا عليك ومنهم من لم نقصص عليك وما كان لرسول ان ياتي بايه الا باذن الله فاذا جاء امر الله قضي بالحق وخسر هنالك المبطلون', 24, 48, 190, 1, 6, 476, false, NULL),
    (4212, 'tanzil-uthmani-v1.1', 40, 79, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَنْعَٰمَ لِتَرْكَبُوا۟ مِنْهَا وَمِنْهَا تَأْكُلُونَ', '2c5078254b7295d025ef517d9d21acbde160c8044aa6702873dbaaee929942e6', 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَنْعَٰمَ لِتَرْكَبُوا۟ مِنْهَا وَمِنْهَا تَأْكُلُونَ', '2c5078254b7295d025ef517d9d21acbde160c8044aa6702873dbaaee929942e6', '2c5078254b7295d025ef517d9d21acbde160c8044aa6702873dbaaee929942e6', NULL, 'الله الذي جعل لكم الانعم لتركبوا منها ومنها تاكلون', 24, 48, 190, 1, 6, 476, false, NULL),
    (4213, 'tanzil-uthmani-v1.1', 40, 80, 'وَلَكُمْ فِيهَا مَنَٰفِعُ وَلِتَبْلُغُوا۟ عَلَيْهَا حَاجَةً فِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 'e8fe2fc6d5adfec6e024532885f091bda8de357e782dc81bf737e5812bd0024b', 'وَلَكُمْ فِيهَا مَنَٰفِعُ وَلِتَبْلُغُوا۟ عَلَيْهَا حَاجَةً فِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 'e8fe2fc6d5adfec6e024532885f091bda8de357e782dc81bf737e5812bd0024b', 'e8fe2fc6d5adfec6e024532885f091bda8de357e782dc81bf737e5812bd0024b', NULL, 'ولكم فيها منفع ولتبلغوا عليها حاجه في صدوركم وعليها وعلي الفلك تحملون', 24, 48, 190, 1, 6, 476, false, NULL),
    (4214, 'tanzil-uthmani-v1.1', 40, 81, 'وَيُرِيكُمْ ءَايَٰتِهِۦ فَأَىَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ', 'ef29daab0a69768c0c7321c61ab237b1d0dba64a7da3cb0e6513ea924ec1be33', 'وَيُرِيكُمْ ءَايَٰتِهِۦ فَأَىَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ', 'ef29daab0a69768c0c7321c61ab237b1d0dba64a7da3cb0e6513ea924ec1be33', 'ef29daab0a69768c0c7321c61ab237b1d0dba64a7da3cb0e6513ea924ec1be33', NULL, 'ويريكم ءايته فاي ءايت الله تنكرون', 24, 48, 190, 1, 6, 476, false, NULL),
    (4215, 'tanzil-uthmani-v1.1', 40, 82, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ كَانُوٓا۟ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'bc67223926a3e6501b98356850cd203e9f427513fd2ae87b4a333bfd0d16577b', 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ كَانُوٓا۟ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 'bc67223926a3e6501b98356850cd203e9f427513fd2ae87b4a333bfd0d16577b', 'bc67223926a3e6501b98356850cd203e9f427513fd2ae87b4a333bfd0d16577b', NULL, 'افلم يسيروا في الارض فينظروا كيف كان عقبه الذين من قبلهم كانوا اكثر منهم واشد قوه وءاثارا في الارض فما اغني عنهم ما كانوا يكسبون', 24, 48, 190, 1, 6, 476, false, NULL),
    (4216, 'tanzil-uthmani-v1.1', 40, 83, 'فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '4b182cdc8181839eba67170bf4b60bbe33e9d85f7c6efba634d4c213c94a53b5', 'فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '4b182cdc8181839eba67170bf4b60bbe33e9d85f7c6efba634d4c213c94a53b5', '4b182cdc8181839eba67170bf4b60bbe33e9d85f7c6efba634d4c213c94a53b5', NULL, 'فلما جاءتهم رسلهم بالبينت فرحوا بما عندهم من العلم وحاق بهم ما كانوا به يستهزءون', 24, 48, 190, 1, 6, 476, false, NULL),
    (4217, 'tanzil-uthmani-v1.1', 40, 84, 'فَلَمَّا رَأَوْا۟ بَأْسَنَا قَالُوٓا۟ ءَامَنَّا بِٱللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ', 'e43f62963bd7445494e357ca4e2a2f1f1366fd52ebb1f0274fc209958ae020a7', 'فَلَمَّا رَأَوْا۟ بَأْسَنَا قَالُوٓا۟ ءَامَنَّا بِٱللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ', 'e43f62963bd7445494e357ca4e2a2f1f1366fd52ebb1f0274fc209958ae020a7', 'e43f62963bd7445494e357ca4e2a2f1f1366fd52ebb1f0274fc209958ae020a7', NULL, 'فلما راوا باسنا قالوا ءامنا بالله وحده وكفرنا بما كنا به مشركين', 24, 48, 190, 1, 6, 476, false, NULL),
    (4218, 'tanzil-uthmani-v1.1', 40, 85, 'فَلَمْ يَكُ يَنفَعُهُمْ إِيمَٰنُهُمْ لَمَّا رَأَوْا۟ بَأْسَنَا سُنَّتَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ فِى عِبَادِهِۦ وَخَسِرَ هُنَالِكَ ٱلْكَٰفِرُونَ', '41907f63436a6d71800c3eaf40ab5c6f29583433ab8e3001794e8108712e2a71', 'فَلَمْ يَكُ يَنفَعُهُمْ إِيمَٰنُهُمْ لَمَّا رَأَوْا۟ بَأْسَنَا سُنَّتَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ فِى عِبَادِهِۦ وَخَسِرَ هُنَالِكَ ٱلْكَٰفِرُونَ', '41907f63436a6d71800c3eaf40ab5c6f29583433ab8e3001794e8108712e2a71', '41907f63436a6d71800c3eaf40ab5c6f29583433ab8e3001794e8108712e2a71', NULL, 'فلم يك ينفعهم ايمنهم لما راوا باسنا سنت الله التي قد خلت في عباده وخسر هنالك الكفرون', 24, 48, 190, 1, 6, 476, false, NULL),
    (4219, 'tanzil-uthmani-v1.1', 41, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'b4f3f13e19bbe78e5f72edb60140cdae2eb77fceae263ed0d2b48f30c7cc67fd', 'حمٓ', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'حم', 24, 48, 190, 1, 6, 477, false, NULL),
