    (4221, 'tanzil-uthmani-v1.1', 41, 3, 'كِتَٰبٌ فُصِّلَتْ ءَايَٰتُهُۥ قُرْءَانًا عَرَبِيًّا لِّقَوْمٍ يَعْلَمُونَ', 'e6a8084d3ee00ddf40a48eb3b1f632f115c02bcf2bd002e9d6c478736ea1236e', 'كِتَٰبٌ فُصِّلَتْ ءَايَٰتُهُۥ قُرْءَانًا عَرَبِيًّا لِّقَوْمٍ يَعْلَمُونَ', 'e6a8084d3ee00ddf40a48eb3b1f632f115c02bcf2bd002e9d6c478736ea1236e', 'e6a8084d3ee00ddf40a48eb3b1f632f115c02bcf2bd002e9d6c478736ea1236e', NULL, 'كتب فصلت ءايته قرءانا عربيا لقوم يعلمون', 24, 48, 190, 1, 6, 477, false, NULL),
    (4222, 'tanzil-uthmani-v1.1', 41, 4, 'بَشِيرًا وَنَذِيرًا فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ', 'bcc965ee090ce66a95d47224553dac8dcadcb63b942122371ef20260cf462dfc', 'بَشِيرًا وَنَذِيرًا فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ', 'bcc965ee090ce66a95d47224553dac8dcadcb63b942122371ef20260cf462dfc', 'bcc965ee090ce66a95d47224553dac8dcadcb63b942122371ef20260cf462dfc', NULL, 'بشيرا ونذيرا فاعرض اكثرهم فهم لا يسمعون', 24, 48, 190, 1, 6, 477, false, NULL),
    (4223, 'tanzil-uthmani-v1.1', 41, 5, 'وَقَالُوا۟ قُلُوبُنَا فِىٓ أَكِنَّةٍ مِّمَّا تَدْعُونَآ إِلَيْهِ وَفِىٓ ءَاذَانِنَا وَقْرٌ وَمِنۢ بَيْنِنَا وَبَيْنِكَ حِجَابٌ فَٱعْمَلْ إِنَّنَا عَٰمِلُونَ', '71a79528568f6a74d461a1821d9a670ab71b3a0399f173c5e06555a95081d1c5', 'وَقَالُوا۟ قُلُوبُنَا فِىٓ أَكِنَّةٍ مِّمَّا تَدْعُونَآ إِلَيْهِ وَفِىٓ ءَاذَانِنَا وَقْرٌ وَمِنۢ بَيْنِنَا وَبَيْنِكَ حِجَابٌ فَٱعْمَلْ إِنَّنَا عَٰمِلُونَ', '71a79528568f6a74d461a1821d9a670ab71b3a0399f173c5e06555a95081d1c5', '71a79528568f6a74d461a1821d9a670ab71b3a0399f173c5e06555a95081d1c5', NULL, 'وقالوا قلوبنا في اكنه مما تدعونا اليه وفي ءاذاننا وقر ومن بيننا وبينك حجاب فاعمل اننا عملون', 24, 48, 190, 1, 6, 477, false, NULL),
    (4224, 'tanzil-uthmani-v1.1', 41, 6, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَٱسْتَقِيمُوٓا۟ إِلَيْهِ وَٱسْتَغْفِرُوهُ وَوَيْلٌ لِّلْمُشْرِكِينَ', 'd18f8cf97c2aa38474384924f13309aeb14e39f6a1f1f5a499bfc42c8740c118', 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَٱسْتَقِيمُوٓا۟ إِلَيْهِ وَٱسْتَغْفِرُوهُ وَوَيْلٌ لِّلْمُشْرِكِينَ', 'd18f8cf97c2aa38474384924f13309aeb14e39f6a1f1f5a499bfc42c8740c118', 'd18f8cf97c2aa38474384924f13309aeb14e39f6a1f1f5a499bfc42c8740c118', NULL, 'قل انما انا بشر مثلكم يوحي الي انما الهكم اله وحد فاستقيموا اليه واستغفروه وويل للمشركين', 24, 48, 190, 1, 6, 477, false, NULL),
    (4225, 'tanzil-uthmani-v1.1', 41, 7, 'ٱلَّذِينَ لَا يُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ', '5e8e548fccf4e4d813cc3ed488bb0dce5fc5a2533accccdb10b10581e101caa8', 'ٱلَّذِينَ لَا يُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ', '5e8e548fccf4e4d813cc3ed488bb0dce5fc5a2533accccdb10b10581e101caa8', '5e8e548fccf4e4d813cc3ed488bb0dce5fc5a2533accccdb10b10581e101caa8', NULL, 'الذين لا يؤتون الزكوه وهم بالاخره هم كفرون', 24, 48, 190, 1, 6, 477, false, NULL),
    (4226, 'tanzil-uthmani-v1.1', 41, 8, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', '7e5a23614f8914d52bba4afd30a6359dedaa3f9c7bf398415fc8e679aa39161e', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', '7e5a23614f8914d52bba4afd30a6359dedaa3f9c7bf398415fc8e679aa39161e', '7e5a23614f8914d52bba4afd30a6359dedaa3f9c7bf398415fc8e679aa39161e', NULL, 'ان الذين ءامنوا وعملوا الصلحت لهم اجر غير ممنون', 24, 48, 190, 1, 6, 477, false, NULL),
    (4227, 'tanzil-uthmani-v1.1', 41, 9, 'قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِٱلَّذِى خَلَقَ ٱلْأَرْضَ فِى يَوْمَيْنِ وَتَجْعَلُونَ لَهُۥٓ أَندَادًا ذَٰلِكَ رَبُّ ٱلْعَٰلَمِينَ', '31d05ac3757c5d48e4b0ed3a3387e528035378f3e90a479b415ab847ab298761', 'قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِٱلَّذِى خَلَقَ ٱلْأَرْضَ فِى يَوْمَيْنِ وَتَجْعَلُونَ لَهُۥٓ أَندَادًا ذَٰلِكَ رَبُّ ٱلْعَٰلَمِينَ', '31d05ac3757c5d48e4b0ed3a3387e528035378f3e90a479b415ab847ab298761', '31d05ac3757c5d48e4b0ed3a3387e528035378f3e90a479b415ab847ab298761', NULL, 'قل ائنكم لتكفرون بالذي خلق الارض في يومين وتجعلون له اندادا ذلك رب العلمين', 24, 48, 191, 1, 6, 477, false, NULL),
    (4228, 'tanzil-uthmani-v1.1', 41, 10, 'وَجَعَلَ فِيهَا رَوَٰسِىَ مِن فَوْقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقْوَٰتَهَا فِىٓ أَرْبَعَةِ أَيَّامٍ سَوَآءً لِّلسَّآئِلِينَ', 'aebd5eb0e0b74193c3378fe07597f70eb7fc8062e9068ce6e02b091f4195b1b9', 'وَجَعَلَ فِيهَا رَوَٰسِىَ مِن فَوْقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقْوَٰتَهَا فِىٓ أَرْبَعَةِ أَيَّامٍ سَوَآءً لِّلسَّآئِلِينَ', 'aebd5eb0e0b74193c3378fe07597f70eb7fc8062e9068ce6e02b091f4195b1b9', 'aebd5eb0e0b74193c3378fe07597f70eb7fc8062e9068ce6e02b091f4195b1b9', NULL, 'وجعل فيها روسي من فوقها وبرك فيها وقدر فيها اقوتها في اربعه ايام سواء للسائلين', 24, 48, 191, 1, 6, 477, false, NULL),
    (4229, 'tanzil-uthmani-v1.1', 41, 11, 'ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِىَ دُخَانٌ فَقَالَ لَهَا وَلِلْأَرْضِ ٱئْتِيَا طَوْعًا أَوْ كَرْهًا قَالَتَآ أَتَيْنَا طَآئِعِينَ', '08b303cdc698573740515e01d49fd4591b429fe7ad5d3dc54735fe8592e0c9cc', 'ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِىَ دُخَانٌ فَقَالَ لَهَا وَلِلْأَرْضِ ٱئْتِيَا طَوْعًا أَوْ كَرْهًا قَالَتَآ أَتَيْنَا طَآئِعِينَ', '08b303cdc698573740515e01d49fd4591b429fe7ad5d3dc54735fe8592e0c9cc', '08b303cdc698573740515e01d49fd4591b429fe7ad5d3dc54735fe8592e0c9cc', NULL, 'ثم استوي الي السماء وهي دخان فقال لها وللارض ائتيا طوعا او كرها قالتا اتينا طائعين', 24, 48, 191, 1, 6, 477, false, NULL),
    (4230, 'tanzil-uthmani-v1.1', 41, 12, 'فَقَضَىٰهُنَّ سَبْعَ سَمَٰوَاتٍ فِى يَوْمَيْنِ وَأَوْحَىٰ فِى كُلِّ سَمَآءٍ أَمْرَهَا وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَحِفْظًا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'a27ae493e323e001226f1fb776bc4754691246e5a9ff6434e9d89eee81dc41df', 'فَقَضَىٰهُنَّ سَبْعَ سَمَٰوَاتٍ فِى يَوْمَيْنِ وَأَوْحَىٰ فِى كُلِّ سَمَآءٍ أَمْرَهَا وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَحِفْظًا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 'a27ae493e323e001226f1fb776bc4754691246e5a9ff6434e9d89eee81dc41df', 'a27ae493e323e001226f1fb776bc4754691246e5a9ff6434e9d89eee81dc41df', NULL, 'فقضيهن سبع سموات في يومين واوحي في كل سماء امرها وزينا السماء الدنيا بمصبيح وحفظا ذلك تقدير العزيز العليم', 24, 48, 191, 1, 6, 478, false, NULL),
    (4231, 'tanzil-uthmani-v1.1', 41, 13, 'فَإِنْ أَعْرَضُوا۟ فَقُلْ أَنذَرْتُكُمْ صَٰعِقَةً مِّثْلَ صَٰعِقَةِ عَادٍ وَثَمُودَ', '01d130f04794928890d11f4fe1962c1df0ecb08d8ffab281a01a340570056fc0', 'فَإِنْ أَعْرَضُوا۟ فَقُلْ أَنذَرْتُكُمْ صَٰعِقَةً مِّثْلَ صَٰعِقَةِ عَادٍ وَثَمُودَ', '01d130f04794928890d11f4fe1962c1df0ecb08d8ffab281a01a340570056fc0', '01d130f04794928890d11f4fe1962c1df0ecb08d8ffab281a01a340570056fc0', NULL, 'فان اعرضوا فقل انذرتكم صعقه مثل صعقه عاد وثمود', 24, 48, 191, 1, 6, 478, false, NULL),
    (4232, 'tanzil-uthmani-v1.1', 41, 14, 'إِذْ جَآءَتْهُمُ ٱلرُّسُلُ مِنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ قَالُوا۟ لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةً فَإِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'a81d32cf7802179eb9e6d5e624b74d08c94a64d0f7f389486c701bf6b96dd370', 'إِذْ جَآءَتْهُمُ ٱلرُّسُلُ مِنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ قَالُوا۟ لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةً فَإِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'a81d32cf7802179eb9e6d5e624b74d08c94a64d0f7f389486c701bf6b96dd370', 'a81d32cf7802179eb9e6d5e624b74d08c94a64d0f7f389486c701bf6b96dd370', NULL, 'اذ جاءتهم الرسل من بين ايديهم ومن خلفهم الا تعبدوا الا الله قالوا لو شاء ربنا لانزل ملئكه فانا بما ارسلتم به كفرون', 24, 48, 191, 1, 6, 478, false, NULL),
    (4233, 'tanzil-uthmani-v1.1', 41, 15, 'فَأَمَّا عَادٌ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَقَالُوا۟ مَنْ أَشَدُّ مِنَّا قُوَّةً أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً وَكَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'dac8e97944af5b3869a9ee22a77277f29039fbe447d8177c5dd6ecfc03e87c6e', 'فَأَمَّا عَادٌ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَقَالُوا۟ مَنْ أَشَدُّ مِنَّا قُوَّةً أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً وَكَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 'dac8e97944af5b3869a9ee22a77277f29039fbe447d8177c5dd6ecfc03e87c6e', 'dac8e97944af5b3869a9ee22a77277f29039fbe447d8177c5dd6ecfc03e87c6e', NULL, 'فاما عاد فاستكبروا في الارض بغير الحق وقالوا من اشد منا قوه اولم يروا ان الله الذي خلقهم هو اشد منهم قوه وكانوا بايتنا يجحدون', 24, 48, 191, 1, 6, 478, false, NULL),
    (4234, 'tanzil-uthmani-v1.1', 41, 16, 'فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِىٓ أَيَّامٍ نَّحِسَاتٍ لِّنُذِيقَهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَخْزَىٰ وَهُمْ لَا يُنصَرُونَ', '86efd0890c685ab5e2d545eb824e88da7580333ffe871012bdd02b4d8066d1e0', 'فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِىٓ أَيَّامٍ نَّحِسَاتٍ لِّنُذِيقَهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَخْزَىٰ وَهُمْ لَا يُنصَرُونَ', '86efd0890c685ab5e2d545eb824e88da7580333ffe871012bdd02b4d8066d1e0', '86efd0890c685ab5e2d545eb824e88da7580333ffe871012bdd02b4d8066d1e0', NULL, 'فارسلنا عليهم ريحا صرصرا في ايام نحسات لنذيقهم عذاب الخزي في الحيوه الدنيا ولعذاب الاخره اخزي وهم لا ينصرون', 24, 48, 191, 1, 6, 478, false, NULL),
    (4235, 'tanzil-uthmani-v1.1', 41, 17, 'وَأَمَّا ثَمُودُ فَهَدَيْنَٰهُمْ فَٱسْتَحَبُّوا۟ ٱلْعَمَىٰ عَلَى ٱلْهُدَىٰ فَأَخَذَتْهُمْ صَٰعِقَةُ ٱلْعَذَابِ ٱلْهُونِ بِمَا كَانُوا۟ يَكْسِبُونَ', '09d7212cc22cb1cbe7e5a550a185d3dde0e996dbdabefed49848f97e01ea25b4', 'وَأَمَّا ثَمُودُ فَهَدَيْنَٰهُمْ فَٱسْتَحَبُّوا۟ ٱلْعَمَىٰ عَلَى ٱلْهُدَىٰ فَأَخَذَتْهُمْ صَٰعِقَةُ ٱلْعَذَابِ ٱلْهُونِ بِمَا كَانُوا۟ يَكْسِبُونَ', '09d7212cc22cb1cbe7e5a550a185d3dde0e996dbdabefed49848f97e01ea25b4', '09d7212cc22cb1cbe7e5a550a185d3dde0e996dbdabefed49848f97e01ea25b4', NULL, 'واما ثمود فهدينهم فاستحبوا العمي علي الهدي فاخذتهم صعقه العذاب الهون بما كانوا يكسبون', 24, 48, 191, 1, 6, 478, false, NULL),
    (4236, 'tanzil-uthmani-v1.1', 41, 18, 'وَنَجَّيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '961d294933d4d1e446707604b1de61522140da149228464b303f779d0d27032a', 'وَنَجَّيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', '961d294933d4d1e446707604b1de61522140da149228464b303f779d0d27032a', '961d294933d4d1e446707604b1de61522140da149228464b303f779d0d27032a', NULL, 'ونجينا الذين ءامنوا وكانوا يتقون', 24, 48, 191, 1, 6, 478, false, NULL),
    (4237, 'tanzil-uthmani-v1.1', 41, 19, 'وَيَوْمَ يُحْشَرُ أَعْدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمْ يُوزَعُونَ', '8c7ad1aae798e13e0dbb3b1f9fd9ac15d7044c86f4b69b1d402e32365a2da98f', 'وَيَوْمَ يُحْشَرُ أَعْدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمْ يُوزَعُونَ', '8c7ad1aae798e13e0dbb3b1f9fd9ac15d7044c86f4b69b1d402e32365a2da98f', '8c7ad1aae798e13e0dbb3b1f9fd9ac15d7044c86f4b69b1d402e32365a2da98f', NULL, 'ويوم يحشر اعداء الله الي النار فهم يوزعون', 24, 48, 191, 1, 6, 478, false, NULL),
    (4238, 'tanzil-uthmani-v1.1', 41, 20, 'حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَٰرُهُمْ وَجُلُودُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'ba39fb3cfccadec67d271e8932ee2284bc8eb8ed66aa9ba42c7c4e7aa44b7ccb', 'حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَٰرُهُمْ وَجُلُودُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 'ba39fb3cfccadec67d271e8932ee2284bc8eb8ed66aa9ba42c7c4e7aa44b7ccb', 'ba39fb3cfccadec67d271e8932ee2284bc8eb8ed66aa9ba42c7c4e7aa44b7ccb', NULL, 'حتي اذا ما جاءوها شهد عليهم سمعهم وابصرهم وجلودهم بما كانوا يعملون', 24, 48, 191, 1, 6, 478, false, NULL),
    (4239, 'tanzil-uthmani-v1.1', 41, 21, 'وَقَالُوا۟ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا قَالُوٓا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِىٓ أَنطَقَ كُلَّ شَىْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ', '96a7bbe4fbffe99da678c6c4ceaf4afadc58cc7b37528b04a8e73d8b0b0202c7', 'وَقَالُوا۟ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا قَالُوٓا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِىٓ أَنطَقَ كُلَّ شَىْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ', '96a7bbe4fbffe99da678c6c4ceaf4afadc58cc7b37528b04a8e73d8b0b0202c7', '96a7bbe4fbffe99da678c6c4ceaf4afadc58cc7b37528b04a8e73d8b0b0202c7', NULL, 'وقالوا لجلودهم لم شهدتم علينا قالوا انطقنا الله الذي انطق كل شيء وهو خلقكم اول مره واليه ترجعون', 24, 48, 191, 1, 6, 479, false, NULL),
    (4240, 'tanzil-uthmani-v1.1', 41, 22, 'وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَآ أَبْصَٰرُكُمْ وَلَا جُلُودُكُمْ وَلَٰكِن ظَنَنتُمْ أَنَّ ٱللَّهَ لَا يَعْلَمُ كَثِيرًا مِّمَّا تَعْمَلُونَ', '20572cc8397630447b7fadefc91e46718fa4648d51a6386580b4b52c31a1a935', 'وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَآ أَبْصَٰرُكُمْ وَلَا جُلُودُكُمْ وَلَٰكِن ظَنَنتُمْ أَنَّ ٱللَّهَ لَا يَعْلَمُ كَثِيرًا مِّمَّا تَعْمَلُونَ', '20572cc8397630447b7fadefc91e46718fa4648d51a6386580b4b52c31a1a935', '20572cc8397630447b7fadefc91e46718fa4648d51a6386580b4b52c31a1a935', NULL, 'وما كنتم تستترون ان يشهد عليكم سمعكم ولا ابصركم ولا جلودكم ولكن ظننتم ان الله لا يعلم كثيرا مما تعملون', 24, 48, 191, 1, 6, 479, false, NULL),
    (4241, 'tanzil-uthmani-v1.1', 41, 23, 'وَذَٰلِكُمْ ظَنُّكُمُ ٱلَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَىٰكُمْ فَأَصْبَحْتُم مِّنَ ٱلْخَٰسِرِينَ', '435455bbc1be18c379a6477273bfcffca07062f502a0c40afbfef5924413553f', 'وَذَٰلِكُمْ ظَنُّكُمُ ٱلَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَىٰكُمْ فَأَصْبَحْتُم مِّنَ ٱلْخَٰسِرِينَ', '435455bbc1be18c379a6477273bfcffca07062f502a0c40afbfef5924413553f', '435455bbc1be18c379a6477273bfcffca07062f502a0c40afbfef5924413553f', NULL, 'وذلكم ظنكم الذي ظننتم بربكم ارديكم فاصبحتم من الخسرين', 24, 48, 191, 1, 6, 479, false, NULL),
    (4242, 'tanzil-uthmani-v1.1', 41, 24, 'فَإِن يَصْبِرُوا۟ فَٱلنَّارُ مَثْوًى لَّهُمْ وَإِن يَسْتَعْتِبُوا۟ فَمَا هُم مِّنَ ٱلْمُعْتَبِينَ', '63803b22439ebf9cd747f82efd5dfdb91cb4b9591d06d1412bb8d7025a1ea782', 'فَإِن يَصْبِرُوا۟ فَٱلنَّارُ مَثْوًى لَّهُمْ وَإِن يَسْتَعْتِبُوا۟ فَمَا هُم مِّنَ ٱلْمُعْتَبِينَ', '63803b22439ebf9cd747f82efd5dfdb91cb4b9591d06d1412bb8d7025a1ea782', '63803b22439ebf9cd747f82efd5dfdb91cb4b9591d06d1412bb8d7025a1ea782', NULL, 'فان يصبروا فالنار مثوي لهم وان يستعتبوا فما هم من المعتبين', 24, 48, 191, 1, 6, 479, false, NULL),
    (4243, 'tanzil-uthmani-v1.1', 41, 25, 'وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُوا۟ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', 'd267ef800df36a342715991628e5bdb94d2e56ccfd09d7ee515972ff0d28ca86', 'وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُوا۟ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', 'd267ef800df36a342715991628e5bdb94d2e56ccfd09d7ee515972ff0d28ca86', 'd267ef800df36a342715991628e5bdb94d2e56ccfd09d7ee515972ff0d28ca86', NULL, 'وقيضنا لهم قرناء فزينوا لهم ما بين ايديهم وما خلفهم وحق عليهم القول في امم قد خلت من قبلهم من الجن والانس انهم كانوا خسرين', 24, 48, 192, 1, 6, 479, false, NULL),
    (4244, 'tanzil-uthmani-v1.1', 41, 26, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَسْمَعُوا۟ لِهَٰذَا ٱلْقُرْءَانِ وَٱلْغَوْا۟ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ', '24013f821933c592bb7bf98d8a0e80003d1955e4c733114d70bc9a38f727c323', 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَسْمَعُوا۟ لِهَٰذَا ٱلْقُرْءَانِ وَٱلْغَوْا۟ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ', '24013f821933c592bb7bf98d8a0e80003d1955e4c733114d70bc9a38f727c323', '24013f821933c592bb7bf98d8a0e80003d1955e4c733114d70bc9a38f727c323', NULL, 'وقال الذين كفروا لا تسمعوا لهذا القرءان والغوا فيه لعلكم تغلبون', 24, 48, 192, 1, 6, 479, false, NULL),
    (4245, 'tanzil-uthmani-v1.1', 41, 27, 'فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُوا۟ عَذَابًا شَدِيدًا وَلَنَجْزِيَنَّهُمْ أَسْوَأَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', '024639e91dfde819d83e246cc03463b3a9d0284a64d74ae9da79129148f93abe', 'فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُوا۟ عَذَابًا شَدِيدًا وَلَنَجْزِيَنَّهُمْ أَسْوَأَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', '024639e91dfde819d83e246cc03463b3a9d0284a64d74ae9da79129148f93abe', '024639e91dfde819d83e246cc03463b3a9d0284a64d74ae9da79129148f93abe', NULL, 'فلنذيقن الذين كفروا عذابا شديدا ولنجزينهم اسوا الذي كانوا يعملون', 24, 48, 192, 1, 6, 479, false, NULL),
    (4246, 'tanzil-uthmani-v1.1', 41, 28, 'ذَٰلِكَ جَزَآءُ أَعْدَآءِ ٱللَّهِ ٱلنَّارُ لَهُمْ فِيهَا دَارُ ٱلْخُلْدِ جَزَآءًۢ بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', '25ec61a967ff6bd6e6aa7d1526f45e0c02376b61cb73cc11c310dd02cae376e3', 'ذَٰلِكَ جَزَآءُ أَعْدَآءِ ٱللَّهِ ٱلنَّارُ لَهُمْ فِيهَا دَارُ ٱلْخُلْدِ جَزَآءًۢ بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', '25ec61a967ff6bd6e6aa7d1526f45e0c02376b61cb73cc11c310dd02cae376e3', '25ec61a967ff6bd6e6aa7d1526f45e0c02376b61cb73cc11c310dd02cae376e3', NULL, 'ذلك جزاء اعداء الله النار لهم فيها دار الخلد جزاء بما كانوا بايتنا يجحدون', 24, 48, 192, 1, 6, 479, false, NULL),
    (4247, 'tanzil-uthmani-v1.1', 41, 29, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ رَبَّنَآ أَرِنَا ٱلَّذَيْنِ أَضَلَّانَا مِنَ ٱلْجِنِّ وَٱلْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ٱلْأَسْفَلِينَ', 'ca705f572a117f9c178d84bd270bbb95c483bd3d90b3c13d7384152194ff0afd', 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ رَبَّنَآ أَرِنَا ٱلَّذَيْنِ أَضَلَّانَا مِنَ ٱلْجِنِّ وَٱلْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ٱلْأَسْفَلِينَ', 'ca705f572a117f9c178d84bd270bbb95c483bd3d90b3c13d7384152194ff0afd', 'ca705f572a117f9c178d84bd270bbb95c483bd3d90b3c13d7384152194ff0afd', NULL, 'وقال الذين كفروا ربنا ارنا الذين اضلانا من الجن والانس نجعلهما تحت اقدامنا ليكونا من الاسفلين', 24, 48, 192, 1, 6, 479, false, NULL),
    (4248, 'tanzil-uthmani-v1.1', 41, 30, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ تَتَنَزَّلُ عَلَيْهِمُ ٱلْمَلَٰٓئِكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحْزَنُوا۟ وَأَبْشِرُوا۟ بِٱلْجَنَّةِ ٱلَّتِى كُنتُمْ تُوعَدُونَ', '7e6d4122a4d50e5a13e7286a7562a601f42cea18eba6b2654b9adab4bfd2afdb', 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ تَتَنَزَّلُ عَلَيْهِمُ ٱلْمَلَٰٓئِكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحْزَنُوا۟ وَأَبْشِرُوا۟ بِٱلْجَنَّةِ ٱلَّتِى كُنتُمْ تُوعَدُونَ', '7e6d4122a4d50e5a13e7286a7562a601f42cea18eba6b2654b9adab4bfd2afdb', '7e6d4122a4d50e5a13e7286a7562a601f42cea18eba6b2654b9adab4bfd2afdb', NULL, 'ان الذين قالوا ربنا الله ثم استقموا تتنزل عليهم الملئكه الا تخافوا ولا تحزنوا وابشروا بالجنه التي كنتم توعدون', 24, 48, 192, 1, 6, 480, false, NULL),
    (4249, 'tanzil-uthmani-v1.1', 41, 31, 'نَحْنُ أَوْلِيَآؤُكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِىٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ', 'e543ca1dd5aa22b13dd8e79686941438dbcb669d3d27cad72de0881ba855b18b', 'نَحْنُ أَوْلِيَآؤُكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِىٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ', 'e543ca1dd5aa22b13dd8e79686941438dbcb669d3d27cad72de0881ba855b18b', 'e543ca1dd5aa22b13dd8e79686941438dbcb669d3d27cad72de0881ba855b18b', NULL, 'نحن اولياؤكم في الحيوه الدنيا وفي الاخره ولكم فيها ما تشتهي انفسكم ولكم فيها ما تدعون', 24, 48, 192, 1, 6, 480, false, NULL),
    (4250, 'tanzil-uthmani-v1.1', 41, 32, 'نُزُلًا مِّنْ غَفُورٍ رَّحِيمٍ', '4ccdf060c4f9048b897ed95bc22e00746187b21a7d55eb9c3fd97b7a0a65d0c1', 'نُزُلًا مِّنْ غَفُورٍ رَّحِيمٍ', '4ccdf060c4f9048b897ed95bc22e00746187b21a7d55eb9c3fd97b7a0a65d0c1', '4ccdf060c4f9048b897ed95bc22e00746187b21a7d55eb9c3fd97b7a0a65d0c1', NULL, 'نزلا من غفور رحيم', 24, 48, 192, 1, 6, 480, false, NULL),
    (4251, 'tanzil-uthmani-v1.1', 41, 33, 'وَمَنْ أَحْسَنُ قَوْلًا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحًا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ', '9c9417d9439301cfec075ab848a7fd690840a84f3e15f923611d0dfbb8d41c0d', 'وَمَنْ أَحْسَنُ قَوْلًا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحًا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ', '9c9417d9439301cfec075ab848a7fd690840a84f3e15f923611d0dfbb8d41c0d', '9c9417d9439301cfec075ab848a7fd690840a84f3e15f923611d0dfbb8d41c0d', NULL, 'ومن احسن قولا ممن دعا الي الله وعمل صلحا وقال انني من المسلمين', 24, 48, 192, 1, 6, 480, false, NULL),
    (4252, 'tanzil-uthmani-v1.1', 41, 34, 'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌ', '707d05e5758d35da3fd4659e253f167c122672def8fb66d51f5f1c0b1e1969a0', 'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌ', '707d05e5758d35da3fd4659e253f167c122672def8fb66d51f5f1c0b1e1969a0', '707d05e5758d35da3fd4659e253f167c122672def8fb66d51f5f1c0b1e1969a0', NULL, 'ولا تستوي الحسنه ولا السيئه ادفع بالتي هي احسن فاذا الذي بينك وبينه عدوه كانه ولي حميم', 24, 48, 192, 1, 6, 480, false, NULL),
    (4253, 'tanzil-uthmani-v1.1', 41, 35, 'وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ', '28c6149c71d5489adf46f45c48b598359d5cfe77684f7f36952267f928c203d9', 'وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ', '28c6149c71d5489adf46f45c48b598359d5cfe77684f7f36952267f928c203d9', '28c6149c71d5489adf46f45c48b598359d5cfe77684f7f36952267f928c203d9', NULL, 'وما يلقيها الا الذين صبروا وما يلقيها الا ذو حظ عظيم', 24, 48, 192, 1, 6, 480, false, NULL),
    (4254, 'tanzil-uthmani-v1.1', 41, 36, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '99b6c9250b21143367106bdb76f6dc68b0ade72fc3ea224e83fbbf64e8627ec0', 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '99b6c9250b21143367106bdb76f6dc68b0ade72fc3ea224e83fbbf64e8627ec0', '99b6c9250b21143367106bdb76f6dc68b0ade72fc3ea224e83fbbf64e8627ec0', NULL, 'واما ينزغنك من الشيطن نزغ فاستعذ بالله انه هو السميع العليم', 24, 48, 192, 1, 6, 480, false, NULL),
    (4255, 'tanzil-uthmani-v1.1', 41, 37, 'وَمِنْ ءَايَٰتِهِ ٱلَّيْلُ وَٱلنَّهَارُ وَٱلشَّمْسُ وَٱلْقَمَرُ لَا تَسْجُدُوا۟ لِلشَّمْسِ وَلَا لِلْقَمَرِ وَٱسْجُدُوا۟ لِلَّهِ ٱلَّذِى خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'f27c274601c02e7144e1784b95ff2c82d4606e37e536120cee828eafd40df27a', 'وَمِنْ ءَايَٰتِهِ ٱلَّيْلُ وَٱلنَّهَارُ وَٱلشَّمْسُ وَٱلْقَمَرُ لَا تَسْجُدُوا۟ لِلشَّمْسِ وَلَا لِلْقَمَرِ وَٱسْجُدُوا۟ لِلَّهِ ٱلَّذِى خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 'f27c274601c02e7144e1784b95ff2c82d4606e37e536120cee828eafd40df27a', 'f27c274601c02e7144e1784b95ff2c82d4606e37e536120cee828eafd40df27a', NULL, 'ومن ءايته اليل والنهار والشمس والقمر لا تسجدوا للشمس ولا للقمر واسجدوا لله الذي خلقهن ان كنتم اياه تعبدون', 24, 48, 192, 1, 6, 480, false, NULL),
    (4256, 'tanzil-uthmani-v1.1', 41, 38, 'فَإِنِ ٱسْتَكْبَرُوا۟ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيْلِ وَٱلنَّهَارِ وَهُمْ لَا يَسْـَٔمُونَ', '43a6a13167457febf1934720f90653b691fc96bd063ff6ad7a470b079cb59df5', 'فَإِنِ ٱسْتَكْبَرُوا۟ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيْلِ وَٱلنَّهَارِ وَهُمْ لَا يَسْـَٔمُونَ', '43a6a13167457febf1934720f90653b691fc96bd063ff6ad7a470b079cb59df5', '43a6a13167457febf1934720f90653b691fc96bd063ff6ad7a470b079cb59df5', NULL, 'فان استكبروا فالذين عند ربك يسبحون له باليل والنهار وهم لا يسمون', 24, 48, 192, 1, 6, 480, true, 'obligatory'),
    (4257, 'tanzil-uthmani-v1.1', 41, 39, 'وَمِنْ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلْأَرْضَ خَٰشِعَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ إِنَّ ٱلَّذِىٓ أَحْيَاهَا لَمُحْىِ ٱلْمَوْتَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'c8121ef4b11a3ee01701c7e273803e246f2d22c8556e6ecd348233ec4cad09cd', 'وَمِنْ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلْأَرْضَ خَٰشِعَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ إِنَّ ٱلَّذِىٓ أَحْيَاهَا لَمُحْىِ ٱلْمَوْتَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'c8121ef4b11a3ee01701c7e273803e246f2d22c8556e6ecd348233ec4cad09cd', 'c8121ef4b11a3ee01701c7e273803e246f2d22c8556e6ecd348233ec4cad09cd', NULL, 'ومن ءايته انك تري الارض خشعه فاذا انزلنا عليها الماء اهتزت وربت ان الذي احياها لمحي الموتي انه علي كل شيء قدير', 24, 48, 192, 1, 6, 481, false, NULL),
    (4258, 'tanzil-uthmani-v1.1', 41, 40, 'إِنَّ ٱلَّذِينَ يُلْحِدُونَ فِىٓ ءَايَٰتِنَا لَا يَخْفَوْنَ عَلَيْنَآ أَفَمَن يُلْقَىٰ فِى ٱلنَّارِ خَيْرٌ أَم مَّن يَأْتِىٓ ءَامِنًا يَوْمَ ٱلْقِيَٰمَةِ ٱعْمَلُوا۟ مَا شِئْتُمْ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', '3fff69f2b2dcf7d1bea039ad0835f68acdf0357f962f122cacce5fa080b8a1e1', 'إِنَّ ٱلَّذِينَ يُلْحِدُونَ فِىٓ ءَايَٰتِنَا لَا يَخْفَوْنَ عَلَيْنَآ أَفَمَن يُلْقَىٰ فِى ٱلنَّارِ خَيْرٌ أَم مَّن يَأْتِىٓ ءَامِنًا يَوْمَ ٱلْقِيَٰمَةِ ٱعْمَلُوا۟ مَا شِئْتُمْ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', '3fff69f2b2dcf7d1bea039ad0835f68acdf0357f962f122cacce5fa080b8a1e1', '3fff69f2b2dcf7d1bea039ad0835f68acdf0357f962f122cacce5fa080b8a1e1', NULL, 'ان الذين يلحدون في ءايتنا لا يخفون علينا افمن يلقي في النار خير ام من ياتي ءامنا يوم القيمه اعملوا ما شئتم انه بما تعملون بصير', 24, 48, 192, 1, 6, 481, false, NULL),
    (4259, 'tanzil-uthmani-v1.1', 41, 41, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِٱلذِّكْرِ لَمَّا جَآءَهُمْ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٌ', 'e85b0d5f78ceec718065e2c1a8c6e574cdfa4dcbe82919ab820f4fc5422a8009', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِٱلذِّكْرِ لَمَّا جَآءَهُمْ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٌ', 'e85b0d5f78ceec718065e2c1a8c6e574cdfa4dcbe82919ab820f4fc5422a8009', 'e85b0d5f78ceec718065e2c1a8c6e574cdfa4dcbe82919ab820f4fc5422a8009', NULL, 'ان الذين كفروا بالذكر لما جاءهم وانه لكتب عزيز', 24, 48, 192, 1, 6, 481, false, NULL),
    (4260, 'tanzil-uthmani-v1.1', 41, 42, 'لَّا يَأْتِيهِ ٱلْبَٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ', '693bd1887222708bede2e2664e1b9f24f0dda476fe38d1fa7ebe792a0267bf82', 'لَّا يَأْتِيهِ ٱلْبَٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ', '693bd1887222708bede2e2664e1b9f24f0dda476fe38d1fa7ebe792a0267bf82', '693bd1887222708bede2e2664e1b9f24f0dda476fe38d1fa7ebe792a0267bf82', NULL, 'لا ياتيه البطل من بين يديه ولا من خلفه تنزيل من حكيم حميد', 24, 48, 192, 1, 6, 481, false, NULL),
    (4261, 'tanzil-uthmani-v1.1', 41, 43, 'مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ وَذُو عِقَابٍ أَلِيمٍ', '1ff3e4818662e4e816c449a269f1587887301434f0d9b1f957e2cccc4a381b4e', 'مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ وَذُو عِقَابٍ أَلِيمٍ', '1ff3e4818662e4e816c449a269f1587887301434f0d9b1f957e2cccc4a381b4e', '1ff3e4818662e4e816c449a269f1587887301434f0d9b1f957e2cccc4a381b4e', NULL, 'ما يقال لك الا ما قد قيل للرسل من قبلك ان ربك لذو مغفره وذو عقاب اليم', 24, 48, 192, 1, 6, 481, false, NULL),
    (4262, 'tanzil-uthmani-v1.1', 41, 44, 'وَلَوْ جَعَلْنَٰهُ قُرْءَانًا أَعْجَمِيًّا لَّقَالُوا۟ لَوْلَا فُصِّلَتْ ءَايَٰتُهُۥٓ ءَا۬عْجَمِىٌّ وَعَرَبِىٌّ قُلْ هُوَ لِلَّذِينَ ءَامَنُوا۟ هُدًى وَشِفَآءٌ وَٱلَّذِينَ لَا يُؤْمِنُونَ فِىٓ ءَاذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى أُو۟لَٰٓئِكَ يُنَادَوْنَ مِن مَّكَانٍۭ بَعِيدٍ', '130f1b6ec0e9b429491494bbeb7323ef810f72aa79d367af24e76e698975e0d8', 'وَلَوْ جَعَلْنَٰهُ قُرْءَانًا أَعْجَمِيًّا لَّقَالُوا۟ لَوْلَا فُصِّلَتْ ءَايَٰتُهُۥٓ ءَا۬عْجَمِىٌّ وَعَرَبِىٌّ قُلْ هُوَ لِلَّذِينَ ءَامَنُوا۟ هُدًى وَشِفَآءٌ وَٱلَّذِينَ لَا يُؤْمِنُونَ فِىٓ ءَاذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى أُو۟لَٰٓئِكَ يُنَادَوْنَ مِن مَّكَانٍۭ بَعِيدٍ', '130f1b6ec0e9b429491494bbeb7323ef810f72aa79d367af24e76e698975e0d8', '130f1b6ec0e9b429491494bbeb7323ef810f72aa79d367af24e76e698975e0d8', NULL, 'ولو جعلنه قرءانا اعجميا لقالوا لولا فصلت ءايته ءاعجمي وعربي قل هو للذين ءامنوا هدي وشفاء والذين لا يؤمنون في ءاذانهم وقر وهو عليهم عمي اولئك ينادون من مكان بعيد', 24, 48, 192, 1, 6, 481, false, NULL),
    (4263, 'tanzil-uthmani-v1.1', 41, 45, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', '7bbde63e13562f6e2da4b681375090bc9f2100f518f668cfc660a39b763b3372', 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', '7bbde63e13562f6e2da4b681375090bc9f2100f518f668cfc660a39b763b3372', '7bbde63e13562f6e2da4b681375090bc9f2100f518f668cfc660a39b763b3372', NULL, 'ولقد ءاتينا موسي الكتب فاختلف فيه ولولا كلمه سبقت من ربك لقضي بينهم وانهم لفي شك منه مريب', 24, 48, 192, 1, 6, 481, false, NULL),
    (4264, 'tanzil-uthmani-v1.1', 41, 46, 'مَّنْ عَمِلَ صَٰلِحًا فَلِنَفْسِهِۦ وَمَنْ أَسَآءَ فَعَلَيْهَا وَمَا رَبُّكَ بِظَلَّٰمٍ لِّلْعَبِيدِ', '598b316eafe0c32301335a22a0864b6bac465d8dcc3ddf7dc6896b40baa33b41', 'مَّنْ عَمِلَ صَٰلِحًا فَلِنَفْسِهِۦ وَمَنْ أَسَآءَ فَعَلَيْهَا وَمَا رَبُّكَ بِظَلَّٰمٍ لِّلْعَبِيدِ', '598b316eafe0c32301335a22a0864b6bac465d8dcc3ddf7dc6896b40baa33b41', '598b316eafe0c32301335a22a0864b6bac465d8dcc3ddf7dc6896b40baa33b41', NULL, 'من عمل صلحا فلنفسه ومن اساء فعليها وما ربك بظلم للعبيد', 24, 48, 192, 1, 6, 481, false, NULL),
    (4265, 'tanzil-uthmani-v1.1', 41, 47, 'إِلَيْهِ يُرَدُّ عِلْمُ ٱلسَّاعَةِ وَمَا تَخْرُجُ مِن ثَمَرَٰتٍ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَآءِى قَالُوٓا۟ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدٍ', 'be1423680aef0edd2368388586ba837bb5f31605a358a1162f390bb41db1f2cb', 'إِلَيْهِ يُرَدُّ عِلْمُ ٱلسَّاعَةِ وَمَا تَخْرُجُ مِن ثَمَرَٰتٍ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَآءِى قَالُوٓا۟ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدٍ', 'be1423680aef0edd2368388586ba837bb5f31605a358a1162f390bb41db1f2cb', 'be1423680aef0edd2368388586ba837bb5f31605a358a1162f390bb41db1f2cb', NULL, 'اليه يرد علم الساعه وما تخرج من ثمرت من اكمامها وما تحمل من انثي ولا تضع الا بعلمه ويوم يناديهم اين شركاءي قالوا ءاذنك ما منا من شهيد', 25, 49, 193, 1, 6, 482, false, NULL),
    (4266, 'tanzil-uthmani-v1.1', 41, 48, 'وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَدْعُونَ مِن قَبْلُ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِيصٍ', '6b5a63239ad7353d551a0aecf82c7d69c175241a51ff52c6e096ebced89e1d1b', 'وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَدْعُونَ مِن قَبْلُ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِيصٍ', '6b5a63239ad7353d551a0aecf82c7d69c175241a51ff52c6e096ebced89e1d1b', '6b5a63239ad7353d551a0aecf82c7d69c175241a51ff52c6e096ebced89e1d1b', NULL, 'وضل عنهم ما كانوا يدعون من قبل وظنوا ما لهم من محيص', 25, 49, 193, 1, 6, 482, false, NULL),
    (4267, 'tanzil-uthmani-v1.1', 41, 49, 'لَّا يَسْـَٔمُ ٱلْإِنسَٰنُ مِن دُعَآءِ ٱلْخَيْرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٌ قَنُوطٌ', '833a425c1ea4b9b0c98ed92faafabff87f285a321bad3659505d99c3e5fee350', 'لَّا يَسْـَٔمُ ٱلْإِنسَٰنُ مِن دُعَآءِ ٱلْخَيْرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٌ قَنُوطٌ', '833a425c1ea4b9b0c98ed92faafabff87f285a321bad3659505d99c3e5fee350', '833a425c1ea4b9b0c98ed92faafabff87f285a321bad3659505d99c3e5fee350', NULL, 'لا يسم الانسن من دعاء الخير وان مسه الشر فيوس قنوط', 25, 49, 193, 1, 6, 482, false, NULL),
    (4268, 'tanzil-uthmani-v1.1', 41, 50, 'وَلَئِنْ أَذَقْنَٰهُ رَحْمَةً مِّنَّا مِنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِى وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّىٓ إِنَّ لِى عِندَهُۥ لَلْحُسْنَىٰ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍ', 'bf23622af48da5781d0f6a53d167fe8269c98c9b11d4f85e26845012384635d5', 'وَلَئِنْ أَذَقْنَٰهُ رَحْمَةً مِّنَّا مِنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِى وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّىٓ إِنَّ لِى عِندَهُۥ لَلْحُسْنَىٰ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍ', 'bf23622af48da5781d0f6a53d167fe8269c98c9b11d4f85e26845012384635d5', 'bf23622af48da5781d0f6a53d167fe8269c98c9b11d4f85e26845012384635d5', NULL, 'ولئن اذقنه رحمه منا من بعد ضراء مسته ليقولن هذا لي وما اظن الساعه قائمه ولئن رجعت الي ربي ان لي عنده للحسني فلننبئن الذين كفروا بما عملوا ولنذيقنهم من عذاب غليظ', 25, 49, 193, 1, 6, 482, false, NULL),
    (4269, 'tanzil-uthmani-v1.1', 41, 51, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ', '78d9f23a32b15710962a971819a9ab3195118a1856c163446b21d4623c26c5fa', 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ', '78d9f23a32b15710962a971819a9ab3195118a1856c163446b21d4623c26c5fa', '78d9f23a32b15710962a971819a9ab3195118a1856c163446b21d4623c26c5fa', NULL, 'واذا انعمنا علي الانسن اعرض ونا بجانبه واذا مسه الشر فذو دعاء عريض', 25, 49, 193, 1, 6, 482, false, NULL),
    (4270, 'tanzil-uthmani-v1.1', 41, 52, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ ثُمَّ كَفَرْتُم بِهِۦ مَنْ أَضَلُّ مِمَّنْ هُوَ فِى شِقَاقٍۭ بَعِيدٍ', '5776fddf3ec3b68dad03301ab1b106645eb16662fa91bc612040735f709caf2d', 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ ثُمَّ كَفَرْتُم بِهِۦ مَنْ أَضَلُّ مِمَّنْ هُوَ فِى شِقَاقٍۭ بَعِيدٍ', '5776fddf3ec3b68dad03301ab1b106645eb16662fa91bc612040735f709caf2d', '5776fddf3ec3b68dad03301ab1b106645eb16662fa91bc612040735f709caf2d', NULL, 'قل ارءيتم ان كان من عند الله ثم كفرتم به من اضل ممن هو في شقاق بعيد', 25, 49, 193, 1, 6, 482, false, NULL),
    (4271, 'tanzil-uthmani-v1.1', 41, 53, 'سَنُرِيهِمْ ءَايَٰتِنَا فِى ٱلْـَٔافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '524dc37d4a5d6bc32bec44875ddf2033fbe46739687940d208899ff409a16f82', 'سَنُرِيهِمْ ءَايَٰتِنَا فِى ٱلْـَٔافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', '524dc37d4a5d6bc32bec44875ddf2033fbe46739687940d208899ff409a16f82', '524dc37d4a5d6bc32bec44875ddf2033fbe46739687940d208899ff409a16f82', NULL, 'سنريهم ءايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق اولم يكف بربك انه علي كل شيء شهيد', 25, 49, 193, 1, 6, 482, false, NULL),
    (4272, 'tanzil-uthmani-v1.1', 41, 54, 'أَلَآ إِنَّهُمْ فِى مِرْيَةٍ مِّن لِّقَآءِ رَبِّهِمْ أَلَآ إِنَّهُۥ بِكُلِّ شَىْءٍ مُّحِيطٌۢ', 'ba9ad9ca30d06044cd28f44d3085efd4f3eddcebea169e67ee5ab365ed33ff16', 'أَلَآ إِنَّهُمْ فِى مِرْيَةٍ مِّن لِّقَآءِ رَبِّهِمْ أَلَآ إِنَّهُۥ بِكُلِّ شَىْءٍ مُّحِيطٌۢ', 'ba9ad9ca30d06044cd28f44d3085efd4f3eddcebea169e67ee5ab365ed33ff16', 'ba9ad9ca30d06044cd28f44d3085efd4f3eddcebea169e67ee5ab365ed33ff16', NULL, 'الا انهم في مريه من لقاء ربهم الا انه بكل شيء محيط', 25, 49, 193, 1, 6, 482, false, NULL),
    (4273, 'tanzil-uthmani-v1.1', 42, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'b4f3f13e19bbe78e5f72edb60140cdae2eb77fceae263ed0d2b48f30c7cc67fd', 'حمٓ', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'حم', 25, 49, 193, 1, 6, 483, false, NULL),
    (4274, 'tanzil-uthmani-v1.1', 42, 2, 'عٓسٓقٓ', 'd80d6c3c7e2954717fe46d541d0a37a34fec17fed61d55b47a185a5988b0d035', 'عٓسٓقٓ', 'd80d6c3c7e2954717fe46d541d0a37a34fec17fed61d55b47a185a5988b0d035', 'd80d6c3c7e2954717fe46d541d0a37a34fec17fed61d55b47a185a5988b0d035', NULL, 'عسق', 25, 49, 193, 1, 6, 483, false, NULL),
    (4275, 'tanzil-uthmani-v1.1', 42, 3, 'كَذَٰلِكَ يُوحِىٓ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'fa663d45dc40d8627ac6e6392d7a39249bd2cdf9f4f0ffc7e0d8ceb09c7c7b1b', 'كَذَٰلِكَ يُوحِىٓ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'fa663d45dc40d8627ac6e6392d7a39249bd2cdf9f4f0ffc7e0d8ceb09c7c7b1b', 'fa663d45dc40d8627ac6e6392d7a39249bd2cdf9f4f0ffc7e0d8ceb09c7c7b1b', NULL, 'كذلك يوحي اليك والي الذين من قبلك الله العزيز الحكيم', 25, 49, 193, 1, 6, 483, false, NULL),
    (4276, 'tanzil-uthmani-v1.1', 42, 4, 'لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', '34f9c5c5bc8c9c28f46689e64d4da4c3ec5b0039776a7de0ae6b7f80c5eec4a3', 'لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', '34f9c5c5bc8c9c28f46689e64d4da4c3ec5b0039776a7de0ae6b7f80c5eec4a3', '34f9c5c5bc8c9c28f46689e64d4da4c3ec5b0039776a7de0ae6b7f80c5eec4a3', NULL, 'له ما في السموت وما في الارض وهو العلي العظيم', 25, 49, 193, 1, 6, 483, false, NULL),
    (4277, 'tanzil-uthmani-v1.1', 42, 5, 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ وَٱلْمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَن فِى ٱلْأَرْضِ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'cde1217280821ebe643953af74b0013de3e88547c6a0719945ecb49ee6a1fbc1', 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ وَٱلْمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَن فِى ٱلْأَرْضِ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'cde1217280821ebe643953af74b0013de3e88547c6a0719945ecb49ee6a1fbc1', 'cde1217280821ebe643953af74b0013de3e88547c6a0719945ecb49ee6a1fbc1', NULL, 'تكاد السموت يتفطرن من فوقهن والملئكه يسبحون بحمد ربهم ويستغفرون لمن في الارض الا ان الله هو الغفور الرحيم', 25, 49, 193, 1, 6, 483, false, NULL),
    (4278, 'tanzil-uthmani-v1.1', 42, 6, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', '1d31821198ed7fece2ca01e4413d995db52124c9de568bca5f36bfdbece39fa5', 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', '1d31821198ed7fece2ca01e4413d995db52124c9de568bca5f36bfdbece39fa5', '1d31821198ed7fece2ca01e4413d995db52124c9de568bca5f36bfdbece39fa5', NULL, 'والذين اتخذوا من دونه اولياء الله حفيظ عليهم وما انت عليهم بوكيل', 25, 49, 193, 1, 6, 483, false, NULL),
    (4279, 'tanzil-uthmani-v1.1', 42, 7, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ قُرْءَانًا عَرَبِيًّا لِّتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَتُنذِرَ يَوْمَ ٱلْجَمْعِ لَا رَيْبَ فِيهِ فَرِيقٌ فِى ٱلْجَنَّةِ وَفَرِيقٌ فِى ٱلسَّعِيرِ', 'd6114c48b5d3387edc6e962bba5d92460e4efeb208a3dc5153e83452c3cb5b2e', 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ قُرْءَانًا عَرَبِيًّا لِّتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَتُنذِرَ يَوْمَ ٱلْجَمْعِ لَا رَيْبَ فِيهِ فَرِيقٌ فِى ٱلْجَنَّةِ وَفَرِيقٌ فِى ٱلسَّعِيرِ', 'd6114c48b5d3387edc6e962bba5d92460e4efeb208a3dc5153e83452c3cb5b2e', 'd6114c48b5d3387edc6e962bba5d92460e4efeb208a3dc5153e83452c3cb5b2e', NULL, 'وكذلك اوحينا اليك قرءانا عربيا لتنذر ام القري ومن حولها وتنذر يوم الجمع لا ريب فيه فريق في الجنه وفريق في السعير', 25, 49, 193, 1, 6, 483, false, NULL),
    (4280, 'tanzil-uthmani-v1.1', 42, 8, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَهُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ وَٱلظَّٰلِمُونَ مَا لَهُم مِّن وَلِىٍّ وَلَا نَصِيرٍ', 'af44ad9e0d049b5b35a00c02722624e797cbea4a327ae92b3b884fb20ce03b4e', 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَهُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ وَٱلظَّٰلِمُونَ مَا لَهُم مِّن وَلِىٍّ وَلَا نَصِيرٍ', 'af44ad9e0d049b5b35a00c02722624e797cbea4a327ae92b3b884fb20ce03b4e', 'af44ad9e0d049b5b35a00c02722624e797cbea4a327ae92b3b884fb20ce03b4e', NULL, 'ولو شاء الله لجعلهم امه وحده ولكن يدخل من يشاء في رحمته والظلمون ما لهم من ولي ولا نصير', 25, 49, 193, 1, 6, 483, false, NULL),
    (4281, 'tanzil-uthmani-v1.1', 42, 9, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ فَٱللَّهُ هُوَ ٱلْوَلِىُّ وَهُوَ يُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '00b9c9ff6d3230cd0f028a0c287a956e6c4d482d1e6a7b51be8f2663a3f1c28d', 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ فَٱللَّهُ هُوَ ٱلْوَلِىُّ وَهُوَ يُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '00b9c9ff6d3230cd0f028a0c287a956e6c4d482d1e6a7b51be8f2663a3f1c28d', '00b9c9ff6d3230cd0f028a0c287a956e6c4d482d1e6a7b51be8f2663a3f1c28d', NULL, 'ام اتخذوا من دونه اولياء فالله هو الولي وهو يحي الموتي وهو علي كل شيء قدير', 25, 49, 193, 1, 6, 483, false, NULL),
    (4282, 'tanzil-uthmani-v1.1', 42, 10, 'وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ ذَٰلِكُمُ ٱللَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', '5eb32843085c3df56bfbdd706088b53a9bf5be682fd4478ea54ba6d419b4423c', 'وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ ذَٰلِكُمُ ٱللَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', '5eb32843085c3df56bfbdd706088b53a9bf5be682fd4478ea54ba6d419b4423c', '5eb32843085c3df56bfbdd706088b53a9bf5be682fd4478ea54ba6d419b4423c', NULL, 'وما اختلفتم فيه من شيء فحكمه الي الله ذلكم الله ربي عليه توكلت واليه انيب', 25, 49, 193, 1, 6, 483, false, NULL),
    (4283, 'tanzil-uthmani-v1.1', 42, 11, 'فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَمِنَ ٱلْأَنْعَٰمِ أَزْوَٰجًا يَذْرَؤُكُمْ فِيهِ لَيْسَ كَمِثْلِهِۦ شَىْءٌ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '1fa3b688b8809ef0160b4f6dad24a339484d3b7e62f7d7a1c514d0346804e889', 'فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَمِنَ ٱلْأَنْعَٰمِ أَزْوَٰجًا يَذْرَؤُكُمْ فِيهِ لَيْسَ كَمِثْلِهِۦ شَىْءٌ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', '1fa3b688b8809ef0160b4f6dad24a339484d3b7e62f7d7a1c514d0346804e889', '1fa3b688b8809ef0160b4f6dad24a339484d3b7e62f7d7a1c514d0346804e889', NULL, 'فاطر السموت والارض جعل لكم من انفسكم ازوجا ومن الانعم ازوجا يذرؤكم فيه ليس كمثله شيء وهو السميع البصير', 25, 49, 193, 1, 6, 484, false, NULL),
    (4284, 'tanzil-uthmani-v1.1', 42, 12, 'لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّهُۥ بِكُلِّ شَىْءٍ عَلِيمٌ', 'c460dead8c2282c0c8630284847ab029840fe56157d6fbd2cb4f060c8f712eb5', 'لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّهُۥ بِكُلِّ شَىْءٍ عَلِيمٌ', 'c460dead8c2282c0c8630284847ab029840fe56157d6fbd2cb4f060c8f712eb5', 'c460dead8c2282c0c8630284847ab029840fe56157d6fbd2cb4f060c8f712eb5', NULL, 'له مقاليد السموت والارض يبسط الرزق لمن يشاء ويقدر انه بكل شيء عليم', 25, 49, 193, 1, 6, 484, false, NULL),
    (4285, 'tanzil-uthmani-v1.1', 42, 13, 'شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ', '9e69b880e1b040de9fae70c562944d106102d423c11342ca6359ade0367fa194', 'شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ', '9e69b880e1b040de9fae70c562944d106102d423c11342ca6359ade0367fa194', '9e69b880e1b040de9fae70c562944d106102d423c11342ca6359ade0367fa194', NULL, 'شرع لكم من الدين ما وصي به نوحا والذي اوحينا اليك وما وصينا به ابرهيم وموسي وعيسي ان اقيموا الدين ولا تتفرقوا فيه كبر علي المشركين ما تدعوهم اليه الله يجتبي اليه من يشاء ويهدي اليه من ينيب', 25, 49, 194, 1, 6, 484, false, NULL),
    (4286, 'tanzil-uthmani-v1.1', 42, 14, 'وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلٍ مُّسَمًّى لَّقُضِىَ بَيْنَهُمْ وَإِنَّ ٱلَّذِينَ أُورِثُوا۟ ٱلْكِتَٰبَ مِنۢ بَعْدِهِمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', '8e8b32f03f610d42c5536f00dcc65d734491ca8bcc6e9b970b7c07dc922e7857', 'وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلٍ مُّسَمًّى لَّقُضِىَ بَيْنَهُمْ وَإِنَّ ٱلَّذِينَ أُورِثُوا۟ ٱلْكِتَٰبَ مِنۢ بَعْدِهِمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ', '8e8b32f03f610d42c5536f00dcc65d734491ca8bcc6e9b970b7c07dc922e7857', '8e8b32f03f610d42c5536f00dcc65d734491ca8bcc6e9b970b7c07dc922e7857', NULL, 'وما تفرقوا الا من بعد ما جاءهم العلم بغيا بينهم ولولا كلمه سبقت من ربك الي اجل مسمي لقضي بينهم وان الذين اورثوا الكتب من بعدهم لفي شك منه مريب', 25, 49, 194, 1, 6, 484, false, NULL),
    (4287, 'tanzil-uthmani-v1.1', 42, 15, 'فَلِذَٰلِكَ فَٱدْعُ وَٱسْتَقِمْ كَمَآ أُمِرْتَ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَقُلْ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٍ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ ٱللَّهُ رَبُّنَا وَرَبُّكُمْ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ ٱللَّهُ يَجْمَعُ بَيْنَنَا وَإِلَيْهِ ٱلْمَصِيرُ', '63dc1ea85f29ccbc52dbe3c5b2995af1361cfda995970429ddd0cc373d2120e0', 'فَلِذَٰلِكَ فَٱدْعُ وَٱسْتَقِمْ كَمَآ أُمِرْتَ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَقُلْ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٍ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ ٱللَّهُ رَبُّنَا وَرَبُّكُمْ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ ٱللَّهُ يَجْمَعُ بَيْنَنَا وَإِلَيْهِ ٱلْمَصِيرُ', '63dc1ea85f29ccbc52dbe3c5b2995af1361cfda995970429ddd0cc373d2120e0', '63dc1ea85f29ccbc52dbe3c5b2995af1361cfda995970429ddd0cc373d2120e0', NULL, 'فلذلك فادع واستقم كما امرت ولا تتبع اهواءهم وقل ءامنت بما انزل الله من كتب وامرت لاعدل بينكم الله ربنا وربكم لنا اعملنا ولكم اعملكم لا حجه بيننا وبينكم الله يجمع بيننا واليه المصير', 25, 49, 194, 1, 6, 484, false, NULL),
    (4288, 'tanzil-uthmani-v1.1', 42, 16, 'وَٱلَّذِينَ يُحَآجُّونَ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ٱسْتُجِيبَ لَهُۥ حُجَّتُهُمْ دَاحِضَةٌ عِندَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذَابٌ شَدِيدٌ', 'fc4e0e5802810c7d5b6236d9eb51bd28f5ec97099595e43a3ab8369d76a98476', 'وَٱلَّذِينَ يُحَآجُّونَ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ٱسْتُجِيبَ لَهُۥ حُجَّتُهُمْ دَاحِضَةٌ عِندَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذَابٌ شَدِيدٌ', 'fc4e0e5802810c7d5b6236d9eb51bd28f5ec97099595e43a3ab8369d76a98476', 'fc4e0e5802810c7d5b6236d9eb51bd28f5ec97099595e43a3ab8369d76a98476', NULL, 'والذين يحاجون في الله من بعد ما استجيب له حجتهم داحضه عند ربهم وعليهم غضب ولهم عذاب شديد', 25, 49, 194, 1, 6, 485, false, NULL),
    (4289, 'tanzil-uthmani-v1.1', 42, 17, 'ٱللَّهُ ٱلَّذِىٓ أَنزَلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَٱلْمِيزَانَ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٌ', '793d538424e058f74b4debec7c7bb80ca3993dfa90adac7b103067a11c3e07a0', 'ٱللَّهُ ٱلَّذِىٓ أَنزَلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَٱلْمِيزَانَ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٌ', '793d538424e058f74b4debec7c7bb80ca3993dfa90adac7b103067a11c3e07a0', '793d538424e058f74b4debec7c7bb80ca3993dfa90adac7b103067a11c3e07a0', NULL, 'الله الذي انزل الكتب بالحق والميزان وما يدريك لعل الساعه قريب', 25, 49, 194, 1, 6, 485, false, NULL),
    (4290, 'tanzil-uthmani-v1.1', 42, 18, 'يَسْتَعْجِلُ بِهَا ٱلَّذِينَ لَا يُؤْمِنُونَ بِهَا وَٱلَّذِينَ ءَامَنُوا۟ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا ٱلْحَقُّ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِى ٱلسَّاعَةِ لَفِى ضَلَٰلٍۭ بَعِيدٍ', 'e54731030d5f19b9b232dd8c7d56645d51cf0a1b61f7627b7a78bd6bfee582e4', 'يَسْتَعْجِلُ بِهَا ٱلَّذِينَ لَا يُؤْمِنُونَ بِهَا وَٱلَّذِينَ ءَامَنُوا۟ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا ٱلْحَقُّ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِى ٱلسَّاعَةِ لَفِى ضَلَٰلٍۭ بَعِيدٍ', 'e54731030d5f19b9b232dd8c7d56645d51cf0a1b61f7627b7a78bd6bfee582e4', 'e54731030d5f19b9b232dd8c7d56645d51cf0a1b61f7627b7a78bd6bfee582e4', NULL, 'يستعجل بها الذين لا يؤمنون بها والذين ءامنوا مشفقون منها ويعلمون انها الحق الا ان الذين يمارون في الساعه لفي ضلل بعيد', 25, 49, 194, 1, 6, 485, false, NULL),
    (4291, 'tanzil-uthmani-v1.1', 42, 19, 'ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 'ddb8af9b8c741a33ebf80e5a6ad4a7c546b841b5f4f8f7c972ca2e237b9c9a86', 'ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 'ddb8af9b8c741a33ebf80e5a6ad4a7c546b841b5f4f8f7c972ca2e237b9c9a86', 'ddb8af9b8c741a33ebf80e5a6ad4a7c546b841b5f4f8f7c972ca2e237b9c9a86', NULL, 'الله لطيف بعباده يرزق من يشاء وهو القوي العزيز', 25, 49, 194, 1, 6, 485, false, NULL),
    (4292, 'tanzil-uthmani-v1.1', 42, 20, 'مَن كَانَ يُرِيدُ حَرْثَ ٱلْـَٔاخِرَةِ نَزِدْ لَهُۥ فِى حَرْثِهِۦ وَمَن كَانَ يُرِيدُ حَرْثَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِن نَّصِيبٍ', '972d9561ee56ac008b49a8cefcb447f3b38fe35fce30937adc90cda0e5e62e74', 'مَن كَانَ يُرِيدُ حَرْثَ ٱلْـَٔاخِرَةِ نَزِدْ لَهُۥ فِى حَرْثِهِۦ وَمَن كَانَ يُرِيدُ حَرْثَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِن نَّصِيبٍ', '972d9561ee56ac008b49a8cefcb447f3b38fe35fce30937adc90cda0e5e62e74', '972d9561ee56ac008b49a8cefcb447f3b38fe35fce30937adc90cda0e5e62e74', NULL, 'من كان يريد حرث الاخره نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الاخره من نصيب', 25, 49, 194, 1, 6, 485, false, NULL),
    (4293, 'tanzil-uthmani-v1.1', 42, 21, 'أَمْ لَهُمْ شُرَكَٰٓؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّينِ مَا لَمْ يَأْذَنۢ بِهِ ٱللَّهُ وَلَوْلَا كَلِمَةُ ٱلْفَصْلِ لَقُضِىَ بَيْنَهُمْ وَإِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', '02bf3a88c52e2393d5dfe23a34f1114e94e3be1756b422446a3edb093c38e7fe', 'أَمْ لَهُمْ شُرَكَٰٓؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّينِ مَا لَمْ يَأْذَنۢ بِهِ ٱللَّهُ وَلَوْلَا كَلِمَةُ ٱلْفَصْلِ لَقُضِىَ بَيْنَهُمْ وَإِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ', '02bf3a88c52e2393d5dfe23a34f1114e94e3be1756b422446a3edb093c38e7fe', '02bf3a88c52e2393d5dfe23a34f1114e94e3be1756b422446a3edb093c38e7fe', NULL, 'ام لهم شركؤا شرعوا لهم من الدين ما لم ياذن به الله ولولا كلمه الفصل لقضي بينهم وان الظلمين لهم عذاب اليم', 25, 49, 194, 1, 6, 485, false, NULL),
    (4294, 'tanzil-uthmani-v1.1', 42, 22, 'تَرَى ٱلظَّٰلِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعٌۢ بِهِمْ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى رَوْضَاتِ ٱلْجَنَّاتِ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', '130f69867dd79c87953a5dc67a7061b8ec253a156104664913cf7f049a168641', 'تَرَى ٱلظَّٰلِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعٌۢ بِهِمْ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى رَوْضَاتِ ٱلْجَنَّاتِ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', '130f69867dd79c87953a5dc67a7061b8ec253a156104664913cf7f049a168641', '130f69867dd79c87953a5dc67a7061b8ec253a156104664913cf7f049a168641', NULL, 'تري الظلمين مشفقين مما كسبوا وهو واقع بهم والذين ءامنوا وعملوا الصلحت في روضات الجنات لهم ما يشاءون عند ربهم ذلك هو الفضل الكبير', 25, 49, 194, 1, 6, 485, false, NULL),
    (4295, 'tanzil-uthmani-v1.1', 42, 23, 'ذَٰلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ وَمَن يَقْتَرِفْ حَسَنَةً نَّزِدْ لَهُۥ فِيهَا حُسْنًا إِنَّ ٱللَّهَ غَفُورٌ شَكُورٌ', '0123c6b634ff9042991c3043ee2a510df81dae474c7451af5b57d49f0a863353', 'ذَٰلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ وَمَن يَقْتَرِفْ حَسَنَةً نَّزِدْ لَهُۥ فِيهَا حُسْنًا إِنَّ ٱللَّهَ غَفُورٌ شَكُورٌ', '0123c6b634ff9042991c3043ee2a510df81dae474c7451af5b57d49f0a863353', '0123c6b634ff9042991c3043ee2a510df81dae474c7451af5b57d49f0a863353', NULL, 'ذلك الذي يبشر الله عباده الذين ءامنوا وعملوا الصلحت قل لا اسلكم عليه اجرا الا الموده في القربي ومن يقترف حسنه نزد له فيها حسنا ان الله غفور شكور', 25, 49, 194, 1, 6, 486, false, NULL),
    (4296, 'tanzil-uthmani-v1.1', 42, 24, 'أَمْ يَقُولُونَ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا فَإِن يَشَإِ ٱللَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ وَيَمْحُ ٱللَّهُ ٱلْبَٰطِلَ وَيُحِقُّ ٱلْحَقَّ بِكَلِمَٰتِهِۦٓ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '1ca39e9824599b2bcf0725afe2d0f44e8e2eee0eba2e2dbd65c35ffb9d71db8a', 'أَمْ يَقُولُونَ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا فَإِن يَشَإِ ٱللَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ وَيَمْحُ ٱللَّهُ ٱلْبَٰطِلَ وَيُحِقُّ ٱلْحَقَّ بِكَلِمَٰتِهِۦٓ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '1ca39e9824599b2bcf0725afe2d0f44e8e2eee0eba2e2dbd65c35ffb9d71db8a', '1ca39e9824599b2bcf0725afe2d0f44e8e2eee0eba2e2dbd65c35ffb9d71db8a', NULL, 'ام يقولون افتري علي الله كذبا فان يشا الله يختم علي قلبك ويمح الله البطل ويحق الحق بكلمته انه عليم بذات الصدور', 25, 49, 194, 1, 6, 486, false, NULL),
    (4297, 'tanzil-uthmani-v1.1', 42, 25, 'وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ', '7ec4e2b9cf63ae551ace95b5002d9b9c9ae0cf91a10015cf95d09f4111ff8adf', 'وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ', '7ec4e2b9cf63ae551ace95b5002d9b9c9ae0cf91a10015cf95d09f4111ff8adf', '7ec4e2b9cf63ae551ace95b5002d9b9c9ae0cf91a10015cf95d09f4111ff8adf', NULL, 'وهو الذي يقبل التوبه عن عباده ويعفوا عن السيات ويعلم ما تفعلون', 25, 49, 194, 1, 6, 486, false, NULL),
    (4298, 'tanzil-uthmani-v1.1', 42, 26, 'وَيَسْتَجِيبُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ وَٱلْكَٰفِرُونَ لَهُمْ عَذَابٌ شَدِيدٌ', '5076d719ba019bc0d42f19418b17ae35396844014e2d2f76cee8b9f342e14614', 'وَيَسْتَجِيبُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ وَٱلْكَٰفِرُونَ لَهُمْ عَذَابٌ شَدِيدٌ', '5076d719ba019bc0d42f19418b17ae35396844014e2d2f76cee8b9f342e14614', '5076d719ba019bc0d42f19418b17ae35396844014e2d2f76cee8b9f342e14614', NULL, 'ويستجيب الذين ءامنوا وعملوا الصلحت ويزيدهم من فضله والكفرون لهم عذاب شديد', 25, 49, 194, 1, 6, 486, false, NULL),
    (4299, 'tanzil-uthmani-v1.1', 42, 27, 'وَلَوْ بَسَطَ ٱللَّهُ ٱلرِّزْقَ لِعِبَادِهِۦ لَبَغَوْا۟ فِى ٱلْأَرْضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٍ مَّا يَشَآءُ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرٌۢ بَصِيرٌ', 'ffa572875d4dcb6fcdc638289799c363b475c64d41af1c6f1afbbc452bf56c9e', 'وَلَوْ بَسَطَ ٱللَّهُ ٱلرِّزْقَ لِعِبَادِهِۦ لَبَغَوْا۟ فِى ٱلْأَرْضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٍ مَّا يَشَآءُ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرٌۢ بَصِيرٌ', 'ffa572875d4dcb6fcdc638289799c363b475c64d41af1c6f1afbbc452bf56c9e', 'ffa572875d4dcb6fcdc638289799c363b475c64d41af1c6f1afbbc452bf56c9e', NULL, 'ولو بسط الله الرزق لعباده لبغوا في الارض ولكن ينزل بقدر ما يشاء انه بعباده خبير بصير', 25, 49, 195, 1, 6, 486, false, NULL),
    (4300, 'tanzil-uthmani-v1.1', 42, 28, 'وَهُوَ ٱلَّذِى يُنَزِّلُ ٱلْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُوا۟ وَيَنشُرُ رَحْمَتَهُۥ وَهُوَ ٱلْوَلِىُّ ٱلْحَمِيدُ', 'f3a18e477ca43e364a97b91790d425badd995bca80d144e2c36a14668c1d4a37', 'وَهُوَ ٱلَّذِى يُنَزِّلُ ٱلْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُوا۟ وَيَنشُرُ رَحْمَتَهُۥ وَهُوَ ٱلْوَلِىُّ ٱلْحَمِيدُ', 'f3a18e477ca43e364a97b91790d425badd995bca80d144e2c36a14668c1d4a37', 'f3a18e477ca43e364a97b91790d425badd995bca80d144e2c36a14668c1d4a37', NULL, 'وهو الذي ينزل الغيث من بعد ما قنطوا وينشر رحمته وهو الولي الحميد', 25, 49, 195, 1, 6, 486, false, NULL),
    (4301, 'tanzil-uthmani-v1.1', 42, 29, 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٍ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَآءُ قَدِيرٌ', '16f40c2e6932993a25d676f141979c378df930f5b5f7b99e285d9ec642e71e5c', 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٍ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَآءُ قَدِيرٌ', '16f40c2e6932993a25d676f141979c378df930f5b5f7b99e285d9ec642e71e5c', '16f40c2e6932993a25d676f141979c378df930f5b5f7b99e285d9ec642e71e5c', NULL, 'ومن ءايته خلق السموت والارض وما بث فيهما من دابه وهو علي جمعهم اذا يشاء قدير', 25, 49, 195, 1, 6, 486, false, NULL),
    (4302, 'tanzil-uthmani-v1.1', 42, 30, 'وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍ', '5539467c8b07ad9f444cd2dc675a118b89a88ac9210b3ea6c47b218e77ec6e69', 'وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍ', '5539467c8b07ad9f444cd2dc675a118b89a88ac9210b3ea6c47b218e77ec6e69', '5539467c8b07ad9f444cd2dc675a118b89a88ac9210b3ea6c47b218e77ec6e69', NULL, 'وما اصبكم من مصيبه فبما كسبت ايديكم ويعفوا عن كثير', 25, 49, 195, 1, 6, 486, false, NULL),
    (4303, 'tanzil-uthmani-v1.1', 42, 31, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'f7fa4c09f3250aee2171b745a204b17048684cbee3873be9acd17596d723e462', 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ', 'f7fa4c09f3250aee2171b745a204b17048684cbee3873be9acd17596d723e462', 'f7fa4c09f3250aee2171b745a204b17048684cbee3873be9acd17596d723e462', NULL, 'وما انتم بمعجزين في الارض وما لكم من دون الله من ولي ولا نصير', 25, 49, 195, 1, 6, 486, false, NULL),
    (4304, 'tanzil-uthmani-v1.1', 42, 32, 'وَمِنْ ءَايَٰتِهِ ٱلْجَوَارِ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', '50a85441be55f9e4a555e50d55b93a01e451857ae50fcc0f8554a8301eddfcb0', 'وَمِنْ ءَايَٰتِهِ ٱلْجَوَارِ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', '50a85441be55f9e4a555e50d55b93a01e451857ae50fcc0f8554a8301eddfcb0', '50a85441be55f9e4a555e50d55b93a01e451857ae50fcc0f8554a8301eddfcb0', NULL, 'ومن ءايته الجوار في البحر كالاعلم', 25, 49, 195, 1, 6, 487, false, NULL),
    (4305, 'tanzil-uthmani-v1.1', 42, 33, 'إِن يَشَأْ يُسْكِنِ ٱلرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', '8c6eba2026774cc291fe226eefe0820713c4880f0be79233694c648f0be55198', 'إِن يَشَأْ يُسْكِنِ ٱلرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ', '8c6eba2026774cc291fe226eefe0820713c4880f0be79233694c648f0be55198', '8c6eba2026774cc291fe226eefe0820713c4880f0be79233694c648f0be55198', NULL, 'ان يشا يسكن الريح فيظللن رواكد علي ظهره ان في ذلك لايت لكل صبار شكور', 25, 49, 195, 1, 6, 487, false, NULL),
    (4306, 'tanzil-uthmani-v1.1', 42, 34, 'أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا۟ وَيَعْفُ عَن كَثِيرٍ', 'e34db46c01381386b9494dab1efe38f25c64b1774702149e80748ccdbecf4044', 'أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا۟ وَيَعْفُ عَن كَثِيرٍ', 'e34db46c01381386b9494dab1efe38f25c64b1774702149e80748ccdbecf4044', 'e34db46c01381386b9494dab1efe38f25c64b1774702149e80748ccdbecf4044', NULL, 'او يوبقهن بما كسبوا ويعف عن كثير', 25, 49, 195, 1, 6, 487, false, NULL),
    (4307, 'tanzil-uthmani-v1.1', 42, 35, 'وَيَعْلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٍ', '597a5de4c5886121bac61fa4b4e6720b621bc916aeac3bc1a812a667f0be803e', 'وَيَعْلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٍ', '597a5de4c5886121bac61fa4b4e6720b621bc916aeac3bc1a812a667f0be803e', '597a5de4c5886121bac61fa4b4e6720b621bc916aeac3bc1a812a667f0be803e', NULL, 'ويعلم الذين يجدلون في ءايتنا ما لهم من محيص', 25, 49, 195, 1, 6, 487, false, NULL),
    (4308, 'tanzil-uthmani-v1.1', 42, 36, 'فَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰ لِلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', '7a450ded8f26846f3971132d0d4efffe6438ad4d3d92dfd22f43c77856ad277a', 'فَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰ لِلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', '7a450ded8f26846f3971132d0d4efffe6438ad4d3d92dfd22f43c77856ad277a', '7a450ded8f26846f3971132d0d4efffe6438ad4d3d92dfd22f43c77856ad277a', NULL, 'فما اوتيتم من شيء فمتع الحيوه الدنيا وما عند الله خير وابقي للذين ءامنوا وعلي ربهم يتوكلون', 25, 49, 195, 1, 6, 487, false, NULL),
    (4309, 'tanzil-uthmani-v1.1', 42, 37, 'وَٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمْ يَغْفِرُونَ', '17b52bc339efb7b346582f856ba4313769a08b403c2a11f18b89bf96e8ecfa2e', 'وَٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمْ يَغْفِرُونَ', '17b52bc339efb7b346582f856ba4313769a08b403c2a11f18b89bf96e8ecfa2e', '17b52bc339efb7b346582f856ba4313769a08b403c2a11f18b89bf96e8ecfa2e', NULL, 'والذين يجتنبون كبئر الاثم والفوحش واذا ما غضبوا هم يغفرون', 25, 49, 195, 1, 6, 487, false, NULL),
    (4310, 'tanzil-uthmani-v1.1', 42, 38, 'وَٱلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', '7c631c77b9c691ca4b91a572798221d88168744d96eaac954bcd5213d10ed470', 'وَٱلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', '7c631c77b9c691ca4b91a572798221d88168744d96eaac954bcd5213d10ed470', '7c631c77b9c691ca4b91a572798221d88168744d96eaac954bcd5213d10ed470', NULL, 'والذين استجابوا لربهم واقاموا الصلوه وامرهم شوري بينهم ومما رزقنهم ينفقون', 25, 49, 195, 1, 6, 487, false, NULL),
    (4311, 'tanzil-uthmani-v1.1', 42, 39, 'وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلْبَغْىُ هُمْ يَنتَصِرُونَ', 'fdfe79631fa19948dd36290898bf3359fbc2b212cf4e21fde512b6d32055d09d', 'وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلْبَغْىُ هُمْ يَنتَصِرُونَ', 'fdfe79631fa19948dd36290898bf3359fbc2b212cf4e21fde512b6d32055d09d', 'fdfe79631fa19948dd36290898bf3359fbc2b212cf4e21fde512b6d32055d09d', NULL, 'والذين اذا اصابهم البغي هم ينتصرون', 25, 49, 195, 1, 6, 487, false, NULL),
    (4312, 'tanzil-uthmani-v1.1', 42, 40, 'وَجَزَٰٓؤُا۟ سَيِّئَةٍ سَيِّئَةٌ مِّثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُۥ عَلَى ٱللَّهِ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ', '3f3593a6ecce849ccc8ce14fd3536caa07335a83f4b03c5544e7ef3dcdbd01d1', 'وَجَزَٰٓؤُا۟ سَيِّئَةٍ سَيِّئَةٌ مِّثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُۥ عَلَى ٱللَّهِ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ', '3f3593a6ecce849ccc8ce14fd3536caa07335a83f4b03c5544e7ef3dcdbd01d1', '3f3593a6ecce849ccc8ce14fd3536caa07335a83f4b03c5544e7ef3dcdbd01d1', NULL, 'وجزؤا سيئه سيئه مثلها فمن عفا واصلح فاجره علي الله انه لا يحب الظلمين', 25, 49, 195, 1, 6, 487, false, NULL),
    (4313, 'tanzil-uthmani-v1.1', 42, 41, 'وَلَمَنِ ٱنتَصَرَ بَعْدَ ظُلْمِهِۦ فَأُو۟لَٰٓئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ', 'bca5cb704f8cbbc873636be84f05ed0c1f389e0ceb0fecd664e73c801d8b71e9', 'وَلَمَنِ ٱنتَصَرَ بَعْدَ ظُلْمِهِۦ فَأُو۟لَٰٓئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ', 'bca5cb704f8cbbc873636be84f05ed0c1f389e0ceb0fecd664e73c801d8b71e9', 'bca5cb704f8cbbc873636be84f05ed0c1f389e0ceb0fecd664e73c801d8b71e9', NULL, 'ولمن انتصر بعد ظلمه فاولئك ما عليهم من سبيل', 25, 49, 195, 1, 6, 487, false, NULL),
    (4314, 'tanzil-uthmani-v1.1', 42, 42, 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظْلِمُونَ ٱلنَّاسَ وَيَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', 'fa020029d7fbdfbde977c752cfb7847c0a40b14136a50d006cc6b4bae3605700', 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظْلِمُونَ ٱلنَّاسَ وَيَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ', 'fa020029d7fbdfbde977c752cfb7847c0a40b14136a50d006cc6b4bae3605700', 'fa020029d7fbdfbde977c752cfb7847c0a40b14136a50d006cc6b4bae3605700', NULL, 'انما السبيل علي الذين يظلمون الناس ويبغون في الارض بغير الحق اولئك لهم عذاب اليم', 25, 49, 195, 1, 6, 487, false, NULL),
    (4315, 'tanzil-uthmani-v1.1', 42, 43, 'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ٱلْأُمُورِ', '341fd26468fbe04533df50bb14f887471d476f93a92794ef77784729171d1c67', 'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ٱلْأُمُورِ', '341fd26468fbe04533df50bb14f887471d476f93a92794ef77784729171d1c67', '341fd26468fbe04533df50bb14f887471d476f93a92794ef77784729171d1c67', NULL, 'ولمن صبر وغفر ان ذلك لمن عزم الامور', 25, 49, 195, 1, 6, 487, false, NULL),
    (4316, 'tanzil-uthmani-v1.1', 42, 44, 'وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِىٍّ مِّنۢ بَعْدِهِۦ وَتَرَى ٱلظَّٰلِمِينَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَدٍّ مِّن سَبِيلٍ', 'ebc011ac0cd666b5c7fabdcf220109474c8e6d31de062c0191c0df9532f29f17', 'وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِىٍّ مِّنۢ بَعْدِهِۦ وَتَرَى ٱلظَّٰلِمِينَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَدٍّ مِّن سَبِيلٍ', 'ebc011ac0cd666b5c7fabdcf220109474c8e6d31de062c0191c0df9532f29f17', 'ebc011ac0cd666b5c7fabdcf220109474c8e6d31de062c0191c0df9532f29f17', NULL, 'ومن يضلل الله فما له من ولي من بعده وتري الظلمين لما راوا العذاب يقولون هل الي مرد من سبيل', 25, 49, 195, 1, 6, 487, false, NULL),
    (4317, 'tanzil-uthmani-v1.1', 42, 45, 'وَتَرَىٰهُمْ يُعْرَضُونَ عَلَيْهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِىٍّ وَقَالَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِى عَذَابٍ مُّقِيمٍ', 'b29b6fd1465152d5193c9be778a98ae6137eb4bdb85223721e8415f1e5e4d721', 'وَتَرَىٰهُمْ يُعْرَضُونَ عَلَيْهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِىٍّ وَقَالَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِى عَذَابٍ مُّقِيمٍ', 'b29b6fd1465152d5193c9be778a98ae6137eb4bdb85223721e8415f1e5e4d721', 'b29b6fd1465152d5193c9be778a98ae6137eb4bdb85223721e8415f1e5e4d721', NULL, 'وتريهم يعرضون عليها خشعين من الذل ينظرون من طرف خفي وقال الذين ءامنوا ان الخسرين الذين خسروا انفسهم واهليهم يوم القيمه الا ان الظلمين في عذاب مقيم', 25, 49, 195, 1, 6, 488, false, NULL),
    (4318, 'tanzil-uthmani-v1.1', 42, 46, 'وَمَا كَانَ لَهُم مِّنْ أَوْلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ', 'f269b596f8ae89e3e33fe4ad94fb4402e7e1db774db45f068ed3650320bfa381', 'وَمَا كَانَ لَهُم مِّنْ أَوْلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ', 'f269b596f8ae89e3e33fe4ad94fb4402e7e1db774db45f068ed3650320bfa381', 'f269b596f8ae89e3e33fe4ad94fb4402e7e1db774db45f068ed3650320bfa381', NULL, 'وما كان لهم من اولياء ينصرونهم من دون الله ومن يضلل الله فما له من سبيل', 25, 49, 195, 1, 6, 488, false, NULL),
    (4319, 'tanzil-uthmani-v1.1', 42, 47, 'ٱسْتَجِيبُوا۟ لِرَبِّكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ مَا لَكُم مِّن مَّلْجَإٍ يَوْمَئِذٍ وَمَا لَكُم مِّن نَّكِيرٍ', '1ce4eb1faccd692a92901072d9c35890477df16c1a339e4fd2c227dd415aa451', 'ٱسْتَجِيبُوا۟ لِرَبِّكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ مَا لَكُم مِّن مَّلْجَإٍ يَوْمَئِذٍ وَمَا لَكُم مِّن نَّكِيرٍ', '1ce4eb1faccd692a92901072d9c35890477df16c1a339e4fd2c227dd415aa451', '1ce4eb1faccd692a92901072d9c35890477df16c1a339e4fd2c227dd415aa451', NULL, 'استجيبوا لربكم من قبل ان ياتي يوم لا مرد له من الله ما لكم من ملجا يومئذ وما لكم من نكير', 25, 49, 195, 1, 6, 488, false, NULL),
    (4320, 'tanzil-uthmani-v1.1', 42, 48, 'فَإِنْ أَعْرَضُوا۟ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا إِنْ عَلَيْكَ إِلَّا ٱلْبَلَٰغُ وَإِنَّآ إِذَآ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةً فَرِحَ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ ٱلْإِنسَٰنَ كَفُورٌ', '79a97366575acc11167f7eee000c3873ecba69ca8457d303d94200598cbea702', 'فَإِنْ أَعْرَضُوا۟ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا إِنْ عَلَيْكَ إِلَّا ٱلْبَلَٰغُ وَإِنَّآ إِذَآ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةً فَرِحَ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ ٱلْإِنسَٰنَ كَفُورٌ', '79a97366575acc11167f7eee000c3873ecba69ca8457d303d94200598cbea702', '79a97366575acc11167f7eee000c3873ecba69ca8457d303d94200598cbea702', NULL, 'فان اعرضوا فما ارسلنك عليهم حفيظا ان عليك الا البلغ وانا اذا اذقنا الانسن منا رحمه فرح بها وان تصبهم سيئه بما قدمت ايديهم فان الانسن كفور', 25, 49, 195, 1, 6, 488, false, NULL),
    (4321, 'tanzil-uthmani-v1.1', 42, 49, 'لِّلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَخْلُقُ مَا يَشَآءُ يَهَبُ لِمَن يَشَآءُ إِنَٰثًا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ', 'ecb2455bba386754910cf6a14d7030030f9a995c9ed7c1cefb4bd509aa4aaa37', 'لِّلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَخْلُقُ مَا يَشَآءُ يَهَبُ لِمَن يَشَآءُ إِنَٰثًا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ', 'ecb2455bba386754910cf6a14d7030030f9a995c9ed7c1cefb4bd509aa4aaa37', 'ecb2455bba386754910cf6a14d7030030f9a995c9ed7c1cefb4bd509aa4aaa37', NULL, 'لله ملك السموت والارض يخلق ما يشاء يهب لمن يشاء انثا ويهب لمن يشاء الذكور', 25, 49, 195, 1, 6, 488, false, NULL),
    (4322, 'tanzil-uthmani-v1.1', 42, 50, 'أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَٰثًا وَيَجْعَلُ مَن يَشَآءُ عَقِيمًا إِنَّهُۥ عَلِيمٌ قَدِيرٌ', 'ce90f466725c116c07f5b9b196c348d0be4e6d18854947b0af3fec16ee47f6e2', 'أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَٰثًا وَيَجْعَلُ مَن يَشَآءُ عَقِيمًا إِنَّهُۥ عَلِيمٌ قَدِيرٌ', 'ce90f466725c116c07f5b9b196c348d0be4e6d18854947b0af3fec16ee47f6e2', 'ce90f466725c116c07f5b9b196c348d0be4e6d18854947b0af3fec16ee47f6e2', NULL, 'او يزوجهم ذكرانا وانثا ويجعل من يشاء عقيما انه عليم قدير', 25, 49, 195, 1, 6, 488, false, NULL),
    (4323, 'tanzil-uthmani-v1.1', 42, 51, 'وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَآئِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِىَ بِإِذْنِهِۦ مَا يَشَآءُ إِنَّهُۥ عَلِىٌّ حَكِيمٌ', '8e2c4826ac4370c268e17caff31d565fefde8c76208f3196bbb25d9a85551157', 'وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَآئِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِىَ بِإِذْنِهِۦ مَا يَشَآءُ إِنَّهُۥ عَلِىٌّ حَكِيمٌ', '8e2c4826ac4370c268e17caff31d565fefde8c76208f3196bbb25d9a85551157', '8e2c4826ac4370c268e17caff31d565fefde8c76208f3196bbb25d9a85551157', NULL, 'وما كان لبشر ان يكلمه الله الا وحيا او من ورائ حجاب او يرسل رسولا فيوحي باذنه ما يشاء انه علي حكيم', 25, 49, 196, 1, 6, 488, false, NULL),
    (4324, 'tanzil-uthmani-v1.1', 42, 52, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحًا مِّنْ أَمْرِنَا مَا كُنتَ تَدْرِى مَا ٱلْكِتَٰبُ وَلَا ٱلْإِيمَٰنُ وَلَٰكِن جَعَلْنَٰهُ نُورًا نَّهْدِى بِهِۦ مَن نَّشَآءُ مِنْ عِبَادِنَا وَإِنَّكَ لَتَهْدِىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '1c4295247571750bfe657536c3c955cd99c1e5aea2194891a56647678204e4cb', 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحًا مِّنْ أَمْرِنَا مَا كُنتَ تَدْرِى مَا ٱلْكِتَٰبُ وَلَا ٱلْإِيمَٰنُ وَلَٰكِن جَعَلْنَٰهُ نُورًا نَّهْدِى بِهِۦ مَن نَّشَآءُ مِنْ عِبَادِنَا وَإِنَّكَ لَتَهْدِىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '1c4295247571750bfe657536c3c955cd99c1e5aea2194891a56647678204e4cb', '1c4295247571750bfe657536c3c955cd99c1e5aea2194891a56647678204e4cb', NULL, 'وكذلك اوحينا اليك روحا من امرنا ما كنت تدري ما الكتب ولا الايمن ولكن جعلنه نورا نهدي به من نشاء من عبادنا وانك لتهدي الي صرط مستقيم', 25, 49, 196, 1, 6, 489, false, NULL),
    (4325, 'tanzil-uthmani-v1.1', 42, 53, 'صِرَٰطِ ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلْأُمُورُ', 'c1f270c6bb231016f2555a1a9f75ae40e4d0cdbf995139c4ee69fec7de0b8297', 'صِرَٰطِ ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلْأُمُورُ', 'c1f270c6bb231016f2555a1a9f75ae40e4d0cdbf995139c4ee69fec7de0b8297', 'c1f270c6bb231016f2555a1a9f75ae40e4d0cdbf995139c4ee69fec7de0b8297', NULL, 'صرط الله الذي له ما في السموت وما في الارض الا الي الله تصير الامور', 25, 49, 196, 1, 6, 489, false, NULL),
    (4326, 'tanzil-uthmani-v1.1', 43, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'b4f3f13e19bbe78e5f72edb60140cdae2eb77fceae263ed0d2b48f30c7cc67fd', 'حمٓ', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'حم', 25, 49, 196, 1, 6, 489, false, NULL),
    (4327, 'tanzil-uthmani-v1.1', 43, 2, 'وَٱلْكِتَٰبِ ٱلْمُبِينِ', '9d9b222146b320c4613c2c25b00dde0f48978fb09a52880e470661c641bef9ca', 'وَٱلْكِتَٰبِ ٱلْمُبِينِ', '9d9b222146b320c4613c2c25b00dde0f48978fb09a52880e470661c641bef9ca', '9d9b222146b320c4613c2c25b00dde0f48978fb09a52880e470661c641bef9ca', NULL, 'والكتب المبين', 25, 49, 196, 1, 6, 489, false, NULL),
    (4328, 'tanzil-uthmani-v1.1', 43, 3, 'إِنَّا جَعَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', '68fea25aee189f11c81a35fcee196408c5a28095253af7b3fbb8f46f61fa3bd3', 'إِنَّا جَعَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', '68fea25aee189f11c81a35fcee196408c5a28095253af7b3fbb8f46f61fa3bd3', '68fea25aee189f11c81a35fcee196408c5a28095253af7b3fbb8f46f61fa3bd3', NULL, 'انا جعلنه قرءنا عربيا لعلكم تعقلون', 25, 49, 196, 1, 6, 489, false, NULL),
    (4329, 'tanzil-uthmani-v1.1', 43, 4, 'وَإِنَّهُۥ فِىٓ أُمِّ ٱلْكِتَٰبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ', '070119a18816501293cc947e12731dfa632dd91c15cc1d3f7481440a5aa13ca3', 'وَإِنَّهُۥ فِىٓ أُمِّ ٱلْكِتَٰبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ', '070119a18816501293cc947e12731dfa632dd91c15cc1d3f7481440a5aa13ca3', '070119a18816501293cc947e12731dfa632dd91c15cc1d3f7481440a5aa13ca3', NULL, 'وانه في ام الكتب لدينا لعلي حكيم', 25, 49, 196, 1, 6, 489, false, NULL),
    (4330, 'tanzil-uthmani-v1.1', 43, 5, 'أَفَنَضْرِبُ عَنكُمُ ٱلذِّكْرَ صَفْحًا أَن كُنتُمْ قَوْمًا مُّسْرِفِينَ', '68dc10b0938136a40fe5db79c9ecbbf6868e6011fe21dc331b6cf5b46cf13faa', 'أَفَنَضْرِبُ عَنكُمُ ٱلذِّكْرَ صَفْحًا أَن كُنتُمْ قَوْمًا مُّسْرِفِينَ', '68dc10b0938136a40fe5db79c9ecbbf6868e6011fe21dc331b6cf5b46cf13faa', '68dc10b0938136a40fe5db79c9ecbbf6868e6011fe21dc331b6cf5b46cf13faa', NULL, 'افنضرب عنكم الذكر صفحا ان كنتم قوما مسرفين', 25, 49, 196, 1, 6, 489, false, NULL),
    (4331, 'tanzil-uthmani-v1.1', 43, 6, 'وَكَمْ أَرْسَلْنَا مِن نَّبِىٍّ فِى ٱلْأَوَّلِينَ', '3a4751c9633d6e799c9d7ed36ad066f86449574526ad88c351a9e15d7ec721af', 'وَكَمْ أَرْسَلْنَا مِن نَّبِىٍّ فِى ٱلْأَوَّلِينَ', '3a4751c9633d6e799c9d7ed36ad066f86449574526ad88c351a9e15d7ec721af', '3a4751c9633d6e799c9d7ed36ad066f86449574526ad88c351a9e15d7ec721af', NULL, 'وكم ارسلنا من نبي في الاولين', 25, 49, 196, 1, 6, 489, false, NULL),
    (4332, 'tanzil-uthmani-v1.1', 43, 7, 'وَمَا يَأْتِيهِم مِّن نَّبِىٍّ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '05f24944e519e42cd66c32fc0af9b0bcf416b8b6f58aabb23eb93d09190bdf2d', 'وَمَا يَأْتِيهِم مِّن نَّبِىٍّ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', '05f24944e519e42cd66c32fc0af9b0bcf416b8b6f58aabb23eb93d09190bdf2d', '05f24944e519e42cd66c32fc0af9b0bcf416b8b6f58aabb23eb93d09190bdf2d', NULL, 'وما ياتيهم من نبي الا كانوا به يستهزءون', 25, 49, 196, 1, 6, 489, false, NULL),
    (4333, 'tanzil-uthmani-v1.1', 43, 8, 'فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشًا وَمَضَىٰ مَثَلُ ٱلْأَوَّلِينَ', '5baf939b62487c8ce175198630d14a4524abe5e2ddadba9677558396e1a2a314', 'فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشًا وَمَضَىٰ مَثَلُ ٱلْأَوَّلِينَ', '5baf939b62487c8ce175198630d14a4524abe5e2ddadba9677558396e1a2a314', '5baf939b62487c8ce175198630d14a4524abe5e2ddadba9677558396e1a2a314', NULL, 'فاهلكنا اشد منهم بطشا ومضي مثل الاولين', 25, 49, 196, 1, 6, 489, false, NULL),
    (4334, 'tanzil-uthmani-v1.1', 43, 9, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلْعَزِيزُ ٱلْعَلِيمُ', '8a5346f743140cb693ff518bcde5e8c82cd5b666be2668f4d88ec4adbb1c995f', 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلْعَزِيزُ ٱلْعَلِيمُ', '8a5346f743140cb693ff518bcde5e8c82cd5b666be2668f4d88ec4adbb1c995f', '8a5346f743140cb693ff518bcde5e8c82cd5b666be2668f4d88ec4adbb1c995f', NULL, 'ولئن سالتهم من خلق السموت والارض ليقولن خلقهن العزيز العليم', 25, 49, 196, 1, 6, 489, false, NULL),
    (4335, 'tanzil-uthmani-v1.1', 43, 10, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَجَعَلَ لَكُمْ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', '1fdb924202e175feb1433059e616db0fd84f14309f6e23237f81a1846df03e30', 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَجَعَلَ لَكُمْ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ', '1fdb924202e175feb1433059e616db0fd84f14309f6e23237f81a1846df03e30', '1fdb924202e175feb1433059e616db0fd84f14309f6e23237f81a1846df03e30', NULL, 'الذي جعل لكم الارض مهدا وجعل لكم فيها سبلا لعلكم تهتدون', 25, 49, 196, 1, 6, 489, false, NULL),
    (4336, 'tanzil-uthmani-v1.1', 43, 11, 'وَٱلَّذِى نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَنشَرْنَا بِهِۦ بَلْدَةً مَّيْتًا كَذَٰلِكَ تُخْرَجُونَ', '6a0bd4e2751adf0c034f69d5ef2be7d031ee0bb0eee26d8a3677d8844e4a6935', 'وَٱلَّذِى نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَنشَرْنَا بِهِۦ بَلْدَةً مَّيْتًا كَذَٰلِكَ تُخْرَجُونَ', '6a0bd4e2751adf0c034f69d5ef2be7d031ee0bb0eee26d8a3677d8844e4a6935', '6a0bd4e2751adf0c034f69d5ef2be7d031ee0bb0eee26d8a3677d8844e4a6935', NULL, 'والذي نزل من السماء ماء بقدر فانشرنا به بلده ميتا كذلك تخرجون', 25, 49, 196, 1, 6, 490, false, NULL),
    (4337, 'tanzil-uthmani-v1.1', 43, 12, 'وَٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلْفُلْكِ وَٱلْأَنْعَٰمِ مَا تَرْكَبُونَ', '6b0b6a1b8db80f97dcec9bd69b87f316537985d73716da5d041b8f8eee468a4d', 'وَٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلْفُلْكِ وَٱلْأَنْعَٰمِ مَا تَرْكَبُونَ', '6b0b6a1b8db80f97dcec9bd69b87f316537985d73716da5d041b8f8eee468a4d', '6b0b6a1b8db80f97dcec9bd69b87f316537985d73716da5d041b8f8eee468a4d', NULL, 'والذي خلق الازوج كلها وجعل لكم من الفلك والانعم ما تركبون', 25, 49, 196, 1, 6, 490, false, NULL),
    (4338, 'tanzil-uthmani-v1.1', 43, 13, 'لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَٰنَ ٱلَّذِى سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ', '3c44d8382b963b391baf77e110040613bd41dec36cf7fcf065cd00cd37bbe571', 'لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَٰنَ ٱلَّذِى سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ', '3c44d8382b963b391baf77e110040613bd41dec36cf7fcf065cd00cd37bbe571', '3c44d8382b963b391baf77e110040613bd41dec36cf7fcf065cd00cd37bbe571', NULL, 'لتستوا علي ظهوره ثم تذكروا نعمه ربكم اذا استويتم عليه وتقولوا سبحن الذي سخر لنا هذا وما كنا له مقرنين', 25, 49, 196, 1, 6, 490, false, NULL),
    (4339, 'tanzil-uthmani-v1.1', 43, 14, 'وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ', '4edb69d75375f370b638076f857c792b2f7d29c50d084addfdc15d1b5631d13a', 'وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ', '4edb69d75375f370b638076f857c792b2f7d29c50d084addfdc15d1b5631d13a', '4edb69d75375f370b638076f857c792b2f7d29c50d084addfdc15d1b5631d13a', NULL, 'وانا الي ربنا لمنقلبون', 25, 49, 196, 1, 6, 490, false, NULL),
    (4340, 'tanzil-uthmani-v1.1', 43, 15, 'وَجَعَلُوا۟ لَهُۥ مِنْ عِبَادِهِۦ جُزْءًا إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌ مُّبِينٌ', '1aa2b0624ca7230fa4fad8dfe6fe46e6d81390990ff88113f68bbe1a1dbf5863', 'وَجَعَلُوا۟ لَهُۥ مِنْ عِبَادِهِۦ جُزْءًا إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌ مُّبِينٌ', '1aa2b0624ca7230fa4fad8dfe6fe46e6d81390990ff88113f68bbe1a1dbf5863', '1aa2b0624ca7230fa4fad8dfe6fe46e6d81390990ff88113f68bbe1a1dbf5863', NULL, 'وجعلوا له من عباده جزءا ان الانسن لكفور مبين', 25, 49, 196, 1, 6, 490, false, NULL),
    (4341, 'tanzil-uthmani-v1.1', 43, 16, 'أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍ وَأَصْفَىٰكُم بِٱلْبَنِينَ', '7df4057a459f8e76f633ff72037975a02b272f569e9b72b2ba242a302e9a9460', 'أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍ وَأَصْفَىٰكُم بِٱلْبَنِينَ', '7df4057a459f8e76f633ff72037975a02b272f569e9b72b2ba242a302e9a9460', '7df4057a459f8e76f633ff72037975a02b272f569e9b72b2ba242a302e9a9460', NULL, 'ام اتخذ مما يخلق بنات واصفيكم بالبنين', 25, 49, 196, 1, 6, 490, false, NULL),
    (4342, 'tanzil-uthmani-v1.1', 43, 17, 'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَٰنِ مَثَلًا ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', '7a513dcc4d5743e64110346e0576d8abc0b8b9ca078d0b07610c20f38da156a5', 'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَٰنِ مَثَلًا ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ', '7a513dcc4d5743e64110346e0576d8abc0b8b9ca078d0b07610c20f38da156a5', '7a513dcc4d5743e64110346e0576d8abc0b8b9ca078d0b07610c20f38da156a5', NULL, 'واذا بشر احدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم', 25, 49, 196, 1, 6, 490, false, NULL),
    (4343, 'tanzil-uthmani-v1.1', 43, 18, 'أَوَمَن يُنَشَّؤُا۟ فِى ٱلْحِلْيَةِ وَهُوَ فِى ٱلْخِصَامِ غَيْرُ مُبِينٍ', 'c8703ae2d525902b37e4e569299cdf6ca211bd1682c80265248ab6573907387a', 'أَوَمَن يُنَشَّؤُا۟ فِى ٱلْحِلْيَةِ وَهُوَ فِى ٱلْخِصَامِ غَيْرُ مُبِينٍ', 'c8703ae2d525902b37e4e569299cdf6ca211bd1682c80265248ab6573907387a', 'c8703ae2d525902b37e4e569299cdf6ca211bd1682c80265248ab6573907387a', NULL, 'اومن ينشؤا في الحليه وهو في الخصام غير مبين', 25, 49, 196, 1, 6, 490, false, NULL),
    (4344, 'tanzil-uthmani-v1.1', 43, 19, 'وَجَعَلُوا۟ ٱلْمَلَٰٓئِكَةَ ٱلَّذِينَ هُمْ عِبَٰدُ ٱلرَّحْمَٰنِ إِنَٰثًا أَشَهِدُوا۟ خَلْقَهُمْ سَتُكْتَبُ شَهَٰدَتُهُمْ وَيُسْـَٔلُونَ', 'd65faa107fc8a409409868c65ed1edb81269b8ac2c021ef8e9016c9296a47d71', 'وَجَعَلُوا۟ ٱلْمَلَٰٓئِكَةَ ٱلَّذِينَ هُمْ عِبَٰدُ ٱلرَّحْمَٰنِ إِنَٰثًا أَشَهِدُوا۟ خَلْقَهُمْ سَتُكْتَبُ شَهَٰدَتُهُمْ وَيُسْـَٔلُونَ', 'd65faa107fc8a409409868c65ed1edb81269b8ac2c021ef8e9016c9296a47d71', 'd65faa107fc8a409409868c65ed1edb81269b8ac2c021ef8e9016c9296a47d71', NULL, 'وجعلوا الملئكه الذين هم عبد الرحمن انثا اشهدوا خلقهم ستكتب شهدتهم ويسلون', 25, 49, 196, 1, 6, 490, false, NULL),
    (4345, 'tanzil-uthmani-v1.1', 43, 20, 'وَقَالُوا۟ لَوْ شَآءَ ٱلرَّحْمَٰنُ مَا عَبَدْنَٰهُم مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَخْرُصُونَ', 'f52885b00c31656383df1198afb32b5eff8e48033b5f482cecb6016470f2af42', 'وَقَالُوا۟ لَوْ شَآءَ ٱلرَّحْمَٰنُ مَا عَبَدْنَٰهُم مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَخْرُصُونَ', 'f52885b00c31656383df1198afb32b5eff8e48033b5f482cecb6016470f2af42', 'f52885b00c31656383df1198afb32b5eff8e48033b5f482cecb6016470f2af42', NULL, 'وقالوا لو شاء الرحمن ما عبدنهم ما لهم بذلك من علم ان هم الا يخرصون', 25, 49, 196, 1, 6, 490, false, NULL),
    (4346, 'tanzil-uthmani-v1.1', 43, 21, 'أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا مِّن قَبْلِهِۦ فَهُم بِهِۦ مُسْتَمْسِكُونَ', 'ebbc25fa5cc359fe9bd17c62d06c9ba20df91d5b1c609ebf4ad85a524a9f6ca6', 'أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا مِّن قَبْلِهِۦ فَهُم بِهِۦ مُسْتَمْسِكُونَ', 'ebbc25fa5cc359fe9bd17c62d06c9ba20df91d5b1c609ebf4ad85a524a9f6ca6', 'ebbc25fa5cc359fe9bd17c62d06c9ba20df91d5b1c609ebf4ad85a524a9f6ca6', NULL, 'ام ءاتينهم كتبا من قبله فهم به مستمسكون', 25, 49, 196, 1, 6, 490, false, NULL),
    (4347, 'tanzil-uthmani-v1.1', 43, 22, 'بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهْتَدُونَ', '76b35a153c70b975b60f22b91498c679533328c51475c5a930e8a75dde3b7486', 'بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهْتَدُونَ', '76b35a153c70b975b60f22b91498c679533328c51475c5a930e8a75dde3b7486', '76b35a153c70b975b60f22b91498c679533328c51475c5a930e8a75dde3b7486', NULL, 'بل قالوا انا وجدنا ءاباءنا علي امه وانا علي ءاثرهم مهتدون', 25, 49, 196, 1, 6, 490, false, NULL),
    (4348, 'tanzil-uthmani-v1.1', 43, 23, 'وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقْتَدُونَ', 'e70839728017bccf5827225fdc8d90b70db242186d07a831623cfa43a1314a83', 'وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقْتَدُونَ', 'e70839728017bccf5827225fdc8d90b70db242186d07a831623cfa43a1314a83', 'e70839728017bccf5827225fdc8d90b70db242186d07a831623cfa43a1314a83', NULL, 'وكذلك ما ارسلنا من قبلك في قريه من نذير الا قال مترفوها انا وجدنا ءاباءنا علي امه وانا علي ءاثرهم مقتدون', 25, 49, 196, 1, 6, 491, false, NULL),
    (4349, 'tanzil-uthmani-v1.1', 43, 24, 'قَٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'fe7eaf817a1e5c2e94b7dc917c72f29b72c421e74a6deb2d9824d471dd60d6a3', 'قَٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 'fe7eaf817a1e5c2e94b7dc917c72f29b72c421e74a6deb2d9824d471dd60d6a3', 'fe7eaf817a1e5c2e94b7dc917c72f29b72c421e74a6deb2d9824d471dd60d6a3', NULL, 'قل اولو جئتكم باهدي مما وجدتم عليه ءاباءكم قالوا انا بما ارسلتم به كفرون', 25, 50, 197, 1, 6, 491, false, NULL),
    (4350, 'tanzil-uthmani-v1.1', 43, 25, 'فَٱنتَقَمْنَا مِنْهُمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'de374911f518d61c748a71be3b48cdb7225cd4f56705e0343ca5c47ce1452ed1', 'فَٱنتَقَمْنَا مِنْهُمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 'de374911f518d61c748a71be3b48cdb7225cd4f56705e0343ca5c47ce1452ed1', 'de374911f518d61c748a71be3b48cdb7225cd4f56705e0343ca5c47ce1452ed1', NULL, 'فانتقمنا منهم فانظر كيف كان عقبه المكذبين', 25, 50, 197, 1, 6, 491, false, NULL),
    (4351, 'tanzil-uthmani-v1.1', 43, 26, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ', '5855eea76c5e80d2bf4c7e5621ddb59118d4ec1149139ab64aacfba9f87bd15a', 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ', '5855eea76c5e80d2bf4c7e5621ddb59118d4ec1149139ab64aacfba9f87bd15a', '5855eea76c5e80d2bf4c7e5621ddb59118d4ec1149139ab64aacfba9f87bd15a', NULL, 'واذ قال ابرهيم لابيه وقومه انني براء مما تعبدون', 25, 50, 197, 1, 6, 491, false, NULL),
    (4352, 'tanzil-uthmani-v1.1', 43, 27, 'إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ', '1e75824bcb2d67f14ca87da7319b4b84a413abdeeb8e0b9d389f1662b39389b7', 'إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ', '1e75824bcb2d67f14ca87da7319b4b84a413abdeeb8e0b9d389f1662b39389b7', '1e75824bcb2d67f14ca87da7319b4b84a413abdeeb8e0b9d389f1662b39389b7', NULL, 'الا الذي فطرني فانه سيهدين', 25, 50, 197, 1, 6, 491, false, NULL),
    (4353, 'tanzil-uthmani-v1.1', 43, 28, 'وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةً فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ', 'e36e1942864ec93a6f1a31547bc1a4ef20452735bf63b81d17f14254e0d1f848', 'وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةً فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ', 'e36e1942864ec93a6f1a31547bc1a4ef20452735bf63b81d17f14254e0d1f848', 'e36e1942864ec93a6f1a31547bc1a4ef20452735bf63b81d17f14254e0d1f848', NULL, 'وجعلها كلمه باقيه في عقبه لعلهم يرجعون', 25, 50, 197, 1, 6, 491, false, NULL),
    (4354, 'tanzil-uthmani-v1.1', 43, 29, 'بَلْ مَتَّعْتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ جَآءَهُمُ ٱلْحَقُّ وَرَسُولٌ مُّبِينٌ', '4af95893c18b97cf99f785acee9887021f307bd4f7f6d8257173d4b306781ee2', 'بَلْ مَتَّعْتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ جَآءَهُمُ ٱلْحَقُّ وَرَسُولٌ مُّبِينٌ', '4af95893c18b97cf99f785acee9887021f307bd4f7f6d8257173d4b306781ee2', '4af95893c18b97cf99f785acee9887021f307bd4f7f6d8257173d4b306781ee2', NULL, 'بل متعت هؤلاء وءاباءهم حتي جاءهم الحق ورسول مبين', 25, 50, 197, 1, 6, 491, false, NULL),
    (4355, 'tanzil-uthmani-v1.1', 43, 30, 'وَلَمَّا جَآءَهُمُ ٱلْحَقُّ قَالُوا۟ هَٰذَا سِحْرٌ وَإِنَّا بِهِۦ كَٰفِرُونَ', 'da8176914a7e21c622021397a24a76aa55a591740baa00e255371b7d2360ffc9', 'وَلَمَّا جَآءَهُمُ ٱلْحَقُّ قَالُوا۟ هَٰذَا سِحْرٌ وَإِنَّا بِهِۦ كَٰفِرُونَ', 'da8176914a7e21c622021397a24a76aa55a591740baa00e255371b7d2360ffc9', 'da8176914a7e21c622021397a24a76aa55a591740baa00e255371b7d2360ffc9', NULL, 'ولما جاءهم الحق قالوا هذا سحر وانا به كفرون', 25, 50, 197, 1, 6, 491, false, NULL),
    (4356, 'tanzil-uthmani-v1.1', 43, 31, 'وَقَالُوا۟ لَوْلَا نُزِّلَ هَٰذَا ٱلْقُرْءَانُ عَلَىٰ رَجُلٍ مِّنَ ٱلْقَرْيَتَيْنِ عَظِيمٍ', '8e497e5fb3c30da0927cc1165600deb204ff11ec80f92ac1faae79db7be39dc3', 'وَقَالُوا۟ لَوْلَا نُزِّلَ هَٰذَا ٱلْقُرْءَانُ عَلَىٰ رَجُلٍ مِّنَ ٱلْقَرْيَتَيْنِ عَظِيمٍ', '8e497e5fb3c30da0927cc1165600deb204ff11ec80f92ac1faae79db7be39dc3', '8e497e5fb3c30da0927cc1165600deb204ff11ec80f92ac1faae79db7be39dc3', NULL, 'وقالوا لولا نزل هذا القرءان علي رجل من القريتين عظيم', 25, 50, 197, 1, 6, 491, false, NULL),
    (4357, 'tanzil-uthmani-v1.1', 43, 32, 'أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَتَّخِذَ بَعْضُهُم بَعْضًا سُخْرِيًّا وَرَحْمَتُ رَبِّكَ خَيْرٌ مِّمَّا يَجْمَعُونَ', '7929f37e30a193e53cbe7184abf2aab10c877309d421ca6719363cb86efae469', 'أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَتَّخِذَ بَعْضُهُم بَعْضًا سُخْرِيًّا وَرَحْمَتُ رَبِّكَ خَيْرٌ مِّمَّا يَجْمَعُونَ', '7929f37e30a193e53cbe7184abf2aab10c877309d421ca6719363cb86efae469', '7929f37e30a193e53cbe7184abf2aab10c877309d421ca6719363cb86efae469', NULL, 'اهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحيوه الدنيا ورفعنا بعضهم فوق بعض درجت ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون', 25, 50, 197, 1, 6, 491, false, NULL),
    (4358, 'tanzil-uthmani-v1.1', 43, 33, 'وَلَوْلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً لَّجَعَلْنَا لِمَن يَكْفُرُ بِٱلرَّحْمَٰنِ لِبُيُوتِهِمْ سُقُفًا مِّن فِضَّةٍ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ', 'dbc67f5e73215820d8865359d276fec6f9404d8835b28dab60b6a6e81d8b6328', 'وَلَوْلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً لَّجَعَلْنَا لِمَن يَكْفُرُ بِٱلرَّحْمَٰنِ لِبُيُوتِهِمْ سُقُفًا مِّن فِضَّةٍ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ', 'dbc67f5e73215820d8865359d276fec6f9404d8835b28dab60b6a6e81d8b6328', 'dbc67f5e73215820d8865359d276fec6f9404d8835b28dab60b6a6e81d8b6328', NULL, 'ولولا ان يكون الناس امه وحده لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضه ومعارج عليها يظهرون', 25, 50, 197, 1, 6, 491, false, NULL),
    (4359, 'tanzil-uthmani-v1.1', 43, 34, 'وَلِبُيُوتِهِمْ أَبْوَٰبًا وَسُرُرًا عَلَيْهَا يَتَّكِـُٔونَ', '1d2acfa2bfc99f543f04491f6e7c79d0f87c06f59b427ce96eb1d6cb5f6bd733', 'وَلِبُيُوتِهِمْ أَبْوَٰبًا وَسُرُرًا عَلَيْهَا يَتَّكِـُٔونَ', '1d2acfa2bfc99f543f04491f6e7c79d0f87c06f59b427ce96eb1d6cb5f6bd733', '1d2acfa2bfc99f543f04491f6e7c79d0f87c06f59b427ce96eb1d6cb5f6bd733', NULL, 'ولبيوتهم ابوبا وسررا عليها يتكون', 25, 50, 197, 1, 6, 492, false, NULL),
    (4360, 'tanzil-uthmani-v1.1', 43, 35, 'وَزُخْرُفًا وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱلْـَٔاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ', '157be4b1508077aa8305fefbf5c2b57fa70983970e6e759716fa0641b300c199', 'وَزُخْرُفًا وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱلْـَٔاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ', '157be4b1508077aa8305fefbf5c2b57fa70983970e6e759716fa0641b300c199', '157be4b1508077aa8305fefbf5c2b57fa70983970e6e759716fa0641b300c199', NULL, 'وزخرفا وان كل ذلك لما متع الحيوه الدنيا والاخره عند ربك للمتقين', 25, 50, 197, 1, 6, 492, false, NULL),
    (4361, 'tanzil-uthmani-v1.1', 43, 36, 'وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَٰنِ نُقَيِّضْ لَهُۥ شَيْطَٰنًا فَهُوَ لَهُۥ قَرِينٌ', '27ca9ab876cb82cbb3ac10e791bea7505710a23fe398d66a7d75919ae4cb5320', 'وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَٰنِ نُقَيِّضْ لَهُۥ شَيْطَٰنًا فَهُوَ لَهُۥ قَرِينٌ', '27ca9ab876cb82cbb3ac10e791bea7505710a23fe398d66a7d75919ae4cb5320', '27ca9ab876cb82cbb3ac10e791bea7505710a23fe398d66a7d75919ae4cb5320', NULL, 'ومن يعش عن ذكر الرحمن نقيض له شيطنا فهو له قرين', 25, 50, 197, 1, 6, 492, false, NULL),
    (4362, 'tanzil-uthmani-v1.1', 43, 37, 'وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ ٱلسَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', '4008fd9b4085413d9eec27d8d7a7cf2a793fbe1506768c299c4ed878b57221d1', 'وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ ٱلسَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', '4008fd9b4085413d9eec27d8d7a7cf2a793fbe1506768c299c4ed878b57221d1', '4008fd9b4085413d9eec27d8d7a7cf2a793fbe1506768c299c4ed878b57221d1', NULL, 'وانهم ليصدونهم عن السبيل ويحسبون انهم مهتدون', 25, 50, 197, 1, 6, 492, false, NULL),
    (4363, 'tanzil-uthmani-v1.1', 43, 38, 'حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيْتَ بَيْنِى وَبَيْنَكَ بُعْدَ ٱلْمَشْرِقَيْنِ فَبِئْسَ ٱلْقَرِينُ', 'ebdfa3679b4dfacd9c20af909c735874b93d7c0cfb8c415372336fd25cf3085f', 'حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيْتَ بَيْنِى وَبَيْنَكَ بُعْدَ ٱلْمَشْرِقَيْنِ فَبِئْسَ ٱلْقَرِينُ', 'ebdfa3679b4dfacd9c20af909c735874b93d7c0cfb8c415372336fd25cf3085f', 'ebdfa3679b4dfacd9c20af909c735874b93d7c0cfb8c415372336fd25cf3085f', NULL, 'حتي اذا جاءنا قال يليت بيني وبينك بعد المشرقين فبئس القرين', 25, 50, 197, 1, 6, 492, false, NULL),
    (4364, 'tanzil-uthmani-v1.1', 43, 39, 'وَلَن يَنفَعَكُمُ ٱلْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', '40a749689de5f3cfa9e82f1d2836d5a554b71a0c9c6d91bdce2c63b03fc5fd1f', 'وَلَن يَنفَعَكُمُ ٱلْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', '40a749689de5f3cfa9e82f1d2836d5a554b71a0c9c6d91bdce2c63b03fc5fd1f', '40a749689de5f3cfa9e82f1d2836d5a554b71a0c9c6d91bdce2c63b03fc5fd1f', NULL, 'ولن ينفعكم اليوم اذ ظلمتم انكم في العذاب مشتركون', 25, 50, 197, 1, 6, 492, false, NULL),
    (4365, 'tanzil-uthmani-v1.1', 43, 40, 'أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ أَوْ تَهْدِى ٱلْعُمْىَ وَمَن كَانَ فِى ضَلَٰلٍ مُّبِينٍ', 'c4a777dfe51aa3bf1476b225511e2fe9b4e338db95d83fc46b67649f9a923110', 'أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ أَوْ تَهْدِى ٱلْعُمْىَ وَمَن كَانَ فِى ضَلَٰلٍ مُّبِينٍ', 'c4a777dfe51aa3bf1476b225511e2fe9b4e338db95d83fc46b67649f9a923110', 'c4a777dfe51aa3bf1476b225511e2fe9b4e338db95d83fc46b67649f9a923110', NULL, 'افانت تسمع الصم او تهدي العمي ومن كان في ضلل مبين', 25, 50, 197, 1, 6, 492, false, NULL),
    (4366, 'tanzil-uthmani-v1.1', 43, 41, 'فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ', '864e4910b95b54293e7ae1c976e8ac3840a6fe73eabc130e28dbcbcd4debc109', 'فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ', '864e4910b95b54293e7ae1c976e8ac3840a6fe73eabc130e28dbcbcd4debc109', '864e4910b95b54293e7ae1c976e8ac3840a6fe73eabc130e28dbcbcd4debc109', NULL, 'فاما نذهبن بك فانا منهم منتقمون', 25, 50, 197, 1, 6, 492, false, NULL),
    (4367, 'tanzil-uthmani-v1.1', 43, 42, 'أَوْ نُرِيَنَّكَ ٱلَّذِى وَعَدْنَٰهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ', '4a31e20f43a988942bdb68a8fcfac65289e6bfa066e542336daaa985208f8855', 'أَوْ نُرِيَنَّكَ ٱلَّذِى وَعَدْنَٰهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ', '4a31e20f43a988942bdb68a8fcfac65289e6bfa066e542336daaa985208f8855', '4a31e20f43a988942bdb68a8fcfac65289e6bfa066e542336daaa985208f8855', NULL, 'او نرينك الذي وعدنهم فانا عليهم مقتدرون', 25, 50, 197, 1, 6, 492, false, NULL),
    (4368, 'tanzil-uthmani-v1.1', 43, 43, 'فَٱسْتَمْسِكْ بِٱلَّذِىٓ أُوحِىَ إِلَيْكَ إِنَّكَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '42f667356ec7aece2e09add2942a0d0e2d21779d4451c44f4aa037fc61f10195', 'فَٱسْتَمْسِكْ بِٱلَّذِىٓ أُوحِىَ إِلَيْكَ إِنَّكَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '42f667356ec7aece2e09add2942a0d0e2d21779d4451c44f4aa037fc61f10195', '42f667356ec7aece2e09add2942a0d0e2d21779d4451c44f4aa037fc61f10195', NULL, 'فاستمسك بالذي اوحي اليك انك علي صرط مستقيم', 25, 50, 197, 1, 6, 492, false, NULL),
    (4369, 'tanzil-uthmani-v1.1', 43, 44, 'وَإِنَّهُۥ لَذِكْرٌ لَّكَ وَلِقَوْمِكَ وَسَوْفَ تُسْـَٔلُونَ', '499476a65f97a02edcbd2d17685c5da7a64b75d3745f7e1c8649ba6dc9edce65', 'وَإِنَّهُۥ لَذِكْرٌ لَّكَ وَلِقَوْمِكَ وَسَوْفَ تُسْـَٔلُونَ', '499476a65f97a02edcbd2d17685c5da7a64b75d3745f7e1c8649ba6dc9edce65', '499476a65f97a02edcbd2d17685c5da7a64b75d3745f7e1c8649ba6dc9edce65', NULL, 'وانه لذكر لك ولقومك وسوف تسلون', 25, 50, 197, 1, 6, 492, false, NULL),
    (4370, 'tanzil-uthmani-v1.1', 43, 45, 'وَسْـَٔلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ ٱلرَّحْمَٰنِ ءَالِهَةً يُعْبَدُونَ', 'e299e2740a5f409bfd11d0b20d68cbbe6a04dd75761e9a41f209b5ab5170e21c', 'وَسْـَٔلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ ٱلرَّحْمَٰنِ ءَالِهَةً يُعْبَدُونَ', 'e299e2740a5f409bfd11d0b20d68cbbe6a04dd75761e9a41f209b5ab5170e21c', 'e299e2740a5f409bfd11d0b20d68cbbe6a04dd75761e9a41f209b5ab5170e21c', NULL, 'وسل من ارسلنا من قبلك من رسلنا اجعلنا من دون الرحمن ءالهه يعبدون', 25, 50, 197, 1, 6, 492, false, NULL),
    (4371, 'tanzil-uthmani-v1.1', 43, 46, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَقَالَ إِنِّى رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', '6f5b44617d5d793370a574639d0e1d6a3279d0216e92814c9bc05ce69bbd0cec', 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَقَالَ إِنِّى رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', '6f5b44617d5d793370a574639d0e1d6a3279d0216e92814c9bc05ce69bbd0cec', '6f5b44617d5d793370a574639d0e1d6a3279d0216e92814c9bc05ce69bbd0cec', NULL, 'ولقد ارسلنا موسي بايتنا الي فرعون وملايه فقال اني رسول رب العلمين', 25, 50, 197, 1, 6, 492, false, NULL),
    (4372, 'tanzil-uthmani-v1.1', 43, 47, 'فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنْهَا يَضْحَكُونَ', 'c6187c8ef2c7f44d43033578fd6e78d21afa943b726a46d4ffdba79604f08713', 'فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنْهَا يَضْحَكُونَ', 'c6187c8ef2c7f44d43033578fd6e78d21afa943b726a46d4ffdba79604f08713', 'c6187c8ef2c7f44d43033578fd6e78d21afa943b726a46d4ffdba79604f08713', NULL, 'فلما جاءهم بايتنا اذا هم منها يضحكون', 25, 50, 197, 1, 6, 492, false, NULL),
    (4373, 'tanzil-uthmani-v1.1', 43, 48, 'وَمَا نُرِيهِم مِّنْ ءَايَةٍ إِلَّا هِىَ أَكْبَرُ مِنْ أُخْتِهَا وَأَخَذْنَٰهُم بِٱلْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ', '5664f6c97f78486bfeafe8ae95650a6b334caa8d7b1f8ffb036fc79d5843f820', 'وَمَا نُرِيهِم مِّنْ ءَايَةٍ إِلَّا هِىَ أَكْبَرُ مِنْ أُخْتِهَا وَأَخَذْنَٰهُم بِٱلْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ', '5664f6c97f78486bfeafe8ae95650a6b334caa8d7b1f8ffb036fc79d5843f820', '5664f6c97f78486bfeafe8ae95650a6b334caa8d7b1f8ffb036fc79d5843f820', NULL, 'وما نريهم من ءايه الا هي اكبر من اختها واخذنهم بالعذاب لعلهم يرجعون', 25, 50, 197, 1, 6, 493, false, NULL),
    (4374, 'tanzil-uthmani-v1.1', 43, 49, 'وَقَالُوا۟ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ', 'ce3ca70bcd218fcbda795c86aef195f514f7faa80f8ee204f0d9759cd426ca23', 'وَقَالُوا۟ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ', 'ce3ca70bcd218fcbda795c86aef195f514f7faa80f8ee204f0d9759cd426ca23', 'ce3ca70bcd218fcbda795c86aef195f514f7faa80f8ee204f0d9759cd426ca23', NULL, 'وقالوا يايه الساحر ادع لنا ربك بما عهد عندك اننا لمهتدون', 25, 50, 197, 1, 6, 493, false, NULL),
    (4375, 'tanzil-uthmani-v1.1', 43, 50, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلْعَذَابَ إِذَا هُمْ يَنكُثُونَ', '64599d9b5b48b3ac26cd8d75868235152cc62fa549f7fcc9c5d6ab76da3fa3b0', 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلْعَذَابَ إِذَا هُمْ يَنكُثُونَ', '64599d9b5b48b3ac26cd8d75868235152cc62fa549f7fcc9c5d6ab76da3fa3b0', '64599d9b5b48b3ac26cd8d75868235152cc62fa549f7fcc9c5d6ab76da3fa3b0', NULL, 'فلما كشفنا عنهم العذاب اذا هم ينكثون', 25, 50, 197, 1, 6, 493, false, NULL),
    (4376, 'tanzil-uthmani-v1.1', 43, 51, 'وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِهِۦ قَالَ يَٰقَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَٰذِهِ ٱلْأَنْهَٰرُ تَجْرِى مِن تَحْتِىٓ أَفَلَا تُبْصِرُونَ', '06775a8a44c2835fc01ff76e1be001ad22f6c00944eb75dad35686382a74e0f8', 'وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِهِۦ قَالَ يَٰقَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَٰذِهِ ٱلْأَنْهَٰرُ تَجْرِى مِن تَحْتِىٓ أَفَلَا تُبْصِرُونَ', '06775a8a44c2835fc01ff76e1be001ad22f6c00944eb75dad35686382a74e0f8', '06775a8a44c2835fc01ff76e1be001ad22f6c00944eb75dad35686382a74e0f8', NULL, 'ونادي فرعون في قومه قال يقوم اليس لي ملك مصر وهذه الانهر تجري من تحتي افلا تبصرون', 25, 50, 197, 1, 6, 493, false, NULL),
    (4377, 'tanzil-uthmani-v1.1', 43, 52, 'أَمْ أَنَا۠ خَيْرٌ مِّنْ هَٰذَا ٱلَّذِى هُوَ مَهِينٌ وَلَا يَكَادُ يُبِينُ', 'c84ec63b0f67bd2034f72fb9636eb5b3bc20b5bfc1e91c6e1b1868ed8a0b4e20', 'أَمْ أَنَا۠ خَيْرٌ مِّنْ هَٰذَا ٱلَّذِى هُوَ مَهِينٌ وَلَا يَكَادُ يُبِينُ', 'c84ec63b0f67bd2034f72fb9636eb5b3bc20b5bfc1e91c6e1b1868ed8a0b4e20', 'c84ec63b0f67bd2034f72fb9636eb5b3bc20b5bfc1e91c6e1b1868ed8a0b4e20', NULL, 'ام انا خير من هذا الذي هو مهين ولا يكاد يبين', 25, 50, 197, 1, 6, 493, false, NULL),
    (4378, 'tanzil-uthmani-v1.1', 43, 53, 'فَلَوْلَآ أُلْقِىَ عَلَيْهِ أَسْوِرَةٌ مِّن ذَهَبٍ أَوْ جَآءَ مَعَهُ ٱلْمَلَٰٓئِكَةُ مُقْتَرِنِينَ', '8f57118bf3c14fae8bc5df042ca7dab2323dbc552d0caaaa1e8c03f4357dbb59', 'فَلَوْلَآ أُلْقِىَ عَلَيْهِ أَسْوِرَةٌ مِّن ذَهَبٍ أَوْ جَآءَ مَعَهُ ٱلْمَلَٰٓئِكَةُ مُقْتَرِنِينَ', '8f57118bf3c14fae8bc5df042ca7dab2323dbc552d0caaaa1e8c03f4357dbb59', '8f57118bf3c14fae8bc5df042ca7dab2323dbc552d0caaaa1e8c03f4357dbb59', NULL, 'فلولا القي عليه اسوره من ذهب او جاء معه الملئكه مقترنين', 25, 50, 197, 1, 6, 493, false, NULL),
    (4379, 'tanzil-uthmani-v1.1', 43, 54, 'فَٱسْتَخَفَّ قَوْمَهُۥ فَأَطَاعُوهُ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', '7f3ead3bdd7d97b0164ddac28eb98b7b47af1a5a4b7366643af2d24bf59090d4', 'فَٱسْتَخَفَّ قَوْمَهُۥ فَأَطَاعُوهُ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ', '7f3ead3bdd7d97b0164ddac28eb98b7b47af1a5a4b7366643af2d24bf59090d4', '7f3ead3bdd7d97b0164ddac28eb98b7b47af1a5a4b7366643af2d24bf59090d4', NULL, 'فاستخف قومه فاطاعوه انهم كانوا قوما فسقين', 25, 50, 197, 1, 6, 493, false, NULL),
    (4380, 'tanzil-uthmani-v1.1', 43, 55, 'فَلَمَّآ ءَاسَفُونَا ٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', '01e463f8ccb690c9a6da4ec418e459bc03acd7c74bd4012cc5d90d69b4595a05', 'فَلَمَّآ ءَاسَفُونَا ٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', '01e463f8ccb690c9a6da4ec418e459bc03acd7c74bd4012cc5d90d69b4595a05', '01e463f8ccb690c9a6da4ec418e459bc03acd7c74bd4012cc5d90d69b4595a05', NULL, 'فلما ءاسفونا انتقمنا منهم فاغرقنهم اجمعين', 25, 50, 197, 1, 6, 493, false, NULL),
    (4381, 'tanzil-uthmani-v1.1', 43, 56, 'فَجَعَلْنَٰهُمْ سَلَفًا وَمَثَلًا لِّلْـَٔاخِرِينَ', 'dc5841c258a083cd58229d15bc94edd957795ca30ed6bb67d344ab9cf505e72b', 'فَجَعَلْنَٰهُمْ سَلَفًا وَمَثَلًا لِّلْـَٔاخِرِينَ', 'dc5841c258a083cd58229d15bc94edd957795ca30ed6bb67d344ab9cf505e72b', 'dc5841c258a083cd58229d15bc94edd957795ca30ed6bb67d344ab9cf505e72b', NULL, 'فجعلنهم سلفا ومثلا للاخرين', 25, 50, 197, 1, 6, 493, false, NULL),
    (4382, 'tanzil-uthmani-v1.1', 43, 57, 'وَلَمَّا ضُرِبَ ٱبْنُ مَرْيَمَ مَثَلًا إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ', '79723fd83c0fe4f85e40ccd66b9bdaf2b65c0fa4736582133f99e588cf2ceaf3', 'وَلَمَّا ضُرِبَ ٱبْنُ مَرْيَمَ مَثَلًا إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ', '79723fd83c0fe4f85e40ccd66b9bdaf2b65c0fa4736582133f99e588cf2ceaf3', '79723fd83c0fe4f85e40ccd66b9bdaf2b65c0fa4736582133f99e588cf2ceaf3', NULL, 'ولما ضرب ابن مريم مثلا اذا قومك منه يصدون', 25, 50, 198, 1, 6, 493, false, NULL),
    (4383, 'tanzil-uthmani-v1.1', 43, 58, 'وَقَالُوٓا۟ ءَأَٰلِهَتُنَا خَيْرٌ أَمْ هُوَ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًۢا بَلْ هُمْ قَوْمٌ خَصِمُونَ', 'cd8739fd86349f3054ad1f44e1bc4c582335a2b5cce74b9262633c3a5b00488a', 'وَقَالُوٓا۟ ءَأَٰلِهَتُنَا خَيْرٌ أَمْ هُوَ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًۢا بَلْ هُمْ قَوْمٌ خَصِمُونَ', 'cd8739fd86349f3054ad1f44e1bc4c582335a2b5cce74b9262633c3a5b00488a', 'cd8739fd86349f3054ad1f44e1bc4c582335a2b5cce74b9262633c3a5b00488a', NULL, 'وقالوا ءالهتنا خير ام هو ما ضربوه لك الا جدلا بل هم قوم خصمون', 25, 50, 198, 1, 6, 493, false, NULL),
    (4384, 'tanzil-uthmani-v1.1', 43, 59, 'إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَٰهُ مَثَلًا لِّبَنِىٓ إِسْرَٰٓءِيلَ', '30ff1c4c997c1d0c2b91943ec4a2bd4b76da6d51636b503cba7ed774a4e682ec', 'إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَٰهُ مَثَلًا لِّبَنِىٓ إِسْرَٰٓءِيلَ', '30ff1c4c997c1d0c2b91943ec4a2bd4b76da6d51636b503cba7ed774a4e682ec', '30ff1c4c997c1d0c2b91943ec4a2bd4b76da6d51636b503cba7ed774a4e682ec', NULL, 'ان هو الا عبد انعمنا عليه وجعلنه مثلا لبني اسرءيل', 25, 50, 198, 1, 6, 493, false, NULL),
    (4385, 'tanzil-uthmani-v1.1', 43, 60, 'وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُم مَّلَٰٓئِكَةً فِى ٱلْأَرْضِ يَخْلُفُونَ', '570161a6565ec038f1c147cab96cdf3b38cd6651a9ef5587f1216c1377af9910', 'وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُم مَّلَٰٓئِكَةً فِى ٱلْأَرْضِ يَخْلُفُونَ', '570161a6565ec038f1c147cab96cdf3b38cd6651a9ef5587f1216c1377af9910', '570161a6565ec038f1c147cab96cdf3b38cd6651a9ef5587f1216c1377af9910', NULL, 'ولو نشاء لجعلنا منكم ملئكه في الارض يخلفون', 25, 50, 198, 1, 6, 493, false, NULL),
    (4386, 'tanzil-uthmani-v1.1', 43, 61, 'وَإِنَّهُۥ لَعِلْمٌ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَٱتَّبِعُونِ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'bbfad59e45286bee7577d78361cdce8fa9627e9e20e0daea87b82b4d101f6f8f', 'وَإِنَّهُۥ لَعِلْمٌ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَٱتَّبِعُونِ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'bbfad59e45286bee7577d78361cdce8fa9627e9e20e0daea87b82b4d101f6f8f', 'bbfad59e45286bee7577d78361cdce8fa9627e9e20e0daea87b82b4d101f6f8f', NULL, 'وانه لعلم للساعه فلا تمترن بها واتبعون هذا صرط مستقيم', 25, 50, 198, 1, 6, 494, false, NULL),
    (4387, 'tanzil-uthmani-v1.1', 43, 62, 'وَلَا يَصُدَّنَّكُمُ ٱلشَّيْطَٰنُ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '46aa7911bddb82530898e6803a0e20c729d965a2107b561b402b5a107620312e', 'وَلَا يَصُدَّنَّكُمُ ٱلشَّيْطَٰنُ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ', '46aa7911bddb82530898e6803a0e20c729d965a2107b561b402b5a107620312e', '46aa7911bddb82530898e6803a0e20c729d965a2107b561b402b5a107620312e', NULL, 'ولا يصدنكم الشيطن انه لكم عدو مبين', 25, 50, 198, 1, 6, 494, false, NULL),
    (4388, 'tanzil-uthmani-v1.1', 43, 63, 'وَلَمَّا جَآءَ عِيسَىٰ بِٱلْبَيِّنَٰتِ قَالَ قَدْ جِئْتُكُم بِٱلْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ ٱلَّذِى تَخْتَلِفُونَ فِيهِ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'a5acd6de82bb1f5bec70c26f7feee3ef7e7324f34340b93bab37d5892669f7da', 'وَلَمَّا جَآءَ عِيسَىٰ بِٱلْبَيِّنَٰتِ قَالَ قَدْ جِئْتُكُم بِٱلْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ ٱلَّذِى تَخْتَلِفُونَ فِيهِ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 'a5acd6de82bb1f5bec70c26f7feee3ef7e7324f34340b93bab37d5892669f7da', 'a5acd6de82bb1f5bec70c26f7feee3ef7e7324f34340b93bab37d5892669f7da', NULL, 'ولما جاء عيسي بالبينت قال قد جئتكم بالحكمه ولابين لكم بعض الذي تختلفون فيه فاتقوا الله واطيعون', 25, 50, 198, 1, 6, 494, false, NULL),
    (4389, 'tanzil-uthmani-v1.1', 43, 64, 'إِنَّ ٱللَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'c3ca3ed90395fb1fdbbc8c3f684b6f1fa8b7182dd376b284243ac1e1c708edc1', 'إِنَّ ٱللَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ', 'c3ca3ed90395fb1fdbbc8c3f684b6f1fa8b7182dd376b284243ac1e1c708edc1', 'c3ca3ed90395fb1fdbbc8c3f684b6f1fa8b7182dd376b284243ac1e1c708edc1', NULL, 'ان الله هو ربي وربكم فاعبدوه هذا صرط مستقيم', 25, 50, 198, 1, 6, 494, false, NULL),
    (4390, 'tanzil-uthmani-v1.1', 43, 65, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ ظَلَمُوا۟ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ', '7cce7ca1d4861fd354fd426d2d70930e9860e141969824c3fb0b86315b400da7', 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ ظَلَمُوا۟ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ', '7cce7ca1d4861fd354fd426d2d70930e9860e141969824c3fb0b86315b400da7', '7cce7ca1d4861fd354fd426d2d70930e9860e141969824c3fb0b86315b400da7', NULL, 'فاختلف الاحزاب من بينهم فويل للذين ظلموا من عذاب يوم اليم', 25, 50, 198, 1, 6, 494, false, NULL),
    (4391, 'tanzil-uthmani-v1.1', 43, 66, 'هَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', '1a9cd5fbea85365d6ef6dc953704309f55dc1dda205be1e148f5859b35588832', 'هَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ', '1a9cd5fbea85365d6ef6dc953704309f55dc1dda205be1e148f5859b35588832', '1a9cd5fbea85365d6ef6dc953704309f55dc1dda205be1e148f5859b35588832', NULL, 'هل ينظرون الا الساعه ان تاتيهم بغته وهم لا يشعرون', 25, 50, 198, 1, 6, 494, false, NULL),
    (4392, 'tanzil-uthmani-v1.1', 43, 67, 'ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ', '0eaa065dcd8a67b9e2df2721964a425bbae015d1fe6824c7ae4568ad546a656b', 'ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ', '0eaa065dcd8a67b9e2df2721964a425bbae015d1fe6824c7ae4568ad546a656b', '0eaa065dcd8a67b9e2df2721964a425bbae015d1fe6824c7ae4568ad546a656b', NULL, 'الاخلاء يومئذ بعضهم لبعض عدو الا المتقين', 25, 50, 198, 1, 6, 494, false, NULL),
    (4393, 'tanzil-uthmani-v1.1', 43, 68, 'يَٰعِبَادِ لَا خَوْفٌ عَلَيْكُمُ ٱلْيَوْمَ وَلَآ أَنتُمْ تَحْزَنُونَ', '6ce4d94068759e70aed92545943a915d0fbf8fd5f542959f0c295c18efe18975', 'يَٰعِبَادِ لَا خَوْفٌ عَلَيْكُمُ ٱلْيَوْمَ وَلَآ أَنتُمْ تَحْزَنُونَ', '6ce4d94068759e70aed92545943a915d0fbf8fd5f542959f0c295c18efe18975', '6ce4d94068759e70aed92545943a915d0fbf8fd5f542959f0c295c18efe18975', NULL, 'يعباد لا خوف عليكم اليوم ولا انتم تحزنون', 25, 50, 198, 1, 6, 494, false, NULL),
    (4394, 'tanzil-uthmani-v1.1', 43, 69, 'ٱلَّذِينَ ءَامَنُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ مُسْلِمِينَ', 'd97289edcb1a074d2aefea83c609391e49df9f8e54c21429970c6e6b3e277084', 'ٱلَّذِينَ ءَامَنُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ مُسْلِمِينَ', 'd97289edcb1a074d2aefea83c609391e49df9f8e54c21429970c6e6b3e277084', 'd97289edcb1a074d2aefea83c609391e49df9f8e54c21429970c6e6b3e277084', NULL, 'الذين ءامنوا بايتنا وكانوا مسلمين', 25, 50, 198, 1, 6, 494, false, NULL),
    (4395, 'tanzil-uthmani-v1.1', 43, 70, 'ٱدْخُلُوا۟ ٱلْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ', '9d415aea31074d2e5b7b91b11373b05b5d6301659d38d5ca004a1dcf69c3e3ce', 'ٱدْخُلُوا۟ ٱلْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ', '9d415aea31074d2e5b7b91b11373b05b5d6301659d38d5ca004a1dcf69c3e3ce', '9d415aea31074d2e5b7b91b11373b05b5d6301659d38d5ca004a1dcf69c3e3ce', NULL, 'ادخلوا الجنه انتم وازوجكم تحبرون', 25, 50, 198, 1, 6, 494, false, NULL),
    (4396, 'tanzil-uthmani-v1.1', 43, 71, 'يُطَافُ عَلَيْهِم بِصِحَافٍ مِّن ذَهَبٍ وَأَكْوَابٍ وَفِيهَا مَا تَشْتَهِيهِ ٱلْأَنفُسُ وَتَلَذُّ ٱلْأَعْيُنُ وَأَنتُمْ فِيهَا خَٰلِدُونَ', '96ebd688c16361b5aa2c5eb322895d9d64ffa166b316c70f3b155ed8bc527e5f', 'يُطَافُ عَلَيْهِم بِصِحَافٍ مِّن ذَهَبٍ وَأَكْوَابٍ وَفِيهَا مَا تَشْتَهِيهِ ٱلْأَنفُسُ وَتَلَذُّ ٱلْأَعْيُنُ وَأَنتُمْ فِيهَا خَٰلِدُونَ', '96ebd688c16361b5aa2c5eb322895d9d64ffa166b316c70f3b155ed8bc527e5f', '96ebd688c16361b5aa2c5eb322895d9d64ffa166b316c70f3b155ed8bc527e5f', NULL, 'يطاف عليهم بصحاف من ذهب واكواب وفيها ما تشتهيه الانفس وتلذ الاعين وانتم فيها خلدون', 25, 50, 198, 1, 6, 494, false, NULL),
    (4397, 'tanzil-uthmani-v1.1', 43, 72, 'وَتِلْكَ ٱلْجَنَّةُ ٱلَّتِىٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 'bd3363cdce5bdea83f1f7310c98ca99d895ab539d4c90c20723c934c20e31c64', 'وَتِلْكَ ٱلْجَنَّةُ ٱلَّتِىٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 'bd3363cdce5bdea83f1f7310c98ca99d895ab539d4c90c20723c934c20e31c64', 'bd3363cdce5bdea83f1f7310c98ca99d895ab539d4c90c20723c934c20e31c64', NULL, 'وتلك الجنه التي اورثتموها بما كنتم تعملون', 25, 50, 198, 1, 6, 494, false, NULL),
    (4398, 'tanzil-uthmani-v1.1', 43, 73, 'لَكُمْ فِيهَا فَٰكِهَةٌ كَثِيرَةٌ مِّنْهَا تَأْكُلُونَ', 'cc737a6c7063d0eb82e432a5149201e63a647985756da608fa4239b807222c6c', 'لَكُمْ فِيهَا فَٰكِهَةٌ كَثِيرَةٌ مِّنْهَا تَأْكُلُونَ', 'cc737a6c7063d0eb82e432a5149201e63a647985756da608fa4239b807222c6c', 'cc737a6c7063d0eb82e432a5149201e63a647985756da608fa4239b807222c6c', NULL, 'لكم فيها فكهه كثيره منها تاكلون', 25, 50, 198, 1, 6, 494, false, NULL),
    (4399, 'tanzil-uthmani-v1.1', 43, 74, 'إِنَّ ٱلْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَٰلِدُونَ', '5f97d0b7c0960887d0308cacd41ce874714d2811fd0e70daafc6377c56cdb2d0', 'إِنَّ ٱلْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَٰلِدُونَ', '5f97d0b7c0960887d0308cacd41ce874714d2811fd0e70daafc6377c56cdb2d0', '5f97d0b7c0960887d0308cacd41ce874714d2811fd0e70daafc6377c56cdb2d0', NULL, 'ان المجرمين في عذاب جهنم خلدون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4400, 'tanzil-uthmani-v1.1', 43, 75, 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ', '25feb097fbff7aead2701cc9c30e3e23e339416374184c1f04f397d15ebfd9b7', 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ', '25feb097fbff7aead2701cc9c30e3e23e339416374184c1f04f397d15ebfd9b7', '25feb097fbff7aead2701cc9c30e3e23e339416374184c1f04f397d15ebfd9b7', NULL, 'لا يفتر عنهم وهم فيه مبلسون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4401, 'tanzil-uthmani-v1.1', 43, 76, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوا۟ هُمُ ٱلظَّٰلِمِينَ', '6b3402e931179f83745ca701f3a6f27462ef2b21bee6e1e1f888278f30eb533e', 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوا۟ هُمُ ٱلظَّٰلِمِينَ', '6b3402e931179f83745ca701f3a6f27462ef2b21bee6e1e1f888278f30eb533e', '6b3402e931179f83745ca701f3a6f27462ef2b21bee6e1e1f888278f30eb533e', NULL, 'وما ظلمنهم ولكن كانوا هم الظلمين', 25, 50, 198, 1, 6, 495, false, NULL),
    (4402, 'tanzil-uthmani-v1.1', 43, 77, 'وَنَادَوْا۟ يَٰمَٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُم مَّٰكِثُونَ', '6bb120a41246af6a76f10ba442883608354d5bfbb5fd22309cfdd1ab165bf2a9', 'وَنَادَوْا۟ يَٰمَٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُم مَّٰكِثُونَ', '6bb120a41246af6a76f10ba442883608354d5bfbb5fd22309cfdd1ab165bf2a9', '6bb120a41246af6a76f10ba442883608354d5bfbb5fd22309cfdd1ab165bf2a9', NULL, 'ونادوا يملك ليقض علينا ربك قال انكم مكثون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4403, 'tanzil-uthmani-v1.1', 43, 78, 'لَقَدْ جِئْنَٰكُم بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَٰرِهُونَ', '94c2723c358608b90fb447b97caa2123cf700260b257d2fc2faf402e51a88fe4', 'لَقَدْ جِئْنَٰكُم بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَٰرِهُونَ', '94c2723c358608b90fb447b97caa2123cf700260b257d2fc2faf402e51a88fe4', '94c2723c358608b90fb447b97caa2123cf700260b257d2fc2faf402e51a88fe4', NULL, 'لقد جئنكم بالحق ولكن اكثركم للحق كرهون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4404, 'tanzil-uthmani-v1.1', 43, 79, 'أَمْ أَبْرَمُوٓا۟ أَمْرًا فَإِنَّا مُبْرِمُونَ', 'a7574c42cbfd09b7903bf6c1e63637bccad96200dcaab6dfe692d49e77479766', 'أَمْ أَبْرَمُوٓا۟ أَمْرًا فَإِنَّا مُبْرِمُونَ', 'a7574c42cbfd09b7903bf6c1e63637bccad96200dcaab6dfe692d49e77479766', 'a7574c42cbfd09b7903bf6c1e63637bccad96200dcaab6dfe692d49e77479766', NULL, 'ام ابرموا امرا فانا مبرمون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4405, 'tanzil-uthmani-v1.1', 43, 80, 'أَمْ يَحْسَبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَىٰهُم بَلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ', '9ce32d62d101ddb77042f43a931e568dfb90bc33763a0c36a6ed3b719afdc3db', 'أَمْ يَحْسَبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَىٰهُم بَلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ', '9ce32d62d101ddb77042f43a931e568dfb90bc33763a0c36a6ed3b719afdc3db', '9ce32d62d101ddb77042f43a931e568dfb90bc33763a0c36a6ed3b719afdc3db', NULL, 'ام يحسبون انا لا نسمع سرهم ونجويهم بلي ورسلنا لديهم يكتبون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4406, 'tanzil-uthmani-v1.1', 43, 81, 'قُلْ إِن كَانَ لِلرَّحْمَٰنِ وَلَدٌ فَأَنَا۠ أَوَّلُ ٱلْعَٰبِدِينَ', '567b09d7b79b3b3e1b8dac2f269a9e112f8b5292a74404c090ad5b666fce4e94', 'قُلْ إِن كَانَ لِلرَّحْمَٰنِ وَلَدٌ فَأَنَا۠ أَوَّلُ ٱلْعَٰبِدِينَ', '567b09d7b79b3b3e1b8dac2f269a9e112f8b5292a74404c090ad5b666fce4e94', '567b09d7b79b3b3e1b8dac2f269a9e112f8b5292a74404c090ad5b666fce4e94', NULL, 'قل ان كان للرحمن ولد فانا اول العبدين', 25, 50, 198, 1, 6, 495, false, NULL),
    (4407, 'tanzil-uthmani-v1.1', 43, 82, 'سُبْحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'c46c309dece17db502f6283c4620542848ac17103735416e935e6b32bb60185c', 'سُبْحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 'c46c309dece17db502f6283c4620542848ac17103735416e935e6b32bb60185c', 'c46c309dece17db502f6283c4620542848ac17103735416e935e6b32bb60185c', NULL, 'سبحن رب السموت والارض رب العرش عما يصفون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4408, 'tanzil-uthmani-v1.1', 43, 83, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', '5ffe0b41b7d2a18196e3c9436ed5151a492a55ff376283e80ca39c35d9041f3a', 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', '5ffe0b41b7d2a18196e3c9436ed5151a492a55ff376283e80ca39c35d9041f3a', '5ffe0b41b7d2a18196e3c9436ed5151a492a55ff376283e80ca39c35d9041f3a', NULL, 'فذرهم يخوضوا ويلعبوا حتي يلقوا يومهم الذي يوعدون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4409, 'tanzil-uthmani-v1.1', 43, 84, 'وَهُوَ ٱلَّذِى فِى ٱلسَّمَآءِ إِلَٰهٌ وَفِى ٱلْأَرْضِ إِلَٰهٌ وَهُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 'cd85cdf1b6d02d70b87990b9045b8dce42d76aca5e6b8b7bfce3ab65c1548ae9', 'وَهُوَ ٱلَّذِى فِى ٱلسَّمَآءِ إِلَٰهٌ وَفِى ٱلْأَرْضِ إِلَٰهٌ وَهُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 'cd85cdf1b6d02d70b87990b9045b8dce42d76aca5e6b8b7bfce3ab65c1548ae9', 'cd85cdf1b6d02d70b87990b9045b8dce42d76aca5e6b8b7bfce3ab65c1548ae9', NULL, 'وهو الذي في السماء اله وفي الارض اله وهو الحكيم العليم', 25, 50, 198, 1, 6, 495, false, NULL),
    (4410, 'tanzil-uthmani-v1.1', 43, 85, 'وَتَبَارَكَ ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَعِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ', '2017f9b1ca7122d2c9c0348f86fa4a99518ac1a2102d08c226ffcdd12d3d283f', 'وَتَبَارَكَ ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَعِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ', '2017f9b1ca7122d2c9c0348f86fa4a99518ac1a2102d08c226ffcdd12d3d283f', '2017f9b1ca7122d2c9c0348f86fa4a99518ac1a2102d08c226ffcdd12d3d283f', NULL, 'وتبارك الذي له ملك السموت والارض وما بينهما وعنده علم الساعه واليه ترجعون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4411, 'tanzil-uthmani-v1.1', 43, 86, 'وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ', 'ae34f513bd0a2c4bd0187874a5fb2313eec9e08ce3932d3c68f571a3c409a41a', 'وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ', 'ae34f513bd0a2c4bd0187874a5fb2313eec9e08ce3932d3c68f571a3c409a41a', 'ae34f513bd0a2c4bd0187874a5fb2313eec9e08ce3932d3c68f571a3c409a41a', NULL, 'ولا يملك الذين يدعون من دونه الشفعه الا من شهد بالحق وهم يعلمون', 25, 50, 198, 1, 6, 495, false, NULL),
    (4412, 'tanzil-uthmani-v1.1', 43, 87, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ٱللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', 'd6c73e2f40e87f58344bd7306d1a5b278e0a473bd658431cddee4ad9e590fbc2', 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ٱللَّهُ فَأَنَّىٰ يُؤْفَكُونَ', 'd6c73e2f40e87f58344bd7306d1a5b278e0a473bd658431cddee4ad9e590fbc2', 'd6c73e2f40e87f58344bd7306d1a5b278e0a473bd658431cddee4ad9e590fbc2', NULL, 'ولئن سالتهم من خلقهم ليقولن الله فاني يؤفكون', 25, 50, 198, 1, 6, 495, false, NULL),
