    (4428, 'tanzil-uthmani-v1.1', 44, 14, 'ثُمَّ تَوَلَّوْا۟ عَنْهُ وَقَالُوا۟ مُعَلَّمٌ مَّجْنُونٌ', 'b67873db882c75a9f3d4bcc513f304047c039fa978085fbb9a9bbd0dabfc7868', 'ثُمَّ تَوَلَّوْا۟ عَنْهُ وَقَالُوا۟ مُعَلَّمٌ مَّجْنُونٌ', 'b67873db882c75a9f3d4bcc513f304047c039fa978085fbb9a9bbd0dabfc7868', 'b67873db882c75a9f3d4bcc513f304047c039fa978085fbb9a9bbd0dabfc7868', NULL, 'ثم تولوا عنه وقالوا معلم مجنون', 25, 50, 198, 1, 6, 496, false, NULL),
    (4429, 'tanzil-uthmani-v1.1', 44, 15, 'إِنَّا كَاشِفُوا۟ ٱلْعَذَابِ قَلِيلًا إِنَّكُمْ عَآئِدُونَ', '1324e6b8cba2571f8ccfa14c957119ec388433a2247e1459c6544f08887cd4e7', 'إِنَّا كَاشِفُوا۟ ٱلْعَذَابِ قَلِيلًا إِنَّكُمْ عَآئِدُونَ', '1324e6b8cba2571f8ccfa14c957119ec388433a2247e1459c6544f08887cd4e7', '1324e6b8cba2571f8ccfa14c957119ec388433a2247e1459c6544f08887cd4e7', NULL, 'انا كاشفوا العذاب قليلا انكم عائدون', 25, 50, 198, 1, 6, 496, false, NULL),
    (4430, 'tanzil-uthmani-v1.1', 44, 16, 'يَوْمَ نَبْطِشُ ٱلْبَطْشَةَ ٱلْكُبْرَىٰٓ إِنَّا مُنتَقِمُونَ', 'c9d854c7dcc988042289095cddc66630ffc718e05e79022081e86ec595f77f78', 'يَوْمَ نَبْطِشُ ٱلْبَطْشَةَ ٱلْكُبْرَىٰٓ إِنَّا مُنتَقِمُونَ', 'c9d854c7dcc988042289095cddc66630ffc718e05e79022081e86ec595f77f78', 'c9d854c7dcc988042289095cddc66630ffc718e05e79022081e86ec595f77f78', NULL, 'يوم نبطش البطشه الكبري انا منتقمون', 25, 50, 198, 1, 6, 496, false, NULL),
    (4431, 'tanzil-uthmani-v1.1', 44, 17, 'وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌ كَرِيمٌ', '2956d5637f6df0778cdf77b5f29c70cb124f45935c8ce18b4d683b324868a210', 'وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌ كَرِيمٌ', '2956d5637f6df0778cdf77b5f29c70cb124f45935c8ce18b4d683b324868a210', '2956d5637f6df0778cdf77b5f29c70cb124f45935c8ce18b4d683b324868a210', NULL, 'ولقد فتنا قبلهم قوم فرعون وجاءهم رسول كريم', 25, 50, 199, 1, 6, 496, false, NULL),
    (4432, 'tanzil-uthmani-v1.1', 44, 18, 'أَنْ أَدُّوٓا۟ إِلَىَّ عِبَادَ ٱللَّهِ إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', '14425f37857143bb2347c95cbf48e5223e9f001adb3c33c0150419b90eff30d2', 'أَنْ أَدُّوٓا۟ إِلَىَّ عِبَادَ ٱللَّهِ إِنِّى لَكُمْ رَسُولٌ أَمِينٌ', '14425f37857143bb2347c95cbf48e5223e9f001adb3c33c0150419b90eff30d2', '14425f37857143bb2347c95cbf48e5223e9f001adb3c33c0150419b90eff30d2', NULL, 'ان ادوا الي عباد الله اني لكم رسول امين', 25, 50, 199, 1, 6, 496, false, NULL),
    (4433, 'tanzil-uthmani-v1.1', 44, 19, 'وَأَن لَّا تَعْلُوا۟ عَلَى ٱللَّهِ إِنِّىٓ ءَاتِيكُم بِسُلْطَٰنٍ مُّبِينٍ', '61bf0a387da32fbf713b198149d9ff949f539ceeff1131436b01afe65d4a0fbe', 'وَأَن لَّا تَعْلُوا۟ عَلَى ٱللَّهِ إِنِّىٓ ءَاتِيكُم بِسُلْطَٰنٍ مُّبِينٍ', '61bf0a387da32fbf713b198149d9ff949f539ceeff1131436b01afe65d4a0fbe', '61bf0a387da32fbf713b198149d9ff949f539ceeff1131436b01afe65d4a0fbe', NULL, 'وان لا تعلوا علي الله اني ءاتيكم بسلطن مبين', 25, 50, 199, 1, 6, 497, false, NULL),
    (4434, 'tanzil-uthmani-v1.1', 44, 20, 'وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ', '543555e2f3acb06103a1b97829f84eb2c3750bb888900768eca4c159268864e9', 'وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ', '543555e2f3acb06103a1b97829f84eb2c3750bb888900768eca4c159268864e9', '543555e2f3acb06103a1b97829f84eb2c3750bb888900768eca4c159268864e9', NULL, 'واني عذت بربي وربكم ان ترجمون', 25, 50, 199, 1, 6, 497, false, NULL),
    (4435, 'tanzil-uthmani-v1.1', 44, 21, 'وَإِن لَّمْ تُؤْمِنُوا۟ لِى فَٱعْتَزِلُونِ', '3db3ddfbaa24c218fb38db6f909091dd0f226e37ec2d13f9911d674426f13927', 'وَإِن لَّمْ تُؤْمِنُوا۟ لِى فَٱعْتَزِلُونِ', '3db3ddfbaa24c218fb38db6f909091dd0f226e37ec2d13f9911d674426f13927', '3db3ddfbaa24c218fb38db6f909091dd0f226e37ec2d13f9911d674426f13927', NULL, 'وان لم تؤمنوا لي فاعتزلون', 25, 50, 199, 1, 6, 497, false, NULL),
