    (4441, 'tanzil-uthmani-v1.1', 44, 27, 'وَنَعْمَةٍ كَانُوا۟ فِيهَا فَٰكِهِينَ', 'bb748fcfa3d164ecd9c4582d2ea292db0fa945f4009b9796cf26e57b484fa7b1', 'وَنَعْمَةٍ كَانُوا۟ فِيهَا فَٰكِهِينَ', 'bb748fcfa3d164ecd9c4582d2ea292db0fa945f4009b9796cf26e57b484fa7b1', 'bb748fcfa3d164ecd9c4582d2ea292db0fa945f4009b9796cf26e57b484fa7b1', NULL, 'ونعمه كانوا فيها فكهين', 25, 50, 199, 1, 6, 497, false, NULL),
