    (4445, 'tanzil-uthmani-v1.1', 44, 31, 'مِن فِرْعَوْنَ إِنَّهُۥ كَانَ عَالِيًا مِّنَ ٱلْمُسْرِفِينَ', '2fd2b2cc0cecb066d2a162f50269a8fae5554d331ef67e0f566080a5145a5003', 'مِن فِرْعَوْنَ إِنَّهُۥ كَانَ عَالِيًا مِّنَ ٱلْمُسْرِفِينَ', '2fd2b2cc0cecb066d2a162f50269a8fae5554d331ef67e0f566080a5145a5003', '2fd2b2cc0cecb066d2a162f50269a8fae5554d331ef67e0f566080a5145a5003', NULL, 'من فرعون انه كان عاليا من المسرفين', 25, 50, 199, 1, 6, 497, false, NULL),
    (4446, 'tanzil-uthmani-v1.1', 44, 32, 'وَلَقَدِ ٱخْتَرْنَٰهُمْ عَلَىٰ عِلْمٍ عَلَى ٱلْعَٰلَمِينَ', 'e84b3f0d0cceb2722917d98fff09c36c24a0adc5485544068ee61e99cda5a9e9', 'وَلَقَدِ ٱخْتَرْنَٰهُمْ عَلَىٰ عِلْمٍ عَلَى ٱلْعَٰلَمِينَ', 'e84b3f0d0cceb2722917d98fff09c36c24a0adc5485544068ee61e99cda5a9e9', 'e84b3f0d0cceb2722917d98fff09c36c24a0adc5485544068ee61e99cda5a9e9', NULL, 'ولقد اخترنهم علي علم علي العلمين', 25, 50, 199, 1, 6, 497, false, NULL),
    (4447, 'tanzil-uthmani-v1.1', 44, 33, 'وَءَاتَيْنَٰهُم مِّنَ ٱلْـَٔايَٰتِ مَا فِيهِ بَلَٰٓؤٌا۟ مُّبِينٌ', '96610ff985be105be527453c2e39fa61e2281e8844e12e6b7239b76a4b78a0aa', 'وَءَاتَيْنَٰهُم مِّنَ ٱلْـَٔايَٰتِ مَا فِيهِ بَلَٰٓؤٌا۟ مُّبِينٌ', '96610ff985be105be527453c2e39fa61e2281e8844e12e6b7239b76a4b78a0aa', '96610ff985be105be527453c2e39fa61e2281e8844e12e6b7239b76a4b78a0aa', NULL, 'وءاتينهم من الايت ما فيه بلؤا مبين', 25, 50, 199, 1, 6, 497, false, NULL),
    (4448, 'tanzil-uthmani-v1.1', 44, 34, 'إِنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ', '990978f7f400ecdb6f7e2aa442cff9e1e10a9066adda720236c81014c7a09384', 'إِنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ', '990978f7f400ecdb6f7e2aa442cff9e1e10a9066adda720236c81014c7a09384', '990978f7f400ecdb6f7e2aa442cff9e1e10a9066adda720236c81014c7a09384', NULL, 'ان هؤلاء ليقولون', 25, 50, 199, 1, 6, 497, false, NULL),
