    (4475, 'tanzil-uthmani-v1.1', 45, 2, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '630417016fb5d33747dc7fe4937d3268572dc1e26350870e4cc108fcc240cae4', 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '630417016fb5d33747dc7fe4937d3268572dc1e26350870e4cc108fcc240cae4', '630417016fb5d33747dc7fe4937d3268572dc1e26350870e4cc108fcc240cae4', NULL, 'تنزيل الكتب من الله العزيز الحكيم', 25, 50, 199, 1, 6, 499, false, NULL),
    (4476, 'tanzil-uthmani-v1.1', 45, 3, 'إِنَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَٰتٍ لِّلْمُؤْمِنِينَ', '6cfac86e1fff1fc0fdc05c8a28b83b0d6104072d8543c685008e51759d7c4818', 'إِنَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَـَٔايَٰتٍ لِّلْمُؤْمِنِينَ', '6cfac86e1fff1fc0fdc05c8a28b83b0d6104072d8543c685008e51759d7c4818', '6cfac86e1fff1fc0fdc05c8a28b83b0d6104072d8543c685008e51759d7c4818', NULL, 'ان في السموت والارض لايت للمؤمنين', 25, 50, 199, 1, 6, 499, false, NULL),
    (4477, 'tanzil-uthmani-v1.1', 45, 4, 'وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٌ لِّقَوْمٍ يُوقِنُونَ', '8453010e9a9877696695794d495697a77afebeb971a59c6eb1cecbb815b91898', 'وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٌ لِّقَوْمٍ يُوقِنُونَ', '8453010e9a9877696695794d495697a77afebeb971a59c6eb1cecbb815b91898', '8453010e9a9877696695794d495697a77afebeb971a59c6eb1cecbb815b91898', NULL, 'وفي خلقكم وما يبث من دابه ءايت لقوم يوقنون', 25, 50, 199, 1, 6, 499, false, NULL),
    (4478, 'tanzil-uthmani-v1.1', 45, 5, 'وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزْقٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ ٱلرِّيَٰحِ ءَايَٰتٌ لِّقَوْمٍ يَعْقِلُونَ', 'b38509f3ee39b4192b80bb53e0c3aeb84be8539ccbad2c9385a6a6b45143189a', 'وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزْقٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ ٱلرِّيَٰحِ ءَايَٰتٌ لِّقَوْمٍ يَعْقِلُونَ', 'b38509f3ee39b4192b80bb53e0c3aeb84be8539ccbad2c9385a6a6b45143189a', 'b38509f3ee39b4192b80bb53e0c3aeb84be8539ccbad2c9385a6a6b45143189a', NULL, 'واختلف اليل والنهار وما انزل الله من السماء من رزق فاحيا به الارض بعد موتها وتصريف الريح ءايت لقوم يعقلون', 25, 50, 199, 1, 6, 499, false, NULL),
    (4479, 'tanzil-uthmani-v1.1', 45, 6, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ فَبِأَىِّ حَدِيثٍۭ بَعْدَ ٱللَّهِ وَءَايَٰتِهِۦ يُؤْمِنُونَ', '548151bf22c99aef39e6c455edf072e532109e2c06994adf985492ea93baea2d', 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ فَبِأَىِّ حَدِيثٍۭ بَعْدَ ٱللَّهِ وَءَايَٰتِهِۦ يُؤْمِنُونَ', '548151bf22c99aef39e6c455edf072e532109e2c06994adf985492ea93baea2d', '548151bf22c99aef39e6c455edf072e532109e2c06994adf985492ea93baea2d', NULL, 'تلك ءايت الله نتلوها عليك بالحق فباي حديث بعد الله وءايته يؤمنون', 25, 50, 199, 1, 6, 499, false, NULL),
    (4480, 'tanzil-uthmani-v1.1', 45, 7, 'وَيْلٌ لِّكُلِّ أَفَّاكٍ أَثِيمٍ', '79da3bc689145187ff901f5611302f6c80306cade2f57d1ad1709a17167c74aa', 'وَيْلٌ لِّكُلِّ أَفَّاكٍ أَثِيمٍ', '79da3bc689145187ff901f5611302f6c80306cade2f57d1ad1709a17167c74aa', '79da3bc689145187ff901f5611302f6c80306cade2f57d1ad1709a17167c74aa', NULL, 'ويل لكل افاك اثيم', 25, 50, 199, 1, 6, 499, false, NULL),
    (4481, 'tanzil-uthmani-v1.1', 45, 8, 'يَسْمَعُ ءَايَٰتِ ٱللَّهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', '555c227bd7f6444e9cf12e9423f75a6367cc762804213d0c5b8e279506b8ff1d', 'يَسْمَعُ ءَايَٰتِ ٱللَّهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ', '555c227bd7f6444e9cf12e9423f75a6367cc762804213d0c5b8e279506b8ff1d', '555c227bd7f6444e9cf12e9423f75a6367cc762804213d0c5b8e279506b8ff1d', NULL, 'يسمع ءايت الله تتلي عليه ثم يصر مستكبرا كان لم يسمعها فبشره بعذاب اليم', 25, 50, 199, 1, 6, 499, false, NULL),
    (4482, 'tanzil-uthmani-v1.1', 45, 9, 'وَإِذَا عَلِمَ مِنْ ءَايَٰتِنَا شَيْـًٔا ٱتَّخَذَهَا هُزُوًا أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'f6e99e3323bda40884a4d5e708e35d7b9020ad9f61534ba6a3ae55474c49eef1', 'وَإِذَا عَلِمَ مِنْ ءَايَٰتِنَا شَيْـًٔا ٱتَّخَذَهَا هُزُوًا أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ', 'f6e99e3323bda40884a4d5e708e35d7b9020ad9f61534ba6a3ae55474c49eef1', 'f6e99e3323bda40884a4d5e708e35d7b9020ad9f61534ba6a3ae55474c49eef1', NULL, 'واذا علم من ءايتنا شيا اتخذها هزوا اولئك لهم عذاب مهين', 25, 50, 199, 1, 6, 499, false, NULL),
    (4483, 'tanzil-uthmani-v1.1', 45, 10, 'مِّن وَرَآئِهِمْ جَهَنَّمُ وَلَا يُغْنِى عَنْهُم مَّا كَسَبُوا۟ شَيْـًٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ وَلَهُمْ عَذَابٌ عَظِيمٌ', '48de4e6527e3e601a6eb3942bc97d5b6a51fe8fbf1725d012a958f3f749a2bbb', 'مِّن وَرَآئِهِمْ جَهَنَّمُ وَلَا يُغْنِى عَنْهُم مَّا كَسَبُوا۟ شَيْـًٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ وَلَهُمْ عَذَابٌ عَظِيمٌ', '48de4e6527e3e601a6eb3942bc97d5b6a51fe8fbf1725d012a958f3f749a2bbb', '48de4e6527e3e601a6eb3942bc97d5b6a51fe8fbf1725d012a958f3f749a2bbb', NULL, 'من ورائهم جهنم ولا يغني عنهم ما كسبوا شيا ولا ما اتخذوا من دون الله اولياء ولهم عذاب عظيم', 25, 50, 199, 1, 6, 499, false, NULL),
    (4484, 'tanzil-uthmani-v1.1', 45, 11, 'هَٰذَا هُدًى وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', 'fcc1f9a3bf74bca5ba5fccb723367649b561da5f7c454cb18ee8255691881f0d', 'هَٰذَا هُدًى وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ', 'fcc1f9a3bf74bca5ba5fccb723367649b561da5f7c454cb18ee8255691881f0d', 'fcc1f9a3bf74bca5ba5fccb723367649b561da5f7c454cb18ee8255691881f0d', NULL, 'هذا هدي والذين كفروا بايت ربهم لهم عذاب من رجز اليم', 25, 50, 199, 1, 6, 499, false, NULL),
    (4485, 'tanzil-uthmani-v1.1', 45, 12, 'ٱللَّهُ ٱلَّذِى سَخَّرَ لَكُمُ ٱلْبَحْرَ لِتَجْرِىَ ٱلْفُلْكُ فِيهِ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '5addf8fa9cfae52358b283e242581ddda282638b4bbd76dcfd78e6291f45197a', 'ٱللَّهُ ٱلَّذِى سَخَّرَ لَكُمُ ٱلْبَحْرَ لِتَجْرِىَ ٱلْفُلْكُ فِيهِ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', '5addf8fa9cfae52358b283e242581ddda282638b4bbd76dcfd78e6291f45197a', '5addf8fa9cfae52358b283e242581ddda282638b4bbd76dcfd78e6291f45197a', NULL, 'الله الذي سخر لكم البحر لتجري الفلك فيه بامره ولتبتغوا من فضله ولعلكم تشكرون', 25, 50, 200, 1, 6, 499, false, NULL),
    (4486, 'tanzil-uthmani-v1.1', 45, 13, 'وَسَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ جَمِيعًا مِّنْهُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', '49f2a19ebe79cd04767cabcae49690693177870233e7d1f6947e738f743d31c1', 'وَسَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ جَمِيعًا مِّنْهُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ', '49f2a19ebe79cd04767cabcae49690693177870233e7d1f6947e738f743d31c1', '49f2a19ebe79cd04767cabcae49690693177870233e7d1f6947e738f743d31c1', NULL, 'وسخر لكم ما في السموت وما في الارض جميعا منه ان في ذلك لايت لقوم يتفكرون', 25, 50, 200, 1, 6, 499, false, NULL),
    (4487, 'tanzil-uthmani-v1.1', 45, 14, 'قُل لِّلَّذِينَ ءَامَنُوا۟ يَغْفِرُوا۟ لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ ٱللَّهِ لِيَجْزِىَ قَوْمًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', '18ed67eed45d032bb860af406bdc0018a367329b1d3bf0add68da558e6691952', 'قُل لِّلَّذِينَ ءَامَنُوا۟ يَغْفِرُوا۟ لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ ٱللَّهِ لِيَجْزِىَ قَوْمًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', '18ed67eed45d032bb860af406bdc0018a367329b1d3bf0add68da558e6691952', '18ed67eed45d032bb860af406bdc0018a367329b1d3bf0add68da558e6691952', NULL, 'قل للذين ءامنوا يغفروا للذين لا يرجون ايام الله ليجزي قوما بما كانوا يكسبون', 25, 50, 200, 1, 6, 500, false, NULL),
    (4488, 'tanzil-uthmani-v1.1', 45, 15, 'مَنْ عَمِلَ صَٰلِحًا فَلِنَفْسِهِۦ وَمَنْ أَسَآءَ فَعَلَيْهَا ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', 'd088b42f5b18707a8102cb1b918259d435f37afba4ecf1e8627552f7ddc1c83d', 'مَنْ عَمِلَ صَٰلِحًا فَلِنَفْسِهِۦ وَمَنْ أَسَآءَ فَعَلَيْهَا ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', 'd088b42f5b18707a8102cb1b918259d435f37afba4ecf1e8627552f7ddc1c83d', 'd088b42f5b18707a8102cb1b918259d435f37afba4ecf1e8627552f7ddc1c83d', NULL, 'من عمل صلحا فلنفسه ومن اساء فعليها ثم الي ربكم ترجعون', 25, 50, 200, 1, 6, 500, false, NULL),
    (4489, 'tanzil-uthmani-v1.1', 45, 16, 'وَلَقَدْ ءَاتَيْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَى ٱلْعَٰلَمِينَ', 'b39903d23980874950735d6e1a923ffe0b6ca4ac03cc7fd9d4fc5b9f06013831', 'وَلَقَدْ ءَاتَيْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَى ٱلْعَٰلَمِينَ', 'b39903d23980874950735d6e1a923ffe0b6ca4ac03cc7fd9d4fc5b9f06013831', 'b39903d23980874950735d6e1a923ffe0b6ca4ac03cc7fd9d4fc5b9f06013831', NULL, 'ولقد ءاتينا بني اسرءيل الكتب والحكم والنبوه ورزقنهم من الطيبت وفضلنهم علي العلمين', 25, 50, 200, 1, 6, 500, false, NULL),
    (4490, 'tanzil-uthmani-v1.1', 45, 17, 'وَءَاتَيْنَٰهُم بَيِّنَٰتٍ مِّنَ ٱلْأَمْرِ فَمَا ٱخْتَلَفُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '9fec9dd09a79d767a2dda96d1e802fef65442fdb76145fbe7718f2909e50fe84', 'وَءَاتَيْنَٰهُم بَيِّنَٰتٍ مِّنَ ٱلْأَمْرِ فَمَا ٱخْتَلَفُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', '9fec9dd09a79d767a2dda96d1e802fef65442fdb76145fbe7718f2909e50fe84', '9fec9dd09a79d767a2dda96d1e802fef65442fdb76145fbe7718f2909e50fe84', NULL, 'وءاتينهم بينت من الامر فما اختلفوا الا من بعد ما جاءهم العلم بغيا بينهم ان ربك يقضي بينهم يوم القيمه فيما كانوا فيه يختلفون', 25, 50, 200, 1, 6, 500, false, NULL),
    (4491, 'tanzil-uthmani-v1.1', 45, 18, 'ثُمَّ جَعَلْنَٰكَ عَلَىٰ شَرِيعَةٍ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ', '28ec4b0cf376b4ac4777d99751b4141019fd99087fee74bb6beb4d088d10f234', 'ثُمَّ جَعَلْنَٰكَ عَلَىٰ شَرِيعَةٍ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ', '28ec4b0cf376b4ac4777d99751b4141019fd99087fee74bb6beb4d088d10f234', '28ec4b0cf376b4ac4777d99751b4141019fd99087fee74bb6beb4d088d10f234', NULL, 'ثم جعلنك علي شريعه من الامر فاتبعها ولا تتبع اهواء الذين لا يعلمون', 25, 50, 200, 1, 6, 500, false, NULL),
    (4492, 'tanzil-uthmani-v1.1', 45, 19, 'إِنَّهُمْ لَن يُغْنُوا۟ عَنكَ مِنَ ٱللَّهِ شَيْـًٔا وَإِنَّ ٱلظَّٰلِمِينَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَٱللَّهُ وَلِىُّ ٱلْمُتَّقِينَ', '2717bd07542353903ba184d28e8cb12362544cf2cd24d0ed674482aa5f8671ea', 'إِنَّهُمْ لَن يُغْنُوا۟ عَنكَ مِنَ ٱللَّهِ شَيْـًٔا وَإِنَّ ٱلظَّٰلِمِينَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ وَٱللَّهُ وَلِىُّ ٱلْمُتَّقِينَ', '2717bd07542353903ba184d28e8cb12362544cf2cd24d0ed674482aa5f8671ea', '2717bd07542353903ba184d28e8cb12362544cf2cd24d0ed674482aa5f8671ea', NULL, 'انهم لن يغنوا عنك من الله شيا وان الظلمين بعضهم اولياء بعض والله ولي المتقين', 25, 50, 200, 1, 6, 500, false, NULL),
    (4493, 'tanzil-uthmani-v1.1', 45, 20, 'هَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُوقِنُونَ', 'ac3178cdc4283f117499d752ad59cc608aaa1aa9d91fcea952435ec91d1e9d6f', 'هَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُوقِنُونَ', 'ac3178cdc4283f117499d752ad59cc608aaa1aa9d91fcea952435ec91d1e9d6f', 'ac3178cdc4283f117499d752ad59cc608aaa1aa9d91fcea952435ec91d1e9d6f', NULL, 'هذا بصئر للناس وهدي ورحمه لقوم يوقنون', 25, 50, 200, 1, 6, 500, false, NULL),
    (4494, 'tanzil-uthmani-v1.1', 45, 21, 'أَمْ حَسِبَ ٱلَّذِينَ ٱجْتَرَحُوا۟ ٱلسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَوَآءً مَّحْيَاهُمْ وَمَمَاتُهُمْ سَآءَ مَا يَحْكُمُونَ', '614d36d71877e9a0ebeacdb68157d5e227affc04308b82ecffb5e71227395547', 'أَمْ حَسِبَ ٱلَّذِينَ ٱجْتَرَحُوا۟ ٱلسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَوَآءً مَّحْيَاهُمْ وَمَمَاتُهُمْ سَآءَ مَا يَحْكُمُونَ', '614d36d71877e9a0ebeacdb68157d5e227affc04308b82ecffb5e71227395547', '614d36d71877e9a0ebeacdb68157d5e227affc04308b82ecffb5e71227395547', NULL, 'ام حسب الذين اجترحوا السيات ان نجعلهم كالذين ءامنوا وعملوا الصلحت سواء محياهم ومماتهم ساء ما يحكمون', 25, 50, 200, 1, 6, 500, false, NULL),
    (4495, 'tanzil-uthmani-v1.1', 45, 22, 'وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'c96f8f984ebf0fa47a44629d27d92f731642d1df5d8b4f9df88c7a0ac1777efe', 'وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 'c96f8f984ebf0fa47a44629d27d92f731642d1df5d8b4f9df88c7a0ac1777efe', 'c96f8f984ebf0fa47a44629d27d92f731642d1df5d8b4f9df88c7a0ac1777efe', NULL, 'وخلق الله السموت والارض بالحق ولتجزي كل نفس بما كسبت وهم لا يظلمون', 25, 50, 200, 1, 6, 500, false, NULL),
    (4496, 'tanzil-uthmani-v1.1', 45, 23, 'أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلْمٍ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةً فَمَن يَهْدِيهِ مِنۢ بَعْدِ ٱللَّهِ أَفَلَا تَذَكَّرُونَ', 'd7cc3a58e145c1864690bbf620bbd07dce9c71ebe0cf6557ad58821ec50fbc86', 'أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلْمٍ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةً فَمَن يَهْدِيهِ مِنۢ بَعْدِ ٱللَّهِ أَفَلَا تَذَكَّرُونَ', 'd7cc3a58e145c1864690bbf620bbd07dce9c71ebe0cf6557ad58821ec50fbc86', 'd7cc3a58e145c1864690bbf620bbd07dce9c71ebe0cf6557ad58821ec50fbc86', NULL, 'افرءيت من اتخذ الهه هويه واضله الله علي علم وختم علي سمعه وقلبه وجعل علي بصره غشوه فمن يهديه من بعد الله افلا تذكرون', 25, 50, 200, 1, 6, 501, false, NULL),
    (4497, 'tanzil-uthmani-v1.1', 45, 24, 'وَقَالُوا۟ مَا هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَآ إِلَّا ٱلدَّهْرُ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَظُنُّونَ', '47c655c7d2f635441bbe80975a974ad2f45f7c2f0138ec80477dfd13fdeb1710', 'وَقَالُوا۟ مَا هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَآ إِلَّا ٱلدَّهْرُ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَظُنُّونَ', '47c655c7d2f635441bbe80975a974ad2f45f7c2f0138ec80477dfd13fdeb1710', '47c655c7d2f635441bbe80975a974ad2f45f7c2f0138ec80477dfd13fdeb1710', NULL, 'وقالوا ما هي الا حياتنا الدنيا نموت ونحيا وما يهلكنا الا الدهر وما لهم بذلك من علم ان هم الا يظنون', 25, 50, 200, 1, 6, 501, false, NULL),
    (4498, 'tanzil-uthmani-v1.1', 45, 25, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ مَّا كَانَ حُجَّتَهُمْ إِلَّآ أَن قَالُوا۟ ٱئْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', '92c2393f7530bd0328379474ee658caa79fa582fdd9a7b6d140cf7e487976e3b', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ مَّا كَانَ حُجَّتَهُمْ إِلَّآ أَن قَالُوا۟ ٱئْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', '92c2393f7530bd0328379474ee658caa79fa582fdd9a7b6d140cf7e487976e3b', '92c2393f7530bd0328379474ee658caa79fa582fdd9a7b6d140cf7e487976e3b', NULL, 'واذا تتلي عليهم ءايتنا بينت ما كان حجتهم الا ان قالوا ائتوا بابائنا ان كنتم صدقين', 25, 50, 200, 1, 6, 501, false, NULL),
    (4499, 'tanzil-uthmani-v1.1', 45, 26, 'قُلِ ٱللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '8e53e42dfab7f2594e7f3eace2c8514ee49d12df17656aca5dd7ce7f2c972c78', 'قُلِ ٱللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', '8e53e42dfab7f2594e7f3eace2c8514ee49d12df17656aca5dd7ce7f2c972c78', '8e53e42dfab7f2594e7f3eace2c8514ee49d12df17656aca5dd7ce7f2c972c78', NULL, 'قل الله يحييكم ثم يميتكم ثم يجمعكم الي يوم القيمه لا ريب فيه ولكن اكثر الناس لا يعلمون', 25, 50, 200, 1, 6, 501, false, NULL),
    (4500, 'tanzil-uthmani-v1.1', 45, 27, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَخْسَرُ ٱلْمُبْطِلُونَ', '439d25a17978017880a8586d6be9c31d2f830a5482a28c4a90967c237a9ab8a7', 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍ يَخْسَرُ ٱلْمُبْطِلُونَ', '439d25a17978017880a8586d6be9c31d2f830a5482a28c4a90967c237a9ab8a7', '439d25a17978017880a8586d6be9c31d2f830a5482a28c4a90967c237a9ab8a7', NULL, 'ولله ملك السموت والارض ويوم تقوم الساعه يومئذ يخسر المبطلون', 25, 50, 200, 1, 6, 501, false, NULL)
