) VALUES
    (4501, 'tanzil-uthmani-v1.1', 45, 28, 'وَتَرَىٰ كُلَّ أُمَّةٍ جَاثِيَةً كُلُّ أُمَّةٍ تُدْعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', '981eeaba998dbb8081388064ac835bca438cd2a57f908043b74d43281063b54b', 'وَتَرَىٰ كُلَّ أُمَّةٍ جَاثِيَةً كُلُّ أُمَّةٍ تُدْعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', '981eeaba998dbb8081388064ac835bca438cd2a57f908043b74d43281063b54b', '981eeaba998dbb8081388064ac835bca438cd2a57f908043b74d43281063b54b', NULL, 'وتري كل امه جاثيه كل امه تدعي الي كتبها اليوم تجزون ما كنتم تعملون', 25, 50, 200, 1, 6, 501, false, NULL),
    (4502, 'tanzil-uthmani-v1.1', 45, 29, 'هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيْكُم بِٱلْحَقِّ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ', '1e8d19ea437d166d4448782a50eadbce7fc28b490364f9fea53c9de2d22dab97', 'هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيْكُم بِٱلْحَقِّ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ', '1e8d19ea437d166d4448782a50eadbce7fc28b490364f9fea53c9de2d22dab97', '1e8d19ea437d166d4448782a50eadbce7fc28b490364f9fea53c9de2d22dab97', NULL, 'هذا كتبنا ينطق عليكم بالحق انا كنا نستنسخ ما كنتم تعملون', 25, 50, 200, 1, 6, 501, false, NULL),
    (4503, 'tanzil-uthmani-v1.1', 45, 30, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِى رَحْمَتِهِۦ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْمُبِينُ', '394b5d0ea5c83c68a1725b59f8bea063a7e514aab660f0a225e79f42a5df7ed4', 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِى رَحْمَتِهِۦ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْمُبِينُ', '394b5d0ea5c83c68a1725b59f8bea063a7e514aab660f0a225e79f42a5df7ed4', '394b5d0ea5c83c68a1725b59f8bea063a7e514aab660f0a225e79f42a5df7ed4', NULL, 'فاما الذين ءامنوا وعملوا الصلحت فيدخلهم ربهم في رحمته ذلك هو الفوز المبين', 25, 50, 200, 1, 6, 501, false, NULL),
    (4504, 'tanzil-uthmani-v1.1', 45, 31, 'وَأَمَّا ٱلَّذِينَ كَفَرُوٓا۟ أَفَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَٱسْتَكْبَرْتُمْ وَكُنتُمْ قَوْمًا مُّجْرِمِينَ', 'e4bb42a139b74b907504b78e7c538725a655dfe1cfdc5884eee7b15b35d63e8a', 'وَأَمَّا ٱلَّذِينَ كَفَرُوٓا۟ أَفَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَٱسْتَكْبَرْتُمْ وَكُنتُمْ قَوْمًا مُّجْرِمِينَ', 'e4bb42a139b74b907504b78e7c538725a655dfe1cfdc5884eee7b15b35d63e8a', 'e4bb42a139b74b907504b78e7c538725a655dfe1cfdc5884eee7b15b35d63e8a', NULL, 'واما الذين كفروا افلم تكن ءايتي تتلي عليكم فاستكبرتم وكنتم قوما مجرمين', 25, 50, 200, 1, 6, 501, false, NULL),
    (4505, 'tanzil-uthmani-v1.1', 45, 32, 'وَإِذَا قِيلَ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱلسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِى مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنًّا وَمَا نَحْنُ بِمُسْتَيْقِنِينَ', '1b4bd78ee6b355c0f0b23fef16941c3357a2db0bbdf47d6f67e0ab59ea95e2f9', 'وَإِذَا قِيلَ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱلسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِى مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنًّا وَمَا نَحْنُ بِمُسْتَيْقِنِينَ', '1b4bd78ee6b355c0f0b23fef16941c3357a2db0bbdf47d6f67e0ab59ea95e2f9', '1b4bd78ee6b355c0f0b23fef16941c3357a2db0bbdf47d6f67e0ab59ea95e2f9', NULL, 'واذا قيل ان وعد الله حق والساعه لا ريب فيها قلتم ما ندري ما الساعه ان نظن الا ظنا وما نحن بمستيقنين', 25, 50, 200, 1, 6, 501, false, NULL),
    (4506, 'tanzil-uthmani-v1.1', 45, 33, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'd9077c6e228a429516891c19722638f2fd02a4f2255abae04d8a805869d3bf8f', 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'd9077c6e228a429516891c19722638f2fd02a4f2255abae04d8a805869d3bf8f', 'd9077c6e228a429516891c19722638f2fd02a4f2255abae04d8a805869d3bf8f', NULL, 'وبدا لهم سيات ما عملوا وحاق بهم ما كانوا به يستهزءون', 25, 50, 200, 1, 6, 502, false, NULL),
    (4507, 'tanzil-uthmani-v1.1', 45, 34, 'وَقِيلَ ٱلْيَوْمَ نَنسَىٰكُمْ كَمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', '019b2d2f2412e5e2af2737a13a8c2e516ea0ee8f0ed79f80af5da5aa71122770', 'وَقِيلَ ٱلْيَوْمَ نَنسَىٰكُمْ كَمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', '019b2d2f2412e5e2af2737a13a8c2e516ea0ee8f0ed79f80af5da5aa71122770', '019b2d2f2412e5e2af2737a13a8c2e516ea0ee8f0ed79f80af5da5aa71122770', NULL, 'وقيل اليوم ننسيكم كما نسيتم لقاء يومكم هذا وماويكم النار وما لكم من نصرين', 25, 50, 200, 1, 6, 502, false, NULL),
    (4508, 'tanzil-uthmani-v1.1', 45, 35, 'ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذْتُمْ ءَايَٰتِ ٱللَّهِ هُزُوًا وَغَرَّتْكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا فَٱلْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ', 'ea2aa52b468bc9d81a88b55d808a24518598f2cf01d6c0143b393020fef7cd72', 'ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذْتُمْ ءَايَٰتِ ٱللَّهِ هُزُوًا وَغَرَّتْكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا فَٱلْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ', 'ea2aa52b468bc9d81a88b55d808a24518598f2cf01d6c0143b393020fef7cd72', 'ea2aa52b468bc9d81a88b55d808a24518598f2cf01d6c0143b393020fef7cd72', NULL, 'ذلكم بانكم اتخذتم ءايت الله هزوا وغرتكم الحيوه الدنيا فاليوم لا يخرجون منها ولا هم يستعتبون', 25, 50, 200, 1, 6, 502, false, NULL),
    (4509, 'tanzil-uthmani-v1.1', 45, 36, 'فَلِلَّهِ ٱلْحَمْدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلْأَرْضِ رَبِّ ٱلْعَٰلَمِينَ', 'fcd3200cb576b2433d7017e64e85761b6a30405249112420b93d40bd25cfd733', 'فَلِلَّهِ ٱلْحَمْدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلْأَرْضِ رَبِّ ٱلْعَٰلَمِينَ', 'fcd3200cb576b2433d7017e64e85761b6a30405249112420b93d40bd25cfd733', 'fcd3200cb576b2433d7017e64e85761b6a30405249112420b93d40bd25cfd733', NULL, 'فلله الحمد رب السموت ورب الارض رب العلمين', 25, 50, 200, 1, 6, 502, false, NULL),
    (4510, 'tanzil-uthmani-v1.1', 45, 37, 'وَلَهُ ٱلْكِبْرِيَآءُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '88c94ec337d6dd26b4ce06d0075d0479422be44f2baf8a59d7723953a2b8eccf', 'وَلَهُ ٱلْكِبْرِيَآءُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '88c94ec337d6dd26b4ce06d0075d0479422be44f2baf8a59d7723953a2b8eccf', '88c94ec337d6dd26b4ce06d0075d0479422be44f2baf8a59d7723953a2b8eccf', NULL, 'وله الكبرياء في السموت والارض وهو العزيز الحكيم', 25, 50, 200, 1, 6, 502, false, NULL),
    (4511, 'tanzil-uthmani-v1.1', 46, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 'b4f3f13e19bbe78e5f72edb60140cdae2eb77fceae263ed0d2b48f30c7cc67fd', 'حمٓ', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'dfd2d839ddbc10542932f547259642a551e312d89a06e3037fe385a1a7a914e0', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'حم', 26, 51, 201, 1, 6, 502, false, NULL),
    (4512, 'tanzil-uthmani-v1.1', 46, 2, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '630417016fb5d33747dc7fe4937d3268572dc1e26350870e4cc108fcc240cae4', 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '630417016fb5d33747dc7fe4937d3268572dc1e26350870e4cc108fcc240cae4', '630417016fb5d33747dc7fe4937d3268572dc1e26350870e4cc108fcc240cae4', NULL, 'تنزيل الكتب من الله العزيز الحكيم', 26, 51, 201, 1, 6, 502, false, NULL),
    (4513, 'tanzil-uthmani-v1.1', 46, 3, 'مَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى وَٱلَّذِينَ كَفَرُوا۟ عَمَّآ أُنذِرُوا۟ مُعْرِضُونَ', 'fee5c824c4444b89978da9cc2d9fc1ed39cd467a70f84d92fa17d36dcbab78c7', 'مَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍ مُّسَمًّى وَٱلَّذِينَ كَفَرُوا۟ عَمَّآ أُنذِرُوا۟ مُعْرِضُونَ', 'fee5c824c4444b89978da9cc2d9fc1ed39cd467a70f84d92fa17d36dcbab78c7', 'fee5c824c4444b89978da9cc2d9fc1ed39cd467a70f84d92fa17d36dcbab78c7', NULL, 'ما خلقنا السموت والارض وما بينهما الا بالحق واجل مسمي والذين كفروا عما انذروا معرضون', 26, 51, 201, 1, 6, 502, false, NULL),
    (4514, 'tanzil-uthmani-v1.1', 46, 4, 'قُلْ أَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَٰوَٰتِ ٱئْتُونِى بِكِتَٰبٍ مِّن قَبْلِ هَٰذَآ أَوْ أَثَٰرَةٍ مِّنْ عِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', '803fc12db25e7f80e762bd1446f0c8aaf317732b54c20cfd8ebb0cf6c1548a9b', 'قُلْ أَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَٰوَٰتِ ٱئْتُونِى بِكِتَٰبٍ مِّن قَبْلِ هَٰذَآ أَوْ أَثَٰرَةٍ مِّنْ عِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', '803fc12db25e7f80e762bd1446f0c8aaf317732b54c20cfd8ebb0cf6c1548a9b', '803fc12db25e7f80e762bd1446f0c8aaf317732b54c20cfd8ebb0cf6c1548a9b', NULL, 'قل ارءيتم ما تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السموت ائتوني بكتب من قبل هذا او اثره من علم ان كنتم صدقين', 26, 51, 201, 1, 6, 502, false, NULL),
    (4515, 'tanzil-uthmani-v1.1', 46, 5, 'وَمَنْ أَضَلُّ مِمَّن يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا يَسْتَجِيبُ لَهُۥٓ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ وَهُمْ عَن دُعَآئِهِمْ غَٰفِلُونَ', 'ed7423b6097db71144361ecf6252f3c6bedce26b26f583b22d335e023e50bb82', 'وَمَنْ أَضَلُّ مِمَّن يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا يَسْتَجِيبُ لَهُۥٓ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ وَهُمْ عَن دُعَآئِهِمْ غَٰفِلُونَ', 'ed7423b6097db71144361ecf6252f3c6bedce26b26f583b22d335e023e50bb82', 'ed7423b6097db71144361ecf6252f3c6bedce26b26f583b22d335e023e50bb82', NULL, 'ومن اضل ممن يدعوا من دون الله من لا يستجيب له الي يوم القيمه وهم عن دعائهم غفلون', 26, 51, 201, 1, 6, 502, false, NULL),
    (4516, 'tanzil-uthmani-v1.1', 46, 6, 'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمْ أَعْدَآءً وَكَانُوا۟ بِعِبَادَتِهِمْ كَٰفِرِينَ', '5eb0cfc0c78e237a2f57ed21572337b6dbe1e45dc6a64da41207f7cb070afc07', 'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمْ أَعْدَآءً وَكَانُوا۟ بِعِبَادَتِهِمْ كَٰفِرِينَ', '5eb0cfc0c78e237a2f57ed21572337b6dbe1e45dc6a64da41207f7cb070afc07', '5eb0cfc0c78e237a2f57ed21572337b6dbe1e45dc6a64da41207f7cb070afc07', NULL, 'واذا حشر الناس كانوا لهم اعداء وكانوا بعبادتهم كفرين', 26, 51, 201, 1, 6, 503, false, NULL),
    (4517, 'tanzil-uthmani-v1.1', 46, 7, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ هَٰذَا سِحْرٌ مُّبِينٌ', '7bbb401e4abe6c1540b5cbdc5bca5d2c79cadb5ea8883db0c36e660bef3daea8', 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ هَٰذَا سِحْرٌ مُّبِينٌ', '7bbb401e4abe6c1540b5cbdc5bca5d2c79cadb5ea8883db0c36e660bef3daea8', '7bbb401e4abe6c1540b5cbdc5bca5d2c79cadb5ea8883db0c36e660bef3daea8', NULL, 'واذا تتلي عليهم ءايتنا بينت قال الذين كفروا للحق لما جاءهم هذا سحر مبين', 26, 51, 201, 1, 6, 503, false, NULL),
    (4518, 'tanzil-uthmani-v1.1', 46, 8, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَلَا تَمْلِكُونَ لِى مِنَ ٱللَّهِ شَيْـًٔا هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ كَفَىٰ بِهِۦ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '1c5de24b31e0a4b9affcdc16f13a705d34087fbacf35ae616866e6e63af4952d', 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَلَا تَمْلِكُونَ لِى مِنَ ٱللَّهِ شَيْـًٔا هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ كَفَىٰ بِهِۦ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '1c5de24b31e0a4b9affcdc16f13a705d34087fbacf35ae616866e6e63af4952d', '1c5de24b31e0a4b9affcdc16f13a705d34087fbacf35ae616866e6e63af4952d', NULL, 'ام يقولون افتريه قل ان افتريته فلا تملكون لي من الله شيا هو اعلم بما تفيضون فيه كفي به شهيدا بيني وبينكم وهو الغفور الرحيم', 26, 51, 201, 1, 6, 503, false, NULL),
    (4519, 'tanzil-uthmani-v1.1', 46, 9, 'قُلْ مَا كُنتُ بِدْعًا مِّنَ ٱلرُّسُلِ وَمَآ أَدْرِى مَا يُفْعَلُ بِى وَلَا بِكُمْ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ', '5989d2e3645b96067928742a55a0297849029ef735d425d5d9d0330c7fee3611', 'قُلْ مَا كُنتُ بِدْعًا مِّنَ ٱلرُّسُلِ وَمَآ أَدْرِى مَا يُفْعَلُ بِى وَلَا بِكُمْ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٌ مُّبِينٌ', '5989d2e3645b96067928742a55a0297849029ef735d425d5d9d0330c7fee3611', '5989d2e3645b96067928742a55a0297849029ef735d425d5d9d0330c7fee3611', NULL, 'قل ما كنت بدعا من الرسل وما ادري ما يفعل بي ولا بكم ان اتبع الا ما يوحي الي وما انا الا نذير مبين', 26, 51, 201, 1, 6, 503, false, NULL),
    (4520, 'tanzil-uthmani-v1.1', 46, 10, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَٱسْتَكْبَرْتُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '16a2295d49c95ec1a0be7912e02dd0ca8382284dd302626d150333295cf92b11', 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَٱسْتَكْبَرْتُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '16a2295d49c95ec1a0be7912e02dd0ca8382284dd302626d150333295cf92b11', '16a2295d49c95ec1a0be7912e02dd0ca8382284dd302626d150333295cf92b11', NULL, 'قل ارءيتم ان كان من عند الله وكفرتم به وشهد شاهد من بني اسرءيل علي مثله فامن واستكبرتم ان الله لا يهدي القوم الظلمين', 26, 51, 201, 1, 6, 503, false, NULL),
    (4521, 'tanzil-uthmani-v1.1', 46, 11, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ لَوْ كَانَ خَيْرًا مَّا سَبَقُونَآ إِلَيْهِ وَإِذْ لَمْ يَهْتَدُوا۟ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفْكٌ قَدِيمٌ', 'abb616b807340286f499531d6db8b5e63554dae27a60f2ba3d98255e19339106', 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ لَوْ كَانَ خَيْرًا مَّا سَبَقُونَآ إِلَيْهِ وَإِذْ لَمْ يَهْتَدُوا۟ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفْكٌ قَدِيمٌ', 'abb616b807340286f499531d6db8b5e63554dae27a60f2ba3d98255e19339106', 'abb616b807340286f499531d6db8b5e63554dae27a60f2ba3d98255e19339106', NULL, 'وقال الذين كفروا للذين ءامنوا لو كان خيرا ما سبقونا اليه واذ لم يهتدوا به فسيقولون هذا افك قديم', 26, 51, 201, 1, 6, 503, false, NULL),
    (4522, 'tanzil-uthmani-v1.1', 46, 12, 'وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً وَهَٰذَا كِتَٰبٌ مُّصَدِّقٌ لِّسَانًا عَرَبِيًّا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُوا۟ وَبُشْرَىٰ لِلْمُحْسِنِينَ', '746a0e231267fe70cc220020e5fc9bc3499a8b0a73c61f8a7ffe3f7c8b9c341b', 'وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًا وَرَحْمَةً وَهَٰذَا كِتَٰبٌ مُّصَدِّقٌ لِّسَانًا عَرَبِيًّا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُوا۟ وَبُشْرَىٰ لِلْمُحْسِنِينَ', '746a0e231267fe70cc220020e5fc9bc3499a8b0a73c61f8a7ffe3f7c8b9c341b', '746a0e231267fe70cc220020e5fc9bc3499a8b0a73c61f8a7ffe3f7c8b9c341b', NULL, 'ومن قبله كتب موسي اماما ورحمه وهذا كتب مصدق لسانا عربيا لينذر الذين ظلموا وبشري للمحسنين', 26, 51, 201, 1, 6, 503, false, NULL),
    (4523, 'tanzil-uthmani-v1.1', 46, 13, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'f6fa19b796be5c88d0c30f714f7266c0f1361681d3c3eea11786e8e8d604c0c5', 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'f6fa19b796be5c88d0c30f714f7266c0f1361681d3c3eea11786e8e8d604c0c5', 'f6fa19b796be5c88d0c30f714f7266c0f1361681d3c3eea11786e8e8d604c0c5', NULL, 'ان الذين قالوا ربنا الله ثم استقموا فلا خوف عليهم ولا هم يحزنون', 26, 51, 201, 1, 6, 503, false, NULL),
    (4524, 'tanzil-uthmani-v1.1', 46, 14, 'أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', '86e59d1b048a1ef8ce468e3bbdc9db0bf89ec030e52fbdcb4e1924f0c8fbe508', 'أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', '86e59d1b048a1ef8ce468e3bbdc9db0bf89ec030e52fbdcb4e1924f0c8fbe508', '86e59d1b048a1ef8ce468e3bbdc9db0bf89ec030e52fbdcb4e1924f0c8fbe508', NULL, 'اولئك اصحب الجنه خلدين فيها جزاء بما كانوا يعملون', 26, 51, 201, 1, 6, 503, false, NULL),
    (4525, 'tanzil-uthmani-v1.1', 46, 15, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ إِحْسَٰنًا حَمَلَتْهُ أُمُّهُۥ كُرْهًا وَوَضَعَتْهُ كُرْهًا وَحَمْلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهْرًا حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرْبَعِينَ سَنَةً قَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًا تَرْضَىٰهُ وَأَصْلِحْ لِى فِى ذُرِّيَّتِىٓ إِنِّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ ٱلْمُسْلِمِينَ', '085f9c936feefc112a0e64dc6cdfab916fb0b4135b2b5ebd8581f0dcfac71c8d', 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ إِحْسَٰنًا حَمَلَتْهُ أُمُّهُۥ كُرْهًا وَوَضَعَتْهُ كُرْهًا وَحَمْلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهْرًا حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرْبَعِينَ سَنَةً قَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًا تَرْضَىٰهُ وَأَصْلِحْ لِى فِى ذُرِّيَّتِىٓ إِنِّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ ٱلْمُسْلِمِينَ', '085f9c936feefc112a0e64dc6cdfab916fb0b4135b2b5ebd8581f0dcfac71c8d', '085f9c936feefc112a0e64dc6cdfab916fb0b4135b2b5ebd8581f0dcfac71c8d', NULL, 'ووصينا الانسن بولديه احسنا حملته امه كرها ووضعته كرها وحمله وفصله ثلثون شهرا حتي اذا بلغ اشده وبلغ اربعين سنه قال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلي ولدي وان اعمل صلحا ترضيه واصلح لي في ذريتي اني تبت اليك واني من المسلمين', 26, 51, 201, 1, 6, 504, false, NULL),
    (4526, 'tanzil-uthmani-v1.1', 46, 16, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِىٓ أَصْحَٰبِ ٱلْجَنَّةِ وَعْدَ ٱلصِّدْقِ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', '8f19cdbc2f01457144f61047d29348b8108d79684d838a4c02a56fc343667210', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِىٓ أَصْحَٰبِ ٱلْجَنَّةِ وَعْدَ ٱلصِّدْقِ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', '8f19cdbc2f01457144f61047d29348b8108d79684d838a4c02a56fc343667210', '8f19cdbc2f01457144f61047d29348b8108d79684d838a4c02a56fc343667210', NULL, 'اولئك الذين نتقبل عنهم احسن ما عملوا ونتجاوز عن سياتهم في اصحب الجنه وعد الصدق الذي كانوا يوعدون', 26, 51, 201, 1, 6, 504, false, NULL),
    (4527, 'tanzil-uthmani-v1.1', 46, 17, 'وَٱلَّذِى قَالَ لِوَٰلِدَيْهِ أُفٍّ لَّكُمَآ أَتَعِدَانِنِىٓ أَنْ أُخْرَجَ وَقَدْ خَلَتِ ٱلْقُرُونُ مِن قَبْلِى وَهُمَا يَسْتَغِيثَانِ ٱللَّهَ وَيْلَكَ ءَامِنْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَيَقُولُ مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', '42de08705173eeb1873d85e7744c9680206e3938a8bf04fdbb36dd5a8e3ea17f', 'وَٱلَّذِى قَالَ لِوَٰلِدَيْهِ أُفٍّ لَّكُمَآ أَتَعِدَانِنِىٓ أَنْ أُخْرَجَ وَقَدْ خَلَتِ ٱلْقُرُونُ مِن قَبْلِى وَهُمَا يَسْتَغِيثَانِ ٱللَّهَ وَيْلَكَ ءَامِنْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَيَقُولُ مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', '42de08705173eeb1873d85e7744c9680206e3938a8bf04fdbb36dd5a8e3ea17f', '42de08705173eeb1873d85e7744c9680206e3938a8bf04fdbb36dd5a8e3ea17f', NULL, 'والذي قال لولديه اف لكما اتعدانني ان اخرج وقد خلت القرون من قبلي وهما يستغيثان الله ويلك ءامن ان وعد الله حق فيقول ما هذا الا اسطير الاولين', 26, 51, 201, 1, 6, 504, false, NULL),
    (4528, 'tanzil-uthmani-v1.1', 46, 18, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', '12d38a4c4ea171c92a84aa44a92eab747d0aabf954271dd51be58d357cc55379', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', '12d38a4c4ea171c92a84aa44a92eab747d0aabf954271dd51be58d357cc55379', '12d38a4c4ea171c92a84aa44a92eab747d0aabf954271dd51be58d357cc55379', NULL, 'اولئك الذين حق عليهم القول في امم قد خلت من قبلهم من الجن والانس انهم كانوا خسرين', 26, 51, 201, 1, 6, 504, false, NULL),
    (4529, 'tanzil-uthmani-v1.1', 46, 19, 'وَلِكُلٍّ دَرَجَٰتٌ مِّمَّا عَمِلُوا۟ وَلِيُوَفِّيَهُمْ أَعْمَٰلَهُمْ وَهُمْ لَا يُظْلَمُونَ', '72d72f5cc6a112f49dedbf421d1b7c363b789cb1149d2bbd79a402a1b5e5b89f', 'وَلِكُلٍّ دَرَجَٰتٌ مِّمَّا عَمِلُوا۟ وَلِيُوَفِّيَهُمْ أَعْمَٰلَهُمْ وَهُمْ لَا يُظْلَمُونَ', '72d72f5cc6a112f49dedbf421d1b7c363b789cb1149d2bbd79a402a1b5e5b89f', '72d72f5cc6a112f49dedbf421d1b7c363b789cb1149d2bbd79a402a1b5e5b89f', NULL, 'ولكل درجت مما عملوا وليوفيهم اعملهم وهم لا يظلمون', 26, 51, 201, 1, 6, 504, false, NULL),
    (4530, 'tanzil-uthmani-v1.1', 46, 20, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذْهَبْتُمْ طَيِّبَٰتِكُمْ فِى حَيَاتِكُمُ ٱلدُّنْيَا وَٱسْتَمْتَعْتُم بِهَا فَٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ', '13d5b550dbab42d43c81c58b1d453885d849e6e210b2447ecc3830a84a06572f', 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذْهَبْتُمْ طَيِّبَٰتِكُمْ فِى حَيَاتِكُمُ ٱلدُّنْيَا وَٱسْتَمْتَعْتُم بِهَا فَٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ', '13d5b550dbab42d43c81c58b1d453885d849e6e210b2447ecc3830a84a06572f', '13d5b550dbab42d43c81c58b1d453885d849e6e210b2447ecc3830a84a06572f', NULL, 'ويوم يعرض الذين كفروا علي النار اذهبتم طيبتكم في حياتكم الدنيا واستمتعتم بها فاليوم تجزون عذاب الهون بما كنتم تستكبرون في الارض بغير الحق وبما كنتم تفسقون', 26, 51, 201, 1, 6, 504, false, NULL),
    (4531, 'tanzil-uthmani-v1.1', 46, 21, 'وَٱذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُۥ بِٱلْأَحْقَافِ وَقَدْ خَلَتِ ٱلنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'cedfc2ca8c2c85ee28b87853763b67bb9b03b8e401a025fa4d65b5d33cad70a3', 'وَٱذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُۥ بِٱلْأَحْقَافِ وَقَدْ خَلَتِ ٱلنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ', 'cedfc2ca8c2c85ee28b87853763b67bb9b03b8e401a025fa4d65b5d33cad70a3', 'cedfc2ca8c2c85ee28b87853763b67bb9b03b8e401a025fa4d65b5d33cad70a3', NULL, 'واذكر اخا عاد اذ انذر قومه بالاحقاف وقد خلت النذر من بين يديه ومن خلفه الا تعبدوا الا الله اني اخاف عليكم عذاب يوم عظيم', 26, 51, 202, 1, 6, 505, false, NULL),
    (4532, 'tanzil-uthmani-v1.1', 46, 22, 'قَالُوٓا۟ أَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'bbfd7ff01f5b5ec760002794ac1ec3170bd31077b62391285fb8b6fee4a0e5f3', 'قَالُوٓا۟ أَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 'bbfd7ff01f5b5ec760002794ac1ec3170bd31077b62391285fb8b6fee4a0e5f3', 'bbfd7ff01f5b5ec760002794ac1ec3170bd31077b62391285fb8b6fee4a0e5f3', NULL, 'قالوا اجئتنا لتافكنا عن ءالهتنا فاتنا بما تعدنا ان كنت من الصدقين', 26, 51, 202, 1, 6, 505, false, NULL),
    (4533, 'tanzil-uthmani-v1.1', 46, 23, 'قَالَ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', 'd45beaa1d7477f455620478efaa6625698893e3a60678d1126bcf01ce0870cae', 'قَالَ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًا تَجْهَلُونَ', 'd45beaa1d7477f455620478efaa6625698893e3a60678d1126bcf01ce0870cae', 'd45beaa1d7477f455620478efaa6625698893e3a60678d1126bcf01ce0870cae', NULL, 'قال انما العلم عند الله وابلغكم ما ارسلت به ولكني اريكم قوما تجهلون', 26, 51, 202, 1, 6, 505, false, NULL),
    (4534, 'tanzil-uthmani-v1.1', 46, 24, 'فَلَمَّا رَأَوْهُ عَارِضًا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا۟ هَٰذَا عَارِضٌ مُّمْطِرُنَا بَلْ هُوَ مَا ٱسْتَعْجَلْتُم بِهِۦ رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ', '3fe5d381797454a21ce1f7a5e21b4379298d29a6cd31ed1c3325beebf5ce956b', 'فَلَمَّا رَأَوْهُ عَارِضًا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا۟ هَٰذَا عَارِضٌ مُّمْطِرُنَا بَلْ هُوَ مَا ٱسْتَعْجَلْتُم بِهِۦ رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ', '3fe5d381797454a21ce1f7a5e21b4379298d29a6cd31ed1c3325beebf5ce956b', '3fe5d381797454a21ce1f7a5e21b4379298d29a6cd31ed1c3325beebf5ce956b', NULL, 'فلما راوه عارضا مستقبل اوديتهم قالوا هذا عارض ممطرنا بل هو ما استعجلتم به ريح فيها عذاب اليم', 26, 51, 202, 1, 6, 505, false, NULL),
    (4535, 'tanzil-uthmani-v1.1', 46, 25, 'تُدَمِّرُ كُلَّ شَىْءٍۭ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا۟ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمْ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', '5c48427a8ebc5735d4409a18eceb92e56654a184779385e42bbb48e71588577a', 'تُدَمِّرُ كُلَّ شَىْءٍۭ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا۟ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمْ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', '5c48427a8ebc5735d4409a18eceb92e56654a184779385e42bbb48e71588577a', '5c48427a8ebc5735d4409a18eceb92e56654a184779385e42bbb48e71588577a', NULL, 'تدمر كل شيء بامر ربها فاصبحوا لا يري الا مسكنهم كذلك نجزي القوم المجرمين', 26, 51, 202, 1, 6, 505, false, NULL),
    (4536, 'tanzil-uthmani-v1.1', 46, 26, 'وَلَقَدْ مَكَّنَّٰهُمْ فِيمَآ إِن مَّكَّنَّٰكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًا وَأَبْصَٰرًا وَأَفْـِٔدَةً فَمَآ أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَآ أَبْصَٰرُهُمْ وَلَآ أَفْـِٔدَتُهُم مِّن شَىْءٍ إِذْ كَانُوا۟ يَجْحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'b177dba2a8e44898204c49a15ad1798478a75cf8277d3eba1934be85d3274c6e', 'وَلَقَدْ مَكَّنَّٰهُمْ فِيمَآ إِن مَّكَّنَّٰكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًا وَأَبْصَٰرًا وَأَفْـِٔدَةً فَمَآ أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَآ أَبْصَٰرُهُمْ وَلَآ أَفْـِٔدَتُهُم مِّن شَىْءٍ إِذْ كَانُوا۟ يَجْحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 'b177dba2a8e44898204c49a15ad1798478a75cf8277d3eba1934be85d3274c6e', 'b177dba2a8e44898204c49a15ad1798478a75cf8277d3eba1934be85d3274c6e', NULL, 'ولقد مكنهم فيما ان مكنكم فيه وجعلنا لهم سمعا وابصرا وافده فما اغني عنهم سمعهم ولا ابصرهم ولا افدتهم من شيء اذ كانوا يجحدون بايت الله وحاق بهم ما كانوا به يستهزءون', 26, 51, 202, 1, 6, 505, false, NULL),
    (4537, 'tanzil-uthmani-v1.1', 46, 27, 'وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ ٱلْقُرَىٰ وَصَرَّفْنَا ٱلْـَٔايَٰتِ لَعَلَّهُمْ يَرْجِعُونَ', 'b400f2995d5b5c7f81bf1413eacddce3b927fadd4f395bd53b480d5a9711b05a', 'وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ ٱلْقُرَىٰ وَصَرَّفْنَا ٱلْـَٔايَٰتِ لَعَلَّهُمْ يَرْجِعُونَ', 'b400f2995d5b5c7f81bf1413eacddce3b927fadd4f395bd53b480d5a9711b05a', 'b400f2995d5b5c7f81bf1413eacddce3b927fadd4f395bd53b480d5a9711b05a', NULL, 'ولقد اهلكنا ما حولكم من القري وصرفنا الايت لعلهم يرجعون', 26, 51, 202, 1, 6, 505, false, NULL),
    (4538, 'tanzil-uthmani-v1.1', 46, 28, 'فَلَوْلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرْبَانًا ءَالِهَةًۢ بَلْ ضَلُّوا۟ عَنْهُمْ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا۟ يَفْتَرُونَ', '819de6cf5762c069f4c85c02888b48f74f461b87fdf0060151e96cc9585aa42a', 'فَلَوْلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرْبَانًا ءَالِهَةًۢ بَلْ ضَلُّوا۟ عَنْهُمْ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا۟ يَفْتَرُونَ', '819de6cf5762c069f4c85c02888b48f74f461b87fdf0060151e96cc9585aa42a', '819de6cf5762c069f4c85c02888b48f74f461b87fdf0060151e96cc9585aa42a', NULL, 'فلولا نصرهم الذين اتخذوا من دون الله قربانا ءالهه بل ضلوا عنهم وذلك افكهم وما كانوا يفترون', 26, 51, 202, 1, 6, 505, false, NULL),
    (4539, 'tanzil-uthmani-v1.1', 46, 29, 'وَإِذْ صَرَفْنَآ إِلَيْكَ نَفَرًا مِّنَ ٱلْجِنِّ يَسْتَمِعُونَ ٱلْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓا۟ أَنصِتُوا۟ فَلَمَّا قُضِىَ وَلَّوْا۟ إِلَىٰ قَوْمِهِم مُّنذِرِينَ', 'a8984b611e684400532053d3e09f035e6e1fb4f52d7bce3115506e9b5f05da0d', 'وَإِذْ صَرَفْنَآ إِلَيْكَ نَفَرًا مِّنَ ٱلْجِنِّ يَسْتَمِعُونَ ٱلْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓا۟ أَنصِتُوا۟ فَلَمَّا قُضِىَ وَلَّوْا۟ إِلَىٰ قَوْمِهِم مُّنذِرِينَ', 'a8984b611e684400532053d3e09f035e6e1fb4f52d7bce3115506e9b5f05da0d', 'a8984b611e684400532053d3e09f035e6e1fb4f52d7bce3115506e9b5f05da0d', NULL, 'واذ صرفنا اليك نفرا من الجن يستمعون القرءان فلما حضروه قالوا انصتوا فلما قضي ولوا الي قومهم منذرين', 26, 51, 202, 1, 6, 506, false, NULL),
    (4540, 'tanzil-uthmani-v1.1', 46, 30, 'قَالُوا۟ يَٰقَوْمَنَآ إِنَّا سَمِعْنَا كِتَٰبًا أُنزِلَ مِنۢ بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِىٓ إِلَى ٱلْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ', 'e7be39e5de11bccb4afa34f1a4123f1b3a33cfe332d59096de586190827343f1', 'قَالُوا۟ يَٰقَوْمَنَآ إِنَّا سَمِعْنَا كِتَٰبًا أُنزِلَ مِنۢ بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِىٓ إِلَى ٱلْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ', 'e7be39e5de11bccb4afa34f1a4123f1b3a33cfe332d59096de586190827343f1', 'e7be39e5de11bccb4afa34f1a4123f1b3a33cfe332d59096de586190827343f1', NULL, 'قالوا يقومنا انا سمعنا كتبا انزل من بعد موسي مصدقا لما بين يديه يهدي الي الحق والي طريق مستقيم', 26, 51, 202, 1, 6, 506, false, NULL),
    (4541, 'tanzil-uthmani-v1.1', 46, 31, 'يَٰقَوْمَنَآ أَجِيبُوا۟ دَاعِىَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ', 'a318d839cd66295b7b3c3053a254b4ec66ec6e4f231b35b894b08b2104d06908', 'يَٰقَوْمَنَآ أَجِيبُوا۟ دَاعِىَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ', 'a318d839cd66295b7b3c3053a254b4ec66ec6e4f231b35b894b08b2104d06908', 'a318d839cd66295b7b3c3053a254b4ec66ec6e4f231b35b894b08b2104d06908', NULL, 'يقومنا اجيبوا داعي الله وءامنوا به يغفر لكم من ذنوبكم ويجركم من عذاب اليم', 26, 51, 202, 1, 6, 506, false, NULL),
    (4542, 'tanzil-uthmani-v1.1', 46, 32, 'وَمَن لَّا يُجِبْ دَاعِىَ ٱللَّهِ فَلَيْسَ بِمُعْجِزٍ فِى ٱلْأَرْضِ وَلَيْسَ لَهُۥ مِن دُونِهِۦٓ أَوْلِيَآءُ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ', '315a051e8d50ff35fd532267957cc569bb8eb3141d99aad3758418df57919634', 'وَمَن لَّا يُجِبْ دَاعِىَ ٱللَّهِ فَلَيْسَ بِمُعْجِزٍ فِى ٱلْأَرْضِ وَلَيْسَ لَهُۥ مِن دُونِهِۦٓ أَوْلِيَآءُ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ', '315a051e8d50ff35fd532267957cc569bb8eb3141d99aad3758418df57919634', '315a051e8d50ff35fd532267957cc569bb8eb3141d99aad3758418df57919634', NULL, 'ومن لا يجب داعي الله فليس بمعجز في الارض وليس له من دونه اولياء اولئك في ضلل مبين', 26, 51, 202, 1, 6, 506, false, NULL),
    (4543, 'tanzil-uthmani-v1.1', 46, 33, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَمْ يَعْىَ بِخَلْقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ بَلَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '465cebfa9ee2b55796cb7f5a433578b64fada84e440283b54a926ef8a530a3dd', 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَمْ يَعْىَ بِخَلْقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ بَلَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '465cebfa9ee2b55796cb7f5a433578b64fada84e440283b54a926ef8a530a3dd', '465cebfa9ee2b55796cb7f5a433578b64fada84e440283b54a926ef8a530a3dd', NULL, 'اولم يروا ان الله الذي خلق السموت والارض ولم يعي بخلقهن بقدر علي ان يحي الموتي بلي انه علي كل شيء قدير', 26, 51, 202, 1, 6, 506, false, NULL),
    (4544, 'tanzil-uthmani-v1.1', 46, 34, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَيْسَ هَٰذَا بِٱلْحَقِّ قَالُوا۟ بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '146b559cdd3cec26ba40da9e7d22337c5867f17b59a1f81602bcd65d36d11b9a', 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَيْسَ هَٰذَا بِٱلْحَقِّ قَالُوا۟ بَلَىٰ وَرَبِّنَا قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', '146b559cdd3cec26ba40da9e7d22337c5867f17b59a1f81602bcd65d36d11b9a', '146b559cdd3cec26ba40da9e7d22337c5867f17b59a1f81602bcd65d36d11b9a', NULL, 'ويوم يعرض الذين كفروا علي النار اليس هذا بالحق قالوا بلي وربنا قال فذوقوا العذاب بما كنتم تكفرون', 26, 51, 202, 1, 6, 506, false, NULL),
    (4545, 'tanzil-uthmani-v1.1', 46, 35, 'فَٱصْبِرْ كَمَا صَبَرَ أُو۟لُوا۟ ٱلْعَزْمِ مِنَ ٱلرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّن نَّهَارٍۭ بَلَٰغٌ فَهَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلْفَٰسِقُونَ', '13476c7eb018f6b3c57155b2cfcb46f210ccd678cf88f1075e3b119ab49720f5', 'فَٱصْبِرْ كَمَا صَبَرَ أُو۟لُوا۟ ٱلْعَزْمِ مِنَ ٱلرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةً مِّن نَّهَارٍۭ بَلَٰغٌ فَهَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلْفَٰسِقُونَ', '13476c7eb018f6b3c57155b2cfcb46f210ccd678cf88f1075e3b119ab49720f5', '13476c7eb018f6b3c57155b2cfcb46f210ccd678cf88f1075e3b119ab49720f5', NULL, 'فاصبر كما صبر اولوا العزم من الرسل ولا تستعجل لهم كانهم يوم يرون ما يوعدون لم يلبثوا الا ساعه من نهار بلغ فهل يهلك الا القوم الفسقون', 26, 51, 202, 1, 6, 506, false, NULL),
    (4546, 'tanzil-uthmani-v1.1', 47, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعْمَٰلَهُمْ', 'cd5e8d525e7acc5071004650aaea9d543723712fcc7e3a1c82e293e5c35423bd', 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعْمَٰلَهُمْ', '16192af14cb20b4b3f460973c2766a9bfcf594383b5a62a6414ee735af87ce57', '16192af14cb20b4b3f460973c2766a9bfcf594383b5a62a6414ee735af87ce57', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'الذين كفروا وصدوا عن سبيل الله اضل اعملهم', 26, 51, 202, 1, 6, 507, false, NULL),
    (4547, 'tanzil-uthmani-v1.1', 47, 2, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٍ وَهُوَ ٱلْحَقُّ مِن رَّبِّهِمْ كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَأَصْلَحَ بَالَهُمْ', 'a0f5b6e94b0485f5547bf23302c6b3c77265fb57c58f5292cf4084dd803cc6c6', 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٍ وَهُوَ ٱلْحَقُّ مِن رَّبِّهِمْ كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَأَصْلَحَ بَالَهُمْ', 'a0f5b6e94b0485f5547bf23302c6b3c77265fb57c58f5292cf4084dd803cc6c6', 'a0f5b6e94b0485f5547bf23302c6b3c77265fb57c58f5292cf4084dd803cc6c6', NULL, 'والذين ءامنوا وعملوا الصلحت وءامنوا بما نزل علي محمد وهو الحق من ربهم كفر عنهم سياتهم واصلح بالهم', 26, 51, 202, 1, 6, 507, false, NULL),
    (4548, 'tanzil-uthmani-v1.1', 47, 3, 'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلْبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلْحَقَّ مِن رَّبِّهِمْ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ لِلنَّاسِ أَمْثَٰلَهُمْ', '2dbf06f054162159d66bcfff928908d5d6fa7b3767eb2d3df4d92bc181826d20', 'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلْبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلْحَقَّ مِن رَّبِّهِمْ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ لِلنَّاسِ أَمْثَٰلَهُمْ', '2dbf06f054162159d66bcfff928908d5d6fa7b3767eb2d3df4d92bc181826d20', '2dbf06f054162159d66bcfff928908d5d6fa7b3767eb2d3df4d92bc181826d20', NULL, 'ذلك بان الذين كفروا اتبعوا البطل وان الذين ءامنوا اتبعوا الحق من ربهم كذلك يضرب الله للناس امثلهم', 26, 51, 202, 1, 6, 507, false, NULL),
    (4549, 'tanzil-uthmani-v1.1', 47, 4, 'فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ فَضَرْبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثْخَنتُمُوهُمْ فَشُدُّوا۟ ٱلْوَثَاقَ فَإِمَّا مَنًّۢا بَعْدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلْحَرْبُ أَوْزَارَهَا ذَٰلِكَ وَلَوْ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنْهُمْ وَلَٰكِن لِّيَبْلُوَا۟ بَعْضَكُم بِبَعْضٍ وَٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعْمَٰلَهُمْ', '1edb871cee4c516f946d287ef47ef3f92090ff8aa02f7a97e6121e7433174c5b', 'فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ فَضَرْبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثْخَنتُمُوهُمْ فَشُدُّوا۟ ٱلْوَثَاقَ فَإِمَّا مَنًّۢا بَعْدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلْحَرْبُ أَوْزَارَهَا ذَٰلِكَ وَلَوْ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنْهُمْ وَلَٰكِن لِّيَبْلُوَا۟ بَعْضَكُم بِبَعْضٍ وَٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعْمَٰلَهُمْ', '1edb871cee4c516f946d287ef47ef3f92090ff8aa02f7a97e6121e7433174c5b', '1edb871cee4c516f946d287ef47ef3f92090ff8aa02f7a97e6121e7433174c5b', NULL, 'فاذا لقيتم الذين كفروا فضرب الرقاب حتي اذا اثخنتموهم فشدوا الوثاق فاما منا بعد واما فداء حتي تضع الحرب اوزارها ذلك ولو يشاء الله لانتصر منهم ولكن ليبلوا بعضكم ببعض والذين قتلوا في سبيل الله فلن يضل اعملهم', 26, 51, 202, 1, 6, 507, false, NULL),
    (4550, 'tanzil-uthmani-v1.1', 47, 5, 'سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ', 'e5e561944351613e369e0a79c9dd7b53eb6bbef216b6dc1910c2b5e6b8f2fc94', 'سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ', 'e5e561944351613e369e0a79c9dd7b53eb6bbef216b6dc1910c2b5e6b8f2fc94', 'e5e561944351613e369e0a79c9dd7b53eb6bbef216b6dc1910c2b5e6b8f2fc94', NULL, 'سيهديهم ويصلح بالهم', 26, 51, 202, 1, 6, 507, false, NULL),
    (4551, 'tanzil-uthmani-v1.1', 47, 6, 'وَيُدْخِلُهُمُ ٱلْجَنَّةَ عَرَّفَهَا لَهُمْ', 'ebe99776efdde7a54362e58f73a0cfe9c6563f373593935c9b27865200508525', 'وَيُدْخِلُهُمُ ٱلْجَنَّةَ عَرَّفَهَا لَهُمْ', 'ebe99776efdde7a54362e58f73a0cfe9c6563f373593935c9b27865200508525', 'ebe99776efdde7a54362e58f73a0cfe9c6563f373593935c9b27865200508525', NULL, 'ويدخلهم الجنه عرفها لهم', 26, 51, 202, 1, 6, 507, false, NULL),
    (4552, 'tanzil-uthmani-v1.1', 47, 7, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ', '5fc7914a791fbb8a88dbe508a3a6f1bde2c8cd02947ff5788e12c92f1570a6e3', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ', '5fc7914a791fbb8a88dbe508a3a6f1bde2c8cd02947ff5788e12c92f1570a6e3', '5fc7914a791fbb8a88dbe508a3a6f1bde2c8cd02947ff5788e12c92f1570a6e3', NULL, 'يايها الذين ءامنوا ان تنصروا الله ينصركم ويثبت اقدامكم', 26, 51, 202, 1, 6, 507, false, NULL),
    (4553, 'tanzil-uthmani-v1.1', 47, 8, 'وَٱلَّذِينَ كَفَرُوا۟ فَتَعْسًا لَّهُمْ وَأَضَلَّ أَعْمَٰلَهُمْ', '805f44ebc985fc513f8b95b10cf5f348bad58f8a8220019b161472130eb07722', 'وَٱلَّذِينَ كَفَرُوا۟ فَتَعْسًا لَّهُمْ وَأَضَلَّ أَعْمَٰلَهُمْ', '805f44ebc985fc513f8b95b10cf5f348bad58f8a8220019b161472130eb07722', '805f44ebc985fc513f8b95b10cf5f348bad58f8a8220019b161472130eb07722', NULL, 'والذين كفروا فتعسا لهم واضل اعملهم', 26, 51, 202, 1, 6, 507, false, NULL),
    (4554, 'tanzil-uthmani-v1.1', 47, 9, 'ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا۟ مَآ أَنزَلَ ٱللَّهُ فَأَحْبَطَ أَعْمَٰلَهُمْ', 'cb82fb3afe951bb4e016f1c1bd1003af55c99807c9d07df7af65b19580ea472d', 'ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا۟ مَآ أَنزَلَ ٱللَّهُ فَأَحْبَطَ أَعْمَٰلَهُمْ', 'cb82fb3afe951bb4e016f1c1bd1003af55c99807c9d07df7af65b19580ea472d', 'cb82fb3afe951bb4e016f1c1bd1003af55c99807c9d07df7af65b19580ea472d', NULL, 'ذلك بانهم كرهوا ما انزل الله فاحبط اعملهم', 26, 51, 202, 1, 6, 507, false, NULL),
    (4555, 'tanzil-uthmani-v1.1', 47, 10, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ دَمَّرَ ٱللَّهُ عَلَيْهِمْ وَلِلْكَٰفِرِينَ أَمْثَٰلُهَا', 'bd4121d6115538b1158c4eaa5a8e75738f075864ad6487cb82326ce96a70d828', 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ دَمَّرَ ٱللَّهُ عَلَيْهِمْ وَلِلْكَٰفِرِينَ أَمْثَٰلُهَا', 'bd4121d6115538b1158c4eaa5a8e75738f075864ad6487cb82326ce96a70d828', 'bd4121d6115538b1158c4eaa5a8e75738f075864ad6487cb82326ce96a70d828', NULL, 'افلم يسيروا في الارض فينظروا كيف كان عقبه الذين من قبلهم دمر الله عليهم وللكفرين امثلها', 26, 51, 203, 1, 6, 507, false, NULL),
    (4556, 'tanzil-uthmani-v1.1', 47, 11, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوْلَى ٱلَّذِينَ ءَامَنُوا۟ وَأَنَّ ٱلْكَٰفِرِينَ لَا مَوْلَىٰ لَهُمْ', '9a63e2d2e68fe5b3802f1ec47f396418a22c5a910857b326a5e25e00eff5c691', 'ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوْلَى ٱلَّذِينَ ءَامَنُوا۟ وَأَنَّ ٱلْكَٰفِرِينَ لَا مَوْلَىٰ لَهُمْ', '9a63e2d2e68fe5b3802f1ec47f396418a22c5a910857b326a5e25e00eff5c691', '9a63e2d2e68fe5b3802f1ec47f396418a22c5a910857b326a5e25e00eff5c691', NULL, 'ذلك بان الله مولي الذين ءامنوا وان الكفرين لا مولي لهم', 26, 51, 203, 1, 6, 507, false, NULL),
    (4557, 'tanzil-uthmani-v1.1', 47, 12, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَٱلَّذِينَ كَفَرُوا۟ يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ ٱلْأَنْعَٰمُ وَٱلنَّارُ مَثْوًى لَّهُمْ', 'f5ba299035d21da7333f97556a74f45f731d38662afc4695a0c16e2b18f181dd', 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَٱلَّذِينَ كَفَرُوا۟ يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ ٱلْأَنْعَٰمُ وَٱلنَّارُ مَثْوًى لَّهُمْ', 'f5ba299035d21da7333f97556a74f45f731d38662afc4695a0c16e2b18f181dd', 'f5ba299035d21da7333f97556a74f45f731d38662afc4695a0c16e2b18f181dd', NULL, 'ان الله يدخل الذين ءامنوا وعملوا الصلحت جنت تجري من تحتها الانهر والذين كفروا يتمتعون وياكلون كما تاكل الانعم والنار مثوي لهم', 26, 51, 203, 1, 6, 508, false, NULL),
    (4558, 'tanzil-uthmani-v1.1', 47, 13, 'وَكَأَيِّن مِّن قَرْيَةٍ هِىَ أَشَدُّ قُوَّةً مِّن قَرْيَتِكَ ٱلَّتِىٓ أَخْرَجَتْكَ أَهْلَكْنَٰهُمْ فَلَا نَاصِرَ لَهُمْ', '847081041a9ae5cdc776c25ec3469454125ccf52e015d47863e7641c4b3842bf', 'وَكَأَيِّن مِّن قَرْيَةٍ هِىَ أَشَدُّ قُوَّةً مِّن قَرْيَتِكَ ٱلَّتِىٓ أَخْرَجَتْكَ أَهْلَكْنَٰهُمْ فَلَا نَاصِرَ لَهُمْ', '847081041a9ae5cdc776c25ec3469454125ccf52e015d47863e7641c4b3842bf', '847081041a9ae5cdc776c25ec3469454125ccf52e015d47863e7641c4b3842bf', NULL, 'وكاين من قريه هي اشد قوه من قريتك التي اخرجتك اهلكنهم فلا ناصر لهم', 26, 51, 203, 1, 6, 508, false, NULL),
    (4559, 'tanzil-uthmani-v1.1', 47, 14, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُم', '44c1bfb570c83ffaa34f92233abcf3a7e82520be452f1d062a318e1ba74faa3a', 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُم', '44c1bfb570c83ffaa34f92233abcf3a7e82520be452f1d062a318e1ba74faa3a', '44c1bfb570c83ffaa34f92233abcf3a7e82520be452f1d062a318e1ba74faa3a', NULL, 'افمن كان علي بينه من ربه كمن زين له سوء عمله واتبعوا اهواءهم', 26, 51, 203, 1, 6, 508, false, NULL),
    (4560, 'tanzil-uthmani-v1.1', 47, 15, 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ فِيهَآ أَنْهَٰرٌ مِّن مَّآءٍ غَيْرِ ءَاسِنٍ وَأَنْهَٰرٌ مِّن لَّبَنٍ لَّمْ يَتَغَيَّرْ طَعْمُهُۥ وَأَنْهَٰرٌ مِّنْ خَمْرٍ لَّذَّةٍ لِّلشَّٰرِبِينَ وَأَنْهَٰرٌ مِّنْ عَسَلٍ مُّصَفًّى وَلَهُمْ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغْفِرَةٌ مِّن رَّبِّهِمْ كَمَنْ هُوَ خَٰلِدٌ فِى ٱلنَّارِ وَسُقُوا۟ مَآءً حَمِيمًا فَقَطَّعَ أَمْعَآءَهُمْ', '2bcb23846c115991e480bc3a1266e850160611606a2546b242a6b2982c976900', 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ فِيهَآ أَنْهَٰرٌ مِّن مَّآءٍ غَيْرِ ءَاسِنٍ وَأَنْهَٰرٌ مِّن لَّبَنٍ لَّمْ يَتَغَيَّرْ طَعْمُهُۥ وَأَنْهَٰرٌ مِّنْ خَمْرٍ لَّذَّةٍ لِّلشَّٰرِبِينَ وَأَنْهَٰرٌ مِّنْ عَسَلٍ مُّصَفًّى وَلَهُمْ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغْفِرَةٌ مِّن رَّبِّهِمْ كَمَنْ هُوَ خَٰلِدٌ فِى ٱلنَّارِ وَسُقُوا۟ مَآءً حَمِيمًا فَقَطَّعَ أَمْعَآءَهُمْ', '2bcb23846c115991e480bc3a1266e850160611606a2546b242a6b2982c976900', '2bcb23846c115991e480bc3a1266e850160611606a2546b242a6b2982c976900', NULL, 'مثل الجنه التي وعد المتقون فيها انهر من ماء غير ءاسن وانهر من لبن لم يتغير طعمه وانهر من خمر لذه للشربين وانهر من عسل مصفي ولهم فيها من كل الثمرت ومغفره من ربهم كمن هو خلد في النار وسقوا ماء حميما فقطع امعاءهم', 26, 51, 203, 1, 6, 508, false, NULL),
    (4561, 'tanzil-uthmani-v1.1', 47, 16, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُوا۟ مِنْ عِندِكَ قَالُوا۟ لِلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مَاذَا قَالَ ءَانِفًا أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ', '3152a8e8329636c0254a3a27d47ffeddca070d1c69effc0040e9970239231cfe', 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُوا۟ مِنْ عِندِكَ قَالُوا۟ لِلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مَاذَا قَالَ ءَانِفًا أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ', '3152a8e8329636c0254a3a27d47ffeddca070d1c69effc0040e9970239231cfe', '3152a8e8329636c0254a3a27d47ffeddca070d1c69effc0040e9970239231cfe', NULL, 'ومنهم من يستمع اليك حتي اذا خرجوا من عندك قالوا للذين اوتوا العلم ماذا قال ءانفا اولئك الذين طبع الله علي قلوبهم واتبعوا اهواءهم', 26, 51, 203, 1, 6, 508, false, NULL),
    (4562, 'tanzil-uthmani-v1.1', 47, 17, 'وَٱلَّذِينَ ٱهْتَدَوْا۟ زَادَهُمْ هُدًى وَءَاتَىٰهُمْ تَقْوَىٰهُمْ', '90b1c935b2e36520e073c505a306a17fdcf79b3fe972e8af048d66eaa01a08ad', 'وَٱلَّذِينَ ٱهْتَدَوْا۟ زَادَهُمْ هُدًى وَءَاتَىٰهُمْ تَقْوَىٰهُمْ', '90b1c935b2e36520e073c505a306a17fdcf79b3fe972e8af048d66eaa01a08ad', '90b1c935b2e36520e073c505a306a17fdcf79b3fe972e8af048d66eaa01a08ad', NULL, 'والذين اهتدوا زادهم هدي وءاتيهم تقويهم', 26, 51, 203, 1, 6, 508, false, NULL),
    (4563, 'tanzil-uthmani-v1.1', 47, 18, 'فَهَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً فَقَدْ جَآءَ أَشْرَاطُهَا فَأَنَّىٰ لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَىٰهُمْ', '05b945dfb9bff4b4294b6b6f8dbf882f57cbd4a374167247eb54444443c0676a', 'فَهَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً فَقَدْ جَآءَ أَشْرَاطُهَا فَأَنَّىٰ لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَىٰهُمْ', '05b945dfb9bff4b4294b6b6f8dbf882f57cbd4a374167247eb54444443c0676a', '05b945dfb9bff4b4294b6b6f8dbf882f57cbd4a374167247eb54444443c0676a', NULL, 'فهل ينظرون الا الساعه ان تاتيهم بغته فقد جاء اشراطها فاني لهم اذا جاءتهم ذكريهم', 26, 51, 203, 1, 6, 508, false, NULL),
    (4564, 'tanzil-uthmani-v1.1', 47, 19, 'فَٱعْلَمْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ', '953330c39dd341207e0e66d40187a91a6ccf0092a6afd46594d8f9c79d176e87', 'فَٱعْلَمْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ', '953330c39dd341207e0e66d40187a91a6ccf0092a6afd46594d8f9c79d176e87', '953330c39dd341207e0e66d40187a91a6ccf0092a6afd46594d8f9c79d176e87', NULL, 'فاعلم انه لا اله الا الله واستغفر لذنبك وللمؤمنين والمؤمنت والله يعلم متقلبكم ومثويكم', 26, 51, 203, 1, 6, 508, false, NULL),
    (4565, 'tanzil-uthmani-v1.1', 47, 20, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوا۟ لَوْلَا نُزِّلَتْ سُورَةٌ فَإِذَآ أُنزِلَتْ سُورَةٌ مُّحْكَمَةٌ وَذُكِرَ فِيهَا ٱلْقِتَالُ رَأَيْتَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يَنظُرُونَ إِلَيْكَ نَظَرَ ٱلْمَغْشِىِّ عَلَيْهِ مِنَ ٱلْمَوْتِ فَأَوْلَىٰ لَهُمْ', '5b1c5310b3f23d3fd2e54e93255c147276a62bfcf55af4120dfe54ba6b569c9d', 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوا۟ لَوْلَا نُزِّلَتْ سُورَةٌ فَإِذَآ أُنزِلَتْ سُورَةٌ مُّحْكَمَةٌ وَذُكِرَ فِيهَا ٱلْقِتَالُ رَأَيْتَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يَنظُرُونَ إِلَيْكَ نَظَرَ ٱلْمَغْشِىِّ عَلَيْهِ مِنَ ٱلْمَوْتِ فَأَوْلَىٰ لَهُمْ', '5b1c5310b3f23d3fd2e54e93255c147276a62bfcf55af4120dfe54ba6b569c9d', '5b1c5310b3f23d3fd2e54e93255c147276a62bfcf55af4120dfe54ba6b569c9d', NULL, 'ويقول الذين ءامنوا لولا نزلت سوره فاذا انزلت سوره محكمه وذكر فيها القتال رايت الذين في قلوبهم مرض ينظرون اليك نظر المغشي عليه من الموت فاولي لهم', 26, 51, 203, 1, 6, 509, false, NULL),
    (4566, 'tanzil-uthmani-v1.1', 47, 21, 'طَاعَةٌ وَقَوْلٌ مَّعْرُوفٌ فَإِذَا عَزَمَ ٱلْأَمْرُ فَلَوْ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَيْرًا لَّهُمْ', '875300790af44584396f1ca420f7cd013897d618c2c6814dc7ba2518d26b6ce2', 'طَاعَةٌ وَقَوْلٌ مَّعْرُوفٌ فَإِذَا عَزَمَ ٱلْأَمْرُ فَلَوْ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَيْرًا لَّهُمْ', '875300790af44584396f1ca420f7cd013897d618c2c6814dc7ba2518d26b6ce2', '875300790af44584396f1ca420f7cd013897d618c2c6814dc7ba2518d26b6ce2', NULL, 'طاعه وقول معروف فاذا عزم الامر فلو صدقوا الله لكان خيرا لهم', 26, 51, 203, 1, 6, 509, false, NULL),
    (4567, 'tanzil-uthmani-v1.1', 47, 22, 'فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا۟ فِى ٱلْأَرْضِ وَتُقَطِّعُوٓا۟ أَرْحَامَكُمْ', '945fbc06d69b45501424eac4a049dbd7ab05ad42b4ca366b996c48c1d9113be0', 'فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا۟ فِى ٱلْأَرْضِ وَتُقَطِّعُوٓا۟ أَرْحَامَكُمْ', '945fbc06d69b45501424eac4a049dbd7ab05ad42b4ca366b996c48c1d9113be0', '945fbc06d69b45501424eac4a049dbd7ab05ad42b4ca366b996c48c1d9113be0', NULL, 'فهل عسيتم ان توليتم ان تفسدوا في الارض وتقطعوا ارحامكم', 26, 51, 203, 1, 6, 509, false, NULL),
    (4568, 'tanzil-uthmani-v1.1', 47, 23, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰٓ أَبْصَٰرَهُمْ', 'a19668088ba9f1c6163a4e7f1885e92c4f5123e90ca726fbd168ea5a5e8adf4c', 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰٓ أَبْصَٰرَهُمْ', 'a19668088ba9f1c6163a4e7f1885e92c4f5123e90ca726fbd168ea5a5e8adf4c', 'a19668088ba9f1c6163a4e7f1885e92c4f5123e90ca726fbd168ea5a5e8adf4c', NULL, 'اولئك الذين لعنهم الله فاصمهم واعمي ابصرهم', 26, 51, 203, 1, 6, 509, false, NULL),
    (4569, 'tanzil-uthmani-v1.1', 47, 24, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَآ', '0d81fbb33547427bbedfbfab76efbbaf5af53f3b5f796bd921b7e38268181691', 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَآ', '0d81fbb33547427bbedfbfab76efbbaf5af53f3b5f796bd921b7e38268181691', '0d81fbb33547427bbedfbfab76efbbaf5af53f3b5f796bd921b7e38268181691', NULL, 'افلا يتدبرون القرءان ام علي قلوب اقفالها', 26, 51, 203, 1, 6, 509, false, NULL),
    (4570, 'tanzil-uthmani-v1.1', 47, 25, 'إِنَّ ٱلَّذِينَ ٱرْتَدُّوا۟ عَلَىٰٓ أَدْبَٰرِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَى ٱلشَّيْطَٰنُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ', '3a2daef1633f1b4de135d1ae43a9ba0602b42fa127fc55168f0342b45d60e401', 'إِنَّ ٱلَّذِينَ ٱرْتَدُّوا۟ عَلَىٰٓ أَدْبَٰرِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَى ٱلشَّيْطَٰنُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ', '3a2daef1633f1b4de135d1ae43a9ba0602b42fa127fc55168f0342b45d60e401', '3a2daef1633f1b4de135d1ae43a9ba0602b42fa127fc55168f0342b45d60e401', NULL, 'ان الذين ارتدوا علي ادبرهم من بعد ما تبين لهم الهدي الشيطن سول لهم واملي لهم', 26, 51, 203, 1, 6, 509, false, NULL),
    (4571, 'tanzil-uthmani-v1.1', 47, 26, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لِلَّذِينَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ ٱلْأَمْرِ وَٱللَّهُ يَعْلَمُ إِسْرَارَهُمْ', '6752b893693f99d0ebb1541913ea85cb09826a91e8c18fe34095c44d171a9885', 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لِلَّذِينَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ ٱلْأَمْرِ وَٱللَّهُ يَعْلَمُ إِسْرَارَهُمْ', '6752b893693f99d0ebb1541913ea85cb09826a91e8c18fe34095c44d171a9885', '6752b893693f99d0ebb1541913ea85cb09826a91e8c18fe34095c44d171a9885', NULL, 'ذلك بانهم قالوا للذين كرهوا ما نزل الله سنطيعكم في بعض الامر والله يعلم اسرارهم', 26, 51, 203, 1, 6, 509, false, NULL),
    (4572, 'tanzil-uthmani-v1.1', 47, 27, 'فَكَيْفَ إِذَا تَوَفَّتْهُمُ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ', '5307287d984cb104a6f526f02bac3cb3d0809d7d0d3c07c763244723fb0d9b71', 'فَكَيْفَ إِذَا تَوَفَّتْهُمُ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ', '5307287d984cb104a6f526f02bac3cb3d0809d7d0d3c07c763244723fb0d9b71', '5307287d984cb104a6f526f02bac3cb3d0809d7d0d3c07c763244723fb0d9b71', NULL, 'فكيف اذا توفتهم الملئكه يضربون وجوههم وادبرهم', 26, 51, 203, 1, 6, 509, false, NULL),
    (4573, 'tanzil-uthmani-v1.1', 47, 28, 'ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَآ أَسْخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضْوَٰنَهُۥ فَأَحْبَطَ أَعْمَٰلَهُمْ', 'f8cc1fa064c7622054b5fdcb5ab4b8a72b6d48e0af99ea9a00f0a38c8ee78987', 'ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَآ أَسْخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضْوَٰنَهُۥ فَأَحْبَطَ أَعْمَٰلَهُمْ', 'f8cc1fa064c7622054b5fdcb5ab4b8a72b6d48e0af99ea9a00f0a38c8ee78987', 'f8cc1fa064c7622054b5fdcb5ab4b8a72b6d48e0af99ea9a00f0a38c8ee78987', NULL, 'ذلك بانهم اتبعوا ما اسخط الله وكرهوا رضونه فاحبط اعملهم', 26, 51, 203, 1, 6, 509, false, NULL),
    (4574, 'tanzil-uthmani-v1.1', 47, 29, 'أَمْ حَسِبَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ ٱللَّهُ أَضْغَٰنَهُمْ', '73ec3e4349149bf712a3e277763b5c2b88ce144d92a3c89ebd070af333774ee5', 'أَمْ حَسِبَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ ٱللَّهُ أَضْغَٰنَهُمْ', '73ec3e4349149bf712a3e277763b5c2b88ce144d92a3c89ebd070af333774ee5', '73ec3e4349149bf712a3e277763b5c2b88ce144d92a3c89ebd070af333774ee5', NULL, 'ام حسب الذين في قلوبهم مرض ان لن يخرج الله اضغنهم', 26, 51, 203, 1, 6, 509, false, NULL),
    (4575, 'tanzil-uthmani-v1.1', 47, 30, 'وَلَوْ نَشَآءُ لَأَرَيْنَٰكَهُمْ فَلَعَرَفْتَهُم بِسِيمَٰهُمْ وَلَتَعْرِفَنَّهُمْ فِى لَحْنِ ٱلْقَوْلِ وَٱللَّهُ يَعْلَمُ أَعْمَٰلَكُمْ', '1d3ce0509850fbb501a8b850b9d317a5685665b13de5412d86b5175a35989045', 'وَلَوْ نَشَآءُ لَأَرَيْنَٰكَهُمْ فَلَعَرَفْتَهُم بِسِيمَٰهُمْ وَلَتَعْرِفَنَّهُمْ فِى لَحْنِ ٱلْقَوْلِ وَٱللَّهُ يَعْلَمُ أَعْمَٰلَكُمْ', '1d3ce0509850fbb501a8b850b9d317a5685665b13de5412d86b5175a35989045', '1d3ce0509850fbb501a8b850b9d317a5685665b13de5412d86b5175a35989045', NULL, 'ولو نشاء لارينكهم فلعرفتهم بسيمهم ولتعرفنهم في لحن القول والله يعلم اعملكم', 26, 51, 203, 1, 6, 510, false, NULL),
    (4576, 'tanzil-uthmani-v1.1', 47, 31, 'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَٰهِدِينَ مِنكُمْ وَٱلصَّٰبِرِينَ وَنَبْلُوَا۟ أَخْبَارَكُمْ', 'f4898f6622c64aead62f1393e192afd2643ce82fcf59e5b6ea6340902f10e11e', 'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَٰهِدِينَ مِنكُمْ وَٱلصَّٰبِرِينَ وَنَبْلُوَا۟ أَخْبَارَكُمْ', 'f4898f6622c64aead62f1393e192afd2643ce82fcf59e5b6ea6340902f10e11e', 'f4898f6622c64aead62f1393e192afd2643ce82fcf59e5b6ea6340902f10e11e', NULL, 'ولنبلونكم حتي نعلم المجهدين منكم والصبرين ونبلوا اخباركم', 26, 51, 203, 1, 6, 510, false, NULL),
    (4577, 'tanzil-uthmani-v1.1', 47, 32, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ وَشَآقُّوا۟ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَىٰ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَسَيُحْبِطُ أَعْمَٰلَهُمْ', '8dc5ee14988b722bf7e6eb0423d81fe7649835da86564a972df9ef36ede8ce57', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ وَشَآقُّوا۟ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَىٰ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًٔا وَسَيُحْبِطُ أَعْمَٰلَهُمْ', '8dc5ee14988b722bf7e6eb0423d81fe7649835da86564a972df9ef36ede8ce57', '8dc5ee14988b722bf7e6eb0423d81fe7649835da86564a972df9ef36ede8ce57', NULL, 'ان الذين كفروا وصدوا عن سبيل الله وشاقوا الرسول من بعد ما تبين لهم الهدي لن يضروا الله شيا وسيحبط اعملهم', 26, 51, 203, 1, 6, 510, false, NULL),
    (4578, 'tanzil-uthmani-v1.1', 47, 33, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَلَا تُبْطِلُوٓا۟ أَعْمَٰلَكُمْ', '3173acb038a5d908657c1692b33ecdc9bd4628db273547143703f5f705c013ca', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَلَا تُبْطِلُوٓا۟ أَعْمَٰلَكُمْ', '3173acb038a5d908657c1692b33ecdc9bd4628db273547143703f5f705c013ca', '3173acb038a5d908657c1692b33ecdc9bd4628db273547143703f5f705c013ca', NULL, 'يايها الذين ءامنوا اطيعوا الله واطيعوا الرسول ولا تبطلوا اعملكم', 26, 51, 204, 1, 6, 510, false, NULL),
    (4579, 'tanzil-uthmani-v1.1', 47, 34, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ', '043ba7b088cae36fd96d085eb7e10aec7fb92feb27e88ab565925bf303e305ea', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمْ كُفَّارٌ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ', '043ba7b088cae36fd96d085eb7e10aec7fb92feb27e88ab565925bf303e305ea', '043ba7b088cae36fd96d085eb7e10aec7fb92feb27e88ab565925bf303e305ea', NULL, 'ان الذين كفروا وصدوا عن سبيل الله ثم ماتوا وهم كفار فلن يغفر الله لهم', 26, 51, 204, 1, 6, 510, false, NULL),
    (4580, 'tanzil-uthmani-v1.1', 47, 35, 'فَلَا تَهِنُوا۟ وَتَدْعُوٓا۟ إِلَى ٱلسَّلْمِ وَأَنتُمُ ٱلْأَعْلَوْنَ وَٱللَّهُ مَعَكُمْ وَلَن يَتِرَكُمْ أَعْمَٰلَكُمْ', 'd7610d2763c3ae74ae160b07a7737b98fb77a7cb050ea8f4efe901dda73ec239', 'فَلَا تَهِنُوا۟ وَتَدْعُوٓا۟ إِلَى ٱلسَّلْمِ وَأَنتُمُ ٱلْأَعْلَوْنَ وَٱللَّهُ مَعَكُمْ وَلَن يَتِرَكُمْ أَعْمَٰلَكُمْ', 'd7610d2763c3ae74ae160b07a7737b98fb77a7cb050ea8f4efe901dda73ec239', 'd7610d2763c3ae74ae160b07a7737b98fb77a7cb050ea8f4efe901dda73ec239', NULL, 'فلا تهنوا وتدعوا الي السلم وانتم الاعلون والله معكم ولن يتركم اعملكم', 26, 51, 204, 1, 6, 510, false, NULL),
    (4581, 'tanzil-uthmani-v1.1', 47, 36, 'إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ', '8badaf080c20f41849503b744dc7bb5aec644227ec8c92cfb4627e59742eb1d7', 'إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ', '8badaf080c20f41849503b744dc7bb5aec644227ec8c92cfb4627e59742eb1d7', '8badaf080c20f41849503b744dc7bb5aec644227ec8c92cfb4627e59742eb1d7', NULL, 'انما الحيوه الدنيا لعب ولهو وان تؤمنوا وتتقوا يؤتكم اجوركم ولا يسلكم امولكم', 26, 51, 204, 1, 6, 510, false, NULL),
    (4582, 'tanzil-uthmani-v1.1', 47, 37, 'إِن يَسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا۟ وَيُخْرِجْ أَضْغَٰنَكُمْ', '3dbc9bb824b4d88758c7c71f561f18ae0899cf3298945381498592eeac9aff29', 'إِن يَسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا۟ وَيُخْرِجْ أَضْغَٰنَكُمْ', '3dbc9bb824b4d88758c7c71f561f18ae0899cf3298945381498592eeac9aff29', '3dbc9bb824b4d88758c7c71f561f18ae0899cf3298945381498592eeac9aff29', NULL, 'ان يسلكموها فيحفكم تبخلوا ويخرج اضغنكم', 26, 51, 204, 1, 6, 510, false, NULL),
    (4583, 'tanzil-uthmani-v1.1', 47, 38, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ تُدْعَوْنَ لِتُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبْخَلُ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِۦ وَٱللَّهُ ٱلْغَنِىُّ وَأَنتُمُ ٱلْفُقَرَآءُ وَإِن تَتَوَلَّوْا۟ يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوٓا۟ أَمْثَٰلَكُم', '8162b481f620d3ba44ad9934c53df32f8278ecc5fb2673d23e7eb7242ee3d7bc', 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ تُدْعَوْنَ لِتُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبْخَلُ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِۦ وَٱللَّهُ ٱلْغَنِىُّ وَأَنتُمُ ٱلْفُقَرَآءُ وَإِن تَتَوَلَّوْا۟ يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوٓا۟ أَمْثَٰلَكُم', '8162b481f620d3ba44ad9934c53df32f8278ecc5fb2673d23e7eb7242ee3d7bc', '8162b481f620d3ba44ad9934c53df32f8278ecc5fb2673d23e7eb7242ee3d7bc', NULL, 'هانتم هؤلاء تدعون لتنفقوا في سبيل الله فمنكم من يبخل ومن يبخل فانما يبخل عن نفسه والله الغني وانتم الفقراء وان تتولوا يستبدل قوما غيركم ثم لا يكونوا امثلكم', 26, 51, 204, 1, 6, 510, false, NULL),
    (4584, 'tanzil-uthmani-v1.1', 48, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا', 'ef0f885bf9198d89713a0476e080d78fb8cf440154a7e3cb08ece28d5ff2dda4', 'إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا', '723bb49a70eac15d357a7ac5780f74cb01e75badcb3f56a323ebed5ec3641fcc', '723bb49a70eac15d357a7ac5780f74cb01e75badcb3f56a323ebed5ec3641fcc', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'انا فتحنا لك فتحا مبينا', 26, 51, 204, 1, 6, 511, false, NULL),
    (4585, 'tanzil-uthmani-v1.1', 48, 2, 'لِّيَغْفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُۥ عَلَيْكَ وَيَهْدِيَكَ صِرَٰطًا مُّسْتَقِيمًا', '1783840d4c2b765754c17073bd959cf1b869bcb33b4797cc18296251c1bd9533', 'لِّيَغْفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُۥ عَلَيْكَ وَيَهْدِيَكَ صِرَٰطًا مُّسْتَقِيمًا', '1783840d4c2b765754c17073bd959cf1b869bcb33b4797cc18296251c1bd9533', '1783840d4c2b765754c17073bd959cf1b869bcb33b4797cc18296251c1bd9533', NULL, 'ليغفر لك الله ما تقدم من ذنبك وما تاخر ويتم نعمته عليك ويهديك صرطا مستقيما', 26, 51, 204, 1, 6, 511, false, NULL),
    (4586, 'tanzil-uthmani-v1.1', 48, 3, 'وَيَنصُرَكَ ٱللَّهُ نَصْرًا عَزِيزًا', '9e77616709f3ea4c55d6586f90bc6ffca8e0e41912be449b5661ac201763c955', 'وَيَنصُرَكَ ٱللَّهُ نَصْرًا عَزِيزًا', '9e77616709f3ea4c55d6586f90bc6ffca8e0e41912be449b5661ac201763c955', '9e77616709f3ea4c55d6586f90bc6ffca8e0e41912be449b5661ac201763c955', NULL, 'وينصرك الله نصرا عزيزا', 26, 51, 204, 1, 6, 511, false, NULL),
    (4587, 'tanzil-uthmani-v1.1', 48, 4, 'هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ لِيَزْدَادُوٓا۟ إِيمَٰنًا مَّعَ إِيمَٰنِهِمْ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '8f674f780f8678d1acf1d2421c3174a5266dcb556c212d3adfe72a6a173dddb3', 'هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ لِيَزْدَادُوٓا۟ إِيمَٰنًا مَّعَ إِيمَٰنِهِمْ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', '8f674f780f8678d1acf1d2421c3174a5266dcb556c212d3adfe72a6a173dddb3', '8f674f780f8678d1acf1d2421c3174a5266dcb556c212d3adfe72a6a173dddb3', NULL, 'هو الذي انزل السكينه في قلوب المؤمنين ليزدادوا ايمنا مع ايمنهم ولله جنود السموت والارض وكان الله عليما حكيما', 26, 51, 204, 1, 6, 511, false, NULL),
    (4588, 'tanzil-uthmani-v1.1', 48, 5, 'لِّيُدْخِلَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوْزًا عَظِيمًا', 'd293889a349c5516c4c123eb6a0dce97890ea18d989bd9af1a5b50b2ce8bf60c', 'لِّيُدْخِلَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوْزًا عَظِيمًا', 'd293889a349c5516c4c123eb6a0dce97890ea18d989bd9af1a5b50b2ce8bf60c', 'd293889a349c5516c4c123eb6a0dce97890ea18d989bd9af1a5b50b2ce8bf60c', NULL, 'ليدخل المؤمنين والمؤمنت جنت تجري من تحتها الانهر خلدين فيها ويكفر عنهم سياتهم وكان ذلك عند الله فوزا عظيما', 26, 51, 204, 1, 6, 511, false, NULL),
    (4589, 'tanzil-uthmani-v1.1', 48, 6, 'وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوْءِ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ وَغَضِبَ ٱللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ وَسَآءَتْ مَصِيرًا', '1d71d1fd32f50864bf191cb2509a284488876c9a648b8ee0fb60300094ef9501', 'وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوْءِ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ وَغَضِبَ ٱللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ وَسَآءَتْ مَصِيرًا', '1d71d1fd32f50864bf191cb2509a284488876c9a648b8ee0fb60300094ef9501', '1d71d1fd32f50864bf191cb2509a284488876c9a648b8ee0fb60300094ef9501', NULL, 'ويعذب المنفقين والمنفقت والمشركين والمشركت الظانين بالله ظن السوء عليهم دائره السوء وغضب الله عليهم ولعنهم واعد لهم جهنم وساءت مصيرا', 26, 51, 204, 1, 6, 511, false, NULL),
    (4590, 'tanzil-uthmani-v1.1', 48, 7, 'وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', '2fdfb18903234357ce2af7e9c4c111e463e92fb39bd4f9d256b32a71ce3f0b94', 'وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', '2fdfb18903234357ce2af7e9c4c111e463e92fb39bd4f9d256b32a71ce3f0b94', '2fdfb18903234357ce2af7e9c4c111e463e92fb39bd4f9d256b32a71ce3f0b94', NULL, 'ولله جنود السموت والارض وكان الله عزيزا حكيما', 26, 51, 204, 1, 6, 511, false, NULL),
    (4591, 'tanzil-uthmani-v1.1', 48, 8, 'إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', 'ba8029229a8a8f096b1460ecfc1b98430e87d5d27d50cc99aad22829435d0784', 'إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًا وَمُبَشِّرًا وَنَذِيرًا', 'ba8029229a8a8f096b1460ecfc1b98430e87d5d27d50cc99aad22829435d0784', 'ba8029229a8a8f096b1460ecfc1b98430e87d5d27d50cc99aad22829435d0784', NULL, 'انا ارسلنك شهدا ومبشرا ونذيرا', 26, 51, 204, 1, 6, 511, false, NULL),
    (4592, 'tanzil-uthmani-v1.1', 48, 9, 'لِّتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', '83289fdc8429590918213f2ad39848ec13f8b80382839826d3c0198b2cec39c2', 'لِّتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَةً وَأَصِيلًا', '83289fdc8429590918213f2ad39848ec13f8b80382839826d3c0198b2cec39c2', '83289fdc8429590918213f2ad39848ec13f8b80382839826d3c0198b2cec39c2', NULL, 'لتؤمنوا بالله ورسوله وتعزروه وتوقروه وتسبحوه بكره واصيلا', 26, 51, 204, 1, 6, 511, false, NULL),
    (4593, 'tanzil-uthmani-v1.1', 48, 10, 'إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوْقَ أَيْدِيهِمْ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِۦ وَمَنْ أَوْفَىٰ بِمَا عَٰهَدَ عَلَيْهُ ٱللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًا', '5a45ca2d46b8e8301116933aac53ef78a7de647001e38816e06fbf41876cb4c7', 'إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوْقَ أَيْدِيهِمْ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِۦ وَمَنْ أَوْفَىٰ بِمَا عَٰهَدَ عَلَيْهُ ٱللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًا', '5a45ca2d46b8e8301116933aac53ef78a7de647001e38816e06fbf41876cb4c7', '5a45ca2d46b8e8301116933aac53ef78a7de647001e38816e06fbf41876cb4c7', NULL, 'ان الذين يبايعونك انما يبايعون الله يد الله فوق ايديهم فمن نكث فانما ينكث علي نفسه ومن اوفي بما عهد عليه الله فسيؤتيه اجرا عظيما', 26, 51, 204, 1, 6, 512, false, NULL),
    (4594, 'tanzil-uthmani-v1.1', 48, 11, 'سَيَقُولُ لَكَ ٱلْمُخَلَّفُونَ مِنَ ٱلْأَعْرَابِ شَغَلَتْنَآ أَمْوَٰلُنَا وَأَهْلُونَا فَٱسْتَغْفِرْ لَنَا يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًۢا بَلْ كَانَ ٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرًۢا', 'c193e2cda8478312494903dd0a0cb9ad599f1ef2204e810d1d05edca914b7613', 'سَيَقُولُ لَكَ ٱلْمُخَلَّفُونَ مِنَ ٱلْأَعْرَابِ شَغَلَتْنَآ أَمْوَٰلُنَا وَأَهْلُونَا فَٱسْتَغْفِرْ لَنَا يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًۢا بَلْ كَانَ ٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرًۢا', 'c193e2cda8478312494903dd0a0cb9ad599f1ef2204e810d1d05edca914b7613', 'c193e2cda8478312494903dd0a0cb9ad599f1ef2204e810d1d05edca914b7613', NULL, 'سيقول لك المخلفون من الاعراب شغلتنا امولنا واهلونا فاستغفر لنا يقولون بالسنتهم ما ليس في قلوبهم قل فمن يملك لكم من الله شيا ان اراد بكم ضرا او اراد بكم نفعا بل كان الله بما تعملون خبيرا', 26, 51, 204, 1, 6, 512, false, NULL),
    (4595, 'tanzil-uthmani-v1.1', 48, 12, 'بَلْ ظَنَنتُمْ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلْمُؤْمِنُونَ إِلَىٰٓ أَهْلِيهِمْ أَبَدًا وَزُيِّنَ ذَٰلِكَ فِى قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ ٱلسَّوْءِ وَكُنتُمْ قَوْمًۢا بُورًا', 'a99633b1386b81d3cc5275e0a8cc7ad9c29edfb0a5822006796db75b0983b79c', 'بَلْ ظَنَنتُمْ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلْمُؤْمِنُونَ إِلَىٰٓ أَهْلِيهِمْ أَبَدًا وَزُيِّنَ ذَٰلِكَ فِى قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ ٱلسَّوْءِ وَكُنتُمْ قَوْمًۢا بُورًا', 'a99633b1386b81d3cc5275e0a8cc7ad9c29edfb0a5822006796db75b0983b79c', 'a99633b1386b81d3cc5275e0a8cc7ad9c29edfb0a5822006796db75b0983b79c', NULL, 'بل ظننتم ان لن ينقلب الرسول والمؤمنون الي اهليهم ابدا وزين ذلك في قلوبكم وظننتم ظن السوء وكنتم قوما بورا', 26, 51, 204, 1, 6, 512, false, NULL),
    (4596, 'tanzil-uthmani-v1.1', 48, 13, 'وَمَن لَّمْ يُؤْمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَعِيرًا', '3e808190bc9c16c2573faa19cc30e43c40356613a8bc3987f78cb6ab82edb882', 'وَمَن لَّمْ يُؤْمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَعِيرًا', '3e808190bc9c16c2573faa19cc30e43c40356613a8bc3987f78cb6ab82edb882', '3e808190bc9c16c2573faa19cc30e43c40356613a8bc3987f78cb6ab82edb882', NULL, 'ومن لم يؤمن بالله ورسوله فانا اعتدنا للكفرين سعيرا', 26, 51, 204, 1, 6, 512, false, NULL),
    (4597, 'tanzil-uthmani-v1.1', 48, 14, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '9e7a91315baaf9510b05423475edc4ecce76550b65bcdeb02a74b44f1a92bc82', 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا', '9e7a91315baaf9510b05423475edc4ecce76550b65bcdeb02a74b44f1a92bc82', '9e7a91315baaf9510b05423475edc4ecce76550b65bcdeb02a74b44f1a92bc82', NULL, 'ولله ملك السموت والارض يغفر لمن يشاء ويعذب من يشاء وكان الله غفورا رحيما', 26, 51, 204, 1, 6, 512, false, NULL),
    (4598, 'tanzil-uthmani-v1.1', 48, 15, 'سَيَقُولُ ٱلْمُخَلَّفُونَ إِذَا ٱنطَلَقْتُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ يُرِيدُونَ أَن يُبَدِّلُوا۟ كَلَٰمَ ٱللَّهِ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمْ قَالَ ٱللَّهُ مِن قَبْلُ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا بَلْ كَانُوا۟ لَا يَفْقَهُونَ إِلَّا قَلِيلًا', '8eeb4dbef7e26e246051d7588aa50eff040bc6f76f2046942d1f1a95d8eee54f', 'سَيَقُولُ ٱلْمُخَلَّفُونَ إِذَا ٱنطَلَقْتُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ يُرِيدُونَ أَن يُبَدِّلُوا۟ كَلَٰمَ ٱللَّهِ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمْ قَالَ ٱللَّهُ مِن قَبْلُ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا بَلْ كَانُوا۟ لَا يَفْقَهُونَ إِلَّا قَلِيلًا', '8eeb4dbef7e26e246051d7588aa50eff040bc6f76f2046942d1f1a95d8eee54f', '8eeb4dbef7e26e246051d7588aa50eff040bc6f76f2046942d1f1a95d8eee54f', NULL, 'سيقول المخلفون اذا انطلقتم الي مغانم لتاخذوها ذرونا نتبعكم يريدون ان يبدلوا كلم الله قل لن تتبعونا كذلكم قال الله من قبل فسيقولون بل تحسدوننا بل كانوا لا يفقهون الا قليلا', 26, 51, 204, 1, 6, 512, false, NULL),
    (4599, 'tanzil-uthmani-v1.1', 48, 16, 'قُل لِّلْمُخَلَّفِينَ مِنَ ٱلْأَعْرَابِ سَتُدْعَوْنَ إِلَىٰ قَوْمٍ أُو۟لِى بَأْسٍ شَدِيدٍ تُقَٰتِلُونَهُمْ أَوْ يُسْلِمُونَ فَإِن تُطِيعُوا۟ يُؤْتِكُمُ ٱللَّهُ أَجْرًا حَسَنًا وَإِن تَتَوَلَّوْا۟ كَمَا تَوَلَّيْتُم مِّن قَبْلُ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا', '7256fc3cd8c58b2ca9d15ba037a939c768f153bcd38071c377780d7debf70cf0', 'قُل لِّلْمُخَلَّفِينَ مِنَ ٱلْأَعْرَابِ سَتُدْعَوْنَ إِلَىٰ قَوْمٍ أُو۟لِى بَأْسٍ شَدِيدٍ تُقَٰتِلُونَهُمْ أَوْ يُسْلِمُونَ فَإِن تُطِيعُوا۟ يُؤْتِكُمُ ٱللَّهُ أَجْرًا حَسَنًا وَإِن تَتَوَلَّوْا۟ كَمَا تَوَلَّيْتُم مِّن قَبْلُ يُعَذِّبْكُمْ عَذَابًا أَلِيمًا', '7256fc3cd8c58b2ca9d15ba037a939c768f153bcd38071c377780d7debf70cf0', '7256fc3cd8c58b2ca9d15ba037a939c768f153bcd38071c377780d7debf70cf0', NULL, 'قل للمخلفين من الاعراب ستدعون الي قوم اولي باس شديد تقتلونهم او يسلمون فان تطيعوا يؤتكم الله اجرا حسنا وان تتولوا كما توليتم من قبل يعذبكم عذابا اليما', 26, 51, 204, 1, 6, 513, false, NULL),
    (4600, 'tanzil-uthmani-v1.1', 48, 17, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَمَن يَتَوَلَّ يُعَذِّبْهُ عَذَابًا أَلِيمًا', 'd8ef362f6ea7da2959dd102b175db52441ba526405467b2e38498626c638e910', 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَمَن يَتَوَلَّ يُعَذِّبْهُ عَذَابًا أَلِيمًا', 'd8ef362f6ea7da2959dd102b175db52441ba526405467b2e38498626c638e910', 'd8ef362f6ea7da2959dd102b175db52441ba526405467b2e38498626c638e910', NULL, 'ليس علي الاعمي حرج ولا علي الاعرج حرج ولا علي المريض حرج ومن يطع الله ورسوله يدخله جنت تجري من تحتها الانهر ومن يتول يعذبه عذابا اليما', 26, 51, 204, 1, 6, 513, false, NULL),
    (4601, 'tanzil-uthmani-v1.1', 48, 18, 'لَّقَدْ رَضِىَ ٱللَّهُ عَنِ ٱلْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيْهِمْ وَأَثَٰبَهُمْ فَتْحًا قَرِيبًا', '0450a6b138cf0ab19674d353b0ad1a4ed6a89839136a769802de115690267b00', 'لَّقَدْ رَضِىَ ٱللَّهُ عَنِ ٱلْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيْهِمْ وَأَثَٰبَهُمْ فَتْحًا قَرِيبًا', '0450a6b138cf0ab19674d353b0ad1a4ed6a89839136a769802de115690267b00', '0450a6b138cf0ab19674d353b0ad1a4ed6a89839136a769802de115690267b00', NULL, 'لقد رضي الله عن المؤمنين اذ يبايعونك تحت الشجره فعلم ما في قلوبهم فانزل السكينه عليهم واثبهم فتحا قريبا', 26, 52, 205, 1, 6, 513, false, NULL),
    (4602, 'tanzil-uthmani-v1.1', 48, 19, 'وَمَغَانِمَ كَثِيرَةً يَأْخُذُونَهَا وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'e2f0a9d3da424e23c569b87dfa8eba4839e8f2cd4c1f83209ff8a363f0c279a7', 'وَمَغَانِمَ كَثِيرَةً يَأْخُذُونَهَا وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 'e2f0a9d3da424e23c569b87dfa8eba4839e8f2cd4c1f83209ff8a363f0c279a7', 'e2f0a9d3da424e23c569b87dfa8eba4839e8f2cd4c1f83209ff8a363f0c279a7', NULL, 'ومغانم كثيره ياخذونها وكان الله عزيزا حكيما', 26, 52, 205, 1, 6, 513, false, NULL),
    (4603, 'tanzil-uthmani-v1.1', 48, 20, 'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَٰذِهِۦ وَكَفَّ أَيْدِىَ ٱلنَّاسِ عَنكُمْ وَلِتَكُونَ ءَايَةً لِّلْمُؤْمِنِينَ وَيَهْدِيَكُمْ صِرَٰطًا مُّسْتَقِيمًا', '2369858225b2a6ae8b1c79357d108341a99a7118a416148aca3ddc0adc18d970', 'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَٰذِهِۦ وَكَفَّ أَيْدِىَ ٱلنَّاسِ عَنكُمْ وَلِتَكُونَ ءَايَةً لِّلْمُؤْمِنِينَ وَيَهْدِيَكُمْ صِرَٰطًا مُّسْتَقِيمًا', '2369858225b2a6ae8b1c79357d108341a99a7118a416148aca3ddc0adc18d970', '2369858225b2a6ae8b1c79357d108341a99a7118a416148aca3ddc0adc18d970', NULL, 'وعدكم الله مغانم كثيره تاخذونها فعجل لكم هذه وكف ايدي الناس عنكم ولتكون ءايه للمؤمنين ويهديكم صرطا مستقيما', 26, 52, 205, 1, 6, 513, false, NULL),
    (4604, 'tanzil-uthmani-v1.1', 48, 21, 'وَأُخْرَىٰ لَمْ تَقْدِرُوا۟ عَلَيْهَا قَدْ أَحَاطَ ٱللَّهُ بِهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', '214a83b1d49a9812b600f6690963cb5d3303e0afda10fdb870d35e1246be7f2c', 'وَأُخْرَىٰ لَمْ تَقْدِرُوا۟ عَلَيْهَا قَدْ أَحَاطَ ٱللَّهُ بِهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا', '214a83b1d49a9812b600f6690963cb5d3303e0afda10fdb870d35e1246be7f2c', '214a83b1d49a9812b600f6690963cb5d3303e0afda10fdb870d35e1246be7f2c', NULL, 'واخري لم تقدروا عليها قد احاط الله بها وكان الله علي كل شيء قديرا', 26, 52, 205, 1, 6, 513, false, NULL),
    (4605, 'tanzil-uthmani-v1.1', 48, 22, 'وَلَوْ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلْأَدْبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', 'b2be5c5d2cb06f5dc6df96af76bae04a431cf6681587d5ba5657e32274fb9d26', 'وَلَوْ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلْأَدْبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا', 'b2be5c5d2cb06f5dc6df96af76bae04a431cf6681587d5ba5657e32274fb9d26', 'b2be5c5d2cb06f5dc6df96af76bae04a431cf6681587d5ba5657e32274fb9d26', NULL, 'ولو قتلكم الذين كفروا لولوا الادبر ثم لا يجدون وليا ولا نصيرا', 26, 52, 205, 1, 6, 513, false, NULL),
    (4606, 'tanzil-uthmani-v1.1', 48, 23, 'سُنَّةَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', 'cba2eaa668b390edc3c122fe4bca5382b3c8f218424453e3551a1a0b62a68c99', 'سُنَّةَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا', 'cba2eaa668b390edc3c122fe4bca5382b3c8f218424453e3551a1a0b62a68c99', 'cba2eaa668b390edc3c122fe4bca5382b3c8f218424453e3551a1a0b62a68c99', NULL, 'سنه الله التي قد خلت من قبل ولن تجد لسنه الله تبديلا', 26, 52, 205, 1, 6, 513, false, NULL),
    (4607, 'tanzil-uthmani-v1.1', 48, 24, 'وَهُوَ ٱلَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', '28403bb2f521c7ef63ae2f56b0370ceac82749eeef83e06f3d355b651fe61b6b', 'وَهُوَ ٱلَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', '28403bb2f521c7ef63ae2f56b0370ceac82749eeef83e06f3d355b651fe61b6b', '28403bb2f521c7ef63ae2f56b0370ceac82749eeef83e06f3d355b651fe61b6b', NULL, 'وهو الذي كف ايديهم عنكم وايديكم عنهم ببطن مكه من بعد ان اظفركم عليهم وكان الله بما تعملون بصيرا', 26, 52, 205, 1, 6, 514, false, NULL),
    (4608, 'tanzil-uthmani-v1.1', 48, 25, 'هُمُ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱلْهَدْىَ مَعْكُوفًا أَن يَبْلُغَ مَحِلَّهُۥ وَلَوْلَا رِجَالٌ مُّؤْمِنُونَ وَنِسَآءٌ مُّؤْمِنَٰتٌ لَّمْ تَعْلَمُوهُمْ أَن تَطَـُٔوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةٌۢ بِغَيْرِ عِلْمٍ لِّيُدْخِلَ ٱللَّهُ فِى رَحْمَتِهِۦ مَن يَشَآءُ لَوْ تَزَيَّلُوا۟ لَعَذَّبْنَا ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابًا أَلِيمًا', '031438854c471c65f4c3c720393004a62488ab72013e378be1a7d6d3c8103656', 'هُمُ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱلْهَدْىَ مَعْكُوفًا أَن يَبْلُغَ مَحِلَّهُۥ وَلَوْلَا رِجَالٌ مُّؤْمِنُونَ وَنِسَآءٌ مُّؤْمِنَٰتٌ لَّمْ تَعْلَمُوهُمْ أَن تَطَـُٔوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةٌۢ بِغَيْرِ عِلْمٍ لِّيُدْخِلَ ٱللَّهُ فِى رَحْمَتِهِۦ مَن يَشَآءُ لَوْ تَزَيَّلُوا۟ لَعَذَّبْنَا ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابًا أَلِيمًا', '031438854c471c65f4c3c720393004a62488ab72013e378be1a7d6d3c8103656', '031438854c471c65f4c3c720393004a62488ab72013e378be1a7d6d3c8103656', NULL, 'هم الذين كفروا وصدوكم عن المسجد الحرام والهدي معكوفا ان يبلغ محله ولولا رجال مؤمنون ونساء مؤمنت لم تعلموهم ان تطوهم فتصيبكم منهم معره بغير علم ليدخل الله في رحمته من يشاء لو تزيلوا لعذبنا الذين كفروا منهم عذابا اليما', 26, 52, 205, 1, 6, 514, false, NULL),
    (4609, 'tanzil-uthmani-v1.1', 48, 26, 'إِذْ جَعَلَ ٱلَّذِينَ كَفَرُوا۟ فِى قُلُوبِهِمُ ٱلْحَمِيَّةَ حَمِيَّةَ ٱلْجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ ٱلتَّقْوَىٰ وَكَانُوٓا۟ أَحَقَّ بِهَا وَأَهْلَهَا وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', '70c57b15b44b1209d1b50701941d37a7079faf8cc4a29cd000d83fb435d79c8f', 'إِذْ جَعَلَ ٱلَّذِينَ كَفَرُوا۟ فِى قُلُوبِهِمُ ٱلْحَمِيَّةَ حَمِيَّةَ ٱلْجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ ٱلتَّقْوَىٰ وَكَانُوٓا۟ أَحَقَّ بِهَا وَأَهْلَهَا وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا', '70c57b15b44b1209d1b50701941d37a7079faf8cc4a29cd000d83fb435d79c8f', '70c57b15b44b1209d1b50701941d37a7079faf8cc4a29cd000d83fb435d79c8f', NULL, 'اذ جعل الذين كفروا في قلوبهم الحميه حميه الجهليه فانزل الله سكينته علي رسوله وعلي المؤمنين والزمهم كلمه التقوي وكانوا احق بها واهلها وكان الله بكل شيء عليما', 26, 52, 205, 1, 6, 514, false, NULL),
    (4610, 'tanzil-uthmani-v1.1', 48, 27, 'لَّقَدْ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءْيَا بِٱلْحَقِّ لَتَدْخُلُنَّ ٱلْمَسْجِدَ ٱلْحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ فَعَلِمَ مَا لَمْ تَعْلَمُوا۟ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحًا قَرِيبًا', '0045fc1524ae7baffedd0666e1bcbe7e2c80b74463ae741f0e7020eaa67a188d', 'لَّقَدْ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءْيَا بِٱلْحَقِّ لَتَدْخُلُنَّ ٱلْمَسْجِدَ ٱلْحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ فَعَلِمَ مَا لَمْ تَعْلَمُوا۟ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحًا قَرِيبًا', '0045fc1524ae7baffedd0666e1bcbe7e2c80b74463ae741f0e7020eaa67a188d', '0045fc1524ae7baffedd0666e1bcbe7e2c80b74463ae741f0e7020eaa67a188d', NULL, 'لقد صدق الله رسوله الرءيا بالحق لتدخلن المسجد الحرام ان شاء الله ءامنين محلقين رءوسكم ومقصرين لا تخافون فعلم ما لم تعلموا فجعل من دون ذلك فتحا قريبا', 26, 52, 205, 1, 6, 514, false, NULL),
    (4611, 'tanzil-uthmani-v1.1', 48, 28, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', '205fd623873da448a49a558a6295e64e367b4372e834bd4ed221b40a899866ed', 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', '205fd623873da448a49a558a6295e64e367b4372e834bd4ed221b40a899866ed', '205fd623873da448a49a558a6295e64e367b4372e834bd4ed221b40a899866ed', NULL, 'هو الذي ارسل رسوله بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا', 26, 52, 205, 1, 6, 514, false, NULL),
    (4612, 'tanzil-uthmani-v1.1', 48, 29, 'مُّحَمَّدٌ رَّسُولُ ٱللَّهِ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ تَرَىٰهُمْ رُكَّعًا سُجَّدًا يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا سِيمَاهُمْ فِى وُجُوهِهِم مِّنْ أَثَرِ ٱلسُّجُودِ ذَٰلِكَ مَثَلُهُمْ فِى ٱلتَّوْرَىٰةِ وَمَثَلُهُمْ فِى ٱلْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَٱسْتَغْلَظَ فَٱسْتَوَىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلْكُفَّارَ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنْهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًۢا', 'cde644142c332e0d20a2438734e166b0aa02715df604d20021384ac39050fe17', 'مُّحَمَّدٌ رَّسُولُ ٱللَّهِ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ تَرَىٰهُمْ رُكَّعًا سُجَّدًا يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا سِيمَاهُمْ فِى وُجُوهِهِم مِّنْ أَثَرِ ٱلسُّجُودِ ذَٰلِكَ مَثَلُهُمْ فِى ٱلتَّوْرَىٰةِ وَمَثَلُهُمْ فِى ٱلْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَٱسْتَغْلَظَ فَٱسْتَوَىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلْكُفَّارَ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنْهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًۢا', 'cde644142c332e0d20a2438734e166b0aa02715df604d20021384ac39050fe17', 'cde644142c332e0d20a2438734e166b0aa02715df604d20021384ac39050fe17', NULL, 'محمد رسول الله والذين معه اشداء علي الكفار رحماء بينهم تريهم ركعا سجدا يبتغون فضلا من الله ورضونا سيماهم في وجوههم من اثر السجود ذلك مثلهم في التوريه ومثلهم في الانجيل كزرع اخرج شطه فازره فاستغلظ فاستوي علي سوقه يعجب الزراع ليغيظ بهم الكفار وعد الله الذين ءامنوا وعملوا الصلحت منهم مغفره واجرا عظيما', 26, 52, 205, 1, 6, 515, false, NULL),
    (4613, 'tanzil-uthmani-v1.1', 49, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَيْنَ يَدَىِ ٱللَّهِ وَرَسُولِهِۦ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', '7e16fa8e229addb4cffefa2ce49e8b408aed63dcb983e0270547719954ace37c', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَيْنَ يَدَىِ ٱللَّهِ وَرَسُولِهِۦ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ', 'f54db0574147d2117de9acb3f84bff21fa69e062469ee23ca354f8ebe392debe', 'f54db0574147d2117de9acb3f84bff21fa69e062469ee23ca354f8ebe392debe', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يايها الذين ءامنوا لا تقدموا بين يدي الله ورسوله واتقوا الله ان الله سميع عليم', 26, 52, 206, 1, 6, 515, false, NULL),
    (4614, 'tanzil-uthmani-v1.1', 49, 2, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَرْفَعُوٓا۟ أَصْوَٰتَكُمْ فَوْقَ صَوْتِ ٱلنَّبِىِّ وَلَا تَجْهَرُوا۟ لَهُۥ بِٱلْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَٰلُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ', '6ed9ce5a62161d38318d7df05a3a009c5ab37cd08dbf5cfa84a5504a8c0076f9', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَرْفَعُوٓا۟ أَصْوَٰتَكُمْ فَوْقَ صَوْتِ ٱلنَّبِىِّ وَلَا تَجْهَرُوا۟ لَهُۥ بِٱلْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَٰلُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ', '6ed9ce5a62161d38318d7df05a3a009c5ab37cd08dbf5cfa84a5504a8c0076f9', '6ed9ce5a62161d38318d7df05a3a009c5ab37cd08dbf5cfa84a5504a8c0076f9', NULL, 'يايها الذين ءامنوا لا ترفعوا اصوتكم فوق صوت النبي ولا تجهروا له بالقول كجهر بعضكم لبعض ان تحبط اعملكم وانتم لا تشعرون', 26, 52, 206, 1, 6, 515, false, NULL),
    (4615, 'tanzil-uthmani-v1.1', 49, 3, 'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصْوَٰتَهُمْ عِندَ رَسُولِ ٱللَّهِ أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱمْتَحَنَ ٱللَّهُ قُلُوبَهُمْ لِلتَّقْوَىٰ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', '44c76a53b326c871f51d213cc6025a1c4f1489186eb1c7b7d7907fa793b1c9a2', 'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصْوَٰتَهُمْ عِندَ رَسُولِ ٱللَّهِ أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱمْتَحَنَ ٱللَّهُ قُلُوبَهُمْ لِلتَّقْوَىٰ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ', '44c76a53b326c871f51d213cc6025a1c4f1489186eb1c7b7d7907fa793b1c9a2', '44c76a53b326c871f51d213cc6025a1c4f1489186eb1c7b7d7907fa793b1c9a2', NULL, 'ان الذين يغضون اصوتهم عند رسول الله اولئك الذين امتحن الله قلوبهم للتقوي لهم مغفره واجر عظيم', 26, 52, 206, 1, 6, 515, false, NULL),
    (4616, 'tanzil-uthmani-v1.1', 49, 4, 'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلْحُجُرَٰتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ', 'f6941c009b762d6342d5b5a7c4d0fb7e7f9b0c60034875fbe68efb1454604af1', 'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلْحُجُرَٰتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ', 'f6941c009b762d6342d5b5a7c4d0fb7e7f9b0c60034875fbe68efb1454604af1', 'f6941c009b762d6342d5b5a7c4d0fb7e7f9b0c60034875fbe68efb1454604af1', NULL, 'ان الذين ينادونك من وراء الحجرت اكثرهم لا يعقلون', 26, 52, 206, 1, 6, 515, false, NULL),
    (4617, 'tanzil-uthmani-v1.1', 49, 5, 'وَلَوْ أَنَّهُمْ صَبَرُوا۟ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَّهُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '7ebf452f982ff0526e38e402d9cf05ca9efe829760f5f7b0537eb166da67f9a7', 'وَلَوْ أَنَّهُمْ صَبَرُوا۟ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَّهُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '7ebf452f982ff0526e38e402d9cf05ca9efe829760f5f7b0537eb166da67f9a7', '7ebf452f982ff0526e38e402d9cf05ca9efe829760f5f7b0537eb166da67f9a7', NULL, 'ولو انهم صبروا حتي تخرج اليهم لكان خيرا لهم والله غفور رحيم', 26, 52, 206, 1, 6, 516, false, NULL),
    (4618, 'tanzil-uthmani-v1.1', 49, 6, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَٰلَةٍ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَٰدِمِينَ', '5d485c65b9af046684c3949cbd741a53f7b7db8dfd34b44c0d3e37f326555963', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَٰلَةٍ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَٰدِمِينَ', '5d485c65b9af046684c3949cbd741a53f7b7db8dfd34b44c0d3e37f326555963', '5d485c65b9af046684c3949cbd741a53f7b7db8dfd34b44c0d3e37f326555963', NULL, 'يايها الذين ءامنوا ان جاءكم فاسق بنبا فتبينوا ان تصيبوا قوما بجهله فتصبحوا علي ما فعلتم ندمين', 26, 52, 206, 1, 6, 516, false, NULL),
    (4619, 'tanzil-uthmani-v1.1', 49, 7, 'وَٱعْلَمُوٓا۟ أَنَّ فِيكُمْ رَسُولَ ٱللَّهِ لَوْ يُطِيعُكُمْ فِى كَثِيرٍ مِّنَ ٱلْأَمْرِ لَعَنِتُّمْ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيْكُمُ ٱلْإِيمَٰنَ وَزَيَّنَهُۥ فِى قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ ٱلْكُفْرَ وَٱلْفُسُوقَ وَٱلْعِصْيَانَ أُو۟لَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ', '932674432f6565467c44285518ea4a30c597290245d90851b0a1d330a4d1a5d4', 'وَٱعْلَمُوٓا۟ أَنَّ فِيكُمْ رَسُولَ ٱللَّهِ لَوْ يُطِيعُكُمْ فِى كَثِيرٍ مِّنَ ٱلْأَمْرِ لَعَنِتُّمْ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيْكُمُ ٱلْإِيمَٰنَ وَزَيَّنَهُۥ فِى قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ ٱلْكُفْرَ وَٱلْفُسُوقَ وَٱلْعِصْيَانَ أُو۟لَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ', '932674432f6565467c44285518ea4a30c597290245d90851b0a1d330a4d1a5d4', '932674432f6565467c44285518ea4a30c597290245d90851b0a1d330a4d1a5d4', NULL, 'واعلموا ان فيكم رسول الله لو يطيعكم في كثير من الامر لعنتم ولكن الله حبب اليكم الايمن وزينه في قلوبكم وكره اليكم الكفر والفسوق والعصيان اولئك هم الرشدون', 26, 52, 206, 1, 6, 516, false, NULL),
    (4620, 'tanzil-uthmani-v1.1', 49, 8, 'فَضْلًا مِّنَ ٱللَّهِ وَنِعْمَةً وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '5c1f6202471417ae8c6d18e7bcbf472f5c71455ef3970d62dca7a94c46751780', 'فَضْلًا مِّنَ ٱللَّهِ وَنِعْمَةً وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '5c1f6202471417ae8c6d18e7bcbf472f5c71455ef3970d62dca7a94c46751780', '5c1f6202471417ae8c6d18e7bcbf472f5c71455ef3970d62dca7a94c46751780', NULL, 'فضلا من الله ونعمه والله عليم حكيم', 26, 52, 206, 1, 6, 516, false, NULL),
    (4621, 'tanzil-uthmani-v1.1', 49, 9, 'وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', '5e81e611862c5367924e69031ec2aa5208bb6a19e1c43a21906ebcfa050f87a0', 'وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', '5e81e611862c5367924e69031ec2aa5208bb6a19e1c43a21906ebcfa050f87a0', '5e81e611862c5367924e69031ec2aa5208bb6a19e1c43a21906ebcfa050f87a0', NULL, 'وان طائفتان من المؤمنين اقتتلوا فاصلحوا بينهما فان بغت احديهما علي الاخري فقتلوا التي تبغي حتي تفيء الي امر الله فان فاءت فاصلحوا بينهما بالعدل واقسطوا ان الله يحب المقسطين', 26, 52, 206, 1, 6, 516, false, NULL),
    (4622, 'tanzil-uthmani-v1.1', 49, 10, 'إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', 'fc8999d03fee799f6627e8be73b0ca61615e7c82ff223cd70bc0418643314187', 'إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', 'fc8999d03fee799f6627e8be73b0ca61615e7c82ff223cd70bc0418643314187', 'fc8999d03fee799f6627e8be73b0ca61615e7c82ff223cd70bc0418643314187', NULL, 'انما المؤمنون اخوه فاصلحوا بين اخويكم واتقوا الله لعلكم ترحمون', 26, 52, 206, 1, 6, 516, false, NULL),
    (4623, 'tanzil-uthmani-v1.1', 49, 11, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَسْخَرْ قَوْمٌ مِّن قَوْمٍ عَسَىٰٓ أَن يَكُونُوا۟ خَيْرًا مِّنْهُمْ وَلَا نِسَآءٌ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيْرًا مِّنْهُنَّ وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَٰبِ بِئْسَ ٱلِٱسْمُ ٱلْفُسُوقُ بَعْدَ ٱلْإِيمَٰنِ وَمَن لَّمْ يَتُبْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'ac5862a988477f3b4e4ed8ecec41f7cb8ee47e0127eddc627476e177a40850c0', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَسْخَرْ قَوْمٌ مِّن قَوْمٍ عَسَىٰٓ أَن يَكُونُوا۟ خَيْرًا مِّنْهُمْ وَلَا نِسَآءٌ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيْرًا مِّنْهُنَّ وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَٰبِ بِئْسَ ٱلِٱسْمُ ٱلْفُسُوقُ بَعْدَ ٱلْإِيمَٰنِ وَمَن لَّمْ يَتُبْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 'ac5862a988477f3b4e4ed8ecec41f7cb8ee47e0127eddc627476e177a40850c0', 'ac5862a988477f3b4e4ed8ecec41f7cb8ee47e0127eddc627476e177a40850c0', NULL, 'يايها الذين ءامنوا لا يسخر قوم من قوم عسي ان يكونوا خيرا منهم ولا نساء من نساء عسي ان يكن خيرا منهن ولا تلمزوا انفسكم ولا تنابزوا بالالقب بئس الاسم الفسوق بعد الايمن ومن لم يتب فاولئك هم الظلمون', 26, 52, 206, 1, 6, 516, false, NULL),
    (4624, 'tanzil-uthmani-v1.1', 49, 12, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ تَوَّابٌ رَّحِيمٌ', '58671edefb6839710bc74148f378fdc083b48fe0125692a490f7f3afa4279e8e', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ تَوَّابٌ رَّحِيمٌ', '58671edefb6839710bc74148f378fdc083b48fe0125692a490f7f3afa4279e8e', '58671edefb6839710bc74148f378fdc083b48fe0125692a490f7f3afa4279e8e', NULL, 'يايها الذين ءامنوا اجتنبوا كثيرا من الظن ان بعض الظن اثم ولا تجسسوا ولا يغتب بعضكم بعضا ايحب احدكم ان ياكل لحم اخيه ميتا فكرهتموه واتقوا الله ان الله تواب رحيم', 26, 52, 206, 1, 6, 517, false, NULL),
    (4625, 'tanzil-uthmani-v1.1', 49, 13, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَٰكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَٰكُمْ شُعُوبًا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌ', '714e0522b14f351bf87b019eb00903764f423b54c10e89e5d354690c098f8fbc', 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَٰكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَٰكُمْ شُعُوبًا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌ', '714e0522b14f351bf87b019eb00903764f423b54c10e89e5d354690c098f8fbc', '714e0522b14f351bf87b019eb00903764f423b54c10e89e5d354690c098f8fbc', NULL, 'يايها الناس انا خلقنكم من ذكر وانثي وجعلنكم شعوبا وقبائل لتعارفوا ان اكرمكم عند الله اتقيكم ان الله عليم خبير', 26, 52, 206, 1, 6, 517, false, NULL),
    (4626, 'tanzil-uthmani-v1.1', 49, 14, 'قَالَتِ ٱلْأَعْرَابُ ءَامَنَّا قُل لَّمْ تُؤْمِنُوا۟ وَلَٰكِن قُولُوٓا۟ أَسْلَمْنَا وَلَمَّا يَدْخُلِ ٱلْإِيمَٰنُ فِى قُلُوبِكُمْ وَإِن تُطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتْكُم مِّنْ أَعْمَٰلِكُمْ شَيْـًٔا إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'eb6dd0c298bb8cdfa79c92b0ffc4471b2b45c969fcd2d685f7557bb9a46fc699', 'قَالَتِ ٱلْأَعْرَابُ ءَامَنَّا قُل لَّمْ تُؤْمِنُوا۟ وَلَٰكِن قُولُوٓا۟ أَسْلَمْنَا وَلَمَّا يَدْخُلِ ٱلْإِيمَٰنُ فِى قُلُوبِكُمْ وَإِن تُطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتْكُم مِّنْ أَعْمَٰلِكُمْ شَيْـًٔا إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'eb6dd0c298bb8cdfa79c92b0ffc4471b2b45c969fcd2d685f7557bb9a46fc699', 'eb6dd0c298bb8cdfa79c92b0ffc4471b2b45c969fcd2d685f7557bb9a46fc699', NULL, 'قالت الاعراب ءامنا قل لم تؤمنوا ولكن قولوا اسلمنا ولما يدخل الايمن في قلوبكم وان تطيعوا الله ورسوله لا يلتكم من اعملكم شيا ان الله غفور رحيم', 26, 52, 207, 1, 6, 517, false, NULL),
    (4627, 'tanzil-uthmani-v1.1', 49, 15, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', 'bedee6fa54d799493e5945db36310d61e874913c478c796314b5634853c1b605', 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', 'bedee6fa54d799493e5945db36310d61e874913c478c796314b5634853c1b605', 'bedee6fa54d799493e5945db36310d61e874913c478c796314b5634853c1b605', NULL, 'انما المؤمنون الذين ءامنوا بالله ورسوله ثم لم يرتابوا وجهدوا بامولهم وانفسهم في سبيل الله اولئك هم الصدقون', 26, 52, 207, 1, 6, 517, false, NULL),
    (4628, 'tanzil-uthmani-v1.1', 49, 16, 'قُلْ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمْ وَٱللَّهُ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '8697d54a1fb0eff001a9d914635816d7c3962dce732102cf6df258e72f86b619', 'قُلْ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمْ وَٱللَّهُ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '8697d54a1fb0eff001a9d914635816d7c3962dce732102cf6df258e72f86b619', '8697d54a1fb0eff001a9d914635816d7c3962dce732102cf6df258e72f86b619', NULL, 'قل اتعلمون الله بدينكم والله يعلم ما في السموت وما في الارض والله بكل شيء عليم', 26, 52, 207, 1, 6, 517, false, NULL),
    (4629, 'tanzil-uthmani-v1.1', 49, 17, 'يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا۟ قُل لَّا تَمُنُّوا۟ عَلَىَّ إِسْلَٰمَكُم بَلِ ٱللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَىٰكُمْ لِلْإِيمَٰنِ إِن كُنتُمْ صَٰدِقِينَ', 'c4a8cbadba482a1c278665cb68abd75645a6c4c62f1504c1f55033bdbed1377a', 'يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا۟ قُل لَّا تَمُنُّوا۟ عَلَىَّ إِسْلَٰمَكُم بَلِ ٱللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَىٰكُمْ لِلْإِيمَٰنِ إِن كُنتُمْ صَٰدِقِينَ', 'c4a8cbadba482a1c278665cb68abd75645a6c4c62f1504c1f55033bdbed1377a', 'c4a8cbadba482a1c278665cb68abd75645a6c4c62f1504c1f55033bdbed1377a', NULL, 'يمنون عليك ان اسلموا قل لا تمنوا علي اسلمكم بل الله يمن عليكم ان هديكم للايمن ان كنتم صدقين', 26, 52, 207, 1, 6, 517, false, NULL),
    (4630, 'tanzil-uthmani-v1.1', 49, 18, 'إِنَّ ٱللَّهَ يَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ بَصِيرٌۢ بِمَا تَعْمَلُونَ', 'ea3ab9ca2e3770170fbbb72e689f8c9c11e592a11191f5d8c08808b6eace8aab', 'إِنَّ ٱللَّهَ يَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱللَّهُ بَصِيرٌۢ بِمَا تَعْمَلُونَ', 'ea3ab9ca2e3770170fbbb72e689f8c9c11e592a11191f5d8c08808b6eace8aab', 'ea3ab9ca2e3770170fbbb72e689f8c9c11e592a11191f5d8c08808b6eace8aab', NULL, 'ان الله يعلم غيب السموت والارض والله بصير بما تعملون', 26, 52, 207, 1, 6, 517, false, NULL),
    (4631, 'tanzil-uthmani-v1.1', 50, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قٓ وَٱلْقُرْءَانِ ٱلْمَجِيدِ', '925f3ad3225f048153505d4658f205b2ae3d458343c5ba520efe00c8bb9ebeac', 'قٓ وَٱلْقُرْءَانِ ٱلْمَجِيدِ', 'df8ec214731ca536cfd6d2574e86675c03a20dd639e08919fee91c19a5d0e331', 'df8ec214731ca536cfd6d2574e86675c03a20dd639e08919fee91c19a5d0e331', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'ق والقرءان المجيد', 26, 52, 207, 1, 7, 518, false, NULL),
    (4632, 'tanzil-uthmani-v1.1', 50, 2, 'بَلْ عَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ فَقَالَ ٱلْكَٰفِرُونَ هَٰذَا شَىْءٌ عَجِيبٌ', '3db0688b3005b531578a03c68a32dd0ea4e99a0d047b4abb852dce7b3616ac32', 'بَلْ عَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ فَقَالَ ٱلْكَٰفِرُونَ هَٰذَا شَىْءٌ عَجِيبٌ', '3db0688b3005b531578a03c68a32dd0ea4e99a0d047b4abb852dce7b3616ac32', '3db0688b3005b531578a03c68a32dd0ea4e99a0d047b4abb852dce7b3616ac32', NULL, 'بل عجبوا ان جاءهم منذر منهم فقال الكفرون هذا شيء عجيب', 26, 52, 207, 1, 7, 518, false, NULL),
    (4633, 'tanzil-uthmani-v1.1', 50, 3, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا ذَٰلِكَ رَجْعٌۢ بَعِيدٌ', '1abb419ef5c8ea72192d834ce2e8d4e0a489ce2e099d248db30755622069e042', 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًا ذَٰلِكَ رَجْعٌۢ بَعِيدٌ', '1abb419ef5c8ea72192d834ce2e8d4e0a489ce2e099d248db30755622069e042', '1abb419ef5c8ea72192d834ce2e8d4e0a489ce2e099d248db30755622069e042', NULL, 'اءذا متنا وكنا ترابا ذلك رجع بعيد', 26, 52, 207, 1, 7, 518, false, NULL),
    (4634, 'tanzil-uthmani-v1.1', 50, 4, 'قَدْ عَلِمْنَا مَا تَنقُصُ ٱلْأَرْضُ مِنْهُمْ وَعِندَنَا كِتَٰبٌ حَفِيظٌۢ', '446999b7906713ed7aac9180ab29b9e84e4f00424003b4a3bc215ccf736d490e', 'قَدْ عَلِمْنَا مَا تَنقُصُ ٱلْأَرْضُ مِنْهُمْ وَعِندَنَا كِتَٰبٌ حَفِيظٌۢ', '446999b7906713ed7aac9180ab29b9e84e4f00424003b4a3bc215ccf736d490e', '446999b7906713ed7aac9180ab29b9e84e4f00424003b4a3bc215ccf736d490e', NULL, 'قد علمنا ما تنقص الارض منهم وعندنا كتب حفيظ', 26, 52, 207, 1, 7, 518, false, NULL),
    (4635, 'tanzil-uthmani-v1.1', 50, 5, 'بَلْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَهُمْ فِىٓ أَمْرٍ مَّرِيجٍ', '6fd0ea0772ec67c6ea4cac702e7cb991d88c08c45a7d7392ccac5a9e382847fc', 'بَلْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَهُمْ فِىٓ أَمْرٍ مَّرِيجٍ', '6fd0ea0772ec67c6ea4cac702e7cb991d88c08c45a7d7392ccac5a9e382847fc', '6fd0ea0772ec67c6ea4cac702e7cb991d88c08c45a7d7392ccac5a9e382847fc', NULL, 'بل كذبوا بالحق لما جاءهم فهم في امر مريج', 26, 52, 207, 1, 7, 518, false, NULL),
    (4636, 'tanzil-uthmani-v1.1', 50, 6, 'أَفَلَمْ يَنظُرُوٓا۟ إِلَى ٱلسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَٰهَا وَزَيَّنَّٰهَا وَمَا لَهَا مِن فُرُوجٍ', '8db31f0e8e3908fde41b744aed7c2837a7e7150eb9d53df7165dac9c93c9c548', 'أَفَلَمْ يَنظُرُوٓا۟ إِلَى ٱلسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَٰهَا وَزَيَّنَّٰهَا وَمَا لَهَا مِن فُرُوجٍ', '8db31f0e8e3908fde41b744aed7c2837a7e7150eb9d53df7165dac9c93c9c548', '8db31f0e8e3908fde41b744aed7c2837a7e7150eb9d53df7165dac9c93c9c548', NULL, 'افلم ينظروا الي السماء فوقهم كيف بنينها وزينها وما لها من فروج', 26, 52, 207, 1, 7, 518, false, NULL),
    (4637, 'tanzil-uthmani-v1.1', 50, 7, 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۭ بَهِيجٍ', 'ba3088e61e84125d4ae4ddfcc26d417818377998a8292c0e0908ecbd19101a7d', 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۭ بَهِيجٍ', 'ba3088e61e84125d4ae4ddfcc26d417818377998a8292c0e0908ecbd19101a7d', 'ba3088e61e84125d4ae4ddfcc26d417818377998a8292c0e0908ecbd19101a7d', NULL, 'والارض مددنها والقينا فيها روسي وانبتنا فيها من كل زوج بهيج', 26, 52, 207, 1, 7, 518, false, NULL),
    (4638, 'tanzil-uthmani-v1.1', 50, 8, 'تَبْصِرَةً وَذِكْرَىٰ لِكُلِّ عَبْدٍ مُّنِيبٍ', 'fdcdb7489e8a3688d3ddc99090486b0ac2a313965f90a3d773437087d090d01f', 'تَبْصِرَةً وَذِكْرَىٰ لِكُلِّ عَبْدٍ مُّنِيبٍ', 'fdcdb7489e8a3688d3ddc99090486b0ac2a313965f90a3d773437087d090d01f', 'fdcdb7489e8a3688d3ddc99090486b0ac2a313965f90a3d773437087d090d01f', NULL, 'تبصره وذكري لكل عبد منيب', 26, 52, 207, 1, 7, 518, false, NULL),
    (4639, 'tanzil-uthmani-v1.1', 50, 9, 'وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءً مُّبَٰرَكًا فَأَنۢبَتْنَا بِهِۦ جَنَّٰتٍ وَحَبَّ ٱلْحَصِيدِ', '642f1e41d04eb7f72fea58f37d204e232232c61d1dfb1ef31a490f63f66be507', 'وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءً مُّبَٰرَكًا فَأَنۢبَتْنَا بِهِۦ جَنَّٰتٍ وَحَبَّ ٱلْحَصِيدِ', '642f1e41d04eb7f72fea58f37d204e232232c61d1dfb1ef31a490f63f66be507', '642f1e41d04eb7f72fea58f37d204e232232c61d1dfb1ef31a490f63f66be507', NULL, 'ونزلنا من السماء ماء مبركا فانبتنا به جنت وحب الحصيد', 26, 52, 207, 1, 7, 518, false, NULL),
    (4640, 'tanzil-uthmani-v1.1', 50, 10, 'وَٱلنَّخْلَ بَاسِقَٰتٍ لَّهَا طَلْعٌ نَّضِيدٌ', '46fb75fff0804b498ad07eb00e78c75687cf3b942e861bc01b5b7932e7c68f9d', 'وَٱلنَّخْلَ بَاسِقَٰتٍ لَّهَا طَلْعٌ نَّضِيدٌ', '46fb75fff0804b498ad07eb00e78c75687cf3b942e861bc01b5b7932e7c68f9d', '46fb75fff0804b498ad07eb00e78c75687cf3b942e861bc01b5b7932e7c68f9d', NULL, 'والنخل باسقت لها طلع نضيد', 26, 52, 207, 1, 7, 518, false, NULL),
    (4641, 'tanzil-uthmani-v1.1', 50, 11, 'رِّزْقًا لِّلْعِبَادِ وَأَحْيَيْنَا بِهِۦ بَلْدَةً مَّيْتًا كَذَٰلِكَ ٱلْخُرُوجُ', 'ca9f4ff97c28300c4a0e357ccfdcc782a852698c410afd41c38e2351e9d5aab4', 'رِّزْقًا لِّلْعِبَادِ وَأَحْيَيْنَا بِهِۦ بَلْدَةً مَّيْتًا كَذَٰلِكَ ٱلْخُرُوجُ', 'ca9f4ff97c28300c4a0e357ccfdcc782a852698c410afd41c38e2351e9d5aab4', 'ca9f4ff97c28300c4a0e357ccfdcc782a852698c410afd41c38e2351e9d5aab4', NULL, 'رزقا للعباد واحيينا به بلده ميتا كذلك الخروج', 26, 52, 207, 1, 7, 518, false, NULL),
    (4642, 'tanzil-uthmani-v1.1', 50, 12, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَأَصْحَٰبُ ٱلرَّسِّ وَثَمُودُ', 'dd9f693b3ed9d906cd6a673b68cbd2689409dd3aef6f46f0d946fa2aa761b6fd', 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَأَصْحَٰبُ ٱلرَّسِّ وَثَمُودُ', 'dd9f693b3ed9d906cd6a673b68cbd2689409dd3aef6f46f0d946fa2aa761b6fd', 'dd9f693b3ed9d906cd6a673b68cbd2689409dd3aef6f46f0d946fa2aa761b6fd', NULL, 'كذبت قبلهم قوم نوح واصحب الرس وثمود', 26, 52, 207, 1, 7, 518, false, NULL),
    (4643, 'tanzil-uthmani-v1.1', 50, 13, 'وَعَادٌ وَفِرْعَوْنُ وَإِخْوَٰنُ لُوطٍ', '5fe248479f2b5dad37d3c878f6226e2258261c68e839e98e17ea313d51d6ce53', 'وَعَادٌ وَفِرْعَوْنُ وَإِخْوَٰنُ لُوطٍ', '5fe248479f2b5dad37d3c878f6226e2258261c68e839e98e17ea313d51d6ce53', '5fe248479f2b5dad37d3c878f6226e2258261c68e839e98e17ea313d51d6ce53', NULL, 'وعاد وفرعون واخون لوط', 26, 52, 207, 1, 7, 518, false, NULL),
    (4644, 'tanzil-uthmani-v1.1', 50, 14, 'وَأَصْحَٰبُ ٱلْأَيْكَةِ وَقَوْمُ تُبَّعٍ كُلٌّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ', 'be686df9f52e7fff494fbe4d750cafa13aecb0a90851babe9e656b23889c5d3b', 'وَأَصْحَٰبُ ٱلْأَيْكَةِ وَقَوْمُ تُبَّعٍ كُلٌّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ', 'be686df9f52e7fff494fbe4d750cafa13aecb0a90851babe9e656b23889c5d3b', 'be686df9f52e7fff494fbe4d750cafa13aecb0a90851babe9e656b23889c5d3b', NULL, 'واصحب الايكه وقوم تبع كل كذب الرسل فحق وعيد', 26, 52, 207, 1, 7, 518, false, NULL),
    (4645, 'tanzil-uthmani-v1.1', 50, 15, 'أَفَعَيِينَا بِٱلْخَلْقِ ٱلْأَوَّلِ بَلْ هُمْ فِى لَبْسٍ مِّنْ خَلْقٍ جَدِيدٍ', '9bdfef3c4bbe92b4fc46bd700cb36b9fd59e17abcaec43d1888ac6eeaaaa8447', 'أَفَعَيِينَا بِٱلْخَلْقِ ٱلْأَوَّلِ بَلْ هُمْ فِى لَبْسٍ مِّنْ خَلْقٍ جَدِيدٍ', '9bdfef3c4bbe92b4fc46bd700cb36b9fd59e17abcaec43d1888ac6eeaaaa8447', '9bdfef3c4bbe92b4fc46bd700cb36b9fd59e17abcaec43d1888ac6eeaaaa8447', NULL, 'افعيينا بالخلق الاول بل هم في لبس من خلق جديد', 26, 52, 207, 1, 7, 518, false, NULL),
    (4646, 'tanzil-uthmani-v1.1', 50, 16, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ', 'b555a3f8389d17b7c4d4f3dae82ac6123499e985c9400403b3220833b7df7969', 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ', 'b555a3f8389d17b7c4d4f3dae82ac6123499e985c9400403b3220833b7df7969', 'b555a3f8389d17b7c4d4f3dae82ac6123499e985c9400403b3220833b7df7969', NULL, 'ولقد خلقنا الانسن ونعلم ما توسوس به نفسه ونحن اقرب اليه من حبل الوريد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4647, 'tanzil-uthmani-v1.1', 50, 17, 'إِذْ يَتَلَقَّى ٱلْمُتَلَقِّيَانِ عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٌ', '9ed1b5f54f219dc8edb3419c402fd72a2ff3cc5456e42de912246dc7bb7e4963', 'إِذْ يَتَلَقَّى ٱلْمُتَلَقِّيَانِ عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٌ', '9ed1b5f54f219dc8edb3419c402fd72a2ff3cc5456e42de912246dc7bb7e4963', '9ed1b5f54f219dc8edb3419c402fd72a2ff3cc5456e42de912246dc7bb7e4963', NULL, 'اذ يتلقي المتلقيان عن اليمين وعن الشمال قعيد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4648, 'tanzil-uthmani-v1.1', 50, 18, 'مَّا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ', '9cac4976deaec6f797e50e36e76dbbc92c4a1bdd330080446bf45942dcca42c4', 'مَّا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ', '9cac4976deaec6f797e50e36e76dbbc92c4a1bdd330080446bf45942dcca42c4', '9cac4976deaec6f797e50e36e76dbbc92c4a1bdd330080446bf45942dcca42c4', NULL, 'ما يلفظ من قول الا لديه رقيب عتيد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4649, 'tanzil-uthmani-v1.1', 50, 19, 'وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ', '3075ba6d3e25fc25bd8b57e14c0396a7a2041bb27ec19430f5a10bfdd247c397', 'وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ', '3075ba6d3e25fc25bd8b57e14c0396a7a2041bb27ec19430f5a10bfdd247c397', '3075ba6d3e25fc25bd8b57e14c0396a7a2041bb27ec19430f5a10bfdd247c397', NULL, 'وجاءت سكره الموت بالحق ذلك ما كنت منه تحيد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4650, 'tanzil-uthmani-v1.1', 50, 20, 'وَنُفِخَ فِى ٱلصُّورِ ذَٰلِكَ يَوْمُ ٱلْوَعِيدِ', '32a5500c37c29ab84ff8836746896acb2805f6c6ecfec1910945a8b84643e156', 'وَنُفِخَ فِى ٱلصُّورِ ذَٰلِكَ يَوْمُ ٱلْوَعِيدِ', '32a5500c37c29ab84ff8836746896acb2805f6c6ecfec1910945a8b84643e156', '32a5500c37c29ab84ff8836746896acb2805f6c6ecfec1910945a8b84643e156', NULL, 'ونفخ في الصور ذلك يوم الوعيد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4651, 'tanzil-uthmani-v1.1', 50, 21, 'وَجَآءَتْ كُلُّ نَفْسٍ مَّعَهَا سَآئِقٌ وَشَهِيدٌ', '2a78f6815c45096dc40471da7e76e98397675108fbd1d800a9c7fcbceab99730', 'وَجَآءَتْ كُلُّ نَفْسٍ مَّعَهَا سَآئِقٌ وَشَهِيدٌ', '2a78f6815c45096dc40471da7e76e98397675108fbd1d800a9c7fcbceab99730', '2a78f6815c45096dc40471da7e76e98397675108fbd1d800a9c7fcbceab99730', NULL, 'وجاءت كل نفس معها سائق وشهيد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4652, 'tanzil-uthmani-v1.1', 50, 22, 'لَّقَدْ كُنتَ فِى غَفْلَةٍ مِّنْ هَٰذَا فَكَشَفْنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلْيَوْمَ حَدِيدٌ', '0cf4a0f6163514d83a06821226af9603169b447ceadb9687c36a6a8d8bd6c617', 'لَّقَدْ كُنتَ فِى غَفْلَةٍ مِّنْ هَٰذَا فَكَشَفْنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلْيَوْمَ حَدِيدٌ', '0cf4a0f6163514d83a06821226af9603169b447ceadb9687c36a6a8d8bd6c617', '0cf4a0f6163514d83a06821226af9603169b447ceadb9687c36a6a8d8bd6c617', NULL, 'لقد كنت في غفله من هذا فكشفنا عنك غطاءك فبصرك اليوم حديد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4653, 'tanzil-uthmani-v1.1', 50, 23, 'وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَىَّ عَتِيدٌ', 'e20fa3dfe73219aa14bb46b3f2e854e95c583221def451bf66394bd8c65c8ea2', 'وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَىَّ عَتِيدٌ', 'e20fa3dfe73219aa14bb46b3f2e854e95c583221def451bf66394bd8c65c8ea2', 'e20fa3dfe73219aa14bb46b3f2e854e95c583221def451bf66394bd8c65c8ea2', NULL, 'وقال قرينه هذا ما لدي عتيد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4654, 'tanzil-uthmani-v1.1', 50, 24, 'أَلْقِيَا فِى جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍ', 'fb3769ab078cf939d626870ab3c83a63303268151274e775d3eb3d3a31a87ed9', 'أَلْقِيَا فِى جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍ', 'fb3769ab078cf939d626870ab3c83a63303268151274e775d3eb3d3a31a87ed9', 'fb3769ab078cf939d626870ab3c83a63303268151274e775d3eb3d3a31a87ed9', NULL, 'القيا في جهنم كل كفار عنيد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4655, 'tanzil-uthmani-v1.1', 50, 25, 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ مُّرِيبٍ', 'e9a7fe996c0955eaf1ebb58d3c08206fb41b4561142205f8abaa5589109226aa', 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ مُّرِيبٍ', 'e9a7fe996c0955eaf1ebb58d3c08206fb41b4561142205f8abaa5589109226aa', 'e9a7fe996c0955eaf1ebb58d3c08206fb41b4561142205f8abaa5589109226aa', NULL, 'مناع للخير معتد مريب', 26, 52, 207, 1, 7, 519, false, NULL),
    (4656, 'tanzil-uthmani-v1.1', 50, 26, 'ٱلَّذِى جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلْقِيَاهُ فِى ٱلْعَذَابِ ٱلشَّدِيدِ', 'd587db99113e2c0b7cd5951040574673b9efb3c2fc0f3c64b4c8a7c693053b3b', 'ٱلَّذِى جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلْقِيَاهُ فِى ٱلْعَذَابِ ٱلشَّدِيدِ', 'd587db99113e2c0b7cd5951040574673b9efb3c2fc0f3c64b4c8a7c693053b3b', 'd587db99113e2c0b7cd5951040574673b9efb3c2fc0f3c64b4c8a7c693053b3b', NULL, 'الذي جعل مع الله الها ءاخر فالقياه في العذاب الشديد', 26, 52, 207, 1, 7, 519, false, NULL),
    (4657, 'tanzil-uthmani-v1.1', 50, 27, 'قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ وَلَٰكِن كَانَ فِى ضَلَٰلٍۭ بَعِيدٍ', '0750cdc59d4c9e5c5e3e795fff60d689e1c6cf80a78a59ef11882a5b69f9f65c', 'قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ وَلَٰكِن كَانَ فِى ضَلَٰلٍۭ بَعِيدٍ', '0750cdc59d4c9e5c5e3e795fff60d689e1c6cf80a78a59ef11882a5b69f9f65c', '0750cdc59d4c9e5c5e3e795fff60d689e1c6cf80a78a59ef11882a5b69f9f65c', NULL, 'قال قرينه ربنا ما اطغيته ولكن كان في ضلل بعيد', 26, 52, 208, 1, 7, 519, false, NULL),
    (4658, 'tanzil-uthmani-v1.1', 50, 28, 'قَالَ لَا تَخْتَصِمُوا۟ لَدَىَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِٱلْوَعِيدِ', 'cc197f8a711d089b13156a094aaaa401c757f8acf9dcca591a368e940cd58ab5', 'قَالَ لَا تَخْتَصِمُوا۟ لَدَىَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِٱلْوَعِيدِ', 'cc197f8a711d089b13156a094aaaa401c757f8acf9dcca591a368e940cd58ab5', 'cc197f8a711d089b13156a094aaaa401c757f8acf9dcca591a368e940cd58ab5', NULL, 'قال لا تختصموا لدي وقد قدمت اليكم بالوعيد', 26, 52, 208, 1, 7, 519, false, NULL),
    (4659, 'tanzil-uthmani-v1.1', 50, 29, 'مَا يُبَدَّلُ ٱلْقَوْلُ لَدَىَّ وَمَآ أَنَا۠ بِظَلَّٰمٍ لِّلْعَبِيدِ', '66e6481c130566ec201e99b214e19480cf01e54122a6aa7b2a32b16d348e6886', 'مَا يُبَدَّلُ ٱلْقَوْلُ لَدَىَّ وَمَآ أَنَا۠ بِظَلَّٰمٍ لِّلْعَبِيدِ', '66e6481c130566ec201e99b214e19480cf01e54122a6aa7b2a32b16d348e6886', '66e6481c130566ec201e99b214e19480cf01e54122a6aa7b2a32b16d348e6886', NULL, 'ما يبدل القول لدي وما انا بظلم للعبيد', 26, 52, 208, 1, 7, 519, false, NULL),
    (4660, 'tanzil-uthmani-v1.1', 50, 30, 'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدٍ', '29943300d141dabdf54a1985933ff9b9acf644d8a342d33ce8e728b4e28763d2', 'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدٍ', '29943300d141dabdf54a1985933ff9b9acf644d8a342d33ce8e728b4e28763d2', '29943300d141dabdf54a1985933ff9b9acf644d8a342d33ce8e728b4e28763d2', NULL, 'يوم نقول لجهنم هل امتلات وتقول هل من مزيد', 26, 52, 208, 1, 7, 519, false, NULL),
    (4661, 'tanzil-uthmani-v1.1', 50, 31, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ', '726800b30a9f54863c1ebb89c98896cdae4e0aa5770ed7ba9a522747ed7ff8e3', 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ', '726800b30a9f54863c1ebb89c98896cdae4e0aa5770ed7ba9a522747ed7ff8e3', '726800b30a9f54863c1ebb89c98896cdae4e0aa5770ed7ba9a522747ed7ff8e3', NULL, 'وازلفت الجنه للمتقين غير بعيد', 26, 52, 208, 1, 7, 519, false, NULL),
    (4662, 'tanzil-uthmani-v1.1', 50, 32, 'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٍ', '8740d7ac3ededc70a5eb8d0c09a673a184d72eabfee48559491e321afe8bd07f', 'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٍ', '8740d7ac3ededc70a5eb8d0c09a673a184d72eabfee48559491e321afe8bd07f', '8740d7ac3ededc70a5eb8d0c09a673a184d72eabfee48559491e321afe8bd07f', NULL, 'هذا ما توعدون لكل اواب حفيظ', 26, 52, 208, 1, 7, 519, false, NULL),
    (4663, 'tanzil-uthmani-v1.1', 50, 33, 'مَّنْ خَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ وَجَآءَ بِقَلْبٍ مُّنِيبٍ', '95765fe7c9bcaab2c3773e63701dd357c822fc1b8a39cee51324939d43a31b6c', 'مَّنْ خَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ وَجَآءَ بِقَلْبٍ مُّنِيبٍ', '95765fe7c9bcaab2c3773e63701dd357c822fc1b8a39cee51324939d43a31b6c', '95765fe7c9bcaab2c3773e63701dd357c822fc1b8a39cee51324939d43a31b6c', NULL, 'من خشي الرحمن بالغيب وجاء بقلب منيب', 26, 52, 208, 1, 7, 519, false, NULL),
    (4664, 'tanzil-uthmani-v1.1', 50, 34, 'ٱدْخُلُوهَا بِسَلَٰمٍ ذَٰلِكَ يَوْمُ ٱلْخُلُودِ', 'd8f61fa8284a2158c40d068ebdf897bac7a03b7954f52614aec0dad43ede54c0', 'ٱدْخُلُوهَا بِسَلَٰمٍ ذَٰلِكَ يَوْمُ ٱلْخُلُودِ', 'd8f61fa8284a2158c40d068ebdf897bac7a03b7954f52614aec0dad43ede54c0', 'd8f61fa8284a2158c40d068ebdf897bac7a03b7954f52614aec0dad43ede54c0', NULL, 'ادخلوها بسلم ذلك يوم الخلود', 26, 52, 208, 1, 7, 519, false, NULL),
    (4665, 'tanzil-uthmani-v1.1', 50, 35, 'لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ', '2a9d010d4c761b6131ff353fe0ef6084dcd1b1ddabba2e3e81e164dd72fdc48f', 'لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ', '2a9d010d4c761b6131ff353fe0ef6084dcd1b1ddabba2e3e81e164dd72fdc48f', '2a9d010d4c761b6131ff353fe0ef6084dcd1b1ddabba2e3e81e164dd72fdc48f', NULL, 'لهم ما يشاءون فيها ولدينا مزيد', 26, 52, 208, 1, 7, 519, false, NULL),
    (4666, 'tanzil-uthmani-v1.1', 50, 36, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَشَدُّ مِنْهُم بَطْشًا فَنَقَّبُوا۟ فِى ٱلْبِلَٰدِ هَلْ مِن مَّحِيصٍ', '236d15a8e0470a6b641e89def520d6d013759779d4f61b493529a10fba320bfd', 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَشَدُّ مِنْهُم بَطْشًا فَنَقَّبُوا۟ فِى ٱلْبِلَٰدِ هَلْ مِن مَّحِيصٍ', '236d15a8e0470a6b641e89def520d6d013759779d4f61b493529a10fba320bfd', '236d15a8e0470a6b641e89def520d6d013759779d4f61b493529a10fba320bfd', NULL, 'وكم اهلكنا قبلهم من قرن هم اشد منهم بطشا فنقبوا في البلد هل من محيص', 26, 52, 208, 1, 7, 520, false, NULL),
    (4667, 'tanzil-uthmani-v1.1', 50, 37, 'إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِمَن كَانَ لَهُۥ قَلْبٌ أَوْ أَلْقَى ٱلسَّمْعَ وَهُوَ شَهِيدٌ', '9b451eb92baeaca3ed4ac79225faeeda71ff4b2edb88c239d157cc81fdf71b95', 'إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِمَن كَانَ لَهُۥ قَلْبٌ أَوْ أَلْقَى ٱلسَّمْعَ وَهُوَ شَهِيدٌ', '9b451eb92baeaca3ed4ac79225faeeda71ff4b2edb88c239d157cc81fdf71b95', '9b451eb92baeaca3ed4ac79225faeeda71ff4b2edb88c239d157cc81fdf71b95', NULL, 'ان في ذلك لذكري لمن كان له قلب او القي السمع وهو شهيد', 26, 52, 208, 1, 7, 520, false, NULL),
    (4668, 'tanzil-uthmani-v1.1', 50, 38, 'وَلَقَدْ خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِن لُّغُوبٍ', '0d34b58abb3dbdd03c0900f564d42d9aa87283857b0aa575bbdf879746e94f38', 'وَلَقَدْ خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ وَمَا مَسَّنَا مِن لُّغُوبٍ', '0d34b58abb3dbdd03c0900f564d42d9aa87283857b0aa575bbdf879746e94f38', '0d34b58abb3dbdd03c0900f564d42d9aa87283857b0aa575bbdf879746e94f38', NULL, 'ولقد خلقنا السموت والارض وما بينهما في سته ايام وما مسنا من لغوب', 26, 52, 208, 1, 7, 520, false, NULL),
    (4669, 'tanzil-uthmani-v1.1', 50, 39, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ ٱلْغُرُوبِ', 'c0581e7f3cb67d5d8e480ce0d0ba0b1b1c9b173b180c781f8f697108ab8c9a7a', 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ ٱلْغُرُوبِ', 'c0581e7f3cb67d5d8e480ce0d0ba0b1b1c9b173b180c781f8f697108ab8c9a7a', 'c0581e7f3cb67d5d8e480ce0d0ba0b1b1c9b173b180c781f8f697108ab8c9a7a', NULL, 'فاصبر علي ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب', 26, 52, 208, 1, 7, 520, false, NULL),
