    (4811, 'tanzil-uthmani-v1.1', 53, 27, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ لَيُسَمُّونَ ٱلْمَلَٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ', '516c4278d5a28eb82195e971c7d876acc69a47ca63d94750d082a7cb9e3b3c2b', 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ لَيُسَمُّونَ ٱلْمَلَٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ', '516c4278d5a28eb82195e971c7d876acc69a47ca63d94750d082a7cb9e3b3c2b', '516c4278d5a28eb82195e971c7d876acc69a47ca63d94750d082a7cb9e3b3c2b', NULL, 'ان الذين لا يؤمنون بالاخره ليسمون الملئكه تسميه الانثي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4812, 'tanzil-uthmani-v1.1', 53, 28, 'وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا', 'dc3c2541c3ba474f2a9dc9121960f8fd8c5abdfa1e6f0a1b2d1ac5c21a5fecc7', 'وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا', 'dc3c2541c3ba474f2a9dc9121960f8fd8c5abdfa1e6f0a1b2d1ac5c21a5fecc7', 'dc3c2541c3ba474f2a9dc9121960f8fd8c5abdfa1e6f0a1b2d1ac5c21a5fecc7', NULL, 'وما لهم به من علم ان يتبعون الا الظن وان الظن لا يغني من الحق شيا', 27, 53, 211, 1, 7, 527, false, NULL),
    (4813, 'tanzil-uthmani-v1.1', 53, 29, 'فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا', '85e0f687988b7e9edd00bc65d226c77c2b887e2cef33139a8eaecb8c3136748a', 'فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا', '85e0f687988b7e9edd00bc65d226c77c2b887e2cef33139a8eaecb8c3136748a', '85e0f687988b7e9edd00bc65d226c77c2b887e2cef33139a8eaecb8c3136748a', NULL, 'فاعرض عن من تولي عن ذكرنا ولم يرد الا الحيوه الدنيا', 27, 53, 211, 1, 7, 527, false, NULL),
    (4814, 'tanzil-uthmani-v1.1', 53, 30, 'ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ', 'a55da12489d417c57fd40a5a4dde471314eacbec67ca1a22bec2bb502ea2831b', 'ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ', 'a55da12489d417c57fd40a5a4dde471314eacbec67ca1a22bec2bb502ea2831b', 'a55da12489d417c57fd40a5a4dde471314eacbec67ca1a22bec2bb502ea2831b', NULL, 'ذلك مبلغهم من العلم ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بمن اهتدي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4815, 'tanzil-uthmani-v1.1', 53, 31, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى', 'f398390c2e370fe7d1f1bc562bf45301476c48719dcc81d3bfeb022687a3d4c1', 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى', 'f398390c2e370fe7d1f1bc562bf45301476c48719dcc81d3bfeb022687a3d4c1', 'f398390c2e370fe7d1f1bc562bf45301476c48719dcc81d3bfeb022687a3d4c1', NULL, 'ولله ما في السموت وما في الارض ليجزي الذين اسوا بما عملوا ويجزي الذين احسنوا بالحسني', 27, 53, 211, 1, 7, 527, false, NULL),
    (4816, 'tanzil-uthmani-v1.1', 53, 32, 'ٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌ فِى بُطُونِ أُمَّهَٰتِكُمْ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ', '07527d8cb5570092b45d772d96067894904a9aa924d55f3b61e2413cec4df7c9', 'ٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌ فِى بُطُونِ أُمَّهَٰتِكُمْ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ', '07527d8cb5570092b45d772d96067894904a9aa924d55f3b61e2413cec4df7c9', '07527d8cb5570092b45d772d96067894904a9aa924d55f3b61e2413cec4df7c9', NULL, 'الذين يجتنبون كبئر الاثم والفوحش الا اللمم ان ربك وسع المغفره هو اعلم بكم اذ انشاكم من الارض واذ انتم اجنه في بطون امهتكم فلا تزكوا انفسكم هو اعلم بمن اتقي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4817, 'tanzil-uthmani-v1.1', 53, 33, 'أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ', '9373a270d97ce9e52fa18cb2ff5c7a761c2689601fae0bf16a55d7b62f3a5a07', 'أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ', '9373a270d97ce9e52fa18cb2ff5c7a761c2689601fae0bf16a55d7b62f3a5a07', '9373a270d97ce9e52fa18cb2ff5c7a761c2689601fae0bf16a55d7b62f3a5a07', NULL, 'افرءيت الذي تولي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4818, 'tanzil-uthmani-v1.1', 53, 34, 'وَأَعْطَىٰ قَلِيلًا وَأَكْدَىٰٓ', '7c39d6e23fedfab911cb80ea6bc5044a3795299f9bb115d3c5f8120a782fde06', 'وَأَعْطَىٰ قَلِيلًا وَأَكْدَىٰٓ', '7c39d6e23fedfab911cb80ea6bc5044a3795299f9bb115d3c5f8120a782fde06', '7c39d6e23fedfab911cb80ea6bc5044a3795299f9bb115d3c5f8120a782fde06', NULL, 'واعطي قليلا واكدي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4819, 'tanzil-uthmani-v1.1', 53, 35, 'أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ', 'da98a3fae9f8e3f5121f686890784989dfb7cdde243b026642f84ffdfee71137', 'أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ', 'da98a3fae9f8e3f5121f686890784989dfb7cdde243b026642f84ffdfee71137', 'da98a3fae9f8e3f5121f686890784989dfb7cdde243b026642f84ffdfee71137', NULL, 'اعنده علم الغيب فهو يري', 27, 53, 211, 1, 7, 527, false, NULL),
    (4820, 'tanzil-uthmani-v1.1', 53, 36, 'أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ', '9ab4c34beb998fb7986df9c22f63391c2379188febd08b392705b38361e7cd55', 'أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ', '9ab4c34beb998fb7986df9c22f63391c2379188febd08b392705b38361e7cd55', '9ab4c34beb998fb7986df9c22f63391c2379188febd08b392705b38361e7cd55', NULL, 'ام لم ينبا بما في صحف موسي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4821, 'tanzil-uthmani-v1.1', 53, 37, 'وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ', 'f21198b24dfe1dd5d64384cec3ac02ef3e44188d75ae5d685d93f718a646e22d', 'وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ', 'f21198b24dfe1dd5d64384cec3ac02ef3e44188d75ae5d685d93f718a646e22d', 'f21198b24dfe1dd5d64384cec3ac02ef3e44188d75ae5d685d93f718a646e22d', NULL, 'وابرهيم الذي وفي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4822, 'tanzil-uthmani-v1.1', 53, 38, 'أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ', 'e106032ce8783dbf2df097cd9d79dfedf1ed4f9e2aad65e6e30044ad80fe2b19', 'أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ', 'e106032ce8783dbf2df097cd9d79dfedf1ed4f9e2aad65e6e30044ad80fe2b19', 'e106032ce8783dbf2df097cd9d79dfedf1ed4f9e2aad65e6e30044ad80fe2b19', NULL, 'الا تزر وازره وزر اخري', 27, 53, 211, 1, 7, 527, false, NULL),
    (4823, 'tanzil-uthmani-v1.1', 53, 39, 'وَأَن لَّيْسَ لِلْإِنسَٰنِ إِلَّا مَا سَعَىٰ', '72723f0a370c1a5dc9aab0f1346a1efecd546869196d5c1db1c8dd561436ce70', 'وَأَن لَّيْسَ لِلْإِنسَٰنِ إِلَّا مَا سَعَىٰ', '72723f0a370c1a5dc9aab0f1346a1efecd546869196d5c1db1c8dd561436ce70', '72723f0a370c1a5dc9aab0f1346a1efecd546869196d5c1db1c8dd561436ce70', NULL, 'وان ليس للانسن الا ما سعي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4824, 'tanzil-uthmani-v1.1', 53, 40, 'وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ', '3a1ca82a9c14f290f0f9aff838bc879a42b76a076df2f160041fee51a4c1f761', 'وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ', '3a1ca82a9c14f290f0f9aff838bc879a42b76a076df2f160041fee51a4c1f761', '3a1ca82a9c14f290f0f9aff838bc879a42b76a076df2f160041fee51a4c1f761', NULL, 'وان سعيه سوف يري', 27, 53, 211, 1, 7, 527, false, NULL),
    (4825, 'tanzil-uthmani-v1.1', 53, 41, 'ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ', '21d3f0982a349606ceedcebddc15189d3871301d67a634b6bcb0cfa0cee4bc78', 'ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ', '21d3f0982a349606ceedcebddc15189d3871301d67a634b6bcb0cfa0cee4bc78', '21d3f0982a349606ceedcebddc15189d3871301d67a634b6bcb0cfa0cee4bc78', NULL, 'ثم يجزيه الجزاء الاوفي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4826, 'tanzil-uthmani-v1.1', 53, 42, 'وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ', '14b84a787245a83626ef2caae93c2ac2139878b0e27539480ab596e77d6701b2', 'وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ', '14b84a787245a83626ef2caae93c2ac2139878b0e27539480ab596e77d6701b2', '14b84a787245a83626ef2caae93c2ac2139878b0e27539480ab596e77d6701b2', NULL, 'وان الي ربك المنتهي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4827, 'tanzil-uthmani-v1.1', 53, 43, 'وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ', '83b7c9037037ffab948f39748a8f4fe7a23432a5f52dcd6294f9b557bb10a33b', 'وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ', '83b7c9037037ffab948f39748a8f4fe7a23432a5f52dcd6294f9b557bb10a33b', '83b7c9037037ffab948f39748a8f4fe7a23432a5f52dcd6294f9b557bb10a33b', NULL, 'وانه هو اضحك وابكي', 27, 53, 211, 1, 7, 527, false, NULL),
    (4828, 'tanzil-uthmani-v1.1', 53, 44, 'وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا', 'fdabbf190b6c338a04b7430b977472dbf3942050ce45e4ea4653f770b44a8cfb', 'وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا', 'fdabbf190b6c338a04b7430b977472dbf3942050ce45e4ea4653f770b44a8cfb', 'fdabbf190b6c338a04b7430b977472dbf3942050ce45e4ea4653f770b44a8cfb', NULL, 'وانه هو امات واحيا', 27, 53, 211, 1, 7, 527, false, NULL),
