    (5077, 'tanzil-uthmani-v1.1', 57, 2, 'لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُحْىِۦ وَيُمِيتُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'dbb2aff1251b1152facc4c3833d8f90fec601a22214c1c250bbdf3cdaaa35d38', 'لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُحْىِۦ وَيُمِيتُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'dbb2aff1251b1152facc4c3833d8f90fec601a22214c1c250bbdf3cdaaa35d38', 'dbb2aff1251b1152facc4c3833d8f90fec601a22214c1c250bbdf3cdaaa35d38', NULL, 'له ملك السموت والارض يحي ويميت وهو علي كل شيء قدير', 27, 54, 215, 1, 7, 537, false, NULL),
    (5078, 'tanzil-uthmani-v1.1', 57, 3, 'هُوَ ٱلْأَوَّلُ وَٱلْـَٔاخِرُ وَٱلظَّٰهِرُ وَٱلْبَاطِنُ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '06466666df2c92bf80b6e6496210d144e7c25b319391214e1ec3f1a1d1f49874', 'هُوَ ٱلْأَوَّلُ وَٱلْـَٔاخِرُ وَٱلظَّٰهِرُ وَٱلْبَاطِنُ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', '06466666df2c92bf80b6e6496210d144e7c25b319391214e1ec3f1a1d1f49874', '06466666df2c92bf80b6e6496210d144e7c25b319391214e1ec3f1a1d1f49874', NULL, 'هو الاول والاخر والظهر والباطن وهو بكل شيء عليم', 27, 54, 215, 1, 7, 537, false, NULL),
    (5079, 'tanzil-uthmani-v1.1', 57, 4, 'هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'a8ddc911bc4eae5b4e240007134d63b35a130d1314f406095643c5a9d77bfa4a', 'هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'a8ddc911bc4eae5b4e240007134d63b35a130d1314f406095643c5a9d77bfa4a', 'a8ddc911bc4eae5b4e240007134d63b35a130d1314f406095643c5a9d77bfa4a', NULL, 'هو الذي خلق السموت والارض في سته ايام ثم استوي علي العرش يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو معكم اين ما كنتم والله بما تعملون بصير', 27, 54, 215, 1, 7, 538, false, NULL),
    (5080, 'tanzil-uthmani-v1.1', 57, 5, 'لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '889d754758806fb91329d95d6425b349b4c04b37b3e2225a2cdaf1637bc22b24', 'لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '889d754758806fb91329d95d6425b349b4c04b37b3e2225a2cdaf1637bc22b24', '889d754758806fb91329d95d6425b349b4c04b37b3e2225a2cdaf1637bc22b24', NULL, 'له ملك السموت والارض والي الله ترجع الامور', 27, 54, 215, 1, 7, 538, false, NULL),
    (5081, 'tanzil-uthmani-v1.1', 57, 6, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '0ef52becbada5ab786c025141281f9b75adeae7705edcd8dc204cde5e78b2fdb', 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '0ef52becbada5ab786c025141281f9b75adeae7705edcd8dc204cde5e78b2fdb', '0ef52becbada5ab786c025141281f9b75adeae7705edcd8dc204cde5e78b2fdb', NULL, 'يولج اليل في النهار ويولج النهار في اليل وهو عليم بذات الصدور', 27, 54, 215, 1, 7, 538, false, NULL),
    (5082, 'tanzil-uthmani-v1.1', 57, 7, 'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌ كَبِيرٌ', 'cf781b364d113cec19b19057533bcd703bcf0b940b0c0f9f26551ede191ef114', 'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌ كَبِيرٌ', 'cf781b364d113cec19b19057533bcd703bcf0b940b0c0f9f26551ede191ef114', 'cf781b364d113cec19b19057533bcd703bcf0b940b0c0f9f26551ede191ef114', NULL, 'ءامنوا بالله ورسوله وانفقوا مما جعلكم مستخلفين فيه فالذين ءامنوا منكم وانفقوا لهم اجر كبير', 27, 54, 215, 1, 7, 538, false, NULL),
    (5083, 'tanzil-uthmani-v1.1', 57, 8, 'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'b963fe4f839f6552776c95828f828e6045fae705ebe962e142818bfdf0c0b9f9', 'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ', 'b963fe4f839f6552776c95828f828e6045fae705ebe962e142818bfdf0c0b9f9', 'b963fe4f839f6552776c95828f828e6045fae705ebe962e142818bfdf0c0b9f9', NULL, 'وما لكم لا تؤمنون بالله والرسول يدعوكم لتؤمنوا بربكم وقد اخذ ميثقكم ان كنتم مؤمنين', 27, 54, 215, 1, 7, 538, false, NULL),
    (5084, 'tanzil-uthmani-v1.1', 57, 9, 'هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَٰتٍۭ بَيِّنَٰتٍ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌ رَّحِيمٌ', '4af976e515d6d279509d5ae75ff837c317121d74d5f07a35eb5600d1741a11c1', 'هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَٰتٍۭ بَيِّنَٰتٍ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌ رَّحِيمٌ', '4af976e515d6d279509d5ae75ff837c317121d74d5f07a35eb5600d1741a11c1', '4af976e515d6d279509d5ae75ff837c317121d74d5f07a35eb5600d1741a11c1', NULL, 'هو الذي ينزل علي عبده ءايت بينت ليخرجكم من الظلمت الي النور وان الله بكم لرءوف رحيم', 27, 54, 215, 1, 7, 538, false, NULL),
    (5085, 'tanzil-uthmani-v1.1', 57, 10, 'وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَٰتَلَ أُو۟لَٰٓئِكَ أَعْظَمُ دَرَجَةً مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَٰتَلُوا۟ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '2f62e9c748c404a8f7066bca88ddf23e54832b7a92650e16f77dae23c291134f', 'وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَٰتَلَ أُو۟لَٰٓئِكَ أَعْظَمُ دَرَجَةً مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَٰتَلُوا۟ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '2f62e9c748c404a8f7066bca88ddf23e54832b7a92650e16f77dae23c291134f', '2f62e9c748c404a8f7066bca88ddf23e54832b7a92650e16f77dae23c291134f', NULL, 'وما لكم الا تنفقوا في سبيل الله ولله ميرث السموت والارض لا يستوي منكم من انفق من قبل الفتح وقتل اولئك اعظم درجه من الذين انفقوا من بعد وقتلوا وكلا وعد الله الحسني والله بما تعملون خبير', 27, 54, 215, 1, 7, 538, false, NULL),
    (5086, 'tanzil-uthmani-v1.1', 57, 11, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌ كَرِيمٌ', 'bdd294eb49e46cde03fe2ad3a40b63d4d3830dbc22f758e40ab4d1dd110a6b3a', 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌ كَرِيمٌ', 'bdd294eb49e46cde03fe2ad3a40b63d4d3830dbc22f758e40ab4d1dd110a6b3a', 'bdd294eb49e46cde03fe2ad3a40b63d4d3830dbc22f758e40ab4d1dd110a6b3a', NULL, 'من ذا الذي يقرض الله قرضا حسنا فيضعفه له وله اجر كريم', 27, 54, 215, 1, 7, 538, false, NULL),
    (5087, 'tanzil-uthmani-v1.1', 57, 12, 'يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '47da3931d28110a3fe2d51d520383e8a007cf7b67e65864fe105ed1f08557e1b', 'يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', '47da3931d28110a3fe2d51d520383e8a007cf7b67e65864fe105ed1f08557e1b', '47da3931d28110a3fe2d51d520383e8a007cf7b67e65864fe105ed1f08557e1b', NULL, 'يوم تري المؤمنين والمؤمنت يسعي نورهم بين ايديهم وبايمنهم بشريكم اليوم جنت تجري من تحتها الانهر خلدين فيها ذلك هو الفوز العظيم', 27, 54, 215, 1, 7, 539, false, NULL),
    (5088, 'tanzil-uthmani-v1.1', 57, 13, 'يَوْمَ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًا فَضُرِبَ بَيْنَهُم بِسُورٍ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ', '61f01122abb418c2093adf892de332e27d7c60f10a1db85599d69a0cc9ae0c96', 'يَوْمَ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًا فَضُرِبَ بَيْنَهُم بِسُورٍ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ', '61f01122abb418c2093adf892de332e27d7c60f10a1db85599d69a0cc9ae0c96', '61f01122abb418c2093adf892de332e27d7c60f10a1db85599d69a0cc9ae0c96', NULL, 'يوم يقول المنفقون والمنفقت للذين ءامنوا انظرونا نقتبس من نوركم قيل ارجعوا وراءكم فالتمسوا نورا فضرب بينهم بسور له باب باطنه فيه الرحمه وظهره من قبله العذاب', 27, 54, 215, 1, 7, 539, false, NULL),
    (5089, 'tanzil-uthmani-v1.1', 57, 14, 'يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ قَالُوا۟ بَلَىٰ وَلَٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'ad241dc261849141fc43e5ec8e7e33c0f305836375fcd3133b1912ce1279beca', 'يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ قَالُوا۟ بَلَىٰ وَلَٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ', 'ad241dc261849141fc43e5ec8e7e33c0f305836375fcd3133b1912ce1279beca', 'ad241dc261849141fc43e5ec8e7e33c0f305836375fcd3133b1912ce1279beca', NULL, 'ينادونهم الم نكن معكم قالوا بلي ولكنكم فتنتم انفسكم وتربصتم وارتبتم وغرتكم الاماني حتي جاء امر الله وغركم بالله الغرور', 27, 54, 215, 1, 7, 539, false, NULL),
    (5090, 'tanzil-uthmani-v1.1', 57, 15, 'فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ مَأْوَىٰكُمُ ٱلنَّارُ هِىَ مَوْلَىٰكُمْ وَبِئْسَ ٱلْمَصِيرُ', 'e2459e8a0f3fcfe52471bf45bd7c414eb40a8a4dac4bb4351bbd36e76767e3f3', 'فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ مَأْوَىٰكُمُ ٱلنَّارُ هِىَ مَوْلَىٰكُمْ وَبِئْسَ ٱلْمَصِيرُ', 'e2459e8a0f3fcfe52471bf45bd7c414eb40a8a4dac4bb4351bbd36e76767e3f3', 'e2459e8a0f3fcfe52471bf45bd7c414eb40a8a4dac4bb4351bbd36e76767e3f3', NULL, 'فاليوم لا يؤخذ منكم فديه ولا من الذين كفروا ماويكم النار هي موليكم وبئس المصير', 27, 54, 215, 1, 7, 539, false, NULL),
    (5091, 'tanzil-uthmani-v1.1', 57, 16, 'أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', '8b483db692d7d15039889dd7225f22f97dcdd42ddb485ef7137bc352eca037a6', 'أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', '8b483db692d7d15039889dd7225f22f97dcdd42ddb485ef7137bc352eca037a6', '8b483db692d7d15039889dd7225f22f97dcdd42ddb485ef7137bc352eca037a6', NULL, 'الم يان للذين ءامنوا ان تخشع قلوبهم لذكر الله وما نزل من الحق ولا يكونوا كالذين اوتوا الكتب من قبل فطال عليهم الامد فقست قلوبهم وكثير منهم فسقون', 27, 54, 216, 1, 7, 539, false, NULL),
    (5092, 'tanzil-uthmani-v1.1', 57, 17, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', '700b39c7ff52fa63a7acd7b904586293df47eba43e057204aa026c1da6af63a9', 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', '700b39c7ff52fa63a7acd7b904586293df47eba43e057204aa026c1da6af63a9', '700b39c7ff52fa63a7acd7b904586293df47eba43e057204aa026c1da6af63a9', NULL, 'اعلموا ان الله يحي الارض بعد موتها قد بينا لكم الايت لعلكم تعقلون', 27, 54, 216, 1, 7, 539, false, NULL),
    (5093, 'tanzil-uthmani-v1.1', 57, 18, 'إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ', 'e8760b7148ea148d4a820112b6d4c7968f97aa54ae5f80ede3591d8cbb42b814', 'إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ', 'e8760b7148ea148d4a820112b6d4c7968f97aa54ae5f80ede3591d8cbb42b814', 'e8760b7148ea148d4a820112b6d4c7968f97aa54ae5f80ede3591d8cbb42b814', NULL, 'ان المصدقين والمصدقت واقرضوا الله قرضا حسنا يضعف لهم ولهم اجر كريم', 27, 54, 216, 1, 7, 539, false, NULL),
    (5094, 'tanzil-uthmani-v1.1', 57, 19, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'cdd110251a86e44ac921844fc605b3c9b46ff77f9e905931c63a035645e5a57c', 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 'cdd110251a86e44ac921844fc605b3c9b46ff77f9e905931c63a035645e5a57c', 'cdd110251a86e44ac921844fc605b3c9b46ff77f9e905931c63a035645e5a57c', NULL, 'والذين ءامنوا بالله ورسله اولئك هم الصديقون والشهداء عند ربهم لهم اجرهم ونورهم والذين كفروا وكذبوا بايتنا اولئك اصحب الجحيم', 27, 54, 216, 1, 7, 540, false, NULL),
    (5095, 'tanzil-uthmani-v1.1', 57, 20, 'ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطَٰمًا وَفِى ٱلْـَٔاخِرَةِ عَذَابٌ شَدِيدٌ وَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرِضْوَٰنٌ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', '7474951c62cd879acfaaa828feee8a689f050523dc5e9be2782f77bf9a3d0bf3', 'ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطَٰمًا وَفِى ٱلْـَٔاخِرَةِ عَذَابٌ شَدِيدٌ وَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرِضْوَٰنٌ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', '7474951c62cd879acfaaa828feee8a689f050523dc5e9be2782f77bf9a3d0bf3', '7474951c62cd879acfaaa828feee8a689f050523dc5e9be2782f77bf9a3d0bf3', NULL, 'اعلموا انما الحيوه الدنيا لعب ولهو وزينه وتفاخر بينكم وتكاثر في الامول والاولد كمثل غيث اعجب الكفار نباته ثم يهيج فتريه مصفرا ثم يكون حطما وفي الاخره عذاب شديد ومغفره من الله ورضون وما الحيوه الدنيا الا متع الغرور', 27, 54, 216, 1, 7, 540, false, NULL),
    (5096, 'tanzil-uthmani-v1.1', 57, 21, 'سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'dad2b17ef74b1972762a534bebeab25b3724c60df69b496d3d137829928b4c38', 'سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'dad2b17ef74b1972762a534bebeab25b3724c60df69b496d3d137829928b4c38', 'dad2b17ef74b1972762a534bebeab25b3724c60df69b496d3d137829928b4c38', NULL, 'سابقوا الي مغفره من ربكم وجنه عرضها كعرض السماء والارض اعدت للذين ءامنوا بالله ورسله ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم', 27, 54, 216, 1, 7, 540, false, NULL),
    (5097, 'tanzil-uthmani-v1.1', 57, 22, 'مَآ أَصَابَ مِن مُّصِيبَةٍ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَٰبٍ مِّن قَبْلِ أَن نَّبْرَأَهَآ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '9cf6b5627efdb237e89a3b4e0b9d1e5f1d7d0fc24ad658211fa72119a0ddd7b2', 'مَآ أَصَابَ مِن مُّصِيبَةٍ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَٰبٍ مِّن قَبْلِ أَن نَّبْرَأَهَآ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '9cf6b5627efdb237e89a3b4e0b9d1e5f1d7d0fc24ad658211fa72119a0ddd7b2', '9cf6b5627efdb237e89a3b4e0b9d1e5f1d7d0fc24ad658211fa72119a0ddd7b2', NULL, 'ما اصاب من مصيبه في الارض ولا في انفسكم الا في كتب من قبل ان نبراها ان ذلك علي الله يسير', 27, 54, 216, 1, 7, 540, false, NULL),
    (5098, 'tanzil-uthmani-v1.1', 57, 23, 'لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', '54fa04a1a11355f50e1e8cc1af8ea8c193bd34b9b83beb0ea268d9ae47b0a8e2', 'لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', '54fa04a1a11355f50e1e8cc1af8ea8c193bd34b9b83beb0ea268d9ae47b0a8e2', '54fa04a1a11355f50e1e8cc1af8ea8c193bd34b9b83beb0ea268d9ae47b0a8e2', NULL, 'لكيلا تاسوا علي ما فاتكم ولا تفرحوا بما ءاتيكم والله لا يحب كل مختال فخور', 27, 54, 216, 1, 7, 540, false, NULL),
    (5099, 'tanzil-uthmani-v1.1', 57, 24, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '7c2d67f869f2c6b2b8dfecf1c9be7082f697da4523ec3d6b17f7ddedb3329bf6', 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '7c2d67f869f2c6b2b8dfecf1c9be7082f697da4523ec3d6b17f7ddedb3329bf6', '7c2d67f869f2c6b2b8dfecf1c9be7082f697da4523ec3d6b17f7ddedb3329bf6', NULL, 'الذين يبخلون ويامرون الناس بالبخل ومن يتول فان الله هو الغني الحميد', 27, 54, 216, 1, 7, 540, false, NULL),
    (5100, 'tanzil-uthmani-v1.1', 57, 25, 'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', '2d5eb098f12c183ab5e6b2f608e156e449aabca8f880aaaca6f2252e56944a20', 'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', '2d5eb098f12c183ab5e6b2f608e156e449aabca8f880aaaca6f2252e56944a20', '2d5eb098f12c183ab5e6b2f608e156e449aabca8f880aaaca6f2252e56944a20', NULL, 'لقد ارسلنا رسلنا بالبينت وانزلنا معهم الكتب والميزان ليقوم الناس بالقسط وانزلنا الحديد فيه باس شديد ومنفع للناس وليعلم الله من ينصره ورسله بالغيب ان الله قوي عزيز', 27, 54, 216, 1, 7, 541, false, NULL),
    (5101, 'tanzil-uthmani-v1.1', 57, 26, 'وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ فَمِنْهُم مُّهْتَدٍ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', '31ac47dbabde724513e92030446dedae1898df33b467af4b693e89fb026f6a53', 'وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ فَمِنْهُم مُّهْتَدٍ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', '31ac47dbabde724513e92030446dedae1898df33b467af4b693e89fb026f6a53', '31ac47dbabde724513e92030446dedae1898df33b467af4b693e89fb026f6a53', NULL, 'ولقد ارسلنا نوحا وابرهيم وجعلنا في ذريتهما النبوه والكتب فمنهم مهتد وكثير منهم فسقون', 27, 54, 216, 1, 7, 541, false, NULL),
    (5102, 'tanzil-uthmani-v1.1', 57, 27, 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةً وَرَحْمَةً وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', 'aae3e897b575c8f61a2a2579a522e7f1f9bf270ee56d428091462a543f19231d', 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةً وَرَحْمَةً وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ وَكَثِيرٌ مِّنْهُمْ فَٰسِقُونَ', 'aae3e897b575c8f61a2a2579a522e7f1f9bf270ee56d428091462a543f19231d', 'aae3e897b575c8f61a2a2579a522e7f1f9bf270ee56d428091462a543f19231d', NULL, 'ثم قفينا علي ءاثرهم برسلنا وقفينا بعيسي ابن مريم وءاتينه الانجيل وجعلنا في قلوب الذين اتبعوه رافه ورحمه ورهبانيه ابتدعوها ما كتبنها عليهم الا ابتغاء رضون الله فما رعوها حق رعايتها فاتينا الذين ءامنوا منهم اجرهم وكثير منهم فسقون', 27, 54, 216, 1, 7, 541, false, NULL),
    (5103, 'tanzil-uthmani-v1.1', 57, 28, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '8c021846b167a12b94d6dab897be5ce31cf9e00d137a9f5e48dacc9622320983', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '8c021846b167a12b94d6dab897be5ce31cf9e00d137a9f5e48dacc9622320983', '8c021846b167a12b94d6dab897be5ce31cf9e00d137a9f5e48dacc9622320983', NULL, 'يايها الذين ءامنوا اتقوا الله وءامنوا برسوله يؤتكم كفلين من رحمته ويجعل لكم نورا تمشون به ويغفر لكم والله غفور رحيم', 27, 54, 216, 1, 7, 541, false, NULL),
    (5104, 'tanzil-uthmani-v1.1', 57, 29, 'لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّن فَضْلِ ٱللَّهِ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '2b99df266d9d9c20421b825d1b69d9b7103352a08fd24a8b9d86c0340331b550', 'لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّن فَضْلِ ٱللَّهِ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', '2b99df266d9d9c20421b825d1b69d9b7103352a08fd24a8b9d86c0340331b550', '2b99df266d9d9c20421b825d1b69d9b7103352a08fd24a8b9d86c0340331b550', NULL, 'لئلا يعلم اهل الكتب الا يقدرون علي شيء من فضل الله وان الفضل بيد الله يؤتيه من يشاء والله ذو الفضل العظيم', 27, 54, 216, 1, 7, 541, false, NULL),
    (5105, 'tanzil-uthmani-v1.1', 58, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', '8376efd8a7f0712993cad3794654895010a3a938b75bb780f5f233b31cf69bb1', 'قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 'e84d00fcbde50e08d6470686795dff4927153b47b5ba56e1a8088d512507ccb0', 'e84d00fcbde50e08d6470686795dff4927153b47b5ba56e1a8088d512507ccb0', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'قد سمع الله قول التي تجدلك في زوجها وتشتكي الي الله والله يسمع تحاوركما ان الله سميع بصير', 28, 55, 217, 1, 7, 542, false, NULL),
    (5106, 'tanzil-uthmani-v1.1', 58, 2, 'ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمْ إِنْ أُمَّهَٰتُهُمْ إِلَّا ٱلَّٰٓـِٔى وَلَدْنَهُمْ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًا مِّنَ ٱلْقَوْلِ وَزُورًا وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', '21ca27f572af380e216f3d400ddd2ee7402fd6eb72f88946ee7627727b4e6524', 'ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمْ إِنْ أُمَّهَٰتُهُمْ إِلَّا ٱلَّٰٓـِٔى وَلَدْنَهُمْ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًا مِّنَ ٱلْقَوْلِ وَزُورًا وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', '21ca27f572af380e216f3d400ddd2ee7402fd6eb72f88946ee7627727b4e6524', '21ca27f572af380e216f3d400ddd2ee7402fd6eb72f88946ee7627727b4e6524', NULL, 'الذين يظهرون منكم من نسائهم ما هن امهتهم ان امهتهم الا الي ولدنهم وانهم ليقولون منكرا من القول وزورا وان الله لعفو غفور', 28, 55, 217, 1, 7, 542, false, NULL),
    (5107, 'tanzil-uthmani-v1.1', 58, 3, 'وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍ مِّن قَبْلِ أَن يَتَمَآسَّا ذَٰلِكُمْ تُوعَظُونَ بِهِۦ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'bf8fb43437967d6b666e4e9a626f2c01fa8c8acbc8115010086384ae1e46d1c4', 'وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍ مِّن قَبْلِ أَن يَتَمَآسَّا ذَٰلِكُمْ تُوعَظُونَ بِهِۦ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'bf8fb43437967d6b666e4e9a626f2c01fa8c8acbc8115010086384ae1e46d1c4', 'bf8fb43437967d6b666e4e9a626f2c01fa8c8acbc8115010086384ae1e46d1c4', NULL, 'والذين يظهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبه من قبل ان يتماسا ذلكم توعظون به والله بما تعملون خبير', 28, 55, 217, 1, 7, 542, false, NULL),
    (5108, 'tanzil-uthmani-v1.1', 58, 4, 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتِلْكَ حُدُودُ ٱللَّهِ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ', '9b6aa9a822ed9820d5f8b0af2fa25a6b5ccff899863c94d8fb91dbfcb8bfb0bb', 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتِلْكَ حُدُودُ ٱللَّهِ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ', '9b6aa9a822ed9820d5f8b0af2fa25a6b5ccff899863c94d8fb91dbfcb8bfb0bb', '9b6aa9a822ed9820d5f8b0af2fa25a6b5ccff899863c94d8fb91dbfcb8bfb0bb', NULL, 'فمن لم يجد فصيام شهرين متتابعين من قبل ان يتماسا فمن لم يستطع فاطعام ستين مسكينا ذلك لتؤمنوا بالله ورسوله وتلك حدود الله وللكفرين عذاب اليم', 28, 55, 217, 1, 7, 542, false, NULL),
    (5109, 'tanzil-uthmani-v1.1', 58, 5, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ وَقَدْ أَنزَلْنَآ ءَايَٰتٍۭ بَيِّنَٰتٍ وَلِلْكَٰفِرِينَ عَذَابٌ مُّهِينٌ', 'fbd672dfaa736742054098cbb1c7f8b9e9e24cc0ac9cef5015d0340c6e519d18', 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ وَقَدْ أَنزَلْنَآ ءَايَٰتٍۭ بَيِّنَٰتٍ وَلِلْكَٰفِرِينَ عَذَابٌ مُّهِينٌ', 'fbd672dfaa736742054098cbb1c7f8b9e9e24cc0ac9cef5015d0340c6e519d18', 'fbd672dfaa736742054098cbb1c7f8b9e9e24cc0ac9cef5015d0340c6e519d18', NULL, 'ان الذين يحادون الله ورسوله كبتوا كما كبت الذين من قبلهم وقد انزلنا ءايت بينت وللكفرين عذاب مهين', 28, 55, 217, 1, 7, 542, false, NULL),
    (5110, 'tanzil-uthmani-v1.1', 58, 6, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'f3c9ab5aed39a866833b8e8200eb936df918154c62a7cd370e1375d6274fa22c', 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 'f3c9ab5aed39a866833b8e8200eb936df918154c62a7cd370e1375d6274fa22c', 'f3c9ab5aed39a866833b8e8200eb936df918154c62a7cd370e1375d6274fa22c', NULL, 'يوم يبعثهم الله جميعا فينبئهم بما عملوا احصيه الله ونسوه والله علي كل شيء شهيد', 28, 55, 217, 1, 7, 542, false, NULL),
    (5111, 'tanzil-uthmani-v1.1', 58, 7, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'a1f85e792562679ebf5008dadd57817326b5d2afb58d23f554ef7b8e258dd191', 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 'a1f85e792562679ebf5008dadd57817326b5d2afb58d23f554ef7b8e258dd191', 'a1f85e792562679ebf5008dadd57817326b5d2afb58d23f554ef7b8e258dd191', NULL, 'الم تر ان الله يعلم ما في السموت وما في الارض ما يكون من نجوي ثلثه الا هو رابعهم ولا خمسه الا هو سادسهم ولا ادني من ذلك ولا اكثر الا هو معهم اين ما كانوا ثم ينبئهم بما عملوا يوم القيمه ان الله بكل شيء عليم', 28, 55, 217, 1, 7, 543, false, NULL),
    (5112, 'tanzil-uthmani-v1.1', 58, 8, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا فَبِئْسَ ٱلْمَصِيرُ', 'e4bab2134134253edbd884206792fc121a29ee81c623df7c99f8889f75acfd12', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا فَبِئْسَ ٱلْمَصِيرُ', 'e4bab2134134253edbd884206792fc121a29ee81c623df7c99f8889f75acfd12', 'e4bab2134134253edbd884206792fc121a29ee81c623df7c99f8889f75acfd12', NULL, 'الم تر الي الذين نهوا عن النجوي ثم يعودون لما نهوا عنه ويتنجون بالاثم والعدون ومعصيت الرسول واذا جاءوك حيوك بما لم يحيك به الله ويقولون في انفسهم لولا يعذبنا الله بما نقول حسبهم جهنم يصلونها فبئس المصير', 28, 55, 217, 1, 7, 543, false, NULL),
    (5113, 'tanzil-uthmani-v1.1', 58, 9, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَٰجَيْتُمْ فَلَا تَتَنَٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', '15ed3828a1ccf6770960abbf0d5982b8283aa064704fe34e844379f584b9cf71', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَٰجَيْتُمْ فَلَا تَتَنَٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', '15ed3828a1ccf6770960abbf0d5982b8283aa064704fe34e844379f584b9cf71', '15ed3828a1ccf6770960abbf0d5982b8283aa064704fe34e844379f584b9cf71', NULL, 'يايها الذين ءامنوا اذا تنجيتم فلا تتنجوا بالاثم والعدون ومعصيت الرسول وتنجوا بالبر والتقوي واتقوا الله الذي اليه تحشرون', 28, 55, 217, 1, 7, 543, false, NULL),
    (5114, 'tanzil-uthmani-v1.1', 58, 10, 'إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'b6185c3624097fed2621ef7a0d849778617e9b18c410a22c49fe42ce186d5559', 'إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 'b6185c3624097fed2621ef7a0d849778617e9b18c410a22c49fe42ce186d5559', 'b6185c3624097fed2621ef7a0d849778617e9b18c410a22c49fe42ce186d5559', NULL, 'انما النجوي من الشيطن ليحزن الذين ءامنوا وليس بضارهم شيا الا باذن الله وعلي الله فليتوكل المؤمنون', 28, 55, 217, 1, 7, 543, false, NULL),
    (5115, 'tanzil-uthmani-v1.1', 58, 11, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '44dff7055422683b5d092a992d7283ce45bb04a1b3306e06a8c3e8a9d74e2670', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', '44dff7055422683b5d092a992d7283ce45bb04a1b3306e06a8c3e8a9d74e2670', '44dff7055422683b5d092a992d7283ce45bb04a1b3306e06a8c3e8a9d74e2670', NULL, 'يايها الذين ءامنوا اذا قيل لكم تفسحوا في المجلس فافسحوا يفسح الله لكم واذا قيل انشزوا فانشزوا يرفع الله الذين ءامنوا منكم والذين اوتوا العلم درجت والله بما تعملون خبير', 28, 55, 217, 1, 7, 543, false, NULL),
    (5116, 'tanzil-uthmani-v1.1', 58, 12, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةً ذَٰلِكَ خَيْرٌ لَّكُمْ وَأَطْهَرُ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'b7dee85e852dfca996b5d1c97a68f51d622f94e05fbaf82f59af04305611f1f4', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةً ذَٰلِكَ خَيْرٌ لَّكُمْ وَأَطْهَرُ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 'b7dee85e852dfca996b5d1c97a68f51d622f94e05fbaf82f59af04305611f1f4', 'b7dee85e852dfca996b5d1c97a68f51d622f94e05fbaf82f59af04305611f1f4', NULL, 'يايها الذين ءامنوا اذا نجيتم الرسول فقدموا بين يدي نجويكم صدقه ذلك خير لكم واطهر فان لم تجدوا فان الله غفور رحيم', 28, 55, 217, 1, 7, 544, false, NULL),
    (5117, 'tanzil-uthmani-v1.1', 58, 13, 'ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَٰتٍ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'e6f1011613e53b3af815c9d91adc7a3e610af5e83b85f349e34f517b146b92ed', 'ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَٰتٍ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'e6f1011613e53b3af815c9d91adc7a3e610af5e83b85f349e34f517b146b92ed', 'e6f1011613e53b3af815c9d91adc7a3e610af5e83b85f349e34f517b146b92ed', NULL, 'ءاشفقتم ان تقدموا بين يدي نجويكم صدقت فاذ لم تفعلوا وتاب الله عليكم فاقيموا الصلوه وءاتوا الزكوه واطيعوا الله ورسوله والله خبير بما تعملون', 28, 55, 217, 1, 7, 544, false, NULL),
    (5118, 'tanzil-uthmani-v1.1', 58, 14, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ', '3a6f2c185526b09954c533f58ae310bb2f70ab4f85d1e0ebd71482e9b6c16379', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ', '3a6f2c185526b09954c533f58ae310bb2f70ab4f85d1e0ebd71482e9b6c16379', '3a6f2c185526b09954c533f58ae310bb2f70ab4f85d1e0ebd71482e9b6c16379', NULL, 'الم تر الي الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون علي الكذب وهم يعلمون', 28, 55, 218, 1, 7, 544, false, NULL),
    (5119, 'tanzil-uthmani-v1.1', 58, 15, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', '7349c2557e7d4197c389b2e4e56e2f7d0397956a254ba0456b6fed5de238dc14', 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', '7349c2557e7d4197c389b2e4e56e2f7d0397956a254ba0456b6fed5de238dc14', '7349c2557e7d4197c389b2e4e56e2f7d0397956a254ba0456b6fed5de238dc14', NULL, 'اعد الله لهم عذابا شديدا انهم ساء ما كانوا يعملون', 28, 55, 218, 1, 7, 544, false, NULL),
    (5120, 'tanzil-uthmani-v1.1', 58, 16, 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ', 'c26999705b9c0422d56aa524b238cf501020cf6989dba0c806ba80e276f17913', 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ', 'c26999705b9c0422d56aa524b238cf501020cf6989dba0c806ba80e276f17913', 'c26999705b9c0422d56aa524b238cf501020cf6989dba0c806ba80e276f17913', NULL, 'اتخذوا ايمنهم جنه فصدوا عن سبيل الله فلهم عذاب مهين', 28, 55, 218, 1, 7, 544, false, NULL),
    (5121, 'tanzil-uthmani-v1.1', 58, 17, 'لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '894608b6b235c7d9d84b661a1bf1a1b1875f6bbdbf2c1a9d84f31af70bfa2100', 'لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ', '894608b6b235c7d9d84b661a1bf1a1b1875f6bbdbf2c1a9d84f31af70bfa2100', '894608b6b235c7d9d84b661a1bf1a1b1875f6bbdbf2c1a9d84f31af70bfa2100', NULL, 'لن تغني عنهم امولهم ولا اولدهم من الله شيا اولئك اصحب النار هم فيها خلدون', 28, 55, 218, 1, 7, 544, false, NULL),
    (5122, 'tanzil-uthmani-v1.1', 58, 18, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ أَلَآ إِنَّهُمْ هُمُ ٱلْكَٰذِبُونَ', '2352c0cd3827a1a6ed4c4cc918b087ab57310cc10314dad1e48ddf164e2aaa26', 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ أَلَآ إِنَّهُمْ هُمُ ٱلْكَٰذِبُونَ', '2352c0cd3827a1a6ed4c4cc918b087ab57310cc10314dad1e48ddf164e2aaa26', '2352c0cd3827a1a6ed4c4cc918b087ab57310cc10314dad1e48ddf164e2aaa26', NULL, 'يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم ويحسبون انهم علي شيء الا انهم هم الكذبون', 28, 55, 218, 1, 7, 544, false, NULL),
    (5123, 'tanzil-uthmani-v1.1', 58, 19, 'ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ أُو۟لَٰٓئِكَ حِزْبُ ٱلشَّيْطَٰنِ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَٰنِ هُمُ ٱلْخَٰسِرُونَ', 'd20890fd02e9d5fcd4a5468d88135a81dd44c8d125c9934deb6e4281de20cbe3', 'ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ أُو۟لَٰٓئِكَ حِزْبُ ٱلشَّيْطَٰنِ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَٰنِ هُمُ ٱلْخَٰسِرُونَ', 'd20890fd02e9d5fcd4a5468d88135a81dd44c8d125c9934deb6e4281de20cbe3', 'd20890fd02e9d5fcd4a5468d88135a81dd44c8d125c9934deb6e4281de20cbe3', NULL, 'استحوذ عليهم الشيطن فانسيهم ذكر الله اولئك حزب الشيطن الا ان حزب الشيطن هم الخسرون', 28, 55, 218, 1, 7, 544, false, NULL),
    (5124, 'tanzil-uthmani-v1.1', 58, 20, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ فِى ٱلْأَذَلِّينَ', '2e161ef0499dda0ee602fcc09b1b46d97dfd6d11f830504e807f05d54c214bd6', 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ فِى ٱلْأَذَلِّينَ', '2e161ef0499dda0ee602fcc09b1b46d97dfd6d11f830504e807f05d54c214bd6', '2e161ef0499dda0ee602fcc09b1b46d97dfd6d11f830504e807f05d54c214bd6', NULL, 'ان الذين يحادون الله ورسوله اولئك في الاذلين', 28, 55, 218, 1, 7, 544, false, NULL),
    (5125, 'tanzil-uthmani-v1.1', 58, 21, 'كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', '2a1a14a78573587ae922e4f1cea921dc4c7980478640935362b399a358ebbd8b', 'كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', '2a1a14a78573587ae922e4f1cea921dc4c7980478640935362b399a358ebbd8b', '2a1a14a78573587ae922e4f1cea921dc4c7980478640935362b399a358ebbd8b', NULL, 'كتب الله لاغلبن انا ورسلي ان الله قوي عزيز', 28, 55, 218, 1, 7, 544, false, NULL),
    (5126, 'tanzil-uthmani-v1.1', 58, 22, 'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ أُو۟لَٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَٰنَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ وَيُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ أُو۟لَٰٓئِكَ حِزْبُ ٱللَّهِ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ', '92a3e56c91b879c598a8ee3b9cf0a83015b5e51204bdca8f6209ddef33b1677b', 'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ أُو۟لَٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَٰنَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ وَيُدْخِلُهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ أُو۟لَٰٓئِكَ حِزْبُ ٱللَّهِ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ', '92a3e56c91b879c598a8ee3b9cf0a83015b5e51204bdca8f6209ddef33b1677b', '92a3e56c91b879c598a8ee3b9cf0a83015b5e51204bdca8f6209ddef33b1677b', NULL, 'لا تجد قوما يؤمنون بالله واليوم الاخر يوادون من حاد الله ورسوله ولو كانوا ءاباءهم او ابناءهم او اخونهم او عشيرتهم اولئك كتب في قلوبهم الايمن وايدهم بروح منه ويدخلهم جنت تجري من تحتها الانهر خلدين فيها رضي الله عنهم ورضوا عنه اولئك حزب الله الا ان حزب الله هم المفلحون', 28, 55, 218, 1, 7, 545, false, NULL),
    (5127, 'tanzil-uthmani-v1.1', 59, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'd17ce0deda2cdddadbdd4aac59c8dd351e369760f026b24b08c74bd50d07d60f', 'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '9dc6ef4a08d6b289f8051f9f58724086d9d923cb7c33a94f9a7a1b11aaf7fb42', '9dc6ef4a08d6b289f8051f9f58724086d9d923cb7c33a94f9a7a1b11aaf7fb42', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'سبح لله ما في السموت وما في الارض وهو العزيز الحكيم', 28, 55, 218, 1, 7, 545, false, NULL),
    (5128, 'tanzil-uthmani-v1.1', 59, 2, 'هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ مِن دِيَٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَٰٓأُو۟لِى ٱلْأَبْصَٰرِ', '83ac80fe3a35622f63b9f35e22086b8fb6c464511305d86d19abf620e7045307', 'هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ مِن دِيَٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَٰٓأُو۟لِى ٱلْأَبْصَٰرِ', '83ac80fe3a35622f63b9f35e22086b8fb6c464511305d86d19abf620e7045307', '83ac80fe3a35622f63b9f35e22086b8fb6c464511305d86d19abf620e7045307', NULL, 'هو الذي اخرج الذين كفروا من اهل الكتب من ديرهم لاول الحشر ما ظننتم ان يخرجوا وظنوا انهم مانعتهم حصونهم من الله فاتيهم الله من حيث لم يحتسبوا وقذف في قلوبهم الرعب يخربون بيوتهم بايديهم وايدي المؤمنين فاعتبروا ياولي الابصر', 28, 55, 218, 1, 7, 545, false, NULL),
    (5129, 'tanzil-uthmani-v1.1', 59, 3, 'وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابُ ٱلنَّارِ', '2f24fa20b2282811ae86e3200a8787e8f63415724b4689eca46470d6a6fad4eb', 'وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابُ ٱلنَّارِ', '2f24fa20b2282811ae86e3200a8787e8f63415724b4689eca46470d6a6fad4eb', '2f24fa20b2282811ae86e3200a8787e8f63415724b4689eca46470d6a6fad4eb', NULL, 'ولولا ان كتب الله عليهم الجلاء لعذبهم في الدنيا ولهم في الاخره عذاب النار', 28, 55, 218, 1, 7, 545, false, NULL),
    (5130, 'tanzil-uthmani-v1.1', 59, 4, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '01f079588ea060ce220e383551ec6a682cbf09effa14a723c4f5597145a974c2', 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', '01f079588ea060ce220e383551ec6a682cbf09effa14a723c4f5597145a974c2', '01f079588ea060ce220e383551ec6a682cbf09effa14a723c4f5597145a974c2', NULL, 'ذلك بانهم شاقوا الله ورسوله ومن يشاق الله فان الله شديد العقاب', 28, 55, 218, 1, 7, 546, false, NULL),
    (5131, 'tanzil-uthmani-v1.1', 59, 5, 'مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَٰسِقِينَ', '3b70a66908887700960501e4978a87302e2647575b2d567362854cb02aa1287e', 'مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَٰسِقِينَ', '3b70a66908887700960501e4978a87302e2647575b2d567362854cb02aa1287e', '3b70a66908887700960501e4978a87302e2647575b2d567362854cb02aa1287e', NULL, 'ما قطعتم من لينه او تركتموها قائمه علي اصولها فباذن الله وليخزي الفسقين', 28, 55, 218, 1, 7, 546, false, NULL),
    (5132, 'tanzil-uthmani-v1.1', 59, 6, 'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '3ac121b8f730404ba048a5afa40992d7d1ea90c0ef9d473933d1f74fccc903ec', 'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '3ac121b8f730404ba048a5afa40992d7d1ea90c0ef9d473933d1f74fccc903ec', '3ac121b8f730404ba048a5afa40992d7d1ea90c0ef9d473933d1f74fccc903ec', NULL, 'وما افاء الله علي رسوله منهم فما اوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله علي من يشاء والله علي كل شيء قدير', 28, 55, 218, 1, 7, 546, false, NULL),
    (5133, 'tanzil-uthmani-v1.1', 59, 7, 'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'b02a77783788e877c9a87a4b85374324c52399abe5d5363565b0822893f5748a', 'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 'b02a77783788e877c9a87a4b85374324c52399abe5d5363565b0822893f5748a', 'b02a77783788e877c9a87a4b85374324c52399abe5d5363565b0822893f5748a', NULL, 'ما افاء الله علي رسوله من اهل القري فلله وللرسول ولذي القربي واليتمي والمسكين وابن السبيل كي لا يكون دوله بين الاغنياء منكم وما ءاتيكم الرسول فخذوه وما نهيكم عنه فانتهوا واتقوا الله ان الله شديد العقاب', 28, 55, 218, 1, 7, 546, false, NULL),
    (5134, 'tanzil-uthmani-v1.1', 59, 8, 'لِلْفُقَرَآءِ ٱلْمُهَٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', '3bd83bfb57d52d03727bdb4282e05c43f0d9dd4c2fbdb40f53acec42f3c4e0eb', 'لِلْفُقَرَآءِ ٱلْمُهَٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', '3bd83bfb57d52d03727bdb4282e05c43f0d9dd4c2fbdb40f53acec42f3c4e0eb', '3bd83bfb57d52d03727bdb4282e05c43f0d9dd4c2fbdb40f53acec42f3c4e0eb', NULL, 'للفقراء المهجرين الذين اخرجوا من ديرهم وامولهم يبتغون فضلا من الله ورضونا وينصرون الله ورسوله اولئك هم الصدقون', 28, 55, 218, 1, 7, 546, false, NULL),
    (5135, 'tanzil-uthmani-v1.1', 59, 9, 'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةً مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '615234dcdc4cdf6485c62f54ee8aae94b638323467d9348f2b80bcd9cb6c4608', 'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةً مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', '615234dcdc4cdf6485c62f54ee8aae94b638323467d9348f2b80bcd9cb6c4608', '615234dcdc4cdf6485c62f54ee8aae94b638323467d9348f2b80bcd9cb6c4608', NULL, 'والذين تبوءو الدار والايمن من قبلهم يحبون من هاجر اليهم ولا يجدون في صدورهم حاجه مما اوتوا ويؤثرون علي انفسهم ولو كان بهم خصاصه ومن يوق شح نفسه فاولئك هم المفلحون', 28, 55, 218, 1, 7, 546, false, NULL),
    (5136, 'tanzil-uthmani-v1.1', 59, 10, 'وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌ رَّحِيمٌ', '81f01b7795e876b13b3d70c44fdd21467dbb8a3b55e6f7a8b8b3587086cc452e', 'وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌ رَّحِيمٌ', '81f01b7795e876b13b3d70c44fdd21467dbb8a3b55e6f7a8b8b3587086cc452e', '81f01b7795e876b13b3d70c44fdd21467dbb8a3b55e6f7a8b8b3587086cc452e', NULL, 'والذين جاءو من بعدهم يقولون ربنا اغفر لنا ولاخوننا الذين سبقونا بالايمن ولا تجعل في قلوبنا غلا للذين ءامنوا ربنا انك رءوف رحيم', 28, 55, 218, 1, 7, 547, false, NULL),
    (5137, 'tanzil-uthmani-v1.1', 59, 11, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', '03f49f3e4c6ad379490c410962121e9a7d1d2051f8101bbb7e94a75f99a67f6c', 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', '03f49f3e4c6ad379490c410962121e9a7d1d2051f8101bbb7e94a75f99a67f6c', '03f49f3e4c6ad379490c410962121e9a7d1d2051f8101bbb7e94a75f99a67f6c', NULL, 'الم تر الي الذين نافقوا يقولون لاخونهم الذين كفروا من اهل الكتب لئن اخرجتم لنخرجن معكم ولا نطيع فيكم احدا ابدا وان قوتلتم لننصرنكم والله يشهد انهم لكذبون', 28, 55, 219, 1, 7, 547, false, NULL),
    (5138, 'tanzil-uthmani-v1.1', 59, 12, 'لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَٰرَ ثُمَّ لَا يُنصَرُونَ', 'a5e9d7ee22e7f50b0564737a3277aaa9fed94bf1421da78e318bc5014645b320', 'لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَٰرَ ثُمَّ لَا يُنصَرُونَ', 'a5e9d7ee22e7f50b0564737a3277aaa9fed94bf1421da78e318bc5014645b320', 'a5e9d7ee22e7f50b0564737a3277aaa9fed94bf1421da78e318bc5014645b320', NULL, 'لئن اخرجوا لا يخرجون معهم ولئن قوتلوا لا ينصرونهم ولئن نصروهم ليولن الادبر ثم لا ينصرون', 28, 55, 219, 1, 7, 547, false, NULL),
    (5139, 'tanzil-uthmani-v1.1', 59, 13, 'لَأَنتُمْ أَشَدُّ رَهْبَةً فِى صُدُورِهِم مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', '9d595f21217475eab646679e6f1d360f3e54338b0d0cdcebbc113ce3de268344', 'لَأَنتُمْ أَشَدُّ رَهْبَةً فِى صُدُورِهِم مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', '9d595f21217475eab646679e6f1d360f3e54338b0d0cdcebbc113ce3de268344', '9d595f21217475eab646679e6f1d360f3e54338b0d0cdcebbc113ce3de268344', NULL, 'لانتم اشد رهبه في صدورهم من الله ذلك بانهم قوم لا يفقهون', 28, 55, 219, 1, 7, 547, false, NULL),
    (5140, 'tanzil-uthmani-v1.1', 59, 14, 'لَا يُقَٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ بَأْسُهُم بَيْنَهُمْ شَدِيدٌ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', '8cb63b0be3381b270c33c5684b961d839e79caecefef6a506011dd55b49b7350', 'لَا يُقَٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ بَأْسُهُم بَيْنَهُمْ شَدِيدٌ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', '8cb63b0be3381b270c33c5684b961d839e79caecefef6a506011dd55b49b7350', '8cb63b0be3381b270c33c5684b961d839e79caecefef6a506011dd55b49b7350', NULL, 'لا يقتلونكم جميعا الا في قري محصنه او من وراء جدر باسهم بينهم شديد تحسبهم جميعا وقلوبهم شتي ذلك بانهم قوم لا يعقلون', 28, 55, 219, 1, 7, 547, false, NULL),
    (5141, 'tanzil-uthmani-v1.1', 59, 15, 'كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًا ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'b0300873d146d88423330be59afda0e31f1a787538e6d8d74105d5918fc742a7', 'كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًا ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 'b0300873d146d88423330be59afda0e31f1a787538e6d8d74105d5918fc742a7', 'b0300873d146d88423330be59afda0e31f1a787538e6d8d74105d5918fc742a7', NULL, 'كمثل الذين من قبلهم قريبا ذاقوا وبال امرهم ولهم عذاب اليم', 28, 55, 219, 1, 7, 547, false, NULL),
    (5142, 'tanzil-uthmani-v1.1', 59, 16, 'كَمَثَلِ ٱلشَّيْطَٰنِ إِذْ قَالَ لِلْإِنسَٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', 'f936bddf7ce7973eb611465253b48f0687a657c0003b96c26f16b02e516b992f', 'كَمَثَلِ ٱلشَّيْطَٰنِ إِذْ قَالَ لِلْإِنسَٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', 'f936bddf7ce7973eb611465253b48f0687a657c0003b96c26f16b02e516b992f', 'f936bddf7ce7973eb611465253b48f0687a657c0003b96c26f16b02e516b992f', NULL, 'كمثل الشيطن اذ قال للانسن اكفر فلما كفر قال اني بريء منك اني اخاف الله رب العلمين', 28, 55, 219, 1, 7, 547, false, NULL),
    (5143, 'tanzil-uthmani-v1.1', 59, 17, 'فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَٰلِدَيْنِ فِيهَا وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', '58d1c76dece6ece5a26d02dd2cb556d21ebff5cdbf136309a2aaaab56da732e3', 'فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَٰلِدَيْنِ فِيهَا وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', '58d1c76dece6ece5a26d02dd2cb556d21ebff5cdbf136309a2aaaab56da732e3', '58d1c76dece6ece5a26d02dd2cb556d21ebff5cdbf136309a2aaaab56da732e3', NULL, 'فكان عقبتهما انهما في النار خلدين فيها وذلك جزؤا الظلمين', 28, 55, 219, 1, 7, 548, false, NULL),
    (5144, 'tanzil-uthmani-v1.1', 59, 18, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'c7972aa41179ec5295a6522a045293e8ddbd24f671bf8b4a7699cfe6d6c11a63', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ وَٱتَّقُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 'c7972aa41179ec5295a6522a045293e8ddbd24f671bf8b4a7699cfe6d6c11a63', 'c7972aa41179ec5295a6522a045293e8ddbd24f671bf8b4a7699cfe6d6c11a63', NULL, 'يايها الذين ءامنوا اتقوا الله ولتنظر نفس ما قدمت لغد واتقوا الله ان الله خبير بما تعملون', 28, 55, 219, 1, 7, 548, false, NULL),
    (5145, 'tanzil-uthmani-v1.1', 59, 19, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ أُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'fdcba593c2c80fd075ca12b80a5faae2721ef0e60ca4b0dbebac22d78305ac61', 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ أُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 'fdcba593c2c80fd075ca12b80a5faae2721ef0e60ca4b0dbebac22d78305ac61', 'fdcba593c2c80fd075ca12b80a5faae2721ef0e60ca4b0dbebac22d78305ac61', NULL, 'ولا تكونوا كالذين نسوا الله فانسيهم انفسهم اولئك هم الفسقون', 28, 55, 219, 1, 7, 548, false, NULL),
    (5146, 'tanzil-uthmani-v1.1', 59, 20, 'لَا يَسْتَوِىٓ أَصْحَٰبُ ٱلنَّارِ وَأَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ', 'b44befa4c121a207e2dc5595d2b6c274071fa886bf51e6a44b28acd0303a220e', 'لَا يَسْتَوِىٓ أَصْحَٰبُ ٱلنَّارِ وَأَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ', 'b44befa4c121a207e2dc5595d2b6c274071fa886bf51e6a44b28acd0303a220e', 'b44befa4c121a207e2dc5595d2b6c274071fa886bf51e6a44b28acd0303a220e', NULL, 'لا يستوي اصحب النار واصحب الجنه اصحب الجنه هم الفائزون', 28, 55, 219, 1, 7, 548, false, NULL),
    (5147, 'tanzil-uthmani-v1.1', 59, 21, 'لَوْ أَنزَلْنَا هَٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُۥ خَٰشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ ٱللَّهِ وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', '21eb6f7c8c95e44bd1639c062494674c288bdda082d68ceaae4227f01025c4a9', 'لَوْ أَنزَلْنَا هَٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُۥ خَٰشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ ٱللَّهِ وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', '21eb6f7c8c95e44bd1639c062494674c288bdda082d68ceaae4227f01025c4a9', '21eb6f7c8c95e44bd1639c062494674c288bdda082d68ceaae4227f01025c4a9', NULL, 'لو انزلنا هذا القرءان علي جبل لرايته خشعا متصدعا من خشيه الله وتلك الامثل نضربها للناس لعلهم يتفكرون', 28, 55, 219, 1, 7, 548, false, NULL),
    (5148, 'tanzil-uthmani-v1.1', 59, 22, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', '0c17777fe6d491e19728efdc6a3fd90085dcaf57b0c79cae64094430d97019f6', 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', '0c17777fe6d491e19728efdc6a3fd90085dcaf57b0c79cae64094430d97019f6', '0c17777fe6d491e19728efdc6a3fd90085dcaf57b0c79cae64094430d97019f6', NULL, 'هو الله الذي لا اله الا هو علم الغيب والشهده هو الرحمن الرحيم', 28, 55, 219, 1, 7, 548, false, NULL),
    (5149, 'tanzil-uthmani-v1.1', 59, 23, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', '0e0d9d1a4cae96a218482a5fc824b201e8cedfe93eb60747facb2d031056e57c', 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', '0e0d9d1a4cae96a218482a5fc824b201e8cedfe93eb60747facb2d031056e57c', '0e0d9d1a4cae96a218482a5fc824b201e8cedfe93eb60747facb2d031056e57c', NULL, 'هو الله الذي لا اله الا هو الملك القدوس السلم المؤمن المهيمن العزيز الجبار المتكبر سبحن الله عما يشركون', 28, 55, 219, 1, 7, 548, false, NULL),
    (5150, 'tanzil-uthmani-v1.1', 59, 24, 'هُوَ ٱللَّهُ ٱلْخَٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '9938fc23595540c94dfe23f1c2ca19ae5472e382ec33d01b653c78d660401266', 'هُوَ ٱللَّهُ ٱلْخَٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '9938fc23595540c94dfe23f1c2ca19ae5472e382ec33d01b653c78d660401266', '9938fc23595540c94dfe23f1c2ca19ae5472e382ec33d01b653c78d660401266', NULL, 'هو الله الخلق البارئ المصور له الاسماء الحسني يسبح له ما في السموت والارض وهو العزيز الحكيم', 28, 55, 219, 1, 7, 548, false, NULL),
    (5151, 'tanzil-uthmani-v1.1', 60, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَٰدًا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', '69e0384ca1d84f6e9c10d2626600b7f7cc3217c1ad735dbec424be703ce853a1', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَٰدًا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 'fabe9106a639c59759f80b7ef5ce8387e0966413cc1c8295e72fab57bfdf159f', 'fabe9106a639c59759f80b7ef5ce8387e0966413cc1c8295e72fab57bfdf159f', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يايها الذين ءامنوا لا تتخذوا عدوي وعدوكم اولياء تلقون اليهم بالموده وقد كفروا بما جاءكم من الحق يخرجون الرسول واياكم ان تؤمنوا بالله ربكم ان كنتم خرجتم جهدا في سبيلي وابتغاء مرضاتي تسرون اليهم بالموده وانا اعلم بما اخفيتم وما اعلنتم ومن يفعله منكم فقد ضل سواء السبيل', 28, 55, 219, 1, 7, 549, false, NULL),
    (5152, 'tanzil-uthmani-v1.1', 60, 2, 'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءً وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ', '43811aec30e6cc78d701a639fb63bee16fcabad8a7a5414f42d9f69846246990', 'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءً وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ', '43811aec30e6cc78d701a639fb63bee16fcabad8a7a5414f42d9f69846246990', '43811aec30e6cc78d701a639fb63bee16fcabad8a7a5414f42d9f69846246990', NULL, 'ان يثقفوكم يكونوا لكم اعداء ويبسطوا اليكم ايديهم والسنتهم بالسوء وودوا لو تكفرون', 28, 55, 219, 1, 7, 549, false, NULL),
    (5153, 'tanzil-uthmani-v1.1', 60, 3, 'لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَٰدُكُمْ يَوْمَ ٱلْقِيَٰمَةِ يَفْصِلُ بَيْنَكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '73fc1f3866b67b1f34ea19f3f8928e4962239b9b698f7af2949b049556db7f00', 'لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَٰدُكُمْ يَوْمَ ٱلْقِيَٰمَةِ يَفْصِلُ بَيْنَكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', '73fc1f3866b67b1f34ea19f3f8928e4962239b9b698f7af2949b049556db7f00', '73fc1f3866b67b1f34ea19f3f8928e4962239b9b698f7af2949b049556db7f00', NULL, 'لن تنفعكم ارحامكم ولا اولدكم يوم القيمه يفصل بينكم والله بما تعملون بصير', 28, 55, 219, 1, 7, 549, false, NULL),
    (5154, 'tanzil-uthmani-v1.1', 60, 4, 'قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ', '235d5ba15cc37260b337dca5aa95cb69eb473ab76f6bb88d61eb546c6e16cf7a', 'قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ', '235d5ba15cc37260b337dca5aa95cb69eb473ab76f6bb88d61eb546c6e16cf7a', '235d5ba15cc37260b337dca5aa95cb69eb473ab76f6bb88d61eb546c6e16cf7a', NULL, 'قد كانت لكم اسوه حسنه في ابرهيم والذين معه اذ قالوا لقومهم انا برءؤا منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العدوه والبغضاء ابدا حتي تؤمنوا بالله وحده الا قول ابرهيم لابيه لاستغفرن لك وما املك لك من الله من شيء ربنا عليك توكلنا واليك انبنا واليك المصير', 28, 55, 219, 1, 7, 549, false, NULL),
    (5155, 'tanzil-uthmani-v1.1', 60, 5, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '1acdc95bd2f9b5af7dc21b61dae5febc718bce2f9a49df9d6f23d019854754b0', 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '1acdc95bd2f9b5af7dc21b61dae5febc718bce2f9a49df9d6f23d019854754b0', '1acdc95bd2f9b5af7dc21b61dae5febc718bce2f9a49df9d6f23d019854754b0', NULL, 'ربنا لا تجعلنا فتنه للذين كفروا واغفر لنا ربنا انك انت العزيز الحكيم', 28, 55, 219, 1, 7, 549, false, NULL),
    (5156, 'tanzil-uthmani-v1.1', 60, 6, 'لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '2c9355af7436483cf81db5f63634d505cea7c56a2217a157f57b43331144e9f6', 'لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', '2c9355af7436483cf81db5f63634d505cea7c56a2217a157f57b43331144e9f6', '2c9355af7436483cf81db5f63634d505cea7c56a2217a157f57b43331144e9f6', NULL, 'لقد كان لكم فيهم اسوه حسنه لمن كان يرجوا الله واليوم الاخر ومن يتول فان الله هو الغني الحميد', 28, 55, 219, 1, 7, 550, false, NULL),
    (5157, 'tanzil-uthmani-v1.1', 60, 7, 'عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةً وَٱللَّهُ قَدِيرٌ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '1cd422349e26494e342598c8110978a2d12d57c976be4bb1f35a5964f33a2980', 'عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةً وَٱللَّهُ قَدِيرٌ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '1cd422349e26494e342598c8110978a2d12d57c976be4bb1f35a5964f33a2980', '1cd422349e26494e342598c8110978a2d12d57c976be4bb1f35a5964f33a2980', NULL, 'عسي الله ان يجعل بينكم وبين الذين عاديتم منهم موده والله قدير والله غفور رحيم', 28, 55, 220, 1, 7, 550, false, NULL),
    (5158, 'tanzil-uthmani-v1.1', 60, 8, 'لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'd77e69db1c3a44dfd3b6dce1e337dff4887996716fd3835db91c5111f3cec42e', 'لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 'd77e69db1c3a44dfd3b6dce1e337dff4887996716fd3835db91c5111f3cec42e', 'd77e69db1c3a44dfd3b6dce1e337dff4887996716fd3835db91c5111f3cec42e', NULL, 'لا ينهيكم الله عن الذين لم يقتلوكم في الدين ولم يخرجوكم من ديركم ان تبروهم وتقسطوا اليهم ان الله يحب المقسطين', 28, 55, 220, 1, 7, 550, false, NULL),
    (5159, 'tanzil-uthmani-v1.1', 60, 9, 'إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَٰرِكُمْ وَظَٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ وَمَن يَتَوَلَّهُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', '8133ba591aedf052527359a67d34265f3995d6f5d6550c87acc1dafe30f8e794', 'إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَٰرِكُمْ وَظَٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ وَمَن يَتَوَلَّهُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', '8133ba591aedf052527359a67d34265f3995d6f5d6550c87acc1dafe30f8e794', '8133ba591aedf052527359a67d34265f3995d6f5d6550c87acc1dafe30f8e794', NULL, 'انما ينهيكم الله عن الذين قتلوكم في الدين واخرجوكم من ديركم وظهروا علي اخراجكم ان تولوهم ومن يتولهم فاولئك هم الظلمون', 28, 55, 220, 1, 7, 550, false, NULL),
    (5160, 'tanzil-uthmani-v1.1', 60, 10, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَٰتُ مُهَٰجِرَٰتٍ فَٱمْتَحِنُوهُنَّ ٱللَّهُ أَعْلَمُ بِإِيمَٰنِهِنَّ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَٰتٍ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ وَءَاتُوهُم مَّآ أَنفَقُوا۟ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ذَٰلِكُمْ حُكْمُ ٱللَّهِ يَحْكُمُ بَيْنَكُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '59665ef7b85a1e8d00694e7590f9f1a70a87f239194b5f4a82c9ed3fe0054610', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَٰتُ مُهَٰجِرَٰتٍ فَٱمْتَحِنُوهُنَّ ٱللَّهُ أَعْلَمُ بِإِيمَٰنِهِنَّ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَٰتٍ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ وَءَاتُوهُم مَّآ أَنفَقُوا۟ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ذَٰلِكُمْ حُكْمُ ٱللَّهِ يَحْكُمُ بَيْنَكُمْ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', '59665ef7b85a1e8d00694e7590f9f1a70a87f239194b5f4a82c9ed3fe0054610', '59665ef7b85a1e8d00694e7590f9f1a70a87f239194b5f4a82c9ed3fe0054610', NULL, 'يايها الذين ءامنوا اذا جاءكم المؤمنت مهجرت فامتحنوهن الله اعلم بايمنهن فان علمتموهن مؤمنت فلا ترجعوهن الي الكفار لا هن حل لهم ولا هم يحلون لهن وءاتوهم ما انفقوا ولا جناح عليكم ان تنكحوهن اذا ءاتيتموهن اجورهن ولا تمسكوا بعصم الكوافر وسلوا ما انفقتم وليسلوا ما انفقوا ذلكم حكم الله يحكم بينكم والله عليم حكيم', 28, 55, 220, 1, 7, 550, false, NULL),
    (5161, 'tanzil-uthmani-v1.1', 60, 11, 'وَإِن فَاتَكُمْ شَىْءٌ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', '83a1379a3652cc542638526e06be7bb9432189081bc30e615be7b9ac78df17f5', 'وَإِن فَاتَكُمْ شَىْءٌ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', '83a1379a3652cc542638526e06be7bb9432189081bc30e615be7b9ac78df17f5', '83a1379a3652cc542638526e06be7bb9432189081bc30e615be7b9ac78df17f5', NULL, 'وان فاتكم شيء من ازوجكم الي الكفار فعاقبتم فاتوا الذين ذهبت ازوجهم مثل ما انفقوا واتقوا الله الذي انتم به مؤمنون', 28, 55, 220, 1, 7, 550, false, NULL),
    (5162, 'tanzil-uthmani-v1.1', 60, 12, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَٰنٍ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '7a5afeb77e71052bd718ba5d49081defcdf962c1eebf7f05dd3f3e24995865a0', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَٰنٍ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '7a5afeb77e71052bd718ba5d49081defcdf962c1eebf7f05dd3f3e24995865a0', '7a5afeb77e71052bd718ba5d49081defcdf962c1eebf7f05dd3f3e24995865a0', NULL, 'يايها النبي اذا جاءك المؤمنت يبايعنك علي ان لا يشركن بالله شيا ولا يسرقن ولا يزنين ولا يقتلن اولدهن ولا ياتين ببهتن يفترينه بين ايديهن وارجلهن ولا يعصينك في معروف فبايعهن واستغفر لهن الله ان الله غفور رحيم', 28, 55, 220, 1, 7, 551, false, NULL),
    (5163, 'tanzil-uthmani-v1.1', 60, 13, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْـَٔاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَٰبِ ٱلْقُبُورِ', '00ca8d2e25ed6dc3960f6b17a0913a8f029a67238398e3b8e0b075d5fa199e19', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْـَٔاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَٰبِ ٱلْقُبُورِ', '00ca8d2e25ed6dc3960f6b17a0913a8f029a67238398e3b8e0b075d5fa199e19', '00ca8d2e25ed6dc3960f6b17a0913a8f029a67238398e3b8e0b075d5fa199e19', NULL, 'يايها الذين ءامنوا لا تتولوا قوما غضب الله عليهم قد يئسوا من الاخره كما يئس الكفار من اصحب القبور', 28, 55, 220, 1, 7, 551, false, NULL),
    (5164, 'tanzil-uthmani-v1.1', 61, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'd17ce0deda2cdddadbdd4aac59c8dd351e369760f026b24b08c74bd50d07d60f', 'سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '9dc6ef4a08d6b289f8051f9f58724086d9d923cb7c33a94f9a7a1b11aaf7fb42', '9dc6ef4a08d6b289f8051f9f58724086d9d923cb7c33a94f9a7a1b11aaf7fb42', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'سبح لله ما في السموت وما في الارض وهو العزيز الحكيم', 28, 55, 220, 1, 7, 551, false, NULL),
    (5165, 'tanzil-uthmani-v1.1', 61, 2, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ', 'e463f34b1ac1e42ef3413b7009dca935c245a19443043221e7b586f76126847d', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ', 'e463f34b1ac1e42ef3413b7009dca935c245a19443043221e7b586f76126847d', 'e463f34b1ac1e42ef3413b7009dca935c245a19443043221e7b586f76126847d', NULL, 'يايها الذين ءامنوا لم تقولون ما لا تفعلون', 28, 55, 220, 1, 7, 551, false, NULL),
    (5166, 'tanzil-uthmani-v1.1', 61, 3, 'كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ', 'b7b796001cdde96252160d040609e2a154aff21fb3a4f665da910cd14bf52f88', 'كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ', 'b7b796001cdde96252160d040609e2a154aff21fb3a4f665da910cd14bf52f88', 'b7b796001cdde96252160d040609e2a154aff21fb3a4f665da910cd14bf52f88', NULL, 'كبر مقتا عند الله ان تقولوا ما لا تفعلون', 28, 55, 220, 1, 7, 551, false, NULL),
    (5167, 'tanzil-uthmani-v1.1', 61, 4, 'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِى سَبِيلِهِۦ صَفًّا كَأَنَّهُم بُنْيَٰنٌ مَّرْصُوصٌ', '1f6f4bffdef323f0642bdfcef937aed70db9b22132261dadd0c7b5eb0510f98e', 'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِى سَبِيلِهِۦ صَفًّا كَأَنَّهُم بُنْيَٰنٌ مَّرْصُوصٌ', '1f6f4bffdef323f0642bdfcef937aed70db9b22132261dadd0c7b5eb0510f98e', '1f6f4bffdef323f0642bdfcef937aed70db9b22132261dadd0c7b5eb0510f98e', NULL, 'ان الله يحب الذين يقتلون في سبيله صفا كانهم بنين مرصوص', 28, 55, 220, 1, 7, 551, false, NULL),
    (5168, 'tanzil-uthmani-v1.1', 61, 5, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'aaacfa6aa5d147a3c9c916b3ad49f79e6a97384b8e284bee9a266885d7bd2b02', 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 'aaacfa6aa5d147a3c9c916b3ad49f79e6a97384b8e284bee9a266885d7bd2b02', 'aaacfa6aa5d147a3c9c916b3ad49f79e6a97384b8e284bee9a266885d7bd2b02', NULL, 'واذ قال موسي لقومه يقوم لم تؤذونني وقد تعلمون اني رسول الله اليكم فلما زاغوا ازاغ الله قلوبهم والله لا يهدي القوم الفسقين', 28, 55, 220, 1, 7, 551, false, NULL),
    (5169, 'tanzil-uthmani-v1.1', 61, 6, 'وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَٰتِ قَالُوا۟ هَٰذَا سِحْرٌ مُّبِينٌ', '126cd42cc75f989e6b4e5886e790c85ceadf4f134fc588b312e48444ee4628f8', 'وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَٰتِ قَالُوا۟ هَٰذَا سِحْرٌ مُّبِينٌ', '126cd42cc75f989e6b4e5886e790c85ceadf4f134fc588b312e48444ee4628f8', '126cd42cc75f989e6b4e5886e790c85ceadf4f134fc588b312e48444ee4628f8', NULL, 'واذ قال عيسي ابن مريم يبني اسرءيل اني رسول الله اليكم مصدقا لما بين يدي من التوريه ومبشرا برسول ياتي من بعدي اسمه احمد فلما جاءهم بالبينت قالوا هذا سحر مبين', 28, 55, 220, 1, 7, 552, false, NULL),
    (5170, 'tanzil-uthmani-v1.1', 61, 7, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَٰمِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '3869b70e5744f8bbe3204276753ad50414903248634ba16746b535c4bfa4bf6b', 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَٰمِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', '3869b70e5744f8bbe3204276753ad50414903248634ba16746b535c4bfa4bf6b', '3869b70e5744f8bbe3204276753ad50414903248634ba16746b535c4bfa4bf6b', NULL, 'ومن اظلم ممن افتري علي الله الكذب وهو يدعي الي الاسلم والله لا يهدي القوم الظلمين', 28, 55, 220, 1, 7, 552, false, NULL),
    (5171, 'tanzil-uthmani-v1.1', 61, 8, 'يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', '73111e1835a07b4c3a7b890758ffe52e0e0ec9fc6b8ae978e570d51bcd2cc458', 'يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', '73111e1835a07b4c3a7b890758ffe52e0e0ec9fc6b8ae978e570d51bcd2cc458', '73111e1835a07b4c3a7b890758ffe52e0e0ec9fc6b8ae978e570d51bcd2cc458', NULL, 'يريدون ليطفوا نور الله بافوههم والله متم نوره ولو كره الكفرون', 28, 55, 220, 1, 7, 552, false, NULL),
    (5172, 'tanzil-uthmani-v1.1', 61, 9, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', '72056e1cc5d673ddd6155a648c4fc6f16db7f0b860112f62fbe189b5e490d593', 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', '72056e1cc5d673ddd6155a648c4fc6f16db7f0b860112f62fbe189b5e490d593', '72056e1cc5d673ddd6155a648c4fc6f16db7f0b860112f62fbe189b5e490d593', NULL, 'هو الذي ارسل رسوله بالهدي ودين الحق ليظهره علي الدين كله ولو كره المشركون', 28, 55, 220, 1, 7, 552, false, NULL),
    (5173, 'tanzil-uthmani-v1.1', 61, 10, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَٰرَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ', '552aa2d6b75c9bb399b5b49e3160edf247d2d9731e54fdfbeb116c9fb0c07181', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَٰرَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ', '552aa2d6b75c9bb399b5b49e3160edf247d2d9731e54fdfbeb116c9fb0c07181', '552aa2d6b75c9bb399b5b49e3160edf247d2d9731e54fdfbeb116c9fb0c07181', NULL, 'يايها الذين ءامنوا هل ادلكم علي تجره تنجيكم من عذاب اليم', 28, 55, 220, 1, 7, 552, false, NULL),
    (5174, 'tanzil-uthmani-v1.1', 61, 11, 'تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '46b34d1464c7a125cf0e4afcf3998c3a69f894db0370536fa6ca0b9e34c2830e', 'تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '46b34d1464c7a125cf0e4afcf3998c3a69f894db0370536fa6ca0b9e34c2830e', '46b34d1464c7a125cf0e4afcf3998c3a69f894db0370536fa6ca0b9e34c2830e', NULL, 'تؤمنون بالله ورسوله وتجهدون في سبيل الله بامولكم وانفسكم ذلكم خير لكم ان كنتم تعلمون', 28, 55, 220, 1, 7, 552, false, NULL),
    (5175, 'tanzil-uthmani-v1.1', 61, 12, 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَمَسَٰكِنَ طَيِّبَةً فِى جَنَّٰتِ عَدْنٍ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'f31be69c99be7a4c61c0c22b0e734e35e6eb92911a052801450f17792a9579a4', 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَمَسَٰكِنَ طَيِّبَةً فِى جَنَّٰتِ عَدْنٍ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'f31be69c99be7a4c61c0c22b0e734e35e6eb92911a052801450f17792a9579a4', 'f31be69c99be7a4c61c0c22b0e734e35e6eb92911a052801450f17792a9579a4', NULL, 'يغفر لكم ذنوبكم ويدخلكم جنت تجري من تحتها الانهر ومسكن طيبه في جنت عدن ذلك الفوز العظيم', 28, 55, 220, 1, 7, 552, false, NULL),
    (5176, 'tanzil-uthmani-v1.1', 61, 13, 'وَأُخْرَىٰ تُحِبُّونَهَا نَصْرٌ مِّنَ ٱللَّهِ وَفَتْحٌ قَرِيبٌ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '90b9b973d373ae67b0c81ac96c9d1aeb62e8dba6ff37fb0db5e27c1e01427cac', 'وَأُخْرَىٰ تُحِبُّونَهَا نَصْرٌ مِّنَ ٱللَّهِ وَفَتْحٌ قَرِيبٌ وَبَشِّرِ ٱلْمُؤْمِنِينَ', '90b9b973d373ae67b0c81ac96c9d1aeb62e8dba6ff37fb0db5e27c1e01427cac', '90b9b973d373ae67b0c81ac96c9d1aeb62e8dba6ff37fb0db5e27c1e01427cac', NULL, 'واخري تحبونها نصر من الله وفتح قريب وبشر المؤمنين', 28, 55, 220, 1, 7, 552, false, NULL),
    (5177, 'tanzil-uthmani-v1.1', 61, 14, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّـۧنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ فَـَٔامَنَت طَّآئِفَةٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَٰهِرِينَ', 'aed49fa70cba527a0ce3188771497eae69c473b2787a58cb76ff6b99b09d1e6c', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّـۧنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ فَـَٔامَنَت طَّآئِفَةٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَٰهِرِينَ', 'aed49fa70cba527a0ce3188771497eae69c473b2787a58cb76ff6b99b09d1e6c', 'aed49fa70cba527a0ce3188771497eae69c473b2787a58cb76ff6b99b09d1e6c', NULL, 'يايها الذين ءامنوا كونوا انصار الله كما قال عيسي ابن مريم للحوارين من انصاري الي الله قال الحواريون نحن انصار الله فامنت طائفه من بني اسرءيل وكفرت طائفه فايدنا الذين ءامنوا علي عدوهم فاصبحوا ظهرين', 28, 55, 220, 1, 7, 552, false, NULL),
    (5178, 'tanzil-uthmani-v1.1', 62, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 'ef639b6ac7a3b3bcfce701bec8a529b0dedaa573b7876458ce9d18eb1a1f7f69', 'يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ', '007980f3033d0a74f267ba02b18299a26846788bd48d1de8469970815645f73b', '007980f3033d0a74f267ba02b18299a26846788bd48d1de8469970815645f73b', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يسبح لله ما في السموت وما في الارض الملك القدوس العزيز الحكيم', 28, 56, 221, 1, 7, 553, false, NULL),
    (5179, 'tanzil-uthmani-v1.1', 62, 2, 'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّـۧنَ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍ مُّبِينٍ', 'f67f65b6de24255ce790925ca9ce4521cfe7db2c832048f1a3ffb0f21e288138', 'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّـۧنَ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍ مُّبِينٍ', 'f67f65b6de24255ce790925ca9ce4521cfe7db2c832048f1a3ffb0f21e288138', 'f67f65b6de24255ce790925ca9ce4521cfe7db2c832048f1a3ffb0f21e288138', NULL, 'هو الذي بعث في الامين رسولا منهم يتلوا عليهم ءايته ويزكيهم ويعلمهم الكتب والحكمه وان كانوا من قبل لفي ضلل مبين', 28, 56, 221, 1, 7, 553, false, NULL),
    (5180, 'tanzil-uthmani-v1.1', 62, 3, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '0f2596fe78c7b5552561561591fb8e67b80a30b2e16625b3a04ca98830c59755', 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', '0f2596fe78c7b5552561561591fb8e67b80a30b2e16625b3a04ca98830c59755', '0f2596fe78c7b5552561561591fb8e67b80a30b2e16625b3a04ca98830c59755', NULL, 'وءاخرين منهم لما يلحقوا بهم وهو العزيز الحكيم', 28, 56, 221, 1, 7, 553, false, NULL),
    (5181, 'tanzil-uthmani-v1.1', 62, 4, 'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'a00927cbce51d0ffce9f669620ddfb70e7ad7b100cb991f1018cc7320dadf29e', 'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 'a00927cbce51d0ffce9f669620ddfb70e7ad7b100cb991f1018cc7320dadf29e', 'a00927cbce51d0ffce9f669620ddfb70e7ad7b100cb991f1018cc7320dadf29e', NULL, 'ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم', 28, 56, 221, 1, 7, 553, false, NULL),
    (5182, 'tanzil-uthmani-v1.1', 62, 5, 'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'c4f6279c2dbdc1b84ace69689c68b903ee6459408f5536e90351b4505e032352', 'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 'c4f6279c2dbdc1b84ace69689c68b903ee6459408f5536e90351b4505e032352', 'c4f6279c2dbdc1b84ace69689c68b903ee6459408f5536e90351b4505e032352', NULL, 'مثل الذين حملوا التوريه ثم لم يحملوها كمثل الحمار يحمل اسفارا بئس مثل القوم الذين كذبوا بايت الله والله لا يهدي القوم الظلمين', 28, 56, 221, 1, 7, 553, false, NULL),
    (5183, 'tanzil-uthmani-v1.1', 62, 6, 'قُلْ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', '82ecc26856e315e5f44064104af8b70920e30cb3131766a2d9afebcdf63b9426', 'قُلْ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', '82ecc26856e315e5f44064104af8b70920e30cb3131766a2d9afebcdf63b9426', '82ecc26856e315e5f44064104af8b70920e30cb3131766a2d9afebcdf63b9426', NULL, 'قل يايها الذين هادوا ان زعمتم انكم اولياء لله من دون الناس فتمنوا الموت ان كنتم صدقين', 28, 56, 221, 1, 7, 553, false, NULL),
    (5184, 'tanzil-uthmani-v1.1', 62, 7, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'e448b31d918922d688848646001e039cb786778d431a9b77e0ab5ae8620e9f6c', 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 'e448b31d918922d688848646001e039cb786778d431a9b77e0ab5ae8620e9f6c', 'e448b31d918922d688848646001e039cb786778d431a9b77e0ab5ae8620e9f6c', NULL, 'ولا يتمنونه ابدا بما قدمت ايديهم والله عليم بالظلمين', 28, 56, 221, 1, 7, 553, false, NULL),
    (5185, 'tanzil-uthmani-v1.1', 62, 8, 'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '24d3337bd732daccbfaca3b71c337132b630e9c9967e995b7cbda7eb036234f4', 'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', '24d3337bd732daccbfaca3b71c337132b630e9c9967e995b7cbda7eb036234f4', '24d3337bd732daccbfaca3b71c337132b630e9c9967e995b7cbda7eb036234f4', NULL, 'قل ان الموت الذي تفرون منه فانه ملقيكم ثم تردون الي علم الغيب والشهده فينبئكم بما كنتم تعملون', 28, 56, 221, 1, 7, 553, false, NULL),
    (5186, 'tanzil-uthmani-v1.1', 62, 9, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'c98d28b006cf1f1688d5fe72c73ded44e5b36b47d9a8a40fd9139833df99f9c2', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'c98d28b006cf1f1688d5fe72c73ded44e5b36b47d9a8a40fd9139833df99f9c2', 'c98d28b006cf1f1688d5fe72c73ded44e5b36b47d9a8a40fd9139833df99f9c2', NULL, 'يايها الذين ءامنوا اذا نودي للصلوه من يوم الجمعه فاسعوا الي ذكر الله وذروا البيع ذلكم خير لكم ان كنتم تعلمون', 28, 56, 221, 1, 7, 554, false, NULL),
    (5187, 'tanzil-uthmani-v1.1', 62, 10, 'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', '9c2dd9d3b734506a0803e798ce478cf38e6f2e6af110f95137ecbb3adf042f23', 'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', '9c2dd9d3b734506a0803e798ce478cf38e6f2e6af110f95137ecbb3adf042f23', '9c2dd9d3b734506a0803e798ce478cf38e6f2e6af110f95137ecbb3adf042f23', NULL, 'فاذا قضيت الصلوه فانتشروا في الارض وابتغوا من فضل الله واذكروا الله كثيرا لعلكم تفلحون', 28, 56, 221, 1, 7, 554, false, NULL),
    (5188, 'tanzil-uthmani-v1.1', 62, 11, 'وَإِذَا رَأَوْا۟ تِجَٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًا قُلْ مَا عِندَ ٱللَّهِ خَيْرٌ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَٰرَةِ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ', 'd338614eafd0618d1738405b12268cd27165523224eb42c21fc4b7485b5e705c', 'وَإِذَا رَأَوْا۟ تِجَٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًا قُلْ مَا عِندَ ٱللَّهِ خَيْرٌ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَٰرَةِ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ', 'd338614eafd0618d1738405b12268cd27165523224eb42c21fc4b7485b5e705c', 'd338614eafd0618d1738405b12268cd27165523224eb42c21fc4b7485b5e705c', NULL, 'واذا راوا تجره او لهوا انفضوا اليها وتركوك قائما قل ما عند الله خير من اللهو ومن التجره والله خير الرزقين', 28, 56, 221, 1, 7, 554, false, NULL),
    (5189, 'tanzil-uthmani-v1.1', 63, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا جَآءَكَ ٱلْمُنَٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَٰفِقِينَ لَكَٰذِبُونَ', '1783105b1395d6dac4a436ad0f2c2522c839b53a6d2fa5b4f7439cda73917302', 'إِذَا جَآءَكَ ٱلْمُنَٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَٰفِقِينَ لَكَٰذِبُونَ', '0471a66b5a94c58140c79d42bb2cde33e8bcf6297e1e971a7b1f318c4a2f8279', '0471a66b5a94c58140c79d42bb2cde33e8bcf6297e1e971a7b1f318c4a2f8279', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'اذا جاءك المنفقون قالوا نشهد انك لرسول الله والله يعلم انك لرسوله والله يشهد ان المنفقين لكذبون', 28, 56, 221, 1, 7, 554, false, NULL),
    (5190, 'tanzil-uthmani-v1.1', 63, 2, 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'cef0ac992d368536845e8ba62374c80c082cdb46450129e8efa10c3140e5d0e7', 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 'cef0ac992d368536845e8ba62374c80c082cdb46450129e8efa10c3140e5d0e7', 'cef0ac992d368536845e8ba62374c80c082cdb46450129e8efa10c3140e5d0e7', NULL, 'اتخذوا ايمنهم جنه فصدوا عن سبيل الله انهم ساء ما كانوا يعملون', 28, 56, 221, 1, 7, 554, false, NULL),
    (5191, 'tanzil-uthmani-v1.1', 63, 3, 'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', '9dd879417a96dd155ddb0ca20173e17645e712e4e210903b3030b566be760fd1', 'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', '9dd879417a96dd155ddb0ca20173e17645e712e4e210903b3030b566be760fd1', '9dd879417a96dd155ddb0ca20173e17645e712e4e210903b3030b566be760fd1', NULL, 'ذلك بانهم ءامنوا ثم كفروا فطبع علي قلوبهم فهم لا يفقهون', 28, 56, 221, 1, 7, 554, false, NULL),
    (5192, 'tanzil-uthmani-v1.1', 63, 4, 'وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ قَٰتَلَهُمُ ٱللَّهُ أَنَّىٰ يُؤْفَكُونَ', 'e39e2ec6728b7128449faa85420dd4efc6bc66e303d0edd3273045c26087b75f', 'وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ قَٰتَلَهُمُ ٱللَّهُ أَنَّىٰ يُؤْفَكُونَ', 'e39e2ec6728b7128449faa85420dd4efc6bc66e303d0edd3273045c26087b75f', 'e39e2ec6728b7128449faa85420dd4efc6bc66e303d0edd3273045c26087b75f', NULL, 'واذا رايتهم تعجبك اجسامهم وان يقولوا تسمع لقولهم كانهم خشب مسنده يحسبون كل صيحه عليهم هم العدو فاحذرهم قتلهم الله اني يؤفكون', 28, 56, 222, 1, 7, 554, false, NULL),
    (5193, 'tanzil-uthmani-v1.1', 63, 5, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ', 'e82b87106819b0801efcca4156e70322b15c688c62f8d7989bf702c914ee1e20', 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ', 'e82b87106819b0801efcca4156e70322b15c688c62f8d7989bf702c914ee1e20', 'e82b87106819b0801efcca4156e70322b15c688c62f8d7989bf702c914ee1e20', NULL, 'واذا قيل لهم تعالوا يستغفر لكم رسول الله لووا رءوسهم ورايتهم يصدون وهم مستكبرون', 28, 56, 222, 1, 7, 555, false, NULL),
    (5194, 'tanzil-uthmani-v1.1', 63, 6, 'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', '41af9dc6d43b7c4928eeb0fe02a46c8175cc78404dc79ce59f1f29690d5edf69', 'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', '41af9dc6d43b7c4928eeb0fe02a46c8175cc78404dc79ce59f1f29690d5edf69', '41af9dc6d43b7c4928eeb0fe02a46c8175cc78404dc79ce59f1f29690d5edf69', NULL, 'سواء عليهم استغفرت لهم ام لم تستغفر لهم لن يغفر الله لهم ان الله لا يهدي القوم الفسقين', 28, 56, 222, 1, 7, 555, false, NULL),
    (5195, 'tanzil-uthmani-v1.1', 63, 7, 'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَفْقَهُونَ', '63653db399037bb343b6eb0db6f0c77366929decca4fb5f4e66c1a59f164e86d', 'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَفْقَهُونَ', '63653db399037bb343b6eb0db6f0c77366929decca4fb5f4e66c1a59f164e86d', '63653db399037bb343b6eb0db6f0c77366929decca4fb5f4e66c1a59f164e86d', NULL, 'هم الذين يقولون لا تنفقوا علي من عند رسول الله حتي ينفضوا ولله خزائن السموت والارض ولكن المنفقين لا يفقهون', 28, 56, 222, 1, 7, 555, false, NULL),
    (5196, 'tanzil-uthmani-v1.1', 63, 8, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَعْلَمُونَ', 'bca018577fc76f3d45c2c9ce8f84efcb79f6934fd88c0ee1f8a92d3c5ef48fdc', 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَعْلَمُونَ', 'bca018577fc76f3d45c2c9ce8f84efcb79f6934fd88c0ee1f8a92d3c5ef48fdc', 'bca018577fc76f3d45c2c9ce8f84efcb79f6934fd88c0ee1f8a92d3c5ef48fdc', NULL, 'يقولون لئن رجعنا الي المدينه ليخرجن الاعز منها الاذل ولله العزه ولرسوله وللمؤمنين ولكن المنفقين لا يعلمون', 28, 56, 222, 1, 7, 555, false, NULL),
    (5197, 'tanzil-uthmani-v1.1', 63, 9, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُمْ عَن ذِكْرِ ٱللَّهِ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '26b746e5ac8af14ce466c37c47c41649ffd29a1389d79e837ac1b989f0723d86', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُمْ عَن ذِكْرِ ٱللَّهِ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', '26b746e5ac8af14ce466c37c47c41649ffd29a1389d79e837ac1b989f0723d86', '26b746e5ac8af14ce466c37c47c41649ffd29a1389d79e837ac1b989f0723d86', NULL, 'يايها الذين ءامنوا لا تلهكم امولكم ولا اولدكم عن ذكر الله ومن يفعل ذلك فاولئك هم الخسرون', 28, 56, 222, 1, 7, 555, false, NULL),
    (5198, 'tanzil-uthmani-v1.1', 63, 10, 'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ', '438a228615d5ac765b23f8bbbdb3b534249c8505b3d6122eb0dc3c6a3a3b104c', 'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ', '438a228615d5ac765b23f8bbbdb3b534249c8505b3d6122eb0dc3c6a3a3b104c', '438a228615d5ac765b23f8bbbdb3b534249c8505b3d6122eb0dc3c6a3a3b104c', NULL, 'وانفقوا من ما رزقنكم من قبل ان ياتي احدكم الموت فيقول رب لولا اخرتني الي اجل قريب فاصدق واكن من الصلحين', 28, 56, 222, 1, 7, 555, false, NULL),
    (5199, 'tanzil-uthmani-v1.1', 63, 11, 'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '789ec15abee13f55f40eba4c4e2edfbd72b7a1fe57192bc10895bb97be1e7730', 'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', '789ec15abee13f55f40eba4c4e2edfbd72b7a1fe57192bc10895bb97be1e7730', '789ec15abee13f55f40eba4c4e2edfbd72b7a1fe57192bc10895bb97be1e7730', NULL, 'ولن يؤخر الله نفسا اذا جاء اجلها والله خبير بما تعملون', 28, 56, 222, 1, 7, 555, false, NULL),
    (5200, 'tanzil-uthmani-v1.1', 64, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'ee601be3f4dc505253c64c2099706f92cdb88b3935265f1634377dbe3774e2ad', 'يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '05cf1d794c1d71f7d3ffdae0960d228d17f5e85c0c5fb072b90efc0ab92ae33b', '05cf1d794c1d71f7d3ffdae0960d228d17f5e85c0c5fb072b90efc0ab92ae33b', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يسبح لله ما في السموت وما في الارض له الملك وله الحمد وهو علي كل شيء قدير', 28, 56, 222, 1, 7, 556, false, NULL),
    (5201, 'tanzil-uthmani-v1.1', 64, 2, 'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌ وَمِنكُم مُّؤْمِنٌ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'c79dbebec355bd4b6d5e90435961b307737883d38927bfdfd4eca1343676b5ea', 'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌ وَمِنكُم مُّؤْمِنٌ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 'c79dbebec355bd4b6d5e90435961b307737883d38927bfdfd4eca1343676b5ea', 'c79dbebec355bd4b6d5e90435961b307737883d38927bfdfd4eca1343676b5ea', NULL, 'هو الذي خلقكم فمنكم كافر ومنكم مؤمن والله بما تعملون بصير', 28, 56, 222, 1, 7, 556, false, NULL),
    (5202, 'tanzil-uthmani-v1.1', 64, 3, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَإِلَيْهِ ٱلْمَصِيرُ', 'acce17563eb4b06fc0e3ddbf169762414246ed4816286fdf8831b39e72e23349', 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَإِلَيْهِ ٱلْمَصِيرُ', 'acce17563eb4b06fc0e3ddbf169762414246ed4816286fdf8831b39e72e23349', 'acce17563eb4b06fc0e3ddbf169762414246ed4816286fdf8831b39e72e23349', NULL, 'خلق السموت والارض بالحق وصوركم فاحسن صوركم واليه المصير', 28, 56, 222, 1, 7, 556, false, NULL),
    (5203, 'tanzil-uthmani-v1.1', 64, 4, 'يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '0630c1c1a99ee2ce0efe52ed4b74907bf35a5238f12e0c0a3a46e5e01dcc3626', 'يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '0630c1c1a99ee2ce0efe52ed4b74907bf35a5238f12e0c0a3a46e5e01dcc3626', '0630c1c1a99ee2ce0efe52ed4b74907bf35a5238f12e0c0a3a46e5e01dcc3626', NULL, 'يعلم ما في السموت والارض ويعلم ما تسرون وما تعلنون والله عليم بذات الصدور', 28, 56, 222, 1, 7, 556, false, NULL),
    (5204, 'tanzil-uthmani-v1.1', 64, 5, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '69b2febeb9d7184e103b8e93e22455e5fe28a9c7d1967fda1900cdbe36757b93', 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', '69b2febeb9d7184e103b8e93e22455e5fe28a9c7d1967fda1900cdbe36757b93', '69b2febeb9d7184e103b8e93e22455e5fe28a9c7d1967fda1900cdbe36757b93', NULL, 'الم ياتكم نبؤا الذين كفروا من قبل فذاقوا وبال امرهم ولهم عذاب اليم', 28, 56, 222, 1, 7, 556, false, NULL),
    (5205, 'tanzil-uthmani-v1.1', 64, 6, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَقَالُوٓا۟ أَبَشَرٌ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ وَّٱسْتَغْنَى ٱللَّهُ وَٱللَّهُ غَنِىٌّ حَمِيدٌ', 'f3f116e434152ac34a0424354f3166870259ddf52fc793bdeb0a846a0fd1dd6f', 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَقَالُوٓا۟ أَبَشَرٌ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ وَّٱسْتَغْنَى ٱللَّهُ وَٱللَّهُ غَنِىٌّ حَمِيدٌ', 'f3f116e434152ac34a0424354f3166870259ddf52fc793bdeb0a846a0fd1dd6f', 'f3f116e434152ac34a0424354f3166870259ddf52fc793bdeb0a846a0fd1dd6f', NULL, 'ذلك بانه كانت تاتيهم رسلهم بالبينت فقالوا ابشر يهدوننا فكفروا وتولوا واستغني الله والله غني حميد', 28, 56, 222, 1, 7, 556, false, NULL),
    (5206, 'tanzil-uthmani-v1.1', 64, 7, 'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '8dd0126fdc2ed8079022cbedf90ac9da336fe3c6b3eacc45eb683d8a0fab7169', 'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', '8dd0126fdc2ed8079022cbedf90ac9da336fe3c6b3eacc45eb683d8a0fab7169', '8dd0126fdc2ed8079022cbedf90ac9da336fe3c6b3eacc45eb683d8a0fab7169', NULL, 'زعم الذين كفروا ان لن يبعثوا قل بلي وربي لتبعثن ثم لتنبؤن بما عملتم وذلك علي الله يسير', 28, 56, 222, 1, 7, 556, false, NULL),
    (5207, 'tanzil-uthmani-v1.1', 64, 8, 'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'dffd51df4691e3c6d820411d7b3afd28d7096aa696adc93bc7ff6255fa3153b5', 'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 'dffd51df4691e3c6d820411d7b3afd28d7096aa696adc93bc7ff6255fa3153b5', 'dffd51df4691e3c6d820411d7b3afd28d7096aa696adc93bc7ff6255fa3153b5', NULL, 'فامنوا بالله ورسوله والنور الذي انزلنا والله بما تعملون خبير', 28, 56, 222, 1, 7, 556, false, NULL),
    (5208, 'tanzil-uthmani-v1.1', 64, 9, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'affe118568a23724335ba4e1428aedf98a1875ea6b6a84a5e94c4d17c464dc14', 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 'affe118568a23724335ba4e1428aedf98a1875ea6b6a84a5e94c4d17c464dc14', 'affe118568a23724335ba4e1428aedf98a1875ea6b6a84a5e94c4d17c464dc14', NULL, 'يوم يجمعكم ليوم الجمع ذلك يوم التغابن ومن يؤمن بالله ويعمل صلحا يكفر عنه سياته ويدخله جنت تجري من تحتها الانهر خلدين فيها ابدا ذلك الفوز العظيم', 28, 56, 222, 1, 7, 556, false, NULL),
    (5209, 'tanzil-uthmani-v1.1', 64, 10, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَا وَبِئْسَ ٱلْمَصِيرُ', '8d96af336883a992bbee832b809378865b204389c6d45d7b3de8b0ccdfa5dfc5', 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَا وَبِئْسَ ٱلْمَصِيرُ', '8d96af336883a992bbee832b809378865b204389c6d45d7b3de8b0ccdfa5dfc5', '8d96af336883a992bbee832b809378865b204389c6d45d7b3de8b0ccdfa5dfc5', NULL, 'والذين كفروا وكذبوا بايتنا اولئك اصحب النار خلدين فيها وبئس المصير', 28, 56, 222, 1, 7, 557, false, NULL),
    (5210, 'tanzil-uthmani-v1.1', 64, 11, 'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '0175a03d059962042719256f5caade24f4f3b0aae1f823c7b4b78a538fb1b9c9', 'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', '0175a03d059962042719256f5caade24f4f3b0aae1f823c7b4b78a538fb1b9c9', '0175a03d059962042719256f5caade24f4f3b0aae1f823c7b4b78a538fb1b9c9', NULL, 'ما اصاب من مصيبه الا باذن الله ومن يؤمن بالله يهد قلبه والله بكل شيء عليم', 28, 56, 222, 1, 7, 557, false, NULL),
    (5211, 'tanzil-uthmani-v1.1', 64, 12, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'f77c23ba9e22a245dd7e5e4bca2b3139ada8f27f9c45f5252d63e1bc86dc84c9', 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 'f77c23ba9e22a245dd7e5e4bca2b3139ada8f27f9c45f5252d63e1bc86dc84c9', 'f77c23ba9e22a245dd7e5e4bca2b3139ada8f27f9c45f5252d63e1bc86dc84c9', NULL, 'واطيعوا الله واطيعوا الرسول فان توليتم فانما علي رسولنا البلغ المبين', 28, 56, 222, 1, 7, 557, false, NULL),
    (5212, 'tanzil-uthmani-v1.1', 64, 13, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '475cd073dc7b3dc7413057c0fa25277ad42f5e88f91e378682bef2f861a02669', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', '475cd073dc7b3dc7413057c0fa25277ad42f5e88f91e378682bef2f861a02669', '475cd073dc7b3dc7413057c0fa25277ad42f5e88f91e378682bef2f861a02669', NULL, 'الله لا اله الا هو وعلي الله فليتوكل المؤمنون', 28, 56, 222, 1, 7, 557, false, NULL),
    (5213, 'tanzil-uthmani-v1.1', 64, 14, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَٰدِكُمْ عَدُوًّا لَّكُمْ فَٱحْذَرُوهُمْ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '784abd6bd148bf39ca99399a8bc11ace8f44c2b6d817ac2fd61bf400cc45d42d', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَٰدِكُمْ عَدُوًّا لَّكُمْ فَٱحْذَرُوهُمْ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', '784abd6bd148bf39ca99399a8bc11ace8f44c2b6d817ac2fd61bf400cc45d42d', '784abd6bd148bf39ca99399a8bc11ace8f44c2b6d817ac2fd61bf400cc45d42d', NULL, 'يايها الذين ءامنوا ان من ازوجكم واولدكم عدوا لكم فاحذروهم وان تعفوا وتصفحوا وتغفروا فان الله غفور رحيم', 28, 56, 222, 1, 7, 557, false, NULL),
    (5214, 'tanzil-uthmani-v1.1', 64, 15, 'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'd23857558aea9e518dc69302ebe8a75d1796da78e5becdbf38061bccf7c6c1bd', 'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 'd23857558aea9e518dc69302ebe8a75d1796da78e5becdbf38061bccf7c6c1bd', 'd23857558aea9e518dc69302ebe8a75d1796da78e5becdbf38061bccf7c6c1bd', NULL, 'انما امولكم واولدكم فتنه والله عنده اجر عظيم', 28, 56, 222, 1, 7, 557, false, NULL),
    (5215, 'tanzil-uthmani-v1.1', 64, 16, 'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًا لِّأَنفُسِكُمْ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'b8ed7eeef6899c31075c785255ae998b4d3a0ce87614e5c5b13648f6514da9bb', 'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًا لِّأَنفُسِكُمْ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 'b8ed7eeef6899c31075c785255ae998b4d3a0ce87614e5c5b13648f6514da9bb', 'b8ed7eeef6899c31075c785255ae998b4d3a0ce87614e5c5b13648f6514da9bb', NULL, 'فاتقوا الله ما استطعتم واسمعوا واطيعوا وانفقوا خيرا لانفسكم ومن يوق شح نفسه فاولئك هم المفلحون', 28, 56, 222, 1, 7, 557, false, NULL),
    (5216, 'tanzil-uthmani-v1.1', 64, 17, 'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ شَكُورٌ حَلِيمٌ', '9669e22d036f6e3ac380d94e919a1b6666c8478e082f93c35b5673c9de715466', 'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ وَٱللَّهُ شَكُورٌ حَلِيمٌ', '9669e22d036f6e3ac380d94e919a1b6666c8478e082f93c35b5673c9de715466', '9669e22d036f6e3ac380d94e919a1b6666c8478e082f93c35b5673c9de715466', NULL, 'ان تقرضوا الله قرضا حسنا يضعفه لكم ويغفر لكم والله شكور حليم', 28, 56, 222, 1, 7, 557, false, NULL),
    (5217, 'tanzil-uthmani-v1.1', 64, 18, 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'da01fcd5dd929070324433877305728e686eef8bb066e7ff9b6c104195b7b758', 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ', 'da01fcd5dd929070324433877305728e686eef8bb066e7ff9b6c104195b7b758', 'da01fcd5dd929070324433877305728e686eef8bb066e7ff9b6c104195b7b758', NULL, 'علم الغيب والشهده العزيز الحكيم', 28, 56, 222, 1, 7, 557, false, NULL),
    (5218, 'tanzil-uthmani-v1.1', 65, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍ مُّبَيِّنَةٍ وَتِلْكَ حُدُودُ ٱللَّهِ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا', 'c1a909a1f7ccb75eaa5006306d90efb3b7b67b67a36daaf5add7560cee183e1d', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍ مُّبَيِّنَةٍ وَتِلْكَ حُدُودُ ٱللَّهِ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا', '79f430004b61592430c814d75f1a15f8a0fae40a2c2d5acf72c70d3129be5e32', '79f430004b61592430c814d75f1a15f8a0fae40a2c2d5acf72c70d3129be5e32', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده واتقوا الله ربكم لا تخرجوهن من بيوتهن ولا يخرجن الا ان ياتين بفحشه مبينه وتلك حدود الله ومن يتعد حدود الله فقد ظلم نفسه لا تدري لعل الله يحدث بعد ذلك امرا', 28, 56, 223, 1, 7, 558, false, NULL),
    (5219, 'tanzil-uthmani-v1.1', 65, 2, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَٰدَةَ لِلَّهِ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا', '279620800797629a1820eec99a3dcc9cdc91bc6f31ec648a594235044750b1b2', 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَٰدَةَ لِلَّهِ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا', '279620800797629a1820eec99a3dcc9cdc91bc6f31ec648a594235044750b1b2', '279620800797629a1820eec99a3dcc9cdc91bc6f31ec648a594235044750b1b2', NULL, 'فاذا بلغن اجلهن فامسكوهن بمعروف او فارقوهن بمعروف واشهدوا ذوي عدل منكم واقيموا الشهده لله ذلكم يوعظ به من كان يؤمن بالله واليوم الاخر ومن يتق الله يجعل له مخرجا', 28, 56, 223, 1, 7, 558, false, NULL),
    (5220, 'tanzil-uthmani-v1.1', 65, 3, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ إِنَّ ٱللَّهَ بَٰلِغُ أَمْرِهِۦ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا', '13196787d72bf61630eb8d26ad633f8c2887eed08fa6fa34478e310f63ae6036', 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ إِنَّ ٱللَّهَ بَٰلِغُ أَمْرِهِۦ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا', '13196787d72bf61630eb8d26ad633f8c2887eed08fa6fa34478e310f63ae6036', '13196787d72bf61630eb8d26ad633f8c2887eed08fa6fa34478e310f63ae6036', NULL, 'ويرزقه من حيث لا يحتسب ومن يتوكل علي الله فهو حسبه ان الله بلغ امره قد جعل الله لكل شيء قدرا', 28, 56, 223, 1, 7, 558, false, NULL),
    (5221, 'tanzil-uthmani-v1.1', 65, 4, 'وَٱلَّٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرٍ وَٱلَّٰٓـِٔى لَمْ يَحِضْنَ وَأُو۟لَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًا', '623771ae5d79e2394870dd609e601994af32a8bfa70d16032a73a074c2fca102', 'وَٱلَّٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرٍ وَٱلَّٰٓـِٔى لَمْ يَحِضْنَ وَأُو۟لَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًا', '623771ae5d79e2394870dd609e601994af32a8bfa70d16032a73a074c2fca102', '623771ae5d79e2394870dd609e601994af32a8bfa70d16032a73a074c2fca102', NULL, 'والي يئسن من المحيض من نسائكم ان ارتبتم فعدتهن ثلثه اشهر والي لم يحضن واولت الاحمال اجلهن ان يضعن حملهن ومن يتق الله يجعل له من امره يسرا', 28, 56, 223, 1, 7, 558, false, NULL),
    (5222, 'tanzil-uthmani-v1.1', 65, 5, 'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا', 'c90ed9bb0cbb0326d86be1248b7292ec2403d06d8842b37656ffc0eb481f392a', 'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا', 'c90ed9bb0cbb0326d86be1248b7292ec2403d06d8842b37656ffc0eb481f392a', 'c90ed9bb0cbb0326d86be1248b7292ec2403d06d8842b37656ffc0eb481f392a', NULL, 'ذلك امر الله انزله اليكم ومن يتق الله يكفر عنه سياته ويعظم له اجرا', 28, 56, 223, 1, 7, 558, false, NULL),
    (5223, 'tanzil-uthmani-v1.1', 65, 6, 'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ وَإِن كُنَّ أُو۟لَٰتِ حَمْلٍ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ', 'fbd4156bfe04bc487a01b7292de955f50d27c29b84ec9fad16847075c1e222ea', 'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ وَإِن كُنَّ أُو۟لَٰتِ حَمْلٍ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ', 'fbd4156bfe04bc487a01b7292de955f50d27c29b84ec9fad16847075c1e222ea', 'fbd4156bfe04bc487a01b7292de955f50d27c29b84ec9fad16847075c1e222ea', NULL, 'اسكنوهن من حيث سكنتم من وجدكم ولا تضاروهن لتضيقوا عليهن وان كن اولت حمل فانفقوا عليهن حتي يضعن حملهن فان ارضعن لكم فاتوهن اجورهن واتمروا بينكم بمعروف وان تعاسرتم فسترضع له اخري', 28, 56, 223, 1, 7, 559, false, NULL),
    (5224, 'tanzil-uthmani-v1.1', 65, 7, 'لِيُنفِقْ ذُو سَعَةٍ مِّن سَعَتِهِۦ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍ يُسْرًا', 'bf06d6b9520e528dcc5e16c767b24a519fb7707b95da050360a4c9f589f8b401', 'لِيُنفِقْ ذُو سَعَةٍ مِّن سَعَتِهِۦ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍ يُسْرًا', 'bf06d6b9520e528dcc5e16c767b24a519fb7707b95da050360a4c9f589f8b401', 'bf06d6b9520e528dcc5e16c767b24a519fb7707b95da050360a4c9f589f8b401', NULL, 'لينفق ذو سعه من سعته ومن قدر عليه رزقه فلينفق مما ءاتيه الله لا يكلف الله نفسا الا ما ءاتيها سيجعل الله بعد عسر يسرا', 28, 56, 223, 1, 7, 559, false, NULL),
    (5225, 'tanzil-uthmani-v1.1', 65, 8, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَٰهَا حِسَابًا شَدِيدًا وَعَذَّبْنَٰهَا عَذَابًا نُّكْرًا', '1f161b8c6da1bed2687ffd3e711fdf1170b74202befa393f801535839d544ef1', 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَٰهَا حِسَابًا شَدِيدًا وَعَذَّبْنَٰهَا عَذَابًا نُّكْرًا', '1f161b8c6da1bed2687ffd3e711fdf1170b74202befa393f801535839d544ef1', '1f161b8c6da1bed2687ffd3e711fdf1170b74202befa393f801535839d544ef1', NULL, 'وكاين من قريه عتت عن امر ربها ورسله فحاسبنها حسابا شديدا وعذبنها عذابا نكرا', 28, 56, 223, 1, 7, 559, false, NULL),
    (5226, 'tanzil-uthmani-v1.1', 65, 9, 'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَٰقِبَةُ أَمْرِهَا خُسْرًا', 'cbca2eb9f6e057cd3c6452e71e32ea27575a333112bd211fb87198a07d5f8d65', 'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَٰقِبَةُ أَمْرِهَا خُسْرًا', 'cbca2eb9f6e057cd3c6452e71e32ea27575a333112bd211fb87198a07d5f8d65', 'cbca2eb9f6e057cd3c6452e71e32ea27575a333112bd211fb87198a07d5f8d65', NULL, 'فذاقت وبال امرها وكان عقبه امرها خسرا', 28, 56, 223, 1, 7, 559, false, NULL),
    (5227, 'tanzil-uthmani-v1.1', 65, 10, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ ٱلَّذِينَ ءَامَنُوا۟ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًا', 'ebd000533c5fc407a9c35d70a96f04a3e80714487988c7c7dd6d23c209d475ca', 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ ٱلَّذِينَ ءَامَنُوا۟ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًا', 'ebd000533c5fc407a9c35d70a96f04a3e80714487988c7c7dd6d23c209d475ca', 'ebd000533c5fc407a9c35d70a96f04a3e80714487988c7c7dd6d23c209d475ca', NULL, 'اعد الله لهم عذابا شديدا فاتقوا الله ياولي الالبب الذين ءامنوا قد انزل الله اليكم ذكرا', 28, 56, 223, 1, 7, 559, false, NULL),
    (5228, 'tanzil-uthmani-v1.1', 65, 11, 'رَّسُولًا يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٍ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًا يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا', '06ff4bf3055735a0f81c08e74c439ddca1560a89bb38d3fe33c7024bdb5892e3', 'رَّسُولًا يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٍ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًا يُدْخِلْهُ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًا قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا', '06ff4bf3055735a0f81c08e74c439ddca1560a89bb38d3fe33c7024bdb5892e3', '06ff4bf3055735a0f81c08e74c439ddca1560a89bb38d3fe33c7024bdb5892e3', NULL, 'رسولا يتلوا عليكم ءايت الله مبينت ليخرج الذين ءامنوا وعملوا الصلحت من الظلمت الي النور ومن يؤمن بالله ويعمل صلحا يدخله جنت تجري من تحتها الانهر خلدين فيها ابدا قد احسن الله له رزقا', 28, 56, 223, 1, 7, 559, false, NULL),
    (5229, 'tanzil-uthmani-v1.1', 65, 12, 'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا', 'cbbde24144b0133022eed7f2f47e4fff3c445a4baacd1ec0e12d41f18a2a22f8', 'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا', 'cbbde24144b0133022eed7f2f47e4fff3c445a4baacd1ec0e12d41f18a2a22f8', 'cbbde24144b0133022eed7f2f47e4fff3c445a4baacd1ec0e12d41f18a2a22f8', NULL, 'الله الذي خلق سبع سموت ومن الارض مثلهن يتنزل الامر بينهن لتعلموا ان الله علي كل شيء قدير وان الله قد احاط بكل شيء علما', 28, 56, 223, 1, 7, 559, false, NULL),
    (5230, 'tanzil-uthmani-v1.1', 66, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '17876351d16a4c3d835fa528a9f67ae532c7f35580c2d865a039f67bcb33de2b', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', '3042a04bb8bfe31057648ed1c4c73303e0b19a44fb28ac579cb04db84fc0a813', '3042a04bb8bfe31057648ed1c4c73303e0b19a44fb28ac579cb04db84fc0a813', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'يايها النبي لم تحرم ما احل الله لك تبتغي مرضات ازوجك والله غفور رحيم', 28, 56, 224, 1, 7, 560, false, NULL),
    (5231, 'tanzil-uthmani-v1.1', 66, 2, 'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ وَٱللَّهُ مَوْلَىٰكُمْ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '6d40febbd58d18c1d7ff652804eaceecd31ab0fa620b9f7a506500928a707b4b', 'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ وَٱللَّهُ مَوْلَىٰكُمْ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', '6d40febbd58d18c1d7ff652804eaceecd31ab0fa620b9f7a506500928a707b4b', '6d40febbd58d18c1d7ff652804eaceecd31ab0fa620b9f7a506500928a707b4b', NULL, 'قد فرض الله لكم تحله ايمنكم والله موليكم وهو العليم الحكيم', 28, 56, 224, 1, 7, 560, false, NULL),
    (5232, 'tanzil-uthmani-v1.1', 66, 3, 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَٰذَا قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ', '7d445f4bd1ab0cecf4f79eba4323def229cf1a60631f929f2e2d1c0d9fb0821a', 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَٰذَا قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ', '7d445f4bd1ab0cecf4f79eba4323def229cf1a60631f929f2e2d1c0d9fb0821a', '7d445f4bd1ab0cecf4f79eba4323def229cf1a60631f929f2e2d1c0d9fb0821a', NULL, 'واذ اسر النبي الي بعض ازوجه حديثا فلما نبات به واظهره الله عليه عرف بعضه واعرض عن بعض فلما نباها به قالت من انباك هذا قال نباني العليم الخبير', 28, 56, 224, 1, 7, 560, false, NULL),
    (5233, 'tanzil-uthmani-v1.1', 66, 4, 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا وَإِن تَظَٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَٰلِحُ ٱلْمُؤْمِنِينَ وَٱلْمَلَٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ', '3c3d7f5b1a051d088441acfd04661e5f1cab897769e14af0c0c0402a49c1fdb0', 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا وَإِن تَظَٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَٰلِحُ ٱلْمُؤْمِنِينَ وَٱلْمَلَٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ', '3c3d7f5b1a051d088441acfd04661e5f1cab897769e14af0c0c0402a49c1fdb0', '3c3d7f5b1a051d088441acfd04661e5f1cab897769e14af0c0c0402a49c1fdb0', NULL, 'ان تتوبا الي الله فقد صغت قلوبكما وان تظهرا عليه فان الله هو موليه وجبريل وصلح المؤمنين والملئكه بعد ذلك ظهير', 28, 56, 224, 1, 7, 560, false, NULL),
    (5234, 'tanzil-uthmani-v1.1', 66, 5, 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًا مِّنكُنَّ مُسْلِمَٰتٍ مُّؤْمِنَٰتٍ قَٰنِتَٰتٍ تَٰٓئِبَٰتٍ عَٰبِدَٰتٍ سَٰٓئِحَٰتٍ ثَيِّبَٰتٍ وَأَبْكَارًا', '217d615eb407ba97fd2d22748cbb5535ab52c72c682919ba5a70ead00d96630d', 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًا مِّنكُنَّ مُسْلِمَٰتٍ مُّؤْمِنَٰتٍ قَٰنِتَٰتٍ تَٰٓئِبَٰتٍ عَٰبِدَٰتٍ سَٰٓئِحَٰتٍ ثَيِّبَٰتٍ وَأَبْكَارًا', '217d615eb407ba97fd2d22748cbb5535ab52c72c682919ba5a70ead00d96630d', '217d615eb407ba97fd2d22748cbb5535ab52c72c682919ba5a70ead00d96630d', NULL, 'عسي ربه ان طلقكن ان يبدله ازوجا خيرا منكن مسلمت مؤمنت قنتت تئبت عبدت سئحت ثيبت وابكارا', 28, 56, 224, 1, 7, 560, false, NULL),
    (5235, 'tanzil-uthmani-v1.1', 66, 6, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', '5e13d186d38c6d6718a8d69f29fc8bf371a25ca3236219a8f16dc0470877ec47', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', '5e13d186d38c6d6718a8d69f29fc8bf371a25ca3236219a8f16dc0470877ec47', '5e13d186d38c6d6718a8d69f29fc8bf371a25ca3236219a8f16dc0470877ec47', NULL, 'يايها الذين ءامنوا قوا انفسكم واهليكم نارا وقودها الناس والحجاره عليها ملئكه غلاظ شداد لا يعصون الله ما امرهم ويفعلون ما يؤمرون', 28, 56, 224, 1, 7, 560, false, NULL),
    (5236, 'tanzil-uthmani-v1.1', 66, 7, 'يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'd50e56e8df9dc9caae0cc5f0da1d806620946642c317d04753f970814be069a5', 'يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 'd50e56e8df9dc9caae0cc5f0da1d806620946642c317d04753f970814be069a5', 'd50e56e8df9dc9caae0cc5f0da1d806620946642c317d04753f970814be069a5', NULL, 'يايها الذين كفروا لا تعتذروا اليوم انما تجزون ما كنتم تعملون', 28, 56, 224, 1, 7, 560, false, NULL),
    (5237, 'tanzil-uthmani-v1.1', 66, 8, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '99817277b49b121af619f2322f174f47692bc6e3788e0cc2c63bc3e4faf9f954', 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', '99817277b49b121af619f2322f174f47692bc6e3788e0cc2c63bc3e4faf9f954', '99817277b49b121af619f2322f174f47692bc6e3788e0cc2c63bc3e4faf9f954', NULL, 'يايها الذين ءامنوا توبوا الي الله توبه نصوحا عسي ربكم ان يكفر عنكم سياتكم ويدخلكم جنت تجري من تحتها الانهر يوم لا يخزي الله النبي والذين ءامنوا معه نورهم يسعي بين ايديهم وبايمنهم يقولون ربنا اتمم لنا نورنا واغفر لنا انك علي كل شيء قدير', 28, 56, 224, 1, 7, 561, false, NULL),
    (5238, 'tanzil-uthmani-v1.1', 66, 9, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'a139f24252aceaca90815affeaad879ea850f82261322d9a23939de18e793cc7', 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ وَمَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمَصِيرُ', 'a139f24252aceaca90815affeaad879ea850f82261322d9a23939de18e793cc7', 'a139f24252aceaca90815affeaad879ea850f82261322d9a23939de18e793cc7', NULL, 'يايها النبي جهد الكفار والمنفقين واغلظ عليهم وماويهم جهنم وبئس المصير', 28, 56, 224, 1, 7, 561, false, NULL),
    (5239, 'tanzil-uthmani-v1.1', 66, 10, 'ضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍ وَٱمْرَأَتَ لُوطٍ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', '30cfa224f1d5095cb262d95ec64f46691e0ca2720d3afe308e14a8b70d18f991', 'ضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍ وَٱمْرَأَتَ لُوطٍ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', '30cfa224f1d5095cb262d95ec64f46691e0ca2720d3afe308e14a8b70d18f991', '30cfa224f1d5095cb262d95ec64f46691e0ca2720d3afe308e14a8b70d18f991', NULL, 'ضرب الله مثلا للذين كفروا امرات نوح وامرات لوط كانتا تحت عبدين من عبادنا صلحين فخانتاهما فلم يغنيا عنهما من الله شيا وقيل ادخلا النار مع الدخلين', 28, 56, 224, 1, 7, 561, false, NULL),
    (5240, 'tanzil-uthmani-v1.1', 66, 11, 'وَضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'a0eeac6b6d191f13000d16a7d42d303498da01c347ce31244170e531f39abc88', 'وَضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 'a0eeac6b6d191f13000d16a7d42d303498da01c347ce31244170e531f39abc88', 'a0eeac6b6d191f13000d16a7d42d303498da01c347ce31244170e531f39abc88', NULL, 'وضرب الله مثلا للذين ءامنوا امرات فرعون اذ قالت رب ابن لي عندك بيتا في الجنه ونجني من فرعون وعمله ونجني من القوم الظلمين', 28, 56, 224, 1, 7, 561, false, NULL),
    (5241, 'tanzil-uthmani-v1.1', 66, 12, 'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَٰنِتِينَ', '607ede0bfbe2eafa7e35ccb29e247b0a8489e5fb1145ba7ef1df22014512828f', 'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَٰنِتِينَ', '607ede0bfbe2eafa7e35ccb29e247b0a8489e5fb1145ba7ef1df22014512828f', '607ede0bfbe2eafa7e35ccb29e247b0a8489e5fb1145ba7ef1df22014512828f', NULL, 'ومريم ابنت عمرن التي احصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمت ربها وكتبه وكانت من القنتين', 28, 56, 224, 1, 7, 561, false, NULL),
    (5242, 'tanzil-uthmani-v1.1', 67, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'a10b8b0844636155d30050d2fbe8d6142377ef7b410c9b73d616dcde575c1300', 'تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 'f0b85333a28a6ab024d9cd2b36dc29f2bea7947f82ca188571eace702506bc07', 'f0b85333a28a6ab024d9cd2b36dc29f2bea7947f82ca188571eace702506bc07', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'تبرك الذي بيده الملك وهو علي كل شيء قدير', 29, 57, 225, 1, 7, 562, false, NULL),
    (5243, 'tanzil-uthmani-v1.1', 67, 2, 'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ', 'f4f31681e92b522ef934e8baa6fb38ede1ea5abe5c3e7f1b1d6111eea131f484', 'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ', 'f4f31681e92b522ef934e8baa6fb38ede1ea5abe5c3e7f1b1d6111eea131f484', 'f4f31681e92b522ef934e8baa6fb38ede1ea5abe5c3e7f1b1d6111eea131f484', NULL, 'الذي خلق الموت والحيوه ليبلوكم ايكم احسن عملا وهو العزيز الغفور', 29, 57, 225, 1, 7, 562, false, NULL),
    (5244, 'tanzil-uthmani-v1.1', 67, 3, 'ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍ طِبَاقًا مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ', '3535f7b08dd1173b14d05658cc8e7abe6e703148da1c48443d2192d895b015c2', 'ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍ طِبَاقًا مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ', '3535f7b08dd1173b14d05658cc8e7abe6e703148da1c48443d2192d895b015c2', '3535f7b08dd1173b14d05658cc8e7abe6e703148da1c48443d2192d895b015c2', NULL, 'الذي خلق سبع سموت طباقا ما تري في خلق الرحمن من تفوت فارجع البصر هل تري من فطور', 29, 57, 225, 1, 7, 562, false, NULL),
    (5245, 'tanzil-uthmani-v1.1', 67, 4, 'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ', 'cd5ae64429c8c1de21706b48596f6ce86c64644ab8c61aab116ee74072b6d8cd', 'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ', 'cd5ae64429c8c1de21706b48596f6ce86c64644ab8c61aab116ee74072b6d8cd', 'cd5ae64429c8c1de21706b48596f6ce86c64644ab8c61aab116ee74072b6d8cd', NULL, 'ثم ارجع البصر كرتين ينقلب اليك البصر خاسئا وهو حسير', 29, 57, 225, 1, 7, 562, false, NULL),
    (5246, 'tanzil-uthmani-v1.1', 67, 5, 'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًا لِّلشَّيَٰطِينِ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ', '903c169a285ef8e3480dddabb401e9c5e8282b104715625965c2cdea4b5e6e3f', 'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًا لِّلشَّيَٰطِينِ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ', '903c169a285ef8e3480dddabb401e9c5e8282b104715625965c2cdea4b5e6e3f', '903c169a285ef8e3480dddabb401e9c5e8282b104715625965c2cdea4b5e6e3f', NULL, 'ولقد زينا السماء الدنيا بمصبيح وجعلنها رجوما للشيطين واعتدنا لهم عذاب السعير', 29, 57, 225, 1, 7, 562, false, NULL),
    (5247, 'tanzil-uthmani-v1.1', 67, 6, 'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ وَبِئْسَ ٱلْمَصِيرُ', 'd5232709e5de6dc12ab94169283001438835ccf9d9e6cdf53f880f141ca5438e', 'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ وَبِئْسَ ٱلْمَصِيرُ', 'd5232709e5de6dc12ab94169283001438835ccf9d9e6cdf53f880f141ca5438e', 'd5232709e5de6dc12ab94169283001438835ccf9d9e6cdf53f880f141ca5438e', NULL, 'وللذين كفروا بربهم عذاب جهنم وبئس المصير', 29, 57, 225, 1, 7, 562, false, NULL),
    (5248, 'tanzil-uthmani-v1.1', 67, 7, 'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًا وَهِىَ تَفُورُ', '7ca48bf50fa9df0955746031e01f939c9d730b6113a8115face88556f4865413', 'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًا وَهِىَ تَفُورُ', '7ca48bf50fa9df0955746031e01f939c9d730b6113a8115face88556f4865413', '7ca48bf50fa9df0955746031e01f939c9d730b6113a8115face88556f4865413', NULL, 'اذا القوا فيها سمعوا لها شهيقا وهي تفور', 29, 57, 225, 1, 7, 562, false, NULL),
    (5249, 'tanzil-uthmani-v1.1', 67, 8, 'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌ', 'cb925a5beac49964378b5c3fd5826afa3bf471e35518df8bbf8dcdc5780a684f', 'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌ', 'cb925a5beac49964378b5c3fd5826afa3bf471e35518df8bbf8dcdc5780a684f', 'cb925a5beac49964378b5c3fd5826afa3bf471e35518df8bbf8dcdc5780a684f', NULL, 'تكاد تميز من الغيظ كلما القي فيها فوج سالهم خزنتها الم ياتكم نذير', 29, 57, 225, 1, 7, 562, false, NULL),
    (5250, 'tanzil-uthmani-v1.1', 67, 9, 'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ كَبِيرٍ', '5d6bbcd04d400fc29bfe300adf57967f87f8bcdb5f918b445c4a3e5797df86e2', 'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ كَبِيرٍ', '5d6bbcd04d400fc29bfe300adf57967f87f8bcdb5f918b445c4a3e5797df86e2', '5d6bbcd04d400fc29bfe300adf57967f87f8bcdb5f918b445c4a3e5797df86e2', NULL, 'قالوا بلي قد جاءنا نذير فكذبنا وقلنا ما نزل الله من شيء ان انتم الا في ضلل كبير', 29, 57, 225, 1, 7, 562, false, NULL),
    (5251, 'tanzil-uthmani-v1.1', 67, 10, 'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ', '7cbd12c02336a4146b63a99fe788d4fc8f6405518e52db8ad8d79c318d4e7aac', 'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ', '7cbd12c02336a4146b63a99fe788d4fc8f6405518e52db8ad8d79c318d4e7aac', '7cbd12c02336a4146b63a99fe788d4fc8f6405518e52db8ad8d79c318d4e7aac', NULL, 'وقالوا لو كنا نسمع او نعقل ما كنا في اصحب السعير', 29, 57, 225, 1, 7, 562, false, NULL),
    (5252, 'tanzil-uthmani-v1.1', 67, 11, 'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًا لِّأَصْحَٰبِ ٱلسَّعِيرِ', '47c6f84a96140c87d0d63dc9554b129b9aca2ec57b4fe4947fd49ee260dcdd69', 'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًا لِّأَصْحَٰبِ ٱلسَّعِيرِ', '47c6f84a96140c87d0d63dc9554b129b9aca2ec57b4fe4947fd49ee260dcdd69', '47c6f84a96140c87d0d63dc9554b129b9aca2ec57b4fe4947fd49ee260dcdd69', NULL, 'فاعترفوا بذنبهم فسحقا لاصحب السعير', 29, 57, 225, 1, 7, 562, false, NULL),
    (5253, 'tanzil-uthmani-v1.1', 67, 12, 'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', 'c83ed278ccc9c6a2fe8a045ac732029b183e5331102e9650715de3c05979ac42', 'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', 'c83ed278ccc9c6a2fe8a045ac732029b183e5331102e9650715de3c05979ac42', 'c83ed278ccc9c6a2fe8a045ac732029b183e5331102e9650715de3c05979ac42', NULL, 'ان الذين يخشون ربهم بالغيب لهم مغفره واجر كبير', 29, 57, 225, 1, 7, 562, false, NULL),
    (5254, 'tanzil-uthmani-v1.1', 67, 13, 'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '9a65bb0119e8d0c8163fd24df58c15e81fc5fef58d9e40f615dc119263a63832', 'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', '9a65bb0119e8d0c8163fd24df58c15e81fc5fef58d9e40f615dc119263a63832', '9a65bb0119e8d0c8163fd24df58c15e81fc5fef58d9e40f615dc119263a63832', NULL, 'واسروا قولكم او اجهروا به انه عليم بذات الصدور', 29, 57, 225, 1, 7, 563, false, NULL),
    (5255, 'tanzil-uthmani-v1.1', 67, 14, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'b2ce9be1537c94657dcb6546ced93573383a7dabc013e6fc2f64fda819cea043', 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'b2ce9be1537c94657dcb6546ced93573383a7dabc013e6fc2f64fda819cea043', 'b2ce9be1537c94657dcb6546ced93573383a7dabc013e6fc2f64fda819cea043', NULL, 'الا يعلم من خلق وهو اللطيف الخبير', 29, 57, 225, 1, 7, 563, false, NULL),
    (5256, 'tanzil-uthmani-v1.1', 67, 15, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ وَإِلَيْهِ ٱلنُّشُورُ', '55720f667680536c1b0b3e0c9d70eb392d29710ee83b15bd8f276b1180d14cf0', 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ وَإِلَيْهِ ٱلنُّشُورُ', '55720f667680536c1b0b3e0c9d70eb392d29710ee83b15bd8f276b1180d14cf0', '55720f667680536c1b0b3e0c9d70eb392d29710ee83b15bd8f276b1180d14cf0', NULL, 'هو الذي جعل لكم الارض ذلولا فامشوا في مناكبها وكلوا من رزقه واليه النشور', 29, 57, 225, 1, 7, 563, false, NULL),
    (5257, 'tanzil-uthmani-v1.1', 67, 16, 'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ', 'addee67f6aaec6dec96311888646b014261f3465da03cef7ff5e5fce2a0c44d1', 'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ', 'addee67f6aaec6dec96311888646b014261f3465da03cef7ff5e5fce2a0c44d1', 'addee67f6aaec6dec96311888646b014261f3465da03cef7ff5e5fce2a0c44d1', NULL, 'ءامنتم من في السماء ان يخسف بكم الارض فاذا هي تمور', 29, 57, 225, 1, 7, 563, false, NULL),
    (5258, 'tanzil-uthmani-v1.1', 67, 17, 'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ', 'fe23bb19a4549c117021bb9de12b0d4f5a308240c042520776d2cbc18a8b1a05', 'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ', 'fe23bb19a4549c117021bb9de12b0d4f5a308240c042520776d2cbc18a8b1a05', 'fe23bb19a4549c117021bb9de12b0d4f5a308240c042520776d2cbc18a8b1a05', NULL, 'ام امنتم من في السماء ان يرسل عليكم حاصبا فستعلمون كيف نذير', 29, 57, 225, 1, 7, 563, false, NULL),
    (5259, 'tanzil-uthmani-v1.1', 67, 18, 'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ', 'd7eea590227f2b88feda9703e96719ec91f153805fd117305df03712f3622665', 'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ', 'd7eea590227f2b88feda9703e96719ec91f153805fd117305df03712f3622665', 'd7eea590227f2b88feda9703e96719ec91f153805fd117305df03712f3622665', NULL, 'ولقد كذب الذين من قبلهم فكيف كان نكير', 29, 57, 225, 1, 7, 563, false, NULL),
    (5260, 'tanzil-uthmani-v1.1', 67, 19, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٍ وَيَقْبِضْنَ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَٰنُ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ', '2456217e3f2d0acab13867a1a4da19ca4f7d95f16468a1093921b5bd2c308fa3', 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٍ وَيَقْبِضْنَ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَٰنُ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ', '2456217e3f2d0acab13867a1a4da19ca4f7d95f16468a1093921b5bd2c308fa3', '2456217e3f2d0acab13867a1a4da19ca4f7d95f16468a1093921b5bd2c308fa3', NULL, 'اولم يروا الي الطير فوقهم صفت ويقبضن ما يمسكهن الا الرحمن انه بكل شيء بصير', 29, 57, 225, 1, 7, 563, false, NULL),
    (5261, 'tanzil-uthmani-v1.1', 67, 20, 'أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ', '84c6838bb8619b618ded232e4bc638c9e38ca0e166204b9c8b43ce6a3ab74689', 'أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ', '84c6838bb8619b618ded232e4bc638c9e38ca0e166204b9c8b43ce6a3ab74689', '84c6838bb8619b618ded232e4bc638c9e38ca0e166204b9c8b43ce6a3ab74689', NULL, 'امن هذا الذي هو جند لكم ينصركم من دون الرحمن ان الكفرون الا في غرور', 29, 57, 225, 1, 7, 563, false, NULL),
    (5262, 'tanzil-uthmani-v1.1', 67, 21, 'أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ بَل لَّجُّوا۟ فِى عُتُوٍّ وَنُفُورٍ', 'cfdd14f46d679d9af1ecb99ffaa82af7d0bf10d30f2319375d35a0d901b1f4a3', 'أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ بَل لَّجُّوا۟ فِى عُتُوٍّ وَنُفُورٍ', 'cfdd14f46d679d9af1ecb99ffaa82af7d0bf10d30f2319375d35a0d901b1f4a3', 'cfdd14f46d679d9af1ecb99ffaa82af7d0bf10d30f2319375d35a0d901b1f4a3', NULL, 'امن هذا الذي يرزقكم ان امسك رزقه بل لجوا في عتو ونفور', 29, 57, 225, 1, 7, 563, false, NULL),
    (5263, 'tanzil-uthmani-v1.1', 67, 22, 'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '1b499da13f7ded78fd51913cd4f43b714eb67b80f3caa83fb340ba6a6ecfc5c2', 'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', '1b499da13f7ded78fd51913cd4f43b714eb67b80f3caa83fb340ba6a6ecfc5c2', '1b499da13f7ded78fd51913cd4f43b714eb67b80f3caa83fb340ba6a6ecfc5c2', NULL, 'افمن يمشي مكبا علي وجهه اهدي امن يمشي سويا علي صرط مستقيم', 29, 57, 225, 1, 7, 563, false, NULL),
    (5264, 'tanzil-uthmani-v1.1', 67, 23, 'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', 'becd37d5bc7cd0d16d574a894b72aedd28a924d8f4064f114012f00c189de3ac', 'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ قَلِيلًا مَّا تَشْكُرُونَ', 'becd37d5bc7cd0d16d574a894b72aedd28a924d8f4064f114012f00c189de3ac', 'becd37d5bc7cd0d16d574a894b72aedd28a924d8f4064f114012f00c189de3ac', NULL, 'قل هو الذي انشاكم وجعل لكم السمع والابصر والافده قليلا ما تشكرون', 29, 57, 225, 1, 7, 563, false, NULL),
    (5265, 'tanzil-uthmani-v1.1', 67, 24, 'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 'd1eb4c820cf4520baffdf43092d0e26493540d1cc54fce1e32c732a8e4ffb8f7', 'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 'd1eb4c820cf4520baffdf43092d0e26493540d1cc54fce1e32c732a8e4ffb8f7', 'd1eb4c820cf4520baffdf43092d0e26493540d1cc54fce1e32c732a8e4ffb8f7', NULL, 'قل هو الذي ذراكم في الارض واليه تحشرون', 29, 57, 225, 1, 7, 563, false, NULL),
    (5266, 'tanzil-uthmani-v1.1', 67, 25, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', '2bbfd28a3f34f46b131d25d09f0cda99933ec52a6f651aa081fa14d3d2001ef9', NULL, 'ويقولون متي هذا الوعد ان كنتم صدقين', 29, 57, 225, 1, 7, 563, false, NULL),
    (5267, 'tanzil-uthmani-v1.1', 67, 26, 'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'ad744032966e4a51c493f30e1acec79e5b87d07a542b21c4530f2a9f52157aa0', 'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 'ad744032966e4a51c493f30e1acec79e5b87d07a542b21c4530f2a9f52157aa0', 'ad744032966e4a51c493f30e1acec79e5b87d07a542b21c4530f2a9f52157aa0', NULL, 'قل انما العلم عند الله وانما انا نذير مبين', 29, 57, 225, 1, 7, 563, false, NULL),
    (5268, 'tanzil-uthmani-v1.1', 67, 27, 'فَلَمَّا رَأَوْهُ زُلْفَةً سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ', '2421671b2bdc88b61c28b492db9a018bbfbee1cff52c2a76cb23058067389013', 'فَلَمَّا رَأَوْهُ زُلْفَةً سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ', '2421671b2bdc88b61c28b492db9a018bbfbee1cff52c2a76cb23058067389013', '2421671b2bdc88b61c28b492db9a018bbfbee1cff52c2a76cb23058067389013', NULL, 'فلما راوه زلفه سيت وجوه الذين كفروا وقيل هذا الذي كنتم به تدعون', 29, 57, 225, 1, 7, 564, false, NULL),
    (5269, 'tanzil-uthmani-v1.1', 67, 28, 'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍ', 'c9ee2323306b07841b9ff7869fc5a90d925a6138963aee482667ecba72e8a4bf', 'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍ', 'c9ee2323306b07841b9ff7869fc5a90d925a6138963aee482667ecba72e8a4bf', 'c9ee2323306b07841b9ff7869fc5a90d925a6138963aee482667ecba72e8a4bf', NULL, 'قل ارءيتم ان اهلكني الله ومن معي او رحمنا فمن يجير الكفرين من عذاب اليم', 29, 57, 225, 1, 7, 564, false, NULL),
    (5270, 'tanzil-uthmani-v1.1', 67, 29, 'قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ', '1f857ae626d85b3268cb5fdb3bd1febb8f725b6ffaa1d4ab4b8049ab4c1a50d9', 'قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ', '1f857ae626d85b3268cb5fdb3bd1febb8f725b6ffaa1d4ab4b8049ab4c1a50d9', '1f857ae626d85b3268cb5fdb3bd1febb8f725b6ffaa1d4ab4b8049ab4c1a50d9', NULL, 'قل هو الرحمن ءامنا به وعليه توكلنا فستعلمون من هو في ضلل مبين', 29, 57, 225, 1, 7, 564, false, NULL),
