    (5419, 'tanzil-uthmani-v1.1', 70, 44, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 'fbcbaf28a06a8644939d80ecd276df266105fe2754bc9a3d8b20c072608b0bb8', 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 'fbcbaf28a06a8644939d80ecd276df266105fe2754bc9a3d8b20c072608b0bb8', 'fbcbaf28a06a8644939d80ecd276df266105fe2754bc9a3d8b20c072608b0bb8', NULL, 'خشعه ابصرهم ترهقهم ذله ذلك اليوم الذي كانوا يوعدون', 29, 57, 228, 1, 7, 570, false, NULL),
    (5420, 'tanzil-uthmani-v1.1', 71, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ', '3f2b88c772504f8402e78da092ec9d8e032d36ffb22a4a757bd2891b0c9aca21', 'إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ', 'ea3db68a09efaef89d8ae6feb24d2c25e9b6756b81771afb8962ade385f783a2', 'ea3db68a09efaef89d8ae6feb24d2c25e9b6756b81771afb8962ade385f783a2', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'انا ارسلنا نوحا الي قومه ان انذر قومك من قبل ان ياتيهم عذاب اليم', 29, 57, 228, 1, 7, 570, false, NULL),
    (5421, 'tanzil-uthmani-v1.1', 71, 2, 'قَالَ يَٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', '7c48b6226c17d56624e6a3767de21ffcd0a130b11e2d4bc414c26bd1f5400ec3', 'قَالَ يَٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', '7c48b6226c17d56624e6a3767de21ffcd0a130b11e2d4bc414c26bd1f5400ec3', '7c48b6226c17d56624e6a3767de21ffcd0a130b11e2d4bc414c26bd1f5400ec3', NULL, 'قال يقوم اني لكم نذير مبين', 29, 57, 228, 1, 7, 570, false, NULL),
    (5422, 'tanzil-uthmani-v1.1', 71, 3, 'أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ', '77ba9e27613054749f322752d731600cccc4374dc1b420abd35f130aa81f98cc', 'أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ', '77ba9e27613054749f322752d731600cccc4374dc1b420abd35f130aa81f98cc', '77ba9e27613054749f322752d731600cccc4374dc1b420abd35f130aa81f98cc', NULL, 'ان اعبدوا الله واتقوه واطيعون', 29, 57, 228, 1, 7, 570, false, NULL),
    (5423, 'tanzil-uthmani-v1.1', 71, 4, 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ لَوْ كُنتُمْ تَعْلَمُونَ', '82afec5291aeab72011b1eda69a0f059fc25abe60b16c397ccd6164f8d25b5ea', 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ لَوْ كُنتُمْ تَعْلَمُونَ', '82afec5291aeab72011b1eda69a0f059fc25abe60b16c397ccd6164f8d25b5ea', '82afec5291aeab72011b1eda69a0f059fc25abe60b16c397ccd6164f8d25b5ea', NULL, 'يغفر لكم من ذنوبكم ويؤخركم الي اجل مسمي ان اجل الله اذا جاء لا يؤخر لو كنتم تعلمون', 29, 57, 228, 1, 7, 570, false, NULL),
    (5424, 'tanzil-uthmani-v1.1', 71, 5, 'قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًا وَنَهَارًا', 'a363c05e5b80139d66878f0fdcebde9b30d7197765ef7dbc462709587b1d272f', 'قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًا وَنَهَارًا', 'a363c05e5b80139d66878f0fdcebde9b30d7197765ef7dbc462709587b1d272f', 'a363c05e5b80139d66878f0fdcebde9b30d7197765ef7dbc462709587b1d272f', NULL, 'قال رب اني دعوت قومي ليلا ونهارا', 29, 57, 228, 1, 7, 570, false, NULL),
    (5425, 'tanzil-uthmani-v1.1', 71, 6, 'فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًا', 'a4c802c524134f3db0003ea61ece0b06bc151a0d4445543cf4ad83d5e02f3c3d', 'فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًا', 'a4c802c524134f3db0003ea61ece0b06bc151a0d4445543cf4ad83d5e02f3c3d', 'a4c802c524134f3db0003ea61ece0b06bc151a0d4445543cf4ad83d5e02f3c3d', NULL, 'فلم يزدهم دعاءي الا فرارا', 29, 57, 228, 1, 7, 570, false, NULL),
    (5426, 'tanzil-uthmani-v1.1', 71, 7, 'وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًا', '58905f3dd28bb754ce7ef96a552f7b0213d335535241a310ead5f08f17846b8f', 'وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًا', '58905f3dd28bb754ce7ef96a552f7b0213d335535241a310ead5f08f17846b8f', '58905f3dd28bb754ce7ef96a552f7b0213d335535241a310ead5f08f17846b8f', NULL, 'واني كلما دعوتهم لتغفر لهم جعلوا اصبعهم في ءاذانهم واستغشوا ثيابهم واصروا واستكبروا استكبارا', 29, 57, 228, 1, 7, 570, false, NULL),
    (5427, 'tanzil-uthmani-v1.1', 71, 8, 'ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًا', '1ba08a6665e50215d69b36fc2152e563c7394f3384c992960c843e1efed3342e', 'ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًا', '1ba08a6665e50215d69b36fc2152e563c7394f3384c992960c843e1efed3342e', '1ba08a6665e50215d69b36fc2152e563c7394f3384c992960c843e1efed3342e', NULL, 'ثم اني دعوتهم جهارا', 29, 57, 228, 1, 7, 570, false, NULL),
    (5428, 'tanzil-uthmani-v1.1', 71, 9, 'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا', '56c0b48ae339a617fe6ebbaa9ae6a47e81e522af0c060e2541e661f1811ccab1', 'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا', '56c0b48ae339a617fe6ebbaa9ae6a47e81e522af0c060e2541e661f1811ccab1', '56c0b48ae339a617fe6ebbaa9ae6a47e81e522af0c060e2541e661f1811ccab1', NULL, 'ثم اني اعلنت لهم واسررت لهم اسرارا', 29, 57, 228, 1, 7, 570, false, NULL),
