    (5438, 'tanzil-uthmani-v1.1', 71, 19, 'وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًا', '8b4ab801e599cbb84626de77810a0d58877e267a8873b303ff716086584668f5', 'وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًا', '8b4ab801e599cbb84626de77810a0d58877e267a8873b303ff716086584668f5', '8b4ab801e599cbb84626de77810a0d58877e267a8873b303ff716086584668f5', NULL, 'والله جعل لكم الارض بساطا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5439, 'tanzil-uthmani-v1.1', 71, 20, 'لِّتَسْلُكُوا۟ مِنْهَا سُبُلًا فِجَاجًا', '8702d5d462ef506e6e62cc19bb46a6187a84935d27126a694a56c63a49155587', 'لِّتَسْلُكُوا۟ مِنْهَا سُبُلًا فِجَاجًا', '8702d5d462ef506e6e62cc19bb46a6187a84935d27126a694a56c63a49155587', '8702d5d462ef506e6e62cc19bb46a6187a84935d27126a694a56c63a49155587', NULL, 'لتسلكوا منها سبلا فجاجا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5440, 'tanzil-uthmani-v1.1', 71, 21, 'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًا', 'ce4a22e39ef300d8f6ac9ec736b23d956e084ae1f593a3ec34e550ba13d3e28b', 'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًا', 'ce4a22e39ef300d8f6ac9ec736b23d956e084ae1f593a3ec34e550ba13d3e28b', 'ce4a22e39ef300d8f6ac9ec736b23d956e084ae1f593a3ec34e550ba13d3e28b', NULL, 'قال نوح رب انهم عصوني واتبعوا من لم يزده ماله وولده الا خسارا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5441, 'tanzil-uthmani-v1.1', 71, 22, 'وَمَكَرُوا۟ مَكْرًا كُبَّارًا', '14a637a4291c20020b26fddd7058abb41ee2ce06b53e3c9b179de005ed4158fa', 'وَمَكَرُوا۟ مَكْرًا كُبَّارًا', '14a637a4291c20020b26fddd7058abb41ee2ce06b53e3c9b179de005ed4158fa', '14a637a4291c20020b26fddd7058abb41ee2ce06b53e3c9b179de005ed4158fa', NULL, 'ومكروا مكرا كبارا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5442, 'tanzil-uthmani-v1.1', 71, 23, 'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا', '6898c336a454e24b90359f55d064266d9265e549e98129687c117e0fce2e458f', 'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا', '6898c336a454e24b90359f55d064266d9265e549e98129687c117e0fce2e458f', '6898c336a454e24b90359f55d064266d9265e549e98129687c117e0fce2e458f', NULL, 'وقالوا لا تذرن ءالهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5443, 'tanzil-uthmani-v1.1', 71, 24, 'وَقَدْ أَضَلُّوا۟ كَثِيرًا وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا ضَلَٰلًا', 'aaa29ccd36fa4174cf0ff36606bbf00f74df9a2c372cd6eac5284b7077768e02', 'وَقَدْ أَضَلُّوا۟ كَثِيرًا وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا ضَلَٰلًا', 'aaa29ccd36fa4174cf0ff36606bbf00f74df9a2c372cd6eac5284b7077768e02', 'aaa29ccd36fa4174cf0ff36606bbf00f74df9a2c372cd6eac5284b7077768e02', NULL, 'وقد اضلوا كثيرا ولا تزد الظلمين الا ضللا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5444, 'tanzil-uthmani-v1.1', 71, 25, 'مِّمَّا خَطِيٓـَٰٔتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًا', '8f5167617e415d3f1dc8dabed506204b296d808f873b578816ac37517d30c4d4', 'مِّمَّا خَطِيٓـَٰٔتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًا', '8f5167617e415d3f1dc8dabed506204b296d808f873b578816ac37517d30c4d4', '8f5167617e415d3f1dc8dabed506204b296d808f873b578816ac37517d30c4d4', NULL, 'مما خطيتهم اغرقوا فادخلوا نارا فلم يجدوا لهم من دون الله انصارا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5445, 'tanzil-uthmani-v1.1', 71, 26, 'وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَٰفِرِينَ دَيَّارًا', 'fd1af4b9df6c1a01c1a1e8e3c754b25e4de3f5d586a034994629ebf3e2d36930', 'وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَٰفِرِينَ دَيَّارًا', 'fd1af4b9df6c1a01c1a1e8e3c754b25e4de3f5d586a034994629ebf3e2d36930', 'fd1af4b9df6c1a01c1a1e8e3c754b25e4de3f5d586a034994629ebf3e2d36930', NULL, 'وقال نوح رب لا تذر علي الارض من الكفرين ديارا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5446, 'tanzil-uthmani-v1.1', 71, 27, 'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًا كَفَّارًا', '6d514ee366954d33931eb7941bedb72224c625e767e47b57869889ef71a65f09', 'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًا كَفَّارًا', '6d514ee366954d33931eb7941bedb72224c625e767e47b57869889ef71a65f09', '6d514ee366954d33931eb7941bedb72224c625e767e47b57869889ef71a65f09', NULL, 'انك ان تذرهم يضلوا عبادك ولا يلدوا الا فاجرا كفارا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5447, 'tanzil-uthmani-v1.1', 71, 28, 'رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارًۢا', '9c7f1f2d14d67fede275795d4ead89d6e37849ac1731278b98d4b186d4daa7a1', 'رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارًۢا', '9c7f1f2d14d67fede275795d4ead89d6e37849ac1731278b98d4b186d4daa7a1', '9c7f1f2d14d67fede275795d4ead89d6e37849ac1731278b98d4b186d4daa7a1', NULL, 'رب اغفر لي ولولدي ولمن دخل بيتي مؤمنا وللمؤمنين والمؤمنت ولا تزد الظلمين الا تبارا', 29, 57, 228, 1, 7, 571, false, NULL),
    (5448, 'tanzil-uthmani-v1.1', 72, 1, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا', '621532d8f67bdd48b2e385285bb1cf57805c815feae0d847478353720348079d', 'قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا', 'b21e6b514812fc05a4ff046865b0f7128d3763bf3338ae3cd07acbf0a6d4d7d2', 'b21e6b514812fc05a4ff046865b0f7128d3763bf3338ae3cd07acbf0a6d4d7d2', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 'قل اوحي الي انه استمع نفر من الجن فقالوا انا سمعنا قرءانا عجبا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5449, 'tanzil-uthmani-v1.1', 72, 2, 'يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًا', '626c22511edb1587b553a759a47ac2464d4f83ce3916928bf618bb1c59a46612', 'يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًا', '626c22511edb1587b553a759a47ac2464d4f83ce3916928bf618bb1c59a46612', '626c22511edb1587b553a759a47ac2464d4f83ce3916928bf618bb1c59a46612', NULL, 'يهدي الي الرشد فامنا به ولن نشرك بربنا احدا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5450, 'tanzil-uthmani-v1.1', 72, 3, 'وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةً وَلَا وَلَدًا', '4ccdc2c3dbfa1aa1a338018662776c8f8688681637247ecfa812f67f4837955c', 'وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةً وَلَا وَلَدًا', '4ccdc2c3dbfa1aa1a338018662776c8f8688681637247ecfa812f67f4837955c', '4ccdc2c3dbfa1aa1a338018662776c8f8688681637247ecfa812f67f4837955c', NULL, 'وانه تعلي جد ربنا ما اتخذ صحبه ولا ولدا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5451, 'tanzil-uthmani-v1.1', 72, 4, 'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا', 'efc1766de756075815ef08961f2f145df7cbf3faa01d14e304b27567ef4cd9df', 'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا', 'efc1766de756075815ef08961f2f145df7cbf3faa01d14e304b27567ef4cd9df', 'efc1766de756075815ef08961f2f145df7cbf3faa01d14e304b27567ef4cd9df', NULL, 'وانه كان يقول سفيهنا علي الله شططا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5452, 'tanzil-uthmani-v1.1', 72, 5, 'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا', 'fff37d2d934f5f89a416ae8e0471dc4675529dc82279962d0480686e706bc88c', 'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا', 'fff37d2d934f5f89a416ae8e0471dc4675529dc82279962d0480686e706bc88c', 'fff37d2d934f5f89a416ae8e0471dc4675529dc82279962d0480686e706bc88c', NULL, 'وانا ظننا ان لن تقول الانس والجن علي الله كذبا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5453, 'tanzil-uthmani-v1.1', 72, 6, 'وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا', '9aa8bee4925f7deac13eb8a9afb9108630018f9bacb42c47ceacc718ed3c9030', 'وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا', '9aa8bee4925f7deac13eb8a9afb9108630018f9bacb42c47ceacc718ed3c9030', '9aa8bee4925f7deac13eb8a9afb9108630018f9bacb42c47ceacc718ed3c9030', NULL, 'وانه كان رجال من الانس يعوذون برجال من الجن فزادوهم رهقا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5454, 'tanzil-uthmani-v1.1', 72, 7, 'وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا', '5b9c66dbc4c32bb5f6483e83858d6f15c0d2ac684317d481b9849c3abc555143', 'وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا', '5b9c66dbc4c32bb5f6483e83858d6f15c0d2ac684317d481b9849c3abc555143', '5b9c66dbc4c32bb5f6483e83858d6f15c0d2ac684317d481b9849c3abc555143', NULL, 'وانهم ظنوا كما ظننتم ان لن يبعث الله احدا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5455, 'tanzil-uthmani-v1.1', 72, 8, 'وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَٰهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا', '29917fbfdaf7792a9fac47ee9667741723d96309fa06b16c5c224b6685e24edf', 'وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَٰهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا', '29917fbfdaf7792a9fac47ee9667741723d96309fa06b16c5c224b6685e24edf', '29917fbfdaf7792a9fac47ee9667741723d96309fa06b16c5c224b6685e24edf', NULL, 'وانا لمسنا السماء فوجدنها ملئت حرسا شديدا وشهبا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5456, 'tanzil-uthmani-v1.1', 72, 9, 'وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَٰعِدَ لِلسَّمْعِ فَمَن يَسْتَمِعِ ٱلْـَٔانَ يَجِدْ لَهُۥ شِهَابًا رَّصَدًا', 'e289b2a0bfe2f50f7366d0c1046f4a63760ea359f2478db1cdf1fcaca98882eb', 'وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَٰعِدَ لِلسَّمْعِ فَمَن يَسْتَمِعِ ٱلْـَٔانَ يَجِدْ لَهُۥ شِهَابًا رَّصَدًا', 'e289b2a0bfe2f50f7366d0c1046f4a63760ea359f2478db1cdf1fcaca98882eb', 'e289b2a0bfe2f50f7366d0c1046f4a63760ea359f2478db1cdf1fcaca98882eb', NULL, 'وانا كنا نقعد منها مقعد للسمع فمن يستمع الان يجد له شهابا رصدا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5457, 'tanzil-uthmani-v1.1', 72, 10, 'وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا', '7c1df54be434416a4c1f47c393a8e06f9aec38bc64d771aa3be03e790f6d69e3', 'وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا', '7c1df54be434416a4c1f47c393a8e06f9aec38bc64d771aa3be03e790f6d69e3', '7c1df54be434416a4c1f47c393a8e06f9aec38bc64d771aa3be03e790f6d69e3', NULL, 'وانا لا ندري اشر اريد بمن في الارض ام اراد بهم ربهم رشدا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5458, 'tanzil-uthmani-v1.1', 72, 11, 'وَأَنَّا مِنَّا ٱلصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ كُنَّا طَرَآئِقَ قِدَدًا', 'f8fa69467606f1c37a4ceb3d8c7f747448d982db9baa05a51aa2be76c833243e', 'وَأَنَّا مِنَّا ٱلصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ كُنَّا طَرَآئِقَ قِدَدًا', 'f8fa69467606f1c37a4ceb3d8c7f747448d982db9baa05a51aa2be76c833243e', 'f8fa69467606f1c37a4ceb3d8c7f747448d982db9baa05a51aa2be76c833243e', NULL, 'وانا منا الصلحون ومنا دون ذلك كنا طرائق قددا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5459, 'tanzil-uthmani-v1.1', 72, 12, 'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًا', 'b304dbbf254bff2cd622e1da1c37e2191b000c0e10fae01f28f4146cefe578a7', 'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًا', 'b304dbbf254bff2cd622e1da1c37e2191b000c0e10fae01f28f4146cefe578a7', 'b304dbbf254bff2cd622e1da1c37e2191b000c0e10fae01f28f4146cefe578a7', NULL, 'وانا ظننا ان لن نعجز الله في الارض ولن نعجزه هربا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5460, 'tanzil-uthmani-v1.1', 72, 13, 'وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا', 'de84e92050294ca9c9ac38f870f7b3f3ff2c547a83c0b00a32c3148b6f92790d', 'وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا', 'de84e92050294ca9c9ac38f870f7b3f3ff2c547a83c0b00a32c3148b6f92790d', 'de84e92050294ca9c9ac38f870f7b3f3ff2c547a83c0b00a32c3148b6f92790d', NULL, 'وانا لما سمعنا الهدي ءامنا به فمن يؤمن بربه فلا يخاف بخسا ولا رهقا', 29, 58, 229, 1, 7, 572, false, NULL),
    (5461, 'tanzil-uthmani-v1.1', 72, 14, 'وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَٰسِطُونَ فَمَنْ أَسْلَمَ فَأُو۟لَٰٓئِكَ تَحَرَّوْا۟ رَشَدًا', '9d092923a143b3f71760e24cadb6d2fca62b2e87bcbe465d42d424fea0cf2e89', 'وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَٰسِطُونَ فَمَنْ أَسْلَمَ فَأُو۟لَٰٓئِكَ تَحَرَّوْا۟ رَشَدًا', '9d092923a143b3f71760e24cadb6d2fca62b2e87bcbe465d42d424fea0cf2e89', '9d092923a143b3f71760e24cadb6d2fca62b2e87bcbe465d42d424fea0cf2e89', NULL, 'وانا منا المسلمون ومنا القسطون فمن اسلم فاولئك تحروا رشدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5462, 'tanzil-uthmani-v1.1', 72, 15, 'وَأَمَّا ٱلْقَٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًا', 'd4e91b0da85c6726222b1716db1869127bbf32866f3aae8b6b7850b0c889c3df', 'وَأَمَّا ٱلْقَٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًا', 'd4e91b0da85c6726222b1716db1869127bbf32866f3aae8b6b7850b0c889c3df', 'd4e91b0da85c6726222b1716db1869127bbf32866f3aae8b6b7850b0c889c3df', NULL, 'واما القسطون فكانوا لجهنم حطبا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5463, 'tanzil-uthmani-v1.1', 72, 16, 'وَأَلَّوِ ٱسْتَقَٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَٰهُم مَّآءً غَدَقًا', 'c7be11a3ee23ff7557f7e29bf7f80d6c502a85c887fe70658cbd636bc549eeb7', 'وَأَلَّوِ ٱسْتَقَٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَٰهُم مَّآءً غَدَقًا', 'c7be11a3ee23ff7557f7e29bf7f80d6c502a85c887fe70658cbd636bc549eeb7', 'c7be11a3ee23ff7557f7e29bf7f80d6c502a85c887fe70658cbd636bc549eeb7', NULL, 'والو استقموا علي الطريقه لاسقينهم ماء غدقا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5464, 'tanzil-uthmani-v1.1', 72, 17, 'لِّنَفْتِنَهُمْ فِيهِ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًا صَعَدًا', 'e93a5ed1eda11a63f4f54c46f765e4606bb48e40064054ab0fb256f4f4fe9481', 'لِّنَفْتِنَهُمْ فِيهِ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًا صَعَدًا', 'e93a5ed1eda11a63f4f54c46f765e4606bb48e40064054ab0fb256f4f4fe9481', 'e93a5ed1eda11a63f4f54c46f765e4606bb48e40064054ab0fb256f4f4fe9481', NULL, 'لنفتنهم فيه ومن يعرض عن ذكر ربه يسلكه عذابا صعدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5465, 'tanzil-uthmani-v1.1', 72, 18, 'وَأَنَّ ٱلْمَسَٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًا', '8d5d511f163935a0e53955f649b876de3cd89215f146593bc9d7ad205d723572', 'وَأَنَّ ٱلْمَسَٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًا', '8d5d511f163935a0e53955f649b876de3cd89215f146593bc9d7ad205d723572', '8d5d511f163935a0e53955f649b876de3cd89215f146593bc9d7ad205d723572', NULL, 'وان المسجد لله فلا تدعوا مع الله احدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5466, 'tanzil-uthmani-v1.1', 72, 19, 'وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًا', 'fcda3e6b3f3ede68ac8302d79495bb51b2d6ffffb56fa5b1a5a246e57de09724', 'وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًا', 'fcda3e6b3f3ede68ac8302d79495bb51b2d6ffffb56fa5b1a5a246e57de09724', 'fcda3e6b3f3ede68ac8302d79495bb51b2d6ffffb56fa5b1a5a246e57de09724', NULL, 'وانه لما قام عبد الله يدعوه كادوا يكونون عليه لبدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5467, 'tanzil-uthmani-v1.1', 72, 20, 'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًا', '794a0023d1c52c0eea689ae695a0959c05046050a07c20687f310f5c9af80090', 'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًا', '794a0023d1c52c0eea689ae695a0959c05046050a07c20687f310f5c9af80090', '794a0023d1c52c0eea689ae695a0959c05046050a07c20687f310f5c9af80090', NULL, 'قل انما ادعوا ربي ولا اشرك به احدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5468, 'tanzil-uthmani-v1.1', 72, 21, 'قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا', 'e6502e8242e76ff813fa731498f2d3c0394343d1b22e7344cc813420cfe3f2f2', 'قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا', 'e6502e8242e76ff813fa731498f2d3c0394343d1b22e7344cc813420cfe3f2f2', 'e6502e8242e76ff813fa731498f2d3c0394343d1b22e7344cc813420cfe3f2f2', NULL, 'قل اني لا املك لكم ضرا ولا رشدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5469, 'tanzil-uthmani-v1.1', 72, 22, 'قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', '3d8c9b6d6156bb1ef28d18ae4ef833bca26ebfca08ec14c4f4220fa05e0e47f2', 'قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', '3d8c9b6d6156bb1ef28d18ae4ef833bca26ebfca08ec14c4f4220fa05e0e47f2', '3d8c9b6d6156bb1ef28d18ae4ef833bca26ebfca08ec14c4f4220fa05e0e47f2', NULL, 'قل اني لن يجيرني من الله احد ولن اجد من دونه ملتحدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5470, 'tanzil-uthmani-v1.1', 72, 23, 'إِلَّا بَلَٰغًا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا', '7b5d67731f88a484e50a0f250dc19044dfeae2012766c18a948b9d835fc5ae4c', 'إِلَّا بَلَٰغًا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا', '7b5d67731f88a484e50a0f250dc19044dfeae2012766c18a948b9d835fc5ae4c', '7b5d67731f88a484e50a0f250dc19044dfeae2012766c18a948b9d835fc5ae4c', NULL, 'الا بلغا من الله ورسلته ومن يعص الله ورسوله فان له نار جهنم خلدين فيها ابدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5471, 'tanzil-uthmani-v1.1', 72, 24, 'حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا', '28a054a4ae5f47f263668602bb59cc1cbd2926f008238f14ea7052bdc58fda87', 'حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا', '28a054a4ae5f47f263668602bb59cc1cbd2926f008238f14ea7052bdc58fda87', '28a054a4ae5f47f263668602bb59cc1cbd2926f008238f14ea7052bdc58fda87', NULL, 'حتي اذا راوا ما يوعدون فسيعلمون من اضعف ناصرا واقل عددا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5472, 'tanzil-uthmani-v1.1', 72, 25, 'قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا', 'b97747401b1142e4065104ea630105931c626747fe7eddd40313ffd588cd286b', 'قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا', 'b97747401b1142e4065104ea630105931c626747fe7eddd40313ffd588cd286b', 'b97747401b1142e4065104ea630105931c626747fe7eddd40313ffd588cd286b', NULL, 'قل ان ادري اقريب ما توعدون ام يجعل له ربي امدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5473, 'tanzil-uthmani-v1.1', 72, 26, 'عَٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا', '8dabeda9d4149b2d93e134fd04e8377b1786f437398fc64158c05718504b76d8', 'عَٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا', '8dabeda9d4149b2d93e134fd04e8377b1786f437398fc64158c05718504b76d8', '8dabeda9d4149b2d93e134fd04e8377b1786f437398fc64158c05718504b76d8', NULL, 'علم الغيب فلا يظهر علي غيبه احدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5474, 'tanzil-uthmani-v1.1', 72, 27, 'إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًا', 'b75ceb2603cdc8af93ac8089c4232cf619b1f84deaeff942965aaf11d87eec85', 'إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًا', 'b75ceb2603cdc8af93ac8089c4232cf619b1f84deaeff942965aaf11d87eec85', 'b75ceb2603cdc8af93ac8089c4232cf619b1f84deaeff942965aaf11d87eec85', NULL, 'الا من ارتضي من رسول فانه يسلك من بين يديه ومن خلفه رصدا', 29, 58, 229, 1, 7, 573, false, NULL),
    (5475, 'tanzil-uthmani-v1.1', 72, 28, 'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا', '6c923afac0b0f62f52dabdcca144ad7bffa34edea5714d7fb8dad6ac544ef125', 'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَٰلَٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا', '6c923afac0b0f62f52dabdcca144ad7bffa34edea5714d7fb8dad6ac544ef125', '6c923afac0b0f62f52dabdcca144ad7bffa34edea5714d7fb8dad6ac544ef125', NULL, 'ليعلم ان قد ابلغوا رسلت ربهم واحاط بما لديهم واحصي كل شيء عددا', 29, 58, 229, 1, 7, 573, false, NULL),
