    (5478, 'tanzil-uthmani-v1.1', 73, 3, 'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا', 'eff79792a5e29bc28cde63e23cc426dc714647bae8c5f5bc344edaf25a0717aa', 'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا', 'eff79792a5e29bc28cde63e23cc426dc714647bae8c5f5bc344edaf25a0717aa', 'eff79792a5e29bc28cde63e23cc426dc714647bae8c5f5bc344edaf25a0717aa', NULL, 'نصفه او انقص منه قليلا', 29, 58, 229, 1, 7, 574, false, NULL),
