    (5480, 'tanzil-uthmani-v1.1', 73, 5, 'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا', 'f95eab06acb8e1f1fc8dd088807bc0b47a654c3ee5b2db4366d7a26e4989cdb3', 'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا', 'f95eab06acb8e1f1fc8dd088807bc0b47a654c3ee5b2db4366d7a26e4989cdb3', 'f95eab06acb8e1f1fc8dd088807bc0b47a654c3ee5b2db4366d7a26e4989cdb3', NULL, 'انا سنلقي عليك قولا ثقيلا', 29, 58, 229, 1, 7, 574, false, NULL),
    (5481, 'tanzil-uthmani-v1.1', 73, 6, 'إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًٔا وَأَقْوَمُ قِيلًا', '54242a88f327914871d2d40fa61dffa1a1d13ac376d73395afbb669e960e7e7b', 'إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًٔا وَأَقْوَمُ قِيلًا', '54242a88f327914871d2d40fa61dffa1a1d13ac376d73395afbb669e960e7e7b', '54242a88f327914871d2d40fa61dffa1a1d13ac376d73395afbb669e960e7e7b', NULL, 'ان ناشئه اليل هي اشد وطا واقوم قيلا', 29, 58, 229, 1, 7, 574, false, NULL),
    (5482, 'tanzil-uthmani-v1.1', 73, 7, 'إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًا طَوِيلًا', '61e8a6818097edfb192aeddd5fcab8092478d73b1a0e2763f486161dcb0d64bf', 'إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًا طَوِيلًا', '61e8a6818097edfb192aeddd5fcab8092478d73b1a0e2763f486161dcb0d64bf', '61e8a6818097edfb192aeddd5fcab8092478d73b1a0e2763f486161dcb0d64bf', NULL, 'ان لك في النهار سبحا طويلا', 29, 58, 229, 1, 7, 574, false, NULL),
    (5483, 'tanzil-uthmani-v1.1', 73, 8, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا', 'b221d3662abaa50dc3f7f5618dff8d0ce2fbe64336ff598485d70cbd3f1b6307', 'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا', 'b221d3662abaa50dc3f7f5618dff8d0ce2fbe64336ff598485d70cbd3f1b6307', 'b221d3662abaa50dc3f7f5618dff8d0ce2fbe64336ff598485d70cbd3f1b6307', NULL, 'واذكر اسم ربك وتبتل اليه تبتيلا', 29, 58, 229, 1, 7, 574, false, NULL),
