    (5594, 'tanzil-uthmani-v1.1', 76, 3, 'إِنَّا هَدَيْنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا', '4be41acf36de668b7cb188ee151daa3e33769b396d0d5edef490a8aaf563b439', 'إِنَّا هَدَيْنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا', '4be41acf36de668b7cb188ee151daa3e33769b396d0d5edef490a8aaf563b439', '4be41acf36de668b7cb188ee151daa3e33769b396d0d5edef490a8aaf563b439', NULL, 'انا هدينه السبيل اما شاكرا واما كفورا', 29, 58, 231, 1, 7, 578, false, NULL),
    (5595, 'tanzil-uthmani-v1.1', 76, 4, 'إِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَلَٰسِلَا۟ وَأَغْلَٰلًا وَسَعِيرًا', 'ce6a8901db9231cd4b9b9c1454093b5ef2b9134a474c74926b224adda92b208e', 'إِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَلَٰسِلَا۟ وَأَغْلَٰلًا وَسَعِيرًا', 'ce6a8901db9231cd4b9b9c1454093b5ef2b9134a474c74926b224adda92b208e', 'ce6a8901db9231cd4b9b9c1454093b5ef2b9134a474c74926b224adda92b208e', NULL, 'انا اعتدنا للكفرين سلسلا واغللا وسعيرا', 29, 58, 231, 1, 7, 578, false, NULL),
    (5596, 'tanzil-uthmani-v1.1', 76, 5, 'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا', 'd8027dd9b7e59e4a622c1c0edf5c60c606c60f0d0997e9331fefac7181a4cff5', 'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا', 'd8027dd9b7e59e4a622c1c0edf5c60c606c60f0d0997e9331fefac7181a4cff5', 'd8027dd9b7e59e4a622c1c0edf5c60c606c60f0d0997e9331fefac7181a4cff5', NULL, 'ان الابرار يشربون من كاس كان مزاجها كافورا', 29, 58, 231, 1, 7, 578, false, NULL),
    (5597, 'tanzil-uthmani-v1.1', 76, 6, 'عَيْنًا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا', 'acc73243d5511041d7632509307f5fdf987133d6cb61f307e2fe6abdedf96786', 'عَيْنًا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا', 'acc73243d5511041d7632509307f5fdf987133d6cb61f307e2fe6abdedf96786', 'acc73243d5511041d7632509307f5fdf987133d6cb61f307e2fe6abdedf96786', NULL, 'عينا يشرب بها عباد الله يفجرونها تفجيرا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5598, 'tanzil-uthmani-v1.1', 76, 7, 'يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُۥ مُسْتَطِيرًا', 'c0933af8cdf185e725ce8d068bcd7bedce60bbb3ab56bed000cfdf32dec910b9', 'يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُۥ مُسْتَطِيرًا', 'c0933af8cdf185e725ce8d068bcd7bedce60bbb3ab56bed000cfdf32dec910b9', 'c0933af8cdf185e725ce8d068bcd7bedce60bbb3ab56bed000cfdf32dec910b9', NULL, 'يوفون بالنذر ويخافون يوما كان شره مستطيرا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5599, 'tanzil-uthmani-v1.1', 76, 8, 'وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا', '04772c58b1efb20bcfb170e14e8cdb3331646781dcf37b19964c579f3d51ef54', 'وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا', '04772c58b1efb20bcfb170e14e8cdb3331646781dcf37b19964c579f3d51ef54', '04772c58b1efb20bcfb170e14e8cdb3331646781dcf37b19964c579f3d51ef54', NULL, 'ويطعمون الطعام علي حبه مسكينا ويتيما واسيرا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5600, 'tanzil-uthmani-v1.1', 76, 9, 'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءً وَلَا شُكُورًا', '08327a57aa1cf54f7b7865d0cd163fcabd7fab7de53c9fe80e4a504c9673181f', 'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءً وَلَا شُكُورًا', '08327a57aa1cf54f7b7865d0cd163fcabd7fab7de53c9fe80e4a504c9673181f', '08327a57aa1cf54f7b7865d0cd163fcabd7fab7de53c9fe80e4a504c9673181f', NULL, 'انما نطعمكم لوجه الله لا نريد منكم جزاء ولا شكورا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5601, 'tanzil-uthmani-v1.1', 76, 10, 'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا', 'ecb6237a53f1807c05e4852697b1619d465e62ba62d44108d7b2157adb74a95d', 'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا', 'ecb6237a53f1807c05e4852697b1619d465e62ba62d44108d7b2157adb74a95d', 'ecb6237a53f1807c05e4852697b1619d465e62ba62d44108d7b2157adb74a95d', NULL, 'انا نخاف من ربنا يوما عبوسا قمطريرا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5602, 'tanzil-uthmani-v1.1', 76, 11, 'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةً وَسُرُورًا', '8331abbafeadb530090b7253b698f1204b0f311a894773d335280a9b730b5fe5', 'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةً وَسُرُورًا', '8331abbafeadb530090b7253b698f1204b0f311a894773d335280a9b730b5fe5', '8331abbafeadb530090b7253b698f1204b0f311a894773d335280a9b730b5fe5', NULL, 'فوقيهم الله شر ذلك اليوم ولقيهم نضره وسرورا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5603, 'tanzil-uthmani-v1.1', 76, 12, 'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةً وَحَرِيرًا', '5b926e218dea0bc572a70928e92a30e85019baa0c4030c7726a5a53cfee08ca2', 'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةً وَحَرِيرًا', '5b926e218dea0bc572a70928e92a30e85019baa0c4030c7726a5a53cfee08ca2', '5b926e218dea0bc572a70928e92a30e85019baa0c4030c7726a5a53cfee08ca2', NULL, 'وجزيهم بما صبروا جنه وحريرا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5604, 'tanzil-uthmani-v1.1', 76, 13, 'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا', '7135634955fd1a74e74e6b5d1f41bc3221f4f1ea24e31b268251e5744cd704a7', 'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا', '7135634955fd1a74e74e6b5d1f41bc3221f4f1ea24e31b268251e5744cd704a7', '7135634955fd1a74e74e6b5d1f41bc3221f4f1ea24e31b268251e5744cd704a7', NULL, 'متكين فيها علي الارائك لا يرون فيها شمسا ولا زمهريرا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5605, 'tanzil-uthmani-v1.1', 76, 14, 'وَدَانِيَةً عَلَيْهِمْ ظِلَٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا', '6f6e4d17df3d48b376b899394dedec0d89e865321d112212c11498dee5a02d9e', 'وَدَانِيَةً عَلَيْهِمْ ظِلَٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا', '6f6e4d17df3d48b376b899394dedec0d89e865321d112212c11498dee5a02d9e', '6f6e4d17df3d48b376b899394dedec0d89e865321d112212c11498dee5a02d9e', NULL, 'ودانيه عليهم ظللها وذللت قطوفها تذليلا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5606, 'tanzil-uthmani-v1.1', 76, 15, 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا۠', 'baf24d9e3eb6b54c88923ed1f93879131210197cab46e83ac2cff4e52a76d060', 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا۠', 'baf24d9e3eb6b54c88923ed1f93879131210197cab46e83ac2cff4e52a76d060', 'baf24d9e3eb6b54c88923ed1f93879131210197cab46e83ac2cff4e52a76d060', NULL, 'ويطاف عليهم بانيه من فضه واكواب كانت قواريرا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5607, 'tanzil-uthmani-v1.1', 76, 16, 'قَوَارِيرَا۟ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا', 'a858fab926d4d379772f7103328b480d7d1c4ee4c80ae8bdf2d669ecdf53cbac', 'قَوَارِيرَا۟ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا', 'a858fab926d4d379772f7103328b480d7d1c4ee4c80ae8bdf2d669ecdf53cbac', 'a858fab926d4d379772f7103328b480d7d1c4ee4c80ae8bdf2d669ecdf53cbac', NULL, 'قواريرا من فضه قدروها تقديرا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5608, 'tanzil-uthmani-v1.1', 76, 17, 'وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا', '0f99115b712b0f008505840c1ec326af94a8eb0b6b98ed9e8c03b0ff15942699', 'وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا', '0f99115b712b0f008505840c1ec326af94a8eb0b6b98ed9e8c03b0ff15942699', '0f99115b712b0f008505840c1ec326af94a8eb0b6b98ed9e8c03b0ff15942699', NULL, 'ويسقون فيها كاسا كان مزاجها زنجبيلا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5609, 'tanzil-uthmani-v1.1', 76, 18, 'عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا', '6cb18ed8002886d41c85efa67d535beb2effd229ba794ce3f58d4a55ecd63005', 'عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا', '6cb18ed8002886d41c85efa67d535beb2effd229ba794ce3f58d4a55ecd63005', '6cb18ed8002886d41c85efa67d535beb2effd229ba794ce3f58d4a55ecd63005', NULL, 'عينا فيها تسمي سلسبيلا', 29, 58, 231, 1, 7, 579, false, NULL),
    (5610, 'tanzil-uthmani-v1.1', 76, 19, 'وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا', '1a2dfde4ee9f15c9921e7eaa9e79b10c0c2b0cb933116ac16186ed76ba92d452', 'وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا', '1a2dfde4ee9f15c9921e7eaa9e79b10c0c2b0cb933116ac16186ed76ba92d452', '1a2dfde4ee9f15c9921e7eaa9e79b10c0c2b0cb933116ac16186ed76ba92d452', NULL, 'ويطوف عليهم ولدن مخلدون اذا رايتهم حسبتهم لؤلؤا منثورا', 29, 58, 232, 1, 7, 579, false, NULL),
    (5611, 'tanzil-uthmani-v1.1', 76, 20, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا', '4a14c16b4b2c8236541f0f4eb1e17cf7099751f724e2d1125ae023aeb94fd948', 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا', '4a14c16b4b2c8236541f0f4eb1e17cf7099751f724e2d1125ae023aeb94fd948', '4a14c16b4b2c8236541f0f4eb1e17cf7099751f724e2d1125ae023aeb94fd948', NULL, 'واذا رايت ثم رايت نعيما وملكا كبيرا', 29, 58, 232, 1, 7, 579, false, NULL),
    (5612, 'tanzil-uthmani-v1.1', 76, 21, 'عَٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًا طَهُورًا', '4329384770416a5bc8a6a0be3948087a7ce44ba7ae3940637d605a6eb4c7ed46', 'عَٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًا طَهُورًا', '4329384770416a5bc8a6a0be3948087a7ce44ba7ae3940637d605a6eb4c7ed46', '4329384770416a5bc8a6a0be3948087a7ce44ba7ae3940637d605a6eb4c7ed46', NULL, 'عليهم ثياب سندس خضر واستبرق وحلوا اساور من فضه وسقيهم ربهم شرابا طهورا', 29, 58, 232, 1, 7, 579, false, NULL),
    (5613, 'tanzil-uthmani-v1.1', 76, 22, 'إِنَّ هَٰذَا كَانَ لَكُمْ جَزَآءً وَكَانَ سَعْيُكُم مَّشْكُورًا', 'a8252790a924372e3c67a1325d533f2d06ff494dac36f26313e3db16cbe69316', 'إِنَّ هَٰذَا كَانَ لَكُمْ جَزَآءً وَكَانَ سَعْيُكُم مَّشْكُورًا', 'a8252790a924372e3c67a1325d533f2d06ff494dac36f26313e3db16cbe69316', 'a8252790a924372e3c67a1325d533f2d06ff494dac36f26313e3db16cbe69316', NULL, 'ان هذا كان لكم جزاء وكان سعيكم مشكورا', 29, 58, 232, 1, 7, 579, false, NULL),
