    (6014, 'tanzil-uthmani-v1.1', 89, 21, 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّا دَكًّا', '971d6d59089c217b57da99ffde8973f94a830c8801ffcc7005ee57e5a8766b0b', 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّا دَكًّا', '971d6d59089c217b57da99ffde8973f94a830c8801ffcc7005ee57e5a8766b0b', '971d6d59089c217b57da99ffde8973f94a830c8801ffcc7005ee57e5a8766b0b', NULL, 'كلا اذا دكت الارض دكا دكا', 30, 60, 237, 1, 7, 593, false, NULL),
